ns.descTemplates = {
    { en = "Shields an ally for $d, absorbing $s1 damage.", ua = "Захищає союзника щитом на $d, поглинаючи $s1 шкоди." },
    { en = "Turns you invisible over $66d, reducing threat each second. While invisible, you are untargetable by enemies. Lasts $32612d. Taking any action cancels the effect.$?a382293[\n\n\n\nIncreases your movement speed by $382293s1% for $337278d.][]", ua = "Робить вас невидимим протягом $66d, щосекунди зменшуючи загрозу. Поки ви невидимі, вороги не можуть обрати вас за ціль. Триває $32612d. Будь-яка дія скасовує ефект.$?a382293[\n\n\n\nЗбільшує вашу швидкість пересування на $382293s1% протягом $337278d.][]" },
    { en = "Charge to an enemy, dealing $126664s2 Physical damage, rooting it for $105771d$?s103828[, and stunning it for $7922d][].\n\n\n\n|cFFFFFFFFGenerates $/10;s2 Rage.|r", ua = "Кидаєтеся на ворога, завдаючи $126664s2 фізичної шкоди та прикорінюючи його на $105771d$?s103828[ і приголомшуючи на $7922d][].\n\n\n\n|cFFFFFFFFСтворює $/10;s2 люті.|r" },
    { en = "Launches a bolt of frost at the enemy, causing $228597s1 Frost damage and slowing movement speed by $205708s1% for $205708d.$?a1246769[\n\n\n\n|CFFffffffApplies $1246769s1 $lstack:stacks; of Freezing.|R][]", ua = "Запускає у ворога крижану стрілу, завдаючи $228597s1 крижаної шкоди й уповільнюючи швидкість пересування на $205708s1% протягом $205708d.$?a1246769[\n\n\n\n|CFFffffffНакладає $1246769s1 $lстак:стаки; «Заморожування».|R][]" },
    { en = "Transforms the enemy into a sheep, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage may cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на вівцю, що безпорадно блукає протягом $d. Поки діє ефект, жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода може скасувати ефект. Обмеження: 1.\n\n\n\nДіє лише на звірів, гуманоїдів і дрібних істот.$?s56382[ Коли діє на дрібних істот, може вражати кілька цілей і триває 1 день.][]" },
    { en = "Targets in a cone in front of you take $s1 Frost damage and $?a386763[are frozen in place for $386770d][have movement slowed by $205708s1% for $205708d].", ua = "Цілі в конусі перед вами зазнають $s1 шкоди Морозу та $?a386763[заморожуються на місці на $386770d][їхній рух сповільнюється на $205708s1% на $205708d]." },
    { en = "Blasts enemies within $A2 yds of you for $s2 Frost damage and freezes them in place for $d. Damage may interrupt the freeze effect.", ua = "Вражає ворогів у радіусі $A2 м від тебе, завдаючи $s2 шкоди від морозу, і заморожує їх на місці на $d. Шкода може перервати ефект заморозки." },
    { en = "Summons an Eye of Kilrogg and binds your vision to it. The eye is stealthed and moves quickly but is very fragile.", ua = "Прикликає Око Кілроґґа і прив'язує до нього твій зір. Око невидиме й рухається швидко, але дуже крихке." },
    { en = "Slows a group member's falling speed for $d.", ua = "Сповільнює падіння члена групи на $d." },
    { en = "Heals your pet for $<total>% of its total health over $d.$?s343242[\n\n\n\nEach time Mend Pet heals your pet, it has a $343242s2% chance to dispel a harmful magic effect from your pet.][]", ua = "Зцілює вашого улюбленця на $<total>% від його загального здоров'я протягом $d.$?s343242[\n\n\n\nЩоразу, коли Лікування улюбленця зцілює вашого улюбленця, є $343242s2% шанс розвіяти з нього шкідливий магічний ефект.][]" },
    { en = "Corrupts the target, causing $s3 Shadow damage and $?a196103[$146739s1 Shadow damage every $146739t1 sec.][an additional $146739o1 Shadow damage over $146739d.]", ua = "Розтліває ціль, завдаючи $s3 шкоди тінню та $?a196103[$146739s1 шкоди тінню кожні $146739t1 сек.][додатково $146739o1 шкоди тінню протягом $146739d.]" },
    { en = "Roots the target in place for $d. Damage may cancel the effect.$?s33891[\n\n\n\n|C0033AA11Tree of Life: Instant cast.|R][]", ua = "Сковує ціль на місці на $d. Шкода може скасувати ефект.$?s33891[\n\n\n\n|C0033AA11Дерево життя: миттєве творення.|R][]" },
    { en = "Taunts the target to attack you, and increases the threat you generate against them by $s2% for $d.", ua = "Провокує ціль атакувати тебе та на $d збільшує загрозу, яку ти створюєш проти неї, на $s2%." },
    { en = "Finishing move that stuns the target$?a426588[ and creates shadow clones to stun all other nearby enemies][]. Lasts longer per combo point, up to $s2 sec:\n\n   1 point : ${$m2-4} $Lsecond:seconds;\n\n   2 points: ${$s2-3} seconds\n\n   3 points: ${$s2-2} seconds\n\n   4 points: ${$s2-1} seconds\n\n   5 points: $s2 seconds", ua = "Завершальний прийом, що приголомшує ціль$?a426588[ і створює тіньових двійників, аби приголомшити всіх інших ворогів поблизу][]. Триває довше за кожне очко комбо, до $s2 сек.:\n\n   1 очко : ${$m2-4} $Lсекунда:секунд;\n\n   2 очки: ${$s2-3} секунди\n\n   3 очки: ${$s2-2} секунди\n\n   4 очки: ${$s2-1} секунди\n\n   5 очок: $s2 секунд" },
    { en = "Soothes enemies in the target area, reducing the range at which they will detect you by $s1 yards. Only affects Humanoid and Dragonkin targets. Does not cause threat. Lasts $d.", ua = "Заспокоює ворогів у вказаній області, зменшуючи відстань, з якої вони тебе помічають, на $s1 м. Діє лише на гуманоїдів і драконідів. Не створює загрози. Триває $d." },
    { en = "Summons and dismisses a rideable Brown Horse.", ua = "Прикликає та відкликає їздового гнідого коня." },
    { en = "Summons and dismisses a rideable gray wolf.", ua = "Прикликає та відкликає їздового сірого вовка." },
    { en = "Party and raid members within $a1 yds are bolstered by their devotion, reducing damage taken by $s1%.", ua = "Члени групи й рейду в радіусі $a1 м зміцнені своєю відданістю, що знижує отримувану шкоду на $s1%." },
    { en = "Summons and dismisses a rideable White Stallion.", ua = "Прикликає та відкликає їздового білого жеребця." },
