    { en = "Creates a portal, teleporting group members that use it to Ironforge.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Айронфорджа." },
    { en = "Creates a portal, teleporting group members that use it to Orgrimmar.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Оґриммара." },
    { en = "Creates a portal, teleporting group members that use it to Undercity.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Підмістя." },
    { en = "Creates a portal, teleporting group members that use it to Darnassus.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Дарнасуса." },
    { en = "Creates a portal, teleporting group members that use it to Thunder Bluff.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Громового Стрімчака." },
    { en = "Summons a Warhorse, which serves as a mount.", ua = "Викликає бойового коня, що служить їздовою твариною." },
