    { en = "Summons a Great Sunwalker Kodo, which serves as a mount.", ua = "Викликає великого кодо сонцеходів, що служить їздовою твариною." },
    { en = "Right Click to summon and dismiss your pug.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свого мопса." },
    { en = "Summons and dismisses a rideable X-45 Heartbreaker prototype rocket. This mount changes depending on your Riding skill and location.", ua = "Прикликає або відпускає верхову ракету-прототип «Серцеїд X-45». Ця їздова тварина змінюється залежно від вашої вправності в їзді та місцеперебування." },
    { en = "Summons and dismisses a rideable Wrathful Gladiator's Frost Wyrm mount.  This is a flying mount.", ua = "Прикликає або відпускає верхового крижаного вирма Розлюченого Гладіатора. Це літальна їздова тварина." },
    { en = "Right Click to summon and dismiss your toxic wasteling. Do not feed toxic wasteling. Do not allow toxic wasteling to approach small animals. Do not touch, sniff, or even look at toxic wasteling for extended periods of time.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свого токсичного покидька. Не годуйте токсичного покидька. Не підпускайте токсичного покидька до дрібних тварин. Не торкайтеся, не нюхайте й навіть не дивіться на токсичного покидька надто довго." },
    { en = "Summons and dismisses the flying undead horse Invincible.  This mount changes depending on your Riding skill and location.", ua = "Прикликає або відпускає летючого мертвого коня Незламного. Ця їздова тварина змінюється залежно від вашої вправності в їзді та місцеперебування." },
    { en = "Summons and dismisses a rideable Icebound Frostbrood Vanquisher.  This is a flying mount.", ua = "Прикликає або відпускає верхового зашкарублого в кризі переможця Морозного Виводку. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Bloodbathed Frostbrood Vanquisher.  This is a flying mount.", ua = "Прикликає або відпускає верхового скривавленого переможця Морозного Виводку. Це літальна їздова тварина." },
    { en = "Summons and dismisses your rideable Crimson Deathcharger.", ua = "Прикликає або відпускає вашого верхового багряного бойового коня смерті." },
    { en = "Summons an Exarch's Elekk, which serves as a mount.", ua = "Викликає елекка екзарха, що служить їздовою твариною." },
    { en = "Summons an Great Exarch's Elekk, which serves as a mount.", ua = "Викликає великого елекка екзарха, що служить їздовою твариною." },
    { en = "An instant weapon strike that causes $s1 Physical damage.", ua = "Миттєвий удар зброєю, що завдає $s1 фізичної шкоди." },
    { en = "Summons and dismisses a rideable Blazing Hippogryph.  The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає або відпускає верхового полум'яного гіпогрифа. Можливості цієї їздової тварини залежать від вашої вправності в їзді та місцеперебування." },
    { en = "Summons and dismisses a rideable Wooly White Rhino.", ua = "Прикликає або відпускає верхового білого волохатого носорога." },
    { en = "Right Click to summon and dismiss your Frigid Frostling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свого крижаного морознюка." },
    { en = "Summons and dismisses your Vashj'ir Seahorse.  Can only be used in Vashj'ir.", ua = "Прикликає або відпускає вашого морського коника з Вашж'іру. Можна використовувати лише у Вашж'ірі." },
    { en = "Summons and dismisses a Frosty Flying Carpet.  This mount changes depending on your Riding skill and location.", ua = "Прикликає або відпускає морозний літальний килим. Ця їздова тварина змінюється залежно від вашої вправності в їзді та місцеперебування." },
    { en = "Summons or dismisses a Celestial Dragon.", ua = "Прикликає або відпускає небесного дракона." },
    { en = "Summons and dismisses a Celestial Steed.  The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає або відпускає небесного скакуна. Можливості цієї їздової тварини залежать від вашої вправності в їзді та місцеперебування." },
    { en = "Right Click to set down or pick up your Lil' XT action figure.", ua = "Клацніть правою кнопкою, щоб поставити чи підняти свою фігурку Малого XT." },
    { en = "Summons a two-passenger X-53 Touring Rocket.  This mount changes depending on your Riding skill and location.", ua = "Прикликає двомісну прогулянкову ракету X-53. Ця їздова тварина змінюється залежно від вашої вправності в їзді та місцеперебування." },
    { en = "Causes the earth within $a1 yards of the target location to tremble and break, dealing ${$s4*$77478s1} Nature damage over $d and has a $77478s2% chance to knock the enemy down. Multiple uses of Earthquake may overlap.\n\n\n\n|cFFFFFFFFThis spell is cast at a selected location.|r", ua = "Змушує землю в межах $a1 ярдів від обраного місця тремтіти й тріскатися, завдаючи ${$s4*$77478s1} Природної шкоди протягом $d, і має $77478s2% шанс збити ворога з ніг. Кілька застосувань «Землетрусу» можуть накладатися.\n\n\n\n|cFFFFFFFFЦе закляття твориться в обраному місці.|r" },
    { en = "Heals every $t1 sec for $d.", ua = "Зцілює кожні $t1 сек. протягом $d." },
    { en = "Strikes all nearby enemies, dealing $s1 $?a429523[Arcane][Bleed] damage and an additional $192090o1 $?a429523[Arcane][Bleed] damage over $192090d. When applied from Bear Form, this effect can stack up to $192090u times.\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Rage.|r", ua = "Б'є всіх ворогів поблизу, завдаючи $s1 $?a429523[арканної][кровотечної] шкоди та ще $192090o1 $?a429523[арканної][кровотечної] шкоди впродовж $192090d. Коли застосовано з ведмежої подоби, цей ефект накладається до $192090u разів.\n\n\n\n|cFFFFFFFFГенерує ${$m2/10} люті.|r" },
    { en = "Right Click to summon and dismiss Mini Thor.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Міні-Тора." },
    { en = "Right Click to summon and dismiss a Blue Mini Jouster.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити синього міні-турнірника." },
    { en = "Right Click to summon and dismiss a Gold Mini Jouster.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити золотого міні-турнірника." },
    { en = "Warp the flow of time, increasing haste by $s1% $?a320919[and time rate by $s4% ][]for all party and raid members for $d.\n\n\n\nAllies will be unable to benefit from Bloodlust, Heroism, or Time Warp again for $57724d.$?a320920[\n\n\n\nWhen the effect ends, all affected players are frozen in time for $356346d.][]", ua = "Викривляє плин часу, збільшуючи поспіх на $s1% $?a320919[і швидкість часу на $s4% ][]для всіх членів групи та рейду протягом $d.\n\n\n\nСоюзники не зможуть знову скористатися Жагою крові, Героїзмом чи Викривленням часу протягом $57724d.$?a320920[\n\n\n\nКоли ефект завершується, усі вражені гравці завмирають у часі на $356346d.][]" },
    { en = "Restores $s1 health to three injured allies within $A1 yards of the initial target every $81262t1 sec for $81262d.", ua = "Відновлює $s1 здоров'я трьом пораненим союзникам у межах $A1 м від початкової цілі кожні $81262t1 сек. протягом $81262d." },
    { en = "Deals $s1 Holy damage every $26573t1 sec to enemies within $A1 yards.", ua = "Завдає $s1 священної шкоди кожні $26573t1 сек. ворогам у радіусі $A1 м." },
    { en = "Right Click to summon and dismiss your Personal World Destroyer.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свого особистого руйнівника світів." },
    { en = "Right Click to summon and dismiss your De-Weaponized Mechanical Companion.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свого роззброєного механічного супутника." },
    { en = "Summons your second pet to you.", ua = "Викликає до тебе твого другого улюбленця." },
    { en = "Summons your third pet to you.", ua = "Викликає до тебе твого третього улюбленця." },
    { en = "Summons your fourth pet to you.", ua = "Викликає до тебе твого четвертого улюбленця." },
    { en = "Summons your fifth pet to you.", ua = "Викликає до тебе твого п'ятого улюбленця." },
    { en = "Right Click to summon and dismiss your crawling claw.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити свою повзучу лапу." },
    { en = "Right Click to summon and dismiss Pebble.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Камінчика." },
    { en = "Summons and dismisses a rideable Fossilized Raptor.", ua = "Прикликає або відпускає верхового скам'янілого раптора." },
    { en = "A mighty blow with both weapons that deals a total of $<damage> Physical damage.$?s383854[\n\n\n\nRaging Blow has a $s1% chance to instantly reset its own cooldown.][]\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Rage.|r", ua = "Потужний удар обома зброями, що завдає загалом $<damage> фізичної шкоди.$?s383854[\n\n\n\nЛютий удар має $s1% шанс миттєво скинути власне перезарядження.][]\n\n\n\n|cFFFFFFFFСтворює ${$m2/10} люті.|r" },
    { en = "Calls down the Light to heal a friendly target for $130551s1$?a378405[ and an additional $378405s1% over $378412d][].$?a315921|?a315924[\n\n\n\n|cFFFFFFFFProtection: |r][]$?a315921[If cast on yourself, healing increased by up to $315921s1% based on your missing health and $315921s2% of the mana cost is refunded.][]$?a315921&?a315924[\n\n\n\n][]$?a315924[If cast on another target, healing increased by up to $315924s1%.][]", ua = "Прикликає Світло, щоб зцілити дружню ціль на $130551s1$?a378405[ і ще на $378405s1% протягом $378412d][].$?a315921|?a315924[\n\n\n\n|cFFFFFFFFЗахист: |r][]$?a315921[Якщо застосовано на себе, зцілення збільшено до $315921s1% залежно від нестачі вашого здоров'я, а $315921s2% витрат мани повертається.][]$?a315921&?a315924[\n\n\n\n][]$?a315924[Якщо застосовано на іншу ціль, зцілення збільшено до $315924s1%.][]" },
    { en = "Sends a shadowy bolt at the enemy, causing $s1 Shadow damage. Deals $s2% additional damage to targets below 20% health.", ua = "Запускає у ворога тіньовий снаряд, завдаючи $s1 шкоди Тінню. Завдає на $s2% більше шкоди цілям зі здоров'ям нижче 20%." },
    { en = "Increases your Intellect by $s1%.", ua = "Збільшує твій інтелект на $s1%." },
    { en = "Increases your Agility by $s1% while wearing only Leather armor.", ua = "Збільшує твою спритність на $s1%, поки ти носиш лише шкіряну броню." },
    { en = "Your main-hand attacks have a $h% chance to trigger an attack with your off-hand that deals $86392s1 Physical damage.", ua = "Атаки основною рукою мають $h% шанс викликати удар другою рукою, що завдає $86392s1 фізичної шкоди." },
    { en = "Increases your Agility by $s1% while wearing only Mail armor.", ua = "Збільшує твою спритність на $s1%, якщо носиш лише кольчужну броню." },
    { en = "Heals the target of your heals for 30% of the amount healed.", ua = "Зцілює ціль твоїх зцілень додатково на 30% від зціленого обсягу." },
    { en = "Unleash the fury of ancient kings, causing $s1 Holy damage per application of Ancient Power, divided evenly among all targets within $a1 yards.", ua = "Вивільняє лють давніх королів, завдаючи $s1 шкоди Світлом за кожне накладання «Давньої сили», порівну розділеної між усіма цілями в межах $a1 м." },
    { en = "Summons and dismisses a rideable Goblin Trike.", ua = "Прикликає або відпускає верховий ґоблінський трицикл." },
    { en = "Summons and dismisses a Goblin Turbo-Trike.", ua = "Прикликає або відпускає ґоблінський турбо-трицикл." },
    { en = "Right Click to summon and dismiss Lil' Deathwing.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Малого Дезвінга." },
    { en = "Eat the egg", ua = "З'їсти яйце" },
    { en = "Starts combat by attacking a target with a melee weapon.", ua = "Починає бій, атакуючи ціль зброєю ближнього бою." },
    { en = "Summons and dismisses a rideable Volcanic Stone Drake.  This is a flying mount.", ua = "Прикликає або відпускає верхового вулканічного кам'яного дрейка. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Drake of the East Wind.  This is a flying mount.", ua = "Прикликає або відпускає верхового дрейка Східного Вітру. Це літальна їздова тварина." },
    { en = "Teleports you to Tol Barad.", ua = "Телепортує тебе до Тол Барада." },
    { en = "Creates a portal, teleporting group members that use it to Tol Barad.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Тол Барада." },
    { en = "Summons and dismisses a rideable Phosphorescent Stone Drake.  This is a flying mount.", ua = "Прикликає або відпускає верхового фосфоресцентного кам'яного дрейка. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Drake of the West Wind.  This is a flying mount.", ua = "Прикликає або відпускає верхового дрейка Західного Вітру. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Drake of the North Wind.  This is a flying mount.", ua = "Прикликає або відпускає верхового дрейка Північного Вітру. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Drake of the South Wind.  This is a flying mount.", ua = "Прикликає або відпускає верхового дрейка Південного Вітру. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Vitreous Stone Drake.  This is a flying mount.", ua = "Прикликає або відпускає верхового склистого кам'яного дрейка. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Brown Riding Camel.", ua = "Прикликає або відпускає верхового бурого їздового верблюда." },
    { en = "Summons and dismisses a rideable Tan Riding Camel.", ua = "Прикликає або відпускає верхового світло-бурого їздового верблюда." },
    { en = "Summons and dismisses a rideable Grey Riding Camel.", ua = "Прикликає або відпускає верхового сірого їздового верблюда." },
    { en = "Summons and dismisses a rideable Dark Phoenix.  This is a flying mount.", ua = "Прикликає або відпускає верхового темного фенікса. Це літальна їздова тварина." },
    { en = "Right Click to summon and dismiss your baby dark phoenix.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити своє темне феніксеня." },
    { en = "Right Click to summon and dismiss a Rustberg Seagull.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити мартина з Растберга." },
    { en = "Rides and parks a Mini Goblin Hotrod.", ua = "Сідає за кермо ґоблінського міні-боліда або паркує його." },
    { en = "Right Click to summon and dismiss your Armadillo Pup.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє броненосеня." },
    { en = "The Felguard recklessly swings its weapon, striking all nearby enemies within $89753A1 yards for $<damage> Physical damage every $t1 sec for $89751d. The Felguard cannot take any other action during Felstorm. Deals reduced damage beyond $89753s3 targets.", ua = "Вартовий Скверни нестримно махає зброєю, завдаючи всім ворогам поблизу в межах $89753A1 ярдів $<damage> фізичної шкоди кожні $t1 с протягом $89751d. Під час Бурі Скверни вартовий Скверни не може виконувати жодних інших дій. Завдає зменшеної шкоди понад $89753s3 цілей." },
    { en = "The $?s108499[Wrathguard][Felguard] hurls its weapon, stunning and interrupting the target for $89766d.", ua = "$?s108499[Вартовий Гніву][Вартовий Скверни] жбурляє свою зброю, оглушуючи та перериваючи ціль на $89766d." },
    { en = "Escapes to the Master, removing all stuns and roots from himself.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nCast when the Imp is stunned or rooted.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Тікає до володаря, знімаючи із себе всі оглушення та знерухомлення.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗастосовується, коли біса оглушено або знерухомлено.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "Burns harmful spells, removing $89808s1 harmful Magic effect from an ally.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nCast upon master when $ghe:she; is unable to cast spells due to a Magic effect.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Випалює шкідливі закляття, знімаючи із союзника $89808s1 шкідливий магічний ефект.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗастосовується на володаря, коли $ghe:she; не може творити закляття через магічний ефект.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "Right Click to summon and dismiss your Rumbling Rockling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого гуркітливого каменюку." },
    { en = "Right Click to summon and dismiss your Swirling Stormling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого вихрового штормовика." },
    { en = "Right Click to summon and dismiss your Whirling Waveling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого кружного хвилевика." },
    { en = "The Beetle hardens up, reducing damage taken by $s1% for $d.", ua = "Жук твердне, зменшуючи отримувану шкоду на $s1% протягом $d." },
    { en = "Puts your Fox into a playful state.", ua = "Уводить вашого лиса в грайливий настрій." },
    { en = "The Spirit Beast heals the current friendly target for ${$m1+(($RAP*0.6)*1)} plus an additional ${$m2+(($RAP*0.6)*.66)*($d/$t2)} over $d.", ua = "Дух-звір зцілює поточну дружню ціль на ${$m1+(($RAP*0.6)*1)} та додатково на ${$m2+(($RAP*0.6)*.66)*($d/$t2)} протягом $d." },
    { en = "Right Click to summon and dismiss your Clockwork Gnome.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого механічного гнома." },
    { en = "Summons and dismisses the Golden King.", ua = "Прикликає та відкликає Золотого Короля." },
    { en = "Right Click to summon and dismiss your Fox Kit.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє лисеня." },
    { en = "Right Click to summon and dismiss the Tiny Shale Spider.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати крихітного сланцевого павука." },
    { en = "Claw the enemy, dealing $<damage> Physical damage.", ua = "Шкрябає ворога кігтями, завдаючи $<damage> фізичної шкоди." },
    { en = "Rakes an enemy with deformed claws, dealing $<sweepingclaw> Shadow damage to the target and $<sweepingclawsecond> Shadow damage to nearby enemies.", ua = "Роздирає ворога потворними кігтями, завдаючи цілі $<sweepingclaw> тіньової шкоди та $<sweepingclawsecond> тіньової шкоди ворогам поблизу." },
    { en = "Strike an enemy with a smashing attack, dealing $s2 Physical damage and stunning for $d.", ua = "Завдає ворогові нищівного удару, наносячи $s2 фізичної шкоди та оглушуючи на $d." },
    { en = "Bite and tear at a target's limbs, stunning it for $d and dealing damage.", ua = "Кусає та роздирає кінцівки цілі, оглушуючи її на $d і завдаючи шкоди." },
    { en = "Charge an enemy, interrupting spellcasting and immobilizing them for $91807d.", ua = "Налітає на ворога, перериваючи творення закляття та знерухомлюючи його на $91807d." },
    { en = "Leap behind an enemy target.", ua = "Стрибає за спину ворожої цілі." },
    { en = "Unleash a fortifying roar, reducing all damage taken by $91837s1% for $91837d.", ua = "Випускає зміцнювальний рик, зменшуючи всю отримувану шкоду на $91837s1% протягом $91837d." },
    { en = "Go into a defensive crouch, reducing all damage taken by $91838s1% but preventing other actions for $91838d.", ua = "Припадає до землі в захисній стійці, зменшуючи всю отримувану шкоду на $91838s1%, але унеможливлюючи інші дії протягом $91838d." },
    { en = "Summons and dismisses a rideable Ultramarine Qiraji Battle Tank.", ua = "Прикликає та відкликає їздовий ультрамариновий бойовий танк кіраджі." },
    { en = "Summons and dismisses a rideable Spectral Steed.", ua = "Прикликає та відкликає їздового примарного скакуна." },
    { en = "Summons and dismisses a rideable Spectral Wolf.", ua = "Прикликає та відкликає їздового примарного вовка." },
    { en = "The Chimera channels a frozen breath attack, causing $<damage> Froststorm damage every $92380T1 sec for $92380d to all enemies within $95725a1 yards.", ua = "Химера зосереджує крижаний подих, завдаючи $<damage> шкоди Морозною Бурею кожні $92380T1 с протягом $92380d усім ворогам у межах $95725a1 ярдів." },
    { en = "Right Click to summon your guild's Page for up to $d.", ua = "Клацніть правою кнопкою, щоб прикликати пажа вашої гільдії на час до $d." },
    { en = "Right Click to summon your guild's Herald for up to $d.", ua = "Клацніть правою кнопкою, щоб прикликати герольда вашої гільдії на час до $d." },
    { en = "Allows you to give commands to control your pet.", ua = "Дозволяє віддавати команди, щоб керувати своїм улюбленцем." },
    { en = "Transforms you into a Sandstone Drake, allowing you to fly very fast and carry an ally on your back.  This is a flying mount.", ua = "Перетворює вас на пісковикового дрейка, дозволяючи дуже швидко літати й нести союзника на спині. Це летюча їздова тварина." },
    { en = "The Worm burrows into the earth and shakes the ground above, dealing $<damage> Nature damage over $d.", ua = "Черв зариваєтся в землю й трясе ґрунт над собою, завдаючи $<damage> шкоди Природою протягом $d." },
    { en = "Right Click to set down or pick up your Landro's Lil' XT action figure.", ua = "Клацніть правою кнопкою, щоб поставити чи підняти свою фігурку \"Малий XT Ландро\"." },
    { en = "Summons and dismisses a rideable Mottled Drake.  This is a flying mount.", ua = "Прикликає та відкликає їздового плямистого дрейка. Це летюча їздова тварина." },
    { en = "Summons and dismisses the Kor'kron Annihilator.", ua = "Прикликає та відкликає Нищителя Кор'крон." },
    { en = "Right Click to summon and dismiss Mr. Grubbs.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Пана Хробачка." },
    { en = "Right Click to summon and dismiss the Tiny Flamefly.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати крихітну вогнемушку." },
    { en = "Right Click to summon and dismiss Bubbles.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Бульбашку." },
    { en = "Right Click to summon and dismiss Scooter the Snail.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати равлика Скутера." },
    { en = "Right Click to summon and dismiss Lizzy.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Ліззі." },
