    { en = "Summons and dismisses a rideable White Riding Camel.", ua = "Прикликає верхового Білого Їздового Верблюда або відкликає його." },
    { en = "Summons and dismisses a rideable Corrupted Hippogryph. This mount changes depending on your Riding skill and location.", ua = "Прикликає верхового Зіпсованого Гіпогрифа або відкликає його. Ця їздова тварина змінюється залежно від твого вміння верхової їзди та місцевості." },
    { en = "Allows the Druid to vanish from sight, entering an improved stealth mode.  Lasts until cancelled.", ua = "Дозволяє друїду зникнути з очей, перейшовши в покращений режим непомітності. Триває до скасування." },
    { en = "Conjures a vortex of wind at the destination location that pulls all enemies within $102793A1 yards toward it.", ua = "Створює вихор вітру в указаному місці, що затягує до себе всіх ворогів у радіусі $102793A1 м." },
    { en = "Right Click to summon and dismiss your Darkmoon Turtle.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою Черепаху Темного Місяця." },
    { en = "Right click to summon and dismiss your Darkmoon balloon.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою кулю Темного Місяця." },
    { en = "Summons and dismisses a rideable Darkmoon Dancing Bear.", ua = "Прикликає верхового Танцівного Ведмедя Темного Місяця або відкликає його." },
    { en = "Right Click to summon and dismiss your coal elemental.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого вугільного елементаля." },
    { en = "Summons and dismisses a rideable Mountain Horse.", ua = "Прикликає верхового Гірського Коня або відкликає його." },
    { en = "Summons and dismisses a rideable Swift Mountain Horse.", ua = "Прикликає верхового Швидкого Гірського Коня або відкликає його." },
    { en = "Right click to summon and dismiss your Darkmoon tonk.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свій танк Темного Місяця." },
    { en = "Right click to summon and dismiss your Darkmoon zeppelin.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свій дирижабль Темного Місяця." },
    { en = "Right Click to summon and dismiss your sea pony... because \"seahorse fry\" doesn't sound very cute at all.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого морського поні... бо «мальок морського коника» звучить геть не мило." },
    { en = "Right Click to summon and dismiss your Lunar Lantern.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свій Місячний Ліхтар." },
    { en = "Right Click to summon and dismiss your Festival Lantern.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свій Святковий Ліхтар." },
    { en = "Hardens your skin, reducing all damage you take by $s3% and granting immunity to interrupt, silence, and pushback effects for $d.", ua = "Зміцнює твою шкіру, зменшуючи всю отримувану шкоду на $s3% і даючи на $d імунітет до ефектів переривання, безмовності та збивання творення." },
    { en = "Right Click to summon and dismiss your Darkmoon Cub.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє Левеня Темного Місяця." },
    { en = "Right Click to summon and dismiss your Fetish Shaman.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого Шамана-Фетиша." },
    { en = "Strikes all nearby enemies, dealing $s1 $?a429523[Arcane][Bleed] damage and an additional $405233o1 $?a429523[Arcane][Bleed] damage over $405233d.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Б'є всіх ворогів поруч, завдаючи $s1 $?a429523[арканної][кровотечної] шкоди та додатково $405233o1 $?a429523[арканної][кровотечної] шкоди протягом $405233d.\n\n\n\n|cFFFFFFFFДає $s2 $lочко комбо:очка комбо;.|r" },
    { en = "Summons and dismisses Tyrael's Charger.  This mount changes depending on your Riding skill and location.", ua = "Прикликає Бойового Коня Тіраеля або відкликає його. Ця їздова тварина змінюється залежно від твого вміння верхової їзди та місцевості." },
    { en = "Summons and dismisses a rideable Spectral Gryphon mount.  This is a flying mount.", ua = "Прикликає верхового Примарного Грифона або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Spectral Wind Rider mount.  This is a flying mount.", ua = "Прикликає верхового Примарного Вершника Вітру або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Blazing Drake.  This is a flying mount.", ua = "Прикликає верхового Палахкого Дрейка або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Twilight Harbinger.  This is a flying mount.", ua = "Прикликає верхового Сутінкового Передвісника або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Life-Binder's Handmaiden.  This is a flying mount.", ua = "Прикликає верхову Служницю Життєплетиці або відкликає її. Це літальна їздова тварина." },
    { en = "All single-target damage done by you and your minions grants you and your pet shadowy shields that absorb $s1% of the damage dealt$?s219272[][ for $108366d], up to $s2% of maximum health.", ua = "Уся одноцільова шкода, завдана вами та вашими прислужниками, дає вам і вашому улюбленцю тіньові щити, що поглинають $s1% завданої шкоди$?s219272[][ протягом $108366d], до $s2% максимального здоров'я." },
    { en = "Roll a short distance.", ua = "Перекочуєшся на коротку відстань." },
    { en = "Heals you for $s1% and your pet for $128594s1% of maximum health.$?s385539[\n\n\n\nExhilaration heals you for an additional ${$385539s1}.1% of your maximum health over $385540d.][]", ua = "Зцілює вас на $s1% та вашого улюбленця на $128594s1% від максимального здоров'я.$?s385539[\n\n\n\nПіднесення додатково зцілює вас на ${$385539s1}.1% від вашого максимального здоров'я протягом $385540d.][]" },
    { en = "Right Click to summon or dismiss the Soul of the Aspects.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Душу Аспектів." },
    { en = "Summons and dismisses a rideable Experiment 12-B.  This is a flying mount.", ua = "Прикликає верховий Експеримент 12-B або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses the Heart of the Aspects.  This mount changes depending on your Riding skill and location.", ua = "Прикликає Серце Аспектів або відкликає його. Ця їздова тварина змінюється залежно від твого вміння верхової їзди та місцевості." },
    { en = "Intimidates any target the Voidwalker attacks, increasing threat generation.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nAlways keep this effect active.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Залякує будь-яку ціль, яку атакує блукач Порожнечі, посилюючи генерацію загрози.\n\n\n\n|cFFFFFFFFАвтоматичне творіння:|r\n\nЗавжди тримай цей ефект активним.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб перемкнути)|r" },
    { en = "Right Click to summon and dismiss an Eye of the Legion.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Око Легіону." },
    { en = "Summons and dismisses a rideable Feldrake.  This is a flying mount.", ua = "Прикликає верхового Дрейка Скверни або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Jade Cloud Serpent.  This is a flying mount.", ua = "Прикликає верхового Нефритового Хмарного Змія або відкликає його. Це літальна їздова тварина." },
    { en = "Assault the target in a bloodthirsty craze, dealing $s1 Physical damage and restoring $117313s1% of your health.\n\n\n\nBloodbath wounds the target to suffer $113344o1 Bleed damage over $113344d. Using Bloodbath on a target that is affected by Bloodbath extends the bleed by $113344d.\n\n\n\n|cFFFFFFFFGenerates ${$s2/10} Rage and has a $s3% chance to Enrage you.|r", ua = "Атакуєте ціль у кровожерливому шаленстві, завдаючи $s1 фізичної шкоди та відновлюючи $117313s1% вашого здоров'я.\n\n\n\nКривава баня ранить ціль, завдаючи $113344o1 шкоди від кровотечі протягом $113344d. Застосування Кривавої бані до цілі, на яку вже діє Кривава баня, продовжує кровотечу на $113344d.\n\n\n\n|cFFFFFFFFГенерує ${$s2/10} люті та має $s3% шанс розлютити вас.|r" },
    { en = "Poisoned weapons have a chance to deal $s1 Nature damage to a target already affected by Deadly Poison.", ua = "Отруєна зброя має шанс завдати $s1 шкоди від сил природи цілі, яка вже під дією «Смертельної отрути»." },
    { en = "Extend a cloak that shrouds party and raid members within $115834A1 yards in shadows, providing stealth for $d.", ua = "Розгортає покров, що огортає тінями членів групи й рейду в радіусі $115834A1 м, надаючи їм непомітність на $d." },
    { en = "A massive gust of air that deals $s1 Physical damage.", ua = "Потужний порив повітря, що завдає $s1 фізичної шкоди." },
    { en = "Right Click to summon and dismiss your Darkmoon Rabbit.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого Кролика Темного Місяця." },
    { en = "Shapeshift into Treant Form.", ua = "Перевтілює тебе в подобу древня." },
    { en = "Fires a beam of light that scatters to strike a clump of targets. \n\n\n\nIf the beam is aimed at an enemy target, it deals $114852s1 Holy damage and radiates ${$114852s2*$<healmod>} healing to 5 allies within $114852A2 yds.\n\n\n\nIf the beam is aimed at a friendly target, it heals for ${$114871s1*$<healmod>} and radiates $114871s2 Holy damage to 5 enemies within $114871A2 yds.\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.", ua = "Випускає промінь світла, що розсіюється, уражаючи скупчення цілей. \n\n\n\nЯкщо промінь спрямовано на ворожу ціль, він завдає $114852s1 священної шкоди та випромінює ${$114852s2*$<healmod>} зцілення на 5 союзників у радіусі $114852A2 м.\n\n\n\nЯкщо промінь спрямовано на дружню ціль, він зцілює на ${$114871s1*$<healmod>} і випромінює $114871s2 священної шкоди на 5 ворогів у радіусі $114871A2 м.\n\n\n\n|cFFFFFFFFСтворює $s2 Священної сили." },
    { en = "For the next $d, $s1% of your healing done and $s2% of your damage done is converted to healing on up to $s4 nearby injured party or raid members, up to ${$MHP*$s3/100} healing to each target per second.", ua = "Протягом наступних $d $s1% завданого вами зцілення та $s2% завданої вами шкоди перетворюються на зцілення до $s4 поранених членів групи чи рейду поблизу, до ${$MHP*$s3/100} зцілення кожній цілі за секунду." },
    { en = "Hurls a Light-infused hammer to the ground, dealing $114919s1 Holy damage to nearby enemies and healing up to 6 nearby allies for $119952s1, every $114918t1 sec for ${$122773d-1.5} sec.", ua = "Жбурляє просякнутий Світлом молот у землю, завдаючи $114919s1 шкоди Святом ворогам поблизу та зцілюючи до 6 союзників поблизу на $119952s1, кожні $114918t1 сек протягом ${$122773d-1.5} сек." },
    { en = "Burns harmful spells, removing $89808s1 harmful Magic effect from an ally.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nCast only upon master when $ghe:she; is unable to cast spells due to a Magic effect.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Спалює шкідливі закляття, знімаючи $89808s1 шкідливий магічний ефект із союзника.\n\n\n\n|cFFFFFFFFАвтоматичне творіння:|r\n\nТвориться лише на господаря, коли $gвін:вона; не може творити закляття через магічний ефект.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб перемкнути)|r" },
    { en = "Hurl a staggering blast of wind at an enemy, dealing a total of ${$115357sw1+$115360sw1} Physical damage, bypassing armor.", ua = "Жбурляє у ворога приголомшливий порив вітру, що завдає загалом ${$115357sw1+$115360sw1} фізичної шкоди в обхід броні." },
    { en = "Taunts the target to attack you, and increases the threat you generate against them by $116189s2% for $116189d$?s328670[ Causes them to move toward you at $116189m3% increased speed.][.]$?s115315[\n\n\n\nThis ability can be targeted on your Statue of the Black Ox, causing the same effect on all enemies within  $118635A1 yards of the statue.][]", ua = "Провокує ціль атакувати тебе і збільшує загрозу, яку ти створюєш проти неї, на $116189s2% на $116189d$?s328670[ Змушує її рухатися до тебе зі швидкістю, збільшеною на $116189m3%.][.]$?s115315[\n\n\n\nЦю здібність можна спрямувати на твою Статую Чорного Вола, накладаючи той самий ефект на всіх ворогів у межах  $118635A1 ярдів від статуї.][]" },
    { en = "You may store an additional $s1 Holy Power beyond the maximum of 3. No ability ever consumes more than 3 Holy Power.", ua = "Ти можеш накопичувати додатково $s1 од. святої сили понад максимум у 3. Жодна здібність ніколи не витрачає більше 3 од. святої сили." },
    { en = "Deals $s1 Fire damage to a target.$?a231795[\n\n\n\nDamage increased by $231795s1% if you have Immolated the target.][]\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Завдає $s1 шкоди вогнем цілі.$?a231795[\n\n\n\nШкода збільшується на $231795s1%, якщо ти підпалив ціль.][]\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб перемкнути)|r" },
    { en = "Causes a surge of invigorating mists, healing the target for $<healing>$?s274586[ and all allies with your Renewing Mist active for $425804s1][].", ua = "Викликає сплеск живильних туманів, зцілюючи ціль на $<healing>$?s274586[ і всіх союзників з активним вашим Оновлювальним туманом на $425804s1][]." },
    { en = "Life in the twisting nether has made this demon particularly agile, increasing its chance to dodge and parry by $s1%.", ua = "Життя у вируючому Нижньому Світі зробило цього демона особливо спритним, збільшивши його шанс ухилитися та парирувати на $s1%." },
    { en = "Bloodthirst heals the Warrior for $s1% of their health.", ua = "Кровожерність зцілює воїна на $s1% його здоров'я." },
    { en = "Pummels all targets in front of you, dealing ${5*$117418s1} Physical damage to your primary target and ${5*$117418s1*$s6/100} damage to all other enemies over $113656d. Deals reduced damage beyond $s1 targets. Can be channeled while moving.", ua = "Молотить усі цілі перед тобою, завдаючи основній цілі ${5*$117418s1} фізичної шкоди, а всім іншим ворогам — ${5*$117418s1*$s6/100} шкоди впродовж $113656d. Шкода зменшується, якщо цілей більше ніж $s1. Можна підтримувати під час руху." },
    { en = "Fires a magical projectile, tethering the enemy and any other enemies within $s2 yds for $d, stunning them for $117526d if they move more than $s2 yds from the arrow.$?s321468[\n\n\n\nTargets stunned by Binding Shot deal $321469s1% less damage to you for $321469d after the effect ends.][]", ua = "Випускає магічний снаряд, прив'язуючи ворога та всіх інших ворогів у межах $s2 м на $d. Якщо вони відійдуть далі ніж на $s2 м від стріли, їх буде оглушено на $117526d.$?s321468[\n\n\n\nЦілі, оглушені Сковувальним пострілом, завдають вам на $321469s1% менше шкоди протягом $321469d після завершення ефекту.][]" },
    { en = "Call down a molten meteor on your target, dealing $s1 damage to up to $I enemies within $A1 yards of your target.", ua = "Закликає на вашу ціль розплавлений метеор, завдаючи $s1 шкоди щонайбільше $I ворогам у межах $A1 ярдів від вашої цілі." },
    { en = "Channel Jade lightning, causing $o1 Nature damage over $117952d to the target$?a154436[, generating 1 Chi each time it deals damage,][] and sometimes knocking back melee attackers.", ua = "Спрямовує нефритову блискавку, завдаючи цілі $o1 шкоди Природою протягом $117952d$?a154436[, генеруючи 1 Чі щоразу, коли вона завдає шкоди,][] та інколи відкидаючи нападників ближнього бою." },
    { en = "Summons and dismisses a rideable Azure Water Strider.", ua = "Прикликає верхового Блакитного Водоступа або відкликає його." },
    { en = "Burns an enemy, then inflicts additional Fire damage every $t2 sec for $d.", ua = "Спалює ворога, а тоді завдає додаткової шкоди вогнем кожні $t2 с протягом $d." },
    { en = "Smashes an enemy with a rocky fist, stunning the target for $d.", ua = "Б'є ворога кам'яним кулаком, приголомшуючи ціль на $d." },
    { en = "Right Click to summon and dismiss your Porcupette.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє Дикображеня." },
    { en = "Summons and dismisses a rideable Pandaren Kite.  This is a flying mount.", ua = "Прикликає верхового Пандаренського Повітряного Змія або відкликає його. Це літальна їздова тварина." },
    { en = "Knocks down all enemies within $A1 yards, stunning them for $d.", ua = "Збиває з ніг усіх ворогів у радіусі $A1 м, приголомшуючи їх на $d." },
    { en = "Surrounds the target with healing mists, restoring $119611o1 health over $119611d.\n\n\n\nIf Renewing Mist heals a target past maximum health, it will travel to another injured ally within $119607A2 yds.$?a231606[\n\n\n\nEach time Renewing Mist heals, it has a $s2% chance to increase the healing of your next Vivify by $197206s1%.][]", ua = "Огортає ціль цілющими туманами, відновлюючи $119611o1 здоров'я протягом $119611d.\n\n\n\nЯкщо Туман відновлення зцілює ціль понад максимум здоров'я, він переходить до іншого пораненого союзника в межах $119607A2 ярдів.$?a231606[\n\n\n\nЩоразу, коли Туман відновлення зцілює, він має $s2% шанс збільшити зцілення вашого наступного Оживлення на $197206s1%.][]" },
    { en = "Commands your demon to perform its most powerful ability. This spell will transform based on your active pet. \n\n$?s30146[\n\nFelguard: $@spellname89766][]\n\nFelhunter: $@spellname19647\n\nVoidwalker: $@spellname17767\n\nIncubus/Succubus: $@spellname6358\n\nImp: $@spellname89808", ua = "Наказує вашому демону застосувати його найпотужнішу здібність. Це закляття змінюється залежно від вашого активного улюбленця. \n\n$?s30146[\n\nСтраж Скверни: $@spellname89766][]\n\nМисливець Скверни: $@spellname19647\n\nБлукач Порожнечі: $@spellname17767\n\nІнкуб/Сукуб: $@spellname6358\n\nБіс: $@spellname89808" },
    { en = "Burns the Master's wounds, dealing a small amount of damage, then restoring $o2% health over $d.", ua = "Припікає рани господаря, завдаючи незначної шкоди, а тоді відновлює $o2% здоров'я протягом $d." },
    { en = "Summons and dismisses a rideable Onyx Panther.", ua = "Прикликає верхову Оніксову Пантеру або відкликає її." },
    { en = "Teleports you to Dalaran.", ua = "Телепортує тебе до Даларана." },
    { en = "Summons and dismisses a rideable Green Dragon Turtle.", ua = "Прикликає верхову Зелену Драконочерепаху або відкликає її." },
    { en = "Right Click to summon or dismiss your Jade Owl.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити вашу Нефритову Сову." },
    { en = "Right Click to summon or dismiss your Sapphire Cub.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє Сапфірове Тигреня." },
    { en = "Summons and dismisses a rideable Great Red Dragon Turtle.", ua = "Прикликає верхову Велику Червону Драконочерепаху або відкликає її." },
    { en = "Your mana regeneration is increased by $s1%.", ua = "Твоє відновлення мани збільшено на $s1%." },
    { en = "Allows you a moment of peace as you kneel in quiet contemplation to ponder the nature of the Light.", ua = "Дарує тобі мить спокою: ти стаєш на коліна в тихому спогляданні, роздумуючи про природу Світла." },
    { en = "Transforms you into an Obsidian Nightwing, allowing you to fly very fast and carry an ally on your back.  This is a flying mount.", ua = "Перетворює тебе на Обсидіанового Нічокрила, дозволяючи літати дуже швидко й нести союзника на спині. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Sapphire Panther.", ua = "Прикликає верхову Сапфірову Пантеру або відкликає її." },
    { en = "Summons and dismisses a rideable Jade Panther.", ua = "Прикликає верхову Нефритову Пантеру або відкликає її." },
    { en = "Summons and dismisses a rideable Ruby Panther.", ua = "Прикликає верхову Рубінову Пантеру або відкликає її." },
    { en = "Summons and dismisses a rideable Dawnstone Panther.", ua = "Прикликає верхову Світанковокам'яну Пантеру або відкликає її." },
    { en = "Calls forth the Grand Expedition Yak, complete with helpful grummles for all your vendor needs.", ua = "Прикликає Великого Похідного Яка разом із послужливими ґрумлями на всі твої торгові потреби." },
    { en = "Summons and dismisses a rideable Crimson Riding Crane.", ua = "Прикликає верхового Багряного Їздового Журавля або відкликає його." },
    { en = "Summons and dismisses a rideable White Riding Yak.", ua = "Прикликає верхового Білого Їздового Яка або відкликає його." },
    { en = "Right Click to summon and dismiss your crab.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого краба." },
    { en = "Right Click to summon and dismiss your raven.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого крука." },
    { en = "Soar forward through the air at high speed for $d.\n\n \n\nIf used again while active, you will land, reducing the movement speed of enemies within $123586A1 yds by $123586s2% for $123586d.", ua = "Стрімко ширяєте вперед у повітрі на високій швидкості протягом $d.\n\n \n\nЯкщо застосувати знову, поки ефект активний, ви приземлитеся, знижуючи швидкість пересування ворогів у межах $123586A1 м на $123586s2% протягом $123586d." },
    { en = "Right Click to summon and dismiss your terrible turnip.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою жахливу ріпу." },
    { en = "Right Click to summon and dismiss your red cricket.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого червоного цвіркуна." },
    { en = "Gives a chance to block enemy melee attacks.", ua = "Дає шанс блокувати ворожі атаки ближнього бою." },
    { en = "Summons and dismisses a rideable Amber Scorpion.", ua = "Прикликає верхового Бурштинового Скорпіона або відкликає його." },
    { en = "Summons and dismisses a rideable Azure Cloud Serpent. This is a flying mount.", ua = "Прикликає верхового Блакитного Хмарного Змія або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Golden Cloud Serpent.  This is a flying mount.", ua = "Прикликає верхового Золотого Хмарного Змія або відкликає його. Це літальна їздова тварина." },
    { en = "Right Click to summon and dismiss your tiny goldfish.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою крихітну золоту рибку." },
    { en = "Right Click to summon and dismiss your feral vermling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого дикого вермлінга." },
    { en = "Absorbs all damage taken for $d, up to $s3% of your maximum health, and redirects $s4% of that amount to the enemy target as Nature damage over $124280d.", ua = "Поглинає всю отриману шкоду протягом $d, до $s3% вашого максимального здоров'я, і перенаправляє $s4% від цієї кількості ворожій цілі як шкоду Природи протягом $124280d." },
    { en = "Summons and dismisses a rideable Thundering Jade Cloud Serpent.  This is a flying mount.", ua = "Прикликає верхового Громового Нефритового Хмарного Змія або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Cataclysmic Gladiator's Twilight Drake.  This is a flying mount.", ua = "Прикликає верхового Сутінкового Дрейка Катаклізмового Гладіатора або відкликає його. Це літальна їздова тварина." },
    { en = "Summons and dismisses an Imperial Quilen. This mount changes depending on your Riding skill and location.", ua = "Прикликає Імперського Квілена або відкликає його. Ця їздова тварина змінюється залежно від твого вміння верхової їзди та місцевості." },
    { en = "Right Click to summon and dismiss your Lucky Quilen Cub.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє Щасливе Квіленя." },
    { en = "Command your pet to retrieve the loot from a nearby corpse within $A1 yards.", ua = "Наказує твоєму улюбленцю принести здобич із ближнього трупа в радіусі $A1 м." },
    { en = "When you kill an enemy, you summon a Healing Sphere, healing you for $125355s1 when you walk through it.$?s322719[\n\n\n\nWhen you kill an enemy with Blackout Kick, you have a $322719m1% chance to summon a Chi Sphere, granting 1 Chi when you walk through it.][]", ua = "Коли ви вбиваєте ворога, ви прикликаєте сферу зцілення, що зцілює вас на $125355s1, коли ви проходите крізь неї.$?s322719[\n\n\n\nКоли ви вбиваєте ворога Затьмарливим копняком, ви маєте $322719m1% шанс прикликати сферу чі, що надає 1 чі, коли ви проходите крізь неї.][]" },
    { en = "You fly through the air at a quick speed on a meditative cloud.", ua = "Ти швидко летиш у повітрі на медитативній хмарі." },
    { en = "Right Click to summon and dismiss the Hopling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Стрибунця." },
    { en = "Right Click to summon and dismiss the Aqua Strider.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Водоступа." },
    { en = "Right Click to summon and dismiss Grinder.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Дробильника." },
    { en = "You command your Crane to do a trick.", ua = "Ти наказуєш своєму журавлеві виконати трюк." },
    { en = "Allows the Hunter and the Water Strider to walk across water. Any damage will cancel the effect.", ua = "Дозволяє мисливцеві та водоступу ходити по воді. Будь-яка шкода скасовує ефект." },
    { en = "You command your pet Rodent to take a rest.", ua = "Ви наказуєте своєму гризунові відпочити." },
    { en = "The apex of goblin ingenuity!  This mount changes depending on your Riding skill and location.", ua = "Вершина гоблінської винахідливості! Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місцеперебування." },
    { en = "A device that rotates the very world beneath you!  This mount changes depending on your Riding skill and location.", ua = "Пристрій, що обертає сам світ під вами! Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місцеперебування." },
    { en = "Transforms the enemy into a porcupine, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на дикобраза, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Your spirit travels to your home temple, leaving your body behind. \n\n\n\nUse Zen Pilgrimage again to return back to near your departure point.", ua = "Ваш дух мандрує до вашого рідного храму, лишаючи тіло позаду. \n\n\n\nВикористайте «Дзен-паломництво» знову, щоб повернутися до місця відправлення." },
    { en = "$?a200617[Returns your spirit back to its body, returning you near to where you once were.\n\n\n\nLeaving the Wandering Isle will cancel Zen Pilgrimage: Return.]\n\n[Returns your spirit back to its body, returning you near to where you once were.\n\n\n\nLeaving Peak of Serenity will cancel Zen Pilgrimage: Return.]", ua = "$?a200617[Повертає ваш дух у тіло, переносячи вас близько до місця, де ви були раніше.\n\n\n\nЯкщо ви залишите Мандрівний острів, Дзен-паломництво: Повернення скасується.]\n\n[Повертає ваш дух у тіло, переносячи вас близько до місця, де ви були раніше.\n\n\n\nЯкщо ви залишите Пік Спокою, Дзен-паломництво: Повернення скасується.]" },
    { en = "Right click to summon and dismiss your Yu'lon Kite.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого змія Ю'лон." },
    { en = "Right click to summon and dismiss your Chi-ji Kite.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого змія Чі-Джі." },
    { en = "Summons and dismisses a rideable Onyx Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового оніксового хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Crimson Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового багряного хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Heavenly Onyx Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового небесного оніксового хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Heavenly Crimson Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового небесного багряного хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Heavenly Golden Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового небесного золотого хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses Yu'lei, Daughter of Jade.  This is a flying mount.", ua = "Прикликає та відпускає Ю'лей, Доньку Нефриту. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Heavenly Azure Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового небесного лазурового хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Astral Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відпускає їздового астрального хмарозмія. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Azure Riding Crane.", ua = "Прикликає та відпускає їздового лазурового верхового журавля." },
    { en = "Summons and dismisses a rideable Golden Riding Crane.", ua = "Прикликає та відпускає їздового золотого верхового журавля." },
    { en = "Summons and dismisses a rideable Regal Riding Crane.", ua = "Прикликає та відпускає їздового величного верхового журавля." },
    { en = "Summons and dismisses a rideable Jungle Riding Crane.", ua = "Прикликає та відпускає їздового джунглевого верхового журавля." },
    { en = "Summons and dismisses a rideable Albino Riding Crane.", ua = "Прикликає та відпускає їздового білого верхового журавля." },
    { en = "Summons and dismisses a rideable Black Riding Yak.", ua = "Прикликає та відпускає їздового чорного верхового яка." },
    { en = "Summons and dismisses a rideable Brown Riding Yak.", ua = "Прикликає та відпускає їздового коричневого верхового яка." },
    { en = "Summons and dismisses a rideable Grey Riding Yak.", ua = "Прикликає та відпускає їздового сірого верхового яка." },
    { en = "Summons and dismisses a rideable Blonde Riding Yak.", ua = "Прикликає та відпускає їздового рудувато-білого верхового яка." },
    { en = "Summons and dismisses a rideable Crimson Water Strider.", ua = "Прикликає та відпускає їздового багряного водомірку." },
    { en = "Summons and dismisses a rideable Orange Water Strider.", ua = "Прикликає та відпускає їздового жовтогарячого водомірку." },
    { en = "Summons and dismisses a rideable Jade Water Strider.", ua = "Прикликає та відпускає їздового нефритового водомірку." },
    { en = "Summons and dismisses a rideable Golden Water Strider.", ua = "Прикликає та відпускає їздового золотого водомірку." },
    { en = "Summons and dismisses a rideable Black Dragon Turtle.", ua = "Прикликає та відпускає їздову чорну дракон-черепаху." },
    { en = "Summons and dismisses a rideable Blue Dragon Turtle.", ua = "Прикликає та відпускає їздову синю дракон-черепаху." },
    { en = "Summons and dismisses a rideable Brown Dragon Turtle.", ua = "Прикликає та відпускає їздову коричневу дракон-черепаху." },
    { en = "Summons and dismisses a rideable Purple Dragon Turtle.", ua = "Прикликає та відпускає їздову фіолетову дракон-черепаху." },
    { en = "Summons and dismisses a rideable Red Dragon Turtle.", ua = "Прикликає та відпускає їздову червону дракон-черепаху." },
    { en = "Summons and dismisses a rideable Great Green Dragon Turtle.", ua = "Прикликає та відпускає їздову велику зелену дракон-черепаху." },
    { en = "Summons and dismisses a rideable Great Black Dragon Turtle.", ua = "Прикликає та відпускає їздову велику чорну дракон-черепаху." },
    { en = "Summons and dismisses a rideable Great Blue Dragon Turtle.", ua = "Прикликає та відпускає їздову велику синю дракон-черепаху." },
    { en = "Summons and dismisses a rideable Great Brown Dragon Turtle.", ua = "Прикликає та відпускає їздову велику коричневу дракон-черепаху." },
    { en = "Summons and dismisses a rideable Great Purple Dragon Turtle.", ua = "Прикликає та відпускає їздову велику фіолетову дракон-черепаху." },
    { en = "Cause a target corpse to explode in a shower of gore. Does not affect mechanical or elemental corpses.", ua = "Підриває цільовий труп фонтаном тельбухів. Не діє на трупи механізмів та елементалів." },
    { en = "Allows the Druid to befriend an ambient creature, which will follow the Druid for $d.", ua = "Дозволяє друїду заприятелювати з дрібним створінням, що йтиме за ним упродовж $d." },
    { en = "Right Click to summon and dismiss your Thundering Serpent Hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити ваше громове змієня." },
    { en = "Right Click to summon and dismiss your singing cricket.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого співучого цвіркуна." },
    { en = "Right Click to summon and dismiss your Crane.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого журавля." },
    { en = "Launch fireworks from your gun, bow or crossbow.", ua = "Запускає феєрверк із твоєї рушниці, лука чи арбалета." },
    { en = "Summons and dismisses a rideable Crimson Pandaren Phoenix.  This is a flying mount.", ua = "Прикликає та відпускає їздового багряного пандаренського фенікса. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Thundering August Cloud Serpent.  This is a flying mount.  Requires Cloud Serpent Riding from the Order of the Cloud Serpent.", ua = "Прикликає та відпускає їздового громового величного хмарозмія. Це летюча їздова тварина. Потребує вміння їздити на хмарозмії від ордену Хмарозмія." },
    { en = "Summons and dismisses a rideable Green Shado-Pan Riding Tiger.", ua = "Прикликає та відпускає їздового зеленого верхового тигра Шадо-Пану." },
    { en = "Summons and dismisses a rideable Blue Shado-Pan Riding Tiger.", ua = "Прикликає та відпускає їздового синього верхового тигра Шадо-Пану." },
    { en = "Summons and dismisses a rideable Red Shado-Pan Riding Tiger.", ua = "Прикликає та відпускає їздового червоного верхового тигра Шадо-Пану." },
    { en = "Summons and dismisses a rideable Brown Riding Goat.", ua = "Прикликає та відпускає їздову коричневу верхову козу." },
    { en = "Summons and dismisses a Red Flying Cloud. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відпускає червону летючу хмару. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місцеперебування." },
    { en = "Summons and dismisses a rideable White Riding Goat.", ua = "Прикликає та відпускає їздову білу верхову козу." },
    { en = "Summons and dismisses a rideable Black Riding Goat.", ua = "Прикликає та відпускає їздову чорну верхову козу." },
    { en = "You're a Level $ctrmin2066 Monk.  Grats!", ua = "Ви монах $ctrmin2066 рівня. Вітаємо!" },
    { en = "Hurls a torrent of Chi energy up to $460485s1 yds forward, dealing $148135s1 Nature damage to all enemies, and $130654s1 healing to the Monk and all allies in its path. Healing and damage reduced beyond $s1 targets.\n\n$?c1[\n\n\n\nCasting Chi Burst does not prevent avoiding attacks.][]", ua = "Жбурляє потік енергії ці на $460485s1 ярдів уперед, завдаючи $148135s1 шкоди Природою всім ворогам і зцілюючи на $130654s1 монаха та всіх союзників на його шляху. Зцілення і шкода зменшені понад $s1 цілей.\n\n$?c1[\n\n\n\nСотворення Вибуху ці не заважає ухилятися від атак.][]" },
    { en = "Right Click to summon and dismiss your jade tentacle.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашу нефритову мацаку." },
    { en = "Right Click to summon and dismiss your venus.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашу венерину мухоловку." },
    { en = "Summons and dismisses a rideable Son of Galleon.", ua = "Прикликає та відпускає їздового Сина Галеона." },
    { en = "Reduces your falling speed.\n\n\n\nYou can activate this ability with the jump key while falling.", ua = "Зменшує швидкість вашого падіння.\n\n\n\nВи можете застосувати цю здібність клавішею стрибка під час падіння." },
    { en = "Right Click to summon and dismiss your Pandaren Water Spirit.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого пандаренського духа води." },
    { en = "Right Click to summon and dismiss your Baneling.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого згубника." },
    { en = "Transforms the Mage to look like another player for $94632d.", ua = "Змінює вигляд мага на вигляд іншого гравця на $94632d." },
    { en = "Summons and dismisses a rideable Thundering Ruby Cloud Serpent.  This is a flying mount.  Requires Cloud Serpent Riding from the Order of the Cloud Serpent.", ua = "Прикликає та відпускає їздового громового рубінового хмарозмія. Це летюча їздова тварина. Потребує вміння їздити на хмарозмії від ордену Хмарозмія." },
    { en = "Summons and dismisses a rideable Ashen Pandaren Phoenix.  This is a flying mount.", ua = "Прикликає та відпускає їздового попелястого пандаренського фенікса. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Emerald Pandaren Phoenix.  This is a flying mount.", ua = "Прикликає та відпускає їздового смарагдового пандаренського фенікса. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Violet Pandaren Phoenix.  This is a flying mount.", ua = "Прикликає та відпускає їздового фіолетового пандаренського фенікса. Це летюча їздова тварина." },
    { en = "Every $t1 sec, your next $?a137023[Keg Smash][Rising Sun Kick] or $?s399491[Sheilun's Gift][Vivify] releases a wave of Chi energy that flows through friends and foes, dealing $132467s1 Nature damage or $132463s1 healing. Bounces up to $115098s1 times to targets within $132466a2 yards.", ua = "Кожні $t1 сек. ваш наступний $?a137023[Удар барилом][Удар висхідного сонця] або $?s399491[Дар Шейлуна][Оживлення] вивільняє хвилю енергії ці, що тече крізь союзників і ворогів, завдаючи $132467s1 шкоди природою або $132463s1 зцілення. Відскакує до $115098s1 разів до цілей у радіусі $132466a2 ярдів." },
    { en = "Right Click to summon and dismiss your Imperial Moth.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого імперського метелика." },
    { en = "Right Click to summon and dismiss your Imperial Silkworm.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого імперського шовкопряда." },
    { en = "Creates a portal, teleporting group members that use it to Vale of Eternal Blossoms.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Долини Вічного Цвітіння." },
    { en = "Teleports you to Vale of Eternal Blossoms.", ua = "Телепортує тебе до Долини Вічного Цвітіння." },
    { en = "Right Click to summon and dismiss your spectral cub.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити ваше примарне тигреня." },
    { en = "Right Click to summon and dismiss your Darkmoon hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити ваше малятко Темного Місяця." },
    { en = "Right Click to summon and dismiss your Darkmoon glowfly.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого світляка Темного Місяця." },
    { en = "Right Click to summon and dismiss your Darkmoon Eye.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити ваше Око Темного Місяця." },
    { en = "Mount a Sky Golem, allowing you to fly very fast. The claws are surprisingly delicate and herbalists can use them to pick herbs! This is a flying mount.\n\n\n\nThe ability to pick herbs while mounted is limited to expansions before Dragonflight.", ua = "Осідлайте небесного голема, що дозволяє вам літати дуже швидко. Його пазурі на диво вправні, тож травники можуть збирати ними трави! Це летюча їздова тварина.\n\n\n\nЗбирати трави верхи можна лише в доповненнях до Польоту Драконів." },
    { en = "Intimidates any target the Felguard attacks, increasing threat generation.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nAlways keep this effect active.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Залякує будь-яку ціль, яку атакує сторож Скверни, посилюючи створення загрози.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗавжди тримати цей ефект активним.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб перемкнути)|r" },
    { en = "Right Click to summon and dismiss your Cinder Kitten.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити ваше вогнисте кошеня." },
    { en = "Summons and dismisses a Swift Windsteed.  This mount changes depending on your Riding skill and location.", ua = "Прикликає та відпускає швидкого вітроскакуна. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місцеперебування." },
    { en = "Right Click to summon and dismiss your Pandaren Fire Spirit.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого пандаренського духа вогню." },
    { en = "Right Click to summon and dismiss your Pandaren Air Spirit.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого пандаренського духа повітря." },
    { en = "Right Click to summon and dismiss your Pandaren Earth Spirit.", ua = "Клацніть правою кнопкою, щоб прикликати або відпустити вашого пандаренського духа землі." },
    { en = "Channels a jet of icy water at the target, $?s198146[slowing the target by $m2% and ][]dealing $o1 Frost damage to the target over $d.", ua = "Спрямовує на ціль струмінь крижаної води, $?s198146[сповільнюючи її на $m2% і ][]завдаючи їй $o1 шкоди від холоду протягом $d." },
