    { en = "Summons and dismisses a rideable Vicious Skeletal Warhorse.", ua = "Прикликає або відкликає верхового Лютого Кістяного Бойового Коня." },
    { en = "Right Click to summon and dismiss Lil' Bling.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Малого Блінга." },
    { en = "Summons and dismisses a Stormcrow.  This mount changes depending on your Riding skill and location.", ua = "Прикликає або відкликає Грозового Крука. Ця їздова тварина змінюється залежно від ваших навичок верхової їзди та місцеперебування." },
    { en = "Right Click to summon and dismiss your Ashleaf Spriteling.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Ясенолистого Дрібнодуха." },
    { en = "Right Click to summon and dismiss your Azure Crane Chick.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваше Блакитне Журавленя." },
    { en = "Right Click to summon and dismiss your Blackfuse Bombling.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашу Бомбочку Чорнокнота." },
    { en = "Right Click to summon and dismiss your Ruby Droplet.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашу Рубінову Краплю." },
    { en = "Right Click to summon and dismiss your Dandelion Frolicker.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого кульбабового жартівника." },
    { en = "Right Click to summon and dismiss your Death Adder Hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє маля смертоносної гадюки." },
    { en = "Right Click to summon and dismiss your Droplet of Y'Shaarj.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою краплину Й'Шаараджа." },
    { en = "Right Click to summon and dismiss your Gooey Sha-ling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє слизьке шаленя." },
    { en = "Right Click to summon and dismiss your Jademist Dancer.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого нефритотуманного танцюриста." },
    { en = "Right Click to summon and dismiss Kovi-Wovi.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Кові-Вові." },
    { en = "Right Click to summon and dismiss your Ominous Flame.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє лиховісне полум'я." },
    { en = "Right Click to summon and dismiss your Skunky Alemental.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого смердючого пиволементаля." },
    { en = "Right Click to summon and dismiss your Skywisp Moth.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого хмаропірного метелика." },
    { en = "Right Click to summon and dismiss your Spineclaw Crab.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого голчастоклішневого краба." },
    { en = "Right Click to summon and dismiss your Gulp Froglet.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє жабеня-ковтуна." },
    { en = "Right Click to summon and dismiss your Ashwing Moth.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого попелокрилого метелика." },
    { en = "Right Click to summon and dismiss your Flamering Moth.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого вогнекрилого метелика." },
    { en = "Right Click to summon and dismiss Bonkers the Boxing Hozen.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Бонкерса, боксера-гозена." },
    { en = "Summons and dismisses a rideable Spawn of Galakras.  This is a flying mount.", ua = "Прикликає та відкликає їздового нащадка Галакраса. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Kor'kron War Wolf.", ua = "Прикликає та відкликає їздового бойового вовка Кор'крон." },
    { en = "Summons and dismisses the Kor'kron Juggernaut.", ua = "Прикликає та відкликає Колос Кор'крон." },
    { en = "Right Click to summon and dismiss your Vengeful Porcupette.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє мстиве дикобразеня." },
    { en = "Summons and dismisses a rideable Ashhide Mushan Beast.", ua = "Прикликає та відкликає їздову мушанську звірину з попелястою шкурою." },
    { en = "Summons and dismisses a rideable Thundering Onyx Cloud Serpent.  This is a flying mount.  Requires Cloud Serpent Riding from the Order of the Cloud Serpent.", ua = "Прикликає та відкликає їздового громового оніксового хмарозмія. Це летюча їздова тварина. Потребує вміння «Їзда на хмарозмії» від ордену Хмарозмія." },
    { en = "Right Click to summon and dismiss your Gu'chi Swarmling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого роєвичка Гу'чі." },
    { en = "Right Click to summon and dismiss your Harmonious Porcupette.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє гармонійне дикобразеня." },
    { en = "Right Click to summon and dismiss your Jadefire Spirit.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого нефритовогняного духа." },
    { en = "Right Click to summon and dismiss your Rotten Little Helper.\n\n\n\nEven rotten helpers are very busy year-round, and only have leisure time during the Feast of Winter Veil.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого капосного помічника.\n\n\n\nНавіть капосні помічники цілий рік дуже зайняті й мають вільний час лише під час Свята Зимового Серпанку." },
    { en = "Summons and dismisses a rideable Tyrannical Gladiator's Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відкликає їздового хмарозмія тиранічного гладіатора. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Grievous Gladiator's Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відкликає їздового хмарозмія тяжкого гладіатора. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Prideful Gladiator's Cloud Serpent.  This is a flying mount.", ua = "Прикликає та відкликає їздового хмарозмія гордого гладіатора. Це летюча їздова тварина." },
    { en = "Right click to summon and dismiss your Sky Lantern.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свій небесний ліхтарик." },
    { en = "Right Click to summon and dismiss your Alterac Brew-Pup.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє альтеракське цуценя-пивоноса." },
    { en = "Right Click to summon and dismiss Murkalot.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Муркалота." },
    { en = "Summons and dismisses a rideable Emerald Hippogryph.  The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає та відкликає їздового смарагдового гіпогрифа. Можливості цієї їздової тварини залежать від вашого вміння їзди та місцеперебування." },
    { en = "Right Click to summon and dismiss your Treasure Goblin.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого скарбошукача-ґобліна." },
    { en = "Summons and dismisses an Iron Skyreaver.  This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Залізного небесного шматувальника. Ця їздова тварина змінюється залежно від вашого вміння їзди та місцеперебування." },
    { en = "Summons and dismisses a Dread Raven. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Крука жаху. Ця їздова тварина змінюється залежно від вашого вміння їзди та місцеперебування." },
    { en = "Right Click to summon and dismiss your Dread Hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє маля жаху." },
    { en = "Right Click to summon and dismiss your Iron Starlette.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою залізну зірочку." },
    { en = "Conjures a gust of wind that deals $s1 Nature damage to an enemy.", ua = "Прикликає порив вітру, що завдає ворогові $s1 шкоди Природи." },
    { en = "Call down a lightning strike on an enemy, dealing $s1 Nature damage, and leaving the Storm Elemental charged with energy for $d.\n\n\n\nWhile charged, the Storm Elemental's damage is increased by $s2%.", ua = "Закликає удар блискавки на ворога, завдаючи $s1 шкоди Природи й наповнюючи штормового елементаля енергією на $d.\n\n\n\nУ зарядженому стані шкода штормового елементаля збільшується на $s2%." },
    { en = "Channel the energy of the storms at your target, causing $269005s1 Nature damage to all enemies within $269005A1 yards every $t1 sec. Deals reduced damage beyond $s3 targets.\n\n\n\nThe damage of this ability increases by $s2% every time it deals damage.", ua = "Зосереджує енергію штормів на цілі, завдаючи $269005s1 шкоди Природи всім ворогам у межах $269005A1 ярдів кожні $t1 с. Завдає зменшеної шкоди понад $s3 цілей.\n\n\n\nШкода цієї здібності збільшується на $s2% щоразу, коли вона завдає шкоди." },
    { en = "Increases your chance to critically strike by $s1%.", ua = "Збільшує твій шанс завдати критичного удару на $s1%." },
    { en = "Heals all allies within $a2 yards for $<healing> over $d.$?s197721[ Extends the duration of all your heal over time effects by $s6 sec every $t1 sec.][]\n\n\n\nHealing decreased beyond $s3 targets.", ua = "Зцілює всіх союзників у радіусі $a2 ярдів на $<healing> упродовж $d.$?s197721[ Подовжує тривалість усіх ваших ефектів поступового зцілення на $s6 с кожні $t1 с.][]\n\n\n\nЗцілення зменшено понад $s3 цілей." },
    { en = "Right Click to summon and dismiss your unusually small abomination.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свою надзвичайно малу гидоту." },
    { en = "Summons or dismisses Lil' Leftovers.", ua = "Прикликає або відкликає Малі Недоїдки." },
    { en = "You gain an additional $s1% movement speed while in the land version of Travel Form. This movement speed bonus will not be granted if Travel Form is activated while in combat.\n\n\n\nThis effect is disabled in battlegrounds and arenas.", ua = "Ви отримуєте додаткові $s1% швидкості пересування в наземній версії Подорожньої подоби. Цей бонус швидкості не надається, якщо Подорожню подобу активовано в бою.\n\n\n\nЦей ефект вимкнено на полях бою та в аренах." },
    { en = "Right Click to summon and dismiss a Crazy Carrot.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Скажену моркву." },
    { en = "When the core hound takes melee attacks, it infuses its hide with molten lava, causing $160124s1 Fire damage to all further melee attackers for $159786d. Molten Hide can only activate every $s2 sec.", ua = "Коли пес ядра зазнає атак у ближньому бою, він просочує свою шкуру розпеченою лавою, завдаючи $160124s1 шкоди Вогню всім подальшим нападникам у ближньому бою протягом $159786d. «Розплавлена шкура» може активуватися лише раз на $s2 с." },
    { en = "The devilsaur feasts on a nearby Humanoid or Beast corpse within $a1 yards, healing it for $159954s1% of its maximum health and restoring $159954s2 focus over $159954d.", ua = "Дияволозавр живиться трупом гуманоїда чи звіра неподалік у межах $a1 ярдів, зцілюючи себе на $159954s1% максимального здоров'я й відновлюючи $159954s2 зосередження протягом $159954d." },
    { en = "Your pet beats its powerful wings, slowing the fall speed of both itself and the hunter for $d.", ua = "Ваш улюбленець б'є потужними крилами, сповільнюючи швидкість падіння як свою, так і мисливця на $d." },
    { en = "The Fox heightens its senses, increasing dodge chance by $s1% for $d.", ua = "Лис загострює свої чуття, збільшуючи шанс ухилення на $s1% протягом $d." },
    { en = "The Riverbeast bites gruesomely at its target, causing Mortal Wounds on the target.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Річкова звірина жахливо вгризається в ціль, завдаючи їй Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого отримуваного зцілення протягом $115804d." },
    { en = "When falling below $s2% health, the Quilen's skin will change to stone, causing it to take $160048s1% less damage and regenerate $160048s2% of its maximum health every $160048t2 sec for $160048d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, шкіра квілена перетворюється на камінь, через що він отримує на $160048s1% менше шкоди та відновлює $160048s2% максимального здоров'я кожні $160048t2 с протягом $160048d.\n\n\n\nЦей ефект може спрацьовувати лише раз на $s3 с." },
    { en = "When falling below $s2% health, the Clefthoof's skin will thicken, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, шкура щілинокопита грубішає, даруючи зниження вхідної шкоди на $160058s1% на $160058d.\n\n\n\nЦей ефект може спрацьовувати лише раз на $s3 с." },
    { en = "The Scorpion lashes out with its tail, stinging the target and causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Скорпіон вдаряє хвостом, жалячи ціль і завдаючи ефекту Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого отримуваного зцілення протягом $115804d." },
    { en = "The Shale Beast hardens its rocky armor, reducing damage taken by $s1% for $d.", ua = "Сланцева звірина загартовує свою кам'яну броню, зменшуючи отримувану шкоду на $s1% протягом $d." },
    { en = "The Aqiri slashes at the target's feet, reducing movement speed by $s1% for $d.", ua = "Аквірі розтинає ноги цілі, зменшуючи швидкість пересування на $s1% протягом $d." },
    { en = "The Spider wraps webs around the target, slowing movement by $s1% for $d.", ua = "Павук обплутує ціль павутинням, сповільнюючи пересування на $s1% протягом $d." },
    { en = "Summons and dismisses your Mechanical Axebeak.", ua = "Прикликає та відкликає вашого механічного сокирудзьоба." },
    { en = "Transforms the enemy into a polar bear cub, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на полярне ведмежа, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Transforms the enemy into a monkey, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на мавпу, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Transforms the enemy into a penguin, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на пінгвіна, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Transforms the enemy into a peacock, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на павича, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Right Click to summon and dismiss your Royal Peachick.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє королівське павеня." },
    { en = "Ascend into the air, keeping you out of harm's way. Lasts $d. Can only be used while in Ashran.", ua = "Здіймаєшся в повітря, уникаючи небезпеки. Триває $d. Можна використовувати лише в Ашрані." },
    { en = "Stuns the target Player for $d. If the judgment holds for $d, the enemy will be instantly teleported to your jail. Can only be used while in Ashran.", ua = "Приголомшує цільового гравця на $d. Якщо осуд протримається $d, ворога буде миттєво телепортовано до твоєї в'язниці. Можна використовувати лише в Ашрані." },
    { en = "Right Click to summon and dismiss your lifelike mechanical boar.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого мов живого механічного вепра." },
    { en = "Hurls a Steel Trap to the target location that snaps shut on the first enemy that approaches, immobilizing them for $162480d and causing them to bleed for $162487o1 damage over $162487d. \n\n\n\nDamage other than Steel Trap may break the immobilization effect. Trap will exist for $162496d. Limit 1.", ua = "Жбурляє Сталеву пастку в обране місце, що захряскується на першому ворогу, який наблизиться, знерухомлюючи його на $162480d та завдаючи $162487o1 шкоди від кровотечі протягом $162487d. \n\n\n\nБудь-яка шкода, окрім Сталевої пастки, може зруйнувати ефект знерухомлення. Пастка існуватиме $162496d. Ліміт 1." },
    { en = "Summons and dismisses a rideable Warforged Nightmare mount.  The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає та відкликає їздову тварину Бойовиковане Жахіття. Можливості цієї їздової тварини залежать від вашого вміння їзди та місцеперебування." },
    { en = "Summons and dismisses a rideable Grinning Reaver  mount.  The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає та відкликає їздову тварину Вишкірений жнець. Можливості цієї їздової тварини залежать від вашого вміння їзди та місцеперебування." },
    { en = "Attempts to finish off a foe, causing up to $<damage> Physical damage based on Rage spent. Only usable on enemies that have less than 20% health.$?s316405[\n\n\n\nIf your foe survives, $s2% of the Rage spent is refunded.][]", ua = "Намагається добити ворога, завдаючи до $<damage> фізичної шкоди залежно від витраченої люті. Застосовується лише до ворогів зі здоров'ям менше 20%.$?s316405[\n\n\n\nЯкщо ворог виживає, $s2% витраченої люті повертається.][]" },
    { en = "Summon and dismiss your Teroclaw  Hatchling.", ua = "Прикликає та відкликає ваше маля терокіготь." },
    { en = "A quick beam of solar light burns the enemy $?s231050[and all enemies within $164815A2 yards ][]for $164815s1 Nature damage and then an additional $164815o2 Nature damage over $164815d.$?s137013[\n\n\n\n|cFFFFFFFFGenerates ${$m3/10} Astral Power.|r][]", ua = "Швидкий промінь сонячного світла спалює ворога $?s231050[й усіх ворогів у межах $164815A2 м ][]на $164815s1 шкоди Природою, а потім додатково на $164815o2 шкоди Природою протягом $164815d.$?s137013[\n\n\n\n|cFFFFFFFFГенерує ${$m3/10} астральної сили.|r][]" },
    { en = "$?a114301[You descend on starry dust, slowing your falling speed.][You flap your wings, slowing your falling speed.]", ua = "$?a114301[Ти спускаєшся на зоряному пилу, сповільнюючи швидкість падіння.][Ти змахуєш крилами, сповільнюючи швидкість падіння.]" },
    { en = "Shapeshift into flight form, increasing movement speed and allowing you to fly. Cannot use in combat. \n\n\n\nThe act of shapeshifting frees the caster of movement impairing effects.", ua = "Перетворюєтеся на летючу подобу, підвищуючи швидкість пересування та дозволяючи літати. Не можна використовувати в бою. \n\n\n\nСам акт перевтілення звільняє заклинача від ефектів, що сповільнюють пересування." },
    { en = "Right Click to summon and dismiss your Elekk Plushie.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати свого плюшевого елекка." },
    { en = "Instantly kills any creature under level $m2, or player under $m3% health.", ua = "Миттєво вбиває будь-яку істоту, нижчу за $m2 рівень, або гравця, що має менш ніж $m3% здоров'я." },
    { en = "Summons and dismisses a Creeping Carpet.  This is a ground mount.", ua = "Прикликає та відкликає Повзучий килим. Це наземна їздова тварина." },
    { en = "Summons and dismisses a rideable Core Hound.", ua = "Прикликає та відкликає їздового пса ядра." },
    { en = "Right Click to summon and dismiss Syd the Squid.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Сіда Кальмара." },
    { en = "Cripples the target, reducing movement speed by $s1% for $d (4 sec in PvP).", ua = "Калічить ціль, зменшуючи швидкість пересування на $s1% протягом $d (4 с у PvP)." },
    { en = "Debilitates the target, reducing movement speed by $s1% for $d (4 sec in PvP).", ua = "Знесилює ціль, зменшуючи швидкість пересування на $s1% протягом $d (4 с у PvP)." },
    { en = "Intimidates any target you attack, increasing your threat generation.\n\n\n\nAlso increases chance to dodge and parry by $s2%, and reduces physical damage taken by $s4%.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nAlways keep this effect active.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Залякує будь-яку ціль, яку ви атакуєте, збільшуючи генерацію вашої загрози.\n\n\n\nТакож збільшує шанс ухилення та парирування на $s2% і зменшує отримувану фізичну шкоду на $s4%.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗавжди тримає цей ефект активним.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "Intimidates any target you attack, increasing your threat generation.\n\n\n\nAlso increases chance to dodge and parry by $s2%, and reduces physical damage taken by $s4%.\n\n\n\n\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nAlways keep this effect active.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Залякує будь-яку ціль, яку ви атакуєте, збільшуючи генерацію вашої загрози.\n\n\n\nТакож збільшує шанс ухилення та парирування на $s2% і зменшує отримувану фізичну шкоду на $s4%.\n\n\n\n\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗавжди тримає цей ефект активним.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "The $?s108499[Abyssal][Infernal] taunts the target to attack it.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nTaunts the current target if it is not attacking the $?s108499[Abyssal][Infernal] and taunts any target who attacks its master.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "$?s108499[Безодняр][Інфернал] провокує ціль атакувати його.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nПровокує поточну ціль, якщо вона не атакує $?s108499[безодняра][інфернала], і провокує будь-яку ціль, що атакує його володаря.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "The infernal releases a powerful burst of flames, dealing $s1 Fire damage to nearby targets, and stunning them for $d.", ua = "Інфернал випускає потужний спалах полум'я, завдаючи $s1 шкоди Вогню цілям поблизу та оглушуючи їх на $d." },
    { en = "The abyssal releases a powerful burst of flames, dealing $s1 Fire damage to nearby targets, and stunning them for $d.", ua = "Безодняр випускає потужний спалах полум'я, завдаючи $s1 шкоди Вогню цілям поблизу та оглушуючи їх на $d." },
    { en = "Purges $s1 beneficial magic effect from an enemy.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nUse on the Infernal's current target.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Очищає $s1 корисний магічний ефект із ворога.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗастосовується на поточну ціль інфернала.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "Purges $s2 beneficial magic effect from an enemy.\n\n\n\n|cFFFFFFFFAuto-Cast:|r\n\nUse on the Abyssal's current target.\n\n\n\n|cFF777777(Right-Click to toggle)|r", ua = "Очищає $s2 корисний магічний ефект із ворога.\n\n\n\n|cFFFFFFFFАвтоматичне прочитання:|r\n\nЗастосовується на поточну ціль безодняра.\n\n\n\n|cFF777777(Клацніть правою кнопкою, щоб увімкнути чи вимкнути)|r" },
    { en = "Right Click to summon and dismiss your Lovebird Hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати своє маля папужки-нерозлучника." },
    { en = "Counter an enemy's spellcast, preventing any spell from that school of magic from being cast for $19647d.", ua = "Контрить творення закляття ворога, не даючи творити жодне закляття цієї школи магії протягом $19647d." },
