    { en = "Right Click to summon and dismiss your Sunblade Micro-Defender.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Мікрозахисника Сонячного Клинка." },
    { en = "Right Click to summon and dismiss your Chaos Pup.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваше Цуценя Хаосу." },
    { en = "Right Click to summon and dismiss your Wretched Servant.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Жалюгідного Слугу." },
    { en = "Right Click to summon and dismiss K'ute.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати К'юта." },
    { en = "Right click to summon and dismiss your Race MiniZep.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваш Гоночний Мінідирижабль." },
    { en = "Summons and dismisses your $@spellname180545.", ua = "Прикликає або відкликає вашого $@spellname180545." },
    { en = "Summons and dismisses a rideable Felsteel Annihilator.  This is a flying mount.", ua = "Прикликає або відкликає верхового Скверносталевого Анігілятора. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Corrupted Dreadwing.", ua = "Прикликає або відкликає верхового Зіпсованого Жахокрила." },
    { en = "When any party or raid member within $a1 yds takes more than $s3% of their health in damage in a single hit, each member gains $404996s1% increased damage and healing, decaying over $404996d. This cannot occur within $392503d of the aura being applied.", ua = "Коли будь-який член групи чи рейду в межах $a1 м зазнає одним ударом шкоди понад $s3% свого здоров'я, кожен член отримує на $404996s1% більше шкоди й зцілення; ефект згасає протягом $404996d. Це не може статися протягом $392503d після накладання аури." },
    { en = "Interrupts the enemy's spellcasting and locks them from that school of magic for $d.|cFFFFFFFF$?s183782[\n\n\n\nGenerates $218903s1 Fury on a successful interrupt.][]|r", ua = "Перериває чарування ворога й блокує йому цю школу магії на $d.|cFFFFFFFF$?s183782[\n\n\n\nГенерує $218903s1 люті при успішному перериванні.][]|r" },
    { en = "Summons and dismisses a rideable Vicious War Mechanostrider.", ua = "Прикликає або відкликає верхового Лютого Бойового Механоступа." },
    { en = "Right Click to summon and dismiss your Lost Netherpup.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати своє Загублене цуценя Нижнього Світу." },
    { en = "Right Click to summon and dismiss your Cinder Pup.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати своє Вогнисте цуценя." },
    { en = "Summons and dismisses your $@spellname185052.", ua = "Прикликає або відкликає вашого $@spellname185052." },
    { en = "Right Click to summon and dismiss your Nightmare Bell.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свій Дзвоник Жахіть." },
    { en = "Throw a demonic glaive at the target, dealing $337819s1 Physical damage. The glaive can ricochet to $?$s320386[${$337819x1-1} additional enemies][an additional enemy] within 10 yards.", ua = "Кидає в ціль демонічну глефу, завдаючи $337819s1 фізичної шкоди. Глефа може рикошетити на $?$s320386[${$337819x1-1} додаткових ворогів][ще одного ворога] у межах 10 ярдів." },
    { en = "Drink an alchemical concoction that heals you for $?a354425&a193546[${$O1}.1][$o1]% of your maximum health over $d.", ua = "Випиваєте алхімічне зілля, яке зцілює вас на $?a354425&a193546[${$O1}.1][$o1]% від максимального здоров'я протягом $d." },
    { en = "A quick shot that causes $sw2 Arcane damage.$?s260393[\n\n\n\nArcane Shot has a $260393h% chance to reduce the cooldown of Rapid Fire by ${$260393m1/10}.1 sec.][]", ua = "Швидкий постріл, що завдає $sw2 арканної шкоди.$?s260393[\n\n\n\nАрканний постріл має $260393h% шанс скоротити перезарядження Швидкого вогню на ${$260393m1/10}.1 с.][]" },
    { en = "Right Click to summon and dismiss your Ghostshell Crab.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свого Краба-привида." },
    { en = "Summon and dismiss Blorp.", ua = "Прикликати або відкликати Блорпа." },
    { en = "Increases your movement speed by $s1% for $d. Upon expiring, increases your movement speed by $186258s1% for another $186258d.", ua = "Збільшує твою швидкість руху на $s1% на $d. Після завершення збільшує швидкість руху на $186258s1% ще на $186258d." },
    { en = "Causes all spells and attacks to miss and reduces all damage you take by $s4% for $d, but you cannot attack.", ua = "Усі закляття й атаки по тобі схиблюють, а отримувана шкода зменшена на $s4% протягом $d, але ти не можеш атакувати." },
    { en = "Right click to summon and dismiss this companion.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати цього супутника." },
    { en = "Summons and dismisses your $@spellname186305.", ua = "Прикликає або відкликає вашого $@spellname186305." },
    { en = "Summons and dismisses your $@spellname186828.", ua = "Прикликає або відкликає вашого $@spellname186828." },
    { en = "Right Click to summon and dismiss your Glowing Sporebat.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свого Сяйного спорокажана." },
    { en = "Right Click to summon and dismiss your Dusty Sporewing.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свою Запорошену спорокрилку." },
    { en = "Right Click to summon and dismiss your Bloodthorn Hatchling.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати своє Кривавотернове маля." },
    { en = "Deals $s1 Chaos damage.", ua = "Завдає $s1 шкоди Хаосу." },
    { en = "Right Click to summon and dismiss your Corrupted Nest Guardian.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свого Зіпсованого вартового гнізда." },
    { en = "Right Click to summon and dismiss your Periwinkle Calf.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати своє Барвінкове телятко." },
    { en = "Hurls a frost trap to the target location that incapacitates the first enemy that approaches for $3355d. Damage may break the effect. Limit 1. Trap will exist for $3355d.", ua = "Кидаєш крижану пастку у вказане місце: перший ворог, що наблизиться, втрачає змогу діяти на $3355d. Шкода може зняти ефект. Не більше 1 цілі. Пастка існує $3355d." },
    { en = "Right Click to summon and dismiss your Left Shark.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свою Лівшу-акулу." },
    { en = "Hurls a bolt of lightning at the target, dealing $s1 Nature damage.$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s1 Maelstrom.|r]?a383303[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed and damage.|r]?a187880[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed.|r][]", ua = "Шпурляє блискавку в ціль, завдаючи $s1 шкоди природою.$?a343725[\n\n\n\n|cFFFFFFFFСтворює $343725s1 Виру.|r]?a383303[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання та шкоди.|r]?a187880[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання.|r][]" },
    { en = "Right Click to summon and dismiss Crusher.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Дробильника." },
    { en = "Allows you to see enemies and treasures through physical barriers, as well as enemies that are stealthed and invisible. Lasts $d.\n\n\n\nLoss of control effects disrupt the sight.", ua = "Дозволяє бачити ворогів і скарби крізь фізичні перешкоди, а також ворогів у скраданні та невидимих. Триває $d.\n\n\n\nЕфекти втрати контролю перебивають цей зір." },
    { en = "Summons and dismisses your $@spellname189043.", ua = "Прикликає або відкликає вашого $@spellname189043." },
    { en = "Summons and dismisses your $@spellname189044.", ua = "Прикликає або відкликає вашого $@spellname189044." },
    { en = "Right Click to summon and dismiss your Shard of Cyrukh.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свій Уламок Цірука." },
    { en = "Summons and dismisses your $@spellname189364.", ua = "Прикликає або відкликає вашого $@spellname189364." },
    { en = "Summons and dismisses your Illidari Felstalker.", ua = "Прикликає або відкликає вашого Скверноблукача іллідарі." },
    { en = "Summons and dismisses your $@spellname189999.", ua = "Прикликає або відкликає вашого $@spellname189999." },
    { en = "Reduces the damage your summoned demon takes from creature area of effect attacks by an additional $s1%.", ua = "Зменшує шкоду, яку ваш прикликаний демон отримує від атак істот по площі, додатково на $s1%." },
    { en = "Right Click to summon and dismiss Nibbles.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Гризунчика." },
    { en = "Right Click to summon and dismiss Brightpaw.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Світлолапку." },
    { en = "Right Click to summon and dismiss Murkidan.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Муркідана." },
    { en = "Conjures mana food for you and your allies. Conjured items disappear if logged out for more than 15 minutes.", ua = "Створює манову їжу для тебе та твоїх союзників. Створені предмети зникають, якщо ти поза грою понад 15 хвилин." },
    { en = "Summons and dismisses your $@spellname190690.", ua = "Прикликає або відкликає вашого $@spellname190690." },
    { en = "Summons Sindragosa, who breathes frost on all enemies within $s1 yd in front of you, dealing $190780s1 Frost damage and slowing movement speed by $190780s2% for $190780d.", ua = "Прикликає Синдрагосу, яка дихає морозом на всіх ворогів у межах $s1 м перед тобою, завдаючи $190780s1 шкоди від морозу та сповільнюючи швидкість руху на $190780s2% на $190780d." },
    { en = "Leap atop your Charger for $221883d, increasing movement speed by $221883s4%. Usable while indoors or in combat.", ua = "Застрибуєш на свого бойового коня на $221883d, збільшуючи швидкість руху на $221883s4%. Можна використовувати в приміщенні та в бою." },
    { en = "Summons and dismisses your $@spellname190977.", ua = "Прикликає або відкликає вашого $@spellname190977." },
    { en = "Right Click to summon and dismiss your Enchanted Cauldron.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свій Зачарований казан." },
    { en = "Right Click to summon and dismiss your Enchanted Torch.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати свій Зачарований смолоскип." },
    { en = "Right Click to summon and dismiss your Enchanted Pen.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати своє Зачароване перо." },
    { en = "Summons and dismisses your $@spellname191314.", ua = "Прикликає або відкликає вашого $@spellname191314." },
    { en = "Leap into the air and land with explosive force, dealing $200166s2 Chaos damage to enemies within 8 yds, and stunning them for $200166d. Players are Dazed for $247121d instead.\n\n\n\nUpon landing, you are transformed into a hellish demon for $162264d, $?s320645[immediately resetting the cooldown of your Eye Beam and Blade Dance abilities, ][]greatly empowering your Chaos Strike and Blade Dance abilities and gaining $162264s4% Haste$?(s235893&s204909)[, $162264s5% Versatility, and $162264s3% Leech]?(s235893&!s204909[ and $162264s5% Versatility]?(s204909&!s235893)[ and $162264s3% Leech][].", ua = "Стрибаєте в повітря й приземляєтеся з вибуховою силою, завдаючи $200166s2 хаотичної шкоди ворогам у радіусі 8 м і оглушуючи їх на $200166d. Гравців натомість дезорієнтовано на $247121d.\n\n\n\nПри приземленні ви перетворюєтеся на пекельного демона на $162264d, що $?s320645[негайно скидає перезарядження ваших здібностей Промінь з очей та Танець клинків, ][]значно підсилює ваші здібності Удар хаосу та Танець клинків і дарує $162264s4% Поспіху$?(s235893&s204909)[, $162264s5% Універсальності та $162264s3% Висмоктування]?(s235893&!s204909[ та $162264s5% Універсальності]?(s204909&!s235893)[ та $162264s3% Висмоктування][]." },
    { en = "Summons and dismisses a Soaring  Skyterror.  This mount changes depending on your Riding skill and location.", ua = "Прикликає або відкликає Ширяльного небоносця. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місцеперебування." },
    { en = "Surround yourself with a shield of lightning for $d.\n\n\n\nMelee attackers have a $h% chance to suffer $192109s1 Nature damage$?a137041[ and have a $s3% chance to generate a stack of Maelstrom Weapon]?a137040[ and have a $s4% chance to generate $s5 Maelstrom][].\n\n\n\n$?s383010[The Shaman can have up to two Elemental Shields active on them.][Only one Elemental Shield can be active on the Shaman at a time.]", ua = "Оточує вас щитом блискавок на $d.\n\n\n\nНападники в ближньому бою з шансом $h% зазнають $192109s1 шкоди природою$?a137041[ і з шансом $s3% створюють заряд Зброї виру]?a137040[ і з шансом $s4% створюють $s5 Виру][].\n\n\n\n$?s383010[Шаман може мати до двох активних стихійних щитів на собі.][На шамані водночас може бути активним лише один стихійний щит.]" },
    { en = "Summons and dismisses a rideable Grove Defiler.", ua = "Прикликає або відкликає їздового Осквернителя гаю." },
    { en = "Right Click to summon and dismiss Emmigosa.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Еммігосу." },
    { en = "Summons and dismisses a rideable Vicious Black War Steed.", ua = "Прикликає або відкликає їздового Лютого чорного бойового скакуна." },
    { en = "Teleports the caster to the Emerald Dreamway.\n\n\n\nCasting Dreamwalk again while in the Emerald Dreamway will return you back to near your departure point.", ua = "Телепортує заклинача на Смарагдовий Шлях Снів.\n\n\n\nПовторне застосування Мандрівки сном на Смарагдовому Шляху Снів поверне вас назад поблизу місця відбуття." },
    { en = "Teleports you to the Hall of the Guardian.", ua = "Телепортує тебе до Зали Хранителя." },
    { en = "Summons and dismisses a rideable Eclipse Dragonhawk.  This is a flying mount.", ua = "Прикликає або відкликає їздового Затемнярного драконояструба. Це летюча їздова тварина." },
    { en = "Hurls a Phoenix that causes $s1 Fire damage to the target and splashes $224637s2 Fire damage to other nearby enemies. This damage is always a critical strike.", ua = "Жбурляє фенікса, що завдає цілі $s1 шкоди від вогню та оббризкує інших ворогів поблизу, завдаючи їм $224637s2 шкоди від вогню. Ця шкода — завжди критичний удар." },
    { en = "Maims the target, reducing movement speed by $s1% for $d.", ua = "Калічить ціль, зменшуючи швидкість руху на $s1% на $d." },
    { en = "You are able to jump again while near the apex of your first jump.", ua = "Ти можеш стрибнути ще раз поблизу найвищої точки першого стрибка." },
    { en = "Rips a hole in time and space, opening a portal that damages your target.\n\n\n\n|cFFFFFFFFGenerates $s2 Soul Shard Fragments.|r", ua = "Розриває діру в часі та просторі, відкриваючи портал, що завдає шкоди вашій цілі.\n\n\n\n|cFFFFFFFFСтворює $s2 Уламки душі.|r" },
    { en = "Summons and dismisses the Spirit of Eche'ro.", ua = "Прикликає або відкликає Дух Еке'ро." },
    { en = "Finishing move that disembowels the target, causing damage per combo point.$?s382511[ Targets with Find Weakness suffer an additional $382511s1% damage as Shadow.][]\n\n   1 point  : ${$m1*1} damage\n\n   2 points: ${$m1*2} damage\n\n   3 points: ${$m1*3} damage\n\n   4 points: ${$m1*4} damage\n\n   5 points: ${$m1*5} damage$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$m1*6} damage][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$m1*7} damage][]", ua = "Завершальний прийом, що потрошить ціль, завдаючи шкоди за кожне очко комбо.$?s382511[ Цілі з ефектом «Пошук слабкості» зазнають додаткової шкоди як Тінь на $382511s1%.][]\n\n   1 очко  : ${$m1*1} шкоди\n\n   2 очки: ${$m1*2} шкоди\n\n   3 очки: ${$m1*3} шкоди\n\n   4 очки: ${$m1*4} шкоди\n\n   5 очок: ${$m1*5} шкоди$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$m1*6} шкоди][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$m1*7} шкоди][]" },
    { en = "Festering Strike applies a pustulent lesion that will burst on death or when damaged by Scourge Strike, dealing $194311s1 Shadow damage and generating $195757s1 Runic Power.\n\n\n\nStacks up to $194310u times on any target.", ua = "Гнійний удар накладає гнійну ятрицю, що вибухає при смерті або коли її уражає Удар Бича, завдаючи $194311s1 шкоди тінню та породжуючи $195757s1 рунічної сили.\n\n\n\nНакопичується до $194310u разів на будь-якій цілі." },
    { en = "Summons and dismisses a rideable Felsaber.", ua = "Прикликає або відкликає їздового Сквернотигра." },
    { en = "Reduces the damage you take from Blessing of Sacrifice by $s1%.", ua = "Знижує шкоду, яку ти отримуєш від «Благословення жертовності», на $s1%." },
    { en = "Releases the Light within yourself, healing $s2 injured allies instantly and an injured ally every $t1 sec within $200653A1 yds for $200654s1.\n\n\n\nAllies healed also receive $200654s2% increased healing from your Holy Light, Flash of Light, and Holy Shock spells for $200654d.", ua = "Вивільняє Світло всередині вас, миттєво зцілюючи $s2 поранених союзників і одного пораненого союзника кожні $t1 с у межах $200653A1 м на $200654s1.\n\n\n\nЗцілені союзники також отримують на $200654s2% більше зцілення від ваших заклять «Святе світло», «Спалах світла» та «Святий шок» на $200654d." },
    { en = "Summons and dismisses a rideable Infinite Timereaver. This is a flying mount.", ua = "Прикликає або відкликає їздового Безконечного часожнеця. Це летюча їздова тварина." },
    { en = "Throws two demonic glaives in a whirlwind of energy, causing ${7*($201628sw1+$201789sw1)} Chaos damage over $d to all nearby enemies.", ua = "Кидає у вихорі енергії дві демонічні глефи, що протягом $d завдають ${7*($201628sw1+$201789sw1)} шкоди хаосу всім ворогам поруч." },
    { en = "Furiously strikes all enemies in front of you, dealing ${$203413s1*9} Physical damage over $d. Critical strike chance increased by $s3% against any target below $s4% health. Deals reduced damage beyond $s5 targets.", ua = "Шалено б'єш усіх ворогів перед собою, завдаючи ${$203413s1*9} фізичної шкоди протягом $d. Шанс критичного удару збільшено на $s3% проти цілей, що мають менш ніж $s4% здоров'я. Якщо цілей більше за $s5, шкода зменшується." },
    { en = "Enter a defensive posture, critically blocking all attacks while a stream of shadowflame erupts from |cFFFFCC99Scale of the Earth-Warder|r, dealing ${6*$203526s1} Shadowflame over $d to all enemies in front of you. You can use defensive abilities while this is active.", ua = "Ти стаєш у захисну стійку, критично блокуючи всі атаки, поки з |cFFFFCC99Луски Вартового Землі|r виривається потік тіньополум'я, що протягом $d завдає ${6*$203526s1} шкоди тіньополум'ям усім ворогам перед тобою. Поки ефект активний, можеш використовувати захисні здібності." },
    { en = "Focuses the power of Wind through |cFFFFCC99Thas'dorah|r, dealing $sw1 Physical damage to your target, and leaving behind a trail of wind for $204475d that increases the movement speed of allies by $204477s1%.", ua = "Зосереджує силу Вітру крізь |cFFFFCC99Thas'dorah|r, завдаючи цілі $sw1 фізичної шкоди та лишаючи за собою вітряний слід на $204475d, що підвищує швидкість пересування союзників на $204477s1%." },
    { en = "Place a Sigil of Flame at the target location that activates after $d.\n\n\n\nDeals $204598s1 $@spelldesc395020 damage, and an additional $204598o3 $@spelldesc395020 damage over $204598d, to all enemies affected by the sigil.\n\n\n\n|CFFffffffGenerates $389787s1 Fury.|R", ua = "Розміщує сигіл полум'я у вказаному місці, що активується за $d.\n\n\n\nЗавдає $204598s1 $@spelldesc395020 шкоди миттєво й додатково $204598o3 $@spelldesc395020 шкоди протягом $204598d усім ворогам під дією сигілу.\n\n\n\n|CFFffffffГенерує $389787s1 люті.|R" },
    { en = "Raise your dagger into the sky, channeling a torrent of void energy into the target for $o Shadow damage over $d. Insanity does not drain during this channel.\n\n\n\nRequires Voidform.", ua = "Здіймаєте кинджал до неба, спрямовуючи в ціль потік енергії Порожнечі, що завдає $o Тіньової шкоди протягом $d. Безум не виснажується під час цього спрямування.\n\n\n\nПотребує Форми Порожнечі." },
    { en = "Allows you to tame pets in the Mechanical family.", ua = "Дозволяє приручати улюбленців із родини механічних." },
    { en = "Strikes all enemies in front of you with a hungering attack that deals $sw2 Physical damage and heals you for $s3% of that damage.", ua = "Уражає всіх ворогів перед вами голодною атакою, що завдає $sw2 фізичної шкоди й зцілює вас на $s3% цієї шкоди." },
    { en = "Lash out with the |cFFFFCC99Ashbringer|r, dealing $sw1 Radiant damage$?a179546[, and an additional $o3 Radiant damage over $d,][] to all enemies within $a1 yd in front of you, and reducing movement speed by $s2% for $d.\n\n\n\nDemon and Undead enemies are stunned for $205290d if struck by the Wake of Ashes.$?a179546[\n\n\n\n|cFFFFFFFFGenerates $218001s1 Holy Power.][]", ua = "Завдає нищівного удару |cFFFFCC99Згубником попелу|r, завдаючи $sw1 шкоди Сяйва$?a179546[ і ще $o3 шкоди Сяйва протягом $d,][] усім ворогам у межах $a1 м перед вами і зменшуючи швидкість руху на $s2% протягом $d.\n\n\n\nДемони та нежить приголомшуються на $205290d, якщо їх уразить Слід попелу.$?a179546[\n\n\n\n|cFFFFFFFFГенерує $218001s1 Святої Сили.][]" },
    { en = "Draws in all nearby clouds of mist generated by |cFFFFCC99Sheilun|r, healing the target for $s1 per cloud absorbed.", ua = "Втягує всі ближні хмари туману, створені |cFFFFCC99Шейлун|r, зцілюючи ціль на $s1 за кожну поглинуту хмару." },
    { en = "Raises |cFFFFCC99The Fist of Ra-den|r to the sky and absorbs all nearby electric energy, causing your next $n casts of Lightning Bolt or Chain Lightning to be instant and deal $s1% increased damage.", ua = "Здіймає |cFFFFCC99Кулак Ра-дена|r до неба і вбирає всю електричну енергію поблизу, через що твої наступні $n прочитань «Блискавки» чи «Ланцюгової блискавки» стають миттєвими і завдають на $s1% більше шкоди." },
    { en = "Unleashes the fiery power Odyn bestowed the |cFFFFCC99Warswords|r, dealing ${$205546sw2+$205547sw2} Fire damage and an additional $205546o3 Fire damage over $205546d to all enemies within $205546A2 yards.", ua = "Вивільняє вогняну міць, якою Одін наділив |cFFFFCC99Бойові мечі|r, завдаючи всім ворогам у радіусі $205546A2 м ${$205546sw2+$205547sw2} шкоди вогнем і ще $205546o3 шкоди вогнем протягом $205546d." },
    { en = "Discharge a massive jolt of electricity from |cFFFFCC99Titanstrike|r into all your pets$?s217200[][ and Dire Beasts], causing them to deal up to ${$RAP*1.15*0.5*$<bmMastery>} Nature damage to their target every $207094t sec. for $207094d.$?s217200[ Also causes the next pet frenzy caused by Barbed Shot to deal $218635s1 additional Nature damage on each of the 5 attacks.][]", ua = "Випускає потужний електричний розряд із |cFFFFCC99Титанобою|r у всіх ваших улюбленців$?s217200[][ і Лютих звірів], змушуючи їх завдавати до ${$RAP*1.15*0.5*$<bmMastery>} шкоди Природою своїй цілі кожні $207094t сек. протягом $207094d.$?s217200[ Також наступне шаленство улюбленця, спричинене Колючим пострілом, завдає $218635s1 додаткової шкоди Природою при кожній із 5 атак.][]" },
    { en = "Carve into the soul of your target, dealing ${$s2+$214743s1} Fire damage and an additional $o1 Fire damage over $d.  Immediately shatters $s3 Soul Fragments from the target and $s4 additional Soul $LFragment :Fragments; every $t1 sec.", ua = "Врізається в душу вашої цілі, завдаючи ${$s2+$214743s1} шкоди вогнем і додатково $o1 шкоди вогнем протягом $d.  Миттєво відколює $s3 фрагменти душі від цілі та $s4 додаткові $LфрагментИ :фрагменти; душі кожні $t1 сек." },
    { en = "A burst of water at your $?a455630[Surging Totem's][Healing Rain's] location heals up to $s2 injured allies within $A1 yards for $s1.", ua = "Сплеск води в місці вашого $?a455630[Буручого тотема][Цілющого дощу] зцілює до $s2 поранених союзників у межах $A1 ярдів на $s1." },
    { en = "Draws upon the power of |cFFFFCC99Light's Wrath|r, dealing $s1 Radiant damage to the target, increased by $s2% per ally affected by your Atonement.", ua = "Черпає силу |cFFFFCC99Гніву Світла|r, завдаючи цілі $s1 променистої шкоди, що збільшується на $s2% за кожного союзника під дією твоєї «Спокути»." },
    { en = "Applies Light of the Naaru to the target, healing for $s2 and increasing your healing done to that target by $208065s1% for $d.", ua = "Накладає на ціль «Світло наару», зцілюючи на $s2 та збільшуючи твоє зцілення цієї цілі на $208065s1% на $d." },
    { en = "Release the natural power within G'Hanir to increase the frequency that all of your heal over time effects heal allies by ${100*(1/(1+($m1/100))-1)}% for $d.", ua = "Вивільни природну силу Ґ'Ганіра, щоб усі твої ефекти поступового зцілення зцілювали союзників на ${100*(1/(1+($m1/100))-1)}% частіше протягом $d." },
    { en = "Releases a blinding flash from |cFFFFCC99Truthguard|r, causing $s2 Holy damage to all nearby enemies within $A1 yds and reducing all damage they deal to you by $s1% for $d.", ua = "Випускає сліпучий спалах із |cFFFFCC99Вартового Істини|r, що завдає $s2 шкоди від Світла всім ворогам у радіусі $A1 м і знижує всю шкоду, яку вони тобі завдають, на $s1% на $d." },
    { en = "Heals the target for $o1 over $d.\n\n\n\nWhile channeling, Effuse and Enveloping Mist are instant cast, and will heal the soothed target without breaking the Soothing Mist channel.", ua = "Зцілює ціль на $o1 протягом $d.\n\n\n\nПід час підтримання Виливання та Огортальний туман сотворюються миттєво й зцілюють заспокоєну ціль, не перериваючи підтримання Заспокійливого туману." },
    { en = "Stomp the ground, causing a ring of corrupted spikes to erupt upwards, dealing $sw1 Shadow damage and applying the Colossus Smash effect to all nearby enemies.", ua = "Тупніть по землі, змусивши вгору вирватися кільце спотворених шпичаків, що завдають $sw1 шкоди Темрявою і накладають ефект «Удар колоса» на всіх ворогів поруч." },
    { en = "Playing Dead, tricking enemies into ignoring them. Lasts up to $d.", ua = "Прикидається мертвим, змушуючи ворогів не зважати на нього. Триває до $d." },
    { en = "Tell your pet to wake up.", ua = "Наказує твоєму улюбленцю прокинутися." },
    { en = "Shapeshift into a mountable ground travel form, increasing movement speed by $5419s1%. Also protects the caster from Polymorph effects. Only usable outdoors.\n\n\n\nThe act of shapeshifting frees the caster of movement impairing effects.", ua = "Перетворюєтеся на їздову подобу для наземних подорожей, підвищуючи швидкість пересування на $5419s1%. Також захищає мага від ефектів Перетворення. Можна використовувати лише надворі.\n\n\n\nСам акт перевтілення звільняє заклинача від ефектів, що сповільнюють пересування." },
    { en = "You are able to comprehend your allies' racial languages.", ua = "Ти розумієш расові мови своїх союзників." },
    { en = "Unleash Ashamane's Frenzy, clawing your target $m2 times over $d for ${$210723s1*$m2} Physical damage and an additional ${$210723s3*3*$m2} Bleed damage over $210723d.\n\n\n\n|cFFFFFFFFAwards $s3 combo $Lpoint:points;.|r", ua = "Вивільняє Шал Ашамейн, шматуючи кігтями ціль $m2 разів протягом $d на ${$210723s1*$m2} фізичної шкоди та додатково ${$210723s3*3*$m2} кровотечної шкоди протягом $210723d.\n\n\n\n|cFFFFFFFFДає $s3 $Lочко комбо:очка комбо;.|r" },
    { en = "Creates a runic prison at the target's location, slowing enemy movement speed by ${$211056s1/-1}%, inflicting ${$211088s1*6} Arcane damage over $d, and then detonating for Arcane damage equal to $s1% of your maximum mana.", ua = "Створює рунну в'язницю в місці розташування цілі, що сповільнює швидкість руху ворогів на ${$211056s1/-1}%, завдає ${$211088s1*6} арканної шкоди протягом $d, а потім вибухає, завдаючи арканної шкоди в розмірі $s1% твоєї максимальної мани." },
    { en = "Transforms the enemy into a compy for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на компі на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Transforms the enemy into a spider for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на павука на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Transforms the enemy into a snake for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на змію на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Transforms the enemy into a cockroach for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на таргана на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Deals $s1 Arcane damage to all targets within $A1 yds.", ua = "Завдає $s1 арканної шкоди всім цілям у радіусі $A1 м." },
    { en = "Deals $s1 Arcane damage to enemies within $A1 yds.", ua = "Завдає $s1 арканної шкоди ворогам у радіусі $A1 м." },
    { en = "|cFFFFCC99Thal'kiel|r drains $s2% of the life from your demon servants and unleashes a blast of Shadow damage at your current target equal to the life he stole.", ua = "|cFFFFCC99Тал'кіель|r висмоктує $s2% життя твоїх демонів-слуг і вивільняє у твою поточну ціль вибух шкоди тінню, що дорівнює викраденому життю." },
    { en = "Create a Crimson Vial to share with allies. Maximum of $212205m2 can be carried at once. \n\n\n\n$@spellicon212198 $@spellname212198\n\n$@spelldesc212198", ua = "Створює Багряний флакон, щоб поділитися із союзниками. Можна нести щонайбільше $212205m2 одночасно. \n\n\n\n$@spellicon212198 $@spellname212198\n\n$@spelldesc212198" },
    { en = "Smash the target with the blunt side of the cleaver, dealing light damage and stunning for $91800d.$?s63560[\n\n\n\n|CFFE55BB0Dark Transformation: Strike an enemy with a smashing attack, dealing $91797s2% of normal melee damage and stunning for $91797d.|R][]", ua = "Гатить ціль тупим боком тесака, завдаючи незначної шкоди й приголомшуючи на $91800d.$?s63560[\n\n\n\n|CFFE55BB0Темне перетворення: завдає нищівного удару ворогові, завдаючи $91797s2% звичайної шкоди в ближньому бою й приголомшуючи на $91797d.|R][]" },
    { en = "Hack at the enemy, dealing $212335s1% of normal melee damage.$?s63560[\n\n\n\n|CFFE55BB0Dark Transformation: Expel vile gas, dealing $212338s1% of normal melee damage as Shadow to all enemies within $212338A1 yds.|R][]", ua = "Рубає ворога, завдаючи $212335s1% звичайної шкоди в ближньому бою.$?s63560[\n\n\n\n|CFFE55BB0Темне перетворення: випускає мерзенний газ, завдаючи $212338s1% звичайної шкоди в ближньому бою у вигляді Тіні всім ворогам у межах $212338A1 ярд.|R][]" },
    { en = "Produce excess bile, becoming coated in it, reducing all damage taken by $212385s1% for $212385d.$?s63560[\n\n\n\n|CFFE55BB0Dark Transformation: Bloat with gastric gases, reducing all damage taken by $212383s1% for $212383d.|R][]", ua = "Виробляє надлишок жовчі й вкривається нею, знижуючи всю отримувану шкоду на $212385s1% на $212385d.$?s63560[\n\n\n\n|CFFE55BB0Темне перетворення: роздувається від шлункових газів, знижуючи всю отримувану шкоду на $212383s1% на $212383d.|R][]" },
    { en = "Hurl a hook, pulling the target. If the target is Immune, the abomination is instead pulled to the target.$?s63560[\n\n\n\n|CFFE55BB0Dark Transformation: Hurl a hook, pulling the target, and immobilizing them for $91807d. If the target is Immune, the flesh golem is instead pulled to the target.|R][]", ua = "Кидає гак, притягуючи ціль. Якщо ціль несприйнятлива, до неї натомість притягується сама гидота.$?s63560[\n\n\n\n|CFFE55BB0Темне перетворення: кидає гак, притягуючи ціль і знерухомлюючи її на $91807d. Якщо ціль несприйнятлива, до неї натомість притягується голем плоті.|R][]" },
