    { en = "Summons and dismisses your Avenging Felcrusher.", ua = "Прикликає та відкликає вашого Мстивого сквернотрощителя." },
    { en = "Summons and dismisses your Bleakhoof Ruinstrider.", ua = "Прикликає та відкликає вашого Тьмянокопитого руїнокрока." },
    { en = "Right Click to summon and dismiss your Rebellious Imp.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого Бунтівного біса." },
    { en = "Summons and dismisses Squawks. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Скрекота. Ця їздова тварина змінюється залежно від вашого вміння їзди та місця перебування." },
    { en = "Summons and dismisses your Giant Parrot. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає вашого Велетенського папугу. Ця їздова тварина змінюється залежно від вашого вміння їзди та місця перебування." },
    { en = "Summon and dismiss Sharkbait with a yummy cracker. This mount changes depending on your Riding skill and location.", ua = "Прикличте та відкличте Шаркбейта смачним крекером. Ця їздова тварина змінюється залежно від вашого вміння їзди та місця перебування." },
    { en = "Your damage brands the target, increasing magic damage taken by $1490s1%.", ua = "Твоя шкода таврує ціль, збільшуючи отримувану нею магічну шкоду на $1490s1%." },
    { en = "Summons and dismisses your Seabraid Stallion.", ua = "Прикликає та відкликає вашого Морегривого жеребця." },
    { en = "Summons and dismisses your Gilded Ravasaur.", ua = "Прикликає та відкликає вашого Позолоченого равазавра." },
    { en = "Right Click to summon and dismiss Tottle.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Тоттла." },
    { en = "Summons and dismisses your Goblin Hovercraft. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає ваше Гоблінське судно на повітряній подушці. Ця їздова тварина змінюється залежно від вашого вміння їзди та місця перебування." },
    { en = "Summons and dismisses your Xiwyllag ATV. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає ваш Всюдихід Хівіллаґ. Ця їздова тварина змінюється залежно від вашого вміння їзди та місця перебування." },
    { en = "Apply Hunter's Mark to the target, causing the target to always be seen and tracked by the Hunter.\n\n\n\nHunter's Mark increases the target's damage taken by $s1%. Can only be applied to a target at a time.", ua = "Накладає на ціль Мітку мисливця, через що мисливець завжди бачить і вистежує ціль.\n\n\n\nМітка мисливця збільшує отримувану ціллю шкоду на $s1%. Може бути накладена лише на одну ціль водночас." },
    { en = "Summons and dismisses your Lightforged Felcrusher.", ua = "Прикликає та відкликає вашого Загартованого Світлом сквернотрощителя." },
    { en = "Summons and dismisses your Highmountain Thunderhoof.", ua = "Прикликає та відкликає вашого Громокопита Високогір'я." },
    { en = "Summons and dismisses your Nightborne Manasaber.", ua = "Прикликає або відкликає вашого манасабельника нічнонароджених." },
    { en = "Engulf yourself in flames, $?a320364 [instantly causing $258921s1 $@spelldesc1224451 damage to enemies within $258921A1 yards and ][]radiating ${$258922s1*$d} $@spelldesc1224451 damage over $d.$?s320374[\n\n\n\n|cFFFFFFFFGenerates $<havocTalentFury> Fury over $d.|r][]$?(s212612 & !s320374)[\n\n\n\n|cFFFFFFFFGenerates $<havocFury> Fury.|r][]$?s212613[\n\n\n\n|cFFFFFFFFGenerates $<vengeFury> Fury over $d.|r][]", ua = "Огортаєте себе полум'ям, $?a320364 [миттєво завдаючи $258921s1 $@spelldesc1224451 шкоди ворогам у радіусі $258921A1 м і ][]випромінюючи ${$258922s1*$d} $@spelldesc1224451 шкоди протягом $d.$?s320374[\n\n\n\n|cFFFFFFFFГенерує $<havocTalentFury> люті протягом $d.|r][]$?(s212612 & !s320374)[\n\n\n\n|cFFFFFFFFГенерує $<havocFury> люті.|r][]$?s212613[\n\n\n\n|cFFFFFFFFГенерує $<vengeFury> люті протягом $d.|r][]" },
    { en = "Summons and dismisses your Starcursed Voidstrider.", ua = "Прикликає або відкликає вашого зорепроклятого ходака Порожнечі." },
    { en = "Summons and dismisses your Admiralty Stallion.", ua = "Прикликає або відкликає вашого жеребця адміралтейства." },
    { en = "Summons and dismisses Shu-Zen.", ua = "Прикликає або відкликає Шу-Зена." },
    { en = "Summons and dismisses a Green Marsh Hopper.", ua = "Прикликає або відкликає зеленого болотяного стрибунця." },
    { en = "Summons and dismisses your Storm's Wake Dapple Gray.", ua = "Прикликає або відкликає вашого сірого в яблуках коня Штормової Варти." },
    { en = "Summons and dismisses your Waycrest Smoky Black Charger.", ua = "Прикликає або відкликає вашого димно-чорного скакуна Вейкресту." },
    { en = "Summons and dismisses your Terrified Pack Mule.", ua = "Прикликає або відкликає вашого нажаханого в'ючного мула." },
    { en = "Summons and dismisses Goldenmane.", ua = "Прикликає або відкликає Золотогрива." },
    { en = "Transforms you into the Hivemind. Other members of your Hivemind may join with you. This is a flying mount.", ua = "Перетворює вас на Колективний Розум. Інші учасники вашого Колективного Розуму можуть приєднатися до вас. Це летюча їздова тварина." },
    { en = "Summons and dismisses your Vicious War Basilisk.", ua = "Прикликає або відкликає вашого лютого бойового василіска." },
    { en = "Summons and dismisses the Mecha-Mogul Mk2.", ua = "Прикликає або відкликає Меха-Магната Mk2." },
    { en = "Summons and dismisses your $@spellname262022.", ua = "Прикликає або відкликає вашого $@spellname262022." },
    { en = "Summons and dismisses your $@spellname262023.", ua = "Прикликає або відкликає вашого $@spellname262023." },
    { en = "Summons and dismisses your $@spellname262024.", ua = "Прикликає або відкликає вашого $@spellname262024." },
    { en = "Summons and dismisses your $@spellname262025.", ua = "Прикликає або відкликає вашого $@spellname262025." },
    { en = "Summons and dismisses your $@spellname262026.", ua = "Прикликає або відкликає вашого $@spellname262026." },
    { en = "Summons and dismisses your $@spellname262027.", ua = "Прикликає або відкликає вашого $@spellname262027." },
    { en = "Summons and dismisses your $@spellname262028.", ua = "Прикликає або відкликає вашого $@spellname262028." },
    { en = "The Hound bites the target's feet, reducing movement speed by $s1% for $d.", ua = "Гончак кусає ноги цілі, знижуючи її швидкість пересування на $s1% на $d." },
    { en = "The Worm spits acid at the target, slowing movement by $s1% for $d.", ua = "Черв'як плює кислотою в ціль, знижуючи її швидкість пересування на $s1% на $d." },
    { en = "Summons and dismisses your Zandalari Direhorn.", ua = "Прикликає або відкликає вашого зандаларського жахорога." },
    { en = "The Wolf bites the target's feet, reducing movement speed by $s1% for $d.", ua = "Вовк кусає ноги цілі, знижуючи її швидкість пересування на $s1% на $d." },
    { en = "The Basilisk stares at the target, reducing movement speed by $s1% for $d.", ua = "Василіск пильно дивиться на ціль, знижуючи її швидкість пересування на $s1% на $d." },
    { en = "The Bird of Prey claws at the target's feet, reducing movement speed by $s1% for $d.", ua = "Хижий птах дряпає кігтями ноги цілі, знижуючи її швидкість пересування на $s1% на $d." },
    { en = "The Hyena sinks its fangs into the target, infecting the target with Mortal Wounds.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Гієна вганяє ікла в ціль, уражаючи її Смертельними Ранами.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого зцілення, яке вона отримує, на $115804d." },
    { en = "The Raptor slashes deep into the target, causing Mortal Wounds.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Раптор глибоко роздирає ціль, завдаючи Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого зцілення, яке вона отримує, на $115804d." },
    { en = "The Rodent gnaws a gaping wound into the target, causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Гризун прогризає в цілі зяючу рану, накладаючи ефект Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого зцілення, яке вона отримує, на $115804d." },
    { en = "The Ravager tears into the enemy,  causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Спустошувач роздирає ворога,  спричиняючи ефект «Смертельні рани».\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого отриманого зцілення на $115804d." },
    { en = "The Wasp dives in and stings the target, causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Оса пікірує вниз і жалить ціль, накладаючи ефект Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого зцілення, яке вона отримує, на $115804d." },
    { en = "The Direhorn drives its horns into the target, causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Жахоріг вганяє роги в ціль, спричиняючи ефект «Смертельні рани».\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого отриманого зцілення на $115804d." },
    { en = "The Hydra bites the target with corrosive venom, causing the Mortal Wounds effect.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Гідра кусає ціль роз'їдаючою отрутою, накладаючи ефект Смертельних Ран.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні Рани|r\n\nТяжко ранить ціль, знижуючи дієвість будь-якого зцілення, яке вона отримує, на $115804d." },
    { en = "The Scalehide hardens its skin, reducing damage taken by $s1% for $d.", ua = "Лускошкір загартовує свою шкіру, знижуючи отримувану шкоду на $s1% на $d." },
    { en = "The Core Hound suddenly cools and hardens the magma on its skin, reducing damage taken by $s1% for $d.", ua = "Гончак Надр раптово охолоджується, і магма на його шкірі твердне, знижуючи отримувану шкоду на $s1% на $d." },
    { en = "The Mechanical contraption creates a personal defense matrix around itself, reducing damage taken by $s1% for $d.", ua = "Механічний пристрій створює навколо себе персональну захисну матрицю, знижуючи отримувану шкоду на $s1% на $d." },
    { en = "The Boar bristles its hide, reducing damage taken by $s1% for $d.", ua = "Вепр настовбурчує щетину, знижуючи отримувану шкоду на $s1% на $d." },
    { en = "The Dragonhawk takes on a defensive posture, increasing dodge chance by $s1% for $d.", ua = "Драконояструб займає захисну стійку, підвищуючи шанс ухилення на $s1% на $d." },
    { en = "The Cat heightens its senses, increasing dodge chance by $s1% for $d.", ua = "Кіт загострює чуття, збільшуючи шанс ухилення на $s1% протягом $d." },
    { en = "The Serpent takes on a defensive posture, increasing dodge chance by $s1% for $d.", ua = "Змій займає захисну стійку, підвищуючи шанс ухилення на $s1% на $d." },
    { en = "The Feathermane flaps wildly, flinging feathers into the air that distract its enemies, increasing dodge chance by $s1% for $d.", ua = "Пернатогрив несамовито махає крилами, здіймаючи в повітря пір'я, яке відвертає увагу ворогів, і підвищує шанс ухилення на $s1% на $d." },
    { en = "When falling below $s2% health, the Gruffhorn will shrug off attacks, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, Буркоріг струшує із себе атаки, знижуючи вхідну шкоду на $160058s1% на $160058d.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $s3 с." },
    { en = "When falling below $s2% health, the Bear's fur will thicken, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, хутро Ведмедя густішає, знижуючи вхідну шкоду на $160058s1% на $160058d.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $s3 с." },
    { en = "When falling below $s2% health, the Gorilla will shrug off attacks, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, Горила струшує із себе атаки, знижуючи вхідну шкоду на $160058s1% на $160058d.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $s3 с." },
    { en = "Right Click to summon and dismiss Francois.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Франсуа." },
    { en = "When falling below $s2% health, the Ox will shrug off attacks, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я падає нижче $s2%, Бик струшує із себе атаки, знижуючи вхідну шкоду на $160058s1% на $160058d.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $s3 с." },
    { en = "Summons and dismisses your Mighty Caravan Brutosaur.", ua = "Прикликає або відкликає вашого могутнього караванного брутозавра." },
    { en = "The Wind Serpent takes on a defensive posture, increasing dodge chance by $s1% for $d.", ua = "Вітровий Змій займає захисну стійку, підвищуючи шанс ухилення на $s1% на $d." },
    { en = "Encases the Voidwalker in shadow energy, reducing physical damage taken by $s1%.", ua = "Огортає блукача Порожнечі тіньовою енергією, знижуючи отримувану фізичну шкоду на $s1%." },
    { en = "Summons and dismisses your Tomb Stalker.", ua = "Прикликає або відкликає вашого гробничого скрадача." },
    { en = "Summons and dismisses Kua'fon.", ua = "Прикликає або відкликає Куа'фона." },
    { en = "Summons and dismisses your Mag'har Direwolf.", ua = "Прикликає або відкликає вашого маг'харського жахововка." },
    { en = "When used, your pet will miraculously return to life with full health.", ua = "При використанні ваш улюбленець чудесним чином повертається до життя з повним здоров'ям." },
    { en = "Transforms the enemy into a skeletal hatchling for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на скелетне дитинча на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Summons and dismisses your Vicious War Clefthoof.", ua = "Прикликає або відкликає вашого лютого бойового клефтгуфа." },
    { en = "Summons a Darkforge Ram, which serves as a mount.", ua = "Прикликає Темнокованого Барана, який слугує їздовою твариною." },
    { en = "Summons a Dawnforge Ram, which serves as a mount.", ua = "Прикликає Світанковокованого Барана, який слугує їздовою твариною." },
    { en = "Summons and dismisses your Dark Iron Core Hound.", ua = "Прикликає або відкликає вашого Гончака Надр Темного Заліза." },
    { en = "Summons and dismisses your Undercity Plaguebat.", ua = "Прикликає або відкликає вашого чумного кажана Андерсіті." },
    { en = "Summons and dismisses your Vicious War Riverbeast.", ua = "Прикликає або відкликає вашу люту бойову річкову звірюку." },
    { en = "Commands your pet to perform its unique ability. This ability will transform based on the specialization of your active pet. \n\n\n\nFerocity: $@spellname264667\n\nTenacity: $@spellname388035\n\nCunning: $@spellname53271", ua = "Наказує улюбленцеві застосувати його унікальне вміння. Це вміння змінюється залежно від спеціалізації твого активного улюбленця. \n\n\n\nЛютість: $@spellname264667\n\nЗавзятість: $@spellname388035\n\nХитрість: $@spellname53271" },
    { en = "Summons and dismisses The Dreadwake.", ua = "Прикликає або відкликає Жахослід." },
    { en = "Right Click to summon and dismiss Whomper.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Бухкала." },
    { en = "Right Click to summon and dismiss Cap'n Crackers.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Капітана Крекерса." },
    { en = "Right Click to summon and dismiss your cobra.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашу кобру." },
    { en = "Right Click to summon and dismiss your filthy slime.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваш брудний слиз." },
