    { en = "Summons and dismisses a Yellow Marsh Hopper.", ua = "Прикликає чи відпускає жовту болотяну стрибунку." },
    { en = "Right Click to summon and dismiss the Void Jelly.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити медузу Порожнечі." },
    { en = "Summons and dismisses a rideable Saltwater Seahorse. This mount is a zippy swimmer.\n\n\n\nDue to his capricious nature, swim speed is not affected by effects that increase or decrease mount speed.", ua = "Прикликає чи відпускає їздового морського коника. Ця їздова тварина - моторний плавець.\n\n\n\nЧерез її примхливу вдачу на швидкість плавання не впливають ефекти, що збільшують чи зменшують швидкість їздової тварини." },
    { en = "Summons and dismisses your Stonehide Elderhorn.", ua = "Прикликає чи відпускає вашого камінношкірого старорога." },
    { en = "The blood beast belches blood at the target, reducing movement speed by $s1% for $d.", ua = "Кровожерний звір вивергає кров на ціль, зменшуючи швидкість пересування на $s1% на $d." },
    { en = "Summons and dismisses your G.M.O.D. This mount changes depending on your Riding skill and location.", ua = "Прикликає чи відпускає ваш G.M.O.D. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місця перебування." },
    { en = "Summons and dismisses your Dazar'alor Windreaver. This mount changes depending on your Riding skill and location.", ua = "Прикликає чи відпускає вашого дазар'алорського вітрожнеця. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місця перебування." },
    { en = "Summons and dismisses your Glacial Tidestorm. This mount changes depending on your riding skill and location.", ua = "Прикликає чи відпускає вашу льодовикову припливну бурю. Ця їздова тварина змінюється залежно від вашої навички верхової їзди та місця перебування." },
    { en = "Summons and dismisses Bruce.", ua = "Прикликає чи відпускає Брюса." },
    { en = "Summons and dismisses this mount.  This mount changes depending on your riding skill and location.", ua = "Прикликає чи відпускає цю їздову тварину. Вона змінюється залежно від вашої навички верхової їзди та місця перебування." },
    { en = "Summons and dismisses this mount. This mount changes depending on your riding skill and location.", ua = "Прикликає та відкликає цю їздову тварину. Ця їздова тварина змінюється залежно від вашого вміння їзди та місцеперебування." },
    { en = "Summons a Crusader's Direhorn, which serves as a mount.", ua = "Викликає люторога хрестоносця, що служить їздовою твариною." },
    { en = "Right Click to summon and dismiss your Slimy Sea Slug.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого слизького морського слимака." },
    { en = "Right Click to summon and dismiss your Slimy Otter.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашу слизьку видру." },
    { en = "Right Click to summon and dismiss your Slimy Octopode.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого слизького восьминога." },
    { en = "Right Click to summon and dismiss your Slimy Fish.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашу слизьку рибу." },
    { en = "Right Click to summon and dismiss your Slimy Eel.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого слизького вугра." },
    { en = "Right Click to summon and dismiss your Slimy Darkhunter.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого слизького темного мисливця." },
    { en = "Right Click to summon and dismiss your Slimy Hermit Crab.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого слизького рака-самітника." },
    { en = "Allows one-hand and off-hand weapons to be equipped in the off-hand.", ua = "Дозволяє споряджати одноручну зброю та зброю для другої руки в другу руку." },
    { en = "Summons and dismisses this mount. Can only be used underwater.", ua = "Прикликає та відкликає цю їздову тварину. Можна використати лише під водою." },
    { en = "Right Click to summon and dismiss your ghostly whelpling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати ваше примарне драконятко." },
    { en = "Right Click to summon and dismiss the Minimancer.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Мінімансера." },
    { en = "Wend through the shadows, appearing at the targeted location.", ua = "Прослизаєте крізь тіні й з'являєтеся в цільовому місці." },
    { en = "Right Click to summon and dismiss your adventurous hopling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого завзятого стрибунця." },
    { en = "Instantly cast Holy Shock, Avenger's Shield, or Judgment on up to $s1 targets within $A2 yds (based on your current specialization).$?c3[\n\n\n\nDivine Toll's Judgment deals $326011s1% increased damage.][]", ua = "Миттєво застосовує Святий шок, Щит месника або Правосуддя на щонайбільше $s1 цілей у межах $A2 м (залежно від вашої поточної спеціалізації).$?c3[\n\n\n\nПравосуддя від Божественного подзвону завдає на $326011s1% більше шкоди.][]" },
    { en = "Place a Kyrian Sigil at the target location that activates after $d.\n\n\n\nDetonates to deal $307046s1 $@spelldesc395039 damage and shatter up to $s3 Lesser Soul Fragments from enemies affected by the sigil. Deals reduced damage beyond $s1 targets.", ua = "Розміщує в цільовому місці кіріанський знак, що активується через $d.\n\n\n\nДетонує, завдаючи $307046s1 шкоди $@spelldesc395039 і вибиваючи до $s3 малих фрагментів душі з ворогів, уражених знаком. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "Conjure a radiant spark that causes $s1 Arcane damage instantly, and an additional $o2 damage over $d.\n\n\n\nThe target takes $307454s1% increased damage from your direct damage spells, stacking each time they are struck. This effect ends after $307454u spells.", ua = "Створює сяйливу іскру, що миттєво завдає $s1 арканної шкоди та додатково $o2 шкоди протягом $d.\n\n\n\nЦіль отримує на $307454s1% більше шкоди від ваших заклять прямої шкоди; ефект накопичується щоразу, коли ціль уражено. Цей ефект завершується після $307454u заклять." },
    { en = "Throw a Kyrian spear at the target location, dealing $307871s1 Arcane damage instantly and an additional $307871o4 damage over $307954d. Deals reduced damage beyond $<cap> targets.\n\n\n\nEnemies hit are tethered to Spear of Bastion's location for the duration.\n\n\n\n|cFFFFFFFFGenerates $/10;307871s3 Rage.|r", ua = "Кидає кіріанський спис у цільове місце, миттєво завдаючи $307871s1 арканної шкоди та додатково $307871o4 шкоди протягом $307954d. Завдає зменшеної шкоди понад $<cap> цілей.\n\n\n\nУражені вороги на час дії прив'язуються до місця Списа Бастіону.\n\n\n\n|cFFFFFFFFГенерує $/10;307871s3 люті.|r" },
    { en = "Summons or dismisses this companion.", ua = "Прикликає чи відкликає цього супутника." },
    { en = "Fire a resonating arrow to the target location that deals $308495s1 Arcane damage to any enemy in the area, and fill the area with echoing anima for $308495d. The effect causes your attacks to ignore line of sight to enemies in the area, and you have $308498s1% increased critical strike chance against them. \n\n\n\nLeaving the area of echoing anima will still allow the hunter to ignore line of sight towards the enemy for ${$308495s3/1000} sec.", ua = "Випускає в цільове місце резонансну стрілу, що завдає $308495s1 арканної шкоди будь-якому ворогу в зоні та наповнює зону відлунною анімою на $308495d. Завдяки цьому ваші атаки ігнорують лінію прямої видимості до ворогів у зоні, а ваш шанс критичного удару по них збільшено на $308498s1%. \n\n\n\nНавіть покинувши зону відлунної аніми, мисливець ще ${$308495s3/1000} сек. може ігнорувати лінію видимості до ворога." },
    { en = "Transforms the enemy into a living honey for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на живий мед на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Turn into $?a333206[a Toad]?a326215[a Wyvern]?a326212[a Gryphon]?a326209[a Hippogryph]?a326207[a Wolfhawk]?a326204[a Feathered Drake]?a326202[a Wolf]?a326200[a Moose]?a326197[a Bear]?a326195[a Raptor]?a326191[a Shadowstalker]?a326184[a Stag]?a326181[a Dragon Turtle]?a326168[a Tiger]?a326165[a Lion]?a326161[a Crane]?a326157[a Shrieker]?a326153[a Horned Horse]?a326152[a Moth]?a349209[a Direhorn]?a349213[a Hippo]?a349215[a Kodo]?a249217[a Mammoth]?a349219[a Saurolisk]?a349221[a Shoveltusk]?a349222[a Spider]?a349225[a Yak]?a321080[a Runestag][a Vulpin], teleporting $324701A1 yds forward and increasing your movement speed by $s3%. You may reactivate Soulshape every few sec to teleport again.$?a137010[\n\n\n\nIncreases armor by $344402s2% and Stamina by $344402s1%.][]\n\n\n\nLasts $d, or indefinitely while in a rest area.", ua = "Перетворює вас на $?a333206[жабу]?a326215[віверну]?a326212[грифона]?a326209[гіпогрифа]?a326207[вовкояструба]?a326204[пернатого дрейка]?a326202[вовка]?a326200[лося]?a326197[ведмедя]?a326195[раптора]?a326191[тіньового переслідувача]?a326184[оленя]?a326181[дракона-черепаху]?a326168[тигра]?a326165[лева]?a326161[журавля]?a326157[верескуна]?a326153[рогатого коня]?a326152[метелика]?a349209[жахорога]?a349213[бегемота]?a349215[кодо]?a249217[мамонта]?a349219[сауроліска]?a349221[лопатоікла]?a349222[павука]?a349225[яка]?a321080[рунного оленя][вульпіна], телепортуючи вас на $324701A1 м уперед і збільшуючи вашу швидкість руху на $s3%. Ви можете повторно активувати «Душевну подобу» кожні кілька секунд, щоб телепортуватися знову.$?a137010[\n\n\n\nЗбільшує броню на $344402s2% і витривалість на $344402s1%.][]\n\n\n\nТриває $d або необмежено, поки ви в зоні відпочинку." },
    { en = "For the next $d, your Mastery is increased by $?c1[${$117906bc1*$s1}]?c2[${$117907bc1*$s1}][${$115636bc1*$s1}.1]%. Additionally, $?a137025[Rising Sun Kick reduces Chi costs by $311054s1 for $311054d, and Blackout Kick reduces the cooldown of affected abilities by an additional ${$s8/1000} sec.][]$?a137023 [Keg Smash cooldown is reset instantly and enemies hit by Keg Smash take $312106s1% increased damage from you for $312106d, stacking up to $312106u times.][]$?a137024[Essence Font cooldown is reset instantly and heals up to $311123s2 nearby allies for $311123s1 health on channel start and end.][]", ua = "Протягом наступних $d ваша майстерність збільшена на $?c1[${$117906bc1*$s1}]?c2[${$117907bc1*$s1}][${$115636bc1*$s1}.1]%. Крім того, $?a137025[«Удар висхідного сонця» зменшує витрати ці на $311054s1 на $311054d, а «Затьмарливий удар» додатково зменшує перезарядження уражених здібностей на ${$s8/1000} сек.][]$?a137023 [перезарядження «Удару барилом» миттєво скидається, а вороги, уражені «Ударом барилом», отримують від вас на $312106s1% більше шкоди протягом $312106d; ефект накопичується до $312106u разів.][]$?a137024[перезарядження «Джерела есенції» миттєво скидається, а на початку й наприкінці підтримання воно зцілює до $311123s2 союзників поблизу на $311123s1 здоров'я.][]" },
    { en = "A heavy mist surrounds you for $d, increasing your Dodge by $s2%. \n\n\n\nDeals $311730s1 Shadow damage every $t1 sec to enemies within $311730A1 yds. Every time it deals damage you gain ${$312546s1/10} Runic Power, up to a maximum of ${$312546s1/10*$s3} Runic Power. Deals reduced damage beyond $s5 targets.", ua = "Густий туман огортає вас на $d, збільшуючи ваше ухилення на $s2%. \n\n\n\nЗавдає $311730s1 шкоди Тіні щосекунди ($t1) ворогам у радіусі $311730A1 м. Щоразу, коли він завдає шкоди, ви отримуєте ${$312546s1/10} рунічної сили, але не більше ${$312546s1/10*$s3} рунічної сили. Завдає зменшеної шкоди понад $s5 цілей." },
    { en = "Admonish your target for their past transgressions, reducing the damage they deal to you by $s2% and dealing $o Arcane damage over $d.\n\n\n\nWhile Shackle the Unworthy is active on an enemy, your direct-damage attacks that spend runes have a $s5% chance to spread Shackle the Unworthy to a nearby enemy.", ua = "Картаєте ціль за минулі провини, зменшуючи шкоду, яку вона вам завдає, на $s2% і завдаючи $o арканної шкоди протягом $d.\n\n\n\nПоки «Окови негідного» діють на ворога, ваші атаки прямої шкоди, що витрачають руни, мають $s5% шансу поширити «Окови негідного» на ворога поблизу." },
    { en = "Deal $s1 Arcane damage instantly, and $o2 over $d. If the enemy dies while affected by Scouring Tithe, you generate $?a137043[${$s3/10}]?a137044[${$s4/10}][${$s5/10}] Soul $LShard:Shards;. If they survive, Scouring Tithe's cooldown is refreshed.", ua = "Миттєво завдає $s1 арканної шкоди та $o2 протягом $d. Якщо ворог гине під дією «Спустошливої данини», ви отримуєте $?a137043[${$s3/10}]?a137044[${$s4/10}][${$s5/10}] $LфрагментДуші:фрагментиДуш;. Якщо він виживає, перезарядження «Спустошливої данини» скидається." },
    { en = "Draw power from the ground beneath, dealing ${$325130s1*$d/$t} Nature damage over $d to enemies within $325130A1 yds. \n\n\n\nWhile channeling, your Mage ability cooldowns are reduced by ${-$s2/1000*$d/$t} sec over $d.", ua = "Черпаєте силу із землі під ногами, завдаючи ${$325130s1*$d/$t} шкоди Природи протягом $d ворогам у радіусі $325130A1 м. \n\n\n\nПід час підтримання перезарядження ваших здібностей мага зменшується на ${-$s2/1000*$d/$t} сек. протягом $d." },
    { en = "Conjure $n mirrors to torment the enemy for $d. Whenever the target attacks, casts a spell, or uses an ability, a mirror is consumed to inflict $320035s1 Shadow damage and their movement and cast speed are slowed by $320035s3%. This effect cannot be triggered more often than once per $345977d.\n\n\n\nThe final mirror will instead inflict $317589s1 Shadow damage to the enemy, Rooting and Silencing them for $317589d.\n\n\n\nWhenever a mirror is consumed $?c1[you gain Clearcasting][]$?c2[your Fire Blast cooldown is reduced by $s2 sec][]$?c3[you gain Brain Freeze][].", ua = "Створює $n дзеркал, що мучать ворога протягом $d. Щоразу, коли ціль атакує, творить закляття чи використовує здібність, одне дзеркало витрачається, завдаючи $320035s1 шкоди Тіні та сповільнюючи її рух і швидкість творення на $320035s3%. Цей ефект не може спрацьовувати частіше, ніж раз на $345977d.\n\n\n\nОстаннє дзеркало натомість завдає ворогу $317589s1 шкоди Тіні, знерухомлюючи й німуючи його на $317589d.\n\n\n\nЩоразу, коли дзеркало витрачається, $?c1[ви отримуєте «Ясновидіння»][]$?c2[перезарядження вашого «Вогняного вибуху» зменшується на $s2 сек.][]$?c3[ви отримуєте «Заморозку розуму»][]." },
    { en = "Learn Death's Due, replacing Death and Decay.", ua = "Вивчає «Належне смерті», що замінює «Смерть і тлін»." },
    { en = "Sprout an additional limb, dealing ${$323798s1*13} Shadow damage over $d to all nearby enemies. Deals reduced damage beyond $s5 targets. Every $t1 sec, an enemy is pulled to your location if they are further than $323710s3 yds from you. The same enemy can only be pulled once every $323710d.\n\n\n\nGain $?a137008[$s3 Bone Shield charges][]$?a137006[Rime][]$?a137007[Runic Corruption][] instantly, and again every $?a353447[${$s4-$353447s2}][$s4] sec.", ua = "Вирощує додаткову кінцівку, що завдає ${$323798s1*13} шкоди Тінню протягом $d усім ворогам поблизу. Завдає зменшеної шкоди понад $s5 цілей. Кожні $t1 с ворога притягує до твого розташування, якщо він далі ніж $323710s3 ярдів від тебе. Того самого ворога можна притягнути лише раз на $323710d.\n\n\n\nОтримуєш $?a137008[$s3 заряди Кістяного щита][]$?a137006[Паморозь][]$?a137007[Руническе зіпсуття][] миттєво, і знову кожні $?a353447[${$s4-$353447s2}][$s4] с." },
    { en = "Finishing move that consumes combo points to increase attack speed by $s1%. Lasts longer per combo point.\n\n   1 point  : 12 seconds\n\n   2 points: 18 seconds\n\n   3 points: 24 seconds\n\n   4 points: 30 seconds\n\n   5 points: 36 seconds$?s193531|((s394320|s394321|s457512)&!s193531)[\n\n   6 points: 42 seconds][]$?s193531&(s394320|s394321|s457512)[\n\n   7 points: 48 seconds][]", ua = "Завершальний прийом, що споживає очки комбо, аби підвищити швидкість атаки на $s1%. Триває довше за кожне очко комбо.\n\n   1 очко  : 12 секунд\n\n   2 очки: 18 секунд\n\n   3 очки: 24 секунди\n\n   4 очки: 30 секунд\n\n   5 очок: 36 секунд$?s193531|((s394320|s394321|s457512)&!s193531)[\n\n   6 очок: 42 секунди][]$?s193531&(s394320|s394321|s457512)[\n\n   7 очок: 48 секунд][]" },
    { en = "Coats your weapons with a Lethal Poison that lasts for $d. Each strike has a $h% chance of poisoning the enemy which instantly inflicts $315585s1 Nature damage.", ua = "Вкриває твою зброю летальною отрутою, що тримається $d. Кожен удар має $h% шансу отруїти ворога, миттєво завдавши $315585s1 шкоди природою." },
    { en = "Strike the target for $s1 Physical damage. This attack cannot be dodged, blocked, or parried.", ua = "Б'є ціль, завдаючи $s1 фізичної шкоди. Від цієї атаки не можна ухилитися, її не можна заблокувати чи парирувати." },
    { en = "Teaches you how to summon this companion.", ua = "Навчає вас прикликати цього супутника." },
    { en = "Hallow the target area for $d. Enemies in the area suffer up to ${$317221s1*$d/$t1} Shadow damage, and allies are healed for up to ${$317223s1*$d/$t1}, reduced if there are more than $s2 targets.\n\n\n\nWithin the Hallow, you may use Hammer of Wrath on any target, and its damage is increased by $330382s2%.", ua = "Освячує цільову зону на $d. Вороги в зоні зазнають до ${$317221s1*$d/$t1} шкоди Тіні, а союзники зцілюються на ${$317223s1*$d/$t1}; значення зменшується, якщо цілей понад $s2.\n\n\n\nУ межах освяченої зони ви можете застосовувати «Молот гніву» до будь-якої цілі, і його шкода збільшена на $330382s2%." },
    { en = "Brand an enemy with the mark of the Venthyr, reducing their melee attack speed by $s3%, their casting speed by $s2%, and inflicting $o1 Shadow damage over $d.\n\n\n\nActivating Metamorphosis applies Sinful Brand to all nearby enemies.", ua = "Таврує ворога знаком вентирів, зменшуючи його швидкість атак ближнього бою на $s3%, швидкість творення на $s2% і завдаючи $o1 шкоди Тіні протягом $d.\n\n\n\nАктивація «Метаморфози» накладає «Грішне тавро» на всіх ворогів поблизу." },
    { en = "Learn Condemn, replacing Execute. Condemn deals Shadow damage, can be used on enemies who are above 80% health or below 20% health, and weakens the target preventing some of the damage they would deal to you.", ua = "Вивчає «Засудження», що замінює «Страту». «Засудження» завдає шкоди Тіні, його можна застосовувати до ворогів із понад 80% або менш ніж 20% здоров'я, і воно послаблює ціль, відвертаючи частину шкоди, яку вона б вам завдала." },
    { en = "Cooldown reduced by ${$s1/-1000} sec.", ua = "Перезарядження скорочено на ${$s1/-1000} сек." },
    { en = "Duration increased by $s1 sec.", ua = "Тривалість збільшено на $s1 сек." },
    { en = "Cooldown reduced by ${-$s1/1000} sec.", ua = "Перезарядження скорочено на ${-$s1/1000} сек." },
    { en = "Reduces the cast time of Lightning Bolt by ${$m1/-1000}.1 sec.", ua = "Зменшує час творення «Блискавки» на ${$m1/-1000}.1 сек." },
    { en = "Heals for an additional $s1% of maximum health.", ua = "Зцілює додатково на $s1% від максимального здоров'я." },
    { en = "Blasts the enemy for $s1 Fire damage.$?a231568[\n\n\n\n|cFFFFFFFFFire:|r Always deals a critical strike.][]", ua = "Уражає ворога, завдаючи $s1 вогняної шкоди.$?a231568[\n\n\n\n|cFFFFFFFFВогонь:|r Завжди завдає критичного удару.][]" },
    { en = "Immolation Aura instantly causes $258921s1 Fire damage to enemies within $258921A1 yards.", ua = "«Аура спалення» миттєво завдає $258921s1 вогняної шкоди ворогам у радіусі $258921A1 м." },
    { en = "Reduces the cooldown of Spectral Sight by ${$abs($s0/1000)} sec.", ua = "Скорочує перезарядження «Спектрального зору» на ${$abs($s0/1000)} сек." },
    { en = "Send a wave of anima at the target, which then jumps to additional nearby targets. Deals $320752s1 Shadow damage to up to 5 enemies, and restores $320751s1 health to up to 5 allies.\n\n\n\nFor each target critically struck, the cooldown of Chain Harvest is reduced by 5 sec.$?s168534[\n\n\n\nGenerates $368583s1 Maelstrom per target damaged or healed.][]", ua = "Посилає в ціль хвилю аніми, що потім перестрибує на додаткові цілі поблизу. Завдає $320752s1 шкоди Тіні до 5 ворогам і відновлює $320751s1 здоров'я до 5 союзникам.\n\n\n\nЗа кожну ціль, уражену критично, перезарядження «Ланцюгового жнива» зменшується на 5 сек.$?s168534[\n\n\n\nГенерує $368583s1 виру за кожну ціль, якій завдано шкоди чи яку зцілено.][]" },
    { en = "Consume up to $s1 charges of Earth Shield to heal up to $s2 allies near your Earth Shield target for ${$320747m1/$m1*(1+$@versadmg)} per charge consumed.", ua = "Споживає до $s1 зарядів Земляного щита, зцілюючи до $s2 союзників поблизу цілі вашого Земляного щита на ${$320747m1/$m1*(1+$@versadmg)} за кожен спожитий заряд." },
    { en = "Transforms the enemy into a mawrat, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Undead, Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на пельгура, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на нежить, тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "Call forth a cloud of chaotic anima that travels to the target enemy, dealing $322167s1 Shadow damage to enemies in its path. When the anima reaches the target it explodes, inflicting either Curse of Weakness or Curse of Tongues, and dealing $322170o1 Shadow damage over $322170d to all nearby enemies.", ua = "Прикликає хмару хаотичної аніми, що рушає до цільового ворога, завдаючи $322167s1 шкоди Тіні ворогам на своєму шляху. Досягнувши цілі, аніма вибухає, накладаючи «Прокляття слабкості» або «Прокляття мов» і завдаючи $322170o1 шкоди Тіні протягом $322170d усім ворогам поблизу." },
    { en = "Expel negative chi from your body, healing for $s1 and dealing $s2% of the amount healed as Nature damage to an enemy within $115129A1 yards.$?s322102[\n\n\n\nDraws in the positive chi of all your Healing Spheres to increase the healing of Expel Harm.][]$?s342928[\n\n\n\n|cFFFFFFFFGenerates ${$s3+$342928s2} Chi.][]", ua = "Виганяє негативне ці з твого тіла, зцілюючи на $s1 і завдаючи $s2% від зціленої кількості як шкоди Природою ворогу в межах $115129A1 ярдів.$?s322102[\n\n\n\nВтягує позитивне ці всіх твоїх зцілющих сфер, щоб посилити зцілення Вигнання шкоди.][]$?s342928[\n\n\n\n|cFFFFFFFFГенерує ${$s3+$342928s2} ці.][]" },
    { en = "You exploit the enemy target's weakest point, instantly dealing damage equal to $s4% of your maximum health to $?s322113[creatures if they have less health than you.][them.\n\n\n\nOnly usable on creatures that have less health than you]$?s322113[ Deals damage equal to $s3% of your maximum health against players and stronger creatures under $s2% health.][.]$?s325095[\n\n\n\nReduces delayed Stagger damage by $325095s1% of damage dealt.]?s325215[\n\n\n\nSpawns $325215s1 Chi Spheres, granting 1 Chi when you walk through them.]?s344360[\n\n\n\nIncreases the Monk's Physical damage by $344361s1% for $344361d.][]", ua = "Ти використовуєш найвразливішу точку ворожої цілі, миттєво завдаючи шкоди, рівної $s4% твого максимального здоров'я, $?s322113[істотам, якщо в них менше здоров'я, ніж у тебе.][їй.\n\n\n\nЗастосовується лише на істотах, у яких менше здоров'я, ніж у тебе]$?s322113[ Завдає шкоди, рівної $s3% твого максимального здоров'я, гравцям і сильнішим істотам зі здоров'ям нижче $s2%.][.]$?s325095[\n\n\n\nЗменшує відкладену шкоду Хитання на $325095s1% від завданої шкоди.]?s325215[\n\n\n\nСтворює $325215s1 сфер ці, що дають 1 ці, коли ти проходиш крізь них.]?s344360[\n\n\n\nЗбільшує фізичну шкоду монаха на $344361s1% на $344361d.][]" },
    { en = "For $d, Druid spells you cast increase your damage and healing by $s1%, and haste by $s3%, stacking.\n\n\n\nIf you spend ${$s9/10} sec idle, the Frenzy overcomes you, consuming $s3% of your health per stack, stunning you for $323557d, and ending.", ua = "Протягом $d закляття друїда, які ви творите, збільшують вашу шкоду й зцілення на $s1%, а поспіх — на $s3%; ефект накопичується.\n\n\n\nЯкщо ви ${$s9/10} сек. лишаєтеся бездіяльними, шал поглинає вас, поглинаючи $s3% вашого здоров'я за кожен заряд, оглушуючи вас на $323557d, і завершується." },
    { en = "Deal $s1 Arcane damage to an enemy, extracting their anima to Animacharge a combo point for $323558d.\n\n\n\nDamaging finishing moves that consume the same number of combo points as your Animacharge function as if they consumed $s2 combo points.\n\n\n\n|cFFFFFFFFAwards $s3 combo $lpoint:points;.|r", ua = "Завдає ворогові $s1 од. арканної шкоди, видобуваючи його аніму, щоб зарядити анімою серійний удар на $323558d.\n\n\n\nДобивальні удари, що завдають шкоди та витрачають таку саму кількість серійних ударів, як ваш Анімозаряд, діють так, ніби витрачають $s2 серійних удари.\n\n\n\n|cFFFFFFFFНадає $s3 $lсерійний удар:серійні удари:серійних ударів;.|r" },
    { en = "Charge to your target, striking them for $323802s1 $@spelldesc395042 damage, rooting them in place for $323996d and inflicting $345335o1 $@spelldesc395042 damage over $345335d to up to $345396s2 enemies in your path. \n\n\n\nThe pursuit invigorates your soul, healing you for $?c1[$345422s1%][$345422s2%] of the damage you deal to your Hunt target for $323802d.", ua = "Кидається до твоєї цілі, б'ючи її на $323802s1 шкоди $@spelldesc395042, прикорінюючи її на місці на $323996d і завдаючи $345335o1 шкоди $@spelldesc395042 протягом $345335d до $345396s2 ворогам на твоєму шляху. \n\n\n\nПереслідування бадьорить твою душу, зцілюючи тебе на $?c1[$345422s1%][$345422s2%] від шкоди, яку ти завдаєш цілі свого Полювання, протягом $323802d." },
    { en = "Lash the target for $s1 Shadow damage, causing each combo point spent within $d to lash for an additional $345316s1. Dealing damage with Flagellation increases your Haste by $s2%, persisting $345569d after their torment fades.", ua = "Шмагає ціль, завдаючи $s1 шкоди Тіні, через що кожне очко комбо, витрачене протягом $d, додатково шмагає на $345316s1. Завдання шкоди «Бичуванням» збільшує ваш поспіх на $s2%, який триває ще $345569d після того, як муки цілі згасають." },
    { en = "Assault an enemy's mind, dealing ${$s1*$m3/100} Shadow damage and briefly reversing their perception of reality.\n\n\n\n$?c3[For $d, the next $<damage> damage they deal will heal their target, and the next $<healing> healing they deal will damage their target.\n\n\n\n|cFFFFFFFFReversed damage and healing generate up to ${$323706s2*2} Insanity.|r]\n\n][For $d, the next $<damage> damage they deal will heal their target, and the next $<healing> healing they deal will damage their target.\n\n\n\n|cFFFFFFFFReversed damage and healing restore up to ${$323706s3*2}% mana.|r]", ua = "Атакує розум ворога, завдаючи ${$s1*$m3/100} шкоди Тіні й на коротку мить обертаючи його сприйняття реальності.\n\n\n\n$?c3[Протягом $d наступні $<damage> шкоди, які він завдасть, зцілять його ціль, а наступні $<healing> зцілення, які він надасть, завдадуть шкоди його цілі.\n\n\n\n|cFFFFFFFFОбернені шкода й зцілення генерують до ${$323706s2*2} безумства.|r]\n\n][Протягом $d наступні $<damage> шкоди, які він завдасть, зцілять його ціль, а наступні $<healing> зцілення, які він надасть, завдадуть шкоди його цілі.\n\n\n\n|cFFFFFFFFОбернені шкода й зцілення відновлюють до ${$323706s3*2}% мани.|r]" },
    { en = "Call upon the Night Fae for an eruption of energy, channeling a rapid flurry of $s2 Druid spells and abilities over $d.\n\n\n\nYou will cast $?a24858|a197625[Starsurge, Starfall,]?a768[Ferocious Bite, Shred, Tiger's Fury,]?a5487[Mangle, Ironfur,][Wild Growth, Swiftmend,] Moonfire, Wrath, Regrowth, Rejuvenation, Rake, and Thrash on appropriate nearby targets, favoring your current shapeshift form.", ua = "Клич Нічних Фей для виверження енергії, підтримуючи стрімкий шквал із $s2 заклять і здібностей друїда протягом $d.\n\n\n\nТи сотвориш $?a24858|a197625[Зоряний вир, Зорепад,]?a768[Лютий укус, Роздирання, Лють тигра,]?a5487[Калічення, Залізна шкура,][Дикий ріст, Швидке зцілення,] Місячний вогонь, Гнів, Відрощення, Омолодження, Дряпання і Молотіння на відповідні цілі поблизу, віддаючи перевагу твоїй поточній звіриній подобі." },
    { en = "Brandish the Conqueror's Banner, granting $s1 Mastery and $s2% increased movement speed to you and your $325862s6 nearest allies, and preventing movement speed from being reduced below $s3%. Lasts $d.\n\n\n\n|cFFFFFFFFGenerates $<rage> Rage per sec.|r", ua = "Здіймає Прапор завойовника, надаючи $s1 майстерності та +$s2% швидкості руху вам і вашим $325862s6 найближчим союзникам, а також не даючи швидкості руху впасти нижче $s3%. Триває $d.\n\n\n\n|cFFFFFFFFГенерує $<rage> люті за секунду.|r" },
    { en = "Fire a shot at your enemy, dealing $s3 Shadow damage and then causing them to bleed for $o1 Shadow damage over $d. Each time Flayed Shot deals damage, you have a $s2% chance to gain Flayer's Mark, causing your next Kill Shot to be free, usable on any target regardless of their current health, and deal $324156s3% increased damage.", ua = "Стріляє у ворога, завдаючи $s3 шкоди Тіні, а потім спричиняючи кровотечу на $o1 шкоди Тіні протягом $d. Щоразу, коли «Білуючий постріл» завдає шкоди, ви маєте $s2% шансу отримати «Тавро білувальника», завдяки чому ваш наступний «Смертельний постріл» стає безкоштовним, застосовним до будь-якої цілі незалежно від її поточного здоров'я та завдає на $324156s3% більше шкоди." },
    { en = "Transform into a powerful skeletal mage for $d. \n\n\n\nWhile in the form of a skeletal mage, your Frostbolt, Fireball, and Arcane Blast hit up to $s4 enemies near your target and your spell damage is increased by $s2%.", ua = "Перетворює вас на могутнього скелета-мага на $d. \n\n\n\nУ подобі скелета-мага ваші «Крижана стріла», «Вогняна куля» та «Арканний вибух» уражають до $s4 ворогів поблизу вашої цілі, а шкода ваших заклять збільшена на $s2%." },
    { en = "Summon a totem at the target location for $d. Your next $s2 damage spells or abilities will cause the totem to radiate $324520s1 Arcane damage to up to $324520I enemies near the totem, and your next $s4 healing spells will heal up to $s6 allies near the totem for $324522s1 health.\n\n\n\nCasting this ability again while the totem is active will relocate the totem.", ua = "Прикликає тотем у цільовому місці на $d. Ваші наступні $s2 заклять чи здібностей шкоди змусять тотем випромінювати $324520s1 арканної шкоди до $324520I ворогам біля тотема, а ваші наступні $s4 заклять зцілення зцілять до $s6 союзників біля тотема на $324522s1 здоров'я.\n\n\n\nПовторне застосування цієї здібності, поки тотем активний, перемістить його." },
    { en = "Form a shield of flesh and bone over $d that absorbs damage equal to $s1% of your maximum health for $324867d.\n\n\n\nWhile channeling, your damage taken is reduced by $s2%.\n\n\n\n|cFFFFFFFFPassive:|r Moving near an enemy's corpse consumes their essence to reduce Fleshcraft's cooldown by $<cdr> sec.", ua = "Створює протягом $d щит із плоті й кісток, що поглинає шкоду в розмірі $s1% вашого максимального здоров'я протягом $324867d.\n\n\n\nПід час підтримання отримувана вами шкода зменшена на $s2%.\n\n\n\n|cFFFFFFFFПасивно:|r переміщення поблизу трупа ворога поглинає його есенцію, зменшуючи перезарядження «Плототворення» на $<cdr> сек." },
    { en = "An explosion of dark energy infects enemies within $325203A1 yds with Unholy Transfusion, and heals allies for up to $347788s1 based on number of targets.\n\n\n\n|TInterface\\ICONS\\Spell_AnimaMaldraxxus_Debuff.blp:24|t |cFFFFFFFFUnholy Tranfusion|r\n\n$@spelldesc325203", ua = "Вибух темної енергії заражає ворогів у радіусі $325203A1 м «Нечестивим переливанням» і зцілює союзників до $347788s1 залежно від кількості цілей.\n\n\n\n|TInterface\\ICONS\\Spell_AnimaMaldraxxus_Debuff.blp:24|t |cFFFFFFFFНечестиве переливання|r\n\n$@spelldesc325203" },
    { en = "Call your steward to bring you a Phial of Serenity that can be consumed to restore $323436s1% health and remove all Curse, Disease, Poison, and Bleed effects.\n\n\n\nYour Steward additionally offers access to a selection of useful amenities for $344432d.", ua = "Прикликає вашого розпорядника, щоб той приніс вам Фіал безтурботності, який можна спожити, щоб відновити $323436s1% здоров'я та зняти всі ефекти прокляття, хвороби, отрути й кровотечі.\n\n\n\nКрім того, ваш розпорядник надає доступ до добірки корисних послуг на $344432d." },
    { en = "Draw upon the power of the Ascended for $d, granting you access to $@spellname325020, replacing $?c3[$@spellname15407][$@spellname585] with $@spellname325283, and increasing movement speed by $s3%.\n\n\n\nUpon expiration, releases an $@spellname325326:\n\n\n\n$@spelldesc325326", ua = "Черпає силу Піднесених протягом $d, надаючи вам доступ до $@spellname325020, замінюючи $?c3[$@spellname15407][$@spellname585] на $@spellname325283 і збільшуючи швидкість руху на $s3%.\n\n\n\nПісля завершення вивільняє $@spellname325326:\n\n\n\n$@spelldesc325326" },
    { en = "Throw a deadly chakram at your current target that will rapidly deal $325037s1 Shadow damage $x times, bouncing to other targets if they are nearby. Enemies struck by Death Chakram take $361756s1% more Physical damage from you and your pet for $361756d.\n\n\n\nEach time the chakram deals damage, its damage is increased by $s3% and you generate $s4 Focus.", ua = "Кидає смертоносний чакрам у вашу поточну ціль, що швидко завдає $325037s1 тіньової шкоди $x разів, відскакуючи до інших цілей, якщо вони поблизу. Вороги, уражені Чакрамом смерті, отримують на $361756s1% більше фізичної шкоди від вас і вашого улюбленця протягом $361756d.\n\n\n\nЩоразу, коли чакрам завдає шкоди, його шкода збільшується на $s3%, а ви генеруєте $s4 зосередженості." },
    { en = "Hurl a brew created from the bones of your enemies at the ground, coating all targets struck for $d.  Your abilities have a $h% chance to affect the target a second time at $s1% effectiveness as Shadow damage or healing.\n\n\n\n$?s137024[Gust of Mists heals targets with your Bonedust Brew active for an additional $328748s1.]?s137023[Tiger Palm and Keg Smash reduces the cooldown of your brews by an additional $s3 sec when striking enemies with your Bonedust Brew active.]?s137025[Spinning Crane Kick refunds 1 Chi when striking enemies with your Bonedust Brew active.][]", ua = "Жбурляє об землю вариво, створене з кісток ваших ворогів, покриваючи ним усі уражені цілі на $d. Ваші здібності мають $h% шансу вдруге вплинути на ціль із $s1% ефективністю у вигляді шкоди Тіні чи зцілення.\n\n\n\n$?s137024[«Порив туманів» зцілює цілі під дією вашого «Кістопилового вариба» додатково на $328748s1.]?s137023[«Тигряча долоня» та «Удар барилом» додатково зменшують перезарядження ваших варив на $s3 сек., коли вражають ворогів під дією вашого «Кістопилового вариба».]?s137025[«Вихровий удар журавля» повертає 1 ці, коли вражає ворогів під дією вашого «Кістопилового вариба».][]" },
    { en = "Hurl bolts of decimating magic at your target, dealing $<damage> Shadow damage and increasing the damage of your next$?s198590[][ $325299u] $?s137046[Incinerates]?s198590[Drain Soul]?a137044&?!s137046[Demonbolts]?!a137044[Shadow Bolts][] by $325299s1%.$?a196408[ This value is reduced while using Fire and Brimstone.][]\n\n\n\nDecimating Bolt's damage, and the bonus to $?s137046[Incinerate]?s198590[Drain Soul]?a137044[Demonbolt]?!s137046&!a137044[Shadow Bolt][] both increase as your target's health decreases.", ua = "Жбурляє у ціль стріли спустошливої магії, завдаючи $<damage> шкоди Тіні та збільшуючи шкоду ваших наступних$?s198590[][ $325299u] $?s137046[«Спопелянь»]?s198590[«Висмоктувань душі»]?a137044&?!s137046[«Демонічних стріл»]?!a137044[«Тіньових стріл»][] на $325299s1%.$?a196408[ Це значення зменшується, поки ви використовуєте «Вогонь і сірку».][]\n\n\n\nІ шкода «Спустошливої стріли», і бонус до $?s137046[«Спопеляння»]?s198590[«Висмоктування душі»]?a137044[«Демонічної стріли»]?!s137046&!a137044[«Тіньової стріли»][] зростають у міру того, як здоров'я вашої цілі зменшується." },
    { en = "Wither away all life force of your current target and up to $s3 additional targets nearby, causing your primary target to suffer ${$o2*(1+$m4/10)} Nature damage and secondary targets to suffer $o2 Nature damage over $d.\n\n\n\nFor the next $d, casting Drain Life will cause you to also Drain Life from any enemy affected by your Soul Rot, and Drain Life will not consume any mana.", ua = "Висушує всю життєву силу вашої поточної цілі та до $s3 додаткових цілей поблизу, через що ваша основна ціль зазнає ${$o2*(1+$m4/10)} шкоди Природи, а другорядні цілі — $o2 шкоди Природи протягом $d.\n\n\n\nПротягом наступних $d застосування «Висмоктування життя» змусить вас також висмоктувати життя з будь-якого ворога під дією вашого «Гниття душі», і «Висмоктування життя» не витрачатиме мани." },
    { en = "Command a swarm that heals $325748o1 or deals $325733o1 Shadow damage over $325733d to a target, and increases the effectiveness of your periodic effects on them by $325748s2%.\n\n\n\nUpon expiration, finds a new target, preferring to alternate between friend and foe up to $s1 times.", ua = "Скеровує рій, що зцілює ціль на $325748o1 або завдає їй $325733o1 шкоди Тіні протягом $325733d і збільшує ефективність ваших періодичних ефектів на ній на $325748s2%.\n\n\n\nПісля завершення рій знаходить нову ціль, надаючи перевагу почерговому переходу між союзником і ворогом, до $s1 разів." },
    { en = "Unleash a wave of anima, dealing $s1 Nature damage to up to $s2 enemies and knocking them down for $d.\n\n\n\nThe ground will continue to expel anima, dealing $<areaDmg> Nature damage to up to $s2 enemies and generating $<rage> Rage per enemy over $343607d. Every $<period> sec, targets are briefly knocked down.", ua = "Вивільняє хвилю аніми, завдаючи $s1 шкоди Природи до $s2 ворогам і збиваючи їх із ніг на $d.\n\n\n\nЗемля й далі викидатиме аніму, завдаючи $<areaDmg> шкоди Природи до $s2 ворогам і генеруючи $<rage> люті за кожного ворога протягом $343607d. Кожні $<period> сек. цілі ненадовго збиваються з ніг." },
    { en = "Blast your target with a Primordial Wave, dealing $327162s1 Shadow damage and apply Flame Shock to an enemy, or $?a137039[heal an ally for $327163s1 and apply Riptide to them][heal an ally for $327163s1].\n\n\n\nYour next $?a137040[Lava Burst]?a137041[Lightning Bolt][Healing Wave] will also hit all targets affected by your $?a137040|a137041[Flame Shock][Riptide] for $?a137039[$s2%]?a137040[$s3%][$s4%] of normal $?a137039[healing][damage].", ua = "Вражає твою ціль Первісною хвилею, завдаючи $327162s1 шкоди Тінню і накладаючи Полум'яний шок на ворога, або $?a137039[зцілює союзника на $327163s1 і накладає на нього Відплив][зцілює союзника на $327163s1].\n\n\n\nТвоя наступна $?a137040[Лавова навала]?a137041[Блискавка][Зцілюща хвиля] також вразить усі цілі, охоплені твоїм $?a137040|a137041[Полум'яним шоком][Відпливом], на $?a137039[$s2%]?a137040[$s3%][$s4%] від звичайного $?a137039[зцілення][шкоди]." },
    { en = "Form a bond with an ally. Every $327097d, you may empower the bond for $327037d, granting you an effect based on your partner's role, and granting them an effect based on your role.\n\n\n\n$?c3[|cFFFFFFFFTank|r\n\n$@spellicon327037 $@spellname327037\n\n$@spelldesc327037]?c4[|cFFFFFFFFHealer|r\n\n$@spellicon327071 $@spellname327071\n\n$@spelldesc327071][|cFFFFFFFFDamager|r\n\n$@spellicon327022 $@spellname327022\n\n$@spelldesc327022]", ua = "Утворює зв'язок із союзником. Кожні $327097d ви можете підсилити цей зв'язок на $327037d, отримуючи ефект залежно від ролі вашого партнера й надаючи йому ефект залежно від вашої ролі.\n\n\n\n$?c3[|cFFFFFFFFТанк|r\n\n$@spellicon327037 $@spellname327037\n\n$@spelldesc327037]?c4[|cFFFFFFFFЦілитель|r\n\n$@spellicon327071 $@spellname327071\n\n$@spelldesc327071][|cFFFFFFFFБоєць|r\n\n$@spellicon327022 $@spellname327022\n\n$@spelldesc327022]" },
    { en = "Hammer of Wrath may be used on any target during Avenging Wrath.", ua = "Під час дії «Гніву месника» «Молот гніву» можна застосовувати до будь-якої цілі." },
    { en = "Engrave your weapon with a rune that causes your Death Strike to deal increased damage based on the target's missing health. When you fall below $326801s1% health, you heal for ${$326808s1*$326808d}% of your maximum health over $326808d. \n\n\n\nModifying your rune requires a Runeforge in Ebon Hold.", ua = "Гравірує на вашій зброї руну, завдяки якій ваш «Смертельний удар» завдає більше шкоди залежно від нестачі здоров'я цілі. Коли ваше здоров'я падає нижче $326801s1%, ви зцілюєтеся на ${$326808s1*$326808d}% максимального здоров'я протягом $326808d. \n\n\n\nЗміна вашої руни потребує рунокузні в Чорному Оплоті." },
    { en = "Engrave your weapon with a rune that deflects $326864s2% of all spell damage and taking magic damage has a chance to create a shield that absorbs magic damage equal to $s2% of your maximum health. When an enemy damages the shield, their cast speed is reduced by $326868s1% for $326868d. \n\n\n\nModifying your rune requires a Runeforge in Ebon Hold.", ua = "Гравірує на вашій зброї руну, що відбиває $326864s2% усієї шкоди від заклять, а отримання магічної шкоди має шанс створити щит, який поглинає магічну шкоду в розмірі $s2% вашого максимального здоров'я. Коли ворог завдає шкоди щиту, його швидкість творення зменшується на $326868s1% протягом $326868d. \n\n\n\nЗміна вашої руни потребує рунокузні в Чорному Оплоті." },
    { en = "Opens a mystic portal for $d. Every ${$t1*3} sec, it summons a spirit of your order's fallen Ox, Crane, or Tiger adepts for $s4 sec.\n\n\n\nFallen $?$C1[Ox]?$C2[Crane][Tiger] adepts assist for an additional $s3 sec, and will also $?$C1[attack your enemies with Breath of Fire]?$C2[heal with Enveloping Mist][assault with Fists of Fury].", ua = "Відкриває містичний портал на $d. Кожні ${$t1*3} сек. він прикликає дух полеглого адепта Вола, Журавля чи Тигра вашого ордену на $s4 сек.\n\n\n\nПолеглі адепти $?$C1[Вола]?$C2[Журавля][Тигра] допомагають додатково $s3 сек. і також $?$C1[атакують ваших ворогів «Подихом вогню»]?$C2[зцілюють «Огортальним туманом»][атакують «Кулаками люті»]." },
    { en = "Engrave your weapon with a rune that increases your movement speed by $326982s2%. Additionally, when you kill an enemy that yields experience or honor you heal for $326984s2% of your maximum health and gain $326984s1% Haste and movement speed.\n\n\n\nModifying your rune requires a Runeforge in Ebon Hold.", ua = "Гравірує на вашій зброї руну, що збільшує вашу швидкість руху на $326982s2%. Крім того, коли ви вбиваєте ворога, що дає досвід чи честь, ви зцілюєтеся на $326984s2% максимального здоров'я та отримуєте $326984s1% поспіху й швидкості руху.\n\n\n\nЗміна вашої руни потребує рунокузні в Чорному Оплоті." },
    { en = "Engrave your weapon with a rune that gives your ghoul's attacks a chance to apply one of the following debuffs to the target, Death: Healing Reduction, War: Increases damage taken from the Death Knight, Famine: Reduces damage dealt to the Death Knight, Pestilence: Slows the target and deals damage over time. \n\n\n\nModifying your rune requires a Runeforge in Ebon Hold.", ua = "Гравірує на вашій зброї руну, що дає атакам вашого упиря шанс накласти на ціль одне з таких послаблень. Смерть: зменшення зцілення. Війна: збільшує шкоду, отримувану від лицаря смерті. Голод: зменшує шкоду, завдану лицарю смерті. Пошесть: сповільнює ціль і завдає шкоди з часом. \n\n\n\nЗміна вашої руни потребує рунокузні в Чорному Оплоті." },
    { en = "Strike the ground fiercely to expose a faeline for $d, dealing $345727s1 Nature damage to up to 5 enemies, and restores $345727s2 health to up to 5 allies within $345727a1 yds caught in the faeline. $?a137024[Up to 5 allies]?a137025[Up to 5 enemies][Stagger is $s3% more effective for $347480d against enemies] caught in the faeline$?a137023[]?a137024[ are healed with an Essence Font bolt][ suffer an additional $327264s1 damage].\n\n\n\nYour abilities have a $s2% chance of resetting the cooldown of Faeline Stomp while fighting on a faeline.", ua = "Люто б'єте об землю, оголюючи феялінію на $d, завдаючи $345727s1 шкоди Природи до 5 ворогам і відновлюючи $345727s2 здоров'я до 5 союзникам у радіусі $345727a1 м, що опинилися на феялінії. $?a137024[До 5 союзників]?a137025[До 5 ворогів][«Затримка» на $s3% ефективніша протягом $347480d проти ворогів], що опинилися на феялінії,$?a137023[]?a137024[ зцілюються спалахом «Джерела есенції»][ зазнають додаткової шкоди $327264s1].\n\n\n\nВаші здібності мають $s2% шансу скинути перезарядження «Тупоту феялінії», поки ви б'єтеся на феялінії." },
    { en = "Call forth three faerie guardians to attend your targets for $d.\n\n\n\n$@spellname342132: Any direct attacks against the target restore ${$327703s1/100}.1% Mana or ${$327703s2/100} Insanity. Follows your Shadow Word: Pain.\n\n\n\n$@spellname327694: Reduces damage taken by $327694s1%. Follows your Power Word: Shield.\n\n\n\n$@spellname327710: Increases the cooldown recovery rate of your target's major ability by $327710s1%. Follows your $?c2[Flash Heal][Shadow Mend].", ua = "Прикликає трьох фейських охоронців, що дбають про ваші цілі протягом $d.\n\n\n\n$@spellname342132: будь-які прямі атаки по цілі відновлюють ${$327703s1/100}.1% мани або ${$327703s2/100} безумства. Слідує за вашим «Тіньове слово: біль».\n\n\n\n$@spellname327694: зменшує отримувану шкоду на $327694s1%. Слідує за вашим «Слово сили: щит».\n\n\n\n$@spellname327710: збільшує швидкість відновлення перезарядження головної здібності вашої цілі на $327710s1%. Слідує за вашим $?c2[«Швидке зцілення»][«Тіньове цілення»]." },
    { en = "Damage increased $s1%.", ua = "Шкоду збільшено на $s1%." },
    { en = "Throws a hammer at your target dealing $s1 Shadow damage, and empowering your next $?c3[Templar's Verdict to automatically trigger Divine Storm]?c1[Word of Glory to automatically trigger Light of Dawn][Word of Glory to automatically trigger Shield of the Righteous] with $s2% increased effectiveness.\n\n\n\n|cFFFFFFFFGenerates $s3 Holy Power.", ua = "Кидає молот у ціль, завдаючи $s1 шкоди Тінню, та підсилює ваш наступний $?c3[Вирок тамплієра, щоб автоматично спрацював Божественний шторм]?c1[Слово слави, щоб автоматично спрацювало Світло світанку][Слово слави, щоб автоматично спрацював Щит праведника] з $s2% підвищеною дієвістю.\n\n\n\n|cFFFFFFFFДає $s3 Священної сили." },
    { en = "Evoke the energy of Wild Spirits at the target location, dealing $328837s3 Nature damage and apply Wild Mark to all enemy targets within the area for $328837d.\n\n\n\nWhile the Wild Spirits are active, each damaging ability you or your pet use against a target in the area will strike up to $328757I nearby targets for $328757s1 Nature damage.", ua = "Прикликає в цільовому місці енергію Диких духів, завдаючи $328837s3 шкоди Природи та накладаючи «Дике тавро» на всі ворожі цілі в зоні на $328837d.\n\n\n\nПоки Дикі духи активні, кожна здібність шкоди, яку ви чи ваш улюбленець застосовуєте проти цілі в зоні, уражатиме до $328757I цілей поблизу на $328757s1 шкоди Природи." },
    { en = "Infect the target's blood, dealing $o1 Nature damage over $d. If the target survives its full duration, they suffer an additional $328306s1 damage and you gain $s6 use of any Stealth ability for $347037d.\n\n\n\nCooldown reduced by $s3 sec if Sepsis does not last its full duration.\n\n\n\n|cFFFFFFFFAwards $s7 combo $lpoint:points;.|r", ua = "Заражає кров цілі, завдаючи $o1 шкоди Природи протягом $d. Якщо ціль переживає весь час дії, вона зазнає додаткової шкоди $328306s1, а ви отримуєте $s6 застосувань будь-якої здібності непомітності на $347037d.\n\n\n\nПерезарядження зменшується на $s3 сек., якщо «Сепсис» не діє весь свій час.\n\n\n\n|cFFFFFFFFНадає $s7 $lочко:очка:очок; комбо.|r" },
    { en = "Embed a bone spike in the target, dealing $s1 Physical damage and $324073s1 Bleed damage every $324073t1 sec until they die or leave combat. \n\n\n\nRefunds a charge when target dies.\n\n\n\n|cFFFFFFFFAwards 1 combo point plus 1 additional per active bone spike.|r", ua = "Встромляє в ціль кістяний шип, завдаючи $s1 фізичної шкоди та $324073s1 шкоди кровотечі кожні $324073t1 сек., доки ціль не загине чи не вийде з бою. \n\n\n\nПовертає заряд, коли ціль гине.\n\n\n\n|cFFFFFFFFНадає 1 очко комбо плюс 1 додаткове за кожен активний кістяний шип.|r" },
    { en = "Bless an ally for $d, causing their attacks to have a $h% chance to deal $s1% additional damage as Holy.\n\n\n\n|cFFFFFFFFBlessing of the Seasons:|r Turns to Autumn after use.", ua = "Благословляє союзника на $d, через що його атаки мають $h% шансу завдати $s1% додаткової шкоди як Свята.\n\n\n\n|cFFFFFFFFБлагословення пір року:|r після використання змінюється на осінь." },
    { en = "Transfer the life force of up to $328928I enemies in the targeted area, dealing ${($328928s1*$d/$t2) + $328928s1} Nature damage evenly split to each enemy target over $d. $?a137041[\n\n\n\nFully channeling Fae Transfusion generates $s4 $Lstack:stacks; of Maelstrom Weapon.][]\n\n\n\nPressing Fae Transfusion again within $328933d will release $s1% of all damage from Fae Transfusion, healing up to $328930s2 allies within $328930A1 yds.", ua = "Переносить життєву силу до $328928I ворогів у цільовій ділянці, завдаючи ${($328928s1*$d/$t2) + $328928s1} шкоди Природи, рівномірно розподіленої між усіма ворожими цілями, протягом $d. $?a137041[\n\n\n\nПовне читання Трансфузії фей дає $s4 $Lнабій:набої:набоїв; Зброї Виру.][]\n\n\n\nЯкщо натиснути Трансфузію фей знову протягом $328933d, вивільниться $s1% усієї шкоди від Трансфузії фей, зцілюючи до $328930s2 союзників у межах $328930A1 м." },
    { en = "Right Click to summon and dismiss Micromancer.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Мікромансера." },
    { en = "Right Click to summon and dismiss your Dredger Butler.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати вашого дворецького-копача." },
    { en = "Your bond with the Night Fae grants special privileges in Ardenweald Dungeons.", ua = "Ваш зв'язок із Нічними Феями надає особливі привілеї в підземеллях Арденвельду." },
    { en = "Your bond with the Kyrian grants special priveleges in Bastion Dungeons.", ua = "Ваш зв'язок із кіріанами надає особливі привілеї в підземеллях Бастіону." },
    { en = "Your bond with the Venthyr grants special priveleges in Revendreth Dungeons.", ua = "Ваш зв'язок із вентирами надає особливі привілеї в підземеллях Ревендрету." },
    { en = "Your bond with the Necrolords grants special priveleges in Maldraxxus Dungeons.", ua = "Ваш зв'язок із некролордами надає особливі привілеї в підземеллях Малдраксусу." },
    { en = "When falling below $s2% health, the Camel will shrug off attacks, granting $160058s1% reduced incoming damage for $160058d.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Коли здоров'я верблюда падає нижче $s2%, він струшує з себе атаки, що на $160058d зменшує отримувану ним шкоду на $160058s1%.\n\n\n\nЦей ефект може спрацьовувати лише раз на $s3 сек." },
    { en = "The Courser gallops quickly, increasing dodge chance by $s1% for $d.", ua = "Скакун швидко мчить галопом, збільшуючи шанс ухилення на $s1% протягом $d." },
    { en = "The Mammoth tramples the target, slowing movement by $s1% for $d.", ua = "Мамонт топче ціль, сповільнюючи її рух на $s1% протягом $d." },
    { en = "Begins a ritual that sacrifices a random participant to summon a doomguard. Requires the caster and 4 additional party members to complete the ritual.", ua = "Розпочинає ритуал, що приносить у жертву випадкового учасника, аби викликати вартового погибелі. Для завершення ритуалу потрібен закликач і ще 4 учасники групи." },
    { en = "You no longer suffer spell pushback when casting Fear.", ua = "Отримана шкода більше не затримує творення «Страху»." },
    { en = "Teleports you to a major city.", ua = "Телепортує тебе до великого міста." },
    { en = "Creates a portal, teleporting group members that use it to a Major City.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до великого міста." },
    { en = "Entangling Roots can withstand $s1% more damage before breaking.", ua = "«Чіпке коріння» витримує на $s1% більше шкоди, перш ніж розірветься." },
    { en = "Your connection with your Covenant grows, increasing movement speed by $s1%.", ua = "Ваш зв'язок із вашим Ковенантом міцніє, збільшуючи швидкість руху на $s1%." },
    { en = "The Water Strider cleanses itself with water droplets, removing $s1 Disease, Magic, and Poison effect.", ua = "Водомірка очищується краплями води, знімаючи $s1 ефект хвороби, магії та отрути." },
    { en = "The Sporebat shakes off excess spores, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Спорокажан струшує надлишок спор, знімаючи із себе $s1 ефект хвороби, магії та отрути." },
    { en = "The Bat emits a sonic pulse from within, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Кажан випромінює зсередини звуковий імпульс, знімаючи із себе $s1 ефект хвороби, магії та отрути." },
    { en = "A pulse of excess energy releases from the Ray, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Імпульс надлишкової енергії вивільняється зі ската, знімаючи з нього $s1 ефект хвороби, магії та отрути." },
    { en = "Shakes its feathers, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Струшує пір'я, знімаючи із себе $s1 ефект хвороби, магії та отрути." },
    { en = "A pulse of spirit energy releases from the Spirit Beast, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Від духовного звіра виходить імпульс духовної енергії, знімаючи з нього $s1 ефект хвороби, магії та отрути." },
    { en = "A soothing breeze surrounds the Stag, removing $s1 Disease, Magic, and Poison effect from itself.", ua = "Лагідний вітерець огортає оленя, знімаючи з нього $s1 ефект хвороби, магії та отрути." },
    { en = "The moth vibrates its wings, releasing tranquil dust all over itself, removing $s1 Disease, Magic, and Poison effect.", ua = "Метелик тріпоче крилами, осипаючи себе заспокійливим пилком, що знімає $s1 ефект хвороби, магії та отрути." },
    { en = "Sends you and your pet into a rage, instantly dealing $344572s1 Physical damage to its target, and increasing all damage you both deal by $s1% for $d. Removes all crowd control effects from your pet. $?s193532[\n\n\n\nActivating Bestial Wrath grants $s2 $Lcharge:charges; of Barbed Shot.][]$?s231548&!s193532[.][]", ua = "Розлючує вас і вашого улюбленця, миттєво завдаючи його цілі $344572s1 од. фізичної шкоди та збільшуючи всю шкоду, яку ви обидва завдаєте, на $s1% протягом $d. Знімає з вашого улюбленця всі ефекти контролю. $?s193532[\n\n\n\nЗастосування Гніву звіра надає $s2 $Lзаряд:заряди:зарядів; Колючого пострілу.][]$?s231548&!s193532[.][]" },
    { en = "Teleports you to Oribos.", ua = "Телепортує тебе до Орибоса." },
    { en = "Creates a portal, teleporting group members that use it to Oribos.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Орибоса." },
    { en = "Quickly attack for $s2 Physical damage.\n\n\n\n|cFFFFFFFFGenerates $?a258876[${$m3+$258876s3} to ${$M3+$258876s4}][$m3 to $M3] Fury.|r", ua = "Швидко атакує, завдаючи $s2 фізичної шкоди.\n\n\n\n|cFFFFFFFFПороджує $?a258876[від ${$m3+$258876s3} до ${$M3+$258876s4}][від $m3 до $M3] Люті.|r" },
    { en = "Slice your target for ${$222031s1+$199547s1} Chaos damage. Chaos Strike has a ${$min($197125h,100)}% chance to refund $193840s1 Fury.", ua = "Розтинаєте вашу ціль, завдаючи ${$222031s1+$199547s1} шкоди Хаосу. Удар хаосу має ${$min($197125h,100)}% шанс повернути $193840s1 люті." },
    { en = "Rush forward, incinerating anything in your path for $192611s1 Chaos damage.", ua = "Кидаєтеся вперед, спопеляючи все на своєму шляху та завдаючи $192611s1 шкоди Хаосу." },
    { en = "Soulshape teleports you in the direction you are moving instead of the direction you are facing.", ua = "«Душевна подоба» телепортує вас у напрямку руху, а не в напрямку, куди ви дивитеся." },
    { en = "Right Click to summon and dismiss this pet.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати цього улюбленця." },
    { en = "Your damaging abilities have a chance to call forth a demon from the Theater of Pain for $329554d. Throw Glaive deals lethal damage to the demon, which explodes on death, dealing $350631s1 $@spelldesc395041 damage to nearby enemies and healing you for $350631s2% of your maximum health. The explosion deals reduced damage beyond 5 targets.", ua = "Ваші здібності шкоди мають шанс прикликати демона з Театру болю на $329554d. «Кидок глефи» завдає демону смертельної шкоди, і той вибухає, гинучи, завдаючи $350631s1 шкоди $@spelldesc395041 ворогам поблизу та зцілюючи вас на $350631s2% максимального здоров'я. Вибух завдає зменшеної шкоди понад 5 цілей." },
    { en = "Fire an enchanted arrow, dealing $354831s1 Shadow damage to your target and an additional $354831s2 Shadow damage to all enemies within $354831A2 yds of your target. Targets struck by a Wailing Arrow are silenced for $355596d.", ua = "Випускаєш зачаровану стрілу, що завдає $354831s1 шкоди від тіні цілі та ще $354831s2 шкоди від тіні всім ворогам у радіусі $354831A2 м від неї. Цілі, уражені «Стрілою голосіння», замовкають на $355596d." },
    { en = "Grow a bulb from the Emerald Dream at an ally's location. After $d, heal up to $355916s2 injured allies within $s1 yds for $355916s1.", ua = "Вирости бруньку зі Смарагдового Сну там, де стоїть союзник. Через $d вона зцілить до $355916s2 поранених союзників у межах $s1 м на $355916s1." },
    { en = "Summons a Holy Lightstrider, which serves as a mount.", ua = "Прикликає святого світлоступа, що слугує їздовою твариною." },
    { en = "Tear into an enemy with a blast of blue magic, inflicting $o1 Spellfrost damage over $d, and slowing their movement speed by $370898s1% for $370898d.", ua = "Розриває ворога вибухом синьої магії, завдаючи $o1 шкоди чарокригою протягом $d і вповільнюючи його швидкість руху на $370898s1% на $370898d." },
    { en = "Inhale, stoking your inner flame. Release to exhale, burning enemies in a cone in front of you for ${$<dmI>+$<doI>} Fire damage, reduced beyond 5 targets.$?s395153[\n\n\n\nIncreases the duration of your active Ebon Might effects by ${$395153s2/1000} sec.][]\n\n\n\nEmpowering causes more of the damage to be dealt immediately instead of over time.\n\n\n\n|cFFFFFFFFI:|r   Deals $<dmI> damage instantly and $<doI> over $<duI> sec.\n\n\n\n|cFFFFFFFFII:|r  Deals $<dmII> damage instantly and $<doII> over $<duII> sec.\n\n\n\n|cFFFFFFFFIII:|r Deals $<dmIII> damage instantly and $<doIII> over $<duIII> sec.", ua = "Вдихаєш, роздмухуючи внутрішнє полум'я. Видихаєш, спалюючи ворогів у конусі перед собою на ${$<dmI>+$<doI>} вогняної шкоди, зменшеної понад 5 цілей.$?s395153[\n\n\n\nПодовжує тривалість твоїх активних ефектів Чорної міці на ${$395153s2/1000} с.][]\n\n\n\nПідсилення завдає більшу частину шкоди миттєво, а не з часом.\n\n\n\n|cFFFFFFFFI:|r   Завдає $<dmI> шкоди миттєво та $<doI> протягом $<duI> с.\n\n\n\n|cFFFFFFFFII:|r  Завдає $<dmII> шкоди миттєво та $<doII> протягом $<duII> с.\n\n\n\n|cFFFFFFFFIII:|r Завдає $<dmIII> шкоди миттєво та $<doIII> протягом $<duIII> с." },
    { en = "Take in a deep breath and fly to the targeted location, spewing molten cinders dealing $353759o1 Volcanic damage to enemies in your path.\n\n\n\nRemoves all root effects. You are immune to movement impairing and loss of control effects while flying.$?s395153[\n\n\n\nIncreases the duration of your active Ebon Might effects by ${$395153s3/1000} sec.][]", ua = "Робиш глибокий вдих і летиш до позначеного місця, вивергаючи розплавлені жарини, що завдають $353759o1 вулканічної шкоди ворогам на твоєму шляху.\n\n\n\nЗнімає всі ефекти знерухомлення. Під час польоту ти маєш імунітет до ефектів сповільнення руху та втрати контролю.$?s395153[\n\n\n\nПодовжує тривалість твоїх активних ефектів Чорної міці на ${$395153s3/1000} с.][]" },
    { en = "Launch yourself and gain $s2% increased movement speed for $<dura> sec.\n\n\n\nAllows Evoker spells to be cast while moving and is castable while casting. Does not affect empowered spells.", ua = "Злітаєте та отримуєте $s2% збільшеної швидкості пересування на $<dura> сек.\n\n\n\nДозволяє творити закляття Пробуджувача на ходу й може бути сотворене під час іншого творення. Не діє на закляття наснаги." },
    { en = "Right Click to summon and dismiss your Archetype of Focus.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Зосередження." },
    { en = "Right Click to summon and dismiss your Resonant Echo.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваше Резонансне Відлуння." },
    { en = "Right Click to summon and dismiss your Omnipotential Core.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваше Всемогутнє Ядро." },
    { en = "Right Click to summon and dismiss your Geordy.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Джорді." },
    { en = "Right Click to summon and dismiss your Archetype of Discovery.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Відкриття." },
    { en = "Right Click to summon and dismiss your Tunneling Vombata.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Риючого Вомбата." },
    { en = "Right Click to summon and dismiss Drakks.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати Дракса." },
    { en = "Right Click to summon and dismiss your Archetype of Motion.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Руху." },
    { en = "Right Click to summon and dismiss your Archetype of Animation.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Оживлення." },
    { en = "Right Click to summon and dismiss your Archetype of Serenity.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Спокою." },
    { en = "Right Click to summon and dismiss your Archetype of Multiplicity.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Множинності." },
    { en = "Right Click to summon and dismiss your Archetype of Metamorphosis.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Метаморфози." },
    { en = "Summons and dismisses a rideable Highland Drake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Високогірного Дрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Right Click to summon and dismiss your Archetype of Predation.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Хижацтва." },
    { en = "Right Click to summon and dismiss your Archetype of Survival.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Виживання." },
    { en = "Brings a dead party member back to life with $s1% health and mana. Cannot be cast when in combat.", ua = "Повертає до життя мертвого члена групи з $s1% здоров'я і мани. Неможливо творити в бою." },
    { en = "Right Click to summon and dismiss your Archetype of Cunning.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Хитрості." },
    { en = "Send a flickering flame towards your target, $?c2[healing an ally for $361509s1 or dealing $361500s1 Fire damage to an enemy.][dealing $361500s1 Fire damage to an enemy or healing an ally for $361509s1.]", ua = "Надсилає мерехтливе полум'я до вашої цілі, $?c2[зцілюючи союзника на $361509s1 або завдаючи $361500s1 шкоди вогнем ворогу.][завдаючи $361500s1 шкоди вогнем ворогу або зцілюючи союзника на $361509s1.]" },
    { en = "Right Click to summon and dismiss your Archetype of Malice.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Злоби." },
    { en = "Right Click to summon and dismiss your Archetype of Satisfaction.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Задоволення." },
    { en = "Project intense energy onto $s1 enemies, dealing $s2 Spellfrost damage to them.", ua = "Спрямовує потужну енергію на ворогів (до $s1), завдаючи їм $s2 шкоди чарокригою." },
    { en = "Summons and dismisses your Colossal Ebonclaw Mawrat.", ua = "Прикликає або відкликає вашого Колосального Пащура Чорнопазура." },
    { en = "Summons and dismisses your Colossal Umbrahide Mawrat.", ua = "Прикликає або відкликає вашого Колосального Пащура Тінешкура." },
    { en = "Summons and dismisses your Colossal Soulshredder Mawrat.", ua = "Прикликає або відкликає вашого Колосального Пащура Душотерзателя." },
    { en = "Summons a Lightforged Ruinstrider, which serves as a mount.", ua = "Прикликає Загартованого Світлом Руїноступа, що слугує їздовою твариною." },
    { en = "Right Click to summon and dismiss your Ambystan Darter.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Амбістового Стрімчака." },
    { en = "Right Click to summon and dismiss your Fierce Scarabid.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Лютого Скарабіда." },
    { en = "Right Click to summon and dismiss your Violent Poultrid.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Шаленого Птахіда." },
    { en = "Right Click to summon and dismiss your Multichicken.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати ваше Мультикурча." },
    { en = "Right Click to summon and dismiss your Stabilized Geomental.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Стабілізованого Геоменталя." },
    { en = "Right Click to summon and dismiss your Terror Jelly.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашу Жахітну Медузу." },
    { en = "Right Click to summon and dismiss your Prototickles.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Протолоскотуна." },
    { en = "Right Click to summon and dismiss your Leaping Leporid.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Стрибучого Лепорида." },
    { en = "Right Click to summon and dismiss your Microlicid.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Мікроліцида." },
    { en = "Right Click to summon and dismiss your Archetype of Vigilance.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Пильності." },
    { en = "Right Click to summon and dismiss your Shelly.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Шеллі." },
    { en = "Right Click to summon and dismiss your Viperid Menace.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Грізного Віперида." },
    { en = "Right Click to summon and dismiss your Archetype of Renewal.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Архетипа Оновлення." },
    { en = "Weave the threads of time, reducing the cooldown of a major movement ability for all party and raid members by $381732s1% for $381732d.", ua = "Сплітаєш нитки часу, скорочуючи перезарядження головної здібності пересування всім членам групи чи рейду на $381732s1% на $381732d." },
    { en = "Right Click to summon and dismiss your E'rnee.", ua = "Клацніть правою кнопкою, щоб прикликати або відкликати вашого Е'рні." },
    { en = "Summons a Succubus or Incubus under your command to seduce enemy Humanoids, preventing them from attacking.", ua = "Прикликає сукуба або інкуба, що стає під твою команду і зваблює ворожих гуманоїдів, не даючи їм атакувати." },
    { en = "Increases your Intellect by $s1% while wearing only Mail armor.", ua = "Збільшує твій інтелект на $s1%, поки на тобі лише кольчужна броня." },
    { en = "Summons and dismisses a Magenta Cloud Serpent.", ua = "Прикликає або відкликає Пурпурового Хмарного Змія." },
    { en = "Summon and dismiss Pocopoc.\n\n\n\nOnly works outside of Zereth Mortis.", ua = "Прикликає або відкликає Покопока.\n\n\n\nДіє лише за межами Зерет-Мортіса." },
    { en = "Summons and dismisses a rideable Savage Green Battle Turtle. This mount swims fast and can't move very quickly on land, but it doesn't need to. It has cannons.", ua = "Прикликає або відкликає верхову Дику Зелену Бойову Черепаху. Ця їздова тварина швидко плаває, а на суходолі рухається доволі повільно, та їй це й не потрібно. Адже вона має гармати." },
    { en = "Summons and dismisses your Colossal Plaguespew Mawrat.", ua = "Прикликає або відкликає вашого Колосального Пащура Чумоблюва." },
    { en = "Summons and dismisses this mount. The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає або відкликає цю їздову тварину. Можливості цієї їздової тварини залежать від ваших навичок верхової їзди та місцеперебування." },
    { en = "Summons and dismisses your Colossal Wraithbound Mawrat.", ua = "Прикликає або відкликає вашого Колосального Пащура Привидозв'язаного." },
    { en = "Summons and dismisses a rideable Winding Slitherdrake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Звивистого Повзодрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Renewed Proto-Drake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Оновленого Протодрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Windborne Velocidrake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Вітрородного Велоцидрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Cliffside Wylderdrake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Скельного Дикодрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Lash out with your tail, knocking enemies within $A1 yds into the air.", ua = "Шмагни хвостом, підкинувши в повітря ворогів у межах $A1 м." },
    { en = "Summons and dismisses a rideable Elusive Emerald Hawkstrider.", ua = "Прикликає або відкликає верхового Невловного Смарагдового Яструбоступа." },
    { en = "Your damaging Blue spells reduce the target's movement speed by $370898s1% for $370898d.", ua = "Твої сині закляття, що завдають шкоди, зменшують швидкість руху цілі на $370898s1% на $370898d." },
    { en = "Call upon the Covenants of the Shadowlands to aid you, restoring $s1 health and increasing your Versatility by $s2% for $d.\n\n\n\n|cFFFFFFFFPassive:|r The Covenants have granted you a portion of their power, increasing your damage and healing by ${$387169s1}.1%.", ua = "Прикликає на допомогу Ковенанти Тіньових Земель, відновлюючи $s1 здоров'я та підвищуючи вашу Універсальність на $s2% на $d.\n\n\n\n|cFFFFFFFFПасивно:|r Ковенанти наділили вас часткою своєї сили, підвищуючи вашу шкоду та зцілення на ${$387169s1}.1%." },
    { en = "Increases haste by $s1% for all party and raid members for $d.\n\n\n\nAllies receiving this effect will become Exhausted and unable to benefit from Fury of the Aspects or similar effects again for $57723d.", ua = "Збільшує поспіх усіх членів групи та рейду на $s1% на $d.\n\n\n\nСоюзники, що отримують цей ефект, стають Виснаженими й не можуть знову скористатися Люттю Аспектів чи подібними ефектами протягом $57723d." },
    { en = "Petition the Light on the behalf of a fallen ally, restoring spirit to body and allowing them to reenter battle with $s2% health and at least $s1% mana.", ua = "Благаєш Світло за полеглого союзника, повертаючи дух у тіло й дозволяючи йому повернутися до бою з $s2% здоров'я і щонайменше $s1% мани." },
    { en = "Transforms the enemy into a duck, wandering around incapacitated for $d. While affected, the victim cannot take actions but will regenerate health very quickly. Damage will cancel the effect. Limit 1.\n\n\n\nOnly works on Beasts, Humanoids and Critters.$?s56382[ When critters are affected, can affect multiple targets, and has a duration of 1 day.][]", ua = "Перетворює ворога на качку, що знесилено блукає довкола протягом $d. Під час дії жертва не може діяти, але дуже швидко відновлює здоров'я. Шкода скасовує ефект. Обмеження: 1.\n\n\n\nДіє лише на тварин, гуманоїдів і дрібноту.$?s56382[ На дрібноту може діяти на кілька цілей водночас і триває 1 день.][]" },
    { en = "The Lesser Dragonkin's scales shimmer, reducing magic damage taken by $s1% for $d.", ua = "Луска Нижчого Драконіда мерехтить, знижуючи отримувану магічну шкоду на $s1% на $d." },
    { en = "Teleports you to Valdrakken.", ua = "Телепортує тебе до Валдраккена." },
    { en = "Creates a portal, teleporting group members that use it to Valdrakken.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Валдраккена." },
    { en = "Transforms you into a white wind eagle. This is a flying mount.", ua = "Перетворює вас на білого вітряного орла. Це летюча їздова тварина." },
    { en = "Your dragon scales increase your armor by $s1%.", ua = "Твоя драконяча луска збільшує броню на $s1%." },
    { en = "Living Flame restores $s1% of its mana cost when striking an enemy.", ua = "«Живе полум'я» відновлює $s1% своєї вартості мани, коли влучає у ворога." },
    { en = "Transform into Tarecgosa's Visage, granting you increased movement speed and allowing you to fly.", ua = "Перетворює вас на Подобу Тарекгози, підвищуючи швидкість пересування та дозволяючи літати." },
    { en = "Summons and dismisses a rideable Felcrystal Scorpion.", ua = "Прикликає або відкликає верхового Скверноскришталевого Скорпіона." },
    { en = "Summons and dismisses a rideable Grotto Netherwing Drake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Печерного Дрейка Нетерокрилих.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses your Scarlet Pterrordax.", ua = "Прикликає або відкликає вашого Багряного Птерордакса." },
    { en = "Summons and dismisses Valiance.", ua = "Прикликає та відпускає Доблесть." },
    { en = "Summons and dismisses a rideable White War Wolf.", ua = "Прикликає або відкликає верхового Білого Бойового Вовка." },
    { en = "Summons and dismisses a rideable Sulfur Hound.", ua = "Прикликає або відкликає верхового Сірчаного Гончака." },
    { en = "Summons and dismisses Juggernaut Perfected.", ua = "Прикликає або відкликає Вдосконаленого Джаґернаута." },
    { en = "Summons and dismisses a rideable Scourgebound Frostbrood Vanquisher.  This is a flying mount.", ua = "Прикликає або відкликає верхового Зв'язаного Погибеллю Переможця Морозного Поріддя. Це летюча їздова тварина." },
    { en = "Call Rusziona so you can have adventures together.", ua = "Прикличте Рузіону, щоб разом вирушати на пригоди." },
    { en = "Call Belastrasza so you can have adventures together.", ua = "Прикличте Беластразу, щоб разом вирушати на пригоди." },
    { en = "Call Zhusadormu so you can have adventures together.", ua = "Прикличте Жусадорму, щоб разом вирушати на пригоди." },
    { en = "Call Zalethgos so you can have adventures together.", ua = "Прикличте Залетгоса, щоб разом вирушати на пригоди." },
    { en = "Call Posidriss so you can have adventures together.", ua = "Прикличте Посідрісс, щоб разом вирушати на пригоди." },
