    { en = "Summons and dismisses a rideable Algarian Stormrider.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Алґарського Штормового Вершника.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Auspicious Arborwyrm.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Сприятливого Деревовирма.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable magical broom!  This mount changes depending on your Riding skill and location. During Hallow's End the cast time is instant.", ua = "Прикликає або відкликає верхову чарівну мітлу! Ця їздова тварина змінюється залежно від ваших навичок верхової їзди та місцеперебування. Під час Гелловіну створення миттєве." },
    { en = "Summons and dismisses Anu'relos, Flame's Guidance.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає Ану'релоса, Дороговказ Полум'я.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Flourishing Whimsydrake.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає або відкликає верхового Квітучого Примхадрейка.\n\n\n\nЦя їздова тварина може використовувати «Спільну їзду»." },
    { en = "Summons and dismisses a rideable Crimson Vulpine.", ua = "Прикликає або відкликає верхового Багряного Вульпіна." },
    { en = "Summons and dismisses a Heartseeker Mana Ray. This mount changes depending on your Riding skill and location.", ua = "Прикликає або відкликає Манового Ската Серцешукача. Ця їздова тварина змінюється залежно від ваших навичок верхової їзди та місцеперебування." },
    { en = "Summons and dismisses a rideable Jeweled Copper Scarab.", ua = "Прикликає або відкликає верхового Самоцвітного Мідного Скарабея." },
    { en = "Summons and dismisses a demonically fueled cycle.", ua = "Прикликає або відкликає демонічно живлений мотоцикл." },
    { en = "Summons and dismisses a rideable Golden Regal Scarab.", ua = "Прикликає або відкликає верхового Золотого Величного Скарабея." },
    { en = "Summons and dismisses a rideable Jeweled Sapphire Scarab.", ua = "Прикликає або відкликає верхового Самоцвітного Сапфірового Скарабея." },
    { en = "Summons and dismisses a rideable Jeweled Jade Scarab.", ua = "Прикликає або відкликає верхового Самоцвітного Нефритового Скарабея." },
    { en = "Summons and dismisses a void fueled deathcycle.", ua = "Прикликає або відкликає живлений Порожнечею мотоцикл смерті." },
    { en = "Summons and dismisses your Gilnean Prowler.", ua = "Прикликає або відкликає вашого Ґілнеанського Никача." },
    { en = "Summons and dismisses the Fur-endship Fox mount.", ua = "Прикликає або відкликає їздову тварину Хутряного Друзяку-Лиса." },
    { en = "Summons and dismisses the Soaring Sky Fox mount.", ua = "Прикликає або відкликає їздову тварину Ширяючого Небесного Лиса." },
    { en = "Summons and dismisses the Twilight Sky Prowler mount.", ua = "Прикликає та відкликає їздову тварину Сутінковий Небесний Блукач." },
    { en = "Summons and dismisses a Noble Flying Carpet. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Шляхетний Літючий Килим. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a rideable Majestic Azure Peafowl. This is a flying mount.", ua = "Прикликає та відкликає верхового Величного Лазурового Павича. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Brilliant Sunburst Peafowl. This is a flying mount.", ua = "Прикликає та відкликає верхового Осяйного Сонячного Павича. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Starry Twilight Peafowl. This is a flying mount.", ua = "Прикликає та відкликає верхового Зоряного Сутінкового Павича. Це летюча їздова тварина." },
    { en = "Summons and dismisses a rideable Savage Blue Battle Turtle. This mount swims fast and can't move very quickly on land, but it doesn't need to. It has cannons.", ua = "Прикликає та відкликає верхову Дику Синю Бойову Черепаху. Ця їздова тварина швидко плаває й не надто прудка на суходолі, та їй це й не потрібно. У неї є гармати." },
    { en = "Summons and dismisses this mount.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає та відкликає цю їздову тварину.\n\n\n\nЦя їздова тварина може користуватися сумісною їздою." },
    { en = "Summons and dismisses a rideable Voyaging Wilderling.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає та відкликає верхового Мандрівного Дикокрила.\n\n\n\nЦя їздова тварина може користуватися сумісною їздою." },
    { en = "Right Click to summon and dismiss Fathom.", ua = "Клацніть правою кнопкою, щоб прикликати чи відкликати Fathom." },
    { en = "Summons and dismisses a rideable Remembered Golden Gryphon mount. The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає та відкликає верхового Згаданого Золотого Грифона. Можливості цієї їздової тварини залежать від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a rideable Green Wind Rider mount. The capabilities of this mount depend on your Riding skill and location.", ua = "Прикликає та відкликає верхового Зеленого Вершника Вітру. Можливості цієї їздової тварини залежать від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a rideable Stonevault Mechsuit.  This is a flying mount.", ua = "Прикликає та відкликає верховий Механокостюм Кам'яного Сховку. Це летюча їздова тварина." },
    { en = "Summons and dismisses the Charming Courier mount.", ua = "Прикликає та відкликає їздову тварину Чарівний Посланець." },
    { en = "Summons and dismisses your Delver's Dirigible.\n\n\n\nThis mount can use Ride Along.", ua = "Прикликає та відкликає ваш Дирижабль Глибинника.\n\n\n\nЦя їздова тварина може використовувати «Спільну поїздку»." },
    { en = "Summons and dismisses a Kickin' Kezan Waveshredder. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Завзятий Кезанський Хвилеріз. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Creates a portal, teleporting group members that use it to Dornogal.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Дорноґала." },
    { en = "Teleports you to Dornogal.", ua = "Телепортує тебе до Дорноґала." },
    { en = "Summons and dismisses a Goblin Wave Shredder. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Гоблінський Хвилеріз. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses this mount. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає цю їздову тварину. Вона змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a Kor'kron Warsaber. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Бойового Сабельника Кор'крону. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a Nightsaber. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Нічного Сабельника. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses a Sentinel War Wolf. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Бойового Вовка Вартової. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
