    { en = "Summons and dismisses your Felscorned Wolfhawk. This mount is only available to Hunters.", ua = "Прикликає чи відпускає вашого Скверноопаленого вовкояструба. Ця їздова тварина доступна лише мисливцям." },
    { en = "Summons and dismisses your Archmage's Felscorned Disc. This mount is only available to Mages.", ua = "Прикликає чи відпускає ваш Скверноопалений диск Верховного мага. Ця їздова тварина доступна лише магам." },
    { en = "Summons and dismisses your Felscorned Grandmaster's Companion. This mount is only available to Monks.", ua = "Прикликає чи відпускає вашого Скверноопаленого супутника Великого майстра. Ця їздова тварина доступна лише монахам." },
    { en = "Summons and dismisses your Felscorned Highlord's Charger. This mount is only available to Paladins.", ua = "Прикликає чи відпускає вашого Скверноопаленого бойового коня Верховного володаря. Ця їздова тварина доступна лише паладинам." },
    { en = "Summons and dismisses your High Priest's Felscorned Seeker. This mount is only available to Priests.", ua = "Прикликає чи відпускає вашого Скверноопаленого шукача Верховного жерця. Ця їздова тварина доступна лише жерцям." },
    { en = "Summons and dismisses your Shadowblade's Felscorned Omen. This mount is only available to Rogues.", ua = "Прикликає чи відпускає вашого Скверноопаленого передвісника Тіньового клинка. Ця їздова тварина доступна лише розбійникам." },
    { en = "Summons and dismisses your Farseer's Felscorned Tempest. This mount is only available to Shamans.", ua = "Прикликає чи відпускає вашу Скверноопалену бурю Дальнозорого. Ця їздова тварина доступна лише шаманам." },
    { en = "Summons and dismisses your Felscorned Netherlord's Dreadsteed. This mount is only available to Warlocks.", ua = "Прикликає чи відпускає вашого Скверноопаленого жахливого скакуна Володаря Нижнього Світу. Ця їздова тварина доступна лише чорнокнижникам." },
    { en = "Summons and dismisses your Felscorned War Wyrm. This mount is only available to Warriors.", ua = "Прикликає чи відпускає вашого Скверноопаленого бойового вирма. Ця їздова тварина доступна лише воїнам." },
    { en = "Right Click to summon and dismiss your pet.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити вашого улюбленця." },
    { en = "Right Click to summon and dismiss Scruffbeak.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Кудлодзьоба." },
    { en = "Creates a portal, teleporting group members that use it to Silvermoon City.", ua = "Створює портал, що телепортує членів групи, які ним скористаються, до Сільвермуна." },
    { en = "Summons and dismisses the Spawn of Vyranoth. This is a flying mount.", ua = "Прикликає чи відпускає Поріддя Віранот. Це літальна їздова тварина." },
    { en = "Summons and dismisses a rideable Savage Crimson Battle Turtle. This mount swims fast and can't move very quickly on land, but it doesn't need to. It has cannons.", ua = "Прикликає чи відпускає їздову Дику багряну бойову черепаху. Ця їздова тварина швидко плаває, а на суходолі рухається повільно, та їй це й не потрібно. Адже в неї є гармати." },
    { en = "Summons and dismisses a Waveshredder. This mount changes depending on your Riding skill and location.", ua = "Прикликає чи відпускає Хвилеруба. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses the Unbound Manawyrm.  This mount changes depending on your Riding skill and location.", ua = "Прикликає чи відпускає Звільненого манавирма. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses the Magister's Spell Bee.", ua = "Прикликає чи відпускає Чаклунську бджолу магістра." },
    { en = "Right Click to summon and dismiss Nar'loka.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Нар'локу." },
    { en = "Right Click to summon and dismiss your eaglet.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити ваше орлятко." },
    { en = "Right Click to summon and dismiss Chubs.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Пухтика." },
    { en = "Right Click to summon and dismiss the Overloaded Manaling.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Перевантажене маналя." },
    { en = "Right Click to summon and dismiss Void-Bathed Snapdragon.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Скупаного в Порожнечі кусачого дракончика." },
    { en = "Right Click to summon and dismiss the Void-Infused Mindbreaker Fry.", ua = "Клацніть правою кнопкою, щоб прикликати чи відпустити Налитого Порожнечею малька-розумоламача." },
    { en = "Summons and dismisses the Voidmancer's Starcarver. This mount changes depending on your Riding skill and location.", ua = "Прикликає чи відпускає Зореруба Чаклуна Порожнечі. Ця їздова тварина змінюється залежно від вашої навички їзди та місця перебування." },
    { en = "Summons and dismisses the Netherforged Nullframe. This mount changes depending on your Riding skill and location.", ua = "Прикликає та відкликає Нетеркований Нуль-каркас. Ця їздова тварина змінюється залежно від вашого вміння їзди та місцеперебування." },
    { en = "Summons and dismisses this moumt.", ua = "Прикликає чи відпускає цю їздову тварину." },
    { en = "Shift into Bear Form and invoke the spirit of Ursol to let loose a deafening roar, incapacitating all enemies within $A1 yards for $d. Damage may cancel the effect.", ua = "Перевтілься в подобу ведмедя й заклич дух Урсола, щоб видати оглушливий рик, який приголомшує всіх ворогів у межах $A1 м на $d. Шкода може скасувати ефект." },
    { en = "Purges the enemy target, removing $m1 beneficial Magic $leffect:effects;.$?(s147762&s51530)\n\n[ Successfully purging a target grants a stack of Maelstrom Weapon.][]", ua = "Вичищає ворожу ціль, знімаючи $m1 корисний магічний $lефект:ефекти;.$?(s147762&s51530)\n\n[ Успішне вичищення цілі надає заряд Зброї виру.][]" },
    { en = "Removes all Curses from a friendly target. $?s115700[If any Curses are successfully removed, you deal $115701s1% additional damage for $115701d.][]", ua = "Знімає всі Прокляття з дружньої цілі. $?s115700[Якщо будь-яке Прокляття успішно знято, ви завдаєте на $115701s1% більше шкоди протягом $115701d.][]" },
    { en = "Dispels Magic on the enemy target, removing $m1 beneficial Magic $leffect:effects;.", ua = "Розвіює магію на ворожій цілі, знімаючи $m1 корисний магічний $leffect:ефект:ефекти;." },
    { en = "Fade out, removing all your threat and reducing enemies' detection range against you for $d.", ua = "Ти зникаєш, скидаючи всю свою загрозу та зменшуючи відстань, з якої вороги тебе помічають. Триває $d." },
    { en = "A powerful prayer that heals your target and ${$s3-1} injured allies within $A2 yards for $s2.", ua = "Могутня молитва, що зцілює твою ціль і ${$s3-1} поранених союзників у радіусі $A2 м на $s2." },
    { en = "Controls a mind up to 1 level above yours for $d. Does not work versus Demonic$?A320889[][, Undead,] or Mechanical beings. Shares diminishing returns with other disorienting effects.", ua = "Підкоряє розум істоти до 1 рівня вище за ваш протягом $d. Не діє на демонічних$?A320889[][, неживих] чи механічних істот. Має спільне послаблення дії з іншими ефектами дезорієнтації." },
    { en = "Banishes an enemy Demon, Aberration$?s386651[, Undead][], or Elemental, preventing any action for $d. Limit 1. Casting Banish again on the target will cancel the effect.", ua = "Виганяє ворожого демона, аберацію$?s386651[, нежить][] або елементаля, не даючи виконувати жодних дій протягом $d. Ліміт 1. Повторне творіння Вигнання на цілі скасує ефект." },
    { en = "Lash out with your weapon, striking all targets within $A1 yds for $s1 Physical damage instantly and wounding them for an additional $388539o1 Bleed damage over $388539d.", ua = "Шмагаєш зброєю всі цілі в радіусі $A1 м, миттєво завдаючи $s1 фізичної шкоди та ранячи їх, що спричиняє додаткових $388539o1 шкоди від кровотечі протягом $388539d." },
    { en = "Heals the target for $o1 over $d.$?s155675[\n\n\n\nYou can apply Rejuvenation twice to the same target.][]$?s33891[\n\n\n\n|C0033AA11Tree of Life: Healing increased by $5420s5% and Mana cost reduced by $5420s4%.|R][]", ua = "Зцілює ціль на $o1 упродовж $d.$?s155675[\n\n\n\nВи можете накласти Омолодження двічі на одну ціль.][]$?s33891[\n\n\n\n|C0033AA11Дерево життя: зцілення збільшено на $5420s5%, а витрати мани зменшено на $5420s4%.|R][]" },
    { en = "Strikes all enemies in front of you for $s1 Physical damage. Deals reduced damage beyond $s2 targets.", ua = "Б'є всіх ворогів перед тобою, завдаючи $s1 фізичної шкоди. Понад $s2 цілей шкоду зменшено." },
    { en = "Reduces all damage you take by $s1% for $d.", ua = "Зменшує всю отримувану тобою шкоду на $s1% на $d." },
    { en = "Protects the target with an earthen shield, increasing your healing on them by $s1% and healing them for ${$379s1*(1+$s1/100)} when they take damage. This heal can only occur once every $?a462454[${$proccooldown+($462454s2/1000)}.1][$proccooldown] sec. $?a1217622[Lasts $d][Maximum $u charges].\n\n\n\n$?s383010[Earth Shield can only be placed on the Shaman and one other target at a time. The Shaman can have up to two Elemental Shields active on them.][Earth Shield can only be placed on one target at a time. Only one Elemental Shield can be active on the Shaman.]", ua = "Захищає ціль земляним щитом, збільшуючи ваше зцілення цілі на $s1% і зцілюючи її на ${$379s1*(1+$s1/100)}, коли вона отримує шкоду. Це зцілення може спрацювати лише раз на $?a462454[${$proccooldown+($462454s2/1000)}.1][$proccooldown] с. $?a1217622[Триває $d][Щонайбільше $u зарядів].\n\n\n\n$?s383010[Щит землі можна накласти лише на шамана та одну іншу ціль водночас. Шаман може мати до двох активних стихійних щитів на собі.][Щит землі можна накласти лише на одну ціль водночас. На шамані може бути активним лише один стихійний щит.]" },
    { en = "Inflicts increasing agony on the target, causing up to ${$s1*$d/$t1*$u} Shadow damage over $d. Damage starts low and increases over the duration. Refreshing Agony maintains its current damage level.\n\n\n\n|cFFFFFFFFAgony damage sometimes generates 1 Soul Shard.|r", ua = "Завдає цілі дедалі сильнішої агонії, спричиняючи до ${$s1*$d/$t1*$u} шкоди від тіні впродовж $d. Спершу шкода невелика, але зростає протягом дії. Поновлення Агонії зберігає її поточний рівень шкоди.\n\n\n\n|cFFFFFFFFШкода від Агонії подеколи створює 1 Уламок душі.|r" },
    { en = "Heals the friendly target for $s1, then jumps up to $?a236502[${$s3*(($236502s2/100)+1)}][$s3] yards to heal the $<jumps> most injured nearby allies. Healing is reduced by $s2% with each jump.", ua = "Зцілює дружню ціль на $s1, а потім перестрибує до $?a236502[${$s3*(($236502s2/100)+1)}][$s3] м, щоб зцілити $<jumps> найтяжче поранених союзників поблизу. Зцілення зменшується на $s2% з кожним стрибком." },
    { en = "Finishing move that causes Bleed damage over time. Lasts longer per combo point.\n\n\n\n   1 point  : ${$o1*2/6} over ${$d*2/6} sec\n\n   2 points: ${$o1*3/6} over ${$d*3/6} sec\n\n   3 points: ${$o1*4/6} over ${$d*4/6} sec\n\n   4 points: ${$o1*5/6} over ${$d*5/6} sec\n\n   5 points: ${$o1*6/6} over ${$d*6/6} sec", ua = "Завершальний прийом, що завдає шкоди від кровотечі з часом. Триває довше за кожне комбо-очко.\n\n\n\n   1 очко  : ${$o1*2/6} протягом ${$d*2/6} сек\n\n   2 очки: ${$o1*3/6} протягом ${$d*3/6} сек\n\n   3 очки: ${$o1*4/6} протягом ${$d*4/6} сек\n\n   4 очки: ${$o1*5/6} протягом ${$d*5/6} сек\n\n   5 очок: ${$o1*6/6} протягом ${$d*6/6} сек" },
    { en = "Summons an Infernal from the Twisting Nether, impacting for $22703s1 Fire damage and stunning all enemies in the area for $22703d.\n\n\n\nThe Infernal will serve you for $111685d, dealing ${$20153s1*(100+$137046s3)/100} damage to all nearby enemies every $19483t1 sec and generating $264365s1 Soul Shard Fragment every $264364t1 sec.", ua = "Прикликає інфернала з Круговерті Порожнечі, який при ударі завдає $22703s1 шкоди від вогню й приголомшує всіх ворогів у ділянці на $22703d.\n\n\n\nІнфернал служитиме вам впродовж $111685d, завдаючи ${$20153s1*(100+$137046s3)/100} шкоди всім ворогам поблизу кожні $19483t1 сек і створюючи $264365s1 Уламок душі кожні $264364t1 сек." },
    { en = "$?s199023[Demoralizes all enemies within $A2 yards, reducing the damage they do by $s2% for $d.][Demoralizes all enemies within $A2 yards, reducing the damage they deal to you by $s1% for $d.]$?s202743[\n\n\n\n|cFFFFFFFFGenerates ${$m5/10} Rage.|r][]", ua = "$?s199023[Деморалізує всіх ворогів у радіусі $A2 м, зменшуючи завдавану ними шкоду на $s2% протягом $d.][Деморалізує всіх ворогів у радіусі $A2 м, зменшуючи завдавану ними вам шкоду на $s1% протягом $d.]$?s202743[\n\n\n\n|cFFFFFFFFСтворює ${$m5/10} люті.|r][]" },
    { en = "Scares a beast, causing it to run in fear for up to $d.  Damage caused may interrupt the effect.  Only one beast can be feared at a time.", ua = "Лякає звіра, змушуючи його тікати в страху до $d. Отримана шкода може перервати ефект. Одночасно можна налякати лише одного звіра." },
    { en = "Forces the target to speak in Demonic, increasing the casting time of all spells by $s1% for $d.$?s103112[\n\n\n\n|CFFE55BB0Soulburn: Your Curse of Tongues will affect all enemies in a $104224A yard radius around your target.|R][]\n\n\n\n|cFF8282FFCurses: A warlock can only have one Curse active per target.|r", ua = "Змушує ціль говорити демонічною мовою, збільшуючи час творення всіх заклять на $s1% протягом $d.$?s103112[\n\n\n\n|CFFE55BB0Спалення душі: ваше Прокляття язиків діятиме на всіх ворогів у радіусі $104224A ярдів навколо вашої цілі.|R][]\n\n\n\n|cFF8282FFПрокляття: чорнокнижник може мати лише одне активне Прокляття на ціль.|r" },
    { en = "Go berserk, increasing all Rage generation by $s1% and granting your abilities $s4% increased critical strike chance for $d.$?a396749[\n\n\n\n|cFFFFFFFFGenerates ${$s3/10} Rage.|r][]", ua = "Впадіть у нестяму, збільшуючи всю генерацію люті на $s1% та надаючи своїм здібностям на $s4% більший шанс критичного удару протягом $d.$?a396749[\n\n\n\n|cFFFFFFFFГенерує ${$s3/10} люті.|r][]" },
    { en = "Gouges the eyes of an enemy target, incapacitating for $d. Damage may interrupt the effect.\n\n\n\nMust be in front of your target.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Тиче ворогові в очі, знешкоджуючи його на $d. Шкода може перервати ефект.\n\n\n\nТи маєш бути перед ціллю.\n\n\n\n|cFFFFFFFFНадає $s2 $lочко комбо:очок комбо;.|r" },
    { en = "Rake the target for $s1 Bleed damage and an additional $155722o1 Bleed damage over $155722d.$?s48484[ Reduces the target's movement speed by $58180s1% for $58180d.][]$?a231052[ \n\n\n\nWhile stealthed, Rake will also stun the target for $163505d and deal $s4% increased damage.][]$?a405834[ \n\n\n\nWhile stealthed, Rake will also stun the target for $163505d and deal $s4% increased damage.][]\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Дряпає ціль, завдаючи $s1 шкоди кровотечею і ще $155722o1 шкоди кровотечею впродовж $155722d.$?s48484[ Зменшує швидкість руху цілі на $58180s1% на $58180d.][]$?a231052[ \n\n\n\nПід час скрадання Дряпання також приголомшує ціль на $163505d і завдає на $s4% більше шкоди.][]$?a405834[ \n\n\n\nПід час скрадання Дряпання також приголомшує ціль на $163505d і завдає на $s4% більше шкоди.][]\n\n\n\n|cFFFFFFFFНадає $s2 комбо-$lочко:очки:очок;.|r" },
    { en = "Perform a miracle, healing an ally for $s1.\n\n\n\n|cFFFFFFFFCooldown reduced by $s2 sec when you cast Flash Heal$?a1246517[ or Prayer of Healing][].|r", ua = "Творить диво, зцілюючи союзника на $s1.\n\n\n\n|cFFFFFFFFПерезарядження зменшується на $s2 сек., коли ви творите Швидке зцілення$?a1246517[ або Молитовне зцілення][].|r" },
    { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage. Deals reduced damage beyond $s2 targets.$?a205037[\n\n\n\nLeaves behind a patch of flames that burns enemies within it for ${$205470d*$205472s1} Fire damage over $205470d.][]\n\n\n\n|cFFFFFFFFThis spell is cast at a selected location.|r", ua = "Прикликає стовп вогню, обпалюючи всіх ворогів у зоні на $s1 вогняної шкоди. Завдає зменшеної шкоди при понад $s2 цілях.$?a205037[\n\n\n\nЗалишає по собі смугу полум'я, що обпалює ворогів у ній на ${$205470d*$205472s1} вогняної шкоди протягом $205470d.][]\n\n\n\n|cFFFFFFFFЦе закляття твориться на обране місце.|r" },
    { en = "Forces the enemy target to sleep for up to $d. Any damage will awaken the target. Only one target can be forced to hibernate at a time. Only works on Beasts and Dragonkin.", ua = "Змушує ворожу ціль заснути на час до $d. Будь-яка шкода розбудить ціль. Приспати можна лише одну ціль водночас. Діє тільки на звірів і драконідів." },
    { en = "Nullifies corrupting effects on the friendly target, removing all Curse and Poison effects.", ua = "Нейтралізує згубні ефекти на дружній цілі, знімаючи всі ефекти проклять і отрут." },
    { en = "Soothes the target, dispelling all enrage effects.", ua = "Заспокоює ціль, розвіюючи всі ефекти розлюченості." },
    { en = "Scorches an enemy for $s1 Fire damage.\n\n\n\nWhen cast on a target below $s2% health, Scorch is a guaranteed critical strike.\n\n\n\nCastable while moving.", ua = "Обпалює ворога на $s1 вогняної шкоди.\n\n\n\nКоли твориться на цілі, у якої менше ніж $s2% здоров'я, Обпалення гарантовано завдає критичного удару.\n\n\n\nМожна творити під час руху." },
    { en = "Run at high speed toward an ally, intercepting all melee and ranged attacks against them for $147833d while they remain within $147833A1 yds.", ua = "Біжиш на високій швидкості до союзника й протягом $147833d перехоплюєш усі атаки ближнього та дальнього бою проти нього, поки він лишається в межах $147833A1 м." },
    { en = "Dazes the target, slowing movement speed by $s1% for $d.$?a137015[\n\n\n\nCobra Shot will increase the duration of Concussive Shot on the target by ${$56641m3/10}.1 sec.]?a137016[\n\n\n\nSteady Shot will increase the duration of Concussive Shot on the target by ${$56641m3/10}.1 sec.][]", ua = "Приголомшує ціль, сповільнюючи її швидкість пересування на $s1% на $d.$?a137015[\n\n\n\nПостріл кобри подовжує дію Приголомшливого пострілу на цілі на ${$56641m3/10}.1 сек.]?a137016[\n\n\n\nВивірений постріл подовжує дію Приголомшливого пострілу на цілі на ${$56641m3/10}.1 сек.][]" },
    { en = "|cFFFFFFFFRequires Clearcasting|r\n\nLaunches ${($d/$t1)+1} waves of Arcane Missiles at the enemy over $5143d, causing a total of ${($d/$t1)*$7268s1} Arcane damage.", ua = "|cFFFFFFFFПотрібне Ясновидіння|r\n\nВипускає у ворога ${($d/$t1)+1} хвиль Арканних снарядів протягом $5143d, завдаючи загалом ${($d/$t1)*$7268s1} арканної шкоди." },
    { en = "Invokes the spirit of Ursoc to stun the target for $d. Usable in all shapeshift forms.", ua = "Прикликає дух Урсока, щоб приголомшити ціль на $d. Можна використовувати в усіх подобах." },
    { en = "Instantly restores $s2 Energy, and increases the damage of all your attacks by $s1% for their full duration. Lasts $d.", ua = "Миттєво відновлює $s2 енергії та збільшує шкоду всіх твоїх атак на $s1% на всю їхню тривалість. Триває $d." },
    { en = "Causes the targeted enemy to cower in fear while all enemies within $a5 yards flee from you and their movement speed is reduced by $s3% for $d.\n\nDamage may cancel the effect.", ua = "Змушує ціль-ворога зіщулитися від страху, а всі вороги в межах $a5 м тікають від тебе, і їхня швидкість пересування зменшується на $s3% на $d.\n\nШкода може скасувати ефект." },
    { en = "Let loose a terrifying howl, causing $?a1270255[${$i+$1270255s4}][$i] enemies within $A1 yds to flee in fear, disorienting them for $d. Damage may cancel the effect.", ua = "Видаєте жахливе виття, змушуючи $?a1270255[${$i+$1270255s4}][$i] ворогів у межах $A1 ярд тікати в страху та дезорієнтуючи їх на $d. Шкода може скасувати цей ефект." },
    { en = "Calls down a rain of hellfire the target location, dealing ${$42223m1*8} Fire damage over $d to enemies in the area.\n\n\n\n|cFFFFFFFFThis spell is cast at a selected location.|r", ua = "Прикликає дощ пекельного вогню на вказане місце, завдаючи ${$42223m1*8} шкоди від вогню впродовж $d ворогам у цій ділянці.\n\n\n\n|cFFFFFFFFЦе закляття твориться у вибраному місці.|r" },
    { en = "Blasts all enemies within $A1 yards for $s1 Physical damage$?s199045[, roots them for $199042d,][] and reduces their movement speed by $435203s1% for $435203d. Deals reduced damage beyond $s5 targets.$?s772[\n\n\n\nInflicts Rend on all targets.][\n\n\n\nIf you know Rend, inflicts Rend on all targets.]$?a137048|(a137050&a436707)[\n\n\n\n|cFFFFFFFFGenerates ${$s4/10} Rage.][]", ua = "Вражає всіх ворогів у радіусі $A1 м на $s1 фізичної шкоди$?s199045[, прикорінює їх на $199042d,][] і зменшує їхню швидкість руху на $435203s1% протягом $435203d. Завдає зменшеної шкоди понад $s5 цілей.$?s772[\n\n\n\nНакладає Шматування на всіх цілей.][\n\n\n\nЯкщо ви знаєте Шматування, накладає його на всіх цілей.]$?a137048|(a137050&a436707)[\n\n\n\n|cFFFFFFFFСтворює ${$s4/10} люті.][]" },
    { en = "Burns the enemy's soul, dealing $s1 Fire damage and applying $?a445465[Wither][Immolate].\n\n\n\n|cFFFFFFFFGenerates ${$281490s1/10} Soul Shard.|r", ua = "Спалює душу ворога, завдаючи $s1 вогняної шкоди й накладаючи $?a445465[Усихання][Спопеляння].\n\n\n\n|cFFFFFFFFПороджує ${$281490s1/10} уламка душі.|r" },
    { en = "Swing in a wide arc, dealing $s1 Physical damage to all enemies in front of you. Deals reduced damage beyond $<cap> targets.\n\n\n\nYour successful dodges and parries have a chance to make your next Revenge cost no Rage.", ua = "Замахуєшся широкою дугою, завдаючи $s1 фізичної шкоди всім ворогам перед тобою. Завдає зменшеної шкоди після $<cap> цілей.\n\n\n\nТвої успішні ухилення та парирування мають шанс зробити твою наступну Помсту безкоштовною щодо люті." },
    { en = "Horrifies an enemy target into fleeing, incapacitating for $6789d and healing you for $108396m1% of maximum health.", ua = "Сповнює ворожу ціль жаху, змушуючи її тікати: знерухомлює на $6789d і зцілює тебе на $108396m1% максимального здоров'я." },
    { en = "Maul the target for $s2 Physical damage.", ua = "Трощить ціль, завдаючи $s2 фізичної шкоди." },
    { en = "Overpower the enemy, dealing $s1 Physical damage. Cannot be blocked, dodged, or parried.$?s316440&s845[\n\n\n\nIncreases the damage of your next Mortal Strike or Cleave by $s2%, stacking up to $u times]?s316440[\n\n\n\nIncreases the damage of your next Mortal Strike by $s2%, stacking up to $u times.][]$?s400801[\n\n\n\n|cFFFFFFFFGenerates ${$7384s3/10} Rage.][]", ua = "Пересильте ворога, завдаючи $s1 фізичної шкоди. Не можна заблокувати, ухилитися чи парирувати.$?s316440&s845[\n\n\n\nЗбільшує шкоду вашого наступного Смертельного удару або Розсічення на $s2%, накопичуючись до $u разів]?s316440[\n\n\n\nЗбільшує шкоду вашого наступного Смертельного удару на $s2%, накопичуючись до $u разів.][]$?s400801[\n\n\n\n|cFFFFFFFFГенерує ${$7384s3/10} люті.][]" },
    { en = "Instantly shocks the target with concussive force, causing $s1 Nature damage.$?a190493[\n\n\n\nEarth Shock will consume all stacks of Fulmination to deal extra Nature damage to your target.][]", ua = "Миттєво вражає ціль приголомшливою силою, завдаючи $s1 шкоди природою.$?a190493[\n\n\n\nЗемляний шок споживає всі заряди Спалаху, щоб завдати додаткової шкоди природою вашій цілі.][]" },
    { en = "Blast the target's mind for $s1 Shadow damage.$?c1[ Costs a high amount of mana.][]$?s137033[\n\n\n\n|cFFFFFFFFGenerates ${$s2/100} Insanity.|r][]", ua = "Вражає розум цілі, завдаючи $s1 шкоди Тінню.$?c1[ Коштує багато мани.][]$?s137033[\n\n\n\n|cFFFFFFFFДає ${$s2/100} Безумства.|r][]" },
    { en = "Lets out a psychic scream, causing all enemies within $A1 yards to flee, disorienting them for $d. Damage may interrupt the effect.", ua = "Видає психічний крик, що змушує всіх ворогів у радіусі $A1 м тікати, дезорієнтуючи їх на $d. Шкода може перервати цей ефект." },
    { en = "Summons a totem at your feet that shakes the ground around it for $d, removing Fear, Charm and Sleep effects from party and raid members within $8146a1 yards.", ua = "Прикликає тотем біля твоїх ніг, що протягом $d стрясає землю довкола себе, знімаючи ефекти страху, зачарування та сну з членів групи й рейду в радіусі $8146a1 м." },
    { en = "Shackles an aberration or undead enemy for $d, preventing all actions and movement. Damage will cancel the effect. Limit 1.", ua = "Сковує аберацію або ворожу нежить на $d, не даючи їй діяти й рухатися. Шкода скасовує ефект. Не більше 1 цілі." },
    { en = "Infuses the target with power for $d, increasing haste by $s1%.\n\n\n\nCan only be cast on players.", ua = "Наповнює ціль силою протягом $d, збільшуючи поспіх на $s1%.\n\n\n\nМожна творити лише на гравцях." },
    { en = "Hurls an immense fiery boulder that causes $s1 Fire damage$?a321711[ and an additional $321712o2 Fire damage over $321712d][].", ua = "Кидає величезний вогняний валун, що завдає $s1 шкоди Вогнем$?a321711[ та додатково $321712o2 шкоди Вогнем протягом $321712d][]." },
    { en = "Shields you with ice, absorbing $<shield> damage$?s235297[ and increasing your armor by $s3%][] for $d.\n\n\n\nMelee attacks against you reduce the attacker's movement speed by $205708s1%.", ua = "Захищає вас кригою, поглинаючи $<shield> шкоди$?s235297[ і підвищуючи вашу броню на $s3%][] протягом $d.\n\n\n\nАтаки ближнього бою проти вас зменшують швидкість пересування нападника на $205708s1%." },
    { en = "Increases your mana regeneration by $s1% for $d.", ua = "Підвищує відновлення мани на $s1% на $d." },
    { en = "A vicious strike that deals $s1 Physical damage and reduces the effectiveness of healing on the target by $115804s1% for $115804d.", ua = "Жорстокий удар, що завдає $s1 фізичної шкоди та зменшує ефективність зцілення цілі на $115804s1% на $115804d." },
    { en = "Snares all enemies within $A1 yards, reducing their movement speed by $s1% for $d.\n\n\n\nSpurs all allies within $1244157A1 yards, increasing their movement speed by $1244157s1% for $1244157d.", ua = "Уловлює всіх ворогів у межах $A1 м, зменшуючи їхню швидкість пересування на $s1% на $d.\n\n\n\nПідганяє всіх союзників у межах $1244157A1 м, збільшуючи їхню швидкість пересування на $1244157s1% на $1244157d." },
    { en = "Whirlwind $?s436707[and Thunder Clap cause][causes] your next $85739u single-target $lattack:attacks; to strike up to $85739s1 additional targets for $85739s2% damage.\n\n\n\nWhirlwind generates $190411s1 Rage plus an additional $190411s2 per target hit. Maximum $<maxRage> Rage.\n\n\n\nIf you know Rend, Whirlwind inflicts Rend on all targets.", ua = "Вихор $?s436707[і Громовий удар змушують][змушує] ваші наступні $85739u $lатаки по одній цілі:атак по одній цілі; уражати до $85739s1 додаткових цілей із $85739s2% шкоди.\n\n\n\nВихор генерує $190411s1 люті плюс додатково $190411s2 за кожну уражену ціль. Максимум $<maxRage> люті.\n\n\n\nЯкщо ви володієте Шматуванням, Вихор завдає Шматування всім цілям." },
    { en = "Increases your Energy regeneration rate by $s1%, your maximum Energy by $s6, and your attack speed by $s2% for $d.$?$s4>0[\n\n\n\nDamage of combo point generating abilities and finishers increased by $s4%.][]", ua = "Підвищує швидкість відновлення Енергії на $s1%, максимальну Енергію на $s6 і швидкість атаки на $s2% на $d.$?$s4>0[\n\n\n\nШкода здібностей, що генерують очки комбо, та завершальних прийомів зростає на $s4%.][]" },
    { en = "Your finishing moves have a $b1% chance per combo point spent to grant a combo point.", ua = "Завершальні прийоми мають $b1% шансу за кожне витрачене очко комбо дати тобі очко комбо." },
    { en = "Critical strikes with attacks that generate combo points grant an additional combo point per critical strike.", ua = "Критичні удари атаками, що створюють очки комбо, дають додаткове очко комбо за кожен критичний удар." },
    { en = "Consumes the enemy in Holy flames that cause $s1 Holy damage and an additional $o2 Holy damage over $d.$?a231687[ Stacks up to $u times.][]", ua = "Поглинає ворога святим полум'ям, що завдає $s1 шкоди Світлом і додатково $o2 шкоди Світлом протягом $d.$?a231687[ Накопичується до $u разів.][]" },
    { en = "Increases your maximum Energy by $s1 and Energy regeneration by $s2%.", ua = "Збільшує максимум енергії на $s1, а відновлення енергії — на $s2%." },
    { en = "Casting Lava Burst increases the damage or healing of your next Nature$?a137039[][, Physical,] or Frost spell by $s2%.", ua = "Творення Виверження лави підвищує шкоду чи зцілення вашого наступного закляття Природи$?a137039[][, Фізичного,] чи Морозу на $s2%." },
    { en = "Your direct heal criticals refund a percentage of your maximum mana: $<healingwave>% from Healing Wave, $<riptide>% from Riptide, and $<chainheal>% from Chain Heal.", ua = "Ваші критичні влучання прямими зціленнями повертають відсоток вашої максимальної мани: $<healingwave>% від Хвилі зцілення, $<riptide>% від Припливної хвилі та $<chainheal>% від Ланцюгового зцілення." },
    { en = "Your auto attacks have a $?s236068[high ][]chance to cause a Clearcasting state, making your next Shred or $?s202028[Brutal Slash][Swipe] cost no Energy$?s236068[ and deal $236068s4% more damage][].$?s236068[\n\n\n\nClearcasting can accumulate up to ${$s135700u+$236068s1} charges.][]", ua = "Ваші автоатаки мають $?s236068[високий ][]шанс викликати стан Ясності, завдяки якому ваше наступне Шматування чи $?s202028[Жорстокий удар][Помах лапи] не коштуватиме енергії$?s236068[ і завдасть на $236068s4% більше шкоди][].$?s236068[\n\n\n\nЯсність може накопичувати до ${$s135700u+$236068s1} зарядів.][]" },
    { en = "Reduces all damage taken by $s1%.", ua = "Зменшує всю отримувану шкоду на $s1%." },
    { en = "Blasts a target for $s1 Shadowflame damage. Only usable on enemies that have less than $s4% health.\n\n\n\n|cFFFFFFFFRestores ${$245731s1/10} Soul Shard and refunds a charge if the target dies within $d.|r", ua = "Вражає ціль, завдаючи $s1 шкоди тіньовим полум'ям. Застосовується лише на ворогах, у яких менше ніж $s4% здоров'я.\n\n\n\n|cFFFFFFFFВідновлює ${$245731s1/10} Уламок душі та повертає заряд, якщо ціль гине протягом $d.|r" },
    { en = "Triggers an explosion on the target, dealing $s1 Fire damage.$?s196406[\n\n\n\nReduces the cast time of your next Incinerate or Chaos Bolt by $117828s1% for $117828d.][]\n\n\n\n|cFFFFFFFFGenerates $245330s1 Soul Shard Fragments.|r", ua = "Спричиняє вибух на цілі, завдаючи $s1 шкоди Вогнем.$?s196406[\n\n\n\nЗменшує час прочитання вашого наступного Спопеляння або Стріли хаосу на $117828s1% протягом $117828d.][]\n\n\n\n|cFFFFFFFFСтворює $245330s1 фрагментів уламка душі.|r" },
    { en = "$?s392410[Extend the duration of your heal over time effects by $392410s1 sec and][Consume a Regrowth, Wild Growth, or Rejuvenation effect to] instantly heal an ally for $s1.", ua = "$?s392410[Подовжує тривалість твоїх ефектів поступового зцілення на $392410s1 сек. і][Поглинає ефект «Відростання», «Дикого росту» чи «Омолодження» та] миттєво зцілює союзника на $s1." },
    { en = "Increases maximum health by $?s373450[${$s1+$373450s1}][$s1]% for $?a458718[${($458718s1+$s4)/1000}][${$s4/1000}] sec, and instantly heals you for that amount.", ua = "Підвищує максимальне здоров'я на $?s373450[${$s1+$373450s1}][$s1]% на $?a458718[${($458718s1+$s4)/1000}][${$s4/1000}] с і миттєво зцілює вас на цю величину." },
    { en = "A powerful aimed shot that $?a1273128[critically strikes, dealing ${$s1*2} Physical damage][deals $s1 Physical damage].", ua = "Потужний прицільний постріл, що $?a1273128[завдає критичного удару, завдаючи ${$s1*2} фізичної шкоди][завдає $s1 фізичної шкоди]." },
    { en = "Removes $s1 Enrage and $s2 Magic effect from an enemy target.", ua = "Знімає $s1 ефект люті та $s2 магічний ефект із ворожої цілі." },
    { en = "Finishing move that causes Physical damage and stuns the target. Damage and duration increased per combo point:\n\n\n\n   1 point  : ${$s2*1} damage, 1 sec\n\n   2 points: ${$s2*2} damage, 2 sec\n\n   3 points: ${$s2*3} damage, 3 sec\n\n   4 points: ${$s2*4} damage, 4 sec\n\n   5 points: ${$s2*5} damage, 5 sec", ua = "Завершальний прийом, що завдає фізичної шкоди та приголомшує ціль. Шкода й тривалість збільшуються за кожне комбо-очко:\n\n\n\n   1 очко  : ${$s2*1} шкоди, 1 сек\n\n   2 очки: ${$s2*2} шкоди, 2 сек\n\n   3 очки: ${$s2*3} шкоди, 3 сек\n\n   4 очки: ${$s2*4} шкоди, 4 сек\n\n   5 очок: ${$s2*5} шкоди, 5 сек" },
    { en = "Heals you for $o1% health over $d$?s301768[, and increases healing received by $301768s1%][].", ua = "Зціляє тебе на $o1% здоров'я протягом $d$?s301768[, а також збільшує отримуване зцілення на $301768s1%][]." },
    { en = "Assault the target in a bloodthirsty craze, dealing $s1 Physical damage and restoring $117313s1% of your health.\n\n\n\n|cFFFFFFFFGenerates ${$s2/10} Rage and has a $s3% chance to Enrage you.|r", ua = "Атакуєш ціль у кровожерному шаленстві, завдаючи $s1 фізичної шкоди й відновлюючи $117313s1% свого здоров'я.\n\n\n\n|cFFFFFFFFСтворює ${$s2/10} люті й має $s3% шансу розлютити тебе.|r" },
    { en = "Raise your $?c3[shield][weapon], reflecting $?a213915[the next $213915s3 spells cast][the first spell cast] on you and reducing magic damage you take by $385391s1% for $d.", ua = "Здіймаєте $?c3[щит][зброю], віддзеркалюючи $?a213915[наступні $213915s3 заклять, спрямовані][перше закляття, спрямоване] на вас, і знижуєте отримувану магічну шкоду на $385391s1% протягом $d." },
    { en = "Shapeshift into $?s114301[Astral Form][Moonkin Form], increasing the damage of your spells by $s9% and your armor by $m3%, and granting protection from Polymorph effects.$?a231042[\n\n\n\nWhile in this form, single-target attacks against you have a $h% chance to make your next Starfire instant.][]\n\n\n\nThe act of shapeshifting frees you from movement impairing effects.", ua = "Перевтілює вас у $?s114301[астральну подобу][подобу місяцерода], збільшуючи шкоду ваших заклять на $s9%, а броню — на $m3%, і надаючи захист від ефектів Перетворення.$?a231042[\n\n\n\nУ цій подобі атаки по одній цілі проти вас мають $h% шанс зробити ваш наступний Зоряний вогонь миттєвим.][]\n\n\n\nСамé перевтілення звільняє вас від ефектів, що обмежують рух." },
    { en = "Embeds a demon seed in the enemy target that will explode after $d, dealing $27285s1 Shadow damage to all enemies within $27285A1 yards and applying $?a445465[Wither][Corruption] to them. Damage reduced beyond $s4 targets.\n\n\n\nThe seed will detonate early if the target is hit by other detonations, or takes ${$SPS*$s1/100} damage from your spells.", ua = "Вживляє демонічне зерно у ворожу ціль, яке вибухне через $d, завдаючи $27285s1 тіньової шкоди всім ворогам у радіусі $27285A1 ярдів і накладаючи на них $?a445465[Усихання][Розтління]. Шкода зменшується після $s4 цілей.\n\n\n\nЗерно здетонує раніше, якщо ціль зачепить інші детонації або вона отримає ${$SPS*$s1/100} шкоди від ваших заклять." },
    { en = "Infuse a friendly healer with energy, allowing them to cast spells without spending mana for $d.$?s326228[\n\n\n\nIf cast on somebody else, you gain the effect at $326228s1% effectiveness.][]", ua = "Наповнює дружнього цілителя енергією, дозволяючи йому творити закляття без витрат мани впродовж $d.$?s326228[\n\n\n\nЯкщо застосовано на когось іншого, ви отримуєте ефект з $326228s1% дієвості.][]" },
    { en = "Your attacks have a chance to make your next $?a317320[Condemn][Execute] $?c1[cost no Rage, ][]be usable on any target regardless of their health$?c1[, and deal damage as if you spent $s1 Rage][].", ua = "Ваші атаки мають шанс зробити ваш наступний $?a317320[«Осуд»][«Страту»] $?c1[без витрат люті, ][]придатним до будь-якої цілі незалежно від її здоров'я$?c1[ і завдати шкоди так, ніби ви витратили $s1 люті][]." },
    { en = "Restores $202147s1% health every $202147t1 sec when you have not taken damage for ${$s1/1000} sec.\n\n\n\nRestores $458245s3% health every $458245t1 sec while you are below $458245s2% health. The amount restored increases the closer you are to death.", ua = "Відновлює $202147s1% здоров'я кожні $202147t1 сек., коли ти не отримував шкоди протягом ${$s1/1000} сек.\n\n\n\nВідновлює $458245s3% здоров'я кожні $458245t1 сек., поки твоє здоров'я нижче $458245s2%. Відновлювана кількість зростає, що ближче ти до смерті." },
    { en = "Summons a Felguard under your command as a powerful melee combatant.", ua = "Викликає вартового Скверни, що стає під твою команду як могутній боєць ближнього бою." },
    { en = "Stuns all enemies within $a1 yds for $d.", ua = "Приголомшує всіх ворогів у радіусі $a1 м на $d." },
    { en = "Steals $?s198100[all beneficial magic effects from the target. These effects lasts a maximum of 2 min][a beneficial magic effect from the target. This effect lasts a maximum of 2 min].", ua = "Краде $?s198100[всі корисні магічні ефекти з цілі. Ці ефекти тривають щонайбільше 2 хв][корисний магічний ефект із цілі. Цей ефект триває щонайбільше 2 хв]." },
    { en = "Quickly fling a shard of ice at the target, dealing $228598s1 Frost damage.\n\n\n\n|CFFffffffShatters $1246769s4 stacks of Freezing.|R", ua = "Швидко жбурляє в ціль уламок криги, завдаючи $228598s1 шкоди від морозу.\n\n\n\n|CFFffffffРозтрощує $1246769s4 нашарування Заморожування.|R" },
    { en = "When your health is brought below $s1%, you instantly heal for ${$31616s1*(1+$s2/100)}% of your maximum health. Cannot occur more than once every $445698d.", ua = "Коли твоє здоров'я падає нижче $s1%, ти миттєво зцілюєшся на ${$31616s1*(1+$s2/100)}% від максимального здоров'я. Не може спрацьовувати частіше, ніж раз на $445698d." },
    { en = "Fatal attacks instead reduce you to $s2% of your maximum health. For $45182d afterward, you take $45182s1% reduced damage. Cannot trigger more often than once per $45181d.", ua = "Смертельні атаки натомість знижують твоє здоров'я до $s2% від максимуму. Протягом наступних $45182d ти отримуєш на $45182s1% менше шкоди. Не може спрацьовувати частіше, ніж раз на $45181d." },
    { en = "Enemies in a $s3 yd cone in front of you take $s2 Fire damage and are disoriented for $d. Damage will cancel the effect.$?a235870[\n\n\n\nAlways deals a critical strike and contributes to Hot Streak.][]", ua = "Вороги в конусі завдовжки $s3 м перед вами отримують $s2 вогняної шкоди й дезорієнтуються на $d. Шкода скасовує ефект.$?a235870[\n\n\n\nЗавжди завдає критичного удару й зараховується до «Гарячої серії».][]" },
    { en = "Summons a Water Elemental to follow and fight for you.", ua = "Прикликає водяного елементаля, що йде за тобою і б'ється на твоєму боці." },
    { en = "Empowers your chosen aura for $d.\n\n\n\n$@spellname465: Damage reduction increased to ${-$s1-$465s2}%.\n\n\n\n$@spellname32223: Mount speed bonus increased to ${$s2+$32223s4}%.\n\n\n\n$@spellname317920: Affected allies immune to interrupts and silences.", ua = "Підсилює обрану вами ауру на $d.\n\n\n\n$@spellname465: Зменшення шкоди збільшено до ${-$s1-$465s2}%.\n\n\n\n$@spellname32223: Бонус до швидкості верхівця збільшено до ${$s2+$32223s4}%.\n\n\n\n$@spellname317920: Уражені союзники несприйнятливі до переривань та німотності." },
    { en = "Hurls your shield at an enemy target, dealing $s1 Holy damage, interrupting and silencing the non-Player target for $d, and then jumping to ${$x1-1} additional nearby enemies. $?a209389[\n\n\n\nShields you for $209388d, absorbing $209389s1% as much damage as it dealt.][]$?a378285[\n\n\n\nDeals $<dmg> additional damage to all enemies within $378286A1 yds of each target hit.][]", ua = "Кидає ваш щит у ворожу ціль, завдаючи $s1 шкоди Світла, перериваючи та занімовуючи ціль, що не є гравцем, на $d, а тоді перескакує на ${$x1-1} додаткових ворогів поблизу. $?a209389[\n\n\n\nЗахищає вас на $209388d, поглинаючи $209389s1% завданої шкоди.][]$?a378285[\n\n\n\nЗавдає $<dmg> додаткової шкоди всім ворогам у межах $378286A1 м від кожної ураженої цілі.][]" },
    { en = "Dispels magic in a $32375a1 yard radius, removing all harmful Magic from $s4 friendly targets and $32592m1 beneficial Magic $leffect:effects; from $s4 enemy targets. Potent enough to remove Magic that is normally undispellable.", ua = "Розвіює магію в радіусі $32375a1 м, знімаючи всю шкідливу магію з $s4 союзних цілей і $32592m1 корисний магічний $leffect:ефект:ефекти; з $s4 ворожих цілей. Достатньо потужне, щоб зняти магію, яку зазвичай розвіяти неможливо." },
    { en = "A word of dark binding that inflicts $s2 Shadow damage to your target. If your target is not killed by Shadow Word: Death, you take backlash damage equal to $s6% of your maximum health.$?A364675[\n\n\n\nDamage increased by ${$s4+$364675s2}% to targets below ${$s3+$364675s1}% health.][\n\n\n\nDamage increased by $s4% to targets below $s3% health.]$?c3[][]$?s137033[\n\n\n\n|cFFFFFFFFGenerates ${$s5/100} Insanity.|r][]", ua = "Слово темного зв'язування, що завдає вашій цілі $s2 шкоди Тінню. Якщо Слово тіні: Смерть не вбиває вашу ціль, ви отримуєте шкоду відплати, рівну $s6% вашого максимального здоров'я.$?A364675[\n\n\n\nШкода збільшена на ${$s4+$364675s2}% проти цілей зі здоров'ям нижче ${$s3+$364675s1}%.][\n\n\n\nШкода збільшена на $s4% проти цілей зі здоров'ям нижче $s3%.]$?c3[][]$?s137033[\n\n\n\n|cFFFFFFFFДає ${$s5/100} Безумства.|r][]" },
    { en = "Reduces all damage taken by a friendly target by $s1% for $d. Castable while stunned.", ua = "Зменшує всю шкоду, яку отримує дружня ціль, на $s1% на $d. Можна творити, коли ти приголомшений." },
    { en = "Heals the target for $o1 over $d. When Lifebloom expires, is dispelled, or is refreshed near expiration the target is instantly healed for $33778s1.\n\n\n\nMay be active on one target at a time.", ua = "Зцілює ціль на $o1 протягом $d. Коли Життєцвіт завершується, розвіюється або оновлюється під кінець дії, ціль миттєво зцілюється на $33778s1.\n\n\n\nМоже бути активним лише на одній цілі водночас." },
    { en = "Tosses the enemy target into the air, disorienting them but making them invulnerable for up to $d. Only one target can be affected by your Cyclone at a time.", ua = "Підкидає ворожу ціль у повітря, дезорієнтуючи її, але роблячи невразливою на час до $d. Одночасно під дією твого «Циклону» може бути лише одна ціль." },
    { en = "Magical damage and healing increased by $s1%.", ua = "Магічна шкода та зцілення збільшені на $s1%." },
    { en = "Shapeshift into the Tree of Life, increasing healing done by $5420s1%, increasing armor by $5420s3%, and granting protection from Polymorph effects. Functionality of Rejuvenation, Wild Growth, Regrowth, Entangling Roots, and Wrath is enhanced.\n\n\n\nLasts $117679d. You may shapeshift in and out of this form for its duration.", ua = "Перетворюєтеся на Древо Життя, підвищуючи завдане зцілення на $5420s1%, броню на $5420s3% та надаючи захист від ефектів Перетворення. Дія Омолодження, Дикого росту, Відростання, Обплутуючого коріння та Гніву посилюється.\n\n\n\nТриває $117679d. Ви можете вільно набувати цю подобу й полишати її протягом дії ефекту." },
    { en = "Give the command to kill, causing your pet to charge your target and savagely deal $83381s1 Physical damage to the enemy.", ua = "Віддаєш наказ убити: твій улюбленець кидається на ціль і люто завдає ворогові $83381s1 фізичної шкоди." },
    { en = "Shadow Word: Death has a $s3% chance to summon a Shadowfiend for $s1 sec when damaging targets below $s2% health.\n\n\n\n$@spellicon1280172 $@spellname1280172\n\nSummons a Shadowfiend to attack your target for $1280172d.$?c3[\n\n\n\n|cFFFFFFFFGenerates ${$200010s1/100} Insanity each time the Shadowfiend attacks.|r][\n\n\n\n|cFFFFFFFFGenerates ${$343727m1/10}.1% mana each time the Shadowfiend attacks.|r]", ua = "Тіньове слово: Смерть має $s3% шанс прикликати Тіньового біса на $s1 сек., завдаючи шкоди цілям зі здоров'ям нижче $s2%.\n\n\n\n$@spellicon1280172 $@spellname1280172\n\nПрикликає Тіньового біса, щоб атакувати вашу ціль протягом $1280172d.$?c3[\n\n\n\n|cFFFFFFFFГенерує ${$200010s1/100} Безуму щоразу, коли Тіньовий біс атакує.|r][\n\n\n\n|cFFFFFFFFГенерує ${$343727m1/10}.1% мани щоразу, коли Тіньовий біс атакує.|r]" },
    { en = "Misdirects all threat you cause to the targeted party or raid member, beginning with your next attack within $d and lasting for $35079d.", ua = "Перенаправляє всю загрозу, яку ти створюєш, на обраного учасника групи чи рейду, починаючи з твоєї наступної атаки протягом $d, і триває $35079d." },
    { en = "Releases miraculous light at a target location, healing up to $s2 allies within $a1 yds for $s1.\n\n\n\n|cFFFFFFFFCooldown reduced by $s3 sec when you cast Prayer of Healing.|r", ua = "Вивільняє чудодійне світло в обраній точці, зцілюючи до $s2 союзників у межах $a1 м на $s1.\n\n\n\n|cFFFFFFFFПерезарядження зменшується на $s3 сек., коли ви творите «Молитву зцілення».|r" },
    { en = "Your off-hand attacks and Pistol Shots have a $s1% chance to generate $35546s1 Energy.", ua = "Атаки другою рукою та «Постріли з пістоля» мають $s1% шансу відновити $35546s1 енергії." },
    { en = "Summons a legion of $?a134735[${$s1/2}][$s1] empowered Lesser Ghouls that last for $1282535d$?s1242608[ and an Abomination]?s1242147[ and a Gargoyle][] to swarm your enemies.\n\n\n\n|cFFFFFFFFGenerates ${$s3/10} Runic Power.|r", ua = "Прикликає легіон із $?a134735[${$s1/2}][$s1] підсилених Менших вурдалаків, які тривають $1282535d$?s1242608[ та Гидоту]?s1242147[ та Ґаргулью][], щоб накинутися на ваших ворогів.\n\n\n\n|cFFFFFFFFСтворює ${$s3/10} Рунічної енергії.|r" },
    { en = "Unleash a flurry of ice, striking the target $s1 times for a total of ${$228354s1*$s1} $?a1248002[Frostfire][Frost] damage.\n\n\n\n|CFFffffffApplies ${$1246769s2*$s1} $lstack:stacks; of Freezing.|R", ua = "Випускає шквал криги, що вражає ціль $s1 раз(и), завдаючи загалом ${$228354s1*$s1} шкоди $?a1248002[морозним вогнем][морозом].\n\n\n\n|CFFffffffНакладає ${$1246769s2*$s1} $lзаряд:заряди; Заморожування.|R" },
    { en = "Encases you in a block of ice, protecting you from all attacks and damage for $d, but during that time you cannot attack, move, or cast spells.$?a382292[\n\n\n\nWhile inside Ice Block, you heal for ${$382292s1*10}% of your maximum health over the duration.][]\n\n\n\nCauses Hypothermia, preventing you from recasting Ice Block for $41425d.", ua = "Огортає вас крижаною брилою, захищаючи від усіх атак і шкоди на $d, але протягом цього часу ви не можете атакувати, рухатися чи творити закляття.$?a382292[\n\n\n\nПеребуваючи в «Крижаній брилі», ви відновлюєте ${$382292s1*10}% свого максимального здоров'я за час дії.][]\n\n\n\nСпричиняє «Гіпотермію», що не дає повторно застосувати «Крижану брилу» протягом $41425d." },
    { en = "Raises a $?s58640[geist][ghoul] to fight by your side.  You can have a maximum of one $?s58640[geist][ghoul] at a time. Lasts $46585d.", ua = "Піднімає $?s58640[ґейста][вурдалака], щоб битися пліч-о-пліч з вами. Ви можете мати щонайбільше одного $?s58640[ґейста][вурдалака] водночас. Триває $46585d." },
    { en = "Sends a wave of force in a frontal cone, causing $s1 damage and stunning all enemies within $a1 yards for $132168d.", ua = "Випускає хвилю сили конусом перед тобою, завдаючи $s1 шкоди та приголомшуючи всіх ворогів у радіусі $a1 м на $132168d." },
    { en = "Direct critical heals create a protective shield on the target, absorbing $s1% of the amount healed. Lasts $47753d.", ua = "Прямі критичні зцілення створюють на цілі захисний щит, що поглинає $s1% від обсягу зцілення. Триває $47753d." },
    { en = "Smash the target's mind with cold, interrupting spellcasting and preventing any spell in that school from being cast for $d.", ua = "Б'є по розуму цілі холодом, перериваючи творення закляття й не даючи творити закляття цієї школи протягом $d." },
    { en = "Drain the will of your enemy to empower your rune weapon, dealing $s2 Shadowfrost damage and reduced damage to enemies nearby, gaining ${$1230959s1/10} Runic Power, and grants you Killing Machine.", ua = "Висотуй волю ворога, щоб посилити свою рунічну зброю: завдає $s2 тіньоморозної шкоди (ворогам поблизу — менше), дає ${$1230959s1/10} рунічної сили та дарує тобі «Машину вбивства»." },
    { en = "Calls upon a guardian spirit to watch over the friendly target for $d, increasing healing received by $s1%. If the target would die, the Spirit sacrifices itself and restores the target to $s2% health.\n\n\n\nCastable while stunned. Cannot save the target from massive damage.", ua = "Прикликає духа-охоронця, що оберігає дружню ціль протягом $d, підвищуючи отримуване зцілення на $s1%. Якщо ціль має загинути, дух жертвує собою й відновлює цілі $s2% здоров'я.\n\n\n\nМожна творити в оглушеному стані. Не може врятувати ціль від нищівної шкоди." },
    { en = "A ghostly soul haunts a single target, dealing $s1 Shadow damage and increasing your damage dealt to the target by $s2% for $d.\n\n\n\n$?a1261984[While active, Haunt deals ${$1262710s1*($48181d/$48181t5)} Shadow damage to its host and ${$1262710x1-1} enemies within $1278047a1 yards suffering from your Corruption or Wither.][] If the target dies, Haunt's cooldown is reset.", ua = "Примарна душа насилає на одну ціль, завдаючи $s1 тіньової шкоди та збільшуючи вашу шкоду по цілі на $s2% протягом $d.\n\n\n\n$?a1261984[Поки діє, Наслання завдає ${$1262710s1*($48181d/$48181t5)} тіньової шкоди своєму носієві та ${$1262710x1-1} ворогам у радіусі $1278047a1 ярдів, що потерпають від вашого Розтління чи Усихання.][] Якщо ціль гине, перезарядження Наслання скидається." },
    { en = "Stamina increased by $s1%.\n\n$?s316714[Damage taken reduced by $s3%.][]", ua = "Витривалість збільшено на $s1%.\n\n$?s316714[Отримувана шкода зменшена на $s3%.][]" },
    { en = "Heals up to $s2 injured allies within $A1 yards of the target for $o1 over $d. Healing starts high and declines over the duration.$?s33891[\n\n\n\n|C0033AA11Tree of Life: Affects $33891s3 additional $ltarget:targets;.|R][]", ua = "Зцілює до $s2 поранених союзників у радіусі $A1 ярдів від цілі на $o1 упродовж $d. Зцілення спершу велике й слабшає з плином часу.$?s33891[\n\n\n\n|C0033AA11Дерево життя: впливає на $33891s3 додаткову $lціль:цілі:цілей;.|R][]" },
    { en = "Rake damage increased by $s2%, and Rake causes an Infected Wound in the target, reducing the target's movement speed by $58180s1% for $58180d.", ua = "Шкода «Дряпання» збільшена на $s2%, а «Дряпання» залишає на цілі заражену рану, що зменшує її швидкість руху на $58180s1% протягом $58180d." },
    { en = "Create a death pact that heals you for $s1% of your maximum health, but absorbs incoming healing equal to $s3% of your max health for $d.", ua = "Укладає пакт смерті, що зцілює тебе на $s1% максимального здоров'я, але поглинає вхідне зцілення в обсязі $s3% твого максимального здоров'я протягом $d." },
    { en = "Your blood freezes, granting immunity to Stun effects and reducing all damage you take by $s3% for $d.", ua = "Твоя кров замерзає, даруючи імунітет до ефектів оглушення та зменшуючи всю отримувану шкоду на $s3% протягом $d." },
    { en = "A brutal attack $?$owb==0[that deals $<2hDamagePhysical> Physical and $<2hDamageFrost> Frost damage.][with both weapons that deals a total of $<dwDamagePhysical> Physical and $<dwDamageFrost> Frost damage.]", ua = "Жорстока атака $?$owb==0[, що завдає $<2hDamagePhysical> фізичної та $<2hDamageFrost> крижаної шкоди.][обома зброями, що завдає в сумі $<dwDamagePhysical> фізичної та $<dwDamageFrost> крижаної шкоди.]" },
    { en = "Summons a rune weapon for $81256d that mirrors your melee attacks and bolsters your defenses.\n\n\n\nWhile active, you gain $81256s1% parry chance.", ua = "Прикликає рунічну зброю на $81256d, що повторює ваші атаки ближнього бою та зміцнює ваш захист.\n\n\n\nПоки активна, ви отримуєте $81256s1% шансу парирування." },
    { en = "Chill your $?$owb==0[weapon with icy power and quickly strike the enemy, dealing $<2hDamage> Frost damage.][weapons with icy power and quickly strike the enemy with both, dealing a total of $<dualWieldDamage> Frost damage.]", ua = "Охолоджує вашу $?$owb==0[зброю крижаною силою та швидко вражає ворога, завдаючи $<2hDamage> шкоди від морозу.][зброю крижаною силою та швидко вражає ворога обома, завдаючи в сумі $<dualWieldDamage> шкоди від морозу.]" },
    { en = "Blast the target with a frigid wind, dealing ${$s1*$<CAP>/$AP} $?s204088[Frost damage and applying Frost Fever to the target.][Frost damage to that foe, and reduced damage to all other enemies within $237680A1 yards, infecting all targets with Frost Fever.]\n\n\n\n$@spellicon55095 |cFFFFFFFF$@spellname55095|r\n\n$@spelldesc55095", ua = "Обрушує на ціль крижаний вітер, завдаючи ${$s1*$<CAP>/$AP} $?s204088[морозної шкоди й накладаючи на ціль Морозну гарячку.][морозної шкоди цьому ворогові та зменшеної шкоди всім іншим ворогам у межах $237680A1 ярдів, заражаючи всі цілі Морозною гарячкою.]\n\n\n\n$@spellicon55095 |cFFFFFFFF$@spellname55095|r\n\n$@spelldesc55095" },
    { en = "Dread Plague has a $s2% chance to exhilarate you, making your next Death Coil or Epidemic cost ${$81340s1/-10} less Runic Power and deal $81340s4% increased damage.", ua = "«Моторошна чума» має $s2% шансу окрилити тебе: твоя наступна «Спіраль смерті» чи «Епідемія» коштує на ${$81340s1/-10} менше рунічної сили та завдає на $81340s4% більше шкоди." },
    { en = "Focuses dark power into a strike$?s137006[ with both weapons, that deals a total of ${$s1+$66188s1}][ that deals $s1] Physical damage and heals you for ${$s2}.2% of all damage taken in the last $s4 sec, minimum ${$s3}.1% of maximum health.", ua = "Зосереджує темну силу в ударі$?s137006[ обома зброями, що завдає загалом ${$s1+$66188s1}][, що завдає $s1] фізичної шкоди і зцілює вас на ${$s2}.2% усієї шкоди, отриманої за останні $s4 с, але щонайменше на ${$s3}.1% максимального здоров'я." },
    { en = "Go berserk for $d, reducing the cooldowns of Mangle, Thrash, and Growl by $s1% and the cooldown of Frenzied Regeneration by $s2%.$?a339062[\n\n\n\nGrants immunity to effects that cause loss of control of your character.][]", ua = "Впадає в шал на $d, зменшуючи перезарядження Шматування, Молотіння й Гарчання на $s1%, а перезарядження Несамовитої регенерації — на $s2%.$?a339062[\n\n\n\nНадає несприйнятливість до ефектів, що спричиняють втрату контролю над персонажем.][]" },
    { en = "Deals $s1 Shadow damage$?s212744[ to all enemies within $A1 yds.][ and infects all enemies within $A1 yds with Blood Plague.\n\n\n\n$@spellicon55078 |cFFFFFFFF$@spellname55078|r\n\n$@spelldesc55078]", ua = "Завдає $s1 тіньової шкоди$?s212744[ усім ворогам у межах $A1 ярдів.][ і заражає всіх ворогів у межах $A1 ярдів Кров'яною пошестю.\n\n\n\n$@spellicon55078 |cFFFFFFFF$@spellname55078|r\n\n$@spelldesc55078]" },
    { en = "Places an Anti-Magic Zone for $d, reducing the magic damage taken by party or raid members by $145629m1%.", ua = "Створює Антимагічну зону на $d, зменшуючи магічну шкоду, яку отримують члени групи чи рейду, на $145629m1%." },
    { en = "Your auto attack critical strikes have a chance to make your next Obliterate deal Frost damage and critically strike, or make your next Frostscythe critically strike for $s2 times the normal damage.", ua = "Критичні удари твоїх автоатак мають шанс зробити так, що твоє наступне «Знищення» завдасть шкоди від морозу та критично вдарить, або що твоя наступна «Морозна коса» завдасть критичного удару зі шкодою, у $s2 рази більшою за звичайну." },
    { en = "The power of frost increases your Strength by $s1% for $d.", ua = "Міць морозу збільшує твою силу на $s1% протягом $d." },
    { en = "Summons a totem at the target location for $d. The totem pulses every $116943t1 sec, rooting all enemies within $64695A1 yards for $64695d. Enemies previously rooted by the totem instead suffer $116947s1% movement speed reduction.", ua = "Прикликає тотем у вказаному місці на $d. Тотем пульсує кожні $116943t1 сек., приковуючи до землі всіх ворогів у радіусі $64695A1 м на $64695d. Вороги, яких тотем уже приковував, натомість сповільнюються на $116947s1%." },
    { en = "Hurls molten lava at the target, dealing $285452s1 Fire damage. Lava Burst will always critically strike if the target is affected by Flame Shock and its damage is increased by your critical strike chance.$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s3 Maelstrom.|r][]", ua = "Шпурляє розплавлену лаву в ціль, завдаючи $285452s1 шкоди вогнем. Виверження лави завжди завдає критичного удару, якщо ціль уражена Полум'яним шоком, а його шкода збільшується на ваш шанс критичного удару.$?a343725[\n\n\n\n|cFFFFFFFFСтворює $343725s3 Виру.|r][]" },
    { en = "Transforms the enemy into a frog for $d. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts.", ua = "Перетворює ворога на жабу на $d. Поки діють чари, жертва недієздатна й не може атакувати чи творити закляття. Шкода може зняти ефект. Не більше 1 цілі. Діє лише на гуманоїдів і звірів." },
    { en = "Casting Riptide grants $s1 $Lstack:stacks; of Tidal Waves. Tidal Waves reduces the cast time of your next Healing Wave or Chain Heal by $53390s1%.\n\n\n\nCan accumulate up to $53390U stacks.", ua = "Прочитання Відпливу надає $s1 $Lзаряд:заряди; Припливних хвиль. Припливні хвилі зменшують час прочитання вашої наступної Хвилі зцілення або Ланцюгового зцілення на $53390s1%.\n\n\n\nМоже накопичувати до $53390U зарядів." },
    { en = "Finishing move that unleashes a barrage of gunfire, striking random enemies within $r yards for Physical damage. Number of strikes increased per combo point.\n\n\n\nRestores $1235074m2 combo $Lpoint:points; every ${$t1}.2 sec.\n\n\n\n   1 point  : ${$<dmg>*2} over ${$424556d}.2 sec\n\n   2 points: ${$<dmg>*3} over ${$424556d*2}.2 sec\n\n   3 points: ${$<dmg>*4} over ${$424556d*3}.2 sec\n\n   4 points: ${$<dmg>*5} over ${$424556d*4}.2 sec\n\n   5 points: ${$<dmg>*6} over ${$424556d*5}.2 sec$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$<dmg>*7} over ${$424556d*6}.2 sec][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$<dmg>*8} over ${$424556d*7}.2 sec][]", ua = "Завершальний прийом, що випускає шквал пострілів, б'ючи випадкових ворогів у межах $r ярдів і завдаючи фізичної шкоди. Кількість ударів зростає за кожне очко комбо.\n\n\n\nВідновлює $1235074m2 $Lочко комбо:очок комбо; кожні ${$t1}.2 сек.\n\n\n\n   1 очко  : ${$<dmg>*2} протягом ${$424556d}.2 сек.\n\n   2 очки: ${$<dmg>*3} протягом ${$424556d*2}.2 сек.\n\n   3 очки: ${$<dmg>*4} протягом ${$424556d*3}.2 сек.\n\n   4 очки: ${$<dmg>*5} протягом ${$424556d*4}.2 сек.\n\n   5 очок: ${$<dmg>*6} протягом ${$424556d*5}.2 сек.$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$<dmg>*7} протягом ${$424556d*6}.2 сек.][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$<dmg>*8} протягом ${$424556d*7}.2 сек.][]" },
    { en = "Removes all Curse effects from a friendly target.", ua = "Знімає всі ефекти проклять із дружньої цілі." },
    { en = "You attempt to finish off a wounded target, dealing $s1 Physical damage. Only usable on enemies with less than $s2% health.", ua = "Ти намагаєшся добити поранену ціль, завдаючи $s1 фізичної шкоди. Можна використати лише проти ворогів, у яких менше ніж $s2% здоров'я." },
    { en = "$?(c1|c2|c3)[][The duration of Avenging Wrath is increased by $s1%.]$?c1[Avenging Wrath and Avenging Crusader have $s1% increased duration.]?c2[Avenging Wrath and Sentinel cause Judgment to generate $s3 additional Holy Power,]?c3[Avenging Wrath and Crusade cause each Holy Power spent to explode with Holy light for $326731s1 damage to nearby enemies,][]$?(c2|c3)[ and have $s1% increased duration.][]", ua = "$?(c1|c2|c3)[][Тривалість «Гніву месника» збільшена на $s1%.]$?c1[«Гнів месника» та «Хрестоносець-месник» діють на $s1% довше.]?c2[«Гнів месника» та «Вартовий» змушують «Осуд» давати $s3 додаткової святої сили,]?c3[«Гнів месника» та «Хрестовий похід» змушують кожну витрачену одиницю святої сили вибухати святим світлом, завдаючи $326731s1 шкоди ворогам поблизу,][]$?(c2|c3)[ а самі діють на $s1% довше.][]" },
    { en = "Unleashes a whirl of divine energy, dealing $?s405289[${$s1*1.05} Radiant][$s1 Holy] damage to all nearby enemies. \n\n\n\nDeals reduced damage beyond $s2 targets.", ua = "Вивільняє вихор божественної енергії, завдаючи $?s405289[${$s1*1.05} променистої][$s1 шкоди Світлом] усім ворогам поблизу. \n\n\n\nЗа межами $s2 цілей шкода зменшена." },
    { en = "Instructs your pet to protect a friendly target, reducing their damage taken by $s1%, but $s2% of all damage taken by that target is transferred to your pet. \n\n\n\nLasts $d or until your pet's health drops below $s3%.", ua = "Наказує вашому улюбленцю захищати дружню ціль, зменшуючи отримувану нею шкоду на $s1%, але $s2% усієї отримуваної цією ціллю шкоди переноситься на вашого улюбленця. \n\n\n\nТриває $d або доки здоров'я вашого улюбленця не впаде нижче $s3%." },
    { en = "Your Holy Shocks have a $s1% chance to empower your next spell cast:\n\n\n\n$@spellname19750: healing increased by $54149s1% and becomes instant cast.\n\n$@spellname275773: Greater Judgment prevents an additional ${$54149s4-100}% damage dealt by the target and generates $54149s6 additional Holy Power.", ua = "Ваш Священний шок має $s1% шансу посилити наступне застосоване вами закляття:\n\n\n\n$@spellname19750: зцілення збільшено на $54149s1% і стає миттєвим.\n\n$@spellname275773: Велике судження запобігає додатковим ${$54149s4-100}% шкоди, що завдає ціль, і дає $54149s6 додаткової Священної сили." },
    { en = "Hammers the current target for $53595sw1 Physical damage.$?s26573&s203785[\n\n\n\nHammer of the Righteous also causes a wave of light that hits all other targets within $88263A1 yds for $88263sw1 Holy damage.]?s26573[\n\n\n\nWhile you are standing in your Consecration, Hammer of the Righteous also causes a wave of light that hits all other targets within $88263A1 yds for $88263sw1 Holy damage.][]\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.", ua = "Б'є молотом поточну ціль, завдаючи $53595sw1 фізичної шкоди.$?s26573&s203785[\n\n\n\nМолот праведника також спричиняє хвилю світла, що влучає в усі інші цілі в межах $88263A1 м, завдаючи $88263sw1 шкоди Світла.]?s26573[\n\n\n\nДоки ви стоїте у своєму Освяченні, Молот праведника також спричиняє хвилю світла, що влучає в усі інші цілі в межах $88263A1 м, завдаючи $88263sw1 шкоди Світла.][]\n\n\n\n|cFFFFFFFFГенерує $s2 Святої Сили." },
    { en = "An unholy strike that deals $s1 Shadow damage and causing your plagues on the target to erupt, dealing their damage an additional time at $s2% effectiveness.\n\n\n\nApplies Virulent Plague or spreads it to a nearby enemy.", ua = "Нечестивий удар, що завдає $s1 шкоди тінню та змушує ваші пошесті на цілі вибухнути, завдаючи їхньої шкоди ще раз із $s2% ефективністю.\n\n\n\nНакладає Згубну пошесть або поширює її на ворога поблизу." },
    { en = "Embrace your undeath, increasing your maximum health by $s4% and increasing all healing and absorbs received by $s1% for $d.", ua = "Прийми свою нежить: максимальне здоров'я збільшується на $s4%, а все отримуване зцілення та поглинання — на $s1% протягом $d." },
    { en = "Creates $s2 copies of you nearby for $55342d, which cast spells and attack your enemies. While active, you generate significantly reduced threat.\n\n\n\nTaking direct damage will cause one of your images to dissipate", ua = "Створює поруч $s2 ваші копії на $55342d, які творять закляття й атакують ваших ворогів. Поки вони активні, ви створюєте значно менше загрози.\n\n\n\nОтримання прямої шкоди змушує одне з ваших відображень розвіятися" },
    { en = "Psychic Scream causes enemies to tremble in place instead of fleeing in fear.", ua = "«Психічний крик» змушує ворогів тремтіти на місці замість тікати з переляку." },
    { en = "Your Fear causes the target to tremble in place instead of fleeing in fear.", ua = "Твій «Страх» змушує ціль тремтіти на місці замість тікати з переляку." },
    { en = "Your Flurry and $?s431044[Frostfire Bolt][Frostbolt] spells strike $s1 additional target at $s2% effectiveness.", ua = "Ваші закляття «Шквал» та $?s431044[«Морозновогняна стріла»][«Крижана стріла»] вражають $s1 додаткову ціль з ефективністю $s2%." },
    { en = "Disrupts the target's concentration with a burst of wind, interrupting spellcasting and preventing any spell in that school from being cast for $d.", ua = "Поривом вітру порушує зосередження цілі, перериваючи читання закляття й не даючи творити закляття цієї школи протягом $d." },
    { en = "Your finishing moves generate $98440s2 Energy per combo point spent.", ua = "Завершальні прийоми відновлюють $98440s2 енергії за кожне витрачене очко комбо." },
    { en = "Removes all movement impairing effects and increases your movement speed by $58875s1% for $58875d.", ua = "Знімає всі ефекти, що сповільнюють рух, і збільшує твою швидкість руху на $58875s1% на $58875d." },
    { en = "Charges your off-hand weapon with lava and burns your target, dealing $s1 Fire damage.\n\n\n\nDamage is increased by $s2% if your offhand weapon is imbued with Flametongue Weapon. $?s334033[Lava Lash will spread Flame Shock from your target to $s3 nearby targets.][]$?s334046[\n\n\n\nLava Lash increases the damage of Flame Shock on its target by $334168s1% for $334168d.][]", ua = "Заряджає вашу зброю в другій руці лавою та обпікає ціль, завдаючи $s1 шкоди вогнем.\n\n\n\nШкода збільшується на $s2%, якщо ваша зброя в другій руці насичена Полум'яним язиком. $?s334033[Лавовий батіг поширює Полум'яний шок з вашої цілі на $s3 ближніх цілей.][]$?s334046[\n\n\n\nЛавовий батіг збільшує шкоду Полум'яного шоку на його цілі на $334168s1% протягом $334168d.][]" },
    { en = "Your damaging $?a343190[and healing ][]critical strikes deal ${$m1+200}% damage $?a343190[or healing ][]instead of the usual 200%.", ua = "Ваші критичні удари, що завдають шкоди $?a343190[чи зцілюють ][], завдають ${$m1+200}% шкоди $?a343190[або зцілення ][]замість звичних 200%." },
    { en = "Restorative waters wash over a friendly target, healing them for $s1 and an additional $o2 over $d.", ua = "Цілющі води омивають дружню ціль, зцілюючи її на $s1 і ще на $o2 протягом $d." },
    { en = "Increases your Energy regeneration rate by $s1%.", ua = "Збільшує швидкість відновлення енергії на $s1%." },
    { en = "Reduces all damage you take by $50322s1% for $50322d.", ua = "Зменшує всю шкоду, яку ти отримуєш, на $50322s1% на $50322d." },
    { en = "Summons a holy barrier to protect all allies at the target location for $d, reducing all damage taken by $81782s2% and preventing damage from delaying spellcasting.", ua = "Прикликає святий бар'єр, що захищає всіх союзників у вказаному місці протягом $d, зменшуючи всю отримувану ними шкоду на $81782s2% і не даючи шкоді сповільнювати читання заклять." },
    { en = "$?c2[Prayer of Mending][Power Word: Shield] and Leap of Faith increase your target's movement speed by $65081s1% for $65081d.", ua = "$?c2[Молитва зцілення][Слово сили: Щит] і Стрибок віри збільшують швидкість руху вашої цілі на $65081s1% на $65081d." },
    { en = "Hurl your weapon at the enemy,  removing any magical immunities and causing $394352s2 Physical damage, ignoring armor. Deals up to $394352s3% increased damage to absorb shields.", ua = "Жбурляєш свою зброю у ворога, знімаючи всі магічні імунітети та завдаючи $394352s2 фізичної шкоди, ігноруючи броню. Завдає до $394352s3% більше шкоди поглинальним щитам." },
    { en = "Heals all party or raid members within $64844A1 yards for ${5*$64844s1} over $d. Each heal increases all targets' healing taken by $64844s2% for $64844d, stacking.\n\n\n\nHealing reduced beyond $s5 targets.", ua = "Зцілює всіх членів групи чи рейду в межах $64844A1 м на ${5*$64844s1} протягом $d. Кожне зцілення збільшує отримуване всіма цілями зцілення на $64844s2% протягом $64844d, накопичуючись.\n\n\n\nЗцілення зменшено понад $s5 цілей." },
    { en = "Pulls the spirit of a party or raid member, instantly moving them directly in front of you.", ua = "Притягує дух учасника групи чи рейду, миттєво переносячи його просто перед тебе." },
    { en = "Unleash elemental forces of Life, healing a friendly target for $s1.\n\n\n\nIncreases the healing of your next Riptide, Chain Heal, or Healing Wave by $s2% and reduces its cast time by $s3%.", ua = "Вивільняє стихійні сили Життя, зцілюючи дружню ціль на $s1.\n\n\n\nЗбільшує зцілення вашого наступного Відпливу, Ланцюгового зцілення або Хвилі зцілення на $s2% і зменшує час його прочитання на $s3%." },
    { en = "Blanket the target area in healing rains, restoring ${$73921m1*6*2/$t2} health to up to $s4 allies over $d.", ua = "Вкриває обрану ділянку цілющим дощем, відновлюючи ${$73921m1*6*2/$t2} здоров'я щонайбільше $s4 союзникам протягом $d." },
    { en = "Inflicts the target with Dread Plague and Virulent Plague.\n\n\n\n$@spellicon1240996$@spellname1240996\n\n$@spelldesc1240996\n\n\n\n$@spellicon191587$@spellname191587\n\n$@spelldesc191587", ua = "Заражає ціль Жахною пошестю та Згубною пошестю.\n\n\n\n$@spellicon1240996$@spellname1240996\n\n$@spelldesc1240996\n\n\n\n$@spellicon191587$@spellname191587\n\n$@spelldesc191587" },
    { en = "Launch a surge of stellar energies at the target, dealing $s1 Astral damage.", ua = "Вивільняє сплеск зоряної енергії в ціль, завдаючи $s1 астральної шкоди." },
    { en = "Summons a beam of solar light over an enemy target's location, interrupting the target and silencing all enemies within the beam. Lasts $d.", ua = "Прикликає промінь сонячного світла над місцем розташування ворожої цілі, перериваючи її закляття та змушуючи замовкнути всіх ворогів у промені. Триває $d." },
    { en = "Evasion also reduces damage taken by $s2%, and Feint also reduces non-area-of-effect damage taken by $s1%.", ua = "Ухилення також зменшує отримувану шкоду на $s2%, а Фінт також зменшує отримувану шкоду від неплощинних атак на $s1%." },
    { en = "You regain $s1 Energy each time your Garrote or Rupture deal Bleed damage to a target affected by your weapon poisons. Energy gain is reduced for bleeds beyond the first.\n\n\n\nIf an enemy dies while afflicted by your Rupture, you regain energy based on its remaining duration.", ua = "Ви відновлюєте $s1 Енергії щоразу, коли ваша «Гарота» чи «Розрив» завдають цілі шкоди від Кровотечі, якщо ця ціль вражена вашими зброярськими отрутами. Відновлення Енергії зменшене для кровотеч після першої.\n\n\n\nЯкщо ворог гине, перебуваючи під дією вашого «Розриву», ви відновлюєте енергію залежно від часу, що залишився." },
    { en = "Calls upon the guidance of the spirits for $d, permitting movement while casting Shaman spells. Castable while casting.$?a192088[ Increases movement speed by $192088s2%.][]", ua = "Прикликає провід духів протягом $d, дозволяючи рухатися під час творення заклять шамана. Можна творити під час прочитання.$?a192088[ Збільшує швидкість пересування на $192088s2%.][]" },
    { en = "Marks a target with Havoc for $d, causing your single target spells to also strike the Havoc victim for $s1% of the damage dealt.", ua = "Позначає ціль «Погромом» на $d, через що твої закляття по одній цілі також вражають жертву «Погрому», завдаючи їй $s1% завданої шкоди." },
    { en = "Power Word: Shield, Flash Heal, Plea, Penance, and Power Word: Radiance apply Atonement to your target for $194384d.\n\n\n\nYour spell damage heals all targets affected by Atonement for $s1% of the damage done. Healing is reduced when healing more than $s2 targets.", ua = "«Слово сили: Щит», «Швидке зцілення», «Благання», «Покута» і «Слово сили: Сяйво» накладають «Спокуту» на вашу ціль протягом $194384d.\n\n\n\nШкода від ваших заклять зцілює всі цілі під ефектом «Спокути» на $s1% завданої шкоди. Зцілення зменшується при зціленні понад $s2 цілей." },
    { en = "Launches an orb of swirling ice in front of you, dealing up to ${20*$84721s1} Frost damage to all enemies it passes through over $d. After a short delay, Frozen Orb will pursue its target. Deals reduced damage beyond $84721s2 targets.\n\n\n\nEnemies damaged by the Frozen Orb are slowed by $205708s1% for $205708d.", ua = "Запускає перед вами сферу вируючої криги, що завдає до ${20*$84721s1} шкоди від морозу всім ворогам, крізь яких вона проходить, протягом $d. Після короткої затримки Заморожена сфера починає переслідувати свою ціль. Завдає зменшеної шкоди понад $84721s2 цілей.\n\n\n\nВороги, уражені Замороженою сферою, сповільнюються на $205708s1% на $205708d." },
    { en = "When you avoid a melee attack or use $?S53595[Hammer of the Righteous]?S204019[Blessed Hammer][Crusader Strike], you have a $s1% chance to reset the remaining cooldown on Avenger's Shield$?S393022[ and increase your Strength by $393019s1% for $393019d.][.]", ua = "Коли ти уникаєш атаки ближнього бою або використовуєш $?S53595[«Молот праведника»]?S204019[«Благословенний молот»][«Удар хрестоносця»], є $s1% шансу скинути решту перезарядження «Щита месника»$?S393022[ і збільшити твою силу на $393019s1% на $393019d.][.]" },
    { en = "Unleashes Holy energy, healing up to $s2 injured allies within a $a1 yd radius around you for $s1.", ua = "Вивільняє святу енергію, зцілюючи до $s2 поранених союзників у радіусі $a1 м довкола тебе на $s1." },
    { en = "Empowers you with the spirit of ancient kings, reducing all damage you take by $86657s2% for $d.", ua = "Сповнює тебе духом стародавніх королів, зменшуючи всю отримувану шкоду на $86657s2% протягом $d." },
    { en = "Fatal damage instead brings you to $86949s2% health and then burns you for $87023o1% of your maximum health over $87023d.\n\n\n\nWhile burning, movement slowing effects are suppressed and your movement speed is increased by $108843s1%.\n\n\n\nThis effect cannot occur more than once every $87024d.", ua = "Смертельна шкода натомість залишає вам $86949s2% здоров'я, а потім спалює вас на $87023o1% вашого максимального здоров'я протягом $87023d.\n\n\n\nПоки ви палаєте, ефекти сповільнення придушуються, а ваша швидкість пересування збільшується на $108843s1%.\n\n\n\nЦей ефект може спрацьовувати не частіше ніж раз на $87024d." },
    { en = "Chastises the target for $s1 Holy damage and $?s200199[stuns][incapacitates] them for $?s200199[$200200d][$200196d].$?s63733[\n\n\n\n|cFFFFFFFFCooldown reduced by $s2 sec when you cast Smite or Holy Nova.|r][]", ua = "Карає ціль, завдаючи $s1 шкоди Світлом і $?s200199[оглушуючи][знесилюючи] її на $?s200199[$200200d][$200196d].$?s63733[\n\n\n\n|cFFFFFFFFПерезарядження зменшено на $s2 с, коли ви застосовуєте Удар або Священну нову.|r][]" },
    { en = "Grow a magical mushroom at the target enemy's location. After $d, the mushroom detonates, dealing $88751s1 Nature damage and then an additional $81281o1 Nature damage over $81281d. Affected targets are slowed by ${$81281s2*-1}%.\n\n\n\nGenerates up to $88751s2 Astral Power based on targets hit.", ua = "Вирощує магічний гриб на місці розташування ворожої цілі. Через $d гриб детонує, завдаючи $88751s1 шкоди від Природи, а потім ще $81281o1 шкоди від Природи протягом $81281d. Уражені цілі сповільнюються на ${$81281s2*-1}%.\n\n\n\nГенерує до $88751s2 Астральної сили залежно від кількості уражених цілей." },
    { en = "Your Stealth abilities allow you to see the flaws in enemies' defenses, causing your attacks to ignore $s1% armor for $316220d.", ua = "Здібності непомітності дозволяють тобі бачити прогалини в захисті ворогів: твої атаки ігнорують $s1% броні протягом $316220d." },
    { en = "Interrupts spellcasting and prevents any spell in that school from being cast for $d.", ua = "Перериває творення закляття і не дає творити закляття цієї школи протягом $d." },
    { en = "Lets loose a rallying cry, granting all party or raid members within $a1 yards $s1% temporary and maximum health for $97463d.\n\n\n\nHealth granted increased by $s2% when not in a raid.", ua = "Видаєш згуртувальний клич, надаючи всім членам групи чи рейду в межах $a1 м $s1% тимчасового й максимального здоров'я на $97463d.\n\n\n\nНадане здоров'я збільшується на $s2%, коли ти не в рейді." },
    { en = "Summons a totem at the target location for $d, which reduces damage taken by all party and raid members within $98007a1 yards by $98007s1%. Immediately and every $98017t1 sec, the health of all affected players is redistributed evenly.", ua = "Прикликає тотем у вказаному місці на $d, що зменшує отримувану шкоду всіх членів групи та рейду в радіусі $98007a1 м на $98007s1%. Одразу й кожні $98017t1 сек. здоров'я всіх охоплених гравців перерозподіляється порівну." },
    { en = "Split your body and spirit, leaving your spirit behind for $d. Use Transcendence: Transfer to swap locations with your spirit.", ua = "Розділяєш тіло і дух, лишаючи свій дух позаду на $d. Використай «Трансценденцію: переміщення», щоб помінятися з духом місцями." },
    { en = "The target's skin becomes as tough as Ironwood, reducing damage taken by $s1%$?a197061[ and increasing healing from your heal over time effects by $s2%][] for $d.$?a392116[\n\n\n\nAllies protected by your Ironbark also receive $392116s1% of the healing from each of your active Rejuvenations.][]", ua = "Шкіра цілі стає твердою, мов залізне дерево, знижуючи отримувану шкоду на $s1%$?a197061[ і підвищуючи зцілення від ваших періодичних ефектів на $s2%][] протягом $d.$?a392116[\n\n\n\nСоюзники під захистом вашої Залізної кори також отримують $392116s1% зцілення від кожного вашого активного Оновлення.][]" },
    { en = "Roots the target and all enemies within $A1 yards in place for $d. Damage may interrupt the effect. Usable in all shapeshift forms.", ua = "Укорінює на місці ціль і всіх ворогів у межах $A1 м на $d. Шкода може перервати ефект. Можна використовувати в усіх подобах." },
    { en = "Fly to a nearby ally's position.", ua = "Лети до позиції союзника поблизу." },
    { en = "An improved Cat Form that grants all of your known Berserk effects and lasts $d. You may shapeshift in and out of this improved Cat Form for its duration. During Incarnation:\n\n\n\nEnergy cost of all Cat Form abilities is reduced by $s3%, and Prowl can be used once while in combat.$?s343223[\n\n\n\nGenerate $343216s1 combo $lpoint:points; every $t1 sec. Combo point generating abilities generate $106951s2 additional combo $lpoint:points;. Finishing moves restore up to $405189u combo points generated over the cap.\n\n\n\nAll attack and ability damage is increased by $s4%.][]", ua = "Покращена котяча подоба, що надає всі ваші відомі ефекти Берсерка й триває $d. Упродовж дії ви можете вільно перевтілюватися в цю покращену котячу подобу й назад. Під час Втілення:\n\n\n\nВитрати енергії всіх умінь котячої подоби зменшено на $s3%, а Скрадання можна застосувати раз під час бою.$?s343223[\n\n\n\nГенерує $343216s1 комбо-$lочко:очки:очок; кожні $t1 с. Уміння, що генерують комбо-очки, дають $106951s2 додаткові комбо-$lочко:очки:очок;. Завершальні удари відновлюють до $405189u комбо-очок, згенерованих понад межу.\n\n\n\nУся шкода від атак і вмінь збільшується на $s4%.][]" },
    { en = "An improved Bear Form that grants the benefits of Berserk, causes Mangle to hit up to $s12 targets, $?a429536[increases Arcane damage by $s14%, ][]and increases maximum health by $s13%.$?a339062[\n\n\n\nGrants immunity to effects that cause loss of control of your character.][]\n\n\n\nLasts $d. You may freely shapeshift in and out of this improved Bear Form for its duration.", ua = "Покращена Ведмежа подоба, що дає переваги Берсерка, дозволяє Роздиранню влучати до $s12 цілей, $?a429536[збільшує арканну шкоду на $s14%, ][]і збільшує максимальне здоров'я на $s13%.$?a339062[\n\n\n\nДає несприйнятливість до ефектів, що спричиняють втрату контролю над вашим персонажем.][]\n\n\n\nТриває $d. Ви можете вільно перевтілюватися в цю покращену Ведмежу подобу й назад протягом її дії." },
    { en = "Conjures a vortex of wind for $d at the destination, reducing the movement speed of all enemies within $A1 yards by $s1%. The first time an enemy attempts to leave the vortex, winds will pull that enemy back to its center. Usable in all shapeshift forms.", ua = "Створює вихор вітру в указаному місці на $d, сповільнюючи рух усіх ворогів у радіусі $A1 м на $s1%. Коли ворог уперше намагається покинути вихор, вітри затягують його назад у центр. Можна використовувати в усіх подобах." },
    { en = "Charge gains $s1 additional charge and its cooldown is reduced by ${$s2/-1000} sec.", ua = "Ривок отримує $s1 додатковий заряд, а його перезарядження скорочено на ${$s2/-1000} сек." },
    { en = "Summons $s1 ferocious Dreadstalkers to attack the target for $193332d.", ua = "Прикликає $s1 лютих ловчих жаху, які атакують ціль протягом $193332d." },
    { en = "You charge and bash the target's skull, interrupting spellcasting and preventing any spell in that school from being cast for $93985d.", ua = "Ти кидаєшся до цілі й б'єш її по черепу, перериваючи творення закляття й не даючи творити закляття цієї школи протягом $93985d." },
    { en = "Shift into Bear Form and let loose a wild roar, increasing the movement speed of all friendly players within $A1 yards by $s1% for $d.", ua = "Перевтілься в подобу ведмедя й видай дикий рик, збільшуючи швидкість руху всіх дружніх гравців у межах $A1 м на $s1% на $d." },
    { en = "Kick upwards, dealing $?s137025[${$185099s1*$<CAP>/$AP}][$185099s1] Physical damage$?s128595[, and reducing the effectiveness of healing on the target for $115804d][].$?a388847[\n\n\n\nApplies Renewing Mist for $388847s1 seconds to an ally within $388847r yds][]", ua = "Удар ногою вгору, що завдає $?s137025[${$185099s1*$<CAP>/$AP}][$185099s1] фізичної шкоди$?s128595[ і зменшує дієвість зцілення на цілі на $115804d][].$?a388847[\n\n\n\nНакладає Оновлювальний туман на $388847s1 секунд на союзника в межах $388847r ярдів][]" },
    { en = "Hurls your weapon at an enemy, causing $s1 Physical damage and stunning for $132169d.$?s436162[ Also hits 2 additional nearby targets, stunning for 2 sec.][]", ua = "Кидає вашу зброю у ворога, завдаючи $s1 фізичної шкоди та оглушуючи на $132169d.$?s436162[ Також вражає 2 додаткові цілі поблизу, оглушуючи на 2 сек.][]" },
    { en = "Transform into a colossus, increasing all damage you deal by $s1% $?c1[and reducing damage you take from area of effect attacks by $s6% ]?c2[and increasing your movement speed by $s7% ]?c3[and reducing all damage you take by $s8% ][]for $d.", ua = "Перетворюєтеся на колоса, збільшуючи всю завдану вами шкоду на $s1% $?c1[та зменшуючи шкоду, яку ви отримуєте від площинних атак, на $s6% ]?c2[та збільшуючи вашу швидкість пересування на $s7% ]?c3[та зменшуючи всю отриману вами шкоду на $s8% ][]на $d." },
    { en = "Shadowy tendrils coil around all enemies within $A2 yards of a hostile or friendly target, pulling them to the target's location and Silencing them for $374776d.", ua = "Тіньові пагони обвивають усіх ворогів у радіусі $A2 м від ворожої або дружньої цілі, притягуючи їх до місця цілі та змушуючи замовкнути на $374776d." },
    { en = "Abilities requiring Stealth can be used for $?a137035[${$s4/1000}][${$s2/1000}] sec after Stealth breaks.\n\n\n\nCombat benefits requiring Stealth persist for an additional $?a137035[${$s4/1000}][${$s2/1000}] sec after Stealth breaks.", ua = "Здібності, що потребують Маскування, можна використовувати ще $?a137035[${$s4/1000}][${$s2/1000}] сек. після того, як Маскування зникає.\n\n\n\nБойові переваги, що потребують Маскування, зберігаються ще $?a137035[${$s4/1000}][${$s2/1000}] сек. після того, як Маскування зникає." },
    { en = "Abilities deal $112942m1% more damage while Stealth or Shadow Dance is active.", ua = "Здібності завдають на $112942m1% більше шкоди, поки діє Скрадання або Танець тіней." },
    { en = "Shift partially into the elemental planes, taking $s1% less damage for $d.", ua = "Частково зміщує тебе у стихійні виміри, зменшуючи отримувану шкоду на $s1% на $d." },
    { en = "Summons a totem at your feet for $d, which pulses every $t2 sec, healing all party or raid members within $114942A1 yards for $114942s1.\n\n\n\nHealing reduced beyond $s1 targets.", ua = "Прикликає тотем біля ваших ніг на $d. Тотем пульсує кожні $t2 сек, зцілюючи всіх членів групи або рейду в межах $114942A1 ярдів на $114942s1.\n\n\n\nЗцілення зменшується понад $s1 цілей." },
    { en = "Relocates your active totems to the specified location.", ua = "Переміщує твої активні тотеми у вказане місце." },
    { en = "Physical damage and Armor increased by $s1%.", ua = "Фізична шкода та броня збільшені на $s1%." },
    { en = "$s2% of all damage you take is taken by your demon pet instead. $?a137044[][\n\n\n\nWhile Grimoire of Sacrifice is active, your Stamina is increased by $s3%.]", ua = "$s2% усієї шкоди, яку ви отримуєте, натомість приймає на себе ваш демон-улюбленець. $?a137044[][\n\n\n\nПоки активний Гримуар жертви, ваша Витривалість збільшена на $s3%.]" },
    { en = "Sacrifices $s2% of your current health to shield you for $s3% of the sacrificed health plus an additional $<points> for $d. Usable while suffering from control impairing effects.", ua = "Жертвує $s2% вашого поточного здоров'я, щоб укрити вас щитом на $s3% пожертвуваного здоров'я плюс додатково $<points> протягом $d. Можна застосувати, навіть коли ви потерпаєте від ефектів контролю." },
    { en = "Sacrifices your demon pet for power, gaining its command demon ability, and causing your spells to sometimes also deal $196100s1 additional Shadow damage.\n\n\n\nLasts $196099d or until you summon a demon pet.", ua = "Приносить у жертву вашого демона-улюбленця заради сили, надаючи вам його здібність командування демоном і змушуючи ваші закляття подеколи завдавати $196100s1 додаткової шкоди від тіні.\n\n\n\nТриває $196099d або доки ви не прикличете демона-улюбленця." },
    { en = "$?a445465[Wither][Corruption] damage has a chance to cause your next $?a388667[Drain Soul][Shadow Bolt] or Malefic Grasp to deal $264571s2% increased damage. \n\n\n\n$?a388667[Drain Soul and Malefic Grasp channel $264571s3% faster while affected.][Shadow Bolt is instant cast and Malefic Grasp channels $264571s3% faster when affected.]", ua = "Шкода від $?a445465[Усихання][Розтління] має шанс зробити так, що ваше наступне $?a388667[Висмоктування душі][Тіньовий снаряд] або Лиховісний захват завдасть на $264571s2% більше шкоди. \n\n\n\n$?a388667[Поки діє цей ефект, Висмоктування душі та Лиховісний захват творяться на $264571s3% швидше.][Поки діє цей ефект, Тіньовий снаряд твориться миттєво, а Лиховісний захват — на $264571s3% швидше.]" },
    { en = "Blasts the enemy, critically striking for ${$s1*2} $?a1248002[Frostfire][Fire] damage.\n\n\n\nCastable while casting other spells.", ua = "Уражає ворога, завдаючи критичним ударом ${$s1*2} $?a1248002[морозовогняної][вогняної] шкоди.\n\n\n\nМожна творити під час творіння інших заклять." },
    { en = "Activating Fade removes all snare effects.", ua = "Активація «Згасання» знімає всі ефекти сповільнення." },
    { en = "When an attack brings you below $s1% health, you gain an absorption shield equal to $s2% of your maximum health for $114214d. Cannot occur more than once every $s3 sec.", ua = "Коли атака опускає твоє здоров'я нижче $s1%, ти отримуєш поглинальний щит, що дорівнює $s2% твого максимального здоров'я, на $114214d. Не може спрацьовувати частіше, ніж раз на $s3 сек." },
    { en = "Your healing spells and Smite have a $s1% chance to make your next Flash Heal$?a1247178[ or Prayer of Healing][] instant and cost $?a137030[$114255s4]?a137031[$114255s2][$114255s3]% less mana. Stacks to $114255u.", ua = "Ваші закляття зцілення та Кара мають $s1% шансу зробити ваше наступне Швидке зцілення$?a1247178[ чи Молитву зцілення][] миттєвим, і воно коштуватиме на $?a137030[$114255s4]?a137031[$114255s2][$114255s3]% менше мани. Накопичується до $114255u." },
    { en = "Disengage also frees you from all movement impairing effects and increases your movement speed by $s2% for $118922d.", ua = "«Відступ» також звільняє тебе від усіх ефектів, що сповільнюють рух, і збільшує твою швидкість руху на $s2% протягом $118922d." },
    { en = "Makes you invisible and untargetable for $110960d, removing all threat. Any action taken cancels this effect.\n\n$?a382293[\n\n\n\nIncreases your movement speed by ${$382293s1}% for $337278d.][]", ua = "Робить вас невидимим і недосяжним для прицілювання на $110960d, знімаючи всю загрозу. Будь-яка дія скасовує цей ефект.\n\n$?a382293[\n\n\n\nПідвищує вашу швидкість пересування на ${$382293s1}% протягом $337278d.][]" },
    { en = "Increases your movement speed by $s1%, but also damages you for $s2% of your maximum health every $t2 sec. Movement impairing effects may not reduce you below $s3% of normal movement speed. Lasts $d.", ua = "Збільшує твою швидкість руху на $s1%, але також завдає тобі шкоди в розмірі $s2% максимального здоров'я кожні $t2 сек. Ефекти, що сповільнюють рух, не можуть знизити твою швидкість нижче $s3% від нормальної швидкості руху. Триває $d." },
    { en = "Dominates the target undead creature up to level $s1, forcing it to do your bidding for $d.", ua = "Підпорядковує цільову нежить аж до $s1 рівня, змушуючи її виконувати твої накази протягом $d." },
    { en = "Creates a demonic gateway between two locations. Activating the gateway transports the user to the other gateway. Each player can use a Demonic Gateway only once per $<GatewayCooldown> sec.", ua = "Створює демонічну браму між двома місцями. Активація брами переносить користувача до іншої брами. Кожен гравець може скористатися Демонічною брамою лише раз на $<GatewayCooldown> сек." },
    { en = "$?s431044[Frostfire Bolt][Frostbolt] has a $s1% chance to grant a charge of Fingers of Frost.\n\n\n\nFingers of Frost causes your next Ice Lance to deal Shatter damage equal to $1246769s4 stacks of Freezing and does not consume Freezing stacks.\n\n\n\nMaximum $44544u $Lcharge:charges;.", ua = "$?s431044[Морозовогняна стріла][Морозна стріла] має $s1% шансу надати заряд Пальців морозу.\n\n\n\nПальці морозу змушують ваш наступний Крижаний спис завдати шкоди Розколювання, рівної $1246769s4 зарядам Заморожування, і не споживають заряди Заморожування.\n\n\n\nЩонайбільше $44544u $Lзаряд:заряди:зарядів;." },
    { en = "Summons a Ring of Frost for $d at the target location. Enemies entering the ring are incapacitated for $82691d. Limit 10 targets.\n\n\n\nWhen the incapacitate expires, enemies are slowed by $321329s1% for $321329d.", ua = "Прикликає Кільце морозу на $d у вибраному місці. Вороги, що заходять у кільце, знесилюються на $82691d. Обмеження — 10 цілей.\n\n\n\nКоли знесилення добігає кінця, вороги сповільнюються на $321329s1% на $321329d." },
    { en = "Transform into a Flame Ascendant for $d, instantly casting a Flame Shock and a $s10% effectiveness Lava Burst at up to $s7 nearby enemies.\n\n\n\nWhile ascended, Elemental Overload damage is increased by $s8% and spells affected by your Mastery: Elemental Overload cause $s9 additional Elemental $LOverload:Overloads;.", ua = "Перетворює вас на Вознесеного полум'я на $d, миттєво застосовуючи Шок полум'я та Спалах лави з $s10% ефективністю до $s7 ворогів поблизу.\n\n\n\nУ стані вознесіння шкода від Елементального перевантаження збільшена на $s8%, а закляття, на які впливає ваша Майстерність: Елементальне перевантаження, спричиняють $s9 додаткових Елементальних $LПеревантажень:Перевантажень;." },
    { en = "Transform into an Air Ascendant for $114051d and unleash Doom Winds, reducing the cooldown and cost of Stormstrike by $114051s9%, and transforming your auto attack and Stormstrike into Wind attacks which bypass armor and have a $114089r yd range.\n\n\n\nMaelstrom Weapon spenders have a ${$1252197s1/10}.1% chance to unleash Doom Winds per Maelstrom Weapon spent while Ascendance is not active.", ua = "Перетворює вас на Вознесеного Повітря на $114051d і вивільняє Вітри погибелі, зменшуючи перезарядження та вартість Удару бурі на $114051s9% і перетворюючи ваші автоатаки та Удар бурі на атаки вітру, що оминають броню й мають дальність $114089r ярдів.\n\n\n\nЗдібності, що витрачають Зброю Виру, мають ${$1252197s1/10}.1% шансу вивільнити Вітри погибелі за кожен витрачений заряд Зброї Виру, поки Вознесіння не активне." },
    { en = "Immediately heals for $294020s1 split between allies within $294020A1 yds and transforms into a Water Ascendant for $d.\n\n\n\nWhile ascended, Chain Heal jumps to $s9 additional allies with $s17% healing reduced for all jumps, Healing Wave always critical heals and heals $s14 additional $Lally:allies; at $s15% effectiveness, and the mana cost of Chain Heal and Healing Wave is reduced by $s16%.", ua = "Негайно зцілює на $294020s1, поділені між союзниками в межах $294020A1 м, і перетворює вас на Вознесеного води на $d.\n\n\n\nДоки ви вознесені, Ланцюгове зцілення перестрибує на $s9 додаткових союзників зі зниженням зцілення на $s17% за кожен стрибок, Хвиля зцілення завжди зцілює критично та зцілює $s14 додаткових $Lсоюзника:союзників; з $s15% ефективністю, а вартість мани Ланцюгового зцілення та Хвилі зцілення зменшується на $s16%." },
    { en = "Solar Eclipse increases Wrath's Astral Power generation by $s1% and Lunar Eclipse increases Starfire's Astral Power generation by $s2%.", ua = "Сонячне затемнення збільшує генерацію астральної сили від Гніву на $s1%, а Місячне затемнення збільшує генерацію астральної сили від Зоряного вогню на $s2%." },
    { en = "Reduces the cooldown of your Divine Shield, $?s184662[Shield of Vengeance, ][]$?s31850[Ardent Defender][Divine Protection], and Lay on Hands by $s1%.", ua = "Зменшує перезарядження твоїх «Божественного щита», $?s184662[«Щита помсти», ][]$?s31850[«Завзятого захисника»][«Божественного захисту»] та «Накладання рук» на $s1%." },
    { en = "An unholy pact that prevents fatal damage, instead absorbing incoming healing equal to the damage prevented, lasting $116888d.\n\n\n\nIf any healing absorption remains when this effect expires, you will die. This effect may only occur every $123981d.", ua = "Нечестивий пакт, що запобігає смертельній шкоді, натомість поглинаючи отримане зцілення в розмірі відверненої шкоди; триває $116888d.\n\n\n\nЯкщо на момент завершення цього ефекту лишається непоглинуте зцілення, ви помираєте. Цей ефект може спрацьовувати лише раз на $123981d." },
    { en = "Torpedoes you forward a long distance and increases your movement speed by $119085m1% for $119085d, stacking up to 2 times.", ua = "Вистрілює тебе вперед, мов торпеду, на велику відстань і збільшує швидкість руху на $119085m1% на $119085d. Ефект складається до 2 разів." },
    { en = "You shrug off attacks, delaying a portion of Physical damage based on your Agility, instead taking it over $124273d. Affects magical attacks at $s5% effectiveness.$?s383714[\n\n\n\n$@spelldesc383714][]", ua = "Ти струшуєш атаки, відкладаючи частину фізичної шкоди залежно від твоєї Спритності, натомість зазнаючи її протягом $124273d. Впливає на магічні атаки з $s5% дієвістю.$?s383714[\n\n\n\n$@spelldesc383714][]" },
    { en = "Incapacitates the target for $d. Limit 1. Damage may cancel the effect.", ua = "Виводить ціль з ладу на $d. Не більше 1 цілі. Шкода може скасувати ефект." },
    { en = "Reduces the cooldown of Roll by ${$m1/-1000} sec and increases its maximum number of charges by $m2.", ua = "Зменшує перезарядження «Перекиду» на ${$m1/-1000} сек. і збільшує його максимальну кількість зарядів на $m2." },
    { en = "Heals the target for $o1 over $d. While channeling, Enveloping Mist$?s227344[, Surging Mist,][]$?s124081[, Zen Pulse,][] and Vivify may be cast instantly on the target.$?a440008[\n\n\n\nFollows the target of your Enveloping Mist and Vivify.][]", ua = "Зцілює ціль на $o1 протягом $d. Під час підтримування Огортальний туман$?s227344[, Навальний туман,][]$?s124081[, Дзен-імпульс,][] і Пожвавлення можна сотворити на ціль миттєво.$?a440008[\n\n\n\nСлідує за ціллю твого Огортального туману і Пожвавлення.][]" },
    { en = "Breathe fire on targets in front of you, causing $s1 Fire damage. Deals reduced damage to secondary targets.\n\n\n\nTargets affected by Keg Smash will also burn, taking $123725o1 Fire damage and dealing $123725s2% reduced damage to you for $123725d.", ua = "Дихаєте вогнем на цілі перед собою, завдаючи $s1 шкоди від вогню. Другорядні цілі отримують зменшену шкоду.\n\n\n\nЦілі під дією Удару барилом також горітимуть, отримуючи $123725o1 шкоди від вогню та завдаючи вам на $123725s2% менше шкоди протягом $123725d." },
    { en = "Heals all party and raid members within $A1 yds for $s1 and clears them of $s4 harmful Magic, all Poison, and all Disease effects.\n\n\n\nHealing reduced beyond $s5 targets.", ua = "Зцілює всіх членів групи та рейду в межах $A1 ярдів на $s1 і звільняє їх від $s4 шкідливих ефектів магії, усіх ефектів отрути та всіх ефектів хвороби.\n\n\n\nЗцілення зменшується після $s5 цілей." },
    { en = "Summons a Jade Serpent Statue at the target location. When you channel Soothing Mist, the statue will also begin to channel Soothing Mist on your target, healing for $198533o1 over $198533d.", ua = "Прикликає статую Нефритового Змія у вказаному місці. Коли ти спрямовуєш «Заспокійливий туман», статуя теж починає спрямовувати «Заспокійливий туман» на твою ціль, зціляючи її на $198533o1 протягом $198533d." },
    { en = "Summons a Black Ox Statue at the target location for $d, pulsing threat to all enemies within $163178A1 yards.\n\n\n\nYou may cast Provoke on the statue to taunt all enemies near the statue.", ua = "Прикликає статую Чорного Вола в обрану місцину на $d, що випромінює загрозу на всіх ворогів у межах $163178A1 ярдів.\n\n\n\nВи можете сотворити Провокацію на статую, щоб роздратувати всіх ворогів поблизу неї." },
    { en = "Increases your maximum Chi by $s1, maximum Energy by $s3, and your Energy regeneration by $s2%.", ua = "Збільшує максимум ці на $s1, максимум енергії на $s3, а відновлення енергії — на $s2%." },
    { en = "Chug some Black Ox Brew, which instantly refills your Energy, Purifying Brew charges, and grants one charge of Celestial Brew or Celestial Infusion.", ua = "Ти вихиляєш «Варево Чорного Бика», що миттєво відновлює твою енергію та заряди «Очисного варева», а також дає один заряд «Небесного варева» чи «Небесного настою»." },
    { en = "Emits dazzling light in all directions, blinding enemies within $105421A1 yds, causing them to wander disoriented for $105421d. Damage may cancel the effect.", ua = "Випромінює сліпуче світло в усі боки, осліплюючи ворогів у радіусі $105421A1 м: вони дезорієнтовано блукають протягом $105421d. Шкода може скасувати ефект." },
    { en = "For every ${$c*$s1} Mana you spend, you gain 1 stack of Mana Tea, with a chance equal to your critical strike chance to generate 1 extra stack.\n\n\n\n$@spellicon115294$@spellname115294:\n\n$@spelldesc115294", ua = "За кожні ${$c*$s1} мани, що ти витрачаєш, ти отримуєш 1 заряд Чаю з мани, з імовірністю, рівною твоєму шансу критичного удару, згенерувати 1 додатковий заряд.\n\n\n\n$@spellicon115294$@spellname115294:\n\n$@spelldesc115294" },
    { en = "After you Wild Thrash, your pet's melee attacks also strike all nearby enemies for $s1% of the damage$?s378207[ and Kill Command strikes all nearby enemies for $s1% of the damage][] for the next ${$s2/1000}.1 sec. Deals reduced damage beyond $118459s2 targets.", ua = "Після вашого Дикого молотіння ближні атаки вашого улюбленця також вражають усіх ворогів поблизу на $s1% шкоди$?s378207[, а Наказ убити вражає всіх ворогів поблизу на $s1% шкоди][] протягом наступних ${$s2/1000}.1 с. Завдає зменшеної шкоди понад $118459s2 цілей." },
    { en = "Reduces the target's movement speed by $s1% for $d, duration refreshed by your melee attacks.$?s343731[ Targets already snared will be rooted for $116706d instead.][]", ua = "Зменшує швидкість руху цілі на $s1% протягом $d; тривалість оновлюється вашими атаками ближнього бою.$?s343731[ Цілі, вже сповільнені, натомість знерухомлюються на $116706d.][]" },
    { en = "Tiger Palm causes your next Blackout Kick to strike an additional time dealing $228649s1 Physical damage, stacking up to $202090u.\n\n\n\nBlackout Kick has a $s1% chance to reset the remaining cooldown on Rising Sun Kick.\n\n\n\n$?a210802[Each additional Blackout Kick restores ${$210803m1/100}.2% mana.][]", ua = "Долоня тигра робить так, що твій наступний Удар затьмарення вражає додатковий раз, завдаючи $228649s1 фізичної шкоди, накопичуючись до $202090u.\n\n\n\nУдар затьмарення має $s1% шанс скинути залишкове перезарядження Копняка висхідного сонця.\n\n\n\n$?a210802[Кожен додатковий Удар затьмарення відновлює ${$210803m1/100}.2% мани.][]" },
    { en = "Receive a jolt of energy, empowering your next $?a197895[$u spells][spell] cast:\n\n\n\n$@spellname124682: Immediately heals for $274062s1 and is instant cast.\n\n$@spellname115151: Duration increased by ${$s3/1000} sec.\n\n$@spellname107428: Cooldown reduced by ${$s1/-1000} sec.\n\n$?s353936[\n\n$@spellname117952: Knockback applied immediately.\n\n$@spellname109132: Refund a charge and heal yourself for $407058s1.][]", ua = "Отримай поштовх енергії, що підсилює наступне сотворення твого $?a197895[$u заклять][закляття]:\n\n\n\n$@spellname124682: Миттєво зцілює на $274062s1 і твориться миттєво.\n\n$@spellname115151: Тривалість збільшено на ${$s3/1000} с.\n\n$@spellname107428: Перезарядження зменшено на ${$s1/-1000} с.\n\n$?s353936[\n\n$@spellname117952: Відкидання застосовується миттєво.\n\n$@spellname109132: Повертає заряд і зцілює тебе на $407058s1.][]" },
    { en = "Jabs the target in the throat, interrupting spellcasting and preventing any spell from that school of magic from being cast for $d.", ua = "Б'є ціль у горло, перериваючи творення закляття й не даючи творити закляття цієї школи магії впродовж $d." },
    { en = "Increases a friendly target's movement speed by $s1% for $d and removes all roots and snares.", ua = "Збільшує швидкість руху дружньої цілі на $s1% на $d та знімає всі ефекти знерухомлення й сповільнення." },
    { en = "Form a Ring of Peace at the target location for $d. Enemies that enter will be ejected from the Ring.", ua = "Створює «Кільце миру» у вказаному місці на $d. Ворогів, які увійдуть, буде виштовхнуто з кільця." },
    { en = "Summons a whirling tornado around you, causing ${(1+$d/$t1)*$148187s1} Physical damage over $d to all enemies within $107270A1 yards. Deals reduced damage beyond $s1 targets.", ua = "Прикликає навколо тебе вихровий торнадо, що завдає ${(1+$d/$t1)*$148187s1} фізичної шкоди протягом $d усім ворогам у радіусі $107270A1 м. Якщо цілей більше ніж $s1, завдає їм зменшену шкоду." },
    { en = "Encases the target in a cocoon of Chi energy for $d, absorbing $<newshield> damage and increasing all healing over time received by $m2%.$?a388548[\n\n\n\nApplies Renewing Mist and Enveloping Mist to the target.][]", ua = "Огортає ціль коконом енергії ці протягом $d, поглинаючи $<newshield> шкоди та збільшуючи все отримане поступове зцілення на $m2%.$?a388548[\n\n\n\nНакладає на ціль Оновлювальний туман та Огортальний туман.][]" },
    { en = "Unleashes a devastating blast of chaos, dealing a critical strike for ${2*$s1} Chaos damage. Damage is further increased by your critical strike chance.", ua = "Вивільняє нищівний вибух хаосу, що завдає критичний удар на ${2*$s1} шкоди від хаосу. Шкода додатково збільшується твоїм шансом критичного удару." },
    { en = "Your Earth, Fire, and Storm Elementals are drawn from primal elementals $s1% more powerful than regular elementals, with additional abilities, and you gain direct control over your Primal Fire Elemental.", ua = "Твої елементалі землі, вогню та бурі походять від первісних елементалів, що на $s1% потужніші за звичайних і мають додаткові здібності, а первісним елементалем вогню ти керуєш безпосередньо." },
    { en = "Harnesses the raw power of the elements, dealing $s1 Elemental damage and increasing your Critical Strike or Haste by $118522s1% or Mastery by ${$173184s1*$168534bc1}% for $118522d.", ua = "Приборкує первісну силу стихій, завдаючи $s1 стихійної шкоди та збільшуючи твій критичний удар або поспіх на $118522s1% чи майстерність на ${$173184s1*$168534bc1}% на $118522d." },
    { en = "Your spells have a $s1% increased chance to deal a critical strike.\n\n\n\nYou gain $s2% more of the Critical Strike stat from all sources.", ua = "Ваші закляття мають на $s1% збільшений шанс завдати критичного удару.\n\n\n\nВи отримуєте на $s2% більше критичного удару з усіх джерел." },
    { en = "Increases your parry chance by $s1% and reduces all damage you take by $s2% for $d.", ua = "Збільшує твій шанс парирування на $s1% і зменшує всю отримувану шкоду на $s2% на $d." },
    { en = "Clears $s1% of your |CFFffffffStaggered|R damage, or a minimum of $s2% of your maximum health.", ua = "Знімає $s1% твоєї |CFFffffffвідтермінованої|R шкоди, але щонайменше $s2% твого максимального здоров'я." },
    { en = "Creates a ring of Holy energy around you that quickly expands to a $s2 yd radius, healing allies for $120692s1 and dealing $<holyhalodamage> Holy damage to enemies.\n\n\n\nHealing reduced beyond $s1 targets.", ua = "Створює навколо вас кільце Святої енергії, що швидко розширюється до радіуса $s2 м, зцілюючи союзників на $120692s1 і завдаючи ворогам $<holyhalodamage> Святої шкоди.\n\n\n\nЗцілення зменшено понад $s1 цілей." },
    { en = "Creates a ring of Shadow energy around you that quickly expands to a $s2 yd radius, healing allies for $120692s1 and dealing $<shadowhalodamage> Shadow damage to enemies. Healing reduced beyond $s1 targets.$?s137033[\n\n\n\n|cFFFFFFFFGenerates ${$m5/100} Insanity.|r][]", ua = "Створює довкола вас кільце енергії Тіні, що швидко розширюється до радіуса $s2 ярдів, зцілюючи союзників на $120692s1 і завдаючи $<shadowhalodamage> шкоди Тінню ворогам. За межами $s1 цілей зцілення зменшене.$?s137033[\n\n\n\n|cFFFFFFFFДає ${$m5/100} Безумства.|r][]" },
    { en = "Damage from your bleed effects has a $s1% chance of attracting a powerful wild beast that attacks your target for $s2 sec.", ua = "Шкода від твоїх ефектів кровотечі з імовірністю $s1% приваблює могутнього дикого звіра, який атакує твою ціль протягом $s2 сек." },
    { en = "Smash a keg of brew, dealing ${$s2*(1+$s8/100)} Physical damage to your primary target and $s2 Physical damage to all other enemies within $A2 yds, and reducing their movement speed by $m3% for $d. Deals reduced damage beyond $s7 targets.$?a322120[\n\n\n\nGrants Shuffle for $s6 sec and reduces the remaining cooldown on your Brews by $s4 sec.][]", ua = "Розбиває барило з варевом, завдаючи ${$s2*(1+$s8/100)} фізичної шкоди основній цілі та $s2 фізичної шкоди всім іншим ворогам у межах $A2 ярдів і зменшуючи їхню швидкість пересування на $m3% на $d. Завдає зменшеної шкоди понад $s7 цілей.$?a322120[\n\n\n\nДає Човгання на $s6 с і зменшує залишкове перезарядження твоїх варев на $s4 с.][]" },
    { en = "Draws upon surrounding shadows to empower your weapons, causing your attacks to deal $s1% additional damage as Shadow and causing your combo point generating abilities to generate double combo points for $d.", ua = "Черпає силу навколишніх тіней, щоб підсилити твою зброю: атаки завдають додатково $s1% шкоди Тінню, а здібності, що створюють очки комбо, протягом $d створюють удвічі більше очок комбо." },
    { en = "Places a feather at the target location, granting the first ally to walk through it $121557s1% increased movement speed for $121557d.$?a440670[ When an ally walks through a feather, you are also granted $440670s3% of its effect.][] Only 3 feathers can be placed at one time.", ua = "Розміщує перо у вказаному місці, надаючи першому союзнику, що пройде крізь нього, підвищену на $121557s1% швидкість руху на $121557d.$?a440670[ Коли союзник проходить крізь перо, ви також отримуєте $440670s3% його ефекту.][] Одночасно можна розмістити лише 3 пера." },
    { en = "While out of combat, your Chi balances to $s1 instead of depleting to empty.\n\n\n\nEvery $t1 sec, your next Tiger Palm also casts Expel Harm.\n\n\n\n$@spellicon451968 $@spellname451968\n\n$@spelldesc451968", ua = "Поза боєм твоє ці врівноважується до $s1 замість того, щоб виснажуватися до нуля.\n\n\n\nКожні $t1 с твоя наступна Долоня тигра також твориться як Вигнання шкоди.\n\n\n\n$@spellicon451968 $@spellname451968\n\n$@spelldesc451968" },
    { en = "You consume a healing elixir when you drop below $s1% health or generate excess healing elixirs, instantly healing you for $428439s1% of your maximum health.\n\n\n\nYou generate $s2 healing elixir every $t2 sec, stacking up to $s3 times.", ua = "Ви споживаєте цілющий еліксир, коли ваше здоров'я падає нижче $s1% або коли ви створюєте надлишок цілющих еліксирів, миттєво зцілюючись на $428439s1% вашого максимального здоров'я.\n\n\n\nВи створюєте $s2 цілющий еліксир кожні $t2 с, аж до $s3 нашарувань." },
    { en = "Summons an effigy of Xuen, the White Tiger for $d. Xuen attacks your primary target, and strikes 3 enemies within $123996A1 yards every $123999t1 sec with Tiger Lightning for $123996s1 Nature damage.$?s323999[\n\n\n\nEvery $323999s1 sec, Xuen strikes your enemies with Empowered Tiger Lightning dealing $323999s2% of the damage you have dealt to those targets in the last $323999s1 sec.][]", ua = "Прикликає подобу Сюеня, Білого Тигра, на $d. Сюень атакує твою основну ціль і вражає 3 ворогів у межах $123996A1 ярдів кожні $123999t1 с Тигровою блискавкою, завдаючи $123996s1 шкоди Природою.$?s323999[\n\n\n\nКожні $323999s1 с Сюень вражає твоїх ворогів Підсиленою тигровою блискавкою, завдаючи $323999s2% від шкоди, яку ти завдав цим цілям за останні $323999s1 с.][]" },
    { en = "When you take damage, you have a chance to summon a Healing Sphere.\n\n\n\n$@spellicon224863$@spellname224863:\n\n$@spelldesc224863", ua = "Коли ти зазнаєш шкоди, у тебе є шанс прикликати зцілющу сферу.\n\n\n\n$@spellicon224863$@spellname224863:\n\n$@spelldesc224863" },
    { en = "Wraps the target in healing mists, healing for $o1 over $d, and increasing healing received from your other spells by $m2%. $?a388847[\n\n\n\nApplies Renewing Mist for $388847s1 seconds to an ally within $388847r yds.][]", ua = "Огортає ціль зцілющими туманами, зцілюючи на $o1 протягом $d і збільшуючи зцілення, отримане від інших твоїх заклять, на $m2%. $?a388847[\n\n\n\nНакладає Оновлювальний туман на $388847s1 секунд на союзника в межах $388847r ярдів.][]" },
    { en = "Increases your movement speed by $s1%.", ua = "Збільшує твою швидкість пересування на $s1%." },
    { en = "An explosion of holy light around you deals up to $s1 Holy damage to enemies and up to $281265s1 healing to allies within $A1 yds, reduced if there are more than $s3 targets.", ua = "Вибух святого світла довкола тебе завдає ворогам до $s1 шкоди від Світла та зцілює союзників до $281265s1 у радіусі $A1 м; ефект слабшає, якщо цілей більше ніж $s3." },
    { en = "Your next Regrowth, $?$a1246126[Cyclone, ][]Rebirth, $?s473909[Ancient of Lore, ][]or Entangling Roots is instant, free, castable in all forms, and heals for an additional $s2%.", ua = "Твоє наступне закляття «Відростання», $?$a1246126[«Циклон», ][]«Відродження», $?s473909[«Древній знань», ][]або «Чіпке коріння» твориться миттєво й безкоштовно, доступне в усіх подобах, а його зцілення збільшене на $s2%." },
    { en = "Summons an effigy of Niuzao, the Black Ox for $d that attacks your primary target and Stomps when you cast Blackout Kick, damaging all nearby enemies.\n\n\n\nWhile active, $s2% of damage delayed by Stagger is instead Staggered by Niuzao, and Niuzao is healed for $s5% of your purified Stagger.", ua = "Прикликає подобу Нюцзао, Чорного Вола, на $d, що атакує вашу основну ціль і тупоче, коли ви творите Затьмарливий удар, завдаючи шкоди всім ворогам поблизу.\n\n\n\nПоки подоба активна, $s2% шкоди, відкладеної Затримкою, натомість затримує Нюцзао, а сам Нюцзао зцілюється на $s5% вашої очищеної Затримки." },
    { en = "You have a $m1% chance when you Tiger Palm to cause your next Blackout Kick to cost no Chi within $116768d.", ua = "Коли ти використовуєш «Долоню тигра», є $m1% шансу, що твій наступний «Удар затьмарення» протягом $116768d не коштуватиме ці." },
    { en = "Grows a healing blossom at the target location, restoring $81269s1 health to $?p138284[four][three] injured allies within $81269A1 yards every $81262t1 sec for $81262d. Limit 1.", ua = "Вирощує цілющу квітку у вказаному місці, що відновлює $81269s1 од. здоров'я $?p138284[чотирьом][трьом] пораненим союзникам у межах $81269A1 м кожні $81262t1 с упродовж $81262d. Не більше 1 квітки." },
    { en = "Removing harmful effects with Divine Shield heals you for $s1% for each effect removed.  This heal cannot exceed ${$m1*$m2}% of your maximum health.\n\n\n\nDivine Shield may now be cast while Forbearance is active.", ua = "Зняття шкідливих ефектів за допомогою «Божественного щита» зцілює вас на $s1% за кожен знятий ефект.  Це зцілення не може перевищувати ${$m1*$m2}% вашого максимального здоров'я.\n\n\n\n«Божественний щит» тепер можна творити, поки активне «Терпіння»." },
    { en = "Interrupts spellcasting, preventing any spell in that school from being cast for $d.", ua = "Перериває творення закляття й на $d не дає творити закляття цієї школи магії." },
    { en = "Calls forth a cataclysm at the target location, dealing $s1 Shadowflame damage to all enemies within $A1 yards and afflicting them with $?a445465[Wither][Immolate].", ua = "Прикликає катаклізм у вказане місце, завдаючи $s1 шкоди тіньовим полум'ям усім ворогам у межах $A1 ярдів і вражаючи їх $?a445465[Згасанням][Самоспаленням]." },
    { en = "Performs a devastating whirling upward strike, dealing ${3*$158221s1} damage to all nearby enemies and an additional $451767s1 damage to the first target struck. Damage reduced beyond $s1 targets.\n\n\n\nOnly usable while both Fists of Fury and Rising Sun Kick are on cooldown.", ua = "Завдає нищівного вихрового удару вгору, завдаючи ${3*$158221s1} шкоди всім ворогам поблизу та додатково $451767s1 шкоди першій враженій цілі. Шкода зменшується після $s1 цілей.\n\n\n\nМожна використати лише тоді, коли і Кулаки люті, і Удар вранішнього сонця перебувають на перезарядженні." },
    { en = "Every $?c1[$s1]?c2[$s3][$s2] Rage you spend$?c3[][ on attacks] reduces the remaining cooldown on Avatar and $?c1[Colossus Smash]?c2[Recklessness][Shield Wall] by 1 sec.", ua = "Кожні $?c1[$s1]?c2[$s3][$s2] Люті, які ви витрачаєте$?c3[][ на атаки], скорочують решту перезарядження Аватара та $?c1[Колосального удару]?c2[Безрозсудності][Щитової стіни] на 1 сек." },
    { en = "Calls down a meteor which lands at the target location after $177345d, dealing $351140s1 Fire damage to all enemies, and burns the ground, dealing ${8*$155158s1} Fire damage over $175396d to all enemies in the area.\n\n\n\n$?a1254857[The enemy closest to the center of the Meteor's impact takes $1254857s1% increased damage. ][]Damage reduced beyond 8 targets.", ua = "Прикликає метеор, який приземляється в обраному місці через $177345d, завдаючи $351140s1 вогняної шкоди всім ворогам і випалюючи землю, завдаючи ${8*$155158s1} вогняної шкоди протягом $175396d усім ворогам у цій зоні.\n\n\n\n$?a1254857[Ворог, найближчий до центру влучання Метеора, зазнає на $1254857s1% більше шкоди. ][]Шкода зменшена при понад 8 цілях." },
    { en = "Launches an Arcane Orb forward from your position, traveling up to 40 yds, dealing $153640s1 Arcane damage to enemies it passes through.\n\n\n\n|cFFFFFFFFGrants 1 Arcane Charge when cast and every time it deals damage.|r", ua = "Запускає вперед від вашої позиції арканну сферу, що пролітає до 40 ярдів, завдаючи $153640s1 арканної шкоди ворогам, крізь яких вона проходить.\n\n\n\n|cFFFFFFFFНадає 1 арканний заряд при творінні та щоразу, коли завдає шкоди.|r" },
    { en = "Your Shadowy Apparitions deal $s1% increased damage and have a chance to generate ${$m2/100} Insanity.", ua = "Твої тіньові привиддя завдають на $s1% більше шкоди й мають шанс згенерувати ${$m2/100} божевілля." },
    { en = "Mangle increases the duration of your next Ironfur by ${$213680m1/1000} sec, or the healing of your next Frenzied Regeneration by $213680s2%.", ua = "«Шматування» подовжує дію твого наступного «Залізного хутра» на ${$213680m1/1000} сек. або збільшує зцілення твоєї наступної «Шаленої регенерації» на $213680s2%." },
    { en = "Moonfire is usable in Cat Form, costs $155625c energy, and generates $155625s3 combo $lpoint:points;.", ua = "«Місячний вогонь» можна застосовувати в подобі кота; він коштує $155625c од. енергії та створює $155625s3 $lочко комбо:очки комбо;." },
    { en = "You can apply Rejuvenation twice to the same target. Rejuvenation's duration is increased by ${$s1/1000} sec.", ua = "Ти можеш накласти «Омолодження» двічі на ту саму ціль. Тривалість «Омолодження» збільшена на ${$s1/1000} сек." },
    { en = "Bristle your fur, causing you to generate Rage based on damage taken for $d.", ua = "Наїжачує твоє хутро, і впродовж $d ти накопичуєш лють залежно від отриманої шкоди." },
    { en = "Heals an ally for $s2 and an additional $o1 over $d.\n\n\n\nHealing increased by $s3% when cast on self.", ua = "Зцілює союзника на $s2 та додатково на $o1 протягом $d.\n\n\n\nЗцілення збільшено на $s3% при накладанні на себе." },
    { en = "Mark a second target as a Beacon, mimicking the effects of Beacon of Light. Your heals will now heal both of your Beacons, but at $s4% reduced effectiveness.", ua = "Позначає другу ціль як Маяк, відтворюючи ефекти «Маяка Світла». Твої зцілення тепер зцілюють обидва Маяки, але з ефективністю, зниженою на $s4%." },
    { en = "When an ally with your Beacon of Light is damaged, they absorb the next $157128s1 damage, increasing by up to $s3% based on their current health. Lower health allies are shielded for more.", ua = "Коли союзник із твоїм «Маяком Світла» зазнає шкоди, він поглинає наступні $157128s1 шкоди; поглинання зростає аж до $s3% залежно від його поточного здоров'я. Союзники з меншим здоров'ям отримують сильніший щит." },
    { en = "You and your allies within $m2 yards have $s1% increased movement speed. Stacks with other similar effects.", ua = "Швидкість руху твоя та союзників у радіусі $m2 м збільшена на $s1%. Складається з іншими подібними ефектами." },
    { en = "Pulses arcane energy around the target enemy or ally, dealing $s2 Arcane damage to all enemies within $A2 yds, and knocking them upward. A primary enemy target will take $s1% increased damage.", ua = "Пульсує арканною енергією довкола ворожої або союзної цілі, завдаючи $s2 арканної шкоди всім ворогам у радіусі $A2 м і підкидаючи їх угору. Основна ворожа ціль отримує на $s1% більше шкоди." },
    { en = "Causes a whirl of icy wind around the enemy, dealing $s1 Frost damage to the target and all other enemies within $a2 yds, freezing them in place for $d. Damage reduced beyond $s3 targets.", ua = "Здіймає вихор крижаного вітру навколо ворога, завдаючи $s1 шкоди від морозу цілі та всім іншим ворогам у радіусі $a2 м і заморожуючи їх на місці на $d. Шкода зменшується, якщо цілей більше за $s3." },
    { en = "Your finishing moves grant $s1 Energy per combo point spent and deal $s2% increased damage.", ua = "Твої завершальні прийоми дають $s1 од. Енергії за кожне витрачене очко комбо й завдають на $s2% більше шкоди." },
    { en = "Mangle generates ${$m1/10} more Rage and deals $s2% more damage.", ua = "«Шматування» породжує на ${$m1/10} більше люті та завдає на $s2% більше шкоди." },
    { en = "Swiftmend increases the healing of your next Regrowth or Rejuvenation by $114108s1%$?s392302[, and they apply to $392302s1 additional targets within $392302s2 yards.][.]", ua = "«Швидке зцілення» збільшує зцілення твого наступного «Відростання» чи «Омолодження» на $114108s1%$?s392302[, а також вони діють на $392302s1 додаткові цілі в радіусі $392302s2 м.][.]" },
    { en = "Wrath and Shred transfer $s1% of their damage and Starfire and Swipe transfer $s2% of their damage into healing onto a nearby ally. \n\n\n\nThis effect is increased by $s3% while Call of the Elder Druid is active.", ua = "Гнів і Шматування передають $s1% своєї шкоди, а Зоряний вогонь і Помах — $s2% своєї шкоди як зцілення найближчому союзникові.\n\n\n\nЦей ефект посилюється на $s3%, поки активний Поклик старійшини друїдів." },
    { en = "While in Cat Form, when you critically strike with an attack that generates a combo point, you gain an additional combo point. Damage over time cannot trigger this effect.\n\n\n\nMangle critical strike damage increased by $s2%.", ua = "Перебуваючи в Котячій подобі, коли ви завдаєте критичного удару атакою, що генерує комбо-очко, ви отримуєте додаткове комбо-очко. Періодична шкода не може спричинити цей ефект.\n\n\n\nШкода від критичних ударів Калічення підвищена на $s2%." },
    { en = "Smash the ground and shatter the armor of all enemies within $A1 yds, dealing $s1 Physical damage and increasing damage you deal to them by $208086s1% for $208086d. Deals reduced damage beyond $s3 targets.$?a1261048[\n\n\n\n|cFFFFFFFFGenerates ${$1261048s2/10} Rage.|r][]", ua = "Вдарте по землі й розтрощіть броню всіх ворогів у радіусі $A1 м, завдаючи $s1 фізичної шкоди й збільшуючи шкоду, яку ви їм завдаєте, на $208086s1% протягом $208086d. Завдає зменшеної шкоди понад $s3 цілей.$?a1261048[\n\n\n\n|cFFFFFFFFГенерує ${$1261048s2/10} люті.|r][]" },
    { en = "Your damaging spells incite the earth around you to come to your aid for $170377d, repeatedly dealing $170379s1 Nature damage to your most recently attacked target.", ua = "Твої атакувальні закляття спонукають землю довкола стати тобі на поміч на $170377d: вона раз у раз завдає $170379s1 шкоди від сил природи останній атакованій тобою цілі." },
    { en = "Renewing Mist now has ${$s5+$m1} charges and reduces the remaining cooldown of Rising Sun Kick by ${$s3/1000}.1 sec.\n\n\n\nRising Sun Kick now reduces the remaining cooldown of Renewing Mist by ${$s4/1000}.1 sec.", ua = "Оновлювальний туман тепер має ${$s5+$m1} зарядів і скорочує залишкове перезарядження Удару вранішнього сонця на ${$s3/1000}.1 сек.\n\n\n\nУдар вранішнього сонця тепер скорочує залишкове перезарядження Оновлювального туману на ${$s4/1000}.1 сек." },
    { en = "Unleash an eruption of fel energy, dealing $s2 Chaos damage and stunning all nearby enemies for $d.$?s320412[\n\n\n\nEach enemy stunned by Chaos Nova has a $s3% chance to generate a Lesser Soul Fragment.][]", ua = "Вивільняє вибух енергії Скверни, завдаючи $s2 шкоди Хаосом і приголомшуючи всіх ближніх ворогів на $d.$?s320412[\n\n\n\nКожен приголомшений Новою хаосу ворог має $s3% шанс згенерувати малий фрагмент душі.][]" },
    { en = "While you are above $s3% health, $s1% of all damage taken by allies within $210372a1 yds is redirected to you, up to a maximum of $<maxAbsorb> every $s1 sec.", ua = "Поки твоє здоров'я перевищує $s3%, $s1% усієї шкоди, якої зазнають союзники в межах $210372a1 м, перенаправляється на тебе — щонайбільше $<maxAbsorb> кожні $s1 с." },
    { en = "Disrupt generates $218903s1 Fury on a successful interrupt.", ua = "Зрив породжує $218903s1 од. Люті при успішному перериванні." },
    { en = "Reduces damage taken by $s1% and Bloodthirst restores an additional $s2% health for $d. Usable while stunned or incapacitated.", ua = "Зменшує отримувану шкоду на $s1%, а «Спрага крові» відновлює додаткових $s2% здоров'я протягом $d. Можна використати, навіть коли ти приголомшений чи недієздатний." },
    { en = "Unleash a series of $s1 brutal strikes for a total of $<damage> Physical damage.$?a1265357[\n\n\n\nWhile Improved Whirlwind is active, you instead deal $<aoedamage> Physical damage to all enemies in front of you. Deals reduced damage beyond $s10 targets.][]\n\n\n\n|cFFFFFFFFEnrages you.|r", ua = "Вивільніть серію з $s1 нещадних ударів, що завдають загалом $<damage> фізичної шкоди.$?a1265357[\n\n\n\nПоки активний Покращений вихор, ви натомість завдаєте $<aoedamage> фізичної шкоди всім ворогам перед вами. Завдає зменшеної шкоди понад $s10 цілей.][]\n\n\n\n|cFFFFFFFFРозлючує вас.|r" },
    { en = "$?s403826[Pierce enemies][Pierce an enemy] with a blade of light, dealing $s1 Holy damage$?s403826[ to your target and $404358s1 Holy damage to nearby enemies.][.]\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.|r", ua = "$?s403826[Пронизує ворогів][Пронизує ворога] клинком світла, завдаючи $s1 шкоди Світла$?s403826[ вашій цілі та $404358s1 шкоди Світла ворогам поблизу.][.]\n\n\n\n|cFFFFFFFFГенерує $s2 Святої Сили.|r" },
    { en = "You have a $s1% chance to gain a charge of Overpower when you use an attack that has a Rage cost.\n\nThis effect applies even if that ability's Rage cost has been reduced to zero.", ua = "Маєте $s1% шанс отримати заряд Подолання, коли використовуєте атаку, що коштує Лють.\n\nЦей ефект діє навіть якщо вартість Люті цієї здібності зведено до нуля." },
    { en = "Shadow Dance duration is increased by $1271702s3% of your Haste stat.\n\n\n\nCurrent bonus duration: ${$s1/1000}.2 sec", ua = "Тривалість «Танку тіней» збільшена на величину, що дорівнює $1271702s3% вашого Поспіху.\n\n\n\nПоточний бонус тривалості: ${$s1/1000}.2 сек." },
    { en = "A vicious slash dealing $s1 Physical damage.", ua = "Жорстокий поріз, що завдає $s1 фізичної шкоди." },
    { en = "Hurls a tar trap to the target location that creates a $187699s1 yd radius pool of tar around itself for $13810d when the first enemy approaches. All enemies have $135299s1% reduced movement speed while in the area of effect. Limit $s2. Trap will exist for $13809d.", ua = "Кидаєш смоляну пастку у вказане місце: коли наблизиться перший ворог, навколо неї на $13810d утворюється калюжа смоли радіусом $187699s1 м. Швидкість руху всіх ворогів у області дії зменшена на $135299s1%. Не більше $s2. Пастка існує $13809d." },
    { en = "Electrocutes all enemies in front of you, dealing $s1 Nature damage. \n\n\n\nEnhances your weapons for $187878d, causing Stormstrike and Lava Lash to discharge $195592s1 Nature damage split between up to $195592i enemies in front of you. $?s1252373[Multiple applications may overlap.][]", ua = "Б'є струмом усіх ворогів перед вами, завдаючи $s1 шкоди природою.\n\n\n\nПідсилює вашу зброю на $187878d, через що Штормовий удар і Лавовий батіг розряджають $195592s1 шкоди природою, поділеної між щонайбільше $195592i ворогами перед вами. $?s1252373[Кілька застосувань можуть накладатися.][]" },
    { en = "When you deal damage with a melee weapon, you have a chance to generate Maelstrom Weapon, stacking up to $344179u times. \n\n\n\nEach stack of Maelstrom Weapon reduces the cast time of your next Lightning Bolt or Chain Lightning by $s5% and increases its damage by $s3%.", ua = "Коли ви завдаєте шкоди зброєю ближнього бою, ви маєте шанс отримати Зброю Виру, що накопичується до $344179u разів. \n\n\n\nКожен заряд Зброї Виру зменшує час прочитання вашого наступного Удару блискавки чи Ланцюгової блискавки на $s5% і збільшує його шкоду на $s3%." },
    { en = "Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies. Affects $x1 total targets$?a383303[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed and damage.|r]?a187880[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed.|r][]$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s5 Maelstrom per target hit.|r][]", ua = "Шпурляє блискавку в ворога, завдаючи $s1 шкоди природою, а потім перестрибує на інших ближніх ворогів. Уражає $x1 цілей загалом$?a383303[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання та шкоди.|r]?a187880[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання.|r][]$?a343725[\n\n\n\n|cFFFFFFFFСтворює $343725s5 Виру за кожну уражену ціль.|r][]" },
    { en = "Engulfs you in flames for $d, increasing your spells' critical strike chance by $s1%.$?a383967[\n\n\n\nAdditionally, increases your Mastery by $383967s1% of your critical strike chance.]?a1254512[\n\n\n\nAdditionally, increases your spell damage by $s3% plus an additional $1254512s1% of your critical strike chance.]?449382[\n\n\n\nAdditionally, increases your spell damage by $s3%.][]\n\n\n\nCastable while casting other spells.", ua = "Огортає вас полум'ям на $d, підвищуючи шанс критичного удару ваших заклять на $s1%.$?a383967[\n\n\n\nКрім того, підвищує вашу майстерність на $383967s1% від вашого шансу критичного удару.]?a1254512[\n\n\n\nКрім того, підвищує шкоду ваших заклять на $s3% плюс додатково $1254512s1% від вашого шансу критичного удару.]?449382[\n\n\n\nКрім того, підвищує шкоду ваших заклять на $s3%.][]\n\n\n\nМожна творити під час прочитання інших заклять." },
    { en = "Ice shards pelt the target area, dealing ${$190357m1*8} Frost damage over $d and reducing movement speed by $12486s1% for $12486d.\n\n\n\n|cFFFFFFFFThis spell is cast at a selected location", ua = "Уламки криги осипають вибрану ділянку, завдаючи ${$190357m1*8} шкоди від морозу протягом $d і зменшуючи швидкість пересування на $12486s1% на $12486d.\n\n\n\n|cFFFFFFFFЦе закляття твориться у вибраному місці" },
    { en = "$?s431044[Frostfire Bolt][Frostbolt] has a $m1% chance to reset the remaining cooldown on Flurry and cause your next Flurry to deal $190446s2% increased damage.", ua = "$?s431044[Льодовогняна стріла][Крижана стріла] має $m1% шанс скинути решту перезарядження Шквалу і зробити так, що ваш наступний Шквал завдасть на $190446s2% більше шкоди." },
    { en = "Fight through the pain, ignoring $s2% of damage taken $?c1[for $d sec or ][]until ${($s1)*(1+$@versadmg)} damage has been prevented.$?c3[\n\n\n\nRepeated uses of Ignore Pain accumulate, up to ${$mhp*$s4/100} total damage prevented.][]", ua = "Долайте біль, ігноруючи $s2% отриманої шкоди $?c1[протягом $d с або ][]доки не буде відвернено ${($s1)*(1+$@versadmg)} шкоди.$?c3[\n\n\n\nПовторні застосування Ігнорування болю накопичуються, відвертаючи загалом до ${$mhp*$s4/100} шкоди.][]" },
    { en = "Increases the damage of Bite, Claw, Smack and the effectiveness of your pet's unique abilities by $s1%.\n\n\n\nIncreases the effectiveness of your pet's Predator's Thirst, Endurance Training, and Pathfinding passives by $s3%.", ua = "Збільшує шкоду Укусу, Кігтя, Ляпасу та ефективність унікальних здібностей вашого улюбленця на $s1%.\n\n\n\nЗбільшує ефективність пасивних здібностей вашого улюбленця: Спраги хижака, Тренування витривалості й Пошуку шляху на $s3%." },
    { en = "Charge yourself with lightning, causing your next $s5 Lightning Bolts to deal $s2% more damage, and also causes your next $s5 Lightning Bolts or Chain Lightings to be instant cast and trigger an Elemental Overload on every target.$?a1264863[\n\n\n\nAdditionally, increases Lightning Bolt and Chain Lightning damage by ${$1264863s2}.1%.][]$?a1264762[\n\n\n\n|cFFFFFFFFGenerates $1264762s2 Maelstrom.|r][]", ua = "Заряджає вас блискавками, через що ваші наступні $s5 Блискавок завдають на $s2% більше шкоди, а також ваші наступні $s5 Блискавок або Ланцюгових блискавок стають миттєвими й викликають Стихійне перевантаження на кожній цілі.$?a1264863[\n\n\n\nКрім того, збільшує шкоду Блискавки та Ланцюгової блискавки на ${$1264863s2}.1%.][]$?a1264762[\n\n\n\n|cFFFFFFFFСтворює $1264762s2 Виру.|r][]" },
    { en = "Casting Stormkeeper summons a $?a117013[Primal][Greater] Storm Elemental to hurl gusts of wind at your enemies for $157299d.", ua = "Творення Хранителя бур прикликає $?a117013[первісного][величного] Стихію бурі, що жбурляє пориви вітру у ваших ворогів протягом $157299d." },
    { en = "Casting Lava Burst has a $s1% chance to cause your next Lightning Bolt$?a454009[, Tempest,][] or Chain Lightning cast to trigger Elemental Overload an additional time, stacking up to $191877U times.", ua = "Творення Виверження лави має $s1% шанс зробити так, що наступне творіння Стріли блискавки$?a454009[, Бурі,][] чи Ланцюгової блискавки спрацює Стихійне перевантаження ще раз, накопичуючись до $191877U разів." },
    { en = "Summons a totem at the target location that gathers electrical energy from the surrounding air and explodes after $s2 sec, stunning all enemies within $118905A1 yards for $118905d.", ua = "Прикликає тотем у вказаному місці, що збирає електричну енергію з навколишнього повітря й вибухає за $s2 сек., оглушуючи всіх ворогів у радіусі $118905A1 м на $118905d." },
    { en = "A gust of wind hurls you forward.", ua = "Порив вітру жбурляє тебе вперед." },
    { en = "Summons a totem at the target location for $d, continually granting all allies who pass within $a1 yards $192082s1% increased movement speed for $192082d.", ua = "Прикликає тотем у вказаному місці на $d, що постійно дарує всім союзникам, які проходять у радіусі $a1 м, прискорення руху на $192082s1% на $192082d." },
    { en = "Increases armor by ${$s1*$AGI/100} for $d.$?a231070[ Multiple uses of this ability may overlap.][]", ua = "Збільшує броню на ${$s1*$AGI/100} на $d.$?a231070[ Кілька застосувань цієї здібності можуть діяти одночасно.][]" },
    { en = "Reduces the cooldown of Spiritwalker's Grace by ${$m1/-1000} sec and increases your movement speed by $s2% while it is active.", ua = "Зменшує перезарядження «Грації духоходця» на ${$m1/-1000} сек. і збільшує твою швидкість руху на $s2%, поки вона діє." },
    { en = "Casting Flash Heal on yourself reduces all damage you take by $193065s1% for $193065d.", ua = "Творення «Швидкого зцілення» на себе зменшує всю отримувану тобою шкоду на $193065s1% на $193065d." },
    { en = "Penance fires one additional bolt of holy light over its duration.", ua = "«Покаяння» випускає один додатковий снаряд святого світла протягом своєї дії." },
    { en = "You regenerate mana $s1% faster.", ua = "Твоя мана відновлюється на $s1% швидше." },
    { en = "Your Prayer of Mending has a $s1% chance to leave a Renew on each target it heals.\n\n\n\n$@spellicon139 $@spellname139\n\n$@spelldesc139", ua = "Ваша Молитва зцілення має $s1% шанс залишити Оновлення на кожній цілі, яку зцілює.\n\n\n\n$@spellicon139 $@spellname139\n\n$@spelldesc139" },
    { en = "A quick shot causing ${$s2*$<mult>} Physical damage.\n\n\n\nReduces the cooldown of Kill Command by $s3 sec.", ua = "Швидкий постріл, що завдає ${$s2*$<mult>} фізичної шкоди.\n\n\n\nЗменшує час перезарядження Наказу вбити на $s3 сек." },
    { en = "Gain $s1 additional max combo point.\n\n\n\nYour finishing moves that consume more than $s3 combo points have increased effects, and your finishing moves deal $s4% increased damage.", ua = "Дає $s1 додаткове максимальне очко комбо.\n\n\n\nВаші завершальні прийоми, що витрачають понад $s3 очок комбо, мають посилені ефекти, а ваші завершальні прийоми завдають на $s4% більше шкоди." },
    { en = "Activating Bestial Wrath grants $s1 $Lcharge:charges; of Barbed Shot.", ua = "Активація Звіриного гніву надає $s1 $Lзаряд:зарядів; Колючого пострілу." },
    { en = "$?s200758[Gloomblade][Backstab] and Shadowstrike have a $s1% chance to create a Shadow Clone that repeats the attack for $s2% of normal damage as Shadow.", ua = "$?s200758[Похмурий клинок][Удар у спину] і Тіньовий удар мають $s1% шанс створити Тіньового клона, який повторює атаку, завдаючи $s2% звичайної шкоди як шкоди тінню." },
    { en = "Haste increased by ${$s1/10}.1%.", ua = "Поспіх збільшено на ${$s1/10}.1%." },
    { en = "Increases the healing you receive from Crimson Vial, healing potions, and healthstones by $s1%.", ua = "Збільшує зцілення, яке ти отримуєш від «Багряного фіала», цілющих зіль та каменів здоров'я, на $s1%." },
    { en = "Call down a burst of energy, causing $s1 Arcane damage to the target, and $?a429523[${($m1*$m3/100)/(1+$429523s1/100)}][${$m1*$m3/100}] Arcane damage to all other enemies within $A1 yards. Deals reduced damage beyond $s5 targets.\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Astral Power.|r", ua = "Закликає вибух енергії, завдаючи $s1 арканної шкоди цілі та $?a429523[${($m1*$m3/100)/(1+$429523s1/100)}][${$m1*$m3/100}] арканної шкоди всім іншим ворогам у радіусі $A1 ярдів. Завдає зменшеної шкоди понад $s5 цілей.\n\n\n\n|cFFFFFFFFГенерує ${$m2/10} астральної сили.|r" },
    { en = "A burst of light heals the target and $s3 injured allies within $A2 yards for $s2, and applies Atonement for $s4% of its normal duration.", ua = "Спалах світла зцілює ціль і $s3 поранених союзників у радіусі $A2 м на $s2 та накладає «Спокуту» на $s4% її звичайної тривалості." },
    { en = "Your ranged auto attacks have a $s1% chance to trigger Lock and Load, causing your next Aimed Shot to cost no Focus and be instant.", ua = "Твої автоматичні атаки дальнього бою мають $s1% шансу активувати «Зброю до бою», завдяки чому твій наступний «Прицільний постріл» не коштує зосередження і виконується миттєво." },
    { en = "Your Blood Plague and Death and Decay deal damage $s2% more often.\n\n\n\nAdditionally, your Blood Plague leeches $s3% more Health.", ua = "Ваші Кров'яна пошесть та Смерть і розклад завдають шкоди на $s2% частіше.\n\n\n\nКрім того, ваша Кров'яна пошесть висмоктує на $s3% більше Здоров'я." },
    { en = "Your Runic Power spending abilities increase your melee attack speed by $s1% for $194879d, stacking up to $194879u times.", ua = "Твої здібності, що витрачають рунічну силу, збільшують швидкість твоїх атак ближнього бою на $s1% на $194879d. Складається до $194879u разів." },
    { en = "Each Rune spent during Remorseless Winter increases its damage by $211805s1%, and extends its duration by ${$m1/10}.1 sec.", ua = "Кожна руна, витрачена під час «Безжальної зими», збільшує її шкоду на $211805s1% і подовжує її тривалість на ${$m1/10}.1 сек." },
    { en = "Raise Dead summons an additional skeletal archer at your command that shoots Blighted Arrows.\n\n\n\n$@spellicon1239356$@spellname1239356\n\n$@spelldesc1239356", ua = "Підняття мертвих прикликає під ваше командування додаткового кістяного лучника, що стріляє Зараженими стрілами.\n\n\n\n$@spellicon1239356$@spellname1239356\n\n$@spelldesc1239356" },
    { en = "Smash the target, dealing $s2 Physical damage and generating $s3 charges of Bone Shield.\n\n\n\n$@spellicon195181 |cFFFFFFFF$@spellname195181|r\n\n$@spelldesc195181", ua = "Трощить ціль, завдаючи $s2 фізичної шкоди та створюючи $s3 заряди Кістяного щита.\n\n\n\n$@spellicon195181 |cFFFFFFFF$@spellname195181|r\n\n$@spelldesc195181" },
    { en = "Your auto attacks have a chance to summon a Bloodworm.\n\n\n\nBloodworms deal minor damage to your target for $198494d and then burst, healing you for $s3% of your missing health.\n\n\n\nIf you drop below $s2% health, your Bloodworms will immediately burst and heal you.", ua = "Ваші автоатаки мають шанс прикликати Кров'яного черв'яка.\n\n\n\nКров'яні черви завдають незначної шкоди вашій цілі впродовж $198494d, а потім лопаються, зцілюючи вас на $s3% вашої нестачі здоров'я.\n\n\n\nЯкщо ваше здоров'я падає нижче $s2%, ваші Кров'яні черви негайно лопаються й зцілюють вас." },
    { en = "$?a445465[Wither][Corruption] is now permanent and deals $s2% increased damage.\n\n\n\nDuration reduced to $s1 sec against players.", ua = "$?a445465[Усихання][Розтління] тепер постійне й завдає на $s2% більше шкоди.\n\n\n\nПроти гравців тривалість зменшено до $s1 сек." },
    { en = "Seed of Corruption now embeds demon seeds into $s1 additional nearby enemies at $s2% effectiveness.", ua = "«Зерно псування» тепер засіває демонічні зерна в $s1 додаткових ворогів поблизу з $s2% ефективності." },
    { en = "Demonic forces suck $s1 of your Wild Imps toward the target, and then cause them to violently explode, dealing $196278s2 Shadowflame damage to all enemies within $196278A3 yards.", ua = "Демонічні сили затягують $s1 твоїх диких імпів до цілі та змушують їх несамовито вибухнути, завдаючи $196278s2 шкоди тіньового полум'я всім ворогам у радіусі $196278A3 м." },
    { en = "Conflagrate reduces the cast time of your next Incinerate, Chaos Bolt, or Soul Fire by $117828s1%. Maximum $?s267115[$s2][$s1] charges.", ua = "Займання зменшує час прочитання вашого наступного Спопеління, Хаосного болта чи Вогню душі на $117828s1%. Щонайбільше $?s267115[$s2][$s1] зарядів." },
    { en = "Incinerate now also hits all enemies near your target for $s1% damage.", ua = "«Спопеління» тепер також влучає у всіх ворогів поруч із ціллю, завдаючи їм $s1% шкоди." },
    { en = "Launches $s1 bolts of felfire over $d at random targets afflicted by your $?a445465[Wither][Immolate] within $196449A1 yds. Each bolt deals $196448s1 Fire damage to the target and $196448s2 Fire damage to nearby enemies.", ua = "Випускає $s1 стріл вогню Скверни протягом $d у випадкові цілі, що зазнають вашого $?a445465[В'янення][Самоспалення] у межах $196449A1 ярд. Кожна стріла завдає цілі $196448s1 шкоди вогнем і $196448s2 шкоди вогнем ворогам поблизу." },
    { en = "Reduces the cooldown of Psychic Scream by ${$m1/-1000} sec.", ua = "Скорочує перезарядження «Психічного крику» на ${$m1/-1000} сек." },
    { en = "Increases the duration of Spirit of Redemption by $s1% and the range of its spells by $s2%.", ua = "Подовжує дію «Духа спокути» на $s1%, а дальність його заклять збільшує на $s2%." },
    { en = "Summons darkness around you in a$?a357419[ 12 yd][n 8 yd] radius, granting friendly targets a $209426s2% chance to avoid all damage from an attack. Lasts $d.\n\n\n\nChance to avoid damage increased by $s3% when not in a raid.", ua = "Огортає вас темрявою в радіусі$?a357419[ 12 м][ 8 м], даючи дружнім цілям $209426s2% шанс уникнути всієї шкоди від атаки. Триває $d.\n\n\n\nШанс уникнути шкоди збільшено на $s3%, коли ви не в рейді." },
    { en = "Drinking from your Brews has a $h% chance to toss a keg high into the air that lands nearby after $s1 sec, dealing $196733s1 Physical damage to all enemies within $196733A1 yards and reducing their movement speed by $196733m2% for $196733d.", ua = "Коли ти п'єш свої варева, з імовірністю $h% високо в повітря злітає барило, що падає поруч через $s1 сек., завдаючи $196733s1 фізичної шкоди всім ворогам у радіусі $196733A1 м і сповільнюючи їхній рух на $196733m2% на $196733d." },
    { en = "Blackout Kick also empowers your next ability:\n\n\n\n$@spellicon100780 Tiger Palm: Damage increased by $228563s1%.\n\n\n\n$@spellicon121253 Keg Smash: Reduces the remaining cooldown on your Brews by $s3 additional sec.", ua = "Удар затьмарення також підсилює вашу наступну здібність:\n\n\n\n$@spellicon100780 Долоня тигра: шкода збільшена на $228563s1%.\n\n\n\n$@spellicon121253 Удар діжкою: додатково зменшує залишкове перезарядження ваших Напоїв на $s3 сек." },
    { en = "Stagger is $s1% more effective at delaying damage.\n\n\n\nPurifying Brew refunds ${$s3/1000}.1 sec of its cooldown if cast at $@spellname1260619.", ua = "Хитання на $s1% дієвіше відкладає шкоду.\n\n\n\nОчисне варево повертає ${$s3/1000}.1 с свого перезарядження, якщо сотворене при $@spellname1260619." },
    { en = "Each successive attack that triggers Combo Strikes in a row grants $196741s1% increased damage, stacking up to $196741u times.", ua = "Кожна наступна атака поспіль, що запускає «Комбо-удари», дає $196741s1% додаткової шкоди, з накопиченням до $196741u разів." },
    { en = "Chills the target with frost, causing $s1 Frost damage and reducing the target's movement speed by $s2% for $d.$?a343725&a210714[\n\n\n\n|cFFFFFFFFGenerates ${$343725s10+$343725s7} Maelstrom.|r]?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s10 Maelstrom.|r][]", ua = "Морозить ціль кригою, завдаючи $s1 шкоди морозом і зменшуючи швидкість пересування цілі на $s2% протягом $d.$?a343725&a210714[\n\n\n\n|cFFFFFFFFСтворює ${$343725s10+$343725s7} Виру.|r]?a343725[\n\n\n\n|cFFFFFFFFСтворює $343725s10 Виру.|r][]" },
    { en = "Garrote silences the target for $s2 sec when used from Stealth.\n\n\n\nEnemies silenced by Garrote deal $256148s1% reduced damage for $256148d.", ua = "«Гарота» занімлює ціль на $s2 сек., якщо застосована зі схованки.\n\n\n\nВороги, занімлені «Гаротою», завдають на $256148s1% менше шкоди протягом $256148d." },
    { en = "Movement speed increased by $s1%.", ua = "Швидкість руху збільшено на $s1%." },
    { en = "Holy Shock reduces the cooldown of Judgment by ${$m1/-1000}.1 sec and Crusader Strike reduces the cooldown of Judgment by ${$m2/-1000}.1 sec.", ua = "«Святий шок» зменшує перезарядження «Осуду» на ${$m1/-1000}.1 сек., а «Удар хрестоносця» зменшує перезарядження «Осуду» на ${$m2/-1000}.1 сек." },
    { en = "Opportunity increases the damage of Pistol Shot by an additional $s1%. Each charge of Opportunity consumed by Pistol Shot generates $1254567s1 combo $Lpoint:points;.", ua = "Нагода збільшує шкоду від Пострілу з пістоля додатково на $s1%. Кожен заряд Нагоди, витрачений Пострілом з пістоля, дає $1254567s1 комбо-$Lочко:очка;." },
    { en = "Gain ${$196980s1*$196980d/$196980t1+$196980s2} Energy over $196980d when you enter Stealth or activate Shadow Dance.", ua = "Отримуєш ${$196980s1*$196980d/$196980t1+$196980s2} енергії протягом $196980d, коли входиш у непомітність або активуєш «Танець тіней»." },
    { en = "The cooldowns of your Holy Words are reduced by an additional $s1% when you cast the relevant spells.", ua = "Перезарядження твоїх «Святих слів» додатково скорочується на $s1%, коли ти твориш відповідні закляття." },
    { en = "When your Power Word: Shield is completely absorbed, you restore $<mana>% of your maximum mana.", ua = "Коли ваше Слово сили: Щит повністю поглинуто, ви відновлюєте $<mana>% від максимальної мани." },
    { en = "Ironbark increases healing from your heal over time effects by $s1%.", ua = "«Залізнокора» збільшує зцілення від твоїх ефектів періодичного зцілення на $s1%." },
    { en = "Reduces the cooldown of Tranquility by ${$m1/-1000} sec.\n\n\n\nWhile channeling Tranquility, you take $740s5% reduced damage and are immune to knockbacks.", ua = "Скорочує перезарядження Спокою на ${$m1/-1000} сек.\n\n\n\nПід час підтримання Спокою ви отримуєте на $740s5% менше шкоди й невразливі до відкидань." },
    { en = "Shatters a line of earth in front of you with your main hand weapon, causing $s1 Flamestrike damage to any enemy hit.", ua = "Розколює землю смугою перед тобою зброєю в основній руці, завдаючи кожному враженому ворогу $s1 шкоди від вогняного удару." },
    { en = "Mastery: Lightbringer now increases your healing based on the target's proximity to either you or your Beacon of Light, whichever is closer.", ua = "«Майстерність: Світлоносець» тепер збільшує твоє зцілення залежно від відстані цілі до тебе або до твого «Маяка Світла» — залежно від того, що ближче." },
    { en = "Increases the range of all of your spells by $s1 yards.", ua = "Збільшує дальність усіх твоїх заклять на $s1 м." },
    { en = "Shapeshift into $?s114301[Astral Form][Moonkin Form], increasing the damage of your spells by $s7% and your armor by $m3%, and granting protection from Polymorph effects.\n\n\n\nThe act of shapeshifting frees you from movement impairing effects.", ua = "Перевтілює вас у $?s114301[астральну подобу][подобу місяцерода], збільшуючи шкоду ваших заклять на $s7%, а броню — на $m3%, і надаючи захист від ефектів Перетворення.\n\n\n\nСамé перевтілення звільняє вас від ефектів, що обмежують рух." },
    { en = "Call down a burst of energy, causing $s1 Arcane damage to the target, and ${$m1*$m2/100} Arcane damage to all other enemies within $A1 yards. Deals reduced damage beyond $s3 targets.", ua = "Закликає сплеск енергії, що завдає $s1 арканної шкоди цілі та ${$m1*$m2/100} арканної шкоди всім іншим ворогам у радіусі $A1 м. Завдає менше шкоди понад $s3 цілей." },
    { en = "Tranquility extends the duration of all of your heal over time effects by $s1 sec every $740t1 sec.", ua = "«Умиротворення» подовжує тривалість усіх твоїх ефектів поступового зцілення на $s1 сек. кожні $740t1 сек." },
    { en = "Evangelism increases your healing and absorption effects by $81700s1% for $81700d.", ua = "«Проповідництво» збільшує твої ефекти зцілення та поглинання на $81700s1% на $81700d." },
    { en = "Thunder Focus Tea now empowers your next ${$m1+1} spells.", ua = "«Чай громової зосередженості» тепер підсилює твої наступні ${$m1+1} закляття." },
    { en = "Increases Enveloping Mist's duration by ${$m2/1000} sec and its healing bonus by $s1%.", ua = "Збільшує тривалість «Огортального туману» на ${$m2/1000} сек., а його бонус до зцілення — на $s1%." },
    { en = "$?s399491[Sheilun's Gift][Vivify] has a $s2% chance to cause your next Rising Sun Kick or Enveloping Mist to generate $s1 stack of Mana Tea.\n\n\n\nEnveloping Mist and Rising Sun Kick have a $s3% chance to cause your next $?s399491[Sheilun's Gift][Vivify] to generate $s1 stack of Mana Tea.", ua = "$?s399491[Дар Шейлун][Оживлення] має $s2% шансу змусити ваш наступний Удар висхідного сонця чи Огортальний туман створити $s1 заряд Чаю мани.\n\n\n\nОгортальний туман та Удар висхідного сонця мають $s3% шансу змусити ваш наступний $?s399491[Дар Шейлун][Оживлення] створити $s1 заряд Чаю мани." },
    { en = "Blasts all enemies in front of you,$?s320415[ dealing guaranteed critical strikes][] for up to $<dmg> Chaos damage over $d. Deals reduced damage beyond $s5 targets.$?s343311[\n\n\n\nWhen Eye Beam finishes fully channeling, your Haste is increased by an additional $343312s1% for $343312d.][]", ua = "Уражає всіх ворогів перед вами,$?s320415[ завдаючи гарантованих критичних ударів][] до $<dmg> хаотичної шкоди протягом $d. Завдає зменшеної шкоди понад $s5 цілей.$?s343311[\n\n\n\nКоли Промінь з очей завершує повну каналізацію, ваш Поспіх збільшується додатково на $343312s1% протягом $343312d.][]" },
    { en = "Shadow Word: Pain has a chance to empower your next Penance with Shadow, increasing its effectiveness by $198069s1%.", ua = "«Слово тіні: Біль» має шанс посилити тінню твоє наступне «Покаяння», збільшуючи його ефективність на $198069s1%." },
    { en = "Calls forth a $?a117013[Primal][Greater] Earth Elemental to protect you$?a1279819[, increasing your maximum health by $381755s1%][ and your allies, generating high threat and taunting enemies periodically] for $188616d.", ua = "Прикликає $?a117013[первісного][більшого] елементаля землі, що захищає вас$?a1279819[, збільшуючи ваше максимальне здоров'я на $381755s1%][ та ваших союзників, створюючи високу загрозу й періодично глузуючи з ворогів] протягом $188616d." },
    { en = "Remove all snares and vault away. Nearby enemies take $198813s2 Physical damage$?s320635[ and have their movement speed reduced by $198813s1% for $198813d][].$?a203551[\n\n\n\n|cFFFFFFFFGenerates ${($203650s1/5)*$203650d} Fury over $203650d if you damage an enemy.|r][]", ua = "Знімає всі ефекти знерухомлення й відстрибує назад. Ближні вороги дістають $198813s2 фізичної шкоди$?s320635[, а їхня швидкість пересування знижується на $198813s1% на $198813d][].$?a203551[\n\n\n\n|cFFFFFFFFГенерує ${($203650s1/5)*$203650d} люті протягом $203650d, якщо ви завдаєте шкоди ворогу.|r][]" },
    { en = "Conjures a cloud of hypnotic mist that slowly travels forward. Enemies touched by the mist fall asleep, Disoriented for $198909d.", ua = "Створює хмару гіпнотичного туману, що повільно пливе вперед. Вороги, яких торкнеться туман, засинають і лишаються дезорієнтованими протягом $198909d." },
    { en = "Allies are healed for $199423s1 when you cast Blessing of Protection or Blessing of Sacrifice on them.", ua = "Союзники зцілюються на $199423s1, коли ти твориш на них «Благословення захисту» або «Благословення жертовності»." },
    { en = "You and your pet blend into the surroundings and gain stealth for $d. While camouflaged, you will heal for $s4% of maximum health every $T4 sec.", ua = "Ви та ваш улюбленець зливаєтеся з оточенням і набуваєте непомітності на $d. Поки ви замаскований, ви зцілюєтеся на $s4% максимального здоров'я кожні $T4 сек." },
    { en = "Your direct damage spells inflict $s1% of their damage on all other targets afflicted by your Vampiric Touch within $199486A2 yards.\n\n\n\nDoes not apply to damage from Shadowy Apparitions, Shadow Word: Pain, and Vampiric Touch.", ua = "Ваші закляття прямої шкоди завдають $s1% своєї шкоди всім іншим цілям під дією вашого «Вампірського дотику» в межах $199486A2 м.\n\n\n\nНе застосовується до шкоди від Тіньових примар, «Слова тіні: Біль» і «Вампірського дотику»." },
    { en = "When you cast Barbed Shot, your pet stomps the ground, dealing $201754s1 Physical damage to all nearby enemies.", ua = "Коли ти твориш «Колючий постріл», твій улюбленець тупає по землі, завдаючи $201754s1 фізичної шкоди всім ворогам поблизу." },
    { en = "While Bestial Wrath is active, Cobra Shot resets the cooldown on Kill Command.", ua = "Поки діє «Звірячий гнів», «Постріл кобри» скидає перезарядження «Наказу вбити»." },
    { en = "Your movement speed is increased by $s2% anytime you have not attacked for ${$s1/1000} sec.", ua = "Твоя швидкість руху збільшується на $s2% щоразу, коли ти не атакуєш протягом ${$s1/1000} сек." },
    { en = "Apply a Beacon of Light to your target and $s2 injured allies within $A2 yds for $d.\n\n\n\nAll affected allies will be healed for $53651s1% of the amount of your other healing done.", ua = "Накладає «Маяк світла» на вашу ціль і $s2 поранених союзників у радіусі $A2 м протягом $d.\n\n\n\nУсі вражені союзники зцілюються на $53651s1% від обсягу вашого іншого зціленого здоров'я." },
    { en = "Riptide's initial heal is increased $s1% and has a $s2% increased critical strike chance.", ua = "Початкове зцілення «Бистрини» збільшено на $s1%, а його шанс критичного удару — на $s2%." },
    { en = "Healing Wave and Chain Heal heal for an additional $s1% on targets affected by your Healing Rain or Riptide.", ua = "«Хвиля зцілення» та «Ланцюгове зцілення» зцілюють на $s1% сильніше цілі під дією твого «Цілющого дощу» чи «Стрімкої течії»." },
    { en = "$s1% of healing done by Flash Heal is replicated to the previous target you healed with those spells.", ua = "$s1% зцілення від «Швидкого зцілення» відтворюється на попередній зціленій тобою цілі." },
    { en = "$?s235587[Gain a charge][Reset the cooldown] of your Holy Words, and enter a pure Holy form for $d, increasing the cooldown reductions to your Holy Words by $s1% and reducing their cost by $s6%.", ua = "$?s235587[Отримайте заряд][Скиньте перезарядження] ваших Святих слів і перейдіть у форму чистого Світла на $d, збільшуючи зменшення перезарядження ваших Святих слів на $s1% і зменшуючи їхню вартість на $s6%." },
    { en = "Holy Word: Chastise stuns the target for $200200d and is not broken by damage.", ua = "«Слово святості: Кара» приголомшує ціль на $200200d, і ефект не зривається від шкоди." },
    { en = "When Guardian Spirit saves the target from death, it does not expire.\n\n\n\nWhen Guardian Spirit expires without saving the target from death, reduce its remaining cooldown to $s1 seconds.", ua = "Коли «Дух-охоронець» рятує ціль від смерті, його дія не завершується.\n\n\n\nКоли «Дух-охоронець» завершується, не врятувавши ціль від смерті, його залишкове перезарядження зменшується до $s1 секунд." },
    { en = "Swiftmend now has ${$m1+1} charges.", ua = "Швидке загоєння тепер має ${$m1+1} заряди." },
    { en = "When Rejuvenation heals a target below $s1% health, they are instantly healed for $200389s1.", ua = "Коли «Омолодження» зцілює ціль із рівнем здоров'я нижче за $s1%, вона миттєво зцілюється на $200389s1." },
    { en = "Aura Mastery also increases all healing received by party or raid members within $211210A1 yards by $s1%.", ua = "«Майстерність аур» також збільшує на $s1% все зцілення, яке отримують члени групи чи рейду в радіусі $211210A1 м." },
    { en = "Blind has $s1% reduced cooldown, $s2% reduced duration, and applies to all nearby enemies.", ua = "«Осліплення» має на $s1% менше перезарядження, на $s2% меншу тривалість і діє на всіх ворогів поблизу." },
    { en = "Punctures your target with your shadow-infused blade for $s1 Shadow damage, bypassing armor.$?s319949[ Critical strikes apply Find Weakness for $319949s1 sec.][]\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Проколює ціль твоїм просякнутим тінню клинком, завдаючи $s1 шкоди як Тінь і оминаючи броню.$?s319949[ Критичні удари накладають «Пошук слабкості» на $319949s1 сек.][]\n\n\n\n|cFFFFFFFFНадає $s2 $lочко комбо:очок комбо;.|r" },
    { en = "Mangle has a $h% chance to reduce the Rage cost of your next Ironfur by $s1%.", ua = "«Шматування» з імовірністю $h% зменшує вартість у люті твого наступного «Залізного хутра» на $s1%." },
    { en = "Melee auto-attacks with Flametongue Weapon active have a $h% chance to reduce the cooldown of Lava Lash by ${100*(1-(100/(100+$m2)))}% and increase the damage of Lava Lash by $s3% for $215785d.\n\n\n\nMay not occur during an active Hot Hand.", ua = "Автоатаки в ближньому бою, доки активний «Полум'яний язик», мають $h% шанс скоротити перезарядження «Лавового батога» на ${100*(1-(100/(100+$m2)))}% і збільшити шкоду «Лавового батога» на $s3% протягом $215785d.\n\n\n\nНе може спрацьовувати, доки активна «Гаряча рука»." },
    { en = "Tiger's Fury lasts ${$s1/1000} additional seconds.\n\n\n\nYour combo point-generating abilities' direct damage is increased by $449864s2% of your Haste.", ua = "Лють тигра триває на ${$s1/1000} секунд довше.\n\n\n\nПряма шкода ваших здібностей, що генерують комбо-очки, підвищується на $449864s2% вашого Поспіху." },
    { en = "Ferocious Bite deals $s1% increased damage.\n\n\n\nFor each Combo Point spent, Ferocious Bite's primary target takes $s2% increased damage from your Cat Form bleed and other periodic abilities for $391722d.", ua = "Лютий укус завдає на $s1% більше шкоди.\n\n\n\nЗа кожне витрачене Комбо-очко основна ціль Лютого укусу отримує на $s2% більше шкоди від вашої кровотечі у формі кота та інших періодичних здібностей на $391722d." },
    { en = "Your maximum health is increased by $s3% and every ${$s2/10} Rage you spend heals you for ${$s1/10}% of your maximum health.", ua = "Твоє максимальне здоров'я збільшено на $s3%, і кожні ${$s2/10} витраченої люті зцілюють тебе на ${$s1/10}% максимального здоров'я." },
    { en = "Place a Sigil of Silence at the target location that activates after $d.\n\n\n\nSilences all enemies affected by the sigil for $204490d.", ua = "Розміщує Знак тиші у цільовому місці, що активується через $d.\n\n\n\nЗмушує замовкнути всіх ворогів під дією знака на $204490d." },
    { en = "Place a Sigil of Chains at the target location that activates after $d.\n\n\n\nAll enemies affected by the sigil are pulled to its center and are snared, reducing movement speed by $204843s1% for $204843d.", ua = "Розміщує Знак ланцюгів у цільовому місці, що активується через $d.\n\n\n\nУсі вороги під дією знака притягуються до його центру й сковуються, що зменшує швидкість пересування на $204843s1% на $204843d." },
    { en = "Reduces the cooldown of Heroic Leap by ${$m1/-1000} sec and Heroic Leap also increases your movement speed by $202164s1% for $202164d.", ua = "Зменшує перезарядження «Героїчного стрибка» на ${$m1/-1000} сек., а сам «Героїчний стрибок» також збільшує твою швидкість руху на $202164s1% на $202164d." },
    { en = "Instantly attack the target, causing $s1 damage and healing you for $202166s1% of your maximum health.\n\n\n\nKilling an enemy that yields experience or honor resets the cooldown of Impending Victory and makes it cost no Rage.", ua = "Миттєво атакуєш ціль, завдаючи $s1 шкоди й зцілюючи тебе на $202166s1% максимального здоров'я.\n\n\n\nУбивство ворога, що дає досвід або честь, скидає перезарядження Близької перемоги й робить її безкоштовною щодо люті." },
    { en = "If Cleave or Whirlwind hits $s1 or more targets you also Slam your primary target. This Slam deals $s2% additional damage.", ua = "Якщо Розсікання або Вихор влучає у $s1 чи більше цілей, ти також застосовуєш Трощення до своєї основної цілі. Це Трощення завдає на $s2% більше шкоди." },
    { en = "Moonfire and Sunfire damage over time has a chance to call down a falling star, dealing $202497s1 Astral damage and generating ${$202497m2/10} Astral Power.", ua = "Періодична шкода «Місячного вогню» і «Сонячного вогню» має шанс прикликати падучу зорю, що завдає $202497s1 астральної шкоди та породжує ${$202497m2/10} од. астральної сили." },
    { en = "Starsurge and Starfall grant you $s1% Haste for $279709d or until you enter a new Eclipse.\n\n\n\nStacks up to $279709u times. Gaining a stack does not refresh the duration.", ua = "Зоряний сплеск і Зорепад надають вам $s1% Поспіху на $279709d або доки ви не ввійдете в нове Затемнення.\n\n\n\nНакопичується до $279709u разів. Отримання заряду не оновлює тривалість." },
    { en = "Reduces the cooldown of Life Cocoon by ${$m1/-1000} sec.", ua = "Зменшує перезарядження «Кокона життя» на ${$m1/-1000} сек." },
    { en = "While in combat you generate ${$s1/10} Astral Power every $t1 sec.\n\n\n\nWhile out of combat your Astral Power rebalances to $s2 instead of depleting to empty.", ua = "У бою ви накопичуєте ${$s1/10} астральної сили раз на $t1 сек.\n\n\n\nПоза боєм ваша астральна сила вирівнюється до $s2 замість того, щоб опускатися до нуля." },
    { en = "Your dodges and parries make your Revenge cost no Rage $s3% more frequently and increase the damage your free Revenges deal by $s1%. Revenge increases the damage of your next Thunder Clap by $1234772s1%.", ua = "Твої ухиляння й парирування на $s3% частіше роблять «Помсту» безкоштовною за люттю та збільшують шкоду безкоштовних «Помст» на $s1%. «Помста» збільшує шкоду твого наступного «Удару грому» на $1234772s1%." },
    { en = "You gain $202602s1% Haste for each enemy or ally within $s1 yards, up to ${$202602s1*$202602u}% Haste.", ua = "Ти отримуєш $202602s1% поспіху за кожного ворога чи союзника в радіусі $s1 м, аж до ${$202602s1*$202602u}% поспіху." },
    { en = "Demoralizing Shout also generates ${$m1/10} Rage and increases damage you deal to affected targets by $s2%.", ua = "Крик деморалізації також генерує ${$m1/10} люті та збільшує шкоду, яку ти завдаєш ураженим цілям, на $s2%." },
    { en = "$?a137010[$@spelldesc428655][Calls down a beam of pure celestial energy that follows the enemy, dealing up to $<dmg> Astral damage over $d within its area. Damage reduced on secondary targets.\n\n\n\n|cFFFFFFFFGenerates ${$m3/10/$t3*$d} Astral Power over its duration.|r]", ua = "$?a137010[$@spelldesc428655][Обрушує промінь чистої небесної енергії, що слідує за ворогом, завдаючи до $<dmg> астральної шкоди протягом $d у межах своєї зони. Шкода зменшена для вторинних цілей.\n\n\n\n|cFFFFFFFFГенерує ${$m3/10/$t3*$d} астральної сили за час дії.|r]" },
    { en = "Reduces the remaining cooldown on Solar Beam by $m1 sec when it interrupts the primary target.", ua = "Зменшує залишок перезарядження «Сонячного променя» на $m1 сек., коли той перериває основну ціль." },
    { en = "Shield Slam generates ${$s2/10} more Rage and extends the duration of Shield Block by ${$m1/100}.1 sec.", ua = "«Удар щитом» породжує на ${$s2/10} більше люті та подовжує дію «Блоку щитом» на ${$m1/100}.1 сек." },
    { en = "Thunder Clap's radius is increased by $s1% and it reduces affected target's movement speed by an additional $s2%.", ua = "Радіус «Удару грому» збільшено на $s1%, і він додатково знижує швидкість руху уражених цілей на $s2%." },
    { en = "Eye Beam generates ${$s3/5} Fury every second, has $s1% increased duration, and deals $s2% increased damage.", ua = "Промінь з очей породжує ${$s3/5} од. Люті щосекунди, триває на $s1% довше та завдає на $s2% більше шкоди." },
    { en = "Sharp brambles protect you, absorbing and reflecting up to $<shield> damage from each attack.\n\n\n\nWhile Barkskin is active, the brambles also deal $213709s1 Nature damage to all nearby enemies every $22812t3 sec.", ua = "Гострі тернини захищають вас, поглинаючи й відбиваючи до $<shield> шкоди від кожної атаки.\n\n\n\nПоки активна Кора, тернини також завдають $213709s1 шкоди від Природи всім ворогам поблизу кожні $22812t3 сек." },
    { en = "Thrash also generates ${$203961s1/10} Rage each time it deals damage, on up to $s1 targets.", ua = "Молотьба також генерує ${$203961s1/10} люті щоразу, як завдає шкоди, щонайбільше від $s1 цілей." },
    { en = "Your damage has a $s1% chance to trigger a free automatic Moonfire on that target.\n\n\n\n$@spellicon8921 $@spellname8921:\n\nWhen this occurs, the next Moonfire you cast generates ${$213708m1/10} Rage, and deals $213708s3% increased direct damage.\n\n\n\n$@spellicon1252871 $@spellname1252871:\n\nWhen this occurs, you gain $s2 $Lcharge:charges; of Lunar Wrath. Each $s3 Rage you spend while Red Moon is active consumes a stack to deal $1253609s1 additional Arcane damage to its target and heal you for $1253609s2.", ua = "Ваша шкода має $s1% шанс безкоштовно й автоматично викликати Місячний вогонь на цій цілі.\n\n\n\n$@spellicon8921 $@spellname8921:\n\nКоли це стається, ваш наступний Місячний вогонь дає ${$213708m1/10} люті та завдає на $213708s3% більше прямої шкоди.\n\n\n\n$@spellicon1252871 $@spellname1252871:\n\nКоли це стається, ви отримуєте $s2 $Lзаряд:заряди; Місячного гніву. Кожні $s3 люті, витрачені, поки активний Червоний місяць, споживають стак, щоб завдати $1253609s1 додаткової арканної шкоди цілі та зцілити вас на $1253609s2." },
    { en = "Reduces the cooldowns of Barkskin and Survival Instincts by $s1%.", ua = "Зменшує перезарядження «Кори» та «Інстинктів виживання» на $s1%." },
    { en = "Blesses a party or raid member, granting immunity to magical damage and harmful effects for $d.\n\n\n\nCannot be used on a target with Forbearance. Causes Forbearance for $25771d.\n\n\n\nShares a cooldown with Blessing of Protection.", ua = "Благословляє учасника групи чи рейду, даруючи несприйнятливість до магічної шкоди та шкідливих ефектів протягом $d.\n\n\n\nНе можна застосувати на ціль із «Поблажливістю». Спричиняє «Поблажливість» на $25771d.\n\n\n\nМає спільне перезарядження з «Благословенням захисту»." },
    { en = "Throws a Blessed Hammer that spirals outward, dealing $204301s1 Holy damage to enemies and reducing the next damage they deal to you by $<shield>.\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.", ua = "Кидає благословенний молот, що по спіралі розлітається назовні, завдаючи $204301s1 од. шкоди Світлом ворогам і зменшуючи наступну шкоду, яку вони вам завдадуть, на $<shield>.\n\n\n\n|cFFFFFFFFГенерує $s2 од. Святої сили." },
    { en = "Brand yourself and an enemy target with demonic symbols, reducing the damage you take by $S1% and instantly dealing $s2 Fire damage$?s320962[ and ${$207771s5*$207771d} Fire damage over $207771d][] to the enemy.", ua = "Таврує вас та ворожу ціль демонічними символами, зменшуючи шкоду, яку ви отримуєте, на $S1% і миттєво завдаючи ворогові $s2 шкоди вогнем$?s320962[ та ${$207771s5*$207771d} шкоди вогнем протягом $207771d][]." },
    { en = "Judgment now has ${1+$s1} charges, and Grand Crusader now also reduces the cooldown of Judgment by ${$s2/1000} sec.", ua = "«Осуд» тепер має ${1+$s1} заряди, а «Великий хрестоносець» тепер також скорочує перезарядження «Осуду» на ${$s2/1000} сек." },
    { en = "Each stack of Thrash reduces the target's damage to you by $s3% and increases your damage to them by $s1%.", ua = "Кожен заряд «Молотіння» зменшує шкоду цілі по тобі на $s3% і збільшує твою шкоду по ній на $s1%." },
    { en = "Your Consecration is $s1% larger, and enemies within it have $s2% reduced movement speed.", ua = "Твоє «Освячення» на $s1% більше, а швидкість руху ворогів у ньому зменшена на $s2%." },
    { en = "Summons a beam of lunar light at your target's location, dealing $1270292s1 Arcane damage each second to your target and $414613s1 to up to $s3 other enemies within the beam. \n\n\n\nLunar Beam also increases your mastery by ${$s2*$mas}%, and heals you for ${$204069s1*$s1} over $m1 sec.", ua = "Прикликає промінь місячного світла на місці розташування вашої цілі, завдаючи $1270292s1 арканної шкоди щосекунди вашій цілі та $414613s1 ще до $s3 інших ворогів у межах променя. \n\n\n\nМісячний промінь також підвищує вашу майстерність на ${$s2*$mas}% і зцілює вас на ${$204069s1*$s1} протягом $m1 сек." },
    { en = "Avenging Wrath and Sentinel have $s1% reduced cooldown and $s2% reduced duration.", ua = "Перезарядження «Гніву месника» та «Вартового» зменшено на $s1%, а їхню тривалість — на $s2%." },
    { en = "During Divine Shield, all targets within $s1 yds are taunted.", ua = "Під час дії «Божественного щита» провокуються всі цілі в радіусі $s1 м." },
    { en = "When your abilities damage a target below $s1% health, you gain $204090s1% increased critical strike chance for $204090d, stacking up to $204090u times.", ua = "Коли твої здібності завдають шкоди цілі, що має менш ніж $s1% здоров'я, твій шанс критичного удару збільшується на $204090s1% протягом $204090d. Ефект складається до $204090u разів." },
    { en = "Your Hex target is slowed by $378080s1% during Hex and for $378080d after it ends.\n\n\n\nReduces the cooldown of Hex by ${($m1/1000)*-1} sec.", ua = "Ціль вашого Вроку сповільнена на $378080s1% протягом дії Вроку та ще $378080d після його завершення.\n\n\n\nЗменшує перезарядження Вроку на ${($m1/1000)*-1} сек." },
    { en = "Leech increased by $s1%.\n\n\n\nGain an additional $s2% leech while Metamorphosis is active.", ua = "Висмоктування збільшене на $s1%.\n\n\n\nОтримуйте додаткові $s2% висмоктування, поки активна Метаморфоза." },
    { en = "Channel an icy beam at the enemy for $d, dealing $s1 Frost damage every ${$t1}.2 sec.\n\n\n\n|CFFffffffApplies ${$d/$t1} $lstack:stacks; of Freezing over its duration.|R", ua = "Спрямовує крижаний промінь на ворога протягом $d, завдаючи $s1 морозної шкоди кожні ${$t1}.2 сек.\n\n\n\n|CFFffffffНакладає ${$d/$t1} $lзаряд:заряди:зарядів; Заморожування протягом своєї дії.|R" },
    { en = "Casting Arcane Intellect summons a Familiar that attacks your enemies and increases your maximum mana by $210126s1% for $210126d.", ua = "Прочитання «Арканного інтелекту» прикликає фамільяра, який атакує твоїх ворогів і збільшує твій максимум мани на $210126s1% на $210126d." },
    { en = "Spell damage increased by $s1%.", ua = "Шкода від заклять збільшена на $s1%." },
    { en = "Causes your next $n Arcane $LBlast:Blasts; to be instant cast$?a134735[ and deal $s2% of normal damage][].", ua = "Робить ваші наступні $n Арканних $LУдара:Ударів; миттєвими в творінні$?a134735[ і такими, що завдають $s2% звичайної шкоди][]." },
    { en = "Your Fireball and Pyroblast spells always deal a critical strike when the target is above $s1% health.", ua = "Твої «Вогняна куля» та «Піровибух» завжди завдають критичного удару, якщо в цілі понад $s1% здоров'я." },
    { en = "Arcane Barrage deals $s1% increased damage per target it hits beyond the first.", ua = "«Арканний шквал» завдає на $s1% більше шкоди за кожну вражену ціль після першої." },
    { en = "Fire Blast gains $s1 additional charge and its cooldown is reduced by ${-$s2/1000}.1 sec.", ua = "«Вогняний вибух» отримує $s1 додатковий заряд, а його перезарядження скорочується на ${-$s2/1000}.1 сек." },
    { en = "Frostbolt grants you Fingers of Frost $s1% more often and Brain Freeze $s2% more often.", ua = "«Морозна стріла» дає тобі «Пальці морозу» на $s1% частіше, а «Замерзання мозку» — на $s2% частіше." },
    { en = "Frost Nova now has ${1+$m1} charges.", ua = "«Морозна нова» тепер має ${1+$m1} заряди." },
    { en = "Your spells have a chance to grant you $266030s1% Haste for $266030d.", ua = "Твої закляття мають шанс дати тобі $266030s1% поспіху на $266030d." },
    { en = "Summons a Darkglare from the Twisting Nether that increases the damage of your Agony, $?a445465[Wither][Corruption], and Unstable Affliction by $1280663s1% while active.\n\n\n\nThe Darkglare will serve you for $d, blasting its target for $205231s1 Shadow damage, increased by $s3% for every damage over time effect you have active on their current target.", ua = "Викликає темнозора з Круговерті Порожнечі, який, поки активний, підвищує шкоду ваших заклять Агонія, $?a445465[Згасання][Псування] та Нестабільна неміч на $1280663s1%.\n\n\n\nТемнозор служитиме вам $d, вражаючи ціль на $205231s1 шкоди Темрявою, що зростає на $s3% за кожен ваш активний ефект періодичної шкоди на її поточній цілі." },
    { en = "Controls a mind up to 1 level above yours for $d while still controlling your own mind. Does not work versus Demonic, Mechanical, or Undead beings$?a205477[][ or players]. This spell shares diminishing returns with other disorienting effects.", ua = "Підкоряє розум істоти до 1 рівня вище за ваш протягом $d, водночас залишаючи контроль над власним розумом. Не діє на демонічних, механічних чи неживих істот$?a205477[][ або гравців]. Це закляття має спільне послаблення дії з іншими ефектами дезорієнтації." },
    { en = "Blur now reduces damage taken by an additional ${$abs($m3)}%.\n\n\n\nAdditionally, damage taken below $s1% Health is reduced by $s2%.", ua = "Розмиття тепер зменшує отриману шкоду додатково на ${$abs($m3)}%.\n\n\n\nКрім того, шкода, отримана при здоров'ї нижче $s1%, зменшується на $s2%." },
    { en = "Summons a stand of $s1 Treants for $248280d which immediately taunt and attack enemies in the targeted area.\n\n\n\n|cFFFFFFFFGenerates ${$m5/10} Astral Power.|r", ua = "Прикликає гай із $s1 трентів на $248280d, які негайно провокують і атакують ворогів у вибраній зоні.\n\n\n\n|cFFFFFFFFГенерує ${$m5/10} Астральної сили.|r" },
    { en = "Reduces the cooldown on Vampiric Blood by ${$s1/1000}.1 sec per $s2 Runic Power spent.", ua = "Зменшує перезарядження «Вампірської крові» на ${$s1/1000}.1 сек. за кожні $s2 витраченої рунічної сили." },
    { en = "Reduces the cooldown of Anti-Magic Shell by ${$s1/-1000} sec and increases its duration and amount absorbed by $s2%.", ua = "Зменшує перезарядження «Антимагічної оболонки» на ${$s1/-1000} сек. та збільшує її тривалість і обсяг поглинання на $s2%." },
    { en = "$?a317320[Condemn][Execute] is usable on targets below $s2% health and its cooldown is reduced by ${$s3/1000}.1 sec.", ua = "$?a317320[Засудження][Страту] можна застосовувати до цілей зі здоров'ям нижче $s2%, а її перезарядження зменшено на ${$s3/1000}.1 сек." },
    { en = "Blade Dance deals $<firstbloodDmg> Chaos damage to the first target struck.", ua = "Танець клинків завдає $<firstbloodDmg> хаотичної шкоди першій враженій цілі." },
    { en = "The Hunt and Vengeful Retreat increase your damage by $208628s1% for $208628d.", ua = "«Полювання» та «Мстивий відступ» збільшують твою шкоду на $208628s1% на $208628d." },
    { en = "Instantly strike the target and 1 other nearby enemy, causing $s2 Physical damage, and reducing enemies' movement speed by $s5% for $d$?s316575[\n\n\n\n|cFFFFFFFFGenerates $s3 bonus Runic Power][]$?s221536[, plus ${$210738s1/10} Runic Power per additional enemy struck][].|r", ua = "Миттєво вражає ціль та 1 іншого ворога поблизу, завдаючи $s2 фізичної шкоди й знижуючи швидкість пересування ворогів на $s5% на $d$?s316575[\n\n\n\n|cFFFFFFFFСтворює $s3 додаткової Рунічної енергії][]$?s221536[, плюс ${$210738s1/10} Рунічної енергії за кожного додатково враженого ворога][].|r" },
    { en = "Damage taken below $s3% Health is reduced by $s2%.", ua = "Шкода, отримувана за здоров'я нижче $s3%, зменшена на $s2%." },
    { en = "Each charge of Bone Shield increases your maximum health by $<increase>%.", ua = "Кожен заряд Кістяного щита збільшує ваше максимальне здоров'я на $<increase>%." },
    { en = "When Frost Strike damages an enemy with $51714u stacks of Razorice it will consume them to deal an additional $s1% damage.\n\n\n\nFrostbane consumes the Razorice on your main target to deal an additional $s2% damage.", ua = "Коли Морозний удар завдає шкоди ворогу з $51714u зарядами Гострольоду, він поглинає їх, щоб завдати додатково $s1% шкоди.\n\n\n\nМорозна згуба поглинає Гострольод на вашій головній цілі, щоб завдати додатково $s2% шкоди." },
    { en = "Consuming the Killing Machine effect has a $s1% chance to grant you $207062s1 Rune.", ua = "Споживання ефекту «Машина вбивства» має $s1% шансу дати тобі $207062s1 руну." },
    { en = "Auto attacks have a chance to generate ${$221322s1/10} Runic Power.", ua = "Автоатаки мають шанс генерувати ${$221322s1/10} рунічної моці." },
    { en = "Casting Howling Blast with Rime active causes jagged icicles to fall on enemies nearby your target, applying Razorice and dealing $207150s1 Frost damage.", ua = "Творіння Виючого шквалу з активною Памороззю обрушує зазубрені бурульки на ворогів поблизу твоєї цілі, накладаючи Різучий лід і завдаючи $207150s1 шкоди від морозу." },
    { en = "Targets in a cone in front of you are blinded, causing them to wander disoriented for $d. Damage may cancel the effect.\n\n\n\nWhen Blinding Sleet ends, enemies are slowed by $317898s1% for $317898d.", ua = "Цілі в конусі перед вами засліплюються й розгублено блукають упродовж $d. Шкода може скасувати цей ефект.\n\n\n\nКоли Сліпуча сніговиця завершується, вороги сповільнюються на $317898s1% на $317898d." },
    { en = "Your auto attack damage grants you an absorb shield equal to $s1% of the damage dealt.", ua = "Шкода твоїх автоатак дає тобі поглинальний щит, рівний $s1% завданої шкоди." },
    { en = "A sweeping attack that strikes all enemies in front of you for $s2 Frost damage. Deals reduced damage beyond $s5 targets. \n\n\n\nConsumes Killing Machine to have its critical strikes deal $s3 times the normal damage.", ua = "Розмашиста атака, що б'є всіх ворогів перед вами на $s2 шкоди морозом. Завдає зменшеної шкоди понад $s5 цілей. \n\n\n\nСпоживає Машину вбивства, завдяки чому її критичні удари завдають у $s3 рази більше звичайної шкоди." },
    { en = "Plagues deal $s3% more damage over time in ${100+$s1}% of their duration.", ua = "Пошесті завдають на $s3% більше періодичної шкоди протягом ${100+$s1}% своєї тривалості." },
    { en = "The infected claws of your ghouls have a chance to sicken the foe, dealing $1241786o Shadow damage over $1241786d. When reapplied, any remaining damage is added to the new effect.", ua = "Заражені пазурі твоїх гулів мають шанс заразити ворога хворобою, що завдає $1241786o шкоди від тіні протягом $1241786d. При повторному накладанні решта шкоди додається до нового ефекту." },
    { en = "$?c3[Soul Immolation grants ${$s2*$1241937d} additional Fury over its duration.][Increases the critical strike chance of Immolation Aura by $s1%.]", ua = "$?c3[Спалення душі надає ${$s2*$1241937d} додаткової люті протягом своєї тривалості.][Збільшує шанс критичного удару Аури спалення на $s1%.]" },
    { en = "For each Rejuvenation you have active, Regrowth's cost is reduced by $207640s1% and critical effect chance is increased by $207640s2%, up to a maximum of ${$207640s2*$207640u}%.", ua = "За кожне твоє активне «Омолодження» вартість «Відростання» знижується на $207640s1%, а шанс критичного ефекту зростає на $207640s2%, аж до максимуму в ${$207640s2*$207640u}%." },
    { en = "Consuming a Soul Fragment reduces all damage you take by $s1% for $212988d.", ua = "Поглинання фрагмента душі зменшує всю отримувану шкоду на $s1% на $212988d." },
    { en = "Targets you heal with Healing Wave, Chain Heal, or Riptide's initial heal gain $s2% increased health for $207400d.", ua = "Цілі, яких ти зцілюєш «Хвилею зцілення», «Ланцюговим зціленням» або початковим зціленням «Бистрини», отримують на $s2% більше здоров'я на $207400d." },
    { en = "Immolation Aura increases your movement speed by $s1% and its duration is increased by $s2%.", ua = "«Аура спалення» збільшує твою швидкість руху на $s1%, а її тривалість збільшена на $s2%." },
    { en = "Place a Sigil of Misery at the target location that activates after $d.\n\n\n\nCauses all enemies affected by the sigil to cower in fear, disorienting them for $207685d.", ua = "Розміщує Знак нещастя у цільовому місці, що активується через $d.\n\n\n\nЗмушує всіх ворогів під дією знака зіщулитися від страху, дезорієнтуючи їх на $207685d." },
    { en = "Soul Cleave heals for an additional $207693s1.", ua = "«Розсічення душ» додатково зцілює на $207693s1." },
    { en = "Every $207771t3 sec, Fiery Brand spreads to one nearby enemy.", ua = "Кожні $207771t3 сек. Вогняне тавро перекидається на одного ворога поблизу." },
    { en = "You take $s1% reduced damage while Enrage is active.", ua = "Поки діє «Розлюченість», ти отримуєш на $s1% менше шкоди." },
    { en = "Sustaining fatal damage instead transforms you to Metamorphosis form.\n\n\n\nThis may occur once every $209261d.", ua = "Отримавши смертельну шкоду, ви натомість перетворюєтеся на форму Метаморфози.\n\n\n\nЦе може статися раз на $209261d." },
    { en = "Your Sigils activate ${$s1/-1000} second faster.", ua = "Твої знаки активуються на ${$s1/-1000} сек. швидше." },
    { en = "Avenger's Shield also shields you for $209388d, absorbing $s1% as much damage as it dealt, up to $s2% of your maximum health.", ua = "«Щит месника» також оточує тебе щитом на $209388d, поглинаючи шкоду в обсязі $s1% завданої ним шкоди, але не більше за $s2% твого максимального здоров'я." },
    { en = "Reduces the cooldown of Invisibility by ${-$s1/1000} sec.", ua = "Скорочує перезарядження Невидимості на ${-$s1/1000} сек." },
    { en = "$?s454009[Tempest, ][]$?s137040[Earth Shock, Elemental Blast, and Earthquake][Lightning Bolt and Chain Lightning] make your target a Lightning Rod for $197209d.\n\n \n\nLightning Rods take $s2% of all damage you deal with $?s454009[Tempest, Lightning Bolt,][Lightning Bolt] and Chain Lightning.", ua = "$?s454009[Буря, ][]$?s137040[Земляний шок, Стихійний вибух і Землетрус][Блискавка і Ланцюгова блискавка] роблять вашу ціль Громовідводом на $197209d.\n\n \n\nГромовідводи отримують $s2% усієї шкоди, яку ви завдаєте $?s454009[Бурею, Блискавкою][Блискавкою] та Ланцюговою блискавкою." },
    { en = "Thrash, Swipe, Moonfire, and Maul have a $s1% chance to reset the cooldown on Mangle, and to cause it to generate an additional ${$93622m1/10} Rage.", ua = "«Шмагання», «Помах», «Місячний вогонь» та «Терзання» мають $s1% шансу скинути перезарядження «Калічення» і змусити його створити додатково ${$93622m1/10} люті." },
    { en = "Stormstrike damage is increased by $s1%, and Stormstrike and Lava Lash have a $m3% chance to generate $m2 $Lstack:stacks; of Maelstrom Weapon.", ua = "Шкода від «Удару бурі» збільшена на $s1%, а «Удар бурі» та «Батіг лави» мають $m3% шансу створити $m2 $Lзаряд:заряди; «Зброї виру»." },
    { en = "Unleash the fel within you, damaging enemies directly in front of you for ${$212105s1*(2/$t1)} Fire damage over $d.$?s320639[ Causing damage also heals you for up to ${$212106s1*(2/$t1)} health.][]", ua = "Вивільняє Скверну всередині вас, завдаючи ворогам прямо перед вами ${$212105s1*(2/$t1)} шкоди вогнем протягом $d.$?s320639[ Завдання шкоди також зцілює вас до ${$212106s1*(2/$t1)} здоров'я.][]" },
    { en = "Fires an explosive shot at your target. After $t1 sec, the shot will explode, dealing $212680s1 Fire damage to all enemies within $212680A1 yds. Deals reduced damage beyond $s2 targets.", ua = "Вистрілюєш вибуховим зарядом у ціль. Через $t1 сек. заряд вибухає, завдаючи $212680s1 шкоди від вогню всім ворогам у радіусі $212680A1 м. Якщо цілей більше за $s2, шкода зменшується." },
    { en = "Embrace the power of the Shadowlands, removing all root effects and increasing your movement speed by $s1% for $d. Taking any action cancels the effect.\n\n\n\nWhile active, your movement speed cannot be reduced below $m2%.", ua = "Прийміть силу Тіньових земель, знімаючи всі ефекти знерухомлення та збільшуючи вашу швидкість пересування на $s1% протягом $d. Будь-яка дія скасовує ефект.\n\n\n\nПоки ефект активний, вашу швидкість пересування не можна знизити нижче $m2%." },
    { en = "Teleports you $A1 yds forward, unless something is in the way. Unaffected by the global cooldown and castable while casting.$?a382289[\n\n\n\nGain a shield that absorbs $382289s1% of your maximum health for $382290d after you Shimmer.][]", ua = "Телепортує вас на $A1 м уперед, якщо ніщо не заважає. Не підпадає під глобальне перезарядження й може застосовуватися під час прочитання заклять.$?a382289[\n\n\n\nПісля «Мерехтіння» ви отримуєте щит, що поглинає $382289s1% вашого максимального здоров'я протягом $382290d.][]" },
    { en = "You heal for $s1% of all Fire damage you deal.", ua = "Ти зцілюєшся на $s1% усієї завданої тобою шкоди вогнем." },
    { en = "Eye Beam causes you to enter demon form for ${$s1/1000} sec after it finishes dealing damage.", ua = "Промінь з очей переводить тебе в демонічну подобу на ${$s1/1000} сек. після завершення завдавання шкоди." },
    { en = "Removes all Disease effects from a friendly target.", ua = "Знімає всі ефекти хвороб із дружньої цілі." },
    { en = "Cleanses a friendly target, removing all Poison and Disease effects.", ua = "Очищає дружню ціль, знімаючи всі ефекти отрут і хвороб." },
    { en = "Swipe nearby enemies, inflicting Physical damage. Damage varies by shapeshift form.$?s137011[\n\n\n\n|cFFFFFFFFAwards $s1 combo $lpoint:points;.|r][]", ua = "Б'є ворогів поруч, завдаючи фізичної шкоди. Розмір шкоди залежить від обраної подоби.$?s137011[\n\n\n\n|cFFFFFFFFДає $s1 $lочко комбо:очка комбо;.|r][]" },
    { en = "Bloodthirst always Enrages you the first time you strike a target and it has a $s1% increased chance to trigger Enrage.", ua = "«Жага крові» завжди розлючує тебе при першому ударі по цілі та має на $s1% більший шанс викликати «Лютування»." },
    { en = "The damage of Smite and Penance is increased by $m1%, and Penance increases or decreases your target's movement speed by $s2% for $355851d.", ua = "Шкода «Кари» та «Покаяння» збільшена на $m1%, а «Покаяння» збільшує або зменшує швидкість руху твоєї цілі на $s2% на $355851d." },
    { en = "Fire a shot that tears through your enemy, causing them to bleed for ${$s1*$s2} damage over $d. If Barbed Shot is reapplied, any remaining damage will be added to the new Barbed Shot.\n\n\n\n|cFFFFFFFFGenerates ${$246152s1*$246152d/$246152t1} Focus over $246152d.|r", ua = "Стріляєте пострілом, що пронизує вашого ворога, змушуючи його стікати кров'ю на ${$s1*$s2} шкоди протягом $d. Якщо Зазублений постріл застосовано повторно, будь-яка залишкова шкода додається до нового Зазубленого пострілу.\n\n\n\n|cFFFFFFFFГенерує ${$246152s1*$246152d/$246152t1} зосередженості протягом $246152d.|r" },
    { en = "Imprisons a demon, beast, or humanoid, incapacitating them for $d. Damage may cancel the effect. Limit 1.", ua = "Ув'язнює демона, звіра чи гуманоїда, позбавляючи його змоги діяти на $d. Шкода може перервати ефект. Максимум 1 ціль." },
    { en = "Removes all Poison and Disease effects from the target.", ua = "Знімає з цілі всі ефекти отрути та хвороби." },
    { en = "Every $s1 Fury spent reduces the remaining cooldown of Demon Spikes by ${$s2/1000}.2 sec.", ua = "Кожні витрачені $s1 од. Люті скорочують залишок перезарядження Демонічних шипів на ${$s2/1000}.2 сек." },
    { en = "Your Soul Leech absorption now passively recharges at a rate of ${$s1/10}.1% of maximum health every $t1 sec, and may now absorb an additional $s2% of maximum health.\n\n\n\nIncreases your armor by $m4%.", ua = "Поглинання твого Висмоктування душі тепер пасивно відновлюється зі швидкістю ${$s1/10}.1% максимального здоров'я кожні $t1 сек. і може поглинути додатково $s2% максимального здоров'я.\n\n\n\nЗбільшує твою броню на $m4%." },
    { en = "While you have at least $s1 Bone Shield charges, the cost of Death Strike is reduced by ${$219788m1/-10} Runic Power.\n\n\n\nAdditionally, your maximum Runic Power is increased by ${$m2/10}.", ua = "Поки у вас є щонайменше $s1 зарядів Кістяного щита, вартість Удару смерті зменшується на ${$219788m1/-10} Рунічної сили.\n\n\n\nКрім того, ваша максимальна Рунічна сила збільшується на ${$m2/10}." },
    { en = "Your Heart Strike generates ${$210738s1/10} additional Runic Power per target hit.", ua = "Твій «Удар у серце» генерує додатково ${$210738s1/10} рунної сили за кожну вражену ціль." },
    { en = "Lifts the enemy target off the ground, crushing their throat with dark energy and stunning them for $d.", ua = "Підіймає ворожу ціль у повітря, стискаючи їй горло темною енергією та приголомшуючи на $d." },
    { en = "Holy Power spending abilities have a $s1% chance to make your next Holy Power spending ability free and deal $223819s2% increased damage and healing.", ua = "Здібності, що витрачають святу силу, мають $s1% шансу зробити твою наступну таку здібність безкоштовною та збільшити її шкоду й зцілення на $223819s2%." },
    { en = "Immolation Aura's initial burst has a chance to shatter Soul Fragments from enemies.", ua = "Початковий вибух «Аури спалення» має шанс вибити фрагменти душ із ворогів." },
    { en = "Become an unstoppable storm of destructive force, striking all nearby enemies for $<dmg> Physical damage over $d. Deals reduced damage beyond $s1 targets.\n\n\n\nYou are immune to movement impairing and loss of control effects, but can use defensive abilities and can avoid attacks.\n\n$?c2[\n\n|cFFFFFFFFGenerates ${$50622s3/10} Rage on each strike.|r][]", ua = "Перетворюєтеся на нестримну бурю руйнівної сили, вражаючи всіх ворогів поблизу на $<dmg> фізичної шкоди протягом $d. Завдає зменшеної шкоди понад $s1 цілей.\n\n\n\nВи несприйнятливі до ефектів, що сповільнюють рух і позбавляють контролю, але можете використовувати захисні здібності й уникати атак.\n\n$?c2[\n\n|cFFFFFFFFСтворює ${$50622s3/10} люті за кожен удар.|r][]" },
    { en = "Bombards your target with a Void Volley and twists your Shadowform with void magic, increasing your spell damage by $194249s1% for $194249d. \n\n\n\nThis spell is replaced with Void Volley while Voidform is active.\n\n\n\n$@spellicon1242173 $@spellname1242173\n\n$@spelldesc1242173", ua = "Обстрілює вашу ціль Залпом Порожнечі й викривлює вашу Форму тіні магією Порожнечі, збільшуючи шкоду ваших заклять на $194249s1% на $194249d. \n\n\n\nПоки активна Форма Порожнечі, це закляття замінюється Залпом Порожнечі.\n\n\n\n$@spellicon1242173 $@spellname1242173\n\n$@spelldesc1242173" },
    { en = "Throws a whirling weapon at your target that chases nearby enemies, inflicting $<damage> Physical damage to all enemies over $d. Deals reduced damage beyond $156287s2 targets.\n\n\n\n$?c1[Cleave and Whirlwind deal $s4% increased damage while Ravager is active]?c3[Revenge and Thunder Clap deal $s5% increased damage while Ravager is active.\n\n\n\n|cFFFFFFFFGenerates ${$334934s1/10} Rage each time it deals damage.|r][]", ua = "Кидає в ціль вихрову зброю, що переслідує ближніх ворогів, завдаючи $<damage> фізичної шкоди всім ворогам протягом $d. Завдає зменшеної шкоди понад $156287s2 цілей.\n\n\n\n$?c1[Розсічення та Вихор завдають на $s4% більше шкоди, поки активний Спустошувач]?c3[Помста та Громовий удар завдають на $s5% більше шкоди, поки активний Спустошувач.\n\n\n\n|cFFFFFFFFГенерує ${$334934s1/10} люті щоразу, коли завдає шкоди.|r][]" },
    { en = "Divine Steed now has ${1+$m1} charges.", ua = "«Божественний скакун» тепер має ${1+$m1} заряди." },
    { en = "Regrowth's initial heal has a $s1% increased chance for a critical effect if the target is already affected by Regrowth.", ua = "Початкове зцілення «Відростання» має на $s1% більший шанс критичного ефекту, якщо ціль уже під дією «Відростання»." },
    { en = "Rejuvenation's duration is increased by ${$s1/1000} sec.\n\n\n\nRegrowth's duration is increased by ${$s2/1000} sec when cast on yourself.", ua = "Тривалість Омолодження збільшується на ${$s1/1000} сек.\n\n\n\nТривалість Відростання збільшується на ${$s2/1000} сек, коли ви застосовуєте його на себе." },
    { en = "Shred deals $s2% increased damage and $?s202028[Brutal Slash][Swipe] deals $s1% increased damage against bleeding targets.", ua = "Проти цілей, що стікають кров'ю, «Шматування» завдає на $s2% більше шкоди, а $?s202028[«Жорстокий розтин»][«Помах лапи»] — на $s1% більше." },
    { en = "Reduce the cooldown of Bestial Wrath by ${$m1/-1000} sec.", ua = "Зменшує перезарядження Звірячого гніву на ${$m1/-1000} сек." },
    { en = "For each Arcane Charge, Arcane Barrage hits $s1 additional nearby $Ltarget:targets; for $s2% damage.", ua = "За кожен арканний заряд Арканний шквал уражає $s1 додаткову ціль поблизу:додаткові цілі поблизу; із $s2% шкоди." },
    { en = "Judgment deems the target unworthy, preventing the next $<shield> damage dealt by the target.", ua = "«Вирок» визнає ціль негідною та відвертає наступні $<shield> од. шкоди, які вона завдасть." },
    { en = "Judgment causes the target to take $s1% increased damage from your next Holy Power ability.\n\n\n\nMultiple applications may overlap.", ua = "«Осуд» змушує ціль отримувати на $s1% більше шкоди від вашої наступної здібності, що витрачає Священну силу.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Smite prevents the next $<shield> damage dealt by the enemy.", ua = "Кара запобігає наступним $<shield> шкоди, завданої ворогом." },
    { en = "Physical damage taken reduced by $s1%.", ua = "Отримана фізична шкода зменшена на $s1%." },
    { en = "Conflagrate gains an additional charge.", ua = "«Займання» отримує додатковий заряд." },
    { en = "Charge to your target and deal $213243sw2 $@spelldesc395020 damage.\n\n\n\n$?s263642[|cFFFFFFFFGenerates $213243s3 Fury.|r]?s203513[|cFFFFFFFFGenerates $213243s3 Fury.|r]?a203555[|cFFFFFFFFGenerates $213243s3 Fury.|r][|cFFFFFFFFGenerates $213243s3 Fury.|r]", ua = "Кидаєтеся до цілі й завдаєте $213243sw2 $@spelldesc395020 шкоди.\n\n\n\n$?s263642[|cFFFFFFFFГенерує $213243s3 люті.|r]?s203513[|cFFFFFFFFГенерує $213243s3 люті.|r]?a203555[|cFFFFFFFFГенерує $213243s3 люті.|r][|cFFFFFFFFГенерує $213243s3 люті.|r]" },
    { en = "Hammer of Justice's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Молота правосуддя» скорочено на ${$s1/-1000} сек." },
    { en = "Agony, $?a445465[Wither][Corruption], Unstable Affliction, Seed of Corruption, and $?s198590[Drain Soul][Shadow Bolt] deal up to $s1% increased damage on targets below $m2% health. Damage increase is higher against lower health targets.", ua = "Агонія, $?a445465[Всихання][Псування], Нестабільне страждання, Сім'я псування та $?s198590[Висмоктування душі][Тіньова стріла] завдають до $s1% більше шкоди цілям зі здоров'ям нижче $m2%. Приріст шкоди вищий проти цілей із меншим здоров'ям." },
    { en = "Resets the cooldown of your Ice Barrier, Frost Nova, $?a417493[][Cone of Cold, ]Ice Cold, and Ice Block.", ua = "Скидає перезарядження ваших Крижаної бар'єру, Морозної нови, $?a417493[][Конуса холоду, ]Крижаного холоду та Крижаного блоку." },
    { en = "Shields you in flame, absorbing $<shield> damage$?s194315[ and reducing Physical damage taken by $s3%][] for $d.\n\n\n\nMelee attacks against you cause the attacker to take $235314s1 Fire damage.", ua = "Захищає вас полум'ям, поглинаючи $<shield> шкоди$?s194315[ і зменшуючи отримувану фізичну шкоду на $s3%][] протягом $d.\n\n\n\nАтаки ближнього бою проти вас завдають нападнику $235314s1 вогняної шкоди." },
    { en = "Shields you with an arcane force, absorbing $<shield> damage and reducing magic damage taken by $s3% for $d.\n\n\n\nThe duration of harmful Magic effects against you is reduced by $s4%.", ua = "Захищає вас арканною силою, поглинаючи $<shield> шкоди й зменшуючи отриману магічну шкоду на $s3% на $d.\n\n\n\nТривалість шкідливих магічних ефектів проти вас зменшена на $s4%." },
    { en = "Critical strikes with Between the Eyes deal ${$s1/100+2}.1 times normal damage.", ua = "Критичні удари «Межи очі» завдають шкоду, у ${$s1/100+2}.1 раза більшу за звичайну." },
    { en = "Holy Word: Serenity$?a?a1246517[ gains][ and Holy Word: Sanctify gain] an additional charge.", ua = "«Святе слово: Безтурботність»$?a?a1246517[ отримує][ та «Святе слово: Освячення» отримують] додатковий заряд." },
    { en = "Omen of Clarity now triggers $s2% more often, can accumulate up to ${$s135700u+$s1} charges, and increases the damage of your next Shred or $?s202028[Brutal Slash][Swipe] by $s4%.", ua = "«Знамення ясності» тепер спрацьовує на $s2% частіше, може накопичувати до ${$s135700u+$s1} зарядів і збільшує шкоду твого наступного «Роздирання» або $?s202028[«Жорстокого розтину»][«Помаху»] на $s4%." },
    { en = "Your auto-attacks deal an additional $236282s1 Physical damage and have a $s2% chance to reset the remaining cooldown on Shield Slam.", ua = "Твої автоатаки завдають додатково $236282s1 фізичної шкоди й мають $s2% шансу скинути перезарядження «Удару щитом»." },
    { en = "Arcane Missiles and Evocation can now be channeled while moving.", ua = "«Арканні снаряди» та «Евокацію» тепер можна спрямовувати під час руху." },
    { en = "Arcane Missiles fires $s2 additional $lmissile:missiles;.", ua = "Арканні ракети випускають $s2 додаткову $lракету:ракети;." },
    { en = "Moonfire reduces damage dealt to you by ${$s1/1}%.", ua = "«Місячний вогонь» зменшує завдану тобі шкоду на ${$s1/1}%." },
    { en = "Atonement reduces damage taken by $s1%.", ua = "«Спокута» зменшує отримувану шкоду на $s1%." },
    { en = "Reduces the cooldown of Desperate Prayer by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Відчайдушної молитви» на ${$s1/-1000} сек." },
    { en = "Power Word: Shield absorbs $s1% additional damage and lasts ${$s2/1000} sec longer.", ua = "«Слово сили: Щит» поглинає на $s1% більше шкоди і триває на ${$s2/1000} сек. довше." },
    { en = "When Holy Word: Serenity $?a1246517[finishes its][or Holy Word: Sanctify finish their] cooldown, you emit a burst of light that heals up to $s1 injured targets within $243241A1 yards for $243241s1.", ua = "Коли $?a1246517[Святе слово: Безтурботність завершує своє][Святе слово: Безтурботність або Святе слово: Освячення завершують своє] перезарядження, ви випромінюєте спалах світла, що зцілює до $s1 поранених цілей у межах $243241A1 ярдів на $243241s1." },
    { en = "Vampiric Touch also applies Shadow Word: Pain to the target. Shadow Word: Pain lasts an additional ${$s2/1000} sec.", ua = "«Вампірський дотик» також накладає на ціль «Слово тіні: Біль». «Слово тіні: Біль» триває додатково ${$s2/1000} сек." },
    { en = "Shadow Dance increases all ability damage by $s2%, and Shadowstrike and Shuriken Storm damage by an additional $s1%.", ua = "«Танець тіней» збільшує шкоду всіх здібностей на $s2%, а шкоду «Удару тіні» та «Бурі сюрикенів» — ще на $s1%." },
    { en = "Consume up to $s2 Soul Fragments then explode, dealing $247455s1 Fire damage to nearby enemies, increased by $s1% per fragment consumed. Deals reduced damage beyond $s3 targets.", ua = "Поглинає до $s2 фрагментів душі, а тоді вибухає, завдаючи $247455s1 вогняної шкоди ворогам поблизу — на $s1% більше за кожен поглинутий фрагмент. Якщо цілей більше за $s3, шкода зменшується." },
    { en = "Shift into Cat Form and increase your movement speed by $s1%, reducing gradually over $d.", ua = "Перекидаєшся в подобу кота та збільшуєш швидкість руху на $s1% з поступовим спаданням протягом $d." },
    { en = "Gain Inexorable Assault every $t1 sec, stacking up to $253595u times.\n\n\n\n$?s207230[Obliterate and Frostscythe consume][Obliterate consumes] up to $s1 stacks, dealing an additional $253597s1 Frost damage for each stack consumed.", ua = "Кожні $t1 сек. ви отримуєте Невблаганний штурм, що накопичується до $253595u разів.\n\n\n\n$?s207230[Винищення та Морозна коса споживають][Винищення споживає] до $s1 стаків, завдаючи додатково $253597s1 морозної шкоди за кожен спожитий стак." },
    { en = "Envenom has a $<chance>% chance per combo point spent to smash a vial of poison at the target's location, creating a pool of acidic death that deals ${$255546s1*$s2} Nature damage over $255545d to all enemies within it.", ua = "Отруєння має $<chance>% шанс за кожне витрачене очко комбо розбити флакон отрути в місці цілі, утворюючи калюжу кислотної смерті, яка завдає ${$255546s1*$s2} шкоди природою впродовж $255545d усім ворогам у ній." },
    { en = "Lash out at your enemies, dealing $s1 Radiant damage to all enemies within $a1 yds in front of you, and applying $@spellname403695, burning the targets for an additional ${$403695s2*($403695d/$403695t+1)} damage over $403695d.\n\n\n\nDemon and Undead enemies are also stunned for $255941d.\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.", ua = "Завдає нищівного удару ворогам, завдаючи $s1 шкоди Сяйва всім ворогам у межах $a1 м перед вами і накладаючи $@spellname403695, спалюючи цілі та завдаючи ще ${$403695s2*($403695d/$403695t+1)} шкоди протягом $403695d.\n\n\n\nДемони та нежить також приголомшуються на $255941d.\n\n\n\n|cFFFFFFFFГенерує $s2 Святої Сили." },
    { en = "Reduces the cooldown of Blind by $s1% and increases its range by $s2 yds.", ua = "Зменшує перезарядження «Осліплення» на $s1% і збільшує його дальність на $s2 м." },
    { en = "Activating Adrenaline Rush improves the result of your next Roll the Bones by one level.", ua = "Активація Припливу адреналіну покращує результат твого наступного Кидка кісток на один рівень." },
    { en = "Reduces the cooldown of Grappling Hook by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Гака-кішки» на ${$s1/-1000} сек." },
    { en = "Shoot a stream of $s1 shots at your target over $d, dealing a total of ${$m1*$257045sw1} Physical damage. Usable while moving.\n\n\n\n|cFFFFFFFFEach shot generates $263585s1 Focus.|r", ua = "Випускає потік із $s1 пострілів у вашу ціль протягом $d, завдаючи загалом ${$m1*$257045sw1} фізичної шкоди. Можна застосовувати в русі.\n\n\n\n|cFFFFFFFFКожен постріл генерує $263585s1 зосередженості.|r" },
    { en = "After using Vanish or Shadow Dance, your next Cheap Shot is free and ignores its cooldown.", ua = "Після використання Зникнення або Танцю тіней твій наступний Підлий удар безкоштовний і нехтує перезарядженням." },
    { en = "When Multi-Shot hits $s2 or more targets, your next Aimed Shot or Rapid Fire will ricochet and hit up to $s1 additional targets for $s4% of normal damage.", ua = "Коли «Мультипостріл» влучає в $s2 чи більше цілей, твій наступний «Прицільний постріл» або «Швидкий вогонь» рикошетить і вражає до $s1 додаткових цілей, завдаючи їм $s4% звичайної шкоди." },
    { en = "Slash all enemies in front of you for $s1 Chaos damage, causing Chaos Strike and Blade Dance to deal $1245759s1 Chaos damage to them for $320338d. Deals reduced damage beyond $s2 targets.", ua = "Розтинає всіх ворогів перед тобою, завдаючи $s1 шкоди хаосу, після чого «Удар хаосу» та «Танець клинків» завдають їм $1245759s1 шкоди хаосу протягом $320338d. Шкода зменшена, якщо цілей більше ніж $s2." },
    { en = "The final slash of Blade Dance inflicts an additional $258883o1 Chaos damage over $258883d.", ua = "Останній помах «Танцю клинків» завдає додатково $258883o1 шкоди хаосу протягом $258883d." },
    { en = "Activating Eye Beam reduces the cooldown of your next Eye Beam by ${$s1/1000}.1 sec, stacking up to $s2 sec.", ua = "Активація «Променя ока» зменшує перезарядження твого наступного «Променя ока» на ${$s1/1000}.1 сек. Складається до $s2 сек." },
    { en = "Give the command to kill, causing your pet to savagely deal $259277s1 Physical damage to the enemy.$?a260285[\n\n\n\nIncreases the damage of your next non-Kill Command ability by $260286s1%.][]\n\n\n\n|cFFFFFFFFGenerates $s2 Focus.|r", ua = "Віддає наказ убити, через що ваш улюбленець люто завдає ворогові $259277s1 од. фізичної шкоди.$?a260285[\n\n\n\nЗбільшує шкоду наступної вашої здібності, окрім Наказу убити, на $260286s1%.][]\n\n\n\n|cFFFFFFFFГенерує $s2 од. зосередження.|r" },
    { en = "Hurl a bomb at the target, exploding for $265157s1 Fire damage in a cone and coating enemies in wildfire, scorching them for $269747o1 Fire damage over $269747d. Deals reduced damage beyond $s2 targets.\n\n\n\nDeals $s3% increased damage to your primary target.", ua = "Жбурляє бомбу в ціль, що вибухає на $265157s1 вогняної шкоди в конусі та вкриває ворогів диким вогнем, обпікаючи їх на $269747o1 вогняної шкоди протягом $269747d. Завдає зменшеної шкоди понад $s2 цілей.\n\n\n\nЗавдає на $s3% більше шкоди вашій основній цілі." },
    { en = "Aimed Shot causes your next Arcane Shot or Multi-Shot to deal $260242s1% more damage and cost $260242s3% less Focus.\n\n\n\nPrecise Shots benefits $?a466932[Black Arrow][Kill Shot]'s damage at $s2% effectiveness.", ua = "Прицільний постріл змушує твій наступний Арканний постріл або Множинний постріл завдавати на $260242s1% більше шкоди й коштувати на $260242s3% менше зосередженості.\n\n\n\nТочні постріли підсилюють шкоду $?a466932[Чорної стріли][Добивального пострілу] з $s2% ефективності." },
    { en = "Rain a volley of arrows down over $d, dealing up to ${$260247s1*12} Physical damage to any enemy in the area, and gain the effects of Trick Shots for as long as Volley is active.", ua = "Обрушує град стріл протягом $d, завдаючи до ${$260247s1*12} фізичної шкоди всім ворогам у зоні, і дає тобі ефекти Трюкових пострілів, поки діє Град стріл." },
    { en = "You and your pet gain $260249s1% attack speed for every bleeding enemy within $s2 yds.", ua = "Ти і твій улюбленець отримуєте $260249s1% швидкості атаки за кожного ворога з кровотечею в радіусі $s2 м." },
    { en = "Kill Command increases the direct damage of your other abilities by $s1%, stacking up to $260286u times.", ua = "Наказ убити збільшує пряму шкоду твоїх інших здібностей на $s1%, складається до $260286u разів." },
    { en = "Your ranged ability critical strikes cause the target to bleed for an additional $s1% of the damage dealt over $269576d.", ua = "Критичні удари твоїх здібностей дальнього бою спричиняють у цілі кровотечу, що завдає додатково $s1% від завданої шкоди протягом $269576d." },
    { en = "Trueshot's cooldown is reduced by ${$s1/1000*-1} sec.", ua = "Перезарядження «Влучного пострілу» скорочено на ${$s1/1000*-1} сек." },
    { en = "While transformed into a Ghost Wolf, you gain $260881s1% increased movement speed and $260881s2% damage reduction every $260882t1 sec, stacking up to $260881u times.", ua = "У подобі примарного вовка ти кожні $260882t1 сек. отримуєш $260881s1% до швидкості руху та $260881s2% зменшення отриманої шкоди; ефект складається до $260881u разів." },
    { en = "Blackout Kick reduces the cooldown of Rising Sun Kick and Fists of Fury by ${$100784m3/1000}.1 sec.", ua = "«Удар затьмарення» скорочує перезарядження «Удару висхідного сонця» та «Кулаків люті» на ${$100784m3/1000}.1 сек." },
    { en = "Overpower causes a seismic wave, dealing $315961s1 damage to all enemies in a $315961A1 yd line. Deals reduced damage beyond $315961s2 targets.", ua = "«Пересилення» викликає сейсмічну хвилю, що завдає $315961s1 шкоди всім ворогам на лінії завдовжки $315961A1 м. Якщо цілей більше ніж $315961s2, шкоду зменшено." },
    { en = "Your auto-attacks generate $?c1[$s2]?$c2[$s3][$s4]% more Rage.\n\n\n\nKilling an enemy instantly generates ${$262232s1/10} Rage and increases your movement speed by $262232s2% for $262232d.", ua = "Ваші автоатаки генерують на $?c1[$s2]?$c2[$s3][$s4]% більше люті.\n\n\n\nУбивство ворога миттєво генерує ${$262232s1/10} люті та збільшує вашу швидкість пересування на $262232s2% протягом $262232d." },
    { en = "Windfury has a $s2% additional chance to trigger and its damage is increased by $s1%.", ua = "«Шал вітру» має додаткові $s2% імовірності спрацювати, а його шкода збільшена на $s1%." },
    { en = "Channel a torrent of void energy into the target, dealing $o Shadow damage over $d and tearing open an $@spellname447444.\n\n\n\n$@spellicon447444 $@spellname447444\n\n$@spelldesc447444\n\n\n\n|cFFFFFFFFGenerates ${$289577s1*$289577s2/100} Insanity over the duration.|r", ua = "Спрямовує в ціль потік енергії Порожнечі, завдаючи $o шкоди Тінню протягом $d і розриваючи $@spellname447444.\n\n\n\n$@spellicon447444 $@spellname447444\n\n$@spelldesc447444\n\n\n\n|cFFFFFFFFДає ${$289577s1*$289577s2/100} Безумства протягом дії.|r" },
    { en = "Your Agony, $?a445465[Wither][Corruption], and Unstable Affliction deal damage $s1% faster.", ua = "Ваші «Агонія», $?a445465[«В'янення»][«Псування»] та «Нестабільна неміч» завдають шкоди на $s1% швидше." },
    { en = "When your Dreadstalkers charge into battle, their Dreadbite attack now hits all targets within $271971A1 yards and deals $s1% more damage.", ua = "Коли твої ловчі жаху кидаються в бій, їхній «Укус жаху» тепер влучає по всіх цілях у радіусі $271971A1 м і завдає на $s1% більше шкоди." },
    { en = "Instantly sacrifice up to $s1 Wild Imps, generating $s1 charges of Demonic Core that cause Demonbolt to deal $334581s1% additional damage.", ua = "Миттєво приносить у жертву до $s1 диких бісів, створюючи $s1 зарядів «Демонічного ядра», завдяки яким «Демонічна стріла» завдає на $334581s1% більше шкоди." },
    { en = "Wildfire Bomb now has ${$s1+1} charges, and the initial explosion deals $s2% increased damage.", ua = "«Бомба дикого вогню» тепер має ${$s1+1} заряди, а початковий вибух завдає на $s2% більше шкоди." },
    { en = "Increases the range of Leg Sweep by $s1 yds.", ua = "Збільшує радіус «Підсічки» на $s1 м." },
    { en = "Reduces all damage you and your pet take by $s1% for $d.", ua = "Зменшує всю шкоду, якої зазнаєте ти і твій улюбленець, на $s1% на $d." },
    { en = "Reduces the cooldown of Capacitor Totem by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Тотема-конденсатора» на ${$s1/-1000} сек." },
    { en = "Summon a Demonic Tyrant that damages your target for $d. \n\n\n\nDamage dealt by Demonic Tyrant is increased by $1276788s1% for each Wild Imp and Dreadstalker active.$?s334585[\n\n\n\n|cFFFFFFFFGenerates ${$s2/10} Soul Shards.|r][]", ua = "Викликає демонічного тирана, який завдає шкоди вашій цілі протягом $d. \n\n\n\nШкода від демонічного тирана підвищена на $1276788s1% за кожного активного дикого біса й жахоблукача.$?s334585[\n\n\n\n|cFFFFFFFFСтворює ${$s2/10} уламків душі.|r][]" },
    { en = "While your initial Infernal is active, every Soul Shard you spend has a $s1% chance to summon an additional Infernal that lasts $335236d.", ua = "Поки діє твій перший інфернал, кожен витрачений уламок душі має $s1% шансу прикликати додаткового інфернала, що існує $335236d." },
    { en = "Chaos Bolt consumes up to $s1 sec of $?a445465[Wither's][Immolate's] damage over time effect on your target, instantly dealing that much damage.", ua = "Хаосний болт поглинає до $s1 сек. ефекту періодичної шкоди $?a445465[Всихання][Спалення] на вашій цілі, миттєво завдаючи такої ж шкоди." },
    { en = "The cooldown of $?c3[Aspect of the Eagle, ][]Aspect of the Cheetah, and Aspect of the Turtle are reduced by ${$s1/-1000} sec.", ua = "Перезарядження $?c3[Подоби орла, ][]Подоби гепарда та Подоби черепахи зменшено на ${$s1/-1000} сек." },
    { en = "Your Call Pet additionally summons the pet from the bonus slot in your stable. This pet will obey your Kill Command, but cannot use pet family abilities.", ua = "Твій «Виклик улюбленця» додатково прикликає улюбленця з бонусного місця твоєї стайні. Цей улюбленець слухатиметься твого «Наказу вбити», але не може використовувати здібності своєї родини улюбленців." },
    { en = "Shadow Bolt and Demonbolt deal $s1% additional damage per demon you have summoned.", ua = "«Стріла тіні» й «Демонічна стріла» завдають на $s1% більше шкоди за кожного прикликаного тобою демона." },
    { en = "You passively summon a Wild Imp to fight for you every $t1 sec.", ua = "Ти пасивно прикликаєш дикого біса, який б'ється за тебе, кожні $t1 сек." },
    { en = "Frailty now also reduces all damage you take from afflicted targets by $s2%.", ua = "«Кволість» тепер також зменшує всю шкоду, яку ти отримуєш від уражених цілей, на $s2%." },
    { en = "$@spelldesc48018\n\n\n\nYou also learn:\n\n\n\n$@spellicon48020 $@spellname48020\n\n$@spelldesc48020", ua = "$@spelldesc48018\n\n\n\nВи також вивчаєте:\n\n\n\n$@spellicon48020 $@spellname48020\n\n$@spelldesc48020" },
    { en = "Consuming Hot Streak has a $s1% chance to make your next non-instant Pyroblast or Flamestrike cast within $269651d deal $269651s1% additional damage.\n\n\n\nMaximum $269651u stacks.", ua = "Споживання Жаркої смуги з імовірністю $s1% змушує ваш наступний нешвидкий Піровибух чи Полум'яний удар, сотворений протягом $269651d, завдати на $269651s1% більше шкоди.\n\n\n\nМаксимум $269651u нашарувань." },
    { en = "Kill Command now has ${$s1+1} charges, and deals $s2% increased damage.", ua = "Наказ убити тепер має ${$s1+1} заряди та завдає на $s2% більше шкоди." },
    { en = "Frozen Orb makes Blizzard instant cast.\n\n\n\nBlizzard damage increased by $s2%.", ua = "Заморожена сфера робить Хуртовину миттєвою.\n\n\n\nШкода від Хуртовини збільшена на $s2%." },
    { en = "Exhilaration's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Наснаги» зменшено на ${-$s1/1000} сек." },
    { en = "Charge to your target with your blades out, dealing ${$271881sw1*$271881s2/100} Physical damage to the target and $271881sw1 to all other nearby enemies. Damage reduced beyond $271881sw3 targets.\n\n\n\nWhile Blade Flurry is active, damage to non-primary targets is increased by $s1%.\n\n\n\n|cFFFFFFFFGenerates ${$271896s1*$271896d/$271896t1} Energy over $271896d.", ua = "Кидається до цілі з оголеними клинками, завдаючи ${$271881sw1*$271881s2/100} фізичної шкоди цілі та $271881sw1 усім іншим ворогам поблизу. Шкода зменшується за межами $271881sw3 цілей.\n\n\n\nПоки активний Шквал клинків, шкода по неосновних цілях збільшується на $s1%.\n\n\n\n|cFFFFFFFFГенерує ${$271896s1*$271896d/$271896t1} енергії протягом $271896d." },
    { en = "Blade Flurry strikes $s3 additional enemies and its duration is increased by ${$s2/1000} sec.", ua = "Кількість ворогів, яких вражає «Шквал клинків», збільшена на $s3, а його тривалість — на ${$s2/1000} сек." },
    { en = "Earth Shock, Elemental Blast, and Earthquake have a $s1% chance to refund all Maelstrom spent.", ua = "«Земний шок», «Стихійний вибух» і «Землетрус» з імовірністю $s1% повертають увесь витрачений Вир." },
    { en = "Kill Command deals $s1% increased damage.", ua = "«Наказ убити» завдає на $s1% більше шкоди." },
    { en = "Each enemy hit by Blood Boil increases the damage and healing done by your next Death Strike by $273947s1%, stacking up to $273947u times.", ua = "Кожен ворог, уражений «Кипінням крові», збільшує шкоду та зцілення твого наступного «Удару смерті» на $273947s1%. Складається до $273947u разів." },
    { en = "$?s152280[Defile][Death and Decay] reduces the movement speed of enemies within its area by $s1%, decaying by $s2% every sec.", ua = "$?s152280[Опоганення][Смерть і тлін] зменшує швидкість пересування ворогів у своїй зоні на $s1%, послаблюючись на $s2% щосекунди." },
    { en = "Death Strike's healing is increased by $s2% and grants you $274009s1% Leech for $274009d.", ua = "Зцілення від «Удару смерті» збільшене на $s2%, і він дарує тобі $274009s1% висмоктування на $274009d." },
    { en = "Deals $s1 Astral damage to the target and empowers New Moon to become Half Moon. \n\n\n\n|cFFFFFFFFGenerates ${$m3/10} Astral Power.|r", ua = "Завдає $s1 астральної шкоди цілі та підсилює Молодик, перетворюючи його на Півмісяць. \n\n\n\n|cFFFFFFFFСтворює ${$m3/10} Астральної сили.|r" },
    { en = "Vivify heals all allies with your Renewing Mist active for $425804s1.\n\n\n\nSheilun's Gift's healing is increased by $s2% on its primary target.", ua = "«Оживлення» зцілює всіх союзників, на яких діє ваш «Відновлювальний туман», на $425804s1.\n\n\n\nЗцілення «Дару Шейлуна» збільшено на $s2% для його основної цілі." },
    { en = "Unleash a furious frenzy, clawing your target $m2 times for ${$274838s1*$m2} Physical damage and an additional ${$m2*$274838s3*$274838d/$274838t3} Bleed damage over $274838d.\n\n\n\n|cFFFFFFFFAwards $s1 combo points.|r", ua = "Вивільняє несамовитий шал, дряпаючи вашу ціль $m2 раз(ів) на ${$274838s1*$m2} фізичної шкоди та ще ${$m2*$274838s3*$274838d/$274838t3} шкоди від кровотечі протягом $274838d.\n\n\n\n|cFFFFFFFFНадає $s1 комбо-очок.|r" },
    { en = "Your periodic heals on targets with Lifebloom have a $s2% chance to cause it to bloom.", ua = "Твої періодичні зцілення цілей із «Цвітом життя» з імовірністю $s2% змушують його розквітнути." },
    { en = "Rising Sun Kick extends your Renewing Mist and Enveloping Mist effects by $s1 sec, up to $s2% of their original duration.", ua = "Удар висхідного сонця подовжує дію твоїх Оновлювального та Огортального туманів на $s1 сек., до $s2% їхньої початкової тривалості." },
    { en = "Shield Slam deals $s1% increased damage and reduces enemies' damage against you by $275335s1% for $275335d. Multiple punishments may overlap.", ua = "«Удар щитом» завдає на $s1% більше шкоди та зменшує шкоду ворогів по тобі на $275335s1% на $275335d. Кілька покарань можуть діяти одночасно." },
    { en = "Avatar increases the damage of Thunder Clap by $107574s9% and reduces its cooldown by $107574s10%.", ua = "«Аватар» збільшує шкоду «Удару грому» на $107574s9% і скорочує його перезарядження на $107574s10%." },
    { en = "Shockwave's range increased by $s3 yards and when it strikes at least $s1 targets its cooldown is reduced by $s2 sec.", ua = "Дальність «Ударної хвилі» збільшено на $s3 м, а коли вона влучає щонайменше в $s1 цілей, її перезарядження скорочується на $s2 сек." },
    { en = "Sudden Doom triggers $s2% more often and can accumulate up to ${$m1+1} charges.\n\n\n\nSummoning a Lesser Ghoul with Scourge Strike reduces the cooldown of Putrefy by ${$s3/1000}.1 sec.", ua = "Раптова погибель спрацьовує на $s2% частіше й може накопичувати до ${$m1+1} зарядів.\n\n\n\nПрикликання нижчого вампіра через Удар погибелі скорочує перезарядження Гниття на ${$s3/1000}.1 сек." },
    { en = "Increases the range of Death Grip by $s1 yds.\n\n\n\nKilling an enemy that yields experience or honor resets the cooldown of Death Grip.", ua = "Збільшує дальність Хватки смерті на $s1 м.\n\n\n\nУбивство ворога, який дає досвід або честь, скидає перезарядження Хватки смерті." },
    { en = "Shuriken Storm reduces enemies' movement speed by $206760s1% for $206760d.", ua = "Буря сюрикенів зменшує швидкість руху ворогів на $206760s1% на $206760d." },
    { en = "Consume $m1 beneficial Magic effect removing it from the target$?s320313[ and granting you $1277738s1 Fury][].", ua = "Поглинає $m1 корисний магічний ефект, знімаючи його з цілі$?s320313[ і даруючи вам $1277738s1 люті][]." },
    { en = "Summons a frostwyrm who breathes on all enemies within $s1 yd in front of you, dealing $279303s1 Frost damage, stunning enemies for $377048d, and slowing movement speed by $279303s2% for $279303d.", ua = "Прикликає морозного вирма, який дихає на всіх ворогів у межах $s1 м перед тобою, завдаючи $279303s1 шкоди від морозу, приголомшуючи ворогів на $377048d і сповільнюючи швидкість руху на $279303s2% на $279303d." },
    { en = "Moonfire deals $s2% increased damage and also hits another nearby enemy within $s1 yds of the target.", ua = "«Місячний вогонь» завдає на $s2% більше шкоди й уражає ще одного ворога поблизу, у межах $s1 м від цілі." },
    { en = "Sinister Strike has a $s1% chance to hit an additional time and grant Opportunity.\n\n\n\n$@spellicon195627 $@spellname195627\n\nYour next Pistol Shot costs $195627s1% less Energy and deals $195627s2% increased damage.", ua = "«Підступний удар» має $s1% шанс вдарити ще раз і надати «Нагоду».\n\n\n\n$@spellicon195627 $@spellname195627\n\nТвій наступний «Постріл з пістоля» коштує на $195627s1% менше Енергії та завдає на $195627s2% більше шкоди." },
    { en = "The cooldown of $?s152173[Serenity][Zenith] is reduced by ${$s1/-1000} sec.", ua = "Перезарядження $?s152173[Безтурботності][Зеніту] зменшено на ${$s1/-1000} с." },
    { en = "Armor granted by Shield of the Righteous is increased by up to $s1%, based on your missing health.", ua = "Броня, надана «Щитом праведника», збільшується щонайбільше на $s1% залежно від кількості втраченого тобою здоров'я." },
    { en = "Whirlwind $?s436707[and Thunder Clap deal][deals] $s1% additional damage when $?s436707[they hit][it hits] $s2 or more targets.", ua = "Вихор $?s436707[та Громовий удар завдають][завдає] $s1% додаткової шкоди, коли $?s436707[вони вражають][він вражає] $s2 або більше цілей." },
    { en = "Increases the duration of |CFFffffffStagger|R by ${$s1/10}.1 sec, causing |CFFffffffStaggered|R damage to be dealt to you more gradually.", ua = "Збільшує тривалість |CFFffffffВідстрочення|R на ${$s1/10}.1 сек., тож |CFFffffffвідстрочена|R шкода завдається тобі поступовіше." },
    { en = "Adds a Leeching effect to your Lethal poisons, granting you ${$108211s1}.1% Leech.", ua = "Додає твоїм смертельним отрутам ефект висмоктування, надаючи тобі ${$108211s1}.1% висмоктування." },
    { en = "$?a317320[Condemn][Execute] is usable on targets below $s2% health.", ua = "$?a317320[Засудження][Страту] можна застосовувати до цілей зі здоров'ям нижче $s2%." },
    { en = "During Pillar of Frost, Frost Strike$?s194913[, Glacial Advance,][] and Howling Blast always grant Killing Machine and have a $s2% chance to generate a Rune.\n\n\n\nAdditionally during Pillar of Frost, Empower Rune Weapon causes your next Obliterate or Frostscythe to cost no Runes.", ua = "Під час дії Стовпа морозу Морозний удар$?s194913[, Льодовиковий наступ][] та Виючий шквал завжди надають Машину вбивства й мають $s2% шансу створити Руну.\n\n\n\nКрім того, під час дії Стовпа морозу Підсилення рунічної зброї робить так, що ваше наступне Винищення або Морозна коса не коштують Рун." },
    { en = "Arcane Pulse has a $s1% chance to repeat its explosion at $s2% effectiveness.", ua = "«Арканний імпульс» має $s1% шансу повторити свій вибух з ефективністю $s2%." },
    { en = "Finishing move that deals instant damage and applies Rip to all enemies within $A1 yards. Lasts longer per combo point.\n\n\n\n   1 point  : ${$s1*2} plus Rip for ${$s2*2} sec\n\n   2 points: ${$s1*3} plus Rip for ${$s2*3} sec\n\n   3 points: ${$s1*4} plus Rip for ${$s2*4} sec\n\n   4 points: ${$s1*5} plus Rip for ${$s2*5} sec\n\n   5 points: ${$s1*6} plus Rip for ${$s2*6} sec", ua = "Завершальний прийом, що завдає миттєвої шкоди і накладає Розрив на всіх ворогів у межах $A1 ярдів. Триває довше за кожну комбо-очку.\n\n\n\n   1 очко  : ${$s1*2} плюс Розрив на ${$s2*2} сек\n\n   2 очки: ${$s1*3} плюс Розрив на ${$s2*3} сек\n\n   3 очки: ${$s1*4} плюс Розрив на ${$s2*4} сек\n\n   4 очки: ${$s1*5} плюс Розрив на ${$s2*5} сек\n\n   5 очок: ${$s1*6} плюс Розрив на ${$s2*6} сек" },
    { en = "Increases your critical strike chance by $s3% and critical strike damage by $s4% for $d.\n\n\n\n$@spellicon19434 $@spellname19434\n\nCooldown recovers $s2% faster$?a471366[, cast time reduced by $471366s1%, and Focus cost reduced $471366s2%.][.]\n\n\n\n$@spellicon257044 $@spellname257044\n\nCooldown recovers $s1% faster.$?(a1253599&a470943)[\n\n\n\n|cFFFFFFFFApplies Sentinel's Mark.|r]?(!a1253599&a470943)[\n\n\n\n|cFFFFFFFFApplies Spotter's Mark.|r][]", ua = "Збільшує ваш шанс критичного удару на $s3% та критичну шкоду на $s4% протягом $d.\n\n\n\n$@spellicon19434 $@spellname19434\n\nПерезарядження відновлюється на $s2% швидше$?a471366[, час застосування зменшено на $471366s1%, а витрати зосередження зменшено на $471366s2%.][.]\n\n\n\n$@spellicon257044 $@spellname257044\n\nПерезарядження відновлюється на $s1% швидше.$?(a1253599&a470943)[\n\n\n\n|cFFFFFFFFНакладає Мітку вартового.|r]?(!a1253599&a470943)[\n\n\n\n|cFFFFFFFFНакладає Мітку спостерігача.|r][]" },
    { en = "Dispersion heals you for an additional $<intangheal>% of your maximum health over its duration and its cooldown is reduced by ${$s1/-1000} sec.", ua = "Безтілесність додатково зцілює вас на $<intangheal>% від максимального здоров'я протягом своєї дії, а її перезарядження зменшується на ${$s1/-1000} с." },
    { en = "Cooldown reduced by ${$m1/-1000} sec.", ua = "Перезарядження скорочено на ${$m1/-1000} сек." },
    { en = "Stamina increased by $s1%.", ua = "Витривалість збільшено на $s1%." },
    { en = "When your Lesser Ghouls expire, they explode in viscera, dealing $<damage> Shadow damage to enemies nearby.", ua = "Коли ваші Менші Гулі зникають, вони вибухають нутрощами, завдаючи $<damage> шкоди Тіні ворогам поблизу." },
    { en = "Your abilities are amplified based on your current shapeshift form, granting an additional effect.\n\n\n\nWrath, Starfire, and Starsurge deal $s2% additional damage and generate $411146s1 Mana.\n\n\n\n$@spellicon197491|CFFFFFFFFBear Form|R\n\nIronfur grants $s1% additional armor and generates $411144s1 Mana.\n\n\n\n$@spellicon202155 |CFFFFFFFFCat Form|R\n\nRip, Ferocious Bite, and Maim deal $s3% additional damage and generate $411143s1 Mana when cast with $s4 combo points.", ua = "Ваші здібності посилюються залежно від вашої поточної подоби, надаючи додатковий ефект.\n\n\n\nГнів, Зоряний вогонь і Зоряний сплеск завдають на $s2% більше шкоди та дають $411146s1 мани.\n\n\n\n$@spellicon197491|CFFFFFFFFПодоба ведмедя|R\n\nЗалізне хутро дає на $s1% більше броні та дає $411144s1 мани.\n\n\n\n$@spellicon202155 |CFFFFFFFFПодоба кота|R\n\nРозрив, Лютий укус і Калічення завдають на $s3% більше шкоди та дають $411143s1 мани, коли застосовуються з $s4 очками комбо." },
    { en = "Stormstrike and Lava Lash unleash a Chain Lightning at $s2% effectiveness that deals $s1% reduced damage with each jump.", ua = "«Удар бурі» та «Лавовий батіг» вивільняють «Ланцюгову блискавку» з $s2% ефективності, яка завдає на $s1% менше шкоди з кожним перескоком." },
    { en = "Frenzied Regeneration and Barkskin increase all healing received by $s1%.", ua = "«Шалена регенерація» та «Кора» збільшують усе отримуване зцілення на $s1%." },
    { en = "Blessing of Freedom increases movement speed by $m1%, and you gain Blessing of Freedom when cast on a friendly target.", ua = "«Благословення свободи» збільшує швидкість руху на $m1%, а коли ти твориш його на дружню ціль, то й сам отримуєш «Благословення свободи»." },
    { en = "When you cast Word of Glory on someone other than yourself, its healing is increased by up to $s1% based on the target's missing health.", ua = "Коли ти твориш «Слово слави» на когось іншого, а не на себе, його зцілення збільшується аж до $s1% залежно від втраченого здоров'я цілі." },
    { en = "Execute no longer costs Rage and now generates ${$s3/10} Rage.", ua = "Страта більше не коштує люті й тепер генерує ${$s3/10} люті." },
    { en = "Execute no longer has a cooldown and if your foe survives, $163201s2% of the Rage spent is refunded.", ua = "Страта більше не має перезарядження, а якщо ворог виживає, тобі повертається $163201s2% витраченої люті." },
    { en = "Increases Frost Strike and Glacial Advance damage by $s1%.", ua = "Збільшує шкоду Морозного удару та Льодовикового наступу на $s1%." },
    { en = "$?a137006[Frostscythe deals $s3% increased damage during Remorseless Winter.][]$?a137008[Heart Strike hits up to $s1][]$?a137007[Scourge Strike and Festering Strike deal $s4% increased damage.][]$?a137008[ additional enemies while you remain in Death and Decay.\n\n\n\nWhen leaving your Death and Decay you retain its bonus effects for ${$s2/1000} sec.][]", ua = "$?a137006[Морозна коса завдає на $s3% більше шкоди під час Безжальної зими.][]$?a137008[Удар у серце вражає до $s1][]$?a137007[Удар Бича та Гнійний удар завдають на $s4% більше шкоди.][]$?a137008[ додаткових ворогів, доки ви лишаєтеся в Смерті й тлінні.\n\n\n\nКоли ви покидаєте свою Смерть і тлінь, ви зберігаєте її бонусні ефекти ще ${$s2/1000} сек.][]" },
    { en = "Vampiric Blood's healing and absorb amount is increased by $s1% and duration by ${$s3/1000} sec.", ua = "Обсяг зцілення та поглинання «Вампірської крові» збільшено на $s1%, а тривалість — на ${$s3/1000} сек." },
    { en = "Unending Resolve reduces damage taken by an additional $s1%.", ua = "«Незламна рішучість» додатково зменшує отримувану шкоду на $s1%." },
    { en = "While Crimson Scourge is active, your next Death and Decay heals you for $317614s1 health per Bone Shield charge and you immediately gain ${$317614s2/10} Runic Power.", ua = "Поки діє «Кармазиновий бич», твоя наступна «Смерть і розклад» зцілює тебе на $317614s1 здоров'я за кожен заряд «Кістяного щита», і ти одразу отримуєш ${$317614s2/10} рунної сили." },
    { en = "Wound Poison can now stack $s1 additional times.", ua = "Ранова отрута тепер може накопичуватися ще $s1 разів." },
    { en = "Stormstrike has an additional charge.\n\n\n\nStormsurge now also causes your next Stormstrike to deal $s1% additional damage as Nature damage, stacking up to $470466u times.", ua = "Удар бурі отримує додатковий заряд.\n\n\n\nХвиля бурі тепер також змушує ваш наступний Удар бурі завдавати на $s1% більше шкоди як шкоду від сил природи, накопичуючись до $470466u разів." },
    { en = "$?s200758[Gloomblade][Backstab] has $s2% increased critical strike chance.\n\n\n\nWhile behind your target, Backstab critical strikes grant Find Weakness for $s1 sec.", ua = "$?s200758[Похмурий клинок][Удар у спину] має на $s2% більший шанс критичного удару.\n\n\n\nКоли ви позаду цілі, критичні Удари у спину надають Пошук слабкості на $s1 сек." },
    { en = "Shuriken Storm has $s2% increased critical strike chance.\n\n\n\nShuriken Storm critical strikes grant Find Weakness for $s1 sec.", ua = "«Буря сюрикенів» має на $s2% більший шанс критичного удару.\n\n\n\nКритичні удари «Бурі сюрикенів» надають «Знайти слабкість» на $s1 сек." },
    { en = "Consume Magic generates $1277738s1 Fury when a beneficial Magic effect is successfully removed from the target.", ua = "Поглинання магії породжує $1277738s1 од. Люті, коли з цілі успішно знято корисний магічний ефект." },
    { en = "$?c3[Soul Immolation][Immolation Aura] increases your armor by $s1% and causes melee attackers to suffer ${$320334s1/$s3} $@spelldesc395020 damage.", ua = "$?c3[Спалення душі][Аура спалення] збільшує вашу броню на $s1% і змушує тих, хто атакує в ближньому бою, зазнавати ${$320334s1/$s3} шкоди від $@spelldesc395020." },
    { en = "Increases the range of Disrupt to ${$s2+$s1} yds.", ua = "Збільшує дальність «Зриву» до ${$s2+$s1} м." },
    { en = "Immolation Aura generates an additional ${$258922s2*$258920d} Fury over $258920d.", ua = "«Аура спалення» створює додатково ${$258922s2*$258920d} люті протягом $258920d." },
    { en = "Throw Glaive ricochets to $s1 additional $ltarget:targets;.", ua = "Кидок глефи рикошетить ще на $s1 $lціль:цілі;." },
    { en = "Reduces the cooldown of Fracture by ${$s2/-1000} sec and Throw Glaive by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Перелому» на ${$s2/-1000} сек., а «Кидка глефи» — на ${$s1/-1000} сек." },
    { en = "The chance that Chaos Strike will refund $193840s1 Fury is increased by $s2% of your critical strike chance.", ua = "Шанс, що «Удар хаосу» поверне $193840s1 од. люті, збільшений на $s2% від твого шансу критичного удару." },
    { en = "$?a212613[Infernal Strike]?s195072[Fel Rush][Shift] gains an additional charge.", ua = "$?a212613[Пекельний удар]?s195072[Ривок Скверни][Зсув] отримує додатковий заряд." },
    { en = "Reduces the cooldown of Sigil of $?s202138[Chains][Misery] by $?s202138[${$s2/-1000}][${$s1/-1000}] sec.", ua = "Зменшує перезарядження «Печатки $?s202138[ланцюгів][страждань]» на $?s202138[${$s2/-1000}][${$s1/-1000}] сек." },
    { en = "Vengeful Retreat reduces the movement speed of all nearby enemies by $198813s1% for $198813d.", ua = "«Мстивий відступ» зменшує швидкість руху всіх ворогів поруч на $198813s1% на $198813d." },
    { en = "Mastery increases your movement speed.", ua = "Майстерність збільшує твою швидкість руху." },
    { en = "Increases maximum Fury by $s1.", ua = "Збільшує максимум люті на $s1." },
    { en = "Barbed Shot now instantly grants $1282660s1 Focus.\n\n\n\nPassive Focus generation increased by $s1%.", ua = "Шипастий постріл тепер миттєво надає $1282660s1 зосередження.\n\n\n\nПасивне накопичення зосередження збільшується на $s1%." },
    { en = "Every $s1 Shields of the Righteous make your next Word of Glory cost no Holy Power. Maximum $327510U stacks.", ua = "Після кожних $s1 вжитків «Щита праведника» твоє наступне «Слово слави» не коштує святої сили. Максимум $327510U накопичень." },
    { en = "Wildfire Bomb deals $s1% additional damage.", ua = "«Бомба дикого вогню» завдає на $s1% більше шкоди." },
    { en = "If a target dies within $322098d after being struck by Shadow Word: Death, generate ${$321973s1/100} Insanity.\n\n\n\nWhen Shadow Word: Death fails to kill a target below $s2% health, its cooldown is reset. Cannot occur more than once every $390628d.", ua = "Якщо ціль гине протягом $322098d після удару «Словом тіні: Смерть», ви отримуєте ${$321973s1/100} Безуму.\n\n\n\nКоли «Слову тіні: Смерть» не вдається вбити ціль зі здоров'ям нижче $s2%, його перезарядження скидається. Не може ставатися частіше ніж раз на $390628d." },
    { en = "Arcane damage dealt is increased based on your current mana, up to $1217242s2% at full mana.$?a1243926[][\n\n\n\nMana Regen is increased based on your current mana, up to $1217242s3% when out of mana.]", ua = "Завдана арканна шкода збільшується залежно від вашої поточної мани, до $1217242s2% за повної мани.$?a1243926[][\n\n\n\nВідновлення мани збільшується залежно від вашої поточної мани, до $1217242s3%, коли мана вичерпана.]" },
    { en = "Clearcasting can stack up to $s1 additional times.", ua = "«Чисте чарування» може накопичуватися додатково до $s1 разів." },
    { en = "$?a466932[Black Arrow][Kill Shot] now has ${$m1+1} charges and has its cooldown reduced by ${$m2/-1000}.1 sec.", ua = "$?a466932[Чорна стріла][Смертельний постріл] тепер має ${$m1+1} зарядів, а його перезарядження зменшено на ${$m2/-1000}.1 сек." },
    { en = "Applies Touch of the Magi to your current target, accumulating $s1% of the damage you deal to the target for $210824d, and then exploding for that amount of Arcane damage to the target and reduced damage to all nearby enemies.\n\n\n\n|cFFFFFFFFGenerates $s2 Arcane Charges.|r", ua = "Накладає Дотик магів на вашу поточну ціль, накопичуючи $s1% шкоди, яку ви завдаєте цілі, протягом $210824d, а потім вибухає, завдаючи цілі арканної шкоди в цьому обсязі та зменшеної шкоди всім ворогам поблизу.\n\n\n\n|cFFFFFFFFГенерує $s2 арканних зарядів.|r" },
    { en = "Arcane Barrage grants you ${$s1/100}.1% of your maximum mana per Arcane Charge spent.", ua = "«Арканний шквал» відновлює тобі ${$s1/100}.1% максимальної мани за кожен витрачений арканний заряд." },
    { en = "Blazing Barrier's damage is increased by $s1% and it now cauterizes your wounds, healing you for $s2% of the damage it absorbs.", ua = "Шкода «Палючого бар'єра» збільшена на $s1%, і тепер він припікає твої рани, зцілюючи тебе на $s2% поглинутої ним шкоди." },
    { en = "Prismatic Barrier further reduces magical damage taken by an additional $s1% and duration of harmful Magic effects by $s2%.", ua = "Призматичний бар'єр додатково зменшує отримувану магічну шкоду ще на $s1%, а тривалість шкідливих магічних ефектів — на $s2%." },
    { en = "Touch of Death can now be used on targets with less than $s1% health remaining, dealing $s2% of your maximum health in damage.", ua = "«Дотик смерті» тепер можна використовувати на цілях, у яких лишилося менше ніж $s1% здоров'я; він завдає шкоди в розмірі $s2% твого максимального здоров'я." },
    { en = "Power Word: Radiance gains an additional charge.", ua = "«Слово сили: Сяйво» отримує додатковий заряд." },
    { en = "Summons an effigy of Yu'lon, the Jade Serpent for $d. Yu'lon will heal injured allies with Soothing Breath, healing the target and up to $s2 allies for $343737o1 over $343737d. \n\n\n\nEnveloping Mist costs $s4% less mana while Yu'lon is active.", ua = "Прикликає подобу Юй'лон, Нефритової Змії, на $d. Юй'лон зцілюватиме поранених союзників Заспокійливим подихом, зцілюючи ціль і до $s2 союзників на $343737o1 протягом $343737d. \n\n\n\nОгортальний туман коштує на $s4% менше мани, поки Юй'лон активна." },
    { en = "Niuzao's teachings allow you to shuffle during combat, increasing the effectiveness of your |CFFffffffStagger|R by $s1%.\n\n\n\nShuffle is granted by attacking enemies with your Keg Smash, Blackout Kick, and Spinning Crane Kick.\n\n\n\n$@spellicon115069 $@spellname115069: $@spelldesc115069", ua = "Вчення Нюдзао дозволяють тобі човгати під час бою, збільшуючи дієвість твого |CFFffffffХитання|R на $s1%.\n\n\n\nЧовгання дається за атаку ворогів Ударом барилом, Ударом затьмарення і Обертовим ударом журавля.\n\n\n\n$@spellicon115069 $@spellname115069: $@spelldesc115069" },
    { en = "A swig of strong brew that coalesces purified chi escaping your body into a celestial guard, absorbing $s1 damage.", ua = "Ковток міцного варива, що згущує очищене ці, яке виходить із твого тіла, у небесний захист, що поглинає $s1 шкоди." },
    { en = "While active, Invoke Niuzao, the Black Ox can be recast to cause Niuzao to stomp mightily and knock nearby enemies into the air.", ua = "Поки ефект активний, «Прикликання Нюцзао, Чорного Бика» можна створити повторно, щоб Нюцзао могутньо тупнув і підкинув ворогів поблизу в повітря." },
    { en = "Fortifying Brew increases |CFFffffffStagger|R effectiveness by $s1% while active.\n\n\n\nCombines with other Fortifying Brew effects.", ua = "Зміцнювальне вариво збільшує ефективність |CFFffffffЗатримки|R на $s1%, поки воно активне.\n\n\n\nПоєднується з іншими ефектами Зміцнювального варива." },
    { en = "Reduces the cooldown of Purifying Brew, Celestial Brew, and Celestial Infusion by $s1%.", ua = "Зменшує перезарядження «Очисного варива», «Небесного варива» і «Небесного вливання» на $s1%." },
    { en = "Hurls a flaming keg at the target location, dealing $s1 Fire damage to nearby enemies, causing your attacks against them to deal $388867s1 additional Fire damage, and causing their melee attacks to deal $s2% reduced damage for the next $d.\n\n\n\nResets the cooldown of Keg Smash.", ua = "Жбурляє палаюче барило в обрану місцину, завдаючи $s1 шкоди від вогню ворогам поблизу, через що ваші атаки по них завдають додатково $388867s1 шкоди від вогню, а їхні атаки ближнього бою завдають на $s2% менше шкоди протягом наступних $d.\n\n\n\nСкидає перезарядження Удару барилом." },
    { en = "Summon an effigy of Chi-Ji for $d that kicks up $s2 Gust of Mists when you Blackout Kick, Rising Sun Kick, or Spinning Crane Kick, healing up to $343818s3 allies for ${$343819s1*$s6/100}.\n\n\n\nChi-Ji's presence makes you immune to movement impairing effects, makes Enveloping Mist instant cast, and reduces the mana cost of Enveloping Mist by $s3%.", ua = "Прикликає подобу Чі-Джі на $d, що здіймає $s2 Пориви туману, коли ви застосовуєте Затьмарливий удар, Удар вранішнього сонця чи Вихровий удар журавля, зцілюючи до $343818s3 союзників на ${$343819s1*$s6/100}.\n\n\n\nПрисутність Чі-Джі робить вас несприйнятливим до ефектів, що сповільнюють рух, робить Огортальний туман миттєвим у прочитанні та зменшує витрати мани на Огортальний туман на $s3%." },
    { en = "Spending Chi has a chance to make your next Spinning Crane Kick cost no Chi.", ua = "Витрачання чі має шанс зробити так, що твій наступний Обертовий удар журавля не коштуватиме чі." },
    { en = "$?s404542[Crusading Strikes has a $s2%][Crusader Strike has a $s1%] chance to make your next Divine Storm free and deal $326733s1% additional damage.", ua = "$?s404542[«Удари хрестоносця» мають $s2%][«Удар хрестоносця» має $s1%] шансу зробити твою наступну «Божественну бурю» безкоштовною та змусити її завдати на $326733s1% більше шкоди." },
    { en = "The cooldown of Lay on Hands is reduced up to $s1%, based on the target's missing health.\n\n\n\nWord of Glory's healing is increased by up to $m3% on yourself, based on your missing health.", ua = "Перезарядження «Накладання рук» зменшено до $s1% залежно від нестачі здоров'я цілі.\n\n\n\nЗцілення «Слова слави» на вас самих зростає до $m3% залежно від нестачі вашого здоров'я." },
    { en = "Fel Devastation heals for an additional $s1%, and $s2% of its healing is converted into an absorb shield for $326863d.", ua = "«Спустошення Скверни» зцілює додатково на $s1%, а $s2% цього зцілення перетворюється на поглинальний щит на $326863d." },
    { en = "Casting Starfall extends the duration of active Moonfires and Sunfires by ${$s1}.1 sec, up to $s2 sec.", ua = "Творення «Зорепаду» подовжує тривалість активних «Місячного вогню» та «Сонячного вогню» на ${$s1}.1 сек., аж до $s2 сек." },
    { en = "Barkskin's duration is increased by ${$s1/1000} sec.", ua = "Тривалість «Корошкури» збільшена на ${$s1/1000} сек." },
    { en = "Wild Growth heals $s1 additional $ltarget:targets;.", ua = "«Дикий ріст» зцілює на $s1 більше цілей." },
    { en = "Ambush and Mutilate have a $s1% chance to make your next Ambush free and usable without Stealth. Chance increased to $s2% if the target is under $s3% health.", ua = "«Засідка» та «Калічення» мають $s1% шансу зробити твою наступну «Засідку» безкоштовною та доступною без «Скрадання». Шанс зростає до $s2%, якщо здоров'я цілі нижче за $s3%." },
    { en = "Provoked targets move towards you at $s1% increased speed.", ua = "Спровоковані цілі рухаються до тебе на $s1% швидше." },
    { en = "Blade Dance now reduces targets' healing received by $356608s1% for $356608d.", ua = "«Танець клинків» тепер зменшує зцілення, яке отримують цілі, на $356608s1% протягом $356608d." },
    { en = "Your next Imp, Voidwalker, Incubus, Succubus, Felhunter, or Felguard Summon spell is free and has its casting time reduced by $s1%.", ua = "Твоє наступне закляття прикликання біса, блукача Порожнечі, інкуба, сукуба, гончака Скверни або вартового Скверни не коштує нічого, а час його творення скорочено на $s1%." },
    { en = "$?s137039[Riptide and Lava Burst have][Lava Burst has] an additional charge.", ua = "$?s137039[Відплив і Вибух лави мають][Вибух лави має] додатковий заряд." },
    { en = "Lava Lash cooldown reduced by ${$m1/-1000}.1 sec, and if Lava Lash is used against a target affected by your Flame Shock, Flame Shock will be spread to up to $s2 nearby enemies.", ua = "Перезарядження «Хльоста лави» зменшено на ${$m1/-1000}.1 сек., а якщо «Хльост лави» влучає в ціль під дією твого «Шоку полум'я», той поширюється на щонайбільше $s2 ворогів поблизу." },
    { en = "Lava Lash and Sundering increases the damage of Flame Shock on its target by $334168s1% for $334168d.", ua = "«Хльост лави» та «Розкол» збільшують шкоду «Шоку полум'я» на своїй цілі на $334168s1% на $334168d." },
    { en = "Reduces the target's movement speed by $s1% for $d.\n\n\n\n|cFF8282FFCurses: A warlock can only have one Curse active per target.|r", ua = "Зменшує швидкість пересування цілі на $s1% впродовж $d.\n\n\n\n|cFF8282FFПрокляття: чорнокнижник може мати лише одне Прокляття активним на ціль.|r" },
    { en = "Chain Lightning now jumps to $s2 additional targets and deals $s1% increased damage.", ua = "«Ланцюгова блискавка» тепер перестрибує на $s2 додаткових цілей і завдає на $s1% більше шкоди." },
    { en = "When an ability used during Sweeping Strikes damages a second target, your next Cleave or Whirlwind deals $334783s1% increased damage, stacking up to $334783u times.", ua = "Коли здібність, використана під час «Розмашистих ударів», завдає шкоди другій цілі, твоє наступне «Розсікання» або «Вихор» завдає на $334783s1% більше шкоди. Складається до $334783u разів." },
    { en = "Rampage increases your haste by $s1% for $335082d. Multiple instances of this effect may overlap.", ua = "«Буйство» збільшує твій поспіх на $s1% на $335082d. Кілька екземплярів цього ефекту можуть діяти одночасно." },
    { en = "A word of madness haunts the target's mind, dealing $s1 Shadow damage instantly plus an additional $o3 Shadow damage over $d. Heals you for ${$e1*100}% of damage dealt.\n\n\n\nWhen reapplied to a target, all remaining damage is added to the new effect.", ua = "Слово божевілля переслідує розум цілі, миттєво завдаючи $s1 од. шкоди Тінню плюс додаткові $o3 од. шкоди Тінню протягом $d. Зцілює вас на ${$e1*100}% завданої шкоди.\n\n\n\nКоли ефект накладається на ціль повторно, уся залишкова шкода додається до нового ефекту." },
    { en = "Immolation Aura damage increases the duration of your Fiery Brand and Sigil of Flame by ${$s1/1000}.2 sec.", ua = "Шкода «Аури спалення» подовжує тривалість твого «Вогняного тавра» та «Печаті полум'я» на ${$s1/1000}.2 сек." },
    { en = "Reduces the mana cost of $?a137033[Purify Disease][Purify] and Mass Dispel by $s1% and Dispel Magic by $s2%.", ua = "Зменшує витрату мани $?a137033[«Очищення від хвороби»][«Очищення»] і «Масового розвіювання» на $s1%, а «Розвіювання магії» — на $s2%." },
    { en = "Voidform generates $s1 Insanity and increases your spell damage by an additonal $s2%.", ua = "«Форма Порожнечі» породжує $s1 од. безумства і додатково збільшує шкоду твоїх заклять на $s2%." },
    { en = "Shadow Word: Madness conjures Shadowy Apparitions that float towards all targets afflicted by your Vampiric Touch for $413231s1 Shadow damage.", ua = "«Слово тіні: Безумство» прикликає тіньові привиддя, що линуть до всіх цілей під дією твого «Вампірського дотику», завдаючи $413231s1 шкоди від тіні." },
    { en = "Your healing on allies with your Renew is increased by $s1%.", ua = "Твоє зцілення союзників, на яких діє твоє Оновлення, збільшено на $s1%." },
    { en = "Direct damage you deal to enemies affected by $?s461264[Nether Flux][Touch of the Magi], causes an explosion that deals $?s461264[${$342232s1*$s3}][$342232s1] Arcane damage to all nearby enemies. Deals reduced damage beyond $s1 targets.", ua = "Пряма шкода, яку ви завдаєте ворогам, ураженим $?s461264[Потоком Нижнього світу][Дотиком магів], спричиняє вибух, що завдає $?s461264[${$342232s1*$s3}][$342232s1] шкоди Арканом усім ворогам поблизу. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "Alters the fabric of time, returning you to your current location and health when cast a second time, or after ${$110909d+$s3} sec. Effect negated by long distance or death.", ua = "Змінює тканину часу: повертає тебе на поточне місце з поточним здоров'ям при повторному прочитанні або через ${$110909d+$s3} сек. Ефект скасовується великою відстанню чи смертю." },
    { en = "Reduces the cooldown of $?a1244090[Temporal Realignment][Alter Time] by ${$s1/-1000} sec.", ua = "Зменшує перезарядження $?a1244090[«Темпорального вирівнювання»][«Зміни часу»] на ${$s1/-1000} сек." },
    { en = "Fire Blast damage increased by $s2%. \n\n\n\nYour direct damage spells reduce the cooldown of Fire Blast by ${$s1/-1000}.2 sec.", ua = "Шкода від Вогняного вибуху збільшена на $s2%. \n\n\n\nВаші закляття прямої шкоди зменшують перезарядження Вогняного вибуху на ${$s1/-1000}.2 сек." },
    { en = "${$s1/10}.1% of your Fire damage shields you, up to a maximum of ${$MHP*$s2/100}.\n\n\n\nShield and maximum values are doubled while Fiery Brand is active.", ua = "${$s1/10}.1% вашої шкоди вогнем перетворюється на щит, до максимум ${$MHP*$s2/100}.\n\n\n\nЗначення щита та максимуму подвоюються, поки активне Полум'яне тавро." },
    { en = "After entering Stealth, your next combo point generating ability generates full combo points.", ua = "Після входу в скрадання твоя наступна здібність, що генерує очки комбо, генерує їх повну кількість." },
    { en = "Frost Nova duration is increased by ${$s1/1000} sec.", ua = "Тривалість «Морозної нови» збільшена на ${$s1/1000} сек." },
    { en = "Chaos Strike damage increased by $s1%.", ua = "Шкода «Удару хаосу» збільшена на $s1%." },
    { en = "Soul Cleave deals $s1% increased damage to your primary target.", ua = "«Розсічення душ» завдає основній цілі на $s1% більше шкоди." },
    { en = "Go Berserk for $d. While Berserk:\n\n\n\nGenerate $343216s1 combo $lpoint:points; every $t1 sec. Combo point generating abilities generate $s2 additional combo $lpoint:points;. Finishing moves restore up to $405189u combo points generated over the cap.\n\n\n\nAll attack and ability damage is increased by $s3%.", ua = "Впадає в Шал на $d. Поки триває Шал:\n\n\n\nСтворює $343216s1 комбо-$lочко:очка; кожні $t1 с. Здібності, що створюють комбо-очки, дають $s2 додаткових комбо-$lочко:очка;. Завершальні прийоми відновлюють до $405189u комбо-очок, створених понад межу.\n\n\n\nУсю шкоду атак і здібностей збільшено на $s3%." },
    { en = "All Fire damage dealt increased by $s1%.", ua = "Уся завдана шкода вогнем збільшена на $s1%." },
    { en = "Mend Pet heals for an additional ${$m1*$136d/$136t1}% of your pet's health over its duration, and has a $s2% chance to dispel a magic effect each time it heals your pet.", ua = "Лікування улюбленця додатково відновлює ${$m1*$136d/$136t1}% здоров'я твого улюбленця протягом дії та має $s2% шансу розвіяти магічний ефект щоразу, коли зцілює улюбленця." },
    { en = "When $?c3[Muzzle][Counter Shot] interrupts a cast, gain $459976s1 Focus.", ua = "Коли $?c3[Намордник][Постріл-перебивка] перериває прочитання, ви отримуєте $459976s1 Зосередження." },
    { en = "The cooldown of Tar Trap and Freezing Trap is reduced by ${$m1/-1000}.1 sec.", ua = "Перезарядження «Смоляної пастки» та «Морозильної пастки» зменшено на ${$m1/-1000}.1 сек." },
    { en = "$?c2[Aimed Shot][Kill Command] has a $?c1[$s2]?c2[$s1][$s3]% chance to grant Deathblow.\n\n\n\n$@spellicon378770 $@spellname378770\n\nThe cooldown of $?a466932[Black Arrow][Kill Shot] is reset. $@spellaura378770", ua = "$?c2[Прицільний постріл][Наказ убити] має $?c1[$s2]?c2[$s1][$s3]% шанс дарувати Смертельний удар.\n\n\n\n$@spellicon378770 $@spellname378770\n\nПерезарядження $?a466932[Чорної стріли][Добивального пострілу] скидається. $@spellaura378770" },
    { en = "Rupture the soul of your enemy, dealing $s1 Shadowfrost damage and causing the foe to take $1241521s1% increased damage from your diseases and minions for $1241521d.\n\n\n\nOnly usable on enemies below $s2% maximum health.\n\n\n\n|cFFFFFFFFConsumes up to $s3 available $lcharge:charges; to cast Putrefy.|r", ua = "Розриває душу вашого ворога, завдаючи $s1 тіньоморозної шкоди й змушуючи ворога отримувати на $1241521s1% більше шкоди від ваших хвороб і прислужників на $1241521d.\n\n\n\nЗастосовується лише до ворогів, у яких менше ніж $s2% максимального здоров'я.\n\n\n\n|cFFFFFFFFСпоживає до $s3 доступних $lзаряду:зарядів;, щоб застосувати Гниття.|r" },
    { en = "When Eye Beam finishes fully channeling, your Haste is increased by an additional $343312s1% for $343312d.", ua = "Коли «Промінь ока» повністю завершує підтримання, твій поспіх додатково зростає на $343312s1% на $343312d." },
    { en = "Unleash a heavenly blast around the target, dealing $343721s2 Holy damage to all enemies nearby, and call down a hammer that slowly falls from the sky upon the target. \n\n\n\nAfter $d, they suffer $s2% of the Holy damage you dealt to all targets affected by the initial blast during that time.", ua = "Вивільняє небесний вибух навколо цілі, завдаючи $343721s2 од. шкоди Світлом усім ворогам поблизу, і прикликає молот, що повільно падає з небес на ціль. \n\n\n\nЧерез $d ціль зазнає $s2% шкоди Світлом, яку ви за цей час завдали всім цілям, що потрапили під початковий вибух." },
    { en = "During the first $343648d of every Eclipse, Shooting Stars fall $s1% more often.", ua = "Протягом перших $343648d кожного затемнення «Падучі зорі» падають на $s1% частіше." },
    { en = "When activated, Yu'lon and Chi-Ji apply Chi Cocoons to $406139s3 targets within $406139r yds, absorbing $<newshield> damage for $406139d.\n\n\n\nChi-Ji grants $s4 stacks of Teachings of the Monastery when invoked.\n\n\n\nYu'lon reduces the cast speed of Enveloping Mist by $322118s6%.", ua = "Коли активовано, Юй'лон і Чі-Цзі огортають $406139s3 цілей у радіусі $406139r м у кокони ці, що поглинають $<newshield> шкоди протягом $406139d.\n\n\n\nЧі-Цзі дарує $s4 нашарувань «Настанов монастиря», коли його прикликано.\n\n\n\nЮй'лон зменшує швидкість прочитання «Огортального туману» на $322118s6%." },
    { en = "Stormstrike has a $s1% chance to strike the target an additional time for $s2% of normal damage. This effect can chain off of itself.", ua = "«Удар бурі» має $s1% шансу вразити ціль іще раз, завдавши $s2% звичайної шкоди. Цей ефект може спрацьовувати ланцюгом сам від себе." },
    { en = "Reduces the cooldown of Paralysis by ${$abs($s0/1000)} sec and the cooldown of Leg Sweep by ${$s2/-1000} sec.", ua = "Зменшує перезарядження «Паралічу» на ${$abs($s0/1000)} сек., а перезарядження «Підсічки» — на ${$s2/-1000} сек." },
    { en = "Mangle and Maul cause an Infected Wound in the target, reducing their movement speed by $345209s1% for $345209d.", ua = "«Шматування» і «Трощення» залишають на цілі заражену рану, що зменшує її швидкість руху на $345209s1% протягом $345209d." },
    { en = "The Hunt and Vengeful Retreat increase the damage of your next Fel Rush or Felblade by $s2%. Lasts $347462d.", ua = "«Полювання» та «Мстивий відступ» збільшують шкоду твого наступного «Ривка Скверни» чи «Клинка Скверни» на $s2%. Триває $347462d." },
    { en = "Interrupt an enemy's spellcasting and prevent any spell from that school of magic from being cast for $d.", ua = "Перериває творення закляття ворога й не дає творити закляття цієї школи магії протягом $d." },
    { en = "Interrupting a spell with Wind Shear reduces all spell damage taken by $355634s1% for $355634d.", ua = "Переривання закляття «Зрізом вітру» зменшує всю отримувану шкоду від заклять на $355634s1% на $355634d." },
    { en = "Inhale, gathering the power of the Dream. Release to exhale, healing yourself and $s1 injured allies in a $s3 yd cone in front of you for ${$355941s3+$355941s1*$<sOneTick>}.\n\n\n\n|cFFFFFFFFI:|r   Heals $355941s3 instantly and ${$355941s1*$<sOneTick>} over $<sOneDur> sec.\n\n\n\n|cFFFFFFFFII:|r  Heals ${$355941s3+$355941s1*2} instantly and ${$355941s1*$<sTwoTick>} over $<sTwoDur> sec.\n\n\n\n|cFFFFFFFFIII:|r Heals ${$355941s3+$355941s1*4} instantly and ${$355941s1*$<sThreeTick>} over $<sThreeDur> sec.", ua = "Вдихаєте, збираючи силу Сну. Видихаєте, зцілюючи себе та $s1 поранених союзників у конусі завдовжки $s3 м перед вами на ${$355941s3+$355941s1*$<sOneTick>}.\n\n\n\n|cFFFFFFFFI:|r   Зцілює $355941s3 миттєво та ${$355941s1*$<sOneTick>} протягом $<sOneDur> сек.\n\n\n\n|cFFFFFFFFII:|r  Зцілює ${$355941s3+$355941s1*2} миттєво та ${$355941s1*$<sTwoTick>} протягом $<sTwoDur> сек.\n\n\n\n|cFFFFFFFFIII:|r Зцілює ${$355941s3+$355941s1*4} миттєво та ${$355941s1*$<sThreeTick>} протягом $<sThreeDur> сек." },
    { en = "Death's Advance, Death and Decay, and Death Grip have $s1 additional charge.", ua = "«Поступ смерті», «Смерть і тлін» та «Хватка смерті» отримують $s1 додатковий заряд." },
    { en = "Stretch time around an ally for the next $d, causing $s1% of damage they would take to instead be dealt over $d.$?s363899[\n\n\n\nHealing a target under the effects of Time Dilation clears a portion of the delayed damage.][]", ua = "Розтягуєш час навколо союзника на наступні $d, через що $s1% шкоди, яку він мав би отримати, натомість завдається протягом $d.$?s363899[\n\n\n\nЗцілення цілі під дією Сповільнення часу прибирає частину відкладеної шкоди.][]" },
    { en = "Lob a ball of flame, dealing $357212s1 Fire damage to your target and all enemies within $357212A1 yds.", ua = "Жбурляє вогняну кулю, що завдає $357212s1 шкоди вогнем твоїй цілі та всім ворогам у радіусі $357212A1 м." },
    { en = "Conjure a path of shifting stone towards the target location, rooting enemies for $355689d. Damage may cancel the effect.", ua = "Створює смугу зсувного каміння до вказаного місця, знерухомлюючи ворогів на $355689d. Шкода може скасувати ефект." },
    { en = "Focus your energies to release a salvo of pure magic, dealing $<dmg> Spellfrost damage to an enemy. Damages additional enemies within $s1 yds when empowered.\n\n\n\n|cFFFFFFFFI:|r   Damages $?s375757[2 enemies][1 enemy].\n\n\n\n|cFFFFFFFFII:|r  Damages $?s375757[4 enemies][2 enemies].\n\n\n\n|cFFFFFFFFIII:|r Damages $?s375757[6 enemies][3 enemies].", ua = "Зосереджуєш свою енергію, щоб випустити залп чистої магії, завдаючи ворогові $<dmg> шкоди чароморозом. У підсиленні завдає шкоди додатковим ворогам у межах $s1 м.\n\n\n\n|cFFFFFFFFI:|r   Завдає шкоди $?s375757[2 ворогам][1 ворогу].\n\n\n\n|cFFFFFFFFII:|r  Завдає шкоди $?s375757[4 ворогам][2 ворогам].\n\n\n\n|cFFFFFFFFIII:|r Завдає шкоди $?s375757[6 ворогам][3 ворогам]." },
    { en = "Emerald Blossom sends out $s1 flying $Lseedling:seedlings; when it bursts, plus up to $s3 additional seedlings if Emerald Blossom heals fewer than $355916s2 allies.\n\n\n\nSeedlings each heal an ally up to $s2 yds away for $361361s1.", ua = "Смарагдовий цвіт випускає $s1 летючих $Lпаросток:паростки;, коли розривається, плюс до $s3 додаткових паростків, якщо Смарагдовий цвіт зцілює менше ніж $355916s2 союзників.\n\n\n\nКожен паросток зцілює союзника на відстані до $s2 м на $361361s1." },
    { en = "Take in a deep breath and fly to the targeted location, healing all allies in your path for $363502s2 immediately, and $363502o1 over $363502d, reduced beyond $s8 targets.\n\n\n\nRemoves all root effects. You are immune to movement impairing and loss of control effects.\n\n\n\nDamage taken while you are flying is absorbed, up to $s1% of your maximum health.", ua = "Робите глибокий вдих і летите до обраного місця, миттєво зцілюючи всіх союзників на своєму шляху на $363502s2 та на $363502o1 протягом $363502d, зі зменшенням після $s8 цілей.\n\n\n\nЗнімає всі ефекти знерухомлення. Ви несприйнятливі до ефектів сповільнення пересування та втрати контролю.\n\n\n\nШкода, отримана під час польоту, поглинається, аж до $s1% вашого максимального здоров'я." },
    { en = "Carve a deathmark into an enemy, dealing $o1 Bleed damage and restoring ${$s3*8} Energy to you over $d. Damage dealt to the target by your Garrote, Rupture, and Lethal Poisons is increased by $s2%.\n\n\n\nEach time you apply a Lethal Poison to the target, apply it twice.", ua = "Вирізаєте на ворогові мітку смерті, завдаючи $o1 шкоди від кровотечі й відновлюючи вам ${$s3*8} енергії протягом $d. Шкода, яку ви завдаєте цілі «Гароттою», «Розривом» і Смертельними отрутами, збільшена на $s2%.\n\n\n\nЩоразу, коли ви накладаєте на ціль Смертельну отруту, накладайте її двічі." },
    { en = "Disorient an enemy for $d, causing them to sleep walk towards you. Damage has a chance to awaken them.", ua = "Дезорієнтує ворога на $d, змушуючи його сновидою брести до тебе. Шкода має шанс розбудити його." },
    { en = "Protect an ally with $?s406907[][$n ]explosive dragonscales, increasing their Armor by $<perc>% of your own.\n\n\n\nMelee attacks against the target cause 1 scale to explode, dealing $<dmg> Volcanic damage to enemies near them. This damage can only occur every few sec.\n\n\n\nBlistering Scales can only be placed on one target at a time. Casts on your enemy's target if they have one.", ua = "Захищаєш союзника $?s406907[][$n ]вибуховими драконячими лусками, підвищуючи його Броню на $<perc>% від твоєї власної.\n\n\n\nАтаки ближнього бою по цілі змушують 1 луску вибухнути, завдаючи $<dmg> вулканічної шкоди ворогам поблизу неї. Ця шкода може траплятися лише раз на кілька секунд.\n\n\n\nПекучу луску можна накласти лише на одну ціль за раз. Накладається на ціль твого ворога, якщо вона в нього є." },
    { en = "Fly to an ally and heal them for $361195s1, or heal yourself for the same amount.", ua = "Підлети до союзника і зціли його на $361195s1 або зціли себе на стільки ж." },
    { en = "Each cast of a Bronze spell causes your next empower spell to reach maximum level in $s1% less time, stacking up to $362877u times.", ua = "Кожне прочитання бронзового закляття дозволяє твоєму наступному підсилюваному закляттю досягти максимального рівня на $s1% швидше. Складається до $362877u разів." },
    { en = "Rewind $?s376210[${$s3/2}%][$s3%] of damage taken in the last $s2 seconds by all allies within $a1 yds. Always heals for at least $<min>.\n\n\n\nHealing increased by $s4% when not in a raid.", ua = "Перемотуєш $?s376210[${$s3/2}%][$s3%] шкоди, отриманої за останні $s2 секунд усіма союзниками в межах $a1 м. Завжди зцілює щонайменше на $<min>.\n\n\n\nЗцілення підвищене на $s4% поза рейдом." },
    { en = "Reinforce your scales, reducing damage taken by $s1% $?s374348[and causing you to be healed over $374349d equal to the damage it prevented][]. Lasts $d.", ua = "Зміцнює вашу луску, знижуючи отримувану шкоду на $s1% $?s374348[і зцілюючи вас протягом $374349d на величину відверненої шкоди][]. Триває $d." },
    { en = "Wrap an ally with temporal energy, healing them for $s1 and causing your next healing spell to cast an additional time on that ally at ${$ceil($s2)}% of normal healing. Essence spells cannot be Echoed.", ua = "Огортаєш союзника часовою енергією, зцілюючи його на $s1, і твоє наступне зцілювальне закляття спрацьовує на цього союзника ще раз із ${$ceil($s2)}% звичайного зцілення. Закляття есенції не можуть мати Відлуння." },
    { en = "Expend all of your current mana to annihilate your enemy target and nearby enemies for up to $?a457521[${$s1*$s2*($457521s1/100+1)}][${$s1*$s2}] Arcane damage based on Mana spent. Deals reduced damage beyond $s3 targets.\n\n\n\nFor the next $365362d, your Mana regeneration is increased by $365362s3% and spell damage is increased by $365362s1%.\n\n\n\n|cFFFFFFFFGenerates Clearcasting.|r", ua = "Витрачає всю вашу поточну ману, щоб знищити ворожу ціль і ворогів поруч, завдаючи до $?a457521[${$s1*$s2*($457521s1/100+1)}][${$s1*$s2}] арканної шкоди залежно від витраченої мани. Завдає зменшеної шкоди понад $s3 цілей.\n\n\n\nПротягом наступних $365362d ваше відновлення мани зростає на $365362s3%, а шкода заклять — на $365362s1%.\n\n\n\n|cFFFFFFFFНадає «Ясність думки».|r" },
    { en = "Expunge toxins affecting an ally, removing all Poison effects.", ua = "Викоріни токсини, що вражають союзника, знявши з нього всі ефекти отрути." },
    { en = "Hover gains $s1 additional charge.", ua = "Ширяння отримує $s1 додатковий заряд." },
    { en = "Living Flame deals $361500o2 damage over $361500d to enemies, or restores $361509o2 health to allies over $361509d. Stacks $361509u times.", ua = "«Живе полум'я» завдає ворогам $361500o2 шкоди протягом $361500d або відновлює союзникам $361509o2 здоров'я протягом $361509d. Сумується до $361509u разів." },
    { en = "Reverse an ally's injuries, $?s378196[instantly healing them for $378196s1% of damage taken in the last $378196s2 sec and an additional][healing them for] $o1 over $d.\n\n\n\nWhen Reversion critically heals, its duration is extended by 2 sec, up to a maximum of ${2*$<cap>} sec.", ua = "Обертаєш ушкодження союзника навспак, $?s378196[миттєво зцілюючи його на $378196s1% шкоди, отриманої за останні $378196s2 с, і додатково на][зцілюючи його на] $o1 протягом $d.\n\n\n\nКоли Реверсія зцілює критично, її тривалість подовжується на 2 с, але не більше ніж до ${2*$<cap>} с." },
    { en = "$s1% of Flash Heal healing on other targets also heals you.", ua = "$s1% зцілення від «Швидкого зцілення» на інших цілях зцілює також і тебе." },
    { en = "When you or an ally fall below $s1% health, a version of yourself enters your timeline and heals them for $<amount>. Your alternate self continues healing for $368415d before returning to their timeline.\n\n\n\nMay only occur once every $s2 sec.", ua = "Коли ви або союзник опускаєтеся нижче $s1% здоров'я, версія вас входить у вашу часову лінію та зцілює ціль на $<amount>. Ваше альтернативне «я» продовжує зцілювати протягом $368415d, перш ніж повернутися до своєї часової лінії.\n\n\n\nМоже статися лише раз на $s2 сек." },
    { en = "Wing Buffet's cooldown is reduced by ${$s1/-60000} min.", ua = "Перезарядження Удару крилами скорочено на ${$s1/-60000} хв." },
    { en = "Pyre has a $s1% chance to flare up and explode again on a nearby target.", ua = "«Погребальне багаття» має $s1% шанс спалахнути й вибухнути ще раз на сусідній цілі." },
    { en = "Living Flame has a $s1% chance, and Reversion has a $s2% chance to make your next Essence ability free.$?s375722[ Stacks $359618u times.][]", ua = "Жива полум'я має $s1% шанс, а Зворот має $s2% шанс зробити вашу наступну здібність есенції безкоштовною.$?s375722[ Накопичується до $359618u разів.][]" },
    { en = "Redirect your excess magic to a friendly healer for $d. When you cast an empowered spell, you restore ${$372571s1/100}.2% of their maximum mana per empower level. Limit 1.", ua = "Перенаправляє твою надлишкову магію дружньому цілителю на $d. Коли ти твориш посилене закляття, цілитель відновлює ${$372571s1/100}.2% своєї максимальної мани за кожен рівень посилення. Не більше 1 цілі." },
    { en = "After casting $411288s2 Pyres, your next Pyre will explode into a Firestorm.\n\n\n\n$@spellicon368847 $@spellname368847\n\n$@spelldesc368847", ua = "Після застосування $411288s2 Багать ваше наступне Багаття вибухне Вогняною бурею.\n\n\n\n$@spellicon368847 $@spellname368847\n\n$@spelldesc368847" },
    { en = "Increases your maximum Essence to $<max>.", ua = "Збільшує ваш максимум есенції до $<max>." },
    { en = "Azure Strike damages $s1 additional $Lenemy:enemies;.", ua = "Лазуровий удар завдає шкоди $s1 $lдодатковому ворогу:додатковим ворогам;." },
    { en = "Disintegrate channels $s1% faster$?c3[ and Eruption's cast time is reduced by $s3%][].", ua = "Дезінтеграція спрямовується на $s1% швидше$?c3[, а час прочитання Виверження зменшено на $s3%][]." },
    { en = "Fire Breath causes your next Living Flame to strike 1 additional target per empower level.", ua = "Вогняний подих змушує твоє наступне Живе полум'я вражати 1 додаткову ціль за кожен рівень посилення." },
    { en = "Casting Emerald Blossom or Verdant Embrace reduces the cast time of your next Living Flame by $375583s1%.", ua = "Творіння Смарагдового цвіту чи Зелених обіймів скорочує час творіння твого наступного Живого полум'я на $375583s1%." },
    { en = "Every other Emerald Blossom has a $s1% chance for one of your Fluttering Seedlings to grow into a new Emerald Blossom.", ua = "Кожен другий Смарагдовий цвіт має $s1% шансу, що один із твоїх Тріпотливих паростків виросте в новий Смарагдовий цвіт." },
    { en = "Your Blue damage increases the damage of your next Pyre by $370454s1%, stacking $370454u times.", ua = "Твоя шкода від синіх заклять збільшує шкоду твого наступного Вогнища на $370454s1%; складається до $370454u разів." },
    { en = "Causes your next ${$s1*3} helpful spells to be duplicated and stored in a time lock. You may reactivate Stasis any time within $s2 sec to quickly unleash their magic.", ua = "Твої наступні ${$s1*3} корисні закляття дублюються і зберігаються в часовому замку. Можеш повторно активувати Стазис будь-коли протягом $s2 сек., щоб швидко вивільнити їхню магію." },
    { en = "Compress time to make your next empowered spell cast instantly at its maximum empower level.", ua = "Стискає час, щоб твоє наступне посилюване закляття створилося миттєво на максимальному рівні посилення." },
    { en = "While in Bear Form, you are healed for $s1% of all Arcane damage done.", ua = "У подобі ведмедя ти зцілюєшся на $s1% від усієї завданої арканної шкоди." },
    { en = "Swoop to an ally and fly with them to the target location. Clears movement impairing effects from you and your ally.", ua = "Кидається до союзника й летить із ним до вказаного місця. Знімає з тебе та твого союзника ефекти, що уповільнюють рух." },
    { en = "While in Bear Form, you deal $s1% increased Arcane damage.", ua = "У подобі ведмедя ти завдаєш на $s1% більше арканної шкоди." },
    { en = "Deep Breath reduces the Essence costs of your next $s1 Disintegrates and Pyres by $411055s1. Stacks up to $411055U times.", ua = "Глибокий подих зменшує вартість в есенції ваших наступних $s1 застосувань Дезінтеграції та Вогнища на $411055s1. Накопичується до $411055U разів." },
    { en = "Enemies affected by Fire Breath's damage over time effect take $s1% increased damage from your Red spells.", ua = "Вороги під дією ефекту періодичної шкоди «Вогняного подиху» отримують на $s1% більше шкоди від твоїх червоних заклять." },
    { en = "Disintegrate has a $s2% chance each time it deals damage to launch a level 1 Eternity Surge at $s1% power.", ua = "Щоразу, коли Дезінтеграція завдає шкоди, є $s2% шанс випустити Сплеск вічності 1-го рівня з $s1% сили." },
    { en = "Living Flame deals $s2% increased damage and healing and its cast time is reduced by ${$s1/-1000}.1 sec.", ua = "«Живе полум'я» завдає на $s2% більше шкоди та зцілення, а час його творення скорочено на ${$s1/-1000}.1 сек." },
    { en = "Casting an empower spell increases your Essence regeneration rate by $376850s1% for $376850d.", ua = "Творіння посилюваного закляття пришвидшує відновлення есенції на $376850s1% на $376850d." },
    { en = "Your damaging critical strikes deal ${$s1+200}% damage instead of the usual 200%.", ua = "Твої критичні удари завдають ${$s1+200}% шкоди замість звичайних 200%." },
    { en = "Casting an empower spell increases the damage of your next $386353u spells of the same color by $386353s1% within $386353d.", ua = "Творіння посилюваного закляття збільшує шкоду твоїх наступних $386353u заклять того самого кольору на $386353s1% протягом $386353d." },
    { en = "Emerald Blossom heals $s1 additional allies.", ua = "«Смарагдовий цвіт» зцілює додатково $s1 союзників." },
    { en = "Rescue increases movement speed by $370889s2% and allows spells to be cast while moving for $370889d.", ua = "«Порятунок» збільшує швидкість руху на $370889s2% і дозволяє творити закляття на ходу протягом $370889d." },
    { en = "Charge to your target, striking them for $370966s1 Chaos damage, rooting them in place for $370970d and inflicting $370969o1 Chaos damage over $370969d to up to $370967s2 enemies in your path.", ua = "Мчиш до цілі, завдаючи їй $370966s1 шкоди хаосу й знерухомлюючи її на $370970d, а також завдаєш $370969o1 шкоди хаосу протягом $370969d щонайбільше $370967s2 ворогам на своєму шляху." },
    { en = "$?s403631[Breath of Eons][Deep Breath] stuns enemies for $372245d.", ua = "$?s403631[Подих еонів][Глибокий подих] приголомшує ворогів на $372245d." },
    { en = "Deep Breath's damage is increased by $s1%.", ua = "Шкода Глибокого подиху збільшена на $s1%." },
    { en = "The critical strike chance of your spells is increased by $s1%.", ua = "Шанс критичного удару твоїх заклять збільшено на $s1%." },
    { en = "Dream Breath healing is increased by $s1%.", ua = "Зцілення «Подиху сну» збільшено на $s1%." },
    { en = "Fire Breath and Deep Breath heal $s3 nearby injured allies for $s1% of damage done to up to $s2 targets, split evenly among them.", ua = "Вогняний подих і Глибокий подих зцілюють $s3 поранених союзників поруч на $s1% шкоди, завданої щонайбільше $s2 цілям, розділяючи зцілення порівну між ними." },
    { en = "You may reactivate $?s359816[Dream Flight and ][]$?s403631[Breath of Eons][Deep Breath] within $s1 sec after landing to travel back in time to your takeoff location.", ua = "Ви можете повторно активувати $?s359816[Політ снів та ][]$?s403631[Подих еонів][Глибокий подих] протягом $s1 сек. після приземлення, щоб повернутися в часі до місця зльоту." },
    { en = "Every $s2 Rage you spend causes a burst of restorative energy, healing up to $s3 allies within $371982A1 yds for $371982s1.", ua = "Кожні $s2 витраченої люті спричиняють сплеск відновної енергії, що зцілює до $s3 союзників у радіусі $371982A1 м на $371982s1." },
    { en = "Let out a bone-shaking roar at enemies in a cone in front of you, increasing the duration of crowd controls that affect them by $s2% in the next $d.$?s374346[\n\n\n\nRemoves $s1 Enrage effect from each enemy.][]", ua = "Видаєш моторошний рев на ворогів у конусі перед собою, подовжуючи на $s2% тривалість ефектів контролю, що діють на них, протягом наступних $d.$?s374346[\n\n\n\nЗнімає $s1 ефект Лютування з кожного ворога.][]" },
    { en = "When you take non-periodic damage, you have a chance to cause your next Regrowth to heal for an additional $372152s4%, and to be instant, free, and castable in all forms for $372152d.", ua = "Коли ти отримуєш неперіодичну шкоду, є шанс, що твоє наступне «Відростання» зцілить додатково на $372152s4% і протягом $372152d буде миттєвим, безкоштовним і доступним у всіх подобах." },
    { en = "Disintegrate deals $s2% more damage and generates ${$372234s1*4} mana over its duration.", ua = "Дезінтеграція завдає на $s2% більше шкоди і створює ${$372234s1*4} мани за час своєї дії." },
    { en = "Increases the damage of Holy Fire by $s1%.\n\n\n\nHoly Fire deals $s3% of its initial damage to all nearby enemies within $400370A1 yards of your target. Damage reduced beyond $400370s2 targets.", ua = "Збільшує шкоду «Святого вогню» на $s1%.\n\n\n\n«Святий вогонь» завдає $s3% початкової шкоди всім ворогам поблизу в межах $400370A1 м від вашої цілі. Шкоду зменшено понад $400370s2 цілей." },
    { en = "While channeling Divine Hymn, place $s2 stacks of Prayer of Mending on up to $s3 allies within its range every ${$64843d/$64843s5}.1 sec.", ua = "Під час підтримання Божественного гімну накладає Молитву відновлення ($s2 зар.) на щонайбільше $s3 союзників у межах його дії кожні ${$64843d/$64843s5}.1 сек." },
    { en = "Store $s1% of your effective healing, up to $<cap>. Your next damaging Living Flame consumes all stored healing to increase its damage dealt.", ua = "Накопичує $s1% вашого ефективного зцілення, до $<cap>. Ваше наступне атакувальне «Живе полум'я» поглинає все накопичене зцілення, щоб збільшити завдану шкоду." },
    { en = "Echo replicates $s1% more healing.", ua = "«Відлуння» відтворює на $s1% більше зцілення." },
    { en = "Moonfire deals $s2% increased damage and also hits another nearby enemy within $279620s1 yds of the target.", ua = "«Місячний вогонь» завдає на $s2% більше шкоди й уражає ще одного ворога поблизу, у межах $279620s1 м від цілі." },
    { en = "Holy Word: Chastise causes your next $s1 casts of Holy Fire to be instant, cost no mana, and incur no cooldown.\n\n\n\nRefreshing Holy Fire on a target now extends its duration by $14914d.", ua = "«Святе слово: Покара» робить ваші наступні $s1 прочитань «Святого вогню» миттєвими, без витрати мани й без перезарядження.\n\n\n\nОновлення «Святого вогню» на цілі тепер подовжує його тривалість на $14914d." },
    { en = "Maul and Raze deal $s1% increased damage.", ua = "«Трощення» і «Руйнування» завдають на $s1% більше шкоди." },
    { en = "Increases the damage and radius of Thrash by $s1%.", ua = "Збільшує шкоду та радіус «Молотіння» на $s1%." },
    { en = "Frenzied Regeneration heals over ${$s1/1000}.1 additional sec and casts Rejuvenation and Regrowth on you at $s3% effectiveness.", ua = "«Шалена регенерація» зцілює додатково ${$s1/1000}.1 сек. і накладає на тебе «Омолодження» й «Відростання» з $s3% ефективності." },
    { en = "Each successive Penance bolt during a channel deals $s1% increased damage and healing.", ua = "Кожен наступний снаряд «Покути» під час спрямування завдає на $s1% більше шкоди та зцілення." },
    { en = "Mind Blast has a $s1% chance to grant Power of the Dark Side and deals $s2% additional damage.", ua = "«Вибух розуму» має $s1% шансу дарувати «Силу темного боку» та завдає на $s2% більше шкоди." },
    { en = "Pain Suppression also heals your target for $372994s1% of their maximum health and applies Atonement.", ua = "«Придушення болю» також зцілює твою ціль на $372994s1% її максимального здоров'я та накладає «Спокуту»." },
    { en = "Shadow Word: Pain deals $s1% additional damage and spreads to $s2 additional $Ltarget:targets; when you cast Penance to its target.", ua = "Тіньове слово: Біль завдає на $s1% більше шкоди та поширюється на $s2 додаткову $Lціль:цілі; коли ви застосовуєте Покуту на його цілі." },
    { en = "Pain Suppression gains an additional charge.\n\n\n\nPower Word: Shield reduces the cooldown of Pain Suppression by ${$abs($s2/1000)} sec.", ua = "«Притлумлення болю» отримує додатковий заряд.\n\n\n\n«Слово сили: Щит» зменшує перезарядження «Притлумлення болю» на ${$abs($s2/1000)} сек." },
    { en = "Atonements granted by Power Word: Shield last an additional $s1 sec.", ua = "«Спокути», надані «Словом сили: Щит», тривають на $s1 сек. довше." },
    { en = "Atonement heals for $s1% more when activated by Shadow spells.", ua = "«Спокута» зцілює на $s1% більше, коли її активують закляття тіні." },
    { en = "Power Word: Radiance causes your next Penance to fire $s2 additional $Lbolt:bolts;, stacking up to $373183u charges.", ua = "Слово сили: Сяйво змушує вашу наступну Покуту випустити $s2 додаткові $Lстріли:стріл;, накопичуючись до $373183u зарядів." },
    { en = "Mind Blast has a $s1% chance to make your next Shadow Word: Madness cost no Insanity and deal $373204s2% additional damage.", ua = "«Вибух розуму» має $s1% шансу зробити так, що твоє наступне «Слово тіні: Безумство» не коштуватиме безумства і завдасть на $373204s2% більше шкоди." },
    { en = "While you have Shadow Word: Pain, Shadow Word: Madness, and Vampiric Touch active on the same target, your Mind Blast, Void Torrent, Mind Flay, and Void Volley deal $s1% more damage.", ua = "Поки на одній цілі одночасно діють Слово Тіні: Біль, Слово Тіні: Безумство та Вампірський дотик, твої Вибух розуму, Потік Порожнечі, Катування розуму та Залп Порожнечі завдають на $s1% більше шкоди." },
    { en = "Increases your Leech by $s1%.", ua = "Збільшує твоє висмоктування на $s1%." },
    { en = "Shadow Word: Death deals $s1% less damage to you.", ua = "«Слово тіні: Смерть» завдає тобі на $s1% менше шкоди." },
    { en = "Verdant Embrace temporarily bonds your life with an ally, causing your healing on either partner to heal the other for $s1% of the amount. Lasts $373267d.", ua = "Зелені обійми тимчасово зв'язують твоє життя з життям союзника: коли твоє зцілення діє на одного з вас, інший теж зцілюється на $s1% від цієї суми. Тривалість: $373267d." },
    { en = "After conjuring Shadowy Apparitions, gain a stack of Idol of Yogg-Saron. At $s1 stacks, you summon a Thing from Beyond that casts Void Spike at nearby enemies for $373277d.\n\n\n\n$@spellicon373279 $@spellname373279\n\n$@spelldesc373279", ua = "Створивши Тіньові з'яви, ви отримуєте заряд Ідола Йоґґ-Сарона. На $s1 зарядах ви прикликаєте Істоту з Потойбіччя, яка застосовує Шпичак Порожнечі по ворогах поблизу протягом $373277d.\n\n\n\n$@spellicon373279 $@spellname373279\n\n$@spelldesc373279" },
    { en = "You create Horrific Visions when casting harmful spells on enemies.\n\n\n\nAt $s1 stacks of Horrific Visions, your target sees a nightmare, dealing $1243105s1 Shadow damage and granting you ${$1243113o1/100} Insanity over $1243113s2 sec.\n\n\n\nAt $s2 stacks, your target witnesses a vision of N'Zoth, dealing $1243106s1 Shadow damage and granting you ${$1243114o1/100} Insanity over $1243114s2 sec.", ua = "Ви створюєте «Жахливі видіння», коли творите шкідливі закляття на ворогах.\n\n\n\nПри $s1 накопиченнях «Жахливих видінь» ваша ціль бачить жахіття, що завдає $1243105s1 Тіньової шкоди й надає вам ${$1243113o1/100} Безуму протягом $1243113s2 сек.\n\n\n\nПри $s2 накопиченнях ваша ціль бачить видіння Н'Зота, що завдає $1243106s1 Тіньової шкоди й надає вам ${$1243114o1/100} Безуму протягом $1243114s2 сек." },
    { en = "While Shadowfiend, Mindbender, or Voidwraith are active, your haste is increased by $373316s1%.", ua = "Поки активний Тіньовий виплодок, Викривлювач розуму або Мара Порожнечі, твій поспіх збільшено на $373316s1%." },
    { en = "$?a137032[Penance, ][]Mind Blast and Shadow Word: Death cause your Shadowfiend, Mindbender, and Voidwraith to teleport behind your target, slashing up to $s1 nearby enemies for $<value> Shadow damage and extending their durations by ${$s2/1000}.1 sec.", ua = "$?a137032[Покута, ][]Удар розуму і Темне слово: Смерть змушують вашого Тінефіянда, Розумозгинача й Привида Порожнечі телепортуватися за спину вашій цілі, розтинаючи до $s1 ворогів поблизу й завдаючи $<value> темної шкоди та подовжуючи їхню тривалість на ${$s2/1000}.1 с." },
    { en = "Fade reduces damage you take by $373447s1%.", ua = "«Зникнення» зменшує отримувану тобою шкоду на $373447s1%." },
    { en = "Increases the maximum health gained from Desperate Prayer by $s1%.", ua = "Збільшує максимум здоров'я, що його дає «Відчайдушна молитва», на $s1%." },
    { en = "While above $s2% health, the cast time of your $?a137033[Flash Heal is]?a137032[Flash Heal and Smite are][Flash Heal, Prayer of Healing, and Smite are] reduced by $s1%.", ua = "Поки у вас понад $s2% здоров'я, час прочитання $?a137033[вашого Швидкого зцілення скорочено]?a137032[ваших Швидкого зцілення та Кари скорочено][ваших Швидкого зцілення, Молитви зцілення та Кари скорочено] на $s1%." },
    { en = "Power Infusion also grants you its effect at $s1% value when used on an ally. \n\n\n\nIf no ally is targeted, it will grant its effect at $s1% value to a nearby ally, preferring damage dealers.", ua = "«Вливання сили» також надає вам свій ефект з $s1% значення, коли застосовується на союзникові. \n\n\n\nЯкщо ціллю не обрано союзника, воно надасть свій ефект з $s1% значення найближчому союзникові, віддаючи перевагу завдавачам шкоди." },
    { en = "Dream Breath healing increased by $s1%, and Living Flame healing increased by $s2%.", ua = "Зцілення Подиху Сну посилено на $s1%, а зцілення Живого полум'я — на $s2%." },
    { en = "Send forward a vortex of temporal energy, absorbing $<shield> damage on you and any allies in its path. Absorption is reduced beyond $s2 targets.\n\n\n\nApplies Echo at $s4% effectiveness on the first $s2 allies it passes through.", ua = "Висилаєте вихор часової енергії, що поглинає $<shield> шкоди вам і будь-яким союзникам на його шляху. Поглинання зменшується після $s2 цілей.\n\n\n\nНакладає Відлуння з $s4% дієвості на перших $s2 союзників, крізь яких проходить." },
    { en = "Chains of Ice affects $s1 additional nearby enemy.", ua = "Крижані ланцюги вражають $s1 додаткового ворога поблизу." },
    { en = "Increases Leech by $s1%.", ua = "Збільшує висмоктування на $s1%." },
    { en = "Damage taken from area of effect attacks reduced by $s1%. When suffering a loss of control effect, this bonus is increased by an additional $454886s1% for $454886d.", ua = "Шкода від атак по області зменшена на $s1%. Коли ти потерпаєш від ефекту втрати контролю, цей бонус додатково збільшується на $454886s1% на $454886d." },
    { en = "Conjure an updraft to lift you and your $s3 nearest allies within $A1 yds into the air, reducing damage taken from area-of-effect attacks by $s1% and increasing movement speed by $s2% for $d.", ua = "Створює висхідний потік, що підіймає тебе і $s3 найближчих союзників у межах $A1 м у повітря, зменшуючи отримувану шкоду від атак по площі на $s1% і збільшуючи швидкість руху на $s2% на $d." },
    { en = "Cauterize an ally's wounds, removing all Bleed, Poison, Curse, and Disease effects. Heals for $s2 upon removing any effect.", ua = "Припікає рани союзника, знімаючи всі ефекти кровотечі, отрути, прокляття і хвороби. Зцілює на $s2 при знятті будь-якого ефекту." },
    { en = "Increases the effectiveness of your Runeforge effects by $s1%.", ua = "Збільшує ефективність твоїх ефектів рунокування на $s1%." },
    { en = "Increases Haste by $s1%.", ua = "Збільшує поспіх на $s1%." },
    { en = "Death Strike's cost is reduced by $?a137008[${$s5/-10}][${$s3/-10}], and its healing is increased by $?a137008[$s4%][$s1%].", ua = "Вартість Удару смерті зменшено на $?a137008[${$s5/-10}][${$s3/-10}], а його зцілення збільшено на $?a137008[$s4%][$s1%]." },
    { en = "Oppressing Roar removes $372048s1 Enrage effect from each enemy, and its cooldown is reduced by ${$s3/-1000} sec.", ua = "«Гнітючий рев» знімає з кожного ворога $372048s1 ефект шалу, а його перезарядження скорочено на ${$s3/-1000} сек." },
    { en = "Obsidian Scales surrounds you with a Renewing Blaze, causing $s1% of the damage it prevented to be healed back over $374349d.", ua = "«Обсидіанова луска» огортає тебе «Відновним полум'ям», що протягом $374349d повертає зціленням $s1% відверненої нею шкоди." },
    { en = "The cooldown of Anti-Magic Zone is reduced by ${$s1/-1000} sec and its duration is increased by ${$s2/1000} sec.", ua = "Перезарядження «Антимагічної зони» зменшено на ${$s1/-1000} сек., а її тривалість збільшено на ${$s2/1000} сек." },
    { en = "Your diseases have a chance to weaken your enemy causing your attacks against them to deal $374557s1% increased damage for $374557d.", ua = "Твої хвороби мають шанс ослабити ворога, через що твої атаки по ньому завдають на $374557s1% більше шкоди протягом $374557d." },
    { en = "Consuming a Rune has a chance to increase your Strength by $s1% for $374585d.", ua = "Витрата руни має шанс збільшити твою Силу на $s1% на $374585d." },
    { en = "When you fall below $s1% health you drain $374606s1 health from nearby enemies, the damage you take is reduced by $454871s1% and your Death Strike cost is reduced by ${$454871s2/-10} for $454871d.\n\n\n\nCan only occur every $374609d.", ua = "Коли ваше здоров'я падає нижче $s1%, ви висмоктуєте $374606s1 здоров'я з ворогів поблизу, отримувана вами шкода зменшується на $454871s1%, а вартість вашого Удару смерті зменшується на ${$454871s2/-10} на $454871d.\n\n\n\nМоже статися лише раз на $374609d." },
    { en = "Bone Shield increases your Haste by $s1% and it can stack $s2 additional times.", ua = "Кістяний щит збільшує твій Поспіх на $s1% і може накопичувати на $s2 зарядів більше." },
    { en = "Heart Strike damage increased by $s1%.", ua = "Шкода Удару в серце збільшена на $s1%." },
    { en = "When Crimson Scourge is consumed, you gain $374748s1% Versatility for $374748d.", ua = "Коли «Кармазиновий бич» витрачається, ти отримуєш $374748s1% універсальності на $374748d." },
    { en = "Bend time, allowing you and your allies within $A1 yds to cast their major movement ability once in the next $375234d, even if it is on cooldown.", ua = "Викривлює час, дозволяючи тобі й союзникам у радіусі $A1 м протягом наступних $375234d один раз ужити свою головну здібність пересування, навіть якщо вона на перезарядженні." },
    { en = "Erupt with draconic fury and exhale Pyres at $375088s1 enemies within $375088A1 yds.\n\n\n\nFor $d, Essence Burst's chance to occur is increased to $s2%$?s376888[, and you gain the maximum benefit of Mastery: Giantkiller regardless of targets' health][].", ua = "Вибухає драконячою люттю й видихає Багаття на $375088s1 ворогів у межах $375088A1 м.\n\n\n\nПротягом $d шанс спрацювання Сплеску есенції підвищений до $s2%$?s376888[, і ви отримуєте максимальну вигоду від Майстерності: Убивця велетнів незалежно від здоров'я цілей][]." },
    { en = "Obsidian Scales has an additional charge.", ua = "«Обсидіанова луска» має додатковий заряд." },
    { en = "Tail Swipe's cooldown is reduced by ${$s1/-60000} min.", ua = "Перезарядження «Змаху хвостом» скорочено на ${$s1/-60000} хв." },
    { en = "Fire Breath's damage over time lasts $s1 sec longer.", ua = "Періодична шкода Вогняного подиху триває на $s1 сек. довше." },
    { en = "Hover lasts ${$s1/1000} sec longer.", ua = "Ширяння триває на ${$s1/1000} сек. довше." },
    { en = "Essence regenerates $s1% faster.", ua = "Есенція відновлюється на $s1% швидше." },
    { en = "Landslide's cooldown is reduced by ${$s1/-1000} sec, and it can withstand $s2% more damage before breaking.", ua = "Перезарядження Зсуву скорочено на ${$s1/-1000} сек., і він витримує на $s2% більше шкоди, перш ніж зламається." },
    { en = "While above 75% health, your movement speed is increased by $s1%.", ua = "Поки твоє здоров'я вище 75%, твою швидкість руху збільшено на $s1%." },
    { en = "Magic damage taken reduced by $s1%.", ua = "Отримувана магічна шкода зменшена на $s1%." },
    { en = "Living Flame deals $s1% more damage and healing.", ua = "«Живе полум'я» завдає на $s1% більше шкоди та зцілення." },
    { en = "Hover increases your movement speed by ${$378105s1+$358267s2}% for the first $378105d.", ua = "Ширяння збільшує твою швидкість руху на ${$378105s1+$358267s2}% протягом перших $378105d." },
    { en = "Green spells restore $s1% more health.", ua = "Зелені закляття відновлюють на $s1% більше здоров'я." },
    { en = "Renewing Blaze restores you more quickly, causing damage you take to be healed back over $<newDur> sec.", ua = "«Оновлювальне полум'я» відновлює вас швидше, завдяки чому отримана вами шкода зцілюється протягом $<newDur> сек." },
    { en = "Instantly cast $?a137029[Holy Shock at $375609s2% effectiveness]?a137028[Avenger's Shield]?a137027[Judgment][Holy Shock, Avenger's Shield, or Judgment] on up to $s1 targets within $A2 yds.$?c3[\n\n\n\nDivine Toll's Judgment deals $s6% increased damage.][]$?c2[\n\n\n\nGenerates $s5 Holy Power per target hit.][]", ua = "Миттєво творить $?a137029[Святий шок з $375609s2% ефективності]?a137028[Щит месника]?a137027[Вирок][Святий шок, Щит месника або Вирок] на до $s1 цілей у межах $A2 м.$?c3[\n\n\n\nВирок від Божественного подзвону завдає на $s6% більше шкоди.][]$?c2[\n\n\n\nГенерує $s5 Святої Сили за кожну уражену ціль.][]" },
    { en = "Disintegrate and Azure Strike deal $s1% more damage.", ua = "Дезінтеграція і Лазуровий удар завдають на $s1% більше шкоди." },
    { en = "Azure Strike has a $s1% chance to cause an Essence Burst, making your next Disintegrate or Pyre cost no Essence.", ua = "«Лазуровий удар» з імовірністю $s1% спричиняє «Вибух есенції», завдяки якому твоє наступне закляття «Дезінтеграція» або «Багаття» не коштує есенції." },
    { en = "Essence Burst stacks ${$s1+1} times.", ua = "«Вибух есенції» складається до ${$s1+1} разів." },
    { en = "Fire Breath deals $s1% more damage.", ua = "Вогняний подих завдає на $s1% більше шкоди." },
    { en = "Eternity Surge hits twice as many targets.", ua = "Сплеск вічності вражає вдвічі більше цілей." },
    { en = "Shadow Word: Madness causes your Shadow Word: Pain and Vampiric Touch to deal damage $s1% faster on all targets for $393919d.", ua = "«Слово тіні: Безумство» змушує твої «Слово тіні: Біль» і «Вампірський дотик» завдавати шкоди всім цілям на $s1% швидше протягом $393919d." },
    { en = "Disintegrate reduces the remaining cooldown of your empower spells by ${$s1/-1000}.2 sec each time it deals damage.\n\n\n\nPyre reduces the remaining cooldown of your empower spells by ${$s2/-1000}.2 sec per enemy struck, up to $<pyreCap> sec.", ua = "Дезінтеграція зменшує залишковий час перезарядження ваших заклять наснаги на ${$s1/-1000}.2 сек щоразу, коли завдає шкоди.\n\n\n\nВогнище зменшує залишковий час перезарядження ваших заклять наснаги на ${$s2/-1000}.2 сек за кожного враженого ворога, аж до $<pyreCap> сек." },
    { en = "Your empower spells' maximum level is increased by 1.", ua = "Максимальний рівень твоїх підсилюваних заклять збільшено на 1." },
    { en = "Essence Burst has a $s1% chance to not be consumed.", ua = "«Вибух есенції» має $s1% шансу не витратитися." },
    { en = "Casting an empower spell extends the duration of Dragonrage by ${$s1/1000} sec.\n\n\n\nEach time this occurs during Dragonrage, its effectiveness is reduced by $s2%.", ua = "Творення закляття наснаги продовжує дію Драконячої люті на ${$s1/1000} сек.\n\n\n\nЩоразу, коли це стається під час Драконячої люті, його дієвість зменшується на $s2%." },
    { en = "Fire Breath damage has $s1% chance to cause your next Living Flame to be instant cast, stacking $375802u times.", ua = "Шкода Вогняного подиху з імовірністю $s1% робить твоє наступне Живе полум'я миттєвим. Складається до $375802u разів." },
    { en = "Shadow Word: Pain periodic damage has a chance to cause your next Mind Blast to be instant and ignore its cooldown.", ua = "Періодична шкода «Слова тіні: Біль» має шанс зробити твій наступний «Удар розуму» миттєвим і без перезарядження." },
    { en = "Increases the damage of Mind Flay by $s1%.", ua = "Збільшує шкоду «Терзання розуму» на $s1%." },
    { en = "Throw a spear at the target location, chaining all enemies in the area to the spear's location and dealing $376080s1 Physical damage instantly and an additional $376080o4 Physical damage over $376081d. \n\n\n\nWhile the spear is active, activating this ability will cause you to leap to the spear, dealing $1271985s1 Physical damage to all targets.\n\n\n\nAll damage dealt reduced beyond $<cap> targets.\n\n\n\n|cFFFFFFFFGenerates $/10;376080s3 Rage.|r", ua = "Метніть спис у вказане місце, прикувавши всіх ворогів у зоні до місця списа й завдавши $376080s1 фізичної шкоди миттєво та додатково $376080o4 фізичної шкоди протягом $376081d. \n\n\n\nПоки спис активний, повторне застосування цієї здібності змусить вас стрибнути до списа, завдавши $1271985s1 фізичної шкоди всім цілям.\n\n\n\nУся завдана шкода зменшується понад $<cap> цілей.\n\n\n\n|cFFFFFFFFГенерує $/10;376080s3 люті.|r" },
    { en = "Empower spells increase your Essence regeneration rate by $370840s1% for $370840d.", ua = "Підсилювані закляття збільшують швидкість відновлення есенції на $370840s1% протягом $370840d." },
    { en = "Dream Breath's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Подиху сну» зменшено на ${$s1/-1000} сек." },
    { en = "Your Magic damage done is increased by $s1%.", ua = "Твою магічну шкоду збільшено на $s1%." },
    { en = "Your Stamina is increased by $s1%.", ua = "Твоя витривалість збільшена на $s1%." },
    { en = "Red spells deal $s1% additional damage and healing.", ua = "Червоні закляття завдають на $s1% більше шкоди та зцілення." },
    { en = "Time Dilation gains an additional charge, and its cooldown is reduced by ${$s2/-1000} sec.", ua = "Уповільнення часу отримує додатковий заряд, а його перезарядження скорочено на ${$s2/-1000} сек." },
    { en = "$s1% of delayed damage from Time Dilation is absorbed.", ua = "$s1% відкладеної шкоди від «Розтягнення часу» поглинається." },
    { en = "Temporal Anomaly reduces the cooldowns of your empower spells by $s1 sec.", ua = "Часова аномалія скорочує перезарядження твоїх посилюваних заклять на $s1 сек." },
    { en = "Your healing is increased by $s1% on targets with your Reversion.", ua = "Твоє зцілення збільшено на $s1% для цілей під дією твого «Обернення»." },
    { en = "Reversion, Time Dilation, Echo, and $?s1291636[Temporal Barrier][Temporal Anomaly] last $s1% longer and cost $s2% less mana.", ua = "Реверсія, Розтягнення часу, Відлуння та $?s1291636[Темпоральний бар'єр][Часова аномалія] тривають на $s1% довше та коштують на $s2% менше мани." },
    { en = "Increases your maximum Runic Power by ${$s1/10}.\n\n\n\nIncreases Rune regeneration rate by $s2%.", ua = "Збільшує вашу максимальну Рунічну силу на ${$s1/10}.\n\n\n\nЗбільшує швидкість відновлення рун на $s2%." },
    { en = "Your Living Flame has a $s1% chance to cause an Essence Burst, making your next Disintegrate or Pyre cost no Essence.", ua = "Твоє Живе полум'я має $s1% шансу викликати Вибух есенції, завдяки чому твоє наступне закляття Дезінтеграція або Вогнище не коштуватиме есенції." },
    { en = "During Deep Breath and Dragonrage you gain the maximum benefit of Mastery: Giantkiller regardless of targets' health.", ua = "Під час «Глибокого подиху» та «Драконячої люті» ти отримуєш максимальну користь від «Майстерності: Убивця велетнів» незалежно від здоров'я цілей." },
    { en = "Your healing done and healing received are increased by $s1%.", ua = "Твоє зцілення та зцілення, яке ти отримуєш, збільшено на $s1%." },
    { en = "Rime empowered Howling Blast deals $s2% increased damage to secondary targets.\n\n\n\nRemorseless Winter deals $s1% increased damage to enemies it hits, stacking up to $376974u times.", ua = "Підсилений Памороззю Завивальний шквал завдає на $s2% більше шкоди другорядним цілям.\n\n\n\nНевблаганна зима завдає на $s1% більше шкоди враженим ворогам, накопичуючись до $376974u разів." },
    { en = "Your $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous][Crusader Strike] deals $s1% increased damage.", ua = "Твій $?s204019[«Благословенний молот»]?s53595[«Молот праведника»][«Удар хрестоносця»] завдає на $s1% більше шкоди." },
    { en = "Remorseless Winter damage is increased by $s2%. The first time Remorseless Winter deals damage to $s1 different enemies, you gain Rime.", ua = "Шкода «Безжальної зими» збільшена на $s2%. Коли «Безжальна зима» вперше завдає шкоди $s1 різним ворогам, ти отримуєш «Паморозь»." },
    { en = "Healing from Vampiric Touch and Shadow Word: Madness when you are at maximum health will shield you for the same amount. The shield cannot exceed $s1% of your maximum health.", ua = "Коли твоє здоров'я повне, зцілення від «Вампірського дотику» та «Слова тіні: Безумство» дає тобі щит на ту саму величину. Щит не може перевищувати $s1% твого максимального здоров'я." },
    { en = "Runic Empowerment has a $s2% chance to refund $s1 additional $LRune:Runes;.", ua = "Рунічне посилення має $s2% шанс відновити $s1 додаткову $LРуну:Руни;." },
    { en = "Frost Strike and Glacial Advance have a $s1% increased chance to trigger Rime and Howling Blast generates ${$377077s1/10} Runic Power while Rime is active.", ua = "Морозний удар і Льодовиковий наступ мають на $s1% більший шанс активувати Паморозь, а Виючий шквал генерує ${$377077s1/10} од. рунічної моці, поки Паморозь активна." },
    { en = "Consuming Killing Machine grants $377101s1% critical strike chance for $377101d, stacking up to ${$377101u-1} times. At ${$377101u-1} stacks your next Killing Machine consumes the stacks and grants you $s1% increased Frost damage for $377103d.", ua = "Поглинання Машини вбивства дає $377101s1% шансу критичного удару на $377101d, накладається до ${$377101u-1} разів. За ${$377101u-1} зарядів твоя наступна Машина вбивства поглинає заряди й збільшує твою шкоду від морозу на $s1% на $377103d." },
    { en = "Consuming a full Temporal Compression grants you Essence Burst.", ua = "Витрата повного Часового стиснення дає тобі Вибух есенції." },
    { en = "Each time you gain Essence Burst, your critical heals are ${$s1+200}% effective instead of the usual 200% for $377102d.", ua = "Щоразу, коли ти отримуєш «Вибух есенції», твої критичні зцілення мають ${$s1+200}% ефективності замість звичних 200% протягом $377102d." },
    { en = "Consecration heals you and $s2 allies within it for $<points> every $26573t1 sec.", ua = "«Освячення» зцілює тебе та $s2 союзників у його межах на $<points> од. кожні $26573t1 с." },
    { en = "When Pillar of Frost expires, your Strength is increased by $377195s1% for $377195d. This effect lasts ${$s2/1000} sec longer, up to ${$s4/1000} sec, for each Obliterate and Frostscythe critical strike during Pillar of Frost.", ua = "Коли «Стовп морозу» завершується, твоя сила збільшується на $377195s1% протягом $377195d. Цей ефект триває на ${$s2/1000} сек. довше, до ${$s4/1000} сек., за кожен критичний удар «Знищення» та «Морозної коси» під час дії «Стовпа морозу»." },
    { en = "Thrash and Maul grant you an absorb shield for $s1% of the damage dealt for $372505d.", ua = "«Шмагання» та «Терзання» дають тобі щит, що поглинає $s1% завданої шкоди, на $372505d." },
    { en = "Pillar of Frost now summons a Remorseless Winter that lasts ${$1233152d-$196770d} sec longer.\n\n\n\nEach enemy Remorseless Winter damages grants you ${$377253s1*$mastery}% Mastery, up to ${$s2*$mastery*$377253u}% for $287338d.", ua = "Стовп морозу тепер прикликає Невблаганну зиму, що триває на ${$1233152d-$196770d} сек. довше.\n\n\n\nКожен ворог, якому Невблаганна зима завдає шкоди, дає вам ${$377253s1*$mastery}% Майстерності, до ${$s2*$mastery*$377253u}% на $287338d." },
    { en = "Mind Flay has a chance to spawn a Void Tendril that channels Mind Flay or Void Lasher that channels Mind Sear at your target.\n\n\n\n$@spellicon193473 $@spellname193473\n\n$@spelldesc193473\n\n\n\n$@spellicon394976 $@spellname394976\n\n$@spelldesc394976", ua = "Шмагання розуму має шанс породити Щупальце Порожнечі, що спрямовує Шмагання розуму, або Шмагача Порожнечі, що спрямовує Випал розуму на вашу ціль.\n\n\n\n$@spellicon193473 $@spellname193473\n\n$@spelldesc193473\n\n\n\n$@spellicon394976 $@spellname394976\n\n$@spelldesc394976" },
    { en = "Each Magus of the Dead under your command grants you ${$s1}.1% Haste.", ua = "Кожен магус мертвих під твоїм командуванням дарує тобі ${$s1}.1% поспіху." },
    { en = "Scourge Strike, Festering Strike, and Death Coil deal $s1% additional damage to enemies below $s2% health.\n\n\n\nDark Transformation resets Soul Reaper's cooldown and allows it to be used on any target.", ua = "Удар погибелі, Гнійний удар і Виток смерті завдають на $s1% більше шкоди ворогам зі здоров'ям нижче $s2%.\n\n\n\nТемне перетворення скидає перезарядження Женця душ і дозволяє застосовувати його на будь-яку ціль." },
    { en = "Putrefy deals $s2% increased damage, has $s1 additional $Lcharge:charges; and consumes up to $s3 available charges.", ua = "«Гниття» завдає на $s2% більше шкоди, має $s1 додатковий $Lзаряд:заряди; і споживає до $s3 наявних зарядів." },
    { en = "Dark Transformation increases the attack speed and damage of you and your Monstrosity by $s1% for $377588d.", ua = "«Темне перевтілення» збільшує швидкість атаки та шкоду тобі й твоїй почварі на $s1% на $377588d." },
    { en = "Spending Runic Power increases your Strength by $?A134735[${$S1/100}.2][${$s1/100}.2]% for $377591d.\n\n\n\nMultiple applications may overlap.", ua = "Витрачання Рунічної енергії збільшує вашу Силу на $?A134735[${$S1/100}.2][${$s1/100}.2]% на $377591d.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Diseased enemies take $s1% increased damage from you per disease they are affected by.", ua = "Хворі вороги отримують від тебе на $s1% більше шкоди за кожну хворобу, що на них діє." },
    { en = "Heart Strike heals you for ${$s1/100}.2% health for each enemy hit while affected by Blood Plague.", ua = "Удар у серце зцілює тебе на ${$s1/100}.2% здоров'я за кожного враженого ворога під дією Кривавої чуми." },
    { en = "Dancing Rune Weapon's cooldown is reduced by ${$s1/-1000} sec and now generates $s2 Bone Shield charges.", ua = "Перезарядження «Танцівної рунічної зброї» скорочено на ${$s1/-1000} сек., і тепер вона генерує $s2 зарядів «Кістяного щита»." },
    { en = "Summons $s1 additional copy of Dancing Rune Weapon and increases its duration by ${$s2/1000} sec.", ua = "Прикликає $s1 додаткову копію танцюючої рунічної зброї та збільшує її тривалість на ${$s2/1000} сек." },
    { en = "Healing you receive is increased by $s1%.", ua = "Зцілення, яке ти отримуєш, збільшене на $s1%." },
    { en = "Frenzied Regeneration's healing is increased by up to $s1% based on your missing health.\n\n\n\nFrenzied Regeneration has ${$s2} additional charge.", ua = "Зцілення від Шаленої регенерації збільшується аж до $s1% залежно від нестачі здоров'я.\n\n\n\nШалена регенерація має ${$s2} додатковий заряд." },
    { en = "Stampeding Roar's radius is increased by $s1%.\n\n\n\nYour movement speed is increased by $s2%.", ua = "Радіус Навального рику збільшено на $s1%.\n\n\n\nВаша швидкість пересування підвищена на $s2%." },
    { en = "For $340541d after shifting into Bear Form, your health and armor are increased by $s1%.", ua = "Протягом $340541d після переходу у ведмежу подобу твоє здоров'я та броня збільшені на $s1%." },
    { en = "When you fall below $s2% health, you cast Frenzied Regeneration, up to once every $s1 sec.", ua = "Коли твоє здоров'я падає нижче за $s2%, ти твориш «Несамовиту регенерацію», щонайбільше раз на $s1 сек." },
    { en = "Astral Shift reduces damage taken by an additional $s1%.", ua = "«Астральний зсув» зменшує отримувану шкоду додатково на $s1%." },
    { en = "Critical strike chance increased by $s1%.", ua = "Імовірність критичного удару збільшена на $s1%." },
    { en = "Ghost Wolf removes snares and increases your movement speed by an additional $s1% for the first $338036d. May only occur once every $proccooldown sec.", ua = "Примарний вовк знімає ефекти знерухомлення та підвищує вашу швидкість пересування додатково на $s1% упродовж перших $338036d. Може спрацьовувати лише раз на $proccooldown с." },
    { en = "When you cast Spiritwalker's Grace, you become immune to Silence and Interrupt effects for $378078d.", ua = "Коли ти твориш «Милість духоходця», то отримуєш імунітет до ефектів німоти та переривання на $378078d." },
    { en = "Your next healing or damaging Nature spell $?a1246131[or Hex ][]is instant cast and costs no mana.", ua = "Ваше наступне закляття Природи, що зцілює чи завдає шкоди, $?a1246131[або Вроки ][]є миттєвим і не коштує мани." },
    { en = "Elemental Fury increases critical strike damage by an additional $s1%.", ua = "«Стихійна лють» збільшує шкоду критичних ударів додатково на $s1%." },
    { en = "Reversion instantly heals the target for $s1% of damage taken in the last $s2 sec.", ua = "«Реверсія» миттєво зцілює ціль на $s1% шкоди, отриманої за останні $s2 сек." },
    { en = "While Beast Cleave is active, Kill Command now also strikes nearby enemies for $s1% of damage dealt. Deals reduced damage beyond $389448s2 targets.", ua = "Поки діє «Звірине розсікання», «Наказ убити» тепер також вражає ворогів поблизу, завдаючи їм $s1% завданої шкоди. Шкода зменшується, якщо цілей більше за $389448s2." },
    { en = "All pet damage dealt increased by $s1%.", ua = "Уся шкода, завдана улюбленцем, збільшена на $s1%." },
    { en = "Your Healing $?a137039[Wave][Surge] is $s1% more effective on yourself.", ua = "Ваше зцілення $?a137039[«Хвиля»][«Сплеск»] на $s1% ефективніше на вас самих." },
    { en = "Cobra Shot Focus cost reduced by $s1. Cobra Shot damage increased by $s2%.", ua = "Витрата зосередження на «Постріл кобри» зменшена на $s1. Шкода «Пострілу кобри» збільшена на $s2%." },
    { en = "Ascendance summons a $?a117013[Primal][Greater] Fire Elemental to rain destruction on your enemies for $188592d. \n\n\n\nWhile the Fire Elemental is active, Flame Shock deals damage ${100*(1/(1+$188592s2/100)-1)}% faster, and newly applied Flame Shocks last $188592s3% longer.", ua = "Вознесіння прикликає $?a117013[первісного][величного] вогняного елементаля, що сіє руйнування серед ваших ворогів протягом $188592d.\n\n\n\nДоки вогняний елементаль активний, Полум'яний шок завдає шкоди на ${100*(1/(1+$188592s2/100)-1)}% швидше, а щойно накладені Полум'яні шоки тривають на $188592s3% довше." },
    { en = "Reduces the cooldown of Flame Shock and Voltaic Blaze by ${$s2/-1000}.1 sec.\n\n\n\nFlame Shock deals damage ${100*(1/(1+$m1/100)-1)}% faster.", ua = "Скорочує перезарядження «Вогняного шоку» та «Вольтаїчного полум'я» на ${$s2/-1000}.1 сек.\n\n\n\n«Вогняний шок» завдає шкоди на ${100*(1/(1+$m1/100)-1)}% швидше." },
    { en = "$?a137039[Casting Riptide]?a137040[Each Maelstrom spent][Each stack of Maelstrom Weapon consumed] has a $?a137039[$s4]?a137040[${$s2/100}.2][${$s3/10}.1]% chance to activate Ascendance for ${$m1/1000}.1 sec.\n\n\n\n$?a137039[$@spellicon114052 $@spellname114052\n\n$@spelldesc114052]?a137040[$@spellicon114050 $@spellname114050\n\n$@spelldesc114050][$@spellicon114051 $@spellname114051\n\nTransform into an Air Ascendant for $114051d and unleash Doom Winds, reducing the cooldown and cost of Stormstrike by $114051s9%, and transforming your auto attack and Stormstrike into Wind attacks which bypass armor and have a $114089r yd range.]", ua = "$?a137039[Застосування «Відпливу»]?a137040[Кожен витрачений Вир][Кожен спожитий заряд «Зброї Виру»] має $?a137039[$s4]?a137040[${$s2/100}.2][${$s3/10}.1]% шанс активувати «Піднесення» на ${$m1/1000}.1 сек.\n\n\n\n$?a137039[$@spellicon114052 $@spellname114052\n\n$@spelldesc114052]?a137040[$@spellicon114050 $@spellname114050\n\n$@spelldesc114050][$@spellicon114051 $@spellname114051\n\nПеретворюєшся на Піднесеного повітря на $114051d і вивільняєш «Вітри судьби», що зменшують перезарядження й вартість «Удару бурі» на $114051s9% та перетворюють твою автоатаку й «Удар бурі» на атаки вітру, які оминають броню й мають дальність $114089r ярдів.]" },
    { en = "Each enemy hit by Avenger's Shield reduces the remaining cooldown on Guardian of Ancient Kings by ${$s1/1000}.1 sec.\n\n\n\nWhen you drop below $s2% health, you become infused with Guardian of Ancient Kings for $s3 sec. This cannot occur again for $337852d.", ua = "Кожен ворог, уражений «Щитом месника», зменшує залишкове перезарядження «Захисника прадавніх королів» на ${$s1/1000}.1 с.\n\n\n\nКоли ваше здоров'я падає нижче $s2%, вас наповнює сила «Захисника прадавніх королів» на $s3 с. Це не може повторитися протягом $337852d." },
    { en = "Your Avenger's Shield is imbued with holy fire, causing it to deal $<dmg> Holy damage to all enemies within $378286A1 yards of each target hit.", ua = "Твій «Щит месника» сповнений святого вогню й завдає $<dmg> святої шкоди всім ворогам у межах $378286A1 м від кожної враженої цілі." },
    { en = "Word of Glory heals for an additional $s1% over $378412d.\n\n\n\nIncreased by $s2% if cast on yourself while you are afflicted by a harmful damage over time effect.", ua = "«Слово слави» зцілює додатково на $s1% протягом $378412d.\n\n\n\nЗростає на $s2%, якщо сотворене на вас самих, поки ви вражені шкідливим ефектом періодичної шкоди." },
    { en = "Frozen Orb has a $s1% chance to grant Brain Freeze.", ua = "«Заморожена сфера» має $s1% шансу дати «Замерзання мозку»." },
    { en = "Your Lay on Hands, Divine Shield, Blessing of Protection, and Blessing of Spellwarding have $s1% reduced cooldown.", ua = "Перезарядження «Покладання рук», «Божественного щита», «Благословення захисту» та «Благословення чарозахисту» зменшене на $s1%." },
    { en = "Energy cost of Feint and Crimson Vial reduced by $s1.", ua = "Витрати енергії на Фінт і Багряний флакон зменшено на $s1." },
    { en = "Increases the non-damaging effects of your weapon poisons by $s1%.", ua = "Збільшує ефекти твоїх отрут для зброї, що не завдають шкоди, на $s1%." },
    { en = "When your primary pet uses Stomp, apply Barbed Shot to a target hit by that Stomp. This Barbed Shot will not cause an extra Stomp.", ua = "Коли твій основний улюбленець використовує «Тупіт», на одну з уражених ним цілей накладається «Колючий постріл». Цей «Колючий постріл» не викликає додаткового «Тупоту»." },
    { en = "Deal ${$378597s1*$s1} Nature damage every $378463t1 sec to up to $378597s2 enemies inside of your Healing Rain.", ua = "Завдає ${$378597s1*$s1} шкоди від природи кожні $378463t1 сек. щонайбільше $378597s2 ворогам у межах твого «Цілющого дощу»." },
    { en = "Ice Lance strikes $s1 additional $Ltarget:targets; at $s2% effectiveness, preferring enemies with more stacks of Freezing.", ua = "Крижаний спис вражає $s1 додаткову $Lціль:цілі; з ефективністю $s2%, надаючи перевагу ворогам з більшою кількістю стаків Заморожування." },
    { en = "Avenger's Shield jumps to $s1 additional targets.", ua = "«Щит месника» перестрибує на $s1 додаткові цілі." },
    { en = "Kill Command has a $s1% chance to also summon a Dire Beast to attack your target for $120679s2 sec.", ua = "«Наказ убити» з імовірністю $s1% також прикликає лютого звіра, який атакує твою ціль протягом $120679s2 сек." },
    { en = "Avenger's Shield deals $s1% increased damage to its primary target.", ua = "«Щит месника» завдає основній цілі на $s1% більше шкоди." },
    { en = "Consuming Precise Shots reduces the cooldown of Aimed Shot by ${$s1/1000}.2 sec.", ua = "Витрата «Точних пострілів» скорочує перезарядження «Прицільного пострілу» на ${$s1/1000}.2 сек." },
    { en = "Purges the enemy target, removing $m1 beneficial Magic effects.", ua = "Очищає ворожу ціль, знімаючи з неї $m1 корисних магічних ефектів." },
    { en = "While Stealth or Shadow Dance is active, you move $s1% faster.", ua = "Поки діє Скрадання або Танець тіней, ти рухаєшся на $s1% швидше." },
    { en = "When Avenger's Shield strikes a single enemy, it deals $s1% additional Holy damage.", ua = "Коли «Щит месника» влучає лише в одного ворога, він завдає на $s1% більше шкоди Світлом." },
    { en = "Successfully interrupting an enemy with Mind Freeze grants ${$378849s1/10} Runic Power and reduces its cooldown by ${$378849s2/-1000} sec.", ua = "Успішне переривання ворога «Замороженням розуму» дає ${$378849s1/10} рунічної сили та зменшує його перезарядження на ${$378849s2/-1000} сек." },
    { en = "Trick Shots now causes Aimed Shot and Rapid Fire to ricochet to $s1 additional $Ltarget:targets;.\n\n\n\nAspect of the Hydra's damage bonus is increased by $s3%.", ua = "Хитрі постріли тепер змушують Прицільний постріл і Швидкий вогонь рикошетити в $s1 додаткову $Lціль:цілі:цілей;.\n\n\n\nБонус шкоди Аспекту гідри збільшено на $s3%." },
    { en = "$?s431044[Frostfire Bolt][Frostbolt] and Flurry critical strike damage increased by $s1%.", ua = "Критична шкода від $?s431044[Льодовогняна стріла][Крижана стріла] і Шквалу збільшена на $s1%." },
    { en = "The damage of your auto-attacks is increased by $s1%.\n\n\n\nYour Agility is increased by $s2%, increased by an additional $s3% while dual-wielding.", ua = "Шкода ваших автоатак збільшена на $s1%.\n\n\n\nВаша Спритність збільшена на $s2% і додатково на $s3% під час бою двома руками." },
    { en = "Wildfire Bomb, Boomstick, and Flamefang Pitch damage increased by $s1%.", ua = "Шкода «Бомби дикого вогню», «Бахкала» та «Смоли вогняного ікла» збільшена на $s1%." },
    { en = "Flurry has a $s1% chance each hit to call down an icy comet, crashing into your target and nearby enemies for $379029s1 Frost damage.\n\n\n\n|CFFffffffApplies $s2 $lstack:stacks; of Freezing.|R", ua = "«Шквал» має $s1% шансу при кожному влучанні прикликати крижану комету, що врізається у вашу ціль і ворогів поруч, завдаючи $379029s1 крижаної шкоди.\n\n\n\n|CFFffffffНакладає $s2 $lстак:стаки; «Заморожування».|R" },
    { en = "Raptor Strike damage increased by $s1%.", ua = "Шкоду Удару раптора збільшено на $s1%." },
    { en = "All damage dealt by your pet is increased by $s1%.", ua = "Уся шкода, завдана твоїм улюбленцем, збільшена на $s1%." },
    { en = "You gain $s1% of a stat while in each form:\n\n\n\nNo Form: Haste\n\nCat Form: Critical Strike\n\nBear Form: Versatility\n\nMoonkin Form: Mastery", ua = "У кожній подобі ви отримуєте $s1% характеристики:\n\n\n\nБез подоби: Поспіх\n\nКотяча подоба: Критичний удар\n\nВедмежа подоба: Універсальність\n\nПодоба сови: Майстерність" },
    { en = "Slice and Dice heals you for up to $s1% of your maximum health per $426605t sec.", ua = "Шаткування зцілює тебе до $s1% максимального здоров'я кожні $426605t сек." },
    { en = "Enemies have $394119s1% reduced damage and healing for $394119d after Blind or Sap's effect on them ends.", ua = "Після завершення дії Осліплення чи Приголомшення вороги завдають на $394119s1% менше шкоди й зцілення протягом $394119d." },
    { en = "While in your Consecration and for ${$s1/1000}.1 sec after leaving it, your damage taken is reduced by $s2%.", ua = "Поки ти в зоні свого «Освячення» та ще ${$s1/1000}.1 сек. після виходу з неї, отримувана тобою шкода зменшена на $s2%." },
    { en = "Consecration lasts ${$s1/1000} sec longer and its damage is increased by $s2%.", ua = "«Освячення» триває на ${$s1/1000} сек. довше, а його шкода збільшена на $s2%." },
    { en = "$?c1[Divine Toll's, Holy Armament's, and Holy Prism's][Divine Toll's] cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження $?c1[«Божественного поклику», «Святого озброєння» та «Святої призми»][«Божественного поклику»] зменшене на ${-$s1/1000} сек." },
    { en = "Casting Glacial Spike has a $s1% chance to grant you Fingers of Frost.", ua = "Прочитання «Льодовикового шипа» має $s1% шансу дати тобі «Пальці морозу»." },
    { en = "Enemies hit by Avenger's Shield deal $383843s1% reduced melee damage to you for $383843d.", ua = "Вороги, уражені «Щитом месника», завдають тобі на $383843s1% менше шкоди в ближньому бою протягом $383843d." },
    { en = "Increases the critical strike chance of your attacks that generate combo points by $s1%.", ua = "Збільшує шанс критичного удару твоїх атак, що генерують комбо-очки, на $s1%." },
    { en = "Increases the damage of your weapon poisons by $s1%.", ua = "Збільшує шкоду твоїх отрут для зброї на $s1%." },
    { en = "Versatility increased by $s1%.", ua = "Універсальність збільшено на $s1%." },
    { en = "$?s185438[Shadowstrike damage increased by $s2%][Ambush generates $s1 additional combo point].", ua = "$?s185438[Шкода Тіньового удару збільшена на $s2%][Засідка генерує $s1 додаткове комбо-очко]." },
    { en = "Energy cost of finishing moves reduced by $s1%.", ua = "Витрати енергії на завершальні прийоми зменшено на $s1%." },
    { en = "Increases the application chance of your weapon poisons by $s1%.", ua = "Збільшує шанс накладання твоїх отрут для зброї на $s1%." },
    { en = "Garrote and Rupture damage increased by $s1%.", ua = "Шкода «Гароти» та «Розриву» збільшена на $s1%." },
    { en = "Kidney Shot and Rupture also apply Internal Bleeding, dealing up to ${5*$381628o1} Bleed damage over $381628d, based on combo points spent.", ua = "«Удар по нирках» та «Розрив» також накладають «Внутрішню кровотечу», що завдає до ${5*$381628o1} шкоди від кровотечі протягом $381628d, залежно від витрачених комбо-очок." },
    { en = "Fan of Knives has $s2% increased critical strike chance and its critical strikes always apply your weapon poisons.", ua = "Віяло ножів має на $s2% більший шанс критичного удару, а його критичні удари завжди накладають твої отрути для зброї." },
    { en = "Shadowstep's cooldown is reduced by $s1% when used on a target afflicted by your Garrote.", ua = "Перезарядження «Кроку тіні» зменшується на $s1%, якщо застосувати його до цілі під дією твоєї «Гароти»." },
    { en = "Fan of Knives has its radius increased to $?a196924[${$196924s1+$s4}][$s4] yds, deals $s5% more damage, and an additional $s1% when striking $s2 or more targets.", ua = "Віяло ножів має збільшений радіус до $?a196924[${$196924s1+$s4}][$s4] ярдів, завдає на $s5% більше шкоди та додатково $s1%, коли вражає $s2 або більше цілей." },
    { en = "Garrote deals $s1% increased damage and has no cooldown when used from Stealth and for $392401d after breaking Stealth.", ua = "«Гарота» завдає на $s1% більше шкоди й не має перезарядження, якщо застосована з непомітності, а також протягом $392401d після виходу з непомітності." },
    { en = "Coats your weapons with a Non-Lethal Poison that lasts for $d. Each strike has a $h% chance of poisoning the enemy, reducing their damage by ${$392388s1*-1}.1% for $392388d.", ua = "Вкриває твою зброю нелетальною отрутою, що тримається $d. Кожен удар має $h% шансу отруїти ворога, зменшивши його шкоду на ${$392388s1*-1}.1% на $392388d." },
    { en = "Your weapon poisons and Nature or Bleed damage over time abilities deal $s1% increased damage to targets for each of your lethal poison or damage over time effects on them.", ua = "Твої отрути для зброї та здібності з періодичною шкодою природи чи кровотечі завдають цілям на $s1% більше шкоди за кожен твій ефект смертельної отрути чи періодичної шкоди на них." },
    { en = "Reduces the cooldown of Astral Shift by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Астрального зсуву» на ${$s1/-1000} сек." },
    { en = "Reduces all magic damage taken by $s1%.", ua = "Зменшує всю отримувану магічну шкоду на $s1%." },
    { en = "Garrote increases the damage of Ambush and Mutilate on the target by $s1%.", ua = "«Гарота» збільшує шкоду «Засідки» та «Калічення» по цілі на $s1%." },
    { en = "Increases the critical strike chance of your Nature spells and abilities by $s1%.", ua = "Збільшує шанс критичного удару твоїх заклять і здібностей природи на $s1%." },
    { en = "Coats your weapons with a Lethal Poison that lasts for $d. Each strike has a $h% chance to poison the enemy, dealing $383414s1 Nature damage and applying Amplifying Poison for $383414d. Envenom can consume $s2 stacks of Amplifying Poison to deal $s1% increased damage. Max $383414u stacks.", ua = "Вкриває твою зброю летальною отрутою, що тримається $d. Кожен удар має $h% шансу отруїти ворога, завдавши $383414s1 шкоди природою та наклавши «Підсилювальну отруту» на $383414d. «Отруєння» може поглинути $s2 зарядів «Підсилювальної отрути», щоб завдати на $s1% більше шкоди. Максимум $383414u зарядів." },
    { en = "Mutilate deals an additional $s1% Bleed damage over ${$381672d+2} sec.", ua = "«Калічення» завдає додатково $s1% шкоди від кровотечі протягом ${$381672d+2} сек." },
    { en = "Stamina increased by $s1%.\n\n\n\nWhile you are at full health, Reincarnation cools down $s2% faster.", ua = "Витривалість збільшена на $s1%.\n\n\n\nДоки ви маєте повне здоров'я, «Перевтілення» перезаряджається на $s2% швидше." },
    { en = "Increases your maximum Maelstrom by $s1.\n\n\n\nIncreases Earth Shock, Elemental Blast, and Earthquake damage by $s2%.", ua = "Збільшує ваш максимальний Вир на $s1.\n\n\n\nЗбільшує шкоду «Земного шоку», «Стихійного вибуху» та «Землетрусу» на $s2%." },
    { en = "Reduces the Maelstrom cost of Earth Shock and Earthquake by $s1.\n\n\n\nReduces the Maelstrom cost of Elemental Blast by $s3.", ua = "Зменшує вартість «Земного шоку» та «Землетрусу» у Вирі на $s1.\n\n\n\nЗменшує вартість «Стихійного вибуху» у Вирі на $s3." },
    { en = "Earth Shock, Elemental Blast, and Earthquake can trigger your Mastery: Elemental Overload at $s1% effectiveness.\n\n\n\nOverloaded Earthquakes do not knock enemies down.", ua = "«Земний шок», «Стихійний вибух» і «Землетрус» можуть запускати вашу «Майстерність: Стихійне перевантаження» з $s1% ефективністю.\n\n\n\nПеревантажені «Землетруси» не збивають ворогів з ніг." },
    { en = "Flame Shock damage has a chance to generate $s1 Maelstrom.", ua = "Шкода «Вогняного шоку» має шанс створити $s1 од. Виру." },
    { en = "Flame Shock damage increased by $s1%.", ua = "Шкода «Вогняного шоку» збільшена на $s1%." },
    { en = "Envenom's effect also increases the critical strike chance of your weapon poisons by $s1%, and their critical strikes generate $s2 Energy.", ua = "Ефект Отруєння також збільшує шанс критичного удару твоїх отрут для зброї на $s1%, а їхні критичні удари створюють $s2 енергії." },
    { en = "Your Bleed, weapon poison, and other Nature damage is increased by $s1% against targets below $s2% health.", ua = "Шкода від твоїх кровотеч, отрут для зброї та інша шкода природи збільшена на $s1% проти цілей, що мають менше ніж $s2% здоров'я." },
    { en = "Each enemy afflicted by your Rupture increases your Agility by $S1%, up to a maximum of $394080u%.", ua = "Кожен ворог, уражений вашим Розривом, збільшує вашу Спритність на $S1%, до максимуму $394080u%." },
    { en = "You may apply $s1 additional Lethal and Non-Lethal Poison to your weapons, but they have $s2% less application chance.", ua = "Ти можеш нанести на зброю ще $s1 смертельну та несмертельну отруту, але їхній шанс накладання менший на $s2%." },
    { en = "Between the Eyes has a $s1% chance per combo point spent to grant $394120s1 combo points and reset its own cooldown.", ua = "«Межи очі» має $s1% шансу за кожне витрачене очко комбо дати $394120s1 очок комбо та скинути власне перезарядження." },
    { en = "Roll the Bones has a $s1% increased chance of granting more powerful results.", ua = "«Кидок кісток» має на $s1% більший шанс дати потужніші результати." },
    { en = "Using Pistol Shot with Opportunity has a $279876s1% chance to make your next Ambush usable without Stealth.\n\n\n\nChance to trigger this effect matches the chance for Sinister Strike to grant Opportunity.", ua = "Застосування «Пострілу з пістоля» з «Нагодою» має $279876s1% шанс зробити вашу наступну «Засідку» доступною без схованки.\n\n\n\nШанс запустити цей ефект дорівнює шансу «Зловісного удару» надати «Нагоду»." },
    { en = "When you gain Opportunity, gain $m1 additional $Lcharge:charges;. Max ${$s2+1} charges.\n\n\n\nPistol Shot consumes $m1 additional $Lcharge:charges; of Opportunity to fire $m1 additional $Lbullet:bullets;. Additional shots deal $s3% reduced damage.", ua = "Коли ти отримуєш «Нагоду», ти отримуєш $m1 додатковий $Lзаряд:заряди;. Максимум ${$s2+1} зарядів.\n\n\n\n«Постріл з пістоля» споживає $m1 додатковий $Lзаряд:заряди; «Нагоди», аби випустити $m1 додаткову $Lкулю:кулі;. Додаткові постріли завдають на $s3% менше шкоди." },
    { en = "Reduces the cooldown of most totems by ${$s1/-1000} sec.", ua = "Зменшує перезарядження більшості тотемів на ${$s1/-1000} сек." },
    { en = "Stamina increased by $<stam>%.", ua = "Витривалість збільшено на $<stam>%." },
    { en = "Blade Flurry's initial damage is increased by $s1% and generates $m2 $Lcombo point:combo points; per target struck, but its Energy cost is increased by $s3.", ua = "Початкова шкода від Шквалу клинків збільшена на $s1%, і він створює $m2 $Lочко комбо:очка комбо; за кожну вражену ціль, але його вартість Енергії збільшена на $s3." },
    { en = "Attacks that generate combo points deal $s1% increased damage.", ua = "Атаки, що породжують очки комбо, завдають на $s1% більше шкоди." },
    { en = "Casting Echo grants one stack of Ouroboros, increasing the healing of your next Emerald Blossom by $387350s1%, stacking up to $387350u times.", ua = "Творіння Відлуння дає один заряд Уробороса, що посилює зцілення твого наступного Смарагдового цвіту на $387350s1%. Складається до $387350u разів." },
    { en = "Rewind's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Перемотування» скорочено на ${$s1/-1000} сек." },
    { en = "Your $?!s137041[Lava Burst][]$?s137039[ and Riptide][]$?s137041[Stormstrike][] casts restore $?a137040[$381931s1]?a137041[$404550s1][$404551s1] mana to you and $s1 allies nearest to you within $395192a1 yards.\n\n\n\nAllies can only benefit from one Shaman's Mana Spring effect at a time, prioritizing healers.", ua = "Ваші прочитання $?!s137041[Виверження лави][]$?s137039[ та Відпливу][]$?s137041[Штормового удару][] відновлюють $?a137040[$381931s1]?a137041[$404550s1][$404551s1] мани вам та $s1 найближчим до вас союзникам у межах $395192a1 м.\n\n\n\nСоюзники можуть користуватися ефектом Джерела мани лише від одного шамана водночас, з пріоритетом для цілителів." },
    { en = "Increases the critical strike chance of Lightning Bolt$?a454009[, Tempest,][] and Chain Lightning by $s1%.", ua = "Підвищує шанс критичного удару Розряду блискавки$?a454009[, Буревію,][] та Ланцюгової блискавки на $s1%." },
    { en = "Increases Riptide's duration by ${$s1/1000}.1 sec and its healing over time by $s2%.", ua = "Збільшує тривалість «Бистрини» на ${$s1/1000}.1 сек., а її поступове зцілення — на $s2%." },
    { en = "Slice and Dice grants additional attack speed equal to $s2% of your Haste.", ua = "Шаткування дає додаткову швидкість атаки, що дорівнює $s2% твого Поспіху." },
    { en = "Increase the remaining duration of your active Roll the Bones combat enhancement by ${$s1/1000} sec.", ua = "Збільшує залишкову тривалість активного бойового підсилення від «Кидка кісток» на ${$s1/1000} сек." },
    { en = "Dispatch deals $s1% increased damage and costs $s3 less Energy. This damage bonus is increased by $315341s4% while your damage is enhanced by your Between the Eyes.", ua = "Розправа завдає на $s1% більше шкоди й коштує на $s3 енергії менше. Цей бонус до шкоди збільшено на $315341s4%, поки твою шкоду підсилено ефектом Поміж очей." },
    { en = "After activating Shadow Dance, your next $@switch<$s1>[attack][$s1 attacks] that $@switch<$s1>[generates][generate] combo points $@switch<$s1>[deals][deal] $394203s3% increased damage.", ua = "Після активації Танцю тіней ваша наступна $@switch<$s1>[атака][$s1 атаки], що $@switch<$s1>[генерує][генерують] комбо-очки, $@switch<$s1>[завдає][завдають] на $394203s3% більше шкоди." },
    { en = "Your abilities deal $s1% increased magic damage.", ua = "Твої здібності завдають на $s1% більше магічної шкоди." },
    { en = "Earth Shield reduces damage taken by $s3% and its healing is increased by up to $s1% as its target's health decreases. Maximum benefit is reached below $s2% health.", ua = "«Земний щит» зменшує отримувану шкоду на $s3%, а його зцілення зростає аж до $s1% мірою того, як зменшується здоров'я цілі. Найбільший ефект досягається нижче $s2% здоров'я." },
    { en = "Imbue your weapon with the element of Earth for $382022d. Your Riptide, Healing Wave, and Chain Heal healing has a $382022s2% chance to trigger Earthliving on the target, healing for $382024o1 over $382024d.", ua = "Насичує твою зброю стихією землі на $382022d. Зцілення від «Бистрини», «Хвилі зцілення» та «Ланцюгового зцілення» має $382022s2% шансу викликати на цілі «Живу землю», що відновлює $382024o1 здоров'я протягом $382024d." },
    { en = "Reduces the cooldown of Healing Stream Totem by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Тотема цілющого потоку» на ${$s1/-1000} сек." },
    { en = "Increases the damage dealt by your Elemental Overloads by $s1%.", ua = "Збільшує шкоду від твоїх «Стихійних перевантажень» на $s1%." },
    { en = "Chain Heal bounces an additional time and casting Chain Heal on a target affected by Riptide consumes Riptide, increasing the healing of your Chain Heal by $s1%.", ua = "«Ланцюгове зцілення» перестрибує ще один раз, а його творення на ціль під дією «Відбійної течії» поглинає її, збільшуючи зцілення твого «Ланцюгового зцілення» на $s1%." },
    { en = "Casting Sundering grants you $s1% Haste for $382043d, and generates $s3 stacks of Maelstrom Weapon.", ua = "Творення «Розколу» дає тобі $s1% поспіху на $382043d і генерує $s3 зарядів «Зброї Виру»." },
    { en = "Every $s1 casts of Riptide also applies Riptide to another friendly target near your Riptide target.", ua = "Кожні $s1 прочитань «Стрімкої течії» також накладають «Стрімку течію» на ще одну дружню ціль поруч із ціллю твоєї «Стрімкої течії»." },
    { en = "For each Riptide active on an ally, your heals are ${$s2/10}.1% more effective.", ua = "За кожну активну «Стрімку течію» на союзникові твоє зцілення на ${$s2/10}.1% ефективніше." },
    { en = "Cleanse Spirit, Wind Shear, Purge, and totem casts no longer cancel Ghost Wolf.", ua = "«Очищення духу», «Зріз вітру», «Чистка» і встановлення тотемів більше не скасовують «Вовка-привида»." },
    { en = "Increases the radius of your totem effects by $s3%.\n\n\n\nIncreases the duration of your Earthbind and Earthgrab Totems by ${$s1/1000} sec.\n\n\n\nIncreases the duration of your $?s157153[Cloudburst][Healing Stream], Tremor, Poison Cleansing, $?s137039[Ancestral Protection, Earthen Wall, ][]and Wind Rush Totems by ${$s2/1000}.1 sec.", ua = "Збільшує радіус дії ваших тотемних ефектів на $s3%.\n\n\n\nЗбільшує тривалість ваших тотемів Земних пут та Земної хватки на ${$s1/1000} с.\n\n\n\nЗбільшує тривалість ваших тотемів $?s157153[Хмаропаду][Зцілющого потоку], Здригання, Очищення від отрути, $?s137039[Захисту предків, Земляної стіни, ][]та Поривів вітру на ${$s2/1000}.1 с." },
    { en = "Increases your movement speed by $s1% and the movement speed bonus of Ghost Wolf by an additional $s2%.", ua = "Збільшує швидкість твого руху на $s1%, а бонус до швидкості руху від «Примарного вовка» — ще на $s2%." },
    { en = "Critical strike chance increased by $s1%. Critical strike damage bonus of your attacks that generate combo points increased by $s2%.", ua = "Шанс критичного удару збільшено на $s1%. Бонус до шкоди критичних ударів твоїх атак, що породжують очки комбо, збільшено на $s2%." },
    { en = "Critically striking with an attack that generates combo points increases the critical strike chance of your next finishing move by $1264297s1%.", ua = "Критичний удар атакою, що створює очки комбо, збільшує шанс критичного удару твого наступного завершального прийому на $1264297s1%." },
    { en = "Leech increased by $s1%.", ua = "Висмоктування збільшено на $s1%." },
    { en = "The cooldowns of Blink and Shimmer are reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Блимання» та «Мерехтіння» зменшено на ${$s1/-1000} сек." },
    { en = "$?s110959[Greater ][]Invisibility increases your movement speed by $s1% for $337278d.", ua = "$?s110959[Велика н][Н]евидимість підвищує вашу швидкість пересування на $s1% протягом $337278d." },
    { en = "Counterspell's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Контрзакляття» зменшено на ${-$s1/1000} сек." },
    { en = "When you heal with your Healing Wave or Riptide you have a $s2% chance to summon an Ancestral spirit to aid you, instantly healing an injured friendly party or raid target within 40 yards for $s1% of the amount healed. Critical strikes increase this chance to $s3%.", ua = "Коли ти зцілюєш «Хвилею зцілення» чи «Стрімниною», з імовірністю $s2% викликаєш духа предків собі на поміч: він миттєво зцілює пораненого союзника з групи чи рейду в межах 40 м на $s1% від обсягу зцілення. Критичні удари підвищують цю ймовірність до $s3%." },
    { en = "Earthliving receives $s1% additional benefit from Mastery: Deep Healing.\n\n\n\nHealing Wave always triggers Earthliving on its target.", ua = "«Жива земля» отримує на $s1% більше користі від «Майстерності: Глибоке зцілення».\n\n\n\n«Хвиля зцілення» завжди запускає «Живу землю» на своїй цілі." },
    { en = "The cooldown of Ice Block is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Крижаної брили» зменшено на ${$s1/-1000} сек." },
    { en = "Healing Stream Totem heals for $s1% more, decaying over its duration.", ua = "«Тотем цілющого потоку» зцілює на $s1% сильніше; ефект слабшає протягом його дії." },
    { en = "Increases critical strike chance by $s1%.", ua = "Підвищує шанс критичного удару на $s1%." },
    { en = "Shadowstep's cooldown is reduced by $s3%, and its maximum range is increased by $s1%.", ua = "Перезарядження «Кроку тіні» зменшено на $s3%, а його максимальну дальність збільшено на $s1%." },
    { en = "Your weapon poisons have $s8% increased application chance and now deal damage as Shadow instead of Nature.\n\n\n\nShadow damage increased by $s2%.", ua = "Ваші зброярські отрути мають на $s8% більший шанс застосування і тепер завдають шкоди як Тіньова замість Природної.\n\n\n\nТіньова шкода збільшена на $s2%." },
    { en = "Remaining out of combat for $470677d increases the duration of your next Shadow Dance by ${$470678s1/1000} sec.", ua = "Перебування поза боєм протягом $470677d збільшує тривалість твого наступного «Танцю тіней» на ${$470678s1/1000} сек." },
    { en = "Shadow Clones deal $s1% increased damage and your effects that have a chance to create them have $s2% additional chance to occur.", ua = "Тіньові клони завдають на $s1% більше шкоди, а твої ефекти, що мають шанс їх створювати, отримують додатковий шанс $s2% спрацювати." },
    { en = "Shroud of Concealment increases the movement speed of allies by $s1% and leaving its area no longer cancels the effect.", ua = "«Покров приховування» збільшує швидкість руху союзників на $s1%, а вихід за межі його дії більше не скасовує ефект." },
    { en = "Shadow Dance increases the critical strike damage bonus of your abilities by $185313s9%.", ua = "«Танець тіней» збільшує бонус шкоди критичних ударів твоїх здібностей на $185313s9%." },
    { en = "Eviscerate and Black Powder deal an additional $s1% damage as Shadow while Find Weakness is active.", ua = "Потрошіння й Чорний порох завдають додатково $s1% шкоди Тінню, поки діє Пошук слабкості." },
    { en = "Find Weakness causes your attacks to ignore an additional $s1% armor.", ua = "Пошук слабкості дозволяє твоїм атакам ігнорувати додатково $s1% броні." },
    { en = "Vanish has $s1 additional $lcharge:charges;.", ua = "Зникнення має $s1 додатковий $lзаряд:заряди:зарядів;." },
    { en = "Movement speed increased by $386237s1% and damage taken reduced by $386237s2% for $386237d after gaining Stealth, Vanish, or Shadow Dance.", ua = "Швидкість руху збільшено на $386237s1%, а отримана шкода зменшена на $386237s2% протягом $386237d після отримання «Непомітності», «Зникнення» або «Танцю тіней»." },
    { en = "Vanish grants you a shield for $386165d, absorbing damage equal to $s1% of your maximum health.", ua = "Зникнення дає тобі щит на $386165d, що поглинає шкоду в розмірі $s1% твого максимального здоров'я." },
    { en = "Shadow damage increased by $383405s1%.", ua = "Шкода темрявою збільшена на $383405s1%." },
    { en = "$?s200758[Gloomblade][Backstab], Shuriken Storm, and Shadowstrike have $1264521s3% increased damage while Find Weakness is active.", ua = "$?s200758[Похмурий клинок][Удар у спину], Буря сюрикенів і Тіньовий удар завдають на $1264521s3% більше шкоди, поки активний Пошук слабкості." },
    { en = "After Shadow Dance ends, $?s200758[Gloomblade][Backstab] deals an additional $s1% damage as Shadow, fading by ${$s1/$s3}.1% per sec.", ua = "Після завершення Танцю тіней $?s200758[Похмурий клинок][Удар у спину] завдає додатково $s1% шкоди як тінню, і цей ефект слабшає на ${$s1/$s3}.1% за секунду." },
    { en = "Eviscerate and Black Powder have $s1% increased critical strike damage bonus.", ua = "Бонус до шкоди критичних ударів Потрошіння й Чорного пороху збільшено на $s1%." },
    { en = "While Shadow Dance is active, each different attack that generates or spends combo points lashes out at the target, dealing $1264397s1 Shadow damage.", ua = "Поки діє Танець тіней, кожна різна атака, що генерує або витрачає очки комбо, шмагає ціль, завдаючи $1264397s1 шкоди тінню." },
    { en = "Enemies hit by Divine Storm take $382538s1% more damage from Consecration and Divine Hammers for $382538d.", ua = "Вороги, уражені «Божественною бурею», отримують на $382538s1% більше шкоди від «Освячення» та «Божественних молотів» протягом $382538d." },
    { en = "When you take any damage, heal for ${$382551s1/10}.1% of your maximum health. \n\n\n\nThis can only occur once every $proccooldown sec.", ua = "Коли ти отримуєш будь-яку шкоду, зцілюєшся на ${$382551s1/10}.1% свого максимального здоров'я. \n\n\n\nЦе може спрацьовувати лише раз на $proccooldown сек." },
    { en = "Nature's Swiftness's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Швидкості природи» скорочується на ${$s1/-1000} сек." },
    { en = "Ironbark's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Залізнокори» скорочується на ${$s1/-1000} сек." },
    { en = "Wild Growth's healing falls off $s1% less over time.", ua = "Зцілення «Дикого росту» слабшає з часом на $s1% менше." },
    { en = "Chain Heal bounces an additional time and its healing is increased by $s2%.", ua = "«Ланцюгове зцілення» перестрибує ще один раз, а його зцілення збільшене на $s2%." },
    { en = "$?c1[Mortal Strike]?c2[Bloodthirst][Shield Slam] deals an additional $?c1[$s1]?c2[$s3][$s5]% damage and deals $?c1[$s2]?c2[$s4][$s6]% increased critical strike damage.", ua = "$?c1[«Смертельний удар»]?c2[«Кровожерливість»][«Удар щитом»] завдає додатково $?c1[$s1]?c2[$s3][$s5]% шкоди і завдає на $?c1[$s2]?c2[$s4][$s6]% більше шкоди критичним ударом." },
    { en = "Maximum Rage increased by ${$s1/10}.", ua = "Максимум люті збільшено на ${$s1/10}." },
    { en = "Increases all Fire and Frost damage you deal by $s1%.", ua = "Збільшує всю шкоду від вогню та морозу, яку ти завдаєш, на $s1%." },
    { en = "Increases your attack speed by $382889s1% for your next $382889n melee swings after dealing a critical strike with a spell or ability.", ua = "Після критичного удару закляттям чи здібністю збільшує швидкість твоєї атаки на $382889s1% для наступних $382889n ударів ближнього бою." },
    { en = "While wielding one-handed weapons your damage is increased by $s1% and Leech increased by $s4%.", ua = "Коли ти озброєний одноручною зброєю, твоя шкода збільшена на $s1%, а висмоктування — на $s4%." },
    { en = "While wielding two-handed weapons your damage is increased by $s1% and damage taken from area of effect attacks is reduced by $s4%.", ua = "Коли ти озброєний дворучною зброєю, твоя шкода збільшена на $s1%, а отримувана шкода від атак по площі зменшена на $s4%." },
    { en = "While dual wielding your damage is increased by $s1% and movement speed is increased by $s4%.", ua = "Коли ти б'єшся парною зброєю, твоя шкода збільшена на $s1%, а швидкість руху — на $s4%." },
    { en = "Stamina increased by $s1% and Armor increased by $s2%.", ua = "Витривалість збільшено на $s1%, а броню — на $s2%." },
    { en = "Haste increased by $s1% and your auto-attack critical strikes increase your auto-attack speed by $s2% for $392778d.", ua = "Поспіх збільшено на $s1%, а критичні удари твоїх автоатак збільшують швидкість автоатак на $s2% на $392778d." },
    { en = "Increases the number of Elemental Shields you can have active on yourself by 1.\n\n\n\nYou can have Earth Shield on yourself and one ally at the same time.", ua = "Збільшує кількість Стихійних щитів, які можуть бути активні на вас, на 1.\n\n\n\nВи можете мати «Земний щит» на собі й на одному союзнику одночасно." },
    { en = "Summons a totem at your feet that removes all Poison effects from a nearby party or raid member within $403922a yards every $383014t1 sec for $d.", ua = "Прикликає тотем біля твоїх ніг, що протягом $d кожні $383014t1 сек. знімає всі ефекти отрути з одного члена групи чи рейду в радіусі $403922a м." },
    { en = "Purify Spirit additionally removes all Curse effects.", ua = "«Очищення духу» додатково знімає всі ефекти проклять." },
    { en = "$?c1[Slam, Whirlwind, and Cleave deal $s1% more damage and $s2% increased critical strike damage.]?c2&s436707[ Thunder Clap, Whirlwind, and Raging Blow deal $s5% more damage and $s6% increased critical strike damage.]?c2[Whirlwind and Raging Blow deal $s5% more damage and $s6% increased critical strike damage.][Revenge deals $s7% more damage and $s8% increased critical strike damage.]", ua = "$?c1[«Удар навідліг», «Вихор» і «Розсікання» завдають на $s1% більше шкоди і на $s2% більше шкоди критичним ударом.]?c2&s436707[ «Громовий удар», «Вихор» і «Лютий удар» завдають на $s5% більше шкоди і на $s6% більше шкоди критичним ударом.]?c2[«Вихор» і «Лютий удар» завдають на $s5% більше шкоди і на $s6% більше шкоди критичним ударом.][«Помста» завдає на $s7% більше шкоди і на $s8% більше шкоди критичним ударом.]" },
    { en = "Reduces magic damage taken by $s1%.", ua = "Зменшує отримувану магічну шкоду на $s1%." },
    { en = "You are healed for $s1% of the Bleed damage dealt by Rend and Deep Wounds.", ua = "Ти зцілюєшся на $s1% шкоди від кровотечі, завданої «Розривом» і «Глибокими ранами»." },
    { en = "Transforms all enemies within $a yards into sheep, wandering around incapacitated for $d. While affected, the victims cannot take actions but will regenerate health very quickly. Damage will cancel the effect.\n\n\n\nOnly works on Beasts, Humanoids and Critters.", ua = "Перетворює всіх ворогів у межах $a ярдів на овець, що знесилено блукають довкола протягом $d. Під дією ефекту жертви не можуть діяти, проте дуже швидко відновлюють здоров'я. Шкода скасовує ефект.\n\n\n\nДіє лише на звірів, гуманоїдів і дрібних створінь." },
    { en = "Rend and Deep Wounds' Bleed effects last $s1% longer and have a $s2% increased critical strike chance.\n\n\n\nIf you know Rend, Mortal Strike inflicts Rend on targets below $s3% health.", ua = "Ефекти кровотечі Шматування та Глибоких ран тривають на $s1% довше й мають на $s2% більший шанс критичного удару.\n\n\n\nЯкщо ти володієш Шматуванням, Смертельний удар накладає Шматування на цілі зі здоров'ям нижче $s3%." },
    { en = "Sweeping Strikes affects $s1 additional damaging single-target abilities.", ua = "«Розмашисті удари» діють на $s1 додаткових здібностей, що завдають шкоди одній цілі." },
    { en = "Rejuvenation healing is increased by up to $s1%, and Tranquility healing is increased by up to $s2%, healing for more on low-health targets.", ua = "Зцілення «Омолодження» збільшено до $s1%, а зцілення «Спокою» — до $s2%; цілі з низьким здоров'ям зцілюються сильніше." },
    { en = "Solar Eclipse increases Wrath damage by an additional $s1%. \n\n\n\nLunar Eclipse increases Starfire damage by an additional $s2%.", ua = "Сонячне затемнення підвищує шкоду Гніву додатково на $s1%. \n\n\n\nМісячне затемнення підвищує шкоду Зоряного вогню додатково на $s2%." },
    { en = "Every $s1th Shooting Star calls down a Full Moon at $s2% effectiveness upon its target.", ua = "Кожна $s1-та «Падаюча зірка» закликає на свою ціль «Повний місяць» з ефективністю $s2%." },
    { en = "$?a455630[Surging Totem][Healing Rain] instantly restores $383223s1 health to $s3 allies within its area, and its radius is increased by $s1 $Lyard:yards;.", ua = "$?a455630[Вируючий тотем][Зцілющий дощ] миттєво відновлює $383223s1 здоров'я $s3 союзникам у своїй області, а його радіус збільшено на $s1 $Lметр:метри:метрів;." },
    { en = "Reduces the cooldown of Judgment by ${$s1/-1000} sec and Crusader Strike by ${$s2/-1000} sec.", ua = "Скорочує перезарядження «Осуду» на ${$s1/-1000} сек., а «Удару хрестоносця» — на ${$s2/-1000} сек." },
    { en = "Ambush has a chance to grant Opportunity. Chance to trigger this effect is $s1% of the chance for Sinister Strike to grant Opportunity.", ua = "«Засідка» має шанс дати «Нагоду». Шанс спрацювання цього ефекту становить $s1% від шансу «Підступного удару» дати «Нагоду»." },
    { en = "Your Bleed effects deal $s1% increased damage and $s2% increased critical strike damage.", ua = "Твої ефекти кровотечі завдають на $s1% більше шкоди та на $s2% більше шкоди критичними ударами." },
    { en = "Bloodthirst's critical strike chance increased by $s1% and if you are Enraged, Bloodthirst extends your Enrage by ${$s2/1000}.1 sec. This extension is doubled if Bloodthirst critically strikes your primary target.", ua = "Шанс критичного удару Кровожерності збільшено на $s1%, а якщо ти в стані Шалу, Кровожерність подовжує твій Шал на ${$s2/1000}.1 сек. Це подовження подвоюється, якщо Кровожерність завдає критичного удару твоїй основній цілі." },
    { en = "Raging Blow's critical strike chance increased by $s1% and critical strike damage increased by $s2%.", ua = "Імовірність критичного удару «Лютого удару» збільшено на $s1%, а його шкоду від критичних ударів — на $s2%." },
    { en = "Unleashes a powerful weapon strike that deals $s1 $?s403664[Holystrike][Holy] damage to an enemy target,\n\n\n\nFinal Verdict has a $s2% chance to reset the cooldown of Judgment.", ua = "Завдає потужного удару зброєю, що завдає $s1 $?s403664[священної][шкоди Світлом] ворожій цілі.\n\n\n\nОстаточний вердикт має $s2% шансу скинути перезарядження Судження." },
    { en = "Mortal Strike, Cleave, and Execute damage increased by $s1% and critical strike damage increased by $s2%.", ua = "Шкоду «Смертельного удару», «Розсікання» та «Страти» збільшено на $s1%, а їхню шкоду від критичних ударів — на $s2%." },
    { en = "Blade of Justice generates $s1 additional Holy Power.", ua = "«Клинок правосуддя» породжує додатково $s1 од. святої сили." },
    { en = "Your Blade of Justice causes the target to burn for $383346o1 $?s403665[Holy][Radiant] damage over $383346d. When reapplied, any remaining damage is added to the new effect.", ua = "Твій «Клинок правосуддя» змушує ціль горіти, завдаючи $383346o1 $?s403665[святої][променистої] шкоди протягом $383346d. При повторному застосуванні решта шкоди додається до нового ефекту." },
    { en = "Maximum Energy increased by $s1 and Energy regeneration increased by $s2%.", ua = "Максимум енергії збільшено на $s1, а відновлення енергії — на $s2%." },
    { en = "Your haste is increased by $s1%.", ua = "Твій поспіх збільшено на $s1%." },
    { en = "Fire Blast increases your mastery by ${$383395s1}% for $383395d. Multiple applications may overlap.", ua = "«Вогняний вибух» збільшує твою майстерність на ${$383395s1}% на $383395d. Кілька застосувань можуть накладатися." },
    { en = "Divine Storm projects an additional wave of light, striking all enemies up to $s1 yds in front of you for $s2% of Divine Storm's damage.", ua = "«Божественна буря» випускає додаткову хвилю світла, що вражає всіх ворогів на відстані до $s1 м перед тобою, завдаючи $s2% шкоди «Божественної бурі»." },
    { en = "Critical strike damage of your abilities is increased by $s1%.", ua = "Шкоду критичних ударів твоїх здібностей збільшено на $s1%." },
    { en = "Enraged Regeneration lasts ${$s1/1000} sec longer and instantly heals for $s2% of your maximum health.", ua = "Розлючена регенерація триває на ${$s1/1000} сек. довше та миттєво зцілює на $s2% від твого максимального здоров'я." },
    { en = "While Enraged, your auto-attacks can no longer miss.", ua = "Поки діє «Розлюченість», твої автоатаки більше не можуть схибити." },
    { en = "While Combustion is active, Fire Blast recharges $383637s1% faster.", ua = "Поки діє «Згоряння», «Вогняний удар» перезаряджається на $383637s1% швидше." },
    { en = "Damaging an enemy with Fireball, Pyroblast, or Flamestrike increases the damage it receives from Ignite by ${$s2/100}.1%. Stacks up to $453268u times.", ua = "Завдання шкоди ворогу «Вогняною кулею», «Піровибухом» або «Ударом полум'я» збільшує шкоду, яку він отримує від «Займання», на ${$s2/100}.1%. Складається до $453268u разів." },
    { en = "Arcane Blast and Arcane Pulse generate an additional Arcane Charge.", ua = "«Арканний вибух» та «Арканний імпульс» створюють додатковий арканний заряд." },
    { en = "Blackout Kick deals $s1% increased damage.", ua = "«Удар затьмарення» завдає на $s1% більше шкоди." },
    { en = "When you use Keg Smash, the remaining cooldown on Breath of Fire is reset.", ua = "Коли ти використовуєш «Удар барилом», перезарядження «Подиху вогню» скидається." },
    { en = "Keg Smash deals an additional $s1% damage to targets affected by Breath of Fire.", ua = "«Удар барилом» завдає на $s1% більше шкоди цілям під дією «Подиху вогню»." },
    { en = "Purifying Brew instantly heals you for $s1% of the |CFFffffffStaggered|R damage it clears.", ua = "«Очисне вариво» миттєво зцілює тебе на $s1% |CFFffffffвідстроченої|R шкоди, яку воно знімає." },
    { en = "Mortal Strike has a $s1% chance to apply a Fatal Mark to your target, stacking up to $383704u times. Your next Execute on a target with a Fatal Mark causes the Fatal Mark to deal $383706s1 additional Physical damage per stack.", ua = "«Смертельний удар» з імовірністю $s1% накладає на твою ціль «Фатальну мітку», що накопичується до $383704u разів. Твоя наступна «Страта» по цілі з «Фатальною міткою» змушує мітку завдати $383706s1 додаткової фізичної шкоди за кожен заряд." },
    { en = "Keg Smash deals $m1% additional damage to its primary target, has $m2 additional $Lcharge:charges;, and its range is increased by $s3 yards.", ua = "Удар барилом завдає на $m1% більше шкоди основній цілі, має $m2 додаткових $Lзаряд:заряди:зарядів;, а його дальність збільшена на $s3 ярдів." },
    { en = "Gain up to ${$s1*$s3}% Mastery based on your current level of Stagger.", ua = "Отримуй до ${$s1*$s3}% майстерності залежно від поточного рівня відтермінування шкоди." },
    { en = "Each time you dodge or an enemy misses you, your next Tiger Palm or Spinning Crane Kick deals $383800s1% increased damage.", ua = "Щоразу, коли ти ухиляєшся або ворог промахується по тобі, твоя наступна «Тигряча долоня» чи «Обертовий удар журавля» завдає на $383800s1% більше шкоди." },
    { en = "Each consecutive critical strike you deal increases critical strike damage you deal by $s1%, up to ${ $s1*$383811u}% for $383811d.", ua = "Кожен твій послідовний критичний удар збільшує шкоду твоїх критичних ударів на $s1%, аж до ${ $s1*$383811u}%, на $383811d." },
    { en = "Enrage increases your haste by $184362s1% and your movement speed by $184362s2%.", ua = "Розлюченість збільшує твій поспіх на $184362s1%, а швидкість руху — на $184362s2%." },
    { en = "Bloodthirst and Raging Blow damage increased by ${$s1/10}.1% and critical strike damage increased by ${$s2/10}.1%.", ua = "Шкода «Жаги крові» та «Лютого удару» збільшена на ${$s1/10}.1%, а їхня шкода від критичних ударів — на ${$s2/10}.1%." },
    { en = "Raging Blow has ${$s1+1} charges and has a $85288s1% chance to instantly reset its own cooldown.", ua = "«Лютий удар» має ${$s1+1} заряди та з імовірністю $85288s1% миттєво скидає власне перезарядження." },
    { en = "Rampage has a $h% chance to refund a charge of Raging Blow.", ua = "«Буйство» з імовірністю $h% повертає заряд «Лютого удару»." },
    { en = "Bloodthirst deals $s1% increased damage to enemies who are below $<threshold>% health.", ua = "Жага крові завдає на $s1% більше шкоди ворогам, що мають менше $<threshold>% здоров'я." },
    { en = "Bloodthirst critical strikes generate ${$383978s1/10} additional Rage and inflict a Gushing Wound that deals $385042o Bleed damage over $385042d and heals you for the damage dealt.", ua = "Критичні удари «Жаги крові» генерують додатково ${$383978s1/10} люті та завдають «Зяючу рану», яка завдає $385042o шкоди кровотечею протягом $385042d і зцілює тебе на величину завданої шкоди." },
    { en = "Combustion grants mastery equal to $s1% of your Critical Strike stat.\n\n\n\nCombustion causes your spells to apply Ignite at $s2% increased effectiveness.", ua = "Займання надає майстерності, що дорівнює $s1% вашого критичного удару.\n\n\n\nЗаймання змушує ваші закляття накладати Підпалення з ефективністю, збільшеною на $s2%." },
    { en = "Your Haste is increased by $s1%.", ua = "Твій Поспіх збільшено на $s1%." },
    { en = "Breath of Fire deals $s2% increased damage, and after using Breath of Fire, you breathe fire $s1 additional times, each dealing $387621s1 Fire damage.", ua = "«Подих вогню» завдає на $s2% більше шкоди, а після його використання ти видихаєш вогонь ще $s1 раз(ів), щоразу завдаючи $387621s1 шкоди вогнем." },
    { en = "$?c1[After casting Divine Toll, you instantly cast Holy Shock every $384029t1 sec for $384029s2 sec.]?c2[After casting Divine Toll, you instantly cast Avenger's Shield every $384029t1 sec for $384029s2 sec.]?c3[After casting Divine Toll, your next $1266308u Judgments cast again at $1266308s2% effectiveness.][]", ua = "$?c1[Після застосування Божественного дзвону ви миттєво застосовуєте Священний шок кожні $384029t1 с протягом $384029s2 с.]?c2[Після застосування Божественного дзвону ви миттєво застосовуєте Щит месника кожні $384029t1 с протягом $384029s2 с.]?c3[Після застосування Божественного дзвону ваші наступні $1266308u Вироки застосовуються повторно з $1266308s2% ефективністю.][]" },
    { en = "$s1% of damage you deal adds to your active Ignore Pain or the next Ignore Pain you activate.\n\n\n\nYour next Ignore Pain can be increased by up to ${$mhp*($190456s4/100)*($s2/100)}.", ua = "$s1% завданої тобою шкоди додається до твого активного Ігнорування болю або до наступного Ігнорування болю, яке ти активуєш.\n\n\n\nТвоє наступне Ігнорування болю може бути збільшене до ${$mhp*($190456s4/100)*($s2/100)}." },
    { en = "Devastate, Thunder Clap, Revenge, and Execute have a $236279s2% chance to reset the remaining cooldown on Shield Slam.", ua = "Спустошення, Удар грому, Помста та Страта мають $236279s2% шансу скинути залишок перезарядження Удару щитом." },
    { en = "Clearcasting has a $s1% increased chance to proc.", ua = "Шанс спрацювання «Чистого чарування» збільшено на $s1%." },
    { en = "Increases Stamina by $s1% and your Haste by $s2%.", ua = "Збільшує витривалість на $s1%, а твій поспіх — на $s2%." },
    { en = "Increases Strength by $s1% and your critical strike chance by $s2%.", ua = "Збільшує силу на $s1%, а твій шанс критичного удару — на $s2%." },
    { en = "Shield Slam reduces the remaining cooldown of Shield Wall by $s1 sec.", ua = "«Удар щитом» скорочує час перезарядження «Стіни щитів», що залишився, на $s1 сек." },
    { en = "Go berserk, removing and granting immunity to Fear, Sap, and Incapacitate effects for $d.\n\n\n\nAlso remove fear effects from$?a1227751[ and reduce the duration of the next crowd control effect within $1219209d by $1219209s1% on][] group members within $384102A1 yds.", ua = "Впадіть у нестяму, знімаючи й даруючи несприйнятливість до ефектів Страху, Присипляння та Знесилення протягом $d.\n\n\n\nТакож знімає ефекти страху з$?a1227751[ та зменшує тривалість наступного ефекту контролю протягом $1219209d на $1219209s1% для][] членів групи в радіусі $384102A1 м." },
    { en = "Hurl your weapon at the enemy, causing $394354s2 Physical damage, ignoring armor. Deals up to $394354s3% increased damage to absorb shields.", ua = "Жбурляєш свою зброю у ворога, завдаючи $394354s2 фізичної шкоди, ігноруючи броню. Завдає до $394354s3% більше шкоди поглинальним щитам." },
    { en = "Gain Strength equal to $?c3[$s3][$s2]% of your Armor.", ua = "Отримуйте Силу, що дорівнює $?c3[$s3][$s2]% вашої Броні." },
    { en = "Maelstrom Weapon can now stack $s1 additional times.\n\n\n\nEach Maelstrom Weapon stacks consumed grants Overflowing Maelstrom, reducing the cast time of your next Healing Surge or Chain Heal by $s3%, and increasing their healing by $s4% up to $s5 times. This effect can be accumulated up to $410681u times.", ua = "«Зброя виру» тепер може накопичуватися додатково $s1 разів.\n\n\n\nКожен витрачений заряд «Зброї виру» надає «Переповнений вир», що скорочує час прочитання вашого наступного «Сплеску зцілення» чи «Ланцюгового зцілення» на $s3% і збільшує їхнє зцілення на $s4%, до $s5 разів. Цей ефект може накопичуватися до $410681u разів." },
    { en = "Lightning Bolt and Chain Lightning can consume up to $s1 Maelstrom Weapon stacks.", ua = "«Блискавка» та «Ланцюгова блискавка» можуть споживати до $s1 зарядів «Зброї виру»." },
    { en = "Ignite deals $s1% more damage when Combustion is not active.\n\n\n\nFire Blast now spreads an additional $s2% of your Ignite.", ua = "Підпалення завдає на $s1% більше шкоди, коли Займання не активне.\n\n\n\nВогняний вибух тепер поширює додаткові $s2% вашого Підпалення." },
    { en = "Unleash a devastating storm around yourself, dealing $469270s1 Stormstrike damage every $466772s5 sec to nearby enemies for $466772d.\n\n\n\nIncreases your chance to activate Windfury Weapon by $466772s1%, and the damage of Windfury Weapon by $466772s2%.", ua = "Вивільняє довкола вас нищівну бурю, завдаючи $469270s1 шкоди Удару бурі кожні $466772s5 сек ворогам поблизу впродовж $466772d.\n\n\n\nЗбільшує ваш шанс активувати Зброю шаленства вітру на $466772s1% і шкоду Зброї шаленства вітру на $466772s2%." },
    { en = "Each active weapon imbue increases all Fire, Frost, and Nature damage dealt by ${$s1/10}.1%.", ua = "Кожне активне просочення зброї збільшує всю завдану шкоду від вогню, морозу та природи на ${$s1/10}.1%." },
    { en = "Damage from Rend has a chance to generate ${$384362s1/10} Rage.", ua = "Шкода від Розриву має шанс згенерувати ${$384362s1/10} люті." },
    { en = "Each target hit by Crash Lightning increases the damage of your next Stormstrike by $198300s1%, up to a maximum of $198300u stacks.", ua = "Кожна ціль, уражена «Грозовим ударом», збільшує шкоду твого наступного «Удару бурі» на $198300s1%, щонайбільше $198300u зарядів." },
    { en = "During Doom Winds or Ascendance, you generate $s1 Maelstrom Weapon $lstack:stacks; every $384437t1 sec.", ua = "Під час Згубних вітрів або Піднесення ви генеруєте $s1 $lзаряд:заряди; Зброї виру кожні $384437t1 с." },
    { en = "Doom Winds and Deeply Rooted Elements last ${$s5/1000} sec longer, and the cooldown of Ascendance is reduced by ${$s4/-1000} sec.\n\n\n\nDuring Doom Winds or Ascendance, Stormstrike and Crash Lightning consume up to $s1 Maelstrom Weapon to discharge a Lightning Bolt or Chain Lightning at $s2% effectiveness at your enemy, whichever you most recently used.", ua = "«Вітри судьби» та «Глибоко вкорінені стихії» тривають на ${$s5/1000} сек. довше, а перезарядження «Піднесення» скорочується на ${$s4/-1000} сек.\n\n\n\nПід час «Вітрів судьби» або «Піднесення» «Штормовий удар» і «Громовиця» витрачають до $s1 «Зброї виру», щоб вивільнити «Блискавку» чи «Ланцюгову блискавку» з $s2% ефективністю по вашому ворогу — те, що ви застосували останнім." },
    { en = "Consuming $s2 stacks of Maelstrom Weapon increases the damage of your next Stormstrike or Lava Lash by $384451s1% and causes them to generate a stack of Maelstrom Weapon.", ua = "Витрата $s2 зарядів «Зброї Виру» збільшує шкоду твого наступного «Удару бурі» чи «Лавового батога» на $384451s1% і змушує їх генерувати заряд «Зброї Виру»." },
    { en = "Each wave of Arcane Missiles increases the damage of Arcane Barrage by $1242974s1%, up to ${$1242974s1*$1242974u}%.", ua = "Кожна хвиля «Арканних снарядів» збільшує шкоду «Арканного обстрілу» на $1242974s1%, аж до ${$1242974s1*$1242974u}%." },
    { en = "Arcane Charges increase the damage of Arcane Blast, Arcane Pulse, and Arcane Barrage by an additional $s1%.", ua = "Арканні заряди збільшують шкоду «Арканного вибуху», «Арканного імпульсу» та «Арканного обстрілу» на додаткові $s1%." },
    { en = "Arcane Orb gains $s1 additional charge. Arcane Orb damage increased by $s2%.", ua = "«Арканна сфера» отримує $s1 додатковий заряд. Шкода «Арканної сфери» збільшена на $s2%." },
    { en = "Ferocious Bite deals $s1% increased damage and an additional $s2% during Tiger's Fury.", ua = "«Лютий укус» завдає на $s1% більше шкоди, та ще на $s2% більше під час «Люті тигра»." },
    { en = "Finishing moves have a $s1% chance per combo point spent to increase the direct damage of your next Rake, Shred, or Swipe by $1244483s2% and make it critically strike.", ua = "Завершальні прийоми мають $s1% шансу за кожне витрачене очко комбо збільшити пряму шкоду твого наступного «Дряпання», «Шматування» чи «Розмаху» на $1244483s2% і зробити удар критичним." },
    { en = "Damage taken from area of effect attacks reduced by $s1%.", ua = "Шкода від атак по області зменшена на $s1%." },
    { en = "When you cast Word of Glory on someone other than yourself, you are also healed for $s1% of the amount healed.", ua = "Коли ти твориш «Слово слави» на когось іншого, а не на себе, ти також зцілюєшся на $s1% від обсягу зцілення." },
    { en = "Reduces the cooldown of Blessing of Sacrifice by ${$m1/-1000} sec.", ua = "Скорочує перезарядження «Благословення жертовності» на ${$m1/-1000} сек." },
    { en = "Arcane Barrage has a $s1% chance per stack of Arcane Salvo to launch an Arcane Orb in front of you at $s2% effectiveness.", ua = "«Арканний шквал» має $s1% шансу за кожен заряд «Арканного залпу» запустити перед тобою арканну сферу з $s2% ефективності." },
    { en = "Reduces the cooldown of Blessing of Protection$?c2[ and Blessing of Spellwarding][] by ${-$s1/1000} sec.", ua = "Зменшує перезарядження «Благословення захисту»$?c2[ та «Благословення чарооберегу»][] на ${-$s1/1000} сек." },
    { en = "After your Blessing of Sacrifice ends, $s1% of the total damage it diverted is added to your next Judgment as bonus damage, or your next Word of Glory as bonus healing.\n\n\n\nThis effect's bonus damage cannot exceed $s3% of your maximum health and its bonus healing cannot exceed $s4% of your maximum health.", ua = "Після завершення «Благословення жертовності» $s1% усієї відведеної ним шкоди додається до вашого наступного «Осуду» як бонусна шкода або до вашого наступного «Слова слави» як бонусне зцілення.\n\n\n\nБонусна шкода цього ефекту не може перевищувати $s3% вашого максимального здоров'я, а бонусне зцілення не може перевищувати $s4% вашого максимального здоров'я." },
    { en = "Unleashes your power, dealing $<dmg> Physical damage and an additional $385060o2 Bleed damage over $385060d to all enemies within $385060A2 yards. Deals reduced damage beyond $s6 targets.\n\n\n\n|cFFFFFFFFEnrages you and generates ${$s5/10} Rage.|r", ua = "Вивільняє твою силу, завдаючи $<dmg> фізичної шкоди й додатково $385060o2 шкоди кровотечею протягом $385060d усім ворогам у межах $385060A2 м. Завдає зменшеної шкоди після $s6 цілей.\n\n\n\n|cFFFFFFFFРозлючує тебе й створює ${$s5/10} люті.|r" },
    { en = "Casting Frozen Orb grants $s1 $Lstack:stacks; of Fingers of Frost.\n\n\n\nDamaging one or more enemies with Frozen Orb has a $s2% chance to grant Fingers of Frost.", ua = "Творіння Замороженої сфери надає $s1 $Lзаряд:заряди:зарядів; Пальців морозу.\n\n\n\nЗавдання шкоди одному чи більше ворогам Замороженою сферою має $s2% шансу надати Пальці морозу." },
    { en = "After you spend $s3 Holy Power, your next Word of Glory echoes onto a nearby ally at $s1% effectiveness.", ua = "Після того як ти витратиш $s3 од. святої сили, твоє наступне «Слово слави» відлунює на союзника поблизу з $s1% ефективності." },
    { en = "Speed increased by $s3% and damage taken from area of effect attacks reduced by $s2%.", ua = "Швидкість збільшена на $s3%, а шкода від атак по площі знижена на $s2%." },
    { en = "Mastery increased by $s2% and $?c1[Intellect][Strength] increased by $s1%.", ua = "Майстерність збільшена на $s2%, а $?c1[Інтелект][Сила] — на $s1%." },
    { en = "Garrote damage increased by $s1%. Garrote generates $s2 additional combo points when used from Stealth.", ua = "Шкода «Гароти» збільшена на $s1%. «Гарота» генерує на $s2 більше комбо-очок, якщо застосована з непомітності." },
    { en = "Armor and critical strike chance increased by $s2%.", ua = "Броню та шанс критичного удару збільшено на $s2%." },
    { en = "Exhilaration now also heals you for an additional ${$s1}.1% of your maximum health over $385540d.", ua = "«Наснага» тепер додатково відновлює тобі ${$s1}.1% максимального здоров'я протягом $385540d." },
    { en = "Overpower has ${1+$s2} charges and deals $s1% more damage.", ua = "«Пересилення» має ${1+$s2} заряди та завдає на $s1% більше шкоди." },
    { en = "Release a powerful poison from your weapons and inject it into your target, dealing $s2 Nature damage instantly and an additional $o4 Nature damage over $d. \n\n\n\nEach time you apply a Lethal Poison to a target affected by Kingsbane, Kingsbane damage increases by $394095s1%, up to ${$394095s1*$394095u}%.\n\n\n\n|cFFFFFFFFAwards $s6 combo $lpoint:points;.|r", ua = "Вивільняє з твоєї зброї потужну отруту і впорскує її в ціль, миттєво завдаючи $s2 шкоди як Природа та ще $o4 шкоди як Природа протягом $d. \n\n\n\nЩоразу, коли ти накладаєш Смертельну отруту на ціль під дією «Згуби королів», шкода «Згуби королів» зростає на $394095s1%, до ${$394095s1*$394095u}%.\n\n\n\n|cFFFFFFFFНадає $s6 $lочко комбо:очок комбо;.|r" },
    { en = "Learn Concentration Aura, Devotion Aura, and Crusader Aura:\n\n\n\n$@spellicon317920$@spellname317920:\n\n$@spelldesc317920\n\n\n\n$@spellicon465 $@spellname465:\n\n$@spelldesc465\n\n\n\n$@spellicon32223 $@spellname32223:\n\n$@spelldesc32223", ua = "Вивчає Ауру зосередження, Ауру відданості та Ауру хрестоносця:\n\n\n\n$@spellicon317920$@spellname317920:\n\n$@spelldesc317920\n\n\n\n$@spellicon465 $@spellname465:\n\n$@spelldesc465\n\n\n\n$@spellicon32223 $@spellname32223:\n\n$@spelldesc32223" },
    { en = "Empower spells cause time to flow $s1% faster for you, increasing movement speed, cooldown recharge rate, and cast speed. Lasts $390148d.", ua = "Підсилювані закляття змушують час плинути для тебе на $s1% швидше, збільшуючи швидкість руху, відновлення перезаряджень і швидкість творення заклять. Триває $390148d." },
    { en = "Bloodthirst causes your Bleeds to deal $1265406s1% additional damage for $1265406d.", ua = "«Жага крові» змушує твої ефекти кровотечі завдавати на $1265406s1% більше шкоди протягом $1265406d." },
    { en = "Your Deep Wounds and Rend deal $s1% increased damage.", ua = "Твої «Глибокі рани» та «Розрив» завдають на $s1% більше шкоди." },
    { en = "Gaining Stealth, Vanish, or Shadow Dance causes your next Shuriken Storm to have $385727s1% increased chance to critically strike.", ua = "Отримання «Непомітності», «Зникнення» чи «Танцю тіней» дає твоїй наступній «Бурі сюрикенів» на $385727s1% більший шанс критичного удару." },
    { en = "Each stack of Mongoose Fury also increases the damage of Strike as One by $s1%.", ua = "Кожен заряд «Люті мангуста» також збільшує шкоду «Удару в унісон» на $s1%." },
    { en = "When you use Barkskin or Survival Instincts, absorb $<shield> damage for $385787d.", ua = "Коли ти використовуєш «Кору» чи «Інстинкти виживання», то поглинаєш $<shield> шкоди протягом $385787d." },
    { en = "Dire Beast lasts an additional ${$m1/1000} sec and deals $s2% increased damage.", ua = "«Лютий звір» діє на ${$m1/1000} сек. довше та завдає на $s2% більше шкоди." },
    { en = "Increases the radius of Demoralizing Shout by $s3 yards.\n\n\n\nEach enemy hit by Thunder Clap reduces the remaining cooldown on Demoralizing Shout by ${$s1/1000}.1 sec, up to ${$s1*$s2/1000}.1 sec.", ua = "Збільшує радіус Деморалізуючого крику на $s3 м.\n\n\n\nКожен ворог, уражений Громовим ляском, зменшує залишкове перезарядження Деморалізуючого крику на ${$s1/1000}.1 сек., до ${$s1*$s2/1000}.1 сек." },
    { en = "Your primary pets gain a bonus effect.\n\n\n\n|cFFFFFFFFImp|r: Successful Singe Magic casts grant the target $386869s1% damage reduction for $386869d.\n\n\n\n|cFFFFFFFFVoidwalker|r: Reduces the cooldown of Shadow Bulwark by ${$abs($s2/1000)} sec.\n\n\n\n|cFFFFFFFFFelhunter|r: Reduces the cooldown of Devour Magic by ${$abs($s3/1000)} sec.\n\n\n\n|cFFFFFFFFSayaad|r: Reduces the cooldown of Seduction by ${$abs($s4/1000)} sec and causes the target to walk faster towards the demon.$?s137044[\n\n\n\n|cFFFFFFFFFelguard|r: Reduces the cooldown of Pursuit by ${$abs($s6/1000)} sec and increases its maximum range by $s7 yards.][]", ua = "Ваші основні улюбленці отримують додатковий ефект.\n\n\n\n|cFFFFFFFFБіс|r: Успішні прочитання Обпалення магії дають цілі $386869s1% зменшення шкоди на $386869d.\n\n\n\n|cFFFFFFFFБлукач Порожнечі|r: Скорочує перезарядження Тіньового бастіону на ${$abs($s2/1000)} сек.\n\n\n\n|cFFFFFFFFМисливець Скверни|r: Скорочує перезарядження Пожирання магії на ${$abs($s3/1000)} сек.\n\n\n\n|cFFFFFFFFСайаад|r: Скорочує перезарядження Спокушання на ${$abs($s4/1000)} сек і змушує ціль швидше йти до демона.$?s137044[\n\n\n\n|cFFFFFFFFСтраж Скверни|r: Скорочує перезарядження Переслідування на ${$abs($s6/1000)} сек і збільшує його максимальну дальність на $s7 м.][]" },
    { en = "Blocking an attack deals $385890s1 Physical damage to the attacker. Critical blocks deal double damage.\n\n\n\nGenerates high threat.", ua = "Блокування атаки завдає $385890s1 фізичної шкоди нападнику. Критичні блокування завдають подвійної шкоди.\n\n\n\nСтворює високу загрозу." },
    { en = "Consumes a Soul Shard, unlocking the hidden power of your spells.\n\n\n\n|cFFFFFFFFDemonic Circle: Teleport|r: Increases your movement speed by $387633s1% and makes you immune to snares and roots for $387633d.\n\n\n\n|cFFFFFFFFDemonic Gateway|r: Can be cast instantly.\n\n\n\n|cFFFFFFFFDrain Life|r: Gain an absorb shield equal to the amount of healing done for $387630d. This shield cannot exceed $387630s1% of your maximum health.\n\n\n\n|cFFFFFFFFHealthstone|r: Increases the healing of your Healthstone by $387626s2% and increases your maximum health by $387636s1% for $387636d.", ua = "Поглинає Уламок душі, вивільняючи приховану силу ваших заклять.\n\n\n\n|cFFFFFFFFДемонічне коло: телепортація|r: збільшує вашу швидкість пересування на $387633s1% і робить вас несприйнятливими до сповільнень та знерухомлень на $387633d.\n\n\n\n|cFFFFFFFFДемонічна брама|r: можна творити миттєво.\n\n\n\n|cFFFFFFFFВисмоктування життя|r: дає поглинальний щит, рівний обсягу завданого зцілення, на $387630d. Цей щит не може перевищувати $387630s1% вашого максимального здоров'я.\n\n\n\n|cFFFFFFFFКамінь здоров'я|r: збільшує зцілення вашого Каменя здоров'я на $387626s2% і збільшує ваше максимальне здоров'я на $387636s1% впродовж $387636d." },
    { en = "Charge to an enemy with your shield, granting you Shield Block and dealing $385954s1 Physical damage to it and $385954s2 Physical damage to all enemies within 10 yards.\n\n\n\nAlso stuns the primary target for $385954d.\n\n\n\n|cFFFFFFFFGenerates ${$385954s4/10} Rage.|r", ua = "Кидаєшся на ворога зі щитом, отримуючи Блокування щитом і завдаючи йому $385954s1 фізичної шкоди, а також $385954s2 фізичної шкоди всім ворогам у межах 10 м.\n\n\n\nТакож приголомшує основну ціль на $385954d.\n\n\n\n|cFFFFFFFFСтворює ${$385954s4/10} люті.|r" },
    { en = "Increases Block chance by $s1% and your Block value by $s2%.", ua = "Збільшує шанс блоку на $s1%, а показник блоку — на $s2%." },
    { en = "Shield Block lasts ${$s1/1000} sec longer.", ua = "«Блок щитом» триває на ${$s1/1000} сек. довше." },
    { en = "Using Shield Slam increases the damage of Shield Slam by $386029s1% and the block value of your shield by $386029s2% for $386029d. Stacking up to $386029u times.", ua = "Використання «Удару щитом» збільшує шкоду «Удару щитом» на $386029s1%, а показник блокування твого щита — на $386029s2% на $386029d. Складається до $386029u разів." },
    { en = "Taunts all enemies within $A1 yds to attack you for $d, interrupts all spellcasting within $A1 yds and prevents any spell in that school from being cast for $d. Increases the threat you generate against the target by $s2%.", ua = "Провокує всіх ворогів у радіусі $A1 м атакувати тебе протягом $d, перериває читання заклять у радіусі $A1 м і не дає творити закляття цієї школи протягом $d. Збільшує загрозу, яку ти створюєш проти цілі, на $s2%." },
    { en = "Reduces the damage dealt by Burning Rush by ${$abs($s1)}%. Burning Rush increases your movement speed by an additional $s2%.", ua = "Зменшує шкоду від «Палаючого ривка» на ${$abs($s1)}%. «Палаючий ривок» збільшує твою швидкість руху ще на $s2%." },
    { en = "Reduces the cooldown of Fel Domination by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Панування Скверни» на ${$s1/-1000} сек." },
    { en = "When Soul Leech absorbs damage, $s1% of damage taken is absorbed and spread out over $387847d.\n\n\n\nReduces damage taken by ${$s4/10}.1%.", ua = "Коли Висмоктування душі поглинає шкоду, $s1% отриманої шкоди поглинається й розподіляється на $387847d.\n\n\n\nЗменшує отриману шкоду на ${$s4/10}.1%." },
    { en = "A balanced combat state that increases the critical strike chance of your abilities by $s1%$?a1280961[, the critical strike damage of your abilities by $s4%,][] and reduces the duration of movement impairing effects by $s2%. \n\n\n\nLasts until canceled.", ua = "Урівноважений бойовий стан, що підвищує шанс критичного удару ваших здібностей на $s1%$?a1280961[, критичну шкоду ваших здібностей на $s4%,][] і зменшує тривалість ефектів, що сповільнюють рух, на $s2%. \n\n\n\nТриває до скасування." },
    { en = "Hand of Gul'dan has a $s1% chance to generate a charge of Demonic Core.", ua = "«Рука Ґул'дана» з імовірністю $s1% створює заряд «Демонічного ядра»." },
    { en = "Your Dreadstalkers' attacks have a $s1% chance to trigger an additional Dreadbite.", ua = "Атаки твоїх ловчих жаху мають $s1% шансу спричинити додатковий «Укус жаху»." },
    { en = "An aggressive combat state that increases the damage of your auto-attacks by $s1%$?a1280961[, your auto-attack speed by $s6%,][] and reduces the duration of Fear, Sap and Incapacitate effects on you by $s2%.\n\n\n\nLasts until canceled.", ua = "Агресивний бойовий стан, що підвищує шкоду ваших автоатак на $s1%$?a1280961[, швидкість ваших автоатак на $s6%,][] і зменшує тривалість ефектів Страху, Підступного удару та Знесилення на вас на $s2%.\n\n\n\nТриває до скасування." },
    { en = "A defensive combat state that reduces all damage you take by $s1%$?a452494[ and all magic damage you take by an additional $s3%][]$?a137048[][ and all damage you deal by $s2%].$?a1280961[\n\n\n\nWhen an attack deals $s5% or more of your maximum health in damage, that damage is reduced by $s6%.][]\n\n\n\nLasts until canceled.", ua = "Захисний бойовий стан, що зменшує всю отримувану вами шкоду на $s1%$?a452494[ і всю отримувану вами магічну шкоду додатково на $s3%][]$?a137048[][ і всю завдавану вами шкоду на $s2%].$?a1280961[\n\n\n\nКоли атака завдає шкоди на $s5% чи більше вашого максимального здоров'я, ця шкода зменшується на $s6%.][]\n\n\n\nТриває до скасування." },
    { en = "Essence Burst increases the damage of affected spells by ${$s1}.1%.", ua = "«Вибух есенції» збільшує шкоду відповідних заклять на ${$s1}.1%." },
    { en = "While channeling Disintegrate your Fire Breath on the target deals damage $s1% more often.", ua = "Під час творення Дезінтеграції твій Вогняний подих завдає цілі шкоди на $s1% частіше." },
    { en = "Deep Breath's cooldown is reduced by 1 min.", ua = "Перезарядження Глибокого подиху скорочено на 1 хв." },
    { en = "When your health is brought below $s1%, you take $386397s1% less damage for $386397d and healing you receive is increased by $386397s2%.\n\n\n\nCannot occur more than once every $456447d.", ua = "Коли твоє здоров'я падає нижче $s1%, ти отримуєш на $386397s1% менше шкоди протягом $386397d, а зцілення, яке ти отримуєш, збільшується на $386397s2%.\n\n\n\nНе може спрацьовувати частіше, ніж раз на $456447d." },
    { en = "Your Living Flame and Emerald Blossom are $s1% more effective on yourself.", ua = "Твої Живе полум'я та Смарагдовий цвіт на $s1% ефективніші, коли діють на тебе." },
    { en = "Every $s1 rage you spend triggers a Violent Outburst, causing your next Shield Slam to deal $386478s1% increased damage, generate $386478s2% more Rage and grant Ignore Pain.", ua = "Кожні $s1 од. витраченої люті викликають Шалений спалах: твій наступний Удар щитом завдає на $386478s1% більше шкоди, генерує на $386478s2% більше люті й дає Ігнорування болю." },
    { en = "Increases you and your pets' maximum health by $s1%.", ua = "Збільшує максимальне здоров'я твоє і твоїх улюбленців на $s1%." },
    { en = "Every $s1 strikes of Bladestorm, you automatically cast a $?c1[Mortal Strike][Bloodthirst] at your target or random nearby enemy, dealing $s2% of normal damage.", ua = "Кожні $s1 удари Клинкової бурі ви автоматично застосовуєте $?c1[Смертельний удар][Спрагу крові] проти вашої цілі або випадкового ворога поблизу, завдаючи $s2% звичайної шкоди." },
    { en = "Overpower has a $h% chance to reset the cooldown of Mortal Strike and reduce the cost of your next Mortal Strike by $386631s1%.", ua = "«Пересилення» з імовірністю $h% скидає перезарядження «Смертельного удару» та зменшує вартість твого наступного «Смертельного удару» на $386631s1%." },
    { en = "Execute increases the damage of your next Mortal Strike by $386633s1%, stacking up to $386633u times.", ua = "Страта збільшує шкоду твого наступного Смертельного удару на $386633s1%, складається до $386633u разів." },
    { en = "Increases the amount of damage required to break your fear effects by $s1%.", ua = "Збільшує на $s1% обсяг шкоди, потрібний, щоб зірвати твої ефекти страху." },
    { en = "Avenger's Shield increases the damage of your next Shield of the Righteous by $386652s1% for each target hit by Avenger's Shield, stacking up to $386652u times, and increases its radius by $386652s3 yds.", ua = "«Щит месника» збільшує шкоду твого наступного «Щита праведника» на $386652s1% за кожну ціль, в яку влучив «Щит месника» (складається до $386652u разів), а також збільшує його радіус на $386652s3 м." },
    { en = "Reduces the cooldown of Unending Resolve by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Незламної рішучості» на ${$s1/-1000} сек." },
    { en = "Dark Pact sacrifices only $s3% of your current health for the same shield value.", ua = "«Темний пакт» жертвує лише $s3% твого поточного здоров'я за ту саму міцність щита." },
    { en = "Reduces the cooldown of Dark Pact by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Темного пакту» на ${$s1/-1000} сек." },
    { en = "Healthstones you conjure for yourself are now Demonic Healthstones and can be used multiple times in combat. Demonic Healthstones cannot be traded.\n\n\n\n$@spellicon452930 $@spellname452930\n\n$@spelldesc452930 60 sec cooldown.", ua = "Камені здоров'я, які ви створюєте для себе, тепер є Демонічними каменями здоров'я й можуть використовуватися кілька разів у бою. Демонічні камені здоров'я не можна передавати.\n\n\n\n$@spellicon452930 $@spellname452930\n\n$@spelldesc452930 Перезарядження 60 сек." },
    { en = "After casting$?c1[ Holy Prism, Holy Armament, or][] Divine Toll, you instantly cast $?c2[Avenger's Shield]?c1[Holy Shock][Judgment] every $386730t1 sec for $386730s2 sec.", ua = "Після застосування$?c1[ Священної призми, Священного озброєння чи][] Божественного дзвону ви миттєво застосовуєте $?c2[Щит месника]?c1[Священний шок][Вирок] кожні $386730t1 с протягом $386730s2 с." },
    { en = "Enemies hit by Cone of Cold are frozen in place for $386770d instead of snared.\n\n\n\nWhen your roots expire or are dispelled, your target is snared by $394255s1%, decaying over $394255d.", ua = "Вороги, уражені Конусом холоду, на $386770d примерзають на місці замість сповільнення.\n\n\n\nКоли ваше обплутання корінням добігає кінця або розвіюється, ваша ціль сповільнюється на $394255s1%, і цей ефект слабшає протягом $394255d." },
    { en = "Casting your barrier removes all snare effects.", ua = "Прочитання твого бар'єра знімає всі ефекти сповільнення." },
    { en = "Barbed Shot has a $s1% chance to cause your pet to use its special attack and deal $s2% bonus damage.", ua = "«Зазублений постріл» має $s1% шансу змусити твого улюбленця використати особливу атаку й завдати $s2% додаткової шкоди." },
    { en = "Each time you dodge or an enemy misses you, the remaining cooldown on your Brews is reduced by ${$s1/10}.1 sec. Effect reduced by $s2% for each additional recent attacker, up to $s3.", ua = "Щоразу, коли ти ухиляєшся або ворог промахується по тобі, решта перезарядження твоїх варев скорочується на ${$s1/10}.1 сек. Ефект слабшає на $s2% за кожного додаткового недавнього нападника, аж до $s3." },
    { en = "Your Breath of Fire ignites your right leg in flame for $386963d, causing your Blackout Kick and Spinning Crane Kick to deal $s1% additional damage as Fire damage and refresh the duration of your Breath of Fire on the target.", ua = "Твій «Подих вогню» запалює твою праву ногу на $386963d, через що «Удар затьмарення» та «Обертовий удар журавля» завдають додатково $s1% шкоди вогнем і поновлюють тривалість твого «Подиху вогню» на цілі." },
    { en = "Shadow Bolt and Drain Soul deal $s1% increased damage, up to ${$s1*$s2}%, per damage over time effect you have active on the target.", ua = "«Стріла тіні» та «Витягування душі» завдають на $s1% більше шкоди, аж до ${$s1*$s2}%, за кожен твій активний ефект періодичної шкоди на цілі." },
    { en = "$?a445465[Wither][Corruption] damage is increased by $s1%, and each time it deals damage any of your Curses active on the target are extended by ${$s2/1000}.1 sec.", ua = "Шкода від $?a445465[В'янення][Розтління] підвищена на $s1%, і щоразу, коли воно завдає шкоди, будь-які ваші Прокляття, активні на цілі, подовжуються на ${$s2/1000}.1 сек." },
    { en = "Fire Blast gains $s1 additional charge and its damage is increased by $s2%.", ua = "«Вогняний вибух» отримує $s1 додатковий заряд, а його шкода збільшена на $s2%." },
    { en = "Blackout Kick deals an additional $s3% damage. Blackout Kick critical hits grant an additional $m2 $Lstack:stacks; of Elusive Brawler.", ua = "Удар затьмарення завдає додатково $s3% шкоди. Критичні влучання Удару затьмарення надають додатково $m2 $Lнакопичення:накопичень; Невловимого бійця." },
    { en = "Increases the critical strike damage of your Destruction spells by $s1%.", ua = "Збільшує шкоду критичних ударів твоїх заклять Руйнування на $s1%." },
    { en = "Conflagrate and Shadowburn have a $s1% chance to guarantee your next cast of either ability to critically strike, and increase its damage by your critical strike chance.", ua = "«Займання» і «Тіньовий опік» з імовірністю $s1% гарантують, що наступне творення будь-якої з цих здібностей буде критичним ударом, а його шкода зросте на величину твого шансу критичного удару." },
    { en = "Channel Demonfire fires an additional $s1 bolts. Each bolt increases the remaining duration of $?a445465[Wither][Immolate] on all targets hit by ${$s2/1000}.1 sec.", ua = "Спрямування демонічного вогню випускає додатково $s1 стріл. Кожна стріла подовжує залишкову тривалість $?a445465[Всихання][Спопеління] на всіх вражених цілях на ${$s2/1000}.1 сек." },
    { en = "Avenging Wrath empowers your next $?c3[damage dealing single target Holy Power ability to automatically activate Divine Storm][Word of Glory to automatically activate Light of Dawn] with $s2% increased effectiveness.", ua = "Гнів месника наснажує $?c3[твою наступну одноцільову здібність святої сили, що завдає шкоди: вона автоматично активує Божественну бурю][твоє наступне Слово слави: воно автоматично активує Світло світанку] з ефективністю, підвищеною на $s2%." },
    { en = "Incinerate now generates $s1% additional Soul Shard Fragments.", ua = "«Спопеління» тепер створює на $s1% більше фрагментів осколків душі." },
    { en = "Your damaging abilities have $@switch<$s1>[a][an increased] chance to invoke Niuzao, causing him to charge to your target's location and Stomp, dealing $1242373s1 Physical damage to your target and reduced damage to secondary targets.", ua = "Ваші здібності, що завдають шкоди, мають $@switch<$s1>[шанс][підвищений шанс] прикликати Ніузао, який кидається до місця вашої цілі та б'є Тупотом, завдаючи $1242373s1 фізичної шкоди вашій цілі та зменшеної шкоди другорядним цілям." },
    { en = "Blackout Kick's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Удару затьмарення» скорочено на ${-$s1/1000} сек." },
    { en = "Chaos Bolt, Shadowburn, and Incinerate deal $s1% increased damage to targets afflicted by $?a445465[Wither][Immolate].", ua = "Хаосний болт, Тіньове горіння та Спопеління завдають на $s1% більше шкоди цілям, що зазнають дії $?a445465[Всихання][Спалення]." },
    { en = "When your $?a445465[Wither][Immolate] deals periodic damage to a target above $s2% health, gain $387263s1% Haste for $387263d.\n\n\n\nStacks up to $387263U times.", ua = "Коли ваше $?a445465[Згасання][Спалення] завдає періодичної шкоди цілі зі здоров'ям понад $s2%, ви отримуєте $387263s1% Поспіху на $387263d.\n\n\n\nНакопичується до $387263U разів." },
    { en = "Chaos Bolt, Rain of Fire, and Shadowburn always gain at least $s1% of the maximum benefit from your Mastery: Chaotic Energies.", ua = "«Стріла хаосу», «Дощ вогню» та «Опік тіні» завжди отримують щонайменше $s1% максимальної вигоди від твоєї «Майстерності: хаотичні енергії»." },
    { en = "Expel Harm's healing is increased by up to $s1%, based on your missing health.", ua = "Зцілення «Вигнання шкоди» збільшується до $s1% залежно від втраченого тобою здоров'я." },
    { en = "Wing Buffet and Tail Swipe knock enemies further and daze them, reducing movement speed by 70% for 4 sec.", ua = "Удар крилами та Удар хвостом відкидають ворогів далі й приголомшують їх, зменшуючи швидкість руху на 70% на 4 сек." },
    { en = "Increases your critical strike chance by $s1%.\n\n\n\nPhysical attacks against you have a $s2% chance to make your next Incinerate instant cast. This effect can only occur once every $proccooldown sec.", ua = "Збільшує ваш шанс критичного удару на $s1%.\n\n\n\nФізичні атаки проти вас мають $s2% шансу зробити ваше наступне Спопеління миттєвим. Цей ефект може спрацьовувати лише раз на $proccooldown сек." },
    { en = "Your single target spells have a $s1% chance to apply $?a200546[Bane of Havoc below][Havoc to] a nearby enemy for ${$s3/1000}.1 sec.\n\n\n\n$?a200546[$@spellicon200546 $@spellname200546\n\nCurses the ground with a demonic bane, causing all of your single target spells to also strike targets marked with the bane for $80240s1% of the damage dealt. Lasts ${$s3/1000}.1 sec.][$@spellicon80240 $@spellname80240\n\nMarks a target with Havoc for ${$s3/1000}.1 sec, causing your single target spells to also strike the Havoc victim for $80240s1% of the damage dealt.]", ua = "Ваші закляття по одній цілі мають $s1% шанс накласти $?a200546[Згубу Сум'яття під][Сум'яття на] найближчого ворога на ${$s3/1000}.1 сек.\n\n\n\n$?a200546[$@spellicon200546 $@spellname200546\n\nПроклинає землю демонічною згубою, через що всі ваші закляття по одній цілі також вражають цілей, позначених згубою, на $80240s1% завданої шкоди. Триває ${$s3/1000}.1 сек.][$@spellicon80240 $@spellname80240\n\nПозначає ціль Сум'яттям на ${$s3/1000}.1 сек, через що ваші закляття по одній цілі також вражають жертву Сум'яття на $80240s1% завданої шкоди.]" },
    { en = "When you Blackout Kick, your |CFFffffffStagger|R is reduced by $<reduc>, increased by up to $s3% based on your missing health.", ua = "Коли ви застосовуєте Затьмарливий удар, ваш |CFFffffffРозподілений урон|R зменшується на $<reduc>, що збільшується до $s3% залежно від вашої нестачі здоров'я." },
    { en = "Blackout Kick's damage increased by $s2% and it strikes an additional $s1 $ltarget;targets.", ua = "Шкода від Удару затьмарення збільшена на $s2%, і він вражає додатково $s1 $lціль;цілей." },
    { en = "Emerald Blossom and Verdant Embrace instantly heal you for $387763s1 when cast.", ua = "«Смарагдовий цвіт» і «Зелені обійми» при прочитанні миттєво зцілюють тебе на $387763s1." },
    { en = "Beacon of Light transfers an additional $s1% of the amount healed.", ua = "«Маяк Світла» переносить додатково $s1% обсягу зцілення." },
    { en = "Your Flash of Light heals for an additional $s1% when cast on a target affected by your Beacon of Light.", ua = "Твій «Спалах Світла» зцілює додатково на $s1%, коли створений на цілі під дією твого «Маяка світла»." },
    { en = "Your Leech is increased by $s1%.", ua = "Твоє висмоктування збільшено на $s1%." },
    { en = "Lay on Hands grants the target $387792s1% increased armor for $387792d and now ignores healing reduction effects.", ua = "«Покладання рук» дає цілі $387792s1% додаткової броні на $387792d і тепер ігнорує ефекти зниження зцілення." },
    { en = "Blessing of Freedom increases the target's movement speed by $s3%. $?s204018[Blessing of Spellwarding][Blessing of Protection] and Blessing of Sacrifice reduce the target's damage taken by $s4%. These effects linger for $394454d after the Blessing ends.", ua = "Благословення свободи збільшує швидкість пересування цілі на $s3%. $?s204018[Благословення захисту від чарів][Благословення захисту] і Благословення жертовності зменшують шкоду, якої зазнає ціль, на $s4%. Ці ефекти тривають ще $394454d після завершення благословення." },
    { en = "Holy Shock and Judgment have a $s1% increased critical strike chance.", ua = "Шанс критичного удару «Святого шоку» та «Осуду» збільшено на $s1%." },
    { en = "The cooldown of your loss of control spells are reduced by ${-$s1/1000} sec.", ua = "Перезарядження твоїх заклять, що позбавляють контролю, зменшено на ${-$s1/1000} сек." },
    { en = "While empowered by Infusion of Light, Flash of Light heals for an additional $s2% and Judgment refunds ${$s1/1000}.1% of your maximum mana.", ua = "Під дією «Наповнення Світлом» «Спалах Світла» зцілює додатково на $s2%, а «Правосуддя» повертає ${$s1/1000}.1% твоєї максимальної мани." },
    { en = "Increases Light of Dawn's healing by $s1%.", ua = "Збільшує зцілення «Світла світанку» на $s1%." },
    { en = "Your $?s399491[Sheilun's Gift][Invigorating Mist] healing is increased by $?s399491[$s3%][$s1%] and your Enveloping Mist also heals allies with Renewing Mist for $s2% of its healing.\n\n\n\nThe duration of Enveloping Mist is increased by ${$322118s5/1000} sec while you have a celestial summoned.", ua = "Зцілення твого $?s399491[Дару Шейлуна][Підбадьорливого туману] збільшено на $?s399491[$s3%][$s1%], а твій Огортальний туман також зцілює союзників з Оновлювальним туманом на $s2% від свого зцілення.\n\n\n\nТривалість Огортального туману збільшено на ${$322118s5/1000} с, поки в тебе прикликаний небожитель." },
    { en = "Gust of Mists has a $s2% chance to do $s1% more healing.", ua = "«Порив туманів» має $s2% шансу зцілити на $s1% більше." },
    { en = "Chi Cocoons now apply Enveloping Mist for ${$s2/1000} sec when they expire or are consumed, and Chi-Ji's Gusts of Mists healing is increased by $s1% and Yu'lon's Soothing Breath healing is increased by $s3%.", ua = "«Кокони ці» тепер накладають «Огортальний туман» на ${$s2/1000} сек., коли спливають або витрачаються; зцілення «Поривів туманів» Чі-Джі збільшено на $s1%, а зцілення «Заспокійливого подиху» Ю'лона — на $s3%." },
    { en = "While channeling Mana Tea you exhale the breath of Yu'lon, healing up to $s1 allies within $388044a1 yards for $388044s1 every ${$388040t1}.1 sec.", ua = "Поки ти підтримуєш «Чай з мани», ти видихаєш подих Ю'лон, зцілюючи до $s1 союзників у радіусі $388044a1 м на $388044s1 кожні ${$388040t1}.1 сек." },
    { en = "The duration of Survival of the Fittest is increased by ${$s2/1000}.1 sec.", ua = "Тривалість «Виживання найпристосованіших» збільшено на ${$s2/1000}.1 сек." },
    { en = "Throw Glaive causes targets to take an additional $s1% of damage dealt as Chaos over $390181d.", ua = "«Кидок глефи» змушує цілі отримати додатково $s1% завданої шкоди як шкоду хаосу протягом $390181d." },
    { en = "Each time Immolation Aura deals damage, $s1% of the damage dealt by up to $s2 critical strikes is gathered as Ragefire.\n\n\n\nWhen Immolation Aura expires you explode, dealing all stored Ragefire damage to nearby enemies.", ua = "Щоразу, коли Аура спалення завдає шкоди, $s1% шкоди, завданої до $s2 критичними ударами, накопичується як Лютий вогонь.\n\n\n\nКоли Аура спалення завершується, ви вибухаєте, завдаючи весь накопичений Лютий вогонь ворогам поблизу." },
    { en = "Damaging an enemy before they damage you increases your critical strike chance by $391215s1% for $391215d.\n\n\n\nVengeful Retreat refreshes your potential to trigger this effect on any enemies you are in combat with.", ua = "Завдавши ворогові шкоди раніше, ніж він завдасть її вам, ви збільшуєте свій шанс критичного удару на $391215s1% на $391215d.\n\n\n\nМстивий відступ оновлює вашу можливість викликати цей ефект на будь-яких ворогах, з якими ви в бою." },
    { en = "When you activate Metamorphosis, the cooldowns of Blade Dance and Eye Beam are immediately reset.", ua = "Коли ти активуєш «Метаморфозу», перезарядження «Танцю клинків» та «Променя ока» миттєво скидається." },
    { en = "Chaos Nova, Eye Beam, and Immolation Aura gain bonuses when striking 1 target.\n\n\n\n$@spellicon179057 $@spellname179057:\n\nStun duration increased by ${$s1/1000} sec.\n\n\n\n$@spellicon198013 $@spellname198013:\n\nDeals $s2% increased damage.\n\n\n\n$@spellicon258920 $@spellname258920:\n\nAlways critically strikes.", ua = "Хаотична нова, Промінь з очей та Аура спалення отримують бонуси, коли вражають 1 ціль.\n\n\n\n$@spellicon179057 $@spellname179057:\n\nТривалість оглушення збільшено на ${$s1/1000} с.\n\n\n\n$@spellicon198013 $@spellname198013:\n\nЗавдає на $s2% більше шкоди.\n\n\n\n$@spellicon258920 $@spellname258920:\n\nЗавжди завдає критичного удару." },
    { en = "The duration of your active demon form is extended by ${$s1/1000}.1 sec per $s2 Fury spent.", ua = "Тривалість твоєї активної демонічної подоби подовжується на ${$s1/1000}.1 сек. за кожні $s2 витраченої люті." },
    { en = "Gain critical strike damage equal to $s2% of your critical strike chance.", ua = "Отримуєш шкоду критичного удару, що дорівнює $s2% твого шансу критичного удару." },
    { en = "Reduces the cooldown of $?s325197[Invoke Chi-Ji, the Red Crane][Invoke Yul'on, the Jade Serpent] by ${$s1/-60000} min, but decreases its duration to ${($s4+$s2)/1000} sec.", ua = "Зменшує перезарядження $?s325197[«Прикликання Чі-Цзі, Червоного журавля»][«Прикликання Юлона, Нефритового змія»] на ${$s1/-60000} хв, але зменшує його тривалість до ${($s4+$s2)/1000} сек." },
    { en = "The absorb amount of Life Cocoon is increased by $s1%.", ua = "Обсяг поглинання «Кокона життя» збільшено на $s1%." },
    { en = "After using Thunder Focus Tea, your next spell gives $s1% of a stat. Only one stat increase may be active at once:\n\n$@spellname124682: Critical strike\n\n$@spellname115151: Haste\n\n$@spellname107428: Versatility", ua = "Після використання Чаю грозового зосередження ваше наступне закляття дає $s1% характеристики. Одночасно може бути активне лише одне підвищення характеристики:\n\n$@spellname124682: Критичний удар\n\n$@spellname115151: Поспіх\n\n$@spellname107428: Універсальність" },
    { en = "Purify $s1% of your Staggered damage each time you gain $s2 sec of Shuffle duration.", ua = "Очищує $s1% твоєї відстроченої шкоди щоразу, коли ти отримуєш $s2 сек. тривалості «Човгання»." },
    { en = "Your Enveloping Mists heal the target for ${$388514s1*$s1} each time they take direct damage.", ua = "Твій «Огортальний туман» зцілює ціль на ${$388514s1*$s1} щоразу, коли вона отримує пряму шкоду." },
    { en = "Life Cocoon applies Renewing Mist and Enveloping Mist to the target.", ua = "«Кокон життя» накладає на ціль «Відновлювальний туман» і «Огортальний туман»." },
    { en = "The cooldown of $?s388615[Restoral][Revival] is reduced by ${$s2/-1000} sec and $?s388615[Restoral][Revival] healing increased by $s1%.", ua = "Перезарядження $?s388615[Відновлення][Воскресіння] зменшено на ${$s2/-1000} с, а зцілення від $?s388615[Відновлення][Воскресіння] збільшено на $s1%." },
    { en = "Allies targeted by Soothing Mist receive $s1% more healing from your Enveloping Mist and Renewing Mist effects.", ua = "Союзники, на яких націлено «Заспокійливий туман», отримують на $s1% більше зцілення від твоїх ефектів «Огортального туману» й «Відновлювального туману»." },
    { en = "Heals all party and raid members within $A1 yds for $s1 and clears them of all harmful Poison and Disease effects. \n\n\n\nCastable while stunned.\n\n\n\nHealing reduced beyond $s5 targets.", ua = "Зцілює всіх членів групи та рейду в межах $A1 ярдів на $s1 і звільняє їх від усіх шкідливих ефектів отрути та хвороби. \n\n\n\nМожна сотворити в оглушеному стані.\n\n\n\nЗцілення зменшується після $s5 цілей." },
    { en = "$?s388667[][Replaces Shadow Bolt.\n\n\n\n]Drains the target's soul, causing $o1 Shadow damage over $d.\n\n\n\nDamage is increased by $s2% against enemies below $s3% health.\n\n\n\n|cFFFFFFFFGenerates 1 Soul Shard if the target dies during this effect.|r", ua = "$?s388667[][Замінює Тіньову блискавку.\n\n\n\n]Висмоктує душу цілі, завдаючи $o1 тіньової шкоди протягом $d.\n\n\n\nШкода збільшена на $s2% проти ворогів зі здоров'ям нижче $s3%.\n\n\n\n|cFFFFFFFFСтворює 1 Уламок душі, якщо ціль гине під час дії ефекту.|r" },
    { en = "Increases all damage dealt by $s1%.", ua = "Збільшує всю завдану шкоду на $s1%." },
    { en = "Reduces all damage taken by you and your target while channeling Soothing Mists by $s1%.", ua = "Зменшує всю шкоду, якої зазнаєте ти і твоя ціль, на $s1%, поки ти підтримуєш «Заспокійливі тумани»." },
    { en = "Renewing Mist's heal over time effect has a ${$s3}.1% chance to apply Enveloping Mist for $s2 sec.", ua = "Періодичне зцілення Оновлювального туману з імовірністю ${$s3}.1% накладає Огортальний туман на $s2 сек." },
    { en = "Renewing Mist has a $s1% chance to immediately spread to an additional target when initially cast or when traveling to a new target.", ua = "Оновлювальний туман з імовірністю $s1% одразу поширюється на додаткову ціль при першому прочитанні або при перенесенні на нову ціль." },
    { en = "Tiger Palms strike twice, Blackout Kicks strike an additional $s5 targets at $s6% effectiveness, and Spinning Crane Kick heals $s4 nearby allies for $s1% of the damage done.", ua = "«Долоня тигра» б'є двічі, «Копняк затьмарення» вражає додатково $s5 цілей з ефективністю $s6%, а «Обертовий копняк журавля» зцілює $s4 союзників поблизу на $s1% завданої шкоди." },
    { en = "Rising Sun Kick deals $s1% increased damage. Spinning Crane Kick deals $s2% additional damage.", ua = "Удар висхідного сонця завдає на $s1% більше шкоди. Обертовий удар журавля завдає на $s2% додаткової шкоди." },
    { en = "Increases all healing taken by $s1%.", ua = "Збільшує все отримуване зцілення на $s1%." },
    { en = "After casting $?a137023[Keg Smash][Rising Sun Kick], your next $?s399491[Sheilun's Gift][Vivify] becomes instant cast.$?c1[\n\n\n\nThis effect also reduces the energy cost of Vivify by $392883s3%.]?c3[\n\n\n\nThis effect also reduces the energy cost of Vivify by $392883s3%.][]", ua = "Після творення $?a137023[Удару діжкою][Удару висхідного сонця] ваше наступне $?s399491[Дар Шейлун][Оживлення] стає миттєвим.$?c1[\n\n\n\nЦей ефект також зменшує витрату енергії Оживлення на $392883s3%.]?c3[\n\n\n\nЦей ефект також зменшує витрату енергії Оживлення на $392883s3%.][]" },
    { en = "Fortifying Brew cooldown reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Зміцнювального варива» скорочено на ${$s1/-1000} сек." },
    { en = "Increases your maximum health by an additional $s1% and your damage taken is reduced by an additional $s2% while Fortifying Brew is active.", ua = "Додатково збільшує максимум здоров'я на $s1% і додатково зменшує отримувану шкоду на $s2%, поки діє «Зміцнювальне вариво»." },
    { en = "Reduces the cooldown of Conflagrate by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Пожежі» на ${$s1/-1000} сек." },
    { en = "Increases the damage of $?a445465[Wither][Immolate] by $s1% and its duration by ${$s3/1000} sec.", ua = "Підвищує шкоду $?a445465[В'янення][Самоспалення] на $s1% та його тривалість на ${$s3/1000} с." },
    { en = "Rising Sun Kick and Enveloping Mist apply Renewing Mist for $s1 seconds to an ally within $r yds.", ua = "Удар висхідного сонця та Огортальний туман накладають Оновлювальний туман на $s1 сек. на союзника в радіусі $r м." },
    { en = "Spinning Crane Kick damage increased by $s1% and its radius is increased by $s2%.", ua = "Шкода Обертового удару журавля збільшена на $s1%, а його радіус — на $s2%." },
    { en = "Rising Sun Kick damage increased by $s1% and critical strike damage increased by $s2%.", ua = "Шкода Удару висхідного сонця збільшена на $s1%, а шкода його критичних ударів — на $s2%." },
    { en = "Tiger Palm damage increased by $s1%.", ua = "Шкода «Долоні тигра» збільшена на $s1%." },
    { en = "Detox additionally removes all Poison and Disease effects.", ua = "«Детоксикація» додатково знімає всі ефекти отрути та хвороби." },
    { en = "Turns your skin to stone for $120954d, increasing your current and maximum health by $<health>% and reducing all damage you take by $<damage>%.\n\n\n\nCombines with other Fortifying Brew effects.", ua = "Обертає вашу шкіру на камінь протягом $120954d, збільшуючи ваше поточне та максимальне здоров'я на $<health>% і зменшуючи всю отримувану шкоду на $<damage>%.\n\n\n\nПоєднується з іншими ефектами Зміцнювального варива." },
    { en = "Damage from Rapid Fire increases the damage of Aimed Shot by $389020s1% for $389020d, stacking up to $389020u times.\n\n\n\nNew stacks do not refresh duration and are removed upon casting Rapid Fire.", ua = "Шкода від Швидкого вогню збільшує шкоду Прицільного пострілу на $389020s1% протягом $389020d, накопичуючись до $389020u разів.\n\n\n\nНові заряди не оновлюють тривалість і знімаються під час застосування Швидкого вогню." },
    { en = "Fiery Brand also increases Fire damage you deal to the target by $s1%.", ua = "«Вогняне тавро» також збільшує вогняну шкоду, якої ти завдаєш цілі, на $s1%." },
    { en = "Execute critical strike chance increased by $s1% and Execute immediately refunds an additional $s2% of the Rage spent.", ua = "Шанс критичного удару Страти збільшено на $s1%, а Страта одразу повертає додатково $s2% витраченої люті." },
    { en = "Soul Leech also heals you for $s1% and your pet for $s2% of the absorption it grants.", ua = "«Висмоктування душі» також зцілює тебе на $s1%, а твого улюбленця — на $s2% від наданого ним поглинання." },
    { en = "Call upon the Light and gain 15 stacks of Divine Resolve, increasing your maximum health by $s11% and reducing your damage taken by $s12% per stack for $d. After $<delay> sec, you will begin to lose 1 stack per second, but each 3 Holy Power spent will delay the loss of your next stack by 1 sec.$?s53376&s384376[\n\n\n\nWhile active, your Judgment generates $53376s3 additional Holy Power, your damage and healing is increased by $s1%, and Hammer of Wrath may be cast on any target.]?s53376[\n\n\n\nWhile active, your Judgment generates $53376s3 additional Holy Power.]?s384376[\n\n\n\nWhile active, your damage and healing is increased by $s1%, and Hammer of Wrath may be cast on any target.][]\n\n\n\nCombines with Avenging Wrath.", ua = "Прикликає Світло і дає 15 набоїв Божественної рішучості, збільшуючи ваше максимальне здоров'я на $s11% і зменшуючи отримувану шкоду на $s12% за кожен набій протягом $d. Через $<delay> с ви почнете втрачати по 1 набою за секунду, але кожні витрачені 3 Святої Сили відкладають втрату наступного набою на 1 с.$?s53376&s384376[\n\n\n\nДоки активне, ваш Вирок генерує $53376s3 додаткової Святої Сили, ваша шкода і зцілення збільшені на $s1%, а Молот гніву можна творити на будь-яку ціль.]?s53376[\n\n\n\nДоки активне, ваш Вирок генерує $53376s3 додаткової Святої Сили.]?s384376[\n\n\n\nДоки активне, ваша шкода і зцілення збільшені на $s1%, а Молот гніву можна творити на будь-яку ціль.][]\n\n\n\nПоєднується з Гнівом месника." },
    { en = "Your healing is increased by up to $s1%, based on the current health of your target. Lower health targets are healed for more.", ua = "Твоє зцілення збільшено до $s1% залежно від поточного здоров'я цілі. Цілі з меншим здоров'ям отримують більше зцілення." },
    { en = "Reduces the chance you will be critically struck by $s1%. All damage your primary demon takes is reduced by $s3%.", ua = "Зменшує шанс отримати критичний удар на $s1%. Уся шкода, якої зазнає твій основний демон, зменшується на $s3%." },
    { en = "Using Demonic Circle: Teleport or your Demonic Gateway reduces all damage you take by $389614s1% for $389614d.", ua = "Використання «Демонічного кола: телепортації» або демонічної брами зменшує всю отримувану шкоду на $389614s1% на $389614d." },
    { en = "Targets resurrected with Soulstone resurrect with $s1% additional health and $s2% additional mana.", ua = "Цілі, воскрешені «Каменем душі», повертаються до життя з додатковими $s1% здоров'я і $s2% мани." },
    { en = "Increases Lichborne duration by ${$s1/1000} sec and reduces the cooldown by ${$s2/-1000} sec.", ua = "Збільшує тривалість Подоби ліча на ${$s1/1000} сек. і зменшує перезарядження на ${$s2/-1000} сек." },
    { en = "Blade Dance causes your next Chaos Strike within $337567d to have a $s1-$s2% increased critical strike chance and will always refund Fury.", ua = "«Танець клинків» дає твоєму наступному «Удару хаосу» протягом $337567d на $s1-$s2% вищий шанс критичного удару, і він завжди повертає лють." },
    { en = "Vengeful Retreat has a ${$s1/-1000} sec reduced cooldown and generates ${$389890m1/$389890t*$389890d} Fury over $389890d.", ua = "Перезарядження «Мстивого відступу» скорочене на ${$s1/-1000} сек., і він породжує ${$389890m1/$389890t*$389890d} од. люті протягом $389890d." },
    { en = "Entering demon form causes your next Chaos Strike to unleash your inner demon, causing it to crash into your target and deal $390137s1 Chaos damage to all nearby enemies. Deals reduced damage beyond $s2 targets.", ua = "Після переходу в демонічну подобу твій наступний Удар хаосу вивільняє внутрішнього демона: він врізається в ціль і завдає $390137s1 шкоди хаосу всім ворогам поблизу. Якщо цілей більше за $s2, шкода зменшується." },
    { en = "Increases maximum health by $s1%.", ua = "Збільшує максимум здоров'я на $s1%." },
    { en = "You take $393009s1% reduced magic damage while Immolation Aura is active.", ua = "Поки діє «Аура спалення», ти отримуєш на $393009s1% менше магічної шкоди." },
    { en = "When Fel Devastation finishes fully channeling, it refreshes $s1-$s2% of its cooldown and refunds $s3-$s4 Fury.", ua = "Коли «Спустошення Скверни» повністю завершує підтримання, воно відновлює $s1-$s2% свого перезарядження та повертає $s3-$s4 од. люті." },
    { en = "When consuming a Soul Fragment would heal you above full health it shields you instead, up to a maximum of ${$MHP*$s1/100}.", ua = "Якщо поглинання фрагмента душі зцілило б тебе понад повне здоров'я, замість цього ти отримуєш щит, щонайбільше ${$MHP*$s1/100}." },
    { en = "Increases the duration of your Sigils by ${$s2/1000} sec and radius by $s1 yds.", ua = "Подовжує тривалість твоїх печатей на ${$s2/1000} сек., а їхній радіус — на $s1 м." },
    { en = "Your Sigils have $S2% reduced cooldowns.", ua = "Ваші Знаки мають на $S2% менше перезарядження." },
    { en = "Demon Spikes reduces damage taken by $S1% while active.", ua = "Демонічні шипи зменшують отримувану шкоду на $S1%, доки активні." },
    { en = "Activating Infernal Strike out of combat or within $1265759d of entering combat places a Sigil of Flame at the target location.", ua = "Активація «Інфернального удару» поза боєм або протягом $1265759d після вступу в бій розміщує «Сигіл полум'я» в цільовій точці." },
    { en = "While Demon Spikes is active, melee attacks against you cause the attacker to take $391159s1 Physical damage. Generates high threat.", ua = "Поки діють «Демонічні шипи», атаки ближнього бою по тобі завдають нападнику $391159s1 фізичної шкоди. Створює високу загрозу." },
    { en = "Fiery Brand has ${$s1/-1000} sec reduced cooldown and $s2 additional $lcharge:charges;.", ua = "Вогняне тавро має зменшене на ${$s1/-1000} с перезарядження та $s2 додаткових $lзаряду:зарядів;." },
    { en = "Throw Glaive has ${$s2+1} charges and snares all enemies hit by $213405s1% for $213405d.", ua = "«Кидок глефи» має ${$s2+1} заряди та сповільнює всіх уражених ворогів на $213405s1% на $213405d." },
    { en = "Increases the duration of Darkness by ${$s1/1000} sec.", ua = "Подовжує тривалість «Темряви» на ${$s1/1000} сек." },
    { en = "Reduces the cooldown of Darkness by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Темряви» на ${$s1/-1000} сек." },
    { en = "The healing of Shattered Souls is increased by $s1%.", ua = "Зцілення від «Розбитих душ» збільшене на $s1%." },
    { en = "$?a212613[Infernal Strike]?a1213636[Shift][Fel Rush] increases your movement speed by $389847s1% for $389847d.", ua = "$?a212613[Пекельний удар]?a1213636[Зсув][Ривок Скверни] підвищує вашу швидкість пересування на $389847s1% протягом $389847d." },
    { en = "Spectral Sight has ${$s1/-1000} sec reduced cooldown and no longer reduces movement speed.", ua = "Перезарядження «Спектрального зору» скорочено на ${$s1/-1000} сек., і він більше не зменшує швидкість руху." },
    { en = "Tiger Palm's damage is increased by $s2% and reduces the remaining cooldown of your Brews by ${$s3/1000}.1 additional sec.", ua = "Шкода «Долоні тигра» збільшена на $s2%, а сама вона скорочує залишкове перезарядження твоїх варив додатково на ${$s3/1000}.1 сек." },
    { en = "Enemies struck by Sigil of Flame, Soul Cleave, and Spirit Bomb are afflicted with Frailty for $247456d.\n\n\n\nYou heal for $247456s1% of all damage you deal to targets with Frailty.", ua = "Вороги, вражені Знаком полум'я, Розтином душі та Бомбою духу, отримують Кволість на $247456d.\n\n\n\nВи зцілюєтеся на $247456s1% усієї шкоди, яку завдаєте цілям із Кволістю." },
    { en = "Frailty now also increases all damage you deal to afflicted targets by $s1%.", ua = "«Кволість» тепер також збільшує всю шкоду, якої ти завдаєш ураженим цілям, на $s1%." },
    { en = "Chaos Strike has a $s1% chance to trigger a second Chaos Strike.", ua = "Удар хаосу має $s1% шанс викликати другий Удар хаосу." },
    { en = "The final slash of Blade Dance deals an additional $s1% damage.", ua = "Останній помах «Танцю клинків» завдає додатково $s1% шкоди." },
    { en = "The effects of Frailty are doubled.", ua = "Ефекти «Кволості» подвоєні." },
    { en = "$?a212613[Fel Devastation][Eye Beam] summons an allied $?a212613[Havoc][Vengeance] Demon Hunter who casts $?a212613[Eye Beam][Fel Devastation], dealing $?a212613[${$391058s1*10*2} Chaos][${$393834s1*(2/$393831t1)} Fire] damage over $?a212613[$391057d][$393831d]. $?a212613[Deals reduced damage beyond $198013s5 targets.][Dealing damage heals you for up to ${$212106s1*(2/$t1)} health.]", ua = "$?a212613[Спустошення Скверни][Промінь з очей] прикликає союзного Мисливця на демонів спеціалізації $?a212613[Хаос][Помста], який творить $?a212613[Промінь з очей][Спустошення Скверни], завдаючи $?a212613[${$391058s1*10*2} шкоди Хаосом][${$393834s1*(2/$393831t1)} шкоди вогнем] протягом $?a212613[$391057d][$393831d]. $?a212613[Завдає зменшеної шкоди понад $198013s5 цілей.][Завдаючи шкоди, ви зцілюєтесь на величину до ${$212106s1*(2/$t1)} здоров'я.]" },
    { en = "Enemies hit by Chaos Strike or Throw Glaive take $s1% increased damage from Chaos Strike and Throw Glaive for $390155d.", ua = "Вороги, уражені Ударом хаосу чи Кидком глефи, отримують на $s1% більше шкоди від Удару хаосу та Кидка глефи протягом $390155d." },
    { en = "Immolation Aura's damage increases by $s1% each time it deals damage.", ua = "Шкода «Аури спалення» збільшується на $s1% щоразу, коли вона завдає шкоди." },
    { en = "Place a demonic sigil at the target location that activates after $d.\n\n\n\nDetonates to deal $389860s1 Chaos damage and shatter up to $s3 Soul $LFragment:Fragments; from enemies affected by the sigil. Deals reduced damage beyond $s1 targets.", ua = "Розміщує демонічний сигіл у вказаному місці, що активується за $d.\n\n\n\nДетонує, завдаючи $389860s1 шкоди Хаосом і вибиваючи до $s3 $LФрагмента душі:Фрагментів душі; з ворогів під дією сигілу. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "Critical strike damage of your diseases is increased by $s1%", ua = "Критична шкода твоїх хвороб збільшена на $s1%" },
    { en = "Dark Transformation and Army of the Dead summon a Magus of the Dead who hurls Frostbolts and Shadow Bolts at your foes for ${$s1/1000} sec.", ua = "«Темне перевтілення» та «Армія мертвих» прикликають магуса мертвих, який протягом ${$s1/1000} сек. жбурляє у твоїх ворогів стріли морозу та стріли Тіні." },
    { en = "Fire damage increased by $s1%.", ua = "Вогняна шкода збільшена на $s1%." },
    { en = "Each time your $?a137021[Arcane Barrage]?a137019[Fireball]?a137020[Frostbolt][Arcane Barrage, Fireball, or Frostbolt] fails to critically strike, it gains $?a137021[$394195s3]?a137019[$394195s1]?a137020[$394195s2][$394195s2]% increased critical strike chance.\n\n\n\nCritical strike bonus is removed when the affected spell critically strikes.", ua = "Щоразу, коли $?a137021[«Арканний шквал»]?a137019[«Вогняна куля»]?a137020[«Крижана стріла»][«Арканний шквал», «Вогняна куля» чи «Крижана стріла»] не завдає критичного удару, його шанс критичного удару зростає на $?a137021[$394195s3]?a137019[$394195s1]?a137020[$394195s2][$394195s2]%.\n\n\n\nБонус до критичного удару знімається, коли уражене закляття завдає критичного удару." },
    { en = "Dark Transformation empowers your $?s207349[Dark Arbiter][Gargoyle], Abomination, Magus and Lesser Ghouls for $390264d, increasing their damage by $s2%.\n\n\n\nThe duration of Lesser Ghouls are increased by $s1% of your Mastery.", ua = "Темне перетворення підсилює $?s207349[вашого Темного арбітра][вашу Ґаргулью], Гидоту, Магуса та Менших вурдалаків на $390264d, збільшуючи їхню шкоду на $s2%.\n\n\n\nТривалість Менших вурдалаків збільшена на $s1% вашої Майстерності." },
    { en = "Death Coil deals $s2% increased damage and causes the target to take an additional $s1% of the direct damage dealt over $253367d.", ua = "«Спіраль смерті» завдає на $s2% більше шкоди, а ціль додатково отримує $s1% завданої прямої шкоди протягом $253367d." },
    { en = "Dread Plague deals damage to an additional nearby enemy at $s2% effectiveness and has a chance to grant you ${$1242078s1/10} Runic Power.", ua = "«Моторошна чума» завдає шкоди ще одному ворогу поблизу з ефективністю $s2% і має шанс дати тобі ${$1242078s1/10} рунічної сили." },
    { en = "Windfury Weapon has a $s1% chance to trigger a third attack.", ua = "«Зброя шалу вітру» з імовірністю $s1% спричиняє третю атаку." },
    { en = "When Lava Lash strikes a target affected by your Flame Shock, its cooldown is reduced by ${$s1/1000}.1 sec.", ua = "Коли «Лавовий батіг» влучає в ціль під дією твого «Полум'яного шоку», його перезарядження скорочується на ${$s1/1000}.1 сек." },
    { en = "$?s102560[Incarnation: Chosen of Elune][Celestial Alignment] blasts all enemies in a targeted area for ${$361237s1*$<mastery>} Astral damage and applies Stellar Flare to them.\n\n\n\nReduces the cooldown of $?s102560[Incarnation: Chosen of Elune][Celestial Alignment] by ${$s3/-1000} sec.\n\n\n\n$@spellicon202347 $@spellname202347\n\nBurns the target for $202347s1 Astral damage, and then an additional $202347o2 damage over $202347d. If dispelled, causes $356474s1 damage to the dispeller and blasts them upwards.\n\n\n\n|cFFFFFFFFGenerates ${$202347m3/10} Astral Power.|r", ua = "$?s102560[Втілення: обранець Елуни][Небесне вирівнювання] б'є всіх ворогів у вказаній зоні на ${$361237s1*$<mastery>} астральної шкоди й накладає на них Зоряний спалах.\n\n\n\nЗменшує перезарядження $?s102560[Втілення: обранця Елуни][Небесного вирівнювання] на ${$s3/-1000} с.\n\n\n\n$@spellicon202347 $@spellname202347\n\nСпалює ціль на $202347s1 астральної шкоди, а потім додатково на $202347o2 шкоди протягом $202347d. Якщо ефект розвіяно, завдає $356474s1 шкоди тому, хто розвіяв, і підкидає його вгору.\n\n\n\n|cFFFFFFFFГенерує ${$202347m3/10} астральної сили.|r" },
    { en = "Reduces the cooldown of Leap of Faith by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Стрибка віри» на ${$s1/-1000} сек." },
    { en = "Purify additionally removes all Disease effects.", ua = "«Очищення» додатково знімає всі ефекти хвороб." },
    { en = "Reduces the cooldown of Fade by ${$s1/-1000)} sec.", ua = "Скорочує перезарядження «Зникнення» на ${$s1/-1000)} сек." },
    { en = "Reduces your target's physical damage taken by $390677s1% for $390677d after a critical heal with $?c1[Flash Heal or Penance]?c2[Flash Heal or Holy Word: Serenity][Flash Heal].", ua = "Зменшує фізичну шкоду, яку отримує ваша ціль, на $390677s1% протягом $390677d після критичного зцілення за допомогою $?c1[«Швидкого зцілення» або «Покути»]?c2[«Швидкого зцілення» або «Святого слова: Безтурботність»][«Швидкого зцілення»]." },
    { en = "Reduces the cooldown of Power Word: Radiance by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Слова сили: Сяйво» на ${$s1/-1000} сек." },
    { en = "Reduces the cast time of Power Word: Radiance by $s2% and causes it to apply Atonement at an additional $s1% of its normal duration.", ua = "Скорочує час творення «Слова сили: Сяйво» на $s2% і змушує його накладати «Спокуту» з тривалістю, збільшеною на $s1% від звичайної." },
    { en = "Each Penance bolt extends the duration of Shadow Word: Pain on enemies hit by ${$s1/1000}.1 sec.", ua = "Кожен снаряд «Покути» подовжує дію «Слова тіні: Біль» на уражених ворогах на ${$s1/1000}.1 сек." },
    { en = "Increases the damage of Shadow Word: Pain by $s1% and increases its duration by ${$s3/1000} sec.", ua = "Збільшує шкоду «Слова Тіні: Біль» на $s1% і подовжує його дію на ${$s3/1000} сек." },
    { en = "Casting Power Word: Shield increases your Haste by $s2% for $390692d.", ua = "Творення «Слова сили: Щит» збільшує твій поспіх на $s2% на $390692d." },
    { en = "Flash Heal, Power Word: Shield, Penance, and Power Word: Radiance have a $s1% increased chance to critically heal.", ua = "«Швидке зцілення», «Слово сили: Щит», «Покута» й «Слово сили: Сяйво» мають на $s1% більший шанс критичного зцілення." },
    { en = "While stealthed, Rake will also stun the target for $163505d, and deal $1822s4% increased damage for its full duration.\n\n\n\nWhile stealthed, Shred deals $5221s3% increased damage, has double the chance to critically strike, and generates $343232s1 additional combo $lpoint:points;.", ua = "У схованці Дряпання також приголомшує ціль на $163505d і завдає на $1822s4% більше шкоди протягом усієї своєї тривалості.\n\n\n\nУ схованці Шматування завдає на $5221s3% більше шкоди, має подвоєний шанс критичного удару і дає $343232s1 додаткове $lочко комбо:очка комбо;." },
    { en = "Your Penance bolts increase the absorb of your next Power Word: Shield by $390787s2%.\n\n\n\nStacks up to $390787U times.", ua = "Стріли вашої Покути збільшують поглинання вашого наступного Слова сили: Щит на $390787s2%.\n\n\n\nНакопичується до $390787U разів." },
    { en = "Immolation Aura has $s4% increased critical strike chance and generates $m1-$M1 Fury when it deals critical damage.\n\n\n\nThis effect may only occur once per ${$proccooldown+0.1} sec.", ua = "Аура спалення має на $s4% збільшений шанс критичного удару й створює $m1-$M1 Люті, коли завдає критичної шкоди.\n\n\n\nЦей ефект може спрацьовувати лише раз на ${$proccooldown+0.1} сек." },
    { en = "Mind Blast and Shadow Word: Death consume $s1 sec of Shadow Word: Pain, dealing damage equal to $s2% of the amount consumed.", ua = "«Вибух розуму» та «Слово Тіні: Смерть» поглинають $s1 сек. дії «Слова Тіні: Біль», завдаючи шкоду в розмірі $s2% поглинутого." },
    { en = "Swipe damage is increased by $s1%.", ua = "Шкоду Змаху збільшено на $s1%." },
    { en = "Tiger's Fury's damage bonus is increased by $s1%.", ua = "Бонус до шкоди від «Люті тигра» збільшено на $s1%." },
    { en = "Increases the amount of damage required to break your Psychic Scream by $s1%.", ua = "Збільшує обсяг шкоди, потрібний, щоб зірвати твій «Психічний крик», на $s1%." },
    { en = "Increases the critical strike chance of Flash Heal and Prayer of Healing by $s1%.", ua = "Збільшує ймовірність критичного удару «Швидкого зцілення» та «Молитви зцілення» на $s1%." },
    { en = "Increases the healing done by your Mastery: Echo of Light by $s1% and your Renew by $s2%.", ua = "Збільшує зцілення твоєї «Майстерності: Відлуння Світла» на $s1%, а «Відновлення» — на $s2%." },
    { en = "After damaging or healing a target below $s3% health, gain $s1% increased damage and healing for $390978d.", ua = "Після завдання шкоди або зцілення цілі з менш ніж $s3% здоров'я твої шкода та зцілення збільшуються на $s1% на $390978d." },
    { en = "Prayer of Mending jumps $s1 additional $Ltime:times;.", ua = "Молитва зцілення перестрибує додатково $s1 $Lраз:разів;." },
    { en = "Flash Heal reduces the cast time of your next Prayer of Healing within $390993d by $390993s2% and increases its healing done by $390993s1%.\n\n\n\nCan accumulate up to $390993U charges.", ua = "Швидке зцілення зменшує час прочитання вашого наступного Молитовного зцілення протягом $390993d на $390993s2% і збільшує його зцілення на $390993s1%.\n\n\n\nНакопичується до $390993U зарядів." },
    { en = "Prayer of Mending $?S120517&?a1246517[and creating a Halo ][]reduces the cooldown of Holy Word: Serenity by $s2 sec.\n\n\n\n$?S120517&!?a1246517[Creating a Halo reduces the cooldown of Holy Word: Sanctify by $s1 sec.\n\n\n\n][]Holy Fire reduces the cooldown of Holy Word: Chastise by $s3 sec.", ua = "Молитва зцілення $?S120517&?a1246517[та створення Ореолу ][]зменшує перезарядження Святого слова: Умиротворення на $s2 сек.\n\n\n\n$?S120517&!?a1246517[Створення Ореолу зменшує перезарядження Святого слова: Освячення на $s1 сек.\n\n\n\n][]Святий вогонь зменшує перезарядження Святого слова: Покарання на $s3 сек." },
    { en = "Rip damage increased by $s1%.", ua = "Шкоду «Роздирання» збільшено на $s1%." },
    { en = "Tiger's Fury lasts ${$s1/1000} additional seconds.", ua = "«Лють тигра» триває на ${$s1/1000} сек. довше." },
    { en = "Mind Flay damage increases the critical strike chance of Mind Blast by $s1%, stacking up to $391092U times.\n\n\n\nLasts $391092d.", ua = "Шкода від Шмагання розуму збільшує шанс критичного удару Удару розуму на $s1%, накопичуючись до $391092U разів.\n\n\n\nТриває $391092d." },
    { en = "Increases your periodic spell damage by $s1%.", ua = "Збільшує періодичну шкоду твоїх заклять на $s1%." },
    { en = "After Spirit of Redemption expires, you will revive at up to $s1% health, based on your healing done during Spirit of Redemption. After reviving, you cannot benefit from Spirit of Redemption for $211319d.", ua = "Після завершення «Духа відкуплення» ти оживеш із щонайбільше $s1% здоров'я залежно від зцілення, виконаного під час дії «Духа відкуплення». Після оживлення ти не можеш скористатися «Духом відкуплення» протягом $211319d." },
    { en = "Hammer of Wrath and Judgment deal $s2% additional damage and extend the duration of $?s384092[Crusade]?s394088[Avenging Crusader]?s385438[Sentinel][Avenging Wrath] by ${$s1/1000}.1 sec.", ua = "«Молот гніву» та «Осуд» завдають на $s2% більше шкоди й подовжують тривалість $?s384092[«Хрестового походу»]?s394088[«Хрестоносця-месника»]?s385438[«Вартового»][«Гніву месника»] на ${$s1/1000}.1 с." },
    { en = "Increases the critical strike chance of Mind Blast, Mind Flay, and Shadow Word: Death by $s1% and increases their critical strike damage by $s2%.", ua = "Збільшує ймовірність критичного удару «Вибуху розуму», «Терзання розуму» та «Слова Тіні: Смерть» на $s1%, а їхню критичну шкоду — на $s2%." },
    { en = "Reduces the cooldown of $?s102543[Incarnation: Avatar of Ashamane][Berserk] by ${$s1/-1000} sec.", ua = "Зменшує перезарядження $?s102543[«Втілення: аватар Ашамани»][«Берсерка»] на ${$s1/-1000} сек." },
    { en = "Fel Devastation heals you for up to $s1% more, based on your missing health.", ua = "«Спустошення Скверни» зцілює тебе до $s1% сильніше залежно від того, скільки здоров'я тобі бракує." },
    { en = "Prayer of Mending has a $s1% chance to not consume a charge when it jumps to a new target.", ua = "«Молитва відновлення» має $s1% шансу не витратити заряд, коли перестрибує на нову ціль." },
    { en = "$?s203555[Demon Blades][Demon's Bite] and Throw Glaive leave open wounds on your enemies, dealing $391191o1 Chaos damage over $391191d and increasing damage taken from your Immolation Aura by $391191s2%.\n\n\n\nMay be applied to up to $s2 targets.", ua = "$?s203555[Клинки демона][Укус демона] та Метання глефи залишають на ваших ворогах відкриті рани, які завдають $391191o1 хаотичної шкоди протягом $391191d і збільшують отримувану ними шкоду від вашої Аури спалення на $391191s2%.\n\n\n\nМоже застосовуватися до $s2 цілей." },
    { en = "The primary target of Prayer of Healing is healed for $s1% more.", ua = "Основна ціль «Молитви зцілення» отримує на $s1% більше зцілення." },
    { en = "Vampiric Touch deals $s1% additional damage and has a chance to generate ${$s2/100} Insanity each time it deals damage.", ua = "«Вампірський дотик» завдає на $s1% більше шкоди та має шанс породжувати ${$s2/100} од. безумства щоразу, коли завдає шкоди." },
    { en = "Prayer of Mending heals $s1% more for each bounce remaining.", ua = "«Молитва відновлення» зцілює на $s1% сильніше за кожен невикористаний стрибок." },
    { en = "Cooldown of $?c1[Die By the Sword]?c2[Enraged Regeneration][Shield Wall], Intervene, $?c3[][Interpose, ]Spell Reflection, Storm Bolt, and Pummel reduced by $s1%.\n\n\n\nSuccessfully interrupting an enemy increases the damage you deal to them by $383116s2% for $383116d.", ua = "Перезарядження $?c1[Смерті від меча]?c2[Розлюченого відновлення][Захисного муру], Втручання, $?c3[][Заслону, ]Відбиття закляття, Громового болта та Молотіння зменшено на $s1%.\n\n\n\nУспішне переривання ворога збільшує шкоду, яку ви йому завдаєте, на $383116s2% протягом $383116d." },
    { en = "Throw Glaive deals $s2% increased damage, reduced by ${$s2/2}% for each previous enemy hit.", ua = "«Кидок глефи» завдає на $s2% більше шкоди; цей бонус зменшується на ${$s2/2}% за кожного раніше враженого ворога." },
    { en = "Your Shadow Word: Pain damage has a chance to create Shadowy Apparitions that float towards all targets afflicted by your Vampiric Touch. \n\n\n\nCritical strikes increase the chance by $s1%.", ua = "Шкода вашого «Слова тіні: Біль» має шанс створити Тіньові примари, що пливуть до всіх цілей під дією вашого «Вампірського дотику». \n\n\n\nКритичні удари збільшують цей шанс на $s1%." },
    { en = "The cooldown of Touch of Death is reduced by ${$s2/-1000} sec.\n\n\n\nTouch of Death deals an additional $s1% damage.", ua = "Перезарядження Дотику смерті скорочується на ${$s2/-1000} сек.\n\n\n\nДотик смерті завдає додаткові $s1% шкоди." },
    { en = "Applying Rip to a target also applies a Tear that deals $s1% of the new Rip's damage over $391356d.", ua = "Накладання «Розриву» на ціль також накладає «Шматування», що завдає $s1% шкоди нового «Розриву» протягом $391356d." },
    { en = "The duration of $?s152173[Serenity][Zenith] is extended by ${$s1/1000} sec.", ua = "Тривалість $?s152173[Безтурботності][Зеніту] подовжено на ${$s1/1000} с." },
    { en = "Increases healing by $s1% on friendly targets at or below $s2% health.", ua = "Збільшує зцілення на $s1% для дружніх цілей із $s2% здоров'я чи менше." },
    { en = "Blackout Kick critical strike chance increased by $s1% and critical damage increased by $s2%.", ua = "Шанс критичного удару «Удару затьмарення» збільшено на $s1%, а критичну шкоду — на $s2%." },
    { en = "Anti-Magic Shell heals you for $s1% of the damage it absorbs.", ua = "Антимагічна оболонка зцілює тебе на $s1% поглинутої нею шкоди." },
    { en = "Blood Shield's duration is increased by ${$s1/1000} sec and it absorbs $s2% more damage.", ua = "Тривалість Кривавого щита збільшена на ${$s1/1000} сек., і він поглинає на $s2% більше шкоди." },
    { en = "The cooldown of $?a212613[Infernal Strike]?a1213636[Shift][Fel Rush] is reduced by ${-$s1/1000}.1 sec.", ua = "Перезарядження $?a212613[Інфернального удару]?a1213636[Зсуву][Ривка Скверни] зменшено на ${-$s1/1000}.1 сек." },
    { en = "While Blood Shield is active, you deal $s1% increased damage.", ua = "Поки діє «Кривавий щит», ти завдаєш на $s1% більше шкоди." },
    { en = "Mind Flay damage increased by $s1% and Insanity generation increased by $s2%.", ua = "Шкода «Катування розуму» збільшена на $s1%, а породження безумства — на $s2%." },
    { en = "Increases your chance to parry by $s1%.", ua = "Збільшує твій шанс парирування на $s1%." },
    { en = "You deal $391459s1% more damage and receive $391459s2% more healing while standing in your Death and Decay.", ua = "Ти завдаєш на $391459s1% більше шкоди й отримуєш на $391459s2% більше зцілення, стоячи в зоні своєї «Смерті й розкладу»." },
    { en = "Enemies affected by Blood Plague take $s1% increased damage from you and Death Strike increases the damage of your Blood Plague by $391481s1% for $391481d, stacking up to $391481u times.", ua = "Вороги під дією Кривавої чуми отримують від тебе на $s1% більше шкоди, а Смертельний удар збільшує шкоду твоєї Кривавої чуми на $391481s1% на $391481d, накопичуючись до $391481u разів." },
    { en = "After Vampiric Blood expires, you absorb damage equal to $s1 times the damage your Blood Plague dealt during Vampiric Blood.", ua = "Коли дія Вампірської крові завершується, ти поглинаєш шкоду, що дорівнює шкоді, яку твоя Кривава чума завдала під час дії Вампірської крові, помноженій на $s1." },
    { en = "Call upon the spirits for an eruption of energy, channeling a rapid flurry of $s2 Druid spells and abilities over $d.$?s391538[ Chance to use an exceptional spell or ability is increased.][]\n\n\n\nYou will cast $?a24858|a197625[Starsurge, Starfall,]?a768[Ferocious Bite, Shred,]?a5487[Mangle, Ironfur,][Wild Growth, Swiftmend,] Moonfire, Wrath, Regrowth, Rejuvenation, Rake, and Thrash on appropriate nearby targets, favoring your current shapeshift form.", ua = "Закликає духів спричинити сплеск енергії, нанизуючи швидку низку з $s2 заклять та вмінь друїда впродовж $d.$?s391538[ Шанс застосувати виняткове закляття чи вміння збільшено.][]\n\n\n\nВи застосуєте $?a24858|a197625[Зоряний потік, Зорепад,]?a768[Лютий укус, Шматування,]?a5487[Шматування, Залізне хутро,][Дикий ріст, Швидке зцілення,] Місячний вогонь, Гнів, Відростання, Омолодження, Дряпання та Молотіння на відповідних цілях поблизу, віддаючи перевагу вашій поточній подобі." },
    { en = "Death's Advance grants an additional $s1% movement speed over the first $338093d.$?s1233429[\n\n\n\nMovement speed while using Price of Progress is increased by $1233429s6%.][]", ua = "Поступ смерті надає додаткові $s1% швидкості пересування протягом перших $338093d.$?s1233429[\n\n\n\nШвидкість пересування під час застосування Ціни поступу збільшена на $1233429s6%.][]" },
    { en = "$@spellicon102543$@spellname102543\n\n$@spelldesc1244546\n\n\n\n$@spellicon391528 $@spellname391528\n\nConvoke the Spirits' cooldown is reduced by ${($abs($391538s4)/120000)*100}% and its duration and number of spells cast is reduced by $391538s1%. Convoke the Spirits has an increased chance to use an exceptional spell or ability.", ua = "$@spellicon102543$@spellname102543\n\n$@spelldesc1244546\n\n\n\n$@spellicon391528 $@spellname391528\n\nПерезарядження Скликання духів зменшено на ${($abs($391538s4)/120000)*100}%, а його тривалість і кількість застосованих заклять зменшено на $391538s1%. Скликання духів має підвищений шанс застосувати виняткове закляття чи вміння." },
    { en = "Rapid Fire deals $s1% additional damage, and Aimed Shot has a $s3% chance to reset the cooldown of Rapid Fire.", ua = "Швидкий вогонь завдає на $s1% більше шкоди, а Прицільний постріл має $s3% шансу скинути перезарядження Швидкого вогню." },
    { en = "Your auto-attacks reduce the target's auto-attack speed by $s1% for $391568d, stacking up to $391568u times.", ua = "Твої автоатаки зменшують швидкість автоатак цілі на $s1% на $391568d. Складається до $391568u разів." },
    { en = "Absorbs are $s1% more effective on you.", ua = "Поглинальні ефекти на тобі дієвіші на $s1%." },
    { en = "Rake also applies Rake to $s1 additional nearby $Ltarget:targets;.", ua = "«Дряпання» також накладає «Дряпання» ще на $s1 $Lціль поблизу:цілі поблизу;." },
    { en = "Ferocious Bite also deals $391710s1 damage per combo point spent to all nearby enemies. Spending extra Energy on Ferocious Bite increases damage dealt by up to $s2%. Damage reduced beyond $s1 $Ltarget:targets;.", ua = "«Лютий укус» також завдає всім ворогам поруч $391710s1 од. шкоди за кожне витрачене комбо-очко. Витрата додаткової енергії на «Лютий укус» збільшує завдану шкоду щонайбільше на $s2%. Понад $s1 цілей шкода зменшується." },
    { en = "Tiger's Fury causes your next $391873n finishing $Lmove:moves; to restore $391874s1 combo $Lpoint:points;.\n\n\n\nTiger's Fury also increases the periodic damage of your bleeds $?a155580[and Moonfire ][]by an additional $s3% for their full duration.", ua = "Лють тигра змушує ваші наступні $391873n завершальні $Lприйом:прийоми; відновлювати $391874s1 $Lочко комбо:очка комбо;.\n\n\n\nЛють тигра також підвищує періодичну шкоду ваших кровотеч $?a155580[і Місячного вогню ][]додатково на $s3% протягом усієї їх тривалості." },
    { en = "Finishing moves have a $s1% chance per combo point spent to grant $391876s1% Haste for $391876d.", ua = "Завершальні прийоми мають $s1% шансу за кожне витрачене очко комбо дати тобі $391876s1% поспіху на $391876d." },
    { en = "Rip damage has a ${$s1/10}.1% chance to make your next Ferocious Bite free and deal the maximum damage.", ua = "Шкода «Роздирання» з імовірністю ${$s1/10}.1% робить твій наступний «Лютий укус» безкоштовним і змушує його завдати максимальної шкоди." },
    { en = "Rip and Rake last $s1% longer.", ua = "«Роздирання» та «Дряпання» тривають на $s1% довше." },
    { en = "While Bestial Wrath is active, your pet's critical damage dealt is increased by $392054s1%.", ua = "Поки діє «Звірячий гнів», критична шкода, яку завдає твій улюбленець, збільшена на $392054s1%." },
    { en = "When your Rejuvenation heals a full health target, its duration is increased by $s1 sec, up to a maximum total increase of $s2 sec per cast.", ua = "Коли твоє «Омолодження» зцілює ціль із повним здоров'ям, його тривалість збільшується на $s1 сек., щонайбільше на $s2 сек. сумарно за одне творення." },
    { en = "Allies protected by your Ironbark also receive $s1% of the healing from each of your active Rejuvenations and Ironbark's duration is increased by ${$s2/1000} sec.", ua = "Союзники під захистом твоєї «Залізної кори» також отримують $s1% зцілення від кожного твого активного «Омолодження», а тривалість «Залізної кори» збільшена на ${$s2/1000} сек." },
    { en = "Wild Growth momentarily shifts your mind into the Emerald Dream, instantly healing all allies affected by your Rejuvenation or Regrowth for $392147s1.", ua = "«Дикий ріст» на мить переносить твій розум у Смарагдовий Сон, миттєво зцілюючи всіх союзників під дією твого «Омолодження» чи «Відростання» на $392147s1 од." },
    { en = "Lifebloom stacks every $s1 sec, stacking up to ${$s2+1} times.", ua = "«Цвіт життя» накопичується кожні $s1 сек., до ${$s2+1} разів." },
    { en = "Ysera's Gift now heals every ${$s2/1000} sec and its healing is increased by $s1% for each of your active Rejuvenations.", ua = "«Дар Ізери» тепер зцілює кожні ${$s2/1000} сек., а його зцілення збільшується на $s1% за кожне твоє активне «Омолодження»." },
    { en = "Lifebloom counts for ${$s1+1} stacks of Mastery: Harmony.", ua = "«Цвіт життя» зараховується як ${$s1+1} накопичень «Майстерності: Гармонія»." },
    { en = "The healing bonus to Regrowth from Nature's Swiftness is increased by $s1%.", ua = "Бонус до зцілення Відростання від Швидкості природи збільшено на $s1%." },
    { en = "Soul of the Forest now causes your next Rejuvenation or Regrowth to apply to $s1 additional $Lally:allies; within $189877s1 yards of the target.", ua = "«Душа лісу» тепер змушує твоє наступне «Омолодження» чи «Відростання» подіяти ще на $s1 союзників у радіусі $189877s1 м від цілі." },
    { en = "When Lifebloom blooms, up to $s1 targets within your Efflorescence are healed for $392329s1.", ua = "Коли «Цвіт життя» розквітає, до $s1 цілей у межах твого «Буйноцвіття» зцілюються на $392329s1." },
    { en = "Increase the chance for Mastery: Enhanced Elements to trigger Windfury and Stormsurge by $s1%.", ua = "Збільшує на $s1% шанс, що «Майстерність: посилені стихії» викличе «Лють вітру» та «Сплеск бурі»." },
    { en = "Every $s1 casts of Swiftmend grants you Incarnation: Tree of Life for $s2 sec.", ua = "Кожні $s1 творень «Швидкого зцілення» дарують тобі «Втілення: Древо Життя» на $s2 сек." },
    { en = "Nature's Cure additionally removes all Curse and Poison effects.", ua = "«Ліки природи» додатково знімають усі ефекти проклять і отрут." },
    { en = "Swiftmend no longer consumes a heal over time effect, and extends the duration of your heal over time effects on the target by $s1 sec.", ua = "Швидке загоєння більше не поглинає ефект періодичного зцілення та подовжує тривалість твоїх ефектів періодичного зцілення на цілі на $s1 сек." },
    { en = "Shadow Word: Death damage increased by $s1%.\n\n\n\nShadow Word: Death gains its damage and talent bonuses against targets below ${$s2+$s3}% health instead of $s3%.", ua = "Шкоду «Слова тіні: Смерть» збільшено на $s1%.\n\n\n\n«Слово тіні: Смерть» отримує свої бонуси до шкоди й талантів проти цілей зі здоров'ям нижче ${$s2+$s3}% замість $s3%." },
    { en = "Your ghoul's attacks have a chance to apply Enfeeble, reducing the enemies movement speed by $392490s1% and the damage they deal to you by $392490s2% for $392490d.", ua = "Атаки твого гуля мають шанс накласти «Знесилення», зменшуючи швидкість руху ворогів на $392490s1%, а шкоду, якої вони тобі завдають, — на $392490s2% протягом $392490d." },
    { en = "Critical strike chance increased by $s1% and critical strike damage of Execute increased by $s2%.", ua = "Шанс критичного удару збільшено на $s1%, а шкоду критичних ударів Страти — на $s2%." },
    { en = "$?c1[Mortal Strike and Cleave have]?c2[Rampage has][Revenge has] a $h% chance to immediately refund $?c1[$s1]?c2[$s2][$s3]% of the Rage spent.", ua = "$?c1[«Смертельний удар» і «Розсікання» мають]?c2[«Шаленство» має][«Помста» має] $h% шанс негайно повернути $?c1[$s1]?c2[$s2][$s3]% витраченої Люті." },
    { en = "Expel Harm's healing increased by $s1% and critical strike chance increased by $s2%.", ua = "Зцілення «Вигнання шкоди» збільшено на $s1%, а його шанс критичного удару — на $s2%." },
    { en = "Holy Light heals up to $s2 targets within $392903a1 yds for $s1% of its healing.", ua = "«Святе Світло» зцілює до $s2 цілей у радіусі $392903a1 м на $s1% свого зцілення." },
    { en = "Infusion of Light has $s1 additional charge.", ua = "Кількість зарядів «Вливання Світла» збільшено на $s1." },
    { en = "Expel Harm's critical healing is increased by $s1%.", ua = "Критичне зцілення «Вигнання шкоди» збільшено на $s1%." },
    { en = "The cooldown of Aura Mastery is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Майстерності аур» зменшено на ${$s1/-1000} сек." },
    { en = "$@spelltooltip5394", ua = "$@spelltooltip5394" },
    { en = "Lay on Hands' cooldown is reduced by ${$s1/1000}.1 sec per Holy Power spent.", ua = "Перезарядження «Покладання рук» скорочується на ${$s1/1000}.1 сек. за кожну витрачену одиницю Святої сили." },
    { en = "While Enraged, Bloodthirst and Raging Blow deal $s1% increased damage.", ua = "Поки діє «Розлюченість», «Жага крові» та «Лютий удар» завдають на $s1% більше шкоди." },
    { en = "Raging Blow deals $386045s1% increased damage and while Enraged, Raging Blow has a $s1% increased chance to instantly reset its own cooldown.", ua = "«Лютий удар» завдає на $386045s1% більше шкоди, а в стані розлюченості «Лютий удар» має на $s1% вищу ймовірність миттєво скинути власне перезарядження." },
    { en = "Judgment grants an absorb shield on up to $s2 injured allies for $414411s2% of the damage done, split evenly among them.\n\n\n\nFlash of Light and Holy Light critical strikes reset the cooldown of Judgment.", ua = "«Осуд» дарує щит поглинання до $s2 поранених союзників розміром $414411s2% завданої шкоди, рівномірно розподілений між ними.\n\n\n\nКритичні удари «Спалаху світла» та «Святого світла» скидають перезарядження «Осуду»." },
    { en = "When empowered by Rime, Howling Blast deals $s1% increased damage to your primary target.", ua = "Підсилений «Паморозтю», «Виючий шквал» завдає на $s1% більше шкоди твоїй основній цілі." },
    { en = "Rising Sun Kick has a chance equal to $s2% of your haste to trigger a second time, dealing $392959s1 Physical damage and restoring $s3 Chi.", ua = "Удар висхідного сонця має шанс, рівний $s2% твого поспіху, спрацювати вдруге, завдаючи $392959s1 фізичної шкоди та відновлюючи $s3 чі." },
    { en = "Consuming Infusion of Light reduces the cooldown of Holy Shock by ${$s1/-1000}.1 sec.", ua = "Споживання «Вливання Світла» зменшує перезарядження «Святого шоку» на ${$s1/-1000}.1 сек." },
    { en = "Spinning Crane Kick detonates into a Chi Explosion, dealing $393056s1 Nature damage to all enemies within $393056A1 yards, reduced beyond $s3 targets.", ua = "Обертовий удар журавля детонує Вибухом чі, завдаючи $393056s1 шкоди від сил природи всім ворогам у радіусі $393056A1 м. Шкода зменшується, якщо цілей більше ніж $s3." },
    { en = "Blackout Kick damage increased by $s2% and strikes an additional $s1 $ltarget;targets at $s3% effectiveness.", ua = "Шкода від Удару затьмарення збільшена на $s2%, і він вражає додатково $s1 $lціль;цілей з ефективністю $s3%." },
    { en = "Strike with both fists at all enemies in front of you, dealing ${$395519s1+$395521s1} Physical damage and reducing movement speed by $s2% for $d. Deals reduced damage to secondary targets.", ua = "Б'єш обома кулаками всіх ворогів перед собою, завдаючи ${$395519s1+$395521s1} фізичної шкоди та сповільнюючи їхній рух на $s2% на $d. Другорядним цілям завдає зменшену шкоду." },
    { en = "Strike of the Windlord and Whirling Dragon Punch grant you $s1 stacks of Thunderfist and an additional stack for each additional enemy struck. \n\n\n\nThunderfist discharges upon melee strikes, dealing $393566s1 Nature damage.", ua = "Удар повелителя вітрів і Вихровий удар дракона надають вам $s1 стаків Громокулака та додатковий стак за кожного додаткового враженого ворога. \n\n\n\nГромокулак розряджається при ударах ближнього бою, завдаючи $393566s1 шкоди від сил природи." },
    { en = "Invoke Xuen, the White Tiger's damage is increased by ${$s1}% and its cooldown is reduced by ${$s2/-1000} sec.", ua = "Шкода «Виклику Сюеня, Білого Тигра» збільшена на ${$s1}%, а його перезарядження скорочено на ${$s2/-1000} сек." },
    { en = "Your Holy Words summon an image of a Naaru at your side. For $392990d, whenever you cast a healing or damaging spell, the Naaru will cast a similar spell.\n\n\n\nIf an image has already been summoned, that image is empowered instead.", ua = "Ваші Святі слова прикликають образ наару поруч із вами. Протягом $392990d щоразу, коли ви творите закляття зцілення чи шкоди, наару творить подібне закляття.\n\n\n\nЯкщо образ уже прикликано, натомість цей образ підсилюється." },
    { en = "Rising Sun Kick critical strikes reduce the cooldown of Fists of Fury by ${$m2/1000} sec.\n\n\n\nSpinning Crane Kick reduces the cooldown of Fists of Fury by ${$s4/1000}.1 sec for each unique target struck, up to ${$s5/1000}.1 sec.\n\n\n\nThe critical strike chance of Rising Sun Kick is increased by $s1%.", ua = "Критичні удари Удару вранішнього сонця скорочують перезарядження Кулаків люті на ${$m2/1000} сек.\n\n\n\nВихровий удар журавля скорочує перезарядження Кулаків люті на ${$s4/1000}.1 сек. за кожну унікальну вражену ціль, максимум на ${$s5/1000}.1 сек.\n\n\n\nШанс критичного удару Удару вранішнього сонця збільшується на $s1%." },
    { en = "Increases the damage of Jadefire Stomp by ${$s1}% per target hit by that damage, up to a maximum of ${$s1*$s2}% additional damage.", ua = "Збільшує шкоду «Тупоту нефритового вогню» на ${$s1}% за кожну ціль, що зазнала цієї шкоди, аж до ${$s1*$s2}% додаткової шкоди." },
    { en = "Cleanse additionally removes all Disease and Poison effects.", ua = "«Очищення» додатково знімає всі ефекти хвороб і отрут." },
    { en = "Throw Glaive now costs $s1 Fury and throws a second glaive at the target.", ua = "«Кидок глефи» тепер коштує $s1 од. люті та кидає у ціль другу глефу." },
    { en = "For each target hit by Avenger's Shield, gain $s1% parry for $393038d.", ua = "За кожну ціль, уражену «Щитом месника», ти отримуєш $s1% до парирування на $393038d." },
    { en = "Ardent Defender reduces damage taken by an additional $s1%.", ua = "«Ревний захисник» зменшує отримувану шкоду додатково на $s1%." },
    { en = "When you consume a Healing Sphere, you clear $s1% of your currently |CFFffffffStaggered|R damage.", ua = "Коли ти споживаєш цілющу сферу, знімаєш $s1% поточної |CFFffffffвідтермінованої|R шкоди." },
    { en = "$@spellicon33891 $@spellname5420\n\nDuring Incarnation: Tree of Life, you summon a Grove Guardian every $393418t sec. The cooldown of Incarnation: Tree of Life is reduced by ${$393381s1/-1000}.1 sec when Grove Guardians fade.\n\n\n\n$@spellicon391528 $@spellname391528\n\nConvoke the Spirits' cooldown is reduced by ${($abs($393374s4)/120000)*100}% and its duration and number of spells cast is reduced by $393374s1%. Convoke the Spirits has an increased chance to use an exceptional spell or ability.", ua = "$@spellicon33891 $@spellname5420\n\nПід час Втілення: дерева життя ви прикликаєте Стража гаю кожні $393418t с. Перезарядження Втілення: дерева життя зменшується на ${$393381s1/-1000}.1 с, коли Стражі гаю зникають.\n\n\n\n$@spellicon391528 $@spellname391528\n\nПерезарядження Скликання духів зменшено на ${($abs($393374s4)/120000)*100}%, а його тривалість і кількість застосованих заклять зменшено на $393374s1%. Скликання духів має підвищений шанс застосувати виняткове закляття чи вміння." },
    { en = "$@spellicon102558 $@spellname102558: \n\nEvery $s5 Rage you spend reduces the cooldown of Incarnation: Guardian of Ursoc by 1 sec.\n\n\n\n$@spellicon391528 $@spellname391528: \n\nConvoke the Spirits' cooldown is reduced by ${($abs($s4)/120000)*100}% and its duration and number of spells cast is reduced by $s1%. Convoke the Spirits has an increased chance to use an exceptional spell or ability.", ua = "$@spellicon102558 $@spellname102558: \n\nЗа кожні $s5 витраченої люті перезарядження Втілення: вартового Урсока зменшується на 1 с.\n\n\n\n$@spellicon391528 $@spellname391528: \n\nПерезарядження Скликання духів зменшено на ${($abs($s4)/120000)*100}%, а його тривалість і кількість застосованих заклять зменшено на $s1%. Скликання духів має підвищений шанс застосувати виняткове закляття чи вміння." },
    { en = "Thrash has a $s1% chance to trigger an additional Thrash.\n\n\n\nThrash stacks $s2 additional $ltime:times;.", ua = "Молотіння має $s1% шанс викликати додаткове Молотіння.\n\n\n\nМолотіння стакається $s2 додаткові $lраз:рази;." },
    { en = "Drinking a Brew grants you $393515s1% dodge for $393515d.", ua = "Випите варево дає тобі $393515s1% ухилення протягом $393515d." },
    { en = "Increases the duration of Barkskin and Ironfur by ${$m1/1000}.1 sec.", ua = "Збільшує тривалість «Кори» та «Залізного хутра» на ${$m1/1000}.1 сек." },
    { en = "Ironfur increases armor by an additional $s1% and Barkskin reduces damage taken by an additional $s2%.", ua = "«Залізне хутро» додатково збільшує броню на $s1%, а «Шкіра-кора» додатково зменшує отриману шкоду на $s2%." },
    { en = "Wrath and Starfire have a 20% chance to cause your next Wrath or Starfire cast during an Eclipse to become Astral and deal $s1% additional damage.", ua = "«Гнів» і «Зоряний вогонь» з імовірністю 20% роблять твоє наступне прочитання «Гніву» чи «Зоряного вогню» під час Затемнення астральним: воно завдає на $s1% більше шкоди." },
    { en = "Increases your mastery by ${$s1*$mas}.1%.", ua = "Збільшує твою майстерність на ${$s1*$mas}.1%." },
    { en = "Fel Devastation damage increased by $s1%.", ua = "Шкода Спустошення Скверни збільшена на $s1%." },
    { en = "Increases healing done by Flash Heal by $s1%.", ua = "Збільшує зцілення від «Швидкого зцілення» на $s1%." },
    { en = "Barbed Shot deals $s2% increased damage, and applying Barbed Shot reduces the cooldown of Kill Command by ${$s3/1000}.1 sec.", ua = "«Зазублений постріл» завдає на $s2% більше шкоди, а його накладання зменшує перезарядження «Наказу вбити» на ${$s3/1000}.1 сек." },
    { en = "Starsurge has a $s1% chance to make Starfall free. Starfall has a $s2% chance to make Starsurge free.", ua = "Зоряний сплеск має $s1% шансу зробити Зорепад безкоштовним. Зорепад має $s2% шансу зробити Зоряний сплеск безкоштовним." },
    { en = "Raging Blow increases the damage of your next Bloodthirst by $393951s1%, stacking up to $393951u times.", ua = "«Лютий удар» збільшує шкоду твоєї наступної «Спраги крові» на $393951s1%, накопичуючись до $393951u разів." },
    { en = "Starsurge and Starfall deal $s1% increased damage and their cost is reduced by $s2%.", ua = "Зоряний сплеск і Зорепад завдають на $s1% більше шкоди, а їхня вартість зменшена на $s2%." },
    { en = "You are healed for ${$393971s1*($393971d/$393971t)}% of your maximum health over $393971d after activating Vanish.", ua = "Після активації Зникнення ти зцілюєшся на ${$393971s1*($393971d/$393971t)}% максимального здоров'я протягом $393971d." },
    { en = "$@spellicon394013 $@spellname394013\n\nReduces the Astral Power cost of Starsurge by ${$s5*-1/10}, and the Astral Power cost of Starfall by ${$s6*-1/10}.\n\n\n\n$@spellicon391528 $@spellname391528\n\nCooldown is reduced by ${($abs($s4)/120000)*100}% and its duration and number of spells cast is reduced by $s1%. Convoke the Spirits has an increased chance to use an exceptional spell or ability.", ua = "$@spellicon394013 $@spellname394013\n\nЗменшує вартість Зоряного сплеску в астральній силі на ${$s5*-1/10}, а вартість Зорепаду в астральній силі на ${$s6*-1/10}.\n\n\n\n$@spellicon391528 $@spellname391528\n\nПерезарядження зменшено на ${($abs($s4)/120000)*100}%, а тривалість і кількість застосованих заклять зменшено на $s1%. Скликання духів має підвищений шанс застосувати виняткове закляття чи вміння." },
    { en = "An improved Moonkin Form that grants both Eclipses, any learned Celestial Alignment bonuses, $?a429536[$s6% increased Arcane damage, ][]and $s2% critical strike chance.\n\n\n\nLasts $d. You may shapeshift in and out of this improved Moonkin Form for its duration.", ua = "Покращена подоба сови, що надає обидва Затемнення, усі вивчені бонуси Небесного вирівнювання, $?a429536[$s6% збільшеної арканної шкоди ][]та $s2% шансу критичного удару.\n\n\n\nТриває $d. Протягом дії ви можете вільно перетворюватися на цю покращену подобу сови й назад." },
    { en = "Starsurge has a chance to summon the Spirit of Goldrinn, which immediately deals ${$s3*$<mastery>} Astral damage to the target.", ua = "Зоряний сплеск має шанс прикликати Духа Ґолдринна, який одразу завдає цілі ${$s3*$<mastery>} астральної шкоди." },
    { en = "Entering Eclipse increases your critical strike chance with Arcane or Nature spells by ${$s1*$394049u}%, decreasing by $s1% every $394049t2 sec.", ua = "Входження в затемнення збільшує твій шанс критичного удару арканними закляттями та закляттями природи на ${$s1*$394049u}%; він зменшується на $s1% кожні $394049t2 сек." },
    { en = "Your Moonfire and Sunfire have a chance to summon a Faerie Dragon to assist you in battle for $394076d.", ua = "Твої «Місячний вогонь» і «Сонячний вогонь» мають шанс прикликати фейського дракона, що допомагатиме тобі в бою протягом $394076d." },
    { en = "You become the ultimate crusader of light for $216331d. Crusader Strike and Judgment cool down $216331s2% faster and heal up to $216331s6 injured allies for $216331s5% of the damage they deal.\n\n\n\nIf |cFFFFFFFFAvenging Wrath |ris known, also increases Judgment, Crusader Strike, and auto-attack damage by $216331s1%.", ua = "Ви стаєте довершеним хрестоносцем світла на $216331d. «Удар хрестоносця» та «Осуд» перезаряджаються на $216331s2% швидше й зцілюють до $216331s6 поранених союзників на $216331s5% завданої ними шкоди.\n\n\n\nЯкщо вивчено |cFFFFFFFFКараючий гнів |r, також підвищує шкоду «Осуду», «Удару хрестоносця» та автоатак на $216331s1%." },
    { en = "Every other Eclipse creates a Fury of Elune at $s1% effectiveness that follows your current target for $s2 sec.", ua = "Кожне друге затемнення створює «Лють Елуни» з ефективністю $s1%, що йде за твоєю поточною ціллю протягом $s2 сек." },
    { en = "After you use Transcendence: Transfer, you can use Transcendence: Transfer again within $343249d, ignoring its cooldown.", ua = "Після використання «Трансцендентності: Перенесення» ти можеш ужити її знову протягом $343249d, ігноруючи перезарядження." },
    { en = "New Moon, Half Moon, and Full Moon deal $s2% increased damage. Full Moon becomes Full Moon once more before resetting to New Moon.\n\n\n\nFury of Elune deals $s3% increased damage and its cooldown is reduced by ${$s1/-1000} sec.", ua = "Молодий місяць, Півмісяць і Повний місяць завдають на $s2% більше шкоди. Повний місяць стає Повним місяцем ще раз, перш ніж скинутися до Молодого місяця.\n\n\n\nЛють Елуни завдає на $s3% більше шкоди, а її перезарядження скорочується на ${$s1/-1000} сек." },
    { en = "Touch of Death's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Дотику смерті» скорочено на ${$s1/-1000} сек." },
    { en = "Devastate deals $s1% increased damage and generates ${$s2/10} Rage.\n\n\n\nDevastator deals $s3% increased damage and generates ${$s4/10} Rage.", ua = "Спустошення завдає на $s1% більше шкоди й створює ${$s2/10} люті.\n\n\n\nСпустошувач завдає на $s3% більше шкоди й створює ${$s4/10} люті." },
    { en = "Shadow Dance has $s1 additional charge.", ua = "«Танець тіней» має $s1 додатковий заряд." },
    { en = "$?a137036[Grappling Hook][Shadowstep] has $s1 additional charge.", ua = "$?a137036[Гак-кішка][Тіньовий крок] має $s1 додатковий заряд." },
    { en = "Celestial bodies align, maintaining both Eclipses and granting $s1% haste for $d.", ua = "Небесні тіла вирівнюються, підтримуючи обидва Затемнення та надаючи $s1% поспіху протягом $d." },
    { en = "Increase all damage dealing allies' primary stat by $<amount>% of your own and increase your own damage by $395296s1% for $d.\n\n\n\nEbon Might will split its effect when applied to more than $s3 other allies.\n\n\n\nEruption, $?s403631[Breath of Eons][Deep Breath], and your empower spells extend the duration of these effects.", ua = "Підвищує основну характеристику всіх союзників, що завдають шкоди, на $<amount>% від твоєї та підвищує твою власну шкоду на $395296s1% на $d.\n\n\n\nЧорна міць розділяє свій ефект, коли діє більш ніж на $s3 інших союзників.\n\n\n\nВивергання, $?s403631[Подих еонів][Глибокий подих] і твої закляття підсилення подовжують тривалість цих ефектів." },
    { en = "Cause a violent eruption beneath an enemy's feet, dealing $s1 Volcanic damage split between them and nearby enemies.$?s395153[\n\n\n\nIncreases the duration of your active Ebon Might effects by ${$395153s1/1000}.1 sec.][]", ua = "Спричиняє потужне виверження під ногами ворога, завдаючи $s1 вулканічної шкоди, поділеної між ним і ворогами поруч.$?s395153[\n\n\n\nПодовжує тривалість ваших активних ефектів Чорної могутності на ${$395153s1/1000}.1 сек.][]" },
    { en = "Generate full combo points when you gain Adrenaline Rush.", ua = "Отримуєш повний запас комбо-очок, коли отримуєш «Приплив адреналіну»." },
    { en = "Afflicting an enemy with a Sigil generates $m1 Soul $LFragment:Fragments;.", ua = "Накладання Знаку на ворога генерує $m1 $LФрагмент:Фрагментів; душі." },
    { en = "Your Living Flame has a $376872s1% chance, and your Azure Strike has a $375721s1% chance, to make your next Eruption $?s414969[or Emerald Blossom ][]cost no Essence.$?s375722[ Stacks $359618u times.][]", ua = "Ваше «Живе полум'я» має $376872s1% шанс, а ваш «Лазуровий удар» — $375721s1% шанс, зробити так, що ваша наступна «Еруптація» $?s414969[або «Смарагдовий цвіт» ][]не коштуватиме есенції.$?s375722[ Накопичується до $359618u разів.][]" },
    { en = "Gather earthen power beneath your enemy's feet and send them hurtling upwards, dealing $396288s2 Volcanic damage to the target and nearby enemies.$?s395153[\n\n\n\nIncreases the duration of your active Ebon Might effects by ${$395153s2/1000} sec.][]\n\n\n\nEmpowering expands the area of effect.\n\n\n\n|cFFFFFFFFI:|r   $<radiusI> yd radius.\n\n\n\n|cFFFFFFFFII:|r  $<radiusII> yd radius.\n\n\n\n|cFFFFFFFFIII:|r $<radiusIII> yd radius.", ua = "Збираєш земну силу під ногами ворога й підкидаєш його вгору, завдаючи $396288s2 вулканічної шкоди цілі та ворогам поблизу.$?s395153[\n\n\n\nПодовжує тривалість твоїх активних ефектів Чорної міці на ${$395153s2/1000} с.][]\n\n\n\nПідсилення розширює зону дії.\n\n\n\n|cFFFFFFFFI:|r   Радіус $<radiusI> м.\n\n\n\n|cFFFFFFFFII:|r  Радіус $<radiusII> м.\n\n\n\n|cFFFFFFFFIII:|r Радіус $<radiusIII> м." },
    { en = "Activating Recklessness generates ${$s1/10} Rage and while Recklessness is active, Raging Blow and Bloodthirst are upgraded to Crushing Blow and Bloodbath.\n\n\n\n$@spellicon335097 $@spellname335097\n\nDeals increased damage and deals $1719s13% additional critical strike damage.\n\n\n\n$@spellicon335096 $@spellname335096\n\nDeals increased damage and wounds the target to suffer $113344o1 Bleed damage over $113344d. Using Bloodbath on a target affected by Bloodbath extends the bleed by $113344d.", ua = "Активація Безрозсудності створює ${$s1/10} люті, і поки Безрозсудність активна, Лютий удар і Жага крові поліпшуються до Нищівного удару та Кривавої купелі.\n\n\n\n$@spellicon335097 $@spellname335097\n\nЗавдає підвищеної шкоди та $1719s13% додаткової критичної шкоди.\n\n\n\n$@spellicon335096 $@spellname335096\n\nЗавдає підвищеної шкоди й ранить ціль, через що вона зазнає $113344o1 шкоди від кровотечі протягом $113344d. Використання Кривавої купелі на цілі під дією Кривавої купелі подовжує кровотечу на $113344d." },
    { en = "Shield Wall gains $s2 additional charge and its cooldown is reduced by ${$s1/-1000} sec.", ua = "«Стіна щитів» отримує $s2 додатковий заряд, а її перезарядження скорочено на ${$s1/-1000} сек." },
    { en = "Increases maximum Energy by $s1. Tiger Palm's Energy cost reduced by $s2.", ua = "Збільшує максимум енергії на $s1. Витрати енергії на «Тигрячу долоню» зменшено на $s2." },
    { en = "When Life Cocoon expires, it releases a burst of mist that restores $399230s2 health to $s3 nearby allies.", ua = "Коли «Кокон життя» спливає, він вивільняє сплеск туману, що відновлює $399230s2 здоров'я $s3 союзникам поблизу." },
    { en = "Draws in all nearby clouds of mist, healing the friendly target $?a471761[][and up to ${$s2-1} nearby allies ]for $s1 and an additional ${$s1*$s5/100} per cloud absorbed.\n\n\n\nA cloud of mist is generated every $?a400053[$400053s2][$s3] sec while in combat.", ua = "Притягує всі хмари туману поблизу, зцілюючи дружню ціль $?a471761[][та до ${$s2-1} союзників поблизу ]на $s1 і додатково на ${$s1*$s5/100} за кожну поглинуту хмару.\n\n\n\nХмара туману утворюється щоразу через $?a400053[$400053s2][$s3] сек у бою." },
    { en = "Increases Sheilun's Gift cloud of mist generation to every ${-$s1/1000} sec.", ua = "«Дар Шейлуна» створює хмарки туману частіше — кожні ${-$s1/1000} сек." },
    { en = "Your Moonfire and Sunfire deal damage $s1% more frequently, also increasing the rate that Shooting Stars fall.", ua = "Твої «Місячний вогонь» і «Сонячний вогонь» завдають шкоди на $s1% частіше; зорі «Зорепаду» також падають частіше." },
    { en = "Casting Regrowth increases your movement speed and healing received by $s1% for $400126d.", ua = "Творення «Відростання» збільшує твою швидкість руху й отримуване зцілення на $s1% на $400126d." },
    { en = "Reduces the cooldown of Typhoon by ${$m1/-1000} sec.", ua = "Зменшує перезарядження «Тайфуну» на ${$m1/-1000} сек." },
    { en = "Increases Typhoon's radius by $s1% and its range by $s2 yds.", ua = "Збільшує радіус «Тайфуну» на $s1%, а його дальність — на $s2 м." },
    { en = "Overpower deals $s1% additional damage to targets below $s2% health.", ua = "«Пересилення» завдає на $s1% більше шкоди цілям, що мають менше ніж $s2% здоров'я." },
    { en = "Strike with the might of Ursoc, dealing $s1 Physical damage to your target and $s2 to all other enemies in front of you. Damage reduced beyond $s3 targets.", ua = "Удар із міццю Урсока, що завдає $s1 фізичної шкоди твоїй цілі та $s2 — усім іншим ворогам перед тобою. Якщо цілей більше за $s3, шкода зменшується." },
    { en = "Your direct damage melee abilities against enemies afflicted by Moonfire cause them to burn for an additional $s1% Arcane damage.", ua = "Твої здібності прямої шкоди ближнього бою проти ворогів під дією «Місячного вогню» обпікають їх, завдаючи додатково $s1% арканної шкоди." },
    { en = "Your damage over time effects deal their damage in $s1% less time, and your healing over time effects in $s2% less time.", ua = "Твої ефекти періодичної шкоди завдають усю свою шкоду за час, на $s1% коротший, а ефекти періодичного зцілення — за час, на $s2% коротший." },
    { en = "Volley now also applies Explosive Shot to up to $s1 $Ltarget:targets; hit.\n\n\n\n$@spellicon212431 $@spellname212431\n\n$@spelldesc212431", ua = "Залп тепер також накладає Вибуховий постріл на щонайбільше $s1 уражену $Lціль:цілі:цілей;.\n\n\n\n$@spellicon212431 $@spellname212431\n\n$@spelldesc212431" },
    { en = "Grove Guardians, Efflorescence, and your other summons heal for $s1% more.", ua = "«Вартові гаю», «Розквіт» та інші твої прикликані істоти зцілюють на $s1% більше." },
    { en = "Blackout Kick has a chance to summon a Healing Sphere.\n\n\n\n$@spellicon224863$@spellname224863:\n\n$@spelldesc224863", ua = "Удар затьмарення має шанс закликати Зцілювальну сферу.\n\n\n\n$@spellicon224863$@spellname224863:\n\n$@spelldesc224863" },
    { en = "Overpower and Slam damage increased by $s1% and critical strike damage increased by $s2%.\n\nCritical strike chance of Slam and Overpower increased by $s3%.", ua = "Шкода Здолання та Удару збільшена на $s1%, а шкода критичних ударів збільшена на $s2%.\n\nШанс критичного удару Удару та Здолання збільшений на $s3%." },
    { en = "Reduces the duration of movement slowing effects $s1%.", ua = "Зменшує тривалість ефектів сповільнення руху на $s1%." },
    { en = "Each Holy Power spent has a $s1% chance to reset the cooldown of Blade of Justice$?s1261113[ and increase the damage of its next cast by $406086s2%.][.]", ua = "Кожна витрачена одиниця святої сили з імовірністю $s1% скидає перезарядження «Клинка правосуддя»$?s1261113[ та збільшує шкоду його наступного вжитку на $406086s2%.][.]" },
    { en = "Armor increased by $s3%, Stamina increased by $s1% and damage taken from area of effect attacks reduced by $s2%.", ua = "Броня збільшена на $s3%, витривалість — на $s1%, а шкода від атак площинної дії зменшена на $s2%." },
    { en = "$?s383328[Final Verdict][Templar's Verdict] and Blade of Justice deal $s4% increased damage.\n\n\n\nThe range of $?s383328[Final Verdict and ][]Blade of Justice is increased to $s3 yds.", ua = "$?s383328[Остаточний вирок][Вирок тамплієра] і Клинок правосуддя завдають на $s4% більше шкоди.\n\n\n\nДальність дії $?s383328[Остаточного вироку і ][]Клинка правосуддя збільшується до $s3 м." },
    { en = "Crusader Strike and Judgment hit an additional $s4 targets but deal $s3% reduced damage to secondary targets.", ua = "«Удар хрестоносця» та «Вирок» вражають додатково $s4 цілей, але завдають другорядним цілям на $s3% менше шкоди." },
    { en = "Your damage over time effects deal $s1% more damage.", ua = "Твої ефекти періодичної шкоди завдають на $s1% більше шкоди." },
    { en = "Learn to attune yourself to the essence of the Black or Bronze Dragonflights:\n\n\n\n$@spellicon403264$@spellname403264: You and your $s2 nearest allies have $403264s1% increased maximum health.\n\n\n\n$@spellicon403265$@spellname403265:You and your $s2 nearest allies have $403265s1% increased movement speed.", ua = "Учишся гармонізуватися з есенцією Чорного або Бронзового драконячих роїв:\n\n\n\n$@spellicon403264$@spellname403264: у тебе та твоїх $s2 найближчих союзників максимальне здоров'я підвищене на $403264s1%.\n\n\n\n$@spellicon403265$@spellname403265: у тебе та твоїх $s2 найближчих союзників швидкість руху підвищена на $403265s1%." },
    { en = "Divine Storm heals you and up to $s2 nearby allies for $403460s1.", ua = "«Божественна буря» зцілює тебе та до $s2 союзників поблизу на $403460s1 од." },
    { en = "Judgment deals $s2% increased damage and increases your movement speed by $20271s2% for $20271d.\n\n\n\nIf you have Greater Judgment, Judgment slows enemies by $408383s1% for $408383d.", ua = "«Осуд» завдає на $s2% більше шкоди й підвищує вашу швидкість руху на $20271s2% на $20271d.\n\n\n\nЯкщо ви маєте «Великий осуд», «Осуд» сповільнює ворогів на $408383s1% на $408383d." },
    { en = "Auto-attack speed increased by $s1%.", ua = "Швидкість автоатак збільшена на $s1%." },
    { en = "Increases Omen of Clarity's chance to activate Clearcasting to $s3% and Clearcasting can stack $s1 additional time.", ua = "Збільшує шанс «Знамення ясності» активувати «Ясне чарування» до $s3%, а «Ясне чарування» може накопичуватися ще $s1 раз." },
    { en = "Successfully interrupting an enemy with Rebuke$?s31935[ or Avenger's Shield][] casts an extra $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike].", ua = "Успішне переривання ворога «Докором»$?s31935[ або «Щитом месника»][] додатково творить $?s204019[«Благословенний молот»]?s53595[«Молот праведника»]?s137029[«Священний шок»][«Удар хрестоносця»]." },
    { en = "Fly to the targeted location, exposing a $@spellname409560 on enemies in your path for $409560d$?s395153[ and granting Ebon Might for ${$395153s3/1000} sec.][.]\n\n\n\nRemoves roots and grants immunity to movement impairing and loss of control effects while flying.\n\n\n\n$@spellicon409560 $@spellname409560\n\n$409560s1% of damage dealt by allies affected by Ebon Might is copied as additional Arcane damage to enemies after $409560d.\n\n\n\nDamage is reduced if Ebon Might affects more than $395152s3 other allies.", ua = "Летиш до позначеного місця, накладаючи на ворогів на твоєму шляху $@spellname409560 на $409560d$?s395153[ і даруючи Чорну міць на ${$395153s3/1000} с.][.]\n\n\n\nЗнімає знерухомлення й дарує імунітет до ефектів сповільнення руху та втрати контролю під час польоту.\n\n\n\n$@spellicon409560 $@spellname409560\n\n$409560s1% шкоди, завданої союзниками під дією Чорної міці, копіюється як додаткова арканна шкода ворогам після $409560d.\n\n\n\nШкода зменшується, якщо Чорна міць діє більш ніж на $395152s3 інших союзників." },
    { en = "$?s406646[Templar Strikes, ]?s404542[Crusading Strikes, ][Crusader Strike, ]Judgment and Blade of Justice deal $s2% increased damage.", ua = "$?s406646[«Удари храмовника», ]?s404542[«Удари хрестоносця», ][«Удар хрестоносця», ]«Осуд» та «Клинок правосуддя» завдають на $s2% більше шкоди." },
    { en = "Blade of Justice now has ${$s1+1} charges.", ua = "«Клинок правосуддя» тепер має ${$s1+1} заряди." },
    { en = "Blade of Justice now hits nearby enemies for $404358s1 Holy damage. \n\n\n\nDeals reduced damage beyond 5 targets.", ua = "«Клинок правосуддя» тепер уражає ворогів поблизу, завдаючи $404358s1 священної шкоди. \n\n\n\nЗавдає зменшеної шкоди понад 5 цілей." },
    { en = "Fatal attacks are diverted into a nearby timeline, preventing the damage, and your death, in this one.\n\n\n\nThe release of temporal energy restores ${$404381o1*(1+$404381s2/100)} health to you, and $404381o1 to ${$404381i-1} nearby allies, over $404381d. Healing starts high and declines over the duration.\n\n\n\nMay only occur once every $404369d.", ua = "Смертельні атаки відхиляються до сусідньої часової лінії, відвертаючи шкоду й вашу смерть у цій лінії.\n\n\n\nВивільнення часової енергії відновлює вам ${$404381o1*(1+$404381s2/100)} здоров'я, а ${$404381i-1} найближчим союзникам — $404381o1 здоров'я протягом $404381d. Спершу зцілення велике й поступово спадає.\n\n\n\nМоже статися лише раз на $404369d." },
    { en = "When your health is brought below $s1%, you instantly cast a free Word of Glory at $s2% effectiveness on yourself.\n\n\n\nCannot occur more than once every $proccooldown sec.", ua = "Коли ваше здоров'я падає нижче $s1%, ви миттєво й безкоштовно творите на себе «Слово слави» з $s2% ефективністю.\n\n\n\nМоже спрацьовувати не частіше ніж раз на $proccooldown с." },
    { en = "Sheilun's Gift heals $s1 additional allies and its cast time is reduced by ${$s2/-1000}.1 sec.", ua = "Дар Шейлун зцілює на $s1 союзників більше, а час його прочитання скорочено на ${$s2/-1000}.1 сек." },
    { en = "Reduces the cooldown of Blade of Justice by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Клинка правосуддя» на ${$s1/-1000} сек." },
    { en = "Mastery: Highlord's Judgment is ${$s3/2}% more effective on Judgment and Hammer of Wrath. Judgment applies an additional stack of Greater Judgment if it is known.", ua = "«Майстерність: Осуд верховного лорда» на ${$s3/2}% ефективніша для «Осуду» та «Молота гніву». «Осуд» накладає додатковий заряд «Великого осуду», якщо його вивчено." },
    { en = "Regrowth's healing over time is increased by $s1%, and it also applies to the target of your Lifebloom.", ua = "Поступове зцілення «Відростання» збільшено на $s1%, і воно також діє на ціль твого «Життєцвіту»." },
    { en = "Crusader Strike replaces your auto-attacks and deals $408385s1 $?Physical damage, but you auto-attack $s2% slower.", ua = "«Удар хрестоносця» заміняє твої автоатаки та завдає $408385s1 $?Physical шкоди, але твої автоатаки на $s2% повільніші." },
    { en = "Surge forward in time, causing your cooldowns to recover $s1% faster for $d.", ua = "Поринає вперед у часі, прискорюючи відновлення твоїх перезаряджень на $s1% протягом $d." },
    { en = "Judgment has a $s3% increased chance to trigger Mastery: Highlord's Judgment.", ua = "«Осуд» має на $s3% більший шанс активувати «Майстерність: Осуд верховного лорда»." },
    { en = "Wake of Ashes deals significantly reduced damage to secondary targets, but now causes you to lash out $s2 extra times for $405345s1 Radiant damage.", ua = "«Слід попелу» завдає значно менше шкоди другорядним цілям, але тепер ти б'єш іще $s2 додаткових разів, завдаючи $405345s1 променистої шкоди." },
    { en = "Judgment now has ${$s1+1} charges.", ua = "«Осуд» тепер має ${$s1+1} заряди." },
    { en = "Your auto attacks have a $s1% chance to reset the cooldown of Blade of Justice$?s1261113[ and increase the damage of its next cast by $406086s2%.][.]\n\n\n\nCritical strikes increase the chance by an additional $s2%.", ua = "Ваші автоатаки мають $s1% шансу скинути перезарядження Клинка правосуддя$?s1261113[ і збільшити шкоду його наступного застосування на $406086s2%.][.]\n\n\n\nКритичні удари збільшують цей шанс ще на $s2%." },
    { en = "$?c2[Shield of the Righteous][Word of Glory] grants $s1% bonus armor for $d.", ua = "$?c2[Щит праведника][Слово слави] надає $s1% додаткової броні на $d." },
    { en = "Crusader Strike and auto-attacks deal $s3% increased damage and deal $s4% increased critical strike damage.", ua = "«Удар хрестоносця» та автоатаки завдають на $s3% більше шкоди та на $s4% більше шкоди від критичних ударів." },
    { en = "Holy Power spending abilities deal $s1% increased damage.\n\n\n\nAfter casting Execution Sentence, your next $1253174u Holy Power $lability:abilities; will refund $lits:their; Holy Power cost.", ua = "Здібності, що витрачають Святу Силу, завдають на $s1% більше шкоди.\n\n\n\nПісля прочитання Смертного вироку ваші наступні $1253174u $lздібність, що витрачає:здібності, що витрачають:здібностей, що витрачають; Святу Силу, $lповерне:повернуть; її витрату." },
    { en = "$?s2812[Denounce][Shield of the Righteous] heals you and up to $s3 nearby allies for $403460s1.", ua = "$?s2812[«Викриття»][«Щит праведника»] зцілює тебе та до $s3 союзників поблизу на $403460s1." },
    { en = "You deal $383346s2% increased Holy damage to targets burning from your Expurgation.", ua = "Ти завдаєш на $383346s2% більше святої шкоди цілям, які палають від твого «Викорінення»." },
    { en = "Crusader Strike loses a charge but is now a combo ability.\n\n\n\nTemplar Strike slashes an enemy for $407480s1 Radiant damage and gets followed up by Templar Slash that deals $406647s1 Radiant damage. Templar Slash always critically strikes.", ua = "«Удар хрестоносця» втрачає заряд, але тепер є комбо-здібністю.\n\n\n\n«Удар храмовника» розтинає ворога, завдаючи $407480s1 променистої шкоди, а за ним слідує «Розтин храмовника», що завдає $406647s1 променистої шкоди. «Розтин храмовника» завжди завдає критичного удару." },
    { en = "Eruption deals $s1% more damage per enemy struck, up to ${$s2*$s1}%.", ua = "«Виверження» завдає на $s1% більше шкоди за кожного враженого ворога, аж до ${$s2*$s1}%." },
    { en = "Evoke a paradox for you and a friendly healer, allowing casting while moving and increasing the range of most spells by $s4% for $d.\n\n\n\nAffects the nearest healer within $407497A1 yds, if you do not have a healer targeted.", ua = "Викликає парадокс для вас і дружнього цілителя, дозволяючи творити закляття на ходу та збільшуючи дальність більшості заклять на $s4% на $d.\n\n\n\nДіє на найближчого цілителя в межах $407497A1 м, якщо ви не обрали цілителя ціллю." },
    { en = "Mind Blast gains an additional charge.", ua = "«Вибух розуму» отримує додатковий заряд." },
    { en = "Increases the duration of Avenging Wrath or Crusade by ${$s1/1000} sec.", ua = "Збільшує тривалість «Гніву месника» або «Хрестового походу» на ${$s1/1000} сек." },
    { en = "Your Wrath and Starfire chance to critically strike is increased by $s1% and they generate ${$s2/10} additional Astral Power.", ua = "Імовірність критичного удару «Гніву» і «Зоряного вогню» збільшена на $s1%, і вони породжують додатково ${$s2/10} од. Астральної сили." },
    { en = "Eruption's Essence cost is reduced by $s1.", ua = "Вартість «Виверження» в есенції зменшено на $s1." },
    { en = "Blistering Scales no longer loses charges and deals $s2% more damage.", ua = "Пекуча луска більше не втрачає зарядів і завдає на $s2% більше шкоди." },
    { en = "The critical strikes of your Holy Power generating abilities grant you $s1% Haste for $407065d.", ua = "Критичні удари твоїх здібностей, що генерують святу силу, дають тобі $s1% поспіху на $407065d." },
    { en = "Obsidian Scales activates Black Attunement, and amplifies it to increase maximum health by $<blacktotal>% for $407254d.\n\n\n\nHover activates Bronze Attunement, and amplifies it to increase movement speed by $<bronzetotal>% for $407244d.", ua = "Обсидіанова луска активує Чорне суголосся та підсилює його, збільшуючи максимальне здоров'я на $<blacktotal>% на $407254d.\n\n\n\nШиряння активує Бронзове суголосся та підсилює його, збільшуючи швидкість пересування на $<bronzetotal>% на $407244d." },
    { en = "Bestial Wrath causes your Barbed Shot to deal damage $s1% faster for $1265063d.", ua = "«Звірячий гнів» змушує твій «Зазублений постріл» завдавати шкоду на $s1% швидше протягом $1265063d." },
    { en = "Increases your Shadow Word: Madness damage by $s2% and increases your maximum Insanity by ${$s1/100}.", ua = "Збільшує шкоду твого «Слова Тіні: Безумство» на $s2%, а максимум божевілля — на ${$s1/100}." },
    { en = "Shadow Apparitions deal $s1% increased damage to targets affected by your Shadow Word: Madness.", ua = "Тіньові привиддя завдають на $s1% більше шкоди цілям під дією твого «Слова тіні: Безумство»." },
    { en = "Reduces the Insanity cost of Shadow Word: Madness by ${$s1/-100}.", ua = "Зменшує вартість «Слова тіні: Безумство» на ${$s1/-100} безумства." },
    { en = "When cast at an enemy, Living Flame strikes $s1 additional enemy for $s2% damage.", ua = "Якщо Живе полум'я створено на ворога, воно вражає $s1 додаткового ворога, завдаючи $s2% шкоди." },
    { en = "$?s403631[Breath of Eons][Deep Breath] grants you Fury of the Aspects for $s1 sec after you land, without causing Exhaustion.", ua = "$?s403631[Подих еонів][Глибокий подих] дарує вам Лють аспектів на $s1 сек. після приземлення, не спричиняючи Виснаження." },
    { en = "Prescience has a $s1% chance to grant Essence Burst.", ua = "«Передбачення» має $s1% шанс дарувати «Вибух есенції»." },
    { en = "Eruption reduces the remaining cooldown of Upheaval by ${$411932s1/-1000}.1 sec.", ua = "«Виверження» зменшує залишок перезарядження «Здіймання» на ${$411932s1/-1000}.1 сек." },
    { en = "Upheaval deals $s1% increased damage to the primary target, and launches them higher.", ua = "Здіймання завдає основній цілі на $s1% більше шкоди та підкидає її вище." },
    { en = "Consuming Essence Burst grants you $s1% Intellect for $408005d. Stacks up to $408005u times.", ua = "Витрата Вибуху есенції дає тобі $s1% інтелекту на $408005d. Складається до $408005u разів." },
    { en = "Your empower spells' maximum level is increased by 1, and they reach maximum empower level $s3% faster.", ua = "Максимальний рівень твоїх підсилюваних заклять збільшено на 1, і вони досягають максимального рівня підсилення на $s3% швидше." },
    { en = "Conjure a pair of Weyrnstones, one for your target ally and one for yourself. Only one ally may bear your Weyrnstone at a time.\n\n\n\nA Weyrnstone can be activated by the bearer to transport them to the other Weyrnstone's location, if they are within 100 yds.", ua = "Викликає пару вейрнкаменів: один для союзника-цілі, інший для вас. Лише один союзник може нести ваш вейрнкамінь водночас.\n\n\n\nНосій може активувати вейрнкамінь, щоб перенестися до розташування іншого вейрнкаменя, якщо той у межах 100 м." },
    { en = "Holy Power spending abilities have a $s1% chance to make your next Holy Power spending ability free and deal $408458s2% increased damage and healing.", ua = "Здібності, що витрачають святу силу, мають $s1% шансу зробити твою наступну таку здібність безкоштовною та збільшити її шкоду й зцілення на $408458s2%." },
    { en = "Essence Burst reduces the cast time of Eruption by $s1% and increases its damage by $s3%.", ua = "«Вибух есенції» зменшує час творення «Виверження» на $s1% і збільшує його шкоду на $s3%." },
    { en = "Increases the damage of Shadow Word: Madness by $s3% and causes it to deal its damage over $s1 sec, but increases its Insanity cost by ${$s5/100}.", ua = "Збільшує шкоду «Слова Тіні: Безумство» на $s3% і розтягує її завдавання на $s1 сек., але підвищує його вартість у божевіллі на ${$s5/100}." },
    { en = "Eruption has a $s1% chance to form a mote of diverted essence near you. Allies who comes in contact with the mote gain a random buff from your arsenal.", ua = "«Виверження» має $s1% шансу утворити поруч із тобою часточку відведеної есенції. Союзники, що торкаються часточки, отримують випадкове підсилення з твого арсеналу." },
    { en = "Grant an ally the gift of foresight, increasing their critical strike chance by $s1% $?s412774[and occasionally copying their damage and healing spells at $412774s1% power ][]for $410089d.\n\n\n\nAffects the nearest ally within $s2 yds, preferring damage dealers with their cooldowns active, if you do not have an ally targeted.", ua = "Даруєш союзникові дар передбачення, підвищуючи його шанс критичного удару на $s1% $?s412774[й інколи копіюючи його закляття шкоди та зцілення з потужністю $412774s1% ][]на $410089d.\n\n\n\nДіє на найближчого союзника в межах $s2 м, віддаючи перевагу бійцям шкоди з активними перезарядженнями, якщо в тебе не позначено союзника." },
    { en = "Each time Blistering Scales explodes it deals $410256s1% more damage for $410256d, stacking $410256u times.", ua = "Щоразу, коли «Пухирчаста луска» вибухає, вона завдає на $410256s1% більше шкоди протягом $410256d. Складається до $410256u разів." },
    { en = "When allies deal damage with Temporal Wounds, they gain a shield for $s1% of the damage dealt. Absorption cannot exceed $s2% of your maximum health.", ua = "Коли союзники завдають шкоди Часовими ранами, вони отримують щит на $s1% від завданої шкоди. Поглинання не може перевищувати $s2% твого максимального здоров'я." },
    { en = "Breath of Eons reduces enemies' movement speed by $439606s1%, and reduces their attack speed by $439606s2%, for $439606d.", ua = "Подих еонів сповільнює рух ворогів на $439606s1% і знижує їхню швидкість атаки на $439606s2% на $439606d." },
    { en = "$?s403631[Breath of Eons][Deep Breath] casts an Eruption at the first $s1 enemies struck. These Eruptions have a $s2% chance to create a Mote of Possibility.", ua = "$?s403631[Подих еонів][Глибокий подих] застосовує Виверження проти перших $s1 уражених ворогів. Ці Виверження мають $s2% шанс створити Частку можливості." },
    { en = "Fire Breath grants the inferno's blessing for $410263d to you and a nearby ally, giving their damaging attacks and spells a high chance to deal an additional $<dmg> Fire damage.", ua = "Вогняний подих дарує благословення інферно на $410263d вам та союзнику поблизу, надаючи їхнім атакам і закляттям зі шкодою високий шанс завдати додатково $<dmg> шкоди вогнем." },
    { en = "While flying during $?s403631[Breath of Eons][Deep Breath], $410355s1% of damage you would take is instead dealt over $410355d.", ua = "Поки ви летите під час $?s403631[Подиху еонів][Глибокого подиху], $410355s1% шкоди, яку ви отримали б, натомість завдається протягом $410355d." },
    { en = "When cast, Blistering Scales grants the target a shield that absorbs up to $<shield> damage for $410651d based on their missing health. Lower health targets gain a larger shield.", ua = "При застосуванні Пекучі луски надають цілі щит, що поглинає до $<shield> шкоди протягом $410651d залежно від її нестачі здоров'я. Цілі з меншим здоров'ям отримують більший щит." },
    { en = "Emerald Blossom increases targets' healing received by $s1% for $410686d.", ua = "«Смарагдовий цвіт» збільшує отримуване цілями зцілення на $s1% протягом $410686d." },
    { en = "Your effects that extend Ebon Might also extend Symbiotic Bloom.", ua = "Твої ефекти, що подовжують «Ебенову міць», також подовжують «Симбіотичний цвіт»." },
    { en = "Azure Strike deals $s2% increased damage and has a $s1% chance per target hit to echo, casting again.", ua = "«Лазуровий удар» завдає на $s2% більше шкоди й з імовірністю $s1% за кожну вражену ціль відлунює, спрацьовуючи ще раз." },
    { en = "Eternity Surge's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Сплеску вічності скорочено на ${$s1/-1000} сек." },
    { en = "Eternity Surge deals $s1% increased damage to your primary target.", ua = "Сплеск вічності завдає твоїй основній цілі на $s1% більше шкоди." },
    { en = "Enchant an ally to appear out of sync with the normal flow of time, reducing threat they generate by $s1% for $d. Less effective on tank-specialized allies. \n\n\n\nMay only be placed on one target at a time.", ua = "Зачаровує союзника, щоб він здавався розсинхронізованим зі звичним плином часу, зменшуючи створювану ним загрозу на $s1% на $d. Менш дієве на союзниках зі спеціалізацією танка.\n\n\n\nМоже бути накладено лише на одну ціль водночас." },
    { en = "The cooldowns of your spells are reduced by $s1%.", ua = "Перезарядження твоїх заклять скорочено на $s1%." },
    { en = "Time Skip channels for ${$s1/1000} sec longer.", ua = "Творення Стрибка в часі триває на ${$s1/1000} сек. довше." },
    { en = "Upheaval cannot be interrupted, and has an additional $s1% chance to critically strike.", ua = "Здіймання неможливо перервати, а його шанс критичного удару додатково збільшено на $s1%." },
    { en = "Prescience grants the ally a chance for their spells and abilities to echo their damage or healing, dealing $s1% of the amount again.", ua = "«Передбачення» дає союзнику шанс, що його закляття та здібності відлунням повторять свою шкоду чи зцілення, завдаючи ще раз $s1% від цієї суми." },
    { en = "Holy Shock now has ${$s1+1} charges and it refunds $s2% of its mana cost when cast on an enemy.", ua = "Кількість зарядів «Святого шоку» тепер становить ${$s1+1}, і він повертає $s2% вартості мани, якщо створений на ворога." },
    { en = "Judgment has a $s1% chance to cast Consecration at the target's location.\n\n\n\nThe limit on Consecration does not apply to this effect.", ua = "«Осуд» має $s1% шанс сотворити «Освячення» в місці перебування цілі.\n\n\n\nОбмеження на «Освячення» не поширюється на цей ефект." },
    { en = "Find resilience in the flow of chi in battle, gaining a magic absorb shield for ${$s1/10}.1% of your max health every $t sec in combat, stacking up to $s2%.", ua = "Знаходь стійкість у плині ці в бою: кожні $t сек. бою ти отримуєш щит, що поглинає магічну шкоду, в розмірі ${$s1/10}.1% твого максимального здоров'я. Накопичується до $s2%." },
    { en = "Your dodge chance is increased by $s1%.", ua = "Твій шанс ухилення збільшено на $s1%." },
    { en = "While in combat, your Holy Power spenders have a $s1% chance to cause your next Judgment to deal $414193s1% increased damage and critically strike.\n\n\n\nActivating Avenging Wrath activates Awakening.", ua = "У бою ваші вміння, що витрачають Святу силу, мають $s1% шанс зробити так, щоб ваш наступний «Осуд» завдав на $414193s1% більше шкоди й завдав критичного удару.\n\n\n\nАктивація «Караючого гніву» активує «Пробудження»." },
    { en = "Arcane Missiles channels $s1% faster.", ua = "«Арканні снаряди» спрямовуються на $s1% швидше." },
    { en = "$?s2812[Denounce][Shield of the Righteous] deals $414448s1 damage to its first target struck.\n\n\n\n$?s2812[Denounce][Shield of the Righteous] now has a $s1% chance to activate Divine Purpose if talented.", ua = "$?s2812[Викриття][Щит праведника] завдає $414448s1 шкоди першій ураженій цілі.\n\n\n\n$?s2812[Викриття][Щит праведника] тепер має $s1% шанс активувати Божественне призначення, якщо обрано талант." },
    { en = "Your Holy Words have a $s1% chance to cause your next cast of Prayer of Mending to ignore its cooldown.", ua = "Твої Святі слова з імовірністю $s1% дозволяють наступній Молитві відновлення знехтувати своїм перезарядженням." },
    { en = "Ice Block now reduces all damage taken by $414658s8% for $414658d but no longer grants Immunity, prevents movement, attacks, or casting spells. Does not incur the Global Cooldown.", ua = "«Крижана брила» тепер зменшує всю отримувану шкоду на $414658s8% на $414658d, але більше не дає невразливості й не забороняє рухатися, атакувати чи творити закляття. Не запускає загальне перезарядження." },
    { en = "You and your allies within $A1 yards instantly become invisible for $d. Taking any action will cancel the effect.\n\n\n\n$?a415945[]\n\n\n\n[Does not affect allies in combat.]", ua = "Ви та ваші союзники в радіусі $A1 ярдів миттєво стаєте невидимими протягом $d. Будь-яка дія скасовує ефект.\n\n\n\n$?a415945[]\n\n\n\n[Не діє на союзників у бою.]" },
    { en = "Lay on Hands' cooldown is reduced by $s1% and restores $415299s1% of your Mana.", ua = "Перезарядження «Покладання рук» скорочено на $s1%, а саме закляття відновлює $415299s1% твоєї мани." },
    { en = "Emerald Blossom no longer has a cooldown, deals $s4% increased healing, and increases the duration of your active Ebon Might effects by $s2 sec, but costs $s1 Essence.", ua = "«Смарагдовий цвіт» більше не має перезарядження, дає на $s4% більше зцілення та подовжує тривалість твоїх активних ефектів «Чорної моці» на $s2 сек., але коштує $s1 есенції." },
    { en = "Holy Shock refunds up to $s1% of its Mana cost and deals up to $s2% more healing or damage, based on the target's missing health.", ua = "«Святий шок» повертає до $s1% вартості мани та дає до $s2% більше зцілення чи шкоди залежно від втраченого здоров'я цілі." },
    { en = "Increases the healing of your spells by $s1%.", ua = "Збільшує зцілення твоїх заклять на $s1%." },
    { en = "Flamestrike has a chance equal to $s1% of your spell critical strike chance to build up to a Hot Streak.\n\n\n\nFlamestrike deals $s2% increased damage for each enemy it damages, up to ${$s2*$s3}%.", ua = "Полум'яний удар з імовірністю, що дорівнює $s1% вашого шансу критичного удару заклять, наближає вас до Жаркої смуги.\n\n\n\nПолум'яний удар завдає на $s2% більше шкоди за кожного враженого ним ворога, аж до ${$s2*$s3}%." },
    { en = "Increases the critical strike chance of your Wild Imp's Fel Firebolt by $s1%.", ua = "Збільшує шанс критичного удару Вогняної стріли Скверни твого дикого імпа на $s1%." },
    { en = "Reduces the cast time of Unstable Affliction by ${$abs($s1)/1000}.2 sec and increases its damage by $s2%.", ua = "Зменшує час творення «Нестабільної напасті» на ${$abs($s1)/1000}.2 сек. і збільшує її шкоду на $s2%." },
    { en = "While Ignite is on $s1 or fewer enemies it flares up dealing an additional $s2% of its damage to affected targets.", ua = "Поки «Займання» діє на $s1 або менше ворогів, воно спалахує, завдаючи ураженим цілям додатково $s2% своєї шкоди." },
    { en = "Meteor's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Метеора скорочується на ${$s1/-1000} сек." },
    { en = "Summon Infernal increases the damage of your next $s3 casts of Chaos Bolt by $s1% or your next $s3 casts of Rain of Fire by $s2%.", ua = "«Виклик інфернала» збільшує шкоду твоїх наступних $s3 прочитань «Стріли хаосу» на $s1% або наступних $s3 прочитань «Дощу вогню» на $s2%." },
    { en = "Hot Streak increases the amount of Ignite damage from Pyroblast or Flamestrike by an additional $s1%.", ua = "«Гаряча серія» додатково збільшує шкоду «Займання» від «Піровибуху» чи «Удару полум'я» на $s1%." },
    { en = "Your Haste is increased by $s1%.\n\n\n\nYou gain $s2% more Haste from all sources of Haste.", ua = "Ваш поспіх збільшено на $s1%.\n\n\n\nВи отримуєте на $s2% більше поспіху з усіх джерел поспіху." },
    { en = "Holy Shock, Holy Light, and Flash of Light critical healing increased by $s1%.", ua = "Критичне зцілення «Святого шоку», «Святого Світла» та «Спалаху Світла» збільшено на $s1%." },
    { en = "Source of Magic increases the target's healing and damage done by $s1%.", ua = "«Джерело магії» збільшує зцілення та шкоду, які завдає ціль, на $s1%." },
    { en = "Your main hand auto attacks reduce the cooldown on your Brews by ${$s2/1000}.2 sec and block your target's chi, dealing $418360s1 additional Nature damage.\n\n\n\nAfter $418361u attacks, the next casts Tiger Palm at $418361s2% effectiveness.", ua = "Автоатаки вашою основною рукою зменшують перезарядження ваших напоїв на ${$s2/1000}.2 с і блокують ці вашої цілі, завдаючи додатково $418360s1 шкоди від сил природи.\n\n\n\nПісля $418361u атак наступна викликає «Долоню тигра» з $418361s2% ефективністю." },
    { en = "Ray of Frost deals $s1% of its damage to $s2 nearby enemies.", ua = "Промінь морозу завдає $s1% своєї шкоди $s2 ворогам поблизу." },
    { en = "Reduces the cooldown of Divine Hymn by ${$s1/-1000} sec.", ua = "Скорочує перезарядження «Божественного гімну» на ${$s1/-1000} сек." },
    { en = "When you spend extra Energy on Ferocious Bite, the extra damage is increased by $s1%.", ua = "Коли ти витрачаєш додаткову енергію на «Лютий укус», додаткова шкода збільшується на $s1%." },
    { en = "Ascend into the air and unleash a massive barrage of Penance bolts, causing $<penancedamage> Holy damage to enemies or $<penancehealing> healing to allies over $421434d.\n\n\n\nWhile ascended, gain a shield for $s1% of your health. In addition, you are unaffected by knockbacks or crowd control effects.", ua = "Здіймається в повітря й вивільняє потужний шквал стріл «Покути», завдаючи $<penancedamage> од. шкоди Світлом ворогам або даруючи $<penancehealing> зцілення союзникам протягом $421434d.\n\n\n\nПеребуваючи в повітрі, отримуєте щит розміром $s1% вашого здоров'я. Крім того, на вас не діють відкидання та ефекти контролю." },
    { en = "Envenom or Kingsbane apply Caustic Spatter for $421976d. Limit 1.\n\n\n\nCaustic Spatter causes $421976s1% of your Nature damage dealt to splash onto other nearby enemies, reduced beyond $421976s2 targets.", ua = "«Отруєння» чи «Згуба королів» накладають «Їдкі бризки» протягом $421976d. Ліміт 1.\n\n\n\n«Їдкі бризки» змушують $421976s1% завданої вами шкоди Природи розбризкуватися на інших ворогів поблизу, зі зменшенням понад $421976s2 цілей." },
    { en = "Mana Tea now channels $s1% faster and generates $s2% more Mana.", ua = "Тепер «Чай з мани» вивільняється на $s1% швидше й дає на $s2% більше мани." },
    { en = "Increases maximum Energy by $s1.", ua = "Збільшує максимум енергії на $s1." },
    { en = "Bleed damage increased by $s1%.\n\n\n\nTargets below $s3% health instantly bleed out and take fatal damage when the remaining Bleed damage you would deal to them exceeds $s2% of their remaining health.", ua = "Шкоду від кровотечі збільшено на $s1%.\n\n\n\nЦілі зі здоров'ям нижче $s3% миттєво стікають кров'ю й зазнають смертельної шкоди, коли решта шкоди від кровотечі, яку ви б їм завдали, перевищує $s2% їхнього залишкового здоров'я." },
    { en = "Feint has $m1 additional $Lcharge:charges;.", ua = "Фінт має $m1 додаткового $Lзаряду:зарядів;." },
    { en = "Shroud of Concealment has $s1% reduced cooldown.", ua = "Перезарядження «Покрову приховування» зменшено на $s1%." },
    { en = "Sprint increases movement speed by an additional $s1% and has ${$s2/1000} sec increased duration.", ua = "Спринт додатково збільшує швидкість руху на $s1%, а його тривалість більша на ${$s2/1000} сек." },
    { en = "Crippling Poison reduces movement speed by an additional $s1%.", ua = "«Калічна отрута» додатково зменшує швидкість руху на $s1%." },
    { en = "$?a137010[$@spellicon204066 $@spellname204066\n\nLunar Beam now causes you to leech life equal to $425217s1% of all damage dealt to enemies within the beam.\n\n\n\n$@spellicon202770 $@spellname202770\n\nFury of Elune now ends with a flash of energy, blasting nearby enemies for $428682s1 Astral damage.]\n\n\n\n[$@spellicon202770 $@spellname202770\n\nFury of Elune now ends with a flash of energy, blasting nearby enemies for $428682s1 Astral damage.\n\n\n\n$@spellicon274283 $@spellname274283\n\n$@spelldesc424588]", ua = "$?a137010[$@spellicon204066 $@spellname204066\n\nМісячний промінь тепер дає вам висмоктувати життя в розмірі $425217s1% усієї шкоди, завданої ворогам у промені.\n\n\n\n$@spellicon202770 $@spellname202770\n\nЛють Елуни тепер завершується спалахом енергії, що б'є ближніх ворогів на $428682s1 астральної шкоди.]\n\n\n\n[$@spellicon202770 $@spellname202770\n\nЛють Елуни тепер завершується спалахом енергії, що б'є ближніх ворогів на $428682s1 астральної шкоди.\n\n\n\n$@spellicon274283 $@spellname274283\n\n$@spelldesc424588]" },
    { en = "Further increases the power of Boundless Moonlight.\n\n\n\n$?a137010[$@spellicon204066 $@spellname204066\n\nLunar Beam increases Mastery by an additional ${$s5*$mas}%, deals $s6% increased damage, and lasts ${$s3/1000} sec longer.\n\n\n\n$@spellicon202770 $@spellname202770\n\nThe flash of energy now generates  ${$428682s3/10} Rage and its damage is increased by $s1%.][$@spellicon202770 $@spellname202770\n\nThe flash of energy now generates ${$428682s2/10} Astral Power and its damage is increased by $s1%.\n\n\n\n$@spellicon274283 $@spellname274283\n\nNew Moon and Half Moon now also call down $s2 Minor $LMoon:Moons;.]", ua = "Ще більше посилює міць Безмежного місячного сяйва.\n\n\n\n$?a137010[$@spellicon204066 $@spellname204066\n\nМісячний промінь збільшує Майстерність ще на ${$s5*$mas}%, завдає на $s6% більше шкоди й триває на ${$s3/1000} с довше.\n\n\n\n$@spellicon202770 $@spellname202770\n\nСпалах енергії тепер генерує ${$428682s3/10} люті, а його шкоду збільшено на $s1%.][$@spellicon202770 $@spellname202770\n\nСпалах енергії тепер генерує ${$428682s2/10} астральної сили, а його шкоду збільшено на $s1%.\n\n\n\n$@spellicon274283 $@spellname274283\n\nМолодий місяць і Півмісяць тепер також закликають $s2 малих $LМісяць:Місяці;.]" },
    { en = "Kill Command damage is increased by $s1%. Barbed Shot lasts ${$m2/1000}.1 sec longer.", ua = "Шкода «Наказу вбити» збільшена на $s1%. «Шипастий постріл» триває на ${$m2/1000}.1 сек. довше." },
    { en = "Each time Barbed Shot deals damage, the cooldown of Kill Command is reduced by ${$m1/1000}.2 sec.", ua = "Щоразу, коли «Шипастий постріл» завдає шкоди, перезарядження «Наказу убити» скорочується на ${$m1/1000}.2 сек." },
    { en = "Your Shout abilities have additional effects.\n\n\n\n$@spellicon6673 $@spellname6673:\n\nGrants you an additional $s6% attack power.\n\n\n\n$@spellicon97462 $@spellname97462:\n\nGrants an additional $s4% health and duration increased by ${$s5/1000} sec.\n\n\n\n$@spellicon12323 $@spellname12323:\n\nRadius increased by $s3%\n\n\n\n$@spellicon384100 $@spellname384100:\n\nRadius increased by $s1%.\n\n\n\n$@spellicon5246 $@spellname5246:\n\nCooldown reduced by ${$s2/-1000} sec.", ua = "Ваші здібності-крики мають додаткові ефекти.\n\n\n\n$@spellicon6673 $@spellname6673:\n\nНадає вам додатково $s6% сили атаки.\n\n\n\n$@spellicon97462 $@spellname97462:\n\nНадає додатково $s4% здоров'я, а тривалість збільшено на ${$s5/1000} с.\n\n\n\n$@spellicon12323 $@spellname12323:\n\nРадіус збільшено на $s3%\n\n\n\n$@spellicon384100 $@spellname384100:\n\nРадіус збільшено на $s1%.\n\n\n\n$@spellicon5246 $@spellname5246:\n\nПерезарядження зменшено на ${$s2/-1000} с." },
    { en = "You gain a stack of Light's Deliverance when you call down an Empyrean Hammer.\n\n\n\nWhile $?a137028[Divine Toll][Wake of Ashes] and Hammer of Light are unavailable, you consume $433674U stacks of Light's Deliverance, empowering yourself to cast Hammer of Light an additional time for free.", ua = "Ви отримуєте заряд Спасіння Світла, коли закликаєте Емпірейський молот.\n\n\n\nПоки $?a137028[Божественний подзвін][Слід попелу] і Молот Світла недоступні, ви споживаєте $433674U зарядів Спасіння Світла, дістаючи змогу безкоштовно застосувати Молот Світла ще раз." },
    { en = "Grants access to the following abilities:\n\n\n\n$@spellicon264178 $@spellname264178\n\n$@spelldesc264178\n\n\n\n$@spellicon267102 $@spellname267102\n\n$@spelldesc267102", ua = "Надає доступ до таких здібностей:\n\n\n\n$@spellicon264178 $@spellname264178\n\n$@spelldesc264178\n\n\n\n$@spellicon267102 $@spellname267102\n\n$@spelldesc267102" },
    { en = "Shadow Dance increases attack speed by $185313s8%.", ua = "«Танець тіней» збільшує швидкість атаки на $185313s8%." },
    { en = "Increases healing received by $s1%.", ua = "Збільшує отримуване зцілення на $s1%." },
    { en = "Lashes out at the target, inflicting $426592s1 Shadow damage and causing your next $426593u finishing moves to cost no Energy.\n\n\n\n|cFFFFFFFFAwards $426593s1 combo $lpoint:points;.|r", ua = "Завдає удару по цілі, наносячи $426592s1 шкоди як Тінь, через що твої наступні $426593u завершальних прийомів не коштуватимуть Енергії.\n\n\n\n|cFFFFFFFFНадає $426593s1 $lочко комбо:очок комбо;.|r" },
    { en = "While Shadow Dance is active, your Shadow Techniques triggers $s3% more frequently, stores $m2 additional combo $Lpoint:points;, and generates $s1 additional Energy.", ua = "Поки активний Танець тіней, ваші Тіньові техніки спрацьовують на $s3% частіше, зберігають $m2 додаткових комбо-$Lочко:очок; і генерують $s1 додаткової Енергії." },
    { en = "Your damage over time effects deal their damage $s1% faster, and your healing over time effects heal $s2% faster.", ua = "Твої ефекти періодичної шкоди завдають шкоди на $s1% швидше, а ефекти періодичного зцілення зцілюють на $s2% швидше." },
    { en = "When you cast Starsurge, Rake, Shred, or Frenzied Regeneration you gain Call of the Elder Druid for $s2 sec, once every $338643d.\n\n\n\n$@spellicon319454 $@spellname319454\n\n$@spelldesc319454", ua = "Коли ви застосовуєте Зоряний сплеск, Дряпання, Шматування чи Несамовите відновлення, ви отримуєте Поклик старійшини друїдів на $s2 сек., раз на $338643d.\n\n\n\n$@spellicon319454 $@spellname319454\n\n$@spelldesc319454" },
    { en = "$?a137028[Divine Toll][Wake of Ashes] is replaced with $@spellname427453 for $427441d after it is cast.\n\n\n\n$@spellicon427453 $@spellname427453:\n\n$@spelldesc427453\n\n|cFFFFFFFFCosts 5 Holy Power.", ua = "$?a137028[Божественний подзвін][Слід попелу] замінюється на $@spellname427453 на $427441d після прочитання.\n\n\n\n$@spellicon427453 $@spellname427453:\n\n$@spelldesc427453\n\n|cFFFFFFFFКоштує 5 Святої Сили." },
    { en = "The Hunt and Vengeful Retreat cause your next Fel Rush or Felblade to empower you, increasing damage by $427641s1% for $427641d.", ua = "«Полювання» та «Мстивий відступ» наділяють силою твій наступний «Ривок Скверни» чи «Клинок Скверни»: він наснажує тебе, збільшуючи шкоду на $427641s1% на $427641d." },
    { en = "Immolation Aura has $m1 additional $Lcharge:charges;, has ${$s3/-1000} sec reduced cooldown, and deals Chaos damage instead of Fire.\n\n\n\nYou can have multiple Immolation Auras active at a time.", ua = "Аура спалення має $m1 додатковий $Lзаряд:заряди;, має зменшене на ${$s3/-1000} с перезарядження та завдає хаотичної шкоди замість вогняної.\n\n\n\nВи можете мати декілька активних Аур спалення одночасно." },
    { en = "You deflect incoming attacks while Blade Dancing, absorbing damage up to $s1% of your maximum health.", ua = "Під час «Танцю клинків» ти відбиваєш атаки, поглинаючи шкоду в обсязі до $s1% свого максимального здоров'я." },
    { en = "For ${$427793D-($428160s1/10)} sec after using Fel Rush, activating it again will dash back towards your initial location.", ua = "Протягом ${$427793D-($428160s1/10)} сек. після використання «Ривка Скверни» його повторна активація ривком поверне тебе на початкове місце." },
    { en = "Increases Versatility by $s1% and reduces threat generated by ${$s2*-1}%.", ua = "Збільшує універсальність на $s1% і зменшує створювану загрозу на ${$s2*-1}%." },
    { en = "Magical damage increased by $s1%, and Physical damage taken reduced by $s2%.", ua = "Магічна шкода збільшена на $s1%, а отримана фізична шкода зменшена на $s2%." },
    { en = "Between the Eyes and Pistol Shot have $s1 yd increased range and deal $s2% increased damage.", ua = "Дальність «Межи очі» та «Пострілу з пістоля» збільшена на $s1 м, а їхня шкода — на $s2%." },
    { en = "Shuriken Storm increases your movement speed by $428389s1% for $428389d when striking $s1 or more enemies.", ua = "Буря сюрикенів збільшує твою швидкість руху на $428389s1% на $428389d, якщо влучає у $s1 або більше ворогів." },
    { en = "Increases Demonbolt damage by $s1% and consuming a Demonic Core has a chance to summon a Wild Imp.", ua = "Збільшує шкоду Демонічної стріли на $s1%, а споживання Демонічного ядра має шанс прикликати дикого імпа." },
    { en = "Your finishing moves heal you for $s1% of damage done. At full health gain shielding instead, absorbing up to $s2% of your maximum health.", ua = "Завершальні прийоми зцілюють тебе на $s1% завданої шкоди. За повного здоров'я натомість отримуєш щит, що поглинає до $s2% твого максимального здоров'я." },
    { en = "Your Chaos damage has a ${$s2/100}.2% chance to be increased by $s3%, occurring up to $m1 total $Ltime:times;.", ua = "Ваша шкода від хаосу має ${$s2/100}.2% шанс зрости на $s3%, спрацьовуючи загалом до $m1 $Lразу:разів;." },
    { en = "$?s137044[Spending a Soul Shard on a damaging spell grants Diabolic Ritual for $431944d. While Diabolic Ritual is active, each Soul Shard spent on a damaging spell reduces its duration by $s1 sec.][Casting Chaos Bolt, Rain of Fire, or Shadowburn grants Diabolic Ritual for $431944d. If Diabolic Ritual is already active, its duration is reduced by $s2 sec instead.]\n\n\n\nWhen Diabolic Ritual expires you gain Demonic Art, causing your next $?s137044[Hand of Gul'dan][Chaos Bolt, Rain of Fire, or Shadowburn] to summon an Overlord, Mother of Chaos, or Pit Lord that unleashes a devastating attack against your enemies.", ua = "$?s137044[Витрата уламка душі на закляття зі шкодою дарує Диявольський ритуал на $431944d. Поки Диявольський ритуал активний, кожен уламок душі, витрачений на закляття зі шкодою, зменшує його тривалість на $s1 сек.][Творення Снаряда хаосу, Вогняного дощу чи Тіньового спалаху дарує Диявольський ритуал на $431944d. Якщо Диявольський ритуал уже активний, його тривалість натомість зменшується на $s2 сек.]\n\n\n\nКоли Диявольський ритуал завершується, ви отримуєте Демонічне мистецтво, через що ваш(е) наступний(є) $?s137044[Рука Ґул'дана][Снаряд хаосу, Вогняний дощ чи Тіньовий спалах] прикликає Володаря, Матір хаосу або Лорда Ями, що здійснює нищівну атаку проти ваших ворогів." },
    { en = "Enemies damaged by your Overlord have their souls cloven, increasing damage taken by you and your pets by $434424s1% for $434424d.", ua = "Душі ворогів, яким завдає шкоди твій володар, розколюються, через що вони протягом $434424d отримують на $434424s1% більше шкоди від тебе і твоїх улюбленців." },
    { en = "Mother of Chaos empowers your next $?s137044[Shadow Bolt][Incinerate] to become Infernal Bolt.\n\n\n\n$@spellicon434506 $@spellname434506\n\n$@spelldesc434506", ua = "Мати Хаосу підсилює ваш наступний $?s137044[Тіньова стріла][Спопеляння], перетворюючи його на Пекельну стрілу.\n\n\n\n$@spellicon434506 $@spellname434506\n\n$@spelldesc434506" },
    { en = "Summoning a Pit Lord causes your next $?s137044[Hand of Gul'dan][Chaos Bolt] to become Ruination.\n\n\n\n$@spellicon434635 $@spellname434635\n\n$@spelldesc434635", ua = "Виклик володаря ями перетворює ваш наступний $?s137044[Рука Ґул'дана][Стріла хаосу] на Спустошення.\n\n\n\n$@spellicon434635 $@spellname434635\n\n$@spelldesc434635" },
    { en = "Your $?a137013[Force of Nature treants][Grove Guardians] cast Moonfire on nearby targets about once every $s1 sec.", ua = "Твої $?a137013[тренти «Сили природи»][«Стражі гаю»] творять «Місячний вогонь» на цілі поблизу приблизно раз на $s1 с." },
    { en = "Sigil of Flame damage increased by $s2%.", ua = "Шкода «Знака полум'я» збільшена на $s2%." },
    { en = "When you parry an attack or have one of your attacks parried, restore $428608s2% of max health and $428608s1 Fury. \n\n\n\nThis effect may only occur once every $s1 sec.", ua = "Коли ви парируєте атаку або одну з ваших атак парирують, відновлюється $428608s2% максимального здоров'я та $428608s1 Люті. \n\n\n\nЦей ефект може спрацьовувати лише раз на $s1 сек." },
    { en = "Moonfire damage has a chance to call down a Fury of Elune to follow your target for ${$s2/1000} sec.\n\n\n\n$@spellicon202770 $@spellname202770\n\nCalls down a beam of pure celestial energy, dealing $<dmg> Astral damage over ${$s2/1000} sec within its area.\n\n\n\n|cFFFFFFFFGenerates $?a137010[${$202770m4/$202770t4*$s2/10000} Rage][${$202770m3/$202770t3*$s2/10000} Astral Power] over its duration.|r", ua = "Шкода Місячного вогню має шанс закликати Лють Елуни, що переслідуватиме вашу ціль упродовж ${$s2/1000} с.\n\n\n\n$@spellicon202770 $@spellname202770\n\nЗакликає промінь чистої небесної енергії, що завдає $<dmg> астральної шкоди впродовж ${$s2/1000} с у своїй ділянці.\n\n\n\n|cFFFFFFFFГенерує $?a137010[${$202770m4/$202770t4*$s2/10000} люті][${$202770m3/$202770t3*$s2/10000} астральної сили] упродовж своєї дії.|r" },
    { en = "$?a137013[Each of your Force of Nature treants increases damage your spells deal by $428735s1% while active.][Each of your Grove Guardians increases your healing done by $428737s1% while active.]", ua = "$?a137013[Кожен твій трент із Сили природи, поки активний, збільшує шкоду твоїх заклять на $428735s1%.][Кожен твій Вартовий гаю, поки активний, збільшує твоє зцілення на $428737s1%.]" },
    { en = "$?a137013[Your Force of Nature treants no longer taunt and deal $449001s1% increased melee damage.][Your Grove Guardians increase the healing of your Rejuvenation, Efflorescence, and Lifebloom by $428866s1% while active.]", ua = "$?a137013[Твої тренти Сили природи більше не провокують ворогів і завдають на $449001s1% більше шкоди в ближньому бою.][Твої Вартові гаю, поки активні, збільшують зцілення твоїх Омолодження, Розквіту та Цвіту життя на $428866s1%.]" },
    { en = "You always gain the benefit of Soulburn when casting Demonic Circle: Teleport, increasing your movement speed by 50% and making you immune to snares and roots for 6 sec.", ua = "Ти завжди отримуєш ефект «Спалення душі», коли твориш «Демонічне коло: телепортація», що збільшує твою швидкість руху на 50% і дає імунітет до сповільнень та знерухомлень на 6 сек." },
    { en = "$?a137013[Force of Nature cooldown reduced by ${$s1/-1000} sec.][Swiftmend and Wild Growth cooldowns reduced by ${$s2/-1000} sec.]", ua = "$?a137013[Перезарядження Сили природи скорочено на ${$s1/-1000} сек.][Перезарядження Швидкого зцілення та Дикого росту скорочено на ${$s2/-1000} сек.]" },
    { en = "Howl of Terror cooldown is reduced by ${$s1/-1000} sec and range is increased by $s2 yds.", ua = "Перезарядження «Виття жаху» скорочене на ${$s1/-1000} сек., а дальність збільшена на $s2 м." },
    { en = "Unending Resolve heals you for ${$434559s1*($434559d/$434559t1)}% of your maximum health over $434559d.", ua = "«Незламна рішучість» зцілює тебе на ${$434559s1*($434559d/$434559t1)}% максимального здоров'я протягом $434559d." },
    { en = "Unending Resolve grants Soul Leech equal to $434561s1% of your maximum health and increases the maximum amount Soul Leech can absorb by $434561s1% for $434561d.", ua = "«Незламна рішучість» дає «Висмоктування душі» в розмірі $434561s1% твого максимального здоров'я і збільшує максимум поглинання «Висмоктування душі» на $434561s1% на $434561d." },
    { en = "Throw Glaive has ${$s2+1} charges and $s1 yard increased range.", ua = "«Кидок глефи» має ${$s2+1} заряди, а його дальність збільшена на $s1 м." },
    { en = "$?a137013[Force of Nature summons 4 Treants.][Your Grove Guardians' healing is increased by $s1%.]", ua = "$?a137013[Сила природи призиває 4 трентів.][Зцілення твоїх Вартових гаю збільшено на $s1%.]" },
    { en = "$?c1[Your Force of Nature treants have $s1% increased health.][Grove Guardians last $s2% longer.]", ua = "$?c1[Твої тренти «Сили природи» мають на $s1% більше здоров'я.][«Вартові гаю» тривають на $s2% довше.]" },
    { en = "Your maximum mana is increased by $s2%$?a137013[ and your maximum Astral Power is increased by ${$s1/10}][].", ua = "Твоя максимальна мана збільшена на $s2%$?a137013[, а твоя максимальна астральна сила збільшена на ${$s1/10}][]." },
    { en = "Wrath and Starfire damage increased by $s1%. \n\n\n\nRegrowth$?a137013[ and Wild Growth][, Wild Growth, and Swiftmend] healing increased by $s2%.", ua = "Шкода від Гніву та Зоряного вогню підвищена на $s1%. \n\n\n\nЗцілення від Відростання$?a137013[ та Бурхливого росту][, Бурхливого росту та Швидкого зцілення] підвищене на $s2%." },
    { en = "$?c1[Orbital Strike damage increased by $s3%, and damage of Stellar Flares it applies increased by $s2%.\n\n\n\nWhirling Stars increases the haste you gain during ][]$?c1&s394013[Incarnation: Chosen of Elune]?c1[Celestial Alignment][]$?c1[ by an additional $s4%.][Reforestation grants Tree of Life for $s5 additional sec.]", ua = "$?c1[Шкода Орбітального удару збільшена на $s3%, а шкода Зоряних спалахів, які він накладає, збільшена на $s2%.\n\n\n\nКружляючі зорі збільшують поспіх, який ви отримуєте під час ][]$?c1&s394013[Втілення: обранця Елуни]?c1[Небесного вирівнювання][]$?c1[, додатково на $s4%.][Лісовідновлення дає Дерево життя на $s5 додаткових с.]" },
    { en = "Every $s1 Regrowths you cast makes your next Wrath, Starfire, or Entangling Roots instant and increases damage it deals by $429474s2%.\n\n\n\nEvery $s1 Starsurges $?a137013[or Starfalls ][]you cast makes your next Regrowth or Entangling roots instant.", ua = "Кожні $s1 застосувань Відростання роблять ваш наступний Гнів, Зоряний вогонь чи Чіпке коріння миттєвими й збільшують їхню шкоду на $429474s2%.\n\n\n\nКожні $s1 застосувань Зоряного потоку $?a137013[чи Зорепаду ][]роблять ваше наступне Відростання чи Чіпке коріння миттєвими." },
    { en = "Hover now causes you to briefly warp out of existence and appear at your destination. Hover's cooldown is also reduced by ${$s1/-1000} sec.\n\n\n\nHover continues to allow Evoker spells to be cast while moving.", ua = "Ширяння тепер змушує вас на мить зникнути з буття та з'явитися в місці призначення. Час перезарядження Ширяння також зменшено на ${$s1/-1000} сек.\n\n\n\nШиряння й надалі дозволяє творити закляття Пробуджувача на ходу." },
    { en = "$?a137013[Moonfire and Starfire generate ${$s1/10} additional Astral Power.][Free automatic Moonfires from Galactic Guardian generate ${$430581s1/10} Rage.]", ua = "$?a137013[Місячний вогонь і Зоряний вогонь генерують ${$s1/10} додаткової астральної сили.][Безкоштовні автоматичні Місячні вогні від Галактичного вартового генерують ${$430581s1/10} люті.]" },
    { en = "$?a137013[Starfire deals $s1% increased damage to its primary target.\n\n\n\nWrath no longer changes your Eclipse ability's mode to Solar Eclipse.][Thrash now deals Arcane damage and its damage is increased by $s2%.]", ua = "$?a137013[Зоряний вогонь завдає на $s1% більше шкоди основній цілі.\n\n\n\nГнів більше не перемикає вашу здібність Затемнення в режим Сонячного затемнення.][Молотіння тепер завдає арканної шкоди, і його шкода збільшена на $s2%.]" },
    { en = "Moonfire deals $s1% increased damage.$?a137010[\n\n\n\nRed Moon deals $s3% increased damage.][]", ua = "Місячний вогонь завдає на $s1% більше шкоди.$?a137010[\n\n\n\nЧервоний місяць завдає на $s3% більше шкоди.][]" },
    { en = "Enemies damaged by $?a137013[Full Moon or Fury of Elune][Lunar Beam or Fury of Elune] take $430589s1% increased damage from you for $430589d.", ua = "Вороги, що зазнали шкоди від $?a137013[«Повного місяця» чи «Люті Елуни»][«Місячного променя» чи «Люті Елуни»], впродовж $430589d отримують від тебе на $430589s1% більше шкоди." },
    { en = "Bear Form and Moonkin Form reduce Arcane damage taken by $s2% and all other magic damage taken by $s1%.", ua = "«Форма ведмедя» та «Форма місяцесича» зменшують отримувану арканну шкоду на $s2%, а всю іншу магічну шкоду — на $s1%." },
    { en = "$?a137013[Incarnation: Chosen of Elune][Incarnation: Guardian of Ursoc] increases Arcane damage from spells and abilities by $102560s6% while active.\n\n\n\nIncreases the duration and number of spells cast by Convoke the Spirits by $s1%.", ua = "$?a137013[Втілення: обранець Елуни][Втілення: вартовий Урсока] збільшує арканну шкоду від заклять і вмінь на $102560s6%, доки активне.\n\n\n\nЗбільшує тривалість і кількість заклять, застосованих Скликанням духів, на $s1%." },
    { en = "Enemies affected by Moonfire are slowed by $164812s8%.", ua = "Вороги під дією «Місячного вогню» сповільнені на $164812s8%." },
    { en = "$?a137013[Your Arcane abilities reduce the cooldown of Fury of Elune by ${$s1/-1000}.1 sec and the cooldown of New Moon, Half Moon, and Full Moon by ${$s2/-1000}.1 sec.][Your Arcane abilities reduce the cooldown of Lunar Beam by ${$s3/-1000}.1 sec.]", ua = "$?a137013[Твої арканні здібності скорочують перезарядження Люті Елуни на ${$s1/-1000}.1 сек, а перезарядження Нового місяця, Півмісяця та Повного місяця — на ${$s2/-1000}.1 сек.][Твої арканні здібності скорочують перезарядження Місячного променя на ${$s3/-1000}.1 сек.]" },
    { en = "All Arcane damage from your spells and abilities is increased by $s1%.", ua = "Уся арканна шкода від твоїх заклять і здібностей збільшена на $s1%." },
    { en = "$?s137044[Summon Demonic Tyrant is empowered, dealing $s1% increased damage and increasing the damage of your demons by $s2% while active.][Summon Infernal becomes empowered, dealing $s3% increased damage. When your Summon Infernal ends, it fragments into two smaller Infernals at $s4% effectiveness that lasts $456310d.]", ua = "$?s137044[Виклик Демонічного тирана посилено: він завдає на $s1% більше шкоди й збільшує шкоду ваших демонів на $s2%, поки активний.][Виклик Інфернала посилено: він завдає на $s3% більше шкоди. Коли ваш Виклик Інфернала завершується, він розпадається на двох менших Інфералів з $s4% ефективністю, що тривають $456310d.]" },
    { en = "Colossal Might increases damage dealt by your next Demolish by $440989s1%, stacking up to $440989u times.\n\n\n\n$?c1[Mortal Strike][Shield Slam] grants a stack of Colossal Might and $?c1[Cleave][Revenge] grants a stack of Colossal Might when it strikes $s1 or more targets.", ua = "Колосальна міць збільшує шкоду від вашого наступного Знесення на $440989s1%, накопичуючись до $440989u разів.\n\n\n\n$?c1[Смертельний удар][Удар щитом] надає заряд Колосальної міці, а $?c1[Розсічення][Помста] надає заряд Колосальної міці, коли вражає $s1 або більше цілей." },
    { en = "Colossal Might stacks up to 10 times. If you would gain a stack of Colossal Might and are at max stacks, the cooldown of Demolish is reduced by $s2 sec.\n\n\n\nEnemies affected by Demolish take up to ${$447513s2*$447513u*0.1}% more damage from you and deal up to ${$447513s1*$447513u*-0.1}% less damage to you for $447513d based on the number of stacks of Colossal Might consumed by Demolish.", ua = "Колосальна міць накопичується до 10 разів. Якщо ти мав би отримати заряд Колосальної міці, перебуваючи на максимумі зарядів, перезарядження Руйнування зменшується на $s2 сек.\n\n\n\nВороги під дією Руйнування отримують до ${$447513s2*$447513u*0.1}% більше шкоди від тебе й завдають тобі до ${$447513s1*$447513u*-0.1}% менше шкоди протягом $447513d залежно від кількості зарядів Колосальної міці, поглинутих Руйнуванням." },
    { en = "Shockwave$?c1[, Cleave,][] and $?c1[Whirlwind][Revenge] deal $s1% more damage per target affected up to $s2.", ua = "Ударна хвиля$?c1[, Розсікання,][] і $?c1[Вихор][Помста] завдають на $s1% більше шкоди за кожну уражену ціль, до $s2." },
    { en = "Critical strike damage of your abilities is increased by $s1% and the amount of damage blocked by your critical blocks is increased by $s2%.", ua = "Шкоду критичних ударів твоїх здібностей збільшено на $s1%, а обсяг шкоди, яку блокують твої критичні блоки, — на $s2%." },
    { en = "Shockwave's stun duration is increased by ${$s1/1000} sec and reduces the movement speed of affected enemies by $458480s1% for $458480d after the stun ends.", ua = "Тривалість приголомшення від «Ударної хвилі» збільшено на ${$s1/1000} сек., а після завершення приголомшення швидкість руху уражених ворогів знижено на $458480s1% на $458480d." },
    { en = "Colossal Might increases the damage of your $?c1[Overpower][Revenge] by $?c1[$440989s3][$440989s4]% per stack.", ua = "Колосальна міць збільшує шкоду вашого $?c1[Здолання][Помсти] на $?c1[$440989s3][$440989s4]% за заряд." },
    { en = "You deal $s1% more damage and take $s4% less damage.\n\n\n\nSize increased by $s5%.", ua = "Ви завдаєте на $s1% більше шкоди і отримуєте на $s4% менше шкоди.\n\n\n\nРозмір збільшено на $s5%." },
    { en = "Damage prevented by each use of Ignore Pain is increased by $s1%.", ua = "Обсяг шкоди, якій запобігає кожне використання Ігнорування болю, збільшено на $s1%." },
    { en = "$?c1[Mortal Strike and Slam damage increased by $s1%.\n\n\n\nCleave and Whirlwind damage increased by $s2%][Shield Slam damage increased by $s3%.\n\n\n\nRevenge and Thunder Clap damage increased by $s4%].$?c3[\n\n\n\nShield Slam generates an additional ${$s5/10} Rage.][]", ua = "$?c1[Шкода від Смертельного удару та Удару наотмаш підвищена на $s1%.\n\n\n\nШкода від Розтину та Вихору підвищена на $s2%][Шкода від Удару щитом підвищена на $s3%.\n\n\n\nШкода від Помсти та Удару грому підвищена на $s4%].$?c3[\n\n\n\nУдар щитом створює додатково ${$s5/10} люті.][]" },
    { en = "Fire damage increased by $s1% and damage dealt by your demons is increased by $s3%.", ua = "Шкода від вогню збільшена на $s1%, а шкода, завдана твоїми демонами, — на $s3%." },
    { en = "$?a137013[Increases the damage of Fury of Elune by $s1% and the damage of Full Moon by $s2%.][Increases the damage of Lunar Beam by $s3% and Fury of Elune by $s1%.]", ua = "$?a137013[Збільшує шкоду Люті Елуни на $s1%, а шкоду Повного місяця — на $s2%.][Збільшує шкоду Місячного променя на $s3%, а Люті Елуни — на $s1%.]" },
    { en = "Demonic Art increases the damage of your next $?s137044[Hand of Gul'dan][Chaos Bolt, Rain of Fire, or Shadowburn] by $s1% and reduces its cast time by $s2%.\n\n\n\n$?s137044[][Casting Chaos Bolt reduces the duration of Diabolic Ritual by $s3 additional sec.]", ua = "Демонічне мистецтво збільшує шкоду вашого(ї) наступного(ї) $?s137044[Руки Ґул'дана][Снаряда хаосу, Вогняного дощу чи Тіньового спалаху] на $s1% і зменшує час його творення на $s2%.\n\n\n\n$?s137044[][Творення Снаряда хаосу зменшує тривалість Диявольського ритуалу на $s3 додаткові(их) сек.]" },
    { en = "$?s137044[Hand of Gul'dan deals $s1% increased damage for each Soul Shard spent.][Enemies marked by your Havoc take $s2% increased damage from your single target spells.]", ua = "$?s137044[Рука Ґул'дана завдає на $s1% більше шкоди за кожен витрачений Уламок душі.][Вороги, позначені вашим Хаосом, зазнають на $s2% більше шкоди від ваших заклять по одній цілі.]" },
    { en = "$?s137044[Summon Demonic Tyrant][Summon Infernal] grants Diabolic Ritual and reduces its duration by ${$s1/1000} sec.", ua = "$?s137044[Виклик Демонічного тирана][Виклик Інфернала] надає Диявольський ритуал і зменшує його тривалість на ${$s1/1000} сек." },
    { en = "Spending Soul Shards on damaging spells while your $?s137044[Demonic Tyrant][Infernal] is active decreases the duration of Diabolic Ritual by ${$s1/1000} additional sec.", ua = "Витрачання уламків душі на закляття, що завдають шкоди, поки активний ваш $?s137044[Демонічний тиран][Інфернал], зменшує тривалість Диявольського ритуалу на додаткові ${$s1/1000} сек." },
    { en = "Dark magic erupts from you and corrupts your soul for $d, causing enemies suffering from your Wither to take $446285s1 Shadowflame damage and increase its stack count by $430014s1.\n\n\n\nWhile corrupted your Haste is increased by $s1% and spending Soul Shards on damaging spells grants $430014s2 additional stack of Wither.", ua = "Темна магія вивергається з вас і опоганює вашу душу протягом $d, через що вороги, уражені вашим Згасанням, отримують $446285s1 шкоди Тіньового полум'я, а кількість стаків зростає на $430014s1.\n\n\n\nПоки душа опоганена, ваш поспіх збільшено на $s1%, а витрата Уламків душі на шкідливі закляття надає $430014s2 додатковий стак Згасання." },
    { en = "Exhilaration grants you $s1 sec of Survival of the Fittest.\n\n\n\nSurvival of the Fittest activates Exhilaration at $s2% effectiveness.", ua = "Снага надає вам $s1 сек. Виживання найсильнішого.\n\n\n\nВиживання найсильнішого активує Снагу з $s2% ефективністю." },
    { en = "While in combat, Disengage will chain the closest target to the ground, causing them to move $442396s1% slower until they move $s1 yards away.", ua = "У бою «Відступ» приковує найближчу ціль до землі, сповільнюючи її на $442396s1%, доки вона не віддалиться на $s1 м." },
    { en = "Launches a bolt of frostfire at the enemy, causing $468655s1 Frostfire damage, slowing movement speed by $205708s1%, and causing an additional $468655o2 Frostfire damage over $468655d.$?a1246769[\n\n\n\n|CFFffffffApplies $1246769s1 $lstack:stacks; of Freezing.|R][]", ua = "Запускає у ворога морозовогняну стрілу, завдаючи $468655s1 морозовогняної шкоди, уповільнюючи швидкість пересування на $205708s1% і завдаючи додатково $468655o2 морозовогняної шкоди протягом $468655d.$?a1246769[\n\n\n\n|CFFffffffНакладає $1246769s1 $lстак:стаки; «Заморожування».|R][]" },
    { en = "$?c2[Blazing Barrier also casts an Ice Barrier at $s1% effectiveness.]?c3[Ice Barrier also casts a Blazing Barrier at $s2% effectiveness.][]", ua = "$?c2[Палахка завіса також творить Крижану завісу з $s1% ефективністю.]?c3[Крижана завіса також творить Палахку завісу з $s2% ефективністю.][]" },
    { en = "$?c2[The cooldown of Frost spells with a base cooldown shorter than $s4 minutes is reduced by $s1%.]?c3[The cooldown of Fire spells is reduced by $s3%.][]", ua = "$?c2[Перезарядження крижаних заклять із базовим перезарядженням коротшим за $s4 хв зменшено на $s1%.]?c3[Перезарядження вогняних заклять зменшено на $s3%.][]" },
    { en = "$?a137019[Meteor now also calls down a Comet Storm, dealing ${$438609s1*7} Frost damage to nearby enemies]?a137020[Comet Storm now also calls down a Meteor, dealing $351140s1 Fire damage to nearby enemies. Damage reduced beyond 8 targets.\n\n\n\nDamage from Meteor Shatters $1246769s5 stacks of Freezing][Meteor now also calls down a Comet Storm, dealing ${$438609s1*7} Frost damage to nearby enemies.\n\n\n\nComet Storm now also calls down a Meteor, dealing $351140s1 Fire damage to nearby enemies].", ua = "$?a137019[Метеор тепер також прикликає Бурю комет, завдаючи ${$438609s1*7} од. шкоди від холоду ворогам поблизу]?a137020[Буря комет тепер також прикликає Метеор, завдаючи $351140s1 од. вогняної шкоди ворогам поблизу. Шкода зменшується після 8 цілей.\n\n\n\nШкода від Метеора руйнує $1246769s5 заряди Заморожування][Метеор тепер також прикликає Бурю комет, завдаючи ${$438609s1*7} од. шкоди від холоду ворогам поблизу.\n\n\n\nБуря комет тепер також прикликає Метеор, завдаючи $351140s1 од. вогняної шкоди ворогам поблизу]." },
    { en = "$?a137020[Ice Block and Ice Cold reset the cooldowns of your Fire spells.]?a137019[Cauterize resets the cooldown of your Frost spells with a base cooldown shorter than $s1 minutes when it activates.][Ice Block and Ice Cold reset the cooldowns of your Fire spells.\n\n\n\nCauterize resets the cooldown of your Frost spells with a base cooldown shorter than $s1 minutes when it activates.]", ua = "$?a137020[Крижана брила та Крижаний холод скидають перезарядження ваших заклять вогню.]?a137019[Припікання при спрацюванні скидає перезарядження ваших заклять морозу з базовим перезарядженням менше $s1 хвилин.][Крижана брила та Крижаний холод скидають перезарядження ваших заклять вогню.\n\n\n\nПрипікання при спрацюванні скидає перезарядження ваших заклять морозу з базовим перезарядженням менше $s1 хвилин.]" },
    { en = "Frostfire Bolt's cast time is reduced by $s1%.", ua = "Час творення «Стріли морозного вогню» скорочений на $s1%." },
    { en = "You melt slightly out of your Ice Block and Ice Cold, allowing you to move slowly during Ice Block and increasing your movement speed over time.\n\n\n\nIce Block and Ice Cold trigger a Blazing Barrier when they end.", ua = "Ви трохи розтаюєте зі свого Крижаного блоку та Крижаного холоду, що дає змогу повільно рухатися під час Крижаного блоку й поступово збільшує вашу швидкість пересування.\n\n\n\nКрижаний блок і Крижаний холод запускають Палахку перепону, коли добігають кінця." },
    { en = "$?a137020[Frostfire Bolt has an additional $s1% chance to grant Brain Freeze]?a137019[Frostfire Bolt's critical strike chance is increased by $s2%.][Frostfire Bolt has and additional $s1% chance to grant Brain Freeze and its critical strike chance is increased by $s2%].\n\n\n\nThe damage of your Frost spells and Fire spells are increased by $s3%.", ua = "$?a137020[Морозовогняна стріла має додаткові $s1% шансу надати Заморозку мозку]?a137019[Шанс критичного удару Морозовогняної стріли збільшено на $s2%.][Морозовогняна стріла має додаткові $s1% шансу надати Заморозку мозку, а її шанс критичного удару збільшено на $s2%].\n\n\n\nШкода від ваших заклять морозу та вогню збільшена на $s3%." },
    { en = "Casting Frostfire spells has a $s3% chance to activate Frostfire Empowerment, causing your next Frostfire Bolt to be instant cast, deal $431177s3% increased damage, explode for $s2% of its damage to nearby enemies. Damage reduced beyond $s5 targets.$?c2[][\n\n\n\nDamage from Frostfire Empowerment applies $s4 $Lstack:stacks; of Freezing.]", ua = "Творіння морозовогняних заклять має $s3% шансу активувати Морозовогняне підсилення, роблячи вашу наступну Морозовогняну стрілу миттєвою, завдаючи на $431177s3% більше шкоди та вибухаючи на $s2% її шкоди по ворогах поблизу. Шкода зменшена при понад $s5 цілях.$?c2[][\n\n\n\nШкода від Морозовогняного підсилення накладає $s4 $Lзаряд:заряди:зарядів; Заморожування.]" },
    { en = "$?a137020[Glacial Spike damage increased by $s1% and it now explodes on impact, dealing $s2% of its damage to up to $s3 nearby enemies.\n\n\n\nAdditionally, Glacial Spike now grants Frostfire Empowerment][Meteor's damage is increased by $s4%.\n\n\n\nMeteor now grants Frostfire Empowerment].", ua = "$?a137020[Шкода від Льодяного шпиля збільшена на $s1%, і він тепер вибухає при влучанні, завдаючи $s2% своєї шкоди $s3 ворогам поблизу.\n\n\n\nКрім того, Льодяний шпиль тепер надає Морозовогняне підсилення][Шкода від Метеора збільшена на $s4%.\n\n\n\nМетеор тепер надає Морозовогняне підсилення]." },
    { en = "Frostfire Empowerment stacks $s1 additional $Ltime:times; and it causes Frostfire Bolt to explode for an additional $s2% of its damage.", ua = "Наснага морозного вогню накопичується $s1 додатковий раз:додаткові рази; та змушує Стрілу морозного вогню вибухати, завдаючи додатково $s2% своєї шкоди." },
    { en = "Casting $?c1[Holy Prism or Divine Toll]?c3[Wake of Ashes][] causes your next $s1 Holy Power spending abilities to apply Dawnlight on your target, dealing $431380o1 Radiant damage or $431381o1 healing over $431380d.\n\n\n\n$431581s1% of Dawnlight's damage and healing radiates to nearby allies or enemies, reduced beyond $431581s2 targets.$?c1[\n\n\n\nDawnlight's healing does not transfer to Beacon of Light.][]", ua = "Прочитання $?c1[Святої призми або Божественного подзвону]?c3[Сліду попелу][] змушує ваші наступні $s1 здібностей, що витрачають Святу Силу, накладати Світанкове сяйво на вашу ціль, завдаючи $431380o1 шкоди Сяйва або зцілюючи на $431381o1 протягом $431380d.\n\n\n\n$431581s1% шкоди та зцілення Світанкового сяйва випромінюється на союзників чи ворогів поблизу, зменшуючись поза межами $431581s2 цілей.$?c1[\n\n\n\nЗцілення Світанкового сяйва не переноситься на Маяк Світла.][]" },
    { en = "$?c1[Critical Strike chance of Holy Shock and Light of Dawn increased by $s1%.]?c3[Critical Strike chance of Hammer of Wrath and Divine Storm increased by $s2%.][]", ua = "$?c1[Шанс критичного удару «Святого шоку» та «Світла світанку» збільшений на $s1%.]?c3[Шанс критичного удару «Молота гніву» та «Божественної бурі» збільшений на $s2%.][]" },
    { en = "Haste is increased by $s1%.", ua = "Поспіх збільшено на $s1%." },
    { en = "Movement speed increased by $431462s1% while above $s1% health.\n\n\n\nWhen your health is brought below $s3%, your movement speed is increased by $431752s1% for $431752d. Cannot occur more than once every $456779d.", ua = "Швидкість руху підвищено на $431462s1%, поки ваше здоров'я вище за $s1%.\n\n\n\nКоли ваше здоров'я падає нижче $s3%, ваша швидкість руху зростає на $431752s1% на $431752d. Може спрацьовувати не частіше ніж раз на $456779d." },
    { en = "Dawnlight leaves an Eternal Flame for ${$s1/1000} sec on allies or a Greater Judgment on enemies when it expires or is extended.", ua = "Коли «Світло світанку» спливає або продовжується, воно лишає на союзниках «Вічне полум'я» на ${$s1/1000} сек., а на ворогах — «Великий вирок»." },
    { en = "$?c1[Holy Shock and Light of Dawn critical strikes cause the target to be healed for an additional $431415o1 over $431415d.]?c3[Hammer of Wrath and Divine Storm critical strikes cause the target to burn for an additional $431414o1 Radiant damage over $431414d.][]", ua = "$?c1[Критичні удари «Святого шоку» та «Світла світанку» додатково зцілюють ціль на $431415o1 протягом $431415d.]?c3[Критичні удари «Молота гніву» та «Божественної бурі» обпалюють ціль, завдаючи їй додатково $431414o1 променистої шкоди протягом $431414d.][]" },
    { en = "Dawnlight reduces the movement speed of enemies by $431380s3% and increases the movement speed of allies by $431381s3%.", ua = "«Світло світанку» зменшує швидкість руху ворогів на $431380s3% та збільшує швидкість руху союзників на $431381s3%." },
    { en = "You link to your Dawnlights within $s8 yds, causing $431911s1 Radiant damage to enemies or $431939s1 healing to allies that pass through the beams, reduced beyond $?c3[$s9][$s6] targets.", ua = "Ти з'єднуєшся променями зі своїми «Світанковими сяйвами» в межах $s8 м: вороги, що проходять крізь промені, зазнають $431911s1 променистої шкоди, а союзники отримують $431939s1 зцілення. Ефект слабшає, якщо цілей більше ніж $?c3[$s9][$s6]." },
    { en = "Living Flame is enhanced with Bronze magic, repeating $?c2[$s1%][$s3%] of the damage or healing you dealt to the target in the last $s2 sec as Arcane, up to $?s1260647[$<cap2>][$<cap>].", ua = "Жива полум'я підсилена бронзовою магією та повторює $?c2[$s1%][$s3%] шкоди або зцілення, які ви завдали цілі за останні $s2 сек., у вигляді арканної енергії, до $?s1260647[$<cap2>][$<cap>]." },
    { en = "Hammer of Light instantly calls down $s1 Empyrean Hammers on your target when it is cast.", ua = "При застосуванні «Молот Світла» миттєво обрушує на твою ціль $s1 «Емпірейських молотів»." },
    { en = "$?c1[Light of Dawn and Holy Shock have a $s1% chance to cast again at $s2% effectiveness.]?c3[Divine Storm and Hammer of Wrath have a $s1% chance to cast again at $s2% effectiveness.][]", ua = "$?c1[«Світло світанку» та «Святий шок» мають $s1% шансу спрацювати повторно з $s2% ефективності.]?c3[«Божественна буря» та «Молот гніву» мають $s1% шансу спрацювати повторно з $s2% ефективності.][]" },
    { en = "Your Holy Power spenders deal $s1% additional damage and healing.", ua = "Твої здібності, що витрачають святу силу, завдають на $s1% більше шкоди та зцілення." },
    { en = "Every ${$t1}.1 sec, your next Dawnlight's damage or healing is increased by $431539s1%, stacking up to $431539u times.\n\n\n\nMorning Star stacks twice as fast while out of combat.", ua = "Кожні ${$t1}.1 с шкода або зцілення вашого наступного «Світанкового сяйва» збільшується на $431539s1%, аж до $431539u нашарувань.\n\n\n\n«Ранкова зоря» нашаровується вдвічі швидше поза боєм." },
    { en = "Each time you cast an empower spell, unstable time magic reduces its cooldown by up to $s1 sec.", ua = "Щоразу, коли ти твориш підсилюване закляття, нестабільна магія часу зменшує його перезарядження щонайбільше на $s1 сек." },
    { en = "After casting Hammer of Light, you call down an Empyrean Hammer on a nearby target every $431536T sec, for $431536d.", ua = "Після прочитання Молота Світла ти скидаєш Емпірейський молот на ціль поблизу кожні $431536T с протягом $431536d." },
    { en = "$?c1[Mortal Strike][Shield Slam] critical strikes grant an additional stack of Colossal Might.", ua = "Критичні удари $?c1[«Смертельного удару»][«Удару щитом»] надають додатковий стос «Колосальної міці»." },
    { en = "When Empyrean Hammer critically strikes, $s2% of its damage is dealt to nearby enemies.\n\n\n\nEnemies hit by this effect deal $431625s3% reduced damage to you for $431625d.", ua = "Коли «Емпірейний молот» завдає критичного удару, $s2% його шкоди завдається ворогам поблизу.\n\n\n\nВороги, уражені цим ефектом, завдають вам на $431625s3% менше шкоди на $431625d." },
    { en = "$?c2[Verdant Embrace heals for an additional $s1% over $409895d.][Upheaval deals $s2% additional damage over $431620d.]", ua = "$?c2[Зелені обійми зцілюють додатково на $s1% протягом $409895d.][Здіймання завдає на $s2% більше шкоди протягом $431620d.]" },
    { en = "For each $?c2[healing over time effect from Verdant Embrace][damage over time effect from Upheaval], gain $s1% haste, up to $s2%.", ua = "За кожен $?c2[ефект періодичного зцілення від Зелених обіймів][ефект періодичної шкоди від Здіймання] ви отримуєте $s1% поспіху, до $s2%." },
    { en = "$?a137028[Crusader Strike, Hammer of Wrath and Judgment][Crusader Strike, Hammer of Wrath and Blade of Justice] extend the duration of Shake the Heavens by $s1 sec.", ua = "$?a137028[«Удар хрестоносця», «Молот гніву» та «Осуд»][«Удар хрестоносця», «Молот гніву» та «Клинок правосуддя»] подовжують тривалість «Струсу небес» на $s1 сек." },
    { en = "Tip the Scales overloads you with temporal energy, increasing your haste, movement speed, and cooldown recovery rate by ${$431698u*$431698s1}%, decreasing over $431698d.", ua = "Схилення терезів переповнює тебе часовою енергією, збільшуючи твій поспіх, швидкість руху та темп відновлення перезаряджень на ${$431698u*$431698s1}%; ефект поступово слабшає протягом $431698d." },
    { en = "$?c2[Temporal Anomaly mana cost reduced by $s1% and cooldown reduced by ${$s2/-1000} sec.][Prescience cooldown reduced by ${$s3/-1000} sec and it grants $s4% additional critical strike chance.]", ua = "$?c2[Витрати мани Часової аномалії зменшено на $s1%, а перезарядження зменшено на ${$s2/-1000} с.][Перезарядження Передбачення зменшено на ${$s3/-1000} с, і воно надає $s4% додаткового шансу критичного удару.]" },
    { en = "$?a137028[Divine Toll][Wake of Ashes] surrounds you with a Holy barrier for $?a137028[$s1][$s4]% of your maximum health.\n\n\n\nHammer of Light heals you for $?a137028[$s2][$s5]% of your maximum health, increased by $?a137028[$s3][$s6]% for each additional target hit. Any overhealing done with this effect gets converted into a Holy barrier instead.", ua = "$?a137028[Божественний подзвін][Слід попелу] оточує вас Святим бар'єром на $?a137028[$s1][$s4]% вашого максимального здоров'я.\n\n\n\nМолот Світла зцілює вас на $?a137028[$s2][$s5]% вашого максимального здоров'я, збільшуючись на $?a137028[$s3][$s6]% за кожну додатково уражену ціль. Будь-яке надлишкове зцілення від цього ефекту натомість перетворюється на Святий бар'єр." },
    { en = "Warp reduces damage taken by ${$s1/-1}%, starting high and reducing over $431872d.", ua = "Викривлення зменшує отримувану шкоду на ${$s1/-1}%: спершу сильно, далі ефект поступово слабшає протягом $431872d." },
    { en = "$?c2[When Dream Breath or Fire Breath critically strike, their duration is extended by $s1 sec, up to a maximum of ${$s1*6} sec.][Ebon Might and Prescience gain a chance equal to your critical strike chance to grant $s2% additional stats.]", ua = "$?c2[Коли Подих мрії або Подих вогню завдають критичного удару, їхню тривалість продовжено на $s1 с, до максимуму в ${$s1*6} с.][Чорна міць і Передбачення отримують шанс, що дорівнює вашому шансу критичного удару, надати $s2% додаткових характеристик.]" },
    { en = "Empower spells send up to $s1 Chrono Flames to your targets.", ua = "Підсилювані закляття посилають у твої цілі до $s1 спалахів «Хронополум'я»." },
    { en = "Non-defensive abilities with a $s1 second or longer cooldown grant $431991s1% Intellect for $431991d.\n\n\n\nEssence spells extend the duration by $s2 sec.", ua = "Незахисні здібності з часом перезарядження $s1 секунд або довше надають $431991s1% інтелекту на $431991d.\n\n\n\nЗакляття есенції продовжують дію на $s2 сек." },
    { en = "$?c2[Echo is $s1% more effective.][Prescience lasts $s2% longer.]", ua = "$?c2[Відлуння на $s1% ефективніше.][Передбачення триває на $s2% довше.]" },
    { en = "Warp leaves a trail of Motes of Acceleration. Allies who come in contact with a mote gain 20% increased movement speed for 30 sec.", ua = "Викривлення лишає за собою слід із Часточок прискорення. Союзники, що торкнулися часточки, отримують збільшення швидкості руху на 20% на 30 сек." },
    { en = "Your physical damage taken is reduced by $s2% and an additional $432180s2% every $t1 sec until you receive a physical attack.", ua = "Отримувана тобою фізична шкода зменшена на $s2% і додатково на $432180s2% кожні $t1 сек., доки ти не зазнаєш фізичної атаки." },
    { en = "Will the Light to coalesce and become manifest as a Holy Armament, wielded by your friendly target.\n\n\n\n$@spellicon432496 $@spellname432496:\n\n\n\n$@spelldesc432496\n\n\n\nBecomes Sacred Weapon after use.$?c1[\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.][]", ua = "Волею змушує Світло згуститися й проявитися як Святе озброєння, яким володіє ваша дружня ціль.\n\n\n\n$@spellicon432496 $@spellname432496:\n\n\n\n$@spelldesc432496\n\n\n\nПісля використання стає Священною зброєю.$?c1[\n\n\n\n|cFFFFFFFFДає $s2 Священної сили.][]" },
    { en = "$?a137028[Shield of the Righteous and Word of Glory]?s383328[Final Verdict][Templar's Verdict]$?a137027[ and Divine Storm][] calls down an Empyrean Hammer on a nearby enemy.\n\n\n\nWhile Shake the Heavens is active, this effect calls down an additional Empyrean Hammer.", ua = "$?a137028[Щит праведника і Слово слави]?s383328[Остаточний вирок][Вирок тамплієра]$?a137027[ і Божественна буря][] прикликають Емпірейський молот на ворога поблизу.\n\n\n\nКоли активне Струсіння небес, цей ефект прикликає додатковий Емпірейський молот." },
    { en = "Empyrean Hammer has a $s1% increased chance to critically strike.", ua = "Шанс критичного удару «Емпірейського молота» збільшено на $s1%." },
    { en = "Hammer of Light $?a137028[grants Shield of the Righteous, erupts a Consecration beneath its target][applies Judgment to its targets], and increases your Haste by $432629s1% for $432629d.", ua = "«Молот світла» $?a137028[дарує «Щит праведника» та вивергає «Освячення» під своєю ціллю][накладає «Осуд» на свої цілі], а також збільшує твій Поспіх на $432629s1% на $432629d." },
    { en = "If you bestow an Armament upon an ally, you also gain its benefits.\n\n\n\nIf you bestow an Armament upon yourself, a nearby ally also gains its benefits.", ua = "Якщо ви даруєте Озброєння союзникові, ви теж отримуєте його переваги.\n\n\n\nЯкщо ви даруєте Озброєння собі, союзник поблизу теж отримує його переваги." },
    { en = "The cooldown of Holy Armaments is reduced by $s1%.", ua = "Перезарядження «Священного озброєння» зменшено на $s1%." },
    { en = "The effect of your active Aura is increased by $432496s1% on targets with your Armaments.", ua = "Ефект твоєї активної аури посилено на $432496s1% для цілей із твоїм озброєнням." },
    { en = "When an Armament fades from you, the cooldown of Lay on Hands is reduced by ${$s1/1000}.1 sec and you gain $?a137028[Shining Light][Infusion of Light].", ua = "Коли дія озброєння на тобі завершується, перезарядження «Покладання рук» скорочується на ${$s1/1000}.1 с, і ти отримуєш ефект $?a137028[«Сяйне світло»][«Вливання Світла»]." },
    { en = "Consuming $?a137028[Shining Light][Infusion of Light] reduces the cooldown of Holy Armaments by ${$s1/1000}.1 sec.", ua = "Споживання ефекту $?a137028[«Осяйне світло»][«Наповнення світлом»] скорочує перезарядження «Святого озброєння» на ${$s1/1000}.1 с." },
    { en = "Divine Toll summons Divine Hammers that spin around you for $198034d.\n\n\n\n$@spellicon198034$@spellname198034\n\n$@spelldesc198034", ua = "Божественний подзвін прикликає Божественні молоти, що обертаються навколо вас протягом $198034d.\n\n\n\n$@spellicon198034$@spellname198034\n\n$@spelldesc198034" },
    { en = "Your spells and abilities have a chance to manifest a Holy Armament for a nearby ally.", ua = "Твої закляття та здібності мають шанс створити «Святе озброєння» для союзника поруч." },
    { en = "Casting Judgment increases the damage of Empyrean Hammer by $433671s1% for $433671d.\n\n\n\nMultiple applications may overlap.", ua = "Накладання «Осуду» збільшує шкоду «Емпірейного молота» на $433671s1% протягом $433671d.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Divine Steed lasts ${$s1/1000} sec longer and increases your movement speed by an additional $442221s1% for the first $442221d.", ua = "«Божественний скакун» триває на ${$s1/1000} сек. довше та додатково збільшує твою швидкість руху на $442221s1% протягом перших $442221d." },
    { en = "You receive 20% less damage from Blessing of Sacrifice and each time its target takes damage, you gain 4% movement speed up to a maximum of 40%.", ua = "Ти отримуєш на 20% менше шкоди від «Благословення жертви», а щоразу, коли його ціль зазнає шкоди, ти отримуєш 4% швидкості руху, аж до максимуму 40%." },
    { en = "Avenging Wrath summons an additional Sacred Weapon, and during Avenging Wrath your Sacred Weapon casts spells on your target and echoes the effects of your Holy Power abilities.", ua = "«Гнів месника» прикликає додаткову священну зброю, і поки діє «Гнів месника», твоя священна зброя творить закляття на твою ціль та повторює ефекти твоїх здібностей святої сили." },
    { en = "Casting a Holy Power ability increases the damage and healing of your next $?s204019[Blessed Hammer]?s53595[Hammer of the Righteous]?s137029[Holy Shock][Crusader Strike] by $433019s1%.", ua = "Створення здібності, що витрачає святу силу, збільшує шкоду та зцілення твого наступного $?s204019[«Благословенного молота»]?s53595[«Молота праведника»]?s137029[«Святого шоку»][«Удару хрестоносця»] на $433019s1%." },
    { en = "For each Holy Power ability cast, your next Consecration deals $?a137029[$<holy>][$<prot>] damage or healing immediately, split across all enemies and allies.", ua = "За кожну вжиту здібність, що витрачає святу силу, твоє наступне «Освячення» миттєво завдає $?a137029[$<holy>][$<prot>] од. шкоди або зцілення, розділених між усіма ворогами та союзниками." },
    { en = "Imbue your weapon with the power of the Light, increasing your armor by $433550s2% and your primary stat by $433550s1%.\n\n\n\nLasts $433550d.", ua = "Наповнює вашу зброю силою Світла, збільшуючи вашу броню на $433550s2% і вашу основну характеристику на $433550s1%.\n\n\n\nТриває $433550d." },
    { en = "Imbue your weapon with the power of the Light, increasing your Stamina by $433584s1% and causing your Holy Power abilities to sometimes unleash a burst of healing around a target.\n\n\n\nLasts $433584d.", ua = "Наповнює вашу зброю силою Світла, збільшуючи вашу витривалість на $433584s1% і змушуючи ваші здібності, що витрачають Священну силу, іноді вивільняти сплеск зцілення навколо цілі.\n\n\n\nТриває $433584d." },
    { en = "Judgment critical strikes cause a shockwave around the target, $?c1[healing to up to $s3 injuried allies for $433722s1][dealing $433717s1 damage to enemies within $433717a1 yards. Damage reduced above $s4 targets].", ua = "Критичні удари «Вироку» спричиняють ударну хвилю навколо цілі, $?c1[що зцілює до $s3 поранених союзників на $433722s1][що завдає $433717s1 од. шкоди ворогам у радіусі $433717a1 м. Шкода зменшується, якщо цілей більше ніж $s4]." },
    { en = "Your Regrowth protects you, reducing damage you take by $s1% while your Regrowth is on you.", ua = "Твоє «Відростання» захищає тебе, зменшуючи отримувану шкоду на $s1%, поки воно діє на тебе." },
    { en = "$?a137013[Force of Nature grants $s1 charges of Dream Burst, causing your next Wrath or Starfire to explode on the target, dealing ${$433850s1*(1+$393014s3/100)} Nature damage to nearby enemies. Damage reduced above $433850s2 targets.][When Grove Guardians are summoned, they grow Dream Petals on your target, healing up to $s2 nearby allies for $434141s1.]", ua = "$?a137013[Сила природи надає $s1 заряди Вибуху сну, завдяки чому твій наступний Гнів або Зоряний вогонь вибухає на цілі, завдаючи ${$433850s1*(1+$393014s3/100)} природної шкоди ворогам поблизу. Шкода зменшена, якщо цілей більше ніж $433850s2.][Коли призиваються Вартові гаю, вони вирощують на твоїй цілі Пелюстки сну, що зцілюють до $s2 союзників поблизу на $434141s1.]" },
    { en = "$?s403631[Breath of Eons][Deep Breath] can now be steered in your desired direction.\n\n\n\nIn addition, $?s403631[Breath of Eons][Deep Breath] burns targets for $441172o1 Volcanic damage over $441172d.$?c1[\n\n\n\nThe duration of this effect is extended when Deep Breath is cast multiple times.][]", ua = "$?s403631[Подих еонів][Глибокий подих] тепер можна спрямовувати в бажаному напрямку.\n\n\n\nКрім того, $?s403631[Подих еонів][Глибокий подих] обпікає цілі на $441172o1 вулканічної шкоди протягом $441172d.$?c1[\n\n\n\nТривалість цього ефекту подовжується, коли Глибокий подих застосовується кілька разів.][]" },
    { en = "Your Death Coil$?a137007[, Epidemic][] and Death Strike have a $s1% chance to make your next $?a137008[Heart Strike]?s207311[Clawing Shadows][Scourge Strike] become Vampiric Strike.\n\n\n\nVampiric Strike heals you for $?a137008[$434422s2][$434422s3]% of your maximum health and grants you Essence of the Blood Queen, increasing your Haste by ${$433925s1/10}.1%, up to ${$433925s1*$433925u/10}.1% for $433925d.", ua = "Ваш Смертельний сувій$?a137007[, Епідемія][] та Удар смерті мають $s1% шансу перетворити ваш наступний $?a137008[Удар у серце]?s207311[Дряпучі тіні][Удар Погибелі] на Вампірський удар.\n\n\n\nВампірський удар зцілює вас на $?a137008[$434422s2][$434422s3]% від вашого максимального здоров'я та дарує вам Есенцію Кривавої Королеви, збільшуючи ваш Поспіх на ${$433925s1/10}.1%, до ${$433925s1*$433925u/10}.1% протягом $433925d." },
    { en = "$?a137032[Your Flash Heal and Power Word: Shield are $s1%][Your Flash Heal and Holy Word: Serenity are $s1%] more effective when cast on yourself.", ua = "$?a137032[Ваше Швидке зцілення і Слово сили: Щит на $s1%][Ваше Швидке зцілення і Святе слово: Безтурботність на $s1%] ефективніші, коли ви чините їх на себе." },
    { en = "Raise Ally revives players at full health and grants you and your ally an absorb shield equal to $s2% of your maximum health.", ua = "«Підняття союзника» воскрешає гравців із повним здоров'ям і дає тобі та твоєму союзнику поглинальний щит, що дорівнює $s2% твого максимального здоров'я." },
    { en = "Death's Advance and Wraith Walk movement speed bonuses are increased by $s1%.\n\n\n\nActivating Death's Advance or Wraith Walk increases $434029s2 nearby allies movement speed by $434029s1% for $434029d.", ua = "Бонуси до швидкості пересування від Поступу смерті та Примарної ходи збільшені на $s1%.\n\n\n\nАктивація Поступу смерті або Примарної ходи збільшує швидкість пересування $434029s2 союзників поблизу на $434029s1% протягом $434029d." },
    { en = "While you are within your Death and Decay, your physical damage taken is reduced by ${$434034s1*-1}% and your chance to gain Vampiric Strike is increased by $s2%.", ua = "Поки ти стоїш у зоні своєї «Смерті й розкладу», отримувана фізична шкода зменшується на ${$434034s1*-1}%, а шанс отримати «Вампірський удар» збільшується на $s2%." },
    { en = "Essence of the Blood Queen stacks $s1 additional times and increases the damage of your $?s137008[Death Coil and Death Strike by $s2%][Death Coil and Death Strike by $s2%, and Epidemic by $s3%] per stack.", ua = "Есенція Кривавої Королеви накопичується $s1 додаткових разів і збільшує шкоду ваших $?s137008[Смертельного покрову та Удару смерті на $s2%][Смертельного покрову та Удару смерті на $s2%, а Епідемії — на $s3%] за кожен стак." },
    { en = "Your Leech is increased by $s1%.\n\n\n\nWhile Lichborne is active, the Leech bonus of this effect is increased by $434105s1%, and it affects $s2 allies within 12 yds.", ua = "Ваше Висмоктування збільшується на $s1%.\n\n\n\nПоки Лічеродний активний, бонус Висмоктування від цього ефекту збільшується на $434105s1% і впливає на $s2 союзників у межах 12 м." },
    { en = "Icebound Fortitude reduces all damage you take by up to an additional $s1% based on your missing health.\n\n\n\nKilling an enemy that yields experience or honor reduces the cooldown of Icebound Fortitude by $s2 sec.", ua = "Крижана стійкість зменшує всю отриману вами шкоду додатково на величину до $s1% залежно від нестачі здоров'я.\n\n\n\nУбивство ворога, який дає досвід або честь, скорочує перезарядження Крижаної стійкості на $s2 сек." },
    { en = "When Vampiric Strike damages an enemy affected by your $?a137008[Blood Plague][plagues], it extends the duration of the $?a137008[disease][plagues] by $?c1[${$s3/1000}.1][${$s5/1000}.1] sec$?c1[, and deals $s2% of the remaining damage to the enemy.][, and erupts them with $s6% increased effectiveness.]", ua = "Коли Вампірський удар завдає шкоди ворогу, ураженому вашою $?a137008[Кривавою чумою][чумою], він продовжує тривалість $?a137008[хвороби][чуми] на $?c1[${$s3/1000}.1][${$s5/1000}.1] сек.$?c1[ і завдає ворогу $s2% залишкової шкоди.][ і викликає вибух із підвищеною на $s6% ефективністю.]" },
    { en = "Vampiric Strike and $?a137008[Heart Strike]?s207311[Clawing Shadows][Scourge Strike] cause your targets to take $458478s1% increased Shadow damage, up to ${$458478s1*$458478U}% for $458478d.\n\n\n\nVampiric Strike benefits from Incite Terror at $s2% effectiveness.", ua = "Вампірський удар і $?a137008[Удар у серце]?s207311[Дряпучі тіні][Удар Погибелі] змушують ваші цілі отримувати на $458478s1% більше тіньової шкоди, до ${$458478s1*$458478U}% протягом $458478d.\n\n\n\nВампірський удар отримує користь від Розпалення жаху з $s2% ефективністю." },
    { en = "While $?a137008[Dancing Rune Weapon][Dark Transformation] is active you gain Gift of the San'layn.\n\n\n\nGift of the San'layn increases the effectiveness of your Essence of the Blood Queen by $?a137007[$434153s1][$434153s4]%, and Vampiric Strike replaces your $?a137008[Heart Strike]?s207311[Clawing Shadows][Scourge Strike] for the duration.", ua = "Поки активна $?a137008[Танцююча рунічна зброя][Темна трансформація], ви отримуєте Дар сан'лейнів.\n\n\n\nДар сан'лейнів збільшує ефективність вашої Есенції Кривавої Королеви на $?a137007[$434153s1][$434153s4]%, а Вампірський удар замінює ваш $?a137008[Удар у серце]?s207311[Дряпучі тіні][Удар Погибелі] на час дії." },
    { en = "When $?a137008[Crimson Scourge][Sudden Doom] is consumed, you gain $?a137008[$461130s1][$434159s1]% Strength for $?a137008[$461130d][$434159d].", ua = "Коли $?a137008[Багряний Батіг][Раптова загибель] використовується, ви отримуєте $?a137008[$461130s1][$434159s1]% Сили протягом $?a137008[$461130d][$434159d]." },
    { en = "$?a137013[Force of Nature grants an additional stack of Dream Burst.][Dream Surge heals $s2 additional $Lally:allies;.]", ua = "$?a137013[Сила природи надає додатковий заряд Вибуху сну.][Сплеск Сну зцілює $s2 $Lдодаткового союзника:додаткових союзників;.]" },
    { en = "Time elapsed while your major abilities are available to be used or at maximum charges is subtracted from that ability's cooldown after the next time you use it, up to $s1 seconds.\n\n\n\nAffects $?a137012[Nature's Swiftness, Incarnation: Tree of Life,][Force of Nature,] $?a137012[]?a394013[Incarnation: Chosen of Elune, ][Celestial Alignment, ]and Convoke the Spirits.", ua = "Час, що минув, поки ваші головні здібності доступні для використання чи мають максимум зарядів, віднімається від перезарядження цієї здібності після наступного її застосування, до $s1 секунд.\n\n\n\nВпливає на $?a137012[Стрімкість природи, Втілення: Дерево Життя,][Силу природи,] $?a137012[]?a394013[Втілення: Обранець Елуни, ][Небесне вирівнювання, ]та Скликання духів." },
    { en = "$?a137008[Dancing Rune Weapon]?s275699[Apocalypse][Dark Transformation] summons a Blood Beast to attack your enemy for $434237d.\n\n\n\nEach time the Blood Beast attacks, it stores a portion of the damage dealt. When the Blood Beast dies, it explodes, dealing $?a137007[$s2][$s1]% of the damage accumulated to nearby enemies and healing the Death Knight for the same amount. Deals reduced damage beyond $s3 targets.", ua = "$?a137008[Танцівна рунічна зброя]?s275699[Апокаліпсис][Темне перетворення] прикликає Криваву звірину, що атакує вашого ворога протягом $434237d.\n\n\n\nЩоразу, коли Кривава звірина атакує, вона накопичує частину завданої шкоди. Коли Кривава звірина гине, вона вибухає, завдаючи $?a137007[$s2][$s1]% накопиченої шкоди ворогам поблизу та зцілюючи Лицаря смерті на ту саму величину. Завдає зменшеної шкоди понад $s3 цілей." },
    { en = "You store $s1% of all Shadow damage dealt into your Blood Beast to explode for additional damage when it expires.", ua = "Ти накопичуєш $s1% усієї завданої тіньової шкоди у своїй кривавій бестії; коли її час спливає, вона вибухає, завдаючи додаткової шкоди." },
    { en = "Your Death Coil$?a137007[, Epidemic][] and Death Strike have a $s2% increased chance to trigger Vampiric Strike when damaging enemies below $s1% health.", ua = "Ваші «Смертельна спіраль»$?a137007[, «Епідемія»][] та «Удар смерті» мають на $s2% більший шанс запустити «Вампірський удар», коли завдають шкоди ворогам зі здоров'ям нижче $s1%." },
    { en = "$?c1[Mass Disintegrate][Mass Eruption] marks your primary target for destruction for the next $434473d.\n\n\n\nYou and your allies have a chance to trigger a Bombardment when attacking marked targets, dealing $<dmg> Volcanic damage split amongst all nearby enemies.", ua = "$?c1[Масовий розпад][Масове виверження] позначає вашу основну ціль для знищення на наступні $434473d.\n\n\n\nВи й ваші союзники маєте шанс викликати Бомбардування, атакуючи позначені цілі, що завдає $<dmg> вулканічної шкоди, поділеної між усіма ворогами поруч." },
    { en = "Transcendence now tethers your spirit onto an ally for $434763d. Use Transcendence: Transfer to teleport to your ally's location.", ua = "«Трансценденція» тепер прив'язує твій дух до союзника на $434763d. Використай «Трансценденцію: перенесення», щоб телепортуватися до союзника." },
    { en = "Reaper's Mark initial strike grants $?a137008][$s3 charges of Bone Shield][Killing Machine].\n\n\n\nReaper's Mark explosion deals up to $s1% increased damage based on your target's missing health.", ua = "Початковий удар Мітки женця надає $?a137008][$s3 заряди Кістяного щита][Машину вбивства].\n\n\n\nВибух Мітки женця завдає до $s1% більше шкоди залежно від нестачі здоров'я вашої цілі." },
    { en = "Damaging enemies with Thunder Clap, $?a137048[Revenge, ][Raging Blow, ]or Execute has a $s1% chance to also strike one with a lightning bolt, dealing $435791s1 Nature damage$?s436152[ and generating ${$436152s3/10} Rage][].\n\n\n\nLightning Strikes occur $s2% more often during Avatar.", ua = "Завдаючи шкоди ворогам Громовим ударом, $?a137048[Помстою, ][Несамовитим ударом, ]чи Стратою, ви маєте $s1% шанс також уразити одного з них блискавкою, завдаючи $435791s1 шкоди Природою$?s436152[ й генеруючи ${$436152s3/10} люті][].\n\n\n\nУдари блискавок трапляються на $s2% частіше під час Аватара." },
    { en = "Stamina increased by $s1%.\n\n\n\n$?s202168[Impending Victory][Victory Rush] increases your maximum health by $437152s3% for $437152d. When this health increase expires, you heal for any amount of the original $?s202168[Impending Victory][Victory Rush] that healed you in excess of your full health.", ua = "Витривалість збільшено на $s1%.\n\n\n\n$?s202168[Неминуча перемога][Шал перемоги] збільшує ваше максимальне здоров'я на $437152s3% протягом $437152d. Коли це збільшення здоров'я спливає, ви зцілюєтеся на ту частину початкового $?s202168[Неминучої перемоги][Шалу перемоги], що зцілила вас понад повне здоров'я." },
    { en = "Your auto attack damage is increased by $s2%. \n\n\n\nThis amount is increased for each stack of Icy Talons you have and it can stack up to $s1 additional times.", ua = "Шкода ваших автоатак збільшується на $s2%. \n\n\n\nЦя величина зростає за кожен заряд Крижаних пазурів, який ви маєте, і може накопичуватися додатково до $s1 разів." },
    { en = "Your auto attack critical strikes have a chance to send out a torrent of ice dealing $439539s1 Frost damage to enemies in front of you.", ua = "Критичні удари твоїх автоатак мають шанс випустити крижаний потік, що завдає $439539s1 шкоди від морозу ворогам перед тобою." },
    { en = "Shield Slam and Bloodthirst have a $s1% chance to grant you Thunder Blast, stacking up to 2 charges.\n\n\n\n$@spellicon435222|cFFFFFFFF$@spellname435222|r\n\nYour next Thunder Clap becomes a Thunder Blast that deals $435222s1 Stormstrike damage and generates ${$435222s4/10} Rage.", ua = "Удар щитом та Жага крові мають $s1% шанс надати вам Громовий вибух, що накопичується до 2 зарядів.\n\n\n\n$@spellicon435222|cFFFFFFFF$@spellname435222|r\n\nВаш наступний Громовий удар стає Громовим вибухом, що завдає $435222s1 шкоди Штормовим ударом і генерує ${$435222s4/10} люті." },
    { en = "Lightning Strikes also deal $460670s1 Nature damage to enemies near their target. Damage reduced beyond $460670s2 targets.", ua = "«Удари блискавки» також завдають $460670s1 шкоди від сил природи ворогам поруч із ціллю. Якщо цілей більше ніж $460670s2, шкоду зменшено." },
    { en = "Lightning Strikes generate ${$s1/10} Rage.\n\n\n\n$?a137048[Revenge][Raging Blow] and Execute damage increased by $s2%.", ua = "Удари блискавок генерують ${$s1/10} люті.\n\n\n\nШкоду $?a137048[Помсти][Несамовитого удару] та Страти збільшено на $s2%." },
    { en = "Storm Bolt also hits $s1 additional nearby $Ltarget:targets;, stunning them for $s2 sec, but its cooldown is increased by ${$s3/1000} sec.", ua = "«Громовий болт» також влучає в $s1 додаткову $Lціль поблизу:додаткові цілі поблизу; та приголомшує їх на $s2 с, але його перезарядження збільшено на ${$s3/1000} с." },
    { en = "Your attacks trigger Lightning Strikes $s1% more often.", ua = "Твої атаки викликають «Удари блискавки» на $s1% частіше." },
    { en = "Empower spells cause your next Disintegrate to strike up to $s1 targets. When striking fewer than $s1 targets, Disintegrate damage is increased by $s2% for each missing target.", ua = "Підсилювані закляття змушують твою наступну «Дезінтеграцію» вражати до $s1 цілей. Якщо вражено менше ніж $s1 цілей, шкода «Дезінтеграції» збільшується на $s2% за кожну відсутню ціль." },
    { en = "Unleash a series of precise and powerful strikes against your target, dealing ${$440884s1+$440886s1+$440888s1} damage to it, and $440888s1 damage to enemies within $440888A1 yds of it. Deals reduced damage beyond $s1 targets.\n\n\n\nWhile channeling Demolish, you take $s4% less damage and are immune to stuns, knockbacks, and forced movement effects.\n\n\n\nYou can block, parry, dodge, and use certain defensive abilities while channeling Demolish.", ua = "Вивільняєш низку точних і потужних ударів по цілі, завдаючи їй ${$440884s1+$440886s1+$440888s1} шкоди, а також $440888s1 шкоди ворогам у межах $440888A1 м від неї. Завдає зменшеної шкоди після $s1 цілей.\n\n\n\nПід час підтримання Руйнування ти отримуєш на $s4% менше шкоди й невразливий до приголомшення, відкидання та ефектів примусового пересування.\n\n\n\nТи можеш блокувати, парирувати, ухилятися й використовувати деякі захисні здібності під час підтримання Руйнування." },
    { en = "$?a137008[Marrowrend and Heart Strike have][Consuming Killing Machine or Rime has] a $s1% chance to grant $s2 stacks of Icy Talons and increase its maximum stacks by the same amount for 6 sec.\n\n\n\nRunic Power spending abilities count as Shadowfrost while Icy Talons is active.", ua = "$?a137008[Костолам і Удар у серце мають][Спожиття Машини вбивства або Паморозі має] $s1% шансу надати $s2 стаки Крижаних кігтів і збільшити їх максимальну кількість стаків на стільки ж на 6 сек.\n\n\n\nПоки активні Крижані кігті, здібності, що витрачають Рунічну енергію, рахуються як тіньоморозні." },
    { en = "Stormstrike or Nature damage your abilities deal is increased by $s1%. Stormstrike damage ignores Armor.\n\n\n\nThunder Clap damage increased by $s4%$?a137050[, no longer costs Rage, and now generates ${$s5/10} Rage][].$?a137050[\n\n\n\nImproved Whirlwind, Meat Cleaver, and Barbaric Training affect Thunder Clap in addition to Whirlwind.][]", ua = "Шкоду Штормовим ударом або Природою, яку завдають ваші здібності, збільшено на $s1%. Шкода Штормового удару ігнорує Броню.\n\n\n\nШкоду Громового удару збільшено на $s4%$?a137050[, він більше не коштує люті й тепер генерує ${$s5/10} люті][].$?a137050[\n\n\n\nПокращений вихор, Різницький тесак та Варварський вишкіл впливають на Громовий удар на додачу до Вихору.][]" },
    { en = "Shield Slam damage increased by $s1%.$?a137048[\n\n\n\nDemoralizing Shout reduces damage enemies deal to you by an additional ${-$s2}%.][\n\n\n\nBloodthirst and Rampage damage increased by $s4%.]", ua = "Шкоду Удару щитом збільшено на $s1%.$?a137048[\n\n\n\nДеморалізуючий крик додатково зменшує шкоду, яку завдають вам вороги, на ${-$s2}%.][\n\n\n\nШкоду Жаги крові та Буйства збільшено на $s4%.]" },
    { en = "Thunder Blast calls down a Lightning Strike on an enemy it hits.", ua = "«Громовий вибух» закликає «Удар блискавки» на влученого ворога." },
    { en = "Lightning Strikes have a $h% chance to make your next $s1 $?a137048[Shield Slams][Bloodthirsts] have no cooldown$?a137050[, deal $437121s2% increased damage, and generate ${$437121s3/10} additional Rage][].", ua = "Удари блискавки мають $h% шанс зробити так, щоб ваші наступні $s1 $?a137048[Удари щитом][Кровожерливості] не мали перезарядження$?a137050[, завдавали на $437121s2% більше шкоди та генерували ${$437121s3/10} додаткової Люті][]." },
    { en = "Reduces the cooldowns of Lichborne and Raise Dead by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Лічеродності» та «Підняття мерця» на ${$s1/-1000} сек." },
    { en = "Casting Avatar grants you $s1 charges of Thunder Blast and resets the cooldown of Thunder Clap.\n\n\n\nWhile Avatar is not active, Lightning Strikes have a $s2% chance to grant you Avatar for $s3 secs.\n\n\n\n$@spellicon435222|cFFFFFFFF$@spellname435222|r\n\nYour next Thunder Clap becomes a Thunder Blast that deals Stormstrike damage.", ua = "Прочитання Аватара дає вам $s1 зарядів Громового вибуху та скидає перезарядження Удару грому.\n\n\n\nПоки Аватар не активний, Удари блискавки мають $s2% шанс надати вам Аватар на $s3 сек.\n\n\n\n$@spellicon435222|cFFFFFFFF$@spellname435222|r\n\nВаш наступний Удар грому стає Громовим вибухом, що завдає шкоди Штормовим ударом." },
    { en = "When Reaper's Mark explodes, it deals $?a137008[$s1][$s2]% of the damage dealt to nearby enemies.", ua = "Коли Мітка женця вибухає, вона завдає $?a137008[$s1][$s2]% завданої шкоди ворогам поблизу." },
    { en = "Your spells and abilities have a chance to make your next Spinning Crane Kick deal an additional $s1% damage.", ua = "Твої закляття та здібності мають шанс зробити так, що твій наступний «Обертовий удар журавля» завдасть додатково $s1% шкоди." },
    { en = "Empower spells cause your next Eruption to strike up to $s1 targets. When striking less than $s1 targets, Eruption damage is increased by $s2% for each missing target.", ua = "Підсилювані закляття змушують твоє наступне «Виверження» вражати до $s1 цілей. Якщо вражено менше ніж $s1 цілей, шкода «Виверження» збільшується на $s2% за кожну відсутню ціль." },
    { en = "Physical damage taken reduced by $s2%.\n\n\n\nThunder Blast reduces damage you take by $438591s1% for $438591d.", ua = "Отримана фізична шкода зменшена на $s2%.\n\n\n\nГромовий вибух зменшує отриману тобою шкоду на $438591s1% на $438591d." },
    { en = "Intervening a target grants them a shield for $438598d that absorbs magic damage equal to $s1 times your Armor.", ua = "Втручання дає цілі щит на $438598d, який поглинає магічну шкоду, рівну твоїй броні, помноженій на $s1." },
    { en = "Rip and Rake damage has a chance to cause Bloodseeker Vines to grow on the victim, dealing $439531o1 Bleed damage over $439531d.\n\n\n\n$?a137011[Wild Growth and Regrowth][Wild Growth, Regrowth, and Efflorescence] healing has a chance to cause Symbiotic Blooms to grow on the target, healing for $439530o1 over $439530d.\n\n\n\nMultiple instances of these can overlap.", ua = "Шкода Розриву й Дряпання має шанс спричинити появу Кровожерливих лоз на жертві, що завдають $439531o1 шкоди кровотечею впродовж $439531d.\n\n\n\nЗцілення $?a137011[Дикого росту й Відростання][Дикого росту, Відростання й Цвітіння] має шанс спричинити появу Симбіотичних квітів на цілі, зцілюючи на $439530o1 упродовж $439530d.\n\n\n\nКілька таких ефектів можуть накладатися." },
    { en = "After you cast $?c1[Holy Prism or Divine Toll]?c3[Wake of Ashes][], gain Divine Purpose.\n\n\n\n$?c1[$@spellicon223819 $@spellname223819\n\n$@spellaura223819]?c3[$@spellicon408458 $@spellname408458\n\n$@spellaura408458][]", ua = "Після прочитання $?c1[Святої призми або Божественного подзвону]?c3[Сліду попелу][] ви отримуєте Божественне призначення.\n\n\n\n$?c1[$@spellicon223819 $@spellname223819\n\n$@spellaura223819]?c3[$@spellicon408458 $@spellname408458\n\n$@spellaura408458][]" },
    { en = "Viciously slice into the soul of your enemy, dealing $?a137008[$s1][$s4] Shadowfrost damage and applying Reaper's Mark.\n\n\n\nEach time you deal Shadow or Frost damage, add a stack of Reaper's Mark. After $434765d or reaching $434765u stacks, the mark explodes, dealing $?a137008[$436304s1][$436304s2] damage per stack.\n\n\n\nReaper's Mark travels to an unmarked enemy nearby if the target dies.", ua = "Люто розтинаєте душу ворога, завдаючи $?a137008[$s1][$s4] тіньольодяної шкоди й накладаючи Мітку женця.\n\n\n\nЩоразу, коли ви завдаєте тіньової або льодяної шкоди, додається стак Мітки женця. Після $434765d або після досягнення $434765u стаків мітка вибухає, завдаючи $?a137008[$436304s1][$436304s2] шкоди за кожен стак.\n\n\n\nЯкщо ціль гине, Мітка женця переходить до непоміченого ворога поблизу." },
    { en = "Reaper's Mark sends forth bursts of Shadowfrost energy and back, dealing $?a137008[$435802s1][$435802s2] Shadowfrost damage both ways to all enemies caught in its path.\n\n\n\nWave of Souls critical strikes cause enemies to take $443404s1% increased Shadowfrost damage for $443404d, stacking up to 2 times, and it is always a critical strike on its way back.", ua = "Мітка женця надсилає сплески тіньоморозної енергії вперед і назад, завдаючи $?a137008[$435802s1][$435802s2] тіньоморозної шкоди в обидва боки всім ворогам на своєму шляху.\n\n\n\nКритичні удари Хвилі душ змушують ворогів отримувати на $443404s1% більше тіньоморозної шкоди на $443404d, накопичуючись до 2 разів, і на зворотному шляху вона завжди завдає критичного удару." },
    { en = "Damage and healing while in Cat Form increased by $s1%.\n\n\n\nMoonfire and Sunfire damage increased by $s4%.", ua = "Шкода та зцілення у формі кота збільшені на $s1%.\n\n\n\nШкода Місячного вогню та Сонячного вогню збільшена на $s4%." },
    { en = "Bloodseeker Vines and Symbiotic Blooms last ${$s1/1000} additional sec.\n\n\n\nWhen a target afflicted by Bloodseeker Vines dies, the vines jump to a valid nearby target for their remaining duration.", ua = "Кровожерні ліани та Симбіотичні квіти тривають на ${$s1/1000} сек. довше.\n\n\n\nКоли ціль під дією Кровожерних ліан помирає, ліани перестрибують на підхожу ціль поблизу на час, що лишився." },
    { en = "Each active Bloodseeker Vine increases the damage your abilities deal by 2%.\n\n\n\nEach active Symbiotic Bloom increases the healing of your spells by 2%.", ua = "Кожна активна Кровожерна ліана збільшує шкоду, яку завдають ваші здібності, на 2%.\n\n\n\nКожен активний Симбіотичний квіт збільшує зцілення ваших заклять на 2%." },
    { en = "$?a137011[Tiger's Fury and attacking from Prowl increase][Attacking from Prowl increases] the chance for Shred, Rake, and $?s202028[Brutal Slash][Swipe] to critically strike by $439891s1% for $439891d.\n\n\n\nYour periodic heals have a $s1% increased chance to critically heal.", ua = "$?a137011[Лють тигра й атака зі Скрадання збільшують][Атака зі Скрадання збільшує] шанс критичного удару Шматування, Удару кігтями та $?s202028[Жорстокого розрізу][Замаху] на $439891s1% протягом $439891d.\n\n\n\nВаше періодичне зцілення має на $s1% більший шанс зцілити критично." },
    { en = "Enemies pulled into Ursol's Vortex are rooted in place for ${$s1/1000} sec. Damage may cancel the effect.", ua = "Вороги, затягнуті у «Вихор Урсола», знерухомлені корінням на ${$s1/1000} сек. Шкода може скасувати ефект." },
    { en = "During Barkskin your movement speed is increased by $s1% and every second flowers grow beneath your feet that heal up to $439902s2 nearby injured allies for $439902s1.", ua = "Поки діє «Корошкіра», твоя швидкість руху збільшена на $s1%, і щосекунди під твоїми ногами виростають квіти, що зцілюють до $439902s2 поранених союзників поблизу на $439902s1." },
    { en = "Rip and Ferocious Bite damage increased by $s1%.\n\n\n\nRejuvenation$?a137012[, Efflorescence, and Lifebloom][] healing increased by $s3%.", ua = "Шкоду Розриву й Лютого укусу збільшено на $s1%.\n\n\n\nЗцілення Омолодження$?a137012[, Цвітіння й Життєцвіту][] збільшено на $s3%." },
    { en = "When an enemy deals direct damage to your Anti-Magic Shell, their cast speed is reduced by $440739s1% for $440739d.", ua = "Коли ворог завдає прямої шкоди твоїй «Антимагічній оболонці», швидкість його творення заклять знижується на $440739s1% на $440739d." },
    { en = "$?a137008[Blood Boil deals $s3% increased damage][Rime empowered Howling Blast deals $s4% increased damage to its main target], and is now Shadowfrost.\n\n\n\nShadowfrost damage applies 2 stacks to Reaper's Mark and 4 stacks when it is a critical strike.", ua = "$?a137008[Кипіння крові завдає на $s3% більше шкоди][Підсилений Памороззю Виючий вибух завдає на $s4% більше шкоди своїй основній цілі] і тепер є тіньоморозом.\n\n\n\nШкода тіньоморозом накладає 2 стопки Мітки женця, а при критичному ударі — 4 стопки." },
    { en = "Shadow damage dealt by your spells and abilities is increased by $s3% and your Shadow spells gain $s1% more critical strike chance from all sources.", ua = "Шкода від тіні, яку завдають твої закляття та здібності, збільшена на $s3%, а твої закляття тіні отримують на $s1% більше шансу критичного удару з усіх джерел." },
    { en = "Spending Soul Shards on damaging spells will further corrupt enemies affected by your Wither, increasing its stack count by $s1.\n\n\n\nEach time Wither gains a stack it has a chance to collapse, consuming a stack every $445731t1 sec to deal $445736s1 Shadowflame damage to its host until 1 stack remains.", ua = "Витрата Уламків душі на закляття шкоди ще дужче скверняє ворогів, уражених вашим Згасанням, збільшуючи кількість його зарядів на $s1.\n\n\n\nЩоразу, коли Згасання отримує заряд, воно має шанс обвалитися, поглинаючи один заряд кожні $445731t1 сек і завдаючи $445736s1 шкоди тіньовим полум'ям своєму носієві, доки не лишиться 1 заряд." },
    { en = "Fire damage dealt by your spells and abilities is increased by $s1% and your Fire spells gain $s4% more critical strike chance from all sources.", ua = "Шкода від вогню, завдана твоїми закляттями і здібностями, збільшена на $s1%, а твої вогняні закляття отримують на $s4% більше шансу критичного удару з усіх джерел." },
    { en = "Critical strike damage dealt by Wither is increased by $s1%. \n\n\n\nWither has a chance to gain a stack when it critically strikes. Stacks gained this way do not activate Blackened Soul.", ua = "Шкода від критичних ударів Згасання збільшена на $s1%. \n\n\n\nЗгасання має шанс отримати заряд, коли завдає критичного удару. Заряди, отримані в такий спосіб, не активують Почорнілу душу." },
    { en = "$?s980[Agony damage increased by $s1%.][Wither damage increased by $s2%.]\n\n\n\nBlackened Soul deals $s3% increased damage per stack of Wither.", ua = "$?s980[Шкода від Агонії збільшена на $s1%.][Шкода від Усихання збільшена на $s2%.]\n\n\n\nПочорніла душа завдає на $s3% більше шкоди за кожен заряд Усихання." },
    { en = "Wither deals $s1% increased periodic damage but its duration is $s2% shorter.", ua = "«В'янення» завдає на $s1% більше періодичної шкоди, але його тривалість на $s2% коротша." },
    { en = "Wither damage increased $s1%. When Wither gains a stack from Blackened Soul, it has a chance to gain an additional stack.", ua = "Шкода «В'янення» збільшена на $s1%. Коли «В'янення» отримує заряд від «Почорнілої душі», воно має шанс отримати додатковий заряд." },
    { en = "After Wither reaches $s1 stacks or when its host reaches $s2% health, Wither deals $445736s1 Shadowflame damage to its host every $445731t1 sec until 1 stack remains.\n\n\n\nWhen Blackened Soul deals damage, you have a chance to gain $?s137046[$s3 stacks of Flashpoint][Shard Instability].", ua = "Коли Усихання сягає $s1 зарядів або коли його носій сягає $s2% здоров'я, Усихання завдає носієві $445736s1 тіньовогняної шкоди кожні $445731t1 сек, доки не залишиться 1 заряд.\n\n\n\nКоли Почорніла душа завдає шкоди, ви маєте шанс отримати $?s137046[$s3 заряди(ів) Спалаху][Нестабільність уламків]." },
    { en = "Curse of Weakness is empowered and transforms into Curse of the Satyr.\n\n\n\n$@spellicon442804 $@spellname442804\n\n$@spelldesc442804", ua = "Прокляття слабкості посилюється й перетворюється на Прокляття сатира.\n\n\n\n$@spellicon442804 $@spellname442804\n\n$@spelldesc442804" },
    { en = "While Unending Resolve is active, enemies within $449587a1 yds are affected by Curse of Tongues and Curse of Weakness at $s1% effectiveness.", ua = "Поки діє «Незламна рішучість», вороги в радіусі $449587a1 м потрапляють під дію «Прокляття язиків» і «Прокляття слабкості» з ефективністю $s1%." },
    { en = "Dark Pact heals you for $108416s5 every $108416t5 sec while active.", ua = "«Темний пакт», поки діє, зцілює тебе на $108416s5 кожні $108416t5 сек." },
    { en = "Sacrifice $s1% of your maximum health. Soul Leech now absorbs an additional $s2% of your maximum health.", ua = "Жертвує $s1% твого максимального здоров'я. «Висмоктування душі» тепер поглинає додатково $s2% твого максимального здоров'я." },
    { en = "Your Regrowth's healing to yourself is increased by $s1%.", ua = "Твоє «Відростання» зцілює тебе самого на $s1% сильніше." },
    { en = "When Bloodseeker Vines or Symbiotic Blooms grow, they have a $s1% chance to cause another growth of the same type to immediately grow on a valid nearby target.", ua = "Коли виростають «Кровошукацькі лози» чи «Симбіотичні квіти», є $s1% шансу, що на придатній цілі поблизу одразу виросте ще один паросток того ж типу." },
    { en = "$?a137011[When you gain or lose Tiger's Fury, your next single-target melee ability causes a Bloodseeker Vine to grow on the target for ${$s1/1000} sec.][Casting Swiftmend or Wild Growth causes a Symbiotic Bloom to grow on a target for ${$s2/1000} sec.]", ua = "$?a137011[Коли ти отримуєш або втрачаєш Лють тигра, твоя наступна одноцільова здібність ближнього бою вирощує на цілі Кровошукацьку лозу на ${$s1/1000} сек.][Прочитання Швидкого зцілення або Дикого росту вирощує на цілі Симбіотичний цвіт на ${$s2/1000} сек.]" },
    { en = "Bloodseeker Vines increase the damage your abilities deal to affected enemies by $s1%.\n\n\n\nSymbiotic Blooms increase the healing your spells do to affected targets by $s2%.", ua = "Кровожерні ліани збільшують шкоду, яку ваші здібності завдають враженим ворогам, на $s1%.\n\n\n\nСимбіотичні квіти збільшують зцілення, яке ваші закляття дають враженим цілям, на $s2%." },
    { en = "When Bloodseeker Vines expire or you use Ferocious Bite on their target they explode in thorns, dealing $440122s1 physical damage to nearby enemies. Damage reduced above 5 targets.\n\n\n\nWhen Symbiotic Blooms expire or you cast Rejuvenation on their target flowers grow around their target, healing them and up to $440121s2 nearby allies for $440121s1.", ua = "Коли Лози-кровошукачі завершуються або ви застосовуєте Лютий укус на їхню ціль, вони вибухають шипами, завдаючи $440122s1 фізичної шкоди ворогам поблизу. Шкода зменшується понад 5 цілей.\n\n\n\nКоли Симбіотичні квіти завершуються або ви застосовуєте Омолодження на їхню ціль, навколо їхньої цілі виростають квіти, зцілюючи її та до $440121s2 союзників поблизу на $440121s1." },
    { en = "Enrage increases your mastery by $184362s5% and your Leech by $184362s6%.", ua = "Розлюченість збільшує твою майстерність на $184362s5%, а висмоктування — на $184362s6%." },
    { en = "Each Rune spent reduces the magic damage you take by ${$abs($440290s1/10)}.1% and each Rune generated reduces the physical damage you take by ${$abs($440289s1/10)}.1% for $440289d, up to $440290u times.", ua = "Кожна витрачена руна зменшує отримувану тобою магічну шкоду на ${$abs($440290s1/10)}.1%, а кожна створена руна зменшує отримувану фізичну шкоду на ${$abs($440289s1/10)}.1% на $440289d, до $440290u разів." },
    { en = "When you suffer a damaging effect equal to $s1% of your maximum health, you instantly cast Death Pact at $s3% effectiveness. May only occur every $s2 min.\n\n\n\nWhen a Reaper's Mark explodes, the cooldowns of this effect and Death Pact are reduced by $s4 sec.", ua = "Коли ви зазнаєте шкідливого ефекту, рівного $s1% вашого максимального здоров'я, ви миттєво творите Смертельний пакт з $s3% ефективністю. Може статися лише раз на $s2 хв.\n\n\n\nКоли Мітка женця вибухає, перезарядження цього ефекту й Смертельного пакту скорочується на $s4 сек." },
    { en = "$?a137032[Power Word: Shield absorbs $s2% additional damage.\n\n\n\nAll damage dealt by Penance, Smite and Holy Nova increased by $s3%.][Increases the healing done by Prayer of Mending by $s1%.\n\n\n\nAll damage dealt by Smite, Holy Fire and Holy Nova increased by $s4%.]", ua = "$?a137032[Слово сили: Щит поглинає на $s2% більше шкоди.\n\n\n\nУся шкода від Покути, Удару й Священної нови збільшена на $s3%.][Збільшує зцілення від Молитви зцілення на $s1%.\n\n\n\nУся шкода від Удару, Священного вогню й Священної нови збільшена на $s4%.]" },
    { en = "For $458650d after casting Leap of Faith you may cast it a second time for free, ignoring its cooldown.", ua = "Протягом $458650d після прочитання «Стрибка віри» можеш створити його вдруге безкоштовно, ігноруючи перезарядження." },
    { en = "Your Angelic Feathers increase movement speed by an additional $s2%.\n\n\n\nWhen an ally walks through your Angelic Feather, you are also granted $s1% of its effect.", ua = "Ваші «Янгольські пера» збільшують швидкість руху додатково на $s2%.\n\n\n\nКоли союзник проходить крізь ваше «Янгольське перо», ви також отримуєте $s1% його ефекту." },
    { en = "$?a137032[Increases the duration of Atonement by ${$s1/1000} sec.][Increases the duration of your Renew by $s2%.]", ua = "$?a137032[Збільшує тривалість Спокути на ${$s1/1000} с.][Збільшує тривалість вашого Оновлення на $s2%.]" },
    { en = "Reduces the cooldown of $?a137032[Power Word: Shield by ${$s2/-1000}.1 sec.][Prayer of Mending by ${$s1/-1000}.1 sec.]", ua = "Зменшує перезарядження $?a137032[«Слова сили: Щит» на ${$s2/-1000}.1 сек.][«Молитви зцілення» на ${$s1/-1000}.1 сек.]" },
    { en = "$?a137032[Pain Suppression reduces damage taken by an additional $s1%.][Guardian Spirit lasts an additional ${$s2/1000} sec.]", ua = "$?a137032[Придушення болю додатково зменшує отриману шкоду на $s1%.][Дух-охоронець триває додатково ${$s2/1000} с.]" },
    { en = "$?a137031[An additional $s1 stacks of Prayer of Mending is placed on a second ally within $A2 yards when casting Prayer of Mending.][$s3 additional Penance bolts are fired at an enemy within $A2 yards when healing an ally with Penance, or fired at an ally within $A2 yards when damaging an enemy with Penance.]", ua = "$?a137031[Додаткові $s1 заряди Молитви зцілення накладаються на другого союзника в межах $A2 метрів під час прочитання Молитви зцілення.][$s3 додаткові стріли Покаяння випускаються у ворога в межах $A2 метрів, коли ви зцілюєте союзника Покаянням, або випускаються в союзника в межах $A2 метрів, коли ви завдаєте шкоди ворогу Покаянням.]" },
    { en = "$?a137032[Power Word: Shield casts apply $s1 $Lstack:stacks; of Prayer of Mending to your target.\n\n\n\n$@spellicon33076 $@spellname33076\n\n$@spelldesc33076][Casting Prayer of Mending applies Power Word: Shield to your target.\n\n\n\n$@spellicon1246768 $@spellname1246768\n\n$@spelldesc1246768]", ua = "$?a137032[Застосування Слова сили: Щит накладає на вашу ціль $s1 $Lзаряд:заряди:зарядів; Молитви зцілення.\n\n\n\n$@spellicon33076 $@spellname33076\n\n$@spelldesc33076][Застосування Молитви зцілення накладає на вашу ціль Слово сили: Щит.\n\n\n\n$@spellicon1246768 $@spellname1246768\n\n$@spelldesc1246768]" },
    { en = "Shockwave also knocks enemies into the air and its cooldown is reduced by ${$s1/-1000} sec.", ua = "«Ударна хвиля» також підкидає ворогів у повітря, а її перезарядження скорочено на ${$s1/-1000} сек." },
    { en = "When your health is brought below 35%, you gain a Second Wind, healing you for ${$441387s1*$441387t1*$441387d}% of your max health over $441387d.\n\n\n\nThis effect cannot occur more than once every $proccooldown sec.", ua = "Коли твоє здоров'я падає нижче 35%, ти отримуєш Друге дихання, що зцілює тебе на ${$441387s1*$441387t1*$441387d}% максимального здоров'я протягом $441387d.\n\n\n\nЦей ефект не може спрацьовувати частіше, ніж раз на $proccooldown сек." },
    { en = "Colossal Might increases the damage of your Rend and Deep Wounds by $440989s2% per stack.", ua = "Колосальна міць збільшує шкоду твоїх Розриву та Глибоких ран на $440989s2% за кожен заряд." },
    { en = "$?a137036[Sinister Strike]?s200758[Gloomblade][Backstab] and $?a137036[Ambush][Shadowstrike] now also strike with an Unseen Blade dealing $441144s1 damage. Targets struck are Fazed for $441224d.\n\n\n\nFazed enemies take $441224s1% more damage from you and cannot parry your attacks.\n\n\n\nThis effect may occur once every $459485d.", ua = "$?a137036[Лиховісний удар]?s200758[Похмурий клинок][Удар у спину] та $?a137036[Засідка][Тіньовий удар] тепер також вражають Невидимим клинком, завдаючи $441144s1 шкоди. Уражені цілі Збентежені на $441224d.\n\n\n\nЗбентежені вороги отримують від вас на $441224s1% більше шкоди й не можуть парирувати ваші атаки.\n\n\n\nЦей ефект може спрацьовувати раз на $459485d." },
    { en = "$?s403631[Breath of Eons][Deep Breath] causes enemies to take $s2% increased damage from Bombardments and Essence abilities for $441172d.$?c1[\n\n\n\nThe duration of this effect is extended when Deep Breath is cast multiple times.][]", ua = "$?s403631[Подих еонів][Глибокий подих] змушує ворогів отримувати на $s2% більше шкоди від Бомбардувань та здібностей есенції протягом $441172d.$?c1[\n\n\n\nТривалість цього ефекту подовжується, коли Глибокий подих застосовується кілька разів.][]" },
    { en = "Obsidian Scales reduces damage taken by an additional ${$s1/-1}%.", ua = "«Обсидіанова луска» зменшує отримувану шкоду додатково на ${$s1/-1}%." },
    { en = "Knocking enemies up or backwards reduces their damage done to you by $s1% for $441201d.", ua = "Підкидання чи відкидання ворогів зменшує шкоду, яку вони завдають тобі, на $s1% протягом $441201d." },
    { en = "Bombardments reduce the cooldown of $?c1[Deep Breath by ${$s1/1000}.1 sec for each target struck, up to ${$s2/1000}.1 sec.][Breath of Eons by ${$s3/1000}.1 sec for each target struck, up to ${$s4/1000}.1 sec.]", ua = "Бомбардування зменшують час перезарядження $?c1[Глибокого вдиху на ${$s1/1000}.1 с за кожну вражену ціль, до ${$s2/1000}.1 с.][Подиху еонів на ${$s3/1000}.1 с за кожну вражену ціль, до ${$s4/1000}.1 с.]" },
    { en = "Essence abilities extend Bombardments by $s1 sec.", ua = "Здібності есенції подовжують Бомбардування на $s1 сек." },
    { en = "Bombardments have a chance to generate Essence Burst.", ua = "Бомбардування мають шанс створити Вибух есенції." },
    { en = "Entering combat grants a charge of Burnout, causing your next Living Flame to cast instantly.", ua = "Вступ у бій дарує заряд «Вигорання», завдяки чому твоє наступне «Живе полум'я» твориться миттєво." },
    { en = "For each second you are in combat, Azure Strike, Living Flame, and $?c1[Disintegrate][Eruption] deal $s1% increased damage, up to $s2%.", ua = "За кожну секунду перебування в бою Блакитний удар, Жива полум'я та $?c1[Розпад][Виверження] завдають на $s1% більше шкоди, до $s2%." },
    { en = "You take $s1% reduced damage from Fazed targets.", ua = "Ти отримуєш на $s1% менше шкоди від спантеличених цілей." },
    { en = "Feint reduces damage taken from area-of-effect attacks by an additional $s1%", ua = "Фінт додатково зменшує шкоду від площинних атак на $s1%" },
    { en = "While Hovering, damage taken from area of effect attacks is reduced by ${$s1/-1}%.", ua = "Під час Ширяння шкоду від атак площинної дії зменшено на ${$s1/-1}%." },
    { en = "$?s403631[Breath of Eons][Deep Breath] resets a charge of Hover.", ua = "$?s403631[Подих еонів][Глибокий подих] скидає заряд Ширяння." },
    { en = "$?a137036[Killing Spree][Secret Technique] applies Fazed to any targets struck.", ua = "$?a137036[Вбивча навала][Таємна техніка] накладає Збентеження на будь-яку уражену ціль." },
    { en = "Attacks that generate combo points deal $s1% increased critical strike damage to Fazed targets.", ua = "Атаки, що породжують очки комбо, завдають спантеличеним цілям на $s1% більше шкоди критичними ударами." },
    { en = "$?a137036[Killing Spree][Secret Technique] has $s1% reduced cooldown and allows your next $s2 strikes of Unseen Blade to ignore its cooldown.", ua = "$?a137036[Вбивча навала][Таємна техніка] має на $s1% зменшене перезарядження й дозволяє вашим наступним $s2 ударам Невидимого клинка ігнорувати його перезарядження." },
    { en = "Unseen Blade and $?a137036[Killing Spree][Secret Technique] increase the damage of your finishing moves by $441326s1% for $441326d. Max $441326u stacks.", ua = "Незримий клинок і $?a137036[Серія вбивств][Таємна техніка] збільшують шкоду ваших добивань на $441326s1% протягом $441326d. Максимум $441326u зарядів." },
    { en = "Slice and Dice grants $s1% additional attack speed and gives your auto-attacks a chance to refresh your opportunity to strike with Unseen Blade.", ua = "Шаткування дає додатково $s1% швидкості атаки, а твої автоатаки отримують шанс поновити можливість ударити Невидимим лезом." },
    { en = "Taking damage from an area-of-effect attack while Feint is active or dodging while Evasion is active refreshes your opportunity to strike with Unseen Blade.\n\n\n\nThis effect may only occur once every $proccooldown sec.", ua = "Отримання шкоди від атаки по площі, доки активна «Підробка», або ухиляння, доки активне «Уникання», оновлює вашу можливість завдати удар «Невидимим клинком».\n\n\n\nЦей ефект може спрацьовувати лише раз на $proccooldown сек." },
    { en = "$?a137036[Blade Flurry damage is increased by $s1%][Your auto-attacks, Unseen Blade, and Coup de Grace also strike up to $s2 nearby enemies for $s3% of normal damage] while Flawless Form is active.", ua = "$?a137036[Шкода Шквалу клинків збільшена на $s1%][Ваші автоатаки, Невидимий клинок і Удар милосердя також уражають до $s2 ворогів поблизу, завдаючи $s3% звичайної шкоди], поки активна Бездоганна форма." },
    { en = "After Reaper's Mark explodes, your next $s3 $?a137008[$LMarrowrend:Marrowrends;][$LObliterate:Obliterates; or $LFrostscythe:Frostscythes;] cost $s4 $LRune:Runes; and summon $s1 $Lscythe:scythes; to strike your enemies.\n\n\n\nThe first scythe strikes your target for $?a137008[$441424s1][$441424s2] Shadowfrost damage $?c2[and has a $s6% chance to grant Killing Machine,][and] the second scythe strikes all enemies around your target for $?a137008[$441426s1][$441426s2] Shadowfrost damage$?(a441894&a137008)[ and applies Blood Plague]?(a441894&$a137006)[ and applies Frost Fever][]. Deals reduced damage beyond $s5 targets.", ua = "Після вибуху Мітки женця ваші наступні $s3 $?a137008[$LКостолам:застосування Костолама;][$LВинищення:застосування Винищення; або $LМорозна коса:застосування Морозної коси;] коштують $s4 $LРуну:Руни; і прикликають $s1 $Lкосу:коси; разити ваших ворогів.\n\n\n\nПерша коса вражає вашу ціль на $?a137008[$441424s1][$441424s2] тіньоморозної шкоди $?c2[і має $s6% шансу надати Машину вбивства,][та] друга коса вражає всіх ворогів навколо вашої цілі на $?a137008[$441426s1][$441426s2] тіньоморозної шкоди$?(a441894&a137008)[ та накладає Кров'яну пошесть]?(a441894&$a137006)[ та накладає Морозну гарячку][]. Завдає зменшеної шкоди понад $s5 цілей." },
    { en = "Finishing moves have $s1% increased chance to critically strike Fazed targets.", ua = "Завершальні прийоми мають на $s1% більший шанс критично вдарити спантеличені цілі." },
    { en = "Tricks of the Trade's threat redirect duration is increased to $m1 $Lhour:min;.", ua = "Тривалість перенаправлення загрози від Хитрощів ремесла збільшено до $m1 $Lгодини:хв;." },
    { en = "Blind and Shroud of Concealment have $s1% reduced cooldown.\n\n\n\nPick Pocket and Sap have $s2 yd increased range.", ua = "Перезарядження «Засліплення» і «Покрову приховання» зменшено на $s1%.\n\n\n\nДальність «Кишенькової крадіжки» і «Оглушення» збільшено на $s2 м." },
    { en = "After $441786s1 strikes with Unseen Blade, your next $?a137036[Dispatch][Eviscerate] will be performed as a Coup de Grace, functioning as if it had consumed $s3 additional combo points, and granting you $s2 stacks of Flawless Form.", ua = "Після $441786s1 ударів Незримим клинком ваше наступне $?a137036[Усунення][Потрошіння] виконається як Удар милосердя, діючи так, ніби спожило $s3 додаткових комбо-очок, і надасть вам $s2 стаків Бездоганної форми." },
    { en = "Activating $?a137036[Adrenaline Rush][Shadow Blades] creates a cloud of smoke for $441587d, allowing attacks from within the cloud to apply Fazed, stacking up to $441640m2 additional $Ltime:times;.\n\n\n\nEffect persists for $?a137036[${$s1/1000}][${$s2/1000}] sec after leaving the cloud.", ua = "Активація $?a137036[Сплеску адреналіну][Тіньових клинків] створює хмару диму на $441587d, дозволяючи атакам зсередини хмари накладати Збентеження, що накопичується до $441640m2 $Lдодаткового разу:додаткових разів;.\n\n\n\nЕфект зберігається ще $?a137036[${$s1/1000}][${$s2/1000}] сек. після виходу з хмари." },
    { en = "Your auto-attacks have a chance to make your next $?a137010[Maul][Ferocious Bite] become Ravage.\n\n\n\n$?a137010[$@spellicon441605|cFFFFFFFF$@spellname441605|r\n\n$@spelldesc441605]$?a137011[$@spellicon441591|cFFFFFFFF$@spellname441591|r\n\n$@spelldesc441591]", ua = "Ваші автоатаки мають шанс перетворити ваше наступне $?a137010[Калічення][Лютий укус] на Спустошення.\n\n\n\n$?a137010[$@spellicon441605|cFFFFFFFF$@spellname441605|r\n\n$@spelldesc441605]$?a137011[$@spellicon441591|cFFFFFFFF$@spellname441591|r\n\n$@spelldesc441591]" },
    { en = "Your maximum Energy and Rage are increased by $s1.\n\n\n\nFrenzied Regeneration also increases your maximum health by $s3%.", ua = "Ваша максимальна енергія та лють збільшуються на $s1.\n\n\n\nШалена регенерація також збільшує ваше максимальне здоров'я на $s3%." },
    { en = "Ironfur and Frenzied Regeneration persist in Cat Form.$?!c3[\n\n\n\nWhen transforming from Bear to Cat Form, you retain $441685s1% of your Bear Form armor and health for $441685d.][]\n\n\n\nFor $441686d after entering Bear Form, you heal for $441686s1% of damage taken over $441688d.", ua = "Залізне хутро й Несамовита регенерація зберігаються в котячій подобі.$?!c3[\n\n\n\nПереходячи з ведмежої в котячу подобу, ви зберігаєте $441685s1% броні та здоров'я ведмежої подоби на $441685d.][]\n\n\n\nУпродовж $441686d після переходу у ведмежу подобу ви зцілюєтеся на $441686s1% від отриманої шкоди впродовж $441688d." },
    { en = "Frenzied Regeneration can be cast in Cat Form for $s2 Energy.\n\n\n\nBear Form reduces magic damage you take by ${-$s4}%.\n\n\n\nShred and $?s202028[Brutal Slash][Swipe] damage increased by $s5%. Mangle damage increased by $s6%.", ua = "Несамовиту регенерацію можна застосувати в котячій подобі за $s2 енергії.\n\n\n\nВедмежа подоба зменшує магічну шкоду, якої ви зазнаєте, на ${-$s4}%.\n\n\n\nШкоду Шматування та $?s202028[Жорстокого розтину][Розмаху] збільшено на $s5%. Шкоду Шматування збільшено на $s6%." },
    { en = "$?s202028[Shred and Brutal Slash]?a137011[Shred and Swipe][]$?a137011[ grant Ursine Potential. When you have $441695s1 stacks, the next time you transform into Bear Form, your next Mangle deals $441698s1% increased damage or your next Swipe deals $441698s2% increased damage. Either generates ${$442562s1/10} extra Rage.][Mangle grants Feline Potential. When you have $441701s1 stacks, the next time you transform into Cat Form, gain $441704s1 combo points and your next Ferocious Bite or Rip deals $441702s1% increased damage for its full duration.]", ua = "$?s202028[«Шматування» та «Брутальний розтин»]?a137011[«Шматування» та «Помах лапи»][]$?a137011[ дарують «Ведмежий потенціал». Коли в тебе $441695s1 зарядів, наступного разу, коли ти перекинешся в «Подобу ведмедя», твоє наступне «Калічення» завдасть на $441698s1% більше шкоди або твій наступний «Помах лапи» завдасть на $441698s2% більше шкоди. Будь-який з них породжує ${$442562s1/10} додаткової люті.][«Калічення» дарує «Котячий потенціал». Коли в тебе $441701s1 зарядів, наступного разу, коли ти перекинешся в «Котячу подобу», ти отримаєш $441704s1 очок комбо, а твій наступний «Лютий укус» чи «Розрив» завдасть на $441702s1% більше шкоди впродовж усієї своєї тривалості.]" },
    { en = "Black spells deal $s1% increased damage.", ua = "Чорні закляття завдають на $s1% більше шкоди." },
    { en = "Ravage also inflicts a Bleed that causes $?a137011[$441812s1][$451177s1] damage over $441812d and saps its victims' strength, reducing damage they deal to you by $?a137011[$441812s2][$451177s2]%.\n\n\n\nDreadful Wound is not affected by Circle of Life and Death. $?a137011[If a Dreadful Wound benefiting from Tiger's Fury is re-applied, the new Dreadful Wound deals damage as if Tiger's Fury was active.][]", ua = "Спустошення також спричиняє кровотечу, що завдає $?a137011[$441812s1][$451177s1] шкоди впродовж $441812d і висотує силу жертв, зменшуючи шкоду, яку вони завдають вам, на $?a137011[$441812s2][$451177s2]%.\n\n\n\nНа Страшну рану не впливає Коло життя і смерті. $?a137011[Якщо Страшну рану, що використовує Лють тигра, накладено повторно, нова Страшна рана завдає шкоди так, наче Лють тигра була активна.][]" },
    { en = "Ravage increases your auto-attack speed by $441817s1% for $441817d.", ua = "«Спустошення» прискорює твої автоатаки на $441817s1% на $441817d." },
    { en = "Ravage increases your Agility by $441825s1% and the armor granted by Ironfur by $441825s2% for $441825d.\n\n\n\nYour first $?a137011[Tiger's Fury][Mangle] after entering combat makes your next $?a137011[Ferocious Bite][Maul] become Ravage.", ua = "Спустошення збільшує вашу Спритність на $441825s1%, а броню від Залізного хутра — на $441825s2% на $441825d.\n\n\n\nВаше перше $?a137011[застосування Люті тигра][Шматування] після входу в бій перетворює ваш наступний $?a137011[Лютий укус][Замах] на Спустошення." },
    { en = "Every $?a137010[Maul, Raze, Mangle,  Thrash, or Swipe]$?a137011[attack with an Energy cost that] you cast extends the duration of your Dreadful Wounds by $?a137010[${$s1/1000}.1][${$s2/1000}.1] sec, up to $s3 additional sec.", ua = "Кожне застосування $?a137010[«Трощення», «Руйнації», «Калічення», «Шмагання» чи «Помаху лапою»]$?a137011[атаки, що коштує енергії,] продовжує дію твоїх «Жаских ран» на $?a137010[${$s1/1000}.1][${$s2/1000}.1] с, загалом до $s3 додаткових с." },
    { en = "During Berserk, $?c3[Mangle, Thrash][Shred], and $?s202028[Brutal Slash][Swipe] have a $s1% chance to make your next $?a137010[Maul][Ferocious Bite] become Ravage.", ua = "Під час «Берсерка» $?c3[«Калічення», «Шмагання»][«Шматування»] та $?s202028[«Жорстокий розтин»][«Помах лапою»] мають $s1% шансу перетворити наступне застосування $?a137010[«Трощення»][«Лютого укусу»] на «Спустошення»." },
    { en = "$?a137011[Ferocious Bite and Rampant Ferocity damage increased by $s1% and Primal Wrath's direct damage increased by $s2%.][Maul and Raze damage increased by $s3%.]", ua = "$?a137011[Шкода Лютого укусу та Несамовитої лютості збільшена на $s1%, а пряма шкода Первісного гніву — на $s2%.][Шкода Трощення та Нищення збільшена на $s3%.]" },
    { en = "Stampeding Roar's duration is increased by $s1%.", ua = "Тривалість Навального реву збільшено на $s1%." },
    { en = "$?c2[Shred, Swipe, and Rake damage increased by $s1% and their critical strike chance is increased by $s3%.][Mangle damage increased by $s4% and its critical strike chance is increased by $s5%.]\n\n\n\n$?c3[Mangle heals you for $458724s1% of maximum health.][]", ua = "$?c2[Шкода Шматування, Замаху та Удару кігтями збільшена на $s1%, а їхній шанс критичного удару збільшено на $s3%.][Шкода Роздирання збільшена на $s4%, а його шанс критичного удару збільшено на $s5%.]\n\n\n\n$?c3[Роздирання зцілює вас на $458724s1% максимального здоров'я.][]" },
    { en = "$?c2[Damage dealt by Chomp and ][]$?(c2&!s1243807)[Feral Frenzy]?c2[Frantic Frenzy][]$?c2[ increased by $s2%][The cooldown of Sundering Roar is reduced by ${$s1/-1000} sec].", ua = "$?c2[Шкоду від «Укусу» та ][]$?(c2&!s1243807)[«Дикого шалу»]?c2[«Несамовитого шалу»][]$?c2[ збільшено на $s2%][Перезарядження «Розривного рику» зменшено на ${$s1/-1000} сек]." },
    { en = "$?a137008[Blood Plague][Frost Fever] deals its damage $?a137008[$s5][$s6]% faster, and the second scythe of Exterminate applies $?a137008[Blood Plague][Frost Fever].", ua = "$?a137008[Кривава чума][Морозлихоманка] завдає своєї шкоди на $?a137008[$s5][$s6]% швидше, і друга коса Винищення накладає $?a137008[Криваву чуму][Морозлихоманку]." },
    { en = "Consuming $?a212612[$s1][$s2] Soul Fragments or casting $?a212612[The Hunt][Sigil of Spite] converts your next Throw Glaive into Reaver's Glaive.\n\n\n\n$@spellicon442294 $@spellname442294: \n\n$@spelldesc442294", ua = "Споживання $?a212612[$s1][$s2] фрагментів душі або застосування $?a212612[Полювання][Знаку зневаги] перетворює ваше наступне Метання глефи на Глефу плюндрувальника.\n\n\n\n$@spellicon442294 $@spellname442294: \n\n$@spelldesc442294" },
    { en = "$?a212612[Chaos Strike][Soul Cleave] deals $s1% increased damage.", ua = "$?a212612[Удар хаосу][Розтин душі] завдає на $s1% більше шкоди." },
    { en = "Reaver's Glaive generates $s1 Fury.", ua = "«Глефа спустошувача» генерує $s1 од. люті." },
    { en = "Consuming a Soul Fragment causes your next $?a212612[Chaos Strike]?s263642[Fracture][Shear] to deal $442507s1 additional Physical damage.$?a212612[\n\n\n\nFelblade consumes up to $s2 nearby Soul Fragments.][]", ua = "Споживання фрагмента душі змушує ваш наступний $?a212612[Удар хаосу]?s263642[Перелом][Зріз] завдати $442507s1 додаткової фізичної шкоди.$?a212612[\n\n\n\nКлинок Скверни споживає до $s2 фрагментів душі поблизу.][]" },
    { en = "When enhanced by Reaver's Glaive, $?a212612[Chaos Strike]?s263642[Fracture][Shear] applies Reaver's Mark, which causes the target to take $442624s1% increased damage for $442624d. Max $442624u stacks.\n\n\n\nApplies $m2 additional $Lstack:stacks; of Reaver's Mark If cast after $?a212612[Blade Dance][Soul Cleave].", ua = "Коли підсилено Глефою Розривача, $?a212612[Удар Хаосу]?s263642[Перелом][Розтин] накладає Мітку Розривача, через що ціль дістає на $442624s1% більше шкоди протягом $442624d. Максимум $442624u стаків.\n\n\n\nНакладає $m2 додаткових $Lстак:стаки; Мітки Розривача, якщо застосовано після $?a212612[Танцю клинків][Розсікання душі]." },
    { en = "The second enhanced ability in a pattern shatters an additional Soul Fragment.", ua = "Друга підсилена здібність у послідовності розбиває додатковий фрагмент душі." },
    { en = "After consuming both enhancements, gain Thrill of the Fight, increasing the damage of your next Reaver's Glaive by $442695s1% and increasing Haste by $442688s1% for $442688d.", ua = "Після використання обох підсилень ти отримуєш «Азарт бою», що збільшує шкоду твоєї наступної «Глефи спустошувача» на $442695s1% та поспіх на $442688s1% протягом $442688d." },
    { en = "Teachings of the Monastery has a $s1% chance to refund a charge when consumed. \n\n\n\nThe damage of Tiger Palm is increased by $s2%.", ua = "Вчення монастиря мають $s1% шансу повернути заряд при споживанні. \n\n\n\nШкода Тигрової долоні збільшується на $s2%." },
    { en = "Felblade surrounds you with a Blade Ward, reducing damage taken by $442715s1% for $442715d.", ua = "«Клинок Скверни» оточує тебе Оберегом клинків, що зменшує отриману шкоду на $442715s1% на $442715d." },
    { en = "When enhanced by Reaver's Glaive, $?a212612[Blade Dance][Soul Cleave] casts $s2 additional glaive slashes to nearby targets. Deals reduced damage beyond $444806s2 targets.\n\n\n\nIf cast after $?a212612[Chaos Strike]?s263642[Fracture][Shear], cast $?a1236360[${($s2*($s1/100+1))+$1236360s1}][${$s2*($s1/100+1)}] slashes instead.", ua = "Коли підсилено Глефою Розривача, $?a212612[Танець клинків][Розсікання душі] завдає $s2 додаткових розрізів глефою ближнім цілям. Завдає зменшеної шкоди понад $444806s2 цілей.\n\n\n\nЯкщо застосовано після $?a212612[Удару Хаосу]?s263642[Перелому][Розтину], завдає натомість $?a1236360[${($s2*($s1/100+1))+$1236360s1}][${$s2*($s1/100+1)}] розрізів." },
    { en = "$?c2[Healing increased by $322118s8% while Chi-Ji, the Red Crane or Yu'lon, the Jade Serpent is active.]?c3[Damage increased by $123904s4% while Xuen, the White Tiger is active.][]", ua = "$?c2[Зцілення збільшується на $322118s8%, поки активний Чі-Цзі, Червоний журавель, або Ю'лон, Нефритовий змій.]?c3[Шкода збільшується на $123904s4%, поки активний Сюень, Білий тигр.][]" },
    { en = "Each Soul Fragment you consume shields you for an additional $s1% of the amount healed.", ua = "Кожен поглинутий фрагмент душі додатково дає тобі щит на $s1% від обсягу зцілення." },
    { en = "$?c2[The healing of Enveloping Mist, Vivify, and Sheilun's Gift is increased by $s1%.]?c3[Fists of Fury and Spinning Crane Kick deal $s2% more damage.][]", ua = "$?c2[Зцілення від Огорнення туманом, Оживлення та Дару Шейлуна збільшено на $s1%.]?c3[Кулаки люті та Обертовий удар журавля завдають на $s2% більше шкоди.][]" },
    { en = "Fortifying Brew grants you an absorb shield for $442749s2% of your maximum health.", ua = "«Зміцнювальне вариво» дає тобі щит, що поглинає шкоду, в розмірі $442749s2% твого максимального здоров'я." },
    { en = "Expose weaknesses in the target of your $@spellname442624, causing your Physical damage to any enemy to also deal $s1% of the damage dealt to your marked target as Chaos, and sometimes shatter a Soul Fragment.", ua = "Викриває слабкості цілі вашого $@spellname442624, через що ваша фізична шкода будь-якому ворогу також завдає $s1% завданої шкоди вашій позначеній цілі як шкоду хаосом, а іноді розколює фрагмент душі." },
    { en = "$?c2[The August Celestials empower you, causing you to radiate ${$443039s1*$s7} healing onto up to $s3 injured allies and ${$443038s1*$s7} Nature damage onto enemies within $s6 yds over $d, reduced beyond $s3 targets.][The August Celestials empower you, causing you to radiate ${$443038s1*$s7} Nature damage onto enemies and ${$443039s1*$s7} healing onto up to $s3 injured allies within $443038A2 yds over $d, reduced beyond $s3 targets.]\n\n\n\nYou may move while channeling, but casting other healing or damaging spells cancels this effect.", ua = "$?c2[Високородні Небожителі підсилюють вас, змушуючи випромінювати ${$443039s1*$s7} зцілення до $s3 поранених союзників і ${$443038s1*$s7} шкоди від сил природи ворогам у радіусі $s6 ярдів протягом $d, зменшено після $s3 цілей.][Високородні Небожителі підсилюють вас, змушуючи випромінювати ${$443038s1*$s7} шкоди від сил природи ворогам і ${$443039s1*$s7} зцілення до $s3 поранених союзників у радіусі $443038A2 ярдів протягом $d, зменшено після $s3 цілей.]\n\n\n\nВи можете рухатися під час підтримання, але творення інших зцілювальних чи шкідливих заклять скасовує цей ефект." },
    { en = "Using Wild Charge while in Bear Form or Moonkin Form incurs a $s1 sec shorter cooldown.", ua = "Використання «Дикого наскоку» в подобі ведмедя чи подобі місячного совуха скорочує його перезарядження на $s1 сек." },
    { en = "You heal for $s2% of your maximum health instantly when you activate Celestial Conduit and receive $s1% less damage for its duration. \n\n\n\nThis effect lingers for an additional $448508d after Celestial Conduit ends.", ua = "Ви миттєво зцілюєтеся на $s2% вашого максимального здоров'я, коли активуєте «Небесний канал», і отримуєте на $s1% менше шкоди протягом його дії. \n\n\n\nЦей ефект триває ще $448508d після завершення «Небесного каналу»." },
    { en = "$?c2[Tiger Palm, Vivify, and Sheilun's Gift have a chance to cause Xuen to claw a nearby enemy for $457917s1 Physical damage, healing a nearby ally for $s2% of the damage done.]?c3[Tiger Palm has a chance to cause Xuen to claw your target for $457917s1 Physical damage, healing a nearby ally for $s2% of the damage done.][Xuen claws your target for $457917s1 Physical damage, healing a nearby ally for $s2% of the damage done.]\n\n\n\n$?c2[Invoke Yu'lon, the Jade Serpent or Invoke Chi-Ji, the Red Crane]?c3[Invoke Xuen, the White Tiger][Invoking a celestial] guarantees your next cast activates this effect.", ua = "$?c2[Долоня тигра, Оживлення та Дар Шейлун мають шанс змусити Сюеня дряпнути ворога поблизу, завдаючи $457917s1 фізичної шкоди та зцілюючи союзника поблизу на $s2% завданої шкоди.]?c3[Долоня тигра має шанс змусити Сюеня дряпнути вашу ціль, завдаючи $457917s1 фізичної шкоди та зцілюючи союзника поблизу на $s2% завданої шкоди.][Сюень дряпає вашу ціль, завдаючи $457917s1 фізичної шкоди та зцілюючи союзника поблизу на $s2% завданої шкоди.]\n\n\n\n$?c2[Заклик Ю'лон, Нефритової Змії, або Заклик Чі-Цзи, Червоного Журавля]?c3[Заклик Сюеня, Білого Тигра][Заклик небожителя] гарантує, що ваше наступне творення активує цей ефект." },
    { en = "$?c2[After Xuen assists you, your next Enveloping Mist's cast time is reduced by $443112s1% and causes Niuzao to grant an absorb shield to $443113s3 nearby allies for $443113s1.]?c3[After Xuen assists you, your next Blackout Kick refunds $s3 stacks of Teachings of the Monastery and causes Niuzao to stomp at your target's location, dealing $443127s1 damage to nearby enemies, reduced beyond $s2 targets.][]", ua = "$?c2[Після того як Сюень допоможе вам, час прочитання вашого наступного Огортального туману зменшується на $443112s1%, а Ніузао надає поглинальний щит $443113s3 союзникам поблизу на $443113s1.]?c3[Після того як Сюень допоможе вам, ваш наступний Затьмарливий удар повертає $s3 стаків Вчень монастиря і змушує Ніузао тупнути в місці вашої цілі, завдаючи $443127s1 шкоди ворогам поблизу, зменшеної понад $s2 цілей.][]" },
    { en = "Reversion healing has a chance to cause your next Living Flame to cast instantly and deal $s2% increased healing or damage. Stacks up to $394552u charges.", ua = "Зцілення «Реверсії» має шанс зробити твоє наступне «Живе полум'я» миттєвим і збільшити його зцілення чи шкоду на $s2%. Сумується до $394552u зарядів." },
    { en = "Essence Burst increases the effectiveness of your next Essence ability by $s1%.", ua = "«Вибух есенції» збільшує ефективність твоєї наступної здібності есенції на $s1%." },
    { en = "$?c2[Thunder Focus Tea calls]?c3[Strike of the Windlord and Whirling Dragon Punch call][] upon Yu'lon to increase the cooldown recovery rate of $?c2[Renewing Mist, Rising Sun Kick, Life Cocoon, and Thunder Focus Tea]?c3[Fists of Fury, Strike of the Windlord, Rising Sun Kick, and Whirling Dragon Punch][] by $443421s2% for $?c2[${$s1/1000} sec]?c3[$443421d][].$?c3[ \n\n\n\nThe channel time of Fists of Fury is reduced by $443421s5% while Yu'lon is active.][]", ua = "$?c2[Чай грозового зосередження кличе]?c3[Удар Володаря вітрів і Вихровий драконячий удар кличуть][] Ю'лон, щоб на $443421s2% пришвидшити відновлення перезарядження $?c2[Оновлювального туману, Удару висхідного сонця, Кокона життя та Чаю грозового зосередження]?c3[Кулаків люті, Удару Володаря вітрів, Удару висхідного сонця та Вихрового драконячого удару][] протягом $?c2[${$s1/1000} сек]?c3[$443421d][].$?c3[ \n\n\n\nЧас підтримання Кулаків люті зменшено на $443421s5%, поки Ю'лон активна.][]" },
    { en = "Lava Burst gains an additional charge and deals $s2% increased damage.$?a137039[\n\n\n\nRiptide gains an additional charge and heals for $s3% more.][]", ua = "Виверження лави отримує додатковий заряд і завдає на $s2% більше шкоди.$?a137039[\n\n\n\nВідплив отримує додатковий заряд і зцілює на $s3% більше.][]" },
    { en = "Ancestors have a $s1% chance to call another Ancestor for $445624d when they depart.", ua = "Предки, зникаючи, мають $s1% шансу прикликати ще одного предка на $445624d." },
    { en = "Using spells with a cast time increases the duration of Spiritwalker's Grace and Spiritwalker's Aegis by ${$s1/1000} sec, up to a maximum of ${$s2/1000} sec.", ua = "Використання заклять із часом творення подовжує дію «Милості духоходця» та «Егіди духоходця» на ${$s1/1000} сек., максимум до ${$s2/1000} сек." },
    { en = "Earth Shield has an additional $s1 charges and heals you for $s3% more.", ua = "«Земний щит» має додатково $s1 зарядів і зцілює тебе на $s3% сильніше." },
    { en = "Reduces the cooldown of Nature's Guardian by ${$s1/-1000} sec and causes it to heal for an additional $s2% of your maximum health.", ua = "Зменшує перезарядження «Вартового природи» на ${$s1/-1000} сек. і змушує його зцілювати додатково на $s2% твого максимального здоров'я." },
    { en = "Ancestors last an additional ${$s1/1000} sec.", ua = "Предки тривають на ${$s1/1000} сек. довше." },
    { en = "$?a137040[Lightning Bolt, Lava Burst, Flame Shock, Voltaic Blaze, and Chain Lightning have a $s2][Riptide has a $s1]% chance to call an Ancestor to your side for $445624d.", ua = "$?a137040[Блискавка, Виверження лави, Полум'яний шок, Вольтаїчне полум'я та Ланцюгова блискавка мають $s2][Відлив має $s1]% шанс прикликати Предка до вас на $445624d." },
    { en = "When an Ancestor departs, they cast $?a137040[Elemental Blast at a nearby enemy.][Hydrobubble on a nearby injured ally.\n\n\n\n$@spellicon444490 |cFFFFFFFF$@spellname444490|r\n\n$@spelldesc444490]", ua = "Коли предок відходить, він читає $?a137040[Стихійний вибух по ближньому ворогу.][Гідробульбашку на ближнього пораненого союзника.\n\n\n\n$@spellicon444490 |cFFFFFFFF$@spellname444490|r\n\n$@spelldesc444490]" },
    { en = "$?a137040[Increases the damage of Earth Shock, Elemental Blast, and Earthquake by $s1%.\n\n\n\nIncreases the healing of Healing Surge and Chain Heal by $s2%.][Increases the healing done by Healing Wave, Downpour, and Chain Heal by $s2%.]", ua = "$?a137040[Підвищує шкоду «Земного удару», «Стихійного вибуху» та «Землетрусу» на $s1%.\n\n\n\nПідвищує зцілення «Хвилі зцілення» та «Ланцюгового зцілення» на $s2%.][Підвищує зцілення «Цілющої хвилі», «Зливи» та «Ланцюгового зцілення» на $s2%.]" },
    { en = "Increases your maximum $?a137040[Maelstrom by $s1.][mana by $s2%.\n\n\n\nTidal Waves can now stack up to ${$s3+$s4} times.]", ua = "Збільшує ваш максимальний $?a137040[Вир на $s1.][запас мани на $s2%.\n\n\n\nПрипливні хвилі тепер можуть накопичуватися до ${$s3+$s4} разів.]" },
    { en = "Your Ancestors' spells are $s1% more powerful.", ua = "Закляття твоїх предків на $s1% потужніші." },
    { en = "$?a137040[Stormkeeper calls an Ancestor to your side for $445624d.][Unleash Life calls an Ancestor to your side for $s1 sec.]\n\n\n\nWhenever you cast a healing or damaging spell, the Ancestor will cast a similar spell.", ua = "$?a137040[«Хранитель бурі» прикликає Предка до тебе на $445624d.][«Вивільнення життя» прикликає Предка до тебе на $s1 сек.]\n\n\n\nЩоразу, коли ти твориш зцілювальне чи шкодне закляття, Предок творить подібне закляття." },
    { en = "When an Ancestor is called, they reduce the cooldown of $?a137040[Stormkeeper by ${$s1/-1000} sec.][Riptide by ${$s2/-1000} sec.]", ua = "Коли Предка прикликають, він зменшує перезарядження $?a137040[Хранителя бур на ${$s1/-1000} сек.][Відпливу на ${$s2/-1000} сек.]" },
    { en = "If no enemies are struck by Soul Rupture, you gain $469169s1% Strength for $469169d.\n\n\n\nWave of Souls is $s2% more effective on the main target of your Reaper's Mark.", ua = "Якщо Розрив душі не вражає жодного ворога, ви отримуєте $469169s1% Сили на $469169d.\n\n\n\nХвиля душ на $s2% ефективніша проти головної цілі вашої Мітки женця." },
    { en = "Your movement speed is increased by $s1% during Celestial Conduit and by $443569s1% for $443569d after being assisted by any Celestial.", ua = "Твоя швидкість руху збільшена на $s1% під час «Небесного провідника» та на $443569s1% на $443569d після допомоги будь-якого Небожителя." },
    { en = "You switch between alignments every $t1 sec, increasing a corresponding secondary stat by $443572s1%.\n\n\n\n|cFFFFFFFFCrane Stance|r:\n\nHaste\n\n\n\n|cFFFFFFFFTiger Stance|r:\n\nCritical Strike\n\n\n\n|cFFFFFFFFOx Stance|r:\n\nVersatility\n\n\n\n|cFFFFFFFFSerpent Stance|r: \n\nMastery", ua = "Ви перемикаєтеся між налаштуваннями кожні $t1 с, збільшуючи відповідну вторинну характеристику на $443572s1%.\n\n\n\n|cFFFFFFFFСтійка журавля|r:\n\nПоспіх\n\n\n\n|cFFFFFFFFСтійка тигра|r:\n\nКритичний удар\n\n\n\n|cFFFFFFFFСтійка бика|r:\n\nУніверсальність\n\n\n\n|cFFFFFFFFСтійка змії|r: \n\nМайстерність" },
    { en = "Celestial Conduit can be recast once during its duration to call upon all of the August Celestials to assist you at $s1% effectiveness.\n\n\n\nUnity Within is automatically cast when Celestial Conduit ends if not used before expiration.", ua = "Небесний провідник можна повторно сотворити один раз протягом його дії, аби прикликати всіх Серпневих небожителів на допомогу з $s1% ефективністю.\n\n\n\nВнутрішня єдність сотворюється автоматично після завершення Небесного провідника, якщо її не використано до закінчення." },
    { en = "Rising Sun Kick damage increased by $s1%.", ua = "Шкода Удару висхідного сонця збільшена на $s1%." },
    { en = "$?c1[Casting Arcane Blast or Arcane Pulse][Casting Frostbolt or Flurry] conjures $?c1[an Arcane][a Frost] Splinter.\n\n$?c1[\n\n$@spellicon443763$@spellname443763:\n\n$@spelldesc443763\n\n]\n\n[\n\n$@spellicon443722$@spellname443722:\n\n$@spelldesc443722\n\n]", ua = "$?c1[Творіння Арканного удару або Арканного пульсу][Творіння Морозної стріли або Шквалу] прикликає $?c1[арканну][морозну] скалку.\n\n$?c1[\n\n$@spellicon443763$@spellname443763:\n\n$@spelldesc443763\n\n]\n\n[\n\n$@spellicon443722$@spellname443722:\n\n$@spelldesc443722\n\n]" },
    { en = "$?c1[Casting Arcane Surge generates $s1 Arcane Splinters][Each time Ray of Frost damages one or more enemies, it generates $s3 Frost $LSplinter:Splinters;].\n\n\n\n$?c1[During Arcane Surge, your chance to conjure an additional Arcane Splinter is increased to $s2%][For $1247908d after casting Ray of Frost, your chance to conjure an additional Frost Splinter is increased to $s2%].", ua = "$?c1[Творіння Аркани сплеску породжує $s1 арканних скалок][Щоразу, коли Промінь морозу завдає шкоди одному чи більше ворогам, він породжує $s3 $Lморозну скалку:морозні скалки:морозних скалок;].\n\n\n\n$?c1[Під час Аркани сплеску ваш шанс прикликати додаткову арканну скалку збільшено до $s2%][Протягом $1247908d після творіння Променя морозу ваш шанс прикликати додаткову морозну скалку збільшено до $s2%]." },
    { en = "Spending Runes has a chance to call forth the aid of a Horsemen for $454390d.\n\n\n\n|cFFFFFFFFMograine|R\n\nCasts Death and Decay at his location that follows his position and extends the duration of your diseases by ${$s2/1000}.1 sec whenever it deals damage.\n\n\n\n|cFFFFFFFFWhitemane|R\n\nCasts Undeath on your target dealing $444633s1 Shadowfrost damage per stack every $444633t sec, for $444633d. Each time Undeath deals damage it gains a stack. Cannot be refreshed.\n\n\n\n|cFFFFFFFFTrollbane|R\n\nCasts Chains of Ice on your target slowing their movement speed by $444834s1% and increasing the damage they take from you by 5% for 8 sec.\n\n\n\n|cFFFFFFFFNazgrim|R\n\nWhile Nazgrim is active you gain Apocalyptic Conquest, increasing your Strength by $444763s1%.", ua = "Витрачання рун має шанс прикликати на допомогу вершника на $454390d.\n\n\n\n|cFFFFFFFFМоґрейн|R\n\nТворить Смерть і розклад на своєму місці; зона ефекту слідує за його положенням і подовжує тривалість ваших хвороб на ${$s2/1000}.1 сек. щоразу, коли завдає шкоди.\n\n\n\n|cFFFFFFFFВайтмейн|R\n\nТворить Нежить на вашій цілі, завдаючи $444633s1 шкоди тіньоморозом за заряд кожні $444633t сек. упродовж $444633d. Щоразу, коли Нежить завдає шкоди, вона отримує заряд. Не можна оновити.\n\n\n\n|cFFFFFFFFТроллбейн|R\n\nТворить Крижані ланцюги на вашій цілі, сповільнюючи її швидкість руху на $444834s1% і збільшуючи шкоду, яку вона отримує від вас, на 5% упродовж 8 сек.\n\n\n\n|cFFFFFFFFНазґрім|R\n\nПоки Назґрім активний, ви отримуєте Апокаліптичне завоювання, що збільшує вашу Силу на $444763s1%." },
    { en = "While outdoors you are able to mount your Acherus Deathcharger in combat.", ua = "Просто неба ти можеш сідати верхи на свого скакуна смерті з Ахеруса навіть у бою." },
    { en = "Call upon your Death Charger to break free of movement impairment effects.\n\n\n\nFor $444347d, while upon your Death Charger your movement speed is increased by $444347s5%, you cannot be slowed below $444347s10% of normal speed, and you are immune to forced movement effects and knockbacks.", ua = "Прикликає вашого смертельного скакуна, щоб вирватися з ефектів, що сковують пересування.\n\n\n\nПротягом $444347d, доки ви верхи на смертельному скакуні, ваша швидкість пересування збільшена на $444347s5%, вас не можна сповільнити нижче $444347s10% від звичайної швидкості, і ви несприйнятливі до ефектів примусового пересування та відкидань." },
    { en = "Essence abilities are enhanced with Flame, dealing $s1% of healing or damage done as Fire over 8 sec.", ua = "Здібності есенції підсилено полум'ям: вони додатково завдають $s1% завданого зцілення або шкоди як вогонь протягом 8 сек." },
    { en = "Fire Breath $?c1[reaches its][and Dream Breath reach their] maximum empower level $s1% faster.", ua = "Вогняний подих $?c1[досягає свого][і Подих сновидінь досягають свого] максимального рівня посилення на $s1% швидше." },
    { en = "When $?a137006[Obliterate or Frostscythe]?s207311[Clawing Shadows][Scourge Strike] damages an enemy affected by Undeath it gains $s1 $Lstack:stacks; and infects another nearby enemy.", ua = "Коли $?a137006[Знищення або Крижана коса]?s207311[Дряпучі тіні][Удар Батога] завдає шкоди ворогові під дією Нежиття, ефект отримує $s1 $Lзаряд:заряди:зарядів; і заражає іншого ворога поблизу." },
    { en = "The damage of your diseases and $?a137006[Frost Strike][Death Coil] are increased by $s1%.", ua = "Шкода від ваших хвороб та $?a137006[Морозного удару][Смертельного шлейфу] збільшена на $s1%." },
    { en = "Army of the Dead and Frostwyrm's Fury call upon all 4 Horsemen to aid you for ${$s2/1000} sec.", ua = "Армія мертвих і Лють морозного вирма прикликають усіх 4 Вершників на допомогу тобі на ${$s2/1000} сек." },
    { en = "Your damage is increased by $444505s1% and you gain $?c3[the benefits of your Death and Decay]?c2[$444505s4% critical strike chance][] while inside Mograine's Death and Decay.", ua = "Ваша шкода збільшена на $444505s1%, і ви отримуєте $?c3[переваги вашої Смерті й тліну]?c2[$444505s4% шансу критичного удару][], поки перебуваєте у Смерті й тліні Моґрейна." },
    { en = "If an enemy dies while Nazgrim is active, the strength of Apocalyptic Conquest is increased by $s1%.\n\n\n\nAdditionally, each Rune you spend increase its value by $s2%.", ua = "Якщо ворог гине, поки Назґрім активний, сила Апокаліптичного завоювання зростає на $s1%.\n\n\n\nКрім того, кожна витрачена руна збільшує його значення на $s2%." },
    { en = "Every $s1 Runic Power you spend extends the duration of the Horsemen's aid in combat by $s3 sec, up to $s2 sec.", ua = "Кожні $s1 од. рунічної моці, які ти витрачаєш, продовжують допомогу вершників у бою на $s3 сек., щонайбільше до $s2 сек." },
    { en = "While you have $s1 or more Horsemen aiding you, your $?c2[Runic Power spending abilities deal]?c3[Death Coil deals $440861s1% and Epidemic deals $440861s3%][] increased damage.", ua = "Поки вам допомагає щонайменше $s1 Вершників, ваші $?c2[здібності, що витрачають руническу силу, завдають]?c3[Спіраль смерті завдає $440861s1%, а Епідемія — $440861s3%][] підвищеної шкоди." },
    { en = "While at your aid, the Horsemen will occasionally cast Anti-Magic Shell on you and themselves at $s1% effectiveness.\n\n\n\nYou may only benefit from this effect every $451777d.", ua = "Допомагаючи вам, вершники час від часу творять Антимагічний панцир на вас і на себе з $s1% ефективністю.\n\n\n\nВи можете скористатися цим ефектом лише раз на $451777d." },
    { en = "When you take damage, $s1% of the damage is redirected to each active horsemen.", ua = "Коли ти зазнаєш шкоди, $s1% її перенаправляється на кожного активного вершника." },
    { en = "$?c1[Disintegrate damage consumes ${$s2/1000}.1 sec of Fire Breath from enemies it damages, detonating it for $s4% of the amount consumed.\n\n\n\nPyre damage consumes ${$s3/1000} sec of Fire Breath from enemies it damages, detonating it for $s7% of the amount consumed.][Verdant Embrace healing consumes ${$s5/1000} sec of Dream Breath from allies it heals, detonating it and healing them for $s6% of the amount consumed.\n\n\n\nEmerald Blossom healing consumes ${$s1/1000} sec of Dream Breath from allies it heals, detonating it and healing them for $s6% of the amount consumed.]", ua = "$?c1[Шкода від Розпаду споживає ${$s2/1000}.1 сек. Вогняного подиху з ворогів, яким вона завдає шкоди, підриваючи його на $s4% спожитого обсягу.\n\n\n\nШкода від Багаття споживає ${$s3/1000} сек. Вогняного подиху з ворогів, яким вона завдає шкоди, підриваючи його на $s7% спожитого обсягу.][Зцілення від Зелених обіймів споживає ${$s5/1000} сек. Подиху сну з союзників, яких воно зцілює, підриваючи його та зцілюючи їх на $s6% спожитого обсягу.\n\n\n\nЗцілення від Смарагдового цвіту споживає ${$s1/1000} сек. Подиху сну з союзників, яких воно зцілює, підриваючи його та зцілюючи їх на $s6% спожитого обсягу.]" },
    { en = "$?a137006[Obliterate and Frostscythe]?s207311[Clawing Shadows][Scourge Strike] $?a137006[shatter][shatters] Trollbane's Chains of Ice when hit, dealing $444834s2 Shadowfrost damage to nearby enemies, and slowing them by $444834s1% for $444834d. Deals reduced damage beyond $s1 targets.", ua = "$?a137006[Знищення і Морозяна коса]?s207311[Дряпучі тіні][Удар Батога] при влучанні $?a137006[розбивають][розбиває] Крижані ланцюги Троллбейна, завдаючи $444834s2 тіньоморозної шкоди ворогам поблизу й уповільнюючи їх на $444834s1% на $444834d. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "$?a137006[Obliterate deals $s4]?s207311[Clawing Shadows deals $s3][Scourge Strike deals $s3]% increased damage and $?s152280[the cooldown of your Defile is reduced by ${$s2/-1000}]?a137006[your Remorseless Winter lasts ${$s5/1000} sec longer][the cooldown of your Death and Decay is reduced by ${$s1/-1000} sec].", ua = "$?a137006[Знищення завдає на $s4]?s207311[Дряпучі тіні завдають на $s3][Удар Батога завдає на $s3]% більше шкоди, і $?s152280[перезарядження вашого Осквернення зменшується на ${$s2/-1000}]?a137006[ваша Безжальна зима триває на ${$s5/1000} сек довше][перезарядження вашої Смерті й тління зменшується на ${$s1/-1000} сек]." },
    { en = "Enemies damaged by your $?c1[Arcane Orb][Frozen Orb] conjure $?c1[$s4 Arcane][$s5 Frost] $LSplinter:Splinters;, up to $?c1[$s1][$s6].\n\n\n\n$?c1[Arcane Orb][Frozen Orb] damage is increased by $s3%.", ua = "Вороги, яким ваша $?c1[«Арканна сфера»][«Крижана сфера»] завдає шкоди, породжують $?c1[$s4 арканні][$s5 крижані] $LSplinter:скалки;, до $?c1[$s1][$s6].\n\n\n\nШкода від $?c1[«Арканної сфери»][«Крижаної сфери»] зростає на $s3%." },
    { en = "Obsidian Scales also applies to your target or $s1 nearby injured $Lally:allies; at $s2% value.", ua = "Обсидіанова луска також застосовується до вашої цілі або $s1 поранених $Lсоюзника:союзників; поблизу з ефективністю $s2%." },
    { en = "$?c1[$s1%][$s4%] of the direct damage dealt by $?c1[an Arcane Splinter][a Frost Splinter] is also dealt to nearby enemies. Damage reduced beyond $s5 targets.", ua = "$?c1[$s1%][$s4%] прямої шкоди, завданої $?c1[Арканним осколком][Морозним осколком], завдається також ворогам поблизу. Шкода зменшується понад $s5 цілей." },
    { en = "Gaining $?c1[Clearcasting][Brain Freeze] conjures $s1 $?c1[Arcane][Frost] $lSplinter:Splinters;.", ua = "Отримання $?c1[Ясного чаклування][Заморозки мозку] прикликає $s1 $?c1[арканний][морозний] $lуламок:уламки;." },
    { en = "$?c1[Casting Arcane Barrage conjures an Arcane Splinter for every $s1 Arcane Salvo stacks consumed][Ice Lance conjures a Frost Splinter for every $s3 Freezing stacks Shattered from its primary target].", ua = "$?c1[Творення «Арканного шквалу» прикликає Арканну скалку за кожні $s1 витрачених стаків «Арканного залпу»][«Крижаний спис» прикликає Морозну скалку за кожні $s3 стаки «Заморозки», Розтрощені на основній цілі]." },
    { en = "You have $s1% increased movement speed during Alter Time$?a236457[ and Evocation][].", ua = "Ваша швидкість пересування збільшена на $s1% під час Зміни часу$?a236457[ та Прикликання][]." },
    { en = "While in combat, Blink summons a Mirror Image at your previous location.", ua = "У бою «Блимання» прикликає «Дзеркальне відображення» на твоїй попередній позиції." },
    { en = "Your attacks against your primary target have a $s1% chance to overwhelm their defenses and trigger a Slayer's Strike, dealing $445579s1 Physical damage and granting you a stack of Executioner, increasing your Execute damage by $445584s1% for $445584d. Multiple stacks of Executioner may overlap.", ua = "Твої атаки по основній цілі мають $s1% шансу зломити її захист і викликати «Удар убивці», що завдає $445579s1 фізичної шкоди та дає тобі заряд «Ката», збільшуючи шкоду твоєї «Страти» на $445584s1% на $445584d. Кілька зарядів «Ката» можуть діяти одночасно." },
    { en = "Every $s1 Slayer's Strikes you gain Sudden Death.\n\n\n\nUsing Sudden Death accelerates your next Bladestorm, striking 1 additional time (max $445606u). Bladestorm's total duration is unchanged.\n\n\n\nSudden Death has a $s2% chance to trigger Reap the Storm at $s3% effectiveness.", ua = "Кожні $s1 Удари вбивці ти отримуєш Раптову смерть.\n\n\n\nВикористання Раптової смерті прискорює твій наступний Вихор клинків, додаючи 1 удар (макс. $445606u). Загальна тривалість Вихору клинків лишається незмінною.\n\n\n\nРаптова смерть має $s2% шансу запустити Жнива бурі з $s3% ефективністю." },
    { en = "You heal for $s1% of damage dealt by Sudden Death.", ua = "Ти зцілюєшся на $s1% шкоди, завданої «Раптовою смертю»." },
    { en = "Executioner also increases your Execute critical strike chance and critical strike damage by $445584s2% per stack.", ua = "Кат також збільшує шанс критичного удару та шкоду від критичних ударів твоєї Страти на $445584s2% за кожен заряд." },
    { en = "Each strike of Bladestorm applies Overwhelmed to all enemies affected, increasing damage you deal to them by $445836s1% for $445836d, max $445836u stacks.", ua = "Кожен удар Бурі клинків накладає Приголомшення на всіх уражених ворогів, збільшуючи шкоду, яку ти їм завдаєш, на $445836s1% на $445836d; максимум $445836u зарядів." },
    { en = "$?c1[Mortal Strike][Bloodthirst] critical strikes increase the damage of your next $?c1[Mortal Strike][Bloodthirst] by $?c1[$458689s1][$458689s2]%.", ua = "Критичні удари $?c1[«Смертельного удару»][«Кровожерливості»] підвищують шкоду вашого наступного $?c1[«Смертельного удару»][«Кровожерливості»] на $?c1[$458689s1][$458689s2]%." },
    { en = "$?c1[When Overpower has its cooldown reset by Tactician, your next Overpower deals $456120s3% additional damage and $456120s4% additional critical damage.][When Raging Blow resets its own cooldown, your next Raging Blow deals $456120s1% additional damage and $456120s2% additional critical damage.] Stacking up to $456120u times.", ua = "$?c1[Коли перезарядження «Здолання» скидається «Тактиком», ваше наступне «Здолання» завдає на $456120s3% більше шкоди і на $456120s4% більше критичної шкоди.][Коли «Лютий удар» скидає власне перезарядження, ваш наступний «Лютий удар» завдає на $456120s1% більше шкоди і на $456120s2% більше критичної шкоди.] Накопичується до $456120u разів." },
    { en = "When $?c1[Cleave hits][Rampage hits] $s2 or more targets$?c2[ via Improved Whirlwind][] you have a $?c1[$s3][$s4]% chance to unleash a flurry of steel, striking all nearby enemies for $446005s1 Physical damage and applying Overwhelmed. Deals reduced damage beyond $s1 targets.", ua = "Коли $?c1[Розсікання вражає][Буйство вражає] $s2 або більше цілей$?c2[ завдяки Покращеному вихору][], ви маєте $?c1[$s3][$s4]% шансу вивільнити град сталі, вражаючи всіх ворогів поблизу на $446005s1 фізичної шкоди і накладаючи Приголомшення. Завдає зменшеної шкоди понад $s1 цілей." },
    { en = "Charge increases your movement speed by $446044s1% for $446044d.\n\n\n\nCharge removes all movement impairing effects, this effect cannot occur more than once every $458386d.", ua = "Ривок збільшує твою швидкість пересування на $446044s1% на $446044d.\n\n\n\nРивок знімає всі ефекти, що уповільнюють пересування; цей ефект не може спрацьовувати частіше, ніж раз на $458386d." },
    { en = "Heroic Leap reduces the cooldown of Charge by $s1 sec and Charge reduces the cooldown of Heroic Leap by $s2 sec.", ua = "Героїчний стрибок зменшує перезарядження Ривка на $s1 сек., а Ривок зменшує перезарядження Героїчного стрибка на $s2 сек." },
    { en = "Each strike of Bladestorm deals an additional $s1% damage evenly split across all targets.", ua = "Кожен удар Бурі клинків завдає додатково $s1% шкоди, порівну розділеної між усіма цілями." },
    { en = "$?c1[Overpower][Raging Blow] and Execute damage increased by $?c1[$s1][$s2]%.", ua = "Шкода від $?c1[«Здолання»][«Лютого удару»] і «Страти» підвищена на $?c1[$s1][$s2]%." },
    { en = "Using Sudden Death causes you to both reduce the cooldown of Bladestorm by $s1 sec and apply $s2 stack of Overwhelmed to your primary target per stack of Executioner you have.\n\n\n\nYou can use Pummel and Storm Bolt while Bladestorming.\n\n\n\nBladestorm damage increased by $s4%.", ua = "Використання Раптової смерті зменшує перезарядження Вихору клинків на $s1 сек. і накладає $s2 заряд Приголомшення на твою основну ціль за кожен наявний у тебе заряд Ката.\n\n\n\nТи можеш використовувати Стусан і Громовий болт під час Вихору клинків.\n\n\n\nШкода Вихору клинків збільшена на $s4%." },
    { en = "Your Mirror Image summons $s2 extra $Lclone:clones;.", ua = "Ваш «Дзеркальний образ» викликає $s2 додаткові $Lклон:клони;." },
    { en = "Your $?c1[Prismatic][Ice] Barrier can absorb up to $s1% more damage based on your missing Health.\n\n\n\nMax effectiveness when under $s1% health.", ua = "Ваш $?c1[Призматичний][Крижаний] бар'єр може поглинути до $s1% більше шкоди залежно від нестачі вашого здоров'я.\n\n\n\nМаксимальна дієвість, коли здоров'я менше за $s1%." },
    { en = "Critical strike chance against targets above $s2% health increased by $s1%.", ua = "Шанс критичного удару по цілях із понад $s2% здоров'я збільшено на $s1%." },
    { en = "Fire Breath's damage over time is increased by $s1%. Dream Breath's heal over time is increased by $s1%.", ua = "Періодична шкода Вогняного подиху збільшена на $s1%. Періодичне зцілення Подиху сну збільшене на $s1%." },
    { en = "$?c1[Hover and Deep Breath][Hover, Deep Breath, and Dream Flight] travel $s1% faster, and Hover travels $s1% further.", ua = "$?c1[«Ширяння» і «Глибокий подих»][«Ширяння», «Глибокий подих» і «Політ мрії»] рухаються на $s1% швидше, а «Ширяння» долає на $s1% більшу відстань." },
    { en = "Vengeful Retreat can be cast a second time within $444929d.", ua = "«Мстивий відступ» можна застосувати вдруге протягом $444929d." },
    { en = "Vengeful Retreat resets the cooldown of Felblade.", ua = "«Мстивий відступ» скидає перезарядження «Клинка Скверни»." },
    { en = "$?c1[Arcane Surge][Ray of Frost] damage increased by $?c1[$s1][$s2]%.\n\n\n\nYour chance to gain $?c1[Clearcasting][Brain Freeze from Frostbolt] is increased by $?c1[$s3][$s4]%.", ua = "Шкода від $?c1[Аркани сплеску][Променя морозу] збільшена на $?c1[$s1][$s2]%.\n\n\n\nВаш шанс отримати $?c1[Ясне творіння][Заморозку мозку від Морозної стріли] збільшено на $?c1[$s3][$s4]%." },
    { en = "Direct damage from $?c1[Arcane][Frost] Splinters reduces the cooldown of $?c1[Arcane][Frozen] Orb by $?c1[${$s1/1000}.2][${$s2/1000}.2] sec.", ua = "Пряма шкода від $?c1[Арканних][Морозяних] скалок зменшує перезарядження $?c1[Арканної][Замороженої] кулі на $?c1[${$s1/1000}.2][${$s2/1000}.2] сек." },
    { en = "Throw Glaive deals $444979s1 Physical damage to enemies near its initial target.", ua = "«Кидок глефи» завдає $444979s1 фізичної шкоди ворогам поруч із початковою ціллю." },
    { en = "Elemental motes orbit around your Surging Totem. Your abilities consume the motes for enhanced effects. \n\n\n\n$?a137041[|cFFFFFFFFAir:|r $@spelldesc453409\n\n\n\n|cFFFFFFFFEarth:|r $@spelldesc453406\n\n\n\n|cFFFFFFFFFire:|r $@spelldesc453405][|cFFFFFFFFWater:|r $@spelldesc453407\n\n\n\n|cFFFFFFFFAir:|r $@spelldesc453409\n\n\n\n|cFFFFFFFFEarth:|r $@spelldesc453406]", ua = "Стихійні часточки кружляють навколо вашого Буйного тотема. Ваші здібності споживають часточки задля підсилених ефектів.\n\n\n\n$?a137041[|cFFFFFFFFПовітря:|r $@spelldesc453409\n\n\n\n|cFFFFFFFFЗемля:|r $@spelldesc453406\n\n\n\n|cFFFFFFFFВогонь:|r $@spelldesc453405][|cFFFFFFFFВода:|r $@spelldesc453407\n\n\n\n|cFFFFFFFFПовітря:|r $@spelldesc453409\n\n\n\n|cFFFFFFFFЗемля:|r $@spelldesc453406]" },
    { en = "$?a137041[Lightning Bolt, Chain Lightning and Elemental Blast has a chance to unleash a Surging Bolt at your Surging Totem, increasing the totem's damage by $458269s1%, and then redirecting the bolt to your target for $458267s1 Nature damage. The damage bonus effect can stack.][Chain Heal now jumps to a nearby totem within $458357A3 yards once it reaches its last target, causing the totem to cast Chain Heal on an injured ally within $458357r yards for $458357s1. Jumps to $s1 nearby targets within $458357A3 yards.]", ua = "$?a137041[Блискавка, Ланцюгова блискавка та Стихійний вибух мають шанс вивільнити Буряний розряд по вашому Буряному тотему, збільшуючи шкоду тотема на $458269s1%, а потім перенаправити розряд на вашу ціль, завдаючи $458267s1 шкоди силами природи. Ефект бонусу до шкоди накопичується.][Ланцюгове зцілення тепер перестрибує на тотем поблизу в межах $458357A3 ярдів, щойно досягне останньої цілі, змушуючи тотем сотворити Ланцюгове зцілення на пораненому союзнику в межах $458357r ярдів на $458357s1. Перестрибує на $s1 цілей поблизу в межах $458357A3 ярдів.]" },
    { en = "Increases the size and radius of your totems by $458016s2%, and the health of your totems by $458016s1%.", ua = "Збільшує розмір і радіус дії твоїх тотемів на $458016s2%, а їхнє здоров'я — на $458016s1%." },
    { en = "Successfully removing a harmful effect with Tremor Totem or Poison Cleansing Totem, or controlling an enemy with Capacitor Totem or Earthgrab Totem reduces the cooldown of the totem used by $/1000;s1 sec.\n\n\n\nCannot occur more than once every $457676d per totem.", ua = "Успішне зняття шкідливого ефекту тотемом Здригання чи тотемом Очищення від отрути, або контроль ворога тотемом Конденсатора чи тотемом Земної хватки зменшує перезарядження використаного тотема на $/1000;s1 с.\n\n\n\nНе може спрацьовувати частіше ніж раз на $457676d для кожного тотема." },
    { en = "$?a137041[Increases the chance for Windfury Weapon to trigger by $s1% and increases its damage by $s2%.\n\n\n\nWhen Flametongue Weapon triggers from Windfury Weapon attacks, it has a chance to gather a whirl of flame around the target, dealing $s5% of its damage to all nearby enemies.][Increases the duration of your Earthliving effect by ${$s3/1000} sec.]", ua = "$?a137041[Підвищує шанс спрацювання «Зброї вітрової люті» на $s1% і збільшує її шкоду на $s2%.\n\n\n\nКоли «Зброя вогнеязика» спрацьовує від атак «Зброї вітрової люті», вона має шанс зібрати вихор полум'я навколо цілі, завдаючи $s5% її шкоди всім ворогам поблизу.][Збільшує тривалість твого ефекту «Земне життя» на ${$s3/1000} сек.]" },
    { en = "While Surging Totem is active, your damage and healing done is increased by $456369s1%.", ua = "Поки діє «Бурхливий тотем», твоя шкода і зцілення збільшені на $456369s1%." },
    { en = "Surging Totem $?a462110[heals for $s1% more][deals $s2% more damage] while Ascendance or Healing Tide Totem is active.", ua = "Тотем хвилі $?a462110[зцілює на $s1% більше][завдає на $s2% більше шкоди], доки активне Піднесення або Тотем цілющого припливу." },
    { en = "If you have a totem active, your totem grants you a shield absorbing ${$mhp*$s1/100} damage for $457387d every $457390d.", ua = "Якщо в тебе є активний тотем, він дає тобі щит, що поглинає ${$mhp*$s1/100} шкоди, на $457387d кожні $457390d." },
    { en = "$?a137041[Increases the damage of Surging Totem by $s1%.][Increases the healing done by Surging Totem by $s2%.]", ua = "$?a137041[Збільшує шкоду від Буряного тотема на $s1%.][Збільшує зцілення від Буряного тотема на $s2%.]" },
    { en = "$?a137041[Increases the critical strike chance of Flametongue Weapon by $s1%, and its critical strike damage by $s2%.][Learn a new weapon imbue, Tidecaller's Guard.\n\n\n\n$@spellicon457481 $@spellname457481\n\n$@spelldesc457481 ]", ua = "$?a137041[Підвищує шанс критичного удару «Зброї вогнеязика» на $s1% і шкоду її критичних ударів на $s2%.][Вивчає нове насичення зброї — «Оберіг закличника припливу».\n\n\n\n$@spellicon457481 $@spellname457481\n\n$@spelldesc457481 ]" },
    { en = "$?a137041[Lava Lash has a chance to summon a Searing Totem to hurl Searing Bolts that deal $3606s1 Fire damage to a nearby enemy. Lasts $458101d.\n\n\n\nLava Lash and Voltaic Blaze cause your Searing Totems to shoot a Searing Volley at up to $s3 nearby enemies for $458147s1 Fire damage.][When you summon a Healing Tide Totem, Healing Stream Totem, or Spirit Link Totem you cast a free instant Chain Heal at $458221s2% effectiveness.]", ua = "$?a137041[«Лавовий батіг» має шанс прикликати «Палючий тотем», що метає «Палючі стріли», завдаючи $3606s1 шкоди як Вогонь ворогові поблизу. Триває $458101d.\n\n\n\n«Лавовий батіг» і «Вольтаїчне полум'я» змушують твої «Палючі тотеми» випускати «Палючий залп» по ще до $s3 ворогах поблизу, завдаючи $458147s1 шкоди як Вогонь.][Коли ти прикликаєш «Тотем цілющого припливу», «Тотем цілющого потоку» чи «Тотем зв'язку духів», ти безкоштовно й миттєво твориш «Ланцюгове зцілення» з $458221s2% ефективністю.]" },
    { en = "$?a137041[While Hot Hand is active Lava Lash shatters the earth, causing a Sundering at $s1% effectiveness.][Your Healing Stream Totems heals an additional ally at $s3% effectiveness.\n\n\n\nHealing Tide Totem healing increased by $s2%.]", ua = "$?a137041[Поки активна «Гаряча рука», «Лавовий батіг» розколює землю, спричиняючи «Розкол» з $s1% ефективністю.][Твої «Тотеми цілющого потоку» зцілюють ще одного союзника з $s3% ефективністю.\n\n\n\nЗцілення «Тотема цілющого припливу» зросло на $s2%.]" },
    { en = "$?a137041[Increases the critical strike chance of your Searing Totem's attacks by $s1%, and its critical strike damage by $s2%.][Chain Heals from Lively Totem and Totemic Rebound are $s3% more effective.]", ua = "$?a137041[Збільшує шанс критичного удару атак вашого Обпікаючого тотема на $s1%, а його критичну шкоду — на $s2%.][Ланцюгові зцілення від Жвавого тотема й Тотемного відскоку на $s3% ефективніші.]" },
    { en = "Tail Swipe and Wing Buffet scorch enemies and blind them with ash, causing their next attack within $445134d to miss.", ua = "«Змах хвостом» і «Удар крилами» обпалюють ворогів і засліплюють їх попелом, через що їхня наступна атака протягом $445134d схибить." },
    { en = "$?c1[The healing and damage of Holy Shock is increased by $s1%.]?c3[Your damage and healing over time effects have a chance to increase the damage of your next Judgment by $445206s1%.][]", ua = "$?c1[Зцілення та шкода «Святого шоку» збільшені на $s1%.]?c3[Твої періодичні ефекти шкоди та зцілення мають шанс збільшити шкоду твого наступного «Осуду» на $445206s1%.][]" },
    { en = "Bestows a vile malediction upon the target, burning the sinew and muscle of its host, dealing $s1 Shadowflame damage immediately and an additional $445474o1 Shadowflame damage over $445474d.$?s137046[\n\n\n\n|cFFFFFFFFPeriodic damage generates 1 Soul Shard Fragment and has a $s2% chance to generate an additional 1 on critical strikes.\n\n\n\nReplaces Immolate.|r][\n\n\n\n|cFFFFFFFFReplaces Corruption.|r]", ua = "Накладає на ціль мерзенне прокляття, що випалює сухожилля й м'язи носія, завдаючи $s1 шкоди тіньовим полум'ям одразу та додаткові $445474o1 шкоди тіньовим полум'ям протягом $445474d.$?s137046[\n\n\n\n|cFFFFFFFFПеріодична шкода створює 1 Фрагмент уламка душі та має $s2% шансу створити додатковий 1 при критичних ударах.\n\n\n\nЗамінює Спопеління.|r][\n\n\n\n|cFFFFFFFFЗамінює Псування.|r]" },
    { en = "Living Flame $?c1[and Azure Strike have $s1 extra chance to trigger Essence Burst when they critically strike.][has $s1 extra chance to trigger Essence Burst when it critically strikes.]", ua = "Жива полум'я $?c1[та Лазуровий удар мають $s1 додатковий шанс спричинити Вибух есенції при критичному ударі.][має $s1 додатковий шанс спричинити Вибух есенції при критичному ударі.]" },
    { en = "Your wounds have a small chance to cauterize, healing you for $s1% of damage taken. Occurs more often from attacks that deal high damage.", ua = "Твої рани мають невеликий шанс припектися, зцілюючи тебе на $s1% отриманої шкоди. Спрацьовує частіше від атак, що завдають великої шкоди." },
    { en = "Your next $?c1[Mortal Strike][Rampage] after Bladestorm ends deals $?c1[$446918s1][$446918s2]% additional damage.", ua = "Ваш наступний $?c1[Смертельний удар][Шал] після завершення Бурі клинків завдає на $?c1[$446918s1][$446918s2]% більше шкоди." },
    { en = "Rising Sun Kick now kicks up a Gust of Mist to heal $s1 $Lally:allies; within $446264A2 yds for $191894s1. \n\n\n\nSpinning Crane Kick and Blackout Kick have a chance to kick up a Gust of Mist to heal $s2 $Lally:allies; within $446264A2 yds for $191894s1.", ua = "Копняк висхідного сонця тепер здіймає Порив туману, що зцілює $s1 $Lally:allies; в межах $446264A2 ярдів на $191894s1. \n\n\n\nОбертовий удар журавля і Удар затьмарення мають шанс здійняти Порив туману, що зцілює $s2 $Lally:allies; в межах $446264A2 ярдів на $191894s1." },
    { en = "Renewing Mist's heal over time has a chance to cause your next $?s399491[Sheilun's Gift][Vivify] to also trigger a Zen Pulse on its target and all allies with Renewing Mist, healing them for $198487s1 increased by $s1% per Renewing Mist active, up to $s2%.", ua = "Періодичне зцілення Оновлюваного туману має шанс зробити так, що ваше наступне $?s399491[Дар Шейлуна][Вивифай] також спричинить Пульс дзену на цілі та всіх союзниках з Оновлюваним туманом, зцілюючи їх на $198487s1, збільшене на $s1% за кожен активний Оновлюваний туман, до $s2%." },
    { en = "After you fully consume Thunder Focus Tea, your next Vivify triggers Zen Pulse.", ua = "Коли ти повністю споживаєш «Чай громового зосередження», твоє наступне «Оживлення» активує «Дзен-імпульс»." },
    { en = "When Truth's Wake critically strikes, its duration is extended by $s1 sec.\n\n\n\nYour other damage over time effects deal $s2% increased damage to targets affected by Truth's Wake.", ua = "Коли «Слід істини» завдає критичного удару, його тривалість продовжується на $s1 с.\n\n\n\nВаші інші ефекти періодичної шкоди завдають на $s2% більше шкоди цілям, ураженим «Слідом істини»." },
    { en = "Rejuvenation instantly heals your target for $s1% of its total periodic effect and Regrowth's duration is increased by ${$s2/1000} sec.", ua = "«Омолодження» миттєво зцілює твою ціль на $s1% свого повного періодичного ефекту, а тривалість «Відростання» збільшено на ${$s2/1000} сек." },
    { en = "$?c3[Tear open a rift][Mind Blast tears open an Entropic Rift] that follows the enemy for $450193d. Enemies caught in its path suffer $447448s1 Shadow damage every $459314t1 sec while within its reach.", ua = "$?c3[Розриває розлом][Удар розуму розриває Ентропійний розлом], що переслідує ворога протягом $450193d. Вороги, які потрапляють на його шлях, зазнають $447448s1 шкоди від тіні кожні $459314t1 с, поки лишаються в його досяжності." },
    { en = "While above $s1% health, Holy Shock's healing is increased $447988s1%, but creates a heal absorb on you for $s2% of the amount healed that prevents Beacon of Light from healing you until it has dissipated.", ua = "Поки твоє здоров'я вище $s1%, зцілення від «Святого шоку» збільшено на $447988s1%, але воно створює на тобі поглинання зцілення в розмірі $s2% від відновленого здоров'я, яке не дає «Маяку світла» зціляти тебе, доки не розсіється." },
    { en = "Light of the Martyr's health threshold is reduced to ${$s4+$s1}% and increases Holy Shock's healing by an additional $448087s1% for every $t2 sec Light of the Martyr is active, stacking up to $448087u times.\n\n\n\nWhile below ${$s4+$s1}% health, the light urgently heals you for $448086s1 every $448086t1 sec.", ua = "Поріг здоров'я «Світла мученика» знижено до ${$s4+$s1}%, а зцілення від «Святого шоку» зростає додатково на $448087s1% за кожні $t2 с активності «Світла мученика», накопичуючись до $448087u разів.\n\n\n\nКоли ваше здоров'я нижче ${$s4+$s1}%, світло нагально зцілює вас на $448086s1 кожні $448086t1 с." },
    { en = "$?c3[Vampiric Touch and Shadow Word: Pain deal $s1% additional damage.][Power Word: Shield absorbs $s2% additional damage.]", ua = "$?c3[Вампірський дотик і Слово тіні: Біль завдають на $s1% більше шкоди.][Слово сили: Щит поглинає на $s2% більше шкоди.]" },
    { en = "Each time $?c3[you cast Shadow Word: Madness][Penance damages or heals], Entropic Rift is empowered, increasing its damage and size by $?c1[$s4][$s3]%.\n\n\n\nAfter Entropic Rift ends it collapses, dealing $448405s1 Shadow damage split amongst enemy targets within $448405a1 yds.", ua = "Щоразу, коли $?c3[ви творите Тіньове слово: Безум][Покута завдає шкоди чи зцілює], Ентропійний Розлом наснажується, збільшуючи свою шкоду та розмір на $?c1[$s4][$s3]%.\n\n\n\nКоли Ентропійний Розлом завершується, він колапсує, завдаючи $448405s1 шкоди Тінню, розподіленої між ворожими цілями в межах $448405a1 ярдів." },
    { en = "$?c1[Casting a damaging spell][Consuming Hot Streak] has a $s1% chance to conjure a Spellfire Sphere.\n\n\n\nWhile you're out of combat, you will slowly conjure Spellfire Spheres over time.\n\n\n\n$@spellicon448604 $@spellname448604\n\n$@spelldesc448604", ua = "$?c1[Творіння закляття, що завдає шкоди][Споживання Гарячої серії] має $s1% шансу прикликати Сферу чарополум'я.\n\n\n\nПоза боєм ви поступово прикликаєте Сфери чарополум'я з часом.\n\n\n\n$@spellicon448604 $@spellname448604\n\n$@spelldesc448604" },
    { en = "When you cast $?c1[Arcane Surge][Combustion], summon an Arcane Phoenix to aid you in battle.\n\n\n\n$@spellicon448659  $@spellname448659\n\nYour Arcane Phoenix aids you for the duration of your $?c1[Arcane Surge][Combustion], casting random Arcane and Fire spells.", ua = "Коли ви твориte $?c1[Арканний сплеск][Спалення], ви закликаєте арканного фенікса, що допомагає вам у бою.\n\n\n\n$@spellicon448659  $@spellname448659\n\nВаш арканний фенікс допомагає вам упродовж дії $?c1[Арканного сплеску][Спалення], творячи випадкові арканні та вогняні закляття." },
    { en = "Your next healing or damaging spell$?a1246131[ or Hex][] is instant, costs no mana, and deals $s6% increased damage and healing.\n\n\n\nIf you know Nature's Swiftness, it is replaced by Ancestral Swiftness and causes Ancestral Swiftness to call an Ancestor to your side for $445624d.", ua = "Ваше наступне закляття зцілення чи шкоди$?a1246131[ або Вроку][] стає миттєвим, не коштує мани й завдає на $s6% більше шкоди та зцілення.\n\n\n\nЯкщо ви знаєте Швидкість природи, її заміняє Швидкість предків, і Швидкість предків прикликає Предка до вас на $445624d." },
    { en = "Stamina increased by $s1%.\n\n\n\nStamina in Bear Form is increased by an additional $s2%.", ua = "Витривалість підвищено на $s1%.\n\n\n\nВитривалість у Подобі ведмедя підвищено додатково на $s2%." },
    { en = "Ferocious Bite and Maul damage increased by $s1%.", ua = "Шкода «Лютого укусу» і «Трощення» збільшена на $s1%." },
    { en = "Moonfire and Sunfire damage increased by $s1%.", ua = "Шкода «Місячного вогню» і «Сонячного вогню» збільшена на $s1%." },
    { en = "Survival Instincts and Barkskin reduce damage taken by an additional $s1%.", ua = "Інстинкти виживання та Кора додатково зменшують отримувану шкоду на $s1%." },
    { en = "Shred, Rake, and Skull Bash can be used in any form and shift you into Cat Form, if necessary. \n\n\n\nMangle can be used in any form and shifts you into Bear Form. \n\n\n\nWrath and Starfire shift you into Moonkin Form, if known.", ua = "Шматування, Дряпання та Удар черепом можна використовувати в будь-якій подобі, і за потреби вони переводять вас у Котячу подобу. \n\n\n\nКалічення можна використовувати в будь-якій подобі, і воно переводить вас у Подобу ведмедя. \n\n\n\nГнів і Зоряний вогонь переводять вас у Подобу місячного жерця, якщо вона вам відома." },
    { en = "$?c1[Casting Arcane Blast or Arcane Barrage][Consuming Hot Streak] grants you $?c1[${$449322s2/10}.1][${$449314s2/10}.1]% Haste for $449322d1. Stacks up to $449314u times. Multiple instances may overlap.", ua = "$?c1[Творення «Арканного удару» або «Арканного шквалу»][Витрачання «Гарячої смуги»] дарує вам $?c1[${$449322s2/10}.1][${$449314s2/10}.1]% Поспіху на $449322d1. Накопичується до $449314u разів. Кілька примірників можуть накладатися." },
    { en = "The bonuses provided by your Barrier spells persist an additional $?c1[$449336d][$1246023d] after your Barrier is removed.$?c1[][\n\n\n\nAdditionally, Cauterize no longer deals damage to you.]", ua = "Бонуси від ваших заклять-бар'єрів зберігаються ще $?c1[$449336d][$1246023d] після того, як бар'єр знято.$?c1[][\n\n\n\nКрім того, «Припікання» більше не завдає вам шкоди.]" },
    { en = "$?c2[Pyroclasm's damage bonus is increased by $s1% and Meteor grants Pyroclasm if talented.][Arcane Barrage deals $s2% increased damage to enemies affected by your Touch of the Magi.]", ua = "$?c2[Бонус до шкоди Піроклазму збільшено на $s1%, а Метеор надає Піроклазм, якщо обрано як талант.][Арканний шквал завдає на $s2% більше шкоди ворогам, на яких діє ваш Дотик магів.]" },
    { en = "When your Arcane Phoenix is summoned, it consumes all your Spellfire Spheres.\n\n\n\nEach Sphere consumed increases your spell damage during $?c1[Arcane Surge][Combustion] by $?c1[$s1][$s2]% and causes your Arcane Phoenix to cast an exceptional Arcane or Fire spell over its duration.", ua = "Коли ваш арканний фенікс закликаний, він поглинає всі ваші Сфери чаровогню.\n\n\n\nКожна поглинута Сфера збільшує шкоду ваших заклять під час $?c1[Арканного сплеску][Спалення] на $?c1[$s1][$s2]% і змушує вашого арканного фенікса протягом його дії сотворити виняткове арканне або вогняне закляття." },
    { en = "$?c2[Generating a Spellfire Sphere causes your next cast of Fire Blast to call down a storm of $s1 Meteorites on its target.][Arcane Barrage summons $s6 $LMeteorite:Meteorites; for every $s4 Arcane Salvo stacks consumed.]\n\n\n\n$@spellicon449559 $@spellname449559\n\n$@spelldesc449559", ua = "$?c2[Породження Сфери чарополум'я змушує ваше наступне творіння Вогняного вибуху прикликати бурю з $s1 метеоритів на його ціль.][Арканний шквал прикликає $s6 $Lметеорит:метеорити:метеоритів; за кожні $s4 спожитих зарядів Залпу аркани.]\n\n\n\n$@spellicon449559 $@spellname449559\n\n$@spelldesc449559" },
    { en = "When you cast $?c1[Arcane Surge][Combustion], its duration is extended by ${$s1/1000}.1 sec for each Spellfire Sphere you have, up to ${$s2/1000}.1 sec.", ua = "Коли ви творите $?c1[Сплеск аркани][Займання], його тривалість продовжується на ${$s1/1000}.1 сек. за кожну Сферу чаровогню, яку ви маєте, аж до ${$s2/1000}.1 сек." },
    { en = "If you generate a combo point in excess of what you can store, your next Ferocious Bite or Primal Wrath deals $449538s1% increased direct damage.", ua = "Якщо ти генеруєш очко комбо понад те, що можеш зберегти, твій наступний «Лютий укус» чи «Первісний гнів» завдає на $449538s1% більше прямої шкоди." },
    { en = "Roll causes you to become lighter than air, allowing you to double jump to dash forward a short distance once within $449609d, but the cooldown of Roll is increased by ${$s1/1000} sec.", ua = "Перекат робить тебе легшим за повітря: протягом $449609d можеш один раз виконати подвійний стрибок, щоб ринути вперед на коротку відстань, але перезарядження Перекату збільшено на ${$s1/1000} сек." },
    { en = "Spellfire Spheres can now stack up to $s2 times.", ua = "Сфери чарівного вогню тепер можуть накопичуватися до $s2 разів." },
    { en = "A demonic entity now inhabits your soul, allowing you to detect if a Soul Shard has a Succulent Soul when it's generated.\n\n\n\nConsuming a Succulent Soul unleashes your demonic soul, dealing $449801s1 Shadow damage to all enemies within $449801a1 yds of the target. Damage reduced beyond 8 targets.", ua = "Демонічна сутність тепер мешкає у вашій душі, дозволяючи виявляти, чи містить Уламок душі Соковиту душу в мить її створення.\n\n\n\nПоглинання Соковитої душі вивільняє вашу демонічну душу, завдаючи $449801s1 шкоди від тіні всім ворогам у межах $449801a1 ярдів від цілі. Шкода зменшується понад 8 цілей." },
    { en = "During $?c1[Arcane Surge][Combustion], you gain twice as many stacks of Mana Cascade.\n\n\n\nWhen your Arcane Phoenix expires, it empowers you, granting $?c1[Arcane Soul][Hyperthermia] for $?c1[${$s1/1000}.1][${$s2/1000}.1] sec.\n\n\n\n$?c1[$@spellicon451038$@spellname451038:\n\n$@spelldesc451038][$@spellicon383874 $@spellname383874:\n\n$@spellaura383874]", ua = "Під час $?c1[«Арканного сплеску»][«Згоряння»] ви отримуєте вдвічі більше стаків «Манового каскаду».\n\n\n\nКоли ваш арканний фенікс зникає, він наснажує вас, надаючи $?c1[«Арканну душу»][«Гіпертермію»] на $?c1[${$s1/1000}.1][${$s2/1000}.1] с.\n\n\n\n$?c1[$@spellicon451038$@spellname451038:\n\n$@spelldesc451038][$@spellicon383874 $@spellname383874:\n\n$@spellaura383874]" },
    { en = "$?s137043[Shadow Bolt and Drain Soul damage increased by $s2%. Nightfall increases the damage of Shadow Bolt and Drain Soul by an additional $s1%.][Shadow Bolt damage increased by $s2%. Power Siphon increases the damage of Demonbolt by an additional $s3%.]", ua = "$?s137043[Шкода Тіньової стріли і Висмоктування душі збільшена на $s2%. Сутінки збільшують шкоду Тіньової стріли і Висмоктування душі додатково на $s1%.][Шкода Тіньової стріли збільшена на $s2%. Викачування сили збільшує шкоду Демонічної стріли додатково на $s3%.]" },
    { en = "Unleashing your demonic soul bestows a fiendish entity unto the soul of its targets, dealing $450538o1 Shadow damage over $450538d.\n\n\n\nIf this effect is reapplied, any remaining damage will be added to the new Soul Anathema.", ua = "Вивільнення вашої демонічної душі насилає лиху сутність на душу її цілей, завдаючи $450538o1 шкоди від тіні впродовж $450538d.\n\n\n\nЯкщо цей ефект накладається повторно, будь-яка залишкова шкода додається до нової Анафеми душі." },
    { en = "Your Arcane Phoenix has picked up a few tricks, and will Spellsteal when it is summoned and when it expires.", ua = "Твій арканний фенікс навчився кількох трюків: він творить «Крадіжку заклять», коли його прикликають і коли він зникає." },
    { en = "Your demonic soul deals $s1% increased damage to $?s137043[targets affected by your Unstable Affliction.][the main target of Hand of Gul'dan.]", ua = "Ваша демонічна душа завдає на $s1% більше шкоди $?s137043[цілям під дією вашого Нестабільного прокляття.][основній цілі Руки Ґул'дана.]" },
    { en = "Damage dealt by your demonic soul is increased by $s1%.\n\n\n\nConsuming $?s137043[Nightfall][Demonic Core] feeds the demonic entity within you, causing it to appear and deal $?s137043[$449826s1][${$449826s1*($s2/100)}] Shadow damage to your target.", ua = "Шкода, завдана вашою демонічною душею, збільшена на $s1%.\n\n\n\nСпоживання $?s137043[Приходу ночі][Демонічного ядра] живить демонічну сутність усередині вас, через що вона з'являється і завдає вашій цілі $?s137043[$449826s1][${$449826s1*($s2/100)}] тіньової шкоди." },
    { en = "Soul Anathema damage increased by $s1% and is dealt $s2% faster.\n\n\n\nConsuming $?s137043[Nightfall][Demonic Core] activates Shared Fate or Feast of Souls.", ua = "Шкода від Прокляття душі підвищена на $s1% і завдається на $s2% швидше.\n\n\n\nСпоживання $?s137043[Сутінків][Демонічного ядра] активує Спільну долю або Бенкет душ." },
    { en = "$?s137043[Corruption deals damage $s1% faster and Haunt grants Nightfall.][Wild Imp damage increased by $s2% and Wild Imps that are imploded have an additional $s3% chance to grant a Demonic Core.]", ua = "$?s137043[Псування завдає шкоди на $s1% швидше, а Переслідування надає Сутінки.][Шкода Диких бісенят збільшена на $s2%, а імплозовані Дикі бісенята мають додатковий $s3% шанс надати Демонічне ядро.]" },
    { en = "Your $?s137043[Dark Harvest spell is empowered by the demonic entity within you, causing it to grant ${$s2} Soul Shard that each contain a Succulent Soul every 1 sec while channeled.][Summon Demonic Tyrant spell is empowered by the demonic entity within you, causing it to grant ${$449858s1/10} Soul Shards that each contain a Succulent Soul.]", ua = "Ваше закляття $?s137043[Темний урожай посилене демонічною сутністю всередині вас, через що воно дає ${$s2} Уламок душі, кожен з яких містить Соковиту душу, щосекунди під час підтримання.][Прикликання демонічного тирана посилене демонічною сутністю всередині вас, через що воно дає ${$449858s1/10} Уламків душі, кожен з яких містить Соковиту душу.]" },
    { en = "Tiger's Fury increases your Haste by $449646s1% and Energy recovery rate by $449646s2% for $449646d.", ua = "«Лють тигра» збільшує твій поспіх на $449646s1%, а швидкість відновлення енергії — на $449646s2% на $449646d." },
    { en = "You always gain the benefit of Soulburn when consuming a Healthstone, increasing its healing by 30% and increasing your maximum health by 20% for 12 sec.", ua = "Ти завжди отримуєш ефект «Спалення душі», коли використовуєш камінь здоров'я, що збільшує його зцілення на 30%, а твоє максимальне здоров'я — на 20% на 12 сек." },
    { en = "Dark Pact now shields you for an additional $s1% of the sacrificed health.", ua = "«Темний пакт» тепер додатково захищає тебе щитом на $s1% від пожертвуваного здоров'я." },
    { en = "When you kill a target, its tortured soul is flung into a nearby enemy for $450591d. This effect inflicts $450593s1 Shadow damage to enemies within $450593a1 yds every $450591t1 sec.\n\n\n\nDeals reduced damage beyond $s1 targets.", ua = "Коли ти вбиваєш ціль, її змучена душа вселяється в найближчого ворога на $450591d. Цей ефект завдає $450593s1 шкоди Тінню ворогам у межах $450593a1 м кожні $450591t1 сек.\n\n\n\nЗавдає зменшеної шкоди після $s1 цілей." },
    { en = "When you kill a target, you have a chance to generate a Soul Shard that is guaranteed to be a Succulent Soul.", ua = "Коли ти вбиваєш ціль, маєш шанс створити осколок душі, який гарантовано буде соковитою душею." },
    { en = "Fel Domination cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Панування Скверни» скорочене на ${$s1/-1000} сек." },
    { en = "Halo now centers around you and returns to you after it reaches its maximum distance, healing allies and damaging enemies each time it passes through them.", ua = "«Німб» тепер центрується на тобі й повертається до тебе, досягнувши максимальної відстані, зцілюючи союзників і завдаючи шкоди ворогам щоразу, коли проходить крізь них." },
    { en = "Halo damage and healing is increased by $s1%.", ua = "Шкоду й зцілення «Німба» збільшено на $s1%." },
    { en = "While Entropic Rift is active, your $?c3[Shadow damage is increased by $s1%] [Atonement healing is increased by $s2%].", ua = "Поки активний Ентропійний розлом, ваша $?c3[шкода Тіні збільшена на $s1%] [зцілення Спокути збільшене на $s2%]." },
    { en = "Void Blast increases the duration of Entropic Rift by $?c1[${$s1}.1][${$s3}.1] sec, up to a maximum of $s2 sec.", ua = "Удар Порожнечі збільшує тривалість Ентропійного розлому на $?c1[${$s1}.1][${$s3}.1] с, до максимуму $s2 с." },
    { en = "Summoning an Entropic Rift $?c1[extends the duration of your $s4 shortest Atonements by $s1 sec][grants you Shadowy Insight].", ua = "Прикликання Ентропійного розлому $?c1[подовжує тривалість $s4 ваших найкоротших ефектів «Спокути» на $s1 с][надає вам «Тіньове прозріння»]." },
    { en = "Your heightened reflexes allow you to react swiftly to the presence of enemies, causing you to quickly lunge to the nearest enemy in front of you within $450156r yards after you Roll.", ua = "Загострені рефлекси дозволяють тобі миттєво реагувати на присутність ворогів: після «Перекату» ти швидко кидаєшся до найближчого ворога перед собою в межах $450156r м." },
    { en = "Starsurge increases the damage the target takes from your periodic effects and Shooting Stars by $450214s1% for $450214d. Reapplying this effect extends its duration, up to ${$s1/1000} sec.", ua = "Зоряний сплеск збільшує шкоду, якої ціль зазнає від твоїх періодичних ефектів і Падучих зір, на $450214s1% на $450214d. Повторне накладання цього ефекту подовжує його тривалість, до ${$s1/1000} сек." },
    { en = "Targets you Roll through are snared by $450342s1% for $450342d.", ua = "Цілі, крізь які ти проходиш «Перекатом», сповільнюються на $450342s1% на $450342d." },
    { en = "When Eclipse ends or when you enter combat, enter a Dreamstate, reducing the cast time of your next $450346u Starfires or Wraths by $450346s1%.", ua = "Коли «Затемнення» завершується або ти вступаєш у бій, ти входиш у «Стан Сну», що зменшує час творення наступних $450346u «Зоряних вогнів» чи «Гнівів» на $450346s1%." },
    { en = "Casting Wrath has a $s1% chance to make your next Starsurge or Starfall free.\n\n\n\nCasting Starfire has a $s2% chance to make your next Starsurge or Starfall free.", ua = "Прочитання Гніву має $s1% шанс зробити ваш наступний Зорепад або Зоряний прибій безкоштовним.\n\n\n\nПрочитання Зоряного вогню має $s2% шанс зробити ваш наступний Зорепад або Зоряний прибій безкоштовним." },
    { en = "Consuming Sentinel's Mark grants you an absorb shield equal to ${$s1}.1% of your maximum health.", ua = "Витрата «Мітки вартового» дарує тобі щит поглинання, рівний ${$s1}.1% твого максимального здоров'я." },
    { en = "$?c2[Steady Shot][Kill Command] grants an additional $s1 Focus and its damage is increased by $s4%. \n\n\n\nMaximum Focus increased by $s2.", ua = "$?c2[Упевнений постріл][Наказ убити] дарує додатково $s1 зосередженості, а його шкода підвищена на $s4%. \n\n\n\nМаксимальна зосередженість підвищена на $s2." },
    { en = "Entropic Rift upgrades $?c3[Mind Blast][Smite] into Void Blast while it is active.\n\n\n\n$?c1[$@spellname450215:\n\n$@spelldesc450215][$@spellname450983:\n\n$@spelldesc450983]", ua = "Поки Ентропійний Розлом активний, він покращує $?c3[Удар розуму][Кара] до Вибуху Порожнечі.\n\n\n\n$?c1[$@spellname450215:\n\n$@spelldesc450215][$@spellname450983:\n\n$@spelldesc450983]" },
    { en = "Magical damage done increased by $s1% and healing done increased by $s2%.", ua = "Завдана магічна шкода збільшена на $s1%, а зцілення — на $s2%." },
    { en = "Increases your Physical damage done by $s1% and Avoidance increased by $s2%.", ua = "Збільшує завдану тобою фізичну шкоду на $s1%, а уникнення — на $s2%." },
    { en = "Paralysis now removes all Enrage effects from its target.", ua = "Тепер «Параліч» знімає з цілі всі ефекти шалу." },
    { en = "Reduces the cooldown of Ring of Peace by ${$s1/-1000} sec and Song of Chi-Ji's cast time is reduced by ${$s2/-1000}.1 sec.", ua = "Зменшує перезарядження «Кільця миру» на ${$s1/-1000} сек., а час творення «Пісні Чі-Джі» — на ${$s2/-1000}.1 сек." },
    { en = "The duration of snare effects on you is reduced by $s1%.", ua = "Тривалість сповільнювальних ефектів на тобі зменшена на $s1%." },
    { en = "Store vitality from $?a137023[$s1%][$s2%] of your damage dealt and $?a137023[$s3%][$s4%] of your $?a137023[effective ][]healing.$?a137024[ Vitality stored from overhealing is reduced.][]\n\n\n\nFor $450711d after casting $?a137023[Celestial Brew or Celestial Infusion][Thunder Focus Tea] your spells and abilities draw upon the stored vitality to deal $s6% additional $?a137023[damage over $450763d][healing over $450769d].", ua = "Накопичує життєву силу з $?a137023[$s1%][$s2%] завданої тобою шкоди і $?a137023[$s3%][$s4%] твого $?a137023[дієвого ][]зцілення.$?a137024[ Життєва сила, накопичена з надлишкового зцілення, зменшена.][]\n\n\n\nПротягом $450711d після сотворення $?a137023[Небесного варева чи Небесного вливання][Чаю громового зосередження] твої закляття і здібності черпають накопичену життєву силу, щоб завдати $s6% додаткової $?a137023[шкоди протягом $450763d][зцілення протягом $450769d]." },
    { en = "The range of Disable is increased by $s1 yds.\n\n \n\nThe duration of Crashing Momentum is increased by ${$s3/1000} sec and its snare now reduces movement speed by an additional $s2%.", ua = "Дальність Знесилення збільшується на $s1 ярдів.\n\n \n\nТривалість Нищівної інерції збільшується на ${$s3/1000} сек., а її пастка тепер зменшує швидкість руху ще на $s2%." },
    { en = "Roll and Chi Torpedo travel a small distance further.", ua = "Перекат і Чі-торпеда переносять тебе трохи далі." },
    { en = "When Aspect of Harmony $?a450870[deals damage or heals]?a137023[deals damage][heals], it has a chance to spread to a nearby $?a450870[target]?a137023[enemy][ally]. When you directly $?a450870[attack or heal]?a137023[attack][heal] an affected target, it has a chance to intensify, withdrawing additional vitality to increase its effect by up to $450508s9%.\n\n\n\n$?a137023[Keg Smash][Vivify] no longer contributes vitality. While Aspect of Harmony is not active, $?a137023[Keg Smash][Vivify] instead draws on available vitality to deal an additional $s2% $?a137023[damage over $1292919d][healing over $1292922d].\n\n\n\nVitality stored by other abilities is increased by $s3%.", ua = "Коли Аспект гармонії $?a450870[завдає шкоди або зцілює]?a137023[завдає шкоди][зцілює], він має шанс поширитися на $?a450870[ціль]?a137023[ворога][союзника] поблизу. Коли ти безпосередньо $?a450870[атакуєш або зцілюєш]?a137023[атакуєш][зцілюєш] охоплену ціль, він має шанс посилитися, черпаючи додаткову життєву силу, щоб збільшити свій ефект до $450508s9%.\n\n\n\n$?a137023[Удар барилом][Пожвавлення] більше не дає життєвої сили. Поки Аспект гармонії неактивний, $?a137023[Удар барилом][Пожвавлення] натомість черпає доступну життєву силу, щоб завдати додаткові $s2% $?a137023[шкоди протягом $1292919d][зцілення протягом $1292922d].\n\n\n\nЖиттєва сила, накопичена іншими здібностями, збільшена на $s3%." },
    { en = "While out of combat, your movement speed is increased by $450552s1%.", ua = "Поза боєм твоя швидкість руху збільшена на $450552s1%." },
    { en = "Starsurge or Starfall increase your current Eclipse's Arcane or Nature damage bonus by an additional $s1%, up to $s2%.", ua = "Зоряний сплеск або Зорепад додатково збільшують бонус до арканної чи природної шкоди твого поточного Затемнення на $s1%, до $s2%." },
    { en = "Transcendence: Transfer immediately heals you for $450559s1% of your maximum health.", ua = "«Трансценденція: перенесення» миттєво зцілює тебе на $450559s1% максимального здоров'я." },
    { en = "You gain a bonus effect based on your current health.\n\n\n\nAbove $s1% health: Movement speed increased by $450574s1%. This bonus stacks with similar effects.\n\n\n\nBetween $s1% and $s2% health: Damage taken reduced by $450572s1%.\n\n\n\nBelow $s2% health: Healing received increased by $450571s1%.", ua = "Ви отримуєте бонусний ефект залежно від вашого поточного здоров'я.\n\n\n\nПонад $s1% здоров'я: швидкість пересування збільшено на $450574s1%. Цей бонус нашаровується зі схожими ефектами.\n\n\n\nМіж $s1% та $s2% здоров'я: отримувана шкода зменшена на $450572s1%.\n\n\n\nНижче $s2% здоров'я: отримуване зцілення збільшено на $450571s1%." },
    { en = "Transcendence: Transfer snares targets within $450596A2 yds by $450596s1% for $450596d when cast.", ua = "«Трансценденція: перенесення» при творенні сповільнює цілі в радіусі $450596A2 м на $450596s1% на $450596d." },
    { en = "Increases maximum Astral Power by ${$s1/10}. Entering Eclipse reduces the Astral Power cost of your next Starsurge or Starfall by ${$450599s1/-10}.", ua = "Збільшує максимум астральної сили на ${$s1/10}. Вхід у затемнення зменшує вартість твого наступного «Зоряного сплеску» чи «Зорепаду» на ${$450599s1/-10} астральної сили." },
    { en = "$?c1[While Entropic Rift is active, Atonement healing with Void Blast and Penance is $s2% more effective.][Void Blast generates ${$s1/100} additional Insanity.]", ua = "$?c1[Поки «Ентропійний розлом» активний, зцілення «Спокути» від «Удару Порожнечі» і «Покути» на $s2% ефективніше.][«Удар Порожнечі» генерує ${$s1/100} додаткового Безумства.]" },
    { en = "Your auto attacks have a chance to generate $s1-$s2 Flurry Charges. When you cast $?c3[Fists of Fury][Keg Smash], unleash all Flurry Charges, dealing $450617s1 Physical damage per charge.", ua = "Ваші автоатаки мають шанс згенерувати $s1-$s2 заряди шквалу. Коли ви творите $?c3[«Кулаки люті»][«Удар барилом»], усі заряди шквалу вивільняються, завдаючи $450617s1 фізичної шкоди за кожен заряд." },
    { en = "Roll removes a snare effect once every $proccooldown sec.", ua = "Перекат знімає ефект сповільнення раз на $proccooldown сек." },
    { en = "Successfully interrupting an enemy reduces the cooldown of Paralysis and Roll by ${$s1/-1000} sec.", ua = "Успішне переривання ворожого закляття скорочує перезарядження «Паралічу» та «Перекату» на ${$s1/-1000} сек." },
    { en = "While your Celestial is active, you cannot be slowed below $s2% normal movement speed.", ua = "Поки твій Небожитель активний, тебе не можна сповільнити нижче $s2% звичайної швидкості руху." },
    { en = "Fireball always critically strikes enemies below $s3% health.\n\n\n\nWhen Fireball or Scorch damage an enemy below $1254311s2% health, Fireball deals $s1% increased damage and Scorch deals $s2% increased damage.", ua = "Вогняна куля завжди завдає критичного удару ворогам, у яких менше ніж $s3% здоров'я.\n\n\n\nКоли Вогняна куля чи Обпалення завдають шкоди ворогові, у якого менше ніж $1254311s2% здоров'я, Вогняна куля завдає на $s1% більше шкоди, а Обпалення — на $s2% більше шкоди." },
    { en = "Your spell critical strike chance is increased by ${$s3/1000}.1%.\n\n\n\nCombustion increases your critical strike damage by ${$s3/1000}.1%.", ua = "Ваш шанс критичного удару заклять збільшено на ${$s3/1000}.1%.\n\n\n\nЗаймання збільшує вашу критичну шкоду на ${$s3/1000}.1%." },
    { en = "When Aspect of Harmony ends, any remaining vitality is expelled as $?a137023[damage over $450820d][healing over $450805d], split among nearby targets.", ua = "Коли Аспект гармонії завершується, будь-яка залишкова життєва сила вивільняється як $?a137023[шкода протягом $450820d][зцілення протягом $450805d], розподілена між цілями поблизу." },
    { en = "During Aspect of Harmony, $?a137023[Expel Harm and Vivify withdraw vitality to heal for an additional $s1% over $450769d][Rising Sun Kick, Blackout Kick, and Tiger Palm also withdraw vitality to damage enemies for an additional $s2% over $450763d].", ua = "Під час Аспекту гармонії $?a137023[Вигнання шкоди та Оживлення вилучають життєву силу, щоб зцілити додатково на $s1% протягом $450769d][Удар висхідного сонця, Затьмарливий удар та Долоня тигра також вилучають життєву силу, щоб завдати ворогам додатково $s2% шкоди протягом $450763d]." },
    { en = "$?c1[Chi Burst and Chi Wave deal][Chi Wave deals] $s1% increased damage and healing.", ua = "$?c1[«Сплеск Ці» та «Хвиля Ці» завдають][«Хвиля Ці» завдає] на $s1% більше шкоди та зцілення." },
    { en = "Casting a Physical spell or ability increases the damage and healing of your next Fire or Nature spell or ability by $451508s1%, and vice versa. Stacks up to $451508U.", ua = "Творення Фізичного закляття чи здібності підвищує шкоду й зцілення вашого наступного закляття чи здібності Вогню або Природи на $451508s1%, і навпаки. Накопичується до $451508U." },
    { en = "$?a137023[Celestial Brew and Celestial Infusion have][Thunder Focus Tea has] $s1 additional charge.", ua = "$?a137023[Небесний напій і Небесне вливання мають][Чай громового зосередження має] $s1 додатковий заряд." },
    { en = "$?a450391[Chi Wave][Chi Burst] increases vitality stored by $451084s1% for $451084d.", ua = "$?a450391[Хвиля ці][Вибух ці] підвищує накопичену життєву силу на $451084s1% протягом $451084d." },
    { en = "$?a137023[][Rising Sun Kick, ]Blackout Kick and Tiger Palm contribute $s1% additional vitality.", ua = "$?a137023[][Удар сонця, що сходить, ]Затьмарний удар і Тигряча долоня додають $s1% додаткової життєвої сили." },
    { en = "Flurry Strikes have $s1% additional chance to critically strike.", ua = "«Шквал ударів» має додатковий шанс $s1% завдати критичного удару." },
    { en = "Enemies who die within $451037d of being damaged by a Flurry Strike explode, dealing $451039s1 physical damage to uncontrolled enemies within $451039a1 yds.", ua = "Вороги, що гинуть протягом $451037d після отримання шкоди від «Шквального удару», вибухають, завдаючи $451039s1 фізичної шкоди неконтрольованим ворогам у радіусі $451039a1 м." },
    { en = "Your agility is increased by $s1%.", ua = "Твою спритність збільшено на $s1%." },
    { en = "Haste increased by $s1%.", ua = "Поспіх збільшено на $s1%." },
    { en = "Auto attack critical strikes generate double the amount of Flurry Charges.\n\n\n\n$?c3[Fists of Fury damage increased by $s2%.][\n\nKeg Smash damage increased by $s3%.]", ua = "Критичні удари автоатак створюють удвічі більше Зарядів шквалу.\n\n\n\n$?c3[Шкода Кулаків люті збільшена на $s2%.][\n\nШкода Удару діжкою збільшена на $s3%.]" },
    { en = "Energy spenders deal an additional $s1% damage.\n\nThe cooldown of $?c1[Invoke Niuzao, the Black Ox is reduced by ${$s6/-1000} sec][Zenith is reduced by ${$s4/-1000} sec].", ua = "Здібності, що витрачають енергію, завдають на $s1% більше шкоди.\n\nПерезарядження $?c1[Заклику Ніузао, Чорного Вола, зменшено на ${$s6/-1000} сек][Зеніту зменшено на ${$s4/-1000} сек]." },
    { en = "Your attacks penetrate $s1% armor.", ua = "Твої атаки пробивають $s1% броні." },
    { en = "When your health drops below $s1%, summon Whirling Steel, increasing your parry chance and avoidance by $451214s1% for $451214d.\n\n\n\nThis effect can not occur more than once every $proccooldown sec.", ua = "Коли ваше здоров'я падає нижче $s1%, прикликає «Вихрову сталь», збільшуючи ваш шанс парирування та уникнення на $451214s1% протягом $451214d.\n\n\n\nЦей ефект може спрацьовувати не частіше ніж раз на $proccooldown с." },
    { en = "When you dodge or parry an attack, reduce all damage taken by $451230s1% for the next $451230d.", ua = "Коли ти ухиляєшся від атаки або парируєш її, вся отримувана шкода зменшується на $451230s1% протягом наступних $451230d." },
    { en = "Blackout Kick deals an additional $s1% critical damage.", ua = "«Удар затьмарення» завдає додаткові $s1% критичної шкоди." },
    { en = "Casting $?a137023[Purifying Brew][Enveloping Mist] stores $<value> additional vitality.", ua = "Творення $?a137023[Очищувального вару][Огортального туману] накопичує $<value> додаткової життєвої сили." },
    { en = "$?c3[Void Torrent can be used while moving. ][]While Entropic Rift is active, you move $s1% faster.", ua = "$?c3[Потік Порожнечі можна застосовувати в русі. ][]Поки активний Ентропійний Розлом, ви рухаєтеся на $s1% швидше." },
    { en = "$?a137023[][Rising Sun Kick, ]Blackout Kick and Tiger Palm deal $s1% additional damage to enemies in a line in front of you. Damage reduced above $s2 targets.", ua = "$?a137023[][Удар сонця, що сходить, ]Затьмарний удар і Тигряча долоня завдають на $s1% більше шкоди ворогам на лінії перед вами. Шкода зменшується понад $s2 цілей." },
    { en = "$?a137023[Fortifying Brew applies a Chi Cocoon, absorbing $<value> damage][Fortifying Brew grants $s1% Stagger].", ua = "$?a137023[Зміцнювальний напій накладає Кокон ці, поглинаючи $<value> шкоди][Зміцнювальний напій надає $s1% Розподілу]." },
    { en = "$?c1[Arcane Blast damage increased by $s3%.\n\n\n\nArcane Pulse damage increased by $s4%][Pyroblast damage increased by $s1%.\n\n\n\nFlamestrike damage increased by $s2%].", ua = "$?c1[Шкода від Арканного удару збільшена на $s3%.\n\n\n\nШкода від Арканного пульсу збільшена на $s4%][Шкода від Піровибуху збільшена на $s1%.\n\n\n\nШкода від Удару полум'я збільшена на $s2%]." },
    { en = "$?a137023[Purifying Brew removes $s1% additional Stagger and causes you to absorb up to $<value> incoming Stagger][When cast on yourself, your single-target healing spells heal for $s2% more and restore an additional $451452o1 health over $451452d].", ua = "$?a137023[Очищувальний напій знімає на $s1% більше Розподілу й дозволяє вам поглинути до $<value> вхідного Розподілу][Коли застосовані на себе, ваші зцілювальні закляття по одній цілі зцілюють на $s2% більше та відновлюють додатково $451452o1 здоров'я протягом $451452d]." },
    { en = "Casting Tiger's Lust reduces the remaining cooldown on Roll by ${$s1/1000} sec.", ua = "Використання «Тигрячої жаги» скорочує решту перезарядження «Перекату» на ${$s1/1000} сек." },
    { en = "Tiger's Lust grants $452701s1% movement speed to up to $452701i allies near its target.", ua = "Тигрячий запал дарує $452701s1% швидкості пересування для до $452701i союзників поблизу його цілі." },
    { en = "Entropic Rift slows enemies by up to $s1%, increased the closer they are to its center.", ua = "«Ентропійний розлом» сповільнює ворогів до $s1% — що ближче вони до його центру, то сильніше." },
    { en = "Wrath, Starsurge, and Starfire damage increased by $s1%. $?!a137013[\n\n\n\nStarsurge's cooldown is reduced by ${-$s2/1000} sec and its mana cost is reduced by $s3%.][]", ua = "Шкода від Гніву, Зоряного сплеску та Зоряного вогню підвищена на $s1%. $?!a137013[\n\n\n\nПерезарядження Зоряного сплеску зменшено на ${-$s2/1000} сек., а його вартість мани знижено на $s3%.][]" },
    { en = "When Entropic Rift ends, a Voidwraith is summoned from the collapsed rift for $451235d.\n\n\n\n$@spellicon451235$@spellname451235\n\n$@spelldesc451235", ua = "Коли Ентропійний Розлом завершується, з колапсованого розлому прикликається Мара Порожнечі на $451235d.\n\n\n\n$@spellicon451235$@spellname451235\n\n$@spelldesc451235" },
    { en = "Fists of Fury's damage is increased by $s1% of your haste and Fists of Fury does $451297s1% more damage each time it deals damage, resetting when Fists of Fury ends.\n\n\n\nYour auto attack speed is increased by $451298s1% for $451298d after Fists of Fury ends.", ua = "Шкода Кулаків люті збільшується на $s1% вашого Поспіху, а Кулаки люті завдають на $451297s1% більше шкоди щоразу, коли завдають шкоди; ефект скидається, коли Кулаки люті завершуються.\n\n\n\nШвидкість ваших автоатак збільшується на $451298s1% протягом $451298d після завершення Кулаків люті." },
    { en = "Every $t1 sec siphon an amount equal to $s1% of your health from an ally within $s3 yds if they are higher health than you.", ua = "Кожні $t1 сек. висмоктує в союзника в межах $s3 м обсяг здоров'я, що дорівнює $s1% твого здоров'я, якщо в нього здоров'я більше, ніж у тебе." },
    { en = "Casting Pyroblast or Flamestrike while Hot Streak is active has a $s1% chance to repeat the spell cast at $s2% effectiveness.\n\n\n\nThis effect counts as consuming Hot Streak.", ua = "Творіння Піровибуху чи Полум'яного удару, поки активна Жарка смуга, з імовірністю $s1% повторює закляття з ефективністю $s2%.\n\n\n\nЦей ефект зараховується як споживання Жаркої смуги." },
    { en = "The cooldown of Rising Sun Kick is reduced by ${$s1/-1000}.1 sec and the damage of Blackout Kick is increased by $s2%.", ua = "Перезарядження «Копняка висхідного сонця» скорочено на ${$s1/-1000}.1 сек., а шкоду «Копняка затьмарення» збільшено на $s2%." },
    { en = "When you consume Blackout Kick!, you have a $s1% chance to generate $s2 Chi.", ua = "Коли ти споживаєш «Удар затьмарення!», є $s1% шансу створити $s2 ці." },
    { en = "You have a $s1% chance to gain Blackout Kick! after consuming Dance of Chi-Ji.", ua = "Ти маєш $s1% шансу отримати «Удар затьмарення!» після споживання «Танцю Чі-Цзі»." },
    { en = "Strike of the Windlord and Whirling Dragon Punch have a $s1% chance to activate Dance of Chi-Ji.", ua = "Удар Володаря вітрів і Вихровий удар дракона з імовірністю $s1% активують Танець Чі-Джі." },
    { en = "Strike of the Windlord and Whirling Dragon Punch grant $s1 stacks of Teachings of the Monastery.\n\n\n\nTeachings of the Monastery can now stack up to $s4 times.", ua = "Удар повелителя вітрів і Вихровий удар дракона надають $s1 стаків Вчень монастиря.\n\n\n\nВчення монастиря тепер можуть накопичуватися до $s4 разів." },
    { en = "You absorb $s3% of all magic damage taken. Absorbing Shadow damage heals you for $s2% of the amount absorbed.", ua = "Ти поглинаєш $s3% усієї отриманої магічної шкоди. Поглинання шкоди Тіні зцілює тебе на $s2% від поглинутої кількості." },
    { en = "Jadefire Stomp now strikes $s4 target, but deals $s2% increased damage and healing.", ua = "Тепер «Тупіт нефритового вогню» вражає $s4 ціль, але завдає на $s2% більше шкоди й зцілення." },
    { en = "Strike of the Windlord and Whirling Dragon Punch have their cooldowns reduced by ${$s1/-1000} sec and their damage is increased by $s2%.", ua = "Перезарядження «Удару володаря вітрів» і «Вихрового удару дракона» скорочується на ${$s1/-1000} сек., а їхня шкода збільшується на $s2%." },
    { en = "Your auto attacks have a $s1% chance to instead kick your target dealing $451839s1 Physical damage. Damage increased while using a two-handed weapon.", ua = "Твої автоатаки мають $s1% шансу натомість завдати цілі удару ногою, що завдає $451839s1 фізичної шкоди. Шкоду збільшено, поки ти використовуєш дворучну зброю." },
    { en = "Shadow Word: Death consumes absorb shields from your target, dealing $32379s1 extra damage to them and granting you $?c3[$s3 Insanity][$s2% mana] if a shield was present.", ua = "Тіньове слово: Смерть споживає поглинальні щити з вашої цілі, завдаючи їй $32379s1 додаткової шкоди та надаючи вам $?c3[$s3 безумства][$s2% мани], якщо щит був присутній." },
    { en = "Casting Combustion refreshes up to $s1 $Lcharge:charges; of Fire Blast.", ua = "Творення Самозаймання поновлює до $s1 $Lзаряду:зарядів; Вогняного вибуху." },
    { en = "Your spells and abilities have a chance to activate Flurry of Xuen, unleashing a barrage of deadly swipes to deal ${$452130s1*$s1} Physical damage in a $452130A1 yd cone, damage reduced beyond $s2 targets.\n\n\n\nInvoking Xuen, the White Tiger activates Flurry of Xuen.", ua = "Ваші закляття та здібності мають шанс активувати «Шквал Сюеня», вивільняючи зливу смертоносних змахів, що завдають ${$452130s1*$s1} фізичної шкоди в конусі $452130A1 м, зі зменшеною шкодою понад $s2 цілей.\n\n\n\nПрикликання Сюеня, Білого Тигра, активує «Шквал Сюеня»." },
    { en = "When a spell consumes Clearcasting, its damage is increased by $s1%.", ua = "Коли закляття поглинає «Ясне творення», його шкода збільшується на $s1%." },
    { en = "$?a212612[][Void ]Metamorphosis now also $?a212612[causes Demon Blades to generate $162264s10 additional Fury][greatly empowers Voidblade and Hungering Slash].\n\n\n\nWhile demon form is active, the first cast of each empowered ability induces a $?a212612[Demonsurge][Voidsurge], causing you to explode with $?a212612[Fel][Void] energy, dealing $?a212612[$452416s1 Chaos][$1246160s1 Cosmic] damage to nearby enemies. Deals reduced damage beyond $452416s3 targets.", ua = "$?a212612[][Метаморфоза Порожнечі ]Метаморфоза тепер також $?a212612[змушує Клинки демона генерувати $162264s10 додаткової люті][значно підсилює Клинок Порожнечі та Ненаситний розтин].\n\n\n\nПоки активна демонічна форма, перше застосування кожної підсиленої здібності викликає $?a212612[Сплеск демона][Сплеск Порожнечі], тож ви вибухаєте енергією $?a212612[Скверни][Порожнечі], завдаючи $?a212612[$452416s1 хаотичної][$1246160s1 космічної] шкоди ворогам поблизу. Завдає зменшеної шкоди понад $452416s3 цілей." },
    { en = "$?c1[Chaos][Void] Nova slows enemies by $453263s1% and reduces attack and cast speed by $453263s2% for $453263d after its stun fades.", ua = "$?c1[«Нова хаосу»][«Нова Порожнечі»] сповільнює ворогів на $453263s1% та зменшує швидкість атаки й творення на $453263s2% протягом $453263d після того, як її оглушення згасає." },
    { en = "Movement speed increased by $s1% per $s2 Fury.", ua = "Швидкість руху збільшено на $s1% за кожні $s2 од. люті." },
    { en = "$?a212612[Demonsurge][Voidsurge] deals $s1% increased damage when it strikes a single target.\n\n\n\nEach additional target reduces this bonus by $s2%.", ua = "$?a212612[Сплеск демона][Сплеск Порожнечі] завдає на $s1% більше шкоди, коли вражає одну ціль.\n\n\n\nКожна додаткова ціль зменшує цей бонус на $s2%." },
    { en = "$s2% of all non-Fire damage taken is instead taken as Fire damage over $453286d.\n\n\n\nFire damage taken reduced by $S3%.", ua = "$s2% усієї отриманої не вогняної шкоди натомість отримується як вогняна шкода протягом $453286d.\n\n\n\nОтримувану вогняну шкоду зменшено на $S3%." },
    { en = "Leech granted by Soul Rending increased by $s1% and an additional $s2% while $?a212612[][Void ]Metamorphosis is active.", ua = "Висмоктування, надане Роздиранням душ, збільшено на $s1% і додатково на $s2%, поки активна $?a212612[][Порожнечева ]Метаморфоза." },
    { en = "$?a212612[Your blades burn with Fel energy, causing the damage from Chaos Strike, Throw Glaive, Blade Dance's First Blood, and auto-attacks to burn for an additional $s1% damage as Fire over $453177d][Your blades burn with Cosmic energy, causing your Voidblade, Hungering Slash, and Throw Glaive to deal an additional $s2% damage as Cosmic damage.\n\n\n\nReap damage increased by $s3%].", ua = "$?a212612[Ваші клинки палають енергією Скверни, тож шкода від Удару хаосу, Метання глефи, Першої крові Танцю клинків та автоатак випалює додатково $s1% шкоди як вогняну протягом $453177d][Ваші клинки палають космічною енергією, тож ваш Клинок Порожнечі, Ненаситний розтин та Метання глефи завдають додатково $s2% шкоди як космічну.\n\n\n\nШкоду Жнив збільшено на $s3%]." },
    { en = "$?a212612[When you activate Metamorphosis, reset the cooldown of Immolation Aura][Entering Void Metamorphosis resets the cooldown of Voidblade and The Hunt.\n\n\n\nThe Hunt deals $s2% increased damage and resets the cooldown of Soul Immolation].", ua = "$?a212612[Коли ви активуєте Метаморфозу, перезарядження Аури спалення скидається][Вхід у Метаморфозу Порожнечі скидає перезарядження Клинка Порожнечі та Полювання.\n\n\n\nПолювання завдає на $s2% більше шкоди та скидає перезарядження Спалення душі]." },
    { en = "The effects of your demon form persist outside of it in a weakened state, increasing $?a212612[Chaos Strike and Blade Dance damage by $453314s2%, and Haste by $453314s1%][Mastery: Monster Within's effectiveness by $453314s4%].", ua = "Ефекти вашої демонічної форми зберігаються поза нею в послабленому стані, збільшуючи $?a212612[шкоду від Удару хаосу та Танцю клинків на $453314s2%, а Поспіх — на $453314s1%][ефективність Майстерності: Монстра всередині на $453314s4%]." },
    { en = "Maximum Fury increased by $?a212612[$s1][$s2].$?c3[\n\n\n\nVoid Ray damage increased by $s3%.][]", ua = "Максимальна лють збільшена на $?a212612[$s1][$s2].$?c3[\n\n\n\nШкода Променя Порожнечі збільшена на $s3%.][]" },
    { en = "$?a212612[Eye Beam][Void Ray] applies Student of Suffering to you, increasing Mastery by ${$453239s1*$mas}.1% and granting $453236s1 Fury every $453239t2 sec, for $453239d.", ua = "$?a212612[Промінь ока][Промінь Порожнечі] накладає на вас Учня страждання, збільшуючи Майстерність на ${$453239s1*$mas}.1% і даючи $453236s1 Люті кожні $453239t2 сек упродовж $453239d." },
    { en = "$?a212612[Immolation Aura][Hungering Slash] has $s1 yd increased radius and $s2% increased critical strike damage bonus.", ua = "$?a212612[Аура самоспалення][Голодний розтин] має на $s1 ярд більший радіус і на $s2% більший бонус до критичної шкоди." },
    { en = "$?a212612[Agility][Intellect] increased by $?a212612[$452550s1][$452550s2]% while not in demon form.$?c3[\n\n\n\nCollapsing Star damage increased by $s2%.][]", ua = "$?a212612[Спритність][Інтелект] збільшено на $?a212612[$452550s1][$452550s2]%, поки ви не в демонічній формі.$?c3[\n\n\n\nШкоду Зорі, що згасає, збільшено на $s2%.][]" },
    { en = "Activating $?a212612[][Void ]Metamorphosis greatly empowers $?a212612[Eye Beam, Immolation Aura][The Hunt].\n\n\n\n$?a212612[Demonsurge][Voidsurge] damage is increased by $?a212612[${$452416s2}][${$1246160s2}]% for each time it previously triggered while your demon form is active.", ua = "Активація $?a212612[][Метаморфози Порожнечі ]Метаморфози значно підсилює $?a212612[Промінь з очей, Ауру спалення][Полювання].\n\n\n\nШкоду $?a212612[Сплеску демона][Сплеску Порожнечі] збільшено на $?a212612[${$452416s2}][${$1246160s2}]% за кожне попереднє спрацювання, поки активна ваша демонічна форма." },
    { en = "Defensive Stance additionally reduces magic damage you take by $s1%.", ua = "Захисна стійка додатково зменшує отримувану тобою магічну шкоду на $s1%." },
    { en = "Flip a Fatebound Coin each time a finishing move consumes $s1 or more combo points. Heads increases the damage of your attacks by ${$452923s4+$452923s1}%, lasting $452923d or until you flip Tails. Tails deals $452538s1 Cosmic damage to your target.\n\n\n\nFor each time the same face is flipped in a row, Heads increases damage by an additional $452923s1% and Tails increases its damage by $452917s1%.", ua = "Підкидає Монету долі щоразу, коли завершальний прийом витрачає $s1 або більше очок комбо. «Орел» збільшує шкоду ваших атак на ${$452923s4+$452923s1}% на $452923d або доки не випаде «решка». «Решка» завдає цілі $452538s1 космічної шкоди.\n\n\n\nЗа кожен раз, коли поспіль випадає той самий бік, «орел» збільшує шкоду додатково на $452923s1%, а «решка» збільшує свою шкоду на $452917s1%." },
    { en = "Reduces the cast time of Soulstone and Create Healthstone by $s1%.", ua = "Зменшує час творення «Каменя душі» та «Створення каменя здоров'я» на $s1%." },
    { en = "During Arcane Surge, your Familiar fires $s1 bolts instead of 1.\n\n\n\nDamage from your Arcane Familiar has a $s2% chance to grant you up to $454020s1% of your maximum mana.", ua = "Під час Арканного сплеску ваш Фамільяр випускає $s1 розряди замість 1.\n\n\n\nШкода від вашого Арканного фамільяра з імовірністю $s2% повертає вам до $454020s1% вашої максимальної мани." },
    { en = "$?a445465[Wither][Corruption] deals $s1% increased damage and its periodic damage heals you for $s2% of the damage dealt.", ua = "$?a445465[В'янення][Розтління] завдає на $s1% більше шкоди, а його періодична шкода зцілює вас на $s2% завданої шкоди." },
    { en = "Reduces the cast time of Shadow Bolt by $s1% and increases its damage by $s2%.", ua = "Зменшує час творення «Стріли тіні» на $s1% і збільшує її шкоду на $s2%." },
    { en = "Increases the critical strike chance of Agony, $?a445465[Wither][Corruption], and Unstable Affliction by $s1%.", ua = "Підвищує шанс критичного удару Агонії, $?a445465[В'янення][Псування] та Нестабільного недуги на $s1%." },
    { en = "Increases critical strike damage dealt by Agony, $?a445465[Wither][Corruption], and Unstable Affliction by $s1%.", ua = "Підвищує критичну шкоду від Агонії, $?a445465[В'янення][Псування] та Нестабільного недуги на $s1%." },
    { en = "Increases the damage dealt by your spells and your demon by $s1%.", ua = "Збільшує шкоду, яку завдають твої закляття і твій демон, на $s1%." },
    { en = "Casting Halo also causes you to create a Halo around you at $s1% effectiveness every $453112t sec for $453112d.", ua = "Творення «Ореолу» також створює довкола тебе «Ореол» з ефективністю $s1% кожні $453112t сек. протягом $453112d." },
    { en = "Shadow Bolt and Drain Soul have a chance to trigger a Shadow Bolt Volley, dealing $<damage> Shadow damage to $s1 enemies within $453176a1 yards of your current target.", ua = "Тіньова стріла та Висмоктування душі мають шанс спричинити Залп тіньових стріл, завдаючи $<damage> шкоди темрявою $s1 ворогам у межах $453176a1 ярдів від вашої поточної цілі." },
    { en = "The cast time of Pyroblast and Flamestrike is reduced by $s1%.", ua = "Час творення «Піровибуху» та «Удару полум'я» зменшено на $s1%." },
    { en = "Fatebound Coins flipped by $?a137036[Dispatch][Envenom] are $s1% more likely to match the same face as the last flip.", ua = "Долезв'язані монети, підкинуті $?a137036[Розправою][Отруєнням], мають на $s1% більшу ймовірність випасти тим самим боком, що й попереднього разу." },
    { en = "Activating $?a137036[Adrenaline Rush][Deathmark] flips a Fatebound Coin and causes it to land on its edge, counting as both Heads and Tails.", ua = "Активація $?a137036[Приплив адреналіну][Мітки смерті] підкидає Долезалежну монету так, що вона падає на ребро, зараховуючись водночас як орел і як решка." },
    { en = "Increases the attack speed of your Dreadstalkers by $s1% and their critical strike chance by $s2%.", ua = "Збільшує швидкість атаки твоїх жахоловців на $s1%, а їхній шанс критичного удару — на $s2%." },
    { en = "Power Word: Fortitude grants you an additional $s1% stamina.", ua = "«Слово сили: Стійкість» дарує тобі додатково $s1% витривалості." },
    { en = "$?a137031[Increases the duration of Spirit of Redemption by ${$s1/1000} sec.][Increases the duration of Dispersion by ${$s2/1000} sec.]", ua = "$?a137031[Збільшує тривалість Духа спокути на ${$s1/1000} с.][Збільшує тривалість Розсіювання на ${$s2/1000} с.]" },
    { en = "Creating a Halo $?a137033[upgrades your next Mind Flay to Mind Flay: Insanity.\n\n\n\n$@spellicon391403 $@spellname391403\n\n$@spelldesc391403][grants Surge of Light.\n\n\n\n$@spellicon109186 $@spellname109186\n\n$@spelldesc109186]", ua = "Створення Німба $?a137033[покращує ваше наступне Виснаження розуму до Виснаження розуму: Безумство.\n\n\n\n$@spellicon391403 $@spellname391403\n\n$@spelldesc391403][дає Сплеск Світла.\n\n\n\n$@spellicon109186 $@spellname109186\n\n$@spelldesc109186]" },
    { en = "$?a137033[Increases the damage done by Mind Flay: Insanity by $s2%.\n\n\n\n][Your spells affected by Surge of Light heal for $s1% more while Surge of Light is active.]", ua = "$?a137033[Збільшує шкоду від Виснаження розуму: Безумство на $s2%.\n\n\n\n][Ваші закляття, на які діє Сплеск Світла, зцілюють на $s1% більше, поки Сплеск Світла активний.]" },
    { en = "Increases the critical strike chance of your primary demon by $s1% of your critical strike chance.", ua = "Збільшує шанс критичного удару твого основного демона на $s1% від твого шансу критичного удару." },
    { en = "$?a137031&?a1246517[Consuming Surge of Light reduces the cooldown of Holy Word: Serenity by ${$s1/-1000} sec.]?a137031&!a1246517[Consuming Surge of Light reduces the cooldown of Holy Word: Sanctify by ${$s1/-1000} sec.][Casting Mind Flay: Insanity has a $s2% chance to conjure Shadowy Apparitions.]", ua = "$?a137031&?a1246517[Споживання Сплеску світла зменшує перезарядження Священного слова: Безтурботність на ${$s1/-1000} сек.]?a137031&!a1246517[Споживання Сплеску світла зменшує перезарядження Священного слова: Освячення на ${$s1/-1000} сек.][Прочитання Терзання розуму: Безумство має $s2% шансу прикликати Тіньові з'яви.]" },
    { en = "$?a137033[Enemies damaged by your Halo take $453850s1% increased damage from you for $453846d, stacking up to $453846U times.][Allies healed by your Halo receive $453850s1% increased healing from you for $453850d, stacking up to $453850U times.]", ua = "$?a137033[Вороги, поранені вашим Ореолом, отримують на $453850s1% більше шкоди від вас протягом $453846d, з нашаруванням до $453846U разів.][Союзники, зцілені вашим Ореолом, отримують на $453850s1% більше зцілення від вас протягом $453850d, з нашаруванням до $453850U разів.]" },
    { en = "Halo damage reduces enemy movement speed by $453848s1% for $453848d, stacking up to $453848U times.", ua = "Шкода від «Німба» зменшує швидкість пересування ворога на $453848s1% на $453848d, накопичуючись до $453848U разів." },
    { en = "Damaging critical strikes dealt by you and your demons deal ${$s1+200}% damage instead of the usual 200%.", ua = "Критичні удари, завдані тобою та твоїми демонами, завдають ${$s1+200}% шкоди замість звичайних 200%." },
    { en = "$?a137031[Your healing done is increased by $s3% while Apotheosis is active.][Your damage dealt is increased by $s1% while Voidform is active.]", ua = "$?a137031[Зцілення, яке ви чините, збільшено на $s3%, поки активний Апофеоз.][Шкода, яку ви завдаєте, збільшена на $s1%, поки активна форма Порожнечі.]" },
    { en = "Psychic Scream creates an image of you at your location. After $s1 sec, the image will let out a Psychic Scream.", ua = "«Психічний крик» створює твоє відображення там, де ти стоїш. Через $s1 сек. відображення видає «Психічний крик»." },
    { en = "Creating a Halo extends the duration of $?a137031[Apotheosis][Voidform] by ${$s1/1000} sec. If $?a137031[Apotheosis][Voidform] is not active, up to $454002U seconds is stored.\n\n\n\nWhile out of combat or affected by a loss of control effect, the duration of $?a137031[Apotheosis][Voidform] is paused for up to $s2 sec.", ua = "Створення Німба продовжує тривалість $?a137031[Апофеозу][Форми Порожнечі] на ${$s1/1000} с. Якщо $?a137031[Апофеоз][Форма Порожнечі] не активний, зберігається до $454002U с.\n\n\n\nПоза боєм або під дією ефекту втрати контролю тривалість $?a137031[Апофеозу][Форми Порожнечі] призупиняється на час до $s2 с." },
    { en = "$?s137040[Each Maelstrom spent has a ${$s1/100}.2% chance to upgrade][Each Maelstrom Weapon spent has a ${$s2/100}.2% chance to upgrade] your next Lightning Bolt to Tempest.\n\n\n\n$@spelltooltip452201", ua = "$?s137040[Кожен витрачений Вир має ${$s1/100}.2% шанс поліпшити][Кожна витрачена «Зброя Виру» має ${$s2/100}.2% шанс поліпшити] твою наступну «Стрілу блискавки» до «Буревію».\n\n\n\n$@spelltooltip452201" },
    { en = "Increases the critical strike chance of your Nature damage spells by $s1% and the critical strike damage of your Nature spells by $s2%.", ua = "Збільшує шанс критичного удару твоїх заклять зі шкодою від природи на $s1%, а шкоду критичних ударів твоїх заклять природи — на $s2%." },
    { en = "Tempest increases your movement speed by $454025s1% for $454025d.", ua = "«Буревій» прискорює твій рух на $454025s1% на $454025d." },
    { en = "$?s137040[Reduces the cooldown of Stormkeeper by ${$s1/-1000} sec.][Doom Winds summons a Nature Feral Spirit for ${$s2/1000} sec.\n\n\n\n$@spellicon469314$@spellname469314\n\nAn Elemental Spirit infused with Nature magic, granting the summoner with $224125s1% increased Nature damage and $224125s3% Physical damage for ${$s2/1000} sec.]", ua = "$?s137040[Зменшує перезарядження «Хранителя бурі» на ${$s1/-1000} сек.][«Вітри судьби» прикликають Дикого духа природи на ${$s2/1000} сек.\n\n\n\n$@spellicon469314$@spellname469314\n\nСтихійний дух, насичений магією природи, що надає закличникові на ${$s2/1000} сек. на $224125s1% більше шкоди як Природа та на $224125s3% більше фізичної шкоди.]" },
    { en = "Lightning Shield reduces the damage you take by $s1%.", ua = "«Щит блискавок» зменшує отримувану тобою шкоду на $s1%." },
    { en = "You have a $s2% chance to absorb $s1% of any damage taken.", ua = "Ти маєш $s2% шансу поглинути $s1% будь-якої отриманої шкоди." },
    { en = "Casting Tempest grants Surging Currents, increasing the effectiveness of your next Chain Heal or Healing Surge by $454376s1%, up to ${$454376s1*$454376u}%.", ua = "Творення «Буревію» дає «Бурхливі течії», що збільшують ефективність твого наступного «Ланцюгового зцілення» чи «Сплеску зцілення» на $454376s1%, аж до ${$454376s1*$454376u}%." },
    { en = "Spending $?s137040[Maelstrom][Maelstrom Weapon stacks] grants you $454394s1% haste for $454394d.\n\n\n\nMultiple applications may overlap.", ua = "Витрата $?s137040[Виру][зарядів Зброї виру] надає вам $454394s1% поспіху протягом $454394d.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "$?a383281[Sinister Strike and Ambush generate]?a137036[Sinister Strike generates][Mutilate, Ambush, and Fan of Knives generate] $454421s1 additional combo point $?a383281[when they grant Opportunity]?a137036[when it grants Opportunity][when they trigger Seal Fate].", ua = "$?a383281[Зловісний удар і Засідка генерують]?a137036[Зловісний удар генерує][Калічення, Засідка та Віяло ножів генерують] $454421s1 додаткову бойову одиницю $?a383281[коли надають Нагоду]?a137036[коли надає Нагоду][коли спрацьовує Печатка долі]." },
    { en = "You cannot be slowed below $s1% of normal movement speed while your Fatebound Coin flips have an active streak of at least $s2 flips matching the same face.", ua = "Тебе не можна сповільнити нижче $s1% звичайної швидкості руху, поки серія підкидань твоєї Доленосної монети налічує щонайменше $s2 однакових випадінь поспіль." },
    { en = "$?a137037[Shadowstep][Grappling Hook] may be used a second time within $457333d with no cooldown, but its total cooldown is increased by ${$s3/1000} sec.", ua = "$?a137037[Тіньовий крок][Гак-кішка] можна використати вдруге протягом $457333d без перезарядження, але його загальне перезарядження збільшується на ${$s3/1000} с." },
    { en = "$?a137037[Weapon poisons have $s1% increased application chance][Sinister Strike has $s2% increased chance to strike an additional time and grant Opportunity] and your Fatebound Coins flipped have an additional $s3% chance to match the same face as the last flip.", ua = "$?a137037[Отрути для зброї мають на $s1% більший шанс накладення][Лиховісний удар має на $s2% більший шанс ударити ще раз і дати Нагоду] і ваші підкинуті Долезв'язані монети мають додатковий $s3% шанс випасти тим самим боком, що й попереднє підкидання." },
    { en = "When you would be healed above maximum health, you instead convert an amount equal to $s1% of your critical strike chance to a heal over time effect.", ua = "Коли зцілення мало б перевищити твоє максимальне здоров'я, ти натомість перетворюєш кількість, що дорівнює $s1% твого шансу критичного удару, на ефект поступового зцілення." },
    { en = "You have a $s1% chance to not reset your Elusive Brawler stacks after a successful dodge.", ua = "Ти маєш $s1% шансу не скинути накопичення «Невловимого бійця» після успішного ухилення." },
    { en = "Increases the critical strike chance of your Destruction spells by $s1%.", ua = "Збільшує шанс критичного удару твоїх заклять Руйнування на $s1%." },
    { en = "Increases the damage done by your Fire spells by $s1% and reduces the cast time of your Incinerate spell by $s2%.", ua = "Збільшує шкоду твоїх вогняних заклять на $s1% і скорочує час творення Спопеління на $s2%." },
    { en = "Chains of Ice now also roots enemies for $454787d but its cooldown is increased to ${$s2/1000} sec.", ua = "Крижані ланцюги тепер також знерухомлюють ворогів на $454787d, але їхнє перезарядження збільшено до ${$s2/1000} сек." },
    { en = "Your chance to be critically struck is reduced by $s2% and your Armor is increased by $s1%.", ua = "Шанс отримати критичний удар зменшено на $s2%, а твою броню збільшено на $s1%." },
    { en = "When you would pull an enemy, the damage they deal to you is reduced by $454824s1% for $454824d.", ua = "Коли ти притягуєш ворога, шкода, яку він тобі завдає, зменшується на $454824s1% на $454824d." },
    { en = "Anti-Magic Shell increases healing received by $s1%.", ua = "Антимагічна оболонка збільшує отримуване зцілення на $s1%." },
    { en = "Magic damage taken is reduced by $s1% and the duration of harmful Magic effects against you are reduced by $s2%.", ua = "Отримувана магічна шкода зменшена на $s1%, а тривалість шкідливих магічних ефектів на тобі зменшена на $s2%." },
    { en = "Casting Anti-Magic Shell grants $454863i nearby allies a Lesser Anti-Magic Shell that Absorbs up to $454863s1 magic damage and reduces the duration of harmful Magic effects against them by $454863s2%.", ua = "Творення Антимагічної оболонки надає $454863i союзникам поблизу Меншу антимагічну оболонку, що поглинає до $454863s1 магічної шкоди та зменшує тривалість шкідливих магічних ефектів проти них на $454863s2%." },
    { en = "$?s137040[Earthquake][Crash Lightning] and Chain Lightning damage increased by $s1%.", ua = "Шкода від $?s137040[Землетрусу][Громового удару] і Ланцюгової блискавки збільшена на $s1%." },
    { en = "Tiger Palm's chance to activate Blackout Kick! is increased by $s1% and Tiger Palm's damage is increased by $s2%.", ua = "Шанс «Долоні тигра» активувати «Копняк затьмарення!» збільшено на $s1%, а шкоду «Долоні тигра» — на $s2%." },
    { en = "The range of your helpful magics is increased by $s1 yards.", ua = "Дальність твоєї помічної магії збільшено на $s1 м." },
    { en = "Casting Purifying Brew grants a charge of Ox Stance. When you take damage that is greater than $s1% of your current health, a charge is consumed to increase the amount you Stagger.", ua = "Використання «Очисного варева» дає заряд «Стійки вола». Коли ти отримуєш шкоду, що перевищує $s1% твого поточного здоров'я, один заряд витрачається, збільшуючи обсяг шкоди, яку ти відтерміновуєш." },
    { en = "Envenom's effect increases the damage of Envenom by $s1%.", ua = "Ефект Отруєння збільшує шкоду від Отруєння на $s1%." },
    { en = "Tempest grants ${$455089s1*$mas}% Mastery for $455089d.", ua = "«Буревій» дарує ${$455089s1*$mas}% майстерності на $455089d." },
    { en = "$?s137040[Casting Tempest grants a charge of Stormkeeper.][Tempest causes your next Chain Lightning to be instant cast, deal $455097s2% increased damage, and cast an additional time.\n\n\n\nCan accumulate up to $470532U charges.]", ua = "$?s137040[Застосування «Буревію» надає заряд «Хранителя бурі».][«Буревій» робить твоє наступне «Ланцюгове блискавковиння» миттєвим, додає йому $455097s2% шкоди й творить його ще раз.\n\n\n\nМоже накопичити до $470532U зарядів.]" },
    { en = "$?s137040[Lightning Bolt, Tempest, and Chain Lightning have a $s1% chance to cause an additional Elemental Overload.][Lightning Bolt, Tempest, and Chain Lightning have a $s2% chance to refund $s3 Maelstrom Weapon stacks.]", ua = "$?s137040[Блискавка, Буревій і Ланцюгова блискавка мають $s1% шанс викликати додаткове Стихійне перевантаження.][Блискавка, Буревій і Ланцюгова блискавка мають $s2% шанс повернути $s3 заряди Зброї виру.]" },
    { en = "$?s137040[Lightning Rod targets now also take $s2% of the damage that Tempest deals, and Tempest also applies Lightning Rod effect.][Gain the effects of the Lightning Rod talent:\n\n\n\n$@spellicon210689 $@spellname210689\n\n$@spelldesc210689]", ua = "$?s137040[Цілі «Громовідводу» тепер також зазнають $s2% шкоди, яку завдає «Буревій», а «Буревій» також накладає ефект «Громовідводу».][Надає ефекти таланту «Громовідвід»:\n\n\n\n$@spellicon210689 $@spellname210689\n\n$@spelldesc210689]" },
    { en = "$?a137040[Each Maelstrom spent has an additional ${$s3/100}.2% chance to upgrade your next Lightning Bolt to Tempest.][Stormstrike has a small chance to upgrade your next Lightning Bolt to Tempest.]", ua = "$?a137040[Кожен витрачений Вир має додатковий ${$s3/100}.2% шанс підвищити вашу наступну Блискавку до Бурі.][Штормовий удар має невеликий шанс підвищити вашу наступну Блискавку до Бурі.]" },
    { en = "Your Magus of the Dead Shadow Bolt now fires a volley of Shadow Bolts at up to $s2 nearby enemies.", ua = "Тіньова стріла твого магуса мертвих тепер випускає залп тіньових стріл у щонайбільше $s2 ворогів поблизу." },
    { en = "When you fall below $s1% health, you gain an absorb for $s2% of your recently Purified damage, or a minimum of $s3% of your maximum health. Cannot occur more than once every $455180d.", ua = "Коли твоє здоров'я падає нижче $s1%, ти отримуєш щит, що поглинає шкоду, в розмірі $s2% нещодавно очищеної шкоди, але не менше $s3% максимального здоров'я. Не може спрацьовувати частіше, ніж раз на $455180d." },
    { en = "Auto-attacks increase auto-attack damage by $455144s1% and movement speed by $455144s2% for $455144d, stacking up to $455144u times.", ua = "Автоатаки збільшують шкоду від автоатак на $455144s1%, а швидкість руху — на $455144s2% протягом $455144d, складається до $455144u разів." },
    { en = "Consuming Sudden Doom summons forth a Lesser Ghoul to assist you for $275430d.", ua = "Поглинання Раптової погибелі прикликає нижчого гуля, що допомагає тобі протягом $275430d." },
    { en = "Your diseases deal $s1% more damage and have a $s3% increased chance to critically strike.", ua = "Твої хвороби завдають на $s1% більше шкоди та мають на $s3% вищий шанс критичного удару." },
    { en = "Festering Strike now follows up with a Festering Scythe that costs no Runes.\n\n\n\n$@spellicon458128$@spellname458128\n\n$@spelldesc458128", ua = "За Гнійним ударом тепер слідує Гнійна коса, що не коштує Рун.\n\n\n\n$@spellicon458128$@spellname458128\n\n$@spelldesc458128" },
    { en = "When your Barrier is removed, reduce its cooldown by ${$s1/1000} sec.", ua = "Коли твій бар'єр зникає, його перезарядження скорочується на ${$s1/1000} сек." },
    { en = "Your Summon Vilefiend becomes Summon Gloomhound and learns the following ability:\n\n\n\n$@spellicon455489 $@spellname455489\n\n$@spelldesc455489", ua = "Ваш Виклик мерзотника стає Викликом похмурого пса й вивчає таку здібність:\n\n\n\n$@spellicon455489 $@spellname455489\n\n$@spelldesc455489" },
    { en = "Your Summon Vilefiend becomes Summon Charhound and learns the following ability:\n\n\n\n$@spellicon428453 $@spellname428453\n\n$@spelldesc428453", ua = "Ваш Виклик мерзотника стає Викликом обвугленого пса й вивчає таку здібність:\n\n\n\n$@spellicon428453 $@spellname428453\n\n$@spelldesc428453" },
    { en = "When you remove an effect with Soothe or $?s88423[Nature's Cure][Remove Corruption], gain a combo point and heal for $s1% of your maximum health. If you are at full health an injured party or raid member will be healed instead.", ua = "Коли ти знімаєш ефект «Заспокоєнням» або $?s88423[«Зціленням природи»][«Зняттям зіпсуття»], то отримуєш очко комбо та зцілюєшся на $s1% свого максимального здоров'я. Якщо твоє здоров'я повне, замість тебе зцілиться поранений член групи чи рейду." },
    { en = "$?a137041[Casting Sundering within $s2 yards of your Surging Totem causes it to create a Tremor at $s1% effectiveness at the target area.][Allies affected by your Earthliving effect receive $s3% increased healing from you.]", ua = "$?a137041[Творення Розколу в межах $s2 ярдів від вашого Буряного тотема змушує його створити Здригання з $s1% ефективності в цільовій ділянці.][Союзники під дією вашого ефекту Земне життя отримують від вас на $s3% більше зцілення.]" },
    { en = "$?a137013[Entering Eclipse increases your haste by $455801s1% for $455801d][Swiftmend healing is increased by $s2%].", ua = "$?a137013[Входження в Затемнення збільшує твій поспіх на $455801s1% протягом $455801d][Швидке зцілення відновлює на $s2% більше здоров'я]." },
    { en = "Each foe struck with Glacial Advance has a chance to transform your next Frost Strike into Frostbane. The chance increases with the number of Razorice stacks on the target.\n\n\n\n$@spellicon1228433$@spellname1228433\n\n$@spelldesc1228433", ua = "Кожен ворог, вражений Льодовиковим наступом, має шанс перетворити ваш наступний Морозний удар на Морозну згубу. Шанс зростає з кількістю стаків Гострольоду на цілі.\n\n\n\n$@spellicon1228433$@spellname1228433\n\n$@spelldesc1228433" },
    { en = "Consuming Killing Machine fires a Glacial Advance through your target at $s1% effectiveness.", ua = "Поглинання Машини вбивства випускає Льодовиковий наступ крізь твою ціль з $s1% ефективності." },
    { en = "When Howling Blast consumes Rime, $s1% of the damage it deals is gathered into the next cast of Remorseless Winter, up to $s2 times.", ua = "Коли «Виючий шквал» поглинає «Паморозь», $s1% завданої ним шкоди накопичується для наступного застосування «Безжальної зими», до $s2 разів." },
    { en = "Your Runic Power spending abilities have a chance to additionally deal $s1% of the damage dealt over 4 sec.", ua = "Твої здібності, що витрачають рунічну силу, мають шанс додатково завдати $s1% завданої шкоди протягом 4 сек." },
    { en = "While Pillar of Frost is active your auto-attack critical strikes increase its duration by $s1 sec, up to a maximum of $s2 sec.", ua = "Поки діє «Стовп морозу», критичні удари твоїх автоатак подовжують його тривалість на $s1 сек., до максимуму $s2 сек." },
    { en = "Activating $?a137048[Demoralizing Shout][Recklessness] grants a charge of Thunder Blast.", ua = "Активація $?a137048[Деморалізуючого крику][Безрозсудності] надає заряд Громового вибуху." },
    { en = "Increases the damage of Chaos Bolt by $s1% and reduces its cast time by ${$s2/-1000}.1 sec.", ua = "Збільшує шкоду Стріли хаосу на $s1% і скорочує час її творення на ${$s2/-1000}.1 сек." },
    { en = "Cloak of Shadows duration increased by ${$s1/1000} sec.", ua = "Тривалість «Плаща тіней» збільшена на ${$s1/1000} сек." },
    { en = "Evasion reduces magical damage taken by ${-$s1}%. \n\n\n\nCloak of Shadows reduces physical damage taken by ${-$s2}%.", ua = "«Ухиляння» зменшує отримувану магічну шкоду на ${-$s1}%. \n\n\n\n«Плащ тіней» зменшує отримувану фізичну шкоду на ${-$s2}%." },
    { en = "$?c1[Garrote][Shadowstrike] applies $s1 stacks of Deathstalker's Mark to your target, unless Deathstalker's Mark is already active. You learn Mark for Death.\n\n\n\nWhen you spend $s2 or more combo points on attacks against a Marked target you consume an application of Deathstalker's Mark, dealing $457157s1 Plague damage.\n\n\n\n$@spellicon1293340\n\n$@spellname1293340\n\n$@spelldesc1293340", ua = "$?c1[Гарота][Тіньовий удар] накладає $s1 зарядів Мітки смертеслідця на вашу ціль, якщо Мітка смертеслідця ще не активна. Ви опановуєте Позначення на смерть.\n\n\n\nКоли ви витрачаєте $s2 чи більше очок комбо на атаки проти позначеної цілі, ви споживаєте один заряд Мітки смертеслідця, завдаючи $457157s1 шкоди Чумою.\n\n\n\n$@spellicon1293340\n\n$@spellname1293340\n\n$@spelldesc1293340" },
    { en = "Auto-attacks against Marked targets deal an additional $457193s1 Plague damage.", ua = "Автоатаки по позначених цілях завдають додатково $457193s1 шкоди чумою." },
    { en = "Damage dealt to targets other than your Marked target deals $s1% Plague damage to your Marked target.", ua = "Шкода, завдана цілям, окрім твоєї позначеної цілі, завдає позначеній цілі $s1% шкоди чумою." },
    { en = "After $?c1[Deathmark][Shadow Blades] expires, gain $?c1[$457273s1][$457273s2]% increased $?c1[Nature][Shadow] damage for $457273d.", ua = "Після завершення $?c1[Мітки смерті][Тіньових клинків] ви отримуєте на $?c1[$457273s1][$457273s2]% збільшену шкоду $?c1[природою][тінню] протягом $457273d." },
    { en = "Each time you consume a stack of Deathstalker's Mark, reduce the cooldown of Shadowstep by ${$s1/-1000} sec.", ua = "Щоразу, коли ти поглинаєш заряд Мітки смертоловця, перезарядження Тіньового кроку скорочується на ${$s1/-1000} сек." },
    { en = "When you consume the final Deathstalker's Mark from a target or your target dies, gain $457280s1 Energy and Darkest Night, causing your next $?c1[Envenom][Eviscerate] cast with 5 or more combo points to critically strike, deal $457280s2% additional damage, and apply $457280s3 stacks of Deathstalker's Mark to the target if no other Deathstalker's Mark is active.\n\n\n\n$?c1[Envenom][Eviscerate] cast with Darkest Night does not consume a stack of active Deathstalker's Marks.", ua = "Коли ти споживаєш останню «Мітку смертовистежника» з цілі або твоя ціль гине, ти отримуєш $457280s1 Енергії та «Найтемнішу ніч», через що твій наступний застосунок $?c1[«Отруєння»][«Потрошіння»] з 5 або більше очками комбо завдає критичного удару, наносить $457280s2% додаткової шкоди й накладає $457280s3 заряд(и) «Мітки смертовистежника» на ціль, якщо немає іншої активної «Мітки смертовистежника».\n\n\n\n$?c1[«Отруєння»][«Потрошіння»], застосоване з «Найтемнішою ніччю», не споживає заряду активних «Міток смертовистежника»." },
    { en = "$?a137037 [Kingsbane][Shadow Dance] additionally increases the damage of your next $?a137037 [two Envenoms][Eviscerate or Black Powder] by $?a137037[$457167s1][$457167s2]%.", ua = "$?a137037 [Згуба королів][Танець тіней] додатково збільшує шкоду ваших наступних $?a137037 [двох Отруєнь][Випатрання чи Чорного пороху] на $?a137037[$457167s1][$457167s2]%." },
    { en = "Shroud of Concealment duration increased by ${$s1/1000} sec.", ua = "Тривалість «Покрову приховування» збільшено на ${$s1/1000} сек." },
    { en = "If you have critically struck with $?c1[Fan of Knives][Shuriken Storm], increase the critical strike chance of $?c1[Fan of Knives][Shuriken Storm] and $?c1[Crimson Tempest][Black Powder] by $457115s1% and critical strike damage by $457115s2% for $457115d.", ua = "Якщо ви завдали критичного удару закляттям $?c1[Віяло ножів][Буря сюрикенів], то на $457115d підвищуєте шанс критичного удару $?c1[Віяла ножів][Бурі сюрикенів] та $?c1[Багряної бурі][Чорного пороху] на $457115s1% і критичну шкоду на $457115s2%." },
    { en = "$?c1[Fan of Knives][Shuriken Storm] and $?c1[Crimson Tempest][Black Powder] deal $?c1[$s1][$s3]% additional damage while $?c1[$s2 or more enemies are afflicted with Rupture][Find Weakness is active].", ua = "$?c1[«Віяло ножів»][«Буря сюрікенів»] та $?c1[«Багряна буря»][«Чорний порох»] завдають на $?c1[$s1][$s3]% більше шкоди, поки $?c1[$s2 або більше ворогів вражені «Розривом»][«Пошук слабкості» активний]." },
    { en = "Arcane Surge's damage is increased by an additional $s1% based on your mana spent.", ua = "Шкода «Арканного сплеску» збільшується на додаткові $s1% залежно від витраченої мани." },
    { en = "Anti-Magic Shell now removes all harmful magical effects when activated, but its cooldown is increased by ${$s2/1000} sec.", ua = "Антимагічна оболонка тепер знімає всі шкідливі магічні ефекти при активації, але її перезарядження збільшено на ${$s2/1000} сек." },
    { en = "While Combustion is not active, damage from Ignite has a small chance to make your next Scorch instant, deal $458964s3% increased damage, and deal damage as though your target was below $s2% health.", ua = "Поки «Згоряння» не активне, шкода від «Займання» має невеликий шанс зробити твій наступний «Опік» миттєвим, збільшити його шкоду на $458964s3% і завдати її так, ніби в цілі менше за $s2% здоров'я." },
    { en = "Damage dealt to targets below $s1% health is increased by $458910s1%.", ua = "Шкода, завдана цілям із рівнем здоров'я нижче $s1%, збільшується на $458910s1%." },
    { en = "At the end of your Fists of Fury channel, you release a Jadefire Stomp, dealing $1248815s1 damage to $s2 $Lenemy:enemies; in front of you and increasing your movement speed by $451943s1% for $451943d.", ua = "Наприкінці підтримання ваших Кулаків люті ви вивільняєте Тупіт нефритового вогню, завдаючи $1248815s1 шкоди $s2 $Lворогу:ворогам; перед вами та збільшуючи вашу швидкість пересування на $451943s1% протягом $451943d." },
    { en = "Increases the damage of Haunt by $s1% and reduces its cast time by ${$abs($s2/1000)}.1 sec.", ua = "Збільшує шкоду Наслання на $s1% і скорочує час його творення на ${$abs($s2/1000)}.1 сек." },
    { en = "$?s231895[Crusade][Avenging Wrath] is replaced with Radiant Glory.\n\n\n\n$@spellicon458359$@spellname458359\n\nWake of Ashes activates $?s231895[Crusade for $454373d][Avenging Wrath for $454351d].", ua = "$?s231895[Хрестовий похід][Гнів месника] замінюється на Промענисту славу.\n\n\n\n$@spellicon458359$@spellname458359\n\nСлід попелу активує $?s231895[Хрестовий похід на $454373d][Гнів месника на $454351d]." },
    { en = "Allies with Renewing Mist receive $s1% more healing from you and Renewing Mist's duration is increased by ${$s2/1000} sec.", ua = "Союзники з «Відновлювальним туманом» отримують від тебе на $s1% більше зцілення, а тривалість «Відновлювального туману» збільшено на ${$s2/1000} сек." },
    { en = "Arcane Intellect grants you an additional $s1% Intellect.", ua = "«Арканний інтелект» дає тобі додатково $s1% інтелекту." },
    { en = "When you would pull an enemy generate $s1 charge of Bone Shield.\n\n\n\n$@spellicon195181 |cFFFFFFFF$@spellname195181|r\n\n$@spelldesc195181", ua = "Коли ви притягуєте ворога, ви отримуєте $s1 заряд Кістяного щита.\n\n\n\n$@spellicon195181 |cFFFFFFFF$@spellname195181|r\n\n$@spelldesc195181" },
    { en = "Critical Strike chance increased by $s1%. This effect is increased by $s2% while Xuen, the White Tiger is active.", ua = "Шанс критичного удару збільшено на $s1%. Цей ефект посилюється на $s2%, поки активний Сюень, Білий Тигр." },
    { en = "Desperate Prayer lasts an additional ${$s1/1000} sec.\n\n\n\nAngelic Bulwark's absorption effect is increased by $s2% of your maximum health.", ua = "«Відчайдушна молитва» триває на ${$s1/1000} сек. довше.\n\n\n\nЕфект поглинання «Янгольського бастіону» збільшено на $s2% вашого максимального здоров'я." },
    { en = "Consumption now contributes to your Mastery: Blood Shield.\n\n\n\nEach time an enemy strikes your Blood Shield, the cooldown of Consumption has chance to be reset.", ua = "Поглинання тепер додає до вашої Майстерності: Кривавий щит.\n\n\n\nЩоразу, коли ворог б'є по вашому Кривавому щиту, є шанс скинути перезарядження Поглинання." },
    { en = "Parrying an attack grants you a charge of Bloodied Blade, increasing your Strength by ${$460499s1/10}.1%, up to ${$460499u*$460499s1/10}.1% for $460499d.\n\n\n\nAt $460499U stacks, your next parry consumes all charges to unleash a Heart Strike at ${100+$s1}% effectiveness, and increases your Strength by $460500s1% for $460500d.", ua = "Парирування атаки надає вам заряд Закривавленого клинка, збільшуючи вашу Силу на ${$460499s1/10}.1%, до ${$460499u*$460499s1/10}.1% на $460499d.\n\n\n\nПри $460499U стаках ваше наступне парирування споживає всі заряди, щоб вивільнити Удар у серце з ${100+$s1}% ефективністю та збільшити вашу Силу на $460500s1% на $460500d." },
    { en = "Upheaval causes an aftershock at its location, dealing $s1% of its damage $s2 additional $Ltime:times;.", ua = "Здвиг спричиняє повторний поштовх у своєму місці, завдаючи $s1% своєї шкоди $s2 додатковий $Lраз:рази:разів;." },
    { en = "Critical strikes from your Agony, $?a445465[Wither][Corruption], and Unstable Affliction have a chance to grant Nightfall.", ua = "Критичні удари вашої Агонії, $?a445465[Згасання][Розтління] та Нестабільної недуги мають шанс дарувати Сутінки." },
    { en = "Survival of the Fittest gains an additional charge.", ua = "«Виживання найсильнішого» отримує додатковий заряд." },
    { en = "You cannot be slowed below $186257s2% of your normal movement speed while Aspect of the Cheetah is active.", ua = "Поки діє «Аспект гепарда», твою швидкість руху не можна сповільнити нижче за $186257s2% від звичайної." },
    { en = "Binding Shot's stun duration is increased by ${$s1/1000} sec.", ua = "Тривалість оглушення від «Сковувального пострілу» збільшена на ${$s1/1000} сек." },
    { en = "When a trap triggers, gain $1267208s1% increased movement speed for $1267208d.", ua = "Коли спрацьовує пастка, твоя швидкість руху збільшується на $1267208s1% протягом $1267208d." },
    { en = "You gain $s1% more critical strike from critical strike sources.", ua = "Ти отримуєш на $s1% більше критичного удару з усіх джерел критичного удару." },
    { en = "Flare's radius is increased by $s1%.", ua = "Радіус «Сигнального спалаху» збільшено на $s1%." },
    { en = "The cooldown of Intimidation is reduced by ${$abs($s2)/1000} sec.", ua = "Перезарядження «Залякування» зменшено на ${$abs($s2)/1000} сек." },
    { en = "Feign Death and Aspect of the Turtle removes poison and disease effects from you.", ua = "«Удавана смерть» і «Аспект черепахи» знімають із тебе ефекти отрут і хвороб." },
    { en = "Your damage over time effects deal $s1% increased damage.\n\n\n\nThis effect is increased by $s2% on targets below $s3% health.", ua = "Ваші ефекти періодичної шкоди завдають на $s1% більше шкоди.\n\n\n\nЦей ефект збільшено на $s2% проти цілей зі здоров'ям нижче $s3%." },
    { en = "$?s403631[Breath of Eons][Deep Breath] reduces the Essence cost of your next $s1 Eruptions by $459574s1.", ua = "$?s403631[Подих еонів][Глибокий подих] зменшує вартість в есенції ваших наступних $s1 Вивержень на $459574s1." },
    { en = "$?a137017[Wildfire Bomb]?a137016[Aimed Shot][Kill Command] deals $s1% increased damage.", ua = "$?a137017[Бомба дикого вогню]?a137016[Прицільний постріл][Наказ убити] завдає на $s1% більше шкоди." },
    { en = "When Misdirection targets your pet, it reduces the damage they take by $459547s1% for $459547d.\n\n\n\nThe cooldown of Misdirection is reduced by ${-$s1/1000} sec.", ua = "Коли Відведення уваги обирає ціллю вашого улюбленця, воно зменшує отримувану ним шкоду на $459547s1% протягом $459547d.\n\n\n\nПерезарядження Відведення уваги зменшено на ${-$s1/1000} сек." },
    { en = "Kill Command deals increased critical strike damage equal to $s2% of your critical strike chance.", ua = "«Наказ убити» завдає підвищену критичну шкоду, що дорівнює $s2% твого шансу критичного удару." },
    { en = "When your pet attacks critically strike, they cause their target to bleed for $459555s1% of the damage dealt over $459560d.", ua = "Коли атаки твого улюбленця завдають критичного удару, ціль спливає кров'ю, отримуючи $459555s1% завданої шкоди протягом $459560d." },
    { en = "Increases the range of most spells by $s1%.", ua = "Збільшує дальність більшості заклять на $s1%." },
    { en = "Bestial Wrath causes all active pets to Stomp at $s1% effectiveness.\n\n\n\nStomp damage increased by $s2%.", ua = "Лють дикого звіра змушує всіх активних улюбленців Тупотіти з $s1% дієвості.\n\n\n\nШкода Тупотіння збільшується на $s2%." },
    { en = "Summoning a Dire Beast $459731u times sounds the Horn of Valor, summoning either Hati or Fenryr to battle.\n\n\n\n|cFFFFFFFFHati|r\n\nIncreases the damage of all your pets by $459738s2%.\n\n\n\n|cFFFFFFFFFenryr|r\n\nPounces your primary target, inflicting a heavy bleed that deals $459753o1 damage over $459753d and grants you $459735s2% Haste.", ua = "Прикликання Лютозвіра $459731u разів змушує сурмити Ріг доблесті, прикликаючи в бій Гаті або Фенріра.\n\n\n\n|cFFFFFFFFHati|r\n\nЗбільшує шкоду всіх ваших улюбленців на $459738s2%.\n\n\n\n|cFFFFFFFFFenryr|r\n\nКидається на вашу основну ціль, завдаючи важкої кровотечі, що завдає $459753o1 шкоди протягом $459753d і надає вам $459735s2% Поспіху." },
    { en = "Rapid Fire shoots $s2 additional shots.\n\n\n\nAimed Shot grants $1279347s1% increased movement speed for $1279347d, decaying rapidly over its duration.", ua = "Швидкий вогонь робить $s2 додаткових пострілів.\n\n\n\nПрицільний постріл надає на $1279347s1% більшу швидкість пересування протягом $1279347d, швидко спадаючи протягом своєї тривалості." },
    { en = "Explosive Shot deals $s1% increased damage and Volley deals $s2% increased damage.", ua = "«Вибуховий постріл» завдає на $s1% більше шкоди, а «Залп» — на $s2% більше." },
    { en = "Flamefang Pitch gains $s2 additional $Lcharge:charges;. \n\n\n\nThrowing your Flamefang Pitch grants $s1 $Lcharge:charges; of Wildfire Bomb.", ua = "Полум'яний кидок отримує $s2 додаткових $Lзаряд:заряди:зарядів;. \n\n\n\nКидаючи Полум'яний кидок, ви отримуєте $s1 $Lзаряд:заряди:зарядів; Запальної бомби." },
    { en = "Each damage over time effect on a target increases the critical strike damage they receive from you by $459941s1%.", ua = "Кожен ефект періодичної шкоди на цілі збільшує критичну шкоду, яку вона отримує від тебе, на $459941s1%." },
    { en = "Kill Command grants an additional $s1 Focus and its critical strike chance is increased by $s2%.", ua = "«Наказ убити» дає додатково $s1 зосередження, а його шанс критичного удару збільшено на $s2%." },
    { en = "Tranquilizing Shot removes $s1 additional Magic effect from up to $s3 nearby targets.", ua = "«Заспокійливий постріл» знімає на $s1 більше магічних ефектів із щонайбільше $s3 цілей поблизу." },
    { en = "If Tranquilizing Shot removes only an Enrage effect, its cooldown is reduced by $s1 sec.", ua = "Якщо «Заспокійливий постріл» знімає лише ефект шалу, його перезарядження зменшується на $s1 сек." },
    { en = "Kill Command damage increased by $s2%.\n\n\n\nKill Command reduces the cooldown of Wildfire Bomb by ${$s1/1000}.1 sec.", ua = "Шкоду Наказу вбити збільшено на $s2%.\n\n\n\nНаказ вбити зменшує перезарядження Бомби дикого вогню на ${$s1/1000}.1 сек." },
    { en = "When Demonbolt consumes a Demonic Core it inflicts impending doom upon the target, dealing $460555s1 Shadow damage to enemies within $460555a1 yds of its target after $460553d or when removed. Damage is reduced beyond $s2 targets.\n\n\n\nHand of Gul'dan reduces the duration of Doom by ${$s1/1000} sec.", ua = "Коли Демонічна блискавка поглинає Демонічне ядро, ціль уражається близьким присудом, завдаючи $460555s1 шкоди Тінню ворогам у межах $460555a1 м від цілі після $460553d або коли ефект знято. Шкода зменшується після $s2 цілей.\n\n\n\nДлань Ґул'дана зменшує тривалість Приреченості на ${$s1/1000} сек." },
    { en = "Frozen Orb increases Shatter's damage by $455122s1% for its duration.", ua = "«Заморожена сфера» збільшує шкоду «Трощення» на $455122s1% на час своєї дії." },
    { en = "Turn Evil's cast time is reduced by $s1%.", ua = "Час творення «Вигнання зла» зменшено на $s1%." },
    { en = "Allies with Beacon of Light receive $s1% less damage.", ua = "Союзники з «Маяком Світла» отримують на $s1% менше шкоди." },
    { en = "$s1% of Holy Shock's overhealing is converted into an absorb shield. The shield amount cannot exceed $s2% of your max health.", ua = "$s1% надлишкового зцілення «Святого шоку» перетворюється на поглинальний щит. Обсяг щита не може перевищувати $s2% твого максимального здоров'я." },
    { en = "Holy Shock has a $s1% chance to refund a charge when cast and its healing is increased by $s2%.", ua = "«Святий шок» має $s1% шансу повернути заряд при створенні, а його зцілення збільшено на $s2%." },
    { en = "Each wave of Arcane Missiles has a $s1% chance to grant you $461524s1 Arcane Charge.\n\n\n\nArcane Missiles damage increased by $s2%.", ua = "Кожна хвиля Арканних снарядів з імовірністю $s1% надає вам $461524s1 арканний заряд.\n\n\n\nШкода від Арканних снарядів збільшена на $s2%." },
    { en = "Each wave of Arcane Missiles will consume an Arcane Charge to increase its damage by $s1%.", ua = "Кожна хвиля «Арканних снарядів» поглинає арканний заряд, збільшуючи свою шкоду на $s1%." },
    { en = "Each wave of Arcane Missiles has a $s1% chance to grant $s2 additional $Lstack:stacks; of Arcane Salvo.", ua = "Кожна хвиля Арканних снарядів має $s1% імовірність надати $s2 додатковий $Lзаряд:заряди; Арканного залпу." },
    { en = "Reduces Arcane Blast's mana cost by $s1% and increases its damage by $s2%.", ua = "Зменшує витрату мани Арканного удару на $s1% і збільшує його шкоду на $s2%." },
    { en = "Gaining $?a137021[Clearcasting]?a137020[Brain Freeze][Hot Streak] increases your Intellect by $461531s1% for $461531d. Multiple instances may overlap.", ua = "Отримання $?a137021[Ясного чаклування]?a137020[Заморозки мозку][Гарячої серії] збільшує ваш Інтелект на $461531s1% протягом $461531d. Кілька екземплярів можуть накладатися." },
    { en = "Judgment heals you for $461546s1 and its mana cost is reduced by $s1%. $s2% of overhealing from this effect is transferred onto $s3 allies within $461529a1 yds.", ua = "«Осуд» зцілює тебе на $461546s1, а його вартість мани знижена на $s1%. $s2% надлишкового зцілення від цього ефекту передається $s3 союзникам у радіусі $461529a1 м." },
    { en = "Word of Glory and Light of Dawn gain up to $s1% additional chance to critically strike, based on their target's current health. Lower health targets are more likely to be critically struck.", ua = "«Слово слави» та «Світло світанку» отримують до $s1% додаткового шансу критичного ефекту залежно від поточного здоров'я цілі. Що менше здоров'я цілі, то вищий шанс критичного ефекту." },
    { en = "$s1% of Word of Glory and Light of Dawn's healing is converted into Holy damage that strikes a nearby enemy.", ua = "$s1% зцілення «Слова слави» та «Світла світанку» перетворюється на святу шкоду, що вражає ворога поблизу." },
    { en = "Wildfire Bomb and Flamefang Pitch deal $s1% increased critical strike damage.", ua = "«Бомба дикого вогню» та «Смола вогнеікла» завдають на $s1% більше шкоди критичних ударів." },
    { en = "Healing from Healing Stream Totem reduces Fire, Frost, and Nature damage taken by $462568s1% for $462568d.", ua = "Зцілення від «Тотема цілющого потоку» зменшує отримувану шкоду від вогню, морозу та природи на $462568s1% на $462568d." },
    { en = "Spirit Link Totem reduces damage taken by an additional $s1%, and it restores $462384s1 health to all nearby allies $m2 $Lsecond:seconds; after it is dropped. Healing reduced beyond $s3 targets.", ua = "Тотем духовного зв'язку зменшує отримувану шкоду на додаткові $s1% і відновлює $462384s1 здоров'я всім сусіднім союзникам через $m2 $Lсекунду:секунд; після встановлення. Зцілення зменшене понад $s3 цілей." },
    { en = "When you cast $?a455630[Surging Totem][Healing Rain], each ally with your Riptide on them is healed for $462425s1.", ua = "Коли ви творите $?a455630[Здіймальний тотем][Зцілющий дощ], кожен союзник із вашим Відпливом зцілюється на $462425s1." },
    { en = "The cooldown of Ascendance$?a137039[ and Healing Tide Totem][] is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Вознесіння$?a137039[ та Тотема цілющого припливу][] зменшено на ${$s1/-1000} с." },
    { en = "Your haste is increased by $s2% $?a137039 [while Ascendance or Healing Tide Totem is active and their durations are][during Ascendance and its duration is] increased by ${$s1/1000} sec.", ua = "Ваш поспіх збільшено на $s2% $?a137039 [поки активні Піднесення чи Тотем зцілювальної хвилі, і їхня тривалість][протягом Піднесення, і його тривалість] збільшено на ${$s1/1000} с." },
    { en = "When refreshing Earth Shield, your target is healed for $462477s1 for each stack of Earth Shield they are missing.$?c3[\n\n\n\nWhen refreshing Water Shield, you are refunded $462479s1 mana for each stack of Water Shield missing.][]\n\n\n\nAdditionally, Earth Shield$?c3[ and Water Shield][] can consume charges ${$s2/-1000}.1 sec faster.", ua = "Під час оновлення Щита землі ваша ціль зцілюється на $462477s1 за кожен відсутній заряд Щита землі.$?c3[\n\n\n\nПід час оновлення Щита води вам повертається $462479s1 мани за кожен відсутній заряд Щита води.][]\n\n\n\nКрім того, Щит землі$?c3[ та Щит води][] можуть споживати заряди на ${$s2/-1000}.1 с швидше." },
    { en = "Casting $?a455630[Surging Totem][Healing Rain] grants a use of Downpour for $462488d.\n\n\n\n$@spellicon207778 $@spellname207778\n\n$@spelldesc207778", ua = "Прочитання $?a455630[Буйного тотема][Зцілющого дощу] надає одне використання Зливи протягом $462488d.\n\n\n\n$@spellicon207778 $@spellname207778\n\n$@spelldesc207778" },
    { en = "Your critical heals have ${$s2+$s1}% effectiveness instead of the usual $s2%.", ua = "Твої критичні зцілення мають ${$s2+$s1}% ефективності замість звичайних $s2%." },
    { en = "Causes the earth within $a1 yards of your target to tremble and break, dealing ${$s4*$77478s1} Nature damage over $d and has a $77478s2% chance to knock the enemy down. Multiple uses of Earthquake may overlap.\n\n\n\n|cFFFFFFFFThis spell is cast at your target.|r", ua = "Змушує землю в межах $a1 ярдів від вашої цілі тремтіти й тріскатися, завдаючи ${$s4*$77478s1} Природної шкоди протягом $d, і має $77478s2% шанс збити ворога з ніг. Кілька застосувань «Землетрусу» можуть накладатися.\n\n\n\n|cFFFFFFFFЦе закляття твориться по вашій цілі.|r" },
    { en = "Reduces the cast time of Lightning Bolt$?s454009[, Tempest,][] and Chain Lightning by $s1%.", ua = "Зменшує час прочитання «Удару блискавки»$?s454009[, «Бурі»][] та «Ланцюгової блискавки» на $s1%." },
    { en = "Imbue your shield with the element of Lightning for $d, giving Lightning Bolt$?a454009[, Tempest,][] and Chain Lightning a chance to call down $s1 Thunderstrikes on your target for $462763s1 Nature damage.", ua = "Наповнює ваш щит стихією Блискавки на $d, даючи Розряду блискавки$?a454009[, Буревію,][] та Ланцюговій блискавці шанс закликати $s1 Громових ударів по вашій цілі, що завдають $462763s1 шкоди Природою." },
    { en = "Increases the cooldown of Frost Shock by ${$s1/1000} sec, but Frost Shock now freezes targets in place for $1258862d.", ua = "Збільшує перезарядження «Шоку морозу» на ${$s1/1000} сек., але тепер «Шок морозу» приморожує цілі на місці на $1258862d." },
    { en = "Enemies within $s1 yds of your Frost Shock are snared by $462765s1%.", ua = "Вороги в межах $s1 м від твого «Морозного шоку» сповільнені на $462765s1%." },
    { en = "Wind Rush Totem's cooldown is reduced by ${$s1/-1000} sec and its movement speed effect lasts an additional ${$s2/1000} sec.", ua = "Перезарядження «Тотему пориву вітру» зменшено на ${$s1/-1000} сек., а його ефект швидкості руху триває на ${$s2/1000} сек. довше." },
    { en = "The effects of your weapon $?a137041[][and shield ]imbues are increased by $?c1[$s1]?c2[$s2]?c3[$s3][]%.", ua = "Ефекти ваших насичень зброї $?a137041[][та щита ]збільшено на $?c1[$s1]?c2[$s2]?c3[$s3][]%." },
    { en = "Wind Rush Totem's movement speed bonus is increased by $s1% and now removes snares.", ua = "Бонус швидкості руху від «Тотему пориву вітру» збільшено на $s1%, і тепер він знімає ефекти сповільнення." },
    { en = "Consuming Power of the Maelstrom additionally fires an Elemental Blast at your target at $s1% effectiveness.", ua = "Поглинання «Сили Виру» додатково вивільняє «Стихійний вибух» у твою ціль з $s1% ефективності." },
    { en = "While Lightning Shield is active, your Nature damage dealt is increased by $s3%.", ua = "Поки діє «Щит блискавок», твоя шкода від сил природи збільшена на $s3%." },
    { en = "While a Fire Elemental is active, your Fire damage dealt is increased by $188592s4%.\n\n\n\nWhile a Storm Elemental is active, your Nature damage dealt is increased by $157299s4%.", ua = "Поки активний Вогняний елементаль, ваша шкода від вогню збільшена на $188592s4%.\n\n\n\nПоки активний Штормовий елементаль, ваша шкода від сил природи збільшена на $157299s4%." },
    { en = "Increases the duration of your Elementals by $s1%.", ua = "Збільшує тривалість твоїх елементалів на $s1%." },
    { en = "The damage bonus of Spotter's Mark is increased by $s1%.\n\n\n\nAdditionally, your Eagle learns how to Fetch.\n\n\n\n$@spellicon466872 $@spellname466872\n\nDamaging an enemy with abilities empowered by Precise Shots has a $1219616s1% chance to apply Spotter's Mark to the primary target, causing your next Aimed Shot to deal $466872s1% increased damage to the target.", ua = "Бонус шкоди Мітки спостерігача збільшено на $s1%.\n\n\n\nКрім того, ваш орел навчається приносити здобич.\n\n\n\n$@spellicon466872 $@spellname466872\n\nЗавдаючи шкоди ворогові здібностями, підсиленими Точними пострілами, ви маєте $1219616s1% шанс накласти Мітку спостерігача на основну ціль, через що ваш наступний Прицільний постріл завдасть цілі на $466872s1% більше шкоди." },
    { en = "You attempt to finish off a wounded target, dealing $s1 Shadow damage and $468572o1 Shadow damage over $468572d. Only usable on enemies above $s3% health or below $s2% health.", ua = "Ти намагаєшся добити поранену ціль, завдаючи $s1 шкоди тінню та ще $468572o1 шкоди тінню протягом $468572d. Можна використати лише проти ворогів, у яких понад $s3% або менше ніж $s2% здоров'я." },
    { en = "Your Kill Shot is replaced with Black Arrow.\n\n\n\n$@spellicon466930 $@spellname466930\n\n$@spelldesc466930", ua = "Ваш Смертельний постріл замінюється Чорною стрілою.\n\n\n\n$@spellicon466930 $@spellname466930\n\n$@spelldesc466930" },
    { en = "$?c1[Bestial Wrath][Trueshot] causes you to surrender to darkness, granting you Withering Fire for $?c1[$466991d][the duration of Trueshot] and Deathblow.\n\n\n\n$@spellicon466991 $@spellname466991\n\nCasting Black Arrow fires a barrage of $s3 additional Black Arrows at nearby targets at $s4% effectiveness, prioritizing enemies that aren't affected by Black Arrow's damage over time effect.", ua = "$?c1[Звіриний гнів][Влучний постріл] змушує тебе піддатися темряві, даруючи тобі Нищівний вогонь на $?c1[$466991d][час дії Влучного пострілу] та Смертельний удар.\n\n\n\n$@spellicon466991 $@spellname466991\n\nЗастосування Чорної стріли випускає залп із $s3 додаткових Чорних стріл по цілях поблизу з $s4% ефективності, віддаючи перевагу ворогам, не вражених ефектом періодичної шкоди Чорної стріли." },
    { en = "Life Cocoon grants up to $s1 stacks of Mana Tea and applies $s2 stacks of Healing Elixir to its target.", ua = "«Кокон життя» дає до $s1 зарядів «Чаю з мани» і накладає на свою ціль $s2 зарядів «Цілющого еліксиру»." },
    { en = "Ancient Teachings transfers an additional $388026s2% damage to healing.\n\n\n\nYour Stamina is increased by $s2%.", ua = "Прадавні вчення переносять додаткові $388026s2% шкоди в зцілення.\n\n\n\nВаша Витривалість збільшується на $s2%." },
    { en = "Kick up a powerful gust of wind, dealing $468179s1 Nature damage in a $468179a1 yd cone to enemies in front of you, split evenly among them. Damage is increased by $s1% for each target hit, up to ${$s1*$s2}%.\n\n\n\n$?c2[Heals up to $s3 allies affected by your heal over time effects for $1269159s1.][]", ua = "Здіймає потужний порив вітру, завдаючи $468179s1 шкоди Природою в конусі $468179a1 ярдів ворогам перед тобою, рівномірно розподіленої між ними. Шкода збільшується на $s1% за кожну вражену ціль, до ${$s1*$s2}%.\n\n\n\n$?c2[Зцілює до $s3 союзників, охоплених твоїми ефектами поступового зцілення, на $1269159s1.][]" },
    { en = "Crackling Jade Lightning's damage is increased by $s2% and now chains to $s1 additional enemies at $s4% effectiveness.", ua = "Шкоду «Тріскучої нефритової блискавки» збільшено на $s2%, і тепер вона перестрибує на $s1 додаткових ворогів з $s4% ефективності." },
    { en = "$?c1[All pet damage increased by $s2%][Critical strike chance increased by $s1%].\n\n\n\n$?c1[Dire Beast damage increased by $s3%][Dark Minion damage increased by $s4%].", ua = "$?c1[Уся шкода улюбленця підвищена на $s2%][Шанс критичного удару підвищений на $s1%].\n\n\n\n$?c1[Шкода Лютого звіра підвищена на $s3%][Шкода Темного посіпаки підвищена на $s4%]." },
    { en = "While in combat, Disengage releases a fan of shadow daggers, dealing $467745s1 Shadow damage per second and reducing affected target's movement speed by $467745s2% for $467745d.", ua = "У бою «Відступ» випускає віяло тіньових кинджалів, що завдає $467745s1 шкоди від тіні за секунду та зменшує швидкість руху уражених цілей на $467745s2% протягом $467745d." },
    { en = "Your auto shot now deals Shadow damage, allowing it to bypass armor.\n\n\n\nAuto shot damage increased by $s3%.", ua = "Ваш автоматичний постріл тепер завдає тіньової шкоди, що дозволяє йому оминати броню.\n\n\n\nШкоду автоматичного пострілу збільшено на $s3%." },
    { en = "You have a chance to get struck by lightning, increasing your movement speed by $468226s2% for $468226d. The effectiveness is increased to $s3% in outdoor areas.\n\n\n\nYou call down a Thunderstorm when you Reincarnate.", ua = "Ви маєте шанс, що вас вдарить блискавка, збільшуючи вашу швидкість пересування на $468226s2% впродовж $468226d. На відкритій місцевості ефективність збільшується до $s3%.\n\n\n\nПри Перевтіленні ви прикликаєте Грозу." },
    { en = "Casting Black Arrow has a $s1% chance to grant Deathblow.\n\n\n\n$@spellicon378770 $@spellname378770\n\nThe cooldown of $?a137015[Black Arrow]?a466932[Black Arrow][Kill Shot] is reset. Your next $?a137015[Black Arrow]?a466932[Black Arrow][Kill Shot] can be used on any target, regardless of their current health.", ua = "Застосування Чорної стріли має $s1% шанс дарувати Смертельний удар.\n\n\n\n$@spellicon378770 $@spellname378770\n\nПерезарядження $?a137015[Чорної стріли]?a466932[Чорної стріли][Добивального пострілу] скидається. Твоя наступна $?a137015[Чорна стріла]?a466932[Чорна стріла][Добивальний постріл] може застосовуватися по будь-якій цілі, незалежно від її поточного здоров'я." },
    { en = "Black Arrow and Bleak Powder critical strike damage increased by $s1%.", ua = "Критична шкода від «Чорної стріли» та «Похмурого пороху» збільшена на $s1%." },
    { en = "Black Arrow now explodes in a cloud of shadow and sulfur on impact, dealing $?c1[$472084s1][$467914s1] Shadow damage to all enemies within an $s2 yd cone behind the target. Damage reduced beyond $s2 targets.", ua = "Чорна стріла тепер вибухає хмарою тіні та сірки під час влучання, завдаючи $?c1[$472084s1][$467914s1] тіньової шкоди всім ворогам у конусі $s2 ярдів позаду цілі. Шкода зменшена понад $s2 цілей." },
    { en = "Reduces the cooldown of Stormkeeper by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Хранителя бурі» на ${$s1/-1000} сек." },
    { en = "Increases the duration of Lightning Rod by ${$s1/1000} sec and its damage bonus by $s2%.", ua = "Збільшує тривалість «Громовідводу» на ${$s1/1000} сек., а його бонус до шкоди — на $s2%." },
    { en = "Increases Earth Shock and Earthquake damage by $s1% and the stat bonuses granted by Elemental Blast by $s2%.", ua = "Збільшує шкоду «Шоку землі» та «Землетрусу» на $s1%, а бонуси до характеристик від «Стихійного вибуху» — на $s2%." },
    { en = "Your auto shot has a $s1% chance to also fire a Cobra Shot at your target.", ua = "Твій автоматичний постріл має $s1% шансу також випустити «Постріл кобри» у твою ціль." },
    { en = "Cobra Shot critical damage dealt increased by $s1%.\n\n\n\nWhen Cobra Shot critically strikes, it refunds $1282710s1 Focus.", ua = "Критична шкода Пострілу кобри збільшується на $s1%.\n\n\n\nКоли Постріл кобри завдає критичного удару, він повертає $1282710s1 зосередження." },
    { en = "$?s102560[Incarnation: Chosen of Elune][Celestial Alignment]'s cooldown is reduced by ${-$s3/1000} seconds and it has two charges.", ua = "Перезарядження $?s102560[«Втілення: обранець Елуни»][«Небесного вирівнювання»] зменшено на ${-$s3/1000} сек., і це закляття має два заряди." },
    { en = "Sunfire damage has a chance to grow a magical mushroom at a target's location. After $468938d, the mushroom detonates, dealing $1280212s1 Nature damage and then an additional $1280213o1 Nature damage over $1280213d. Affected targets are slowed by ${$1280213s2*-1}%.\n\n\n\nGenerates up to $1280212s2 Astral Power based on targets hit.", ua = "Шкода від Сонячного вогню має шанс виростити магічний гриб на місці розташування цілі. Через $468938d гриб детонує, завдаючи $1280212s1 шкоди від Природи, а потім ще $1280213o1 шкоди від Природи протягом $1280213d. Уражені цілі сповільнюються на ${$1280213s2*-1}%.\n\n\n\nГенерує до $1280212s2 Астральної сили залежно від кількості уражених цілей." },
    { en = "Casting a free Starsurge or Starfall grants Solstice for ${$s1/1000} sec.", ua = "Творення безкоштовного «Зоряного сплеску» чи «Зорепаду» дарує «Сонцестояння» на ${$s1/1000} сек." },
    { en = "You automatically cast Blessing of Sacrifice onto an ally within $a2 yds when they are below $s2% health and you are not in a loss of control effect.\n\n\n\nThis effect activates $s1% of Blessing of Sacrifice's cooldown.", ua = "Ви автоматично творите «Благословення жертовності» на союзника в межах $a2 м, коли його здоров'я нижче $s2%, а ви не перебуваєте під ефектом втрати контролю.\n\n\n\nЦей ефект задіює $s1% перезарядження «Благословення жертовності»." },
    { en = "Divine Steed also grants Blessing of Freedom for ${$s1/1000}.1 sec.\n\n\n\n$@spellicon1044 $@spellname1044:\n\n$@spelldesc1044", ua = "Божественний скакун також дає Благословення свободи на ${$s1/1000}.1 с.\n\n\n\n$@spellicon1044 $@spellname1044:\n\n$@spelldesc1044" },
    { en = "Melee and ranged attackers receive $469311s1 Holy damage each time they strike you during $?c2[Ardent Defender][Divine Protection] and Divine Shield.", ua = "Вороги, що атакують тебе зблизька чи здалеку, отримують $469311s1 од. святої шкоди щоразу, коли влучають по тобі під час дії $?c2[«Завзятого захисника»][«Божественного захисту»] та «Божественного щита»." },
    { en = "Casting Sundering summons $s1 Fire Feral $lSpirit:Spirits; and Doom Winds summons $s2 Nature Feral $lSpirit:Spirits; by your side for $469322d.\n\n\n\n$@spellicon469314$@spellname469314\n\nAn Elemental Spirit $?s147783[Raptor][Wolf] infused with Fire or Nature magic, granting the summoner with $224125s1% increased Fire or Nature damage and $224125s3% Physical damage for $469322d.", ua = "Прочитання Розколу прикликає $s1 вогняних диких $lдуха:духів;, а Вітри судьби прикликають $s2 природних диких $lдуха:духів; до вас на $469322d.\n\n\n\n$@spellicon469314$@spellname469314\n\nСтихійний дух $?s147783[раптора][вовка], наповнений магією вогню чи природи, що надає прикликачу на $224125s1% збільшену шкоду вогнем чи природою та $224125s3% фізичну шкоду протягом $469322d." },
    { en = "The duration of stun effects on you is reduced by $s1%.", ua = "Тривалість ефектів оглушення на тобі зменшено на $s1%." },
    { en = "Turn Evil now affects $s1 additional enemies.", ua = "«Вигнання зла» тепер діє на $s1 додаткових ворогів." },
    { en = "Blessing of Sacrifice now removes and prevents all Poison and Disease effects.", ua = "«Благословення жертовності» тепер знімає всі ефекти отрут і хвороб та запобігає їм." },
    { en = "The cooldown of Blinding Light is reduced by ${$s2/-1000} sec.", ua = "Перезарядження «Сліпучого світла» зменшено на ${$s2/-1000} сек." },
    { en = "Holy Power spending abilities have $s1% increased damage and healing.", ua = "Шкоду та зцілення здібностей, що витрачають святу силу, збільшено на $s1%." },
    { en = "Divine Steed's cooldown is reduced by $s1%, but its duration is reduced by $s2%.", ua = "Перезарядження «Божественного скакуна» скорочено на $s1%, але його тривалість зменшено на $s2%." },
    { en = "After $?c1[Cleanse][Cleanse Toxins] successfully removes an effect from an ally, they are healed for ${$469413s1*$s1}.", ua = "Коли $?c1[Очищення][Очищення від токсинів] успішно знімає ефект із союзника, той зцілюється на ${$469413s1*$s1}." },
    { en = "$s1% of all healing done to you from other sources heals up to $s2 nearby allies, divided evenly among them.", ua = "$s1% усього зцілення, яке ти отримуєш з інших джерел, зцілює до $s2 союзників поблизу, розподіляючись між ними порівну." },
    { en = "Flash of Light $?c1[and Holy Light are][is] $s1% more effective on your allies and $s2% of the healing done also heals you.", ua = "«Спалах світла» $?c1[та «Святе світло» діють][діє] на $s1% ефективніше на твоїх союзників, а $s2% виконаного зцілення зцілює також і тебе." },
    { en = "$?c2[Ardent Defender][Divine Protection] increases healing taken by $s1% for its duration.", ua = "$?c2[«Завзятий захисник»][«Божественний захист»] на час своєї дії збільшує отримуване зцілення на $s1%." },
    { en = "Your Forbearance's duration is reduced by ${$s1/-1000} sec.", ua = "Тривалість твоєї «Стриманості» зменшена на ${$s1/-1000} сек." },
    { en = "The radius of your auras is increased by $s1 yds.", ua = "Радіус твоїх аур збільшено на $s1 м." },
    { en = "$?c1[Kill Command has a $s1% chance and Barbed Shot has a $s2% chance to grant Deathblow.\n\n][Aimed Shot's chance to grant Deathblow is increased by $s3%. Rapid Fire has a $s4% chance to grant Deathblow.]\n\n$@spellicon378770 $@spellname378770\n\nThe cooldown of $?a137015[Black Arrow]?a466932[Black Arrow][Kill Shot] is reset. Your next $?a137015[Black Arrow]?a466932[Black Arrow][Kill Shot] can be used on any target, regardless of their current health.", ua = "$?c1[Наказ убити має $s1% шанс, а Шипаста стріла має $s2% шанс дарувати Смертельний удар.\n\n][Шанс Прицільного пострілу дарувати Смертельний удар підвищений на $s3%. Швидкий вогонь має $s4% шанс дарувати Смертельний удар.]\n\n$@spellicon378770 $@spellname378770\n\nПерезарядження $?a137015[Чорної стріли]?a466932[Чорної стріли][Добивального пострілу] скидається. Твоя наступна $?a137015[Чорна стріла]?a466932[Чорна стріла][Добивальний постріл] може застосовуватися по будь-якій цілі, незалежно від її поточного здоров'я." },
    { en = "Find Weakness increases the damage of finishing moves by $s1%.\n\n\n\nShadow Dance increases the damage of finishing moves by $s2%.\n\n\n\nShadow Blades increases the damage of finishing moves by $s3%.", ua = "«Знайти слабкість» збільшує шкоду завершальних прийомів на $s1%.\n\n\n\n«Танок тіней» збільшує шкоду завершальних прийомів на $s2%.\n\n\n\n«Тіньові клинки» збільшують шкоду завершальних прийомів на $s3%." },
    { en = "When you or an ally wielding a Holy Bulwark are healed above maximum health, transfer $s1% of the overhealing to your ally.\n\n\n\nWhen you or an ally wielding a Sacred Weapon drop below $432502s4% health, redistribute your health immediately and every $469703t sec for $469703d. May only occur once per cast.", ua = "Коли ви або союзник, що тримає «Святий бастіон», отримуєте зцілення понад максимальне здоров'я, $s1% надлишкового зцілення передається вашому союзникові.\n\n\n\nКоли ви або союзник, що тримає «Священну зброю», падаєте нижче $432502s4% здоров'я, ваше здоров'я перерозподіляється негайно й кожні $469703t с протягом $469703d. Може спрацювати лише раз за творіння." },
    { en = "Allies affected by your Blessings have $s1% increased movement speed.", ua = "Союзники під дією твоїх благословень рухаються на $s1% швидше." },
    { en = "Restore $s1 Energy.\n\n\n\nWhen your Energy is reduced below $469779s2, drink a Thistle Tea.", ua = "Відновлює $s1 енергії.\n\n\n\nКоли ваша енергія опускається нижче $469779s2, випиваєте Будяковий чай." },
    { en = "Divine Steed reduces the cooldown of $s1 nearby ally's major movement ability by ${$s2/-1000}.1 sec.\n\n\n\nYour movement speed is increased by $s4%.", ua = "«Божественний скакун» зменшує перезарядження головної здібності пересування $s1 союзника поблизу на ${$s2/-1000}.1 с.\n\n\n\nВаша швидкість пересування збільшена на $s4%." },
    { en = "Reduces the cooldown of Reaper's Mark by ${$s1/-1000} sec, but the amount of $?a137008[Marrowrends][Obliterates and Frostscythes] empowered by Exterminate is reduced by $s2.", ua = "Зменшує перезарядження «Знаку женця» на ${$s1/-1000} сек, але кількість $?a137008[«Розривів кісткового мозку»][«Знищень» і «Морозних кіс»], підсилених «Винищенням», зменшено на $s2." },
    { en = "Casting Cobra Shot reduces the cooldown of Barbed Shot by ${$s1/1000} sec.", ua = "Прочитання «Пострілу кобри» скорочує перезарядження «Шипастого пострілу» на ${$s1/1000} сек." },
    { en = "Enemies struck by Avenger's Shield burn with holy fire, suffering $469883s1% additional Radiant damage over $d.", ua = "Вороги, уражені Щитом месника, палають святим вогнем, зазнаючи $469883s1% додаткової Променистої шкоди протягом $d." },
    { en = "Successfully $?c1[dispelling a harmful effect][interrupting an enemy spellcast] reduces $?c1[Cleanse's cooldown by ${$s3/1000}.1 sec][Rebuke's cooldown by ${$s1/1000}.1 sec]. Effect increased by $s2% while wielding a Holy Armament.", ua = "Успішне $?c1[розвіювання шкідливого ефекту][переривання ворожого закляття] зменшує $?c1[перезарядження «Очищення» на ${$s3/1000}.1 сек][перезарядження «Докору» на ${$s1/1000}.1 сек]. Ефект посилено на $s2%, поки ти тримаєш «Святе озброєння»." },
    { en = "$?c1[Arcane Blast and Arcane Pulse damage increased by $s3%.\n\n\n\nCasting Touch of the Magi conjures $s1 Arcane Splinters][Frostbolt and Blizzard damage increased by $s4%.\n\n\n\nGlacial Spike conjures $s2 additional Frost Splinters].", ua = "$?c1[Шкода від Арканного удару та Арканного пульсу збільшена на $s3%.\n\n\n\nТворіння Дотику магів прикликає $s1 арканних скалок][Шкода від Морозної стріли та Завірюхи збільшена на $s4%.\n\n\n\nЛьодяний шпиль прикликає $s2 додаткових морозних скалок]." },
    { en = "Instantly shocks the target and $s4 enemies within $A1 yds with blazing thunder, applying Flame Shock and dealing $1259101s1 Nature damage. Always critically strikes.$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s14 Maelstrom.|r][\n\n\n\nGenerates $s2 $Lstack:stacks; of Maelstrom Weapon.]", ua = "Миттєво вражає ціль та $s4 ворогів у межах $A1 м палаючим громом, накладаючи Полум'яний шок і завдаючи $1259101s1 шкоди природою. Завжди завдає критичного удару.$?a343725[\n\n\n\n|cFFFFFFFFСтворює $343725s14 Виру.|r][\n\n\n\nСтворює $s2 $Lзаряд:заряди; Зброї виру.]" },
    { en = "Healing Wave and Chain Heal increase the initial healing of your next Riptide by $470077s1%, stacking up to $470077u times.", ua = "«Хвиля зцілення» та «Ланцюгове зцілення» збільшують початкове зцілення твоєї наступної «Стрімкої течії» на $470077s1%; складається до $470077u разів." },
    { en = "$?a137035[Shadow Dance]?a137036[Adrenaline Rush][Kingsbane] supercharges $m1 combo $Lpoint:points;.\n\n\n\nDamaging finishing moves consume a supercharged combo point to function as if they spent $m2 additional combo $Lpoint:points;.", ua = "$?a137035[Танець тіней]?a137036[Сплеск адреналіну][Згуба королів] надзаряджає $m1 $Lочко комбо:очка комбо;.\n\n\n\nЗавершальні прийоми, що завдають шкоди, споживають надзаряджене очко комбо, діючи так, ніби витратили $m2 $Lдодаткове очко комбо:додаткові очки комбо;." },
    { en = "Swiftmend healing increased by $s1%.", ua = "Зцілення Швидкого загоєння збільшено на $s1%." },
    { en = "Swiftmend cooldown is reduced by $s1%, increasing up to $s2% on lower health targets.", ua = "Перезарядження Швидкого загоєння зменшено на $s1%, і це зменшення зростає до $s2% на цілях із нижчим рівнем здоров'я." },
    { en = "Increase the bonus granted when a damaging finishing move consumes a supercharged combo point by $s1.", ua = "Збільшує на $s1 бонус, який надається, коли завершальний прийом, що завдає шкоди, споживає надзаряджене комбо-очко." },
    { en = "After consuming a supercharged combo point, your next $?s200758[Gloomblade]?a137035[Backstab]?a137036[Sinister Strike][Mutilate] also strikes the target with an Echoing Reprimand dealing $470672s1 Physical damage.", ua = "Після витрати наднабоєного очка комбо ваше наступне $?s200758[Похмурий клинок]?a137035[Удар у спину]?a137036[Лиховісний удар][Каліцтво] також вражає ціль Лункою доганою, завдаючи $470672s1 фізичної шкоди." },
    { en = "Trueshot sends your $?a1253599[Sentinel Owl][Spotting Eagle] into a frenzy, instantly applying $?a1253599[Sentinel's Mark][Spotter's Mark] to your target. \n\n\n\nDuring Trueshot, your chance to apply $?a1253599[Sentinel's Mark][Spotter's Mark] is increased by $s1%.", ua = "Несхибний постріл доводить $?a1253599[вашу сову-вартову][вашого орла-спостерігача] до шаленства, миттєво накладаючи на вашу ціль $?a1253599[Мітку вартового][Мітку спостерігача]. \n\n\n\nПід час Несхибного пострілу ваш шанс накласти $?a1253599[Мітку вартового][Мітку спостерігача] збільшено на $s1%." },
    { en = "Aimed Shot, Rapid Fire, and Arcane Shot now hit $s2 additional $Ltarget:targets; for $s1% of their damage.", ua = "Прицільний постріл, Швидкий вогонь та Арканний постріл тепер уражають $s2 додаткову $Lціль:цілі; на $s1% своєї шкоди." },
    { en = "Collecting $1225789u Soul Fragments grants access to Void Metamorphosis.\n\n\n\n$@spellicon1217605 $@spellname1217605\n\n$@spelldesc1217605", ua = "Збирання $1225789u фрагментів душі надає доступ до Метаморфози Порожнечі.\n\n\n\n$@spellicon1217605 $@spellname1217605\n\n$@spelldesc1217605" },
    { en = "The damage of your auto shot is increased by $s2% and its critical strike chance is increased by $s1%.", ua = "Шкоду твого автоматичного пострілу збільшено на $s2%, а його шанс критичного удару — на $s1%." },
    { en = "Damage from $?a466932[Black Arrow][Kill Shot] increases the damage your target receives from $?a466932[Black Arrow][Kill Shot] by $1277558s1%, stacking up to $1277558u times.", ua = "Шкода від $?a466932[Чорної стріли][Смертельного пострілу] збільшує шкоду, яку ваша ціль отримує від $?a466932[Чорної стріли][Смертельного пострілу], на $1277558s1%. Накопичується до $1277558u разів." },
    { en = "Trueshot now also reduces the cast time of Aimed Shot by $s1% and reduces the Focus cost of Aimed Shot by $s2%.", ua = "«Влучний постріл» тепер також скорочує час творення «Прицільного пострілу» на $s1% і зменшує його вартість зосередження на $s2%." },
    { en = "When Aimed Shot damages a target affected by your Explosive Shot, Explosive Shot instantly explodes, dealing $474199s1% increased damage.", ua = "Коли «Прицільний постріл» завдає шкоди цілі під дією твого «Вибухового пострілу», «Вибуховий постріл» миттєво детонує, завдаючи на $474199s1% більше шкоди." },
    { en = "Bulletstorm now increases your critical strike damage by $s1%. Additionally, Bulletstorm now stacks $s2 more times.", ua = "«Шквал куль» тепер збільшує твою критичну шкоду на $s1%. Крім того, «Шквал куль» тепер накопичує на $s2 заряди більше." },
    { en = "Gain magical damage reduction equal to $s1% of your damage reduction from armor.", ua = "Отримуєш зменшення магічної шкоди, що дорівнює $s1% твого зменшення шкоди від броні." },
    { en = "Holy Word: Serenity applies ${$s1/1000} sec of Renew to its target.\n\n\n\n$?a1246517[Ultimate Serenity][Holy Word: Sanctify] applies $?a440671[${$s2/1000}.1][${$s2/1000}] sec of Renew to allies it heals.\n\n\n\n$@spellicon139 $@spellname139\n\nFill the target with faith in the light, healing for $?a440671[${$139o1*$s1/15000/(1+$440671s2/100)}.1][${$139o1*$s1/15000}] over ${$s1/1000} sec.", ua = "Святе слово: Умиротворення накладає ${$s1/1000} сек. Оновлення на свою ціль.\n\n\n\n$?a1246517[Найвище умиротворення][Святе слово: Освячення] накладає $?a440671[${$s2/1000}.1][${$s2/1000}] сек. Оновлення на союзників, яких зцілює.\n\n\n\n$@spellicon139 $@spellname139\n\nСповнює ціль вірою у світло, зцілюючи на $?a440671[${$139o1*$s1/15000/(1+$440671s2/100)}.1][${$139o1*$s1/15000}] протягом ${$s1/1000} сек." },
    { en = "Increases the healing done by Holy Word: Serenity$?a1246517[ by $s1%.][ and Holy Word: Sanctify by $s1%.\n\n\n\nIncreases the radius of Holy Word: Sanctify by $s2%.]", ua = "Збільшує зцілення Святого слова: Умиротворення$?a1246517[ на $s1%.][ та Святого слова: Освячення на $s1%.\n\n\n\nЗбільшує радіус Святого слова: Освячення на $s2%.]" },
    { en = "Sheilun's Gift's healing is increased by $s3% and its cast time is reduced by $s2%, but it now only heals a single ally.", ua = "Зцілення Дару Шейлун збільшено на $s3%, а час прочитання скорочено на $s2%, але тепер він зцілює лише одного союзника." },
    { en = "While in combat, every $471877d your next Kill Command summons the aid of a Beast.\n\n\n\n$@spellicon471881 Wyvern\n\nA Wyvern descends from the skies, letting out a battle cry that increases the damage of you and your pets by ${$471881s1*$s3}% for $471881d.\n\n\n\n$@spellicon471936 Boar\n\nA Boar charges through your target $s2 $Ltime:times;, dealing $471938s1 damage to nearby enemies and an additional $471936s1 physical damage to its primary target. Damage reduced beyond $471938s2 targets.\n\n\n\n$@spellicon471993 Bear\n\nA Bear leaps into the fray, rending the flesh of your enemies, dealing $471999o1 damage over $471999d to up to $471999s2 nearby enemies.", ua = "У бою кожні $471877d ваш наступний Наказ убити прикликає на допомогу звіра.\n\n\n\n$@spellicon471881 Віверна\n\nВіверна спускається з небес і видає бойовий клич, що збільшує шкоду вашу та ваших улюбленців на ${$471881s1*$s3}% протягом $471881d.\n\n\n\n$@spellicon471936 Вепр\n\nВепр пробивається крізь вашу ціль $s2 $Lраз:рази:разів;, завдаючи $471938s1 од. шкоди ворогам поблизу та додатково $471936s1 од. фізичної шкоди основній цілі. Шкода зменшується після $471938s2 цілей.\n\n\n\n$@spellicon471993 Ведмідь\n\nВедмідь стрибає у битву, шматуючи плоть ваших ворогів і завдаючи $471999o1 од. шкоди протягом $471999d щонайбільше $471999s2 ворогам поблизу." },
    { en = "Kill Command reduces the cooldown of Howl of the Pack Leader by $?c1[${$s1/1000}.1][${$s2/1000}.1] sec.\n\n\n\n$?s259387[Mongoose Bite]?a137017[Raptor Strike][Cobra Shot] reduces the cooldown of Howl of the Pack Leader by $?c1[${$s3/1000}.1][${$s4/1000}.1] sec.", ua = "Наказ убити зменшує час перезарядження Виття ватажка зграї на $?c1[${$s1/1000}.1][${$s2/1000}.1] сек.\n\n\n\n$?s259387[Укус мангуста]?a137017[Удар раптора][Постріл кобри] зменшує час перезарядження Виття ватажка зграї на $?c1[${$s3/1000}.1][${$s4/1000}.1] сек." },
    { en = "Damage dealt by your pet$?c1[s][] is increased by $?c1[$s1][$s2]%.\n\n\n\n$?c1[Barbed Shot damage increased by $s4%][Raptor Strike damage increased by $s3%].", ua = "Шкода від $?c1[ваших улюбленців][вашого улюбленця] збільшується на $?c1[$s1][$s2]%.\n\n\n\n$?c1[Шкода Колючого пострілу збільшена на $s4%][Шкода Удару раптора збільшена на $s3%]." },
    { en = "Howl of the Pack Leader increases the damage of your Kill Command by $s1%.\n\n\n\nSummoning a Beast reduces the cooldown of $?c1[Barbed Shot][Wildfire Bomb] by $?c1[${$s2/1000}.1][${$s3/1000}.1] sec.", ua = "Виття ватажка зграї збільшує шкоду вашого Наказу убити на $s1%.\n\n\n\nВиклик звіра зменшує час перезарядження $?c1[Колючого пострілу][Запальної бомби] на $?c1[${$s2/1000}.1][${$s3/1000}.1] сек." },
    { en = "Smite extends the duration of an active Atonement by ${$s1/1000}.1 sec.", ua = "«Кара» подовжує дію активної «Покути» на ${$s1/1000}.1 сек." },
    { en = "Immediately Power Word: Radiance your target at $s2% effectiveness, and causes your next $s1 casts of Power Word: Radiance to be instant cast with $s3% reduced mana cost.", ua = "Миттєво застосовує до твоєї цілі «Слово сили: Сяйво» з ефективністю $s2%, а наступні $s1 прочитань «Слова сили: Сяйво» стають миттєвими й коштують на $s3% менше мани." },
    { en = "When your Bear is summoned, it is joined by $s1 Dire $LBeast:Beasts;.", ua = "Коли прикликається ваш Ведмідь, до нього приєднується $s1 Люта $LТварина:Тварини;." },
    { en = "The damage of your Bear's Rend Flesh is increased by $s1%.", ua = "Шкоду «Роздирання плоті» твого ведмедя збільшено на $s1%." },
    { en = "Your pet's attacks increase your Wyvern's damage bonus by $471881s1%, up to $s1%.\n\n\n\nCasting $?c1[Kill Command][Wildfire Bomb] extends the duration of your Wyvern by $?c1[${$s2/1000}.1][${$s3/1000}.1] sec, up to $?c1[$s4][$s5] additional sec.", ua = "Атаки вашого улюбленця збільшують бонус шкоди вашої віверни на $471881s1%, до $s1%.\n\n\n\nЗастосування $?c1[Наказу убити][Запальної бомби] подовжує тривалість вашої віверни на $?c1[${$s2/1000}.1][${$s3/1000}.1] сек., до $?c1[$s4][$s5] додаткових сек." },
    { en = "Shadow Word: Pain Spreads to $?s373003[${1+$373003s2} nearby enemies][a nearby enemy] when you cast Penance on the target.", ua = "Тіньове слово: Біль поширюється на $?s373003[${1+$373003s2} ворогів поблизу][ворога поблизу], коли ви застосовуєте Покуту на цілі." },
    { en = "$?c1[When your Boar deals damage, the damage of your next Cobra Shot is increased by $472640s1%.\n\n\n\nEach additional enemy damaged by your Boar causes Cobra Shot to strike $472640s3 additional $Ltarget:targets;, up to $472640u][Each time your Boar deals damage, the damage of your next Boomstick is increased by $472640s2%, up to ${$472640s2*$472640u}%].", ua = "$?c1[Коли твій Вепр завдає шкоди, шкода твого наступного Кобрового пострілу підвищується на $472640s1%.\n\n\n\nКожен додатковий ворог, ушкоджений твоїм Вепром, змушує Кобровий постріл вражати $472640s3 додаткову $Lціль:цілі:цілей;, до $472640u][Щоразу, коли твій Вепр завдає шкоди, шкода твого наступного Гримопалу підвищується на $472640s2%, до ${$472640s2*$472640u}%]." },
    { en = "Your Bleed effects deal $?c1[$s1][$s2]% increased damage.", ua = "Ваші ефекти кровотечі завдають на $?c1[$s1][$s2]% більше шкоди." },
    { en = "Survival of the Fittest now summons a Turtle to aid you, further increasing its damage reduction effect by ${-$s1}%.", ua = "«Виживання найсильнішого» тепер викликає черепаху тобі на допомогу, додатково посилюючи його ефект зменшення шкоди на ${-$s1}%." },
    { en = "When Disengage removes a movement impairing effect, its cooldown is reduced by ${$s1/1000} sec.", ua = "Коли «Відступ» знімає ефект, що обмежує рух, його перезарядження скорочується на ${$s1/1000} сек." },
    { en = "When an enemy is stunned by Binding Shot, it is dragged to Binding Shot's center.", ua = "Коли ворога приголомшує «Сковувальний постріл», його затягує в центр дії «Сковувального пострілу»." },
    { en = "Casting $?c1[Bestial Wrath][Takedown] grants Howl of the Pack Leader and causes your next Kill Command to rouse the nearby wildlife into a Stampede, charging your target and dealing ${$201594s1* $s1} Physical damage over $201430d.", ua = "Творення $?c1[Звіриного гніву][Повалення] надає Виття ватажка зграї та змушує ваш наступний Наказ убити збурити дику природу поблизу до Навали, що мчить на вашу ціль і завдає ${$201594s1* $s1} фізичної шкоди протягом $201430d." },
    { en = "Aimed Shot deals $s1% increased damage.\n\n\n\nRapid Fire deals $s2% increased damage.", ua = "Прицільний постріл завдає на $s1% більше шкоди.\n\n\n\nШвидкий вогонь завдає на $s2% більше шкоди." },
    { en = "Casting Trueshot or Volley grants Double Tap, causing your next Aimed Shot to fire again at $s2% power, or your next Rapid Fire to fire $s3% additional shots during its channel.", ua = "Прочитання «Влучної стрільби» або «Залпу» дарує «Дублет»: твій наступний «Прицільний постріл» вистрілює ще раз із $s2% сили, а наступний «Швидкий вогонь» випускає на $s3% більше пострілів під час спрямування." },
    { en = "Rapid Fire grants Precise Shots.", ua = "Швидкий вогонь дає Точні постріли." },
    { en = "Casting Explosive Shot has a $s1% chance to grant Lock and Load.", ua = "Прочитання «Вибухового пострілу» з імовірністю $s1% дарує «Бойову готовність»." },
    { en = "Consuming Precise Shots has a $s3% to grant Precise Shots.\n\n\n\nThe damage bonus of Precise Shots is increased by an additional $s1%.", ua = "Витрата Точних пострілів має $s3% шансу надати Точні постріли.\n\n\n\nБонус до шкоди Точних пострілів додатково збільшено на $s1%." },
    { en = "$?a1217607[][|CFFffffffRequires $c Fury|R]\n\nUnleash a beam of concentrated void energy, dealing $1213649s1 Cosmic damage$?a1217607[][ and consuming $1213649c Fury] every ${$t1}.1 sec.$?a1217607[\n\n\n\nChanneling Void Ray substantially reduces your Fury drain.][\n\n\n\nEffect ends after $d or upon reaching $s4 Fury.]", ua = "$?a1217607[][|CFFffffffПотребує $c люті|R]\n\nВивільняє промінь сконцентрованої енергії Порожнечі, завдаючи $1213649s1 космічної шкоди$?a1217607[][ та споживаючи $1213649c люті] кожні ${$t1}.1 с.$?a1217607[\n\n\n\nКаналізація Променя Порожнечі значно зменшує втрату вашої люті.][\n\n\n\nЕфект завершується через $d або при досягненні $s4 люті.]" },
    { en = "Your Spotting Eagle descends from the skies, stunning your target for $24394d.$?s321468[\n\n\n\nTargets stunned by Intimidation deal $321469s1% less damage to you for $321469d after the effect ends.][]\n\n\n\nThis ability does not require line of sight when used against players.", ua = "Ваш орел-спостерігач спускається з небес, оглушуючи вашу ціль на $24394d.$?s321468[\n\n\n\nЦілі, оглушені Залякуванням, завдають вам на $321469s1% менше шкоди протягом $321469d після завершення ефекту.][]\n\n\n\nЦя здібність не потребує прямої видимості, коли застосовується проти гравців." },
    { en = "Your Spotting Eagle gains the Cunning specialization, granting you Master's Call and Pathfinding.\n\n\n\n$@spellicon53271 $@spellname53271\n\n$@spelldesc53271\n\n\n\n$@spellicon264656 $@spellname264656\n\nYour movement speed is increased by $s2%.", ua = "Ваш орел-спостерігач отримує спеціалізацію Хитрість, що надає вам Поклик господаря та Пошук шляху.\n\n\n\n$@spellicon53271 $@spellname53271\n\n$@spelldesc53271\n\n\n\n$@spellicon264656 $@spellname264656\n\nВаша швидкість пересування збільшена на $s2%." },
    { en = "Your Spotting Eagle gains the Tenacity specialization, granting you Endurance Training and Air Superiority.\n\n\n\n$@spellicon264662 $@spellname264662\n\nYou gain $s2% increased maximum health.\n\n\n\n$@spellicon470937 $@spellname470937\n\n$@spelldesc470937", ua = "Ваш орел-спостерігач отримує спеціалізацію Завзятість, що надає вам Тренування витривалості та Перевагу в повітрі.\n\n\n\n$@spellicon264662 $@spellname264662\n\nВи отримуєте на $s2% більше максимального здоров'я.\n\n\n\n$@spellicon470937 $@spellname470937\n\n$@spelldesc470937" },
    { en = "Rake, Rip, and Thrash damage increased by $s2%.", ua = "Шкода «Дряпання», «Розриву» і «Шмагання» збільшена на $s2%." },
    { en = "Physical damage dealt by your abilities increased by $?a137012[$s3][$s1]%.", ua = "Фізична шкода твоїх здібностей збільшена на $?a137012[$s3][$s1]%." },
    { en = "Magical damage dealt by your spells increased by $?a137012[$s3][$s1]%.", ua = "Магічна шкода твоїх заклять збільшена на $?a137012[$s3][$s1]%." },
    { en = "When a hit deals more than $s2% of your maximum health, instantly heal for $474683s1% of your health.\n\n\n\nThis effect cannot occur more than once every $s3 seconds.", ua = "Коли удар завдає понад $s2% вашого максимального здоров'я, ви миттєво зцілюєтеся на $474683s1% свого здоров'я.\n\n\n\nЦей ефект не може спрацьовувати частіше ніж раз на $s3 секунд." },
    { en = "Trueshot now increases your critical strike chance by an additional $s1% and increases your critical strike damage by an additional $s2%.", ua = "«Влучний постріл» тепер підвищує твій шанс критичного удару додатково на $s1%, а шкоду критичних ударів — додатково на $s2%." },
    { en = "Your pet damage is increased by $s1% and your pet is $474751s1% larger.", ua = "Шкода твого улюбленця збільшена на $s1%, а сам улюбленець на $474751s1% більший." },
    { en = "Form a bond with an ally. Your self-healing also heals your bonded ally for $474754s1% of the amount healed. Your healing to your bonded ally also heals you for $474754s2% of the amount healed.", ua = "Утворює зв'язок із союзником. Твоє самозцілення також зцілює зв'язаного союзника на $474754s1% від обсягу зцілення. Твоє зцілення зв'язаного союзника також зцілює тебе на $474754s2% від обсягу зцілення." },
    { en = "Well-Honed Instincts can trigger up to once every ${$382912d+$s1} sec.", ua = "«Відточені інстинкти» можуть спрацьовувати щонайбільше раз на ${$382912d+$s1} сек." },
    { en = "Periodic damage from $?a445465[Wither][Immolate] has a $s1% chance to fire a Demonfire bolt at $s3% increased effectiveness.\n\n\n\nIncinerate has a $s2% chance to fire a Demonfire bolt at $s3% increased effectiveness.", ua = "Періодична шкода від $?a445465[Згасання][Спалення] має $s1% шанс випустити стрілу демонічного вогню з підвищеною на $s3% дієвістю.\n\n\n\nСпопеляння має $s2% шанс випустити стрілу демонічного вогню з підвищеною на $s3% дієвістю." },
    { en = "Calls down a rain of hellfire upon your target, dealing ${$42223m1*8} Fire damage over $d to enemies in the area.\n\n\n\n|cFFFFFFFFThis spell is cast at your target.|r", ua = "Прикликає дощ пекельного вогню на вашу ціль, завдаючи ${$42223m1*8} шкоди від вогню впродовж $d ворогам у цій ділянці.\n\n\n\n|cFFFFFFFFЦе закляття твориться на вашій цілі.|r" },
    { en = "Your healing is increased by $s1% while Apotheosis is active.\n\n\n\nCasting Apotheosis causes your next $1216314U Prayer of Healing casts to be instant and heal for $1216314s2% more.", ua = "Ваше зцілення збільшується на $s1%, поки активний Апофеоз.\n\n\n\nТворіння Апофеозу робить ваші наступні $1216314U прочитань Молитовного зцілення миттєвими та зцілює на $1216314s2% більше." },
    { en = "Increases the duration of Apotheosis by ${$s1/1000} sec.", ua = "Подовжує дію «Апофеозу» на ${$s1/1000} сек." },
    { en = "$s1% of healing done with Flash Heal is replicated to $s2 injured allies within $1215266A2 yards.", ua = "$s1% зцілення від «Швидкого зцілення» відтворюється на $s2 поранених союзниках у радіусі $1215266A2 м." },
    { en = "Reduces the cooldown of your Holy Words by ${$s1/-1000} sec.", ua = "Скорочує перезарядження твоїх «Святих слів» на ${$s1/-1000} сек." },
    { en = "Consume damage increased by $s1%.\n\n\n\nConsume generates a Soul Fragment.", ua = "Шкода Поглинання збільшена на $s1%.\n\n\n\nПоглинання створює Уламок душі." },
    { en = "Shattering enemies inside your Blizzard increases Shatter's area damage by $s1%.", ua = "Дроблення ворогів усередині твоєї Хуртовини збільшує шкоду Дроблення по області на $s1%." },
    { en = "Envelop yourself in razor-sharp winds, then lunge forward dealing $1217411s1 Nature damage to enemies in your path. Damage reduced beyond $s3 enemies.\n\n\n\nHold to increase lunge distance.", ua = "Огортаєте себе гострими, як лезо, вітрами, а тоді кидаєтеся вперед, завдаючи $1217411s1 шкоди від сил природи ворогам на вашому шляху. Шкода зменшується після $s3 ворогів.\n\n\n\nУтримуйте, щоб збільшити відстань випаду." },
    { en = "When summoned, Dire Beasts gain Beast Cleave at $s1% effectiveness for ${$s2/1000}.1 sec.", ua = "Прикликані люті звірі отримують «Звірине розсікання» з $s1% ефективності на ${$s2/1000}.1 сек." },
    { en = "Earth Shield $?c3[and Water Shield no longer lose charges and are][no longer loses charges and is] ${100+$s1}% effective.", ua = "Земляний щит $?c3[і Водяний щит більше не втрачають зарядів і мають][більше не втрачає зарядів і має] ефективність ${100+$s1}%." },
    { en = "Efflorescence healing increased by $s1%, and it now automatically grows beneath your Lifebloom target's feet.", ua = "Зцілення «Розквіту» збільшене на $s1%, і тепер він автоматично виростає під ногами цілі твого «Життєцвіту»." },
    { en = "Sundering transforms into a single use Primordial Storm for $1218125d after it is cast.\n\n\n\n$@spellicon1218047$@spellname1218047\n\nDevastate nearby enemies with a Primordial Storm dealing $1218113s1 Flamestrike, $1218116s1 Froststrike, $1218118s1 Stormstrike damage, and unleashing a Lightning Bolt or a Chain Lightning at $s2% effectiveness. Deals reduced damage beyond $s3 targets.\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased damage.|r", ua = "Розкол перетворюється на одноразову Первісну бурю на $1218125d після прочитання.\n\n\n\n$@spellicon1218047$@spellname1218047\n\nСпустошує ближніх ворогів Первісною бурею, завдаючи $1218113s1 шкоди Полум'яним ударом, $1218116s1 Морозним ударом, $1218118s1 Штормовим ударом, і вивільняє Блискавку або Ланцюгову блискавку з $s2% ефективністю. Завдає зменшеної шкоди понад $s3 цілей.\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення шкоди.|r" },
    { en = "$?c1[Fire Breath deals its damage][Fire Breath and Dream Breath deal their damage and healing] $s1% more often.", ua = "$?c1[«Вогняний подих» завдає своєї шкоди][«Вогняний подих» і «Подих мрій» завдають своєї шкоди та зцілення] на $s1% частіше." },
    { en = "Disintegrate deals damage $s1% more often, but deals $s2% less damage.", ua = "Дезінтеграція завдає шкоди на $s1% частіше, але на $s2% менше." },
    { en = "Blade Dance automatically triggers Throw Glaive on your primary target for $s3% damage and each slash has a $s2% chance to Throw Glaive an enemy for $s1% damage.", ua = "«Танець клинків» автоматично спрацьовує «Кидком глефи» по твоїй основній цілі, завдаючи $s3% шкоди, а кожен помах має $s2% шанс кинути глефу у ворога, завдаючи $s1% шкоди." },
    { en = "While in Void Metamorphosis, every $s1 Soul Fragments harvested grants access to Collapsing Star.\n\n\n\n$@spellicon1221150 $@spellname1221150\n\n$@spelldesc1221150", ua = "Під час Метаморфози Порожнечі кожні $s1 зібраних фрагментів душі дають доступ до Колапсу зорі.\n\n\n\n$@spellicon1221150 $@spellname1221150\n\n$@spelldesc1221150" },
    { en = "The cast range of Voidblade, Consume Magic, and Disrupt are increased by $s1 yds.", ua = "Дальність застосування «Клинка Порожнечі», «Поглинання магії» та «Переривання» збільшена на $s1 м." },
    { en = "Regain access to Call Pet.\n\n\n\nWhile outdoors, your pet deals $s1% increased damage and takes $s2% reduced damage.", ua = "Повертає доступ до Прикликання улюбленця.\n\n\n\nНа відкритій місцевості ваш улюбленець завдає на $s1% більше шкоди й отримує на $s2% менше шкоди." },
    { en = "Upon reaching maximum stacks of Arcane Salvo, your next Arcane Barrage deals $s1% increased damage.", ua = "Після досягнення максимальної кількості зарядів «Арканного залпу» твій наступний «Арканний шквал» завдає на $s1% більше шкоди." },
    { en = "Damage from Void Ray has a $s1% increased chance to generate a Soul Fragment.", ua = "Шкода від Променя Порожнечі має на $s1% більший шанс породити фрагмент душі." },
    { en = "Fully channeling Void Ray upgrades your Reap to Eradicate.\n\n\n\n$@spellicon1225826 $@spellname1225826\n\n$@spelldesc1225826", ua = "Повна каналізація Променя Порожнечі покращує ваші Жнива до Викорінення.\n\n\n\n$@spellicon1225826 $@spellname1225826\n\n$@spelldesc1225826" },
    { en = "Casting Swiftmend or Wild Growth summons a Treant that casts Nourish on that target or a nearby ally periodically, healing for ${$422090m1}. Lasts $102693d.", ua = "Творення «Швидкого зцілення» або «Буйного росту» прикликає трента, який періодично творить «Живлення» на ту саму ціль або найближчого союзника, зцілюючи на ${$422090m1}. Триває $102693d." },
    { en = "Summons a massive shadowy appendage to slam the ground, dealing $1227621s1 Shadow damage in front of you and $s1 yds around your target.\n\n\n\nApplies Vampiric Touch to up to $s3 enemies, prioritizing ones without Vampiric Touch.\n\n\n\n|cFFFFFFFFGenerates $/100;s2 Insanity.", ua = "Прикликає велетенський тіньовий відросток, що вдаряє об землю, завдаючи $1227621s1 шкоди Тінню перед вами та в межах $s1 ярдів навколо вашої цілі.\n\n\n\nНакладає Вампіричний дотик на щонайбільше $s3 ворогів, віддаючи перевагу тим, хто без Вампіричного дотику.\n\n\n\n|cFFFFFFFFГенерує $/100;s2 Безуму." },
    { en = "Each Collapsing Star you cast increases the damage of your next Collapsing Star by $1227338s1%.", ua = "Кожен сотворений Колапс зорі збільшує шкоду наступного Колапсу зорі на $1227338s1%." },
    { en = "Summoned minions last $s2% longer and deal an additional $s1% damage.", ua = "Прикликані поплічники існують на $s2% довше і завдають додатково $s1% шкоди." },
    { en = "Obliterate and Frostscythe consume all Killing Machines to deal $s2% increased critical strike damage and grant ${$1230916s1/10}.1% Haste for $1230916d for each stack consumed.\n\n\n\nMultiple applications may overlap.", ua = "Знищення та Морозна коса поглинають усі заряди Машини вбивства, завдаючи на $s2% більше шкоди від критичних ударів і даючи ${$1230916s1/10}.1% Поспіху на $1230916d за кожен поглинутий заряд.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Rime empowered Howling Blast unleashes $s2 icy blades at its target that deal $1231083s1 Frost damage and have $s1% chance to grant Killing Machine.", ua = "Посилений «Памороззю» «Виючий шквал» випускає в ціль $s2 крижаних клинків, які завдають $1231083s1 шкоди від морозу й мають $s1% шансу дати «Машину вбивства»." },
    { en = "Frost Strike and Glacial Advance now cause your next Frost Strike and Glacial Advance to deal $1230273s1% increased damage and cost ${$1230273s2/10} more Runic Power. \n\n\n\nThis effect stacks until the next Runic Empowerment.", ua = "Удар морозу та Льодовиковий поступ тепер змушують ваші наступні Удар морозу та Льодовиковий поступ завдавати на $1230273s1% більше шкоди й коштувати на ${$1230273s2/10} більше рунічної сили. \n\n\n\nЦей ефект накопичується до наступного Рунічного підсилення." },
    { en = "Howling Blast now hits an additional target with maximum effectiveness. \n\n\n\nRime increases Howling Blast damage done by an additional $s1%.", ua = "Виючий вибух тепер уражає ще одну ціль з максимальною ефективністю. \n\n\n\nПаморозь збільшує шкоду від Виючого вибуху додатково на $s1%." },
    { en = "Obliterate deals $s4% increased damage and has a chance to tether the souls of its target and a nearby enemy to yours.\n\n\n\nFrost Strike severs the tethers, dealing $1233619s1 Shadowfrost damage to both foes.", ua = "Знищення завдає на $s4% більше шкоди й має шанс прив'язати душі своєї цілі та ворога поблизу до вашої.\n\n\n\nМорозний удар розриває ці пута, завдаючи $1233619s1 шкоди тіньоморозом обом ворогам." },
    { en = "Casting Voidform summons a Mindbender for $200174d.\n\n\n\n$@spellicon200174 $@spellname200174\n\nSummons a shadowy fiend to attack your target.\n\n\n\n|cFFFFFFFFGenerates ${$200010s1/100} Insanity each time the Mindbender attacks.|r", ua = "Застосування Форми Порожнечі прикликає Розумокрута на $200174d.\n\n\n\n$@spellicon200174 $@spellname200174\n\nПрикликає тіньового виплідка, що атакує вашу ціль.\n\n\n\n|cFFFFFFFFДає ${$200010s1/100} Безумства щоразу, коли Розумокрут атакує.|r" },
    { en = "Casting Shadow Word: Madness increases the duration of Voidform by ${$228260s2/1000}.1 sec.\n\n\n\nEach time this occurs during Voidform, its effectiveness is reduced by $s3%.", ua = "Прочитання «Слова тіні: Безум» подовжує тривалість Форми Порожнечі на ${$228260s2/1000}.1 сек.\n\n\n\nЩоразу, коли це стається під час Форми Порожнечі, ефективність зменшується на $s3%." },
    { en = "$@spellicon156910 $@spellname156910:\n\nAllies with Beacon of Light or Beacon of Faith are healed for $53563s5 every $53563t5 sec.\n\n\n\n$@spellicon200025 $@spellname200025:\n\nBeacon of Virtue instantly heals allies for $1232617s1.", ua = "$@spellicon156910 $@spellname156910:\n\nСоюзники з Маяком Світла або Маяком віри зцілюються на $53563s5 кожні $53563t5 с.\n\n\n\n$@spellicon200025 $@spellname200025:\n\nМаяк чесноти миттєво зцілює союзників на $1232617s1." },
    { en = "Dire Beasts will now obey your Kill Command, dealing its damage at $s1% effectiveness.\n\n\n\nBestial Wrath now sends your Dire Beasts into a rage, increasing their damage dealt by $1235388s1% for $186254d. Dire Beasts summoned during a Bestial Wrath will benefit at a reduced duration.", ua = "Лютозвірі тепер коряться вашому Наказу вбити, завдаючи його шкоди з $s1% ефективністю.\n\n\n\nЗвіриний гнів тепер вводить ваших Лютозвірів у лють, збільшуючи завдану ними шкоду на $1235388s1% протягом $186254d. Лютозвірі, прикликані під час Звіриного гніву, отримають цей ефект на скорочений час." },
    { en = "You gain a bonus while in each form inspired by the breadth of your Druidic knowledge:\n\n\n\nNo Form: $378989s2% Magic Damage\n\nCat Form: $378990s2% Stamina\n\nBear Form: $378991s2% Movement Speed\n\nMoonkin Form: $378992s2% Area damage taken reduction", ua = "У кожній подобі ви отримуєте бонус, навіяний широтою ваших друїдичних знань:\n\n\n\nБез подоби: $378989s2% магічної шкоди\n\nКотяча подоба: $378990s2% витривалості\n\nВедмежа подоба: $378991s2% швидкості пересування\n\nПодоба сови: $378992s2% зменшення отримуваної шкоди по площі" },
    { en = "The damage bonus of Precise Shots is increased by an additional $s1%.", ua = "Бонус до шкоди «Точних пострілів» додатково збільшено на $s1%." },
    { en = "Corrupt and evolve your Ghoul into a Monstrosity, greatly empowering its abilities for $d.\n\n\n\nDeath Coil and Epidemic extends the duration of this effect by ${$390268s1/1000}.1 sec.", ua = "Спотворює та розвиває вашого Гуля в Потвору, значно підсилюючи його здібності на $d.\n\n\n\nПокров смерті та Епідемія продовжують тривалість цього ефекту на ${$390268s1/1000}.1 сек." },
    { en = "Unleash an eruption of void energy, dealing $s2 Cosmic damage and stunning your target and all nearby enemies for $d.", ua = "Вивільняє вибух енергії Порожнечі, завдаючи $s2 космічної шкоди й оглушуючи твою ціль і всіх ворогів поруч на $d." },
    { en = "Death and Decay deals its damage ${(1/(1+($s1/100))-1)*100}% faster.", ua = "«Смерть і тлін» завдає свою шкоду на ${(1/(1+($s1/100))-1)*100}% швидше." },
    { en = "Armor increased by $s1%.", ua = "Броня збільшена на $s1%." },
    { en = "Damage you take from area of effect attacks is reduced by $s1%. Spell Reflection reduces magic damage taken by an additional $s2%.", ua = "Шкоду, яку ти отримуєш від атак по області, зменшено на $s1%. Віддзеркалення заклять додатково зменшує отримувану магічну шкоду на $s2%." },
    { en = "You have a $s2% chance to disrupt magic damage dealt to you, reducing the damage it deals by $s3%.", ua = "З шансом $s2% ти розбиваєш спрямовану на тебе магічну шкоду, зменшуючи її на $s3%." },
    { en = "Defensive Stance reduces damage taken by an additional $s1%.", ua = "Захисна стійка зменшує отримувану шкоду ще на $s1%." },
    { en = "Execute hits up to $s1 additional $Ltarget:targets; for $s2% damage.", ua = "Страта вражає до $s1 додаткових $Lцілі:цілей; на $s2% шкоди." },
    { en = "Your attacks have a chance to target a nearby enemy with Ravager for ${$s1/1000} sec.", ua = "Твої атаки мають шанс націлити «Нищителя» на ворога поблизу на ${$s1/1000} сек." },
    { en = "Mind Blast deals $s2% increased damage, but costs $s1% more mana.", ua = "«Вибух розуму» завдає на $s2% більше шкоди, але коштує на $s1% більше мани." },
    { en = "Bleak Powder now applies Black Arrow's periodic effect to all enemies it damages.\n\n\n\nIf Bleak Powder damages $s2 or more enemies, gain $?c1[Beast Cleave][Trick Shots] if talented.", ua = "Похмурий порох тепер накладає періодичний ефект Чорної стріли на всіх ворогів, яким завдає шкоди.\n\n\n\nЯкщо Похмурий порох завдає шкоди $s2 або більше ворогам, ти отримуєш $?c1[Звіриний розруб][Хитрі постріли], якщо обрав цей талант." },
    { en = "Soul Fragments grant $1232310s1% increased damage for $1232310d. Multiple applications may overlap.", ua = "Фрагменти душ збільшують шкоду на $1232310s1% протягом $1232310d. Кілька ефектів можуть діяти одночасно." },
    { en = "Bronze healing and absorption increased by $s1%.", ua = "Бронзове зцілення і поглинання посилено на $s1%." },
    { en = "After fully channeling Void Ray, the cooldown of Reap is reset and your next Reap will collect up to $1238495s1 additional Soul Fragments.", ua = "Після повного спрямування «Променя Порожнечі» перезарядження «Жнив» скидається, а твої наступні «Жнива» зберуть до $1238495s1 додаткових фрагментів душі." },
    { en = "Consuming Rime reduces the cooldown of Empower Rune Weapon by ${$s1/-1000} sec.", ua = "Поглинання Паморозі скорочує перезарядження Посилення рунічної зброї на ${$s1/-1000} сек." },
    { en = "Each Soul Fragment gathered by Reap increases its damage by $s1%.", ua = "Кожен фрагмент душі, зібраний Жнивами, збільшує їхню шкоду на $s1%." },
    { en = "Critical strike damage of your minions is increased by $1238902s1%", ua = "Критична шкода твоїх слуг збільшена на $1238902s1%" },
    { en = "After dealing damage with The Hunt or Voidblade, Voidblade is replaced with Hungering Slash for $1239525d.\n\n\n\n$@spellicon1239123 $@spellname1239123\n\n$@spelldesc1239123\n\n\n\nHungering Slash grants a temporary charge of Vengeful Retreat and causes your next Vengeful Retreat within $1223157d to deal an additional $1239526s1 Cosmic damage.", ua = "Після завдання шкоди Полюванням або Клинком Порожнечі Клинок Порожнечі замінюється на Ненаситний розтин на $1239525d.\n\n\n\n$@spellicon1239123 $@spellname1239123\n\n$@spelldesc1239123\n\n\n\nНенаситний розтин дарує тимчасовий заряд Мстивого відступу й змушує ваш наступний Мстивий відступ протягом $1223157d завдати додатково $1239526s1 космічної шкоди." },
    { en = "Reap gains an additional charge.", ua = "«Жнива» отримують додатковий заряд." },
    { en = "Your empower spells are $s1% more effective. While charging a healing empower spell, you cannot be knocked back.", ua = "Твої підсилювані закляття на $s1% ефективніші. Поки ти заряджаєш цілюще підсилюване закляття, тебе неможливо відкинути." },
    { en = "You may draw the sun and moon into alignment for $48517d, empowering either your Nature or Arcane spells. Casting Wrath or Starfire changes what mode of Eclipse will be entered, and the two modes of Eclipse share a button and $?a1240188[${$s1+$1240188s1/1000}][$s1] sec cooldown.\n\n\n\n$@spellicon48517 $@spellname48517\n\nNature spells deal $48517s1% additional damage and Wrath damage is increased by $48517s3%.\n\n\n\n$@spellicon48518 $@spellname48518\n\nArcane spells deal $48518s1% additional damage and Starfire damage is increased by $48518s3%.", ua = "Ви можете звести сонце й місяць у вирівнювання на $48517d, посилюючи свої закляття природи або аркани. Застосування Гніву чи Зоряного вогню змінює, в який режим Затемнення ви ввійдете, а обидва режими Затемнення мають спільну кнопку та перезарядження $?a1240188[${$s1+$1240188s1/1000}][$s1] сек.\n\n\n\n$@spellicon48517 $@spellname48517\n\nЗакляття природи завдають на $48517s1% більше шкоди, а шкода від Гніву підвищена на $48517s3%.\n\n\n\n$@spellicon48518 $@spellname48518\n\nЗакляття аркани завдають на $48518s1% більше шкоди, а шкода від Зоряного вогню підвищена на $48518s3%." },
    { en = "Moonfire, Sunfire, and Shooting Stars damage increased by $s1%.", ua = "Шкода «Місячного вогню», «Сонячного вогню» і «Падучих зір» збільшена на $s1%." },
    { en = "The cooldowns of Lunar Eclipse and Solar Eclipse are reduced by ${-$s1/1000} sec.", ua = "Перезарядження Місячного затемнення та Сонячного затемнення зменшено на ${-$s1/1000} сек." },
    { en = "Increases Mastery by $s2% and reduces the cast time of your Summon Demonic Tyrant and Summon Felguard by ${$s1/-1000}.1 sec.", ua = "Збільшує майстерність на $s2% і скорочує час творення твоїх заклять Прикликання демонічного тирана та Прикликання вартового Скверни на ${$s1/-1000}.1 сек." },
    { en = "Damage from Voidblade and the Hunt increases the damage your target takes from you by $1241532s1% for $1241532d. Multiple applications may overlap.", ua = "Шкода від Клинка Порожнечі та Полювання збільшує шкоду, якої ціль зазнає від тебе, на $1241532s1% на $1241532d. Кілька накладань можуть діяти одночасно." },
    { en = "After fully channeling Void Ray, gain $1241922s1 Fury.", ua = "Після повного спрямування «Променя Порожнечі» ти отримуєш $1241922s1 од. люті." },
    { en = "Void Ray deals $s1% more damage when damaging $s2 $Ltarget:targets;.", ua = "Промінь Порожнечі завдає на $s1% більше шкоди, коли вражає $s2 $Lціль:цілі:цілей;." },
    { en = "Collapsing Star now generates $s1 Soul $LFragment:Fragments;.", ua = "Зоря, що згасає, тепер генерує $s1 $LФрагмент:Фрагменти; душі." },
    { en = "Entering any Eclipse has a $s1% chance to grant the benefits of both Lunar and Solar Eclipse.", ua = "Входження в будь-яке затемнення з імовірністю $s1% дарує переваги одночасно місячного й сонячного затемнення." },
    { en = "Starfall deals its damage ${100*(-1/($s1/100)-1)}% faster.", ua = "Зорепад завдає свою шкоду на ${100*(-1/($s1/100)-1)}% швидше." },
    { en = "When you exit Eclipse with less than ${$s1/10} Astral Power, Wrath and Starfire's cast times are reduced by $1240285s1% for $1240285d or until you enter an Eclipse.", ua = "Коли ти виходиш із «Затемнення», маючи менш ніж ${$s1/10} астральної сили, час творення «Гніву» та «Зоряного вогню» зменшується на $1240285s1% на $1240285d або доки ти не ввійдеш у «Затемнення»." },
    { en = "Shadow Word: Death deals damage $s1 additional $Ltime:times; at $s2% effectiveness.", ua = "Тіньове слово: Смерть завдає шкоди $s1 додатковий $Lраз:рази; з $s2% ефективністю." },
    { en = "Increases the chance for Shadowy Insight to occur by $s2%. When consuming Shadowy Insight, Mind Blast generates ${$s1/100} additional Insanity.", ua = "Збільшує ймовірність спрацювання «Тіньового прозріння» на $s2%. Коли «Вибух розуму» витрачає «Тіньове прозріння», він породжує додатково ${$s1/100} од. божевілля." },
    { en = "The damage bonus from your Mastery: Shadow Weaving gains $s1% additional benefit from Shadow Word: Madness.", ua = "Бонус шкоди від твоєї «Майстерності: Тіньове плетиво» отримує на $s1% більше користі від «Слова тіні: Безумство»." },
    { en = "Lunar Eclipse and Solar Eclipse have one additional charge.", ua = "«Місячне затемнення» і «Сонячне затемнення» мають один додатковий заряд." },
    { en = "Every time Starfall drops a wave of stars, a meteorite also falls on up to $s1 targets in its range, each dealing $1240913s1 Astral damage.", ua = "Щоразу, коли «Зорепад» скидає хвилю зір, метеорит також падає на щонайбільше $s1 цілей у його радіусі, завдаючи кожній $1240913s1 астральної шкоди." },
    { en = "A strong herbal brew that coalesces purified chi escaping your body into a celestial guard, absorbing $s2% of incoming damage, up to $<absorb> total.", ua = "Міцний трав'яний відвар, що збирає очищене ці, яке покидає ваше тіло, в небесний захист, поглинаючи $s2% вхідної шкоди, до $<absorb> загалом." },
    { en = "Healing Spheres now heal over $1241109d, and their healing is increased by up to $s1% based on your missing health.", ua = "«Цілющі сфери» тепер зцілюють поступово протягом $1241109d, а їхнє зцілення збільшується до $s1% залежно від втраченого тобою здоров'я." },
    { en = "The effectiveness of your Stagger is increased by up to $s1%, based on your missing health.", ua = "Ефективність твого «Відтермінування» підвищується щонайбільше на $s1%, залежно від того, скільки здоров'я тобі бракує." },
    { en = "Activating Avenging Wrath releases the Light within yourself, healing $200652s2 injured allies instantly and an injured ally every $200652t1 sec within $200653A1 yds for $200654s1.\n\n\n\nAllies healed also receive $200654s2% increased healing from your Holy Light, Flash of Light, and Holy Shock spells for $200654d.", ua = "Активація «Караючого гніву» вивільняє Світло всередині вас, миттєво зцілюючи $200652s2 поранених союзників, а також одного пораненого союзника кожні $200652t1 с у радіусі $200653A1 м на $200654s1.\n\n\n\nЗцілені союзники також отримують на $200654s2% більше зцілення від ваших заклять «Священне світло», «Спалах світла» та «Священний удар» протягом $200654d." },
    { en = "During Avenging Wrath, Judgment is empowered into Hammer of Wrath.$?c3[\n\n\n\n$@spellicon24275$@spellname24275\n\n$@spelldesc24275][\n\n\n\n$@spellicon1241413 $@spellname1241413\n\n$@spelldesc1241413]", ua = "Під час Гніву месника Вирок підсилюється до Молота гніву.$?c3[\n\n\n\n$@spellicon24275$@spellname24275\n\n$@spelldesc24275][\n\n\n\n$@spellicon1241413 $@spellname1241413\n\n$@spelldesc1241413]" },
    { en = "Judgment critical strikes empower your next Word of Glory to automatically activate Light of Dawn at $s2% effectiveness.", ua = "Критичні удари «Осуду» наснажують твоє наступне «Слово слави», і воно автоматично активує «Світло світанку» з $s2% ефективності." },
    { en = "A pulse of Arcane magic erupts from underneath your target, dealing $s1 Arcane damage to all enemies within $A1 yds. Damage reduced beyond $s3 targets.\n\n\n\nEach Arcane Charge increases damage by $36032s1%, radius by $36032s6 yds, and mana cost by $36032s5%.$?a137021[\n\n\n\n|cFFFFFFFFGenerates $s2 Arcane $LCharge:Charges;.|r][]", ua = "Імпульс арканної магії вивергається з-під вашої цілі, завдаючи $s1 арканної шкоди всім ворогам у радіусі $A1 ярдів. Шкода зменшена при понад $s3 цілях.\n\n\n\nКожен Арканний заряд збільшує шкоду на $36032s1%, радіус на $36032s6 ярдів і вартість мани на $36032s5%.$?a137021[\n\n\n\n|cFFFFFFFFПороджує $s2 $Lарканний заряд:арканні заряди:арканних зарядів;.|r][]" },
    { en = "Avenging Wrath's cooldown is reduced by ${$s1/-1000} sec, but its duration is reduced by ${$s2/-1000}.1 sec.\n\n\n\nAvenging Crusader's cooldown is reduced by ${$s3/-1000}.1 sec, but its duration is reduced by ${$s4/-1000}.1 sec.", ua = "Перезарядження «Караючого гніву» зменшено на ${$s1/-1000} с, але його тривалість зменшено на ${$s2/-1000}.1 с.\n\n\n\nПерезарядження «Караючого хрестоносця» зменшено на ${$s3/-1000}.1 с, але його тривалість зменшено на ${$s4/-1000}.1 с." },
    { en = "Activating Aura Mastery also casts a Divine Toll at $s1% effectiveness.", ua = "Активація «Майстерності аур» також творить «Божественний подзвін» з $s1% ефективності." },
    { en = "Shadows guide your strikes, increasing the damage of your Scourge Strike by $s1%, and causing it to grant you Clawing Shadows up to $1241569u times.\n\n\n\nFor each stack of Clawing Shadows, your Scourge Strike chains to an additional enemy. Each subsequent chain deals $s3% reduced damage.", ua = "Тіні скеровують ваші удари, збільшуючи шкоду Удару погибелі на $s1% і даючи вам Кігтисті тіні до $1241569u разів.\n\n\n\nЗа кожен заряд Кігтистих тіней ваш Удар погибелі перекидається на ще одного ворога. Кожне наступне перекидання завдає на $s3% менше шкоди." },
    { en = "Verdant Embrace healing is increased by $s1%. In addition, it no longer causes you to leap to your target, instead sending forth a Dream Simulacrum.", ua = "Зцілення від Зелених обіймів збільшено на $s1%. Крім того, ти більше не стрибаєш до цілі — натомість посилаєш до неї Симулякр Сну." },
    { en = "Verdant Embrace gains an additional charge.", ua = "Зелені обійми отримують додатковий заряд." },
    { en = "Each Lesser Ghoul increases the damage of your permanent Ghoul by $s1%, and Dark Transformation additionally empowers the Claw attacks of your Lesser Ghouls to Sweeping Claws.\n\n\n\n$@spellicon91778$@spellname91778\n\n$@spelldesc91778", ua = "Кожен Менший вурдалак збільшує шкоду вашого постійного Вурдалака на $s1%, а Темне перетворення додатково підсилює атаки Кігтів ваших Менших вурдалаків до Розмашистих кігтів.\n\n\n\n$@spellicon91778$@spellname91778\n\n$@spelldesc91778" },
    { en = "Word of Glory and Light of Dawn now convert $s2% of their healing into an absorb shield instead.", ua = "«Слово слави» та «Світло світанку» тепер перетворюють $s2% свого зцілення на поглинальний щит." },
    { en = "While at maximum health, targets with Beacon of Light generate an absorb shield equal to $s1% of their health every $53563t6 sec, up to a maximum of $s2%.", ua = "Цілі з «Маяком світла», маючи повне здоров'я, кожні $53563t6 сек. створюють поглинальний щит у розмірі $s1% свого здоров'я, аж до максимуму $s2%." },
    { en = "Putrefy causes your permanent Ghoul to go on an unholy frenzy, increasing its attack speed and energy regeneration by $1270491s1% for $1270491d.\n\n\n\nMultiple applications may overlap.", ua = "Гниття вкидає вашого постійного вампіра в нечестиве шаленство, збільшуючи його швидкість атаки та відновлення енергії на $1270491s1% на $1270491d.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Light your soul aflame, healing yourself for ${$s2*$s3}% of your maximum health, generating ${$1242475s1*$s3} Fury and shattering $s1 Soul Fragments over $d.", ua = "Запалюєш власну душу: зцілюєшся на ${$s2*$s3}% максимального здоров'я, створюєш ${$1242475s1*$s3} люті та вибиваєш $s1 фрагментів душ протягом $d." },
    { en = "Damage taken reduced by up to $s1%, increasing as your health decreases.", ua = "Отримувану шкоду зменшено щонайбільше на $s1% — що менше в тебе здоров'я, то сильніший ефект." },
    { en = "Hammer of Wrath deals up to $s1% additional damage based on its target's health. Lower health targets receive more damage.", ua = "«Молот гніву» завдає до $s1% додаткової шкоди залежно від здоров'я цілі. Що менше в цілі здоров'я, то більша шкода." },
    { en = "Activating Avenging Wrath calls upon the Light to empower you, causing your next $?s216331[Holy Light][$s1 Holy Lights] to be instant cast and cost $414273s2% less mana.", ua = "Активація Гніву месника закликає Світло, що наснажує тебе: $?s216331[твоє наступне Священне світло твориться миттєво й коштує][твої наступні $s1 застосування Священного світла творяться миттєво й коштують] на $414273s2% менше мани." },
    { en = "Casting Emerald Blossom causes your next Echo to cast on an additional ally within $s1 yards at $s2% effectiveness. Stacks up to $1242759u charges.", ua = "Творіння Смарагдового цвіту змушує твоє наступне Відлуння подіяти ще на одного союзника в межах $s1 м з $s2% ефективності. Складається до $1242759u зарядів." },
    { en = "Army of the Dead now summons a Gargoyle into the battlefield to bombard your enemies for $61777d.\n\n\n\nThe Gargoyle gains $211947s1% increased damage for every $49206s4 Runic Power you spend and always critically strikes.", ua = "Армія мертвих тепер прикликає на поле бою Ґаргулью, що бомбардує ваших ворогів протягом $61777d.\n\n\n\nҐаргулья завдає на $211947s1% більше шкоди за кожні $49206s4 рунічної сили, які ви витрачаєте, і завжди б'є критично." },
    { en = "Army of the Dead siphons the power of the fallen, transforming Death Coil and Epidemic into Necrotic Coil and Graveyard for $1242223d.\n\n\n\n$@spellicon1242174$@spellname1242174\n\n$@spelldesc1242174\n\n\n\n$@spellicon383269$@spellname383269\n\n$@spelldesc383269", ua = "Армія мертвих висмоктує силу полеглих, перетворюючи Жмут смерті та Епідемію на Некротичний жмут і Цвинтар на $1242223d.\n\n\n\n$@spellicon1242174$@spellname1242174\n\n$@spelldesc1242174\n\n\n\n$@spellicon383269$@spellname383269\n\n$@spelldesc383269" },
    { en = "Collapsing Star always critically strikes.", ua = "Колапс зорі завжди завдає критичних ударів." },
    { en = "Every soul consumed in Void Metamorphosis grants ${$s1/100}.2% haste, up to $s1%.", ua = "Кожна душа, поглинута в Метаморфозі Порожнечі, дає ${$s1/100}.2% поспіху, аж до $s1%." },
    { en = "Your damaging critical strikes deal ${200+$s1}% damage instead of the usual 200%.", ua = "Твої критичні удари завдають ${200+$s1}% шкоди замість звичайних 200%." },
    { en = "Scourge Strike now causes your Plagues to erupt at ${$s2+$s1}% effectiveness.\n\n\n\nClawing Shadows can now stack $s3 additional times.", ua = "Удар погибелі тепер змушує ваші Пошесті вибухати з ${$s2+$s1}% ефективністю.\n\n\n\nКігтисті тіні тепер можуть накопичуватися додатково $s3 разів." },
    { en = "Army of the Dead now raises an Abomination for $288853d to attack enemies while emitting a disease cloud, dealing $1244347s1 Plague damage to nearby enemies every $s1 sec.", ua = "Армія мертвих тепер піднімає гидоту на $288853d: вона атакує ворогів і випускає хмару хвороби, що завдає $1244347s1 шкоди від чуми ворогам поблизу кожні $s1 сек." },
    { en = "Increases Tentacle Slam damage by $s1%.", ua = "Збільшує шкоду «Удару щупальця» на $s1%." },
    { en = "Casting Dream Flight or Stasis increases your healing over time by $1242747s1% and causes Living Flame and Reversion to have a $1242747s2% increased chance to grant Essence Burst. Lasts $?s359816[$s2][$s3] sec.", ua = "Творення Польоту мрій чи Стазису підвищує ваше періодичне зцілення на $1242747s1% і дає Живому полум'ю та Поверненню на $1242747s2% більший шанс надати Сплеск есенції. Триває $?s359816[$s2][$s3] сек." },
    { en = "Your chance to shatter a Soul Fragment from enemies you damage is increased by $s1%.", ua = "Шанс вибити фрагмент душі з ворогів, яким ти завдаєш шкоди, збільшений на $s1%." },
    { en = "Increases the critical strike chance of Shadowy Apparitions by $s1% and their critical strike damage by $s2%.", ua = "Збільшує ймовірність критичного удару «Тіньових видінь» на $s1%, а їхню критичну шкоду — на $s2%." },
    { en = "Increases the critical strike chance of Vampiric Touch and Shadow Word: Pain by $s1% and their critical strike damage by $s2%.", ua = "Збільшує ймовірність критичного удару «Вампіричного дотику» та «Слова Тіні: Біль» на $s1%, а їхню критичну шкоду — на $s2%." },
    { en = "Thunder Focus Tea summons a Jade Serpent Statue at your location. When you channel Soothing Mist, the statue will also begin to channel Soothing Mist on your target, healing for $198533o1 over $198533d.", ua = "«Чай громової зосередженості» прикликає статую Нефритового Змія в місці, де ти стоїш. Коли ти спрямовуєш «Заспокійливий туман», статуя теж починає спрямовувати «Заспокійливий туман» на твою ціль, зціляючи її на $198533o1 протягом $198533d." },
    { en = "Your Mastery is increased by $s1%.", ua = "Твоя майстерність збільшена на $s1%." },
    { en = "$?s399491[Sheilun's Gift][Vivify] healing increased by $s1% and Renewing Mist's healing is increased by $s2%.", ua = "Зцілення від $?s399491[Дар Шейлуна][Оживлення] збільшено на $s1%, а зцілення від Оновлювального туману збільшено на $s2%." },
    { en = "Activating Fortifying Brew transfers all currently active harmful magical effects on you back to their original caster if possible.", ua = "Активація «Зміцнювального варива» переносить усі поточні шкідливі магічні ефекти з тебе назад на того, хто їх наклав, якщо це можливо." },
    { en = "Arcane Missiles now damages ${$s2} additional targets at $s1% effectiveness.", ua = "«Арканні снаряди» тепер завдають шкоди ${$s2} додатковим цілям з ефективністю $s1%." },
    { en = "Casting Arcane Orb while you have Clearcasting causes you to fire $s1 additional Arcane $lOrb:Orbs; at $s2% effectiveness.\n\n\n\nCasting Arcane Orb now consumes Clearcasting.", ua = "Творіння Арканної сфери за наявності Ясного творіння змушує вас випустити $s1 додаткову арканну $lсферу:сфери; з $s2% ефективністю.\n\n\n\nТворіння Арканної сфери тепер споживає Ясне творіння." },
    { en = "Casting Touch of the Magi grants Clearcasting.", ua = "Прочитання «Дотику магів» дає «Чисте чарування»." },
    { en = "The damage of Arcane Blast and Arcane Pulse are increased by $s1%, but their mana costs are increased by $s2%.", ua = "Шкоду «Арканного вибуху» та «Арканного імпульсу» збільшено на $s1%, але витрати мани на них зростають на $s2%." },
    { en = "Casting Arcane Blast or Arcane Pulse grants $s1 $Lstack:stacks; of Arcane Salvo.\n\n\n\nCasting Arcane Orb grants $s2 $Lstack:stacks; of Arcane Salvo.", ua = "Творіння Арканного удару або Арканного пульсу надає $s1 $Lзаряд:заряди:зарядів; Залпу аркани.\n\n\n\nТворіння Арканної сфери надає $s2 $Lзаряд:заряди:зарядів; Залпу аркани." },
    { en = "Activating Shield Wall increases your maximum health by $12975s1% for $12975d and instantly heals you for that amount.", ua = "Активація «Стіни щитів» збільшує твоє максимальне здоров'я на $12975s1% на $12975d і миттєво зцілює тебе на цю величину." },
    { en = "The effects of your shouts last $s1% longer.", ua = "Ефекти твоїх криків тривають на $s1% довше." },
    { en = "Unleash a furious frenzy, flickering to nearby targets in front of you $s1 times and clawing all enemies around them for $1244079s1 Physical damage and an additional ${$1244079s3*$1244079d/$1244079t3} Bleed damage over $1244079d.\n\n\n\n|cFFFFFFFFAwards $s1 combo points.|r", ua = "Вивільняє несамовитий шал, миготливо перескакуючи до ближніх цілей перед вами $s1 раз(ів) і дряпаючи всіх ворогів довкола них на $1244079s1 фізичної шкоди та ще ${$1244079s3*$1244079d/$1244079t3} шкоди від кровотечі протягом $1244079d.\n\n\n\n|cFFFFFFFFНадає $s1 комбо-очок.|r" },
    { en = "Arcane Salvo damage bonus increased by $s1%.\n\n\n\n$@spellicon1242974 $@spellname1242974:\n\nIncreases the damage of your next Arcane Barrage by $1242974s1%.", ua = "Бонус до шкоди Залпу аркани збільшено на $s1%.\n\n\n\n$@spellicon1242974 $@spellname1242974:\n\nЗбільшує шкоду вашого наступного Арканного шквалу на $1242974s1%." },
    { en = "You are healed for $s1% of the damage dealt by Refining Fire.", ua = "Ти зцілюєшся на $s1% від шкоди, завданої «Очисним вогнем»." },
    { en = "Mirror Image's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження Дзеркального образу скорочується на ${-$s1/1000} сек." },
    { en = "$?s212653[Shimmer][Blink] gains an additional charge.", ua = "$?s212653[Мерехтіння][Блимання] отримує додатковий заряд." },
    { en = "Ice Barrier reduces your physical damage taken by ${-$s1}% and absorbs an additional $s2% of your maximum health.", ua = "«Крижаний бар'єр» зменшує отримувану тобою фізичну шкоду на ${-$s1}% і додатково поглинає шкоду в обсязі $s2% твого максимального здоров'я." },
    { en = "Casting Avenger's Shield causes Consecration to deal its damage and healing again immediately at $s1% effectiveness.", ua = "Творення «Щита месника» змушує «Освячення» негайно повторити свою шкоду та зцілення з ефективністю $s1%." },
    { en = "Alter Time resets the cooldown of Blink and Shimmer when you return to your original location.", ua = "«Зміна часу» скидає перезарядження «Блимання» та «Мерехтіння», коли ти повертаєшся на початкове місце." },
    { en = "Run at high speed toward a target location near your allies, taking $1244091s1% of all damage dealt to allies within $a1 yards for $1244091d or until you take at least ${($1244091s3/100)*$MHP} damage from this effect.", ua = "Біжиш на високій швидкості до цільової точки біля союзників і протягом $1244091d приймаєш на себе $1244091s1% усієї шкоди, завданої союзникам у радіусі $a1 м, або поки не отримаєш щонайменше ${($1244091s3/100)*$MHP} шкоди від цього ефекту." },
    { en = "Upon dropping below $s1% health, your past self corrects your timeline, casting Alter Time and instantly returning $1244092s1% of your maximum health.", ua = "Коли твоє здоров'я падає нижче $s1%, твоє минуле «я» виправляє твою лінію часу: творить «Зміну часу» й миттєво повертає $1244092s1% твого максимального запасу здоров'я." },
    { en = "The critical strike damage of your spells is increased by $s1%.", ua = "Шкоду від критичних ударів твоїх заклять збільшено на $s1%." },
    { en = "Ice Block and Ice Barrier now have an additional charge.", ua = "«Крижана брила» та «Крижаний бар'єр» тепер мають додатковий заряд." },
    { en = "Void Ray's cooldown during Void Metamorphosis is reduced by ${-$s1/1000}.1 sec.", ua = "Перезарядження «Променя Порожнечі» під час «Метаморфози Порожнечі» скорочене на ${-$s1/1000}.1 сек." },
    { en = "Reap and Consume damage increased by $s1%.", ua = "Шкода «Жнив» і «Поглинання» збільшена на $s1%." },
    { en = "When Void Metamorphosis expires, for each unused Soul you harvested, gain $s1 Fury and increase your damage by ${$s1/10}.2% for $1244235d.", ua = "Коли «Метаморфоза Порожнечі» закінчується, за кожну зібрану, але не використану душу ти отримуєш $s1 од. люті, а твоя шкода зростає на ${$s1/10}.2% на $1244235d." },
    { en = "Chomp your target, causing $s1 Physical damage. Chomp critical strikes deal ${$1244292s3/100+2} times normal damage.\n\n\n\nChomp can only be used when you fall below ${$1244292s1+1}% Energy or for ${$1244393s1/1000} seconds afterward.", ua = "Кусає вашу ціль, завдаючи $s1 фізичної шкоди. Критичні удари Укусу завдають у ${$1244292s3/100+2} разів більше звичайної шкоди.\n\n\n\nУкус можна застосувати лише тоді, коли ви опускаєтеся нижче ${$1244292s1+1}% Енергії, або протягом ${$1244393s1/1000} секунд після цього." },
    { en = "Increases Mastery by $s1%.", ua = "Збільшує майстерність на $s1%." },
    { en = "The duration of Feast of Souls is increased by ${$s1/1000} sec.\n\n\n\n$@spellicon1237270 $@spellname1237270\n\n$@spelldesc1237270", ua = "Тривалість Бенкету душ збільшено на ${$s1/1000} с.\n\n\n\n$@spellicon1237270 $@spellname1237270\n\n$@spelldesc1237270" },
    { en = "Increases Conflagrate damage by $s1%. \n\n\n\nConflagrate now erupts the target's $?a445465[Wither][Immolate], spreading it up to $s2 nearby enemies.", ua = "Збільшує шкоду Займання на $s1%. \n\n\n\nЗаймання тепер змушує $?a445465[Усихання][Спопеляння] цілі спалахнути, поширюючи його на до $s2 ворогів поблизу." },
    { en = "Gaining Clearcasting has a $s1% chance to cause your next Arcane Missiles to be Overpowered, causing it to deal $1277009s1% increased damage, generate maximum stacks of Arcane Salvo, and strike $1277009s2 additional $Ltarget:targets; at $1243307s1% effectiveness.", ua = "Отримання Ясного чаклування має $s1% шанс зробити ваш наступний Арканний обстріл Надпотужним, через що він завдає на $1277009s1% більше шкоди, генерує максимум зарядів Арканного залпу та уражає $1277009s2 додаткову ціль:додаткові цілі; з $1243307s1% ефективності." },
    { en = "$s2% of Lifebloom's final bloom heals up to $s3 injured allies within $1244341a1 yds.", ua = "$s2% фінального цвітіння «Цвіту життя» зцілює до $s3 поранених союзників у радіусі $1244341a1 м." },
    { en = "$?s212653[Shimmer][Blink]'s cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження $?s212653[Мерехтіння][Блимання] зменшено на ${-$s1/1000} сек." },
    { en = "Increases the duration of Havoc by ${$s1/1000} sec and increases the damage Havoc victims are dealt by an additional $s2%.", ua = "Збільшує тривалість Погрому на ${$s1/1000} сек. і збільшує шкоду, якої зазнають жертви Погрому, ще на $s2%." },
    { en = "Lifebloom bursts into a Blooming Frenzy when you consume Soul of the Forest, causing it to bloom $s1 times in rapid succession.", ua = "Коли ти поглинаєш «Душу лісу», «Цвіт життя» вибухає «Шалом цвітіння», розквітаючи $s1 разів поспіль." },
    { en = "Ferocious Bite's damage to its primary target increased by $s1% for each enemy affected by your Rip, up to $s2.", ua = "Шкода «Лютого укусу» по головній цілі збільшена на $s1% за кожного ворога під дією твого «Роздирання», аж до $s2." },
    { en = "Feral Frenzy's cooldown reduced by ${-$s1/1000} sec and its damage is increased by $s2%.", ua = "Перезарядження «Дикого шалу» скорочено на ${-$s1/1000} сек., а його шкода збільшена на $s2%." },
    { en = "When an enemy afflicted by your Rip dies, gain 10 Energy and your damage dealt is increased by 5% for 8 sec, stacking up to 5 times.", ua = "Коли ворог під дією твого «Розриву» гине, ти отримуєш 10 енергії, а завдана тобою шкода збільшується на 5% на 8 сек.; ефект складається до 5 разів." },
    { en = "The final slash of Blade Dance consumes $s1 Fury when it strikes $s2 or more enemies, launching two demonic glaives in a whirlwind of energy, causing ${14*$342857s1} Chaos damage over $342817d to all nearby enemies. Deals reduced damage beyond $342817s2 targets.", ua = "Останній помах «Танцю клинків» поглинає $s1 од. люті, якщо влучає у $s2 чи більше ворогів, запускаючи у вихорі енергії дві демонічні глефи, які протягом $342817d завдають ${14*$342857s1} шкоди хаосу всім ворогам поруч. Завдає менше шкоди, якщо цілей більше за $342817s2." },
    { en = "Damage of your bleeds increased by $s1%.", ua = "Шкода твоїх кровотеч збільшена на $s1%." },
    { en = "Increases Chaos Bolt damage by $s1% and Chaos Bolt now has a $s2% chance to make your next Incinerate instant.", ua = "Збільшує шкоду «Стріли хаосу» на $s1%, і «Стріла хаосу» тепер з імовірністю $s2% робить твоє наступне «Спопеління» миттєвим." },
    { en = "Cataclysm now leaves behind a lake of fire that deals ${$1244890s1*($1244885d/$1244885t2)} Fire damage to enemies within it over $1244885d.\n\n\n\n$?a445465[Wither][Immolate] deals $1244918s1% increased damage to enemies within the lake of fire.", ua = "Катаклізм тепер залишає по собі вогняне озеро, що завдає ${$1244890s1*($1244885d/$1244885t2)} вогняної шкоди ворогам усередині нього протягом $1244885d.\n\n\n\n$?a445465[Усихання][Спопеляння] завдає на $1244918s1% більше шкоди ворогам у вогняному озері." },
    { en = "While in combat, apply a Beacon of the Savior to the lowest health ally within $s1 yds that causes your direct healing on others to also heal that ally for $s2% of the amount healed.\n\n\n\nBeacon of the Savior transfers to the lowest health ally within $s1 yds if it heals a target past maximum health or if an ally drops below $1270083s4% health.", ua = "У бою накладає «Маяк спасителя» на союзника з найнижчим здоров'ям у межах $s1 м, завдяки чому ваше пряме зцілення інших також зцілює того союзника на $s2% обсягу зціленого.\n\n\n\n«Маяк спасителя» переходить на союзника з найнижчим здоров'ям у межах $s1 м, якщо він зцілює ціль понад максимальне здоров'я або якщо союзник падає нижче $1270083s4% здоров'я." },
    { en = "Increases how quickly Rain of Fire deals damage by $s1% and how quickly your Infernal's Immolation deals damage by $s2%.", ua = "Збільшує швидкість, з якою Вогняний дощ завдає шкоди, на $s1%, а швидкість, з якою Спалення твого інфернала завдає шкоди, — на $s2%." },
    { en = "Rain of Fire has a $s1% chance to reduce the cost of your next Rain of Fire within $1244947d by $1244947s2%.", ua = "«Вогняний дощ» має $s1% шансу зменшити вартість твого наступного «Вогняного дощу» протягом $1244947d на $1244947s2%." },
    { en = "Casting Soul Fire summons an Overfiend.\n\n\n\nOpening a Dimensional Rift has a chance to summon an Overfiend instead.\n\n\n\n$@spellicon434587 $@spellname434587\n\n$@spelldesc434587", ua = "Творення Вогню душі прикликає Верховного нечестивця.\n\n\n\nВідкриття Міжвимірного розлому має шанс натомість прикликати Верховного нечестивця.\n\n\n\n$@spellicon434587 $@spellname434587\n\n$@spelldesc434587" },
    { en = "Consecration deals $s1% increased damage when it strikes a single target.", ua = "«Освячення» завдає на $s1% більше шкоди, коли влучає лише в одну ціль." },
    { en = "Beacon of the Savior transfers an additional $s1% of the amount healed and allies with Beacon of the Savior receive $s2% more healing from you.", ua = "«Маяк спасителя» переносить додатково $s1% обсягу зцілення, а союзники з «Маяком спасителя» отримують від тебе на $s2% більше зцілення." },
    { en = "Every $t1 sec or when Beacon of the Savior transfers to a new injured target, they are granted an absorb shield that prevents the next $1245369s1 damage and reduces damage taken by $1245369s2% for $1245369d.\n\n\n\nBeacon of the Savior now additionally follows the target of your Holy Light and Flash of Light spells once every $proccooldown sec.", ua = "Кожні $t1 с або коли «Маяк рятівника» переходить на нову поранену ціль, вона отримує поглинальний щит, що запобігає наступним $1245369s1 шкоди та зменшує отримувану шкоду на $1245369s2% протягом $1245369d.\n\n\n\n«Маяк рятівника» тепер додатково слідує за ціллю ваших заклять «Священне світло» та «Спалах світла» раз на $proccooldown с." },
    { en = "Unleash your glaives and charge to your target, dealing $1245414s2 Cosmic damage.$?a1246562[\n\n\n\n|CFFffffffGenerates $1245414s3 Fury.|R][]", ua = "Вивільняє ваші глефи та кидається до цілі, завдаючи $1245414s2 космічної шкоди.$?a1246562[\n\n\n\n|CFFffffffГенерує $1245414s3 люті.|R][]" },
    { en = "Critical strikes dealt by Chaos Bolt, Conflagrate, or Incinerate have a $s1% chance to make your next cast of Shadowburn within $1245664d cost no Soul Shards and usable on any target regardless of health.", ua = "Критичні удари «Стріли хаосу», «Займання» та «Спопеління» з імовірністю $s1% роблять так, що твій наступний «Тіньовий опік» протягом $1245664d не коштує осколків душі та може бути застосований до будь-якої цілі незалежно від її здоров'я." },
    { en = "Consecration heals you for $s1% of the damage it deals.", ua = "«Освячення» зцілює тебе на $s1% завданої ним шкоди." },
    { en = "While out of combat, Divine Steed grants Shield of the Righteous for its duration and an additional ${$s1/1000}.1 sec after it fades.", ua = "Поза боєм «Божественний скакун» дарує «Щит праведника» на час своєї дії та ще на ${$s1/1000}.1 сек. після завершення ефекту." },
    { en = "After casting $?c1[Arcane Surge][Combustion], your next $?s212653[Shimmer][Blink] will cause a Blast Wave at your previous location, dealing $157981s1 Fire damage, knocking enemies back $s1 yds, and slowing them by $157981s2% for $157981d.", ua = "Після застосування $?c1[Арканного сплеску][Згоряння] ваше наступне $?s212653[Мерехтіння][Стрибок] спричинить Вибухову хвилю на вашій попередній позиції, завдаючи $157981s1 шкоди вогнем, відкидаючи ворогів на $s1 м. і вповільнюючи їх на $157981s2% протягом $157981d." },
    { en = "Charge to your target, striking them for $1246169s1 Cosmic damage, rooting them in place for $370970d and inflicting $1246168o1 Cosmic damage over $1246168d to up to $370967s2 enemies in your path.", ua = "Мчиш до цілі, завдаючи їй $1246169s1 космічної шкоди й знерухомлюючи її на $370970d, а також завдаєш $1246168o1 космічної шкоди протягом $1246168d щонайбільше $370967s2 ворогам на своєму шляху." },
    { en = "Guardian of Ancient Kings has $s1 additional $Lcharge:charges;.", ua = "Кількість зарядів «Захисника стародавніх королів» збільшено на $s1." },
    { en = "Judgment chains to $s1 additional $Ltarget;targets at ${$275779f1*100}% effectiveness.", ua = "«Вирок» перестрибує ланцюгом на $s1 додаткових цілей з ${$275779f1*100}% ефективності." },
    { en = "Increases the healing done by Holy Word: Serenity by $s2% and causes it to heal $1250581s2 nearby injured allies within $1250581A1 yards for $s3% of its healing done.\n\n\n\nTalents that affect Holy Word: Sanctify instead affect Holy Word: Serenity.", ua = "Збільшує зцілення від «Святого слова: Безтурботність» на $s2% і змушує його зцілювати $1250581s2 поранених союзників поблизу в межах $1250581A1 м на $s3% завданого ним зцілення.\n\n\n\nТаланти, що впливають на «Святе слово: Освячення», натомість впливають на «Святе слово: Безтурботність»." },
    { en = "Increases the damage of Holy Nova by $s1%, its healing by $s2%, and its cooldown by ${$s3/1000} sec.", ua = "Збільшує шкоду «Священної нови» на $s1%, її зцілення — на $s2%, а перезарядження — на ${$s3/1000} сек." },
    { en = "The cooldown of Soul Immolation is reduced by ${-$s1/1000} sec and it gains $s2 additional $Lcharge:charges;.", ua = "Перезарядження Спалення душі зменшено на ${-$s1/1000} с, і воно отримує $s2 додаткових $Lзаряд:заряди;." },
    { en = "Soul Immolation heals for an additional ${$s1*$1241937s2}% of your health over its duration and its cooldown is reset upon killing an enemy that yields experience or honor.", ua = "«Спалення душі» додатково зцілює тебе на ${$s1*$1241937s2}% здоров'я за час дії, а його перезарядження скидається, коли ти вбиваєш ворога, що дає досвід чи честь." },
    { en = "Reap now generates $s1 Fury.", ua = "«Жнива» тепер генерують $s1 од. люті." },
    { en = "Voidblade damage increased by $s1% and Voidblade now generates $s2 Fury.", ua = "Шкода «Клинка Порожнечі» збільшена на $s1%, і тепер «Клинок Порожнечі» породжує $s2 од. люті." },
    { en = "$?a137032[The first bolt of each Penance cast damages or heals for $s1% more.][$@spelldesc1246798]", ua = "$?a137032[Перша стріла кожного творіння Покути завдає шкоди або зцілює на $s1% більше.][$@spelldesc1246798]" },
    { en = "$s1% of overhealing done is redistributed to up to $s2 nearby injured allies.", ua = "$s1% надлишкового зцілення перерозподіляється між щонайбільше $s2 пораненими союзниками поблизу." },
    { en = "Shatter damage has a $s1% increased chance to critically strike.", ua = "Шкода Дроблення має на $s1% більший шанс критичного удару." },
    { en = "While in combat, Frost crystallizes around you, generating an Icicle every ${$t1}.1 sec. Upon generating $s2 Icicles, $?s431044[Frostfire Bolt][Frostbolt] upgrades to Glacial Spike for its next cast.\n\n\n\n$@spellicon199786 $@spellname199786\n\n$@spelldesc199786", ua = "У бою мороз кристалізується навколо вас, утворюючи Бурульку щоразу через ${$t1}.1 сек. Коли утвориться $s2 Бурульок, $?s431044[Стріла морозного вогню][Морозна стріла] під час наступного творення стає Льодовиковим шпичаком.\n\n\n\n$@spellicon199786 $@spellname199786\n\n$@spelldesc199786" },
    { en = "Shatter's critical strike damage is increased by $s1% of your critical strike chance.", ua = "Шкода критичних ударів Дроблення збільшена на $s1% від твого шансу критичного удару." },
    { en = "Ray of Frost damage increased by $s1%.", ua = "Шкода Променя морозу збільшена на $s1%." },
    { en = "$?a157997[Ice Nova][Cone of Cold] now applies $s1 $Lstack:stacks; of Freezing to up to $s2 enemies.", ua = "$?a157997[Крижана нова][Конус холоду] тепер накладає $s1 $Lстак:стаків; Заморожування на щонайбільше $s2 ворогів." },
    { en = "Reduces the mana cost of Prayer of Healing by $s1%.", ua = "Зменшує вартість мани «Молитви зцілення» на $s1%." },
    { en = "Reduces the mana cost of Flash Heal by $s1%.", ua = "Зменшує вартість мани «Швидкого зцілення» на $s1%." },
    { en = "$?c2[Surge of Light can now be consumed by Prayer of Healing in addition to Flash Heal.\n\n\n\n$@spellicon109186 $@spellname109186\n\n$@spelldesc109186][Increases Shadowy Apparition damage by $s1%.]", ua = "$?c2[Сплеск Світла тепер можна спожити не лише Швидким зціленням, а й Молитвою зцілення.\n\n\n\n$@spellicon109186 $@spellname109186\n\n$@spelldesc109186][Збільшує шкоду Тіньової з'яви на $s1%.]" },
    { en = "Slash all enemies within $A1 yds dealing $s1 damage. Deals reduced damage beyond $s4 targets.\n\n\n\nCopy the longest Garrote and Rupture on the enemies you hit onto up to $s2 other enemies. \n\n\n\n|cFFFFFFFFAwards $s3 combo $lpoint:points;.|r", ua = "Розтинає всіх ворогів у межах $A1 ярдів, завдаючи $s1 шкоди. Завдає зменшеної шкоди після $s4 цілей.\n\n\n\nКопіює найдовші ефекти «Удавки» та «Розриву» з уражених ворогів на ще до $s2 інших ворогів. \n\n\n\n|cFFFFFFFFНадає $s3 $lочко комбо:очок комбо;.|r" },
    { en = "Summon a Lesser Ghoul to strike the enemy for $1277016s1 Shadow damage and have them explode for $390220s1 Shadow damage to nearby enemies.", ua = "Прикликає нижчого гуля, який б'є ворога, завдаючи $1277016s1 шкоди від тіні, а тоді вибухає, завдаючи $390220s1 шкоди від тіні ворогам поблизу." },
    { en = "Void Metamorphosis requires $s1 less souls.\n\n\n\nYour Fury drains ${-$s2}% faster while in Void Metamorphosis.", ua = "Метаморфоза Порожнечі потребує на $s1 менше душ.\n\n\n\nВаша Лють витрачається на ${-$s2}% швидше під час Метаморфози Порожнечі." },
    { en = "Void Ray and Hungering Slash damage increased by $s1%.", ua = "Шкода «Променя Порожнечі» та «Голодного розтину» збільшена на $s1%." },
    { en = "Ray of Frost generates $s1 $Lstack:stacks; of Fingers of Frost over its duration.", ua = "«Промінь холоду» генерує $s1 $Lнакопичення:накопичення; «Крижаних перстів» упродовж своєї дії." },
    { en = "Consuming Brain Freeze has a $s1% chance to cause your next Ice Lance to Shatter $1246769s4 additional stacks of Freezing.", ua = "Використання «Заморозки мозку» має $s1% шансу, що твій наступний «Крижаний спис» розколе $1246769s4 додаткових зарядів «Замороження»." },
    { en = "The time it takes to generate an Icicle is reduced by ${-$s1/1000}.1 sec.", ua = "Час, потрібний для створення Бурульки, зменшено на ${-$s1/1000}.1 сек." },
    { en = "$?s431044[Frostfire Bolt][Frostbolt] and Glacial Spike damage increased by $s1%.", ua = "Шкода від $?s431044[Льодовогняна стріла][Крижана стріла] і Льодовикового шпиля збільшена на $s1%." },
    { en = "Flurry and Blizzard damage increased by $s1%.", ua = "Шкода «Шквалу» та «Хуртовини» збільшена на $s1%." },
    { en = "Flurry fires $s1 additional $Lmissile:missiles;.", ua = "Шквал випускає $s1 додатковий $Lснаряд:снаряди;." },
    { en = "Casting Ray of Frost replaces your Ray of Frost with Comet Storm, calling down a series of 7 icy comets on and around the target, that deals up to ${7*$153596s1} Frost damage to all enemies within $153596A1 yds of its impacts.\n\n\n\n|CFFffffffEach Comet Shatters $1246769s5 $Lstack:stacks; of Freezing.|R", ua = "Творіння Променя морозу замінює ваш Промінь морозу на Бурю комет, прикликаючи серію із 7 крижаних комет на ціль і навколо неї, що завдають до ${7*$153596s1} морозної шкоди всім ворогам у радіусі $153596A1 ярдів від місць влучання.\n\n\n\n|CFFffffffКожна комета розколює $1246769s5 $Lзаряд:заряди:зарядів; Заморожування.|R" },
    { en = "When Ice Lance Shatters a stack of Freezing, the cooldown of Ray of Frost is reduced by ${$s2/1000}.2 sec.", ua = "Коли «Крижаний спис» розколює заряд «Заморожування», перезарядження «Променя морозу» скорочується на ${$s2/1000}.2 сек." },
    { en = "Ice Lance Shatters $s1 additional $Lstack:stacks; of Freezing.", ua = "Крижаний спис розбиває $s1 додатковий $Lстак:стаки; Заморожування." },
    { en = "Increases your Energy regeneration by $s1%.", ua = "Збільшує відновлення енергії на $s1%." },
    { en = "$?a137020[Flurry]?a137019[Fire Blast][Flurry and Fire Blast] now $?a137020[deals]?a137019[deals][deal] Frostfire damage and $?a137020[its]?a137019[its][their] damage is increased by $?a137020[$s3%]?a137019[$s2%][$s2%].", ua = "$?a137020[Хуртовина]?a137019[Вогняний вибух][Хуртовина й Вогняний вибух] тепер $?a137020[завдає]?a137019[завдає][завдають] морозовогняної шкоди, і $?a137020[її]?a137019[її][їхня] шкода збільшується на $?a137020[$s3%]?a137019[$s2%][$s2%]." },
    { en = "Your $?a137020[Fire]?a137019[Frost][Frost and Fire] spells deal $?a137020[$s1]?a137019[$s2][$s1]% increased critical strike damage.\n\n\n\n$?a137020[Shatter damage increased by $s3%.\n\n\n\nBlizzard damage increased by $s6%.]?a137019[Pyroblast damage increased by $s4%.\n\n\n\nFlamestrike damage increased by $s5%.][Ice Lance and Pyroblast  have their damage increased by $s3%.]", ua = "Ваші $?a137020[вогняні]?a137019[морозні][морозні та вогняні] закляття завдають на $?a137020[$s1]?a137019[$s2][$s1]% більше критичної шкоди.\n\n\n\n$?a137020[Шкода Розколу збільшена на $s3%.\n\n\n\nШкода Хуртовини збільшена на $s6%.]?a137019[Шкода Вогняного вибуху збільшена на $s4%.\n\n\n\nШкода Вогняного удару збільшена на $s5%.][Шкода Крижаного списа та Вогняного вибуху збільшена на $s3%.]" },
    { en = "$?a137020[Comet Storm damage increased by $s2%.\n\n\n\nMeteor damage increased by $s1%.]?a137019[Meteor damage increased by $s3%.\n\n\n\nComet Storm damage increased by $s4%.][The damage of Meteor and Comet Storm is increased.]", ua = "$?a137020[Шкода від Бурі комет збільшена на $s2%.\n\n\n\nШкода від Метеора збільшена на $s1%.]?a137019[Шкода від Метеора збільшена на $s3%.\n\n\n\nШкода від Бурі комет збільшена на $s4%.][Шкода від Метеора та Бурі комет збільшена.]" },
    { en = "Increases Cosmic Ripple healing by $s1%.", ua = "Збільшує зцілення «Космічних брижів» на $s1%." },
    { en = "$?a137032[Penance][Prayer of Mending] gains an additional charge.", ua = "$?a137032[Покута][Молитва зцілення] отримує додатковий заряд." },
    { en = "Rising Sun Kick's critical strike chance is increased by $1248705s1% for each nearby enemy, up to $s3 enemies.\n\n\n\n$s1% of Rising Sun Kick's damage splashes onto nearby enemies. Damage is reduced beyond $s2 targets.", ua = "Шанс критичного удару Удару вранішнього сонця збільшується на $1248705s1% за кожного ворога поблизу, максимум до $s3 ворогів.\n\n\n\n$s1% шкоди Удару вранішнього сонця розбризкується на ворогів поблизу. Шкода зменшується після $s2 цілей." },
    { en = "The damage of Fists of Fury is increased by $s1%.", ua = "Шкода «Кулаків люті» збільшена на $s1%." },
    { en = "You gain $s2% more Haste from all sources of Haste.", ua = "Ти отримуєш на $s2% більше поспіху з усіх джерел поспіху." },
    { en = "When you consume an application of Deathstalker's Mark, the damage of your next $?c1[Ambush or Mutilate]?s200758[Gloomblade][Backstab] is increased by $1248775s1%$?c1[][ or Shadowstrike increased by $1248775s2%].", ua = "Коли ви споживаєте накладання Мітки смертельного переслідувача, шкода вашого наступного $?c1[Засідки чи Калічення]?s200758[Похмурого клинка][Удару в спину] збільшується на $1248775s1%$?c1[][, або Тіньовий удар збільшується на $1248775s2%]." },
    { en = "$?c1[Rupture][Deathstalker's Mark] damage increased by $?c1[$s1][$s2]%.", ua = "Шкода від $?c1[«Розриву»][«Мітки смертеслідця»] підвищена на $?c1[$s1][$s2]%." },
    { en = "$?c1[Fan of Knives][Shuriken Storm] damage increased by $s1%.", ua = "Шкода від $?c1[«Віяла ножів»][«Бурі сюрікенів»] збільшена на $s1%." },
    { en = "When $?s431044[Frostfire Bolt][Frostbolt] critically strikes, it applies $s1 additional $Lstack:stacks; of Freezing.\n\n\n\nEach stack of Freezing that you Shatter deals $1246949s2 damage to nearby enemies. Damage reduced beyond $s2 targets.", ua = "Коли $?s431044[Стріла морозного вогню][Морозна стріла] завдає критичного удару, накладається $s1 додатковий $Lзаряд:заряди; Заморожування.\n\n\n\nКожен заряд Заморожування, який ви розколюєте, завдає $1246949s2 шкоди ворогам поблизу. Шкода зменшується після $s2 цілей." },
    { en = "Ice shards pelt the target area, dealing ${$190357m1*8} Frost damage over $d and reducing movement speed by $12486s1% for $12486d.\n\n\n\n|cFFFFFFFFThis spell is cast at your target.|r", ua = "Уламки криги осипають вибрану ділянку, завдаючи ${$190357m1*8} шкоди від морозу протягом $d і зменшуючи швидкість пересування на $12486s1% на $12486d.\n\n\n\n|cFFFFFFFFЦе закляття твориться на вашій цілі.|r" },
    { en = "Slicing Winds now generates $1248835s1 Chi when cast.", ua = "Розтинальні вітри тепер генерують $1248835s1 чі при прочитанні." },
    { en = "Slicing Winds now costs $s1 Chi to cast, but its damage is increased by $s2%.", ua = "Розтинальні вітри тепер коштують $s1 чі, але їхня шкода збільшена на $s2%." },
    { en = "Every $s1 coin flips, keep a lucky coin that bends you towards your fate for $1248971d. Your Agility is increased by $1248971s1%, the damage and bonuses of Fatebound Coins are increased by $1248971s3%, and coin flips are $1248971s5% more likely to match the same face as the last flip.\n\n\n\nCoin flips do not count toward finding a lucky coin while you have a lucky coin.", ua = "Кожні $s1 підкидань монети ви зберігаєте щасливу монету, що схиляє вас до вашої долі протягом $1248971d. Ваша Спритність збільшується на $1248971s1%, шкода й бонуси Доленосних монет збільшуються на $1248971s3%, а підкидання монети на $1248971s5% частіше дають той самий бік, що й попереднє підкидання.\n\n\n\nПідкидання монети не зараховуються до пошуку щасливої монети, поки у вас є щаслива монета." },
    { en = "After Invoking Xuen, the White Tiger you may cast Celestial Conduit within $1248992d.\n\n\n\n$@spellicon443028 $@spellname443028:\n\n$@spelldesc443028", ua = "Після Заклику Сюеня, Білого Тигра, ви можете сотворити Небесний провідник протягом $1248992d.\n\n\n\n$@spellicon443028 $@spellname443028:\n\n$@spelldesc443028" },
    { en = "$?c2[Dispatch][Envenom] has a $?c2[$s2][$s3]% chance to flip $s1 Fatebound Coins.", ua = "$?c2[Розправа][Отруєння] має $?c2[$s2][$s3]% шанс підкинути $s1 Монет, скутих долею." },
    { en = "$?c1[Envenom deals][Dispatch and Between the Eyes deal] $s1% more damage when $?c1[it consumes][they consume] $s2 or more combo points.", ua = "$?c1[«Отруєння» завдає][«Розправа» та «Між очі» завдають] на $s1% більше шкоди, коли $?c1[воно витрачає][вони витрачають] $s2 або більше комбо-очок." },
    { en = "Flipping a Fatebound Coin restores $1249202s1 health.", ua = "Підкидання доленосної монети відновлює $1249202s1 здоров'я." },
    { en = "Gain $?c1[$s1][$s2] Energy every time you flip a Fatebound Coin. Gain $?c1[$s3][$s4] Energy for Coins that land on their edge.", ua = "Отримуйте $?c1[$s1][$s2] енергії щоразу, коли підкидаєте Монету долі. Отримуйте $?c1[$s3][$s4] енергії за Монети, що приземляються на ребро." },
    { en = "$?c1[Caustic Spatter][Blade Flurry] causes an additional $?c1[$s1% of Nature][$s2% of attack] damage dealt to be dealt to affected enemies.", ua = "$?c1[«Їдкі бризки»][«Шквал клинків»] змушує завдати вражденим ворогам додатково $?c1[$s1% завданої шкоди від Природи][$s2% завданої шкоди від атаки]." },
    { en = "Increases the damage of your spells by $s1%.", ua = "Збільшує шкоду твоїх заклять на $s1%." },
    { en = "Surge of Light occurs up to $s1% more often based on your missing mana.", ua = "«Сплеск світла» спрацьовує до $s1% частіше залежно від нестачі твоєї мани." },
    { en = "Chi costs are reduced by $s7 and Blackout Kick reduces the cooldown of affected abilities by an additional ${$s3/1000} sec for $d.\n\n\n\nActivating Zenith resets the remaining cooldown on Rising Sun Kick.", ua = "Витрати чі зменшуються на $s7, а Затьмарливий удар скорочує перезарядження вражених здібностей ще на ${$s3/1000} сек. протягом $d.\n\n\n\nАктивація Зеніту скидає залишкове перезарядження Удару вранішнього сонця." },
    { en = "Call upon Sindragosa's aid in battle for $d, continuously dealing ${$155166s2*$<CAP>/$AP} Frost damage every $t1 sec to enemies in a cone in front of you. Consuming Killing Machine or Rime increases the duration by ${$s3/1000}.1 sec. Deals reduced damage to secondary targets.\n\n\n\n|cFFFFFFFFGrants a charge of Empower Rune Weapon at the start and 2 Runes at the end.|r", ua = "Прикликає на допомогу в бою Синдрагосу на $d, безперервно завдаючи ${$155166s2*$<CAP>/$AP} шкоди морозом кожні $t1 сек ворогам у конусі перед вами. Споживання Машини вбивства або Паморозі збільшує тривалість на ${$s3/1000}.1 сек. Завдає зменшеної шкоди другорядним цілям.\n\n\n\n|cFFFFFFFFНадає заряд Підсилення рунічної зброї на початку та 2 руни наприкінці.|r" },
    { en = "Garrote lasts ${$s1/1000} sec longer.", ua = "«Гарота» триває на ${$s1/1000} сек. довше." },
    { en = "All damage you deal is increased by $1249810s1% while Deathmark is active.", ua = "Уся завдана тобою шкода збільшена на $1249810s1%, поки діє Мітка смерті." },
    { en = "During Zenith, Blackout Kick generates $1249833s1 Chi.", ua = "Під час «Зеніту» «Удар затьмарення» генерує $1249833s1 од. ці." },
    { en = "Applying Envenom while Envenom is already active causes it to increase all damage you deal by $s1% in addition to increasing your poison application chance.", ua = "Якщо накласти «Отруєння», поки воно ще активне, воно збільшує всю завдану тобою шкоду на $s1% — на додачу до підвищення шансу нанесення отрут." },
    { en = "Fists of Fury's Chi cost is reduced by $s1, but its damage is reduced by $s2%.", ua = "Вартість «Кулаків люті» в ці зменшено на $s1, але їхня шкода зменшена на $s2%." },
    { en = "Casting Strike of the Windlord or Whirling Dragon Punch grants Blackout Kick!.", ua = "Використання «Удару повелителя вітрів» або «Вихрового удару дракона» дає «Удар затьмарення!»." },
    { en = "All Cosmic damage dealt increased by $s4%.\n\n\n\nCollapsing Star's critical strike damage is increased by $s3% of your critical strike chance.", ua = "Уся завдана космічна шкода збільшена на $s4%.\n\n\n\nКритична шкода Зорі, що згасає, збільшена на $s3% від вашого шансу критичного удару." },
    { en = "Entering Void Metamorphosis causes your soul to erupt, generating $s1 Soul Fragments and granting immediate access to Collapsing Star.", ua = "При вході в Метаморфозу Порожнечі твоя душа вибухає, породжуючи $s1 фрагментів душі та одразу відкриваючи доступ до Колапсу зорі." },
    { en = "When you apply a Weapon Poison with a single-target attack, you have a $s1% chance to strike a nearby enemy for $1250216s1 Physical damage and apply the same Weapon Poison to them.", ua = "Коли ти наносиш отруту для зброї атакою по одній цілі, маєш $s1% шансу вдарити ворога поблизу, завдавши $1250216s1 фізичної шкоди й наклавши на нього ту саму отруту для зброї." },
    { en = "Holy damage increased by $s1%.", ua = "Святу шкоду збільшено на $s1%." },
    { en = "Finishing moves have a $s1% chance per combo point spent to increase your chance to critically strike by $1250272s1% for $1250272d.", ua = "Завершальні прийоми мають $s1% шансу за кожне витрачене очко комбо збільшити твій шанс критичного удару на $1250272s1% на $1250272d." },
    { en = "Calls down a demonic meteor full of Wild Imps which burst forth to attack the target.\n\n\n\nDeals up to ${$m1*$86040m1} Shadowflame damage on impact to all enemies within $86040A1 yds of the target$?s196283[, applies Doom to each target,][] and summons ${$m1*$104317m2} Wild Imps.", ua = "Прикликає демонічний метеор, повний Диких бісів, які вириваються назовні, щоб атакувати ціль.\n\n\n\nЗавдає при ударі до ${$m1*$86040m1} шкоди тіньовим полум'ям усім ворогам у радіусі $86040A1 ярдів від цілі$?s196283[, накладає Прокляття долі на кожну ціль][] та прикликає ${$m1*$104317m2} Диких бісів." },
    { en = "Shadow damage and healing done increased by $s1%.", ua = "Завдавана шкода від тіні та зцілення збільшені на $s1%." },
    { en = "Hypothermia's duration is reduced by ${-$s1/1000} sec.", ua = "Тривалість «Гіпотермії» скорочена на ${-$s1/1000} сек." },
    { en = "Applying Envenom while Envenom is already active restores $1250319s1 combo point.", ua = "Якщо накласти «Отруєння», поки воно ще активне, відновлюється $1250319s1 очко комбо." },
    { en = "When Kingsbane ends, gain $1250331s1% haste for every $s1 stacks of increased Kingsbane damage that you had, decreasing by $1250331s1% every $1250331t2 sec.", ua = "Коли Згуба королів закінчується, ти отримуєш $1250331s1% поспіху за кожні $s1 зарядів збільшеної шкоди Згуби королів, що в тебе були. Ефект слабшає на $1250331s1% кожні $1250331t2 сек." },
    { en = "Rupture damage increased by $s1%.", ua = "Шкода «Розриву» збільшена на $s1%." },
    { en = "Increases Critical Strike chance by $s1%.", ua = "Збільшує шанс критичного удару на $s1%." },
    { en = "Elemental damage increased by $s1%. \n\n\n\nEach stack of Maelstrom Weapon consumed reduces the cooldown of Stormstrike by ${$s3/1000}.1 sec and Lava Lash by ${$s4/1000}.1 sec.", ua = "Стихійна шкода збільшена на $s1%. \n\n\n\nКожен витрачений заряд «Зброї виру» скорочує перезарядження «Штормового удару» на ${$s3/1000}.1 сек. і «Лавового батога» на ${$s4/1000}.1 сек." },
    { en = "Increases your Mastery by $s1%.", ua = "Збільшує твою майстерність на $s1%." },
    { en = "Fade creates an illusion of you for $1250385d, tricking enemies to attack it instead.", ua = "«Зникнення» створює твою ілюзію на $1250385d, обманом змушуючи ворогів атакувати її замість тебе." },
    { en = "Increases Shadow Word: Madness damage by $s1%.", ua = "Збільшує шкоду «Слова тіні: Безумство» на $s1%." },
    { en = "Increases the critical strike chance of your Holy Word: Serenity$?a1246517[] [ and Holy Word: Sanctify] by $s1%.", ua = "Підвищує шанс критичного удару вашого Святого слова: Безмятежність$?a1246517[] [ та Святого слова: Освячення] на $s1%." },
    { en = "Your healing spells critically strike for ${$s1+$s2}% of healing done instead of the usual $s2%.", ua = "Критичні удари твоїх заклять зцілення зцілюють на ${$s1+$s2}% від обсягу зцілення замість звичайних $s2%." },
    { en = "After consuming Blackout Kick!, Rising Sun Kick has a $s1% chance to become Rushing Wind Kick.\n\n\n\n$@spellicon467307$@spellname467307:\n\n$@spelldesc467307", ua = "Після використання Удару затьмарення! Удар висхідного сонця має $s1% шансу стати Копняком навального вітру.\n\n\n\n$@spellicon467307$@spellname467307:\n\n$@spelldesc467307" },
    { en = "You and your pet leap to your target and strike as one, dealing ${$1253862s1+$1253859s1} Physical damage$?a1256938[ to your target and up to $1256938s2 nearby enemies][]. Your pet frees itself from roots when it leaps.\n\n\n\nFor the next $d, the damage dealt by you and your pet is increased by $s1%$?a1256938[ and your attack speed is increased by $s4%][].\n\n\n\n|cFFFFFFFFGenerates $1258571s1 Focus$?a1272139[ and $1272139s1 $Lstack:stacks; of Tip of the Spear][].|r", ua = "Ви з вашим улюбленцем стрибаєте до цілі та б'єте як одне ціле, завдаючи ${$1253862s1+$1253859s1} од. фізичної шкоди$?a1256938[ вашій цілі та щонайбільше $1256938s2 ворогам поблизу][]. Стрибаючи, ваш улюбленець звільняється від коренів.\n\n\n\nПротягом наступних $d шкода, яку завдаєте ви та ваш улюбленець, збільшена на $s1%$?a1256938[, а ваша швидкість атаки збільшена на $s4%][].\n\n\n\n|cFFFFFFFFГенерує $1258571s1 од. зосередження$?a1272139[ та $1272139s1 $Lзаряд:заряди:зарядів; Вістря списа][].|r" },
    { en = "Increases Prayer of Mending healing by $s1%.", ua = "Збільшує зцілення «Молитви відновлення» на $s1%." },
    { en = "Call shadowy tendrils to constrict enemies when Psychic Scream ends, rooting them in place for $114404d.", ua = "Коли завершується «Психічний крик», прикликає тіньові мацаки, що обплутують ворогів, знерухомлюючи їх на $114404d." },
    { en = "Hand of Gul'dan now empowers $s1 of the Wild Imps it summons, increasing its damage dealt by $1250772s2%.", ua = "«Рука Ґул'дана» тепер посилює $s1 з прикликаних нею диких імпів, збільшуючи завдавану ним шкоду на $1250772s2%." },
    { en = "Increases the duration of Mind Control and Dominate Mind against enemy creatures by ${$s1/1000} sec.", ua = "Подовжує дію «Контролю розуму» та «Панування над розумом» на ворожих істотах на ${$s1/1000} сек." },
    { en = "Increases your Stamina by $s1%.", ua = "Збільшує твою витривалість на $s1%." },
    { en = "Increases your haste by $s1%.", ua = "Збільшує твій поспіх на $s1%." },
    { en = "Your demons deal ${$1281559s1}.1% increased damage for each demon you control.", ua = "Твої демони завдають на ${$1281559s1}.1% більше шкоди за кожного демона під твоїм контролем." },
    { en = "Heal each time you spend Rage, up to ${$s1/100}.1% of your maximum health for $s2 Rage spent.", ua = "Зцілює тебе щоразу, коли витрачаєш лють: до ${$s1/100}.1% максимального здоров'я за кожні $s2 витраченої люті." },
    { en = "Motes of Possibility may now grant Prescience to allies and have a $s1% increased chance to activate.", ua = "«Частки можливостей» тепер можуть дарувати союзникам «Передбачення», а їхній шанс спрацювати збільшено на $s1%." },
    { en = "Your Demonic Tyrant is equipped with armor forged within Antorus, increasing their armor by $1251000s1%. While summoned, your Demonic Tyrant now assaults enemies with powerful melee attacks.\n\n\n\n$@spellicon1264093 $@spellname1264093\n\n$@spelldesc1264093", ua = "Ваш демонічний тиран споряджений бронею, викуваною в Анторусі, що підвищує його броню на $1251000s1%. Поки викликаний, ваш демонічний тиран тепер атакує ворогів потужними ударами в ближньому бою.\n\n\n\n$@spellicon1264093 $@spellname1264093\n\n$@spelldesc1264093" },
    { en = "Barkskin increases your maximum health by $s2%, but its duration is reduced by $s1%.", ua = "«Корошкура» збільшує твоє максимальне здоров'я на $s2%, але її тривалість зменшена на $s1%." },
    { en = "The critical strike damage of your Nature abilities are increased by $s2% of your critical strike chance.", ua = "Шкода критичних ударів твоїх здібностей природи збільшується на $s2% від твого шансу критичного удару." },
    { en = "Increases the damage of $?a137033[Mind Flay][Smite] by $s1%.", ua = "Підвищує шкоду $?a137033[Шмагання розуму][Удару] на $s1%." },
    { en = "Increases the damage of $?a137031&?s14914[Holy Fire]?a137031&!s14914[Holy Fire and Shadow Word: Pain][Shadow Word: Pain] by $s1%.", ua = "Підвищує шкоду $?a137031&?s14914[Святого вогню]?a137031&!s14914[Святого вогню та Слова темряви: Біль][Слова темряви: Біль] на $s1%." },
    { en = "Critical strikes of your Nature abilities reduce the target's movement speed by $1251059s1% for $1251059d.", ua = "Критичні удари твоїх здібностей природи знижують швидкість руху цілі на $1251059s1% на $1251059d." },
    { en = "Increases the damage and healing of your Holy and Shadow spells by $s1%.", ua = "Збільшує шкоду та зцілення твоїх священних і тіньових заклять на $s1%." },
    { en = "When you shapeshift out of Bear Form, its benefits to health and armor slowly decay over $1251407d.", ua = "Коли ти виходиш із подоби ведмедя, її бонуси до здоров'я та броні поступово згасають протягом $1251407d." },
    { en = "Toss a fiery concoction that explodes violently upon reaching its destination, dealing $1251595s1 Fire damage to enemies in its area. Damage reduced beyond $s3 targets.\n\n\n\nAfter landing, your Flamefang Pitch ignites nearby terrain, dealing ${$1251614s1*$1251610d} Fire damage to enemies in its area over $1251610d.", ua = "Жбурляє вогняне вариво, що нищівно вибухає, досягнувши призначення, завдаючи $1251595s1 вогняної шкоди ворогам у своїй зоні. Шкода зменшується понад $s3 цілей.\n\n\n\nПісля приземлення ваша Смола вогнеікла підпалює місцевість поблизу, завдаючи ${$1251614s1*$1251610d} вогняної шкоди ворогам у своїй зоні протягом $1251610d." },
    { en = "Consuming Tip of the Spear provokes your pet to attack your target, dealing $1251779s1 Physical damage.\n\n\n\nAll damage dealt by your pet is increased by $s2%.", ua = "Витрата Вістря списа провокує вашого улюбленця атакувати вашу ціль, завдаючи $1251779s1 фізичної шкоди.\n\n\n\nУся шкода, яку завдає ваш улюбленець, збільшена на $s2%." },
    { en = "Strike as One damages $s1 additional enemies and its damage is increased by $s2% for each enemy it strikes beyond the first.", ua = "«Удар в унісон» завдає шкоди $s1 додатковим ворогам, а його шкода збільшується на $s2% за кожного враженого ворога після першого." },
    { en = "Call Dreadstalkers also summons a Vilefiend that assists you in combat for $1251781d.", ua = "«Поклик жахоловів» також викликає мерзотного біса, що допомагає тобі в бою протягом $1251781d." },
    { en = "Takedown cooldown reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Повалення» зменшено на ${-$s1/1000} сек." },
    { en = "Ironfur increases your Mastery by $s1%.", ua = "Залізне хутро збільшує вашу майстерність на $s1%." },
    { en = "Shadow Word: Pain damage has a chance to upgrade your next $@spellname2061 to $@spellname186263. Stacks up to $1252217u charges.\n\n\n\n$@spellicon186263 $@spellname186263:\n\n$@spelldesc186263", ua = "Шкода від Тіньового слова: Біль має шанс покращити ваше наступне $@spellname2061 до $@spellname186263. Накопичується до $1252217u зарядів.\n\n\n\n$@spellicon186263 $@spellname186263:\n\n$@spelldesc186263" },
    { en = "Crash Lightning electrocutes the area struck, dealing $s1% of its damage $s2 additional times over $1252433d, and its weapon enhancement effect now increases auto-attack speed by $s3%.", ua = "«Грозовий удар» б'є струмом уражену ділянку, завдаючи $s1% своєї шкоди ще $s2 разів протягом $1252433d, а його ефект посилення зброї тепер збільшує швидкість автоатак на $s3%." },
    { en = "Raptor Strike increases the damage of Raptor Strike by $259388s1% for $259388d. Multiple applications may overlap.", ua = "Удар раптора збільшує шкоду Удару раптора на $259388s1% на $259388d. Кілька застосувань можуть накладатися." },
    { en = "Gaining a stack of Mongoose Fury has a $s1% chance to increase the damage of your next Raptor Strike by $1252741s1%.", ua = "Отримання заряду «Люті мангуста» з імовірністю $s1% збільшує шкоду твого наступного «Удару раптора» на $1252741s1%." },
    { en = "Reduces the mana cost of Chain Heal by $s1%.", ua = "Зменшує вартість мани «Ланцюгового зцілення» на $s1%." },
    { en = "Channel the power of the enraged moon to deal $o1 Arcane damage to your target over $d. Casting Mangle extends its duration by ${$s2/1000}.1 sec and generates ${$1253582s1/10} Rage.", ua = "Спрямовуй силу розгніваного місяця, завдаючи цілі $o1 арканної шкоди протягом $d. Творення «Калічення» подовжує тривалість на ${$s2/1000}.1 сек. і породжує ${$1253582s1/10} люті." },
    { en = "Increases the healing done by $?a455630[Surging Totem by $s1%.][Healing Rain by $s1% and reduces its cast time by ${$s2/-1000}.1 sec.]", ua = "Підвищує зцілення від $?a455630[Бурхливого тотема на $s1%.][Цілющого дощу на $s1% і зменшує час його прочитання на ${$s2/-1000}.1 с.]" },
    { en = "$?a455630[Surging Totem][Healing Rain] grants an additional use of Downpour.", ua = "$?a455630[Вируючий тотем][Зцілющий дощ] надає додаткове використання Зливи." },
    { en = "Your Boomstick's damage is increased by $s1% when striking a single target.\n\n\n\nEach additional target reduces this bonus by $s2%.", ua = "Шкода вашого Бабахала збільшена на $s1% під час ураження однієї цілі.\n\n\n\nКожна додаткова ціль зменшує цей бонус на $s2%." },
    { en = "Throwing your Flamefang Pitch imbues your weapon with flame, causing you and your pet's auto-attacks to deal an additional $1252966s1 Fire damage for $1252947d.", ua = "Кидок «Смоли вогнеікла» насичує твою зброю полум'ям: твої автоатаки й автоатаки твого улюбленця завдають додатково $1252966s1 шкоди від вогню протягом $1252947d." },
    { en = "Maul and Raze may consume up to ${$s1/10} more Rage to deal up to $s2% additional damage.", ua = "«Трощення» і «Руйнування» можуть спожити до ${$s1/10} додаткової люті, щоб завдати до $s2% додаткової шкоди." },
    { en = "Increases Downpour healing by $s1%.", ua = "Збільшує зцілення від «Зливи» на $s1%." },
    { en = "Mangle has $s3 additional $Lcharge:charges; and when Maul is cast at $s1 Rage or above its chance to activate Gore is increased by $s2%.", ua = "«Шматування» має $s3 $Lдодатковий заряд:додаткові заряди;, а коли «Трощення» застосовано з $s1 од. люті або більше, його шанс активувати «Розпорювання» збільшується на $s2%." },
    { en = "Your Bleed effects deal $s1% increased damage.", ua = "Твої ефекти кровотечі завдають на $s1% більше шкоди." },
    { en = "Healing Wave's critical strike chance is increased by $s1%.", ua = "Імовірність критичного удару «Хвилі зцілення» збільшена на $s1%." },
    { en = "Reduces the mana cost of Healing Wave by 15%.", ua = "Зменшує вартість мани «Хвилі зцілення» на 15%." },
    { en = "Healing Stream Totem heals ${100*(1/(1+$s1/100)-1)}% more often.", ua = "«Тотем цілющого потоку» зцілює на ${100*(1/(1+$s1/100)-1)}% частіше." },
    { en = "When Strike as One critically strikes, it bleeds its target for an additional $1253138o1 damage over $1253138d.", ua = "Коли «Удар в унісон» завдає критичного удару, ціль спливає кров'ю, отримуючи додатково $1253138o1 шкоди протягом $1253138d." },
    { en = "Wildfire Bomb's periodic effect is now a Bleed and grants you and your pet ${$1292687s1*$1292687d} Focus over $1292687d.", ua = "Періодичний ефект «Бомби дикого вогню» тепер є кровотечею і дає тобі та твоєму улюбленцю ${$1292687s1*$1292687d} од. зосередження протягом $1292687d." },
    { en = "All Fire damage dealt is increased by $s1%.", ua = "Уся завдана вогняна шкода збільшена на $s1%." },
    { en = "$?a212613[Fracture][Consume] has a $s3% chance to grant $m1 $Lstack:stacks; of Voidfall.\n\n\n\nUpon reaching $1256301u stacks of Voidfall, $?a212613[Soul Cleave][Reap] consumes a stack to reach into the Void and call down a meteor strike at your target's location, dealing $?a212613[$1256306s1 Shadowflame][$1256305s1 Cosmic] damage to all enemies within $1256306A yards. Damage reduced beyond $s2 targets.", ua = "$?a212613[Перелом][Поглинання] має $s3% шансу надати $m1 $Lстак:стаки; Падіння Порожнечі.\n\n\n\nПри досягненні $1256301u стаків Падіння Порожнечі $?a212613[Розсічення душі][Жнива] споживає стак, щоб сягнути в Порожнечу й накликати удар метеора на місце вашої цілі, завдаючи $?a212613[$1256306s1 тіньовогняної][$1256305s1 космічної] шкоди всім ворогам у радіусі $1256306A м. Шкода зменшується понад $s2 цілей." },
    { en = "$?c2[Fel Devastation][Void Ray] damage increased by $s1%.\n\n\n\n$?c2[Fel Devastation][Fully channeling Void Ray] generates $?c2[$s4 Soul Fragments over its duration][$s3 $Lstack:stacks; of Voidfall].", ua = "Шкоду $?c2[Спустошення Скверни][Променя Порожнечі] збільшено на $s1%.\n\n\n\n$?c2[Спустошення Скверни][Повна каналізація Променя Порожнечі] генерує $?c2[$s4 фрагментів душі протягом своєї дії][$s3 $Lстак:стаки; Падіння Порожнечі]." },
    { en = "While at $s1 stacks of Voidfall, $?c2[Spirit Bomb and Soul Cleave][Reap] consumes all $s1 to rapidly call down that many meteor strikes.", ua = "За наявності $s1 стаків Падіння Порожнечі $?c2[Бомба духу та Розсікання душі споживають][Жнива споживають] усі $s1, щоб стрімко обрушити стільки ж ударів метеорів." },
    { en = "Each stack of Voidfall grants $s1% increased movement speed.", ua = "Кожен заряд Падіння Порожнечі збільшує швидкість руху на $s1%." },
    { en = "$?a212613[Torment][Shift] has $m1 additional $Lcharge:charges;.", ua = "$?a212613[Муки][Зсув] має $m1 додатковий $Lзаряд:заряди:зарядів;." },
    { en = "$?s263642[Fracture]?a212613[Shear][Consume] generates $?a212613[$s1][$s2] additional Fury and deals $?a212613[$s3%][$s4%] increased damage.", ua = "$?s263642[Перелом]?a212613[Розсікання][Поглинання] породжує $?a212613[$s1][$s2] додаткового Шалу і завдає $?a212613[$s3%][$s4%] більше шкоди." },
    { en = "Awaken memories of past conflicts, causing a Dread Shade to take form nearby.\n\n\n\nWhile active, shades slowly travel toward your target, dealing $1253488s1 Nature damage to nearby enemies and mirroring your Thrash casts.", ua = "Пробуджує спогади про минулі сутички, через що поблизу постає Моторошна тінь.\n\n\n\nДоки активні, тіні повільно рухаються до вашої цілі, завдаючи $1253488s1 шкоди силами природи ворогам поблизу та повторюючи ваші застосування Молотіння." },
    { en = "Penance has a high chance to upgrade Power Word: Shield into $@spellname1253593.\n\n\n\n$@spellicon1253593 $@spellname1253593:\n\n$@spelldesc1253593", ua = "Покута має високий шанс покращити Слово сили: Щит до $@spellname1253593.\n\n\n\n$@spellicon1253593 $@spellname1253593:\n\n$@spelldesc1253593" },
    { en = "Avenging Wrath now grants you $s1% Haste.\n\n\n\nEach Holy Power spent during Avenging Wrath increases Haste by an additional $s1%, up to $s2%.", ua = "«Караючий гнів» тепер дарує вам $s1% поспіху.\n\n\n\nКожна Священна сила, витрачена під час «Караючого гніву», збільшує поспіх ще на $s1%, аж до $s2%." },
    { en = "$?c3[Consuming Tip of the Spear has a $s2% chance to summon the aid of a Sentinel Owl that descends from the skies and applies Sentinel's Mark to your target][Your Eagle is replaced with a Sentinel Owl that applies an enhanced Sentinel's Mark].\n\n\n\n$@spellicon1253601$@spellname1253601\n\n$@spellaura1253601", ua = "$?c3[Витрачання Вістря списа має $s2% шанс прикликати на допомогу Сову-вартового, яка спускається з небес і накладає Мітку вартового на твою ціль][Твій Орел замінюється Совою-вартовим, яка накладає посилену Мітку вартового].\n\n\n\n$@spellicon1253601$@spellname1253601\n\n$@spellaura1253601" },
    { en = "Each stack of Voidfall grants $s1% Haste.", ua = "Кожен заряд Падіння Порожнечі дає $s1% Поспіху." },
    { en = "Activating $?a212613[Infernal Strike][Void Ray] out of combat or within $?a1213636[${$1265768d*$s2} sec][$1265768d] of entering combat calls down $?a212613[$s3][$s1] Voidfall $LMeteor:Meteors;$?a212613[][ over its duration].", ua = "Активація $?a212613[Інфернального удару][Променя Порожнечі] поза боєм або протягом $?a1213636[${$1265768d*$s2} сек.][$1265768d] після вступу в бій спричиняє падіння $?a212613[$s3][$s1] $LМетеора:Метеорів; Падіння Порожнечі$?a212613[][ протягом усієї тривалості]." },
    { en = "Casting Smite increases the damage of Smite by $s1%, stacking $1253725u times. Lasts $1253725d.", ua = "Творення «Кари» збільшує шкоду «Кари» на $s1%, складається до $1253725u разів. Триває $1253725d." },
    { en = "When Sentinel's Mark is consumed, it summons a barrage of $s1 lunar missiles, each dealing $1253733s1 Arcane damage to enemies within $s2 yds.", ua = "Коли «Знак вартової» поглинається, він прикликає шквал із $s1 місячних снарядів, кожен з яких завдає $1253733s1 арканної шкоди ворогам у радіусі $s2 м." },
    { en = "$?c2[Consuming Precise Shots][Consuming Tip of the Spear] grants $1253750s1% increased critical strike damage for $1253750d. Multiple applications may overlap.", ua = "$?c2[Споживання Точних пострілів][Споживання Вістря списа] надає $1253750s1% збільшеної шкоди критичним ударом на $1253750d. Кілька накладань можуть поєднуватися." },
    { en = "Enemies struck by a Voidfall Meteor take an additional $?a212613[$s1%][$s2%] damage over $1256667d.", ua = "Вороги, уражені метеором Падіння Порожнечі, отримують додатково $?a212613[$s1%][$s2%] шкоди впродовж $1256667d." },
    { en = "Roar with earthshattering ferocity, dealing $s2 Physical damage, and resetting the cooldown of Thrash and allowing it to stack $s1 additional times for $d. \n\n\n\nWhen Sundering Roar ends, any excess stacks of Thrash immediately deal their remaining damage.", ua = "Ричите з нищівною лютістю, завдаючи $s2 фізичної шкоди, скидаючи перезарядження Молотіння й дозволяючи йому накопичуватися ще $s1 раз(ів) протягом $d. \n\n\n\nКоли Розривний рик завершується, усі надлишкові заряди Молотіння негайно завдають своєї залишкової шкоди." },
    { en = "Passive bonuses granted by each stack of Voidfall persist for $1256322d after being consumed.", ua = "Пасивні бонуси від кожного заряду «Падіння Порожнечі» зберігаються протягом $1256322d після використання." },
    { en = "$?c2[Volley damage increased by $s1%][Flamefang Pitch damage increased by $s2%].", ua = "$?c2[Шкоду Залпу збільшено на $s1%][Шкоду Кидка вогняного ікла збільшено на $s2%]." },
    { en = "$?a212613[Spirit Bomb][Collapsing Star] and Voidfall meteors deal $s1% increased damage when striking a single target.\n\n\n\nEach additional target reduces this bonus by $s2%.", ua = "$?a212613[Духовна бомба][Зоря, що згасає] та метеори Падіння Порожнечі завдають на $s1% більше шкоди, коли вражають одну ціль.\n\n\n\nКожна додаткова ціль зменшує цей бонус на $s2%." },
    { en = "$?c2[Consuming Precise Shots][Consuming Tip of the Spear] has a $s1% increased chance to summon your Sentinel Owl.\n\n\n\nWhen your Sentinel Owl applies Sentinel's Mark, reduce the cooldown of $?c2[Aimed Shot][Wildfire Bomb] by $?c2[${$s2/1000}.1][${$s3/1000}.1] sec.", ua = "$?c2[Витрачання Точних пострілів][Витрачання Вістря списа] має на $s1% більший шанс прикликати твою Сову-вартового.\n\n\n\nКоли твоя Сова-вартовий накладає Мітку вартового, перезарядження $?c2[Прицільного пострілу][Бомби дикого вогню] скорочується на $?c2[${$s2/1000}.1][${$s3/1000}.1] с." },
    { en = "Void Shield reflects $s1% of damage taken to enemies, causing Atonement healing.", ua = "«Щит Порожнечі» відбиває $s1% отриманої шкоди у ворогів, викликаючи зцілення «Покути»." },
    { en = "$?c2[Precise Shots damage bonus][Tip of the Spear damage bonus] increased by $?c2[$s1][$s2]%.\n\n\n\n$?c2[Trueshot][Takedown] duration increased by $?c2[${$s3/1000}][${$s4/1000}] sec.", ua = "$?c2[Бонус шкоди Точних пострілів][Бонус шкоди Вістря списа] підвищений на $?c2[$s1][$s2]%.\n\n\n\nТривалість $?c2[Влучного пострілу][Повалення] подовжена на $?c2[${$s3/1000}][${$s4/1000}] с." },
    { en = "An additional $?c2[$s1][$s2]% of $?c2[Rapid Fire][Raptor Strike]'s damage is dealt as Arcane damage over $1253836d.", ua = "Додаткові $?c2[$s1][$s2]% шкоди $?c2[Швидкого вогню][Удару раптора] завдаються як арканна шкода протягом $1253836d." },
    { en = "Shadow damage and Atonement healing increased by $s1%.", ua = "Шкода від тіні та зцілення «Покути» збільшені на $s1%." },
    { en = "Sentinel's Mark further increases the damage of $?c2[Aimed Shot][Wildfire Bomb] by $?c2[$s1][$s2]%", ua = "Мітка вартового додатково збільшує шкоду $?c2[Прицільного пострілу][Бомби дикого вогню] на $?c2[$s1][$s2]%" },
    { en = "$?c2[Feathered Frenzy further increases your chance to summon your Sentinel Owl during Trueshot by $s1%][Takedown summons your Sentinel Owl and your chance to summon your Sentinel Owl is increased by an additional $s2% during Takedown].", ua = "$?c2[Пернате шаленство додатково збільшує ваш шанс прикликати Сову-вартову під час Влучного пострілу на $s1%][Повалення прикликає вашу Сову-вартову, а ваш шанс прикликати Сову-вартову збільшується ще на $s2% під час Повалення]." },
    { en = "Your movement speed is increased by $s1%.\n\n\n\nAspect of the Cheetah's cooldown is reduced by ${-$s2/1000} sec.", ua = "Ваша швидкість пересування збільшена на $s1%.\n\n\n\nПерезарядження Аспекту гепарда зменшено на ${-$s2/1000} сек." },
    { en = "Enemy detection radius reduced by $s1 yds.\n\n\n\nWhile in Camouflage, your stealth detection radius is increased by $s2 yds.", ua = "Радіус виявлення ворогів зменшено на $s1 м.\n\n\n\nПід час Маскування ваш радіус виявлення прихованих цілей збільшено на $s2 м." },
    { en = "Damaging one or more enemies with your Boomstick grants you $s1 $Lstack:stacks; of Mongoose Fury.\n\n\n\n$@spellicon259388 $@spellname259388\n\n$@spellaura259388", ua = "Завдаючи шкоди одному чи кільком ворогам Гримкою, ви отримуєте $s1 $Lзаряд:заряди:зарядів; Люті мангуста.\n\n\n\n$@spellicon259388 $@spellname259388\n\n$@spellaura259388" },
    { en = "Combustion's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Згоряння» зменшено на ${-$s1/1000} сек." },
    { en = "Increases Earth Shield healing by $s1%.", ua = "Збільшує зцілення від «Щита землі» на $s1%." },
    { en = "Reduces the cooldown of Riptide by ${$s1/-1000}.1 sec.", ua = "Зменшує перезарядження «Бистрини» на ${$s1/-1000}.1 сек." },
    { en = "Combustion grants you $s2% increased spell damage plus an additional $s1% of your critical strike chance as spell damage.", ua = "«Згоряння» збільшує шкоду твоїх заклять на $s2%, а також додає ще $s1% твого шансу критичного удару як шкоду заклять." },
    { en = "The explosion effect of Putrefy extends the duration of your plagues by ${$s1/1000}.1 sec and deals $s2% of the damage they would deal over that time instantly.\n\n\n\nPutrefy now applies your plagues to unaffected targets.", ua = "Ефект вибуху Гниття подовжує тривалість ваших пошестей на ${$s1/1000}.1 сек. і миттєво завдає $s2% шкоди, яку вони завдали б за цей час.\n\n\n\nГниття тепер накладає ваші пошесті на цілі, ще не охоплені ними." },
    { en = "Fire Blast now spreads $s3% of your target's Ignite to $s1 $Lenemy:enemies;.\n\n\n\nFlamestrike applies $s2% more Ignite.", ua = "«Вогняний вибух» тепер поширює $s3% ефекту «Займання» вашої цілі на $s1 $Lenemy:ворогів;.\n\n\n\n«Вогняний удар» накладає на $s2% більше «Займання»." },
    { en = "Fire Blast damage increased by $s2% and it now spreads Ignite to $s1 additional $Ltarget:targets;.", ua = "Шкода Вогняного вибуху збільшена на $s2%, і він тепер поширює Займання на $s1 додаткову $Lціль:цілі;." },
    { en = "Calls down a pillar of fire on your target, burning all enemies within the area for $s1 Fire damage. Deals reduced damage beyond $s2 targets.$?a205037[\n\n\n\nLeaves behind a patch of flames that burns enemies within it for ${$205470d*$205472s1} Fire damage over $205470d.][]\n\n\n\n|cFFFFFFFFThis spell is cast at your target.|r", ua = "Прикликає стовп вогню на вашу ціль, обпалюючи всіх ворогів у зоні на $s1 вогняної шкоди. Завдає зменшеної шкоди при понад $s2 цілях.$?a205037[\n\n\n\nЗалишає по собі смугу полум'я, що обпалює ворогів у ній на ${$205470d*$205472s1} вогняної шкоди протягом $205470d.][]\n\n\n\n|cFFFFFFFFЦе закляття твориться на вашу ціль.|r" },
    { en = "The enemy closest to the center of Meteor's impact takes $s3% increased damage.", ua = "Ворог, найближчий до центру падіння «Метеора», отримує на $s3% більше шкоди." },
    { en = "Casting Pyroblast or Flamestrike has a $s1% chance to summon a storm of $s4 cinders that pursue your target. Upon reaching your target, each cinder deals $1254024s1 Fire damage, applies Ignite at $s5% effectiveness, and spreads $s2% of your Ignite to up to $s3 nearby $Ltarget:targets;.", ua = "Творення Піровибуху чи Удару полум'я має $s1% шанс прикликати бурю з $s4 жарин, що переслідують вашу ціль. Досягнувши цілі, кожна жарина завдає $1254024s1 шкоди Вогнем, застосовує Займання з $s5% дієвості й поширює $s2% вашого Займання на до $s3 ближніх $Lцілей:цілей;." },
    { en = "The cooldown of Alter Time is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Зміни часу» зменшено на ${-$s1/1000} сек." },
    { en = "Each stack of Voidfall grants $s1% reduced damage taken.", ua = "Кожен заряд Падіння Порожнечі зменшує отримувану шкоду на $s1%." },
    { en = "Gain $m1 $Lstack:stacks; of Voidfall $?a212613[and reset the cooldown of Spirit Bomb][and reset the cooldown of Reap] upon activating $?a212613[Metamorphosis][Void Metamorphosis].", ua = "Отримуйте $m1 заряд:заряди; Падіння Порожнечі $?a212613[та скидайте перезарядження Бомби духу][та скидайте перезарядження Жнивування] під час активації $?a212613[Метаморфози][Метаморфози Порожнечі]." },
    { en = "Your first $?a212613[Spirit Bomb][Collapsing Star] after $?a212613[entering demon form][casting Void Metamorphosis] causes a $?a212613[Shadowflame][Cosmic] meteor shower to assault the area, dealing $?a212613[${$1264130s1*($s1)} Shadowflame][${$1264129s1*($s1)} Cosmic] damage over ${$s1/2} sec.", ua = "Ваша перша $?a212613[Душевна бомба][Зоря, що згасає] після $?a212613[входу в демонічну форму][прочитання Метаморфози Порожнечі] викликає метеоритний дощ $?a212613[Тіньового полум'я][Космічний], що обрушується на місцевість, завдаючи $?a212613[${$1264130s1*($s1)} шкоди Тіньовим полум'ям][${$1264129s1*($s1)} Космічної шкоди] протягом ${$s1/2} с." },
    { en = "The third Voidfall meteor strike called down in sequence is larger, has $s1% increased area, deals $s2% increased damage, and $?a212613[reduces the remaining cooldown of Metamorphosis by $s3 sec][generates $s4 Soul $LFragment:Fragments;].", ua = "Третій метеор Падіння Порожнечі, викликаний у послідовності, більший, має на $s1% більшу площу, завдає на $s2% більше шкоди та $?a212613[зменшує залишок перезарядження Метаморфози на $s3 с][створює $s4 $LФрагмент:Фрагменти; душі]." },
    { en = "Putrefy causes your next $s2 Scourge $LStrike:Strikes; to summon a Lesser Ghoul, and grants you $s1% Mastery for $1256576d.\n\n\n\nMultiple applications may overlap.", ua = "Гниття робить так, що ваші наступні $s2 $LУдари Погибелі:застосування Удару Погибелі; прикликають Меншого вурдалака, та надає вам $s1% Майстерності на $1256576d.\n\n\n\nКілька застосувань можуть накладатися." },
    { en = "Each Magus of the Dead under your command increases the damage of Necrotic Coil and Graveyard by $s4%.\n\n\n\nDread Plague has a $s3% chance to rouse the dead, causing a Lesser Ghoul to unearth and leap at the target to Putrefy at $s2% effectiveness.", ua = "Кожен Магус мертвих під вашим командуванням збільшує шкоду Некротичного покрову та Цвинтаря на $s4%.\n\n\n\nПошесть жаху має $s3% шанс розбудити мертвих, через що Менший гуль вибирається з-під землі та стрибає на ціль, завдаючи Гниття з $s2% ефективністю." },
    { en = "Essence abilities have a chance to infuse your next Reversion with the power of the Green Dragonflight, upgrading it to Merithra's Blessing:\n\n\n\n$@spellicon1256581 $@spellname1256581\n\n$@spelldesc1256581", ua = "Здібності есенції мають шанс наповнити ваше наступне Повернення силою Зеленої зграї драконів, підвищуючи його до Благословення Мерітри:\n\n\n\n$@spellicon1256581 $@spellname1256581\n\n$@spelldesc1256581" },
    { en = "Adrenaline Rush magnifies your precision and power, increasing the damage your combo point generating abilities and finishers deal by $s1%.", ua = "Приплив адреналіну посилює твою точність і міць, збільшуючи на $s1% шкоду твоїх здібностей, що генерують очки комбо, та завершальних прийомів." },
    { en = "Reversion protects allies, reversing ${$s1/10}.1% of all damage taken and healing them instead.", ua = "«Реверсія» захищає союзників, обертаючи ${$s1/10}.1% усієї отриманої шкоди на зцілення." },
    { en = "Dream Breath's instant healing is increased by $s1% and Dream Breath has a $s2% chance to grant Merithra's Blessing.", ua = "Миттєве зцілення «Подиху сну» збільшено на $s1%, а «Подих сну» має $s2% шансу дарувати «Благословення Мерітри»." },
    { en = "When you Putrefy a Lesser Ghoul, it has a $s1% chance to reanimate as a Magus of the Dead who hurls Frostbolts and Shadow Bolts at your foes for ${$s2/1000} sec.\n\n\n\nMagus of the Dead Frostbolts and Shadow Bolts deal $s3% increased damage.", ua = "Коли ви застосовуєте Гниття на нижчого вампіра, він має $s1% шансу ожити як Маг мертвих, що жбурляє Морозні стріли та Тіньові стріли у ваших ворогів упродовж ${$s2/1000} сек.\n\n\n\nМорозні стріли та Тіньові стріли Мага мертвих завдають на $s3% більше шкоди." },
    { en = "Takedown damage increased by $s1% and it now strikes $s2 additional nearby targets.\n\n\n\nDuring Takedown, your attack speed is increased by $s3%.", ua = "Шкоду Повалення збільшено на $s1%, і воно тепер уражає $s2 додаткових цілей поблизу.\n\n\n\nПід час Повалення ваша швидкість атаки збільшена на $s3%." },
    { en = "Raptor Strike and Boomstick deal $s1% increased critical strike damage.", ua = "Удар раптора та Бум-палиця завдають на $s1% більше критичної шкоди." },
    { en = "Consume the life force of each target afflicted by your damaging periodic effects, dealing ${$1257065s1*(1+ $d/$t1)} Shadowflame damage over $d.\n\n\n\nDamage dealt by Dark Harvest heals you for ${$1257065e1*100}% of damage done.", ua = "Поглинає життєву силу кожної цілі, ураженої вашими періодичними ефектами шкоди, завдаючи ${$1257065s1*(1+ $d/$t1)} шкоди тіньовим полум'ям впродовж $d.\n\n\n\nШкода, завдана Темними жнивами, зцілює вас на ${$1257065e1*100}% завданої шкоди." },
    { en = "Consuming Hot Streak has a $s1% chance to grant you a stack of Fired Up, increasing your Fire damage by $1257350s1% for $1257350d. Multiple applications may overlap.", ua = "Використання «Гарячої серії» має $s1% шансу дати тобі заряд ефекту «Розпалений», збільшуючи твою шкоду від вогню на $1257350s1% на $1257350d. Кілька накладань можуть діяти одночасно." },
    { en = "Combustion significantly increases your chance of gaining Fired Up, reducing each time you gain Fired Up.\n\n\n\nAdditionally Fired Up now extends Combustion's duration by ${$s2/1000}.1 sec.", ua = "Займання значно збільшує вашу ймовірність отримати Розпалений, і ця ймовірність зменшується щоразу, коли ви отримуєте Розпалений.\n\n\n\nКрім того, Розпалений тепер продовжує тривалість Займання на ${$s2/1000}.1 сек." },
    { en = "Gaining Fired Up reduces the cooldown of Fire Blast by ${$s1/1000}.1 sec.\n\n\n\nAll Fire damage dealt is increased by $s2%.", ua = "Отримання Розпаленого зменшує перезарядження Вогняного вибуху на ${$s1/1000}.1 сек.\n\n\n\nУся завдана вогняна шкода збільшена на $s2%." },
    { en = "Touch of the Magi increases the damage your target receives from you by $s1%.", ua = "«Дотик магів» збільшує шкоду, якої твоя ціль зазнає від тебе, на $s1%." },
    { en = "Arcane Charges further increase the damage of Arcane Blast, Arcane Pulse, and Arcane Barrage by $s1%.\n\n\n\nArcane Missiles damage increased by $s3%.", ua = "Арканні заряди додатково збільшують шкоду від Арканного вибуху, Арканного пульсу та Арканного шквалу на $s1%.\n\n\n\nШкода від Арканних снарядів збільшена на $s3%." },
    { en = "When Touch of the Magi explodes, it leaves behind a pulsing rune on its target, dealing $s1% of its damage over $1258134d to nearby enemies. Damage is increased by $s2% on your initial Touch of the Magi target.", ua = "Коли «Дотик магів» вибухає, він лишає на цілі пульсівну руну, що завдає ворогам поблизу $s1% його шкоди протягом $1258134d. Шкода для початкової цілі «Дотику магів» збільшена на $s2%." },
    { en = "Your maximum health is increased by $s1%.", ua = "Твоє максимальне здоров'я збільшене на $s1%." },
    { en = "Aspect of the Cheetah's initial burst of speed is increased by ${$s2/1000}.1 sec.", ua = "Початковий ривок швидкості «Аспекту гепарда» подовжено на ${$s2/1000}.1 сек." },
    { en = "The cooldown of Aspect of the Cheetah is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Аспекту гепарда» зменшено на ${-$s1/1000} сек." },
    { en = "The cooldown of Aspect of the Turtle is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Аспекту черепахи» зменшено на ${-$s1/1000} сек." },
    { en = "The cooldown of Feign Death is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Удаваної смерті» зменшено на ${-$s1/1000} сек." },
    { en = "Intimidation now also stuns nearby enemies for ${$1258508d}.1 sec.", ua = "«Залякування» тепер також приголомшує ворогів поблизу на ${$1258508d}.1 сек." },
    { en = "Lava Burst deals $s1% additional damage.", ua = "«Вибух лави» завдає на $s1% більше шкоди." },
    { en = "$@spellicon1258895 $@spellname1258895\n\nAll elemental damage is increased by an additional $s3%.\n\n\n\n$@spellicon462757 $@spellname462757\n\nIncreases the chance for Thunderstrikes to occur by $s2% and increases Thunderstrike damage by $s1%.", ua = "$@spellicon1258895 $@spellname1258895\n\nУся стихійна шкода додатково збільшується на $s3%.\n\n\n\n$@spellicon462757 $@spellname462757\n\nЗбільшує шанс спрацювання Громового удару на $s2% і збільшує шкоду Громового удару на $s1%." },
    { en = "All Elemental damage increased by $s1%.", ua = "Уся стихійна шкода збільшена на $s1%." },
    { en = "Earth Shock, Elemental Blast, and Earthquake deal $s1% increased damage.", ua = "«Земний шок», «Стихійний вибух» і «Землетрус» завдають на $s1% більше шкоди." },
    { en = "Raptor Strike has a $s1% chance to upgrade itself to a Raptor Swipe, dealing $1262293s1 Physical damage to all enemies within $s3 yds in front of you. Damage reduced beyond $s2 targets.", ua = "Удар раптора має $s1% шансу перетворитися на Змах раптора, що завдає $1262293s1 фізичної шкоди всім ворогам у межах $s3 м перед тобою. Шкоду зменшено, якщо цілей більше за $s2." },
    { en = "Raptor Strike, Wildfire Bomb, and Raptor Swipe damage increased by $s1%.\n\n\n\nRaptor Swipe deals $s2% increased damage to its primary target.", ua = "Шкоду Удару раптора, Бомби дикого вогню та Змаху раптора збільшено на $s1%.\n\n\n\nЗмах раптора завдає на $s2% більше шкоди своїй основній цілі." },
    { en = "Raptor Strike now has a $s1% chance to upgrade itself to a Raptor Swipe.\n\n\n\nRaptor Swipes that benefit from Tip of the Spear provoke an additional Strike as One at $s2% effectiveness.", ua = "Удар раптора тепер має $s1% шансу поліпшитися до Змаху раптора.\n\n\n\nЗмахи раптора, що користуються Вістрям списа, провокують додатковий Удар в унісон з $s2% ефективністю." },
    { en = "Lightning Bolt, $?a454009[Tempest, ][]Chain Lightning, Earth Shock, Elemental Blast, and Earthquake deal $s1% increased damage to targets affected by Flame Shock.", ua = "Удар блискавки, $?a454009[Буря, ][]Ланцюгова блискавка, Земний шок, Стихійний вибух та Землетрус завдають на $s1% більше шкоди цілям, що зазнають Полум'яного шоку." },
    { en = "Breath of Eons summons a version of you from the future to assist you in battle, lasting $1259171d. Your duplicate casts Eruption, Fire Breath, and Upheaval.", ua = "Подих еонів прикликає твою версію з майбутнього, що допомагає тобі в бою протягом $1259171d. Твій дублікат творить Виверження, Вогняний подих і Здіймання." },
    { en = "Any time you extend Ebon Might, your duplicate is also extended, equal to $s1% of the amount you extended Ebon Might by.", ua = "Щоразу, коли ти продовжуєш «Ебенову міць», твій дублікат теж продовжується — на $s1% часу, на який ти продовжуєш «Ебенову міць»." },
    { en = "While your duplicate is active, your Ebon Might grants $s1% additional stats and Upheaval and Eruption deal $1259171s3% increased damage.", ua = "Поки твій дублікат активний, твоя Ебенова міць дарує на $s1% більше характеристик, а Здіймання та Виверження завдають на $1259171s3% більше шкоди." },
    { en = "Your chance for Sinister Strike to strike twice and grant Opportunity is increased by $s1%", ua = "Шанс, що «Зловісний удар» вдарить двічі й дасть «Нагоду», збільшено на $s1%" },
    { en = "Adrenaline Rush's duration is increased by ${$s1/1000} sec.", ua = "Тривалість Припливу адреналіну збільшено на ${$s1/1000} сек." },
    { en = "Blade Flurry causes your attacks to hit nearby enemies for an additional $s1% of their normal damage.", ua = "Завдяки «Шквалу клинків» твої атаки додатково б'ють ворогів поблизу, завдаючи їм $s1% звичайної шкоди." },
    { en = "Voltaic Blaze unleashes volcanic rage, causing your next Lava Burst to also fire at $s3 additional targets with your Flame Shock at $1259491s1% effectiveness with reduced Maelstrom generation.\n\n\n\nLava Burst damage increased by $s1%.", ua = "Вольтаїчне полум'я вивільняє вулканічну лють, через що ваш наступний Вибух лави також влучає по $s3 додаткових цілях вашим Полум'яним ударом з $1259491s1% ефективністю та зі зменшеним накопиченням Виру.\n\n\n\nШкода Вибуху лави збільшена на $s1%." },
    { en = "The cooldown of Between the Eyes is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Межи очі» скорочено на ${-$s1/1000} сек." },
    { en = "The bonuses granted by your Roll the Bones are stronger.\n\n\n\nBonuses to chance for Sinister Strike to strike twice are $s1% greater.\n\nBonuses to Sinister Strike and Ambush damage are $s2% greater.\n\nBonuses to Restless Blades cooldown reduction are $s3% greater.\n\nJackpot's bonus to critical strike chance is $s4% greater.", ua = "Бонуси, що надає ваш «Кидок костей», сильніші.\n\n\n\nБонуси до шансу «Зловісного удару» вдарити двічі більші на $s1%.\n\nБонуси до шкоди «Зловісного удару» та «Засідки» більші на $s2%.\n\nБонуси до скорочення перезарядження «Невгамовних клинків» більші на $s3%.\n\nБонус «Джекпоту» до шансу критичного удару більший на $s4%." },
    { en = "Your auto-attack critical strikes increase the damage and critical strike chance of your next Between the Eyes by $1259486s1%, stacking up to $1259486u times.", ua = "Критичні удари твоїх автоатак збільшують шкоду та шанс критичного удару наступного «Межи очі» на $1259486s1%; ефект складається до $1259486u разів." },
    { en = "Sinister Strike and Ambush deal $s1% increased damage. They also generate $1259493s1 Energy when they grant you Opportunity.", ua = "Підступний удар і Засідка завдають на $s1% більше шкоди. Також вони генерують $1259493s1 од. енергії, коли дають тобі Нагоду." },
    { en = "Between the Eyes increases your damage dealt by an additional $s1%.", ua = "«Межи очі» додатково збільшує завдану тобою шкоду на $s1%." },
    { en = "Your finishing moves deal $s1% increased damage.", ua = "Твої завершальні прийоми завдають на $s1% більше шкоди." },
    { en = "After spending $s1 combo points, if you spend no combo points for $1259613d, abilities affected by Restless Blades will cool down $1259614s1% faster for $1259614d or until you spend a combo point.", ua = "Якщо після витрати $s1 очок комбо ти не витрачаєш очки комбо протягом $1259613d, здібності, на які діють Невтомні клинки, перезаряджаються на $1259614s1% швидше протягом $1259614d або доки ти не витратиш очко комбо." },
    { en = "Afflicts the target with $o2 Shadow damage over $d. Multiple uses of this ability may overlap.\n\n\n\nIf dispelled, deals ${$m2*$s1/100} damage to the dispeller and silences them for $196364d. This damage is increased by $s3% per stack on the target.\n\n\n\n|cFFFFFFFFGenerates $231791m1 Soul $LShard:Shards; if the target dies while afflicted.|r", ua = "Уражає ціль $o2 тіньової шкоди протягом $d. Кілька застосувань цієї здібності можуть накладатися.\n\n\n\nЯкщо розвіяти, завдає ${$m2*$s1/100} шкоди тому, хто розвіяв, і змушує його замовкнути на $196364d. Ця шкода збільшується на $s3% за кожен заряд на цілі.\n\n\n\n|cFFFFFFFFПороджує $231791m1 $LуламокДуші:уламки душі:уламків душі; якщо ціль гине під дією ефекту.|r" },
    { en = "Mastery increased by $s1%.", ua = "Майстерність збільшено на $s1%." },
    { en = "Increases damage dealt by Unstable Affliction and Seed of Corruption by $s1%.", ua = "Збільшує шкоду Нестабільної недуги та Зерна зіпсуття на $s1%." },
    { en = "Increases Agony damage by $s1% and Agony now hits another nearby enemy within $s2 yds of the target.", ua = "Збільшує шкоду «Агонії» на $s1%, і «Агонія» тепер вражає ще одного ворога в радіусі $s2 м від цілі." },
    { en = "Reduces the cast time of Seed of Corruption by ${$abs($s1)/1000}.2 sec and increases its damage by $s2%.", ua = "Зменшує час творення «Зерна псування» на ${$abs($s1)/1000}.2 сек. і збільшує його шкоду на $s2%." },
    { en = "Casting Unstable Affliction or Seed of Corruption reduces the cooldown of Dark Harvest by ${$s1/1000}.1 sec.", ua = "Творення «Нестабільної напасті» чи «Сімені зіпсуття» зменшує перезарядження «Темних жнив» на ${$s1/1000}.1 сек." },
    { en = "Agony damage is increased by $s1% and starts at $s2 stacks.", ua = "Шкода «Агонії» збільшена на $s1%, і вона починається з $s2 зарядів." },
    { en = "When Unstable Affliction expires, it has a $s1% chance to reapply itself.", ua = "Коли «Нестабільна напасть» спливає, є $s1% шансу, що вона накладеться знову." },
    { en = "Damage dealt by $?s388667[Drain Soul][Shadow Bolt] has a $?s198590[$s1][$s2]% chance to make your next Unstable Affliction cost no Soul Shards and cast instantly.", ua = "Шкода, завдана $?s388667[Висмоктуванням душі][Тіньовою стрілою], має $?s198590[$s1][$s2]% шанс зробити вашу наступну Нестабільну недугу безкоштовною за осколками душі та миттєвою у творенні." },
    { en = "Increases $?a445465[Wither][Corruption] damage by $s1% and Nightfall additionally makes your next Seed of Corruption cost no Soul Shards and cast instantly.", ua = "Підвищує шкоду $?a445465[В'янення][Псування] на $s1%, а Сутінки додатково роблять ваше наступне Сім'я псування таким, що не коштує Уламків душі та твориться миттєво." },
    { en = "When your Arcane Phoenix expires, it grants you Lesser Time Warp for $1260277d.\n\n\n\n$@spellicon1260277 $@spellname1260277\n\n$@spelldesc1260277", ua = "Коли ваш арканний фенікс зникає, він дарує вам Слабке викривлення часу протягом $1260277d.\n\n\n\n$@spellicon1260277 $@spellname1260277\n\n$@spelldesc1260277" },
    { en = "Increases damage dealt by Seed of Corruption to its host by $s1%.", ua = "Збільшує шкоду, яку Зерно зіпсуття завдає своєму носієві, на $s1%." },
    { en = "Divine Toll casts $s1 additional $ltime:times; on your target at $s2% effectiveness.", ua = "«Божественний поклик» спрацьовує на твоїй цілі ще $s1 раз з ефективністю $s2%." },
    { en = "Tip the Scales' cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Схилення терезів скорочено на ${$s1/-1000} сек." },
    { en = "Rising Sun Kick and Vivify have a chance to activate Spiritfont, causing your next Enveloping Mist's cast time to be reduced by $1260565s3% and channel Soothing Mist from you onto up to $s2 allies at $s1% effectiveness for $1260670d.\n\n\n\nIf Spiritfont's Soothing Mists heal a full health target, they will jump to another injured ally or split its healing into your remaining Soothing Mists.", ua = "Удар вранішнього сонця та Пожвавлення мають шанс активувати Духоджерело, через що час прочитання вашого наступного Огортального туману зменшується на $1260565s3%, а від вас на час $1260670d на до $s2 союзників підтримується Заспокійливий туман із $s1% ефективністю.\n\n\n\nЯкщо Заспокійливі тумани від Духоджерела зцілюють ціль з повним здоров'ям, вони перестрибують на іншого пораненого союзника або розподіляють своє зцілення між рештою ваших Заспокійливих туманів." },
    { en = "$?c1[Arcane Salvo can stack $s1 additional times][Fire Blast cooldown reduced by ${-$s2/1000}.1 sec].\n\n\n\nMeteorite damage increased by $s3%.", ua = "$?c1[Залп аркани може накопичуватися додатково $s1 разів][Перезарядження Вогняного вибуху зменшено на ${-$s2/1000}.1 сек].\n\n\n\nШкода від метеорита збільшена на $s3%." },
    { en = "$?c2[Lava Lash damage increased by $s2%.\n\n\n\nEach stack of Maelstrom Weapon consumed increases the duration of an active Hot Hand by ${$s1/1000}.2 sec.][Reduces the cooldown of Healing Stream Totem by ${$s3/-1000} sec.]", ua = "$?c2[Шкода «Лавового батога» зросла на $s2%.\n\n\n\nКожен спожитий заряд «Зброї Виру» збільшує тривалість активної «Гарячої руки» на ${$s1/1000}.2 сек.][Зменшує перезарядження «Тотема цілющого потоку» на ${$s3/-1000} сек.]" },
    { en = "Chrono Flames' maximum damage or healing is increased by $s1%, up to $<cap> Arcane.", ua = "Максимальна шкода чи зцілення Хроновогнів збільшується на $s1%, щонайбільше до $<cap> арканної." },
    { en = "Voltaic Blaze generates $s1 additional Maelstrom Weapon and has a $s2% chance to cause a Fire Nova.\n\n\n\n$@spellicon333974$@spellname333974\n\n$@spelldesc333974", ua = "Вольтова заграва створює $s1 додаткову Зброю виру і з шансом $s2% викликає Вогняну нову.\n\n\n\n$@spellicon333974$@spellname333974\n\n$@spelldesc333974" },
    { en = "$?c1[Each wave of Arcane Missiles][Damage from Fireball] has a $?c1[$s1][$s2]% chance to summon a Meteorite.\n\n\n\nWhen a Meteorite lands, $?c1[you have a $s5% chance to gain Clearcasting][the cooldown of Fire Blast is reduced by ${$s4/1000}.1 sec].", ua = "$?c1[Кожна хвиля Арканних снарядів][Шкода від Вогняної кулі] має $?c1[$s1][$s2]% шансу прикликати метеорит.\n\n\n\nКоли метеорит приземляється, $?c1[ви маєте $s5% шансу отримати Ясне творіння][перезарядження Вогняного вибуху зменшується на ${$s4/1000}.1 сек]." },
    { en = "Rising Sun Kick damage increased by $s2% and Enveloping Mist healing increased by $s1%. These bonuses are increased by $s3% while Spiritfont is active.", ua = "Шкода Удару висхідного сонця збільшена на $s2%, а зцілення Огортального туману — на $s1%. Поки активне Духоджерело, ці бонуси збільшені на $s3%." },
    { en = "Thunder Focus Tea activates Spiritfont and Spiritfont applies Chi Cocoons at $s1% effectiveness to allies targeted.", ua = "«Чай громової зосередженості» активує «Духоджерело», а «Духоджерело» накладає на обраних союзників «Кокони ці» з ефективністю $s1%." },
    { en = "While flying during $?s403631[Breath of Eons][Deep Breath] you are assisted by a squadron of Dracthyr who assault enemies with Pyre, dealing $1236970s1 Fire damage to nearby enemies up to $s3 times.", ua = "Поки ви летите під час $?s403631[Подиху еонів][Глибокого подиху], вам допомагає ескадра драктирів, які атакують ворогів Багаттям, завдаючи $1236970s1 шкоди Вогнем ворогам поблизу до $s3 разів." },
    { en = "$?c2[After casting Surging Totem, your next Lava Lash casts again at $s1% effectiveness.][Healing Stream Totem and Healing Tide Totem healing has a $s2% chance to apply Earthliving to allies it heals.]", ua = "$?c2[Після прочитання Вогкого тотема ваш наступний Лавовий батіг твориться знову з $s1% ефективністю.][Зцілення Тотема цілющого потоку й Тотема цілющого приливу має $s2% шанс накласти Живоземлю на зцілених союзників.]" },
    { en = "Slam has a 10% increased chance to trigger Tactician.", ua = "«Трощення» має на 10% вищий шанс активувати «Тактика»." },
    { en = "Slam's Rage cost is reduced by $s1%.", ua = "Вартість «Трощення» в люті зменшено на $s1%." },
    { en = "Colossus Smash generates ${$s1/10} Rage.", ua = "Удар колоса генерує ${$s1/10} люті." },
    { en = "Colossus Smash grants you Sweeping Strikes.", ua = "Удар колоса надає тобі Кругові удари." },
    { en = "Secondary targets take an additional $s1% damage from Sweeping Strikes.", ua = "Другорядні цілі отримують на $s1% більше шкоди від «Розмашистих ударів»." },
    { en = "Colossus Smash causes your next $1261185u Mortal Strikes to have a $1261185s1% chance to trigger Tactician.", ua = "Удар колоса надає твоїм наступним $1261185u Смертельним ударам $1261185s1% шансу активувати Тактика." },
    { en = "Colossus Smash causes your next $1261189u Cleaves within $1261189d to trigger no cooldown.", ua = "Удар колоса дозволяє твоїм наступним $1261189u Розсіченням протягом $1261189d не запускати перезарядження." },
    { en = "Tactician has a $s1% increased chance to trigger.", ua = "«Тактик» має на $s1% вищий шанс спрацювати." },
    { en = "Execute inflicts Deep Wounds on the target.\n\n\n\n$@spellicon262115 $@spellname262115\n\n$@spelldesc262115", ua = "Страта завдає цілі Глибоких ран.\n\n\n\n$@spellicon262115 $@spellname262115\n\n$@spelldesc262115" },
    { en = "Mortal Strike and Slam critical strikes inflict Deep Wounds at $s1% effectiveness.\n\n\n\n$@spellicon262115 $@spellname262115\n\n$@spelldesc262115", ua = "Критичні удари Смертельного удару та Замашного удару завдають Глибоких ран із $s1% ефективністю.\n\n\n\n$@spellicon262115 $@spellname262115\n\n$@spelldesc262115" },
    { en = "Direct damage from $?c1[Arcane][Frost] Splinters have a $?c1[$s1][$s2]% chance to $?c1[grant $s3 $Lstack:stacks; Arcane Salvo][apply $s4 $Lstack:stacks; of Freezing].$?c1[\n\n\n\n$@spellicon1242974 $@spellname1242974\n\n$@spellaura1242974][]", ua = "Пряма шкода від $?c1[арканних][крижаних] скалок має $?c1[$s1][$s2]% шанс $?c1[надати $s3 $Lстак:стаки; «Арканного залпу»][накласти $s4 $Lстак:стаки; «Заморожування»].$?c1[\n\n\n\n$@spellicon1242974 $@spellname1242974\n\n$@spellaura1242974][]" },
    { en = "$?c1[Casting Arcane Barrage while at $s1 or more Arcane Salvo stacks refunds $s2 Arcane Salvo $Lstack:stacks;.\n\n\n\nArcane Barrage damage increased by $s4%.][Ice Lance Shatters $s3 additional $Lstack:stacks; of Freezing.\n\n\n\nShatter damage increased by $s5%.]", ua = "$?c1[Творіння Арканного шквалу за наявності $s1 або більше зарядів Залпу аркани повертає $s2 $Lзаряд:заряди:зарядів; Залпу аркани.\n\n\n\nШкода від Арканного шквалу збільшена на $s4%.][Крижаний спис розколює $s3 додаткових $Lзаряд:заряди:зарядів; Заморожування.\n\n\n\nШкода від Розколювання збільшена на $s5%.]" },
    { en = "$?c1[Your Arcane Familiar has a $s1% chance to conjure a Splinter alongside its Arcane Assault][Your Water Elemental has a $s2% chance to conjure a Splinter alongside its Waterbolt].", ua = "$?c1[Ваш арканний фамільяр має $s1% шанс прикликати Скалку разом зі своїм Арканним натиском][Ваш елементаль води має $s2% шанс прикликати Скалку разом зі своїм Водяним зарядом]." },
    { en = "Avenging Wrath further increases the damage of $?s383328[Final Verdict][Templar's Verdict] and Divine Storm by $s1%.", ua = "Гнів месника додатково збільшує шкоду $?s383328[Останнього вердикту][Вердикту храмовника] і Божественної бурі на $s1%." },
    { en = "$?s402912[Righteous Cause][Art of War] increases the damage of your next Blade of Justice by $s1%.", ua = "$?s402912[«Праведна справа»][«Мистецтво війни»] збільшує шкоду твого наступного «Клинка правосуддя» на $s1%." },
    { en = "Casting Unstable Affliction on a target affected by your Unstable Affliction increases your Haste by $1261125s1% for $1261125d.", ua = "Творення «Нестабільної напасті» на цілі, що вже під дією твоєї «Нестабільної напасті», збільшує твій поспіх на $1261125s1% на $1261125d." },
    { en = "While Darkglare is active, your $?a388667[Drain Soul][Shadow Bolt] becomes Malefic Grasp. \n\n\n\n$@spellicon1261153 $@spellname1261153\n\n$@spelldesc1261153", ua = "Поки темнозор активний, ваша $?a388667[Висмоктування душі][Тіньова стріла] стає Зловісною хваткою. \n\n\n\n$@spellicon1261153 $@spellname1261153\n\n$@spelldesc1261153" },
    { en = "$?s402912[Righteous Cause][Art of War] further empowers Blade of Justice to unleash a wave of Holy energy, dealing ${$1261160s1*$<mult>} Holy damage to its primary target and $1261160s1 Holy damage to all other enemies in its path.", ua = "$?s402912[«Праведна справа»][«Мистецтво війни»] ще більше підсилює «Клинок правосуддя»: він вивільняє хвилю святої енергії, що завдає ${$1261160s1*$<mult>} святої шкоди основній цілі та $1261160s1 святої шкоди всім іншим ворогам на своєму шляху." },
    { en = "Unload a series of ${($d/$t1)+1} shotgun blasts $s3 yds in front of you, dealing ${$1261215s1*4} Physical damage over $d. Deals reduced damage beyond $s2 targets.", ua = "Випускаєш серію з ${($d/$t1)+1} пострілів із рушниці на $s3 м перед собою, завдаючи ${$1261215s1*4} фізичної шкоди протягом $d. Шкода зменшується, якщо цілей більше за $s2." },
    { en = "Damaging one or more enemies with your Boomstick reduces the cooldown of Wildfire Bomb by ${$s1/1000}.1 sec.", ua = "Поранення одного чи більше ворогів «Бабахалкою» скорочує перезарядження «Бомби дикого вогню» на ${$s1/1000}.1 сек." },
    { en = "$?c1[Mass Disintegrate][Mass Eruption] strikes $s1 additional $Ltarget:targets;.", ua = "$?c1[«Масова дезінтеграція»][«Масове виверження»] вражає $s1 додаткову $Ltarget:targets;." },
    { en = "Essence abilities deal $s1% additional damage.", ua = "Здібності есенції завдають на $s1% більше шкоди." },
    { en = "Empyrean Hammer deals $s1% increased critical strike damage and its critical strikes have $h% chance to grant an additional stack of Light's Deliverance.", ua = "«Емпірейський молот» завдає на $s1% більше шкоди від критичних ударів, а його критичні удари мають $h% шансу дати додатковий заряд «Визволення Світла»." },
    { en = "Blackout Kick deals $s1% increased damage. Spinning Crane Kick deals $s2% additional damage.", ua = "«Удар затьмарення» завдає на $s1% більше шкоди. «Обертовий удар журавля» завдає на $s2% додаткової шкоди." },
    { en = "Divine Protection reduces damage taken by an additional $s2% and casts Shield of Vengeance.\n\n\n\n$@spellicon184662$@spellname184662\n\n$@spelldesc184662", ua = "Божественний захист зменшує отримувану шкоду ще на $s2% і творить Щит помсти.\n\n\n\n$@spellicon184662$@spellname184662\n\n$@spelldesc184662" },
    { en = "Activating an Eclipse makes your next Wrath or Starfire instant. The first 3 Starsurges or Starfalls you cast during each Eclipse deal $1263382s1% increased damage.", ua = "Активація затемнення робить твій наступний «Гнів» або «Зоряний вогонь» миттєвим. Перші 3 «Зоряні сплески» чи «Зорепади», створені під час кожного затемнення, завдають на $1263382s1% більше шкоди." },
    { en = "Your critical strikes dealt during an Eclipse cause their victims to languish for an additional $s1% of damage dealt for $1263250d.", ua = "Твої критичні удари під час Затемнення змушують жертв знемагати, завдаючи їм додатково $s1% завданої шкоди протягом $1263250d." },
    { en = "Activating an Eclipse also launches Solar or Lunar Bolts at enemies within $s1 yds that always critically strike.\n\n\n\n$@spellicon1261573 $@spellname1261573\n\nEntering Solar Eclipse launches a Solar Bolt at $s2 $Lenemy:enemies; that deals $1261573s1 Nature damage.\n\n\n\n$@spellicon1263137 $@spellname1263137\n\nEntering Lunar Eclipse launches $s3 Lunar Bolts at enemies that deal $1263137s1 Arcane damage to them and nearby targets. Deals reduced damage beyond 5 targets.", ua = "Активація Затемнення також запускає Сонячні або Місячні стріли у ворогів у межах $s1 м, що завжди влучають критично.\n\n\n\n$@spellicon1261573 $@spellname1261573\n\nВхід у Сонячне затемнення запускає Сонячну стрілу в $s2 $Lворога:ворогів;, що завдає $1261573s1 шкоди Природою.\n\n\n\n$@spellicon1263137 $@spellname1263137\n\nВхід у Місячне затемнення запускає $s3 Місячні стріли у ворогів, що завдають $1263137s1 арканної шкоди їм і ближнім цілям. Завдає зменшеної шкоди понад 5 цілей." },
    { en = "While in combat, generate $s1 Soul $LFragment:Fragments; every $t1 sec.\n\n\n\nWhile out of combat, you will slowly build towards your Void Metamorphosis, up to $s2 Soul Fragments.", ua = "У бою генерує $s1 $LФрагмент душі:Фрагменти душі; кожні $t1 с.\n\n\n\nПоза боєм ви поволі наближаєтесь до Метаморфози Порожнечі, аж до $s2 фрагментів душі." },
    { en = "Every $s2 Chi spent generates Tigereye Brew. Zenith consumes up to $s3 Tigereye Brew stacks to increase your critical strike chance for its duration by $1261724s1% per stack.\n\n\n\nGenerates quickly up to $s1 stacks while out of combat and may generate up to a maximum of $1261724u stacks.", ua = "За кожні витрачені $s2 чі генерується Варево тигрового ока. Зеніт споживає до $s3 стаків Варева тигрового ока, збільшуючи на час своєї дії ваш шанс критичного удару на $1261724s1% за стак.\n\n\n\nПоза боєм швидко генерує до $s1 стаків, а максимум може згенерувати до $1261724u стаків." },
    { en = "Your spells and abilities deal $s1% increased critical strike damage.", ua = "Твої закляття та здібності завдають на $s1% більше шкоди критичних ударів." },
    { en = "Zenith now grants access to $s1 additional Zenith Stomps.\n\n\n\n$@spellicon1272696 $@spellname1272696:\n\n$@spelldesc1272696", ua = "Зеніт тепер дає доступ до $s1 додаткових Тупотів зеніту.\n\n\n\n$@spellicon1272696 $@spellname1272696:\n\n$@spelldesc1272696" },
    { en = "Perform a powerful off-role ability depending on your currently active shapeshift form.$?c4[][\n\n\n\n|cFFFFFFFFNon-shapeshifted:|r\n\nEmpowered Wild Growth that heals up to $48438s2 injured allies within $48438A1 yards of the target for ${$48438o1*$s4/100} over $48438d.]$?c1[]?c2[][\n\n\n\n|cFFFFFFFFCat Form:|r\n\nUnleash an empowered Feral Frenzy, clawing your target $274837m2 times for ${$274837m2*$274838s1*$s2/100} Physical damage and an additional ${$274837m2*$s2/100*$274838s3*$274838d/$274838t3} Bleed damage over $274838d. Awards 5 combo points.\n\n\n\n|cFFFFFFFFMoonkin Form:|r\n\nCall down waves of empowered falling stars upon enemies within $50286A1 yds, dealing ${54*$191037s1} Astral damage over $191034d.]$?c3[][\n\n\n\n|cFFFFFFFFBear Form:|r\n\nIncrease your maximum health by $1261872s1% for $1261872d.]", ua = "Виконує потужне нерольове вміння залежно від вашої поточної подоби.$?c4[][\n\n\n\n|cFFFFFFFFБез подоби:|r\n\nПосилений Дикий ріст, що зцілює до $48438s2 поранених союзників у радіусі $48438A1 ярдів від цілі на ${$48438o1*$s4/100} упродовж $48438d.]$?c1[]?c2[][\n\n\n\n|cFFFFFFFFКотяча подоба:|r\n\nВивільняє посилену Дику нестяму, шматуючи кігтями вашу ціль $274837m2 рази й завдаючи ${$274837m2*$274838s1*$s2/100} фізичної шкоди та ще ${$274837m2*$s2/100*$274838s3*$274838d/$274838t3} шкоди кровотечею впродовж $274838d. Надає 5 комбо-очок.\n\n\n\n|cFFFFFFFFПодоба місяцерода:|r\n\nЗакликає хвилі посилених падучих зір на ворогів у радіусі $50286A1 ярдів, завдаючи ${54*$191037s1} астральної шкоди впродовж $191034d.]$?c3[][\n\n\n\n|cFFFFFFFFВедмежа подоба:|r\n\nЗбільшує ваше максимальне здоров'я на $1261872s1% на $1261872d.]" },
    { en = "Haunt now calls upon a demonic soul from within the Twisting Nether to haunt your target.\n\n\n\nThe soul is unstable and ravenous, dealing ${$1262710s1*($48181d/$48181t5)} Shadow damage to its host and ${$1262710x1-1} enemies within $1278047a1 yards suffering from your $?a445465[Wither][Corruption] over its duration.", ua = "Наслання тепер прикликає демонічну душу з Викривленої Порожнечі, щоб насилати на вашу ціль.\n\n\n\nДуша нестабільна й ненаситна, завдаючи ${$1262710s1*($48181d/$48181t5)} тіньової шкоди своєму носієві та ${$1262710x1-1} ворогам у радіусі $1278047a1 ярдів, що потерпають від вашого $?a445465[Усихання][Розтління], протягом усієї тривалості." },
    { en = "Increases the initial damage of Haunt by $s1% and Haunt increases damage dealt to its host by an additional $s2%.", ua = "Збільшує початкову шкоду Наслання на $s1%, а Наслання збільшує шкоду, завдану його носієві, додатково на $s2%." },
    { en = "Damage dealt by Haunt has a chance to release the demonic soul haunting its target. When released, it unleashes a devastating attack before being banished back to Nathreza.\n\n\n\n$@spellicon1262028 $@spellname1262028\n\n$@spelldesc1262028", ua = "Шкода, завдана Насланням, має шанс вивільнити демонічну душу, що насилає на її ціль. Вивільнившись, вона здійснює нищівну атаку, перш ніж бути вигнаною назад до Натрези.\n\n\n\n$@spellicon1262028 $@spellname1262028\n\n$@spelldesc1262028" },
    { en = "Exploding Keg also causes your next $s1 $Lcast:casts; of Keg Smash to summon a whirl of flame which spirals outwards, dealing $1262159s1 additional Fire damage to each enemy struck.", ua = "Вибуховий барель також змушує ваші наступні $s1 $Lпрочитання:прочитання; Удару барелем прикликати вихор полум'я, що розкручується назовні, завдаючи $1262159s1 додаткової шкоди вогнем кожному враженому ворогу." },
    { en = "Mark of the Wild is $s1% more effective on yourself.", ua = "«Знак дикої природи» на $s1% ефективніший, коли діє на тебе." },
    { en = "Exploding Keg can be reactivated within $1262768d to throw $s1 additional kegs at nearby targets, each dealing $1262765s1 Physical damage and reducing the cooldown of your Brews by ${$s2/1000}.1 sec.", ua = "«Вибухове барило» можна активувати повторно протягом $1262768d, щоб кинути в найближчі цілі ще $s1 барил, кожне з яких завдає $1262765s1 фізичної шкоди та скорочує перезарядження твоїх варив на ${$s2/1000}.1 сек." },
    { en = "Crackling Jade Lightning deals its damage in $s1% less time, costs $s3% less Energy, and strikes ${$s2-1} additional targets, but has a ${$s5/1000} sec cooldown.", ua = "«Тріскуча нефритова блискавка» завдає свою шкоду на $s1% швидше, коштує на $s3% менше енергії та вражає ${$s2-1} додаткові цілі, але має перезарядження ${$s5/1000} сек." },
    { en = "Wildfire Bomb reduces the cooldown of Boomstick by ${$s1/1000}.1 sec for each enemy hit, up to ${$s1/1000*$s2} sec.", ua = "«Бомба дикого вогню» скорочує перезарядження «Бахкала» на ${$s1/1000}.1 сек. за кожного враженого ворога, аж до ${$s1/1000*$s2} сек." },
    { en = "Mastery increased by $s1%.\n\n\n\nYou gain $s2% increased Mastery from all Mastery sources.", ua = "Майстерність збільшено на $s1%.\n\n\n\nВи отримуєте на $s2% більше Майстерності з усіх джерел Майстерності." },
    { en = "Activating $?c1[Invoke Niuzao, the Black Ox][Zenith] instantly grants $s1 stacks of Flurry Strikes that trigger on your next attack at $s2% effectiveness.", ua = "Активація $?c1[Прикликання Ніузао, Чорного Вола][Зеніту] миттєво надає $s1 стаків Шквалу ударів, що спрацьовують при вашій наступній атаці з $s2% ефективністю." },
    { en = "$?c1[Invoke Niuzao, the Black Ox's stomp damage increased by $s2%][Zenith Stomp damage increased by $s1%].", ua = "$?c1[Шкода від тупоту «Прикликання Ніузао, Чорного Вола» підвищена на $s2%][Шкода від «Зенітного тупоту» підвищена на $s1%]." },
    { en = "Flurry Strikes deal $451250s1 Nature damage to all enemies within $451250a yds, reduced beyond $s2 targets.", ua = "«Шквал ударів» завдає $451250s1 шкоди від природи всім ворогам у радіусі $451250a м; шкода зменшена, якщо цілей більше ніж $s2." },
    { en = "Purifying Brew also surrounds you with protective energies for $1263631d. \n\n\n\nWhen |CFFffffffStaggered|R damage would be dealt to you, you instead absorb up to $1263631s2%, until $<absorb> has been prevented.", ua = "Очищувальне вариво також огортає вас захисними енергіями протягом $1263631d. \n\n\n\nКоли вам мала б бути завдана |CFFffffffЗатримана|R шкода, ви натомість поглинаєте до $1263631s2%, доки не буде відвернено $<absorb>." },
    { en = "Lightning Bolt and Chain Lightning deal $s1% increased damage and have a $s2% chance to refund the Maelstrom Weapon spent.", ua = "«Блискавка» та «Ланцюгова блискавка» завдають на $s1% більше шкоди й мають $s2% шансу повернути витрачені заряди «Зброї виру»." },
    { en = "Heal for $s1% of all Fire or Nature damage dealt by your spells and abilities.", ua = "Зцілює тебе на $s1% усієї шкоди від вогню чи природи, завданої твоїми закляттями та здібностями." },
    { en = "$?c3[Heart of the Jade Serpent additionally triggers for ${$s1/1000} sec at $s2% effectiveness after you cast Zenith][Vivify and Sheilun's Gift have a chance to trigger Heart of the Jade Serpent for ${$s1/1000} sec at $s2% effectiveness].", ua = "$?c3[Серце Нефритової Змії додатково спрацьовує на ${$s1/1000} с із $s2% ефективністю після того, як ви застосуєте Зеніт][Оживлення та Дар Шейлуна мають шанс спрацювати Серце Нефритової Змії на ${$s1/1000} с із $s2% ефективністю]." },
    { en = "Heart of the Jade Serpent increases your haste by $443421s8% while active.", ua = "«Серце Нефритової Змії» збільшує твій поспіх на $443421s8%, поки діє." },
    { en = "Each Maelstrom Weapon spent has a ${$s1/10}% chance to cause your next Crash Lightning to ignore its cooldown. The weapon enhancement effect of Crash Lightning may now overlap.", ua = "Кожен витрачений заряд «Зброї Виру» з імовірністю ${$s1/10}% дозволяє твоєму наступному «Грозовому удару» знехтувати перезарядженням. Ефект посилення зброї від «Грозового удару» тепер може накладатися." },
    { en = "Prayer of Mending healing has a chance to upgrade your next Flash Heal to Benediction, healing the target for $s1% more and causing a Cosmic Ripple.", ua = "Зцілення «Молитви відновлення» має шанс покращити твоє наступне «Швидке зцілення» до «Благословіння», що зцілює ціль на $s1% сильніше та викликає «Космічну хвилю»." },
    { en = "Strength of the Black Ox's effect is $?c3[$s1][$s2]% more effective on your primary target.", ua = "Ефект «Сили Чорного Вола» на $?c3[$s1][$s2]% ефективніший на вашій основній цілі." },
    { en = "Cosmic Ripple healing increased by $s1%.\n\n\n\nAll healing done increased by $s2%.", ua = "Зцілення від «Космічної брижі» збільшено на $s1%.\n\n\n\nУсе завдане зцілення збільшено на $s2%." },
    { en = "Each pulse of Divine Hymn emits a Cosmic Ripple at $s1% effectiveness.\n\n\n\nDuring Apotheosis, Flash Heal is upgraded to Benediction.", ua = "Кожен імпульс «Божественного гімну» випромінює «Космічну брижу» з ефективністю $s1%.\n\n\n\nПід час «Апофеозу» «Швидке зцілення» поліпшується до «Благословіння»." },
    { en = "Maelstrom Weapon spending abilities deal $s1% increased damage. \n\n\n\nWeapon Imbuements deal $s2% increased damage.", ua = "Здібності, що витрачають «Зброю виру», завдають на $s1% більше шкоди. \n\n\n\nЗброярські просочення завдають на $s2% більше шкоди." },
    { en = "$?c2[Casting Pyroblast has a $s2% chance to also cast a Glacial Spike, dealing $1262862s1 Frost damage][Casting Glacial Spike also casts a Pyroblast, dealing $1262863s1 Fire damage].", ua = "$?c2[Прочитання Піровибуху має $s2% шанс також прочитати Льодяний шпиль, завдаючи $1262862s1 шкоди морозом][Прочитання Льодяного шпиля також творить Піровибух, завдаючи $1262863s1 шкоди вогнем]." },
    { en = "$?c3[Your Frostfire spells apply Ignite, dealing an additional $s1% of their damage over $1262887d][Your Frostfire spells apply Ignite at $s2% increased effectiveness].", ua = "$?c3[Ваші закляття Льодополум'я накладають Займання, завдаючи додатково $s1% своєї шкоди протягом $1262887d][Ваші закляття Льодополум'я накладають Займання з підвищеною на $s2% ефективністю]." },
    { en = "$?c2[Comet Storm and Glacial Spike now apply Ignite][Meteor and Pyroblast now apply Ignite].\n\n\n\nYour Haste is increased by $s2%.", ua = "$?c2[Буря комет та Льодяний шпиль тепер накладають Займання][Метеор та Піровибух тепер накладають Займання].\n\n\n\nВаш Поспіх збільшено на $s2%." },
    { en = "Shattering an enemy has a $s1% chance to summon a Hand of Frost to pursue your target, dealing $1262769s1 Frost damage and applying $s2 $Lstack:stacks; of Freezing on contact.", ua = "Розбиття ворога має $s1% шансу прикликати Руку морозу, що переслідує вашу ціль, завдаючи $1262769s1 шкоди від морозу і накладаючи $s2 $Lнабій:набоїв; Замороження при контакті." },
    { en = "Each stack of Freezing you Shatter increases your chance to summon a Hand of Frost by an additional ${$s1/10}.1%.\n\n\n\nDamage from Hand of Frost increases your spell damage by $s2% for $1263263d. Multiple applications may overlap.", ua = "Кожне нашарування Заморожування, яке ви Розтрощуєте, збільшує вашу ймовірність прикликати Руку морозу на додаткові ${$s1/10}.1%.\n\n\n\nШкода від Руки морозу збільшує шкоду ваших заклять на $s2% на $1263263d. Кілька накладань можуть перекриватися." },
    { en = "Mastery increased by $s1%. Double this effect while Invoke Niuzao, the Black Ox is active.", ua = "Майстерність збільшена на $s1%. Ефект подвоюється, поки діє «Виклик Нюцзао, Чорного Вола»." },
    { en = "Ray of Frost summons $s1 Hands of Frost over its duration.\n\n\n\nRay of Frost gains an additional charge and its damage is increased by $s3%.", ua = "Промінь морозу прикликає $s1 Руки морозу протягом своєї тривалості.\n\n\n\nПромінь морозу отримує додатковий заряд, а його шкода збільшується на $s3%." },
    { en = "$?a137028[Judgment]?s383328[Final Verdict][Templar's Verdict] damage increased by $?a137028[$s2%][$s1%].", ua = "Шкода $?a137028[«Осуду»]?s383328[«Остаточного вердикту»][«Вердикту храмовника»] збільшена на $?a137028[$s2%][$s1%]." },
    { en = "Drinking from a Brew increases your movement speed by $1263345s1% and your auto-attack speed by $1263345s2% for $1263345d.", ua = "Випите варево збільшує твою швидкість руху на $1263345s1%, а швидкість автоатак — на $1263345s2% протягом $1263345d." },
    { en = "Drinking from Brews has a $h% chance to coat you with Celestial Flames for $325190d. While Celestial Flames is active:\n\n\n\n$@spellicon196730 $@spellname196730:\n\nKegs thrown by Special Delivery are ignited and splash upon landing, dealing $1263667s1 Fire damage to up to 5 nearby enemies.\n\n\n\n$@spellicon116847 $@spellname116847:\n\nRushing Jade Wind becomes a firestorm, increasing its radius by $1263641s2% and causing it to deal Fire damage.", ua = "Коли ви п'єте Напої, є $h% шансу, що вас огорне Небесне полум'я протягом $325190d. Поки Небесне полум'я активне:\n\n\n\n$@spellicon196730 $@spellname196730:\n\nДіжки, кинуті Особливою доставкою, спалахують і розбризкуються при падінні, завдаючи $1263667s1 вогняної шкоди до 5 ворогам поблизу.\n\n\n\n$@spellicon116847 $@spellname116847:\n\nНавальний нефритовий вітер стає вогняною бурею, збільшуючи свій радіус на $1263641s2% і завдаючи вогняної шкоди." },
    { en = "Sprout an additional limb, pulling enemies further than $1263566s3 yds from you every $t1 sec.  \n\n\n\nThe same enemy can only be pulled once every $1263566d.", ua = "Відрощує додаткову кінцівку, що притягує до вас ворогів, віддалених більш ніж на $1263566s3 м, кожні $t1 сек.  \n\n\n\nОдного й того самого ворога можна притягнути лише раз на $1263566d." },
    { en = "When you Ferocious Bite, you have a $s1% chance per combo point spent to flicker to an enemy within $s2 yds and deliver an Unseen Attack. Unseen Attack damage is reduced if less than 5 combo points and ${$22568c+$22568s2} Energy are spent on Ferocious Bite.\n\n\n\n$@spellicon1263827 $@spellname1263827\n\n$@spelldesc1263827\n\n\n\n$@spellicon1263902 $@spellname1263902\n\n$@spelldesc1263902", ua = "Коли ви застосовуєте Лютий укус, ви маєте $s1% шанс за кожне витрачене очко комбо мерехтливо перенестися до ворога в межах $s2 м і завдати Незримої атаки. Шкода Незримої атаки знижується, якщо на Лютий укус витрачено менше 5 очок комбо та ${$22568c+$22568s2} енергії.\n\n\n\n$@spellicon1263827 $@spellname1263827\n\n$@spelldesc1263827\n\n\n\n$@spellicon1263902 $@spellname1263902\n\n$@spelldesc1263902" },
    { en = "Unseen Attacks increase your damage done by $s1% for $1263939d per combo point spend to trigger it. Additional applications extend this effect.", ua = "«Невидимі атаки» збільшують завдану тобою шкоду на $s1% на $1263939d за кожне очко комбо, витрачене на їхню активацію. Повторні застосування подовжують цей ефект." },
    { en = "Tiger's Fury causes you to perform an Unseen Attack for maximum damage after your next $1263962u combo point generating attacks. Rip and Unseen Attack damage increased by $s2%.", ua = "«Лють тигра» змушує тебе виконати «Невидиму атаку» з максимальною шкодою після наступних $1263962u атак, що створюють очки комбо. Шкода «Розриву» та «Невидимої атаки» збільшена на $s2%." },
    { en = "When you cast Dancing Rune Weapon, you become enveloped in a blood mist that surrounds you for $1263729d, increasing your Parry by $1263729s2%. \n\n\n\nDeals $1263752s1 Shadow damage every $1263729t1 sec to enemies within $1263752A1 yds. Every time it deals damage you gain ${$1263774s1/10} Runic Power, up to a maximum of ${$1263774s1/10*$1263729s3} Runic Power. Deals reduced damage beyond $1263729s4 targets.", ua = "Коли ви творите Танець рунічної зброї, вас огортає кривавий туман на $1263729d, збільшуючи ваше Парирування на $1263729s2%. \n\n\n\nЗавдає $1263752s1 шкоди тінню кожні $1263729t1 сек. ворогам у межах $1263752A1 м. Щоразу, коли він завдає шкоди, ви отримуєте ${$1263774s1/10} Рунічної сили, до максимуму ${$1263774s1/10*$1263729s3} Рунічної сили. Завдає зменшеної шкоди понад $1263729s4 цілей." },
    { en = "When Blood Mist ends it deals $1263786s1 Shadow damage to $1263786i nearby enemies, healing you for ${$1263786e*100}% of the damage dealt. The damage is increased by $1263789s1% for every $s1 Runic Power spent while Blood Mist was active.", ua = "Коли Кривавий туман завершується, він завдає $1263786s1 шкоди Темрявою $1263786i ворогам поблизу, зцілюючи вас на ${$1263786e*100}% завданої шкоди. Шкода збільшується на $1263789s1% за кожні $s1 рунічної сили, витраченої, поки Кривавий туман був активний." },
    { en = "$?c3[You have a $s1% chance to gain Blessing of An'she and generate $s2 Holy Power after casting Avenging Wrath.\n\n\n\nDuring Avenging Wrath, Hammer of Wrath casts Blade of Justice at $s3% effectiveness.][Infusion of Light occurs $s4% more often during Avenging Wrath.]", ua = "$?c3[Ви маєте $s1% шанс отримати Благословення Ан'ше і згенерувати $s2 Святої Сили після прочитання Гніву месника.\n\n\n\nПід час Гніву месника Молот гніву творить Клинок правосуддя з $s3% ефективності.][Влиття Світла трапляється на $s4% частіше під час Гніву месника.]" },
    { en = "$?c1[Dawnlight's duration is increased by ${$s1/1000}.1 sec when it heals an ally with full health.][Dawnlight's duration is increased by ${$s2/1000}.1 sec whenever struck by Divine Storm or Templar's Verdict.\n\n\n\nWhen 2 Dawnlights are struck by Divine Storm, their durations are extended by an additional ${$s3/1000}.1 sec.]", ua = "$?c1[Тривалість Світанкового сяйва збільшується на ${$s1/1000}.1 с, коли воно зцілює союзника з повним здоров'ям.][Тривалість Світанкового сяйва збільшується на ${$s2/1000}.1 с щоразу, коли по ньому влучає Божественна буря або Вирок тамплієра.\n\n\n\nКоли по 2 Світанкових сяйвах влучає Божественна буря, їхня тривалість продовжується ще на ${$s3/1000}.1 с.]" },
    { en = "Empower the runes in your weapon, reducing the damage you take over the duration and unleashing a devastating attack that deals $1263825s1 Shadow damage and consumes up to $s4% of your Blood Plague instantly from enemies in front of you.\n\n\n\n|cFFFFFFFFI:|r Consumes up to $s2% of your Blood Plague. While empowering, your damage taken is reduced by $s5% and an additional ${$s8/1000} sec after empowering.\n\n\n\n|cFFFFFFFFII:|r Consumes up to $s3% of your Blood Plague. While empowering, your damage taken is reduced by $s6% and an additional ${$s9/1000} sec after empowering.\n\n\n\n|cFFFFFFFFIII:|r Consumes up to $s4% of your Blood Plague. While empowering, your damage taken is reduced by $s7% and an additional ${$s10/1000} sec after empowering.", ua = "Підсилює руни у вашій зброї, зменшуючи зазнану вами шкоду протягом дії та вивільняючи нищівну атаку, що завдає $1263825s1 шкоди тінню й миттєво споживає до $s4% вашої Кривавої пошесті з ворогів перед вами.\n\n\n\n|cFFFFFFFFI:|r Споживає до $s2% вашої Кривавої пошесті. Під час підсилення зазнана вами шкода зменшена на $s5% і ще ${$s8/1000} сек після підсилення.\n\n\n\n|cFFFFFFFFII:|r Споживає до $s3% вашої Кривавої пошесті. Під час підсилення зазнана вами шкода зменшена на $s6% і ще ${$s9/1000} сек після підсилення.\n\n\n\n|cFFFFFFFFIII:|r Споживає до $s4% вашої Кривавої пошесті. Під час підсилення зазнана вами шкода зменшена на $s7% і ще ${$s10/1000} сек після підсилення." },
    { en = "Regrowth heals all other allies with Regrowth for $s1% of its healing.", ua = "«Відростання» зцілює всіх інших союзників, на яких діє «Відростання», на $s1% свого зцілення." },
    { en = "Dawnlight's critical strike chance is increased by $1264050s1% during Avenging Wrath.", ua = "Під час «Гніву месника» шанс критичного удару «Світла світанку» збільшено на $1264050s1%." },
    { en = "The cooldown of your Felguard's Felstorm is reduced by ${$1263938s1/-1000} sec and damage dealt to your primary demon is reduced by $1263938s2%.", ua = "Перезарядження «Бурі Скверни» твого вартового Скверни скорочено на ${$1263938s1/-1000} сек., а шкода, завдавана твоєму основному демону, зменшена на $1263938s2%." },
    { en = "When your Wild Imps cast Fel Firebolt, they have $s1% chance to instantly cast another Fel Firebolt at $s2% effectiveness.", ua = "Коли твої дикі біси читають «Вогняну стрілу Скверни», вони мають $s1% шансу миттєво випустити ще одну «Вогняну стрілу Скверни» з $s2% ефективності." },
    { en = "When an effect from an Idol is activated, conjure Shadowy Apparitions.", ua = "Коли активується ефект Ідола, створює тіньові привиддя." },
    { en = "Shadowy Apparitions have a $s2% chance to spawn as Void Apparitions that release a $@spellname1264177 at their target and deal $s1% increased damage.\n\n\n\n$@spellicon1264177 $@spellname1264177\n\n$@spelldesc1264177", ua = "Тіньові привиддя мають $s2% шанс з'явитися як Привиддя Порожнечі, що випускають $@spellname1264177 по своїй цілі та завдають на $s1% більше шкоди.\n\n\n\n$@spellicon1264177 $@spellname1264177\n\n$@spelldesc1264177" },
    { en = "Tentacle Slam has a $s1% chance to activate an effect from one of your Idols.\n\n\n\n$@spellicon373310 $@spellname373310\n\nSummons a Shadowfiend.\n\n\n\n$@spellicon373280 $@spellname373280\n\nYour target witnesses a nightmare or vision of N'Zoth.\n\n\n\n$@spellicon373273 $@spellname373273\n\nSummons a Thing From Beyond.\n\n\n\n$@spellicon377349 $@spellname377349\n\nSummons a Void Tendril or Void Lasher.", ua = "Удар щупальцем має $s1% шанс активувати ефект одного з ваших Ідолів.\n\n\n\n$@spellicon373310 $@spellname373310\n\nПрикликає Тіньового біса.\n\n\n\n$@spellicon373280 $@spellname373280\n\nВаша ціль зазнає жахіття чи видіння Н'Зота.\n\n\n\n$@spellicon373273 $@spellname373273\n\nПрикликає Створіння з Потойбіччя.\n\n\n\n$@spellicon377349 $@spellname377349\n\nПрикликає Щупальце Порожнечі або Шмагача Порожнечі." },
    { en = "Death Strike hits an additional $s1 enemies at ${$49998f1*100}% effectiveness.", ua = "«Удар смерті» вражає $s1 додаткових ворогів з ефективністю ${$49998f1*100}%." },
    { en = "$?c1[Fire Breath gains][Dream Breath and Fire Breath gain] an additional charge.", ua = "$?c1[«Вогняний подих» отримує][«Подих мрій» і «Вогняний подих» отримують] додатковий заряд." },
    { en = "$?c1[When summoning a Dire Beast, you have a $s1% chance to instead summon a Dark Hound that deals significantly increased damage.][Black Arrow's periodic damage has a small chance to rouse the dead, summoning a Dark Minion to fight alongside you for $1264345d.]", ua = "$?c1[Прикликаючи Лютого звіра, ви маєте $s1% шанс натомість прикликати темного гончака, що завдає значно більшої шкоди.][Періодична шкода «Чорної стріли» має малий шанс підняти мертвих, прикликаючи темного слугу битися поряд із вами протягом $1264345d.]" },
    { en = "$?c1[Bestial Wrath][Trueshot] summons a $?c1[Dark Hound][Dark Minion].\n\n\n\nFor $459808d after casting $?c1[Bestial Wrath][Trueshot], $?c1[Bestial Wrath][Trueshot] is replaced with Wailing Arrow.\n\n\n\n$@spellicon392060 $@spellname392060\n\n$@spelldesc392060", ua = "$?c1[Звіриний гнів][Влучний постріл] прикликає $?c1[Темного хорта][Темного посіпаку].\n\n\n\nПротягом $459808d після застосування $?c1[Звіриного гніву][Влучного пострілу] $?c1[Звіриний гнів][Влучний постріл] замінюється Тужливою стрілою.\n\n\n\n$@spellicon392060 $@spellname392060\n\n$@spelldesc392060" },
    { en = "You fire $s1 additional Black Arrows during Withering Fire's barrage.\n\n\n\n$?a137016[Trick Shots damage bonus increased by $s3%. Aspect of the Hydra's damage bonus increased by $s4%][Beast Cleave and Kill Cleave damage increased by $s5%].", ua = "Ви випускаєте $s1 додаткових Чорних стріл під час шквалу Згубного вогню.\n\n\n\n$?a137016[Бонус шкоди Хитрих пострілів збільшено на $s3%. Бонус шкоди Аспекту гідри збільшено на $s4%][Шкода Звіриного розрубу та Смертельного розрубу збільшена на $s5%]." },
    { en = "Death Strike heals for an additional $s1% of its healing over $1264304d.", ua = "«Удар смерті» додатково зцілює на $s1% свого зцілення протягом $1264304d." },
    { en = "Fire Breath's damage over time lasts $s1 sec longer.$?c2[\n\n\n\nDream Breath's heal over time lasts ${$s2/1000} sec longer.][]", ua = "Періодична шкода Вогняного подиху триває на $s1 сек. довше.$?c2[\n\n\n\nПеріодичне зцілення Подиху сну триває на ${$s2/1000} сек. довше.][]" },
    { en = "You focus on the target struck by your Devastator, dealing $1277983s1% additional Revenge damage to them.\n\n\n\nOnly one target can have your focus at a time.", ua = "Ви зосереджуєтеся на цілі, яку вразив ваш Спустошувач, завдаючи їй на $1277983s1% більше шкоди від Помсти.\n\n\n\nВи можете зосередитися лише на одній цілі водночас." },
    { en = "When you consume a Rune you have a chance to call a Dancing Rune Weapon to your aid for $1264353d.", ua = "Коли ти витрачаєш руну, є шанс прикликати собі на допомогу «Танцівливу рунну зброю» на $1264353d." },
    { en = "Command your pet to thrash all enemies within $1264355A1 yds, dealing $1264355s1 Physical damage to them. Damage is increased by $s1% if Wild Thrash hits $s2 or more $L enemy:enemies;.\n\n\n\nDeals reduced damage beyond $1264355s2 $Ltarget:targets;.", ua = "Наказуєш улюбленцеві молотити всіх ворогів у межах $1264355A1 м, завдаючи їм $1264355s1 фізичної шкоди. Шкода підвищується на $s1%, якщо Дике молотіння влучає в $s2 або більше $L ворога:ворогів:ворогів;.\n\n\n\nЗавдає зменшеної шкоди понад $1264355s2 $Lціль:цілі:цілей;." },
    { en = "Fire Breath's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Вогняного подиху скорочено на ${$s1/-1000} сек." },
    { en = "Direct damage from Fire Breath consumes absorb shields from enemies, dealing $1264379s1 additional Spellfrost damage to them.", ua = "Пряма шкода Вогняного подиху поглинає захисні щити ворогів, завдаючи їм $1264379s1 додаткової шкоди магічним морозом." },
    { en = "For each Dancing Rune Weapon active your damage is increased by $s1% and your damage taken is reduced by $s4%.", ua = "За кожну активну Танцівну рунічну зброю твоя шкода збільшена на $s1%, а отримувана шкода зменшена на $s4%." },
    { en = "While Dancing Rune Weapon is active, Parrying an attack has a chance to make your next Heart Strike cost no Runes and deal 150% increased damage.", ua = "Поки діє «Танцівлива рунна зброя», парирування атаки дає шанс, що твій наступний «Удар у серце» не коштуватиме рун і завдасть на 150% більше шкоди." },
    { en = "$?c1[Entering an Eclipse summons a Dryad to assist you for $1264618d, casting Starsurge dealing $1264677s1 Astral damage and Starfall at $s2% effectiveness.][Your periodic heals have a chance to empower your next Swiftmend to summon a Dryad to assist you, casting Tranquility at $s1% effectiveness and Regrowth to heal $1264664s1 damage onto your lowest health ally.]", ua = "$?c1[Входження в Затемнення призиває дріаду, що допомагає тобі протягом $1264618d, читаючи Зоряний сплеск, який завдає $1264677s1 астральної шкоди, та Зорепад з $s2% ефективності.][Твої періодичні зцілення мають шанс підсилити твоє наступне Швидке зцілення: воно призве дріаду, яка допомагатиме тобі, читаючи Спокій з $s1% ефективності та Відростання, що відновлює $1264664s1 здоров'я союзникові з найменшим запасом здоров'я.]" },
    { en = "When Regrowth critically heals, it is ${$s1+200}% effective instead of the usual 200%.", ua = "Коли «Відростання» зцілює критично, його ефективність становить ${$s1+200}% замість звичайних 200%." },
    { en = "$?c1[Casting ][]Ascendance upgrades your next Lightning Bolt to Tempest.", ua = "$?c1[Творення ][]«Піднесення» покращує вашу наступну «Блискавку» до «Бурі»." },
    { en = "$?c1[Kill Command causes your Dark Hound to Shadow Thrash, dealing $1264485s1 Shadow damage to up to $s2 nearby enemies][Aimed Shot causes your Dark Minion to fire a Blighted Arrow, dealing $1264364s1 Shadow damage to up to $s1 nearby enemies].", ua = "$?c1[«Наказ убити» змушує вашого темного гончака завдати «Тіньового шмагання», завдаючи $1264485s1 шкоди темрявою до $s2 ворогам поблизу][«Прицільний постріл» змушує вашого темного слугу випустити Згубну стрілу, завдаючи $1264364s1 шкоди темрявою до $s1 ворогам поблизу]." },
    { en = "Nature damage is increased by $s1%", ua = "Шкоду від сил природи збільшено на $s1%" },
    { en = "$?c1[Storm Elemental lasts ${$s1/1000} sec longer, and Stormkeeper generates $s2 Maelstrom.][Windfury Weapon damage increased by $s3%.\n\n\n\nWhen Crash Lightning hits a single enemy, it activates Windfury Weapon.]", ua = "$?c1[«Грозовий елементаль» триває на ${$s1/1000} сек. довше, а «Хранитель бурі» генерує $s2 Виру.][Шкода «Зброї вітрової люті» зросла на $s3%.\n\n\n\nКоли «Розряд блискавки» влучає в одного ворога, він активує «Зброю вітрової люті».]" },
    { en = "Shuriken Storm has a $s1% chance to create a Shadow Clone that repeats the attack for $s2% of normal damage as Shadow.", ua = "Буря сюрикенів має $s1% шансу створити тіньового клона, який повторює атаку, завдаючи $s2% звичайної шкоди тінню." },
    { en = "Your mastery is increased by $s1%.$?c3[\n\n\n\nWildfire Bomb deals an additional $s2% increased damage to its primary target.][]", ua = "Ваша майстерність збільшена на $s1%.$?c3[\n\n\n\nЗапальна бомба завдає основній цілі додатково на $s2% більше шкоди.][]" },
    { en = "$?c4[Dryads cause Swiftmend to cool down $1264618s3% faster.][Dryads cause most of your Astral power generation to be increased by $1264618s4%.]", ua = "$?c4[Дріади змушують «Швидке зцілення» перезаряджатися на $1264618s3% швидше.][Дріади збільшують генерацію астральної сили з більшості джерел на $1264618s4%.]" },
    { en = "Your $?c1[auto shot][auto attacks] grant$?c1[s][] $1264783s1 Focus to you and your pet.\n\n\n\n$?c1[Auto shot][Auto attack] damage increased by $?c1[$s2][$s3]%.", ua = "$?c1[Ваш автопостріл][Ваші автоатаки] $?c1[надає][надають] $1264783s1 од. зосередження вам і вашому улюбленцю.\n\n\n\nШкода $?c1[автопострілу][автоатак] збільшена на $?c1[$s2][$s3]%." },
    { en = "The damage bonus from your Wyvern now lasts an additional ${$s2/1000}.1 sec.", ua = "Бонус до шкоди від твоєї віверни тепер триває на ${$s2/1000}.1 сек. довше." },
    { en = "$?c1[Hogstrider further increases the damage of Cobra Shot by $s1% and it now strikes up to $s3 additional targets][Hogstrider further increases the damage of Boomstick by $s2%].", ua = "$?c1[Вепроступ додатково підвищує шкоду від «Кобрового пострілу» на $s1%, і він тепер вражає до $s3 додаткових цілей][Вепроступ додатково підвищує шкоду від «Бабахалки» на $s2%]." },
    { en = "$?c4[Ironbark summons a Dryad to channel a beam of pure nature onto your target, healing them for $1264905o1 over $1264905d.][Your Starfall damage is increased by $s1% and your Starsurge damage is increased by $s2%.]", ua = "$?c4[«Залізна кора» прикликає дріаду, що спрямовує промінь чистої природи на твою ціль, зцілюючи її на $1264905o1 протягом $1264905d.][Шкоду твого «Зорепаду» збільшено на $s1%, а шкоду «Зоряного сплеску» — на $s2%.]" },
    { en = "For $1264946d after casting $?c2[Trueshot][Takedown], $?c2[Trueshot][Takedown] is replaced with Moonlight Chakram.\n\n\n\n$@spellicon1264949 $@spellname1264949\n\n$@spelldesc1264949", ua = "Протягом $1264946d після застосування $?c2[Несхибного пострілу][Повалення] $?c2[Несхибний постріл][Повалення] замінюється Чакрамом місячного сяйва.\n\n\n\n$@spellicon1264949 $@spellname1264949\n\n$@spelldesc1264949" },
    { en = "Your Moonlight Chakram deals $1264949s3% increased damage each time it bounces.", ua = "Твій «Чакрам місячного світла» завдає на $1264949s3% більше шкоди з кожним відскоком." },
    { en = "When your Moonlight Chakram expires, it summons an explosion of moonlight, dealing $1266096s1 Arcane damage to nearby enemies. Damage reduced beyond $s1 targets.", ua = "Коли дія твого «Чакрама місячного світла» завершується, він викликає вибух місячного світла, що завдає $1266096s1 арканної шкоди ворогам поблизу. Шкода зменшується, якщо цілей більше за $s1." },
    { en = "Increases the attack speed of your active pets by $s1%.", ua = "Збільшує швидкість атаки твоїх активних улюбленців на $s1%." },
    { en = "All bleed damage dealt by you and your pets  increased by $s1%.", ua = "Уся шкода від кровотечі, яку завдаєш ти і твої улюбленці, збільшена на $s1%." },
    { en = "Barbed Shot critical strike chance increased by $s1%.\n\n\n\nCobra Shot critical strike chance increased by $s2%.", ua = "Шанс критичного удару Шипастого пострілу збільшується на $s1%.\n\n\n\nШанс критичного удару Пострілу кобри збільшується на $s2%." },
    { en = "Summoning a Dire Beast grants ${$s1/10}.2% haste for $1282747d.", ua = "Виклик лютого звіра дає ${$s1/10}.2% поспіху на $1282747d." },
    { en = "Drinking a Brew has a $H% chance to leave you with an Empty Barrel, which is tossed along with your next Keg Smash to deal $1265133s1 Physical damage to your target. Ricochets up to $1265133x1 times at ${$1265133f1*100}% effectiveness.", ua = "Випивання вариву з імовірністю $H% залишає вам Порожнє барило, яке метається разом із наступним Ударом барилом, завдаючи $1265133s1 фізичної шкоди вашій цілі. Рикошетить до $1265133x1 разів з ефективністю ${$1265133f1*100}%." },
    { en = "Gaining an Empty Barrel resets the cooldown of Keg Smash and makes its next cast cost $s2% less energy. \n\n\n\nPhysical damage dealt increased by $s1%.", ua = "Отримання Порожнього барила скидає перезарядження Удару барилом і робить наступне його прочитання на $s2% дешевшим за енергією. \n\n\n\nЗавдана фізична шкода збільшується на $s1%." },
    { en = "When you cast Fortifying Brew or $?s1241059[Celestial Infusion][Celestial Brew] you tap a fresh keg, granting yourself and $s1 nearby $Lally:allies; a refreshing drink, and leaving you with an Empty Barrel.\n\n\n\nEmpty Barrels deal $s2% increased damage.\n\n\n\n$@spellicon1265140 $@spellname1265140:\n\n$@spelldesc1265140", ua = "Коли ти твориш Зміцнювальне варево чи $?s1241059[Небесне вливання][Небесне варево], ти відкорковуєш свіже барило, даючи собі та $s1 $Lally:allies; поблизу освіжний напій і лишаючи собі Порожню бочку.\n\n\n\nПорожні бочки завдають на $s2% більше шкоди.\n\n\n\n$@spellicon1265140 $@spellname1265140:\n\n$@spelldesc1265140" },
    { en = "Rampage increases the damage of your next Bloodthirst by $1265399s1%, stacking up to $1265399u times.", ua = "«Буйство» збільшує шкоду твоєї наступної «Спраги крові» на $1265399s1%, накопичуючись до $1265399u разів." },
    { en = "Bloodthirst critical strikes restore $1283442s1% additional health and increase the damage of Raging Blow by $1265403s1% for $1265403d.", ua = "Критичні удари Кровожерності відновлюють додатково $1283442s1% здоров'я та збільшують шкоду Лютого удару на $1265403s1% на $1265403d." },
    { en = "While Improved Whirlwind is active Rampage instead strikes all targets in front of you for ${$1265579s1+$1265580s1+$1265581s1+$1265582s1} Physical damage. Deals reduced damage beyond $s1 targets.", ua = "Поки активний «Покращений вихор», «Буйство» натомість вражає всі цілі перед тобою, завдаючи ${$1265579s1+$1265580s1+$1265581s1+$1265582s1} фізичної шкоди. Завдає менше шкоди понад $s1 цілей." },
    { en = "When Raging Blow resets its own cooldown, your auto-attack damage and speed is increased by $1265560s1% for $1265560d.", ua = "Коли «Лютий удар» скидає власне перезарядження, шкода та швидкість твоїх автоатак збільшуються на $1265560s1% на $1265560d." },
    { en = "When you would sustain fatal damage, you instead fly into an unstoppable rage, becoming unkillable and immune to movement-impairing effects for $1265600d as you seek revenge on your would-be killer.\n\n\n\nIf you kill your killer in that time, you emerge from your blind rage triumphant, with at least $1265600s5% of your max health intact. If you are not victorious, you die.\n\n\n\nThis effect can only occur once every $1265598d and if your killer is alive when you sustain fatal damage.", ua = "Коли ти мав би отримати смертельну шкоду, ти натомість впадаєш у нестримну лють, стаючи невбивним і невразливим до ефектів, що уповільнюють пересування, на $1265600d, поки шукаєш помсти своєму майбутньому вбивці.\n\n\n\nЯкщо ти вб'єш свого вбивцю за цей час, ти виходиш зі сліпої люті переможцем, маючи щонайменше $1265600s5% максимального здоров'я. Якщо ти не переможеш, ти гинеш.\n\n\n\nЦей ефект може спрацьовувати лише раз на $1265598d і лише якщо твій убивця живий, коли ти отримуєш смертельну шкоду." },
    { en = "Nothing will save your target from you. Envenom damage increased by $s3%. When your Envenom bonus expires, gain $s1% increased Energy generation for $1265391d. \n\n\n\nGain an additional $s2% increased Energy generation for each Envenom you used while Envenom's bonus was active, up to ${$s1+4*$s2}% total.", ua = "Ніщо не врятує вашу ціль від вас. Шкода «Отруєння» збільшена на $s3%. Коли бонус «Отруєння» закінчується, отримуєте на $s1% більшу генерацію Енергії протягом $1265391d. \n\n\n\nОтримуєте додатково на $s2% більшу генерацію Енергії за кожне «Отруєння», застосоване, доки бонус «Отруєння» був активний, але не більш ніж ${$s1+4*$s2}% загалом." },
    { en = "Your Nature and Bleed ability damage is increased by $s1%.", ua = "Шкода твоїх здібностей природи та кровотечі збільшена на $s1%." },
    { en = "After striking with Kingsbane, rapidly strike that target $1265787s1 times over $1265787d for $1265795s1 Physical and $1265794s1 Nature damage. Each strike applies the Lethal Poisons on your weapons and generates a combo point.", ua = "Після удару Згубою королів швидко завдає цій цілі $1265787s1 ударів протягом $1265787d, що наносять $1265795s1 фізичної шкоди та $1265794s1 шкоди від сил природи. Кожен удар накладає смертельні отрути з твоєї зброї та генерує очко комбо." },
    { en = "The cooldown of Ice Block and Ice Cold are reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Крижаної брили» та «Крижаного холоду» зменшено на ${-$s1/1000} сек." },
    { en = "Fear duration on you reduced by $s3%. This effect is increased to $s2% during Avenging Wrath.", ua = "Тривалість ефектів страху на тобі зменшено на $s3%. Під час «Гніву месника» цей ефект зростає до $s2%." },
    { en = "Essence of the Blood Queen additionally increases your Mastery by $?c3[${$s1/10}.1][${$s3/10}.1]% per stack.\n\n\n\n$?c3[Dread Plague deals $s5% and Virulent Plague deals $s3%][Blood Plague deals $s4%] increased damage.", ua = "Есенція Кривавої Королеви додатково збільшує вашу Майстерність на $?c3[${$s1/10}.1][${$s3/10}.1]% за стак.\n\n\n\n$?c3[Жахна пошесть завдає на $s5%, а Згубна пошесть на $s3%][Кров'яна пошесть завдає на $s4%] більше шкоди." },
    { en = "Killing an enemy that yields experience or honor causes you to explode with holy energy, healing up to $s1 nearby allies and yourself for $1265595s1, split evenly among them.", ua = "Коли вбиваєш ворога, що дає досвід або честь, ти вибухаєш святою енергією, зцілюючи до $s1 союзників поблизу й себе на $1265595s1, розділені порівну між усіма." },
    { en = "Execute generates ${$s1/10} additional Rage and increases the damage of Rampage by $1265575s1% for $1265575d.", ua = "Страта генерує ${$s1/10} додаткової люті та збільшує шкоду Буйства на $1265575s1% на $1265575d." },
    { en = "Vampiric Strike increases the damage of $?c3[the Lesser Ghoul it summons][your Dancing Rune Weapons] by $?c3[$1280386s1%.][$1236822s3% for $1236822d. \n\n\n\nMultiple applications may overlap.]", ua = "Вампірський удар збільшує шкоду $?c3[нижчого вампіра, якого він прикликає][ваших танцюючих рунічних зброй] на $?c3[$1280386s1%.][$1236822s3% протягом $1236822d. \n\n\n\nКілька застосувань можуть накладатися.]" },
    { en = "Frostwyrm's Fury deals $s1% increased damage to the first enemy it hits and grants you $1265630s1% Haste for $1265630d.", ua = "Лють морозного вирма завдає на $s1% більше шкоди першому враженому ворогові та дає тобі $1265630s1% поспіху на $1265630d." },
    { en = "Frostwyrm's Fury extends the duration of an active Pillar of Frost by ${$s1/1000}.1 sec.\n\n\n\nEnduring Strength grants an additional $s2% Strength.", ua = "Лють морозного змія продовжує тривалість активного Стовпа морозу на ${$s1/1000}.1 сек.\n\n\n\nНезламна сила надає додатково $s2% Сили." },
    { en = "All Frost damage increased by $s3%.\n\n\n\nFrostwyrm's Fury deals $s1% increased damage. After the Frostwyrm flies away, you may cast Frostwyrm's Fury again to recall it at $s2% effectiveness.", ua = "Уся шкода морозом збільшена на $s3%.\n\n\n\nЛють морозного змія завдає на $s1% більше шкоди. Після того як морозний змій відлітає, ви можете знову застосувати Лють морозного змія, щоб прикликати його з $s2% ефективністю." },
    { en = "Casting Incinerate has a chance to evoke an echo of the Dark Titan's power.\n\n\n\n$@spellicon1265884 $@spellname1265884\n\n$@spelldesc1265884", ua = "Творення Спопелення має шанс викликати відлуння сили Темного Титана.\n\n\n\n$@spellicon1265884 $@spellname1265884\n\n$@spelldesc1265884" },
    { en = "Memories of the Titans' destruction flash in your mind when you evoke the Dark Titan's power, increasing critical strike by $s2% and haste by $s1% for $1265939d.", ua = "Спогади про знищення титанів спалахують у твоїй свідомості, коли ти прикликаєш силу Темного Титана, збільшуючи критичний удар на $s2%, а поспіх — на $s1% на $1265939d." },
    { en = "Casting Chaos Bolt, Shadowburn, or Rain of Fire evokes an echo of the Dark Titan's power at $s1%, $s2%, or $s3% effectiveness respectively.\n\n\n\nIf no target is found, a random target suffering from your $?a445465[Wither][Immolate] will be selected.", ua = "Творення Снаряда хаосу, Тіньового спалаху чи Вогняного дощу викликає відлуння сили Темного Титана з $s1%, $s2% або $s3% дієвості відповідно.\n\n\n\nЯкщо ціль не знайдено, буде обрано випадкову ціль, що потерпає від вашого $?a445465[Усихання][Спопеляння]." },
    { en = "Heart Strike has a chance to make your next Blood Boil empowered, dealing $1265968s1% increased damage and echoing after $s1 sec.", ua = "Удар у серце має шанс посилити твоє наступне Кипіння крові: воно завдасть на $1265968s1% більше шкоди й відлунить через $s1 сек." },
    { en = "Call forth a cloud of cloying shadow mist that envelopes the target and all enemies within $1271803a1 yds, increasing the time between their attacks by $1271798s1% and reducing their critical strike chance by $1271798s2% for $1271798d.\n\n\n\n|cFF8282FFCurses: A warlock can only have one Curse or Blight active per target.|r", ua = "Прикликає хмару задушливого тіньового туману, що огортає ціль і всіх ворогів у межах $1271803a1 м, збільшуючи час між їхніми атаками на $1271798s1% та знижуючи їхній шанс критичного удару на $1271798s2% протягом $1271798d.\n\n\n\n|cFF8282FFПрокляття: чорнокнижник може мати активним лише одне Прокляття або Пошесть на ціль.|r" },
    { en = "Physical damage increased by $s1%.", ua = "Фізична шкода збільшена на $s1%." },
    { en = "Reduces the cast time of Demonic Gateway by ${$s1/-1000}.1 sec and you can now use Demonic Gateways twice before triggering a cooldown.", ua = "Зменшує час творення «Демонічної брами» на ${$s1/-1000}.1 сек., і тепер ти можеш скористатися демонічними брамами двічі, перш ніж почнеться перезарядження." },
    { en = "Eternity Surge additionally releases a Shattering Star at your target that deals $s1% more damage per empower level reached.\n\n\n\n$@spellicon1265804 $@spellname1265804\n\n$@spelldesc1265804", ua = "Сплеск вічності додатково випускає Нищівну зорю в вашу ціль, що завдає на $s1% більше шкоди за кожен досягнутий рівень посилення.\n\n\n\n$@spellicon1265804 $@spellname1265804\n\n$@spelldesc1265804" },
    { en = "Healing done by Drain Life also heals your primary demon at $s1% effectiveness.", ua = "Зцілення від «Висмоктування життя» також зцілює твого основного демона з ефективністю $s1%." },
    { en = "Casting Curse of Exhaustion, Curse of Tongues, or $?a440057[Curse of the Satyr][Curse of Weakness] now curses all enemies within $s1 yds of the target.", ua = "Творення Прокляття виснаження, Прокляття мов чи $?a440057[Прокляття сатира][Прокляття слабкості] тепер проклинає всіх ворогів у межах $s1 ярдів від цілі." },
    { en = "Increases the range of Mortal Coil by $s1 yds and Mortal Coil now heals for an additional $s2% of maximum health.", ua = "Збільшує дальність Тлінної оболонки на $s1 м, а Тлінна оболонка тепер зцілює додатково на $s2% максимального здоров'я." },
    { en = "Metamorphosis has ${$s1/1000} sec increased duration and increases the damage of Fracture, Soul Cleave, and Spirit Bomb by $s2%.", ua = "Тривалість «Метаморфози» збільшено на ${$s1/1000} сек., а шкода «Перелому», «Розсічення душ» і «Духовної бомби» збільшена на $s2%." },
    { en = "Increases Shattering Star damage by $s1%.\n\n\n\nShattering Stars are exhaled at all of your Eternity Surge targets.", ua = "Збільшує шкоду Розколювальної зорі на $s1%.\n\n\n\nРозколювальні зорі видихаються на всі цілі вашого Сплеску вічності." },
    { en = "Reaper's Mark deals $s7% increased damage.\n\n\n\nCasting $?c1?[Dancing Rune Weapon][Reaper's Mark] grants $?c1?[$s4][$s1] $Lstack:stacks; of Exterminate with $?c1?[$s5][$s2]% first scythe and $?c1?[$s6][$s3]% second scythe effectiveness.", ua = "Мітка женця завдає на $s7% більше шкоди.\n\n\n\nЗастосування $?c1?[Танцюючої рунічної зброї][Мітки женця] надає $?c1?[$s4][$s1] $Lстак:стаки; Винищення з $?c1?[$s5][$s2]% ефективністю першої коси та $?c1?[$s6][$s3]% ефективністю другої коси." },
    { en = "The effectiveness of Permafrost is increased by $?c1[$s1][$s2]%$?c1[ and Exterminate grants Permafrost equal to $s3% of the damage dealt.]?c2[.][]\n\n\n\n$@spellicon207200$@spellname207200\n\n$@spelldesc207200", ua = "Ефективність Вічної мерзлоти збільшена на $?c1[$s1][$s2]%$?c1[, а Винищення надає Вічну мерзлоту в розмірі $s3% завданої шкоди.]?c2[.][]\n\n\n\n$@spellicon207200$@spellname207200\n\n$@spelldesc207200" },
    { en = "Between the Eyes has a $s1% chance to apply 2 stacks of its bonus to your damage dealt.", ua = "«Межи очі» має $s1% шансу накласти 2 заряди свого бонусу до завданої тобою шкоди." },
    { en = "When you spend $s1 or more combo points on Dispatch, immediately strike your target with an underhanded Scoundrel Strike for $s3 Physical damage.", ua = "Коли ти витрачаєш $s1 або більше очок комбо на Розправу, ти миттєво б'єш ціль підступним Ударом пройдисвіта, завдаючи $s3 фізичної шкоди." },
    { en = "When you Dispatch you have a $s1% chance per combo point spent to hide a bullet up your sleeve. When you've hidden $s2 bullets, your next Between the Eyes consumes them and costs no Energy, generates $1279356s1 combo points, and immediately resets its own cooldown.", ua = "Коли ти використовуєш Розправу, маєш $s1% шансу за кожне витрачене очко комбо сховати кулю в рукаві. Коли сховаєш $s2 куль, твій наступний «Межи очі» споживає їх: не коштує енергії, генерує $1279356s1 очок комбо й миттєво скидає власне перезарядження." },
    { en = "Eternity Surge upgrades your next Azure Strike to Azure Sweep, damaging all nearby enemies and dealing $1265871s2% additional damage.\n\n\n\n$@spellicon1265872 $@spellname1265872\n\n$@spelldesc1265872", ua = "Сплеск вічності підвищує ваш наступний Лазуровий удар до Лазурового помаху, завдаючи шкоди всім ворогам поруч і додаткових $1265871s2% шкоди.\n\n\n\n$@spellicon1265872 $@spellname1265872\n\n$@spelldesc1265872" },
    { en = "Your Blood Plague critical hits have a chance to reduce the cooldown of your Blood Boil by ${$s1/-1000}.2 sec.", ua = "Критичні удари твоєї «Кривавої чуми» мають шанс скоротити перезарядження «Кипіння крові» на ${$s1/-1000}.2 сек." },
    { en = "Spirit Bomb shields you for $263648d, absorbing ${$MHP*$s1/100} damage plus ${$MHP*$s2/100} for each Soul Fragment consumed.", ua = "«Духовна бомба» вкриває тебе щитом на $263648d, що поглинає ${$MHP*$s1/100} шкоди плюс ${$MHP*$s2/100} за кожен поглинутий фрагмент душі." },
    { en = "$?c2[Frost Strike damage is increased by $s1% and Glacial Advance damage is increased by $s2%.\n\n\n\nReaper's Mark grants $s4 charges of Bonegrinder if it is known.]?c1[Death Strike damage increased by $s3%.][]", ua = "$?c2[Шкода від Морозного удару збільшена на $s1%, а шкода від Льодовикового наступу збільшена на $s2%.\n\n\n\nМітка женця надає $s4 заряди Костомолки, якщо її вивчено.]?c1[Шкода від Удару смерті збільшена на $s3%.][]" },
    { en = "$?c2[Casting Obliterate or Frostscythe orders Trollbane to cast his Obliterate or Frostscythe alongside you at $s1% effectiveness.][Casting Death Coil or Epidemic orders Whitemane to cast her Death Coil or Epidemic alongside you at $s2% effectiveness.]", ua = "$?c2[Прочитання Знищення чи Морозної коси наказує Троллбейну також прочитати своє Знищення чи Морозну косу разом з вами з $s1% ефективністю.][Прочитання Смертельної змійки чи Епідемії наказує Вайтмейн також прочитати свою Смертельну змійку чи Епідемію разом з вами з $s2% ефективністю.]" },
    { en = "Black Powder deals increased damage equal to $s1% of your Mastery when it spends $s2 or more combo points.", ua = "«Чорний порох» завдає додаткову шкоду в розмірі $s1% твоєї майстерності, коли витрачає $s2 або більше очок комбо." },
    { en = "$?c2[Pillar of Frost summons forth Trollbane for $s1 sec.][Dark Transformation summons forth Whitemane for $s2 sec.]", ua = "$?c2[Стовп морозу прикликає Троллбейна на $s1 с.][Темне перетворення прикликає Вайтмейн на $s2 с.]" },
    { en = "The abilities that Horsemen cast deal $s1% increased damage.$?c3[\n\n\n\nYour Ghoul and skeletal archer deals $s3% and Lesser Ghouls deal $s5% increased damage][].", ua = "Здібності, що застосовують Вершники, завдають на $s1% більше шкоди.$?c3[\n\n\n\nВаш Вурдалак і кістяний лучник завдають на $s3%, а Менші вурдалаки на $s5% більше шкоди][]." },
    { en = "Consuming Essence Burst fires a twin flame, $?c1[striking your target for $1265980s1 Fire damage][healing your target for $1265991s1].", ua = "Поглинання Сплеску есенції випускає подвійне полум'я, $?c1[завдаючи цілі $1265980s1 шкоди вогнем][зцілюючи вашу ціль на $1265991s1]." },
    { en = "Twin Flame bounces to up to $s1 additional targets.", ua = "Близнюче полум'я перестрибує щонайбільше на $s1 додаткових цілей." },
    { en = "$?c1[Fire Breath has][Dream Breath and Fire Breath have] a $s1% chance to generate Essence Burst.", ua = "$?c1[«Вогняний подих» має][«Подих мрій» і «Вогняний подих» мають] $s1% шанс згенерувати «Сплеск есенції»." },
    { en = "Throwing your Moonlight Chakram $?c2[grants you Lock and Load][reduces the cooldown of Wildfire Bomb by ${$s1/1000} sec].", ua = "Кидок вашого Місячного чакрама $?c2[дарує вам Заряджай і пали][зменшує перезарядження Бомби з диким вогнем на ${$s1/1000} с]." },
    { en = "Deep Breath deals $?a134735[$s1% reduced][$s1% increased] damage and can be cast again within $1266165d of being used.\n\n\n\nRecall will be available after the second cast if talented.", ua = "Глибокий подих завдає $?a134735[на $s1% менше][на $s1% більше] шкоди і може бути застосований знову протягом $1266165d після використання.\n\n\n\nПовернення стане доступним після другого застосування, якщо вивчено талант." },
    { en = "The primary target of $?c3[Void Nova][Chaos Nova] is stunned for an additional ${$s1/1000} sec.", ua = "Основну ціль $?c3[Нови Порожнечі][Нови хаосу] оглушено ще на ${$s1/1000} с." },
    { en = "$?c2[Demon Spikes][Blur] gains $s1 additional $Lcharge:charges;.", ua = "$?c2[Демонічні шипи][Розмиття] отримує $s1 додатковий $Lзаряд:заряди;." },
    { en = "$?c3[Soul Immolation][Immolation Aura] removes $s1 Disease $Leffect:effects;.", ua = "$?c3[Спалення душі][Аура спалення] знімає $s1 $Lефект:ефекти; хвороби." },
    { en = "Attacks and abilities that generate Fury deal $s1% increased damage.", ua = "Атаки та здібності, що генерують лють, завдають на $s1% більше шкоди." },
    { en = "Attacks and abilities that spend Fury deal $s1% increased damage.", ua = "Атаки та здібності, що витрачають лють, завдають на $s1% більше шкоди." },
    { en = "Interrupting a spell with Disrupt decreases your magic damage taken by $1266616s1% for $1266616d.", ua = "Переривання закляття «Зривом» зменшує отриману тобою магічну шкоду на $1266616s1% на $1266616d." },
    { en = "Any time you would generate one or more Soul Fragments, you have a $s1% chance to generate an additional Soul Fragment.", ua = "Щоразу, коли ти маєш створити один чи більше фрагментів душі, є $s1% шанс створити додатковий фрагмент душі." },
    { en = "Glide speed increased by $s1%.", ua = "Швидкість «Ширяння» збільшена на $s1%." },
    { en = "$?c3[Soul Immolation][Immolation Aura] removes $s1 Curse $Leffect:effects;.", ua = "$?c3[Спалення душі][Аура спалення] знімає $s1 $Lефект:ефекти; прокляття." },
    { en = "$?a212612[Fel Rush]?a212613[Infernal Strike][Shift] grants you a rapidly decaying shield equal to $s1% of your maximum health.", ua = "$?a212612[Натиск Скверни]?a212613[Пекельний удар][Зсув] дає вам швидко згасаючий щит, рівний $s1% вашого максимального здоров'я." },
    { en = "Fully channeling $?a212612[Eye Beam]?a212613[Fel Devastation][Void Ray] increases the damage of its final tick by $s1%.", ua = "Повне читання $?a212612[Променя ока]?a212613[Спустошення Скверни][Променя Порожнечі] збільшує шкоду його останнього спрацювання на $s1%." },
    { en = "While no enemies are within $s1 yds, you heal for $1266720s1 every $t1 sec.", ua = "Поки в радіусі $s1 м немає ворогів, ти зцілюєшся на $1266720s1 кожні $t1 сек." },
    { en = "Leg Sweep applies Disable for ${$s1/1000}.1 sec when it ends.", ua = "Коли «Підсічка» завершується, вона накладає «Знерухомлення» на ${$s1/1000}.1 сек." },
    { en = "After casting Enveloping Mist, your next $?s399491[Sheilun's Gift][Vivify] becomes instant cast.", ua = "Після прочитання Огортального туману ваше наступне $?s399491[Сходження Шейлуна][Оживлення] творитиметься миттєво." },
    { en = "After Detox successfully removes an effect from an ally, their movement speed is increased by $1266743s1% for $1266743d.", ua = "Коли «Детокс» успішно знімає ефект із союзника, його швидкість руху збільшується на $1266743s1% на $1266743d." },
    { en = "Vivify and Sheilun's Gift critical strike chances are increased by $s1% on yourself.", ua = "Шанс критичного удару «Оживлення» та «Дару Шейлун» на тобі збільшено на $s1%." },
    { en = "Your movement speed is increased by $s1%.", ua = "Твоя швидкість руху збільшена на $s1%." },
    { en = "Increases the damage of $?a137043[Unstable Affliction by $s1][Chaos Bolt by $s4]% and $?a137043[Seed of Corruption by $s3][Rain of Fire by $s5]%.\n\n\n\nThis effect is doubled while Malevolence is active.", ua = "Збільшує шкоду $?a137043[Нестабільної недуги на $s1][Снаряда хаосу на $s4]% та $?a137043[Зерна зіпсуття на $s3][Вогняного дощу на $s5]%.\n\n\n\nЦей ефект подвоюється, поки активна Злостивість." },
    { en = "Malevolence grants an additional $s1% Haste and when cast increases the stack count of active Withers by an additional $s2 stacks.", ua = "«Зловмисність» дає додаткові $s1% поспіху, а її прочитання збільшує кількість зарядів активних ефектів «В'янення» ще на $s2." },
    { en = "Periodic damage dealt by Wither has a chance to grant Malevolence for $s1 sec.", ua = "Періодична шкода від «В'янення» має шанс дати тобі «Зловмисність» на $s1 сек." },
    { en = "Vivify and Sheilun's Gift trigger a Gust of Mist on yourself.", ua = "«Оживлення» та «Дар Шейлуна» викликають «Порив туману» на тобі." },
    { en = "The cooldown of Death Pact is reduced by ${$s1/-1000} sec, and you receive $s2% increased healing while its healing absorb is active.", ua = "Перезарядження «Пакту смерті» зменшено на ${$s1/-1000} сек., а поки діє його поглинання зцілення, ти отримуєш на $s2% більше зцілення." },
    { en = "Raise Ally costs ${$s1/-10} less Runic Power.", ua = "«Підняття союзника» коштує на ${$s1/-10} менше рунічної сили." },
    { en = "Shadow Word: Pain and Entropic Rift deal damage ${100*(1/(1+$m1/100)-1)}% more often.", ua = "«Слово тіні: Біль» та «Ентропійний розлом» завдають шкоди на ${100*(1/(1+$m1/100)-1)}% частіше." },
    { en = "Voidheart now persists for $s1 sec after Entropic Rift ends.", ua = "«Серце Порожнечі» тепер зберігається протягом $s1 сек. після завершення «Ентропійного розлому»." },
    { en = "$?c3[Void Torrent deals $s1% increased damage.][Mind Blast deals $s2% increased damage.]", ua = "$?c3[Потік Порожнечі завдає на $s1% більше шкоди.][Удар розуму завдає на $s2% більше шкоди.]" },
    { en = "Your $?c3[auto attack][auto shot] damage is increased by $s1%.", ua = "Шкоду вашої $?c3[автоатаки][автопострілу] збільшено на $s1%." },
    { en = "Riptide has a $s1% chance to upgrade your next Healing Stream Totem to Stormstream Totem which heals for $s2% more, heals $s3 additional $Lally:allies; at $s4% effectiveness, and heals $s5 injured allies for $1268684s1 healing when used.", ua = "Бурхлива течія має $s1% шанс покращити ваш наступний Тотем зцілющого потоку до Тотема штормового потоку, який зцілює на $s2% більше, зцілює $s3 додаткових $Lсоюзника:союзників; з $s4% ефективністю та зцілює $s5 поранених союзників на $1268684s1 при застосуванні." },
    { en = "While you are below $s1% health, your Ghoul sacrifices $1267032s1% of its maximum health to heal you for $1277365s2% of your maximum health every sec.", ua = "Поки твоє здоров'я нижче $s1%, твій гуль жертвує $1267032s1% свого максимального здоров'я, щоб щосекунди зцілювати тебе на $1277365s2% твого максимального здоров'я." },
    { en = "Healing Stream and Stormstream Totem healing increased by $s1%.", ua = "Зцілення «Тотема цілющого потоку» й «Тотема штормового потоку» збільшено на $s1%." },
    { en = "Casting $?s443454[Ancestral][Nature's] Swiftness grants a use of Stormstream Totem and Stormstream Totem no longer consumes a charge of Healing Stream Totem when used.", ua = "Творення $?s443454[Прудкості предків][Прудкості природи] надає змогу застосувати Тотем штормового потоку, і Тотем штормового потоку більше не споживає заряд Тотема зцілющого потоку під час застосування." },
    { en = "Shiv's Energy cost is reduced by $s1, its cooldown is reduced by ${-$s2/1000} sec, and its range is increased by $s3 yds.", ua = "Вартість енергії «Заточки» зменшена на $s1, її перезарядження зменшено на ${-$s2/1000} сек., а дальність збільшено на $s3 м." },
    { en = "Judgment has a chance to grant you Vanguard, causing your next Avenger's Shield to leave an echoing bolt of light in a line between you and the initial target, piercing any enemies for $1269175s1 Holy damage.", ua = "«Осуд» має шанс дати тобі «Авангард», завдяки чому твій наступний «Щит месника» лишає відлунний спалах світла лінією між тобою та початковою ціллю, пронизуючи всіх ворогів на шляху та завдаючи їм $1269175s1 шкоди від Світла." },
    { en = "Glide speed and height increased by $s1%.", ua = "Швидкість і висота планерування збільшені на $s1%." },
    { en = "Increases your Agility by $s1%.", ua = "Збільшує твою спритність на $s1%." },
    { en = "Judgment deals $s1% increased damage. When you consume Vanguard you gain $s2 Holy Power.", ua = "«Осуд» завдає на $s1% більше шкоди. Коли ти витрачаєш «Авангард», то отримуєш $s2 од. святої сили." },
    { en = "Your next cast of Shield of the Righteous after Vanguard deals $1269179s1% additional damage to your primary target and causes light to refract onto $s1 other $Ltarget:targets; for $1269224s1 Holy damage.\n\n\n\nDuring Avenging Wrath your Avenger's Shield always benefits from Vanguard.", ua = "Ваше наступне застосування Щита праведника після Авангарду завдає $1269179s1% додаткової шкоди вашій основній цілі й заломлює світло на $s1 $Lіншу ціль:інших цілей;, завдаючи $1269224s1 шкоди Світлом.\n\n\n\nПід час Караючого гніву ваш Щит месника завжди користає з Авангарду." },
    { en = "Damage taken during Aspect of the Turtle is reduced by an additional $s1%.", ua = "Шкода, отримувана під час «Аспекту черепахи», додатково зменшена на $s1%." },
    { en = "You have a $s2% chance to partially evade any damage dealt to you, reducing the damage it deals by $s3%.", ua = "Ти маєш $s2% шансу частково ухилитися від будь-якої завданої тобі шкоди, зменшивши її на $s3%." },
    { en = "When your Freezing Trap breaks, the victim's movement speed is reduced by $1268673s1% for $1268673d.", ua = "Коли дія твоєї «Заморожувальної пастки» уривається, швидкість руху жертви зменшується на $1268673s1% протягом $1268673d." },
    { en = "The duration of Master's Call is increased by ${$s1/1000} sec and it increases the movement speed of its target by $s2%.", ua = "Тривалість «Кличу майстра» збільшено на ${$s1/1000} сек., і він збільшує швидкість руху своєї цілі на $s2%." },
    { en = "You summon a Diabolic Oculus, up to $1269643u, each time the duration of Diabolic Ritual is reduced by one of your spells.\n\n\n\nDiabolic Oculi explode when consuming Demonic Art, dealing $1269800s1 Fire damage to all enemies within $1269800a1 yds of the target. Damage reduced beyond $s1 targets.", ua = "Ти прикликаєш Диявольське око, до $1269643u, щоразу, коли тривалість Диявольського ритуалу зменшується одним з твоїх заклять.\n\n\n\nДиявольські очі вибухають, поглинаючи Демонічне мистецтво, завдаючи $1269800s1 шкоди Вогнем усім ворогам у межах $1269800a1 м від цілі. Шкода зменшується після $s1 цілей." },
    { en = "Your Diabolic Oculi now cast Diabolic Gaze at your primary demon's target every 1 sec while active.\n\n\n\n$@spellicon1269892 $@spellname1269892\n\n$@spelldesc1269892", ua = "Ваші диявольські очі тепер, поки активні, кожну 1 сек творять Диявольський погляд на цілі вашого основного демона.\n\n\n\n$@spellicon1269892 $@spellname1269892\n\n$@spelldesc1269892" },
    { en = "Your Diabolic Oculi observe the battlefield and collect information that is imparted to you upon being exploded, each Diabolic Oculi increasing your Intellect by $1269879s1% for $1269879d.", ua = "Твої диявольські очі спостерігають за полем бою і збирають відомості, які передаються тобі під час вибуху: кожне диявольське око збільшує твій інтелект на $1269879s1% на $1269879d." },
    { en = "Thunder Focus Tea now empowers Enveloping Mist and Rising Sun Kick further.\n\n\n\n$@spellicon124682 $@spellname124682:\n\nBegins a channel of Soothing Mist onto your target.\n\n\n\n$@spellicon107428 $@spellname107428:\n\nReleases a Jadefire Stomp infront of you that transfers damage into Ancient Teachings at $s2% effectiveness.\n\n\n\n$@spellicon1248812 $@spellname1248812:\n\n$@spelldesc1248812", ua = "Чай громового зосередження тепер ще більше підсилює Огортальний туман і Копняк висхідного сонця.\n\n\n\n$@spellicon124682 $@spellname124682:\n\nПочинає підтримування Заспокійливого туману на твоїй цілі.\n\n\n\n$@spellicon107428 $@spellname107428:\n\nВивільняє Тупіт нефритового вогню перед тобою, що передає шкоду в Прадавні вчення з $s2% дієвістю.\n\n\n\n$@spellicon1248812 $@spellname1248812:\n\n$@spelldesc1248812" },
    { en = "Renewing Mist healing is increased by up to $s1% in proportion to its coverage on yourself and your allies.", ua = "Зцілення Оновлювального туману збільшується до $s1% пропорційно до того, скількох із вас — тебе і твоїх союзників — він укриває." },
    { en = "Wing Clip slows an additional ${-$s1}%.\n\n\n\nConcussive Shot slows an additional ${-$s2}%.", ua = "Підрізання крил сповільнює додатково на ${-$s1}%.\n\n\n\nКонтузійний постріл сповільнює додатково на ${-$s2}%." },
    { en = "Your Agility is increased by $s1%.", ua = "Твоя спритність збільшена на $s1%." },
    { en = "Defy Fate healing increased by $s1% and its cooldown is reduced by $s2 min.", ua = "Зцілення Виклику долі посилено на $s1%, а його перезарядження скорочено на $s2 хв." },
    { en = "Each Succulent Soul consumed has an increasing chance to unleash the Demonic Soul within you, enabling it to assault your enemies for $1269042d.\n\n\n\n$@spellicon1269049 $@spellname1269049\n\n$@spelldesc1269049", ua = "Кожна спожита Соковита душа дає зростаючий шанс вивільнити Демонічну душу всередині вас, дозволяючи їй атакувати ваших ворогів протягом $1269042d.\n\n\n\n$@spellicon1269049 $@spellname1269049\n\n$@spelldesc1269049" },
    { en = "Increases your Mastery by $s1%.\n\n\n\nThis effect is doubled while the demonic entity is aiding you in combat.", ua = "Збільшує вашу Майстерність на $s1%.\n\n\n\nЦей ефект подвоюється, поки демонічна сутність допомагає вам у бою." },
    { en = "Increases the duration of Manifested Avarice by ${$s1/1000} sec and increases the damage of Soul Swipe by $s2%.", ua = "Збільшує тривалість Втіленої жадоби на ${$s1/1000} сек. і збільшує шкоду Змаху душі на $s2%." },
    { en = "Damaging attacks that expend Shadow Techniques to generate combo points have a $s1% chance per stack expended to create a Shadow Clone that repeats the attack for $s2% of normal damage as Shadow.", ua = "Атаки, що завдають шкоди й витрачають Тіньові техніки для створення очок комбо, мають $s1% шансу за кожен витрачений заряд створити тіньового клона, який повторює атаку, завдаючи $s2% звичайної шкоди Тінню." },
    { en = "Shadow damage increased by $s2%.\n\n\n\nShadow Clones have a $s1% chance to trigger Shadow Techniques' effect.", ua = "Тіньова шкода збільшена на $s2%.\n\n\n\nТіньові клони мають $s1% шанс запустити ефект «Тіньових технік»." },
    { en = "After attacks that generate combo points, if $s1 or more stacks of Shadow Techniques remain, your next damaging finishing move will expend them to generate combo points up to your max.", ua = "Якщо після атак, що генерують очки комбо, лишається $s1 чи більше зар. Тіньових технік, твій наступний завершальний прийом, що завдає шкоди, витратить їх, щоб згенерувати очки комбо до твого максимуму." },
    { en = "Voltaic Blaze's cooldown is reduced by ${$s1/-1000} sec and its instant damage is increased by $s2%.", ua = "Перезарядження «Вольтаїчного спалаху» зменшено на ${$s1/-1000} сек., а його миттєву шкоду збільшено на $s2%." },
    { en = "Each stack of Master of Warfare increases Mortal Strike, Cleave, and Overpower damage by ${$s1/10}.1% and critical strike damage by ${$s2/10}.1%.", ua = "Кожен заряд Майстра війни збільшує шкоду Смертельного удару, Розсічення та Пересилення на ${$s1/10}.1%, а шкоду критичних ударів — на ${$s2/10}.1%." },
    { en = "Heroic Strike increases the damage you deal to enemies affected by your next Colossus Smash by an additional ${$1292058s1}.1%. Stacks up to $1292058u times.", ua = "Героїчний удар додатково збільшує на ${$1292058s1}.1% шкоду, якої ти завдаєш ворогам під дією твого наступного Удару колоса. Складається до $1292058u разів." },
    { en = "Rampage damage increased by $s1% and Rampage makes you go Berserk, increasing your Strength by $1269349s1% for $1269349d. Multiple applications of Berserk may overlap.", ua = "Шкоду «Буйства» збільшено на $s1%, а саме «Буйство» вводить тебе в стан берсерка, збільшуючи твою Силу на $1269349s1% на $1269349d. Кілька ефектів «Берсерка» можуть діяти одночасно." },
    { en = "Rampage's Rage cost is reduced by ${$s1/-10} and damage is increased by a further $s2% during Recklessness.", ua = "Під час «Безрозсудності» вартість «Буйства» в люті зменшено на ${$s1/-10}, а його шкоду додатково збільшено на $s2%." },
    { en = "Recklessness grants $s2 stacks of Berserk and duration of Recklessness increased by $s1%.", ua = "«Безрозсудність» надає $s2 зарядів «Берсерка», а тривалість «Безрозсудності» збільшено на $s1%." },
    { en = "Thunder Clap causes your next Shield Slam to deal $1278009s1% additional damage and unleash a wave of force, dealing $1270116s1 Physical damage to all enemies in front of you.", ua = "«Удар грому» змушує твій наступний «Удар щитом» завдати на $1278009s1% більше шкоди та випустити хвилю сили, що завдає $1270116s1 фізичної шкоди всім ворогам перед тобою." },
    { en = "Damage dealt by Thunder Clap and Phalanx's wave of force is increased by $s1%.", ua = "Шкоду від Удару грому та хвилі сили Фаланги збільшено на $s1%." },
    { en = "While Shield Block is active, Shield Slam deals 10% additional damage and has a 20% increased chance to critically strike.\n\n\n\nEnemies damaged by Phalanx's wave of force deal ${$1292071s1/-1}.1% reduced damage to you for $1292071d.", ua = "Поки активне Блокування щитом, Удар щитом завдає на 10% більше шкоди і має на 20% вищий шанс критичного удару.\n\n\n\nВороги, що зазнали шкоди від хвилі сили Фаланги, завдають вам на ${$1292071s1/-1}.1% менше шкоди протягом $1292071d." },
    { en = "Your single target melee abilities have a chance to upgrade Slam to Heroic Strike.\n\nAll modifiers and talents that affect Slam also affect Heroic Strike.\n\n\n\n$@spellicon1269383 $@spelltooltip1269383", ua = "Ваші здібності ближнього бою по одній цілі мають шанс покращити Замашний удар до Героїчного удару.\n\nУсі модифікатори й таланти, що впливають на Замашний удар, також впливають на Героїчний удар.\n\n\n\n$@spellicon1269383 $@spelltooltip1269383" },
    { en = "After you cast Berserk or Incarnation: Guardian of Ursoc, you gain access to Wild Guardian:\n\n$@spellicon1269616 $@spellname1269616:\n\nSpirits of the wild come to your aid, causing your next $s2 $Lcast:casts; of Ironfur, Maul, and Frenzied Regeneration to be echoed at $s1% effectiveness.", ua = "Після застосування Берсерка або Втілення: вартового Урсока ви отримуєте доступ до Дикого стража:\n\n$@spellicon1269616 $@spellname1269616:\n\nДухи дикої природи приходять вам на допомогу, через що ваші наступні $s2 $Lзастосування:застосувань; Залізного хутра, Калічення та Шаленої регенерації повторюються з $s1% ефективністю." },
    { en = "Mastery increased by $s1%. \n\n\n\nWhen you cast Wild Guardian, you gain $s2 charges of $?a372119[Dream of Cenarius][Dream Guide].", ua = "Майстерність збільшено на $s1%. \n\n\n\nКоли ви застосовуєте Дикого стража, ви отримуєте $s2 заряди $?a372119[Сну Кенарія][Провідника снів]." },
    { en = "Wild Guardian's echoes are now cast at $?a1269619[$1269614s1][${$s2+$1269614s1}]% effectiveness, and each echo $s3 additional times over ${$s4/1000}.0 sec.\n\n\n\nMaul is always empowered and deals $s1% additional Nature damage over $1270065d.", ua = "Відлуння Дикого стража тепер застосовуються з $?a1269619[$1269614s1][${$s2+$1269614s1}]% ефективністю, і кожне відлуння повторюється $s3 додаткові рази протягом ${$s4/1000}.0 сек.\n\n\n\nКалічення завжди посилене і завдає на $s1% більше шкоди природою протягом $1270065d." },
    { en = "Elemental Overload damage increased by $s1%.", ua = "Шкода «Стихійного перевантаження» збільшена на $s1%." },
    { en = "Spell critical strike chance increased by $s1%. Elemental Fury increases spell critical strike damage by an additional $s2%.", ua = "Шанс критичного удару заклять збільшено на $s1%. «Стихійна лють» додатково збільшує шкоду критичних ударів заклять на $s2%." },
    { en = "Elemental Overloads have a $s1% chance to cause an additional Elemental Overload. This effect cannot chain.", ua = "«Стихійні перевантаження» з імовірністю $s1% спричиняють додаткове «Стихійне перевантаження». Цей ефект не може спрацьовувати ланцюгом." },
    { en = "Reduces the cooldown of Shadowfury by ${$s1/-1000} sec and increases its radius by $s2 yds.\n\n\n\nReduces the cooldown of Howl of Terror by ${$s3/-1000} sec and it now fears $s4 additional enemies.", ua = "Зменшує перезарядження Тіньової люті на ${$s1/-1000} сек і збільшує її радіус на $s2 ярдів.\n\n\n\nЗменшує перезарядження Виття жаху на ${$s3/-1000} сек, і воно тепер лякає $s4 додаткових ворогів." },
    { en = "$?c3[Water][Lightning] Shield increases your $?c2[Agility][Intellect] by $s1%.\n\n\n\nCasting $?c3[Water][Lightning] Shield now applies your weapon imbuements. Earth Shield is also applied if you have the Elemental Orbit talent.", ua = "$?c3[«Водяний][«Блискавковий] щит» підвищує твою $?c2[Спритність][Інтелект] на $s1%.\n\n\n\nЗастосування $?c3[«Водяного][«Блискавкового] щита» тепер накладає твої насичення зброї. «Земний щит» теж накладається, якщо ти маєш талант «Стихійна орбіта»." },
    { en = "Soul Cleave and Spirit Bomb have a chance per soul fragment consumed to grant Untethered Rage, allowing Metamorphosis to be cast without incurring its cooldown and lasting $s1 sec.", ua = "«Розсічення душ» і «Духовна бомба» з кожним поглинутим фрагментом душі мають шанс дарувати «Розкутий гнів», що дозволяє створити «Метаморфозу» тривалістю $s1 сек., не запускаючи її перезарядження." },
    { en = "Your Intellect is increased by ${$s1}.1% for each Ancestor active.", ua = "Твій інтелект збільшено на ${$s1}.1% за кожного активного предка." },
    { en = "The cast times of $?c1[Healing Surge, Chain Heal and][Healing Wave, Chain Heal, and] Lava Burst are reduced by $s1%.", ua = "Час прочитання $?c1[Цілющого сплеску, Ланцюгового зцілення та][Хвилі зцілення, Ланцюгового зцілення та] Виверження лави зменшено на $s1%." },
    { en = "Soul Cleave and Spirit Bomb can consume an additional soul fragment and deal an additional $s1% damage for each consumed.", ua = "«Розсічення душ» і «Духовна бомба» можуть поглинути додатковий фрагмент душі та завдають на $s1% більше шкоди за кожен поглинутий." },
    { en = "Each cast of Soul Cleave and Spirit Bomb that does not grant Untethered Rage instead applies a stack of Seething Anger.\n\n\n\nSeething Anger grants $1270547s1% Agility and increases your chance to gain Untethered Rage. Lasts $1270547d and cannot be refreshed after gaining Untethered Rage.", ua = "Кожне прочитання Розтину душі та Бомби духу, яке не дає Розкутий гнів, натомість накладає заряд Клекотливої злості.\n\n\n\nКлекотлива злість дає $1270547s1% Спритності та збільшує ваш шанс отримати Розкутий гнів. Триває $1270547d і не може бути оновлена після отримання Розкутого гніву." },
    { en = "$?c3[For $1270453d sec after casting Nature's Swiftness or Ancestral Swiftness, the recharge rate of Riptide is increased by $1270453s1%.\n\n\n\n][]Increases the chance for Lava Surge to occur by $s1%.", ua = "$?c3[Протягом $1270453d сек. після застосування «Стрімкості природи» або «Стрімкості предків» швидкість перезарядки «Відпливу» зростає на $1270453s1%.\n\n\n\n][]Підвищує шанс спрацювання «Лавового сплеску» на $s1%." },
    { en = "The rate at which $?c2[Bloodseeker Vines][Symbiotic Blooms] grow is increased by $?c2[$s1][$s2]%.", ua = "Швидкість росту $?c2[«Лоз-кровошукачів»][«Симбіотичного цвіту»] збільшено на $?c2[$s1][$s2]%." },
    { en = "$?c2[Bloodseeker Vines][Symbiotic Blooms] have a $?c2[$s1][$s2]% chance to trigger Bursting Growth every 2 sec at $?c2[$s3][$s4]% effectiveness.", ua = "$?c2[«Лози-кровошуки» мають][«Симбіотичний цвіт» має] $?c2[$s1][$s2]% шансу що 2 сек. спричинити «Вибуховий ріст» з ефективністю $?c2[$s3][$s4]%." },
    { en = "Your $?c2[Bleeds and other damage over time][heal over time] effects are $?c2[$s1][$s3]% more effective.", ua = "Твої ефекти $?c2[кровотечі та іншої поступової шкоди][поступового зцілення] на $?c2[$s1][$s3]% ефективніші." },
    { en = "Consuming Mana Tea generates $s1 $Lcloud of mist:clouds of mist;.", ua = "Поглинання Чаю мани створює $s1 $Lхмару туману:хмари туману;." },
    { en = "Increases your critical strike chance by $s1%.", ua = "Збільшує твій шанс критичного удару на $s1%." },
    { en = "Drain Life now channels ${$s1*-2}% faster and restores health ${$s1*-2}% faster.", ua = "«Висмоктування життя» тепер підтримується на ${$s1*-2}% швидше і відновлює здоров'я на ${$s1*-2}% швидше." },
    { en = "Demolish's final strike applies Deep Wounds to all targets at $s1% effectiveness.", ua = "Останній удар Трощення накладає Глибокі рани на всі цілі з $s1% ефективності." },
    { en = "$?c1[Mortal Strike][Shield Slam] critical strikes increase your Rend and Deep Wounds damage by $1270840s1% for $1270840d.", ua = "Критичні удари $?c1[«Смертельного удару»][«Удару щитом»] підвищують шкоду ваших «Роздирання» і «Глибоких ран» на $1270840s1% протягом $1270840d." },
    { en = "Demolish's final strike grants $1270843s1% Haste for $1270843d and increases the critical strike chance of your next $?c1[Mortal Strike][Shield Slam] by $1270846s1%.", ua = "Останній удар Знесення надає $1270843s1% Поспіху на $1270843d і збільшує шанс критичного удару вашого наступного $?c1[Смертельного удару][Удару щитом] на $1270846s1%." },
    { en = "Bladestorm puts you into a battle trance, granting you 15% haste for 8 sec after you stop Bladestorming.", ua = "«Буря клинків» занурює тебе в бойовий транс, даючи 15% поспіху на 8 сек. після її завершення." },
    { en = "Executioner's duration is increased by ${$s1/1000} sec.", ua = "Тривалість Ката збільшено на ${$s1/1000} сек." },
    { en = "Lightning Strike damage increased by $s1% and critical strike damage increased by $s2%.", ua = "Шкоду «Удару блискавки» збільшено на $s1%, а шкоду від критичних ударів — на $s2%." },
    { en = "During Avatar, Thunder Blast extends Avatar's duration by ${$s1/1000}.1 sec.", ua = "Під час дії Аватара Громовий вибух подовжує тривалість Аватара на ${$s1/1000}.1 сек." },
    { en = "Spellsteal repeats its effect after $1270828d, but it now has a cooldown of ${$s1/1000}.1 sec.", ua = "Крадіжка закляття повторює свій ефект через $1270828d, але тепер має перезарядження ${$s1/1000}.1 сек." },
    { en = "After casting $?s212653[Shimmer][Blink], it is replaced with Reflection for $389714d.\n\n\n\n$@spellicon389713 $@spellname389713\n\n$@spelldesc389713", ua = "Після творіння $?s212653[Мерехтіння][Стрибка] він замінюється на Віддзеркалення на $389714d.\n\n\n\n$@spellicon389713 $@spellname389713\n\n$@spelldesc389713" },
    { en = "Your mana costs are reduced by ${-$s1}%.", ua = "Витрати мани зменшено на ${-$s1}%." },
    { en = "Casting Remove Curse on a friendly target also casts it on yourself, but its cooldown is increased by ${$s2/1000} sec.", ua = "Прочитання «Зняття прокляття» на дружню ціль також застосовує його до тебе, але перезарядження збільшується на ${$s2/1000} сек." },
    { en = "Counterspell prevents casting for an additional ${$s1/1000}.1 sec.", ua = "«Контрзакляття» блокує читання заклять на додаткові ${$s1/1000}.1 сек." },
    { en = "The duration of $?a137019[Hot Streak]?a137020[Brain Freeze][Clearcasting] is increased by $?a137021[${$s1/1000}][${$s2/1000}] sec.", ua = "Тривалість $?a137019[Гарячої смуги]?a137020[Заморозки мозку][Ясного розуму] збільшено на $?a137021[${$s1/1000}][${$s2/1000}] с." },
    { en = "The Hunt empowers your next Eye Beam, increasing damage by $s1% and affecting enemies in a wider area.", ua = "«Полювання» підсилює твій наступний «Промінь ока», збільшуючи його шкоду на $s1% і розширюючи зону враження ворогів." },
    { en = "The Hunt has ${$s2/-1000} sec reduced cooldown, deals $s1% more damage, and its damage over time effect applies to $s3 additional enemies.", ua = "Перезарядження «Полювання» скорочено на ${$s2/-1000} сек., воно завдає на $s1% більше шкоди, а його ефект періодичної шкоди діє ще на $s3 ворогів." },
    { en = "Blade Dance damage increased by $s1%.\n\n\n\nFully channeling Eye Beam causes your next Blade Dance to refresh its own cooldown.", ua = "Шкода Танцю клинків збільшена на $s1%.\n\n\n\nПовне підтримання Променя ока дає вашому наступному Танцю клинків скинути власне перезарядження." },
    { en = "The mana cost of Holy Light is reduced by $s1% and its cast time is reduced by $s2%.", ua = "Вартість мани «Святого світла» зменшено на $s1%, а час його творення — на $s2%." },
    { en = "Casting $?s322507[Celestial Brew]?s1241059[Celestial Infusion][Thunder Focus Tea] grants $?c1[$s5][$s6] $Lcharge:charges; of Potential Energy. Your next cast of Tiger Palm or Vivify consumes all charges of Potential Energy to cause a Harmonic Surge.\n\n\n\n$@spellicon1271011$@spellname1271011:\n\n$@spelldesc1271011", ua = "Творення $?s322507[Небесного напою]?s1241059[Небесного настою][Чаю грозового зосередження] дарує $?c1[$s5][$s6] $Lзаряд:заряди; Потенційної енергії. Ваше наступне творення Долоні тигра або Оживлення поглинає всі заряди Потенційної енергії, спричиняючи Гармонійний приплив.\n\n\n\n$@spellicon1271011$@spellname1271011:\n\n$@spelldesc1271011" },
    { en = "While Avenging Wrath is not active, you gain $s1% Mastery.\n\n\n\nWhile Avenging Wrath is active, you gain $s2% movement speed.", ua = "Поки «Караючий гнів» неактивний, ви отримуєте $s1% Майстерності.\n\n\n\nПоки «Караючий гнів» активний, ви отримуєте $s2% швидкості руху." },
    { en = "Casting $?c1[Keg Smash][Rising Sun Kick or Rushing Wind Kick] grants a charge of Potential Energy.", ua = "Творення $?c1[Удару барилом][Удару сонця, що сходить, або Удару стрімкого вітру] надає заряд Потенційної енергії." },
    { en = "Holy Light's healing is increased by $s1%, but its mana cost is increased by $s2%.", ua = "Зцілення «Святого Світла» збільшено на $s1%, але його вартість мани збільшено на $s2%." },
    { en = "Unleash Life heals for $s1% more and its bonus healing effect is increased by $s2%.", ua = "«Вивільнення життя» зцілює на $s1% більше, а його бонусний ефект зцілення збільшено на $s2%." },
    { en = "$?a388023[Ancient Teachings transfers an additional $s1% damage to healing.][$@spellicon196736 Blackout Combo:\n\nIncreases Tiger Palm damage by an additional $s2% and Keg Smash reduces the cooldown on your Brews by an additional ${$s3/1000}.1 sec.\n\n\n\n$@spellicon418359  Press the Advantage:\n\nNature damage dealt by your main hand auto-attacks is increased by $s4% and they now reduce the cooldown on your Brews by an additional ${$s5/1000}.2 sec.]", ua = "$?a388023[Прадавні вчення переносять на $s1% більше шкоди в зцілення.][$@spellicon196736 Комбо затьмарення:\n\nЗбільшує шкоду Долоні тигра ще на $s2%, а Удар діжкою додатково зменшує перезарядження ваших Напоїв на ${$s3/1000}.1 сек.\n\n\n\n$@spellicon418359  Тиснути перевагу:\n\nШкода від сил природи, яку завдають автоатаки вашої основної руки, збільшена на $s4%, і тепер вони додатково зменшують перезарядження ваших Напоїв на ${$s5/1000}.2 сек.]" },
    { en = "Fire Blast deals $1271173s1 additional Fire damage to up to $s2 nearby enemies.", ua = "«Вогняний вибух» завдає $1271173s1 додаткової шкоди від вогню щонайбільше $s2 ворогам поблизу." },
    { en = "When Combustion expires, all of your active Ignites explode, dealing $s1% of their remaining damage.", ua = "Коли «Згоряння» завершується, усі твої активні «Займання» вибухають, завдаючи $s1% решти своєї шкоди." },
    { en = "$?c1[Gaining Astral Power with Wrath or Starfire][Thrash] has a $?c1[$s1][$s2]% chance to launch a Starsurge at a victim at $?c1[$s3][$s4]% effectiveness.", ua = "$?c1[Отримання астральної сили від Гніву чи Зоряного вогню][Молотьба] має $?c1[$s1][$s2]% шанс випустити в жертву Зоряний сплеск із $?c1[$s3][$s4]% ефективності." },
    { en = "Light of Dawn receives $s1% increased benefit from Mastery: Lightbringer.", ua = "«Світло світанку» отримує на $s1% більшу користь від «Майстерності: Світлоносець»." },
    { en = "$?c1[Lunar Eclipse increases Arcane damage by an additional $s1%][\n\nLunar Beam increases Arcane damage you deal by $204066s6% while it is active].", ua = "$?c1[Місячне затемнення збільшує арканну шкоду додатково на $s1%][\n\nМісячний промінь збільшує арканну шкоду, яку ви завдаєте, на $204066s6%, доки активний]." },
    { en = "$?c1[Starsurge damage increased by $s1%. \n\nStarfall damage increased by $s2%.]?s400254[Raze][Maul] $?c3[damage increased by $s3%. Lunar Beam's damage dealt to its primary target increased by $s4%.][]", ua = "$?c1[Шкода Зоряного сплеску збільшена на $s1%. \n\nШкода Зорепаду збільшена на $s2%.]?s400254[Зрівняння][Калічення] $?c3[завдає на $s3% більше шкоди. Шкода Місячного променя по основній цілі збільшена на $s4%.][]" },
    { en = "After casting a Holy Armament, your next $s1 $Lability:abilities; $Lcasts:cast; a Lesser Armament of the same kind on a nearby ally.", ua = "Після застосування Святого озброєння $s1 $Lтвоя наступна здібність накладає:твої наступні здібності накладають; Мале озброєння того самого виду на союзника поблизу." },
    { en = "The healing of Gusts of Mist caused by Renewing Mist is increased by $s1%.", ua = "Зцілення «Поривів туману», викликаних «Відновлювальним туманом», збільшено на $s1%." },
    { en = "When your Holy Bulwark absorbs damage or your Sacred Weapon deals damage or healing, you have a chance to gain $?c2[Grand Crusader][Awakening].", ua = "Коли твій «Святий бастіон» поглинає шкоду або твоя «Священна зброя» завдає шкоди чи зцілює, ти маєш шанс отримати ефект $?c2[«Великий хрестоносець»][«Пробудження»]." },
    { en = "Your auto-attacks are 30% more likely to make your next $?c2[Ferocious Bite]?s400254[Raze][Maul] become Ravage.", ua = "Твої автоатаки на 30% частіше перетворюють твою наступну здібність $?c2[«Лютий укус»]?s400254[«Руйнування»][«Трощення»] на «Спустошення»." },
    { en = "$?c1[Holy Armaments activate][Divine Toll activates] Hammer and Anvil at $s1% effectiveness.", ua = "$?c1[«Святе озброєння» активує][«Божественний поклик» активує] «Молот і ковадло» з $s1% ефективності." },
    { en = "You have a $?c2[$s1][$s2]% chance to follow up any single target melee ability$?c3[ or Raze][] with a Twin Claw, dealing $?c2[$1271636s1][$1271657s1] Physical damage and generating $?c2[$1271636s2 Energy][${$1271657s2/10} Rage].", ua = "Ти маєш $?c2[$s1][$s2]% шансу після будь-якої здібності ближнього бою по одній цілі$?c3[ або «Руйнування»][] завдати удару «Подвійним кігтем», що завдає $?c2[$1271636s1][$1271657s1] фізичної шкоди та додає $?c2[$1271636s2 енергії][${$1271657s2/10} люті]." },
    { en = "While Dragonrage is active you gain Rising Fury every $1271783t4 sec, increasing your haste by $1271783s1%, stacking up to $1271783U times.", ua = "Поки активна Драконяча лють, ви кожні $1271783t4 сек. отримуєте Наростання люті, що збільшує ваш поспіх на $1271783s1%. Накопичується до $1271783U разів." },
    { en = "Drain Life heals for an additional ${$s1*100}% of damage dealt and grants Soul Leech equal to $s2% of damage dealt.", ua = "«Висмоктування життя» зцілює додатково на ${$s1*100}% від завданої шкоди і дає «Висмоктування душі» в обсязі $s2% від завданої шкоди." },
    { en = "Soul Leech may now absorb an additional ${$s1}% of your maximum health.", ua = "«Висмоктування душі» тепер може поглинати додатково ${$s1}% твого максимального здоров'я." },
    { en = "Healthstones heal you for an additional $s1% additional health.", ua = "Камені здоров'я відновлюють тобі додатково $s1% здоров'я." },
    { en = "When Dragonrage ends, gain Risen Fury for ${$s1/1000} sec for each stack of Rising Fury.\n\n\n\nRisen Fury grants the damage and haste bonuses accumulated from Rising Fury and generates Essence Burst every $1271799t4 sec.", ua = "Коли Драконяча лють завершується, ви отримуєте Збурену лють на ${$s1/1000} сек за кожен заряд Наростання люті.\n\n\n\nЗбурена лють надає бонуси шкоди та поспіху, накопичені з Наростання люті, і породжує Спалах есенції щораз на $1271799t4 сек." },
    { en = "At $1271783U stacks of Rising Fury, all damage dealt is increased by $s1%.", ua = "За $1271783U зарядів Наростання люті вся завдана шкода збільшується на $s1%." },
    { en = "Call forth a cloud of cloying shadow mist that envelopes the target and all enemies within $1272123a1 yds, increasing their casting time of all spells by $1272122s1% for $1272122d.\n\n\n\n|cFF8282FFCurses: A warlock can only have one Curse or Blight active per target.|r", ua = "Прикликає хмару задушливого тіньового туману, що огортає ціль і всіх ворогів у межах $1272123a1 ярдів, збільшуючи час прочитання всіх їхніх заклять на $1272122s1% впродовж $1272122d.\n\n\n\n|cFF8282FFПрокляття: чорнокнижник може мати лише одне Прокляття або Пошесть активними на ціль.|r" },
    { en = "Your Dreadful Wounds increase the damage afflicted enemies take from your Bleed damage over time effects by $?c2[$s2][$s3]%.", ua = "Твої «Жахливі рани» збільшують шкоду, яку уражені вороги отримують від твоїх ефектів поступової шкоди від кровотеч, на $?c2[$s2][$s3]%." },
    { en = "Cooldown of Berserker Rage is reduced by $s1% and Berseker Rage removes all movement speed-impairing effects.", ua = "Перезарядження Люті берсерка скорочено на $s1%, а Лють берсерка знімає всі ефекти, що сповільнюють рух." },
    { en = "Healing received increased by $s1% and all self-healing increased by an additional $s2%.", ua = "Отримуване зцілення збільшено на $s1%, а все самозцілення — додатково ще на $s2%." },
    { en = "Range of your thrown abilities is increased by $s1 yards.\n\n\n\nDamage dealt by Champion's Spear, Shattering Throw, and Wrecking Throw increased by $s2%.\n\n\n\nShattering Throw and Wrecking Throw silence non-players for $1277104d.", ua = "Дальність твоїх метальних здібностей збільшена на $s1 м.\n\n\n\nШкода від Списа чемпіона, Нищівного кидка та Руйнівного кидка збільшена на $s2%.\n\n\n\nНищівний кидок і Руйнівний кидок німують неігрових персонажів на $1277104d." },
    { en = "Dark Transformation grants access to Blightfall.\n\n\n\n$@spellicon1271967$@spellname1271967\n\n$@spelldesc1271967", ua = "Темне перетворення відкриває доступ до Спаду пошесті.\n\n\n\n$@spellicon1271967$@spellname1271967\n\n$@spelldesc1271967" },
    { en = "Your pet protects you at all times, reducing the damage you take by $s1%. Your pet receives $s2% of the damage it mitigates.", ua = "Твій улюбленець постійно захищає тебе, зменшуючи отримувану тобою шкоду на $s1%. Улюбленець отримує $s2% від відверненої шкоди." },
    { en = "Bestial Wrath provokes your pets to tear into your target, causing your target to bleed for $321538o1 damage over $321538d.", ua = "«Звірячий гнів» спонукає твоїх улюбленців роздерти ціль, спричиняючи кровотечу, що завдає $321538o1 шкоди протягом $321538d." },
    { en = "Boomstick's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження «Бабахалки» скорочене на ${-$s1/1000} сек." },
    { en = "Reaver's Glaive damage is increased by $s1% and other Physical-only damage is increased by $s2%.", ua = "Шкода «Глефи спустошувача» збільшена на $s1%, а інша суто фізична шкода — на $s2%." },
    { en = "Takedown grants $s1 stacks of Tip of the Spear.", ua = "«Повалення» дає $s1 зарядів «Вістря списа»." },
    { en = "$?a212613[Sigil of Spite][The Hunt] shatters $?a212613[$s1 additional][$s2] Soul $LFragment:Fragments;. $?a212613[Soul Cleave has][Blade Dance and Chaos Strike have] a $?a212613[$s3][$s4]% chance to shatter a Soul Fragment.", ua = "$?a212613[Знак злоби][Полювання] розколює $?a212613[$s1 додатковий][$s2] $LФрагмент душі:Фрагменти душі:Фрагментів душі;. $?a212613[Розтин душі має][Танець клинків і Удар Хаосу мають] $?a212613[$s3][$s4]% шанс розколоти Фрагмент душі." },
    { en = "Fury of the Aldrachi further empowers $?a212613[Soul Cleave][Blade Dance] when cast after $?a212613[Fracture][Chaos Strike], increasing slashes to ${$442718s2*($442718s1/100+1)+$s1}.\n\n\n\nReaver's Mark now stacks up to $442624u times and further empowers $?a212613[Fracture][Chaos Strike] when cast after $?a212613[Soul Cleave][Blade Dance], applying an additional stack.", ua = "Лють Алдрахі ще більше підсилює $?a212613[Розсічення душі][Танець клинків], якщо застосовано після $?a212613[Перелому][Удару хаосу], збільшуючи кількість розтинів до ${$442718s2*($442718s1/100+1)+$s1}.\n\n\n\nМітка плюндрувальника тепер накопичується до $442624u разів і ще більше підсилює $?a212613[Перелом][Удар хаосу], якщо застосовано після $?a212613[Розсічення душі][Танцю клинків], додаючи додатковий стак." },
    { en = "Kill Command grants $s1 additional $Lstack:stacks; of Tip of the Spear.\n\n\n\nTip of the Spear's damage bonus is increased by $s2%.", ua = "Наказ убити надає $s1 додатковий $Lзаряд:заряди:зарядів; Вістря списа.\n\n\n\nБонус шкоди Вістря списа збільшено на $s2%." },
    { en = "Your magical damage is increased by $s1%.", ua = "Твоя магічна шкода збільшена на $s1%." },
    { en = "Power Surge lasts an additional ${$s1/1000} sec.", ua = "«Сплеск сили» триває на ${$s1/1000} сек. довше." },
    { en = "$?c2[Prayer of Healing mana cost reduced by $s1% and its cast time is reduced by $s2%.][Void Volley damage increased by $s3% and its cooldown is reduced by ${$s4/-1000} sec.]", ua = "$?c2[Витрати мани Молитви зцілення зменшуються на $s1%, а час її прочитання зменшується на $s2%.][Шкода Залпу Порожнечі збільшується на $s3%, а її перезарядження зменшується на ${$s4/-1000} с.]" },
    { en = "$?c2[Flash Heal healing increased by $s1%. \n\n\n\nHealing spells and Smite have an additional $s2% chance to grant Surge of Light.][Shadow Word: Death damage increased by $s3% and its cooldown is reduced by ${$s4/-1000} sec.]", ua = "$?c2[Зцілення від Швидкого зцілення збільшено на $s1%. \n\n\n\nЗцілювальні закляття та Удар мають додаткові $s2% шансу дати Сплеск Світла.][Шкода від Слова тіні: Смерть збільшена на $s3%, а її перезарядження зменшено на ${$s4/-1000} с.]" },
    { en = "$?a137031&?a1246517[Holy Word: Serenity healing increased by $s1%.]?c2[Holy Word: Serenity and Holy Word: Sanctify healing increased by $s1%.][Flash Heal, Plea, and Power Word: Radiance healing increased by $s2%.]", ua = "$?a137031&?a1246517[Зцілення Священного слова: Безтурботність збільшується на $s1%.]?c2[Зцілення Священного слова: Безтурботність і Священного слова: Освячення збільшується на $s1%.][Зцілення Швидкого зцілення, Благання та Слова сили: Сяйво збільшується на $s2%.]" },
    { en = "$?c2[Reduces the cooldown of your Holy Words by ${$s1/-1000} sec.][Atonement healing from Holy spells is increased by $s4%.]", ua = "$?c2[Зменшує перезарядження ваших Священних слів на ${$s1/-1000} с.][Зцілення від Спокути зі священних заклять збільшено на $s4%.]" },
    { en = "$?c2[When Prayer of Mending expires without healing, it jumps to a nearby injured ally and loses $s1 $Lstack:stacks; instead.][\n\nWhen Power Word: Shield or Void Shield expires with absorption remaining, it jumps to a nearby injured ally and loses $s2% of its maximum absorb instead.]", ua = "$?c2[Коли Молитва зцілення спливає, не зціливши, вона натомість перестрибує на пораненого союзника поблизу й втрачає $s1 $Lзаряд:заряди:зарядів;.][\n\nКоли Слово сили: Щит або Щит Порожнечі спливає з рештою поглинання, він натомість перестрибує на пораненого союзника поблизу й втрачає $s2% свого максимального поглинання.]" },
    { en = "$?a212612[Fire][Cosmic] damage increased by $?a212612[$s1][$s3]%.\n\n\n\nEffect is doubled while in demon form.", ua = "$?a212612[Вогняну][Космічну] шкоду збільшено на $?a212612[$s1][$s3]%.\n\n\n\nЕфект подвоюється в демонічній формі." },
    { en = "$?a212612[Immolation Aura][Soul Immolation] has a $?a212612[$s1][$s2]% chance to reignite after it expires, reapplying its effect.", ua = "$?a212612[Аура самоспалення][Самоспалення душі] має $?a212612[$s1][$s2]% шанс знову спалахнути після завершення, повторно накладаючи свій ефект." },
    { en = "Rising Sun Kick gains $s1% additional effectiveness from Mastery: Combo Strikes.", ua = "Удар висхідного сонця отримує на $s1% більшу ефективність від «Майстерності: комбо-ударів»." },
    { en = "Collapsing Star reduces the cooldown of Voidblade by ${$s1/1000} sec.\n\n\n\nVoidblade and The Hunt briefly reduce your Fury drain while in Void Metamorphosis.", ua = "Зоря, що згасає, зменшує перезарядження Клинка Порожнечі на ${$s1/1000} сек.\n\n\n\nКлинок Порожнечі та Полювання ненадовго сповільнюють втрату Люті під час Метаморфози Порожнечі." },
    { en = "Hungering Slash and Voidblade's critical strike chance is increased by $s1%.", ua = "Шанс критичного удару «Голодного розтину» та «Клинка Порожнечі» збільшено на $s1%." },
    { en = "Touch of Death now heals you for $s1% of its damage done.", ua = "«Дотик смерті» тепер зцілює тебе на $s1% завданої ним шкоди." },
    { en = "Entering demon form $?a212612[immediately induces a Demonsurge][causes your next Voidsurge to repeat after a short delay].", ua = "Прийняття форми демона $?a212612[миттєво спричиняє Демонічний сплеск][змушує ваш наступний Сплеск Порожнечі повторитися після короткої затримки]." },
    { en = "Your damage during Zenith is increased by $s1%.", ua = "Твоя шкода під час «Зеніту» збільшена на $s1%." },
    { en = "Your melee attack speed is increased by $s2%. This bonus is increased to $s3% during Zenith.", ua = "Швидкість твоїх ближніх атак збільшена на $s2%. Під час «Зеніту» цей бонус зростає до $s3%." },
    { en = "Activating Zenith causes you to release a powerful stomp, dealing $1272696s1 Nature damage to nearby enemies, reduced beyond $s1 targets.\n\n\n\n|cFFFFFFFFGenerates $1272696s2 Chi.", ua = "Активація Зеніту вивільняє потужний тупіт, що завдає $1272696s1 шкоди від сил природи ворогам поблизу. Шкода зменшується після $s1 цілей.\n\n\n\n|cFFFFFFFFГенерує $1272696s2 чі." },
    { en = "Voidblade damage increased by $s1%.\n\n\n\nHungering Slash deals $s2% increased damage to its primary target.", ua = "Шкода Клинка Порожнечі збільшена на $s1%.\n\n\n\nЖадібний розсік завдає на $s2% більше шкоди своїй основній цілі." },
    { en = "Your auto attack critical strike chance is increased by $s1%.", ua = "Шанс критичного удару твоїх автоатак збільшено на $s1%." },
    { en = "Consume deals $s1% increased damage and its cast time is reduced by ${-$s2/1000}.2 sec.", ua = "Поглинання завдає на $s1% більше шкоди, а час його творення скорочено на ${-$s2/1000}.2 сек." },
    { en = "$?c1[Invoke Niuzao, the Black Ox][Zenith] causes $?c1[Breath of Fire][Rising Sun Kick and Spinning Crane Kick] to launch $s1 Flurry Strikes.", ua = "$?c1[«Прикликання Ніузао, Чорного Вола»][«Зеніт»] змушує $?c1[«Подих вогню»][«Удар сонця, що сходить» і «Вихровий удар журавля»] випустити $s1 Шквальних ударів." },
    { en = "Soul Immolation generates an additional ${$s2*$1241937s3} Fury over its duration.", ua = "«Спалення душі» генерує додатково ${$s2*$1241937s3} од. люті за час своєї дії." },
    { en = "Reap's cooldown is reduced by your Haste.", ua = "Перезарядження «Жнив» скорочується від твого поспіху." },
    { en = "The cooldown of Roll is decreased by $s1%.", ua = "Перезарядження «Перекату» скорочено на $s1%." },
    { en = "Your critical strike chance is increased by $s1%.", ua = "Твій шанс критичного удару збільшений на $s1%." },
    { en = "Movement speed is increased by $1272850s1% for the first $1272850d of combat.", ua = "Швидкість руху збільшена на $1272850s1% протягом перших $1272850d бою." },
    { en = "Critical strike damage bonus increased by $s2%.", ua = "Бонус до шкоди критичних ударів збільшено на $s2%." },
    { en = "Deathstalker's Mark has a ${$s1/$s2*100}% chance to immediately consume a stack when applied.", ua = "Мітка смертоловця має ${$s1/$s2*100}% шансу негайно поглинути один заряд при накладанні." },
    { en = "Deathstalker's Mark deals $?c1[$s1][$s2]% of its normal damage to all other enemies within 8 yds $?c1[that are afflicted by Rupture][when a stack is consumed by Black Powder].", ua = "Тавро смертопереслідувача завдає $?c1[$s1][$s2]% своєї звичайної шкоди всім іншим ворогам у радіусі 8 ярдів, $?c1[які вражені Розривом][коли стак споживається Чорним порохом]." },
    { en = "Bestial Wrath summons an Animal Companion from your Stable to fight alongside you for $1282474d. The summoned Animal Companion obeys your Kill Command, Wild Thrash, and Stomps alongside your other pets.", ua = "«Звірячий гнів» прикликає звіра-компаньйона з твоєї стайні, який б'ється поруч із тобою протягом $1282474d. Прикликаний звір-компаньйон виконує «Наказ убити», «Дике шмагання» і «Тупіт» разом з іншими твоїми улюбленцями." },
    { en = "Overpower and Slam increase the damage of your next Mortal Strike by $316440s1%, stacking up to 3 times.", ua = "«Пересилення» та «Потужний удар» збільшують шкоду твого наступного «Смертельного удару» на $316440s1%, накопичуючись до 3 разів." },
    { en = "Damage dealt by your pets increased by $s1%.\n\n\n\nBestial Wrath strikes $s2 additional targets.", ua = "Шкода, яку завдають ваші улюбленці, збільшена на $s1%.\n\n\n\nЗвіриний гнів уражає $s2 додаткових цілей." },
    { en = "Cleave and Whirlwind deal $s1% additional damage to targets below $s2% health.", ua = "Розсічення та Вихор завдають на $s1% більше шкоди цілям, у яких менше ніж $s2% здоров'я." },
    { en = "Barbed Shot and Cobra Shot damage increased by $s1%.\n\n\n\nBarbed Shot, Cobra Shot, and Black Arrow increases the damage of your next Kill Command by $1276720s1%.", ua = "Шкода Шипастого пострілу й Пострілу кобри збільшується на $s1%.\n\n\n\nШипастий постріл, Постріл кобри та Чорна стріла збільшують шкоду вашого наступного Наказу вбити на $1276720s1%." },
    { en = "Aimed Shot always critically strikes.", ua = "«Прицільний постріл» завжди влучає критично." },
    { en = "Aimed Shot's critical strike damage is increased by $s4% of your critical strike chance.\n\n\n\nThe damage of your other ranged abilities is increased by $s2%.", ua = "Критична шкода Прицільного пострілу збільшується на $s4% від вашого шансу критичного удару.\n\n\n\nШкода ваших інших здібностей дальнього бою збільшується на $s2%." },
    { en = "Rapid Fire damage increased by $s1%.\n\n\n\nEach shot fired from Rapid Fire reduces the cooldown of Aimed Shot by ${$s2/1000}.2 sec.", ua = "Шкоду Швидкого вогню збільшено на $s1%.\n\n\n\nКожен постріл, випущений Швидким вогнем, зменшує перезарядження Прицільного пострілу на ${$s2/1000}.2 сек." },
    { en = "Celestial Conduit's healing and damage is increased by $s1% when striking a single target.\n\n\n\nEach addtional target reduces this bonus by $s2%.", ua = "Зцілення та шкода Небесного провідника збільшуються на $s1% при ударі по одній цілі.\n\n\n\nКожна додаткова ціль зменшує цей бонус на $s2%." },
    { en = "Lava Burst damage increased by $s1%.\n\n\n\nLava Burst and Lava Burst Overload generate $s2 additional Maelstrom.", ua = "Шкода «Лавового сплеску» збільшена на $s1%.\n\n\n\n«Лавовий сплеск» і «Перевантаження Лавового сплеску» генерують $s2 додаткового Виру." },
    { en = "Summoning your Demonic Tyrant leaves open a portal to Argus for $1276166d, causing every $s1 casts of Hand of Gul'dan to summon a subjugated demon that serves you for $1276182d.", ua = "Виклик демонічного тирана лишає відкритим портал до Аргуса на $1276166d, і кожні $s1 прочитань «Руки Ґул'дана» прикликають підкореного демона, що служить тобі протягом $1276182d." },
    { en = "Increases the duration of Dominion of Argus by ${$s1/1000} sec and increases damage dealt by Hand of Gul'dan by $s2%.", ua = "Збільшує тривалість Влади Аргуса на ${$s1/1000} сек. і збільшує шкоду Руки Ґул'дана на $s2%." },
    { en = "While Dominion of Argus is active, Hand of Gul'dan refunds ${$1276318s1/10} $lSoul Shard:Soul Shards;.\n\n\n\nDemons summoned by Dominion of Argus last an additional ${$s2/1000} sec.", ua = "Поки Влада Аргуса активна, Рука Ґул'дана повертає ${$1276318s1/10} $lуламок душі:уламки душі;.\n\n\n\nДемони, викликані Владою Аргуса, тривають на ${$s2/1000} сек довше." },
    { en = "Increases damage dealt by Hand of Gul'dan to its main target by $s1%.", ua = "Збільшує шкоду, яку Рука Ґул'дана завдає основній цілі, на $s1%." },
    { en = "Summons an Imp Lord to assist you in combat for $d and will remove 1 harmful effect from you when summoned. \n\n\n\nTransforms into Singe Magic while on cooldown.", ua = "Прикликає Лорда імпів, що допомагає вам у бою впродовж $d і знімає з вас 1 шкідливий ефект у мить прикликання. \n\n\n\nПід час перезарядження перетворюється на Обпалення магії." },
    { en = "Summons a Fel Ravager to assist you in combat for $d and will purge 1 beneficial magic effect from an enemy.\n\n\n\nTurns into Devour Magic while on cooldown.", ua = "Прикликає Спустошувача Скверни, що допомагає вам у бою впродовж $d і знімає 1 корисний магічний ефект з ворога.\n\n\n\nПід час перезарядження перетворюється на Пожирання магії." },
    { en = "Fazed increases damage taken by an additional $s1%.", ua = "Спантеличення додатково збільшує отримувану шкоду на $s1%." },
    { en = "Unseen Blade may now occur once every ${20-($s1/-1000)} sec and has $s2% chance to strike twice.", ua = "Невидиме лезо тепер може спрацьовувати раз на ${20-($s1/-1000)} сек. і має $s2% шансу вдарити двічі." },
    { en = "Increases the duration of your Summon Vilefiend, Grimoire: Imp Lord, and Grimoire: Fel Ravager by ${$s1/1000} sec.", ua = "Збільшує тривалість твоїх заклять Прикликання мерзотника, Гримуар: володар імпів та Гримуар: спустошувач Скверни на ${$s1/1000} сек." },
    { en = "Summons a Doomguard to assist you in combat for $d. Consuming a Demonic Core reduces the cooldown of Summon Doomguard by $s2 sec.\n\n\n\n$@spellicon1251989 $@spellname1251989\n\n$@spelldesc1251989", ua = "Викликає вартового погибелі, який допомагає вам у бою протягом $d. Споживання демонічного ядра скорочує перезарядження Виклику вартового погибелі на $s2 сек.\n\n\n\n$@spellicon1251989 $@spellname1251989\n\n$@spelldesc1251989" },
    { en = "$?c2[Pistol Shot][Shuriken Storm] has $?c2[$s1][$s2]% increased critical strike chance and now triggers Unseen Blade when available.", ua = "$?c2[Постріл з пістоля][Буря сюрикенів] має на $?c2[$s1][$s2]% збільшений шанс критичного удару й тепер запускає Незриме лезо, коли воно доступне." },
    { en = "Your Demonic Tyrant also empowers you while active, increasing your haste by $1276767s1%.", ua = "Твій демонічний тиран, поки активний, підсилює і тебе, збільшуючи твій поспіх на $1276767s1%." },
    { en = "Your Demonic Tyrant lasts an additional ${$s1/1000} sec and extends the duration of your Dreadstalkers by 15 sec when summoned.", ua = "Твій демонічний тиран існує на ${$s1/1000} сек. довше і при прикликанні подовжує тривалість твоїх ловчих жаху на 15 сек." },
    { en = "Flipping Heads increases damage by an additional $s1%. Damage dealt by flipping Tails is increased by $s2%.", ua = "Випадання орла додатково збільшує шкоду на $s1%. Шкоду від випадання решки збільшено на $s2%." },
    { en = "After flipping a Fatebound Coin that ends a streak of $s1 or more, flip another that matches the same face.", ua = "Коли підкидання доленосної монети завершує серію з $s1 або більше, підкидається ще одна монета, що падає тим самим боком." },
    { en = "Shield of the Righteous reduces magical damage taken by $s1%.", ua = "«Щит праведника» знижує отримувану магічну шкоду на $s1%." },
    { en = "Call Dreadstalkers costs $s1 less $lSoul Shard:Soul Shards; and its cast time is reduced by $s3%.", ua = "Заклик жахоблукачів коштує на $s1 $lуламок душі:уламки душі; менше, а час його прочитання зменшено на $s3%." },
    { en = "The fangs of your Dreadstalkers are coated in corrosive bile, causing Dreadbite to deal additional damage equal to $s1% of damage dealt as Plague damage.", ua = "Ікла твоїх ловчих жаху вкриті їдкою жовчю: «Укус жаху» завдає додаткової шкоди від пошесті в розмірі $s1% завданої шкоди." },
    { en = "Judgment causes its primary target's successful melee attacks against you to grant a Physical absorb shield for $s1% of the damage dealt. Limit $i.", ua = "Присуд робить так, що успішні атаки ближнього бою основної цілі проти вас надають фізичний поглинальний щит у розмірі $s1% завданої шкоди. Обмеження: $i." },
    { en = "Shield of the Righteous consumes up to $s2 more Holy Power and deals $s1% increased damage for each additional Holy Power consumed.", ua = "«Щит праведника» поглинає до $s2 додаткової Святої сили й завдає на $s1% більше шкоди за кожну додатково витрачену одиницю Святої сили." },
    { en = "Fight through the pain, ignoring $s2% of damage taken for $d or until ${($s1)*(1+$@versadmg)} damage has been prevented.", ua = "Перемагаєш біль, ігноруючи $s2% отриманої шкоди протягом $d або доки не буде відвернено ${($s1)*(1+$@versadmg)} шкоди." },
    { en = "Rising Sun Kick's damage is increased by your Mastery rating and Thunder Focus Tea resets its cooldown.", ua = "Шкода Удару висхідного сонця збільшена на величину твого показника майстерності, а Чай громового зосередження скидає його перезарядження." },
    { en = "While holding a shield, you have a $s2% chance to block incoming spells, reducing their damage by $s3%. \n\n\n\nWithout a shield, you have a $s4% chance to parry incoming melee attacks, reducing their damage by $s5%.", ua = "Поки ви тримаєте щит, ви маєте $s2% шанс блокувати вхідні закляття, зменшуючи їхню шкоду на $s3%. \n\n\n\nБез щита ви маєте $s4% шанс парирувати вхідні атаки ближнього бою, зменшуючи їхню шкоду на $s5%." },
    { en = "You heal for $s1% of all magical damage taken.", ua = "Ти зцілюєшся на $s1% усієї отриманої магічної шкоди." },
    { en = "When Surging Shots resets the cooldown of Rapid Fire, the damage of your next Rapid Fire is increased by $s1%.", ua = "Коли «Шквал пострілів» скидає перезарядження «Швидкого вогню», шкода твого наступного «Швидкого вогню» збільшується на $s1%." },
    { en = "When Rapid Fire begins and finishes channeling, it releases an Arcane Shot at $s1% effectiveness.\n\n\n\nIf your target is $?a466932[above 80% health or below 20%][below 20%] health, Rapid Fire instead releases $?a466932[Black Arrow][Kill Shot]s.", ua = "Коли Швидкий вогонь починає та завершує підтримання, він випускає Арканний постріл з $s1% ефективністю.\n\n\n\nЯкщо у вашої цілі $?a466932[понад 80% або менше 20%][менше 20%] здоров'я, Швидкий вогонь натомість випускає $?a466932[Чорні стріли][Смертельні постріли]." },
    { en = "$?c1[Black Arrow deals $s2% increased damage to enemies affected by Black Arrow's periodic damage.][Headshot can now stack $s1 additional $Ltime:times;.\n\n\n\n$@spellicon471363 $@spellname471363\n\n$@spelldesc471363]", ua = "$?c1[Чорна стріла завдає на $s2% більше шкоди ворогам, враженим періодичною шкодою Чорної стріли.][Постріл у голову тепер може накопичуватися на $s1 $Lраз:рази:разів; більше.\n\n\n\n$@spellicon471363 $@spellname471363\n\n$@spelldesc471363]" },
    { en = "Precise Shots now increases the critical strike chance of Arcane Shot and Multi-Shot by $s1%", ua = "Точні постріли тепер збільшують шанс критичного удару Арканного пострілу та Мультипострілу на $s1%" },
    { en = "Your healing is increased by up to $s2%, based on the average health percentage of allies with your Beacon of Light.", ua = "Твоє зцілення збільшено аж до $s2% залежно від середнього відсотка здоров'я союзників із твоїм «Маяком світла»." },
    { en = "Immediately reset the cooldowns of Adrenaline Rush, Between the Eyes, Blade Flurry, Blade Rush, and Killing Spree.", ua = "Миттєво скидає перезарядження «Припливу адреналіну», «Межи очі», «Шквалу клинків», «Натиску клинків» та «Шалу вбивств»." },
    { en = "When Frenzied Regeneration would heal you above maximum health, $s1% of its excess healing is instead converted to an absorb shield.", ua = "Коли «Несамовита регенерація» мала б зцілити тебе понад максимум здоров'я, $s1% надлишкового зцілення натомість перетворюється на щит поглинання." },
    { en = "When you take non-periodic damage, you have a chance to gain a charge of Dream Guide. \n\n\n\nWhen you or a nearby ally drops below $1278914s1% health, you consume a charge of Dream Guide to automatically cast Regrowth on them. This Regrowth heals for an additional $1278914s2%.", ua = "Коли ви отримуєте неперіодичну шкоду, ви маєте шанс отримати заряд Провідника Сну. \n\n\n\nКоли ваше здоров'я або здоров'я союзника поблизу падає нижче $1278914s1%, ви витрачаєте заряд Провідника Сну, щоб автоматично застосувати на нього Відростання. Це Відростання зцілює додатково на $1278914s2%." },
    { en = "Voidfall Meteor damage increased by $s1%.", ua = "Шкода «Метеора Порожнечепаду» збільшена на $s1%." },
    { en = "Shadow Word: Pain deals $s1% increased damage.", ua = "«Слово тіні: Біль» завдає на $s1% більше шкоди." },
    { en = "Tentacle Slam afflicts your target with Shadow Word: Madness at $s1% effectiveness.", ua = "«Удар мацака» накладає на твою ціль «Слово тіні: Безумство» з ефективністю $s1%." },
    { en = "Tentacle Slam deals $s2% increased damage and Void Volley deals $s1% increased damage.\n\n\n\nWhen Voidform ends, you can cast Void Volley $1279437U additional $Ltime:times; within $1279437d.", ua = "Удар щупальцем завдає на $s2% більше шкоди, а Залп Порожнечі завдає на $s1% більше шкоди.\n\n\n\nКоли Форма Порожнечі завершується, ви можете сотворити Залп Порожнечі $1279437U $Lдодатковий раз:додаткові рази; протягом $1279437d." },
    { en = "Shadowy Apparition damage increased by $s1%.\n\n\n\nWhen Shadowy Apparitions deal damage, they extend the duration of your Shadow Word: Pain and Vampiric Touch on the target by ${$s2/1000}.1 sec.", ua = "Шкоду «Тіньової примари» збільшено на $s1%.\n\n\n\nКоли Тіньові примари завдають шкоди, вони подовжують тривалість ваших «Слова тіні: Біль» і «Вампірського дотику» на цілі на ${$s2/1000}.1 сек." },
    { en = "Secret Technique damage increased by $s1%.", ua = "Шкода «Таємної техніки» збільшена на $s1%." },
    { en = "Increases damage dealt by Agony and $?a445465[Wither][Corruption] by $s1%.", ua = "Підвищує шкоду від Агонії та $?a445465[В'янення][Псування] на $s1%." },
    { en = "Increases the duration of Summon Darkglare by ${$s1/1000}.1 sec.", ua = "Збільшує тривалість Прикликання темнозора на ${$s1/1000}.1 сек." },
    { en = "Increases the damage of your Felguard's Felstorm by $s1% and its duration by ${$s2/1000}.1 sec.", ua = "Збільшує шкоду Бурі Скверни твого вартового Скверни на $s1%, а її тривалість — на ${$s2/1000}.1 сек." },
    { en = "While Blood Shield is active, taking direct damage reflects $1279656s1 Shadow damage back to the attacker. Blood Shield can now absorb up to $s1% of your maximum health.", ua = "Поки діє «Кривавий щит», пряма шкода, якої ти зазнаєш, відбиває $1279656s1 тіньової шкоди в нападника. «Кривавий щит» тепер може поглинути до $s1% твого максимального здоров'я." },
    { en = "Your Earth Elemental no longer taunts nearby enemies or generates threat and instead increases your maximum health by $381755s1% while active.", ua = "Твій елементаль землі більше не провокує ворогів поблизу і не створює загрози; натомість, поки він активний, твоє максимальне здоров'я збільшене на $381755s1%." },
    { en = "Your Penance bolts sear the enemy, dealing $s1% of its damage over 8 sec.", ua = "Заряди твоєї Покути обпалюють ворога, завдаючи $s1% її шкоди протягом 8 сек." },
    { en = "Evangelism summons a Mindbender to attack a nearby target for $123040d.\n\n\n\n|cFFFFFFFFGenerates ${$123051m1/100}.1% Mana each time the Mindbender attacks.|r", ua = "«Євангелізм» прикликає Розумокрута, що атакує найближчу ціль протягом $123040d.\n\n\n\n|cFFFFFFFFГенерує ${$123051m1/100}.1% мани щоразу, коли Розумокрут атакує.|r" },
    { en = "Conjuring one or more $?c1[Arcane][Frost] Splinters has a $s1% chance to conjure a burst of $s2 $?c1[Arcane][Frost] $LSplinter:Splinters;.", ua = "Створення одного або кількох $?c1[арканних][крижаних] осколків має $s1% шанс створити сплеск із $s2 $?c1[арканних][крижаних] $Lосколок:осколків;." },
    { en = "Renewing Mist's healing is increased by $s1% on your lowest health ally with its effect.", ua = "Зцілення Оновлювального туману збільшено на $s1% для союзника під його дією з найменшим здоров'ям." },
    { en = "When Shred or Moonfire generate combo points, they have a $h% chance to generate full combo points.", ua = "Коли «Шматування» чи «Місячний вогонь» створюють очки комбо, є $h% шансу, що вони створять повний запас очок комбо." },
    { en = "Reduces the cooldown of Summon Infernal by ${$s1/-1000}.1 sec and increases your Mastery by $s2%.", ua = "Зменшує перезарядження «Прикликання інфернала» на ${$s1/-1000}.1 сек. і збільшує твою майстерність на $s2%." },
    { en = "$?a137008[Blood Plague deals up to $s2%][Your plagues deal up to $s1%] increased damage based on the target's missing health.$?a137007[\n\n\n\nVampiric Strike grants maximum stacks of Clawing Shadows.][]", ua = "$?a137008[Кривава пошесть завдає до $s2%][Ваші пошесті завдають до $s1%] більше шкоди залежно від нестачі здоров'я цілі.$?a137007[\n\n\n\nВампірський удар надає максимум стопок Дряпучих тіней.][]" },
    { en = "Adorns your Darkglare with armor forged from within Antorus, increasing their armor by $1280940s1%. \n\n\n\nEye Beam now jumps to up to $s1 additional targets within $s2 yards and deals $s3% increased damage.", ua = "Споряджає вашого Похмурозора бронею, викуваною в Анторусі, збільшуючи його броню на $1280940s1%. \n\n\n\nПромінь ока тепер перескакує на до $s1 додаткових цілей у межах $s2 ярдів і завдає на $s3% більше шкоди." },
    { en = "Glacial Spike deals $s2% increased damage and applies $s1 additional $Lstack:stacks; of Freezing.", ua = "Льодовиковий шпиль завдає на $s2% більше шкоди та накладає $s1 додатковий заряд:додаткові заряди; Замерзання." },
    { en = "Glacial Spike no longer applies Freezing, and instead Shatters $s1 $Lstack:stacks; of Freezing.", ua = "«Льодовиковий шпиль» більше не накладає Заморожування, а натомість розтрощує $s1 $Lстак:стаки; Заморожування." },
    { en = "Chaos Bolt and Shadowburn have a $s1% chance to rip open a hole in space and time, opening a random portal that damages your target:\n\n\n\n$@spellicon394235$@spellname394235\n\n$@spelldesc394235\n\n\n\n$@spellicon387979$@spellname387979\n\n$@spelldesc387979\n\n\n\n$@spellicon394243$@spellname394243\n\n$@spelldesc394243\n\n\n\n|cFFFFFFFFGenerates $s2 Soul Shard Fragments.|r", ua = "Снаряд хаосу й Тіньовий спалах мають $s1% шанс розірвати діру в просторі й часі, відкривши випадковий портал, що завдає шкоди вашій цілі:\n\n\n\n$@spellicon394235$@spellname394235\n\n$@spelldesc394235\n\n\n\n$@spellicon387979$@spellname387979\n\n$@spelldesc387979\n\n\n\n$@spellicon394243$@spellname394243\n\n$@spelldesc394243\n\n\n\n|cFFFFFFFFПороджує $s2 фрагменти(ів) уламків душі.|r" },
    { en = "Your stances have additional effects.\n\n\n\n$?c1|c3[$@spellicon386164 $@spellname386164\n\nIncreases the critical strike damage of your abilities by $386164s4%.][$@spellicon386196 $@spellname386196\n\nIncreases your auto-attack speed by $386196s6%.]\n\n\n\n$@spellicon386208 $@spellname386208\n\nWhen an attack deals $386208s5% or more of your maximum health in damage, that damage is reduced by $386208s6%.", ua = "Ваші стійки мають додаткові ефекти.\n\n\n\n$?c1|c3[$@spellicon386164 $@spellname386164\n\nЗбільшує шкоду критичного удару ваших здібностей на $386164s4%.][$@spellicon386196 $@spellname386196\n\nЗбільшує швидкість ваших автоатак на $386196s6%.]\n\n\n\n$@spellicon386208 $@spellname386208\n\nКоли атака завдає шкоди в розмірі $386208s5% або більше вашого максимального здоров'я, цю шкоду зменшено на $386208s6%." },
    { en = "Shadow Clones deal $s1% increased damage.\n\n\n\nCheap Shot creates a Shadow Clone to Shadowstrike the target for $s2% of normal damage as Shadow.\n\n\n\nKidney Shot creates a Shadow Clone to Eviscerate the target for $s2% of normal damage as Shadow.", ua = "Тіньові клони завдають на $s1% більше шкоди.\n\n\n\n«Підлий удар» створює Тіньового клона, що вражає ціль «Тіньовим ударом» на $s2% від звичайної шкоди як Тіньова.\n\n\n\n«Удар по нирках» створює Тіньового клона, що потрошить ціль «Потрошінням» на $s2% від звичайної шкоди як Тіньова." },
    { en = "Power Siphon and Implosion summon $s1 Imp Gang Boss for every $s2 Wild Imps sacrificed. Wild Imps summoned this way gain Unstable Soul.\n\n\n\n$@spellicon1281512 $@spellname1281512\n\n$@spelldesc1281512", ua = "Висмоктування сили та Імплозія викликають $s1 ватажка зграї бісів за кожні $s2 принесених у жертву диких бісів. Дикі біси, викликані в такий спосіб, отримують Нестабільну душу.\n\n\n\n$@spellicon1281512 $@spellname1281512\n\n$@spelldesc1281512" },
    { en = "Ice Lance reduces the cooldown of Frozen Orb by ${$s1/1000}.1 sec, increased by ${$s2/1000}.1 sec for each stack of Freezing Shattered.", ua = "«Крижаний спис» скорочує перезарядження «Замороженої сфери» на ${$s1/1000}.1 сек; це скорочення збільшується на ${$s2/1000}.1 сек за кожен розтрощений заряд «Заморозки»." },
    { en = "Will the Light to coalesce and become manifest as a Holy Armament, wielded by your target.\n\n\n\n$@spellicon432502 $@spellname432502: \n\n\n\n$@spelldesc432502\n\n\n\nBecomes Holy Bulwark after use.$?c1[\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.][]", ua = "Волею змушує Світло зосередитися й утілитися як Священна Зброя, якою володіє ваша ціль.\n\n\n\n$@spellicon432502 $@spellname432502: \n\n\n\n$@spelldesc432502\n\n\n\nПісля застосування стає Священним Бастіоном.$?c1[\n\n\n\n|cFFFFFFFFГенерує $s2 Священної Сили.][]" },
    { en = "Putrefy reduces the cooldown of Death and Decay by ${$s1/1000}.1 sec.\n\n\n\nDeath and Decay reduces the cooldown of Putrefy by ${$s2/1000}.1 sec for each enemy it damages, up to ${$s3/1000}.1 sec.", ua = "Гниття скорочує перезарядження Смерті й розкладу на ${$s1/1000}.1 сек.\n\n\n\nСмерть і розклад скорочує перезарядження Гниття на ${$s2/1000}.1 сек. за кожного ворога, якому завдає шкоди, до ${$s3/1000}.1 сек." },
    { en = "Inferno's Blessing's damage is increased by $s1%, and your effects that extend Ebon Might also extend Inferno's Blessing.", ua = "Шкода Благословення інферно збільшена на $s1%, а твої ефекти, що подовжують Ебенову міць, подовжують і Благословення інферно." },
    { en = "Living Flame's cast time is reduced by ${$s1/-1000}.1 sec, and it deals $s2% increased damage or healing when it is a non-instant cast.", ua = "Час творення «Живого полум'я» скорочено на ${$s1/-1000}.1 сек, і воно завдає на $s2% більше шкоди чи зцілення, коли твориться не миттєво." },
    { en = "Send out a ripple of temporal energy, absorbing $s1 damage and applying Echo at $s3% effectiveness on your target and up to $s2 allies within $a1 yds.", ua = "Випускає хвилю часової енергії, що поглинає $s1 шкоди й накладає «Відлуння» з $s3% ефективності на твою ціль і до $s2 союзників у радіусі $a1 м." },
    { en = "If the target of your Deathmark dies, Deathmark jumps to a nearby enemy combatant for its remaining duration.", ua = "Якщо ціль твоєї «Мітки смерті» гине, «Мітка смерті» перестрибує на ворожого бійця поблизу на решту своєї тривалості." },
    { en = "When you deal the killing blow to a target that yields experience or honor, the cooldown of Crimson Vial is reduced by ${-$s2/1000} sec and your next use heals $1293149s1% of your health instantly.", ua = "Коли ти завдаєш смертельного удару цілі, що дає досвід або честь, перезарядження Багряного фіала скорочується на ${-$s2/1000} сек., а наступне використання миттєво зцілює $1293149s1% твого здоров'я." },
    { en = "Fill the target with faith in the light, healing for $o1 over $d.", ua = "Сповнює ціль вірою у Світло, зцілюючи на $o1 протягом $d." },
    { en = "Assaults the target's mind with Shadow energy, causing $o1 Shadow damage over $d and slowing their movement speed by $s2%.\n\n\n\n|cFFFFFFFFGenerates ${$s4*$s3/100} Insanity over the duration.|r", ua = "Атакує розум цілі тіньовою енергією, завдаючи $o1 шкоди Тіні протягом $d та сповільнюючи її швидкість пересування на $s2%.\n\n\n\n|cFFFFFFFFСтворює ${$s4*$s3/100} Безумства за час дії.|r" },
    { en = "Places a ward on an ally that heals them for $33110s1 the next time they take damage, and then jumps to another ally within $155793a1 yds. Jumps up to $s1 times and lasts $41635d after each jump.", ua = "Накладає на союзника оберіг, що зцілює його на $33110s1, коли він наступного разу зазнає шкоди, а потім перестрибує на іншого союзника в межах $155793a1 ярдів. Перестрибує до $s1 разів і триває $41635d після кожного стрибка." },
    { en = "Summons a Demonic Circle for $d. Cast Demonic Circle: Teleport to teleport to its location and remove all movement slowing effects.$?s58081[\n\n\n\nIf you cast Demonic Circle: Summon while controlling an Eye of Kilrogg, the circle will appear where the eye is located.][]", ua = "Прикликає Демонічне коло на $d. Застосуйте Демонічне коло: Телепорт, щоб телепортуватися до його місця й зняти всі ефекти сповільнення пересування.$?s58081[\n\n\n\nЯкщо ви застосуєте Демонічне коло: Прикликання, керуючи Оком Кілроґґа, коло з'явиться там, де перебуває око.][]" },
    { en = "Teleports you to your Demonic Circle and removes all movement slowing effects.", ua = "Телепортує вас до вашого Демонічного кола та знімає всі ефекти сповільнення пересування." },
    { en = "Your pet removes all root and movement impairing effects from itself and a friendly target, and grants immunity to all such effects for $54216d.", ua = "Ваш улюбленець знімає всі ефекти знерухомлення та обмеження пересування з себе й дружньої цілі та надає несприйнятливість до всіх таких ефектів на $54216d." },
    { en = "Consumes 1 stack of Mana Tea per $t1 sec to restore $s1 Mana.\n\n\n\nCan be cast while moving, but movement speed is reduced by $s2% while channeling.", ua = "Споживає 1 стак Чаю з мани кожні $t1 сек, відновлюючи $s1 мани.\n\n\n\nМожна творити в русі, але швидкість пересування знижена на $s2% під час підтримання." },
    { en = "Creates a barrier of holy light that absorbs $<shield> damage for $d.\n\n\n\nWhen the shield expires, it bursts to inflict Holy damage equal to the total amount absorbed, divided among all nearby enemies.", ua = "Створює бар'єр зі святого світла, що поглинає $<shield> шкоди протягом $d.\n\n\n\nКоли щит завершується, він вибухає, завдаючи шкоди Святом, рівної загальній поглиненій кількості, поділеної між усіма ворогами поблизу." },
    { en = "Wraps an ally in shadows which heal for $s1, but at a price.\n\n\n\nThe ally will take ${$s1/20} damage every $187464t1 sec, until they have taken ${$s1/2} total damage from all sources, or leave combat.", ua = "Огортає союзника тінями, що зцілюють на $s1, але за свою ціну.\n\n\n\nСоюзник зазнаватиме ${$s1/20} шкоди кожні $187464t1 сек, доки не зазнає загалом ${$s1/2} шкоди з усіх джерел або не вийде з бою." },
    { en = "An infectious plague that spreads to all nearby enemies, dealing $o Shadow damage over $d.", ua = "Заразна пошесть, що поширюється на всіх ворогів поблизу, завдаючи $o шкоди Тіні протягом $d." },
    { en = "Assaults the target's mind with Shadow energy, causing $o1 Shadow damage over $d and slowing their movement speed by $s3%.\n\n\n\n|cFFFFFFFFGenerates ${$s2*$377358s1/100} Insanity over the duration.|r", ua = "Атакує розум цілі тіньовою енергією, завдаючи $o1 шкоди Тіні протягом $d та сповільнюючи її швидкість пересування на $s3%.\n\n\n\n|cFFFFFFFFСтворює ${$s2*$377358s1/100} Безумства за час дії.|r" },
    { en = "Surrounds you with a barrier of whirling bones, increasing Armor by ${$s1*$STR/100}$?s316746[, and your Haste by $s4%][]. Each melee attack against you consumes a charge. Lasts $d or until all charges are consumed.", ua = "Оточує вас бар'єром із вируючих кісток, підвищуючи Броню на ${$s1*$STR/100}$?s316746[, а ваш Поспіх — на $s4%][]. Кожна атака ближнього бою по вас споживає заряд. Триває $d або доки не вичерпаються всі заряди." },
    { en = "You gain:\n\n\n\n$@spellicon16931 $@spellname16931\n\n$@spelldesc16931\n\n\n\nYou also learn:\n\n\n\n$@spellicon77758 $@spellname77758\n\n$@spellicon22842 $@spellname22842\n\n$@spellicon99 $@spellname99", ua = "Ви отримуєте:\n\n\n\n$@spellicon16931 $@spellname16931\n\n$@spelldesc16931\n\n\n\nВи також вивчаєте:\n\n\n\n$@spellicon77758 $@spellname77758\n\n$@spellicon22842 $@spellname22842\n\n$@spellicon99 $@spellname99" },
    { en = "Strikes all enemies nearby for $?s405289[${$198137sw1*1.05} Radiant][$198137sw1 Holy] damage every $t sec. Deals reduced damage beyond 8 targets.", ua = "Б'є всіх ворогів поблизу, завдаючи $?s405289[${$198137sw1*1.05} променистої][$198137sw1 святої] шкоди кожні $t сек. Завдає зменшеної шкоди понад 8 цілей." },
    { en = "Conjures a massive spike of ice that impales your target, dealing $228600s1 damage and slowing the target's movement speed by $205708s1% for $205708d.\n\n\n\n$?a1280780[|CFFffffffShatters $1280780s1 $lstack:stacks; of Freezing.|R][|CFFffffffApplies $1246769s3 $lstack:stacks; of Freezing.|R]", ua = "Прикликає велетенський крижаний шпиль, що пронизує вашу ціль, завдаючи $228600s1 шкоди та сповільнюючи швидкість пересування цілі на $205708s1% на $205708d.\n\n\n\n$?a1280780[|CFFffffffРозбиває $1280780s1 $lнакладення:накладень; Заморожування.|R][|CFFffffffНакладає $1246769s3 $lнакладення:накладень; Заморожування.|R]" },
    { en = "Summons a Mindbender to attack the target for $d.\n\n\n\n|cFFFFFFFFGenerates ${$200010s1/100} Insanity each time the Mindbender attacks.|r", ua = "Прикликає Розумокрута, що атакує ціль протягом $d.\n\n\n\n|cFFFFFFFFЩоразу, коли Розумокрут атакує, ви отримуєте ${$200010s1/100} Безумства.|r" },
    { en = "$?a387506[Your single target spells have a $387506s1% chance to curse][Curses] the ground with a demonic bane, causing all of your single target spells to also strike targets marked with the bane for  $80240s1% of the damage dealt. Lasts $?a387506[${$387506s3/1000} sec][$d].", ua = "$?a387506[Ваші закляття по одній цілі мають $387506s1% шанс проклясти][Проклинає] землю демонічною згубою, через що всі ваші закляття по одній цілі також уражають позначені згубою цілі на $80240s1% завданої шкоди. Триває $?a387506[${$387506s3/1000} сек][$d]." },
    { en = "You gain:\n\n\n\n$@spellicon131768 $@spellname131768\n\n$@spelldesc131768\n\n\n\nYou also learn:\n\n\n\n$@spellicon1822 $@spellname1822\n\n$@spellicon1079 $@spellname1079\n\n$@spellicon22570 $@spellname22570\n\n\n\nYour energy regeneration is increased by $s2%.", ua = "Ви отримуєте:\n\n\n\n$@spellicon131768 $@spellname131768\n\n$@spelldesc131768\n\n\n\nВи також вивчаєте:\n\n\n\n$@spellicon1822 $@spellname1822\n\n$@spellicon1079 $@spellname1079\n\n$@spellicon22570 $@spellname22570\n\n\n\nВідновлення вашої енергії підвищено на $s2%." },
    { en = "Burns the target for $s1 Astral damage, and then an additional $o2 damage over $d. If dispelled, causes $356474s1 damage to the dispeller and blasts them upwards.\n\n\n\n|cFFFFFFFFGenerates ${$m3/10} Astral Power.|r", ua = "Випалює ціль, завдаючи $s1 астральної шкоди, а потім ще $o2 шкоди протягом $d. У разі розвіювання завдає $356474s1 шкоди тому, хто розвіяв, і підкидає його вгору.\n\n\n\n|cFFFFFFFFСтворює ${$m3/10} Астральної Сили.|r" },
    { en = "Drink an alchemical concoction that heals you for $o1% of your maximum health over $d.", ua = "Випиваєте алхімічне зілля, що зцілює вас на $o1% вашого максимального здоров'я протягом $d." },
    { en = "Summon a Healing Sphere visible only to you. Moving through this Healing Sphere heals you for $124507s1.", ua = "Прикликає сферу зцілення, видиму лише вам. Проходячи крізь цю сферу зцілення, ви відновлюєте $124507s1 здоров'я." },
    { en = "Causes the target to suffer $o1 Bleed damage over $d. If this effect is reapplied, any remaining damage will be added to the new Deep Wounds.", ua = "Завдає цілі $o1 шкоди від кровотечі протягом $d. Якщо цей ефект застосувати повторно, будь-яка залишкова шкода додається до нових Глибоких ран." },
    { en = "Send the fiery soul of a fallen demon at the enemy, causing $s1 Shadowflame damage.$?c2[\n\n\n\n|cFFFFFFFFGenerates 2 Soul Shards.|r][]", ua = "Насилає вогненну душу полеглого демона на ворога, завдаючи $s1 шкоди Тіньового полум'я.$?c2[\n\n\n\n|cFFFFFFFFСтворює 2 Уламки душі.|r][]" },
    { en = "You and your pet gain $s1% increased movement speed.", ua = "Ви та ваш улюбленець отримуєте на $s1% більшу швидкість пересування." },
    { en = "You and your pet gain $s1% increased maximum health.", ua = "Ви та ваш улюбленець отримуєте $s1% до максимального здоров'я." },
    { en = "Increases haste by $s1% for all party and raid members for $d.\n\n\n\nAllies receiving this effect will become Sated and unable to benefit from Primal Rage or similar effects again for $57724d.", ua = "Збільшує поспіх на $s1% усім членам групи та рейду протягом $d.\n\n\n\nСоюзники, які отримують цей ефект, стають Насиченими й не можуть знову скористатися Первісною Люттю чи подібними ефектами протягом $57724d." },
    { en = "When your Wild Imps fade or are imploded, you have a $s1% chance to absorb their life essence, granting you a stack of Demonic Core. \n\n\n\nWhen your summoned Dreadstalkers fade away, you have a $s2% chance to absorb their life essence, granting you a stack of Demonic Core.\n\n\n\nDemonic Core reduces the cast time of Demonbolt by $264173s1%. Maximum $264173u stacks.", ua = "Коли ваші Дикі біси зникають або вибухають, ви маєте $s1% шанс поглинути їхню життєву есенцію, отримуючи накладення Демонічного ядра.\n\n\n\nКоли ваші прикликані Жахослідці зникають, ви маєте $s2% шанс поглинути їхню життєву есенцію, отримуючи накладення Демонічного ядра.\n\n\n\nДемонічне ядро зменшує час прочитання Демонічної блискавки на $264173s1%. Максимум $264173u накладень." },
    { en = "Deals $m1 Astral damage to the target and nearby enemies, and resets Full Moon to become New Moon. Deals reduced damage to secondary targets.\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Astral Power.|r", ua = "Завдає $m1 астральної шкоди цілі та ворогам поблизу й скидає Повний місяць до Молодого місяця. Завдає зменшеної шкоди другорядним цілям.\n\n\n\n|cFFFFFFFFСтворює ${$m2/10} Астральної Сили.|r" },
    { en = "Judges the target, dealing $s1 Holy damage$?s231644[, and preventing $<shield> damage dealt by the target][].$?s315867[\n\n\n\n|cFFFFFFFFGenerates $220637s1 Holy Power.][]", ua = "Виносить вирок цілі, завдаючи $s1 шкоди Світла$?s231644[ та запобігаючи $<shield> шкоди, завданої ціллю][].$?s315867[\n\n\n\n|cFFFFFFFFСтворює $220637s1 Священної сили.][]" },
    { en = "Interrupt and Silence effects on party and raid members within $a1 yds are $s1% shorter. $?a339124[Fear effects are also reduced.][]", ua = "Ефекти переривання та німоти на учасниках групи й рейду в межах $a1 ярдів коротші на $s1%. $?a339124[Ефекти страху також зменшені.][]" },
    { en = "Abilities not associated with your specialization are substantially empowered for $d.$?!s137013[\n\n\n\n|cFFFFFFFFBalance:|r Cast time of Balance spells reduced by $s13% and damage increased by $s1%.][]$?!s137011[\n\n\n\n|cFFFFFFFFFeral:|r Gain $s14 Combo Point every $t14 sec while in Cat Form and Physical damage increased by $s4%.][]$?!s137010[\n\n\n\n|cFFFFFFFFGuardian:|r Bear Form gives an additional $s7% Stamina, multiple uses of Ironfur may overlap, and Frenzied Regeneration has ${$s9+1} charges.][]$?!s137012[\n\n\n\n|cFFFFFFFFRestoration:|r Healing increased by $s10%, and mana costs reduced by $s12%.][]", ua = "Здібності, не пов'язані з вашою спеціалізацією, суттєво підсилені на $d.$?!s137013[\n\n\n\n|cFFFFFFFFБаланс:|r Час застосування заклять Балансу зменшено на $s13%, а шкоду збільшено на $s1%.][]$?!s137011[\n\n\n\n|cFFFFFFFFЛютий звір:|r Дає $s14 Комбо-очко кожні $t14 с у Котячій подобі, а фізичну шкоду збільшено на $s4%.][]$?!s137010[\n\n\n\n|cFFFFFFFFСтраж:|r Подоба ведмедя дає додатково $s7% Витривалості, повторні застосування Залізної шкури можуть накладатися, а Несамовита регенерація має ${$s9+1} заряди.][]$?!s137012[\n\n\n\n|cFFFFFFFFВідновлення:|r Зцілення збільшено на $s10%, а витрати мани зменшено на $s12%.][]" },
    { en = "Release a powerful burst of anima, dealing up to $s1 Arcane damage, based on the number of enemies, and $325041s1 healing to up to $325041s2 allies within $A1 yds.\n\n\n\nGrants $s3 $lstack:stacks; of Boon of the Ascended for each target damaged.", ua = "Вивільняє потужний сплеск аніми, завдаючи до $s1 арканної шкоди залежно від кількості ворогів та зцілюючи на $325041s1 до $325041s2 союзників у межах $A1 ярдів.\n\n\n\nНадає $s3 $lнакладення:накладень; Благодаті Піднесених за кожну уражену ціль." },
    { en = "Deals up to $o1 Shadow damage based on number of targets over $d. Allies who damage this target are healed for ${$325118s1*$<mult>}.", ua = "Завдає до $o1 шкоди Тіні залежно від кількості цілей протягом $d. Союзники, що завдають шкоди цій цілі, зцілюються на ${$325118s1*$<mult>}." },
    { en = "Blasts the enemy with pure Anima, causing $s1 Arcane damage and healing a nearby ally for $s2% of the damage done.\n\n\n\nGrants $s3 $lstack:stacks; of Boon of the Ascended.", ua = "Уражає ворога чистою анімою, завдаючи $s1 арканної шкоди та зцілюючи союзника поблизу на $s2% завданої шкоди.\n\n\n\nНадає $s3 $lнакладення:накладень; Благодаті Піднесених." },
    { en = "Explode for up to $s1 Arcane damage to enemies and $347625s1 healing to allies within $A1 yds, based on number of targets. Damage and healing increased by $325013s5% for each stack of Boon of the Ascended.", ua = "Вибухає, завдаючи до $s1 арканної шкоди ворогам та зцілюючи на $347625s1 союзників у межах $A1 ярдів залежно від кількості цілей. Шкода й зцілення підвищуються на $325013s5% за кожне накладення Благодаті Піднесених." },
    { en = "Energize your bonded partner, granting them $327139s1% of your damage as additional Arcane damage, healing, or absorption.", ua = "Наснажує вашого зв'язаного напарника, надаючи йому $327139s1% вашої шкоди як додаткову арканну шкоду, зцілення чи поглинання." },
    { en = "Protect your bonded partner, redirecting $s1% of damage they take to you, unless you fall below $s3% health.", ua = "Захищає вашого зв'язаного напарника, перенаправляючи $s1% завданої йому шкоди на вас, доки ваше здоров'я не опуститься нижче $s3%." },
    { en = "Focus on your bonded partner, replicating $327148s1% of all healing you deal onto them.", ua = "Зосереджується на вашому зв'язаному напарнику, копіюючи на нього $327148s1% усього зцілення, яке ви здійснюєте." },
    { en = "Erupt a burst of fiery damage from all targets affected by your Flame Shock, dealing $333977s1 Volcanic damage to up to $333977I targets within $333977A1 yds of your Flame Shock targets.", ua = "Спричиняє спалах вогняної шкоди від усіх цілей, уражених вашим Полум'яним шоком, завдаючи $333977s1 вулканічної шкоди до $333977I цілям у радіусі $333977A1 ярдів від цілей вашого Полум'яного шоку." },
    { en = "Strike a mighty blow with both weapons that deals a total of ${$335098s1+$335100s1} Physical damage. \n\n\n\nCrushing Blow has a $s1% chance to instantly reset its own cooldown and its critical strikes deal $1719s13% additional damage.\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Rage.|r", ua = "Завдає могутнього удару обома зброями, що загалом завдає ${$335098s1+$335100s1} фізичної шкоди.\n\n\n\nНищівний удар має $s1% шанс миттєво скинути власне перезарядження, а його критичні удари завдають $1719s13% додаткової шкоди.\n\n\n\n|cFFFFFFFFСтворює ${$m2/10} Люті.|r" },
    { en = "An explosion bombards the target area with white-hot embers, dealing ${$369374s1*$s1} Fire damage to enemies over $369372d.", ua = "Вибух засипає цільову ділянку розпеченими до білого вуглинами, завдаючи ${$369374s1*$s1} вогняної шкоди ворогам протягом $369372d." },
    { en = "Hurls a bolt of dark magic, dealing $s1 Shadow damage and ${$s1*$s2/100} Shadow damage to all enemies within $a1 yards of the target. Damage reduced beyond $s3 targets.", ua = "Метає заряд темної магії, завдаючи $s1 тіньової шкоди та ${$s1*$s2/100} тіньової шкоди всім ворогам у межах $a1 ярдів від цілі. Шкода зменшується після $s3 цілей." },
    { en = "Aimed Shot now has a $s2% chance and Rapid Fire now has a $s1% chance to grant Deathblow.\n\n\n\n$?a466932[Black Arrow][Kill Shot] critical strike damage is increased by $s3%.\n\n\n\n$@spellicon378770 $@spellname378770\n\nThe cooldown of $?a466932[Black Arrow][Kill Shot] is reset. $@spellaura378770", ua = "Прицільний постріл тепер має шанс $s2%, а Швидкий вогонь — шанс $s1% надати Смертельний удар.\n\n\n\nКритична шкода $?a466932[Чорної стріли][Добивального пострілу] збільшена на $s3%.\n\n\n\n$@spellicon378770 $@spellname378770\n\nПерезарядження $?a466932[Чорної стріли][Добивального пострілу] скидається. $@spellaura378770" },
    { en = "The dead erupt beneath all foes with Virulent Plague, dealing $383313s1 Shadow damage and $383313s2 Shadow damage to enemies nearby.", ua = "Мертві проривають землю під усіма ворогами, ураженими Згубною Чумою, завдаючи $383313s1 тіньової шкоди та $383313s2 тіньової шкоди ворогам поблизу." },
    { en = "Pyroblast and Flamestrike have no cast time, are guaranteed to critically strike, and increase the damage of Pyroblast and Flamestrike by $1242220s1%.", ua = "Піровибух і Вогняний Удар не мають часу прочитання, гарантовано завдають критичного удару та підвищують шкоду Піровибуху і Вогняного Удару на $1242220s1%." },
    { en = "When Shield of the Righteous expires, gain $386556s1% block chance and deal $386553s1 Holy damage to all attackers for $386556d.", ua = "Коли Щит Праведника зникає, ви отримуєте $386556s1% шансу блокування та завдаєте $386553s1 священної шкоди всім нападникам протягом $386556d." },
    { en = "Drain Life heals for $s1% more while below $s2% health.", ua = "Висмоктування Життя зцілює на $s1% більше, коли здоров'я нижче за $s2%." },
    { en = "When you use a Healthstone, gain $s2% Leech for $386647d.", ua = "Коли ви використовуєте камінь здоров'я, ви отримуєте $s2% висмоктування на $386647d." },
    { en = "Reduces Stagger by $<reduc>.", ua = "Зменшує Розкладання шкоди на $<reduc>." },
    { en = "Deals ${$387985s1*($387984d/$387984t1)} Chaos damage over $387984d.", ua = "Завдає ${$387985s1*($387984d/$387984t1)} шкоди хаосу протягом $387984d." },
    { en = "Damage taken reduced by $388035s2%.", ua = "Отримана шкода зменшена на $388035s2%." },
    { en = "Teleports you back to where you last $?s212653[Shimmered][Blinked]. Castable while casting and unaffected by the global cooldown.", ua = "Телепортує вас назад до місця, звідки ви востаннє застосували $?s212653[Мерехтіння][Стрибок]. Можна творити під час іншого читання й не залежить від глобального перезарядження." },
    { en = "Fire an enchanted arrow, dealing $392058s1 Shadow damage to your target and an additional $392058s2 Shadow damage to all enemies within $392058A2 yds of your target. Non-Player targets struck by a Wailing Arrow have their spellcasting interrupted and are silenced for $392061d.\n\n\n\n|cFFFFFFFFGrants Deathblow.|r", ua = "Випускаєте зачаровану стрілу, завдаючи $392058s1 шкоди Тіні вашій цілі та додаткові $392058s2 шкоди Тіні всім ворогам у межах $392058A2 м від вашої цілі. Цілям, що не є гравцями, уражені Стрілою голосіння перериває прочитання заклять і знемовлює їх на $392061d.\n\n\n\n|cFFFFFFFFНадає Смертельний удар.|r" },
    { en = "Deals ${$394238s1*($394237d/$394237t1)} Shadow damage over $394237d.", ua = "Завдає ${$394238s1*($394237d/$394237t1)} тіньової шкоди протягом $394237d." },
    { en = "Fires a Chaos Bolt, dealing $s1 Chaos damage. This Chaos Bolt always critically strikes and your critical strike chance increases its damage.", ua = "Випускає Стрілу хаосу, завдаючи $s1 шкоди хаосом. Ця Стріла хаосу завжди завдає критичного удару, а ваш шанс критичного удару збільшує її шкоду." },
    { en = "Corrosive shadow energy radiates from the target, dealing ${$394979s2*$s2} Shadow damage over $d to all enemies within $394979a2 yards of the target. Damage reduced beyond $394979s3 targets.\n\n\n\n|cFFFFFFFFGenerates ${$s2*$377358s1/100} Insanity over the duration.|r", ua = "Їдка тіньова енергія випромінюється від цілі, завдаючи ${$394979s2*$s2} тіньової шкоди протягом $d усім ворогам у межах $394979a2 ярдів від цілі. Шкода зменшується після $394979s3 цілей.\n\n\n\n|cFFFFFFFFГенерує ${$s2*$377358s1/100} Божевілля протягом дії.|r" },
    { en = "$?a388114[Chaos][Fire]", ua = "$?a388114[хаосу][вогню]" },
    { en = "$?a388114[Chaos][Arcane]", ua = "$?a388114[хаосу][арканну]" },
    { en = "$?a388114[Chaos][Shadow]", ua = "$?a388114[хаосу][тіньову]" },
    { en = "$?a388114[Chaos][Nature]", ua = "$?a388114[хаосу][природну]" },
    { en = "Attune to Black magic, granting you and your $403208s2 nearest allies $s1% increased maximum health.", ua = "Налаштовує вас на чорну магію, підвищуючи максимальне здоров'я вам та вашим $403208s2 найближчим союзникам на $s1%." },
    { en = "Attune to Bronze magic, granting you and your $403208s2 nearest allies $s1% increased movement speed.", ua = "Налаштовує вас на бронзову магію, підвищуючи швидкість пересування вам та вашим $403208s2 найближчим союзникам на $s1%." },
    { en = "Burns the targets for an additional $o2 Radiant damage over $d, and slows them by $s1%.", ua = "Палить цілі, завдаючи додатково $o2 променистої шкоди протягом $d, та сповільнює їх на $s1%." },
    { en = "$?a424113[New Moon and Half Moon call down $s3 Minor $LMoon:Moons; and ][]Full Moon calls down $424058s1 Minor $LMoon:Moons; that $Ldeals:deal; $s1 Astral damage and generate ${$m2/10} Astral Power.", ua = "$?a424113[Молодик і Півмісяць закликають $s3 малих $LМісяць:Місяці; та ][]Повний Місяць закликає $424058s1 малих $LМісяць:Місяці;, що $Lзавдає:завдають; $s1 астральної шкоди та $Lгенерує:генерують; ${$m2/10} Астральної Сили." },
    { en = "Hammer down your enemy with the power of the Light, dealing $s1 Holy damage and $429826s1 Holy damage up to $s2 nearby enemies. \n\n\n\nAdditionally, calls down Empyrean Hammers from the sky to strike $427445s2 nearby enemies for $431398s1 Holy damage each.", ua = "Обрушує на ворога силу Світла, завдаючи $s1 святої шкоди йому та $429826s1 святої шкоди щонайбільше $s2 сусіднім ворогам. \n\n\n\nКрім того, прикликає з небес Емпірейські молоти, що вражають $427445s2 сусідніх ворогів, завдаючи кожному $431398s1 святої шкоди." },
    { en = "Cloaked in the ever-burning flames of the abyss, dealing $428455s1 Fire damage to enemies within $428455a1 yards every $t1 sec.", ua = "Огорнутий вічногорючим полум'ям безодні, завдаючи $428455s1 вогняної шкоди ворогам у межах $428455a1 ярдів кожні $t1 с." },
    { en = "While wielding a Holy Bulwark, gain an absorb shield for ${$s2/10}.1% of your max health and an additional ${$s4/10}.1% every $t2 sec. Lasts $d.", ua = "Поки ви володієте Священним Бастіоном, ви отримуєте поглинальний щит на ${$s2/10}.1% вашого максимального здоров'я та додатково ${$s4/10}.1% кожні $t2 с. Триває $d." },
    { en = "Hurl a bolt enveloped in the infernal flames of the abyss, dealing $s1 Fire damage to your enemy target and generating ${$s2/10} Soul Shards.", ua = "Метає заряд, огорнутий пекельним полум'ям безодні, завдаючи $s1 вогняної шкоди вашій ворожій цілі та генеруючи ${$s2/10} Уламків Душі." },
    { en = "Generates $457578s1 Soul Shard Fragment every $457578t1 sec and casts Chaos Bolt at $456975s1% effectiveness at its summoner's target. Lasts $d.", ua = "Генерує $457578s1 Фрагмент Уламка Душі кожні $457578t1 с і творить Заряд Хаосу з $456975s1% ефективністю по цілі того, хто його прикликав. Триває $d." },
    { en = "Call down a demon-infested meteor from the depths of the Twisting Nether, dealing $434636s1 Chaos damage on impact to all enemies within $434636a1 yds of the target$?s137046[ and summoning $433885s3 Diabolic Imp.\n\n\n\nDamage is further increased by your critical strike chance and is reduced beyond $s2 targets.][ and summoning $433885s2 Wild Imps.\n\n\n\nDamage is reduced beyond $s2 targets.]", ua = "Прикликає заражений демонами метеор із глибин Круговерті Порожнечі, завдаючи при ударі $434636s1 шкоди Хаосу всім ворогам у радіусі $434636a1 ярдів від цілі$?s137046[ та прикликаючи $433885s3 Диявольського біса.\n\n\n\nШкода додатково збільшується вашим шансом критичного удару і зменшується понад $s2 цілей.][ та прикликаючи $433885s2 Диких бісів.\n\n\n\nШкода зменшується понад $s2 цілей.]" },
    { en = "Blasts all enemies within $A1 yards for $s1 Stormstrike damage$?s199045[, roots them for $199042d,][] and reduces their movement speed by $435203s1% for $435203d. Deals reduced damage beyond $s5 targets.$?a137048|(a137050&a436707)[\n\n\n\n|cFFFFFFFFGenerates ${$s4/10} Rage.][]", ua = "Вражає всіх ворогів у радіусі $A1 ярдів, завдаючи $s1 шкоди ударом бурі$?s199045[, знерухомлює їх на $199042d][] та зменшує їхню швидкість пересування на $435203s1% протягом $435203d. Завдає зменшеної шкоди понад $s5 цілей.$?a137048|(a137050&a436707)[\n\n\n\n|cFFFFFFFFСтворює ${$s4/10} Люті.][]" },
    { en = "Finishing move that slashes through your target in a wide arc, dealing Physical damage per combo point to your target and consuming up to $?a102543[${$s2*(1+$102543s3/100)}][$s2] additional Energy to increase that damage by up to 100%. Hits all other enemies in front of you for reduced damage per combo point spent. \n\n\n\n1 point: ${$m1*1/5} damage, ${$m3*1/5} in an arc\n\n2 points: ${$m1*2/5} damage, ${$m3*2/5} in an arc\n\n3 points: ${$m1*3/5} damage, ${$m3*3/5} in an arc\n\n4 points: ${$m1*4/5} damage, ${$m3*4/5} in an arc\n\n5 points: ${$m1*5/5} damage, ${$m3*5/5} in an arc", ua = "Завершальний прийом, що розтинає вашу ціль широкою дугою, завдаючи фізичної шкоди за кожне комбо-очко вашій цілі й споживаючи до $?a102543[${$s2*(1+$102543s3/100)}][$s2] додаткової Енергії, щоб збільшити цю шкоду до 100%. Вражає всіх інших ворогів перед вами зі зменшеною шкодою за витрачене комбо-очко. \n\n\n\n1 очко: ${$m1*1/5} шкоди, ${$m3*1/5} дугою\n\n2 очки: ${$m1*2/5} шкоди, ${$m3*2/5} дугою\n\n3 очки: ${$m1*3/5} шкоди, ${$m3*3/5} дугою\n\n4 очки: ${$m1*4/5} шкоди, ${$m3*4/5} дугою\n\n5 очок: ${$m1*5/5} шкоди, ${$m3*5/5} дугою" },
    { en = "Slash through your target in a wide arc, dealing $s1 Physical damage to your target and $s2 to all other enemies in front of you.", ua = "Розсікаєте вашу ціль широкою дугою, завдаючи $s1 фізичної шкоди вашій цілі та $s2 усім іншим ворогам перед вами." },
    { en = "Throw a glaive enhanced with the essence of consumed souls at your target, dealing $s1 Physical damage and ricocheting to ${$x1-1} additional $Lenemy:enemies;.\n\n \n\nBegins a well-practiced pattern of glaivework, enhancing your next $?a212612[Chaos Strike]?s263642[Fracture][Shear] and $?a212612[Blade Dance][Soul Cleave].\n\n\n\nThe enhanced ability you cast first deals $442290s3% increased damage, and the second deals $442290s4% increased damage.$?a442497[\n\n\n\n|CFFffffffGenerates $s2 Fury.|R][]", ua = "Кидає в ціль глефу, посилену есенцією поглинутих душ, завдаючи $s1 фізичної шкоди та рикошетом уражаючи ${$x1-1} додаткових $Lворога:ворогів;.\n\n \n\nРозпочинає добре відпрацьований ланцюг ударів глефою, посилюючи ваше наступне $?a212612[Удар Хаосу]?s263642[Розлом][Розсічення] та $?a212612[Танець Клинків][Розколювання Душі].\n\n\n\nПосилене вміння, яке ви творите першим, завдає на $442290s3% більше шкоди, а друге — на $442290s4% більше шкоди.$?a442497[\n\n\n\n|CFFffffffГенерує $s2 Люті.|R][]" },
    { en = "Increases the time between an enemy's attacks by $s1% and the casting time of all spells by $s3% for $d.$?s103112[\n\n\n\n|CFFE55BB0Soulburn: Your Curse of Weakness will affect all enemies in a $104222A yard radius around your target.|R][]\n\n\n\n|cFF8282FFCurses: A warlock can only have one Curse active per target.|r", ua = "Збільшує час між атаками ворога на $s1% і час застосування всіх заклять на $s3% протягом $d.$?s103112[\n\n\n\n|CFFE55BB0Спалення душі: ваше Прокляття слабкості вражатиме всіх ворогів у радіусі $104222A ярдів навколо вашої цілі.|R][]\n\n\n\n|cFF8282FFПрокляття: чорнокнижник може мати лише одне активне Прокляття на ціль.|r" },
    { en = "Conjure raw Frost magic into a sharp projectile that deals $s1 Frost damage.", ua = "Створює з чистої магії холоду гострий снаряд, що завдає $s1 шкоди холодом." },
    { en = "Conjure raw Arcane magic into a sharp projectile that deals $s1 Arcane damage.", ua = "Створює з чистої арканної магії гострий снаряд, що завдає $s1 арканної шкоди." },
    { en = "Surrounds your target in a protective water bubble for $d.\n\n\n\nThe shield absorbs the next $?a443449[${$s1*(1+$443449s1/100)}][$s1] incoming damage, but the absorb amount decays fully over its duration.", ua = "Оточує вашу ціль захисною водяною бульбашкою на $d.\n\n\n\nЩит поглинає наступні $?a443449[${$s1*(1+$443449s1/100)}][$s1] вхідної шкоди, але обсяг поглинання поступово спадає до нуля за час дії." },
    { en = "Increases your spell damage by $?c1[${$s1}.1][${$s2}.1]%. Stacks up to $u times.", ua = "Підвищує шкоду ваших заклять на $?c1[${$s1}.1][${$s2}.1]%. Накопичується до $u разів." },
    { en = "Calls down a meteorite which lands at the target location after $177345d, dealing $449569s1 Fire damage to all enemies hit, reduced beyond 8 targets.", ua = "Закликає метеорит, що падає на цільове місце через $177345d, завдаючи $449569s1 вогняної шкоди всім ураженим ворогам; шкода зменшується після 8 цілей." },
    { en = "Sends a blast of cosmic void energy at the enemy, causing $s1 Shadow damage.$?c3[\n\n\n\n|cFFFFFFFFGenerates ${$c/100*-1} Insanity.|r][]", ua = "Шле у ворога спалах космічної енергії Порожнечі, завдаючи $s1 шкоди тінню.$?c3[\n\n\n\n|cFFFFFFFFПороджує ${$c/100*-1} Безумства.|r][]" },
    { en = "Sends a blast of cosmic void energy at the enemy, causing $s1 Shadow damage.$?c3[\n\n\n\n|cFFFFFFFFGenerates ${$s2/100} Insanity.|r][]", ua = "Шле у ворога спалах космічної енергії Порожнечі, завдаючи $s1 шкоди тінню.$?c3[\n\n\n\n|cFFFFFFFFПороджує ${$s2/100} Безумства.|r][]" },
    { en = "Arcane Barrage grants Clearcasting and generates $s1 Arcane Charges.\n\n\n\nEach cast of Arcane Barrage grants $s2 stacks of Arcane Salvo and casting Arcane Barrage does not consume Arcane Salvo.", ua = "Арканний Шквал надає Ясне Чаротворення та генерує $s1 Арканних Зарядів.\n\n\n\nКожне творіння Арканного Шквалу надає $s2 стаків Арканного Залпу, і творіння Арканного Шквалу не витрачає Арканний Залп." },
    { en = "Summon a Voidwraith that casts Void Flay from afar. Void Flay deals bonus damage to high health enemies, up to a maximum of $451435s2% if they are full health.$?s137033[\n\n\n\n|cFFFFFFFFGenerates ${$262485s1/100} Insanity each time the Voidwraith attacks.|r][\n\n\n\n|cFFFFFFFFGenerates ${$34433s4/10}.1% Mana each time the Voidwraith attacks.|r]", ua = "Прикликає Мару Порожнечі, що здалеку творить Батіг Порожнечі. Батіг Порожнечі завдає додаткової шкоди ворогам із високим здоров'ям, до $451435s2% максимум, якщо вони з повним здоров'ям.$?s137033[\n\n\n\n|cFFFFFFFFПороджує ${$262485s1/100} Безумства щоразу, коли Мара Порожнечі атакує.|r][\n\n\n\n|cFFFFFFFFПороджує ${$34433s4/10}.1% Мани щоразу, коли Мара Порожнечі атакує.|r]" },
    { en = "Instantly restores $s1% health$?s262031[, plus an additional ${$262080d/$262080t1*$262080s1}% over $262080d.][.]", ua = "Миттєво відновлює $s1% здоров'я$?s262031[ та додатково ${$262080d/$262080t1*$262080s1}% протягом $262080d.][.]" },
    { en = "Your next Lava Lash grants you Hot Hand for ${$s1/1000} sec.", ua = "Ваш наступний Лавовий Батіг надає вам Гарячу Руку на ${$s1/1000} с." },
    { en = "$?a137041[Your next Sundering deals $s1% increased damage and summons a Searing Totem.][Your next Chain Heal applies Earthliving at $s2% effectiveness to all targets hit.]", ua = "$?a137041[Ваше наступне Розколювання завдає на $s1% більше шкоди та прикликає Палючий Тотем.][Ваше наступне Ланцюгове Зцілення накладає Земне Життя з $s2% ефективністю на всі уражені цілі.]" },
    { en = "Your next Healing Wave also heals an ally inside of your Healing Rain at $s1% effectiveness.", ua = "Ваша наступна Зцілювальна Хвиля також зцілює союзника в зоні вашого Зцілювального Дощу з $s1% ефективністю." },
    { en = "$?a137041[Your next Lightning Bolt, Chain Lightning or Elemental Blast unleashes $s3 Surging Bolts at your Surging Totem.][The cast time of your next healing spell is reduced by $s1%.]", ua = "$?a137041[Ваш наступний Заряд Блискавки, Ланцюгова Блискавка чи Стихійний Вибух вивільняє $s3 Навальних Зарядів по вашому Навальному Тотему.][Час прочитання вашого наступного зцілювального закляття зменшується на $s1%.]" },
    { en = "Tooth and claw are drenched in malignant shadow magic, causing the Gloomhound's melee attacks to deal an additional $455491s1 Shadow damage.", ua = "Зуби та кігті просякнуті лиховісною тіньовою магією, через що атаки ближнього бою Похмурого Пса завдають додатково $455491s1 тіньової шкоди." },
    { en = "Imbue your shield with the element of Water for $457496d. Your healing done is increased by ${$457496s2}.1% and the duration of your Healing Stream Totem is increased by ${$457496s1/1000}.1 sec.", ua = "Просочує ваш щит стихією Води на $457496d. Ваше зцілення підвищується на ${$457496s2}.1%, а тривалість вашого Тотема Зцілювального Потоку збільшується на ${$457496s1/1000}.1 с." },
    { en = "Slashes through all enemies within $a1 yds in front of you, dealing $s1 Shadow damage and hastening all of your plagues on targets hit to deal damage $1241077s1% faster for $1241077d.", ua = "Розсікає всіх ворогів у межах $a1 м перед вами, завдаючи $s1 шкоди Тіні та пришвидшуючи всі ваші пошесті на уражених цілях, щоб вони завдавали шкоди на $1241077s1% швидше протягом $1241077d." },
    { en = "Your Spotting Eagle alerts you to oncoming danger, reducing all damage you take by $s1%", ua = "Ваш Пильний Орел попереджає вас про небезпеку, що насувається, зменшуючи всю шкоду, яку ви отримуєте, на $s1%" },
    { en = "|CFFffffffRequires $1225789u Soul Fragments|R\n\n\n\nYou ascend to a higher state of being, substantially empowering your abilities.\n\n\n\nWhile in Void Metamorphosis, your Consume and Reap are enhanced and your Fury will slowly drain. Additionally, Void Ray reduces your Fury drain, deals increased damage, and no longer consumes Fury.", ua = "|CFFffffffПотребує $1225789u фрагментів душі|R\n\n\n\nВи підноситеся до вищого стану буття, суттєво підсилюючи свої здібності.\n\n\n\nПід час Метаморфози Порожнечі ваші Поглинання та Жнива посилені, а ваша Лють поволі вичерпується. Крім того, Промінь Порожнечі зменшує вичерпання вашої Люті, завдає підвищеної шкоди й більше не споживає Люті." },
    { en = "Channel an immense amount of void energy into a single, cataclysmic blast, $?a1242486[critically striking for ${$1221162s1*2}][dealing $1221162s1] Cosmic damage to your target and $?a1242486[${2*($1221162s1*($s2/100))}][${$1221162s1*($s2/100)}] Cosmic damage to all nearby enemies. Damage reduced beyond $s1 targets.\n\n\n\nWhile casting Collapsing Star, your Fury drain is significantly reduced.$?a1240204[\n\n\n\n|CFFffffffGenerates $1240204s1 Soul $LFragment:Fragments;|R.][]", ua = "Спрямовує величезну кількість енергії Порожнечі в єдиний катаклізмічний вибух, $?a1242486[критично вражаючи на ${$1221162s1*2}][завдаючи $1221162s1] космічної шкоди вашій цілі та $?a1242486[${2*($1221162s1*($s2/100))}][${$1221162s1*($s2/100)}] космічної шкоди всім ворогам поблизу. Шкода зменшується понад $s1 цілей.\n\n\n\nПід час застосування Колапсу зорі витрата вашої Люті значно зменшена.$?a1240204[\n\n\n\n|CFFffffffСтворює $1240204s1 $LФрагмент:Фрагменти; душі|R.][]" },
    { en = "$?a427775[Chaos][Fire]", ua = "$?a427775[Хаосу][Вогню]" },
    { en = "Slam your Scythe to the ground, dealing $?a1217607[$1279200s1][$1225827s1] Cosmic damage to your primary target and $?a1217607[${$1279200s1*($s1/100)}][${$1225827s1*($s1/100)}] to all other enemies within a $s2 yd cone in front of you. Damage reduced beyond $1226033s1 targets.\n\n\n\nEradicate gathers up to $1227619s2 nearby souls.$?a1246558[\n\n\n\n|CFFffffffGenerates $1261679s1 Fury.|R][]", ua = "Б'є косою об землю, завдаючи $?a1217607[$1279200s1][$1225827s1] космічної шкоди вашій основній цілі та $?a1217607[${$1279200s1*($s1/100)}][${$1225827s1*($s1/100)}] усім іншим ворогам у конусі завдовжки $s2 ярдів перед вами. Шкода зменшена понад $1226033s1 цілей.\n\n\n\nВикорінення збирає до $1227619s2 душ поблизу.$?a1246558[\n\n\n\n|CFFffffffПороджує $1261679s1 Люті.|R][]" },
    { en = "Start a frozen onslaught that strikes twice, unleashing the chilling essence of winter, dealing $1228443s1 Frost damage to all enemies caught in its wake with each strike.\n\n\n\nEach enemy struck reduces the damage dealt to the next foe by $455993s4%, down to $455993s5%.", ua = "Здіймає крижану навалу, що б'є двічі, вивільняючи холодну сутність зими й завдаючи $1228443s1 шкоди морозом усім ворогам на її шляху з кожним ударом.\n\n\n\nКожен уражений ворог зменшує шкоду, завдану наступному супротивнику, на $455993s4%, аж до $455993s5%." },
    { en = "Violently slash your scythe around you, dealing $1239127s1 Cosmic damage to nearby enemies and generating $1239507s1 Fury. Shatters up to $s1 Soul $LFragment:Fragments; from nearby enemies. Damage reduced beyond $s2 targets.", ua = "Несамовито розтинаєте косою все навколо себе, завдаючи $1239127s1 космічної шкоди ворогам поблизу та породжуючи $1239507s1 Люті. Відколює до $s1 $LФрагмента:Фрагментів; душі від ворогів поблизу. Шкода зменшена понад $s2 цілей." },
    { en = "An unholy arrow that deals $s1 Shadow damage. When consuming Sudden Doom, your Death Coil commands your archer to fire an additional Blighted Arrow at $194916s1% effectiveness. Epidemic will instead cause Blighted Arrow to ricochet and hit up to $1239385s2 additional targets.", ua = "Нечестива стріла, що завдає $s1 тіньової шкоди. Коли витрачається Раптова Загибель, ваша Смертна Змійка наказує вашому лучнику випустити додаткову Згубну Стрілу з $194916s1% ефективністю. Епідемія натомість змусить Згубну Стрілу рикошетити й уразити до $1239385s2 додаткових цілей." },
    { en = "A malicious plague that deals $o Shadow damage over $d. Explodes for $1242564s1 Shadow damage to nearby enemies and infects one when the host dies. Can only be applied to $s5 $Lhost:hosts; at a time.", ua = "Лиховісна чума, що завдає $o тіньової шкоди протягом $d. Вибухає, завдаючи $1242564s1 тіньової шкоди ворогам поблизу, та заражає одного з них, коли носій гине. Може бути накладена одночасно лише на $s5 $Lносія:носіїв;." },
    { en = "Hurls a divine hammer that strikes an enemy for $<damage> $?s403664[Holystrike][Holy] damage.\n\n\n\n|cFFFFFFFFGenerates $s2 Holy Power.", ua = "Метає божественний молот, що вражає ворога на $<damage> шкоди $?s403664[Священним ударом][Світла].\n\n\n\n|cFFFFFFFFСтворює $s2 Священної сили." },
    { en = "Releases a volley of pure void energy, firing $s1 bolts at your target and $s3 $L:bolts;bolt at all enemies within 10 yards of your target for $1242189s1 Shadow damage.\n\n\n\n|cFFFFFFFFGenerates ${$m2/100} Insanity.|r", ua = "Вивільняє залп чистої енергії Порожнечі, випускаючи $s1 зарядів по вашій цілі та $s3 $L:зарядів;заряд по всіх ворогах у межах 10 ярдів від вашої цілі, завдаючи $1242189s1 тіньової шкоди.\n\n\n\n|cFFFFFFFFГенерує ${$m2/100} Божевілля.|r" },
    { en = "Unleash a vortex of necrotic energy and bone, dealing $1242172s1 Shadowstrike damage up to $1242158s2 foes and $1242178s1 Shadow damage to all pierced enemies.", ua = "Вивільняє вихор некротичної енергії та кісток, завдаючи $1242172s1 шкоди тіньовим ударом до $1242158s2 ворогам та $1242178s1 тіньової шкоди всім пронизаним ворогам." },
    { en = "Incarnation: Avatar of Ashamane's cooldown is reduced by ${-$s1/1000} sec.", ua = "Перезарядження Втілення: аватара Ашамейн зменшено на ${-$s1/1000} сек." },
    { en = "Casting Prayer of Mending heals your target for $s1.", ua = "Прочитання Молитви зцілення відновлює вашій цілі $s1 здоров'я." },
    { en = "You release a Jadefire Stomp, dealing $1248815s1 damage to $s2 enemies in front of you.", ua = "Ви вивільняєте Тупіт нефритового вогню, завдаючи $1248815s1 шкоди $s2 ворогам перед вами." },
    { en = "Sends a volley of malefic bolts at $x1 enemies within $s2 yds, inflicting $s1 Shadow damage to each target.", ua = "Випускає залп лиховісних зарядів по $x1 ворогах у межах $s2 ярдів, завдаючи $s1 тіньової шкоди кожній цілі." },
    { en = "Shields $s3 allies for $d, absorbing $s1 damage.", ua = "Захищає щитом $s3 союзників на $d, поглинаючи $s1 шкоди." },
    { en = "Spring a bloom of life from your target, healing them and up to ${$x2-1} other allies within $s3 yards for $s2. Blooms may heal your primary target multiple times if no nearby injured allies are present.", ua = "Викликає з вашої цілі цвіт життя, зцілюючи її та до ${$x2-1} інших союзників у межах $s3 ярдів на $s2. Цвіти можуть зцілити вашу головну ціль кілька разів, якщо поблизу немає поранених союзників." },
    { en = "Warp the flow of time, increasing your haste by $s1%.", ua = "Викривлює плин часу, підвищуючи ваш поспіх на $s1%." },
    { en = "Binds the target in twilight, dealing $o1 Shadow damage over $d.\n\n\n\nWhen Malefic Grasp deals damage, it causes all of your other periodic Affliction damage effects to instantly deal $s2% of their normal periodic damage.", ua = "Зв'язує ціль сутінками, завдаючи $o1 шкоди Тіні протягом $d.\n\n\n\nКоли Зловісна хватка завдає шкоди, усі ваші інші періодичні ефекти шкоди від Чорнокнижництва миттєво завдають $s2% від своєї звичайної періодичної шкоди." },
    { en = "Calls down a meteor formed from the ruins of Nathreza that explodes upon impact, dealing $1278047s1 Shadow damage to all enemies within $1278047a1 yds.\n\n\n\nDamage reduced beyond $s2 targets.", ua = "Закликає метеор, утворений з руїн Натрези, що вибухає при ударі, завдаючи $1278047s1 тіньової шкоди всім ворогам у межах $1278047a1 ярдів.\n\n\n\nШкода зменшується після $s2 цілей." },
    { en = "Slash the target, dealing $1263890s1 Physical damage and an additional ${$1271863s2*$1271863d/$1271863t2} Bleed damage over $1271863d. If this effect is reapplied, any remaining damage is added to the new Bleed.", ua = "Розсікає ціль, завдаючи $1263890s1 фізичної шкоди та додатково ${$1271863s2*$1271863d/$1271863t2} шкоди від кровотечі протягом $1271863d. Якщо цей ефект накладається повторно, будь-яка залишкова шкода додається до нової кровотечі." },
    { en = "Swipe nearby targets, dealing $1263908s1 Physical damage. Damage reduced beyond 5 targets.", ua = "Б'є розмашистим ударом цілі поблизу, завдаючи $1263908s1 фізичної шкоди. Шкода зменшується після 5 цілей." },
    { en = "Cleaves all enemies in a cone in front of the caster, inflicting $s1 Shadowflame damage. Damage reduced beyond $s2 targets.", ua = "Розсікає всіх ворогів у конусі перед заклинателем, завдаючи $s1 шкоди тіньовим полум'ям. Шкода зменшується після $s2 цілей." },
    { en = "Sends a bolt of pure void energy at your target, dealing $s1 Shadow damage.", ua = "Посилає стрілу чистої енергії Порожнечі у вашу ціль, завдаючи $s1 шкоди Тіні." },
    { en = "Throw a chakram blessed with moonlight at your current target that will rapidly deal $1266081s1 Physical damage $x times, bouncing to other targets if they are nearby.", ua = "Метає чакрам, благословенний місячним сяйвом, у вашу поточну ціль, швидко завдаючи $1266081s1 фізичної шкоди $x разів і відскакуючи до інших цілей, якщо вони поруч." },
    { en = "Upon taking damage, automatically consume a refreshing drink to heal for $o1 over $d.", ua = "При отриманні шкоди автоматично спожийте освіжний напій, щоб зцілити $o1 протягом $d." },
    { en = "Exhale a bolt of concentrated power from your mouth at the target for $s2 Spellfrost damage.", ua = "Видихає на ціль заряд зосередженої сили, завдаючи $s2 шкоди магічним холодом." },
    { en = "Concentrate azure energy into your tail and sweep to release pure magic upon an enemy and nearby targets for $s2 Spellfrost damage. Damage reduced beyond $s1 targets.", ua = "Зосереджуєте лазурову енергію у хвості та робите помах, вивільняючи чисту магію на ворога й цілі поблизу, завдаючи $s2 шкоди Закляттєвого холоду. Шкода зменшується після $s1 цілей." },
    { en = "Hurl an ember torn from Nihilam at the target, dealing $s1 Shadowflame damage and an additional $s2 Shadowflame damage to all enemies within $a2 yds.\n\n\n\nDamage reduced beyond $s3 targets.", ua = "Метає в ціль вуглину, вирвану з Нігілама, завдаючи $s1 шкоди тіньовим полум'ям та додатково $s2 шкоди тіньовим полум'ям усім ворогам у межах $a2 ярдів.\n\n\n\nШкода зменшується після $s3 цілей." },
    { en = "Strikes nearby enemies with a malevolent claw, dealing $s1 Shadow damage to its target and $s2 Shadow damage to other enemies in $a2 yds.", ua = "Б'є ворогів поблизу лиховісним кігтем, завдаючи $s1 тіньової шкоди своїй цілі та $s2 тіньової шкоди іншим ворогам у межах $a2 ярдів." },
    { en = "Powerfully strike an opponent, causing $s1 Physical damage and gaining a stack of Master of Warfare, allowing your attacks to penetrate $1269394s1% armor for $1269394d. Multiple applications of this effect may overlap.", ua = "Завдає супротивнику потужного удару, завдаючи $s1 фізичної шкоди та надаючи стак Майстра Воєнного Мистецтва, що дозволяє вашим атакам пробивати $1269394s1% броні протягом $1269394d. Кілька застосувань цього ефекту можуть накладатися." },
    { en = "Fire a beam of destructive chaos magic at the target, dealing $s1 Chaos damage.\n\n\n\nDamage is increased by $s2% per Demonic Oculus active.", ua = "Випускає по цілі промінь руйнівної магії хаосу, завдаючи $s1 шкоди хаосу.\n\n\n\nШкода підвищується на $s2% за кожен активний Демонічний Окулус." },
    { en = "For each charge of Potential Energy, deal $?c1[${$1271011s1*$1270958s1/100}][${$1271011s1*$1270958s2/100}] Nature damage to your target and $?c1[${$1271011s2*$1270958s1/100}][${$1271011s2*$1270958s2/100}] Nature damage to other nearby enemies, and heal up to $1271045s2 allies for $?c1[${$1271045s1*$1270958s3/100}][${$1271045s1*$1270958s4/100}]. Damage reduced above $1270958s7 targets.", ua = "За кожен заряд Потенційної енергії завдає $?c1[${$1271011s1*$1270958s1/100}][${$1271011s1*$1270958s2/100}] шкоди Природи вашій цілі та $?c1[${$1271011s2*$1270958s1/100}][${$1271011s2*$1270958s2/100}] шкоди Природи іншим ворогам поблизу, а також зцілює до $1271045s2 союзників на $?c1[${$1271045s1*$1270958s3/100}][${$1271045s1*$1270958s4/100}]. Шкода зменшується понад $1270958s7 цілей." },
    { en = "Consume $1271974s1% of your plagues around you and deal $1271974s2% of their remaining damage instantly.\n\n\n\n|cFFFFFFFFGrants $1271974s3 $lcharge:charges; of Putrefy.|r", ua = "Поглинає $1271974s1% ваших пошестей навколо вас і миттєво завдає $1271974s2% їхньої залишкової шкоди.\n\n\n\n|cFFFFFFFFНадає $1271974s3 $lзаряд:заряди; Гниття.|r" },
    { en = "Release a powerful stomp, dealing $1272696s1 Nature damage to nearby enemies, reduced beyond $1272694s1 targets.\n\n\n\n|cFFFFFFFFGenerates $s2 Chi.", ua = "Вивільняєте потужний тупіт, завдаючи $1272696s1 шкоди Природи ворогам поблизу, зменшується після $1272694s1 цілей.\n\n\n\n|cFFFFFFFFГенерує $s2 ці." },
    { en = "Increases damage done by $s1% and Fel Firebolt now jumps to $s2 additional targets.", ua = "Підвищує завдану шкоду на $s1%, і Заряд Вогню Скверни тепер перестрибує на $s2 додаткових цілей." },
    { en = "Move your active Deathstalker's Mark to your target.", ua = "Переміщує ваше активне Тавро Смертопивача на вашу ціль." },
    { en = "Increases speed while mounted by $s1%. Not active in Battlegrounds or Arenas.", ua = "Збільшує швидкість верхи на $s1%. Не діє на полях бою та аренах." },
    { en = "Reduces the cooldown on your Hearthstone by ${$m1/-60000} minutes.", ua = "Зменшує час відновлення вашого Каменя дому на ${$m1/-60000} хв." },
    { en = "Click this button while facing a body of water, then click on the bobber when it splashes. You can drag this button to your action bar.", ua = "Натисніть цю кнопку, стоячи обличчям до водойми, а потім клацніть по поплавку, коли він смикнеться. Цю кнопку можна перетягнути на панель дій." },
    { en = "Instantly removes all stun, silence, fear and horror effects from the friendly target and reduces the duration of future such effects by $m2% for $d.", ua = "Миттєво знімає з дружньої цілі всі ефекти оглушення, німоти, страху та жаху і на $d зменшує тривалість таких майбутніх ефектів на $m2%." },
    { en = "Call down a strike of Holy energy, dealing $<damage> Holy damage to enemies within $A1 yards after $s1 sec. Damage reduced beyond $s2 targets.", ua = "Прикликає удар святої енергії, завдаючи через $s1 с $<damage> святої шкоди ворогам у межах $A1 м. Шкода зменшується за межами $s2 цілей." },
    { en = "Increases Holy damage done by ${$s1}.1%.\n\n\n\nJudgment has a ${($s1/2)*(1+($405278s2/100))*(1+($404512s4/100))}.1% chance to blast the target with the Light, dealing $383921s1 Holy damage.", ua = "Збільшує завдану святу шкоду на ${$s1}.1%.\n\n\n\nСуд має ${($s1/2)*(1+($405278s2/100))*(1+($404512s4/100))}.1% шанс уразити ціль Світлом, завдаючи $383921s1 святої шкоди." },
    { en = "Spiral forward a great distance, increasing speed.\n\n\n\nWhirling Surge dismounts airborne enemy players.", ua = "Спіраллю кидає вас далеко вперед, збільшуючи швидкість.\n\n\n\nВихровий ривок скидає з польоту ворожих гравців у повітрі." },
    { en = "Flap forward.\n\n\n\nSurge Forward evades obstacles encountered in time trials and races.", ua = "Кидок крилами вперед.\n\n\n\nРивок уперед допомагає уникати перешкод під час випробувань на час і перегонів." },
    { en = "Flap upward.", ua = "Змах крилами вгору." },
    { en = "Flap back, reducing forward movement.\n\n\n\nAfter activating Aerial Halt, experience a brief moment of weightlessness as the effects of gravity are reduced for $s2 sec.\n\n\n\n$?s425782[][|cnRED_FONT_COLOR:Unlocked at level 30.|r]", ua = "Змахує крилами назад, сповільнюючи рух уперед.\n\n\n\nПісля активації Повітряної зупинки ви відчуваєте коротку мить невагомості, бо ефекти гравітації зменшені на $s2 сек.\n\n\n\n$?s425782[][|cnRED_FONT_COLOR:Відкривається на 30-му рівні.|r]" },
    { en = "Reduces all damage you take by $s1% for $d$?s1261562[ and casts Shield of Vengeance][]. Usable while stunned.", ua = "Зменшує всю зазнану вами шкоду на $s1% протягом $d$?s1261562[ та творить Щит помсти][]. Можна використовувати під час оглушення." },
    { en = "Blade of Justice casts Consecration at the target's location.\n\n\n\nThis effect can only occur every 10 sec.", ua = "Клинок правосуддя застосовує Освячення на місці цілі.\n\n\n\nЦей ефект може спрацьовувати лише раз на 10 с." },
    { en = "Stunned.", ua = "Оглушено." },
    { en = "Overload a nearby elemental ore deposit.\n\n\n\n$?pc106420[The cooldown of this ability is reduced whenever you mine ore native to Khaz Algar.][Specialize into Master of the Elements to gain significant cooldown reduction on this ability whenever you mine ore native to Khaz Algar.]", ua = "Перевантажує елементальне рудне родовище поблизу.\n\n\n\n$?pc106420[Перезарядження цієї здібності зменшується щоразу, коли ви видобуваєте руду, питому для Каз Алґара.][Спеціалізуйтеся в Майстрі елементів, щоб значно зменшити перезарядження цієї здібності щоразу, коли ви видобуваєте руду, питому для Каз Алґара.]" },
    { en = "Overload a nearby elemental herb.\n\n\n\n$?pc120578[The cooldown of this ability is reduced whenever you gather herbs native to Khaz Algar.][Specialize into Overloading the Underground to gain significant cooldown reduction on this ability whenever you gather herbs native to Khaz Algar.]", ua = "Перевантажує елементальну траву поблизу.\n\n\n\n$?pc120578[Перезарядження цієї здібності зменшується щоразу, коли ви збираєте трави, питомі для Каз Алґара.][Спеціалізуйтеся в Перевантаженні підземелля, щоб значно зменшити перезарядження цієї здібності щоразу, коли ви збираєте трави, питомі для Каз Алґара.]" },
    { en = "Reach within for untapped reserves and instantly regenerates a charge for your skyriding abilities.\n\n\n\n$?s425782[][|cnRED_FONT_COLOR:Unlocked at level 20.|r]", ua = "Сягаєте в себе по незужиті резерви й миттєво відновлюєте заряд для ваших здібностей небесної їзди.\n\n\n\n$?s425782[][|cnRED_FONT_COLOR:Відкривається на 20-му рівні.|r]" },
    { en = "|CFF88AAFF$?A404468[Steady Flight][Skyriding]|R\n\nSwitch between Skyriding and steady flight styles for flying mounts. Mounts that don't support Skyriding will be grounded if Skyriding is active.", ua = "|CFF88AAFF$?A404468[Рівний політ][Небесна їзда]|R\n\nПеремикайтеся між небесною їздою та рівним стилем польоту для летючих їздових тварин. Їздові тварини, що не підтримують небесну їзду, будуть приземлені, якщо небесна їзда активна." },
    { en = "This delve has an abundance of treasures and will remain bountiful while inside.\n\n\n\nUse a Restored Coffer Key to open a Bountiful Coffer at the end of this delve to receive powerful equipment and greater rewards.", ua = "У цьому проваллі вдосталь скарбів, і воно лишатиметься щедрим, доки ви всередині.\n\n\n\nВикористайте відновлений ключ від скрині наприкінці цього провалля, щоб відкрити щедру скриню й отримати потужне спорядження та більші винагороди." },
    { en = "Allows a cook to make food and drink from Midnight zones.", ua = "Дозволяє кухарю готувати їжу та напої із зон Опівночі." },
    { en = "Allows an herbalist to master gathering herbs from around the Midnight regions. Herbs are used in Alchemy and Inscription.", ua = "Дозволяє травнику опанувати збирання трав у регіонах Опівночі. Трави використовуються в алхімії та накресленні." },
    { en = "Overload a nearby infused herb.\n\n\n\n$?pc120578[The cooldown of this ability is reduced whenever you gather herbs native to Midnight.][Specialize into Overloading Midnight to gain significant cooldown reduction on this ability whenever you gather herbs native to Midnight.]", ua = "Перевантажує наповнену траву поблизу.\n\n\n\n$?pc120578[Перезарядження цієї здібності зменшується щоразу, коли ви збираєте трави, питомі для Опівночі.][Спеціалізуйтеся в Перевантаженні Опівночі, щоб значно зменшити перезарядження цієї здібності щоразу, коли ви збираєте трави, питомі для Опівночі.]" },
    { en = "Overload a nearby infused deposit.\n\n\n\n$?pc136421[The cooldown of this ability is reduced whenever you mine deposits native to Midnight.][Specialize into Over-LODED to gain significant cooldown reduction on this ability whenever you mine deposits native to Midnight.]", ua = "Перевантажує наповнене родовище поблизу.\n\n\n\n$?pc136421[Перезарядження цієї здібності зменшується щоразу, коли ви видобуваєте родовища, питомі для Опівночі.][Спеціалізуйтеся в Над-РУДІННІ, щоб значно зменшити перезарядження цієї здібності щоразу, коли ви видобуваєте родовища, питомі для Опівночі.]" },
    { en = "Recipe for $M1 servings. Actual number of servings will vary based on cooking skill.", ua = "Рецепт на $M1 порцій. Фактична кількість порцій залежить від навички кулінарії." },
    { en = "Selfies are much more dangerous within the Slayer's Rise.", ua = "На Височині Вбивць селфі значно небезпечніші." },
    { en = "Reduces damage taken by $s1% for $d.", ua = "Зменшує отриману шкоду на $s1% протягом $d." },
    { en = "Overcharge the Wardbreaker, destroying the fel barrier protecting Aradis's private study.", ua = "Перевантажує руйнівник оберегів, знищуючи скверний бар'єр, що захищає особистий кабінет Арадіса." },
    { en = "Pretend to sip from a glass while eavesdropping on a nearby conversation.", ua = "Удавано сьорбаєте з келиха, підслуховуючи розмову неподалік." },
    { en = "Destroys mana containers and inflicts minor Arcane damage to enemies in a cone in front of you.", ua = "Руйнує вмістища мани та завдає незначної таємничої шкоди ворогам у конусі перед вами." },
    { en = "When any party member's health falls below $s1% during combat, the mantle grants them an absorb shield equal to $s2% of their maximum health.\n\n\n\nEnemies near the shielded ally and active companion are knocked up and take $s3% more damage for $s4 sec.\n\n\n\nCan only occur every $1255774d.", ua = "Коли здоров'я будь-якого учасника групи падає нижче $s1% під час бою, мантія дає йому поглинальний щит, рівний $s2% його максимального здоров'я.\n\n\n\nВорогів поблизу захищеного союзника й активного супутника підкидає вгору, і вони отримують на $s3% більше шкоди протягом $s4 сек.\n\n\n\nМоже статися лише кожні $1255774d." },
    { en = "Your companion has a chance during combat to afflict an enemy with Nether Entropy, causing them to take moderate Void damage over $s3 sec.\n\n\n\nEach time Nether Entropy deals damage it has a $s5% chance to propagate to $s1 nearby enemies, stacking up to $s2 times.", ua = "Ваш супутник має шанс під час бою вразити ворога Нетер-ентропією, через що той протягом $s3 сек отримує помірну шкоду Порожнечею.\n\n\n\nЩоразу, коли Нетер-ентропія завдає шкоди, вона має $s5% шанс поширитися на $s1 ворогів поблизу, накопичуючись до $s2 разів." },
    { en = "Deliver supplies!", ua = "Доставте припаси!" },
    { en = "Your companion's spells and abilities have a chance to weaken enemies, increasing the chance to critically strike affected targets by $s1% for $1261796d.", ua = "Закляття та здібності вашого супутника мають шанс послабити ворогів, збільшуючи шанс критичного удару по уражених цілях на $s1% протягом $1261796d." },
    { en = "Magical constructs that Antenorian uses to keep watch over and punish intruders and underlings alike with explosive bursts of Void.", ua = "Магічні конструкти, якими Антеноріан стежить за порушниками й підлеглими та карає їх вибуховими спалахами Порожнечі." },
    { en = "The remnants of the Shadowguard serve under the cruel auspices of the Devouring Host.", ua = "Рештки Тіньової варти служать під жорстокою рукою Ненажерливого воїнства." },
    { en = "Gain access to the Singularity Renown.", ua = "Надає доступ до Слави Сингулярності." },
    { en = "Reduces mana cost of all spells by $s1 for $d.", ua = "Зменшує вартість мани всіх заклять на $s1 на $d." },
    { en = "Increases spell power by up to $s1 for $d.", ua = "Підвищує силу заклять до $s1 на $d." },
    { en = "Your attacks have a chance to grant Feathers of Fury, granting $138759s1 Strength every $138759t1 sec for $138759d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати Пера Люті, даруючи $138759s1 сили кожні $138759t1 сек. протягом $138759d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Summon a flaming keg of Alerage's Reserve at the target location, dealing $s2 damage to nearby enemies every $t2 sec for $d.", ua = "Прикликає палаюче барило Запасу Алереджа у вказане місце, завдаючи $s2 шкоди довколишнім ворогам кожні $t2 сек. протягом $d." },
    { en = "Heal self for $s1 damage.", ua = "Зцілює вас на $s1." },
    { en = "Your attacks have a chance to increase your Mastery by $202899s1 and heal you for $202899o2 over $202899d.", ua = "Ваші атаки мають шанс підвищити вашу майстерність на $202899s1 та зцілити вас на $202899o2 протягом $202899d." },
    { en = "Your attacks have a chance to increase your Haste by $202866s1 for $202866d.", ua = "Ваші атаки мають шанс підвищити вашу швидкість на $202866s1 протягом $202866d." },
    { en = "Unleash an Ice Bomb at your location, damaging enemies within $A1 yards for $s1 Frost damage and reducing their movement speed by $s2% for $d.\n\n\n\nYou gain $214589s1 Versatility for each target hit up to $214589u, for $214589d.", ua = "Вивільняє Крижану Бомбу у вашому місці, завдаючи ворогам у радіусі $A1 ярдів $s1 шкоди від холоду та знижуючи їхню швидкість пересування на $s2% протягом $d.\n\n\n\nВи отримуєте $214589s1 універсальності за кожну вражену ціль, до $214589u, протягом $214589d." },
    { en = "Your healing spells grant $109813s1 Versatility for the next $109813d, stacking up to $109813u times.", ua = "Ваші зцілювальні закляття дарують $109813s1 універсальності протягом наступних $109813d, накопичуючись до $109813u разів." },
    { en = "The Plume's radiance grants you $1260592s1 Mastery, waning over ${$1260615t2*$1260615u} sec before reigniting to full incandescence. The Plume's power also regenerates while out of combat.", ua = "Сяйво Пера дарує вам $1260592s1 майстерності, що згасає протягом ${$1260615t2*$1260615u} сек., перш ніж знову розгорітися на повну. Сила Пера також відновлюється поза боєм." },
    { en = "When you deal damage you have a chance to gain $102747s1 Agility for $102747d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $102747s1 спритності протягом $102747d." },
    { en = "Send the spores to your target, applying a shield that will absorb up to $s1 damage for $d. If the shield breaks before expiring, a cute mushroom will grow at the target's feet.", ua = "Надсилає спори на вашу ціль, накладаючи щит, що поглине до $s1 шкоди протягом $d. Якщо щит розіб'ється до закінчення дії, біля ніг цілі виросте милий гриб." },
    { en = "Charge the crystal to summon a rift that draws power from nearby enemies, inflicting ${$<rolemult>*$s2*$450922d} Shadow damage over $450922d.\n\n\n\nWhen the rift collapses, its drawn energy returns to you to increase your Intellect by $s3 for $451248d, further increased for each enemy struck.", ua = "Заряджає кристал, аби прикликати розлам, що витягує силу з довколишніх ворогів, завдаючи ${$<rolemult>*$s2*$450922d} шкоди від тіні протягом $450922d.\n\n\n\nКоли розлам згортається, витягнута енергія повертається до вас, підвищуючи ваш інтелект на $s3 протягом $451248d, що додатково зростає за кожного враженого ворога." },
    { en = "May cause extra gold to drop whenever you kill a target that yields experience or honor.", ua = "Може спричинити випадіння додаткового золота щоразу, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Drink from the vial and ascend over 1.5 sec before taking on a new more powerful form, increasing your $pri by $s2 and all other stats by $s1, but only for $d.", ua = "Випийте з флакона й піднесіться протягом 1,5 сек, перш ніж прибрати нову, могутнішу подобу, що підвищує вашу $pri на $s2 і всі інші характеристики на $s1, але лише на $d." },
    { en = "Your harmful spells and abilities have a chance to grant you a Void Fragment. Slaying an enemy guarantees a Void Fragment. Upon collecting $s4 Fragments, you absorb their void energy, increasing your Mastery by $s1 for $1224918d.", ua = "Ваші шкідливі закляття та здібності мають шанс надати вам Уламок Порожнечі. Убивство ворога гарантує Уламок Порожнечі. Зібравши $s4 уламків, ви поглинаєте їхню енергію порожнечі, підвищуючи вашу майстерність на $s1 протягом $1224918d." },
    { en = "Your healing spells and abilities have a chance to release a spirit of the Duskwraith, leaping to your target and healing them for $s1.\n\n\n\nIf the target's health is below $s3%, the spirit empowers them further, granting $s2 Versatility for $1263447d.", ua = "Ваші зцілювальні закляття та здібності мають шанс вивільнити дух Сутінкового Привида, що стрибає до вашої цілі та зцілює її на $s1.\n\n\n\nЯкщо здоров'я цілі нижче $s3%, дух підсилює її ще більше, даруючи $s2 універсальності протягом $1263447d." },
    { en = "Your attacks have a chance to grant you $235006s1 armor for $235006d.", ua = "Ваші атаки мають шанс надати вам $235006s1 броні протягом $235006d." },
    { en = "Your healing and damaging spells have a chance to grant $122896s1 mastery for $122896d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $122896s1 майстерності протягом $122896d." },
    { en = "Increases your Haste by $s1 and your Speed by $s2 for $d.", ua = "Підвищує вашу швидкість на $s1 та вашу прудкість на $s2 протягом $d." },
    { en = "Nearby player and enemy deaths grant you a Lost Soul, up to 10. Consuming Lost Souls $?a137047|a137034|a212611|a137005|a137041|a137027|a137025|a137011|a137017|a137028|a137023|a137010[shields you for $s3 per Lost Soul consumed.][]$?a137039|a137031|a137032|a137029|a137024|a356810|a137012[regenerates $s6 mana per Lost Soul consumed.][]$?a137042|a137018|a137040|a137033|a137016|a137015|a356809|a137013[empowers you, gaining $s5 Mastery per Lost Soul consumed for $415133d.][]", ua = "Смерть ближніх гравців і ворогів надає вам Загублену Душу, до 10. Поглинання Загублених Душ $?a137047|a137034|a212611|a137005|a137041|a137027|a137025|a137011|a137017|a137028|a137023|a137010[захищає вас на $s3 за кожну поглинуту Загублену Душу.][]$?a137039|a137031|a137032|a137029|a137024|a356810|a137012[відновлює $s6 мани за кожну поглинуту Загублену Душу.][]$?a137042|a137018|a137040|a137033|a137016|a137015|a356809|a137013[підсилює вас, надаючи $s5 майстерності за кожну поглинуту Загублену Душу протягом $415133d.][]" },
    { en = "Instantly heal a friendly target for $s1.", ua = "Миттєво зцілює дружню ціль на $s1." },
    { en = "Let the power of the Scourge course through and corrupt you, consuming all Lost Souls $?a137047|a137034|a212611|a137005|a137041|a137027|a137025|a137011|a137017|a137028|a137023|a137010[and transforming into a lich for $415033d. During this time you periodically deal $415006s2 Frost damage split between nearby enemies. After $415006s10 sec, unleash a wave of shadows causing nearby enemies to flee for $415038d. The duration of the fear is reduced for each nearby enemy (min 0.5 sec). (2 min 30 sec cooldown)][]$@spelldesc415245\n\n\n\nThis effect can differ based on your Specialization.", ua = "Дозволяє силі Погибелі пройти крізь вас і спотворити вас, поглинаючи всі Загублені Душі $?a137047|a137034|a212611|a137005|a137041|a137027|a137025|a137011|a137017|a137028|a137023|a137010[і перетворюючи вас на ліча на $415033d. Протягом цього часу ви періодично завдаєте $415006s2 шкоди від холоду, розподіленої між ближніми ворогами. Через $415006s10 сек ви вивільняєте хвилю тіней, що змушує ближніх ворогів тікати у страху протягом $415038d. Тривалість страху зменшується за кожного ближнього ворога (мін. 0.5 сек). (Час відновлення 2 хв 30 сек)][]$@spelldesc415245\n\n\n\nЦей ефект може відрізнятися залежно від вашої спеціалізації." },
    { en = "Your healing and damaging spells have a chance to grant $102662s1 mastery for $102662d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $102662s1 майстерності протягом $102662d." },
    { en = "Your melee attacks have a chance to shed a limb, granting $92174s1 Mastery and $92174s2 Avoidance for $92174d.", ua = "Ваші атаки ближнього бою мають шанс відірвати кінцівку, даруючи $92174s1 майстерності та $92174s2 ухилення протягом $92174d." },
    { en = "Your melee attacks have a chance to grant you a Mote of Anger.  When you reach $71432u Motes of Anger, they will release, causing you to instantly attack for $71433s2% weapon damage with one of your melee weapons.", ua = "Ваші атаки ближнього бою мають шанс надати вам Частку Гніву. Коли ви досягнете $71432u Часток Гніву, вони вивільняться, змусивши вас миттєво атакувати з $71433s2% шкоди зброї однією з ваших зброй ближнього бою." },
    { en = "$h% chance to increase your spell power by $41263s1 for $41263d when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "$h% шанс підвищити силу ваших заклять на $41263s1 протягом $41263d, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше ніж раз на 10 секунд." },
    { en = "Call upon an echo of Neltharion's power to crash to the ground below you, dealing $401468s3 Shadowflame damage to nearby enemies if you have traveled at least $m3 yards.", ua = "Прикликає відлуння сили Нелтаріона, що падає на землю під вами, завдаючи $401468s3 шкоди тіньовим полум'ям довколишнім ворогам, якщо ви подолали щонайменше $m3 ярдів." },
    { en = "Summons the Truesilver Boar to fight for you for 30 seconds.", ua = "Прикликає Срібнолитого Вепра, що б'ється за вас протягом 30 секунд." },
    { en = "Grants $s1 Critical Strike for $d.", ua = "Дарує $s1 критичного удару протягом $d." },
    { en = "Increases your haste by $s1 for $d1.", ua = "Підвищує вашу швидкість на $s1 протягом $d1." },
    { en = "Increases your Strength by $s1 for $d.", ua = "Підвищує вашу силу на $s1 протягом $d." },
    { en = "Drain $311483s1-$311490s1 Haste from the target and empowering yourself for the same. The amount drained depends on the topmost card in the deck. Lasts $311491d.", ua = "Висмоктує $311483s1-$311490s1 швидкості з цілі та підсилює вас на ту саму величину. Висмоктана кількість залежить від верхньої карти в колоді. Триває $311491d." },
    { en = "Increases your spell power by $s1 for $d.", ua = "Підвищує силу ваших заклять на $s1 протягом $d." },
    { en = "Stomp the ground, commanding flames to radiate outward from your position, dealing $394393s1 Fire damage split between all enemies struck and granting you a $394393s2 shield for $382058d. After a delay, the flames return, dealing the same damage and refreshing the shield.\n\n\n\nDamage and absorption are increased for each enemy struck, up to $s3 enemies.", ua = "Тупаєте об землю, наказуючи полум'ю розходитися від вашої позиції, завдаючи $394393s1 шкоди вогнем, розподіленої між усіма враженими ворогами, та даруючи вам щит на $394393s2 протягом $382058d. Після затримки полум'я повертається, завдаючи ту саму шкоду та оновлюючи щит.\n\n\n\nШкода й поглинання зростають за кожного враженого ворога, до $s3 ворогів." },
    { en = "When you cast healing spells, you have a chance to gain Blessing of the Celestials, increasing your Versatility by $128987s1 for $128987d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ви накладаєте зцілювальні закляття, ви маєте шанс отримати Благословення Небожителів, підвищуючи вашу універсальність на $128987s1 протягом $128987d. ($h% шанс, ${$proccooldown} сек. перезарядки)" },
    { en = "Increases maximum health by $s1 for $d. Shares cooldown with other Battlemaster's trinkets.", ua = "Підвищує максимальне здоров'я на $s1 протягом $d. Спільна перезарядка з іншими брязкальцями Бойового Майстра." },
    { en = "Your melee attacks have a chance to putt a bomb toward your enemy, dealing ${$<rolemult>*$1215321s1} Fire damage on impact.\n\n\n\nWhen you exit combat, gain a burst of speed for $1215336d if your score is a Hole-in-One, Birdie, or Par.", ua = "Ваші атаки ближнього бою мають шанс запатати бомбу в напрямку вашого ворога, завдаючи ${$<rolemult>*$1215321s1} шкоди вогнем при влучанні.\n\n\n\nКоли ви виходите з бою, отримуєте сплеск прудкості протягом $1215336d, якщо ваш рахунок — Лунка з Одного Удару, Берді або Пар." },
    { en = "Grants $s1 Mastery for $d.", ua = "Надає $s1 майстерності на $d." },
    { en = "Your attacks have a chance to grant you $146308s1 Agility for $146308d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $146308s1 спритності на $146308d.  ($h% шанс, ${$proccooldown} сек перезарядка)" },
    { en = "Your attacks have a chance to grant you $126236s1 armor for $126236d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $126236s1 броні на $126236d.  ($h% шанс, ${$proccooldown} сек перезарядка)" },
    { en = "Drop a Shadowgrasp Totem at your feet for $d that harvests your target, inflicting $329878s1 Shadow damage every $331532t1 sec. Each time a target dies while affected by Shadowgrasp Totem, you are healed for $329878s2 and this cooldown is reduced by $329878s3 sec.", ua = "Встановлює біля ваших ніг Тотем Тіньохвату на $d, який жне вашу ціль, завдаючи $329878s1 шкоди Тінню кожні $331532t1 сек. Щоразу, коли ціль гине під дією Тотема Тіньохвату, ви зцілюєтеся на $329878s2, а ця перезарядка скорочується на $329878s3 сек." },
    { en = "Gaze into the mirror's depths, inviting a version of your future self to fight alongside you for $d, casting spells based on your role. In addition, you grant yourself $s2 of your highest secondary stat.", ua = "Зазирніть у глибини дзеркала, запросивши версію свого майбутнього «я» битися пліч-о-пліч із вами на $d, читаючи закляття відповідно до вашої ролі. Крім того, ви надаєте собі $s2 від своєї найвищої вторинної характеристики." },
    { en = "Fire a web at the target, rooting them for $d.  Has no effect on players.  Only useable in Valley of the Four Winds and Krasarang Wilds.", ua = "Вистрілює павутиною в ціль, знерухомлюючи її на $d.  Не діє на гравців.  Можна застосовувати лише в Долині Чотирьох Вітрів та Нетрях Красаранга." },
    { en = "Increases your Agility by $s1 for $d.", ua = "Підвищує вашу спритність на $s1 на $d." },
    { en = "Increase your Critical Strike by ${$s1*6} decreasing by ${$s1} every $t2 sec.", ua = "Підвищує ваш критичний удар на ${$s1*6}, зменшуючись на ${$s1} кожні $t2 сек." },
    { en = "Summons a Blackwater Pirate to aid you in combat for $471404d.", ua = "Прикликає Пірата Чорноводдя, який допомагає вам у бою протягом $471404d." },
    { en = "When you deal damage you have a chance to gain $126700s1 Strength for $126700d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $126700s1 сили на $126700d." },
    { en = "While you remain stationary, gain $s2 Haste every $t1 sec stacking up to $u times. Lasts $d.", ua = "Поки ви залишаєтеся нерухомими, отримуйте $s2 швидкості кожні $t1 сек, складаючись до $u разів. Триває $d." },
    { en = "Your critical attacks have a chance to grant you $139170s1 Critical Strike for $139170d. This effect can stack up to $139170u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші критичні атаки мають шанс надати вам $139170s1 критичного удару на $139170d. Цей ефект складається до $139170u разів.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Absorbs up to $s1 damage from an attack that would kill you. When this effect occurs, you instantly heal for $225720s1 and then take all of the prevented damage over $229457d. May only occur once every $229333d.", ua = "Поглинає до $s1 шкоди від атаки, яка вбила б вас. Коли цей ефект спрацьовує, ви миттєво зцілюєтеся на $225720s1, а потім отримуєте всю відвернену шкоду протягом $229457d. Може спрацьовувати лише раз на $229333d." },
    { en = "Increases Agility by $s1 for $d.", ua = "Підвищує спритність на $s1 на $d." },
    { en = "Increases your parry by $s1 for $d.", ua = "Підвищує ваше парирування на $s1 на $d." },
    { en = "Your harmful spells and abilities have a high chance to summon a spirit shark that deals $s1 Frost damage split among your target and nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші шкідливі закляття та здібності мають високий шанс прикликати духа-акулу, що завдає $s1 шкоди Морозом, розподіленої між вашою ціллю та ворогами поблизу.\n\n\n\nШкода зростає за кожного враженого ворога, до $s2 ворогів." },
    { en = "Consume all Titanic Power to increase your critical strike, haste, or mastery by $s1 per Titanic Power accumulated, lasting $96927d.  The apparatus will always choose the highest of those three values.", ua = "Поглинає всю Титанічну Силу, щоб підвищити ваш критичний удар, швидкість або майстерність на $s1 за кожну накопичену Титанічну Силу, триваючи $96927d.  Апарат завжди обирає найвище з цих трьох значень." },
    { en = "Your attacks have a chance to cause spiraling winds to surround you, increasing your Agility by $s1 every $383756t2 sec, stacking up to $383756u times before quickly dissipating. Lasts $383756d.", ua = "Ваші атаки мають шанс оточити вас вируючими вітрами, підвищуючи вашу спритність на $s1 кожні $383756t2 сек, складаючись до $383756u разів, перш ніж швидко розвіятися. Триває $383756d." },
    { en = "When your attacks critical strike your target you have a chance to gain $s1 Agility for $362620d.", ua = "Коли ваші атаки критично вражають ціль, ви маєте шанс отримати $s1 спритності на $362620d." },
    { en = "Your attacks have a chance to grant $177035s1 Haste for $177035d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177035s1 швидкості на $177035d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Grants $s1 Versatility for $d.", ua = "Надає $s1 універсальності на $d." },
    { en = "When you deal damage you have a chance to gain Paragon, increasing your Strength or Agility by $67703s1 for $67703d.  Your highest stat is always chosen.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати Взірець, що підвищує вашу силу або спритність на $67703s1 на $67703d.  Завжди обирається ваша найвища характеристика." },
    { en = "Your attacks have a chance to cause you to breathe fire, burning enemies in front of you for ${$202841s1*3} damage over $202845d.", ua = "Ваші атаки мають шанс змусити вас дихнути вогнем, спалюючи ворогів перед вами на ${$202841s1*3} шкоди протягом $202845d." },
    { en = "When you deal damage you have a chance to gain $109742s1 critical strike for $109742d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109742s1 критичного удару на $109742d." },
    { en = "Your melee attacks have a chance to deal $s1 Nature damage split between the target and nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші атаки ближнього бою мають шанс завдати $s1 шкоди Природою, розподіленої між ціллю та ворогами поблизу.\n\n\n\nШкода зростає за кожного враженого ворога, до $s2 ворогів." },
    { en = "Your healing spells have a chance to increase your Critical Strike by $375289s1.", ua = "Ваші зцілювальні закляття мають шанс підвищити ваш критичний удар на $375289s1." },
    { en = "Your melee attacks have a chance to grant $92166s1 mastery for $92166d.", ua = "Ваші атаки ближнього бою мають шанс надати $92166s1 майстерності на $92166d." },
    { en = "When you fall below 50% health a Shadow Reflection manifests from the Emerald Nightmare, absorbing $222479s2% of damage taken for $222479d. Prevents up to $s3 total damage. This may only occur once every 2 min.", ua = "Коли ваше здоров'я падає нижче 50%, із Смарагдового Жахіття проявляється Тіньове Відображення, поглинаючи $222479s2% отриманої шкоди протягом $222479d. Запобігає загалом до $s3 шкоди. Може спрацьовувати лише раз на 2 хв." },
    { en = "Your melee attacks grant $107968s1 dodge for the next $107968d, stacking up to $107968u times.", ua = "Ваші атаки ближнього бою надають $107968s1 ухилення на наступні $107968d, складаючись до $107968u разів." },
    { en = "Increases attack power by $s1 when fighting Undead and Demons.  It also allows the acquisition of Scourgestones on behalf of the Argent Dawn.", ua = "Підвищує силу атаки на $s1 під час боротьби з Нежиттю та Демонами.  Також дозволяє збирати Камені Лиха від імені Срібного Світанку." },
    { en = "Your spells and abilities have a chance to grant $s1 Haste per Ysemerald you have equipped. Upon reaching $M2 stacks, all stacks are consumed and you gain $s3 secondary stats, split evenly for $376643d.", ua = "Ваші закляття та здібності мають шанс надати $s1 швидкості за кожен спорядженій вами Ісмарагд. Досягнувши $M2 складань, усі складання поглинаються, і ви отримуєте $s3 вторинних характеристик, розподілених порівну, на $376643d." },
    { en = "Your damaging spells and abilities have a chance to throw rusty scrap metal at your target, dealing $304113s1 damage.", ua = "Ваші шкодочинні закляття та здібності мають шанс жбурнути іржавий металобрухт у вашу ціль, завдаючи $304113s1 шкоди." },
    { en = "When you deal damage you have a chance to gain $71541s1 attack power for $71541d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $71541s1 сили атаки на $71541d." },
    { en = "Increases your current and maximum health by $s1 for $d.", ua = "Підвищує ваше поточне та максимальне здоров'я на $s1 на $d." },
    { en = "Your damaging and healing spells have a chance to call a raptora that graces you with her wisdom, increasing your intellect by $s1 for $367734d.", ua = "Ваші шкодочинні та зцілювальні закляття мають шанс прикликати раптору, яка благословляє вас своєю мудрістю, підвищуючи ваш інтелект на $s1 на $367734d." },
    { en = "Absorbs $s2% of the damage you take up to $s1 total damage. For every ${$s1/$s4} damage absorbed, you release a wave of heat dealing $s3 Fire damage split amongst enemies within $469815a yds.", ua = "Поглинає $s2% шкоди, яку ви отримуєте, до $s1 загальної шкоди. За кожні ${$s1/$s4} поглинутої шкоди ви вивільняєте хвилю жару, що завдає $s3 шкоди вогнем, розподіленої між ворогами в межах $469815a м." },
    { en = "Bite a friendly target, granting them $s1 Leech for $d. (20 sec recharge, 3 charges)", ua = "Кусає дружню ціль, надаючи їй $s1 висмоктування життя на $d. (Перезарядка 20 сек, 3 заряди)" },
    { en = "Maintain the current Oscillation for $d.", ua = "Підтримує поточну Осциляцію протягом $d." },
    { en = "Select a player in your party or raid, granting them $368513s2 of their highest secondary stat, and granting you $368513s1 of that same stat, for $368512d.", ua = "Оберіть гравця у вашій групі чи рейді, надаючи йому $368513s2 його найвищої вторинної характеристики та надаючи вам $368513s1 тієї самої характеристики на $368512d." },
    { en = "Each time your spells heal you have a chance to gain $126640s1 Versatility for $126640d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші заклинання зцілюють вас, є шанс отримати $126640s1 універсальності на $126640d. ($h% шанс, перезарядка ${$proccooldown} сек)" },
    { en = "Gain $u charges of Maddening Whispers. Your damaging spells transfer one Maddening Whisper to the target for $222046d. This may only occur once every ${$proccooldown}.1 sec. When all Whispers have been applied, each deals $s1 Shadow damage.", ua = "Отримайте $u зарядів Божевільного Шепоту. Ваші заклинання, що завдають шкоди, переносять один Божевільний Шепіт на ціль на $222046d. Це може ставатися лише раз на ${$proccooldown}.1 сек. Коли всі Шепоти застосовано, кожен завдає $s1 шкоди тінню." },
    { en = "Your melee and ranged attacks have a chance to increase your Haste by $65019s1 for $65019d.", ua = "Ваші ближні та дистанційні атаки мають шанс підвищити вашу швидкість на $65019s1 на $65019d." },
    { en = "Your attacks have a chance to unleash a Radiant Strike at your target, dealing ${$s1*$<rolemult>} Holy damage split among nearby enemies.", ua = "Ваші атаки мають шанс вивільнити Сяйливий Удар по вашій цілі, завдаючи ${$s1*$<rolemult>} шкоди світлом, розподіленої між ворогами поблизу." },
    { en = "Your damaging spells have a chance to grant you $225719s1 Haste for $225719d, stacking up to 5 times. Stacking does not refresh duration.", ua = "Ваші заклинання, що завдають шкоди, мають шанс надати вам $225719s1 швидкості на $225719d, накопичуючись до 5 разів. Накопичення не оновлює тривалість." },
    { en = "Your melee attacks have a chance to grant $91363s1 Strength for $91363d.", ua = "Ваші ближні атаки мають шанс надати $91363s1 сили на $91363d." },
    { en = "Your damaging spells have a chance to draw a minion from the void, sending it running at your target where it explodes, dealing $s1 Shadow damage split between all nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші заклинання, що завдають шкоди, мають шанс прикликати посіпаку з Порожнечі, відправляючи його до вашої цілі, де він вибухає, завдаючи $s1 шкоди тінню, розподіленої між усіма ворогами поблизу.\n\n\n\nШкода зростає за кожного враженого ворога, до $s2 ворогів." },
    { en = "Your melee attacks have a chance of stirring a nova of blood that deals $s1 Shadow damage to 5 enemies within $472232a yd of you every sec for $472228d.", ua = "Ваші ближні атаки мають шанс здійняти кров'яну нову, що завдає $s1 шкоди тінню 5 ворогам у межах $472232a м від вас щосекунди протягом $472228d." },
    { en = "Your melee and ranged attacks have a chance to grant $122270s1 critical strike for $122270d.", ua = "Ваші ближні та дистанційні атаки мають шанс надати $122270s1 критичного удару на $122270d." },
    { en = "Your attacks have a chance to grant $176912s1 Strength for $176912d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176912s1 сили на $176912d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your melee and ranged attacks have a chance to grant $92052s1 critical strike for $92052d.", ua = "Ваші ближні та дистанційні атаки мають шанс надати $92052s1 критичного удару на $92052d." },
    { en = "Absorbs up to $s1 damage from an attack that would kill you. When this effect occurs, you instantly heal for $288189s1 and then gain Bwonsamdi's Bargain absorbing healing equal to $s3% of the initial damage prevented. May only occur once every $288194d.", ua = "Поглинає до $s1 шкоди від атаки, яка б вас убила. Коли цей ефект спрацьовує, ви миттєво зцілюєтеся на $288189s1 й отримуєте Угоду Бвонсамді, що поглинає зцілення в розмірі $s3% від спочатку відверненої шкоди. Може ставатися лише раз на $288194d." },
    { en = "Your harmful spells have a chance to increase your Intellect by $194627s1 for $194627d.", ua = "Ваші шкідливі заклинання мають шанс підвищити ваш інтелект на $194627s1 на $194627d." },
    { en = "Increases spell power by $s1 for $d.", ua = "Підвищує силу заклять на $s1 на $d." },
    { en = "Envenom also increases the critical strike chance of Mutilate by $s1%.", ua = "Отруєння також підвищує шанс критичного удару Каліцтва на $s1%." },
    { en = "Open the spoils and loot the first item you find to gain its fleeting power, increasing a secondary stat by $381766s1 for $s2 sec.", ua = "Відкрийте трофеї та підберіть перший знайдений предмет, щоб здобути його скороминущу силу, підвищивши вторинну характеристику на $381766s1 на $s2 сек." },
    { en = "Increases attack power by $s1 for $d.", ua = "Підвищує силу атаки на $s1 на $d." },
    { en = "Your damage dealing spells have a chance to trigger a Shadowbolt Volley, dealing $109798s1 damage to all enemies within $109798A1 yards of your current target.", ua = "Ваші заклинання, що завдають шкоди, мають шанс викликати Залп Тіньових Стріл, завдаючи $109798s1 шкоди всім ворогам у межах $109798A1 м від вашої поточної цілі." },
    { en = "Your attacks have a chance to increase your Mastery by $202908s1 and heal you for $202908o2 over $202908d.", ua = "Ваші атаки мають шанс підвищити вашу майстерність на $202908s1 та зцілити вас на $202908o2 протягом $202908d." },
    { en = "Restores $s1 mana every second for $d.", ua = "Відновлює $s1 мани щосекунди протягом $d." },
    { en = "Your harmful spells and abilities have a chance to manifest a fel elemental by your side for $414976d, periodically dealing $s1 Fire damage to your target and increasing your Haste by $s2.", ua = "Ваші шкідливі заклинання та здібності мають шанс проявити поряд із вами скверноелементаля на $414976d, що періодично завдає $s1 шкоди вогнем вашій цілі й підвищує вашу швидкість на $s2." },
    { en = "Chance on melee and ranged critical strike to increase your haste by $58904s1 for $58904d.", ua = "Шанс під час критичного ближнього чи дистанційного удару підвищити вашу швидкість на $58904s1 на $58904d." },
    { en = "Your spells and abilities have a chance to grant $277181s1 primary stat for $277181d.", ua = "Ваші заклинання та здібності мають шанс надати $277181s1 основної характеристики на $277181d." },
    { en = "Spores surrounds you, making you gain [A] shield for [B]sec. Upon expiration gain [C] leech for [D] sec.", ua = "Спори оточують вас, надаючи вам [A] щита на [B] сек. По завершенні ви отримуєте [C] висмоктування життя на [D] сек." },
    { en = "Consumes all applications of Heart's Revelation, increasing your haste by $s1 per application consumed.  Lasts $d.", ua = "Поглинає всі застосування Одкровення Серця, підвищуючи вашу швидкість на $s1 за кожне поглинуте застосування. Триває $d." },
    { en = "Summon a ring of light on a specific location that lasts for $d.", ua = "Прикликає кільце світла в певному місці, що триває $d." },
    { en = "Your damaging spells and abilities have the chance to grant Vivaciousness, increasing secondary stats by $s1 and Speed or Avoidance by $s2 for $454978d based on the school it was activated from.", ua = "Ваші заклинання та здібності, що завдають шкоди, мають шанс надати Жвавість, підвищуючи вторинні характеристики на $s1 та швидкість пересування чи ухиляння на $s2 на $454978d залежно від школи магії, якою її було активовано." },
    { en = "Increases Intellect by $s1 for $d1.", ua = "Підвищує інтелект на $s1 на $d1." },
    { en = "Your spells have a chance to deal $s1 damage or $s2 healing to a target with the lowest health within $384114a yds, based on the spell you cast.", ua = "Ваші заклинання мають шанс завдати $s1 шкоди або зцілити на $s2 ціль із найнижчим запасом здоров'я в межах $384114a м, залежно від накладеного вами заклинання." },
    { en = "Your melee and ranged attacks have a chance to grant $92126s1 critical strike for $92126d.", ua = "Ваші ближні та дистанційні атаки мають шанс надати $92126s1 критичного удару на $92126d." },
    { en = "Your healing spells have a low chance to create $s2 Fragments of Life near your location for $345496d. Allies who collect a Fragment of Life are healed for $s1, and grant $345502s1 Versatility to your party for $345499d.", ua = "Ваші зцілювальні заклинання мають низький шанс створити $s2 Уламки Життя поблизу вашого місця на $345496d. Союзники, які підбирають Уламок Життя, зцілюються на $s1 і надають $345502s1 універсальності вашій групі на $345499d." },
    { en = "Falling below $s1% health puts you to sleep for $339738d and restores $339738s1 health. This effect may only occur once every $339736d.", ua = "Коли ваше здоров'я падає нижче $s1%, ви засинаєте на $339738d і відновлюєте $339738s1 здоров'я. Цей ефект може спрацьовувати лише раз на $339736d." },
    { en = "Your spells and abilities have a chance to uproot a Lightspawn Lasher to aid you in combat for $1263077d, dealing up to ${$<rolemult>*($s1*10)} Physical damage.\n\n\n\nThe Lightspawn Lasher then withers, bursting into light-infused sap and inflicting ${$<rolemult>*$s2} Holy damage split among nearby enemies.", ua = "Ваші заклинання та здібності мають шанс вирвати з землі Світлородного Шмагача, який допомагатиме вам у бою впродовж $1263077d, завдаючи до ${$<rolemult>*($s1*10)} фізичної шкоди.\n\n\n\nПотім Світлородний Шмагач в'яне й вибухає просоченим світлом соком, завдаючи ${$<rolemult>*$s2} священної шкоди, розподіленої між ворогами поблизу." },
    { en = "Your melee and ranged attacks have a chance to grant $118610s1 mastery for $118610d.", ua = "Ваші атаки ближнього та дального бою мають шанс надати $118610s1 майстерності на $118610d." },
    { en = "Your damaging and healing abilities have a chance to grant you Call of the Horde, increasing your highest secondary stat by $s2 for 10 sec.", ua = "Ваші здібності, що завдають шкоди й зцілюють, мають шанс надати вам Поклик Орди, підвищуючи вашу найвищу вторинну характеристику на $s2 на 10 сек." },
    { en = "Casting spells and abilities has a low chance to refund $s1 mana. If below $s3% mana the seal breaks restoring $s2 mana. \n\nThe seal can only be broken once every $s4 minutes.", ua = "Застосування заклять і здібностей має низький шанс повернути $s1 мани. Якщо мани менше за $s3%, печатка розбивається, відновлюючи $s2 мани.\n\nПечатку можна розбити лише раз на $s4 хв." },
    { en = "Increases critical strike by $s1 for $d1.", ua = "Підвищує критичний удар на $s1 на $d1." },
    { en = "Has a 2% chance when struck in combat of increasing your primary stat by $s1 for $21970d1.", ua = "Має 2% шанс при отриманні удару в бою збільшити вашу основну характеристику на $s1 на $21970d1." },
    { en = "Increases Versatility by $s1 for $d1.", ua = "Підвищує універсальність на $s1 на $d1." },
    { en = "Summon the Black Brewmaiden, who will smite your foes with your empty tankards. Wave at her for Brewfest Brew!", ua = "Прикликати Чорну Шинкарку, яка каратиме ваших ворогів вашими порожніми кухлями. Помахайте їй, щоб отримати Пиво Хмільного свята!" },
    { en = "Your ranged attacks and spells have a chance to summon a behemoth from the deep to swallow your target whole, dealing $s1 Nature damage split amongst you and all nearby enemies.", ua = "Ваші атаки дального бою та заклинання мають шанс прикликати чудовисько з глибин, що цілком поглинає вашу ціль, завдаючи $s1 шкоди від сил природи, розподіленої між вами й усіма ворогами поблизу." },
    { en = "Increases your Versatility by $s1 for $d1.", ua = "Підвищує вашу універсальність на $s1 на $d1." },
    { en = "Your damaging spells and abilities have a chance to place a Spelunker's Candle on your head, granting $s2 Critical Strike for $455420d.\n\n\n\nMoving within 3 yards of an ally places the Spelunker's Candle on both heads, sharing the effect for the remaining duration.", ua = "Ваші заклинання та здібності, що завдають шкоди, мають шанс встановити Свічку Спелеолога на вашій голові, надаючи $s2 критичного удару на $455420d.\n\n\n\nПереміщення в межах 3 метрів від союзника встановлює Свічку Спелеолога на обидві голови, розділяючи ефект на час, що лишився." },
    { en = "For the next $d, your direct heals increase healing received by their target by up to $60518s1.  This effect lasts $60518d and stacks up to 5 times.", ua = "Упродовж наступних $d ваші прямі зцілення підвищують зцілення, отримане їхньою ціллю, до $60518s1. Цей ефект триває $60518d і накопичується до 5 разів." },
    { en = "Increases dodge by $s1 for $d.", ua = "Підвищує ухиляння на $s1 на $d." },
    { en = "Your melee and ranged attacks have a chance to grant $92349s1 haste for $92349d.", ua = "Ваші атаки ближнього та дального бою мають шанс надати $92349s1 швидкості на $92349d." },
    { en = "Your melee attacks have a chance to call a vombata to charge the enemy, causing $s1 Physical damage.", ua = "Ваші атаки ближнього бою мають шанс прикликати вомбату, що ринеться на ворога, завдаючи $s1 фізичної шкоди." },
    { en = "Increases Dodge by $s1 for $d.", ua = "Підвищує ухиляння на $s1 на $d." },
    { en = "Your spells and abilities have a chance to shroud you in void, absorbing $s2 damage for $315763d. Your Critical Strike is increased by $315774s1 while the shroud persists.", ua = "Ваші заклинання та здібності мають шанс огорнути вас Порожнечею, що поглинає $s2 шкоди впродовж $315763d. Доки огортання триває, ваш критичний удар підвищено на $315774s1." },
    { en = "Consume Brimming Life-Pod to gain $384658s1 Versatility and $384658s3 Maximum Health per stack consumed. Lasts $d.", ua = "Спожити Налиту Життям Капсулу, щоб отримати $384658s1 універсальності та $384658s3 максимального здоров'я за кожен спожитий заряд. Триває $d." },
    { en = "Your damaging spells have a chance to inflict $224078s1 Nature damage and slow the target by $224078s2% for $224078d.", ua = "Ваші заклинання, що завдають шкоди, мають шанс завдати $224078s1 шкоди від сил природи й уповільнити ціль на $224078s2% впродовж $224078d." },
    { en = "Your attacks and spells have a chance to summon a Risen Ravasaur to your side for $274478d.", ua = "Ваші атаки та заклинання мають шанс прикликати Воскреслого Равазавра вам на допомогу на $274478d." },
    { en = "Weave an arcane cocoon around yourself and four nearby allies for $d, reducing their damage taken by $s2% until $1232719s1 damage has been prevented.\n\n\n\nIf a cocoon expires, it bursts to heal an injured ally for $s3% of its remaining power.", ua = "Сплести довкола себе та чотирьох союзників поблизу таємний кокон на $d, зменшуючи отриману ними шкоду на $s2%, доки не буде відвернено $1232719s1 шкоди.\n\n\n\nКоли кокон спливає, він вибухає, зцілюючи пораненого союзника на $s3% залишкової сили." },
    { en = "Activate Soul Igniter, sacrificing up to $345214s1 health over $345211d to empower Blazing Surge.\n\n\n\nReactivate to cast Blazing Surge, dealing ${$345214s2*(1+$@versadmg)} Fire damage split between enemies in a $345215a1 yd cone, plus up to $345214s4% additional damage, based on how long Soul Igniter was active.\n\n\n\nDamage is increased per enemy struck, up to $s2 enemies. (1 min Cooldown)", ua = "Вмикає Душезапальник, жертвуючи до $345214s1 здоров'я протягом $345211d, щоб підсилити Полум'яний сплеск.\n\n\n\nУвімкніть повторно, щоб застосувати Полум'яний сплеск, завдаючи ${$345214s2*(1+$@versadmg)} одиниць Вогняної шкоди, що ділиться між ворогами в конусі завдовжки $345215a1 м, а також до $345214s4% додаткової шкоди залежно від того, як довго був активний Душезапальник.\n\n\n\nШкода зростає за кожного ураженого ворога, до $s2 ворогів. (Час відновлення 1 хв)" },
    { en = "All damage received is reduced by ${$AP*$m1/100} (increased by Attack Power). All damage prevented this way is dealt back to the attacker as Nature damage. This effect cannot absorb more than $s2% of an attack.", ua = "Уся отримана шкода зменшується на ${$AP*$m1/100} (підвищується силою атаки). Уся відвернена в такий спосіб шкода завдається нападнику як шкода від сил природи. Цей ефект не може поглинути більше за $s2% атаки." },
    { en = "Your attacks have a chance to reduce the remaining cooldown on $?a137006[Empower Rune Weapon]?a137007[Summon Gargoyle]?a212612[Metamorphosis]?a137011[Berserk]?a137015[Aspect of the Wild]?a137016[Trueshot]?a137017[Aspect of the Eagle]?a137025[Storm, Earth, and Fire]?a137027[Avenging Wrath]?a137037[Vendetta]?a137036[Adrenaline Rush]?a137035[Shadow Blades]?a137041[Feral Spirit]?a137049[Battle Cry]?a137050[Battle Cry][one of your powerful abilities] by $s1 sec.|CFF808080$?!(a137006|a137007|a212612|a137011|a137015|a137016|a137017|a137025|a137027|a137037|a137036|a137035|a137041|a137049|a137050)[\n\n\n\nNot valid for your specialization.][]|R", ua = "Ваші атаки мають шанс зменшити час відновлення, що залишився, $?a137006[«Підсилення рунічної зброї»]?a137007[«Прикликання ґаргуйлі»]?a212612[«Метаморфози»]?a137011[«Берсерка»]?a137015[«Аспекту дикості»]?a137016[«Влучного пострілу»]?a137017[«Аспекту орла»]?a137025[«Шторм, Земля і Вогонь»]?a137027[«Караючого гніву»]?a137037[«Вендети»]?a137036[«Приплив адреналіну»]?a137035[«Тіньових клинків»]?a137041[«Дикого духа»]?a137049[«Бойового кличу»]?a137050[«Бойового кличу»][однієї з ваших потужних здібностей] на $s1 сек.|CFF808080$?!(a137006|a137007|a212612|a137011|a137015|a137016|a137017|a137025|a137027|a137037|a137036|a137035|a137041|a137049|a137050)[\n\n\n\nНе діє для вашої спеціалізації.][]|R" },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $92184s1 armor for $92184d.   Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $92184s1 броні на $92184d. Може спрацьовувати не частіше ніж раз на 30 сек." },
    { en = "Caber Toss!", ua = "Метання колоди!" },
    { en = "Grants you $s1 Haste for $d.", ua = "Надає вам $s1 швидкості на $d." },
    { en = "Your attacks have a chance to activate Devilsaur's Stampede, causing your steps to deal ${$224061s1*($224060d/$224060t1+1)} Physical damage to nearby enemies over $224060d.", ua = "Ваші атаки мають шанс активувати Тиснява Диявозавра, через що ваші кроки завдають ${$224061s1*($224060d/$224060t1+1)} фізичної шкоди ворогам поблизу впродовж $224060d." },
    { en = "Spray your target with volatile acid, dealing ${$<rolemult>*$444488s1} Nature damage every $447471t1 sec for $447471d. \n\n\n\nYour abilities intensify the acid's damage by an additional ${$<rolemult>*$444488s1} per sec for the remaining duration and splash up to 5 nearby enemies for ${$<rolemult>*$444488s2} Nature damage per stack.", ua = "Обприскати ціль нестійкою кислотою, завдаючи ${$<rolemult>*$444488s1} шкоди від сил природи кожні $447471t1 сек упродовж $447471d.\n\n\n\nВаші здібності підсилюють шкоду від кислоти на додаткові ${$<rolemult>*$444488s1} за секунду на час, що лишився, і розхлюпуються на до 5 ворогів поблизу, завдаючи ${$<rolemult>*$444488s2} шкоди від сил природи за кожен заряд." },
    { en = "Inject $278086u stacks of Mutating Antibodies into a friendly target for $278086d. Your direct heals on that ally will consume a Mutating Antibody to restore an additional $278088s1 health.", ua = "Ввести $278086u зарядів Мутаційних Антитіл у дружню ціль на $278086d. Ваші прямі зцілення цього союзника споживатимуть Мутаційне Антитіло, відновлюючи додаткові $278088s1 здоров'я." },
    { en = "Increases your Intellect by $s1 for $d.", ua = "Підвищує ваш інтелект на $s1 на $d." },
    { en = "Reduces the threat you generate by 35% for $d.", ua = "Зменшує загрозу, яку ви створюєте, на 35% на $d." },
    { en = "Select a player in your party or raid, granting them $351927s2 of their highest secondary stat, and granting you $351927s1 of that same stat, for $351952d.", ua = "Обрати гравця у вашій групі чи рейді, надаючи йому $351927s2 його найвищої вторинної характеристики й надаючи вам $351927s1 цієї ж характеристики на $351952d." },
    { en = "Increases your Haste by $s1 and Speed by $s2, stacking up to $u times over ${$288173t1*5} sec. The stacks increase faster and faster as the engine accelerates. The engine runs for a total of ${$288173t1*5+$288173t1*4} sec.", ua = "Збільшує ваш Поспіх на $s1, а Швидкість на $s2, накопичуючись до $u разів протягом ${$288173t1*5} сек. Заряди накопичуються дедалі швидше, у міру того як двигун прискорюється. Двигун працює загалом ${$288173t1*5+$288173t1*4} сек." },
    { en = "Activates your Elementium Dragonling to fight for you for $d.", ua = "Активує вашого Елементієвого Дракончика, який битиметься за вас упродовж $d." },
    { en = "Your damaging spells have a chance to launch an orb of charged blood at your target, dealing $s1 Shadow damage split among all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Ваші шкідливі закляття мають шанс випустити в ціль кулю наелектризованої крові, завдаючи $s1 одиниць Тіньової шкоди, що ділиться між усіма ворогами поблизу. Завдає підвищеної шкоди, коли вражає кілька цілей." },
    { en = "Your critical heals have a chance to instantly heal the most injured nearby party member for $109822s1.", ua = "Ваші критичні зцілення мають шанс миттєво зцілити найтяжче пораненого учасника групи поблизу на $109822s1." },
    { en = "Restores $s1 mana.", ua = "Відновлює $s1 мани." },
    { en = "Your damaging spells have a chance to increase your Critical Strike by $353492s1 for $d, stacking up to $u times.", ua = "Ваші закляття, що завдають шкоди, мають шанс підвищити ваш Критичний удар на $353492s1 на $d, накопичуючись до $u разів." },
    { en = "Removes all movement impairing effects and all effects which cause loss of control of your character.", ua = "Знімає всі ефекти, що перешкоджають пересуванню, і всі ефекти, що спричиняють втрату контролю над вашим персонажем." },
    { en = "Douse the enemy in hot oil, dealing $268554s1 Fire damage.", ua = "Обливає ворога гарячою олією, завдаючи $268554s1 шкоди вогнем." },
    { en = "Your ranged offensive abilities have a high chance to apply a stack of Sulfuric Burning to the target, dealing ${$s1*($406744d/($406744t1))} Fire damage over $406744d. When applying the $406744uth stack of Sulfuric Burning, all stacks are removed and the target is disoriented for $406747d.", ua = "Ваші далекобійні наступальні здібності з високим шансом накладають заряд Сірчаного горіння на ціль, завдаючи ${$s1*($406744d/($406744t1))} вогняної шкоди протягом $406744d. При накладанні $406744u-го заряду Сірчаного горіння всі заряди знімаються, а ціль дезорієнтується на $406747d." },
    { en = "Returns you to the sanctuary of Frostwolf Keep.", ua = "Повертає вас до притулку Фортеці Морозного Вовка." },
    { en = "Place a ward on the ground for $d which increases your Haste by $268311s1 and your Speed by $268311s2 while you stand within it.", ua = "Розміщує на землі оберіг на $d, що підвищує вашу швидкість на $268311s1 та темп пересування на $268311s2, поки ви перебуваєте в його межах." },
    { en = "Sustaining fatal damage throws you $s1 seconds into the past, restoring up to $s2 health lost during that time.\n\n\n\nFor the next $417139d, your Haste is increased by $s4 and enemies responsible for your untimely demise deal $s3% less damage to you.\n\n\n\nThis effect can only occur once every $417069d.", ua = "Отримання смертельної шкоди відкидає вас на $s1 секунд у минуле, відновлюючи до $s2 здоров'я, втраченого за цей час.\n\n\n\nНаступні $417139d ваша швидкість підвищена на $s4, а вороги, винні у вашій передчасній загибелі, завдають вам на $s3% менше шкоди.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $417069d." },
    { en = "When you deliver a melee or ranged critical strike, you have a chance to gain Blessing of the Celestials, increasing your Agility by $128984s1 for $128984d.", ua = "Коли ви завдаєте критичного удару в ближньому або дальньому бою, ви маєте шанс отримати Благословення Небожителів, що підвищує вашу спритність на $128984s1 на $128984d." },
    { en = "Summons a tracking hound that will protect you for $d.", ua = "Прикликає мисливського пса, який захищатиме вас протягом $d." },
    { en = "Increases your dodge by $s1 for $d.", ua = "Підвищує ваше ухилення на $s1 на $d." },
    { en = "Collects $45062m1 Holy Energy from healing spells you cast.  Cannot collect more than ${$45062m1*20} Holy Energy.", ua = "Збирає $45062m1 Священної енергії від зцілювальних заклять, які ви накладаєте. Не може зібрати більше ніж ${$45062m1*20} Священної енергії." },
    { en = "Your harmful spells and abilities have a chance to impale the target with a shard of jagged ice, stacking up to $388929u.", ua = "Ваші шкідливі закляття та здібності мають шанс простромити ціль уламком зубчастого льоду, накопичуючись до $388929u разів." },
    { en = "Increases Strength by $s1 for $d.", ua = "Підвищує силу на $s1 на $d." },
    { en = "Your melee and ranged attacks have a chance to grant $122313s1 critical strike for $122313d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $122313s1 критичного удару на $122313d." },
    { en = "Charge at an enemy, inflicting $148535s2 Fire damage to enemies within $148535A2 yards and knocking them down for $148535d.", ua = "Налітає на ворога, завдаючи $148535s2 шкоди вогнем ворогам у радіусі $148535A2 м та збиваючи їх з ніг на $148535d." },
    { en = "Your abilities have a chance to call a member of the Goon Squad to attack your target for $1217427d. Gaining Bloodlust or a similar effect summons the whole crew.", ua = "Ваші здібності мають шанс прикликати учасника Загону Бандюганів, який атакуватиме вашу ціль протягом $1217427d. Отримання Кровожерливості або подібного ефекту прикликає всю братію." },
    { en = "Increases your mastery by $s1 for $d.", ua = "Підвищує вашу майстерність на $s1 на $d." },
    { en = "Summons forth several Void Tendrils to aid you in combat for $189422d.", ua = "Прикликає кілька Щупалець Порожнечі, які допомагатимуть вам у бою протягом $189422d." },
    { en = "\"Borrow\" power from an alternate timeline for personal gain, increasing your Haste by $s1 for $d and triggering a Paradox $417543d later.\n\n\n\nIf the Paradox arrives, you will be frozen in time, completely unable to act or move for $417587d. Killing enemies steals their remaining time to partially delay the Paradox by $s3 sec, with major enemies restoring the timeline completely.", ua = "«Позичає» силу з альтернативної часової лінії задля власної вигоди, підвищуючи вашу швидкість на $s1 на $d та запускаючи Парадокс через $417543d.\n\n\n\nЯкщо Парадокс настане, ви будете заморожені в часі, повністю нездатні діяти чи рухатися протягом $417587d. Убивство ворогів краде їхній залишковий час, частково відтерміновуючи Парадокс на $s3 сек, а важливі вороги відновлюють часову лінію повністю." },
    { en = "Decreases the mana cost of all Druid shapeshifting forms by $s1 for $d.", ua = "Зменшує витрати мани на всі форми перевтілення друїда на $s1 на $d." },
    { en = "When you parry an attack, you gain $92208s1 dodge for $92208d.  Cannot occur more often than once every 60 sec.", ua = "Коли ви парируєте атаку, ви отримуєте $92208s1 ухилення на $92208d. Може спрацьовувати не частіше, ніж раз на 60 сек." },
    { en = "Each time your attacks hit, you have a chance to gain $126649s1 critical strike for $126649d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $126649s1 критичного удару на $126649d. ($h% шанс, ${$proccooldown} сек відновлення)" },
    { en = "Envelop up to $s2 allies in the targeted area in shared shields for $d, preventing up to $<absorb> damage taken by any of them. Damage prevented is increased when affecting multiple allies.", ua = "Огортає до $s2 союзників у цільовій ділянці спільними щитами на $d, запобігаючи до $<absorb> отриманої шкоди для будь-кого з них. Запобігнута шкода зростає, коли впливає на кількох союзників." },
    { en = "Recklessly feed a portion of your essence to the forge, granting you ${$1232797s1} $pri decaying over $d at the cost of $s3% of your maximum health.", ua = "Необачно згодовує частину вашої сутності горнилу, надаючи вам ${$1232797s1} $pri, що згасає протягом $d, ціною $s3% вашого максимального здоров'я." },
    { en = "Your attacks have a chance to poison the target, dealing $202761o1 Nature damage over $202761d.", ua = "Ваші атаки мають шанс отруїти ціль, завдаючи $202761o1 шкоди силами природи протягом $202761d." },
    { en = "Marrowrend deals $s2% increased damage, and heals you for $s1% of damage dealt.", ua = "Шматування Кісткового Мозку завдає на $s2% більше шкоди та зцілює вас на $s1% завданої шкоди." },
    { en = "When you deal damage you have a chance to gain $190026s1 Agility for $190026d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $190026s1 спритності на $190026d." },
    { en = "Summons Martar the Not-So-Smart to fight, adventure, and frolic with you for $d.", ua = "Прикликає Мартара Не-Дуже-Кмітливого, який протягом $d битиметься, шукатиме пригод і пустуватиме разом з вами." },
    { en = "Your spells and abilities have a chance to grant you $268604s1 Critical Strike for $268604d.", ua = "Ваші закляття та здібності мають шанс надати вам $268604s1 критичного удару на $268604d." },
    { en = "When you deal damage you have a chance to gain $107982s1 haste for $107982d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $107982s1 швидкості на $107982d." },
    { en = "Flash of Light and Holy Light have a 15% chance to grant your target $40471o healing over $40471d, and your Judgements have a 50% chance to inflict $40472o damage on their target over $40472d.", ua = "Спалах Світла та Священне Світло мають 15% шанс надати вашій цілі $40471o зцілення протягом $40471d, а ваші Присуди мають 50% шанс завдати $40472o шкоди їхній цілі протягом $40472d." },
    { en = "Increases your Versatility by $s1 for $d.", ua = "Підвищує вашу універсальність на $s1 на $d." },
    { en = "Increases your maximum health by $23782s1 for 20 sec.  After the effects wear off, you will lose the extra maximum health.", ua = "Підвищує ваше максимальне здоров'я на $23782s1 на 20 сек. Коли ефект завершується, ви втрачаєте додаткове максимальне здоров'я." },
    { en = "Your spells have a chance to charge the device and request a Backfill Barrel near your target's location. Damaging the barrel causes it to explode, inflicting ${$<rolemult>*$s1} Fire damage split between nearby enemies.", ua = "Ваші закляття мають шанс зарядити пристрій і викликати Бочку Поповнення поблизу місця розташування вашої цілі. Завдання шкоди бочці спричиняє її вибух, завдаючи ${$<rolemult>*$s1} шкоди вогнем, розподіленої між ворогами поблизу." },
    { en = "Your melee and ranged attacks grant $92085s1 Agility.  Lasts $92085d, stacking up to $92085u times.", ua = "Ваші атаки в ближньому та дальньому бою надають $92085s1 спритності. Триває $92085d, накопичуючись до $92085u разів." },
    { en = "Your melee and ranged attacks have a chance to grant $120178s1 critical strike for $120178d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $120178s1 критичного удару на $120178d." },
    { en = "Your abilities have a very high chance to lash out with a Hateful Strike, inflicting ${$s2*$<rolemult>} Physical damage to an enemy and healing you for $s1. These effects are increased by ${($s4*100)-100}% while you are below $s3% health.", ua = "Ваші вміння мають дуже високий шанс завдати Ненависного удару, завдаючи ${$s2*$<rolemult>} фізичної шкоди ворогові й зцілюючи вас на $s1. Ці ефекти посилюються на ${($s4*100)-100}%, поки ваше здоров'я нижче $s3%." },
    { en = "Reduce damage taken by $s3% for $d or until $433000s1 damage has been absorbed. Your Armor is increased by $433000s2 while the shield holds, further increasing by $433000s4 when struck, stacking up to $434270u times. The shield explodes when broken, dealing $433000s3 Physical damage split between all nearby enemies.\n\n\n\nDamage increased per enemy struck, up to 5.", ua = "Зменшує отриману шкоду на $s3% на $d або доки не буде поглинуто $433000s1 шкоди. Поки щит тримається, ваша броня підвищена на $433000s2, а при отриманні удару підвищується ще на $433000s4, накопичуючись до $434270u разів. Коли щит руйнується, він вибухає, завдаючи $433000s3 фізичної шкоди, розподіленої між усіма ворогами поблизу.\n\n\n\nШкода зростає за кожного враженого ворога, до 5." },
    { en = "Your heals grant the target Leech for $184671d, equal to ${$<WarlordsTrinketNerf>*$m1/100}.2% of the effective healing done.", ua = "Ваше зцілення надає цілі Висмоктування Життя на $184671d, що дорівнює ${$<WarlordsTrinketNerf>*$m1/100}.2% дієвого зціленого здоров'я." },
    { en = "Your spells have a chance to increase your spell power by $60494s1 for $60494d1.", ua = "Ваші закляття мають шанс підвищити вашу силу заклять на $60494s1 на $60494d1." },
    { en = "Your attacks have a chance to grant $176974s1 Versatility for $176974d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176974s1 універсальності на $176974d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your melee attacks grant $91338s1 Strength.   Lasts $91338d, stacking up to $91338u times.", ua = "Ваші атаки ближнього бою надають $91338s1 сили.   Триває $91338d, накопичується до $91338u разів." },
    { en = "Your damaging attacks and spells have a chance to flip a coin granting $s1 of a secondary stat for 15 sec. Heads is Critical Strike, and Tails is Haste.", ua = "Ваші атаки та закляття, що завдають шкоди, мають шанс підкинути монету, яка надає $s1 вторинної характеристики на 15 сек. Орел — критичний удар, решка — швидкість." },
    { en = "The Core's unstable energies will randomly buff one of your secondary stats for $s1. This lasts between 10 and 30 sec before randomly changing to another stat.", ua = "Нестабільні енергії Ядра випадково підсилюють одну з ваших вторинних характеристик на $s1. Це триває від 10 до 30 сек., перш ніж випадково зміниться на іншу характеристику." },
    { en = "Your attacks have a chance to harmonize with the shard, granting you $268439s1 Agility for $268439d.", ua = "Ваші атаки мають шанс ввійти в гармонію з осколком, надаючи вам $268439s1 спритності на $268439d." },
    { en = "Your special attacks have a chance to give you $37174s1 critical strike for $37174d.", ua = "Ваші особливі атаки мають шанс надати вам $37174s1 критичного удару на $37174d." },
    { en = "Your melee attacks have a chance to trigger Cruelty for $146285d.  While Cruelty is active, you gain $146285s1 Critical Strike every $146285t1 sec, stacking up to $146293u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки ближнього бою мають шанс активувати Жорстокість на $146285d.  Поки Жорстокість активна, ви отримуєте $146285s1 критичного удару кожні $146285t1 сек, накопичуючись до $146293u разів.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to grant you $148899s1 Strength for $148899d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $148899s1 сили на $148899d.  ($h% шанс, ${$proccooldown} сек перезарядки)" },
    { en = "Your spells and abilities have a chance to grant you $285496s1 Mastery for $285496d.", ua = "Ваші закляття та здібності мають шанс надати вам $285496s1 майстерності на $285496d." },
    { en = "Swipe at a the nearest enemy for $s1 Physical damage and gain 1 stack of $@spellname421994 whenever you or an ally takes damage, granting $s2 $pri and stacking up to $421994u times. This effect may occur every 3 sec.\n\n\n\nAt $421994u stacks of $@spellname421994, gain $@spellname422016 for $422016d before consuming them, counterattacking all blows and regenerating $s3 health every $434251T1 sec. \n\n\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "Б'є найближчого ворога, завдаючи $s1 фізичної шкоди, та надає 1 заряд $@spellname421994, коли ви або союзник зазнаєте шкоди, даючи $s2 $pri та накопичуючись до $421994u разів. Цей ефект може спрацьовувати кожні 3 с.\n\n\n\nЗа $421994u зарядів $@spellname421994 ви отримуєте $@spellname422016 на $422016d, перш ніж витратити їх, контратакуючи всі удари й відновлюючи $s3 здоров'я кожні $434251T1 с. \n\n\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Дійсно лише для спеціалізацій танка.|r]" },
    { en = "Restores $s1 health every $t1 sec.", ua = "Відновлює $s1 здоров'я кожні $t1 сек." },
    { en = "Your damaging spells have a chance to grant $75473s1 spell power for $75473d.", ua = "Ваші закляття, що завдають шкоди, мають шанс надати $75473s1 сили заклять на $75473d." },
    { en = "Increases Intellect by $s1 for $d.", ua = "Підвищує інтелект на $s1 на $d." },
    { en = "Chance when taking damage to gain Soulguard, absorbing $274459s1 damage.", ua = "Шанс отримати Вартового душі, коли ви зазнаєте шкоди, що поглинає $274459s1 шкоди." },
    { en = "Your harmful spells have a high chance to resonate with a dark ritual, storing magic within the emblem.", ua = "Ваші шкідливі закляття мають високий шанс резонувати з темним ритуалом, накопичуючи магію в емблемі." },
    { en = "Duration of incoming crowd control effects reduced by $s1%. Does not stack with similar effects.", ua = "Тривалість вхідних ефектів контролю натовпу зменшено на $s1%. Не накопичується з подібними ефектами." },
    { en = "Your attacks have a chance to inflict Volcanic Pressure on the enemy, dealing $s1 Fire damage every $300832t1 sec for $300832d. When Volcanic Pressure reaches $300832u stacks it erupts, dealing $s2 Fire damage to all nearby enemies.", ua = "Ваші атаки мають шанс накласти на ворога Вулканічний Тиск, завдаючи $s1 шкоди вогнем кожні $300832t1 сек протягом $300832d. Коли Вулканічний Тиск досягає $300832u зарядів, він вивергається, завдаючи $s2 шкоди вогнем усім ворогам поблизу." },
    { en = "If you are killed by no more than $s1 damage, the Weave of Warped Fates will unwind your fate, returning yourself to life and healing for ${$s2*(1+$@versadmg)}.\n\n\n\nThis effect can only occur once every $357581d.", ua = "Якщо вас убито шкодою не більшою за $s1, Плетиво Спотворених Доль розплете вашу долю, повертаючи вас до життя та зціляючи на ${$s2*(1+$@versadmg)}.\n\n\n\nЦей ефект може спрацьовувати лише раз на $357581d." },
    { en = "Your spells and abilities have a chance to increase your primary stat by $396047s1 for $396047d and reduce the cooldown of your combat potions by $s1 sec.", ua = "Ваші закляття та здібності мають шанс підвищити вашу основну характеристику на $396047s1 на $396047d і зменшити час перезарядки ваших бойових зілль на $s1 сек." },
    { en = "Restores $o1 mana over $d.", ua = "Відновлює $o1 мани протягом $d." },
    { en = "Your melee attacks have a chance to grant $122689s1 parry for $122689d.", ua = "Ваші атаки ближнього бою мають шанс надати $122689s1 парирування на $122689d." },
    { en = "Grants $s1 Haste for $d.", ua = "Надає $s1 швидкості на $d." },
    { en = "Use: Hurl a Smoldering Inferno at the target that deals between ${$s1*.3}-$s1 Fire damage. Damage dealt is determined by the top-most card of the deck.", ua = "Застосувати: Метнути Тліюче Пекло в ціль, що завдає від ${$s1*.3} до $s1 шкоди вогнем. Завдана шкода визначається верхньою картою колоди." },
    { en = "Charge at an enemy, inflicting $126558s2 Physical damage to enemies within $126558A2 yards and knocking them down for $126558d.", ua = "Налітаєте на ворога, завдаючи $126558s2 фізичної шкоди ворогам у радіусі $126558A2 метрів і збиваючи їх з ніг на $126558d." },
    { en = "Each time your attacks hit, you have a chance to gain $162917s1 critical strike for $162917d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $162917s1 критичного удару на $162917d.  ($h% шанс, ${$proccooldown} сек перезарядки)" },
    { en = "Taking damage has a chance to increase your primary stat by $384598s1 and grant $384598s2 armor to yourself and $384605i closest allies for $384598d.", ua = "Отримання шкоди має шанс підвищити ваш основний показник на $384598s1 та надати $384598s2 броні вам самим і $384605i найближчим союзникам на $384598d." },
    { en = "Infuse your ally with a tuft of phoenix plumes, healing them for ${$344915s1*(1+$@versadmg)} after $d, increased by up to $s2% based on your target's missing health. If your ally suffers lethal damage, this effect triggers instantly.", ua = "Наповнюєте союзника жмутом феніксового пір'я, зціляючи його на ${$344915s1*(1+$@versadmg)} через $d, що збільшується до $s2% залежно від нестачі здоров'я цілі. Якщо ваш союзник зазнає смертельної шкоди, цей ефект спрацьовує миттєво." },
    { en = "Your next $90927u spells cast within $d will grant a bonus of $90927s spell power, stacking up to $90927u times. Lasts $d.", ua = "Ваші наступні $90927u заклять, накладені протягом $d, нададуть бонус $90927s сили заклять, накопичуючись до $90927u разів. Триває $d." },
    { en = "Each time you are struck by a melee attack, you have a $h% chance to gain $71577s1 stamina for the next $71577d, stacking up to $71577u times.", ua = "Щоразу, коли вас уражає атака ближнього бою, ви маєте $h% шанс отримати $71577s1 витривалості на наступні $71577d, накопичуючись до $71577u разів." },
    { en = "Your attacks  have a chance to grant Blades of Renataki, granting $138756s1 Agility every $138756t1 sec for $138756d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати Клинки Ренатакі, що дають $138756s1 спритності кожні $138756t1 сек протягом $138756d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage or heal a target you have a chance to gain $105137s1 spell power for $105137d.", ua = "Коли ви завдаєте шкоди або зціляєте ціль, ви маєте шанс отримати $105137s1 сили заклять на $105137d." },
    { en = "Your healing spells have a chance to grant $126266s1 Intellect for $126266d.", ua = "Ваші закляття зцілення мають шанс надати $126266s1 інтелекту на $126266d." },
    { en = "Take a sip of the drink you swiped from the freight, increasing your Critical Strike by $s1 for $d.", ua = "Зробіть ковток напою, поцупленого з вантажу, що підвищує ваш критичний удар на $s1 на $d." },
    { en = "Gain $u stacks of Platinum Plating for $d, increasing your Armor by $s1. Receiving more than $s2% of your health from a Physical damage effect will remove one stack of Platinum Plating.", ua = "Отримайте $u зарядів Платинового Покриття на $d, що підвищує вашу броню на $s1. Отримання понад $s2% вашого здоров'я від ефекту фізичної шкоди знімає один заряд Платинового Покриття." },
    { en = "Your melee and ranged attacks have a chance to trigger an additional attack for ${$m1+0.3*$AP}-${$M1+0.3*$AP} Physical damage.", ua = "Ваші атаки ближнього та дальнього бою мають шанс активувати додаткову атаку, що завдає від ${$m1+0.3*$AP} до ${$M1+0.3*$AP} фізичної шкоди." },
    { en = "Your abilities have a chance to call the Darkness to you, increasing your $pri by $s1, up to ${$s1*$451369u}.\n\n\n\nUpon reaching full power, the Darkness is unleashed, inflicting ${$<rolemult>*$s2*$451602d/$451602t1} Shadow damage split between nearby enemies over $451602d before fading back into the remnant.", ua = "Ваші здібності мають шанс прикликати до вас Темряву, підвищуючи вашу $pri на $s1, до ${$s1*$451369u}.\n\n\n\nДосягнувши повної сили, Темрява вивільняється, завдаючи ${$<rolemult>*$s2*$451602d/$451602t1} шкоди Тіні, розподіленої між найближчими ворогами протягом $451602d, перш ніж згаснути назад у залишок." },
    { en = "Your healing and damaging spells have a chance to grant $122686s1 haste for $122686d.", ua = "Ваші закляття зцілення та шкоди мають шанс надати вам $122686s1 швидкості на $122686d." },
    { en = "Blow the horn, emboldening you and your party members, increasing Mastery by $s1 split between allies for $d.", ua = "Сурміть у ріг, надихаючи вас і членів вашої групи, що підвищує майстерність на $s1, розподілену між союзниками, на $d." },
    { en = "Your harmful abilities have a chance to cause you to summon Ooker Dooker to fight by your side for $202813d.", ua = "Ваші шкідливі здібності мають шанс прикликати Укера Дукера, щоб той бився поруч із вами впродовж $202813d." },
    { en = "Sip from the vial, gaining ${$268836u1*$268836s1} Strength, which decays over $D.", ua = "Відпийте з флакона, отримавши ${$268836u1*$268836s1} сили, яка згасає протягом $D." },
    { en = "Your damaging abilities have a chance to conjure a Frothing Pustule to fight by your side, dealing ${$s1*5} Nature damage to your target.", ua = "Ваші здібності, що завдають шкоди, мають шанс прикликати Пінисту Пустулу, яка б'ється поруч із вами, завдаючи ${$s1*5} шкоди від природи вашій цілі." },
    { en = "Your healing spells have a chance to cause your next $?a137012[Regrowth]?a137024[Effuse]?a137031[Heal]?a137032[Shadow Mend]?a137029[Holy Light]?a137039[Healing Wave][direct healing spell] to restore $s2 mana instead of costing mana.", ua = "Ваші закляття зцілення мають шанс зробити так, що ваше наступне $?a137012[Відродження]?a137024[Випромінення]?a137031[Зцілення]?a137032[Тіньове цілительство]?a137029[Святе світло]?a137039[Хвиля зцілення][пряме закляття зцілення] відновлює $s2 мани замість того, щоб коштувати мани." },
    { en = "Your melee and ranged attacks have a chance to trigger an additional attack for ${$m1+0.266*$AP}-${$M1+0.266*$AP} physical damage.", ua = "Ваші атаки ближнього й дальнього бою мають шанс спричинити додаткову атаку на ${$m1+0.266*$AP}-${$M1+0.266*$AP} фізичної шкоди." },
    { en = "Calls forth a Vanquished Tentacle of Yogg-Saron to serve you for $64982d.", ua = "Прикликає Подоланого Слизня Йоґг-Сарона, щоб той служив вам упродовж $64982d." },
    { en = "Your attacks have a chance to hone your edge, granting $271105s1 Critical Strike for $271105d.", ua = "Ваші атаки мають шанс загострити ваше лезо, надаючи $271105s1 критичного удару на $271105d." },
    { en = "Your harmful spells and abilities have a chance to strike your target with an abyssal comet, dealing ${$s1*$<rolemult>} Cosmic damage and amplifying their gravity to increase the damage of future comets by $s2%.\n\n\n\nUpon death, enemies implode to deal $s3 Cosmic damage per gravity stack split between nearby enemies. $@spelldesc1240903", ua = "Ваші шкідливі закляття й здібності мають шанс уразити ціль безодньою кометою, завдаючи ${$s1*$<rolemult>} космічної шкоди й посилюючи її тяжіння, що підвищує шкоду наступних комет на $s2%.\n\n\n\nГинучи, вороги вибухають усередину, завдаючи $s3 космічної шкоди за кожен заряд тяжіння, розподіленої між ворогами поруч. $@spelldesc1240903" },
    { en = "Restores $s1 mana and increases the spell power of your next Fire spell by $s2.  Effect lasts for $d.", ua = "Відновлює $s1 мани та підвищує силу заклять вашого наступного заклинання вогню на $s2. Ефект триває $d." },
    { en = "Your critical heals have a chance to instantly heal the most injured nearby party member for $108000s1.", ua = "Ваші критичні зцілення мають шанс миттєво зцілити найтяжче пораненого члена групи поруч на $108000s1." },
    { en = "Your harmful abilities have a chance to cause you to summon a Laughing Skull Berserker to fight by your side for $175739d.", ua = "Ваші шкідливі здібності мають шанс прикликати Берсерка Реготливого Черепа, щоб той бився поруч із вами впродовж $175739d." },
    { en = "Taking damage has a chance to trigger your Reactive Defense Matrix, which reflects the next $s1 damage back at your attacker.\n\n\n\nReactive Defense Matrix triggers automatically when your health drops below $s2% health. This effect cannot occur more than once per $s3 sec.", ua = "Отримання шкоди має шанс активувати вашу Реактивну Захисну Матрицю, яка відбиває наступні $s1 шкоди назад у нападника.\n\n\n\nРеактивна Захисна Матриця активується автоматично, коли ваше здоров'я падає нижче $s2%. Цей ефект не може спрацьовувати частіше, ніж раз на $s3 сек." },
    { en = "Lob void energy at the destination, creating a pool of spite. Enemies within the pool are snared by $315391s1% and have their Corruption increased by $316008s1.\n\n\n\nThe pool applies Lingering Spite every second, increasing the target's corruption by $316008s2. Lingering Spite decays every second the target is outside of the pool.", ua = "Метає енергію Порожнечі в задану точку, створюючи калюжу злостивості. Вороги в межах калюжі сповільнюються на $315391s1%, а їхнє Спотворення зростає на $316008s1.\n\n\n\nКалюжа щосекунди накладає Тривку Злостивість, підвищуючи спотворення цілі на $316008s2. Тривка Злостивість слабшає щосекунди, поки ціль перебуває поза калюжею." },
    { en = "Your attacks have a chance to grant you $138699s1 Agility for $138699d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $138699s1 спритності на $138699d. ($h% шанс, ${$proccooldown} сек. відновлення)" },
    { en = "When you deal damage you have a chance to gain $85032s1 Strength for $85032d.", ua = "Коли ви завдаєте шкоди, є шанс, що ви отримаєте $85032s1 сили на $85032d." },
    { en = "Every $303040t1 seconds, gain an absorb that prevents ${$303036s1*(1+$@versadmg)} $?a303042[Magic][Physical] damage. If the absorb is consumed you gain Fanaticism, causing subsequent absorbs to prevent $303074s1% more damage, up to ${$303074s1*($303074U1-1)}%.", ua = "Кожні $303040t1 секунд ви отримуєте поглинання, що запобігає ${$303036s1*(1+$@versadmg)} $?a303042[магічної][фізичної] шкоди. Якщо поглинання витрачено, ви отримуєте Фанатизм, завдяки чому наступні поглинання запобігають на $303074s1% більше шкоди, до ${$303074s1*($303074U1-1)}%." },
    { en = "Increases spell power by $s2 for $d.", ua = "Підвищує силу заклять на $s2 на $d." },
    { en = "Your melee critical strikes have a chance to draw a drogbar fist out of the ground beneath your target, dealing $407896s1 Physical damage.", ua = "Ваші критичні удари ближнього бою мають шанс висмикнути кулак дроґбара із землі під вашою ціллю, завдаючи $407896s1 фізичної шкоди." },
    { en = "When your attacks hit you have a chance to gain $138938s1 Agility and summon $s1 Voodoo Gnomes for $138938d. (Approximately ${$procrppm}.2 procs per minute)", ua = "Коли ваші атаки влучають, є шанс, що ви отримаєте $138938s1 спритності та прикличете $s1 Вуду-Ґномів на $138938d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your spells have a chance to grant you $278377s1 Critical Strike for $278377d.", ua = "Ваші заклинання мають шанс надати вам $278377s1 критичного удару на $278377d." },
    { en = "Your damaging and healing spells have a chance to pelt your target with magical sands, dealing $s1 Nature damage to an enemy or restoring $s2 health to an ally.", ua = "Ваші заклинання шкоди та зцілення мають шанс осипати вашу ціль магічним піском, завдаючи $s1 шкоди від природи ворогові або відновлюючи $s2 здоров'я союзникові." },
    { en = "Your spell critical strikes have a 50% chance to grant you $40483s1 spell haste for $40483d.", ua = "Ваші критичні удари заклять мають 50% шанс надати вам $40483s1 швидкості заклять на $40483d." },
    { en = "Your attacks have a chance to grant you $148896s1 Agility for $148896d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $148896s1 спритності на $148896d. ($h% шанс, ${$proccooldown} сек. відновлення)" },
    { en = "Cover yourself in four fetid pustules, absorbing $1257925s1 damage for $d. Each time the shield loses $1257925s2% of its value, a pustule erupts, dealing $1257925s3  Plague damage split among nearby enemies.\n\n\n\nIf all pustules erupt, the final burst deals $1257925s4 additional Plague damage.", ua = "Вкриває вас чотирма смердючими пустулами, що поглинають $1257925s1 шкоди впродовж $d. Щоразу, коли щит втрачає $1257925s2% свого значення, пустула вибухає, завдаючи $1257925s3 чумної шкоди, розподіленої між ворогами поблизу.\n\n\n\nЯкщо вибухнуть усі пустули, фінальний вибух завдає $1257925s4 додаткової чумної шкоди." },
    { en = "Your spells and abilities have a chance to grant you $269887s1 Haste for $269887d.", ua = "Ваші заклинання та здібності мають шанс надати вам $269887s1 швидкості на $269887d." },
    { en = "When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by $s1 for $60229d.  Your highest stat is always chosen.", ua = "Коли ви зцілюєте або завдаєте шкоди, є шанс підвищити вашу силу, спритність або інтелект на $s1 на $60229d. Завжди обирається ваша найвища характеристика." },
    { en = "When you deal damage or heal a target you have a chance to gain $92218s1 spell power for $92218d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, є шанс, що ви отримаєте $92218s1 сили заклять на $92218d." },
    { en = "Heal your target for ${$s1*(1+$@versadmg)} plus all healing stored within the mirror.", ua = "Зцілює вашу ціль на ${$s1*(1+$@versadmg)} плюс усе зцілення, накопичене в дзеркалі." },
    { en = "Hungry lumberjacks or peons come to your aid for 10 minutes.", ua = "Голодні лісоруби або пеони приходять вам на допомогу на 10 хвилин." },
    { en = "When you deal damage or heal a target you have a chance to gain $85027s1 spell power for $85027d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, є шанс, що ви отримаєте $85027s1 сили заклять на $85027d." },
    { en = "Your melee and ranged attacks have a chance to grant $118875s1 mastery for $118875d.", ua = "Ваші атаки ближнього й дальнього бою мають шанс надати $118875s1 майстерності на $118875d." },
    { en = "Assume a martial stance based on the last weapon drawn.", ua = "Прибрати бойову стійку залежно від останньої вийнятої зброї." },
    { en = "For the next $d, each time your direct healing spells heal a target you cause the target of your heal to heal themselves and friends within $75494a1 yards for $75494s1 each sec for $75494d.", ua = "Упродовж наступних $d щоразу, коли ваші прямі зцілювальні заклинання зцілюють ціль, ви змушуєте ціль вашого зцілення зцілювати себе та друзів у межах $75494a1 ярдів на $75494s1 щосекунди впродовж $75494d." },
    { en = "Your melee and ranged attacks have a chance to grant $120180s1 mastery for $120180d.", ua = "Ваші атаки ближнього й дальнього бою мають шанс надати $120180s1 майстерності на $120180d." },
    { en = "Launch the superheated gear-a-rang,  inflicting ${$<rolemult>*$446811s1} Flamestrike damage to enemies, losing heat as it cuts through them.", ua = "Запускає перегрітий зубчастий бумеранг, завдаючи ${$<rolemult>*$446811s1} шкоди від Полум'яного Удару ворогам, втрачаючи жар, поки прорізає їх." },
    { en = "Reduce all damage taken by $s2% for $d, up to ${$s1*(1+$@versadmg)} damage prevented. When this effect expires, you suffer $225778s1% increased damage as Fire for $225778d, up to $225778s2 extra damage.", ua = "Зменшує всю отримувану шкоду на $s2% на $d, але не більше ніж ${$s1*(1+$@versadmg)} відверненої шкоди. Коли цей ефект спливає, ви зазнаєте $225778s1% збільшеної шкоди вогнем упродовж $225778d, але не більше ніж $225778s2 додаткової шкоди." },
    { en = "Form a Huntsman's Bond with a target ally for $d. $s1% of damage you suffer will be redirected to your bonded ally, up to ${$344400s1*(1+$@versadmg)} total damage redirected.", ua = "Утворює Узи Мисливця із цільовим союзником на $d. $s1% шкоди, якої ви зазнаєте, перенаправляється на вашого пов'язаного союзника, але не більше ніж ${$344400s1*(1+$@versadmg)} перенаправленої шкоди загалом." },
    { en = "Your attacks have a chance to grant $176984s1 Haste for $176984d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176984s1 швидкості на $176984d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage you have a chance to gain $109774s1 mastery for $109774d.", ua = "Коли ви завдаєте шкоди, є шанс, що ви отримаєте $109774s1 майстерності на $109774d." },
    { en = "Unleash a wave that crashes into your target then returns to your original location, inflicting ${$302579s1*(1+$302580d)*(1+$@versadmg)} Frost damage over $302580d to enemies in its path. Catch the wave to reduce the cooldown of this ability by $302579s2 sec.", ua = "Випускає хвилю, що накочується на вашу ціль і повертається до вашого початкового місця, завдаючи ${$302579s1*(1+$302580d)*(1+$@versadmg)} шкоди від холоду протягом $302580d ворогам на її шляху. Спіймайте хвилю, щоб зменшити час відновлення цієї здібності на $302579s2 сек." },
    { en = "Your next $n healing spells restore $271058s1 mana.", ua = "Ваші наступні $n заклять зцілення відновлюють $271058s1 мани." },
    { en = "Increase your Versatility by $s1 every $t2 sec. Lasts $d.", ua = "Підвищує вашу універсальність на $s1 кожні $t2 сек. Триває $d." },
    { en = "Your damaging spells have a chance to conjure $s3 Shadow Blades. After $253264d, the swords begin launching forward, each dealing $257702s1 Shadow damage to the first enemy in their path and increasing damage taken from your subsequent Shadow Blades by $253265s2% for $253265d, up to ${$253265s2*$253265u}%.", ua = "Ваші шкідливі закляття мають шанс прикликати $s3 Тіньових Клинків. За $253264d мечі починають летіти вперед, кожен завдаючи $257702s1 шкоди від тіні першому ворогові на своєму шляху та підвищуючи шкоду, отриману від ваших наступних Тіньових Клинків, на $253265s2% на $253265d, до ${$253265s2*$253265u}%." },
    { en = "Unleash a bolt of Anguish at your target, inflicting ${$<rolemult>*$1272690s1} Shadow damage. Residual Anguish energy surrounds you for a time, granting $1272690s2 Leech for $1272698d.", ua = "Випускає у вашу ціль розряд Муки, завдаючи ${$<rolemult>*$1272690s1} шкоди від тіні. Залишкова енергія Муки оточує вас деякий час, надаючи $1272690s2 висмоктування на $1272698d." },
    { en = "Increases the damage dealt by your Lightning Shield spell by $s1 for $d.", ua = "Підвищує шкоду, завдану вашим заклятям Блискавичний Щит, на $s1 на $d." },
    { en = "Increase your Armor by $251941s1 for $251940d, and inflict $s1 Frost damage to enemies within $A1 yds and reduce their movement speed by $s2% for $d.", ua = "Підвищує вашу броню на $251941s1 на $251940d, завдає $s1 шкоди від холоду ворогам у радіусі $A1 м. та зменшує їхню швидкість пересування на $s2% на $d." },
    { en = "Your harmful spells and abilities have a chance to grant you $s1 Critical Strike, Mastery, or Haste for $392248d depending on how many pets you control.", ua = "Ваші шкідливі закляття та здібності мають шанс надати вам $s1 критичного удару, майстерності або швидкості на $392248d залежно від того, скількома улюбленцями ви керуєте." },
    { en = "Embrace N'Zoth's gift, increasing your Mastery by $295508s1 for $295408d. Every $295408t2 sec gain Suffering, inflicting $295513s1 Shadow damage per application.", ua = "Прийміть дар Н'Зота, підвищивши вашу майстерність на $295508s1 на $295408d. Кожні $295408t2 сек. ви отримуєте Страждання, що завдає $295513s1 шкоди від тіні за кожне накладання." },
    { en = "Create a magical feast for $d. Up to $s1 allies who partake in the feast absorb $225723s1 damage for $225723d.", ua = "Створює магічний бенкет на $d. До $s1 союзників, які беруть участь у бенкеті, поглинають $225723s1 шкоди протягом $225723d." },
    { en = "Taking damage as well dealing harmful spells and abilities has a chance to grant you a $s1 absorb shield that regenerates after being broken up to $s2 additional times.", ua = "Отримання шкоди, а також застосування шкідливих заклять і здібностей мають шанс надати вам щит, що поглинає $s1 шкоди та відновлюється після руйнування ще до $s2 разів." },
    { en = "You are embraced by the Light, increasing Mastery by $s2.\n\n\n\nYour damaging spells and abilities can call a beam of radiant light nearby. Standing in the light blesses you with $s3 Mastery while you stand in it.", ua = "Вас огортає Світло, підвищуючи майстерність на $s2.\n\n\n\nВаші шкідливі закляття та здібності можуть прикликати поблизу промінь сяйливого світла. Стоячи у світлі, ви благословенні $s3 майстерності, доки в ньому перебуваєте." },
    { en = "Your melee autoattacks grant you Chaotic Energy, increasing your Strength or Agility by $214831s3, stacking up to $214831u times.\n\n\n\nIf you do not autoattack an enemy for 4 sec, this effect will decrease by 1 stack every sec.", ua = "Ваші автоатаки ближнього бою надають вам Хаотичну Енергію, що підвищує вашу силу або спритність на $214831s3, накопичуючись до $214831u разів.\n\n\n\nЯкщо ви не атакуєте ворога автоатакою протягом 4 сек., цей ефект зменшуватиметься на 1 стак щосекунди." },
    { en = "When you deal damage you have a chance to gain $102432s1 Strength for $102432d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $102432s1 сили на $102432d." },
    { en = "Accumulate dark power from the Spellforge every $452030t2 sec to empower your next $?a137013[$@spellname78674][]$?a137012[$@spellname5176][]$?a396186[$@spellname395160][]$?a356809[$@spellname356995][]$?a356810[$@spellname361469][]$?a137019[$@spellname108853][]$?a137021[$@spellname44425][]$?a137020[$@spellname30455][]$?a137024[$@spellname107428][]$?a137031[$@spellname14914][]$?a137032[$@spellname585][]$?a137033[$@spellname8092][]$?a137040[$@spellname51505][]$?a137039[$@spellname51505][]$?a137046[$@spellname116858][]$?a137043[$@spellname324536][]$?a137044[$@spellname264178][]$?a137029[$@spellname20271][]$?a137047|$?a137034|$?a137023|$?a137025|$?a137014|$?a212611|$?a137005|$?a137010|$?a137011[specialization spell][] to deal ${$<rolemult>*$s1} additional Shadow damage.", ua = "Накопичує темну силу з Закляттєкузні кожні $452030t2 с, щоб підсилити ваше наступне $?a137013[$@spellname78674][]$?a137012[$@spellname5176][]$?a396186[$@spellname395160][]$?a356809[$@spellname356995][]$?a356810[$@spellname361469][]$?a137019[$@spellname108853][]$?a137021[$@spellname44425][]$?a137020[$@spellname30455][]$?a137024[$@spellname107428][]$?a137031[$@spellname14914][]$?a137032[$@spellname585][]$?a137033[$@spellname8092][]$?a137040[$@spellname51505][]$?a137039[$@spellname51505][]$?a137046[$@spellname116858][]$?a137043[$@spellname324536][]$?a137044[$@spellname264178][]$?a137029[$@spellname20271][]$?a137047|$?a137034|$?a137023|$?a137025|$?a137014|$?a212611|$?a137005|$?a137010|$?a137011[закляття вашої спеціалізації][] так, щоб воно завдавало додатково ${$<rolemult>*$s1} шкоди Тінню." },
    { en = "Your melee and ranged attacks have a chance to grant $118608s1 haste for $118608d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс надати $118608s1 швидкості на $118608d." },
    { en = "Increase your Mastery by $s1 for $d.", ua = "Підвищує вашу майстерність на $s1 на $d." },
    { en = "Release the stored heat within, dealing $s1 Fire damage split between enemies in front of you.", ua = "Вивільняє накопичений усередині жар, завдаючи $s1 шкоди від вогню, розподіленої між ворогами перед вами." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $92233s1 mastery for $92233d.   Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $92233s1 майстерності на $92233d. Не може спрацьовувати частіше ніж раз на 30 сек." },
    { en = "Grants you $346746s1 Versatility for $d.", ua = "Надає вам $346746s1 універсальності на $d." },
    { en = "You gain an Electrical Charge each time you cause a damaging spell critical strike, granting a chance to fire a Lightning Bolt for ${$m1*0.875} to ${$m1*1.125} damage per Electrical Charge accumulated.  You cannot have more than $96890u Electrical Charges and cannot gain one more often than once every 2.5 sec.", ua = "Ви отримуєте Електричний Заряд щоразу, коли завдаєте критичного удару шкідливим заклятям, що дає шанс випустити Блискавку, яка завдає від ${$m1*0.875} до ${$m1*1.125} шкоди за кожен накопичений Електричний Заряд. Ви не можете мати більше ніж $96890u Електричних Зарядів і не можете отримувати їх частіше ніж раз на 2.5 сек." },
    { en = "Chance on spell hit to restore $33523s1 mana to the bearer.", ua = "Шанс при влучанні заклятям відновити носієві $33523s1 мани." },
    { en = "Each time you deal spell damage to an opponent, you gain $71570s1 spell power for the next $71570d, stacking up to $71570u times.", ua = "Щоразу, коли ви завдаєте супротивникові шкоди заклятям, ви отримуєте $71570s1 сили заклять на наступні $71570d, накопичуючись до $71570u разів." },
    { en = "Brandish the Voodoo Doll at your target, dealing $271465o1 Shadow damage over $271465d, and an additional $271468s1 Shadow damage after $271465d.", ua = "Махає Вуду-Лялькою в напрямку вашої цілі, завдаючи $271465o1 шкоди від тіні протягом $271465d, а також додатково $271468s1 шкоди від тіні за $271465d." },
    { en = "Your damaging spells have a chance to summon a void tendril near your target's location, dealing ${$250834s1*$<rolemult>} Shadow damage to all enemies within $250834A1 yds after a brief delay.", ua = "Ваші шкідливі закляття мають шанс прикликати щупальце Порожнечі поблизу місця вашої цілі, що після короткої затримки завдає ${$250834s1*$<rolemult>} шкоди від тіні всім ворогам у радіусі $250834A1 м." },
    { en = "Summons an Argent Knight to your side.", ua = "Прикликає до вас Срібного Лицаря." },
    { en = "Teleports you forward 20 yds or until reaching an obstacle, and frees you from all stuns and bonds.", ua = "Телепортує вас на 20 м. уперед або до зіткнення з перешкодою та звільняє вас від усіх оглушень і пут." },
    { en = "Your spells and abilities have a chance to grant $s1 Versatility per Malygite you have equipped. Upon reaching $M2 stacks, all stacks are consumed and you gain $s3 secondary stats, split evenly for $376643d.", ua = "Ваші закляття та здібності мають шанс надати $s1 універсальності за кожен споряджений Малігіт. Досягнувши $M2 стаків, усі стаки поглинаються, і ви отримуєте $s3 вторинних характеристик, розподілених рівномірно, на $376643d." },
    { en = "Gain the Tidehunter's blessing, increasing your Strength by $s1 for $d1.", ua = "Отримайте благословення Ловця Припливів, що підвищує вашу силу на $s1 на $d1." },
    { en = "???", ua = "???" },
    { en = "Recaptures $s1% of the base mana cost of your spells, and stores it within the doll to be released at a later time.  Up to a maximum of $s2 mana can be stored.", ua = "Відновлює $s1% базової вартості мани ваших заклять і зберігає її в ляльці, щоб вивільнити згодом. Може зберігатися щонайбільше $s2 мани." },
    { en = "Activates your Mechanical Dragonling to fight for you for $d.", ua = "Активує вашого Механічного Дракончика, що б'ється за вас протягом $d." },
    { en = "The next opponent killed within $d that yields experience or honor will restore $33015s1 health.", ua = "Наступний убитий протягом $d супротивник, що дає досвід або честь, відновить $33015s1 здоров'я." },
    { en = "Echo the sound of your drum through a sacred loa temple, aligning its beat with the will of the loa.", ua = "Розноситься звук вашого барабана крізь священний храм лоа, узгоджуючи його ритм із волею лоа." },
    { en = "Chance on spell hit to restore $33513s1 mana to the bearer.", ua = "Шанс при влучанні заклятям відновити носієві $33513s1 мани." },
    { en = "Four dance partners appear in a random pattern around you. Moving to each grants you $345431s1 Haste and $345431s2 Speed for $345439d, stacking.", ua = "Навколо вас у випадковому порядку з'являються четверо партнерів по танцю. Підхід до кожного надає вам $345431s1 швидкості та $345431s2 прудкості на $345439d, накопичуючись." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain a protective shield which absorbs $96945s1 damage for $96945d.  Cannot occur more than once every 1 min.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам захисний щит, який поглинає $96945s1 шкоди на $96945d. Не може спрацьовувати частіше, ніж раз на 1 хв." },
    { en = "Your damaging spells and abilities have the chance to embolden you in Void Glass granting $s1 Versatility over $1244617d. Multiple applications can overlap.\n\n\n\nThis effect is augmented by Darkmoon Sigil: Void.", ua = "Ваші шкідливі закляття та здібності мають шанс наснажити вас Порожнечним Склом, надаючи $s1 універсальності на $1244617d. Кілька застосувань можуть накладатися.\n\n\n\nЦей ефект посилюється Сигілом Похмуромісяччя: Порожнеча." },
    { en = "Your healing spells have a chance to grant the target Nightwell Tranquility, restoring $225724o1 health over $225724d. Healing an ally affected by Nightwell Tranquility can cause the effect to detonate, healing nearby allies for $225725s1.", ua = "Ваші зцілювальні закляття мають шанс надати цілі Спокій Нічного Джерела, відновлюючи $225724o1 здоров'я протягом $225724d. Зцілення союзника, ураженого Спокоєм Нічного Джерела, може спричинити детонацію ефекту, зціливши сусідніх союзників на $225725s1." },
    { en = "A small breeze follows you around, periodically healing or shielding you or your allies for $s1.", ua = "Легкий вітерець супроводжує вас, періодично зцілюючи або захищаючи вас чи ваших союзників на $s1." },
    { en = "Your healing spells have a chance to grant an ally an absorption shield that absorbs up to $300806s1 damage for $300806d. While the shield is active, the targets Primary Stat is increased by $300806s2.", ua = "Ваші зцілювальні закляття мають шанс надати союзнику поглинальний щит, який поглинає до $300806s1 шкоди протягом $300806d. Поки щит активний, основна характеристика цілі підвищена на $300806s2." },
    { en = "Increase your Versatility by ${$s1*$u} for $d. After ${$t2*6} sec, the effect decreases by $s1 every sec.", ua = "Підвищує вашу універсальність на ${$s1*$u} на $d. Через ${$t2*6} с ефект зменшується на $s1 щосекунди." },
    { en = "Suspend the Egg's incubation state for $d.", ua = "Призупиняє стан інкубації Яйця на $d." },
    { en = "Increases maximum health by $s1 for $d. Shares cooldown with Battlemaster's trinkets.", ua = "Підвищує максимальне здоров'я на $s1 на $d. Має спільний час відновлення з брязкальцями Бойового Майстра." },
    { en = "$?pc91397[Gain the benefit of your $@spellname333372]?pc91400[Reset the cooldown of your $@spellname300728]?pc91398[Channel your $@spellname324631, gaining its benefits]?pc91399[Reset the cooldown of your $@spellname310143][Gain the power of your Covenant Signature ability] and gain $s1 Versatility for $d.", ua = "$?pc91397[Надає переваги вашої здатності $@spellname333372]?pc91400[Скидає час відновлення вашої здатності $@spellname300728]?pc91398[Підтримує вашу здатність $@spellname324631, надаючи її переваги]?pc91399[Скидає час відновлення вашої здатності $@spellname310143][Надає силу фірмової здатності вашого Ковенанту] та надає $s1 універсальності протягом $d." },
    { en = "Increases your Critical Strike by $s1 for $d.", ua = "Підвищує вашу швидкість критичного удару на $s1 на $d." },
    { en = "Your attacks and beneficial spells have a chance to grant $177060s1 Versatility for $177060d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки та сприятливі закляття мають шанс надати $177060s1 універсальності на $177060d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your healing spell and abilities have a very high chance to summon a Twisted Mana Sprite to assist you in combat for $1247081d1. Twisted Mana Sprite periodically heal a random nearby ally for ${$s1*$<healingrolemult>}. Overhealing is converted into an absorb shield for $1247511d.", ua = "Ваші зцілювальні закляття та здібності мають дуже високий шанс прикликати Скривленого Мана-Духа, щоб допомагати вам у бою протягом $1247081d1. Скривлений Мана-Дух періодично зцілює випадкового сусіднього союзника на ${$s1*$<healingrolemult>}. Надлишкове зцілення перетворюється на поглинальний щит протягом $1247511d." },
    { en = "Your harmful abilities and spells have a chance to summon Gruffy. When summoned, Gruffy will charge your target from a random direction dealing $s1 physical damage to any enemy he passes through, while knocking them back a short distance.", ua = "Ваші шкідливі здібності та закляття мають шанс прикликати Грубчика. Прикликаний Грубчик кидається на вашу ціль із випадкового напрямку, завдаючи $s1 фізичної шкоди кожному ворогу, крізь якого проходить, і відкидаючи їх на коротку відстань." },
    { en = "Hold out the feather for $?${$s2%10}>0[${$s2/10}.1][${$s2/10}] sec to strike with the power of the storm, crashing down on the target location and inflicting ${$<rolemult>*$s1} Nature damage split between nearby enemies.", ua = "Тримайте перо $?${$s2%10}>0[${$s2/10}.1][${$s2/10}] с, щоб вдарити силою шторму, який обрушується на цільову місцевість і завдає ${$<rolemult>*$s1} шкоди силами природи, розподіленої між ворогами поблизу." },
    { en = "Each time your spells heal a target you have a chance to cause another nearby friendly target to be instantly healed for $71610s1.", ua = "Щоразу, коли ваші закляття зцілюють ціль, ви маєте шанс миттєво зцілити іншу сусідню дружню ціль на $71610s1." },
    { en = "Your spells have a chance to empower the Voidcore, granting you $s1 Intellect for $1239221d. This chance is increased by $s3% while below $s2% mana. Multiple applications may overlap.", ua = "Ваші закляття мають шанс наснажити Порожнечне Ядро, надаючи вам $s1 інтелекту на $1239221d. Цей шанс підвищується на $s3%, доки у вас менше $s2% мани. Кілька застосувань можуть накладатися." },
    { en = "Proclaim your allegiance to the Stone Legion, increasing your Versatility by $s1, increased by $s2% for each Stone Legionnaire in your party.", ua = "Проголошує вашу відданість Кам'яному Легіону, підвищуючи вашу універсальність на $s1, збільшену на $s2% за кожного Кам'яного Легіонера у вашій групі." },
    { en = "Manifest void breaches above nearby party members to heal them and yourself for $s1 split between all targets.", ua = "Породжує розломи Порожнечі над сусідніми членами групи, зціливши їх і вас на $s1, розподілені між усіма цілями." },
    { en = "Your damaging abilities have a very low chance to manifest a drust behemoth, smashing your target and dealing $s2 Physical damage to all nearby enemies.", ua = "Ваші шкідливі здібності мають дуже низький шанс породити друстського бегемота, який трощить вашу ціль і завдає $s2 фізичної шкоди всім сусіднім ворогам." },
    { en = "Increases your Agility by $s1 for $d1.", ua = "Підвищує вашу спритність на $s1 на $d1." },
    { en = "Detonate all Fire Mines.", ua = "Підриває всі Вогняні Міни." },
    { en = "Increase your Critical Strike by $s1 for $d.", ua = "Підвищує вашу швидкість критичного удару на $s1 на $d." },
    { en = "When you deal damage or heal a target you have a chance to gain $99742s1 spell power for $99742d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, ви маєте шанс отримати $99742s1 сили заклять на $99742d." },
    { en = "Your damaging spells and abilities have the chance to ignite your target with Radiant Focus for $454560d. \n\n\n\nAfter dealing up to $454560s1 damage to the target, the focused energies ignite you with Radiance, granting between ${$s1*.5} to $s1 of your highest secondary stat based on damage dealt for $454560d.", ua = "Ваші шкідливі закляття та здібності мають шанс підпалити вашу ціль Осяйним Зосередженням на $454560d.\n\n\n\nПісля завдання цілі до $454560s1 шкоди зосереджена енергія підпалює вас Сяйвом, надаючи від ${$s1*.5} до $s1 вашої найвищої вторинної характеристики залежно від завданої шкоди на $454560d." },
    { en = "Each time your Shadow Word: Pain deals damage, it has a $h% chance to grant you $40441s1 spell power for $40441d and each time your Renew heals, it has a $h% chance to grant you $40440s1 spell power for $40440d.", ua = "Щоразу, коли ваше Слово Тіні: Біль завдає шкоди, воно має $h% шанс надати вам $40441s1 сили заклять на $40441d, а щоразу, коли ваше Оновлення зцілює, воно має $h% шанс надати вам $40440s1 сили заклять на $40440d." },
    { en = "Your healing and damage periodic spells grant $90985s1 Intellect each time they heal or deal damage. Lasts $90985d, stacking up to $90985u times.", ua = "Ваші зцілювальні та шкідливі періодичні закляття надають $90985s1 інтелекту щоразу, коли зцілюють або завдають шкоди. Триває $90985d, накопичується до $90985u разів." },
    { en = "Your damaging spells and abilities have a chance to throw an exploding banana at your target, dealing damage split between all nearby enemies.", ua = "Ваші шкідливі закляття та здібності мають шанс кинути у вашу ціль вибухову банану, завдаючи шкоди, розподіленої між усіма сусідніми ворогами." },
    { en = "Increases your critical strike by $s1 for $d.", ua = "Підвищує вашу швидкість критичного удару на $s1 на $d." },
    { en = "Your damaging spells have a chance to fire a beam of blacklight in the target's direction, dealing $s1 Shadow damage to all targets that it passes through.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші шкідливі закляття мають шанс випустити промінь чорного світла в напрямку цілі, завдаючи $s1 шкоди Тінню всім цілям, крізь які він проходить. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a high chance to deal $s1 Frost damage and apply Frozen Heart to the enemy.", ua = "Ваші атаки мають високий шанс завдати $s1 шкоди Морозом і накласти на ворога Заморожене Серце." },
    { en = "Healing an ally below $s4% health grants them Blossom of Amirdrassil, healing for ${$s1*$426678d} over $426678d. This effect may occur once per minute. \n\n\n\nIf the target is above $s5% health when this effect expires, the Blossom spreads to 3 injured allies to heal for ${$s3*$426718d} over $426718d. If the target is not fully healed, the Blossom blooms to absorb $s2 damage instead.", ua = "Зцілення союзника зі здоров'ям нижче $s4% надає йому Цвіт Амірдрассілу, зціливши на ${$s1*$426678d} протягом $426678d. Цей ефект може спрацьовувати раз на хвилину.\n\n\n\nЯкщо при завершенні ефекту здоров'я цілі вище $s5%, Цвіт поширюється на 3 поранених союзників, зціливши на ${$s3*$426718d} протягом $426718d. Якщо ціль не зцілена повністю, Цвіт натомість розквітає, щоб поглинути $s2 шкоди." },
    { en = "When you deal damage you have a chance to gain $182062s1 Strength for $182062d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $182062s1 сили на $182062d." },
    { en = "Your melee and ranged attacks grant $92089s1 Agility.  Lasts $92089d, stacking up to $92089u times.", ua = "Ваші атаки ближнього та дальнього бою надають $92089s1 спритності. Триває $92089d, накопичується до $92089u разів." },
    { en = "Reduce the remaining cooldown of $?a137012[your Swiftmend by ${$357919s1*$357919s2/100}.1]?a137024[your Renewing Mist by ${$357919s1*$357919s3/100}.1]?a137029[your Holy Shock by ${$357919s1*$357919s4/100}.1]?a137032[your Penance by ${$357919s1*$357919s5/100}.1]?a137031[your Circle of Healing by ${$357919s1*$357919s6/100}.1]?a137039[your Riptide by ${$357919s1*$357919s7/100}.1][an appropriate healing spell by $357919s1] sec. $?(a137012|a137024|a137031|a137032|a137029|a137039)[][\n\n\n\n|CFF808080Valid only for healer specializations.|R]", ua = "Зменшує залишковий час відновлення $?a137012[вашого Швидкозцілення на ${$357919s1*$357919s2/100}.1]?a137024[вашого Оновлювального Туману на ${$357919s1*$357919s3/100}.1]?a137029[вашого Святого Шоку на ${$357919s1*$357919s4/100}.1]?a137032[вашого Покаяння на ${$357919s1*$357919s5/100}.1]?a137031[вашого Кола Зцілення на ${$357919s1*$357919s6/100}.1]?a137039[вашого Відпливу на ${$357919s1*$357919s7/100}.1][відповідного зціляючого закляття на $357919s1] сек. $?(a137012|a137024|a137031|a137032|a137029|a137039)[][\n\n\n\n|CFF808080Дійсне лише для зціляючих спеціалізацій.|R]" },
    { en = "Your melee attacks have a chance to trigger a whirlwind attack dealing $107997s1 physical damage to all targets within $107997A1 yards.", ua = "Ваші атаки ближнього бою мають шанс спричинити вихорову атаку, що завдає $107997s1 фізичної шкоди всім цілям у межах $107997A1 м." },
    { en = "Your melee and ranged attacks have a chance to increase your Agility or Strength by $64790s2 for $64790d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс підвищити вашу спритність або силу на $64790s2 на $64790d." },
    { en = "Increases your Critical Strike by ${$71564m1*$71564u} for $71564d. Every time one of your non-periodic spells deals a critical strike, the bonus is reduced by $71564s1.", ua = "Підвищує вашу швидкість критичного удару на ${$71564m1*$71564u} на $71564d. Щоразу, коли одне з ваших неперіодичних заклять завдає критичного удару, бонус зменшується на $71564s1." },
    { en = "Channel a Bulwark of Flame that absorbs $s1 damage for $d. When the Bulwark expires you unleash $s2 Waves of Flame, dealing $251948s1 Fire damage to all enemies in their path.\n\n\n\nYou cannot move or use abilities during Bulwark of Flame.", ua = "Підтримує Заслін Полум'я, який поглинає $s1 шкоди протягом $d. Коли Заслін завершується, ви випускаєте $s2 Хвиль Полум'я, що завдають $251948s1 шкоди Вогнем усім ворогам на їхньому шляху.\n\n\n\nПід час Засліну Полум'я ви не можете рухатися чи використовувати здібності." },
    { en = "Your melee attacks have a chance to grant $116723s1 parry for $116723d.", ua = "Ваші ближні атаки мають шанс надати $116723s1 парирування на $116723d." },
    { en = "When your attacks hit you have a chance to gain $146312s1 Mastery for $146312d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $146312s1 майстерності на $146312d. ($h% шанс, перезарядка ${$proccooldown} сек)" },
    { en = "Absorbs $s1 physical damage.  Lasts $d.", ua = "Поглинає $s1 фізичної шкоди. Триває $d." },
    { en = "Your damaging and healing spells have a chance to increase your Critical Strike by $355044s1.", ua = "Ваші заклинання шкоди та зцілення мають шанс підвищити вашу швидкість критичного удару на $355044s1." },
    { en = "Your attacks have a chance to cause flaming tentacles to grow from your body for $381727d. The tentacles lash out, dealing $s1 Fire damage every $s3 sec split between enemies in front of you.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші атаки мають шанс зростити з вашого тіла полум'яні мацаки на $381727d. Мацаки шмагають навсібіч, завдаючи $s1 шкоди вогнем кожні $s3 сек, розподіленої між ворогами перед вами.\n\n\n\nШкода збільшується за кожного враженого ворога, до $s2 ворогів." },
    { en = "Affix a Domination Rune to yourself, gaining power at a price.", ua = "Закріплює на вас Руну Панування, даруючи могутність за певну ціну." },
    { en = "Chance on parrying an attack to gain $52424s Strength for $52424d.", ua = "Шанс під час парирування атаки отримати $52424s сили на $52424d." },
    { en = "Your spells have a chance to increase your Haste by $202886s1 for $202886d.", ua = "Ваші заклинання мають шанс підвищити вашу швидкість на $202886s1 на $202886d." },
    { en = "Increases maximum health by $1256126s1 for $d, up to twice your original maximum. Shares cooldown with Battlemaster's trinkets.", ua = "Підвищує максимальне здоров'я на $1256126s1 на $d, до подвоєння вашого первісного максимуму. Має спільну перезарядку з брелоками Бойового Майстра." },
    { en = "Your melee and ranged attacks have a chance to grant $122921s1 haste for $122921d.", ua = "Ваші ближні та дальні атаки мають шанс надати $122921s1 швидкості на $122921d." },
    { en = "Your damaging spells have a chance to pull a nightmare star from the sky, creating a pool of corruption that deals ${10*$213786s1} Shadow damage to all enemies in the area over $213785d.", ua = "Ваші заклинання шкоди мають шанс стягнути з неба зорю кошмару, створюючи калюжу скверни, що завдає ${10*$213786s1} шкоди Тінню всім ворогам у цій зоні протягом $213785d." },
    { en = "Increases armor by $s1 for $d.", ua = "Підвищує броню на $s1 на $d." },
    { en = "Your healing spells have a chance to awaken the Heart, restoring ${$s3*($409898d/($409898t3))} mana over $409898d and causing your healing spells to restore ${$s1*($401186d/($401186t2))} additional health over $401186d.\n\n\n\nOverhealing from this effect invigorates your target, granting them up to $401183s2 Versatility for $401187d.", ua = "Ваші заклинання зцілення мають шанс пробудити Серце, відновлюючи ${$s3*($409898d/($409898t3))} мани протягом $409898d і змушуючи ваші заклинання зцілення відновлювати додаткові ${$s1*($401186d/($401186t2))} здоров'я протягом $401186d.\n\n\n\nНадлишкове зцілення від цього ефекту наснажує вашу ціль, даруючи їй до $401183s2 універсальності на $401187d." },
    { en = "Increases armor by $s1 for $d. Only usable in Pandaria.", ua = "Підвищує броню на $s1 на $d. Можна використати лише в Пандарії." },
    { en = "Your healing and damaging spells have a chance to grant $122691s1 critical strike for $122691d.", ua = "Ваші заклинання зцілення та шкоди мають шанс надати $122691s1 критичного удару на $122691d." },
    { en = "Call upon a spectral owl to attack your target, inflicting $242571s1 Arcane damage every $t2 sec for $d. Your ranged attacks and spells against the same enemy have a chance to make the owl perform an additional attack for $246442s1 damage.", ua = "Прикликає примарну сову, що атакує вашу ціль, завдаючи $242571s1 шкоди Тайнощами кожні $t2 сек протягом $d. Ваші дальні атаки та заклинання проти того самого ворога мають шанс змусити сову завдати додаткової атаки на $246442s1 шкоди." },
    { en = "Increases your maximum health by $s1, and your Armor by $s2. Lasts $d.", ua = "Підвищує ваше максимальне здоров'я на $s1, а вашу броню на $s2. Триває $d." },
    { en = "Cast your watchful eye over your target, granting a high chance to heal them for $382183s1 when they receive any healing over the next $382161d.", ua = "Накладає на вашу ціль пильне око, даючи високий шанс зцілити її на $382183s1, коли вона отримає будь-яке зцілення протягом наступних $382161d." },
    { en = "Your damaging abilities have a chance to deal an additional $273936s1 Nature damage.", ua = "Ваші здібності шкоди мають шанс завдати додаткові $273936s1 шкоди Природою." },
    { en = "Your attacks have a chance to summon an intangible presence to haunt your target, reducing their auto attack damage against you by up to $s2 per strike for $230088d.", ua = "Ваші атаки мають шанс прикликати безтілесну присутність, що переслідує вашу ціль, зменшуючи шкоду її автоатак проти вас до $s2 за удар протягом $230088d." },
    { en = "Increases your Mastery by $s1 for $d.", ua = "Підвищує вашу майстерність на $s1 на $d." },
    { en = "Feed the Coagulum, redirecting $444271s4% of all healing done until ${$444271s1*$444271s3/100} healing has been consumed. Once sated, the Coagulum bursts to heal $444271s5 allies for ${($444271s1+($444271s1*$444271s3*.01*(1+$444271s6*.01)))/$444271s5}.\n\n\n\nLingering effluvia causes affected allies' next attacks to deal an additional $444271s2 Shadow damage, increased based on overhealing done by the Coagulum.", ua = "Живить Коагулюм, перенаправляючи $444271s4% усього завданого зцілення, доки не буде спожито ${$444271s1*$444271s3/100} зцілення. Наситившись, Коагулюм вибухає, зцілюючи $444271s5 союзників на ${($444271s1+($444271s1*$444271s3*.01*(1+$444271s6*.01)))/$444271s5}.\n\n\n\nЗалишкові випари змушують наступні атаки уражених союзників завдавати додаткові $444271s2 шкоди Тінню, збільшені залежно від надлишкового зцілення Коагулюму." },
    { en = "Grants $s1 mana, but consumes all applications of Inner Eye and prevents Inner Eye from being triggered for $d.", ua = "Надає $s1 мани, але споживає всі застосування Внутрішнього Ока та запобігає спрацюванню Внутрішнього Ока на $d." },
    { en = "Your spells have a chance to inspire you to experiment on an ally, enhancing them in unforeseen ways for $452288d.", ua = "Ваші заклинання мають шанс надихнути вас на експеримент над союзником, посилюючи його непередбачуваним чином на $452288d." },
    { en = "Increased speed by $s1% and prevents new snares from landing on the user for $d.", ua = "Підвищує швидкість на $s1% і запобігає накладанню нових пасток на користувача протягом $d." },
    { en = "Every $t1 sec, gain an absorb shield for $<absorb>, up to a maximum absorb of ${$<absorb>*$s2}.", ua = "Кожні $t1 сек ви отримуєте поглинальний щит на $<absorb>, до максимального поглинання ${$<absorb>*$s2}." },
    { en = "Your melee and ranged attacks have a chance to grant $92069s1 Agility for $92069d.", ua = "Ваші ближні та дальні атаки мають шанс надати $92069s1 спритності на $92069d." },
    { en = "Your healing spells have a chance to conjure a sanguine pool near your location, containing $s2 healing. While standing within the pool, your healing spells restore $s3 additional health, until the pool is depleted.", ua = "Ваші заклинання зцілення мають шанс прикликати поблизу вашого місця криваву калюжу, що містить $s2 зцілення. Доки ви стоїте в калюжі, ваші заклинання зцілення відновлюють додаткові $s3 здоров'я, доки калюжа не вичерпається." },
    { en = "When you heal or deal damage you have a chance to gain Greatness, increasing your Strength, Agility, or Intellect by $60229s1 for $60229d.  Your highest stat is always chosen.", ua = "Коли ви зцілюєте чи завдаєте шкоди, ви маєте шанс отримати Велич, що підвищує вашу силу, спритність або інтелект на $60229s1 на $60229d. Завжди обирається ваша найвища характеристика." },
    { en = "Your damaging abilities have a chance to deal an additional $378735s1 Nature damage.", ua = "Ваші здібності шкоди мають шанс завдати додаткові $378735s1 шкоди Природою." },
    { en = "While out of combat, invoke the Plume's dual nature to transform it into an Umbral Plume.", ua = "Поза боєм ви можете прикликати подвійну природу Пера, щоб перетворити його на Сутінкове Перо." },
    { en = "Casting Healing Surge, Chain Heal, or Healing Wave on a target with your Riptide on it has a $s1% chance to spread that Riptide to another nearby ally.", ua = "Застосування Хвилі Зцілення, Ланцюгового Зцілення або Цілющої Хвилі на ціль, на якій є ваш Відплив, має $s1% шанс поширити цей Відплив на іншого союзника поблизу." },
    { en = "Your damaging attacks have a chance to make your weapon glow hot with the fire of Khaz'goroth's forge, causing your autoattacks to do ${$<mult>*$mws*$257244s1} additional Fire damage for $256826d.\n\n\n\n|cFFFFFFFFKhaz'goroth's Shaping|r\n\nWhen empowered by the Pantheon, your Critical Strike, Haste, Mastery, or Versatility is increased by $256835s1 for $256835d. Khaz'goroth always empowers your highest stat.", ua = "Ваші атаки шкоди мають шанс розжарити вашу зброю вогнем кузні Каз'ґората, змушуючи ваші автоатаки завдавати додаткові ${$<mult>*$mws*$257244s1} шкоди Вогнем на $256826d.\n\n\n\n|cFFFFFFFFФормування Каз'ґората|r\n\nКоли вас наснажує Пантеон, ваша швидкість критичного удару, швидкість, майстерність або універсальність підвищується на $256835s1 на $256835d. Каз'ґорат завжди наснажує вашу найвищу характеристику." },
    { en = "Your healing spells have a chance to apply a shield that prevents the next $215248s1 damage taken for $215248d. While the shield holds, the target will be healed for $215248s2 every $215248t2 sec.", ua = "Ваші заклинання зцілення мають шанс накласти щит, що запобігає наступним $215248s1 отриманої шкоди протягом $215248d. Доки щит тримається, ціль зцілюється на $215248s2 кожні $215248t2 сек." },
    { en = "Empty the chalice upon an ally granting them ${$<healingrolemult>*$1253117s1} absorb for each drop spilled for $d1.", ua = "Виливає чашу на союзника, даруючи йому ${$<healingrolemult>*$1253117s1} поглинання за кожну розлиту краплю на $d1." },
    { en = "Caber toss.", ua = "Кидок колоди." },
    { en = "Restores $s2 health every $t2 sec and increases your Strength by $s1.  Lasts $d.", ua = "Відновлює $s2 здоров'я кожні $t2 сек і підвищує вашу силу на $s1. Триває $d." },
    { en = "Your direct spell damage has a chance to apply Mark of Doom for $184073d. Direct spell damage you do against the Marked target triggers an explosion for $184075s1 Shadow damage.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваша пряма шкода від заклять має шанс накласти Знак Прокляття на $184073d. Пряма шкода від заклять, завдана позначеній цілі, спричиняє вибух на $184075s1 шкоди Тіні. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increase your armor by $s1 and regenerate $343401s1 health every $t3 sec for $d, but you are slowed by $s2%.", ua = "Підвищує вашу броню на $s1 і відновлює $343401s1 здоров'я кожні $t3 сек протягом $d, але сповільнює вас на $s2%." },
    { en = "Chance when you hit with a harmful spell to grant Voidsight, increasing Critical Strike, Haste, and Mastery by $201410s1 and increasing all damage against Demons by $201410s2% for $201410d.", ua = "Шанс під час влучання шкідливим закляттям отримати Зір Порожнечі, що підвищує критичний удар, швидкість і майстерність на $201410s1 та збільшує всю шкоду демонам на $201410s2% протягом $201410d." },
    { en = "Give a bakar a biscuit, granting you $s1 Mastery for $d.", ua = "Дайте бакарові печиво, отримавши $s1 майстерності на $d." },
    { en = "Grasp the shard tightly to enrich yourself with crystalline energy, increasing your Mastery by $s1 for $d.", ua = "Міцно стисніть осколок, щоб наповнитися кристалічною енергією, підвищуючи вашу майстерність на $s1 протягом $d." },
    { en = "Your damaging spells have a chance to grant Nefarious Pact, increasing your casting speed by $225774s1% for $225774d. When Nefarious Pact expires, your casting speed is decreased by $225776s1% for $225776d.", ua = "Ваші шкідливі закляття мають шанс надати Мерзенний Пакт, підвищуючи швидкість читання заклять на $225774s1% протягом $225774d. Коли Мерзенний Пакт завершується, ваша швидкість читання заклять знижується на $225776s1% протягом $225776d." },
    { en = "Increases maximum health by ${$m1*10} for $d. Shares cooldown with other Battlemaster's trinkets.", ua = "Підвищує максимальне здоров'я на ${$m1*10} протягом $d. Має спільний час відновлення з іншими підвісками бойового майстра." },
    { en = "Absorbs $s1 damage.  Lasts $d.", ua = "Поглинає $s1 шкоди. Триває $d." },
    { en = "Curse an enemy, dealing $s1 Shadow damage every $t1 sec for $d. Duration increases by up to $s3% based on their missing health. (1 Min 30 Sec Cooldown)", ua = "Проклинає ворога, завдаючи $s1 шкоди Тіні кожні $t1 сек протягом $d. Тривалість збільшується до $s3% залежно від нестачі його здоров'я. (Час відновлення: 1 хв 30 сек)" },
    { en = "Call on the Lost Dwarves to rain down cannon fire at your location dealing $387777s1 Fire damage split between you and all enemies over $d.\n\n\n\nDamage is increased for each target struck, up to $s2 targets.", ua = "Кличе Загублених Дворфів обрушити гарматний вогонь на ваше місце, завдаючи $387777s1 шкоди Вогню, розподіленої між вами та всіма ворогами протягом $d.\n\n\n\nШкода збільшується за кожну вражену ціль, до $s2 цілей." },
    { en = "Your spells and abilities have a low chance to call forth a Winterpelt Defender to fight by your side for $398252d.", ua = "Ваші закляття та здібності мають низький шанс прикликати Захисника Зимошкурих, що б'ється поруч із вами протягом $398252d." },
    { en = "Increases $pri by $s1 for $d. Only usable in Pandaria.", ua = "Підвищує $pri на $s1 протягом $d. Можна використовувати лише в Пандарії." },
    { en = "Removes one Bleed effect.  Will not work on bleeds cast by enemies over level $ctrmax2067.", ua = "Знімає один ефект кровотечі. Не діє на кровотечі від ворогів понад рівень $ctrmax2067." },
    { en = "Become enveloped by a Gaseous Bubble that absorbs up to $s1 damage for $d. When the bubble is consumed or expires, it explodes and deals $s2 Frost damage to all nearby enemies within $214972A1 yards.", ua = "Огортає вас Газовою Бульбашкою, що поглинає до $s1 шкоди протягом $d. Коли бульбашка вичерпується або завершується, вона вибухає, завдаючи $s2 шкоди Льоду всім ворогам поблизу в межах $214972A1 м." },
    { en = "Your healing spells and abilities have a chance to summon Mister Pick-Me-Up for $467251d, firing a healing beam every $467251t1 sec that jumps between $s3 injured allies to restore $467250s1 health each.\n\n\n\nOverhealing from this effect irradiates allies to deal Nature damage to nearby enemies over $474467d, increased by additional overhealing.", ua = "Ваші зціляючі закляття та здібності мають шанс прикликати Пана Підбадьорника на $467251d, що випускає промінь зцілення кожні $467251t1 сек, який перестрибує між $s3 пораненими союзниками, відновлюючи кожному $467250s1 здоров'я.\n\n\n\nНадлишкове зцілення від цього ефекту опромінює союзників, завдаючи шкоди Природи ворогам поблизу протягом $474467d, що збільшується від додаткового надлишкового зцілення." },
    { en = "Increases mount speed by $s1%.  Does not work for players above level $ctrmax2067.", ua = "Підвищує швидкість їздової тварини на $s1%. Не діє для гравців вище $ctrmax2067 рівня." },
    { en = "Your spells and abilities have a chance to nourish the mycelium, granting you $s1 of a random secondary stat and Leech for $1284698d.", ua = "Ваші закляття та здібності мають шанс наситити міцелій, надаючи вам $s1 випадкової вторинної характеристики та поглинання здоров'я протягом $1284698d." },
    { en = "Increase the critical strike of all party members within $a1 yards by $s1 for $d.", ua = "Підвищує критичний удар усіх членів групи в межах $a1 м на $s1 протягом $d." },
    { en = "Unleash incendiary flames at your target inflicting $s1 Fire damage.", ua = "Вивільняє запальне полум'я в ціль, завдаючи $s1 одиниць Вогняної шкоди." },
    { en = "Increase your Critical Strike by $s1 every $t2 sec. Lasts $d.", ua = "Підвищує ваш критичний удар на $s1 кожні $t2 сек. Триває $d." },
    { en = "Upon killing a creature that grants you experience, you grow furious, increasing your chance to critically strike for the next 10 seconds.", ua = "Убивши істоту, що дає вам досвід, ви впадаєте в лють, підвищуючи ваш шанс критичного удару на наступні 10 секунд." },
    { en = "Your melee critical strikes grant Titanic Power, allowing you to power this device.  Titanic Power stacks up to $96923u times and lasts $96923d.", ua = "Ваші критичні удари в ближньому бою надають Титанічну Силу, що дає змогу живити цей пристрій. Титанічна Сила накопичується до $96923u разів і триває $96923d." },
    { en = "Your abilities have a chance to increase your $pri by $s1 for $357673d.", ua = "Ваші здібності мають шанс підвищити вашу $pri на $s1 на $357673d." },
    { en = "When you deal damage you have a chance to gain $120172s1 critical strike for $120172d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $120172s1 критичного удару протягом $120172d." },
    { en = "Your attacks have a chance to increase your Agility by $s1 every $t2 sec. Lasts $d.", ua = "Ваші атаки мають шанс підвищувати вашу Спритність на $s1 кожні $t2 с. Триває $d." },
    { en = "Shatter the quill, dealing $408903s1 Physical damage split between nearby enemies and absorbing $s1 damage for $d.", ua = "Розтрощує перо, завдаючи $408903s1 фізичної шкоди, розподіленої між ворогами поблизу, і поглинаючи $s1 шкоди протягом $d." },
    { en = "Increase all healing done by $s2% and causes $s4% of overhealing on players to be redistributed to up to $s1 nearby injured allies, for $d.", ua = "Підвищує все завдане зцілення на $s2% і спричиняє перерозподіл $s4% надлишкового зцілення на гравцях до $s1 поранених союзників поблизу протягом $d." },
    { en = "Consume all Latent Power to gain $1233553s2 $?(a137047|a137005|a137026)[Strength]?(a212611|a137009|a137014|a137022|a137034|a137038)[Agility][Strength or Agility] per stack for $d.", ua = "Поглиньте всю Приховану Силу, щоб отримати $1233553s2 $?(a137047|a137005|a137026)[сили]?(a212611|a137009|a137014|a137022|a137034|a137038)[спритності][сили чи спритності] за заряд протягом $d." },
    { en = "Each time your melee attacks hit, you have a chance to gain $146296s1 haste for $146296d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки в ближньому бою влучають, ви маєте шанс отримати $146296s1 швидкості протягом $146296d. ($h% шанс, час відновлення ${$proccooldown} сек)" },
    { en = "Your damaging abilities have a high chance to smell out the scent of delicious soul energy, stacking up to $s2 times. At full stacks, a swarm of devourers burst forth, chomping your target for $s1 Physical damage.\n\n\n\nEffects that cause your target to move generate bonus stacks.", ua = "Ваші здібності, що завдають шкоди, мають високий шанс винюхати запах смачної енергії душі, накопичуючись до $s2 разів. На повних стопках вивергається рій пожирачів, що вгризається у вашу ціль на $s1 фізичної шкоди.\n\n\n\nЕфекти, що змушують вашу ціль рухатися, дають додаткові стопки." },
    { en = "Your harmful spells and abilities have a chance to brand your target with sacred text dealing ${$s1*$1266394d/$1266394t} Holy damage over $1266394d.\n\n\n\nRebranding an enemy ignites the text, granting you $s2 Critical Strike for $1266403d and immediately dealing all remaining damage.", ua = "Ваші шкідливі закляття та здібності мають шанс затаврувати вашу ціль священним текстом, завдаючи ${$s1*$1266394d/$1266394t} шкоди Світла протягом $1266394d.\n\n\n\nПовторне таврування ворога займає текст, надаючи вам $s2 критичного удару протягом $1266403d і миттєво завдаючи всю решту шкоди." },
    { en = "Your spells have a chance to infuse the leyrose with mana, causing it to rapidly bloom. While blooming, it infuses you with $s1 Intellect for $1272942d.", ua = "Ваші закляття мають шанс наповнити лейрозу маною, змушуючи її стрімко розквітати. Поки вона квітне, вона наповнює вас $s1 інтелекту протягом $1272942d." },
    { en = "Your melee and ranged strikes have a chance to increase your critical strike by $61671s1 for $61671d.", ua = "Ваші удари в ближньому та дальньому бою мають шанс підвищити ваш критичний удар на $61671s1 протягом $61671d." },
    { en = "Restores $s1 mana every $t1 sec for $d.", ua = "Відновлює $s1 мани кожні $t1 сек протягом $d." },
    { en = "Your spells and abilities have a chance to unleash vibrant vines that surge toward your target. Enemies struck take ${$s2*5} Nature damage over $1255357d. Allies are wrapped in protective flora, absorbing up to $s3 damage over $1255367d.", ua = "Ваші закляття та здібності мають шанс вивільнити яскраві лози, що ринуть до вашої цілі. Вражені вороги отримують ${$s2*5} шкоди Природи протягом $1255357d. Союзники огортаються захисною флорою, що поглинає до $s3 шкоди протягом $1255367d." },
    { en = "Your harmful melee abilities have a chance to Gnash your target dealing ${$<rolemult>*$s1} Physical damage. Every third Gnash on the same target does additional damage based on targets missing health. Count is reset if Gnash hits a different target.", ua = "Ваші шкідливі здібності ближнього бою мають шанс Скусити вашу ціль, завдаючи ${$<rolemult>*$s1} фізичної шкоди. Кожне третє Скусювання тієї самої цілі завдає додаткової шкоди залежно від нестачі здоров'я цілі. Лічильник скидається, якщо Скусювання влучає в іншу ціль." },
    { en = "Your melee attacks have a chance to grant $91364s1 Strength for $91364d.", ua = "Ваші атаки в ближньому бою мають шанс надати $91364s1 сили протягом $91364d." },
    { en = "Channel on a friendly target to restore up to ${$343538s2*(1+$@versadmg)} health over $d split between all allies bathed in the $343541a1 yd beam. Channel on an enemy target dealing up to ${$343538s1*(1+$@versadmg)} Holy damage over $d split amongst enemies caught in the $343540a1 yd beam. Damage and Healing are increased slightly for each target hit.", ua = "Канальте на дружню ціль, щоб відновити до ${$343538s2*(1+$@versadmg)} здоров'я протягом $d, розподіленого між усіма союзниками, охопленими променем у $343541a1 м. Канальте на ворожу ціль, завдаючи до ${$343538s1*(1+$@versadmg)} шкоди Світла протягом $d, розподіленої між ворогами, охопленими променем у $343540a1 м. Шкода та зцілення трохи збільшуються за кожну вражену ціль." },
    { en = "Reignite the pilot light to gain $471057s1 Intellect for $d. After casting $473147u harmful spells, it unleashes a beam dealing ${$471057s2*$<rolemult>} Fire damage to your primary target and ${$471057s2*$471057s3/100*$<rolemult>} damage to up to $471057s4 enemies in its path.", ua = "Знову запаліть запальний вогник, щоб отримати $471057s1 інтелекту протягом $d. Після читання $473147u шкідливих заклять він вивільняє промінь, що завдає ${$471057s2*$<rolemult>} шкоди Вогню вашій основній цілі та ${$471057s2*$471057s3/100*$<rolemult>} шкоди до $471057s4 ворогам на його шляху." },
    { en = "Transform to Eye of Shatug.", ua = "Перетворитися на Око Шатуга." },
    { en = "Each time your attacks hit, you have a chance to gain $162915s1 critical strike for $162915d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $162915s1 критичного удару на $162915d. ($h% шанс, ${$proccooldown} сек перезарядка)" },
    { en = "Instantly remove all Fear effects.", ua = "Миттєво знімає всі ефекти страху." },
    { en = "Call forth an Attendant Automa who channels ${$367307s1*$d} Cosmic damage onto your target over $d, after which it expires.", ua = "Прикликає Автома-прислужника, що підтримує ${$367307s1*$d} космічної шкоди по цілі протягом $d, після чого зникає." },
    { en = "Let loose a five-hit combo upon your current target dealing a total of ${$414928s2*$s2} Physical damage and unleashing a $?FAC=[Doomstrike][Kingstrike] with each blow.", ua = "Випускає серію з п'яти ударів по поточній цілі, завдаючи в сумі ${$414928s2*$s2} фізичної шкоди та вивільняючи $?FAC=[Удар Приреченості][Королівський Удар] з кожним ударом." },
    { en = "Chance on spell critical hit to increase your critical strike by $54739s1 for $54739d.", ua = "Шанс при критичному влученні заклять підвищити ваш критичний удар на $54739s1 на $54739d." },
    { en = "Your melee attacks and abilities have a chance to $?FAC=[Doomstrike][Kingstrike] your target, dealing $s1 $?FAC=[Nature][Holy] damage.", ua = "Ваші ближні атаки й здібності мають шанс уразити ціль $?FAC=[Ударом приреченості][Королівським ударом], завдаючи $s1 шкоди $?FAC=[від сил природи][від сил святості]." },
    { en = "Your attacks have a chance to mark their targets as Dead Ahead. Attacking the marked target grants $268769s1 Critical Strike for $268769d, stacking up to $268769U times.", ua = "Ваші атаки мають шанс позначити цілі як «Прямо по курсу». Атака позначеної цілі надає $268769s1 критичного удару на $268769d, накопичуючись до $268769U разів." },
    { en = "Your healing and damaging spells have a chance to grant $122917s1 mastery for $122917d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $122917s1 майстерності на $122917d." },
    { en = "Unleash a colossal slam that always critically hits, dealing $232044s1 Physical damage split amongst all nearby enemies. If you hit less than $s2 targets, the cooldown of this ability is reduced by $s3 seconds.", ua = "Завдає колосального удару, що завжди влучає критично, спричиняючи $232044s1 фізичної шкоди, розподіленої між усіма ворогами поблизу. Якщо ви влучите менш ніж по $s2 цілях, час перезарядки цієї здібності зменшується на $s3 секунд." },
    { en = "Your melee attacks have a chance to trigger Spirit Shift for $184293d. While a spirit, your damage dealt is stored up. When this effects ends, you explode back into corporeality, dealing ${100+$m1/100}.2% of the stored damage to all enemies within 10 yds, split evenly. (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки ближнього бою мають шанс активувати Перехід у дух на $184293d. Доки ви дух, завдана вами шкода накопичується. Коли цей ефект завершується, ви вибухаєте, повертаючись у тіло, і завдаєте ${100+$m1/100}.2% накопиченої шкоди всім ворогам у радіусі 10 м, рівномірно розподіленої. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your spells and abilities have a chance to grant $183924s1 Intellect for $183924d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші закляття та здібності мають шанс надати $183924s1 інтелекту на $183924d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage you have a chance to gain $122918s1 mastery for $122918d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $122918s1 майстерності на $122918d." },
    { en = "Kindle your soul, gaining ${$268998U1*$268998s1} Intellect, which decays over $D or when taking damage.", ua = "Запалює вашу душу, надаючи ${$268998U1*$268998s1} Інтелекту, що згасає протягом $D або при отриманні шкоди." },
    { en = "Your spells that damage a target below $s1% health grant $91002s1 spell power for $91002d.  Cannot activate again for $91002d after bonus expires.", ua = "Ваші закляття, що завдають шкоди цілі зі здоров'ям нижче $s1%, надають $91002s1 сили заклять на $91002d. Не може активуватися знову протягом $91002d після завершення бонусу." },
    { en = "Your abilities have a chance to increase your Haste by $451750s1 for $451748d.", ua = "Ваші здібності мають шанс підвищити вашу швидкість на $451750s1 на $451748d." },
    { en = "Your harmful attacks, spells, and abilities have a chance to engage the dispenser dropping $s2 footbombs on the field for $1234025d.\n\n\n\nRunning into a footbomb kicks it at your current target dealing ${$s1*$<rolemult>} Fire damage to all enemies in a $1234219a-yard radius.", ua = "Ваші шкідливі атаки, закляття та здібності мають шанс задіяти роздавач, скидаючи $s2 ножибомб на поле на $1234025d.\n\n\n\nНаштовхнувшись на ножибомбу, ви відбиваєте її в поточну ціль, завдаючи ${$s1*$<rolemult>} вогняної шкоди всім ворогам у радіусі $1234219a м." },
    { en = "Your melee attacks have a chance to generate extra appendages for $222166d that attack nearby enemies for $222168s1 Physical damage every ${$222166t1}.2 sec.", ua = "Ваші атаки ближнього бою мають шанс породити додаткові відростки на $222166d, що атакують ворогів поблизу, завдаючи $222168s1 фізичної шкоди кожні ${$222166t1}.2 сек." },
    { en = "Your melee attacks and abilities have a chance to viciously brand your target, dealing ${$s1*((1+$s3/100)^(1-$s5))} Fire damage over 6 sec, and grant you $@spellname425153, stacking up to 15 times. Damage increased per stack to a maximum of ${$s1*((1+$s3/100)^($s2-$s5))}.\n\n\n\nWhile above 5 stacks, also deals $s4% of its damage to you. At 15 stacks, enemies near your target suffer $s6% of the damage dealt split between them. $@spellname425153 decays every $425153t2 sec while out of combat and fades entirely after $s8 sec.", ua = "Ваші ближні атаки й здібності мають шанс люто затаврувати ціль, завдаючи ${$s1*((1+$s3/100)^(1-$s5))} шкоди від вогню протягом 6 сек, і надати вам $@spellname425153, що накопичується до 15 разів. Шкода збільшується за кожен заряд до максимуму ${$s1*((1+$s3/100)^($s2-$s5))}.\n\n\n\nПонад 5 зарядів ефект також завдає $s4% своєї шкоди вам. При 15 зарядах вороги поруч із вашою ціллю зазнають $s6% завданої шкоди, розподіленої між ними. $@spellname425153 згасає кожні $425153t2 сек поза боєм і повністю зникає через $s8 сек." },
    { en = "Your critical strikes have a chance to build Static Electricity, granting $s2% attack speed per stack. This effect may occur every $proccooldown sec.\n\n\n\nAt $s3 stacks lightning surges through you, increasing your movement speed by $s4% for $s1 seconds. While surging, your auto attacks jolt your target and 1 nearby enemy for $s5 Nature damage.\n\n\n\nWhen this effect fades, you become grounded for $397621d and unable to generate Static Electricity.", ua = "Ваші критичні удари мають шанс накопичувати статичну електрику, що надає $s2% швидкості атаки за заряд. Цей ефект може спрацьовувати раз на $proccooldown сек.\n\n\n\nПри $s3 зарядах крізь вас проходить блискавка, підвищуючи вашу швидкість пересування на $s4% на $s1 секунд. Поки триває розряд, ваші автоатаки б'ють струмом ціль і 1 ворога поруч, завдаючи $s5 шкоди від сил природи.\n\n\n\nКоли цей ефект згасає, ви заземлюєтеся на $397621d і не можете накопичувати статичну електрику." },
    { en = "Sheathe your weapons in ice for $d, giving your melee attacks a chance to cause $214964s1 additional Frost damage and slow the target's movement speed by $214964s2% for $214964d.", ua = "Огортає вашу зброю кригою на $d, надаючи вашим атакам ближнього бою шанс завдати додатково $214964s1 крижаної шкоди та сповільнити швидкість пересування цілі на $214964s2% на $214964d." },
    { en = "Your attacks have a chance to grant you $138870s1 Strength for $138870d. This effect can stack up to $138870u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати вам $138870s1 сили на $138870d. Цей ефект може накопичуватися до $138870u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Taking damage and melee attacks can coat yourself in fiery thorns, granting $s1 Strength and reducing damage taken from enemies by $s2 for $424107d.", ua = "Отримання шкоди та атаки ближнього бою можуть вкрити вас вогняними шипами, надаючи $s1 сили та зменшуючи шкоду, отриману від ворогів, на $s2 на $424107d." },
    { en = "Your damaging spells have a chance to cause a Cacaphonous Chord, dealing $271671s1 damage to a nearby enemy.\n\n\n\nYour healing spells have a chance to cause a Harmonious Chord, restoring $271682s1 health to a nearby injured ally.", ua = "Ваші шкідливі закляття мають шанс спричинити Какофонічний акорд, завдаючи $271671s1 шкоди ворогові поблизу.\n\n\n\nВаші зцілювальні закляття мають шанс спричинити Гармонійний акорд, відновлюючи $271682s1 здоров'я пораненому союзникові поблизу." },
    { en = "Your damaging abilities have a chance to unleash the prism's radiant light, increasing your Critical Strike by $s1 for $1255504d, further increased by $s2 for every $s3% of the target's missing health, up to a maximum of $s4.", ua = "Ваші здібності, що завдають шкоди, мають шанс вивільнити сяйливе світло призми, підвищуючи ваш критичний удар на $s1 на $1255504d, додатково збільшене на $s2 за кожні $s3% відсутнього здоров'я цілі, до максимуму в $s4." },
    { en = "Starsurge has a $s1% chance to also trigger Starfall.", ua = "Зоряний прибій має $s1% шанс також активувати Зорепад." },
    { en = "Each time your harmful spells hit, you have a chance to gain $138703s1 haste for $138703d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші шкідливі закляття влучають, ви маєте шанс отримати $138703s1 швидкості на $138703d. ($h% шанс, ${$proccooldown} сек перезарядка)" },
    { en = "Your healing spells have a chance to trigger a beam of Twilight Restoration, healing all allies in front of you for $s1.", ua = "Ваші зцілювальні закляття мають шанс активувати промінь Сутінкового відновлення, зцілюючи всіх союзників перед вами на $s1." },
    { en = "Heals the target for $s1 every $t1 sec, stacking up to $U times. Healing starts low and increases over the duration.", ua = "Зцілює ціль на $s1 кожні $t1 сек, накопичуючись до $U разів. Зцілення починається з малого й зростає протягом дії ефекту." },
    { en = "Weep before the Eternals, dedicating yourself to their service.\n\n\n\nGain $s1 of your highest secondary stat, and grant $s2% of this bonus to any party members who also serve your covenant.", ua = "Ридайте перед Вічними, присвячуючи себе служінню їм.\n\n\n\nОтримайте $s1 до своєї найвищої вторинної характеристики та надайте $s2% цього бонусу будь-яким членам групи, що також служать вашому ковенанту." },
    { en = "Mark an enemy with a Thunder Ritual, dealing $230224s1 Nature damage after $d. If they are affected by Flame Gale, Thunder Ritual deals $s2% increased damage and stuns for $230228d.", ua = "Позначає ворога Ритуалом грому, завдаючи $230224s1 шкоди силами природи через $d. Якщо на нього діє Вогняний шквал, Ритуал грому завдає на $s2% більше шкоди та оглушує на $230228d." },
    { en = "When you deal damage you have a chance to gain $107988s1 critical strike for $107988d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $107988s1 критичного удару на $107988d." },
    { en = "When you deal damage you have a chance to gain $92220s1 Agility for $92220d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $92220s1 спритності на $92220d." },
    { en = "Increase your Haste by $s1 for $d.", ua = "Підвищує вашу швидкість на $s1 на $d." },
    { en = "Each successful block heals you for $33090s1. Lasts $d.", ua = "Кожен успішний блок зцілює вас на $33090s1. Триває $d." },
    { en = "Your attacks have a chance to grant you $278288s1 Strength for $278288d.", ua = "Ваші атаки мають шанс надати вам $278288s1 сили на $278288d." },
    { en = "Your $?a137012[Rejuvenation and Regrowth]?a137024[Vivify and Enveloping Mist]?a137031[Heal and Flash Heal]?a137032[Flash Heal and Power Word: Shield]?a137029[Holy Light and Flash of Light]?a137039[Healing Wave and Healing Surge]?a353167[Living Flame and Echo][direct healing spells] apply and refresh Fragile Echo for $215267d. When Fragile Echo expires, it restores $s1 mana to you.", ua = "Ваші $?a137012[«Омолодження» та «Відновлення росту»]?a137024[«Оживлення» та «Огортальний туман»]?a137031[«Зцілення» та «Швидке зцілення»]?a137032[«Швидке зцілення» та «Слово сили: Щит»]?a137029[«Святе світло» та «Спалах світла»]?a137039[«Хвиля зцілення» та «Прибій зцілення»]?a353167[«Жива полум'я» та «Відлуння»][чари прямого зцілення] накладають і поновлюють «Крихке відлуння» на $215267d. Коли «Крихке відлуння» спливає, воно відновлює вам $s1 мани." },
    { en = "Your damaging attacks and abilities have a chance to grant $128519s1 critical strike for $128519d.", ua = "Ваші атаки та здібності, що завдають шкоди, мають шанс надати $128519s1 критичного удару на $128519d." },
    { en = "Your spell casts have a chance to increase your spell power by $60064s1 for $60064d.", ua = "Ваші накладання заклять мають шанс підвищити вашу силу заклять на $60064s1 на $60064d." },
    { en = "Summon Pitbot Geardo to assist you for $d, coating nearby enemies with rancid motor oil for additional threat. Geardo ensures you take the blame.\n\n\n\nGeardo departs explosively to deal $466646s1 Fire damage split between nearby enemies, increased by $466646s3% if recently oiled.", ua = "Прикликає Пітбота Гірдо на допомогу на $d, обливаючи ворогів поблизу прогірклою моторною оливою для додаткової загрози. Гірдо подбає, щоб провину поклали на вас.\n\n\n\nГірдо вибухово зникає, завдаючи $466646s1 вогняної шкоди, розподіленої між ворогами поблизу, збільшеної на $466646s3%, якщо вони нещодавно облиті оливою." },
    { en = "Increases Critical Strike by $s1 for $d.", ua = "Підвищує критичний удар на $s1 на $d." },
    { en = "Increase an ally's Armor by up to $s2 and heal them for up to ${$s1*($d/($t1+1))} over $d. These effects are increased based on the current health of your target, and are most powerful on targets below $s4% health.", ua = "Підвищує броню союзника до $s2 та зцілює його до ${$s1*($d/($t1+1))} протягом $d. Ці ефекти посилюються залежно від поточного здоров'я вашої цілі та найпотужніші на цілях зі здоров'ям нижче $s4%." },
    { en = "Your harmful spells have a chance to afflict your victim with Vengeful Wisp, which deals $91075s1 damage every $91075t1 sec.  In addition, each time the Vengeful Wisp deals damage, it has a $s1% chance to spread to a random nearby enemy.", ua = "Ваші шкідливі закляття мають шанс уразити жертву Мстивим вогником, що завдає $91075s1 шкоди кожні $91075t1 сек. Крім того, щоразу, коли Мстивий вогник завдає шкоди, він має $s1% шанс поширитися на випадкового ворога поблизу." },
    { en = "Your healing spells have a chance to grant the target $214142s1 Haste and heal them for $214142o2 over $214142d.", ua = "Ваші зцілювальні закляття мають шанс надати цілі $214142s1 швидкості та зцілити її на $214142o2 протягом $214142d." },
    { en = "Your damaging spells have a chance to stir the Void near your target, erupting for $s1 Shadow damage split among nearby enemies. You siphon energy from the Void, gaining $s2 Intellect for $1264404d.", ua = "Ваші шкідливі заклять мають шанс сколихнути Порожнечу біля вашої цілі, що вибухає, завдаючи $s1 шкоди Темрявою, розподіленої між ворогами поблизу. Ви висмоктуєте енергію Порожнечі, отримуючи $s2 інтелекту на $1264404d." },
    { en = "Unfurl a myriad of grasping webs in front of you entangling your enemies, reducing damage they deal to you by $s3% up to $s2 total damage and reducing their Attack Speed by $s1% for $d.\n\n\n\n$?$pl>80[Attack Speed reduction is less effective against enemies above level $s4.][]", ua = "Розгортає перед вами безліч чіпких павутин, що обплутують ваших ворогів, зменшуючи шкоду, яку вони вам завдають, на $s3% до загальної шкоди $s2 та знижуючи їхню швидкість атаки на $s1% протягом $d.\n\n\n\n$?$pl>80[Зниження швидкості атаки менш дієве проти ворогів понад рівень $s4.][]" },
    { en = "Summons a Bound Voidcaller to fight for you for $d.", ua = "Прикликає Зв'язаного Викликача Порожнечі, який б'ється за вас упродовж $d." },
    { en = "+$s1 Weapon Damage.", ua = "+$s1 до шкоди зброї." },
    { en = "Form a Fel Shield for $d, absorbing $s2% of incoming damage, up to $1283373s1. While the shield holds, a portion of the absorbed damage is stored as volatile Fel energy.\n\n\n\nWhen the shield expires or breaks, the energy erupts and inflicts Fire damage to split between nearby enemies.", ua = "Створює Скверний Щит на $d, поглинаючи $s2% вхідної шкоди, до $1283373s1. Поки щит тримається, частина поглинутої шкоди накопичується як нестабільна енергія Скверни.\n\n\n\nКоли щит спливає або руйнується, енергія вивільняється і завдає шкоди Вогнем, розподіленої між ворогами поблизу." },
    { en = "Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $24853s1 mana every $24853t1 seconds to group members within $24853a1 yards.", ua = "Прикликає до ніг закляттяра Тотем Манового Джерела з $s1 здоров'я на $d, що відновлює $24853s1 мани кожні $24853t1 с членам групи в межах $24853a1 ярдів." },
    { en = "You gain a Thunder Charge each time you cause a damaging spell critical strike. When you reach $s1 Thunder Charges, they will release, firing a Lightning Bolt for $54843s1 damage. Thunder Charge cannot be gained more often than once every 2.5 sec.", ua = "Ви отримуєте Громовий Заряд щоразу, коли завдаєте критичного удару шкідливим закляттям. Коли ви досягаєте $s1 Громових Зарядів, вони вивільняються, випускаючи Блискавицю, що завдає $54843s1 шкоди. Громовий Заряд не можна отримувати частіше, ніж раз на 2.5 с." },
    { en = "Increases all resistances by $s1 for $d.", ua = "Підвищує всі опірності на $s1 на $d." },
    { en = "Increase your primary stat by $s1 for $d.", ua = "Підвищує вашу основну характеристику на $s1 на $d." },
    { en = "For the next $d, each time your direct healing spells heal a target you cause the target of your heal to heal themselves and friends within $75493a1 yards for $75493s1 each sec for $75493d.", ua = "Упродовж наступних $d щоразу, коли ваші прямі зцілювальні заклять зцілюють ціль, ви змушуєте ціль вашого зцілення зцілювати себе та союзників у межах $75493a1 ярдів на $75493s1 щосекунди упродовж $75493d." },
    { en = "Your melee attacks have a chance to grant $109994s1 mastery for $109994d.", ua = "Ваші ближні атаки мають шанс надати $109994s1 майстерності на $109994d." },
    { en = "Restores $s1 health per 5 sec.", ua = "Відновлює $s1 здоров'я кожні 5 с." },
    { en = "Your spells and abilities have a low chance to grant Annihilating Flame for $426553d, causing your critical strikes to deal $s2% additional damage as Fire split between nearby enemies. The Flame may deal ${$s1*(1+$@versadmg)} total damage before fading, further increased by critical strikes.\n\n\n\nDamage and cap increased per enemy struck, up to 5.", ua = "Ваші заклять і вміння мають низький шанс надати Нищівне Полум'я на $426553d, через що ваші критичні удари завдають додатково $s2% шкоди Вогнем, розподіленої між ворогами поблизу. Полум'я може завдати загалом ${$s1*(1+$@versadmg)} шкоди, перш ніж згасне, що додатково посилюється критичними ударами.\n\n\n\nШкода й межа зростають за кожного враженого ворога, до 5." },
    { en = "$?a251967[Grants $256718s1 additional Armor to a nearby tank-specialized ally bearing the Eye of F'harg.]?a251968[Grants $256719s1 additional Versatility to a nearby tank-specialized ally bearing the Eye of Shatug.][Grants $256718s1 Armor or $256719s1 Versatility to a nearby tank-specialized ally bearing the opposite Eye.]", ua = "$?a251967[Надає $256718s1 додаткової броні найближчому союзнику-танку, що носить Око Ф'харга.]?a251968[Надає $256719s1 додаткової універсальності найближчому союзнику-танку, що носить Око Шатуга.][Надає $256718s1 броні або $256719s1 універсальності найближчому союзнику-танку, що носить протилежне Око.]" },
    { en = "Increases the cooldown recovery rate of some of your major abilities by $s1%.  Effective for Strength-based damage roles only. Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Підвищує швидкість відновлення деяких ваших головних здібностей на $s1%. Ефективно лише для бойових ролей на основі Сили. Знижена ефективність на $ctrmin2066 рівні та вище." },
    { en = "$?a303565[Remove Razor Coral from your target, granting you $303573s1 Critical Strike per stack for $303570d.][Deal ${$304877s1*(1+$@versadmg)} Physical damage and apply Razor Coral to your target, giving your damaging abilities against the target a high chance to deal ${$304877s1*(1+$@versadmg)} Physical damage and add a stack of Razor Coral.\n\n\n\nReactivating this ability will remove Razor Coral from your target, granting you $303573s1 Critical Strike per stack for $303570d.]", ua = "$?a303565[Знімає Гострий Корал із цілі, надаючи вам $303573s1 критичного удару за кожен заряд протягом $303570d.][Завдає ${$304877s1*(1+$@versadmg)} фізичної шкоди й накладає на ціль Гострий Корал, через що ваші здатності, що завдають шкоди цілі, мають високий шанс завдати ${$304877s1*(1+$@versadmg)} фізичної шкоди та додати заряд Гострого Коралу.\n\n\n\nПовторна активація цієї здатності знімає Гострий Корал із цілі, надаючи вам $303573s1 критичного удару за кожен заряд протягом $303570d.]" },
    { en = "Increases your critical strike by $s1 and size for $d.", ua = "Підвищує вашу критичну влучність на $s1 і розмір на $d." },
    { en = "Empowers your pet, increasing its attack power by $s1 for $d. This spell will only affect an Imp, Succubus, Voidwalker, Felhunter, or Felguard.", ua = "Наснажує вашого улюбленця, підвищуючи його силу атаки на $s1 на $d. Це закляття діє лише на Біса, Сукубу, Блукача Порожнечі, Скверноборця чи Скверногвардійця." },
    { en = "Your melee and ranged attacks have a chance to increase your critical strike by $40477s1 for $40477d.", ua = "Ваші ближні та дальні атаки мають шанс підвищити вашу критичну влучність на $40477s1 на $40477d." },
    { en = "Roll a tiny Iron Star at the target, dealing $s1 Fire Damage upon impact.", ua = "Котить крихітну Залізну Зорю на ціль, завдаючи $s1 шкоди Вогнем під час зіткнення." },
    { en = "Your damaging spells have a chance to grant you $215816s1 Critical Strike every $215815t2 sec for $215815d.", ua = "Ваші шкідливі заклять мають шанс надати вам $215816s1 критичної влучності кожні $215815t2 с упродовж $215815d." },
    { en = "Chance on melee and ranged critical strike to increase your Agility by $194608s1 for $194608d.", ua = "Шанс при критичному ближньому чи дальньому ударі підвищити вашу спритність на $194608s1 на $194608d." },
    { en = "Unleash a Silverstrike Trick Shot, critically striking your target and a nearby enemy for ${$1260265s1*$<rolemult>} Arcane damage. This damage is further increased by your critical strike chance.\n\n\n\nYour critical strikes have a high chance to reduce this cooldown by $1260265s2 sec.", ua = "Вивільняє Каверзний Постріл Срібного Удару, критично вражаючи вашу ціль і ворога поблизу на ${$1260265s1*$<rolemult>} шкоди Тайнощами. Ця шкода додатково посилюється вашим шансом критичного удару.\n\n\n\nВаші критичні удари мають високий шанс скоротити цей час відновлення на $1260265s2 с." },
    { en = "Your melee and ranged attacks have a chance to grant $117644s1 mastery for $117644d.", ua = "Ваші ближні та дальні атаки мають шанс надати $117644s1 майстерності на $117644d." },
    { en = "Push the Big Red Button, launching a missile barrage which deals ${$<rolemult>*$271376s1} Fire damage split among all enemies in the area. Deals increased damage when striking multiple targets.", ua = "Натискає Велику Червону Кнопку, запускаючи залп ракет, що завдає ${$<rolemult>*$271376s1} шкоди Вогнем, розподіленої між усіма ворогами в зоні. Завдає підвищеної шкоди при враженні кількох цілей." },
    { en = "Increases primary stat by $s1 for $d.", ua = "Підвищує основну характеристику на $s1 на $d." },
    { en = "Your damaging spells have a chance to grant $138963s1% critical strike chance for $138963d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші шкідливі заклять мають шанс надати $138963s1% шансу критичного удару на $138963d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Deal $o1 Arcane damage to an enemy over $d.\n\n\n\nIf your target dies while afflicted with Glyph of Assimilation, your Mastery is increased by $345500s1 for $s2 times the duration remaining on the Glyph.", ua = "Завдає $o1 шкоди Тайнощами ворогові упродовж $d.\n\n\n\nЯкщо ваша ціль гине, перебуваючи під дією Гліфа Засвоєння, ваша майстерність підвищується на $345500s1 на $s2-кратний час, що лишився на Гліфі." },
    { en = "Channel latent magic for up to $296971d, increasing your primary stat by $s1. The duration is extended for each second spent channeling, up to $M4 sec.", ua = "Спрямовує приховану магію впродовж до $296971d, підвищуючи вашу основну характеристику на $s1. Тривалість продовжується за кожну секунду спрямування, до $M4 с." },
    { en = "Taking magic damage has a chance to apply Choking Flames to the attacker, silencing them for $214459d.\n\n\n\nThis may only occur once every $proccooldown sec.", ua = "Коли ви отримуєте магічну шкоду, є шанс накласти Удушливе Полум'я на нападника, занімовуючи його на $214459d.\n\n\n\nЦе може статися не частіше ніж раз на $proccooldown с." },
    { en = "Use: Call a Refreshing Dance that bounces 6-13 times between friends and foes within $r yards dealing $384613s1 Nature damage or $384624s1 healing. The number of bounces is determined by the top-most card of the deck.", ua = "Застосування: Викликає Освіжний Танець, що відскакує 6-13 разів між союзниками й ворогами в межах $r ярдів, завдаючи $384613s1 шкоди Природою або зцілюючи на $384624s1. Кількість відскоків визначається верхньою картою колоди." },
    { en = "Each time you cast a spell, you gain $67750s1 Versatility for $67750d.  Stacks up to $67750u times.", ua = "Щоразу, коли ви читаєте закляття, ви отримуєте $67750s1 універсальності на $67750d. Накопичується до $67750u разів." },
    { en = "When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by $s1 for $60229d. Your highest stat is always chosen.", ua = "Коли ви зцілюєте або завдаєте шкоди, ви маєте шанс підвищити вашу силу, спритність чи інтелект на $s1 на $60229d. Завжди обирається ваша найвища характеристика." },
    { en = "Absorbs $s1 damage for $d.  When the shield is removed by any means, you regain $60242s1 mana.", ua = "Поглинає $s1 шкоди на $d. Коли щит знімається в будь-який спосіб, ви відновлюєте $60242s1 мани." },
    { en = "Increases maximum health by $s1 for $d.", ua = "Підвищує максимальне здоров'я на $s1 на $d." },
    { en = "Your attacks have a chance to cause Wasting Infection, dealing ${$278110s1*$278110d/$278110t1} Shadow damage over $278110d. Attacking an enemy suffering from Wasting Infection grants you $278108s1 Critical Strike for $278108d, stacking up to $278108u times.", ua = "Ваші атаки мають шанс спричинити Виснажливу Інфекцію, що завдає ${$278110s1*$278110d/$278110t1} шкоди Темрявою упродовж $278110d. Атака ворога, що страждає від Виснажливої Інфекції, надає вам $278108s1 критичної влучності на $278108d, накопичуючись до $278108u разів." },
    { en = "Your next $97120u spells cast within $d will reduce the cost of your holy and nature spells by $97120s1, stacking up to $97120u times.", ua = "Ваші наступні $97120u заклять, прочитані впродовж $d, зменшать вартість ваших заклять Священства та Природи на $97120s1, накопичуючись до $97120u разів." },
    { en = "When you deal damage you have a chance to gain $122267s1 haste for $122267d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $122267s1 швидкості на $122267d." },
    { en = "Your attacks have a chance to launch a Dread Spore at the target, inflicting $268524s1 Shadow damage.", ua = "Ваші атаки мають шанс запустити Спору Жаху в ціль, завдаючи $268524s1 шкоди Темрявою." },
    { en = "Your healing and damaging spells have a chance to grant $118606s1 mastery for $118606d.", ua = "Ваші зцілювальні та шкідливі заклять мають шанс надати $118606s1 майстерності на $118606d." },
    { en = "Your healing abilities have a chance to heal your target for $336608s1. If your target is missing more health than you, sacrifice up to $s1 health, healing your ally for that amount.", ua = "Ваші зцілювальні вміння мають шанс зцілити вашу ціль на $336608s1. Якщо вашій цілі бракує більше здоров'я, ніж вам, ви жертвуєте до $s1 здоров'я, зцілюючи вашого союзника на цю величину." },
    { en = "Increase a random secondary stat by $230102s1 for $230102d.", ua = "Підвищує випадкову вторинну характеристику на $230102s1 на $230102d." },
    { en = "Your heals have a ${$m1/100}.2% chance to Cleave, dealing the same healing to up to 5 other nearby targets. Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Ваші зцілення мають ${$m1/100}.2% шансу розсіктися, завдаючи такого ж зцілення до 5 іншим цілям поруч. Знижена ефективність на рівні $ctrmin2066 і вище." },
    { en = "Taking damage has a chance to grant you Cunning of the Deceiver, stacking up to $242630u times.", ua = "Отримана шкода дає шанс надати вам Хитрість Ошуканця, що накопичується до $242630u разів." },
    { en = "Each time your spells heal you have a chance to gain $146314s1 Intellect for $146314d.  ($h% chance, ${$proccooldown} sec cooldown).  Effective for healer specializations only.", ua = "Щоразу, коли ваші заклять зцілюють, ви маєте шанс отримати $146314s1 інтелекту на $146314d. ($h% шансу, ${$proccooldown} сек перезарядки). Діє лише для зцілювальних спеціалізацій." },
    { en = "Encase your body in crystal, absorbing up to $s2 damage from each attack against you. Absorbs up to ${$s1*(1+$@versadmg)} total damage.\n\n\n\nLasts $d.", ua = "Огортає ваше тіло кристалом, що поглинає до $s2 шкоди від кожної атаки проти вас. Поглинає загалом до ${$s1*(1+$@versadmg)} шкоди.\n\n\n\nТриває $d." },
    { en = "Your melee attacks grant $109780s1 dodge for the next $109780d, stacking up to $109780u times.", ua = "Ваші атаки ближнього бою надають $109780s1 ухилення на наступні $109780d, накопичуючись до $109780u разів." },
    { en = "Poisons all enemies in an $A1 yard radius around the caster.  Victims of the poison suffer $s1 Nature damage every 5 sec for 45 sec.", ua = "Отруює всіх ворогів у радіусі $A1 ярдів навколо заклинача. Жертви отрути зазнають $s1 шкоди Природою кожні 5 сек протягом 45 сек." },
    { en = "Your harmful spells have a chance to create 1 to 3 Arcane Illusions of yourself that channel for 3 sec before unleashing Arcane Barrage at your target's location dealing up to ${$s1*1.1} Arcane damage to all enemies in the area.", ua = "Ваші шкідливі заклять мають шанс створити від 1 до 3 Чародійських Ілюзій вас самих, які каналізують 3 сек, а потім вивільняють Чародійський Залп на місці вашої цілі, завдаючи до ${$s1*1.1} шкоди Чародійством усім ворогам у цій зоні." },
    { en = "Restores $51351s1 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $51351s1 мани, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект може спрацьовувати не частіше ніж раз на 10 секунд." },
    { en = "Smite your foe for $s1 damage and restore $s4% of your mana. A nearby ally is healed for $s2% of the damage dealt. Deals $s3% extra damage against Demons.", ua = "Вражає вашого ворога, завдаючи $s1 шкоди й відновлюючи $s4% вашої мани. Союзник поруч зцілюється на $s2% завданої шкоди. Завдає $s3% додаткової шкоди демонам." },
    { en = "Chance on melee and ranged critical strike to increase your attack power by $127928s1 for $127928d.", ua = "Критичний удар у ближньому або дальньому бою має шанс підвищити вашу силу атаки на $127928s1 на $127928d." },
    { en = "Taking damage has a chance to call Xeri'tac's brood to your aid, attacking your foes and covering you in protective webbing which absorbs $s1 damage.", ua = "Отримана шкода має шанс прикликати виводок Ксері'така вам на допомогу: він атакує ваших ворогів і огортає вас захисним павутинням, що поглинає $s1 шкоди." },
    { en = "Taking damage has a high chance to grant you Gluttonous, stacking up to $334511u times.", ua = "Отримана шкода має високий шанс надати вам Ненажерливість, що накопичується до $334511u разів." },
    { en = "Each time one of your spells deals periodic damage, you have a chance to gain $71605s1 spell power for $71605d.", ua = "Щоразу, коли одне з ваших заклять завдає періодичної шкоди, ви маєте шанс отримати $71605s1 сили заклять на $71605d." },
    { en = "Become Oath-Bound to a nearby ally every $t1 sec.\n\n\n\nDirectly healing the ally fulfills the oath to grant you $s1 Intellect for $1240000d and shields your ally for $s2% of any overhealing done.", ua = "Кожні $t1 сек ви стаєте Зв'язаним Клятвою з союзником поруч.\n\n\n\nПряме зцілення цього союзника виконує клятву, надаючи вам $s1 інтелекту на $1240000d і захищаючи вашого союзника щитом на $s2% будь-якого надлишкового зцілення." },
    { en = "Each time you deal damage, you have a chance to do an additional $60203s1 Shadow damage.", ua = "Щоразу, коли ви завдаєте шкоди, ви маєте шанс завдати додатково $60203s1 шкоди Тінню." },
    { en = "Sometimes heals bearer of $33504s1 damage when damaging an enemy in melee.", ua = "Іноді зцілює носія на $33504s1, коли він завдає шкоди ворогові в ближньому бою." },
    { en = "Your damaging attacks and abilities have a chance to grant $128524s1 haste for $128524d.", ua = "Ваші атаки й здібності, що завдають шкоди, мають шанс надати $128524s1 швидкості на $128524d." },
    { en = "Increases Agility or Strength by $s3 for $d.", ua = "Підвищує спритність або силу на $s3 на $d." },
    { en = "Falling below $s2% health grants you a shield that absorbs ${$s1*(1+$@versadmg)} damage for $286342d. This effect may occur once every $288756d.", ua = "Падіння здоров'я нижче $s2% надає вам щит, що поглинає ${$s1*(1+$@versadmg)} шкоди на $286342d. Цей ефект може спрацьовувати раз на $288756d." },
    { en = "Grants Haste based on percentage of maximum health that is missing.", ua = "Надає швидкість залежно від відсотка втраченого максимального здоров'я." },
    { en = "Surround yourself with a phalanx of $N shields. Attacks against you destroy one shield, reducing the damage taken from the attack up to $311492s1-$311499s1. The amount reduced depends on the topmost card in the deck. Lasts $d.", ua = "Оточіть себе фалангою з $N щитів. Атаки проти вас знищують один щит, зменшуючи отриману від атаки шкоду на величину до $311492s1-$311499s1. Розмір зменшення залежить від верхньої карти в колоді. Триває $d." },
    { en = "Battle Shout grants you up to $58157s1 additional attack power.", ua = "Бойовий Клич надає вам до $58157s1 додаткової сили атаки." },
    { en = "Gain $s1 mana.", ua = "Отримайте $s1 мани." },
    { en = "Spikes sprout from you causing $s1 Nature damage to attackers when hit.  Lasts $d.", ua = "З вас проростають шипи, що завдають $s1 шкоди Природою нападникам, коли ті вас вражають. Триває $d." },
    { en = "Your attacks have a chance to grant you Frothing Rage for $278143d. When Frothing Rage reaches $278143u charges, your next attack will deal an additional $278148s1 Physical damage.", ua = "Ваші атаки мають шанс надати вам Скажену Лють на $278143d. Коли Скажена Лють досягає $278143u зарядів, ваша наступна атака завдасть додатково $278148s1 фізичної шкоди." },
    { en = "Your attacks have a chance to grant $165830s1 Critical Strike for $165830d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $165830s1 критичного удару на $165830d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Your melee and ranged attacks have a chance to cause the target to Bleed for ${$355087s1*$s2} over $355087d.", ua = "Ваші атаки ближнього й дальнього бою мають шанс змусити ціль кровоточити на ${$355087s1*$s2} протягом $355087d." },
    { en = "Your melee and ranged attacks have a chance to grant $117649s1 haste for $117649d.", ua = "Ваші атаки ближнього й дальнього бою мають шанс надати $117649s1 швидкості на $117649d." },
    { en = "Increases spell power by $s1, and decreases the magical resistances of your spell targets by $s2 for $d.", ua = "Підвищує силу заклять на $s1 і зменшує магічні опори цілей ваших заклять на $s2 на $d." },
    { en = "When you drop below $s2% health, the Light will heal you for ${$AP*$m1/100}, and deal ${$AP*$m1/100} Holy damage to nearby enemies. This cannot occur again for $185101d.", ua = "Коли ваше здоров'я падає нижче $s2%, Світло зцілить вас на ${$AP*$m1/100} і завдасть ${$AP*$m1/100} шкоди Святом ворогам поруч. Це не може повторитися протягом $185101d." },
    { en = "Your melee attacks have a chance to grant $120257s1 dodge for $120257d.", ua = "Ваші атаки ближнього бою мають шанс надати $120257s1 ухилення на $120257d." },
    { en = "Your ranged attacks and spells have a chance to launch a Homing Missile if your target is at least $s1 yds away, dealing up to $255629s2 Fire damage to all enemies within $255629A2 yds. Targets closer to the impact take more damage.", ua = "Ваші атаки дальнього бою та заклять мають шанс запустити Самонавідну Ракету, якщо ваша ціль перебуває щонайменше за $s1 ярдів, завдаючи до $255629s2 шкоди Вогнем усім ворогам у межах $255629A2 ярдів. Цілі, ближчі до місця влучання, зазнають більшої шкоди." },
    { en = "Your melee attacks have a chance to unleash 4 Shadow Waves that deal $s1 Shadow damage to enemies in their path. The waves travel 15 yards away from you, and then return.", ua = "Ваші атаки ближнього бою мають шанс вивільнити 4 Тіньові Хвилі, що завдають $s1 шкоди Тінню ворогам на своєму шляху. Хвилі рухаються на 15 ярдів від вас, а потім повертаються." },
    { en = "Your healing spells and abilities have a high chance to fill the chalice with Hope, drop by drop, up to $1259994u times.", ua = "Ваші зцілювальні заклять і здібності мають високий шанс наповнювати чашу Надією, краплина за краплиною, до $1259994u разів." },
    { en = "Your damaging abilities have a chance to launch an oblivion spear at your target, inflicting $295393s1 Shadow damage. On impact, the spear will shatter towards you. You will be silenced for $295395d if struck.", ua = "Ваші здібності, що завдають шкоди, мають шанс метнути спис забуття у вашу ціль, завдаючи $295393s1 шкоди Тінню. Під час влучання спис розколюється у ваш бік. Якщо він вас вразить, вас охопить німота на $295395d." },
    { en = "Summons the Felsteel Boar to fight for you for 30 seconds.", ua = "Прикликає Скверносталевого Вепра, який битиметься за вас протягом 30 секунд." },
    { en = "Activates your Mithril Mechanical Dragonling to fight for you for $d.", ua = "Активує вашого Мітрилового Механічного Драконця, що б'ється за вас протягом $d." },
    { en = "Upon entering combat, and every $472195t sec, gain either $@spellname472185 or $@spellname472184 for 30 sec.\n\n\n\n$@spellicon472184$@spellname472184\n\n$@spelldesc472184\n\n\n\n$@spellicon472185$@spellname472185\n\n$@spelldesc472185", ua = "На початку бою та кожні $472195t сек ви отримуєте або «$@spellname472185», або «$@spellname472184» на 30 сек.\n\n\n\n$@spellicon472184$@spellname472184\n\n$@spelldesc472184\n\n\n\n$@spellicon472185$@spellname472185\n\n$@spelldesc472185" },
    { en = "Giant spikes emerge from your armor dealing $s1 Physical damage split between enemies within $a1 yds and continue to deal $351872s1 Physical damage to attackers that hit you until they deal $351872s2 total damage.", ua = "З вашого обладунку проростають велетенські шипи, завдаючи $s1 фізичної шкоди, поділеної між ворогами в межах $a1 ярд., і продовжують завдавати $351872s1 фізичної шкоди нападникам, що вас б'ють, доки не завдадуть загалом $351872s2 шкоди." },
    { en = "Shrinks the target reducing their attack power by $13003s1.  That's what it usually does anyway.....", ua = "Зменшує ціль, послаблюючи її силу атаки на $13003s1. Принаймні зазвичай воно так працює....." },
    { en = "Unleash a gout of flame, dealing $129116s1 fire damage to targets in a 10 yard cone in front of the caster every 0.5 sec for 4 sec.\n\n\n\nMay walk while casting.", ua = "Випускає струмінь полум'я, завдаючи $129116s1 шкоди вогнем цілям у 10-ярдовому конусі перед заклинателем кожні 0.5 сек. протягом 4 сек.\n\n\n\nМожна рухатися під час застосування." },
    { en = "Your damaging melee attacks have a chance to cause $355068s1 Physical Damage to creatures in a cone up to $355068a1 yds.", ua = "Ваші шкідливі атаки ближнього бою мають шанс завдати $355068s1 фізичної шкоди істотам у конусі завдовжки до $355068a1 ярд." },
    { en = "Your healing and damage periodic spells grant $90953s1 spell power each time they heal or deal damage.   Lasts $90953d, stacking up to $90953u times.", ua = "Ваші зціляльні та шкідливі періодичні закляття надають $90953s1 сили заклять щоразу, коли зціляють або завдають шкоди. Триває $90953d, накопичуючись до $90953u разів." },
    { en = "Study the tome, learning the weakness of your targeted enemy. Your damaging abilities have a very high chance to deal $357169s1 additional Shadow damage to your studied foe.\n\n\n\nStudying a new enemy removes the benefit of any prior studies.", ua = "Вивчіть фоліант, дізнаючись слабкість обраної цілі. Ваші шкідливі здібності мають дуже високий шанс завдати $357169s1 додаткової шкоди тінню вивченому ворогові.\n\n\n\nВивчення нового ворога знімає перевагу від попередніх вивчень." },
    { en = "Your excessive healing attracts nearby shadow energy to your party, storing up to $s1 healing and restoring the target's health when they receive damage.", ua = "Ваше надмірне зцілення притягує до вашої групи довколишню тіньову енергію, накопичуючи до $s1 зцілення та відновлюючи здоров'я цілі, коли вона зазнає шкоди." },
    { en = "Your attacks have a chance to trigger Dark Intensity, increasing your Strength by $278379s1 every $278379t2 sec. Lasts $278379d.", ua = "Ваші атаки мають шанс активувати Темну Інтенсивність, підвищуючи вашу силу на $278379s1 кожні $278379t2 сек. Триває $278379d." },
    { en = "Your damaging spells have a chance to grant $75466s1 spell power for $75466d.", ua = "Ваші шкідливі закляття мають шанс надати $75466s1 сили заклять на $75466d." },
    { en = "Channel to store ${-1*$s1} mana in the Ingenious Mana Battery, up to a max of $s2.", ua = "Каналізуйте, щоб зберегти ${-1*$s1} мани в Хитромудрій Батареї Мани, до максимуму $s2." },
    { en = "Restores $51360s1 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $51360s1 здоров'я, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше, ніж раз на 10 секунд." },
    { en = "Call upon the bark to grant you a shield which absorbs the next ${$<rolemult>*$s1} damage taken for $d. When the shield expires, it bursts outward with potent natural magic, dealing ${$<rolemult>*$s2} Nature damage split among all nearby foes.", ua = "Закликає кору, щоб надати вам щит, який поглинає наступні ${$<rolemult>*$s1} отриманої шкоди протягом $d. Коли щит спливає, він вибухає назовні потужною природною магією, завдаючи ${$<rolemult>*$s2} шкоди природою, поділеної між усіма довколишніми ворогами." },
    { en = "Your attacks have a chance to grant $176937s1 Haste for $176937d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176937s1 швидкості на $176937d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to grant $148897s1 Intellect for $148897d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати $148897s1 інтелекту на $148897d. ($h% шанс, ${$proccooldown} сек. перезарядки)" },
    { en = "The Plume's gloom grants you $1265809s1 Critical Strike, waning over ${$1265808t2*$1265808u} sec before returning to full darkness. The Plume's power also regenerates while out of combat.", ua = "Морок Пера дарує тобі $1265809s1 критичного удару, що згасає протягом ${$1265808t2*$1265808u} с, перш ніж повернутися до повної темряви. Сила Пера також відновлюється поза боєм." },
    { en = "Chance on melee and ranged critical strike to increase your attack power by $101287s1 for $101287d.", ua = "Шанс при критичному ударі в ближньому чи дальньому бою підвищити вашу силу атаки на $101287s1 на $101287d." },
    { en = "Your spells and abilities have a chance to awaken the unbound essence of Aln, increasing your $pri by ${$1255460s1*$1255460u}. This power, drawn from half-formed dreams and mists, fades with each ability used or after $1255460d.", ua = "Ваші чари та здібності мають шанс пробудити невпокорену сутність Ална, підвищуючи вашу $pri на ${$1255460s1*$1255460u}. Ця сила, зіткана з напівсформованих снів і туманів, слабшає з кожною використаною здібністю або через $1255460d." },
    { en = "Your melee attacks have a chance to increase your attack power by $92108s1 for $92108d.", ua = "Ваші атаки ближнього бою мають шанс підвищити вашу силу атаки на $92108s1 на $92108d." },
    { en = "Increases your dodge by $s2, but decreases your melee and ranged attack power by $s1.  Effect lasts for $d.", ua = "Підвищує ваше ухилення на $s2, але знижує вашу силу атаки в ближньому та дальньому бою на $s1. Ефект триває $d." },
    { en = "Your healing spells have a chance to grant $91184s1 Versatility for $91184d.", ua = "Ваші зціляльні закляття мають шанс надати $91184s1 універсальності на $91184d." },
    { en = "Surround your target ally with Lightblossoms, healing them for ${$s1*($d/$t1)} over $d.\n\n\n\nIf their health falls below $s2%, the Lightblossoms fully bloom in radiant light, instantly healing them for $1285918s1.", ua = "Оточує вашого союзника-ціль Світлоцвітами, зціляючи його на ${$s1*($d/$t1)} протягом $d.\n\n\n\nЯкщо його здоров'я падає нижче $s2%, Світлоцвіти повністю розквітають сяйливим світлом, миттєво зціляючи його на $1285918s1." },
    { en = "Your harmful spells and abilities have a low chance to launch an arcane orb at your target. The size and power of the missile can vary dealing up to ${$s1*1.4} Arcane damage.", ua = "Ваші шкідливі закляття та здібності мають низький шанс запустити у вашу ціль чародійну сферу. Розмір і потужність снаряда можуть різнитися, завдаючи до ${$s1*1.4} чародійної шкоди." },
    { en = "Your spells have a chance to jostle the spoils, reordering the treasure within.", ua = "Ваші закляття мають шанс струсити здобич, перевпорядкувавши скарби всередині." },
    { en = "Each time one of your spells deals periodic damage, there is a chance $60488s1 additional damage will be dealt.", ua = "Щоразу, коли одне з ваших заклять завдає періодичної шкоди, є шанс, що буде завдано $60488s1 додаткової шкоди." },
    { en = "Your attacks have a chance to grant you $278225s1 Critical Strike for $278225d.", ua = "Ваші атаки мають шанс надати вам $278225s1 критичного удару на $278225d." },
    { en = "Increases Fire Resistance by 20 and deals 20 Fire damage to anyone who strikes you with a melee attack for $d.", ua = "Підвищує опір вогню на 20 і завдає 20 шкоди вогнем кожному, хто вдарить вас атакою ближнього бою, протягом $d." },
    { en = "Your attacks and abilities have a chance to grant you ephemeral dragon wings, increasing your Haste by $313571s1 and your Speed by $313571s2 for $313571d.", ua = "Ваші атаки та здібності мають шанс надати вам ефемерні драконячі крила, підвищуючи вашу швидкість на $313571s1 і ваш темп на $313571s2 на $313571d." },
    { en = "Spells and abilities have a chance to unearth a Colourful Fungal Friend to heal allies for $s2, grant you $s3 mana, or deal ${$s4*($438685d/$438685t)} Nature damage over $438685d to a nearby enemy.", ua = "Закляття та здібності мають шанс відкопати Барвистого Грибного Друга, який зцілить союзників на $s2, надасть вам $s3 мани або завдасть ${$s4*($438685d/$438685t)} шкоди природою протягом $438685d довколишньому ворогові." },
    { en = "Your spells have a chance to increase your Haste by $384165s1 and movement speed by $384165s2% for $384165d.", ua = "Ваші закляття мають шанс підвищити вашу швидкість на $384165s1 і швидкість пересування на $384165s2% на $384165d." },
    { en = "Raise the remains of a fallen ally as a skeletal warrior for $s1 sec.", ua = "Підіймає рештки полеглого союзника як кістяного воїна на $s1 сек." },
    { en = "Your spells have a chance to grant you $278862s1 Intellect for $278862d.", ua = "Ваші закляття мають шанс надати вам $278862s1 інтелекту на $278862d." },
    { en = "Increases your Strength by $s1 for $d1.", ua = "Підвищує вашу силу на $s1 на $d1." },
    { en = "Your spells and attacks in each form have a chance to grant you a blessing for $37340d.", ua = "Ваші закляття та атаки в будь-якій формі мають шанс надати вам благословення на $37340d." },
    { en = "You are one of the devout. Up to $s2 allies within $a yd of you gain $s1 health every $t sec.", ua = "Ви — один із відданих. До $s2 союзників у межах $a ярд. від вас отримують $s1 здоров'я кожні $t сек." },
    { en = "Your damaging and healing spell casts grant you $281791s1 of a secondary stat for $281791d, based on the spell. These effects stack up to $281791u times.", ua = "Застосування ваших шкідливих і зціляльних заклять надає вам $281791s1 вторинної характеристики на $281791d, залежно від закляття. Ці ефекти накопичуються до $281791u разів." },
    { en = "|cnGOLD_FONT_COLOR:Your companion has a chance during combat, via casting spells, abilities, or from slaying enemies to gain a Sanctum's Blessing. Each blessing grants $s1% increased healing and damage.\n\n\n\nUpon reaching $s6 blessings, your companion becomes a Sanctum's Champion, converting $s2% of their current health into an absorb shield that lasts for $1265780d, or until depleted. While the shield holds, increase the damage and healing conferred by Sanctum's Blessings. Upon expiration, blessings are removed.\n\n\n\nSlaying an Elite enemy grants $s4 Sanctum's Blessings, while normal foes yield $s3.|r", ua = "|cnGOLD_FONT_COLOR:Ваш супутник має шанс під час бою — через застосування заклять, здібностей чи вбивство ворогів — здобути Благословення Святилища. Кожне благословення дає $s1% до зцілення та шкоди.\n\n\n\nДосягнувши $s6 благословень, ваш супутник стає Чемпіоном Святилища, перетворюючи $s2% свого поточного здоров'я на поглинальний щит, що триває $1265780d або доки не вичерпається. Поки щит тримається, шкода та зцілення від Благословень Святилища підвищені. Зі спливанням благословення зникають.\n\n\n\nВбивство елітного ворога дає $s4 Благословення Святилища, а звичайні вороги — $s3.|r" },
    { en = "Grants $96962s1 mastery for $96962d each time you deal periodic spell damage, stacking up to $96962u times.", ua = "Дає $96962s1 майстерності на $96962d щоразу, коли ви завдаєте періодичної магічної шкоди. Накопичується до $96962u разів." },
    { en = "Release a toll of holy light upon the target, inflicting ${$<rolemult>*$450641s2} Holy damage. The next $450641s3 allies to attack the target will receive the Blessing of Mereldar, increasing their Versatility by $450641s1 for $450551d.", ua = "Здіймає на ціль дзвін святого світла, завдаючи ${$<rolemult>*$450641s2} шкоди святом. Наступні $450641s3 союзників, які атакують ціль, отримають Благословення Мерелдар, що підвищує їхню універсальність на $450641s1 на $450551d." },
    { en = "Your spells have a chance to trigger Molten Metal for $177081d.  While Molten Metal is active, you gain $177081s1 Mastery every $177081t1 sec, stacking up to $177083u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші закляття мають шанс активувати Розплавлений Метал на $177081d. Поки Розплавлений Метал активний, ви отримуєте $177081s1 майстерності кожні $177081t1 сек, накопичуючись до $177083u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Call forth an Automa Medic which restores ${$367835s1*$d} mana to you over $d before expiring.", ua = "Прикликає Автома-Медика, який відновлює вам ${$367835s1*$d} мани протягом $d, перш ніж зникнути." },
    { en = "Increases Versatility by $s1 for $d.", ua = "Підвищує універсальність на $s1 на $d." },
    { en = "Hook an enemy who is within $r yds, causing them to bleed for ${$<rolemult>*$s1} Physical damage every $t1 sec and reducing their movement speed by $s2%. Lasts $d, or until they move more than $s3 yds away from you.", ua = "Чіпляє гаком ворога в межах $r ярдів, змушуючи його кровоточити, завдаючи ${$<rolemult>*$s1} фізичної шкоди кожні $t1 сек і знижуючи його швидкість пересування на $s2%. Триває $d або доки він не відійде більш ніж на $s3 ярдів від вас." },
    { en = "Summons a Phantom Boar to fight for you for 30 seconds.", ua = "Прикликає Примарного Вепра, який б'ється за вас протягом 30 секунд." },
    { en = "Increases Haste by $s1 for $d.", ua = "Підвищує швидкість на $s1 на $d." },
    { en = "Each time you deal periodic damage you have a chance to gain $126577s1 Intellect for $126577d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ви завдаєте періодичної шкоди, ви маєте шанс отримати $126577s1 інтелекту на $126577d. ($h% шансу, ${$proccooldown} сек відновлення)" },
    { en = "Whenever you kill an enemy that rewards experience, you gain Bloodseeker's Fury, granting you $128897s1 Agility for $128897d.  Stacks up to 10 times.", ua = "Щоразу, коли ви вбиваєте ворога, що дає досвід, ви отримуєте Лють Шукача Крові, яка дає вам $128897s1 спритності на $128897d. Накопичується до 10 разів." },
    { en = "Your harmful spells have a chance to grant $91007s1 spell power for $91007d.", ua = "Ваші ворожі закляття мають шанс дати $91007s1 сили заклять на $91007d." },
    { en = "Summons the Khorium Boar to fight for you for 30 sec.", ua = "Прикликає Хоріумного Вепра, який б'ється за вас протягом 30 сек." },
    { en = "Your abilities have a chance to grant you $268522s1 Mastery for $268522d.", ua = "Ваші здібності мають шанс дати вам $268522s1 майстерності на $268522d." },
    { en = "Your attacks have a chance to grant $146046s1 Intellect for $146046d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс дати $146046s1 інтелекту на $146046d. ($h% шансу, ${$proccooldown} сек відновлення)" },
    { en = "Your melee attacks have a chance to grant $118614s1 dodge for $118614d.", ua = "Ваші атаки ближнього бою мають шанс дати $118614s1 ухилення на $118614d." },
    { en = "When you deal damage you have a chance to gain $109744s1 critical strike for $109744d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109744s1 критичного удару на $109744d." },
    { en = "Your attacks have a chance to burn dealing $167334s1 damage every 2 seconds over $167334d.", ua = "Ваші атаки мають шанс підпалити, завдаючи $167334s1 шкоди кожні 2 секунди протягом $167334d." },
    { en = "Taking damage has a chance for the shroud's enchantments to enhance your prowess, granting $s1 Versatility for $1231221d.", ua = "Отримання шкоди має шанс активувати чари покрову, що підсилюють вашу майстерність, даючи $s1 універсальності на $1231221d." },
    { en = "Summons a Hammer of Expertise.", ua = "Прикликає Молот Вправності." },
    { en = "Restores $s1% of your maximum mana whenever you kill a target that yields experience or honor.", ua = "Відновлює $s1% вашої максимальної мани щоразу, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Your abilities have a chance to crystallize your target, inflicting ${$s2*($385903d/($385903t1+1))*(1+$@versadmg)} Arcane damage over $385903d. If the target dies while crystallized they explode, inflicting $s3 Arcane damage split between all nearby enemies.", ua = "Ваші здібності мають шанс кристалізувати ціль, завдаючи ${$s2*($385903d/($385903t1+1))*(1+$@versadmg)} таємничої шкоди протягом $385903d. Якщо ціль помирає, поки вона кристалізована, вона вибухає, завдаючи $s3 таємничої шкоди, розподіленої між усіма ворогами поблизу." },
    { en = "Your melee critical strikes have a chance to grant $91368s1 Strength for $91368d.", ua = "Ваші критичні удари ближнього бою мають шанс дати $91368s1 сили на $91368d." },
    { en = "Your attacks have a chance to drain $s1 health from your target and heal you for $s2% of the health drained.", ua = "Ваші атаки мають шанс висмоктати $s1 здоров'я з вашої цілі та зцілити вас на $s2% висмоктаного здоров'я." },
    { en = "While in Ny'alotha and based on your Corruption Resistance, the amount of damage reduction you receive is further reduced by up to $s1%.", ua = "Поки ви в Ньялоті та залежно від вашого опору псуванню, отримуване вами зниження шкоди додатково зменшується аж до $s1%." },
    { en = "Become the Skulking Predator for $d, gaining $s1 Speed and pouncing on the next enemy to come within $s2 yds, dealing $345113s2 Physical damage.", ua = "Станьте Скрадливим Хижаком на $d, отримавши $s1 швидкості, і стрибніть на наступного ворога, який наблизиться на $s2 ярдів, завдаючи $345113s2 фізичної шкоди." },
    { en = "When you deal damage you have a chance to gain $85022s1 Agility for $85022d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $85022s1 спритності на $85022d." },
    { en = "Your harmful spells have a chance to increase your spell power by $127923s1 for $127923d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші ворожі закляття мають шанс підвищити вашу силу заклять на $127923s1 на $127923d. ($h% шансу, ${$proccooldown} сек відновлення)" },
    { en = "Increases Stamina by $276204s1-$276211s1, and heal for $276204s2-$276211s2 whenever the deck is shuffled. The amount of Stamina and healing depends on the topmost card in the deck.", ua = "Підвищує витривалість на $276204s1-$276211s1 та зцілює на $276204s2-$276211s2 щоразу, коли колоду перетасовано. Кількість витривалості та зцілення залежить від верхньої карти в колоді." },
    { en = "Your healing spells have a chance to increase your Intellect by $65003s1 for $65003d.", ua = "Ваші зцілювальні закляття мають шанс підвищити ваш інтелект на $65003s1 на $65003d." },
    { en = "Your melee and ranged attacks have a chance to plant Fire Mines at the enemy's feet. Fire Mines detonate after $253320d, inflicting $253321s1 Fire damage to all enemies within $253321A1 yds.", ua = "Ваші атаки ближнього бою та дальнього бою мають шанс закласти Вогняні Міни біля ніг ворога. Вогняні Міни детонують через $253320d, завдаючи $253321s1 шкоди вогнем усім ворогам у межах $253321A1 ярдів." },
    { en = "Grants $96980s1 critical strike for $96980d each time you deal a melee critical strike, stacking up to $96980u times.", ua = "Дає $96980s1 критичного удару на $96980d щоразу, коли ви завдаєте критичного удару ближнього бою. Накопичується до $96980u разів." },
    { en = "Your melee and ranged attacks have a chance to grant $116724s1 haste for $116724d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс дати $116724s1 швидкості на $116724d." },
    { en = "Your attacks have a chance to summon a Firefury Spirit to fight with you for $131411d.", ua = "Ваші атаки мають шанс прикликати Дух Вогняної Люті, який б'ється поряд з вами протягом $131411d." },
    { en = "Consume all stored energy cores to send a surge of restorative energy through you, instantly healing you for $1214704s1, with an additional $1214704s2 healing over $1214704s4 seconds for each core consumed.", ua = "Поглинає всі накопичені ядра енергії, щоб пустити крізь вас сплеск відновлювальної енергії, миттєво зцілюючи вас на $1214704s1, з додатковими $1214704s2 зцілення протягом $1214704s4 секунд за кожне поглинуте ядро." },
    { en = "Obliterate deals $s1% additional damage as Frost damage.", ua = "Знищення завдає $s1% додаткової шкоди як шкоду від Льоду." },
    { en = "Reduces your threat to enemy targets within $A1 yards, making them less likely to attack you.", ua = "Зменшує вашу загрозу для ворожих цілей у межах $A1 ярдів, через що вони рідше нападатимуть на вас." },
    { en = "Increases attack power by $s1 when fighting Undead.  It also allows the acquisition of Scourgestones on behalf of the Argent Dawn.", ua = "Підвищує силу атаки на $s1 у бою з Нежиттю. Також дозволяє збирати Каменя Покари для Срібного Світанку." },
    { en = "Release the Doom's Wake increasing your Agility by $s1 every $t2 sec for $s3 sec and then persisting for an additional ${$d-$s3} sec.", ua = "Вивільняє Поступ Прокляття, підвищуючи вашу спритність на $s1 кожні $t2 сек протягом $s3 сек, а потім ефект триває ще додатково ${$d-$s3} сек." },
    { en = "Your melee and ranged attacks have a chance to grant you $96911s1 haste for $96911d.", ua = "Ваші ближні та далекобійні атаки мають шанс надати вам $96911s1 швидкості на $96911d." },
    { en = "When you deal damage you have a chance to gain $107986s1 mastery for $107986d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $107986s1 майстерності на $107986d." },
    { en = "Invoke an echo of Fearbreaker's might, splitting the ground beneath your current target and dealing ${$<rolemult>*$452867s}  Nature damage split between all enemies near them.", ua = "Викликає відлуння могутності Сокрушителя Страху, розколюючи землю під вашою поточною ціллю та завдаючи ${$<rolemult>*$452867s} шкоди від природи, розподіленої між усіма ворогами поруч із нею." },
    { en = "Your harmful spells have a chance to increase your Haste by $65004s1 for $65004d.", ua = "Ваші шкідливі заклинання мають шанс підвищити вашу швидкість на $65004s1 на $65004d." },
    { en = "Release the Lion's Guile increasing your Agility by $s1 every $t2 sec for $s3 sec and then persisting for an additional ${$d-$s3} sec.", ua = "Вивільняє Хитрість Лева, підвищуючи вашу спритність на $s1 кожні $t2 сек протягом $s3 сек, а потім ефект триває ще додатково ${$d-$s3} сек." },
    { en = "The shard draws in remnant energy from defeated enemies, increasing your Mastery by $449792s1 for $449792d, up to $449792u times.", ua = "Уламок вбирає залишкову енергію переможених ворогів, підвищуючи вашу майстерність на $449792s1 на $449792d, до $449792u разів." },
    { en = "Increases your spell power by $s1 for $d1.", ua = "Підвищує вашу силу заклять на $s1 на $d1." },
    { en = "Drain the target's life force, inflicting $o1 Shadow damage to the enemy and restoring ${$313162s1*(($d/$t)+1.5)} mana to yourself over $d.", ua = "Висмоктує життєву силу цілі, завдаючи ворогові $o1 шкоди від Тіні та відновлюючи вам ${$313162s1*(($d/$t)+1.5)} мани протягом $d." },
    { en = "Your harmful spells and ranged abilities have a chance to call forth Loa aspects to bombard your target three times, each time dealing ${$<rolemult>*$s1} Physical damage split between all nearby enemies.", ua = "Ваші шкідливі заклинання та далекобійні здібності мають шанс прикликати аспекти Лоа, що тричі бомбардують вашу ціль, щоразу завдаючи ${$<rolemult>*$s1} фізичної шкоди, розподіленої між усіма ворогами поруч." },
    { en = "Each time you deal melee or ranged damage to an opponent, you gain $60314s1 attack power for the next 10 sec, stacking up to 20 times.", ua = "Щоразу, коли ви завдаєте ближньої або далекобійної шкоди супротивнику, ви отримуєте $60314s1 сили атаки на наступні 10 сек, накопичуючись до 20 разів." },
    { en = "Taking damage has a chance to increase your Versatility by $256816s1 for $256816d.\n\n\n\n|cFFFFFFFFAggramar's Fortitude|r\n\nWhen empowered by the Pantheon, your maximum health is increased by $256831s1 for $256831d, and you are healed for $256831s2.", ua = "Отримання шкоди має шанс підвищити вашу універсальність на $256816s1 на $256816d.\n\n\n\n|cFFFFFFFFСтійкість Аґрамара|r\n\nКоли вас наснажує Пантеон, ваше максимальне здоров'я підвищується на $256831s1 на $256831d, і вас зцілюється на $256831s2." },
    { en = "Your spells and abilities have a chance to grant you $268520s1 Primary stat for $268520d.", ua = "Ваші заклинання та здібності мають шанс надати вам $268520s1 основної характеристики на $268520d." },
    { en = "Each time you cast a spell, there is chance you will gain up to $37656s1 Versatility for $37656d.", ua = "Щоразу, коли ви накладаєте заклинання, є шанс, що ви отримаєте до $37656s1 універсальності на $37656d." },
    { en = "Your harmful spells and ranged abilities critical strikes have a high chance to grant you Arcane Hunter up to 5 times, increasing your Critical Strike rating by $s1 per stack for $1245376d1.", ua = "Критичні удари ваших шкідливих заклинань та далекобійних здібностей мають високий шанс надати вам Чародійського Мисливця до 5 разів, підвищуючи ваш рейтинг критичного удару на $s1 за кожен заряд на $1245376d1." },
    { en = "Taking damage has a high chance to brand your assailant dealing $s1 Holy Fire damage and healing you for $s2% of damage dealt.", ua = "Отримання шкоди має високий шанс затаврувати вашого нападника, завдаючи $s1 шкоди від Священного Вогню та зцілюючи вас на $s2% завданої шкоди." },
    { en = "When you use harmful spells or abilities, there is a chance you also take a sip of the energy drink, increasing your Mastery by $s1 for $1216650d. Gain an additional $s2 Mastery if you are below $s3% health.", ua = "Коли ви використовуєте шкідливі заклинання або здібності, є шанс, що ви також зробите ковток енергетичного напою, підвищуючи вашу майстерність на $s1 на $1216650d. Отримуєте додатково $s2 майстерності, якщо ваше здоров'я нижче $s3%." },
    { en = "Summons a Fallen Footman to your side.", ua = "Прикликає до вас полеглого піхотинця." },
    { en = "Your melee attacks have a chance to deal an additional $242218s1 Fire damage. The critical strike chance of this damage is increased by $246654s1% for each ally within $246654a1 yds who bears this item.", ua = "Ваші ближні атаки мають шанс завдати додатково $242218s1 шкоди від Вогню. Шанс критичного удару цієї шкоди підвищується на $246654s1% за кожного союзника в межах $246654a1 ярдів, який має цей предмет." },
    { en = "Your spells have a chance to grant you Overcharge for $d, increasing your Intellect by $s1.", ua = "Ваші закляття мають шанс дати вам Перенавантаження на $d, збільшуючи ваш Інтелект на $s1." },
    { en = "When you deal damage you have a chance to gain $100322s1 Critical Strike for $100322d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $100322s1 критичного удару на $100322d." },
    { en = "Increases spell power against Undead by $s1.  It also allows the acquisition of Scourgestones on behalf of the Argent Dawn.", ua = "Підвищує силу заклять проти Нежиті на $s1. Також дозволяє збирати Каменя Покари для Срібного Світанку." },
    { en = "Your abilities have a chance to ignite the ember, dealing $409067o2 Shadowflame damage to yourself over $409067d and increasing your Haste by $409067s1.", ua = "Ваші здібності мають шанс підпалити жарину, завдаючи вам $409067o2 шкоди від тіньового полум'я протягом $409067d та підвищуючи вашу швидкість на $409067s1." },
    { en = "Your healing spells have a chance to grant $92332s1 Versatility for $92332d.", ua = "Ваші зцілювальні заклинання мають шанс надати $92332s1 універсальності на $92332d." },
    { en = "Your healing spells have a chance to restore $64739s1 mana.", ua = "Ваші зцілювальні заклинання мають шанс відновити $64739s1 мани." },
    { en = "Resonate with the power of your sworn dragonflight, granting you $s1 secondary stat. Allies sworn to a different dragonflight gain $s2 secondary stat from your Resonance. You may only benefit from one Resonance per Flight.", ua = "Резонує з силою зграї драконів, якій ви присяглися, надаючи вам $s1 вторинної характеристики. Союзники, присяглі іншій зграї драконів, отримують $s2 вторинної характеристики від вашого Резонансу. Ви можете користуватися лише одним Резонансом на зграю." },
    { en = "Throw a Magma Serpent Lure at the target location. After $408913s2 seconds a magma serpent emerges, dealing ${($408913s3/$408913s2)*$408913s1} Fire damage over $408913s3 sec split between all enemies.", ua = "Кидає Принаду Магмового Змія у вказане місце. За $408913s2 секунд з'являється магмовий змій, завдаючи ${($408913s3/$408913s2)*$408913s1} шкоди від Вогню протягом $408913s3 сек, розподіленої між усіма ворогами." },
    { en = "Your damaging and healing spells have a chance to increase your spell power by $60479s1 for $60479d1.", ua = "Ваші шкідливі та зцілювальні заклинання мають шанс підвищити вашу силу заклять на $60479s1 на $60479d1." },
    { en = "Your ranged attacks and spells have a chance to create a Tormenting Cyclone at the target's location for $221857d that deals $s1 Shadow damage every sec.", ua = "Ваші далекобійні атаки та заклинання мають шанс створити Мученицький Циклон у місці цілі на $221857d, що завдає $s1 шкоди від Тіні щосекунди." },
    { en = "Increases armor by $s1, and heals $23781s1 damage every time you take ranged or melee damage for $d.", ua = "Підвищує броню на $s1 та зцілює $23781s1 шкоди щоразу, коли ви отримуєте далекобійну або ближню шкоду, протягом $d." },
    { en = "Your harmful spells have a high chance to call cosmic shards from the heavens to slice your target and one nearby enemy for ${$s1*$<rolemult>} Cosmic damage.\n\n\n\nIf either enemy is below $s3% health, gain $s2 Haste for $1264337d as you speed them to their fate.", ua = "Ваші шкідливі заклинання мають високий шанс прикликати космічні уламки з небес, що розсікають вашу ціль та одного ворога поруч на ${$s1*$<rolemult>} космічної шкоди.\n\n\n\nЯкщо будь-який із ворогів має здоров'я нижче $s3%, ви отримуєте $s2 швидкості на $1264337d, спрямовуючи його назустріч долі." },
    { en = "Your melee and ranged attacks have a chance to grant $118754s1 mastery for $118754d.", ua = "Ваші ближні та далекобійні атаки мають шанс надати $118754s1 майстерності на $118754d." },
    { en = "Fire a powerful rocket at the enemy that does $s1 damage and stuns them for $s2 sec.    This thing has quite a kick though...", ua = "Випускає у ворога потужну ракету, що завдає $s1 шкоди та оглушує його на $s2 сек. Щоправда, у цієї штуки чималенька віддача..." },
    { en = "Spells and abilities have a chance to bathe the target in moonlight, dealing $s1 Arcane damage to an enemy or restoring $s2 health to an ally.", ua = "Закляття та здібності мають шанс огорнути ціль місячним сяйвом, завдаючи $s1 шкоди від чарів ворогові або відновлюючи $s2 здоров'я союзникові." },
    { en = "When your attacks critical strike your target you have a chance to gain $126489s1 Agility for $126489d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ваші атаки завдають критичного удару по цілі, ви маєте шанс отримати $126489s1 спритності на $126489d. ($h% шанс, ${$proccooldown} сек відновлення)" },
    { en = "Your ranged attacks and spells have a chance to launch a ball of venom that deals up to $215405s1 Nature damage, based on your distance from the target (maximum damage at 20 yards).", ua = "Ваші дальні атаки та закляття мають шанс випустити кулю отрути, що завдає до $215405s1 шкоди від сил природи залежно від вашої відстані до цілі (максимальна шкода на 20 ярдах)." },
    { en = "Reduce all damage taken by $s2% for $d, until you have prevented ${$s1*(1+$@versadmg)} damage.", ua = "Зменшує всю отримувану шкоду на $s2% на $d, доки ви не запобіжите ${$s1*(1+$@versadmg)} шкоди." },
    { en = "Increases your melee and ranged attack power by $s1.  Effect lasts for $d.", ua = "Підвищує вашу силу ближньої та дальньої атаки на $s1. Ефект триває $d." },
    { en = "Your abilities have a chance to stir the sac, releasing an egg which grants you $s1 $pri. Each egg hatches after $452146d, and the new brood attacks your next target, inflicting ${$<rolemult>*$s2*$452229d/$452229t1} Nature damage over $452229d.", ua = "Ваші здібності мають шанс розворушити мішок, вивільняючи яйце, яке надає вам $s1 $pri. Кожне яйце вилуплюється через $452146d, і новий виводок атакує вашу наступну ціль, завдаючи ${$<rolemult>*$s2*$452229d/$452229t1} шкоди Природи протягом $452229d." },
    { en = "When your attacks hit you have a chance to trigger Re-Origination.  Re-Origination converts the lower two values of your Critical Strike, Haste, and Mastery into twice as much of the highest of those three attributes for $139120d.  (Approximately ${$procrppm}.2 procs per minute, ${$proccooldown} sec cooldown)", ua = "Коли ваші атаки влучають, ви маєте шанс активувати Перетворення. Перетворення обертає два менших показники з-поміж вашого критичного удару, швидкості та майстерності на удвічі більший показник найвищого з цих трьох атрибутів на $139120d. (Приблизно ${$procrppm}.2 спрацювань за хвилину, ${$proccooldown} сек відновлення)" },
    { en = "Entering combat summons an orb of dark power to assist you.", ua = "Вхід у бій прикликає кулю темної сили на допомогу вам." },
    { en = "Your attacks have a chance to grant you $126582s1 Strength for $126582d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $126582s1 сили на $126582d. ($h% шанс, ${$proccooldown} сек відновлення)" },
    { en = "Feed on seven allies or enemies within $A yards, devouring up to $s1 health from each. You are healed for $M2% of damage dealt.", ua = "Живиться сімома союзниками чи ворогами в межах $A ярдів, поглинаючи до $s1 здоров'я з кожного. Ви зцілюєтеся на $M2% завданої шкоди." },
    { en = "Each time you deal melee or ranged damage to an opponent, you gain $39439s1 attack power for the next 10 sec., stacking up to 20 times.  Each time you land a harmful spell on an opponent, you gain $39441s1 spell power for the next 10 sec., stacking up to 10 times.", ua = "Щоразу, коли ви завдаєте ближньої або дальньої шкоди супротивникові, ви отримуєте $39439s1 сили атаки на наступні 10 сек, до 20 накопичень. Щоразу, коли ви влучаєте по супротивникові шкідливим заклять, ви отримуєте $39441s1 сили заклять на наступні 10 сек, до 10 накопичень." },
    { en = "Create a Flame Gale at an enemy's location, dealing ${$230215s2*8} Fire damage over $230213d. If Flame Gale strikes an enemy affected by Thunder Ritual, Flame Gale's damage is increased by $230213s3%, and its radius by $230213s4%.", ua = "Створює Полум'яний Шквал на місці ворога, завдаючи ${$230215s2*8} шкоди від вогню протягом $230213d. Якщо Полум'яний Шквал влучає по ворогові під дією Грозового Ритуалу, шкода Полум'яного Шквалу зростає на $230213s3%, а його радіус — на $230213s4%." },
    { en = "Plant a blessed banner of the Argent Dawn, consecrating the ground beneath it.", ua = "Встановлює благословенний прапор Срібного Світанку, освячуючи землю під ним." },
    { en = "Inflict $s1 Shadow damage split between all nearby enemies, and form a Blood Barrier on yourself. The Blood Barrier absorbs ${$329852s1*(1+$@versadmg)} damage for $329849d.\n\n\n\nDamage and absorption are increased for each enemy struck, up to $s2 enemies.", ua = "Завдає $s1 шкоди від темряви, розподіленої між усіма ворогами поблизу, і утворює Кров'яний Бар'єр на вас. Кров'яний Бар'єр поглинає ${$329852s1*(1+$@versadmg)} шкоди протягом $329849d.\n\n\n\nШкода й поглинання зростають за кожного враженого ворога, до $s2 ворогів." },
    { en = "Each time you are struck by an attack, you gain $67727s1 armor.  Stacks up to $67727u times.  Entire effect lasts $d.", ua = "Щоразу, коли по вас влучає атака, ви отримуєте $67727s1 броні. Накопичується до $67727u разів. Увесь ефект триває $d." },
    { en = "Go with the flow, steadily rising towards High Tide or falling towards Low Tide every $402894u seconds.\n\n\n\nAt Low Tide, your next harmful spell or ranged ability grants you $s2 Critical Strike for $402897d. \n\n\n\nAt High Tide, your next harmful spell or ranged ability launches a lava wave to crash upon your target dealing $s1 Volcanic damage split between all nearby enemies. This damage is reduced if the lava wave travels less than $s5 yds.", ua = "Пливіть за течією, поступово підіймаючись до Припливу або спадаючи до Відпливу кожні $402894u секунд.\n\n\n\nПід час Відпливу ваше наступне шкідливе закляття чи дальня здібність надає вам $s2 критичного удару на $402897d.\n\n\n\nПід час Припливу ваше наступне шкідливе закляття чи дальня здібність випускає лавову хвилю, що обрушується на вашу ціль, завдаючи $s1 вулканічної шкоди, розподіленої між усіма ворогами поблизу. Ця шкода зменшується, якщо лавова хвиля долає менш ніж $s5 ярдів." },
    { en = "Each time you strike an enemy with a melee attack, you gain $67737s1 attack power.  Stacks up to $67737u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви вражаєте ворога ближньою атакою, ви отримуєте $67737s1 сили атаки. Накопичується до $67737u разів. Увесь ефект триває $d." },
    { en = "Your abilities have a chance to light the globe, drawing the attention of underlight moths. Collecting an attracted moth grants you Underlight Harmony, increasing your $pri by $s1 for $408983d.", ua = "Ваші здібності мають шанс запалити кулю, привертаючи увагу нічних метеликів. Зібравши приваблений метелик, ви отримуєте «Гармонію підсвітку», що підвищує вашу $pri на $s1 на $408983d." },
    { en = "Each spell cast within 20 seconds will grant a stacking bonus of $35095s1 Versatility. Expires after $d.  Abilities with no mana cost will not trigger this trinket.", ua = "Кожне закляття, застосоване протягом 20 секунд, надає накопичувальний бонус $35095s1 універсальності. Спливає через $d. Здібності без витрати мани не активують цей брелок." },
    { en = "Increases haste by $s1 for $d.", ua = "Підвищує швидкість на $s1 на $d." },
    { en = "Throw a bomb at the target, dealing $s1 Fire Damage upon impact to all enemies within $A yards.", ua = "Кидає бомбу в ціль, завдаючи при влучанні $s1 шкоди від вогню всім ворогам у межах $A ярдів." },
    { en = "Your ranged attacks and spells have a chance to release a Mechanical Bomb Squirrel that charges your target and explodes for $s1 Fire damage.", ua = "Ваші дальні атаки та закляття мають шанс випустити Механічну Білку-Бомбу, що кидається на вашу ціль і вибухає, завдаючи $s1 шкоди від вогню." },
    { en = "Solve a puzzle, increasing your Mastery by $s1 for $d.", ua = "Розв'язує загадку, підвищуючи вашу майстерність на $s1 на $d." },
    { en = "Deals $12278s1 Fire damage every $t1 sec for $d1 to all enemies in front of you. Gets you quite drunk too!", ua = "Завдає $12278s1 шкоди від вогню кожні $t1 сек протягом $d1 усім ворогам перед вами. А ще добряче вас п'янить!" },
    { en = "Your healing spells have a chance to grant you $102746s1 Versatility for $102746d.", ua = "Ваші зцілювальні закляття мають шанс надати вам $102746s1 універсальності на $102746d." },
    { en = "Inflict Taint of the Sea on an enemy for $d, causing them to take $s1% of the damage you deal to all other enemies, up to $215672s1 total damage.|CFF808080$?!(a137013|a137015|a137016|a137018|a137032|a137033|a137040|a137042)[\n\n\n\nValid for ranged damage specializations.][]|R", ua = "Накладає Скверну моря на ворога протягом $d, через що той отримує $s1% шкоди, яку ви завдаєте всім іншим ворогам, до $215672s1 шкоди загалом.|CFF808080$?!(a137013|a137015|a137016|a137018|a137032|a137033|a137040|a137042)[\n\n\n\nДіє для спеціалізацій далекобійної шкоди.][]|R" },
    { en = "Your attacks have a chance to increase your Strength by $202744s1 for $202744d.", ua = "Ваші атаки мають шанс підвищити вашу силу на $202744s1 на $202744d." },
    { en = "When struck in combat has a chance of shielding you in a protective barrier which will reduce damage from each attack by $s1.  Lasts $60218d.", ua = "При влучанні в бою має шанс огорнути вас захисним бар'єром, що зменшить шкоду від кожної атаки на $s1. Триває $60218d." },
    { en = "Increase your Critical Strike by up to $s5, reduced by ${$s5*.08} for each ally within $s3 yards of you. Lasts $d. When this effect ends, your Versatility is increased by $314040s3 for each ally within $s4 yards of you, up to a max of ${$314040s3*5}. Lasts $d.", ua = "Підвищує ваш критичний удар до $s5, зменшуючись на ${$s5*.08} за кожного союзника в межах $s3 ярдів від вас. Триває $d. Коли цей ефект завершується, ваша універсальність зростає на $314040s3 за кожного союзника в межах $s4 ярдів від вас, до максимуму ${$314040s3*5}. Триває $d." },
    { en = "Removes any loss of control effect with a duration of $s1 seconds or more. This effect can only occur once every $336139d.", ua = "Знімає будь-який ефект втрати контролю тривалістю $s1 секунд або більше. Цей ефект може спрацьовувати лише раз на $336139d." },
    { en = "Your healing spells and abilities have a chance to activate a Pre-Fabricated Assistant who applies $s1 absorb to your most injured nearby ally every $368208t1 sec for $368208d.", ua = "Ваші зцілювальні закляття та здібності мають шанс активувати Заздалегідь Зібраного Помічника, який накладає $s1 поглинання на найважче пораненого союзника поблизу кожні $368208t1 сек протягом $368208d." },
    { en = "Gain $@spellname453575 every $457594t seconds spent in combat.\n\n\n\n$@spellname453575 grants $s1 of a random secondary stat for $457596d, stacking up to $457594s1 times.", ua = "Надає $@spellname453575 за кожні $457594t секунд, проведених у бою.\n\n\n\n$@spellname453575 надає $s1 випадкової вторинної характеристики протягом $457596d, накопичуючись до $457594s1 разів." },
    { en = "Your spells and abilities have a chance to grant $378462s1 primary stat for $378462d.", ua = "Ваші закляття та здібності мають шанс надати $378462s1 основної характеристики на $378462d." },
    { en = "Increases your Versatility by +$s1 for $d1.", ua = "Підвищує вашу універсальність на +$s1 на $d1." },
    { en = "Your ranged attacks and spells have a chance to unleash a Carrion Swarm to infect all enemies in a line in front of you, dealing ${$s1*4} Shadow damage over $225731d.", ua = "Ваші дальні атаки та закляття мають шанс випустити Рій Падла, що заражає всіх ворогів на лінії перед вами, завдаючи ${$s1*4} шкоди від темряви протягом $225731d." },
    { en = "Unleash the voice of Ohn'ahra to wrap an ally in wind, shielding them for $s1 damage for $388855d. When this effect ends the winds disperse and shield up to $s3 nearby allies.", ua = "Вивільняє голос Он'агри, щоб огорнути союзника вітром, захищаючи його від $s1 шкоди на $388855d. Коли цей ефект завершується, вітри розсіюються і захищають до $s3 союзників поблизу." },
    { en = "Repurpose a Seaforium charge to give your heart a kick, causing your first ability every $s2 sec to trigger Explosive Adrenaline, granting $s1 Critical Strike for $1218713d.\n\n\n\nWhile exploding, Critical Strikes cause you to blow up again, extending this duration by 1 sec, up to 15 times.", ua = "Перепризначає заряд морфіуму, щоб дати поштовх вашому серцю, через що ваша перша здібність кожні $s2 сек активує Вибухову Адреналіну, надаючи $s1 критичного удару на $1218713d.\n\n\n\nПід час вибуху критичні удари змушують вас вибухати знову, продовжуючи цю тривалість на 1 сек, до 15 разів." },
    { en = "Your melee and ranged attacks have a chance to grant $120258s1 mastery for $120258d.", ua = "Ваші ближні та дальні атаки мають шанс надати $120258s1 майстерності на $120258d." },
    { en = "Each time you cast a spell, there is a chance you will gain up to $49623s1 Versatility for $49623d.", ua = "Щоразу, коли ви застосовуєте закляття, є шанс, що ви отримаєте до $49623s1 універсальності на $49623d." },
    { en = "Reduces damage taken from creature area of effect attacks by $s1% for $d.", ua = "Зменшує шкоду від атак істот по площі на $s1% протягом $d." },
    { en = "Restores $265476s1 health whenever you kill a target that yields experience or honor.", ua = "Відновлює $265476s1 здоров'я щоразу, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Select a target friendly player to coach.", ua = "Оберіть союзного гравця для наставництва." },
    { en = "Throw a small Darkened Elemental Core at the target location dealing $405165s1 Shadowflame damage split between all enemies.", ua = "Кидає невелике Затемнене Стихійне Ядро в обрану місцевість, завдаючи $405165s1 шкоди тіньовим полум'ям, розподіленої між усіма ворогами." },
    { en = "Spray enemies with poisonous pheremones over $d, dealing ${$201857s2*$d/$t1} Nature damage and slowing them for $201857d.", ua = "Обприскує ворогів отруйними феромонами протягом $d, завдаючи ${$201857s2*$d/$t1} шкоди від природи та сповільнюючи їх на $201857d." },
    { en = "Call a friend to come help you! They may deal $406477s3 Physical damage to your target and $?134735a[snare][stun] it for $406488d, heal you for $406477s1, or increase a random secondary stat by $406477s2 for $406485d.\n\n\n\nIf you're feeling hungry, they might even bring you some food!", ua = "Покличте друга на допомогу! Він може завдати вашій цілі $406477s3 фізичної шкоди та $?134735a[сповільнити][приголомшити] її на $406488d, зцілити вас на $406477s1 або підвищити випадкову вторинну характеристику на $406477s2 на $406485d.\n\n\n\nА якщо ви зголодніли, друг може навіть принести вам трохи їжі!" },
    { en = "Coat the enemy in a layer of unstable slime, dealing $1214609s3 Nature damage over $1213436d1. If the target dies while slimed, it releases corrosive goo that deals $1214609s2 Nature damage, split between nearby enemies.", ua = "Покриває ворога шаром нестабільної слизі, завдаючи $1214609s3 шкоди від природи протягом $1213436d1. Якщо ціль гине в слизі, вона вивільняє їдку гидоту, що завдає $1214609s2 шкоди від природи, розподіленої між довколишніми ворогами." },
    { en = "Contaminate the ground beneath your feet for $d, dealing $s2 Shadow damage to enemies in the area each second. While you remain in this area, you gain $s3 Leech.", ua = "Забруднює землю під вашими ногами на $d, щосекунди завдаючи $s2 шкоди від темної магії ворогам у цій зоні. Поки ви лишаєтеся в цій зоні, ви отримуєте $s3 до висмоктування." },
    { en = "Your harmful spells have a chance to strike your enemy, dealing $60483s1 shadow damage.", ua = "Ваші шкідливі закляття мають шанс уразити ворога, завдаючи $60483s1 шкоди від темної магії." },
    { en = "Your attacks drain the hourglass, giving you a chance to gain $s1 Haste up to $417452u times before the sand runs out.\n\n\n\nOnce the glass is empty, your next offensive ability performs a flurry of Accelerated Strikes, dealing $s2 Physical damage per stack and flipping the Hourglass to begin the cycle anew.", ua = "Ваші атаки спорожнюють пісковий годинник, даючи вам шанс отримати $s1 швидкості до $417452u разів, перш ніж висиплеться весь пісок.\n\n\n\nКоли годинник спорожніє, ваша наступна наступальна здатність виконає шквал Прискорених Ударів, завдаючи $s2 фізичної шкоди за заряд і перевертаючи Пісковий Годинник, щоб розпочати цикл знову." },
    { en = "Your damaging spells have a chance to attract mites to feast on your target, inflicting up to ${$s1*$1243828d/$1243828t1} Shadow damage over $1243828d. Well-fed mites share their meal with you, each increasing your Intellect by $s2 for $1243843d.", ua = "Ваші закляття, що завдають шкоди, мають шанс приманити кліщів, які бенкетують на вашій цілі, завдаючи до ${$s1*$1243828d/$1243828t1} шкоди від темної магії протягом $1243828d. Сіті кліщі діляться з вами своєю поживою, кожен підвищуючи ваш інтелект на $s2 протягом $1243843d." },
    { en = "Unleash your inner tempest to gain $470042s1 Strength for $d. Your next 3 abilities cause a lightning blast dealing ${$470042s2*$<rolemult>} Nature damage to your primary target. Damage increased by $470042s3% with each subsequent blast.", ua = "Вивільняє вашу внутрішню бурю, даючи $470042s1 сили протягом $d. Ваші наступні 3 здатності викликають спалах блискавки, що завдає ${$470042s2*$<rolemult>} шкоди від природи вашій основній цілі. Шкода зростає на $470042s3% з кожним наступним спалахом." },
    { en = "Your Run Through now deals $s2% additional damage.", ua = "Ваше Наскрізне Проколювання тепер завдає на $s2% більше шкоди." },
    { en = "Taking damage has a chance to open a portal to another world, either healing you, providing an absorption shield, or empowering you with shadowflame magic.", ua = "Отримання шкоди має шанс відкрити портал до іншого світу, який або зцілює вас, або надає поглинальний щит, або наділяє вас магією тіньового полум'я." },
    { en = "Your spells and abilities have a chance to grant you $268536s1 Haste for $268536d.", ua = "Ваші закляття та здатності мають шанс надати вам $268536s1 швидкості протягом $268536d." },
    { en = "Restores $227408s1 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $227408s1 здоров'я, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше ніж раз на 10 секунд." },
    { en = "Your damaging abilities have a high chance to apply Shiver Venom to your target, dealing ${$301624s1*5} Nature damage over 20 seconds, and stacking up to 5 times.", ua = "Ваші здатності, що завдають шкоди, мають високий шанс накласти на ціль Тремтливу Отруту, завдаючи ${$301624s1*5} шкоди від природи протягом 20 секунд, і накопичуючись до 5 разів." },
    { en = "The next opponent you kill within $d1 that yields experience or honor will restore $33013s1 mana.", ua = "Наступний супротивник, якого ви вб'єте протягом $d1 і який дає досвід або честь, відновить $33013s1 мани." },
    { en = "While your health is above $s2% you are judged Worthy, increasing your highest secondary stat by $s1. While your health is below $s2% you are judged Unworthy, decreasing your highest secondary stat by $s1.", ua = "Поки ваше здоров'я вище за $s2%, вас визнано Гідним, що підвищує вашу найвищу вторинну характеристику на $s1. Поки ваше здоров'я нижче за $s2%, вас визнано Негідним, що знижує вашу найвищу вторинну характеристику на $s1." },
    { en = "Increases attack power by $29604s1 and an additional $29604s1 every $t1 sec.  Lasts $d.", ua = "Підвищує силу атаки на $29604s1 і додатково на $29604s1 кожні $t1 сек. Триває $d." },
    { en = "Summon $s7 roots to draw on their power for $d, slowing you by ${$422440s2/4}% per root. Your next $s7 melee abilities each sever a root, dealing $422440s1 additional Shadowflame damage split between nearby enemies.\n\n\n\nDamage increased per enemy struck, up to 5.", ua = "Прикликає $s7 коренів, щоб черпати їхню силу протягом $d, сповільнюючи вас на ${$422440s2/4}% за кожен корінь. Ваші наступні $s7 здатностей ближнього бою щоразу відсікають корінь, завдаючи $422440s1 додаткової шкоди тіньовим полум'ям, розподіленої між довколишніми ворогами.\n\n\n\nШкода зростає за кожного враженого ворога, до 5." },
    { en = "Your healing spell critical strikes have a chance to grant $91138s1 Versatility for $91138d.", ua = "Критичні удари ваших зцілювальних заклять мають шанс надати $91138s1 універсальності протягом $91138d." },
    { en = "Your spells and abilities have a chance to grant you a Light Fragment. Upon collecting $s3 fragments, you unleash the Light within the shard, increasing your $pri by $s1 for $1283378d.", ua = "Ваші чари та здібності мають шанс надати вам Фрагмент Світла. Зібравши $s3 фрагментів, ви вивільняєте Світло всередині уламка, підвищуючи вашу $pri на $s1 протягом $1283378d." },
    { en = "When you deal damage you have a chance to gain $99748s1 Agility for $99748d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $99748s1 спритності протягом $99748d." },
    { en = "Your next $96907u spells cast within $d will reduce the cost of your holy and nature spells by $96907s1, stacking up to $96907u times.", ua = "Ваші наступні $96907u заклять, застосовані протягом $d, зменшать вартість ваших священних і природних заклять на $96907s1, накопичуючись до $96907u разів." },
    { en = "Unseal the ampoule and release the built-up flames of life, dealing $s1 damage split between all enemies and $s2 healing split between all allies within $a1 yds.", ua = "Відкорковує ампулу та вивільняє накопичене полум'я життя, завдаючи $s1 шкоди, розподіленої між усіма ворогами, та $s2 зцілення, розподіленого між усіма союзниками в межах $a1 м." },
    { en = "Your spells and abilities have a chance to grant you $268534s1 Mastery for $268534d.", ua = "Ваші закляття та здатності мають шанс надати вам $268534s1 майстерності протягом $268534d." },
    { en = "Healing Surge has a 10% chance to grant $40465s1 mana, Lightning Bolt has a 15% chance to grant up to $40465s1 mana, and Stormstrike has a 50% chance to grant up to $40466s1 attack power for $40466d.", ua = "Зцілювальна Хвиля має 10% шанс надати $40465s1 мани, Блискавка має 15% шанс надати до $40465s1 мани, а Штормовий Удар має 50% шанс надати до $40466s1 сили атаки протягом $40466d." },
    { en = "Your attacks have a chance to trigger Ettin's Brawn, granting you $224167s1 Strength every $224165t1 sec for $224165d.", ua = "Ваші атаки мають шанс активувати Силу М'язів Еттіна, надаючи вам $224167s1 сили кожні $224165t1 сек. протягом $224165d." },
    { en = "Your healing spells have a chance to increase your Versatility by $89182s1 for $89182d.  This effect can stack up to $89182u times.", ua = "Ваші зцілювальні закляття мають шанс підвищити вашу універсальність на $89182s1 протягом $89182d. Цей ефект може накопичуватися до $89182u разів." },
    { en = "Throw the cosmic resonator which explodes after $s2 sec, dealing $363491s1 Cosmic damage split between all nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to $s3 enemies.", ua = "Кидає космічний резонатор, який вибухає за $s2 сек., завдаючи $363491s1 космічної шкоди, розподіленої між усіма довколишніми ворогами.\n\n\n\nШкода зростає за кожного враженого ворога, до $s3 ворогів." },
    { en = "Your attacks have a chance to grant $176980s1 Haste for $176980d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176980s1 швидкості протягом $176980d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Increases armor by $s1 for $d1.", ua = "Підвищує броню на $s1 протягом $d1." },
    { en = "Incoming melee attacks have a chance to grant you an Earthen Ward, damaging nearby targets for $375273s1 Physical damage split between all nearby enemies and granting you a shield for $375276d1 that absorbs $s1 damage.\n\n\n\nDamage is increased per enemy struck, up to $s2.", ua = "Вхідні атаки ближнього бою мають шанс надати вам Земляний Оберіг, завдаючи довколишнім цілям $375273s1 фізичної шкоди, розподіленої між усіма довколишніми ворогами, та надаючи вам щит на $375276d1, що поглинає $s1 шкоди.\n\n\n\nШкода зростає за кожного враженого ворога, до $s2." },
    { en = "Your attacks grant $107960s1 Agility for the next $107960d, stacking up to $107960u times.", ua = "Ваші атаки надають $107960s1 спритності протягом наступних $107960d, накопичуючись до $107960u разів." },
    { en = "Targets under $s2% health are stung dealing ${$329127s1*($329127d/$329127t1)} Shadow damage over $329127d, returning $s3% of the damage to you as healing. This effect can only occur once every $s4 seconds.", ua = "Цілі зі здоров'ям нижче за $s2% жалить, завдаючи ${$329127s1*($329127d/$329127t1)} шкоди від темної магії протягом $329127d, повертаючи вам $s3% завданої шкоди як зцілення. Цей ефект може спрацьовувати лише раз на $s4 секунд." },
    { en = "Your melee critical strikes have a chance to grant $91355s1 haste for $91355d.", ua = "Ваші критичні удари ближнього бою мають шанс надати $91355s1 швидкості протягом $91355d." },
    { en = "Your melee attacks have a chance to grant $92342s1 haste for $92342d.", ua = "Ваші атаки ближнього бою мають шанс надати $92342s1 швидкості протягом $92342d." },
    { en = "Your direct healing and heal over time spells have a chance to increase your Haste by $195007s1 for $195007d.", ua = "Ваші прямі зцілення та закляття зцілення в часі мають шанс підвищити вашу швидкість на $195007s1 на $195007d." },
    { en = "Melee attacks against you have a chance to invoke a Sonic Shield, absorbing $55019s1 damage.  This effect can only occur once a minute.", ua = "Атаки ближнього бою по вас мають шанс закликати Звуковий Щит, що поглинає $55019s1 шкоди. Цей ефект може спрацьовувати лише раз на хвилину." },
    { en = "Your spells have a chance to increase your Mastery $202899s1 for $202899d.", ua = "Ваші закляття мають шанс підвищити вашу майстерність на $202899s1 на $202899d." },
    { en = "Your attacks have a chance to imbed Fel Barbs into your target, dealing $238523o Fire damage over $238523d.", ua = "Ваші атаки мають шанс встромити в ціль Скверноскалки, завдаючи $238523o шкоди вогнем протягом $238523d." },
    { en = "Your spells have a chance to grant $90847s1 spell power for $90847d.", ua = "Ваші закляття мають шанс надати $90847s1 сили заклять на $90847d." },
    { en = "Taking damage has a chance to heal you, and any overhealing is converted into an absorb.", ua = "Отримання шкоди має шанс зцілити вас, а будь-яке надлишкове зцілення перетворюється на поглинання." },
    { en = "Don Ultradon scales granting you an $s1 absorb shield for $d.", ua = "Вкриває вас лускою ультрадона, надаючи поглинальний щит на $s1 протягом $d." },
    { en = "Grants $34747s1 increased spell power for $34747d when one of your spells is resisted.", ua = "Надає $34747s1 додаткової сили заклять на $34747d, коли одному з ваших заклять чинять опір." },
    { en = "Release all accumulated Holy Energy to instantly heal current friendly target by the amount of Holy Energy accumulated.", ua = "Вивільняє всю накопичену Священну Енергію, миттєво зцілюючи поточну дружню ціль на величину накопиченої Священної Енергії." },
    { en = "Your melee and ranged attacks have a chance to grant $122268s1 mastery for $122268d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $122268s1 майстерності на $122268d." },
    { en = "Your harmful spells and abilities have a chance to awaken the relic, its energy overloading and erupting at your target, inflicting ${$s1*$<rolemult>} Physical damage split among nearby enemies.", ua = "Ваші шкідливі закляття та здібності мають шанс пробудити реліквію, чия енергія перевантажується й вивергається на вашу ціль, завдаючи ${$s1*$<rolemult>} фізичної шкоди, розподіленої між ворогами поблизу." },
    { en = "Your healing and damaging spells have a chance to grant $118866s1 haste for $118866d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $118866s1 швидкості на $118866d." },
    { en = "Summons a Terracotta Warrior to fight for you for $d.", ua = "Закликає Теракотового Воїна, що б'ється за вас протягом $d." },
    { en = "Your healing and damaging spells have a chance to grant $117647s1 Critical Strike for $117647d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $117647s1 критичного удару на $117647d." },
    { en = "Harness the power of lightning to strike down all enemies around you for ${$<rolemult>*$17669s1} Nature damage.", ua = "Опануйте силу блискавки, щоб уразити всіх ворогів довкола вас на ${$<rolemult>*$17669s1} шкоди природою." },
    { en = "Summon a Wisp to aid an ally. When the Wisp reaches your target's location, it detonates for $221903s1 healing within $221903A1 yds.", ua = "Закликає Вогник на допомогу союзникові. Коли Вогник досягає місця розташування вашої цілі, він детонує, зцілюючи на $221903s1 у радіусі $221903A1 м." },
    { en = "Your direct healing and heal over time spells have a chance to increase your Haste by $234786s1 for $234786d.", ua = "Ваші прямі зцілення та закляття зцілення в часі мають шанс підвищити вашу швидкість на $234786s1 на $234786d." },
    { en = "Your healing has a low chance to manifest a Sapling of Life near your target's location that periodically restores $413711s1 health split between you and all allies in your party for $s4 sec.\n\n\n\nAs the Sapling gives, its life slowly fades. Healing the Sapling of Life extends its duration up to $413710d.", ua = "Ваше зцілення має низький шанс проявити Паросток Життя поблизу місця розташування вашої цілі, що періодично відновлює $413711s1 здоров'я, розподіленого між вами та всіма союзниками у вашій групі, протягом $s4 сек.\n\n\n\nПоки Паросток дарує, його власне життя повільно згасає. Зцілення Паростка Життя подовжує його тривалість до $413710d." },
    { en = "Enkindle the fragment to throw an erupting spear which deals $381484s1 Fire damage split between all enemies in the area. The erupted flames return to you for $381476d, increasing your Critical Strike by $381484s2 for each enemy struck, stacking up to $381484s3 times.", ua = "Запаліть фрагмент, щоб метнути вибухаючий спис, який завдає $381484s1 шкоди вогнем, розподіленої між усіма ворогами в зоні. Спалахи полум'я повертаються до вас протягом $381476d, підвищуючи ваш критичний удар на $381484s2 за кожного враженого ворога, накопичуючись до $381484s3 разів." },
    { en = "Each time your attacks hit, you have a chance to gain $162913s1 Versatility for $162913d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $162913s1 універсальності на $162913d. ($h% шансу, ${$proccooldown} сек. відновлення)" },
    { en = "Your harmful abilities have a chance to cause you to summon a Paladin Protector to fight by your side for $175733d.", ua = "Ваші шкідливі здібності мають шанс закликати Паладина-Захисника, що б'ється поруч із вами протягом $175733d." },
    { en = "Blasts enemies in front of you with the power of wind, fire, all that kind of thing!", ua = "Уражає ворогів перед вами силою вітру, вогню й усього такого!" },
    { en = "Your damaging spells and abilities have a chance to deal an additional ${$s1*($356181d/$356181t1+1)} Shadow damage over $356181d.\n\n\n\nIf a target dies while affected by the Tormentor's Rack Fragment, it leaves a Shredded Soul behind which you can collect to gain $s2 Critical Strike for $356281d.", ua = "Ваші шкідливі закляття та здібності мають шанс завдати додатково ${$s1*($356181d/$356181t1+1)} шкоди тінню протягом $356181d.\n\n\n\nЯкщо ціль гине під дією Фрагмента Дибки Мучителя, вона залишає по собі Пошматовану Душу, яку ви можете зібрати, щоб отримати $s2 критичного удару на $356281d." },
    { en = "Increases your haste by $s1 for $d.", ua = "Підвищує вашу швидкість на $s1 на $d." },
    { en = "Your harmful spells have a chance to grant $91024s1 mastery for $91024d.", ua = "Ваші шкідливі закляття мають шанс надати $91024s1 майстерності на $91024d." },
    { en = "Your healing spells have a chance to call a flowing anthem, granting $91143s1 Haste for $91143d. While under this effect, your healing spells on allies have a chance to cause a ripple, granting them $413426s1 Haste for $413426d.", ua = "Ваші зцілювальні закляття мають шанс закликати плинний гімн, надаючи $91143s1 швидкості на $91143d. Поки діє цей ефект, ваші зцілювальні закляття на союзниках мають шанс викликати брижі, надаючи їм $413426s1 швидкості на $413426d." },
    { en = "Each time your attacks hit, you have a chance to gain $162919s1 critical strike for $162919d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $162919s1 критичного удару на $162919d. ($h% шансу, ${$proccooldown} сек. відновлення)" },
    { en = "Your abilities have a chance to call an earthen ally to your aid, supporting you in combat.", ua = "Ваші здібності мають шанс прикликати на допомогу земляного союзника, що підтримує вас у бою." },
    { en = "Your melee attacks have a chance to grant $122269s1 parry for $122269d.", ua = "Ваші атаки ближнього бою мають шанс надати $122269s1 парирування на $122269d." },
    { en = "When you deal damage you have a chance to gain $75458s1 attack power for $75458d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $75458s1 сили атаки на $75458d." },
    { en = "Increases arcane spell power by $s1 for $d.", ua = "Підвищує силу містичних заклять на $s1 на $d." },
    { en = "Borrow from the fates of those around you, increasing your Mastery by $s1 for $d.", ua = "Позичте з доль тих, хто довкола вас, підвищивши вашу майстерність на $s1 на $d." },
    { en = "Your spells and abilities have a high chance to Hype you up, granting $s1 Haste up to $1216212u times. Upon reaching maximum Hype, amp it up by $s2% for $s3 sec before starting again.", ua = "Ваші закляття та здібності мають високий шанс розпалити Ажіотаж, надаючи $s1 швидкості до $1216212u разів. Досягнувши максимального Ажіотажу, підсильте його на $s2% на $s3 сек., перш ніж почати знову." },
    { en = "Summon the Brewmaiden, whose very presence bolsters a party's vigor. Wave at her for Brewfest Brew!", ua = "Закликає Броварницю, чия сама лише присутність зміцнює бойовий дух групи. Помахайте їй, щоб отримати Хмільне Пиво!" },
    { en = "Increases Armor by $s1 for $d.", ua = "Підвищує броню на $s1 на $d." },
    { en = "Your healing and damaging spells have a chance to grant $117642s1 Versatility for $117642d.", ua = "Ваші зцілювальні та шкодочинні закляття мають шанс надати $117642s1 універсальності на $117642d." },
    { en = "Succumb to the Icon's whispers and become Infused with $?a137048|a137028|a137023|a137010|a137008|a212613[Earth]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[Fire][Frost], increasing your $?a137048|a137028|a137023|a137010|a137008|a212613[Versatility]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[Haste][Critical Strike] by $s1. \n\n\n\nFighting alongside allies who are Infused with $?a137048|a137028|a137023|a137010|a137008|a212613[Fire or Frost]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[Earth or Frost][Earth or Fire] has a chance to grant you $s2 of their Infusion's stat for $382081d.\n\n\n\nInfusion based on your current specialization.", ua = "Піддайтеся шепотінню Ікони й сповніться $?a137048|a137028|a137023|a137010|a137008|a212613[Землею]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[Вогнем][Льодом], що підвищує вашу $?a137048|a137028|a137023|a137010|a137008|a212613[універсальність]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[швидкість][влучність критичних ударів] на $s1. \n\n\n\nБій пліч-о-пліч із союзниками, сповненими $?a137048|a137028|a137023|a137010|a137008|a212613[Вогнем або Льодом]?a137039|a137031|a137032|a137029|a137024|a356810|a137012[Землею або Льодом][Землею або Вогнем], дає шанс надати вам $s2 показника їхнього Сповнення на $382081d.\n\n\n\nСповнення залежить від вашої поточної спеціалізації." },
    { en = "Periodically rummage through the cache, finding a new stolen weapon.", ua = "Періодично нишпорить у схованці, знаходячи нову вкрадену зброю." },
    { en = "Wave the larynx in the air to release a tormenting chorus, inflicting ${$<rolemult>*$446787s2*$d/$t1} Shadow damage over $d split between nearby enemies. Your whispers leave to join the chorus, increasing its damage before falling silent.", ua = "Махніть гортанню в повітрі, щоб вивільнити стражденний хор, завдаючи ${$<rolemult>*$446787s2*$d/$t1} шкоди тінню протягом $d, поділеної між ворогами поблизу. Ваші шепоти линуть приєднатися до хору, посилюючи його шкоду, перш ніж стихнути." },
    { en = "Reduces the mana cost of your spells by $s1.", ua = "Зменшує витрату мани ваших заклять на $s1." },
    { en = "Chance on melee or ranged critical strike to increase your haste by $s1 for $71403d.", ua = "Критичний удар у ближньому або дальньому бою має шанс підвищити вашу швидкість на $s1 на $71403d." },
    { en = "Your spells have a chance to grant you Wrath of Elune, causing your damaging spells to inflict $202917s1 additional Holy damage for $202917d.", ua = "Ваші закляття мають шанс надати вам Гнів Елуни, через що ваші шкодочинні закляття завдають додатково $202917s1 шкоди святом протягом $202917d." },
    { en = "Activate the Tyrstone, recording $s1% of your healing done over the next $d, up to $417959s2 healing done.", ua = "Активуйте Тірстоун, накопичуючи $s1% завданого вами зцілення протягом наступних $d, до $417959s2 зцілення." },
    { en = "Each time you land a killing blow on an enemy that yields experience or honor, you gain the Power of Madness.", ua = "Щоразу, коли ви завдаєте смертельного удару ворогу, що дає досвід чи честь, ви отримуєте Силу Безумства." },
    { en = "Shield an ally for up to $s1 from a great distance and gain up to $s2 Speed. The Absorb and Speed amounts vary depending on the distance between you and your target, with the Absorb increasing and the Speed decreasing the closer you are.", ua = "Захищає союзника на величезній відстані щитом до $s1 та надає вам до $s2 швидкості. Розмір поглинання та швидкості залежить від відстані між вами й ціллю: що ви ближче, то більше поглинання і то менша швидкість." },
    { en = "Defer ${$s1*(1+$@versadmg)} healing every $t1 seconds. Moving releases deferred healing, restoring health to your $s2 most injured allies.", ua = "Відкладає ${$s1*(1+$@versadmg)} зцілення кожні $t1 сек. Рух вивільняє відкладене зцілення, відновлюючи здоров'я вашим $s2 найтяжче пораненим союзникам." },
    { en = "The gearbox is Wound each time you cause a critical strike. When Wound $s1 times, unleash a Torrent of Flames dealing ${$<rolemult>*$s2} Fire damage. The gearbox cannot be Wound more than once every 2.5 sec.", ua = "Механізм заводиться щоразу, коли ви завдаєте критичного удару. Коли він заведений $s1 раз(и), вивільняється Потік Полум'я, завдаючи ${$<rolemult>*$s2} шкоди вогнем. Механізм не може заводитися частіше ніж раз на 2,5 сек." },
    { en = "Auto attacking the same target $281545u times in a row grants you $281546s1 Haste for $281546d.", ua = "Автоатака по тій самій цілі $281545u раз(и) поспіль надає вам $281546s1 швидкості на $281546d." },
    { en = "Deal yourself in, granting you ${$466680s1*(1-$466680s2/100)} to ${$466680s1*(1+$466680s2/100)} Mastery for $d and stacking the deck. Stacking the deck increases the minimum Mastery on future hands by ${$466680s1*($466680s2/100/3)} until you leave combat, up to $1219158u times.", ua = "Роздайте собі карти, отримавши від ${$466680s1*(1-$466680s2/100)} до ${$466680s1*(1+$466680s2/100)} майстерності на $d і складаючи колоду на свою користь. Складання колоди підвищує мінімальну майстерність майбутніх роздач на ${$466680s1*($466680s2/100/3)}, доки ви не вийдете з бою, до $1219158u раз(ів)." },
    { en = "Understand the forbidden tongue of Demonic. You dare not speak its words.", ua = "Ви розумієте заборонену демонічну мову. Ви не наважуєтеся вимовляти її слова." },
    { en = "If your mana is above $377450s1%, toss the Chillglobe at your target, inflicting $377450s2 Frost damage.\n\n\n\nIf your mana is below $377450s1%, instead drink from the Chillglobe to restore $377450s3 mana instantly.", ua = "Якщо ваша мана вища за $377450s1%, ви жбурляєте Крижану Кулю в ціль, завдаючи $377450s2 шкоди морозом.\n\n\n\nЯкщо ваша мана нижча за $377450s1%, ви натомість п'єте з Крижаної Кулі, миттєво відновлюючи $377450s3 мани." },
    { en = "Your critical strikes have a chance to grant $250076s1 Agility for $250076d.", ua = "Ваші критичні удари мають шанс надати $250076s1 спритності на $250076d." },
    { en = "Taking damage has a chance to increase your Versatility by $381769s1 for $381769d.\n\n\n\nThis effect is increased for every ally within $381769s2 yds, up to $381769s3.", ua = "Отримання шкоди має шанс підвищити вашу універсальність на $381769s1 на $381769d.\n\n\n\nЦей ефект посилюється за кожного союзника в межах $381769s2 м, до $381769s3." },
    { en = "You gain Nalorakk's Favor of Enduring. Taking damage has a chance to grant a Mark of Frost, increasing your Critical Strike by $s1 for $1260316d. Stacks up to $1260316u times.\n\n\n\nIf your health falls below $s2%, the reservoir ruptures, consuming all marks to form a Frost Barrier that absorbs $s3 damage per mark for $1260321d.", ua = "Ви отримуєте Прихильність Витривалості Налоракка. Отримання шкоди має шанс надати Знак Морозу, підвищуючи ваш критичний удар на $s1 на $1260316d. Складається до $1260316u раз(ів).\n\n\n\nЯкщо ваше здоров'я падає нижче $s2%, резервуар проривається, поглинаючи всі знаки, щоб сформувати Морозну Перепону, яка поглинає $s3 шкоди за кожен знак протягом $1260321d." },
    { en = "Your disease ticks have a $s1% chance to trigger Wandering Plague, dealing the same damage again to the target and all other enemies within $184899A1 yards, split evenly.", ua = "Тікі ваших хвороб мають $s1% шанс спричинити Мандрівну Чуму, завдаючи ту саму шкоду знову цілі та всім іншим ворогам у межах $184899A1 м, поділену порівну." },
    { en = "Your attacks have a high chance to create an Anima Field at your location for $345534d. Standing within the field grants you $s1 Haste.", ua = "Ваші атаки мають високий шанс створити Поле Аніми на вашій позиції на $345534d. Перебування в полі надає вам $s1 швидкості." },
    { en = "Mark a friendly player with Glimmering Dust, healing them for ${$s1*(1+$@versadmg)} every ${$t1}.1 sec for $d. If they fall below $s2% health, Glimmering Dust is consumed to grant them a shield that prevents ${(1+$@versadmg)*$346438s1} damage for $339516d.", ua = "Позначає дружнього гравця Мерехтливим Пилом, зцілюючи його на ${$s1*(1+$@versadmg)} кожні ${$t1}.1 сек протягом $d. Якщо його здоров'я падає нижче $s2%, Мерехтливий Пил поглинається, надаючи йому щит, що відвертає ${(1+$@versadmg)*$346438s1} шкоди протягом $339516d." },
    { en = "Your spells have a chance to call on Dope'rel to Backstab your target dealing ${$<rolemult>*$s1} Physical damage.", ua = "Ваші закляття мають шанс прикликати Доп'рела, щоб завдати цілі удару в спину на ${$<rolemult>*$s1} фізичної шкоди." },
    { en = "Your spells have a chance to trigger Sanitizing for $177086d.  While Sanitizing is active, you gain $177086s1 Haste every $177086t1 sec, stacking up to $177087u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші закляття мають шанс запустити Знезараження на $177086d. Поки Знезараження активне, ви отримуєте $177086s1 швидкості кожні $177086t1 сек, складаючись до $177087u раз(ів). (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your melee and ranged critical strikes have a chance to grant $92055s1 haste for $92055d.", ua = "Ваші критичні удари в ближньому та дальньому бою мають шанс надати $92055s1 швидкості на $92055d." },
    { en = "Your spells have a chance to increase your haste by $60492s1 for 10 secs.", ua = "Ваші закляття мають шанс підвищити вашу швидкість на $60492s1 на 10 сек." },
    { en = "Your spells have a chance to conjure a typhoon that travels towards enemies dealing $300917s1 Nature damage and grant you $300919s~1 Haste for $300919d, up to ${$300919s*$300919u} Haste.", ua = "Ваші закляття мають шанс прикликати тайфун, що рухається до ворогів, завдаючи $300917s1 шкоди природою та надаючи вам $300919s~1 швидкості на $300919d, до ${$300919s*$300919u} швидкості." },
    { en = "Poison your target for $s1 Nature damage every $t1 sec for $d.", ua = "Отруює вашу ціль, завдаючи $s1 шкоди природою кожні $t1 сек протягом $d." },
    { en = "Your damaging abilities have a low chance to surround you with an Arcane Tempest for $d, inflicting $302774s1 Arcane damage every $t1 sec to nearby enemies. The Tempest accelerates each time it strikes a lone enemy, dealing damage more frequently.", ua = "Ваші шкідливі здібності мають низький шанс оточити вас Чаромагічною бурею на $d, завдаючи $302774s1 одиниць Чаромагічної шкоди щомиті $t1 с ворогам поблизу. Буря пришвидшується щоразу, коли вражає одинокого ворога, завдаючи шкоди частіше." },
    { en = "Your spells and abilities have a chance to grant you $268607s1 Haste for $268607d.", ua = "Ваші закляття та здібності мають шанс надати вам $268607s1 швидкості на $268607d." },
    { en = "Your melee and ranged attacks have a chance to grant $116722s1 haste for $116722d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $116722s1 швидкості на $116722d." },
    { en = "Your ranged attacks have a chance to send a vengeful flame towards your target, dealing ${$<rolemult>*$s1} Fire damage when it reaches them.\n\n\n\nThe spirit grows as it travels towards the target, dealing up to $s2% additional Fire damage.", ua = "Ваші дальні атаки мають шанс послати мстиве полум'я до вашої цілі, завдаючи ${$<rolemult>*$s1} шкоди вогнем, коли воно її досягає.\n\n\n\nДух росте, рухаючись до цілі, завдаючи до $s2% додаткової шкоди вогнем." },
    { en = "Your damaging abilities have a chance to deal an additional $336587s1 Shadow damage.", ua = "Ваші шкодочинні здібності мають шанс завдати додатково $336587s1 шкоди тінню." },
    { en = "Summons a keg of Flamelager's Summer Brew at the target location for $d.  Allies can use the keg to be healed for $127788s1.  20 charges.", ua = "Прикликає барило Літнього Пива Полум'яного Лагера на цільовій позиції на $d. Союзники можуть скористатися барилом, щоб зцілитися на $127788s1. 20 зарядів." },
    { en = "Your healing spells have a chance to grant $91141s1 haste for $91141d.", ua = "Ваші зцілювальні закляття мають шанс надати $91141s1 швидкості на $91141d." },
    { en = "Your healing effects have a chance to do an additional $242327s1 healing. This occurs more often while you are at low mana.", ua = "Ваші ефекти зцілення мають шанс дати додатково $242327s1 зцілення. Це трапляється частіше, коли у вас мало мани." },
    { en = "Your damaging spells and abilities have a chance to send an orb of volatile black blood drifting to your target, exploding for ${$<rolemult>*$s1} Shadow damage split between all nearby enemies on impact. Intercepting the orb allows you to siphon its power, instead increasing your Mastery by $s2 for $451303d.", ua = "Ваші шкодочинні закляття та здібності мають шанс послати кулю нестабільної чорної крові, що дрейфує до вашої цілі, вибухаючи на ${$<rolemult>*$s1} шкоди тінню, поділену між усіма ворогами поблизу при влучанні. Перехоплення кулі дозволяє вам відсмоктати її силу, натомість підвищуючи вашу майстерність на $s2 на $451303d." },
    { en = "Your melee attacks have a chance to deal $342428s1 Arcane damage split between enemies in a $342428A1 yd cone in front of you.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші атаки ближнього бою мають шанс завдати $342428s1 чарівної шкоди, розподіленої між ворогами в конусі завдовжки $342428A1 ярд перед вами.\n\n\n\nШкода зростає за кожного враженого ворога, до $s2 ворогів." },
    { en = "Increases dodge by $s2 for $d.", ua = "Підвищує ухилення на $s2 на $d." },
    { en = "Your melee and ranged attacks have a chance to increase your critical strike by $60437s1 for $60437d1.", ua = "Ваші атаки ближнього та дальнього бою мають шанс підвищити ваш критичний удар на $60437s1 на $60437d1." },
    { en = "Heal yourself for $s1.", ua = "Зцілює вас на $s1." },
    { en = "Every $t1 sec, your next melee ability applies Liquefying Ooze, dealing ${$s1*($345466d/$345466t1)*(1+$@versadmg)} Nature damage over $345466d.\n\n\n\nLiquefying Ooze stacks up to $345466u times. Stacking does not refresh the duration.", ua = "Кожні $t1 с ваша наступна здатність ближнього бою накладає Розріджувальну Слиз, завдаючи ${$s1*($345466d/$345466t1)*(1+$@versadmg)} шкоди природою протягом $345466d.\n\n\n\nРозріджувальна Слиз накопичується до $345466u разів. Накопичення не оновлює тривалість." },
    { en = "When your attacks hit you have a chance to gain $126513s1 critical strike for $126513d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $126513s1 критичного удару на $126513d. ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Increases the damage of Shadowstrike by $s1%.", ua = "Підвищує шкоду Тіньового Удару на $s1%." },
    { en = "Your melee attacks have a chance to grant $109993s1 mastery for $109993d.", ua = "Ваші атаки ближнього бою мають шанс надати $109993s1 майстерності на $109993d." },
    { en = "Your harmful abilities may cause your mind to tear piece by piece. At the tenth tear, you succumb to Arcane Insanity granting you $s1 Haste while periodically recovering your sanity over time.\n\n\n\nSlaying an enemy or witnessing an ally's death instantly tears at your sanity.", ua = "Ваші шкідливі здатності можуть розривати ваш розум шматок за шматком. На десятому розриві ви піддаєтеся Чарівному Божевіллю, отримуючи $s1 швидкості, тимчасом як ваша свідомість поступово відновлюється з часом.\n\n\n\nВбивство ворога або споглядання смерті союзника миттєво розриває вашу свідомість." },
    { en = "Heals you for $s1% of your maximum health whenever you kill a target that yields experience or honor.", ua = "Зцілює вас на $s1% вашого максимального здоров'я щоразу, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Each time your harmful spells hit, you have a chance to gain $126659s1 Haste for $126659d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші шкідливі закляття влучають, ви маєте шанс отримати $126659s1 швидкості на $126659d. ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Your attacks have a chance to increase your Haste by $s1 for $d, stacking up to $u times.", ua = "Ваші атаки можуть збільшити ваш Поспіх на $s1 протягом $d, накопичуючись до $u разів." },
    { en = "Your skin hardens, absorbing ${$s1*(1+$@versadmg)} damage for $d.\n\n\n\nTaking magic damage increases the remaining absorb by $s2 and duration by $s3 sec, up to a maximum of ${$s1+($s2*$s4)} damage and ${$d+($s3*$s4)} sec.", ua = "Ваша шкіра твердне, поглинаючи ${$s1*(1+$@versadmg)} шкоди протягом $d.\n\n\n\nОтримання магічної шкоди підвищує залишковий щит поглинання на $s2, а тривалість на $s3 с, до максимуму ${$s1+($s2*$s4)} шкоди та ${$d+($s3*$s4)} с." },
    { en = "Sharpen your weapon with Elementium, giving your $?a137048[Shield Slam][]$?a137050[Raging Blow and Annihilator][]$?a137049[Mortal Strike][]$?a137028[Hammer of the Righteous and Blessed Hammer][]$?a137027[Crusader Strike, Crusading Strikes, and Templar Strikes][]$?a137023[Tiger Palm][]$?a137025[Tiger Palm][]$?a137009[Mangle, Maul, and Shred][]$?a212613[Soul Cleave][]$?a212612[Chaos Strike and Annihilation][]$?a137008[Heart Strike][]$?a137007[Scourge Strike and Clawing Shadows][]$?a137006[Obliterate][]$?a137035[Backstab and Gloomblade][]$?a137036[Sinister Strike][]$?a137037[Mutilate][]$?a137014[Raptor Strike and Mongoose Bite][]$?a137041[Stormstrike and Windstrike][]$?a137039|$a137031|$a137032|$a137029|$a137024|$a356810|$a137046|$a137044|$a137043|$a137040|$a137033|$a137020|$a137019|$a137021|$a356809|[melee damage dealer specialization's main class ability][] a chance to deal ${$s1*0.6} additional Shadowflame damage on-hit.", ua = "Загострює вашу зброю елементієм, надаючи вашому $?a137048[Удару щитом][]$?a137050[Шаленому удару та Винищувачу][]$?a137049[Смертельному удару][]$?a137028[Молоту праведника та Благословенному молоту][]$?a137027[Удару хрестоносця, Ударам хрестового походу та Ударам тамплієра][]$?a137023[Тигрячій лапі][]$?a137025[Тигрячій лапі][]$?a137009[Шматуванню, Каліченню та Роздиранню][]$?a212613[Розколу душі][]$?a212612[Удару хаосу та Знищенню][]$?a137008[Удару в серце][]$?a137007[Удару Батога та Дряпучим тіням][]$?a137006[Винищенню][]$?a137035[Удару в спину та Похмурому клинку][]$?a137036[Лиховісному удару][]$?a137037[Калічінню][]$?a137014[Удару раптора та Укусу мангуста][]$?a137041[Удару бурі та Удару вітру][]$?a137039|$a137031|$a137032|$a137029|$a137024|$a356810|$a137046|$a137044|$a137043|$a137040|$a137033|$a137020|$a137019|$a137021|$a356809|[головній класовій здібності спеціалізації ближнього бою, що завдає шкоди][] шанс завдавати ${$s1*0.6} додаткової шкоди тіньовим полум'ям під час влучання." },
    { en = "Dealing or taking damage has a chance to grant you a stack of Brimming Life-Pod, up to $384646u.", ua = "Завдавання або отримання шкоди має шанс надати вам заряд Повної Життєвої Капсули, до $384646u." },
    { en = "Your spells have a chance to evoke the feral insights of the charm, granting $s1 Critical Strike for $449710d.\n\n\n\nFighting against or alongside a beast increases this effect by $s2%.", ua = "Ваші закляття мають шанс пробудити дикі прозріння оберега, надаючи $s1 критичного удару на $449710d.\n\n\n\nБій проти звіра або пліч-о-пліч зі звіром підвищує цей ефект на $s2%." },
    { en = "Increases resistances to all schools of magic by $s1 for $d.", ua = "Підвищує опір до всіх шкіл магії на $s1 на $d." },
    { en = "Deal $382132s1 Frost damage to your target, encasing them and nearby enemies in a Crystalline Web for $382130d. Webbed enemies are slowed by $382130s2% and take $382132s2 Frost damage when any enemy in the web is struck. \n\n\n\nDamage is increased for each webbed enemy, up to $s5. Damage per target is reduced beyond $s5 enemies.", ua = "Завдає $382132s1 шкоди морозом вашій цілі, оплітаючи її та довколишніх ворогів Кристалічним Павутинням на $382130d. Обплутані вороги уповільнюються на $382130s2% і зазнають $382132s2 шкоди морозом, коли будь-який ворог у павутинні зазнає удару.\n\n\n\nШкода зростає за кожного обплутаного ворога, до $s5. Шкода на ціль зменшується понад $s5 ворогів." },
    { en = "Your spells have a chance to increase your Critical Strike by $383168s1 for $383168d.", ua = "Ваші закляття мають шанс підвищити ваш критичний удар на $383168s1 на $383168d." },
    { en = "Your spells and abilities have a chance to increase your primary stat by $s2 for $372134d and extend the duration of your active phial by $s1 sec.", ua = "Ваші закляття та здатності мають шанс підвищити вашу основну характеристику на $s2 на $372134d і подовжити тривалість вашого активного флакона на $s1 с." },
    { en = "Each time your attacks hit, you have a chance to gain $126657s1 haste for $126657d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $126657s1 швидкості на $126657d. ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Increase the Haste of all party members within $a1 yards by $s1 for $d.", ua = "Підвищує швидкість усіх членів групи в межах $a1 ярдів на $s1 на $d." },
    { en = "Gain the Titans' crumbling power, increasing $pri by ${$s3*$u}, reduced each time you use an ability. Lasts $d.", ua = "Надає згасаючу силу Титанів, підвищуючи $pri на ${$s3*$u}, що зменшується щоразу, коли ви застосовуєте здібність. Триває $d." },
    { en = "Increases the cooldown recovery rate of some of your major abilities by $s1%.  Effective for tank roles only.  Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Підвищує швидкість відновлення деяких ваших головних здібностей на $s1%. Ефективно лише для ролей танка. Знижена ефективність на $ctrmin2066 рівні та вище." },
    { en = "Your damaging abilities apply Everchill Brambles for $339301d, dealing $289526s1 Frost damage every $289526t1 seconds and stacking up to $339301u times. When Everchill Brambles reaches $339301u stacks, the target is rooted for $339309d.", ua = "Ваші здатності, що завдають шкоди, накладають Ожину Вічного Холоду на $339301d, завдаючи $289526s1 шкоди морозом кожні $289526t1 с і накопичуючись до $339301u разів. Коли Ожина Вічного Холоду досягає $339301u зарядів, ціль скута на $339309d." },
    { en = "Each time one of your direct damage attacks does not critically strike, you gain $39443s1 critical strike and $39443s1 spell critical strike for the next 10 sec.  This effect is consumed when you deal a critical strike.", ua = "Щоразу, коли одна з ваших прямих атак не завдає критичного удару, ви отримуєте $39443s1 критичного удару та $39443s1 критичного удару заклять на наступні 10 с. Цей ефект витрачається, коли ви завдаєте критичного удару." },
    { en = "Your attacks have a chance to grant $183931s1 Mastery for $183931d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $183931s1 майстерності на $183931d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to grant $176917s1 Agility for $176917d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176917s1 спритності на $176917d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increase Critical Strike by $191603s1-$191610s1. The amount of Critical Strike depends on the topmost card in the deck.", ua = "Підвищує критичний удар на $191603s1-$191610s1. Величина критичного удару залежить від верхньої карти в колоді." },
    { en = "Your harmful spells have a chance to increase your Intellect by $64713s1 for $64713d", ua = "Ваші шкідливі закляття мають шанс підвищити ваш інтелект на $64713s1 на $64713d" },
    { en = "Let out a Motivating Howl, granting $s1 Versatility for $d split among you and up to $s3 nearby allies. For each ally you motivate, you gain an additional $s2 Versatility.", ua = "Видає Підбадьорливе Виття, надаючи $s1 універсальності на $d, розподіленої між вами та до $s3 довколишніх союзників. За кожного підбадьореного союзника ви отримуєте додатково $s2 універсальності." },
    { en = "Each time your spells heal you have a chance to gain $148911s1 Intellect for $148911d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші закляття зцілюють, ви маєте шанс отримати $148911s1 інтелекту на $148911d. ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Unleash devouring darkness upon an enemy, reducing their movement speed by $s2% and inflicting $o1 Shadow damage over $d. You are healed for ${$e1*100}% of the damage dealt.", ua = "Вивільняє пожираючу пітьму на ворога, зменшуючи його швидкість пересування на $s2% і завдаючи $o1 шкоди тінню протягом $d. Ви зцілюєтеся на ${$e1*100}% завданої шкоди." },
    { en = "Gain an absorb shield preventing $s2% of the damage done to you in the next $d, up to a total of $s1 damage done. $s3% of the remaining absorption explodes splitting the damage between all enemies within $336850a1 yds.", ua = "Надає щит поглинання, що запобігає $s2% завданої вам шкоди протягом наступних $d, до загального обсягу $s1 шкоди. $s3% залишкового поглинання вибухає, розподіляючи шкоду між усіма ворогами в межах $336850a1 ярдів." },
    { en = "Your damaging spells have a high chance to lash your target with arcane power, dealing ${$s1*$<rolemult>} Arcane damage split between your target and enemies caught in its path. \n\n\n\nDamage increased by $s2% per additional enemy, up to ${$s2*$s3}%, and further increased by your Mastery.", ua = "Ваші закляття, що завдають шкоди, мають високий шанс хльоснути вашу ціль чарівною силою, завдаючи ${$s1*$<rolemult>} чарівної шкоди, розподіленої між вашою ціллю та ворогами на її шляху.\n\n\n\nШкода зростає на $s2% за кожного додаткового ворога, до ${$s2*$s3}%, і додатково зростає від вашої майстерності." },
    { en = "Calls forth 3 Voodoo Gnomes to destroy your enemies.", ua = "Прикликає 3 Вуду-Гномів, щоб знищити ваших ворогів." },
    { en = "Your melee and ranged attacks have a chance to grant $117651s1 mastery for $117651d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс надати $117651s1 майстерності на $117651d." },
    { en = "Your $?a137012[Wild Growth]?a137024[Essence Font]?a137031[Prayer of Healing]?a137032[Power Word: Radiance]?a137029[Light of Dawn]?a137039[Chain Heal][multi-target healing spell] has a chance to grant you Ocean's Embrace, healing your nearest injured ally within $242474A1 yds for $242474s1 every ${$242467t1}.2 sec for $242467d.|CFF808080$?!(a137012|a137024|a137031|a137032|a137029|a137039)[\n\n\n\nValid for healer specializations.][]|R", ua = "Ваші $?a137012[«Дикий ріст»]?a137024[«Джерело суті»]?a137031[«Молитва зцілення»]?a137032[«Слово сили: Сяйво»]?a137029[«Світло світанку»]?a137039[«Ланцюгове зцілення»][чари зцілення кількох цілей] мають шанс надати вам «Обійми океану», зцілюючи вашого найближчого пораненого союзника в межах $242474A1 м на $242474s1 кожні ${$242467t1}.2 сек протягом $242467d.|CFF808080$?!(a137012|a137024|a137031|a137032|a137029|a137039)[\n\n\n\nДіє для спеціалізацій зцілювачів.][]|R" },
    { en = "Deals $s1 Nature damage to an enemy every $t1 sec for $d1.", ua = "Завдає $s1 шкоди природою ворогові кожні $t1 с протягом $d1." },
    { en = "Each time your spells heal you have a chance to gain $126588s1 Intellect for $126588d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші закляття зцілюють, ви маєте шанс отримати $126588s1 інтелекту на $126588d. ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Become the pinnacle of Gallagio service excellence and dole out Kaja'Cola Mega-Lite to injured allies $s2 times over $d, healing them for $471213s1 and increasing their Speed by $471213s2 for $1216884d. The number of servings is increased by your Haste.", ua = "Станьте вершиною бездоганного обслуговування «Галаджіо» й роздавайте «Кадж'А-Колу Мега-Лайт» пораненим союзникам $s2 раз(и) протягом $d, зціляючи їх на $471213s1 і підвищуючи їхню швидкість на $471213s2 на $1216884d. Кількість порцій збільшується від вашої швидкості." },
    { en = "Mark your target for execution, increasing your Haste by $s3 for $d. While the target is marked, each of your attacks against them grants an additional $s2 Critical Strike, as the Void urges you to finish the kill, up to a maximum of ${$s2*$1263357u} Critical Strike.", ua = "Позначає вашу ціль для страти, підвищуючи вашу швидкість на $s3 на $d. Поки ціль позначена, кожна ваша атака по ній дає додатково $s2 критичного удару, адже Порожнеча спонукає вас завершити вбивство, до максимуму ${$s2*$1263357u} критичного удару." },
    { en = "Chance on melee or ranged attack to deal an extra Quick Strike attack dealing ${$<rolemult>*$s1} Physical damage.", ua = "Шанс під час ближньої або дальньої атаки завдати додаткової атаки «Стрімкий Удар», що завдає ${$<rolemult>*$s1} фізичної шкоди." },
    { en = "Each time you cast a spell, there is chance you will gain $37198s1 spell power.", ua = "Щоразу, коли ви накладаєте закляття, є шанс отримати $37198s1 сили заклять." },
    { en = "Increases dodge by $s1 for $d1.", ua = "Підвищує ухиляння на $s1 на $d1." },
    { en = "Increases your maximum health by $s1 for $d1.", ua = "Підвищує ваше максимальне здоров'я на $s1 на $d1." },
    { en = "Grants $s1 mana.", ua = "Надає $s1 мани." },
    { en = "Your area effect spells and abilities have a chance to grant you $s1 $pri and increase damage you receive by $s2% for $403382d.", ua = "Ваші чари та здібності площинної дії мають шанс надати вам $s1 $pri й підвищити шкоду, яку ви отримуєте, на $s2% на $403382d." },
    { en = "Your melee and ranged attacks have a chance to grant $92091s1 Agility for $92091d.", ua = "Ваші ближні та дальні атаки мають шанс надати $92091s1 спритності на $92091d." },
    { en = "The light blesses your weapon, granting your attacks a chance to deal $s1 additional Holy damage and heal you for $s2 health.", ua = "Світло благословляє вашу зброю, надаючи вашим атакам шанс завдати $s1 додаткової священної шкоди та зцілити вас на $s2 здоров'я." },
    { en = "Your ranged attacks and spells have a chance to deal an additional $214350o1 Shadow damage over $214350d and reduce the target's movement speed by $214350s2%.", ua = "Ваші дальні атаки та закляття мають шанс завдати додатково $214350o1 тіньової шкоди протягом $214350d і знизити швидкість пересування цілі на $214350s2%." },
    { en = "Each time you cast a spell, you gain $67696s1 Versatility for $67696d.  Stacks up to $67696u times.", ua = "Щоразу, коли ви накладаєте закляття, ви отримуєте $67696s1 універсальності на $67696d. Накопичується до $67696u разів." },
    { en = "When you deal damage you have a chance to gain $109711s1 haste for $109711d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109711s1 швидкості на $109711d." },
    { en = "Damaging spells and abilities have a chance to grant $s1 Agility and $s2 Speed for $424141d.", ua = "Закляття та здібності, що завдають шкоди, мають шанс надати $s1 спритності та $s2 швидкості на $424141d." },
    { en = "Attacks which reduce your health below $s1% grant you a physical absorb shield equal to $s2% of the damage done by the attack for $108008d, up to $s4.  This effect cannot trigger more often than once every $s3 sec.", ua = "Атаки, що знижують ваше здоров'я нижче $s1%, надають вам щит фізичного поглинання, що дорівнює $s2% від шкоди, завданої атакою, на $108008d, до $s4. Цей ефект не може спрацьовувати частіше, ніж раз на $s3 сек." },
    { en = "Your melee and ranged attacks have a chance to grant $118868s1 critical strike for $118868d.", ua = "Ваші ближні та дальні атаки мають шанс надати $118868s1 критичного удару на $118868d." },
    { en = "Empower yourself with dark energy, causing your attacks to have a chance to inflict $215659s1 additional Shadow damage and grant you a shield for $215659s2.\n\n\n\nLasts $d.", ua = "Наповнює вас темною енергією, через що ваші атаки мають шанс завдати $215659s1 додаткової тіньової шкоди та надати вам щит на $215659s2.\n\n\n\nТриває $d." },
    { en = "Channel a cleansing matrix into an ally, healing them for $o1 over $d. Fully completing the channel also grants the ally a shield that prevents $242621s1 damage for $242621d.", ua = "Підтримує очищувальну матрицю в союзника, зціляючи його на $o1 протягом $d. Повне завершення каналізації також надає союзнику щит, що запобігає $242621s1 шкоди на $242621d." },
    { en = "Removes $m1 poison $leffect:effects;.", ua = "Знімає $m1 $leffect:effects; отрути." },
    { en = "Reduces the duration and period of Agony, Unstable Affliction, and Corruption by $s1%.", ua = "Зменшує тривалість і період дії «Агонії», «Нестабільної Скверни» та «Псування» на $s1%." },
    { en = "Flip to the next section.", ua = "Перейти до наступного розділу." },
    { en = "Your melee and ranged attacks have a chance to grant $122898s1 haste for $122898d.", ua = "Ваші ближні та дальні атаки мають шанс надати $122898s1 швидкості на $122898d." },
    { en = "Afflict your target with Rotting Roots dealing $s1 Nature Damage every $1247411t seconds for $1247411d. This effect stacks up to $1247411u times. New stacks do not refresh applied stacks.\n\n\n\nThis effect is augmented by Darkmoon Sigil: Rot.", ua = "Уражає вашу ціль «Гнилими Коренями», що завдають $s1 шкоди силами природи кожні $1247411t секунд протягом $1247411d. Цей ефект накопичується до $1247411u разів. Нові накопичення не оновлюють уже застосовані накопичення.\n\n\n\nЦей ефект посилюється «Печаткою Самоцвітного Місяця: Гниль»." },
    { en = "Your melee attacks have a chance to grant $122899s1 parry for $122899d.", ua = "Ваші ближні атаки мають шанс надати $122899s1 парирування на $122899d." },
    { en = "Your attacks have a chance to grant you $138702s1 Strength for $138702d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $138702s1 сили на $138702d. ($h% шанс, ${$proccooldown} сек перезарядки)" },
    { en = "Your spells and abilities have a chance to grant you $273992s1 Haste for $273992d.", ua = "Ваші закляття та здібності мають шанс надати вам $273992s1 швидкості на $273992d." },
    { en = "When struck in combat you have a chance to gain a protective barrier which reduces Physical damage from incoming attacks by $64765s1 for $64765d.", ua = "Коли вас вражають у бою, ви маєте шанс отримати захисний бар'єр, що знижує фізичну шкоду від вхідних атак на $64765s1 на $64765d." },
    { en = "Stick a Dragonfire Bomb to your target, dealing $408667s1 Fire damage after $408675d. If your target dies with a bomb attached, it deals $408667s2 split between all enemies within $408694A yards instead. Stores a maximum of $408667s4 bombs. (30 Sec Cooldown)\n\n\n\nCritically striking $408770u times triggers a flash of inspiration, allowing you to assemble an extra Bomb charge on the fly.", ua = "Чіпляє «Драконвогняну Бомбу» до вашої цілі, завдаючи $408667s1 вогняної шкоди через $408675d. Якщо ваша ціль гине з причепленою бомбою, та натомість завдає $408667s2, розділеної між усіма ворогами в радіусі $408694A метрів. Зберігає максимум $408667s4 бомб. (Перезарядка 30 сек)\n\n\n\nКритичне влучання $408770u разів спричиняє спалах натхнення, що дозволяє вам зібрати додатковий заряд бомби на ходу." },
    { en = "Your harmful spells have a chance to grant $91047s1 spell power for $91047d.", ua = "Ваші шкідливі закляття мають шанс надати $91047s1 сили заклять на $91047d." },
    { en = "When you deal damage you have a chance to gain $102742s1 Mastery for $102742d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $102742s1 майстерності на $102742d." },
    { en = "Your heals have a chance to release Living Magma that will travel to the lowest health ally within $s2 yds and heal them for $s1.", ua = "Ваші зцілення мають шанс вивільнити Живу Магму, що полине до союзника з найнижчим здоров'ям у радіусі $s2 м і зцілить його на $s1." },
    { en = "Your spells have a chance to destabilize the void energy, releasing a corrupted fragment. Retrieving a fragment briefly infuses you with its power, increasing your Intellect by $s1 for $11790d.", ua = "Ваші закляття мають шанс дестабілізувати енергію Порожнечі, вивільняючи зіпсований фрагмент. Підбирання фрагмента ненадовго наповнює вас його силою, підвищуючи ваш інтелект на $s1 на $11790d." },
    { en = "Your spells and abilities have a chance to grant you $268619s1 Haste for $268619d.", ua = "Ваші закляття та здібності мають шанс надати вам $268619s1 швидкості на $268619d." },
    { en = "Carve a wax copy of your target, which absorbs $451924s2% of their damage taken. The absorption heats up the wax, causing it to melt after absorbing $451924s1 damage.", ua = "Вирізьблює воскову копію вашої цілі, що поглинає $451924s2% завданої їй шкоди. Поглинання нагріває віск, через що він плавиться після поглинання $451924s1 шкоди." },
    { en = "Your spells have a chance to grant you $278812s1 Versatility for $278812d.", ua = "Ваші закляття мають шанс надати вам $278812s1 універсальності на $278812d." },
    { en = "Your healing spells have a chance to cause Loose Mana to form nearby, lasting $230141d. Contact with it restores $s2 mana to you.", ua = "Ваші зціляючі закляття мають шанс утворити поруч Вільну Ману, що триває $230141d. Контакт із нею відновлює вам $s2 мани." },
    { en = "Your melee attacks and abilities have a high chance to attach a Volatile Satchel onto your target. Upon reaching ${$u1+1} stacks, or when removed, the Volatile Satchel detonates, inflicting ${$<rolemult>*$367901s1} Fire damage.", ua = "Ваші атаки та здібності ближнього бою з високою ймовірністю чіпляють Нестійку торбинку на вашу ціль. Досягнувши ${$u1+1} стаків або при знятті, Нестійка торбинка вибухає, завдаючи ${$<rolemult>*$367901s1} шкоди Вогнем." },
    { en = "Command the Medichopper to attach to your target, absorbing $1220605s1 damage and granting them $1220605s2 versatility for $1219104d.\n\n\n\nWhile attached, your healing spells have a chance to refuel the chopper, granting these bonuses to their host again.", ua = "Наказує Медикоптеру причепитися до вашої цілі, поглинаючи $1220605s1 шкоди та надаючи їй $1220605s2 універсальності на $1219104d.\n\n\n\nПоки він причеплений, ваші зціляючі закляття мають шанс дозаправити коптер, знову надаючи ці бонуси його носію." },
    { en = "Restores $276136s2-$276143s2 mana whenever the deck is shuffled, and your spells have a chance to heal $276136s1-$276143s1 allies for $276146s1. The amount of mana restored and the number of allies healed depends on the topmost card in the deck.", ua = "Відновлює $276136s2-$276143s2 мани щоразу, коли колоду тасують, а ваші закляття мають шанс зцілити $276136s1-$276143s1 союзників на $276146s1. Кількість відновленої мани та число зцілених союзників залежать від верхньої карти в колоді." },
    { en = "Imbue your abilities with the globe's powers gaining $n charges of Frozen Wellspring. Dealing damage consumes a charge dealing $433824s1 additional Frost damage and apply Wellspring's Frost, slowing enemy movement speed by $433824s3% per stack.\n\n\n\nWhen Frozen Wellspring is fully consumed shatter all targets afflicted with Wellspring's Frost dealing $433824s2 Frost damage per stack split between all nearby targets.", ua = "Наповнює ваші здібності силами кулі, надаючи $n зарядів Замерзлого Джерела. Завдаючи шкоди, ви витрачаєте заряд, завдаючи $433824s1 додаткової шкоди від холоду та накладаючи Холод Джерела, що сповільнює швидкість пересування ворога на $433824s3% за кожен стак.\n\n\n\nКоли Замерзле Джерело повністю витрачене, всі цілі під дією Холоду Джерела розколюються, отримуючи $433824s2 шкоди від холоду за кожен стак, розподіленої між усіма цілями поблизу." },
    { en = "Your melee critical strikes have a chance to grant $91370s1 Strength for $91370d.", ua = "Ваші критичні удари в ближньому бою мають шанс надати $91370s1 сили на $91370d." },
    { en = "Taking damage has a chance to fabricate an ally from the Pocket Protoforge who interferes with your enemies' attacks, assisting in combat and absorbing $s2 damage.", ua = "Отримання шкоди має шанс створити в Кишеньковому Протогорні союзника, який заважає атакам ваших ворогів, допомагає в бою та поглинає $s2 шкоди." },
    { en = "Lure out a deepflayer to pounce on your target dealing $s1 Physical damage and granting you $409308s1 bonus maximum health for $409347d.", ua = "Виманює глибинного білувальника, що накидається на вашу ціль, завдаючи $s1 фізичної шкоди та надаючи вам $409308s1 додаткового максимального здоров'я на $409347d." },
    { en = "While your mana is above $s1%, gain $s3 Versatility, increased by up to $300970s3% by the mana stored in the battery. While your mana is under $s2%, siphon $300971s2 mana every $300971t1 sec from the Ingenious Mana Battery into your mana pool.", ua = "Поки ваша мана вища за $s1%, ви отримуєте $s3 універсальності, що збільшується до $300970s3% залежно від мани, накопиченої в батареї. Поки ваша мана нижча за $s2%, ви викачуєте $300971s2 мани кожні $300971t1 сек. із Хитромудрої Манабатареї до свого запасу мани." },
    { en = "Your melee and ranged attacks have a chance to grant $92124s1 haste for $92124d.", ua = "Ваші атаки в ближньому та далекому бою мають шанс надати $92124s1 швидкості на $92124d." },
    { en = "Your harmful ranged spells and abilities have a high chance to rouse the lantern's flame, granting a stack of Lamp Light up to $440635u times.\n\n\n\nAfter $440635d of collecting stacks, Lamp Light is consumed to attract an equal amount of Fireflies to charge the next target you attack exploding for ${$<rolemult>*$s1} Fire damage per Firefly.", ua = "Ваші шкідливі закляття та здібності далекого бою мають високий шанс розпалити полум'я ліхтаря, надаючи стак Світла Лампи до $440635u разів.\n\n\n\nЧерез $440635d зібрані стаки Світла Лампи витрачаються, приваблюючи відповідну кількість світляків, які заряджають наступну ціль, яку ви атакуєте, вибухаючи на ${$<rolemult>*$s1} шкоди від вогню за кожного світляка." },
    { en = "Use: Grants the Watcher's Blessing for 5-12s and an absorb shield for $384532s1 damage. \n\nIf the shield depletes while Watcher's Blessing is active, gain $384560s1 versatility for the same duration. Duration is determined by the top-most card of the deck.", ua = "Використання: Надає Благословення Вартового на 5-12 сек. і поглинаючий щит на $384532s1 шкоди.\n\nЯкщо щит вичерпується, поки активне Благословення Вартового, ви отримуєте $384560s1 універсальності на ту саму тривалість. Тривалість визначається верхньою картою колоди." },
    { en = "Reduce the damage of the next $u melee attacks against you by up to $s1 each. Lasts up to $d.\n\n\n\nSuffering melee attacks reduces the cooldown of this ability by ${$251949s1/1000} sec.", ua = "Зменшує шкоду від наступних $u атак у ближньому бою проти вас до $s1 кожна. Триває до $d.\n\n\n\nОтримання атак у ближньому бою скорочує час відновлення цієї здібності на ${$251949s1/1000} сек." },
    { en = "Instantly heals you for $s1.", ua = "Миттєво зцілює вас на $s1." },
    { en = "When you deal damage you have a chance to gain $118751s1 mastery for $118751d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $118751s1 майстерності на $118751d." },
    { en = "When you deal damage you have a chance to gain $118612s1 haste for $118612d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $118612s1 швидкості на $118612d." },
    { en = "Add an energy core to the container for every enemy slain, up to a maximum of $1214704s3.", ua = "Додає до контейнера енергетичне ядро за кожного вбитого ворога, до максимуму в $1214704s3." },
    { en = "Your melee and ranged attacks have a chance to increase your haste by $34775s1 for $34775d1.", ua = "Ваші атаки в ближньому та далекому бою мають шанс підвищити вашу швидкість на $34775s1 на $34775d1." },
    { en = "Increases your spell resistances by ${$26464m1*10} for $d. Every time a hostile spell lands on you, this bonus is reduced by $26464m1 resistance.", ua = "Підвищує ваш опір заклять на ${$26464m1*10} на $d. Щоразу, коли вас уражає вороже закляття, цей бонус зменшується на $26464m1 опору." },
    { en = "Your melee and ranged critical strikes have a chance to grant $92094s1 Agility for $92094d.", ua = "Ваші критичні удари в ближньому та далекому бою мають шанс надати $92094s1 спритності на $92094d." },
    { en = "Your helpful spells and abilities have a chance to pep up you and your Coached ally, granting you both $s2 Mastery for $383803d.", ua = "Ваші корисні закляття та здібності мають шанс підбадьорити вас і вашого підопічного союзника, надаючи вам обом $s2 майстерності на $383803d." },
    { en = "Radiate a burst of light that heals up to $s1 injured allies within $214200A1 yards for $214200s1.", ua = "Випромінює спалах світла, що зцілює до $s1 поранених союзників у радіусі $214200A1 м на $214200s1." },
    { en = "Your spell casts have a chance to restore $s1 mana every $38346T1 sec for $38346d.", ua = "Ваші чари мають шанс відновлювати $s1 мани кожні $38346T1 с протягом $38346d." },
    { en = "Throw a watermelon at target location, covering nearby enemies in sticky watermelon which will prevent them from moving for $127723d.  Has no effect on players.", ua = "Кидає кавун у вказане місце, обліплюючи ворогів поблизу липкою кавуновою м'якоттю, що не дає їм рухатися протягом $127723d. Не діє на гравців." },
    { en = "Ignite the fuse, gaining $271115s1 Haste every $t1 sec. Haste is removed after $d.", ua = "Підпалює ґніт, надаючи $271115s1 швидкості кожні $t1 сек. Швидкість зникає через $d." },
    { en = "Your melee and ranged attacks have a chance to grant $148447s1 haste for $148447d.", ua = "Ваші атаки в ближньому та далекому бою мають шанс надати вам $148447s1 швидкості на $148447d." },
    { en = "Your healing spells have a chance to grant you $221752s1 Haste and $221752s2 Intellect for $221752d.", ua = "Ваші зцілювальні закляття мають шанс надати вам $221752s1 швидкості та $221752s2 інтелекту на $221752d." },
    { en = "Your damage and healing spells have a chance open a portal to Mardum, sending a stream of imps at your target or your target's opponent.", ua = "Ваші закляття шкоди та зцілення мають шанс відкрити портал до Мардуму, спрямовуючи потік бісенят на вашу ціль або на супротивника вашої цілі." },
    { en = "Your attacks have a chance to grant $176941s1 Mastery for $176941d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176941s1 майстерності на $176941d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your shots deal ${$m1/100}.2% increased damage per yard between you and the target.", ua = "Ваші постріли завдають на ${$m1/100}.2% більше шкоди за кожен метр між вами та ціллю." },
    { en = "Your harmful abilities have a chance to power the amplifier, randomly increasing either your highest secondary stat by $s1 or your lowest secondary stat by $s2 for $1214806d.", ua = "Ваші шкідливі здібності мають шанс живити підсилювач, випадково підвищуючи або вашу найвищу другорядну характеристику на $s1, або найнижчу другорядну характеристику на $s2 на $1214806d." },
    { en = "Drain up to ${$363581s1*4} absorption from all nearby enemies over $d, then unleash it in a $363715a1 yd cone in front of you as healing absorption.", ua = "Витягує до ${$363581s1*4} поглинання з усіх ворогів поблизу протягом $d, а потім вивільняє його в конусі завдовжки $363715a1 м перед вами як зцілювальне поглинання." },
    { en = "Your melee attacks have a chance to grant $102664s1 mastery for $102664d.", ua = "Ваші атаки в ближньому бою мають шанс надати $102664s1 майстерності на $102664d." },
    { en = "Your critical autoattacks have a chance to cause your target to bleed for $221770o1 Physical damage over $221770d.", ua = "Ваші критичні автоатаки мають шанс змусити вашу ціль стікати кров'ю, завдаючи $221770o1 фізичної шкоди протягом $221770d." },
    { en = "When you deal damage you have a chance to gain $122310s1 haste for $122310d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $122310s1 швидкості на $122310d." },
    { en = "Your helpful spells have a chance to grant you a Blessing of Zuldazar, which stacks up to $138967u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші корисні закляття мають шанс надати вам Благословення Зулдазару, яке накопичується до $138967u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage you have a chance to gain $118872s1 haste for $118872d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $118872s1 швидкості на $118872d." },
    { en = "A Slicing Maelstrom surrounds you, inflicting ${7*$214985s1} Physical damage to nearby enemies over $d.", ua = "Вас оточує Розтинаючий Вир, що завдає ${7*$214985s1} фізичної шкоди ворогам поблизу протягом $d." },
    { en = "Your abilities have a chance to deal an additional $s2 damage or $s1 healing, as appropriate to your target.", ua = "Ваші здібності мають шанс завдати додаткові $s2 шкоди або зцілити на $s1, відповідно до вашої цілі." },
    { en = "Shield an ally for $405098s2 while channeling a beam of molten flame dealing ${$405098s1*($d/($t1))}  Fire damage over $d to them. If they survive the channel, heal them for $405098s3.", ua = "Захищає союзника щитом на $405098s2, спрямовуючи на нього промінь розплавленого полум'я, що завдає ${$405098s1*($d/($t1))} шкоди вогнем протягом $d. Якщо союзник переживе спрямування, зцілює його на $405098s3." },
    { en = "Grants $256719s1 additional Versatility to a nearby tank-specialized ally bearing the Eye of Shatug.", ua = "Надає $256719s1 додаткової універсальності найближчому союзнику-танку, який носить Око Шатуга." },
    { en = "Summons a Windmill Lance.", ua = "Прикликає Вітрякову Списа." },
    { en = "Your ranged spells and abilities have a chance to launch a glob of water at an enemy dealing $s1 Frost damage to them and 4 other enemies within $472337A1 yd of them.", ua = "Ваші далекобійні закляття та здібності мають шанс випустити кулю води в ворога, завдаючи $s1 шкоди льодом йому та 4 іншим ворогам у радіусі $472337A1 ярдів від нього." },
    { en = "Reduces the base mana cost of your spells by $s1.", ua = "Зменшує базову вартість мани ваших заклять на $s1." },
    { en = "$?a467492[$@spelldesc467492]?a467497[$@spelldesc467497][$@spelldesc467492]", ua = "$?a467492[$@spelldesc467492]?a467497[$@spelldesc467497][$@spelldesc467492]" },
    { en = "Unleash the fel energy stored within the crystal, sacrificing $s1 of your health to infuse a target ally for $1255200d, absorbing $1266821s2 damage.", ua = "Вивільняє скверну, що зберігається в кристалі, жертвуючи $s1 вашого здоров'я, щоб наповнити нею цільового союзника на $1255200d, поглинаючи $1266821s2 шкоди." },
    { en = "Your melee attacks have a chance to trigger a Fel Cleave, dealing $184248s1 damage to all enemies in front of you.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші ближні атаки мають шанс викликати Скверний Розтин, завдаючи $184248s1 шкоди всім ворогам перед вами. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage you have a chance to gain $118867s1 critical strike for $118867d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $118867s1 критичного удару на $118867d." },
    { en = "Your melee attacks have a chance to grant Blessing of the Celestials, increasing your Strength by $128986s1 for $128986d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші ближні атаки мають шанс надати Благословення Небожителів, підвищуючи вашу силу на $128986s1 на $128986d. ($h% шанс, ${$proccooldown} сек. перезарядка)" },
    { en = "Use your accumulated knowledge to strike when the time is right, granting $444958s2 Intellect per report for $d and consuming their passive effect.", ua = "Використайте накопичені знання, щоб завдати удару в потрібну мить, отримуючи $444958s2 інтелекту за кожен звіт на $d та поглинаючи їхній пасивний ефект." },
    { en = "Your attacks have a chance to release toxic parasites that burst around you, dealing $s1 Nature damage split among nearby enemies and healing you for $s2.", ua = "Ваші атаки мають шанс випустити токсичних паразитів, що вибухають довкола вас, завдаючи $s1 шкоди силами природи, розподіленої між найближчими ворогами, та зцілюючи вас на $s2." },
    { en = "Your melee attacks grant $91810s1 Strength.   Lasts $91810d, stacking up to $91810u times.", ua = "Ваші ближні атаки надають $91810s1 сили. Триває $91810d, накопичується до $91810u разів." },
    { en = "Channel for $1241801s5 sec to invoke the wrath of the idol, increasing your Critical Strike by $1241801s1 for $1241806d. The force slams the earth, dealing $1241801s2 Nature damage to all nearby enemies and increasing Critical Strike by $1241801s3 per enemy hit, up to a maximum of $1241801s4.", ua = "Спрямовуйте протягом $1241801s5 сек., щоб прикликати гнів ідола, підвищуючи ваш критичний удар на $1241801s1 на $1241806d. Сила вдаряє об землю, завдаючи $1241801s2 шкоди силами природи всім найближчим ворогам і підвищуючи критичний удар на $1241801s3 за кожного враженого ворога, максимум до $1241801s4." },
    { en = "Your melee and ranged critical strikes have a chance to grant $92096s1 Agility for $92096d.", ua = "Ваші критичні ближні та далекобійні атаки мають шанс надати $92096s1 спритності на $92096d." },
    { en = "Increase Versatility by $s1 for $d.", ua = "Підвищує універсальність на $s1 на $d." },
    { en = "Redirect the life force of an enemy, increasing your Intellect by up to $s2 for $d. This grants more Intellect when used against targets at high health.", ua = "Перенаправляє життєву силу ворога, підвищуючи ваш інтелект до $s2 на $d. Надає більше інтелекту, коли застосовується проти цілей з високим здоров'ям." },
    { en = "Your direct healing and heal over time spells have a chance to increase your haste by $127915s1 for $127915d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші прямі та поступові зцілювальні закляття мають шанс підвищити вашу швидкість на $127915s1 на $127915d. ($h% шанс, ${$proccooldown} сек. перезарядка)" },
    { en = "Flings a magical boomerang towards target enemy dealing $s1 damage and has a chance to stun or disarm them.", ua = "Кидає магічний бумеранг у вибраного ворога, завдаючи $s1 шкоди, та має шанс оглушити чи роззброїти його." },
    { en = "Falling below $s1% health grants you Warlord's Fortitude, increasing your health by $s2 and your Mastery by $s4 for $214624d.\n\n\n\nThis may only occur once every $214648d.", ua = "Падіння здоров'я нижче $s1% надає вам Стійкість Воєначальника, підвищуючи ваше здоров'я на $s2 та майстерність на $s4 на $214624d.\n\n\n\nЦе може статися лише раз на $214648d." },
    { en = "Your attacks have a chance to let loose a flurry of mystic texts, increasing your Haste by $235021s1 for $235021d.", ua = "Ваші атаки мають шанс випустити шквал містичних текстів, підвищуючи вашу швидкість на $235021s1 на $235021d." },
    { en = "Your attacks have a high chance to unleash a cosmic onslaught, dealing ${$s1*$<rolemult>} Cosmic damage to your target. \n\n\n\nDamage increased by $s3% for every 1% health the target is missing, and nearby enemies take $s4% of the damage dealt split between them.", ua = "Ваші атаки мають високий шанс розв'язати космічний натиск, завдаючи ${$s1*$<rolemult>} космічної шкоди вашій цілі. \n\n\n\nШкода збільшується на $s3% за кожен відсоток здоров'я, якого бракує цілі, а найближчі вороги отримують $s4% завданої шкоди, розподіленої між ними." },
    { en = "Drive a spike into your target, dealing $s1 Physical damage and creating a chain link between you for $d. While the chain persists, $s2% of all damage dealt to the target is stored within it, up to a maximum of $s3.\n\n\n\nMoving away from your target will rip the chain out, dealing the stored amount as Shadow damage to all enemies within $s4 yds of them.", ua = "Вбиває шип у вашу ціль, завдаючи $s1 фізичної шкоди та створюючи ланцюговий зв'язок між вами на $d. Поки ланцюг тримається, $s2% усієї шкоди, завданої цілі, накопичується в ньому, максимум до $s3.\n\n\n\nВіддалення від цілі вириває ланцюг, завдаючи накопиченої кількості як тіньової шкоди всім ворогам у радіусі $s4 ярдів від неї." },
    { en = "Increases the damage done by your Mongoose Bite by $s1%.", ua = "Підвищує шкоду, завдану вашим Укусом Мангуста, на $s1%." },
    { en = "Consume all Gathering Clouds, creating a Raging Storm for $d that heals up to 5 nearby allies every 1 sec for $215293s1 health per Gathering Cloud consumed.", ua = "Поглинає всі Збірні Хмари, створюючи Лютий Шторм на $d, що зцілює до 5 найближчих союзників щосекунди на $215293s1 здоров'я за кожну поглинуту Збірну Хмару." },
    { en = "Taking damage grants you a chance to unleash the First Technique for $d, reflecting $s2% of incoming damage, up to a maximum of ${$s1*(1+$@versadmg)} damage absorbed.", ua = "Отримання шкоди дає шанс застосувати Першу техніку на $d, відбиваючи $s2% вхідної шкоди, до максимуму ${$s1*(1+$@versadmg)} поглинутої шкоди." },
    { en = "Listen to the Whispers of L'ura for $d, granting the chance for your healing spells to heal for an additional $250781s1.", ua = "Прислухайтеся до Шепоту Л'ури на $d, надаючи вашим зцілювальним заклять шанс зцілити додатково на $250781s1." },
    { en = "Your healing spells and abilities have a chance to increase your Mastery by $s1 for $1259228d1.\n\nIf this occurs while healing an ally below 40% health, grant double the mastery.\n\n\n\nCan only occur once every $1259741d1.", ua = "Ваші зцілювальні закляття та здібності мають шанс підвищити вашу майстерність на $s1 на $1259228d1.\n\nЯкщо це стається під час зцілення союзника зі здоров'ям нижче 40%, надається подвійна майстерність.\n\n\n\nМоже статися лише раз на $1259741d1." },
    { en = "Your attacks have a chance to summon a cannon for $d that will fire at enemies in front of it.", ua = "Ваші атаки можуть прикликати на $d гармату, що стрілятиме по ворогах перед нею." },
    { en = "Trunksy does a Mud Dive, inflicting $s1 Nature damage divided evenly among enemies within 8 yards of the target.", ua = "Хоботко виконує Грязьовий пірнок, завдаючи $s1 одиниць шкоди Природою, що порівну ділиться між ворогами в межах 8 метрів від цілі." },
    { en = "After $227389d, gain $s2 Critical Strike, Haste, Mastery, or Versatility for $227390d. You may reactivate this once within $227389d to change which bonus will be granted. (2 min cooldown)", ua = "Через $227389d отримуєте $s2 критичного удару, швидкості, майстерності або універсальності на $227390d. Ви можете повторно активувати це раз протягом $227389d, щоб змінити, який бонус буде надано. (2 хв. перезарядка)" },
    { en = "Mr. Munchykins serves a friendly target tea, granting $s1 Haste for $d.", ua = "Пан Ласунчик подає дружній цілі чай, надаючи $s1 швидкості на $d." },
    { en = "Rip magical essence out of your target and consume it dealing ${$s1*$<rolemult>} Arcane damage while granting you $1247205s1 of your lowest secondary stat for $1247207d.\n\n\n\nIf the target was an Ethereal, your highest secondary stat is increased instead.", ua = "Вириває магічну сутність із вашої цілі та поглинає її, завдаючи ${$s1*$<rolemult>} шкоди силами тайнощів і надаючи вам $1247205s1 вашої найнижчої вторинної характеристики на $1247207d.\n\n\n\nЯкщо ціль була Ефірною, замість цього підвищується ваша найвища вторинна характеристика." },
    { en = "Invoke the litany to apply Beacon of Lightblind Wrath to an enemy for $d. Your next $u harmful spells call down a blast of Light to deal $1258275s1 Holy damage to the target.\n\n\n\n$1263727i injured allies are shielded for the same amount, absorbing $1263727s2% of damage taken while the shield holds.", ua = "Прикликає літанію, щоб накласти на ворога Маяк світлосліпого гніву протягом $d. Ваші наступні $u шкідливих заклять закликають спалах Світла, що завдає цілі $1258275s1 Священної шкоди.\n\n\n\n$1263727i поранених союзників отримують щит на ту саму величину, поглинаючи $1263727s2% отриманої шкоди, доки щит тримається." },
    { en = "$?!a303042[Declare Edict of the Sea Witch, causing this ability to instead absorb Magic damage][Declare Edict of the Myrmidon, causing this ability to instead absorb Physical damage] and resetting Fanaticism.", ua = "$?!a303042[Проголошує Едикт Морської Відьми, через що ця здатність натомість поглинає магічну шкоду][Проголошує Едикт Мірмідона, через що ця здатність натомість поглинає фізичну шкоду] та скидає Фанатизм." },
    { en = "Mark a friendly player with Guiding Hand, healing them for $s1 every ${$t1}.1 sec for $d. If they fall below $s2% health, Guiding Hand is consumed to grant them a shield that prevents ${(1+$@versadmg)*$242623s1} damage for $242623d. (2 min recharge, 2 charges)", ua = "Позначає дружнього гравця Скеровною Рукою, зцілюючи його на $s1 кожні ${$t1}.1 сек. протягом $d. Якщо його здоров'я падає нижче $s2%, Скеровна Рука поглинається, щоб надати йому щит, що відвертає ${(1+$@versadmg)*$242623s1} шкоди на $242623d. (2 хв. перезарядка, 2 заряди)" },
    { en = "Taking damage has a chance to restore $s1 mana.", ua = "Отримання шкоди має шанс відновити $s1 мани." },
    { en = "Your attacks have a high chance to charge the Arcanocore. At $1240896u charges, deploy a sentinel to arcanoblast your target for ${$s1*$<rolemult>} Arcane damage split between nearby enemies. Recover $s2 charges if only one enemy is struck.\n\n\n\n$@spelldesc1240903", ua = "Ваші атаки мають високий шанс зарядити Арканоядро. За $1240896u зарядів розгортається вартовий, що б'є вашу ціль аркановибухом на ${$s1*$<rolemult>} шкоди Тайнощів, розподіленої між найближчими ворогами. Відновлює $s2 зарядів, якщо вражено лише одного ворога.\n\n\n\n$@spelldesc1240903" },
    { en = "Your spells have a chance to invigorate the star, increasing your Intellect by $429221s1 for $429221d.", ua = "Ваші закляття мають шанс наснажити зірку, підвищуючи ваш інтелект на $429221s1 на $429221d." },
    { en = "When you deal spell damage, you have a chance to gain Blessing of the Celestials, increasing your Intellect by $128984s1 for $128984d.", ua = "Коли ви завдаєте шкоди заклять, маєте шанс отримати Благословення Небожителів, підвищуючи ваш інтелект на $128984s1 на $128984d." },
    { en = "Infuses you with Arcane energy, causing your next Arcane Shot fired within $d to detonate at the target. The Arcane Detonation will deal $23722s1 damage to enemies near the target.", ua = "Наповнює вас енергією тайнощів, через що ваш наступний Тайний Постріл, випущений протягом $d, детонує на цілі. Тайна Детонація завдасть $23722s1 шкоди ворогам поблизу цілі." },
    { en = "Grants ${$m1*10} armor, decreasing by $s1 every $t2 sec.  Lasts $d.", ua = "Надає ${$m1*10} броні, що зменшується на $s1 кожні $t2 сек. Триває $d." },
    { en = "Your damaging attacks and abilities have a chance to grant $128521s1 mastery for $128521d.", ua = "Ваші атаки та здібності, що завдають шкоди, мають шанс надати $128521s1 майстерності на $128521d." },
    { en = "Call upon Ashjra'kamas, Shroud of Resolve to slow your falling speed for $d.", ua = "Прикличте Ашджра'камас, Покров Рішучості, щоб уповільнити швидкість вашого падіння на $d." },
    { en = "Your harmful spells have a chance to increase your spell power by $101291s1 for $101291d.", ua = "Ваші шкідливі заклинання мають шанс підвищити вашу силу заклять на $101291s1 на $101291d." },
    { en = "Your spells and abilities have a chance to grant you $274430s1 Haste or Mastery for $274430d.", ua = "Ваші заклинання та здібності мають шанс надати вам $274430s1 швидкості або майстерності на $274430d." },
    { en = "Your spells and abilities have a chance to grant you $268602s1 Mastery for $268602d.", ua = "Ваші заклинання та здібності мають шанс надати вам $268602s1 майстерності на $268602d." },
    { en = "Your melee and ranged attacks have a chance to grant $120256s1 mastery for $120256d.", ua = "Ваші ближні та дальні атаки мають шанс надати $120256s1 майстерності на $120256d." },
    { en = "Casting spells and abilities has a chance to grant you a stack of Domineering Arrogance up to $411661u.\n\n\n\n$?a137040[Summoning your Fire or Storm Elemental][]$?a137041[Summoning your Feral Spirit][]$?a137039[Summoning your Healing Tide, Mana Tide, or Spirit Link Totem][]$?a137022[Invoking your Celestial][]$?a137046[Summoning your Infernal][]$?a137044[Summoning your Demonic Tyrant][]$?a137043[Summoning your Darkglare][]$?a137017[Casting Coordinated Assault][]$?a137016[Casting Trueshot][]$?a137015[Casting Bestial Wrath][]$?a137047|a137034|a137030|a137026|a137018|a353167|a137009|a212611|a137005[Using your major cooldown][] grants you $s1 $pri per stack and reduces your movement speed by $s2% for $403380d.", ua = "Застосування заклять і вмінь має шанс надати вам заряд Деспотичної Зарозумілості, до $411661u.\n\n\n\n$?a137040[Прикликання Вогняного чи Грозового елементаля][]$?a137041[Прикликання Дикого духа][]$?a137039[Прикликання тотема Цілющого припливу, Припливу мани чи Зв'язку духів][]$?a137022[Прикликання Небожителя][]$?a137046[Прикликання Інфернала][]$?a137044[Прикликання Демонічного тирана][]$?a137043[Прикликання Темнозора][]$?a137017[Застосування Узгодженого штурму][]$?a137016[Застосування Влучного пострілу][]$?a137015[Застосування Звіриної люті][]$?a137047|a137034|a137030|a137026|a137018|a353167|a137009|a212611|a137005[Застосування головного вміння з відновленням][] надає вам $s1 $pri за заряд і знижує вашу швидкість пересування на $s2% на $403380d." },
    { en = "Your melee attacks have a chance to deal $214169s1 Physical damage and increase all damage the target takes from you by $214169s2% for $214169d, up to $214169s3 extra damage dealt.", ua = "Ваші ближні атаки мають шанс завдати $214169s1 фізичної шкоди та підвищити всю шкоду, якої ціль зазнає від вас, на $214169s2% на $214169d, до $214169s3 додаткової завданої шкоди." },
    { en = "Chance on melee attack to grant Demonbane, increasing Strength by $201405s1 and all damage against Demons by $201405s2% for $201405d. If you score a killing blow while this effect is active, its duration is extended by $201597s1 sec up to the original duration.", ua = "Шанс під час ближньої атаки надати Погибель Демонів, що підвищує силу на $201405s1 і всю шкоду проти демонів на $201405s2% на $201405d. Якщо ви завдаєте смертельного удару, поки цей ефект активний, його тривалість продовжується на $201597s1 сек., але не довше за початкову тривалість." },
    { en = "Cover yourself with $u Hellsteel Plates, reducing damage taken by $400962s1 and your movement speed by $400962s2% per plate, for $400986d2. \n\n\n\nTaking $400962s5 damage ruptures one plate, removing it and releasing forth a pillar of Shadowflame that deals $400962s4 damage to all enemies in its path. This effect may only occur once every $400962s6 sec. Upon expiration, all remaining plates rupture.", ua = "Вкрийтеся $u пекельносталевими пластинами, що зменшують отримувану шкоду на $400962s1 та вашу швидкість пересування на $400962s2% за кожну пластину, на $400986d2. \n\n\n\nОтримання $400962s5 шкоди розколює одну пластину, прибираючи її та вивільняючи стовп тінеполум'я, що завдає $400962s4 шкоди всім ворогам на своєму шляху. Цей ефект може спрацьовувати не частіше ніж раз на $400962s6 сек. Після завершення всі пластини, що залишилися, розколюються." },
    { en = "Restores $s2 health and mana to a friendly target and attempts to dispel any polymorph effects from them.  Reduced effectiveness against polymorph effects from casters of level $ctrmin2066 and higher.", ua = "Відновлює $s2 здоров'я та мани союзній цілі й намагається розвіяти з неї будь-які ефекти перевтілення. Знижена дієвість проти ефектів перевтілення від чаклунів рівня $ctrmin2066 та вище." },
    { en = "$@spelldesc1254520\n\n\n\n$@spelldesc1254514", ua = "$@spelldesc1254520\n\n\n\n$@spelldesc1254514" },
    { en = "Reflects Fire and Frost spells back at their caster for $d.", ua = "Відбиває заклинання вогню та морозу назад у того, хто їх наклав, на $d." },
    { en = "Your spells have a chance to grant $90896s1 spell power for $90896d.", ua = "Ваші заклинання мають шанс надати $90896s1 сили заклять на $90896d." },
    { en = "Your healing and damaging spells have a chance to grant $122309s1 mastery for $122309d.", ua = "Ваші заклинання зцілення та шкоди мають шанс надати $122309s1 майстерності на $122309d." },
    { en = "Your ranged attacks have a chance to inject a paralytic venom into the target, dealing ${$<rolemult>*$s1} Nature damage over $449892d.\n\n\n\nEach second the target is moving while affected grants you ${$s2/$449895u} Haste for $449895d stacking up to $449895u times.", ua = "Ваші дальні атаки мають шанс впорснути в ціль паралітичну отруту, що завдає ${$<rolemult>*$s1} шкоди від сил природи протягом $449892d.\n\n\n\nЗа кожну секунду, поки уражена ціль рухається, ви отримуєте ${$s2/$449895u} швидкості на $449895d, накопичуючись до $449895u разів." },
    { en = "Supercharge yourself and increase your Haste by $1216773s1 for $1216770d1. The first ally you heal directly is also charged, increasing their Haste by $1216773s2 for $1216774d1.", ua = "Перезаряджає вас і підвищує вашу швидкість на $1216773s1 на $1216770d1. Перший союзник, якого ви зцілюєте напряму, також заряджається, що підвищує його швидкість на $1216773s2 на $1216774d1." },
    { en = "Increases Stamina by $s3 and reduces physical damage taken by $20590s1 for $d. However, lowers Strength and Agility by $s1 and increases magical damage taken by up to $20590s2.", ua = "Підвищує витривалість на $s3 і зменшує отримувану фізичну шкоду на $20590s1 на $d. Однак знижує силу та спритність на $s1 і підвищує отримувану магічну шкоду до $20590s2." },
    { en = "Your melee and ranged attacks have a chance to grant $118873s1 critical strike for $118873d.", ua = "Ваші ближні та дальні атаки мають шанс надати $118873s1 критичного удару на $118873d." },
    { en = "You gain Nalorakk's Favor of Growth. Your healing spells and abilities have a chance to instantly heal your target for $s1 and spawn a glowing mushroom near them that lasts for $1264294d.\n\n\n\nIf an ally steps on and consumes the mushroom, they are healed for an additional $s2.", ua = "Ви отримуєте Прихильність Росту Налораккса. Ваші заклинання та здібності зцілення мають шанс миттєво зцілити вашу ціль на $s1 і виростити поряд із нею сяйливий гриб, що існує $1264294d.\n\n\n\nЯкщо союзник наступить на гриб і спожиє його, він зцілюється ще на $s2." },
    { en = "Grants $s1 haste, and reduces the mana cost of Rejuvenation, Healing Touch, Regrowth, and Tranquility by $s2% for $d.", ua = "Надає $s1 швидкості та зменшує витрати мани Омолодження, Зцілювального Дотику, Відновлення та Спокою на $s2% на $d." },
    { en = "Each time your Corruption deals damage, it has a $h% chance to grant you $40480s1 spell power for $40480d.", ua = "Щоразу, коли ваше Псування завдає шкоди, воно має $h% шанс надати вам $40480s1 сили заклять на $40480d." },
    { en = "Your abilities have a low chance to grant Fall of Night, increasing your Haste by $s1 for $339342d. When Fall of Night expires, your Haste is reduced by $s2 for $339341d.", ua = "Ваші здібності мають низький шанс надати Падіння Ночі, що підвищує вашу швидкість на $s1 на $339342d. Коли Падіння Ночі завершується, ваша швидкість знижується на $s2 на $339341d." },
    { en = "Copies the wearer's current flask buff but at a fraction of the power. Lasts $265442d.", ua = "Копіює поточне підсилення від флакона власника, але з часткою його потужності. Триває $265442d." },
    { en = "Your attacks have a chance to grant you Nightwell Energy, stacking up to $214572u times.", ua = "Ваші атаки мають шанс надати вам Енергію Нічного Колодязя, накопичуючись до $214572u разів." },
    { en = "Each time you cast a helpful spell, you gain $67739s1 spell power.  Stacks up to $67739u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви накладаєте допоміжне заклинання, ви отримуєте $67739s1 сили заклять. Накопичується до $67739u разів. Увесь ефект триває $d." },
    { en = "Tap into the power of the skull, increasing Haste by $s1 for $d.", ua = "Зачерпніть силу черепа, підвищивши швидкість на $s1 на $d." },
    { en = "Accept the storm, becoming a Primal Air Elemental and immobilizing yourself for $d.\n\n\n\nWhile in this form, the winds around you deal $382092s1 Nature damage per second to all enemies within $s5 yards, intensifying by $s4% each second until the transformation subsides.", ua = "Прийміть бурю, ставши Первісним Елементалем Повітря та знерухомивши себе на $d.\n\n\n\nУ цій формі вітри довкола вас завдають $382092s1 шкоди від сил природи щосекунди всім ворогам у межах $s5 ярдів, посилюючись на $s4% щосекунди, поки перетворення не вщухне." },
    { en = "Your melee attacks have a chance to bathe the target in flames for $27655s1 Fire damage.", ua = "Ваші ближні атаки мають шанс охопити ціль полум'ям, завдаючи $27655s1 вогняної шкоди." },
    { en = "Your spells have a chance of releasing spores that grant $s1 Mastery to $s2 nearby allies for $449753d. Any spores that can't find a host grant you $s3% of the Mastery instead.\n\n\n\nActivating this effect by a Nature spell causes one additional spore to be released.", ua = "Ваші заклинання мають шанс вивільнити спори, що надають $s1 майстерності $s2 союзникам поблизу на $449753d. Будь-які спори, що не знайдуть носія, натомість надають вам $s3% майстерності.\n\n\n\nАктивація цього ефекту заклинанням сил природи спричиняє вивільнення однієї додаткової спори." },
    { en = "Your attacks have a chance to inflict $224074s1 Physical damage and stun the target for $224074d.", ua = "Ваші атаки мають шанс завдати $224074s1 фізичної шкоди та оглушити ціль на $224074d." },
    { en = "Surround yourself with wailing souls to prevent $s2% of damage taken for $d, up to ${$s1*(1+$@versadmg)} total damage. The cooldown of this ability is reduced by up to $s3 sec, based on the amount of damage absorbed.", ua = "Оточіть себе тужливими душами, щоб запобігти $s2% отримуваної шкоди на $d, до ${$s1*(1+$@versadmg)} шкоди загалом. Час відновлення цієї здібності зменшується до $s3 сек. залежно від обсягу поглинутої шкоди." },
    { en = "Places a Rift Portal in front of you that charges for $d before unleashing a blast of ${$368775s1*(1+$@versadmg)} Cosmic damage split between enemies in a line. The portal plunders reality itself, granting you a shield for $368810d which absorbs ${$368775s2*(1+$@versadmg)} damage.\n\n\n\nDamage and absorption are increased for each enemy struck, up to $368775s3 enemies.", ua = "Розміщує перед вами Портал Розриву, який заряджається $d, а потім вивільняє вибух ${$368775s1*(1+$@versadmg)} космічної шкоди, розподіленої між ворогами на лінії. Портал грабує саму реальність, надаючи вам щит на $368810d, що поглинає ${$368775s2*(1+$@versadmg)} шкоди.\n\n\n\nШкода та поглинання зростають за кожного враженого ворога, до $368775s3 ворогів." },
    { en = "Increases your critical strike by $s1 for $d1.", ua = "Підвищує ваш критичний удар на $s1 на $d1." },
    { en = "Throw the powder, reducing the threat you generate by $s1% for $d.", ua = "Киньте порошок, зменшивши загрозу, яку ви створюєте, на $s1% на $d." },
    { en = "Embrace the fel energies contained within.", ua = "Увібрати скверні енергії, що містяться всередині." },
    { en = "Chance to strike your enemies for $89087s1 Nature damage when dealing damage with melee or ranged attacks.", ua = "Шанс уразити ваших ворогів на $89087s1 шкоди від сил природи під час завдання шкоди ближніми чи дальніми атаками." },
    { en = "Your autoattacks have a chance to increase your Critical Strike by $253307s1 for $253307d.", ua = "Ваші автоатаки мають шанс підвищити ваш критичний удар на $253307s1 на $253307d." },
    { en = "Arcane Power also increases the damage and reduces the cast time and global cooldown of Arcane Blast by $s1%.", ua = "Чародійна Міць також збільшує шкоду та зменшує час прочитання й глобальний відкат Чародійного Вибуху на $s1%." },
    { en = "Your direct healing and heal over time spells have a chance to increase your haste by $101289s1 for 10 secs.", ua = "Ваші заклинання прямого зцілення та зцілення з часом мають шанс підвищити вашу швидкість на $101289s1 на 10 сек." },
    { en = "The Bashful Book may read an excerpt from an Unpublished Steamy Romance Novel to the target of your spells, dealing ${$<rolemult>*$s1} Arcane damage or $s2 healing every $1216424t1 sec for $1216424d.\n\n\n\nIf the target dies before the story is finished, the ending will be spoiled for a nearby target, dealing what remains instantly.", ua = "Сором'язлива Книга може зачитати уривок з Невиданого Жагучого Любовного Роману цілі ваших заклять, завдаючи ${$<rolemult>*$s1} чародійної шкоди або зцілюючи на $s2 кожні $1216424t1 сек протягом $1216424d.\n\n\n\nЯкщо ціль гине до завершення оповіді, кінцівку буде розкрито найближчій цілі, миттєво завдавши їй усе, що лишилося." },
    { en = "Gain $s1 Haste and $s2 Speed for $d.", ua = "Дає $s1 швидкості та $s2 прискорення на $d." },
    { en = "Reduces the base mana cost of your spells by $191615s1-$191622s1. The amount of mana reduction depends on the topmost card in the deck.", ua = "Зменшує базову вартість мани ваших заклять на $191615s1-$191622s1. Величина зменшення мани залежить від верхньої карти в колоді." },
    { en = "Quickens the mind, increasing the Mage's haste by $s1 for $d.", ua = "Загострює розум, підвищуючи швидкість мага на $s1 протягом $d." },
    { en = "Your damaging abilities have a very low chance to summon a Leviathan, inflicting ${$s2*(1+$@versadmg)} Physical damage to your target.\n\n\n\nDealing damage also cultivates luminous algae on your target, increasing your chance to summon.", ua = "Ваші здібності, що завдають шкоди, мають дуже малий шанс прикликати Левіафана, що завдає ${$s2*(1+$@versadmg)} фізичної шкоди вашій цілі.\n\n\n\nЗавдаючи шкоди, ви також вирощуєте на цілі сяйливі водорості, підвищуючи свій шанс прикликання." },
    { en = "Your damaging abilities have a chance to deal $s1 Holy damage to your target while above $s3% health, or heal you for $s2 health while below $s3% health.", ua = "Ваші здібності, що завдають шкоди, мають шанс завдати $s1 свячої шкоди вашій цілі, доки ваше здоров'я вище за $s3%, або зцілити вас на $s2 здоров'я, доки воно нижче за $s3%." },
    { en = "Wind up, then unleash a cataclysmic punch upon your target, dealing $s2 Physical damage, $s1 Fire damage, and knocking them up.", ua = "Замахуєтеся, а тоді обрушуєте катаклізмічний удар по цілі, завдаючи $s2 фізичної шкоди, $s1 вогняної шкоди та підкидаючи її в повітря." },
    { en = "Increases agility by $s1 for $d.", ua = "Підвищує спритність на $s1 протягом $d." },
    { en = "Mayor Striggs absorbs $s1 damage over $d.", ua = "Мер Стріґз поглинає $s1 шкоди протягом $d." },
    { en = "Your healing effects have a chance to apply a charge of Highfather's Timekeeping for $253287d, max $253287u charges. When the ally falls below $s1% health, Highfather's Timekeeping is consumed to instantly heal them for $253288s1 health per charge.", ua = "Ваші ефекти зцілення мають шанс накласти заряд Хронометражу Праотця на $253287d, щонайбільше $253287u зарядів. Коли здоров'я союзника падає нижче за $s1%, Хронометраж Праотця витрачається, щоб миттєво зцілити його на $253288s1 здоров'я за кожен заряд." },
    { en = "Your damage and healing has a chance to grant you Alnsight for $1266686d. While active, casting spells and abilities manifests unstable Alnscorned and consumes their essence to grant you $s1 $pri for $1266687d. Multiple applications may overlap.", ua = "Ваша шкода й зцілення мають шанс надати вам Бачення Алну на $1266686d. Поки воно активне, застосування заклять і здібностей породжує нестабільних Алнозневажених і поглинає їхню сутність, надаючи вам $s1 $pri на $1266687d. Кілька застосувань можуть накладатися." },
    { en = "Places Egg Shell on your current target, absorbing $s1 damage.  While Egg Shell persists, you will gain $91306s1 mana every $t2 sec.  When the effect is cancelled, you gain $91305s1 mana.  Lasts $d.", ua = "Накладає Яєчну Шкаралупу на вашу поточну ціль, поглинаючи $s1 шкоди. Поки Яєчна Шкаралупа діє, ви отримуєте $91306s1 мани кожні $t2 сек. Коли ефект скасовується, ви отримуєте $91305s1 мани. Триває $d." },
    { en = "Increases Spell Power by up to $s1 for $d.", ua = "Підвищує силу заклять до $s1 протягом $d." },
    { en = "Increases spell power by $s1, and increases mana cost of spells by $s3% for $d.", ua = "Підвищує силу заклять на $s1 та збільшує вартість мани заклять на $s3% протягом $d." },
    { en = "Heals you for $s1 health whenever you kill a target that yields experience or honor.", ua = "Зцілює вас на $s1 здоров'я щоразу, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Channel the coaglam's power, concentrating all current shadow energy to shield your target.", ua = "Підтримує силу коаґлама, зосереджуючи всю наявну тіньову енергію в щит для вашої цілі." },
    { en = "When struck you have a chance to reduce all damage taken by $469931s1 for $469931d.", ua = "Коли вас б'ють, ви маєте шанс зменшити всю отриману шкоду на $469931s1 протягом $469931d." },
    { en = "Your damaging and healing abilities have a chance to grant you Call of the Alliance, increasing your highest secondary stat by $s2 for 10 sec.", ua = "Ваші здібності, що завдають шкоди та зцілюють, мають шанс надати вам Поклик Альянсу, підвищуючи вашу найвищу вторинну характеристику на $s2 протягом 10 сек." },
    { en = "Absorbs up to $m1 damage every time you take physical damage, up to a maximum of ${$m1*5} damage absorbed.", ua = "Поглинає до $m1 шкоди щоразу, коли ви отримуєте фізичну шкоду, щонайбільше ${$m1*5} поглиненої шкоди." },
    { en = "Reduce the damage you take by $s1% for $d until your Psychic Shell has taken $s2 total damage.", ua = "Зменшує отриману вами шкоду на $s1% протягом $d, доки ваш Психічний Панцир не поглине загалом $s2 шкоди." },
    { en = "Increases Fire resistance by $s2 and reduces all Fire damage taken by up to $s1 for $d.", ua = "Підвищує опір вогню на $s2 та зменшує всю отриману вогняну шкоду до $s1 протягом $d." },
    { en = "Slow your current enemy target's attack and casting speed by $s% for $d.", ua = "Сповільнює швидкість атаки та прочитання поточної ворожої цілі на $s% протягом $d." },
    { en = "Blocking, parrying, or dodging has a chance to awaken the Gauze causing it to lash out dealing $s1 Arcane damage split between nearby enemies while shielding you for $s2 damage for $1245431d.", ua = "Блокування, парирування чи ухиляння мають шанс пробудити Серпанок, змушуючи його вдарити, завдаючи $s1 чародійної шкоди, розподіленої між ближніми ворогами, і водночас захищаючи вас щитом на $s2 шкоди протягом $1245431d." },
    { en = "Increases resistance to Arcane, Fire, Frost, Nature, and Shadow spells by $s1 for $d.", ua = "Підвищує опір чародійним, вогняним, крижаним, природним і тіньовим закляттям на $s1 протягом $d." },
    { en = "Your melee attacks have a chance to coalesce a warpstalker echo to strike with you, inflicting ${$<rolemult>*$s1} Arcane damage split between enemies in its path.", ua = "Ваші атаки ближнього бою мають шанс згустити відлуння викривлоскрада, що б'є разом з вами, завдаючи ${$<rolemult>*$s1} чародійної шкоди, розподіленої між ворогами на його шляху." },
    { en = "Summon an Unstable Arcane Rune at your location for $d. While standing within, you or your party members gain power but suffer its corruption, increasing primary stat by $391290s1 and decreasing Critical Strike by $391290s2.", ua = "Прикликає Нестабільну Чародійну Руну у вашому місці перебування на $d. Перебуваючи в ній, ви або члени вашої групи отримують міць, але страждають від її скверни: первинна характеристика підвищується на $391290s1, а критичний удар знижується на $391290s2." },
    { en = "Prevents $s2% of all damage taken for $d. Can absorb a maximum of ${$s1*(1+$@versadmg)} damage.", ua = "Відвертає $s2% усієї отриманої шкоди протягом $d. Може поглинути щонайбільше ${$s1*(1+$@versadmg)} шкоди." },
    { en = "Your melee attacks have a chance to crank the launcher's gears, decreasing its cooldown by $s1 sec and heating up your weapon which causes your next attack to inflict ${$<rolemult>*$s2} additional Fire damage.", ua = "Ваші атаки ближнього бою мають шанс накрутити шестерні пускача, зменшуючи його відкат на $s1 сек і розігріваючи вашу зброю, через що ваша наступна атака завдає ${$<rolemult>*$s2} додаткової вогняної шкоди." },
    { en = "Your attacks have a chance to grant $176914s1 Haste for $176914d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176914s1 швидкості протягом $176914d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "During combat you have a chance to become consumed by Fanatical Inspiration, increasing your highest secondary by $s1 for $1266299d.\n\n\n\nParty members also equipped with the keepsake have their lowest secondary increased by $s2 for $1266300d.", ua = "У бою ви маєте шанс бути охопленими Фанатичним Натхненням, що підвищує вашу найвищу вторинну характеристику на $s1 протягом $1266299d.\n\n\n\nЧлени групи, які також екіпірували пам'ятну річ, отримують підвищення найнижчої вторинної характеристики на $s2 протягом $1266300d." },
    { en = "Reflects Shadow spells back at their caster for $d.  Chance to be resisted when used by players over level $ctrmax2067.", ua = "Відбиває закляття темряви назад у того, хто їх наклав, протягом $d. Існує ймовірність опору, коли застосовується гравцями, вищими за рівень $ctrmax2067." },
    { en = "Your attacks have a chance to unleash a remnant of Azshara's torment, dealing $s2 shadow damage to all nearby enemies and granting you Unleashed Agony, increasing the damage of this effect by $s4%. Upon reaching 12 stacks of Unleashed Agony, they are consumed to deal $313089s1 Shadow damage to all nearby enemies.", ua = "Ваші атаки мають шанс вивільнити рештки Муки Азшари, завдаючи $s2 тіньової шкоди всім ближнім ворогам і надаючи вам Вивільнену Агонію, що підвищує шкоду цього ефекту на $s4%. Досягнувши 12 зарядів Вивільненої Агонії, вони витрачаються, щоб завдати $313089s1 тіньової шкоди всім ближнім ворогам." },
    { en = "Transform to Eye of F'harg.", ua = "Перетворення на Око Ф'харґа." },
    { en = "Chance on spell critical hit to increase your spell power by $34321s1 for $34321d.", ua = "Шанс при критичному влучанні закляттям підвищити вашу силу заклять на $34321s1 протягом $34321d." },
    { en = "Enter a primal rage, dealing $<damage> Physical damage split among nearby enemies over $d. Deals increased damage when striking multiple targets. You cannot move or use abilities during your rage.", ua = "Впадаєте в первісну лють, завдаючи $<damage> фізичної шкоди, розподіленої між ворогами поблизу, протягом $d. Завдає підвищеної шкоди, вражаючи кількох цілей. Під час люті ви не можете рухатися чи використовувати здібності." },
    { en = "Draw a set of aqueous spheres towards you that envelop you on contact, increasing your Mastery by $429262s1 for $429262d, stacking up to $429262u times.", ua = "Притягує до вас низку водяних сфер, що огортають вас при контакті, підвищуючи вашу майстерність на $429262s1 протягом $429262d, накопичуючись до $429262u разів." },
    { en = "When you deal damage you have a chance to gain $102748s1 Intellect for $102748d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $102748s1 інтелекту на $102748d." },
    { en = "When you heal you have a chance to gain $109802s1 haste for $109802d.", ua = "Зціляючи, ви маєте шанс отримати $109802s1 швидкості на $109802d." },
    { en = "Empower your weapons for $d, causing your attacks to have a very high chance to deal $s1 Arcane damage.", ua = "Наснажує вашу зброю на $d, надаючи вашим атакам дуже високий шанс завдати $s1 арканної шкоди." },
    { en = "When you deal damage you have a chance to gain $122315s1 critical strike for $122315d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $122315s1 критичного удару на $122315d." },
    { en = "Your melee attacks have a chance to grant $118869s1 mastery for $118869d.", ua = "Ваші атаки в ближньому бою мають шанс надати вам $118869s1 майстерності на $118869d." },
    { en = "Periodically shuffle the deck while in combat.", ua = "Періодично тасує колоду під час бою." },
    { en = "When you deal damage you have a chance to gain $120255s1 critical strike for $120255d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $120255s1 критичного удару на $120255d." },
    { en = "Your attacks and abilities have a chance to grant you ephemeral dragon wings, increasing your Critical Strike by $s1 and your Leech by $s2 for $401469d.", ua = "Ваші атаки та здібності мають шанс надати вам ефемерні драконячі крила, що підвищують ваш критичний удар на $s1 і ваше висмоктування на $s2 на $401469d." },
    { en = "Your spells have a chance to grant you $278359s1 Versatility for $278359d.", ua = "Ваші заклять мають шанс надати вам $278359s1 універсальності на $278359d." },
    { en = "Your spells and abilities have a chance to release an energy orb that bounces between up to $1254534x nearby allies, increasing their Versatility by $s2 for $1254577d. If an ally is below $s3% health, the orb heals them for $s4 instead.", ua = "Ваші заклять і здібності мають шанс випустити кулю енергії, що відскакує між $1254534x найближчими союзниками, підвищуючи їхню універсальність на $s2 на $1254577d. Якщо здоров'я союзника нижче $s3%, куля натомість зцілює його на $s4." },
    { en = "Your healing spells have a high chance to cause you to inject yourself with a charge of $@spellname452816. Multiple charges may overlap.\n\n\n\nIf an ally drops below $s3% health, expel a charge to heal them for $s1. If unconsumed after $452816d, charges catalyze to grant you $s2 Intellect for $452565d instead.", ua = "Ваші закляття зцілення мають високий шанс змусити вас впорснути собі заряд $@spellname452816. Кілька зарядів можуть накладатися.\n\n\n\nЯкщо здоров'я союзника падає нижче $s3%, ви випускаєте заряд, щоб зцілити його на $s1. Якщо заряди не використано через $452816d, вони каталізуються й натомість надають вам $s2 інтелекту на $452565d." },
    { en = "Casting a damaging spell causes your next single target heal to grant $344227s1 Leech for $344227d. This effect may only occur once every $344229d.", ua = "Застосування шкідливого заклять змушує ваше наступне одноцільове зцілення надати $344227s1 висмоктування на $344227d. Цей ефект може спрацьовувати лише раз на $344229d." },
    { en = "Bask a single friendly target in the censer's glow, applying a shield that absorbs up to $s1 damage for $d.", ua = "Огортає одну дружню ціль сяйвом кадильниці, накладаючи щит, що поглинає до $s1 шкоди протягом $d." },
    { en = "Wrap yourself in ritual bandages, absorbing ${$s1*(1+$@versadmg)} damage for $d.", ua = "Огортає вас ритуальними бинтами, що поглинають ${$s1*(1+$@versadmg)} шкоди протягом $d." },
    { en = "Your melee and ranged attacks have a chance to grant $92087s1 Critical Strike for $92087d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $92087s1 критичного удару на $92087d." },
    { en = "Chance on critical hit to increase your attack power by $33649s1 for $33649d.", ua = "Шанс при критичному ударі підвищити вашу силу атаки на $33649s1 на $33649d." },
    { en = "Your melee attacks have a chance to capture the Raw Fury of the Blackwing.", ua = "Ваші атаки в ближньому бою мають шанс полонити Первісну Лють Чорнокрилих." },
    { en = "Your attacks have a chance to grant $176928s1 Versatility for $176928d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176928s1 універсальності на $176928d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Your healing spells grant Inner Eye, increasing Versatility by $92329s1 for $92329d and stacking up to $92329u times.", ua = "Ваші зцілювальні заклять надають Внутрішнє Око, підвищуючи універсальність на $92329s1 на $92329d, що накопичується до $92329u разів." },
    { en = "Rap the leg on the ground, summoning the crew of the Barnacle to aid you in combat for $d.", ua = "Стукає ногою об землю, прикликаючи команду «Морської Жолуді», щоб допомогти вам у бою на $d." },
    { en = "Restores $33743s1 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $33743s1 мани, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше, ніж раз на 10 секунд." },
    { en = "Grants $97131s1 mastery for $97131d each time you deal periodic spell damage, stacking up to $97131u times.", ua = "Надає $97131s1 майстерності на $97131d щоразу, коли ви завдаєте періодичної шкоди закляттям, що накопичується до $97131u разів." },
    { en = "Generates a bolt of lightning to strike an enemy for $s1 Nature damage.  This entire device is made of metal....", ua = "Генерує блискавку, що вражає ворога, завдаючи $s1 шкоди від сил природи. Увесь цей пристрій зроблено з металу...." },
    { en = "When you deal damage you have a chance to gain $102740s1 Strength for $102740d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $102740s1 сили на $102740d." },
    { en = "Your attacks have a chance to call to the pact, exploding for ${$<rolemult>*$s1} Shadow damage split between nearby enemies and increasing your Haste by $s2 for $450962d.\n\n\n\nYour death breaks the pact, causing a violent explosion.", ua = "Ваші атаки мають шанс прикликати пакт, вибухаючи на ${$<rolemult>*$s1} тіньової шкоди, розподіленої між найближчими ворогами, і підвищуючи вашу швидкість на $s2 на $450962d.\n\n\n\nВаша смерть розриває пакт, спричиняючи нищівний вибух." },
    { en = "Your harmful spells grant $109795s1 Intellect for the next $109795d, stacking up to $109795u times.", ua = "Ваші шкідливі заклять надають $109795s1 інтелекту на наступні $109795d, що накопичується до $109795u разів." },
    { en = "Your attacks have a chance to grant you $202836s1 Haste for $202836d.", ua = "Ваші атаки мають шанс надати вам $202836s1 швидкості на $202836d." },
    { en = "Your melee attacks have a chance to summon an elite Axethrower who hurls an axe at your target, inflicting ${$<rolemult>*$s1} Physical damage.", ua = "Ваші атаки в ближньому бою мають шанс прикликати елітного метальника сокир, який жбурляє сокиру у вашу ціль, завдаючи ${$<rolemult>*$s1} фізичної шкоди." },
    { en = "Charges your weapon with a small amount of Fire magic.", ua = "Заряджає вашу зброю невеликою кількістю магії Вогню." },
    { en = "Releases the kidnapped puppies to fight for you for $d.", ua = "Випускає викрадених цуценят, що б'ються за вас протягом $d." },
    { en = "Your healing and damaging spells have a chance to grant $122266s1 mastery for $122266d.", ua = "Ваші зцілювальні та шкідливі заклять мають шанс надати $122266s1 майстерності на $122266d." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $92355s1 mastery for $92355d.   Cannot occur more than once every 30 sec.", ua = "Атаки в ближньому бою, що знижують ваше здоров'я нижче $s1%, надають вам $92355s1 майстерності на $92355d. Може спрацьовувати не частіше, ніж раз на 30 сек." },
    { en = "Your harmful abilitlies have a chance to cause you to summon  lobstrok guardians to fight by your side for $163725d.", ua = "Ваші шкідливі здібності мають шанс прикликати вартових-лобстроків, що б'ються поряд із вами протягом $163725d." },
    { en = "Let loose a dangerous current of lightning, dealing $377465s2 Nature damage to your target and $377465s3 Nature damage to yourself. Self-damage increases with your stacks of Hatred.", ua = "Вивільняє небезпечний потік блискавок, завдаючи $377465s2 шкоди від сил природи вашій цілі та $377465s3 шкоди від сил природи вам самим. Шкода собі зростає з вашими стосами Ненависті." },
    { en = "Your damaging and healing abilities have a chance to activate your Holographic Manipulator, increasing your highest secondary stat by $s2 for 10 sec.", ua = "Ваші шкідливі та зцілювальні здібності мають шанс активувати ваш Голографічний Маніпулятор, підвищуючи вашу найвищу вторинну характеристику на $s2 на 10 сек." },
    { en = "Turns the target into a chicken for $30501d.   Well, that is assuming the transmogrification polarity has not been reversed...", ua = "Перетворює ціль на курку на $30501d. Ну, за умови, що полярність трансмогрифікації не було перевернуто...." },
    { en = "Your melee attacks have a chance to trigger Battering for $177102d.  While Battering is active, you gain $177102s1 Haste every $177102t1 sec, stacking up to $177103u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки ближнього бою мають шанс активувати Молотіння на $177102d. Поки Молотіння активне, ви отримуєте $177102s1 швидкості кожні $177102t1 сек, накопичуючись до $177103u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Creates a new, permanent Carved Ogre Idol item in your inventory while consuming this trinket.", ua = "Створює у вашому інвентарі новий постійний предмет Різьблений Ідол Оґра, споживаючи цей брелок." },
    { en = "Your attacks have a chance to trigger Detonation for $177067d.  While Detonation is active, you gain $177067s1 Critical Strike every $177067t1 sec, stacking up to $177070u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс активувати Детонацію на $177067d. Поки Детонація активна, ви отримуєте $177067s1 критичного удару кожні $177067t1 сек, накопичуючись до $177070u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your healing has a high chance to inflict Cosmic Crescendo on a nearby enemy, dealing $s1 Cosmic damage every $1264948t1 sec until their death, stacking up to $1264948u times.\n\n\n\nHum a cosmic hymn every $t1 sec, consuming a Cosmic Crescendo stack if any ally is below $s3% health to heal them and up to 4 injured allies for ${$s2*$<healingrolemult>} split between them. Healing increased by $1240903s1% per additional ally, up to ${$1240903s1*$1240903s2}%.", ua = "Ваше зцілення має високий шанс накласти Космічне Крещендо на ворога поблизу, завдаючи $s1 космічної шкоди кожні $1264948t1 сек до його смерті, накопичуючись до $1264948u разів.\n\n\n\nНаспівуйте космічний гімн кожні $t1 сек, споживаючи стак Космічного Крещендо, якщо здоров'я будь-якого союзника нижче $s3%, щоб зцілити його та до 4 поранених союзників на ${$s2*$<healingrolemult>}, розподілене між ними. Зцілення збільшується на $1240903s1% за кожного додаткового союзника, до ${$1240903s1*$1240903s2}%." },
    { en = "Establish a link deep within your target's mind, increasing your dodge rating by $s2, and draining ${$s1*($d/$t1)} health over $d.\n\n\n\nIf the link is still intact when this effect ends, their mind shatters, dealing $s3 Shadow damage to enemies within $s4 yds of them and Horrifying them for $368785d.", ua = "Установлює зв'язок глибоко в розумі вашої цілі, підвищуючи ваш рейтинг ухилення на $s2 та висмоктуючи ${$s1*($d/$t1)} здоров'я протягом $d.\n\n\n\nЯкщо зв'язок усе ще цілий, коли цей ефект завершується, її розум розколюється, завдаючи $s3 шкоди Темрявою ворогам у радіусі $s4 м від неї та жахаючи їх на $368785d." },
    { en = "Your melee and ranged attacks have a chance to grant $117646s1 haste for $117646d.", ua = "Ваші атаки ближнього й дального бою мають шанс надати $117646s1 швидкості на $117646d." },
    { en = "Increases your attack power by $s1 and your critical strike by $s2.  Effect lasts for $d.", ua = "Підвищує вашу силу атаки на $s1 та ваш критичний удар на $s2. Ефект триває $d." },
    { en = "Your attacks have a chance to grant $177056s1 Mastery for $177056d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177056s1 майстерності на $177056d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $92179s1 armor for $92179d.   Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $92179s1 броні на $92179d. Не може траплятися частіше ніж раз на 30 сек." },
    { en = "Your melee and ranged attacks have a chance to grant $122316s1 haste for $122316d.", ua = "Ваші атаки ближнього й дального бою мають шанс надати $122316s1 швидкості на $122316d." },
    { en = "Deploy an explosive barrel to bring righteous flame to the enemies of Arathor, dealing ${$<rolemult>*$445516s} Fire damage split between all enemies caught in the blast.", ua = "Розгортає вибухову діжку, щоб обрушити праведне полум'я на ворогів Аратора, завдаючи ${$<rolemult>*$445516s} шкоди Вогнем, розподіленої між усіма ворогами, що потрапили у вибух." },
    { en = "Your damaging spells and abilities have a chance to electrocute your opponent for $285470s1 Nature damage.", ua = "Ваші шкідливі заклинання та здібності мають шанс ударити супротивника струмом, завдаючи $285470s1 шкоди Природою." },
    { en = "Your damaging critical strikes have a chance to apply Volatile Magic. At $215859u stacks Volatile Magic is converted into Withering Consumption, dealing ${$215859s1*5} Arcane damage over $215884d.", ua = "Ваші критичні удари, що завдають шкоди, мають шанс накласти Нестабільну Магію. При $215859u стаках Нестабільна Магія перетворюється на Згубне Поглинання, завдаючи ${$215859s1*5} шкоди Тайнощами протягом $215884d." },
    { en = "Calls forth a Timbermaw Ancestor to fight at your side and heal you.", ua = "Прикликає Предка Дерев'яної Пащі, щоб той бився поруч із вами та зціляв вас." },
    { en = "Roll an Explosive Barrel at the target, dealing $s1 Fire Damage upon impact.", ua = "Котить Вибухову Діжку до цілі, завдаючи $s1 шкоди Вогнем при зіткненні." },
    { en = "Become surrounded by lightning, causing $202891s1 Nature damage to nearby enemies every $t1 sec for $d.", ua = "Оточує вас блискавками, завдаючи $202891s1 шкоди Природою ворогам поблизу кожні $t1 сек протягом $d." },
    { en = "Your attacks have a chance to grant you $126554s1 Agility for $126554d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $126554s1 спритності на $126554d. ($h% шансу, ${$proccooldown} сек перезарядка)" },
    { en = "Captures the target in a net for $13099d.  The net has a lot of hooks however and sometimes gets caught in the user's clothing when fired.", ua = "Захоплює ціль у сітку на $13099d. Однак сітка має багато гачків і часом чіпляється за одяг користувача під час пострілу." },
    { en = "Compel an oathbound Shadowguard squad to annihilate your target and nearby enemies, dealing $1235557s1 Cosmic damage split between them.\n\n\n\n$@spelldesc1240903", ua = "Змусьте загін присяжної Тіньової варти знищити вашу ціль і ворогів поблизу, завдаючи $1235557s1 космічної шкоди, розподіленої між ними.\n\n\n\n$@spelldesc1240903" },
    { en = "Increase the Versatility of all party members within $a1 yards by $s1 for $d.", ua = "Підвищує універсальність усіх членів групи в радіусі $a1 м на $s1 протягом $d." },
    { en = "Your melee attacks have a chance to trigger Forgemaster's Vigor for $177096d.  While Forgemaster's Vigor is active, you gain $177096s1 Mastery every $177096t1 sec, stacking up to $177099u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки ближнього бою мають шанс активувати Снагу Майстра Кузні на $177096d. Поки Снага Майстра Кузні активна, ви отримуєте $177096s1 майстерності кожні $177096t1 сек, накопичуючись до $177099u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increases your critical strike and spell critical strike by $s1.  Lasts $d.", ua = "Підвищує ваш критичний удар та критичний удар заклять на $s1. Триває $d." },
    { en = "Your damaging abilities have a high chance to deal $344153s1 Physical damage, healing you for ${$s2*100}% of the damage dealt. If this effect overheals, deal ${$s1*5*(1+$@versadmg)} Physical damage split between nearby enemies over $344154d, but suppress the lifesteal effect.\n\n\n\nDamage increased per enemy struck, up to $s3 enemies.", ua = "Ваші шкідливі здібності мають високий шанс завдати $344153s1 фізичної шкоди, зціляючи вас на ${$s2*100}% завданої шкоди. Якщо цей ефект перевищує зцілення, він завдає ${$s1*5*(1+$@versadmg)} фізичної шкоди, розподіленої між ворогами поблизу протягом $344154d, але придушує ефект викрадення життя.\n\n\n\nШкода збільшується за кожного враженого ворога, до $s3 ворогів." },
    { en = "Increases spell power of the next 5 spells by $s2 for $d.", ua = "Підвищує силу заклять наступних 5 заклять на $s2 протягом $d." },
    { en = "Complete the ritual, unleashing a horrific blast that deals ${$<rolemult>*$s1} Shadow damage to your target per magic stored up to ${$<rolemult>*($s1*$455464u)} .", ua = "Завершує ритуал, вивільняючи жахливий вибух, що завдає ${$<rolemult>*$s1} шкоди Темрявою вашій цілі за кожну накопичену магію, до ${$<rolemult>*($s1*$455464u)}." },
    { en = "When you heal you have a chance to gain $109804s1 haste for $109804d.", ua = "Коли ви зціляєте, ви маєте шанс отримати $109804s1 швидкості на $109804d." },
    { en = "Deal $o1 Shadow damage over $d. When this effect ends or the target dies, you gain $243942s1 Critical Strike for $243942d plus any time remaining on the effect.", ua = "Завдає $o1 шкоди Темрявою протягом $d. Коли цей ефект завершується або ціль гине, ви отримуєте $243942s1 критичного удару на $243942d плюс будь-який залишковий час ефекту." },
    { en = "Increase Armor by $191624s1-$191631s1. The amount of Armor depends on the topmost card in the deck.", ua = "Підвищує броню на $191624s1-$191631s1. Величина броні залежить від верхньої карти в колоді." },
    { en = "Channel to unravel your target's essence, dealing $422953s1 Nature damage over $s2 sec and granting you up to $422953s2 Mastery for $427072d. \n\n\n\nDamage increased by $422953s3% against immobilized targets.", ua = "Каналізуйте, щоб розплести сутність вашої цілі, завдаючи $422953s1 шкоди Природою протягом $s2 сек та надаючи вам до $422953s2 майстерності на $427072d.\n\n\n\nШкода збільшується на $422953s3% проти знерухомлених цілей." },
    { en = "Whenever a nearby Automa dies, your cooldowns recover $s2% more quickly for $368937d.", ua = "Щоразу, коли Автома поблизу гине, ваші перезарядки відновлюються на $s2% швидше протягом $368937d." },
    { en = "Conjure a Spectral Scythe, dealing $345877s1 Shadow damage to your target and $345877s2 Shadow damage in a $345963A1 yd cone to enemies behind your target.", ua = "Прикликає Примарну Косу, що завдає $345877s1 шкоди Темрявою вашій цілі та $345877s2 шкоди Темрявою в конусі $345963A1 м ворогам позаду вашої цілі." },
    { en = "Grants $97142s1 critical strike for $97142d each time you deal a melee critical strike, stacking up to $97142u times.", ua = "Надає $97142s1 критичного удару на $97142d щоразу, коли ви завдаєте критичного удару в ближньому бою, накопичуючись до $97142u разів." },
    { en = "Increases your spell critical strike by $s1 for $d.", ua = "Підвищує ваш критичний удар заклять на $s1 протягом $d." },
    { en = "You have a chance to foresee damage taken by your allies, healing them instantly for $s1 when they are injured.", ua = "Ви маєте шанс передбачити шкоду, яку зазнають ваші союзники, миттєво зціляючи їх на $s1, коли вони поранені." },
    { en = "Your abilities have a low chance to summon a gnoll ally to assist you during combat. They may deal $s2 Physical damage to your target and $?134735a[snare][stun] it for $386168d, poison your target for ${$s3*($384290d/($384290t1))} Nature over $384290d, or increase your highest secondary stat by $s1 for $384294d.", ua = "Ваші здібності мають низький шанс прикликати союзника-гнола, щоб той допомагав вам у бою. Він може завдати $s2 фізичної шкоди вашій цілі та $?134735a[сповільнити][приголомшити] її на $386168d, отруїти вашу ціль на ${$s3*($384290d/($384290t1))} Природи протягом $384290d або підвищити вашу найвищу вторинну характеристику на $s1 на $384294d." },
    { en = "When a nearby ally's health drops below $s1%, sacrifice $s2 of your health to heal them for the same amount. May only occur every 1 min.", ua = "Коли здоров'я союзника поблизу падає нижче $s1%, ви жертвуєте $s2 свого здоров'я, щоб зцілити його на ту саму величину. Може траплятися лише раз на 1 хв." },
    { en = "Your attacks have a chance to grant $177046s1 Critical Strike for $177046d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177046s1 критичного удару на $177046d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Engrave a ritual seal into your skin binding you to the shadows, granting yourself $s1 $pri.\n\n\n\nYour spells and abilities have a low chance to reduce one of your secondary stats by $s2 for $440389d during combat.", ua = "Викарбуйте на своїй шкірі ритуальну печатку, що прив'язує вас до тіней, надаючи собі $s1 $pri.\n\n\n\nВаші закляття та вміння мають низький шанс знизити одну з ваших вторинних характеристик на $s2 на $440389d під час бою." },
    { en = "Equip: Periodically shuffle the deck while in combat.", ua = "Спорядження: Періодично тасує колоду під час бою." },
    { en = "Your attacks have a chance to fill you with energy. After $224154d the Nether Energy explodes, dealing $224155s1 Arcane damage to nearby enemies.", ua = "Ваші атаки мають шанс наповнити вас енергією. Через $224154d Енергія Нижнього Світу вибухає, завдаючи $224155s1 шкоди від чарів навколишнім ворогам." },
    { en = "Say a prayer to the Light.  Not usable while in combat.", ua = "Промовте молитву до Світла. Не можна використати в бою." },
    { en = "Call your Ruby Whelpling to inspect your target's situation, teaching them how to be helpful.", ua = "Кличе вашого Рубінового Дракончика оглянути становище вашої цілі, навчаючи його бути корисним." },
    { en = "Briefly open a pair of gates to the Void to redirect the orbit of An'shuul, the Cosmic Wanderer through your target, dealing $402574s1 Cosmic damage split between all nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to 5 enemies.", ua = "Ненадовго відкриває пару брам у Порожнечу, щоб спрямувати орбіту Ан'шуула, Космічного Мандрівника крізь вашу ціль, завдаючи $402574s1 космічної шкоди, розподіленої між усіма навколишніми ворогами.\n\n\n\nШкода зростає за кожного враженого ворога, до 5 ворогів." },
    { en = "Your attacks have a chance to rouse the fiber, increasing your Critical Strike by $1276677s1 for $1276677d.", ua = "Ваші атаки мають шанс пробудити волокно, підвищуючи вашу швидкість критичного удару на $1276677s1 на $1276677d." },
    { en = "Your ranged attacks and spells have a chance to release a ball of Volatile Energy that travels towards your target, dealing $s1 damage to enemies it passes through.", ua = "Ваші дальні атаки та закляття мають шанс випустити кулю Нестійкої Енергії, що летить до вашої цілі, завдаючи $s1 шкоди ворогам, крізь яких вона проходить." },
    { en = "Increases haste by $s1 for $d1.", ua = "Підвищує швидкість на $s1 на $d1." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $45058s1 dodge for $45058d.  Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, які знижують ваше здоров'я нижче $s1%, надають вам $45058s1 ухилення на $45058d. Не може спрацьовувати частіше, ніж раз на 30 сек." },
    { en = "Your damaging abilities against enemies above $M3% health have a very high chance to apply Conductive Ink. When an enemy falls below $M3% health, Conductive Ink inflicts ${$s1*(1+$@versadmg)} Nature damage per stack.", ua = "Ваші здібності, що завдають шкоди ворогам зі здоров'ям понад $M3%, мають дуже високий шанс накласти Провідне Чорнило. Коли здоров'я ворога падає нижче $M3%, Провідне Чорнило завдає ${$s1*(1+$@versadmg)} шкоди від природи за кожен заряд." },
    { en = "Chance on melee hit to gain 1 extra attack.", ua = "Шанс при влучанні в ближньому бою отримати 1 додаткову атаку." },
    { en = "Grants a chance for enemies that attack you to have their souls Darkened, reducing the damage they deal to you by ${-$222209s1}.2% for $222209d. Additional applications increase the effectiveness of Darkening Soul but do not refresh its duration.", ua = "Надає шанс, що душі ворогів, які вас атакують, будуть Затьмарені, знижуючи шкоду, яку вони вам завдають, на ${-$222209s1}.2% на $222209d. Додаткові накладання підвищують дієвість Затьмарення Душі, але не оновлюють його тривалість." },
    { en = "Seize the eye's draconic power, granting you $1259293s1 Mastery diminishing over $d and allowing you to see hidden enemies.", ua = "Захоплює драконячу силу ока, надаючи вам $1259293s1 майстерності, що зменшується протягом $d, і дозволяючи бачити прихованих ворогів." },
    { en = "Your attacks have a chance to inflict your target with mantid poison, dealing $128386s1 damage every $128386t sec for $128386d.", ua = "Ваші атаки мають шанс уразити ціль отрутою мантидів, завдаючи $128386s1 шкоди кожні $128386t сек. протягом $128386d." },
    { en = "Your healing and damaging spells have a chance to grant $118611s1 haste for $118611d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати $118611s1 швидкості на $118611d." },
    { en = "When you deal damage you have a chance to gain $109709s1 haste for $109709d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109709s1 швидкості на $109709d." },
    { en = "$@class be nimble, $@class be quick. $@class invoke the power of the candlestick to increase movement speed by $s1% and Haste by $s2 for $d.", ua = "$@class, будь спритним, $@class, будь швидким. $@class закликає силу свічника, щоб підвищити швидкість пересування на $s1% та шпаркість на $s2 протягом $d." },
    { en = "Your attacks and abilities have a low chance to beckon a random Loa spirit to your side, increasing your combat capabilities for $1266182d.", ua = "Ваші атаки та здібності мають низький шанс прикликати випадковий дух Лоа до вашого боку, підвищуючи ваші бойові можливості на $1266182d." },
    { en = "Impale yourself with the splinter, immediately suffering $s1 Nature damage but letting its slime loose over your body. The slime absorbs $s3% of damage taken, up to $s2 total damage, for $d.", ua = "Проштрикує вас скалкою, негайно завдаючи $s1 шкоди від природи, але вивільняючи її слиз по вашому тілу. Слиз поглинає $s3% отриманої шкоди, до $s2 загальної шкоди, протягом $d." },
    { en = "When you deal damage you have a chance to gain $182059s1 Agility for $182059d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $182059s1 спритності на $182059d." },
    { en = "Launch void energy at your target, dealing ${$305251s1*(1+$@versadmg)} Shadow damage every $305250t1 sec for $305250d. Each time Maledict deals damage, absorb the next ${$305251s2*(1+$@versadmg)} healing received by your target. Lasts $305249d.", ua = "Запускає у вашу ціль енергію Порожнечі, завдаючи ${$305251s1*(1+$@versadmg)} тіньової шкоди кожні $305250t1 сек. протягом $305250d. Щоразу, коли Прокляття завдає шкоди, воно поглинає наступні ${$305251s2*(1+$@versadmg)} зцілення, отриманого вашою ціллю. Триває $305249d." },
    { en = "Lead the charge to gain $1251817s1 Haste for $d. All Vanguard of the Light volunteers within 40 yards also gain $1251817s2 Speed for $1262496d.", ua = "Очолює атаку, надаючи $1251817s1 швидкості на $d. Усі добровольці Авангарду Світла в межах 40 ярдів також отримують $1251817s2 прудкості на $1262496d." },
    { en = "When you dodge, you have a $h% chance to gain $138864s1 mastery for $138864d.  This effect can stack up to $138864u times.", ua = "Коли ви ухиляєтесь, ви маєте $h% шанс отримати $138864s1 майстерності на $138864d. Цей ефект накладається до $138864u разів." },
    { en = "When you deal damage you have a chance to gain Paragon, increasing your Strength or Agility by $67772s1 for $67772d.  Your highest stat is always chosen.", ua = "Коли ви завдаєте шкоди, ви маєте шанс стати Взірцем, підвищуючи вашу силу або спритність на $67772s1 на $67772d. Завжди обирається ваша найвища характеристика." },
    { en = "Each time you cast a damaging or healing spell, there is a chance you will gain up to $60520s1 Versatility for $60520d.", ua = "Щоразу, коли ви читаєте шкідливе або зцілювальне закляття, є шанс отримати до $60520s1 універсальності на $60520d." },
    { en = "Everyone sees just how awesome you are.", ua = "Усі бачать, наскільки ви чудові." },
    { en = "Taking damage has a high chance to fill the chalice with Despair, drop by drop, up to $1265323u times. Once full, the chalice spills, blanketing the ground beneath you in a dark mire dealing $s2 Void damage each second split between enemies inside for $1265325d while granting you $s1 versatility.", ua = "Отримання шкоди має високий шанс наповнити чашу Відчаєм, крапля за краплею, до $1265323u разів. Щойно чаша наповниться, вона переливається, вкриваючи землю під вами темною твань, що завдає $s2 шкоди від Порожнечі щосекунди, розподіленої між ворогами всередині, протягом $1265325d, а також надаючи вам $s1 універсальності." },
    { en = "Heals $o1 damage over $d.", ua = "Зцілює $o1 шкоди протягом $d." },
    { en = "Your harmful attacks and abilities have a high chance to build momentum, granting $459224s1% bonus movement speed per stack.\n\n\n\nAt 5 stacks you reach full momentum increasing your movement speed bonus to $459228s1% for $459228d. While at full momentum, your attacks hit the target at high velocity dealing an additional ${$<rolemult>*$s1} Nature damage scaling up with your current movement speed.", ua = "Ваші шкідливі атаки та здібності мають високий шанс накопичити інерцію, надаючи $459224s1% додаткової швидкості пересування за кожен заряд.\n\n\n\nЗа 5 зарядів ви досягаєте повної інерції, підвищуючи ваш бонус до швидкості пересування до $459228s1% на $459228d. Перебуваючи в повній інерції, ваші атаки влучають у ціль на високій швидкості, завдаючи додатково ${$<rolemult>*$s1} шкоди від природи, що зростає разом із вашою поточною швидкістю пересування." },
    { en = "Cause the target to explode with energy, dealing $s1 Shadow damage split evenly to all enemies within 10 yards. Enemies hit are ${$311464S1*0.01}% to ${$311471S1*0.01}% more likely to be critically hit by you. The critical strike chance amount depends on the topmost card of the deck. Lasts $d.", ua = "Змушує ціль вибухнути енергією, завдаючи $s1 одиниць Тіньової шкоди, що порівну ділиться між усіма ворогами в межах 10 метрів. Уражені вороги стають на ${$311464S1*0.01}% – ${$311471S1*0.01}% уразливішими до ваших критичних ударів. Величина шансу критичного удару залежить від верхньої карти колоди. Триває $d." },
    { en = "Instantly heal your current friendly target for $s1.", ua = "Миттєво зцілює вашу поточну дружню ціль на $s1." },
    { en = "Your attacks have a chance to grant $165822s1 Haste for $165822d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $165822s1 швидкості на $165822d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your Nature spells have a chance to restore $37243s1 mana.", ua = "Ваші закляття Природи мають шанс відновити $37243s1 мани." },
    { en = "Fashion nearby garbage into a sphere and launch it into the sky. After $1219296s2 sec of gathering momentum the sphere crashes into the targeted location dealing $1219296s1 Physical damage split between all enemies in the area.", ua = "Формує з навколишнього сміття сферу та запускає її в небо. Після $1219296s2 сек. набирання швидкості сфера врізається в обрану ділянку, завдаючи $1219296s1 фізичної шкоди, розподіленої між усіма ворогами в зоні." },
    { en = "Freeze the Shiver Venom on your target, consuming it to deal ${$301576s1*(1+$@versadmg)} Frost damage per stack to all nearby enemies.", ua = "Заморожує Тремтливу Отруту на вашій цілі, поглинаючи її, щоб завдати ${$301576s1*(1+$@versadmg)} шкоди від льоду за кожен заряд усім навколишнім ворогам." },
    { en = "Grants you $s1 Mastery for $d.", ua = "Надає вам $s1 майстерності на $d." },
    { en = "Gaze into the orb, suffering ${$s1*4} Shadow damage over $d to increase your Mastery by $356334s1 for up to ${$356326d*4} sec. The longer you gaze, the more tormented and insightful you become.", ua = "Вдивляється у сферу, завдаючи ${$s1*4} тіньової шкоди протягом $d, щоб підвищити вашу майстерність на $356334s1 на час до ${$356326d*4} сек. Чим довше ви вдивляєтесь, тим більш стражденними та прозірливими ви стаєте." },
    { en = "Expend your Cunning to reduce the cooldown of $?a137008[Icebound Fortitude]?a212613[Metamorphosis]?a137010[Survival Instincts]?a137023[Fortifying Brew]?a137028[Guardian of Ancient Kings]?a137048[Shield Wall][a strong defensive ability] by $<cooldown> sec per stack. If $?a137008[Icebound Fortitude]?a212613[Metamorphosis]?a137010[Survival Instincts]?a137023[Fortifying Brew]?a137028[Guardian of Ancient Kings]?a137048[Shield Wall][a strong defensive ability] is currently active, this instead extends its duration by $<extension> sec per stack.|CFF808080$?!(a137008|a212613|a137010|a137023|a137028|a137048)[\n\n\n\nValid for tank specializations.][]|R", ua = "Витрачає вашу Хитрість, щоб зменшити час відновлення $?a137008[Крижаної стійкості]?a212613[Метаморфози]?a137010[Інстинктів виживання]?a137023[Зміцнювального відвару]?a137028[Вартового стародавніх королів]?a137048[Захисної стіни][потужної захисної здібності] на $<cooldown> сек за заряд. Якщо $?a137008[Крижана стійкість]?a212613[Метаморфоза]?a137010[Інстинкти виживання]?a137023[Зміцнювальний відвар]?a137028[Вартовий стародавніх королів]?a137048[Захисна стіна][потужна захисна здібність] зараз активна, замість цього подовжує її тривалість на $<extension> сек за заряд.|CFF808080$?!(a137008|a212613|a137010|a137023|a137028|a137048)[\n\n\n\nДіє для спеціалізацій танка.][]|R" },
    { en = "Your healing spells have a chance to launch a Pulse at your target, healing them for $215263s1 and bouncing to up to ${$215263x1-1} additional targets.", ua = "Ваші зцілювальні закляття мають шанс запустити Імпульс у ціль, зцілюючи її на $215263s1 та перестрибуючи ще до ${$215263x1-1} додаткових цілей." },
    { en = "Your spells and abilities have a chance to grant $345230s1 primary stat for $345230d.", ua = "Ваші закляття та здібності мають шанс надати $345230s1 основної характеристики на $345230d." },
    { en = "Your melee attacks have a chance to trigger a whirlwind attack dealing $109754s1 physical damage to all targets within $109754A1 yards.", ua = "Ваші ближні атаки мають шанс викликати вихровий удар, що завдає $109754s1 фізичної шкоди всім цілям у радіусі $109754A1 м." },
    { en = "Your melee and ranged attacks have a chance to grant $120175s1 mastery for $120175d.", ua = "Ваші ближні та дальні атаки мають шанс надати $120175s1 майстерності на $120175d." },
    { en = "Your attacks slowly build Concussive Force, granting $s1 attack power per stack. \n\n\n\nAt $382094u stacks, your next $s3 melee abilities emit a shockwave in front of you, dealing $s2 bonus Nature damage to all enemies in a line. Shockwaves deal more damage to enemies at high health.", ua = "Ваші атаки повільно нарощують Струсну Силу, надаючи $s1 сили атаки за кожен заряд. \n\n\n\nПри $382094u зарядах ваші наступні $s3 ближні здібності випускають ударну хвилю перед вами, завдаючи $s2 додаткової шкоди від Природи всім ворогам на лінії. Ударні хвилі завдають більше шкоди ворогам з високим рівнем здоров'я." },
    { en = "You are one of the devout. Your spells and abilities have a chance of burning a nearby enemy for $s1 Radiant damage and healing another devout ally for that amount.", ua = "Ви — один із відданих. Ваші закляття та здібності мають шанс спопелити ворога поблизу на $s1 Сяйливої шкоди та зцілити іншого відданого союзника на цю саму величину." },
    { en = "Your damaging attacks and abilities have a chance for Ohn'ahra to bless you with her winds, increasing your Haste by $381998s1.", ua = "Ваші атаки та здібності, що завдають шкоди, мають шанс на те, що Он'агра благословить вас своїми вітрами, підвищуючи вашу швидкість на $381998s1." },
    { en = "Give in to the Rageheart, absorbing $422652s3 damage for $425571d. Suffer $422652s2 Shadowflame damage and lash out at a nearby enemy every $t1 sec for $d to deal $422652s4 Shadowflame damage split between nearby enemies. \n\n\n\nDamage increased per enemy struck, up to 5.", ua = "Піддайтеся Серцю Люті, поглинаючи $422652s3 шкоди протягом $425571d. Зазнавайте $422652s2 шкоди від Тіньового Полум'я та накидайтеся на ворога поблизу кожні $t1 с протягом $d, завдаючи $422652s4 шкоди від Тіньового Полум'я, розподіленої між ворогами поблизу. \n\n\n\nШкода зростає за кожного враженого ворога, аж до 5." },
    { en = "Your melee attacks have a chance to grant $118874s1 mastery for $118874d.", ua = "Ваші ближні атаки мають шанс надати $118874s1 майстерності на $118874d." },
    { en = "Reduces the cost of your next spell cast within $d by up to $s1 mana.", ua = "Зменшує вартість вашого наступного закляття, застосованого протягом $d, до $s1 мани." },
    { en = "Your damaging abilities have a chance to echo with Xathuux's furious roar, increasing Critical Strike by $s1 for $1254180d.\n\n\n\nDuring this time, each of your attacks increases your Critical Strike by an additional $s2, $@spelldesc1254331", ua = "Ваші здібності, що завдають шкоди, мають шанс відлунити лютим ревом Затуукса, підвищуючи критичний удар на $s1 на $1254180d.\n\n\n\nУ цей час кожна ваша атака додатково підвищує ваш критичний удар на $s2, $@spelldesc1254331" },
    { en = "Your healing abilities have a chance to inject your target with slime, healing them for $o1 over $d.", ua = "Ваші зцілювальні здібності мають шанс упорснути цілі слиз, зцілюючи її на $o1 протягом $d." },
    { en = "Increases your Armor by $s1 for $d.", ua = "Підвищує вашу броню на $s1 на $d." },
    { en = "Desperately unravel yourself over $d to unleash a barrage of ${$d/$t1} cosmic missiles at your target, increased by your haste. Each deals ${$1259103s1*$<rolemult>} Cosmic damage split between nearby enemies. $@spelldesc1240903\n\n\n\nAllied deaths induce further madness, reducing the cooldown by $1259103s3 sec.", ua = "Розпачливо розпускайте себе протягом $d, щоб випустити шквал із ${$d/$t1} космічних снарядів по вашій цілі, посилений вашою скорострільністю. Кожен завдає ${$1259103s1*$<rolemult>} космічної шкоди, розподіленої між ворогами поблизу. $@spelldesc1240903\n\n\n\nСмерті союзників розпалюють подальше божевілля, скорочуючи час відновлення на $1259103s3 сек." },
    { en = "Restores $33758s1 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $33758s1 здоров'я, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект може спрацьовувати не частіше ніж раз на 10 секунд." },
    { en = "Unleash a solar maelstrom, slowing yourself and nearby enemies before erupting in flames after 2 sec to deal $422141s1 Fire damage split between all enemies and $422141s2 Fire damage to you over $425417d.\n\n\n\nCastable while moving. Damage increased per enemy struck, up to 5.", ua = "Вивільняє сонячний вир, сповільнюючи вас та ворогів поблизу, перш ніж за 2 с спалахнути полум'ям, завдаючи $422141s1 шкоди від Вогню, розподіленої між усіма ворогами, та $422141s2 шкоди від Вогню вам протягом $425417d.\n\n\n\nЗастосовується в русі. Шкода зростає за кожного враженого ворога, аж до 5." },
    { en = "Your melee attacks have a chance to grant $122312s1 parry for $122312d.", ua = "Ваші ближні атаки мають шанс надати $122312s1 парирування на $122312d." },
    { en = "Your attacks and beneficial spells have a chance to grant $176978s1 Critical Strike for $176978d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки та сприятливі закляття мають шанс надати $176978s1 критичного удару на $176978d.  (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Tap into the power of the skull, increasing haste by $s1 for $d1.", ua = "Черпає силу черепа, підвищуючи швидкість на $s1 протягом $d1." },
    { en = "When your attacks hit you have a chance to gain $173834s1 critical strike for $173834d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $173834s1 критичного удару на $173834d.  ($h% шансу, ${$proccooldown} с перезарядки)" },
    { en = "Your spells and abilities have a chance to secrete $?pc129946[][$<effectCount> ]different pheromones around you. Touching these pheromones will increase your primary stat by $s1 for $441428d.$?pc129945[][\n\n\n\nReach Accomplice reputation with each of the Severed Threads' pacts to secrete more pheromones.]", ua = "Ваші чари та здібності мають шанс виділити навколо вас $?pc129946[][$<effectCount> ]різних феромонів. Дотик до цих феромонів підвищить вашу основну характеристику на $s1 протягом $441428d.$?pc129945[][\n\n\n\nДосягніть репутації «Спільник» з кожним із пактів Розітнутих Ниток, щоб виділяти більше феромонів.]" },
    { en = "Your spells and abilities have a chance to grant you $256818s1 Speed, Avoidance, and Leech for $256818d.\n\n\n\n|cFFFFFFFFAman'Thul's Grandeur|r\n\nWhen empowered by the Pantheon, your $?(a137005|a137047|a137028|a137027)[Strength]?(a212611|a137011|a137010|a137014|a137023|a137025|a137034|a137041)[Agility][Intellect] is increased by $256832s1 for $256832d.", ua = "Ваші чари та здібності мають шанс надати вам $256818s1 швидкості, ухилення та висмоктування протягом $256818d.\n\n\n\n|cFFFFFFFFВелич Аман'Тула|r\n\nКоли Пантеон наділяє вас могутністю, ваша $?(a137005|a137047|a137028|a137027)[сила]?(a212611|a137011|a137010|a137014|a137023|a137025|a137034|a137041)[спритність][інтелект] підвищується на $256832s1 протягом $256832d." },
    { en = "Your spells and abilities have a chance to grant $s1 secondary stats the way $?|CFFFFFFFFyou|R like them!", ua = "Ваші чари та здібності мають шанс надати $s1 вторинних характеристик так, як $?|CFFFFFFFFви|R любите!" },
    { en = "Your attacks and beneficial spells have a chance to grant $177063s1 Critical Strike for $177063d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки та сприятливі закляття мають шанс надати $177063s1 критичного удару на $177063d.  (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Increases critical strike  by $s1 for $d.", ua = "Підвищує критичний удар на $s1 на $d." },
    { en = "Your harmful spells grant $109793s1 Intellect for the next $109793d, stacking up to $109793u times.", ua = "Ваші шкідливі закляття надають $109793s1 інтелекту на наступні $109793d, накопичуючись до $109793u разів." },
    { en = "Fire a resonant bolt at your target which causes a Disintegration Halo from its location, dealing $s1 damage every $368231t1 sec for $368231d. Crescendos $s2 times before taking it again from the top.", ua = "Випускає в ціль резонансну стрілу, що створює Ореол Розпаду в її місці, завдаючи $s1 шкоди кожні $368231t1 с протягом $368231d. Наростає $s2 разів, перш ніж початися знову спочатку." },
    { en = "Call a Nerubian to ambush an enemy, impaling them for $355301s2 Physical damage. Enemies in the Nerubian's path who are affected by your Frozen Heart suffer $355301s3 Frost damage.", ua = "Прикликає Нерубіанця, щоб той із засідки атакував ворога, проштрикуючи його на $355301s2 фізичної шкоди. Вороги на шляху Нерубіанця, уражені вашим Замерзлим Серцем, зазнають $355301s3 шкоди від Морозу." },
    { en = "You have proven your worth to Nalorakk. Your abilities have a chance to echo with the war god's furious roar, granting you $s1 Strength for $1258223d.\n\n\n\nNearby allies with Nalorakk's favor are rallied, gaining $1258222s1% movement speed for $1258222d.", ua = "Ви довели свою гідність Налораку. Ваші здібності мають шанс відлунити лютим ревом бога війни, надаючи вам $s1 сили на $1258223d.\n\n\n\nСоюзники поблизу, що мають прихильність Налорака, надихаються, отримуючи $1258222s1% швидкості пересування на $1258222d." },
    { en = "$@spelldesc1277482\n\n\n\n$?pc149756[Protocol of Violence: The Voidlust consumes you more often.][Engage the Protocol of Violence to increase the frequency of Voidlust episodes.]\n\n\n\n$?pc149755[Protocol of Sustenance: Voidlust episodes last longer.][Engage the Protocol of Sustenance to increase the duration of Voidlust episodes.]\n\n\n\n$?pc149754[Protocol of Predation: Voidlust episodes are more intense.][Engage the Protocol of Predation to increase the intensity of Voidlust episodes.]", ua = "$@spelldesc1277482\n\n\n\n$?pc149756[Протокол Насильства: Жага Порожнечі охоплює вас частіше.][Активуйте Протокол Насильства, щоб підвищити частоту проявів Жаги Порожнечі.]\n\n\n\n$?pc149755[Протокол Підживлення: прояви Жаги Порожнечі тривають довше.][Активуйте Протокол Підживлення, щоб збільшити тривалість проявів Жаги Порожнечі.]\n\n\n\n$?pc149754[Протокол Хижацтва: прояви Жаги Порожнечі інтенсивніші.][Активуйте Протокол Хижацтва, щоб підвищити інтенсивність проявів Жаги Порожнечі.]" },
    { en = "Your healing spells grant Inner Eye, increasing Versatility by $91320s1 for $91320d and stacking up to $91320u times.", ua = "Ваші зцілювальні закляття надають Внутрішнє Око, підвищуючи універсальність на $91320s1 на $91320d та накопичуючись до $91320u разів." },
    { en = "Calls forth a Netherwing Ally to fight at your side in Shadowmoon Valley.", ua = "Прикликає Союзника Нетерокрилих, щоб той бився поруч із вами в Долині Тіньового Місяця." },
    { en = "Call in a ravenous ally and ride off into the sunset (or $443387rad1 yds, whichever is closest), inflicting ${$<rolemult>*$448909s1} Fire damage split between all enemies you ride through.", ua = "Прикличте ненажерливого союзника й помчіть назустріч заходу сонця (або на $443387rad1 ярдів, залежно від того, що ближче), завдаючи ${$<rolemult>*$448909s1} шкоди вогнем, розподіленої між усіма ворогами, крізь яких ви проїдете." },
    { en = "Sacrifice $345551s2 health to charge the phylactery.\n\n\n\nHealing a target below $s3% health expends the phylactery's charge to amplify your spell, restoring $345551s1 additional health to the target.", ua = "Пожертвуйте $345551s2 здоров'я, щоб зарядити філактерій.\n\n\n\nЗцілення цілі, що має менше за $s3% здоров'я, витрачає заряд філактерія, підсилюючи ваше закляття та відновлюючи цілі додатково $345551s1 здоров'я." },
    { en = "The noise made from melee combat sometimes causes Sonic Awareness, increasing your attack power by $55018s1 for $55018d.  This effect can only occur once every minute.", ua = "Шум ближнього бою інколи викликає Звукову Чутливість, підвищуючи вашу силу атаки на $55018s1 на $55018d.  Цей ефект може спрацьовувати лише раз на хвилину." },
    { en = "Hurl the grapnel up to $r yds to impale your target, dealing $400955s1 Physical damage and heaving you towards them with tremendous force. On impact, deal $400955s2 Volcanic damage split between all nearby enemies. \n\n\n\nImpact damage is increased per enemy struck, up to 5 enemies.", ua = "Метає гарпун на відстань до $r м, щоб проштрикнути ціль, завдаючи $400955s1 фізичної шкоди та з величезною силою притягуючи вас до неї. При зіткненні завдає $400955s2 Вулканічної шкоди, розподіленої між усіма ворогами поблизу. \n\n\n\nШкода від зіткнення зростає за кожного враженого ворога, аж до 5 ворогів." },
    { en = "Your melee and ranged attacks grant $92104s1 Agility.  Lasts $92104d, stacking up to $92104u times.", ua = "Ваші ближні та дальні атаки надають $92104s1 спритності.  Триває $92104d, накопичуючись до $92104u разів." },
    { en = "Your melee attacks have a chance to grant $91821s1 haste for $91821d.", ua = "Ваші ближні атаки мають шанс надати $91821s1 швидкості на $91821d." },
    { en = "$?s137048[Shield Block now also reduces magic damage taken by $s1%. Ignore Pain now also increases your Armor by $s2%.][]$?s137048&s152276[ Shield Charge now increases Shield Slam, Revenge, and Heroic Strike damage by an additional $s3%.][]", ua = "$?s137048[Блокування Щитом тепер також зменшує отриману магічну шкоду на $s1%. Зневага до Болю тепер також підвищує вашу броню на $s2%.][]$?s137048&s152276[ Натиск Щитом тепер підвищує шкоду від Удару Щитом, Помсти та Героїчного Удару додатково на $s3%.][]" },
    { en = "Each time you cast a helpful spell, you have a chance to gain $67666s1 mana.", ua = "Щоразу, коли ви застосовуєте сприятливе закляття, ви маєте шанс отримати $67666s1 мани." },
    { en = "When you deal damage you have a chance to gain $75456s1 attack power for $75456d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $75456s1 сили атаки на $75456d." },
    { en = "Create a patch of light at the target location for $d. Allies within the light split ${$342433s1*(1+$@versadmg)} absorption every $s1 sec while it persists. \n\n\n\nAbsorption is increased for each ally within the patch of light, up to $s3.", ua = "Створює пляму світла в цільовому місці на $d. Союзники в межах світла розподіляють між собою ${$342433s1*(1+$@versadmg)} поглинання кожні $s1 с, доки воно зберігається. \n\n\n\nПоглинання зростає за кожного союзника в межах плями світла, аж до $s3." },
    { en = "Chance on melee or ranged attack to grant Cleansing Flame, dealing $201408s1 damage instantly and increasing your damage against Demons by $201408s2% for $201408d.", ua = "Шанс при ближній або дальній атаці надати Очисне Полум'я, що миттєво завдає $201408s1 шкоди та підвищує вашу шкоду проти Демонів на $201408s2% на $201408d." },
    { en = "Restore $s1 health to the target, but inflict a curse on yourself that absorbs the next $291170s1 healing you receive.", ua = "Відновлює $s1 здоров'я цілі, але накладає на вас прокляття, що поглинає наступні $291170s1 зцілення, яке ви отримуєте." },
    { en = "Your spell critical strikes have a chance to increase your spell power by $38348s1 for $38348d.", ua = "Ваші критичні удари заклять мають шанс підвищити силу заклять на $38348s1 на $38348d." },
    { en = "Your attacks and spells have a chance to summon a Released Crawg to your side for $274791d.", ua = "Ваші атаки й закляття мають шанс прикликати поряд із вами Звільненого Крога на $274791d." },
    { en = "Energizes a Paladin with light, increasing melee haste by $s2 and spell haste by $s1 for $d.", ua = "Наповнює паладина світлом, підвищуючи швидкість ближнього бою на $s2 та швидкість заклять на $s1 на $d." },
    { en = "Lob a barrel of poison at the target, dealing $s1 Nature Damage upon impact.", ua = "Жбурляє в ціль бочку з отрутою, завдаючи $s1 шкоди Природою під час влучання." },
    { en = "Removes all movement impairing effects and all effects which cause loss of control of your character. Only usable in Pandaria.", ua = "Знімає всі ефекти, що обмежують пересування, та всі ефекти, що спричиняють втрату контролю над персонажем. Використовується лише в Пандарії." },
    { en = "Your melee and ranged attacks have a chance to grant $92043s1 haste for $92043d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $92043s1 швидкості на $92043d." },
    { en = "Your melee attacks have a chance to grant you Congealing Goo, stacking up to $215126u times.", ua = "Ваші атаки ближнього бою мають шанс надати вам Згусток Слизу, що накопичується до $215126u разів." },
    { en = "Your spells that damage a target below $s1% health grant $90996s1 spell power for $90996d.  Cannot activate again for $90996d after bonus expires.", ua = "Ваші закляття, що завдають шкоди цілі зі здоров'ям нижче $s1%, надають $90996s1 сили заклять на $90996d. Не може активуватися знову протягом $90996d після завершення бонусу." },
    { en = "Your spells and abilities have a chance to increase your Versatility by $s1 for $d.", ua = "Ваші закляття та здібності можуть збільшити вашу Універсальність на $s1 протягом $d." },
    { en = "Your damage dealing spells have a chance to trigger a Shadowbolt Volley, dealing $109800s1 damage to all enemies within $109800A1 yards of your current target.", ua = "Ваші закляття, що завдають шкоди, мають шанс викликати Залп Тіньових Стріл, завдаючи $109800s1 шкоди всім ворогам у межах $109800A1 ярдів від вашої поточної цілі." },
    { en = "When you deal damage you have a chance to gain $105135s1 Agility for $105135d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $105135s1 спритності на $105135d." },
    { en = "Your healing spells have a chance to grant $91192s1 Intellect for $91192d.", ua = "Ваші зцілювальні закляття мають шанс надати $91192s1 інтелекту на $91192d." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $92233s1 dodge for $92233d.   Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $92233s1 ухилення на $92233d. Може спрацьовувати не частіше ніж раз на 30 сек." },
    { en = "Conjure a Guardian's Familiar to watch over up to $i nearby allies for $d. $s3% of damage each ally takes is transferred to you, up to $s1 total damage per target.", ua = "Прикличте Вартового Фаміліара, щоб він оберігав до $i союзників поблизу протягом $d. $s3% шкоди, яку отримує кожен союзник, передається вам, до $s1 загальної шкоди на ціль." },
    { en = "The device charges over time using your life force and then directs a burst of energy at your opponent.", ua = "Пристрій із часом заряджається, використовуючи вашу життєву силу, а потім спрямовує на супротивника спалах енергії." },
    { en = "Each time you cast a harmful spell, you gain $67743s1 haste.  Stacks up to $67743u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви застосовуєте шкідливе закляття, ви отримуєте $67743s1 швидкості. Накопичується до $67743u разів. Увесь ефект триває $d." },
    { en = "When you deal damage or heal a target you have a chance to gain $126705s1 Intellect for $126705d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, ви маєте шанс отримати $126705s1 інтелекту на $126705d." },
    { en = "Incoming attacks have a chance to trigger a retaliatory strike, inflicting $336595s1 Nature damage split between all nearby enemies and healing you for $s1.\n\n\n\nDamage and healing are increased per enemy struck, up to $s2.", ua = "Вхідні атаки мають шанс викликати удар у відповідь, завдаючи $336595s1 шкоди Природою, розподіленої між усіма ворогами поблизу, та зцілюючи вас на $s1.\n\n\n\nШкода й зцілення зростають за кожного враженого ворога, до $s2." },
    { en = "Casting spells has a high chance to tempt you with the power of the Void, increasing your Intellect by $s1 for $1259317d.\n\n\n\nEach temptation permanently increases this effect by $s2%, up to $1268058u times, diminishing quickly upon leaving combat.", ua = "Застосування заклять має високий шанс спокусити вас силою Порожнечі, підвищуючи ваш інтелект на $s1 на $1259317d.\n\n\n\nКожна спокуса назавжди підвищує цей ефект на $s2%, до $1268058u разів, швидко спадаючи після виходу з бою." },
    { en = "Each spell cast within 20 seconds will grant a stacking bonus of $469926s1 Intellect up to $469926u stacks. Expires after $d.", ua = "Кожне закляття, застосоване протягом 20 секунд, надає накопичувальний бонус $469926s1 інтелекту до $469926u стаків. Завершується через $d." },
    { en = "Your direct healing and heal over time spells have a chance to increase your haste by $60062s1 for $60062d.", ua = "Ваші пряме зцілення та закляття зцілення з часом мають шанс підвищити вашу швидкість на $60062s1 на $60062d." },
    { en = "Every swing poisons your foe for $26610s1 damage every second for $26610d.", ua = "Кожен удар отруює ворога, завдаючи $26610s1 шкоди щосекунди протягом $26610d." },
    { en = "Your attacks have a chance to grant you $138895s1 haste for $138895d.  This effect can stack up to $138895u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати вам $138895s1 швидкості на $138895d. Цей ефект накопичується до $138895u разів. (Приблизно ${$procrppm}.2 спрацьовувань за хвилину)" },
    { en = "While you have a greater health percentage than your target, your abilities have a very high chance to deal ${$s1*(1+$@versadmg)} Physical damage.\n\n\n\nWhile you have a lower health percentage than your target, your abilities have a very high chance to heal you for ${$s2*(1+$@versadmg)}.", ua = "Коли ваш відсоток здоров'я вищий за відсоток здоров'я цілі, ваші здібності мають дуже високий шанс завдати ${$s1*(1+$@versadmg)} фізичної шкоди.\n\n\n\nКоли ваш відсоток здоров'я нижчий за відсоток здоров'я цілі, ваші здібності мають дуже високий шанс зцілити вас на ${$s2*(1+$@versadmg)}." },
    { en = "Your taunt abilities activate the module's refracting energy, protecting you from $451568s2% of damage taken, up to $451568s1. This may only occur once every $451779d.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "Ваші здібності провокації активують заломлювальну енергію модуля, захищаючи вас від $451568s2% отриманої шкоди, але не більше ніж на $451568s1. Це може статися лише раз на $451779d.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Дійсне лише для спеціалізацій танка.|r]" },
    { en = "Your spells and abilities have a chance to infuse you with vita, increasing your Haste by $315787s1 and your party members' Haste by $316522s1. Lasts $315787d.", ua = "Ваші закляття та здібності мають шанс наповнити вас вітою, підвищуючи вашу швидкість на $315787s1 та швидкість членів вашої групи на $316522s1. Триває $315787d." },
    { en = "Your damaging spells that critically strike have a chance to increase your Haste, Mastery, or Critical Strike by $s2 for $253261d, stacking up to $253261u times. When any stack reaches $253261u, all effects are consumed to grant you $s3 of all three attributes for $253260d.", ua = "Ваші закляття, що завдають шкоди критичним ударом, мають шанс підвищити вашу швидкість, майстерність або критичний удар на $s2 на $253261d, накопичуючись до $253261u разів. Коли будь-який стак досягає $253261u, усі ефекти поглинаються, надаючи вам $s3 до всіх трьох характеристик на $253260d." },
    { en = "Your melee and ranged attacks have a chance to grant you a Fiery, Frost, or Arcane enchant for $225726d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати вам Вогняні, Крижані або Чародійські чари на $225726d." },
    { en = "Your melee and ranged attacks have a chance to grant you $97125s1 haste for $97125d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати вам $97125s1 швидкості на $97125d." },
    { en = "Recklessly intensify the power of the Spellforge, multiplying its current damage by ${(1+$445593s3/100)*100}% until shortly after leaving combat, up to $u times. At full power, gain $445593s2 Haste for $451845d when empowering your $?a137013[$@spellname78674][]$?a137012[$@spellname5176][]$?a396186[$@spellname395160][]$?a356809[$@spellname356995][]$?a356810[$@spellname361469][]$?a137019[$@spellname108853][]$?a137021[$@spellname44425][]$?a137020[$@spellname30455][]$?a137024[$@spellname107428][]$?a137031[$@spellname14914][]$?a137032[$@spellname585][]$?a137033[$@spellname8092][]$?a137040[$@spellname51505][]$?a137039[$@spellname51505][]$?a137046[$@spellname116858][]$?a137043[$@spellname324536][]$?a137044[$@spellname264178][]$?a137029[$@spellname20271][]$?a137047|$?a137034||$?a137023||$?a137025||$?a137014||$?a212611||$?a137005||$?a137010||$?a137011|[specialization spell][]. \n\n\n\nBeware glimpses of the Unseeming.", ua = "Необачно посилює міць Закляттєвого Горнила, помножуючи його поточну шкоду на ${(1+$445593s3/100)*100}% до моменту невдовзі після виходу з бою, до $u разів. На повній потужності отримуєте $445593s2 швидкості на $451845d, коли підсилюєте своє $?a137013[$@spellname78674][]$?a137012[$@spellname5176][]$?a396186[$@spellname395160][]$?a356809[$@spellname356995][]$?a356810[$@spellname361469][]$?a137019[$@spellname108853][]$?a137021[$@spellname44425][]$?a137020[$@spellname30455][]$?a137024[$@spellname107428][]$?a137031[$@spellname14914][]$?a137032[$@spellname585][]$?a137033[$@spellname8092][]$?a137040[$@spellname51505][]$?a137039[$@spellname51505][]$?a137046[$@spellname116858][]$?a137043[$@spellname324536][]$?a137044[$@spellname264178][]$?a137029[$@spellname20271][]$?a137047|$?a137034||$?a137023||$?a137025||$?a137014||$?a212611||$?a137005||$?a137010||$?a137011|[закляття спеціалізації][]. \n\n\n\nЗважайте на проблиски Незримого." },
    { en = "20% chance per combo point for your finishing moves to grant $40461s1 critical strike for $40461d.", ua = "20% шансу за кожну комбо-очку, що ваші завершальні прийоми нададуть $40461s1 критичного удару на $40461d." },
    { en = "Your attacks have a chance to awaken the powers of the races of Northrend, temporarily transforming you and increasing your combat capabilities for $71561d.", ua = "Ваші атаки мають шанс пробудити сили народів Нордскола, тимчасово перетворюючи вас і підвищуючи ваші бойові можливості на $71561d." },
    { en = "Your melee attacks have a chance to grant $102660s1 Critical Strike for $102660d.", ua = "Ваші атаки ближнього бою мають шанс надати $102660s1 критичного удару на $102660d." },
    { en = "Your healing and damaging spells have a chance to grant $120254s1 critical strike for $120254d.", ua = "Ваші зцілювальні закляття та закляття, що завдають шкоди, мають шанс надати $120254s1 критичного удару на $120254d." },
    { en = "Your heals have a chance to grant Luminescence to your most injured ally within $s2 yds. Allies with Luminescence receive $s3% additional healing, up to ${$s1*(1+$@versadmg)} total additional healing.", ua = "Ваше зцілення має шанс надати Люмінесценцію вашому найбільш пораненому союзнику в межах $s2 ярдів. Союзники з Люмінесценцією отримують $s3% додаткового зцілення, до ${$s1*(1+$@versadmg)} загального додаткового зцілення." },
    { en = "Taking Shadowflame damage has a chance to increase your Speed by $409077s1 for $409077d.", ua = "Отримання шкоди Тіньовим Полум'ям має шанс підвищити вашу швидкість пересування на $409077s1 на $409077d." },
    { en = "Increases your pet's attack power by $s1 for $d.", ua = "Підвищує силу атаки вашого улюбленця на $s1 на $d." },
    { en = "Increases time between target's attacks by $s1% for $d.", ua = "Збільшує час між атаками цілі на $s1% на $d." },
    { en = "When you deal damage or heal a target you have a chance to gain $102435s1 spell power for $102435d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, ви маєте шанс отримати $102435s1 сили заклять на $102435d." },
    { en = "Your ranged attacks have a chance to call a fiery orb that launches towards your target. The orb destabilizes after $s2 sec, exploding for $s1 damage split between nearby enemies.", ua = "Ваші дальні атаки мають шанс прикликати вогняну кулю, що летить до вашої цілі. Куля стає нестабільною за $s2 сек. і вибухає, завдаючи $s1 шкоди, розподіленої між ворогами поблизу." },
    { en = "Grant an ally $348137s2 Speed and heal them for ${$348137s1*($d/$t1)} health over $d.", ua = "Надає союзникові $348137s2 швидкості та зцілює його на ${$348137s1*($d/$t1)} здоров'я протягом $d." },
    { en = "Your harmful abilities have a chance to cause you to summon a Frostwolf to fight by your side for $175725d.", ua = "Ваші шкідливі здібності мають шанс прикликати Морозного Вовка, що б'ється на вашому боці протягом $175725d." },
    { en = "Your spells and abilities have a chance to grant you $268558s1 Versatility for $268558d.", ua = "Ваші закляття та здібності мають шанс надати вам $268558s1 універсальності на $268558d." },
    { en = "Increases your movement speed by $128882s1% while in Dread Wastes.", ua = "Підвищує вашу швидкість пересування на $128882s1%, поки ви перебуваєте в Жахливих Пустищах." },
    { en = "Your melee attacks have a chance to activate Screams of the Dead, granting you a random combat enhancement for $214807d.", ua = "Ваші атаки ближнього бою мають шанс активувати Крики Мертвих, що надають вам випадкове бойове підсилення на $214807d." },
    { en = "Activates your Arcanite Dragonling to fight for you for $d.", ua = "Активує вашого Арканітового Драконика, щоб він бився за вас протягом $d." },
    { en = "When struck in combat has a 1% chance of increasing all party member's armor by $18946s1 for $18946d.", ua = "При отриманні удару в бою має 1% шанс підвищити броню всіх членів групи на $18946s1 протягом $18946d." },
    { en = "Increases attack power by $s2 for $d. You feel drunk!", ua = "Підвищує силу атаки на $s2 протягом $d. Ви відчуваєте сп'яніння!" },
    { en = "Cause an eruption of abhorrent spines, striking all nearby enemies for $s1 Physical damage.", ua = "Спричиняє виверження огидних шипів, що вражають усіх ворогів поблизу на $s1 фізичної шкоди." },
    { en = "Amplifies your Critical Strike damage and healing, Haste, Mastery, and Versatility by $s2%. Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Підсилює вашу критичну шкоду й критичне зцілення, швидкість, майстерність та універсальність на $s2%. Знижена дієвість на рівні $ctrmin2066 і вище." },
    { en = "Increase your Versatility by $s1 for $d.", ua = "Підвищує вашу універсальність на $s1 протягом $d." },
    { en = "Your healing spells have a chance to grant $127572s1 spellpower for $127572d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші зцілювальні закляття мають шанс надати $127572s1 сили заклять на $127572d.  ($h% шанс, ${$proccooldown} сек. перезарядки)" },
    { en = "Your spells and abilities have a chance to grant $s1 Mastery per Neltharite you have equipped. Upon reaching $M2 stacks, all stacks are consumed and you gain $s3 secondary stats, split evenly for $376643d.", ua = "Ваші закляття та здібності мають шанс надати $s1 майстерності за кожен спорядженний Нелтарит. Сягнувши $M2 зарядів, усі заряди витрачаються, і ви отримуєте $s3 вторинних характеристик, розподілених рівномірно, протягом $376643d." },
    { en = "Your attacks may occasionally attract small celestial objects.", ua = "Ваші атаки інколи можуть притягувати дрібні небесні об'єкти." },
    { en = "Create a Dread Reflection at your location for $d and cause each of your Dread Reflections to unleash a torrent of magic that deals ${$246464s1*4} Shadow damage over $246463d, split evenly among nearby enemies.", ua = "Створює Жахливе Відображення у вашому місці на $d і змушує кожне ваше Жахливе Відображення вивільнити потік магії, що завдає ${$246464s1*4} шкоди Тінню протягом $246463d, розподіленої рівномірно між ворогами поблизу." },
    { en = "Your ranged attacks and spells have a chance to call down a Fel Meteor on your target, dealing $214052s1 Fire damage to them and nearby enemies.", ua = "Ваші дальні атаки та закляття мають шанс прикликати на вашу ціль Сквернний Метеор, завдаючи їй та ворогам поблизу $214052s1 шкоди Вогнем." },
    { en = "Teleport yourself to the Timeless Isle.", ua = "Телепортує вас на Позачасовий Острів." },
    { en = "Call upon Annhylde's Aegis for protection, reducing damage you take from enemies in front of you by $s3 for $d.\n\n\n\nIf the Aegis absorbs at least $s1 damage, it becomes overcharged and will expel coalesced power, dealing $s4 Holy damage to all enemies in front of you as it expires.", ua = "Прикликає Егіду Аннгільди для захисту, зменшуючи шкоду, яку ви отримуєте від ворогів перед вами, на $s3 протягом $d.\n\n\n\nЯкщо Егіда поглине щонайменше $s1 шкоди, вона перевантажується і вивільняє зосереджену силу, завдаючи $s4 шкоди Святом усім ворогам перед вами по закінченні дії." },
    { en = "When you deal damage you have a chance to gain $190025s1 Strength for $190025d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $190025s1 сили на $190025d." },
    { en = "Absorb up to ${$s1*(1+$@versadmg)} damage for $d, then heal for ${$s2*100}% of the shield's remaining amount.", ua = "Поглинає до ${$s1*(1+$@versadmg)} шкоди протягом $d, а потім зцілює на ${$s2*100}% залишкового обсягу щита." },
    { en = "Your attacks have a chance to grant you $148903s1 Agility for $148903d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати вам $148903s1 спритності на $148903d.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Summons a Whirlwind of Blades to fight for you for $d.", ua = "Прикликає Вихор Клинків, що б'ється за вас протягом $d." },
    { en = "Whenever you attack a new enemy for the first time, you demoralize it, reducing its damage done by $s2% up to $s1 for $406635d.", ua = "Щоразу, коли ви вперше атакуєте нового ворога, ви деморалізуєте його, зменшуючи завдану ним шкоду на $s2%, аж до $s1, протягом $406635d." },
    { en = "Restores $51348s1 health when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $51348s1 здоров'я, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше ніж раз на 10 секунд." },
    { en = "Whenever a nearby Automa dies, you exude Ephemera, healing up to $s3 nearby allies for ${$s2*$368932d} over $368932d.", ua = "Щоразу, коли поблизу гине Автома, ви випромінюєте Ефемеру, зцілюючи до $s3 союзників поблизу на ${$s2*$368932d} протягом $368932d." },
    { en = "Increases Arcane, Fire, Frost, Nature, and Shadow resistances by $s1 for $d.", ua = "Підвищує опір до Тайнощів, Вогню, Морозу, Природи та Тіні на $s1 протягом $d." },
    { en = "Draw power from the remnants of the Embersoul, gaining $423021s1 $pri for $d, decaying every $t3 sec. Once this effect ends, become Burned Out, losing $423021s2 Haste for 60 sec before recovering.\n\n\n\nWhen circumstances are dire your soul ignites, granting this bonus again without decaying. This effect may only occur once per combat.", ua = "Витягніть силу із залишків Жародуші, отримуючи $423021s1 $pri протягом $d, що згасає кожні $t3 сек. Щойно цей ефект завершиться, ви станете Вигорілими, втративши $423021s2 скорострільності на 60 сек, перш ніж відновитеся.\n\n\n\nКоли обставини стають критичними, ваша душа спалахує, надаючи цей бонус знову без згасання. Цей ефект може спрацювати лише раз за бій." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $71633s1 armor for $71633d.  Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $71633s1 броні на $71633d.  Не може спрацьовувати частіше ніж раз на 30 сек." },
    { en = "Increases the damage and duration of Flame Shock by $s1%.", ua = "Підвищує шкоду та тривалість Полум'яного Шоку на $s1%." },
    { en = "The sprig occasionally absorbs vital energies from enemies you defeat, granting you $s1 Speed when above $s3% Health. If you are below, you instead gain $s2 Leech. These effects last $1265132d.", ua = "Гілочка інколи поглинає життєву енергію з ворогів, яких ви здолали, надаючи вам $s1 швидкості, коли ваше здоров'я вище $s3%. Якщо нижче, ви натомість отримуєте $s2 висмоктування. Ці ефекти тривають $1265132d." },
    { en = "Your melee and ranged attacks have a chance to grant $102659s1 Haste for $102659d.", ua = "Ваші атаки ближнього та дального бою мають шанс надати $102659s1 швидкості на $102659d." },
    { en = "Your attacks have a chance to create a damaging shockwave that deals $225716s1 Physical damage to enemies in front of you.", ua = "Ваші атаки мають шанс створити шкідливу ударну хвилю, що завдає $225716s1 фізичної шкоди ворогам перед вами." },
    { en = "Your damaging spells have a chance to launch the crystal shard at your target which shatters on impact with an enemy, dealing $s1 Physical damage split between nearby enemies.", ua = "Ваші шкідливі закляття мають шанс запустити кристалічний уламок у вашу ціль, що розбивається при зіткненні з ворогом, завдаючи $s1 фізичної шкоди, розподіленої між ворогами поблизу." },
    { en = "Your damaging spells have a chance to draw a minion from the satchel, sending it running at your target where it explodes, dealing $s1 Shadow damage split between all nearby enemies.\n\n\n\nDamage is increased for each enemy struck, up to $s2 enemies.", ua = "Ваші шкідливі закляття мають шанс витягти прислужника з торбини, відправляючи його бігти до вашої цілі, де він вибухає, завдаючи $s1 шкоди Тінню, розподіленої між усіма ворогами поблизу.\n\n\n\nШкода зростає за кожного враженого ворога, аж до $s2 ворогів." },
    { en = "Calls down a meteor, burning all enemies within the area for $s1 total Fire damage.", ua = "Прикликає метеор, що спалює всіх ворогів у межах ділянки, завдаючи загалом $s1 шкоди Вогнем." },
    { en = "Your healing spells have a chance to apply a Spirit Fragment, preventing the next $221878s1 damage done to the target for $221878d.", ua = "Ваші зцілювальні закляття мають шанс накласти Фрагмент Духу, що запобігає наступним $221878s1 шкоди, завданим цілі, протягом $221878d." },
    { en = "Falling below $s2% health grants you a shield that absorbs $278159s2% of incoming damage, up to ${$s1*(1+$@versadmg)} total damage prevented. Lasts $278159d. This may only occur once every $279924d.", ua = "Падіння здоров'я нижче $s2% дарує вам щит, що поглинає $278159s2% вхідної шкоди, до ${$s1*(1+$@versadmg)} загальної відверненої шкоди. Триває $278159d. Може спрацьовувати лише раз на $279924d." },
    { en = "Casting spells and abilities builds stacks of Spite. At $s2, a Spiteful Stormbolt arcs towards your current target, dealing ${$s1*($382426d/$382426t1)*(1+$@versadmg)} Nature damage over $382426d.\n\n\n\nUpon expiration the bolt returns, increasing the amount of Spite needed by $s3 and permanently increasing Spiteful Stormbolt's damage against them until either of you die.", ua = "Застосування заклять і здібностей накопичує заряди Злоби. При $s2 Злобний Грозовий Болт б'є у вашу поточну ціль, завдаючи ${$s1*($382426d/$382426t1)*(1+$@versadmg)} шкоди від природи протягом $382426d.\n\n\n\nПісля завершення болт повертається, збільшуючи потрібну кількість Злоби на $s3 і назавжди підвищуючи шкоду Злобного Грозового Болта проти цілі, доки хтось із вас не загине." },
    { en = "Your damage dealing spells have a chance to trigger a Shadowbolt Volley, dealing $108005s1 damage to all enemies within $108005A1 yards of your current target.", ua = "Ваші заклинання, що завдають шкоди, мають шанс викликати Залп Тіньових Болтів, завдаючи $108005s1 шкоди всім ворогам у радіусі $108005A1 ярдів від вашої поточної цілі." },
    { en = "Your attacks have a chance to grant $165824s1 Mastery for $165824d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $165824s1 майстерності на $165824d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your heals have a chance to grant the target a shield absorbing $140380s1 damage, lasting $140380d. (Approximately ${$procrppm}.2 procs per minute, ${$proccooldown} sec cooldown)", ua = "Ваші зцілення мають шанс надати цілі щит, що поглинає $140380s1 шкоди, тривалістю $140380d. (Приблизно ${$procrppm}.2 спрацювань за хвилину, ${$proccooldown} сек. відновлення)" },
    { en = "Periodically imbue yourself while in combat with tainted Primal Wellspring water reducing your Versatility by $s3 and movement speed by $433726s3% for $433726d.\n\nDispelling the water's impurities reverse the effect, increasing your Versatility by $s1, movement speed by $433734s3% and granting all nearby allies a $s2 shield for $433734d.", ua = "Періодично під час бою просочує вас зіпсованою водою Первісного Джерела, зменшуючи вашу універсальність на $s3 і швидкість пересування на $433726s3% на $433726d.\n\nРозвіювання домішок води обертає ефект, підвищуючи вашу універсальність на $s1, швидкість пересування на $433734s3% і даруючи всім ближнім союзникам щит на $s2 тривалістю $433734d." },
    { en = "Stuns target for $d.  Increased chance to be resisted when used against targets over level $ctrmax2067.", ua = "Приголомшує ціль на $d. Підвищений шанс на спротив під час застосування проти цілей понад рівень $ctrmax2067." },
    { en = "Transform $?a251967[to Eye of F'harg]?a251968[to Eye of Shatug][the Eye].", ua = "Перетворює $?a251967[на Око Ф'харга]?a251968[на Око Шатуга][Око]." },
    { en = "Your melee and ranged abilities have a chance to increase your Strength or Agility by $253308s1 for $253308d.", ua = "Ваші ближні та далекобійні здібності мають шанс підвищити вашу силу або спритність на $253308s1 на $253308d." },
    { en = "The eye foresees your death, reducing all damage taken by up to ${$<WarlordsTrinketNerf>*$m2/100}.2% based on missing health.", ua = "Око передбачає вашу смерть, зменшуючи всю отриману шкоду до ${$<WarlordsTrinketNerf>*$m2/100}.2% залежно від нестачі здоров'я." },
    { en = "Your damaging spells and abilities have a chance to zap your opponent for $269889s1 Nature damage.", ua = "Ваші заклинання та здібності, що завдають шкоди, мають шанс уразити супротивника на $269889s1 шкоди від природи." },
    { en = "Your healing spells have a chance to grant you 20 stacks of Solemnity for $224346d, increasing your Haste by $224347s1 per stack. Solemnity loses a stack every $224346t2 sec.", ua = "Ваші зцілювальні заклинання мають шанс надати вам 20 зарядів Урочистості на $224346d, підвищуючи вашу швидкість на $224347s1 за заряд. Урочистість втрачає заряд кожні $224346t2 сек." },
    { en = "When you take damage, the torch has a chance to bathe you in light, healing you for $383939s1. The torchlight's healing increases based on your missing health.", ua = "Коли ви отримуєте шкоду, смолоскип має шанс огорнути вас світлом, зцілюючи на $383939s1. Зцілення світла смолоскипа зростає залежно від нестачі вашого здоров'я." },
    { en = "While no allies are within $289590A1 yds of you, gain $289523s1 Critical Strike every $t1 sec. At $289523u applications of this effect, you also gain $289524s1 Mastery. These effects slowly fade when allies are nearby, unless they also bear this item.", ua = "Доки поблизу немає союзників у радіусі $289590A1 ярдів, ви отримуєте $289523s1 критичного удару кожні $t1 сек. При $289523u накопиченнях цього ефекту ви також отримуєте $289524s1 майстерності. Ці ефекти повільно згасають, коли поряд є союзники, якщо тільки вони не мають цього предмета." },
    { en = "Your healing and damaging spells have a chance to grant $118750s1 mastery for $118750d.", ua = "Ваші зцілювальні заклинання та заклинання шкоди мають шанс надати $118750s1 майстерності на $118750d." },
    { en = "Your attacks have a chance to call a lupine to lacerate the enemy, dealing ${$s1*($367726d/1.5)} Physical damage over $367726d.", ua = "Ваші атаки мають шанс прикликати вовка, що роздирає ворога, завдаючи ${$s1*($367726d/1.5)} фізичної шкоди протягом $367726d." },
    { en = "Your healing effects have a chance to grow an Emerald Blossom nearby, which heals a random injured ally for $257442s1 every $s4 sec. Lasts $256823d.\n\n\n\n|cFFFFFFFFEonar's Verdant Embrace|r\n\nWhen empowered by the Pantheon, your next $257470u $?a137012[Rejuvenation]?a137024[Vivify]?a137031[Flash Heal]?a137032[Power Word: Shield]?a137029[Flash of Light]?a137039[Healing Wave][direct healing] spells grant the target a shield that prevents $257444s1 damage for $257444d.", ua = "Ваші ефекти зцілення мають шанс виростити поруч Смарагдовий Квіт, який зцілює випадкового пораненого союзника на $257442s1 кожні $s4 сек. Триває $256823d.\n\n\n\n|cFFFFFFFFСоковито-зелені обійми Еонар|r\n\nКоли вас наснажує Пантеон, ваші наступні $257470u заклять $?a137012[Відновлення]?a137024[Оживлення]?a137031[Зцілення-спалах]?a137032[Слово сили: Щит]?a137029[Спалах світла]?a137039[Хвиля зцілення][прямого зцілення] надають цілі щит, що запобігає $257444s1 шкоди на $257444d." },
    { en = "Conjures a Power Circle lasting for $d.  While standing in this circle, the caster gains $45044s1 spell power.", ua = "Прикликає Коло Сили тривалістю $d. Стоячи в цьому колі, заклинач отримує $45044s1 сили заклять." },
    { en = "Your Windfury Attacks deal $s1% increased damage and generate $s2 additional Maelstrom.", ua = "Ваші Атаки Вітряної Люті завдають на $s1% більше шкоди і генерують $s2 додаткового Виру." },
    { en = "Each time you deal spell damage to an opponent, you gain $71572s1 spell power for the next $71572d, stacking up to $71572u times.", ua = "Щоразу, коли ви завдаєте супротивнику шкоди закляттями, ви отримуєте $71572s1 сили заклять на наступні $71572d, накопичуючись до $71572u разів." },
    { en = "Enter a fel-crazed rage, dealing $225777s1 Shadow damage to a random nearby enemy every ${$t1}.2 sec for $d. You cannot move or use abilities during your rage.", ua = "Впадаєте у скверноскажену лють, завдаючи $225777s1 шкоди від темряви випадковому ближньому ворогу кожні ${$t1}.2 сек протягом $d. Під час люті ви не можете рухатися чи застосовувати здібності." },
    { en = "When you deal damage or heal a target you have a chance to gain $99719s1 spell power for $99719d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, ви маєте шанс отримати $99719s1 сили заклять на $99719d." },
    { en = "Your harmful spells have a chance to increase your spell power by $71600s1 and an additional $71600s1 every $71601t1 sec for $71601d.", ua = "Ваші шкідливі заклинання мають шанс підвищити вашу силу заклять на $71600s1 і ще на $71600s1 кожні $71601t1 сек протягом $71601d." },
    { en = "Join the Dream Team, gaining ${$s1/$426647d} of Pip's Mastery, Urctos's Versatility, or Aerwynn's Critical Strike based on your current Best Friend.\n\n\n\nYour spells and abilities have a chance to tag in a random new Best Friend, granting you their passive bonus and empowering it to $s1 before diminishing over 12 sec.", ua = "Приєднайтеся до Команди Мрії, отримуючи ${$s1/$426647d} майстерності Піпа, універсальності Урктоса чи критичного удару Аервінн залежно від вашого поточного Найкращого Друга.\n\n\n\nВаші заклинання та здібності мають шанс залучити випадкового нового Найкращого Друга, даруючи вам його пасивний бонус і підсилюючи його до $s1, перш ніж він спадатиме протягом 12 сек." },
    { en = "Each time you cast a damaging or healing spell you gain $60486s1 spell power for the next $60486d, stacking up to 10 times.", ua = "Щоразу, коли ви застосовуєте заклинання шкоди чи зцілення, ви отримуєте $60486s1 сили заклять на наступні $60486d, накопичуючись до 10 разів." },
    { en = "Each time one of your spells deals periodic damage, there is a chance $45055s1 additional damage will be dealt.", ua = "Щоразу, коли одне з ваших заклять завдає періодичної шкоди, є шанс, що буде завдано $45055s1 додаткової шкоди." },
    { en = "Gives a chance on melee or ranged attack to apply an effect on you for $d, increasing your critical strike by $26481s1. The critical strike effect can be applied up to 6 times.", ua = "Дає шанс при ближній чи далекобійній атаці накласти на вас ефект на $d, підвищуючи ваш критичний удар на $26481s1. Ефект критичного удару може накладатися до 6 разів." },
    { en = "Your attacks have a chance to increase your Haste by $278865s1 every $278865t2 sec. Lasts $278865d.", ua = "Ваші атаки мають шанс підвищувати вашу швидкість на $278865s1 кожні $278865t2 сек. Триває $278865d." },
    { en = "Your melee and ranged attacks have a chance to grant $118613s1 mastery for $118613d.", ua = "Ваші ближні та далекобійні атаки мають шанс надати $118613s1 майстерності на $118613d." },
    { en = "Your ranged attacks and spells have a chance to unleash a Dark Blast in the direction of your target, dealing $s1 Shadow damage to all enemies in the line.", ua = "Ваші далекобійні атаки та заклинання мають шанс вивільнити Темний Вибух у напрямку вашої цілі, завдаючи $s1 шкоди від темряви всім ворогам на лінії." },
    { en = "Increases your spellpower by $s1 for $d.", ua = "Підвищує вашу силу заклять на $s1 на $d." },
    { en = "Your melee attacks have a chance to grant you a Mote of Anger.  When you reach ${$71432u-1} Motes of Anger, they will release, causing you to instantly attack for $71433s2% weapon damage with one of your melee weapons.", ua = "Ваші ближні атаки мають шанс надати вам Часточку Гніву. Коли ви досягаєте ${$71432u-1} Часточок Гніву, вони вивільняються, змушуючи вас миттєво атакувати на $71433s2% шкоди зброї однією з ваших ближніх зброй." },
    { en = "Each time you cast a harmful spell, you gain $67735s1 haste.  Stacks up to $67735u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви застосовуєте шкідливе закляття, ви отримуєте $67735s1 швидкості. Накопичується до $67735u разів. Весь ефект триває $d." },
    { en = "When you deal damage you have a chance to gain $109776s1 mastery for $109776d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109776s1 майстерності на $109776d." },
    { en = "Tear the anima from your target dealing $s1 Shadow damage and forming a font of power at your feet, increasing your Intellect by $343397s1 for $343394d while you stand within it.", ua = "Вириває аніму з вашої цілі, завдаючи $s1 шкоди від темряви та утворюючи джерело сили біля ваших ніг, що підвищує ваш інтелект на $343397s1 на $343394d, доки ви стоїте в ньому." },
    { en = "Embrace the gem to increase your Critical Strike by $s1 for $d. Your healing as well as damage-dealing spells and abilities have a high chance to empower the gem, increasing its effect.", ua = "Прийміть самоцвіт, щоб підвищити ваш критичний удар на $s1 на $d. Ваші зцілювальні заклинання й здібності, а також ті, що завдають шкоди, мають високий шанс підсилити самоцвіт, посилюючи його ефект." },
    { en = "Your attacks have a chance to grant $176935s1 Mastery for $176935d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176935s1 майстерності на $176935d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Mind Flay damage applies Mental Fatigue to the target, increasing damage taken from Mind spells by ${$m1/100}.2% for $185104d, stacking up to $185104u times.", ua = "Шкода від Виснаження Розуму накладає на ціль Розумову Втому, підвищуючи отриману шкоду від заклять Розуму на ${$m1/100}.2% на $185104d, накопичуючись до $185104u разів." },
    { en = "Grant an ally Writhing Ward for $d, absorbing up to $401239s1 damage. If broken, the Ward coalesces into Writhing Ire, dealing ${$401239s2*($401257d/$401257t1)} Shadowflame damage over $401257d to the last enemy to strike it.", ua = "Дарує союзникові Звивистий Оберіг на $d, поглинаючи до $401239s1 шкоди. Якщо оберіг зруйновано, він перетворюється на Звивисту Лють, завдаючи ${$401239s2*($401257d/$401257t1)} шкоди тіньовим полум'ям протягом $401257d останньому ворогові, який його вдарив." },
    { en = "Creates a Battle Chicken that will fight for you for $13166d or until it is destroyed.", ua = "Створює Бойову Курку, яка битиметься за вас протягом $13166d або доки її не знищать." },
    { en = "Raise your signet to the Light, increasing your highest secondary stat by $450877s2 for $d. Your act inspires nearby signetbearers within your party, granting them $450877s1 of the same stat for $450882d.", ua = "Здіймає вашу печатку до Світла, підвищуючи вашу найвищу другорядну характеристику на $450877s2 на $d. Ваш вчинок надихає сусідніх печатконосців у вашій групі, надаючи їм $450877s1 тієї самої характеристики на $450882d." },
    { en = "While in combat your rage builds, increasing your Haste by $s1 every $356490t sec, stacking up to $356492u times.", ua = "У бою ваша лють зростає, підвищуючи вашу швидкість на $s1 кожні $356490t сек, накопичуючись до $356492u разів." },
    { en = "Calls forth 3 servants of the House Barov that will fight, cook, and clean for you.", ua = "Прикликає 3 слуг дому Баровів, які битимуться, готуватимуть і прибиратимуть за вас." },
    { en = "Melee attacks which reduce you below $s1% health cause you to instantly heal for $138973s1.   Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, миттєво зцілюють вас на $138973s1. Може спрацьовувати не частіше, ніж раз на 30 сек." },
    { en = "Inject an enemy with digestive venom, dealing $444258s1 Nature damage over 20 sec. While active, your attacks and abilities against the target restore $444258s2 health. Cannot occur more than every 1 sec. \n\n\n\nOverhealing from this effect permanently increases your maximum health by the same amount, becoming an absorb shield upon leaving combat.", ua = "Впорскує ворогові травну отруту, завдаючи $444258s1 шкоди силами природи протягом 20 сек. Доки ефект активний, ваші атаки та здібності проти цілі відновлюють $444258s2 здоров'я. Може спрацьовувати не частіше, ніж раз на 1 сек.\n\n\n\nНадлишкове зцілення від цього ефекту назавжди підвищує ваше максимальне здоров'я на ту саму величину, перетворюючись на поглинальний щит після виходу з бою." },
    { en = "Increases chance to deal and take a  Critical Strike by $s1% for $d. Only usable in Falcosaur and PvP World Quest areas.", ua = "Підвищує шанс завдати та отримати критичний удар на $s1% на $d. Можна застосовувати лише в зонах фалькозаврів та світових завдань PvP." },
    { en = "Taking damage has a chance to erupt the ground, covering you in a layer of dark oil that absorbs $s2 damage for $1216921d1. When the shield is broken, it splatters nearby enemies for $s3 Shadow damage.", ua = "Отримання шкоди має шанс розверзнути землю, вкриваючи вас шаром темної нафти, що поглинає $s2 шкоди протягом $1216921d1. Коли щит зруйновано, він оббризкує сусідніх ворогів, завдаючи $s3 шкоди силами тіні." },
    { en = "Replant the Seedling and attempt to put out its flames for $d. Healing the Seedling also heals up to $s3 injured allies for the same amount, split evenly. Healing is increased for each ally until $422081s1 additional healing is provided.\n\n\n\n\n\nIf the Seedling is still alive after $d, receive $422081s2 Mastery for 10 sec as thanks.", ua = "Пересаджує Сіянець і намагається загасити його полум'я протягом $d. Зцілення Сіянця також зцілює до $s3 поранених союзників на ту саму величину, поділену порівну. Зцілення зростає за кожного союзника, доки не буде надано $422081s1 додаткового зцілення.\n\n\n\n\n\nЯкщо Сіянець досі живий по завершенні $d, ви отримуєте $422081s2 майстерності на 10 сек на знак подяки." },
    { en = "Your healing spells have a chance to put you into a waking dream, granting additional mana regeneration and increasing your Mastery by $383816s2 for $383816d.", ua = "Ваші зцілювальні закляття мають шанс занурити вас у марення наяву, надаючи додаткову регенерацію мани та підвищуючи вашу майстерність на $383816s2 на $383816d." },
    { en = "Your attacks have a chance to grant you $126533s1 armor for $126533d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $126533s1 броні на $126533d. ($h% шансу, ${$proccooldown} сек відновлення)" },
    { en = "Your melee and ranged attacks have a chance to grant you ${$146310m1*20} Agility for $146310d.  Every $146310t2 sec this effect decrements by $146310m1 Agility. (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки ближнього та далекого бою мають шанс надати вам ${$146310m1*20} спритності на $146310d. Кожні $146310t2 сек цей ефект зменшується на $146310m1 спритності. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Place a Mogu Rune of Paralysis on the ground for $d, which will stun the next creature that enters it for $129553d.", ua = "Розміщує на землі Мог'юську Руну Паралічу на $d, яка оглушить наступну істоту, що ступить на неї, на $129553d." },
    { en = "You gain $s1% more mana when you use a mana gem.  In addition, using a mana gem grants you $37445s1 spell power for $37445d.", ua = "Ви отримуєте на $s1% більше мани, коли використовуєте самоцвіт мани. Крім того, використання самоцвіта мани надає вам $37445s1 сили заклять на $37445d." },
    { en = "$s3% of damage taken grants you Healing Blood, up to ${$s1*(1+$@versadmg)} total. Every $303520t1 sec, ${$s2*(1+$@versadmg)} Healing Blood is expended to heal you if you are injured.", ua = "$s3% отриманої шкоди надає вам Зцілющу Кров, загалом до ${$s1*(1+$@versadmg)}. Кожні $303520t1 сек ${$s2*(1+$@versadmg)} Зцілющої Крові витрачається, щоб зцілити вас, якщо ви поранені." },
    { en = "Your melee and ranged attacks have a chance to grant $122919s1 mastery for $122919d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $122919s1 майстерності на $122919d." },
    { en = "Your damaging spells have a chance to afflict the target with Nightmare Corruption for $222706d, causing your spells to deal up to $s1 additional damage as Shadow. Every $222706t2 sec Nightmare Corruption attempts to spread to a nearby enemy. If no uninfected enemies are nearby, the intensity of the Corruption increases.", ua = "Ваші закляття, що завдають шкоди, мають шанс уразити ціль Жахливою Скверною на $222706d, через що ваші закляття завдають до $s1 додаткової шкоди силами тіні. Кожні $222706t2 сек Жахлива Скверна намагається поширитися на сусіднього ворога. Якщо поруч немає неуражених ворогів, інтенсивність Скверни зростає." },
    { en = "Your spell casts have a chance to grant $71584s1 Versatility for $71584d.", ua = "Ваші закляття мають шанс надати $71584s1 універсальності на $71584d." },
    { en = "When you deal damage you have a chance to gain $126707s1 Agility for $126707d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $126707s1 спритності на $126707d." },
    { en = "Your melee and ranged attacks have a chance to grant $122690s1 haste for $122690d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $122690s1 швидкості на $122690d." },
    { en = "Duration of incoming crowd control effects increased by $s1%. Does not stack with similar effects. When affected, protects from the next crowd control effect, persisting for $362699d.", ua = "Тривалість вхідних ефектів контролю натовпу збільшено на $s1%. Не накопичується з подібними ефектами. У разі дії захищає від наступного ефекту контролю натовпу, зберігаючись протягом $362699d." },
    { en = "Your attacks have a chance to grant $183926s1 Agility for $183926d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $183926s1 спритності на $183926d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increases your spell power by ${$24659m1*12} for $d. Every time you cast a spell, the bonus is reduced by $24659m1 spell power.", ua = "Підвищує вашу силу заклять на ${$24659m1*12} на $d. Щоразу, коли ви твоїте закляття, бонус зменшується на $24659m1 сили заклять." },
    { en = "Every $455535t sec in combat take 1% of your maximum Health as Nature damage and gain a stack of Symbiosis, granting $s2 Versatility for $455536d  stacking up to 5 times.", ua = "Кожні $455535t сек у бою ви отримуєте шкоду силами природи в розмірі 1% вашого максимального здоров'я та здобуваєте заряд Симбіозу, що надає $s2 універсальності на $455536d, накопичуючись до 5 разів." },
    { en = "Each time you cast a spell you gain $60525s1 Versatility for the next 10 sec, stacking up to 10 times.", ua = "Щоразу, коли ви твоїте закляття, ви отримуєте $60525s1 універсальності на наступні 10 сек, накопичуючись до 10 разів." },
    { en = "Your healing and damaging spells have a chance to grant $118871s1 mastery for $118871d.", ua = "Ваші зцілювальні закляття та закляття, що завдають шкоди, мають шанс надати $118871s1 майстерності на $118871d." },
    { en = "Your Rejuvenation and Lifebloom ticks have a $s1% chance to also heal other allies within $185019A1 yds.", ua = "Тіки ваших заклять Омолодження та Цвіт Життя мають $s1% шансу також зцілити інших союзників у межах $185019A1 м." },
    { en = "Your abilities have a chance to wrap your target in blue flames, causing ${$s1*$377420d} Arcane damage over $377420d.", ua = "Ваші здібності мають шанс огорнути вашу ціль блакитним полум'ям, завдаючи ${$s1*$377420d} шкоди силами тайнощів протягом $377420d." },
    { en = "Garrote your target from behind, causing them to bleed for $s1 Physical damage every $t1 sec until they die.", ua = "Гарротуєте вашу ціль ззаду, через що вона стікає кров'ю, отримуючи $s1 фізичної шкоди кожні $t1 сек, доки не загине." },
    { en = "Your damaging and healing spells have a chance to shine through one of the facets, increasing a random secondary stat by $s1 for 10 seconds.", ua = "Ваші закляття, що завдають шкоди та зцілюють, мають шанс зблиснути крізь одну з граней, підвищуючи випадкову другорядну характеристику на $s1 на 10 секунд." },
    { en = "Your healing spells have a chance to increase your Critical Strike or Haste by $s2 for $242543d. This effect grants Critical Strike during the day, or Haste during the night.", ua = "Ваші зцілювальні закляття мають шанс підвищити ваш критичний удар або швидкість на $s2 на $242543d. Цей ефект надає критичний удар удень або швидкість уночі." },
    { en = "Your healing and damaging spells have a chance to grant $122314s1 Versatility for $122314d.", ua = "Ваші зцілювальні закляття та закляття, що завдають шкоди, мають шанс надати $122314s1 універсальності на $122314d." },
    { en = "Your spells and abilities have a chance to grant you $285500s1 Critical Strike for $285500d.", ua = "Ваші закляття та здібності мають шанс надати вам $285500s1 критичного удару на $285500d." },
    { en = "Your abilities have a chance to summon a Silverpaw Lynx to strike at your foes, dealing $s1 physical damage split between all nearby enemies. Damage is increased per target hit.", ua = "Ваші здібності мають шанс прикликати Рись Срібнолапу, що вражає ваших ворогів, завдаючи $s1 фізичної шкоди, поділеної між усіма сусідніми ворогами. Шкода зростає за кожну уражену ціль." },
    { en = "Your spells have a chance to grant you the Lingering Power of Xalzaix for $278155d. When it reaches $278155u charges the power is released, increasing your Intellect by $278156s1 for $278156d.", ua = "Ваші закляття мають шанс наділити вас Залишковою Силою Залзаікса на $278155d. Коли вона досягає $278155u зарядів, сила вивільняється, підвищуючи ваш інтелект на $278156s1 на $278156d." },
    { en = "Reduces your fall speed for $d.", ua = "Зменшує швидкість вашого падіння на $d." },
    { en = "Your healing spells have a chance to make your next heal cast within $60515d cost $60515s1 less mana.", ua = "Ваші зцілювальні закляття мають шанс зробити так, що ваше наступне зцілення, застосоване протягом $60515d, коштуватиме на $60515s1 менше мани." },
    { en = "Your melee and ranged attacks have a chance to grant $97139s1 critical strike, haste, or mastery for 30 sec, whichever is currently highest.", ua = "Ваші ближні та дальні атаки мають шанс надати $97139s1 критичного удару, швидкості або майстерності на 30 сек., залежно від того, який показник наразі найвищий." },
    { en = "Your damaging spells have a chance to fire a Soulseeker Arrow towards your target, inflicting ${$s2*($388755d/$388755t1+1)*(1+$@versadmg)} Shadow damage over $388755d. If the target dies while affected, your next damaging spells will fire an arrow.", ua = "Ваші шкодочинні закляття мають шанс випустити Стрілу Шукача Душ у вашу ціль, завдаючи ${$s2*($388755d/$388755t1+1)*(1+$@versadmg)} тіньової шкоди протягом $388755d. Якщо ціль гине, перебуваючи під дією ефекту, ваші наступні шкодочинні закляття випустять стрілу." },
    { en = "While out of combat, invoke the Plume's dual nature to transform it into a Radiant Plume.", ua = "Поза боєм виклич подвійну природу Пера, щоб перетворити його на Осяйне Перо." },
    { en = "Your melee attacks have a chance to grant $118753s1 mastery for $118753d.", ua = "Ваші ближні атаки мають шанс надати $118753s1 майстерності на $118753d." },
    { en = "Your attacks have a chance to grant Recursive Strikes for $225736d, causing your auto attacks to deal an additional $225736s1 damage and increase the intensity of Recursive Strikes.", ua = "Ваші атаки мають шанс надати Рекурсивні Удари на $225736d, через що ваші автоатаки завдають додатково $225736s1 шкоди та підвищують інтенсивність Рекурсивних Ударів." },
    { en = "Your critical strikes have a chance to stir the void within granting you $s1 $?(a137047|a137005|a137026)[Strength]?(a212611|a137009|a137014|a137022|a137034|a137038)[Agility][Strength or Agility] for $1255226d1.", ua = "Ваші критичні удари мають шанс розбурхати в собі Порожнечу, даруючи вам $s1 $?(a137047|a137005|a137026)[сили]?(a212611|a137009|a137014|a137022|a137034|a137038)[спритності][сили або спритності] на $1255226d1." },
    { en = "Your damaging spells and abilities have a chance to summon a Poison Frog that spits a volley of poison darts at the target, each strike sinking deeper as the venom compounds, doubling in potency with every hit. Deals a total of ${$s2*7} damage over $1260522d.", ua = "Ваші шкодочинні закляття та здібності мають шанс прикликати Отруйну Жабу, що випльовує залп отруйних дротиків у ціль, причому кожен удар занурюється глибше в міру накопичення отрути, подвоюючи потужність із кожним влучанням. Завдає в сумі ${$s2*7} шкоди протягом $1260522d." },
    { en = "When dealing damage with spells, you have a chance to deal $89091s1 additional Fire damage to the target and gain $89091s2 Intellect for $89091d.", ua = "Завдаючи шкоди заклятьями, ви маєте шанс завдати цілі $89091s1 додаткової вогняної шкоди та отримати $89091s2 інтелекту на $89091d." },
    { en = "Your melee attacks have a chance to grant $102667s1 dodge for $102667d.", ua = "Ваші ближні атаки мають шанс надати $102667s1 ухилення на $102667d." },
    { en = "Reflects Shadow and Nature spells back at their caster for $d.", ua = "Відбиває тіньові й природні закляття назад у того, хто їх застосовує, протягом $d." },
    { en = "Launch $s2 Holy Bolts at injured allies within $r yds over $d, healing for $230017s1 per Bolt.", ua = "Запускає $s2 Святих Блискавок у поранених союзників у межах $r ярд. протягом $d, зцілюючи на $230017s1 за кожну Блискавку." },
    { en = "Creates a mobile bomb that charges the nearest enemy and explodes for $s1 fire damage.", ua = "Створює рухому бомбу, що мчить до найближчого ворога й вибухає, завдаючи $s1 вогняної шкоди." },
    { en = "Increases your Agility or Intellect by $s3 for $d. Your ranged attacks and spells cause this effect to stack, up to $u times.", ua = "Підвищує вашу спритність або інтелект на $s3 на $d. Ваші дальні атаки та закляття змушують цей ефект накопичуватися, до $u разів." },
    { en = "Each time you are struck by an attack, you gain $67741s1 armor.  Stacks up to $67741u times.  Entire effect lasts $d.", ua = "Щоразу, коли вас уражає атака, ви отримуєте $67741s1 броні. Накопичується до $67741u разів. Увесь ефект триває $d." },
    { en = "Falling below $s1% health activates the defense matrix for up to $433770d, absorbing $433770s2% of damage taken up to a maximum of $s3. While the matrix holds, the resonator pulses every $433770t3 sec to deal $s2 Fire damage to all nearby enemies. Damage is reduced beyond 8 enemies.\n\n\n\nThis may only occur once every $433759d.", ua = "Падіння здоров'я нижче $s1% активує оборонну матрицю на час до $433770d, яка поглинає $433770s2% отриманої шкоди до максимуму в $s3. Поки матриця тримається, резонатор пульсує кожні $433770t3 сек., завдаючи $s2 вогняної шкоди всім ворогам поблизу. Шкода зменшується за межами 8 ворогів.\n\n\n\nЦе може статися лише раз на $433759d." },
    { en = "Whenever you or one of your allies falls below $417960s1% health, the Tyrstone will summon an echo of your past self, healing them for the stored amount split among nearby allies and granting $s3 Haste for $418080d before the record is lost. Deals increased healing when healing multiple allies.", ua = "Щоразу, коли ви або один із ваших союзників опускаєтеся нижче $417960s1% здоров'я, Камінь Тіра прикличе відлуння вашого минулого \"я\", зцілюючи на накопичений обсяг, розподілений між союзниками поблизу, та надаючи $s3 швидкості на $418080d, перш ніж запис буде втрачено. Завдає посиленого зцілення, коли зцілює кількох союзників." },
    { en = "Your attacks have a chance to eviscerate the target for $s1 Physical damage. Deals twice the damage when behind your target.", ua = "Ваші атаки мають шанс випатрати ціль, завдаючи $s1 фізичної шкоди. Завдає вдвічі більше шкоди, коли ви позаду цілі." },
    { en = "Your harmful spells and abilities apply Ratfang Toxin to your target, stacking up to $s1 times.", ua = "Ваші шкідливі закляття та здібності накладають на ціль Отруту Щуролика, що накопичується до $s1 разів." },
    { en = "Your harmful spells and abilities have a chance to fracture the enemy's soul, dealing ${$s1*$<rolemult>} Shadow damage over $1225149d. If a fractured enemy dies, you absorb their lingering energy, increasing your Versatility by $s2 for $1225151d.", ua = "Ваші шкідливі закляття та здібності мають шанс розколоти душу ворога, завдаючи ${$s1*$<rolemult>} тіньової шкоди протягом $1225149d. Якщо розколотий ворог гине, ви поглинаєте його залишкову енергію, підвищуючи вашу універсальність на $s2 на $1225151d." },
    { en = "Your harmful spells and abilities have a low chance to call upon tragic arcane powers to infect your target with Crystal Sickness, dealing ${($s1*$433522d/$433522t1*$433522u)/2} Arcane damage over $433522d, increasing every second. \n\n\n\nCreatures, other than players and bosses, who drop below $s2% health while afflicted will crystallize, die and infect a nearby enemy with Crystal Sickness. This can happen up to $s4 times.", ua = "Ваші шкідливі закляття та здібності мають низький шанс закликати трагічні чародійні сили, щоб заразити вашу ціль Кришталевою Хворобою, завдаючи ${($s1*$433522d/$433522t1*$433522u)/2} чародійної шкоди протягом $433522d, що зростає щосекунди. \n\n\n\nІстоти, окрім гравців і босів, що опускаються нижче $s2% здоров'я під час дії ефекту, кристалізуються, гинуть і заражають Кришталевою Хворобою ворога поблизу. Це може статися до $s4 разів." },
    { en = "Increases the damage of your Imp's Firebolt spell by $s1.", ua = "Підвищує шкоду заклинання Вогняна Стріла вашого Біса на $s1." },
    { en = "The gland releases pheromones that attract a Ceaseless Swarm of insects to surround you. Taking damage has a high chance to retaliate against attackers, inflicting ${$s1*$450969d/$450969t1} Nature damage over $450969d and reducing damage dealt to you by $s2.", ua = "Залоза вивільняє феромони, що приваблюють Невпинний Рій комах, який оточує вас. Отримання шкоди має високий шанс відплатити нападникам, завдаючи ${$s1*$450969d/$450969t1} природної шкоди протягом $450969d та зменшуючи шкоду, завдану вам, на $s2." },
    { en = "Healing with Holy Shock grants you Magnifying Light, increasing the healing of your next Holy Light or Flash of Light within $185100d by $185100s1%.", ua = "Зцілення за допомогою Святого Шоку надає вам Підсилювальне Світло, що підвищує зцілення вашого наступного Святого Світла або Спалаху Світла протягом $185100d на $185100s1%." },
    { en = "Your Arcane Shot ability increases the damage dealt by all other damaging shots by $37508s1 for $37508d.", ua = "Ваша здібність Чародійний Постріл підвищує шкоду, завдану всіма іншими шкодочинними пострілами, на $37508s1 на $37508d." },
    { en = "Bathe your target ally in radiant light, healing them for $1255804s1 and imbuing them for $1254624d.\n\nWhile imbued, your healing spells and abilities also heal this ally for $1255804s2.", ua = "Огортає обрану ціль-союзника сяйливим світлом, зцілюючи її на $1255804s1 та насичуючи на $1254624d.\n\nПоки ціль насичена, ваші зцілювальні закляття та здібності також зцілюють цього союзника на $1255804s2." },
    { en = "Your periodic damage spells have a chance to grant $138898s1 Intellect for $138898d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші періодичні шкодочинні закляття мають шанс надати $138898s1 інтелекту на $138898d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Your damaging and healing abilities have a chance to activate Umbric's Channeling Focus, increasing your highest secondary stat by $s2 for $1253325d.", ua = "Ваші шкодочинні та зцілювальні здібності мають шанс активувати Зосередження Каналізації Умбрика, підвищуючи ваш найвищий вторинний показник на $s2 на $1253325d." },
    { en = "Places Egg Shell on your current target, absorbing ${$96173s2+$96173s3} damage. While Egg Shell persists, you gain ${$96173s4/($d/$t2)}.2% mana every $t2 sec.  When the effect ends, you gain $96173s5% mana.  Lasts $d.", ua = "Накладає на вашу поточну ціль Яєчну Шкаралупу, що поглинає ${$96173s2+$96173s3} шкоди. Поки Яєчна Шкаралупа тримається, ви отримуєте ${$96173s4/($d/$t2)}.2% мани кожні $t2 сек. Коли ефект завершується, ви отримуєте $96173s5% мани. Триває $d." },
    { en = "Summons a Winterpelt totem at the target location for $d. Party members within $s2 yards have a high chance to deal $398322s1 bonus Nature damage when dealing a harmful spell or ability.\n\n\n\nThe bonus damage is increased if the affected ally is a furbolg.", ua = "Прикликає тотем Зимошкурого в указаному місці на $d. Учасники групи в межах $s2 ярд. мають високий шанс завдати $398322s1 додаткової природної шкоди, застосовуючи шкідливе закляття чи здібність.\n\n\n\nДодаткова шкода збільшується, якщо уражений союзник — фурболг." },
    { en = "Your spells and abilities have a chance to grant you $268518s1 Critical Strike for $268518d.", ua = "Ваші закляття та здібності мають шанс надати вам $268518s1 критичного удару на $268518d." },
    { en = "Your harmful spells have a high chance to draw unstable flames from the Vessel, increasing your Haste by $s4 and dealing ${$s1*$401394d/$401394t2} Fire damage to you over $401394d.\n\n\n\nUpon reaching $401394u stacks the flames leap toward your target, combusting immediately for $401395s2 Shadow damage, then burning them for ${$401395s3*6} Shadowflame damage over 12 seconds.", ua = "Ваші шкідливі закляття мають високий шанс витягти нестабільне полум'я з Посудини, підвищуючи вашу швидкість на $s4 та завдаючи вам ${$s1*$401394d/$401394t2} вогняної шкоди протягом $401394d.\n\n\n\nДосягнувши $401394u зарядів, полум'я стрибає до вашої цілі, негайно спалахуючи на $401395s2 тіньової шкоди, а потім спалюючи її на ${$401395s3*6} тіньовогняної шкоди протягом 12 секунд." },
    { en = "When you heal an ally who is below $356134s2% health, a Spectral Feline will infuse them for an additional $s1 healing. The Feline will reconstitute itself after $356184d.", ua = "Коли ви зцілюєте союзника, чиє здоров'я нижче $356134s2%, Примарний Кіт наповнить його додатковими $s1 зцілення. Кіт відновиться через $356184d." },
    { en = "Activate the Broker defenses, protecting yourself from spell interruption and crowd control effects. The defenses withstand up to $s1 $Leffect:effects; and persist for $362699d.", ua = "Активує захист Посередників, оберігаючи вас від переривання заклять і ефектів контролю. Захист витримує до $s1 $Leffect:effects; і триває $362699d." },
    { en = "Ice Lances cast immediately following a Frostbolt deal $s1% more damage.", ua = "Крижані Списи, застосовані одразу після Крижаної Стріли, завдають на $s1% більше шкоди." },
    { en = "Each time one of your spells deals periodic damage, you have a chance to gain $71636s1 spell power for $71636d.", ua = "Щоразу, коли одне з ваших заклять завдає періодичної шкоди, ви маєте шанс отримати $71636s1 сили заклять на $71636d." },
    { en = "Wrap yourself in a cocoon, entering a dreamless sleep for $d. During that time you restore $s1 Mana per second.", ua = "Огортає вас у кокон, занурюючи в безсонне забуття на $d. Протягом цього часу ви відновлюєте $s1 мани за секунду." },
    { en = "Chance on melee and ranged critical strike to increase your attack power by $60065s1 for $60065d.", ua = "Шанс під час критичного удару в ближньому чи дальньому бою підвищити вашу силу атаки на $60065s1 на $60065d." },
    { en = "Your magical heals provide the target with a shield that absorbs damage for up to 15% of the amount healed for $d. This effect becomes less powerful at higher levels.", ua = "Ваші магічні зцілення дарують цілі щит, що поглинає шкоду в розмірі до 15% від зціленого обсягу протягом $d. Цей ефект слабшає на вищих рівнях." },
    { en = "Your spells and abilities have a chance to grant you $269885s1 Critical Strike for $269885d.", ua = "Ваші закляття та здібності мають шанс надати вам $269885s1 критичного удару на $269885d." },
    { en = "Your harmful spells have a chance to increase your spell power by $71643s1 and an additional $71643s1 every $71644t1 sec for $71644d.", ua = "Ваші шкідливі закляття мають шанс підвищити вашу силу заклять на $71643s1 і додатково на $71643s1 кожні $71644t1 с протягом $71644d." },
    { en = "Your damaging spells and abilities have the chance to grant $@spellname1245025, increasing your lowest secondary stat by $s1 for $1245025d.\n\n\n\nWhen an allied player dies, gain $s2 of your highest secondary stat for $1245025d. This effect can only occur once every 5 min.\n\n\n\nThis effect is augmented by Darkmoon Sigil: Blood.", ua = "Ваші закляття й здібності, що завдають шкоди, мають шанс надати $@spellname1245025, підвищуючи вашу найнижчу вторинну характеристику на $s1 на $1245025d.\n\n\n\nКоли союзний гравець гине, ви отримуєте $s2 до вашої найвищої вторинної характеристики на $1245025d. Цей ефект може спрацьовувати лише раз на 5 хв.\n\n\n\nЦей ефект підсилюється Сигілом Темного Місяця: Кров." },
    { en = "Pierce your target with a spear of light, dealing $s1 Holy damage.", ua = "Пронизує ціль списом світла, завдаючи $s1 свячено-священної шкоди." },
    { en = "When you deal damage you have a chance to gain $122897s1 mastery for $122897d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $122897s1 майстерності на $122897d." },
    { en = "Your melee attacks have a chance to grant $91816s1 Strength for $91816d.", ua = "Ваші атаки в ближньому бою мають шанс надати $91816s1 сили на $91816d." },
    { en = "Your spells and abilities have a chance to awaken a soul within the vessel. Each soul you collect increases your $pri by $s1 for $1265566d.", ua = "Ваші чари та здібності мають шанс пробудити душу в посудині. Кожна зібрана душа підвищує вашу $pri на $s1 протягом $1265566d." },
    { en = "When you deal damage you have a chance to gain $99721s1 Strength for $99721d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $99721s1 сили на $99721d." },
    { en = "Casting spells grants stacks of Hatred, permanently lowering this trinket's cooldown by $382419s1 second until combat ends. This effect stacks up to 180 times.", ua = "Промовляння заклять надає заряди Ненависті, що остаточно знижують час відновлення цього аксесуара на $382419s1 секунду до завершення бою. Цей ефект накопичується до 180 разів." },
    { en = "Each time you deal melee or ranged damage to an opponent, you gain $71396s1 attack power for the next $71396d, stacking up to $71396u times.", ua = "Щоразу, коли ви завдаєте супротивнику шкоди в ближньому чи дальньому бою, ви отримуєте $71396s1 сили атаки на наступні $71396d, накопичуючись до $71396u разів." },
    { en = "Summon a Bursting Lightspawn which sacrifices its health to unleash Bursts of Light, inflicting $450916s1 Holy damage split between nearby enemies every $450923t1 sec while it lives.", ua = "Прикликає Вибухове Поріддя Світла, яке жертвує своїм здоров'ям, щоб вивільнити Спалахи Світла, завдаючи $450916s1 свячено-священної шкоди, розподіленої між довколишніми ворогами кожні $450923t1 с, поки воно живе." },
    { en = "Your melee and ranged attacks have a chance to grant $122311s1 mastery for $122311d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $122311s1 майстерності на $122311d." },
    { en = "Your attacks have a chance to increase your Mastery based on the might of your current prey for $384193d.", ua = "Ваші атаки мають шанс підвищити вашу майстерність залежно від могутності вашої нинішньої здобичі на $384193d." },
    { en = "Chance on melee or ranged hit to increase your attack power by $60065s1 for $60065d.", ua = "Шанс під час влучання в ближньому чи дальньому бою підвищити вашу силу атаки на $60065s1 на $60065d." },
    { en = "Calls forth Rhea's Child to fight by your side.", ua = "Прикликає Дитя Реї, щоб воно билося поруч із вами." },
    { en = "Carefully balance the Egg's incubation. While stationary, gain $s1 $pri every $t6 sec, up to $s3 times. Diminishes while moving. While moving, gain $s2 of your highest secondary stat every $t6 sec, up to $s3 times. Diminishes while stationary. \n\n\n\nAdditional stacks above $s5 grant $s4% reduced benefit.", ua = "Ретельно балансуйте інкубацію Яйця. Стоячи нерухомо, ви отримуєте $s1 $pri кожні $t6 сек, до $s3 разів. Слабшає під час руху. Рухаючись, ви отримуєте $s2 своєї найвищої вторинної характеристики кожні $t6 сек, до $s3 разів. Слабшає, коли ви стоїте на місці.\n\n\n\nДодаткові заряди понад $s5 дають $s4% меншу користь." },
    { en = "Transfer $s2% of your damage taken to an ally within $r yards for $d, up to $s1 damage. If your target moves out of range or falls below $s3% health, the effect ends.", ua = "Переносить $s2% отриманої вами шкоди на союзника в межах $r метрів протягом $d, до $s1 шкоди. Якщо ваша ціль виходить за межі досяжності або її здоров'я падає нижче $s3%, ефект завершується." },
    { en = "Your harmful debuffs, and periodic spells and abilities have a chance to grant you $s1 $pri and suffer ${$s2*($408469d/$408469t)} Shadow damage over $408469d.", ua = "Ваші шкідливі послаблення, а також періодичні закляття й здібності мають шанс надати вам $s1 $pri і завдати вам ${$s2*($408469d/$408469t)} шкоди від сил темряви протягом $408469d." },
    { en = "Your spells and abilities have a chance to call forth a Vanquished Tendril of G'huun to serve you for $278163d.", ua = "Ваші закляття та здібності мають шанс прикликати Подоланий Пагін Ґ'хууна, що служитиме вам протягом $278163d." },
    { en = "Your ranged attacks and abilities have a high chance of granting you Eagle Training, increasing your Critical Strike by $390240s1 up to $390250u times.\n\nUpon dealing critical damage, your eagle will swoop down and deal $s1 physical damage to your current target.\n\n\n\nDealing critical damage removes all stacks of Eagle Training.", ua = "Ваші дальні атаки та здібності мають високий шанс надати вам Орлине Вишколення, підвищуючи ваш критичний удар на $390240s1 до $390250u разів.\n\nЗавдавши критичної шкоди, ваш орел стрімко спікірує й завдасть $s1 фізичної шкоди вашій нинішній цілі.\n\n\n\nЗавдання критичної шкоди знімає всі заряди Орлиного Вишколення." },
    { en = "Your healing spells have a chance to grant you $215198s1 Mastery every $215197t2 sec for $215197d.", ua = "Ваші зціляльні закляття мають шанс надавати вам $215198s1 майстерності кожні $215197t2 с протягом $215197d." },
    { en = "Your spells have a chance to inflict a Suffocating Squall on the enemy, dealing $276132s1 Nature damage every $276132t1 sec for $<minDuration>-$<maxDuration> sec. The duration depends on the topmost card in the deck.", ua = "Ваші закляття мають шанс наслати на ворога Задушливий Шквал, завдаючи $276132s1 природної шкоди кожні $276132t1 с протягом $<minDuration>-$<maxDuration> с. Тривалість залежить від верхньої карти в колоді." },
    { en = "Your spells and abilities have a chance to grant you $273798s1 primary stat for $273798d.", ua = "Ваші закляття та здібності мають шанс надати вам $273798s1 основної характеристики на $273798d." },
    { en = "Your spells and abilities have a chance to increase your primary stat by  $268609s1 for $268609d.", ua = "Ваші закляття та здібності мають шанс підвищити вашу основну характеристику на $268609s1 на $268609d." },
    { en = "Your melee and ranged attacks have a chance to grant $122900s1 haste for $122900d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $122900s1 швидкості на $122900d." },
    { en = "Your healing spells have a chance to grant $s1 mana.", ua = "Ваші зціляльні закляття мають шанс надати $s1 мани." },
    { en = "Attune with a nearby dragonflight Oathstone in the Dragon Isles.", ua = "Налаштовується на довколишній Камінь Присяги драконячих зграй на Драконових островах." },
    { en = "2% chance on successful spellcast to allow $23684s1% of your Mana regeneration to continue while casting for $23684d.", ua = "2% шансу при успішному промовлянні закляття дозволити $23684s1% вашої регенерації мани тривати під час промовляння протягом $23684d." },
    { en = "Soothing Mist also heals allies around the target for $s1% of the primary target.", ua = "Заспокійлива Мла також зцілює союзників навколо цілі на $s1% від зцілення основної цілі." },
    { en = "Your healing abilities have a chance to grant yourself 5 swirls of Disturbed Sands, with each swirl giving $1231653s1 Haste. One swirl decays every 4 sec until the Disturbed Sands dissipate.", ua = "Ваші зціляльні здібності мають шанс надати вам 5 вирів Збурених Пісків, де кожен вир дає $1231653s1 швидкості. Один вир згасає кожні 4 с, доки Збурені Піски не розвіються." },
    { en = "Your abilities have a chance to grant you a protective shell, absorbing up to $1264144s2% of incoming damage for $1264144d or until $s1 damage has been prevented. If the shell expires without breaking, gain $s2 Haste for 12 sec.", ua = "Ваші здібності мають шанс надати вам захисну оболонку, що поглинає до $1264144s2% отримуваної шкоди протягом $1264144d або доки не буде відвернено $s1 шкоди. Якщо оболонка спливає, не зруйнувавшись, ви отримуєте $s2 швидкості на 12 с." },
    { en = "Increases armor by $s2, all resistances by $s3 for $d.  Also grants immunity to Fear if you are level $ctrmax2067 or below.", ua = "Підвищує броню на $s2 та всі опірності на $s3 протягом $d. Також надає несприйнятливість до Страху, якщо ви $ctrmax2067 рівня або нижче." },
    { en = "Your melee and ranged attacks have a chance to grant $122695s1 critical strike for $122695d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс надати $122695s1 критичного удару на $122695d." },
    { en = "A voice whispers to you, periodically compelling you to follow its instructions. If you comply, you will be rewarded with $s1 of your highest secondary stat for $357185d.", ua = "Голос шепоче вам, час від часу спонукаючи дотримуватися його настанов. Якщо ви скоритеся, вас винагородять $s1 вашої найвищої вторинної характеристики на $357185d." },
    { en = "Increases the effect that healing and mana potions have on the wearer by 40%.  This effect does not stack.", ua = "Підвищує дію зціляльних і манових зіль на власника на 40%. Цей ефект не накопичується." },
    { en = "Your critical hits have a chance to increase your $?a137005|a137026|a137047[Strength]?a137009|a137014|a137022|a137034|a137038|a212611[Agility][Strength or Agility] by $s1 for $356687d. If you are below $s2% health when this occurs, you also heal for ${$s3*4} over $356689d.", ua = "Ваші критичні удари мають шанс підвищити вашу $?a137005|a137026|a137047[силу]?a137009|a137014|a137022|a137034|a137038|a212611[спритність][силу або спритність] на $s1 на $356687d. Якщо в цю мить ваше здоров'я нижче $s2%, ви також відновлюєте ${$s3*4} здоров'я протягом $356689d." },
    { en = "Your Steady Shot has a $h% chance to grant you $40487s1 attack power for $40487d.", ua = "Ваш Влучний Постріл має $h% шансу надати вам $40487s1 сили атаки на $40487d." },
    { en = "Your attacks have a chance to grant $176903s1 Mastery for $176903d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176903s1 майстерності на $176903d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $75480s1 dodge for $75480d.  Cannot occur more than once every 45 sec.", ua = "Удари ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $75480s1 ухилення на $75480d. Не може спрацьовувати частіше, ніж раз на 45 сек." },
    { en = "Chance to strike your melee target with lightning for $23687s1 Nature damage.", ua = "Шанс уразити ціль ближнього бою блискавкою, завдаючи $23687s1 шкоди від Природи." },
    { en = "Your harmful spells or abilities have a chance for the battery to drain the life force of the enemy inflicting $1231099s1 Arcane damage every $1231104t1 sec over $1231104d.", ua = "Ваші шкідливі закляття чи здібності мають шанс змусити батарею висмоктувати життєву силу ворога, завдаючи $1231099s1 шкоди від Тайнощів кожні $1231104t1 сек протягом $1231104d." },
    { en = "Your spells and abilities have a chance to grant you $268567s1 Haste and $268567m2% Swim Speed for $268567d.", ua = "Ваші закляття та здібності мають шанс надати вам $268567s1 швидкості й $268567m2% швидкості плавання на $268567d." },
    { en = "Your attacks have a chance to grant $176982s1 Critical Strike for $176982d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176982s1 критичного удару на $176982d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increases maximum health by $s2 for $d. Shares cooldown with other Battlemaster's trinkets.", ua = "Підвищує максимальне здоров'я на $s2 протягом $d. Має спільну перезарядку з іншими брязкальцями Бойового Майстра." },
    { en = "Your healing and damaging spells have a chance to grant $120176s1 mastery for $120176d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс надати вам $120176s1 майстерності на $120176d." },
    { en = "Empty out the Dragon Games kickballs onto the field. Running into them kicks them at your enemy target, inflicting ${$<rolemult>*$383950s1} Physical damage.", ua = "Висипає м'ячі Драконячих Ігор на поле. Наштовхнувшись на них, ви відбиваєте їх у ворожу ціль, завдаючи ${$<rolemult>*$383950s1} фізичної шкоди." },
    { en = "Slowly build up stacks of titan energy. The amount of stacks gained per second can vary but when fully charged at $s3 stacks the Buzzing Orb Core will increase a random secondary stat by $s0, as well as your movement speed by $s1 for $405202d.", ua = "Поволі накопичує заряди титанічної енергії. Кількість зарядів, що здобуваються за секунду, може різнитися, але за повного заряду в $s3 зарядів Ядро Дзижчливої Сфери підвищить випадкову вторинну характеристику на $s0, а також вашу швидкість пересування на $s1 протягом $405202d." },
    { en = "Grants $s1 haste and reduces the mana cost of your healing spells by $s2% for $d.", ua = "Надає $s1 швидкості та знижує витрати мани ваших зцілювальних заклять на $s2% протягом $d." },
    { en = "Pheromones in the square grant you $s1 Mastery Rating for $d.", ua = "Феромони у квадраті надають вам $s1 рейтингу майстерності на $d." },
    { en = "Spells and abilities have a chance to grant $s1 Intellect and shapeshift you.", ua = "Закляття та здібності мають шанс надати $s1 інтелекту й перевтілити вас." },
    { en = "Your damaging spells and abilities have a chance to tear open a rift of the Void within your target, erupting for ${$<rolemult>*$s1} Shadow damage split among nearby enemies.", ua = "Ваші шкідливі закляття та здібності мають шанс розверзнути в цілі розлом Порожнечі, що вибухає, завдаючи ${$<rolemult>*$s1} шкоди від Темряви, поділеної між ближніми ворогами." },
    { en = "Taking damage has a high chance to cause you to devour the essence of nearby enemies, dealing $s1 Shadow damage split between them and healing you for $s2% of the damage dealt.\n\n\n\nFatal damage not exceeding $s3 instead restores you to $s5% health and reconstitutes you as unstable void for $1236692d. Exceed $s4% health to stabilize and avoid death. This effect may occur once per $1236691d. The Nucleus is unable to deal damage while recharging.", ua = "Отримуючи шкоду, ви маєте високий шанс поглинути сутність ближніх ворогів, завдаючи $s1 шкоди від Темряви, поділеної між ними, і зцілюючи вас на $s2% завданої шкоди.\n\n\n\nСмертельна шкода, що не перевищує $s3, натомість відновлює ваше здоров'я до $s5% і перетворює вас на нестабільну порожнечу протягом $1236692d. Перевищіть $s4% здоров'я, щоб стабілізуватися й уникнути смерті. Цей ефект може спрацьовувати раз на $1236691d. Ядро не може завдавати шкоди, поки перезаряджається." },
    { en = "Your harmful abilities have a chance to cause you to summon The Thumper to fight by your side for $175737d.", ua = "Ваші шкідливі здібності мають шанс закликати Гупача, що б'ється поруч із вами протягом $175737d." },
    { en = "Your attacks have a chance to grant you $146250s1 Strength for $146250d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс надати вам $146250s1 сили на $146250d. ($h% шансу, ${$proccooldown} сек перезарядки)" },
    { en = "When you heal you have a chance to gain $107982s1 haste for $107982d.", ua = "Коли ви зцілюєте, ви маєте шанс отримати $107982s1 швидкості на $107982d." },
    { en = "Melee attacks against you have a chance to make the heart pulse, dealing $413423s1 Nature damage split between nearby enemies.", ua = "Удари ближнього бою по вас мають шанс змусити серце пульсувати, завдаючи $413423s1 шкоди від Природи, поділеної між ближніми ворогами." },
    { en = "Incinerate increases the critical strike chance of your spells against that target by $185229s1% for $185229d, stacking up to $185229u times.", ua = "«Спопеління» підвищує шанс критичного удару ваших заклять проти цієї цілі на $185229s1% протягом $185229d, накопичуючись до $185229u разів." },
    { en = "You gain an Electrical Charge each time you cause a non-periodic damaging spell critical strike.  When you reach $s1 Electrical Charges, they will release, firing a Lightning Bolt for $37661s1 damage.  Electrical Charge cannot be gained more often than once every 2.5 sec.", ua = "Ви отримуєте Електричний Заряд щоразу, коли завдаєте критичного удару неперіодичним шкідливим закляттям. Коли ви накопичите $s1 Електричних Зарядів, вони вивільняться, випустивши Блискавку, що завдає $37661s1 шкоди. Електричний Заряд не може здобуватися частіше, ніж раз на 2,5 сек." },
    { en = "Your damaging abilities have a chance to create a Ravaging Storm at your target's location, inflicting ${$257286s1*$256820d} Nature damage split among all enemies within $257286A1 yds over $256820d.\n\n\n\n|cFFFFFFFFGolganneth's Thunderous Wrath|r\n\nWhen empowered by the Pantheon, your autoattacks cause an explosion of lightning dealing ${$<mult>*$<weaponSpeed>*$257430s1} Nature damage to all enemies within $257430A2 yds of the target. Lasts $256833d.", ua = "Ваші шкідливі здібності мають шанс створити Спустошливу Бурю на місці вашої цілі, завдаючи ${$257286s1*$256820d} шкоди від Природи, поділеної між усіма ворогами в межах $257286A1 м, протягом $256820d.\n\n\n\n|cFFFFFFFFГромовий Гнів Гольганнета|r\n\nКоли вас наснажує Пантеон, ваші автоатаки спричиняють вибух блискавки, завдаючи ${$<mult>*$<weaponSpeed>*$257430s1} шкоди від Природи всім ворогам у межах $257430A2 м від цілі. Триває $256833d." },
    { en = "Your next $U damaging abilities inflict Shattered Psyche, dealing $344664s1 Shadow damage and increasing the target's damage taken from Shattered Psyche by $s1% for $344663d, stacking up to $344663U times.", ua = "Ваші наступні $U здібності, що завдають шкоди, накладають Розбиту Психіку, завдаючи $344664s1 шкоди від сил темряви й підвищуючи шкоду, якої ціль зазнає від Розбитої Психіки, на $s1% на $344663d, що накопичується до $344663U разів." },
    { en = "Systematically consume a small dosage of the serum when entering combat heightening your senses to their limit.\n\nIn this state parrying and dodging have a chance to cause you to reposte with a Counter dealing Y Physical damage to your assailant.", ua = "Систематично споживає невелику дозу сироватки при вступі в бій, загострюючи ваші чуття до краю.\n\nУ цьому стані парирування та ухилення мають шанс змусити вас завдати удару у відповідь Контратакою, що завдає Y фізичної шкоди вашому нападнику." },
    { en = "Your spells and abilities have a chance to grant you $214128s1 Haste and $214128s2 Speed for $214128d.", ua = "Ваші закляття та здібності мають шанс надати вам $214128s1 швидкості й $214128s2 жвавості на $214128d." },
    { en = "Your harmful abilities have a chance to cause you to summon a Sha'tari Golem to fight by your side for $175741d.", ua = "Ваші шкідливі здібності мають шанс закликати Голема Ша'тарі, що б'ється поруч із вами протягом $175741d." },
    { en = "Your healing spells have a chance to grant you $102744s1 Haste for $102744d.", ua = "Ваші зцілювальні закляття мають шанс надати вам $102744s1 швидкості на $102744d." },
    { en = "Deploy a power crystal which beams arcane energy into you, inflicting $o1 Arcane damage over $d and granting you $s2 Critical Strike for the duration.", ua = "Розгортає кристал сили, що променить у вас таємничу енергію, завдаючи $o1 шкоди від Тайнощів протягом $d і надаючи вам $s2 критичного удару на весь час дії." },
    { en = "Deals $s1 Fire damage to all targets in a cone in front of the caster.", ua = "Завдає $s1 шкоди від Вогню всім цілям у конусі перед закляттярем." },
    { en = "When you deal damage you have a chance to gain $122692s1 mastery for $122692d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $122692s1 майстерності на $122692d." },
    { en = "Your ranged attacks and spells have a chance to create a Flame Wreath beneath your target. After $230259d, or if they move out of the ring, it explodes for ${$s1*(1+$@versadmg)} Fire damage to all enemies within $230261A1 yds.", ua = "Ваші дальнобійні атаки та закляття мають шанс створити Вінець Полум'я під вашою ціллю. За $230259d, або якщо ціль вийде з кільця, він вибухає, завдаючи ${$s1*(1+$@versadmg)} шкоди від Вогню всім ворогам у межах $230261A1 м." },
    { en = "You have a $s1% chance to perform a free Rising Sun Kick after each Fists of Fury, Blackout Kick, or normal Rising Sun Kick.", ua = "Ви маєте $s1% шансу виконати безкоштовний «Удар Висхідного Сонця» після кожного «Кулаків Люті», «Затемнювального Удару» або звичайного «Удару Висхідного Сонця»." },
    { en = "Increases your Speed by $213888s1 for $213888d when you kill a target that gives experience or honor.", ua = "Підвищує вашу жвавість на $213888s1 протягом $213888d, коли ви вбиваєте ціль, що дає досвід або честь." },
    { en = "Casting a major class cooldown imbues you with the ferocity of vrykul spirits, granting $s1 Critical Strike for $472360d.\n\n\n\nThis effect's duration is increased by up to ${$472360d*5} sec based on when you were last imbued.", ua = "Застосування великої класової здібності з перезарядкою сповнює вас лютістю духів врайкулів, надаючи $s1 критичного удару на $472360d.\n\n\n\nТривалість цього ефекту збільшується до ${$472360d*5} сек залежно від того, коли вас наснажили востаннє." },
    { en = "Your melee attacks and abilities have a high chance to attach a Volatile Satchel onto your target. Upon reaching ${$u1+1} stacks, or when removed, the Volatile Satchel detonates and deals $351679s1 Fire damage.", ua = "Ваші атаки та здібності ближнього бою з високою ймовірністю чіпляють Нестійку торбинку на вашу ціль. Досягнувши ${$u1+1} стаків або при знятті, Нестійка торбинка вибухає та завдає $351679s1 шкоди Вогнем." },
    { en = "Increases your melee and ranged damage by ${$24662m1*20} for $d. Every time you hit a target, this bonus is reduced by $24662m1.", ua = "Підвищує вашу шкоду в ближньому бою та на відстані на ${$24662m1*20} протягом $d. Щоразу, коли ви вражаєте ціль, цей бонус знижується на $24662m1." },
    { en = "Open the cage, creating a pool of anima at the target location for $d. The pool grants $343387s1 Critical Strike to up to $343386s2 allies standing within it.", ua = "Відчиняє клітку, створюючи калюжу аніми в місці цілі на $d. Калюжа надає $343387s1 критичного удару щонайбільше $343386s2 союзникам, що стоять у ній." },
    { en = "Your melee attacks have a chance to grant $117645s1 parry for $117645d.", ua = "Ваші удари ближнього бою мають шанс надати $117645s1 парирування на $117645d." },
    { en = "Your melee auto attacks increase your Critical Strike by $230152s1 for $230152d, stacking up to $230152u times. This effect is reset if you auto attack a different target.", ua = "Ваші автоатаки в ближньому бою підвищують ваш критичний удар на $230152s1 на $230152d, накопичуючись до $230152u разів. Цей ефект скидається, якщо ви автоатакуєте іншу ціль." },
    { en = "Gain $s1 mana each sec. for $d.  Channeled.", ua = "Відновлює $s1 мани щосекунди протягом $d. Підтримується." },
    { en = "Invoke the swarm, losing the ability to cast or attack but transforming into a swarm of hungering locusts, gaining $s3 Speed and $s4 Leech, and dealing ${$364155s1*3} Shadow damage split between all nearby enemies over $d.\n\n\n\nDamage is increased for each enemy struck, up to $s6 enemies.", ua = "Прикликає рій: ви втрачаєте здатність застосовувати закляття чи атакувати, але перетворюєтесь на рій голодної сарани, отримуючи $s3 швидкості та $s4 висмоктування й завдаючи ${$364155s1*3} шкоди Тіні, розподіленої між усіма ворогами поблизу, протягом $d.\n\n\n\nШкода зростає за кожного враженого ворога, до $s6 ворогів." },
    { en = "Absorbs 20% of incoming damage, up to $s1.  After the effect ends, you take 8% of the damage absorbed every $96993t sec for $96993d.  Lasts $d.", ua = "Поглинає 20% вхідної шкоди, до $s1. Коли ефект завершується, ви зазнаєте 8% поглинутої шкоди кожні $96993t сек. протягом $96993d. Триває $d." },
    { en = "Your harmful abilities have a chance to cause you to summon a wolf guardian to fight by your side for $163725d.", ua = "Ваші ворожі здібності мають шанс прикликати вовка-охоронця, що битиметься поруч із вами протягом $163725d." },
    { en = "Your damaging critical strikes reduce all damage the target deals by ${-$214229s1} for $214229d. Stacks up to $214229u times.", ua = "Ваші критичні удари, що завдають шкоди, зменшують усю шкоду, яку завдає ціль, на ${-$214229s1} протягом $214229d. Накопичується до $214229u разів." },
    { en = "You are a volunteer of the Vanguard of the Light.", ua = "Ви доброволець Авангарду Світла." },
    { en = "Your spells grant $65006s1 Intellect for $65006d, stacking up to $65006u times.", ua = "Ваші закляття дають $65006s1 інтелекту протягом $65006d, накопичуючись до $65006u разів." },
    { en = "Your melee and ranged attacks have a chance to grant $118870s1 critical strike for $118870d.", ua = "Ваші атаки в ближньому та дальньому бою мають шанс дати $118870s1 критичного удару протягом $118870d." },
    { en = "Your melee attacks have a chance to infuse you with nightmare winds, granting $214342s1 Haste every $215024t2 sec for $215024d.", ua = "Ваші атаки в ближньому бою мають шанс наповнити вас вітрами жахіть, даючи $214342s1 швидкості кожні $215024t2 сек. протягом $215024d." },
    { en = "Your attacks have a chance to grant $177040s1 Critical Strike for $177040d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс дати $177040s1 критичного удару протягом $177040d. (Приблизно ${$procrppm}.2 спрацювань на хвилину)" },
    { en = "Pump the fang's noxious venom gland, spraying poisonous mist forward in a cone. The mist deals $267410s1 Nature damage every $267410t1 sec over $d, stacking up to $267410u times.", ua = "Стискає отруйну залозу ікла, розпорошуючи перед собою конус отруйного туману. Туман завдає $267410s1 шкоди Природи кожні $267410t1 сек. протягом $d, накопичуючись до $267410u разів." },
    { en = "Become Mudborne, absorbing $1221145s3 damage and pulsing ${$1221145s1*$1221146d/$1221146t} Nature damage split between nearby enemies over $d.\n\n\n\nPeriodic damage you take coalesces into pungent mud to feed the ritual, reducing this cooldown by $?${$1221145s2%10}=0[${$1221145s2/10}][${$1221145s2/10}.1] sec.", ua = "Перетворює вас на Породження Багна, поглинаючи $1221145s3 шкоди й пульсуючи ${$1221145s1*$1221146d/$1221146t} шкодою Природою, що розподіляється між ворогами поблизу, протягом $d.\n\n\n\nПеріодична шкода, яку ви отримуєте, зливається у смердючу багнюку, живлячи ритуал і скорочуючи цей час відновлення на $?${$1221145s2%10}=0[${$1221145s2/10}][${$1221145s2/10}.1] с." },
    { en = "Void energy pools at your feet for $250765d, dealing ${$s1*10} Shadow damage to targets standing within the area. You are healed for ${$e1*100}% of the damage dealt.", ua = "Енергія Порожнечі збирається калюжею біля ваших ніг на $250765d, завдаючи ${$s1*10} шкоди Тінню цілям, що стоять у цій ділянці. Ви зцілюєтеся на ${$e1*100}% завданої шкоди." },
    { en = "Manifest a Quasar which orbits your target, blasting it with $s1 Cosmic damage over $369287d.\n\n\n\nAfter $369287d, the Quasar stabilizes, creating an Event Horizon for $368645d which grants you $s2 Haste while within its perimeter.", ua = "Проявляє Квазар, що обертається навколо вашої цілі, вражаючи її $s1 космічної шкоди протягом $369287d.\n\n\n\nЧерез $369287d Квазар стабілізується, створюючи Горизонт Подій на $368645d, що надає вам $s2 швидкості, поки ви перебуваєте в його межах." },
    { en = "When you deal damage you have a chance to gain $92216s1 Strength for $92216d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $92216s1 сили протягом $92216d." },
    { en = "Inhale the spores, granting ${$s1*$u} Haste, which decays over $d.", ua = "Вдихає спори, даючи ${$s1*$u} швидкості, що згасає протягом $d." },
    { en = "Your harmful spells grant $107970s1 Intellect for the next $107970d, stacking up to $107970u times.", ua = "Ваші шкідливі закляття дають $107970s1 інтелекту на наступні $107970d, накопичуючись до $107970u разів." },
    { en = "Throw one of the many weapons in the Monster Slayer's Kit at the target.", ua = "Кидає в ціль одну з багатьох зброй із Набору вбивці монстрів." },
    { en = "Reduces your threat to enemy targets within $a1 yards, making them less likely to attack you.", ua = "Знижує вашу загрозу для ворожих цілей у радіусі $a1 м, через що вони менш схильні атакувати вас." },
    { en = "Your attacks have a chance to grant you $146245s1 Strength for $146245d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Ваші атаки мають шанс дати вам $146245s1 сили протягом $146245d. ($h% шанс, ${$proccooldown} сек. перезарядки)" },
    { en = "Your harmful spells and abilities have a chance to grant you $s1 haste for $392216d.", ua = "Ваші шкідливі закляття та здібності мають шанс дати вам $s1 швидкості протягом $392216d." },
    { en = "Your healing and damaging spells have a chance to grant $120171s1 critical strike for $120171d.", ua = "Ваші зцілювальні та шкідливі закляття мають шанс дати $120171s1 критичного удару протягом $120171d." },
    { en = "Your spells and abilities have a chance to usher in primal magics, dealing damage to enemies and buffing allies.", ua = "Ваші закляття та здібності мають шанс прикликати первісну магію, що завдає шкоди ворогам і підсилює союзників." },
    { en = "Your spells have a chance to grant $90887s1 Haste for $90887d.", ua = "Ваші закляття мають шанс дати $90887s1 швидкості протягом $90887d." },
    { en = "Your attacks have a chance to activate the diffusion implement for 20 sec, causing your attacks to have a very high chance of dealing an explosion of $s1 Arcane damage centered on your target.", ua = "Ваші атаки мають шанс активувати дифузійний пристрій на 20 сек., через що ваші атаки отримують дуже високий шанс завдати вибуху на $s1 шкоди Тайнощів із центром на вашій цілі." },
    { en = "While you are above $s1% health you gain $242642s3 Strength or Agility per second, based on your specialization, stacking up to $242642u times. If you fall below $s2% health, this effect is lost.", ua = "Поки ваше здоров'я вище $s1%, ви отримуєте $242642s3 сили або спритності щосекунди залежно від вашої спеціалізації, накопичуючись до $242642u разів. Якщо ваше здоров'я падає нижче $s2%, цей ефект втрачається." },
    { en = "Increases the damage dealt by Instant Poison by $s1 and the periodic damage dealt by Deadly Poison by $s2 for $d.", ua = "Підвищує шкоду від Миттєвої Отрути на $s1 і періодичну шкоду від Смертельної Отрути на $s2 протягом $d." },
    { en = "For the next $d, your direct heals grant Fecundity to your target, increasing the healing received by the target by up to $38333s1.  Fecundity lasts $38333d and stacks up to 5 times.", ua = "Протягом наступних $d ваші прямі зцілення дають цілі Плідність, підвищуючи зцілення, яке отримує ціль, до $38333s1. Плідність триває $38333d і накопичується до 5 разів." },
    { en = "Your spells and abilities have a chance to grant you $268519s1 primary stat for $268519d.", ua = "Ваші закляття та здібності мають шанс дати вам $268519s1 основної характеристики протягом $268519d." },
    { en = "Your attacks have a chance to increase your Versatility by $202866s1 for $202866d.", ua = "Ваші атаки мають шанс підвищити вашу універсальність на $202866s1 протягом $202866d." },
    { en = "Your healing effects have a chance to increase your Haste by $253269s1 for $253269d, stacking up to $253269u times. This is more likely to occur when you heal allies who are at low health.", ua = "Ваші ефекти зцілення мають шанс підвищити вашу швидкість на $253269s1 протягом $253269d, накопичуючись до $253269u разів. Це трапляється частіше, коли ви зцілюєте союзників із низьким здоров'ям." },
    { en = "Restores Mana, Rage, Energy, Focus, or Runic Power when you kill a target that grants honor or experience.", ua = "Відновлює ману, лють, енергію, зосередження або руническу силу, коли ви вбиваєте ціль, що дає честь чи досвід." },
    { en = "Your attacks have a chance to increase your critical strike damage by ${$228142s2}.1% for $228142d.", ua = "Ваші атаки мають шанс підвищити шкоду ваших критичних ударів на ${$228142s2}.1% протягом $228142d." },
    { en = "Your melee attacks have a chance to trigger a Landslide, dealing $214397s1 Physical damage to all enemies directly in front of you.", ua = "Ваші атаки в ближньому бою мають шанс спричинити Зсув землі, завдаючи $214397s1 фізичної шкоди всім ворогам безпосередньо перед вами." },
    { en = "When you deal damage you have a chance to gain $117648s1 mastery for $117648d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $117648s1 майстерності протягом $117648d." },
    { en = "A veil of splashing water increases your Dodge by $s1 for $d.", ua = "Завіса з бризок води підвищує ваше ухилення на $s1 протягом $d." },
    { en = "Your spells and abilities have a chance to grant you $268547s1 Primary stat for $268547d.", ua = "Ваші закляття та здібності мають шанс дати вам $268547s1 основної характеристики на $268547d." },
    { en = "Your healing spells have a chance to return $244120s1 mana.", ua = "Ваші зцілювальні закляття мають шанс повернути $244120s1 мани." },
    { en = "When you drop below $s1% health, you gain a charge of Ironskin Brew. Ironskin Brew also increases damage dealt by $s2%.", ua = "Коли ваше здоров'я падає нижче $s1%, ви отримуєте заряд Залізошкірого Вару. Залізошкірий Вар також підвищує завдану шкоду на $s2%." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $71639s1 armor for $71639d.  Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, дають вам $71639s1 броні на $71639d. Не може спрацьовувати частіше, ніж раз на 30 сек." },
    { en = "Taking damage has a chance to cause your next melee attack to deal an additional $407907s1 Physical damage.", ua = "Отримання шкоди має шанс зробити так, що ваша наступна атака ближнього бою завдасть додатково $407907s1 фізичної шкоди." },
    { en = "Uncork the vial to summon a bolt of lightning on the target, inflicting $s1 Nature damage split evenly among all enemies within $268525A1 yards.", ua = "Відкоркуйте флакон, щоб закликати блискавку на ціль, завдаючи $s1 шкоди Природою, рівномірно розподіленої між усіма ворогами в радіусі $268525A1 метрів." },
    { en = "Send an Orb of Destruction to your target's location at least 10 yds away, dealing up to $229700s1 Shadow damage to all enemies within $229700A1 yards after 4 sec. Targets closer to the impact take more damage.", ua = "Надсилає Сферу Руйнування на місце вашої цілі щонайменше за 10 метрів, завдаючи до $229700s1 шкоди Тінню всім ворогам у радіусі $229700A1 метрів за 4 сек. Цілі, ближчі до точки удару, отримують більше шкоди." },
    { en = "Your spells and abilities have a chance to grant you a shield, absorbing $268532s1 damage for $268532d.", ua = "Ваші закляття та здібності мають шанс дати вам щит, що поглинає $268532s1 шкоди на $268532d." },
    { en = "Taking damage has a chance to increase your Armor by $242209s1 and cause you to reflect $242650s1 damage as Fire when you are attacked. Lasts $242209d.", ua = "Отримання шкоди має шанс підвищити вашу броню на $242209s1 і змусити вас відбивати $242650s1 шкоди як Вогонь, коли на вас нападають. Триває $242209d." },
    { en = "Your attacks have a chance to grant you $278381s1 Agility for $278381d.", ua = "Ваші атаки мають шанс дати вам $278381s1 спритності на $278381d." },
    { en = "$h% chance to increase your attack power by $41261s1 for $41261d when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "$h% шанс підвищити вашу силу атаки на $41261s1 на $41261d, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше, ніж раз на 10 секунд." },
    { en = "When you deal damage you have a chance to gain $99717s1 Agility for $99717d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $99717s1 спритності на $99717d." },
    { en = "Allows control of a mechanical target for a short time.  It may not always work and may just root the machine or make it very very angry.  Gnomish engineering at its finest.", ua = "Дозволяє на короткий час контролювати механічну ціль. Це не завжди спрацьовує і може просто знерухомити машину або зробити її дуже-дуже злою. Гномська інженерія у всій красі." },
    { en = "Increases the cooldown recovery rate of some of your major abilities by $s1%.  Effective for Agility-based damage roles only. Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Підвищує швидкість відновлення деяких ваших головних здібностей на $s1%. Ефективно лише для бойових ролей на основі Спритності. Знижена ефективність на $ctrmin2066 рівні та вище." },
    { en = "Activate the defenses, absorbing $s2% of all Magic damage taken, up to ${$s1*(1+$@versadmg)}, persisting for $d. Cosmic damage is fully absorbed.", ua = "Активує захист, поглинаючи $s2% усієї отриманої магічної шкоди, до ${$s1*(1+$@versadmg)}, триває $d. Космічна шкода поглинається повністю." },
    { en = "When you deal damage you have a chance to gain $99746s1 Strength for $99746d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $99746s1 сили на $99746d." },
    { en = "Your spells have a chance to stir the Primal blood, granting $429246s1 Critical Strike for $429246d.", ua = "Ваші закляття мають шанс сколихнути Первісну кров, даючи $429246s1 критичного удару на $429246d." },
    { en = "Your harmful spells and abilities have a chance to deal up an additional ${$s1*1.15} physical damage to your current target. Damage is increased based on your targets missing health.", ua = "Ваші шкідливі закляття та здібності мають шанс завдати додатково до ${$s1*1.15} фізичної шкоди вашій поточній цілі. Шкода зростає залежно від відсутнього здоров'я цілі." },
    { en = "When struck in combat inflicts $s1 Fire damage to the attacker.", ua = "У разі удару в бою завдає $s1 шкоди Вогнем нападнику." },
    { en = "Your healing spells have a chance to grant $126467s1 mana.", ua = "Ваші зцілювальні закляття мають шанс дати $126467s1 мани." },
    { en = "Mangle has a 40% chance to grant $40452s1 Strength for $40452d, Starfire has a 25% chance to grant $40445s1 spell power for $40445d, and Rejuvenation has a 25% chance to grant  $40446s1 spell power for $40446d.", ua = "Калічення має 40% шанс дати $40452s1 сили на $40452d, Зоряний Вогонь має 25% шанс дати $40445s1 сили заклять на $40445d, а Омолодження має 25% шанс дати $40446s1 сили заклять на $40446d." },
    { en = "Hand of Gul'dan has a $s1% chance to also summon $s2 Wild Imps.", ua = "Рука Ґул'дана має $s1% шанс також закликати $s2 Диких Бісенят." },
    { en = "Instantly increases your energy by 60.", ua = "Миттєво підвищує вашу енергію на 60." },
    { en = "Deal $s0 Shadowflame damage to you and nearby enemies every 3 sec while in combat.", ua = "Завдає $s0 шкоди Тіньовим Полум'ям вам і ворогам поблизу кожні 3 сек у бою." },
    { en = "Each healing spell you cast has a $h% chance to make your next heal cast within $37706d cost $37706s1 less mana.", ua = "Кожне зцілювальне закляття, яке ви накладаєте, має $h% шанс зробити так, що ваше наступне зцілення, накладене протягом $37706d, коштуватиме на $37706s1 менше мани." },
    { en = "Your spells have a chance to send you into a frenzy, granting you $s1 Critical Strike for $474285d. While frenzied, each spell cast grants an additional $s1 Critical Strike but does not refresh the duration. This effect may only occur every $s2 sec.", ua = "Ваші закляття мають шанс увігнати вас у шал, даючи вам $s1 критичного удару на $474285d. Під час шалу кожне накладене закляття дає додатково $s1 критичного удару, але не оновлює тривалість. Цей ефект може спрацьовувати лише раз на $s2 сек." },
    { en = "Unleash a burst of hungering Gloom, dealing $1260627s1 Shadow damage split between nearby enemies and absorbing up to $1263141s2% of incoming damage until an equal amount of damage has been prevented.\n\n\n\n$@spelldesc1240903", ua = "Вивільняє спалах ненаситної Імли, завдаючи $1260627s1 шкоди Тіні, розподіленої між найближчими ворогами, і поглинаючи до $1263141s2% вхідної шкоди, доки не буде відвернено таку саму її кількість.\n\n\n\n$@spelldesc1240903" },
    { en = "You gain a Mote of Flame each time you cause a non-periodic spell critical strike.  When you reach $s1 Motes, they will release, firing a Pillar of Flame for $67714s1 damage.  Mote of Flame cannot be gained more often than once every 2 sec.", ua = "Ви отримуєте Іскру Полум'я щоразу, коли завдаєте неперіодичного критичного удару заклять. Коли ви накопичуєте $s1 Іскор, вони вивільняються, випускаючи Стовп Полум'я, що завдає $67714s1 шкоди. Іскру Полум'я не можна отримувати частіше, ніж раз на 2 сек." },
    { en = "Your spells and abilities have a chance to rip apart the enemy's psyche, dealing $313663s1 Shadow damage to them and causing them to suffer $s2 additional Shadow damage from your spells and abilities for $313627d.", ua = "Ваші закляття та здібності мають шанс розірвати психіку ворога, завдаючи йому $313663s1 шкоди Тінню і змушуючи його отримувати на $s2 більше шкоди Тінню від ваших заклять і здібностей протягом $313627d." },
    { en = "Channel to vent flames for $d, dealing ${$1219410s1*($d/$t+1)} Fire damage split between all nearby enemies.\n\n\n\nMechanical enemies become Superheated, taking $1219410s2  additional Fire damage when struck by your next harmful ability.", ua = "Каналізуйте, щоб вивергати полум'я протягом $d, завдаючи ${$1219410s1*($d/$t+1)} шкоди Вогнем, розподіленої між усіма ворогами поблизу.\n\n\n\nМеханічні вороги стають Розпеченими, отримуючи $1219410s2 додаткової шкоди Вогнем, коли їх вражає ваша наступна шкідлива здібність." },
    { en = "Your melee attacks have a chance to grant you a blessing of one of the Allies of Nature for $222519d.", ua = "Ваші атаки ближнього бою мають шанс дати вам благословення одного з Союзників Природи на $222519d." },
    { en = "Your spells and abilities have a chance to grant you $268616s1 Mastery for $268616d.", ua = "Ваші закляття та здібності мають шанс дати вам $268616s1 майстерності на $268616d." },
    { en = "Your spells and abilities have a chance to grant $s1 Critical Strike per Alexstraszite you have equipped. Upon reaching $M2 stacks, all stacks are consumed and you gain $s3 secondary stats, split evenly for $376643d.", ua = "Ваші закляття та здібності мають шанс дати $s1 критичного удару за кожен екіпірований Алекстразит. Досягнувши $M2 стаків, усі стаки витрачаються, і ви отримуєте $s3 вторинних характеристик, рівномірно розподілених, на $376643d." },
    { en = "Falling below $s3% health surrounds you with a protective vortex of junk, reducing damage taken by $466673s2% for $466673d or until $s1 damage is prevented. This effect may only occur every $472170d.\n\n\n\nAfter $472171d without activating while in combat, the Scrapfield overloads to energize you with $s2 Haste for $472167d.\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "Падіння нижче $s3% здоров'я оточує вас захисним вихором мотлоху, зменшуючи отриману шкоду на $466673s2% протягом $466673d або доки не буде відвернено $s1 шкоди. Цей ефект може спрацьовувати лише раз на $472170d.\n\n\n\nПісля $472171d без активації в бою Брухтополе перевантажується й наповнює вас енергією, надаючи $s2 Швидкості протягом $472167d.\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Дійсне лише для спеціалізацій танка.|r]" },
    { en = "Launch a Geargrinder trike to its final blaze of glory, exploding upon impacting the first enemy in its path to deal ${$<rolemult>*$471058s1} Fire damage split between all nearby enemies.", ua = "Запустіть трицикл Шестеродробильника до його останньої вогняної слави, що вибухає, врізаючись у першого ворога на своєму шляху, і завдає ${$<rolemult>*$471058s1} шкоди Вогнем, розподіленої між усіма ворогами поблизу." },
    { en = "Bind with the blaze for $d, giving your attacks a high chance to increase your Strength by $s1, stacking up to $u times. When your binding is complete, emit a burnout wave, dealing up to $s2 Fire damage split between all nearby enemies, based on the strength of your binding.", ua = "Зв'яжіться з полум'ям на $d, даючи вашим атакам високий шанс підвищити вашу силу на $s1, стаком до $u разів. Коли зв'язок завершується, ви випромінюєте хвилю згоряння, що завдає до $s2 шкоди Вогнем, розподіленої між усіма ворогами поблизу, залежно від сили вашого зв'язку." },
    { en = "Your abilities have a low chance to create a Void Tear nearby for $303104d. Moving to a Void Tear opens a portal for $302702d. Standing in a portal grants you $s1 Intellect.", ua = "Ваші здібності мають низький шанс створити поблизу Розрив Порожнечі на $303104d. Переміщення до Розриву Порожнечі відкриває портал на $302702d. Стоячи в порталі, ви отримуєте $s1 інтелекту." },
    { en = "Command an invocation of Yu'lon to strike your target, dealing $288282s1 Nature damage split among them and all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Накажіть прикликаному Ю'лону вдарити вашу ціль, завдаючи $288282s1 шкоди Природою, розподіленої між нею та всіма ворогами поблизу. Завдає більше шкоди, вражаючи кілька цілей." },
    { en = "Reverse the magnet's polarity to violently recycle buried garbage, dealing ${$471211s1*$<rolemult>} Plague damage to your target per charge. Lingering virulence deals $471211s3% of the damage dealt to $471211s2 nearby enemies over $1220481d.", ua = "Змінює полярність магніту на протилежну, щоб бурхливо переробити закопане сміття, завдаючи ${$471211s1*$<rolemult>} шкоди чумою вашій цілі за заряд. Залишкова вірулентність завдає $471211s3% завданої шкоди $471211s2 ворогам поблизу протягом $1220481d." },
    { en = "Summons a Tranquil Spout to heal you for $d.", ua = "Прикликає Спокійне Джерело, що зцілює вас протягом $d." },
    { en = "You have a chance to gain Berserker when you deal or take damage in combat, increasing your critical strike by $60196s1 for $60196d.  Effect stacks up to 3 times.", ua = "Завдаючи чи отримуючи шкоду в бою, ви маєте шанс отримати Берсерк, що підвищує вашу критичну ударність на $60196s1 протягом $60196d. Ефект накопичується до 3 разів." },
    { en = "Your attacks have a chance to grant $177038s1 Mastery for $177038d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177038s1 майстерності протягом $177038d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When your spells deal damage you have a chance to gain $126476s1 critical strike for $126476d.", ua = "Коли ваші закляття завдають шкоди, ви маєте шанс отримати $126476s1 критичної ударності протягом $126476d." },
    { en = "Your Mortal Strike, Bloodthirst, and Shield Slam attacks have a $h% chance to heal you for $40459s1 and grant $40459s2 Strength for $40459d.", ua = "Ваші атаки Смертельний Удар, Жага Крові та Удар Щитом мають $h% шанс зцілити вас на $40459s1 і надати $40459s2 сили протягом $40459d." },
    { en = "Occasionally share a drink with allies who assist you in combat, granting them $s2 of their primary stat for $443381d and absorbing $s3 damage. You take a sip as well, granting $s4 $pri and absorbing $s5 damage.\n\n\n\nWhen you fall below $s1% health, you take an emergency sip. This may only occur once every $450610d.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "Час від часу ділиться напоєм із союзниками, які допомагають вам у бою, надаючи їм $s2 їхньої основної характеристики на $443381d та поглинаючи $s3 шкоди. Ви теж робите ковток, отримуючи $s4 $pri та поглинаючи $s5 шкоди.\n\n\n\nКоли ваше здоров'я падає нижче $s1%, ви робите аварійний ковток. Це може статися лише раз на $450610d.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Дійсне лише для танкових спеціалізацій.|r]" },
    { en = "Your damaging abilities have a very high chance to charge the magnet, up to $1219661u times.", ua = "Ваші здібності, що завдають шкоди, мають дуже високий шанс зарядити магніт, до $1219661u разів." },
    { en = "Your abilities have a high chance to summon a phantom ethereal, dealing ${$<rolemult>*$s1} Shadow damage to your target and ${$<rolemult>*$s1*($s5/100)} Shadow damage to all other enemies caught in its path. \n\n\n\nIf the target is below $s2% health, this effect summons two additional phantoms at $s3% effectiveness.", ua = "Ваші здібності мають високий шанс прикликати примарного ефірного, завдаючи ${$<rolemult>*$s1} шкоди тінню вашій цілі та ${$<rolemult>*$s1*($s5/100)} шкоди тінню всім іншим ворогам на його шляху. \n\n\n\nЯкщо ціль має менше за $s2% здоров'я, цей ефект прикликає двох додаткових примар із $s3% ефективністю." },
    { en = "Absorbs up to $s3 damage from a lethal attack. When this effect occurs, erupt in a burst of flames, inflicting ${$s1*(1+$@versadmg)} Fire damage to nearby allies and enemies, and recovering ${$s2*(1+$@versadmg)} health.\n\n\n\nThis effect can only occur once every $344907d.", ua = "Поглинає до $s3 шкоди від смертельної атаки. Коли цей ефект спрацьовує, ви вибухаєте полум'ям, завдаючи ${$s1*(1+$@versadmg)} шкоди вогнем союзникам і ворогам поблизу та відновлюючи ${$s2*(1+$@versadmg)} здоров'я.\n\n\n\nЦей ефект може спрацьовувати лише раз на $344907d." },
    { en = "Summon your eagle to fly beside you. It will leave upon moving.", ua = "Прикликає вашого орла, щоб він летів поруч із вами. Він зникне, щойно ви рушите з місця." },
    { en = "Inflicts $s1 Fire damage and stuns the targets in a $a1 yard radius for $d.", ua = "Завдає $s1 шкоди вогнем і оглушує цілі в радіусі $a1 м на $d." },
    { en = "Your spells have a chance to increase your Intellect by $202879s1 for $202879d.", ua = "Ваші закляття мають шанс підвищити ваш інтелект на $202879s1 протягом $202879d." },
    { en = "Join the Crimson Chorus. Every minute, your Critical Strike swells by ${$s1*3} over ${$344803d*3} sec. before returning to normal. This effect is increased by $s2% for each member of the Crimson Chorus in your party.", ua = "Приєднайтеся до Багряного Хору. Щохвилини ваша критична ударність зростає на ${$s1*3} протягом ${$344803d*3} с, а потім повертається до норми. Цей ефект посилюється на $s2% за кожного учасника Багряного Хору у вашій групі." },
    { en = "Call upon two Void Stalkers to strike your target from two directions inflicting up to ${$250908s1*2*$<rolemult>} Physical damage to all enemies in their paths.", ua = "Прикликає двох Переслідувачів Порожнечі, щоб вони вдарили вашу ціль із двох напрямків, завдаючи до ${$250908s1*2*$<rolemult>} фізичної шкоди всім ворогам на їхньому шляху." },
    { en = "Add another.", ua = "Додати ще одну." },
    { en = "Your healing spells have a chance to grant you Infinite Power.  Once you have accumulated $139189u Infinite Power, you will instantly heal the most injured nearby party member for $139195s1.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші зцілювальні закляття мають шанс надати вам Нескінченну Силу. Щойно ви накопичите $139189u Нескінченної Сили, ви миттєво зцілите найтяжче пораненого учасника групи поблизу на $139195s1. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to increase your Strength by $231945s1, $231946s1, or $231947s1 for $231945d.", ua = "Ваші атаки мають шанс підвищити вашу силу на $231945s1, $231946s1 або $231947s1 протягом $231945d." },
    { en = "Your melee attacks grant $109750s1 Strength for the next $109750d, stacking up to $109750u times.", ua = "Ваші ближні атаки надають $109750s1 сили протягом наступних $109750d, накопичуючись до $109750u разів." },
    { en = "Has a 2% chance when struck in combat of protecting you with a holy shield.", ua = "Має 2% шанс при отриманні удару в бою захистити вас священним щитом." },
    { en = "Casting a single target heal has a chance to summon a Zoatroid on your target, absorbing ${$s1*(1+$@versadmg)} damage and granting up to $302935s2 Versatility, based on the absorb remaining. Every $303137s1% mana you spend nourishes your Zoatroids, adding ${$s2*(1+$@versadmg)} absorb and $302935s3 Versatility.", ua = "Застосування одноцільового зцілення має шанс прикликати Зоатроїда на вашій цілі, що поглинає ${$s1*(1+$@versadmg)} шкоди та надає до $302935s2 універсальності залежно від залишку поглинання. За кожні $303137s1% мани, які ви витрачаєте, ваші Зоатроїди живляться, додаючи ${$s2*(1+$@versadmg)} поглинання та $302935s3 універсальності." },
    { en = "Increases your armor by ${$24575m1*10} and dodge by ${$24575m2*10} for $d. Every time you take melee or ranged damage, this bonus is reduced by $24575s1 armor and $24575s2 dodge.", ua = "Підвищує вашу броню на ${$24575m1*10} та ухиляння на ${$24575m2*10} протягом $d. Щоразу, коли ви отримуєте шкоду в ближньому чи дальньому бою, цей бонус зменшується на $24575s1 броні та $24575s2 ухиляння." },
    { en = "You gain a Shard of Flame each time you cause a non-periodic spell critical strike.  When you reach $s1 Shards, they will release, firing a Pillar of Flame for $67760s1 damage.  Shard of Flame cannot be gained more often than once every 2 sec.", ua = "Ви отримуєте Уламок Полум'я щоразу, коли завдаєте неперіодичного критичного удару закляттям. Коли ви досягнете $s1 Уламків, вони вивільняться, випустивши Стовп Полум'я, що завдає $67760s1 шкоди. Уламок Полум'я не можна отримувати частіше за раз на 2 с." },
    { en = "Send your swarm into a frenzy, summoning $s1 scarabs over $d to ravage your foes. The number of scarabs is increased by your Haste.", ua = "Доводить ваш рій до шаленства, прикликаючи $s1 скарабеїв протягом $d, щоб шматувати ваших ворогів. Кількість скарабеїв зростає від вашої швидкості." },
    { en = "Sap the soul of your target for $d, causing you to be healed for $s1% of the damage you deal to them, up to $215938s2 total healing.", ua = "Висмоктує душу вашої цілі протягом $d, зцілюючи вас на $s1% шкоди, яку ви їй завдаєте, до $215938s2 загального зцілення." },
    { en = "Reflects Fire spells back at their caster for $d.  Chance to be resisted when used by players over level $ctrmax2067.", ua = "Відбиває закляття вогню назад у того, хто їх наклав, протягом $d. Існує ймовірність опору, коли застосовується гравцями, вищими за рівень $ctrmax2067." },
    { en = "Your ranged spells and abilities have a chance to unleash a volley of pure decay, dealing up to ${$s2*$s1} Nature damage split between enemies hit and decreasing their movement speed by up to ${$393935s3*$s1}% for $393935d.", ua = "Ваші дальні закляття та здібності мають шанс вивільнити залп чистого тліну, завдаючи до ${$s2*$s1} шкоди природою, розподіленої між враженими ворогами, та знижуючи їхню швидкість пересування до ${$393935s3*$s1}% протягом $393935d." },
    { en = "Your damaging spells have a chance for a swarm of carrion insects to engulf your target, dealing $221812o1 Nature damage over $221812d.", ua = "Ваші закляття, що завдають шкоди, мають шанс огорнути вашу ціль роєм трупоїдних комах, завдаючи $221812o1 шкоди природою протягом $221812d." },
    { en = "Your harmful spells have a chance to grant $92320s1 mastery for $92320d.", ua = "Ваші шкідливі закляття мають шанс надати $92320s1 майстерності протягом $92320d." },
    { en = "Your melee and ranged attacks have a chance to strike your enemy, dealing $60443s1 arcane damage.", ua = "Ваші ближні та дальні атаки мають шанс уразити ворога, завдаючи $60443s1 шкоди тайнощами." },
    { en = "Sear an enemy with holy light, inflicting $o1 Holy damage over $d. Restores $255981s1 mana each time damage is dealt.", ua = "Випалює ворога священним світлом, завдаючи $o1 шкоди святістю протягом $d. Відновлює $255981s1 мани щоразу, коли завдається шкода." },
    { en = "When you deal damage or heal a target you have a chance to gain $182057s1 Intellect for $182057d.", ua = "Коли ви завдаєте шкоди чи зцілюєте ціль, ви маєте шанс отримати $182057s1 інтелекту протягом $182057d." },
    { en = "Your next 5 damage or healing spells cast within 20 seconds will grant a bonus of $28204s1 spell power, stacking up to 5 times. Expires after 6 damage or healing spells or 20 seconds, whichever occurs first.", ua = "Ваші наступні 5 заклять шкоди чи зцілення, застосованих протягом 20 секунд, нададуть бонус $28204s1 до сили заклять, накопичуючись до 5 разів. Зникає після 6 заклять шкоди чи зцілення або через 20 секунд, залежно від того, що настане раніше." },
    { en = "Your spells and abilities have a chance to activate the Manacell, filling you with Volatile Power that grants $s1 of a random secondary stat for $1270343d.", ua = "Ваші закляття та здібності мають шанс активувати Манокомірку, наповнюючи вас Нестійкою Силою, що надає $s1 випадкової вторинної характеристики протягом $1270343d." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $75477s1 dodge for $75477d.  Cannot occur more than once every 45 sec.", ua = "Ближні атаки, що знижують ваше здоров'я нижче за $s1%, надають вам $75477s1 ухиляння протягом $75477d. Може спрацьовувати не частіше ніж раз на 45 с." },
    { en = "Release all toxin stacks to deal ${$1216603s2*$<rolemult>} Nature damage, plus ${$1216603s3*$<rolemult>} per stack over $1216606d1.", ua = "Вивільняє всі накопичення токсину, щоб завдати ${$1216603s2*$<rolemult>} шкоди природою плюс ${$1216603s3*$<rolemult>} за накопичення протягом $1216606d1." },
    { en = "Each time you cast a harmful spell, you have a chance to gain $67669s1 spell power for $67669d.", ua = "Щоразу, коли ви застосовуєте шкідливе закляття, ви маєте шанс отримати $67669s1 сили заклять протягом $67669d." },
    { en = "When your attacks hit you have a chance to gain $126483s1 haste for $126483d.", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $126483s1 швидкості на $126483d." },
    { en = "Captures the target in a net for $13099d.  The net has a lot of hooks however and sometimes gets caught in the user's clothing when fired......", ua = "Ловить ціль у сітку на $13099d. Проте сітка має багато гачків і часом чіпляється за одяг власника під час пострілу..." },
    { en = "Your spells have a chance to wrap yourself in red magic, causing spells to deal $s1 additional Fire damage to enemies or healing to allies for $377544d.", ua = "Ваші заклять мають шанс огорнути вас червоною магією, через що заклять завдають $s1 додаткової шкоди вогнем ворогам або зцілюють союзників на цю величину протягом $377544d." },
    { en = "Activate the Soulshield to unleash a shockwave dealing $1235218s2 Arcane damage to all nearby enemies and reduce your damage taken by $s2% for $d or until $1235218s1 damage has been prevented.", ua = "Активуйте Душевний Щит, щоб вивільнити ударну хвилю, яка завдає $1235218s2 шкоди від тайнощів усім ворогам поблизу та знижує отримувану вами шкоду на $s2% протягом $d або доки не буде відвернено $1235218s1 шкоди." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain $52419s1 parry for $52419d.  Cannot occur more than once every 30 sec.", ua = "Атаки ближнього бою, що знижують ваше здоров'я нижче $s1%, надають вам $52419s1 парирування на $52419d. Може спрацьовувати не частіше ніж раз на 30 сек." },
    { en = "Consumes all Blessings of Zuldazar to shield the target, absorbing $s1 damage per Blessing consumed.  Lasts $d.", ua = "Поглинає всі Благословення Зулдазару, щоб захистити ціль, поглинаючи $s1 шкоди за кожне поглинуте Благословення. Триває $d." },
    { en = "When you deal damage or heal a target you have a chance to gain $190027s1 Intellect for $190027d.", ua = "Коли ви завдаєте шкоди або зцілюєте ціль, ви маєте шанс отримати $190027s1 інтелекту на $190027d." },
    { en = "Grants $s1 armor for $d.", ua = "Надає $s1 броні на $d." },
    { en = "Coat your weapons in Flayedwing Toxin for $d, giving your attacks a high chance to inflict ${$<rolemult>*$345547s1*3} Nature damage over $345546d.", ua = "Покриває вашу зброю Токсином Білокрила на $d, надаючи вашим атакам високий шанс завдати ${$<rolemult>*$345547s1*3} шкоди силами природи протягом $345546d." },
    { en = "Your helpful spells have a chance to grant $148908s1 Intellect for $148908d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші сприятливі заклять мають шанс надати $148908s1 інтелекту на $148908d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to direct a Kobold Cart towards your target, sending a careening troop that collides with enemies, inflicting ${$<rolemult>*$s1} Physical damage split between enemies impacted.", ua = "Ваші атаки мають шанс направити Кобольдський Візок на вашу ціль, посилаючи нестримний загін, що врізається у ворогів, завдаючи ${$<rolemult>*$s1} фізичної шкоди, поділеної між уражениими ворогами." },
    { en = "Your critical strikes have a chance to summon a lava serpent to attack your target for 10 sec. The serpent spews a lava bolt every 2 sec, dealing $s1 Volcanic damage. Every third summoning, call forth three serpents instead.\n\n\n\nIf the target dies, the serpent enrages to deal $s2 Volcanic damage to up to 8 nearby enemies.", ua = "Ваші критичні удари мають шанс прикликати лавового змія, що атакує вашу ціль протягом 10 сек. Змій випльовує лавовий снаряд кожні 2 сек., завдаючи $s1 вулканічної шкоди. Кожне третє прикликання натомість викликає трьох зміїв.\n\n\n\nЯкщо ціль гине, змій впадає в лють і завдає $s2 вулканічної шкоди до 8 ворогам поблизу." },
    { en = "Your attacks have a chance to grant $177053s1 Versatility for $177053d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177053s1 універсальності на $177053d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your healing spells and abilities have a chance to summon Dr. Scrapheal to heal your target additionally for $s1.\n\n\n\nWhen a nearby ally's health falls below $1213431s1%, Dr. Scrapheal springs into action, delivering instant care to heal them for $1213431s2. This effect can only activate once every $1214057d.", ua = "Ваші зцілювальні заклять і здібності мають шанс прикликати Лікаря Брухтозцілія, щоб додатково зцілити вашу ціль на $s1.\n\n\n\nКоли здоров'я союзника поблизу падає нижче $1213431s1%, Лікар Брухтозцілій вступає в дію, надаючи миттєву допомогу та зцілюючи його на $1213431s2. Цей ефект може спрацьовувати лише раз на $1214057d." },
    { en = "You have a $h% chance when hit by an attack or harmful spell to deal $39445s1 holy damage to your attacker.", ua = "Ви маєте $h% шанс під час влучання атаки або шкідливого закляття завдати $39445s1 шкоди силами Світла вашому нападнику." },
    { en = "Call a Legion ship to bombard the target's location for $255713d, dealing $256325s1 Fire damage to all targets within $255712A1 yds, including the ship.", ua = "Прикликає корабель Легіону, щоб бомбардувати місцеперебування цілі протягом $255713d, завдаючи $256325s1 шкоди вогнем усім цілям у межах $255712A1 ярдів, включно з кораблем." },
    { en = "Each time you cast a helpful spell, you gain $67723s1 spell power.  Stacks up to $67723u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви насилаєте сприятливе закляття, ви отримуєте $67723s1 сили заклять. Накопичується до $67723u разів. Увесь ефект триває $d." },
    { en = "When you deal damage you have a chance to gain $118607s1 mastery for $118607d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $118607s1 майстерності на $118607d." },
    { en = "Draw out a piece of the target's soul, decreasing their movement speed by $s1% until the soul reaches you. The soul instantly heals you for $345806s1, and grants you up to ${$345807s1+$345807s2} Critical Strike for $345805d. You gain more Critical Strike from lower health targets.", ua = "Витягує частину душі цілі, знижуючи її швидкість пересування на $s1%, доки душа не досягне вас. Душа миттєво зцілює вас на $345806s1 та надає вам до ${$345807s1+$345807s2} критичного удару протягом $345805d. Ви отримуєте більше критичного удару від цілей із нижчим здоров'ям." },
    { en = "Stores up to $m1 additional health from spells which heal you for more than your maximum health.", ua = "Зберігає до $m1 додаткового здоров'я із заклять, що зцілюють вас понад вашу максимальну величину здоров'я." },
    { en = "Create a Collapsing Shadow at your location for $d, increasing your Agility or Intellect by $s2 while you are within it.|CFF808080$?!(a137013|a137012|a137015|a137016|a137018|a137024|a137029|a137030|a137040|a137039|a137042)[\n\n\n\nValid for healer and ranged damage specializations.][]|R", ua = "Створіть на своєму місці Згасаючу Тінь на $d, що підвищує вашу спритність або інтелект на $s2, доки ви перебуваєте в ній.|CFF808080$?!(a137013|a137012|a137015|a137016|a137018|a137024|a137029|a137030|a137040|a137039|a137042)[\n\n\n\nДля цілительських спеціалізацій і спеціалізацій дальнього бою.][]|R" },
    { en = "Your spells have a chance to grant $90895s1 critical strike for $90895d.", ua = "Ваші заклять мають шанс надати $90895s1 критичного удару на $90895d." },
    { en = "Your melee and ranged attacks have a chance to grant $120173s1 mastery for $120173d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс надати $120173s1 майстерності на $120173d." },
    { en = "$?a447962[$@spellname448090\n\n$@spelldesc448090]?a447978[$@spellname445475\n\n$@spelldesc445475]?a448036[$@spellname445434 \n\n$@spelldesc445434][$@spellname445434 \n\n$@spelldesc445434]", ua = "$?a447962[$@spellname448090\n\n$@spelldesc448090]?a447978[$@spellname445475\n\n$@spelldesc445475]?a448036[$@spellname445434 \n\n$@spelldesc445434][$@spellname445434 \n\n$@spelldesc445434]" },
    { en = "Returns you to the sanctuary of Dun Baldar.", ua = "Повертає вас до притулку Дун-Балдара." },
    { en = "Your spells and abilities have the chance to grant $s1 secondary stats for $1252487d  based on the target creature's type.\n\n\n\nThis effect is augmented by Darkmoon Sigil: Hunt.", ua = "Ваші заклять і здібності мають шанс надати $s1 вторинних характеристик протягом $1252487d залежно від типу цільового створіння.\n\n\n\nЦей ефект посилюється Печаткою Місяцеликого: Полювання." },
    { en = "Your ranged attacks and spells have a chance to conjure a Spear of Anguish. After $242606d the spear launches towards its target, dealing $246751s1 Shadow damage to all enemies it passes through.", ua = "Ваші атаки та заклять дальнього бою мають шанс прикликати Спис Страждання. Через $242606d спис вилітає до своєї цілі, завдаючи $246751s1 шкоди силами Тіні всім ворогам, крізь яких він проходить." },
    { en = "Your damaging attacks have a chance to claw your target, causing them to bleed for $288330o1 Physical damage over $288333d. Clawing the target from behind will leech ${$288333e1*100}% of the damage done.", ua = "Ваші шкідливі атаки мають шанс роздряпати вашу ціль, змушуючи її стікати кров'ю, завдаючи $288330o1 фізичної шкоди протягом $288333d. Роздряпування цілі ззаду висмоктує ${$288333e1*100}% завданої шкоди." },
    { en = "When your attacks hit you have a chance to gain $160818s1 Critical Strike for $160818d.", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $160818s1 критичного удару на $160818d." },
    { en = "Chance on hit to increase your critical strike by $63250s1 for 10 secs.", ua = "Шанс під час влучання підвищити ваш критичний удар на $63250s1 на 10 сек." },
    { en = "Taking damage has a chance to heal you for $242617o1 over $242617d. When this effect expires, you and up to $s1 allies within $242618A1 yds gain a shield that prevents $242618s1 damage for $242618d.", ua = "Отримання шкоди має шанс зцілити вас на $242617o1 протягом $242617d. Коли цей ефект завершується, ви та до $s1 союзників у межах $242618A1 ярдів отримуєте щит, що відвертає $242618s1 шкоди протягом $242618d." },
    { en = "Channel for $d, unleashing a furious volley of flame around your target, dealing ${$394954s1*($d/$t)*(1+$@versadmg)} Fire damage to your target with a chance to strike nearby enemies for additional damage.\n\n\n\nWhenever an allied player dies, this cooldown is reduced by $s2 seconds.", ua = "Підтримує протягом $d, вивільнюючи лютий залп полум'я навколо вашої цілі, завдаючи ${$394954s1*($d/$t)*(1+$@versadmg)} шкоди вогнем вашій цілі з шансом уразити ворогів поблизу додатковою шкодою.\n\n\n\nЩоразу, коли гине союзний гравець, час відновлення скорочується на $s2 секунд." },
    { en = "Enter an Elemental Stance. Successfully dodging or parrying an attack unleashes a powerful Elemental Counterattack to enemies in front of you as you assume the next stance.\n\n\n\nThis effect can only occur once every $proccooldown seconds.", ua = "Прибравши Стихійну стійку. Успішне ухилення від атаки або її парирування вивільняє потужний Стихійний контрудар по ворогах перед вами, доки ви переходите в наступну стійку.\n\n\n\nЦей ефект може спрацювати лише раз на $proccooldown секунд." },
    { en = "Your healing spells have a chance to increase your Mastery, Haste, or Critical Strike by $s2 for $225749d.", ua = "Ваші зцілювальні заклять мають шанс підвищити вашу майстерність, швидкість або критичний удар на $s2 протягом $225749d." },
    { en = "Your attacks have a chance to grant $177042s1 Mastery for $177042d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177042s1 майстерності на $177042d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your spells and abilities have a chance to remind you of lessons learned from reading books, granting you $340020s1 Mastery for $340020d.", ua = "Ваші заклять і здібності мають шанс нагадати вам уроки, засвоєні з прочитаних книг, надаючи вам $340020s1 майстерності на $340020d." },
    { en = "Your healing spells have a chance to grant you Gathering Clouds, stacking up to $215294u times.", ua = "Ваші зцілювальні заклять мають шанс надати вам Хмари, що Збираються, накопичуючись до $215294u разів." },
    { en = "Your auto attacks have a chance to increase your Strength or Agility, based on your specialization, by $242612s3 for $242612d, and expel orbs of fel energy. Collecting an orb increases the duration of this effect by $s1 sec.", ua = "Ваші автоатаки мають шанс підвищити вашу силу або спритність, залежно від вашої спеціалізації, на $242612s3 протягом $242612d та виштовхнути сфери скверни. Збір сфери збільшує тривалість цього ефекту на $s1 сек." },
    { en = "Your melee attacks have a chance to grant $122694s1 dodge for $122694d.", ua = "Ваші атаки ближнього бою мають шанс надати $122694s1 ухилення на $122694d." },
    { en = "Your attacks grant $109719s1 Agility for the next $109719d, stacking up to $109719u times.", ua = "Ваші атаки надають $109719s1 спритності на $109719d, складаючись до $109719u разів." },
    { en = "You gain $71566s1 mana each time you heal a target with one of your spells.", ua = "Ви отримуєте $71566s1 мани щоразу, коли зцілюєте ціль одним зі своїх заклять." },
    { en = "Your spells and abilities have a chance to grant you $344118s1 $pri for $344118d.", ua = "Ваші чари та здібності мають шанс надати вам $344118s1 $pri протягом $344118d." },
    { en = "Your attacks have a chance to call Bloodstalker worgs to your side.", ua = "Ваші атаки мають шанс прикликати воргів Кровопивців, що б'ються поруч із вами." },
    { en = "Your damaging and healing spells have a chance to increase your Mastery, Haste, or Critical Strike by $s2 for $225749d.", ua = "Ваші заклинання шкоди та зцілення мають шанс підвищити вашу майстерність, швидкість або критичний удар на $s2 на $225749d." },
    { en = "Your melee attacks have a chance to trigger a whirlwind attack dealing $109752s1 physical damage to all targets within $109752A1 yards.", ua = "Ваші атаки ближнього бою мають шанс запустити вихрову атаку, що завдає $109752s1 фізичної шкоди всім цілям у радіусі $109752A1 м." },
    { en = "Feast upon the toe, increasing your Critical Strike by $s1 for $d and causing you to exude a fetid breath, dealing ${$397401s1*$d/$t2} Shadow damage split between enemies in front of you.", ua = "Поглинаєте палець, підвищуючи свій критичний удар на $s1 на $d та змушуючи себе видихати смердюче дихання, що завдає ${$397401s1*$d/$t2} шкоди Тінню, розподіленої між ворогами перед вами." },
    { en = "Restores $s1 health.", ua = "Відновлює $s1 здоров'я." },
    { en = "Receive cryptic instructions from somewhere in the Twisting Nether to reveal your next task. It's probably nothing, so complete it to gain $446209s1 $pri for $449954d.", ua = "Отримує загадкові вказівки звідкись із Викривленої Порожнечі, що розкривають ваше наступне завдання. Це, мабуть, дрібниця, тож виконайте його, щоб отримати $446209s1 $pri протягом $449954d." },
    { en = "Your healing and damaging spells have a chance to grant $116720s1 mastery for $116720d.", ua = "Ваші заклинання зцілення та шкоди мають шанс надати $116720s1 майстерності на $116720d." },
    { en = "Your damaging spells have a chance to haunt the target, dealing ${$s1*$1264613d} Shadow damage over $1264613d.\n\n\n\nIf the target dies while haunted, the effect transfers to a nearby enemy, inflicting $s2% of the Shadow damage over the remaining duration.", ua = "Ваші заклинання шкоди мають шанс переслідувати ціль, завдаючи ${$s1*$1264613d} шкоди Тінню протягом $1264613d.\n\n\n\nЯкщо ціль гине під час переслідування, ефект переходить на ворога поблизу, завдаючи $s2% шкоди Тінню за час, що залишився." },
    { en = "Your melee and ranged strikes have a chance to increase your critical strike by $61619s1 for $61619d.", ua = "Ваші удари ближнього та далекого бою мають шанс підвищити ваш критичний удар на $61619s1 на $61619d." },
    { en = "Fire $s1 Empyreal Ordnance at up to $s2 targets. Targets suffer ${$345542s1*6*(1+$@versadmg)} Arcane damage over $345540d for each ordnance that hits them. As the ordnance expires on the target they return, each granting $345543s1 Intellect for $345541d.", ua = "Випускає $s1 Емпірейних снарядів по щонайбільше $s2 цілях. Цілі зазнають ${$345542s1*6*(1+$@versadmg)} шкоди Тайнами протягом $345540d за кожен снаряд, що в них влучив. Коли снаряд згасає на цілі, він повертається до вас, надаючи $345543s1 інтелекту на $345541d за кожен." },
    { en = "Your harmful abilities have a chance to cause you to summon a Saberon Bodyguard to fight by your side for $175735d.", ua = "Ваші шкідливі здібності мають шанс прикликати Саберонського охоронця, що б'ється поруч із вами протягом $175735d." },
    { en = "Your melee and ranged attacks have a chance to grant $92351s1 critical strike for $92351d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $92351s1 критичного удару на $92351d." },
    { en = "Your melee attacks have a chance to grant $120174s1 dodge for $120174d.", ua = "Ваші атаки ближнього бою мають шанс надати $120174s1 ухилення на $120174d." },
    { en = "Inflict $s1 Shadow damage to an enemy in melee range, plus $o2 damage over $d. If they die while this effect is active, the cooldown of this ability is reduced by $s3 sec.", ua = "Завдає $s1 шкоди Тінню ворогові в зоні ближнього бою, а також $o2 шкоди протягом $d. Якщо він гине, поки цей ефект активний, час відновлення цієї здібності скорочується на $s3 с." },
    { en = "Your damaging and healing abilities have a chance to deal an additional $s2 nature damage to enemies or heal an ally for an additional $s3 health.", ua = "Ваші здібності шкоди та зцілення мають шанс завдати додатково $s2 шкоди Природою ворогам або зцілити союзника на додаткові $s3 здоров'я." },
    { en = "Your melee and ranged attacks have a chance to grant $122688s1 haste for $122688d.", ua = "Ваші атаки ближнього та далекого бою мають шанс надати $122688s1 швидкості на $122688d." },
    { en = "Your abilities have a low chance to inject your target with slime, dealing $o1 Nature damage over $d. Targets that die under its effect will detonate, dealing all remaining Nature damage to nearby enemies.", ua = "Ваші здібності мають низький шанс упорснути цілі слиз, завдаючи $o1 одиниць шкоди Природою протягом $d. Цілі, що гинуть під його дією, вибухають, завдаючи всієї решти шкоди Природою ворогам поблизу." },
    { en = "When you deal damage you have a chance to gain $105139s1 Strength for $105139d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $105139s1 сили на $105139d." },
    { en = "Your attacks have a chance to awaken the powers of the races of Northrend, temporarily transforming you and increasing your combat capabilities for $71491d.", ua = "Ваші атаки мають шанс пробудити сили народів Нортренду, тимчасово перетворюючи вас і підвищуючи ваші бойові можливості на $71491d." },
    { en = "Restores $51353s1 mana when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds.", ua = "Відновлює $51353s1 мани, коли ви вбиваєте ціль, що дає досвід або честь. Цей ефект не може спрацьовувати частіше ніж раз на 10 секунд." },
    { en = "The radius of the second half of the Manifesto is increased by ${$s2} $Lyard:yards; based on the power of your Ashjra'kamas, Shroud of Resolve.", ua = "Радіус другої половини Маніфесту збільшено на ${$s2} $Lyard:yards; залежно від могутності вашого Ашжра'камаса, Савану рішучості." },
    { en = "When you deal damage you have a chance to gain $109787s1 haste for $109787d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109787s1 швидкості на $109787d." },
    { en = "Your spells and abilities have a chance to let loose a nascent empowerment from the crystal, increasing a random secondary stat by $449275s1 for $449275d.", ua = "Ваші заклинання та здібності мають шанс вивільнити з кристала зароджуване підсилення, підвищуючи випадкову вторинну характеристику на $449275s1 на $449275d." },
    { en = "Use: Deal $386623s2 Frost damage and apply Awakening Rime to your target for 4-12s. If the target dies while Awakening Rime is active, it explodes for $370880s Frost damage split between enemies in a 10 yard radius. Duration is determined by the top-most card of the deck.", ua = "Застосування: завдає $386623s2 шкоди Морозом і накладає на ціль Пробудний Іній на 4-12 с. Якщо ціль гине, поки Пробудний Іній активний, вона вибухає, завдаючи $370880s шкоди Морозом, розподіленої між ворогами в радіусі 10 метрів. Тривалість визначається верхньою картою колоди." },
    { en = "Your attacks have a chance to grant you $214494s1 Armor every $214493t2 sec for $214493d.", ua = "Ваші атаки мають шанс надавати вам $214494s1 броні кожні $214493t2 с протягом $214493d." },
    { en = "Your melee attacks have a chance to deal $253324s1 Shadow damage to the target. If there are no other enemies within $s1 yds of them, this deals an additional $255609s2 damage.", ua = "Ваші атаки ближнього бою мають шанс завдати $253324s1 шкоди Тінню цілі. Якщо в радіусі $s1 м від неї немає інших ворогів, це завдає додатково $255609s2 шкоди." },
    { en = "Your spells have a chance to grant you $278253s1 Haste for $278253d, stacking up to $278253u times.", ua = "Ваші заклинання мають шанс надати вам $278253s1 швидкості на $278253d, складаючись до $278253u разів." },
    { en = "Channel the Light for $d, creating a zone of protection around you, absorbing $s3% of all damage taken by allies within, up to a total of $s2.\n\n\n\nYour critical heals have a chance to reduce the cooldown by $363572s1 sec.$?(a137012|a137024|a137031|a137032|a137029|a137039)[][\n\n\n\n|CFF808080Valid only for healer specializations.|R]", ua = "Каналізуйте Світло протягом $d, створюючи навколо себе зону захисту, що поглинає $s3% усієї шкоди, отриманої союзниками всередині, до загального обсягу $s2.\n\n\n\nВаші критичні зцілення мають шанс скоротити час відновлення на $363572s1 сек.$?(a137012|a137024|a137031|a137032|a137029|a137039)[][\n\n\n\n|CFF808080Лише для цілительських спеціалізацій.|R]" },
    { en = "Your attacks have a chance to inflict Choking Brine, causing ${$268194s1*$268194d/$268194t1} Nature damage over $268194d. If the target dies while inflicted with Choking Brine, it splashes to all targets within $268197A1 yds.", ua = "Ваші атаки мають шанс накласти Удушливий Розсіл, завдаючи ${$268194s1*$268194d/$268194t1} шкоди Природою протягом $268194d. Якщо ціль гине під дією Удушливого Розсолу, він розхлюпується на всі цілі в радіусі $268197A1 м." },
    { en = "Your damaging spells dispatch a spider to spy on your foes, increasing your Intellect by $s1 per report received. Stacks up to $451199u times. This effect may only occur every $proccooldown sec.", ua = "Ваші закляття, що завдають шкоди, відправляють павука шпигувати за ворогами, підвищуючи ваш інтелект на $s1 за кожне отримане донесення. Накопичується до $451199u разів. Цей ефект може спрацьовувати лише раз на $proccooldown сек." },
    { en = "$?a450162[Draw the blades once more to perform both strikes at the same time.\n\n\n\nWhen used or after $450157d, the pouch will seal itself to magically recharge its contents.]?a450151[Open the pouch and draw Vx's frost blade to launch a long range attack, inflicting ${$<rolemult>*$450044s2} Frost damage split between enemies it passes through.\n\n\n\nYou may use the pouch one additional time within $450157d before it seals itself to magically recharge its contents.][Open the pouch and draw Nx's shadow blade to quickly strike at enemies in front of you, inflicting ${$<rolemult>*$450044s1} Shadow damage to all enemies hit.\n\n\n\nYou may use the pouch up to two additional times within $450157d before it seals itself to magically recharge its contents.]", ua = "$?a450162[Дістаньте клинки ще раз, щоб завдати обох ударів одночасно.\n\n\n\nПісля використання або через $450157d торбинка запечатається, щоб магічно поповнити свій вміст.]?a450151[Відкрийте торбинку й дістаньте крижаний клинок Вікс, щоб завдати дальнього удару, що завдає ${$<rolemult>*$450044s2} крижаної шкоди, розподіленої між ворогами, крізь яких він проходить.\n\n\n\nВи можете скористатися торбинкою ще один раз протягом $450157d, перш ніж вона запечатається, щоб магічно поповнити свій вміст.][Відкрийте торбинку й дістаньте тіньовий клинок Нікс, щоб швидко вдарити ворогів перед собою, завдаючи ${$<rolemult>*$450044s1} тіньової шкоди всім враженим ворогам.\n\n\n\nВи можете скористатися торбинкою ще до двох разів протягом $450157d, перш ніж вона запечатається, щоб магічно поповнити свій вміст.]" },
    { en = "Your healing abilities have a chance to power the Aethercell increasing your Mastery by $s1, decreasing by ${$s1/$1245397d1} each sec. Lasts $1245397d1.", ua = "Ваші здібності зцілення мають шанс наснажити Етерну комірку, підвищуючи вашу майстерність на $s1, що зменшується на ${$s1/$1245397d1} щосекунди. Триває $1245397d1." },
    { en = "Your Critical Strike increases by $s1 every $t1 sec, capping at ${$s1*$s2} Critical Strike for ${$t1*$s3} sec, then decreasing and turning off for ${$t1*$s3} sec, cycling every $s4 sec.", ua = "Ваш критичний удар підвищується на $s1 кожні $t1 с, сягаючи межі ${$s1*$s2} критичного удару протягом ${$t1*$s3} с, потім зменшується та вимикається на ${$t1*$s3} с, повторюючи цикл кожні $s4 с." },
    { en = "Your melee attacks have a chance to grant $117650s1 mastery for $117650d.", ua = "Ваші атаки ближнього бою мають шанс надати $117650s1 майстерності на $117650d." },
    { en = "Your healing spells have a chance to grant $91149s1 Versatility for $91149d.", ua = "Ваші заклинання зцілення мають шанс надати $91149s1 універсальності на $91149d." },
    { en = "Your critical heals have a chance to instantly heal the most injured nearby party member for $109825s1.", ua = "Ваші критичні зцілення мають шанс миттєво зцілити найтяжче пораненого члена групи поблизу на $109825s1." },
    { en = "Your attacks have a chance to summon a whirlwind of sharpened claws, inflicting $268525s1 Physical damage split evenly among all enemies within $268525A1 yards.", ua = "Ваші атаки мають шанс прикликати вихор гострих кігтів, що завдає $268525s1 фізичної шкоди, розподіленої рівномірно між усіма ворогами в радіусі $268525A1 м." },
    { en = "Your harmful spells have a chance to increase your Haste by $33370s1 for $33370d.", ua = "Ваші шкідливі заклинання мають шанс підвищити вашу швидкість на $33370s1 на $33370d." },
    { en = "Every $472636t sec spent in combat causes the rune to overcharge, striking a nearby enemy with lightning dealing $s1 Nature damage.\n\n\n\nThis effect triggers immediately when striking a creature for the first time.", ua = "Кожні $472636t сек у бою руна перенавантажується, вражаючи найближчого ворога блискавкою, що завдає $s1 шкоди від сил природи.\n\n\n\nЦей ефект спрацьовує миттєво, коли ви вперше вражаєте істоту." },
    { en = "Your spells and abilities have a chance to grant you $285472s1 Versatility for $285472d.", ua = "Ваші закляття й здібності мають шанс надати вам $285472s1 універсальності на $285472d." },
    { en = "When your attacks hit you have a chance to gain $133630s1 Mastery for $133630d.", ua = "Коли ваші атаки влучають, є шанс отримати $133630s1 майстерності на $133630d." },
    { en = "Recalibrate for $?a467492[$@spellname467497]?a467497[$@spellname467492][$@spellname467497].", ua = "Перекалібровує на $?a467492[$@spellname467497]?a467497[$@spellname467492][$@spellname467497]." },
    { en = "Consume all Congealing Goo to vomit on enemies in front of you for $d, inflicting ${$o1*(1+$@versadmg)} Nature damage per Goo consumed.", ua = "Поглинає всю Згусаючу Слиз, щоб блювати на ворогів перед вами протягом $d, завдаючи ${$o1*(1+$@versadmg)} шкоди від сил природи за кожну поглинуту Слиз." },
    { en = "Your healing spells grant $107962s1 Versatility for the next $107962d, stacking up to $107962u times.", ua = "Ваші зцілювальні закляття надають $107962s1 універсальності на наступні $107962d, накопичуючись до $107962u разів." },
    { en = "Increases speed by $s1% for $d.", ua = "Підвищує швидкість пересування на $s1% на $d." },
    { en = "Your spells have a chance to grant $90898s1 spell power for $90898d.", ua = "Ваші закляття мають шанс надати $90898s1 сили заклять на $90898d." },
    { en = "Your healing spells have a chance to deliver a burst of $352273s1 healing split among your target and nearby allies and granting you $352274s1 Haste for $352274d. Deals increased healing when healing multiple allies.", ua = "Ваші зцілювальні закляття мають шанс вивільнити сплеск зцілення на $352273s1, розподілений між вашою ціллю та найближчими союзниками, а також надати вам $352274s1 швидкості на $352274d. Зцілення збільшується, коли ви зціляєте кількох союзників." },
    { en = "Release the fetters to empower your soul, increasing your $pri by $1230281s1 for $d.", ua = "Звільняє пута, щоб підсилити вашу душу, збільшуючи ваш $pri на $1230281s1 протягом $d." },
    { en = "Sometimes heals bearer of $23682s1 damage when damaging an enemy in melee.", ua = "Іноді зціляє носія на $23682s1, коли він завдає ворогові шкоди в ближньому бою." },
    { en = "Increases $pri by $s1 for $d.", ua = "Підвищує $pri на $s1 протягом $d." },
    { en = "Increase your Critical Strike, Haste, Mastery, and Versatility by $s1 for $d.", ua = "Підвищує ваш критичний удар, швидкість, майстерність та універсальність на $s1 на $d." },
    { en = "Consume $91832u stacks of Raw Fury to forge into the form of a Blackwing Dragonkin, granting $s2 Strength for $d.", ua = "Поглинає $91832u стосів Сирої Люті, щоб перетворитися на Чорнокрилого драконіда, надаючи $s2 сили на $d." },
    { en = "Your attacks and abilities have a chance to electrify the target, dealing $255586s1 Nature damage every $253309t1 sec for $253309d.", ua = "Ваші атаки й здібності мають шанс наелектризувати ціль, завдаючи $255586s1 шкоди від сил природи кожні $253309t1 сек протягом $253309d." },
    { en = "Your melee attacks have a chance to grant $92345s1 Strength for $92345d.", ua = "Ваші атаки в ближньому бою мають шанс надати $92345s1 сили на $92345d." },
    { en = "Your attacks have a chance to summon a Ghost Iron Dragonling to fight with you for $131411d.", ua = "Ваші атаки мають шанс прикликати Драконину з примарної криці, що б'ється поруч із вами протягом $131411d." },
    { en = "Bind a spectral essence to an enemy for $d, causing allied attacks to heal for $s2% of damage dealt, up to $s1 total healing.\n\n\n\nWhen the essence expires or is removed early, the remaining healing bursts, healing up to $s3 allies within $345704a1 yds.", ua = "Прив'язує примарну сутність до ворога на $d, через що атаки союзників зціляють на $s2% завданої шкоди, до $s1 загального зцілення.\n\n\n\nКоли сутність згасає або знімається завчасно, рештки зцілення вибухають, зціляючи до $s3 союзників у межах $345704a1 м." },
    { en = "Your attacks have a chance to grant you $278249s1 Critical Strike for $278249d.", ua = "Ваші атаки мають шанс надати вам $278249s1 критичного удару на $278249d." },
    { en = "When struck you have a chance to reduce all damage taken by $15595s1 for $15595d.", ua = "Коли вас уражено, є шанс зменшити всю отримувану шкоду на $15595s1 на $15595d." },
    { en = "Fly to a nearby Totem of Pa'ku. Only usable outdoors in Dazar'alor.", ua = "Летить до найближчого Тотема Па'ку. Можна використати лише просто неба в Дазар'алорі." },
    { en = "Your damaging abilities have a chance to call a Child of Rezan to viciously rend your target, dealing $s1 Physical damage and causing them to bleed for ${($429233d/$429233t2)*$s2} damage over $429233d.", ua = "Ваші здібності, що завдають шкоди, мають шанс прикликати Дитя Резана, щоб люто роздерти вашу ціль, завдаючи $s1 фізичної шкоди й змушуючи її кровоточити на ${($429233d/$429233t2)*$s2} шкоди протягом $429233d." },
    { en = "Bring forth your Argent Tome and smite your foes with its sacred wisdom.", ua = "Дістає ваш Срібний Том і вражає ваших ворогів його священною мудрістю." },
    { en = "Your melee attacks grant $109782s1 dodge for the next $109782d, stacking up to $109782u times.", ua = "Ваші атаки в ближньому бою надають $109782s1 ухилення на наступні $109782d, накопичуючись до $109782u разів." },
    { en = "Your spells and abilities have a chance to embolden those around you, granting $s1 Versatility split between you and nearby allies.\n\n\n\nVersatility is increased for each ally affected, up to $s2 allies.", ua = "Ваші закляття й здібності мають шанс надихнути тих, хто поруч, надаючи $s1 універсальності, розподіленої між вами та найближчими союзниками.\n\n\n\nУніверсальність збільшується за кожного враженого союзника, до $s2 союзників." },
    { en = "Your attacks have a chance to increase your Critical Strike by $s1 and size, diminishing over $1262753d.", ua = "Ваші атаки мають шанс підвищити ваш критичний удар на $s1 та збільшити ваш розмір, що спадає протягом $1262753d." },
    { en = "Open a portal at an ally's location that releases brilliant light, restoring $253282s1 health split amongst injured allies within $253282A1 yds.", ua = "Відкриває портал у місці союзника, що випромінює сяйливе світло, відновлюючи $253282s1 здоров'я, розподіленого між пораненими союзниками в межах $253282A1 м." },
    { en = "Your spells and abilities have a chance to grant you $268623s1 Critical Strike for $268623d.", ua = "Ваші закляття й здібності мають шанс надати вам $268623s1 критичного удару на $268623d." },
    { en = "Release the Nethergate, flooding your location with corrupted mana dealing $1246837s1 damage every $1246837s3 sec to enemies inside for $d and Heal for $1246837s2 per target hit up to $1246837s4 targets.", ua = "Вивільняє Нетербраму, затоплюючи ваше місце спотвореною маною, що завдає $1246837s1 шкоди кожні $1246837s3 сек ворогам усередині протягом $d і зціляє на $1246837s2 за кожну вражену ціль, до $1246837s4 цілей." },
    { en = "Increase your Intellect by ${$s1*20} decreasing by ${$s1*4} every $t2 sec.", ua = "Підвищує ваш інтелект на ${$s1*20}, зменшуючись на ${$s1*4} кожні $t2 сек." },
    { en = "Your damage spells grant Heart's Revelation, increasing spell power by $92325s1 for $92325d and stacking up to $92325u times.", ua = "Ваші закляття шкоди надають Одкровення Серця, підвищуючи силу заклять на $92325s1 на $92325d і накопичуючись до $92325u разів." },
    { en = "Your attacks have a chance to cause a Void Sector, instantly dealing $278153s1 Shadow damage split among all targets in a cone in front of you. Deals increased damage when striking multiple targets.", ua = "Ваші атаки мають шанс створити Сектор Порожнечі, миттєво завдаючи $278153s1 шкоди від темряви, розподіленої між усіма цілями в конусі перед вами. Завдає більше шкоди при ураженні кількох цілей." },
    { en = "Your melee and ranged attacks have a chance to grant $118752s1 haste for $118752d.", ua = "Ваші атаки в ближньому й дальньому бою мають шанс надати $118752s1 швидкості на $118752d." },
    { en = "Reveal your enemy's impending demise, increasing your Haste by $303455s1 for $303431d. For every $s1% health your target is missing, gain $303455s2 additional Haste.", ua = "Розкриває наближення загибелі вашого ворога, підвищуючи вашу швидкість на $303455s1 на $303431d. За кожні $s1% здоров'я, яких бракує вашій цілі, ви отримуєте додатково $303455s2 швидкості." },
    { en = "Your melee and ranged attacks have a chance to burn your enemy, dealing $60307s1 Fire damage.", ua = "Ваші атаки в ближньому й дальньому бою мають шанс спалити вашого ворога, завдаючи $60307s1 шкоди від вогню." },
    { en = "Your harmful abilitlies have a chance to cause you to summon a spectral guardian to fight by your side for $163725d.", ua = "Ваші шкідливі здібності мають шанс прикликати примарного охоронця, що б'ється поруч із вами протягом $163725d." },
    { en = "Your healing abilities have a chance to call the nearby metal to form a shield around an ally, absorbing $s1 damage.\n\n\n\nThe shield reacts explosively to fire, inflicting $s2 Fire damage to nearby enemies when struck.", ua = "Ваші зцілювальні здібності мають шанс зібрати найближчий метал, щоб сформувати щит навколо союзника, поглинаючи $s1 шкоди.\n\n\n\nЩит вибухово реагує на вогонь, завдаючи $s2 шкоди від вогню найближчим ворогам, коли його уражено." },
    { en = "Your attacks have a chance to grant you $231965s1 Agility every $t1 sec for $d.", ua = "Ваші атаки можуть надати вам $231965s1 Спритності кожні $t1 с протягом $d." },
    { en = "Your spells have a chance to wrap your target in winds, slicing an enemy for $s1 Nature damage or granting $s2 Haste to an ally over $384584d.", ua = "Ваші закляття мають шанс огорнути вашу ціль вітрами, розтинаючи ворога на $s1 шкоди від сил природи або надаючи $s2 швидкості союзникові протягом $384584d." },
    { en = "Become an unstoppable storm of destructive force, striking all targets within $50622A1 yards $?s23881[with both weapons for ${7*($225308m1+$225307m1)} Physical damage][for ${7*$225308m1} Physical damage] over $d.\n\n\n\nYou are immune to movement impairing and loss of control effects, but can use defensive abilities and can avoid attacks.", ua = "Перетворює вас на нестримну бурю руйнівної сили, що вражає всі цілі в межах $50622A1 м $?s23881[обома руками, завдаючи ${7*($225308m1+$225307m1)} фізичної шкоди][завдаючи ${7*$225308m1} фізичної шкоди] протягом $d.\n\n\n\nВи несприйнятливі до ефектів сповільнення руху та втрати контролю, але можете застосовувати захисні здібності й ухилятися від атак." },
    { en = "Your attacks have a chance to grant you Wrath of Elune, causing them to inflict $202912s1 additional Holy damage for $202912d.", ua = "Ваші атаки мають шанс надати вам Гнів Елуни, через що вони завдають додатково $202912s1 шкоди від священних сил протягом $202912d." },
    { en = "Increases your stealth slightly.", ua = "Трохи підвищує вашу непомітність." },
    { en = "Your damaging abilities have a chance to call a magma worm that unleashes a molten volley at your target, dealing up to ${$s1*3} Fire damage.", ua = "Ваші здібності, що завдають шкоди, мають шанс прикликати магмового черва, який вивергає розплавлений залп по вашій цілі, завдаючи до ${$s1*3} шкоди вогнем." },
    { en = "Your attacks or attacks made against you have a chance to increase your Critical Strike by $s1 for $336372d stacking up to $336372u times.", ua = "Ваші атаки або атаки проти вас мають шанс підвищити ваш критичний удар на $s1 на $336372d, накопичуючись до $336372u разів." },
    { en = "Your healing spells grant $109811s1 Versatility for the next $109811d, stacking up to $109811u times.", ua = "Ваші зцілювальні закляття надають $109811s1 універсальності на наступні $109811d, накопичуючись до $109811u разів." },
    { en = "Your auto attacks increase your haste by ${$m1/100}.2% for $185230d, stacking up to $185230u times. This effect is reset if you auto attack a different target.", ua = "Ваші авто-атаки підвищують вашу швидкість на ${$m1/100}.2% на $185230d, накопичуючись до $185230u разів. Цей ефект скидається, якщо ви авто-атакуєте іншу ціль." },
    { en = "Channel torrents around you dealing ${$s1*($390459d/$390459t1)*(1+$@versadmg)} nature damage to nearby enemies over $390459d. Then unleash a powerful blast dealing $s2 nature damage split between all nearby enemies.", ua = "Спрямовує навколо вас потоки, завдаючи ${$s1*($390459d/$390459t1)*(1+$@versadmg)} шкоди силами природи довколишнім ворогам протягом $390459d. Потім вивільняє потужний вибух, що завдає $s2 шкоди силами природи, розподіленої між усіма довколишніми ворогами." },
    { en = "Apply Bladedancer's Armor for $d, increasing your armor by $342426s1 and causing attackers to suffer $s1 Physical damage.", ua = "Накладає на $d «Обладунок Танцівника з Клинком», підвищуючи вашу броню на $342426s1 та змушуючи нападників зазнавати $s1 фізичної шкоди." },
    { en = "Releases all mana stored within the doll, causing you to gain that much mana, and all enemies within $a2 yards take 1 point of Arcane damage for each point of mana released.", ua = "Вивільняє всю накопичену в ляльці ману, даючи вам відповідну кількість мани, а всі вороги в межах $a2 ярдів зазнають 1 одиниці арканної шкоди за кожну вивільнену одиницю мани." },
    { en = "Your melee attacks have a chance to latch a bloody hook onto the target. After $449877d the hook retracts, raking them for ${$<rolemult>*$s1} Physical damage.\n\n\n\nWhile hooked, any critical Physical strike buries the hook further into the target, causing an additional ${$<rolemult>*$s2} Physical damage over $449886d.", ua = "Ваші ближні атаки мають шанс вчепити криваве жало в ціль. За $449877d жало висмикується, шматуючи її на ${$<rolemult>*$s1} фізичної шкоди.\n\n\n\nПоки жало встромлене, кожен критичний фізичний удар занурює його глибше в ціль, завдаючи додатково ${$<rolemult>*$s2} фізичної шкоди протягом $449886d." },
    { en = "Your spells and abilities have a chance to strike yourself with empowering lightning, dealing $s2 Nature damage to yourself and increasing your Haste by $s1 for $392128d.", ua = "Ваші закляття та здібності мають шанс уразити вас підсилювальною блискавкою, завдаючи вам $s2 шкоди силами природи та підвищуючи вашу швидкість на $s1 на $392128d." },
    { en = "When you deal damage you have a chance to gain $102744s1 Haste for $102744d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $102744s1 швидкості на $102744d." },
    { en = "Taking damage has a low chance to grant you a shield, absorbing $s2 damage for $389527d, and increasing your Armor by $s3 while the shield holds. The shield explodes when broken, dealing $s4 Physical damage split between all nearby enemies.", ua = "Зазнавання шкоди має низький шанс надати вам щит, що поглинає $s2 шкоди на $389527d та підвищує вашу броню на $s3, поки щит тримається. Щит вибухає при руйнуванні, завдаючи $s4 фізичної шкоди, розподіленої між усіма довколишніми ворогами." },
    { en = "Your spells and abilities have a chance to call a Ruby Whelpling, which will try to be helpful and assist you in combat.", ua = "Ваші закляття та здібності мають шанс прикликати Рубінового Дракончика, який намагатиметься бути корисним і допомагати вам у бою." },
    { en = "Drains health from an enemy, transferring it to the caster.", ua = "Висмоктує здоров'я з ворога, передаючи його заклинателю." },
    { en = "Your spells and abilities have a chance to grant you $269883s1 Versatility for $269883d.", ua = "Ваші закляття та здібності мають шанс надати вам $269883s1 універсальності на $269883d." },
    { en = "Your melee and ranged attacks have a chance to grant $118615s1 mastery for $118615d.", ua = "Ваші ближні та дальні атаки мають шанс надати $118615s1 майстерності на $118615d." },
    { en = "When you deal damage you have a chance to gain $71401s1 attack power for $71401d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $71401s1 сили атаки на $71401d." },
    { en = "Your damage spells grant Heart's Revelation, increasing spell power by $91027s1 for $91027d and stacking up to $91027u times.", ua = "Ваші закляття шкоди надають «Одкровення Серця», підвищуючи силу заклять на $91027s1 на $91027d, накопичуючись до $91027u разів." },
    { en = "Your spells and abilities have a chance to heal you for $268528o1 over $268528d.", ua = "Ваші закляття та здібності мають шанс зцілити вас на $268528o1 протягом $268528d." },
    { en = "Perform the summoning ritual and commune with one of the Primal Turtles to gain its blessing.\n\n\n\nThe ritual site can be found south of Uktulut Pier in The Waking Shores, near the remains of a dragon.", ua = "Здійсніть ритуал прикликання та поспілкуйтеся з однією з Первісних Черепах, щоб отримати її благословення.\n\n\n\nМісце ритуалу можна знайти на південь від Пристані Уктулут на Пробуджених Берегах, неподалік від решток дракона." },
    { en = "Casts your Summon Voidwalker spell with no mana requirement.", ua = "Застосовує ваше закляття «Прикликати Блукача Порожнечі» без потреби в мані." },
    { en = "Commands the spirit of Cliffwatcher Longhorn to fight for you for 30 seconds.", ua = "Наказує духу Скелевартового Довгорога битися за вас протягом 30 секунд." },
    { en = "Rapidly deploy the bomb suit to reduce damage taken by $s2% for $d or until $466693s1 damage has been prevented.\n\n\n\nUpon depletion, the bomb suit detonates to deal $466693s2 Fire damage split between nearby enemies.", ua = "Швидко розгортає бомбовий костюм, щоб зменшити отримувану шкоду на $s2% на $d або доки не буде відвернено $466693s1 шкоди.\n\n\n\nПісля вичерпання бомбовий костюм детонує, завдаючи $466693s2 шкоди вогнем, розподіленої між довколишніми ворогами." },
    { en = "Sound the horn, increasing your primary stat by $215956s1 for $215956d.", ua = "Засурміть у ріг, підвищуючи вашу основну характеристику на $215956s1 на $215956d." },
    { en = "Your damaging spells have a chance to increase your Intellect by $256828s1 for $256828d.\n\n\n\n|cFFFFFFFFNorgannon's Command|r\n\nWhen empowered by the Pantheon, you gain $256836u charges of Norgannon's Command for $256836d. Your damaging spells expend a charge to inflict an additional $257241s1 damage to the target, from a random school of magic.", ua = "Ваші закляття, що завдають шкоди, мають шанс підвищити ваш інтелект на $256828s1 на $256828d.\n\n\n\n|cFFFFFFFFНаказ Норганнона|r\n\nКоли вас підсилює Пантеон, ви отримуєте $256836u зарядів Наказу Норганнона на $256836d. Ваші закляття шкоди витрачають заряд, щоб завдати цілі додатково $257241s1 шкоди від випадкової школи магії." },
    { en = "Your healing spells have a chance to instantly heal the most injured nearby party member for $96966s1.", ua = "Ваші зцілювальні закляття мають шанс миттєво зцілити найбільш пораненого довколишнього члена групи на $96966s1." },
    { en = "Your attacks have a chance for the compass to show you a direction, increasing your Critical Strike, Haste, Mastery, or Versatility by $383818s1 for $383818d.", ua = "Ваші атаки мають шанс, що компас укаже вам напрямок, підвищуючи ваш критичний удар, швидкість, майстерність або універсальність на $383818s1 на $383818d." },
    { en = "Grab the weapon from the cache, gaining its benefit.", ua = "Візьміть зброю зі схованки, отримавши її перевагу." },
    { en = "Your heals have a chance to grant you ${$146317m1*20} Versatility for $146317d. Every $146317t2 sec, this effect is reduced by $146317m1 Versatility.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваше зцілення має шанс надати вам ${$146317m1*20} універсальності на $146317d. Кожні $146317t2 сек цей ефект зменшується на $146317m1 універсальності.  (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your spells have a chance to increase your Intellect by $227099s1 for $227099d.", ua = "Ваші закляття мають шанс підвищити ваш інтелект на $227099s1 на $227099d." },
    { en = "Run speed increased slightly.", ua = "Швидкість бігу трохи підвищена." },
    { en = "Your damaging spells and abilities have a chance to throw a large bone at your target, dealing $279791s1 damage.", ua = "Ваші закляття та здібності, що завдають шкоди, мають шанс кинути велику кістку у вашу ціль, завдаючи $279791s1 шкоди." },
    { en = "Summon an Armed Scavenger to assist you for $d.", ua = "Прикликає Озброєного Здобувача, щоб допомагати вам протягом $d." },
    { en = "Increases your Haste by $s1 for $d.", ua = "Підвищує вашу швидкість на $s1 на $d." },
    { en = "Your melee attacks have a chance to grant $122920s1 parry for $122920d.", ua = "Ваші ближні атаки мають шанс надати $122920s1 парирування на $122920d." },
    { en = "Gain a shield that absorbs ${(1+$@versadmg)*$s1} damage for $d. The shield is $s2% more effective if your attacker is a Demon.", ua = "Дає щит, що поглинає ${(1+$@versadmg)*$s1} шкоди протягом $d. Щит на $s2% ефективніший, якщо ваш нападник — демон." },
    { en = "$?a443534[Advance to the $s1 Verses of Inner Radiance, reading as you are attacked.\n\nInner Radiance increases your Critical Strike by $s2 and grants your attacks a chance to inflict an additional $s3 Radiant damage.][Advance to the $s1 Verses of Inner Resilience, reading as you are attacked.\n\nInner Resilience increases your armor by $s4 and grants your attacks a chance to invoke a ward which absorbs $s5 Magic damage.] When finished, sift through the passages to another chapter.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "$?a443534[Переходите до $s1 Віршів Внутрішнього Сяйва, читаючи їх, поки вас атакують.\n\nВнутрішнє Сяйво підвищує ваш критичний удар на $s2 і надає вашим атакам шанс завдати додатково $s3 шкоди світлом.][Переходите до $s1 Віршів Внутрішньої Стійкості, читаючи їх, поки вас атакують.\n\nВнутрішня Стійкість підвищує вашу броню на $s4 і надає вашим атакам шанс закликати оберіг, що поглинає $s5 магічної шкоди.] Завершивши, гортаєте сторінки до іншого розділу.$?(a137048|a137028|a137023|a137010|a212613|a137008)[][\n\n\n\n|cnRED_FONT_COLOR:Лише для танкових спеціалізацій.|r]" },
    { en = "Tear through time and steal power from your future self, gaining $s2 Intellect for $382126d, then losing $s1 Intellect for $384050d.", ua = "Розриваєте час і викрадаєте силу у свого майбутнього «я», отримуючи $s2 інтелекту на $382126d, а потім втрачаючи $s1 інтелекту на $384050d." },
    { en = "Your spells have a chance to grant $90885s1 haste for $90885d.", ua = "Ваші закляття мають шанс дати $90885s1 швидкості на $90885d." },
    { en = "Lure out magmaclaws to attach themselves to you and your surrounding party members granting up to $409269s1 Absorb Shield for $409296d. \n\nThe shield is more effective on allies that are closer to you.", ua = "Виманює магмаклешні, що чіпляються до вас і до членів вашої групи поруч, даючи поглинальний щит до $409269s1 на $409296d. \n\nЩит ефективніший на союзниках, що стоять ближче до вас." },
    { en = "Turns you into a fish, allowing you to breathe underwater and increasing your swim speed.", ua = "Перетворює вас на рибу, дозволяючи дихати під водою та підвищуючи швидкість плавання." },
    { en = "Your spells have a chance to imbue the wax, causing it to form into a blazing candle for $451367d which increases your Versatility by $s1, further increased by $s2 while you remain within its light.", ua = "Ваші закляття мають шанс просочити віск, перетворюючи його на палаючу свічку на $451367d, що підвищує вашу універсальність на $s1, а додатково на $s2, поки ви лишаєтеся в її світлі." },
    { en = "Unleash an $@spellname1250508, increasing your Haste by $s1 for $d.\n\n\n\nYou have a low chance to suffer an $@spellname1255853, reducing one of your other secondary stats by $s2 for $1255853d.", ua = "Вивільняє «$@spellname1250508», підвищуючи вашу швидкість на $s1 на $d.\n\n\n\nВи маєте низький шанс зазнати «$@spellname1255853», що знижує одну з ваших інших вторинних характеристик на $s2 на $1255853d." },
    { en = "Your damaging spells have a chance to hurl a meteor from the Twisting Nether, causing $225764s1 Spellfire damage to your target and nearby enemies.", ua = "Ваші закляття шкоди мають шанс жбурнути метеор із Викривленої Порожнечі, завдаючи $225764s1 шкоди чароплам'ям вашій цілі та ворогам поруч." },
    { en = "Increases the base weapon damage used by Aimed Shot and Multishot by $s1 for $d.", ua = "Підвищує базову шкоду зброї для Прицільного пострілу та Мультипостілу на $s1 протягом $d." },
    { en = "Take what is rightfully yours, gorging on your target's essence to deal ${$<rolemult>*$443128s1} Shadow damage and healing you for $443128s2 over $446067d. Damage and healing increased based on the target's missing health.\n\n\n\nCooldown reduced by $443128s4 sec if this effect kills the target.", ua = "Забираєте те, що по праву ваше, упиваючись сутністю цілі, щоб завдати ${$<rolemult>*$443128s1} шкоди тінню та зцілити вас на $443128s2 протягом $446067d. Шкода і зцілення зростають залежно від нестачі здоров'я цілі.\n\n\n\nЧас відновлення зменшується на $443128s4 сек., якщо цей ефект вбиває ціль." },
    { en = "Your attacks have a chance to deploy a cannon battery at your side for $271194d, dealing ${$s1*5} total Fire damage divided evenly among enemies in a cone in front of it. Deals increased damage when striking multiple targets.", ua = "Ваші атаки мають шанс розгорнути гарматну батарею поруч із вами на $271194d, що завдає загалом ${$s1*5} шкоди вогнем, рівномірно розподіленої між ворогами в конусі перед нею. Завдає підвищеної шкоди, вражаючи кількох цілей." },
    { en = "Your spells have a chance to increase your Haste by $288305s1 and your Speed by $288305s2 for $288305d.", ua = "Ваші закляття мають шанс підвищити вашу швидкість на $288305s1 і ваш темп на $288305s2 протягом $288305d." },
    { en = "When you deal damage you have a chance to gain $102741s1 Dodge for $102741d.", ua = "Коли ви завдаєте шкоди, маєте шанс отримати $102741s1 ухилення на $102741d." },
    { en = "Summons a Fallen Grunt to your side.", ua = "Прикликає до вас Полеглого Піхотинця." },
    { en = "Project a web of healing energy $r yards forward containing $311474s1 to $311481s2 total healing. Allies are healed for up to 30% of the amount stored. The total healing depends on the topmost card in the deck.", ua = "Випускає павутину зцілювальної енергії на $r ярдів уперед, що містить від $311474s1 до $311481s2 загального зцілення. Союзники зцілюються до 30% від збереженої кількості. Загальне зцілення залежить від верхньої карти в колоді." },
    { en = "Taking damage has a chance to create a Nightmare Ichor nearby. Absorbing the Ichor increases your Versatility by $s2 for $222027d.", ua = "Отримання шкоди має шанс створити поруч Кошмарний Іхор. Поглинання Іхору підвищує вашу універсальність на $s2 протягом $222027d." },
    { en = "Imbue your weapon with power, increasing attack power against undead and demons by 150.  Lasts 5 min.", ua = "Наповнює вашу зброю силою, підвищуючи силу атаки проти нежиті й демонів на 150.  Триває 5 хв." },
    { en = "Each time you hit with a melee or ranged attack, you have a chance to gain $67671s1 attack power for $67671d.", ua = "Щоразу, коли ви влучаєте ближньою чи дальньою атакою, маєте шанс отримати $67671s1 сили атаки на $67671d." },
    { en = "A small moonwell appears, blessing you with $s2 Mastery for $d.", ua = "З'являється маленька місячна криниця, благословляючи вас $s2 майстерності протягом $d." },
    { en = "Spew out a Slimey Morsel for every stack of Gluttonous. The Morsels immediately attempt to return to you, each healing you for $334512s1.", ua = "Вивергає Слизький Шматочок за кожен стак Ненажерливості. Шматочки негайно намагаються повернутися до вас, кожен зцілюючи вас на $334512s1." },
    { en = "Increases your movement speed by $s1% for $d.", ua = "Підвищує вашу швидкість пересування на $s1% протягом $d." },
    { en = "Your attacks grant $109717s1 Agility for the next $109717d, stacking up to $109717u times.", ua = "Ваші атаки дають $109717s1 спритності на наступні $109717d, накопичуючись до $109717u разів." },
    { en = "Chance on spell hit to increase your Versatility by $54839s1 for 10 secs.", ua = "Шанс при влучанні закляттям підвищити вашу універсальність на $54839s1 на 10 сек." },
    { en = "Your spells have a chance to grant you $271071s1 Critical Strike for $271071d.", ua = "Ваші закляття мають шанс дати вам $271071s1 критичного удару на $271071d." },
    { en = "Your melee and ranged attacks have a chance to increase your Agility or Strength by $65014s2 for $65014d.", ua = "Ваші ближні та дальні атаки мають шанс підвищити вашу спритність або силу на $65014s2 протягом $65014d." },
    { en = "Your attacks have a chance to launch a volley of 6 Wind Bolts, each dealing $227870s1 Nature damage and slowing your target by $227870s2% for $227870d.", ua = "Ваші атаки мають шанс випустити залп із 6 Вітряних Стріл, кожна з яких завдає $227870s1 шкоди природою та сповільнює вашу ціль на $227870s2% протягом $227870d." },
    { en = "If a target dies while affected by the Ebonsoul Vise, it leaves a Shredded Soul behind which you can collect to gain $355327s2 Critical Strike for $356281d.", ua = "Якщо ціль гине під дією Чорнодушних Лещат, вона лишає по собі Роздерту Душу, яку ви можете зібрати, щоб отримати $355327s2 критичного удару на $356281d." },
    { en = "Your damaging spells have a chance to create a Waterspout at your target's location. The Waterspout erupts after $270910d, dealing $s1 Nature damage split among all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Ваші закляття шкоди мають шанс створити Водяний Стовп у місці розташування вашої цілі. Водяний Стовп вибухає через $270910d, завдаючи $s1 шкоди природою, розподіленої між усіма ворогами поруч. Завдає підвищеної шкоди, вражаючи кількох цілей." },
    { en = "Grants $s1 haste for $d.", ua = "Дає $s1 швидкості на $d." },
    { en = "Increases the healing done by your Heal and Flash Heal by $s1%.", ua = "Підвищує зцілення від ваших Зцілення та Швидкого зцілення на $s1%." },
    { en = "Envelop an ally in ancient protection, absorbing up to $s1 damage. If the protection is fully consumed, the ally gains an ancient resurgence, increasing Versatility by $429272s1 for $429272d.", ua = "Огортає союзника прадавнім захистом, поглинаючи до $s1 шкоди. Якщо захист повністю витрачено, союзник отримує прадавнє відродження, що підвищує універсальність на $429272s1 протягом $429272d." },
    { en = "Your ranged attacks and abilities have a chance to summon a Mailemental that throws Unstable Goods at your target, dealing ${$s1*$<rolemult>} Arcane damage.", ua = "Ваші дальні атаки та вміння мають шанс прикликати Поштовика-елементаля, що жбурляє Нестабільні Товари у вашу ціль, завдаючи ${$s1*$<rolemult>} шкоди тайнощами." },
    { en = "Consume all stacks of Nightwell Energy to gain a shield for $d that absorbs ${$s1*(1+$@versadmg)} damage per Energy consumed.", ua = "Поглинає всі стаки Енергії Нічної Криниці, щоб отримати на $d щит, що поглинає ${$s1*(1+$@versadmg)} шкоди за кожну поглинуту Енергію." },
    { en = "Your harmful spells have a chance to grant $92318s1 spell power for $92318d.", ua = "Ваші шкідливі закляття мають шанс дати $92318s1 сили заклять на $92318d." },
    { en = "Your melee attacks have a chance to grant $122317s1 mastery for $122317d.", ua = "Ваші ближні атаки мають шанс дати $122317s1 майстерності на $122317d." },
    { en = "You feel confident that you can predict movements ahead of time, making you gain [A] leech. Each time you are hit, you have a chance of losing [B] leech until reaching [C] leech. Killing an enemy resets your leech.", ua = "Ви впевнені, що можете завчасно передбачати рухи, тож отримуєте [A] висмоктування. Щоразу, коли вас вражають, маєте шанс втратити [B] висмоктування, поки не сягнете [C] висмоктування. Убивство ворога скидає ваше висмоктування." },
    { en = "Your attacks have a chance to grant $177051s1 Haste for $177051d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $177051s1 швидкості на $177051d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Deals $s1 Fire damage to your current target.", ua = "Завдає $s1 шкоди вогнем вашій поточній цілі." },
    { en = "Call a hound to unleash a smoldering howl, increasing your Critical Strike by $s1 for $d.", ua = "Прикликає гончака, що видає тліючий вий, підвищуючи ваш критичний удар на $s1 на $d." },
    { en = "Strike your weapon against the anvil to strengthen it further, dealing $401303s2 Shadowflame damage to nearby enemies and increasing the on-hit damage by $401303s3% until shortly after leaving combat. Stacks $u times.", ua = "Вдарте зброєю об ковадло, щоб ще більше її зміцнити, завдаючи $401303s2 шкоди тіньовим полум'ям ворогам поблизу та підвищуючи шкоду від влучань на $401303s3% до короткого часу після виходу з бою. Накопичується до $u разів." },
    { en = "Reflects Frost spells back at their caster for $d.  Chance to be resisted when used by players over level $ctrmax2067.", ua = "Відбиває закляття холоду назад у того, хто їх наклав, протягом $d. Існує ймовірність опору, коли застосовується гравцями, вищими за рівень $ctrmax2067." },
    { en = "Damaging spells and abilities have a chance to call a Nightclaw to eviscerate the target, dealing $s1 Physical damage and an additional ${$s2*$423923d} Physical damage over $423923d.", ua = "Шкідливі закляття та здібності мають шанс прикликати Нічного Пазура, щоб випатрати ціль, завдаючи $s1 фізичної шкоди та додатково ${$s2*$423923d} фізичної шкоди протягом $423923d." },
    { en = "Your melee attacks grant $109748s1 Strength for the next $109748d, stacking up to $109748u times.", ua = "Ваші атаки ближнього бою надають $109748s1 сили на наступні $109748d, накопичуючись до $109748u разів." },
    { en = "Your healing spells have a chance to instantly heal the most injured nearby party member for $97136s1.", ua = "Ваші зціляючі закляття мають шанс миттєво зцілити найважче пораненого учасника групи поблизу на $97136s1." },
    { en = "Plunge a twisted blade into your target, dealing $422297s1 Physical damage. After $422297s3 sec, the blade ignites with Shadowflame and returns to you, dealing $422297s2 Shadowflame damage split between the target and all enemies in its path.\n\n\n\nDamage increased per enemy struck, up to 5.", ua = "Встромляє покручене лезо у вашу ціль, завдаючи $422297s1 фізичної шкоди. Через $422297s3 сек. лезо спалахує тіньовим полум'ям і повертається до вас, завдаючи $422297s2 шкоди тіньовим полум'ям, розподіленої між ціллю та всіма ворогами на його шляху.\n\n\n\nШкода зростає за кожного враженого ворога, до 5." },
    { en = "Your ranged attacks and spells have a chance to cause a Solar Collapse at your target's location, dealing $229737s2 Fire damage to nearby enemies after $225746d.", ua = "Ваші дальні атаки та закляття мають шанс спричинити Сонячний Колапс у місці розташування вашої цілі, завдаючи $229737s2 шкоди вогнем ворогам поблизу через $225746d." },
    { en = "Your spells and abilities have a high chance to empower the Eye and grant you $s1 $pri up to $469889u times, decaying rapidly upon leaving combat. While fully empowered, the Eye instead deals ${$s2*$<rolemult>} Fire damage to enemies or heals allies for $s3.", ua = "Ваші чари та здібності з високим шансом наснажують Око, надаючи вам $s1 $pri до $469889u разів; цей ефект швидко згасає після виходу з бою. Коли Око повністю наснажене, воно натомість завдає ворогам ${$s2*$<rolemult>} вогняної шкоди або зцілює союзників на $s3." },
    { en = "Instantly release all health stored on the Scales of Life as a self-heal.", ua = "Миттєво вивільняє все здоров'я, накопичене на Терезах Життя, як самозцілення." },
    { en = "Crusader Strike increases your damage by ${$m1/100}.2% for $185102d, stacking up to $185102u times. This effect is reset if you Crusader Strike a different target.", ua = "Удар Хрестоносця підвищує вашу шкоду на ${$m1/100}.2% на $185102d, накопичуючись до $185102u разів. Цей ефект скидається, якщо ви застосуєте Удар Хрестоносця по іншій цілі." },
    { en = "Your melee and ranged attacks have a chance to grant $122693s1 haste for $122693d.", ua = "Ваші атаки ближнього та дальнього бою мають шанс надати $122693s1 швидкості на $122693d." },
    { en = "Your Shadow Mend, Plea, Power Word: Radiance, and Penance also grant Naaru's Discipline to allies, reducing damage taken by $185103s1% for $185103d.", ua = "Ваші Тіньове Загоєння, Благання, Слово Сили: Сяйво та Покута також надають союзникам Дисципліну Наару, зменшуючи отримувану шкоду на $185103s1% на $185103d." },
    { en = "Call a mechacycle to crash into your target and explode, inflicting $302308s1 Physical damage to them and $302308s2 Fire damage to all nearby enemies.", ua = "Прикликає мехацикл, що врізається у вашу ціль і вибухає, завдаючи їй $302308s1 фізичної шкоди та $302308s2 шкоди вогнем усім ворогам поблизу." },
    { en = "Your melee and ranged attacks have a chance to increase your haste by $64772s1 for $64772d1.", ua = "Ваші атаки ближнього та дальнього бою мають шанс підвищити вашу швидкість на $64772s1 на $64772d1." },
    { en = "Your pet's attacks have a chance to deal an additional 50% damage as Nature, but no more than $s1.", ua = "Атаки вашого улюбленця мають шанс завдати додатково 50% шкоди силами природи, але не більше ніж $s1." },
    { en = "Increase Critical Strike by $191545s1-$191554s1. The amount of Critical Strike depends on the topmost card in the deck.", ua = "Підвищує критичний удар на $191545s1-$191554s1. Величина критичного удару залежить від верхньої карти в колоді." },
    { en = "You gain $184770s1 Stamina per second, stacking up to $184770u times. If you fall below $s2% health, this effect is lost.", ua = "Ви отримуєте $184770s1 витривалості за секунду, накопичуючись до $184770u разів. Якщо ваше здоров'я впаде нижче $s2%, цей ефект втрачається." },
    { en = "Turn your hands to gold, causing your next $U auto-attacks to deal $265953s1 extra Physical damage.", ua = "Перетворює ваші руки на золото, через що ваші наступні $U автоатак завдають $265953s1 додаткової фізичної шкоди." },
    { en = "Your harmful spells and abilities have a chance to drain your target's electrical power, dealing ${$s1*$<rolemult>} Nature damage over $472127d. If the target dies while being drained, you gain $472350s1% movement speed for $472350d.", ua = "Ваші шкідливі закляття та здібності мають шанс висмоктати електричну енергію вашої цілі, завдаючи ${$s1*$<rolemult>} шкоди силами природи протягом $472127d. Якщо ціль гине під час висмоктування, ваша швидкість пересування зростає на $472350s1% на $472350d." },
    { en = "Increases your critical strike by $s1 for 20 sec.", ua = "Підвищує ваш критичний удар на $s1 на 20 сек." },
    { en = "Poison all enemies in an $s2 yard radius around the caster. Victims of the poison suffer $s1 Nature damage every $t1 sec for $d.\n\nEnemies that die while poisoned release a healing wave that restores $391637s1 health to nearby allies.", ua = "Отруює всіх ворогів у радіусі $s2 м навколо завідача. Жертви отрути зазнають $s1 шкоди силами природи кожні $t1 сек. протягом $d.\n\nВороги, що гинуть під дією отрути, вивільняють хвилю зцілення, яка відновлює $391637s1 здоров'я союзникам поблизу." },
    { en = "Your attacks have a chance to summon a Spawn of Serpentrix to assist you.", ua = "Ваші атаки мають шанс прикликати Поріддя Серпентрікса на допомогу вам." },
    { en = "Cause the ground to quake beneath your feet, dealing $s1 Nature damage split between all nearby enemies over $d. Damage increased per target hit.\n\n\n\nWhile quaking, you can sense nearby tectonic weak points. Moving over a weak point will deal an additional $s2 Nature damage to all nearby enemies.", ua = "Змушує землю здригатися під вашими ногами, завдаючи $s1 шкоди силами природи, розподіленої між усіма ворогами поблизу, протягом $d. Шкода зростає за кожну вражену ціль.\n\n\n\nПід час здригання ви відчуваєте тектонічні слабкі місця поблизу. Переміщення через слабке місце завдасть додатково $s2 шкоди силами природи всім ворогам поблизу." },
    { en = "Your attacks and abilities have a chance to grant Phenomenal Power. On reaching $267179u applications you will Unleash Lightning, inflicting $267205s1 Nature damage.", ua = "Ваші атаки та здібності мають шанс надати Феноменальну Силу. Досягнувши $267179u накопичень, ви Вивільните Блискавку, завдаючи $267205s1 шкоди силами природи." },
    { en = "Your spell critical strikes have a chance to restore $60538s1 mana.", ua = "Ваші критичні удари закляттями мають шанс відновити $60538s1 мани." },
    { en = "Your spells have a chance to grant $90989s1 spell power for $90989d.", ua = "Ваші закляття мають шанс надати $90989s1 сили заклять на $90989d." },
    { en = "When you deal damage you have a chance to gain $116721s1 mastery for $116721d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $116721s1 майстерності на $116721d." },
    { en = "Your damaging and healing abilities have a chance to grant you Storm's Eye, increasing your highest secondary stat by $s2 for 10 sec.", ua = "Ваші здібності завдавання шкоди та зцілення мають шанс надати вам Око Бурі, підвищуючи вашу найвищу вторинну характеристику на $s2 на 10 сек." },
    { en = "Strengthen your resolve, increasing Versatility by $s1 for $d.", ua = "Зміцнює вашу рішучість, підвищуючи універсальність на $s1 на $d." },
    { en = "When your spells deal damage you have a chance to gain $146218s1 critical strike for $146218d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Коли ваші закляття завдають шкоди, ви маєте шанс отримати $146218s1 критичного удару на $146218d. ($h% шансу, ${$proccooldown} сек. перезарядки)" },
    { en = "Reduces the base mana cost of  Flight Form and Swift Flight Form by $s1.", ua = "Зменшує базову вартість мани Подоби Польоту та Подоби Швидкого Польоту на $s1." },
    { en = "Every $t sec, Zap your target and $s5 nearby enemy for ${$s1*$<rolemult>} Nature damage.\n\n\n\nCasting $s3 spells Turbo-Charges you for $1220413d, doubling the frequency of your Zaps and upgrading them into Giga-Zaps, dealing ${$s1*$s4*$<rolemult>} Nature Damage instead.", ua = "Кожні $t сек. вражає вашу ціль і $s5 ворога поблизу розрядом на ${$s1*$<rolemult>} шкоди силами природи.\n\n\n\nЗастосування $s3 заклять Турбозаряджає вас на $1220413d, подвоюючи частоту ваших розрядів і покращуючи їх до Гігарозрядів, які натомість завдають ${$s1*$s4*$<rolemult>} шкоди силами природи." },
    { en = "Apply a thick coating of reinforced wax to your armor, granting you $s1 damage reduction.", ua = "Наносить товстий шар укріпленого воску на ваш обладунок, надаючи вам $s1 зменшення шкоди." },
    { en = "Your attacks have a chance to grant you a Spark of Zandalar.  Once you have accumulated $138958u Sparks, you will transform into a Zandalari Warrior and gain $138960s2 Strength for $138960d. (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати вам Іскру Зандалара. Щойно ви накопичите $138958u Іскор, ви перетворитеся на Воїна Зандаларі та отримаєте $138960s2 сили на $138960d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Each spell cast within 20 seconds will grant a stacking bonus of $65000s1 Versatility Expires after 20 seconds.  Abilities with no mana cost will not trigger this trinket.", ua = "Кожне закляття, застосоване протягом 20 секунд, надає накопичувальний бонус $65000s1 універсальності. Спливає через 20 секунд. Здібності без вартості мани не активують цей брязкальце." },
    { en = "Gives the wearer a 10% chance of being able to resurrect with $23700s1% health and mana.", ua = "Дає власнику 10% шанс воскреснути з $23700s1% здоров'я та мани." },
    { en = "Summons a Goblin nurse that will perform a physical.", ua = "Прикликає гобліна-санітара, який проведе медичний огляд." },
    { en = "Look through the lens and randomly scale up or down, gaining $1214603s1 Critical Strike or Haste for $1213433d1.", ua = "Погляньте крізь лінзу й випадково збільшіться чи зменшіться, отримавши $1214603s1 критичного удару або швидкості на $1213433d1." },
    { en = "Your spells and abilities have a chance to Arcanocrystalize the energies around you, granting a fluctuating secondary stat for $382963d.", ua = "Ваші заклинання та здібності мають шанс арканокристалізувати енергії довкола вас, надаючи мінливу вторинну характеристику на $382963d." },
    { en = "Your spells have a chance to grant $90992s1 spell power for $90992d.", ua = "Ваші заклинання мають шанс надати $90992s1 сили заклять на $90992d." },
    { en = "The Perfect Dreamgrove Blossom increases your movement speed by $s1%.\n\n\n\nOnly usable on the Broken Isles and Argus.", ua = "Досконалий Цвіт Снолісся збільшує вашу швидкість пересування на $s1%.\n\n\n\nМожна використовувати лише на Зламаних Островах та Аргусі." },
    { en = "Your helpful spells and abilities have a high chance to create a Burning Ember on an ally. The ember flares up after $387028d, cauterizing wounds to heal for $s1 and expelling $s2 Fire damage split between nearby enemies.", ua = "Ваші допоміжні заклинання та здібності мають високий шанс створити Палаючий Жар на союзникові. Через $387028d жар спалахує, припікаючи рани й зцілюючи на $s1 та вивільняючи $s2 шкоди вогнем, розподіленої між ворогами поблизу." },
    { en = "Your attacks have a chance to deal $s1 additional physical damage.", ua = "Ваші атаки мають шанс завдати $s1 додаткової фізичної шкоди." },
    { en = "Heal your target for $s1.", ua = "Зцілює вашу ціль на $s1." },
    { en = "Summons $?s19574[${$m1/2}][$m1] Mirror Images to attack your target and nearby enemies for $184271d.", ua = "Прикликає $?s19574[${$m1/2}][$m1] Дзеркальних відображень, які атакують вашу ціль і ворогів поблизу протягом $184271d." },
    { en = "Your melee attacks have a chance to rake all enemies in front of you for $225721s1 Arcane damage.", ua = "Ваші атаки ближнього бою мають шанс розшматувати всіх ворогів перед вами, завдаючи $225721s1 шкоди тайнощами." },
    { en = "Your direct healing spells have a chance to place a heal over time on your target, healing $38324o1 over $38324d.", ua = "Ваші прямі зцілювальні заклинання мають шанс накласти на ціль періодичне зцілення, відновлюючи $38324o1 здоров'я протягом $38324d." },
    { en = "Gain an absorb shield for $s3% of your maximum health for $235169d. When the shield is consumed or expires, $235169s2% of the damage absorbed is dealt to nearby enemies, split evenly.", ua = "Отримайте поглинальний щит на $s3% вашого максимального здоров'я на $235169d. Коли щит витрачено або він спливає, $235169s2% поглиненої шкоди завдається ворогам поблизу, рівномірно розподіленої." },
    { en = "Falling below $s1% health activates the defense matrix for $386001d, which has a high chance to react to your damage taken, counterattacking for $s2 Fire damage and absorbing the next $s3 damage you take.\n\n\n\nThis may only occur once every $386092d.", ua = "Падіння нижче $s1% здоров'я активує захисну матрицю на $386001d, яка має високий шанс зреагувати на отриману вами шкоду, контратакуючи на $s2 шкоди вогнем і поглинаючи наступні $s3 шкоди, яку ви отримаєте.\n\n\n\nЦе може ставатися лише раз на $386092d." },
    { en = "Launch a random number of deadly grenades at your enemies, each dealing ${$1214939s1*$<rolemult>} Fire damage split between nearby targets caught in the blast.", ua = "Запускає випадкову кількість смертоносних гранат у ваших ворогів, кожна завдає ${$1214939s1*$<rolemult>} шкоди вогнем, розподіленої між ближніми цілями, що потрапили під вибух." },
    { en = "Your auto attacks have a $s1% chance to reset the cooldown of Colossus Smash.", ua = "Ваші автоатаки мають $s1% шанс скинути час відновлення Колосального Удару." },
    { en = "When you deal damage you have a chance to gain $102439s1 Agility for $102439d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $102439s1 спритності на $102439d." },
    { en = "Your melee and ranged attacks have a chance to chastise your enemy, dealing $55748s1 Holy damage.", ua = "Ваші атаки ближнього та далекого бою мають шанс покарати ворога, завдаючи $55748s1 шкоди святістю." },
    { en = "Your melee and ranged attacks have a chance to increase your Haste by $60302s1 for $60302d.", ua = "Ваші атаки ближнього та далекого бою мають шанс збільшити вашу швидкість на $60302s1 на $60302d." },
    { en = "When your spells deal critical damage, you have a chance to gain $139133s1 Intellect for $139133d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Коли ваші заклинання завдають критичної шкоди, ви маєте шанс отримати $139133s1 інтелекту на $139133d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your healing spells and abilities have a chance to cause the vial to maliciously launch itself onto your lowest health ally, healing them for $s1.", ua = "Ваші зцілювальні заклинання та здібності мають шанс змусити флакон підступно кинутися на вашого союзника з найнижчим здоров'ям, зцілюючи його на $s1." },
    { en = "Reduces the threat from your harmful critical strikes.", ua = "Зменшує загрозу від ваших шкідливих критичних ударів." },
    { en = "Your attacks have a chance to drop an anchor on your target, dealing $276187s1-$276194s1 Physical damage. The damage of the anchor depends on the topmost card in the deck.", ua = "Ваші атаки мають шанс скинути якір на вашу ціль, завдаючи $276187s1-$276194s1 фізичної шкоди. Шкода якоря залежить від верхньої карти в колоді." },
    { en = "Your spells have a chance to bring the candle to life, summoning a waxen ally to light up your enemies.", ua = "Ваші заклинання мають шанс оживити свічку, прикликаючи воскового союзника, щоб освітити ваших ворогів." },
    { en = "Each time you are struck by a melee attack, you have a $h% chance to gain $71575s1 stamina for the next $71575d, stacking up to $71575u times.", ua = "Щоразу, коли по вас влучає атака ближнього бою, ви маєте $h% шанс отримати $71575s1 витривалості на наступні $71575d, накопичуючись до $71575u разів." },
    { en = "Your spells and abilities have a chance to increase your primary stat by $273974s1 for $273974d.", ua = "Ваші заклинання та здібності мають шанс збільшити вашу основну характеристику на $273974s1 на $273974d." },
    { en = "Your melee swings have a chance to deal $s1 additional Fire damage. Your harmful melee abilities have a chance to make the Fragment erupt, dealing $s2 Fire damage split between all nearby enemies. The Fragment also has a chance to react to your damage taken, counterattacking for $s3 Fire damage.", ua = "Ваші замахи в ближньому бою мають шанс завдати $s1 додаткової шкоди вогнем. Ваші шкідливі здібності ближнього бою мають шанс змусити Уламок вивергнутися, завдаючи $s2 шкоди вогнем, розподіленої між усіма ворогами поблизу. Уламок також має шанс зреагувати на отриману вами шкоду, контратакуючи на $s3 шкоди вогнем." },
    { en = "Enshroud a friendly target in darkness for $d, absorbing the next ${$s1*(1+$@versadmg)} damage or healing taken.", ua = "Огортає дружню ціль темрявою на $d, поглинаючи наступні ${$s1*(1+$@versadmg)} шкоди чи отриманого зцілення." },
    { en = "Place an abyssal trap at your feet. When an enemy comes within $440771s2 yards, a giant water bubble is created for $441229d. All enemies within the bubble take ${$<rolemult>*$440771s1} Frost damage every second.\n\n\n\nThe trap will exist for $d before being automatically disarmed.", ua = "Розставте безодневу пастку біля своїх ніг. Коли ворог наближається на $440771s2 ярдів, створюється велетенська водяна бульбашка на $441229d. Усі вороги всередині бульбашки отримують ${$<rolemult>*$440771s1} шкоди морозом щосекунди.\n\n\n\nПастка існуватиме $d, після чого автоматично знешкоджується." },
    { en = "Your attacks have a ${$m1/100}.2% chance to Cleave, dealing the same damage to up to 5 other nearby targets. Reduced effectiveness at level $ctrmin2066 and higher.", ua = "Ваші атаки мають ${$m1/100}.2% шансу завдати «Розсікання», завдаючи такої самої шкоди до 5 іншим найближчим цілям. Знижена ефективність на рівні $ctrmin2066 та вище." },
    { en = "Your spells and abilities have a chance to increase your Critical Strike, Haste, or Mastery by $s2 for $224170d, whichever is highest.", ua = "Ваші заклинання та здібності мають шанс збільшити ваш критичний удар, швидкість або майстерність на $s2 на $224170d, залежно від того, що найвище." },
    { en = "Your attacks and abilities have a chance to roll the loaded dice, gaining a random combination of Mastery, Haste, and Critical Strike for $267325d.", ua = "Ваші атаки та здібності мають шанс кинути краплені кості, отримавши випадкову комбінацію майстерності, швидкості та критичного удару на $267325d." },
    { en = "Your ranged attacks and spells have a chance to summon a Volatile Ichor, which creeps towards the target and explodes on contact, dealing $s1 Nature damage within $222197A1 yards.", ua = "Ваші атаки далекого бою та заклинання мають шанс прикликати Летку Сукровицю, яка повзе до цілі й вибухає від дотику, завдаючи $s1 шкоди природою в межах $222197A1 ярдів." },
    { en = "Chance on critical hit to increase your attack power by $42084s1 for $42084d.", ua = "Шанс при критичному ударі збільшити вашу силу атаки на $42084s1 на $42084d." },
    { en = "Your spells grant $90854s1 spell power for $90854d, stacking up to $90854u times.", ua = "Ваші заклинання надають $90854s1 сили заклять на $90854d, накопичуючись до $90854u разів." },
    { en = "When you deal damage you have a chance to gain $109789s1 haste for $109789d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $109789s1 швидкості на $109789d." },
    { en = "Each time your spells heal a target you have a chance to cause another nearby friendly target to be instantly healed for $71641s1.", ua = "Щоразу, коли ваші заклинання зцілюють ціль, ви маєте шанс зробити так, щоб інша дружня ціль поблизу миттєво зцілилася на $71641s1." },
    { en = "For every $s1 mana spent, store ${$s2*(1+$@versadmg)} healing within the mirror, up to ${$s3*(1+$@versadmg)} for $344244d.", ua = "За кожні витрачені $s1 мани накопичує в дзеркалі ${$s2*(1+$@versadmg)} зцілення, до ${$s3*(1+$@versadmg)} протягом $344244d." },
    { en = "Your healing spells have a chance to grant $91147s1 Versatility for $91147d.", ua = "Ваші зцілювальні закляття мають шанс надати $91147s1 універсальності на $91147d." },
    { en = "Unleash a wave of $s3 Tide Elementals that crash into your target, each exploding for $288046s1 Frost damage split among all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Випускає хвилю з $s3 Елементалів припливу, що обрушуються на ціль, і кожен вибухає, завдаючи $288046s1 шкоди від холоду, розподіленої між усіма ворогами поблизу. Завдає підвищеної шкоди, влучаючи в кількох цілей." },
    { en = "Your attacks have a chance to call a centaur to aid you, increasing your party's Speed by $s1 for $392908d. The centaur charges forward, trampling enemies in a line for $385533s2 Physical damage split between them.", ua = "Ваші атаки мають шанс прикликати кентавра на допомогу, підвищуючи швидкість вашої групи на $s1 протягом $392908d. Кентавр мчить уперед, затоптуючи ворогів у лінії і завдаючи $385533s2 фізичної шкоди, розподіленої між ними." },
    { en = "Your melee attacks have a chance to grant $120179s1 parry for $120179d.", ua = "Ваші атаки ближнього бою мають шанс надати $120179s1 парирування на $120179d." },
    { en = "Each time your attacks hit, you have a chance to gain $126646s1 armor for $126646d.  ($h% chance, ${$proccooldown} sec cooldown)", ua = "Щоразу, коли ваші атаки влучають, ви маєте шанс отримати $126646s1 броні на $126646d. ($h% шансу, ${$proccooldown} сек відновлення)" },
    { en = "Your healing spells have a chance to grant you Blessing of Eternal Kings for $414873d, allowing your heals to shield the target up to ten times for $s1 damage. The shield lasts for $414875d.", ua = "Ваші зцілювальні закляття мають шанс надати вам Благословення Вічних Королів на $414873d, дозволяючи вашим зціленням огортати ціль щитом до десяти разів на $s1 шкоди. Щит триває $414875d." },
    { en = "Your damaging spells have a chance to summon a Volatile Shadeweaver which creeps towards the target and explodes on contact, dealing $s1 Shadow damage split among all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Ваші ушкоджувальні закляття мають шанс прикликати Нестійкого Тіньоткача, що повзе до цілі й вибухає при контакті, завдаючи $s1 шкоди від темряви, розподіленої між усіма ворогами поблизу. Завдає підвищеної шкоди, влучаючи в кількох цілей." },
    { en = "Creates a new, permanent Perpetual Purple Firework item in your inventory while consuming this trinket.", ua = "Створює у вашому інвентарі новий, постійний предмет Вічний Фіолетовий Феєрверк, споживаючи цей дрібничку." },
    { en = "Your abilities have a chance to awaken the powers of the races of Northrend, temporarily transforming you and increasing your combat capabilities for $71491d.", ua = "Ваші здібності мають шанс пробудити сили народів Нордскола, тимчасово перетворюючи вас і підвищуючи ваші бойові можливості на $71491d." },
    { en = "When you take damage, you have a chance to heal for $300814s2 health and gain $300814s1 Armor for $300814d, stacking up to ${$300814s1*$300814u} Armor.", ua = "Коли ви зазнаєте шкоди, ви маєте шанс зцілитися на $300814s2 здоров'я й отримати $300814s1 броні на $300814d, накопичуючи до ${$300814s1*$300814u} броні." },
    { en = "Your attacks have a chance to grant $176939s1 Mastery for $176939d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176939s1 майстерності на $176939d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Increases the duration of Tiger's Fury and Berserk by $s1%.", ua = "Збільшує тривалість Лютості тигра та Берсерка на $s1%." },
    { en = "Your harmful spells have a chance to grant Wushoolay's Lightning, granting $138786s1 Intellect every $138786t1 sec for $138786d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші шкідливі закляття мають шанс надати Блискавку Вушулея, даючи $138786s1 інтелекту кожні $138786t1 сек протягом $138786d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your healing spell critical strikes have a chance to grant $91139s1 Versatility for $91139d.", ua = "Критичні удари ваших зцілювальних заклять мають шанс надати $91139s1 універсальності на $91139d." },
    { en = "Your ranged attacks and spells have a chance to launch a Vortex Bomb at your target, dealing $214052s1 Arcane damage to them and nearby enemies.", ua = "Ваші дальнобійні атаки та закляття мають шанс випустити Вихрову Бомбу в ціль, завдаючи $214052s1 шкоди від магії їй і ворогам поблизу." },
    { en = "Your melee and ranged attacks have a chance to grant $122318s1 mastery for $122318d.", ua = "Ваші атаки ближнього та дального бою мають шанс надати $122318s1 майстерності на $122318d." },
    { en = "Your melee attacks grant $107966s1 Strength for the next $107966d, stacking up to $107966u times.", ua = "Ваші атаки ближнього бою надають $107966s1 сили на наступні $107966d, накопичуючись до $107966u разів." },
    { en = "Your ranged and melee attacks have a chance to increase your Haste by $221796s1 for $221796d. This effect occurs more often against targets at low health.", ua = "Ваші атаки дального та ближнього бою мають шанс підвищити вашу швидкість на $221796s1 протягом $221796d. Цей ефект частіше спрацьовує проти цілей з низьким здоров'ям." },
    { en = "Your attacks have a chance to trigger Wrath of the Darkspear for $146184d.  While Wrath of the Darkspear is active, every $146184t1 sec you gain $146184s1 Intellect, stacking up to $146202u times.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс викликати Гнів Темного Списа на $146184d. Поки Гнів Темного Списа активний, кожні $146184t1 сек ви отримуєте $146184s1 інтелекту, накопичуючи до $146202u разів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks cause the target to burn for $184256o1 Fire damage over $184256d. Successive attacks do not refresh Fel Burn's duration, but instead add an additional stack of Fel Burn.", ua = "Ваші атаки змушують ціль горіти, завдаючи $184256o1 шкоди від вогню протягом $184256d. Наступні атаки не оновлюють тривалість Скверного Опіку, а натомість додають ще один стак Скверного Опіку." },
    { en = "Designate another player to bond with, becoming their Guardian for $394457d.\n\n\n\nWhile bonded, you and your ally gain ${$382280s1*(1-$382280s3/100)} Versatility and restore ${$382280s2*(1-$382280s4/100)} health per second. If you are within 15 yards of one another, these bonuses are increased. $?(a137012|a137024|a137031|a137032|a137029|a137039|a356810)[][\n\n\n\n|CFF808080Valid only for healer specializations.|R]", ua = "Оберіть іншого гравця, щоб поріднитися з ним, ставши його Вартовим на $394457d.\n\n\n\nДоки триває зв'язок, ви та ваш союзник отримуєте ${$382280s1*(1-$382280s3/100)} універсальності й відновлюєте ${$382280s2*(1-$382280s4/100)} здоров'я щосекунди. Якщо ви перебуваєте за 15 ярдів одне від одного, ці бонуси посилюються. $?(a137012|a137024|a137031|a137032|a137029|a137039|a356810)[][\n\n\n\n|CFF808080Лише для цілительських спеціалізацій.|R]" },
    { en = "Your damaging melee abilities apply Everchill, dealing $289526s1 Frost damage every $289526t1 sec and reducing movement speed by $289526s2%, stacking up to $289526u times. Lasts $289526d.", ua = "Ваші ушкоджувальні здібності ближнього бою накладають Вічну Мерзлоту, завдаючи $289526s1 шкоди від холоду кожні $289526t1 сек і знижуючи швидкість пересування на $289526s2%, накопичуючи до $289526u разів. Триває $289526d." },
    { en = "Ignite the Solar Core within you for $d, forming a radiant shield that absorbs $s2% of incoming damage, up to $1257989s1. Gain up to $1257989s3 Versatility for $1257988d if the shield expires, based on its remaining power.", ua = "Запалює Сонячне Ядро всередині вас на $d, формуючи осяйний щит, що поглинає $s2% вхідної шкоди, до $1257989s1. Якщо щит спливає, надає до $1257989s3 універсальності на $1257988d залежно від залишкової потужності." },
    { en = "Calls forth a Netherwing Ally to fight at your side.", ua = "Прикликає Союзника Нетеркрила, щоб він бився поруч із вами." },
    { en = "Your melee and ranged attacks have a chance to increase your Critical Strike by $244067s1 for $244067d.", ua = "Ваші атаки ближнього та дального бою мають шанс підвищити ваш критичний удар на $244067s1 протягом $244067d." },
    { en = "Drink from the vial and let the toxins course through your veins increasing all secondary stats by $s1 for $d.\n\n\n\nJump to administer yourself the antidote to end the effect.\n\n\n\nIf the Antidote is not administered before the end of the effect you will be stunned for $440235d.", ua = "Випийте з флакона й дозвольте токсинам розтектися вашими венами, підвищуючи всі другорядні характеристики на $s1 протягом $d.\n\n\n\nСтрибніть, щоб ввести собі протиотруту й завершити ефект.\n\n\n\nЯкщо протиотруту не введено до завершення ефекту, вас буде оглушено на $440235d." },
    { en = "Grants $256718s1 additional Armor to a nearby tank-specialized ally bearing the Eye of F'harg.", ua = "Надає $256718s1 додаткової броні союзнику-танку поблизу, що носить Око Ф'харга." },
    { en = "Gain $s1 Leech for $d.", ua = "Надає $s1 висмоктування на $d." },
    { en = "Increase your Mastery by $s1 for $d. Spending $?a137047[Rage]?a137005[Runic Power]?a137027[Holy Power]?a137028[charges of Shield of the Righteous][resources] extends the duration of this effect, or if it is not active, reduces its cooldown.", ua = "Підвищує вашу Майстерність на $s1 протягом $d. Витрачання $?a137047[Люті]?a137005[Рунічної сили]?a137027[Священної сили]?a137028[зарядів Щита праведника][ресурсів] подовжує тривалість цього ефекту, а якщо він неактивний — зменшує час його відновлення." },
    { en = "Increases spell power against Undead and Demons by $s1.  It also allows the acquisition of Scourgestones on behalf of the Argent Dawn.", ua = "Підвищує силу заклять проти Нежиті та Демонів на $s1. Також дозволяє збирати Камені Погибелі від імені Багряного Світанку." },
    { en = "Your attacks have a chance to grant $165833s1 Versatility for $165833d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $165833s1 універсальності на $165833d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Unseal the urn causing the void within to pour out and engulf you for $d1, increasing all secondary stats by $s1.\n\n\n\nAs the void dissipates, you become horrified for $1259443d1. Killing an enemy while engulfed prevents this effect from occurring.", ua = "Розпечатайте урну, через що Порожнеча всередині виливається й огортає вас на $d1, підвищуючи всі другорядні характеристики на $s1.\n\n\n\nКоли Порожнеча розсіюється, вас охоплює жах на $1259443d1. Убивство ворога, поки вас огортає Порожнеча, запобігає цьому ефекту." },
    { en = "Each time you strike an enemy with a melee attack, you gain $67746s1 attack power.  Stacks up to $67746u times.  Entire effect lasts $d.", ua = "Щоразу, коли ви вражаєте ворога атакою ближнього бою, ви отримуєте $67746s1 сили атаки. Накопичується до $67746u разів. Увесь ефект триває $d." },
    { en = "When you deal damage you have a chance to gain $120177s1 mastery for $120177d.", ua = "Коли ви завдаєте шкоди, ви маєте шанс отримати $120177s1 майстерності на $120177d." },
    { en = "The cooldown of your Covenant Signature Ability is reduced by $s1%.", ua = "Час відновлення вашої Сигнатурної Здібності Ковенанту зменшено на $s1%." },
    { en = "Your harmful abilities draw focused void through the prism to deal ${$s1*$<rolemult>} Cosmic damage split between your target and nearby enemies. Damage increased by $s3% per enemy struck, up to ${$s3*$s4}%. This effect may occur every $proccooldown sec and accumulates Latent Power within the prism, up to $1239675u times.", ua = "Ваші шкідливі здібності витягують крізь призму зосереджену Порожнечу, завдаючи ${$s1*$<rolemult>} космічної шкоди, розподіленої між вашою ціллю та ворогами поруч. Шкода збільшується на $s3% за кожного враженого ворога, до ${$s3*$s4}%. Цей ефект може спрацьовувати раз на $proccooldown сек і накопичує приховану силу в призмі, до $1239675u разів." },
    { en = "Your spells and abilities have a low chance to create a Temporal Pocket near your location for $396190d. Standing within the pocket grants you $s2 Haste and $s3 rapidly decaying movement speed.", ua = "Ваші закляття та здібності мають низький шанс створити Часову Кишеню поблизу вашого розташування на $396190d. Перебування в кишені надає вам $s2 швидкості та $s3 швидкості пересування, що швидко спадає." },
    { en = "Your melee attacks have a chance to grant an Echo of Gorshalach. On reaching $253327u applications, you lash out with a devastating combination of attacks, critically striking enemies in a 15 yd cone in front of you for ${$253329s1+$255673s1} Fire damage.", ua = "Ваші ближні атаки мають шанс надати Відлуння Ґоршалаха. Досягнувши $253327u зарядів, ви завдаєте нищівної серії ударів, критично вражаючи ворогів у конусі завдовжки 15 м перед вами на ${$253329s1+$255673s1} шкоди вогнем." },
    { en = "Your melee and ranged attacks grant $469769s1 Strength. Lasts $469769d, stacking up to $469769u times.", ua = "Ваші ближні та далекобійні атаки надають $469769s1 сили. Триває $469769d, накопичується до $469769u разів." },
    { en = "Melee attacks which reduce you below $s1% health cause you to gain a protective shield which absorbs $97129s1 damage for $97129d.  Cannot occur more than once every 1 min.", ua = "Ближні атаки, що знижують ваше здоров'я нижче $s1%, надають вам захисний щит, який поглинає $97129s1 шкоди протягом $97129d. Може спрацьовувати не частіше ніж раз на 1 хв." },
    { en = "When your attacks hit you have a chance to gain $235018s1 Critical Strike for $235018d.", ua = "Коли ваші атаки влучають, ви маєте шанс отримати $235018s1 критичного удару на $235018d." },
    { en = "Increases parry by $s1 for $d1.", ua = "Підвищує парирування на $s1 на $d1." },
    { en = "Taking damage has a chance to siphon chaos energies from the Twisting Nether granting you $s1  Leech for $1246543d1. Dropping below $s3% health will unleash the Harvester immediately granting you $s2 Leech for $1246545d. Can only occur every 120 sec.", ua = "Отримання шкоди має шанс висмоктати енергії хаосу з Викривленої Порожнечі, надаючи вам $s1 кровопивства на $1246543d1. Падіння нижче $s3% здоров'я негайно вивільнить Жнеця, надаючи вам $s2 кровопивства на $1246545d. Може спрацьовувати лише раз на 120 с." },
    { en = "Chance on melee or ranged hit to enter a Battle Trance, during which your melee or ranged attacks will each grant $45041s1 attack power, stacking up to 10 times.  Expires after $45040d.", ua = "Шанс під час ближнього чи далекобійного влучання увійти в Бойовий Транс, протягом якого кожна ваша ближня або далекобійна атака надає $45041s1 сили атаки, накопичуючись до 10 разів. Спливає через $45040d." },
    { en = "Your heals each cost $37878s1 less mana for the next $37878d.", ua = "Кожне ваше зцілення коштує на $37878s1 менше мани протягом наступних $37878d." },
    { en = "Summon your loyal raccoon friend.", ua = "Призиває вашого вірного друга-єнота." },
    { en = "The antenna has a chance to detect and draw ambient arcane energy towards you, granting $s1 Critical Strike for $1239641d. Multiple applications may overlap.", ua = "Антена має шанс виявити та притягнути до вас навколишню чародійну енергію, надаючи $s1 критичного удару на $1239641d. Кілька застосувань можуть накладатися." },
    { en = "Taking damage as well as dealing harmful spells and abilities has a chance to grant you a $s1 absorb shield for $391952d and $s2 Speed while the shield lasts.", ua = "Отримання шкоди, а також застосування шкідливих заклять і здібностей мають шанс надати вам щит поглинання на $s1 протягом $391952d і $s2 швидкості, поки діє щит." },
    { en = "Summon the artifact-bound Quilen.", ua = "Призиває прив'язаного до артефакту Цілена." },
    { en = "Your healing spells and abilities have a high chance to grant you Void Suffusion for $1258534d, increasing your Intellect by $s1 plus an additional ${$s1*$s2/100} Intellect for every 1% health the target was missing. Multiple Suffusions may overlap.", ua = "Ваші зцілювальні закляття та здібності мають високий шанс надати вам Просякання Порожнечею на $1258534d, підвищуючи ваш інтелект на $s1 плюс додатково ${$s1*$s2/100} інтелекту за кожен 1% здоров'я, якого бракувало цілі. Кілька Просякань можуть накладатися." },
    { en = "Your melee attacks have a chance to trigger Hungering Blows, granting $183941s1 Strength for $183941d, and gaining one stack on each additional attack, up to $183941u stacks.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші ближні атаки мають шанс спричинити Голодні Удари, надаючи $183941s1 сили на $183941d і додаючи один заряд за кожну наступну атаку, до $183941u зарядів. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your attacks have a chance to grant $176943s1 Haste for $176943d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $176943s1 швидкості на $176943d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Your melee and ranged attacks have a chance to grant $96977s1 critical strike, haste, or mastery for 30 sec, whichever is currently highest.", ua = "Ваші ближні та далекобійні атаки мають шанс надати $96977s1 критичного удару, швидкості або майстерності на 30 с, залежно від того, що зараз найвище." },
    { en = "Launch a vortex of destruction that seeks your current enemy. When it reaches the target, it explodes, dealing a critical strike to all enemies within $235999A1 yds for ${$235999s1*$s2/100} Fire damage.", ua = "Запускає вихор руйнування, що переслідує вашого поточного ворога. Досягнувши цілі, він вибухає, завдаючи критичного удару всім ворогам у радіусі $235999A1 м на ${$235999s1*$s2/100} шкоди вогнем." },
    { en = "Your direct healing spells have a chance to place a heal over time on your target, healing $60530o1 over $60530d.", ua = "Ваші прямі зцілювальні закляття мають шанс накласти на ціль періодичне зцілення, відновлюючи $60530o1 протягом $60530d." },
    { en = "Your abilities have a chance to grant you $s4 primary stat for $d.", ua = "Ваші здібності мають шанс надати вам $s4 основної характеристики на $d." },
    { en = "Increases Speed by $s1 for $d1.", ua = "Підвищує швидкість на $s1 на $d1." },
    { en = "Your attacks have a chance to grant $148906s1 Intellect for $148906d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші атаки мають шанс надати $148906s1 інтелекту на $148906d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "Fling the deadly tip of the sword towards the target enemy dealing $s1 damage.", ua = "Метає смертоносне вістря меча у ворожу ціль, завдаючи $s1 шкоди." },
    { en = "Your spells have a chance to grant $92166s1 mastery for $92166d.", ua = "Ваші закляття мають шанс надати $92166s1 майстерності на $92166d." },
    { en = "Reduces damage from each attack by $s2, up to a total of ${$s1*(1+$@versadmg)} damage absorbed.  Lasts $d.", ua = "Зменшує шкоду від кожної атаки на $s2, поглинаючи загалом до ${$s1*(1+$@versadmg)} шкоди. Триває $d." },
    { en = "Shatter all shards, dealing up to $388948s1 Frost damage split between nearby enemies and decreasing their movement speed by up to $s2% per stack for $s3 sec.", ua = "Розбиває всі осколки, завдаючи до $388948s1 шкоди морозом, розподіленої між ворогами поблизу, і знижуючи їхню швидкість пересування на до $s2% за заряд протягом $s3 с." },
    { en = "Hurl a massive hook toward your target, cleaving through enemies in its path and dealing ${$<rolemult>*$1255379s2} Physical damage to each. When the hook crashes into the target, it inflicts ${$<rolemult>*$1255379s1} Physical damage split among enemies within $1255298a1 yards.", ua = "Метає у ціль масивний гак, що пронизує ворогів на своєму шляху, завдаючи кожному ${$<rolemult>*$1255379s2} фізичної шкоди. Коли гак врізається в ціль, він завдає ${$<rolemult>*$1255379s1} фізичної шкоди, розподіленої між ворогами в радіусі $1255298a1 м." },
    { en = "When you parry, dodge, or block an attack, gain $92205s1 dodge for $92205d.  Cannot occur more often than once every 60 sec.", ua = "Коли ви парируєте, ухиляєтеся або блокуєте атаку, ви отримуєте $92205s1 ухилення на $92205d. Може спрацьовувати не частіше ніж раз на 60 с." },
    { en = "Your melee abilities grant you a stack of Blazing Soul, up to $s2. Movement removes all stacks, granting you up to ${$s1*$s2} movement speed for $389178d.", ua = "Ваші ближні здібності надають вам заряд Палаючої Душі, до $s2. Пересування знімає всі заряди, надаючи вам до ${$s1*$s2} швидкості пересування на $389178d." },
    { en = "Awaken the Bloodthorn Roots, erupting around your target and inflicting ${$1259351s1*$<rolemult>} Nature damage split among nearby enemies. You absorb their essence, gaining $1259351s2 Mastery for $1259352d.", ua = "Пробуджує Кореневища Кровошипу, що вибухають навколо вашої цілі та завдають ${$1259351s1*$<rolemult>} шкоди силами природи, розподіленої між ворогами поблизу. Ви поглинаєте їхню сутність, отримуючи $1259351s2 майстерності на $1259352d." },
    { en = "Increases the duration of Bestial Wrath by $s1%.", ua = "Збільшує тривалість Звіриного Гніву на $s1%." },
    { en = "Throw an Orange Painted Turnip at the target location, causing any nearby virmen to run away in fear for $127821d.", ua = "Кидає Оранжеву Розмальовану Ріпу в обране місце, змушуючи всіх вірменів поблизу втікати у страху протягом $127821d." },
    { en = "Your spells have a chance to increase your Intellect by $s1 for $d.", ua = "Ваші закляття мають шанс збільшити ваш Інтелект на $s1 на $d." },
    { en = "Deals $13184s1 fire damage for $d to all targets in a cone in front of the engineer using the weapon.   That is unless it explodes.....", ua = "Завдає $13184s1 шкоди вогнем протягом $d усім цілям у конусі перед інженером, що використовує цю зброю. Хіба що вона вибухне..." },
    { en = "Your healing spells have a chance to grant $235016s1 Intellect for $235016d.", ua = "Ваші зцілювальні закляття мають шанс надати $235016s1 інтелекту на $235016d." },
    { en = "Your melee attacks have a chance to set the target ablaze, dealing ${$s1*($442801d/$442801t)} Fire damage over $442801d.\n\n\n\nTriggering this effect while the target is already burning refreshes the duration while also spreading to a nearby enemy.", ua = "Ваші ближні атаки мають шанс підпалити ціль, завдаючи ${$s1*($442801d/$442801t)} шкоди вогнем протягом $442801d.\n\n\n\nСпрацювання цього ефекту, коли ціль уже горить, оновлює тривалість і поширює полум'я на ворога поблизу." },
    { en = "Your harmful spells have a chance to increase your spell power by $60064s1 for $60064d.", ua = "Ваші шкідливі закляття мають шанс підвищити вашу силу заклять на $60064s1 на $60064d." },
    { en = "Hold the fissure open causing time to distort itself reducing your movement speed by $s2% while increasing your Haste by $s5 each second over $d1.", ua = "Утримує розлам відкритим, спричиняючи викривлення часу, що знижує вашу швидкість пересування на $s2%, водночас підвищуючи вашу швидкість на $s5 щосекунди протягом $d1." },
    { en = "When you deal damage you have a chance to gain $122687s1 haste for $122687d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $122687s1 швидкості на $122687d." },
    { en = "Taking damage infuriates you, causing you to absorb $s1 damage and deal $s2 Shadow damage per infuriation split between nearby enemies. $@spelldesc1240903\n\n\n\nYou may be further infuriated every $proccooldown sec, stacking up to $1235879u times, but calm quickly upon leaving combat. \n\n\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Valid only for tank specializations.|r]", ua = "Отримання шкоди розлючує вас, через що ви поглинаєте $s1 шкоди та завдаєте $s2 тіньової шкоди за кожне розлючення, що розподіляється між ворогами поблизу. $@spelldesc1240903\n\n\n\nВи можете розлючуватися знову кожні $proccooldown с, накопичуючись до $1235879u разів, але швидко заспокоюєтеся, щойно полишите бій. \n\n\n\n$?(a137048|a137028|a137023|a137010|a212613|a137008)[][|cnRED_FONT_COLOR:Дійсно лише для спеціалізацій танка.|r]" },
    { en = "Chance on melee or ranged attack to enter Wracking Pains, during which your attacks will each grant $54697s1 critical strike, stacking up to 10 times.  Expires after $54696d.", ua = "Шанс під час ближньої чи дальньої атаки увійти в стан Нестерпного Болю, під час якого кожна ваша атака надає $54697s1 критичного удару, накопичуючись до 10 разів. Спливає за $54696d." },
    { en = "Harness the corruption of enemy players to open a gateway for $314572d, allowing bearers of this trinket to slip into the void for up to $d. While in the void, Speed is increased by $314576s1 and you cannot be seen by players outside the void.\n\n\n\nLeaving the void increases damage taken by $314573s1% for $314573d.", ua = "Опановує скверну ворожих гравців, відкриваючи прохід на $314572d, що дає носіям цієї дрібнички прослизнути в Порожнечу на час до $d. Перебуваючи в Порожнечі, ви отримуєте $314576s1 Прудкості й залишаєтеся невидимими для гравців за її межами.\n\n\n\nПісля виходу з Порожнечі отримана вами шкода зростає на $314573s1% упродовж $314573d." },
    { en = "Your spells and abilities have a chance to awaken the Heart of Wind, surrounding you with strong gales that increase your Haste by $s1 for $1263318d.", ua = "Ваші закляття та здібності мають шанс пробудити Серце Вітру, оточуючи вас потужними вихорами, що підвищують вашу швидкість на $s1 на $1263318d." },
    { en = "Increase your Haste by ${$s1*5}, decreasing by $s1 every $t2 sec.", ua = "Підвищує вашу швидкість на ${$s1*5}, зменшуючись на $s1 кожні $t2 сек." },
    { en = "Your ranged attacks and spells have a chance to trigger Focused Lightning, granting you $215632s1 Mastery every $215631t1 sec. After $215631d, this bonus decreases every $215632t2 sec.", ua = "Ваші дальні атаки та закляття мають шанс викликати Зосереджену Блискавку, надаючи вам $215632s1 майстерності кожні $215631t1 сек. Через $215631d цей бонус зменшується кожні $215632t2 сек." },
    { en = "Your melee and ranged attacks have a chance to trigger an additional attack for ${$109724m1+0.339*$AP}-${$109724M1+0.339*$AP} physical damage.", ua = "Ваші ближні та дальні атаки мають шанс викликати додаткову атаку, що завдає ${$109724m1+0.339*$AP}-${$109724M1+0.339*$AP} фізичної шкоди." },
    { en = "Chance on hit to increase your attack power by $45053s1 for $45053d.", ua = "Шанс при влучанні підвищити вашу силу атаки на $45053s1 на $45053d." },
    { en = "Have a 2% chance when struck in combat of increasing armor by $10342s1 for $10342d1.", ua = "Має 2% шансу при отриманні удару в бою підвищити броню на $10342s1 на $10342d1." },
    { en = "Hurl the molten contents, dealing $s1 Fire damage split between nearby enemies and an additional $o2 Fire damage over $d.", ua = "Жбурляє розплавлений вміст, завдаючи $s1 шкоди вогнем, розподіленої між ворогами поблизу, та додатково $o2 шкоди вогнем протягом $d." },
    { en = "Sift through the passages in the tome with increased $?a443534[Resilience][Radiance].", ua = "Гортайте уривки фоліанта з підвищеною $?a443534[стійкістю][сяйністю]." },
    { en = "Your harmful spells and abilities have a chance to conjure a cyclone at your current target's location. The cyclone follows the initial target dealing ${$s1* ($415339d/$s4)} Nature damage over $415339d split between all enemies.\n\n\n\nWhile inside the cyclone, enemies become Lightning Conduits. Dealing damage to a Lightning Conduit has a high chance to unleash a bolt of forked lighting, dealing $s2 Nature damage split between them and up to $s3 additional nearby targets.", ua = "Ваші шкідливі закляття та здібності мають шанс прикликати циклон на місці вашої поточної цілі. Циклон слідує за початковою ціллю, завдаючи ${$s1* ($415339d/$s4)} шкоди Природою протягом $415339d, розподіленої між усіма ворогами.\n\n\n\nПеребуваючи всередині циклону, вороги стають Провідниками Блискавки. Завдання шкоди Провіднику Блискавки має високий шанс вивільнити розгалужену блискавку, що завдає $s2 шкоди Природою, розподіленої між ним та ще до $s3 найближчих цілей." },
    { en = "Your attacks and abilities have a high chance to summon a scarab that retrieves a fortifying chunk of flesh from your target. Scarabs deal $s1 Physical damage and reduce your damage taken by 50% until $s2 damage has been prevented.", ua = "Ваші атаки та здібності мають високий шанс прикликати скарабея, який вириває зміцнювальний шматок плоті з вашої цілі. Скарабеї завдають $s1 фізичної шкоди та зменшують отримувану вами шкоду на 50%, доки не буде відвернено $s2 шкоди." },
    { en = "Increases spell power by $s1 for $d1.", ua = "Підвищує силу заклять на $s1 на $d1." },
    { en = "Each time a melee attack strikes you, you have a chance to gain $67631s1 armor for $67631d.", ua = "Щоразу, коли вас вражає ближня атака, ви маєте шанс отримати $67631s1 броні на $67631d." },
    { en = "You have a high chance to spatter your target with volatile phlegm, dealing ${$s1*$<rolemult>} Nature damage per sec and stacking up to $1269591u times.\n\n\n\nUpon $1269591u stacks or the enemy's demise, the phlegm violently consumes itself to deal $s2 Nature damage split between nearby enemies. $@spelldesc1240903", ua = "Ви маєте високий шанс забризкати ціль нестійким слизом, що завдає ${$s1*$<rolemult>} шкоди Природи за секунду й накопичується до $1269591u разів.\n\n\n\nПісля $1269591u зарядів або загибелі ворога слиз бурхливо поглинає сам себе, завдаючи $s2 шкоди Природи, розподіленої між найближчими ворогами. $@spelldesc1240903" },
    { en = "Your harmful abilities have a chance to cause you to summon a guardian to fight by your side for $163766d.", ua = "Ваші шкідливі здібності мають шанс прикликати охоронця, який битиметься поряд із вами протягом $163766d." },
    { en = "Gives invisibility for $d1.", ua = "Надає невидимість на $d1." },
    { en = "Instantly increases your rage by ${300/10}.", ua = "Миттєво підвищує вашу лють на ${300/10}." },
    { en = "Your spells and abilities have a chance to increase your primary stat by  $273988s1 for $273988d.", ua = "Ваші закляття та здібності мають шанс підвищити вашу основну характеристику на $273988s1 на $273988d." },
    { en = "Your attacks have a chance to stir the larynx, allowing its dark whispers to influence you. Each whisper flows through your mind for $446822d, granting $s1 Strength.", ua = "Ваші атаки мають шанс розворушити гортань, дозволяючи її темному шепоту впливати на вас. Кожен шепіт струменіє крізь ваш розум протягом $446822d, надаючи $s1 сили." },
    { en = "Place a Felshield on an ally, absorbing ${$s1*(1+$@versadmg)} damage for $d. When the shield is consumed or expires, it explodes dealing $?a137032[${$s2*0.45}][$s2]% of the absorbed damage as Fire split amongst all enemies within $253278A1 yds.", ua = "Накладає на союзника Скверний Щит, що поглинає ${$s1*(1+$@versadmg)} шкоди протягом $d. Коли щит вичерпується або спливає, він вибухає, завдаючи $?a137032[${$s2*0.45}][$s2]% поглинутої шкоди вогнем, розподіленої між усіма ворогами в межах $253278A1 м." },
    { en = "Fire Blast has a $s1% chance to also cast a Flamestrike at the target's location.", ua = "Вогняний Вибух має $s1% шансу також застосувати Полум'яний Удар на місці цілі." },
    { en = "Conjure a storm of glaives at your location, causing $242556s1 Arcane damage every $t2 sec to nearby enemies. After $d the glaives shatter, causing another $242557s1 Arcane damage to enemies in the area.", ua = "Прикликає бурю глеф на вашому місці, завдаючи $242556s1 шкоди Енергією Таємниць кожні $t2 сек. ближнім ворогам. Через $d глефи розколюються, завдаючи ще $242557s1 шкоди Енергією Таємниць ворогам у цій ділянці." },
    { en = "Your melee attacks have a chance to grant $118609s1 mastery for $118609d.", ua = "Ваші ближні атаки мають шанс надати $118609s1 майстерності на $118609d." },
    { en = "Your attacks have a chance to grant you $226991s1 Agility for $226991d.", ua = "Ваші атаки мають шанс надати вам $226991s1 спритності на $226991d." },
    { en = "Your melee and ranged attacks have a chance to inject poison into your target dealing $34587s1 Nature damage.", ua = "Ваші ближні та дальні атаки мають шанс ввести отруту у вашу ціль, завдаючи $34587s1 шкоди Природою." },
    { en = "Your attacks and attacks made against you have a chance to trigger spores to grow for $268062d before bursting. When they burst, they restore $278708s1 health to you and deal $268068s1 damage split among all nearby enemies. Deals increased damage when striking multiple targets.", ua = "Ваші атаки та атаки проти вас мають шанс спричинити ріст спор протягом $268062d, перш ніж вони лопнуть. Коли вони лопаються, то відновлюють вам $278708s1 здоров'я та завдають $268068s1 шкоди, розподіленої між усіма ближніми ворогами. Завдає підвищеної шкоди при влучанні в кілька цілей." },
    { en = "Cause the target to take up to $<damage> Shadow damage over $d. The damage of Growing Despair increases over the duration.", ua = "Змушує ціль отримати до $<damage> шкоди Тінню протягом $d. Шкода Дедалі більшого Відчаю збільшується з плином тривалості." },
    { en = "Your healing spells have a chance to grant $138856s1 mana per $138856t sec over $138856d.  (Approximately ${$procrppm}.2 procs per minute)", ua = "Ваші зцілювальні закляття мають шанс надати $138856s1 мани кожні $138856t сек. протягом $138856d. (Приблизно ${$procrppm}.2 спрацювань за хвилину)" },
    { en = "When you deal damage you have a chance to gain $117643s1 haste for $117643d.", ua = "Завдаючи шкоди, ви маєте шанс отримати $117643s1 швидкості на $117643d." },
    { en = "Reduces the threat you generate by 70% for $d.", ua = "Зменшує загрозу, яку ви створюєте, на 70% на $d." },
    { en = "Reach into the satchel and pull out something, anything that might help you out.", ua = "Сягніть рукою в торбину й витягніть звідти щось, будь-що, що могло б вам зарадити." },
    { en = "Builds a campfire that increases the Versatility of those nearby by $7353s1 and allows cooking.", ua = "Розводить багаття, що підвищує Універсальність усіх поблизу на $7353s1 і дозволяє готувати." },
    { en = "Gather herbs from bushes and other plants for use in Alchemy and Inscription.", ua = "Збирай трави з кущів та інших рослин для використання в алхімії та накресленні." },
    { en = "Allows a cook to make basic recipes. Requires meat from beasts and fire to make food.", ua = "Дозволяє кухарю готувати базові рецепти. Для приготування їжі потрібні м'ясо звірів і вогонь." },
    { en = "Gather ore and other minerals from deposits for use in Engineering, Blacksmithing, and Jewelcrafting.", ua = "Видобувайте руду та інші мінерали з покладів для використання в інженерії, ковальстві та ювелірній справі." },
    { en = "Access info about mining skills, deposits, and specializations. Also manage your mining equipment.", ua = "Доступ до інформації про навички видобутку, поклади та спеціалізації. Також дозволяє керувати вашим спорядженням для видобутку." },
    { en = "Survey for archaeology fragments within a dig site. Each survey will direct you closer to the location of the fragments.", ua = "Обстеж місце розкопок у пошуках археологічних фрагментів. Кожне обстеження наближатиме тебе до місця, де лежать фрагменти." },
    { en = "A powerful but expensive spell, healing a friendly target for $s1.$?s231642[\n\n\n\n|cFFFFFFFFGenerates $88852s1 Holy Power.][]", ua = "Потужне, але затратне закляття, що зцілює дружню ціль на $s1.$?s231642[\n\n\n\n|cFFFFFFFFГенерує $88852s1 Святої Сили.][]" },
    { en = "Summons a Guild Chest that allows access to your guild bank for $88306d. Only guild members with guild reputation of friendly and above are allowed to use a Guild Chest.", ua = "Прикликає Гільдійну скриню, що надає доступ до банку вашої гільдії на $88306d. Користуватися Гільдійною скринею можуть лише члени гільдії з репутацією «доброзичливий» і вище." },
    { en = "You can now ride at the highest possible speed on your flying mount.", ua = "Тепер ви можете їздити на летючій їздовій тварині з найвищою можливою швидкістю." },
    { en = "Heals and resurrects all of your battle pets to 100% health.", ua = "Зцілює та воскрешає всіх ваших бойових улюбленців до 100% здоров'я." },
    { en = "Allows an archaeologist to find artifact fragments and complete artifacts up to a maximum potential skill of 700.", ua = "Дозволяє археологу знаходити фрагменти артефактів і відновлювати артефакти до максимального потенційного рівня вміння 700." },
    { en = "Teleport to the entrance of Skyreach.", ua = "Телепортує до входу в Небосяг." },
    { en = "Honor gains from Arena Skirmishes increased by $s1%.", ua = "Здобуток честі за арена-сутички збільшено на $s1%." },
    { en = "Access info about herbalism skills, herbs, and specializations. Also manage your herbalism equipment.", ua = "Доступ до відомостей про навички травництва, трави та спеціалізації. Тут же керуйте своїм спорядженням травника." },
    { en = "Reduces Holy damage taken by ${$s1/-1}% and increases healing done by $s2%.", ua = "Зменшує отриману шкоду Світла на ${$s1/-1}% і підвищує заподіяне зцілення на $s2%." },
    { en = "Erupt with Light upon death. Deals $256896s1 Holy damage to enemies within 8 yards and heals allies for $256896s2.", ua = "По смерті вибухаєте Світлом. Завдає $256896s1 шкоди Світла ворогам у межах 8 ярдів і зцілює союзників на $256896s2." },
    { en = "Experience gains from killing Demons increased by $s1%.", ua = "Досвід за вбивство демонів збільшено на $s1%." },
    { en = "Access info about fishing skills and special fishing locations. Also manage your fishing equipment.", ua = "Доступ до відомостей про навички риболовлі та особливі місця для риболовлі. Тут же керуйте своїм риболовним спорядженням." },
    { en = "Stamina increased by $s1%.\n\n\n\nArmor increased by $s2%.", ua = "Витривалість збільшено на $s1%.\n\n\n\nБроню збільшено на $s2%." },
    { en = "Teleport to the entrance to Algeth'ar Academy.", ua = "Телепортує до входу в Академію Алґет'ар." },
    { en = "$?A426756[Toggle to stop your follower from leading the way.][Toggle to allow a follower to lead the way.]", ua = "$?A426756[Перемкніть, щоб ваш послідовник перестав вести вперед.][Перемкніть, щоб дозволити послідовнику вести вперед.]" },
    { en = "This delve has an abundance of treasures and will remain bountiful while inside.\n\n\n\nUse a Restored Coffer Key to open a Bountiful Coffer at the end of this delve to receive powerful equipment and greater rewards, provided you have lives remaining.", ua = "У цій глибині безліч скарбів, і вона лишатиметься щедрою, доки ти всередині.\n\n\n\nВикористай відновлений ключ від скрині, щоб наприкінці цієї глибини відкрити Щедру Скриню й отримати потужне спорядження та більші нагороди, якщо в тебе лишилися життя." },
    { en = "Increases your Versatility by $s1.", ua = "Підвищує вашу Універсальність на $s1." },
    { en = "Brann offers you some of his smoked gouda while at a campfire, increasing $pri by $s1% for $d.", ua = "Бранн біля багаття пригощає тебе шматком копченої гауди, що збільшує твою $pri на $s1% на $d." },
    { en = "Xal'atath emerges and attempts to empower enemies in combat. Players can intercept these effects and harness the power for themselves.", ua = "Ксал'атат з'являється і намагається підсилити ворогів у бою. Гравці можуть перехопити ці ефекти й обернути їхню силу на себе." },
    { en = "Allows a blacksmith to forge powerful weapons, armor, and tools from ores found in Midnight zones.", ua = "Дозволяє ковалю кувати потужну зброю, броню та інструменти з руд, що трапляються в зонах Опівночі." },
    { en = "Allows the player to improve at catching fish from bodies of water in Quel'Thalas and other Midnight zones.", ua = "Дозволяє гравцеві вдосконалювати вилов риби з водойм у Кель'Таласі та інших зонах Опівночі." },
    { en = "Devour the symbol of Torentia's authority to gain access to the vault.", ua = "Поглинь символ влади Торентії, щоб отримати доступ до сховища." },
    { en = "Frighten all hawkstriders around you.", ua = "Налякай усіх яструбоступів навколо себе." },
    { en = "Devour the symbol of Severum's authority to gain access to the vault.", ua = "Поглинь символ влади Северума, щоб отримати доступ до сховища." },
    { en = "Arator infuses you with his light, shielding you and blessing your attacks with Holy damage.", ua = "Аратор наповнює тебе своїм світлом, оточує захисним щитом і благословляє твої атаки шкодою Світла." },
    { en = "Take a breather, prepare some food and have a meal. Restores ${$1231418s1*$1231418d}% of your maximum health over $1231418d.", ua = "Перепочиньте, приготуйте трохи їжі та поїжте. Відновлює ${$1231418s1*$1231418d}% вашого максимального здоров'я протягом $1231418d." },
    { en = "Unlocks access to World Quests and Adventure Mode during Midnight for your Warband.", ua = "Відкриває твоїй бойовій ватазі доступ до Світових Завдань і Режиму Пригод під час Опівночі." },
    { en = "Your companion has a chance to gain Sanctum's Blessings through combat, as well as by slaying foes. Elite enemies grant $s4, while normal foes yield $s3.\n\n\n\nEach blessing grants $s1% increased healing and damage. Upon reaching $s6, your companion converts $s2% of their current health into an absorb shield that increases blessing bonuses while active.", ua = "Ваш супутник може отримувати Благословення Святилища в бою, а також знищуючи ворогів. Елітні вороги дають $s4, а звичайні — $s3.\n\n\n\nКожне благословення збільшує зцілення та шкоду на $s1%. Досягнувши $s6, ваш супутник перетворює $s2% свого поточного здоров'я на щит поглинання, що посилює бонуси благословень, поки активний." },
    { en = "Standing still during combat gain stacks of Cosmic Momentum every $t5 sec up to $s2. Each stack increases your movement speed by $s1%.\n\n\n\nJumping while at $s2 stacks consumes them to grant you $s3% Haste per stack for $s4 sec and knocks up surrounding enemies.\n\n\n\nCan only occur every $1256628d.", ua = "Стоячи нерухомо під час бою, ви отримуєте заряди Космічного імпульсу кожні $t5 сек, до $s2. Кожен заряд збільшує вашу швидкість руху на $s1%.\n\n\n\nСтрибок за наявності $s2 зарядів витрачає їх, даруючи вам $s3% Поспіху за кожен заряд протягом $s4 сек і підкидаючи навколишніх ворогів.\n\n\n\nМоже статися лише кожні $1256628d." },
    { en = "When your delve companion casts $@spellname1251603, a Sacred Mandate is bestowed upon party members granting their harmful spells and abilities a ${($s5/1000)*100}.1% chance to deal $s3% of the target's maximum health as additional Holy damage per Mandate.\n\n\n\nCan only occur once per target every $1261324proccooldown sec.\n\n\n\n$@spellicon1251603 $@spellname1251603\n\n$@spelldesc1251603", ua = "Коли ваш супутник Глибин творить $@spellname1251603, на учасників групи накладається Священний мандат, що дає їхнім шкідливим закляттям і здібностям ${($s5/1000)*100}.1% шанс завдати $s3% максимального здоров'я цілі як додаткову шкоду Світлом за кожен мандат.\n\n\n\nМоже статися лише раз на ціль кожні $1261324proccooldown сек.\n\n\n\n$@spellicon1251603 $@spellname1251603\n\n$@spelldesc1251603" },
    { en = "Opening a Mislaid Curiosity summons a Subjugated Burden that worships you during combat, increasing your $pri by $s3%.\n\n\n\nYou may have up to $s4 Subjugated Burdens at a time.\n\nAfter gathering at least $s5 worshipers the amount of granted $pri per Burden is increased.", ua = "Відкриття Загубленої Дивовижі прикликає Підкорену Ношу, що поклоняється вам під час бою, підвищуючи ваш(у) $pri на $s3%.\n\n\n\nВи можете мати водночас до $s4 Підкорених Нош.\n\nЗібравши щонайменше $s5 шанувальників, ви збільшуєте приріст $pri від кожної Ноши." },
    { en = "Valeera applies a debilitating poison to her and her allies' weapons. Enemies struck by these poisoned weapons have their damage reduced by $s1% and their Haste reduced by $s2% for $d.", ua = "Валіра наносить виснажливу отруту на зброю собі та своїм союзникам. Вороги, вражені цією отруєною зброєю, завдають на $s1% менше шкоди, а їхній поспіх знижено на $s2% протягом $d." },
    { en = "Spear Traps are armed throughout the delve. They will fire on unsuspecting victims who do not disarm them first.", ua = "Списові пастки розставлені по всій глибині. Вони вистрелять у необачних жертв, які не знешкодять їх заздалегідь." },
    { en = "Teleport to the entrance of Seat of the Triumvirate.", ua = "Телепортує до входу в Престол Тріумвірату." },
    { en = "Teleport to the entrance of Nexus-Point Xenas.", ua = "Телепортує до входу у Вузлову Точку Ксенас." },
    { en = "Temporarily conceals and protects the drinker from the Bound Loa. Will also knock back enemies.", ua = "Тимчасово приховує і захищає того, хто його випив, від зв'язаного лоа. Також відкидає ворогів." },
    { en = "Possessing the eye marks suspicious teachers and students. Activate the eye to reveal the true identities of any teachers or students who are disguised.", ua = "Володіння оком позначає підозрілих викладачів і студентів. Активуйте око, щоб розкрити справжню сутність будь-яких перевдягнених викладачів чи студентів." },
    { en = "Your companion has a chance during combat to toss a grenade at an enemy target dealing moderate Holy damage with a $s1% chance to stun for $1262080d. This has a $s2% chance to bounce to a new target.\n\n\n\nThe grenade can safely bounce on party members.", ua = "Ваш супутник має шанс під час бою кинути гранату у ворожу ціль, завдаючи помірної шкоди Світлом із шансом $s1% приголомшити на $1262080d. Вона має шанс $s2% відскочити до нової цілі.\n\n\n\nГраната може безпечно відскакувати на членів групи." },
    { en = "After $s3 sec of combat, party members and Valeera deal $s1% more damage and healing for $s2 sec. ($1262284d cooldown)", ua = "Після $s3 сек бою учасники групи та Валіра завдають на $s1% більше шкоди й зцілення протягом $s2 сек. ($1262284d перезарядження)" },
    { en = "Your companion has a chance during combat to create a sanctified area at a party members' location, warping the flow of time and combat for all inside. Allies within gain $s1% increased movement speed, cooldown recharge rate, and cast speed while enemies suffer the opposite effects. Lasts $1262233d.", ua = "У бою ваш супутник може створити освячену зону на позиції учасника групи, викривляючи плин часу та бою для всіх усередині. Союзники всередині отримують $s1% до швидкості пересування, темпу відновлення перезаряджень та швидкості творення, а вороги зазнають протилежних ефектів. Триває $1262233d." },
    { en = "A Sanctified Banner $@switch<$s1>[may][will] manifest within this Delve.\n\n\n\nFinding it will provide additional rewards at the end of this Delve.", ua = "Освячений Стяг $@switch<$s1>[може з'явитися][з'явиться] у цій Глибині.\n\n\n\nЯкщо знайдеш його, отримаєш додаткові нагороди наприкінці Глибини." },
    { en = "Nullaeus' allies are wandering about the delve.\n\n\n\nDefeating a group of these enemies upgrades the Nemesis Strongbox found in the treasure room, providing additional rewards at the end of this delve.$?WE43453[\n\n\n\nEnemy groups remaining: |cnWHITE_FONT_COLOR:$@currency3103 / $@currency3104|r][]", ua = "Союзники Нуллея блукають Глибиною.\n\n\n\nПеремога над групою цих ворогів покращує Сейф Немезиди в скарбниці, надаючи додаткові нагороди наприкінці цієї Глибини.$?WE43453[\n\n\n\nЗалишилося ворожих груп: |cnWHITE_FONT_COLOR:$@currency3103 / $@currency3104|r][]" },
    { en = "Gently set the mirror down.", ua = "Обережно покласти дзеркало." },
    { en = "Non-boss enemies have 20% more health and inflict up to 20% increased damage.", ua = "Звичайні вороги мають на 20% більше здоров'я та завдають до 20% більше шкоди." },
    { en = "Xal'atath betrays players, revoking her bargains while making deaths subtract 15 seconds from time remaining.", ua = "Ксал'атат зраджує гравців, скасовуючи свої угоди, а кожна смерть віднімає 15 секунд від часу, що лишився." },
    { en = "Filo, Loa of Children, becomes available for worship at the Altar of Blessings in Amani'Zar Village.", ua = "Філо, лоа дітей, стає доступним для вшанування біля Вівтаря благословень у селищі Амані'Зар." },
    { en = "Shadra, Loa of Subterfuge, becomes available for worship at the Altar of Blessings in Amani'Zar Village.", ua = "Шадра, лоа хитрощів, стає доступною для вшанування біля Вівтаря благословень у селищі Амані'Зар." },
    { en = "Your collected shards are transmuted into an Elemental Voidcore.\n\n\n\nYou have contributed $@currency3409 of $s1  Elemental Voidcores needed to complete the Voidforge.", ua = "Зібрані тобою скалки трансмутуються в Елементальне Ядро Порожнечі.\n\n\n\nТи вже надав $@currency3409 з $s1 елементальних ядер Порожнечі, потрібних для завершення Кузні Порожнечі." },
    { en = "It's very dark. You might be eaten by a grue when not standing in bright light.", ua = "Тут дуже темно. Поки не стоїш у яскравому світлі, тебе може зжерти грю." },
    { en = "Carnivorous plants dangle sticky threads from the ceiling to ensnare unwary prey.", ua = "М'ясоїдні рослини звішують зі стелі липкі нитки, щоб упіймати необачну здобич." },
    { en = "The Grudge Pit is the premiere Fungarian wrestling arena in Harandar.", ua = "Яма Злоби — найвідоміша арена для боротьби фунґаріан у Гарандарі." },
    { en = "Akil'zon's Storm Shock creates a dangerous threat for friends and foes.", ua = "Штормовий Удар Акіл'зона створює небезпечну загрозу і для друзів, і для ворогів." },
    { en = "A rack of haunted weapons can provide a powerful assistance in combat.", ua = "Стійка із зачаклованою зброєю може стати потужною підмогою в бою." },
    { en = "Contains materials for upgrading gear, gold, and more.", ua = "Містить матеріали для покращення спорядження, золото та інше." },
    { en = "Completing this quest will reward you with a Spark of Radiance. These sparks are usable by professions to create powerful weapons and armor.\n\n\n\nCompleting these activities may reward you with a weekly Spark of Radiance. If you fall behind on these weekly sparks, completing other max-level content such as Delves, Mythic Plus, Raids, Instanced PvP, and some outdoor events may help you catch up.", ua = "За виконання цього завдання ти отримаєш Іскру Сяйва. Ці іскри використовуються в професіях для створення потужної зброї та обладунків.\n\n\n\nЗа ці дії ти можеш отримати щотижневу Іскру Сяйва. Якщо ти відстав у здобутті щотижневих іскор, надолужити допоможе виконання іншого контенту для максимального рівня: Глибин, міфічних ключових підземель, рейдів, інстансованого PvP та деяких подій у відкритому світі." },
    { en = "Unlocks access to the Midnight Endgame activities across all Midnight zones.", ua = "Відкриває доступ до ендґейм-активностей Опівночі в усіх зонах Опівночі." },
    { en = "Restores $s1% health and mana over $d. Must remain seated while eating.", ua = "Відновлює $s1% здоров'я та мани протягом $d. Під час їди потрібно лишатися сидіти." },
    { en = "Lindormi highlights and weakens select non-boss enemies and prevents player deaths from reducing time remaining.\n\n\n\nDefeating all highlighted enemies will complete the enemy forces requirement.", ua = "Ліндормі підсвічує та послаблює окремих ворогів (не босів) і не дає смертям гравців скорочувати час, що лишився.\n\n\n\nПеремога над усіма підсвіченими ворогами виконає вимогу щодо ворожих сил." },
    { en = "Lindormi highlights select non-boss enemies. Defeating all highlighted enemies will complete the enemy forces requirement.", ua = "Ліндормі підсвічує окремих звичайних ворогів. Подолання всіх підсвічених ворогів виконає вимогу щодо ворожих сил." },
    { en = "An arcane folio containing powerful runes usable in combat.", ua = "Арканний фоліант, що містить потужні руни, придатні до використання в бою." },
    { en = "Upon running out of energy Arcanotron Custos begins recharging, drawing Energy Orbs toward itself and increasing damage taken by $s4% for $d.", ua = "Коли в Арканотрона-Кустоса закінчується енергія, він починає перезаряджатися, притягуючи до себе кулі енергії та збільшуючи отримувану шкоду на $s4% на $d." },
    { en = "Garfrost throws saronite ore at players, inflicting $1261295s1 Physical damage to players within $1261295A1 yards of impact.\n\n\n\nThe ore $?diff8|diff23[becomes $@spellname1261799 and ][]explodes into $@spellname1272433 when destroyed.", ua = "Ґарфрост кидає саронітову руду в гравців, завдаючи $1261295s1 фізичної шкоди гравцям у межах $1261295A1 ярдів від місця влучання.\n\n\n\nРуда $?diff8|diff23[стає $@spellname1261799 та ][]вибухає на $@spellname1272433, коли її знищено." },
    { en = "Garfrost unleashes a devastating mace slam on players within $A1 yards of his primary target, inflicting $s1 Physical damage and stunning them for $1261966d.\n\n\n\nIf the slam strikes saronite ore, it no longer stuns, instead destroying the ore.", ua = "Ґарфрост завдає нищівного удару булавою по гравцях у межах $A1 ярдів від його основної цілі, завдаючи $s1 фізичної шкоди та оглушуючи їх на $1261966d.\n\n\n\nЯкщо удар влучає в саронітову руду, він більше не оглушує, а натомість знищує руду." },
    { en = "The Forgemaster's frozen core siphons heat from players, inflicting $1261808s1 Frost damage to all players every $t1 sec.", ua = "Замерзле ядро Майстра-коваля висмоктує тепло з гравців, завдаючи $1261808s1 морозної шкоди всім гравцям кожні $t1 сек." },
    { en = "The Forgemaster's stomp causes an icy reverberation, inflicting $s1 Physical damage to all players and sending out Cryoshards.\n\n\n\nThis reverberation also destroys all saronite ore.", ua = "Тупіт Майстра-коваля спричиняє крижане відлуння, завдаючи $s1 фізичної шкоди всім гравцям і розсилаючи кріоскалки.\n\n\n\nЦе відлуння також знищує всю саронітову руду." },
    { en = "Garfrost's overloaded forge pulses cold for $d, increasing all player's Frost damage taken by $1275687s1% every $t1 sec for $1275687d. This effect stacks.\n\n\n\nSaronite ore protects players from this effect.", ua = "Перевантажена кузня Ґарфроста пульсує холодом упродовж $d, збільшуючи отримувану всіма гравцями морозну шкоду на $1275687s1% кожні $t1 сек упродовж $1275687d. Цей ефект накопичується.\n\n\n\nСаронітова руда захищає гравців від цього ефекту." },
    { en = "Tyrannus knocks away his primary target with a powerful slash, branding them. This brand increases Shadow damage taken by $1262596s1% for $1262596d. Afterward, Tyrannus casts $@spellname1263671.", ua = "Тираннус відкидає свою основну ціль потужним ударом, таврує її. Це тавро збільшує отримувану тіньову шкоду на $1262596s1% на $1262596d. Після цього Тираннус творить $@spellname1263671." },
    { en = "Rimefang blasts a player with ice, inflicting $1262750s1 Frost damage to players within $1262750A1 yards and applying $@spellname1263716. Any $@spellname1276357$?diff8|diff23[ or $@spellname1276391][] within the radius become frozen, preventing them from producing undead minions.", ua = "Раймфанг б'є гравця кригою, завдаючи $1262750s1 морозної шкоди гравцям у межах $1262750A1 ярдів і накладаючи $@spellname1263716. Будь-які $@spellname1276357$?diff8|diff23[ чи $@spellname1276391][] у радіусі замерзають, не даючи їм створювати нежить-прислужників." },
    { en = "Scourgelord Tyrannus raises Rotlings from $@spellname1276357$?diff8|diff23[ and Scourge Plaguespreaders from $@spellname1276391.][.]", ua = "Володар Погибелі Тираннус піднімає гнилячків із $@spellname1276357$?diff8|diff23[ та чумосіїв Погибелі з $@spellname1276391.][.]" },
    { en = "Hands of the dead emerge at the location of players, inflicting $1263766s1 Shadow damage to players within $1263766A1 yards and slowing them by $1263766s2% for $1263766d.", ua = "Руки мертвих з'являються на місці гравців, завдаючи $1263766s1 тіньової шкоди гравцям у межах $1263766A1 ярдів і сповільнюючи їх на $1263766s2% на $1263766d." },
    { en = "Krick releases a burst of dark energy and teleports to a ritual circle. This burst inflicts $1264246s1 Shadow damage to all players and an additional $1264246s2 Shadow damage every $1264246t2 sec for $1264246d.\n\n\n\nThis ritual summons $@spellname1264259 nearby.", ua = "Крік вивільняє спалах темної енергії й телепортується до ритуального кола. Цей спалах завдає $1264246s1 тіньової шкоди всім гравцям і додатково $1264246s2 тіньової шкоди кожні $1264246t2 сек упродовж $1264246d.\n\n\n\nЦей ритуал прикликає поблизу $@spellname1264259." },
    { en = "Krick's shade channels dark magic into a player, inflicting $s1 Shadow damage every $t1 sec and slowing their movement speed by $s2%.", ua = "Тінь Кріка спрямовує темну магію в гравця, завдаючи $s1 тіньової шкоди кожні $t1 сек і сповільнюючи його швидкість пересування на $s2%." },
    { en = "Shades of Krick $@spellname1264186 players, exploding as a $@spellname1271678 if not defeated within $1271678d.", ua = "Тіні Кріка застосовують на гравців $@spellname1264186, вибухаючи як $@spellname1271678, якщо їх не здолати протягом $1271678d." },
    { en = "Ick smashes his target, inflicting $s1 Physical damage and forming $@spellname1264299.", ua = "Ік б'є свою ціль, завдаючи $s1 фізичної шкоди та утворюючи $@spellname1264299." },
    { en = "Ick disgorges a wave of necrotic filth, inflicting $s1 Nature damage to all players and launching $@spellname1264349 towards them.", ua = "Ік вивергає хвилю некротичного бруду, завдаючи $s1 шкоди від сил природи всім гравцям і запускаючи в них $@spellname1264349." },
    { en = "Krick teleports atop Ick, compelling Ick to enter a $@spellname1264453.", ua = "Крік телепортується на Іка, змушуючи його ввійти в $@spellname1264453." },
    { en = "Krick fires a massive shadow bolt at a player that inflicts $s1 Shadow damage.", ua = "Крік випускає величезну тіньову стрілу в гравця, завдаючи $s1 тіньової шкоди." },
    { en = "Tyrannus leaps at his primary target's location, delivering a heaving necrotic strike. This maneuver impacts players within $1263701A1 yards of the landing zone, inflicting $1263691s1 Physical damage and $1263701s1 Shadow damage.", ua = "Тираннус стрибає до позиції основної цілі та завдає важкого некротичного удару. Цей маневр влучає по гравцях у радіусі $1263701A1 м від місця приземлення, завдаючи $1263691s1 фізичної шкоди та $1263701s1 шкоди Тінню." },
    { en = "Rimefang chills his victim to the bone, inflicting $s1 Frost damage every $t1 sec for $d.", ua = "Раймфанг проймає свою жертву холодом до самих кісток, завдаючи $s1 шкоди морозом кожні $t1 с протягом $d." },
    { en = "The smashed saronite oozes a harmful substance, inflicting $s1 Shadow damage to players within it.", ua = "Розтрощений сароніт сочиться шкідливою речовиною, завдаючи $s1 шкоди Тінню гравцям усередині." },
    { en = "While wielding a Sacred Weapon, your spells and abilities have a chance to deal $432616s1 additional Holy damage or healing to nearby targets. Effect is increased when Sacred Weapon strikes a single target, and reduced above $432616s2. Lasts $d.", ua = "Поки ви володієте Священною зброєю, ваші закляття та здібності можуть завдати $432616s1 додаткової шкоди Світлом або зцілити сусідні цілі на цю величину. Ефект посилюється, коли Священна зброя влучає по одній цілі, і слабшає понад $432616s2. Триває $d." },
    { en = "Unfrozen bone piles produce Rotlings when Scourgelord Tyrannus summons an $@spellname1263406.", ua = "Незаморожені купи кісток породжують гнилликів, коли Тираннус, Володар Погибелі, прикликає $@spellname1263406." },
    { en = "Unfrozen infused bone piles produce Scourge Plaguespreaders when Scourgelord Tyrannus summons an $@spellname1263406.", ua = "Незаморожені просочені купи кісток породжують чумних розповсюджувачів Погибелі, коли Володар Погибелі Тираннус прикликає $@spellname1263406." },
    { en = "Your spells and abilities have a high chance to lase your target for $@spellname467492, calling in Mister Lock-N-Stalk to deal ${$467469s1*$<rolemult>} Physical damage to your target.", ua = "Ваші закляття та здібності мають високий шанс лазерно позначити вашу ціль ефектом $@spellname467492, прикликаючи Пана Замок-і-Стеж, щоб завдати ${$467469s1*$<rolemult>} фізичної шкоди вашій цілі." },
    { en = "Your spells and abilities have a high chance to lase enemies for $@spellname467497, calling in Mister Lock-N-Stalk to deal ${$467469s2*$<rolemult>} Fire damage split between your target and nearby enemies.", ua = "Ваші закляття та здібності мають високий шанс лазерно позначити ворогів ефектом $@spellname467497, прикликаючи Пана Замок-і-Стеж, щоб завдати ${$467469s2*$<rolemult>} шкоди вогнем, розподіленої між вашою ціллю та ворогами поблизу." },
    { en = "Chunks of saronite ore rain down, inflicting $s1 Physical damage to players within $A1 yards of each impact.", ua = "Брили сароніту падають дощем, завдаючи $s1 фізичної шкоди гравцям у межах $A1 ярдів від кожного влучання." },
    { en = "Ick's blight pools inflict $s1 Nature damage every $t1 sec.", ua = "Калюжі зґуби Іка завдають $s1 шкоди від сил природи кожні $t1 сек." },
    { en = "Globules of necrotic filth impact the ground, inflicting $s1 Nature damage to players within $A1 yards and forming $@spellname1264299.", ua = "Згустки некротичного бруду вдаряють об землю, завдаючи $s1 шкоди силами природи гравцям у межах $A1 ярдів і утворюючи $@spellname1264299." },
    { en = "Ick fixates on a player for $d, increasing his attack speed by $1264492s4% and ignoring other players at all costs. While fixating, he $?diff8|diff23[splatters $@spellname1264299 and ][]launches $@spellname1264461.\n\n\n\nIck periodically changes which player he fixates upon.", ua = "Ік фіксується на гравцеві на $d, збільшуючи свою швидкість атаки на $1264492s4% і за будь-яку ціну ігноруючи інших гравців. Поки він зафіксований, він $?diff8|diff23[розбризкує $@spellname1264299 і ][]запускає $@spellname1264461.\n\n\n\nІк періодично змінює гравця, на якому фіксується." },
    { en = "Your damaging periodic effects from your spells erupt on all targets, causing $324540s1 Shadowflame damage per effect.", ua = "Ваші згубні періодичні ефекти від заклять вибухають на всіх цілях, завдаючи $324540s1 шкоди тінеполум'ям за кожен ефект." },
    { en = "stacking up to a maximum of $u times.", ua = "накопичується до $u разів." },
    { en = "Gain $@spellname453575 every $457594t seconds spent in combat.\n\n\n\n$@spellname453575 grants $458573s2 of a random secondary stat for $457596d, stacking up to $457594s1 times.\n\n\n\nThis is a Nerubian embellishment.", ua = "Отримуйте $@spellname453575 кожні $457594t секунд, проведених у бою.\n\n\n\n$@spellname453575 дає $458573s2 випадкової вторинної характеристики на $457596d, накопичуючись до $457594s1 разів.\n\n\n\nЦе нерубіанська оздоба." },
    { en = "Conjure dual swords from the Arsenal to rend your target, dealing ${$<rolemult>*$445203s1} Shadow damage over $d. Gain $445203s2 Parry and $445203s3 Avoidance until the next weapon is drawn.", ua = "Прикличте парні мечі з Арсеналу, щоб роздерти вашу ціль, завдаючи ${$<rolemult>*$445203s1} шкоди Тінню протягом $d. Отримуєте $445203s2 Парирування та $445203s3 Уникнення, доки не дістано наступну зброю." },
    { en = "Draw a bow from the Arsenal to unleash a barrage of arrows in front of you, dealing ${$<rolemult>*$445203s6} Shadow damage to all enemies within $a1 yards. \n\n\n\nUntil the next weapon is drawn, remain stationary to increase your speed by ${$445203s7/$448433u}% for $448436d upon moving, increased by an additional ${$445203s7/$448433u}% every $448036t1 sec, up to $448433u times.", ua = "Дістаньте лук з Арсеналу, щоб випустити перед собою залп стріл, завдаючи ${$<rolemult>*$445203s6} шкоди Тінню всім ворогам у радіусі $a1 м. \n\n\n\nДоки не дістано наступну зброю, стійте на місці, щоб збільшити свою швидкість на ${$445203s7/$448433u}% протягом $448436d, щойно рушите, додатково на ${$445203s7/$448433u}% кожні $448036t1 с, до $448433u разів." },
    { en = "If your health falls below $1250584s2%, the jelly instinctively thickens around you for $d, absorbing up to $1250584s3 damage. This effect can only activate once every $1254907d.", ua = "Якщо ваше здоров'я падає нижче $1250584s2%, желе інстинктивно загусає навколо вас на $d, поглинаючи до $1250584s3 шкоди. Цей ефект може активуватися лише раз на $1254907d." },
    { en = "Reduces your size by $s1%, and increases your Speed by $472120s4 and Haste by $472120s3.", ua = "Зменшує ваш розмір на $s1% і збільшує вашу Швидкість на $472120s4, а Поспіх на $472120s3." },
    { en = "Increases your size by $s1%, maximum health by $472120s1, and $pri by $472120s2.", ua = "Збільшує ваш розмір на $s1%, максимальне здоров'я на $472120s1, а $pri на $472120s2." },
    { en = "Taking damage has a chance to form a jelly shield for $d, absorbing $s2% of incoming damage, up to $1250584s1.", ua = "Отримання шкоди має шанс утворити желейний щит на $d, що поглинає $s2% вхідної шкоди, до $1250584s1." },
    { en = "Launches bolts of arcane energy at the enemy target, causing $s1 Arcane damage. \n\n\n\nFor each Arcane Charge, deals $36032s2% additional damage$?a321526[, grants you ${$321526s1/100}.1% of your maximum mana,][]$?a231564[ and hits $231564s1 additional nearby $Ltarget:targets; for $231564s2% of its damage][].\n\n\n\n|cFFFFFFFFConsumes all Arcane Charges.|r", ua = "Запускає стріли арканної енергії у ворожу ціль, завдаючи $s1 арканної шкоди. \n\n\n\nЗа кожен арканний заряд завдає $36032s2% додаткової шкоди$?a321526[, дає вам ${$321526s1/100}.1% вашої максимальної мани,][]$?a231564[ і вражає $231564s1 додаткову $Lціль:цілі; поблизу, завдаючи $231564s2% своєї шкоди][].\n\n\n\n|cFFFFFFFFСпоживає всі арканні заряди.|r" },
    { en = "$?a137042|a137018|a137040|a137033|a137016|a137015|a356809|a137013[and transforming into a lich for $415133d. As a lich, your harmful spells and abilities have a chance to slow the target by $415132s1% for $415132d. $415006s10 sec after transforming, you launch a pillar of ice at your target dealing $415006s4 Frost damage split between all nearby enemies. (2 Min 30 Sec Cooldown)][]$?a137039|a137031|a137032|a137029|a137024|a356810|a137012[and transforming into a lich while promoting a friendly target to Scourge General for $415170d. The Scourge General's maximum health is increased by $415006s7 and damage they deal has a chance to heal them for $415006s8. After $415006s10 sec, your Scourge General gains $415006s9 Haste for $415200d. (2 Min 30 Sec Cooldown)][]", ua = "$?a137042|a137018|a137040|a137033|a137016|a137015|a356809|a137013[і перетворюючи вас на ліча на $415133d. Як ліч, ваші шкідливі закляття й вміння мають шанс уповільнити ціль на $415132s1% на $415132d. Через $415006s10 с після перетворення ви запускаєте крижаний стовп у свою ціль, завдаючи $415006s4 шкоди морозом, розподіленої між усіма ворогами поблизу. (Перезарядження 2 хв 30 с)][]$?a137039|a137031|a137032|a137029|a137024|a356810|a137012[і перетворюючи вас на ліча, водночас підвищуючи союзну ціль до генерала Погибелі на $415170d. Максимальне здоров'я генерала Погибелі збільшено на $415006s7, а шкода, яку він завдає, має шанс зцілити його на $415006s8. Через $415006s10 с ваш генерал Погибелі отримує $415006s9 Поспіху на $415200d. (Перезарядження 2 хв 30 с)][]" },
    { en = "Your spells and abilities have a chance to induce Voidlust. Voidlust increases your Critical Strike by $1272091s1, Leech by $s2%, and Movement Speed by $s3%.", ua = "Ваші закляття та здібності можуть викликати Жагу Порожнечі. Жага Порожнечі збільшує ваш Критичний удар на $1272091s1, Висмоктування на $s2% та Швидкість пересування на $s3%." },
    { en = "Drinking the Phial of Serenity rejuvinates you, restoring health.", ua = "Випивши Флакон спокою, ви оновлюєтеся, відновлюючи здоров'я." },
    { en = "Draw a polearm from the Arsenal to strike all enemies in a line, dealing ${$<rolemult>*$445203s4} Physical damage split between all targets. \n\n\n\nUntil the next weapon is drawn, your critical strikes deal $445203s5% bonus Shadow damage to absorb shields.", ua = "Дістаньте держакову зброю з Арсеналу, щоб уразити всіх ворогів у лінії, завдаючи ${$<rolemult>*$445203s4} фізичної шкоди, розподіленої між усіма цілями. \n\n\n\nДоки не дістано наступну зброю, ваші критичні удари завдають $445203s5% додаткової шкоди Тінню щитам поглинання." },
    { en = "Damage increased by $s1% per additional enemy, up to ${$s1*$s2}%.", ua = "Шкода збільшена на $s1% за кожного додаткового ворога, до ${$s1*$s2}%." },
    { en = "Krick's shade explodes after $d, destroying itself. This inflicts $1271679s1 Shadow damage to all players and an additional $1271679s2 Shadow damage every $1271679t2 sec for $1271679d. This effect stacks.", ua = "Тінь Кріка вибухає за $d, знищуючи себе. Це завдає $1271679s1 шкоди Тінню всім гравцям і додатково $1271679s2 шкоди Тінню кожні $1271679t2 с протягом $1271679d. Цей ефект накопичується." },
    { en = "Rimefang spits frost at a player that inflicts $s1 Frost damage.", ua = "Раймфанг плює морозом у гравця, завдаючи $s1 шкоди Льодом." },
    { en = "Rimefang spits icy chunks towards players for $d, inflicting $1276973s1 Frost damage to players within $1276973A1 yards of each impact.", ua = "Раймфанг випльовує крижані брили в бік гравців протягом $d, завдаючи $1276973s1 шкоди Льодом гравцям у межах $1276973A1 ярдів від кожного влучання." },
    { en = "The Scourge Plaguespreader's decaying presence inflicts $1263000s1 Nature damage to all players every $t1 sec.", ua = "Гнильна присутність Чумосію Погибелі завдає $1263000s1 шкоди Природою всім гравцям щосекунди впродовж $t1 сек." },
    { en = "While riding atop Ick, Krick throws dark energy at a player that inflicts $s1 Shadow damage.", ua = "Сидячи верхи на Іку, Крік кидає темну енергію в гравця, завдаючи $s1 шкоди Тінню." },
    { en = "Krick connects his life force with Ick to enhance his control, causing both to share all damage taken.", ua = "Крік пов'язує свою життєву силу з Іком, щоб посилити контроль над ним, через що обидва ділять усю отриману шкоду." },
    { en = "The Rotling rots its primary target with each melee strike, reducing their maximum health by $<reduction>% for $1262930d. This effect stacks.", ua = "Гнилець гноїть свою основну ціль кожним ударом ближнього бою, зменшуючи її максимальне здоров'я на $<reduction>% протягом $1262930d. Цей ефект накопичується." },
    { en = "The Scourge Plaguespreader hurls putrid magic at a player that inflicts $s1 Nature damage.", ua = "Чумосій Погибелі жбурляє гнилу магію в гравця, завдаючи $s1 шкоди Природою." },
    { en = "Shards of ice slam into players, increasing their Frost damage taken by $s1% and slowing them by $s2% for $d.", ua = "Скалки криги врізаються в гравців, підвищуючи отримувану ними шкоду Льодом на $s1% і сповільнюючи їх на $s2% протягом $d." },
    { en = "$?diff23|diff8[Scourgelord Tyrannus stomps necrotic energy into the ground, turning some $@spellname1276357 into $@spellname1276391.\n\n\n\nThe stomp inflicts $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.][Scourgelord Tyrannus stomps necrotic energy into the ground, inflicting $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.]", ua = "$?diff23|diff8[Володар Погибелі Тираннус вбиває некротичну енергію в землю, перетворюючи деякі $@spellname1276357 на $@spellname1276391.\n\n\n\nУдар завдає $s1 шкоди Тінню всім гравцям і додатково $s2 шкоди Тінню щосекунди впродовж $t2 сек. протягом $d.][Володар Погибелі Тираннус вбиває некротичну енергію в землю, завдаючи $s1 шкоди Тінню всім гравцям і додатково $s2 шкоди Тінню щосекунди впродовж $t2 сек. протягом $d.]" },
    { en = "Valeera uses her gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.", ua = "Валіра використовує свої збиральницькі знаряддя, щоб допомогти гравцям знаходити додаткове золото, руду, трави, рибу, шкури та скарби." },
    { en = "Arcanotron Custos strikes it's current target with destructive force inflicting $s1 Arcane damage and knocking them back.", ua = "Арканотрон-вартовий вдаряє свою поточну ціль руйнівною силою, завдаючи $s1 арканної шкоди й відкидаючи її." },
    { en = "Inflicts $s1 Arcane damage every $t second for $d. This effect stacks.", ua = "Завдає $s1 арканної шкоди кожні $t с протягом $d. Цей ефект накопичується." },
    { en = "Arcanotron Custos expels Arcane energy creating a pool of $@spellname1214089 at its feet, inflicting $s3 damage to all players and knocking them back.", ua = "Арканотрон Кустос вивергає арканну енергію, утворюючи під собою калюжу $@spellname1214089, що завдає $s3 шкоди всім гравцям і відкидає їх назад." },
    { en = "$?DIFF1[Arcanotron Custos attracts unstable Energy Orbs to itself, granting it $@spellname474407 upon contact. If a player comes into contact with an Energy Orb it will be destroyed, covering the player with $@spellname1243905 .][]$?DIFF2[Arcanotron Custos attracts unstable Energy Orbs to itself, granting it $@spellname474407  upon contact. If a player comes into contact with an Energy Orb it will be destroyed, covering the player with $@spellname1243905][]$?DIFF8$?DIFF23[Arcanotron Custos attracts unstable Energy Orbs to itself, granting it $@spellname474407 upon contact. If a player comes into contact with an Energy Orb it will be destroyed, creating a pool of $@spellname1214089 and covering the player with $@spellname1243905.][]", ua = "$?DIFF1[Аркано-трон Кустос притягує до себе нестабільні Кулі Енергії, отримуючи $@spellname474407 при контакті. Якщо гравець торкається Кулі Енергії, вона руйнується, вкриваючи гравця $@spellname1243905 .][]$?DIFF2[Аркано-трон Кустос притягує до себе нестабільні Кулі Енергії, отримуючи $@spellname474407  при контакті. Якщо гравець торкається Кулі Енергії, вона руйнується, вкриваючи гравця $@spellname1243905][]$?DIFF8$?DIFF23[Аркано-трон Кустос притягує до себе нестабільні Кулі Енергії, отримуючи $@spellname474407 при контакті. Якщо гравець торкається Кулі Енергії, вона руйнується, створюючи калюжу $@spellname1214089 й вкриваючи гравця $@spellname1243905.][]" },
    { en = "An Energy Orb refueling Arcanotron Custos creates an arcane explosion inflicting $474414s1 Arcane damage to all players and increasing the damage inflicted by Arcanotron Custos by $474407s1%.", ua = "Енергетична куля, що підзаряджає Арканотрон Кустос, спричиняє арканний вибух, завдаючи $474414s1 арканної шкоди всім гравцям і збільшуючи шкоду, яку завдає Арканотрон Кустос, на $474407s1%." },
    { en = "Creates a pool of $@spellname1214089 inflicting $s1 Arcane damage every $t1 sec and reducing the movement speed of players in the area by $s2%.", ua = "Створює калюжу $@spellname1214089, що завдає $s1 арканної шкоди кожні $t1 с і зменшує швидкість пересування гравців у зоні на $s2%." },
    { en = "Arcanotron Custos suppresses the movement of several players, inflicting $s1 Arcane damage every $t1 sec and rooting them for $d.", ua = "Аркано-трон Кустос пригнічує рух кількох гравців, завдаючи $s1 арканної шкоди кожні $t1 с і вкорінюючи їх на $d." },
    { en = "Seranel hurls an Arcane infused glaive at a target inflicting ${$s1+$1225796s1} Arcane damage and an additional $1225796s1 Arcane damage every $t2 sec to players within $1225796A2 yards. The glaive bounces to $s3 nearby players.", ua = "Серанель жбурляє в ціль глефу, насичену арканною магією, завдаючи ${$s1+$1225796s1} арканної шкоди й додаткові $1225796s1 арканної шкоди кожні $t2 с гравцям у радіусі $1225796A2 м. Глефа відскакує до $s3 довколишніх гравців." },
    { en = "Seranel slams his shield into the ground, inflicting $1224903s1 Arcane damage to players within $1224903A2 yards and conjuring a $@spellname1224903 at the impact area.\n\n\n\nThe $@spellname1224903 silences and pacifies players standing within and purges magical effects.", ua = "Серанель б'є щитом об землю, завдаючи $1224903s1 арканної шкоди гравцям у радіусі $1224903A2 метрів і прикликаючи $@spellname1224903 у місці удару.\n\n\n\n$@spellname1224903 змушує замовкнути та втихомирює гравців, що стоять усередині, і знімає магічні ефекти." },
    { en = "Seranel readies a $@spellname1225201, inflicting $s1 Arcane damage to all players and pacifying any player outside of the $@spellname1225015 for $1225205d.", ua = "Серанель готує $@spellname1225201, завдаючи $s1 арканної шкоди всім гравцям і утихомирюючи кожного гравця поза межами $@spellname1225015 на $1225205d." },
    { en = "The $@spellname1224801 violently reacts to the removal, inflicting $s1 Arcane damage to all players and reducing their movement speed by $s2% for $d. This effect stacks.", ua = "$@spellname1224801 бурхливо реагує на видалення, завдаючи $s1 арканної шкоди всім гравцям і знижуючи їхню швидкість пересування на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The $@spellname1225015 consumes $@spellname1224801 from the target, causing them to emit a barrage of arcane missiles. Each missile inflicts $s1 Arcane damage to players within $A2 yards of the impact area, silencing and pacifying them for $d.", ua = "$@spellname1225015 поглинає $@spellname1224801 із цілі, змушуючи її випустити шквал арканних снарядів. Кожен снаряд завдає $s1 арканної шкоди гравцям у радіусі $A2 м від зони удару, роблячи їх німими й утихомирюючи на $d." },
    { en = "Seranel surrounds himself in a hastening ward, increasing his attack speed by $s1% and his auto attacks to inflict an additional $1271317s1 Arcane damage for $d.", ua = "Серанель оточує себе прискорювальним оберегом, збільшуючи швидкість своїх атак на $s1% і змушуючи свої автоатаки завдавати додатково $1271317s1 арканної шкоди протягом $d." },
    { en = "All Gemellus function as a collective, sharing health.", ua = "Усі Гемеллуси діють як єдине ціле, маючи спільне здоров'я." },
    { en = "$@spellname1223958 forms a pool of secretions, inflicting $s1 Shadow damage every $t1 sec to players standing within.", ua = "$@spellname1223958 утворює калюжу виділень, завдаючи $s1 тіньової шкоди кожні $t1 с гравцям, що стоять у ній." },
    { en = "At the start of the encounter and upon reaching $s3% remaining health Gemullus self replicates, creating $s1 clones of itself.", ua = "На початку сутички та діставшись $s3% залишкового здоров'я, Гемеллус самовідтворюється, створюючи $s1 своїх клонів." },
    { en = "Gemellus forms a neural link with a player, absorbing damage equal to $s2% of its maximum health. The player they are linked to receives $1253709s1% more damage for $1253709d.\n\n\n\nPlayers who touch the Gemellus who linked with them before $@spellname1253707 expires disrupts the connection, removing Gemellus' damage absorb.", ua = "Гемеллус утворює нейронний зв'язок із гравцем, поглинаючи шкоду в розмірі $s2% свого максимального здоров'я. Гравець, із яким він пов'язаний, отримує на $1253709s1% більше шкоди протягом $1253709d.\n\n\n\nЯкщо гравці торкнуться Гемеллуса, з яким пов'язані, до закінчення $@spellname1253707, зв'язок розривається, знімаючи поглинання шкоди Гемеллуса." },
    { en = "Gemellus channels a shadowy tendril at a player, inflicting $s1 Shadow damage every $t1 sec and pulling the player towards them for $D.", ua = "Гемеллус спрямовує на гравця тіньове щупальце, завдаючи $s1 тіньової шкоди кожні $t1 с і притягуючи гравця до себе на $D." },
    { en = "Gemellus radiates players pulled within its grasp, inflicting $s1 Shadow damage every $t1 sec.", ua = "Гемеллус опромінює гравців, притягнутих у його хватку, завдаючи $s1 тіньової шкоди кожні $t1 с." },
    { en = "Gemellus stings a player with Cosmic Void, inflicting $s1 Shadow damage and creating a pool of $@spellname1224104 at their location. Inflicts an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Гемеллус жалить гравця Космічною Порожнечею, завдаючи $s1 тіньової шкоди й створюючи калюжу $@spellname1224104 на його місці. Завдає додатково $s2 тіньової шкоди кожні $t2 с протягом $d." },
    { en = "Degentrius corrupts several players with Void energy, inflicting $s1 Shadow damage every $t1 sec. Each afflicted player receives a different duration.\n\n\n\nUpon expiration, $@spellname1269631s launch from the player's location.", ua = "Дегентрій псує кількох гравців енергією Порожнечі, завдаючи $s1 тіньової шкоди кожні $t1 с. Кожен уражений гравець отримує різну тривалість.\n\n\n\nПісля завершення з місця гравця вистрілюють $@spellname1269631s." },
    { en = "Degentrius unleashes an $@spellname1271066 at its primary target inflicting Physical damage.", ua = "Дегентрій вивільняє $@spellname1271066 на свою основну ціль, завдаючи фізичної шкоди." },
    { en = "Degentrius launches unstable void energy that bounces to $s2 locations, inflicting $1215157s1 Shadow damage to any player at the point of impact.\n\n\n\nIf no player is in the area the unstable void essence erupts in $@spellname1215161.", ua = "Деґентріус запускає нестабільну енергію Порожнечі, що відскакує до $s2 місць, завдаючи $1215157s1 тіньової шкоди будь-якому гравцеві в точці влучання.\n\n\n\nЯкщо в зоні немає гравця, нестабільна есенція Порожнечі вибухає, утворюючи $@spellname1215161." },
    { en = "Degentrius smashes a massive fragment into their current target, inflicting $1280119s1 Shadow damage to players within $1280119a1 yards.\n\n\n\nThe force of the impact knocks away other players within $1280119a1 yards of their target.", ua = "Дегентрій врізає величезний уламок у свою поточну ціль, завдаючи $1280119s1 тіньової шкоди гравцям у радіусі $1280119a1 м.\n\n\n\nСила удару відкидає інших гравців у радіусі $1280119a1 м від цілі." },
    { en = "Embedded splinters from $@spellname1280113 inflict $s1 Shadow damage every $t1 sec for $d. This effect stacks.\n\n\n\nUpon removal, the splinters dissolve, leaving behind $@spellname1284628.", ua = "Вбиті скалки від $@spellname1280113 завдають $s1 тіньової шкоди кожні $t1 с протягом $d. Цей ефект накопичується.\n\n\n\nПісля зняття скалки розчиняються, залишаючи по собі $@spellname1284628." },
    { en = "The dissolved splinters form a pool on the ground for $d, inflicting $1284633s1 Shadow damage every $1284633t1 sec to players within.", ua = "Розчинені скалки утворюють калюжу на землі на $d, завдаючи $1284633s1 тіньової шкоди кожні $1284633t1 с гравцям усередині." },
    { en = "Void energy erupts upon impact with the ground inflicting $s1 Shadow damage to all players plus an additional $s2 Shadow damage every $t2 sec for $d. This effect stacks.", ua = "Енергія Порожнечі вибухає при влучанні в землю, завдаючи $s1 тіньової шкоди всім гравцям і додатково $s2 тіньової шкоди кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "The Celestial Orrery's focusing lenses channel Void energy into Degentrius. Contact with a $@spellname1215786 inflicts $s1 Shadow damage and stuns the player for $d.", ua = "Фокусувальні лінзи Небесного Планетарію каналізують енергію Порожнечі в Деґентріуса. Контакт із $@spellname1215786 завдає $s1 тіньової шкоди й оглушує гравця на $d." },
    { en = "Volatile masses inflict $s2 Shadow damage to players struck and additionaly reduce their movement speed by $s1% for $d.", ua = "Летючі маси завдають $s2 тіньової шкоди враженим гравцям і додатково знижують їхню швидкість пересування на $s1% протягом $d." },
    { en = "Ranjit hurls a wind chakram in front of him, inflicting $1258160s1 Nature damage to all players caught in its path.", ua = "Ранджит жбурляє вітряний чакрам перед собою, завдаючи $1258160s1 шкоди від сил природи всім гравцям на його шляху." },
    { en = "Ranjit blasts target players with a powerful gust of wind, inflicting $1252691s1 Nature damage and knocking them back$?diff1|diff2[.][ and leaves behind a $@spellname1258140.]", ua = "Ранджит уражає вибраних гравців потужним поривом вітру, завдаючи $1252691s1 шкоди природою та відкидаючи їх назад$?diff1|diff2[.][ і лишаючи по собі $@spellname1258140.]" },
    { en = "Ranjit throws a powerful wind chakram to the center of the platform, inflicting $1281396s2 Nature damage to players within $1281396a2 yards of the impact area. The chakram continues to spin, inflicting $s1 Nature damage to players it hits and knocking them back.\n\n\n\nThe chakram forms raging wind vortexes that trail around the platform, inflicting $s1 Nature damage to any enemy hit and knocking them in the air.", ua = "Ранджит кидає потужний вітряний чакрам у центр платформи, завдаючи $1281396s2 шкоди від сил природи гравцям у межах $1281396a2 ярдів від зони влучання. Чакрам продовжує обертатися, завдаючи $s1 шкоди від сил природи гравцям, яких влучає, і відкидаючи їх.\n\n\n\nЧакрам утворює лютуючі вихори вітру, що тягнуться платформою, завдаючи $s1 шкоди від сил природи будь-якому враженому ворогові й підкидаючи його в повітря." },
    { en = "Unleashes a powerful gust of wind that inflicts $s1 Nature damage to target player and knocking them back.", ua = "Вивільняє потужний порив вітру, що завдає $s1 шкоди від сил природи цільовому гравцеві й відкидає його назад." },
    { en = "Ranjit throws razor sharp blades in all directions, inflicting $s1 Physical damage and causing them to bleed, inflicting $s2 Physical damage every $t2 sec for $d.", ua = "Ранджит кидає гострі як бритва клинки в усіх напрямках, завдаючи $s1 фізичної шкоди й змушуючи кровоточити, завдаючи $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Araknath unleashes a wave of solar energy that inflicts $s1 Fire damage to all players and additional $s2 Fire damage every $t2 sec for $d. This effect stacks.\n\n\n\nThis attack is only used by Araknath whenever he is not actively engaged in melee combat.", ua = "Аракнат вивільняє хвилю сонячної енергії, що завдає $s1 вогняної шкоди всім гравцям і додатково $s2 вогняної шкоди кожні $t2 с протягом $d. Цей ефект накопичується.\n\n\n\nЦю атаку Аракнат застосовує лише тоді, коли не задіяний активно в ближньому бою." },
    { en = "The solar beam inflicts $1287905s1 Fire damage every $t1 sec to players blocking it.", ua = "Сонячний промінь завдає $1287905s1 вогняної шкоди кожні $t1 с гравцям, які його перекривають." },
    { en = "Light rays that connect with Araknath infuse it with solar energy, inflicting $1258205s1 Fire damage to all players and increasing $@spellname154135's damage done by $s1%. This effect stacks. \n\n\n\nSolar Infusion is consumed after empowering $@spellname154135.", ua = "Промені світла, що сягають Аракната, наповнюють його сонячною енергією, завдаючи $1258205s1 вогняної шкоди всім гравцям і збільшуючи шкоду від $@spellname154135 на $s1%. Цей ефект накопичується. \n\n\n\nСонячне Вливання витрачається після підсилення $@spellname154135." },
    { en = "The lesser constructs exhaust heat in front of them after focusing energy into Araknath, inflicting $1281873s1 Fire damage to players in the impact area.", ua = "Менші конструкти, сфокусувавши енергію в Аракнаті, випускають жар перед собою, завдаючи $1281873s1 вогняної шкоди гравцям у зоні удару." },
    { en = "Araknath raises one of its arms and smashes the ground on that side, inflicting $s1 Fire damage to all players in the impact area and increases their damage taken from $@spellname154132 by $s2% for $d. This effect stacks.", ua = "Аракнат піднімає одну зі своїх рук і трощить землю з того боку, завдаючи $s1 вогняної шкоди всім гравцям у зоні удару й збільшуючи шкоду, яку вони отримують від $@spellname154132, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Araknath releases a burst of solar energy that inflicts $s1 Fire damage to all players.", ua = "Аракнат вивільняє спалах сонячної енергії, що завдає $s1 вогняної шкоди всім гравцям." },
    { en = "Araknath is in a defensive stance, rooting itself and emitting blistering heat, inflicting $s1 Fire damage every $t1 sec to players standing within $s2 yards.", ua = "Аракнат займає захисну стійку, вкорінюючись і випромінюючи нестерпний жар, завдаючи $s1 вогняної шкоди кожні $t1 с гравцям, що стоять у радіусі $s2 м." },
    { en = "Lesser constructs surrounding the arena focus light rays at Araknath, healing it for $154149s1% every $t1 sec$?diff1|diff2[.][ and granting it $@spellname1252877 every $t1 sec.]\n\n\n\nPlayers blocking light rays suffer $1287905s1 Fire damage every $154150t1 sec.", ua = "Менші конструкти, що оточують арену, фокусують промені світла на Аракнаті, зцілюючи його на $154149s1% кожні $t1 с$?diff1|diff2[.][ і надаючи йому $@spellname1252877 кожні $t1 с.]\n\n\n\nГравці, що блокують промені світла, зазнають $1287905s1 вогняної шкоди кожні $154150t1 с." },
    { en = "Rukhran calls down a burst of solar energy that inflicts $s1 Fire damage to all players and summons a Sunwing.", ua = "Рухран викликає спалах сонячної енергії, що завдає $s1 вогняної шкоди всім гравцям і прикликає Сонцекрила." },
    { en = "The Sunwing fixates on a random player and pulses its fiery energy at the cost of its health, burning $1281876s1% of its maximum health and inflicting $s1 Fire damage to all players every $1253367t1 sec.", ua = "Сонцекрил зосереджується на випадковому гравцеві й випромінює свою вогняну енергію ціною власного здоров'я, спалюючи $1281876s1% свого максимального здоров'я та завдаючи $s1 вогняної шкоди всім гравцям кожні $1253367t1 сек." },
    { en = "The Sunwing erupts in a blaze of glory upon defeat, inflicting $s1 Fire damage to players within $a1 yards of the impact area$?diff1|diff2[.]\n\n\n\n[.\n\n\n\nSmoldering Eggs caught in the blast remerge as a Sunwing.]", ua = "Зазнавши поразки, Сонцекрил вибухає сяйвом слави, завдаючи $s1 вогняної шкоди гравцям у межах $a1 м від зони влучання$?diff1|diff2[.]\n\n\n\n[.\n\n\n\nТліючі Яйця, охоплені вибухом, знову зливаються в Сонцекрила.]" },
    { en = "Rukhran unleashes a deafening screech, inflicting $s2 Sonic damage to all players.\n\n\n\nThis attack is only used if Ruhkhran is not actively engaged in melee combat.", ua = "Рухран вивільняє оглушливий вереск, завдаючи $s2 звукової шкоди всім гравцям.\n\n\n\nЦя атака застосовується, лише коли Рухран не задіяний у ближньому бою." },
    { en = "Rukhran lashes their current target with burning claws, inflicting $s1 Physical damage and $1253520s1 Fire damage. Also casues the the target to burn, inflicting $1253521s1 Fire damage every $1253520t2 sec for $1253520d.", ua = "Рухран шматує свою поточну ціль палаючими пазурами, завдаючи $s1 фізичної шкоди та $1253520s1 вогняної шкоди. Також підпалює ціль, завдаючи $1253521s1 вогняної шкоди кожні $1253520t2 с протягом $1253520d." },
    { en = "Upon defeat, the Sunwing enters dormancy as a Smoldering Egg.", ua = "Зазнавши поразки, Сонцекрил впадає у сплячку у вигляді Тліючого Яйця." },
    { en = "Rukhran unleashes waves of flaming quills, inflicting $s3 Fire damage every $159382t1 sec to players in line of sight for $159382d.", ua = "Рухран вивільняє хвилі полум'яних голок, завдаючи $s3 вогняної шкоди кожні $159382t1 с гравцям у полі зору протягом $159382d." },
    { en = "High Sage Viryx summons a Solar Zealot above a random player that will attempt to carry them off the balcony and drop them to their death below.", ua = "Верховна Мудрець Вірікс прикликає Сонячного Фанатика над випадковим гравцем, що намагатиметься винести його за балкон і скинути на смерть унизу." },
    { en = "High Sage Viryx blasts their current target with solar energy, inflicting $s1 Fire damage.", ua = "Верховна мудреця Вірікс вражає поточну ціль сонячною енергією, завдаючи $s1 вогняної шкоди." },
    { en = "High Sage Viryx scorches several players with focused sunlight, inflicting $1253543s1 Fire damage and an additional $1253543s3  Fire damage every $1253543t3 sec for $1253543d.", ua = "Верховна мудриця Вірікс обпалює кількох гравців сфокусованим сонячним світлом, завдаючи $1253543s1 вогняної шкоди та додатково $1253543s3 вогняної шкоди кожні $1253543t3 сек. протягом $1253543d." },
    { en = "Lens Flare creates areas of intense heat that inflict $s1 Fire damage every $t1 sec to players standing in the area.", ua = "Спалах Лінзи створює зони пекучого жару, що завдають $s1 вогняної шкоди кожні $t1 с гравцям, які стоять у зоні." },
    { en = "High Sage Viryx commands the solar crystals to focus their intense energy on a player, inflicting $s1 Fire damage to enemies within $a1 yards of impact$?diff1|diff2[.][ and leaving behind $@spellname154043.]", ua = "Верховна мудреця Вірікс наказує сонячним кристалам зосередити свою потужну енергію на гравцеві, завдаючи $s1 вогняної шкоди ворогам у радіусі $a1 м від місця удару$?diff1|diff2[.][ і лишаючи по собі $@spellname154043.]" },
    { en = "$@spellname386201 inflicts $s1 Arcane damage every $t1 sec to players inside and reduces their movement speed by $s3%.", ua = "$@spellname386201 завдає $s1 од. арканної шкоди кожні $t1 сек гравцям усередині та знижує їхню швидкість пересування на $s3%." },
    { en = "Vexamus ejects a mass of arcane energy inflicting $s1 Arcane damage to players in front of it.", ua = "Вексамус вивергає масу арканної енергії, завдаючи $s1 арканної шкоди гравцям перед собою." },
    { en = "Increases damage taken from absorbing $@spellname387691 by $s1% for $d.", ua = "Підвищує шкоду, отриману від поглинання $@spellname387691, на $s1% протягом $d." },
    { en = "Upon reaching 100 energy, Vexamus explodes with overwhelming power inflicting $388537s2 Arcane damage to all players and pushing them back.", ua = "Сягнувши 100 енергії, Вексамус вибухає нездоланною силою, завдаючи $388537s2 арканної шкоди всім гравцям і відкидаючи їх назад." },
    { en = "The Professor conjures enchanted orbs from the magic book that inflict $385970s2 Arcane damage within 3 yards of impact and begin to gravitate towards Vexamus.\n\n\n\nIf an orb is absorbed by Vexamus, the elemental inflict $386088s2 Arcane damage to all players. If an orb is absorbed by a player, it will inflict $385981s1 Arcane damage to them.", ua = "Професор прикликає з магічної книги зачаровані кулі, що завдають $385970s2 арканної шкоди в межах 3 м від місця влучання й починають тяжіти до Вексамуса.\n\n\n\nЯкщо кулю поглине Вексамус, елементаль завдасть $386088s2 арканної шкоди всім гравцям. Якщо кулю поглине гравець, вона завдасть йому $385981s1 арканної шкоди." },
    { en = "Upon reaching 100 energy, Vexamus explodes with overwhelming power inflicting $s2 Arcane damage to all players and pushing them back. Fissures erupt multiple times at player locations, each inflicting $388546s1 Arcane damage within $388546A1 yards.", ua = "Сягнувши 100 енергії, Вексамус вибухає нездоланною силою, завдаючи $s2 арканної шкоди всім гравцям і відкидаючи їх назад. На місцях гравців багаторазово розверзаються тріщини, кожна з яких завдає $388546s1 арканної шкоди в межах $388546A1 м." },
    { en = "Vexamus infuses up to $s2 players with explosive mana, inflicting $386181s1 Arcane damage every $386181t1 sec for $386181d. Upon expiration, the mana will detonate inflicting $386202s1 Arcane damage within $386202A1 yards and leaving a pool of $@spellname386201 for $386202d.", ua = "Вексамус наповнює до $s2 гравців вибуховою маною, завдаючи $386181s1 арканної шкоди кожні $386181t1 с протягом $386181d. Після закінчення мана детонує, завдаючи $386202s1 арканної шкоди в радіусі $386202A1 м і лишаючи калюжу $@spellname386201 на $386202d." },
    { en = "Heal an ally for $s1.", ua = "Зцілює союзника на $s1." },
    { en = "The Overgrown Ancient stomps its target with crushing force, inflicting $s1 Physical damage and increasing Physical damage taken by $s2% for $d.", ua = "Зарослий Прадавній топче свою ціль нищівною силою, завдаючи $s1 фізичної шкоди й збільшуючи отримувану фізичну шкоду на $s2% на $d." },
    { en = "The Hungry Lasher's attacks have a chance to poison the target, inflicting $s1 Nature damage every $t1 sec for $d. This effect stacks.", ua = "Атаки голодного шмагача мають шанс отруїти ціль, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Splinters erupt from the Ancient as its branch is torn away, causing all players to bleed for $s1 every $t1 sec for $d. This effect stacks.", ua = "Скалки вибухають з Прадавнього, коли від нього відривають гілку, через що всі гравці кровоточать, отримуючи $s1 кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "The Overgrown Ancient throws one of its own branches at a location, inflicting $s1 Physical damage to players within $a1 yds and knocking them back.\n\n\n\nThe Ancient Branch then animates and attacks players.", ua = "Розрослий Прадавній кидає одну зі своїх власних гілок у певне місце, завдаючи $s1 фізичної шкоди гравцям у межах $a1 ярдів і відкидаючи їх.\n\n\n\nГілка Прадавнього потім оживає й атакує гравців." },
    { en = "Upon death, release a spark of life energy that bursts after $396720d, healing allies and players within $a1 yds for $s1, and removing all applications of $@spellname396716.", ua = "Після загибелі вивільняє іскру життєвої енергії, що вибухає за $396720d, зцілюючи союзників і гравців у межах $a1 м на $s1 і знімаючи всі накладення $@spellname396716." },
    { en = "Upon reaching 100 energy, the Overgrown Ancient releases its abundant life magic to awaken all dormant Lashers, inflicting $s1 Nature damage to all players as they burst free from the ground.", ua = "Сягнувши 100 енергії, Зарослий Прадавній вивільняє свою щедру магію життя, щоб пробудити всіх дрімотних Батіжників, які завдають $s1 шкоди від сил природи всім гравцям, вириваючись із землі." },
    { en = "The Overgrown Ancient forces dormant lasher seeds beneath all players' feet to sprout every $388796t1 sec for $388796d.\n\n\n\nEach emerging seed inflicts $s1 Physical damage to players within $a1 yds and knocks them back, then leaves behind a dormant Hungry Lasher.", ua = "Розрослий Прадавній змушує приспані насінини батожника під ногами всіх гравців проростати кожні $388796t1 сек. протягом $388796d.\n\n\n\nКожна насінина, що сходить, завдає $s1 фізичної шкоди гравцям у межах $a1 ярдів і відкидає їх, а потім лишає по собі приспаного Голодного Батожника." },
    { en = "The goal erupts in flames, launching several motes of fire at the arena. \n\n\n\nEach mote inflicts $376449s1 Fire damage and stuns players for $376449D within $376449A1 yards of where it lands.\n\n\n\nThe Firestorm also stuns Crawth and makes her take $376781s2% increased damage for $376781D and afflicts her with $@spellname1285508.", ua = "Ціль спалахує полум'ям, метаючи кілька вогняних частинок на арену. \n\n\n\nКожна частинка завдає $376449s1 вогняної шкоди й приголомшує гравців на $376449D у радіусі $376449A1 м від місця приземлення.\n\n\n\nВогняна Буря також приголомшує Кравт і змушує її отримувати на $376781s2% більше шкоди протягом $376781D та вражає її $@spellname1285508." },
    { en = "Fire emits searing heat that inflicts $s1 Fire damage every $1285508t1 sec to all players.", ua = "Вогонь випромінює пекучий жар, що завдає $s1 вогняної шкоди кожні $1285508t1 с усім гравцям." },
    { en = "Crawth releases a loud screech, causing a sonic eruption at all players, inflicting $377009s1 Nature damage.\n\n\n\nThis effect interrupts spell casts and also silences any player interrupted in this manner for $377008d.", ua = "Кравт видає гучний вереск, спричиняючи звукове виверження на всіх гравців і завдаючи $377009s1 шкоди від сил природи.\n\n\n\nЦей ефект перериває прочитання заклять, а також змушує замовкнути будь-якого перерваного в такий спосіб гравця на $377008d." },
    { en = "Crawth viciously pecks at her target, inflicting $s1 Physical damage instantly with an additional $s2 Physical damage every $t2 sec for $d.", ua = "Кравт люто дзьобає свою ціль, миттєво завдаючи $s1 фізичної шкоди й додаткові $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Scoring $s1 points in the $@spellname389481 triggers a $@spellname376448.", ua = "Набравши $s1 очок у $@spellname389481, спрацьовує $@spellname376448." },
    { en = "Crawth faces a random player and flaps her wings, inflicting $s3 Nature damage and knocking back all players in front of her.", ua = "Кравт повертається до випадкового гравця й махає крилами, завдаючи $s3 шкоди від сил природи й відкидаючи всіх гравців перед собою." },
    { en = "Scoring $s1 points in the $@spellname389483 triggers $@spellname376467.", ua = "Набравши $s1 очок у $@spellname389483, спрацьовує $@spellname376467." },
    { en = "Crawth releases a loud screech, causing a sonic eruption at all player locations, inflicting $377009s1 Nature damage and additional $377009s2 Nature damage every $377009t2 sec for $377009d to all players within $377009A1 yards of each location.\n\n\n\nThis effect interrupts spell casts and also silences any player interrupted in this manner for $377008d.", ua = "Кравт видає гучний вереск, спричиняючи звуковий вибух у місцях усіх гравців, завдаючи $377009s1 шкоди від сил природи і додатково $377009s2 шкоди від сил природи кожні $377009t2 с протягом $377009d усім гравцям у радіусі $377009A1 м від кожного місця.\n\n\n\nЦей ефект перериває творіння заклять, а також робить німим будь-якого гравця, перерваного в такий спосіб, на $377008d." },
    { en = "At 75% and 45% health, Crawth unleashes a devasting gust of winds every $t1 sec, inflicting $1276770s1 Nature damage to all players and knocking them back.", ua = "При 75% і 45% здоров'я Кравт вивільняє нищівний порив вітру кожні $t1 с, завдаючи $1276770s1 шкоди від сил природи всім гравцям і відкидаючи їх." },
    { en = "Fierce winds rush out of the goal, knocking Crawth in the air and pushing players back and summoning Roving Cyclones.\n\n\n\nEach mote can be picked up to grant $376760s1% Haste and $376760s2% movement speed for $376760d. This effect also provides immunity to being pushed by $@spellname376467.", ua = "З цілі вириваються лютий вітер, підкидаючи Кравт у повітря, відштовхуючи гравців назад і прикликаючи Мандрівних Циклонів.\n\n\n\nКожну частинку можна підібрати, щоб отримати $376760s1% Поспіху й $376760s2% швидкості пересування на $376760d. Цей ефект також надає несприйнятливість до відштовхування від $@spellname376467." },
    { en = "Creates cyclones that move around, inflicting $s1 Nature damage and knocking back any player it contacts.", ua = "Створює циклони, що рухаються довкола, завдаючи $s1 шкоди від сил природи й відкидаючи будь-якого гравця, до якого торкаються." },
    { en = "The goals of The Pitch activate, allowing players to score points in either the Goal of the Searing Blaze or the Goal of the Rushing Winds.", ua = "Цілі на Полі активуються, дозволяючи гравцям заробляти очки у Воротах Палючого Полум'я чи у Воротах Рвучких Вітрів." },
    { en = "The Echo of Doragosa unleashes powerful arcane energy, inflicting $s1 Arcane damage to all players and opening $@spellname388901s in nearby locations.", ua = "Відлуння Дораґоси вивільняє потужну арканну енергію, завдаючи $s1 арканної шкоди всім гравцям і відкриваючи $@spellname388901s у сусідніх місцях." },
    { en = "The excess power coalesces into a rift of arcane energy, inflicting $389007s1 Arcane damage every $389007t1 sec to players within. This rift occasionally releases $@spellname388951.", ua = "Надлишок сили зливається в розлом арканної енергії, завдаючи $389007s1 арканної шкоди кожні $389007t1 с гравцям усередині. Цей розлом час від часу вивільняє $@spellname388951." },
    { en = "The Echo of Doragosa blasts the target player with powerful arcane energy, inflicting $s1 Arcane damage and applying $@spellname389011.", ua = "Відлуння Дораґоси вражає цільового гравця потужною арканною енергією, завдаючи $s1 арканної шкоди та накладаючи $@spellname389011." },
    { en = "The Echo of Doragosa inflicts $s1 Arcane damage to a player.\n\n\n\nApplies $@spellname389011 to the target.", ua = "Відлуння Дораґоси завдає $s1 арканної шкоди гравцеві.\n\n\n\nНакладає на ціль $@spellname389011." },
    { en = "The Echo of Doragosa marks random players with arcane energy for $374350d.  When the $@spellname374352 expires, it inflicts $s1 Arcane damage to all players within $A1 yards.\n\n\n\nApplies $@spellname389011 to the target.", ua = "Відлуння Дораґоси позначає випадкових гравців арканною енергією на $374350d. Коли $@spellname374352 завершується, воно завдає $s1 арканної шкоди всім гравцям у радіусі $A1 м.\n\n\n\nЗастосовує до цілі $@spellname389011." },
    { en = "The Echo of Doragosa's arcane attacks leave wild energy on players they hit, inflicting $s3 Arcane damage every $t3 sec and increasing their Haste $s1%. This effect stacks.\n\n\n\nAt 3 applications, this effect erupts into an Arcane Rift.", ua = "Арканні атаки Відлуння Дораґоси лишають дику енергію на гравцях, яких уражають, завдаючи $s3 арканної шкоди кожні $t3 с і підвищуючи їхній Поспіх на $s1%. Цей ефект накопичується.\n\n\n\nПри 3 накопиченнях цей ефект вибухає Арканним Розломом." },
    { en = "The Echo of Doragosa pulls all players to her location, then strikes with explosive energy inflicting $s1 Arcane damage and knocking back all players within $a1 yards.\n\n\n\nApplies $@spellname389011 to anyone hit.", ua = "Відлуння Дораґоси притягує всіх гравців до свого місцеперебування, тоді вдаряє вибуховою енергією, завдаючи $s1 арканної шкоди й відкидаючи всіх гравців у радіусі $a1 м.\n\n\n\nНакладає $@spellname389011 на кожного враженого." },
    { en = "Wild Magic explodes on contact with a player, inflicting $s1 Arcane damage to players within $A1 yds.\n\n\n\nApplies $@spellname389011 to all targets struck.", ua = "Дика Магія вибухає при контакті з гравцем, завдаючи $s1 арканної шкоди гравцям у межах $A1 ярдів.\n\n\n\nНакладає $@spellname389011 на всі вражені цілі." },
    { en = "The Echo of Doragosa pulls all players to her location, then strikes with explosive energy inflicting $388822s1 Arcane damage and knocking back all players within $388822a1 yards.", ua = "Відлуння Дораґоси притягує всіх гравців до свого місцеперебування, тоді вдаряє вибуховою енергією, завдаючи $388822s1 арканної шкоди й відкидаючи всіх гравців у радіусі $388822a1 м." },
    { en = "The Echo of Doragosa inflicts $373326s1 Arcane damage to a player.", ua = "Відлуння Дораґоси завдає $373326s1 арканної шкоди гравцеві." },
    { en = "The Echo of Doragosa marks a player arcane energy for $374350d.  When the $@spellname374352 expires, it inflicts $374352s1 Arcane damage to all players within $374352A1 yards.", ua = "Відлуння Дораґоси позначає гравця арканною енергією на $374350d. Коли $@spellname374352 завершується, воно завдає $374352s1 арканної шкоди всім гравцям у радіусі $374352A1 м." },
    { en = "Upon reaching 100 energy, Zuraal begins to gather void energy around himself, pulling all players and Coalesced Void in. Zuraal unleashes the gathered void energy after 5 sec, inflicting $s1 Shadow damage to all players and knocking them back.", ua = "Сягнувши 100 енергії, Зураал починає збирати енергію Порожнечі довкола себе, притягуючи всіх гравців і Згущену Порожнечу. Зураал вивільняє зібрану енергію Порожнечі за 5 с, завдаючи $s1 тіньової шкоди всім гравцям і відкидаючи їх назад." },
    { en = "Zuraal infuses his fist with void energy and lashes out, inflicting $s1 Shadow damage to their target and creating a pool of $@spellname244588 at their location.", ua = "Зураал наповнює свій кулак енергією Порожнечі й завдає удару, завдаючи $s1 тіньової шкоди цілі та створюючи калюжу $@spellname244588 у її місці." },
    { en = "Zuraal slams the ground with void energy, inflicting $s1 Shadow damage to all players and inflicting additional $s2 Shadow damage every $t2 sec for $d.\n\n\n\nThe slam also spawns Coalesced Void in nearby locations.", ua = "Зураал б'є об землю енергією Порожнечі, завдаючи $s1 тіньової шкоди всім гравцям і додаткові $s2 тіньової шкоди кожні $t2 с протягом $d.\n\n\n\nУдар також породжує згущену Порожнечу в довколишніх місцях." },
    { en = "A pool of volatile void that inflicts $s1 Shadow damage every $t1 sec.", ua = "Калюжа летючої Порожнечі, що завдає $s1 тіньової шкоди кожні $t1 с." },
    { en = "Zuraal unleashes three powerful swipes at his target, inflicting $1263484s1  Physical damage twice with another final strike inflicting $1263494s1 Shadow damage.", ua = "Зураал обрушує три потужні удари на свою ціль, завдаючи $1263484s1 фізичної шкоди двічі та останнім ударом завдаючи $1263494s1 тіньової шкоди." },
    { en = "Zuraal releases a cresting wave of chaotic magic, inflicting $s2 Shadow damage to all players in front of himself.", ua = "Зураал вивільняє наростаючу хвилю хаотичної магії, завдаючи $s2 тіньової шкоди всім гравцям перед собою." },
    { en = "Explodes in a shower of void energy, inflicting $s1 Shadow to all enemies and additional $s2 Shadow damage every $t2 sec for $d.", ua = "Вибухає зливою енергії Порожнечі, завдаючи $s1 тіньової шкоди всім ворогам і додатково $s2 тіньової шкоди кожні $t2 с протягом $d." },
    { en = "When the Coalesced Void is killed, it leaves behind a pool of Void Sludge at its location.", ua = "Коли Згущену Порожнечу вбито, вона залишає по собі калюжу Слизу Порожнечі на своєму місці." },
    { en = "Saprish creates void shades that dash towards each player, inflicting $s1 Shadow damage to all players within $a1 yards of impact. This effect detonates all $@spellname246026 hit, triggering $@spellname1263508.", ua = "Сапріш створює тіні Порожнечі, які кидаються до кожного гравця, завдаючи $s1 тіньової шкоди всім гравцям у радіусі $a1 м від місця удару. Цей ефект детонує кожен уражений $@spellname246026, активуючи $@spellname1263508." },
    { en = "Saprish releases a massive blast, inflicting $s1 Shadow damage to all players and $s2 Shadow damage every $t2 sec for $d.\n\n\n\nThis blast ignites all Void Bombs, inflicting $1263526s1 Shadow damage to all players and applying $@spellname1268840.", ua = "Сапріш вивільняє потужний вибух, завдаючи $s1 тіньової шкоди всім гравцям і $s2 тіньової шкоди кожні $t2 с протягом $d.\n\n\n\nЦей вибух підриває всі бомби Порожнечі, завдаючи $1263526s1 тіньової шкоди всім гравцям і накладаючи $@spellname1268840." },
    { en = "Void seeps into target player, increasing their Shadow damage taken by $s1% for $d. This effect stacks.", ua = "Порожнеча просочується в ціль, підвищуючи отримувану нею тіньову шкоду на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Saprish throws void bombs at nearby player locations. Upon contact with a player, the bomb explodes and inflicts $s2 Shadow damage to players within $a1 yards and additional $s1 Shadow damage every $t1 sec for $d.", ua = "Сапріш кидає бомби Порожнечі в місця поблизу гравців. При контакті з гравцем бомба вибухає й завдає $s2 тіньової шкоди гравцям у радіусі $a1 ярдів і додатково $s1 тіньової шкоди кожні $t1 с протягом $d." },
    { en = "Darkfang pounces on a player, inflicting $s1 Physical damage and additional $s2 Physical damage every $t2 sec for $d.", ua = "Даркфенг накидається на гравця, завдаючи $s1 фізичної шкоди й додаткові $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Saprish's melee attacks inflict an additional $s1 Shadow damage.", ua = "Атаки ближнього бою Сапріша завдають додатково $s1 тіньової шкоди." },
    { en = "The $@spellname246026 releases a wave of void energy, inflicting $s1 Shadow damage to all players.", ua = "$@spellname246026 вивільняє хвилю енергії Порожнечі, завдаючи $s1 тіньової шкоди всім гравцям." },
    { en = "Shadewing swoops down on a random player, inflicting $248829s1 Physical damage. After reaching their destination, Shadewing releases a $@spellname248831.", ua = "Тінекрил налітає на випадкового гравця, завдаючи $248829s1 фізичної шкоди. Досягнувши цілі, Тінекрил вивільняє $@spellname248831." },
    { en = "Shadewing releases a piercing screech, inflicting $s1 Shadow damage and disorienting all players for $d.", ua = "Шейдвінг видає пронизливий вереск, завдаючи $s1 тіньової шкоди й дезорієнтуючи всіх гравців на $d." },
    { en = "Void waves inflict $s1 Shadow damage with an additional $s2 Shadow damage every $t2 sec for $d to players struck.", ua = "Хвилі Порожнечі завдають $s1 тіньової шкоди та додатково $s2 тіньової шкоди кожні $t2 с протягом $d враженим гравцям." },
    { en = "Raging storm that inflicts $s1 Shadow damage every $1263529t1 sec for $1263529d. \n\n\n\nAdditionally, players inside the storm are suffer an additional $1263532s1 Shadow damage every $1263532t1 sec.", ua = "Лютий шторм, що завдає $s1 тіньової шкоди кожні $1263529t1 с протягом $1263529d. \n\n\n\nКрім того, гравці всередині шторму зазнають додаткової $1263532s1 тіньової шкоди кожні $1263532t1 с." },
    { en = "At 100 energy, Nezhar teleports to the center of the room, knocking all players back$?diff1|diff2[.]$?diff8[ while continuously pushing them with $@spellname1263533.] Void energy begins to collapse towards Nezhar, forming a $@spellname1265030 after $1263529s1 sec.", ua = "Сягнувши 100 енергії, Нежар телепортується в центр кімнати, відкидаючи всіх гравців назад$?diff1|diff2[.]$?diff8[ і безперервно відштовхуючи їх за допомогою $@spellname1263533.] Енергія Порожнечі починає стягуватися до Нежара, утворюючи $@spellname1265030 за $1263529s1 с." },
    { en = "Viceroy Nezhar pushes players back with powerful force.", ua = "Віцекороль Нежар відкидає гравців потужною силою." },
    { en = "Viceroy Nezhar summons a gate to the void that unleashes Umbral Waves.", ua = "Віцекороль Нежар прикликає браму до Порожнечі, що вивільняє Тіньові Хвилі." },
    { en = "Viceroy Nezhar hurls a bolt of void energy at his target, inflicting $s1 Shadow damage.", ua = "Віцекороль Нежар жбурляє в ціль блискавку енергії Порожнечі, завдаючи $s1 тіньової шкоди." },
    { en = "Nezhar summons void tentacles from underneath the ground.", ua = "Нежар прикликає щупальця Порожнечі з-під землі." },
    { en = "Viceroy Nezhar infuses players with void energy, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Віцекороль Нежар наповнює гравців енергією Порожнечі, завдаючи $s1 тіньової шкоди кожні $t1 с протягом $d." },
    { en = "Void tentacle tears into reality, inflicting $s1 Shadow damage to all players.", ua = "Щупальце Порожнечі вривається в реальність, завдаючи $s1 тіньової шкоди всім гравцям." },
    { en = "The Umbral Tentacle assaults a player's mind, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Тіньове щупальце атакує розум гравця, завдаючи $s1 тіньової шкоди кожні $t1 с протягом $d." },
    { en = "L'ura channels revolving void beams, inflicting $s1 Shadow damage to players struck.", ua = "Л'ура спрямовує обертові промені Порожнечі, завдаючи $s1 тіньової шкоди враженим гравцям." },
    { en = "L'ura passively tears open a rift to the void every $t1 sec. After 3 rifts are opened, L'ura summons an $@spellname1267207 from each of them, inflicting $1268598s1 Shadow damage to her target for each lance. This effect closes the rifts.", ua = "L'ura пасивно розриває розлом до Порожнечі кожні $t1 с. Коли відкрито 3 розломи, L'ura прикликає з кожного по $@spellname1267207, завдаючи своїй цілі $1268598s1 тіньової шкоди за кожен спис. Цей ефект закриває розломи." },
    { en = "L'ura sings her dark song, inflicting $1265420s1 Shadow damage to all players every $1265419t1 sec for $1265419d. This song creates multiple $@spellname1265420.", ua = "Л'ура співає свою темну пісню, завдаючи $1265420s1 тіньової шкоди всім гравцям кожні $1265419t1 с протягом $1265419d. Ця пісня створює кілька примірників $@spellname1265420." },
    { en = "L'ura performs the $@spellname1265421, immediately inflicting $s1 Shadow damage to all players. This song causes all $@spellname1265420 to radiates $1265424s1 Shadow damage every $1265422t2 sec until they are silenced.", ua = "Л'ура виконує $@spellname1265421, негайно завдаючи $s1 тіньової шкоди всім гравцям. Ця пісня змушує всі $@spellname1265420 випромінювати $1265424s1 тіньової шкоди кожні $1265422t2 с, доки їх не зроблять німими." },
    { en = "Alleria drains the power of L'ura, stunning her and increasing her damage taken by $s2% for $d.", ua = "Аллерія викачує силу з Л'ури, оглушуючи її та збільшуючи отримувану нею шкоду на $s2% на $d." },
    { en = "L'ura breaks out of Alleria's hold and unleashes a wave of void energy that inflicts $s1 Shadow damage to all players, knocking them back.", ua = "L'ura виривається з-під контролю Аллерії й вивільняє хвилю енергії Порожнечі, що завдає $s1 тіньової шкоди всім гравцям, відкидаючи їх назад." },
    { en = "$@spellname1265419 cause players to become vulnerable to the effects of $@spellname1265421, increasing damage taken from it by $s1%. This effect stacks.", ua = "$@spellname1265419 робить гравців вразливими до ефектів $@spellname1265421, збільшуючи отримувану від нього шкоду на $s1%. Цей ефект накопичується." },
    { en = "L'ura channels the Eternal Night, attempting to instantly kill all players.", ua = "Л'ура підтримує Вічну Ніч, намагаючись миттєво вбити всіх гравців." },
    { en = "L'ura blasts target players with sonic energy, inflicting $s1 Physical damage to all players in the line and silencing any $@spellname1265420 hit. This damage ignores armor.", ua = "Л'ура вражає цільових гравців звуковою енергією, завдаючи $s1 фізичної шкоди всім гравцям на лінії та роблячи німою будь-яку вражену $@spellname1265420. Ця шкода ігнорує броню." },
    { en = "L'ura shifts the $@spellname1265419 and begins a $@spellname1265689 for $1265589d, inflicting $1271666s1 to players within $1271666a1 yards of each active $@spellname1265420$?diff1|diff2[.]$?diff8[.\n\nEach active $@spellname1265420 afflicts players with $@spellname1265650 every $1265589t3 sec until the $@spellname1265419 are destroyed.]", ua = "Л'ура зміщує $@spellname1265419 й розпочинає $@spellname1265689 на $1265589d, завдаючи $1271666s1 гравцям у радіусі $1271666a1 м від кожної активної $@spellname1265420$?diff1|diff2[.]$?diff8[.\n\nКожна активна $@spellname1265420 вражає гравців $@spellname1265650 кожні $1265589t3 с, доки $@spellname1265419 не знищать.]" },
    { en = "$@spellname467120 react to the winds from $@spellname465904, ejecting fiery tornadoes that inflict $470212s1 Fire damage to players struck and stun players hit for $470212d before tossing them away.", ua = "$@spellname467120 реагують на вітри від $@spellname465904, викидаючи вогняні торнадо, що завдають $470212s1 вогняної шкоди враженим гравцям і приголомшують уражених гравців на $470212d, перш ніж відкинути їх геть." },
    { en = "Emberdawn breathes a cone of fire towards a player, inflicting $s1 Fire damage to players hit.", ua = "Ембердон видихає конус вогню в напрямку гравця, завдаючи $s1 вогняної шкоди враженим гравцям." },
    { en = "Emberdawn conjures a flaming windstorm that inflicts $466888s2 Fire damage every $466888t2 sec to all players and pushes them for $d.", ua = "Ембердон прикликає полум'яну бурю, що завдає $466888s2 вогняної шкоди кожні $466888t2 с усім гравцям і відштовхує їх протягом $d." },
    { en = "Fiery remains inflict $472118s1 Fire damage every $472118t1 sec to players within. The patch's central updraft inflicts inflicts $465957s1 Fire damage to players who touch it, knocking them away.", ua = "Вогняні рештки завдають $472118s1 вогняної шкоди щосекунди ($472118t1) гравцям, що стоять усередині. Висхідний потік у центрі калюжі завдає $465957s1 вогняної шкоди гравцям, які торкаються його, і відкидає їх." },
    { en = "Emberdawn pecks her current target, inflicting $s1 Physical damage and an additional $466091s1 Fire damage every $466091t1 sec for $466091d.", ua = "Ембердон дзьобає свою поточну ціль, завдаючи $s1 фізичної шкоди й додаткові $466091s1 вогняної шкоди кожні $466091t1 с протягом $466091d." },
    { en = "Emberdawn spits fire at a player, inflicting $466559s1 Fire damage every $466559t1 sec for $466559d. Upon expiration, the fire forms into a flaming patch that inflicts $472118s1 Fire damage every $472118t1 sec to players within it. \n\n\n\nThe patch's central updraft inflicts $465957s1 Fire damage to players who touch it, knocking them away.", ua = "Ембердон плює вогнем у гравця, завдаючи $466559s1 вогняної шкоди кожні $466559t1 с протягом $466559d. Після завершення вогонь утворює палаючу пляму, що завдає $472118s1 вогняної шкоди кожні $472118t1 с гравцям у ній. \n\n\n\nЦентральний висхідний потік плями завдає $465957s1 вогняної шкоди гравцям, що його торкаються, відкидаючи їх." },
    { en = "Kalis continually releases piercing shrieks, inflicting $1219491s1 Shadow damage to all players every $t1 sec and increasing their damage taken from $@spellname472736 by $1219491s2% for $1219491d. This effect stacks.\n\n\n\nLatch's $@spellname472795 interrupts this ability.", ua = "Каліс безперервно видає пронизливі крики, завдаючи $1219491s1 тіньової шкоди всім гравцям кожні $t1 с і збільшуючи шкоду, яку вони отримують від $@spellname472736, на $1219491s2% протягом $1219491d. Цей ефект накопичується.\n\n\n\n$@spellname472795 Латча перериває цю здібність." },
    { en = "Latch's bile inflicts $1282272s1 Nature damage to players hit every $1282272t1 sec for $1282272d.", ua = "Жовч Засова завдає $1282272s1 шкоди від сил природи враженим гравцям кожні $1282272t1 с протягом $1282272d." },
    { en = "Incorporeal darkness reduces damage taken by $s2%.", ua = "Безтілесна темрява знижує отриману шкоду на $s2%." },
    { en = "Latch strikes the hooked player, inflicting $s1 Physical damage and stunning them for $d.", ua = "Латч вражає зачепленого гравця, завдаючи $s1 фізичної шкоди й приголомшуючи його на $d." },
    { en = "Latch spews bile onto players, inflicting $472758s1 Nature damage to players within $472758A1 yards of each impact and applying $@spellname1282272.\n\n\n\n$@spellname472777 forms at the impact locations.", ua = "Засов плює жовчю на гравців, завдаючи $472758s1 шкоди від сил природи гравцям у радіусі $472758A1 ярдів від кожного влучання й накладаючи $@spellname1282272.\n\n\n\nУ місцях влучання утворюється $@spellname472777." },
    { en = "Latch's bile coats the ground, inflicting $s1 Nature damage every $t1 sec to players within it and increasing their damage taken from $@spellname472745 by $s3%.", ua = "Жовч Латча вкриває землю, завдаючи $s1 шкоди від сил природи кожні $t1 с гравцям у ній і збільшуючи шкоду, яку вони отримують від $@spellname472745, на $s3%." },
    { en = "Kalis inflicts $s1 Shadow damage to a player.", ua = "Каліс завдає $s1 тіньової шкоди гравцеві." },
    { en = "Latch chops his primary target, inflicting $474065s1 Physical damage every ${$t1}.2 sec for $d.", ua = "Латч рубає свою основну ціль, завдаючи $474065s1 фізичної шкоди кожні ${$t1}.2 с протягом $d." },
    { en = "Kalis curses players, causing Dark Entities to fixate upon them for $1215803d.", ua = "Каліс проклинає гравців, змушуючи Темних Сутностей зосереджуватися на них протягом $1215803d." },
    { en = "Latch throws a hook towards a player, pulling the first target hit to his location. If a player is struck, Latch follows up with $@spellname474075.", ua = "Латч кидає гак у гравця, притягуючи першу вражену ціль до свого місця. Якщо гравець вражений, Латч продовжує $@spellname474075." },
    { en = "When either Kalis or Latch falls in battle, the other becomes incensed, increasing their damage done by $s1% every $1219554t1 sec.", ua = "Коли Каліс або Латч падає в бою, інший шаленіє, збільшуючи завдану ним шкоду на $s1% кожні $1219554t1 с." },
    { en = "Commander Kroluk bellows an intimidating shout, causing players who stand alone to run in fear and suffer $1253030s2 Shadow damage every $1253030t2 sec for $1253030d.", ua = "Командувач Кролук видає залякувальний крик, через що гравці, які стоять самотою, тікають у страху й зазнають $1253030s2 тіньової шкоди кожні $1253030t2 с протягом $1253030d." },
    { en = "Commander Kroluk fortifies himself, reducing his damage taken by 99%.", ua = "Командувач Кролук укріплює себе, знижуючи отримувану шкоду на 99%." },
    { en = "Commander Kroluk focuses his destructive urge on his current target, repeatedly thrashing them and inflicting $467621s1 Physical damage every $t1 sec for $d.", ua = "Командувач Кролук зосереджує свій руйнівний порив на поточній цілі, раз по раз молотячи її та завдаючи $467621s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "The Spectral Axethrower throws an axe at a player, inflicting $s1 Physical damage and causing them to bleed for $s2 Physical damage every $t2 sec for $d.", ua = "Примарний Сокирометальник кидає сокиру в гравця, завдаючи $s1 фізичної шкоди й змушуючи його кровоточити, отримуючи $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Commander Kroluk unleashes a bloodthirsty warcry, inflicting $468221s1 Physical damage to all players and summoning a warparty to fight alongside him.", ua = "Командувач Кролук вивільняє кровожерливий бойовий клич, завдаючи $468221s1 фізичної шкоди всім гравцям і прикликаючи бойову ватагу, що б'ється поруч із ним." },
    { en = "The Haunting Grunt charges toward their current target and inflicts $s2 Physical damage.", ua = "Примарний грунт мчить до своєї поточної цілі й завдає $s2 фізичної шкоди." },
    { en = "The Phantasmal Mystic sends lightning into a player, inflicting $s1 Nature damage. The lightning then jumps to the closest other player.", ua = "Примарний Містик спрямовує блискавку в гравця, завдаючи $s1 шкоди від сил природи. Далі блискавка перестрибує на найближчого іншого гравця." },
    { en = "Commander Kroluk recklessly leaps towards the furthest player, inflicting $472054s1 Physical damage and an additional $472054s2 Physical damage every $472054t2 sec for $472054d to players within $472054A1 yards of the impact location. \n\n\n\nThe force of the impact causes $@spellname1283357.", ua = "Командувач Кролук нерозважливо стрибає до найдальшого гравця, завдаючи $472054s1 фізичної шкоди й додаткові $472054s2 фізичної шкоди кожні $472054t2 с протягом $472054d гравцям у радіусі $472054A1 м від місця удару. \n\n\n\nСила удару спричиняє $@spellname1283357." },
    { en = "Commander Kroluk enters a battle-trance, fixating on a player and inflicting $468924s1 Physical damage every $468924t1 sec to players within $s2 yards.\n\n\n\nCommander Kroluk continues to $@spellname470963 until his warparty is defeated.", ua = "Командир Кролук впадає в бойовий транс, зосереджуючись на гравцеві й завдаючи $468924s1 фізичної шкоди кожні $468924t1 с гравцям у межах $s2 м.\n\n\n\nКомандир Кролук продовжує $@spellname470963, доки його бойову ватагу не буде знищено." },
    { en = "The Phantasmal Mystic unleashes a nova of flame, inflicting $s1 Fire damage to all players.", ua = "Примарний Містик вивільняє вогняну нову, завдаючи $s1 вогняної шкоди всім гравцям." },
    { en = "Falling debris rains from the ceiling, inflicting $s1 Nature damage to players within $A1 yards of each impact location.", ua = "Зі стелі сиплеться уламкова злива, завдаючи $s1 шкоди від сил природи гравцям у радіусі $A1 м від кожного місця удару." },
    { en = "The Restless Heart fires a salvo of arrows towards a player for $d, inflicting $472672s1 Nature damage every $t1 sec to players in a frontal cone.", ua = "Невгамовне Серце випускає залп стріл по гравцеві протягом $d, завдаючи $472672s1 шкоди від сил природи кожні $t1 с гравцям у фронтальному конусі." },
    { en = "The Restless Heart marks players with wind-infused arrows. After $1253979d, the arrows unleash a wind gust, inflicting $1253978s1 Nature damage to players within $1253978A1 yards and an additional $1253978s2 Nature damage every $1253978t2 sec for $1253978d.$?diff8|diff23[\n\n\n\nThe wind gust destroys any $@spellname1282932 hit.][]", ua = "Неспокійне Серце позначає гравців стрілами, наповненими вітром. Через $1253979d стріли вивільняють пориви вітру, завдаючи $1253978s1 шкоди від сил природи гравцям у радіусі $1253978A1 м і додатково $1253978s2 шкоди від сил природи кожні $1253978t2 с протягом $1253978d.$?diff8|diff23[\n\n\n\nПорив вітру руйнує будь-яку вражену $@spellname1282932.][]" },
    { en = "Stormy energy lashes outward when the Restless Heart leaps, inflicting $s1 Nature damage to all players and an additional $1283371s2 Nature damage every $t2 sec.\n\n\n\nContacting $@spellname1253977 removes this affliction.", ua = "Штормова енергія шмагає назовні, коли Невгамовне Серце стрибає, завдаючи $s1 шкоди від сил природи всім гравцям і додатково $1283371s2 шкоди від сил природи кожні $t2 с.\n\n\n\nКонтакт із $@spellname1253977 знімає цю недугу." },
    { en = "The Restless Heart shoots a rain of arrows, inflicting $472634s1 Nature damage to players within $472634A1 yards of each impact and forming $@spellname472635.", ua = "Невгамовне Серце випускає зливу стріл, завдаючи $472634s1 шкоди від сил природи гравцям у межах $472634A1 м від кожного влучання й утворюючи $@spellname472635." },
    { en = "The Restless Heart fires an arrow at a location in its chamber, inflicting $734277s1 Nature damage to players within $734277A1 yards of impact and forming $@spellname468442.", ua = "Невгамовне Серце випускає стрілу в позицію у своїй залі, завдаючи $734277s1 шкоди від сил природи гравцям у межах $734277A1 м від влучання й утворюючи $@spellname468442." },
    { en = "A stormy spirit inflicts $1282955s1 Nature damage to players standing within its storm pool every $1282955t1 sec. $@spellname1253986 quells these spirits.", ua = "Штормовий дух завдає $1282955s1 шкоди від сил природи гравцям, що стоять у його штормовій калюжі, кожні $1282955t1 с. $@spellname1253986 втихомирює цих духів." },
    { en = "The Restless Heart knocks away its primary target, inflicting $s1 Physical damage and increasing their Physical damage taken by $s3% for $d.\n\n\n\nAfterward, The Restless Heart fires a $@spellname1253986.", ua = "Невгамовне Серце відкидає свою основну ціль, завдаючи $s1 фізичної шкоди й збільшуючи отримувану нею фізичну шкоду на $s3% на $d.\n\n\n\nПісля цього Невгамовне Серце випускає $@spellname1253986." },
    { en = "The windy arrow detonates upon contact with a player, inflicting $s2 Nature damage and knocking them upwards.\n\n\n\nThe detonation removes $@spellname1216042$?diff23|diff8[, forming a $@spellname1282932.][.]", ua = "Вітряна стріла детонує при контакті з гравцем, завдаючи $s2 шкоди від сил природи й підкидаючи його вгору.\n\n\n\nДетонація знімає $@spellname1216042$?diff23|diff8[, утворюючи $@spellname1282932.][.]" },
    { en = "A ring of violent wind expands, inflicting $s1 Nature damage every $t1 sec to players who touch it and stunning them for $d.", ua = "Кільце шаленого вітру розширюється, завдаючи $s1 шкоди від сил природи кожні $t1 с гравцям, що його торкаються, і приголомшуючи їх на $d." },
    { en = "Muro'jin's defeat sends Nekraxx into a frenzy, increasing her damage done by $s1% every $1249947t1 sec. This effect stacks.", ua = "Поразка Муро'джина вганяє Некраксс у несамовитість, збільшуючи завдану нею шкоду на $s1% кожні $1249947t1 с. Цей ефект накопичується." },
    { en = "Muro'jin fixes his aim on a player for $d, firing a spray of venomous arrows in a frontal cone toward them every $t1 sec. The volley inflicts $1260648s1 Plague damage to players struck and applies $@spellname1260709.", ua = "Муро'джин наводить приціл на гравця на $d, випускаючи на нього розпорошений залп отруйних стріл у фронтальному конусі кожні $t1 с. Залп завдає $1260648s1 чумної шкоди враженим гравцям і накладає $@spellname1260709." },
    { en = "Muro'jin's venom-tipped arrows inhibit targets, reducing their movement speed by $s1% for $d. This effect stacks.", ua = "Отруєні стріли Муро'джина гальмують цілі, зменшуючи їхню швидкість пересування на $s1% на $d. Цей ефект накопичується." },
    { en = "Triggered $@spellname1260731s leave behind a frozen patch that inflicts $1243752s1 Frost damage every $1243752t1 sec to players within and causes them to slide.", ua = "Спрацьовані $@spellname1260731s лишають по собі морозну пляму, що завдає $1243752s1 морозної шкоди кожні $1243752t1 с гравцям у ній і змушує їх ковзати." },
    { en = "Nekraxx charges toward a marked player, inflicting $1249638s1 Shadow damage to players in her path and knocking them upwards.\n\n\n\nIf Nekraxx strikes a player incapacitated by $@spellname1260731, the trap shatters instead, stunning Nekraxx for $1256387d.", ua = "Некраксс кидається на позначеного гравця, завдаючи $1249638s1 тіньової шкоди гравцям на своєму шляху й підкидаючи їх угору.\n\n\n\nЯкщо Некраксс влучить у гравця, знерухомленого $@spellname1260731, пастка натомість розтрощиться, приголомшивши Некраксс на $1256387d." },
    { en = "Muro'jin hurls an axe at players knocked up by $@spellname1249479, inflicting $1249989s1 Physical damage and knocking them further upwards.", ua = "Муро'джин жбурляє сокиру в гравців, підкинутих $@spellname1249479, завдаючи $1249989s1 фізичної шкоди й відкидаючи їх ще вище вгору." },
    { en = "Nekraxx pierces all players with festering feathers, inflicting $s1 Plague damage every $t1 sec for $d.", ua = "Некраксс пронизує всіх гравців гнійними перами, завдаючи $s1 чумної шкоди кожні $t1 с протягом $d." },
    { en = "Muro'jin harpoons behind his current target and hurls a massive spear. The spear inflicts $1266485s1 Physical damage and knocks the target away, applying $@spellname1266488.", ua = "Муро'джин гарпунить позаду своєї поточної цілі й метає величезний спис. Спис завдає $1266485s1 фізичної шкоди й відкидає ціль, застосовуючи $@spellname1266488." },
    { en = "Muro'jin's $@spellname1266480 causes the target to bleed profusely, inflicting $s1 Physical damage every $t1 sec for $d.", ua = "$@spellname1266480 Муро'джина змушує ціль рясно кровоточити, завдаючи $s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Muro'jin throws traps at players which remain for $1243731d. Upon contact, these incapacitate the triggering player for $1243741d. Damage may break the effect.", ua = "Муро'джин кидає пастки в гравців, які лишаються на $1243731d. При контакті вони знешкоджують гравця, який їх спрацював, на $1243741d. Шкода може зняти ефект." },
    { en = "Nekraxx soars to a location and releases a surge of dark energy, inflicting $1243900s1 Shadow damage to players within $1243900a1 yards and flinging quills which inflict $1256247s1 Shadow damage to players within $1256247a1 yards.", ua = "Некракс злітає до місця й вивільняє хвилю темної енергії, завдаючи $1243900s1 тіньової шкоди гравцям у радіусі $1243900a1 м і метаючи голки, що завдають $1256247s1 тіньової шкоди гравцям у радіусі $1256247a1 м." },
    { en = "Muro'jin revives Nekraxx, returning them to life with $1249793s1% of their health.", ua = "Муро'джин оживляє Некраксса, повертаючи його до життя з $1249793s1% здоров'я." },
    { en = "Vordaza siphons the life essence from her current target, inflicting $1251567s1 Shadow damage and absorbing the next $1251568s1 healing received every $t1 sec for $d.", ua = "Вордаза висмоктує життєву есенцію зі своєї поточної цілі, завдаючи $1251567s1 тіньової шкоди й поглинаючи наступні $1251568s1 отриманого зцілення кожні $t1 с протягом $d." },
    { en = "Vordaza's ritual forms masses of soul ichor that flow across the dais, inflicting $1252611s1 Shadow damage to players struck.", ua = "Ритуал Вордази утворює маси душевного іхору, що розтікаються по помості, завдаючи $1252611s1 тіньової шкоди враженим гравцям." },
    { en = "Vordaza wrests fresh sacrifices to do her bidding, manifesting Unstable Phantoms that seek out players.", ua = "Вордаза вириває свіжі жертви, щоб виконати її волю, маніфестуючи Нестабільних Привидів, які вистежують гравців." },
    { en = "The phantom screams when slain, inflicting $s1 Shadow damage to all players.", ua = "Фантом кричить, коли його вбивають, завдаючи $s1 тіньової шкоди всім гравцям." },
    { en = "Vordaza wraps herself in a necrotic barrier, becoming immune to interrupt effects and absorbing the next $1251598s1 damage for $d.", ua = "Вордаза огортає себе некротичним бар'єром, стаючи несприйнятливою до ефектів переривання й поглинаючи наступні $1251598s1 шкоди протягом $d." },
    { en = "$?|diff23[The phantom's incorporeal form reduces their damage taken by $s1%.][The phantom's incorporeal form reduces their damage taken by $s1%, but causes them to lose $s2% health every $t2 sec.]", ua = "$?|diff23[Безтілесна форма привида зменшує отримувану ним шкоду на $s1%.][Безтілесна форма привида зменшує отримувану ним шкоду на $s1%, але змушує його втрачати $s2% здоров'я кожні $t2 с.]" },
    { en = "Final Pursuit's burst haunts players struck, increasing their damage taken from $@spellname1251811 by $s1% for $d.", ua = "Спалах Останньої Гонитви переслідує вражених гравців, збільшуючи шкоду, яку вони отримують від $@spellname1251811, на $s1% протягом $d." },
    { en = "Vordaza protects herself with $@spellname1251598 and unleashes waves of necrotic energy which inflict $1263735s1 Shadow damage to all players every $t2 sec for up to $d. This effect grows in intensity over time.", ua = "Вордаза захищає себе закляттям $@spellname1251598 і вивільняє хвилі некротичної енергії, які завдають $1263735s1 тіньової шкоди всім гравцям кожні $t2 с протягом щонайбільше $d. З часом цей ефект посилюється." },
    { en = "Vordaza unleashes a frontal surge of soulflaying force for $d, inflicting $1252130s1 Shadow damage every $1252130t1 sec to players caught in the blast and pushing them away.", ua = "Вордаза вивільняє фронтальний наплив душероздираючої сили на $d, завдаючи $1252130s1 тіньової шкоди кожні $1252130t1 с гравцям, захопленим вибухом, і відштовхуючи їх." },
    { en = "Upon defeat Unstable Phantoms leave behind a pool of necrotic residue for $1251828d, inflicting $s1 Shadow damage every $t1 sec to players within.", ua = "Зазнавши поразки, Нестабільні Привиди залишають по собі калюжу некротичних решток на $1251828d, завдаючи $s1 тіньової шкоди кожні $t1 с гравцям усередині." },
    { en = "A withering miasma saturates the cavern, inflicting $1264989s1 Shadow damage to all players every $t1 sec.", ua = "Згубне марево насичує печеру, завдаючи $1264989s1 тіньової шкоди всім гравцям кожні $t1 с." },
    { en = "The phantom seeks out a player until defeated. When it reaches its target or collides with another Unstable Phantom, it bursts, inflicting $1251811s1 Shadow damage to players within $1251811a1 yards.", ua = "Фантом вистежує гравця, доки його не знищать. Коли він досягає своєї цілі або зіштовхується з іншим Нестабільним Фантомом, він вибухає, завдаючи $1251811s1 тіньової шкоди гравцям у радіусі $1251811a1 м." },
    { en = "Rak'tul's roar shatters each remaining Soulbind Totem, inflicting $s1 Shadow damage to all players for each totem shattered.", ua = "Рев Рак'тула розбиває кожен уцілілий Тотем Поєднання Душ, завдаючи $s1 тіньової шкоди всім гравцям за кожен розбитий тотем." },
    { en = "The pooling essence inflicts $s1 Shadow damage every $t1 sec to players within and increases their damage taken by $s3%.", ua = "Калюжа есенції завдає $s1 тіньової шкоди щосекунди ($t1) гравцям усередині й підвищує отримувану ними шкоду на $s3%." },
    { en = "Rak'tul repeatedly leaps and slams down, inflicting $1252704s1 Shadow damage to players within $1252704a1 yards. Each impact plants a Soulbind Totem.", ua = "Рак'тул раз за разом стрибає й гепає вниз, завдаючи $1252704s1 тіньової шкоди гравцям у межах $1252704a1 м. Кожне влучання встановлює Тотем Душезв'язку." },
    { en = "The totem ensnares a player, inflicting $s1 Shadow damage every $t1 sec and pulling them toward the totem.", ua = "Тотем обплутує гравця, завдаючи $s1 тіньової шкоди кожні $t1 с і притягуючи його до тотема." },
    { en = "Released essence empowers players, increasing their movement speed by $s1% and increasing their damage, healing, and absorption effects by $s2% for $d. This effect stacks, but does not refresh its duration.", ua = "Вивільнена есенція підсилює гравців, збільшуючи їхню швидкість пересування на $s1% та посилюючи завдану ними шкоду, зцілення й ефекти поглинання на $s2% на $d. Цей ефект накопичується, але не оновлює тривалість." },
    { en = "Rak'tul pummels his target twice, inflicting $1251024s1 Physical damage with each strike. He then delivers a final empowered blow, inflicting $1253765s1 Shadow damage and launching the target high into the air.\n\n\n\nThe final blow leaves behind a patch of $@spellname1253779.", ua = "Рак'тул двічі гамселить ціль, завдаючи $1251024s1 фізичної шкоди кожним ударом. Потім він завдає останнього підсиленого удару, що завдає $1253765s1 тіньової шкоди й підкидає ціль високо в повітря.\n\n\n\nОстанній удар залишає по собі пляму $@spellname1253779." },
    { en = "The totem inflicts $s1 Shadow damage every $t1 sec to players within $1252813A1 yards.", ua = "Тотем завдає $s1 тіньової шкоди кожні $t1 с гравцям у межах $1252813A1 м." },
    { en = "Released soul energy bursts upon impact, inflicting $s1 Shadow damage to players within $a1 yards.", ua = "Вивільнена енергія душі вибухає при влучанні, завдаючи $s1 тіньової шкоди гравцям у радіусі $a1 ярдів." },
    { en = "The soul cries out upon contacting a player, inflicting $s1 Shadow damage and rooting them for $d.", ua = "Душа скрикує від дотику до гравця, завдаючи $s1 тіньової шкоди й знерухомлюючи його на $d." },
    { en = "While in an incorporeal form, the target suffers $s1 Shadow damage every $t1 sec. This effect stacks every $1253842t1 sec.\n\n\n\nReturning to the realm of the living removes this effect.", ua = "Перебуваючи в безтілесній формі, ціль зазнає $s1 тіньової шкоди кожні $t1 с. Цей ефект накопичується кожні $1253842t1 с.\n\n\n\nПовернення до світу живих знімає цей ефект." },
    { en = "$@spellname1253788 sends Rak'tul into a stupor, stunning him for $d. Souls periodically erupt from his form, inflicting $1279517s1 Shadow damage to players within $1279517a1 yards of each impact.", ua = "$@spellname1253788 вкидає Рак'тула в заціпеніння, оглушуючи його на $d. З його тіла періодично вириваються душі, завдаючи $1279517s1 тіньової шкоди гравцям у межах $1279517a1 м від кожного влучання." },
    { en = "The soul radiates shadow magic, reducing the movement speed of players within $a1 yards by $1254043s1%. Upon interruption, the soul dissipates, empowering all players with $@spellname1255629.", ua = "Душа випромінює тіньову магію, знижуючи швидкість пересування гравців у радіусі $a1 м на $1254043s1%. При перериванні душа розсіюється, наділяючи всіх гравців $@spellname1255629." },
    { en = "Rak'tul roars with tremendous force, awakening the $@spellname1254441 and applying $@spellname1253844 to all players. This affliction tears players' souls asunder, flinging them across the Echoing Span and severing them from the realm of the living.\n\n\n\n$@spellname1253909 leaves Rak'tul momentarily in a trance.", ua = "Рак'тул реве з нездоланною силою, пробуджуючи $@spellname1254441 і накладаючи $@spellname1253844 на всіх гравців. Ця недуга роздирає душі гравців, жбурляючи їх через Лунку Просторінь і відриваючи від світу живих.\n\n\n\n$@spellname1253909 на мить занурює Рак'тула в транс." },
    { en = "Rak'tul's engorged form releases soul energy every $1248863t1 sec, inflicting $1248879s1 Shadow damage to all players and ejecting $@spellname1248980s.", ua = "Розбухле тіло Рак'тула вивільняє енергію душ кожні $1248863t1 сек., завдаючи $1248879s1 тіньової шкоди всім гравцям і викидаючи $@spellname1248980s." },
    { en = "An arcane discharge clings to players absorbing the next $s1 healing and inflicts $s2 Arcane damage every $t2 sec.", ua = "Арканний розряд чіпляється до гравців, поглинаючи наступні $s1 зцілення, і завдає $s2 арканної шкоди кожні $t2 с." },
    { en = "Upon reaching 100 energy, Kasreth overcharges a spark in the core engine and launches it at a random location, inflicting $s1 Arcane damage to all players within $A1 yards of the impact. The detonation causes a $@spellname1264040, leaving behind $@spellname1264042s, and $@spellname1276485 clings to all players.", ua = "Сягнувши 100 енергії, Касрет перенавантажує іскру в ядрі двигуна й запускає її у випадкове місце, завдаючи $s1 арканної шкоди всім гравцям у межах $A1 м від влучання. Детонація спричиняє $@spellname1264040, залишаючи по собі $@spellname1264042, а до всіх гравців чіпляється $@spellname1276485." },
    { en = "Broken pipes leak excess power, inflicting $s1 Arcane damage to enemies within $a1 yards of the impact. Causes an $@spellname1264042 to form for $d.", ua = "Зламані труби витікають надлишком енергії, завдаючи $s1 арканної шкоди ворогам у радіусі $a1 м від удару. Спричиняє утворення $@spellname1264042 на $d." },
    { en = "Residual arcane energy lingers on the ground, inflicting $s1 Arcane damage every $t1 sec to players standing within.", ua = "Залишкова арканна енергія тримається на землі, завдаючи $s1 арканної шкоди кожні $t1 с гравцям, що стоять усередині." },
    { en = "Kasreth hurls a refluxing circuit on a random player inflicting $1282915s1 Arcane damage every $1251772t1 sec. \n\nProvides immunity while standing in $@spellname1251626 as the circuit recoils and clears the effect, stunning the player for $1257836d.", ua = "Касрет жбурляє в випадкового гравця рефлюксний контур, що завдає $1282915s1 арканної шкоди кожні $1251772t1 с. \n\nЗабезпечує несприйнятливість, доки гравець стоїть у $@spellname1251626, бо контур відскакує й знімає ефект, приголомшуючи гравця на $1257836d." },
    { en = "Kasreth zaps the player, inflicting $s1 Arcane damage.", ua = "Касрет уражає гравця струмом, завдаючи $s1 арканної шкоди." },
    { en = "A dangerous flow of Arcane power links between conduits inflicting $s1 Arcane damage when crossed and reducing their movement speed by $s2% for $d. This effect stacks.", ua = "Небезпечний потік арканної сили з'єднує провідники, завдаючи $s1 арканної шкоди при перетині та знижуючи швидкість руху цілі на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Nysarra leaps to her primary target and unleashes consecutive slashes on them, inflicting $1248007s1 Shadow damage with every strike and causing $@spellname1252828 on the final one.", ua = "Нісарра стрибає до своєї основної цілі й обрушує на неї послідовні удари, завдаючи $1248007s1 тіньової шкоди кожним ударом і застосовуючи $@spellname1252828 на останньому." },
    { en = "The Grand Nullifier conjures a blast of void energy at the target, inflicting $s1 Shadow damage.", ua = "Великий Нуліфікатор закликає в ціль розряд енергії Порожнечі, завдаючи $s1 тіньової шкоди." },
    { en = "The Grand Nullifier calls several frights to a void zone, fearing players within $1282724A1 yards of the impact for $1282724d.", ua = "Великий Анулятор прикликає кілька жахів у зону Порожнечі, нажахаючи гравців у радіусі $1282724A1 м від удару на $1282724d." },
    { en = "A fractured image of Lothraxion strikes at Nysarra, causing her wound to flare and stunning her for $d. Players caught in the image's blast suffer $1265984s1 Holy damage and are disoriented for $1265984d.\n\n\n\nStanding in the wound's flare increases the target's healing done by $1247975s3% and damage dealt to Nysarra by $1247975s2% but inflicts $1271433s1 Holy damage every $1271433t1 sec until she recovers.", ua = "Розколотий образ Лотраксіона б'є по Нісаррі, через що її рана спалахує, а сама вона приголомшена на $d. Гравці, яких зачепив вибух образу, зазнають $1265984s1 священної шкоди й дезорієнтовані на $1265984d.\n\n\n\nПеребування в спалаху рани підвищує зцілення, яке отримує ціль, на $1247975s3% і шкоду, завдану Нісаррі, на $1247975s2%, але завдає $1271433s1 священної шкоди кожні $1271433t1 с, доки вона не відновиться." },
    { en = "The Dreadflail empowers its weapons, causing melee attacks to inflict $1282664s1 Shadow damage in a cone in front of it for $d.", ua = "Жахоціп підсилює свою зброю, через що атаки в ближньому бою завдають $1282664s1 тіньової шкоди в конусі перед ним протягом $d." },
    { en = "Wounded by Lothraxion, Nysarra begins the encounter at $s1% health. Fractured Images periodically tear into the arena, causing $@spellname1247976.", ua = "Поранена Лотраксіоном, Нісарра починає бій із $s1% здоров'я. Розколоті образи періодично прориваються на арену, спричиняючи $@spellname1247976." },
    { en = "Nyssara channels the void to consume any surviving subordinates, restoring her own strength every $t1 sec for $d and triggers a burst of void energy inflicting $1257980s1 Shadow damage to all players.", ua = "Нісарра скеровує Порожнечу, щоб поглинути будь-яких уцілілих підлеглих, відновлюючи власну силу кожні $t1 с протягом $d і спричиняючи спалах енергії Порожнечі, що завдає $1257980s1 тіньової шкоди всім гравцям." },
    { en = "Nysarra slips into the shadows and strikes at random players, inflicting $1252875s1 Shadow damage and additional $1252875s2 Shadow damage every $1252875t2 sec for $1252875d to all players within $1252875a2 yards.", ua = "Нісарра прослизає в тіні й завдає ударів випадковим гравцям, завдаючи $1252875s1 тіньової шкоди й додатково $1252875s2 тіньової шкоди кожні $1252875t2 с протягом $1252875d усім гравцям у радіусі $1252875a2 м." },
    { en = "The Dreadflail fixates on a random enemy and spins their flails inflicting $1282676s1 Shadow damage every $1282678t3 sec to enemies within $1282676A1 yards of the caster.", ua = "Жахоціп зосереджується на випадковому ворогові й розкручує свої ціпи, завдаючи $1282676s1 тіньової шкоди кожні $1282678t3 с ворогам у радіусі $1282676A1 м від мовця." },
    { en = "Gashes the player, knocking them back and increasing all damage taken by $s1% for $d.", ua = "Розтинає гравця, відкидаючи його та збільшуючи всю отримувану шкоду на $s1% на $d." },
    { en = "Remnants of Nysarra's shattered command rise to defend and suppress.", ua = "Рештки розбитого загону Нісарри підіймаються, щоб захищати й придушувати." },
    { en = "Fractured Images periodically flicker to new locations, inflicting $1255533s1 Holy damage and knocking away players in its path.", ua = "Розколоті Образи періодично мерехтять до нових місць, завдаючи $1255533s1 священної шкоди й відкидаючи гравців на своєму шляху." },
    { en = "Upon reaching 100 energy, Lothraxion disguises himself amongst his Fractured Images as they all channel light energy into the core, inflicting $s1 Holy damage every $1257595t2 sec until Lothraxion is interrupted.", ua = "Сягнувши 100 енергії, Лотраксіон ховається серед своїх Розколотих Образів, поки всі вони скеровують енергію світла в ядро, завдаючи $s1 священної шкоди кожні $1257595t2 с, доки Лотраксіона не переривають." },
    { en = "Inflicts $s1 Holy damage to all players and increases Holy damage taken by $s2% for $d.", ua = "Завдає $s1 священної шкоди всім гравцям і збільшує отримувану священну шкоду на $s2% на $d." },
    { en = "Lothraxion unleashes radiant swarms toward several players, blasting players within $1255503A1 yards of the impact for $1255503s1 Holy damage and searing an additional $1255503s2 Holy damage every $1255503t2 sec for $1255503d. \n\nFractured Images scatter, erupting with $@spellname1282791 to enemies within $1282791A1 yards of their creation.", ua = "Лотраксіон вивільняє осяйні рої в напрямку кількох гравців, уражаючи гравців у межах $1255503A1 м від влучання на $1255503s1 священної шкоди й випікаючи додаткові $1255503s2 священної шкоди кожні $1255503t2 с протягом $1255503d. \n\nРозтрощені Образи розлітаються, вибухаючи $@spellname1282791 на ворогів у межах $1282791A1 м від місця їх появи." },
    { en = "Coming in contact with a Fractured Image rends the target, knocking them away and inflicting $1269220s1 Holy damage with an additional $1271956s1 Holy damage every $1271956t1 sec. This effect stacks and leaves behind $@spellname1255389s.", ua = "Контакт із розколотим образом роздирає ціль, відкидаючи її та завдаючи $1269220s1 священної шкоди, а також додаткові $1271956s1 священної шкоди кожні $1271956t1 с. Цей ефект накопичується й лишає по собі $@spellname1255389s." },
    { en = "A jagged brand of divine energy inflicts $s1 Holy damage every $t1 sec to players within the area.", ua = "Зазубрене тавро божественної енергії завдає $s1 священної шкоди кожні $t1 с гравцям у межах зони." },
    { en = "Lothraxion lashes out with a precise, double-slash aimed at his current target, with each strike inflicting $1255208s1 Physical damage and an additional $1255335s1 Holy damage every $1255335t1 sec for $1255335d. Carves $@spellname1255310s into the ground.", ua = "Лотраксіон завдає точного подвійного удару по своїй поточній цілі, причому кожен удар завдає $1255208s1 фізичної шкоди й додаткові $1255335s1 священної шкоди кожні $1255335t1 с протягом $1255335d. Викарбовує $@spellname1255310s на землі." },
    { en = "Upon contact with a player, the windy arrow knocks them upwards, inflicting $s1 Nature damage and an additional $s3 Nature damage every $t3 sec for $d.$?diff23|diff8[\n\n\n\nThis affliction creates $@spellname1216044 upon expiration.][]", ua = "Торкаючись гравця, вітряна стріла підкидає його вгору, завдаючи $s1 шкоди від сил природи й додатково $s3 шкоди від сил природи кожні $t3 с протягом $d.$?diff23|diff8[\n\n\n\nПісля завершення це ураження створює $@spellname1216044.][]" },
    { en = "A gust blasts outward, inflicting $s1 Nature damage to players within $A1 yards.", ua = "Порив вибухає назовні, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів." },
    { en = "Gemellus stings a player with Cosmic Void, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d.\n\n\n\nOn expiration, $@spellname1224104 are created at the player's location.", ua = "Гемеллус жалить гравця Космічною Порожнечею, завдаючи $s1 тіньової шкоди й додатково $s2 тіньової шкоди кожні $t2 с протягом $d.\n\n\n\nПісля завершення на місці гравця створюється $@spellname1224104." },
    { en = "Rak'tul's terrible roar awakens Lost Souls and Malignant Souls, impeding players' path back to the realm of the living.", ua = "Жахливий рев Рак'тула пробуджує Загублені Душі та Злоякісні Душі, які перешкоджають гравцям повернутися до світу живих." },
    { en = "The Hoardmonger gathers from the nearest pile of resources, replacing one of his abilities with a new one.$?DIFF8|?DIFF23[][ He can only retain one ability at a time.]", ua = "Накопичувач Скарбів збирає з найближчої купи ресурсів, замінюючи одну зі своїх здібностей новою.$?DIFF8|?DIFF23[][ Він може зберігати лише одну здібність водночас.]" },
    { en = "Gathering from his pile of mushrooms, the Hoardmonger gains $@spellname1235105.\n\n\n\nThis effect increases the amount of $@spellname1234740s thrown during $@spellname1234233.", ua = "Беручи з купи грибів, Скарбохапач отримує $@spellname1235105.\n\n\n\nЦей ефект збільшує кількість $@spellname1234740, які кидаються під час $@spellname1234233." },
    { en = "The Hoardmonger slams the ground, inflicting $s2 Nature damage to players in a frontal cone.", ua = "Накопичувач Скарбів б'є об землю, завдаючи $s2 шкоди від сил природи гравцям у фронтальному конусі." },
    { en = "The Hoardmonger reaches into his sack and tosses rotten food over $d, impacting targeted players for $1234734s1 Nature damage or littering $@spellname1234740s around the arena.", ua = "Скарбохапа сягає рукою у свій мішок і жбурляє гнилу їжу протягом $d, що завдає цільовим гравцям $1234734s1 шкоди від сил природи або засипає арену $@spellname1234740." },
    { en = "After $s2 sec the mushroom bursts, inflicting $s1 Nature damage, applying $@spellname1234846 to all players.", ua = "Через $s2 сек. гриб лопається, завдаючи $s1 шкоди від сил природи та накладаючи $@spellname1234846 на всіх гравців." },
    { en = "Broken bones litter the ground, inflicting $s1 Physical damage every $t1 sec and reducing movement speed by $s2%.", ua = "Уламки кісток вкривають землю, завдаючи $s1 фізичної шкоди кожні $t1 с і знижуючи швидкість пересування на $s2%." },
    { en = "Gathering from his pile of meat, the Hoardmonger unlocks $@spellname1235125.\n\n\n\nThe Hoardmonger lets out a mighty roar, inflicting $s1 Physical damage to all players and an additional $s2 Physical damage every $t2 sec for $d. Ignores armor.", ua = "Беручи з купи м'яса, Скарбохапач відмикає $@spellname1235125.\n\n\n\nСкарбохапач видає могутній рик, завдаючи $s1 фізичної шкоди всім гравцям і додатково $s2 фізичної шкоди кожні $t2 с протягом $d. Ігнорує броню." },
    { en = "The Hoardmonger lets out a mighty roar, inflicting $s1 Physical damage to all players. Ignores armor.", ua = "Скарбохапач видає могутній рик, завдаючи $s1 фізичної шкоди всім гравцям. Ігнорує броню." },
    { en = "Gathering from his pile of bones, the Hoardmonger unlocks $@spellname1235129.\n\n\n\nThe Hoardmonger slams the ground, inflicting $s2 Nature damage to players in a frontal cone. This additionally creates bone spikes for $1235192d which apply $@spellname1235405 upon contact.", ua = "Беручи з купи кісток, Скарбохапач відмикає $@spellname1235129.\n\n\n\nСкарбохапач гупає об землю, завдаючи $s2 шкоди від сил природи гравцям у фронтальному конусі. Це додатково створює кісткові шипи на $1235192d, що накладають $@spellname1235405 при контакті." },
    { en = "Rotten Mushrooms apply a noxious cloud, inflicting $s1 Nature damage every $t1 sec for $d. This effect stacks.", ua = "Гнилі гриби створюють отруйну хмару, що завдає $s1 шкоди від сил природи кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "The Fractured Shivercore bursts releasing ice shards that impact $1263585d later inflicting $s1 Frost damage to players within $A1 yards.\n\n\n\nIf no players are struck the shard fragments cause a $@spellname1263597.", ua = "Розколотий тремтокор вибухає, вивільняючи крижані скалки, які за $1263585d падають і завдають $s1 морозної шкоди гравцям у межах $A1 м.\n\n\n\nЯкщо жодного гравця не влучено, уламки скалки спричиняють $@spellname1263597." },
    { en = "The Sentinel of Winter slams the ice, forming 2 icicles which splinter, inflicting $1235795s2 Frost damage to players within $1235795A2 yards of targeted locations, revealing a Fractured Shivercore.", ua = "Вартовий Зими б'є по льоду, утворюючи 2 бурульки, які розколюються, завдаючи $1235795s2 морозної шкоди гравцям у радіусі $1235795A2 ярдів від цільових місць і відкриваючи Тріснуте драглисте ядро." },
    { en = "The Sentinel of Winter manifests a massive storm, surrounding itself in a frozen veil absorbing damage equal to $s4% of max health. Until broken, this storm inflicts $1235658s1 Frost damage to all players every $t1 sec, pushing them away.", ua = "Вартовий Зими породжує велетенську бурю, оточуючи себе крижаною завісою, що поглинає шкоду в розмірі $s4% максимального здоров'я. Поки завіса не зруйнована, ця буря завдає $1235658s1 морозної шкоди всім гравцям кожні $t1 с, відштовхуючи їх." },
    { en = "The Sentinel of Winter creates $@spellname1235641s, inflicting $1235635s1 Frost damage to players within $1235635A1 yards of the impact location. These squalls wander the arena for $1235635d, inflicting $s1 Frost damage every $t1 sec to players within $1235638A1 yards.", ua = "Вартовий Зими створює $@spellname1235641s, завдаючи $1235635s1 морозної шкоди гравцям у межах $1235635A1 м від місця удару. Ці шквали блукають ареною протягом $1235635d, завдаючи $s1 морозної шкоди кожні $t1 с гравцям у межах $1235638A1 м." },
    { en = "Upon defeat, the Fractured Shivercore forms a pile of deep snow at its location. Players standing within have their movement speed reduced by $s1% and are immune to forced movement effects.", ua = "Зазнавши поразки, Розколотий зморозосердечник утворює на своєму місці кучугуру глибокого снігу. Гравцям, які стоять усередині, швидкість пересування зменшується на $s1%, і вони стають несприйнятливими до ефектів примусового переміщення." },
    { en = "Inflicts $s1 Frost damage to all players and roots them in place for $d.", ua = "Завдає $s1 морозної шкоди всім гравцям і прикорінює їх на місці на $d." },
    { en = "The Fractured Shivercore blankets players with the chill of Winter, inflicting $s1 Frost damage to all players, increasing their Frost damage taken by $s2% for $d. This effect stacks.", ua = "Розколотий зморозосердечник окутує гравців зимовим холодом, завдаючи $s1 морозної шкоди всім гравцям і збільшуючи морозну шкоду, яку вони зазнають, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The Sentinel of Winter assaults players with freezing temperatures, inflicting $s1 Frost damage every $t1 sec for $d.", ua = "Вартовий Зими атакує гравців крижаними температурами, завдаючи $s1 морозної шкоди кожні $t1 с протягом $d." },
    { en = "Nalorakk swipes repeatedly, obliterating his primary target for $1243585d, inflicting $s1 Physical damage every $1243585t1 sec and increasing $@spellname1243590 damage taken by $s2% for $d. This effect stacks.", ua = "Налоракк раз за разом завдає ударів, нищачи свою основну ціль протягом $1243585d, завдаючи $s1 фізичної шкоди кожні $1243585t1 с і підвищуючи отримувану від $@spellname1243590 шкоду на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Nalorakk marks players for $1242869d, then sends an Echo of Nalorakk to their position. All Echoes of Nalorakk immediately inflict $s1 Nature damage to players within $A1 yards.", ua = "Налоракк позначає гравців на $1242869d, тоді надсилає до їхньої позиції Відлуння Налоракка. Усі Відлуння Налоракка миттєво завдають $s1 шкоди від сил природи гравцям у межах $A1 м." },
    { en = "Zul'jarra cries out in pain from the undefended attack, inflicting $s1 Physical damage to all players. Ignores armor.\n\n\n\nPlayers feel the weight of her burden, increasing damage taken by $s2% for $d. This effect stacks.", ua = "Зул'джарра скрикує від болю через невідбиту атаку, завдаючи $s1 фізичної шкоди всім гравцям. Ігнорує броню.\n\n\n\nГравці відчувають тягар її ноші, що збільшує отримувану шкоду на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The charging Echo of Nalorakk ravages the first target in their path, inflicting $s1 Nature damage.", ua = "Навальне Відлуння Налоракка нищить першу ціль на своєму шляху, завдаючи $s1 шкоди від сил природи." },
    { en = "When Nalorakk casts $@spellname1243585, Zul'jarra creates a protective barrier reducing damage taken from $@spellname1243585 by $1261781s1% to players behind her.", ua = "Коли Налоракк творить $@spellname1243585, Зул'джарра зводить захисний бар'єр, що зменшує шкоду від $@spellname1243585 на $1261781s1% для гравців позаду неї." },
    { en = "Nalorakk disables Zul'jarra with a hefty blow. Unable to defend herself, she stands vulnerable to Nalorakk's echoes.", ua = "Налоракк потужним ударом виводить Зул'джарру з ладу. Нездатна захиститися, вона стає беззахисною перед відлуннями Налоракка." },
    { en = "The echo slashes at nearby players, knocking them back and causing them to bleed for $s1 Physical damage every $t1 sec for $d. This effect stacks.", ua = "Відлуння шмагає гравців поблизу, відкидаючи їх і змушуючи стікати кров'ю, завдаючи $s1 фізичної шкоди кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Nalorakk headbutts Zul'jarra into a $@spellname1243063, then commands the Echoes of Nalorakk to charge her position. These collide with the first target encountered casting $@spellname1243408$?diff23[ and $@spellname1255577][].\n\n\n\nAny Echo of Nalorakk that reaches Zul'jarra triggers $@spellname1262253. Each Echo remains for one additional $@spellname1243002, then vanishes.", ua = "Налоракк ударом голови вганяє Зул'джарру в $@spellname1243063, а тоді наказує Відлункам Налоракка кинутися на її позицію. Вони стикаються з першою ціллю, яку зустрінуть, творячи $@spellname1243408$?diff23[ та $@spellname1255577][].\n\n\n\nБудь-яке Відлуння Налоракка, що досягає Зул'джарри, спричиняє $@spellname1262253. Кожне Відлуння лишається ще на один $@spellname1243002, а потім зникає." },
    { en = "Nalorakk's shout resonates throughout the den, inflicting $s3 Physical damage and pushes away players for $d. Ignores armor.", ua = "Крик Налоракка лунає по всьому лігву, завдаючи $s3 фізичної шкоди й відштовхуючи гравців на $d. Ігнорує броню." },
    { en = "When Nibbles is drained of fel magic she reverts to her light form. While in her light form, Nibbles attempts to purge the fel from Kystia with an infusion of light.", ua = "Коли з Кусаки витягують магію Скверни, вона повертається до своєї світлої форми. У світлій формі Кусака намагається очистити Кистію від Скверни вливанням Світла." },
    { en = "Kystia teleports to a random player's location and sends out an explosive wave of destructive energy, inflicting $s1 Fire damage to nearby players and knocking them back.", ua = "Кистія телепортується до позиції випадкового гравця і випускає вибухову хвилю руйнівної енергії, завдаючи $s1 вогняної шкоди гравцям поблизу і відкидаючи їх назад." },
    { en = "The light infusion stuns Kystia for $d, bringing her attacks to a halt, increasing all damage she takes by $s1%, and expelling bursts of fel magic that inflict $1214959s1 Chaos damage to all players every $t3 sec.\n\n\n\nAdditionally, this reduces the effectiveness of Kystia's $@spellname1217989.", ua = "Вливання світла приголомшує Кистію на $d, спиняючи її атаки, збільшуючи всю шкоду, якої вона зазнає, на $s1% і вивергаючи спалахи скверномагії, що завдають $1214959s1 шкоди хаосом усім гравцям кожні $t3 с.\n\n\n\nКрім того, це знижує ефективність здібності Кістії $@spellname1217989." },
    { en = "Kystia enshrouds herself in a fel barrier, reducing the damage she takes by ${$abs($s1*$U)}%.", ua = "Кистія огортає себе бар'єром скверни, знижуючи отримувану шкоду на ${$abs($s1*$U)}%." },
    { en = "Nibbles spits at players, inflicting $s1 Fire damage immediately and $s2 Fire damage every $t2 sec for $d. This effect stacks.", ua = "Кусака плює в гравців, завдаючи $s1 вогняної шкоди миттєво та $s2 вогняної шкоди кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Kystia's mirror image engulfs the arena in fel fire, inflicting $1264110m1 Fire damage to all nearby players every $t1 sec.", ua = "Дзеркальне відображення Кістії огортає арену вогнем Скверни, завдаючи $1264110m1 вогняної шкоди всім гравцям поблизу кожні $t1 с." },
    { en = "Kystia infuses Nibbles with fel magic, turning her hostile to players while she is above $s1% health.", ua = "Кистія наповнює Кусаку магією Скверни, роблячи її ворожою до гравців, доки її здоров'я перевищує $s1%." },
    { en = "Nibbles unleashes a spray of fel magic in a cone in front of her, dealing $1253813s1 Fire damage to players caught in the spray every $t1 sec for $d.", ua = "Кусака вивергає струмінь магії скверни конусом перед собою, завдаючи $1253813s1 вогняної шкоди гравцям, що потрапили під струмінь, кожні $t1 с протягом $d." },
    { en = "Kystia unleashes a devastating blast of chaos at her current target, dealing $s1 Chaos damage and then jumping to nearby players at reduced effectiveness.", ua = "Кистія вивільняє нищівний вибух хаосу по своїй поточній цілі, завдаючи $s1 шкоди хаосу, а потім перестрибує на гравців поблизу зі зниженою дієвістю." },
    { en = "Kystia creates copies of herself nearby, each of which cast $@spellname1264106.", ua = "Кистія створює поблизу копії себе, кожна з яких творить $@spellname1264106." },
    { en = "Upon being hit by a Fire Bomb or Murder in a Row, Forbidden Freight explode after $d, inflicting $s1 Fire damage to nearby players, knocking them away.", ua = "Зазнавши влучання Вогняної Бомби чи Вбивства в Ряду, Заборонений Вантаж вибухає через $d, завдаючи $s1 вогняної шкоди гравцям поблизу й відкидаючи їх." },
    { en = "Zaen takes a few precious moments to take aim at all players. When he is ready to fire, he shoots all players in his line of sight, inflicting $474740s1 Physical damage and an additional $474740o3 Bleed damage over $474740d.", ua = "Заен витрачає кілька дорогоцінних митей, щоб прицілитися в усіх гравців. Коли він готовий стріляти, то стріляє в усіх гравців у полі зору, завдаючи $474740s1 фізичної шкоди та додатково $474740o3 шкоди від кровотечі протягом $474740d." },
    { en = "Zaen drives a poisoned blade in deep at his current target, inflicting $1223939s1 Physical damage and applying $@spellname474515.", ua = "Заен глибоко вганяє отруєний клинок у свою поточну ціль, завдаючи $1223939s1 фізичної шкоди й застосовуючи $@spellname474515." },
    { en = "Zaen calls upon the warehouse workers above to throw Forbidden Freight at players, causing $474768s1 Fire damage on impact and knocking them away.", ua = "Заен наказує робітникам складу нагорі жбурляти в гравців Заборонений Вантаж, що при влучанні завдає $474768s1 вогняної шкоди й відкидає їх." },
    { en = "Zaen unleashes a rapid barrage of gunfire, inflicting $474483s1 Physical damage to all players every $t1 sec over $d.", ua = "Заен вивільняє стрімкий шквал вогню зі зброї, завдаючи $474483s1 фізичної шкоди всім гравцям кожні $t1 сек. протягом $d." },
    { en = "A shipment that is barely containing the volatile magic within, inflicting $1217099s1 Fire damage to all players every $1217100t1 sec.", ua = "Вантаж, що ледве стримує всередині нестабільну магію, завдаючи $1217099s1 вогняної шкоди всім гравцям кожні $1217100t1 сек." },
    { en = "A lethal poison that reduces the target's maximum health by $474515s1% and inflicts $474515o2 Nature damage over $474515d.", ua = "Смертельна отрута, що зменшує максимальне здоров'я цілі на $474515s1% і завдає $474515o2 шкоди силами природи протягом $474515d." },
    { en = "Zaen hurls a ticking bomb at a player. After $1214352d the bomb explodes, dealing $1214355s1 Fire damage to players within $1214355a1 yards and destroying any Forbidden Freight caught in the blast.", ua = "Заен жбурляє в гравця бомбу з годинниковим механізмом. Через $1214352d бомба вибухає, завдаючи $1214355s1 вогняної шкоди гравцям у радіусі $1214355a1 ярдів і знищуючи будь-який Заборонений вантаж, що потрапив під вибух." },
    { en = "Xathuux the Annihilator spreads fel magic across the ground from his feet inflicting $s1 Fire damage every $t sec to any players standing in it.", ua = "Ксатуукс Нищитель розливає скверну по землі від своїх ніг, завдаючи $s1 вогняної шкоди кожні $t с усім гравцям, що стоять у ній." },
    { en = "Xathuux the Annihilator throws his massive axe at the location of a random player inflicting $s1 Chaos damage and interrupting players within $a yds of the impact. The axe remains on the ground emitting Fel Light until it is destroyed.", ua = "Ксатуукс Нищитель кидає свою величезну сокиру в позицію випадкового гравця, завдаючи $s1 шкоди хаосом і перериваючи гравців у межах $a м від удару. Сокира лишається на землі, випромінюючи Скверносвітло, доки її не знищать." },
    { en = "Xathuux the Annihilator performs a powerful swing with his axe that inflicts $s1 Physical damage and reduces healing received by $s2% for $d.", ua = "Ксатуукс Нищитель завдає потужного удару сокирою, що завдає $s1 фізичної шкоди й зменшує отримане зцілення на $s2% протягом $d." },
    { en = "Xathuux the Annihilator flies into a Demonic Rage, inflicting $s1 Chaos damage to all players. While this effect is active, Xathuux gains $s2% attack speed, suffers $s3% increased incoming damage, and gains Burning Steps for $d.", ua = "Ксатуукс Нищитель впадає в Демонічну Лють, завдаючи всім гравцям $s1 шкоди від хаосу. Поки цей ефект активний, Ксатуукс отримує $s2% швидкості атаки, зазнає $s3% збільшеної вхідної шкоди й отримує Палаючі Кроки на $d." },
    { en = "Xathuux the Annihilator's axe channels beams of fel lightning at all players inflicting $s1 Chaos damage every $1214646t1 sec. This effect stacks.", ua = "Сокира Ксатуукса Нищителя спрямовує промені скверноблискавки на всіх гравців, завдаючи $s1 шкоди хаосом кожні $1214646t1 с. Цей ефект накопичується." },
    { en = "Empowered by Malefic Wave, increasing haste by $s1%.", ua = "Підсилення Лиховісною хвилею, що збільшує поспіх на $s1%." },
    { en = "Lithiel Cinderfury unleashes a devastating blast inflicting $s1 Chaos damage.", ua = "Літіель Сіндерф'юрі вивільняє нищівний вибух, що завдає $s1 шкоди хаосу." },
    { en = "Lithiel Cinderfury conjures a Felshield and then projects a wave of fel fire. Impacted players suffer $s1 Fire damage every $t1 sec and take $s2% additional fire damage for $d. This effect stacks.\n\n\n\nDemons struck by Malefic Wave are granted $@spellname1226469.", ua = "Літіель Сіндерф'юрі прикликає Щит скверни, а тоді випускає хвилю вогню скверни. Уражені гравці зазнають $s1 вогняної шкоди кожні $t1 сек. і отримують на $s2% більше вогняної шкоди протягом $d. Цей ефект накопичується.\n\n\n\nДемони, у яких влучає Лиховісна хвиля, отримують $@spellname1226469." },
    { en = "Lithiel enshrouds herself in a fel barrier, reducing the damage she takes by $s1% for $d.", ua = "Літіель огортає себе бар'єром скверни, зменшуючи шкоду, яку зазнає, на $s1% протягом $d." },
    { en = "Lithiel Cinderfury engulfs herself in fel fire, radiating $1216945s1 Fire damage to enemies every $t1 sec.", ua = "Літіель Сіндерф'юрі огортає себе вогнем скверни, випромінюючи $1216945s1 вогняної шкоди ворогам кожні $t1 с." },
    { en = "Lithiel Cinderfury creates a demonic gateway between two locations. Activating the gateway transports the user to the other gateway and prevents initial damage and Fire vulnerability from $@spellname1217384.", ua = "Літіель Сіндерф'юрі створює демонічну браму між двома місцями. Активація брами переносить користувача до іншої брами і запобігає первинній шкоді та вразливості до вогню від $@spellname1217384." },
    { en = "Lithiel Cinderfury calls down demonic magic to each nearby enemy inflicting $s1 Shadowflame damage to all enemies within $A1 yds of each target. Wild Imps to burst from the impact sites and attack nearby targets.", ua = "Літіель Сіндерф'юрі прикликає демонічну магію на кожного ворога поблизу, завдаючи $s1 тіньовогняної шкоди всім ворогам у радіусі $A1 ярдів від кожної цілі. З місць влучання вириваються дикі бісенята й нападають на цілі поблизу." },
    { en = "Inflicts $1231353s1 Fire damage to nearby enemies every $t sec.", ua = "Завдає $1231353s1 вогняної шкоди ближнім ворогам кожні $t с." },
    { en = "Kezkitt inflicts $s1 Holy damage to a player.", ua = "Кезкітт завдає гравцеві $s1 священної шкоди." },
    { en = "Meittik strikes their primary target with immense force, inflicting $1234773s1 Nature damage and $s1 Physical damage. The force of the impact ruptures nearby topsoil, creating patches of $@spellname1234782.", ua = "Меіттік б'є основну ціль із величезною силою, завдаючи $1234773s1 шкоди від сил природи та $s1 фізичної шкоди. Сила удару розриває верхній шар ґрунту поблизу, утворюючи ділянки $@spellname1234782." },
    { en = "Lekshi dashes between patches of $@spellname1234782, inflicting $1235546s1 Holy damage to players in their path and sowing a Lightblossom at each destination.", ua = "Лекші стрімко мчить між ділянками $@spellname1234782, завдаючи $1235546s1 священної шкоди гравцям на своєму шляху і висіваючи Світлоцвіт у кожному пункті призначення." },
    { en = "Meittik, Lekshi, and Kezkitt are bonded, causing them to share all damage taken.", ua = "Меіттік, Лекші та Кезкітт пов'язані, через що ділять усю отриману шкоду." },
    { en = "The charred earth inflicts $1235828s1 Holyfire damage every $1235828t1 sec to players standing within the effect.", ua = "Обвуглена земля завдає $1235828s1 шкоди священним вогнем кожні $1235828t1 сек. гравцям, які стоять у зоні дії." },
    { en = "The fully cultivated Lightblossom surges with energy, inflicting $1235752s1 Holy damage to all players every $t1 sec for $d. Devoid of nutrients, patches of $@spellname1234782 wither into $@spellname1235814.", ua = "Повністю вирощений Світлоцвіт пульсує енергією, завдаючи $1235752s1 священної шкоди всім гравцям кожні $t1 с протягом $d. Позбавлені поживних речовин, ділянки $@spellname1234782 в'януть і перетворюються на $@spellname1235814." },
    { en = "The impact of $@spellname1234753 causes an aftershock that inflicts $s1 Nature damage to all players every $t1 sec for $d.", ua = "Удар $@spellname1234753 спричиняє поштовх, що завдає $s1 шкоди від сил природи всім гравцям кожні $t1 с протягом $d." },
    { en = "Kezkitt channels a beam of light on each Lightblossom Seed, inflicting $1235574s1 Holy damage every $1235574t1 sec to players standing in the effect. The powerful beam rapidly germinates the seed, applying stacks of $@spellname1235729. After $d, the blossom casts $@spellname1235751.\n\n\n\nStanding within the beam stifles the seed's growth and prevents applications of $@spellname1235729.", ua = "Кезкітт спрямовує промінь світла на кожне Зерно Світлоцвіту, завдаючи $1235574s1 священної шкоди кожні $1235574t1 с гравцям, що стоять у дії ефекту. Потужний промінь швидко пророщує зерно, накладаючи стоси ефекту $@spellname1235729. Через $d цвіт творить $@spellname1235751.\n\n\n\nПеребування в промені пригнічує ріст зерна й запобігає накладанню $@spellname1235729." },
    { en = "The concentrated energy empowers the Lightblossom, increasing its damage inflicted by $s2% with each application.", ua = "Зосереджена енергія підсилює Світлоцвіт, збільшуючи завдану ним шкоду на $s2% з кожним застосуванням." },
    { en = "Lekshi unleashes a flurry of thorns, inflicting $1261013s1 Nature damage to players within $1261013A1 yards of their location every $t1 sec for $d.", ua = "Лекші вивільняє град колючок, завдаючи $1261013s1 шкоди від сил природи гравцям у межах $1261013A1 м від свого місця кожні $t1 с протягом $d." },
    { en = "Lekshi ambushes a player and backstabs them, inflicting $1235642s1 Nature damage and causing them to bleed for $1235865s1 Physical damage every $1235865t1 sec for $1235865d.", ua = "Лекші влаштовує засідку на гравця і б'є його в спину, завдаючи $1235642s1 шкоди від сил природи і спричиняючи кровотечу на $1235865s1 фізичної шкоди кожні $1235865t1 с протягом $1235865d." },
    { en = "Unearthed subsoil slows players standing within the effect by $1234802s1% and inflicts $1234802s3 Nature damage every $1234802t3 sec.", ua = "Розритий ґрунт сповільнює гравців у зоні дії на $1234802s1% і завдає $1234802s3 шкоди від сил природи кожні $1234802t3 с." },
    { en = "The player is stunned for $d after being chewed up and spit out.", ua = "Гравець оглушений на $d після того, як його пережували й виплюнули." },
    { en = "Ikuzz fixates on a player, pursuing them for 10 sec. Upon reaching their target, Ikuzz will $@spellname1237166 them.", ua = "Ікузз зосереджується на гравцеві, переслідуючи його 10 с. Досягнувши цілі, Ікузз застосує до неї $@spellname1237166." },
    { en = "While fixating on a target, Ikuzz's massive footfalls inflict $s1 Nature damage to players and crush any $@spellname1236658 within $A1 yards every $1237092t1 sec.", ua = "Поки Ікузз зосереджений на цілі, його велетенські кроки завдають $s1 шкоди від сил природи гравцям і трощать будь-які $@spellname1236658 у радіусі $A1 ярдів кожні $1237092t1 с." },
    { en = "$?DIFF8|DIFF23[Ikuzz roars, inflicting $1236731s1 Nature damage to all players while $@spellname1236658 erupt around it every $t1 sec for $d.\n\n][Ikuzz roars, inflicting $1236731s1 Nature damage to all players every $t1 sec for $d.]", ua = "$?DIFF8|DIFF23[Ікузз ричить, завдаючи $1236731s1 шкоди від сил природи всім гравцям, поки навколо нього кожні $t1 с протягом $d вивергаються $@spellname1236658.\n\n][Ікузз ричить, завдаючи $1236731s1 шкоди від сил природи всім гравцям кожні $t1 с протягом $d.]" },
    { en = "Ikuzz stomps, inflicting $s1 Physical damage to all players and knocking them back. $?DIFF23|DIFF8[After $1236747d, $@spellname1236658 emerge at players' locations.][]", ua = "Ікузз тупає, завдаючи $s1 фізичної шкоди всім гравцям і відкидаючи їх. $?DIFF23|DIFF8[Через $1236747d на позиціях гравців з'являються $@spellname1236658.][]" },
    { en = "Upon reaching its prey, Ikuzz chomps down on the player, causing them to bleed $1237267s1 Physical damage every $1237267t1 sec for $1237267d.", ua = "Досягнувши своєї здобичі, Ікузз вгризається в гравця, спричиняючи кровотечу на $1237267s1 фізичної шкоди кожні $1237267t1 с протягом $1237267d." },
    { en = "Ikuzz fully absorbs the power of the Lightbloom, increasing its movement speed by $s2% and causing it to pulse $1263420s1 Holy damage every $t3 sec.", ua = "Ікузз цілком поглинає силу Світлоцвіту, що збільшує його швидкість руху на $s2% і змушує його випромінювати $1263420s1 священної шкоди кожні $t3 с." },
    { en = "Roots entangle players, inflicting $1237330s1 Nature damage and rooting them in place until destroyed.", ua = "Коріння обплутує гравців, завдаючи $1237330s1 шкоди від сил природи й знерухомлюючи їх, доки не буде знищене." },
    { en = "Ruia calls down waves of falling Light energy, inflicting $1240152s1 Holy damage to players within $1240152A1 yards of the impact.", ua = "Руя обрушує хвилі енергії Світла, завдаючи $1240152s1 шкоди Світлом гравцям у межах $1240152A1 м від місця удару." },
    { en = "Ruia thrashes about, inflicting $s1 Physical damage to players and causing them to bleed an additional $s2 Physical damage every $t2 sec for $d or until fully healed. This effect stacks.", ua = "Руя несамовито б'ється, завдаючи гравцям $s1 фізичної шкоди та змушуючи їх стікати кров'ю, отримуючи додатково $s2 фізичної шкоди кожні $t2 с протягом $d або до повного зцілення. Цей ефект накопичується." },
    { en = "Upon being struck by $@spellname1240210, players take $s1% increased damage from $@spellname1240210 for $d.", ua = "Зазнавши влучання від $@spellname1240210, гравці отримують на $s1% більше шкоди від $@spellname1240210 протягом $d." },
    { en = "While in Bear form, Lightwarden Ruia's melee attacks inflict $s%1 increased damage.", ua = "У ведмежій подобі ближні атаки Світловартового Руї завдають на $s% більше шкоди." },
    { en = "Ruia calls upon the spirits, casting $@spellname1239824, $@spellname1240098, $@spellname1240210, and $@spellname1241058 every $t1 sec until he is defeated.", ua = "Руя закликає духів, творячи $@spellname1239824, $@spellname1240098, $@spellname1240210 і $@spellname1241058 кожні $t1 с, доки його не буде здолано." },
    { en = "Ruia blasts his current target with a bolt of energy, inflicting $s1 Nature damage.", ua = "Руя б'є свою поточну ціль розрядом енергії, завдаючи $s1 шкоди від сил природи." },
    { en = "Ruia shoots a beam of energy at a player, burning them for $1239825s1 Radiant damage every $1239825t1 sec for $1239825d.\n\n\n\nUpon expiration, $@spellname1239830 emerge at the afflicted player's location.", ua = "Руя стріляє в гравця променем енергії, обпалюючи його на $1239825s1 променевої шкоди кожні $1239825t1 с протягом $1239825d.\n\n\n\nПісля завершення на місці враженого гравця з'являються $@spellname1239830." },
    { en = "Ruia marks several targets and launches a wave of force toward each of them in a frontal cone every $t1 sec for $d. Each impact inflicts $1240257s2 Physical damage to players within the effect and applies $@spellname1257094.", ua = "Руя позначає кілька цілей і запускає в кожну з них хвилю сили в конусі попереду кожні $t1 с протягом $d. Кожне влучання завдає гравцям у зоні дії $1240257s2 фізичної шкоди й накладає $@spellname1257094." },
    { en = "Standing within the beams inflicts $s1 Radiant damage every $t1 sec and silences players for $d.", ua = "Перебування в променях завдає $s1 променевої шкоди кожні $t1 с і занімовлює гравців на $d." },
    { en = "Ziekket sows Light energy into the soil, sprouting Lightspawn Lashers and reawakening any that are $@spellname1246379.\n\n\n\nLashers reawaken with $@spellname1253320.", ua = "Зіккет засіває ґрунт енергією Світла, пророщуючи Світлородних Шмагачів і пробуджуючи всіх, хто перебуває під дією $@spellname1246379.\n\n\n\nШмагачі пробуджуються з $@spellname1253320." },
    { en = "Viscous resin covers the ground, inflicting $1246753s1 Holy damage every $1246753t1 sec to players standing within the effect and reducing their movement speed by $1246753s2%.", ua = "В'язка смола вкриває землю, завдаючи $1246753s1 священної шкоди кожні $1246753t1 с гравцям, що стоять у зоні дії, і знижуючи їхню швидкість пересування на $1246753s2%." },
    { en = "Ziekket impales the player with his spiked branch, inflicting $s1 Holy damage and knocking them back. The puncture wound causes the player to bleed an additional $1247746s1 Physical damage every $1247746t1 sec for $1247746d.", ua = "Зіккет настромлює гравця на свою колючу гілку, завдаючи $s1 священної шкоди і відкидаючи його. Колота рана змушує гравця стікати кров'ю, завдаючи додатково $1247746s1 фізичної шкоди кожні $1247746t1 с протягом $1247746d." },
    { en = "Lightspawn Lashers reawaken with renewed power, increasing their haste and damage done by $s1%. This effect also makes them immune to interrupts and crowd controlling effects.", ua = "Світлопороджені шмагальники пробуджуються з оновленою силою, підвищуючи свій поспіх і завдану шкоду на $s1%. Цей ефект також робить їх несприйнятливими до переривань та ефектів контролю." },
    { en = "Ziekket draws out globules of Lightbloom energy from the earth that move toward him, triggering a $@spellname1247039 upon reaching him.\n\n\n\nThe orbs instead burst when touched by players, granting that player $@spellname1247052.", ua = "Зіккет витягає з землі кульки енергії Світлоцвіту, що рухаються до нього й спричиняють $@spellname1247039, коли його сягають.\n\n\n\nНатомість, коли кулі торкаються гравці, вони лопаються, даруючи тому гравцеві $@spellname1247052." },
    { en = "Upon reaching 1% remaining health, Lightspawn Lashers submerge themselves back into the ground, becoming unable to move and immune to player effects.", ua = "Досягнувши 1% залишкового здоров'я, Світлонароджені шмагальники занурюються назад під землю, втрачаючи здатність рухатися та стаючи несприйнятливими до ефектів гравців." },
    { en = "Ziekket becomes enveloped in Light energy, absorbing the next $s1 damage taken and increasing his damage done by $s2%. This effect stacks.", ua = "Зіккет огортається енергією Світла, що поглинає наступні $s1 отриманої шкоди й збільшує завдану ним шкоду на $s2%. Цей ефект накопичується." },
    { en = "Players briefly borrow the power of the Lightbloom, increasing damage and healing done by $s1% while suffering $s3 Holy damage every $t3 sec for $d. This effect stacks.", ua = "Гравці ненадовго позичають силу Світлоцвіту, що збільшує завдану шкоду й зцілення на $s1%, поки вони зазнають $s3 священної шкоди кожні $t3 с протягом $d. Цей ефект накопичується." },
    { en = "Ziekket releases a powerful beam of Light energy, inflicting $1246751s1 Holy damage every $1246751t1 sec to players within the effect.\n\n\n\nAny $@spellname1246379 Lightspawn Lashers hit by the beam are instantly liquified into puddles of $@spellname1246660.", ua = "Зіккет вивільняє потужний промінь енергії Світла, завдаючи $1246751s1 священної шкоди кожні $1246751t1 сек. гравцям у зоні дії.\n\n\n\nБудь-які Світлонароджені шмагальники зі станом $@spellname1246379, у яких влучає промінь, миттєво розріджуються в калюжі $@spellname1246660." },
    { en = "Ziekket gorges on Light energy, inflicting $1247644s1 Holy damage to all players every $t1 sec.", ua = "Зіккет упивається енергією Світла, завдаючи всім гравцям $1247644s1 священної шкоди кожні $t1 с." },
    { en = "The lasher spews at a player, inflicting $s1 Holy damage.", ua = "Шмагальник плює в гравця, завдаючи $s1 священної шкоди." },
    { en = "Ziekket absorbs the $@spellname1246858, triggering a powerful reaction that inflicts $s1 Holy damage to all players. This effect grants Ziekket a $@spellname1247050.", ua = "Зіккет поглинає $@spellname1246858, спричиняючи потужну реакцію, що завдає $s1 священної шкоди всім гравцям. Цей ефект дарує Зіккету $@spellname1247050." },
    { en = "Taz'Rah slashes his current target, inflicting $s1 Shadowstrike damage.", ua = "Таз'Ра шматує свою поточну ціль, завдаючи $s1 шкоди тіньовим ударом." },
    { en = "Taz'Rah teleports a short distance and summons Ethereal Shades to lash out at players.", ua = "Таз'Ра телепортується на коротку відстань і прикликає астральні тіні, що накидаються на гравців." },
    { en = "The Ethereal Shade dashes through its target, inflicting $1222103s1 Shadow damage and an additional $1222103s3 Shadow damage every $1222103t3 sec for $1222103d to all players in a line.", ua = "Астральна тінь проноситься крізь свою ціль, завдаючи $1222103s1 тіньової шкоди та додатково $1222103s3 тіньової шкоди кожні $1222103t3 с протягом $1222103d усім гравцям на лінії." },
    { en = "Taz'Rah projects two shards toward a player. Each shard detonates on the first player it impacts inflicting $s1 Shadow damage. If both shards impact the player, that player suffers an additional $1270352s1 Shadow damage.", ua = "Таз'Ра випускає в гравця два уламки. Кожен уламок вибухає на першому гравцеві, якого влучає, завдаючи $s1 тіньової шкоди. Якщо обидва уламки влучають в одного гравця, той зазнає додатково $1270352s1 тіньової шкоди." },
    { en = "Taz'Rah rips open a rift for $1222274d that pulls all players toward it, inflicting $126283s1  Shadow damage every $1222305t1 sec to them. Players who fall within the center of the rift suffer $1222305s1 Shadow damage every $1222305t1 sec.", ua = "Таз'Ра роздирає розлом на $1222274d, що притягує до себе всіх гравців, завдаючи їм $126283s1 тіньової шкоди кожні $1222305t1 с. Гравці, що потрапляють у центр розлому, зазнають $1222305s1 тіньової шкоди кожні $1222305t1 с." },
    { en = "Atroxus inflicts $s2 Physical damage to all players, knocking them back.", ua = "Атроксус завдає $s2 фізичної шкоди всім гравцям, відкидаючи їх." },
    { en = "Atroxus agitates the surrounding pools, causing a Toxic Creeper to emerge and attack players.", ua = "Атроксус збурює навколишні озерця, через що з них з'являється Токсичний Повзун і атакує гравців." },
    { en = "The Toxic Creeper radiates a toxic cloud that inflicts $s1 Nature damage every $t sec to players within $s2 yards.", ua = "Отруйний Повзун випромінює отруйну хмару, що завдає $s1 шкоди від сил природи кожні $t с гравцям у радіусі $s2 ярдів." },
    { en = "Leaving a Poison Pool afflicts the player with a lingering poison, inflicting $s1 Nature damage every $t1 sec for $d.", ua = "Залишення Отруйної калюжі накладає на гравця тривку отруту, що завдає $s1 шкоди від сил природи кожні $t1 с протягом $d." },
    { en = "Atroxus breathes out Noxious Fumes in front of itself, inflicting $s1 Nature damage to players struck.", ua = "Атроксус видихає перед собою Отруйні Випари, завдаючи $s1 шкоди від сил природи враженим гравцям." },
    { en = "The Toxic Creeper bites a player, causing them to suffer $s1% increased Nature damage for $d. This effect stacks.", ua = "Токсичний повзун кусає гравця, через що той зазнає на $s1% більше шкоди від сил природи протягом $d. Цей ефект накопичується." },
    { en = "Atroxus splashes poison around itself, inflicting $s1 Nature damage with an additional $s2 Nature damage every $t2 sec for $d to players struck. Each impact creates a poison pool for $1247420d.", ua = "Атроксус розбризкує отруту довкола себе, завдаючи $s1 шкоди від сил природи та додаткові $s2 шкоди від сил природи кожні $t2 с протягом $d ураженим гравцям. Кожне влучання утворює отруйну калюжу на $1247420d." },
    { en = "The Toxic Creeper fixates upon a player.", ua = "Токсичний повзун зосереджується на гравцеві." },
    { en = "Atroxus delivers a powerful blow to a player that inflicts $s1 Nature damage with an additional $s2 Nature damage every $t2 sec for $d.", ua = "Атроксус завдає гравцю потужного удару, що завдає $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "Atroxus's acidic venom inflicts $s1 Nature damage every $t1 sec to players standing within it.", ua = "Кислотна отрута Атроксуса завдає $s1 шкоди від природи кожні $t1 сек. гравцям, що стоять у ній." },
    { en = "Charonus summons a seeking Gravitic Orb near each player. The orb afflicts target player with $@spellname1287450 every $1263983t3 sec.\n\n\n\nIf the orb comes within 6 yards of an Unstable Singularity, its essence is torn apart and the orb is destroyed.", ua = "Харонус прикликає поряд із кожним гравцем гравітаційну кулю-шукача. Куля вражає ціль закляттям $@spellname1287450 кожні $1263983t3 с.\n\n\n\nЯкщо куля наблизиться до Нестабільної Сингулярності ближче ніж на 6 ярдів, її сутність розривається, а куля знищується." },
    { en = "Charonus projects condensed cosmic power toward nearby players. Players coming into contact with this energy suffer $s1 Shadow damage and are knocked away.", ua = "Харонус метає згущену космічну силу в гравців поблизу. Гравці, що торкаються цієї енергії, зазнають $s1 тіньової шкоди й відкидаються." },
    { en = "Charonus marks players and creates a gravity well at their location after 5.5 sec. Players within 12 yards of the well suffer $1264188s1 Shadow damage every $1264188t1 sec and are slowly pulled toward the center. Players within 6 yards suffer an additional $s2  Shadow damage every $t2 sec and have their movement speed reduced by $s1%.", ua = "Харонус позначає гравців і через 5.5 сек. створює гравітаційний колодязь на їхньому місці. Гравці в межах 12 ярдів від колодязя зазнають $1264188s1 тіньової шкоди кожні $1264188t1 сек. і повільно затягуються до центру. Гравці в межах 6 ярдів зазнають додатково $s2 тіньової шкоди кожні $t2 сек., а швидкість їхнього пересування зменшується на $s1%." },
    { en = "Gravitic Orbs fixate a player, inflicting $1287450s1 Shadow damage every $1287450t1 sec and reducing their movement speed by $1287450s2%. This effect stacks.", ua = "Гравітаційні сфери фіксуються на гравцеві, завдаючи $1287450s1 тіньової шкоди кожні $1287450t1 сек. і зменшуючи швидкість його пересування на $1287450s2%. Цей ефект накопичується." },
    { en = "Charonus releases a massive blast, knocking back all players and inflicting $s1 Shadow damage to them with an additional $s3 Shadow damage every $t3 sec for $d.", ua = "Харонус вивільняє потужну ударну хвилю, відкидаючи всіх гравців і завдаючи їм $s1 тіньової шкоди та додатково $s3 тіньової шкоди кожні $t3 сек. протягом $d." },
    { en = "Avanoxx feasts on any Starved Crawlers that reach her, increasing her damage done by $446794s1% for $446794d. This effect stacks.", ua = "Аваноксс пожирає всіх зголоднілих повзунів, що дістаються до неї, збільшуючи завдану нею шкоду на $446794s1% на $446794d. Цей ефект накопичується." },
    { en = "Web Wrap fully encases the player, incapacitating them for $d.", ua = "«Павутинний кокон» повністю огортає гравця, знерухомлюючи його на $d." },
    { en = "Avanoxx leaps to her primary target and unleashes 3 consecutive bites. Each bite inflicts $438949s1 Physical damage and the final bite further increases damage taken by $439200s1% for $439200d.", ua = "Аваноксс стрибає до своєї основної цілі й завдає 3 послідовні укуси. Кожен укус завдає $438949s1 фізичної шкоди, а останній укус додатково підвищує отримувану шкоду на $439200s1% протягом $439200d." },
    { en = "Avanoxx slings toxic webs in all directions, inflicting $438960s1 Nature damage every $438954t1 sec to all players for $438954d.\n\n\n\nAdditionally, this leaves behind $@spellname434830 at the targets' locations, which inflict $438966s1 Nature damage to players within $438966A1 yards of each impact.", ua = "Аваноксс розкидає отруйне павутиння в усіх напрямках, завдаючи $438960s1 шкоди від сил природи щороку $438954t1 сек усім гравцям протягом $438954d.\n\n\n\nКрім того, це залишає $@spellname434830 в місцях розташування цілей, що завдає $438966s1 шкоди від сил природи гравцям у радіусі $438966A1 м від кожного влучання." },
    { en = "Avanoxx releases a loud screech, calling forth Starved Crawlers from their eggs and inflicting $438495s1 Physical damage every $438494t1 sec to all players for $438494d.", ua = "Аваноксс видає гучний вереск, прикликаючи виголоднілих повзунів з їхніх яєць і завдаючи $438495s1 фізичної шкоди щороку $438494t1 сек усім гравцям протягом $438494d." },
    { en = "$@spellname434830 ensnares players standing within, reducing movement speed by $435466s1% and inflicting $s1 Nature damage every $t1 sec. This effect stacks.\n\n\n\nUpon reaching $s2 applications, the webbing develops into a $@spellname436614.", ua = "$@spellname434830 обплутує гравців, що стоять усередині, знижуючи швидкість пересування на $435466s1% і завдаючи $s1 шкоди від сил природи щороку $t1 сек. Цей ефект накопичується.\n\n\n\nСягнувши $s2 застосувань, павутиння розвивається в $@spellname436614." },
    { en = "The Starved Crawler fixates a random player and increases damage done by $439333s1% every $t1 sec. This effect stacks.", ua = "Виголоднілий повзун зосереджується на випадковому гравцеві й підвищує завдану шкоду на $439333s1% щороку $t1 сек. Цей ефект накопичується." },
    { en = "The Bloodstained Webmage encases its target in tight yet porous webbing, immobilizing the target and inflicting $s2 Nature damage every $t2 sec for $d.", ua = "Закривавлений Павутинний Маг огортає свою ціль тугою, але пористою павутиною, знерухомлюючи ціль і завдаючи $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "Upon reaching 100 energy, Anub'zekt calls forth a massive swarm surrounding the arena. While within the biting insect swarm, players rapidly gain applications of Ceaseless Swarm.", ua = "Сягнувши 100 енергії, Ануб'зект прикликає велетенський рій, що оточує арену. Перебуваючи в кусючому рої комах, гравці швидко накопичують застосування Невпинного Рою." },
    { en = "Anub'zekt calls a swarm to feast upon a random player, inflicting $s1 Nature damage every $t1 sec for $d.\n\n\n\nUpon removal, they will form into a $@spellname433747 and hunt for more prey.", ua = "Ануб'зект прикликає рій бенкетувати на випадковому гравцеві, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d.\n\n\n\nПісля зняття вони формуються у $@spellname433747 й полюють на нову здобич." },
    { en = "Anub'zekt burrows through a random player, inflicting $434284s2  Physical damage and knocking back players in his path. \n\n\n\nAt the end of his path, he erupts from the earth, inflicting $433731s1 Physical damage and knocking back players within $433731A1 yards.", ua = "Ануб'зект прориває під землею крізь випадкового гравця, завдаючи $434284s2 фізичної шкоди і відкидаючи гравців на своєму шляху.\n\n\n\nНаприкінці шляху він вибухає із землі, завдаючи $433731s1 фізичної шкоди і відкидаючи гравців у межах $433731A1 м." },
    { en = "Anub'zekt launches a cone of spikes through the earth at his current target, inflicting $s1 Physical damage to and knocking back players hit.", ua = "Ануб'зект пускає конус шипів крізь землю в поточну ціль, завдаючи $s1 фізичної шкоди вцілених гравців і відкидаючи їх." },
    { en = "The Ceaseless Swarm prowls the arena, seeking players to devour. When they come into contact with a player, they leave festering wounds inflicting $s1 Nature damage every $t1 sec and reducing movement speed by $s3% for $d. This effect stacks.", ua = "Невпинний Рій нишпорить ареною в пошуках гравців, щоб їх пожерти. Зіткнувшись із гравцем, він залишає гнійні рани, що завдають $s1 шкоди від сил природи кожні $t1 с і знижують швидкість пересування на $s3% протягом $d. Цей ефект накопичується." },
    { en = "Ki'katal the Harvester causes several spiderweb eruptions to occur, inflicting $432132s1 Nature damage and stunning players struck for $432132d.", ua = "Кі'катал Жниця спричиняє кілька вивержень павутиння, що завдають $432132s1 шкоди від сил природи і приголомшують вражених гравців на $432132d." },
    { en = "Ki'katal the Harvester blasts all players with venom, reducing their movement speed by $s3% and inflicting $s1 Nature damage immediately with an additional $s2 Nature damage every $t2 sec for $d.", ua = "Кі'катал Жниця обдає всіх гравців отрутою, знижуючи їхню швидкість пересування на $s3% і завдаючи $s1 шкоди від сил природи негайно, а також додаткові $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "Ki'katal the Harvester injects a growing poison in $s2 players, inflicting $s1 Nature damage every $t1 sec for $d. Upon removal, it erupts forth in waves and inflicts $461507s1 Nature damage and an additional $461507s2 Nature damage every $461507t2 sec for $461507d to players struck.", ua = "Кі'катал Жниця впорскує $s2 гравцям отруту, що наростає, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. При знятті вона прориває хвилями і завдає вражденим гравцям $461507s1 шкоди від сил природи та додатково $461507s2 шкоди від сил природи кожні $461507t2 с протягом $461507d." },
    { en = "Ki'katal the Harvester pulls in all players and begins create a spatial distortion. Upon finishing the cast, all players within $A1 yards suffer $s1 Shadow damage and are knocked away.", ua = "Кі'катал Жниця притягує всіх гравців і починає створювати просторове викривлення. Завершивши прочитання, завдає всім гравцям у межах $A1 ярдів $s1 тіньової шкоди й відкидає їх геть." },
    { en = "Players struck by $@spellname432117 have their essences partially dissolved, reducing damage done by $s1% and increasing damage taken by $s2% for $d.", ua = "У гравців, уражених $@spellname432117, частково розчиняється їхня есенція, через що завдавана ними шкода зменшується на $s1%, а отримувана шкода зростає на $s2% на $d." },
    { en = "Stepping within a spilled pool of Black Blood causes it to congeal and root the target in place for $d, inflicting $s2 Shadow damage every $t2 sec. The Black Blood can be destroyed to free the player.", ua = "Якщо ступити в розлиту калюжу Чорної Крові, вона загусає й прикорінює ціль на місці на $d, завдаючи $s2 тіньової шкоди кожні $t2 сек. Чорну Кров можна знищити, щоб звільнити гравця." },
    { en = "Benk Buzzbee commands Cindy to furiously beat her wings, summoning a small gust around her that pushes players away and inflicts $439586s1 Nature damage to all players every $439586t1 sec for $d.", ua = "Бенк Баззбі наказує Сінді люто бити крилами, прикликаючи навколо неї невеликий порив вітру, що відштовхує гравців і завдає $439586s1 шкоди від сил природи всім гравцям щороку $439586t1 сек протягом $d." },
    { en = "Benk Buzzbee coats his current target in flammable honey. After $d the player ignites, inflicting $440138s1 Fire damage to players within $440138A1 yards of their location.\n\n\n\nFlaming honey remains on the ground, inflicting $440141s1 Fire damage every $440141t1 sec to players standing within the effect.", ua = "Бенк Баззбі вкриває свою поточну ціль займистим медом. За $d гравець спалахує, завдаючи $440138s1 вогняної шкоди гравцям у межах $440138A1 ярдів від свого місця.\n\n\n\nПалаючий мед лишається на землі, завдаючи $440141s1 вогняної шкоди кожні $440141t1 сек гравцям, що стоять у межах дії ефекту." },
    { en = "Benk Buzzbee summons barrels of delicious honey. The collision inflicts $438651s2 Physical damage to players standing within $438651A2 yards of the impact.\n\n\n\nThe honey's aroma attracts a Ravenous Cinderbee every $438663t1 sec.", ua = "Бенк Баззбі прикликає діжки смачнючого меду. Зіткнення завдає $438651s2 фізичної шкоди гравцям, що стоять у межах $438651A2 ярдів від місця удару.\n\n\n\nАромат меду приваблює Ненажерливу Попелясту Бджолу кожні $438663t1 сек." },
    { en = "The Ravenous Cinderbee musters the last of its strength to charge forward $A1 yards before finally perishing.\n\n\n\nThe force of the collision will destroy any Honey Barrels in its path.", ua = "Ненажерлива попеляста бджола збирає рештки сил, щоб ринути вперед на $A1 ярдів, перш ніж остаточно загинути.\n\n\n\nСила зіткнення знищить будь-які діжки з медом на її шляху." },
    { en = "The Ravenous Cinderbee binges on the $@spellname440140, healing themselves for $s4 health every $t4 sec. \n\n\n\nThe honey's sugar increases their haste by $s1% and causes them to become immune to crowd control effects.", ua = "Ненажерлива попеляста бджола обжирається $@spellname440140, зцілюючи себе на $s4 здоров'я кожні $t4 с.\n\n\n\nЦукор меду підвищує її поспіх на $s1% і робить її несприйнятливою до ефектів контролю." },
    { en = "The Cinderbee leaps to an enemy and lodges its stinger into them. The puncture wound bleeds $s1 Physical damage every $t1 sec for $d.", ua = "Попеляста бджола стрибає до ворога й встромляє в нього жало. Колота рана кровоточить, завдаючи $s1 фізичної шкоди щороку $t1 сек протягом $d." },
    { en = "Upon reaching 1% health, Ravenous Cinderbees become docile and can be ridden by players.\n\n\n\nAfter $d the Ravenous Cinderbee perishes.", ua = "Сягнувши 1% здоров'я, ненажерливі попелясті бджоли стають слухняними, і гравці можуть на них їздити.\n\n\n\nЗа $d ненажерлива попеляста бджола гине." },
    { en = "Scalding honey forms on the ground for $432186d, inflicting $s1 Fire damage every $t1 sec to players standing within and reducing their movement speed by $s2%.", ua = "На землі утворюється кипучий мед на $432186d, що завдає $s1 вогняної шкоди щосекунди ($t1) гравцям, які стоять у ньому, і знижує їхню швидкість пересування на $s2%." },
    { en = "Brew Master Aldryr smashes a keg into his current target, inflicting $s1 Physical damage and knocking them back. The keg splinters, forming $@spellname432196.", ua = "Майстер-броварник Алдрір розбиває барило об свою поточну ціль, завдаючи $s1 фізичної шкоди й відкидаючи її. Барило розколюється, утворюючи $@spellname432196." },
    { en = "Brew Master Aldryr takes a swig of Cinderbrew and unleashes a fiery belch towards a player, inflicting $s2 Fire damage to players in a frontal cone.", ua = "Майстер-броварник Алдрір робить ковток Жаровару й вивергає вогняну відрижку в бік гравця, завдаючи $s2 вогняної шкоди гравцям у конусі перед собою." },
    { en = "Brew Master Aldryr ignores all distractions until players serve his Thirsty Patrons, reducing all damage taken by $s1%.", ua = "Майстер-броварник Алдрір нехтує всіма відволіканнями, доки гравці не обслужать його Спраглих відвідувачів, знижуючи всю отриману шкоду на $s1%." },
    { en = "Brew Master Aldryr tosses hot Cinderbrew at players, inflicting $s1 Fire damage every $t1 sec for $d and forming $@spellname432186 underneath.", ua = "Майстер-броварник Алдрір хлюпає гарячим «Жароваром» на гравців, завдаючи $s1 вогняної шкоди кожні $t1 с протягом $d і утворюючи під ними $@spellname432186." },
    { en = "Thirsty Patrons slam their table, inflicting $431897s1 Physical damage to all players every $t1 sec and reducing their haste by $431897s2%.\n\n\n\nWhen given a mug of Cinderbrew, these patrons cease their tantrum.", ua = "Спраглі відвідувачі гамселять по столу, завдаючи $431897s1 фізичної шкоди всім гравцям кожні $t1 сек і знижуючи їхній поспіх на $431897s2%.\n\n\n\nОтримавши кухоль Жаровару, ці відвідувачі припиняють буянити." },
    { en = "A barroom brawl breaks out in a flurry of fists and thick heads for $445234d. Players coming into contact with the brawl are stunned and suffer $s2 Physical damage every $t2 sec for $d.", ua = "Спалахує шинкова бійка з вихором кулаків і затьмарених голів на $445234d. Гравці, що потрапляють у сутичку, оглушуються й зазнають $s2 фізичної шкоди кожні $t2 сек протягом $d." },
    { en = "At 66% and 33% health, Brew Master Aldryr leaps behind the counter to pour Cinderbrew for Thirsty Patrons. While pouring, he $@spellname442611s players.", ua = "На 66% і 33% здоров'я Майстер-броварник Алдрір стрибає за стійку, щоб налити Жаровару спраглим відвідувачам. Поки наливає, він $@spellname442611s гравців." },
    { en = "Goldie Baronbottom arcs a bullet off of a flipped coin, inflicting $s1 Fire damage with an additional $s2 Fire damage every $t2 sec for $d. \n\n\n\nThe burning bullet ricochets to other players and Cinderbrew Bombs within $s3 yards. Any Cinderbrew Bombs hit will erupt with $@spellname435788.", ua = "Ґолді Баронботтом запускає кулю рикошетом від підкинутої монети, завдаючи $s1 вогняної шкоди та додатково $s2 вогняної шкоди кожні $t2 сек. протягом $d. \n\n\n\nПалаюча куля рикошетить до інших гравців і Бомб Жаровару в межах $s3 ярдів. Будь-яка вражена Бомба Жаровару вибухає з $@spellname435788." },
    { en = "Upon reaching 100 energy Goldie Baronbottom fires wildly into the air, detonating all remaining Cinderbrew Bombs and inflicting $442484s1 Fire damage to all players every $t3 sec for $d.", ua = "Досягнувши 100 енергії, Ґолді Баронботтом безладно палить у повітря, підриваючи всі вцілілі Жароварні бомби та завдаючи $442484s1 вогняної шкоди всім гравцям кожні $t3 сек. протягом $d." },
    { en = "Cinderbrew Bombs detonate upon being struck by Goldie Baronbottom, erupting and sending out waves of fire that inflicts $s1 Fire damage to players struck and knocks them back.", ua = "Бомби Жаровару детонують, коли в них влучає Ґолді Баронботтом, вибухаючи й розсилаючи хвилі вогню, що завдають $s1 вогняної шкоди враженим гравцям і відкидають їх назад." },
    { en = "Volatile Barrels explode causing all players to burn, inflicting $s1 Fire damage every $t1 sec for $d.\n\n\n\nThis effect stacks.", ua = "Нестабільні Барила вибухають, спалюючи всіх гравців і завдаючи $s1 вогняної шкоди кожні $t1 с протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Goldie Baronbottom stomps the ground, causing  several Cinderbrew Bombs to fall into the room.", ua = "Ґолді Баронботтом гупає об землю, через що в кімнату падає кілька Бомб Жаровару." },
    { en = "Goldie Baronbottom blasts players and Cinderbrew Bombs with gold coins, inflicting $s1 Physical damage in a frontal cone and knocking back all players struck. Any Cinderbrew Bombs hit will erupt with $@spellname435788.", ua = "Ґолді Баронботтом обстрілює гравців і Бомби Жаровару золотими монетами, завдаючи $s1 фізичної шкоди в передньому конусі й відкидаючи всіх влучених гравців. Будь-які влучені Бомби Жаровару вибухнуть ефектом $@spellname435788." },
    { en = "I'pa slathers players in burning mead, inflicting $s1 Fire damage every $t1 sec for $d.", ua = "І'па обливає гравців палаючим медом, завдаючи $s1 вогняної шкоди кожні $t1 сек. протягом $d." },
    { en = "I'pa expels mead, inflicting $s1 Fire damage to all players every $439365t1 sec for $439365d. Mead droplets fling outward, inflicting an additional $439991s1 Fire damage to players within $439991A1 yards.\n\n\n\nSome droplets form into Brew Drops.", ua = "І'па вивергає медовуху, завдаючи $s1 вогняної шкоди всім гравцям кожні $439365t1 с протягом $439365d. Краплі медовухи розлітаються назовні, завдаючи додаткові $439991s1 вогняної шкоди гравцям у радіусі $439991A1 ярдів.\n\n\n\nДеякі краплі формуються в Краплі Вару." },
    { en = "I'pa consumes Brew Drops it touches, inflicting $442108s1 Fire damage to all players and granting I'pa a shield that absorbs damage equal to $s2% of its maximum health.", ua = "І'па споживає краплі браги, яких торкається, завдаючи $442108s1 вогняної шкоди всім гравцям і даруючи І'па щит, що поглинає шкоду в розмірі $s2% від його максимального здоров'я." },
    { en = "Upon reaching 100 energy the Brew Drop's increases its movement speed by $s2%.", ua = "Сягнувши 100 енергії, Крапля Вару підвищує свою швидкість пересування на $s2%." },
    { en = "Brew Drops ooze burning honey upon death, inflicting $s1 Fire damage every $t1 sec to players standing within and reducing their movement speed by $s2%.\n\n\n\nThis honey shrinks over time, causing the Brew Drop to reform once it dissipates.", ua = "Краплі Вару, гинучи, сочаться палаючим медом, завдаючи $s1 вогняної шкоди кожні $t1 сек гравцям, що стоять усередині, і знижуючи їхню швидкість пересування на $s2%.\n\n\n\nЦей мед з часом меншає, тож Крапля Вару відновлюється, щойно він розсіється." },
    { en = "Brew Drops ooze burning honey upon death, inflicting $s1 Fire damage every $t1 sec to players standing within and reducing their movement speed by $s2%.\n\n\n\nThis honey shrinks over time.", ua = "Краплі браги по смерті сочаться палючим медом, завдаючи $s1 вогняної шкоди кожні $t1 сек гравцям, що стоять усередині, і знижуючи їхню швидкість пересування на $s2%.\n\n\n\nЦей мед з часом зменшується." },
    { en = "I'pa punches its current target with a fist full of brew, inflciting $s1 Physical damage and knocking them back.", ua = "І'па б'є свою поточну ціль кулаком, повним вару, завдаючи $s1 фізичної шкоди й відкидаючи її." },
    { en = "Orator Krix'vizk lashes out at his current target, inflicting $s1 Shadow damage and $434723s1 Physical damage and reducing their movement speed by $s2% for $d.", ua = "Оратор Крікс'візк накидається на свою поточну ціль, завдаючи $s1 тіньової шкоди і $434723s1 фізичної шкоди та знижуючи її швидкість пересування на $s2% протягом $d." },
    { en = "Orator Krix'vizk torments all players with a litany of dark propaganda, inflicting $434832s1 Shadow damage every $t1 sec for $d.\n\n\n\nLeaves behind an area of $@spellname434926.", ua = "Оратор Крікс'візк мучить усіх гравців литанією темної пропаганди, завдаючи $434832s1 тіньової шкоди кожні $t1 с протягом $d.\n\n\n\nЗалишає по собі ділянку $@spellname434926." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec to players who remain within the area.", ua = "Завдає $s1 тіньової шкоди кожні $t1 сек гравцям, що лишаються в зоні." },
    { en = "Orator Krix'vizk infects players' minds with doubt, inflicting $s1 Shadow damage every $t1 sec for $d.\n\n\n\nUpon expiration or removal, doubts explode outward from the target inflicting $448562s1 Shadow damage to players hit and stunning them for $448562d.", ua = "Оратор Крікс'візк заражає розум гравців сумнівом, завдаючи $s1 тіньової шкоди кожні $t1 с протягом $d.\n\n\n\nПісля завершення або знаття сумніви вибухають назовні від цілі, завдаючи $448562s1 тіньової шкоди враженим гравцям і приголомшуючи їх на $448562d." },
    { en = "Orator Krix'vizk binds all players with dark magic. Whenever a player is more than $440310s1 yards away for more than $440310t1 sec, Krix'vizk inflicts $s1 Shadow damage and forces them back into range.", ua = "Оратор Крікс'візк зв'язує всіх гравців темною магією. Щоразу, коли гравець перебуває далі ніж за $440310s1 м понад $440310t1 с, Крікс'візк завдає йому $s1 тіньової шкоди і силоміць повертає його в межі досяжності." },
    { en = "Orator Krix'vizk unleashes a terrifying screech toward a player, inflicting $s1 Shadow damage to players in a cone in front of him and forcing them to cower in fear for $d.", ua = "Оратор Крікс'візк вивергає жахливий вереск у бік гравця, завдаючи $s1 тіньової шкоди гравцям у конусі перед собою й змушуючи їх скулитися від страху на $d." },
    { en = "Upon reaching 100 energy, Nx and Vx repeatedly dash across the arena inflicting $440049s1 Physical damage to players in their path. They then swap between attacking and supporting roles.", ua = "Сягнувши 100 енергії, Нкс і Вкс багаторазово ринуть через арену, завдаючи $440049s1 фізичної шкоди гравцям на своєму шляху. Потім вони міняються ролями нападу й підтримки." },
    { en = "Nx slashes in the direction of their current target, inflicting $439686s1 Physical and $439687s1 Shadow damage to players in a cone in front of them and leaving behind an $@spellname439637.", ua = "Нкс рубає в напрямку своєї поточної цілі, завдаючи $439686s1 фізичної та $439687s1 тіньової шкоди гравцям у конусі перед собою й лишаючи по собі $@spellname439637." },
    { en = "The caster throws a knife at a player, inflicting $s1 Physical damage and an additional $s2 Physical damage every $t2 sec for $d.", ua = "Той, хто творить закляття, кидає в гравця ніж, завдаючи $s1 фізичної шкоди та додаткові $s2 фізичної шкоди кожні $t2 сек упродовж $d." },
    { en = "Nx calls upon the darkness inflicting $439697s1 Shadow damage to all players every $t1 sec for $d, then unleashes its power to inflict $439696s1 Shadow damage to players within $439696A1 yards of Nx and his Echoing Shades.", ua = "Нкс прикликає пітьму, завдаючи $439697s1 тіньової шкоди всім гравцям кожні $t1 сек. протягом $d, а потім вивільняє її силу, завдаючи $439696s1 тіньової шкоди гравцям у межах $439696A1 ярдів від Нкс і його Лунких Тіней." },
    { en = "Vx imbues her daggers with ice and plunges them into her current target, inflicting $441295s1 Physical damage and afflicting $441298s2 applications of $@spellname441298. The daggers then burst inflicting $441305s1 Frost damage to all players.", ua = "Вкс просочує свої кинджали кригою й встромляє їх у поточну ціль, завдаючи $441295s1 фізичної шкоди й накладаючи $441298s2 застосувань $@spellname441298. Потім кинджали вибухають, завдаючи $441305s1 морозної шкоди всім гравцям." },
    { en = "Nx's shadows echo his $@spellname439621 in the direction they're currently facing.", ua = "Тіні Нкса повторюють його $@spellname439621 у тому напрямку, куди вони наразі дивляться." },
    { en = "The target's blood begins to freeze solid, inflicting $s1 Frost damage every $t1 sec. This effect stacks.\n\n\n\nStanding near another player removes 1 application of this effect per player every $t1 sec.", ua = "Кров цілі починає замерзати, завдаючи $s1 морозної шкоди кожні $t1 с. Цей ефект накопичується.\n\n\n\nПеребування поруч з іншим гравцем знімає 1 накладання цього ефекту за гравця кожні $t1 с." },
    { en = "Upon reaching $441433s2 applications of $@spellname441298 the player is frozen solid, stunning them and inflicting $s2 Frost damage every $t2 sec for $d.", ua = "Досягнувши $441433s2 накладань $@spellname441298, гравець замерзає, що приголомшує його й завдає $s2 морозної шкоди кожні $t2 с на $d." },
    { en = "Vx aims frosted daggers at several players, inflicting $440238s1 Frost damage to all targets within the dagger's line of travel. The dagger remains embedded in the target, reducing movement speed by $440238s3% and inflicts an additional $440238s2 Frost damage every $440238t2 sec for $440238d.", ua = "Вкс цілиться морозними кинджалами в кількох гравців, завдаючи $440238s1 морозної шкоди всім цілям на траєкторії польоту кинджала. Кинджал лишається застряглим у цілі, знижуючи швидкість пересування на $440238s3% та завдаючи додатково $440238s2 морозної шкоди кожні $440238t2 сек. протягом $440238d." },
    { en = "The Fangs of the Queen harness a synergistic power, causing them to share $s1% of all damage taken.", ua = "Ікла Королеви черпають синергічну силу, завдяки чому розподіляють між собою $s1% усієї отриманої шкоди." },
    { en = "The Coaglamation slams the ground knocking players back and releasing orbs of congealed black blood from canisters throughout the arena that travel towards it. \n\n\n\nOrbs of black blood that reach The Coaglamation are absorbed, restoring $441222s1% of its maximum health.\n\n\n\nPlayers that touch orbs of black blood absorb them and are afflicted with $@spellname442285. $?diff23|diff8[Absorbing an orb creates a pool of black blood at its location, inflicting $459961s2 Shadow damage to all players within the pool and reduces their movement speed by $445435s1%.][]", ua = "Коаґламат вдаряє об землю, відкидаючи гравців і вивільняючи з каністр по всій арені кулі згуслої чорної крові, що рухаються в його бік.\n\n\n\nКулі чорної крові, що досягають Коаґламата, поглинаються, відновлюючи $441222s1% його максимального здоров'я.\n\n\n\nГравці, що торкаються куль чорної крові, поглинають їх і зазнають дії ефекту $@spellname442285. $?diff23|diff8[Поглинання кулі створює на її місці калюжу чорної крові, що завдає $459961s2 тіньової шкоди всім гравцям у калюжі та зменшує їхню швидкість пересування на $445435s1%.][]" },
    { en = "Players that come into contact with an orb of black blood are coated in a vile coating, absorbing $s1 healing.", ua = "Гравці, що торкаються кулі чорної крові, вкриваються мерзенним нашаруванням, яке поглинає $s1 зцілення." },
    { en = "The Coaglamation slams its current target, inflicting $s1 Shadow damage and reducing healing received by $s2% for $d.", ua = "Коаґламат вгачує свою поточну ціль, завдаючи $s1 тіньової шкоди і знижуючи отримуване зцілення на $s2% протягом $d." },
    { en = "$?diff23|diff8[The Coaglamation roars, inflicting $461880s1 Shadow damage to players within $461880a1 yards and creates a growing pool of black blood at its location.][The Coaglamation excites the blood reservoirs causing black blood to spill outward from them and form pools.] Players standing in these pools suffer $438601s1 Shadow damage every $445420t1 sec and their movement speed is reduced by $445435s1% while standing in the area.", ua = "$?diff23|diff8[Коаґламат реве, завдаючи $461880s1 тіньової шкоди гравцям у межах $461880a1 м і створюючи на своєму місці калюжу чорної крові, що розростається.][Коаґламат збурює резервуари крові, через що чорна кров виливається з них і утворює калюжі.] Гравці, що стоять у цих калюжах, зазнають $438601s1 тіньової шкоди кожні $445420t1 с, а їхня швидкість пересування знижується на $445435s1%, поки вони перебувають у зоні." },
    { en = "Upon reaching 100 energy, The Coaglamation throbs violently, releasing dark energy that inflicts $s1 Shadow damage every $441395t1 sec to all players.", ua = "Сягнувши 100 енергії, Коаґламат шалено пульсує, вивільняючи темну енергію, що завдає $s1 тіньової шкоди кожні $441395t1 сек усім гравцям." },
    { en = "Izo uses her mastery of alchemical transformation to assume the form of a Nerubian Lord.\n\n\n\nShe then slams the ground with all her might, inflicting $s2 Nature damage to all players and an additional $s1 Nature damage to players within $A1 yards.", ua = "Ізо застосовує свою майстерність алхімічного перетворення, щоб прибрати подобу нерубіанського володаря.\n\n\n\nПотім вона щосили б'є об землю, завдаючи $s2 шкоди від сил природи всім гравцям і додатково $s1 шкоди від сил природи гравцям у межах $A1 ярдів." },
    { en = "The Scarab explodes in a shower of acid and viscera, inflicting $s1 Nature damage every $t1 sec and stunning players within $A1 yards for $d. The Scarab is killed in the process.", ua = "Скарабей вибухає бризками кислоти й нутрощів, завдаючи $s1 шкоди від сил природи кожні $t1 с і приголомшуючи гравців у межах $A1 ярдів на $d. У процесі скарабея вбиває." },
    { en = "Izo creates spheres of anomalous energy that inflict $439481s1 Shadow damage and knock back players on contact. The anomalies periodically relocate to new positions.", ua = "Ізо створює сфери аномальної енергії, що завдають $439481s1 тіньової шкоди й відкидають гравців при дотику. Аномалії періодично переміщуються на нові позиції." },
    { en = "Izo uses her mastery of alchemical transformation to assume the form of a Nerubian Sage.\n\n\n\nShe then ensnares all players in shadowy webs, inflicting $439324s1 Shadow damage and rooting them in place for $439324d or until the webs are destroyed.", ua = "Ізо використовує свою майстерність алхімічного перетворення, щоб набути подоби Нерубіанської Мудреці.\n\n\n\nПотім вона обплутує всіх гравців тіньовою павутиною, завдаючи $439324s1 тіньової шкоди й знерухомлюючи їх на $439324d або доки павутину не буде знищено." },
    { en = "Izo injects experimental strands into all players, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Ізо вприскує всім гравцям піддослідні нитки, завдаючи $s1 тіньової шкоди кожні $t1 с протягом $d." },
    { en = "The Scarab gorges on the flesh of its current target, inflicting $s1 Physical damage.", ua = "Скарабей пожирає плоть своєї поточної цілі, завдаючи $s1 фізичної шкоди." },
    { en = "Izo recalls all anomalies to her location then violently smashes them into her target one at a time, inflicting $439763s1 Shadow and $439764s1 Physical damage to players within $439763a1 yards a total of $s1 times over $d.", ua = "Ізо відкликає всі аномалії до свого місця, а тоді люто жбурляє їх у ціль по одній, завдаючи $439763s1 тіньової та $439764s1 фізичної шкоди гравцям у межах $439763a1 ярдів, загалом $s1 разів за $d." },
    { en = "Successful casts of $@spellname450042 increase the Scarab's size.\n\n\n\nAfter gorging $s2 times, trigger $@spellname450055.", ua = "Успішні прочитання $@spellname450042 збільшують розмір скарабея.\n\n\n\nПісля $s2 пожирань спрацьовує $@spellname450055." },
    { en = "Ol' Waxbeard pierces his current target's armor with their pickaxe, inflicting $s2 Physical damage and increases Physical damage taken by $s1% for $d.", ua = "Старий Воскобород пробиває броню своєї поточної цілі кайлом, завдаючи $s2 фізичної шкоди й збільшуючи отримувану фізичну шкоду на $s1% протягом $d." },
    { en = "Ol' Waxbeard commands Wick to charge towards the furthest player. This attack knocks back and inflicts $s1 Physical damage to all players and triggers a $@spellname422270 at the end of the charge.\n\n\n\nFatal to Menial Laborers.", ua = "Старий Воскобород наказує Ґноту мчати до найвіддаленішого гравця. Ця атака відкидає й завдає $s1 фізичної шкоди всім гравцям і спричиняє $@spellname422270 наприкінці ривка.\n\n\n\nСмертельно для Чорноробів." },
    { en = "Menial Laborers sneak a dynamite laden cart onto the nearby tracks. If it is not destroyed within $429093s4 sec, it explodes inflicting $429093s1 Fire damage to all players with an additional $429093s2 Fire damage every $429093t2 sec for $429093d.", ua = "Чорнороби потайки викочують візок із динамітом на найближчі рейки. Якщо його не знищити за $429093s4 сек, він вибухає, завдаючи $429093s1 вогняної шкоди всім гравцям, а також додатково $429093s2 вогняної шкоди щороку $429093t2 сек протягом $429093d." },
    { en = "Waxbeard throws a fresh lit candle at a random player. The burning wax inflicts $460839s1 Fire damage every $460839t sec and causes all Menial Laborers to fixate on that target for $d.", ua = "Воскобород жбурляє свіжозапалену свічку у випадкового гравця. Палаючий віск завдає $460839s1 вогняної шкоди кожні $460839t сек і змушує всіх Чорноробів зосередитися на цій цілі протягом $d." },
    { en = "Ol' Waxbeard calls Menial Laborers into battle on foot or by minecart.", ua = "Старий Воскобород закликає до бою чорноробів пішки або на вагонетці." },
    { en = "The minecart slams into anything in its path knocking back and inflicting $s1 Physical damage to players it strikes.\n\n\n\nFatal to Menial Laborers.", ua = "Вагонетка врізається в усе на своєму шляху, відкидаючи й завдаючи $s1 фізичної шкоди гравцям, яких влучає.\n\n\n\nСмертельно для чорноробів." },
    { en = "Menial Laborers' attacks inflicts $s1 Physical Damage every $t sec for $d. This effect stacks.", ua = "Атаки Чорноробів завдають $s1 фізичної шкоди кожні $t сек протягом $d. Цей ефект накопичується." },
    { en = "Ol' Waxbeard's charge reverberates through the cave, dropping boulders above each player after a short delay. Boulders inflict $422274s1 Nature damage within $422274A1 yards.\n\n\n\nFatal to Menial Laborers.", ua = "Ривок Старого Воскоборода прокочується відлунням по печері, скидаючи валуни над кожним гравцем після короткої затримки. Валуни завдають $422274s1 шкоди від сил природи в межах $422274A1 м.\n\n\n\nСмертельно для чорноробів." },
    { en = "Blazikon hurls a torrent of flames at players, inflicting $s1 Fire damage to players within $A1 yards of each impact.\n\n\n\nThe flames of Wicklighter Barrage ignite candles.", ua = "Блейзікон вивергає потік полум'я в гравців, завдаючи $s1 вогняної шкоди гравцям у межах $A1 ярдів від кожного влучання.\n\n\n\nПолум'я Залпу Ґнотопалія запалює свічки." },
    { en = "Blazikon forms gusting winds toward target players. Tornadoes that reach players inflict $s1 Nature damage.\n\n\n\nTornadoes extinguish candles they touch.", ua = "Блейзікон здіймає рвучкі вітри в бік цілей-гравців. Торнадо, що дістаються до гравців, завдають $s1 шкоди від сил природи.\n\n\n\nТорнадо гасять свічки, яких торкаються." },
    { en = "Blazikon summons strong winds, inflicting $s1 Nature damage to all players and extinguishing all candles.", ua = "Блейзікон закликає сильні вітри, завдаючи $s1 шкоди від сил природи всім гравцям і гасячи всі свічки." },
    { en = "Blazikon invokes the power of flames when no players are in melee combat, inflicting $s1 Fire damage to all players.", ua = "Блейзікон закликає міць полум'я, коли жоден гравець не перебуває в ближньому бою, завдаючи $s1 вогняної шкоди всім гравцям." },
    { en = "Blazikon unleashes a fiery burst towards each extinguished candle, reigniting that candle and inflicting $s1 Fire damage to all players in its path.\n\n\n\nThe inferno sears all players, inflicting $1218308s1 Fire damage every $1218308t1 sec for $1218308d. This effect stacks.", ua = "Блейзікон вивільняє вогняний спалах до кожної згаслої свічки, знову її запалюючи й завдаючи $s1 вогняної шкоди всім гравцям на своєму шляху.\n\n\n\nПекельне полум'я обпікає всіх гравців, завдаючи $1218308s1 вогняної шкоди щороку $1218308t1 сек протягом $1218308d. Цей ефект накопичується." },
    { en = "Blazikon causes all lit candles to surge with incandescent heat and spread burning patches of embers. These flames inflict $s1 Fire damage every $t1 sec to players standing within.", ua = "Блейзікон змушує всі запалені свічки спалахнути розжареним жаром і розкидати палаючі жарини. Це полум'я завдає $s1 вогняної шкоди кожні $t1 сек гравцям, що стоять усередині." },
    { en = "The Candle King amplifies players' fear of the dark, causing them to flee in fear for $d.", ua = "Свічковий король підсилює в гравців страх темряви, змушуючи їх тікати в жаху протягом $d." },
    { en = "When a wax statue melts down, it forms a pool of molten wax for $420963d. Standing within inflicts $s1 Fire damage every $t1 sec.", ua = "Коли воскова статуя розплавляється, вона утворює калюжу розплавленого воску на $420963d. Перебування в ній завдає $s1 вогняної шкоди щороку $t1 сек." },
    { en = "Evil darkness flows from each wax statue. A player coming within $s1 yards of a statue causes the wax to flow from it and encase the player completely. This effect stuns the target for $421653d.", ua = "Зловісна пітьма струмує з кожної воскової статуї. Коли гравець наближається до статуї на $s1 ярдів, віск стікає з неї та повністю огортає гравця. Цей ефект оглушує ціль на $421653d." },
    { en = "The Candle King forms several wax statues of players. Each statue inflicts $420919s1 Fire damage to all players every $420918t1 sec as long as it survives.", ua = "Свічковий король формує кілька воскових статуй гравців. Кожна статуя завдає $420919s1 вогняної шкоди всім гравцям кожні $420918t1 сек, поки вона існує." },
    { en = "The Candle King marks random players. After a short time, he hurls the shadowy flames at them, inflicting $421146s1 Shadow damage to targets within $421146A1 yards and absorbing the next $421146s2 healing on them. These flames are strong enough to melt wax creations.", ua = "Свічковий король позначає випадкових гравців. За мить він жбурляє в них тіньове полум'я, завдаючи $421146s1 тіньової шкоди цілям у межах $421146A1 ярдів і поглинаючи наступні $421146s2 зцілення на них. Це полум'я достатньо сильне, щоб плавити воскові витвори." },
    { en = "The Candle King readies a pickaxe to throw at a target. The pickaxe collides with the first target it hits, inflicting $421282s1 Shadow damage and knocking them back. If it strikes a wax statue, it instead shatters it.", ua = "Свічковий король готується метнути кайло в ціль. Кайло влучає в першу ціль на своєму шляху, завдаючи $421282s1 тіньової шкоди та відкидаючи її назад. Якщо воно влучає у воскову статую, то натомість розбиває її." },
    { en = "The Darkness targets a player with a massive blast. After $427015d, the shadows erupt, inflicting $s1 Shadow damage to players within $A1 yds. If this effect hits the Candlelight, it reduces its heat.", ua = "Пітьма обирає гравця ціллю для потужного вибуху. Через $427015d тіні вивергаються, завдаючи $s1 тіньової шкоди гравцям у межах $A1 м. Якщо цей ефект влучає у Свічкове Світло, він зменшує його жар." },
    { en = "Wriggling Darkspawns drain the flames from a candle, reducing its heat by $s1 and inflicting $439010s1  Shadow damage to players every $t1 sec for $d.", ua = "Звивисті Темнопороддя висмоктують полум'я зі свічки, зменшуючи її жар на $s1 і завдаючи $439010s1  шкоди від тіні гравцям кожні $t1 с протягом $d." },
    { en = "The Darkness releases waves of pure shadow every $t1 sec for $d. Each wave inflicts $428276s1 Shadow damage to all players and reduces the Candlelight's heat.", ua = "Пітьма вивільняє хвилі чистої тіні щороку $t1 сек протягом $d. Кожна хвиля завдає $428276s1 тіньової шкоди всім гравцям і зменшує тепло свічкового світла." },
    { en = "Remaining within the candle light protects the player from $@spellname422806, but reduces the heat level of the candle over time. Players can pick up and move the candle light source.", ua = "Перебування у світлі свічки захищає гравця від $@spellname422806, але з часом знижує рівень жару свічки. Гравці можуть підняти й переносити джерело свічкового світла." },
    { en = "The Darkness beckons multiple Wriggling Darkspawn to crawl out of the shadows.", ua = "Пітьма манить численних звивистих породжень пітьми виповзти з тіней." },
    { en = "Darkness enshrouds the area. All players without a light source have their damage and healing done reduced by $s1%.", ua = "Пітьма огортає місцевість. Усім гравцям без джерела світла завдана шкода та зцілення знижуються на $s1%." },
    { en = "The Darkness readies its claws and slashes out in a line towards the Candlelight. The wave of darkness inflicts $s1 Shadow damage to players hit and reduces the Candlelight's heat.", ua = "Пітьма готує пазурі й б'є ними по прямій у бік Світла Свічок. Хвиля пітьми завдає $s1 тіньової шкоди враженим гравцям і зменшує жар Світла Свічок." },
    { en = "Hurl a lump of wax gathered from a dead Candlebearer to restore heat to your candle.", ua = "Кидає грудку воску, зібрану з мертвого свіченосця, щоб відновити тепло вашої свічки." },
    { en = "If the candle heat is depleted, The Darkness wreathes the area in gloom, inflicting $s1 Shadow damage to all players and causing them to flee in fear for $427180d. This also increases their damage taken by $s2% and reduces their haste by $s3% for $d. This effect stacks.", ua = "Якщо тепло свічки вичерпано, Пітьма огортає місцевість мороком, завдаючи $s1 тіньової шкоди всім гравцям і змушуючи їх тікати в страху протягом $427180d. Це також підвищує отримувану ними шкоду на $s2% і знижує їхній поспіх на $s3% протягом $d. Цей ефект накопичується." },
    { en = "Captain Dailcry and his trusted guard are bound by holy light, causing all four to share health while near each other. Captain Dailcry's presence increases the health of his nearby trusted guard by $462855s1%.", ua = "Капітан Дейлкрай і його вірна варта зв'язані священним світлом, через що всі четверо ділять здоров'я, перебуваючи поряд одне з одним. Присутність капітана Дейлкрая збільшує здоров'я його вірної варти поблизу на $462855s1%." },
    { en = "Captain Dailcry unleashes an intimidating $@spellname424419 inflicting $s1 Physical damage to all players. Ignores armor.\n\n\n\nCaptain Dailcry's $@spellname424419 inspires his allies, granting each of them $s3 energy and increasing their damage done by $s2% for $d.\n\n\n\nThis effect stacks.", ua = "Капітан Дейлкрай вивільняє грізний $@spellname424419, завдаючи $s1 фізичної шкоди всім гравцям. Ігнорує броню.\n\n\n\n$@spellname424419 капітана Дейлкрая надихає його союзників, надаючи кожному з них $s3 енергії та збільшуючи завдану ними шкоду на $s2% протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Elaena Emberlanz calls down $@spellname448515 on her current target, inflicting $s1 Holy damage and increasing their damage taken by $s2% for $d.", ua = "Елейна Емберланц прикликає $@spellname448515 на свою поточну ціль, завдаючи $s1 шкоди Світлом і збільшуючи отримувану нею шкоду на $s2% на $d." },
    { en = "Taener Duelmal launches a fireball at a target player, inflicting $s1 Fire damage.", ua = "Таенер Дуелмал запускає вогняну кулю в цільового гравця, завдаючи $s1 вогняної шкоди." },
    { en = "Sergeant Shaynemail leaps at a nearby target, inflicting $s1 Physical damage to players within $a1 yards of the target and causing victims to bleed for an additional $s2 Physical damage every $t2 sec for $d.", ua = "Сержант Шейнмейл стрибає на найближчу ціль, завдаючи $s1 фізичної шкоди гравцям у межах $a1 ярдів від цілі та змушуючи жертв стікати кров'ю, що завдає додатково $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Sergeant Shaynemail smashes the ground with powerful force, inflicting $s1 Physical damage and stunning players with $a1 yards for $d.", ua = "Сержант Шейнмейл б'є по землі могутньою силою, завдаючи $s1 фізичної шкоди й оглушуючи гравців у радіусі $a1 ярдів на $d." },
    { en = "Taener Duelmal calls down burning embers that inflict $s1 Fire damage to players within $a1 yards of the impact locations.", ua = "Тейнер Дуелмал закликає палаючі жарини, що завдають $s1 вогняної шкоди гравцям у межах $a1 м від місць влучання." },
    { en = "Captain Dailcry commands Ember to maul a player, immobilizing them and inflicting $s2 Physical damage every $t2 sec.\n\n\n\nCaptain Dailcry protects Ember while she mauls her target, absorbing the next $447443s1 damage. Breaking Dailcry's protection interrupts the effect.", ua = "Капітан Дейлкрай наказує Жариночці шматувати гравця, знерухомлюючи його та завдаючи $s2 фізичної шкоди кожні $t2 с.\n\n\n\nКапітан Дейлкрай захищає Жариночку, доки вона шматує ціль, поглинаючи наступні $447443s1 шкоди. Якщо подолати захист Дейлкрая, ефект переривається." },
    { en = "Elaena Emberlanz channels the wrath of the light, inflicting $s1 Holy damage to all players every $424431t1 sec for $424431d.", ua = "Елейна Емберланц спрямовує гнів Світла, завдаючи $s1 священної шкоди всім гравцям кожні $424431t1 с протягом $424431d." },
    { en = "Captain Dailcry's loyal defenders inflict $s1% increased damage for each nearby member of the Trusted Guard.", ua = "Віддані захисники Капітана Дейлкрая завдають на $s1% більше шкоди за кожного члена Довіреної варти поблизу." },
    { en = "Captain Dailcry hurls his spear with destructive force that inflicts $s3 Physical damage to players in the area and shatters the ground, inflicting $s1 Sonic damage to all players. The shattered ground inflicts $1238782s1 Sonic damage every $1238782t1 sec to players in the area.", ua = "Капітан Дейлкрай метає свій спис із нищівною силою, що завдає $s3 фізичної шкоди гравцям у зоні та розколює землю, завдаючи $s1 звукової шкоди всім гравцям. Розколена земля завдає $1238782s1 звукової шкоди кожні $1238782t1 сек гравцям у зоні." },
    { en = "Captain Dailcry slashes at his current target, inflicting $s1 Physical damage and causing the target to bleed for $s2 Physical damge every $t2 sec for $d. \n\n\n\nThis effect stacks.", ua = "Капітан Дейлкрай шматує свою поточну ціль, завдаючи $s1 фізичної шкоди та змушуючи ціль стікати кров'ю, що завдає $s2 фізичної шкоди кожні $t2 с протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Braunpyke creates a burning pyre containing $s1 charges that last for $446379d. Each time a player comes into contact with the pyre, a charge is consumed, the player is affected by $@spellname446403 and causing the pyre to erupt in holy energy, inflicting $1218149s1 damage to all players.\n\n\n\nWhile empowered by $@spellname422969, $@spellname446368 has $s2 charges.", ua = "Браунпайк створює палаюче вогнище, що містить $s1 зарядів і триває $446379d. Щоразу, коли гравець торкається вогнища, витрачається один заряд, на гравця накладається $@spellname446403, а вогнище вибухає святою енергією, завдаючи $1218149s1 шкоди всім гравцям.\n\n\n\nПід дією підсилення $@spellname422969 закляття $@spellname446368 має $s2 зарядів." },
    { en = "A searing flame that inflicts $s1 Holy damage every $t1 sec for $d. This effect stacks.", ua = "Пекуче полум'я, що завдає $s1 шкоди Світлом кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Braunpyke hurls a holy shield at several players, inflicting $s1 Holy damage and reducing movement speed by $s2% for $d upon impact. \n\n\n\nWhile empowered by $@spellname422969, $@spellname446649 hits $s3 players.", ua = "Браунпайк жбурляє священний щит у кількох гравців, завдаючи $s1 священної шкоди й знижуючи швидкість пересування на $s2% протягом $d при влучанні.\n\n\n\nПід підсиленням від $@spellname422969 закляття $@spellname446649 влучає в $s3 гравців." },
    { en = "Holy energy erupts from the impact locations of $@spellname446649, inflicting $s1 Holy damage to players within $A1 yards.", ua = "Священна енергія вивергається з місць влучань $@spellname446649, завдаючи $s1 священної шкоди гравцям у радіусі $A1 ярдів." },
    { en = "Braunpyke unleashes a burst of holy light, inflicting $s1 Holy damage to all players and an additional $s1 Holy damage every $t2 sec for $d. The burst of light also heals Braunpyke for $s3% of his maximum health. \n\n\n\nWhile empowered by $@spellname422969, the cast time of $@spellname423051 is reduced.", ua = "Браунпайк вивільняє спалах священного світла, завдаючи $s1 шкоди Світлом усім гравцям і додаткові $s1 шкоди Світлом кожні $t2 с протягом $d. Спалах світла також зцілює Браунпайка на $s3% його максимального здоров'я. \n\n\n\nПід час посилення від $@spellname422969 час прочитання $@spellname423051 скорочується." },
    { en = "Braunpyke calls searing light down on a player's location, inflicting $s1 Holy damage to players within $a1 yards. Hammers then spiral outwards from the impact location, inflicting $s1 Holy damage to players in their path. \n\n\n\nWhile empowered by $@spellname422969, $@spellname423076 hits $s7 players.", ua = "Браунпайк закликає палюче світло на місце розташування гравця, завдаючи $s1 священної шкоди гравцям у радіусі $a1 ярдів. Потім молоти розлітаються по спіралі від місця удару, завдаючи $s1 священної шкоди гравцям на своєму шляху. \n\n\n\nПід час підсилення від $@spellname422969 $@spellname423076 вражає $s7 гравців." },
    { en = "Braunpyke empowers himself with the light, increasing his Physical damage by $s1% and empowering each of his abilities.", ua = "Браунпайк наснажується світлом, збільшуючи свою фізичну шкоду на $s1% і посилюючи кожну зі своїх здібностей." },
    { en = "Upon reaching 50% health, Murrpray protects herself with a shield of light that absorbs the next $s1 damage and providing immunity to interrupt effects.", ua = "Досягнувши 50% здоров'я, Мурпрей захищає себе щитом світла, що поглинає наступні $s1 шкоди й надає несприйнятливість до ефектів переривання." },
    { en = "Murrpray calls down a ray of searing fire from the Sacred Flame that inflicts $425556s1 Holy damage every $t1 sec to players caught in its path, and leaves behind a pool of Sanctified Ground.", ua = "Меррпрей закликає промінь пекучого вогню зі Священного Полум'я, що завдає $425556s1 шкоди від Світла кожні $t1 с гравцям на його шляху і лишає по собі калюжу Освяченої Землі." },
    { en = "Murrpray unleashes a dazzling light that inflicts $s1 Holy damage to all players. Players looking in Murrpray's direction suffer an additional $428170s2 Holy damage and are disoriented by the $@spellname428169 for $428170d.", ua = "Мурпрей вивільняє сліпуче світло, що завдає $s1 священної шкоди всім гравцям. Гравці, що дивляться в бік Мурпрей, зазнають додатково $428170s2 священної шкоди й дезорієнтовані $@spellname428169 протягом $428170d." },
    { en = "Murrpray smites her current target, inflicting $s1 Holy damage.", ua = "Мурпрей карає свою поточну ціль, завдаючи $s1 священної шкоди." },
    { en = "Murrpray channels the power of the Sacred Flame, inflicting $s1 Holy damage to all players every $423664t1 sec. This effect grows in intensity over time.", ua = "Мурпрей спрямовує силу Священного Полум'я, завдаючи $s1 священної шкоди всім гравцям кожні $423664t1 сек. Цей ефект із часом наростає в інтенсивності." },
    { en = "The Sacred Flame empowers Murrpray, increasing her Holy damage by $444608s1% for $d. While empowered, Murrpray radiates $423547s1 Holy damage to all players every $444608t2 sec.", ua = "Священне Полум'я підсилює Мурпрей, збільшуючи її священну шкоду на $444608s1% протягом $d. Поки вона підсилена, Мурпрей випромінює $423547s1 священної шкоди всім гравцям кожні $444608t2 с." },
    { en = "The fires left by the Sacred Flame inflict $s1 Holy damage every $t1 sec to players caught within them.", ua = "Вогні, залишені Священним Полум'ям, завдають $s1 священної шкоди кожні $t1 с гравцям, які в них потрапили." },
    { en = "Murrpray calls down a ray of light at a player's location, inflicting $s1 Holy damage and an additional $s2 Holy damage every $t2 sec to any players within $a1 yards of the impact location.", ua = "Мурпрей закликає промінь світла на місце гравця, завдаючи $s1 священної шкоди й додатково $s2 священної шкоди кожні $t2 с усім гравцям у межах $a1 м від місця влучання." },
    { en = "$?DIFF1[Empowered by the Sacred Flame, increasing damage done by $s1%.\n\n\n\nThe overwhelming power of the Sacred Flame drains $425017s1% health every $425017t1 sec.][]$?DIFF2[Empowered by the Sacred Flame, increasing damage done by $s1% and inflicting $425018s1 Holy damage to players within $425018a1 yards every $t2 sec.\n\n\n\nThe overwhelming power of the Sacred Flame drains $425017s1% health every $425017t1 sec.][]$?DIFF8$?DIFF23[Empowered by the Sacred Flame, increasing damage done by $s1% and inflicting $425018s1 Holy damage to players within $425018a1 yards every $t2 sec.\n\n\n\nThe overwhelming power of the Sacred Flame drains $425017s1% health every $425017t1 sec.][]", ua = "$?DIFF1[Підсилений Священним Полум'ям, що збільшує завдану шкоду на $s1%.\n\n\n\nНездоланна сила Священного Полум'я висмоктує $425017s1% здоров'я кожні $425017t1 с.][]$?DIFF2[Підсилений Священним Полум'ям, що збільшує завдану шкоду на $s1% і завдає $425018s1 священної шкоди гравцям у межах $425018a1 м кожні $t2 с.\n\n\n\nНездоланна сила Священного Полум'я висмоктує $425017s1% здоров'я кожні $425017t1 с.][]$?DIFF8$?DIFF23[Підсилений Священним Полум'ям, що збільшує завдану шкоду на $s1% і завдає $425018s1 священної шкоди гравцям у межах $425018a1 м кожні $t2 с.\n\n\n\nНездоланна сила Священного Полум'я висмоктує $425017s1% здоров'я кожні $425017t1 с.][]" },
    { en = "While flying during this encounter infused orbs of Light radiate. Collecting these grants a Skyriding Charge and extends the duration of $@spellname449042.", ua = "Під час польоту в цьому бою сяють наповнені кулі Світла. Збір їх дає заряд Небесної їзди та подовжує тривалість $@spellname449042." },
    { en = "Shadowcrown shears the link between a player's body and soul inflicting $426735s1 Shadow damage every $426735T1 sec and reducing movement speed by $426735s2% $?diff23[forever][for $426735D].\n\n\n\nUpon removal applies $@spellname426736 to $426736I players.", ua = "Тінокорона розриває зв'язок між тілом і душею гравця, завдаючи $426735s1 тіньової шкоди кожні $426735T1 сек і знижуючи швидкість пересування на $426735s2% $?diff23[назавжди][протягом $426735D].\n\n\n\nПісля зняття накладає $@spellname426736 на $426736I гравців." },
    { en = "Speaker Shadowgrown ejects dark energy at a target, inflicting $425489s1 Shadow damage and $425489s2 Shadow damage to all other targets.", ua = "Речниця Тінокорона викидає темну енергію в ціль, завдаючи $425489s1 тіньової шкоди їй і $425489s2 тіньової шкоди всім іншим цілям." },
    { en = "A dark shroud clings to players absorbing the next $s1 healing$?diff23[ and inflicts $426736s2 Shadow damage every $426736T2 sec][].", ua = "Темний саван чіпляється до гравців, поглинаючи наступні $s1 зцілення$?diff23[ й завдаючи $426736s2 тіньової шкоди кожні $426736T2 сек][]." },
    { en = "Shadowcrown unleashes a massive explosion of shadow magic in an attempt to destroy any players aboard the Dawnbreaker. While casting Shadowcrown is immune to damage.", ua = "Тінокорона вивільняє потужний вибух тіньової магії, намагаючись знищити всіх гравців на борту Світанкоборця. Під час чарування Тінокорона несприйнятлива до шкоди." },
    { en = "Radiant light bathes the player, protecting them from $@spellname449332. Enables skyriding, steady flight, and mounting in combat.\n\n\n\nUpon exiting the Lamplighter's influence Radiant Light no longer lasts forever and when $449332D or less remains, players gain $@spellname449332.", ua = "Промениста світло огортає гравця, захищаючи його від $@spellname449332. Дозволяє небесну їзду, рівний політ і сідання на їздову тварину в бою.\n\n\n\nПісля виходу з-під впливу Ліхтарника Промениста світло більше не триває вічно, і коли лишається $449332D чи менше, гравці зазнають $@spellname449332." },
    { en = "The Order of Night's ritual on Beledar inflicts $449335s1 Shadow damage to those unprotected by $@spellname449042, killing instantly upon expiration.", ua = "Ритуал Ордену Ночі на Беледарі завдає $449335s1 тіньової шкоди тим, кого не захищає $@spellname449042, миттєво вбиваючи після завершення дії." },
    { en = "Shadowcrown rips open portals at targeted locations for $453153D, inflicting $453173s1 Shadow damage every $453173T1 sec to those inside. These zones increase in size over time.", ua = "Тінокорона роздирає портали в обраних місцях на $453153D, завдаючи $453173s1 тіньової шкоди кожні $453173T1 с тим, хто всередині. Ці зони з часом збільшуються." },
    { en = "Shadowcrown hurls shadow magic at a player, inflicting $s1 Shadow damage.", ua = "Тінокорона жбурляє тіньову магію в гравця, завдаючи $s1 тіньової шкоди." },
    { en = "Shadowcrown rips open portals at targeted locations, inflicting $426715s1 Shadow damage to targets within $426714A1 yards, $426719A1 yards, $426720A1 yards, and $426723A1 yards sequentially.", ua = "Тінокорона розриває портали в позначених місцях, завдаючи $426715s1 тіньової шкоди цілям у радіусі $426714A1 м, $426719A1 м, $426720A1 м та $426723A1 м послідовно." },
    { en = "Shadowcrown ejects dark energy at her current target inflicting $453310s1 Shadow damage and an additional $453310s2 Shadow damage to all other players.\n\n\n\nFor $453212D shadow magic radiates in targeted directions, inflicting $453214s1 Shadow damage and an additional $453214s2 Shadow damage every $453214T2 sec for $453214D upon contact. This effect stacks.", ua = "Тінокорона викидає темну енергію у свою поточну ціль, завдаючи $453310s1 тіньової шкоди їй і додаткові $453310s2 тіньової шкоди всім іншим гравцям.\n\n\n\nПротягом $453212D тіньова магія випромінюється в обрані напрямки, завдаючи $453214s1 тіньової шкоди й додаткові $453214s2 тіньової шкоди кожні $453214T2 с протягом $453214D при дотику. Цей ефект накопичується." },
    { en = "Anub'ikkaj pours forth dark magic inflicting $426793s1 Shadow damage every $426787T1 sec for $426787D$?diff23[, increasing in damage by $426787s2% each period. This effect stacks.][]", ua = "Ануб'іккай вивергає темну магію, завдаючи $426793s1 тіньової шкоди кожні $426787T1 сек протягом $426787D$?diff23[, при цьому шкода зростає на $426787s2% з кожним разом. Цей ефект накопичується.][]" },
    { en = "The Animated Shadow flings shadowy sludge at a target inflicting $s1 Shadow damage.", ua = "Оживлена тінь жбурляє тіньову твань у ціль, завдаючи $s1 тіньової шкоди." },
    { en = "Anub'ikkaj conjures a sphere of pure darkness which travels until it impacts an object exploding for $426826s1 Shadow damage to all players. This damage is decreased the farther the orb travels.\n\n\n\nUpon contact this darkness applies $@spellname427378.", ua = "Ануб'іккай прикликає сферу чистої пітьми, що рухається, доки не влучить в об'єкт, вибухаючи й завдаючи $426826s1 тіньової шкоди всім гравцям. Ця шкода зменшується, що далі летить сфера.\n\n\n\nПри контакті ця пітьма накладає $@spellname427378." },
    { en = "Inflicts $s1 Shadow damage every $T1 sec for $D. This effect stacks.", ua = "Завдає $s1 тіньової шкоди кожні $T1 с протягом $D. Цей ефект накопичується." },
    { en = "Anub'ikkaj's lieutenants share formidable power with him increasing their damage by $s1% and maximum health by $s2%. This effect stacks.\n\n\n\nDefeating them removes this power.", ua = "Лейтенанти Ануб'іккая ділять із ним грізну силу, підвищуючи свою шкоду на $s1% і максимальне здоров'я на $s2%. Цей ефект накопичується.\n\n\n\nЇхня поразка знімає цю силу." },
    { en = "Anub'ikkaj blasts his current target for $427002s2 Physical damage and $427007s1 Shadow damage, knocking them back. Additionally inflicts $427007s1 Shadow damage to other targets within $427007A1 yards and fears them for $427007D.", ua = "Ануб'іккай вражає свою поточну ціль на $427002s2 фізичної шкоди та $427007s1 тіньової шкоди, відкидаючи її назад. Додатково завдає $427007s1 тіньової шкоди іншим цілям у межах $427007A1 ярдів і наганяє на них жах на $427007D." },
    { en = "Anub'ikkaj reaches into the darkness and summons living shadows to his aid.", ua = "Ануб'іккай сягає в темряву і призиває собі на допомогу живі тіні." },
    { en = "Hurl an Arathi Bomb at Rasha'nan inflicting ${$434726s2/10}.1% of her total health in damage.\n\n\n\nUsable within $438946A1 yards of Rasha'nan.", ua = "Жбурляє аратійську бомбу в Раша'нана, завдаючи шкоди в розмірі ${$434726s2/10}.1% його загального здоров'я.\n\n\n\nМожна застосувати в радіусі $438946A1 ярдів від Раша'нана." },
    { en = "$@spellname448888 jettisons globs of acid at players inflicting $463428s1 Nature damage every $463428T1 sec for $463428D. This effect stacks.", ua = "$@spellname448888 жбурляє згустки кислоти в гравців, завдаючи $463428s1 шкоди від сил природи кожні $463428T1 с протягом $463428D. Цей ефект накопичується." },
    { en = "Upon reaching the Veneration Grounds Rasha'nan thrashes in rage inflicting $s1 Nature damage to all players until interrupted. This effect increases in intensity over time. \n\n\n\nRasha'nan is immune to damage while the effect lasts.", ua = "Досягнувши Землі Поклоніння, Раша'нан несамовито шаленіє, завдаючи $s1 шкоди Природою всім гравцям, доки її не перервуть. Цей ефект із часом посилюється. \n\n\n\nПоки триває ефект, Раша'нан несприйнятлива до шкоди." },
    { en = "Rasha'nan expels a poisonous concoction at marked targets which sloshes off in waves in the indicated direction from the target. \n\n\n\nPlayers splashed by the initial corrosive eruption are caught in an $@spellname434576.\n\n\n\nAny player that touches a wave has their movement speed reduced by $434441s2% and gains $@spellname434579 every $434441T1 sec.\n\n\n\nThe waves incinerate $@spellname434096 inflicting $438956s1 Nature damage to players within $457467A1 yards and creates $@spellname438957.", ua = "Раша'нан вивергає отруйне вариво на позначені цілі, і воно розтікається хвилями у вказаному від цілі напрямку. \n\n\n\nГравці, забризкані первинним їдким виверженням, потрапляють під дію $@spellname434576.\n\n\n\nУ будь-якого гравця, який торкається хвилі, швидкість пересування знижується на $434441s2%, і він отримує $@spellname434579 щороку $434441T1 сек.\n\n\n\nХвилі спалюють $@spellname434096, завдаючи $438956s1 шкоди від сил природи гравцям у радіусі $457467A1 м і створюючи $@spellname438957." },
    { en = "$@spellname434089' snap inflicting $434119s1 Shadow damage to all players.", ua = "Розрив $@spellname434089 завдає $434119s1 тіньової шкоди всім гравцям." },
    { en = "Rasha'nan blasts webs at targeted players inflicting $434093s1 Shadow damage to players within $434093A1 yards, tethering the original target and creating $@spellname434096.\n\n\n\nThis tether inflicts $434113s1 Shadow damage every $434113T1 sec, pulling in the original target. Moving $434113A2 yards snaps this tether, causing a $@spellname434119.", ua = "Раша'нан вистрілює павутиною в позначених гравців, завдаючи $434093s1 тіньової шкоди гравцям у межах $434093A1 ярдів, прив'язуючи початкову ціль і створюючи $@spellname434096.\n\n\n\nЦя прив'язь завдає $434113s1 тіньової шкоди кожні $434113T1 с, притягуючи початкову ціль. Якщо віддалитися на $434113A2 ярдів, прив'язь розривається, спричиняючи $@spellname434119." },
    { en = "Carrying an Arathi Bomb. The bomb continuously sparks inflicting $434668s2 Fire damage every $434668T2 sec while held.", ua = "Несе аратійську бомбу. Поки її тримають, бомба безперервно іскрить, завдаючи $434668s2 вогняної шкоди кожні $434668T2 с." },
    { en = "Rolling Acid can form caustic zones for $438956D. Contact with this zone inflicts $438957s1 Nature damage every $438957T1 sec.", ua = "«Розкотистий кислотний вал» здатний утворювати їдкі зони протягом $438956D. Контакт із такою зоною завдає $438957s1 шкоди від сил природи щороку $438957T1 сек." },
    { en = "The propulsive expulsion of $@spellname439789 inflicts $s1 Nature damage and stuns for $434576D.", ua = "Реактивне виверження $@spellname439789 завдає $s1 шкоди від сил природи та оглушує на $434576D." },
    { en = "$@spellname439784' silken adhesive coats the arena inflicting $434096s1 Nature damage every $434096T1 sec and reducing movement speed by $434096s2%.", ua = "Шовкова клейка речовина $@spellname439784 вкриває арену, завдаючи $434096s1 шкоди від сил природи кожні $434096T1 с і знижуючи швидкість пересування на $434096s2%." },
    { en = "Vile acid corrodes the target for $434579D, suffering $434579s1 Nature damage every $434579T1 sec. This effect stacks.", ua = "Мерзенна кислота роз'їдає ціль протягом $434579D, завдаючи $434579s1 шкоди природою кожні $434579T1 с. Цей ефект накопичується." },
    { en = "Rasha'nan ejects tacky strands in targeted directions inflicting $448215s1 Nature damage to players within $448215A1 yards of impact locations and rooting them in place for $448215D.", ua = "Раша'нан викидає липкі нитки в позначених напрямках, завдаючи $448215s1 шкоди від сил природи гравцям у радіусі $448215A1 м від місць влучання й знерухомлюючи їх на $448215D." },
    { en = "Rasha'nan violently expels webs while no players are in melee range, inflicting $s1 Nature damage plus an additional $s2 Nature damage every $T2 sec for $D. This effect stacks.", ua = "Раша'нан бурхливо вивергає павутину, поки в зоні ближнього бою немає гравців, завдаючи $s1 шкоди від сил природи та додаткові $s2 шкоди від сил природи кожні $T2 с протягом $D. Цей ефект накопичується." },
    { en = "Rasha'nan spews acid for $448888D inflicting $448888s2 Nature damage at all players plus an additional $448887s1 every $448888T1 sec.", ua = "Раша'нан вивергає кислоту протягом $448888D, завдаючи $448888s2 шкоди від сил природи всім гравцям, а також додаткову $448887s1 кожні $448888T1 с." },
    { en = "Nightfall Bombers toss high explosives on the deck of the Dawnbreaker which detonate after $434653D inflicting $s1 Fire damage to all players and an additional $s2 Fire damage every $T2 sec for $D. This effect stacks.\n\n\n\nArathi Bombs can be carried by players.\n\n\n\nArathi Bombs thrown at Rasha'nan detonate inflicting ${$434726s2/10}.1% of her total health in damage.", ua = "Нічні бомбардувальники жбурляють потужну вибухівку на палубу Світанкокрила, яка детонує за $434653D, завдаючи $s1 вогняної шкоди всім гравцям і додатково $s2 вогняної шкоди кожні $T2 с протягом $D. Цей ефект накопичується.\n\n\n\nАратійські бомби можуть переносити гравці.\n\n\n\nАратійські бомби, кинуті в Раша'нан, детонують, завдаючи шкоди в розмірі ${$434726s2/10}.1% її загального здоров'я." },
    { en = "Unleashes wild lightning toward players, inflicts $s1 Nature damage to players within $a1 yards of the impact location.", ua = "Вивільняє дику блискавку в гравців, завдаючи $s1 шкоди від сил природи гравцям у межах $a1 ярдів від місця удару." },
    { en = "Kyrioss suffuses a random player with electricity. Upon removal, the target unleashes an eruption of electrical energy, inflicting $s1 Nature damage to all players. The eruption can be discharged safely in the central tempest.", ua = "Кіріосс наповнює випадкового гравця електрикою. Після зняття ефекту ціль вивільняє виверження електричної енергії, завдаючи $s1 шкоди від сил природи всім гравцям. Виверження можна безпечно розрядити в центральній бурі." },
    { en = "Kyrioss creates a raging storm that periodically unleashes a crash of lightning that strikes a player's location inflicting $444411s1 Nature damage to players within $444411A1 yards of the impact.", ua = "Кіріос створює лютий шторм, що періодично вивільняє удар блискавки, який б'є в розташування гравця, завдаючи $444411s1 шкоди Природою гравцям у радіусі $444411A1 ярдів від місця влучання." },
    { en = "Strikes target locations with a grounding bolt, inflicting $s1 Nature damage to all enemies within $a1 yards.", ua = "Б'є по цільових місцях заземлювальною блискавкою, завдаючи $s1 шкоди від сил природи всім ворогам у межах $a1 м." },
    { en = "Kyrioss launches lightning that arcs to up to $s2 players, inflicting $s1 Nature damage.", ua = "Кіріосс випускає блискавку, що перестрибує щонайбільше на $s2 гравців, завдаючи $s1 шкоди від сил природи." },
    { en = "Summons a tempest that crashes down on players, inflicting $s1 to all enemies within $a1 yards of impact.", ua = "Прикликає бурю, що обрушується на гравців, завдаючи $s1 усім ворогам у межах $a1 м від влучання." },
    { en = "Upon reaching 100 energy, Kyrioss flies to the center of the room and overcharges itself with lightning energy, inflicting $1214323s1 Nature damage $?diff1|diff2[]$?diff8|diff23[and striking them with $@spellname1214320] every $1214315t1 sec for $1214315d. Also unleashes 4 torrents of lightning. Touching these torrents inflicts $s1 Nature damage and stuns the target for $d.", ua = "Досягнувши 100 енергії, Кіріосс злітає до центру кімнати й перевантажує себе енергією блискавки, завдаючи $1214323s1 шкоди від сил природи $?diff1|diff2[]$?diff8|diff23[й уражаючи їх закляттям $@spellname1214320] кожні $1214315t1 сек упродовж $1214315d. Також вивільняє 4 потоки блискавок. Дотик до цих потоків завдає $s1 шкоди від сил природи й приголомшує ціль на $d." },
    { en = "Kyiross leaps to a location and unleashes a charged blast, inflicting $s1 Nature damage to players within $A1 yards, knocking them away.", ua = "Кайросс стрибає на позицію і вивільняє заряджений вибух, завдаючи $s1 одиниць шкоди силами природи гравцям у межах $A1 ярдів і відкидаючи їх." },
    { en = "Stormguard Gorren imbues a player with $s2 charges of void, inflicting $s1  Shadow damage every $t1 sec for $d1.\n\n\n\nUpon removal, a charge of void is expended and a transference of those energies to the nearest player.", ua = "Штормовий вартовий Ґоррен наповнює гравця $s2 зарядами Порожнечі, завдаючи $s1 тіньової шкоди щохвилини $t1 сек упродовж $d1.\n\n\n\nПісля зняття один заряд Порожнечі витрачається, і ця енергія передається найближчому гравцю." },
    { en = "The impact leaves a zone of shadowy energy that lasts for $424961d1. Players in the zone suffer $s1 Shadow damage every $t1 sec.", ua = "Удар лишає зону тіньової енергії, що триває $424961d1. Гравці в зоні зазнають $s1 тіньової шкоди кожні $t1 с." },
    { en = "Tears in the fabric of reality emanate from the point of impact inflicting $s1 Shadow damage to any players caught in their path.", ua = "Розриви в тканині реальності розходяться від місця удару, завдаючи $s1 тіньової шкоди будь-яким гравцям на їхньому шляху." },
    { en = "Stormguard Gorren channels umbral energies, pulling players towards him and inflicting $426160s1 Shadow damage every $426160t1 sec for $425048d.\n\n\n\nUpon completion Gorren's hammer explodes with energy at players within $a1 yards, inflicting $s1 Shadow damage and knocking players away.", ua = "Штормовий вартовий Ґоррен черпає тіньову енергію, притягуючи гравців до себе й завдаючи $426160s1 тіньової шкоди кожні $426160t1 с протягом $425048d.\n\n\n\nПо завершенні молот Ґоррена вибухає енергією по гравцях у радіусі $a1 ярдів, завдаючи $s1 тіньової шкоди й відкидаючи гравців." },
    { en = "Inflicts $s1 Shadow damage to players within $a1 yards of the impact.", ua = "Завдає $s1 тіньової шкоди гравцям у радіусі $a1 м від влучання." },
    { en = "Increases damage taken from $@spellname424739 by $s1% for $d1. This effect stacks.", ua = "Збільшує шкоду від $@spellname424739 на $s1% на $d1. Цей ефект накопичується." },
    { en = "Stormguard Gorren charges his hammer with void and leaps towards the player's location, inflicting $s1 Shadow damage to all players.\n\n\n\nThe impact rends the fabric of reality creating $@spellname426136s and leaving behind a zone of $@spellname424966.", ua = "Штормовий вартовий Ґоррен заряджає свій молот Порожнечею і стрибає до позиції гравця, завдаючи $s1 тіньової шкоди всім гравцям.\n\n\n\nУдар розриває тканину реальності, створюючи $@spellname426136s і лишаючи по собі зону $@spellname424966." },
    { en = "The Voidstone Monstrosity smashes its fists into the platform inflicting $s1 Shadow damage to all players while no players are in melee range.", ua = "Чудовисько з Каменю Порожнечі гатить кулаками по платформі, завдаючи $s1 тіньової шкоди всім гравцям, поки жоден гравець не перебуває в зоні ближнього бою." },
    { en = "The Voidstone Awakened is overloaded with corruption inflicting $s1 Shadow damage to all players every $429028t1 sec and increasing all damage done by $s2%. This effect stacks.", ua = "Пробуджений Каменю Порожнечі переповнений зіпсуттям, завдаючи $s1 тіньової шкоди всім гравцям кожні $429028t1 с і збільшуючи всю завдавану шкоду на $s2%. Цей ефект накопичується." },
    { en = "Stormrider Vokmar energizes marked players increasing their movement speed by $s1% for $d. Vokmar then hurls his lightning hammer to detonate any Voidstone Fragments within $458088A2 yards of each player marked with $@spellname458082.", ua = "Штормовий вершник Вокмар наповнює енергією позначених гравців, збільшуючи їхню швидкість пересування на $s1% протягом $d. Потім Вокмар жбурляє свій блискавичний молот, щоб підірвати всі Уламки Каменю Порожнечі в межах $458088A2 м від кожного гравця, позначеного ефектом $@spellname458082." },
    { en = "The Voidstone Monstrosity smashes the platform inflicting $428126s2 Shadow damage and releasing cascading explosions that inflict $s1 Shadow damage to players within $a1 yards of each impact.\n\n\n\nAdditionally this ejects Voidstone Fragments around the arena.", ua = "Чудовисько з Каменю Порожнечі трощить платформу, завдаючи $428126s2 тіньової шкоди й вивільняючи каскадні вибухи, що завдають $s1 тіньової шкоди гравцям у межах $a1 м від кожного влучання.\n\n\n\nКрім того, це розкидає по арені Уламки Каменю Порожнечі." },
    { en = "Unstable Corruption creates a pool of $@spellname433067 upon removal which inflicts $s1 Shadow damage every $t1 sec to players in the area.", ua = "Нестійке Спотворення створює після зняття калюжу $@spellname433067, яка завдає $s1 тіньової шкоди кожні $t1 с гравцям у цій ділянці." },
    { en = "Voidstone Fragments reshape into Skardyn over $s1 sec, crystallizing into a Voidstone Awakened.", ua = "Уламки Каменю Порожнечі за $s1 с перетворюються на скардинів, кристалізуючись у Пробудженого Каменем Порожнечі." },
    { en = "The Voidstone Monstrosity encases itself in a shell of void energy absorbing $s2% of its max health as damage and protecting itself from $@spellname424371.", ua = "Чудовисько Каменю Порожнечі огортає себе оболонкою з енергії Порожнечі, що поглинає шкоду в розмірі $s2% його максимального здоров'я та захищає його від $@spellname424371." },
    { en = "The Voidstone Monstrosity unleashes $@spellname429493 upon $s2 nearby players inflicting $s3 Shadow damage and an additional $s1 Shadow damage every $t1 sec for $d.\n\n$?DIFF8$?DIFF23[Creates a pool of $@spellname458017 upon removal which inflicts $433067s1 Shadow damage every $433067t1 sec to players in the area.][]", ua = "Чудовисько з Каменю Порожнечі вивільняє $@spellname429493 на $s2 найближчих гравців, завдаючи $s3 тіньової шкоди й додатково $s1 тіньової шкоди кожні $t1 с протягом $d.\n\n$?DIFF8$?DIFF23[Після зняття створює калюжу $@spellname458017, яка завдає $433067s1 тіньової шкоди кожні $433067t1 с гравцям у цій ділянці.][]" },
    { en = "The Voidstone Monstrosity unleashes a wave of condensed void energy at its current target, inflicting $s1 Shadow damage to players in its path.", ua = "Чудовисько з Каменю Порожнечі вивільняє хвилю згущеної енергії Порожнечі в свою поточну ціль, завдаючи $s1 тіньової шкоди гравцям на її шляху." },
    { en = "Upon penetrating its Void Shell, Stormrider Vokmar launches his stormhammer at the Voidstone Monstrosity stunning it and increasing its damage taken by $423839s2% for $423839d.", ua = "Пробивши Оболонку Порожнечі, штормовий вершник Вокмар жбурляє свій штормовий молот у Чудовисько з Каменю Порожнечі, оглушуючи його та підвищуючи отримувану ним шкоду на $423839s2% протягом $423839d." },
    { en = "E.D.N.A. unleashes a beam of fiery energy at up to $s4 players, inflicting $s2 Fire damage to players caught in the effect.\n\n\n\nVolatile Spikes hit with this effect are destroyed.", ua = "Е.Д.Н.А. вивільняє промінь вогняної енергії по щонайбільше $s4 гравцях, завдаючи $s2 вогняної шкоди гравцям, яких зачепило ефектом.\n\n\n\nНестабільні Шипи, влучені цим ефектом, знищуються." },
    { en = "E.D.N.A. creates volatile spikes that erupt from the earth. Any players who come into contact with a spike causes it to erupt, knocking the player back and inflicting $s1 Fire damage to all players within $A1 yards and inflicting $s3 Fire damage every $t3 sec to all players.", ua = "Е.Д.Н.А. створює нестійкі шипи, що виростають із землі. Будь-який гравець, що торкається шипа, спричиняє його вибух, відкидаючи гравця назад і завдаючи $s1 вогняної шкоди всім гравцям у межах $A1 ярдів, а також $s3 вогняної шкоди кожні $t3 с усім гравцям." },
    { en = "E.D.N.A. slams the ground, inflicting $s1 Nature damage to all players and sending out seismic pulses that destroy all Volatile Spikes.", ua = "Е.Д.Н.А. б'є об землю, завдаючи $s1 шкоди від сил природи всім гравцям і розсилаючи сейсмічні імпульси, що знищують усі нестійкі шипи." },
    { en = "E.D.N.A. punches its current target with incredible force, inflicting $s1 Physical damage and afflicting them with $@spellname424889.", ua = "E.D.N.A. б'є свою поточну ціль із неймовірною силою, завдаючи $s1 фізичної шкоди і вражаючи її ефектом $@spellname424889." },
    { en = "Rippling waves of force surround the target, inflicting $s1 Nature damage every $t1 sec for $d. \n\n\n\nUpon being dispelled, a $@spellname424893 suffuses the target.", ua = "Брижисті хвилі сили оточують ціль, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. \n\n\n\nПісля розвіювання ціль сповнює $@spellname424893." },
    { en = "The strength of earth suffuses though the target, reducing their damage taken by $s1% for $d.", ua = "Сила землі сповнює ціль, зменшуючи отриману нею шкоду на $s1% протягом $d." },
    { en = "Brokk sends hot liquid metal surging into players, inflicting $s1 Fire damage and slowing them by $s2% for $d.", ua = "Брокк спрямовує на гравців потік розпеченого рідкого металу, завдаючи $s1 шкоди вогнем і сповільнюючи їх на $s2% протягом $d." },
    { en = "As the cube grinds across the floor, it inflicts $s1 Physical damage to players in its path and stuns them for $d.", ua = "Котячись підлогою, куб завдає $s1 фізичної шкоди гравцям на своєму шляху і оглушує їх на $d." },
    { en = "Dorlita superheats the hammer on her mech suit, then slams it into her target inflicting $s1 Fire damage.", ua = "Дорліта розжарює молот на своєму механічному костюмі, а потім гатить ним по цілі, завдаючи $s1 вогняної шкоди." },
    { en = "Inflicts $s1 Fire damage and an additional $s2 fire damage every $t2 sec for $d.", ua = "Завдає $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d." },
    { en = "Brokk leaps to one end of the arena and calls to the metal surrounding him to coalesce into a massive cube, which he then hurls in a straight line across the arena.", ua = "Брокк стрибає до одного краю арени й закликає метал навколо себе зібратися в гігантський куб, який потім жбурляє прямою лінією через усю арену." },
    { en = "Inflicts $429999s1 Fire damage every $429999t1 sec to players standing in the flames.", ua = "Завдає $429999s1 шкоди вогнем кожні $429999t1 с гравцям, що стоять у полум'ї." },
    { en = "Waves of molten metal surge from where the cube once stood, inflicting $463145s1 Fire damage every $463145t1 sec to players standing within.", ua = "Хвилі розплавленого металу здіймаються з місця, де колись стояв куб, завдаючи $463145s1 шкоди вогнем кожні $463145t1 сек. гравцям, що стоять усередині." },
    { en = "Brokk channels energy into the machinery beneath him to activate its thermal exhaust vents for $428820d inflicting $443954s1 Fire damage to all players every $443954t1 sec to all players, and continually releasing $@spellname429999 into the area.\n\n\n\nWhile active, the vents inflict $s1 Fire damage every $t1 sec to players standing on top of them.", ua = "Брокк скеровує енергію в механізм під собою, щоб активувати його теплові випускні отвори на $428820d, завдаючи $443954s1 вогняної шкоди всім гравцям кожні $443954t1 с і безперервно вивільняючи в зону $@spellname429999.\n\n\n\nПоки отвори активні, вони завдають $s1 вогняної шкоди кожні $t1 с гравцям, що стоять над ними." },
    { en = "Dorlita fires an orb of lava from her mech's cannon toward a random player. The orb inflicts $449169s1 Fire damage and an additional $449169s2 Fire damage every $449169t2 sec to players in its path.", ua = "Дорліта вистрілює кулю лави з гармати свого меха в напрямку випадкового гравця. Куля завдає $449169s1 шкоди вогнем та додатково $449169s2 шкоди вогнем кожні $449169t2 с гравцям на її шляху." },
    { en = "This Speaker fights on with increased zealotry after witnessing one of their own killed, and calls to the lava surrounding them to aid them. The Speaker pulses $457144s1 Fire damage every $t1 sec to all players. Additionally this Speaker has their damage increased by $s2%.", ua = "Цей речник б'ється з посиленим завзяттям, побачивши загибель когось зі своїх, і кличе на допомогу лаву довкола себе. Речник випромінює $457144s1 од. шкоди Вогню кожні $t1 с усім гравцям. Крім того, шкода цього речника збільшується на $s2%." },
    { en = "Dorlita drags the Scrap Cube to the center of the arena and superheats it until it explodes, inflicting $428535s2 Fire damage to all players and applying $@spellname464392 to players within $464392a1 yards.", ua = "Дорліта тягне Куб Брухту до центру арени і перегріває його, доки той не вибухає, завдаючи $428535s2 шкоди вогнем усім гравцям і накладаючи $@spellname464392 на гравців у межах $464392a1 ярдів." },
    { en = "Skarmorak draws power from the rocks within its chamber, refilling its energy and gaining a shield that absorbs ${($423228s1)*6} damage. Each Crystal Shard causes Skarmorak's shield to absorb an additional $423228s1 damage.\n\n\n\nWhile shielded, Skarmorak channels $@spellname423324. Destroying $@spellname423200 stuns Skarmorak for $423246d.", ua = "Скармарак черпає силу з каміння у своїй залі, поповнюючи свою енергію та отримуючи щит, що поглинає ${($423228s1)*6} шкоди. Кожен Кристалічний Уламок дає щиту Скармарака поглинути додаткові $423228s1 шкоди.\n\n\n\nПоки щит активний, Скармарак спрямовує $@spellname423324. Знищення $@spellname423200 оглушує Скармарака на $423246d." },
    { en = "Picking up $@spellname443405  increase healing, and damage done to $@spellname423228  by $438583s1% for $438583d. This effect stacks. \n\n\n\nIn addition, $@spellname435813 also inflicts $464980s1 Shadow damage to affected players every $t1 sec.", ua = "Підбирання $@spellname443405  збільшує зцілення та шкоду, завдану $@spellname423228  на $438583s1% протягом $438583d. Цей ефект накопичується. \n\n\n\nКрім того, $@spellname435813 також завдає $464980s1 шкоди тінню ураженим гравцям кожні $t1 с." },
    { en = "Upon Destruction, Crystal Shards fragment violently, inflicting $s1 Shadow damage to all players.", ua = "Після знищення Кристалічні Уламки бурхливо розколюються, завдаючи $s1 шкоди Тінню всім гравцям." },
    { en = "Crystal Shards return their essence to Skarmorak, increasing the potency of $@spellname423228 by $423228s1.", ua = "Кристалічні скалки повертають свою есенцію Скармараку, посилюючи потужність $@spellname423228 на $423228s1." },
    { en = "Void Fragments inflict $s1 Shadow damage to players within $a1 yards of their impact.", ua = "Фрагменти Порожнечі завдають $s1 тіньової шкоди гравцям у радіусі $a1 ярдів від місця їхнього падіння." },
    { en = "Skarmorak smashes the ground with unstable fury, inflicting $s2 Shadow damage to players within $a2 yards. and ejecting $@spellname423557.", ua = "Скармарак гатить об землю нестабільною люттю, завдаючи $s2 тіньової шкоди гравцям у радіусі $a2 ярдів і викидаючи $@spellname423557." },
    { en = "Skarmorak slams its current target, inflicting $s1 Physical damage. $@spellname422261 shatter loose from the impact of its fist.", ua = "Скармарак вдаряє свою поточну ціль, завдаючи $s1 фізичної шкоди. Від удару його кулака відколюються $@spellname422261." },
    { en = "Skarmorak expels entropic energy, inflicting $423327s1 Shadow damage to all players, and increasing $@spellname423324 damage by $423327s2% every $t1 seconds. This effect stacks. Breaking $@spellname423228 interrupts this ability.", ua = "Скарморак вивергає ентропійну енергію, завдаючи $423327s1 шкоди тінню всім гравцям і збільшуючи шкоду від $@spellname423324 на $423327s2% кожні $t1 с. Цей ефект накопичується. Руйнування $@spellname423228 перериває цю здібність." },
    { en = "Void Speaker Eirich corrupts players with void energies, inflicting $s1 Shadow damage every $t1 sec which increases $427433s1% every $t1 sec until removed. \n\n\n\nMoving within $427315A1 yards of a $@spellname427315 consumes $@spellname427329, removing it.", ua = "Речник Порожнечі Ейріх псує гравців енергіями Порожнечі, завдаючи $s1 тіньової шкоди кожні $t1 сек, яка зростає на $427433s1% кожні $t1 сек, поки її не знято. \n\n\n\nПереміщення в межах $427315A1 ярдів від $@spellname427315 споживає $@spellname427329, знімаючи його." },
    { en = "Void Speaker Eirich unleashes a cacophony of void energies from the target, inflicting $s1 Shadow damage to all players within $A1 yards of the targer and leaving a zone of $@spellname457456.", ua = "Речник Порожнечі Ейріх вивільняє з цілі какофонію енергій Порожнечі, завдаючи $s1 тіньової шкоди всім гравцям у межах $A1 ярдів від цілі й лишаючи зону $@spellname457456." },
    { en = "Void Speaker Eirich opens rifts to the Void, pulling in nearby players, killing anyone within $A2 yards of the center of the rift.", ua = "Речник Порожнечі Ейріх відкриває розломи до Порожнечі, втягуючи ближніх гравців і вбиваючи всіх у межах $A2 ярдів від центру розлому." },
    { en = "A zone of void energy is created at the location that lasts for $d, inflicting $457465s1 Shadow damage every $457465t1 sec to players within the effect.", ua = "На цьому місці створюється зона енергії Порожнечі, що триває $d, завдаючи $457465s1 тіньової шкоди кожні $457465t1 сек гравцям у межах дії ефекту." },
    { en = "Void Speaker Eirich unleashes a cone of umbral unmaking towards a player's location, inflicting $s2 Shadow damage to players in the effect.", ua = "Речник Порожнечі Ейріх вивільняє конус тіньового розкладу в бік місцезнаходження гравця, завдаючи $s2 тіньової шкоди гравцям у зоні дії ефекту." },
    { en = "Big M.O.M.M.A. summons $s1 Darkfuse Mechadrones to assist them in combat.", ua = "Велика М.А.М.А. призиває $s1 механодрони Темногорна на допомогу собі в бою." },
    { en = "The mechadrone unleashes a strafing run towards a player, bombarding in a straight line and inflicting $472454S1 Nature damage to players within $472454A1 yards of each impact.", ua = "Мехадрон здійснює штурмовий захід на гравця, обстрілюючи по прямій лінії й завдаючи $472454S1 шкоди від сил природи гравцям у межах $472454A1 м від кожного влучання." },
    { en = "Big M.O.M.M.A. blasts a pulse of sonic energy towards a player which inflicts $473224s1 Sonic damage every $473224t1 sec while dragging and silencing players within.\n\n\n\n$@spelldesc473240", ua = "Велика М.А.М.А. випускає в гравця імпульс звукової енергії, що завдає $473224s1 звукової шкоди кожні $473224t1 с, тягнучи й знемовлюючи гравців усередині.\n\n\n\n$@spelldesc473240" },
    { en = "The electrified ground inflicts $s1 Nature damage every $t1 sec to players standing within.", ua = "Наелектризована земля завдає $s1 шкоди від сил природи кожні $t1 с гравцям, що стоять на ній." },
    { en = "Big M.O.M.M.A. crushes their target with an electrified claw, inflicting $s1 Nature damage and an additional $473836s1 Nature damage every $473836t1 sec for $473836d.", ua = "Велика М.А.М.А. трощить свою ціль електризованим пазуром, завдаючи $s1 шкоди від сил природи та додатково $473836s1 шкоди від сил природи кожні $473836t1 сек протягом $473836d." },
    { en = "The mechadrone fires a quick shot at a random player, inflicting $s1 Physical damage.", ua = "Мехадрон стріляє швидким пострілом по випадковому гравцеві, завдаючи $s1 фізичної шкоди." },
    { en = "The mechadrone overloads its communications array, inflicting $1214801s1 Sonic damage to players within $1214801A1 yards and pushing them away every $t1 sec for $d.", ua = "Механодрон перевантажує свій комунікаційний модуль, завдаючи $1214801s1 звукової шкоди гравцям у межах $1214801A1 ярдів і відкидаючи їх кожні $t1 с протягом $d." },
    { en = "Once all Darkfuse Mechadrones are defeated, Big M.O.M.M.A. attempts to jumpstart their depleted battery. This process causes it to take $s2% increased damage and release jolts of energy every $t1 sec for $d. Each jolt of energy inflicts $460158s1 Nature damage to all players.\n\n\n\nOnce their reserves are fully recharged, Big M.O.M.M.A. leaves behind $@spellname473287.", ua = "Щойно всіх Мехадронів Темнощитих переможено, Велика М.А.М.А. намагається силоміць запустити свою виснажену батарею. Цей процес змушує її отримувати на $s2% більше шкоди й вивільняти спалахи енергії кожні $t1 с протягом $d. Кожен спалах енергії завдає $460158s1 шкоди від сил природи всім гравцям.\n\n\n\nЩойно її резерви повністю заряджено, Велика М.А.М.А. лишає по собі $@spellname473287." },
    { en = "Big M.O.M.M.A. surrounds themselves in an electric barrier, reducing all damage taken by $s1%. While the shield is active, it inflicts $1215504s1 Nature damage to all players every $t2 sec.", ua = "Велика М.А.М.А. оточує себе електричним бар'єром, зменшуючи всю отримувану шкоду на $s1%. Поки щит активний, він завдає $1215504s1 шкоди від сил природи всім гравцям кожні $t2 с." },
    { en = "Keeza calls down a delivery of multiple Ticking Time Bombs. Ticking Time Bombs last for $460781d and cause $@spellname460787 when they expire.", ua = "Кіза викликає постачання кількох цокотливих бомб сповільненої дії. Цокотливі бомби тривають $460781d і спричиняють $@spellname460787, коли вибухають." },
    { en = "Bront barrels towards his target, inflicting $460965s1 Physical damage to any players in his way and stunning them for $460965d.\n\n\n\nThe force of Bront's charge is strong enough to knock away any Ticking Time Bombs in his path.", ua = "Бронт мчить на свою ціль, завдаючи $460965s1 фізичної шкоди всім гравцям на своєму шляху і приголомшуючи їх на $460965d.\n\n\n\nСила розгону Бронта достатня, щоб відкинути будь-які цокотливі бомби сповільненої дії на його шляху." },
    { en = "Defeating either Keeza or Bront causes the other to increase their damage done by $s1% every $470091t1 sec.\n\n\n\nBront also begins repeatedly $@spellname459799ing his foes.", ua = "Перемога над Кізою або Бронтом змушує іншого підвищувати завдану ним шкоду на $s1% кожні $470091t1 с.\n\n\n\nБронт також починає раз за разом застосовувати $@spellname459799 проти своїх ворогів." },
    { en = "Ticking Time Bombs explode when knocked into the air, raining down shrapnel that inflicts $s1 Fire damage to players within $A1 yards of impact.", ua = "Тікаючі бомби сповільненої дії вибухають, коли їх підкидає в повітря, осипаючи все шрапнеллю, що завдає $s1 вогняної шкоди гравцям у радіусі $A1 ярдів від місця падіння." },
    { en = "The Ticking Time Bomb explodes, inflicting $s1 Fire damage and an additional $461994s1 Fire damage every $461994t1 sec for $461994d to all players. This effect stacks.", ua = "Цокітлива бомба сповільненої дії вибухає, завдаючи $s1 вогняної шкоди та додатково $461994s1 вогняної шкоди кожні $461994t1 с протягом $461994d усім гравцям. Цей ефект накопичується." },
    { en = "Keeza unleashes her Blazing Ballistic Blunt Force Gun, inflicting $1217751s1 Fire damage to players caught in the blast and knocking them upwards.", ua = "Кіза вивільняє свою Палаючу Балістичну Гармату Тупого Удару, завдаючи $1217751s1 вогняної шкоди гравцям, захопленим вибухом, і підкидаючи їх угору." },
    { en = "Keeza affixes a Kinetic Explosive Gel to a player which inflicts $473713s1 Fire damage every $473713t1 sec for $473713d.\n\n\n\nRemoving the gel causes it to erupt with force, inflicting $473719s1 Fire damage to players and knocking up all Ticking Time Bombs within $473719A1 yards.", ua = "Кіза чіпляє до гравця Кінетичний Вибуховий Гель, що завдає $473713s1 вогняної шкоди кожні $473713t1 с протягом $473713d.\n\n\n\nЗнімання гелю спричиняє його потужний вибух, що завдає $473719s1 вогняної шкоди гравцям і підкидає всі Цокотливі Бомби Сповільненої Дії в радіусі $473719A1 ярдів." },
    { en = "Bront wallops his current target, inflicting $s1 Physical damage and knocking them upwards.", ua = "Бронт гамселить свою поточну ціль, завдаючи $s1 фізичної шкоди й підкидаючи її вгору." },
    { en = "Keeza fires a quick shot at a random player, inflicting $s1 Physical damage.", ua = "Кіза робить швидкий постріл у випадкового гравця, завдаючи $s1 фізичної шкоди." },
    { en = "Swampface ravages the target with gruesome claws, inflicting $469479s1 Physical damage and $469480s1 Nature damage. The muddy gashes absorb $469479s2 healing.", ua = "Болотопикий шматує ціль жахливими пазурами, завдаючи $469479s1 фізичної шкоди та $469480s1 шкоди від сил природи. Багнисті рани поглинають $469479s2 зцілення." },
    { en = "Swampface repeatedly smashes the ground every $t1 sec for $d, inflicting $473081s1 Nature damage to all players and causing Skewering Roots to erupt from the riverbed.", ua = "Болотопикий раз за разом гатить по землі кожні $t1 с протягом $d, завдаючи $473081s1 шкоди від сил природи всім гравцям і змушуючи Прохромливе Коріння виринати з річкового дна." },
    { en = "Swampface entangles players together in pairs. The vines inflict $472794s1 Nature damage every $472819t1 sec for $470041d. \n\n\n\nMoving $470041s1 yards apart yanks players back together.", ua = "Болотопикий сплутує гравців попарно. Лози завдають $472794s1 шкоди від сил природи кожні $472819t1 с протягом $470041d.\n\n\n\nЯкщо розійтися на $470041s1 м, гравців ривком стягує назад докупи." },
    { en = "Colossal roots burst from below, inflicting $473046s1 Nature damage to players within $473046A1 yards as Rushing Tides flow outwards.", ua = "Велетенські корені вибухають з-під землі, завдаючи $473046s1 шкоди від сил природи гравцям у межах $473046A1 ярдів, тимчасом як навсібіч розходяться рвучкі припливи." },
    { en = "Swampface upheaves massive amounts of mud in front of him, inflicting $473126s1 Nature damage to any player hit.", ua = "Баговиддя здіймає перед собою величезну кількість багна, завдаючи $473126s1 шкоди силами природи кожному враженому гравцю." },
    { en = "A wave of river water that inflicts $473051s1 Frost damage every $473051t1 sec to players within the effect and pushes them in its direction.", ua = "Хвиля річкової води, що завдає $473051s1 морозної шкоди кожні $473051t1 с гравцям у межах ефекту й штовхає їх у своєму напрямку." },
    { en = "Water leaks from the cracks above, forming pools. Contact with electricity transforms the pool into $@spellname468661.", ua = "Вода просочується крізь тріщини вгорі, утворюючи калюжі. Контакт з електрикою перетворює калюжу на $@spellname468661." },
    { en = "Beams of ultra death lightning emit from Geezle, inflicting $465982s1  Nature damage and stunning any players hit for $465982d.", ua = "Із Ґізла б'ють промені ультрасмертельної блискавки, завдаючи $465982s1 шкоди від сил природи й оглушуючи всіх вражених гравців на $465982d." },
    { en = "Geezle consumes $s1 Electricity to shock players with unlimited power, inflicting $468815s1 Nature damage and an additional $468815s2 Nature damage every $468815t2 sec for $468815d.", ua = "Ґізл споживає $s1 електрики, щоб уразити гравців безмежною силою, завдаючи $468815s1 шкоди силами природи та ще $468815s2 шкоди силами природи кожні $468815t2 с протягом $468815d." },
    { en = "Geezle consumes $s1 Electricity to galvanize several Leaping Sparks that fixate players.\n\n\n\nUpon contact, the spark inflicts $468647s1 Nature damage and stuns for $468647d.", ua = "Ґізл споживає $s1 електрики, щоб наелектризувати кілька Стрибучих Іскор, які фіксуються на гравцях.\n\n\n\nПри контакті іскра завдає $468647s1 шкоди силами природи й оглушує на $468647d." },
    { en = "Geezle siphons power from the generator into his battery pack, gaining 10 Electricity and emitting $465462s1 Nature damage to all players every $465463t1 sec for $465463d.", ua = "Ґізл відсмоктує енергію з генератора у свій акумуляторний блок, отримуючи 10 електрики і випромінюючи $465462s1 шкоди від сил природи всім гравцям кожні $465463t1 с протягом $465463d." },
    { en = "The dam structure shakes from the immense transfer of energy, causing water to leak and rubble to fall from above.", ua = "Конструкція греблі здригається від величезного переносу енергії, через що просочується вода й згори падає каміння." },
    { en = "The water electrifies, inflicting $468741s1 Nature damage and stunning any player inside for $468741d.\n\n\n\nInflicts $468723s1 Nature damage every $468723t1 sec to players within the effect.", ua = "Вода електризується, завдаючи $468741s1 шкоди від сил природи й оглушуючи кожного гравця всередині на $468741d.\n\n\n\nЗавдає $468723s1 шкоди від сил природи кожні $468723t1 сек гравцям у зоні дії." },
    { en = "Geezle consumes $s1 Electricity to sucker punch the target with a jolting fist, knocking them back and inflicting $466189s1 Physical damage and $466188s1 Nature damage every $466188t1 sec for $466188d.", ua = "Ґізл споживає $s1 електрики, щоб зненацька зацідити цілі електризованим кулаком, відкидаючи її та завдаючи $466189s1 фізичної шкоди й $466188s1 шкоди від сил природи кожні $466188t1 сек протягом $466188d." },
    { en = "Chunks of rock break and fall from the ceiling, inflicting $468604s1 Physical damage within $468604A1 yards of each impact.", ua = "Брили каменю відколюються й падають зі стелі, завдаючи $468604s1 фізичної шкоди в радіусі $468604A1 ярдів від кожного падіння." },
    { en = "If no targets are engaged in melee Azhiccar slams into the ground, inflicting $s1 Physical damage to all players.", ua = "Якщо жодна ціль не зайнята в ближньому бою, Азіккар гатить об землю, завдаючи $s1 фізичної шкоди всім гравцям." },
    { en = "Uncontrolled mites attack random targets.", ua = "Некеровані кліщі атакують випадкові цілі." },
    { en = "The devourer leaps towards a player and sinks their fangs into them, leeching $1217383s1 health and gaining $1217383s2% increased damage done for $1217383d. This effect stacks.", ua = "Пожирач стрибає до гравця й уп'ялюється в нього іклами, висмоктуючи $1217383s1 здоров'я й отримуючи на $1217383s2% більше завданої шкоди протягом $1217383d. Цей ефект накопичується." },
    { en = "Digestive acid burns players and creatures standing within, inflicting $s1 Shadow damage every $t1 sec and reducing their movement speed by $s2%.", ua = "Травна кислота обпікає гравців і створінь, що стоять усередині, завдаючи $s1 тіньової шкоди кожні $t1 сек. і знижуючи їхню швидкість пересування на $s2%." },
    { en = "Azhiccar screeches, calling forth Devourer Mites to join the battle and inflicting $1231850s1 Physical damage to all players.", ua = "Азіккар верещить, прикликаючи кліщів-пожирачів долучитися до бою й завдаючи $1231850s1 фізичної шкоди всім гравцям." },
    { en = "Upon reaching 100 energy, Azhiccar inhales and attempts to consume all players and creatures in the arena for $d, inflicting $1217316s1 Shadow damage to all players every $t2 sec.\n\n\n\nEach time Azhiccar successfully consumes a living creature or player, it $@spellname1217241s.", ua = "Сягнувши 100 енергії, Азіккар вдихає й намагається поглинути всіх гравців та істот на арені протягом $d, завдаючи $1217316s1 тіньової шкоди всім гравцям щороку $t2 сек.\n\n\n\nЩоразу, коли Азіккар успішно поглинає живу істоту чи гравця, він застосовує $@spellname1217241." },
    { en = "Azhiccar feasts on nearby living creatures and players, inflicting $s1 Shadow damage and knocking them back. The victim suffers $s2 Shadow damage every $t2 sec and is stunned for $d.\n\n\n\nAzhiccar restores $1217247s1% of its maximum health and gains $1217247s2% increased damage done for $1217247d. This effect stacks.", ua = "Азіккар пожирає живих істот і гравців поблизу, завдаючи $s1 тіньової шкоди й відкидаючи їх. Жертва отримує $s2 тіньової шкоди щороку $t2 сек і приголомшується на $d.\n\n\n\nАзіккар відновлює $1217247s1% свого максимального здоров'я й завдає на $1217247s2% більше шкоди протягом $1217247d. Цей ефект накопичується." },
    { en = "Azhiccar spews digestive acid at targeted players, inflicting $1217439s1 Shadow damage every $1217439t1 sec for $1217439d to enemies within $1217439a1 yards of impact and leaving a pool of $@spellname1217441 at their location.", ua = "Азіккар вивергає травну кислоту на обраних гравців, завдаючи $1217439s1 тіньової шкоди кожні $1217439t1 с протягом $1217439d ворогам у межах $1217439a1 ярдів від місця влучання та лишаючи калюжу «$@spellname1217441» на їхній позиції." },
    { en = "Taah'bat disperses into pure energy, reducing all damage taken by $s1% until shattered out of the ether.\n\n\n\nUpon being struck with $@spellname1227137, Taah'bat loses an application of $@spellname1219457. Upon losing all applications of $@spellname1219457, both A'wazj and Taah'bat become $@spellname1219731.", ua = "Таа'бат розпадається на чисту енергію, зменшуючи всю отримувану шкоду на $s1%, доки його не виб'ють з ефіру.\n\n\n\nКоли його вражає $@spellname1227137, Таа'бат втрачає одне накопичення ефекту $@spellname1219457. Втративши всі накопичення ефекту $@spellname1219457, А'вадж і Таа'бат стають уразливими до $@spellname1219731." },
    { en = "A'wazj coalesces echoes of itself that warp towards marked targets, inflicting $1227152s1 Arcane damage to players in their path and causing them to suffer $1227152s2 Arcane damage every $1227152t2 sec for $1227152d. This effect stacks.", ua = "А'вадж зливає докупи відлуння самого себе, що викривлюються в бік позначених цілей, завдаючи $1227152s1 арканної шкоди гравцям на своєму шляху й змушуючи їх зазнавати $1227152s2 арканної шкоди кожні $1227152t2 с протягом $1227152d. Цей ефект накопичується." },
    { en = "A'wazj warps through the target, inflicting $1220390s1 Arcane damage to players in its path and causing them to suffer $1220390s2 Arcane damage every $1220390t2 sec for $1220390d. This effect stacks.", ua = "А'вадж викривлюється крізь ціль, завдаючи $1220390s1 арканної шкоди гравцям на своєму шляху й змушуючи їх зазнавати $1220390s2 арканної шкоди кожні $1220390t2 сек протягом $1220390d. Цей ефект накопичується." },
    { en = "Taah'bat launches arcane javelins at targeted players, inflicting $1219704s1 Arcane damage to players within $1219704A1 yards of the targets and tethering all players struck. \n\n\n\nEach tether inflicts $1239487s1 Arcane damage every $t1 sec and reduces their movement speed by $s2%, increasing in intensity every $s3 seconds until the javelin is destroyed. This effect stacks.", ua = "Таа'бат метає арканні дротики в позначених гравців, завдаючи $1219704s1 арканної шкоди гравцям у межах $1219704A1 ярдів від цілей і прив'язуючи всіх уражених. \n\n\n\nКожна прив'язь завдає $1239487s1 арканної шкоди кожні $t1 с і знижує швидкість пересування на $s2%, посилюючись кожні $s3 секунди, доки дротик не буде знищено. Цей ефект накопичується." },
    { en = "Taah'bat unleashes a series of arcane javelins into the air, inflicting $s1 Arcane damage to all players every $1220511t1 sec.", ua = "Таа'бат вивільняє в повітря низку арканних дротиків, завдаючи $s1 арканної шкоди всім гравцям кожні $1220511t1 сек." },
    { en = "The collision knocks both Taah'bat and A'wazj out of the ether, stunning them for $d and bringing the $@spellname1219700 to a halt.", ua = "Зіткнення вибиває і Таа'бата, і А'ваджа з ефіру, приголомшуючи їх на $d і зупиняючи $@spellname1219700." },
    { en = "Upon reaching 100 energy, A'wazj vanishes and unleashes $@spellname1227137 at players while Taah'bat gains $@spellname1219457 and goes into $@spellname1220497.", ua = "Досягнувши 100 одиниць енергії, А'вадж зникає і вивільняє $@spellname1227137 на гравців, тоді як Таа'бат отримує $@spellname1219457 і переходить у стан $@spellname1220497." },
    { en = "Taah'bat and A'wazj are bonded, causing them to share all damage taken.", ua = "Таа'бат і А'вадж пов'язані, тож вони ділять усю отриману шкоду." },
    { en = "A'wazj slashes their current target with its Arcane-charged claws, inflicting $s1 Arcane damage and causing them to bleed for $1219535s1 Physical damage every $1219535t1 sec for $1219535d.", ua = "А'вадж шматує свою поточну ціль кігтями, зарядженими арканною енергією, завдаючи $s1 арканної шкоди та змушуючи її кровоточити, що завдає $1219535s1 фізичної шкоди кожні $1219535t1 сек. протягом $1219535d." },
    { en = "Soul-Scribe splinters the soul of every player, summoning multiple echoes of their Fate and causing them to suffer $1224868s1 Arcane damage.", ua = "Скрижальниця Доль розколює душу кожного гравця, прикликаючи численні відлуння його долі й завдаючи $1224868s1 арканної шкоди." },
    { en = "Converged with Fate, increasing damage and healing done by $s1% for $d. This effect stacks.", ua = "Злита з долею, що збільшує завдану шкоду й зцілення на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Soul-Scribe imbues marked players with dread. Upon expiration, the player erupts inflicting $1225308s1 Arcane damage to players within $1225226A1 yards of the eruption.\n\n\n\nFates struck afflict their bound player with $@spellname1226444.", ua = "Скрижальниця Доль сповнює позначених гравців жахом. Після завершення гравець вибухає, завдаючи $1225308s1 арканної шкоди гравцям у межах $1225226A1 м від вибуху.\n\n\n\nВражені долі насилають на свого зв'язаного гравця $@spellname1226444." },
    { en = "Soul-Scribe flings daggers in the direction of Fates and Fatebound players, inflicting $1225179s1 Arcane damage to players struck and inflicting an additional $1225179s2 Arcane damage every $1225179t2 sec for $1225179d.\n\n\n\nFates struck afflict their bound player with $@spellname1226444.", ua = "Скрижальниця Доль метає кинджали в напрямку Доль і приречених гравців, завдаючи $1225179s1 арканної шкоди ураженим гравцям і додатково $1225179s2 арканної шкоди кожні $1225179t2 с протягом $1225179d.\n\n\n\nУражені Долі вражають свого прив'язаного гравця ефектом $@spellname1226444." },
    { en = "The player's fate suffers a debilitating wound, causing the player to suffer $s1 Arcane damage every $t1 sec and haste reduced by $s2% for $d.", ua = "Доля гравця зазнає виснажливої рани, через що гравець отримує $s1 арканної шкоди кожні $t1 с, а його поспіх знижено на $s2% протягом $d." },
    { en = "Soul-Scribe's energy radiates $1242006s1 Arcane damage every $t1 sec to all players.", ua = "Енергія Скрижальниці Доль випромінює $1242006s1 арканної шкоди кожні $t1 сек. усім гравцям." },
    { en = "Soul-Scribe shatters the fate of every player, summoning echoes of their Fate and causing them to suffer $1249985s1 Arcane damage.", ua = "Скрижальниця Доль розбиває долю кожного гравця, прикликаючи відлуння їхньої Долі та змушуючи їх зазнати $1249985s1 арканної шкоди." },
    { en = "Upon reaching 100 energy Soul-Scribe enters a ritual for $d, unleashing a series of cones that inflict $1236910s1 Arcane damage to players caught within.\n\n\n\nFates struck afflict their bound player with $@spellname1226444.", ua = "Сягнувши 100 енергії, Скрижальниця Доль починає ритуал на $d, вивільняючи низку конусів, що завдають $1236910s1 арканної шкоди гравцям, які в них потрапили.\n\n\n\nВражені долі накладають на прив'язаного до них гравця $@spellname1226444." },
    { en = "Rasha'nan blasts webs at marked targets inflicting $439781s1 Nature damage$?diff15|diff16[ to players within $439781A1 yards][], tethering $?diff15|diff16[all struck players][the player] and creating $@spellname439780. This tether inflicts $456170s1 Nature damage every $456170T1 sec, pulling their victim inward.\n\n\n\nStretching this tether $439779A1 yards snaps it, causing a $@spellname439778.", ua = "Раша'нан вистрілює павутиною в позначені цілі, завдаючи $439781s1 шкоди від сил природи$?diff15|diff16[ гравцям у межах $439781A1 ярдів][], прив'язуючи $?diff15|diff16[всіх уражених гравців][гравця] і створюючи $@spellname439780. Ця прив'язь завдає $456170s1 шкоди від сил природи кожні $456170T1 с, притягуючи свою жертву всередину.\n\n\n\nЯкщо розтягнути цю прив'язь на $439779A1 ярдів, вона розривається, спричиняючи $@spellname439778." },
    { en = "$@spellname439784 snap inflicting $439778s1 Nature damage to all players.", ua = "Розрив $@spellname439784 завдає $439778s1 шкоди від сил природи всім гравцям." },
    { en = "$@spellname439784' silken adhesive coats the arena inflicting $439780s1 Nature damage every $439780T1 sec and reducing movement speed by $439780s2%.", ua = "Шовкова клейка речовина $@spellname439784 вкриває арену, завдаючи $439780s1 шкоди від сил природи кожні $439780T1 с і знижуючи швидкість пересування на $439780s2%." },
    { en = "Skarmorak is bolstered by surrounding Skardyn crystals, absorbing $s1 damage taken.\n\nAfter taking substantial damage, the shell shatters, stunning Skarmorak.", ua = "Скарморака зміцнюють навколишні кристали скардинів, поглинаючи $s1 отриманої шкоди.\n\nПісля значної шкоди оболонка розколюється, оглушуючи Скарморака." },
    { en = "Rasha'nan expels a poisonous concoction at marked targets which sloshes off in waves in the indicated direction from the target. \n\n\n\nPlayers splashed by the initial corrosive eruption are caught in an $@spellname439787.\n\n\n\nAny player that touches a wave has their movement speed reduced by $439786s2% and gains $@spellname439785 every $439786T1 sec.\n\n\n\nThe waves incinerate $@spellname439780 inflicting $457467s1 Nature damage to players within $457467A1 yards and creates $@spellname439776.", ua = "Раша'нан вивергає отруйне вариво в позначені цілі, яке розхлюпується хвилями в указаному напрямку від цілі. \n\n\n\nГравців, забризканих початковим їдким викидом, вражає $@spellname439787.\n\n\n\nБудь-якому гравцеві, що торкається хвилі, знижується швидкість пересування на $439786s2%, і він отримує $@spellname439785 кожні $439786T1 сек.\n\n\n\nХвилі спалюють $@spellname439780, завдаючи $457467s1 шкоди від сил природи гравцям у межах $457467A1 ярдів, та створюють $@spellname439776." },
    { en = "Erosive Spray, Caustic Hail, and Rolling Acid can form caustic zones for $439777D. Contact with this zone inflicts $439776s1 Nature damage every $439776T1 sec.", ua = "Їдкий бризк, Їдкий град та Перекатна кислота можуть утворювати їдкі зони на $439777D. Контакт із такою зоною завдає $439776s1 шкоди від сил природи кожні $439776T1 сек." },
    { en = "Vile acid corrodes the target for $439785D, suffering $439785s1 Nature damage every $439785T1 sec. This effect stacks.", ua = "Мерзенна кислота роз'їдає ціль протягом $439785D, завдаючи $439785s1 шкоди від сил природи кожні $439785T1 сек. Цей ефект накопичується." },
    { en = "The propulsive expulsion of $@spellname439789 inflicts $s1 Nature damage and stuns for $439787D.", ua = "Реактивне виверження $@spellname439789 завдає $s1 шкоди від сил природи та оглушує на $439787D." },
    { en = "Fractures of Skarmorak are loaded with latent energy, inflicting $s1 Shadow damage to players within $a1 yd.", ua = "Уламки Скарморака сповнені прихованої енергії й завдають $s1 шкоди тінню гравцям у радіусі $a1 м." },
    { en = "The pulse explodes upon colliding with an obstacle, inflicting $s1 Sonic damage to players within $473221s2 yards.", ua = "Імпульс вибухає при зіткненні з перешкодою, завдаючи $s1 звукової шкоди гравцям у радіусі $473221s2 ярдів." },
    { en = "Rira spins in a furious tornado of steel towards random players several times in a row at $s2% reduced speed for $377844d, inflicting $377830s1 Physical damage to all players within $377830A1 yards every $t1 sec. while spinning.", ua = "Ріра кілька разів поспіль кружляє в лютому сталевому смерчі до довільних гравців зі зниженою на $s2% швидкістю протягом $377844d, завдаючи $377830s1 фізичної шкоди всім гравцям у межах $377830A1 ярдів кожні $t1 сек., поки кружляє." },
    { en = "Gashtooth flings an alchemical bag of decay at the target, inflicting $s1 Nature damage, and blinding them. \n\n\n\nAdditionally, increases Physical damage taken by $s3% for $d.", ua = "Ґаштут жбурляє в ціль алхімічну торбу гниття, завдаючи $s1 шкоди від сил природи та засліплюючи її. \n\n\n\nКрім того, посилює отримувану фізичну шкоду на $s3% на $d." },
    { en = "Gashtooth rapidly shadowsteps between players five times, inflicting $s1 Physical damage. Players struck bleed for $s2 Physical damage every $t2 sec. for $d. This effect stacks.\n\n\n\nThis effect is removed if the player is healed over 90% health.", ua = "Черевостріл п'ять разів стрімко переноситься тінню між гравцями, завдаючи $s1 фізичної шкоди. Уражені гравці кровоточать, отримуючи $s2 фізичної шкоди кожні $t2 с протягом $d. Цей ефект накопичується.\n\n\n\nЦей ефект знімається, якщо гравцю відновлюють понад 90% здоров'я." },
    { en = "Gashtooth flings an alchemical bag of decay at the target, inflicting $s1 Nature damage. \n\n\n\nAdditionally, increases Physical damage taken by $s3% for $d.", ua = "Гаштут жбурляє в ціль алхімічний мішок тління, завдаючи $s1 шкоди від сил природи.\n\n\n\nКрім того, збільшує отримувану фізичну шкоду на $s3% протягом $d." },
    { en = "Gashtooth rapidly shadowsteps between players five times, inflicting $s1 Physical damage. Players struck bleed for $s2 Physical damage every $t2 sec. for $d.", ua = "Гаштут блискавично тіньокроком п'ять разів переміщується між гравцями, завдаючи $s1 фізичної шкоди. Уражені гравці кровоточать, отримуючи $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Rira lines up a powerful charge with a player. After 14 sec., she charges towards them and collides with the first player in her path, inflicting $s1 Physical damage to that target.", ua = "Ріра готує потужний ривок проти гравця. Через 14 сек. вона мчить до нього й стикається з першим гравцем на своєму шляху, завдаючи $s1 фізичної шкоди цій цілі." },
    { en = "Tricktotem propels a mass of earth at her current target, inflicting $s1 Nature damage.", ua = "Трюкотем жбурляє масу землі в свою поточну ціль, завдаючи $s1 шкоди від сил природи." },
    { en = "When an ally's remaining health drops below 15%, Tricktotem increases the haste and damage done of all her fellow gnolls by $s1% until the end of the encounter.", ua = "Коли залишок здоров'я союзника падає нижче 15%, Хитрототем збільшує поспіх і завдану шкоду всіх своїх побратимів-ґнолів на $s1% до кінця сутички." },
    { en = "Rira's melee attacks strike all players in front of her within $A1 yards.", ua = "Ближні атаки Ріри вражають усіх гравців перед нею в межах $A1 ярдів." },
    { en = "Increases haste by $s1%.\n\n\n\nThis effect stacks.", ua = "Збільшує поспіх на $s1%.\n\n\n\nЦей ефект накопичується." },
    { en = "Gashtooth focuses on relentlessly butchering a player, inflicting $378230s1 Physical damage every $t1 sec. for $d.", ua = "Гаштут зосереджується на безжальній розправі над гравцем, завдаючи $378230s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Tricktotem heals a friendly target for $s1, and additionally $s2 every $t2 sec. for $d.", ua = "Хитрототем зцілює дружню ціль на $s1, а також на $s2 кожні $t2 с протягом $d." },
    { en = "The totem reduces a player to a helpless forest creature, incapacitating them for up to $d while channeling.", ua = "Тотем перетворює гравця на безпорадну лісову істоту, знесилюючи його на час до $d, доки підтримує силу." },
    { en = "The War-Band senses weakness in its prey, gaining a stack of $@spellname389808 for every $s2% total health missing from players.", ua = "Бойова ватага відчуває слабкість своєї здобичі, отримуючи заряд $@spellname389808 за кожні $s2% сукупного здоров'я, якого бракує гравцям." },
    { en = "Tricktotem summons a totem that channels a $@spellname381466 on a player, incapacitating them for $381466d.", ua = "Хитрототем прикликає тотем, що підтримує $@spellname381466 на гравця, знесилюючи його на $381466d." },
    { en = "Treemouth's digestive fluids remain on the eaten player, increasing the damage they would take from $@spellname377222 by $s1% for $d.", ua = "Травні соки Деревопащі лишаються на з'їденому гравцеві, збільшуючи шкоду, яку він зазнав би від $@spellname377222, на $s1% протягом $d." },
    { en = "Treemouth lashes out and grabs players with its decaying vines, dragging them towards it for $d. After dragging players closer, Treemouth begins to $@spellname377184 the nearest player.", ua = "Деревопащ накидається й хапає гравців своїми гнилими лозами, тягнучи їх до себе протягом $d. Притягнувши гравців ближче, Деревопащ починає $@spellname377184 щодо найближчого гравця." },
    { en = "Treemouth devours the nearest player, absorbing all damage. After $d or $s1 damage taken, Treemouth spits out the consumed player.", ua = "Деревопаща пожирає найближчого гравця, поглинаючи всю шкоду. Через $d або після $s1 отриманої шкоди Деревопаща випльовує проковтнутого гравця." },
    { en = "Treemouth devours the nearest player, inflicting $s1 Nature damage every $t1 sec for $d.\n\n\n\nWhile $@spellname378022, Treemouth absorbs the next $378022s1 damage. If broken, Treemouth spits the consumed player out.", ua = "Деревопаща пожирає найближчого гравця, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.\n\n\n\nПід час $@spellname378022 Деревопаща поглинає наступні $378022s1 шкоди. Якщо ефект перервано, Деревопаща випльовує поглиненого гравця." },
    { en = "When defeated, the Decaying Slime bursts, inflicting $s2 Nature damage to players within $A2 yards of the impact and leaving behind a pool of decay for $d.", ua = "Коли його переможено, Тліючий Слиз лопається, завдаючи $s2 шкоди від сил природи гравцям у межах $A2 м від місця влучання й лишаючи по собі калюжу гнилі на $d." },
    { en = "Players standing in the decay pool begin to wither away, suffering $s1 Nature damage every $t1 sec. In addition, movement speed is reduced by $s2%.", ua = "Гравці, що стоять у калюжі гнилі, починають марніти, зазнаючи $s1 пог. природою кожні $t1 сек. Крім того, швидкість пересування знижується на $s2%." },
    { en = "Decaying Slime splashes, inflicting $s1 Nature damage to all players within $A2  yards.", ua = "Гнильний слиз розбризкується, завдаючи $s1 шкоди від сил природи всім гравцям у межах $A2 м." },
    { en = "Treemouth retches out in a cone in front of it, inflicting $s2 Nature damage to all players struck and summoning 4 Decaying Slimes.", ua = "Деревопащ вивергає блювотиння конусом перед собою, завдаючи $s2 пог. природою всім враженим гравцям і прикликаючи 4 Гнилих Слизів." },
    { en = "Treemouth spits at random players, covering all hit players with infected spit. This effect inflicts $s1 Nature damage every $t1 sec and reduces movement speed by $s2% for $d. This effect stacks.", ua = "Деревопаща плює в довільних гравців, вкриваючи всіх уражених заразним слиновинням. Цей ефект завдає $s1 шкоди від сил природи кожні $t1 сек. і знижує швидкість пересування на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Treemouth vine whips in front of itself, inflicting $s1 Physical damage and knocking back all targets struck.", ua = "Деревопаща шмагає лозою перед собою, завдаючи $s1 фізичної шкоди й відкидаючи всі вражені цілі." },
    { en = "Angered by the missed meal, Treemouth enrages. Damage done is increased by $s1% and haste is increased by $s2% for $d.", ua = "Розлючена упущеною трапезою, Деревопаща впадає в лють. Завдавана шкода зростає на $s1%, а поспіх — на $s2% протягом $d." },
    { en = "Gutshot throws a chunk of bloody meat at a random target, causing them to $@spellname384425.", ua = "Черевостріл кидає шматок кривавого м'яса у випадкову ціль, накладаючи на неї $@spellname384425." },
    { en = "The smell of fresh meat lingers, attracting a Rotfang Hyena's interest for $d.", ua = "Запах свіжого м'яса витає в повітрі, привертаючи увагу гнилоіклої гієни на $d." },
    { en = "The Rotfang Hyena leaps to a random target, inflicting $s1 Physical damage and stunning all players within $A2 yards for $d.", ua = "Гнилозуба гієна стрибає на випадкову ціль, завдаючи $s1 фізичної шкоди та оглушуючи всіх гравців у межах $A2 м протягом $d." },
    { en = "Gutshot aims her crossbow and fires a powerful shot, inflicting $s1 Physical damage and knocking the player back.", ua = "Черевостріл наводить свій арбалет і робить потужний постріл, завдаючи $s1 од. фізичної шкоди та відкидаючи гравця." },
    { en = "Gutshot increases damage done of allies within 15 yards by $387889s2%, and reduces their cooldowns by $387889s1%.", ua = "Черевостріл збільшує шкоду, завдану союзниками в межах 15 м, на $387889s2% і зменшує їхні перезарядження на $387889s1%." },
    { en = "Gutshot launches a trap towards random players. When triggered, the trap entangles all creatures and players within $A2 yards and inflicts $s3 Physical damage every $t3 sec for $d.", ua = "Черевостріл запускає пастку в напрямку випадкових гравців. Спрацювавши, пастка обплутує всіх істот і гравців у радіусі $A2 ярдів і завдає $s3 фізичної шкоди кожні $t3 сек протягом $d." },
    { en = "The Rotfang Hyena leaps to a random target, inflicting $s1 Physical damage to all players within $A2 yards.", ua = "Гнилоікла гієна стрибає на випадкову ціль, завдаючи $s1 фізичної шкоди всім гравцям у межах $A2 м." },
    { en = "Gushot calls out for help, signaling $s3 Rotfang Hyenas to aid her in battle.", ua = "Черевостріл кличе на допомогу, подаючи знак $s3 гнилоіклим гієнам прийти їй на поміч у бою." },
    { en = "The Rotfang Hyena begins to chase the target that $@spellname384425, enraging itself for $d. While enraged, all damage done is increased by $s1%.", ua = "Гнилоікла гієна починає переслідувати ціль, позначену $@spellname384425, впадаючи в лють на $d. У стані люті вся завдана шкода збільшується на $s1%." },
    { en = "Gutshot calls to her Rotfang Hyenas, freeing them from the $@spellname384148. The hyenas gain immunity to all such effects and movement speed is increased by $s4% for $d.", ua = "Черевостріл кличе своїх гнилоіклих гієн, звільняючи їх від $@spellname384148. Гієни отримують несприйнятливість до всіх таких ефектів, а їхня швидкість пересування підвищується на $s4% на $d." },
    { en = "The hyena bites the target, inflicting $384577s1 Physical damage. \n\n\n\nIn addition,$s1 Physical damage is inflicted every $t1 sec, healing taken is reduced by $s2% and movement speed is decreased by $s3% for $d.", ua = "Гієна кусає ціль, завдаючи $384577s1 од. фізичної шкоди. \n\n\n\nКрім того, кожні $t1 с завдається $s1 од. фізичної шкоди, отримуване зцілення знижено на $s2%, а швидкість пересування зменшено на $s3% на $d." },
    { en = "The player erupts for $s1 damage to all nearby players, the size of the effect is increased by the applications of $@spellname373896 on the player.", ua = "Гравець вибухає, завдаючи $s1 шкоди всім гравцям поблизу; розмір ефекту збільшується залежно від кількості накладань $@spellname373896 на гравця." },
    { en = "Withering Rot saps the player's strength, inflicting $s2 Nature damage every $t2 sec. and reducing damage done by $s3% $?DIFF23|$?DIFF8[until Wratheye is defeated][for $d].\n\n\n\nThis effect stacks.", ua = "Виснажлива гнилизна висотає силу гравця, завдаючи $s2 шкоди від сил природи кожні $t2 с і зменшуючи завдану шкоду на $s3%$?DIFF23|$?DIFF8[, доки Гнівооку не буде переможено][ протягом $d].\n\n\n\nЦей ефект накопичується." },
    { en = "Wratheye evokes a deadly ritual, converting players' applications of $@spellname373896 into $@spellname374186 for herself, increasing damage done by $s1%. This effect stacks.\n\n\n\nAdditionally creates a $@spellname387264 at each player's location.", ua = "Гнівоока творить смертоносний ритуал, перетворюючи накладання $@spellname373896 з гравців на $@spellname374186 для себе й збільшуючи завдану шкоду на $s1%. Цей ефект накопичується.\n\n\n\nКрім того, створює $@spellname387264 у місці кожного гравця." },
    { en = "Wratheye breathes out a cloud of decay, inflicting $s2 Nature to players in front of her. The rot coalesces into a drifting cloud, inflicting $376149s2 Nature damage every $376149t2 sec. silencing players and applying $@spellname373896 to players within.", ua = "Гнівоока видихає хмару гнилі, завдаючи $s2 шкоди від сил природи гравцям перед собою. Тлін згущується в рухливу хмару, що завдає $376149s2 шкоди від сил природи кожні $376149t2 с, занімовлює гравців і накладає $@spellname373896 на тих, хто всередині." },
    { en = "The Rotburst Totem inflicts $s1 Nature damage to all players and applies $@spellname373896.", ua = "Тотем гнилоспалаху завдає $s1 шкоди від сил природи всім гравцям і накладає $@spellname373896." },
    { en = "Wratheye breathes out a cloud of decay, inflicting $376170s2 Nature to players in front of her. The rot coalesces into a drifting cloud, inflicting $376149s2 Nature damage every $376149t2 sec. and silencing players within.", ua = "Гнівоока видихає хмару тління, завдаючи $376170s2 шкоди від сил природи гравцям перед собою. Гнилизна збирається в хмару, що дрейфує, завдаючи $376149s2 шкоди від сил природи кожні $376149t2 с і знеголошуючи гравців усередині." },
    { en = "The Rotburst Totem inflicts $373939s1 Nature damage to all players.", ua = "Тотем гнилобуху завдає $373939s1 шкоди від сил природи всім гравцям." },
    { en = "Wratheye summons a $@spellname373944 at a location, inflicting $s2 Nature damage to any players at the location when it lands.\n\n\n\nThe totem repeatedly casts $@spellname373941.", ua = "Гнівоока прикликає $@spellname373944 у певному місці, завдаючи $s2 шкоди від сил природи всім гравцям у цьому місці, коли він приземляється.\n\n\n\nТотем раз за разом творить $@spellname373941." },
    { en = "Wratheye evokes a deadly ritual, granting $@spellname374186 to herself, increasing damage done by $374186s1%. This effect stacks.\n\n\n\nAdditionally creates a $@spellname387264 at each player's location.", ua = "Гнівоока творить смертоносний ритуал, надаючи собі $@spellname374186 і збільшуючи завдану шкоду на $374186s1%. Цей ефект накопичується.\n\n\n\nКрім того, створює $@spellname387264 у місці кожного гравця." },
    { en = "The player erupts for $387264s1 damage to all nearby players.", ua = "Гравець вибухає, завдаючи $387264s1 шкоди всім гравцям поблизу." },
    { en = "Wratheye infuses her claws with decay and strikes her target twice, inflicting $373915s1 Physical damage and absorbing $s1 healing taken with each hit.", ua = "Гнівоока наповнює свої кігті гниллю і двічі б'є ціль, завдаючи $373915s1 фізичної шкоди й поглинаючи $s1 отриманого зцілення кожним ударом." },
    { en = "Watcher Irideus grants himself $s2 applications of $@spellname383840, which reduces incoming damage by $s1%. While this barrier holds, he uses $@spellname389056 to gain strength.\n\n\n\nApplications of $@spellname383840 can be removed by $@spellname389446.", ua = "Вартовий Іридей надає собі $s2 застосувань $@spellname383840, що зменшує отримувану ним шкоду на $s1%. Поки цей бар'єр тримається, він використовує $@spellname389056, щоб набирати сили.\n\n\n\nЗастосування $@spellname383840 можна зняти за допомогою $@spellname389446." },
    { en = "Watcher Irideus siphons power from the titan facility itself, increasing his Nature damage done by $389486s1% every $t2 sec for $d. Removing $@spellname383840 interrupts further power gains.", ua = "Вартовий Іридей викачує силу з самого об'єкта титанів, збільшуючи завдавану ним шкоду від сил природи на $389486s1% кожні $t2 с протягом $d. Зняття $@spellname383840 перериває подальше накопичення сили." },
    { en = "The Nullification Device blasts a random target, inflicting $s1 Arcane damage on impact with an additional $s2 Arcane damage every $t2 sec for $d. This effect stacks.", ua = "Пристрій нейтралізації б'є по випадковій цілі, завдаючи $s1 арканної шкоди при влучанні та додатково $s2 арканної шкоди кожні $t2 с протягом $d. Цей ефект накладається стосами." },
    { en = "Upon being destroyed, a Nullification Device will fire off a Nullification Pulse. This pulse inflicts $s1 Arcane damage and silences all players within $a1 yards for $d.\n\n\n\nNullification Pulse also removes one application of Ablative Shield if it strikes Watcher Irideus.", ua = "Будучи знищеним, нуліфікаційний пристрій випускає нуліфікаційний імпульс. Цей імпульс завдає $s1 арканної шкоди й позбавляє мови всіх гравців у межах $a1 ярдів протягом $d.\n\n\n\nНуліфікаційний імпульс також знімає одне застосування Аблятивного щита, якщо вражає Вартового Іридея." },
    { en = "Upon being destroyed, a Nullification Device will fire off a Nullification Pulse. This pulse inflicts $s1 Arcane damage and silences all players within $a1 yards for $d.\n\n\n\nNullification Pulse also removes one application of Ablative Shield.", ua = "Будучи знищеним, нуліфікаційний пристрій випускає нуліфікаційний імпульс. Цей імпульс завдає $s1 арканної шкоди й позбавляє мови всіх гравців у межах $a1 ярдів протягом $d.\n\n\n\nНуліфікаційний імпульс також знімає одне застосування Аблятивного щита." },
    { en = "Watcher Irideus slams his fist down, inflicting $s1 Physical damage and knocking down all players in front of him.", ua = "Вартовий Іридей б'є кулаком об землю, завдаючи $s1 фізичної шкоди та збиваючи з ніг усіх гравців перед собою." },
    { en = "The Nullification Device blasts a random target, inflicting $s1 Arcane damage on impact with an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Пристрій Нейтралізації б'є по випадковій цілі, завдаючи $s1 арканної шкоди при влучанні та додатково $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Watcher Irideus siphons power from the titan facility itself. Removing $@spellname383840 interrupts further power gains.", ua = "Вартовий Іридей викачує силу з самого об'єкта титанів. Зняття $@spellname383840 перериває подальше накопичення сили." },
    { en = "Arcane energy flows out from Watcher Irideus, inflicting $s1 Arcane damage to all players every $384014t1 sec for $384014d.", ua = "Арканна енергія струмує з Вартового Іридея, завдаючи $s1 арканної шкоди всім гравцям кожні $384014t1 с протягом $384014d." },
    { en = "Watcher Irideus fires a volley of sparks from his core. Each spark strikes players within $a1 yards of the impact, inflicting $s1 Arcane damage with an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Вартовий Іридей випускає залп іскор зі свого ядра. Кожна іскра вражає гравців у межах $a1 м від місця влучання, завдаючи $s1 арканної шкоди й додатково $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Watcher Irideus infuses $s2 enemies with electricity, inflicting $s1 Nature damage every $t1 sec for $d. When the infusion expires or is removed, it leaves behind a $@spellname389181 for $389180d.", ua = "Вартовий Іридей наповнює електрикою $s2 ворогів, спричиняючи $s1 шкоди від сил природи кожні $t1 с протягом $d. Коли наповнення спливає або знімається, воно лишає по собі $@spellname389181 на $389180d." },
    { en = "The $@spellname389181 electrifies players within it, inflicting $s1 Nature damage every $t1 sec.", ua = "$@spellname389181 електризує гравців усередині, спричиняючи $s1 шкоди від сил природи кожні $t1 с." },
    { en = "The Gulping Goliath unleashes a massive croak, inflicting $s1 Physical damage to all players every $385181t1 sec for $385181d.\n\n\n\nThe croak shakes the caverns, causing rocky debris and Curious Swoglets to rain from above.", ua = "Ковтливий Голіаф вивільняє могутнє кумкання, завдаючи $s1 фізичної шкоди всім гравцям кожні $385181t1 с протягом $385181d.\n\n\n\nКумкання струшує печери, через що згори сиплеться кам'яне груддя та Цікаві свогленята." },
    { en = "The Gulping Goliath inflicts $s1 Nature damage to all players every $385442t1 sec for $385442d.", ua = "Ковтливий Голіаф завдає $s1 шкоди від сил природи всім гравцям кожні $385442t1 сек упродовж $385442d." },
    { en = "The Gulping Goliath becomes very mad when hungry, increasing Physical damage done by $s1% for $d. This effect stacks.", ua = "Зголоднівши, Ковтливий Голіаф дуже лютує, що збільшує завдану ним фізичну шкоду на $s1% на $d. Цей ефект накопичується." },
    { en = "Falling rocks inflict $s1 Physical damage to players within $A1 yards of each impact and sends $s2 Curious Swoglets crashing down from above.", ua = "Падуче каміння завдає $s1 фізичної шкоди гравцям у межах $A1 ярдів від кожного удару й скидає згори $s2 цікавих своґлетів." },
    { en = "Fixates a nearby target.", ua = "Зосереджується на цілі поблизу." },
    { en = "The Goliath attempts to gulp down players and creatures within $385551A1 yards for $d, inflicting $388245s1 Nature damage every $t1 sec for its duration. While inside the Goliath's gullet, the target also gains $s2 stacks of Gulp Swog Toxin.\n\n\n\nIf the Goliath does not find a player to gulp, he will become Hangry.", ua = "Голіаф намагається проковтнути гравців та істот у межах $385551A1 ярдів протягом $d, завдаючи $388245s1 шкоди від сил природи щомиті $t1 сек упродовж цього часу. Перебуваючи в горлянці Голіафа, ціль також отримує $s2 стаків Токсину Жадібного Свога.\n\n\n\nЯкщо Голіаф не знайде гравця, щоб проковтнути, він стане Голодлютим." },
    { en = "Deadly toxin inflicts $s1 Nature damage every $t1 sec for $d.\n\n\n\nInstantly kills upon reaching $s2 applications.", ua = "Смертельна отрута завдає $s1 пог. природою кожні $t1 сек. протягом $d.\n\n\n\nМиттєво вбиває, сягнувши $s2 зарядів." },
    { en = "The Gulping Goliath leaps up and crashes down upon a target location, inflicting $s1 Physical damage to all players within $a1 yards upon landing.", ua = "Ковтливий Голіаф підстрибує і обвалюється на вибране місце, завдаючи при приземленні $s1 од. фізичної шкоди всім гравцям у межах $a1 ярдів." },
    { en = "The Goliath attempts to gulp down players and creatures within $385551A1 yards for $d, inflicting $388245s1 Nature damage every $t1 sec for its duration.", ua = "Голіаф намагається проковтнути гравців і створінь у межах $385551A1 ярдів протягом $d, завдаючи $388245s1 шкоди Природою кожні $t1 с упродовж усієї дії." },
    { en = "Rings of frost surge out from Khajin, inflicting $s1 Frost damage to players struck by a ring.\n\n\n\nThe surge leaves behind several Ice Boulders.", ua = "Із Каджин вихоплюються кільця морозу, завдаючи $s1 морозної шкоди гравцям, яких влучило кільце.\n\n\n\nЦей сплеск лишає по собі кілька крижаних брил." },
    { en = "Khajin the Unyielding launches a volley of hailstones at all players and Ice Boulders, inflicting $s1 Frost damage to players struck.\n\n\n\nIce Boulders will block incoming hailstones, becoming damaged in the process.", ua = "Каджин Незламна випускає залп градин по всіх гравцях і крижаних брилах, завдаючи $s1 морозної шкоди враженим гравцям.\n\n\n\nКрижані брили блокують градини, що летять, але при цьому пошкоджуються." },
    { en = "Khajin the Unyielding unleashes Polar Winds, inflicting $s1 Frost damage every $t1 sec to all players until she is defeated.", ua = "Каджин Незламна вивільняє Полярні Вітри, завдаючи $s1 морозної шкоди кожні $t1 сек усім гравцям, доки її не буде здолано." },
    { en = "Khajin the Unyielding throws a jagged icicle, inflicting $s1 Frost damage and reducing the target's movement speed by $s2% for $d.", ua = "Каджин Незламна жбурляє зазубрену бурульку, завдаючи $s1 морозної шкоди й знижуючи швидкість пересування цілі на $s2% протягом $d." },
    { en = "The surge of frost forms into a solid chunk of ice which can block the effects of Hailstorm twice.\n\n\n\nAfter the second time the Boulder blocks such an effect, it will break apart into an Avalanche.", ua = "Сплеск морозу формується у твердий шмат криги, який може двічі заблокувати ефекти Граду.\n\n\n\nКоли брила вдруге заблокує такий ефект, вона розколеться на Лавину." },
    { en = "Khajin the Unyielding launches a volley of hailstones at all players, inflicting $386757s1 Frost damage to players struck.", ua = "Каджин Незламна випускає залп градин по всіх гравцях, спричиняючи $386757s1 морозної шкоди влученим гравцям." },
    { en = "Rings of frost surge out from Khajin, inflicting $386562s1 Frost damage to players struck by a ring.", ua = "Від Каджин розходяться кільця морозу, спричиняючи $386562s1 морозної шкоди гравцям, яких влучило кільце." },
    { en = "Khajin conjures a Frost Cyclone which barrels forward in the direction of an enemy. The Cyclone inflicts $s1 Frost damage and knocks back players caught in the area. The Cyclone additionally damages Ice Boulders it contacts.", ua = "Каджин Незламна прикликає Морозний Циклон, що мчить уперед у напрямку ворога. Циклон завдає $s1 морозної шкоди й відкидає гравців, які потрапили в зону дії. Крім того, Циклон ушкоджує Крижані Брили, яких торкається." },
    { en = "When an Ice Boulder is destroyed, it explodes into an avalanche of ice, inflicting $s1 Frost damage to all players within $a1 yards.", ua = "Коли Крижаний Валун знищено, він вибухає крижаною лавиною, завдаючи $s1 морозної шкоди всім гравцям у межах $a1 м." },
    { en = "The Primal Tsunami unleashes several globules of water, inflicting $387474s1 Frost damage to players within $387474A1 yards of each impact.\n\n\n\nThe Infused Globule then drifts about, applying Waterlogged to players on contact.\n\n\n\nAfter $s2 sec, the Globule explodes, inflicting $s1 Frost damage to players within $a1 yards.", ua = "Первісне Цунамі вивільняє кілька водяних кульок, завдаючи $387474s1 морозної шкоди гравцям у радіусі $387474A1 ярдів від кожного влучання.\n\n\n\nСповнена енергією кулька потім дрейфує навколо, накладаючи на гравців «Промоклість» при дотику.\n\n\n\nЗа $s2 с кулька вибухає, завдаючи $s1 морозної шкоди гравцям у радіусі $a1 ярдів." },
    { en = "The Primal Tsunami entraps each player in a bubble of water and casts them away.", ua = "Первісне Цунамі ув'язнює кожного гравця в бульбашці води й відкидає геть." },
    { en = "The Primalist Infuser channels into the Primal Tsunami, increasing its damage done by $s1%. This effect continues to stack every $387618t1 sec until it is interrupted.", ua = "Вливальниця первісників підтримує силу в Первісне Цунамі, підвищуючи завдану ним шкоду на $s1%. Цей ефект накопичується далі щомиті $387618t1 сек, доки його не перервуть." },
    { en = "The Primalist Infuser channels into the Primal Tsunami, restoring its form.", ua = "Вливальниця первісників скеровує енергію в Первісне Цунамі, відновлюючи його форму." },
    { en = "The Primal Tsunami calls upon raging storms and inflicts $s1 Frost damage to all players.", ua = "Первісне Цунамі прикликає люті бурі й завдає $s1 морозної шкоди всім гравцям." },
    { en = "The Primal Tsunami causes a burst of wind at its current target, inflicting $s1 Frost damage and knocking them away.", ua = "Первісне Цунамі здіймає порив вітру на поточну ціль, завдаючи $s1 морозної шкоди й відкидаючи її." },
    { en = "When the Primal Tsunami is unable to attack enemies in melee, it periodically inflicts $389875s1 Frost damage to all players.", ua = "Коли Первісне Цунамі не може атакувати ворогів у ближньому бою, воно періодично завдає $389875s1 морозної шкоди всім гравцям." },
    { en = "The Primalist Infuser hurls spheres of infused water at players within $a1 yards, inflicting $s1 Frost damage.", ua = "Вливальниця первісників жбурляє сфери насиченої води в гравців у радіусі $a1 м, завдаючи $s1 морозної шкоди." },
    { en = "The Primal Tsunami inundates its current target with water, inflicting $s1 Frost damage every $t1 sec for $d.", ua = "Первісне Цунамі затоплює свою поточну ціль водою, завдаючи $s1 морозної шкоди щомиті $t1 сек протягом $d." },
    { en = "The Primal Tsunami causes a burst of wind at its current target, inflicting $387504s1 Frost damage.", ua = "Первісне Цунамі здіймає порив вітру на своїй поточній цілі, спричиняючи $387504s1 морозної шкоди." },
    { en = "A crashing tsunami washes over the player, inflicting $s1 Frost damage and knocking the target away.", ua = "Навальне цунамі накриває гравця, завдаючи $s1 морозної шкоди та відкидаючи ціль." },
    { en = "Infused waters inundate a target, inflicting $s1 Frost damage and slowing the target's movement by $s2% for $d.", ua = "Сповнені енергією води затоплюють ціль, завдаючи $s1 морозної шкоди та сповільнюючи рух цілі на $s2% протягом $d." },
    { en = "Inflicts $s1 Fire damage to all players and an additional $s2 Fire damage every $t2 sec for $d.", ua = "Завдає $s1 вогняної шкоди всім гравцям і додатково $s2 вогняної шкоди кожні $t2 с протягом $d." },
    { en = "Lava flies off of Chargath and inflicts $s1 Fire damage to all players within $A1 yards of the impact.", ua = "Від Чарґата відлітає лава й завдає $s1 вогняної шкоди всім гравцям у межах $A1 ярдів від точки влучання." },
    { en = "Chargath lunges at a random player striking them for $373735s1 Physical damage and causing them to bleed for an additional $373735s2 Physical damage every $373735t2 sec. for $373735d.", ua = "Чарґат кидається на довільного гравця, вражаючи його на $373735s1 фізичної шкоди й змушуючи кровоточити, завдаючи додатково $373735s2 фізичної шкоди кожні $373735t2 сек. протягом $373735d." },
    { en = "Magma erupts out of the ground around the spear, inflicting $374854s1 Fire damage every $374854t1 sec to players within.", ua = "Магма виривається з землі довкола списа, завдаючи $374854s1 вогняної шкоди кожні $374854t1 с гравцям поблизу." },
    { en = "Inflicts $389059s1 Fire damage to all players and an additional $389059s2 Fire damage every $389059t2 sec for $389059d. This effect stacks.", ua = "Завдає $389059s1 шкоди Вогнем усім гравцям і додатково $389059s2 шкоди Вогнем кожні $389059t2 с протягом $389059d. Цей ефект накопичується." },
    { en = "Chargath unleashes a growing wave of magma that inflicts $373756s1 Fire damage to all players in its wake.", ua = "Чарґат вивільняє дедалі більшу хвилю магми, що завдає $373756s1 шкоди Вогнем усім гравцям на її шляху." },
    { en = "If Chargath trips on $@spellname374482, it breaks, knocking him down for $d.", ua = "Якщо Чарґат спіткнеться об $@spellname374482, той розривається й збиває його з ніг на $d." },
    { en = "Chargath hurls a $@spellname373424 at a random player, inflicting $396672s1 Physical damage and applying $@spellname374482 to the target.", ua = "Чарґат жбурляє $@spellname373424 у випадкового гравця, завдаючи $396672s1 фізичної шкоди та накладаючи $@spellname374482 на ціль." },
    { en = "Upon reaching 100 energy, Chargath fixates on his primary target, unleashing a flurry of magma attacks for $375055d. \n\n\n\nWhile|Hspell:375056|h $@spellname375056|h is in effect, Chargath inflicts $384019s1 Physical damage and $437458s1 Fire damage to target player every $375055t7 sec and emits|Hspell:375397|h Lava Splashes|h every $375055t3 sec.\n\n\n\nChargath unleashes a wave of magma if $@spellname375056 is not interrupted, afflicting all players with $@spellname414585.", ua = "Сягнувши 100 енергії, Чарґат зосереджується на основній цілі, вивільняючи шквал магматичних атак протягом $375055d. \n\n\n\nПоки діє |Hspell:375056|h $@spellname375056|h, Чарґат завдає $384019s1 фізичної шкоди та $437458s1 вогняної шкоди цільовому гравцеві кожні $375055t7 с і випускає|Hspell:375397|h Бризки лави|h кожні $375055t3 с.\n\n\n\nЧарґат вивільняє хвилю магми, якщо $@spellname375056 не перервати, накладаючи на всіх гравців $@spellname414585." },
    { en = "Reduces the movement speed of the chained player by $s1%. When broken, the tripped target suffers from $@spellname374655 and the chain explodes with |Hspell:395656|h$@spellname389059|h.", ua = "Знижує швидкість пересування скутого ланцюгом гравця на $s1%. Коли ланцюг розривається, спіткнута ціль зазнає $@spellname374655, а сам ланцюг вибухає з |Hspell:395656|h$@spellname389059|h." },
    { en = "If Chargath trips on $@spellname374482, it explosively breaks and slows him for $374655d. This effect stacks.", ua = "Якщо Чарґат спіткнеться об $@spellname374482, той з вибухом розбивається й сповільнює його на $374655d. Цей ефект накопичується." },
    { en = "Chargath unleashes a wave of lava, inflicting $s1 Fire damage to all players every $t1 sec for $d.", ua = "Чарґат вивільняє хвилю лави, завдаючи $s1 вогняної шкоди всім гравцям щосекунди впродовж $t1 на $d." },
    { en = "The Forgemaster performs a pair of swings on his current target, inflicting $375306s2 Physical damage each, and knocking the target away.\n\n\n\nHe then leaps to the target's location and slams down with his ignited hammer, inflicting $374517s1 Physical damage and $374397s1 Fire damage to players within $374397A1 yards of impact.", ua = "Майстер кузні завдає поточній цілі двох ударів, кожен з яких заподіює $375306s2 фізичної шкоди й відкидає ціль.\n\n\n\nПотім він стрибає на місце цілі й б'є об землю своїм розжареним молотом, завдаючи $374517s1 фізичної шкоди та $374397s1 пог. вогнем гравцям у межах $374397A1 ярдів від місця влучання." },
    { en = "The final slam of $@spellname374535 creates a pool of $@spellname381482 that inflicts $s1 Fire damage every $t1 sec to players inside it and reduces their movement speed by $s2%.", ua = "Останній удар $@spellname374535 створює калюжу $@spellname381482, що завдає $s1 вогняної шкоди щомиті $t1 сек гравцям усередині неї та знижує їхню швидкість пересування на $s2%." },
    { en = "The Forgemaster leaps to his anvil, inflicting $374586s1 Physical damage to all players upon landing and begins forging a $@spellname374812.", ua = "Майстер-Коваль стрибає до свого ковадла, завдаючи $374586s1 фізичної шкоди всім гравцям при приземленні, і починає кувати $@spellname374812." },
    { en = "The Forgemaster throws his hammer into the forge, provoking it to fire a barrage of blazing embers across the room that inflict $375241s1 Fire damage to players within $375241A1 yards of impact.", ua = "Майстер-Коваль жбурляє свій молот у горно, спонукаючи його випустити шквал палаючих жарин по всій залі, що завдають $375241s1 вогняної шкоди гравцям у межах $375241A1 ярдів від влучання." },
    { en = "Each strike of the Forgemaster's hammer upon his anvil inflicts $374641s1 Fire damage to all players.", ua = "Кожен удар молота Майстра-Коваля об ковадло завдає $374641s1 вогняної шкоди всім гравцям." },
    { en = "Inflicts $375061s1 Fire damage to players within $375061A1 yards of impact.", ua = "Завдає $375061s1 вогняної шкоди гравцям у радіусі $375061A1 ярдів від влучання." },
    { en = "The Forgemaster hurls the freshly forged shield at a player, inflicting $375046s1 Fire damage within $375046A1 yards and an additional $392666s1 Fire damage every $392666t1 sec for $392666d.\n\n\n\nBlazing Eruptions are triggered in four directions.", ua = "Майстер кузні жбурляє в гравця щойно викуваний щит, завдаючи $375046s1 пог. вогнем у межах $375046A1 ярдів і додаткові $392666s1 пог. вогнем кожні $392666t1 сек. протягом $392666d.\n\n\n\nУ чотирьох напрямках запускаються Полум'яні Виверження." },
    { en = "Magmatusk becomes strengthened while standing in lava, increasing all damage inflicted by $s1%.", ua = "Магматуск стає сильнішим, перебуваючи в лаві, що збільшує всю завдану шкоду на $s1%." },
    { en = "Inflicts $s1 Fire damage every $t1 sec.", ua = "Завдає $s1 вогняної шкоди кожні $t1 сек." },
    { en = "Magma Tentacles grow from Magmatusk's back, increasing $@spellname375251 damage inflicted by $s1%, increasing the number of Lava Waves released by $@spellname375449, and increases the duration of $@spellname375890.", ua = "Зі спини Магматуска виростають Магмові Щупальця, підвищуючи шкоду від $@spellname375251 на $s1%, збільшуючи кількість Лавових Хвиль, що вивільняються $@spellname375449, і подовжуючи тривалість $@spellname375890." },
    { en = "Magmatusk releases a wave of fire, inflicting $s1 Fire damage to anyone it collides with.", ua = "Магматуск вивільняє хвилю вогню, завдаючи $s1 вогняної шкоди всім, з ким вона стикається." },
    { en = "Magmatusk erupts with lava, inflicting $s1 Fire damage and $s2 Fire damage every $t2 sec to all players. Magma Eruption lasts $t2 sec for each application of $@spellname374410.", ua = "Магматуск вивергає лаву, завдаючи $s1 вогняної шкоди і $s2 вогняної шкоди кожні $t2 сек усім гравцям. Виверження Магми триває $t2 сек за кожне застосування $@spellname374410." },
    { en = "Magmatusk sprays a cone of lava at a player, inflicting $s2 Fire damage.", ua = "Магматуск бризкає конусом лави на гравця, завдаючи $s2 вогняної шкоди." },
    { en = "Magmatusk charges forward, inflicting $s1 Fire damage and knocking back all players in the way. At the end of the charge, Magmatusk unleashes one $@spellname375535 for each $@spellname374410.", ua = "Магматуск кидається вперед, завдаючи $s1 вогняної шкоди і відкидаючи всіх гравців на шляху. Наприкінці ривка Магматуск вивільняє одну $@spellname375535 за кожне $@spellname374410." },
    { en = "Upon reaching 100 Magma, Magmatusk mutates and triggers $@spellname375890 and applies an application of $@spellname374410.", ua = "Сягнувши 100 Магми, Магматуск мутує, запускає $@spellname375890 та накладає один заряд $@spellname374410." },
    { en = "Magmatusk's tentacles launches globs of lava at players, inflicting $s1 Fire damage to players within $A1 yards of the point of impact and leaving behind a pool of $@spellname375204.", ua = "Щупальця Магматуска жбурляють у гравців згустки лави, завдаючи $s1 вогняної шкоди гравцям у радіусі $A1 ярдів від точки влучання та лишаючи по собі калюжу $@spellname375204." },
    { en = "Warlord Sargha launches an empowered fire ember, inflicting $s1 Fire damage to all players within $A1 yards of the point of impact. This ember creates $@spellname377542, and summons a Raging Ember.", ua = "Воєначальниця Сарга випускає посилений вогняний жар, завдаючи $s1 пог. вогнем усім гравцям у межах $A1 ярдів від місця влучання. Цей жар створює $@spellname377542 та прикликає Лютий Жар." },
    { en = "$@spellname377542 inflicts $s1 Fire damage to an enemy every $t1 sec.", ua = "$@spellname377542 завдає ворогові $s1 пог. вогнем кожні $t1 сек." },
    { en = "The $@spellname392171 unleashes its mystical energy, inflicting $s1 Arcane damage to damage absorb shields to all enemies within $A1 yards.", ua = "$@spellname392171 вивільняє свою містичну енергію, завдаючи $s1 арканної шкоди щитам поглинання всіх ворогів у межах $A1 ярдів." },
    { en = "Inflicts $s1 Arcane damage to damage absorb shields.", ua = "Завдає $s1 арканної шкоди щитам, що поглинають шкоду." },
    { en = "Warlord Sargha envelops herself in shield of magma, absorbing $s2 damage taken, and triggering $@spellname376783 every $t1 sec for $d.", ua = "Воєначальниця Сарга огортає себе щитом із магми, поглинаючи $s2 отриманої шкоди й запускаючи $@spellname376783 кожні $t1 сек. протягом $d." },
    { en = "Warlord Sargha erupts with fire, inflicting $s1 Fire damage and applying $@spellname376784 to every player.", ua = "Воєначальниця Саргха вибухає вогнем, завдаючи $s1 вогняної шкоди й накладаючи $@spellname376784 на кожного гравця." },
    { en = "$@spellname376784 causes players to take $s1% more damage from subsequent $@spellname376783 for $d. This effect stacks.", ua = "$@spellname376784 змушує гравців отримувати на $s1% більше шкоди від наступних застосувань $@spellname376783 протягом $d. Цей ефект накопичується." },
    { en = "Picking up a weapon unleashes a curse, inflicting $s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Підняття зброї вивільняє прокляття, що завдає $s1 тіньової шкоди щомиті $t1 сек протягом $d. Цей ефект накопичується." },
    { en = "The Raging Ember fixates a random player.", ua = "Лютий Жар націлюється на випадкового гравця." },
    { en = "Warlord Sargha unleashes a cone of fire, inflicting $s2 Fire damage to all players in front of her.", ua = "Воєначальниця Саргха вивільняє конус вогню, завдаючи $s2 вогняної шкоди всім гравцям перед собою." },
    { en = "Warlord Sargha erupts with fire, inflicting $376783s1 Fire damage to every player.", ua = "Воєначальниця Саргха вибухає вогнем, завдаючи $376783s1 вогняної шкоди кожному гравцеві." },
    { en = "Inflicts $s1 Arcane damage to damage absorb shields within $A1 yards of the impact.", ua = "Завдає $s1 од. арканної шкоди щитам поглинання шкоди в межах $A1 ярдів від місця влучання." },
    { en = "Warlord Sargha hurls $@spellname377018 at a player, inflicting $s1 Fire damage every $t1 sec.", ua = "Воєначальниця Сарга жбурляє $@spellname377018 у гравця, завдаючи $s1 пог. вогнем кожні $t1 сек." },
    { en = "The lava erupts launching magma, inflicting $s1 Fire damage to players within $A1 yds of the impact.", ua = "Лава вивергається, викидаючи магму, що завдає $s1 вогняної шкоди гравцям у межах $A1 ярдів від точки влучання." },
    { en = "Melidrussa launches a shard of ice that inflicts $s1 Frost damage to her current player target.", ua = "Мелідрусса запускає крижаний осколок, що спричиняє $s1 морозної шкоди її поточній цілі-гравцю." },
    { en = "$@spellname372682 reduces the player's movement speed by $s2% per application. \n\n\n\nUpon reaching $U applications, the player's body is overloaded with primal frost energy and $@spellname373022.", ua = "$@spellname372682 зменшує швидкість руху гравця на $s2% за кожне застосування.\n\n\n\nСягнувши $U застосувань, тіло гравця перевантажується первісною морозною енергією, і настає $@spellname373022." },
    { en = "Infused Whelps attack their target with frost-infused claws, inflicting $s1 Frost damage and applying $@spellname372682.", ua = "Наповнені Драконятка атакують ціль крижаними кігтями, завдаючи $s1 шкоди Морозом та накладаючи $@spellname372682." },
    { en = "Melidrussa causes a detonation of primal frost energy that inflicts $s1 Frost damage to all players and launches $@spellname396044 at them.\n\n\n\nThese $@spellname396044 explode in a blast of chilling ice if contacted by a player, inflicting $384024s1 Frost damage to that player.", ua = "Мелідрусса Холодоткана спричиняє детонацію первісної морозної енергії, що завдає $s1 морозної шкоди всім гравцям і запускає в них $@spellname396044.\n\n\n\nЦі $@spellname396044 вибухають спалахом крижаного холоду, якщо до них торкнеться гравець, завдаючи $384024s1 морозної шкоди цьому гравцеві." },
    { en = "$?diff23[Melidrussa channels primal frost energy for $d, encasing herself in an $@spellname372988 for the duration. \n\n\n\nWhile channeling, she inflicts $373688s1 Frost damage every $t1 sec to all players.][Melidrussa channels primal frost energy for $d.\n\n\n\nWhile channeling, she inflicts $373688s1 Frost damage every $t1 sec to all players.]", ua = "$?diff23[Мелідрусса підтримує первісну енергію морозу протягом $d, оточуючи себе $@spellname372988 на весь час дії. \n\n\n\nПід час каналізації вона завдає $373688s1 морозної шкоди кожні $t1 сек. всім гравцям.][Мелідрусса підтримує первісну енергію морозу протягом $d.\n\n\n\nПід час каналізації вона завдає $373688s1 морозної шкоди кожні $t1 сек. всім гравцям.]" },
    { en = "Melidrussa summons a growing storm of frost at a player's location that pulls players towards the center. \n\n\n\nEvery $372963t1 sec, the storm inflicts $397077s1 Frost damage to all players and an additional $372963s1 Frost damage to players standing within it.\n\n\n\nAfter $372961d the storm explodes, inflicting $383925s1 Frost damage to all players and pushing them away.", ua = "Мелідрусса прикликає на місці гравця наростаючий морозний шторм, що притягує гравців до центру.\n\n\n\nКожні $372963t1 с шторм спричиняє $397077s1 морозної шкоди всім гравцям і додатково $372963s1 морозної шкоди гравцям, що стоять усередині.\n\n\n\nЧерез $372961d шторм вибухає, спричиняючи $383925s1 морозної шкоди всім гравцям і відкидаючи їх." },
    { en = "Melidrussa calls upon her Infused Whelps to join the fight.", ua = "Мелідрусса прикликає своїх Сповнених енергією драконят, щоб ті долучилися до бою." },
    { en = "$@spellname372988 absorbs $s2 damage and prevents $@spellname373680 from being interrupted.", ua = "$@spellname372988 поглинає $s2 шкоди й не дає перервати $@spellname373680." },
    { en = "Chilling magic freezes the player solid, stunning them for $d and inflicting $s4 Frost damage every $t4 sec.", ua = "Крижана магія сковує гравця льодом, оглушуючи його на $d та завдаючи $s4 шкоди Морозом кожні $t4 сек." },
    { en = "Upon reaching 100 energy, Kokia summons a Blazebound Firestorm near a player's location, searing players within $a1 yards for $s1 Fire damage.", ua = "Сягнувши 100 енергії, Кокія прикликає Полум'яний вогняний шторм поблизу гравця, обпалюючи гравців у радіусі $a1 ярдів на $s1 вогняної шкоди." },
    { en = "Kokia slams a molten boulder into the ground in front of her, inflicting $s1 Fire damage to any player it touches, knocking them back and stunning them for $d.\n\n\n\nThe boulder rolls forward up to $372832s1 yds and then explodes, inflicting $372819s1 damage to players within $372819A1 yds.", ua = "Кокія обрушує розплавлену брилу об землю перед собою, завдаючи $s1 вогняної шкоди кожному гравцеві, якого вона торкнеться, відкидаючи їх та оглушуючи на $d.\n\n\n\nБрила котиться вперед до $372832s1 м, а потім вибухає, завдаючи $372819s1 шкоди гравцям у межах $372819A1 м." },
    { en = "The scorched ground inflicts $s1 Fire damage to players within the flames every $t1 sec. Lasts $372825d.", ua = "Випалена земля спричиняє $s1 вогняної шкоди гравцям усередині полум'я кожні $t1 с. Триває $372825d." },
    { en = "The Blazebound Firestorm radiates flames that inflict $s1 Fire damage to all players, plus an additional $s2 Fire damage every $t2 sec for $d.", ua = "Полум'ясповита вогняна буря випромінює полум'я, що завдає $s1 вогняної шкоди всім гравцям, а також додатково $s2 вогняної шкоди кожні $t2 с протягом $d." },
    { en = "The Blazebound Firestorm blasts all players with flames, inflicting $s2 Fire damage.", ua = "Полум'яний вогняний шторм обпалює всіх гравців полум'ям, завдаючи $s2 вогняної шкоди." },
    { en = "Kokia strikes her target $s1 times over $d, inflicting $372859s1% weapon damage and applying $@spellname372860 with each strike.", ua = "Кокія завдає цілі $s1 ударів за $d, спричиняючи $372859s1% шкоди зброї та накладаючи $@spellname372860 з кожним ударом." },
    { en = "Each strike from Searing Blows causes the target's skin to blister and bleed, inflicting $s1 Physical damage every $t1 sec for $d. This effect stacks.", ua = "Кожен удар Обпікаючих ударів спричиняє пухирі та кровотечу на шкірі цілі, завдаючи $s1 фізичної шкоди кожні $t1 с протягом $d. Цей ефект накладається стосами." },
    { en = "When its health is depleted, the Blazebound Firestorm goes out with a bang, inflicting $s1 Fire damage to players within $A2 yds.", ua = "Коли його здоров'я вичерпується, Полум'яний вогняний шторм гине з вибухом, завдаючи $s1 вогняної шкоди гравцям у радіусі $A2 ярдів." },
    { en = "Chars the ground with fire for $381868D, inflicting $384773s1 Fire damage every $384773T1 sec. $?diff23|diff8[ applying $@spellname381862 upon contact.][]", ua = "Випалює землю вогнем протягом $381868D, завдаючи $384773s1 вогняної шкоди кожні $384773T1 с. $?diff23|diff8[ накладаючи $@spellname381862 при дотику.][]" },
    { en = "Kyrakka's $@spellname381525 and $@spellname381607 ignite targets, inflicting $381862s1 Fire damage every half-second for $381862D. This effect stacks.\n\n\n\nUpon removal these flames explode inflicting $381864s2 Fire damage to players within $381864A2 yards, creating a pool of $@spellname384773 nearby for each stack.", ua = "$@spellname381525 та $@spellname381607 Кіракки підпалюють цілі, завдаючи $381862s1 вогняної шкоди кожні півсекунди протягом $381862D. Цей ефект накопичується.\n\n\n\nПри знятті це полум'я вибухає, завдаючи $381864s2 вогняної шкоди гравцям у радіусі $381864A2 м і створюючи поряд калюжу $@spellname384773 за кожен заряд." },
    { en = "Kyrakka spits a gout of fire, inflicting $381607s1 Fire damage to targeted players, applying $@spellname381862 to effected players.", ua = "Кіракка випльовує струмінь вогню, завдаючи $381607s1 вогняної шкоди позначеним гравцям і накладаючи $@spellname381862 на уражених гравців." },
    { en = "Erkhart delivers a massive blow to a player, inflicting $381514s1 Physical damage and $381513s1 Nature damage$?diff23|diff8[, additionally increasing Nature damage taken by $381515s1% for $381515D. This effect stacks.][.]", ua = "Еркгарт завдає гравцеві нищівного удару, що спричиняє $381514s1 фізичної шкоди й $381513s1 шкоди від сил природи$?diff23|diff8[ та додатково підвищує отримувану шкоду від сил природи на $381515s1% протягом $381515D. Цей ефект накопичується.][.]" },
    { en = "Erkhart conjures a massive torrent, inflicting $381516s1 Nature damage to all players and interrupting casts for $381516D.", ua = "Еркгарт прикликає потужний потік, що завдає $381516s1 шкоди від сил природи всім гравцям і перериває творіння заклять протягом $381516D." },
    { en = "Erkhart conjures a localized hurricane, inflicting $381518s1 Nature damage every $381518T1 sec. for $381517D, directionally pushing players and Kyrakka's $@spellname384773.", ua = "Еркгарт прикликає локальний ураган, що завдає $381518s1 шкоди від сил природи щомиті $381518T1 сек протягом $381517D і спрямовано штовхає гравців та Кіраккину $@spellname384773." },
    { en = "Kyrakka forges flames in a frontal direction, tempering targets for $381526s1 Fire damage every second for $381525D, applying $@spellname381862 to affected players.", ua = "Кіракка кує полум'я перед собою, гартуючи цілі $381526s1 вогняної шкоди щосекунди протягом $381525D і накладаючи $@spellname381862 на уражених гравців." },
    { en = "Erkhart conjures a massive torrent, inflicting $381516s1 Nature damage to all players.", ua = "Еркгарт прикликає потужний потік, що завдає $381516s1 шкоди від сил природи всім гравцям." },
    { en = "Leymor consumes the energy of all Ley-Line Sprouts and stomps the ground, inflicting $374731s1 Arcane damage to all players.", ua = "Леймор поглинає енергію всіх паростей лей-ліній і тупає по землі, завдаючи $374731s1 арканної шкоди всім гравцям." },
    { en = "Leymor ruptures the ground in front of itself, inflicting $s2 Arcane damage and knocking back any players struck.\n\n\n\nAlso, any Ley-Line Sprouts caught in the rupture are destroyed.", ua = "Леймор розриває землю перед собою, завдаючи $s2 арканної шкоди і відкидаючи всіх вражених гравців.\n\n\n\nТакож усі Паростки Лей-Ліній, що потрапили в розрив, знищуються." },
    { en = "Leymor strikes a player with magical energy, inflicting $s1 Arcane damage with an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Леймор б'є гравця магічною енергією, спричиняючи $s1 арканної шкоди та додаткові $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Leymor slams the ground, inflicting $374582s2 Arcane damage to players within $374582A2 yards, knocking them back and afflicting all players with a magical brand that explodes after $d. This eruption destroys Ley-Line Sprouts and inflicts $374582s2 Arcane damage to players within $374570A1 yards.", ua = "Леймор б'є об землю, завдаючи $374582s2 арканної шкоди гравцям у радіусі $374582A2 м, відкидаючи їх та позначаючи всіх гравців магічним тавром, що вибухає за $d. Цей вибух знищує паростки лей-ліній і завдає $374582s2 арканної шкоди гравцям у радіусі $374570A1 м." },
    { en = "The sapling explodes, inflicting $s1 Arcane damage and slowing enemies by $s2% within $A1 yards for $d.", ua = "Паросток вибухає, завдаючи $s1 арканної шкоди й уповільнюючи ворогів на $s2% у межах $A1 м на $d." },
    { en = "Ley-Line sprouts create Volatile Saplings when destroyed.", ua = "Пагони лей-ліній, коли їх знищують, створюють нестабільні саджанці." },
    { en = "Ley-Line Sprouts increase the damage done by Leymor's $@spellname374720 by $s1% for each living sprout.", ua = "Парості лей-ліній збільшують шкоду, що завдає $@spellname374720 Леймора, на $s1% за кожну живу парость." },
    { en = "Magical roots inflict $s1 Arcane damage every $t1 sec to players within $s3 yards.", ua = "Магічне коріння завдає $s1 арканної шкоди кожні $t1 с гравцям у радіусі $s3 м." },
    { en = "Leymor causes several Ley-Line Sprouts to spring forth and grow nearby.", ua = "Леймор змушує кілька Паростків Лей-Ліній прорости й вирости поблизу." },
    { en = "Azureblade moves to the center of the room and begins to gain power from the draconic seal. She protects herself with Draconic Illusions and inflicts $384625s1 Arcane damage to all players every $t1 sec until all the illusions have been destroyed.", ua = "Лазурний Клинок переміщується до центру кімнати й починає черпати силу з драконячої печатки. Він захищає себе Драконячими Ілюзіями й завдає $384625s1 арканної шкоди всім гравцям кожні $t1 с, доки всі ілюзії не будуть знищені." },
    { en = "Azureblade slices players within $a1 yards in front of herself, inflicting $s1 Arcane damage.", ua = "Лазурний Клинок розтинає гравців у межах $a1 м перед собою, завдаючи $s1 арканної шкоди." },
    { en = "Azureblade creates an orb of pure magic and hurls it at a player inflicting $385579s1 Arcane damage and knocking back all players in the path of the orb.", ua = "Лазурний Клинок створює сферу чистої магії й кидає її в гравця, завдаючи $385579s1 арканної шкоди й відкидаючи всіх гравців на шляху сфери." },
    { en = "The image fires an illusory bolt at a random player, inflicting $s1 Arcane damage.", ua = "Образ випускає ілюзорну стрілу по випадковому гравцю, завдаючи $s1 арканної шкоди." },
    { en = "Upon death, releases fragments of magic toward each player. Inflicts $s1 Arcane damage to players within $a1 yds of the impact location.", ua = "Після загибелі вивільняє уламки магії в бік кожного гравця. Завдає $s1 арканної шкоди гравцям у межах $a1 м від місця влучання." },
    { en = "Draconic Illusions channel on Azureblade and make her immune to incoming damage.", ua = "Драконічні ілюзії спрямовуються на Лазурний Клинок і роблять її несприйнятливою до отримуваної шкоди." },
    { en = "Azureblade's $@spellname384132 causes magic to stream out uncontrollably. Players that come into contact with an orb suffer $s1 Arcane damage and are knocked back.", ua = "$@spellname384132 Лазурного Клинка змушує магію витікати некеровано. Гравці, які торкаються сфери, зазнають $s1 арканної шкоди й відкидаються назад." },
    { en = "Azureblade summons an illusion of herself to attack and disrupt players.", ua = "Лазурний Клинок прикликає свою ілюзію, щоб нападати на гравців і переривати їх." },
    { en = "Telash freezes the area, gathering power to unleash a large attack, inflicting $s1 Frost damage to all players. Players are rooted for $396722d1, if not protected by a Vault Rune.", ua = "Телаш заморожує область, збираючи силу для потужної атаки, що завдає $s1 морозної шкоди всім гравцям. Гравці знерухомлюються на $396722d1, якщо їх не захищає Руна Сховища." },
    { en = "Sindragosa's image detects destructive magic and activates Vault Runes to protect players by reducing damage taken by $s1%.", ua = "Образ Синдрагоси виявляє руйнівну магію й активує руни Сховища, захищаючи гравців і знижуючи отримувану шкоду на $s1%." },
    { en = "The cold freezes the ground in the area for $387149d1, inflicting $s1 Frost damage every $t1 sec and reducing movement speed by $s2%.", ua = "Холод заморожує землю в цій ділянці на $387149d1, спричиняючи $s1 морозної шкоди кожні $t1 с і знижуючи швидкість пересування на $s2%." },
    { en = "Telash channels a breath attack at a player, inflicting $s1 Frost damage to all players within $a1 yards of the target every $387151t1 sec for $387151d1.", ua = "Телаш скеровує на гравця подих, що спричиняє $s1 морозної шкоди всім гравцям у межах $a1 м від цілі кожні $387151t1 с протягом $387151d1." },
    { en = "The air freezes and protects Telash Greywing, reducing all damage taken by $s1%.", ua = "Повітря замерзає й захищає Телаша Сірокрила, знижуючи всю отримувану ним шкоду на $s1%." },
    { en = "Telash embeds shards of frost in each player that detonates after $386881d1, inflicting $386910s1 Frost damage to players within $386910a2 yards and creating a patch of Frozen Ground.", ua = "Телаш вганяє в кожного гравця уламки криги, що детонують за $386881d1, завдаючи $386910s1 морозної шкоди гравцям у радіусі $386910a2 м і створюючи ділянку Замерзлої землі." },
    { en = "Umbrelskul unleashes a blast of arcane energy, pushing players away and inflicting $s2 Arcane damage.", ua = "Умбрелскул вивільняє вибух арканної енергії, відштовхуючи гравців і завдаючи $s2 арканної шкоди." },
    { en = "Creates a barrier around the crystal that absorbs $s1 damage. While the barrier stands, inflicts $439045s1 Arcane damage every $439045t1 sec.", ua = "Створює навколо кристала бар'єр, що поглинає $s1 шкоди. Доки бар'єр тримається, завдає $439045s1 арканної шкоди кожні $439045t1 с." },
    { en = "Umbrelskul stomps on a player, inflicting $s1 Arcane damage and an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Умбрелскул тупає по гравцю, завдаючи $s1 арканної шкоди й додатково $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "The crystal explodes inflicting $s1 Arcane damage every $t1 sec for $d to all players.", ua = "Кристал вибухає, завдаючи $s1 арканної шкоди кожні $t1 с протягом $d усім гравцям." },
    { en = "The Crackling Vortex inflicts $s1 Arcane damage every $t1 sec to players standing within it.", ua = "Тріскотливий вихор завдає $s1 од. арканної шкоди кожні $t1 с гравцям, що стоять у ньому." },
    { en = "Umbrelskul conjures $@spellname385267es at random locations, inflicting $s1 Arcane damage to players within $a1 yards and knocks them back.", ua = "Умбрелскул прикликає $@spellname385267 у випадкових місцях, спричиняючи $s1 арканної шкоди гравцям у межах $a1 м і відкидаючи їх." },
    { en = "At 75%, 50%, and 25% remaining health Umbrelskul shatters causing $@spellname385530 to fall from his body.", ua = "При 75%, 50% і 25% здоров'я, що лишилось, Умбрелскул розтріскується, і з його тіла відпадають $@spellname385530." },
    { en = "Umbrelskul roars, unleashing a blast of unbridled magic inflicting $s2 Arcane damage to all players in a line in front of himself.", ua = "Умбрелскул реве, вивільняючи сплеск нестримної магії, що завдає $s2 арканної шкоди всім гравцям на лінії перед собою." },
    { en = "Fire at Granyth to stun him for $387155D and inflict $387155S2% of his maximum health as Physical damage.", ua = "Стріляє по Ґраніту, оглушуючи його на $387155D та завдаючи фізичної шкоди в розмірі $387155S2% від його максимального здоров'я." },
    { en = "Granyth expels a number of shards and inflicts $s1 Nature damage to all players within $a1 yards.", ua = "Ґраніт викидає численні уламки й завдає $s1 шкоди від сил природи всім гравцям у радіусі $a1 м." },
    { en = "The Nokhud Saboteur disables a Dragonkiller Lance, preventing it from being able to be fired or reloaded.", ua = "Нохудський диверсант виводить з ладу драконовбивчий спис, не даючи з нього стріляти чи перезаряджати його." },
    { en = "Granyth causes the earth beneath him to erupt, inflicting $385389s1 Nature damage to all players every $t1 sec. Each time this occurs, the damage of subsequent shockwaves is increased.", ua = "Ґраніт спричиняє виверження землі під собою, завдаючи $385389s1 шкоди від сил природи всім гравцям кожні $t1 с. Щоразу, коли це стається, шкода наступних ударних хвиль зростає." },
    { en = "Granyth stomps the ground inflicting $s0 Nature damage to all players within $A yards and knocking them away.", ua = "Ґраніт б'є об землю, завдаючи $s0 шкоди від сил природи всім гравцям у межах $A м і відкидаючи їх." },
    { en = "Granyth causes the earth beneath him to erupt, inflicting $385389s1 Nature damage to all players every $388283t1 sec.", ua = "Ґраніт змушує землю під собою вибухати, завдаючи $385389s1 шкоди від сил природи всім гравцям кожні $388283t1 сек." },
    { en = "The Raging Tempest creates lightning orbs from its own uncontrollable energy. Coming into contact with a lightning orb inflicts $382628s1 Nature damage and grants $382628s2% increased damage and healing for $382628d.\n\n\n\nThis effect stacks.", ua = "Лютий буревій створює блискавичні сфери з власної некерованої енергії. Дотик до блискавичної сфери завдає $382628s1 шкоди від сил природи і дарує $382628s2% підвищеної шкоди та зцілення протягом $382628d.\n\n\n\nЦей ефект накопичується." },
    { en = "The Raging Tempest unleashes a massive Electrical Storm inflicting $384628s1 Nature damage every $t1 sec to all players for $d.", ua = "Лютий буревій вивільняє потужну Електричну Бурю, що завдає $384628s1 шкоди від сил природи кожні $t1 сек усім гравцям протягом $d." },
    { en = "The Raging Tempest experiences an Energy Surge Increasing melee attack speed by $s1% for $d1 and causing melee attacks to inflict an additional $384687s1 Nature damage.", ua = "Лютий буревій зазнає Сплеску Енергії, що підвищує швидкість атак ближнього бою на $s1% протягом $d1 і змушує атаки ближнього бою завдавати додатково $384687s1 шкоди від сил природи." },
    { en = "$@spellname385490 inflicts $386916s1 Nature damage every $386916t1 sec to players standing beneath it.", ua = "$@spellname385490 завдає $386916s1 шкоди від сил природи кожні $386916t1 сек гравцям, що стоять під нею." },
    { en = "The Raging Tempest inflicts $s1% of normal weapon damage as Nature damage to its current target if the player is not in melee range.", ua = "Лютий буревій завдає поточній цілі $s1% звичайної шкоди зброї як шкоди від сил природи, якщо гравець не в зоні ближнього бою." },
    { en = "A massive Lightning Strike that inflicts $s1 Nature damage to all players within $s2 yards.", ua = "Потужний удар блискавки, що завдає $s1 шкоди від сил природи всім гравцям у межах $s2 ярдів." },
    { en = "Any lightning orbs that return to The Raging Tempest cause it to release a Surge of Power, inflicting $s1 Nature damage to all enemies within $a1 yards and increasing The Raging Tempest's damage by $s2% for $d.\n\n\n\nThis effect stacks.", ua = "Кожна куля блискавки, що повертається до Лютого Буревію, змушує його вивільнити Сплеск Сили, завдаючи $s1 шкоди Природи всім ворогам у радіусі $a1 ярдів і підвищуючи шкоду Лютого Буревію на $s2% на $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Lightning Orbs that are struck by a $@spellname384186 will cause an Electrical Overload, destroying the Lightning Orb and inflicting $s1 Nature damage to enemies within $a1 yards.", ua = "Блискавичні Сфери, у які влучає $@spellname384186, спричиняють Електричне Перевантаження, знищуючи Блискавичну Сферу й завдаючи $s1 шкоди від сил природи ворогам у межах $a1 м." },
    { en = "Teera leaps to a nearby location.", ua = "Тіра стрибає в довколишнє місце." },
    { en = "When Teera and Maruuk are more than $392197s1 yards away from each other, they become more aggressive toward their enemies, increasing their damage dealt by $s1% every $392197t1 sec.", ua = "Коли Тіра і Маруук віддаляються одне від одного більш ніж на $392197s1 ярдів, вони стають агресивнішими до ворогів, збільшуючи завдану шкоду на $s1% кожні $392197t1 сек." },
    { en = "Teera channels forceful winds that push players away from Maruuk for $d.", ua = "Тіра насилає шалені вітри, що відштовхують гравців від Маруука протягом $d." },
    { en = "Teera fires a quick arrow at a random player, inflicting $s1 Physical damage.", ua = "Тіра випускає швидку стрілу у випадкового гравця, завдаючи $s1 фізичної шкоди." },
    { en = "At 100 energy, Teera blasts target players with a destructive force of wind, inflicting $s1 Nature damage.\n\n\n\n4 tornadoes drift from the point of impact, inflicting $386037s1 Nature damage and knocking back any player they come into contact with.", ua = "При 100 енергії Тіра вражає позначених гравців руйнівною силою вітру, завдаючи $s1 шкоди від сил природи.\n\n\n\nВід місця влучання розходяться 4 торнадо, що завдають $386037s1 шкоди від сил природи й відкидають будь-якого гравця, якого торкнуться." },
    { en = "Maruuk lets out a terrifying roar, inflicting $s2 Shadow damage to all players within $r yards and fearing them for $d.", ua = "Маруук видає жахливий рев, завдаючи $s2 тіньової шкоди всім гравцям у межах $r ярдів і вселяючи в них страх на $d." },
    { en = "Teera summons a gust of wind that pushes all players away from Maruuk and begins channeling $@spellname384808.", ua = "Тіра прикликає порив вітру, що відштовхує всіх гравців від Маруука, і починає творити $@spellname384808." },
    { en = "The ground continues to quake for $395668d, inflicting $s1 Physical damage to any enemy within $s2 yards every $s3 sec and reducing their movement speed by $395669s1%.", ua = "Земля й далі двигтить упродовж $395668d, завдаючи $s1 фізичної шкоди будь-якому ворогові в межах $s2 ярдів кожні $s3 сек і зменшуючи його швидкість пересування на $395669s1%." },
    { en = "Maruuk inflicts $s1 Physical damage to his current target.", ua = "Маруук завдає $s1 фізичної шкоди своїй поточній цілі." },
    { en = "At 100 energy, Maruuk slams the ground with all his might, causing the earth to split towards target players every $t1 sec for $d.\n\n\n\nThe ground erupts after $382870s2 sec, inflicting $385193s1 Physical damage to all players within 4 yards of each impact.", ua = "При 100 енергії Маруук гатить по землі з усієї сили, через що земля розколюється в напрямку цільових гравців кожні $t1 с протягом $d.\n\n\n\nЗемля вибухає за $382870s2 с, завдаючи $385193s1 фізичної шкоди всім гравцям у радіусі 4 ярдів від кожного влучання." },
    { en = "Balakar throws his spear at a marked player, inflicting $376866s1 Nature damage to players within $376866a1 yards of the impact location. \n\n\n\nUpon impact the spear inflicts $376866s4 Nature damage to all players and pulls them to its location.", ua = "Балакар кидає свого списа в позначеного гравця, спричиняючи $376866s1 шкоди від сил природи гравцям у межах $376866a1 м від місця влучання.\n\n\n\nПісля влучання спис спричиняє $376866s4 шкоди від сил природи всім гравцям і притягує їх до свого місця." },
    { en = "Balakar inflicts $s1 Physical damage to his current target and causes them to bleed for $s2 Physical damage every $t2 sec for $d.\n\n\n\nIncreases damage taken from $@spellname375929 by $s3%.", ua = "Балакар завдає $s1 фізичної шкоди своїй поточній цілі й змушує її кровоточити, завдаючи $s2 фізичної шкоди кожні $t2 с протягом $d.\n\n\n\nЗбільшує шкоду, отриману від $@spellname375929, на $s3%." },
    { en = "Lightning strikes inflict $s1 Nature damage to players within $a1 yards of the impact locations.", ua = "Удари блискавки завдають $s1 шкоди від сил природи гравцям у межах $a1 м від місць влучання." },
    { en = "A crackling cloud that inflicts $s1 Nature damage every $t1 sec to players who stand within it.", ua = "Тріскотлива хмара, що спричиняє $s1 шкоди від сил природи кожні $t1 с гравцям, які стоять усередині." },
    { en = "Balakar flings earth towards a player's location, knocking back players and inflicting $s2 Physical damage.$?diff23[ Causes a $@spellname393421 at each player's location.][]", ua = "Балакар жбурляє землю в місце, де перебуває гравець, відкидаючи гравців і завдаючи $s2 фізичної шкоди.$?diff23[ Спричиняє $@spellname393421 у місці кожного гравця.][]" },
    { en = "Balakar charges towards his spear, inflicting $376685s1 Physical damage to players caught in his path and knocking them away.", ua = "Балакар кидається до свого списа, завдаючи $376685s1 фізичної шкоди гравцям на своєму шляху й відкидаючи їх." },
    { en = "A quake erupts at the target's location, inflicting $393425s1 Nature damage to players within $393425a1 yards.", ua = "У місці цілі вибухає поштовх, завдаючи $393425s1 шкоди від сил природи гравцям у межах $393425a1 ярдів." },
    { en = "The Nokhud Stormcaster flings a storm bolt that inflicts $s1 Nature damage.", ua = "Штормотворець Нохуд жбурляє штормовий розряд, що завдає $s1 шкоди від сил природи." },
    { en = "Balakar inflicts $s1 Physical damage to his current target.", ua = "Балакар завдає $s1 фізичної шкоди своїй поточній цілі." },
    { en = "Balakar throws his spear at a marked player, inflicting $376660s1 Physical damage to players within $376660a1 yards of the impact location and knocking them back.", ua = "Балакар кидає спис у позначеного гравця, завдаючи $376660s1 фізичної шкоди гравцям у радіусі $376660a1 м від місця влучання та відкидаючи їх." },
    { en = "Balakar inflicts $s1 Nature damage to his current target and an additional $s2 Nature damage every $t2 sec for $d.\n\n\n\nIncreases damage taken from $@spellname376829 by $s3%.", ua = "Балакар завдає $s1 шкоди від сил природи поточній цілі та додатково $s2 шкоди від сил природи кожні $t2 с протягом $d.\n\n\n\nЗбільшує шкоду, отриману від $@spellname376829, на $s3%." },
    { en = "Balakar flings charged earth towards a player's location, knocking back players and inflicting $s2 Nature damage.$?diff23[\n\n\n\nAs the explosion occurs, each player inflicts $376896s1 Nature damage to players within $376896a1 yards and leaves behind a $@spellname376899.][]", ua = "Балакар жбурляє заряджену землю на місце гравця, відкидаючи гравців і спричиняючи $s2 шкоди від сил природи.$?diff23[\n\n\n\nПід час вибуху кожен гравець спричиняє $376896s1 шкоди від сил природи гравцям у межах $376896a1 м і лишає по собі $@spellname376899.][]" },
    { en = "Balakar inflicts $s1 Nature damage to his current target.", ua = "Балакар завдає $s1 шкоди від сил природи поточній цілі." },
    { en = "The violent winds radiating from Balakar Khan push all players away and inflict $376732s1 Nature damage every $t1 sec.", ua = "Несамовиті вітри, що випромінює Хан Балакар, відкидають усіх гравців і завдають $376732s1 шкоди від сил природи кожні $t1 с." },
    { en = "$@spellname375286 leaves behind patches of $@spellname377824 for $377824d which inflict $s1 Fire damage every $t1 sec to players within.", ua = "$@spellname375286 лишає по собі плями $@spellname377824 на $377824d, які завдають $s1 вогняної шкоди кожні $t1 сек. гравцям усередині." },
    { en = "Olaf leaps to a fellow's aid and plants his shield. This protects an area and reduces the damage that Lost Dwarves take by $s1% for $369602d.", ua = "Олаф кидається на допомогу побратимові й встромляє свій щит. Це захищає область і знижує шкоду, яку зазнають Загублені дворфи, на $s1% протягом $369602d." },
    { en = "Baelog takes aim and fires an arrow in a straight line, inflicting $s2 Physical damage to players struck and knocking them back.", ua = "Баелог цілиться й випускає стрілу по прямій лінії, завдаючи $s2 фізичної шкоди ураженим гравцям і відкидаючи їх." },
    { en = "Each Lost Dwarf crewing the longboat increases its rate of fire.", ua = "Кожен Загублений дворф у команді човна підвищує темп його стрільби." },
    { en = "Each time the longboat fires its cannons, a blast of flames inflicts $s1 Fire damage to all players.", ua = "Щоразу, коли довгий човен стріляє з гармат, спалах полум'я завдає $s1 вогняної шкоди всім гравцям." },
    { en = "Baelog takes aim and fires an arrow, inflicting $s2 Physical damage and knocking the target back.", ua = "Баелог прицілюється й випускає стрілу, завдаючи $s2 фізичної шкоди й відкидаючи ціль назад." },
    { en = "Olaf hurls his shield at a player, inflicting $s1 Physical damage. The shield ricochets towards up to $x1 players within $s2 yards.", ua = "Олаф жбурляє свій щит у гравця, завдаючи $s1 фізичної шкоди. Щит рикошетить до $x1 гравців у межах $s2 ярдів." },
    { en = "Eric hurls a dagger at a random player, inflicting $s1% of his normal attack damage.", ua = "Ерік метає кинджал у випадкового гравця, завдаючи $s1% своєї звичайної шкоди від атаки." },
    { en = "The dwarven longboat fires its cannons at player locations, knocking back players. Targets struck suffer $s1 Fire damage with an additional $s3 Fire damage every $t3 sec for $d. This effect stacks.", ua = "Дворфський драккар стріляє з гармат по позиціях гравців, відкидаючи їх. Уражені цілі зазнають $s1 вогняної шкоди та додатково $s3 вогняної шкоди кожні $t3 сек. протягом $d. Цей ефект накопичується." },
    { en = "Baelog lashes out with his weapon, inflicting $s1 Physical damage to players within $a1 yards in front of him.", ua = "Баелог замахується зброєю, завдаючи $s1 фізичної шкоди гравцям у межах $a1 ярдів перед собою." },
    { en = "Eric charges to a target's destination, inflicting $369792s1 Physical damage to players within $369792A1 yards and disorienting them for $369792d.", ua = "Ерік кидається до місця цілі, завдаючи $369792s1 фізичної шкоди гравцям у межах $369792A1 ярдів і дезорієнтуючи їх на $369792d." },
    { en = "Leaps to random player's location, ambushing nearby players upon landing: $@spelldesc369696.", ua = "Стрибає в місце випадкового гравця, влаштовуючи засідку на ближніх гравців при приземленні: $@spelldesc369696." },
    { en = "Bromach lets out a bellowing shout, calling upon Stonevault Troggs to join the battle.", ua = "Бромах видає громовий рик, прикликаючи троггів Кам'яного Склепу долучитися до бою." },
    { en = "Bromach slams the ground, inflicting $s1 Nature damage to players within $A1 yards.", ua = "Бромах гатить по землі, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів." },
    { en = "The geomancer causes a spike of stone to jab at the target, inflicting $s1 Nature damage.", ua = "Геомант здіймає кам'яний шпиль, що пронизує ціль, завдаючи $s1 шкоди від сил природи." },
    { en = "The Geomancer strikes an enemy with a lightning bolt that arcs to another nearby enemy, inflicting $s1 Nature damage. The spell affects up to $x1 targets.", ua = "Геомант вражає ворога блискавкою, що перестрибує на іншого ворога поблизу, завдаючи $s1 шкоди від сил природи. Закляття діє на до $x1 цілей." },
    { en = "The totem releases a static shock, inflicting $s1 Nature damage to all players every $369611t1 sec.", ua = "Тотем вивільняє статичний розряд, завдаючи $s1 шкоди від сил природи всім гравцям кожні $369611t1 сек." },
    { en = "Bromach summons a Quaking Totem.", ua = "Бромах прикликає Тотем Тремтіння." },
    { en = "Bromach empowers himself and all Stonevault Troggs, increasing Haste by $s1% for $d.", ua = "Бромах підсилює себе й усіх трогів Кам'яного Склепу, збільшуючи поспіх на $s1% протягом $d." },
    { en = "When slain, the totem causes a large cave-in. This effect stuns all Stonevault Troggs, increasing their damage taken by $s2% for $d.", ua = "Коли тотем знищено, він спричиняє великий обвал. Цей ефект приголомшує всіх троггів Кам'яного Склепу, збільшуючи отримувану ними шкоду на $s2% протягом $d." },
    { en = "Talondras generates energy over time.\n\n\n\nStunning Talondras resets the $@spellname372716, draining all of its energy.  After $s1 sec, the dynamo resets and Talondras casts $@spellname372600 and begins generating energy once more.", ua = "Талондрас із часом накопичує енергію.\n\n\n\nОглушення Талондрас скидає $@spellname372716, виснажуючи всю її енергію. За $s1 с динамо скидається, Талондрас творить $@spellname372600 і знову починає накопичувати енергію." },
    { en = "Talondras heaves a blast of jagged stones at the target, inflicting $s1 Physical damage and causing the target to bleed for an additional $s2 Physical damage every $t2 sec for $d.", ua = "Талондрас жбурляє в ціль град гострих каменів, завдаючи $s1 фізичної шкоди й змушуючи ціль стікати кров'ю, що додатково завдає $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Talondras activates up to $372623s1 titan orbs. Any player or monster touching one of these orbs becomes stunned for $d.", ua = "Талондрас активує до $372623s1 титанічних сфер. Будь-який гравець чи монстр, який торкнеться однієї з цих сфер, буде приголомшений на $d." },
    { en = "Upon reaching 100 energy Talondras becomes unstoppable, making her immune to all crowd control abilities and increasing her damage done by $s4% for $d.", ua = "Сягнувши 100 енергії, Талондрас стає нестримною: вона несприйнятлива до всіх ефектів контролю, а завдавана нею шкода зростає на $s4% протягом $d." },
    { en = "Talondras's defenses are hardened, making her immune to the next $n Stun effects.", ua = "Захист Талондрас загартовується, роблячи її несприйнятливою до наступних $n ефектів оглушення." },
    { en = "Whenever Talondras recovers from being stunned or casts $@spellname372719, she gains $s1% additional damage done for the rest of the battle. This effect stacks.", ua = "Щоразу, коли Талондрас оговтується від оглушення або застосовує $@spellname372719, вона дістає $s1% додаткової завданої шкоди до кінця бою. Цей ефект накопичується." },
    { en = "Talondras unleashes a wave of energy that inflicts $s1 Physical damage to all players and knocks them away.", ua = "Талондрас вивільняє хвилю енергії, що завдає $s1 фізичної шкоди всім гравцям і відкидає їх." },
    { en = "While channeling Purging Flames, Emberon releases a wave of fire every $368990t2 sec, inflicting $s1 Fire damage to all players.", ua = "Спрямовуючи Очисне полум'я, Емберон вивільняє хвилю вогню кожні $368990t2 сек, завдаючи $s1 вогняної шкоди всім гравцям." },
    { en = "Players entering the Sacred Barrier suffer $s1 Fire damage and are knocked back.", ua = "Гравці, що заходять у Священний бар'єр, зазнають $s1 вогняної шкоди й відкидаються назад." },
    { en = "Emberon channels intense flames to purge intruders. Beams of fire rotate around the vault, inflicting $368996s1 Fire damage to any player caught.", ua = "Емберон скеровує несамовите полум'я, щоб винищити зайд. Промені вогню обертаються довкола сховища, завдаючи $368996s1 вогняної шкоди будь-якому гравцеві, якого зачепить." },
    { en = "A sacred barrier of flames surrounds Emberon, making it immune to damage taken while $@spellname368990 is in effect.", ua = "Священний бар'єр полум'я оточує Емберона, роблячи його несприйнятливим до отримуваної шкоди, доки діє $@spellname368990." },
    { en = "Emberon claps its hands, inflicting $s1 Fire damage to all players in front of itself.\n\n\n\nEach $@spellname369061 causes $@spellname369006 on all players.", ua = "Емберон плескає в долоні, завдаючи $s1 вогняної шкоди всім гравцям перед собою.\n\n\n\nКожен $@spellname369061 накладає $@spellname369006 на всіх гравців." },
    { en = "Emberon activates $i dormant Vault Keepers to provide it power.", ua = "Емберон активує $i бездіяльних хранителів сховища, щоб наснажити себе силою." },
    { en = "Emberon heats up, inflicting $s1 Fire damage to all players every $t1 sec for $d.", ua = "Емберон розжарюється, завдаючи $s1 вогняної шкоди всім гравцям кожні $t1 сек упродовж $d." },
    { en = "Emberon causes $@spellname369110 to form around random players for $d. Upon expiration, these embers erupt and inflict $369116s1 Fire damage to all players within $369116A1 yards.", ua = "Емберон спричиняє появу $@spellname369110 навколо випадкових гравців на $d. Після завершення ці жарини вибухають і завдають $369116s1 вогняної шкоди всім гравцям у межах $369116A1 ярдів." },
    { en = "Activated keepers periodically launch balls of fire at random players. If they strike a player, the orbs explode and inflict $s1 Fire damage to that target.", ua = "Активовані хранителі періодично запускають вогняні кулі в випадкових гравців. Якщо вони влучають у гравця, кулі вибухають і завдають цій цілі $s1 вогняної шкоди." },
    { en = "Emberon channels intense flames to purge intruders. Beams of fire rotate around the vault, inflicting $368996s1 Fire damage to any player caught.\n\n\n\nThese beams persist until all active Vault Keepers are defeated.", ua = "Емберон спрямовує потужне полум'я, щоб винищити зловмисників. Промені вогню обертаються довкола сховища, завдаючи $368996s1 вогняної шкоди будь-якому захопленому гравцеві.\n\n\n\nЦі промені тривають, доки не буде здолано всіх активних хранителів сховища." },
    { en = "Chrono-Lord Deios drains the time away from players caught within an $@spellname376325, inflicting $s1 Arcane damage every $t1 sec and reducing their haste by $s2%.", ua = "Хроно-Лорд Дейос виснажує час гравців, що потрапили в $@spellname376325, завдаючи $s1 арканної шкоди кожні $t1 с та зменшуючи їхній поспіх на $s2%." },
    { en = "While time is being reversed, a $@spellname376329 will float upwards, back towards its point of creation.", ua = "Поки час тече назад, $@spellname376329 здіймається вгору, назад до місця свого виникнення." },
    { en = "While time is being reversed, a $@spellname376333 will funnel lost time back into players, increasing their haste by $s1%.", ua = "Поки час тече назад, $@spellname376333 повертає втрачений час гравцям, збільшуючи їхній поспіх на $s1%." },
    { en = "Chrono-Lord Deios breathes out time-altering sand, inflicting $s1 Arcane damage to players in front of him.", ua = "Хроно-Лорд Дейос видихає пісок, що змінює час, завдаючи $s1 арканної шкоди гравцям перед собою." },
    { en = "While time is being reversed, lost time will funnel back into players, increasing their haste by $376333s1%.", ua = "Поки час обертається назад, втрачений час повертається до гравців, збільшуючи їхній поспіх на $376333s1%." },
    { en = "Chrono-Lord Deios reverses the flow of time, restoring his own temporal energy while inflicting $s1 Arcane damage to players every $376208t1 sec for $376208d. \n\n\n\nWhile this is in effect, Eternity Orbs and Zones revert to Temporal Orbs and Zones.", ua = "Хроно-Лорд Дейос обертає плин часу назад, відновлюючи власну часову енергію та завдаючи гравцям $s1 арканної шкоди кожні $376208t1 с протягом $376208d. \n\n\n\nПоки цей ефект діє, вічні кулі та зони повертаються до часових куль і зон." },
    { en = "Chrono-Lord Deios reverses the flow of time, restoring his own temporal energy while inflicting $376209s1 Arcane damage to players every $376208t1 sec for $376208d. \n\n\n\nWhile this is in effect, players gain the effect of $@spellname455344.", ua = "Хроно-Лорд Дейос обертає плин часу назад, відновлюючи власну часову енергію й завдаючи гравцям $376209s1 арканної шкоди щосекунди впродовж $376208t1 на $376208d. \n\n\n\nПоки діє цей ефект, гравці отримують дію $@spellname455344." },
    { en = "Chrono-Lord Deios flaps his wings, inflicting $s1 Arcane damage to all players and knocking them back.", ua = "Хроно-Лорд Дейос змахує крилами, завдаючи $s1 арканної шкоди всім гравцям і відкидаючи їх назад." },
    { en = "An eruption of excess time inflicts $s1 Arcane damage to players within $A1 yards and knocks them back.", ua = "Виверження надлишкового часу завдає $s1 арканної шкоди гравцям у межах $A1 м і відкидає їх." },
    { en = "Time is ripped away from the target, inflicting $s2 Arcane damage every $t2 sec and reducing movement speed by $s1% for $d. Upon removal, triggers a $@spellname377561.", ua = "У цілі відбирають час, завдаючи $s2 арканної шкоди щомиті $t2 сек і знижуючи швидкість пересування на $s1% протягом $d. Після зняття спричиняє $@spellname377561." },
    { en = "Chrono-Lord Deios calls forth an eternal orb made of sand, which falls from above. When it strikes the ground, it inflicts $s1 Arcane damage to all players and forms an $@spellname376325.", ua = "Хроно-Лорд Дейос викликає вічну кулю з піску, що падає згори. Вдарившись об землю, вона завдає $s1 арканної шкоди всім гравцям і утворює $@spellname376325." },
    { en = "On emergence, $@spellname412944 inflicts $s1 Arcane damage to players within $s2 yards.\n\n\n\nThe pool inflicts $401794s1 Arcane damage every $401794t1 sec to players who remain inside of it, reducing their movement speed by $401794s2% and their haste by $401794s3%.", ua = "При появі $@spellname412944 завдає $s1 арканної шкоди гравцям у межах $s2 ярдів.\n\n\n\nКалюжа завдає $401794s1 арканної шкоди кожні $401794t1 сек гравцям, які лишаються в ній, зменшуючи їхню швидкість пересування на $401794s2% та поспіх на $401794s3%." },
    { en = "$@spellname403486 explodes, inflicting $s1 Arcane damage to all players and an additional $s2 Arcane damage every $t2 sec for $d.", ua = "$@spellname403486 вибухає, завдаючи $s1 арканної шкоди всім гравцям, а також додатково $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Chronikar stomps the ground, manifesting a $@spellname401794 under marked players.", ua = "Хронікар тупає об землю, проявляючи $@spellname401794 під позначеними гравцями." },
    { en = "Chronikar leaps and slams down onto the location of a player, inflicting $403088s1 Arcane damage to players within $403088A1 yards of the impact.\n\n\n\nThe resulting explosion creates $@spellname405970$?diff2[.][ and $@spellname403486.]", ua = "Хронікар стрибає та обрушується на місце розташування гравця, завдаючи $403088s1 арканної шкоди гравцям у межах $403088A1 м від місця влучання.\n\n\n\nВибух, що утворюється, створює $@spellname405970$?diff2[.][ та $@spellname403486.]" },
    { en = "Timespace fragments explode outward, inflicting $s1 Arcane damage to players hit and knocking them back.", ua = "Уламки просторочасу вибухають назовні, завдаючи $s1 арканної шкоди влученим гравцям та відкидаючи їх." },
    { en = "Instability in the target's timeline weakens their lifespan, increasing their damage taken by $s1% for $s2 sec.\n\n\n\nThis effect cannot be dispelled if the target is afflicted by $@spellname413013.", ua = "Нестабільність часової лінії цілі послаблює тривалість її життя, збільшуючи отримувану нею шкоду на $s1% протягом $s2 с.\n\n\n\nЦей ефект не можна розвіяти, якщо ціль уражена $@spellname413013." },
    { en = "Chronikar strikes her target with a mighty axe swing, inflicting $s1 Physical damage and knocking them away. This cannot be dodged or parried.\n\n\n\nHer axe twists the target's timeline, causing them to absorb $s2 healing$?diff2[.][ and applying $@spellname413041. While afflicted by $@spellname413013, the target is undispellable.]", ua = "Хронікар б'є ціль могутнім замахом сокири, завдаючи $s1 фізичної шкоди й відкидаючи її. Від цього удару не можна ні ухилитися, ні парирувати його.\n\n\n\nЇї сокира викривлює часову лінію цілі, через що та поглинає $s2 зцілення$?diff2[.][ і накладає $@spellname413041. Поки на ціль діє $@spellname413013, її неможливо розвіяти.]" },
    { en = "Harmful energy surges into players within $A1 yards of the residue's impact, inflicting $s1 Arcane damage.\n\n\n\n$@spellname403486 explodes in a $@spellname403259 if it fails to hit a player.", ua = "Згубна енергія вривається в гравців у радіусі $A1 м від місця влучання залишку, завдаючи $s1 арканної шкоди.\n\n\n\n$@spellname403486 вибухає як $@spellname403259, якщо не влучає в гравця." },
    { en = "Radiates time magic when her current target is not within melee range, inflicting $198520s1 Arcane damage, increasing in damage by $198520s2% per cast.", ua = "Випромінює магію часу, коли поточна ціль перебуває поза досяжністю ближнього бою, завдаючи $198520s1 арканної шкоди, що зростає на $198520s2% за кожне творіння." },
    { en = "Decays afflicted targets connection to time, inflicting $405672s1 Arcane damage every $403910T1 sec. and additionally reduces damage taken by $403910s2%.", ua = "Руйнує зв'язок уражених цілей із часом, завдаючи $405672s1 арканної шкоди кожні $403910T1 с і додатково зменшуючи отримувану шкоду на $403910s2%." },
    { en = "Expedites afflicted targets connection to time, inflicting $405671s1 Arcane damage every $403912T1 sec. and additionally increases movement speed by $403912s2%.", ua = "Прискорює зв'язок уражених цілей із часом, завдаючи $405671s1 арканної шкоди кожні $403912T1 с і додатково збільшуючи швидкість пересування на $403912s2%." },
    { en = "Releases a ripple of bronze magic inflicting $405448s1 Arcane damage every half-second while in contact with the wave. This wave travels extraordinarily slow if the originating player was afflicted with $@spellname403910.", ua = "Випускає брижі бронзової магії, що завдають $405448s1 од. арканної шкоди кожні півсекунди тим, хто торкається хвилі. Ця хвиля рухається надзвичайно повільно, якщо гравець, від якого вона походить, був уражений $@spellname403910." },
    { en = "Destabilizes targeted players, inflicting $405478s2 Arcane damage every ${$404141T1*$404141s1} sec. for $404141D. The frequency of this effect is increased to $404141T1 sec while under the effects of $@spellname403912.\n\n\n\nUpon removal this releases |5 $@spellname405448.", ua = "Дестабілізує цілей-гравців, завдаючи $405478s2 арканної шкоди кожні ${$404141T1*$404141s1} с на $404141D. Частота цього ефекту зростає до $404141T1 с, поки ціль перебуває під дією $@spellname403912.\n\n\n\nПісля зняття вивільняє |5 $@spellname405448." },
    { en = "Draws from the future and past for $405431D, emitting pockets of time which radiate outwards, inflicting $404650s1 Arcane damage upon contact and an additional $404650s2 Arcane damage every $404650T2 sec for $404650D. This effect stacks.\n\n\n\nThese pockets of time travel slower while inside $@spellname403910.", ua = "Черпає з майбутнього та минулого протягом $405431D, випускаючи часові згустки, що розходяться назовні й завдають $404650s1 арканної шкоди при дотику та додатково $404650s2 арканної шкоди кожні $404650T2 с протягом $404650D. Цей ефект накопичується.\n\n\n\nУсередині $@spellname403910 ці часові згустки рухаються повільніше." },
    { en = "Blight of Galakrond blasts a player with corrosive energy, applying $@spellname406891 and causing a $@spellname407027.", ua = "Зараза Ґалакронда б'є гравця їдкою енергією, накладаючи $@spellname406891 і спричиняючи $@spellname407027." },
    { en = "At $415576s2% health, Blight of Galakrond separates its power between Loszkeleth and Dazhak, causing 100% of the damage done against one to occur to the other.", ua = "При $415576s2% здоров'я Зараза Ґалакронда розділяє свою силу між Лоскелетом і Дажаком, унаслідок чого 100% шкоди, завданої одному, отримує й інший." },
    { en = "Ahnzon radiates power, inflicting $415254s1 Nature damage every $415259t1 sec for $d and pushing players away.\n\n\n\nWhile radiating, tornadoes blow outward, inflicting $408008s1 Nature damage upon contact with players and knocking them away.", ua = "Анзон випромінює силу, завдаючи $415254s1 шкоди від сил природи кожні $415259t1 сек упродовж $d і відштовхуючи гравців.\n\n\n\nПід час випромінювання назовні розлітаються торнадо, що завдають $408008s1 шкоди від сил природи при дотику до гравців і відкидають їх." },
    { en = "If $@spellname407406 afflicts a player for its full duration, the player is consumed by blight.\n\n\n\nTheir mind becomes corrupted, turning them against their allies for $d.", ua = "Якщо $@spellname407406 вражає гравця всю свою тривалість, гравця поглинає зараза.\n\n\n\nЙого розум скверниться, обертаючи його проти союзників протягом $d." },
    { en = "Dazhak breathes necrotic flames, inflicting $408177s1 Fire damage every $408177t1 sec for $d to players in front of her.", ua = "Дажак видихає некротичне полум'я, завдаючи $408177s1 вогняної шкоди щомиті $408177t1 сек протягом $d гравцям перед собою." },
    { en = "Blight corrodes a player, inflicting $407714s1 Nature damage on impact and an additional $407413s1 Nature damage every $t1 sec$?diff23|diff8[ for $d.\n\n\n\nUpon expiration, $@spellname407406 causes $@spellname418346.\n\n\n\n$@spellname407406 transfers to another player on contact. $@spellname407159 consumes this affliction.][.\n\n\n\n$@spellname407406 transfers to another player on contact. $@spellname407159 consumes this affliction.]", ua = "Зараза роз'їдає гравця, завдаючи $407714s1 шкоди від сил природи при влучанні та додатково $407413s1 шкоди від сил природи кожні $t1 с$?diff23|diff8[ протягом $d.\n\n\n\nПісля закінчення $@spellname407406 спричиняє $@spellname418346.\n\n\n\n$@spellname407406 передається іншому гравцеві при дотику. $@spellname407159 поглинає цю недугу.][.\n\n\n\n$@spellname407406 передається іншому гравцеві при дотику. $@spellname407159 поглинає цю недугу.]" },
    { en = "Toxic corruption oozes from Blight of Galakrond, draining its energy and inflicting $407147s1 Nature damage every $407147t1 sec to players within the resulting blight pools.", ua = "Із Зарази Ґалакронда сочиться токсична скверна, що виснажує її енергію та завдає $407147s1 шкоди від сил природи кожні $407147t1 с гравцям у калюжах зарази, що утворюються." },
    { en = "Blight of Galakrond ejects a volley of ooze, inflicting $s1 Nature damage to players within $A1 yards of the impact and stunning them for $d.", ua = "Зараза Ґалакронда викидає залп слизу, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 м від місця влучання та оглушуючи їх на $d." },
    { en = "Dazhak spits blight at players, inflicting $s1 Nature damage.", ua = "Дажак плює заразою в гравців, завдаючи $s1 шкоди від сил природи." },
    { en = "Blight of Galakrond reclaims blight particles to re-energize, inflicting $s1 Physical damage to players in a frontal cone and pulling them inward. This effect removes $@spellname406891.", ua = "Зараза Ґалакронда повертає собі частинки зарази, щоб відновити сили, завдаючи $s1 фізичної шкоди гравцям у фронтальному конусі й притягуючи їх до себе. Цей ефект знімає $@spellname406891." },
    { en = "Loszkeleth immobilizes a player with necrotic frost, reducing their haste by $408044s2% and inflicting $415448s1 Frost damage every $408084t1 sec until the $@spellname408029 is destroyed.", ua = "Лосзкелет знерухомлює гравця некротичним морозом, знижуючи його поспіх на $408044s2% і завдаючи $415448s1 морозної шкоди щомиті $408084t1 сек, доки $@spellname408029 не буде знищено." },
    { en = "With a burst of renewed tenacity, Chromie increases the haste of players by $s1% for $d.", ua = "Сплеском відновленої завзятості Хромі підвищує поспіх гравців на $s1% протягом $d." },
    { en = "A jagged rock inflicts $416257s1 Nature damage and bleeds a player for $412285s1 Physical damage every $412285t1 sec for $412285d. This effect stacks.", ua = "Зазубрений камінь завдає $416257s1 шкоди від сил природи й пускає гравцеві кров на $412285s1 фізичної шкоди щомиті $412285t1 сек протягом $412285d. Цей ефект накопичується." },
    { en = "Iridikron slams his wings against the ground as he unleashes a monstrous breath of stone, inflicting $409642s1 Nature damage to players in a frontal cone and underneath him within $409667s1 yards.$?diff23|diff8[\n\n\n\nAdditionally, this causes $@spellname409884 to erupt under marked players.][]", ua = "Іридикрон б'є крилами об землю, вивільняючи жахливий кам'яний подих, що спричиняє $409642s1 шкоди від сил природи гравцям у конусі перед собою та під собою в межах $409667s1 м.$?diff23|diff8[\n\n\n\nКрім того, це змушує $@spellname409884 вибухати під позначеними гравцями.][]" },
    { en = "Iridikron blasts Chromie with a barrage of rocks for $d.\n\n\n\nEach rock inflicts $414583s1 Nature damage within $414583A1 yards, split amongst Chromie and any players hit.$?diff23|diff8[\n\n\n\nIf a player fails to intercept a rock prior to impact, it causes $@spellname414552. Intercepted rocks inflict $414604s1 Physical damage.][]", ua = "Іридикрон закидає Хромі градом каменів протягом $d.\n\n\n\nКожен камінь завдає $414583s1 шкоди від сил природи в радіусі $414583A1 ярдів, розподіленої між Хромі та враженими гравцями.$?diff23|diff8[\n\n\n\nЯкщо гравець не перехоплює камінь до удару, той спричиняє $@spellname414552. Перехоплені камені завдають $414604s1 фізичної шкоди.][]" },
    { en = "$@spellname409456 emits waves of spikes that inflict $s1 Nature damage to players upon contact, knocking them away.$?diff23|diff8|diff2[ Each spike leaves behind $@spellname414376.][]", ua = "$@spellname409456 випускає хвилі шипів, що завдають $s1 шкоди від сил природи гравцям при дотику й відкидають їх.$?diff23|diff8|diff2[ Кожен шип лишає по собі $@spellname414376.][]" },
    { en = "Volatile earthen energy inflicts $s1 Nature damage every $t1 sec to players within it.", ua = "Нестабільна земляна енергія завдає $s1 шкоди від сил природи кожні $t1 с гравцям усередині неї." },
    { en = "Iridikron unleashes a cataclysmic blast that inflicts $414205s1 Nature damage to all players. This damage cannot be avoided.\n\n\n\nWhile readying his attack, he inflicts $414483s1 Nature damage to all players every $414482t1 sec.\n\n\n\nIridikron loses energy upon taking damage, failing this ability if he reaches 0 energy. Chromie casts $@spellname414293 to assist her allies.", ua = "Іридикрон вивільняє катаклізмічний вибух, що завдає $414205s1 шкоди від сил природи всім гравцям. Цієї шкоди не уникнути.\n\n\n\nГотуючи свою атаку, він завдає $414483s1 шкоди від сил природи всім гравцям щомиті $414482t1 сек.\n\n\n\nІридикрон втрачає енергію, отримуючи шкоду, і ця здібність провалюється, якщо його енергія сягне 0. Хромі творить $@spellname414293, щоб допомогти своїм союзникам." },
    { en = "Iridikron targets a player with a devastating earth blast, inflicting $409268s1 Nature damage to players within $409268A1 yards and an additional $414300s1 Nature damage every $414300t1 sec for $414300d.\n\n\n\nChromie's $@spellname414330 reduces damage from this ability.", ua = "Іридикрон націлюється на гравця нищівним вибухом землі, завдаючи $409268s1 шкоди від сил природи гравцям у радіусі $409268A1 ярдів і додатково $414300s1 шкоди від сил природи кожні $414300t1 сек протягом $414300d.\n\n\n\n$@spellname414330 Хромі знижує шкоду від цієї здібності." },
    { en = "With a strategy designed to wear down Chromie and her allies, Iridikron patiently builds energy as his foes attack him.\n\n\n\nAt 100 energy, he unleashes $@spellname414184 in an attempt to overwhelm his wearied opponents.", ua = "За стратегією, покликаною виснажити Хромі та її союзників, Іридикрон терпляче накопичує енергію, поки вороги його атакують.\n\n\n\nПри 100 енергії він вивільняє $@spellname414184, прагнучи здолати своїх знесилених супротивників." },
    { en = "Iridikron shields himself with a protective earthen barrier that absorbs $410719s1 damage. While the shield holds, he pulses tectonic energy every $t1 sec, causing $@spellname409287 to erupt outward.\n\n\n\nEach pulse inflicts $409584s1 Nature damage to all players$?diff23|diff8[][.]", ua = "Іридикрон захищає себе земляним бар'єром, що поглинає $410719s1 шкоди. Поки щит тримається, він кожні $t1 с випромінює тектонічну енергію, через що назовні виривається $@spellname409287.\n\n\n\nКожен імпульс завдає $409584s1 шкоди від сил природи всім гравцям$?diff23|diff8[][.]" },
    { en = "Chromie takes an additional $s1% damage.\n\n\n\nIf protected from $@spellname414535, she overcomes her exhaustion and casts $@spellname414496.", ua = "Хромі отримує на $s1% більше шкоди.\n\n\n\nЯкщо її захистити від $@spellname414535, вона долає своє виснаження і творить $@spellname414496." },
    { en = "Chromie generates a time distortion bubble, granting players their future maximum potential.\n\n\n\nIncreases damage done by $414178s1%, haste by $414178s2%, cooldown rate by $414178s3%, and resource regeneration rate by $414178s4%.\n\n\n\nChromie can only do this once without risking permanent timeline convergence.", ua = "Хромі створює бульбашку викривлення часу, надаючи гравцям їхній майбутній максимальний потенціал.\n\n\n\nПідвищує завдану шкоду на $414178s1%, поспіх на $414178s2%, темп перезарядження на $414178s3% і темп відновлення ресурсів на $414178s4%.\n\n\n\nХромі може зробити це лише раз, не ризикуючи остаточним сходженням часових ліній." },
    { en = "Chromie and all players in the blast zone bleed for $414552s1 Physical damage every $414552t1 sec for $414552d. This effect stacks.", ua = "Хромі та всі гравці в зоні вибуху кровоточать, зазнаючи $414552s1 фізичної шкоди кожні $414552t1 сек протягом $414552d. Цей ефект накопичується." },
    { en = "Chromie creates an expanded time bubble, reducing damage to players within it by $414333s1% for $d.\n\n\n\nWhen $@spellname414330 ends, Chromie is $@spellname414353.", ua = "Хромі створює розширену часову бульбашку, знижуючи шкоду для гравців усередині неї на $414333s1% протягом $d.\n\n\n\nКоли $@spellname414330 завершується, Хромі стає $@spellname414353." },
    { en = "Iridikron's successful melee attacks pulverize his target, increasing Physical damage taken by $409558s1% for $409558d. This effect stacks.", ua = "Успішні удари Іридикрона в ближньому бою трощать ціль, посилюючи отримувану нею фізичну шкоду на $409558s1% на $409558d. Цей ефект накопичується." },
    { en = "Iridikron's stone creations immediately inflict $s2 Nature damage to players within $A2 yards.", ua = "Кам'яні витвори Іридикрона миттєво завдають $s2 шкоди від сил природи гравцям у радіусі $A2 ярдів." },
    { en = "Tyr musters his titanic strength to strike his target, inflicting $417339m1 Physical damage and knocking back players in a cone in front of him$?diff2[.][, and leaving behind $@spellname400643.]", ua = "Тір збирає всю свою титанічну силу для удару по цілі, завдаючи $417339m1 фізичної шкоди й відкидаючи гравців у конусі перед собою$?diff2[.][ та лишаючи по собі $@spellname400643.]" },
    { en = "Tyr smashes the ground with overwhelming force, inflicting $m1 Arcane damage split evenly among players within $A1 yards and leaving behind $@spellname400643.\n\n\n\nIf Dividing Strike fails to hit at least 2 players, Tyr gains $@spellname408183.", ua = "Тір б'є по землі нездоланною силою, завдаючи $m1 арканної шкоди, рівномірно розподіленої між гравцями в межах $A1 м, і лишаючи по собі $@spellname400643.\n\n\n\nЯкщо Розділовий Удар не влучає щонайменше у 2 гравців, Тір дістає $@spellname408183." },
    { en = "When Tyr's energy is expended, he siphons power from the Infinite Oathstone and shields himself with $@spellname410249.\n\n\n\nThis act destabilizes the Oathstone, causing it to release $@spellname404315.", ua = "Коли Тірова енергія вичерпується, він висмоктує силу з Нескінченного Каменя Клятви й захищається $@spellname410249.\n\n\n\nЦя дія дестабілізує Камінь Клятви, через що він вивільняє $@spellname404315." },
    { en = "Tyr harnesses the power of the infinite, increasing all damage done by $s1% for the remainder of the fight. This effect stacks.", ua = "Тір опановує силу нескінченності, збільшуючи всю завдану шкоду на $s1% до кінця бою. Цей ефект накопичується." },
    { en = "Tyr expends energy to unleash a deadly combination of attacks with his mace, The Infinite Hand.", ua = "Тір витрачає енергію, щоб вивільнити смертоносну послідовність ударів своєю булавою — Нескінченною Дланню." },
    { en = "Tyr haunts up to $400649I players with memories not yet written, inflicting $400680M1 Arcane damage every $T1 sec to players within $400680a1 yards.\n\n\n\nUpon expiration or removal, inflicts $400683M1 Arcane damage to all players.", ua = "Тір переслідує до $400649I гравців ще не написаними спогадами, завдаючи $400680M1 арканної шкоди кожні $T1 с гравцям у межах $400680a1 м.\n\n\n\nПісля закінчення чи зняття завдає $400683M1 арканної шкоди всім гравцям." },
    { en = "Tyr shields himself with Infinite magic, absorbing $M1 damage.\n\n\n\nWhen $@spellname410249 activates or is refreshed, it inflicts $414493M1 damage to all enemies and pushes them back.", ua = "Тір захищає себе нескінченною магією, поглинаючи $M1 шкоди.\n\n\n\nКоли $@spellname410249 спрацьовує або поновлюється, завдає $414493M1 шкоди всім ворогам і відкидає їх назад." },
    { en = "Inflicts $M1 Arcane damage every $T1 sec.", ua = "Завдає $M1 арканної шкоди кожні $T1 с." },
    { en = "Increases haste and movement speed by $M2% for $D. This effect stacks up to $U times.", ua = "Збільшує поспіх і швидкість пересування на $M2% протягом $D. Цей ефект накопичується до $U разів." },
    { en = "Tyr faces a random player and slams the ground, inflicting $m1 Arcane damage to players in a cone in front of him$?diff2[.][ and leaving behind $@spellname400643.]", ua = "Тір повертається до випадкового гравця й б'є об землю, спричиняючи $m1 арканної шкоди гравцям у конусі перед собою$?diff2[.][ й лишаючи по собі $@spellname400643.]" },
    { en = "The siphoned Oathstone releases motes of temporal essence that slowly return to it. Any that reach the Oathstone are absorbed by Tyr, increasing the absorption of $@spellname410249.\n\n\n\nPlayers can collect temporal essence to gain $@spellname406543.", ua = "Висмоктаний Камінь Клятви вивільняє часточки часової есенції, що повільно повертаються до нього. Усі, що сягають Каменя Клятви, поглинаються Тіром, посилюючи поглинання $@spellname410249.\n\n\n\nГравці можуть збирати часову есенцію, щоб дістати $@spellname406543." },
    { en = "Inflicts $412769s1 Arcane damage to players within $412769A1 yards every $t1 sec.", ua = "Завдає $412769s1 арканної шкоди гравцям у межах $412769A1 ярдів кожні $t1 с." },
    { en = "Morchie transforms into her infinite dragon form and unleashes a breath attack, inflicting $s1 Arcane damage to players in front of her and causing them to become $@spellname413208.", ua = "Морчі перетворюється на свою форму нескінченного дракона і випускає атаку диханням, завдаючи $s1 арканної шкоди гравцям перед собою та накладаючи на них $@spellname413208." },
    { en = "Fixates their current timeline self.", ua = "Зосереджується на собі з поточної часової лінії." },
    { en = "Morchie creates traps at random locations that trigger on contact with Players or Familiar Faces.", ua = "Морчі створює пастки в довільних місцях, які спрацьовують при контакті з гравцями або Знайомими Обличчями." },
    { en = "Morchie summons alternate versions of herself from other timelines and hides herself among them.", ua = "Морчі прикликає альтернативні версії себе з інших часових ліній і ховається серед них." },
    { en = "Morchie fires a sand projectile that inflicts $s1 Physical damage to players in a line in front of her.", ua = "Морчі стріляє піщаним снарядом, що завдає $s1 фізичної шкоди гравцям на лінії перед нею." },
    { en = "The Time Trap explodes when triggered, inflicting $s1 Arcane damage to all players and an additional $s2 Arcane damage every $t2 for $d.", ua = "Часова Пастка вибухає, коли її активують, завдаючи $s1 арканної шкоди всім гравцям і додатково $s2 арканної шкоди кожні $t2 протягом $d." },
    { en = "Sand remnants from Morchie's $@spellname404365 linger, inflicting $s1 Nature damage every $t1 sec.", ua = "Залишки піску від закляття $@spellname404365 Морчі продовжують діяти, завдаючи $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Morchie summons minions from her timeline to aid the fight.", ua = "Морчі прикликає прислужників зі своєї часової лінії на допомогу в бою." },
    { en = "Screams with a terrifying sound, inflicting $s1 Nature damage to all enemies.", ua = "Кричить жахливим звуком, завдаючи $s1 шкоди від сил природи всім ворогам." },
    { en = "Reduces the effectiveness of any healing effects received by $410497s1% for $410497D.", ua = "Знижує дієвість усіх отриманих ефектів зцілення на $410497s1% на $410497D." },
    { en = "Grommash slams Gorehowl into the ground multiple times in quick succession, inflicting $408228s2 Nature  damage in a frontal cone.", ua = "Ґроммаш кілька разів поспіль із швидкою послідовністю врізає Кривавим Зойком об землю, завдаючи $408228s2 шкоди від сил природи в передньому конусі." },
    { en = "Swings twice with deadly accuracy, inflicting $410258s1 Physical damage each time, applying $@spellname410497. This attack cannot be blocked, dodged, or parried.", ua = "Завдає двох ударів зі смертоносною точністю, щоразу завдаючи $410258s1 фізичної шкоди й накладаючи $@spellname410497. Цю атаку неможливо заблокувати, ухилитися від неї чи парирувати." },
    { en = "Hurls a well-honed blade at an enemy, inflicting $s1 Physical damage and additionally bleeds the target, inflicting $s2 Physical damage every $T2 sec for $D.", ua = "Метає добре загострений клинок у ворога, завдаючи $s1 фізичної шкоди та додатково спричиняючи кровотечу, що завдає цілі $s2 фізичної шкоди кожні $T2 с протягом $D." },
    { en = "Burns an enemy, inflicting $s1 Fire damage and an additional $s2 Fire damage every $T2 sec for $D.", ua = "Спалює ворога, завдаючи $s1 вогняної шкоди і додатково $s2 вогняної шкоди кожні $T2 сек протягом $D." },
    { en = "Throws an axe at an enemy, inflicting $s1 Physical damage.", ua = "Кидає сокиру у ворога, завдаючи $s1 фізичної шкоди." },
    { en = "Calls down a rain of hellfire for $D, dealing $407123s1 Fire damage every $407123T2 sec to enemies in the area.", ua = "Призиває дощ пекельного вогню протягом $D, завдаючи $407123s1 вогняної шкоди кожні $407123T2 сек ворогам у зоні." },
    { en = "Upon killing an enemy, Grommash gains Thirst for Battle. This effect stacks.\n\n\n\nSuccessful melee attacks sate his thirst, consuming a stack and inflicting $419604s1 Nature damage to all players.", ua = "Убивши ворога, Ґроммаш отримує «Жагу бою». Цей ефект накопичується.\n\n\n\nВдалі удари в ближньому бою тамують його жагу, витрачаючи заряд і завдаючи $419604s1 шкоди від сил природи всім гравцям." },
    { en = "Leaps at a player swinging wildly at nearby enemies for $410236D, inflicting $410238s1 Physical damage every $410236T1 sec to enemies within $410238A1 yards.", ua = "Стрибає до гравця й шалено рубає ворогів поблизу протягом $410236D, завдаючи $410238s1 фізичної шкоди щомиті $410236T1 сек ворогам у межах $410238A1 ярдів." },
    { en = "Grommash rallies $s1 |4ally:allies; who attack players.", ua = "Ґроммаш прикликає $s1 |4союзника:союзників;, які нападають на гравців." },
    { en = "Sets an enemy ablaze, inflicting $s1 Fire damage and an additional $s2 Fire damage every $T2 sec for $D.", ua = "Підпалює ворога, завдаючи $s1 вогняної шкоди й додатково $s2 вогняної шкоди кожні $T2 с протягом $D." },
    { en = "Lothar slams his sword into the ground multiple times in quick succession, inflicting $418056s2 Nature damage in a frontal cone.", ua = "Лотар кілька разів поспіль гатить мечем у землю, завдаючи $418056s2 шкоди від сил природи в передньому конусі." },
    { en = "Conjures icy shards from above for $D, inflicting $417026s1 Frost damage every $417026T2 sec to enemies in the area.", ua = "Прикликає крижані скалки згори протягом $D, завдаючи $417026s1 морозної шкоди кожні $417026T2 с ворогам у зоні." },
    { en = "Lothar swings twice with deft precision, inflicting $410258s1 Physical damage each time, applying $@spellname410497. This attack cannot be blocked, dodged, or parried.", ua = "Лотар б'є двічі зі вправною точністю, завдаючи $410258s1 фізичної шкоди щоразу та накладаючи $@spellname410497. Цю атаку неможливо заблокувати, ухилитися від неї чи парирувати." },
    { en = "Lothar yells with a fearsome sound, inflicting $s1 Nature damage to all enemies.", ua = "Лотар видає жахливий рев, завдаючи $s1 шкоди від сил природи всім ворогам." },
    { en = "Shoot at a target, inflicting $s1 Physical damage.", ua = "Стріляє по цілі, завдаючи $s1 фізичної шкоди." },
    { en = "Upon defeating an enemy, Lothar gains Battle Senses. This effect stacks.\n\n\n\nSuccessful melee attacks hone his skill, consuming a stack and inflicting $419616s1 Nature damage to all players.", ua = "Перемагаючи ворога, Лотар отримує Бойові чуття. Цей ефект накопичується.\n\n\n\nУспішні удари ближнього бою відточують його вправність, витрачаючи заряд і завдаючи $419616s1 одиниць шкоди силами природи всім гравцям." },
    { en = "Lets fly a serrated arrow at an enemy, inflicting $s1 Physical damage and additionally bleeds the target, inflicting $s2 Physical damage every $T2 sec for $D.", ua = "Випускає зазубрену стрілу у ворога, завдаючи $s1 фізичної шкоди та додатково спричиняє кровотечу в цілі, завдаючи $s2 фізичної шкоди кожні $T2 с протягом $D." },
    { en = "Lothar rallies $s1 |4ally:allies; who attack players.", ua = "Лотар прикликає $s1 |4союзника:союзників;, які нападають на гравців." },
    { en = "Deios manifests orbs of compressed time above targeted locations which fall, exploding in |5$@spellname410908 upon arrival. These orbs fall slower when players stand underneath them.", ua = "Дейос проявляє сфери стиснутого часу над визначеними місцями, які падають і вибухають у |5$@spellname410908 при приземленні. Ці сфери падають повільніше, коли гравці стоять під ними." },
    { en = "Defeating the Infinite Keeper destabilizes the time rift, inflicting $416261s1% of Deios' health in damage over $416261D.", ua = "Перемога над Вічним Хранителем дестабілізує часовий розлом, завдаючи шкоди в розмірі $416261s1% здоров'я Дейоса протягом $416261D." },
    { en = "Deios' $@spellname416264 scars the ground for $417412D, inflicting $s1 Arcane damage every $T1 sec to those who stand upon it.", ua = "$@spellname416264 Дейоса лишає рубець на землі протягом $417412D, завдаючи $s1 арканної шкоди кожні $T1 сек тим, хто стоїть на ньому." },
    { en = "Deios blasts Nozdormu with corrupted bronze magic for $416264D, sending arcane artillery throughout the environment every $416264T1 sec, additionally inflicting $416290s1 Arcane damage to all players.\n\n\n\nThe smaller bolts inflict $416265s1 Arcane damage to targets within $416265A1 yards, and the larger bolts inflict $416266s1 Arcane damage to targets within $416266A1 yards.", ua = "Дейос закидає Ноздорму зіпсованою бронзовою магією протягом $416264D, розсилаючи арканну артилерію по всьому довкіллю кожні $416264T1 сек і додатково завдаючи $416290s1 арканної шкоди всім гравцям.\n\n\n\nМенші блискавки завдають $416265s1 арканної шкоди цілям у радіусі $416265A1 ярдів, а більші — $416266s1 арканної шкоди цілям у радіусі $416266A1 ярдів." },
    { en = "Deios emanates time magic in a frontal direction, inflicting $416139s1 Arcane damage and an additional $416139s2 Arcane damage every $416139T2 sec for $416139D.", ua = "Дейос випускає магію часу в напрямку перед собою, завдаючи $416139s1 арканної шкоди та додатково $416139s2 арканної шкоди кожні $416139T2 сек упродовж $416139D." },
    { en = "The time rift rips Time-Displaced Troopers from their own timeline, significantly lowering their starting health.", ua = "Часовий розлом вириває зміщених у часі бійців з їхньої часової лінії, значно знижуючи їхнє початкове здоров'я." },
    { en = "Jettisons time magic towards an enemy, inflicting $s1 Arcane damage.", ua = "Жбурляє в ворога часову магію, спричиняючи $s1 арканної шкоди." },
    { en = "Deios rips an infinite agent from another timeline who creates a stable rift, summoning reinforcements from across space and time.", ua = "Дейос вириває нескінченного агента з іншої часової лінії, який створює стабільний розлом, прикликаючи підкріплення з усіх куточків простору й часу." },
    { en = "Corrupts the timeline of an enemy, inflicting $s1 Arcane damage for $D every $T1 sec, decreasing in frequency over time.", ua = "Спотворює часову лінію ворога, завдаючи $s1 арканної шкоди впродовж $D кожні $T1 сек, із дедалі рідшою частотою з часом." },
    { en = "Explodes in a ripple of time magic, inflicting $410908s1 Arcane damage to all players and additionally increasing damage taken by Infinity Nova by $410908s2% for $410908D. This effect stacks.", ua = "Вибухає брижами часової магії, завдаючи $410908s1 арканної шкоди всім гравцям і додатково збільшуючи шкоду, отриману від Нескінченної Нови, на $410908s2% протягом $410908D. Цей ефект накопичується." },
    { en = "These reinforcements invade this timeline from others every $410911T1 sec, aiding the Infinite Keepers in combat.", ua = "Це підкріплення вторгається в цю часову лінію з інших кожні $410911T1 с, допомагаючи Вічним Хранителям у бою." },
    { en = "Upon expiration, $@spellname407406 consumes the player's mind, turning them against their allies for $d.", ua = "Після закінчення $@spellname407406 пожирає розум гравця, обертаючи його проти союзників на $d." },
    { en = "$@spellname403486 explodes, inflicting $s1 Arcane damage to all players and an additional $s2 Arcane damage every $t2 sec for $d. This effect stacks.", ua = "$@spellname403486 вибухає, завдаючи $s1 арканної шкоди всім гравцям, а також додатково $s2 арканної шкоди кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "The totem fires a burst of decay at a player, inflicting $s1 Nature damage to all players within $A1 yards of the targeted player. Applies a stack of $@spellname373896.", ua = "Тотем випускає спалах гнилі по гравцю, завдаючи $s1 шкоди від сил природи всім гравцям у межах $A1 ярдів від цілі. Накладає стак $@spellname373896." },
    { en = "Pierces a target with both barbed arms, inflicting $322736s1 Physical damage with the first strike and $322735s1 Shadow damage with the second strike.", ua = "Пронизує ціль обома шипастими руками, завдаючи $322736s1 фізичної шкоди першим ударом і $322735s1 тіньової шкоди другим ударом." },
    { en = "Hakkar's minions are eternal, spilling their essence in lieu of death. This creates a pool on the ground for $323567D, inflicting $323569s1 Shadow damage every $323569T1 sec while inside it. \n\n\n\nThis pool gradually shrinks over time, healing the minion, resurrecting upon reaching full health.", ua = "Поплічники Хаккара вічні: замість смерті вони проливають свою есенцію. Це створює калюжу на землі на $323567D, що завдає $323569s1 тіньової шкоди кожні $323569T1 сек тим, хто в ній стоїть. \n\n\n\nЗ часом ця калюжа поступово зменшується, зцілюючи поплічника, який воскресає, щойно повністю відновить здоров'я." },
    { en = "Violently erupts in shadow magic, inflicting $322759s1 Shadow damage to all enemies, forming a protective barrier. The value of the absorb is based on the damage inflicted to targets. This effect can also strike Sons of Hakkar.", ua = "Несамовито вибухає тіньовою магією, завдаючи $322759s1 тіньової шкоди всім ворогам і утворюючи захисний бар'єр. Величина поглинання залежить від шкоди, завданої цілям. Цей ефект може вражати й Синів Хаккара." },
    { en = "Inflicts $s1 Shadow damage to all enemies and grants the caster $s2% increased Shadow damage for $D. This effect stacks.", ua = "Завдає $s1 тіньової шкоди всім ворогам і дарує тому, хто творить, на $s2% збільшену тіньову шкоду протягом $D. Цей ефект накопичується." },
    { en = "Spews a barrage of acrid blood at targeted locations, inflicting $323118s1 Shadow damage and reducing damage done by $323118s2% to enemies within $323118a1 yards for $323118D. This effect stacks.", ua = "Вивергає шквал їдкої крові на цільові місця, завдаючи $323118s1 тіньової шкоди й зменшуючи завдавану шкоду на $323118s2% ворогам у межах $323118a1 ярдів протягом $323118D. Цей ефект накопичується." },
    { en = "Inflicts $322746s1 Shadow damage every $322746T1 sec for $322746d.\n\n\n\nThis effect attempts to spread to nearby targets within $322746s2 yards.", ua = "Завдає $322746s1 тіньової шкоди кожні $322746T1 с впродовж $322746d.\n\n\n\nЦей ефект намагається поширитися на найближчі цілі в радіусі $322746s2 м." },
    { en = "Gains Zealous, fixating on a target and refusing to attack any others.", ua = "Отримує Завзяття, зосереджуючись на одній цілі й відмовляючись нападати на інших." },
    { en = "Inflicts $335072s1 Arcane damage to enemies within $335072A1 yards.", ua = "Завдає $335072s1 арканної шкоди ворогам у радіусі $335072A1 м." },
    { en = "Shadowfury is unleashed, inflicting $320132s1 Shadow damage and stunning all players within $320132A1 yds for $320132D. This effect can also affect Millificent Manastorm.", ua = "Вивільняється Тіньова лють, завдаючи $320132s1 тіньової шкоди й оглушуючи всіх гравців у радіусі $320132A1 м на $320132D. Цей ефект може зачепити й Мілліфісент Манасторм." },
    { en = "Inflicts $320008s1 Frost damage and reduces movement speed by $320008s2% for $320008d.", ua = "Завдає $320008s1 морозної шкоди і знижує швидкість пересування на $320008s2% на $320008d." },
    { en = "Hurls a Buzz-Saw at a target, inflicting $320145s1 Physical damage and applying $@spellname320147.", ua = "Жбурляє Циркулярну пилку в ціль, завдаючи $320145s1 фізичної шкоди та накладаючи $@spellname320147." },
    { en = "Inflicts $324010s1 Fire damage and stuns enemies within the affected area. This effect can also affect Millhouse Manastorm.", ua = "Завдає $324010s1 вогняної шкоди і приголомшує ворогів у враженій зоні. Цей ефект також може зачепити Міллгауса Манасторма." },
    { en = "The Squirrel Bomb charges up and then explodes, inflicting $320804s1 Fire damage to all players. The bomb can be disarmed or destroyed beforehand to prevent the explosion.", ua = "Білка-Бомба заряджається, а тоді вибухає, завдаючи $320804s1 вогняної шкоди всім гравцям. Бомбу можна завчасно знешкодити чи знищити, аби запобігти вибуху." },
    { en = "Delivers a series of strikes so diabolical, it is unable to be described accurately in text. Affected targets will similarly be unlikely to have understood the full effect of this spell as its blinding brilliance washes over them like tidal wave of devastation.\n\n\n\nInflicts $320142s1 Shadow damage to all enemies every $320141T1 sec for $320141D, increasing in damage by $320142s2%. This effect stacks.", ua = "Завдає серії настільки диявольських ударів, що їх неможливо точно описати словами. Уражені цілі так само навряд чи усвідомлять повну дію цього закляття, коли його сліпуча яскравість накриває їх, наче нищівна припливна хвиля.\n\n\n\nЗавдає $320142s1 тіньової шкоди всім ворогам кожні $320141T1 с протягом $320141D, причому шкода зростає на $320142s2%. Цей ефект накопичується." },
    { en = "Aims a finger-aimed laser at multiple targets, cutting lines of damage across the room, inflicting $323992s1 Fire damage to enemies within the afflicted area. This effect can also affect Millhouse Manastorm.\n\n\n\nAn Eruption occurs moments after the initial impact.", ua = "Спрямовує лазер із пальця на кілька цілей, прорізаючи кімнату лініями шкоди, завдаючи $323992s1 вогняної шкоди ворогам у враженій зоні. Цей ефект також може зачепити Міллгауса Манасторма.\n\n\n\nЗа мить після початкового влучання стається Виверження." },
    { en = "Spears a target on her Buzz-Saw, rooting them for $330434D and inflicting $320145s1 Physical damage every $320144T2 sec for $320144D and applies $@spellname320147.", ua = "Настромлює ціль на свою циркулярну пилку, знерухомлюючи її на $330434D і завдаючи $320145s1 фізичної шкоди кожні $320144T2 с протягом $320144D, а також накладає $@spellname320147." },
    { en = "Millhouse summons a power crystal, which channels towards Millhouse, affecting players or Millhouse, whichever it strikes first.\n\n\n\nPower Overwhelming affects players by inflicting $320786s1 Arcane damage every $320786T1 sec and increasing damage done by $320786s2% for $320786D. This effect stacks.\n\n\n\nPower Overwhelming affects Millhouse by increasing damage done by $320785s1% for $320785D, and causing $@spellname335072. This effect stacks.", ua = "Мілгаус прикликає кристал сили, що підтримує до Мілгауса, впливаючи на гравців або на самого Мілгауса — залежно від того, кого вразить першим.\n\n\n\nНа гравців Нездоланна Сила діє, завдаючи $320786s1 арканної шкоди кожні $320786T1 с і збільшуючи завдану шкоду на $320786s2% впродовж $320786D. Цей ефект накопичується.\n\n\n\nНа Мілгауса Нездоланна Сила діє, збільшуючи завдану шкоду на $320785s1% впродовж $320785D і спричиняючи $@spellname335072. Цей ефект накопичується." },
    { en = "Bleeds a target, inflicting $320147s1 Physical damage every $320147T1 sec for $320147D. This effect stacks.", ua = "Викликає кровотечу в цілі, завдаючи $320147s1 фізичної шкоди кожні $320147T1 с протягом $320147D. Цей ефект накопичується." },
    { en = "Deploys the A.R.C.B., rocketing boostered roosters from above, inflicting $321011s1 Fire damage upon touchdown to all players.", ua = "Розгортає П.Б.К.К., запускаючи згори турборакетних півнів, що при приземленні завдають $321011s1 вогняної шкоди всім гравцям." },
    { en = "Millhouse focuses his magics, increasing Frost damage done by $s1%.\n\n\n\n\"I'll teach you to mess with genius!\"", ua = "Мілгаус зосереджує свою магію, збільшуючи завдану морозну шкоду на $s1%.\n\n\n\n\"Я навчу вас не зв'язуватися з генієм!\"" },
    { en = "Several Mechanical Bomb Squirrels are released from the bomb, each charging to a player and exploding, inflicting $320830s1 Fire damage, destroying the squirrel.", ua = "З бомби вивільняється кілька Механічних Білок-Бомб, кожна з яких мчить до гравця та вибухає, завдаючи $320830s1 вогняної шкоди та знищуючи білку." },
    { en = "Dealer Xy'exa creates a displacement trap that teleports the triggering player high into the air.", ua = "Торговка Кс'екса створює пастку зміщення, що телепортує гравця, який її активував, високо в повітря." },
    { en = "Dealer Xy'exa unleashes a beam of energy into a nearby portal, inflicting $320727s1 Arcane damage to all players caught in its path. Soon after, this beam erupts from a portal at a different location, inflciting $320723s1 Arcane damage to all players caught in its path.", ua = "Торговка Кс'екса вивільняє промінь енергії в найближчий портал, завдаючи $320727s1 арканної шкоди всім гравцям на його шляху. Незабаром цей промінь виривається з порталу в іншому місці, завдаючи $320723s1 арканної шкоди всім гравцям на його шляху." },
    { en = "Dealer Xy'exa infuses a player with unstable Arcane energy that inflicts $s1 Arcane Damage and applies one stack of $@spellname323692 every $t1 sec for $d.  Every $d Arcane Lightning arcs to the next closest player.", ua = "Торговка Кс'екса наповнює гравця нестабільною арканною енергією, що завдає $s1 арканної шкоди й накладає один стак $@spellname323692 кожні $t1 с протягом $d. Кожні $d арканна блискавка перестрибує на наступного найближчого гравця." },
    { en = "Dealer Xy'exa unleashes a blast of energy inflicting $s1 Arcane damage and an additional $s2 Arcane damage every $t2 sec for $d to all players that remain on the ground with her. This effect stacks.\n\n\n\nIn addition, all Displacement Traps are destroyed.", ua = "Торговка Ксі'екса вивільняє вибух енергії, завдаючи $s1 арканної шкоди й додатково $s2 арканної шкоди кожні $t2 с протягом $d усім гравцям, що лишаються з нею на землі. Цей ефект накопичується.\n\n\n\nКрім того, всі Пастки Зміщення знищуються." },
    { en = "Increases damage taken from $@spellname323687 by $s1%.", ua = "Збільшує шкоду, отриману від $@spellname323687, на $s1%." },
    { en = "Dealer Xy'exa places a broker device on a random player that explodes after $321948d, inflicting $s1 Arcane damage and an additional $s2 Arcane damage every $t2 sec for $d to all players at the same level as the target. This effect stacks.\n\n\n\nIn addition, if the target of $@spellname342961 remains on the ground, all Displacement Traps are destroyed.", ua = "Торговка Кс'екса встановлює на випадкового гравця пристрій торговців, що вибухає за $321948d, завдаючи $s1 арканної шкоди і додатково $s2 арканної шкоди кожні $t2 с протягом $d усім гравцям на тому ж рівні, що й ціль. Цей ефект накопичується.\n\n\n\nКрім того, якщо ціль $@spellname342961 лишається на землі, усі пастки переміщення знищуються." },
    { en = "Bashes the ground every $327426T1 sec, inflicting $327427s1 Shadow damage to targets within $327427A1 yards of the center of the platform.", ua = "Гатить по землі кожні $327426T1 с, завдаючи $327427s1 тіньової шкоди цілям у радіусі $327427A1 м від центру платформи." },
    { en = "Expels shadow, blood, and necromantic magic in a direction, inflicting $334913s1 Shadow damage and an additional $334913s2 Shadow damage every $334913T2 sec for $334913D to targets hit by Master of Death. This effect stacks.", ua = "Вивергає тінь, кров і некромантичну магію в одному напрямку, завдаючи $334913s1 тіньової шкоди та додатково $334913s2 тіньової шкоди кожні $334913T2 с протягом $334913D цілям, що зазнали Володаря Смерті. Цей ефект накопичується." },
    { en = "Infuses a Primeval Grasp totem with Bwonsamdi's Mojo, releasing a fragment of Bwonsamdi's power to seek revenge on Mueh'zala.", ua = "Насичує тотем Прадавнього Хвату Моджо Бвонсамді, вивільняючи фрагмент сили Бвонсамді, що прагне помсти Муех'залі." },
    { en = "Inflicts $325807s1 Shadow damage to all players.", ua = "Завдає $325807s1 тіньової шкоди всім гравцям." },
    { en = "Smashes the platform, inflicting $s1% of melee damage as Shadow to all enemies within $A1 yards while no players are in melee range.", ua = "Розбиває платформу, завдаючи $s1% шкоди ближнього бою як тіньової всім ворогам у межах $A1 м, поки в зоні ближнього бою немає гравців." },
    { en = "Blasts Mueh'zala with necromantic power, inflicting $327891s1% of the target's health in damage over $327891D, granting players $@spellname327893.", ua = "Уражає Муех'залу некромантичною силою, завдаючи шкоди в розмірі $327891s1% здоров'я цілі впродовж $327891D і надаючи гравцям $@spellname327893." },
    { en = "Bwonsamdi increases the player's haste by $s1% and movement speed by $s1% for $d. This effect stacks.", ua = "Бвонсамді збільшує поспіх гравця на $s1% і швидкість пересування на $s1% упродовж $d. Цей ефект накопичується." },
    { en = "Manifests a massive orb of chaotic magic, then crushes it, instantly killing anyone within $326171a1 yards.", ua = "Проявляє величезну сферу хаотичної магії, а тоді розчавлює її, миттєво вбиваючи всіх у межах $326171a1 м." },
    { en = "Coalesces a cloud of shadow at locations of players who are not on Mueh'zala's platform. These clouds  inflict $335000s1 Shadow damage every second to targets within $334999A1 yards.", ua = "Згущує хмару тіні на місцях гравців, які перебувають не на платформі Муех'зали. Ці хмари завдають $335000s1 тіньової шкоди щосекунди цілям у радіусі $334999A1 м." },
    { en = "Tapping into the mojo players have acquired, Bwonsamdi manifests Deathgates for $324698D, allowing quick access to escape Mueh'zala's $@spellname326171.", ua = "Користуючись моджо, що зібрали гравці, Бвонсамді проявляє Брами Смерті на $324698D, даючи змогу швидко втекти від $@spellname326171 Муех'зали." },
    { en = "The distortion detonates after $325647D, inflicting $325691s1 Shadow damage to players within $325691a1 yards.", ua = "Викривлення детонує через $325647D, завдаючи $325691s1 тіньової шкоди гравцям у радіусі $325691a1 м." },
    { en = "Distorts the objective reality of afflicted players, inflicting $325725s1 Shadow damage every $325725T1 sec for $325725D.\n\n\n\nUpon expiration, this explodes inflicting $325807s1 Shadow damage to all players.\n\n\n\nUpon being removed, this distortion transfers to the ground.", ua = "Викривлює об'єктивну реальність уражених гравців, завдаючи $325725s1 тіньової шкоди кожні $325725T1 с протягом $325725D.\n\n\n\nПісля завершення вибухає, завдаючи $325807s1 тіньової шкоди всім гравцям.\n\n\n\nПісля зняття це викривлення переноситься на землю." },
    { en = "Slams his primary target, inflicting $327646s1 Physical damage. This applies $@spellname327649, inflicting the damage taken from $@spellname327646 over $327649D.", ua = "Б'є по основній цілі, завдаючи $327646s1 фізичної шкоди. Це накладає $@spellname327649, завдаючи шкоди, отриманої від $@spellname327646, протягом $327649D." },
    { en = "Halkias emits powerful beams of refracted Sinlight from his four windows, inflicting $324044s1 Shadow damage every $337929t1 sec to enemies within each beam.", ua = "Халкіас випромінює зі своїх чотирьох вікон потужні промені заломленого Світла Гріха, завдаючи $324044s1 тіньової шкоди кожні $337929t1 с ворогам у кожному промені." },
    { en = "Horrifying visions of sin are emitted from the Goliath's core, causing a random player to be inflicted with Fear.", ua = "З ядра Голіафа линуть жахливі видіння гріха, уражаючи випадкового гравця Страхом." },
    { en = "The Lights of Atonement protect players within from horrifying Sinlight Visions.", ua = "Вогні Спокути захищають гравців усередині від жахливих Видінь Гріхосвітла." },
    { en = "Horrifying visions of sin are emitted from the Goliath's core, causing players outside of the Lights of Atonement to flee in Fear.", ua = "З ядра Голіафа линуть жахливі видіння гріха, змушуючи гравців за межами Вогнів Спокути тікати в страху." },
    { en = "Halkias brings down his massive stone arms and slams the ground in front of him, inflicting $s1 Physical damage to enemies within $a1 yards of the impact and $s3 Sonic damage to all players within $a3 yards. The impact of $@spellname322936 leaves behind Glass Shards.", ua = "Халкіас опускає свої масивні кам'яні руки та гатить об землю перед собою, завдаючи $s1 фізичної шкоди ворогам у межах $a1 ярдів від місця влучання та $s3 звукової шкоди всім гравцям у межах $a3 ярдів. Влучання $@spellname322936 лишає по собі Скляні Уламки." },
    { en = "Razor sharp shards of glass and rubble reduce movement speed by $s3% and inflict $s2 Physical damage every $t2 sec.", ua = "Гострі як бритва уламки скла та каміння знижують швидкість руху на $s3% і завдають $s2 фізичної шкоди кожні $t2 с." },
    { en = "Halkias hurls a chunk of debris at a random player inflicting $322945s2 Physical damage to players within $322945a2 yards of the impact and $322945s3 Sonic damage to all players within $322945a3 yards. The impact of $@spellname322943 leaves behind Glass Shards.", ua = "Халкіас жбурляє брилу уламків у випадкового гравця, завдаючи $322945s2 фізичної шкоди гравцям у межах $322945a2 ярдів від місця влучання та $322945s3 звукової шкоди всім гравцям у межах $322945a3 ярдів. Влучання $@spellname322943 лишає по собі Скляні Уламки." },
    { en = "Echelon shatters the earth around him, inflicting $s1 Nature damage to all players within $a1 yards and applies $@spellname344874. \n\n\n\n$@spellname319592 destroys all Undying Stonefiends in $@spellname319724 within $a1 yards", ua = "Ешелон трощить землю довкола себе, завдаючи $s1 шкоди від сил природи всім гравцям у радіусі $a1 м і накладаючи $@spellname344874. \n\n\n\n$@spellname319592 знищує всіх безсмертних кам'яних поторочів у $@spellname319724 в радіусі $a1 м" },
    { en = "Inflicts $s1 Nature damage every $t1 sec for $d.", ua = "Завдає $s1 шкоди від сил природи щосекунди ($t1) протягом $d." },
    { en = "When a Undying Stonefiend reaches 0 health it becomes immune to damage and heals for $s2% of maximum health every $t2 sec for $d.", ua = "Коли Невмируща кам'яна потвора досягає 0 здоров'я, вона стає невразливою до шкоди і зцілюється на $s2% максимального здоров'я кожні $t2 сек. упродовж $d." },
    { en = "Upon reaching 100 energy, Echelon begins to turn a player to stone reducing their movement speed by $319602s1% every $t1 for $d. $?DIFF1[Upon reaching 4 stacks the player is $@spellname319611 stunning them for $319611d.][]$?DIFF2[Upon reaching 4 stacks the player is $@spellname319611 stunning them for $319611d.][]$?DIFF8[Upon reaching 4 stacks the player is $@spellname319611 stunning them and any players within $319611a2 yds for $319611d.][]$?DIFF23[Upon reaching 4 stacks the player is $@spellname319611 stunning them and any players within $319611a2 yds for $319611d.][]", ua = "Сягнувши 100 енергії, Ешелон починає обертати гравця на камінь, зменшуючи його швидкість пересування на $319602s1% кожні $t1 протягом $d. $?DIFF1[Сягнувши 4 нашарувань, на гравця діє $@spellname319611, приголомшуючи його на $319611d.][]$?DIFF2[Сягнувши 4 нашарувань, на гравця діє $@spellname319611, приголомшуючи його на $319611d.][]$?DIFF8[Сягнувши 4 нашарувань, на гравця діє $@spellname319611, приголомшуючи його та всіх гравців у радіусі $319611a2 м на $319611d.][]$?DIFF23[Сягнувши 4 нашарувань, на гравця діє $@spellname319611, приголомшуючи його та всіх гравців у радіусі $319611a2 м на $319611d.][]" },
    { en = "Echelon calls for help from allies, summoning $s2 Undying Stonefiends.", ua = "Ешелон кличе на допомогу союзників, прикликаючи $s2 Невмирущих кам'яних потвор." },
    { en = "Echelon creates a torrent of toxic blood inflicting $319702s1 Shadow damage on impact and inflicting $s1 Shadow damage every $t1 sec to all players in the area.", ua = "Ешелон створює потік отруйної крові, що завдає $319702s1 тіньової шкоди при влучанні і $s1 тіньової шкоди кожні $t1 сек. усім гравцям у зоні." },
    { en = "Undying Stonefiends explode upon turning to stone, inflicting $s1 Nature damage to all enemies.", ua = "Невмирущі камінні нечисті вибухають, обертаючись на камінь, і завдають $s1 шкоди від сил природи всім ворогам." },
    { en = "High Adjudicator Aleez unleashes $@spellname1236514 upon $s2 players inflicting $s1 Shadow damage every $1236513t1 sec for $1236513d.\n\n\n\nPlayers afflicted by $@spellname1236514 inflict $s1 Shadow damage to allies within $a1 yards every $1236513t1 sec for $1236513d.", ua = "Верховна Суддиня Аліз вивільняє $@spellname1236514 на $s2 гравців, завдаючи $s1 тіньової шкоди кожні $1236513t1 сек. протягом $1236513d.\n\n\n\nГравці, уражені $@spellname1236514, завдають $s1 тіньової шкоди союзникам у межах $a1 ярдів кожні $1236513t1 сек. протягом $1236513d." },
    { en = "Ghastly Parishioner fixates on a player and attempts to approach them.", ua = "Примарний паратієць зосереджується на гравцеві й намагається наблизитися до нього." },
    { en = "Vessels of Atonement capture the spirit of nearby Haunting Parisioners, dissipating the Haunting Parisioner and sealing the Vessel of Atonement.", ua = "Посудини Спокути захоплюють дух Примарних паратійців поблизу, розвіюючи Примарного паратійця і запечатуючи Посудину Спокути." },
    { en = "A rhythmic pulse from the realms beyond inflicts $s1 Shadow damage to all players every $323852t sec and increases all damage done by the Ghastly Parishioner by $s2%. This effect stacks.", ua = "Ритмічний пульс із потойбічних світів завдає $s1 тіньової шкоди всім гравцям кожні $323852t сек. і збільшує всю шкоду, яку завдає Примарний паратієць, на $s2%. Цей ефект накопичується." },
    { en = "High Adjudicator Aleez summons a Ghastly Parishioner to pursue a random player.", ua = "Верховна Суддиня Аліз прикликає примарного паратійця, щоб переслідувати випадкового гравця." },
    { en = "Inflicts $s1 Shadow damage to High Adjudicator Aleez's current target.", ua = "Завдає $s1 тіньової шкоди поточній цілі Верховної Суддині Аліз." },
    { en = "The anima fountain boils over, inflicting $327475s1 Shadow damage to all players within $327475A1 yards of each impact.", ua = "Джерело аніми вирує через край, завдаючи $327475s1 тіньової шкоди всім гравцям у межах $327475A1 ярдів від кожного влучання." },
    { en = "Ghastly Parishioners exist in the space between worlds, reducing their damage taken by 100%.", ua = "Примарні паратійці існують у просторі між світами, що зменшує отримувану ними шкоду на 100%." },
    { en = "Lord Chamberlain channels a beam of anima towards a Sinstone Statue, affecting a player or the statue, whichever it strikes first.\n\n\n\nUpon striking a player, inflicts $335338s1 Shadow damage every $t1 sec.\n\n\n\nUpon striking a statue, all players suffer $323414s1 Shadow damage.", ua = "Верховний камергер скеровує промінь аніми в Статую Каменя гріхів, вражаючи гравця або статую — залежно від того, кого торкнеться першим.\n\n\n\nВлучивши в гравця, завдає $335338s1 тіньової шкоди кожні $t1 с.\n\n\n\nВлучивши в статую, завдає всім гравцям $323414s1 тіньової шкоди." },
    { en = "Lord Chamberlain unleashes a wave of anima, inflicting $s2 Shadow damage to all players in a cone in front of him.", ua = "Верховний камергер вивільняє хвилю аніми, завдаючи $s2 тіньової шкоди всім гравцям у конусі перед собою." },
    { en = "Lord Chamberlain unleashes sinister energy from himself and all sinstone statues inflicting $s1 Shadow damage to players within $A1 yards.", ua = "Верховний камергер вивільняє лиховісну енергію з себе і з усіх статуй гріхокаменю, завдаючи $s1 тіньової шкоди гравцям у межах $A1 ярдів." },
    { en = "Lord Chamberlain throws a Sinstone Statue at a nearby player, inflicting $323126s1 Physical damage and knocking back anyone in its path. The force of the Sinstone Statue being thrown inflicts $1237634s1 Sonic damage to all players upon landing.", ua = "Верховний камергер кидає Статую Каменя гріхів в гравця поблизу, завдаючи $323126s1 фізичної шкоди й відкидаючи всіх на її шляху. Сила кинутої Статуї Каменя гріхів при падінні завдає $1237634s1 звукової шкоди всім гравцям." },
    { en = "Lord Chamberlain repels all nearby Sinstone Statues directly away from him, inflicting $323126s1 Physical damage and knocking back anyone in its path. Each Sinstone Statue inflicts $1237642s1 Sonic damage to all players upon landing after being repelled from Lord Chamberlain.", ua = "Верховний камергер відштовхує всі Статуї Каменя гріхів поблизу геть від себе, завдаючи $323126s1 фізичної шкоди й відкидаючи всіх на їхньому шляху. Кожна Статуя Каменя гріхів, відштовхнута Верховним камергером, при падінні завдає $1237642s1 звукової шкоди всім гравцям." },
    { en = "Lord Chamberlain channels a beam of anima towards all nearby Sinstone Statues, affecting players or the statue, whichever it strikes first.\n\n\n\nUpon striking a player, inflicts $335338s1 Shadow damage every $t1 sec.\n\n\n\nUpon striking a statue, all players suffer $323414s1 Shadow damage.", ua = "Верховний камергер скеровує промінь аніми на всі Гріхокам'яні статуї поблизу, вражаючи гравців або статую — залежно від того, що влучить першим.\n\n\n\nВлучивши в гравця, завдає $335338s1 тіньової шкоди кожні $t1 сек.\n\n\n\nВлучивши в статую, завдає всім гравцям $323414s1 тіньової шкоди." },
    { en = "Lord Chamberlain pulls all nearby Sinstone Statues to him, inflicting $323126s1 Physical damage and knocking back any player in the statue's path.", ua = "Верховний камергер притягує до себе всі сусідні Статуї Гріхокаменю, завдаючи $323126s1 фізичної шкоди та відкидаючи будь-якого гравця на шляху статуї." },
    { en = "Lord Chamberlain chains $@spellname329113, $@spellname323129, and $@spellname323393 over $d.", ua = "Лорд-камергер поєднує в ланцюг $@spellname329113, $@spellname323129 і $@spellname323393 протягом $d." },
    { en = "Oulfarran expels a cone of enchanted pollen that inflicts $s1 Nature damage and disorients players for $d.", ua = "Улфарран випускає конус зачарованого пилку, що завдає $s1 шкоди від сил природи й дезорієнтує гравців на $d." },
    { en = "Maloch periodically forces Oulfarran to cast $@spellname323263.", ua = "Малох періодично змушує Улфаррана творити $@spellname323263." },
    { en = "Anima bursts from Oulfarran's bark and rains down around players. Each glob of anima inflicts $323263s1 Nature damage to players within $323263A1 yds and leaves behind an Anima Puddle.", ua = "Аніма вибухає з кори Улфаррана й проливається дощем навколо гравців. Кожна крапля аніми завдає $323263s1 шкоди від сил природи гравцям у межах $323263A1 ярдів і лишає по собі Калюжу Аніми." },
    { en = "Inflicts $s1 Shadow damage to all players every $t1 sec while Maloch is protected by Embrace Darkness.", ua = "Завдає $s1 тіньової шкоди всім гравцям кожні $t1 сек., поки Малоха захищають Обійми Темряви." },
    { en = "Maloch shrouds himself in dark energy, applying Death Shroud to all players and reducing all damage he takes by $s1%.\n\n\n\nOulfarran can remove this effect with $@spellname323059.", ua = "Малох огортає себе темною енергією, накладаючи Саван Смерті на всіх гравців і зменшуючи всю отримувану ним шкоду на $s1%.\n\n\n\nУлфарран може зняти цей ефект за допомогою $@spellname323059." },
    { en = "Maloch uses drust magic to take control of Oulfarran's mind, forcing them to attack players while above $s2% health.", ua = "Малох застосовує магію друстів, аби заволодіти розумом Оулфаррана, змушуючи її атакувати гравців, поки в неї понад $s2% здоров'я." },
    { en = "Each time Oulfarran is forced to cast Tears of the Forest, the number of missiles increases by $s1.\n\n\n\nBreaking free of Soul Shackle removes this effect.", ua = "Щоразу, коли Оулфарран змушують творити Сльози Лісу, кількість снарядів збільшується на $s1.\n\n\n\nЗвільнення від Душевних Кайданів знімає цей ефект." },
    { en = "Maloch fires a bolt of deathly energy that inflicts $s1 Shadow damage.", ua = "Малох випускає блискавку смертоносної енергії, що завдає $s1 тіньової шкоди." },
    { en = "Inflicts $s1 Nature damage every $t1 sec to players standing in the puddle.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с гравцям, що стоять у калюжі." },
    { en = "Oulfarran overwhelms Maloch with the fury of the forest, stunning him and increasing all damage he takes by $s2% for $d.\n\n\n\nThis removes the effects of Embrace Darkness and Death Shroud.", ua = "Улфарран приголомшує Малоха люттю лісу, оглушаючи його та підвищуючи всю отримувану ним шкоду на $s2% протягом $d.\n\n\n\nЦе знімає ефекти Обійми Темряви та Саван Смерті." },
    { en = "Maloch compels all players to flee in fear for $d.", ua = "Малох змушує всіх гравців тікати в страху протягом $d." },
    { en = "The caster chooses a target to fixate.", ua = "Заклинач обирає ціль для зосередження." },
    { en = "Mistcaller plays $@spellname321828 with an enemy, inflicting $s1 Nature damage and confusing the target for $d. This spell can be interrupted by the target.", ua = "Туманозваник грає в $@spellname321828 з ворогом, завдаючи $s1 шкоди силами природи й спантеличуючи ціль на $d. Це закляття може бути перерване ціллю." },
    { en = "Inflicts $s1 Nature damage to all enemies. This damage increases by $321725s1% every cast.", ua = "Завдає $s1 шкоди силами природи всім ворогам. Ця шкода зростає на $321725s1% за кожне прочитання." },
    { en = "When the caster reaches an enemy they explode, inflicting $s1 Frost damage and stunning all enemies within $A1 yards for $d.", ua = "Досягнувши ворога, заклинач вибухає, завдаючи $s1 морозної шкоди і приголомшуючи всіх ворогів у межах $A1 м на $d." },
    { en = "Mistcaller wants to play $@spellname321834 and throws an anima ball at players, inflicting $s1 Nature damage to all enemies in a line.", ua = "Туманозвачка хоче зіграти в $@spellname321834 і кидає в гравців кулю аніми, завдаючи $s1 шкоди від сил природи всім ворогам у лінії." },
    { en = "When the wrong Illusionary Clone is destroyed it explodes, inflicting $s1 Nature damage to all enemies.", ua = "Коли знищено хибного Ілюзорного Клона, він вибухає, завдаючи $s1 шкоди силами природи всім ворогам." },
    { en = "Mistcaller summons an Illusionary Vulpin to chase her enemies for $d. Upon reaching an enemy it triggers $@spellname321893.", ua = "Туманозвачка прикликає ілюзорного вульпіна, що переслідує її ворогів протягом $d. Досягнувши ворога, він спричиняє $@spellname321893." },
    { en = "Mistcaller wants to play a $@spellname321471, disappearing while leaving 4 illusionary clones. Destroying the clone with a sigil that is different from the others ends the game.", ua = "Туманозвачка хоче зіграти в $@spellname321471, зникаючи й лишаючи 4 ілюзорні копії. Знищення копії з печаткою, відмінною від інших, завершує гру." },
    { en = "Anima erupts from Tred'ova, inflicting $s1 Nature damage to all players.", ua = "Аніма вивергається з Тред'ови, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Tredova marks a random player for\n\nthe Gormling Larva to fixate on for $d.", ua = "Тред'ова позначає випадкового гравця,\n\nна якому Личинка ґормлінга зосереджується протягом $d." },
    { en = "Gormling Larva explode into a pool of acid upon death, inflicting $s1 Nature damage every $t1 sec to anyone in the pool.", ua = "Личинки ґормлінгів вибухають при загибелі, утворюючи калюжу кислоти, що завдає $s1 шкоди від сил природи кожні $t1 с усім у калюжі." },
    { en = "Tred'nova gathers poison on itself and pulls players in. The concentrated poison explodes after $d, inflicting $463603s1 Nature damage to all players within $463603a1 yards of impact.", ua = "Тред'ова збирає на собі отруту й затягує гравців досередини. Сконцентрована отрута вибухає через $d, завдаючи $463603s1 шкоди від сил природи всім гравцям у межах $463603a1 ярд. від місця влучання." },
    { en = "Tred'ova consumes the depleted Cocoon of Lakali causing anima to erupt from them, inflicting $322465s1 Nature every $s2 sec to all enemies for $d. While this occurs Tred'ova will launch missile of anima at random locations around them", ua = "Тред'ова поглинає виснажений Кокон Лакалі, через що з нього вивергається аніма, завдаючи $322465s1 шкоди від сил природи кожні $s2 с усім ворогам протягом $d. Поки це триває, Тред'ова запускатиме снаряди аніми у випадкові місця навколо себе." },
    { en = "Tred'ova quickly incubates nearby eggs, summoning 4 Gormling Larva.", ua = "Тред'ова швидко інкубує найближчі яйця, прикликаючи 4 Личинки ґормлінга." },
    { en = "Tred'ova unleashes a blast of anima that impacts at a random location nearby, inflicting $s1 Nature damage to all players within $A1 yards of the impact.", ua = "Тред'ова вивільняє вибух аніми, що влучає у випадкове місце поблизу, завдаючи $s1 шкоди від природи всім гравцям у межах $A1 ярдів від точки влучання." },
    { en = "Tred'ova tethers a target to multiple allies, inflicting $s1 Shadow damage every $t1 sec. All damage taken is duplicated to tethered player as Shadow damage.\n\n\n\nMoving more than $s3 yards from the player dispels the $@spellname322648 from that ally.", ua = "Тред'ова прив'язує ціль до кількох союзників, завдаючи $s1 тіньової шкоди кожні $t1 с. Уся отримана шкода дублюється на прив'язаного гравця як тіньова шкода.\n\n\n\nВіддалення більш ніж на $s3 м від гравця знімає $@spellname322648 з цього союзника." },
    { en = "Tred'ova spits a glob of acid at all nearby players' location, inflicting $s1 Nature damage to any player within $a1 yards of impact.\n\n\n\nAs Tred'ova gains intelligence she will attempt to predict where her enemies will move and also fire globs of acid at those locations.", ua = "Тред'ова плює згустком кислоти в місце всіх гравців поблизу, завдаючи $s1 шкоди силами природи будь-якому гравцеві в радіусі $a1 м від падіння.\n\n\n\nМірою того, як Тред'ова набуває інтелекту, вона намагається передбачити, куди рушать її вороги, і також метає згустки кислоти в ті місця." },
    { en = "Tred'ova hardens her shell, absorbing damage equal to $s2% of her maximum health. While this shield is active, $@spellname322450 cannot be interrupted.", ua = "Тред'ова загартовує свій панцир, поглинаючи шкоду в розмірі $s2% від її максимального здоров'я. Поки цей щит активний, $@spellname322450 не можна перервати." },
    { en = "Globgrog feasts upon any slime which reaches him, healing him for ${$E1*100}% of the slime's remaining health.", ua = "Ґлобґроґ пожирає будь-який слиз, що його досягає, зцілюючись на ${$E1*100}% решти здоров'я слизу." },
    { en = "Globgrog beckons $s2 Slimy Morsels that slowly move towards him.", ua = "Ґлобґроґ прикликає $s2 Слизьких Лагоминок, що повільно рухаються до нього." },
    { en = "Globgrog's stomp coats players in plague, inflicting $s2 Nature damage every $t2 sec and reducing their movement speed by $s1% for $d.", ua = "Тупіт Глобґроґа вкриває гравців чумою, завдаючи $s2 шкоди від природи кожні $t2 с і знижуючи їхню швидкість пересування на $s1% протягом $d." },
    { en = "Globgrog's plagued mass stomps the ground and inflicts $s1 Physical damage to all players, knocking them away and applying $@spellname331238.", ua = "Зачумлена туша Ґлобґроґа гупає об землю та завдає $s1 фізичної шкоди всім гравцям, відкидаючи їх і накладаючи $@spellname331238." },
    { en = "Globgrog slams his plagued fist, creating a frontal slime wave inflicting $s1 Nature damage to players. Additionally, players affected by this wave are rooted and suffer $326242s2 Nature damage every $326242t2 sec for $326242d.", ua = "Ґлобґроґ б'є своїм зачумленим кулаком, створюючи фронтальну хвилю слизу, що завдає гравцям $s1 шкоди від сил природи. Крім того, уражені цією хвилею гравці знерухомлюються та зазнають $326242s2 шкоди від сил природи кожні $326242t2 сек. протягом $326242d." },
    { en = "Doctor Ickus summons a Congealed Slime at his location.", ua = "Доктор Іккус прикликає згуслий слиз на своїй позиції." },
    { en = "Doctor Ickus leaps to the farthest random player's destination, inflicting $s1 Physical damage to all nearby players and knocking them back.", ua = "Доктор Іккус стрибає до позиції найдальшого випадкового гравця, завдаючи $s1 фізичної шкоди всім гравцям поблизу й відкидаючи їх." },
    { en = "The slime inoculates allies within 7 yards, increasing their haste by $s1%.", ua = "Слиз прищеплює союзників у межах 7 ярдів, збільшуючи їхній поспіх на $s1%." },
    { en = "The ooze erupts, inflicting $s1 Nature damage to all players.", ua = "Слиз вибухає, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Doctor Ickus summons Pestilence Slimes around his location.", ua = "Доктор Іккус прикликає Чумних слизів довкола себе." },
    { en = "The slime inoculates allies within 7 yards, reducing their damage received by $328175s1%.", ua = "Слиз імунізує союзників у межах 7 ярдів, зменшуючи отримувану ними шкоду на $328175s1%." },
    { en = "The slime hurls globs at players, inflicting $321975s1 Nature damage.", ua = "Слиз жбурляє в гравців грудки, завдаючи $321975s1 шкоди від сил природи." },
    { en = "Doctor Ickus amps his slime pack, radiating waves of filth in four directions that inflict $s1 Nature damage to players within $a1 yards of the impact.", ua = "Доктор Іккус підсилює свою зграю слизу, випромінюючи хвилі бруду в чотирьох напрямках, що завдають $s1 шкоди від сил природи гравцям у межах $a1 ярдів від місця удару." },
    { en = "The slime lunges at a player, inflicting $322410s1 Nature damage and reducing haste by $322410s2% to all players within $322410a1 yards of the impact.", ua = "Слиз кидається на гравця, завдаючи $322410s1 шкоди від сил природи і знижуючи поспіх на $322410s2% усім гравцям у межах $322410a1 м від влучання." },
    { en = "Doctor Ickus infects the player, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d. This effect stacks.\n\n\n\nWhen removed, this aura spawns a Erupting Ooze for each stack applied.", ua = "Доктор Іккус заражає гравця, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 с протягом $d. Цей ефект накопичується.\n\n\n\nПісля зняття ця аура породжує Слиз-Виверження за кожен накопичений заряд." },
    { en = "Doctor Ickus infects all players, inflicting $s1 Nature damage on impact and an additional $s2 Nature damage every $t2 sec for $d when not engaged in melee combat.\n\n\n\nThis effect stacks.", ua = "Доктор Іккус заражає всіх гравців, завдаючи $s1 шкоди від сил природи при влучанні та додатково $s2 шкоди від сил природи кожні $t2 сек. протягом $d, поки він не зайнятий ближнім боєм.\n\n\n\nЦей ефект накопичується." },
    { en = "The ooze bursts underfoot, inflicting $s1 Physical damage to the player who stepped on it.", ua = "Слиз вибухає під ногами, завдаючи $s1 фізичної шкоди гравцю, що на нього наступив." },
    { en = "Doctor Ickus arms a Plague Bomb that will detonate, inflicting $s1 Nature damage to all players.", ua = "Доктор Іккус активує Чумну Бомбу, що вибухне, завдавши $s1 шкоди від сил природи всім гравцям." },
    { en = "Doctor Ickus summons a Pestilence Slime at his location.", ua = "Доктор Іккус прикликає слиз Пошесті у своєму місці." },
    { en = "Domina preys upon isolated players who are not within $s2 yards of an ally, encasing them in a Web Wrap.", ua = "Доміна полює на самотніх гравців, що перебувають далі ніж за $s2 ярдів від союзника, оплутуючи їх Павутинним Сповиттям." },
    { en = "A thick webbing encases the Brood Assassin, providing stealth.\n\n\n\nWebs extend from the Brood Assassin's location, reducing movement speed of players in the area by $s1%.", ua = "Густе павутиння огортає вбивцю виводка, даруючи приховування.\n\n\n\nПавутина простягається від місця вбивці виводка, зменшуючи швидкість пересування гравців у цій зоні на $s1%." },
    { en = "Domina coats her deadly blades in poison, causing her melee attacks to inflict an additional $s1 Nature damage.", ua = "Доміна покриває свої смертоносні клинки отрутою, через що її атаки ближнього бою завдають додатково $s1 шкоди від сил природи." },
    { en = "Domina slashes her current target, inflicting $s1 Physical damage and applying a toxin increasing the victim's Nature damage taken by $s2% for $d.", ua = "Доміна шматує свою поточну ціль, завдаючи $s1 фізичної шкоди і накладаючи токсин, що збільшує отримувану жертвою шкоду від сил природи на $s2% протягом $d." },
    { en = "Domina encases the player in a powerful web wrap, causing them to become stunned until the web can be destroyed.", ua = "Доміна оповиває гравця міцним павутинним коконом, через що той стає приголомшеним, доки павутину не буде знищено." },
    { en = "Domina appears behind a marked player, ambushing all players within $A1 yds of her target. Players affected by this ambush suffer $s1 Shadow damage and are stunned for $d.", ua = "Доміна з'являється позаду позначеного гравця і завдає удару з засідки всім гравцям у межах $A1 ярдів від її цілі. Уражені засідкою гравці зазнають $s1 тіньової шкоди й приголомшуються на $d." },
    { en = "Brood Assassins periodically hurl a poisoned dagger at a random target that inflicts $s1 Nature damage initially and $s2 Nature damage every $t2 sec for $d.", ua = "Асасини виводка періодично кидають отруєний кинджал у випадкову ціль, завдаючи спершу $s1 шкоди від сил природи, а потім $s2 шкоди від сил природи кожні $t2 сек. протягом $d." },
    { en = "Margrave Stradama summons a Malignant Spawn.", ua = "Маркграфиня Страдама прикликає Злоякісне поріддя." },
    { en = "Stradama sinks beneath the slime and causes tentacles to erupt in a pattern, inflicting $322475s1 Nature damage to players caught in the blast.", ua = "Страдама занурюється під слиз і змушує щупальця вивергатися візерунком, завдаючи $322475s1 шкоди від сил природи гравцям, що потрапили під вибух." },
    { en = "Margrave Stradama unleashes a torrent of plague every $322232t1 sec for $322232d coating all players in filth for $s1 Nature damage. This disease additionally inflicts $s2 Nature damage every $t2 sec for $d.\n\n\n\nThis effect stacks.", ua = "Маркграфиня Страдама вивільняє потік чуми кожні $322232t1 сек. протягом $322232d, вкриваючи всіх гравців багном, що завдає $s1 шкоди від сил природи. Ця хвороба додатково завдає $s2 шкоди від сил природи кожні $t2 сек. протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Margrave Stradama infects all players, inflicting $322492s1 Nature damage every $322492t1 sec for $322492d when not engaged in melee combat.\n\n\n\nThis effect stacks.", ua = "Маркграфиня Страдама заражає всіх гравців, завдаючи $322492s1 шкоди від сил природи кожні $322492t1 с протягом $322492d, коли вона не веде ближнього бою.\n\n\n\nЦей ефект накопичується." },
    { en = "The Malignant Spawn slams the ground, inflicting $322239s1 Nature damage to players within $322239a1 yards of impact. If this attack does not hit any players, it inflicts $322240s1 Nature damage to the party.", ua = "Злоякісне поріддя гатить об землю, завдаючи $322239s1 шкоди від сил природи гравцям у межах $322239a1 ярд. від місця влучання. Якщо ця атака не вражає жодного гравця, вона завдає $322240s1 шкоди від сил природи групі." },
    { en = "Kryxis the Voracious charges a targeted player, hitting any players between him and the targeted player for $319715s1 Physical damage, split between every player hit, and knocking them back.", ua = "Криксіс Ненажерливий кидається на позначеного гравця, влучаючи в усіх гравців між ним і позначеним гравцем на $319715s1 фізичної шкоди, розподіленої між кожним ураженим гравцем, і відкидає їх назад." },
    { en = "Kryxis the Voracious headbutts his current target, inflicting $s1 Physical damage and knocking them back.", ua = "Криксіс Ненажерливий б'є головою свою поточну ціль, завдаючи $s1 фізичної шкоди й відкидаючи її." },
    { en = "Kryxis the Voracious pulls $@spellname319684 from each player. If Kryxis the Voracious touches them, he is healed for $319688s1% of his maximum health and gains an application of $@spellname319657. If reabsorbed by a player, it inflicts $319687s1 Shadow damage to them.", ua = "Криксіс Ненажерливий витягує $@spellname319684 з кожного гравця. Якщо Криксіс Ненажерливий торкається її, він зцілюється на $319688s1% свого максимального здоров'я і отримує застосування $@spellname319657. Якщо її повторно поглинає гравець, вона завдає йому $319687s1 тіньової шкоди." },
    { en = "At 100 Energy, Kryxis the Voracious emits a massive wave of force outwards, inflicting $s1 Shadow damage and knocking back all players. Each player leaves an orb of $@spellname319684 behind.", ua = "За 100 енергії Криксіс Ненажерливий випускає назовні потужну хвилю сили, завдаючи $s1 тіньової шкоди і відкидаючи всіх гравців. Кожен гравець лишає по собі сферу $@spellname319684." },
    { en = "Kryxis the Voracious drains the essence out of all nearby players, inflicting $319655s1 Shadow damage and giving Kryxis the Voracious an application of $@spellname319657 every $t1 sec for $d. This effect stacks.", ua = "Криксіс Ненажерливий висмоктує есенцію з усіх гравців поблизу, завдаючи $319655s1 тіньової шкоди й надаючи Криксісу Ненажерливому стак $@spellname319657 кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Kryxis the Voracious is empowered when consuming essence, increasing damage done by $s1% for $d. This effect stacks.", ua = "Криксіс Ненажерливий підсилюється, поглинаючи есенцію, що збільшує завдавану шкоду на $s1% упродовж $d. Цей ефект накопичується." },
    { en = "Executor Tarvold creates an orb of anima that orbits the prison.  Touching an orb inflicts $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d.  In addition, the target's haste is reduced by $s3% for the duration.", ua = "Кат Тарвольд створює сферу аніми, що кружляє довкола в'язниці. Дотик до сфери завдає $s1 тіньової шкоди та додатково $s2 тіньової шкоди кожні $t2 сек. протягом $d. Крім того, поспіх цілі знижується на $s3% на час дії." },
    { en = "Executor Tarvold unleashes an imprisoned Fleeting Manifestation.", ua = "Кат Тарвольд вивільняє ув'язнену Швидкоплинну Маніфестацію." },
    { en = "Executor Tarvold torments a player causing waves of energy to emanate from them, inflicting $s1 Shadow damage to all players within $A1 yards of the target.", ua = "Кат Тарвольд мучить гравця, змушуючи хвилі енергії розходитися від нього, завдаючи $s1 тіньової шкоди всім гравцям у межах $A1 м від цілі." },
    { en = "While alive, each Fleeting Manifestation inflicts $324659s1 Shadow damage to all players every $323548t1 sec.", ua = "Поки живе, кожне Швидкоплинне Втілення завдає $324659s1 тіньової шкоди всім гравцям кожні $323548t1 сек." },
    { en = "Upon death the Fleeting Manifestation erupts, creating a pool of raw sin. The size of the pool is increased based on the manifestation's energy. Standing within the pool inflicts $s1 Shadow damage every $t1 sec.", ua = "Гинучи, Швидкоплинне Втілення вибухає, створюючи калюжу неприкритого гріха. Розмір калюжі збільшується залежно від енергії втілення. Стояння в калюжі завдає $s1 тіньової шкоди кожні $t1 сек." },
    { en = "Z'rali unleashes $s3 fragments of her power. Any player that touches a fragment reduces the damage taken from $@spellname325360 by $s1%. Stacking up to $s2 times.", ua = "З'ралі вивільняє $s3 фрагментів своєї сили. Будь-який гравець, що торкнеться фрагмента, знижує шкоду, отриману від $@spellname325360, на $s1%. Накопичується до $s2 разів." },
    { en = "Grand Proctor Beryllia summons forth $s2 $@spellname325254 that impale her current target over $d.  Each spike inflicts $325260s1 Physical damage.", ua = "Велика Наглядачка Берилія прикликає $s2 $@spellname325254, що протягом $d протинають її поточну ціль. Кожен шпичак завдає $325260s1 фізичної шкоди." },
    { en = "Z'rali creates an area of safety that reduces the damage taken of the first player to touch the zone by $324092s1% and making them immune to $@spellname328593 for up to $d.", ua = "Z'rali створює зону безпеки, що зменшує отримувану шкоду першого гравця, який її торкнеться, на $324092s1% і робить його несприйнятливим до $@spellname328593 на час до $d." },
    { en = "Grand Proctor Beryllia unleashes a blast of stored anima inflicting $s1 Shadow damage and applying $@spellname328593 to all players.", ua = "Велика Наглядачка Берилія вивільняє вибух накопиченої аніми, завдаючи $s1 тіньової шкоди і накладаючи $@spellname328593 на всіх гравців." },
    { en = "Grand Proctor Beryllia brands a player with a painful mark, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Велика наглядачка Беріллія таврує гравця болісною міткою, завдаючи $s1 шкоди від темряви кожні $t1 с протягом $d." },
    { en = "Grand Proctor Beryllia unleashes a torrent of anima into Z'rali, causing her to release waves of pain that inflict $328673s1 Holy damage to all players and unleash $@spellname325885 every $t1 sec for $d.", ua = "Велика Наглядачка Берилія вивільняє потік аніми в Z'rali, через що та випускає хвилі болю, що завдають $328673s1 священної шкоди всім гравцям, і вивільняє $@spellname325885 кожні $t1 с протягом $d." },
    { en = "Bolts of holy light burst from Z'rali, inflicting $s1 Holy damage to all players within $a1 yards of the impact and an additional $s2 Holy damage every $t2 sec for $d.", ua = "Спалахи священного світла вириваються з Z'rali, завдаючи $s1 священної шкоди всім гравцям у межах $a1 м від влучання і додатково $s2 священної шкоди кожні $t2 с протягом $d." },
    { en = "General Kaal creates an afterimage of herself which rushes forward with preternatural speed, inflicting $s2 Physical damage to all players in a line in front of them.", ua = "Генерал Каал створює власне залишкове зображення, що мчить уперед із надприродною швидкістю, завдаючи $s2 фізичної шкоди всім гравцям у лінії перед собою." },
    { en = "General Kaal marks multiple players to charge. After a few seconds, she rushes to each, attacking all players  within $322796A1 yards of the charged player's location with $@spellname322796.", ua = "Генерал Каал позначає кількох гравців для ривка. За кілька секунд вона кидається до кожного, атакуючи всіх гравців у межах $322796A1 ярдів від місця позначеного гравця за допомогою $@spellname322796." },
    { en = "General Kaal tears in to the player, inflicting $s1 Physical damage and causes them to bleed for $s2 Physical damage every $t2 sec for $d.", ua = "Генерал Каал розриває гравця, завдаючи $s1 фізичної шкоди та змушуючи його стікати кров'ю, завдаючи $s2 фізичної шкоди кожні $t2 с впродовж $d." },
    { en = "At 100 Energy, General Kaal releases a large powerful blast of anima-infused wind, inflicting $322903s1 Shadow damage and knocking all enemies back.", ua = "При 100 енергії генерал Каал вивільняє потужний вибух просякнутого анімою вітру, завдаючи $322903s1 тіньової шкоди та відкидаючи всіх ворогів." },
    { en = "Channel Z'rali's essence, creating a barrier around you, reducing damage taken by $324092s1% to all nearby allies, removing applications of $@spellname327814 and making them immune to knockbacks.", ua = "Підтримує есенцію Z'rali, створюючи навколо вас бар'єр, що знижує отримувану шкоду всіх союзників поблизу на $324092s1%, знімає застосування $@spellname327814 і робить їх несприйнятливими до відкидань." },
    { en = "General Kaal tears in to the player, inflicting $s1 Physical damage and causes them to bleed for $s2 Physical damage every $t2 sec until the end of the encounter.", ua = "Генерал Каал роздирає гравця, завдаючи $s1 фізичної шкоди і змушуючи його кровоточити, отримуючи $s2 фізичної шкоди кожні $t2 с до кінця бою." },
    { en = "Kin-Tara slashes out, inflicting a massive amount of Physical damage to her primary target.", ua = "Кін-Тара завдає удару, спричиняючи величезну фізичну шкоду своїй основній цілі." },
    { en = "Kin-Tara hurls a charged spear at the target that inflicts $321034s1 Arcane damage to all players within $321034A1 yards of the impact and creates a zone of Ionized Plasma.\n\n\n\nPlayers standing in Ionized Plasma take $324662s1 Arcane damage every $324662t1 sec. and have their movement speed reduced by $32466s2%.", ua = "Кін-Тара жбурляє в ціль заряджений спис, що завдає $321034s1 арканної шкоди всім гравцям у межах $321034A1 ярдів від місця влучання та створює зону Іонізованої Плазми.\n\n\n\nГравці в Іонізованій Плазмі отримують $324662s1 арканної шкоди кожні $324662t1 с, а їхня швидкість руху знижується на $32466s2%." },
    { en = "Azules fires multiple missiles of Arcane energy that inflict $s1 Arcane damage to players caught in their path.", ua = "Азулес випускає кілька снарядів арканної енергії, що завдають $s1 арканної шкоди гравцям на їхньому шляху." },
    { en = "The bond between Kin-Tara and Azules manifests as a beam of energy. Any player caught in the beam suffers $331251s1 Arcane damage every $331251t1 sec. for $331251d1. \n\n\n\nThis effect stacks.", ua = "Зв'язок між Кін-Тарою та Азулесом проявляється як промінь енергії. Будь-який гравець, що потрапив у промінь, зазнає $331251s1 арканної шкоди кожні $331251t1 сек. протягом $331251d1. \n\n\n\nЦей ефект накопичується." },
    { en = "When either combatant dies, their remaining ally enrages, increasing their damage dealt by $s1% and unlocking new abilities.", ua = "Коли гине один із бійців, його союзник, що лишився, шаленіє, збільшуючи завдавану шкоду на $s1% і відкриваючи нові здібності." },
    { en = "Azules' venom inflicts $s1 Arcane damage every $t1 sec. for $d.", ua = "Отрута Азулеса завдає $s1 арканної шкоди кожні $t1 с протягом $d." },
    { en = "Kin-Tara hurls lances of dark energy at nearby players that inflict $s1 Arcane damage every $t1 sec. for $d.", ua = "Кін-Тара жбурляє списи темної енергії в довколишніх гравців, які завдають $s1 арканної шкоди кожні $t1 с. протягом $d." },
    { en = "Azuels fires several orbs in a straight line that will form pools of Maw-Touched Venom on impact.\n\nPlayers standing in these pools suffer $317626s1 Arcane damage every$317626t1 sec.", ua = "Азуель випускає кілька сфер по прямій лінії, які при падінні утворюють калюжі Отрути, торкнутої Пащею.\n\nГравці, що стоять у цих калюжах, зазнають $317626s1 арканної шкоди кожні$317626t1 с." },
    { en = "Azoras fires multiple missiles of Arcane energy that inflict $s1 Arcane damage to players caught in their path.", ua = "Азорас випускає кілька снарядів арканної енергії, що завдають $s1 арканної шкоди гравцям на своєму шляху." },
    { en = "Each Dark Bolt from a Shadowhirl inflicts $s1 Shadow damage and knocks up any players they touch.", ua = "Кожен темний снаряд від Тіньовиру завдає $s1 тіньової шкоди й підкидає в повітря гравців, яких торкається." },
    { en = "Ventunax creates a flash of light, stunning players within a frontal cone for $d.", ua = "Вентунакс створює спалах світла, оглушуючи гравців у передньому конусі на $d." },
    { en = "Moving with incredible speed, Ventunax appears behind a player and inflicts $324154s1 Physical damage every second for $324154d.\n\n\n\nAdditionally, Ventunax leaves a Shadowhirl behind.", ua = "Рухаючись із неймовірною швидкістю, Вентунакс з'являється позаду гравця й завдає $324154s1 фізичної шкоди щосекунди протягом $324154d.\n\n\n\nКрім того, Вентунакс залишає по собі Тіньовир." },
    { en = "Ventunax restores $s1% energy every $t sec for $d.\n\n\n\nAdditionally, all Shadowhirls erupt for $d.", ua = "Вентунакс відновлює $s1% енергії кожні $t с протягом $d.\n\n\n\nКрім того, усі Тіньовири вивільняються протягом $d." },
    { en = "Ventunax's incredibly fast movements leave Shadowhirls in her wake.\n\n\n\nEach Shadowhirl emits Dark Bolts, and a burst of Dark Bolts whenever Ventunax recovers energy.", ua = "Неймовірно швидкі рухи Вентунакс лишають по собі тіньовиховори.\n\n\n\nКожен тіньовиховор випускає темні стріли, а також спалах темних стріл щоразу, коли Вентунакс відновлює енергію." },
    { en = "Oryphrion stomps their current target, inflicting $s1 Arcane damage and applying Charged Anima to all players within $A1 yards of the impact.", ua = "Оріфріон тупає по своїй поточній цілі, завдаючи $s1 арканної шкоди та накладаючи Заряджену аніму на всіх гравців у межах $A1 м від влучання." },
    { en = "Oryphrion is drained of Anima, their damage taken is increased by $s1%, and they stop attacking to recharge.", ua = "Оріфріон позбувається Аніми, отримувана ним шкода збільшується на $s1%, і він припиняє атакувати, щоб перезарядитися." },
    { en = "Harmful anima charges the player's body, reducing movement speed by $s1%.", ua = "Шкідлива аніма наповнює тіло гравця, зменшуючи швидкість пересування на $s1%." },
    { en = "Harmful anima charges the player's body, reducing movement speed by $s1% and inflicting $s2 Arcane damage every $t2 sec. for $d.", ua = "Шкідлива аніма наповнює тіло гравця, зменшуючи швидкість пересування на $s1% і завдаючи $s2 арканної шкоди кожні $t2 сек. протягом $d." },
    { en = "Touching Coalesced Anima causes it to burst, inflicting $s1 Arcane damage to players in $a1 yards.", ua = "Дотик до Згуслої Аніми спричиняє її вибух, завдаючи $s1 арканної шкоди гравцям у радіусі $a1 м." },
    { en = "Oryphrion generates $s1 Anima every $t1 sec. for $d. In addition, all Anima Fields form into Coalesced Anima.", ua = "Оріфріон генерує $s1 аніми кожні $t1 с протягом $d. Крім того, усі поля аніми формуються у згущену аніму." },
    { en = "Oryphrion instantly energizes for $324317s1 Anima and bursts with overcharge, inflicting $s1 Arcane damage to all players.", ua = "Оріфріон миттєво наповнюється енергією на $324317s1 аніми й вибухає перенасиченням, завдаючи $s1 арканної шкоди всім гравцям." },
    { en = "Oryphrion fires their cannon towards a player, inflicting $s1 Arcane damage on impact, and $s2 Arcane damage every $t2 sec. for $d to players within $A1 yards of the impact.", ua = "Оріфріон стріляє з гармати в гравця, завдаючи $s1 арканної шкоди при влучанні та $s2 арканної шкоди щосекунди ($t2 сек.) протягом $d гравцям у межах $A1 ярдів від місця влучання." },
    { en = "$@spelldesc323372\n\n\n\nLeaves an Anima Field behind.", ua = "$@spelldesc323372\n\n\n\nЗалишає по собі Поле Аніми." },
    { en = "Touching Coalesced Anima causes it to burst, inflicting $s1 Arcane damage to players in $a1 yards, and $s2 Arcane damage every $t2 sec. for $d.", ua = "Дотик до Згущеної аніми спричиняє її вибух, завдаючи $s1 арканної шкоди гравцям у межах $a1 ярдів і $s2 арканної шкоди кожні $t2 сек. упродовж $d." },
    { en = "Devos creates a concentrated nexus of maw anima that explodes after $334626d., inflicting $s1 Arcane damage to all players within $A1 yards.", ua = "Девос створює сконцентрований нексус аніми Пащі, який вибухає через $334626d, завдаючи $s1 арканної шкоди всім гравцям у межах $A1 ярд." },
    { en = "Devos infects a random player's mind with doubt for $s1 Arcane damage every $t1 sec. for $d.  When this effect ends, a pool of $@spellname322817 forms at the victim's feet.\n\n\n\nPlayers standing in the pool of $@spellname322817 gain a stack of Lingering Doubt every 1 sec. for $322816d.", ua = "Девос отруює розум випадкового гравця сумнівом, завдаючи $s1 арканної шкоди кожні $t1 с впродовж $d. Коли цей ефект завершується, біля ніг жертви утворюється калюжа $@spellname322817.\n\n\n\nГравці, що стоять у калюжі $@spellname322817, кожну 1 с отримують заряд Стійкого Сумніву впродовж $322816d." },
    { en = "Your doubt grows within you, inflicting $s1 Arcane damage every $t1 sec. for $d.", ua = "Сумнів зростає всередині вас, завдаючи $s1 арканної шкоди кожні $t1 с впродовж $d." },
    { en = "Devos activates the Anima Conduit, inflicting $323011s1 Arcane damage to all players.", ua = "Девос активує Канал Аніми, завдаючи $323011s1 арканної шкоди всім гравцям." },
    { en = "Devos charges in a line through her target, inflicting $s2 Physical damage to all players in her path.", ua = "Девос мчить по прямій крізь свою ціль, завдаючи $s2 фізичної шкоди всім гравцям на своєму шляху." },
    { en = "Hurl the Archon's Spear at Devos, inflicting $322958s1% of her total health on a successful hit and forcing her to return to the ground once more.", ua = "Жбурніть Спис Архонта в Девос, завдаючи при влучанні шкоди в розмірі $322958s1% її загального здоров'я та змушуючи її знову повернутися на землю." },
    { en = "Strong winds pull all players and anima off the front of the platform.  While the winds persist, all players gain an application of Lingering Doubt every 6 sec.", ua = "Сильні вітри стягують усіх гравців та всю аніму з переднього боку платформи. Поки вітри тривають, усі гравці отримують накладення Тривкого Сумніву кожні 6 с." },
    { en = "Pick up a fragment of Raw Anima. Return it to the Anima Conduit to help unlock the Archon's Spear.", ua = "Підберіть фрагмент Сирої Аніми. Поверніть його до Провідника Аніми, щоб допомогти відкрити Спис Архонта." },
    { en = "Strong winds push all players and anima to the back of the platform. While the winds persist, all players gain an application of Lingering Doubt every 6 sec.", ua = "Сильні вітри відштовхують усіх гравців і аніму до тильної частини платформи. Поки вітри тривають, усі гравці отримують застосування ефекту «Затяжний Сумнів» кожні 6 с." },
    { en = "Kyrestia, the Firstborne creates a barrier that protects all players within its confines, reducing the damage taken from the next Abyssal Detonation by $335805s1%.", ua = "Кірестія Первородна створює бар'єр, що захищає всіх гравців у його межах, зменшуючи шкоду, отриману від наступної Безодньої Детонації, на $335805s1%." },
    { en = "Zo'phex replenishes the limbs of his torso, increasing Physical damage done by $s2%.", ua = "Зо'фекс відновлює кінцівки свого торсу, збільшуючи завдану фізичну шкоду на $s2%." },
    { en = "The target of Zo'phex's Interrogation is contained within a Containment Cell. Destroying the Cell ends the Interrogation and triggers a Security Measure.", ua = "Ціль Допиту Зо'фекса ув'язнено в Стримувальній Камері. Знищення Камери завершує Допит і запускає Запобіжний Захід." },
    { en = "Zo'phex confiscates a player's weapon, silencing and pacifying them until they retrieve it.", ua = "Зо'фекс конфісковує зброю гравця, накладаючи мовчання та упокорення, доки той її не поверне." },
    { en = "Retrieving your weapon emboldens you, increasing Haste by $s1% for $d.", ua = "Повернення зброї додає вам відваги, підвищуючи Поспіх на $s1% на $d." },
    { en = "The Containment Cell initiates a final security measure upon collapsing, inflicting $s1 Arcane damage to all players.", ua = "Стримувальна Камера під час руйнування запускає останній захід безпеки, завдаючи $s1 арканної шкоди всім гравцям." },
    { en = "Zo'phex charges up his swords and unleash a massive slash, inflicting $s2 Physical damage to all enemies in front of him.", ua = "Зо'фекс заряджає свої мечі та вивільняє нищівний удар, завдаючи $s2 фізичної шкоди всім ворогам перед собою." },
    { en = "Zo'phex's arms detach from his torso and begin to whirl violently, inflicting $348366s1 Physical damage every $348366t1 sec to nearby players within 6 yds.", ua = "Руки Зо'фекса від'єднуються від тулуба й починають несамовито обертатися, завдаючи $348366s1 фізичної шкоди кожні $348366t1 с гравцям поблизу в радіусі 6 м." },
    { en = "Zo'phex fixates a marked player for Interrogation, detaining them within a Containment Cell while slowly advancing towards them.\n\n\n\nWhile advancing, Zo'phex's blades inflict $346028s1 Arcane damage directly in front of the caster.", ua = "Зо'фекс зосереджується на позначеному гравцеві для Допиту, утримуючи його в Камері Утримання й повільно наближаючись до нього.\n\n\n\nПід час наближення клинки Зо'фекса завдають $346028s1 арканної шкоди прямо перед тим, хто творить." },
    { en = "Achillite afflicts $s2 players with unstable anima, inflicting $s1 Holy damage every $t1 sec for $d. Explodes upon expiration, inflicting $350468s1 Holy damage to all players within $350468A1 yards.", ua = "Ахілліт уражає $s2 гравців нестабільною анімою, завдаючи $s1 священної шкоди кожні $t1 с протягом $d. Після завершення вибухає, завдаючи $350468s1 священної шкоди всім гравцям у радіусі $350468A1 м." },
    { en = "Achillite vents its anima core, releasing Volatile Anima and inflicting $351070s1 Holy damage and knocking back all players within $351070A1 yards.", ua = "Ахілліт випускає своє ядро аніми, вивільняючи Нестабільну Аніму, завдаючи $351070s1 священної шкоди і відкидаючи всіх гравців у радіусі $351070A1 м." },
    { en = "Alcruux creates waves of consuming orbs that explode after $s2 sec, leeching $s1 health from all players within $A1 yards.", ua = "Алкрукс створює хвилі поглинальних сфер, які вибухають за $s2 сек., висмоктуючи $s1 здоров'я з усіх гравців у межах $A1 ярдів." },
    { en = "Explodes on contact with a player, inflicting $349999s1 Holy damage to players within $349999A1 yds and decreasing their damage done by $349999s2% for $d. This effect stacks.", ua = "Вибухає при дотику до гравця, завдаючи $349999s1 священної шкоди гравцям у радіусі $349999A1 ярд. і зменшуючи завдавану ними шкоду на $349999s2% протягом $d. Цей ефект накопичується." },
    { en = "Venza whirls madly with the Edge of Annihilation, drawing all players towards her and inflicting $s1 Physical damage every $350086t1 sec to all players within $A1 yards.", ua = "Венза несамовито крутиться з Лезом Знищення, притягуючи всіх гравців до себе і завдаючи $s1 фізичної шкоди кожні $350086t1 сек усім гравцям у межах $A1 ярдів." },
    { en = "Achillite begins pummeling its target, inflicting $s1 Physical damage every $349934t1 sec for $349934d.", ua = "Ахілліт починає молотити свою ціль, завдаючи $s1 фізичної шкоди кожні $349934t1 с протягом $349934d." },
    { en = "Venza chains a random player in place, inflicting $s3 Physical damage every $t3 sec and decreasing their speed by $s2% until the chains are destroyed.", ua = "Венза приковує випадкового гравця на місці, завдаючи $s3 фізичної шкоди кожні $t3 сек і зменшуючи його швидкість на $s2%, доки ланцюги не буде знищено." },
    { en = "Increases all damage done by $s1%. This effect stacks.", ua = "Збільшує всю завдану шкоду на $s1%. Цей ефект накопичується." },
    { en = "Alcruux afflicts the nearest player with the essence of hunger for $d, allowing them to safely absorb volatile anima but inflicting $350013s1 Shadow damage every $350013t1 sec to all other players within $s4 yards.\n\n\n\nUpon expiration, $@spellname349627 is transfered to the nearest other player.", ua = "Алкрукс уражає найближчого гравця есенцією голоду на $d, дозволяючи йому безпечно поглинати нестабільну аніму, але завдаючи $350013s1 тіньової шкоди кожні $350013t1 с усім іншим гравцям у межах $s4 ярдів.\n\n\n\nПісля завершення $@spellname349627 передається наступному найближчому гравцеві." },
    { en = "Alcruux pulls all players to his location, then strikes with explosive force inflicting $s1 Shadow damage to all players within $a1 yards.", ua = "Алкрукс притягує всіх гравців до себе, а тоді б'є з вибуховою силою, завдаючи $s1 тіньової шкоди всім гравцям у межах $a1 ярдів." },
    { en = "The P.O.S.T. Master activates the central mail portal, releasing packages of Unstable Goods that explode if not delivered within $346296d.\n\n\n\nPlayers can pick up Unstable Goods, reducing movement speed by $346403s2% and granting the Throw Package ability.", ua = "Поштмейстер активує центральний поштовий портал, випускаючи пакунки Нестабільних товарів, які вибухають, якщо їх не доставити протягом $346296d.\n\n\n\nГравці можуть підбирати Нестабільні товари, що зменшує швидкість пересування на $346403s2% і надає здібність Кинути пакунок." },
    { en = "Throw your package of Unstable Goods at the target location.\n\n\n\nThe package must land in an active Delivery Portal or be caught by another player to avoid an Unstable Explosion.", ua = "Кидає ваш пакунок Нестабільного товару в цільову точку.\n\n\n\nПакунок має приземлитися в активному Порталі доставки або бути впійманим іншим гравцем, щоб уникнути Нестабільного вибуху." },
    { en = "Spilled liquids inflict $s1 Arcane damage every $t1 sec and reduce movement speed by $s2% for players standing within them.", ua = "Розлиті рідини завдають $s1 арканної шкоди кожні $t1 сек. і зменшують швидкість пересування на $s2% гравцям, що в них стоять." },
    { en = "The P.O.S.T. Master activates the central mail portal, releasing a shipment of Hazardous Liquids that spill on the floor unless caught by players.", ua = "Поштмейстер P.O.S.T. активує центральний поштовий портал, вивільняючи партію небезпечних рідин, що розливаються по підлозі, якщо їх не перехоплять гравці." },
    { en = "The P.O.S.T. Master drops a ton of gold on a player, inflicting $346967s1 Physical damage to players within $346967A1 yds, split evenly between all players hit.", ua = "Поштмейстер скидає купу золота на гравця, завдаючи $346967s1 фізичної шкоди гравцям у межах $346967A1 ярд., порівну розподіленої між усіма ураженими гравцями." },
    { en = "The P.O.S.T. Master goes haywire, firing letters in every direction that inflict $346294s1 Physical damage every $t1 sec to all players for $d.", ua = "Поштмейстер П.О.Ш.Т.А. шаленіє й випускає листи на всі боки, завдаючи $346294s1 фізичної шкоди кожні $t1 с усім гравцям протягом $d." },
    { en = "Unstable Goods explode if dropped, or if they're not delivered within $346296d.\n\n\n\nInflicts $s1 Fire damage to all players, plus an additional $s2 Fire damage every $t2 sec for $d.", ua = "Нестабільний товар вибухає, якщо його впустити або не доставити впродовж $346296d.\n\n\n\nЗавдає $s1 вогняної шкоди всім гравцям, плюс додаткові $s2 вогняної шкоди кожні $t2 сек. упродовж $d." },
    { en = "Players who catch Hazardous Liquids are covered in residue, inflicting $s1 Arcane damage every $t1 sec for $d. This effect stacks.", ua = "Гравці, що ловлять Небезпечні рідини, вкриваються залишком, який завдає $s1 арканної шкоди щосекунди ($t1) протягом $d. Цей ефект накопичується." },
    { en = "Unruly Patrons throw disgusting refuse that inflicts $356482s1 Nature damage to players within $A1 yds of the impact location.", ua = "Буйні гуляки кидають огидні покидьки, що завдають $356482s1 шкоди від сил природи гравцям у радіусі $A1 м від місця влучання." },
    { en = "Perform an improvisation on the horn to hit notes within $A1 yds. Each note grants the performer an application of $@spellname348567.", ua = "Зіграйте імпровізацію на ріжку, влучаючи в ноти в межах $A1 м. Кожна нота дає виконавцю застосування $@spellname348567." },
    { en = "The caster throws a drink in a player's face, inflicting $s1 Physical damage.", ua = "Заклинач кидає напій в обличчя гравцю, завдаючи $s1 фізичної шкоди." },
    { en = "Hitting a note increases haste by $s1% for $d. This effect stacks.", ua = "Влучання в ноту підвищує поспіх на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Upon reaching 100 rage speakeasy patrons become rowdy, increasing damage done by $s2%.", ua = "Досягнувши 100 люті, відвідувачі шинку буянять, збільшуючи завдану шкоду на $s2%." },
    { en = "The caster channels to suppress a player for $d, inflicting $s1 Arcane damage every $t1 sec and reducing their movement speed by $s2%.", ua = "Той, хто творить, підтримує закляття, щоб придушити гравця на $d, завдаючи $s1 арканної шкоди кожні $t1 сек. і зменшуючи його швидкість пересування на $s2%." },
    { en = "The caster inflicts $s1 Arcane damage to a player.", ua = "Той, хто творить, завдає $s1 арканної шкоди гравцю." },
    { en = "Zo'gron surrounds himself in a barrier that absorbs incoming damage while casting Final Warning. Upon completion, the barrier pulses $1258336s1 Arcane damage to all players every $1241032t1 sec until it is destroyed.", ua = "Зо'ґрон оточує себе бар'єром, що поглинає вхідну шкоду, поки творить Останнє Попередження. Після завершення бар'єр пульсує $1258336s1 арканної шкоди всім гравцям кожні $1241032t1 сек, доки його не знищать." },
    { en = "The caster clobbers their target with a hammer, inflicting $s1 Physical damage.", ua = "Творець гамселить ціль молотом, завдаючи $s1 фізичної шкоди." },
    { en = "Play the drums to hit notes around the drumset. Each note grants the performer an application of $@spellname348567.", ua = "Грайте на барабанах, щоб влучати в ноти навколо ударної установки. Кожна нота дає виконавцеві один заряд $@spellname348567." },
    { en = "Zo'gron deflects all attacks and spells from the front for $d.\n\n\n\nWhen the guard ends, Zo'gron inflicts $350921s1 Arcane damage to all players in a frontal cone and knocks them back.", ua = "Зо'грон відбиває всі атаки та закляття спереду протягом $d.\n\n\n\nКоли захист завершується, Зо'грон завдає $350921s1 арканної шкоди всім гравцям у фронтальному конусі та відкидає їх назад." },
    { en = "Inflicts $s2 Physical damage to all players and interrupts spellcasting for $d. Ignores armor.", ua = "Завдає $s2 фізичної шкоди всім гравцям і перериває творіння заклять на $d. Ігнорує броню." },
    { en = "Slide forward $s1 yds, hitting notes along the way. Each note grants the performer an application of $@spellname348567.", ua = "Ковзає вперед на $s1 ярдів, влучаючи в ноти на шляху. Кожна нота дає виконавцю один заряд $@spellname348567." },
    { en = "Gaining $s5 applications of $@spellname348567 increases damage and healing by $s2% and haste by $s1% for $d. \n\n\n\nRemoves all applications of $@spellname348567. Hitting a note while $@spellname358311 is active refreshes its duration.", ua = "Отримання $s5 накопичень $@spellname348567 збільшує шкоду й зцілення на $s2%, а поспіх — на $s1% протягом $d.\n\n\n\nЗнімає всі накопичення $@spellname348567. Влучання по ноті, поки активне $@spellname358311, оновлює його тривалість." },
    { en = "Zo'gron pulls players towards his location, creating an opportune moment for a group performance.\n\n\n\nAfter $355437d each player inflicts $355440s1 Arcane damage to allies within $355440A1 yards.", ua = "Зо'ґрон притягує гравців до себе, створюючи слушну мить для групового виступу.\n\n\n\nЧерез $355437d кожен гравець завдає $355440s1 арканної шкоди союзникам у межах $355440A1 м." },
    { en = "Teleports to a nearby location.", ua = "Телепортується до місця поблизу." },
    { en = "So'azmi deploys pairs of Relocators to confuse his enemies.\n\nWhen a player touches a Relocator, they are instantly teleported to the other Relocator that matches it.", ua = "Со'азмі розставляє пари Переміщувачів, щоб заплутати ворогів.\n\nКоли гравець торкається Переміщувача, його миттєво телепортує до парного Переміщувача." },
    { en = "Upon reaching $s1% and $s2% health, So'azmi divides the area with a barrier that players are unable to move or target through.", ua = "Досягнувши $s1% та $s2% здоров'я, Со'азмі розділяє ділянку бар'єром, крізь який гравці не можуть ні пройти, ні вибрати ціль." },
    { en = "So'Azmi uses his secret two-part technique.\n\nUpon completion he hurls burning blades at all players, inflicting $s1 Fire damage every $t1 sec for $d.\n\nThis spell must be interrupted ${$357189N} times to prevent it from casting.", ua = "Со'Азмі застосовує свою таємну техніку з двох частин.\n\nПо завершенні він метає палаючі клинки в усіх гравців, завдаючи $s1 од. шкоди від вогню кожні $t1 с протягом $d.\n\nЦе закляття треба перервати ${$357189N} раз(и), щоб не дати йому завершитися." },
    { en = "So'azmi steps into the shadow and slashes 3 random players, inflicting $s1 Physical damage and causing them to bleed for $s2 Physical damage every $t2 sec for $d.", ua = "Со'азмі ступає в тінь і шматує 3 випадкових гравців, завдаючи $s1 фізичної шкоди та змушуючи їх стікати кров'ю, що завдає $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "So'Azmi creates an expanding ring of Arcane energy that causes players caught in its path to suffer $s1 Arcane damage every $t1 sec for $d.", ua = "Со'азмі створює розширюване кільце арканної енергії, що завдає гравцям на його шляху $s1 арканної шкоди кожні $t1 с протягом $d." },
    { en = "Hylbrande creates a ball of energy and splits it into 3 missiles, striking enemies for $s1 Holy damage.", ua = "Гілбранд створює кулю енергії та розділяє її на 3 снаряди, що вражають ворогів, завдаючи $s1 священної шкоди." },
    { en = "Hylbrande takes two consecutive swings at his primary target, inflicting $346876s1 Physical damage, and then $346876s1 Physical damage.", ua = "Гілбранд завдає двох послідовних ударів по основній цілі, завдаючи $346876s1 фізичної шкоди, а потім ще $346876s1 фізичної шкоди." },
    { en = "Vault Purifiers channel energy into Hylbrande, reducing all damage taken by $s1%.", ua = "Очисники Сховища спрямовують енергію в Гілбранда, зменшуючи всю отримувану шкоду на $s1%." },
    { en = "The Vault Purifier blasts a target with energy, inflicting $s1 Holy damage.", ua = "Очисник Сховища вражає ціль енергією, завдаючи $s1 священної шкоди." },
    { en = "Hylbrande orders a turret to focus intense energy towards a player's feet, inflicting $346960s2 Holy damage every $t1 sec to players who remain in the area, and leaving behind a Purging Field.", ua = "Гілбранд наказує турелі сфокусувати потужну енергію під ногами гравця, завдаючи $346960s2 священної шкоди щосекунди ($t1) гравцям, які лишаються в зоні, і лишаючи по собі Очисне Поле." },
    { en = "Hylbrande slams his sword down, inflicting $s1 Physical damage to all players in front of him and stunning them for $d.", ua = "Гілбранд опускає свій меч додолу, завдаючи $s1 фізичної шкоди всім гравцям перед собою та приголомшуючи їх на $d." },
    { en = "The Vault Purifier channels a protective shield on a security panel, blocking interaction.", ua = "Очисник Сховища скеровує захисний щит на панель безпеки, блокуючи взаємодію." },
    { en = "Accessing the Titan Console reveals override inputs for Security Panels around the room for $d.", ua = "Доступ до Титанічної консолі на $d відкриває важелі перевизначення для Панелей безпеки по всій кімнаті." },
    { en = "Inputting the wrong Bypass Code into a Security Panel inflicts $s1 Holy damage and stuns the player for $d.", ua = "Введення хибного коду обходу до панелі безпеки завдає $s1 священної шкоди і приголомшує гравця на $d." },
    { en = "Timecap'n Hooktail attaches $@spellname1240102 to $s1 players increasing their haste by $s2% but also inflicting $1240099s1 Arcane damage every $t1 sec for $d. $@spellname1240097's damage is increased by $s4% every time it inflicts damage. \n\n\n\nUpon removal a $@spellname1240105 is unleashed inflicting $1240105s1 Arcane damage to all players.", ua = "Часокапітан Гуктейл чіпляє $@spellname1240102 до $s1 гравців, підвищуючи їхній поспіх на $s2%, але водночас завдаючи $1240099s1 арканної шкоди кожні $t1 сек. протягом $d. Шкода $@spellname1240097 збільшується на $s4% щоразу, коли вона завдає шкоди.\n\n\n\nПісля зняття вивільняється $@spellname1240105, завдаючи $1240105s1 арканної шкоди всім гравцям." },
    { en = "Inflicts $s1 Fire damage every $t1 sec to players standing in the flames.", ua = "Завдає $s1 вогняної шкоди кожні $t1 с гравцям, що стоять у полум'ї." },
    { en = "Removing $@spellname1240099 causes a $@spellname1240105 inflicting $s1 Arcane damage to all players.", ua = "Зняття $@spellname1240099 спричиняє $@spellname1240105, завдаючи $s1 арканної шкоди всім гравцям." },
    { en = "Cannon fire from Hooktail's ship inflicts $s1 Fire damage to players within $A1 yds of the impact location and leaves behind a patch of Burning Tar.", ua = "Гарматний вогонь з корабля Гуктейл завдає $s1 вогняної шкоди гравцям у радіусі $A1 м від місця удару й лишає по собі пляму Палаючої Смоли." },
    { en = "Hooktail's powerful breath inflicts $s1 Arcane damage and stuns players within a frontal cone for $d1.\n\n\n\nCorsair Brutes hit by $@spellname347149 are killed instantly.", ua = "Потужний подих Гуктейл завдає $s1 арканної шкоди та приголомшує гравців у фронтальному конусі на $d1.\n\n\n\nГромили корсарів, уражені $@spellname347149, гинуть миттєво." },
    { en = "Timecap'n Hooktail increases the movement speed and attack speed of her loyal crew by $s1% every $t1 sec.", ua = "Часокапітан Гуктейл кожні $t1 с збільшує швидкість пересування та швидкість атаки своєї відданої команди на $s1%." },
    { en = "Hooktail's ship fires an anchor shot at a random player, inflicting $s1 Physical damage and dragging them towards the ship for $d1.", ua = "Корабель Гуктейла стріляє якорем у випадкового гравця, завдаючи $s1 фізичної шкоди й тягнучи його до корабля протягом $d1." },
    { en = "The seas in this area are swarming with hungry sharks. Players who linger in the water are quickly devoured.", ua = "Води в цій місцині кишать голодними акулами. Гравців, які затримуються у воді, швидко пожирають." },
    { en = "So'leah unleashes a blast of energy through all players inflicting $s1 Arcane damage in a line between each player and increasing damage taken from $@spellname350885 by $s2% for $d.\n\n\n\nStriking a relic with the blast disrupts its link with So'leah.", ua = "Со'лея вивільняє вибух енергії крізь усіх гравців, завдаючи $s1 од. шкоди від магії школи Тайнощів по лінії між кожним гравцем і збільшуючи отримувану шкоду від «$@spellname350885» на $s2% протягом $d.\n\n\n\nУдар вибуху по реліквії розриває її зв'язок із Со'леєю." },
    { en = "So'leah creates a $@spellname350796 that jumps between all players, inflicting $s1 Arcane damage.", ua = "Со'лея створює $@spellname350796, що перестрибує між усіма гравцями, завдаючи $s1 арканної шкоди." },
    { en = "So'leah links herself to the relics, drawing upon their power to reduce all damage taken by $s1% while linked.\n\n\n\nStriking a relic with $@spellname350885 disrupts its link with So'leah.", ua = "Со'лея зв'язує себе з реліквіями, черпаючи їхню силу, щоб зменшити всю отримувану шкоду на $s1%, доки триває зв'язок.\n\n\n\nУдар по реліквії закляттям «$@spellname350885» розриває її зв'язок із Со'леєю." },
    { en = "The Assassin quickly repositions and readies a volley of shurikens. Inflicts $s1 Physical damage to all players and causes them to bleed, inflicting an additional $s2 Physical damage every $t2 sec for $d.", ua = "Убивця швидко змінює позицію та готує залп сюрикенів. Завдає $s1 фізичної шкоди всім гравцям і змушує їх стікати кров'ю, завдаючи додатково $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "So'leah forms an orb containing $s1 charges of $@spellname350804 that persists for $d. Each time a player comes into contact with the $@spellname350799 it consumes a charge to apply $@spellname350804 to all players, inflicting $350804s1 Arcane damage every $350804t1 sec for $350804d.\n\n\n\nAll remaining charges of $@spellname350804 are consumed when the $@spellname350799 expires.", ua = "Со'лея створює сферу з $s1 зарядами $@spellname350804, що зберігається протягом $d. Щоразу, коли гравець торкається $@spellname350799, вона витрачає заряд, накладаючи $@spellname350804 на всіх гравців і завдаючи $350804s1 арканної шкоди кожні $350804t1 с протягом $350804d.\n\n\n\nУсі залишкові заряди $@spellname350804 витрачаються, коли $@spellname350799 завершується." },
    { en = "So'leah summons elite assassins to assist her.", ua = "Со'лея прикликає елітних убивць собі на допомогу." },
    { en = "So'leah triggers a violent reaction in a relic, releasing energy fragments in several directions. Players caught in the path of an energy fragment are knocked away and suffer $351101s1 Arcane damage and an additional $351101s2 Arcane damage every $351101t2 sec for $351101d.", ua = "Со'лея спричиняє бурхливу реакцію в реліквії, вивільняючи фрагменти енергії в кількох напрямках. Гравців, що опинилися на шляху фрагмента енергії, відкидає, і вони зазнають $351101s1 арканної шкоди та додатково $351101s2 арканної шкоди кожні $351101t2 с протягом $351101d." },
    { en = "So'leah and the relics erupt, inflicting $s1 Arcane damage to players within $a1 yds.", ua = "Со'лея та реліквії вибухають, завдаючи $s1 арканної шкоди гравцям у межах $a1 ярдів." },
    { en = "The Carrion Worm bites the target, inflicting $s1 Physical damage.\n\n\n\nAdditionally, each successful $@spellname320614 causes the worm to grow in size, permanently increasing its Physical damage done by $320630s1%. \n\n\n\nUpon reaching $s2 applications, the worm explodes in a $@spellname320631.", ua = "Трупний черв кусає ціль, завдаючи $s1 фізичної шкоди.\n\n\n\nКрім того, кожне успішне $@spellname320614 збільшує черва в розмірі, назавжди підвищуючи завдану ним фізичну шкоду на $320630s1%.\n\n\n\nДосягнувши $s2 застосувань, черв вибухає через $@spellname320631." },
    { en = "Blightbone smashes his current target, inflicting $s1 Physical damage.", ua = "Пошесткіст лупить свою поточну ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Unleashes a store of pent up gas that last for up to $320637d.  Standing within the area inflicts $s2 Nature damage every $t2 sec and prevents all actions and spell casting.", ua = "Вивільняє запас накопиченого газу, що зберігається до $320637d. Перебування в зоні дії завдає $s2 шкоди від сил природи кожні $t2 сек. і не дає виконувати жодних дій та творити закляття." },
    { en = "Blightbone hurls a toxic spew at all players in a cone in front of him, inflicting $s2 Nature damage and an additional $s3 Nature damage every $t3 sec for $d as Blightbone spews forth up to $s1 Carrion Worms.", ua = "Пошесткіст вивергає потік токсичної жижі на всіх гравців у конусі перед собою, завдаючи $s2 шкоди від сил природи та додатково $s3 шкоди від сил природи кожні $t3 сек. протягом $d, водночас випускаючи до $s1 Трупних червів." },
    { en = "The Carrion Worm explodes, spraying all players with noxious goo that inflicts $s1 Nature damage every $t1 sec for $d.", ua = "Трупний черв вибухає, оббризкуючи всіх гравців отруйною слизотою, що завдає $s1 шкоди від сил природи кожні $t1 сек. протягом $d." },
    { en = "Amarth harvests power from the deaths of enemies and allies alike. Each application inflicts $333634s1 Shadow damage to all enemies every $t1 sec.\n\n\n\nThis effect stacks.", ua = "Амарт жне силу зі смерті як ворогів, так і союзників. Кожне застосування завдає $333634s1 тіньової шкоди всім ворогам кожні $t1 с.\n\n\n\nЦей ефект накопичується." },
    { en = "Fires a bolt of ice at the target, inflicting $s1 Frost damage and applying $@spellname328664.", ua = "Випускає крижаний снаряд у ціль, завдаючи $s1 морозної шкоди і накладаючи $@spellname328664." },
    { en = "Amarth summons skeletal minions to his side over $d. Inflicts $333627s1 Shadow damage to players within $333627A1 yards of the summoning location.", ua = "Амарт прикликає скелетних посіпак до себе протягом $d. Завдає $333627s1 тіньової шкоди гравцям у радіусі $333627A1 м від місця прикликання." },
    { en = "Amarth inflicts $s1 Shadow damage to an enemy and causes them to absorb the next $s2 healing.", ua = "Амарт завдає $s1 тіньової шкоди ворогові й змушує його поглинути наступні $s2 зцілення." },
    { en = "Amarth sends Bonefang into a frenzy, increasing its attack speed by $s1% for $d.", ua = "Амарт вводить Бонефанґа в шал, підвищуючи його швидкість атаки на $s1% на $d." },
    { en = "Lingering ichor from $@spellname333493 inflicts $s1 Shadow damage every $t1 sec and reduces healing received by $s2% for $d.", ua = "Залишковий іхор від $@spellname333493 завдає $s1 тіньової шкоди кожні $t1 с і зменшує отримуване зцілення на $s2% протягом $d." },
    { en = "Bonefang spews forth necrotic spittle, inflicting $333489s1 Shadow damage every $333489t sec. to enemies caught in the breath and reducing healing received by $333489s3%.", ua = "Кістезуб вивергає некротичну слину, завдаючи $333489s1 шкоди від темряви кожні $333489t с ворогам, що потрапили під подих, і знижуючи отримуване ними зцілення на $333489s3%." },
    { en = "Sends shards of ice at nearby enemies, inflicting $333624s1 Frost damage and applying $@spellname328664.", ua = "Випускає крижані осколки в довколишніх ворогів, завдаючи $333624s1 морозної шкоди і накладаючи $@spellname328664." },
    { en = "Reduces the target's movement speed by $s1% for $d. This effect stacks.", ua = "Знижує швидкість пересування цілі на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Amarth harvests the bodies of his minions, destroying them. \n\n\n\nIf the minion still stands, it explodes and inflicts $321258s1 damage to all players. Otherwise its corpse explodes, inflicting $321253s1 damage only to players within $321253a1 yards.", ua = "Амарт жне тіла своїх прислужників, знищуючи їх. \n\n\n\nЯкщо прислужник ще стоїть, він вибухає й завдає $321258s1 шкоди всім гравцям. Інакше вибухає його труп, завдаючи $321253s1 шкоди лише гравцям у радіусі $321253a1 м." },
    { en = "Surgeon Stitchflesh fixates on a nearby target for $343556d, increasing his damage done by $343558s3% but reducing movement speed by $343558s2%.", ua = "Хірург Стічфлеш зосереджується на цілі поблизу протягом $343556d, підвищуючи завдавану ним шкоду на $343558s3%, але зменшуючи швидкість пересування на $343558s2%." },
    { en = "Stitchflesh awakens one of his monstrous creations and douses them with $@spellname334321.", ua = "Стічфлеш пробуджує одне зі своїх жахливих творінь і обливає його $@spellname334321." },
    { en = "After a short period of time Stitchflesh escapes to the safety of his worktable.", ua = "Через короткий час Стічфлеш утікає в безпеку до свого робочого столу." },
    { en = "Stitchflesh throws a sharp needle, inflicting $s1 Physical damage and causing the player to bleed for $s2 Physical damage every $t2 sec. for $d.", ua = "Зшитоплоть кидає гостру голку, завдаючи $s1 фізичної шкоди й змушуючи гравця кровоточити, зазнаючи $s2 фізичної шкоди кожні $t2 с. протягом $d." },
    { en = "Surgeon Stitchflesh inflicts $s1 Physical damage to his current target.", ua = "Хірург Стічфлеш завдає $s1 фізичної шкоди своїй поточній цілі." },
    { en = "Standing in the disgusting fluids inflicts $s1 Plague damage every $t1 sec.", ua = "Перебування в огидній рідині завдає $s1 шкоди чумою кожні $t1 с." },
    { en = "Stitchflesh throws a jar of his embalming ichor, inflicting $320365s2 Plague damage to all players within $320365A2 yds and leaving behind a puddle of $@spellname320366.", ua = "Стічфлеш кидає глек зі своїм бальзамувальним сукровищем, завдаючи $320365s2 шкоди від чуми всім гравцям у межах $320365A2 ярдів і лишаючи по собі калюжу $@spellname320366." },
    { en = "Stitchflesh's creation is drenched in a rotting liquid that inflicts $334322s1 Plague damage to all enemies every $t1 sec. \n\n\n\nThis effect stacks.", ua = "Творіння Стічфлеша облите гнилою рідиною, що завдає $334322s1 чумної шкоди всім ворогам кожні $t1 с. \n\n\n\nЦей ефект накопичується." },
    { en = "Inflicts $s1 Physical damage to an enemy.", ua = "Завдає $s1 фізичної шкоди ворогові." },
    { en = "The construct hurls its meat hook through the air, pulling the first target hit to its location.\n\n\n\nInflicts $327952s1 Physical damage to players.", ua = "Конструкт жбурляє свій м'ясний гак у повітря, притягуючи до себе першу вражену ціль.\n\n\n\nЗавдає гравцям $327952s1 фізичної шкоди." },
    { en = "Surgeon Stitchflesh's work area is filled with a noxious fog that protects him from harm.\n\n\n\nInflicts $327100s1 Plague damage every $327100t1 sec. to nearby enemies.", ua = "Робоче місце хірурга Стічфлеша заповнене отруйним туманом, що захищає його від шкоди.\n\n\n\nЗавдає $327100s1 чумної шкоди кожні $327100t1 с ворогам поблизу." },
    { en = "The caster channels a beam of necrotic energy at the player, inflicting $s1 Shadow damage every $t1 sec and reducing their haste and movement speed by $s2% for up to $d.", ua = "Закляр спрямовує промінь некротичної енергії на гравця, завдаючи $s1 тіньової шкоди щосекунди ($t1) і знижуючи його поспіх та швидкість пересування на $s2% протягом щонайбільше $d." },
    { en = "Nalthor launches a shard of ice at his current target, inflicting $s1 Physical damage.", ua = "Налтор метає крижаний осколок у свою поточну ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Icy comets drop from the sky inflicting $s1 Frost damage to all players within $A1 yards of the impact and increases their damage taken by $@spellname321956 by $s2% for $d.", ua = "Крижані комети падають із неба, завдаючи $s1 морозної шкоди всім гравцям у межах $A1 м від влучання і підвищуючи отримувану ними шкоду від $@spellname321956 на $s2% на $d." },
    { en = "Nalthor banishes a player from his platform to the lower wings of the necropolis.\n\n\n\nAfter $323198d, players banished to the lower wings are slain outright unless they escape.", ua = "Налтор виганяє гравця зі своєї платформи в нижні крила некрополя.\n\n\n\nЗа $323198d вигнаних у нижні крила гравців негайно вбиває, якщо вони не втечуть." },
    { en = "The Gilded Champion bestowes their blessing upon the hero that saved them, increasing critical strike chance by $s1% for $d.", ua = "Позолочений Чемпіон дарує своє благословення героєві, що його врятував, збільшуючи шанс критичного удару на $s1% впродовж $d." },
    { en = "Nalthor calls down icy comets at each player's location every $t1 sec for $d. Each comet inflicts $320784s1 Frost damage to all players within $320784A1 yards of the impact and increases their damage taken by $@spellname320772 by $320784s2% for $320784d.", ua = "Налтор кожні $t1 с впродовж $d скидає крижані комети на місце розташування кожного гравця. Кожна комета завдає $320784s1 морозної шкоди всім гравцям у радіусі $320784A1 м від місця удару та збільшує шкоду, якої вони зазнають від $@spellname320772, на $320784s2% впродовж $320784d." },
    { en = "Nalthor unleashes tendrils of frost to bind a random player, immobilizing them and inflicting $s1 Frost damage every $t1 sec for up to $d.\n\n\n\nUpon expiration, this effect spreads to all players within $320790A1 yards.", ua = "Налтор вивільняє морозні щупальця, що сковують випадкового гравця, знерухомлюючи його та завдаючи $s1 морозної шкоди кожні $t1 с впродовж до $d.\n\n\n\nПісля завершення цей ефект поширюється на всіх гравців у радіусі $320790A1 м." },
    { en = "While on the lower platforms freezing winds buffet the player, continually reducing their movement speed by $s2% every $328179t1 sec.\n\n\n\nUpon expiring, an area of $@spellname328211 is created covering an area based on the number of $@spellname328181 applications gained.", ua = "Поки гравець перебуває на нижніх платформах, його шмагають крижані вітри, безперервно знижуючи швидкість пересування на $s2% кожні $328179t1 с.\n\n\n\nПісля завершення створюється зона $@spellname328211, площа якої залежить від кількості отриманих застосувань $@spellname328181." },
    { en = "Covers an area with sharp crystals of ice for up to $d.  Standing in the area inflicts $s1 Frost damage and reduces movement speed by $s2%.", ua = "Покриває зону гострими крижаними кристалами на час до $d. Перебування в зоні завдає $s1 морозної шкоди й зменшує швидкість пересування на $s2%." },
    { en = "Nalthor shields himself in a curtain of ice, preventing the next $s1 damage.  While the shield is active, waves of frosty energy emanate from him, inflicting $321370s1 Frost damage every $t2 sec to all players.", ua = "Налтор затуляється завісою криги, відвертаючи наступні $s1 шкоди. Поки щит активний, від нього розходяться хвилі морозної енергії, завдаючи $321370s1 морозної шкоди кожні $t2 сек усім гравцям." },
    { en = "Nalthor shields himself in a curtain of ice, preventing the next $s1 damage.  While the shield is active waves of frosty energy emanate from him, inflicting $321755s1 Frost damage to all players every $t2 sec and increases the damage taken of $@spellname321755 by $321755s2% for $321755d. This effect stacks.", ua = "Налтор огортає себе завісою з льоду, запобігаючи наступним $s1 шкоди. Поки щит активний, від нього розходяться хвилі морозної енергії, що завдають $321755s1 морозної шкоди всім гравцям кожні $t2 сек. і збільшують шкоду, отримувану від $@spellname321755, на $321755s2% упродовж $321755d. Цей ефект накопичується." },
    { en = "Ice shards pelt the area, inflicting $287296s1 Frost damage every $t1 sec. Players hit with $@spellname287294 become $@spellname287295, reducing their movement speed by $287295s1% for $287295d.", ua = "Крижані скалки осипають зону, завдаючи $287296s1 морозної шкоди кожні $t1 с. Гравці, уражені $@spellname287294, стають $@spellname287295, що зменшує їхню швидкість пересування на $287295s1% протягом $287295d." },
    { en = "Reduces the target's movement speed by $s1% for $d.", ua = "Зменшує швидкість пересування цілі на $s1% протягом $d." },
    { en = "Final will of the fighter absorbed by the remaining contenders, increasing their damage done by $s1% and granting them additional energy $s2 after using their powerful abilities. This effect stacks.", ua = "Останню волю бійця поглинають уцілілі суперники, що збільшує завдану ними шкоду на $s1% і дарує їм додаткову енергію $s2 після застосування потужних здібностей. Цей ефект накопичується." },
    { en = "Dessia strikes her current target for $s1 Physical damage and reduces their healing received by $s2% for $d.", ua = "Дессія б'є свою поточну ціль, завдаючи $s1 фізичної шкоди й зменшуючи отримуване нею зцілення на $s2% протягом $d." },
    { en = "Upon reaching 100 energy, Sathel inflicts players with Searing Death that inflicts $333292s1 Shadow damage to all players within $333292A1 yards of the victim every $t1 sec. for $d.", ua = "Досягнувши 100 енергії, Сатель накладає на гравців Пекучу Смерть, що завдає $333292s1 тіньової шкоди всім гравцям у межах $333292A1 ярдів від жертви кожні $t1 с протягом $d." },
    { en = "Sathel blasts a random player, inflicting $s1 Shadow damage.", ua = "Сатель вражає випадкового гравця, завдаючи $s1 тіньової шкоди." },
    { en = "Causes the target to wither, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Змушує ціль в'янути, завдаючи $s1 тіньової шкоди кожні $t1 сек. протягом $d." },
    { en = "Upon reaching 100 energy, Paceran throws vile concoctions at players every $320182t1 sec for $320182d, inflicting $1215636s1 Plague damage to players within $1215636a1 yards and creating a zone of Noxious Spores at the target location for $1215636d, inflicting $s1 Plague damage every $t1 sec to all players standing within it.", ua = "Сягнувши 100 енергії, Пасеран кожні $320182t1 сек. протягом $320182d жбурляє в гравців мерзенні мікстури, завдаючи $1215636s1 шкоди від чуми гравцям у межах $1215636a1 ярд. і створюючи в цільовому місці зону Згубних спор на $1215636d, яка завдає $s1 шкоди від чуми щосекунди ($t1) усім гравцям, що в ній стоять." },
    { en = "Unleashes decaying breath at enemies in front of the caster, inflicting $s2 Plague damage to all players impacted.", ua = "Вивільняє гнилісний подих на ворогів перед закляттярем, завдаючи $s2 чумної шкоди всім враженим гравцям." },
    { en = "Upon reaching 100 energy, Dessia unleashes a mighty smash that inflicts $s1 Nature damage to all players and reduces their movement speed by $s2% for $d.", ua = "Досягнувши 100 енергії, Дессія вивільняє могутній удар, що завдає $s1 шкоди від сил природи всім гравцям і зменшує їхню швидкість пересування на $s2% впродовж $d." },
    { en = "Leaps towards a target, inflicting $s1 Physical damage to all enemies within $A1 yards.", ua = "Стрибає до цілі, завдаючи $s1 фізичної шкоди всім ворогам у межах $A1 ярдів." },
    { en = "Gorechop pulls in all players and smashes the ground, inflicting $s1 Physical damage and knocking back players struck.", ua = "Кишколом притягує всіх гравців і б'є об землю, завдаючи $s1 фізичної шкоди й відкидаючи уражених гравців." },
    { en = "Upon death, leaves a pool of $@spellname321447 that inflicts $323130s1 Plague damage every $323130t1 sec to players standing in the area and reduces their movement speed by $323130s2%.", ua = "Гинучи, лишає калюжу $@spellname321447, що завдає $323130s1 шкоди від чуми кожні $323130t1 сек гравцям, які стоять у цій ділянці, і зменшує їхню швидкість пересування на $323130s2%." },
    { en = "Meat hooks descend and sweep across the arena. Players that are struck by a meat hook are stunned and suffer $@spellname323406.", ua = "Згори опускаються м'ясні гаки й проносяться через арену. Гравців, яких влучає м'ясний гак, оглушує, і вони зазнають $@spellname323406." },
    { en = "Oozing Leftovers unravel themselves, losing $323543s1% of their maximum health every $t3 sec.", ua = "Сочаві Недоїдки розпадаються самі по собі, втрачаючи $323543s1% свого максимального здоров'я кожні $t3 сек." },
    { en = "Gorechop strikes his target, inflicting $s1 Physical damage.", ua = "Криваворуб б'є ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Xav plants an $@spellname331606, reducing the movement speed of all players by $s1% every $s2 sec while it persists.", ua = "Ксав встановлює $@spellname331606, зменшуючи швидкість пересування всіх гравців на $s1% кожні $s2 сек, поки воно діє." },
    { en = "A series of brutal melee strikes that inflict increasing Physical damage to their target.", ua = "Серія жорстоких ударів ближнього бою, що завдають цілі дедалі більшої фізичної шкоди." },
    { en = "Damage dealt increased by $s1% for $d.", ua = "Завдавана шкода збільшена на $s1% протягом $d." },
    { en = "Upon reaching 100 energy, Xav forces players into the dueling pit below. The winner of the duel is granted $@spellname320165 while the loser is affected by $@spellname320167.\n\n\n\nPlayers gain a stack of $@spellname332670 every $t5 sec. \n\n\n\nIf neither player is defeated within $d, both players are affected by $@spellname320711.", ua = "Сягнувши 100 енергії, Ксав примушує гравців до бійцівської ями внизу. Переможець двобою отримує $@spellname320165, а переможений зазнає $@spellname320167.\n\n\n\nГравці отримують накопичення $@spellname332670 кожні $t5 с.\n\n\n\nЯкщо жоден із гравців не зазнає поразки протягом $d, обох уражає $@spellname320711." },
    { en = "Damage dealt reduced by $s1% for $d.", ua = "Завдана шкода зменшена на $s1% впродовж $d." },
    { en = "Damage dealt decreased by $s1% for $d.", ua = "Завдавана шкода зменшена на $s1% протягом $d." },
    { en = "Xav slams the ground, inflicting $s2 Physical damage to players in a line in front of him.", ua = "Ксав гатить по землі, завдаючи $s2 фізичної шкоди гравцям на лінії перед собою." },
    { en = "Xav leaps to the center of the arena inflicting $320789s1 Physical damage to all players and performs a random combination of attacks.", ua = "Ксав стрибає в центр арени, завдаючи $320789s1 фізичної шкоди всім гравцям, і виконує випадкову комбінацію атак." },
    { en = "Xav stomps, interrupting all spellcasting within $A4 yards for $d and inflicts $s2 Physical damage and knocks back players within $A2 yards.", ua = "Ксав тупає, перериваючи всі прочитання заклять у межах $A4 ярдів на $d, завдає $s2 фізичної шкоди та відкидає гравців у межах $A2 ярдів." },
    { en = "Xav slashes in a frontal hemisphere, inflicting $s2 Physical damage to all players struck.", ua = "Ксав робить замах по фронтальній півсфері, завдаючи $s2 фізичної шкоди всім враженим гравцям." },
    { en = "Combatants take $s1% increased damage, stacking every $320102t5 sec.", ua = "Бійці отримують на $s1% більше шкоди; ефект накопичується кожні $320102t5 с." },
    { en = "Kul'tharok attaches $@spellname473540 onto target players for $473576d. The well pulses necrotic energy every $473576t1 sec, inflicting $1222949s1 Shadow damage to players within $1222949a1 yard", ua = "Кул'тарок накладає $@spellname473540 на цільових гравців на $473576d. Колодязь випромінює некротичну енергію кожні $473576t1 с, завдаючи $1222949s1 тіньової шкоди гравцям у межах $1222949a1 м." },
    { en = "Kul'tharok tears the souls from players, inflicting $474141s2 Shadow damage every $474298t1 sec for $474141d. \n\n\n\nThe lost souls move toward Kul'tharok and causes $@spellname474013 when they reach him.", ua = "Кул'тарок вириває душі з гравців, завдаючи $474141s2 тіньової шкоди кожні $474298t1 с протягом $474141d. \n\n\n\nЗагублені душі рухаються до Кул'тарока та спричиняють $@spellname474013, коли досягають його." },
    { en = "Kul'tharok unleashes necrotic energy at primary target, inflicts $474084s1 Shadow damage to all players in front of him.", ua = "Кул'тарок вивільняє некротичну енергію по основній цілі, завдаючи $474084s1 тіньової шкоди всім гравцям перед собою." },
    { en = "Kul'tharok unleashes necrotic energy at all players, inflicting $473519s1 Shadow damage every 1 sec for $d sec.", ua = "Кул'тарок вивільняє некротичну енергію на всіх гравців, завдаючи $473519s1 тіньової шкоди щосекунди протягом $d с." },
    { en = "Kul'tharok attaches the phantasms to the arena and inflicts $473519s1 Shadow damage every 1 sec to the player who touches the phantasm.", ua = "Кул'тарок прикріплює фантазми до арени і завдає $473519s1 тіньової шкоди щосекунди гравцеві, який торкається фантазму." },
    { en = "Inflicts $s1 Shadow damage to an enemy.", ua = "Завдає $s1 тіньової шкоди ворогові." },
    { en = "Kul'tharok corrupts the player's soul, causes it to erupt in necromantic energy. Inflicting $s1 Shadow damage to players.", ua = "Кул'тарок опоганює душу гравця, змушуючи її вибухнути некромантичною енергією. Завдає $s1 тіньової шкоди гравцям." },
    { en = "Mordretha haunts all players, inflicting $s1 Shadow damage every $t1 sec for $d. When this effect expires, it inflicts $324514s1 to the player and allies within $324514a1 yards.", ua = "Мордрета переслідує всіх гравців, завдаючи $s1 тіньової шкоди кожні $t1 с протягом $d. Коли цей ефект спливає, він завдає $324514s1 гравцеві та союзникам у межах $324514a1 ярдів." },
    { en = "Mordretha channels a beam of Anima, inflicting $s1 Shadow damage every $t1 sec and pushing back players within it.", ua = "Мордрета спрямовує промінь аніми, завдаючи $s1 тіньової шкоди кожні $t1 с і відштовхуючи гравців у ньому." },
    { en = "Mordretha tears open a $@spellname323825 that draws all players towards it for $d. Players that are pulled into the $@spellname323825 are afflicted with $@spellname323831.", ua = "Мордрета розриває $@spellname323825, що притягує до себе всіх гравців на $d. Гравці, втягнуті в $@spellname323825, зазнають дії $@spellname323831." },
    { en = "Ghostly riders charge across the arena, inflicting $s1 Shadow damage and knocking back players caught in their path.", ua = "Примарні вершники мчать через арену, завдаючи $s1 тіньової шкоди і відкидаючи гравців на своєму шляху." },
    { en = "Mordretha empowers her scythe and strikes her primary target, inflicting $s1 Shadow damage and $324424s1 Physical damage.", ua = "Мордрета підсилює свою косу й б'є по основній цілі, завдаючи $s1 тіньової шкоди і $324424s1 фізичної шкоди." },
    { en = "Upon reaching $s1% health remaining, Mordretha conjures Echoes of Carnage for the remainder of the encounter. \n\n\n\nEchoes of Carnage inflicts $s3 Shadow damage to all players instantly and $339759s1 Shadow damage every $t2 sec thereafter. \n\n\n\nGhostly Combatants are periodically drawn to the arena while Echoes of Carnage is in effect.", ua = "Щойно в Мордрети лишається $s1% здоров'я, вона прикликає Відлуння Різанини до кінця сутички. \n\n\n\nВідлуння Різанини миттєво завдає $s3 тіньової шкоди всім гравцям, а потім $339759s1 тіньової шкоди кожні $t2 сек. \n\n\n\nПоки діє Відлуння Різанини, на арену періодично прибувають Примарні Бійці." },
    { en = "Stuns the victim, rendering them unable to move or attack and inflicts $s2 Shadow damage every $t2 sec for $d.", ua = "Приголомшує жертву, позбавляючи її змоги рухатися чи атакувати, і завдає $s2 тіньової шкоди кожні $t2 сек. упродовж $d." },
    { en = "Ghostly combatants clash, inflicting $s1 Shadow damage to players within $A1 yards.", ua = "Примарні бійці зіштовхуються, завдаючи $s1 тіньової шкоди гравцям у межах $A1 ярдів." },
    { en = "Oryphrion launches anima infused ordnance, inflicting $s1 Arcane damage to enemies within $A1 yards of the impact.", ua = "Оріфріон запускає просочений анімою боєприпас, завдаючи $s1 арканної шкоди ворогам у межах $A1 ярдів від місця влучання." },
    { en = "Gaining $s5 applications of $@spellname348567 increases damage and healing by $s2% and haste by $s1% for $d. \n\n\n\nRemoves all applications of $@spellname348567.", ua = "Отримання $s5 накопичень $@spellname348567 збільшує шкоду й зцілення на $s2%, а поспіх — на $s1% протягом $d.\n\n\n\nЗнімає всі накопичення $@spellname348567." },
    { en = "Inflicts $s1 Arcane damage to all players every $t1 sec for $d. This effect stacks.", ua = "Завдає $s1 арканної шкоди всім гравцям кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Tears in to all nearby enemies, inflicting $s1 Physical damage and causes them to bleed for $s2 Physical damage every $t2 sec for $d.", ua = "Роздирає всіх ворогів поблизу, завдаючи $s1 фізичної шкоди і змушуючи їх кровоточити, завдаючи $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Target is stunned for $d.", ua = "Ціль оглушено на $d." },
    { en = "Lu'ashal erupts in a lightcrazed rage, inflicting $s1 Radiant damage to all players and causing all existing $@spellname1243988 to erupt simultaneously, releasing $@spellname1258426 that burst outwards in all directions.", ua = "Лу'ашал вибухає світлошаленою люттю, завдаючи $s1 променистої шкоди всім гравцям і змушуючи всі наявні $@spellname1243988 здетонувати одночасно, вивільняючи $@spellname1258426, що розлітаються навсібіч." },
    { en = "Players standing in the area suffer $s1 Radiant damage every $t1 sec and their chance to hit is reduced by $s2%.", ua = "Гравці, що стоять у цій ділянці, зазнають $s1 променистої шкоди кожні $t1 сек., а їхній шанс влучити знижено на $s2%." },
    { en = "Lu'ashal afflicts players with a searing halo that inflicts $1276470s1 Radiant damage to the target and all allies within $1276468A1 yards every $1276427t1 sec for $1276427d.", ua = "Лу'ашал вражає гравців пекучим німбом, що кожні $1276427t1 с протягом $1276427d завдає $1276470s1 променистої шкоди цілі й усім союзникам у радіусі $1276468A1 м." },
    { en = "Lu'ashal exhales a breath of holy flame at her primary target, inflicting Radiant damage every $1276247t1 sec for $1276247d to her primary target and players standing in the area.", ua = "Лу'ашал видихає струмінь священного полум'я на свою основну ціль, завдаючи їй та гравцям у зоні шкоди від Світла кожні $1276247t1 сек. протягом $1276247d." },
    { en = "Inflicts $s1 Radiant damage to players that come into contact with an ember and knocks them back.", ua = "Завдає $s1 променистої шкоди гравцям, які торкаються жарини, і відкидає їх назад." },
    { en = "Lu'ashal calls down searing Holy energy from the skies, inflicting $1243967s1 Radiant damage to players within the impact area. \n\n\n\nThe impact tears open a $@spellname1243988.", ua = "Лу'ашал прикликає з небес пекуче священне Світло, завдаючи $1243967s1 шкоди від Світла гравцям у зоні влучання. \n\n\n\nВлучання розриває $@spellname1243988." },
    { en = "Thorm'belan hurls a light-infused shard towards a location.  Intercepting this shard as it strikes the ground inflicts $1257735s1 Holy damage to players within $1257735A1 yards of the impact and causes the shard to bounce to a new location.\n\n\n\nIf no players are within the effect the shard explodes triggering a $@spellname1257737", ua = "Торм'белан жбурляє пронизану світлом скалку до певного місця. Перехоплення цієї скалки під час її удару об землю завдає $1257735s1 шкоди від Світла гравцям у межах $1257735A1 м від місця влучання й змушує скалку відскочити до нового місця.\n\n\n\nЯкщо в зоні дії немає жодного гравця, скалка вибухає, спричиняючи $@spellname1257737" },
    { en = "Thorm'belan embeds motes of searing light into several targets, inflicting $s1 Holy damage every $t1 sec for $d.\n\n\n\nUpon expiration, a $@spellname1257618 is triggered.", ua = "Торм'белан вкорінює часточки палючого світла в кількох цілей, завдаючи $s1 шкоди від Світла кожні $t1 с протягом $d.\n\n\n\nПісля завершення спрацьовує $@spellname1257618." },
    { en = "Contact with the ground causes the shard to erupt in a radiant blast that inflicts $s1 Holy damage to all players, stunning them for $d.", ua = "Контакт із землею змушує скалку вибухнути променистим спалахом, що завдає $s1 шкоди від Світла всім гравцям, оглушуючи їх на $d." },
    { en = "Thorm'belan binds all players in a cone wth vines, pulling them towards its location and inflicting $1258781s1 Nature damage every $s1 sec for up to $d.\n\n\n\nThe vines snap when their victims move far enough away from the caster, ending the effect.", ua = "Торм'белан обплутує лозами всіх гравців у конусі, притягуючи їх до себе та завдаючи $1258781s1 шкоди природою кожні $s1 с протягом до $d.\n\n\n\nЛози розриваються, коли їхні жертви відходять достатньо далеко від творця, припиняючи дію ефекту." },
    { en = "The mote erupts in a dazzling cascade of light, inflicting $1257618s1 Holy damage to all other players within $1257367A1 yards of the detonation, causing them to become disoriented for $1257367d.", ua = "Частинка вибухає сліпучим каскадом світла, завдаючи $1257618s1 шкоди Світлом усім іншим гравцям у радіусі $1257367A1 ярдів від детонації та дезорієнтуючи їх на $1257367d." },
    { en = "Thorm'belan rends their target's flesh, inflicting $s1 Physical damage and causing them to bleed for an additional $s2 Physical damage every $t2 sec for $d.", ua = "Торм'белан роздирає плоть своєї цілі, завдаючи $s1 фізичної шкоди та змушуючи її стікати кров'ю, що додатково завдає $s2 фізичної шкоди щосекунди $t2 протягом $d." },
    { en = "Predaxas lurches multiple times inflicting $1276323s1 Nature damage to players within $1276320A1 yards, knocking back.\n\n\n\nRegurgitated creatures react to this effect.", ua = "Предаксас кидається кілька разів, завдаючи $1276323s1 шкоди від сил природи гравцям у межах $1276320A1 ярдів і відкидаючи їх назад.\n\n\n\nВідригнуті істоти реагують на цей ефект." },
    { en = "Predaxas expels some of its stomach contents inflicting $1276220s1 Nature damage plus an additional $1276220s2 Nature damage every $1276220T2 sec for $1276220D to players in a frontal cone.\n\n\n\nAdditional enemies emerge from the spray attacking players.", ua = "Предаксас вивергає частину вмісту свого шлунка, завдаючи $1276220s1 шкоди від сил природи та додатково $1276220s2 шкоди від сил природи кожні $1276220T2 сек. протягом $1276220D гравцям у передньому конусі.\n\n\n\nЗ викинутої маси з'являються додаткові вороги, що атакують гравців." },
    { en = "Predaxas' stomachs rumble, seeking a meal. Blitzing to a position they attempt to eat prey every $1277829T1 sec for up to $1277829D inflicting $1277835s1 Nature damage and stunning for $1277835D players within $1277835A1 yards of the indicated location.", ua = "Шлунки Предаксаса бурчать, прагнучи поживи. Кидаючись на позицію, він намагається поласувати здобиччю кожні $1277829T1 с протягом до $1277829D, завдаючи $1277835s1 шкоди від сил природи й оглушуючи на $1277835D гравців у межах $1277835A1 м від позначеного місця." },
    { en = "Enters a bestial rage increasing damage done by $s1% for $D.", ua = "Впадає в звірину лють, збільшуючи завдану шкоду на $s1% протягом $D." },
    { en = "Seismic Slam scatters digestive fluids off the consumptor leaving behind a zone for $1277043D. This area inflicts $1277045s1 Nature damage every $1277045T1 sec and reduces movement speed by $1277045s2%.", ua = "Сейсмічний удар розкидає травні соки пожирача, лишаючи по собі зону на $1277043D. Ця зона завдає $1277045s1 шкоди від сил природи кожні $1277045T1 сек і знижує швидкість пересування на $1277045s2%." },
    { en = "Seismic Slam vibrates the blistercreep showering cosmic hail inflicting $1276884s1 Shadow damage to players within $1276884A1 yards of each impact location.", ua = "Сейсмічний удар струшує пухировугра, обсипаючи косимічним градом і завдаючи $1276884s1 шкоди від тіні гравцям у межах $1276884A1 ярдів від кожного місця влучання." },
    { en = "The consumptor shakes it off spraying toxins throughout inflicting $1276988s2 Nature damage.", ua = "Пожирач струшується, розбризкуючи довкола токсини, що завдають $1276988s2 шкоди від сил природи." },
    { en = "Seismic Slam jostles the shredclaw ejecting myocardial fluid inflicting $1277045s1 Shadow damage and an additional $1277694s3 Shadow damage every $1277694T3 sec, increasing damage taken by $1277694s2% for $1277694D. This effect stacks.", ua = "Сейсмічний удар струшує дробокігтя, вибиваючи міокардіальну рідину, що завдає $1277045s1 шкоди від тіні та додатково $1277694s3 шкоди від тіні кожні $1277694T3 сек., збільшуючи отримувану шкоду на $1277694s2% протягом $1277694D. Цей ефект накопичується." },
    { en = "Cragpine grows a mighty pine from the earth and wields it as a war club, causing his next $s2 melee attacks to inflict additional Physical damage.", ua = "Креґпайн вирощує із землі могутню сосну і вимахує нею, мов бойовою довбнею, через що його наступні $s2 атаки в ближньому бою завдають додаткової фізичної шкоди." },
    { en = "Cragpine awakens ancient seeds deep within the earth. These seeds pulse with energy, inflicting $1257905s1 Nature damage every $1257878t1 sec for $1257878d.", ua = "Скеледрев пробуджує прадавнє насіння глибоко в землі. Це насіння пульсує енергією, завдаючи $1257905s1 шкоди від сил природи кожні $1257878t1 сек. упродовж $1257878d." },
    { en = "Cragpine stomps the earth, inflicting $s1 Physical damage to players within $a1 yards and causing $@spellname1235134 to emerge.\n\n\n\nThe disturbance awakens slumbering treants.", ua = "Скеледрев б'є по землі, завдаючи $s1 фізичної шкоди гравцям у межах $a1 ярдів і змушуючи $@spellname1235134 виринути назовні.\n\n\n\nЦей струс пробуджує сплячих трентів." },
    { en = "Piercing roots erupt from the earth, inflicting $s1 Nature damage to players within $a1 yards and knocking them upwards.", ua = "Із землі виринають пронизливі корені, завдаючи $s1 шкоди від сил природи гравцям у межах $a1 ярдів і підкидаючи їх угору." },
    { en = "Players periodically inflict $s1 Nature damage to allies in a $A1 yard radius within the opposing realm.", ua = "Гравці періодично завдають $s1 шкоди від сил природи союзникам у радіусі $A1 м у протилежному світі." },
    { en = "Players are wrenched into the Rift, allowing them to see Manifestations within the Aln for $d.", ua = "Гравців затягує в Розлом, дозволяючи їм бачити Прояви в Альні впродовж $d." },
    { en = "The energies surrounding the player erupt, causing players within $1257093A1 yards to suffer $s1 Nature damage every $t1 sec for $d and knocking them back.$?DIFF17[][ This effect stacks.]", ua = "Енергія довкола гравця вибухає, через що гравці в межах $1257093A1 ярдів зазнають $s1 шкоди від сил природи кожні $t1 сек протягом $d і відкидаються назад.$?DIFF17[][ Цей ефект накопичується.]" },
    { en = "As each Manifestation emerges within the Rift, they release a wave of sickness, causing all players to absorb the next $s1 healing received.", ua = "Щойно черговий Прояв виринає в Розломі, він вивільняє хвилю хвороби, через яку всі гравці поглинатимуть наступні $s1 отриманого зцілення." },
    { en = "Cannibalizing a Manifestation inflicts $1280655s1 Nature damage to all players and heals Chimaerus for $1255546s2% of the Manifestation's remaining vitality.\n\n\n\nIn addition, Chimaerus' damage done is increased by $s1%. This effect stacks.", ua = "Поглинання Прояву завдає $1280655s1 шкоди від сил природи всім гравцям і зцілює Чимаеруса на $1255546s2% залишкової життєвої сили Прояву.\n\n\n\nКрім того, шкода, яку завдає Чимаерус, зростає на $s1%. Цей ефект накопичується." },
    { en = "Chimaerus slashes in the direction of a nearby target, inflicting $s2 Physical damage to players in a frontal cone, causing them to bleed for $s3 Physical damage every $t3 sec for $d and knocking them away.", ua = "Чимаерус б'є навідліг у напрямку найближчої цілі, завдаючи $s2 фізичної шкоди гравцям у передньому конусі, через що вони кровоточать, отримуючи $s3 фізичної шкоди кожні $t3 с протягом $d, і відкидає їх." },
    { en = "Chimaerus launches globs of phlegm at all players, inflicting $1246653s1 Nature damage every $1246653t1 sec for $1246653d.", ua = "Чимаерус метає згустки слизу в усіх гравців, завдаючи $1246653s1 шкоди від сил природи кожні $1246653t1 сек. упродовж $1246653d." },
    { en = "Manifestations emerge enshrouded in an ephemeral shield that absorbs $s1 damage. Upon removal, the Manifestation crosses the threshold into Reality$?DIFF17[.][, leaving behind $@spellname1245919.]", ua = "Прояви з'являються огорнуті ефемерним щитом, що поглинає $s1 шкоди. Після зняття Прояв проривається в Реальність$?DIFF17[.][, лишаючи по собі $@spellname1245919.]" },
    { en = "The Haunting Essence launches a bolt of essence at a random player, inflicting $s1 Nature damage.", ua = "Примарна Есенція метає згусток есенції у випадкового гравця, завдаючи $s1 шкоди від сил природи." },
    { en = "Chimaerus sweeps across its den, exhaling corruption that inflicts $s1 Nature damage to players standing in the area and stuns them for $d.\n\n\n\nThe spewed corruption coalesces Manifestations and leaves behind $@spellname1245919.", ua = "Чимаерус проноситься своїм лігвом, видихаючи скверну, що завдає $s1 шкоди від сил природи гравцям у зоні та приголомшує їх на $d.\n\n\n\nВивергнута скверна згущується в Прояви та лишає по собі $@spellname1245919." },
    { en = "Chimaerus is protected by the shroud of its den while in the air, reducing damage taken by $s1%.", ua = "Поки Чимаерус у повітрі, його захищає полог його лігва, знижуючи отриману шкоду на $s1%." },
    { en = "The Colossal Horror unleashes a dreadful roar, inflicting $s1 Physical damage to all players. Ignores Armor. \n\n\n\nIncreases the damage of $@spellname1249207 by $s2%. This effect stacks.", ua = "Колосальний Жах випускає жахливий рик, завдаючи $s1 фізичної шкоди всім гравцям. Ігнорує броню. \n\n\n\nЗбільшує шкоду $@spellname1249207 на $s2%. Цей ефект накопичується." },
    { en = "The Colossal Horror unleashes a series of three strikes at its current target over $d, inflicting $1262053s1 Physical damage and $1262059s1 Nature damage with each strike.", ua = "Колосальний Жах обрушує на свою поточну ціль серію з трьох ударів упродовж $d, завдаючи $1262053s1 фізичної шкоди та $1262059s1 шкоди від сил природи кожним ударом." },
    { en = "Chimaerus tears a hole in Reality, inflicting $1246827s1 Physical damage to its current target and inflicting $1282073s1 Nature damage to several players. \n\n\n\nVictims are knocked into the air and gain $@spellname1245698.", ua = "Чимаерус роздирає Реальність, завдаючи $1246827s1 фізичної шкоди своїй поточній цілі та $1282073s1 шкоди від сил природи кільком гравцям. \n\n\n\nЖертв підкидає в повітря, і вони отримують $@spellname1245698." },
    { en = "Chimaerus tears a hole in Reality, inflicting $1246827s1 Physical damage to its current target and $s1 Nature damage split evenly between players within $1262303A1 yards of the impact.\n\n\n\nVictims are knocked into the air and gain $@spellname1245698.", ua = "Чимаерус роздирає діру в Реальності, завдаючи $1246827s1 фізичної шкоди своїй поточній цілі та $s1 шкоди від сил природи, розподіленої порівну між гравцями в межах $1262303A1 м від місця влучання.\n\n\n\nЖертв підкидає в повітря, і вони отримують $@spellname1245698." },
    { en = "Chimaerus consumes the essence of its enemies, inflicting $1273112s1 Nature damage every $t1 sec for $d.\n\n\n\nUpon finishing its channel, Chimaerus knocks players away and consumes any remaining Manifestations, casting $@spellname1245844 for each Manifestation consumed.", ua = "Чимаерус споживає есенцію своїх ворогів, завдаючи $1273112s1 шкоди від сил природи кожні $t1 с протягом $d.\n\n\n\nЗавершивши творіння, Чимаерус відкидає гравців і поглинає всі вцілілі Прояви, застосовуючи $@spellname1245844 за кожен поглинутий Прояв." },
    { en = "Chimaerus descends to the ground, inflicting $s1 Physical damage to all players upon landing and knocking them into the air.\n\n\n\nAny remaining Manifestations are consumed, causing Chimaerus to cast $@spellname1245844 for each Manifestation consumed.", ua = "Чимаерус опускається на землю, завдаючи $s1 фізичної шкоди всім гравцям під час приземлення й підкидаючи їх у повітря.\n\n\n\nУсі вцілілі Прояви поглинаються, через що Чимаерус застосовує $@spellname1245844 за кожен поглинутий Прояв." },
    { en = "A pool of essence that inflicts $s1 Nature damage every $t1 sec to players within it and reduces movement speed by $s2%.", ua = "Калюжа есенції, що завдає $s1 шкоди від сил природи кожні $t1 сек. гравцям усередині неї та знижує швидкість пересування на $s2%." },
    { en = "Chimaerus surrounds several players with ravenous energy, causing them to suffer $s1 Nature damage every $t1 sec for $d.\n\n\n\nUpon removal, the target erupts with $@spellname1257093 and consumes $@spellname1245857 within $1257093A1 yards.", ua = "Чимаерус оповиває кількох гравців ненаситною енергією, через що вони зазнають $s1 шкоди від сил природи кожні $t1 сек протягом $d.\n\n\n\nКоли ефект зникає, ціль вибухає, спричиняючи $@spellname1257093, і поглинає $@spellname1245857 в межах $1257093A1 ярдів." },
    { en = "Exposure from the Rift increases damage taken from $@spellname1262289 by $s1% for $d. This effect stacks.", ua = "Вплив Розлому збільшує отриману шкоду від $@spellname1262289 на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Chimaerus unleashes an unearthly roar, inflicting $s2 Nature damage to all players and causing Manifestations to emerge throughout the Rift.", ua = "Чимаерус видає неземний рик, завдаючи $s2 шкоди від сил природи всім гравцям і змушуючи Прояви виринати по всьому Розлому." },
    { en = "Chimaerus causes several players within the Rift to succumb to madness, inflicting $1264782s1 Nature damage to players within $1264975A1 yards and horrifying them, causing them to suffer $1275637s1 Nature damage every $1264757t1 sec. This effect increases in intensity every $1264780t7 sec.\n\n\n\nAllies outside the Rift can stand nearby the victims to swap realms with them after a short duration, saving them from the madness.", ua = "Чимаерус змушує кількох гравців у Розломі піддатися божевіллю, завдаючи $1264782s1 шкоди від сил природи гравцям у межах $1264975A1 ярдів і вселяючи в них жах, через що вони зазнають $1275637s1 шкоди від сил природи кожні $1264757t1 сек. Сила цього ефекту зростає кожні $1264780t7 сек.\n\n\n\nСоюзники поза Розломом можуть стати поряд із жертвами, щоб за коротку мить помінятися з ними реальностями й урятувати їх від божевілля." },
    { en = "The Haunting Essence unleashes a scream, inflicting $1265940s1 Nature damage every $1265940t1 sec to all players for $d and causing them to flee in fear.", ua = "Примарна Есенція видає крик, завдаючи $1265940s1 шкоди від сил природи кожні $1265940t1 с усім гравцям протягом $d і змушуючи їх тікати від страху." },
    { en = "Chimaerus feasts on any Manifestations in Reality within its reach, casting $@spellname1245844 for every Manifestation consumed.", ua = "Чимаерус пожирає всі Прояви в Реальності в межах досяжності й застосовує $@spellname1245844 за кожен поглинутий Прояв." },
    { en = "The Voidmaw's melee attacks inflict $1255683s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Атаки ближнього бою Пащі Порожнечі завдають $1255683s1 шкоди від тіні кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Averzian knocks back players and rains destruction onto the field at several destinations, inflicting $s1 Shadow damage to players within $a1 yards of the impact locations.", ua = "Аверзіан відкидає гравців і проливає руйнування на кілька місць поля бою, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м від місць влучання." },
    { en = "While at 35% health remaining, the Voidmaw's movement speed is reduced by $s1%.", ua = "Доки в нього лишається 35% здоров'я, швидкість пересування Паща Порожнечі зменшено на $s1%." },
    { en = "Averzian's melee attacks infect his target with void, reducing their maximum health by $s1% for $d. This effect stacks.\n\n\n\nWhen Averzian's troops take the field, the target with the highest amount of $@spellname1265540 becomes $@spellname1283069.", ua = "Атаки ближнього бою Аверзіана заражають ціль Порожнечею, знижуючи її максимальне здоров'я на $s1% на $d. Цей ефект накопичується.\n\n\n\nКоли війська Аверзіана виходять на поле бою, ціль із найбільшою кількістю $@spellname1265540 зазнає ефекту $@spellname1283069." },
    { en = "Averzian marks several targets with a devouring void. Upon removal, applies $@spellname1280075 and consumes an application of $@spellname1280035 within $1280024A1 yards.", ua = "Аверзіан позначає кількох цілей пожиральною Порожнечею. Після зняття накладає $@spellname1280075 і поглинає накопичення $@spellname1280035 у радіусі $1280024A1 м." },
    { en = "The caster grants a shield to allies that absorbs the next $s1 damage.", ua = "Творець дарує союзникам щит, що поглинає наступні $s1 шкоди." },
    { en = "Averzian gains $s1% increased damage and reduces his damage taken by $s2% while within $a1 yards of claimed territory.", ua = "Аверзіан завдає на $s1% більше шкоди й отримує на $s2% менше шкоди, доки перебуває в межах $a1 м від захопленої території." },
    { en = "Averzian summons Abyssal Voidshapers onto the battlefield. As his minions emerge, they inflict $1253691s1 Shadow damage to players within $1253691A1 yards and knocks them away.", ua = "Аверзіан прикликає на поле бою Безодніх Формувачів Порожнечі. Коли його посіпаки з'являються, вони завдають $1253691s1 шкоди від тіні гравцям у радіусі $1253691A1 м і відкидають їх." },
    { en = "The Abyssal Voidshaper creates a shell that prevents $@spellname1249265 from removing its $@spellname1249714.", ua = "Безодній Творець Порожнечі створює оболонку, що не дає $@spellname1249265 зняти його $@spellname1249714." },
    { en = "Upon reaching 35% health remaining, the Voidmaw approaches the closest void-claimed space to restore its health.", ua = "Щойно в нього лишається 35% здоров'я, Паща Порожнечі рушає до найближчого захопленого Порожнечею простору, щоб відновити своє здоров'я." },
    { en = "Averzian launches void lances outward, inflicting $1260718s1 Shadow damage to players in their path and knocking them back.", ua = "Аверзіан випускає назовні списи Порожнечі, завдаючи $1260718s1 шкоди від тіні гравцям на своєму шляху та відкидаючи їх." },
    { en = "Enshrouded by the Void, the caster reduces all damage taken by $s1% unless impacted by an $@spellname1249262.", ua = "Огорнутий Порожнечею, той, хто творить закляття, знижує всю отриману шкоду на $s1%, якщо на нього не вплинула $@spellname1249262." },
    { en = "The Abyssal Malus curses several players with a dark miasma, inflicting $s1 Shadow damage and reducing their haste by $s2% for $d.", ua = "Безодній Малус проклинає кількох гравців темним міазмом, завдаючи $s1 шкоди від тіні та знижуючи їхній поспіх на $s2% протягом $d." },
    { en = "A column of Averzian's troops march across the field, inflicting $s1 Shadow damage every $t1 sec to players in their path.", ua = "Колона військ Аверзіана марширує через поле, завдаючи $s1 шкоди від тіні щосекунди $t1 гравцям на своєму шляху." },
    { en = "At full power, the Voidshaper transforms into an Obscurion Endwalker.", ua = "На повній потужності Творець Порожнечі перетворюється на Кінцехода Обскуріону." },
    { en = "Returning from the brink of the Void leaves scars, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Повернення з-над безодні Порожнечі лишає шрами, завдаючи $s1 шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "The Abyssal Voidshaper claims territory for Averzian, inflicting $s1 Shadow damage to players within $a1 yards and an additional $1279890s1 Shadow damage to players caught in the star burst blast.\n\n\n\nEach claimed territory brings Averzian's army closer to the $@spellname1260981.", ua = "Безодняний Творець Порожнечі захоплює територію для Аверзіана, завдаючи $s1 шкоди від тіні гравцям у межах $a1 ярдів і додатково $1279890s1 шкоди від тіні гравцям, що потрапили під зоряний спалах.\n\n\n\nКожна захоплена територія наближає армію Аверзіана до $@spellname1260981." },
    { en = "The caster hurls dark energy at several players, inflicting $s1 Shadow damage upon impact.", ua = "Заклинач кидає темну енергію в кількох гравців, завдаючи $s1 шкоди від тіні при влучанні." },
    { en = "Averzian harnesses the Void, inflicting $s1 Shadow damage to all players.\n\n\n\nHe then continues to radiate energy, inflicting $1259903s1 Shadow damage every $1259900t1 sec.", ua = "Аверзіан вивільняє Порожнечу, завдаючи $s1 шкоди від тіні всім гравцям.\n\n\n\nПотім він продовжує випромінювати енергію, завдаючи $1259903s1 шкоди від тіні кожні $1259900t1 сек." },
    { en = "Averzian collapses void energy around his target, inflicting $s1 Shadow damage to all players. This damage is reduced by the number of players within $1249261A1 yards of the impact location.", ua = "Аверзіан стискає енергію Порожнечі довкола своєї цілі, завдаючи $s1 шкоди від тіні всім гравцям. Ця шкода зменшується залежно від кількості гравців у межах $1249261A1 ярдів від місця удару." },
    { en = "Voidspawn rush toward the player with the highest amount of $@spellname1265540 for the next $d.", ua = "Поріддя Порожнечі кидається до гравця з найбільшою кількістю $@spellname1265540 протягом наступних $d." },
    { en = "With three adjacent portals empowering each other, Averzian tears open the void unleashing the endless march, inflicting $1260981s1 Shadow damage every $1260981t1 sec to players in its path.", ua = "Коли три суміжні портали підсилюють один одного, Аверзіан розриває Порожнечу, вивільняючи нескінченний похід, що завдає $1260981s1 шкоди від тіні кожні $1260981t1 сек. гравцям на його шляху." },
    { en = "Vorasius sweeps a deadly beam across the battlefield, immediately inflicting  $1259921s1 Shadow damage to all players in front of him and $1242376s1 Shadow damage every $1256762t1 sec to players caught in its path. The beam radiates Dark Energy while active, inflicting $1280101s1 Shadow damage every $t1 sec for $d.", ua = "Воразіус проводить смертоносним променем по полю бою, миттєво завдаючи $1259921s1 шкоди від тіні всім гравцям перед собою та $1242376s1 шкоди від тіні кожні $1256762t1 с гравцям, що опинилися на його шляху. Доки промінь активний, він випромінює темну енергію, завдаючи $1280101s1 шкоди від тіні кожні $t1 с протягом $d." },
    { en = "If no player is within reach, Vorasius pulses with deadly void energy.", ua = "Якщо поблизу немає жодного гравця, Воразіус пульсує смертоносною енергією Порожнечі." },
    { en = "Dark ichor that inflicts $s1 Shadow damage to players within the area every $t1 sec.", ua = "Темна сукровиця, що завдає $s1 шкоди Тінню гравцям у межах ділянки кожні $t1 сек." },
    { en = "Vorasius gathers power with each roar, radiating $s1 Shadow damage to all players every $1272937t sec.", ua = "Воразіус набирає сили з кожним риком, випромінюючи $s1 шкоди від тіні всім гравцям кожні $1272937t сек." },
    { en = "Shadowclaw Slam creates seismic aftershocks that reverberate from the impact location, inflicting $1276811s1 Physical damage to players within the area.", ua = "Удар Тіньопазура породжує сейсмічні поштовхи, що розходяться від місця удару, завдаючи $1276811s1 фізичної шкоди гравцям у цій зоні." },
    { en = "The Blistercreep periodically spits void ichor at a player, reducing their movement speed by $s1% for $d. This effect stacks.", ua = "Пухировзкрад періодично плює сукровицею Порожнечі в гравця, зменшуючи його швидкість пересування на $s1% протягом $d. Цей ефект накопичується." },
    { en = "The Blistercreep explodes upon death, inflicting $s1 Shadow damage to players within $A1 yards, increasing their damage taken by $s2% for $d and knocking them away. The explosion also inflicts $s5 Shadow damage to all players.", ua = "Пухироповз вибухає, гинучи, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів, підвищуючи отримувану ними шкоду на $s2% протягом $d і відкидаючи їх. Вибух також завдає $s5 шкоди від тіні всім гравцям." },
    { en = "The impact from Vorasius's larger claws increases the victim's Physical damage taken by $s1% for $d. This effect stacks.", ua = "Удар більших пазурів Воразіуса збільшує фізичну шкоду, якої зазнає жертва, на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Vorasius takes a deep breath, pulling players closer before unleashing a deafening roar that inflicts $s1 Physical damage to all players and knocks them away.", ua = "Воразіус робить глибокий вдих, притягуючи гравців ближче, а тоді вивільняє оглушливий рев, що завдає $s1 фізичної шкоди всім гравцям і відкидає їх." },
    { en = "Vorasius shakes off parasitic Blistercreeps, spraying the battlefield with globs of dark ichor that inflict $1275556s1 Shadow damage to players within $1275554A1 yards upon impact.", ua = "Воразій струшує паразитичних пухироповзів, оббризкуючи поле бою згустками темної сукровиці, що завдають $1275556s1 шкоди Тінню гравцям у радіусі $1275554A1 ярдів при ударі." },
    { en = "Vorasius slams a giant claw into the ground, inflicting $1281906s0 Shadow and $1281954s0 Physical damage to players in the impact area and $1241808s0 Shadow damage to all players. If the central impact fails to hit at least 1 player, Vorasius inflicts $1241807s0 Shadow damage to all players instead. The impact of the larger claws applies Smashed and creates Void Crystals.", ua = "Воразіус врізає велетенський кіготь у землю, завдаючи $1281906s0 шкоди від тіні та $1281954s0 фізичної шкоди гравцям у зоні удару й $1241808s0 шкоди від тіні всім гравцям. Якщо центральний удар не влучає принаймні в 1 гравця, Воразіус натомість завдає $1241807s0 шкоди від тіні всім гравцям. Удар більших кігтів накладає Розтрощення та створює кристали Порожнечі." },
    { en = "Salhadaar manifests several Fractured Images of himself nearby.", ua = "Салгадаар створює довкола себе кілька розколотих образів самого себе." },
    { en = "Darkness smothers the affected player, absorbing $s1 healing.", ua = "Темрява огортає враженого гравця, поглинаючи $s1 зцілення." },
    { en = "Salhadaar consumes the orb on contact, inflicting $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Салгадаар поглинає сферу при дотику, завдаючи $s1 шкоди від тіні всім гравцям і додатково $s2 шкоди від тіні кожні $t2 сек. протягом $d." },
    { en = "Salhadaar hurls a dark star at his current target, inflicting $1250803s1 Shadow damage upon impact and causing $@spellname1251213 to erupt outwards from the impact location.", ua = "Салгадаар жбурляє темну зорю у свою поточну ціль, завдаючи $1250803s1 шкоди Тінню при ударі та змушуючи $@spellname1251213 вибухнути назовні з місця удару." },
    { en = "The Fractured Image releases a burst of void energy, inflicting $s2 Shadow damage to all players and leaving behind $@spellname1245592. The image then reintegrates with Salhadaar.", ua = "Розколоте Відображення вивільняє спалах енергії Порожнечі, завдаючи $s2 шкоди від тіні всім гравцям і лишаючи по собі $@spellname1245592. Тоді відображення знову зливається з Салгадааром." },
    { en = "Exposes players to an excessive amount of void energy, inflicting $s1 Shadow damage every $t1 sec to players within it.", ua = "Піддає гравців надмірній кількості енергії Порожнечі, завдаючи $s1 шкоди від тіні кожні $t1 сек. гравцям усередині." },
    { en = "Dark energy erupts from the ground, inflicting $s1 Shadow damage every $t1 sec to players within it.", ua = "Темна енергія вивергається із землі, завдаючи $s1 шкоди від тіні кожні $t1 с гравцям, що перебувають у ній." },
    { en = "Orbs of Concentrated Void cover all players in void essence when destroyed, inflicting $1285504s1 Shadow damage every $t sec for $d. This effect stacks.", ua = "Сфери Згущеної Порожнечі, коли їх знищують, вкривають усіх гравців есенцією Порожнечі, завдаючи $1285504s1 шкоди від тіні щосекунди $t протягом $d. Цей ефект накопичується." },
    { en = "Beams of pure void radiate from Salhadaar, inflicting $1260030s1 Shadow damage every $1260030t1 sec to players within them.", ua = "Промені чистої Порожнечі випромінюються від Салгадаара, завдаючи $1260030s1 шкоди від тіні кожні $1260030t1 сек. гравцям усередині них." },
    { en = "A dark barrier that protects from crowd control and interrupt effects.", ua = "Темний бар'єр, що захищає від ефектів контролю та переривання." },
    { en = "Salhadaar's melee attacks destabilize his current target, inflicting $1284963s1 Shadow damage every $1271579t1 sec for $1271579d. This effect stacks.", ua = "Атаки ближнього бою Салгадаара дестабілізують його поточну ціль, завдаючи $1284963s1 шкоди від тіні кожні $1271579t1 сек. протягом $1271579d. Цей ефект накопичується." },
    { en = "Lingering void energy that inflicts $s1 Shadow damage every $t1 sec to players within it.", ua = "Залишкова енергія Порожнечі, що завдає $s1 шкоди від тіні кожні $t1 сек. гравцям усередині неї." },
    { en = "Salhadaar attempts to bend several players to his will, inflicting $1260835s1 Shadow damage every $t1 sec to players within $1260835a1 yd of afflicted players for $d.\n\n\n\nWhen this aura expires, Salhadaar shrouds the wearer in $@spellname1248709$?DIFF14|DIFF15|DIFF16[ and creates a pool of $@spellname1245592 at the wearer's location][].", ua = "Салгадаар намагається підкорити кількох гравців своїй волі, завдаючи $1260835s1 шкоди від тіні кожні $t1 сек. гравцям у межах $1260835a1 ярдів від уражених гравців упродовж $d.\n\n\n\nКоли ця аура спадає, Салгадаар огортає носія в $@spellname1248709$?DIFF14|DIFF15|DIFF16[ і створює калюжу $@spellname1245592 на місці носія][]." },
    { en = "The machinery of the Riftlabs produces orbs of Concentrated Void that are drawn towards Salhadaar. Players who come into contact with an orb are afflicted by $@spellname1250828.\n\n\n\nSalhadaar consumes orbs on contact, causing a $@spellname1245960.", ua = "Механізми Лабораторій Розлому виробляють сфери Зосередженої Порожнечі, які притягуються до Салгадаара. Гравці, що торкаються сфери, зазнають дії $@spellname1250828.\n\n\n\nСалгадаар поглинає сфери при дотику, спричиняючи $@spellname1245960." },
    { en = "Salhadaar releases a bolt of twisting darkness that jumps between all players, inflicting $s1 Shadow damage upon contact and an additional $s3 Shadow damage every $t3 sec for $d.", ua = "Салгадаар вивільняє блискавку звивистої темряви, що перестрибує між усіма гравцями, завдаючи $s1 шкоди від тіні при контакті та додаткові $s3 шкоди від тіні кожні $t3 с протягом $d." },
    { en = "Upon reaching 100 energy, Salhadaar is overwhelmed by the Void. He unravels violently, inflicting $1254018s1 Shadow damage to all players every $1254019t1 sec and taking $s5% increased damage for $d.  \n\n\n\nUpon expiration, Salhadaar leaves behind $@spellname1245592.", ua = "Досягнувши 100 енергії, Салгадаар підкоряється Порожнечі. Він стрімко розпадається, завдаючи $1254018s1 шкоди від тіні всім гравцям кожні $1254019t1 сек. і отримуючи на $s5% більше шкоди протягом $d.  \n\n\n\nПісля завершення Салгадаар лишає по собі $@spellname1245592." },
    { en = "Forms an unstable rift which tethers players, pulling inward and inflicting $1244672s1 Shadow damage every $1244672T1 sec. This effect stacks.\n\n\n\nStretching this tether an additional $1244390s2 yards beyond the initial radius triggers a Nullsnap.$?diff15|diff16[ If no other tethered players remain, the field collapses, triggering a Nullzone Implosion instead.][]", ua = "Утворює нестабільний розлом, що прив'язує гравців, притягує всередину й кожні $1244672T1 с завдає $1244672s1 шкоди від тіні. Цей ефект накопичується.\n\n\n\nРозтягнення цієї прив'язі на додаткові $1244390s2 м за межі початкового радіуса спричиняє Нуль-розрив.$?diff15|diff16[ Якщо не лишається інших прив'язаних гравців, поле натомість колапсує, спричиняючи Імплозію Нуль-зони.][]" },
    { en = "Ezzorak slams targets within a $A1 yard rear cone, bleeding for $s1 Physical damage plus an additional $s2 Physical damage every $T2 sec and stunning for $D.\n\n\n\nThis occurs immediately after casting Rakfang.", ua = "Еззорак вдаряє цілі в задньому конусі завширшки $A1 м, завдаючи кровотечею $s1 фізичної шкоди й додатково $s2 фізичної шкоди кожні $T2 с і оглушуючи на $D.\n\n\n\nЦе стається одразу після створення Ракфанґа." },
    { en = "Xal'atath draws shadow power from her target, creating an Astral Reflection. This extradimensional clone lingers momentarily, casting the target's ability, then disintegrates.", ua = "Ксал'атат витягує з цілі силу тіні, створюючи Астральне Відображення. Цей позамежний клон затримується на мить, творить здібність цілі, а тоді розпадається." },
    { en = "Nullzone's first tether snap releases a cascade of cosmic hail, inflicting $1266570s1 Shadow damage to players within $1266570A1 yards of each impact location.", ua = "Перший розрив прив'язі 'Нуль-зони' вивільняє каскад космічного граду, завдаючи $1266570s1 шкоди від тіні гравцям у межах $1266570A1 м від кожного місця влучання." },
    { en = "Vaelgor expels crystalline spacetime every $1262676T1 sec for $1262651D to players in a frontal direction. This outpouring inflicts $1283856s1 Physical damage plus an additional $1262688s1 Shadow damage every $1262676T1 sec for $1262676D. This effect stacks.\n\n\n\nUpon completion, the lattice shatters, forming a Nullzone and tethering all players. Nullzone's pull magnitude weakens as Nullbeam stacks, up to $1262999U times.", ua = "Вейлґор кожні $1262676T1 с протягом $1262651D вивергає кристалічний простір-час на гравців перед собою. Цей потік завдає $1283856s1 фізичної шкоди й додатково $1262688s1 шкоди від тіні кожні $1262676T1 с протягом $1262676D. Цей ефект накопичується.\n\n\n\nПісля завершення ґратка розколюється, утворюючи Нуль-зону й прив'язуючи всіх гравців. Сила притягання Нуль-зони слабшає з кожним накопиченням Нуль-променя, до $1262999U разів." },
    { en = "The presence of the Lightbound Vanguard weakens this enemy's vitality, reducing their maximum health by $s1% and damage done by $s2%.\n\n\n\nThis effect stacks for each present member of the Vanguard.", ua = "Присутність Авангарду Світлозв'язаних послаблює життєву силу цього ворога, зменшуючи його максимальне здоров'я на $s1% і завдану шкоду на $s2%.\n\n\n\nЦей ефект накопичується за кожного присутнього члена Авангарду." },
    { en = "The clutchmates share a link, increasing damage done by $s1% if $?diff14|diff15|diff16[their remaining health diverges by at least $s2% of total health, or are closer than $s3 yards of each other.][they are closer than $s3 yards of each other.]\n\n\n\nIf one of the dragons dies, the remaining dragon gains Twilight Fury.", ua = "Побратими з виводка ділять зв'язок, що збільшує завдану шкоду на $s1%, якщо $?diff14|diff15|diff16[різниця в їхньому залишковому здоров'ї становить щонайменше $s2% від загального здоров'я або вони ближче ніж за $s3 ярдів один від одного.][вони ближче ніж за $s3 ярдів один від одного.]\n\n\n\nЯкщо один із драконів гине, дракон, що лишився, отримує Сутінкову Лють." },
    { en = "Vaelgor roars toward a targeted player, fearing $?diff17[them.][players in a massive frontal cone.] The dragon's breath inflicts $1244225s1 Shadow damage and an additional $1255979s1 Shadow damage every $1255979T1 sec$?diff16[, increasing movement speed by $1255979s4%,][, reducing movement speed by $1255979s3%,]$?diff17[ for $1255979D.][ fearing them for $1255979D.]", ua = "Вейлґор реве в бік обраного гравця, вселяючи жах $?diff17[у нього.][у гравців у величезному передньому конусі.] Подих дракона завдає $1244225s1 шкоди від тіні та додатково $1255979s1 шкоди від тіні кожні $1255979T1 сек$?diff16[, збільшуючи швидкість пересування на $1255979s4%,][, знижуючи швидкість пересування на $1255979s3%,]$?diff17[ протягом $1255979D.][ і вселяючи в них жах на $1255979D.]" },
    { en = "The cosmic field collapses, inflicting $1252157s2 Shadow damage and an additional $1285954s1 Shadow damage every $1252157T1 sec for $1252157D to all players.", ua = "Космічне поле руйнується, завдаючи $1252157s2 шкоди від тіні та додатково $1285954s1 шкоди від тіні кожні $1252157T1 сек. протягом $1252157D усім гравцям." },
    { en = "Gloomtouched's affliction weighs heavily on targets, increasing damage taken by Gloomtouched by $s1% for $D. This effect stacks.", ua = "Хвороба Мороком тяжко гнітить цілі, збільшуючи шкоду, яку завдає їм Морок, на $s1% протягом $D. Цей ефект накопичується." },
    { en = "While flying, the dragon lashes their primary target in cosmic entanglement, inflicting between $1283971s1 and ${$1283971s1*10} Shadow damage, increasing in damage as distance between the dragon and their target increases.\n\n\n\nThe dragon then pulls the distant target nearby.", ua = "У польоті дракон обплутує свою основну ціль косимічними путами, завдаючи від $1283971s1 до ${$1283971s1*10} шкоди від тіні, причому шкода зростає зі збільшенням відстані між драконом і його ціллю.\n\n\n\nПотім дракон притягує віддалену ціль до себе." },
    { en = "Ezzorak strikes his primary target, inflicting $1245647s1 Physical damage and $1245652s1 Shadow damage.\n\n\n\nThis attack empowers Ezzorak's melee attacks, causing them to absorb the next $1280355s1 healing. This effect stacks, increasing in intensity each Rakfang until Rakfang strikes a new target.", ua = "Еззорак б'є свою основну ціль, завдаючи $1245647s1 фізичної шкоди та $1245652s1 шкоди від тіні.\n\n\n\nЦей удар підсилює атаки Еззорака в ближньому бою, змушуючи їх поглинати наступні $1280355s1 зцілення. Цей ефект накопичується, посилюючись із кожним Ракфангом, доки Ракфанг не вразить нову ціль." },
    { en = "Ezzorak ejects a moving mass of pure darkness in a frontal direction, inflicting $1245500s1 to ${$1245500s1*$1245500s2} Shadow damage to all players upon arrival, creating a Gloomfield.\n\n\n\nGloom damage done and the size of Gloomfield decreases up to $1245391s1 times as players contact the darkness, applying Gloomtouched.", ua = "Еззорак вивергає рухому масу чистої темряви вперед, завдаючи від $1245500s1 до ${$1245500s1*$1245500s2} шкоди від тіні всім гравцям при досягненні цілі й створюючи поле Мороку.\n\n\n\nШкода від Мороку та розмір поля Мороку зменшуються до $1245391s1 разів, коли гравці торкаються темряви, накладаючи Дотик Мороку." },
    { en = "Senn eminates holy power for $1248847D, blessing players within $1248847A1 yards. Every $1248847T2 sec, this applies protection to nearby players that absorbs $1249595s1 Midnight Flames damage. If present, Bellamy and/or Lightblood increase the amount of absorb granted. ${100-$1248865s1}% of Midnight Flames damage pierces this absorb.\n\n\n\nAdditionally, gaining Radiant Barrier consumes Midnight Manifestation, spawning a Manifestation of Midnight or infusing an existing Manifestation for each aura stack consumed.", ua = "Сенн випромінює святу силу протягом $1248847D, благословляючи гравців у межах $1248847A1 ярдів. Кожні $1248847T2 сек це накладає на ближніх гравців захист, що поглинає $1249595s1 шкоди від Опівнічного полум'я. Якщо присутні, Беллемі та/або Лайтблад збільшують величину наданого поглинання. ${100-$1248865s1}% шкоди від Опівнічного полум'я пробиває це поглинання.\n\n\n\nКрім того, отримання Променистого бар'єру споживає Опівнічний прояв, призиваючи Прояв Опівніччя або напоюючи наявний Прояв за кожен спожитий заряд аури." },
    { en = "Vaelgor knocks away players within a $A1 yard rear cone, bleeding for $s1 Physical damage plus an additional $s2 Physical damage every $T2 sec for $D.", ua = "Вейлґор відкидає гравців у тиловому конусі $A1 ярдів, завдаючи кровотечею $s1 фізичної шкоди та додатково $s2 фізичної шкоди кожні $T2 сек. протягом $D." },
    { en = "Upon reaching 100 energy, Ezzorak and Vaelgor fly as one, each spewing $1249748s2 Shadow damage to all players plus an additional $1250071s1 Shadow damage every $1249748T1 sec for $1249748D.", ua = "Досягнувши 100 енергії, Еззорак і Вейлґор злітають як одне ціле, кожен вивергаючи $1249748s2 шкоди від тіні всім гравцям і додатково $1250071s1 шкоди від тіні кожні $1249748T1 сек. протягом $1249748D." },
    { en = "Xal'atath appears, tipping the scales and enfeebling targeted players, then vanishes.\n\n\n\nThis malediction inflicts $1259275s1 Shadow damage every $1255763T1 sec. This effect stacks.", ua = "Ксал'атат з'являється, схиляючи терези й знесилюючи позначених гравців, а тоді зникає.\n\n\n\nЦе прокляття завдає $1259275s1 шкоди від тіні кожні $1255763T1 сек. Цей ефект накопичується." },
    { en = "Every $1251686T1 sec, the manifestation darkens, increasing attack speed by $1251686s2% and reducing the speed at which they can be slowed to by $1251686s3%. This effect stacks.", ua = "Кожні $1251686T1 с прояв темніє, збільшуючи швидкість атаки на $1251686s2% і зменшуючи межу, до якої його можна сповільнити, на $1251686s3%. Цей ефект накопичується." },
    { en = "Upon seeing their sibling perish, the remaining dragon enters a draconic rage, increasing damage done by $s1%. This effect stacks, increasing in intensity over time.", ua = "Побачивши загибель свого побратима, дракон, що лишився, впадає в драконячу лють, збільшуючи завдану шкоду на $s1%. Цей ефект накопичується, посилюючись із часом." },
    { en = "Vaelgor buffets his primary target, knocking them away and inflicting $1265143s1 Shadow damage and $1265139s1 Physical damage. \n\n\n\nThis attack empowers Vaelgor's melee attacks, causing them to inflict $1280434s1 Shadow damage. This effect stacks, increasing in intensity each Vaelwing until Vaelwing strikes a new target.", ua = "Вейлґор б'є свою головну ціль, відкидаючи її та завдаючи $1265143s1 шкоди від тіні і $1265139s1 фізичної шкоди. \n\n\n\nЦя атака підсилює атаки ближнього бою Вейлґора, через що вони завдають $1280434s1 шкоди від тіні. Цей ефект накопичується, посилюючись із кожним застосуванням Велвінги, доки Велвінг не вразить нову ціль." },
    { en = "Galactic emptiness engulfs a massive location in darkness for $1245420D, inflicting $1245421s1 Shadow damage every $1245421T1 sec and reducing movement speed by $1245421s2%.", ua = "Галактична порожнеча огортає величезну ділянку темрявою на $1245420D, завдаючи $1245421s1 шкоди від тіні кожні $1245421T1 с і зменшуючи швидкість пересування на $1245421s2%." },
    { en = "The manifestation taints targets inflicting $1270513s1 Shadow damage every $1270497T1 sec for $1270497D.\n\n\n\nUpon expiration the mark detonates inflicting $1270516s1 Shadow damage to other players within $1270516A1 yards of the marked target.", ua = "Прояв опоганює цілі, завдаючи $1270513s1 шкоди від тіні кожні $1270497T1 с протягом $1270497D.\n\n\n\nПісля завершення мітка детонує, завдаючи $1270516s1 шкоди від тіні іншим гравцям у радіусі $1270516A1 м від позначеної цілі." },
    { en = "A dark malady drips from those in contact with Gloom, inflicting $1283711s1 Shadow damage plus an additional $1283712s1 Shadow damage every $1245554T1 sec for $1245554D$?diff16[ to players within $1245554A1 yards of the contacting player][]. This effect stacks.$?diff15|diff16[\n\n\n\nUpon removal, Gloomtouched applies Diminish.][]", ua = "Темна недуга стікає з тих, хто торкнувся Мороку, завдаючи $1283711s1 шкоди від тіні плюс додаткові $1283712s1 шкоди від тіні кожні $1245554T1 с протягом $1245554D$?diff16[ гравцям у межах $1245554A1 м від ураженого гравця][]. Цей ефект накопичується.$?diff15|diff16[\n\n\n\nПісля зняття Торкнутий Мороком накладає Послаблення.][]" },
    { en = "Ezzorak wreathes all players in shadow, inflicting $1245302s1 Shadow damage to players within $1245302A1 yards of each player.\n\n\n\nSummons a Voidorb at each players' location.", ua = "Еззорак огортає всіх гравців тінню, завдаючи $1245302s1 шкоди від тіні гравцям у радіусі $1245302A1 м від кожного гравця.\n\n\n\nПризиває кулю Порожнечі в місці кожного гравця." },
    { en = "The Voidorb ejects raw void magic at a player, inflicting $1245175s1 Shadow damage plus an additional $1245175s2 Shadow damage every $1245175T2 sec for $1245175D.$?diff16[ This effect stacks.][]", ua = "Сфера Порожнечі викидає в гравця сиру магію Порожнечі, завдаючи $1245175s1 шкоди від тіні та додатково $1245175s2 шкоди від тіні кожні $1245175T2 сек. протягом $1245175D.$?diff16[ Цей ефект накопичується.][]" },
    { en = "The cosmic bindings shatter, inflicting $1244413s1 Shadow damage to all players.", ua = "Космічні пута розламуються, завдаючи $1244413s1 шкоди від тіні всім гравцям." },
    { en = "A vortex of holy energy that inflicts $s1 Holy damage to players within $s3 yards every $t1 sec and reduces their movement speed by $s2%.", ua = "Вихор енергії Світла, що кожні $t1 с завдає $s1 шкоди від Світла гравцям у радіусі $s3 м і зменшує їхню швидкість пересування на $s2%." },
    { en = "Bellamy unleashes a volley of holy shields every $t1 sec for $d. Shields that hit players inflict $1248652s1 Holy damage and silence them for $1248652d.", ua = "Беллемі вивільняє залп священних щитів кожні $t1 с протягом $d. Щити, що влучають у гравців, завдають $1248652s1 шкоди від Світла й знемовлюють їх на $1248652d." },
    { en = "Lightblood passes judgment on his current target, inflicting $s1 Holy damage and increasing damage they take from $@spellname1251812 by $s2% for $d.\n\n\n\nAfter passing judgment, Lightblood immediately casts Final Verdict on his current target.", ua = "Лайтблад чинить суд над своєю поточною ціллю, завдаючи $s1 шкоди від Світла й підвищуючи шкоду, яку та отримує від $@spellname1251812, на $s2% протягом $d.\n\n\n\nПісля винесення вироку Лайтблад негайно творить Остаточний вирок на свою поточну ціль." },
    { en = "Bellamy passes judgment on her current target, inflicting $s1 Holy damage and increasing damage they take from $@spellname1251859 by $s2% for $d.\n\n\n\nAfter passing judgment, Bellamy immediately casts $@spellname1251859 on her current target.", ua = "Беллемі чинить суд над своєю поточною ціллю, завдаючи $s1 шкоди від Світла й підвищуючи шкоду, яку та отримує від $@spellname1251859, на $s2% протягом $d.\n\n\n\nПісля винесення вироку Беллемі негайно творить $@spellname1251859 на свою поточну ціль." },
    { en = "Senn emits a blinding flash of light, inflicting $s1 Holy damage to all players and disorienting them for $d.", ua = "Сенн випускає сліпучий спалах світла, завдаючи $s1 священної шкоди всім гравцям і дезорієнтуючи їх на $d." },
    { en = "Bellamy slams her current target with her shield, inflicting $s1 Holy damage.", ua = "Беллемі вдаряє свою поточну ціль щитом, завдаючи $s1 шкоди від Світла." },
    { en = "Bellamy targets several players with holy shields that explode on impact, inflicting $s1 Holy damage plus an additional $s2 Holy damage every $t2 sec to players within $a1 yards.", ua = "Беллемі позначає кількох гравців священними щитами, що вибухають при влучанні, завдаючи $s1 шкоди від Світла та додатково $s2 шкоди від Світла кожні $t2 сек. гравцям у межах $a1 ярдів." },
    { en = "Holy hammers spiral outward, inflicting $s1 Holy damage to players in their path.", ua = "Священні молоти розходяться спіраллю, завдаючи $s1 шкоди від Світла гравцям на своєму шляху." },
    { en = "The manifested Spirit moves to Bellamy's side, preparing to unleash Tyr's Wrath alongside her next Divine Toll.\n\n\n\nIt then emboldens Bellamy with Zealous Spirit, increasing her damage and empowering her Avenger's Shield.", ua = "Проявлений Дух стає поруч з Беллемі, готуючись вивільнити Гнів Тіра разом з її наступним Божественним Передзвоном.\n\n\n\nПісля цього він надихає Беллемі Ревним Духом, підвищуючи її шкоду та посилюючи її Щит Месника." },
    { en = "Senn exorcises her current target, inflicting $s1 Holy damage.", ua = "Сенн виганяє з її поточної цілі біса, завдаючи $s1 шкоди від Світла." },
    { en = "Lightblood deems players within $a1 yards unworthy, inflicting $s1 Holy damage to them.", ua = "Лайтблад визнає гравців у радіусі $a1 м негідними, завдаючи їм $s1 шкоди від Світла." },
    { en = "$?DIFF17[Lightblood marks several players, then attempts to execute them $s2 sec later, inflicting $1249024s1 Holy damage split evenly among players within $1249024a1 yards of their location.\n\n\n\n$s1 Divine Hammers then spiral outward from the impact location.][]$?DIFF14[Lightblood marks several players, then attempts to execute them $s2 sec later, inflicting $1249024s1 Holy damage split evenly among players within $1249024a1 yards of their location and increasing damage taken from Execution Sentence by $1249024s2% for $1249024d.\n\n\n\n$s1 Divine Hammers then spiral outward from the impact location.][]", ua = "$?DIFF17[Лайтблад позначає кількох гравців, а тоді за $s2 сек намагається стратити їх, завдаючи $1249024s1 шкоди від Світла, рівномірно розподіленої між гравцями в межах $1249024a1 ярдів від їхнього розташування.\n\n\n\nПісля цього $s1 божественних молотів спірально розходяться назовні з місця влучання.][]$?DIFF14[Лайтблад позначає кількох гравців, а тоді за $s2 сек намагається стратити їх, завдаючи $1249024s1 шкоди від Світла, рівномірно розподіленої між гравцями в межах $1249024a1 ярдів від їхнього розташування, і підвищуючи отримувану від Смертного Вироку шкоду на $1249024s2% протягом $1249024d.\n\n\n\nПісля цього $s1 божественних молотів спірально розходяться назовні з місця влучання.][]" },
    { en = "Senn shields herself, absorbing the next $s1 damage and becoming immune to interrupt effects. She then charges into battle on her mighty elekk before casting $@spellname1258514.", ua = "Сенн захищає себе щитом, поглинаючи наступні $s1 шкоди й стаючи несприйнятливою до ефектів переривання. Потім вона кидається в бій на своєму могутньому елекку, перш ніж сотворити $@spellname1258514." },
    { en = "Bellamy is infused with holy light that inflicts $s1 Holy damage to all players every $1258659t1 sec. \n\n\n\nThis damage increases by $1258662s1% every time a member of the Vanguard unleashes their aura.", ua = "Беллемі насичена святим світлом, що завдає $s1 шкоди від Світла всім гравцям щосекунди $1258659t1.\n\n\n\nЦя шкода зростає на $1258662s1% щоразу, коли член Авангарду вивільняє свою ауру." },
    { en = "Lightblood unleashes a devastating storm of Holy energy, inflicting $s1 Holy damage to players within $a1 yards.", ua = "Лайтблад вивільняє нищівну бурю енергії Світла, завдаючи $s1 шкоди від Світла гравцям у радіусі $a1 м." },
    { en = "The Vanguard member calls upon the Light to protect them, becoming immune to all damage and harmful effects for $d.", ua = "Член Авангарду закликає Світло собі на захист, стаючи несприйнятливим до всієї шкоди та шкідливих ефектів протягом $d." },
    { en = "Lightblood calls upon the Light to become an avatar of its fury, increasing his damage done by $s1% and damage taken by $s3% for $d.", ua = "Лайтблад закликає Світло, аби стати втіленням його люті, підвищуючи завдану ним шкоду на $s1% і отримувану шкоду на $s3% протягом $d." },
    { en = "Consecrated ground inflicts $1276982s1 Holy damage to players within every $1276982t1 sec, increases all damage they take by $1276982s3%, and pacifies them.", ua = "Освячена земля кожні $1276982t1 с завдає гравцям на ній $1276982s1 шкоди від Світла, підвищує всю отримувану ними шкоду на $1276982s3% і знесилює їх." },
    { en = "After using a powerful ability, members of the Vanguard cannot be affected by Avenging Wrath or Divine Shield for $d.", ua = "Після застосування потужної здібності члени Авангарду не можуть зазнати дії Караючого Гніву чи Божественного Щита протягом $d." },
    { en = "Senn channels the holy Light for $1255738d, inflicting $s1 Holy damage to all players every $t1 sec.", ua = "Сенн підтримує священне Світло протягом $1255738d, завдаючи $s1 шкоди від Світла всім гравцям кожні $t1 сек." },
    { en = "$?DIFF14[Upon reaching 100 energy, Lightblood emanates an $@spellname1248450 for $1248449d, increasing Holy damage done by $s1% for allies within $1248449s2 yards.][]$?DIFF17[Upon reaching 100 energy, Lightblood emanates an $@spellname1248450 for $1248449d, increasing Holy damage done by $s1% for allies within $1248449s2 yards.][]$?DIFF15[Upon reaching 100 energy, Lightblood emanates an $@spellname1248450 for $1248449d, increasing Holy damage done by $s1% for allies within $1248449s2 yards.\n\n\n\nUpon expiration, Lightblood consecrates the ground beneath his feet.][]$?DIFF16[Upon reaching 100 energy, Lightblood emanates an $@spellname1248450 for $1248449d, increasing Holy damage done by $s1% for allies within $1248449s2 yards.\n\n\n\nUpon expiration, Lightblood consecrates the ground beneath his feet.][]", ua = "$?DIFF14[Сягнувши 100 енергії, Лайтблад випромінює $@spellname1248450 на $1248449d, підвищуючи шкоду від Світла на $s1% для союзників у межах $1248449s2 ярдів.][]$?DIFF17[Сягнувши 100 енергії, Лайтблад випромінює $@spellname1248450 на $1248449d, підвищуючи шкоду від Світла на $s1% для союзників у межах $1248449s2 ярдів.][]$?DIFF15[Сягнувши 100 енергії, Лайтблад випромінює $@spellname1248450 на $1248449d, підвищуючи шкоду від Світла на $s1% для союзників у межах $1248449s2 ярдів.\n\n\n\nКоли ефект спливає, Лайтблад освячує землю під своїми ногами.][]$?DIFF16[Сягнувши 100 енергії, Лайтблад випромінює $@spellname1248450 на $1248449d, підвищуючи шкоду від Світла на $s1% для союзників у межах $1248449s2 ярдів.\n\n\n\nКоли ефект спливає, Лайтблад освячує землю під своїми ногами.][]" },
    { en = "$?DIFF14[Upon reaching 100 energy, Senn emanates a calming $@spellname1248451 for $d, protecting allies within $s2 yards and pacifying any player who directly attacks them for $1250812d.][]$?DIFF17[Upon reaching 100 energy, Senn emanates a calming $@spellname1248451 for $d, protecting allies within $s2 yards and pacifying any player who directly attacks them for $1250812d.][]$?DIFF15[Upon reaching 100 energy, Senn emanates a calming $@spellname1248451 for $d, protecting allies within $s2 yards and pacifying any player who directly attacks them for $1250812d.\n\n\n\nUpon expiration, Senn consecrates the ground beneath her feet.][]$?DIFF16[Upon reaching 100 energy, Senn emanates a calming $@spellname1248451 for $d, protecting allies within $s2 yards and pacifying any player who directly attacks them for $1250812d.\n\n\n\nUpon expiration, Senn consecrates the ground beneath her feet.][]", ua = "$?DIFF14[Сягнувши 100 енергії, Сенн випромінює заспокійливу $@spellname1248451 на $d, захищаючи союзників у межах $s2 ярдів і втихомирюючи на $1250812d будь-якого гравця, що нападає на них напряму.][]$?DIFF17[Сягнувши 100 енергії, Сенн випромінює заспокійливу $@spellname1248451 на $d, захищаючи союзників у межах $s2 ярдів і втихомирюючи на $1250812d будь-якого гравця, що нападає на них напряму.][]$?DIFF15[Сягнувши 100 енергії, Сенн випромінює заспокійливу $@spellname1248451 на $d, захищаючи союзників у межах $s2 ярдів і втихомирюючи на $1250812d будь-якого гравця, що нападає на них напряму.\n\n\n\nКоли ефект спливає, Сенн освячує землю під своїми ногами.][]$?DIFF16[Сягнувши 100 енергії, Сенн випромінює заспокійливу $@spellname1248451 на $d, захищаючи союзників у межах $s2 ярдів і втихомирюючи на $1250812d будь-якого гравця, що нападає на них напряму.\n\n\n\nКоли ефект спливає, Сенн освячує землю під своїми ногами.][]" },
    { en = "The Lightblinded Vanguard seek retribution for any of their allies slain in battle, increasing their damage done by $s1% every $1278108t1 sec until they avenge their fallen ally or die trying.", ua = "Світлосліпа Передова Варта прагне відплати за будь-якого зі своїх союзників, полеглих у бою, збільшуючи завдану шкоду на $s1% кожні $1278108t1 с, доки не помститься за полеглого товариша чи не загине, намагаючись це зробити." },
    { en = "Senn brings $@spellname1248721 down upon the $1248718s1 players nearest to her every $1248710t1 sec, absorbing the next $s1 healing they receive. This effect stacks.", ua = "Сенн насилає $@spellname1248721 на $1248718s1 найближчих до неї гравців кожні $1248710t1 сек., поглинаючи наступні $s1 зцілення, що вони отримують. Цей ефект накопичується." },
    { en = "Consecrated ground inflicts $424430s1 Holy damage to players within every $s2 sec.", ua = "Освячена земля завдає $424430s1 священної шкоди гравцям, що стоять на ній, кожні $s2 сек." },
    { en = "$?DIFF14[Upon reaching 100 energy, Bellamy emanates an $@spellname1246162 for $d, reducing damage taken by $1246165s2% for allies within $s1 yards.][]$?DIFF17[Upon reaching 100 energy, Bellamy emanates an $@spellname1246162 for $d, reducing damage taken by $1246165s2% for allies within $s1 yards.][]$?DIFF15[Upon reaching 100 energy, Bellamy emanates an $@spellname1246162 for $d, reducing damage taken by $1246165s2% for allies within $s1 yards.\n\n\n\nUpon expiration, Bellamy consecrates the ground beneath her feet.][]$?DIFF16[Upon reaching 100 energy, Bellamy emanates an $@spellname1246162 for $d, reducing damage taken by $1246165s2% for allies within $s1 yards.\n\n\n\nUpon expiration, Bellamy consecrates the ground beneath her feet.][]", ua = "$?DIFF14[Досягнувши 100 енергії, Беламі випромінює $@spellname1246162 на $d, зменшуючи шкоду, що отримують союзники в межах $s1 ярдів, на $1246165s2%.][]$?DIFF17[Досягнувши 100 енергії, Беламі випромінює $@spellname1246162 на $d, зменшуючи шкоду, що отримують союзники в межах $s1 ярдів, на $1246165s2%.][]$?DIFF15[Досягнувши 100 енергії, Беламі випромінює $@spellname1246162 на $d, зменшуючи шкоду, що отримують союзники в межах $s1 ярдів, на $1246165s2%.\n\n\n\nПісля завершення Беламі освячує землю під своїми ногами.][]$?DIFF16[Досягнувши 100 енергії, Беламі випромінює $@spellname1246162 на $d, зменшуючи шкоду, що отримують союзники в межах $s1 ярдів, на $1246165s2%.\n\n\n\nПісля завершення Беламі освячує землю під своїми ногами.][]" },
    { en = "A Zealous Spirit emboldens a member of the Vanguard, increasing their damage done by $s1% for $d and empowering one of their abilities. \n\n\n\nUpon expiration, the Spirit manifests and seeks out a new member of the Vanguard.", ua = "Запальний дух підбадьорює бійця Авангарду, збільшуючи завдану ним шкоду на $s1% протягом $d та підсилюючи одну з його здібностей. \n\n\n\nПісля завершення дух проявляється і шукає нового бійця Авангарду." },
    { en = "Lightblood marks several players then attempts to execute them $s2 sec later, inflicting $1249024s1 Holy damage split evenly among players within $1249024a1 yards of their location and increasing damage taken from Execution Sentence by $1249024s2% for $1249024d.\n\n\n\n$s1 Divine Hammers then spiral outward from the impact location.", ua = "Лайтблад позначає кількох гравців, а тоді намагається стратити їх через $s2 с, завдаючи $1249024s1 шкоди від Світла, розподіленої порівну між гравцями в радіусі $1249024a1 м від їхнього місця, і збільшуючи шкоду від Вироку Страти, якої вони зазнають, на $1249024s2% протягом $1249024d.\n\n\n\nТоді $s1 божественних молотів розходяться спіраллю від місця удару." },
    { en = "Lightblood unleashes a devastating strike on his current target that inflicts $s1 Holy damage.", ua = "Лайтблад завдає нищівного удару по своїй поточній цілі, завдаючи $s1 священної шкоди." },
    { en = "Senn charges forward on her mighty elekk, inflicting $1249135s1 Physical damage to players in her path.", ua = "Сенн мчить уперед на своєму могутньому елекку, завдаючи $1249135s1 фізичної шкоди гравцям на своєму шляху." },
    { en = "The manifested Spirit moves to Senn's side, preparing to unleash Execution Sentence alongside her next Tyr's Wrath.\n\n\n\nIt then emboldens Senn with Zealous Spirit, increasing her damage and empowering her Searing Radiance.", ua = "Явлений Дух стає поряд із Сенн, готуючись розв'язати «Смертний вирок» разом із її наступним «Гнівом Тіра».\n\n\n\nДалі він надихає Сенн «Ревним духом», підвищуючи її шкоду й посилюючи її «Пекуче сяйво»." },
    { en = "The manifested Spirit moves to Lightblood's side, preparing to unleash Divine Toll alongside his next Execution Sentence.\n\n\n\nIt then emboldens Lightblood with Zealous Spirit, increasing his damage and empowering his Divine Storm.", ua = "Проявлений дух стає на бік Лайтблада, готуючись вивільнити Божественний Подзвін разом із його наступним Смертним Вироком.\n\n\n\nПотім він надихає Лайтблада Ревним Духом, збільшуючи його шкоду й підсилюючи його Божественний Шторм." },
    { en = "The Rift Simulacrum grants Alleria and her Voidspawn $1237593s2% reduced damage taken and $1237593s1% increased damage done every $t1 sec while they are within $s2 yards of it. This effect stacks.", ua = "Симулякр Розлому надає Аллерії та її пагону Порожнечі на $1237593s2% менше отримуваної шкоди та на $1237593s1% більше завданої шкоди кожні $t1 сек., поки вони перебувають у межах $s2 ярдів від нього. Цей ефект накопичується." },
    { en = "Uncontrolled silver-lined arrows fire from Alleria, inflicting $1235617s1 Arcane damage and removing Void effects from players struck.", ua = "Від Аллерії безконтрольно летять стріли зі срібними вістрями, завдаючи $1235617s1 арканної шкоди та знімаючи ефекти Порожнечі з уражених гравців." },
    { en = "Raw Void energy arcs outward from Alleria, inflicting $1234570s1 Shadow damage every $1234570t1 sec and increasing the effects of forced movement by $1234570s2% for $1234570d. This effect stacks.", ua = "Від Аллерії розходиться чиста енергія Порожнечі, завдаючи $1234570s1 шкоди від тіні кожні $1234570t1 сек і посилюючи ефекти примусового пересування на $1234570s2% протягом $1234570d. Цей ефект накопичується." },
    { en = "Upon reaching 100 energy, the Voidspawn permanently gains $s2% movement speed, $s3% damage done, and immunity to crowd controlling effects.", ua = "Сягнувши 100 одиниць енергії, поріддя Порожнечі назавжди отримує $s2% швидкості пересування, $s3% завданої шкоди та несприйнятливість до ефектів знерухомлення." },
    { en = "A backlash of magic blasts out from each obelisk, inflicting $s1 Shadow damage to all players struck.", ua = "З кожного обеліска виривається спалах магії, завдаючи $s1 шкоди від тіні всім враженим гравцям." },
    { en = "When an Undying Sentinel is struck with silver, it suffers $s1 Arcane damage every $t1 sec until it dies. This damage removes Void effects.", ua = "Коли Безсмертний вартовий уражений сріблом, він зазнає $s1 арканної шкоди кожні $t1 сек. до самої смерті. Ця шкода знімає ефекти Порожнечі." },
    { en = "Wild pockets of gravity surge from Alleria, inflicting $1235631s1 Shadow damage to players within $1235631A1 yards of each impact and knocking them away.", ua = "Від Аллерії линуть дикі згустки гравітації, завдаючи $1235631s1 шкоди від тіні гравцям у межах $1235631A1 ярдів від кожного влучання та відкидаючи їх." },
    { en = "Alleria marks players with a consuming arrow, reducing their healing received by $1239111s1% until they move $s1 yards away from the arrow. This effect stacks, growing in intensity every $1239111t3 sec. \n\n\n\nUpon being removed, a Gravity Collapse is triggered.", ua = "Аллерія позначає гравців пожиральною стрілою, зменшуючи отримуване ними зцілення на $1239111s1%, доки вони не відійдуть від стріли на $s1 м. Цей ефект накопичується, посилюючись кожні $1239111t3 с. \n\n\n\nПісля зняття спрацьовує Гравітаційний колапс." },
    { en = "Alleria fires a Void-tipped arrow at several players, inflicting $1237040s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Аллерія випускає стрілу з вістрям Порожнечі по кількох гравцях, завдаючи $1237040s1 шкоди від тіні кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Reverberating darkness knocks the target upwards and increases their Physical damage taken by $1255453s1% for $1255453d. The cosmic tremors additionally inflict $1239095s1 Shadow damage to all other players.", ua = "Відлунна темрява підкидає ціль угору й підвищує отримувану нею фізичну шкоду на $1255453s1% на $1255453d. Космічні поштовхи додатково завдають $1239095s1 шкоди від тіні всім іншим гравцям." },
    { en = "Stellar mass orbits around Alleria, inflicting $1246001s1 Shadow damage and pulling players it collides with.", ua = "Довкола Аллерії обертається зоряна маса, завдаючи $1246001s1 шкоди від тіні та притягуючи гравців, з якими стикається." },
    { en = "A player touching a cosmic feather fallen from Alleria's quiver gains greatly increased movement speed and suffers $1238709s1 Shadow damage every $t2 sec for $d.", ua = "Гравець, що торкається космічного пера, упалого з сагайдака Аллерії, отримує значно підвищену швидкість пересування та зазнає $1238709s1 шкоди від тіні щосекунди $t2 протягом $d." },
    { en = "Void energy remains on the ground, inflicting $s1 Shadow damage to all players within it every $t1 sec.", ua = "Енергія Порожнечі лишається на землі, завдаючи $s1 шкоди від тіні всім гравцям у ній кожні $t1 сек." },
    { en = "Alleria calls upon the unending cosmos to consume her foes. Players caught within suffer $1238882s1 Shadow damage every $1227557t1 sec and receive $1227557s3% reduced healing and absorbs.", ua = "Аллерія прикликає нескінченний космос, щоб поглинути своїх ворогів. Гравці, захоплені в пастку, зазнають $1238882s1 шкоди від тіні кожні $1227557t1 сек. та отримують на $1227557s3% менше зцілення й поглинання." },
    { en = "Void magic binds the Sentinel to existence, preventing it from dying.", ua = "Магія Порожнечі прив'язує Вартового до буття, не даючи йому загинути." },
    { en = "Stepping on a volatile ground fissure inflicts $1238210s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Наступ на хитку тріщину в землі завдає $1238210s1 шкоди від тіні щосекунди $t1 протягом $d. Цей ефект накопичується." },
    { en = "Alleria marks a player, firing a silver-lined arrow through them. The arrow inflicts $1233649s1 Arcane damage in a line and removes Void effects from players and Voidspawn struck.", ua = "Аллерія позначає гравця і пускає крізь нього стрілу зі срібним обрамленням. Стріла завдає $1233649s1 арканної шкоди по лінії та знімає ефекти Порожнечі з уражених гравців і поріддя Порожнечі." },
    { en = "A void barrier surrounds the Rift Simulacrum, absorbing damage equal to $s3% of its maximum health. While this barrier persists, it inflicts $1246925s1 Shadow damage to all players every $t2 sec.", ua = "Бар'єр Порожнечі оточує Симулякр Розлому, поглинаючи шкоду в розмірі $s3% його максимального здоров'я. Поки цей бар'єр існує, він завдає $1246925s1 шкоди від тіні всім гравцям кожні $t2 с." },
    { en = "Alleria calls down a celestial body near a player. This energy crashes into the ground and inflicts $1233826s1 Shadow damage to all players.", ua = "Аллерія прикликає небесне тіло поблизу гравця. Ця енергія врізається в землю й завдає $1233826s1 шкоди від тіні всім гравцям." },
    { en = "Alleria places a shell of Void magic around a player that absorbs $s1 healing. If $@spellname1233865 is dispelled, the remaining absorb jumps to another random player.", ua = "Аллерія огортає гравця оболонкою магії Порожнечі, що поглинає $s1 зцілення. Якщо $@spellname1233865 розвіяти, залишок поглинання перестрибує на іншого випадкового гравця." },
    { en = "Celestial energy bursts around Alleria, inflicting $1237875s1 Shadow damage within $1237875A1 yards of each impact and calling forth an Undying Voidspawn.", ua = "Навколо Аллерії вибухає небесна енергія, завдаючи $1237875s1 шкоди від тіні в межах $1237875A1 ярдів від кожного влучання та прикликаючи Безсмертну поросль Порожнечі." },
    { en = "Uncontrolled silver-lined arrows fire from Alleria, inflicting $1243981s1 Arcane damage and removing Void effects from players struck. Being hit with an arrow increases damage taken from $@spellname1243981 by $1243981s2% for $1243981d. This effect stacks.", ua = "Аллерія неконтрольовано випускає посріблені стріли, що завдають $1243981s1 арканної шкоди та знімають ефекти Порожнечі з уражених гравців. Влучання стрілою збільшує шкоду, отримувану від $@spellname1243981, на $1243981s2% протягом $1243981d. Цей ефект накопичується." },
    { en = "Ancient obelisks grasp a player with Void energy, inflicting $s1 Shadow damage every $t1 sec and reducing their movement speed by $s2% for $d. Upon removal, $@spellname1232784 fires out through each obelisk.", ua = "Прадавні обеліски хапають гравця енергією Порожнечі, завдаючи $s1 шкоди від тіні кожні $t1 сек і знижуючи його швидкість пересування на $s2% протягом $d. Коли ефект зникає, $@spellname1232784 вистрілює крізь кожен обеліск." },
    { en = "Void magic binds the Voidspawn to existence, preventing it from dying.", ua = "Магія Порожнечі прив'язує пагін Порожнечі до буття, не даючи йому загинути." },
    { en = "Celestial energy bursts around Alleria, inflicting $1237875s1 Shadow damage within $1237875A1 yards of each impact and calling forth a Shattered Voidspawn.", ua = "Навколо Аллерії вибухає небесна енергія, завдаючи $1237875s1 шкоди від тіні в межах $1237875A1 ярдів від кожного влучання та прикликаючи Розколоту поросль Порожнечі." },
    { en = "The droplet erupts with Void upon death and splashes players and Sentinels within $A1 yards. This inflicts $s2 Shadow damage and causes the target to take $s1% increased damage for $d. This effect stacks.", ua = "Краплина при загибелі вибухає Порожнечею й оббризкує гравців і Вартових у межах $A1 ярдів. Це завдає $s2 шкоди від тіні й змушує ціль отримувати на $s1% більше шкоди протягом $d. Цей ефект накопичується." },
    { en = "The Undying Sentinel releases shuddering waves, inflicting $s1 Shadow damage to players within $A1 yards and interrupting spellcasts.", ua = "Невмирущий вартовий вивільняє двигтливі хвилі, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів і перериваючи прочитання заклять." },
    { en = "The Voidspawn blasts random players, inflicting $s1 Shadow damage.", ua = "Поріддя Порожнечі вражає випадкових гравців, завдаючи $s1 шкоди від тіні." },
    { en = "A silver-lined arrow bounces between players, inflicting $s1 Arcane damage and removing Void effects from players and Voidspawn struck.", ua = "Срібляста стріла відскакує між гравцями, завдаючи $s1 арканної шкоди і знімаючи ефекти Порожнечі з уражених гравців та поріддя Порожнечі." },
    { en = "The Undying Sentinel devours the essence of players within $A1 yards, inflicting $s2 Shadow damage and reducing their damage done by $s1% for $d.", ua = "Невмирущий вартовий пожирає есенцію гравців у межах $A1 ярдів, завдаючи $s2 шкоди від тіні та знижуючи завдану ними шкоду на $s1% протягом $d." },
    { en = "The Rift Simulacrum grants Alleria $1237593s2% reduced damage taken and $1237593s1% increased damage done every $t1 sec while she is within $s2 yards of it. This effect stacks.", ua = "Симулякр Розлому дарує Аллерії $1237593s2% зниження отримуваної шкоди та $1237593s1% збільшення завданої шкоди кожні $t1 сек, поки вона перебуває в межах $s2 ярдів від нього. Цей ефект накопичується." },
    { en = "Alleria applies a Ranger Captain's Mark to random players within $s1 yards for $1237623d. Upon expiration, she fires a $@spellname1237729 at them.", ua = "Аллерія накладає Мітку капітана-вартівника на випадкових гравців у межах $s1 ярдів на $1237623d. Коли мітка спливає, вона випускає в них $@spellname1237729." },
    { en = "When no players are within melee range, the Undying Sentinel releases Void energy in a dark wave. This energy inflicts $s1 Shadow damage to all players.", ua = "Коли поблизу немає гравців у радіусі ближнього бою, Невмирущий Вартовий вивільняє енергію Порожнечі темною хвилею. Ця енергія завдає $s1 шкоди від тіні всім гравцям." },
    { en = "Undying Sentinels release Void energy every $1281706t1 sec, inflicting $1281707s1 Shadow damage to all players.\n\n\n\nWhen no players are within melee range, the Undying Sentinel periodically increases its damage done by $s1%. This effect stacks.", ua = "Невмирущі вартові вивільняють енергію Порожнечі кожні $1281706t1 с, завдаючи $1281707s1 шкоди від тіні всім гравцям.\n\n\n\nКоли жоден гравець не перебуває в зоні ближнього бою, невмирущий вартовий періодично збільшує завдану шкоду на $s1%. Цей ефект накопичується." },
    { en = "The Undying Sentinel strikes its current target with a deadly touch, inflicting $s1 Physical and $s1 Shadow damage and knocking the target back.", ua = "Невмирущий вартовий вражає свою поточну ціль смертоносним дотиком, завдаючи $s1 фізичної шкоди та $s1 шкоди від тіні й відкидаючи ціль." },
    { en = "The Rift Simulacrum strikes its current target with a draining touch, inflicting $s1 Physical damage to the player and reducing all of their stats by $1246462s2% for $1246462d. This effect stacks.", ua = "Симулякр Розлому вражає свою поточну ціль виснажливим дотиком, завдаючи $s1 фізичної шкоди гравцю та знижуючи всі його характеристики на $1246462s2% протягом $1246462d. Цей ефект накопичується." },
    { en = "The flames within Belo'ren radiate intense heat, causing him to inflict $1264650s1 Fire damage to all players every $t1 sec.", ua = "Полум'я всередині Бело'рена випромінює нестерпний жар, через що він кожні $t1 сек. завдає $1264650s1 шкоди вогнем усім гравцям." },
    { en = "Bursts on contact with a player, inflicting $1242991s1 Holy damage.", ua = "Вибухає при контакті з гравцем, завдаючи $1242991s1 шкоди від Світла." },
    { en = "Bursts on contact with a player, inflicting $1242996s1 Shadow damage.", ua = "Вибухає при контакті з гравцем, завдаючи $1242996s1 шкоди від тіні." },
    { en = "Belo'ren takes hold of the Light and Void within, erupting for $1241932s1 Twilight damage to all players every $t1 sec for $d and infusing players with a Light or Void feather.", ua = "Бело'рен оволодіває Світлом і Порожнечею всередині себе та вибухає, завдаючи $1241932s1 сутінкової шкоди всім гравцям кожні $t1 с протягом $d і наділяючи гравців пером Світла або Порожнечі." },
    { en = "Belo'ren periodically targets random players with Light or Void infused quills. The quills fire toward their targets after $1242091d, striking the first player in its path.", ua = "Бело'рен періодично обирає цілями випадкових гравців і випускає в них пера, напоєні Світлом або Порожнечею. Пера летять до своїх цілей через $1242091d, вражаючи першого гравця на своєму шляху." },
    { en = "Belo'ren lashes out, inflicting $1241646s1 Holy damage and $1265781s1 Physical damage to players in a cone in front of him and knocking them back.", ua = "Бело'рен завдає удару, спричиняючи $1241646s1 шкоди від Світла та $1265781s1 фізичної шкоди гравцям у конусі перед собою і відкидаючи їх." },
    { en = "Belo'ren lashes out, inflicting $1241676s1 Shadow damage and $1265781s1 Physical damage to players in a cone in front of him and knocking them back.", ua = "Бело'рен завдає удару, спричиняючи $1241676s1 шкоди від тіні та $1265781s1 фізичної шкоди гравцям у конусі перед собою і відкидаючи їх." },
    { en = "Belo'ren casts $@spellname1261217 and $@spellname1261218 simultaneously.", ua = "Бело'рен творить $@spellname1261217 і $@spellname1261218 одночасно." },
    { en = "Belo'ren periodically engulfs the arena in flames of Light and Void that erupt after $t1 sec to inflict Holy or Shadow damage to players within them.", ua = "Бело'рен періодично заливає арену полум'ям Світла і Порожнечі, що спалахує за $t1 сек, завдаючи шкоди від Світла або від тіні гравцям усередині нього." },
    { en = "Inflicts $1242803s1 Holy damage.\n\n\n\nPlayers infused with opposing element also take $1242803o2 Holy damage over $1242803d. This effect stacks.", ua = "Завдає $1242803s1 шкоди від Світла.\n\n\n\nГравці, насичені протилежним елементом, також зазнають $1242803o2 шкоди від Світла протягом $1242803d. Цей ефект накопичується." },
    { en = "When an ember's health is depleted, they retreat into an ashen egg. If the egg is not killed within $s1 sec a new ember hatches from the egg, inflicting $s5 Fire damage to all players.", ua = "Коли здоров'я жарини вичерпується, вона ховається в попелясте яйце. Якщо яйце не знищити протягом $s1 сек., з нього вилуплюється нова жарина, завдаючи $s5 шкоди вогнем усім гравцям." },
    { en = "Eternal flames fuel Belo'ren's energy, allowing him to use Rebirth when his health is fully depleted.", ua = "Вічне полум'я живить енергію Бело'рена, дозволяючи йому застосувати Відродження, коли його здоров'я повністю вичерпане." },
    { en = "The ember blasts a random player, inflicting $s1 Holy damage.", ua = "Жарина б'є по випадковому гравцеві, завдаючи $s1 шкоди від Світла." },
    { en = "The ember blasts a random player, inflicting $s1 Shadow damage.", ua = "Жарина вражає випадкового гравця, завдаючи $s1 шкоди від тіні." },
    { en = "Belo'ren burns players with searing Light and consuming Void, absorbing healing and periodically inflicting damage to the target until the burn is healed.", ua = "Бело'рен обпікає гравців пекучим Світлом і пожираючою Порожнечею, поглинаючи зцілення та періодично завдаючи шкоди цілі, доки опік не буде зцілений." },
    { en = "Absorbs $s1 healing and inflicts $s2 Holy damage every $t2 sec until the burn is fully healed.", ua = "Поглинає $s1 зцілення та завдає $s2 шкоди від Світла щосекунди $t2, доки опік не буде повністю зцілений." },
    { en = "Inflicts $1242815s1 Shadow damage.\n\n\n\nPlayers infused with the opposing element also take $1242815o2 Shadow damage over $1242815d. This effect stacks.", ua = "Завдає $1242815s1 шкоди від тіні.\n\n\n\nГравці, насичені протилежним елементом, також зазнають $1242815o2 шкоди від тіні протягом $1242815d. Цей ефект накопичується." },
    { en = "Belo'ren summons Light or Void Embers that attack players.", ua = "Бело'рен призиває Жарини Світла або Порожнечі, що атакують гравців." },
    { en = "Infused with a luminous feather, reducing Holy damage taken by $s1%.", ua = "Напоєний осяйним пером, що знижує отримувану шкоду від Світла на $s1%." },
    { en = "Infused with a darkened feather, reducing Shadow damage taken by $s1%.", ua = "Напоєний потемнілим пером, що знижує отримувану шкоду від тіні на $s1%." },
    { en = "The ember focuses on a player for $d, then dives into them inflicting $1241291s1 Holy damage split evenly among players within $1241291a1 yards, knocking them away and leaving behind a $@spellname1241838.", ua = "Жарина зосереджується на гравцеві на $d, тоді кидається на нього, завдаючи $1241291s1 шкоди від Світла, розподіленої порівну між гравцями в радіусі $1241291a1 м, відкидає їх і лишає по собі $@spellname1241838." },
    { en = "The ember unleashes the radiant light within, inflicting $s1 Holy damage to all players.\n\n\n\nThis spell can only be interrupted by players infused with a $@spellname1243559.", ua = "Жарина вивільняє променисте світло всередині, завдаючи $s1 шкоди від Світла всім гравцям.\n\n\n\nЦе закляття можуть перервати лише гравці, насичені $@spellname1243559." },
    { en = "The ember unleashes the devouring void within, inflicting $s1 Shadow damage to all players.\n\n\n\nThis spell can only be interrupted by players infused with a $@spellname1243560.", ua = "Жарина вивільняє пожираючу Порожнечу всередині, завдаючи $s1 шкоди від тіні всім гравцям.\n\n\n\nЦе закляття можуть перервати лише гравці, насичені $@spellname1243560." },
    { en = "Echoes react violently on contact with players infused with the opposing element, inflicting $s1 Twilight damage instantly and $o2 Twilight damage over $d.", ua = "Відлуння бурхливо реагують на контакт із гравцями, насиченими протилежною стихією, завдаючи $s1 шкоди від сутінків миттєво і $o2 шкоди від сутінків протягом $d." },
    { en = "Belo'ren performs a devastating combination of Light and Void attacks.\n\n\n\nFailing to attack a player or attacking a player that is infused with an opposing element empowers Belo'ren, increasing all damage done by $1260826s1% for $1260826d. This effect stacks.", ua = "Бело'рен виконує спустошливу комбінацію атак Світла й Порожнечі.\n\n\n\nЯкщо він не влучить у гравця або влучить у гравця, насиченого протилежною стихією, Бело'рен підсилюється, збільшуючи всю завдану шкоду на $1260826s1% протягом $1260826d. Цей ефект накопичується." },
    { en = "Belo'ren's ashen egg burns brightly, increasing the frequency of damage from $@spellname1283067 by $1283067s2%.\n\n\n\nDamaging Belo'ren in this state diminishes his $@spellname1243320, and depleting his energy prevents his rebirth entirely.\n\n\n\nAfter $s1 sec, Belo'ren's rebirth is complete and he returns to battle players at full health.", ua = "Попелясте яйце Бело'рена палає яскраво, збільшуючи частоту шкоди від $@spellname1283067 на $1283067s2%.\n\n\n\nЗавдаючи Бело'рену шкоди в цьому стані, ви виснажуєте його $@spellname1243320, а повне вичерпання його енергії остаточно унеможливлює його відродження.\n\n\n\nЧерез $s1 с відродження Бело'рена завершується, і він повертається в бій із повним здоров'ям." },
    { en = "Absorbs $s1 healing and inflicts $s2 Shadow damage every $t2 sec until the burn is fully healed.", ua = "Поглинає $s1 зцілення і завдає $s2 шкоди від тіні кожні $t2 с, доки опік повністю не загоїться." },
    { en = "Belo'ren conjures echoes of concentrated Light and Void that drift across the arena for $s1 sec.", ua = "Бело'рен прикликає відлуння зосередженого Світла й Порожнечі, що дрейфують ареною протягом $s1 с." },
    { en = "Inflicts $s1 Holy damage.", ua = "Завдає $s1 священної шкоди." },
    { en = "Lingering light energy inflicts $1241840s1 Holy damage to players within every $1241840t1 sec and increases Holy damage they take by $1241840s2%.", ua = "Залишкова енергія світла завдає $1241840s1 шкоди від Світла гравцям у зоні дії кожні $1241840t1 с і збільшує шкоду від Світла, якої вони зазнають, на $1241840s2%." },
    { en = "Inflicts $s1 Shadow damage.", ua = "Завдає $s1 шкоди від тіні." },
    { en = "Belo'ren's rebirth inflicts $s1 Fire damage to all players and reduces their healing done by $s2%. This effect stacks.", ua = "Відродження Бело'рена завдає $s1 шкоди вогнем усім гравцям і знижує зцілення, яке вони чинять, на $s2%. Цей ефект накопичується." },
    { en = "Lingering void energy inflicts $1241841s1 Shadow damage to players within every $1241841t1 sec and increases Shadow damage they take by $1241841s2%.", ua = "Залишкова енергія Порожнечі завдає $1241841s1 шкоди від тіні гравцям у зоні дії кожні $1241841t1 с і збільшує шкоду від тіні, якої вони зазнають, на $1241841s2%." },
    { en = "When Belo'ren's health is depleted, he soars sky-high and slams into the center of the arena inflicting $1241333s1 Physical damage to all players and knocking them upward. Players farther from the impact location receive less damage and are not knocked up as high.", ua = "Коли здоров'я Бело'рена вичерпується, він злітає високо в небо й врізається в центр арени, завдаючи $1241333s1 фізичної шкоди всім гравцям і підкидаючи їх угору. Гравці, дальші від місця удару, отримують менше шкоди й підлітають не так високо." },
    { en = "The ember focuses on a player for $d, then dives into them inflicting $1241340s1 Shadow damage split evenly among players within $1241340a1 yards, knocking them away and leaving behind a $@spellname1241845.", ua = "Жарина зосереджується на гравцеві на $d, тоді кидається на нього, завдаючи $1241340s1 шкоди від тіні, розподіленої порівну між гравцями в радіусі $1241340a1 м, відкидає їх і лишає по собі $@spellname1241845." },
    { en = "L'ura showers the chamber in infinite darkness, inflicting $1249797s1 Shadow damage to all players every $t1 sec for $d.", ua = "Л'ура заливає палату нескінченною темрявою, завдаючи $1249797s1 шкоди від тіні всім гравцям кожні $t1 с протягом $d." },
    { en = "L'ura coalesces glass spikes that descend upon random players, inflicting $1281473s1 Cosmic damage.\n\n\n\nFractured shards erupt outward from each target, inflicting $1279581s1 Cosmic damage to any players hit.", ua = "Л'ура збирає докупи скляні шипи, що падають на випадкових гравців, завдаючи $1281473s1 космічної шкоди.\n\n\n\nВід кожної цілі назовні вибухають розколоті скалки, завдаючи $1279581s1 космічної шкоди всім зачепленим гравцям." },
    { en = "The aftershocks trigger a wave of void to cascade from the Darkwell, inflicting $1263255s1 Cosmic damage and an additional $1285719s1 Cosmic damage every $1254635t1 sec to players caught within.", ua = "Поштовхи спричиняють хвилю порожнечі, що каскадом ллється з Темного Колодязя, завдаючи $1263255s1 космічної шкоди та додатково $1285719s1 космічної шкоди щосекунди $1254635t1 гравцям, що опинилися всередині." },
    { en = "If either dimension is devoid of players, L'ura inflicts increasing Cosmic damage to all players every $1275057t3 sec.", ua = "Якщо в одному з вимірів немає гравців, Л'ура кожні $1275057t3 с завдає всім гравцям дедалі більшої космічної шкоди." },
    { en = "While not held by a player, the $@spellname1266628 surges with overwhelming light, inflicting increasing Holy damage to all players every $s2 sec.", ua = "Поки $@spellname1266628 не тримає гравець, він пульсує приголомшливим світлом, завдаючи дедалі більшої священної шкоди всім гравцям кожні $s2 сек." },
    { en = "L'ura spins and unleashes whirling blades that eviscerate players on contact, inflicting up to ${$1254076s1*5} Cosmic damage. \n\n\n\nThe blades ricochet through the chamber, inflicting reduced damage as they lose speed.", ua = "Л'ура обертається й вивільняє вихор лез, що шматують гравців при дотику, завдаючи до ${$1254076s1*5} космічної шкоди. \n\n\n\nЛеза рикошетять палатою, завдаючи дедалі меншої шкоди, втрачаючи швидкість." },
    { en = "Remaining $@spellname1282246 overheat and detonate, regenerating L'ura's energy. \n\n\n\nEach blast inflicts $1284531s1 Cosmic damage to all players and an additional $1284531s2 Cosmic damage every $1284531t2 sec for $1284531d. This effect stacks.", ua = "Решта $@spellname1282246 перегріваються й детонують, відновлюючи енергію Л'ури. \n\n\n\nКожен вибух завдає $1284531s1 космічної шкоди всім гравцям, а також додатково $1284531s2 космічної шкоди кожні $1284531t2 сек протягом $1284531d. Цей ефект накопичується." },
    { en = "L'ura's beings remain bonded across realities, inflicting $s1% of their damage taken to each other.", ua = "Істоти Л'ури лишаються пов'язаними крізь реальності, завдаючи одна одній $s1% отриманої ними шкоди." },
    { en = "A chain reaction inflicts $1281178s2 Cosmic damage within $1281178A2 yards of all players.", ua = "Ланцюгова реакція завдає $1281178s2 космічної шкоди в межах $1281178A2 ярдів від усіх гравців." },
    { en = "Upon reaching 100 energy, L'ura activates the Darkwell's full potential, expelling all players with an astronomic blast inflicting $1281123s1 Cosmic damage.", ua = "Сягнувши 100 енергії, Л'ура задіює повний потенціал Темного Колодязя, відкидаючи всіх гравців астрономічним вибухом, що завдає $1281123s1 космічної шкоди." },
    { en = "L'ura fires electric beams at random players, each inflicting $1284530s1 Cosmic damage to all players hit.\n\n\n\nImpact with a $@spellname1282247 triggers $@spellname1282249.", ua = "Л'ура випускає електричні промені у випадкових гравців, кожен з яких завдає $1284530s1 космічної шкоди всім ураженим гравцям.\n\n\n\nЗіткнення з $@spellname1282247 запускає $@spellname1282249." },
    { en = "A $@spellname1249609 hit in the correct order creates a transcendant toll, inflicting $s2 Cosmic damage to players within $A2 yards.", ua = "$@spellname1249609, уражена в правильному порядку, породжує потойбічний дзвін, завдаючи $s2 космічної шкоди гравцям у межах $A2 ярдів." },
    { en = "A $@spellname1249609 hit out of order creates an echoing clamor, inflicting $1249585s2 Cosmic damage to all players every $t1 sec for $d.", ua = "$@spellname1249609, уражена в неправильному порядку, породжує відлунний гомін, завдаючи $1249585s2 космічної шкоди всім гравцям кожні $t1 с протягом $d." },
    { en = "Glass spikes embed deep into flesh, inflicting $1253879s1 Cosmic damage every $t1 sec and increasing damage taken from $@spellname1263970 by $s2% for $d. This effect stacks.", ua = "Скляні шипи глибоко вгрузають у плоть, завдаючи $1253879s1 космічної шкоди кожні $t1 с і збільшуючи отриману шкоду від $@spellname1263970 на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Dark shadows encircle the chamber, pushing players towards the center.", ua = "Темні тіні оточують палату, відштовхуючи гравців до центру." },
    { en = "$@spellname1282027 releases jets of excess void energy, inflicting $1282469s1 Cosmic damage every $1282470t1 sec to players within them.", ua = "$@spellname1282027 вивільняє струмені надлишкової енергії Порожнечі, завдаючи $1282469s1 косимічної шкоди кожні $1282470t1 сек. гравцям усередині них." },
    { en = "L'ura synthesizes a revolving bulwark of Safeguard Matrices, each reducing her damage taken by 33% for up to $d.", ua = "Л'ура синтезує обертовий оплот із Захисних матриць, кожна з яких знижує отримувану нею шкоду на 33% протягом аж до $d." },
    { en = "True darkness suffocates any player forsaken within, reducing movement speed by $1266623s2% and inflicting $1263514s1 Shadow damage every $1263514t1 sec. This effect stacks.", ua = "Справжня темрява душить будь-якого гравця, що покинутий усередині неї, знижуючи швидкість пересування на $1266623s2% і завдаючи $1263514s1 шкоди Тінню кожні $1263514t1 с. Цей ефект накопичується." },
    { en = "The Matrix attempts to fortify itself, gaining an application of $@spellname1251392 upon completion. \n\n\n\nInterrupting this ability removes an application of $@spellname1251392. Removing all applications destroys the Matrix.", ua = "Матриця намагається зміцнитися, отримуючи один заряд $@spellname1251392 після завершення. \n\n\n\nПереривання цієї здібності знімає один заряд $@spellname1251392. Зняття всіх зарядів знищує Матрицю." },
    { en = "L'ura's Prism disintegrates, inflicting $s1 Cosmic damage to all players as crystals splinter from her.", ua = "Призма Л'ури розпадається, завдаючи $s1 космічної шкоди всім гравцям, коли від неї відколюються кристали." },
    { en = "Any player holding a $@spellname1266628 becomes a beacon of hope for their allies, protecting players within $s1 yards from the darkness of $@spellname1266622.", ua = "Будь-який гравець, що тримає $@spellname1266628, стає світочем надії для своїх союзників, захищаючи гравців у межах $s1 ярдів від темряви $@spellname1266622." },
    { en = "L'ura synthesizes a revolving assault of Termination Matrices, each increasing her damage done by 33% for up to $d.", ua = "Л'ура синтезує почерговий шквал Матриць знищення, кожна з яких збільшує завдану нею шкоду на 33% протягом щонайбільше $d." },
    { en = "Excess power arcs between all players, inflicting up to $s1 Cosmic damage. \n\n\n\nEach player within the effect of $@spellname1284525 diffuses its overflow, reducing this damage.", ua = "Надлишок енергії стрибає дугами між усіма гравцями, завдаючи до $s1 космічної шкоди. \n\n\n\nКожен гравець у зоні дії $@spellname1284525 розсіює надлишок, зменшуючи цю шкоду." },
    { en = "The $@spellname1282247 brims with power, inflicting $1282375s1 Cosmic damage to players on contact.", ua = "$@spellname1282247 повниться силою, завдаючи $1282375s1 косимічної шкоди гравцям при дотику." },
    { en = "The Matrix attempts to execute hostiles, inflicting $1286276s1 Cosmic damage to all players in front of it upon completion. \n\n\n\nInterrupting this ability removes an application of $@spellname1284932. Removing all applications destroys the Matrix.", ua = "Матриця намагається стратити ворогів, завдаючи $1286276s1 космічної шкоди всім гравцям перед собою після завершення. \n\n\n\nПереривання цієї здібності знімає один заряд $@spellname1284932. Зняття всіх зарядів знищує Матрицю." },
    { en = "Singularities within the Darkwell capable of containing infinite void energy.", ua = "Сингулярності в Темному Колодязі, здатні вмістити нескінченну енергію Порожнечі." },
    { en = "L'ura sings a dreadful melody before marking players with a $@spellname1249609 corresponding to each note. Collision between marked players activates each $@spellname1249609 .", ua = "Л'ура співає моторошну мелодію, а тоді позначає гравців ефектом $@spellname1249609 відповідно до кожної ноти. Зіткнення позначених гравців активує кожен $@spellname1249609 ." },
    { en = "Marked with a musical note, inflicting $1249594s1 Cosmic damage every $t1 sec. \n\n\n\nUpon activation, triggers either $@spellname1249582 or $@spellname1249584.", ua = "Позначено музичною нотою, що завдає $1249594s1 космічної шкоди кожні $t1 с. \n\n\n\nПісля активації спричиняє або $@spellname1249582, або $@spellname1249584." },
    { en = "The $@spellname1282247 opens, pulling all players towards it and inflicting $1282372s1 Cosmic damage every $t1 sec for $d as their atoms are ripped away and consumed to create a $@spellname1282373.", ua = "$@spellname1282247 розкривається, притягуючи всіх гравців до себе й завдаючи $1282372s1 космічної шкоди кожні $t1 сек протягом $d, тоді як їхні атоми відриваються й поглинаються, щоб створити $@spellname1282373." },
    { en = "The crystal shatters into shrapnel, inflicting $s1 Cosmic damage to all players and an additional $s2 Cosmic damage every $t2 sec for $d.", ua = "Кристал розлітається на осколки, завдаючи $s1 космічної шкоди всім гравцям і додатково $s2 космічної шкоди кожні $t2 сек. протягом $d." },
    { en = "L'ura invokes voracious rifts that hunger for light, inflicting $1266810s1 Cosmic damage to players within $1266808s2 yards every ${$1266808s1/10}.1 for up to $1266808d.\n\n\n\nRifts that expire before they are satiated detonate in a $@spellname1266898.", ua = "Л'ура викликає ненажерливі Розломи, що жадають світла, завдаючи $1266810s1 космічної шкоди гравцям у радіусі $1266808s2 м кожні ${$1266808s1/10}.1 на час до $1266808d.\n\n\n\nРозломи, що зникають, не наситившись, детонують у $@spellname1266898." },
    { en = "L'ura transfigures into an unholy weapon of godlike destruction, firing a cataclysmic blast that inflicts $1251080s1 Cosmic damage to all players.", ua = "Л'ура обертається на нечестиву зброю божественної руйнації й випускає катаклізмічний вибух, що завдає $1251080s1 космічної шкоди всім гравцям." },
    { en = "Space-time collapses, inflicting $1266903s1 Cosmic damage to all players.", ua = "Простір-час колапсує, завдаючи $1266903s1 космічної шкоди всім гравцям." },
    { en = "L'ura calls down dark stars, inflicting $1266584s1 Cosmic damage within $1266584A1 yards of each impact. \n\n\n\nThe stars interconnect, inflicting $1266586s1 Cosmic damage to players within the patterns.", ua = "Л'ура накликає темні зорі, завдаючи $1266584s1 космічної шкоди в радіусі $1266584A1 м від кожного влучання.\n\n\n\nЗорі сполучаються між собою, завдаючи $1266586s1 космічної шкоди гравцям усередині візерунків." },
    { en = "A $@spellname1249609 hit out of order creates an echoing clamor, silencing the target for $d.", ua = "Влучання «$@spellname1249609» у неправильному порядку створює лункий гамір, що занімовує ціль на $d." },
    { en = "All players are bathed in the Darkwell's nebulous liquid, inflicting $1282004s1 Cosmic damage every $1282006t1 sec.", ua = "Усіх гравців омиває туманна рідина Темного Колодязя, завдаючи $1282004s1 космічної шкоди кожні $1282006t1 сек." },
    { en = "L'ura transcends, diverging both players and her own being across two alternate dimensions. The violent division inflicts $1276173s1 Cosmic damage to all players.", ua = "Л'ура долає межі буття, розводячи і гравців, і власну сутність по двох паралельних вимірах. Цей жорстокий розкол завдає $1276173s1 космічної шкоди всім гравцям." },
    { en = "The destruction of a $@spellname1266628 induces utter despair, inflicting $s1 Holy damage to all players and increasing all damage taken by $s2% for $d.", ua = "Знищення $@spellname1266628 викликає цілковитий відчай, завдаючи $s1 шкоди від Світла всім гравцям і збільшуючи всю отримувану шкоду на $s2% протягом $d." },
    { en = "L'ura regenerates a halo of glass ornaments over time. Upon reaching $s1 applications, she forges the glass into spikes that fire into her current target.\n\n\n\nEach impact inflicts $1253878s1 Cosmic damage and applies $@spellname1265842.", ua = "З часом Л'ура відрощує ореол скляних оздоб. Сягнувши $s1 застосувань, вона кує зі скла шипи, що летять у її поточну ціль.\n\n\n\nКожне влучання завдає $1253878s1 космічної шкоди й накладає $@spellname1265842." },
    { en = "L'ura transfigures into a conduit within the Darkwell, regenerating her energy and applying $@spellname1262055 to all players every $1255743t1 sec for $1255743d.", ua = "Л'ура перетворюється на провідник усередині Темного Колодязя, відновлюючи свою енергію і накладаючи $@spellname1262055 на всіх гравців кожні $1255743t1 с протягом $1255743d." },
    { en = "Enveloped in refracting shadows, absorbing the next $s1 healing received.", ua = "Огорнутий заломлюваними тінями, що поглинають наступні $s1 отриманого зцілення." },
    { en = "The surrounding iris of pure void atomizes any players attempting to escape.", ua = "Навколишня райдужка чистої Порожнечі розпорошує будь-якого гравця, який намагається втекти." },
    { en = "The Darkwell's colossal void beam instantly vaporizes any player that dares to enter.", ua = "Колосальний промінь Порожнечі Темного Колодязя миттєво випаровує будь-якого гравця, який наважиться увійти." },
    { en = "L'ura pulls each $@spellname1282269 into herself for absorption, inflicting $1282425s1 Cosmic damage to all players and regenerating her energy.", ua = "Л'ура притягує до себе кожен $@spellname1282269 для поглинання, завдаючи $1282425s1 космічної шкоди всім гравцям і відновлюючи свою енергію." },
    { en = "The $@spellname1251653 fades, inflicting increasing Shadow damage to it every $t1 sec and undergoing $@spellname1251789 upon death.\n\n\n\nUpon reaching full health, it instead transforms into a $@spellname1266628.", ua = "$@spellname1251653 згасає, зазнаючи дедалі більшої шкоди від тіні кожні $t1 сек і після загибелі зазнаючи $@spellname1251789.\n\n\n\nА сягнувши повного здоров'я, він натомість перетворюється на $@spellname1266628." },
    { en = "L'ura weeps alone, inflicting $s1 Holy damage to all players.", ua = "Л'ура плаче на самоті, завдаючи $s1 шкоди від Світла всім гравцям." },
    { en = "Collision between players in opposite realities causes a dimensional rupture, ending their existence.", ua = "Зіткнення гравців із протилежних реальностей спричиняє вимірний розрив, що обриває їхнє існування." },
    { en = "L'ura exerts her cosmic grip upon all players, pulling them into the heart of the Darkwell.", ua = "Л'ура стискає всіх гравців своїм космічним захватом, втягуючи їх у серце Темного Колодязя." },
    { en = "The Darkwell rages with overflowing void, inflicting $1254644s1 Cosmic damage to all players every $t1 sec.", ua = "Темний Колодязь вирує переповненою Порожнечею, завдаючи $1254644s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "It's time to face the music.", ua = "Час зустріти музику лицем до лиця." },
    { en = "The $@spellname1266628 scintillates with holy light during dire moments, briefly allowing its holder to cast $@spellname1253104.\n\n\n\nThe crystal tessellates into a brilliant dome, reducing damage taken by players within by $1253770s1% for up to $1253771d. This consumes the $@spellname1266628.", ua = "$@spellname1266628 у грізні миті спалахує святим світлом, на коротку мить дозволяючи власникові сотворити $@spellname1253104.\n\n\n\nКристал складається в осяйний купол, зменшуючи шкоду, що отримують гравці всередині, на $1253770s1% протягом до $1253771d. Це поглинає $@spellname1266628." },
    { en = "When hit directly by Cosmic damage, the $@spellname1266628 sheds tears of anguish inflicting $1254257s1 Holy damage to players within $1254257A1 yards upon impact.\n\n\n\nTears that fail to hit at least one player elicit $@spellname1254256.", ua = "Зазнавши прямого влучання космічної шкоди, $@spellname1266628 проливає сльози муки, завдаючи $1254257s1 шкоди від Світла гравцям у межах $1254257A1 м при влучанні.\n\n\n\nСльози, що не влучають хоча б в одного гравця, спричиняють $@spellname1254256." },
    { en = "L'ura sings a dreadful melody before marking players with a $@spellname1249609 corresponding to each note. She then fires a sweeping laser, activating each $@spellname1249609 hit.", ua = "Л'ура співає моторошну мелодію, а тоді позначає гравців ефектом $@spellname1249609 відповідно до кожної ноти. Після цього вона випускає лазер, що описує дугу, активуючи кожен влучений $@spellname1249609." },
    { en = "The $@spellname1266628 shimmers, inflicting $1254398s1 Holy damage every $1253031t1 sec to the player holding it.", ua = "$@spellname1266628 мерехтить, завдаючи $1254398s1 шкоди Світлом кожні $1253031t1 с гравцеві, що його тримає." },
    { en = "A rotting wound that inflicts $1222284s1 Nature damage to all players every $t1 sec. This effect stacks.", ua = "Гнила рана, що завдає $1222284s1 шкоди від сил природи всім гравцям щосекунди $t1. Цей ефект накопичується." },
    { en = "Rotmire unleashes a putrid miasma, inflicting $s1 Nature damage to all players, with an additional $s2 Nature damage every $t2 sec for $d, and knocking them away.\n\n\n\nThe spores empower fungal minions, applying $@spellname1221644 and healing them for $1221644s1% of their maximum health. Creates a $@spellname1221965 at each fungal corpse.", ua = "Ротмайр вивільняє смердюче марево, завдаючи $s1 шкоди від сил природи всім гравцям, з додатковими $s2 шкоди від сил природи кожні $t2 с протягом $d, і відкидаючи їх.\n\n\n\nСпори підсилюють грибних посіпак, накладаючи $@spellname1221644 й зціляючи їх на $1221644s1% їхнього максимального здоров'я. Створює $@spellname1221965 на кожному грибному трупі." },
    { en = "Rotmire wraps several players in thorny vines, inflicting $s3 Nature damage every $t3 sec and decreasing their movement speed by $s2%.\n\n\n\nUpon expiration, the vines snap apart, inflicting $1222122s1 Nature damage to players within $1222122a1 yards and leaving behind $@spellname1222129.", ua = "Ротмайр обплітає кількох гравців колючими лозами, завдаючи $s3 шкоди від сил природи кожні $t3 сек. і знижуючи їхню швидкість пересування на $s2%.\n\n\n\nКоли ефект спадає, лози розриваються, завдаючи $1222122s1 шкоди від сил природи гравцям у межах $1222122a1 ярдів і лишаючи по собі $@spellname1222129." },
    { en = "Putrid spores enrage the fungal minion, increasing its damage by $s2% and movement speed by $s3%, and granting it immunity to crowd control effects and interrupts.", ua = "Гнилісні спори впадають грибного посіпаку в лють, підвищуючи його шкоду на $s2% і швидкість пересування на $s3%, а також надаючи йому несприйнятливість до ефектів контролю й переривань." },
    { en = "The shroom explodes, inflicting $s1 Nature damage to all players.", ua = "Гриб вибухає, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Writhing vines inflict $s1 Nature damage every $t1 sec to players within the area.", ua = "Звивисті лози завдають $s1 шкоди від сил природи кожні $t1 сек. гравцям у межах ділянки." },
    { en = "The Sporecap emits a burst of poisonous spores, inflicting $s1 Nature damage to all players and an additional $s2 Nature damage every $t2 sec for $d. This effect stacks.", ua = "Спорокап вивергає хмару отруйних спор, завдаючи $s1 шкоди від сил природи всім гравцям і додатково $s2 шкоди від сил природи кожні $t2 сек протягом $d. Цей ефект накопичується." },
    { en = "The Sporecap shoots a glob of poison at a player, inflicting $s1 Nature damage.", ua = "Спорокап випускає в гравця згусток отрути, завдаючи $s1 шкоди від сил природи." },
    { en = "Rotmire blooms with fungal growths that rapidly explode, inflicting $1221901s1 Nature damage to players within $1221901a1 yards of their locations and knocking them away. \n\n\n\nCreates a fungal minion.", ua = "Ротмайр розквітає грибковими наростами, що швидко вибухають, завдаючи $1221901s1 шкоди від сил природи гравцям у межах $1221901a1 ярдів від місця вибуху та відкидаючи їх. \n\n\n\nСтворює грибкового прислужника." },
    { en = "Rotmire smashes its current target with a rotting fist, inflicting $s1 Physical damage and knocking the player upwards. Increases Physical damage taken by $1222289s1% for $1222289d. This effect stacks.", ua = "Ротмайр б'є свою поточну ціль гнилим кулаком, завдаючи $s1 фізичної шкоди та підкидаючи гравця вгору. Підвищує отримувану фізичну шкоду на $1222289s1% протягом $1222289d. Цей ефект накопичується." },
    { en = "Rotmire bursts several bulging pustules on its back, inflicting $1222278s1 Nature damage to all players and gaining an application of $@spellname1222176 for each burst.", ua = "Ротмайр розриває кілька набряклих пухирів на своїй спині, завдаючи $1222278s1 шкоди від сил природи всім гравцям і отримуючи накладання $@spellname1222176 за кожен розрив." },
    { en = "On Mythic difficulty, a Doom Shroom is created if a Shroomling corpse comes within $1221637s5 yards of a Fungling corpse.", ua = "На міфічній складності Гриб Погибелі утворюється, якщо труп Грибеняти опиняється в межах $1221637s5 м від трупа Фунґлінга." },
    { en = "The shroom explodes, inflicting $s1 Nature damage to all players and an additional $s2 Nature damage every $t2 sec for $d.", ua = "Гриб вибухає, завдаючи $s1 шкоди від сил природи всім гравцям і додаткові $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "A purified Naaru fragment that can be carried.", ua = "Очищений фрагмент наару, який можна носити із собою." },
    { en = "Belo'ren infuses all players with Holy or Void feathers, granting them absorption against that school of magic.", ua = "Бело'рен насичує всіх гравців перами Світла або Порожнечі, даючи їм поглинання проти відповідної школи магії." },
    { en = "A dimming Naaru fragment.", ua = "Згасальний уламок наару." },
    { en = "The caster burrows and then bursts from the ground, inflicting $s1 Nature damage to players within $A1 yards of the impact and knocking them back.", ua = "Той, хто творить закляття, заривається під землю, а тоді вибухово виринає з неї, завдаючи $s1 шкоди природою гравцям у радіусі $A1 ярдів від місця удару й відкидаючи їх." },
    { en = "Allows nearby players to cross over into Untethered Space.", ua = "Дозволяє гравцям поблизу переходити у Невіддалений Простір." },
    { en = "Reshanor unleashes a shattering roar interrupting all enemies and inflicting Physical damage every $1238078t1 sec for $1238078d. The echo causes all |cFF2959D3|Hspell:1226441|h[Null Ruptures]|h|r to expand.", ua = "Решанор вивільняє руйнівний рев, що перериває всіх ворогів і завдає фізичної шкоди кожні $1238078t1 с протягом $1238078d. Відлуння змушує всі |cFF2959D3|Hspell:1226441|h[Нульові Розриви]|h|r розширюватися." },
    { en = "Upon reaching 0 energy, Reshanor shifts into Untethered Space to feed on arcane energies, obscuring vision for enemies in Reality and increasing all critical damage taken in Untethered Space by $s2% for $d.\n\n\n\nReshanor's shift causes void creatures to spill out into Reality.", ua = "Сягнувши 0 енергії, Решанор переходить у Незв'язаний Простір, щоб живитися арканними енергіями, затьмарюючи зір ворогам у Реальності та збільшуючи всю отримувану критичну шкоду в Незв'язаному Просторі на $s2% на $d.\n\n\n\nПерехід Решанора змушує істот Порожнечі вихлюпуватися в Реальність." },
    { en = "Slams the ground creating a small void rift, inflicting Shadow damage to all enemies within $A1 yards of the impact and pulling them in for $d.", ua = "Гатить по землі, утворюючи невеликий розлом Порожнечі, що завдає шкоди від тіні всім ворогам у радіусі $A1 м від удару й затягує їх усередину протягом $d." },
    { en = "Masses of rock crater into the ground inflicting $s1 Physical damage to players within $a1 yards of the impact.\n\n\n\nVoid rifts persist for $d and pull in players within range, applying |cFF2959D3|Hspell:1237906|h[Void Corruption]|h|r every $1227209t1 sec.", ua = "Брили каменю врізаються в землю, завдаючи $s1 фізичної шкоди гравцям у радіусі $a1 м від удару.\n\n\n\nРозломи Порожнечі тривають $d і затягують гравців у межах досяжності, накладаючи |cFF2959D3|Hspell:1237906|h[Порчу Порожнечі]|h|r кожні $1227209t1 с." },
    { en = "Reshanor's presence manifests a voidstorm, causing |cFF2959D3|Hspell:1226441|h[Null Ruptures]|h|r and |cFF2959D3|Hspell:1226389|h[Errant Zaps]|h|r to hit the ground periodically.", ua = "Присутність Решанора проявляє войдшторм, через що |cFF2959D3|Hspell:1226441|h[Нульові Розриви]|h|r та |cFF2959D3|Hspell:1226389|h[Блукливі Розряди]|h|r періодично б'ють по землі." },
    { en = "Slices at an enemy, inflicting Shadow damage and additional Shadow damage every $t2 sec for $d.", ua = "Розсікає ворога, завдаючи тіньової шкоди та додаткової тіньової шкоди кожні $t2 сек. протягом $d." },
    { en = "Spits a glob of poison, inflicting Nature damage, then additional Nature damage every $t2 sec for $d. This effect stacks.", ua = "Випльовує згусток отрути, завдаючи шкоди від сил природи, а потім додаткової шкоди від сил природи кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Exhales a powerful breath full of Void energy, applying |cFF2959D3|Hspell:1237906|h[Void Corruption]|h|r every $t2 sec to all enemies in a cone in front of the caster for $d.", ua = "Видихає потужний подих, сповнений енергії Порожнечі, накладаючи |cFF2959D3|Hspell:1237906|h[Порчу Порожнечі]|h|r кожні $t2 с на всіх ворогів у конусі перед закляттярем протягом $d." },
    { en = "Reshanor corrupts enemies hit by any of his abilities, inflicting $1239052s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Решанор псує ворогів, яких зачепила будь-яка з його здібностей, завдаючи $1239052s1 шкоди від тіні кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Calls into the void to summon allies that assist in combat.", ua = "Кличе в Порожнечу, щоб прикликати союзників, які допомагають у бою." },
    { en = "Chaotic energies surge into the ground, inflicting $s1 Arcane damage to players within $a1 yards of the impact and stunning them for $d.", ua = "Хаотичні енергії ринуть у землю, завдаючи $s1 арканної шкоди гравцям у радіусі $a1 м від удару й оглушуючи їх на $d." },
    { en = "Kordac fires lasers which track several players for $458220d, inflicting $458220s1 Arcane damage every $458700t1 sec and knocking back players singed by the beams.\n\n\n\nThe lasers leave $@spellname458799 and $@spellname459281 in their wake.", ua = "Кордак випускає лазери, що переслідують кількох гравців протягом $458220d, завдаючи $458220s1 арканної шкоди кожні $458700t1 с і відкидаючи гравців, обпечених променями.\n\n\n\nЛазери лишають по собі $@spellname458799 та $@spellname459281." },
    { en = "Destructive power lingers in the ground, burning those that touch it for $s1 Arcane damage every $t1 sec.", ua = "Руйнівна сила лишається в землі, обпікаючи тих, хто її торкається, на $s1 арканної шкоди кожні $t1 с." },
    { en = "Kordac smashes the ground in front of himself with Arcane infused fists, inflicting $458327s1 Physical and $458319s1 Arcane damage. Players caught in the impact are launched into the air.", ua = "Кордак трощить землю перед собою кулаками, налитими чародійством, завдаючи $458327s1 фізичної та $458319s1 арканної шкоди. Гравців, що потрапили під удар, підкидає в повітря." },
    { en = "Excess Arcane power coalesces into semi-stable forms which provide $s1% increased damage for $d when collected. This effect stacks.", ua = "Надлишок чародійської сили збирається в напівстабільні форми, що дають $s1% підвищеної шкоди протягом $d, коли їх зібрати. Цей ефект накопичується." },
    { en = "Kordac imbues several targets with supressive arcane energy. After $d, the energy explodes, silencing and pacifying the targets and all players within $458844A1 yards for $458844d.", ua = "Кордак наповнює кількох цілей пригнічувальною чародійською енергією. Через $d енергія вибухає, занімовуючи й утихомирюючи цілі та всіх гравців у радіусі $458844A1 м протягом $458844d." },
    { en = "Upon reaching 100 Energy, Kordac rains countless Arcane missiles down upon the area, inflicting $458433s1 Arcane damage to all players within $458433A1 yards of the impacts.", ua = "Досягнувши 100 енергії, Кордак проливає на місцевість незліченні чародійські снаряди, завдаючи $458433s1 арканної шкоди всім гравцям у радіусі $458433A1 м від ударів." },
    { en = "The Aggregation of Horrors slams its current target, inflicting $s1 Shadow damage and an additional $453298s1 Shadow damage every $453298t1 sec for $453298d.", ua = "Скупчення Жахіть гатить свою поточну ціль, завдаючи $s1 шкоди від тіні й додаткові $453298s1 шкоди від тіні кожні $453298t1 с протягом $453298d." },
    { en = "The Aggregation of Horrors expels jagged shards from its body, inflicting $s1 Shadow damage to players within 5 yards of a shard impact.", ua = "Скупчення Жахіть викидає зі свого тіла зазубрені скалки, завдаючи $s1 шкоди Тінню гравцям у межах 5 ярдів від падіння скалки." },
    { en = "The Aggregation of Horrors inflicts $s1 Shadow damage to its current target if the player is not in melee range.", ua = "Скупчення Жахіть завдає $s1 шкоди від тіні своїй поточній цілі, якщо гравець не в межах ближнього бою." },
    { en = "$@spellaura452980", ua = "$@spellaura452980" },
    { en = "The Aggregation of Horrors smashes the ground, inflicting $s1 Shadow damage to all players within $A1 yards and transforming nearby shards into Fractured Skardyn.", ua = "Скупчення Жахіть трощить землю, завдаючи $s1 шкоди від тіні всім гравцям у радіусі $A1 м і перетворюючи скалки поблизу на Розколотих Скардинів." },
    { en = "Shurrai vomits up brine, inflicting $453748s1 Frost damage to players within $453748A1 yards of each impact. The pools of brine persist, inflicting $453757s1 Frost damage to players every $453757t1 sec and slowing movement speed by $453757s2%.", ua = "Шуррай вивергає розсіл, завдаючи $453748s1 шкоди від морозу гравцям у радіусі $453748A1 м від кожного падіння. Калюжі розсолу лишаються, завдаючи $453757s1 шкоди від морозу гравцям кожні $453757t1 с і сповільнюючи швидкість пересування на $453757s2%." },
    { en = "Shurrai slams his current target with a necromantically-infused anchor, inflicting $s1 Plague damage and applying a heal absorb equal to the amount of unmitigated damage.", ua = "Шуррай гатить свою поточну ціль якорем, налитим некромантією, завдаючи $s1 шкоди від чуми й накладаючи поглинання зцілення, що дорівнює обсягу непом'якшеної шкоди." },
    { en = "Upon death, the caster inflicts $453871s1 Plague damage to players within $453871A1 yards and an additional $453871s2 Plague damage every $453871t2 sec for $453871d. This effect stacks.\n\n\n\nThe released souls also lash back at their captor, inflicting $455635s1 Plague damage to Shurrai.", ua = "Після загибелі закляттяр завдає $453871s1 шкоди від чуми гравцям у радіусі $453871A1 м і додаткові $453871s2 шкоди від чуми кожні $453871t2 с протягом $453871d. Цей ефект накопичується.\n\n\n\nВивільнені душі також обертаються проти свого полонителя, завдаючи $455635s1 шкоди від чуми Шурраю." },
    { en = "Shurrai summons 3 waves that travel outwards, inflicting $455175s1 Frost damage and knocking players away. These waves dissolve any pools of $@spellname453733 that they pass through.", ua = "Шуррай прикликає 3 хвилі, що розходяться назовні, завдаючи $455175s1 шкоди від морозу й відкидаючи гравців. Ці хвилі розчиняють усі калюжі $@spellname453733, крізь які проходять." },
    { en = "Shurrai regurgitates the souls of his past victims every $t1 sec for $d, inflicting $455667s1 Plague damage to all players and ejecting a mass of captive souls that inflicts $453885s1 Plague damage to players within $453885A1 yards of the impact. Each impact summons $s3 Drowned Arathi.", ua = "Шуррай відригує душі своїх колишніх жертв кожні $t1 с протягом $d, завдаючи $455667s1 шкоди від чуми всім гравцям і викидаючи масу полонених душ, що завдає $453885s1 шкоди від чуми гравцям у радіусі $453885A1 м від падіння. Кожне падіння прикликає $s3 Утоплених Араті." },
    { en = "Shurrai enshrouds himself in necromantic energies, absorbing $s1 damage for $d every $453875t1 sec during $@spellname453875.", ua = "Шуррай огортає себе некромантичними енергіями, поглинаючи $s1 шкоди протягом $d кожні $453875t1 с під час $@spellname453875." },
    { en = "Orta slams the ground, inflicting $450407s1 Nature damage to players in a frontal cone and knocking them high into the air.", ua = "Орта гатить по землі, завдаючи $450407s1 шкоди від сил природи гравцям у фронтальному конусі й підкидаючи їх високо в повітря." },
    { en = "Orta grabs nearby players, crushing them in his grasp and inflicting $s4 Physical damage. His grasp silences players and inflicts $s2 Physical damage every $t2 sec.", ua = "Орта хапає гравців поблизу, розчавлюючи їх у своєму захваті й завдаючи $s4 фізичної шкоди. Його хват занімовує гравців і завдає $s2 фізичної шкоди кожні $t2 с." },
    { en = "Orta invokes a rune of devastation every $t1 sec for $d. When triggered, the runes stun the triggering player and additionally inflict $450863s3 Fire damage every $450863t3 sec for $450863d.", ua = "Орта прикликає руну спустошення кожні $t1 с протягом $d. Коли руни спрацьовують, вони оглушують гравця, що їх активував, і додатково завдають $450863s3 вогняної шкоди кожні $450863t3 с протягом $450863d." },
    { en = "Orta flings the weaklings within his grasp away from himself with all his might.", ua = "Орта з усієї сили жбурляє від себе слабаків, яких тримає у своєму захваті." },
    { en = "Orta unleashes a powerful roar, inflicting $s1 Sonic damage to all players and knocking them back. The roar inflicts an additional $s2 Sonic damage every $t2 sec for $d.", ua = "Орта вивільняє потужний рев, завдаючи $s1 звукової шкоди всім гравцям і відкидаючи їх. Рев завдає додаткові $s2 звукової шкоди кожні $t2 с протягом $d." },
    { en = "The Primed Boomcrawler detonates, inflicting $s1 Fire damage and knocking back players within $A2 yards.", ua = "Заряджений Бабахоповз детонує, завдаючи $s1 вогняної шкоди й відкидаючи гравців у радіусі $A2 м." },
    { en = "The Gobfather spews a barrage of missiles from its rocket launchers, inflicting $s1 Fire damage to players within $a1 yards of each impact.", ua = "Ґобатько випускає зі своїх ракетниць шквал снарядів, завдаючи $s1 шкоди вогнем гравцям у радіусі $a1 м від кожного влучання." },
    { en = "The Gobfather slams the ground with massive force, inflicting $s1 Fire damage to all players and knocking them back.", ua = "Ґобфазер трощить землю з величезною силою, завдаючи $s1 вогняної шкоди всім гравцям і відкидаючи їх." },
    { en = "The Gobfather unleashes a jet of flame, inflicting $s2 Fire damage to players in a frontal cone.", ua = "Ґобфазер вивільняє струмінь полум'я, завдаючи $s2 вогняної шкоди гравцям у фронтальному конусі." },
    { en = "The Gobfather releases hazardous chemicals into the air, inflicting $s1 Nature damage every $t1 sec.", ua = "Ґобфазер випускає в повітря небезпечні хімікати, завдаючи $s1 шкоди від сил природи кожні $t1 с." },
    { en = "The Gobfather scatters Primed Boomcrawlers that wander for $1216574d. Stepping on a Primed Boomcrawler causes it to detonate early, triggering $@spellname1216577.", ua = "Ґобатько розкидає Заряджених Бабахоповзів, що блукають $1216574d. Якщо наступити на Зарядженого Бабахоповза, він детонує передчасно, спричиняючи $@spellname1216577." },
    { en = "Reinforced plating reduces the damage the Primed Boomcrawler receives by $s1%.", ua = "Підсилена броня зменшує шкоду, яку отримує Заряджений Бабахоповз, на $s1%." },
    { en = "On death, the beetles innards spill across the floor creating a tempting treat for Ulgrax.", ua = "По смерті нутрощі жука розливаються по підлозі, створюючи спокусливу поживу для Улґракса." },
    { en = "Ulgrax crushes the current threat target, inflicting $434702s1 Physical damage and $s2 applications of $@spellname434705.", ua = "Улґракс трощить поточну ціль загрози, завдаючи $434702s1 фізичної шкоди та накладаючи $s2 застосувань ефекту $@spellname434705." },
    { en = "Ulgrax leaps to the center of the arena and smashes the ground, inflicting $s1 Physical damage and knocking back all players. Players farther from the target receive less damage.", ua = "Улґракс стрибає в центр арени й гатить по землі, завдаючи $s1 фізичної шкоди та відкидаючи всіх гравців. Гравці, дальші від цілі, отримують менше шкоди." },
    { en = "Insulted by players' unwillingness to take the $@spellname434776 seriously, Ulgrax flies into a rage, increasing damage inflicted by $s1%.", ua = "Ображений небажанням гравців сприймати $@spellname434776 серйозно, Улґракс впадає в лють, збільшуючи завдану шкоду на $s1%." },
    { en = "Reduces healing taken by $s1%. This effect stacks, but loses an application every $t2 sec.", ua = "Зменшує отримане зцілення на $s1%. Цей ефект накопичується, але втрачає одне застосування кожні $t2 сек." },
    { en = "Ulgrax traps players in webs, stunning them for $d. The webs inflict $s1 damage every $t1 sec to the trapped player while intact.", ua = "Улґракс ловить гравців у павутиння, оглушуючи їх на $d. Поки павутиння ціле, воно завдає полоненому гравцю $s1 шкоди кожні $t1 сек." },
    { en = "Ulgrax increases his Physical damage done by $s1% for $d.", ua = "Улґракс збільшує завдану фізичну шкоду на $s1% на $d." },
    { en = "Ulgrax emerges from the Swallowing Darkness and charges across the arena, inflicting $436217s1 Shadow damage to players caught in his path.\n\n\n\nUlgrax re-enters the Darkness on the opposite side of the arena, inflicting $s1 Shadow damage instantly and $s2 Shadow damage every $t2 sec for $d.", ua = "Улґракс виринає з Всепоглинної Темряви й мчить через арену, завдаючи $436217s1 шкоди від тіні гравцям на своєму шляху.\n\n\n\nУлґракс знову занурюється в Темряву з протилежного боку арени, миттєво завдаючи $s1 шкоди від тіні та $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "Damage taken from $@spellname434776 increased by $s1%.", ua = "Шкода від $@spellname434776 збільшена на $s1%." },
    { en = "Hurl viscera into Ulgrax's gullet to sate his hunger.", ua = "Жбурляй нутрощі в горлянку Улґракса, щоб втамувати його голод." },
    { en = "Inflicts $s1 Nature damage to up to $i enemies within $a1 yards and adapts the caster's bile glands to inflict $457599s1% additional Nature damage per successful volley of Bioactive Spines.", ua = "Завдає $s1 шкоди Природою щонайбільше $i ворогам у межах $a1 ярдів і пристосовує жовчні залози творця, щоб завдавати додатково $457599s1% шкоди Природою за кожен успішний залп Біоактивних Голок." },
    { en = "Ulgrax flings poison at all players, inflicting $s1 Nature damage on impact and an additional $s2 Nature damage every $t2 sec for $d.", ua = "Улґракс жбурляє отруту в усіх гравців, завдаючи $s1 шкоди від сил природи при влучанні та додаткові $s2 шкоди від сил природи кожні $t2 сек протягом $d." },
    { en = "Ulgrax belches Digestive Acid at several players, inflicting $s1 Nature damage every $t1 sec for $d.\n\n\n\nOnce removed venom erupts the victim's skin, inflicting $435152s1 Nature damage to players within $435152a1 yards and dissolving any webbing left behind by $@spellname441451.", ua = "Улґракс відригує Травну Кислоту на кількох гравців, завдаючи $s1 шкоди від сил природи кожні $t1 сек протягом $d.\n\n\n\nКоли ефект знято, отрута проривається крізь шкіру жертви, завдаючи $435152s1 шкоди від сил природи гравцям у межах $435152a1 ярдів і розчиняючи будь-яке павутиння, залишене ефектом $@spellname441451." },
    { en = "Ulgrax emerges from the Swallowing Darkness rift to sate his hunger. The Darkness inflicts $s1 Shadow damage to players in the area and destroys $@spellname441452.", ua = "Улґракс виринає з розлому Всепоглинної Темряви, щоб втамувати свій голод. Темрява завдає $s1 шкоди від тіні гравцям у зоні та знищує $@spellname441452." },
    { en = "Ulgrax devours the player inflicting $s1 Physical damage every $t1 sec for $d.", ua = "Улґракс пожирає гравця, завдаючи $s1 фізичної шкоди кожні $t1 сек протягом $d." },
    { en = "Ulgrax spews webs at a player and all allies within $a1 yards, inflicting $s1 Nature damage split evenly between all players, binding them to Ulgrax.\n\n\n\nBound players suffer $s3 Nature damage every $t3 sec and are pulled toward Ulgrax. The strength with which Ulgrax pulls players is reduced for each bound player.", ua = "Улґракс випускає павутиння на гравця та всіх союзників у межах $a1 ярдів, завдаючи $s1 шкоди від сил природи, що порівну розподіляється між усіма гравцями, і прив'язуючи їх до Улґракса.\n\n\n\nПрив'язані гравці зазнають $s3 шкоди від сил природи кожні $t3 сек і притягуються до Улґракса. Сила, з якою Улґракс притягує гравців, зменшується за кожного прив'язаного гравця." },
    { en = "Ulgrax shoots webs over random destinations, inflicting $s1 Nature damage to players within $a1 yards of impact and leaving behind $@spellname439419.", ua = "Улґракс випускає павутину на випадкові цілі, завдаючи $s1 шкоди від сил природи гравцям у радіусі $a1 м від місця удару та лишаючи по собі $@spellname439419." },
    { en = "Ulgrax refuses to move until fed, meanwile damage taken from all sources is reduced by $s2%.", ua = "Улґракс відмовляється рухатися, доки його не нагодують, а тим часом шкода, якої він зазнає з усіх джерел, зменшена на $s2%." },
    { en = "Ulgrax traps players, rooting them for $d. Players trapped suffer $s2 Nature damage every $t2 sec.", ua = "Улґракс заманює гравців у пастку, знерухомлюючи їх на $d. Спіймані гравці зазнають $s2 од. шкоди Природи кожні $t2 с." },
    { en = "Ulgrax screams for food, inflicting $s1 Physical damage to all players on impact and an additional $s2 Physical damage every $t2 sec for $d.\n\n\n\nUlgrax's $@spellname438041 builds with each Bellow.", ua = "Улґракс волає, вимагаючи їжі, завдаючи $s1 фізичної шкоди всім гравцям при влучанні та додаткові $s2 фізичної шкоди кожні $t2 сек протягом $d.\n\n\n\nЕфект $@spellname438041 Улґракса наростає з кожним Ревом." },
    { en = "Bites at the player's guts, inflicting $s1 Physical damage and an additional $s2 Physical damage every $t2 sec for $d. This effect stacks.", ua = "Кусає нутрощі гравця, завдаючи $s1 фізичної шкоди та додаткові $s2 фізичної шкоди кожні $t2 сек протягом $d. Цей ефект накопичується." },
    { en = "A shadowy realm below reality where true horrors lurk.", ua = "Тіньовий світ під реальністю, де чигають справжні жахіття." },
    { en = "The return to reality scars the player, increasing damage taken from $@spellname443612 by $s1% for $d.", ua = "Повернення до реальності залишає на гравцеві шрами, збільшуючи шкоду від $@spellname443612 на $s1% протягом $d." },
    { en = "The Bloodbound Horror siphons Black Blood from the surrounding pool granting itself a $@spellname461876. It then unleashes a torrent of Black Blood that washes over all players within $442530A1 yards, inflicting $442530s1 Shadow damage.\n\n\n\nResidue sticks to remaining players, inflicting $s2 Shadow damage every $t2 sec for $d.", ua = "Кровопов'язаний Жах висмоктує Чорну Кров із довколишньої калюжі, надаючи собі $@spellname461876. Тоді він вивільняє потік Чорної Крові, що накриває всіх гравців у радіусі $442530A1 м, завдаючи $442530s1 шкоди від тіні.\n\n\n\nЗалишки прилипають до решти гравців, завдаючи $s2 шкоди від тіні щосекунди $t2 протягом $d." },
    { en = "The Bloodbound Horror focuses The Unseeming on to multiple players, manifesting tentacles at their location every $443042t1 sec for $443042d.\n\n\n\nAfter $s2 sec each tentacle erupts, inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Кровозв'язаний Жах зосереджує Незриме на кількох гравцях, породжуючи мацаки в їхньому розташуванні кожні $443042t1 сек. протягом $443042d.\n\n\n\nЧерез $s2 сек. кожен мацак вибухає, завдаючи $s1 шкоди Тінню всім гравцям у радіусі $A1 ярдів." },
    { en = "If no players are within reach, The Bloodbound Horror continually expels contaminated blood that inflicts $438696s1 Shadow damage to all players every $438682t1 sec.", ua = "Якщо поблизу немає жодного гравця, Кровопов'язаний Жах безперервно вивергає заражену кров, що завдає $438696s1 шкоди від тіні всім гравцям щосекунди $438682t1." },
    { en = "Blood Horrors that reach The Bloodbound Horror explode, inflicting $s1 Shadow damage to all players.", ua = "Криваві Жахіття, що досягають Кровозв'язаного Жаху, вибухають, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "The Bloodbound Horror coats each player in vile blood, causing them to absorb ${$s1*$s2} healing.", ua = "Кровозв'язаний Жах укриває кожного гравця мерзенною кров'ю, через що ті поглинають ${$s1*$s2} зцілення." },
    { en = "The Lost Watcher slams their current target, inflicting $s1 Physical damage.", ua = "Втрачений Вартовий гатить по своїй поточній цілі, завдаючи $s1 фізичної шкоди." },
    { en = "The Bloodbound Horror vomits Black Blood in a cone in front of itself, inflicting $s1 Shadow damage and an additional $443612s3 Shadow damage every $443612t3 sec for $443612d. Players under this effect briefly peer into The Unseeming.", ua = "Кровозв'язаний Жах вивергає Чорну Кров конусом перед собою, завдаючи $s1 шкоди від тіні та додаткові $443612s3 шкоди від тіні кожні $443612t3 сек протягом $443612d. Гравці під дією цього ефекту на мить зазирають у Неподобне." },
    { en = "The Bloodbound Horror transfuses Black Blood into each player that causes them to erupt after $452245d, inflicting $s1 Shadow damage to players within $A2 yards.", ua = "Кровозв'язане Жахіття вливає Чорну Кров у кожного гравця, через що той вибухає за $452245d, завдаючи $s1 шкоди Тінню гравцям у межах $A2 ярдів." },
    { en = "The Bloodbound Horror forms two geysers of Black Blood on each side that slowly rotate around itself for $s2 sec. Standing within a geyser inflicts $s1 Shadow damage every ${$442656t1}.2 sec.", ua = "Кровопов'язаний Жах утворює обабіч себе два гейзери Чорної Крові, що повільно обертаються довкола нього протягом $s2 с. Перебування в гейзері завдає $s1 шкоди від тіні кожні ${$442656t1}.2 с." },
    { en = "The Bloodbound Horror transfuses the Black Blood into its body, increasing its damage done by $s1%. This effect stacks.", ua = "Кровозв'язаний Жах переливає Чорну Кров у своє тіло, збільшуючи завдану шкоду на $s1%. Цей ефект накопичується." },
    { en = "The Forgotten Harbinger manifests a Blood Horror out of The Unseeming that slowly moves toward The Bloodbound Horror.", ua = "Забутий Передвісник прикликає з Неподобного Криваве Жахіття, що повільно рухається до Кровозв'язаного Жаху." },
    { en = "The Lost Watcher channels the essence of The Unseeming into The Bloodbound Horror, causing it to absorb $451305s1 damage, increasing every $t1 sec for $d.", ua = "Втрачений Вартовий вливає есенцію Неподобного в Кровозв'язаного Жаху, через що той поглинає $451305s1 шкоди, і це значення зростає кожні $t1 сек протягом $d." },
    { en = "Sikran's blades rend a portion of players essence, creating a simulacrum at their location.\n\n\n\nThese simulacrums pulse with cosmic energy, inflicting $458340s1 Shadow damage to all players every $t2 sec until they are destroyed.", ua = "Клинки Сікрана відсікають частину сутності гравців, створюючи симулякр на їхньому місці.\n\n\n\nЦі симулякри пульсують космічною енергією, завдаючи $458340s1 шкоди Тінню всім гравцям кожні $t2 с, доки їх не буде знищено." },
    { en = "Sikran marks players and lunges towards each marked target inflicting $433877s1 Physical damage to anyone in his path. \n\n\n\nAdditionally, players hit have their healing received reduced by $434860s2% and an additional $434860s1 Shadow damage inflicted every $434860t1 sec for $434860d.\n\n\n\nMarked targets leave behind a $@spellname458272 when struck.", ua = "Сікран позначає гравців і кидається до кожної позначеної цілі, завдаючи $433877s1 фізичної шкоди кожному на своєму шляху. \n\n\n\nКрім того, ураженим гравцям зменшується отримуване зцілення на $434860s2%, а також завдається додатково $434860s1 шкоди тінню кожні $434860t1 с протягом $434860d.\n\n\n\nПозначені цілі при ударі лишають по собі $@spellname458272." },
    { en = "At 100 energy, Sikran swings his polearm in a deadly arc, inflicting $458277s1 Shadow damage to all enemies. This damage is decreased based on distance. \n\n\n\nAll remaining Cosmic Simulacrum are destroyed by this effect, and damage from $@spellname459273 is increased by $464442s1% for each Simulacrum destroyed for $464442d.\n\n\n\nAdditionally, players within $458277A2 yards are knocked back and have their damage taken increased by $458277s2% for $458277d.", ua = "При 100 енергії Сікран змахує своєю древковою зброєю по смертоносній дузі, завдаючи $458277s1 шкоди Тінню всім ворогам. Ця шкода зменшується залежно від відстані. \n\n\n\nЦей ефект знищує всі вцілілі Космічні Симулякри, а шкода від $@spellname459273 збільшується на $464442s1% за кожен знищений Симулякр протягом $464442d.\n\n\n\nКрім того, гравців у межах $458277A2 ярдів відкидає, а отримувана ними шкода збільшується на $458277s2% на $458277d." },
    { en = "Sikran fires a volley of arrows into the air, falling throughout the area, inflicting $432353s1 Shadow damage to players within $432353a1 yds of impact.", ua = "Сікран випускає в повітря залп стріл, що падають по всій зоні, завдаючи $432353s1 шкоди від тіні гравцям у межах $432353a1 ярдів від влучання." },
    { en = "Upon being destroyed the Cosmic Simulacrum erupts, inflicting $s1 Shadow damage to all players, and an additional $s2 Shadow damage every $t2 sec for $d. This effect stacks. \n\n\n\nIn addition, the eruption leaves behind a pool of Cosmic Residue.", ua = "Знищений Космічний Симулякр вибухає, завдаючи $s1 шкоди від тіні всім гравцям і додаткові $s2 шкоди від тіні кожні $t2 сек протягом $d. Цей ефект накопичується. \n\n\n\nКрім того, вибух лишає по собі калюжу Космічного Залишку." },
    { en = "Cosmic Simulacrums leave a residue from beyond that reduces all healing received by $s3% and inflicts $s1 Shadow damage to players every $t1 sec and persist $?DIFF17[for $459831d.][] $?DIFF14[for $459831d.][]$?DIFF15[Until the end of the encounter.][]$?DIFF16[until the end of the encounter.][]", ua = "Космічні Симулякри лишають залишок з-поза меж, що зменшує все отримане зцілення на $s3% і завдає $s1 шкоди від тіні гравцям кожні $t1 сек, та зберігається $?DIFF17[протягом $459831d.][] $?DIFF14[протягом $459831d.][]$?DIFF15[До кінця бою.][]$?DIFF16[до кінця бою.][]" },
    { en = "Sikran slashes at his target, inflicting $s1 Physical damage and exposing a weakness, increasing Physical damage taken by $438845s1% for $438845d.", ua = "Сікран шматує свою ціль, завдаючи $s1 фізичної шкоди й оголюючи слабке місце, що збільшує отримувану фізичну шкоду на $438845s1% протягом $438845d." },
    { en = "Sikran pierces his primary target, inflicting $s1 Shadow damage, $446819s1 Physical damage.\n\n\n\nIn addition, the target takes $435410s1% increased damage from Phase Lunge for $435410d.", ua = "Сікран простромлює свою основну ціль, завдаючи $s1 шкоди від тіні та $446819s1 фізичної шкоди.\n\n\n\nКрім того, ціль зазнає на $435410s1% більше шкоди від Фазового Випаду протягом $435410d." },
    { en = "Sikran unleashes a barrage of maneuvers, executing two Exposes before ending with a Phase Lunge.", ua = "Сікран вивільняє шквал маневрів, виконуючи два Викриття, а потім завершує Фазовим випадом." },
    { en = "Cosmic Simulacrums react to each other and combust, inflicting $s1 Shadow damage to all players if another Simulacrum is within $s2 yards.", ua = "Космічні симулякри реагують одне на одного й спалахують, завдаючи $s1 шкоди від тіні всім гравцям, якщо інший симулякр перебуває в межах $s2 м." },
    { en = "Sikran unleashes a barrage of cosmic eruptions from his polearm, inflicting $459350s1 Shadow damage to all players between himself and his targets. \n\n\n\nCosmic Simulacrum's that are hit by this effect are destroyed.", ua = "Сікран вивільняє зі своєї древкової зброї шквал космічних вивержень, завдаючи $459350s1 шкоди Тінню всім гравцям між ним і його цілями.\n\n\n\nКосмічні Симулякри, уражені цим ефектом, знищуються." },
    { en = "$@spellname439811 jettisons globs of acid at players inflicting $440193s1 Nature damage every $440193T1 sec for $440193D. This effect stacks.", ua = "$@spellname439811 жбурляє в гравців згустки кислоти, завдаючи $440193s1 шкоди від сил природи кожні $440193T1 с протягом $440193D. Цей ефект накопичується." },
    { en = "Rasha'nan spews acid for $439811D inflicting $s2 Nature damage to all players plus an additional $440191s1 every $439811T1 sec, periodically applying $@spellname440193.", ua = "Раша'нан випльовує кислоту протягом $439811D, завдаючи $s2 шкоди від сил природи всім гравцям, а також додатково $440191s1 кожні $439811T1 с, періодично накладаючи $@spellname440193." },
    { en = "Rasha'nan seeds a new brood within marked targets $?diff15|diff16[inflicting $439817s1 Nature damage to players within $439817A1 yards][inflicting $439817s1 Nature damage]. These spawn then $@spellname455287 their host before finding new prey.", ua = "Раша'нан засіває новий виводок у позначених цілях$?diff15|diff16[, завдаючи $439817s1 шкоди від сил природи гравцям у межах $439817A1 м][, завдаючи $439817s1 шкоди від сил природи]. Ці поріддя тоді $@spellname455287 свого носія, перш ніж шукати нову здобич." },
    { en = "Rasha'nan smashes her current target inflicting $444694s1 Physical damage and $444696s1 Nature damage. Additionally $444687s1% of unmitigated damage is inflicted as a $@spellname444704.", ua = "Раша'нан гамселить свою поточну ціль, завдаючи $444694s1 фізичної шкоди та $444696s1 шкоди від сил природи. До того ж $444687s1% незменшеної шкоди завдається як $@spellname444704." },
    { en = "Successful $@spellname452806 casts form a temporay shell, granting Rasha'nan immunity from damage for $457877D.", ua = "Успішні прочитання $@spellname452806 утворюють тимчасову оболонку, даруючи Раша'нану несприйнятливість до шкоди протягом $457877D." },
    { en = "Rasha'nan rains acid inflicting $s1 Nature damage to players within $A1 yards of impact locations, occasionally creating Acid Pools.", ua = "Раша'нан проливає кислотний дощ, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 м від місць влучання й час від часу утворюючи кислотні калюжі." },
    { en = "Until interrupted Rasha'nan thrashes about inflicting $s1 Nature damage to all players and increases Acidic Eruption damage by $s2% $?diff16[forever][for $D]. This effect stacks.", ua = "Доки її не перервуть, Раша'нан несамовито б'ється навсібіч, завдаючи $s1 шкоди від сил природи всім гравцям і підвищуючи шкоду від Кислотного Виверження на $s2% $?diff16[назавжди][протягом $D]. Цей ефект накопичується." },
    { en = "Rasha'nan ejects torrents of sticky web that inflict $454988s1 Nature damage to players within $454988A1 yards of impact. \n\n\n\nThis effect entombs players in webbing stunning them for $454991D. Destroying these webs removes the effect.", ua = "Раша'нан викидає потоки липкого павутиння, що завдають $454988s1 шкоди від сил природи гравцям у межах $454988A1 м від місця влучання. \n\n\n\nЦей ефект замуровує гравців у павутинні, оглушуючи їх на $454991D. Знищення цього павутиння знімає ефект." },
    { en = "Inflicts the unmitigated damage from $@spellname444687 as Physical and Nature damage every $T1 sec for $D. This effect stacks, adding to the effects of previous Savage Wounds.", ua = "Завдає незменшеної шкоди від $@spellname444687 як фізичної шкоди та шкоди від сил природи кожні $T1 с протягом $D. Цей ефект накопичується, додаючись до ефектів попередніх Лютих Ран." },
    { en = "Rasha'nan's rakes the targeted area inflicting $439794s1 Nature damage and pulling players towards her. These effects split evenly among players within $439795A1 yards of the impact.\n\n\n\nIf Web Reave fails to hit at least $439795s1 targets all players suffer the full effect.", ua = "Раша'нан роздирає цільову ділянку, завдаючи $439794s1 шкоди від сил природи й притягуючи гравців до себе. Ці ефекти рівномірно розподіляються між гравцями в межах $439795A1 м від місця влучання.\n\n\n\nЯкщо Павутинний Розрив влучає менш ніж у $439795s1 цілей, усі гравці зазнають повного ефекту." },
    { en = "Rasha'nan binds the initial targets of Spinneret's Strands with a web of adhesive sinews that snap after $460789D, inflicting $460798s1 Nature damage to players inside the indicated area.", ua = "Раша'нан зв'язує початкові цілі Прядивних Ниток павутиною з клейких сухожиль, що рвуться за $460789D, завдаючи $460798s1 шкоди від сил природи гравцям у позначеній зоні." },
    { en = "The Infested Spawn chews on their target inflicting $455287s1 Nature damage every $455287T1 sec$?diff16[ and reduces movement speed by $s2%][] for $455287D. This effect stacks.", ua = "Заражене Поріддя гризе свою ціль, завдаючи $455287s1 шкоди від сил природи кожні $455287T1 с$?diff16[ і знижуючи швидкість пересування на $s2%][] протягом $455287D. Цей ефект накопичується." },
    { en = "Coming into contact with $@spellname442810 mutates Voracious Worms, increasing their health by $s1% and increases casting speed by $s2%.", ua = "Контакт із $@spellname442810 спричиняє мутацію Ненажерливих Червів, підвищуючи їхнє здоров'я на $s1% і швидкість творення заклять на $s2%." },
    { en = "Broodtwister Ovi'nax injects Black Blood into its Experimental Eggs, mutating the creatures growing within. \n\n\n\nBroodtwister Ovi'nax injects all eggs matching the egg associated with each Black Blood canister.", ua = "Виводкокрут Ові'накс впорскує Чорну Кров у свої експериментальні яйця, спричиняючи мутацію істот, що ростуть усередині. \n\n\n\nВиводкокрут Ові'накс впорскує її в усі яйця, що відповідають яйцю, пов'язаному з кожним балоном Чорної Крові." },
    { en = "While empowered by Mutation: Necrotic, $@spellname438807 also reduces healing done to the target by $s1% for $d.", ua = "Під час підсилення Мутацією: Некротичне, $@spellname438807 також зменшує зцілення, отримуване ціллю, на $s1% протягом $d." },
    { en = "Black Blood causes the rapid incubation of any Experimental Eggs it touches, causing it to hatch and inflict $s1 Shadow damage to all players every $t1 sec for $d.", ua = "Чорна Кров спричиняє швидку інкубацію будь-яких експериментальних яєць, яких торкнеться, змушуючи їх вилупитися й завдавати $s1 шкоди від тіні всім гравцям кожні $t1 с протягом $d." },
    { en = "Coming into contact with $@spellname442810 mutates Colossal Spiders, increasing their health by $s1% and empowering Vicious Bite to inflict Necrotic Wounds.", ua = "Контакт із $@spellname442810 спричиняє мутацію Колосальних Павуків, підвищуючи їхнє здоров'я на $s1% і підсилюючи Лютий Укус, щоб той завдавав Некротичних Ран." },
    { en = "Consuming hunger drives the Blood Parasite to fixate upon their prey and attempt to $@spellname442257 it.", ua = "Всепоглинальний голод змушує Кров'яного Паразита вчепитися у свою здобич і спробувати $@spellname442257 її." },
    { en = "The Voracious Worm unleashes a blast of toxic slime that inflicts $s1 Nature damage to all players.", ua = "Ненажерливий Черв вивільняє вибух токсичного слизу, що завдає $s1 шкоди від сил природи всім гравцям." },
    { en = "Black Blood overloads Broodtwister Ovi'nax's system, unleashing a torrent of $@spellname441612 inflicting $s2 Shadow damage on impact to players in the area.", ua = "Чорна Кров перевантажує організм Виводкокрута Ові'накса, вивільняючи потік $@spellname441612, що завдає $s2 шкоди від тіні при влучанні гравцям у зоні дії." },
    { en = "Broodtwister Ovi'nax covers several players with sticky webbing, inflicting $s2 Nature damage every $t2 sec and reducing movement speed by $s1% until it is dispelled.\n\n\n\nUpon removal a $@spellname446351 is triggered.", ua = "Виводкокрут Ові'накс вкриває кількох гравців липким павутинням, завдаючи $s2 шкоди від сил природи кожні $t2 с і знижуючи швидкість пересування на $s1% до розвіювання.\n\n\n\nПісля зняття спрацьовує $@spellname446351." },
    { en = "The canister of Black Blood leaks its contents across the floor of the chamber, slowly growing in size. This pool inflicts $s1 Shadow damage and absorbs the next $s2 healing received every $t1 sec from players within the effect.\n\n\n\nExperimental Eggs that come in contact with the pool trigger a $@spellname450661.", ua = "Балон Чорної Крові розливає свій вміст по підлозі зали, повільно розростаючись. Ця калюжа завдає $s1 шкоди від тіні й поглинає наступні $s2 зцілення кожні $t1 с гравцям, які перебувають у її межах.\n\n\n\nЕкспериментальні яйця, що торкаються калюжі, спричиняють $@spellname450661." },
    { en = "Coming into contact with $@spellname442810 mutates Blood Parasites, increasing their health by $s1%.\n\n\n\nIn addition, their inexorable desire to consume increases their movement speed by $458207s1% every $t2 sec until they are slain.", ua = "Контакт із $@spellname442810 спричиняє мутацію Кров'яних Паразитів, підвищуючи їхнє здоров'я на $s1%.\n\n\n\nКрім того, їхнє невгамовне бажання поглинати підвищує їхню швидкість пересування на $458207s1% кожні $t2 с, доки їх не вб'ють." },
    { en = "Blood Parasite burrows into its target, inflicting $s1 Nature damage every $t1 sec for $d. \n\n\n\nUpon expiration, $?DIFF14[$s4][]$?DIFF15[$s2][]$?DIFF16[$s2][]$?DIFF17[$s4][] Blood Parasites erupt from the player and seek new prey.", ua = "Кров'яний Паразит угвинчується у свою ціль, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d. \n\n\n\nПісля закінчення з гравця виривається $?DIFF14[$s4][]$?DIFF15[$s2][]$?DIFF16[$s2][]$?DIFF17[$s4][] Кров'яних Паразитів, які шукають нову здобич." },
    { en = "Sticky webbing erupts from the target, inflicting $s1 Nature damage and rooting players within $a1 yards for $d.", ua = "З цілі виривається липке павутиння, завдаючи $s1 шкоди від сил природи й знерухомлюючи гравців у межах $a1 м протягом $d." },
    { en = "Broodtwister Ovi'nax injects a cocktail of unstable substances into his target, inflicting $s2 Nature damage and an additional $s1 Nature damage every $t1 sec for $d.\n\n\n\nUpon expiration the chemicals react, inflicting additional Nature damage based on the target's missing health. This damage is reduced the healthier the target is.", ua = "Виводкокрут Ові'накс впорскує у свою ціль коктейль з нестабільних речовин, завдаючи $s2 шкоди від сил природи й додатково $s1 шкоди від сил природи кожні $t1 с протягом $d.\n\n\n\nПісля закінчення хімікати реагують, завдаючи додаткової шкоди від сил природи залежно від нестачі здоров'я цілі. Що здоровіша ціль, то менша ця шкода." },
    { en = "The Colossal Spider bites its current target, inflicting $s1 Nature damage.\n\n\n\nIn addition, frenzy overtakes the spider, increasing its damage done by $s2% until it is slain. This effect stacks.", ua = "Колосальний Павук кусає свою поточну ціль, завдаючи $s1 шкоди від сил природи.\n\n\n\nКрім того, павука охоплює шал, підвищуючи завдавану ним шкоду на $s2%, доки його не вб'ють. Цей ефект накопичується." },
    { en = "Upon reaching full energy Broodtwister Ovi'nax charges towards a full canister of Black Blood and begins devouring it. Feasting upon the canisters contents unleashes torrents of $@spellname441612 every $442432t2 sec and inflicts $442437s1 Shadow damage that absorbs the next $442437s2 healing to all players. Upon finishing the canister, Broodtwister Ovi'nax gains $@spellname443273.", ua = "Сповнившись енергії, Виводкокрут Ові'накс кидається до повного балона Чорної Крові й починає його пожирати. Бенкетування вмістом балона вивільняє потоки $@spellname441612 кожні $442432t2 с і завдає $442437s1 шкоди від тіні, що поглинає наступні $442437s2 зцілення в усіх гравців. Допивши балон, Виводкокрут Ові'накс отримує $@spellname443273." },
    { en = "Waves of shadowy energy emanate from the Black Blood infused Broodtwister, inflicting $443274s1 Shadow damage and absorbing the next $443274s2 healing done to all players every $443273t1 sec. In addition, waves of $@spellname441612 are released every $443273t1 sec.", ua = "Хвилі тіньової енергії линуть від просякнутого Чорною Кров'ю Виводкокрута, завдаючи $443274s1 шкоди від тіні й поглинаючи наступні $443274s2 зцілення в усіх гравців кожні $443273t1 с. Крім того, кожні $443273t1 с вивільняються хвилі $@spellname441612." },
    { en = "Broodtwister Ovi'nax injects a reactive catalyst into several players causing them to erupt after $440421d, inflicting  $442660s1 Shadow damage and absorbing $442660s3 healing to all players within $442660a1 yards.\n\n\n\nExperimental Eggs caught in this effect are hatched.", ua = "Виводкокрут Ові'накс впорскує реактивний каталізатор у кількох гравців, змушуючи їх вибухнути за $440421d, що завдає $442660s1 шкоди від тіні й поглинає $442660s3 зцілення в усіх гравців у межах $442660a1 м.\n\n\n\nЕкспериментальні яйця, охоплені цим ефектом, вилуплюються." },
    { en = "A gaping wound that inflicts $440577s1 Shadow damage every $t1 sec and increases damage taken from Void Shredder strikes by $s2% for $d. This effect stacks.", ua = "Зяюча рана, що завдає $440577s1 шкоди від тіні кожні $t1 с і підвищує шкоду, отримувану від ударів Шматувальника Порожнечі, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Ky'veza marks several players for assassination. After $s1 sec, she shadowsteps to each target, inflicting $436934s1 Shadow damage to players within $436934A1 yards and applying Queensbane.\n\n\n\nCreates a $@spellname437371 at each location.", ua = "Кай'веза позначає кількох гравців для вбивства. За $s1 с вона робить тіньовий крок до кожної цілі, завдаючи $436934s1 шкоди від тіні гравцям у межах $436934A1 м і накладаючи Згубу Королеви.\n\n\n\nСтворює $@spellname437371 на кожному місці." },
    { en = "Ky'veza commands each Nether Phantom to focus a target player. After $s1 sec, each phantom dashes towards their target, inflicting $438145s1 Shadow damage and applying $@spellname437343 to any player in their path.", ua = "Кай'веза наказує кожному Примарі Нижнього Світу зосередитися на одному гравцеві. За $s1 с кожна примара кидається до своєї цілі, завдаючи $438145s1 шкоди від тіні й накладаючи $@spellname437343 на будь-якого гравця на своєму шляху." },
    { en = "Ky'veza consumes $@spellname448364 from Nether Phantoms that dash through her during $@spellname438245, cloaking herself in their dark power for $d. While active, Ky'veza's damage is increased by $s1%. This effect stacks.\n\n\n\nUpon reaching 3 stacks, $@spellname447174  becomes permanent.", ua = "Кай'веза поглинає $@spellname448364 з Примар Нижнього Світу, що проносяться крізь неї під час $@spellname438245, огортаючи себе їхньою темною силою на $d. Поки ефект активний, шкода Кай'вези підвищена на $s1%. Цей ефект накопичується.\n\n\n\nЗ досягненням 3 зарядів $@spellname447174 стає постійним." },
    { en = "The third $@spellname435405 has no end, shrouding the chamber in an eternal darkness.", ua = "Третя $@spellname435405 не має кінця, огортаючи залу у вічну темряву." },
    { en = "Ky'veza masks several Nether Phantoms in a grim veil.\n\n\n\nAs $@spellname435414 begins, phantoms still affected by a $@spellname447169 unleash a haunting scream that inflicts $449838s1 Shadow damage to all players.", ua = "Кай'веза огортає кількох Фантомів Нижнього Світу похмурою пеленою.\n\n\n\nКоли починається $@spellname435414, фантоми, досі вражені $@spellname447169, вивільняють моторошний крик, що завдає $449838s1 шкоди від тіні всім гравцям." },
    { en = "When any player drops below $s1% health, a shadow of Ky'veza emerges behind the target and attempts to execute them, inflicting $436762s1 Shadow damage.", ua = "Коли здоров'я будь-якого гравця падає нижче за $s1%, позаду цілі з'являється тінь Ки'вези й намагається стратити її, завдаючи $436762s1 од. шкоди Тіні." },
    { en = "Corrupted gore erupts outwards, inflicting $439408s1 Shadow damage to players hit.", ua = "Зіпсована кровиця вибухає назовні, завдаючи $439408s1 шкоди від тіні враженим гравцям." },
    { en = "Ky'veza tears open a rift to the Twisting Nether, inflicting $464259s1 Shadow damage to players within $s1 yards.\n\n\n\nThe rift inflicts $437839s1 Shadow damage to all players every $s2 sec for $d and pulls players towards its center.", ua = "Кай'веза розриває розлом до Викривленого Нижнього Світу, завдаючи $464259s1 шкоди від тіні гравцям у межах $s1 м.\n\n\n\nРозлом завдає $437839s1 шкоди від тіні всім гравцям кожні $s2 с протягом $d і притягує гравців до свого центру." },
    { en = "Ky'veza veils sections of the room with waves of darkness, inflicting $442495s1 Shadow damage to any player caught within.", ua = "Кай'веза огортає частини зали хвилями темряви, завдаючи $442495s1 шкоди від тіні будь-якому гравцеві, що потрапив усередину." },
    { en = "The phantom's haunting presence inflicts $436996s1 Shadow damage to all players every $t1 sec.", ua = "Моторошна присутність фантома завдає $436996s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "Upon reaching 100 energy, Ky'veza lifts into the air and pulses with darkness, inflicting $435415s1 Shadow damage to all players every $435405t1 sec for $435405d.", ua = "Сягнувши 100 енергії, Кай'веза здіймається в повітря й пульсує темрявою, завдаючи $435415s1 шкоди від тіні всім гравцям кожні $435405t1 с протягом $435405d." },
    { en = "Ky'veza flings regal knives in multiple directions, inflicting $440149s1 Shadow damage to any player struck.", ua = "Кай'веза метає величні ножі в кількох напрямках, завдаючи $440149s1 шкоди від тіні кожному враженому гравцеві." },
    { en = "Ky'veza carves a series of deep lacerations into her current target. Each strike inflicts $440413s1 Physical damage and $440521s1 Shadow damage and leaves behind a $@spellname440576.", ua = "Ки'веза розтинає поточну ціль серією глибоких ран. Кожен удар завдає $440413s1 од. фізичної шкоди та $440521s1 од. шкоди Тіні й лишає по собі $@spellname440576." },
    { en = "The $@spellname437620 vaporizes players pulled inside, inflicting $s1 Shadow damage every 0.25 sec.", ua = "$@spellname437620 випаровує гравців, затягнутих усередину, завдаючи $s1 шкоди від тіні кожні 0.25 с." },
    { en = "Nether Phantoms dive through the shadows at targeted players, inflicting $436787s1 Shadow damage to players in their path.", ua = "Фантоми Нижнього Світу пірнають крізь тіні до позначених гравців, завдаючи $436787s1 шкоди від тіні гравцям на своєму шляху." },
    { en = "A dark venom fit for royalty. Inflicts $437342s1 Shadow damage every $t1 sec for $d. This effect stacks.\n\n\n\nUpon expiration, the void infection bursts inflicting $437469s1 Shadow damage.", ua = "Темна отрута, гідна королів. Завдає $437342s1 од. шкоди Тіні кожні $t1 с протягом $d. Цей ефект накопичується.\n\n\n\nПісля закінчення зараження Порожнечею вибухає, завдаючи $437469s1 од. шкоди Тіні." },
    { en = "Takazj unleashes a deluge of venom, inflicting $s2 Nature damage to players within $A2 yards of the targets and an additional $s3 Nature damage every $t3 sec for $d.", ua = "Таказж вивільняє потік отрути, завдаючи $s2 шкоди від сил природи гравцям у межах $A2 м від цілей та додатково $s3 шкоди від сил природи кожні $t3 с протягом $d." },
    { en = "Anub'arash summons several Shattershell Scarabs that fixate upon players.", ua = "Ануб'араш прикликає кількох Скарабеїв-Друзкопанцирів, що фіксуються на гравцях." },
    { en = "Anub'arash unleashes swarms of insects at several targets, inflicting $s1 Nature damage every $t1 sec and increasing their damage taken by $s4%. \n\n\n\nUpon removal, the swarm releases a $@spellname449993 and the $@spellname438708 transfers to the nearest player or Takazj. If transferred to Takazj, the $@spellname438708 dissipates after $456252d.\n\n\n\nAt $s3 applications the target suffers from $@spellname456235 and loses all applications of $@spellname438708.", ua = "Ануб'араш напускає рої комах на кількох цілей, завдаючи $s1 шкоди від сил природи щосекунди $t1 і збільшуючи отримувану ними шкоду на $s4%. \n\n\n\nПісля зняття рій вивільняє $@spellname449993, а $@spellname438708 переходить до найближчого гравця або до Таказж. У разі переходу до Таказж $@spellname438708 розсіюється після $456252d.\n\n\n\nПри $s3 нашаруваннях ціль зазнає $@spellname456235 і втрачає всі нашарування $@spellname438708." },
    { en = "Takazj pulls players to her location with dark strands of webs, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d.\n\n\n\nPlayers hit are bound to another player with $@spellname440001.", ua = "Таказж притягує гравців до себе темними пасмами павутини, завдаючи $s1 од. шкоди Природи та додатково $s2 од. шкоди Природи кожні $t2 с протягом $d.\n\n\n\nУражені гравці зв'язуються з іншим гравцем за допомогою $@spellname440001." },
    { en = "Takazj shields herself, absorbing $s2 damage. \n\n\n\nWhile the shield holds, Takazj unleashes an $@spellname460600 every $t1 sec and spins cones of webs throughout the chamber. These webs decrease player movement by $451086s1% and inflict $451086s2 Shadow damage every $451086t2 sec to players within the area. \n\n\n\nThe webs periodically explode, knocking players back while inflicting $451016s2 Shadow damage and an additional $451016s4 Shadow damage every $451016t4 sec for $451016d.", ua = "Таказж огортає себе щитом, що поглинає $s2 шкоди.\n\n\n\nПоки щит тримається, Таказж вивільняє $@spellname460600 кожні $t1 с і пряде конуси павутини по всій палаті. Ця павутина сповільнює пересування гравців на $451086s1% і завдає $451086s2 шкоди від тіні кожні $451086t2 с гравцям у межах ділянки.\n\n\n\nПавутина періодично вибухає, відкидаючи гравців і завдаючи $451016s2 шкоди від тіні та додатково $451016s4 шкоди від тіні кожні $451016t4 с протягом $451016d." },
    { en = "Upon reaching 100 energy, the Shattershell Scarab increases its movement speed by $s1% and becomes immune to crowd control effects.", ua = "Сягнувши 100 енергії, Скарабей-Друзкопанцир збільшує швидкість свого пересування на $s1% і стає несприйнятливим до ефектів контролю." },
    { en = "Players marked by Takazj are filled with paranoia, killing any player without $@spellname455849 within $A yards. \n\n\n\nPlayers affected by the mark create a $@spellname460357 when hit by some of The Silken Court's abilities.", ua = "Гравців, позначених Таказж, охоплює параноя, що вбиває будь-якого гравця без $@spellname455849 у межах $A ярдів. \n\n\n\nГравці під дією мітки створюють $@spellname460357, коли їх вражають деякі здібності Шовкового Двору." },
    { en = "Players marked by Anub'arash are filled with rage, killing any player without $@spellname455850 within $a1 yards. \n\n\n\nPlayers affected by the mark create a $@spellname460263 when hit by some of The Silken Court's abilities.", ua = "Гравців, позначених Ануб'арашем, охоплює лють, що вбиває будь-якого гравця без $@spellname455850 у межах $a1 ярдів. \n\n\n\nГравці під дією мітки створюють $@spellname460263, коли їх вражають деякі здібності Шовкового Двору." },
    { en = "A mass of Stinging Swarms overwhelms the target, increasing their damage taken by $s2% and disorienting them for $d.", ua = "Маса Жалких Роїв накриває ціль, збільшуючи отримувану нею шкоду на $s2% і дезорієнтуючи її на $d." },
    { en = "Takazj flings a shadow bolt at her current target, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Таказж жбурляє згусток Тіні в поточну ціль, завдаючи $s1 од. шкоди Тіні та додатково $s2 од. шкоди Тіні кожні $t2 с протягом $d." },
    { en = "The Shattershell Scarab's carapace begins in a hardened state, reducing damage by $s4%. This effect stacks.\n\n\n\nThe scarab begins with $s3 applications of Hardened Carapace and naturally loses an application every $t2 sec over $d.", ua = "Панцир скарабея-розкольника спочатку перебуває в загартованому стані, що зменшує отриману шкоду на $s4%. Цей ефект накопичується.\n\n\n\nСкарабей починає з $s3 нашаруваннями Загартованого панцира і природним чином втрачає одне нашарування кожні $t2 с протягом $d." },
    { en = "Skeinspinner Takazj enters the void and exits at a nearby location.", ua = "Прядильниця Таказж входить у Порожнечу й виходить у сусідньому місці." },
    { en = "Takazj rips reality, knocking back all players in a frontal cone and inflicting $s2 Shadow damage.", ua = "Таказж розриває реальність, відкидаючи всіх гравців у фронтальному конусі й завдаючи $s2 шкоди від тіні." },
    { en = "Players are condemned by the court and filled with the essence of death, inflicting $460365s1 Chaos damage every $t1 sec. This aura persists through death.", ua = "Гравців засуджує двір і сповнює есенцією смерті, що завдає $460365s1 шкоди хаосом кожні $t1 с. Ця аура триває й після смерті." },
    { en = "Takazj flings sticky knots of webbing throughout the chamber, slowing players' movement speed by $454311s1% and and inflicting $454311s2 Physical damage every $454311t2 sec while within the area.\n\n\n\nThe central knot erupts when touched, inflicting $s1 Nature damage to players within $A1 yards and binding two players together in $@spellname440001.\n\n\n\nIf Anub'arash charges through strands of Binding Webs, he becomes Entangled.", ua = "Таказж розкидає липкі вузли павутини по всій залі, сповільнюючи швидкість руху гравців на $454311s1% і завдаючи $454311s2 од. фізичної шкоди кожні $454311t2 с тим, хто перебуває в зоні дії.\n\n\n\nЦентральний вузол вибухає від дотику, завдаючи $s1 од. шкоди Природи гравцям у радіусі $A1 ярдів і зв'язуючи двох гравців разом за допомогою $@spellname440001.\n\n\n\nЯкщо Ануб'араш проривається крізь пасма Зв'язувальної павутини, він стає Заплутаним." },
    { en = "Anub'arash rips spikes from the earth in a frontal cone, inflicting $s2 Nature damage to players in the area and applying Impaled.", ua = "Ануб'араш вириває шипи із землі в передньому конусі, завдаючи $s2 од. шкоди Природи гравцям у зоні дії та накладаючи Настромлення." },
    { en = "Takazj flings a poison globule at her current target, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d.", ua = "Таказж жбурляє отруйну кульку в поточну ціль, завдаючи $s1 од. шкоди Природи та додатково $s2 од. шкоди Природи кожні $t2 с протягом $d." },
    { en = "Takazj unleashes a barrage of void energy, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d. Applies $@spellname463461.", ua = "Таказж вивільняє шквал енергії Порожнечі, завдаючи $s1 шкоди від темної магії та додатково $s2 шкоди від темної магії кожні $t2 сек. протягом $d. Накладає $@spellname463461." },
    { en = "Anub'arash charges forward, inflicting $s1 Nature damage to any player in his path and knocking them away. \n\n\n\nUpon colliding with a wall, Anub'arash releases a deadly shockwave that inflicts $440178s1 Nature damage to all players.", ua = "Ануб'араш кидається вперед, завдаючи $s1 од. шкоди Природи будь-якому гравцю на своєму шляху й відкидаючи його. \n\n\n\nВрізавшись у стіну, Ануб'араш вивільняє смертоносну ударну хвилю, що завдає $440178s1 од. шкоди Природи всім гравцям." },
    { en = "Anub'arash releases a swarm of biting insects that inflicts $s1 Nature damage to all players every $442994t1 sec for $442994d. This effect grows in intensity over time.", ua = "Ануб'араш випускає рій кусючих комах, що завдає $s1 шкоди від сил природи всім гравцям кожні $442994t1 с протягом $442994d. Цей ефект з часом зростає в інтенсивності." },
    { en = "The spike impales the player, stunning them and inflicting $s1 Physical damage every $t1 sec until destroyed.", ua = "Шпичак протинає гравця, оглушуючи його та завдаючи $s1 фізичної шкоди кожні $t1 с, доки не буде знищений." },
    { en = "Sticky strands bind targets together, inflicting $464748s1 Physical damage every $t1 sec and reducing movement speed by $s2%. \n\n\n\nMoving $s1 yards apart snaps the strands.", ua = "Липкі пасма зв'язують цілі разом, завдаючи $464748s1 од. фізичної шкоди кожні $t1 с і зменшуючи швидкість руху на $s2%. \n\n\n\nЯкщо віддалитися на $s1 ярдів одне від одного, пасма рвуться." },
    { en = "Anub'arash and Skeinspinner Takazj are bound to each other by the will of Queen Ansurek, sharing health", ua = "Ануб'араш і Прядильниця Тенет Таказж пов'язані одне з одним волею королеви Ансурек і ділять спільне здоров'я" },
    { en = "An essence of paranoia that erupts after $s2 sec, applying $@spellname460359 to players affected by $@spellname455850.\n\n\n\nPlayers with the $@spellname455850 who touch an essence consume it and gain $@spellname460359.", ua = "Есенція параної, що вибухає за $s2 сек., накладаючи $@spellname460359 на гравців, які перебувають під дією $@spellname455850.\n\n\n\nГравці з ефектом $@spellname455850, що торкаються есенції, поглинають її й отримують $@spellname460359." },
    { en = "The void degenerates the target, inflicting $s1 Shadow damage every $t1 sec for $d. This effect stacks.\n\n\n\nAt $s2 stacks, $460365s2 Chaos damage is inflicted on the affected player.", ua = "Порожнеча розкладає ціль, завдаючи $s1 шкоди від тіні кожні $t1 с протягом $d. Цей ефект накопичується.\n\n\n\nПри $s2 стаках на враженого гравця завдається $460365s2 шкоди хаосом." },
    { en = "Anub'arash burrows into the ground then erupts from a nearby location, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec to all players for $d.", ua = "Ануб'араш заривається в землю, а потім вигулькує неподалік, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 сек. усім гравцям протягом $d." },
    { en = "The Stinging Swarm dissipates, inflicting $s1 Nature damgae to all players.", ua = "Жалкий рій розсіюється, завдаючи $s1 шкоди Природою всім гравцям." },
    { en = "Anub'arash pierces his current target, inflicting $s1 Physical damage and increasing damage inflicted by $@spellname438218 by $s2% for $d. This effect stacks.", ua = "Ануб'араш прохромлює свою поточну ціль, завдаючи $s1 фізичної шкоди та збільшуючи шкоду, завдану $@spellname438218, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Anub'arash unleashes a shockwave, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d. Applies $@spellname463464.", ua = "Ануб'араш вивільняє ударну хвилю, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 с протягом $d. Накладає $@spellname463464." },
    { en = "Anub'arash shields himself, absorbing $s2 damage. \n\n\n\nWhile the shield holds, Anub'arash unleashes a $@spellname460364 every $t1 sec and causes $@spellname443068 periodically throughout the chamber.", ua = "Ануб'араш огортає себе щитом, поглинаючи $s2 шкоди. \n\n\n\nПоки тримається щит, Ануб'араш вивільняє $@spellname460364 кожні $t1 с і час від часу спричиняє $@spellname443068 по всій палаті." },
    { en = "Takazj unleashes an entropic explosion, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d to players within $A1 yards.", ua = "Таказж вивільняє ентропійний вибух, завдаючи $s1 шкоди від тіні та додатково $s2 шкоди від тіні кожні $t2 сек. протягом $d гравцям у межах $A1 ярдів." },
    { en = "Skeinspinner Takazj unleashes a blast of entropy, inflicting an initial $s1 Shadow damage and $s2 Shadow damage every $t2 sec for $d.", ua = "Прядильниця Таказж вивільняє вибух ентропії, завдаючи спершу $s1 шкоди від тіні, а потім $s2 шкоди від тіні кожні $t2 сек. протягом $d." },
    { en = "Anub'arash launches a series of $s2 groupings of spikes, inflicting $s1 Nature damage and afflicting the players in the area with$@spellname449857.", ua = "Ануб'араш запускає серію з $s2 скупчень шипів, завдаючи $s1 шкоди від сил природи та накладаючи на гравців у зоні $@spellname449857." },
    { en = "Dark energy clings to the player, increasing damage taken from $@spellname460600 by $s1%. This effect stacks.", ua = "Темна енергія чіпляється до гравця, збільшуючи шкоду від $@spellname460600 на $s1%. Цей ефект накопичується." },
    { en = "An essence of rage that erupts after $s2 sec, applying $@spellname460281 to players affected by $@spellname455849.\n\n\n\nPlayers with the $@spellname455849  who touch an essence consume it and gain $@spellname460281.", ua = "Есенція люті, що вивергається через $s2 сек., накладаючи $@spellname460281 на гравців, уражених $@spellname455849.\n\n\n\nГравці з $@spellname455849, які торкаються есенції, поглинають її та здобувають $@spellname460281." },
    { en = "The ground heaves beneath the player, increasing damage taken from $@spellname460364 by $s1%. This effect stacks.", ua = "Земля здіймається під гравцем, збільшуючи шкоду від $@spellname460364 на $s1%. Цей ефект накопичується." },
    { en = "Anub'arash becomes entangled in the sticky strands, stunning him and increasing his damage taken by $s3% for $d.", ua = "Ануб'араш заплутується в липких нитках, що його оглушує та збільшує отримувану ним шкоду на $s3% протягом $d." },
    { en = "Takazj and Anub'arash choose members of their coterie, applying $@spellname455849 or $@spellname455850 respectively to players within $455849A yards.\n\n\n\nPlayers who do not gain a mark gain $@spellname455863.", ua = "Таказж і Ануб'араш обирають членів свого гурту, накладаючи відповідно $@spellname455849 або $@spellname455850 на гравців у межах $455849A ярдів.\n\n\n\nГравці, що не отримали мітки, отримують $@spellname455863." },
    { en = "The Shattershell Scarab's melee attacks shred their target's defenses, increasing the target's damage taken by $s1% for $d. This effect stacks.", ua = "Удари ближнього бою скарабея-скалкопанцира роздирають захист цілі, збільшуючи отримувану ціллю шкоду на $s1% протягом $d. Цей ефект накопичується." },
    { en = "The unquenchable rage torments the target, inflicting $s1 Fire damage every $t1 sec for $d. This effect stacks.\n\n\n\nAt $s2 stacks, $460365s2 Chaos damage is inflicted on the affected player.", ua = "Невгамовна лють терзає ціль, завдаючи $s1 шкоди вогнем кожні $t1 сек. протягом $d. Цей ефект накопичується.\n\n\n\nПри $s2 накопиченнях уражений гравець отримує $460365s2 хаотичної шкоди." },
    { en = "Skeinspinner Takazj leaps to a new location.", ua = "Прядильниця Таказж стрибає в нове місце." },
    { en = "Ansurek's diluted toxin inflicts $464646s1 Nature damage every $t1 sec for $d. This effect stacks.", ua = "Розведений токсин Ансурек завдає $464646s1 шкоди від сил природи кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Silk strands pull bladed webbing towards players, inflicting $439536s1 Nature damage to players struck and slowing them by $439536s2% for $439536d.", ua = "Шовкові нитки тягнуть до гравців клинкове павутиння, завдаючи $439536s1 шкоди від сил природи враженим гравцям і сповільнюючи їх на $439536s2% протягом $439536d." },
    { en = "Shadowy globs launch towards players, inflicting $s1 Shadow damage to players within $A1 yards of the impacts$?diff14|diff17[.][ and forming $@spellname443399.]", ua = "Тінисті згустки злітають до гравців, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів від місць влучання$?diff14|diff17[.][ й утворюючи $@spellname443399.]" },
    { en = "$?diff220[Ansurek roots all players in webbing, inflicting $439865s1 Nature damage and an additional $439852s1 Nature damage every $439829t1 sec while webbed.][Ansurek roots all players in webbing, inflicting $439865s1 Nature damage to players within $439865A1 yards of the webbing's impact. This webbing inflicts $439852s1 Nature damage to its victims every $439829t1 sec until destroyed.]$?diff14|diff17|diff220[][\n\n\n\nUpon destruction, the webbing leaves behind $@spellname441958.]", ua = "$?diff220[Ансурек прикоренює всіх гравців павутинням, завдаючи $439865s1 шкоди від сил природи та додатково $439852s1 шкоди від сил природи кожні $439829t1 сек., поки вони обплутані.][Ансурек прикоренює всіх гравців павутинням, завдаючи $439865s1 шкоди від сил природи гравцям у межах $439865A1 ярдів від місця влучання павутиння. Це павутиння завдає своїм жертвам $439852s1 шкоди від сил природи кожні $439829t1 сек., доки не буде знищене.]$?diff14|diff17|diff220[][\n\n\n\nПісля знищення павутиння лишає по собі $@spellname441958.]" },
    { en = "Ansurek devours her victim, inflicting $s1 Physical damage.", ua = "Ансурек пожирає свою жертву, завдаючи $s1 фізичної шкоди." },
    { en = "Web shackles connect to players, slowing them by $s2% and inflicting $441867s1 Nature damage every $t1 sec until the shackles are destroyed. The strength of this effect increases over time.\n\n\n\nThe shackles trap any player they touch in a $@spellname441872. Destroying a shackle frees its cocooned players.", ua = "Павутинні пута з'єднуються з гравцями, сповільнюючи їх на $s2% і завдаючи $441867s1 шкоди від сил природи кожні $t1 сек., доки пута не буде знищено. Сила цього ефекту зростає з часом.\n\n\n\nПута полонять у $@spellname441872 кожного гравця, до якого торкаються. Знищення пут звільняє закоконованих гравців." },
    { en = "Darkness clings to the ground, inflicting $s1 Shadow damage every $t1 sec to players within it.", ua = "Темрява чіпляється до землі, завдаючи $s1 шкоди від тіні кожні $t1 сек. гравцям усередині неї." },
    { en = "Void conduits tear open, inflicting $450850s1 Shadow damage to players within $450850A1 yards$?diff14|diff17[.][ and launching $@spellname444507.]\n\n\n\nThe conduits teleport players between them when touched, inflicting $444456s2 Shadow damage$?diff15|diff16[ and applying $@spellname455387.][.]\n\n\n\nWhen these conduits destabilize, a $@spellname444502 occurs.", ua = "Провідники Порожнечі розриваються, завдаючи $450850s1 шкоди від тіні гравцям у межах $450850A1 ярдів$?diff14|diff17[.][ і запускаючи $@spellname444507.]\n\n\n\nПровідники телепортують гравців між собою при дотику, завдаючи $444456s2 шкоди від тіні$?diff15|diff16[ та накладаючи $@spellname455387.][.]\n\n\n\nКоли ці провідники дестабілізуються, відбувається $@spellname444502." },
    { en = "Ansurek connects $@spellname447170 to players and violently yanks them towards her, inflicting $450345s1 Nature damage$?diff16[ and leaving $@spellname460182 underneath them][].", ua = "Ансурек з'єднує $@spellname447170 з гравцями та різко притягує їх до себе, завдаючи $450345s1 шкоди від сил природи$?diff16[ і лишаючи $@spellname460182 під ними][]." },
    { en = "The Chamber Expeller teleports away and then fires a cosmic beam towards a player, inflicting $451601s1 Shadow damage to players hit$?diff17[.][ and knocking them away.]", ua = "Виганяч зали телепортується геть, а потім випускає космічний промінь у гравця, завдаючи $451601s1 шкоди від тіні враженим гравцям$?diff17[.][ і відкидаючи їх.]" },
    { en = "A cocoon fully envelops the victim, stunning them.", ua = "Кокон повністю огортає жертву, оглушуючи її." },
    { en = "The Chamber Guardian inflicts $451408s1 Physical damage and $451410s1 Shadow damage to its target$?diff17|diff220[.][, knocking them away.]$?diff220[][\n\n\n\nThis ability ejects $@spellname460315.]", ua = "Охоронець зали завдає своїй цілі $451408s1 фізичної шкоди та $451410s1 шкоди від тіні$?diff17|diff220[.][, відкидаючи її.]$?diff220[][\n\n\n\nЦя здібність викидає $@spellname460315.]" },
    { en = "Ansurek shoots acid at players, inflicting $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d.", ua = "Ансурек оббризкує гравців кислотою, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 сек. протягом $d." },
    { en = "Ansurek eradicates players with burning acid, inflicting $449943s1 Nature damage to all players and an additional $449945s1 Nature damage every $449944t1 sec.", ua = "Ансурек винищує гравців пекучою кислотою, завдаючи $449943s1 шкоди від сил природи всім гравцям та додатково $449945s1 шкоди від сил природи кожні $449944t1 сек." },
    { en = "Gloom Hatchlings burst from the infested victim, inflicting $443718s1 Shadow damage to all players within $443718A1 yards.", ua = "З ураженої жертви вириваються Похмурі вилупки, завдаючи $443718s1 шкоди від тіні всім гравцям у межах $443718A1 ярдів." },
    { en = "Rolling waves of poison inflict $s1 Nature damage to players in their paths, knocking them away and applying $@spellname447456.", ua = "Котливі хвилі отрути завдають $s1 шкоди від сил природи гравцям на своєму шляху, відкидаючи їх і накладаючи $@spellname447456." },
    { en = "Dark fragments of energy inflict $s1 Shadow damage to players within $A1 yards of the impacts, knocking them away.", ua = "Темні уламки енергії завдають $s1 шкоди від тіні гравцям у межах $A1 ярдів від місць влучання, відкидаючи їх." },
    { en = "Ansurek lets forth a ghastly shriek, inflicting $444833s1 Shadow damage to all players and calling Summoned Acolytes to her aid.$?diff14|diff17|diff220[][\n\n\n\nUpon death, they become $@spellname445152.]", ua = "Ансурек видає моторошний вереск, завдаючи $444833s1 шкоди від тіні всім гравцям і скликаючи Прикликаних послушників собі на допомогу.$?diff14|diff17|diff220[][\n\n\n\nПісля смерті вони перетворюються на $@spellname445152.]" },
    { en = "Ansurek radiates acidic fumes, inflicting $440608s1 Nature damage to all players every $t1 sec.", ua = "Ансурек випромінює кислотні випари, завдаючи $440608s1 шкоди від сил природи всім гравцям кожні $t1 сек." },
    { en = "Ansurek unleashes a ring of venom, inflicting $438947s1 Nature damage to players within $438947A1 yards.\n\n\n\nThe ring expands, inflicting $454019s1 Nature damage every $438804t1 sec for $438804d to players that touch it and slowing them by $438804s2%.$?diff17|diff220[][\n\n\n\n$@spellname441556 occurs if the ring touches $@spellname438846.]", ua = "Ансурек вивільняє кільце отрути, завдаючи $438947s1 шкоди від сил природи гравцям у межах $438947A1 ярдів.\n\n\n\nКільце розширюється, завдаючи $454019s1 шкоди від сил природи кожні $438804t1 сек. протягом $438804d гравцям, які до нього торкаються, і сповільнюючи їх на $438804s2%.$?diff17|diff220[][\n\n\n\n$@spellname441556 відбувається, якщо кільце торкається $@spellname438846.]" },
    { en = "The caster shares a dark connection with others of its type, echoing $s1% of damage taken to the others.\n\n\n\nIf close together, these creatures resonate, becoming immune to all damage and pulsing $462698s1 Shadow damage to all players every $453990t3 sec. This damage increases by $462699s1% with each pulse.", ua = "Той, хто творить, поділяє темний зв'язок з іншими істотами свого типу, відлунюючи $s1% отриманої шкоди на інших.\n\n\n\nЯкщо вони близько одна до одної, ці істоти резонують, стаючи несприйнятливими до всієї шкоди й пульсуючи $462698s1 шкодою від тіні всім гравцям кожні $453990t3 с. Ця шкода зростає на $462699s1% з кожним пульсом." },
    { en = "The Ascended Voidspeaker's essence destabilizes shortly after death, inflicting $s1 Shadow damage to players within $A1 yards and knocking them away.\n\n\n\nThis explosion causes $@spellname443403 to expand rapidly from the epicenter.", ua = "Есенція Вознесеного речника Порожнечі дестабілізується невдовзі після смерті, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів і відкидаючи їх.\n\n\n\nЦей вибух змушує $@spellname443403 стрімко розширюватися від епіцентру." },
    { en = "Cosmic spheres inflict $s1 Shadow damage to players in their paths, knocking them away.", ua = "Космічні сфери завдають $s1 шкоди від тіні гравцям на своєму шляху, відкидаючи їх." },
    { en = "Ansurek violently yanks all players towards her, inflicting $447440s1 Nature damage$?diff16[ and leaving $@spellname460182 underneath them][].", ua = "Ансурек різко притягує всіх гравців до себе, завдаючи $447440s1 шкоди від сил природи$?diff16[ і лишаючи $@spellname460182 під ними][]." },
    { en = "The essence of Ansurek's acolyte vaporizes, inflicting $460354s1 Shadow damage to all players and slowing their movement speed by $s1% for $d. This effect stacks.\n\n\n\nAnsurek consumes this vapor, increasing her damage done by $445880s1% for $445880d. This effect stacks.", ua = "Есенція послушника Ансурек випаровується, завдаючи $460354s1 шкоди від тіні всім гравцям і сповільнюючи їхню швидкість пересування на $s1% протягом $d. Цей ефект накопичується.\n\n\n\nАнсурек поглинає цю пару, збільшуючи завдавану нею шкоду на $445880s1% протягом $445880d. Цей ефект накопичується." },
    { en = "Ansurek's web threads grip all players, pulling them towards her frothing maw. This pull force increases over time.", ua = "Павутинні нитки Ансурек охоплюють усіх гравців, тягнучи їх до її піняви пащі. Сила цього притягання зростає з часом." },
    { en = "The $@spellname460366 afflicts transported players with dark energy, inflicting $455099s1 Shadow damage every $447967t1 sec to players within $455099A1 yards of the victims for $447967d.\n\n\n\nUpon removal, a $@spellname447983 occurs and $@spellname443403 forms.", ua = "$@spellname460366 уражає перенесених гравців темною енергією, завдаючи $455099s1 шкоди від тіні щосекунди $447967t1 гравцям у радіусі $455099A1 м від жертв протягом $447967d.\n\n\n\nПісля зняття спрацьовує $@spellname447983 й утворюється $@spellname443403." },
    { en = "Entropic power distorts the player's dimensional presence, preventing them from entering a $@spellname460366 for $d.", ua = "Ентропійна сила спотворює вимірну присутність гравця, не даючи йому увійти в $@spellname460366 протягом $d." },
    { en = "The acolyte's essence melds with the player, increasing damage taken from $@spellname445152 by $s1% for $d.", ua = "Есенція аколіта зливається з гравцем, збільшуючи шкоду від $@spellname445152 на $s1% на $d." },
    { en = "Ansurek injects her current target with shadow-infused egg sacs, inflicting $443655s1 Shadow damage and $443654s1 Physical damage. Additionally, the victims suffer $443657s1 Shadow damage every $443656t1 sec for $443656d.\n\n\n\nUpon expiration, the sacs erupt in an $@spellname443667.", ua = "Ансурек впорскує своїй поточній цілі насичені тінню яйцеві мішки, завдаючи $443655s1 шкоди від тіні та $443654s1 фізичної шкоди. Крім того, жертви зазнають $443657s1 шкоди від тіні кожні $443656t1 с протягом $443656d.\n\n\n\nКоли час спливає, мішки розриваються, спричиняючи $@spellname443667." },
    { en = "$?diff17[When a player touches the froth, it inflicts $455953s1 Nature damage to them and knocks them into the air.\n\n\n\n$@spellname437417 disperses froth into a pool of $@spellname437078 and launches a froth glob that splatters into $@spellname438481.][When a player touches the froth, it bursts, afflicting them with $@spellname451278.]$?diff17[][\n\n\n\nThis burst launches players within $452277A1 yards into the air and inflicts $464642s1 Nature damage to all players]$?diff15|diff16[, applying $@spellname464638][]$?diff14[.][]$?diff16[ and $@spellname460133.][]$?diff15[.][]$?diff17[][ A glob of venom also launches, splattering into $@spellname438481.\n\n\n\n$@spellname437417 disperses burst froth into a pool of $@spellname437078.]", ua = "$?diff17[Коли гравець торкається піни, вона завдає йому $455953s1 шкоди від сил природи й підкидає в повітря.\n\n\n\n$@spellname437417 розсіює піну в калюжу $@spellname437078 й запускає згусток піни, що розбризкується на $@spellname438481.][Коли гравець торкається піни, вона лопає, накладаючи на нього $@spellname451278.]$?diff17[][\n\n\n\nЦей вибух підкидає гравців у радіусі $452277A1 м у повітря й завдає $464642s1 шкоди від сил природи всім гравцям]$?diff15|diff16[, накладаючи $@spellname464638][]$?diff14[.][]$?diff16[ і $@spellname460133.][]$?diff15[.][]$?diff17[][ Також запускається згусток отрути, що розбризкується на $@spellname438481.\n\n\n\n$@spellname437417 розсіює пінний вибух у калюжу $@spellname437078.]" },
    { en = "$?diff220[Ansurek forms silken spikes that drop onto players, inflicting $441213s1 Nature damage.][Ansurek forms silken spikes that drop onto marked players, inflicting $441213s1 Nature damage to all players, reduced with distance.]$?diff14|diff17|diff220[][\n\n\n\nThe impacts form $@spellname441859.]", ua = "$?diff220[Ансурек утворює шовкові шипи, що падають на гравців, завдаючи $441213s1 шкоди від сил природи.][Ансурек утворює шовкові шипи, що падають на позначених гравців, завдаючи $441213s1 шкоди від сил природи всім гравцям; шкода зменшується з відстанню.]$?diff14|diff17|diff220[][\n\n\n\nУдари утворюють $@spellname441859.]" },
    { en = "Ansurek's web threads inflict $447175s1 Nature damage every $t1 sec$?diff14|diff17[.][ to players within $447175A1 yards of each victim.]", ua = "Павутинні нитки Ансурек завдають $447175s1 шкоди від сил природи кожні $t1 с$?diff14|diff17[.][ гравцям у радіусі $447175A1 м від кожної жертви.]" },
    { en = "Ansurek injects her current target with digestive juices, inflicting $436799s1 Nature damage and $440900s1 Physical damage.\n\n\n\nThis injection inflicts an additional $453609s1 Nature damage every $436800t2 sec for $436800d and causes the victim to take $436800s1% increased Physical damage.\n\n\n\nPoison overflows from Ansurek when she injects her target, causing an $@spellname441084.", ua = "Ансурек впорскує своїй поточній цілі травні соки, завдаючи $436799s1 шкоди від сил природи та $440900s1 фізичної шкоди.\n\n\n\nЦе впорскування завдає додатково $453609s1 шкоди від сил природи кожні $436800t2 с протягом $436800d і змушує жертву зазнавати на $436800s1% більше фізичної шкоди.\n\n\n\nКоли Ансурек впорскує отруту своїй цілі, та переливається через край, спричиняючи $@spellname441084." },
    { en = "$?diff17[Shadowy spiderlings appear, attacking nearby players.][Shadowy spiderlings rush towards Ansurek. If they reach her, she devours them, inflicting $443723s1 Shadow damage to all players and increasing her damage done by $443726s1% for $443726d.]$?diff14|diff17[][\n\n\n\nUpon death, these spiderlings leak $@spellname443403.]", ua = "$?diff17[З'являються тіньові павучки, що нападають на гравців поблизу.][Тіньові павучки кидаються до Ансурек. Якщо досягають її, вона пожирає їх, завдаючи $443723s1 шкоди від тіні всім гравцям і збільшуючи завдану нею шкоду на $443726s1% на $443726d.]$?diff14|diff17[][\n\n\n\nГинучи, ці павучки виділяють $@spellname443403.]" },
    { en = "Ansurek tears ravenously into her current target every $t2 sec for $d, inflicting $443361s1 Physical damage with each strike and increasing Physical damage taken by $443342s2% for $443342d. This effect stacks.\n\n\n\nThese strikes cause $@spellname443396 and inflict $443364s1 Shadow damage to all players.$?diff14|diff17[][ An additional $443364s3% of their Physical damage also occurs as Shadow damage to all players.]", ua = "Ансурек ненажерливо роздирає свою поточну ціль кожні $t2 с протягом $d, завдаючи $443361s1 фізичної шкоди кожним ударом і збільшуючи отримувану фізичну шкоду на $443342s2% на $443342d. Цей ефект накопичується.\n\n\n\nЦі удари спричиняють $@spellname443396 й завдають $443364s1 шкоди від тіні всім гравцям.$?diff14|diff17[][ Додатково $443364s3% їхньої фізичної шкоди завдається як шкода від тіні всім гравцям.]" },
    { en = "The Devoted Worshipper unleashes lethal cosmic power, inflicting $448460s1 Shadow damage to players within $448460A1 yards and an additional $448464s1 Shadow damage every $448461t1 sec.\n\n\n\nThe explosion forms $@spellname443403.", ua = "Відданий Поклонник вивільняє смертоносну космічну силу, завдаючи $448460s1 шкоди від тіні гравцям у радіусі $448460A1 м і додатково $448464s1 шкоди від тіні кожні $448461t1 с.\n\n\n\nВибух утворює $@spellname443403." },
    { en = "Ansurek's volatile acid absorbs into the victim, inflicting $464736s1 Nature damage every $t1 sec for $d.\n\n\n\nUpon expiration, the toxin detonates, $?diff15|diff16[applying $@spellname464628 to the victim and ][]inflicting $464640s1 Nature damage to players within $464640A1 yards.", ua = "Нестабільна кислота Ансурек убирається в жертву, завдаючи $464736s1 шкоди від сил природи кожні $t1 с протягом $d.\n\n\n\nКоли час спливає, токсин детонує, $?diff15|diff16[накладаючи на жертву $@spellname464628 й ][]завдаючи $464640s1 шкоди від сил природи гравцям у радіусі $464640A1 м." },
    { en = "Shadowy gateways deploy Ansurek's forces and then explode, inflicting $460369s1 Shadow damage to players within $460369A1 yards. \n\n\n\nTraveling through a gateway disrupts the explosion, but inflicts $460213s1 Shadow damage to the traveler and afflicts them with both $@spellname447967 and $@spellname460218.", ua = "Тіньові портали розгортають сили Ансурек, а потім вибухають, завдаючи $460369s1 шкоди від тіні гравцям у радіусі $460369A1 м. \n\n\n\nПрохід крізь портал зриває вибух, але завдає $460213s1 шкоди від тіні мандрівникові й накладає на нього і $@spellname447967, і $@spellname460218." },
    { en = "$?diff220[The creature inflicts $s1 Shadow damage to a player.][The Ascended Voidspeaker annihilates a player with shadowy energy, inflicting $s1 Shadow damage.]", ua = "$?diff220[Істота завдає $s1 шкоди від тіні гравцю.][Піднесений Речник Порожнечі знищує гравця тіньовою енергією, завдаючи $s1 шкоди від тіні.]" },
    { en = "A toxic splatter inflicts $464673s1 Nature damage to players within $464673A1 yards of the impact.\n\n\n\nWaves of poison roll outward, inflicting $s1 Nature damage to players in their paths and knocking them away.", ua = "Токсичне розбризкування завдає $464673s1 шкоди від сил природи гравцям у радіусі $464673A1 м від удару.\n\n\n\nХвилі отрути котяться назовні, завдаючи $s1 шкоди від сил природи гравцям на своєму шляху й відкидаючи їх." },
    { en = "The Chamber Acolyte inflicts $s1 Shadow damage to players within $A1 yards.", ua = "Аколіт Палати завдає $s1 шкоди від тіні гравцям у радіусі $A1 м." },
    { en = "The Caustic Skitterer's attacks corrode the target, increasing damage taken by $449236s1% for $449236d. This effect stacks.", ua = "Атаки Їдкого Дріботуна роз'їдають ціль, збільшуючи отримувану шкоду на $449236s1% на $449236d. Цей ефект накопичується." },
    { en = "$@spellname438846 vaporizes, inflicting $451315s1 Nature damage to all players and an additional $441703s1 Nature damage every $t1 sec for $d. This effect stacks.", ua = "$@spellname438846 випаровується, завдаючи $451315s1 шкоди від сил природи всім гравцям і додатково $441703s1 шкоди від сил природи кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "The Summoned Acolyte's shadowy barrier absorbs $s1 damage and prevents crowd controlling effects.", ua = "Тіньовий бар'єр Викликаного Аколіта поглинає $s1 шкоди й запобігає ефектам контролю натовпу." },
    { en = "Ansurek's acid inflicts $s1 Nature damage every $t1 sec to players within it.", ua = "Кислота Ансурек завдає $s1 шкоди від сил природи кожні $t1 с гравцям усередині неї." },
    { en = "The conduit collapses, inflicting $s1 Shadow damage to players within $A1 yards. \n\n\n\nThis destabilization launches $@spellname444507 and forms $@spellname443403.", ua = "Канал руйнується, завдаючи $s1 шкоди від тіні гравцям у радіусі $A1 м. \n\n\n\nЦя дестабілізація запускає $@spellname444507 й утворює $@spellname443403." },
    { en = "$?diff17[Ansurek launches a toxin towards players, inflicting $456012s1 Nature damage to players within $456012A1 yards of the impact and forming $@spellname438846.][Ansurek afflicts players with a toxin, inflicting $451324s1 Nature damage every $437586t1 sec for $437586d to players within $451324A1 yards.\n\n\n\nUpon expiration, the toxin forms into $@spellname438846, inflicting $451321s1 Nature damage to players within $451321A1 yards and knocking them away.]", ua = "$?diff17[Ансурек запускає токсин у гравців, завдаючи $456012s1 шкоди від сил природи гравцям у радіусі $456012A1 м від удару й утворюючи $@spellname438846.][Ансурек накладає на гравців токсин, завдаючи $451324s1 шкоди від сил природи кожні $437586t1 с протягом $437586d гравцям у радіусі $451324A1 м.\n\n\n\nКоли час спливає, токсин формується в $@spellname438846, завдаючи $451321s1 шкоди від сил природи гравцям у радіусі $451321A1 м і відкидаючи їх.]" },
    { en = "Ansurek radiates dreadful energy, inflicting $445275s1 Shadow damage every $t1 sec to all players. This damage permanently increases by $445268s~1% whenever $@spellname451802 open.\n\n\n\nIf she casts $@spellname445422 with $s~2 applications of this effect, her cosmic energy overflows, granting her $@spellname451832.", ua = "Ансурек випромінює жахливу енергію, завдаючи $445275s1 шкоди від тіні кожні $t1 с усім гравцям. Ця шкода назавжди зростає на $445268s~1%, щоразу як відкриваються $@spellname451802.\n\n\n\nЯкщо вона творить $@spellname445422 з $s~2 нашаруваннями цього ефекту, її космічна енергія переливається через край, даруючи їй $@spellname451832." },
    { en = "Abyssal energy explodes after $d, inflicting $455416s1 Shadow damage to players within $455416A1 yards.", ua = "Безодняна енергія вибухає за $d, завдаючи $455416s1 шкоди від тіні гравцям у радіусі $455416A1 м." },
    { en = "Abyssal fragments inflict $s1 Shadow damage to players in their paths, knocking them away.", ua = "Безодняні уламки завдають $s1 шкоди від тіні гравцям на своєму шляху, відкидаючи їх." },
    { en = "The Devoted Worshipper periodically afflicts players with dark energy, inflicting $455099s1 Shadow damage every $447967t1 sec to$?diff16[ players within $455099A1 yards of][] the victims for $447967d.$?diff14|diff17[][\n\n\n\nUpon removal, a $@spellname447983 occurs]$?diff16[ and $@spellname443403 forms.][]$?diff15[.][]", ua = "Відданий Поклонник періодично накладає на гравців темну енергію, завдаючи $455099s1 шкоди від тіні кожні $447967t1 с$?diff16[ гравцям у радіусі $455099A1 м від][] жертв протягом $447967d.$?diff14|diff17[][\n\n\n\nПісля зняття стається $@spellname447983]$?diff16[ і утворюється $@spellname443403.][]$?diff15[.][]" },
    { en = "The Summoned Acolyte inflicts $s1 Shadow damage to all players.$?diff220[][ Each successful cast increases its damage done by $445915s1%.]", ua = "Викликаний Аколіт завдає $s1 шкоди від тіні всім гравцям.$?diff220[][ Кожне успішне прочитання збільшує завдану ним шкоду на $445915s1%.]" },
    { en = "Ansurek splashes venom, slowing all players by $447532s1% and increasing damage taken from $@spellname447411 by $447532s2%. This effect stacks.\n\n\n\nAdditionally, each splash ejects $@spellname447492.", ua = "Ансурек розбризкує отруту, сповільнюючи всіх гравців на $447532s1% і збільшуючи шкоду від $@spellname447411 на $447532s2%. Цей ефект накопичується.\n\n\n\nКрім того, кожне розбризкування викидає $@spellname447492." },
    { en = "Ansurek consumes the essence of her victim, inflicting $s1 Shadow damage.", ua = "Ансурек поглинає есенцію своєї жертви, завдаючи $s1 шкоди від тіні." },
    { en = "The essence absorbs into a player when touched, inflicting $451848s1 Shadow damage and an additional $445162s1 Shadow damage every $445152t1 sec$?diff14|diff17[.\n\n\n\nTraveling through an $@spellname443915 removes this affliction.][]$?diff15[.\n\n\n\nTraveling through an $@spellname443915 while afflicted destabilizes the conduit and removes this affliction.\n\n\n\nUpon removal, the victim gets $@spellname446012.][]$?diff16[ for $d.\n\n\n\nUpon expiration, the victim gets $@spellname446012 and the essence reforms.\n\n\n\nTraveling through an $@spellname443915 while afflicted destabilizes the conduit.][]", ua = "Есенція вбирається в гравця при дотику, завдаючи $451848s1 шкоди від тіні й додатково $445162s1 шкоди від тіні кожні $445152t1 с$?diff14|diff17[.\n\n\n\nПрохід крізь $@spellname443915 знімає це послаблення.][]$?diff15[.\n\n\n\nПрохід крізь $@spellname443915 під час дії послаблення дестабілізує канал і знімає це послаблення.\n\n\n\nПісля зняття жертва отримує $@spellname446012.][]$?diff16[ протягом $d.\n\n\n\nКоли час спливає, жертва отримує $@spellname446012, а есенція формується знову.\n\n\n\nПрохід крізь $@spellname443915 під час дії послаблення дестабілізує канал.][]" },
    { en = "Ansurek attaches $@spellname447170 to all players and gains a web shield that absorbs $447207s1 damage.\n\n\n\nWhile shielded, she assaults players with $@spellname447456 and occasionally yanks players towards her, devouring any that get within $447140s1 yards.", ua = "Ансурек чіпляє $@spellname447170 до всіх гравців і отримує павутинний щит, що поглинає $447207s1 шкоди.\n\n\n\nПоки щит діє, вона атакує гравців $@spellname447456 й час від часу притягує гравців до себе, пожираючи кожного, хто опиняється в радіусі $447140s1 м." },
    { en = "Toxic particles cling to all players, increasing damage taken from $@spellname438846 by $s1% for $d. This effect stacks.", ua = "Токсичні часточки чіпляються до всіх гравців, збільшуючи шкоду від $@spellname438846 на $s1% на $d. Цей ефект накопичується." },
    { en = "Sticky webbing reduces movement speed by $s2% and inflicts $s1 Nature damage every $t1 sec to players within it.", ua = "Липке павутиння зменшує швидкість пересування на $s2% і завдає $s1 шкоди від сил природи кожні $t1 с гравцям усередині нього." },
    { en = "Ansurek feasts on a chunk of her current target's flesh, inflicting $s1 Physical damage$?diff17[][ and causing absorption of the next $455404s1 healing].$?diff14|diff17[][\n\n\n\nThis wound absorbs additional healing equal to $455404s2% of the Physical damage done.]", ua = "Ансурек ласує шматком плоті своєї поточної цілі, завдаючи $s1 фізичної шкоди$?diff17[][ і спричиняючи поглинання наступних $455404s1 зцілення].$?diff14|diff17[][\n\n\n\nЦя рана поглинає додаткове зцілення, що дорівнює $455404s2% завданої фізичної шкоди.]" },
    { en = "The Devoted Worshipper exchanges its health for an absorption shield and protects Ansurek from all damage.", ua = "Відданий Поклонник обмінює своє здоров'я на поглинальний щит і захищає Ансурек від усієї шкоди." },
    { en = "Ansurek draws in a ring of cosmic energy, inflicting $445820s1 Shadow damage every $445818t1 sec for $445818d to players that touch it and slowing them by $445818s2%. She pulls players towards her with $@spellname445623, consuming victims within $s1 yards.\n\n\n\nAnsurek also consumes living Summoned Acolytes upon casting this ability, causing $@spellname445877.", ua = "Ансурек стягує кільце космічної енергії, завдаючи $445820s1 шкоди від тіні кожні $445818t1 с протягом $445818d гравцям, які торкаються його, і сповільнюючи їх на $445818s2%. Вона притягує гравців до себе за допомогою $@spellname445623, пожираючи жертв у радіусі $s1 м.\n\n\n\nАнсурек також пожирає живих Викликаних Аколітів, творячи цю здібність, що спричиняє $@spellname445877." },
    { en = "Darkness erupts from the victim, inflicting $s1 Shadow damage to players within $A1 yards.", ua = "З жертви вибухає темрява, завдаючи $s1 шкоди від тіні гравцям у радіусі $A1 м." },
    { en = "$?diff17[Ansurek launches dark energy towards players, inflicting $456815s1 Shadow damage to players within $456815A1 yards of the impacts and forming $@spellname451802.][Ansurek afflicts players with dark energy, inflicting $443906s1 Shadow damage every $443903t1 sec for $443903d to players within $443906A1 yards.\n\n\n\nUpon expiration, the energy ruptures into an $@spellname443915, inflicting $443907s1 Shadow damage to players within $443906A1 yards and knocking them away.]", ua = "$?diff17[Ансурек запускає темну енергію в гравців, завдаючи $456815s1 шкоди від тіні гравцям у радіусі $456815A1 м від ударів і утворюючи $@spellname451802.][Ансурек накладає на гравців темну енергію, завдаючи $443906s1 шкоди від тіні кожні $443903t1 с протягом $443903d гравцям у радіусі $443906A1 м.\n\n\n\nКоли час спливає, енергія розривається на $@spellname443915, завдаючи $443907s1 шкоди від тіні гравцям у радіусі $443906A1 м і відкидаючи їх.]" },
    { en = "The victim's organs corrode, increasing damage taken from $@spellname451278 by $s1% for $d.", ua = "Органи жертви роз'їдаються, через що шкода від $@spellname451278 зростає на $s1% на $d." },
    { en = "All $@spellname443403 rapidly expands and Ansurek recasts $@spellname445422 indefinitely.", ua = "Усі $@spellname443403 стрімко розростаються, а Ансурек безкінечно перетворює $@spellname445422." },
    { en = "Acidic venom explodes outward from Ansurek, $?diff15|diff16[inflicting $460782s1 Nature damage to all players and ][]forming a large pool of $@spellname437078 underneath her.\n\n\n\nGlobs of her venom launch towards players, inflicting $s1 Nature damage to players within $A1 yards of the impacts$?diff14|diff17[.][ and forming $@spellname437078.]", ua = "З Ансурек назовні вибухає їдка отрута, $?diff15|diff16[завдаючи $460782s1 шкоди від сил природи всім гравцям і ][]утворюючи під нею велику калюжу $@spellname437078.\n\n\n\nГрудки її отрути летять у бік гравців, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів від місць влучань$?diff14|diff17[.][ та утворюючи $@spellname437078.]" },
    { en = "A viscous froth covers the player for $d and then detonates, causing them to suffer $437632s1 Nature damage. This effect stacks.\n\n\n\nEach player within $452277A1 yards of a bursting $@spellname438846 reduces this affliction's applications.$?diff16[ \n\n\n\nUpon expiration, the victim receives $@spellname464643 with matching applications.][]", ua = "Густа піна вкриває гравця на $d, а тоді детонує, завдаючи йому $437632s1 шкоди від сил природи. Цей ефект накладається стосами.\n\n\n\nКожен гравець у межах $452277A1 ярдів від $@spellname438846, що лопається, зменшує кількість накладень цього послаблення.$?diff16[ \n\n\n\nПісля завершення жертва отримує $@spellname464643 з відповідною кількістю накладень.][]" },
    { en = "The Ascended Voidspeaker inflicts $448006s1 Shadow damage every $t1 sec to$?diff220[ all players][ players within $448006A1 yards]$?diff14|diff17|diff220[.][ and periodically forms $@spellname448176.\n\n\n\nThe orbs eject after a short delay, inflicting $451459s1 Shadow damage to players within $451459A1 yards of the ejection's epicenter.]$?diff220[][\n\n\n\nUpon the Ascended Voidspeaker's death, $@spellname448046 occurs.]", ua = "Піднесений речник Порожнечі завдає $448006s1 шкоди від тіні кожні $t1 сек.$?diff220[ всім гравцям][ гравцям у межах $448006A1 ярдів]$?diff14|diff17|diff220[.][ та періодично утворює $@spellname448176.\n\n\n\nКулі викидаються після короткої затримки, завдаючи $451459s1 шкоди від тіні гравцям у межах $451459A1 ярдів від епіцентру викиду.]$?diff220[][\n\n\n\nПісля загибелі піднесеного речника Порожнечі стається $@spellname448046.]" },
    { en = "The Geargrinder launches oil at targeted players, $?DIFF15|DIFF16[forming an $@spellname459679 at their location and ][]dousing players within $A1 yards of the impact with oil, inflicting $s1 Nature damage every $t1 sec for $d.", ua = "Шестернокрут запускає нафту в обраних гравців, $?DIFF15|DIFF16[утворюючи $@spellname459679 в їхньому розташуванні та ][]обливаючи нафтою гравців у радіусі $A1 м від місця удару, завдаючи $s1 шкоди від сил природи щосекунди $t1 протягом $d." },
    { en = "The Geargrinder creates a pool of noxious oil that lasts for up to $d. Players within the pool suffer $459683s1 Nature damage every $459683t1 sec and have their movement speed reduced by $459683s2%. Additionally, players within the effect slip and slide along the ground.\n\n\n\nGeargrinder Bikes passing over the $@spellname459679 spin out, stunning the rider for $459685d.", ua = "Шестернедробар створює калюжу їдкої нафти, що тримається до $d. Гравці в калюжі зазнають $459683s1 шкоди від сил природи кожні $459683t1 сек, а їхня швидкість пересування знижується на $459683s2%. Окрім того, гравці в зоні дії послизаються й ковзають по землі.\n\n\n\nМотоцикли Шестернедробарів, що проїжджають крізь $@spellname459679, втрачають керування, оглушуючи водія на $459685d." },
    { en = "The player who catches an $@spellname1216740 becomes soaked in oil, increasing damage taken from $@spellname1216740 by $s3% for $d.", ua = "Гравець, який ловить $@spellname1216740, просочується нафтою, через що шкода від $@spellname1216740 зростає на $s3% на $d." },
    { en = "The Support Rig inspires efficiency in nearby pit crew members, making Pit Mechanics within $473638s1 yards immune to crowd control effects.", ua = "Допоміжна установка надихає сусідній екіпаж ями на ефективність, роблячи Механіків Ями в межах $473638s1 м несприйнятливими до ефектів контролю." },
    { en = "The Geargrinder calls in Geargrinder Bikers to aid it in battle.", ua = "Шестернедробар прикликає байкерів Шестернедробара, щоб ті допомогли йому в бою." },
    { en = "The Geargrinder releases smog that suffocates all players for $d, inflicting $s1 Shadow damage every $t1 sec. This increases in intensity by $468149s1% with every cast.", ua = "Шестернедробар випускає смог, що душить усіх гравців на $d, завдаючи $s1 шкоди від тіні кожні $t1 сек. Інтенсивність зростає на $468149s1% з кожним застосуванням." },
    { en = "Durable plating protects the Geargrinder, allowing it to slowly gain energy.\n\n\n\nWhen all applications of $@spellname466615 are removed, the Geargrinder enters a $@spellname460603.", ua = "Міцне бронювання захищає Шестернедробар, дозволяючи йому повільно накопичувати енергію.\n\n\n\nКоли всі застосування $@spellname466615 знято, Шестернедробар переходить у $@spellname460603." },
    { en = "With its $@spellname471500 removed, the Geargrinder breaks down causing it to suffer $s2% increased damage taken until $@spellname471500 is restored.\n\n\n\nIn addition, the engine periodically $@spellname460386s sending $@spellname460624 into the arena.", ua = "Коли $@spellname471500 знято, Шестернедробар ламається, через що зазнає на $s2% більше шкоди, доки $@spellname471500 не буде відновлено.\n\n\n\nКрім того, двигун періодично $@spellname460386s, викидаючи $@spellname460624 на арену." },
    { en = "The player takes control of an abandoned Geargrinder bike to launch it forward in a $@spellname459453.\n\n\n\nIf the bike hits the Geargrinder, the war-tank suffers $467230s1% of its maximum health and loses $467230s3 application of $@spellname471500 as the bike explodes, inflicting $460633s1 Fire damage to all players and triggering a shower of $@spellname460625.", ua = "Гравець бере під контроль покинутий мотоцикл Шестернедробара, щоб кинути його вперед у $@spellname459453.\n\n\n\nЯкщо мотоцикл влучає в Шестернедробар, бойова машина зазнає шкоди в розмірі $467230s1% свого максимального здоров'я і втрачає $467230s3 застосування $@spellname471500, коли мотоцикл вибухає, завдаючи $460633s1 шкоди вогнем усім гравцям і спричиняючи зливу $@spellname460625." },
    { en = "Geargrinder bombers lob bombs at players, inflicting $s1 Fire damage on impact and causing the target to burn for $s2 Fire damage every $t2 sec for $d.", ua = "Бомбардувальники Шестернокрута жбурляють бомби в гравців, завдаючи $s1 шкоди вогнем при влучанні та змушуючи ціль горіти, отримуючи $s2 шкоди вогнем щосекунди $t2 протягом $d." },
    { en = "The Geargrinder's protective plating shatters into multiple burning pieces of shrapnel, each inflicting $s1 Fire damage to players within $A1 yards of the impact.", ua = "Захисне бронювання Шестернедробара розлітається на безліч палаючих уламків шрапнелі, кожен з яких завдає $s1 шкоди вогнем гравцям у межах $A1 м від місця влучання." },
    { en = "Vexie orders emergency repairs to the Geargrinder causing it to repair its $@spellname466615 over $d. Vexie also calls in a crew to assist with the repairs.", ua = "Вексі замовляє аварійний ремонт Шестернедробара, завдяки чому той відновлює свою $@spellname466615 протягом $d. Вексі також прикликає бригаду на допомогу з ремонтом." },
    { en = "The Geargrinder Biker charges towards a player's location, inflicting $460021s1 Fire damage to players in their path and knocking them back.", ua = "Байкер Шестернокрута кидається до розташування гравця, завдаючи $460021s1 шкоди вогнем гравцям на своєму шляху та відкидаючи їх." },
    { en = "Upon defeat, the bike explodes and sends canisters of oil flying through the air. A player can catch the oil canister, suffering $1216740s1 Nature damage and becoming $@spellname473507 for $473507d.\n\n\n\nEach canister that fails to hit a player explodes, leaving an $@spellname459683 behind.", ua = "Зазнавши поразки, мотоцикл вибухає й розкидає каністри з нафтою в повітря. Гравець може спіймати каністру з нафтою, зазнаючи $1216740s1 шкоди від сил природи і отримуючи $@spellname473507 на $473507d.\n\n\n\nКожна каністра, що не влучає в гравця, вибухає, лишаючи по собі $@spellname459683." },
    { en = "The Geargrinder's engine backfires, inflicting $460388s1 Fire damage every $t1 sec to all players.", ua = "Двигун Шестернедробара дає зворотний спалах, завдаючи $460388s1 шкоди вогнем кожні $t1 сек усім гравцям." },
    { en = "Upon reaching 100 energy, The Geargrinder's engine goes into overdrive for $d launching shrapnel at all players every $t1 sec inflicting $471508s1 Fire damage and an additional $471508s2 Fire damage every $471508t2 sec for $471508d. This effect stacks.", ua = "Сягнувши 100 енергії, двигун Шестернедробара переходить у форсаж на $d, запускаючи шрапнель в усіх гравців кожні $t1 сек, завдаючи $471508s1 шкоди вогнем і додатково $471508s2 шкоди вогнем кожні $471508t2 сек упродовж $471508d. Цей ефект накопичується." },
    { en = "The Geargrinder slams into its current target, inflicting $s1 Physical damage, knocking them back and causing them to bleed for $474061s1 Physical damage every $465865t2 sec for $465865d. In addition, the target suffers $465865s1% increased damage taken by $@spellname459627 for $465865d. This effect stacks.\n\n$?DIFF15|DIFF16[\n\nThe exertion causes the Geargrinder to expel a cloud of $@spellname468147 and leak an $@spellname459679 that lasts for $459679d.][]", ua = "Шестернедробар врізається в поточну ціль, завдаючи $s1 фізичної шкоди, відкидаючи її та змушуючи кровоточити, завдаючи $474061s1 фізичної шкоди кожні $465865t2 сек упродовж $465865d. Окрім того, ціль зазнає на $465865s1% більше шкоди від $@spellname459627 протягом $465865d. Цей ефект накопичується.\n\n$?DIFF15|DIFF16[\n\nЧерез навантаження Шестернедробар викидає хмару $@spellname468147 і дає витік $@spellname459679, що тримається $459679d.][]" },
    { en = "The Geargrinder focuses fire at several players for $468216d, launching blazing shells at their location every $468216t1 sec. Each shell inflicts $s1 Fire damage to players within $A1 yards$?DIFF15|DIFF16[ and burns away any $@spellname459679s in the area.][.]", ua = "Шестернокрут зосереджує вогонь на кількох гравцях протягом $468216d, запускаючи палаючі снаряди в їхнє розташування щосекунди $468216t1. Кожен снаряд завдає $s1 шкоди вогнем гравцям у радіусі $A1 м$?DIFF15|DIFF16[ і випалює будь-які $@spellname459679 в зоні.][.]" },
    { en = "The Pit Mechanic repairs $460153s1%  of the Geargrinder's $@spellname471500 every $t1 sec until the plating is restored.", ua = "Ямний механік відновлює $460153s1% від $@spellname471500 Шестернокрута щосекунди $t1, доки обшивку не буде полагоджено." },
    { en = "Torq smashes his current target, inflicting $463798s1 Physical damage. Additionally, $s1% of unmitigated damage is inflicted as Nature damage.", ua = "Торк трощить поточну ціль, завдаючи $463798s1 фізичної шкоди. Окрім того, $s1% незменшеної шкоди завдається як шкода від сил природи." },
    { en = "The last beast standing becomes the $@spellname471557, increasing its damage by $s2% every $t2 sec and vastly increasing the range of some abilities.", ua = "Остання істота, що лишилася на ногах, стає $@spellname471557, збільшуючи свою шкоду на $s2% кожні $t2 сек і значно збільшуючи дальність деяких здібностей." },
    { en = "Flarendo radiates flame, applying $@spellname472220 to all players within $1221259A1 yards every $t1 sec. Inflicts $472222s1 Fire damage every $472222t1 sec for $472222d. This effect stacks.", ua = "Флярендо випромінює полум'я, накладаючи $@spellname472220 на всіх гравців у межах $1221259A1 м кожні $t1 сек. Завдає $472222s1 шкоди вогнем кожні $472222t1 сек упродовж $472222d. Цей ефект накопичується." },
    { en = "Torq bristles with electricity, applying $@spellname472223 to all players within $1221256A1 yards every $t1 seconds. Inflicts $472225s1 Nature damage every $472222t1 sec for $472222d. This effect stacks.", ua = "Торк іскриться електрикою, накладаючи $@spellname472223 на всіх гравців у межах $1221256A1 м кожні $t1 сек. Завдає $472225s1 шкоди від сил природи кожні $472222t1 сек упродовж $472222d. Цей ефект накопичується." },
    { en = "Flarendo unleashes explosion-propelled flames that inflict $465466s1 Fire damage to players hit.", ua = "Флярендо вивільняє розігнане вибухом полум'я, що завдає $465466s1 шкоди вогнем уражених гравцям." },
    { en = "Flarendo tracks a target while charging, then locks in place and prepares to fire. Once ready, it fires a beam over the next $472237d. The beam inflicts $472242s1 Fire damage every $472242t1 sec to players on contact, obliterating them.", ua = "Флярендо стежить за ціллю під час зарядки, тоді фіксується на місці й готується до пострілу. Готовий, він стріляє променем протягом наступних $472237d. Промінь завдає $472242s1 шкоди вогнем кожні $472242t1 сек гравцям при контакті, знищуючи їх." },
    { en = "Torq's suit  has been overclocked, causing him to periodically call down.$@spellname463800s throughout the arena.", ua = "Костюм Торка розігнано, через що він періодично закликає $@spellname463800s по всій арені." },
    { en = "Upon reaching 100 Energy, Flarendo and Torq clash in the middle of the arena for $465872d. Their battle inflicts $470032s2 Fire and $470034s2 Nature damage to all players every $465872t sec and causes $@spellname463800s and $@spellname465446s to erupt from them.\n\n\n\nEach clash increases the damage of $@spellname465833 by $470044s1%. This effect stacks.", ua = "Сягнувши 100 енергії, Флярендо й Торк зчіплюються посеред арени на $465872d. Їхній бій завдає $470032s2 шкоди вогнем і $470034s2 шкоди від сил природи всім гравцям кожні $465872t сек і змушує $@spellname463800s та $@spellname465446s вириватися з них.\n\n\n\nКожне зіткнення збільшує шкоду $@spellname465833 на $470044s1%. Цей ефект накопичується." },
    { en = "Torq summons electric images of himself that fixate players for $1213992d. Upon contact, the image explodes, inflicting $1214024s1 Nature damage to players within $1214024A1 yards and creating $@spellname463925.", ua = "Торк прикликає електричні образи самого себе, що фіксуються на гравцях на $1213992d. При контакті образ вибухає, завдаючи $1214024s1 шкоди від сил природи гравцям у межах $1214024A1 м і створюючи $@spellname463925." },
    { en = "Flarendo spits a ball of scrap that explodes after $473654d, inflicting $473653s1 Fire damage to all players and knocking back players within $473653a2 yards. This damage is reduced for each player within $473652A1 yards of the $@spellname473650.", ua = "Флярендо випльовує кулю брухту, що вибухає за $473654d, завдаючи $473653s1 шкоди вогнем усім гравцям і відкидаючи гравців у межах $473653a2 м. Ця шкода зменшується за кожного гравця в межах $473652A1 м від $@spellname473650." },
    { en = "Lingering Electricity inflicts $s1 Nature damage every $t1 seconds to players within the area, silencing and pacifying them.", ua = "Залишкова Електрика завдає $s1 шкоди від сил природи кожні $t1 сек. гравцям у зоні, занімовуючи та утихомирюючи їх." },
    { en = "Torq calls down lightning strikes that inflict $463803s1 Nature damage to players within $463803A1 yards of the impact locations.", ua = "Торк закликає удари блискавки, що завдають $463803s1 шкоди від сил природи гравцям у межах $463803A1 м від місць влучання." },
    { en = "Fans periodically throw toys resembling Flarendo and Torq into the arena. Toys charge towards a rival toy within $s1 yards, destroying both in the process and inflicting $1221824s1 Fire and $1221825s2 Nature damage to all players every $t1 sec for $d . This effect stacks. During Colossal Clash, all toys charge their closest rival regardless of range, inflicting $465863s4% increased damage.\n\n\n\nToys can be kicked by running into them.", ua = "Фанати періодично кидають на арену іграшки, схожі на Флярендо й Торка. Іграшки мчать до іграшки-суперника в межах $s1 м, знищуючи обидві в процесі та завдаючи $1221824s1 шкоди вогнем і $1221825s2 шкоди від сил природи всім гравцям кожні $t1 сек упродовж $d . Цей ефект накопичується. Під час Колосального Зіткнення всі іграшки мчать до найближчого суперника незалежно від відстані, завдаючи на $465863s4% більше шкоди.\n\n\n\nІграшки можна відкидати, наштовхуючись на них." },
    { en = "Molten metal spreads across the ground, sending $@spellname470301s in multiple directions and inflicting $s1 Fire damage every $t1 sec to players touching it.", ua = "Розплавлений метал розтікається по землі, посилаючи $@spellname470301s в кількох напрямках і завдаючи $s1 шкоди вогнем кожні $t1 сек гравцям, що його торкаються." },
    { en = "Torq's suit amplifies the electrical charges generated within $s2 yards. Until the next $@spellname465833, an electric charge courses through players that enter into range, inflicting $474159s3 Nature damage every $474159t3 sec. Additionally, while in range, the charge grows when the target moves and depletes when they are stationary. At max charge, it erupts into a $@spellname473983.", ua = "Костюм Торка підсилює електричні заряди, що утворюються в межах $s2 м. До наступного $@spellname465833 електричний заряд проходить крізь гравців, що входять у радіус дії, завдаючи $474159s3 шкоди від сил природи кожні $474159t3 сек. Окрім того, поки ціль у радіусі дії, заряд росте, коли вона рухається, і спадає, коли вона нерухома. На максимальному заряді він вибухає $@spellname473983." },
    { en = "Torq rapidly drums his 'launch' button, firing missiles at all players within $A1 yards for $d. Each missiles inflicts $474322s1 Nature damage within $474322A1 yards on impact.", ua = "Торк швидко тарабанить по своїй кнопці 'запуск', стріляючи ракетами в усіх гравців у межах $A1 м протягом $d. Кожна ракета завдає $474322s1 шкоди від сил природи в межах $474322A1 м при влучанні." },
    { en = "Flarendo and Torq bolster their defenses while within $s2 yards of each other reducing their damage taken by $s1%. This effect does not occur during $@spellname465833.", ua = "Флярендо й Торк зміцнюють свій захист, поки перебувають у межах $s2 м один від одного, зменшуючи отримувану шкоду на $s1%. Цей ефект не діє під час $@spellname465833." },
    { en = "Flarendo runs several calculations then stomps triggering an eruption beneath their current target that inflicts $s1 Fire damage and launches them high into the air, releasing Fiery Waves in multiple directions.", ua = "Флярендо проводить кілька обчислень, тоді тупає ногою, спричиняючи виверження під поточною ціллю, що завдає $s1 шкоди вогнем і підкидає її високо в повітря, вивільняючи Вогняні Хвилі в кількох напрямках." },
    { en = "Flarendo coats a player in molten metal, inflicting $1214035s1 Fire damage to all players with $1214035A1 yards every $1213690t1 sec for $1213690d.", ua = "Флярендо вкриває гравця розплавленим металом, завдаючи $1214035s1 шкоди вогнем усім гравцям у межах $1214035A1 м кожні $1213690t1 сек упродовж $1213690d." },
    { en = "A maximum buildup of $@spellname473951 stuns the player for $d.", ua = "Максимальне накопичення $@spellname473951 оглушує гравця на $d." },
    { en = "Rik's reverberating Amplifiers produce a low hum that inflicts $s1 Sonic damage to all players every $464120t1 sec.\n\n\n\nEach active Amplifier increases the damage of Noise Pollution by $465573s1%.", ua = "Резонуючі Підсилювачі Ріка видають низький гул, що завдає $s1 звукової шкоди всім гравцям кожні $464120t1 сек.\n\n\n\nКожен активний Підсилювач збільшує шкоду Шумового Забруднення на $465573s1%." },
    { en = "Allured by the sound of Rik's sweet voice, the target is lured towards him, unable to take any actions for $d. \n\n\n\nDealing sufficient damage to the charmed target will break them free of the effect.", ua = "Зваблена звуком солодкого голосу Ріка, ціль притягується до нього, неспроможна виконувати будь-які дії на $d. \n\n\n\nЯкщо завдати зачарованій цілі достатньо шкоди, вона звільниться від ефекту." },
    { en = "Rik's $@spellname464488s increase the target's Sonic damage taken by $s1% for $d. This effect stacks.", ua = "$@spellname464488 Ріка збільшує звукову шкоду, яку отримує ціль, на $s1% на $d. Цей ефект накопичується." },
    { en = "Rik's machine short circuits sending a jolt of electricity through several players, inflicting $467020s1 Nature damage. The electricity lingers in them for $d, inflicting $467048s1 Nature damage to players within $467048A1 yards every $t1 sec and increasing the target's Nature damage taken by $s3% for $d.", ua = "Машина Ріка коротить, посилаючи розряд електрики крізь кількох гравців, завдаючи $467020s1 шкоди від сил природи. Електрика затримується в них на $d, завдаючи $467048s1 шкоди від сил природи гравцям у радіусі $467048A1 м щосекунди $t1 і збільшуючи отримувану ціллю шкоду від сил природи на $s3% протягом $d." },
    { en = "Rik deploys a sonic amplifier beneath his machine as his drones deploy amplifiers nearby. Each amplifier inflicts $466364s2 Physical damage to players within $466364A1 yards of its impact location, knocking them away and stunning for $466364d.", ua = "Рік встановлює звуковий підсилювач під своєю машиною, а його дрони розставляють підсилювачі поблизу. Кожен підсилювач завдає $466364s2 фізичної шкоди гравцям у межах $466364A1 ярдів від місця удару, відкидаючи їх і приголомшуючи на $466364d." },
    { en = "Rik tracks a target before blasting noise from his sonic resonator in their direction, inflicting $467615s1 Sonic damage to players in front of his machine.", ua = "Рік відстежує ціль, а тоді гримить на неї шумом зі свого звукового резонатора, завдаючи $467615s1 звукової шкоди гравцям перед своєю машиною." },
    { en = "An echoing wave of sound overwhelms players in its path inflicting $468120s1 Sonic damage every $t1 sec for $d. This effect stacks.", ua = "Відлунна звукова хвиля накриває гравців на своєму шляху, завдаючи $468120s1 звукової шкоди кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Rik's sonic resonator drops down out of the air, unleashing a ring of sonic demise inflicting $467992s1 Sonic damage to targets in its wake every $t1 sec for $d.", ua = "Звуковий резонатор Ріка падає з повітря, вивільняючи кільце звукової загибелі, що завдає $467992s1 звукової шкоди цілям на своєму шляху кожні $t1 сек. протягом $d." },
    { en = "$@spellname466093 Amplifiers blow out from the force of the sound, knocking players within $A1 yards up into the air, inflicting $470405s1 Physical damage and granting them immunity to $@spellname467580.", ua = "Підсилювачі, що є $@spellname466093, вибухають від сили звуку, підкидаючи гравців у межах $A1 ярдів у повітря, завдаючи $470405s1 фізичної шкоди й наділяючи їх імунітетом до $@spellname467580." },
    { en = "Upon reaching full power the amplifier goes haywire, inflicting $472990s1 Sonic damage to all players every $t1 sec and expelling additional $@spellname468119.", ua = "Досягнувши повної потужності, підсилювач виходить з ладу, завдаючи $472990s1 звукової шкоди всім гравцям кожні $t1 сек. і викидаючи додаткові $@spellname468119." },
    { en = "Rik rally-chants about Chrome-King Gallywix causing $@spellname468119 to burst out from all amplifiers in random directions.", ua = "Рік заводить запальну кричалку про Хромованого Короля Ґаллівікса, через що $@spellname468119 вириваються з усіх підсилювачів у випадкових напрямках." },
    { en = "The third $@spellname473791 has no end! Rik consumes his $@spellname1213817 to increase all damage he inflicts by $1218060s1% and continues to cast $@spellname467991s endlessly.", ua = "Третя $@spellname473791 не має кінця! Рік споживає свій $@spellname1213817, щоб збільшити всю завдану ним шкоду на $1218060s1%, і безперервно творить $@spellname467991s." },
    { en = "Rik boosts the power generation of amplifiers within $s1 yards, causing them to gain additional power.", ua = "Рік підсилює вироблення енергії підсилювачами в межах $s1 ярдів, через що ті отримують додаткову потужність." },
    { en = "Successful attacks on the pyrotechnics spark excitement, increasing movement speed by $s1% and haste by $s2% for $d. This effect stacks up to $u times.", ua = "Вдалі атаки по піротехніці викрешують іскри захвату, збільшуючи швидкість пересування на $s1% і поспіх на $s2% протягом $d. Цей ефект накопичується до $u разів." },
    { en = "The amplifier loses power when activated by a player, inflicting $1217126s1 Nature damage to them every $t1 sec.", ua = "Підсилювач втрачає потужність, коли гравець його активує, завдаючи йому $1217126s1 шкоди від сил природи кожні $t1 сек." },
    { en = "A burst of electricity erupts from colliding players if both are afflicted by $@spellname466961, inflicting $s1 Nature damage to all players.\n\n\n\nThis disruptive jolt removes $@spellname1214829 from amplifiers within $467133a2 yards.", ua = "Спалах електрики вихоплюється з гравців, що зіткнулися, якщо обидва вражені $@spellname466961, завдаючи $s1 шкоди від сил природи всім гравцям.\n\n\n\nЦей руйнівний розряд знімає $@spellname1214829 з підсилювачів у межах $467133a2 ярдів." },
    { en = "The pyrotechnic explodes after $472293d inflicting $469417s1 Fire damage to all players every $472294t1 sec for $472294d. This effect stacks.", ua = "Піротехніка вибухає за $472293d, завдаючи $469417s1 шкоди вогнем усім гравцям кожні $472294t1 сек. протягом $472294d. Цей ефект накопичується." },
    { en = "Rik's melee attacks inflict $464487s1 Sonic damage to players in a $464487A1 yard frontal cone and apply $@spellname464518.", ua = "Атаки ближнього бою Ріка завдають $464487s1 звукової шкоди гравцям у фронтальному конусі завширшки $464487A1 ярдів і накладають $@spellname464518." },
    { en = "A sonic barrier protects the amplifier from losing power or suffering from $@spellname466722", ua = "Звуковий бар'єр захищає підсилювач від втрати потужності й від $@spellname466722." },
    { en = "Rik's stagehands toss pyrotechnics into the yard that inflict $472297s1 Fire damage to players within $472297A1 yards of the impact location. \n\n\n\nPyrotechnics scatter burning sparks that inflict $472297s1 Fire damage to players within $472297a1 yards of the impact locations. \n\n\n\nPyrotechnics provide $@spellname1214164 when attacked.", ua = "Помічники Ріка зі сцени жбурляють піротехніку на арену, що завдає $472297s1 шкоди вогнем гравцям у межах $472297A1 ярдів від місця удару.\n\n\n\nПіротехніка розкидає палаючі іскри, що завдають $472297s1 шкоди вогнем гравцям у межах $472297a1 ярдів від місць удару.\n\n\n\nПіротехніка дарує $@spellname1214164, коли її атакують." },
    { en = "A nullifying bubble protects Rik Reverb and his flying sonic resonator from harm, reducing damage taken by $s1% for $d.", ua = "Нейтралізаційна бульбашка захищає Ріка Реверба і його летючий звуковий резонатор від шкоди, зменшуючи отримувану шкоду на $s1% протягом $d." },
    { en = "Stix pushes his mech to its limits, increasing his attack speed by $s1%$?diff14|diff15|diff16 [, allowing him to summon more Discarded Doomsplosives][]$?diff16 [ and Scrapmasters][], and causing $@spellname464149 to target additional garbage piles.", ua = "Стікс виводить свій мех на межу можливостей, збільшуючи свою швидкість атаки на $s1%$?diff14|diff15|diff16 [, що дозволяє йому викликати більше Викинутих Гибельобомб][]$?diff16 [ і Брухтомайстрів][], і змушуючи $@spellname464149 націлюватися на додаткові купи сміття." },
    { en = "Upon reaching 100 energy, Stix activates his mech's electromagnetic drive, inflicting $464559s1 Nature damage to all players every $t1 sec for $d and causing a variety of garbage to emerge from the landfill.", ua = "Досягнувши 100 одиниць енергії, Стікс активує електромагнітний привід свого меха, завдаючи $464559s1 шкоди від сил природи всім гравцям кожні $t1 сек. протягом $d і змушуючи різноманітне сміття вилазити зі звалища." },
    { en = "The Scrapmaster locks onto a player for $s1 sec, then fires an incredibly destructive rocket that inflicts $1220757s1 Fire damage on impact.", ua = "Брухтомайстер захоплює гравця як ціль на $s1 сек., а тоді запускає неймовірно руйнівну ракету, що завдає $1220757s1 шкоди вогнем при влучанні." },
    { en = "Experimental powercoils emerge from the landfill.\n\n\n\nPowercoils form a link with a random player and discharge their stored energy, inflicting $1218706s1 Nature damage and applying 1 stack of $@spellname1218708 every $t1 sec for $d.", ua = "Експериментальні енергокотушки виринають зі звалища.\n\n\n\nЕнергокотушки утворюють зв'язок із випадковим гравцем і вивільняють накопичену енергію, завдаючи $1218706s1 шкоди від сил природи й накладаючи 1 стак ефекту $@spellname1218708 кожні $t1 сек. протягом $d." },
    { en = "Excess charge builds up in the target's body, increasing damage taken from Prototype Powercoil by $s1% per stack.", ua = "У тілі цілі накопичується надлишковий заряд, збільшуючи отримувану від Прототипу Силокотушки шкоду на $s1% за кожен стак." },
    { en = "When Rolling Rubbish is destroyed, any enemies it absorbed are ejected to nearby locations.\n\n\n\nAfter this traumatic experience they take $s1% increased damage, but can no longer be absorbed by Rolling Rubbish.", ua = "Коли Котючий Брухт знищено, усі поглинуті ним вороги викидаються в найближчі місця.\n\n\n\nПісля цього травматичного досвіду вони отримують на $s1% більше шкоди, але їх більше не може поглинути Котючий Брухт." },
    { en = "Stix fires rocket salvos at random players over $d, inflicting $464165s1 Fire damage to players within $464165a1 yards and applying $@spellname472893.\n\n\n\nIf this effect hits a Garbage Pile, it ignites and becomes $@spellname464248.", ua = "Стікс випускає ракетні залпи по випадкових гравцях протягом $d, завдаючи $464165s1 шкоди вогнем гравцям у межах $464165a1 ярдів і накладаючи $@spellname472893.\n\n\n\nЯкщо цей ефект влучає в Купу Сміття, вона спалахує й стає $@spellname464248." },
    { en = "After $d, the Territorial Bombshell explodes, inflicting $473119s1 Fire damage to all players plus an additional $473119s2 Fire damage every $473119t2 sec for $473119d and killing itself in the process.\n\n\n\nContact with a large enough Rolling Rubbish triggers this effect instantly, destroying the Rolling Rubbish.", ua = "Через $d Територіальна Крабомба вибухає, завдаючи $473119s1 шкоди вогнем усім гравцям плюс додатково $473119s2 шкоди вогнем кожні $473119t2 сек. протягом $473119d, і при цьому знищуючи саму себе.\n\n\n\nКонтакт із достатньо великим Котючим Брухтом запускає цей ефект миттєво, знищуючи Котючий Брухт." },
    { en = "Stix fries his current target with intense electricity, inflicting $1217964s1 Nature damage every $t1 sec for $d.", ua = "Стікс підсмажує свою поточну ціль потужним струмом, завдаючи $1217964s1 шкоди від сил природи кожні $t1 сек. протягом $d." },
    { en = "Deadly fumes released by burning garbage inflict $s1 Nature damage to all players every $t1 sec. This effect stacks.", ua = "Смертоносні випари від палаючого сміття завдають $s1 шкоди від сил природи всім гравцям кожні $t1 сек. Цей ефект накопичується." },
    { en = "Stix eventually becomes impatient and forces his mech into Overdrive, temporarily reducing all damage taken by $s2% as he soars sky-high and rains down countless $@spellname467149s.\n\n\n\nHe then plunges back down with $@spellname467135 and operates at $@spellname473227 until defeated.", ua = "Зрештою Стікс втрачає терпіння й переводить свій мех у режим Форсажу, тимчасово зменшуючи всю отримувану шкоду на $s2%, поки він злітає в небеса й насилає вниз незліченні $@spellname467149s.\n\n\n\nТоді він пірнає назад униз із $@spellname467135 і діє в режимі $@spellname473227, доки його не переможуть." },
    { en = "The Scrapmaster jetpack jumps toward a player and slams into the landfill at their location, causing an explosion of garbage that inflicts $s1 Nature damage and knocks back players within $A1 yards.", ua = "Реактивний ранець Майстра брухту стрибає до гравця і врізається у звалище на його позиції, спричиняючи вибух сміття, що завдає $s1 шкоди від сил природи й відкидає гравців у радіусі $A1 м." },
    { en = "Inflicts $s2 Fire damage every $t2 sec and increases damage taken from $@spellname464865 by $s1% for $d.", ua = "Завдає $s2 шкоди вогнем кожні $t2 сек. і збільшує отримувану від $@spellname464865 шкоду на $s1% протягом $d." },
    { en = "The Scrapmaster locks on to a player and fires a salvo of salvaged rockets, inflicting $1219386s1 Fire damage every ${$t1}.2 sec for $d.", ua = "Брухтомайстер захоплює гравця як ціль і випускає залп врятованих ракет, завдаючи $1219386s1 шкоди вогнем кожні ${$t1}.2 сек. протягом $d." },
    { en = "The Junkyard Hyena sinks its filthy teeth into its current target, inflicting $s1 Physical damage$?diff15|diff16[ and reducing all healing they receive by $s2% for $d][].", ua = "Гієна зі Звалища впивається своїми брудними зубами у свою поточну ціль, завдаючи $s1 фізичної шкоди$?diff15|diff16[ і зменшуючи все отримуване нею зцілення на $s2% протягом $d][]." },
    { en = "Players hit by $@spellname464165 radiate intense heat every ${$t1}.2 sec for $d, inflicting $472849s1 Fire damage to players within $472849A1 yards.\n\n\n\nIf this effect hits a Garbage Pile, it ignites and becomes $@spellname464248.", ua = "Гравці, вражені $@spellname464165, випромінюють інтенсивний жар кожні ${$t1}.2 сек. протягом $d, завдаючи $472849s1 шкоди вогнем гравцям у межах $472849A1 ярдів.\n\n\n\nЯкщо цей ефект влучає в Купу Сміття, вона спалахує й стає $@spellname464248." },
    { en = "Stix completes the Overdrive process with an explosive landing, releasing an immense wave of electrical energy that inflicts $s1 Nature damage to players within $a1 yards.\n\n\n\nThe blast radiates outward inflicting an additional $s2 Nature damage to all players and knocking them back.", ua = "Стікс завершує процес Форсажу вибуховим приземленням, вивільняючи неосяжну хвилю електричної енергії, що завдає $s1 шкоди від сил природи гравцям у межах $a1 ярдів.\n\n\n\nВибух розходиться назовні, завдаючи додатково $s2 шкоди від сил природи всім гравцям і відкидаючи їх." },
    { en = "Rolling Rubbish inflicts $s1 Physical damage on contact with other players and stuns them for $d.", ua = "Котючий Брухт завдає $s1 фізичної шкоди при контакті з іншими гравцями і приголомшує їх на $d." },
    { en = "Rolling Rubbish explodes on contact with Stix, inflicting up to ${$s1/100}.1% of his maximum health as Nature damage based on the size of the ball.\n\n\n\nThe Rolling Rubbish is destroyed in the process.", ua = "Котючий Брухт вибухає при контакті зі Стіксом, завдаючи до ${$s1/100}.1% його максимального здоров'я як шкоду від сил природи залежно від розміру кулі.\n\n\n\nКотючий Брухт при цьому знищується." },
    { en = "Electricity arcs from Stix's mech to a nearby location, inflicting $s1 Nature damage to players within $a1 yards of the impact.", ua = "Електрика вистрілює дугою з меха Стікса в найближче місце, завдаючи $s1 шкоди від сил природи гравцям у межах $a1 ярдів від місця удару." },
    { en = "Contact with a large enough Rolling Rubbish absorbs the Discarded Doomsplosive, triggering a muffled explosion that inflicts $s1 Fire damage to all players.\n\n\n\nThe Rolling Rubbish is destroyed in the process.", ua = "Контакт із достатньо великим Котючим Брухтом поглинає Викинуту Гибельобомбу, спричиняючи приглушений вибух, що завдає $s1 шкоди вогнем усім гравцям.\n\n\n\nКотючий Брухт при цьому знищується." },
    { en = "Piles of garbage emerge from the landfill, knocking away nearby players.\n\n\n\nStanding within a Garbage Pile reduces movement speed by $s2% and inflicts $s1 Nature damage every $t1 sec.", ua = "Купи сміття вилазять зі звалища, відкидаючи гравців поблизу.\n\n\n\nПеребування в Купі Сміття зменшує швидкість пересування на $s2% і завдає $s1 шкоди від сил природи кожні $t1 сек." },
    { en = "Balls of garbage emerge beneath up to $465344s1 players, allowing them to control the ball's movement and roll over small enemies and garbage piles to absorb them.\n\n\n\nAfter absorbing enough, the ball increases in size and can absorb even larger objects.", ua = "Кулі зі сміття виринають під ногами щонайбільше $465344s1 гравців, дозволяючи їм керувати рухом кулі та накочуватися на дрібних ворогів і купи сміття, поглинаючи їх.\n\n\n\nПоглинувши достатньо, куля збільшується в розмірі й може поглинати ще більші об'єкти." },
    { en = "An absolutely enormous unused bomb emerges from the landfill.\n\n\n\nAfter $464863d the bomb explodes, inflicting $s1 Fire damage and applying $@spellname1217975 to all players.", ua = "З-під звалища виринає геть величезна невикористана бомба.\n\n\n\nЧерез $464863d бомба вибухає, завдаючи $s1 шкоди вогнем і накладаючи $@spellname1217975 на всіх гравців." },
    { en = "The Territorial Bombshell stubbornly guards its garbage pile, refusing to move and gaining immunity to crowd control effects.\n\n\n\nUpon reaching $s1% health, it abandons its garbage pile and this effect is removed.", ua = "Територіальна Бомбохульса завзято стереже свою купу сміття, відмовляючись зрушити з місця й отримуючи імунітет до ефектів контролю.\n\n\n\nДосягнувши $s1% здоров'я, вона полишає свою купу сміття, і цей ефект знімається." },
    { en = "Stix smashes his current target with a charged attack, inflicting $s1 Nature damage and $464113s1 Physical damage. In addition, all damage the target takes is increased by $s2% for $d.", ua = "Стікс гамселить свою поточну ціль зарядженою атакою, завдаючи $s1 шкоди від сил природи та $464113s1 фізичної шкоди. Крім того, вся шкода, якої зазнає ціль, збільшується на $s2% упродовж $d." },
    { en = "Ignited garbage inflicts $s1 Fire damage every $t1 sec to players standing within the area and emits $@spellname1218343 that affect all players.", ua = "Підпалене сміття завдає $s1 шкоди вогнем кожні $t1 сек гравцям, що стоять у зоні, та випромінює $@spellname1218343, що впливає на всіх гравців." },
    { en = "Void energy erupts from the impact, inflicting $s1 Shadow damage to all players.", ua = "Енергія Порожнечі вивергається з місця удару, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "Touching a trap causes it snap shut, launching the player into the air and inflicting $s1 Fire damage every $t1 sec. The pain of the fiery blister additionally increases movement speed by $s4% for $d.", ua = "Дотик до пастки змушує її захлопнутися, підкидаючи гравця в повітря та завдаючи $s1 шкоди вогнем кожні $t1 сек. Біль від вогняного пухиря додатково збільшує швидкість пересування на $s4% упродовж $d." },
    { en = "The Invention fires a massive rocket every $t1 sec for $d that inflicts $1216661s1 Fire damage upon impact with a player.", ua = "Винахід випускає величезну ракету кожні $t1 сек упродовж $d, що завдає $1216661s1 шкоди вогнем при влучанні в гравця." },
    { en = "Lockenstock infuses the target with a positive charge until the next cast of $@spellname1216802.\n\n\n\nContact with players afflicted with $@spellname1216934 will trigger a $@spellname1216965.", ua = "Локенсток наділяє ціль позитивним зарядом до наступного застосування $@spellname1216802.\n\n\n\nКонтакт із гравцями, ураженими $@spellname1216934, спричинить $@spellname1216965." },
    { en = "Lockenstock teems with unstable black blood unleashing waves of void energy that inflict $s1 Shadow damage to all players and cause the next $s2 healing to be absorbed.", ua = "Локенсток вирує нестабільною чорною кров'ю, вивільняючи хвилі енергії Порожнечі, що завдають $s1 шкоди від тіні всім гравцям і спричиняють поглинання наступних $s2 зцілення." },
    { en = "When a Foot-Blaster is detonated, it explodes inflicting $s1 Fire damage to all players and causes them to take $s2% increased damage from Unstable Explosion for $d.", ua = "Коли Ножний Бластер детонує, він вибухає, завдаючи $s1 шкоди вогнем усім гравцям і змушуючи їх зазнавати на $s2% більше шкоди від Нестабільного Вибуху впродовж $d." },
    { en = "Lockenstock gifts his current target a package of explosives. After $1214878d the recipient explodes, inflicting up to $1214910s1 Fire damage to all players. Players further from the impact position receive less damage.", ua = "Локенсток дарує своїй поточній цілі пакунок вибухівки. Через $1214878d обдарований вибухає, завдаючи щонайбільше $1214910s1 шкоди вогнем усім гравцям. Гравці, що далі від місця вибуху, зазнають меншої шкоди." },
    { en = "The Invention unleashes a line of fire for $d, inflicting $1216415s1 Fire damage every $1216415t1 sec to players within the effect.", ua = "Винахід вивільняє лінію вогню на $d, завдаючи $1216415s1 шкоди вогнем кожні $1216415t1 сек гравцям у зоні дії." },
    { en = "The Invention unleashes a massive beam of void energy inflicting $1216679s1  Shadow damage every $1216679t1 sec to players within the effect.", ua = "Винахід вивільняє потужний промінь енергії Порожнечі, що завдає $1216679s1 шкоди від тіні кожні $1216679t1 сек гравцям у зоні дії." },
    { en = "Lockenstock polarizes all players, inflicting $1217357s1 Nature damage every $1217357t1 sec and afflicting them with either $@spellname1216911 or $@spellname1216934.", ua = "Локенсток поляризує всіх гравців, завдаючи $1217357s1 шкоди від сил природи кожні $1217357t1 сек і вражаючи їх $@spellname1216911 або $@spellname1216934." },
    { en = "Lockenstock infuses the target with a negative charge until the next cast of $@spellname1216802.\n\n\n\nContact with players afflicted with $@spellname1216911 will trigger a $@spellname1216965.", ua = "Локенсток наділяє ціль негативним зарядом до наступного застосування $@spellname1216802.\n\n\n\nКонтакт із гравцями, ураженими $@spellname1216911, спричинить $@spellname1216965." },
    { en = "Touching the Foot-Blaster causes fragments to embed themselves in the target, inflicting $s1 Fire damage and increasing damage taken from Unstable Shrapnel by $s2% for $d.", ua = "Дотик до Ножного Бластера змушує осколки вгризтися в ціль, завдаючи $s1 шкоди вогнем і збільшуючи отримувану шкоду від Нестабільної Шрапнелі на $s2% упродовж $d." },
    { en = "Lockenstock becomes empowered by the black blood infusion, increasing his damage done by $s1%. This effect stacks.", ua = "Локенсток дістає підсилення від вливання чорної крові, що збільшує завдану ним шкоду на $s1%. Цей ефект накопичується." },
    { en = "Lockenstock debuts his explosive new tech, upgrading an Invention type with potent void energies. In addition, the unstable chemicals unleash a $@spellname1218319 every $1218318t1 sec as torrents of $@spellname1214265 rain down on the facility for $d.", ua = "Локенсток являє світові свою вибухову нову технологію, удосконалюючи один тип Винаходу потужними енергіями Порожнечі. Крім того, нестабільні хімікати вивільняють $@spellname1218319 кожні $1218318t1 сек, поки потоки $@spellname1214265 ринуть дощем на установку впродовж $d." },
    { en = "Gouts of black blood gush out of the canisters throughout the facility splattering to the ground, inflicting $1214267s1 Shadow damage to players within $1214267A1 yards of the impact and disorienting them for $1214267d.", ua = "Струмені чорної крові б'ють із каністр по всій установці, розбризкуючись по землі, завдаючи $1214267s1 шкоди від тіні гравцям у межах $1214267A1 м від місця удару та дезорієнтуючи їх на $1214267d." },
    { en = "Lockenstock overloads the capacitors around the factory causing a section of the floor to become electrified. Standing within these areas inflicts $s1 Nature damage to players every $t1 sec and reduces their movement speed by $s2%.", ua = "Локенсток перевантажує конденсатори по всій фабриці, через що ділянка підлоги стає наелектризованою. Перебування в цих зонах завдає $s1 шкоди від сил природи гравцям кожні $t1 сек і зменшує їхню швидкість пересування на $s2%." },
    { en = "Lockenstock launches several land mines into the room. Stepping on a Foot-Blaster triggers an $@spellname1216406 and embeds $@spellname1218342 into the triggering player. In addition, these reactive mines detonate on contact with other Inventions or $@spellname466235, triggering an $@spellname1216406.", ua = "Локенсток закидає в кімнату кілька наземних мін. Наступання на Ножний Бластер спричиняє $@spellname1216406 та вживлює $@spellname1218342 в гравця, що його активував. Крім того, ці реактивні міни детонують при контакті з іншими Винаходами чи $@spellname466235, спричиняючи $@spellname1216406." },
    { en = "The Invention launches a void projectile every $t1 sec for $d. Touching a projectile inflicts $1216706s1 Shadow damage and triggers a $@spellname1217673.", ua = "Винахід запускає снаряд Порожнечі кожні $t1 сек упродовж $d. Дотик до снаряда завдає $1216706s1 шкоди від тіні та спричиняє $@spellname1217673." },
    { en = "Lockenstock halts the conveyors and electrifies them, inflicting $1221320s1 Nature damage to players within the area every $1221320t1 sec. In addition, he activates all of his Inventions.", ua = "Локенсток зупиняє конвеєри й електризує їх, завдаючи $1221320s1 шкоди від сил природи гравцям у зоні кожні $1221320t1 сек. Крім того, він активує всі свої Винаходи." },
    { en = "Contact with a player of the opposite charge causes an explosive reaction, knocking both players away from each other and inflicting $1216989s1 Nature damage every $1216989t1 sec for $1216989d.", ua = "Контакт із гравцем протилежного заряду спричиняє вибухову реакцію, що відкидає обох гравців один від одного й завдає $1216989s1 шкоди від сил природи кожні $1216989t1 сек упродовж $1216989d." },
    { en = "Upon reaching 100 Energy Lockenstock flings pesky players away from him and begins channeling $@spellname466860.", ua = "По досягненні 100 енергії Локенсток відкидає набридливих гравців геть від себе й починає вивільняти $@spellname466860." },
    { en = "Lockenstock fires an enormous blast of gravitational energy, inflicting $s1 Sonic damage to all players and an additional $s2 Sonic damage every $t2 sec for $d.", ua = "Локенсток випускає величезний залп гравітаційної енергії, завдаючи $s1 звукової шкоди всім гравцям і додатково $s2 звукової шкоди кожні $t2 сек упродовж $d." },
    { en = "The mismatched polarities result in an especially deadly blast, inflicting $s1 Fire damage to all players and causing them to take $s2% increased damage from Unstable Explosion and Polarized Catastro-Blast for $d.", ua = "Невідповідні полярності спричиняють особливо смертоносний вибух, завдаючи $s1 шкоди вогнем усім гравцям і змушуючи їх зазнавати на $s2% більше шкоди від Нестабільного Вибуху та Поляризованого Катастро-Вибуху впродовж $d." },
    { en = "Touching a drill punctures players, stunning them and causing them to bleed for $s2 Physical damage every $t2 sec for up to $d.", ua = "Дотик до бура пробиває гравців, оглушуючи їх і змушуючи стікати кров'ю, завдаючи $s2 фізичної шкоди кожні $t2 сек упродовж щонайбільше $d." },
    { en = "The Invention pulls players towards itself for $d. Upon contact with the magnet, players become stunned for $1216503d.", ua = "Винахід притягує гравців до себе протягом $d. При контакті з магнітом гравці приголомшуються на $1216503d." },
    { en = "Lockenstock marks players, inflicting $1216509s3 Nature damage and causing a deadly drill to emerge at their location every $1216509t1  sec for $1216509d.\n\n\n\nTouching a drill causes the player to become $@spellname1217261", ua = "Локенсток позначає гравців, завдаючи $1216509s3 шкоди від сил природи та змушуючи смертоносний бур з'являтися на їхній позиції кожні $1216509t1  с протягом $1216509d.\n\n\n\nДотик до бура накладає на гравця ефект «$@spellname1217261»" },
    { en = "Lockenstock's attacks cause energy to cling to the current target, increasing all damage taken by $s1% and reducing their movement speed by $s2%. This effect stacks.", ua = "Атаки Локенстока змушують енергію чіплятися до поточної цілі, збільшуючи всю отримувану шкоду на $s1% і зменшуючи її швидкість пересування на $s2%. Цей ефект накопичується." },
    { en = "The One-Armed Bandit pulls its big arm, calling in Reel Assistants and spinning the reels rapidly for $d. Defeating an assistant makes it drop its Token, which players can deposit in the One-Armed Bandit to lock it in.\n\n\n\nWhen two Tokens are locked in, the \"Fabulous Prize\" is dispensed.", ua = "Однорукий Бандит смикає за свій великий важіль, прикликаючи Помічників Барабанів і швидко обертаючи барабани впродовж $d. Подолання помічника змушує його впустити Жетон, який гравці можуть внести до Однорукого Бандита, щоб зафіксувати його.\n\n\n\nКоли зафіксовано два Жетони, видається «Казковий Приз»." },
    { en = "Reel Assistants wrap flames around a player, inflicting $471927s1 Fire damage every $471927t1 sec for $471927d. This inferno reduces the targets maximum health by $471927s2% every time the flames inflict damage.\n\n\n\nUpon removal, $@spellname474731 erupt outwards from the player.", ua = "Помічники Барабанів огортають гравця полум'ям, завдаючи $471927s1 шкоди вогнем кожні $471927t1 сек упродовж $471927d. Це пекло зменшує максимальне здоров'я цілі на $471927s2% щоразу, коли полум'я завдає шкоди.\n\n\n\nПри знятті $@spellname474731 вивергаються назовні від гравця." },
    { en = "The One-Armed Bandit blasts out smoky exhaust at all players every $469993t1 sec for $469993d. Each blast absorbs the next $s1 healing received. \n\n\n\nWhile this effect persists, it inflicts $s4 Shadow damage every $t4 sec and reduces movement speed by $s2% per application.", ua = "Однорукий Бандит вивергає димні вихлопи на всіх гравців кожні $469993t1 сек упродовж $469993d. Кожен викид поглинає наступні $s1 отриманого зцілення.\n\n\n\nПоки цей ефект триває, він завдає $s4 шкоди від тіні кожні $t4 сек і зменшує швидкість пересування на $s2% за кожне застосування." },
    { en = "The One-Armed Bandit successfully cheats when not enough Tokens are deposited or a previously selected reel combination is locked in, permanently increasing its damage done by $s1%.", ua = "Однорукий Бандит успішно шахраює, коли внесено недостатньо Жетонів або зафіксовано раніше обрану комбінацію барабанів, назавжди збільшуючи завдану ним шкоду на $s1%." },
    { en = "Players rolled over by the chip are crushed underneath it, suffering $s1 Physical damage and becoming stunned for $d.", ua = "Гравці, на яких накотилася фішка, розчавлюються під нею, зазнаючи $s1 фізичної шкоди й оглушуючись на $d." },
    { en = "While a $@spellname460181 chip is in play, the One-Armed Bandit's damage done is increased by $s1%. This effect stacks for each token.", ua = "Поки в грі фішка $@spellname460181, шкода Однорукого Бандита збільшена на $s1%. Цей ефект накопичується за кожну марку." },
    { en = "The One-Armed Bandit rolls a massive casino chip towards players, causing anyone caught in its path to become $@spellname460430. Players can stand near the path to become a $@spellname460444. \n\n\n\nUpon reaching its destination, the chip then falls over and inflicts $460424s1 Nature damage to players within $460635A1 yards with an additional $460427s1 Nature damage to all players.\n\n\n\nPlayers may roll these chips back to destroy them.", ua = "Однорукий Бандит котить велетенську фішку казино на гравців, через що кожен на її шляху стає $@spellname460430. Гравці можуть стати поряд зі шляхом, щоб стати $@spellname460444.\n\n\n\nДосягнувши місця призначення, фішка падає й завдає $460424s1 шкоди від сил природи гравцям у межах $460635A1 м, а також додатково $460427s1 шкоди від сил природи всім гравцям.\n\n\n\nГравці можуть закотити ці фішки назад, щоб знищити їх." },
    { en = "Three Shock symbols causes the One-Armed Bandit to periodically create Hyper Coils. A Hyper Coil knocks back all players on creation or activation and is linked to the One-Armed Bandit with a $@spellname473178.", ua = "Три символи удару струмом змушують Однорукого Бандита періодично створювати Гіперзмійовики. Гіперзмійовик відкидає всіх гравців під час створення чи активації та з'єднаний з Одноруким Бандитом через $@spellname473178." },
    { en = "Depositing a Shock Token and a Flame Token creates a Superheated Coil. This electric coil releases $@spellname474731 when created or activated.", ua = "Внесення Марки Удару Струмом і Марки Полум'я створює Перегрітий Змійовик. Цей електричний змійовик вивільняє $@spellname474731 під час створення чи активації." },
    { en = "Players become high rollers, increasing damage and healing done by $s1% and movement speed by $s2% for $d.", ua = "Гравці стають хайроллерами, що збільшує завдану шкоду та зцілення на $s1%, а швидкість руху на $s2% протягом $d." },
    { en = "The One-Armed Bandit cheats the system and determines its own results in a specific order.", ua = "Однорукий Бандит махлює з системою й визначає власні результати в певному порядку." },
    { en = "The walking dynamite chases a random player for $465009d. Upon reaching the target, it explodes and inflicts $s1 Fire damage to all players.", ua = "Ходячий динаміт переслідує випадкового гравця протягом $465009d. Досягнувши цілі, він вибухає й завдає $s1 шкоди вогнем усім гравцям." },
    { en = "Depositing a Shock Token and a Bomb Token creates a Dynamite-Laden Coil. This electric coil releases Dynamite Booty when created or activated.", ua = "Внесення Марки Удару Струмом і Марки Бомби створює Змійовик із Динамітом. Цей електричний змійовик вивільняє Динамітний Куш під час створення чи активації." },
    { en = "The assistant releases a massive jolt of electricity, inflicting $s1 Nature damage to all players and knocking them back.", ua = "Помічник вивільняє потужний електричний розряд, завдаючи $s1 шкоди від сил природи всім гравцям і відкидаючи їх." },
    { en = "The Premium Currency Coil attracts the gold in player bags, pulling them towards itself and inflicting $474665s1 Physical damage every $473017t2 sec for $473017d.", ua = "Котушка Преміум-Валюти притягує золото в сумках гравців, підтягуючи їх самих до себе й завдаючи $474665s1 фізичної шкоди кожні $473017t2 с протягом $473017d." },
    { en = "Three Flame symbols causes blazing flames to erupt from the One-Armed Bandit, marking random players for $465325d. Upon expiration or removal, a line of flames blasts out towards them from the One-Armed Bandit, inflicting $465388s1 Fire damage to all players struck.", ua = "Три символи полум'я змушують Однорукого Бандита вивергнути палаюче полум'я, позначаючи випадкових гравців на $465325d. Після закінчення чи зняття до них від Однорукого Бандита вистрілює лінія полум'я, завдаючи $465388s1 шкоди вогнем усім враженим гравцям." },
    { en = "Three Coin symbols causes the One-Armed Bandit to fire golden coins wildly, inflicting $465583s1 Physical damage to all players every $t1 sec until it is destroyed.", ua = "Три символи монети змушують Однорукого Бандита шалено вистрілювати золоті монети, завдаючи $465583s1 фізичної шкоди всім гравцям кожні $t1 с, доки його не знищать." },
    { en = "Depositing a Coin Token and a Shock Token creates a Premium Currency Coil plated with gold. This electric coil activates $@spellname474665 when created or activated.", ua = "Внесення Марки Монети і Марки Удару Струмом створює позолочений Змійовик Преміумвалюти. Цей електричний змійовик активує $@spellname474665 під час створення чи активації." },
    { en = "Reel Assistants wear D.L.C. armor, preventing them from being damaged below $s2% health. \n\n\n\nSmashing them with a $@spellname460181 chip unlocks the rest of the health bar.", ua = "Помічники Барабанів носять броню D.L.C., що не дає завдавати їм шкоди нижче $s2% здоров'я.\n\n\n\nУдар по них фішкою $@spellname460181 розблоковує решту смуги здоров'я." },
    { en = "The Reel Assistant blasts its target, inflicting $s1 Nature damage. Every $t2 sec for $d, electricity arcs off of the target and inflicts $460873s1 Nature damage to all other players. This effect stacks.", ua = "Помічник Барабанів вражає свою ціль, завдаючи $s1 шкоди від сил природи. Кожні $t2 с протягом $d електрика дугою зривається з цілі й завдає $460873s1 шкоди від сил природи всім іншим гравцям. Цей ефект накопичується." },
    { en = "Activating a Coil inflicts $s1 Physical damage to the player who activates it and triggers the Coil's effect. In addition, the Coil draws in and absorbs the $s2 nearest $@spellname460474s.", ua = "Активація Змійовика завдає $s1 фізичної шкоди гравцю, який його активує, та запускає ефект Змійовика. До того ж Змійовик притягує й поглинає $s2 найближчих $@spellname460474." },
    { en = "Three Bomb symbols causes the One-Armed Bandit to explode. Killing everybody. Painfully.", ua = "Три символи бомби змушують Однорукого Бандита вибухнути. Вбиваючи всіх. Болісно." },
    { en = "The One-Armed Bandit slams its big arm into the ground, inflicting $s1 Physical damage to its target and increasing their damage taken from $@spellname460472 by $s2% for $d. This effect stacks.\n\n\n\nIn addition, $@spellname460472 leaves behind a $@spellname460474.", ua = "Однорукий Бандит гепає своєю величезною рукою об землю, завдаючи $s1 фізичної шкоди своїй цілі та збільшуючи отриману нею шкоду від $@spellname460472 на $s2% протягом $d. Цей ефект накопичується.\n\n\n\nКрім того, $@spellname460472 залишає по собі $@spellname460474." },
    { en = "Players standing within the electric field take $460576s3% increased damage and suffer $460576s1 Nature damage every $460576t1 sec.", ua = "Гравці, що стоять у межах електричного поля, отримують на $460576s3% більше шкоди та зазнають $460576s1 шкоди від сил природи кожні $460576t1 с." },
    { en = "Each time the One-Armed Bandit spins its reels, it gains $s1% attack speed. This effect stacks.", ua = "Щоразу, коли Однорукий Бандит крутить свої барабани, він отримує $s1% швидкості атаки. Цей ефект накопичується." },
    { en = "Depositing a Flame Token and a Coin Token causes the One-Armed Bandit to fire searing hot coins at all players every $t1 sec for $d. These coins inflict $461390s1 Fire damage every $461390t1 sec for $461390d. This effect stacks.", ua = "Внесення Марки Полум'я і Марки Монети змушує Однорукого Бандита вистрілювати розпечені монети по всіх гравцях кожні $t1 с протягом $d. Ці монети завдають $461390s1 шкоди вогнем кожні $461390t1 с протягом $461390d. Цей ефект накопичується." },
    { en = "Depositing a Coin Token and a Bomb Token calls forth a multiple Premium Dynamite Booty bots plated with gold. The premium currency increases its health by $s1% and damage done by $s2% and makes it immune to crowd controlling and interrupting effects.", ua = "Внесення Марки Монети і Марки Бомби викликає кількох позолочених ботів Преміумного Динамітного Куша. Преміумвалюта збільшує їхнє здоров'я на $s1% і завдану шкоду на $s2%, а також робить їх несприйнятливими до ефектів контролю та переривання." },
    { en = "Crossing the beam inflicts $473178s1 Nature damage every $465444t2 sec to players.", ua = "Перетин променя завдає гравцям $473178s1 шкоди від сил природи кожні $465444t2 с." },
    { en = "Colliding with $@spellname474731 inflicts $s1 Fire damage and knocks players back.", ua = "Зіткнення з $@spellname474731 завдає $s1 шкоди вогнем і відкидає гравців." },
    { en = "The walking dynamite chases a random player for $d. Upon reaching the target, it explodes and inflicts $465010s1 Fire damage to all players with an additional $465010s2 Fire damage every $465010t2 sec for $465010d. This effect stacks.", ua = "Динаміт, що ходить, переслідує випадкового гравця протягом $d. Досягнувши цілі, він вибухає й завдає $465010s1 шкоди вогнем усім гравцям, а також додатково $465010s2 шкоди вогнем кожні $465010t2 с протягом $465010d. Цей ефект накопичується." },
    { en = "Upon death, the Fiery Dynamite Booty explodes and inflicts $s1 Fire damage to players within $A1 yards.\n\n\n\nThis explosion releases waves of $@spellname474731.", ua = "Після загибелі Вогняний Динамітний Куш вибухає й завдає $s1 шкоди вогнем гравцям у межах $A1 м.\n\n\n\nЦей вибух вивільняє хвилі $@spellname474731." },
    { en = "Depositing a Flame Token and a Bomb Token calls forth multiple Fiery Dynamite Booty bots, which have $s1% increased health and $s2% reduced movement speed. These detonate with a $@spellname465028.", ua = "Внесення Марки Полум'я і Марки Бомби викликає кількох ботів Вогняного Динамітного Куша, що мають на $s1% більше здоров'я та на $s2% меншу швидкість руху. Вони детонують через $@spellname465028." },
    { en = "The goblin fires a disintigration beam at a random player, inflicting $s1 Fire damage every $t1 sec for $1215481d. Every $t1 sec, damage is increased by $s2%.", ua = "Гоблін вистрілює промінь дезінтеграції по випадковому гравцю, завдаючи $s1 шкоди вогнем кожні $t1 с протягом $1215481d. Кожні $t1 с шкода збільшується на $s2%." },
    { en = "The blow leaves players covered in molten gold, causing players to drip $@spellname470089s in their wake.  Each pool that is created removes an application of $@spellname467202.  \n\n\n\nAfter $d, if $@spellname467202 isn't removed the player is turned to $@spellname467225.", ua = "Удар лишає гравців укритими розплавленим золотом, через що гравці лишають по собі $@spellname470089. Кожна створена калюжа знімає одне накладення $@spellname467202.\n\n\n\nЯкщо через $d $@spellname467202 не зняте, гравця перетворює на $@spellname467225." },
    { en = "Upon reaching 100 energy, Mug'Zee enrages and fires volleys of lightning and lead, inflicting $1216143s1 Fire damage to all players every $t1 sec.", ua = "Досягнувши 100 одиниць енергії, Муг'Зі лютує й вистрілює залпи блискавок і свинцю, завдаючи $1216143s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "The MK II Electro Shocker fires an arc of electricity at a random player, inflicting $s1 Nature damage and then jumping to up to $s2 targets. This damage increases by $s3% each time it jumps.", ua = "Електрошокер Mk II вистрілює дугу електрики по випадковому гравцю, завдаючи $s1 шкоди від сил природи, а потім перестрибує на щонайбільше $s2 цілей. Ця шкода збільшується на $s3% за кожен перестриб." },
    { en = "The force from the round rips through the first player hit, inflicting $469393s1 Physical damage every $t1 sec for $d. This effect stacks.", ua = "Сила набою прошиває першого враженого гравця, завдаючи $469393s1 фізичної шкоди кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Mug'zee spins in place firing volleys of lightning and lead for $471419d. Mug unleashes thunderous waves of lightning inflicting $1218182s1 Nature damage every $1218183t1 sec to all players in a cone on one side of Mug'zee and Zee fires a spray of bullets inflicting $1218077s1 Physical damage every $1218076t1 sec to all players in a cone on the opposite side of Mug'zee.\n\n\n\nAll damage from Bulletstorm destroys $@spellname472631 and detonates $@spellname466539.", ua = "Муг'Зі крутиться на місці, вистрілюючи залпи блискавок і свинцю протягом $471419d. Муг вивільняє громові хвилі блискавок, завдаючи $1218182s1 шкоди від сил природи кожні $1218183t1 с усім гравцям у конусі з одного боку від Муг'Зі, а Зі випускає струмінь куль, завдаючи $1218077s1 фізичної шкоди кожні $1218076t1 с усім гравцям у конусі з протилежного боку від Муг'Зі.\n\n\n\nУся шкода від Кульової Бурі знищує $@spellname472631 і детонує $@spellname466539." },
    { en = "The molten gold eventually solidifies, stunning players for $d.", ua = "Розплавлене золото врешті твердне, оглушуючи гравців на $d." },
    { en = "The goon enrages if Mug'Zee or another goon overlaps the gaol, or if all players escape the gaol, increasing its damage done and attack speed by $s1%$?diff16[, and reducing damage taken by $s6%.][.]", ua = "Громило лютує, якщо Муг'Зі чи інший громило перекриває в'язницю, або якщо всі гравці втечуть із в'язниці, що збільшує його завдану шкоду та швидкість атаки на $s1%$?diff16[, і зменшує отриману шкоду на $s6%.][.]" },
    { en = "The MK II Electro Shocker envelopes itself in charged energy, reducing damage taken by $s1%.\n\n\n\nRemoved upon being hit with $@spellname466509.", ua = "Електрошокер Mk II огортає себе зарядженою енергією, зменшуючи отриману шкоду на $s1%.\n\n\n\nЗнімається після враження $@spellname466509." },
    { en = "Mug encases several players' feet in blocks of ice, inflicting $1221079s1 Frost damage to players within $1221079a1 yards every $t1 sec and causing them to slide$?|diff16 [.][ for $d.] $?|diff15|diff16 [\n\n\n\nMug'Zee coalesces and launches a lethal $@spellname466480 towards each affected player.][]", ua = "Муг заковує ноги кількох гравців у крижані брили, завдаючи $1221079s1 шкоди від криги гравцям у межах $1221079a1 м кожні $t1 с і змушуючи їх ковзати$?|diff16 [.][ протягом $d.] $?|diff15|diff16 [\n\n\n\nМуг'Зі збирається й запускає смертоносну $@spellname466480 в кожного враженого гравця.][]" },
    { en = "A lethal ice spear launches at the afflicted player, inflicting $s1 Frost damage. $@spellname466480 impacts the first player, Earthshaker Gaol wall, or Unstable Crawler Mine hit, freezing them for $1224674d.", ua = "Смертоносний крижаний спис летить у враженого гравця, завдаючи $s1 шкоди від криги. $@spellname466480 вражає першого гравця, стіну В'язниці Землетруса чи Нестабільну Повзучу Міну, заморожуючи їх на $1224674d." },
    { en = "Mug takes charge by commanding the elements to assault players, inflicting $468660s1 Elemental damage to all players every $t1 sec for $d.\n\n\n\nPlayers are then branded with $@spellname468663.", ua = "Муг бере командування, наказуючи стихіям атакувати гравців, і завдає $468660s1 стихійної шкоди всім гравцям кожні $t1 сек. протягом $d.\n\n\n\nПісля цього на гравців накладається $@spellname468663." },
    { en = "The blast embeds searing shrapnel in the player's flesh causing them to absorb the next $s1 healing.  While afflicted by this effect, they also suffer $469052s1 Fire damage every $t2 sec. $?diff16,15[This effect stacks.][]", ua = "Вибух вганяє розпечені скалки в плоть гравця, через що він поглинає наступні $s1 зцілення. Поки діє цей ефект, гравець також зазнає $469052s1 шкоди вогнем кожні $t2 сек. $?diff16,15[Цей ефект стакається.][]" },
    { en = "Zee commands a Volunteer Rocketeer to assist him. This volunteer 'guides' an explosive payload to a player's location, inflicting $s1 Fire damage split evenly among all players within $a1 yards of the impact and creating a $@spellname472057. The impact also detonates any hit $@spellname466539.\n\n\n\nIf the rocket fails to hit at least $s2 players, it inflicts $468817s1 Fire damage to all players.", ua = "Зі наказує добровольцю-ракетнику допомогти йому. Цей доброволець «наводить» вибухонебезпечний заряд на місце гравця, завдаючи $s1 шкоди вогнем, що порівну ділиться між усіма гравцями в межах $a1 м від місця удару, і створює $@spellname472057. Удар також підриває будь-яку зачеплену $@spellname466539.\n\n\n\nЯкщо ракета не влучає щонайменше в $s2 гравців, вона завдає $468817s1 шкоди вогнем усім гравцям." },
    { en = "Mug commands Gallagio Goons to lock down several players inside earthen gaols, inflicting $1220769s1 Nature damage split evenly among all players within $1220769a1 yards of the impact.", ua = "Муг наказує посіпакам Ґалладжіо замкнути кількох гравців у земляних темницях, завдаючи $1220769s1 шкоди від сил природи, що порівну ділиться між усіма гравцями в межах $1220769a1 м від місця удару." },
    { en = "Mug emanates with elemental ferocity, inflicting $468665s1 Elemental damage to all players every $t1 sec for $d. This effect stacks.", ua = "Муг випромінює стихійну лють, завдаючи $468665s1 стихійної шкоди всім гравцям кожні $t1 сек. протягом $d. Цей ефект стакається." },
    { en = "The goons death causes the earth to shake, inflicting $s1 Nature damage every $t1 sec to players within the gaol.", ua = "Смерть посіпаки змушує землю двигтіти, завдаючи $s1 шкоди від сил природи кожні $t1 сек. гравцям усередині темниці." },
    { en = "The mine explodes into a cluster of bombs, inflicting $s1 Fire damage to players within $a1 yards of the impact locations.\n\n\n\nClusters that fail to hit a player inflict $1221224s1 Fire damage to all players.", ua = "Міна вибухає на гроно бомб, завдаючи $s1 шкоди вогнем гравцям у межах $a1 м від місць удару.\n\n\n\nГрона, які не влучають у гравця, завдають $1221224s1 шкоди вогнем усім гравцям." },
    { en = "Mug and Zee take turns being the Head Honcho. Whenever $?diff16[all][the majority of players] players are on either Mug or Zee's side of the room that head takes charge, removing 10 applications of Moxie and granting Mug'Zee a unique set of abilities. \n\n\n\nIn addition, when Mug takes control, he unleashes $@spellname468658. When Zee takes control, he begins his assault with $@spellname468694.", ua = "Муг і Зі по черзі стають Головним Заправилою. Щоразу, коли $?diff16[усі][більшість] гравців опиняються на боці Муга або Зі в кімнаті, ця голова бере командування, знімаючи 10 накладень Завзяття і даруючи Муг'Зі унікальний набір здібностей.\n\n\n\nКрім того, коли керування бере Муг, він вивільняє $@spellname468658. Коли керування бере Зі, він починає свій штурм із $@spellname468694." },
    { en = "The molten gold drips to the ground and creates pools for $470088d. Contact with the gold inflicts $s1 Fire damage every $470089t1 sec and slows movement speed by $470089s3%.", ua = "Розплавлене золото скрапує на землю й утворює калюжі на $470088d. Контакт із золотом завдає $s1 шкоди вогнем кожні $470089t1 сек. і сповільнює швидкість пересування на $470089s3%." },
    { en = "The goblin activates their rocket belt to jump to a player.", ua = "Гоблін активує свій ракетний пояс, щоб стрибнути до гравця." },
    { en = "Mug fulminates lightning outward from his finger, inflicting $470245s1 Nature damage in a frontal cone every $t1 sec for $d.\n\n\n\nThe excess electricity in the area creates a $@spellname466516.", ua = "Муг вистрілює блискавки зі свого пальця, завдаючи $470245s1 шкоди від сил природи в передньому конусі кожні $t1 сек. протягом $d.\n\n\n\nНадлишок електрики в зоні створює $@spellname466516." },
    { en = "The goon pays its respects to Mug'Zee, causing him to absorb $472779s1 damage, increasing every $t1 sec for $d.", ua = "Посіпака віддає шану Муг'Зі, через що той поглинає $472779s1 шкоди, і ця величина зростає кожні $t1 сек. протягом $d." },
    { en = "Mug'Zee grows resolute over time, increasing their damage done by $s1% every $466377t1 sec. This effect stacks.", ua = "Рішучість Муг'Зі з часом зростає, збільшуючи завдану ним шкоду на $s1% кожні $466377t1 сек. Цей ефект стакається." },
    { en = "Mug'Zee harnesses electricity around him and charges, inflicting $1215902s1 Physical damage to players in his path, destroying all $@spellname472631s and $@spellname466539.\n\n\n\nUpon reaching his target, Mug'Zee unleashes a $@spellname471574.", ua = "Муг'Зі вбирає в себе електрику довкола і робить ривок, завдаючи $1215902s1 фізичної шкоди гравцям на своєму шляху та знищуючи всі $@spellname472631s і $@spellname466539.\n\n\n\nДосягнувши цілі, Муг'Зі вивільняє $@spellname471574." },
    { en = "The chaotic destruction burns, inflicting $468665s1 Fire damage to all players every $t1 sec for $d. This effect stacks.", ua = "Хаотичне руйнування палає, завдаючи $468665s1 шкоди вогнем усім гравцям кожні $t1 сек. протягом $d. Цей ефект стакається." },
    { en = "The goon violently erupts the earth in a frontal cone, inflicting $s1 Nature damage.", ua = "Посіпака люто здіймає землю в передньому конусі, завдаючи $s1 шкоди від сил природи." },
    { en = "A looming storm cloud crackles with energy, unleashing bolts that strike the ground, inflicting $466517s1 Nature damage to players within $466517a1 yards of impact locations and stunning players hit for $466517d.", ua = "Грозова хмара, що нависає, тріщить енергією і вивільняє блискавки, які б'ють у землю, завдаючи $466517s1 шкоди від сил природи гравцям у межах $466517a1 м від місць удару й приголомшуючи зачеплених гравців на $466517d." },
    { en = "Zee takes charge by calling in bombs, rockets, and drones, inflicting $469708s1 Fire damage to all players every $t1 sec for $d. \n\n\n\nPlayers are then afflicted with $@spellname469715.", ua = "Зі бере командування, викликаючи бомби, ракети й дрони, які завдають $469708s1 шкоди вогнем усім гравцям кожні $t1 сек. протягом $d.\n\n\n\nПісля цього на гравців накладається $@spellname469715." },
    { en = "Mug unleashes a blow of molten gold and lava in a frontal cone, inflicting $466519s1 Physical damage and $467201s1 Fire damage, knocking them back.\n\n\n\nPlayers hit are covered in $@spellname467202.", ua = "Муг завдає удару розплавленим золотом і лавою в передньому конусі, завдаючи $466519s1 фізичної шкоди та $467201s1 шкоди вогнем і відкидаючи цілі назад.\n\n\n\nЗачеплені гравці вкриваються $@spellname467202." },
    { en = "The crawler mine is covered in experimental plating, granting immunity to all damage.\n\n\n\nUpon reaching 100 energy, the mine becomes immune to crowd control effects and gains $1225928s1% movement speed.", ua = "Повзуча міна вкрита експериментальним бронюванням, що дає несприйнятливість до будь-якої шкоди.\n\n\n\nДосягнувши 100 енергії, міна стає несприйнятливою до ефектів контролю та отримує $1225928s1% швидкості пересування." },
    { en = "Players impacted by the rocket suffer radiation sickness, increasing the damage taken from $@spellname467381 by $s1% for $d.", ua = "Гравці, у яких влучила ракета, потерпають від променевої хвороби, що збільшує шкоду від $@spellname467381 на $s1% протягом $d." },
    { en = "Mug'Zee empowers themselves, increasing Haste by $s1%.", ua = "Муг'Зі підсилює себе, збільшуючи Поспіх на $s1%." },
    { en = "Upon reaching $s1% health the flyer malfunctions, becoming stunned and taking $1215595s1% increased damage for $1215595d.", ua = "Досягнувши $s1% здоров'я, літун дає збій, стає приголомшеним і отримує на $1215595s1% більше шкоди протягом $1215595d." },
    { en = "Zee scatters mines that fixate on players which detonate when coming into contact with players, $@spellname472631s, inflicting $469061s1 Physical damage and $469062s1 Fire damage to the target triggering the mine, knocking them away. \n\n\n\nTriggering a mine unleashes $?diff16,15[a $@spellname1220551 and ][]a barrage of $@spellname472333. $?diff16,15[\n\nOn Heroic and Mythic difficulties, the player triggering the Unstable Crawler Mine takes $472061s1% increased damage from Unstable Crawler Mines for $472061d.][]", ua = "Зі розкидає міни, що фіксуються на гравцях і детонують при контакті з гравцями чи $@spellname472631s, завдаючи $469061s1 фізичної шкоди та $469062s1 шкоди вогнем цілі, що спровокувала міну, і відкидаючи її геть.\n\n\n\nСпровокована міна вивільняє $?diff16,15[$@spellname1220551 та ][]шквал $@spellname472333. $?diff16,15[\n\nНа складностях «Героїчна» та «Міфічна» гравець, що спровокував Нестабільну Повзучу Міну, отримує на $472061s1% більше шкоди від Нестабільних Повзучих Мін протягом $472061d.][]" },
    { en = "Mug'Zee unleashes his $@spellname1216495 and divides the arena in two, instantly killing players who come into contact with it.", ua = "Муг'Зі вивільняє свою $@spellname1216495 і розділяє арену надвоє, миттєво вбиваючи гравців, які з нею стикаються." },
    { en = "Zee unleashes a cone of bullets at a player, inflicting $466546s1 Physical damage every $t1 for $d to players standing within the effect and detonating any hit $@spellname466539.", ua = "Зі вистрілює конус куль у гравця, завдаючи $466546s1 фізичної шкоди кожні $t1 протягом $d гравцям, що стоять у зоні ефекту, і підриваючи будь-яку зачеплену $@spellname466539." },
    { en = "Zee fires an explosive high caliber round towards a random player, inflicting $1220398s1 Physical damage to the closest player and applying $@spellname469391. All other targets take up to $1220398s1 Physical damage, reduced by the closest player's total damage mitigation.\n\n\n\n$@spellname466539 hit are detonated and all players hit are stunned for $469601d. In addition, an $@spellname469375 is lodged in the original target.", ua = "Зі стріляє вибуховим набоєм великого калібру у випадкового гравця, завдаючи $1220398s1 фізичної шкоди найближчому гравцеві й накладаючи $@spellname469391. Усі інші цілі отримують до $1220398s1 фізичної шкоди, зменшеної на загальне пом'якшення шкоди найближчого гравця.\n\n\n\nЗачеплені $@spellname466539 детонують, і всіх зачеплених гравців приголомшує на $469601d. Крім того, в первинну ціль вгрузає $@spellname469375." },
    { en = "The rocket leaves behind a fiery mess. Players within this effect suffer $s1 Fire damage every $t1 sec.", ua = "Ракета залишає по собі вогняне місиво. Гравці в зоні цього ефекту зазнають $s1 шкоди вогнем кожні $t1 сек." },
    { en = "The goon erupts when killed, inflicting $s1 Nature damage to players within the gaol and knocking them back.\n\n\n\nColliding with a wall of $@spellname472631 causes it to be destroyed.", ua = "Посіпака вибухає, коли його вбивають, завдаючи $s1 шкоди від сил природи гравцям усередині темниці й відкидаючи їх назад.\n\n\n\nЗіткнення зі стіною $@spellname472631 призводить до її знищення." },
    { en = "The round lodges in the original target exploding after $d, inflicting $469377s1 Fire damage to players and detonates $@spellname466539 within $469377a1 yards.", ua = "Набій вгрузає в первинну ціль і вибухає через $d, завдаючи $469377s1 шкоди вогнем гравцям і підриваючи $@spellname466539 в межах $469377a1 м." },
    { en = "Gallywix finishes this Suppression with pizzaz firing a massive shock at a targeted location inflicting $s1 Nature damage to all players, decreasing in damage as distance increases.", ua = "Ґаллівікс завершує цю Розправу з шиком, вистрілюючи потужний удар струмом у вказане місце, завдаючи $s1 шкоди від сил природи всім гравцям; шкода зменшується зі зростанням відстані." },
    { en = "Carrying a Giga Bomb in front of Giga Controls automatically detonates the Giga Bomb $?diff16[inflicting $469795s1 Nature damage to players within $469795A1 yards, and sabotages nearby Giga Controls based on the health of the bomb.][inflicting $469795s1 Nature damage and sabotages nearby Giga Controls.]\n\n\n\nAdditionally this jolt grants $469795s2% increased movement speed for $469795D.", ua = "Якщо пронести Гіга-Бомбу повз Гіга-Керування, Гіга-Бомба автоматично детонує$?diff16[, завдаючи $469795s1 шкоди від сил природи гравцям у межах $469795A1 м і саботуючи довколишнє Гіга-Керування залежно від здоров'я бомби.][, завдаючи $469795s1 шкоди від сил природи й саботуючи довколишнє Гіга-Керування.]\n\n\n\nКрім того, цей поштовх дарує на $469795s2% більшу швидкість пересування протягом $469795D." },
    { en = "A two-for-one deal - $@spellname466158 drops additional bombs which explode moments later inflicting $1217837s1 Fire damage to players within $1217837A1 yards.", ua = "Дві в ціні однієї — $@spellname466158 скидає додаткові бомби, які вибухають за мить, завдаючи $1217837s1 шкоди вогнем гравцям у межах $1217837A1 м." },
    { en = "A two-stage effect releases bombettes throughout inflicting $1217293s1 Fire damage to all players.", ua = "Двостадійний ефект розсіює бомбочки повсюди, завдаючи $1217293s1 шкоди вогнем усім гравцям." },
    { en = "Gallywix gives his current target a $466958s2-hit knuckle sandwich, inflicting $467011s1 Physical damage each strike. These blows cannot be dodged or parried.\n\n\n\nAdditionally $466958s1% of unmitigated damage is inflicted as a $@spellname467064.", ua = "Ґаллівікс пригощає свою поточну ціль кулаком $466958s2 рази поспіль, завдаючи $467011s1 фізичної шкоди кожним ударом. Ці удари не можна ні ухилити, ні відбити.\n\n\n\nКрім того, $466958s1% непом'якшеної шкоди завдається як $@spellname467064." },
    { en = "Gallywix shells his primary target with many explosives inflicting $1214611s1 Physical damage and increases Bigger Badder Bomb Blast damage taken by $1216444s1% for $1216444D. This effect stacks and cannot be dodged or parried.\n\n\n\nAdditionally inflicts $1214611s1 Fire damage to players within $1214616A1 yards of the primary target, applying $@spellname466154. These munitions (mostly) detonate on impact.\n\n\n\nHowever, some of the fuze within the bunch scatters about the arena.", ua = "Ґаллівікс закидає свою основну ціль безліччю вибухівки, завдаючи $1214611s1 фізичної шкоди і збільшуючи шкоду від «Бомбезнішого Бомбового Вибуху» на $1216444s1% протягом $1216444D. Цей ефект стакається, і його не можна ні ухилити, ні відбити.\n\n\n\nКрім того, завдає $1214611s1 шкоди вогнем гравцям у межах $1214616A1 м від основної цілі, накладаючи $@spellname466154. Ці боєприпаси (здебільшого) детонують при ударі.\n\n\n\nОднак частина запалів із цього гурту розсипається по арені." },
    { en = "The Sharpshot Sentry focuses charged energy at a target for $466834D inflicting $466834s2 Nature damage and up to an additional $466955s1 Nature damage every $466834T1 sec.", ua = "Сторожа-Влучник зосереджує заряджену енергію на цілі протягом $466834D, завдаючи $466834s2 шкоди від сил природи та ще до $466955s1 шкоди від сил природи кожні $466834T1 сек." },
    { en = "Gallywix slams into the arena inflicting $1214226s1 Fire damage to players within $1214226A1 yards of the point of impact, and $1214226s2 Fire damage to all other players.", ua = "Ґаллівікс врізається в арену, завдаючи $1214226s1 шкоди вогнем гравцям у межах $1214226A1 м від місця удару та $1214226s2 шкоди вогнем усім іншим гравцям." },
    { en = "Darkfuse agents hardened this metal as much as they could (then they rubbed some solvent on it - don't know what that's for), granting immunity to interrupt effects and absorbing $s2 damage.", ua = "Агенти Темнозапалу загартували цей метал, як тільки могли (а потім ще й розчинником його натерли — не знаю, навіщо це), даючи імунітет до ефектів переривання й поглинаючи $s2 шкоди." },
    { en = "Gallywix's experiment covers afflicted enemies absorbing $1220761s1 healing for $1220761D. \n\n\n\nUpon expiration or consuming this healing implodes the canister incurring $@spellname474447.", ua = "Експеримент Ґаллівікса вкриває уражених ворогів, поглинаючи $1220761s1 зцілення протягом $1220761D. \n\n\n\nКоли ефект спливає або це зцілення вичерпується, каністра вибухає, завдаючи $@spellname474447." },
    { en = "Giga Bombs detonate after $1223905D or when struck by Giga Blast inflicting $469404s1 Nature damage plus an additional $469404s2 Nature damage every $469404T2 sec to all players for $469404D. This effect stacks.", ua = "Гіга-бомби детонують через $1223905D або коли в них влучає Гіга-вибух, завдаючи $469404s1 шкоди від сил природи плюс додаткові $469404s2 шкоди від сил природи кожні $469404T2 сек усім гравцям протягом $469404D. Цей ефект накопичується." },
    { en = "Gallywix calls in explosives which (mostly) detonate moments later inflicting $465938s1 Fire damage and applies $@spellname466154.\n\n\n\nHowever, some of the fuze within the bunch scatters about the arena.", ua = "Ґаллівікс викликає вибухівку, яка (здебільшого) детонує за мить, завдаючи $465938s1 шкоди вогнем і накладаючи $@spellname466154.\n\n\n\nПроте частина запалів у цій зв'язці розлітається по арені." },
    { en = "Gallywix rains rockets inflicting $1214448s1 Fire damage to all players every $T1 sec for $D. Every $T1 sec this damage increases by $s2%.", ua = "Ґаллівікс засипає ракетами, завдаючи $1214448s1 шкоди вогнем усім гравцям кожні $T1 сек протягом $D. Кожні $T1 сек ця шкода зростає на $s2%." },
    { en = "Miniaturized rockets zing from the pile inflicting $s1 Fire damage every $T1 sec for $D. This effect stacks.", ua = "Мініатюрні ракети вилітають із купи, завдаючи $s1 шкоди вогнем кожні $T1 сек протягом $D. Цей ефект накопичується." },
    { en = "The blast lights the good stuff attaching some OL rockets to unsuspecting fools for $1214749D.\n\n\n\nUpon removal these rockets blast out in indicated directions inflicting $1214755s1 Fire damage every second for $1214755D to impacted players, knocking them back.", ua = "Вибух підпалює добрячий запас, чіпляючи кілька перевантажених ракет до нічого не підозрюючих бовдурів на $1214749D.\n\n\n\nПісля зняття ці ракети вистрілюють у вказаних напрямках, завдаючи $1214755s1 шкоди вогнем щосекунди протягом $1214755D гравцям, у яких влучили, і відкидаючи їх." },
    { en = "Gallywix cannons his current target inflicting $1213156s1 Physical damage. This attack cannot be dodged or parried.\n\n\n\nThis additionally blasts players in a frontal cone inflicting $466419s1 Fire damage and increases Scatterblast Canisters damage taken by $471603s1% for $471603D. This damage splits evenly among effected players.\n\n\n\nAll targets become afflicted with $@spellname1220761.\n\n\n\nIf this fails to hit at least $466340s1 |4target:targets; all players suffer the full effect.", ua = "Ґаллівікс стріляє з гармати по своїй поточній цілі, завдаючи $1213156s1 фізичної шкоди. Цю атаку неможливо ухилити чи парирувати.\n\n\n\nДодатково вона вражає гравців у фронтальному конусі, завдаючи $466419s1 шкоди вогнем і збільшуючи отримувану шкоду від Осколкових каністр на $471603s1% протягом $471603D. Ця шкода рівномірно розподіляється між ураженими гравцями.\n\n\n\nУсі цілі стають уражені $@spellname1220761.\n\n\n\nЯкщо це не влучає принаймні в $466340s1 |4ціль:цілі:цілей;, усі гравці зазнають повного ефекту." },
    { en = "$?diff16[][Gallywix launches shells that attach to marked targets. ]After $466344D these detonate inflicting $466489s1 Fire damage to players within $466577A2 yards. This damage splits evenly among effected players$?diff16[.][.\n\n\n\nAll targets become afflicted with $@spellname1220761.\n\n\n\nIf this fails to hit at least $466341s1 |4target:targets; all players suffer the full effect.]", ua = "$?diff16[][Ґаллівікс запускає снаряди, які чіпляються до позначених цілей. ]Через $466344D вони детонують, завдаючи $466489s1 шкоди вогнем гравцям у межах $466577A2 м. Ця шкода рівномірно розподіляється між ураженими гравцями$?diff16[.][.\n\n\n\nУсі цілі стають уражені $@spellname1220761.\n\n\n\nЯкщо це не влучає принаймні в $466341s1 |4ціль:цілі:цілей;, усі гравці зазнають повного ефекту.]" },
    { en = "Gallywix charges and activates The House of Chrome's Giga Coils inflicting $469295s1 Nature damage to all players every $469293T1 sec. This effect stacks.$?diff16[][\n\n\n\nGallywix then starts Giga Blast-ing!]\n\n\n\n$@spellname469767 damages the Giga Controls interrupting Gallywix's Giga Coils, and Giga Coils become Sabotaged Coils upon losing both Giga Controls. This creates $@spellname1215209.", ua = "Ґаллівікс заряджає й активує Гіга-котушки Дому Хрому, завдаючи $469295s1 шкоди від сил природи всім гравцям кожні $469293T1 сек. Цей ефект накопичується.$?diff16[][\n\n\n\nПотім Ґаллівікс починає застосовувати Гіга-вибух!]\n\n\n\n$@spellname469767 пошкоджує Гіга-керування, перериваючи Гіга-котушки Ґаллівікса, і Гіга-котушки стають Саботованими котушками після втрати обох Гіга-керувань. Це створює $@spellname1215209." },
    { en = "$?diff16[][Gallywix ejects volatile containers that embed into the floor. ]After $466581D these detonate inflicting $466578s1 Fire damage to players within $466580A1 yards. This damage splits evenly among effected players$?diff16[.][.\n\n\n\nAll targets become afflicted with $@spellname1220761.\n\n\n\nIf this fails to hit at least $466342s1 |4target:targets; all players suffer the full effect.]", ua = "$?diff16[][Ґаллівікс викидає нестабільні контейнери, що вгрузають у підлогу. ]Через $466581D вони детонують, завдаючи $466578s1 шкоди вогнем гравцям у межах $466580A1 м. Ця шкода рівномірно розподіляється між ураженими гравцями$?diff16[.][.\n\n\n\nУсі цілі стають уражені $@spellname1220761.\n\n\n\nЯкщо це не влучає принаймні в $466342s1 |4ціль:цілі:цілей;, усі гравці зазнають повного ефекту.]" },
    { en = "Inflicts $1218989s1 Nature damage every $1218987T1 sec to the nearest $1218987s1 players.\n\n\n\nUpon interaction gain Discharged Giga Bomb, instead suffering $1218989s1 Nature damage every $1218992T2 sec. This effect stacks.", ua = "Завдає $1218989s1 шкоди від сил природи кожні $1218987T1 сек найближчим $1218987s1 гравцям.\n\n\n\nПісля взаємодії ви отримуєте Розряджену гіга-бомбу й натомість зазнаєте $1218989s1 шкоди від сил природи кожні $1218992T2 сек. Цей ефект накопичується." },
    { en = "Damaged Giga Controls spark profusely inflicting $469297s1 Nature damage to targeted players every $1220669T1 sec. This effect stacks for each Sabotaged Control, and is definitely against regulation.", ua = "Пошкоджене Гіга-керування рясно іскрить, завдаючи $469297s1 шкоди від сил природи позначеним гравцям кожні $1220669T1 сек. Цей ефект накопичується за кожне Саботоване керування і вже точно суперечить нормам безпеки." },
    { en = "$1220781D after picking up a Giga Bomb the silver bracelets click, preventing $@spellname469363 and picking up additional Giga Bombs.\n\n\n\nIf for any reason this aura removes the shackles detonate inflicting $1220791s1 Fire damage to all players.", ua = "Через $1220781D після підняття Гіга-бомби срібні браслети клацають, перешкоджаючи $@spellname469363 та підняттю додаткових Гіга-бомб.\n\n\n\nЯкщо ця аура з будь-якої причини знімається, окови вибухають, завдаючи $1220791s1 шкоди вогнем усім гравцям." },
    { en = "The Darkfuse Blaster turbocharges the Giga Bomb inflicting $471352s2 Nature damage to players within $471352A2 yards.\n\n\n\nAdditionally this increases the Darkfuse Blaster's damage done by $471352s3% and movement speed by $471352s4%. This effect stacks.", ua = "Бластер Темнозапалу турбозаряджає Гіга-бомбу, завдаючи $471352s2 шкоди від сил природи гравцям у межах $471352A2 м.\n\n\n\nДодатково це збільшує завдану Бластером Темнозапалу шкоду на $471352s3% і швидкість руху на $471352s4%. Цей ефект накопичується." },
    { en = "Gallywix's barrels spit hot lead inflicting $s1 Physical damage, increasing by up to $s2% as distance to the target increases.", ua = "Стволи Ґаллівікса плюються гарячим свинцем, завдаючи $s1 фізичної шкоди, що зростає аж до $s2% зі збільшенням відстані до цілі." },
    { en = "Gallywix's machines dump excessive heat over $466751D inflicting $466751s1 Fire damage to all players plus an additional $466752s1 Fire damage every $466751T2 sec.", ua = "Машини Ґаллівікса скидають надлишок тепла протягом $466751D, завдаючи $466751s1 шкоди вогнем усім гравцям плюс додаткові $466752s1 шкоди вогнем кожні $466751T2 сек." },
    { en = "Gallywix's contraption dissipates inefficiently increasing the duration of $@spellname466751 by $466753s1 sec. This effect stacks.", ua = "Пристрій Ґаллівікса розсіює тепло неефективно, збільшуючи тривалість $@spellname466751 на $466753s1 сек. Цей ефект накопичується." },
    { en = "Gallywix gains a stack of $@spellname1220290 every $1220290T1 sec.\n\n\n\nUpon reaching $1220290s2 stacks or when changing primary target all shots release inflicting $1220353s1 Physical damage and an additional $1226288s1 Fire damage every $1220375T1 sec for $1220375D, each. This effect stacks, and cannot be dodged.", ua = "Ґаллівікс отримує заряд $@spellname1220290 кожні $1220290T1 сек.\n\n\n\nПри досягненні $1220290s2 зарядів або при зміні основної цілі вистрілюють усі постріли, кожен з яких завдає $1220353s1 фізичної шкоди й додаткові $1226288s1 шкоди вогнем кожні $1220375T1 сек протягом $1220375D. Цей ефект накопичується, і його неможливо ухилити." },
    { en = "Gallywix taps into his reserve stash firing both $@spellname466341 and $@spellname466342 at the same time.\n\n\n\nAfter $466344D the $@spellname466341 detonate inflicting $466489s1 Fire damage to players within $466577A2 yards, and after $466581D the $@spellname466342 detonate inflicting $466578s1 damage to players within $466580A1 yards. These effects split evenly among effected players.\n\n\n\nAll targets become afflicted with $@spellname1220761.\n\n\n\nIf this fails to hit at least $1217987s1 |4target:targets; all players suffer the full effect.", ua = "Ґаллівікс черпає зі своєї резервної заначки, вистрілюючи $@spellname466341 та $@spellname466342 одночасно.\n\n\n\nЧерез $466344D $@spellname466341 детонують, завдаючи $466489s1 шкоди вогнем гравцям у межах $466577A2 м, а через $466581D $@spellname466342 детонують, завдаючи $466578s1 шкоди гравцям у межах $466580A1 м. Ці ефекти рівномірно розподіляються між ураженими гравцями.\n\n\n\nУсі цілі стають уражені $@spellname1220761.\n\n\n\nЯкщо це не влучає принаймні в $1217987s1 |4ціль:цілі:цілей;, усі гравці зазнають повного ефекту." },
    { en = "The ordnance's blast sears inflicting $1217291s1 Fire damage every $466246T1 sec for $466246D. This effect stacks.\n\n\n\nFocused Detonation triggers a Time-Release Crackle upon removal.", ua = "Вибух боєприпасу обпікає, завдаючи $1217291s1 шкоди вогнем кожні $466246T1 сек протягом $466246D. Цей ефект накопичується.\n\n\n\nСфокусована детонація після зняття спричиняє Сповільнений тріск." },
    { en = "Charged ions remain after a Giga Blast for $1218504D. Upon contact charges a Discharged Giga Bomb, or inflicts $1218513s1 Nature damage and stuns for $1218513D when one is not present. This consumes the residue.", ua = "Заряджені іони лишаються після Гіга-вибуху протягом $1218504D. При контакті заряджають Розряджену гіга-бомбу або, якщо такої немає, завдають $1218513s1 шкоди від сил природи й оглушують на $1218513D. Це поглинає залишок." },
    { en = "The hobgoblin is holding a wrench. Doing so he now knows how to strike someone with the wrench inflicting $s1 Physical damage and increases Wrench damage taken by $s2%. This effect stacks, and causes quite a headache.", ua = "Хобгоблін тримає гайковий ключ. А коли тримаєш, то вже знаєш, як ним когось добряче приголомшити: завдає $s1 фізичної шкоди й збільшує отримувану шкоду від Гайкового ключа на $s2%. Цей ефект накопичується і неабияк болить голова." },
    { en = "Humane, high-voltage shock. Quickly eliminates pests. Gallywix attaches lightning tethers inflicting $1219280s1 Nature damage every $T1 sec to targeted players and any additional player between them and Gallywix. This effect increases in damage while tethered targets are further from Gallywix.", ua = "Гуманний удар струмом високої напруги. Швидко позбавляє від шкідників. Ґаллівікс чіпляє блискавичні пута, завдаючи $1219280s1 шкоди від сил природи кожні $T1 сек позначеним гравцям і будь-якому іншому гравцеві між ними та Ґаллівіксом. Шкода цього ефекту зростає, що далі прив'язані цілі від Ґаллівікса." },
    { en = "Explodes inflicting up to $s2 Shadow damage to $?diff15|diff16[all players][the wearer] based on the remaining healing absorb in the Mechengineer's Canister.", ua = "Вибухає, завдаючи до $s2 шкоди від тіні $?diff15|diff16[усім гравцям][носієві] залежно від залишку поглинання зцілення в Каністрі Мехінженера." },
    { en = "$?diff16[Gallywix blasts lightning][Gallywix collects and ejects Giga Coil power] in a direction inflicting $469326s1 Nature damage plus an additional $469326s2 Nature damage every $469326T2 sec for $469326D. This effect stacks.$?diff16[][\n\n\n\nEach successive blast increases Giga Coil damage by $471341s1%. This effect stacks.]", ua = "$?diff16[Ґаллівікс випускає блискавку][Ґаллівікс збирає й викидає енергію Гіга-котушки] у напрямку, завдаючи $469326s1 шкоди від сил природи плюс додаткові $469326s2 шкоди від сил природи кожні $469326T2 сек протягом $469326D. Цей ефект накопичується.$?diff16[][\n\n\n\nКожен наступний випуск збільшує шкоду Гіга-котушки на $471341s1%. Цей ефект накопичується.]" },
    { en = "The hobgoblin does what he does best - get mad. Then he lumbers towards his target inflicting $s1% increased damage done with $s4% reduced movement speed for $D.", ua = "Хобгоблін робить те, що вміє найкраще — лютує. Потім він важко суне до своєї цілі, завдаючи на $s1% більше шкоди при $s4% зниженій швидкості руху протягом $D." },
    { en = "Arrive just in time to be the life of the show knocking back and inflicting $1223126s1 Fire damage to enemies within $1223126A1 yards upon impact. Cool.", ua = "Прибуваєте якраз вчасно, щоб стати окрасою шоу, відкидаючи й завдаючи $1223126s1 шкоди вогнем ворогам у межах $1223126A1 м при ударі. Клас." },
    { en = "Excites the magnetic field ionizing players inflicting $s1 Nature damage every $T1 sec and reducing movement speed by $s2% for $D.", ua = "Збуджує магнітне поле, іонізуючи гравців, завдаючи $s1 шкоди від сил природи кожні $T1 сек і знижуючи швидкість руху на $s2% протягом $D." },
    { en = "The techie jolts a targeted player, inflicting $s1 Nature damage, stunning them for $375653D.", ua = "Технар б'є струмом позначеного гравця, завдаючи $s1 шкоди від сил природи й оглушуючи його на $375653D." },
    { en = "Loaded with out-of-compliance \"safety fuse\" these bombs scatter detonating late inflicting $s1 Fire damage to players within $A1 yards and applies $@spellname466154.", ua = "Заряджені невідповідним нормам «запобіжним запалом», ці бомби розлітаються й детонують із запізненням, завдаючи $s1 шкоди вогнем гравцям у межах $A1 м і накладаючи $@spellname466154." },
    { en = "The ordnance singes slowpokes inflicting $s1 Fire damage every $T1 sec for $D. This effect stacks.", ua = "Боєприпас обпалює тих, хто роззявляється, завдаючи $s1 шкоди вогнем кожні $T1 сек протягом $D. Цей ефект накопичується." },
    { en = "Sabotaged Coils discharge energy into The House of Chrome forming a zone. Contact with this zone inflicts $s1 Nature damage every $T1 sec.", ua = "Саботовані котушки розряджають енергію в Дім Хрому, утворюючи зону. Контакт із цією зоною завдає $s1 шкоди від сил природи кожні $T1 сек." },
    { en = "Marked players gain a value pack! After $466155D these detonate inflicting $466158s1 Fire damage to players within $466158A1 yards applying Blast Burns$?diff15|diff16[ and Sapper's Satchel.][.]", ua = "Позначені гравці отримують вигідний набір! Через $466155D він детонує, завдаючи $466158s1 шкоди вогнем гравцям у межах $466158A1 м і накладаючи Опіки від вибуху$?diff15|diff16[ та Саквояж сапера.][.]" },
    { en = "Gallywix shrapnels subordinates for $467182D inflicting $467184s1 Fire damage plus an additional $467184s2 Fire damage every $467184T2 sec to players within $467184A1 yards of indicated locations for $467184D. This effect stacks.", ua = "Ґаллівікс закидає підлеглих шрапнеллю протягом $467182D, завдаючи $467184s1 шкоди вогнем плюс додаткові $467184s2 шкоди вогнем кожні $467184T2 сек гравцям у межах $467184A1 м від вказаних місць протягом $467184D. Цей ефект накопичується." },
    { en = "Sabotaging a Giga Controls causes a Control Meltdown for $D. During this time if Gallywix activates Giga Coils it backfires, interrupting Giga Coils.", ua = "Саботаж Гіга-керування спричиняє Розплавлення керування протягом $D. Упродовж цього часу, якщо Ґаллівікс активує Гіга-котушки, стається збій, що перериває Гіга-котушки." },
    { en = "The Giga Coils furiously eject free ions causing strikes throughout inflicting $s1 Nature damage to players within $A1 yards of each impact.", ua = "Гіга-котушки люто викидають вільні іони, спричиняючи удари по всій площі, що завдають $s1 шкоди від сил природи гравцям у межах $A1 м від кожного влучання." },
    { en = "Inflicts $1218500s1 Nature damage every $469373T1 sec to players within $469395A1 yards.\n\n\n\nUpon interaction gain Charged Giga Bomb, instead suffering $1218500s1 Nature damage every $469362T2 sec.$?diff15[ This effect stacks.][]", ua = "Завдає $1218500s1 шкоди від сил природи щосекунди ($469373T1) гравцям у радіусі $469395A1 ярдів.\n\n\n\nПри взаємодії дає Заряджену Гіга-Бомбу, через що шкода від сил природи $1218500s1 завдається кожні $469362T2 сек.$?diff15[ Цей ефект накопичується.][]" },
    { en = "Ditch the Giga Bomb you are holding.", ua = "Скиньте Гіга-Бомбу, яку тримаєте." },
    { en = "DUD-1500 munitions embed into the arena exploding after $466165D inflicting $466185s1 Fire damage to all players plus an additional $466185s2 Fire damage every $466185T2 sec for $466185D. This effect stacks.\n\n\n\nInteracting with the ordnance instead focuses the blast inflicting $466204s1 Physical damage and applying $@spellname466246, additionally knocking back.", ua = "Боєприпаси DUD-1500 вгрузають у арену й вибухають через $466165D, завдаючи $466185s1 шкоди вогнем усім гравцям, а також додатково $466185s2 шкоди вогнем кожні $466185T2 сек. упродовж $466185D. Цей ефект накопичується.\n\n\n\nЯкщо ж взаємодіяти зі снарядом, вибух натомість фокусується, завдаючи $466204s1 фізичної шкоди й застосовуючи $@spellname466246, а також відкидаючи назад." },
    { en = "Energy surges around Gallywix inflicting $1219322s1 Nature damage every $1219319T1 sec and stunning those caught by the beam of raw lightning for $1219319D.", ua = "Енергія здіймається довкола Ґаллівікса, завдаючи $1219322s1 шкоди від сил природи щосекунди ($1219319T1) й приголомшуючи тих, кого зачепив промінь чистої блискавки, на $1219319D." },
    { en = "Targets struck by Gallywix's $@spellname466958 continually suffer the unmitigated damage as Physical damage every $T1 sec for $D. This effect stacks, adding to the effects of previous Checked Ego.", ua = "Цілі, уражені $@spellname466958 від Ґаллівікса, безперервно зазнають незменшеної шкоди як фізичної кожні $T1 сек. упродовж $D. Цей ефект накопичується, додаючись до ефектів попередніх застосувань Перевіреного Его." },
    { en = "The Plexus Sentinel relocates, pushing players away and activating the $@spellname1217649. The Atomizer slowly passes over the chamber, Atomizing any players $?DIFF16[and Volatile Manifestation][] it contacts.\n\n\n\nAfter relocating, The Plexus Sentinel begins channelling $@spellname1220618 and gains a shield that absorbs damage. Breaking this shield interrupts $@spellname1220618.", ua = "Вартовий Плексуса змінює позицію, відкидаючи гравців і активуючи $@spellname1217649. Розпорошувач повільно проходить над палатою, розпорошуючи будь-яких гравців$?DIFF16[ і нестабільні прояви][], яких торкається.\n\n\n\nЗмінивши позицію, Вартовий Плексуса починає творити $@spellname1220618 й отримує щит, що поглинає шкоду. Руйнування цього щита перериває $@spellname1220618." },
    { en = "A purging orb of arcane energy that expulses players in the area, knocking them away, and inflicting $1219471s2 Arcane damage.", ua = "Очисна сфера арканної енергії, що виганяє гравців із зони дії, відкидаючи їх і завдаючи $1219471s2 арканної шкоди." },
    { en = "The Plexus Sentinel rains lightning down after activating The Influx, inflicting $1242310s1 Arcane damage to players in a $a1 yard radius.", ua = "Вартова Плексуса проливає дощ блискавок після активації Припливу, завдаючи $1242310s1 арканної шкоди гравцям у радіусі $a1 ярдів." },
    { en = "The $@spellname1217649 inflicts $s1 Arcane Damage to players passing through the Sieve.", ua = "$@spellname1217649 завдає $s1 арканної шкоди гравцям, що проходять крізь Решето." },
    { en = "Residual energy slows players in the area by $s2% and inflicts $s1 Arcane damage every $t1 sec.", ua = "Залишкова енергія сповільнює гравців у цій зоні на $s2% і завдає $s1 арканної шкоди кожні $t1 сек." },
    { en = "The Plexus Sentinel sends an $@spellname1232268 through The Influx.", ua = "Вартовий Плексуса посилає $@spellname1232268 крізь Приплив." },
    { en = "The Plexus Sentinel sections off portions of The Influx with $@spellname1219248, inflicting $s1 Arcane damage every $t1 sec to players in the area.", ua = "Вартовий Плексуса відсікає частини Притоку за допомогою «$@spellname1219248», завдаючи $s1 арканної шкоди кожні $t1 с гравцям у зоні дії." },
    { en = "The Plexus Sentinel marks its current target, then fires an arcane charge that inflicts $1219346s3 Arcane damage to players within $1219346a3 yards, and $1219346s1 Arcane damage to all other players. Players farther from the target receive less damage. This explosion leaves behind $@spellname1219354.\n\n\n\nThe impact causes the primary target to take $1233999s1% damage from $@spellname1219263 for $1233999d.", ua = "Вартова Плексуса позначає свою поточну ціль, після чого випускає чародійський заряд, який завдає $1219346s3 арканної шкоди гравцям у межах $1219346a3 ярдів і $1219346s1 арканної шкоди решті гравців. Гравці, дальші від цілі, отримують менше шкоди. Цей вибух лишає по собі $@spellname1219354.\n\n\n\nВід влучання основна ціль отримує на $1233999s1% більше шкоди від $@spellname1219263 протягом $1233999d." },
    { en = "The Plexus Sentinel targets a player to be purged, firing $?DIFF15|DIFF16[two missiles in quick succession. Each missile inflicts][a missile inflicting] $s1 Arcane damage split evenly between players within $a1 yards$?DIFF15|DIFF16[ and knocking players away from the primary target][].$?DIFF16[\n\n\n\nIf a missile fails to hit at least 5 players, it instead inflicts $1241142s1 Arcane damage to all players.] []", ua = "Вартовий Плексуса обирає гравця для очищення, випускаючи $?DIFF15|DIFF16[дві ракети поспіль. Кожна ракета завдає][ракету, що завдає] $s1 арканної шкоди, розподіленої порівну між гравцями в радіусі $a1 м$?DIFF15|DIFF16[ і відкидаючи гравців від основної цілі][].$?DIFF16[\n\n\n\nЯкщо ракета не влучає щонайменше в 5 гравців, вона натомість завдає $1241142s1 арканної шкоди всім гравцям.] []" },
    { en = "The $@spellname1218625 detonates when touched, inflicting $s1 Arcane damage and stunning players within $a1 yards, leaving behind $@spellname1219354.\n\n\n\nAdditionally, the activating player will be teleported to a random nearby location.", ua = "$@spellname1218625 вибухає при дотику, завдаючи $s1 арканної шкоди та приголомшуючи гравців у межах $a1 ярдів, лишаючи по собі «$@spellname1219354».\n\n\n\nКрім того, гравець, що активував його, телепортується у випадкове місце поблизу." },
    { en = "The Plexus Sentinel periodically emits arcing energy, inflicting $1219687s1 Arcane damage to the target and up to $1219687X players within 20 yards.", ua = "Вартовий Плексуса періодично випускає дугоподібну енергію, завдаючи $1219687s1 арканної шкоди цілі та щонайбільше $1219687X гравцям у радіусі 20 метрів." },
    { en = "The Plexus Sentinel targets a player to be purged, firing a missile inflicting $1219611s1 Arcane damage split evenly between players within $1219611a1 yards.", ua = "Вартова Плексуса обирає гравця для очищення й випускає в нього снаряд, що завдає $1219611s1 арканної шкоди, розподіленої порівну між гравцями в межах $1219611a1 ярдів." },
    { en = "The Plexus Sentinel continuously channels arcane lightning through its chassis, inflicting $s1 Arcane damage to all players with each cast. Each cast empowers the chassis, increasing damage of subsequent casts by $s2%. This effect stacks.", ua = "Вартовий Плексуса безперервно проводить арканну блискавку крізь своє шасі, завдаючи $s1 арканної шкоди всім гравцям при кожному прочитанні. Кожне прочитання підсилює шасі, збільшуючи шкоду наступних прочитань на $s2%. Цей ефект накопичується." },
    { en = "Activates the Reshii Wraps to enter an ethereal state and making the caster immune to the $@spellname1235178.", ua = "Активує Сповивачі Решій, щоб увійти в ефірний стан і зробити заклинача несприйнятливим до $@spellname1235178." },
    { en = "The Volatile Manifestation erupts in arcane energy, inflicting $s1 Arcane damage to all players and increasing damage taken from $@spellname1235816 by $s2%.", ua = "Нестабільна Маніфестація вибухає чародійською енергією, завдаючи $s1 арканної шкоди всім гравцям і збільшуючи отримувану шкоду від $@spellname1235816 на $s2%." },
    { en = "A rotating beam of arcane energy that inflicts $s1 Arcane damage to players in the area.", ua = "Обертовий промінь арканної енергії, що завдає $s1 арканної шкоди гравцям у зоні дії." },
    { en = "The $@spellname1231803 will $@spellname1219223 all players who come in contact with it.", ua = "$@spellname1231803 застосовує «$@spellname1219223» до всіх гравців, які торкаються його." },
    { en = "The Plexus Sentinel fires Arcane energy into players, inflicting $1226752s1 Arcane damage every $t1 sec for $d. Upon expiration, a $@spellname1218626 is created.", ua = "Вартовий Плексуса випускає арканну енергію в гравців, завдаючи $1226752s1 арканної шкоди кожні $t1 с протягом $d. Після завершення створюється «$@spellname1218626»." },
    { en = "Arcane silk encases the target, stunning them for $d.", ua = "Чародійський шовк огортає ціль, оглушуючи її на $d." },
    { en = "If Writhing Wave fails to hit at least $s2 targets, Loom'ithar shields himself with the extra silk, absorbing damage taken.", ua = "Якщо Звивиста Хвиля не влучає принаймні в $s2 цілей, Лум'ітар захищає себе зайвим шовком, поглинаючи отримувану шкоду." },
    { en = "Exposure to $@spellname1247672 causes the target to take $s1% increased damage from $@spellname1247672 for $d. This effect stacks.", ua = "Контакт із $@spellname1247672 призводить до того, що ціль отримує на $s1% більше шкоди від $@spellname1247672 протягом $d. Цей ефект накопичується." },
    { en = "The chamber's arcane pylons pump energy into Loom'ithar through arcane beams, triggering an $@spellname1247029 on contact.\n\n\n\nPlayers standing within the beam block its path, suffering $1250103s1 Arcane damage and gaining an application of $@spellname1247045 every $1246990t1 sec. This effect stacks.", ua = "Чародійські пілони зали накачують енергію в Лум'ітара чародійськими променями, спричиняючи $@spellname1247029 при контакті.\n\n\n\nГравці, що стоять у промені, перекривають його шлях, отримуючи $1250103s1 арканної шкоди й одне накопичення $@spellname1247045 кожні $1246990t1 сек. Цей ефект накопичується." },
    { en = "Each Infused Tangle is protected by a barrier of silk that prevents all damage. This barrier is broken when struck by $@spellname1237907.", ua = "Кожне Просочене Сплетіння захищене бар'єром із шовку, що відвертає всю шкоду. Цей бар'єр руйнується, коли його уражає $@spellname1237907." },
    { en = "Ichor pours from Loom'ithar's wounds and inflicts $s1 Arcane damage every $t1 sec to players within its area.", ua = "Сукровиця сочиться з ран Лум'ітара й завдає $s1 арканної шкоди кожні $t1 сек гравцям у її зоні." },
    { en = "Loom'ithar unleashes $@spellname1243771 and pure arcane energy with an enraged shriek, repelling and inflicting $1227784s1 Arcane damage to all players each second for the next $1227784d.", ua = "Лум'ітар із розлюченим вереском вивільняє $@spellname1243771 та чисту чародійську енергію, відкидаючи всіх гравців і завдаючи їм $1227784s1 арканної шкоди щосекунди протягом наступних $1227784d." },
    { en = "Loom'ithar pulls several players to its location, binding them with silken strands that inflict $1238197s1 Arcane damage each second, growing in intensity over time.\n\n\n\nEach strand snaps when drawn to $s3 yards, creating a splotch of $@spellname1226322 at the player's location.", ua = "Лум'ітар притягує кількох гравців до своєї позиції, обплутуючи їх шовковими нитками, що завдають $1238197s1 арканної шкоди щосекунди, посилюючись із часом.\n\n\n\nКожна нитка рветься, коли її натягнуто до $s3 м, утворюючи пляму $@spellname1226322 на позиції гравця." },
    { en = "Loom'ithar primary attack launches silk that inflicts Physical damage to its current target.", ua = "Основна атака Лум'ітара випускає шовк, що завдає фізичної шкоди його поточній цілі." },
    { en = "Loom'ithar's excess energy radiates outward, inflicting $1231469s1 Arcane damage to all players every $t1 sec.", ua = "Надлишкова енергія Лум'ітара випромінюється назовні, завдаючи $1231469s1 арканної шкоди всім гравцям кожні $t1 сек." },
    { en = "Upon reaching 50% health, Loom'ithar rips itself free of its bindings, incurring a great wound that increases its damage taken by $1228070s1%. As it crashes down, Loom'ithar inflicts $1228069s1 Physical damage to all players and knocking them away.\n\n\n\n$@spellname1226321 pours endlessly from its severed half above.", ua = "Досягнувши 50% здоров'я, Лум'ітар силою звільняється від своїх пут, дістаючи велику рану, яка збільшує отримувану ним шкоду на $1228070s1%. Падаючи додолу, Лум'ітар завдає $1228069s1 фізичної шкоди всім гравцям і відкидає їх.\n\n\n\n$@spellname1226321 безперестанку ллється з його відсіченої половини вгорі." },
    { en = "Arcane energy rains down from the chamber above, inflicting $1226877s1 Arcane damage within $1226877a1 yards of the impact locations.", ua = "Арканна енергія сипле з палати нагорі, завдаючи $1226877s1 арканної шкоди в радіусі $1226877a1 ярдів від місць удару." },
    { en = "The $@spellname1247672' beams trigger a burst of arcane energy from within Loom'ithar, inflicting $s1 Arcane damage to all players.", ua = "Промені $@spellname1247672 спричиняють спалах чародійської енергії всередині Лум'ітара, завдаючи $s1 арканної шкоди всім гравцям." },
    { en = "Loom'ithar weaves a collapsing ring of Infused Tangles that inflict $1237307s1 Nature damage to players in their path and root them for $1237307d.\n\n\n\nDestroying an Infused Tangle removes its connecting threads.", ua = "Лум'ітар сплітає кільце Просочених Сплетінь, що стискається й завдає $1237307s1 шкоди від сил природи гравцям на своєму шляху та знерухомлює їх на $1237307d.\n\n\n\nЗнищення Просоченого Сплетіння прибирає його з'єднувальні нитки." },
    { en = "Loom'ithar unleashes a surge of silk towards its current target, inflicting $s1 Nature damage and an additional $1227163s1 Nature damage every $1227163t1 sec for $1227163d. The damage is split evenly among players in a frontal cone.", ua = "Лум'ітар вивільняє хвилю шовку в напрямку поточної цілі, завдаючи $s1 шкоди від сил природи й додатково $1227163s1 шкоди від сил природи кожні $1227163t1 сек. протягом $1227163d. Шкода розподіляється порівну між гравцями в лобовому конусі." },
    { en = "Loom'ithar inflicts $s1 Arcane damage to all players every $t1 sec for $d as it absorbs arcane energy. Then, it releases the energy in a massive explosion inflicting $1226394s1 Arcane damage to players within $1226394a1 yards.", ua = "Лум'ітар завдає $s1 арканної шкоди всім гравцям кожні $t1 сек. протягом $d, поглинаючи арканну енергію. Потім вивільняє цю енергію в потужному вибуху, завдаючи $1226394s1 арканної шкоди гравцям у радіусі $1226394a1 ярдів." },
    { en = "Tendrils of arcane silk inflict $s2 Nature damage every second and reduce movement speed by $s1%.", ua = "Пагони чародійського шовку завдають $s2 шкоди від сил природи щосекунди й знижують швидкість пересування на $s1%." },
    { en = "Loom'ithar launches a heavily infused strand through their current target at high speed, inflicting $s1 Arcane damage to all players in a line and increasing damage taken from Piercing Strand by $1237212s1% for $1237212d.", ua = "Лум'ітар запускає на високій швидкості рясно просочену нитку крізь поточну ціль, завдаючи $s1 арканної шкоди всім гравцям на лінії та збільшуючи отримувану шкоду від Пронизливої нитки на $1237212s1% протягом $1237212d." },
    { en = "The Phaseblade gains power over time, increasing its damage by $1242021s%. This effect stacks", ua = "Фазоклинок із часом набирає сили, збільшуючи свою шкоду на $1242021s%. Цей ефект накопичується" },
    { en = "The Soulbinder Naazindhri enchants the Binding Chambers with dark sigils, protecting them from Soulfray Annihilation.\n\n\n\nA sigil is destroyed when struck by Soulfire Convergence and triggers Shatterpulse.", ua = "Душезв'язувачка Наазіндрі зачаровує Камери Зв'язування темними сигілами, захищаючи їх від Знищення Зношеної Душі.\n\n\n\nСигіл руйнується, коли його уражає Збіг Душевогню, і спричиняє Скалкопульс." },
    { en = "Residual energy inflicts $1242086s1 Arcane damage every $1242086t1 sec to players within the area.", ua = "Залишкова енергія завдає $1242086s1 арканної шкоди кожні $1242086t1 сек гравцям у цій зоні." },
    { en = "The Shadowguard Assassin targets a random player, vanishing into the shadows then reappearing behind them to deliver a devastating strike infused with Shadow energy, $?diff16[inflicting  $1227051s1 Shadow damage and an additional $1227051s2 Shadow damage  every $1227051t2 sec for $1227051d to all players within the impact area.][inflicting  $1227051s1 Shadow damage and an additional $1227051s2 Shadow damage every $1227051t2 sec for $1227051d.]", ua = "Вбивця Тіньової варти обирає випадкового гравця, зникає в тінях, а потім з'являється позаду нього, щоб завдати спустошливого удару, просоченого енергією тіні, $?diff16[завдаючи $1227051s1 шкоди від тіні та додатково $1227051s2 шкоди від тіні кожні $1227051t2 сек протягом $1227051d усім гравцям у зоні влучання.][завдаючи $1227051s1 шкоди від тіні та додатково $1227051s2 шкоди від тіні кожні $1227051t2 сек протягом $1227051d.]" },
    { en = "The Binding Chamber expires and bursts outward, inflicting $1227848s2 Arcane damage.", ua = "Камера Зв'язування зникає й вибухає назовні, завдаючи $1227848s2 арканної шкоди." },
    { en = "The Soulbinder Naazindhri unleashes a devastating shockwave, inflicting $s2 Arcane damage and an additional $1242071s1 Arcane damage every $1242071t1 sec for $1242071d to them.\n\n\n\nArcane Energy lingers where players crash to the ground.", ua = "Душезв'язувачка Наазіндрі вивільняє спустошливу ударну хвилю, завдаючи $s2 арканної шкоди та додатково $1242071s1 арканної шкоди кожні $1242071t1 сек протягом $1242071d.\n\n\n\nЧародійська енергія лишається там, де гравці падають на землю." },
    { en = "An orb of energy that $?diff16[inflicts $s4 Arcane damage every $t4 sec, reduced movement speed by $s2% and haste by $s1% for $d.][inflicts $1225629s1 Arcane damage every $t2 sec, and reduced movement speed by $s1% for $d.]", ua = "Куля енергії, яка $?diff16[завдає $s4 арканної шкоди кожні $t4 сек, знижує швидкість пересування на $s2% і поспіх на $s1% протягом $d.][завдає $1225629s1 арканної шкоди кожні $t2 сек і знижує швидкість пересування на $s1% протягом $d.]" },
    { en = "The caster forth a burst of Void energy, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d to target player.", ua = "Той, хто творить закляття, вивільняє спалах енергії Порожнечі, завдаючи $s1 тіньової шкоди та додатково $s2 тіньової шкоди кожні $t2 сек. протягом $d цільовому гравцю." },
    { en = "The Soulbinder Naazindhri unleashes an orb in the direction of randomly targeted players, inflicting $1227277s1 Arcane damage to any player struck by the orb and causing them to take $1227277s2% increased damage for $1227277d.\n\n\n\n$?diff16[If a Binding Chamber is hit by the orb, its shield is destroyed and the Unbound Soul within takes $1241357s1% increased damage.][If a Binding Chamber is hit by the orb, the Unbound Soul within takes $1241357s1% increased damage.]", ua = "Душезв'язувачка Наазіндрі вивільняє кулю в напрямку випадково обраних гравців, завдаючи $1227277s1 арканної шкоди будь-якому гравцеві, ураженому кулею, і змушуючи його отримувати на $1227277s2% більше шкоди протягом $1227277d.\n\n\n\n$?diff16[Якщо куля влучає в Камеру Зв'язування, її щит руйнується, і Звільнена Душа всередині отримує на $1241357s1% більше шкоди.][Якщо куля влучає в Камеру Зв'язування, Звільнена Душа всередині отримує на $1241357s1% більше шкоди.]" },
    { en = "The Soulbinder Naazindhri activates chambers throughout the room, transforming unbound souls within each chamber to join the Shadowguard. Souls within each chamber are protected as long as the chamber's shield holds.", ua = "Душезв'язувачка Наазіндрі активує камери по всій залі, перетворюючи незв'язані душі в кожній камері на бійців Тіньової варти. Душі в кожній камері захищені, доки тримається щит камери." },
    { en = "The Soulbinder Naazindhri lashes out at her current target, inflicting $1237629s1 Arcane damage every $t1 sec for $d. $?diff15,diff16[The blow brands the victim, increasing the damage of Mystic Lash by \n\n $1237607s1% and Physical damage by $1237607s2% for $1237607d.\n\n\n\nThis effect stacks. \n\n][The blow brands the victim, increasing the damage of Mystic Lash by $1248464s1%.\n\n\n\nThis effect stacks.]", ua = "Душезв'язувачка Наазіндрі завдає удару по своїй поточній цілі, завдаючи $1237629s1 арканної шкоди кожні $t1 сек протягом $d. $?diff15,diff16[Удар таврує жертву, збільшуючи шкоду Містичного Батога на \n\n $1237607s1% і фізичну шкоду на $1237607s2% протягом $1237607d.\n\n\n\nЦей ефект накопичується. \n\n][Удар таврує жертву, збільшуючи шкоду Містичного Батога на $1248464s1%.\n\n\n\nЦей ефект накопичується.]" },
    { en = "The Soulbinder Naazindhri courses arcane energy through the bodies of several players, inflicting $1249065s1 Arcane damage every $1249065t1 sec for $1249065d.\n\n \n\nUpon expiration, Soulrend Orbs explode from the target's body.", ua = "Душезв'язувачка Наазіндрі пропускає чародійську енергію крізь тіла кількох гравців, завдаючи $1249065s1 арканної шкоди щосекунди протягом $1249065d (інтервал $1249065t1 сек).\n\n \n\nКоли ефект спадає, з тіла цілі вибухають Сфери Душороздиру." },
    { en = "The Soulbinder Naazindhri radiates Arcane energy, inflicting $1240763s1 Arcane damage to all players every $t sec.", ua = "Душезв'язувачка Наазіндрі випромінює чародійську енергію, завдаючи $1240763s1 арканної шкоди всім гравцям кожні $t сек." },
    { en = "The Soulbinder Naazindhri unleashes a devastating shockwave, inflicting $s2 Arcane damage and an additional $s3 Arcane damage every $t3 sec for $d to them.", ua = "Душезв'язувачка Наазіндрі вивільняє нищівну ударну хвилю, завдаючи $s2 арканної шкоди та ще $s3 арканної шкоди кожні $t3 сек протягом $d." },
    { en = "The Unbound Soul is slowly wrapped in silk bindings, transforming into a member of the Shadowguard.", ua = "Незв'язану душу поволі сповивають шовкові нитки, перетворюючи її на члена Тіньової варти." },
    { en = "A shattering Arcane Sigil sends out a pulse of energy, applying a $s1 healing absorb shield to all players.", ua = "Розколовшись, Чародійська печатка випускає імпульс енергії, накладаючи на всіх гравців щит, що поглинає $s1 зцілення." },
    { en = "The Shadowguard Phaseblade sears the target inflicting $s1 Shadow damage. The power of Void that scatters after impact jumps between all players, inflicting $s1 Shadow damage.", ua = "Фазовий клинок Тіньової варти випалює ціль, завдаючи $s1 шкоди від тіні. Сила Порожнечі, що розсіюється після удару, перестрибує між усіма гравцями, завдаючи $s1 шкоди від тіні." },
    { en = "Escaping energy from the manaforge inflicts $1240708s1 Arcane damage every $t1 sec for $d. This effect stacks.", ua = "Енергія, що вихоплюється з манакузні, завдає $1240708s1 арканної шкоди кожні $t1 сек протягом $d. Цей ефект накопичується." },
    { en = "Araz sacrifices his essence to power the manaforge, stunning him and increasing his damage taken by $s1% for $d.", ua = "Араз жертвує свою есенцію, щоб живити манакузню, через що його приголомшено, а отримувана ним шкода зростає на $s1% протягом $d." },
    { en = "The destroyed collector causes a breach,  inflicting $s1 Arcane damage every $1243165t1 sec to players.", ua = "Знищений збирач спричиняє розлом, завдаючи гравцям $s1 арканної шкоди кожні $1243165t1 сек." },
    { en = "Araz abandons the ritual at $s2% health and opens a $@spellname1233076, inflicting $s1 Shadow damage to all players.", ua = "Сягнувши $s2% здоров'я, Араз полишає ритуал і відкриває $@spellname1233076, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "Upon reaching full energy the Arcane Collector channels into the Manaforge, inflicting $s1 Arcane damage to all players every $1232590t1 sec for $1232590d.", ua = "Досягнувши повної енергії, Чародійський збирач підтримує її в манакузню, завдаючи $s1 арканної шкоди всім гравцям кожні $1232590t1 сек протягом $1232590d." },
    { en = "The Arcane Collector emits an energy beam, inflicting $1234324s1 Arcane damage to players in the area. Victims suffer an additional $1234324s2 Arcane damage every $1234324t2 sec for $1234324d.", ua = "Чародійський збирач випускає промінь енергії, завдаючи $1234324s1 арканної шкоди гравцям у зоні. Постраждалі отримують ще $1234324s2 арканної шкоди кожні $1234324t2 сек протягом $1234324d." },
    { en = "The Manaforge becomes unstable causing energy to erupt at random destinations, inflicting $s1 Arcane damage to players within $a1 yards of the impact locations.", ua = "Манакузня стає нестабільною, через що енергія вивергається у випадкових місцях, завдаючи $s1 арканної шкоди гравцям у межах $a1 ярдів від точок влучання." },
    { en = "Araz rains down arcane energy at players' destinations every $t1 sec for $d, inflicting $1228168s1 Arcane damage to players within $1228168A1 yards of the impact location and silencing them for $1228168d.", ua = "Араз обрушує чародійську енергію на місця, де стоять гравці, кожні $t1 сек протягом $d, завдаючи $1228168s1 арканної шкоди гравцям у межах $1228168A1 ярдів від точки влучання та сковуючи їхню мову на $1228168d." },
    { en = "Energy focused through the manaforge inflicts $s1 Arcane damage every $t1 sec to players within the iris.", ua = "Енергія, сфокусована крізь манакузню, завдає $s1 арканної шкоди кожні $t1 сек гравцям усередині райдужки." },
    { en = "While the Forgeweaver and his echoes are within $a1 yards of each other, their damage done increases by $s1% and their damage received is reduced by $s2%.", ua = "Поки Ткач Кузні та його відлуння перебувають у межах $a1 ярдів одне від одного, завдавана ними шкода зростає на $s1%, а отримувана зменшується на $s2%." },
    { en = "The Arcane Collector creates a Void Tear capable of consuming large amounts of arcane power, inflicting $s1 Shadow damage every $t1 sec to players within them.", ua = "Чародійський збирач створює Розрив Порожнечі, здатний поглинати велику кількість чародійської сили, завдаючи $s1 шкоди від тіні кожні $t1 сек гравцям усередині нього." },
    { en = "The crushing force of the $@spellname1233073  inflicts $s1 Shadow damage every $t1 sec to players beyond the event horizon.", ua = "Нищівна сила $@spellname1233073 завдає $s1 шкоди від тіні кожні $t1 сек гравцям за межами горизонту подій." },
    { en = "A singularity erupts within the forge, inflicting $1233301s1 Shadow damage every $1233300t1 sec to players and pulling them into its $@spellname1233074. Over time, the strength of this movement force increases.", ua = "Усередині кузні вибухає сингулярність, завдаючи $1233301s1 шкоди від тіні кожні $1233300t1 сек гравцям і затягуючи їх у свій $@spellname1233074. З часом сила цього тяжіння зростає." },
    { en = "The Arcane Collector draws energy from several players, inflicting $1244998s1 Arcane damage every $t1 sec for $d. Upon expiration, an $@spellname1228211 forms at each player's location.", ua = "Чародійський збирач витягує енергію з кількох гравців, завдаючи $1244998s1 арканної шкоди кожні $t1 сек протягом $d. Коли ефект спадає, на місці кожного гравця утворюється $@spellname1228211." },
    { en = "Araz unleashes a burst of energy onto his current target, inflicting $s1 Arcane damage to all players. The damage is reduced by the number of players within $1228217A1 yards of the impact location. $?diff15|diff16 [\n\n\n\nPlayers within $1228217A1 yards of the impact location also have $1232775s1 healing absorbed and suffer $@spellname1228219.][]$?diff14|diff15|diff16 [\n\n\n\nAdditionally an $@spellname1228220 is summoned at the location.][]", ua = "Араз вивільняє сплеск енергії на свою поточну ціль, завдаючи $s1 арканної шкоди всім гравцям. Шкода зменшується залежно від кількості гравців у межах $1228217A1 ярдів від точки влучання. $?diff15|diff16 [\n\n\n\nГравці в межах $1228217A1 ярдів від точки влучання також отримують поглинання $1232775s1 зцілення та зазнають $@spellname1228219.][]$?diff14|diff15|diff16 [\n\n\n\nКрім того, на цьому місці прикликається $@spellname1228220.][]" },
    { en = "Araz's $@spellname1228218 marks the player with residual energy, removing their ability to reduce the damage from this spell's next cast for $d.", ua = "$@spellname1228218 Араза позначає гравця залишковою енергією, позбавляючи його здатності зменшувати шкоду від наступного застосування цього закляття протягом $d." },
    { en = "The Arcane Collector thrums with power, inflicting $s1 Arcane damage to all players every $1228100t1 sec.", ua = "Чародійський збирач гуде від сили, завдаючи $s1 арканної шкоди всім гравцям кожні $1228100t1 сек." },
    { en = "Manifestations become empowered, reducing all incoming damage by $s1%.", ua = "Прояви набувають могутності, зменшуючи всю отримувану шкоду на $s1%." },
    { en = "The Arcane Collector activates, unleashing motes of energy that inflict $s1 Arcane damage to players in their path.", ua = "Чародійський збирач активується, вивільняючи частинки енергії, що завдають $s1 арканної шкоди гравцям на своєму шляху." },
    { en = "Araz's echo triggers an Arcane Collector to begin its $@spellname1237322.", ua = "Відлуння Араза спонукає Чародійський збирач почати свій $@spellname1237322." },
    { en = "The Forgeweaver blasts his current target, inflicting $1228510s1 Arcane damage every $1228506t1 sec for $1228506d. This effect stacks.", ua = "Ткач Кузні обрушується на свою поточну ціль вибухом, завдаючи $1228510s1 арканної шкоди кожні $1228506t1 сек протягом $1228506d. Цей ефект накопичується." },
    { en = "Araz's echo rains down arcane energy at players' destinations every $t1 sec for $d, inflicting $1228168s1 Arcane damage to players within $1228168A1 yards of the impact location and silencing them for $1228168d.", ua = "Відлуння Араза обрушує чародійську енергію на місця, де стоять гравці, кожні $t1 сек протягом $d, завдаючи $1228168s1 арканної шкоди гравцям у межах $1228168A1 ярдів від точки влучання та сковуючи їхню мову на $1228168d." },
    { en = "Araz erupts as his form is torn apart, inflicting $s1 Arcane damage to all players and knocking them back.", ua = "Араз вибухає, коли його форму розриває на шматки, завдаючи $s1 арканної шкоди всім гравцям і відкидаючи їх назад." },
    { en = "The Shielded Attendant periodically gains a shield that absorbs the next $s1 damage.", ua = "Захищений прислужник періодично отримує щит, що поглинає наступні $s1 одиниць шкоди." },
    { en = "Araz triggers one of his Arcane Collectors to begin its $@spellname1237322.", ua = "Араз спонукає один зі своїх Чародійських збирачів почати свій $@spellname1237322." },
    { en = "The Arcane Collector erects a barrier, reducing its damage taken by $s1%.", ua = "Чародійський збирач зводить бар'єр, зменшуючи отримувану ним шкоду на $s1%." },
    { en = "The Arcane Collector surges with energy if it contacts an Arcane Manifestation, inflicting $s1 Arcane damage to all players and an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Чародійський збирач наповнюється енергією, торкнувшись Чародійського прояву, завдаючи $s1 арканної шкоди всім гравцям і ще $s2 арканної шкоди кожні $t2 сек протягом $d." },
    { en = "Araz unleashes energy as he begins a ritual, inflicting $s2 Arcane damage to all players and knocking them back.", ua = "Араз вивільняє енергію, починаючи ритуал, завдаючи $s2 арканної шкоди всім гравцям і відкидаючи їх назад." },
    { en = "The $@spellname1233299 surges with energy if it contacts an Void Manifestation, inflicting $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "$@spellname1233299 наповнюється енергією, торкнувшись Прояву Порожнечі, завдаючи $s1 шкоди від тіні всім гравцям і ще $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "With each consecutive melee attack against the same target, the casters' attack speed increases by $s1%.\n\n\n\nThis effect stacks.", ua = "З кожною наступною ближньою атакою по тій самій цілі швидкість атаки заклинача зростає на $s1%.\n\n\n\nЦей ефект накопичується." },
    { en = "The $@spellname1233299 draws energy from several players, inflicting $1245002s1 Shadow damage every $t1 sec for $d. Upon expiration, a  $@spellname1243333 forms at each player's location", ua = "$@spellname1233299 витягує енергію з кількох гравців, завдаючи $1245002s1 шкоди від тіні кожні $t1 сек протягом $d. Коли ефект спадає, на місці кожного гравця утворюється $@spellname1243333." },
    { en = "Adarus drains the essence of players afflicted with $@spellname1222232, inflicting $1235158s1 Cosmic damage and absorbing the next $1222307s1 healing received.$?|diff15|diff16[\n\n\n\nThis blast applies $@spellname1222310.][]", ua = "Адарус висмоктує есенцію гравців, уражених $@spellname1222232, завдаючи $1235158s1 космічної шкоди та поглинаючи наступні $1222307s1 отриманого зцілення.$?|diff15|diff16[\n\n\n\nЦей вибух накладає $@spellname1222310.][]" },
    { en = "Ilyssa explodes, inflicting $s1 Fire damage to all players and applying $@spellname1242284.\n\n\n\nIlyssa destroys any fragments still present from $@spellname1241833, applying $@spellname1242304 to all players.", ua = "Ілісса вибухає, завдаючи $s1 шкоди вогнем усім гравцям і накладаючи $@spellname1242284.\n\n\n\nІлісса знищує всі уламки, що ще лишилися від $@spellname1241833, накладаючи $@spellname1242304 на всіх гравців." },
    { en = "The casters bind several players together for $d, causing them to snap towards each other and suffer $1243162s1 Chaos damage if they move further than $s1 yards apart.", ua = "Закляттяри зв'язують кількох гравців між собою на $d, через що тих різко притягує одне до одного, і вони зазнають $1243162s1 шкоди від хаосу, якщо віддаляються більш ніж на $s1 ярдів." },
    { en = "Velaryn marks a player as her prey, charging towards them and inflicting $1227823s1 Chaos damage. This effect is reduced for each player standing within the path of $@spellname1227809.\n\n\n\n$?|diff15|diff16 [Velaryn additionally strikes players along the path, inflicting $1227846s1 Chaos damage to players within $1227846A1 yards of each player struck.][Velaryn additionally strikes players along the path, inflicting $1227846s1 Chaos damage to players struck.]", ua = "Веларін позначає гравця як свою здобич, кидається на нього і завдає $1227823s1 шкоди від хаосу. Цей ефект послаблюється за кожного гравця, який стоїть на шляху $@spellname1227809.\n\n\n\n$?|diff15|diff16 [Веларін також б'є гравців уздовж шляху, завдаючи $1227846s1 шкоди від хаосу гравцям у межах $1227846A1 ярдів від кожного враженого.][Веларін також б'є гравців уздовж шляху, завдаючи $1227846s1 шкоди від хаосу враженим гравцям.]" },
    { en = "Images of Adarus slice open the fabric of the void around them, inflicting $s1 Cosmic damage to players within $A1 yards and coalescing a pool of $@spellname1235045.", ua = "Образи Адаруса розтинають тканину Порожнечі довкола себе, завдаючи $s1 космічної шкоди гравцям у межах $A1 ярдів і збираючи калюжу $@spellname1235045." },
    { en = "Adarus withers their target, increasing the damage and healing absorb taken from $@spellname1222244 by $s1% for $d. This effect stacks.", ua = "Адарус виснажує свою ціль, збільшуючи отриману шкоду та поглинання зцілення від $@spellname1222244 на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Velaryn charges to her current target, inflicting $1225130s1 Fire damage and an additional $1225130s2 Fire damage every $1225130t2 sec for $1225130d.", ua = "Веларін кидається на свою поточну ціль, завдаючи $1225130s1 шкоди вогнем і додатково $1225130s2 шкоди вогнем кожні $1225130t2 с протягом $1225130d." },
    { en = "$@spellname1242259 causes players to absorb the next $s1 healing received.", ua = "$@spellname1242259 змушує гравців поглинути наступні $s1 отриманого зцілення." },
    { en = "Velaryn wreathes the arena in flame, inflicting $1245384s1 Fire damage to all players and an additional $1245384s2 Fire damage every $1245384t2 sec for $1245384d when each pillar of the inferno is created. This effect stacks.\n\n\n\nThe flame inflicts $s1 Fire damage every $t1 sec to any players who step into the firestorm.", ua = "Веларін огортає арену полум'ям, завдаючи $1245384s1 шкоди вогнем усім гравцям і додатково $1245384s2 шкоди вогнем кожні $1245384t2 с протягом $1245384d щоразу, коли постає стовп пекельного вогню. Цей ефект накопичується.\n\n\n\nПолум'я завдає $s1 шкоди вогнем кожні $t1 с будь-яким гравцям, які заходять у вогняну бурю." },
    { en = "When any of the Soul Hunters are slain, their soul begins to pulse with power, inflicting $1237767s1 Cosmic or Chaos damage to all players every $1237735t1 sec. This effect increases in strength by $1237742s1% each pulse.", ua = "Коли когось із Мисливців на душі вбито, його душа починає пульсувати силою, завдаючи $1237767s1 космічної шкоди або шкоди від хаосу всім гравцям кожні $1237735t1 с. Сила цього ефекту зростає на $1237742s1% з кожним пульсом." },
    { en = "Adarus conjures a scythe-wielding shadow that dashes behind players and cleaves through them, inflicting $1245726s1 Cosmic damage to all players struck.", ua = "Адарус прикликає тінь із косою, що проноситься за спинами гравців і розсікає їх, завдаючи $1245726s1 космічної шкоди всім враженим гравцям." },
    { en = "The $@spellname1233093 inflicts $s1 Cosmic damage every $t1 sec to players within its mass.", ua = "$@spellname1233093 завдає $s1 космічної шкоди кожні $t1 с гравцям усередині своєї маси." },
    { en = "Velaryn channels a torrent of Fel energy towards her current target for $d, inflicting $1221477s1 Chaos damage and applying $@spellname1221490 every ${$s1/2}.1 sec to players within the beam and blasting them away.\n\n\n\nAfter the blast concludes, Velaryn will $@spellname1225127 towards her current target.", ua = "Веларін спрямовує потік енергії Скверни на свою поточну ціль протягом $d, завдаючи $1221477s1 шкоди від хаосу та накладаючи $@spellname1221490 кожні ${$s1/2}.1 с на гравців у промені й відкидаючи їх.\n\n\n\nПісля завершення спалаху Веларін застосує $@spellname1225127 проти своєї поточної цілі." },
    { en = "Velaryn exposes any players struck along the path of $@spellname1227846, increasing their damage taken from standing in the path of $@spellname1227846 by $s1% for $d.", ua = "Веларін робить уразливими всіх гравців, вражених уздовж шляху $@spellname1227846, збільшуючи шкоду, яку вони отримують від перебування на шляху $@spellname1227846, на $s1% протягом $d." },
    { en = "Ilyssa places a Sigil of Chains at their current target's location that activates after ${$s1/2}.1 sec.\n\n\n\nAll players are pulled to its center and snared, reducing movement speed by $1223624s1% for $1223624d.", ua = "Ілісса розміщує Знак ланцюгів у місці перебування своєї поточної цілі, що активується за ${$s1/2}.1 с.\n\n\n\nУсіх гравців притягує до його центру і сковує, зменшуючи швидкість пересування на $1223624s1% протягом $1223624d." },
    { en = "The fragment draws upon the target's soul, reducing their healing received by $s1%. This effect stacks.\n\n\n\nPlayers other than the target can collect the fragment, suffering $1254762s1 Chaos damage every $1241946t1 sec for $1241946d. This effect stacks.", ua = "Уламок зачерпує душу цілі, зменшуючи отримане нею зцілення на $s1%. Цей ефект накопичується.\n\n\n\nГравці, окрім цілі, можуть підібрати уламок, зазнаючи $1254762s1 шкоди від хаосу кожні $1241946t1 с протягом $1241946d. Цей ефект накопичується." },
    { en = "$@spellname1242259 explodes any splintered fragments remaining from $@spellname1241833, inflicting $s1 Fire damage to all players plus an additional $s2 Fire damage every $t2 sec for $d. This effect stacks.", ua = "$@spellname1242259 підриває всі розщеплені уламки, що лишилися від $@spellname1241833, завдаючи $s1 шкоди вогнем усім гравцям, а також додатково $s2 шкоди вогнем кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Ilyssa engulfs themselves in flame, inflicting $1225155s1 Chaos damage to all players every $t1 sec.", ua = "Ілісса огортає себе полум'ям, завдаючи $1225155s1 шкоди від хаосу всім гравцям кожні $t1 с." },
    { en = "Adarus manifests a Collapsing Star which begins to pull players towards its center.\n\n\n\nStellar fragments rain down and are pulled towards the center of the star. The fragments explode upon contacting a player, inflicting $1233103s1 Cosmic damage$?|diff15|diff16[ and applying $@spellname1233105.][.]\n\n\n\nIf the fragments reach the center, they instead inflict $1233104s1 Cosmic damage to all players.", ua = "Адарус являє Колапсуючу Зорю, що починає притягувати гравців до свого центру.\n\n\n\nЗоряні уламки сиплються дощем і притягуються до центру зорі. Уламки вибухають від дотику до гравця, завдаючи $1233103s1 космічної шкоди$?|diff15|diff16[ і накладаючи $@spellname1233105.][.]\n\n\n\nЯкщо уламки досягають центру, вони натомість завдають $1233104s1 космічної шкоди всім гравцям." },
    { en = "Velaryn manifests echoes of herself for $d which rush forward, incinerating anything in their path for $1223080s1 Chaos damage.", ua = "Веларін являє відлуння себе протягом $d, які мчать уперед, спопеляючи все на своєму шляху, завдаючи $1223080s1 шкоди від хаосу." },
    { en = "The stellar residue burns, inflicting $s1 Cosmic damage every $t1 sec for $d. This effect stacks.", ua = "Зоряний залишок палає, завдаючи $s1 космічної шкоди кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Adarus hurls orbs of ravenous void at several locations, inflicting $1226330s1 Cosmic damage to all players if not intercepted.\n\n\n\nAdarus focuses his gaze upon players who intercepted these orbs, continually assailing them with $@spellname1222244 and increasing their Physical damage taken by $1222232s3%.\n\n\n\nUpon removal, $@spellname1222232 transfers to a nearby player and inflicts $1226539s1 Cosmic damage to all players.", ua = "Адарус жбурляє кулі ненаситної Порожнечі в кілька місць, завдаючи $1226330s1 космічної шкоди всім гравцям, якщо їх не перехопити.\n\n\n\nАдарус зосереджує погляд на гравцях, які перехопили ці кулі, безперервно атакуючи їх за допомогою $@spellname1222244 і збільшуючи отриману ними фізичну шкоду на $1222232s3%.\n\n\n\nПісля зняття $@spellname1222232 переходить на найближчого гравця і завдає $1226539s1 космічної шкоди всім гравцям." },
    { en = "Velaryn rapidly slashes at nearby locations, inflicting $s1 Chaos damage to players caught in the effect.", ua = "Веларін стрімко розсікає сусідні місця, завдаючи $s1 шкоди від хаосу гравцям, що потрапили під ефект." },
    { en = "Adarus tears open a path through the void and teleports to a new location, inflicting $1237205s1 Cosmic damage to players within $1237205A1 yards along the path to his destination.\n\n\n\nDuring this movement, Adarus manifests images of himself which cast $@spellname1227685.", ua = "Адарус прориває шлях крізь Порожнечу і телепортується в нове місце, завдаючи $1237205s1 космічної шкоди гравцям у межах $1237205A1 ярдів уздовж шляху до пункту призначення.\n\n\n\nПід час цього руху Адарус являє образи себе, що творять $@spellname1227685." },
    { en = "A growing expanse of void opens, inflicting $s1 Cosmic damage every $t1 sec to players within and increasing their damage taken by $s2%.\n\n\n\nThe void spreads over time, but players afflicted with $@spellname1222232 can greedily consume the essence and reduce its size.", ua = "Розкривається дедалі ширша пройма Порожнечі, завдаючи $s1 космічної шкоди кожні $t1 с гравцям усередині й збільшуючи отриману ними шкоду на $s2%.\n\n\n\nПорожнеча поширюється з часом, але гравці, вражені $@spellname1222232, можуть жадібно поглинати есенцію і зменшувати її розмір." },
    { en = "Ilyssa's torrent of Fel withers her targets, reducing their movement speed by $s1% for $d. This effect stacks.", ua = "Потік Скверни Ілісси висушує її цілі, зменшуючи їхню швидкість пересування на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Ilyssa rapidly slashes her current target, inflicting $s1 Physical damage and applying $@spellname1226493.\n\n\n\nThis strike cleaves the target's soul into fragments which each maintain $@spellname1241917 on the target until another player collects the fragment.", ua = "Ілісса стрімко розсікає свою поточну ціль, завдаючи $s1 фізичної шкоди й накладаючи $@spellname1226493.\n\n\n\nЦей удар розсікає душу цілі на уламки, кожен з яких підтримує $@spellname1241917 на цілі, доки інший гравець не підбере уламок." },
    { en = "Ilyssa leaps to a location, inflicting $1227340s1 Fire damage to all players within $1227340A1 yards and knocking them away.", ua = "Ілісса стрибає в певне місце, завдаючи $1227340s1 шкоди вогнем усім гравцям у межах $1227340A1 ярдів і відкидаючи їх." },
    { en = "Ilyssa unleashes the Fel within, inflicting $1227119s1 Fire damage every $t2 sec to all players within the effect for $d.", ua = "Ілісса вивільняє Скверну зсередини, завдаючи $1227119s1 шкоди вогнем кожні $t2 с усім гравцям у зоні ефекту протягом $d." },
    { en = "$?|diff16 [Increases the damage taken from $@spellname1221477 by $s1% and $@spellname1225127 by $s2% for $d. This effect stacks.][Increases the damage taken from $@spellname1221477 by $s1% for $d. This effect stacks.]", ua = "$?|diff16 [Збільшує шкоду, отриману від $@spellname1221477, на $s1% і від $@spellname1225127 на $s2% протягом $d. Цей ефект накопичується.][Збільшує шкоду, отриману від $@spellname1221477, на $s1% протягом $d. Цей ефект накопичується.]" },
    { en = "Ilyssa shatters the target's soul, increasing their damage taken from $@spellname1222337 by $s2% for $d.", ua = "Ілісса розколює душу цілі, збільшуючи отриману нею шкоду від $@spellname1222337 на $s2% протягом $d." },
    { en = "Dark energy infuses multiple players with void, inflicting $s1 Shadow damage every $t1 sec for $d.\n\n\n\n$@spellname1247495 is triggered upon expiration.", ua = "Темна енергія наповнює кількох гравців Порожнечею, завдаючи $s1 шкоди Тінню кожні $t1 с протягом $d.\n\n\n\nПісля завершення спрацьовує $@spellname1247495." },
    { en = "Shrapnel erupts from a broken Crystal Nexus, inflicting $s1 Shadow damage to players within $A1 yards.", ua = "Шрапнель вибухає з розбитого Кристалічного Нексуса, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів." },
    { en = "The player explodes, inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Гравець вибухає, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 ярдів." },
    { en = "A crystalline wall of void energy which explodes upon impact with a player affected by $@spellname1227378. The explosion launches $@spellname1232130.", ua = "Кристалічна стіна з енергії Порожнечі, що вибухає від зіткнення з гравцем, враженим $@spellname1227378. Вибух запускає $@spellname1232130." },
    { en = "Fractillus does a sweeping backhand, inflicting $s2 Shadow damage to all players and knocking back players afflicted by $@spellname1227378.", ua = "Фрактіллус робить розмашистий удар тильним боком руки, завдаючи $s2 шкоди від тіні всім гравцям і відкидаючи гравців, вражених $@spellname1227378." },
    { en = "Fractillus begins crystallizine several players, inflicting $s1 Shadow damage every $t1 seconds for $d.\n\n\n\nUpon expiration, the player is crystallized and rooted for $1227378d.", ua = "Фрактілус починає кристалізувати кількох гравців, завдаючи $s1 тіньової шкоди кожні $t1 сек. протягом $d.\n\n\n\nПісля завершення гравець кристалізується й знерухомлюється на $1227378d." },
    { en = "A crystalline wall of void energy which explodes upon impact with a player affected by $@spellname1227378. The explosion launches $@spellname1232130 and applies $@spellname1232760 to all players.", ua = "Кристалічна стіна з енергії Порожнечі, що вибухає від зіткнення з гравцем, враженим $@spellname1227378. Вибух запускає $@spellname1232130 і накладає $@spellname1232760 на всіх гравців." },
    { en = "A crystalline wall of void energy which explodes upon impact with a player affected by $@spellname1227378. The explosion launches $@spellname1232130 and applies $@spellname1232130 to several players.", ua = "Кристалічна стіна з енергії Порожнечі, що вибухає від зіткнення з гравцем, враженим $@spellname1227378. Вибух запускає $@spellname1232130 і накладає $@spellname1232130 на кількох гравців." },
    { en = "The crystal nexus emits amplified void energy, inflicting $s1 Shadow damage every $t1 sec.", ua = "Кристалічний нексус випромінює підсилену енергію Порожнечі, завдаючи $s1 шкоди від тіні щосекунди ($t1)." },
    { en = "The target becomes crystal, rooting them in place for $d.", ua = "Ціль перетворюється на кристал, що знерухомлює її на $d." },
    { en = "Razor sharp void crystals explode from the brittle nexus, inflicting $s1 Shadow damage every $t1 sec for $d to all players. This effect stacks.", ua = "З крихкого нексуса вибухають гострі, мов лезо, кристали Порожнечі, завдаючи всім гравцям $s1 шкоди від тіні кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Six dark crystals that emit $@spellname1241137 in a line towards Fractillus, inflicting $1241137s1 Shadow damage every $1241137t1 sec to players touching it.", ua = "Шість темних кристалів випромінюють $@spellname1241137 лінією в напрямку Фрактіллуса, завдаючи гравцям, які торкаються її, $1241137s1 шкоди від тіні кожні $1241137t1 с." },
    { en = "Fractillus becomes empowered by $@spellname1241137, increasing the damage it does by $s1% and triggers $@spellname1225673.", ua = "Фрактіллус отримує наснагу від $@spellname1241137, що підвищує завдану ним шкоду на $s1% і запускає $@spellname1225673." },
    { en = "Fractillus unleashes a sequence of crystal shockwaves, inflicting $s1 Shadow damage every $t1 sec for $d to anyone hit and creates a nexus.", ua = "Фрактіллус вивільняє низку кристалічних ударних хвиль, завдаючи $s1 шкоди від тіні кожні $t1 с протягом $d кожному ураженому й створюючи нексус." },
    { en = "Fractillus slams his target, inflicting $s1 Physical damage, increases damage taken from Physical damage by $s2% for $d and triggers a $@spellname1224414.", ua = "Фрактіллус б'є свою ціль, завдаючи $s1 фізичної шкоди, підвищує фізичну шкоду, що вона зазнає, на $s2% протягом $d і запускає $@spellname1224414." },
    { en = "The Voidwing unleashes a galactic beam from its jaws for $d, inflicting $1236872s1 Cosmic damage to any player within it every $1228196t1 sec.\n\n\n\nSeveral portals tear open, from which this breath is emitted in additional directions.", ua = "Войдвінг вивільняє з пащі галактичний промінь на $d, завдаючи $1236872s1 космічної шкоди будь-якому гравцю в ньому кожні $1228196t1 сек.\n\n\n\nРозчахуються кілька порталів, з яких цей подих вихоплюється в додаткових напрямках." },
    { en = "Salhadaar exiles several players, inflicting $1227554s1 Shadow damage every $1227549t1 sec for $1227549d. \n\n\n\nUpon expiration, each target bursts with torturous void inflicting $1227562s1 Shadow damage.", ua = "Салгадаар виганяє кількох гравців, завдаючи $1227554s1 шкоди від тіні кожні $1227549t1 с протягом $1227549d. \n\n\n\nПісля закінчення кожна ціль вибухає стражденною Порожнечею, завдаючи $1227562s1 шкоди від тіні." },
    { en = "A star materializes from the Twisting Nether, pulling players towards its center for $d. \n\n\n\nUpon emergence, players within the $@spellname1225405 are $@spellname1225444 as $@spellname1225645 ripple outward. Inflicts $1225452s1 Cosmic damage to all players every $s1 sec.", ua = "Зоря виникає з Викривленого Нижнього Світу, притягуючи гравців до свого центру протягом $d. \n\n\n\nПісля появи гравці в межах $@spellname1225405 зазнають $@spellname1225444, тоді як $@spellname1225645 розходяться навсібіч. Завдає $1225452s1 космічної шкоди всім гравцям кожні $s1 с." },
    { en = "The Royal Voidwing splits into several cosmic images that mirror its attacks.", ua = "Королівське крило Порожнечі розділяється на кілька космічних подоб, що віддзеркалюють його атаки." },
    { en = "The automaton fires a barrage of dark missiles, inflicting $1232403s1 Shadow damage within $1232403A1 yards of each impact.", ua = "Автоматон випускає шквал темних снарядів, завдаючи $1232403s1 шкоди від тіні в межах $1232403A1 м від кожного влучання." },
    { en = "The $@spellname1225405 orbits around the arena.", ua = "$@spellname1225405 кружляє довкола арени." },
    { en = "The ethereal shadowsteps behind a player and slashes through them, inflicting $1228056s1 Shadow damage and an additional $1228056s2 Shadow damage every $1228056t2 sec for $1228056d.", ua = "Ефіріал крізь тінь переноситься за спину гравця й розтинає його, завдаючи $1228056s1 шкоди від тіні та ще $1228056s2 шкоди від тіні кожні $1228056t2 с протягом $1228056d." },
    { en = "Images of Salhadaar emerge alongside him to smash their targets with galactic force, applying $@spellname1226362 and inflicting $1225331s1 Cosmic damage to all players. Players farther from each target take less damage. \n\n\n\nSalhadaar's primary target is $@spellname1226417. A $@spellname1225405 forms at each impact location.", ua = "Поряд із Салгадааром постають його подоби, які трощать свої цілі галактичною силою, накладаючи $@spellname1226362 й завдаючи $1225331s1 космічної шкоди всім гравцям. Гравці, що далі від кожної цілі, дістають менше шкоди. \n\n\n\nГоловна ціль Салгадаара — $@spellname1226417. У кожному місці удару утворюється $@spellname1225405." },
    { en = "Salhadaar declares a trial of loyalty, inflicting $1224734s1 Shadow damage to all players every $t1 sec for $d and granting $s1 applications of $@spellname1224737.", ua = "Салгадаар проголошує випробування відданості, завдаючи $1224734s1 тіньової шкоди всім гравцям кожні $t1 сек. протягом $d та надаючи $s1 зарядів ефекту $@spellname1224737." },
    { en = "Salhadaar summons a wave of Shadowguard that arrive at each side of the loading bay.", ua = "Салгадаар прикликає хвилю Тіньової варти, що прибуває з обох боків вантажного відсіку." },
    { en = "$@spellname1225645 close in from all sides, engulfing the arena in a sea of cosmic evisceration.", ua = "$@spellname1225645 насуваються з усіх боків, поглинаючи арену в море космічного потрошіння." },
    { en = "The ethereal blasts cosmic beams in several directions. Contact with any beam inflicts $1228080s1 Shadow damage every $1228081t1 sec.", ua = "Ефіріал випускає космічні промені в кількох напрямках. Дотик до будь-якого променя завдає $1228080s1 шкоди від тіні кожні $1228081t1 с." },
    { en = "Rings of stellar spikes surge from below, inflicting $s1 Cosmic damage to any player struck.", ua = "Кільця зоряних шпичаків здіймаються знизу, завдаючи $s1 космічної шкоди кожному враженому гравцю." },
    { en = "Salhadaar's galactic mace inflicts $1226418s1 Physical damage and increases damage taken from $@spellname1226417 by $1226413s1% for up to $1226413d.", ua = "Галактична булава Салгадаара завдає $1226418s1 фізичної шкоди й підвищує шкоду, що зазнають від $@spellname1226417, на $1226413s1% на час до $1226413d." },
    { en = "The ethereal annihilates a player with twilight energy, inflicting $1230267s1 Shadow damage.", ua = "Ефіріал знищує гравця сутінковою енергією, завдаючи $1230267s1 шкоди від тіні." },
    { en = "The interstellar blast blackens the sky, inflicting $s1 Cosmic damage to all players every $t1 sec for $d.", ua = "Міжзоряний вибух чорнить небо, завдаючи $s1 космічної шкоди всім гравцям кожні $t1 с протягом $d." },
    { en = "An oath shatters, inflicting $s1 Shadow damage to all players.", ua = "Присяга розколюється, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "A player succumbs to their oath, becoming mind-controlled for $d. The void invigorates the player, healing them to full health.\n\n\n\nUpon expiration, the player explodes inflicting $1252449s1 Shadow damage to all players.", ua = "Гравець піддається своїй присязі, потрапляючи під контроль розуму на $d. Порожнеча наповнює гравця снагою, повністю зцілюючи його.\n\n\n\nПісля закінчення гравець вибухає, завдаючи $1252449s1 шкоди від тіні всім гравцям." },
    { en = "Oaths return to haunt their breakers, manifesting as ethereal spirits that dart into players. Failing to face a spirit returns an application of $@spellname1224737.", ua = "Присяги повертаються, щоб переслідувати тих, хто їх порушив, проявляючись ефірними духами, що кидаються на гравців. Якщо не зустріти духа лицем до лиця, повертається нашарування $@spellname1224737." },
    { en = "The Voidwing sweeps across the sky, exhaling a breath that inflicts $1227472s1 Cosmic damage every $1227470t1 sec to any player within the effect.", ua = "Крило Порожнечі ширяє небом, видихаючи подих, що завдає $1227472s1 космічної шкоди кожні $1227470t1 с кожному гравцю в межах ефекту." },
    { en = "Salhadaar funnels energy into the door of the Manaforge, inflicting $1232392s1 Shadow damage every $t1 sec to players within $1232392A1 yards.", ua = "Салгадаар спрямовує енергію у двері манакузні, завдаючи $1232392s1 шкоди від тіні кожні $t1 с гравцям у межах $1232392A1 м." },
    { en = "Salhadaar executes a combination of strikes to subdue players.", ua = "Салгадаар виконує серію ударів, щоб здолати гравців." },
    { en = "Salhadaar invokes the oath, inflicting $s1 Shadow damage to all players. Any player that is still $@spellname1224737 is converted into $@spellname1224767.", ua = "Салгадаар прикликає присягу, завдаючи $s1 шкоди від тіні всім гравцям. Кожен гравець, який досі $@spellname1224737, перетворюється на $@spellname1224767." },
    { en = "Salhadaar hurls his mace which ricochets between several targets, inflicting $1228119s1 Shadow damage within $1228119A1 yards of each impact.", ua = "Салгадаар жбурляє свою булаву, що рикошетить між кількома цілями, завдаючи $1228119s1 тіньової шкоди в радіусі $1228119A1 ярдів від кожного удару." },
    { en = "Salhadaar smashes his current target, inflicting $1224791s1 Physical damage and an additional $1224794s1 Shadow damage split among all players within $1224794A1 yards, knocking them upwards.\n\n\n\nPlayers struck lose a stack of $@spellname1224737. Increases damage taken from $@spellname1224787 by $1224795s1% for $1224795d.", ua = "Салгадаар розтрощує свою поточну ціль, завдаючи $1224791s1 фізичної шкоди та додатково $1224794s1 шкоди Тіні, розподіленої між усіма гравцями в межах $1224794A1 м, і підкидає їх угору.\n\n\n\nУражені гравці втрачають заряд $@spellname1224737. Збільшує шкоду, отримувану від $@spellname1224787, на $1224795s1% на $1224795d." },
    { en = "Consuming a $@spellname1226042 $?|diff16 [more than once in rapid succession ][]destroys the $@spellname1225405 from the inside. Erupting shrapnel inflicts $s1 Cosmic damage to all players.", ua = "Споживання $@spellname1226042 $?|diff16 [більш ніж раз поспіль ][]руйнує $@spellname1225405 зсередини. Розлітаючись, осколки завдають $s1 космічної шкоди всім гравцям." },
    { en = "Enshrouded in regal shadows, reducing damage taken by $s1%.", ua = "Огорнутий королівськими тінями, що зменшують зазнавану шкоду на $s1%." },
    { en = "Upon reaching 100 energy, self-destruction protocol is initiated. \n\n\n\nAfter $s2 sec, the automaton detonates inflicting $s1 Shadow damage to all players and increasing their damage taken by $1252803s1% for $1252803d.", ua = "Щойно енергія сягає 100, запускається протокол самознищення. \n\n\n\nЧерез $s2 с автоматон детонує, завдаючи $s1 шкоди від тіні всім гравцям і підвищуючи шкоду, що вони зазнають, на $1252803s1% протягом $1252803d." },
    { en = "The Voidwing shreds its current target between stellar jaws, inflicting $s1 Physical damage. \n\n\n\nThe target's essence is devoured, inflicting an additional $1234902s1 Cosmic damage every $t2 sec and increasing damage taken from $@spellname1228163 by $s3% for $d.", ua = "Крило Порожнечі шматує свою поточну ціль між зоряних щелеп, завдаючи $s1 фізичної шкоди. \n\n\n\nЕсенцію цілі пожирає, що додатково завдає $1234902s1 космічної шкоди кожні $t2 с і підвищує шкоду, що зазнають від $@spellname1228163, на $s3% протягом $d." },
    { en = "The $@spellname1225405 vaporizes any player within it, reducing movement speed by $s3% and inflicting $1225445s1 Cosmic damage every $t1 sec.", ua = "$@spellname1225405 випаровує кожного гравця в собі, знижуючи швидкість пересування на $s3% і завдаючи $1225445s1 космічної шкоди кожні $t1 с." },
    { en = "Salhadaar drains the energy from the Voidwing, increases its damage taken by $1228265s1% and inflicting $1228280s1 Shadow damage to all players every $1228265t3 sec for $1228265d.\n\n\n\nUpon completion, Salhadaar heals himself equal to the Voidwing's remaining health as the drake fades from existence.", ua = "Салгадаар висмоктує енергію з Крила Порожнечі, збільшуючи отримувану ним шкоду на $1228265s1% і завдаючи $1228280s1 шкоди від тіні всім гравцям кожні $1228265t3 сек. протягом $1228265d.\n\n\n\nПісля завершення Салгадаар зцілює себе на величину, рівну решті здоров'я Крила Порожнечі, тимчасом як дрейк зникає з буття." },
    { en = "The target's existence unravels after $d, inflicting Cosmic damage proportional to the damage taken from $@spellname1228163 to all players.", ua = "Існування цілі розпадається через $d, завдаючи всім гравцям космічної шкоди, пропорційної до шкоди, зазнаної від $@spellname1228163." },
    { en = "Salhadaar cleaves his current target, inflicting $1224814s1 Physical damage and an additional $1233702s1 Shadow damage to all players in front of him, knocking them away. \n\n\n\nIncreases damage taken from $@spellname1224812 by $1224816s1% for $1224816d.", ua = "Салгадаар розсікає свою поточну ціль, завдаючи $1224814s1 фізичної шкоди та додатково $1233702s1 шкоди Тіні всім гравцям перед собою і відкидаючи їх. \n\n\n\nЗбільшує шкоду, отримувану від $@spellname1224812, на $1224816s1% на $1224816d." },
    { en = "Images of Salhadaar emerge alongside him to swing and erupt a galactic missile at their targets, inflicting $1226360s1 Cosmic damage to all players in its path and applying $@spellname1226362.\n\n\n\nSalhadaar's primary target is $@spellname1226417. Each missile detonates in a $@spellname1226042 unless consumed by a $@spellname1248137.", ua = "Образи Салгадаара з'являються поряд із ним, замахуються та випускають галактичну ракету по своїх цілях, завдаючи $1226360s1 космічної шкоди всім гравцям на її шляху і накладаючи $@spellname1226362.\n\n\n\nГоловна ціль Салгадаара — $@spellname1226417. Кожна ракета вибухає, утворюючи $@spellname1226042, якщо її не поглине $@spellname1248137." },
    { en = "$@spellname1225099 swipe at players that get too close, inflicting $1247213s1 Cosmic damage and knocking them back.", ua = "$@spellname1225099 б'є по гравцях, які підходять надто близько, завдаючи $1247213s1 космічної шкоди й відкидаючи їх." },
    { en = "The Nexus-Prince shields himself for $s2% of his maximum health.", ua = "Король Нексуса огортає себе щитом на $s2% свого максимального здоров'я." },
    { en = "The coalesced Royal Voidwing pierces up from below, inflicting $1227897s1 Cosmic damage to any player hit and knocking all players back.", ua = "Сформована Королівська Крилата Порожнеча пробивається знизу, завдаючи $1227897s1 космічної шкоди кожному враженому гравцю й відкидаючи всіх гравців." },
    { en = "The ethereal takes aim at a player before dashing through them, inflicting $1237109s1 Shadow damage to any player in its path. \n\n\n\nInflicts significant damage to $@spellname1237105 if struck.", ua = "Ефіріал бере гравця на приціл, а тоді кидається крізь нього, завдаючи $1237109s1 шкоди від тіні всім гравцям на своєму шляху.\n\n\n\nЗавдає значної шкоди $@spellname1237105, якщо влучить." },
    { en = "Salhadaar's imperious presence inflicts $1224825s1 Shadow damage to all players every $t1 sec.", ua = "Владна присутність Салгадаара завдає $1224825s1 шкоди від тіні всім гравцям кожні $t1 сек." },
    { en = "An abyssal fissure that inflicts $s1 Cosmic damage every $t1 sec to players within the effect.", ua = "Безодняна тріщина, що завдає $s1 космічної шкоди кожні $t1 сек гравцям у межах ефекту." },
    { en = "Mutilated by chaotic magic of another dimension, inflicting $1226363s1 Cosmic damage every $t1 sec for $d.", ua = "Понівечено хаотичною магією іншого виміру, що завдає $1226363s1 космічної шкоди кожні $t1 сек. протягом $d." },
    { en = "The Voidwing shreds through a player with its claws, inflicting $1224840s1 Cosmic damage and dragging any player caught within their path.", ua = "Крилата Порожнеча шматує гравця своїми пазурами, завдаючи $1224840s1 космічної шкоди й тягнучи за собою кожного гравця, що опинився на її шляху." },
    { en = "The ethereal focuses on their target, becoming immune to crowd control effects.", ua = "Ефіріал зосереджується на своїй цілі, стаючи несприйнятливим до ефектів контролю." },
    { en = "Collision with another $@spellname1225405 inflicts $s1 Cosmic damage to all players every $t2 sec.", ua = "Зіткнення з іншим $@spellname1225405 завдає $s1 космічної шкоди всім гравцям кожні $t2 сек." },
    { en = "Dimensius sweeps his enormous hand over all players and blasts them with dark matter, inflicting $1230999s1 Shadow damage to players within $1230989A1 yards on impact.", ua = "Дименсіус проводить велетенською долонею над усіма гравцями й накриває їх темною матерією, завдаючи $1230999s1 шкоди від тіні гравцям у межах $1230989A1 м під час удару." },
    { en = "Upon reaching 100 energy Dimensius increases his Density, creating a powerful inward force that inflicts $1245289s1 Shadow damage every $t1 for $d and pulls in players, Voidstars, Black Holes, and the Accretion Disk.\n\n\n\nAfter $d any player outside of a Voidstar's $@spellname1232394 is immediately pulled into Dimensius and consigned to $@spellname1229327.", ua = "Досягнувши 100 одиниць енергії, Дименсіус збільшує свою Густину, створюючи потужну силу тяжіння всередину, яка завдає $1245289s1 шкоди від тіні кожні $t1 протягом $d і притягує гравців, Зорі Порожнечі, Чорні Діри та Акреційний Диск.\n\n\n\nЧерез $d будь-який гравець за межами $@spellname1232394 Зорі Порожнечі негайно втягується в Дименсіуса й прирікається на $@spellname1229327." },
    { en = "Dimensius calls down a series of massive celestial objects that collide with the ground one after another. Each impact inflicts $s1 Shadow damage to players within $a1 yards and triggers a Shadowquake.", ua = "Дименсіус закликає низку велетенських небесних тіл, які одне за одним врізаються в землю. Кожен удар завдає $s1 шкоди від тіні гравцям у межах $a1 м і спричиняє Тіньотрус." },
    { en = "A tremendous shockwave of dark energy radiates outward from the impact, inflicting $s1 Shadow damage to players on contact and increasing damage taken from Shadowquake by $s2% for $d. This effect stacks.", ua = "Від місця удару назовні розходиться потужна ударна хвиля темної енергії, завдаючи $s1 шкоди від тіні гравцям при дотику й збільшуючи отримувану від Тіньотрусу шкоду на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Dimensius smashes his current target with devastating force, inflicting $1249206s1 Physical damage and $1231195s1 Cosmic damage to players within $1230144a1 yards and applying $@spellname1230168.\n\n\n\nThe force of the attack ripples outward through space inflicting $1242095s1 Cosmic damage to all other players, knocking them away from the impact location, and scattering Living Mass.", ua = "Дименсіус б'є по своїй поточній цілі з нищівною силою, завдаючи $1249206s1 фізичної шкоди й $1231195s1 космічної шкоди гравцям у межах $1230144a1 м і накладаючи $@spellname1230168.\n\n\n\nСила атаки розходиться брижами крізь простір, завдаючи $1242095s1 космічної шкоди всім іншим гравцям, відкидаючи їх від місця удару та розкидаючи Живу Масу." },
    { en = "Dimensius warps space around random players, reducing their movement speed by $s2% and inflicting $s1 Cosmic damage every $t1 sec for $d.", ua = "Дименсіус викривлює простір довкола випадкових гравців, знижуючи їхню швидкість пересування на $s2% і завдаючи $s1 космічної шкоди кожні $t1 сек протягом $d." },
    { en = "Voidstars project a Gravity Well that inflicts $s1 Shadow damage every $t1 sec to players within $s4 yards and reduces their movement speed by $s2%.\n\n\n\nDimensius cannot $@spellname1233539 players affected by a Gravity Well.", ua = "Зорі Порожнечі проєктують Гравітаційний Колодязь, який завдає $s1 шкоди від тіні кожні $t1 сек гравцям у межах $s4 м і знижує їхню швидкість пересування на $s2%.\n\n\n\nДименсіус не може застосувати $@spellname1233539 до гравців під дією Гравітаційного Колодязя." },
    { en = "Xal'atath bends space to her advantage creating waygates that refresh the duration of $@spellname1235114, grant a burst of speed and restore Skyriding Charges when players pass through them.", ua = "Ксал'атат вигинає простір на свою користь, створюючи портали, які оновлюють тривалість $@spellname1235114, дарують ривок швидкості та відновлюють Заряди Небесної Їзди, коли гравці крізь них проходять." },
    { en = "Dimensius' lost mass swirls and churns at the edge of the platform, inflicting $s1 Shadow damage to players on contact and knocking them back.", ua = "Втрачена маса Дименсіуса вирує й клекоче на краю платформи, завдаючи $s1 шкоди від тіні гравцям при дотику й відкидаючи їх." },
    { en = "Dimensius instantly devours any player who enters his body for any reason, killing them horribly.", ua = "Дименсіус миттєво пожирає будь-якого гравця, що з будь-якої причини потрапляє до його тіла, жахливо вбиваючи його." },
    { en = "Artoshion ejects superheated mass at random players after $1249425d, inflicting $1249433s1 Cosmic damage to all players in its path, knocking them back, and leaving behind a $@spellname1237696.", ua = "Артошіон викидає розпечену масу по випадкових гравцях через $1249425d, завдаючи $1249433s1 космічної шкоди всім гравцям на її шляху, відкидаючи їх і лишаючи по собі $@spellname1237696." },
    { en = "Dimensius' melee attacks disrupt the very fabric of space, forcing his target into melee range if they can't be reached and inflicting $1227665s1 Shadow damage to players within $1227663A1 yards of his target.\n\n\n\nThe force of the impact knocks away other players within $1227663A1 yards of his target.", ua = "Атаки ближнього бою Дименсіуса розривають саму тканину простору, змушуючи його ціль наблизитися на дистанцію ближнього бою, якщо її не дістати, і завдаючи $1227665s1 шкоди від тіні гравцям у радіусі $1227663A1 м від його цілі.\n\n\n\nСила удару відкидає інших гравців у радіусі $1227663A1 м від його цілі." },
    { en = "Increases damage of Cosmic Radiation by $s2%. This effect stacks.", ua = "Збільшує шкоду Космічної Радіації на $s2%. Цей ефект накопичується." },
    { en = "Unfathomable cosmic energy that inflicts $s1 Cosmic damage to players standing within every $t1 sec, increases all damage they take by $s2%, and reduces their movement speed by $s3%.", ua = "Незбагненна космічна енергія, яка завдає $s1 космічної шкоди гравцям усередині кожні $t1 сек, збільшує всю отримувану ними шкоду на $s2% і знижує їхню швидкість пересування на $s3%." },
    { en = "The Living Mass sustains a high-energy reaction that inflicts $1231194s1 Cosmic damage to random players every $t sec.", ua = "Жива Маса підтримує високоенергетичну реакцію, що завдає $1231194s1 космічної шкоди випадковим гравцям кожні $t сек." },
    { en = "Dimensius tears through space with an immense stream of radiation that inflicts $1237097s1 Cosmic damage every $1237097t1 sec to players who stray too close.\n\n\n\nPlayers who attempt to cross the center of the stream are vaporized instantly.", ua = "Дименсіус розтинає простір величезним потоком радіації, що завдає $1237097s1 космічної шкоди кожні $1237097t1 сек гравцям, які підходять надто близько.\n\n\n\nГравці, які намагаються перетнути центр потоку, миттєво випаровуються." },
    { en = "Dimensius reaches down with both hands and tears at the very fabric of space, inflicting $1243693s1 Cosmic damage to players within $1243693A1 yards of each hand and $1243694s1 Cosmic damage to all other players.\n\n\n\nThis violent act creates an enormous sphere of Antimatter at each location and causes a flurry of Spatial Fragments to rain down around players.", ua = "Дименсіус тягнеться обома руками й роздирає саму тканину простору, завдаючи $1243693s1 космічної шкоди гравцям у межах $1243693A1 м від кожної руки та $1243694s1 космічної шкоди всім іншим гравцям.\n\n\n\nЦей жорстокий акт створює велетенську сферу Антиматерії в кожному місці й спричиняє зливу Просторових Уламків довкола гравців." },
    { en = "Xal'atath energizes players' Reshii Wraps, protecting them from $@spellname1241188 and allowing the use of flying mounts.", ua = "Ксал'атат наповнює енергією Покрови Решші гравців, захищаючи їх від $@spellname1241188 і дозволяючи користуватися летючими їздовими тваринами." },
    { en = "Upon defeat, Living Mass decays into Excess Mass that players can pick up.\n\n\n\nDuring $@spellname1229038, players with Excess Mass can gather to project a zone of Collective Gravity.", ua = "Будучи переможеною, Жива Маса розпадається на Надлишкову Масу, яку гравці можуть підібрати.\n\n\n\nПід час $@spellname1229038 гравці з Надлишковою Масою можуть зібратися разом, щоб спроєктувати зону Колективної Гравітації." },
    { en = "When $1228206s1 or more players with $@spellname1228206 gather during $@spellname1229038, they project a $1247217A1 yard zone that reduces movement speed by $s2% and grants 1 stack of Collective Gravity for each player within who has $@spellname1228206. \n\n\n\nDimensius can only $@spellname1229038 players with less Collective Gravity than his $@spellname1229674.", ua = "Коли $1228206s1 або більше гравців з $@spellname1228206 збираються разом під час $@spellname1229038, вони проєктують зону розміром $1247217A1 м, яка знижує швидкість пересування на $s2% і дарує 1 заряд Колективної Гравітації за кожного гравця в межах, що має $@spellname1228206. \n\n\n\nДименсіус може застосувати $@spellname1229038 лише до гравців, чия Колективна Гравітація менша за його $@spellname1229674." },
    { en = "Pargoth releases a burst of superheated stardust, inflicting $s1 Cosmic damage to players within $A1 yards, launching several Starshards, and leaving behind a $@spellname1237696.", ua = "Парґот вивільняє вибух розпеченого зоряного пилу, завдаючи $s1 космічної шкоди гравцям у межах $A1 м, запускаючи кілька Зоряних Скалок і лишаючи по собі $@spellname1237696." },
    { en = "Fragments of Shattered Space rain down around players, inflicting $s1 Cosmic damage to players within $1243698A1 yards of the impact location and stunning them for $d.", ua = "Уламки Розколотого Простору сиплються довкола гравців, завдаючи $s1 космічної шкоди гравцям у межах $1243698A1 м від місця удару й оглушуючи їх на $d." },
    { en = "Dimensius tightens his hold on Airborne players. They can only be pulled down by a number of players with Excess Mass equal to or greater than Dimensius' current Anomalous Force.\n\n\n\nThis effect is reset when Dimensius casts Devour.", ua = "Дименсіус міцніше хапає Піднятих у повітря гравців. Їх може стягнути вниз лише така кількість гравців з Надлишковою Масою, що дорівнює поточній Аномальній Силі Дименсіуса або перевищує її.\n\n\n\nЦей ефект скидається, коли Дименсіус творить Пожирання." },
    { en = "Spheres of Antimatter form at the location of Shattered Space and remain stable for $1243700d, then trigger an annihilation reaction that inflicts $s1 Cosmic damage to all players.\n\n\n\nEvery ${$1243700s1/10}.1 sec, Antimatter reacts with players within $1243700A1 yards inflicting $1243702s1 Cosmic damage and reducing the damage of its final reaction by the same amount.", ua = "Сфери Антиматерії формуються в місці Розколотого Простору й лишаються стабільними протягом $1243700d, а тоді спричиняють реакцію анігіляції, що завдає $s1 космічної шкоди всім гравцям.\n\n\n\nКожні ${$1243700s1/10}.1 сек Антиматерія реагує з гравцями в межах $1243700A1 м, завдаючи $1243702s1 космічної шкоди й знижуючи шкоду своєї фінальної реакції на ту саму величину." },
    { en = "Dimensius targets random players then reverses their gravity after $d, inflicting $1243581s1 Shadow damage to players within $1243580A1 yards and sending them Airborne.\n\n\n\nPlayers hit by this effect who are already Airborne are immediately launched into Dimensius.", ua = "Дименсіус бере на приціл випадкових гравців, а тоді обертає їхню гравітацію через $d, завдаючи $1243581s1 шкоди від тіні гравцям у межах $1243580A1 м і піднімаючи їх у повітря.\n\n\n\nГравці, вражені цим ефектом, які вже перебувають у повітрі, негайно запускаються в Дименсіуса." },
    { en = "The Voidlord begins a ritual to seal the worldsoul fragment within a veil of impenetrable darkness.\n\n\n\nUpon completion of the ritual, the fragment becomes inaccessible.\n\n\n\nUpon reaching 100 energy, the Voidlord completes the ritual instantly.", ua = "Володар Порожнечі починає ритуал, щоб запечатати фрагмент Світодуші за пеленою непроникної темряви.\n\n\n\nПісля завершення ритуалу фрагмент стає недосяжним.\n\n\n\nДосягнувши 100 одиниць енергії, Володар Порожнечі завершує ритуал миттєво." },
    { en = "Arthosion ejects superheated mass at players in a line in front of him, inflicting $s1 Cosmic damage and knocking them back.", ua = "Артошіон викидає розпечену масу по гравцях лінією перед собою, завдаючи $s1 космічної шкоди й відкидаючи їх." },
    { en = "The Voidlord's successful melee attacks apply Touch of Oblivion, inflicting $1246145s3 Shadow damage every $1246145t3 sec for $1246145d. This effect stacks.\n\n\n\nUpon reaching $1246145s2 applications, the target is consigned to $@spellname1229327.", ua = "Успішні удари ближнього бою Володаря Порожнечі накладають Дотик забуття, завдаючи $1246145s3 шкоди від тіні щосекунди ($1246145t3) протягом $1246145d. Цей ефект складається.\n\n\n\nКоли кількість накладань сягає $1246145s2, ціль приречена на $@spellname1229327." },
    { en = "The Voidlord's powerful spell leaves behind cosmic debris that inflicts $s1 Cosmic damage every $t1 sec to players within and reduces their movement speed by $s2%.", ua = "Потужне закляття Володаря Порожнечі лишає по собі космічні уламки, що завдають $s1 космічної шкоди щосекунди ($t1) гравцям усередині та зменшують їхню швидкість пересування на $s2%." },
    { en = "Pargoth releases a burst of superheated stardust, inflicting $s1 Cosmic damage to players within $A1 yards.", ua = "Парґот вивільняє спалах розпеченого зоряного пилу, завдаючи $s1 космічної шкоди гравцям у радіусі $A1 м." },
    { en = "Dimensius bends the laws of nature, applying either $@spellname1234243 or $@spellname1234244 to all players.", ua = "Дименсіус викривлює закони природи, накладаючи на всіх гравців або $@spellname1234243, або $@spellname1234244." },
    { en = "After $d intense gravity pushes down around the target, inflicting $1234248s1 Cosmic damage and applying Crushed to all players within $1234248A1 yards.", ua = "Через $d навколо цілі вниз тисне нездоланна гравітація, завдаючи $1234248s1 космічної шкоди й накладаючи Розчавлення на всіх гравців у радіусі $1234248A1 м." },
    { en = "After $d intense gravity pushes outward from the target, inflicting $1234249s1 Cosmic damage and violently knocking away players within $1234249A1 yards.\n\n$?diff16 [\n\nHitting players who have $@spellname1234243 removes it from them instead of knocking them away.][]", ua = "Через $d від цілі назовні вибухає нездоланна гравітація, завдаючи $1234249s1 космічної шкоди й жорстоко відкидаючи гравців у радіусі $1234249A1 м.\n\n$?diff16 [\n\nГравцям, на яких діє $@spellname1234243, удар натомість знімає цей ефект, а не відкидає їх.][]" },
    { en = "Dimensius tears through space with an immense stream of radiation that inflicts $1237325s1 Cosmic damage every $1237325t1 sec to all players and pushes them away over $d.", ua = "Дименсіус розриває простір потужним потоком випромінювання, що завдає $1237325s1 космічної шкоди щосекунди ($1237325t1) усім гравцям і відштовхує їх протягом $d." },
    { en = "Upon death, the Voidwarden's energy is absorbed by all other Voidwardens within $1246536A1 yards, fully restoring their health and reducing all damage they take by $s2%.", ua = "Після загибелі енергію Стража Порожнечі поглинають усі інші Стражі Порожнечі в радіусі $1246536A1 м, що повністю відновлює їхнє здоров'я та зменшує всю отримувану ними шкоду на $s2%." },
    { en = "The target is crushed by intense gravity, stunning them and inflicting $s1 Cosmic damage every $t1 sec for $d.", ua = "Ціль розчавлює нездоланна гравітація, оглушуючи її та завдаючи $s1 космічної шкоди щосекунди ($t1) протягом $d." },
    { en = "The Nullbinder weaves a dark pattern and binds all players with it, inflicting $s1 Shadow damage plus an additional $s2 Shadow damage every $t2 sec for $d and reducing their movement speed by $s3%. This effect stacks.", ua = "Нуль-плетій тче темний візерунок і сплутує ним усіх гравців, завдаючи $s1 шкоди Тінню та додатково $s2 шкоди Тінню кожні $t2 сек. протягом $d і зменшуючи їхню швидкість руху на $s3%. Цей ефект накопичується." },
    { en = "Dimensius initiates the death of a Voidstar, causing it to explode after $s1 sec inflicting $1232986s1 Cosmic damage to all players, reduced based on distance.\n\n\n\nA $@spellname1232987 appears in place of the Voidstar and continues to orbit Dimensius.", ua = "Дименсіус спричиняє загибель Зорі Порожнечі, через що вона вибухає за $s1 сек., завдаючи $1232986s1 космічної шкоди всім гравцям; шкода зменшується залежно від відстані.\n\n\n\nНа місці Зорі Порожнечі з'являється $@spellname1232987 і продовжує обертатися навколо Дименсіуса." },
    { en = "Dimensius radiates intense energy, inflicting $1228368s1 Cosmic damage to all players every $t1 sec.", ua = "Дименсіус випромінює потужну енергію, завдаючи $1228368s1 космічної шкоди всім гравцям щосекунди ($t1)." },
    { en = "Black Holes shred players into their constituent atoms on contact, killing them.", ua = "Чорні діри при дотику роздирають гравців на атоми, з яких вони складаються, убиваючи їх." },
    { en = "Concentrated stellar energy that can be collected by flying players, allowing them to launch a Shooting Star at the nearest Voidlord when they land.", ua = "Згущена зоряна енергія, яку можуть зібрати гравці в польоті, що дозволяє їм запустити Падаючу зорю в найближчого Володаря Порожнечі, коли вони приземляться." },
    { en = "Dimensius collapses space itself in an attempt to crush his target, inflicting $1234269s1 Cosmic damage and $1234270s1 Physical damage to players within $1234265A1 yards and applying $@spellname1234266.", ua = "Дименсіус згортає сам простір, намагаючись розчавити свою ціль, завдаючи $1234269s1 космічної та $1234270s1 фізичної шкоди гравцям у радіусі $1234265A1 м і накладаючи $@spellname1234266." },
    { en = "Increases Physical damage taken by $s1%. This effect stacks.", ua = "Збільшує отримувану фізичну шкоду на $s1%. Цей ефект складається." },
    { en = "Targets of $@spellname1243577 are launched upward, where they float helplessly toward Dimensius.\n\n\n\nPlayers with $@spellname1228206 can stand under them to pull them back down, canceling this effect when they reach solid ground.", ua = "Цілі $@spellname1243577 злітають угору, де безпорадно линуть до Дименсіуса.\n\n\n\nГравці з $@spellname1228206 можуть стати під ними, щоб стягнути їх назад униз, скасовуючи цей ефект, щойно ті торкнуться твердої землі." },
    { en = "Fragments of worlds shattered by Dimensius hurtle through space, inflicting $s1 Cosmic damage and dismounting players on impact.", ua = "Уламки світів, розтрощених Дименсіусом, мчать крізь простір, завдаючи $s1 космічної шкоди й скидаючи гравців з їздових тварин під час зіткнення." },
    { en = "When a star dies a singularity forms in its place, lethally spaghettifying any player it touches.", ua = "Коли зоря гине, на її місці утворюється сингулярність, що смертельно спагетифікує будь-якого гравця, якого торкнеться." },
    { en = "Increases Cosmic damage taken by $s1%. This effect stacks.", ua = "Збільшує отримувану космічну шкоду на $s1%. Цей ефект складається." },
    { en = "The Voidlord summons a phalanx of Voidwardens to secure his territory and restrict player movement.", ua = "Володар Порожнечі прикликає фалангу Стражів Порожнечі, щоб убезпечити свою територію та обмежити пересування гравців." },
    { en = "When $s2 or more players gather within the Gravity Well of a single Voidstar it immediately explodes, inflicting $s1 Cosmic damage to all players.\n\n\n\nA $@spellname1232987 appears in place of the Voidstar and continues to orbit Dimensius.", ua = "Коли $s2 або більше гравців збираються в межах Гравітаційного колодязя однієї Зорі Порожнечі, вона негайно вибухає, завдаючи $s1 космічної шкоди всім гравцям.\n\n\n\nНа місці Зорі Порожнечі з'являється $@spellname1232987 і продовжує обертатися навколо Дименсіуса." },
    { en = "After $1249247s2 sec, the Nullbinder becomes immune to all forms of crowd control.", ua = "Через $1249247s2 сек. Нуль-в'язатель стає несприйнятливим до всіх форм контролю." },
    { en = "Dimensius consigns players to $@spellname1229325 from any distance if they're not protected by $@spellname1235114.", ua = "Дименсіус прирікає гравців на $@spellname1229325 з будь-якої відстані, якщо їх не захищає $@spellname1235114." },
    { en = "Smash concentrated stellar energy into the nearest Voidlord, inflicting Cosmic damage equal to $s1% of the Voidlord's maximum health.", ua = "Вганяє згущену зоряну енергію в найближчого Володаря Порожнечі, завдаючи космічної шкоди в розмірі $s1% від його максимального здоров'я." },
    { en = "The Voidwarden exerts control over the area around it, knocking back players who enter and inflicting $s1 Shadow damage plus an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Страж Порожнечі панує над простором навколо себе, відкидаючи гравців, які заходять у нього, і завдаючи $s1 шкоди від тіні плюс додатково $s2 шкоди від тіні щосекунди ($t2) протягом $d." },
    { en = "Dimensius calls $s1 Voidstars down around him over $d, each inflicting $1232391s3 Shadow damage to all players plus an additional $1232391s1 Shadow damage to players within $1232391A1 yards of the impact location.\n\n\n\nThe Voidstars then begin to orbit him and project a $@spellname1232394.", ua = "Дименсіус скликає до себе $s1 Зор Порожнечі протягом $d, і кожна з них завдає $1232391s3 шкоди від тіні всім гравцям плюс додатково $1232391s1 шкоди від тіні гравцям у радіусі $1232391A1 м від місця падіння.\n\n\n\nДалі Зорі Порожнечі починають обертатися навколо нього й випромінюють $@spellname1232394." },
    { en = "Dimensius' hunger grows with each cast of Devour, increasing the amount of $@spellname1228207 needed to survive.", ua = "Голод Дименсіуса зростає з кожним застосуванням Пожирання, збільшуючи кількість $@spellname1228207, потрібну для виживання." },
    { en = "Dimensius reels from Xal'atath's devastating counter-attack, increasing all damage taken by $s1% until he recovers.", ua = "Дименсіус хитається від нищівної контратаки Ксал'атат, збільшуючи всю отримувану шкоду на $s1%, доки він не оговтається." },
    { en = "Dimensius hurls a fragment of a broken world at players, inflicting $1238773s1 Cosmic damage to players caught in its path and stunning them for $1238773d.", ua = "Дименсіус жбурляє в гравців уламок зруйнованого світу, завдаючи $1238773s1 космічної шкоди гравцям на його шляху й оглушуючи їх на $1238773d." },
    { en = "Upon reaching 100 energy, Dimensius attempts to devour all players, inflicting $1243373s1 Shadow damage every $t1 sec for $d.\n\n\n\nAfter $d any player with insufficient $@spellname1228207 is pulled into Dimensius and consigned to $@spellname1229327. He then absorbs all $@spellname1228206 and Living Mass.", ua = "Сягнувши 100 енергії, Дименсіус намагається пожерти всіх гравців, завдаючи $1243373s1 шкоди від тіні щосекунди ($t1) протягом $d.\n\n\n\nЧерез $d кожен гравець із недостатньою кількістю $@spellname1228207 затягується в Дименсіуса й приречений на $@spellname1229327. Потім він поглинає всю $@spellname1228206 та Живу масу." },
    { en = "Whenever a Living Mass' health is depleted, it enters a state of Infinite Possibilities for $d, then restores all Living Mass to full health.\n\n\n\nDepleting the health of all Living Mass at the same time interrupts this effect and leaves them with only one possibility: Death.", ua = "Щоразу, коли здоров'я Живої маси вичерпується, вона переходить у стан Нескінченних можливостей на $d, а потім повністю відновлює здоров'я всієї Живої маси.\n\n\n\nЯкщо вичерпати здоров'я всієї Живої маси одночасно, цей ефект переривається, лишаючи їй єдину можливість: Смерть." },
    { en = "Detonates violently on contact with a player, inflicting $s2 Cosmic damage to players within $1254379A1 yards every $t2 sec for $d and leaving behind a $@spellname1237696.\n\n\n\nWhenever a player is hit by another Starshard while under this effect, a $@spellname1254384 occurs at their location.", ua = "Бурхливо детонує при дотику до гравця, завдаючи $s2 космічної шкоди гравцям у радіусі $1254379A1 м щосекунди ($t2) протягом $d і лишаючи по собі $@spellname1237696.\n\n\n\nЩоразу, коли гравця, на якого діє цей ефект, влучає інший Зоряний осколок, на його місці стається $@spellname1254384." },
    { en = "When a $@spellname1254385 hits a player already affected by $@spellname1254385, a cataclysmic explosion occurs inflicting $s1 Cosmic damage to all players.", ua = "Коли $@spellname1254385 влучає гравця, на якого вже діє $@spellname1254385, стається катаклізмічний вибух, що завдає $s1 космічної шкоди всім гравцям." },
    { en = "Dimensius radiates intense energy, inflicting $1232895s1 Cosmic damage to all players every $t1 sec.", ua = "Дименсіус випромінює потужну енергію, завдаючи $1232895s1 космічної шкоди всім гравцям щосекунди ($t1)." },
    { en = "The Arcane Sieve will $@spellname1219223 all players who come in contact with it, and leave behind $@spellname1219248.", ua = "Арканний Фільтр накладає $@spellname1219223 на всіх гравців, що торкаються його, і лишає по собі $@spellname1219248." },
    { en = "Ilyssa rapidly slashes her current target, inflicting $s1 Physical damage and shattering $@spellname1225199s from them. This strike applies $@spellname1226493 to her current target.", ua = "Ілісса стрімко розсікає свою ціль, завдаючи $s1 фізичної шкоди та вибиваючи з неї $@spellname1225199s. Цей удар накладає $@spellname1226493 на її ціль." },
    { en = "Inflicts $s1 Chaos damage to players within $A1 yards of impact and creates a $@spellname1222385.", ua = "Завдає $s1 шкоди від хаосу гравцям у радіусі $A1 метрів від місця удару та створює $@spellname1222385." },
    { en = "Players can move near Soul Fragments to consume them, suffering $1225208s1 Fire damage every $1225208t1 sec for $1225208d.", ua = "Гравці можуть наблизитися до Уламків Душі, щоб поглинути їх, зазнаючи $1225208s1 шкоди від вогню щосекунди ($1225208t1 сек.) протягом $1225208d." },
    { en = "Adarus drains the essence of any players currently bearing $@spellname1222057, inflicting $s1 Cosmic damage and absorbing the next $1222307s1 healing received.\n\n\n\nThis blast applies $@spellname1222310.", ua = "Адарус витягує есенцію з усіх гравців, на яких діє $@spellname1222057, завдаючи $s1 космічної шкоди та поглинаючи наступні $1222307s1 одиниць отриманого зцілення.\n\n\n\nЦей вибух накладає $@spellname1222310." },
    { en = "A fiery heat wave formed by Flarendo's spontaneous combustion engine. inflicts $465466s1 Fire damage to players it contacts.", ua = "Вогняна хвиля жару, породжена двигуном самозаймання Фларендо, завдає $465466s1 шкоди вогнем гравцям, яких торкається." },
    { en = "Fractillus pounds the ground, inflicting $1225210s1  Shadow damage to all players every $t1 sec for $d.", ua = "Фрактіллус гамселить землю, завдаючи $1225210s1  тіньової шкоди всім гравцям кожні $t1 сек. протягом $d." },
    { en = "Web shackles form and connect to all players, pulling them inward and inflicting $441867s1 Nature damage every $441865t1 sec until the shackles are destroyed.\n\n\n\nAny player that is pulled into the shackles is trapped in a $@spellname441872. Destroying the shackles frees cocooned players.", ua = "Утворюються павутинні кайдани, що з'єднуються з усіма гравцями, тягнуть їх досередини й завдають $441867s1 од. шкоди Природи кожні $441865t1 с, доки кайдани не буде знищено.\n\n\n\nБудь-який гравець, затягнутий у кайдани, опиняється в пастці $@spellname441872. Знищення кайданів звільняє закутаних у кокон гравців." },
    { en = "A spectral image of Ky'veza that mirrors some of her attacks.", ua = "Примарний образ Ки'вези, що відтворює деякі з її атак." },
    { en = "Upon death or upon reaching 100 energy, the Dynamite Booty explodes and inflicts $s1 Fire damage to all players with an additional $s2 Fire damage every $t2 sec for $d. This effect stacks.", ua = "Після загибелі або по досягненні 100 енергії Динамітна Здобич вибухає й завдає $s1 шкоди вогнем усім гравцям, а також ще $s2 шкоди вогнем кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Overloaded with |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r, the extra power is discharged from the player, inflicting $s1 Nature damage and stunning them for $d. Inflicts an additional $388781s1 to players within $388781A1 yards.", ua = "Перевантажений ефектом |cFF2959D3|Hspell:387199|h[Буря Струнраана]|h|r, гравець розряджає надлишкову енергію, завдаючи $s1 шкоди від сил природи й оглушуючи себе на $d. Додатково завдає $388781s1 гравцям у радіусі $388781A1 ярдів." },
    { en = "The tempest surrounding Strunraan fills the air with electric power. |cFF2959D3|Hspell:388980|h[Storm's Strike]|h|r hits the ground periodically.", ua = "Буря, що оточує Струнраана, наповнює повітря електричною силою. |cFF2959D3|Hspell:388980|h[Удар Бурі]|h|r періодично б'є по землі." },
    { en = "While standing in water, Strunraan electrocutes all players in it, inflicting $s1 Nature damage every $385991t1 sec.", ua = "Поки гравці стоять у воді, Струнраан б'є їх струмом, завдаючи $s1 шкоди від сил природи кожні $385991t1 с." },
    { en = "Inflicts $s1 Nature damage to players within $a1 yards of the lightning strike. Applies |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r.", ua = "Завдає $s1 шкоди від сил природи гравцям у радіусі $a1 ярдів від удару блискавки. Накладає |cFF2959D3|Hspell:387199|h[Буря Струнраана]|h|r." },
    { en = "Upon reaching 100 energy, Strunraan empowers the |cFF2959D3|Hspell:383601|h[Surrounding Storm]|h|r causing |cFF2959D3|Hspell:388980|h[Storm's Strike]|h|r to occur at an accelerated rate for $d.", ua = "Сягнувши 100 енергії, Струнраан підсилює |cFF2959D3|Hspell:383601|h[Навколишня буря]|h|r, через що |cFF2959D3|Hspell:388980|h[Удар бурі]|h|r відбувається прискорено протягом $d." },
    { en = "Strunraan unleashes a breath of electricity inflicting $s1 Nature damage every $t1 sec. Enemies hit by the breath are knocked back and gain a stack of |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r.", ua = "Струнраан випускає подих електрики, завдаючи $s1 шкоди від сил природи кожні $t1 с. Вороги, яких зачепив подих, відкидаються назад і отримують заряд ефекту |cFF2959D3|Hspell:387199|h[Буря Струнраана]|h|r." },
    { en = "Strunraan unleashes tornadoes in a circle around him that each inflict $s1 Nature damage, knocking the player back and applying |cFF2959D3|Hspell:387199|h[Strunraan's Tempest]|h|r.", ua = "Струнраан здіймає навколо себе кільце торнадо, кожне з яких завдає $s1 шкоди від сил природи, відкидає гравця та накладає |cFF2959D3|Hspell:387199|h[Буря Струнраана]|h|r." },
    { en = "The tempest-filled air electrifies your attack and casting speeds, increasing them by $s1% for $d. \n\n\n\nGaining the effect again while its already active will cause |cFF2959D3|Hspell:387265|h[Overcharge]|h|r.", ua = "Сповнене бурею повітря електризує вашу швидкість атаки й творення заклять, підвищуючи їх на $s1% протягом $d. \n\n\n\nЯкщо отримати цей ефект знову, поки він уже діє, спрацює |cFF2959D3|Hspell:387265|h[Перевантаження]|h|r." },
    { en = "Basrikron gives life to the earth, summoning elementals to aid him.", ua = "Басрікрон дарує життя землі, прикликаючи елементалів собі на допомогу." },
    { en = "Basrikron exhales fragments of earth on their current target, inflicting $s1 Physical damage, and increasing Physical damage taken by $s2% for $d.", ua = "Басрікрон видихає на свою поточну ціль уламки землі, завдаючи $s1 од. фізичної шкоди та збільшуючи отримувану фізичну шкоду на $s2% на $d." },
    { en = "At 100 energy, Basrikron attempts to take flight while priming his constructs to become volatile. Basrikron will crash back to the earth, inflicting $s1 Nature damage and knocking back players in a $a1 yd radius, and $s3 Nature damage to all players. Upon landing, Basrikron's earthen constructs erupt.", ua = "Сягнувши 100 енергії, Басрікрон намагається злетіти, готуючи свої конструкти стати нестабільними. Басрікрон обрушиться назад на землю, завдаючи $s1 шкоди від сил природи й відкидаючи гравців у радіусі $a1 ярдів, а також $s3 шкоди від сил природи всім гравцям. Приземлившись, земляні конструкти Басрікрона вибухають." },
    { en = "Earthen constructs erupt, inflicting $s1 Nature damage and knocking players back within an $a1 yd radius.", ua = "Земляні конструкти вибухають, завдаючи $s1 од. шкоди Природою та відкидаючи гравців у радіусі $a1 ярдів." },
    { en = "Basrikron fractures the earth beneath players feet, raising a $@spellname385879 at their location, inflicting $385284s1 Nature damage and knocking players away. The area around the $@spellname385879 is unstable, inflicting $385355s1 Nature damage, and slows movement speed by $385355s2% to players in a $385355r yd area.", ua = "Басрікрон розколює землю під ногами гравців, здіймаючи $@spellname385879 на їхньому місці, завдаючи $385284s1 од. шкоди Природою та відкидаючи гравців. Ділянка навколо $@spellname385879 нестійка, завдаючи $385355s1 од. шкоди Природою та сповільнюючи швидкість пересування на $385355s2% гравцям у межах $385355r ярдів." },
    { en = "The area around the $@spellname385879 is unstable, inflicting $385355s1 Nature damage, and slowing movement speed by $385355s2% to players in an $385355r yd area.", ua = "Ділянка навколо $@spellname385879 нестійка, завдаючи $385355s1 од. шкоди Природою та сповільнюючи швидкість пересування на $385355s2% гравцям у межах $385355r ярдів." },
    { en = "Bazual blasts his target with searing lava, inflicting $s1 Fire damage to target player and all players in a $r yard cone.", ua = "Базуал б'є свою ціль пекучою лавою, завдаючи $s1 шкоди від вогню цільовому гравцю та всім гравцям у конусі завдовжки $r ярдів." },
    { en = "Powered by the plane of fire, Bazual summons a rain of fire at up to 20 random players' locations every $t sec for $d.\n\n\n\nInflicts $390683s1 Fire damage to all players within $390683A yards of impact.", ua = "Живлений стихією вогню, Базуал прикликає вогняну зливу на місця до 20 випадкових гравців кожні $t с протягом $d.\n\n\n\nЗавдає $390683s1 шкоди від вогню всім гравцям у радіусі $390683A ярдів від влучання." },
    { en = "Bazual empowers himself with the raging flame from the Plane of Fire and gains $@spellname391251.", ua = "Базуал підсилює себе шаленим полум'ям зі Стихії Вогню й отримує $@spellname391251." },
    { en = "Bazual sends out a wave of flame around him, inflicting $s1 Fire damage to all players and knocking them back.", ua = "Базуал випускає довкола себе хвилю полум'я, завдаючи $s1 шкоди від вогню всім гравцям і відкидаючи їх назад." },
    { en = "$@spellaura391251", ua = "$@spellaura391251" },
    { en = "Bazual targets up to 5 random players with searing magma. Upon impact, it leaves behind a pool of fire for $d, inflicting $389366s1 Fire damage every $s2 sec to players in the area.", ua = "Базуал обирає цілями до 5 випадкових гравців, обпікаючи їх палючою магмою. Після влучання вона лишає по собі вогняну калюжу на $d, завдаючи $389366s1 шкоди від вогню кожні $s2 с гравцям у зоні дії." },
    { en = "Upon reaching 100 energy, Liskanoth unleashes her icy power, spewing out frozen air below her. \n\n\n\nAll players caught in her path take $s1 Frost damage. In addition, $s2 Frost damage is inflicted every $t2 sec and they are stunned for $d.", ua = "Сягнувши 100 одиниць енергії, Лісканот вивільняє свою крижану міць, вивергаючи під собою морозне повітря. \n\n\n\nУсі гравці на її шляху зазнають $s1 шкоди від морозу. Крім того, кожні $t2 с їм завдається $s2 шкоди від морозу, і вони приголомшені протягом $d." },
    { en = "Liskanoth creates an icy storm around her, sending chunks of ice into the ground, inflicting $s1 Frost damage to those within $A1 yards of the impact and leaving behind a patch of frozen ground. \n\n\n\nPlayers standing within frozen ground are chilled, suffering $389287s1 Frost damage every $389287t1 sec and movement speed is reduced by $389287s2%", ua = "Лісканот створює довкола себе крижану бурю, скидаючи брили льоду на землю, завдаючи $s1 шкоди від морозу тим, хто в радіусі $A1 ярдів від влучання, і лишаючи по собі ділянку мерзлої землі. \n\n\n\nГравці, що стоять на мерзлій землі, промерзають, отримуючи $389287s1 шкоди від морозу кожні $389287t1 с, а їхня швидкість пересування зменшується на $389287s2%" },
    { en = "Inflicts $s1 Frost damage every $t1 sec and reduces movement speed by $s2% for $d.", ua = "Завдає $s1 шкоди від морозу кожні $t1 с і знижує швидкість пересування на $s2% протягом $d." },
    { en = "Liskanoth exhales out an icy cone, inflicting $s2 Frost damage and applying $@spellname388924 to all enemies caught in the cone.", ua = "Лісканот видихає крижаний конус, завдаючи $s2 шкоди від морозу та накладаючи $@spellname388924 на всіх ворогів, що потрапили в конус." },
    { en = "Liskanoth hurls ice at her target, binding them to the ground and rooting them in place until the Binding Ice is defeated. \n\n\n\nWhile bound in ice, $s2 Frost damage is taken every $t2 sec.", ua = "Лісканот жбурляє лід у свою ціль, прив'язуючи її до землі та знерухомлюючи на місці, доки Сковуючий Лід не буде знищено. \n\n\n\nПоки ціль скута льодом, вона зазнає $s2 шкоди від морозу кожні $t2 с." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec for $d. This effect stacks.\n\n\n\nAlso disperses any $@spellname403384 a player stands within.", ua = "Завдає $s1 шкоди тіньовим полум'ям щосекунди ($t1 сек.) протягом $d. Цей ефект накопичується.\n\n\n\nТакож розсіює будь-яке $@spellname403384, у якому стоїть гравець." },
    { en = "Using $@spellname403779 to disperse a $@spellname403384 fills the player with Vakan's might, increasing their haste by $s1% for $d.", ua = "Використання $@spellname403779 для розсіювання $@spellname403384 наповнює гравця могутністю Вакана, підвищуючи його поспіх на $s1% протягом $d." },
    { en = "Using $@spellname402824 to disperse a $@spellname403940 fills the player with Gholna's might, increasing their haste by $s1% for $d.", ua = "Використання $@spellname402824 для розсіювання $@spellname403940 наповнює гравця могутністю Ґолни, підвищуючи його поспіх на $s1% протягом $d." },
    { en = "Vakan unleashes darkness at random destinations, inflicting $404515s1 Shadowflame damage to players within $404515a1 yards of impact.\n\n\n\nWhile casting, Vakan is protected by $@spellname407787.", ua = "Вакан вивільняє темряву у випадкових місцях, завдаючи $404515s1 шкоди від тіньового полум'я гравцям у радіусі $404515a1 ярдів від влучання.\n\n\n\nПід час творення Вакана захищає $@spellname407787." },
    { en = "Gholna hurls lava at $s1 random players, inflicting $402966s1 Volcanic damage and applying $@spellname402824.", ua = "Голна жбурляє лаву в $s1 випадкових гравців, завдаючи $402966s1 вулканічної шкоди й накладаючи $@spellname402824." },
    { en = "Inflicts $s1 Volcanic damage every $t1 sec for $d. This effect stacks.\n\n\n\nAlso disperses any $@spellname403940 a player stands within.", ua = "Завдає $s1 Вулканічної шкоди кожні $t1 с протягом $d. Цей ефект накопичується.\n\n\n\nТакож розсіює будь-який $@spellname403940, у якому стоїть гравець." },
    { en = "Gholna causes magma to erupt at $402985s1 random player destinations, inflicting $s2 Volcanic damage to players within $A2 yards of impact and creating a $@spellname403384.", ua = "Голна спричиняє виверження магми на місцях $402985s1 випадкових гравців, завдаючи $s2 вулканічної шкоди гравцям у радіусі $A2 ярдів від влучання й створюючи $@spellname403384." },
    { en = "Gholna hurls magma every $t1 sec for $d, at random destinations inflicting $402997s1 Volcanic damage to players within $402997A1 yards of impact.\n\n\n\nWhile channeling, Gholna is protected by $@spellname407815.", ua = "Гольна метає магму кожні $t1 с протягом $d у випадкові місця, завдаючи $402997s1 Вулканічної шкоди гравцям у радіусі $402997A1 ярдів від влучання.\n\n\n\nПід час спрямовування Гольну захищає $@spellname407815." },
    { en = "Gholna and Vakan's rivalry is so potent, they gain strength while within $a1 yards of each other reducing their damage received by $s1%.", ua = "Суперництво Голни й Вакана таке сильне, що вони набираються сили, перебуваючи в радіусі $a1 ярдів одне від одного, зменшуючи отримувану ними шкоду на $s1%." },
    { en = "The Vortex inflicts $s1 Shadowflame damage every $t1 sec to players standing within it.", ua = "Вихор завдає $s1 шкоди тіньовим полум'ям щосекунди ($t1 сек.) гравцям, які стоять усередині нього." },
    { en = "Shadowflame wreaths Vakan, reducing all incoming damage by $s1%.", ua = "Тіньове полум'я огортає Вакана, зменшуючи всю отримувану шкоду на $s1%." },
    { en = "Gholna strikes her current target, inflicting $s1 Volcanic damage to players in a frontal cone and knocking them back.\n\n\n\nAdditionally, applies $@spellname402824 to players hit by this effect.", ua = "Голна б'є свою поточну ціль, завдаючи $s1 вулканічної шкоди гравцям у передньому конусі й відкидаючи їх назад.\n\n\n\nКрім того, накладає $@spellname402824 на гравців, яких зачепив цей ефект." },
    { en = "Vakan hurls dark bolts at $s1 random players, inflicting $403857s1 Shadowflame damage and applying $@spellname403779.", ua = "Вакан жбурляє темні стріли в $s1 випадкових гравців, завдаючи $403857s1 шкоди від тіньового полум'я й накладаючи $@spellname403779." },
    { en = "Vakan hurls darkness at $404171s1 random player destinations, inflicting $s2 Shadowflame damage to all players within $A2 yards of the impact and summons a $@spellname403947.", ua = "Вакан жбурляє темряву на місця $404171s1 випадкових гравців, завдаючи $s2 шкоди від тіньового полум'я всім гравцям у радіусі $A2 ярдів від влучання й прикликаючи $@spellname403947." },
    { en = "A fiery shield surrounds Gholna, reducing all incoming damage by $s1%.", ua = "Голну оточує вогняний щит, зменшуючи всю отримувану шкоду на $s1%." },
    { en = "Magma inflicts $s1 Volcanic damage every $t1 sec to players standing within it.", ua = "Магма завдає $s1 од. вулканічної шкоди щосекунди ($t1) гравцям, які стоять у ній." },
    { en = "Vakan smashes his current target, inflicting $s1 Shadowflame damage to players in a frontal cone and knocking them back.\n\n\n\nAdditionally, applies $@spellname403779 to players hit by this effect.", ua = "Вакан вдаряє свою поточну ціль, завдаючи $s1 од. шкоди тіньовим полум'ям гравцям у конусі попереду й відкидаючи їх назад.\n\n\n\nКрім того, накладає $@spellname403779 на гравців, уражених цим ефектом." },
    { en = "Magma erupts every $403578t1 sec inflicting $s1 Volcanic damage to $403579s1 random players.", ua = "Магма вивергається кожні $403578t1 сек., завдаючи $s1 од. вулканічної шкоди $403579s1 випадковим гравцям." },
    { en = "Aurostor begins to throw a tantrum, sundering the ground and sending lines of fractured earth towards his targets' location inflicting $s1 Physical damage to all players hit within $a1 yds of the impact.", ua = "Ауростор впадає в лють, розколюючи землю та посилаючи смуги розтрісканого ґрунту до місць, де стоять його цілі, завдаючи $s1 фізичної шкоди всім гравцям, влученим у межах $a1 м від удару." },
    { en = "Target is put to sleep. Damage taken increased by $s2%.\n\n\n\nTaking damage removes this effect.", ua = "Ціль засинає. Отримувана шкода збільшена на $s2%.\n\n\n\nОтримання шкоди знімає цей ефект." },
    { en = "Shards of earth are sent flying from the area, inflicting $s1 Nature damage to players within a $a1 yd radius.", ua = "Із зони здіймаються уламки землі, завдаючи $s1 шкоди природою гравцям у радіусі $a1 м." },
    { en = "Aurostor charges to a player's location and pummels anyone within $a1 yds inflicting $s1 Nature damage, and sends $@spellname422583 towards players.", ua = "Ауростор кидається до місця, де стоїть гравець, і молотить усіх у межах $a1 м, завдаючи $s1 шкоди від сил природи, та посилає $@spellname422583 у бік гравців." },
    { en = "Aurostor roars, inflicting $421260s1 Nature damage to all enemies. Additionally, players receive 3 stacks of $@spellname421260 and are slowed by $421260s2% per stack for $421260d. \n\n\n\nJumping removes a stack of $@spellname421260.", ua = "Ауростор реве, завдаючи $421260s1 од. шкоди від сил природи всім ворогам. Крім того, гравці отримують 3 заряди $@spellname421260 і сповільнюються на $421260s2% за кожен заряд протягом $421260d.\n\n\n\nСтрибок знімає один заряд $@spellname421260." },
    { en = "Aurostor knocks aside his current target, inflicting $s1 Physical damage and sending them soaring through the air.", ua = "Ауростор відкидає свою поточну ціль убік, завдаючи $s1 фізичної шкоди й підкидаючи її в повітря." },
    { en = "The $@spellname397114 inflicts $s1 Fire damage to players in their path and stuns them for $d.", ua = "$@spellname397114 завдає $s1 шкоди вогнем гравцям на своєму шляху та оглушує їх на $d." },
    { en = "Upon reaching 100 energy, Eranog summons an army of $@spellname397114s and emits $@spellname370410 every $370307t1 sec for $d.", ua = "Сягнувши 100 енергії, Ераног прикликає армію створінь «$@spellname397114s» і кожні $370307t1 сек. випромінює $@spellname370410 протягом $d." },
    { en = "The $@spellname390716 fixates on a player, pursuing them relentlessly.", ua = "$@spellname390716 фіксується на гравцеві й невпинно його переслідує." },
    { en = "The $@spellname396039 creates $@spellname394917 that jump between several players, inflicting $s1 Fire damage on impact and an additional $s2 Fire damage every $t2 sec for $d. This effect stacks.", ua = "$@spellname396039 створює «$@spellname394917», що перестрибують між кількома гравцями, завдаючи $s1 шкоди вогнем при влучанні та додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d. Цей ефект накопичується." },
    { en = "The $@spellname396039 inflicts $s1 Fire damage to a player.", ua = "$@spellname396039 завдає гравцеві $s1 шкоди вогнем." },
    { en = "Eranog's scales pulse with flames, inflicting $s1 Fire damage to all players", ua = "Луска Ераноґа пульсує полум'ям, завдаючи $s1 шкоди вогнем усім гравцям" },
    { en = "Eranog roars, exhaling flames that inflict $s1 Fire damage to all players and an additional $s2 Fire damage every $t2 sec for $d. This effect stacks.$?diff15|diff16[\n\n\n\nDestroys $@spellname396022.][]", ua = "Ераног реве, видихаючи полум'я, що завдає $s1 шкоди вогнем усім гравцям і додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d. Цей ефект накопичується.$?diff15|diff16[\n\n\n\nЗнищує «$@spellname396022».][]" },
    { en = "Eranog pulls forth $@spellname396022 from the chamber floor, inflicting $396025s1 Physical damage to players within $396025a1 yards and knocking them away.\n\n\n\nThese spikes explode into $@spellname396030 when Eranog bellows an $@spellname396023.", ua = "Ераног здіймає «$@spellname396022» з підлоги палати, завдаючи $396025s1 фізичної шкоди гравцям у межах $396025a1 ярдів і відкидаючи їх.\n\n\n\nЦі шпичаки вибухають на «$@spellname396030», коли Ераног видає рев «$@spellname396023»." },
    { en = "Eranog swings his molten axe, inflicting $s2 Fire damage to players in a frontal cone.", ua = "Ераног змахує своєю розплавленою сокирою, завдаючи $s2 шкоди вогнем гравцям у фронтальному конусі." },
    { en = "Eranog's melee attacks cause searing wounds that inflict $397113s1 Fire damage every $394906t1 sec for $394906d. This effect stacks.", ua = "Ближні атаки Ераноґа лишають пекучі рани, що завдають $397113s1 шкоди вогнем кожні $394906t1 сек. протягом $394906d. Цей ефект накопичується." },
    { en = "A pool of lava that inflicts $370648s1 Fire damage every $370648t1 sec to players standing within it.", ua = "Калюжа лави, що завдає $370648s1 шкоди вогнем кожні $370648t1 сек. гравцям, які в ній стоять." },
    { en = "Eranog wreathes several players in flames. Upon expiration a $@spellname390717 forms at each player's location, inflicting $390717s1 Fire damage to players within $390717A1 yards.\n\n\n\nA $@spellname390716 spills forth from each $@spellname390717, leaving behind a $@spellname370648.", ua = "Ераног огортає кількох гравців полум'ям. Зі спливом часу на місці кожного гравця утворюється «$@spellname390717», що завдає $390717s1 шкоди вогнем гравцям у межах $390717A1 ярдів.\n\n\n\nЗ кожного «$@spellname390717» виривається $@spellname390716, лишаючи по собі $@spellname370648." },
    { en = "Eranog wreathes his current target in flames. Upon expiration a $@spellname396033 forms at the player's location, inflicting $396033s1 Fire damage to players within $396033A1 yards.\n\n\n\nA $@spellname396039 spills forth from the $@spellname390717, leaving behind a $@spellname370648.", ua = "Ераног огортає свою поточну ціль полум'ям. Зі спливом часу на місці гравця утворюється «$@spellname396033», що завдає $396033s1 шкоди вогнем гравцям у межах $396033A1 ярдів.\n\n\n\nЗ «$@spellname390717» виривається $@spellname396039, лишаючи по собі $@spellname370648." },
    { en = "Molten spikes explode, creating fissures that inflict $s1 Fire damage to players within $a1 yards of the impact locations and knocking them upwards.", ua = "Розплавлені шпичаки вибухають, утворюючи розколини, що завдають $s1 шкоди вогнем гравцям у межах $a1 ярдів від місць влучання та підкидають їх угору." },
    { en = "The aftershock of $@spellname380487 inflicts $s1 Nature damage to players within $A1 yards, knocking them upwards.", ua = "Поштовх від «$@spellname380487» завдає $s1 шкоди від сил природи гравцям у межах $A1 ярдів, підкидаючи їх угору." },
    { en = "Terros fractures the earth, inflicting $s1 Nature damage to players within $A1 yards of the impact location and knocking them upwards.\n\n\n\nCauses $@spellname378861 to fall from the ceiling.", ua = "Террос розколює землю, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів від місця влучання та підкидаючи їх угору.\n\n\n\nЗмушує «$@spellname378861» падати зі стелі." },
    { en = "Upon filling the chamber with $@spellname382458, Terros begins radiating devastating waves of earthen energy that inflict $s1 Nature damage and increase damage taken from $@spellname377505 by $377507s1%.", ua = "Наповнивши палату «$@spellname382458», Террос починає випромінювати спустошливі хвилі земної енергії, що завдають $s1 шкоди від сил природи та підвищують отримувану від «$@spellname377505» шкоду на $377507s1%." },
    { en = "The earth erupts beneath several players, inflicting $381315s1 Nature damage to players within $381315A1 yards and knocking them back.\n\n\n\nUpon erupting, begins to inflict $395686s1 Nature damage to all players every $382776t1 sec until destroyed. \n\n\n\nUpon destruction, releases a $@spellname381576.", ua = "Земля вибухає під кількома гравцями, завдаючи $381315s1 шкоди від сил природи гравцям у межах $381315A1 м та відкидаючи їх.\n\n\n\nПісля вибуху починає завдавати $395686s1 шкоди від сил природи всім гравцям кожні $382776t1 с, доки не буде знищено. \n\n\n\nПісля знищення вивільняє $@spellname381576." },
    { en = "Terros launches a swirling vortex of energized earth at a player, inflicting $381298s1 Nature damage $?diff16[to all players when it impacts, reduced by the number of players within $389284A1 yards of the impact location.\n\n\n\nCauses eruptions of $@spellname381486][split evenly among players within $381298A1 yards and causing eruptions of $@spellname381486].\n\n\n\nAfterward, an $@spellname386400 occurs at the impact location.", ua = "Террос пускає в гравця вируючий вихор наснаженої землі, завдаючи $381298s1 шкоди від сил природи $?diff16[усім гравцям при влучанні, зменшеної залежно від кількості гравців у межах $389284A1 ярдів від місця влучання.\n\n\n\nСпричиняє виверження «$@spellname381486»][, що розподіляється порівну між гравцями в межах $381298A1 ярдів і спричиняє виверження «$@spellname381486»].\n\n\n\nПісля цього на місці влучання стається «$@spellname386400»." },
    { en = "$@spellname381576 inflicts $s1 Nature damage to all players.\n\n\n\nInflicts an additional $381595s1 Nature damage every $381595t1 sec for $381595d.", ua = "$@spellname381576 завдає $s1 шкоди від сил природи всім гравцям.\n\n\n\nЗавдає додатково $381595s1 шкоди від сил природи кожні $381595t1 сек. протягом $381595d." },
    { en = "If no player is within reach, Terros continually emits tectonic pulses that inflict $388396s1 Nature damage.", ua = "Якщо поблизу немає жодного гравця, Террос безперервно випускає тектонічні пульсації, що завдають $388396s1 шкоди від сил природи." },
    { en = "A jagged earth column erupts from the ground, inflicting $s1 Nature damage to players within $A1 yards and knocking them upwards.", ua = "Із землі здіймається зазубрена земляна колона, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів і підкидаючи їх угору." },
    { en = "Rubble falls from the ceiling, inflicting $s1 Nature damage to players within $A1 yards of the impact location$?diff15|diff16[ and leaving behind $@spellname382458.][.]", ua = "Зі стелі падає каміння, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярдів від місця влучання$?diff15|diff16[ і лишаючи по собі «$@spellname382458».][.]" },
    { en = "Upon reaching 100 energy, Terros unleashes his volatile power with a brutal slam.\n\n\n\nThis slam inflicts $381775s1 Nature damage to all players in a frontal cone, destroys $@spellname381486, and leaves $@spellname382458 in its wake.\n\n\n\nThe cavern shutters from the force of the impact, inflicting an additional $386277s1 Nature damage to all players and causing $@spellname378861 to fall from the ceiling.", ua = "Сягнувши 100 енергії, Террос вивільняє свою нестійку міць нищівним ударом.\n\n\n\nЦей удар завдає $381775s1 шкоди від сил природи всім гравцям у фронтальному конусі, знищує «$@spellname381486» і лишає по собі «$@spellname382458».\n\n\n\nПечера здригається від сили удару, завдаючи додатково $386277s1 шкоди від сил природи всім гравцям і змушуючи «$@spellname378861» падати зі стелі." },
    { en = "The earth pulses with resonating energy, inflicting $s1 Nature damage every $t1 sec to players within the area.", ua = "Земля пульсує резонуючою енергією, завдаючи $s1 шкоди від сил природи кожні $t1 сек. гравцям у цій ділянці." },
    { en = "Terros discharges a line of tectonic energy that inflicts $381781s1 Physical damage to players and increases damage taken by $376276s1% for $376276d. This effect stacks.\n\n\n\nDestroys any $@spellname381486 caught in the blast.", ua = "Террос випускає лінію тектонічної енергії, що завдає $381781s1 фізичної шкоди гравцям і підвищує отримувану шкоду на $376276s1% протягом $376276d. Цей ефект накопичується.\n\n\n\nЗнищує будь-яку «$@spellname381486», що потрапила під вибух." },
    { en = "The dust from $@spellname396351 explodes, inflicting $s1 Nature damage to all players per application consumed in the explosion.\n\n\n\nThe blast causes the ground underneath the epicenter to become $@spellname394347.", ua = "Пил від «$@spellname396351» вибухає, завдаючи $s1 шкоди від сил природи всім гравцям за кожну застосовану ним порцію, спожиту у вибуху.\n\n\n\nВибух перетворює землю під епіцентром на «$@spellname394347»." },
    { en = "Terros strikes the ground, infusing all players with volatile dust that inflicts $396538s1 damage every $391592t1 sec.\n\n\n\nIf two afflicted players touch, the harmful dust is removed in an $@spellname391322.", ua = "Террос б'є по землі, насичуючи всіх гравців нестійким пилом, що завдає $396538s1 шкоди кожні $391592t1 сек.\n\n\n\nЯкщо двоє уражених гравців торкнуться одне одного, шкідливий пил знімається через «$@spellname391322»." },
    { en = "Opalfang convokes primal earth, releasing forceful blasts of earthen magic that inflict $386354s1 Nature damage to all players every $t1 sec. This damage increases over time.\n\n\n\nOpalfang channels until all members of the Primal Council are defeated.", ua = "Опалозуб скликає первісну землю, вивільняючи потужні спалахи земляної магії, що завдають $386354s1 шкоди від сил природи всім гравцям кожні $t1 сек. Ця шкода з часом зростає.\n\n\n\nОпалозуб підтримує її, доки не буде здолано всіх членів Первісної Ради." },
    { en = "The player is overcome by the $@spellname371836, and is trapped in a tomb of ice that inflicts $s1 Frost damage and an additional $s3 Frost damage every $t3 sec. until freed.", ua = "Гравця огортає «$@spellname371836», ув'язнюючи його в крижаній гробниці, що завдає $s1 шкоди від морозу та додатково $s3 шкоди від морозу кожні $t3 сек., доки гравця не звільнять." },
    { en = "Upon defeat, Kadros convokes the plane of ice, inflicting $386661s1 Frost damage to all players every $t1 sec. This damage increases over time.\n\n\n\nKadros channels until all members of the Primal Council are defeated.", ua = "Після поразки Кадрос прикликає вимір льоду, завдаючи $386661s1 од. шкоди Морозом усім гравцям кожні $t1 с. Ця шкода зростає з часом.\n\n\n\nКадрос підтримує закляття, доки не буде здолано всіх членів Первинної Ради." },
    { en = "Upon defeat, Dathea convokes the plane of storms, inflicting $386376s1 Nature damage to all players every $t1 sec. This damage increases over time.\n\n\n\nDathea channels until all members of the Primal Council are defeated.", ua = "Зазнавши поразки, Датея скликає вимір бур, завдаючи $386376s1 шкоди від сил природи всім гравцям кожні $t1 сек. Ця шкода з часом зростає.\n\n\n\nДатея підтримує його, доки не буде здолано всіх членів Первісної Ради." },
    { en = "Dathea hurls lightning at a random player, inflicting $s1 Nature damage.", ua = "Датея жбурляє блискавку у випадкового гравця, завдаючи $s1 шкоди від сил природи." },
    { en = "Earthen Pillars send out shockwaves, inflicting $s1 Nature damage every $396343t1 sec. to all players.", ua = "Земляні Стовпи випускають ударні хвилі, завдаючи $s1 шкоди від сил природи кожні $396343t1 сек. всім гравцям." },
    { en = "Opalfang erupts pillars of rock from the earth at locations of several players, inflicting $s2 Nature damage to players within $A2 yards and knocking them back.$?DIFF15|DIFF16[ \n\n\n\nOn this difficulty, Earthen Pillars erupt with $@spellname396328.][]", ua = "Опалозуб здіймає кам'яні стовпи із землі на місцях кількох гравців, завдаючи $s2 шкоди від сил природи гравцям у межах $A2 ярдів і відкидаючи їх назад.$?DIFF15|DIFF16[ \n\n\n\nНа цій складності Земляні Стовпи здіймаються з «$@spellname396328».][]" },
    { en = "Upon reaching 100 energy, Embar infuses her axe with lava and cleaves the player, inflicting $s1 Fire damage and an additional $s2 Fire damage every $t2 sec. for $d to all players in front of Embar. This effect stacks.", ua = "Сягнувши 100 енергії, Ембар насичує свою сокиру лавою і розтинає гравця, завдаючи $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d усім гравцям перед Ембар. Цей ефект накопичується." },
    { en = "Embar convokes the plane of fire, inflicting $386291s1 Fire damage to all players every $t1 sec. This damage increases over time.\n\n\n\nEmbar channels until all members of the Primal Council are defeated.", ua = "Ембар скликає вимір вогню, завдаючи $386291s1 шкоди вогнем усім гравцям кожні $t1 сек. Ця шкода з часом зростає.\n\n\n\nЕмбар підтримує його, доки не буде здолано всіх членів Первісної Ради." },
    { en = "A bolt of lightning strikes a random player, inflicting $s1 Nature damage and then jumping to nearby players.", ua = "Розряд блискавки влучає у випадкового гравця, завдаючи $s1 шкоди від сил природи, а потім перестрибує на сусідніх гравців." },
    { en = "Opalfang crushes her current target, inflicting $s1 Physical damage and increasing all Physical damage taken by $s2%. This effect stacks.", ua = "Опалозуб трощить свою поточну ціль, завдаючи $s1 фізичної шкоди й збільшуючи всю отримувану фізичну шкоду на $s2%. Цей ефект накопичується." },
    { en = "Kadros propels a spike of ice at a random player, inflicting $s1 Frost damage.", ua = "Кадрос метає крижаний шпичак у випадкового гравця, завдаючи $s1 шкоди від морозу." },
    { en = "Upon reaching 100 energy, Kadros channels a freezing storm for $373059d. The chill inflicts $s1 Frost damage every $373059t2 sec., increasing Frost damage taken by $s4% and reducing Fire damage taken by $s3% for $d. This effect stacks. $@spellname371514 removes this effect.\n\n\n\nUpon reaching 10 applications, players are trapped in a $@spellname371591.", ua = "Досягнувши 100 одиниць енергії, Кадрос насилає крижану бурю на $373059d. Холод завдає $s1 шкоди від морозу щосекунди ($373059t2), збільшує отримувану шкоду від морозу на $s4% і зменшує отримувану шкоду від вогню на $s3% на $d. Цей ефект накопичується. $@spellname371514 знімає цей ефект.\n\n\n\nДосягнувши 10 нашарувань, гравці опиняються в пастці — $@spellname371591." },
    { en = "Permafrost forms on the lower reaches of Sennarth's lair, inflicting $s1 Frost damage every $t1 sec to players within the affected area. This effect stacks.", ua = "Нижні ділянки лігва Сеннарта вкриває вічна мерзлота, завдаючи $s1 шкоди від морозу щосекунди ($t1) гравцям у враженій зоні. Цей ефект накопичується." },
    { en = "Sennarth chills players with volatile rime, inflicting $s1 Frost damage every $t1 sec for $d and causing a $@spellname371979 upon expiration or removal.", ua = "Сеннарт вкриває гравців нестійким інеєм, завдаючи $s1 шкоди від морозу щосекунди ($t1) протягом $d і спричиняючи $@spellname371979 після завершення чи зняття." },
    { en = "An icy explosion inflicts $s1 Frost damage to all other players within $A1 yards.", ua = "Крижаний вибух завдає $s1 шкоди від морозу всім іншим гравцям у радіусі $A1 м." },
    { en = "Sennarth releases a burst of webs, inflicting $s1 Physical damage to all players and pushing them away.", ua = "Сеннарт випускає сплеск павутини, завдаючи $s1 фізичної шкоди всім гравцям і відкидаючи їх." },
    { en = "Sennarth attaches gossamer webs to all players, inflicting $s1 Physical damage and drawing them inwards.", ua = "Сеннарт чіпляє до всіх гравців тонке павутиння, завдаючи $s1 фізичної шкоди й притягуючи їх до себе." },
    { en = "Sennarth blasts her current target with a ball of webs, inflicting $s1% of normal attack damage and causing them to suffer $385083s2% increased damage from Web Blasts for $385083d. This effect stacks.", ua = "Сеннарт б'є по поточній цілі клубком павутини, завдаючи $s1% звичайної шкоди від атаки й змушуючи її отримувати на $385083s2% більше шкоди від Павутинних залпів протягом $385083d. Цей ефект накопичується." },
    { en = "Sennarth targets several players with spiderwebs, inflicting $373048s1 Physical damage every $373048t1 sec for $373048d. At the end of the duration, she knocks them back while instantly causing $@spellname372044 and releasing $@spellname372030 at their locations.", ua = "Сеннарт бере на приціл кількох гравців павутиною, завдаючи $373048s1 фізичної шкоди щосекунди ($373048t1) протягом $373048d. Наприкінці дії вона відкидає їх, миттєво спричиняючи $@spellname372044 й вивільняючи $@spellname372030 на їхніх місцях." },
    { en = "Sennarth chills the very air around herself, causing players to suffer $s1% increased Frost damage until she dies. This effect stacks.", ua = "Сеннарт остуджує саме повітря довкола себе, змушуючи гравців отримувати на $s1% більше шкоди від морозу, доки вона не загине. Цей ефект накопичується." },
    { en = "Caustic acid dissolves the target's defenses, increasing Nature damage taken by $s1% for $d. This effect stacks.", ua = "Їдка кислота роз'їдає захист цілі, збільшуючи отримувану шкоду від сил природи на $s1% протягом $d. Цей ефект накопичується." },
    { en = "$@spellname371979 leaves behind a $@spellname373559. These plumes inflict $s1 Frost damage and knock back players who come into contact with it.", ua = "$@spellname371979 лишає по собі $@spellname373559. Ці хмари завдають $s1 шкоди від морозу й відкидають гравців, що торкаються їх." },
    { en = "The Frostbreath Arachnid effuses a chilling vapor, increasing its Frost damage done by $s2% and inflicting $s1 Frost damage to all players. This effect stacks.", ua = "Морозодишний арахнід випускає крижану пару, збільшуючи завдану ним шкоду від морозу на $s2% і завдаючи $s1 шкоди від морозу всім гравцям. Цей ефект накопичується." },
    { en = "Sennarth wreathes herself in a chilling storm, creating $@spellname372055 in a large area. As long as the storm persists, Sennarth takes $s2% less damage and inflicts $372540s1 Frost damage to all players every $372540t1 sec for $372540d. This effect repeats and grows in intensity every $t1 sec.", ua = "Сеннарт огортає себе крижаною бурею, створюючи $@spellname372055 на великій площі. Доки буря триває, Сеннарт отримує на $s2% менше шкоди й завдає $372540s1 шкоди від морозу всім гравцям щосекунди ($372540t1) протягом $372540d. Цей ефект повторюється й посилюється щосекунди ($t1)." },
    { en = "Standing within sticky cobwebs provides resistance to displacement and sliding, as well as reduces the player's movement speed by $s1% for $d. Can be removed by $@spellname372045.\n\n\n\nUpon reaching $s2 applications, the target becomes $@spellname372044.", ua = "Перебування в липкому павутинні дає опір до зміщення й ковзання, а також зменшує швидкість пересування гравця на $s1% протягом $d. Знімається за допомогою $@spellname372045.\n\n\n\nДосягнувши $s2 нашарувань, ціль стає $@spellname372044." },
    { en = "Spiderwebs fully enwrap the player, stunning them for $d. Can be removed by $@spellname372045.", ua = "Павутиння повністю огортає гравця, оглушуючи його на $d. Можна зняти за допомогою $@spellname372045." },
    { en = "The Caustic Spiderling erupts upon death, inflicting $s1 Nature damage to players within $A1 yards. \n\n\n\nThe eruption destroys and removes webbing from the ground as well as $@spellname372030 and $@spellname372044 from players struck.", ua = "Їдке павутиння гине з вибухом, завдаючи $s1 шкоди від сил природи гравцям у радіусі $A1 м. \n\n\n\nВибух руйнує й прибирає павутиння із землі, а також знімає $@spellname372030 та $@spellname372044 з уражених гравців." },
    { en = "Sennarth exhales a frozen vapor that creates patches of $@spellname372053.", ua = "Сеннарт видихає заморожену пару, що створює ділянки — $@spellname372053." },
    { en = "Standing atop $@spellname372053 inflicts $s1 Frost damage every $t1 sec and causes players to slide.", ua = "Перебування на $@spellname372053 завдає $s1 шкоди від морозу щосекунди ($t1) і змушує гравців ковзати." },
    { en = "Spiderwebs enwrap the player, reducing their movement speed by $s1% for $d. Can be removed by $@spellname372045.", ua = "Павутиння обплутує гравця, зменшуючи його швидкість пересування на $s1% протягом $d. Знімається за допомогою $@spellname372045." },
    { en = "The Frostbreath Arachnid emits a freezing breath, inflicting $s1 Frost damage in a frontal cone and creating patches of $@spellname372055.", ua = "Морозодишний арахнід випускає крижаний подих, завдаючи $s1 шкоди від морозу в передньому конусі й створюючи ділянки $@spellname372055." },
    { en = "Sennarth causes spider webs to envelop several players, inflicting $s1 Physical damage and causing them to drop $@spellname372030 at their locations every $t1 sec for $d.", ua = "Сеннарт огортає павутинням кількох гравців, завдаючи $s1 фізичної шкоди й змушуючи їх скидати $@spellname372030 на своїх місцях щосекунди ($t1) протягом $d." },
    { en = "Sennarth forms whirling columns of ice, which inflict $s1 Frost damage and knock back any players they come in contact with.", ua = "Сеннарт утворює вихрові колони з криги, що завдають $s1 шкоди від морозу й відкидають будь-яких гравців, що торкаються їх." },
    { en = "Inflicts $s1 Nature damage to any player that touches the tempest and knocks them up into the air.", ua = "Завдає $s1 шкоди від сил природи будь-якому гравцеві, що торкається бурі, і підкидає його в повітря." },
    { en = "Energizing a Dormant Infuser discharges electricity to all players, inflicting $s1 Nature damage, and an additional $s2 Nature damage every $t2 sec for $d. This effect stacks.", ua = "Заряджання сплячого вливача вивільняє електрику на всіх гравців, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Dathea marks the player with lightning, inflicting $s3 Nature damage on impact, $s2 Nature damage every $t2 sec, and increasing Nature damage taken by $s1%$?DIFF16[][ for $d]. This effect stacks.\n\n\n\nMoving within $s4 yards of other players will duplicate and refresh $@spellname391686.", ua = "Датея позначає гравця блискавкою, завдаючи $s3 шкоди від сил природи при влучанні, $s2 шкоди від сил природи кожні $t2 с і збільшуючи отримувану шкоду від сил природи на $s1%$?DIFF16[][ протягом $d]. Цей ефект накопичується.\n\n\n\nПереміщення в межах $s4 ярдів від інших гравців дублює та оновлює $@spellname391686." },
    { en = "The Volatile Infuser channels its essence into Dathea, periodically increasing her damage by $388029s1% for $388029d. This effect stacks.", ua = "Нестійкий вливач спрямовує свою есенцію в Датею, періодично збільшуючи її шкоду на $388029s1% на $388029d. Цей ефект накопичується." },
    { en = "$?diff15|diff16[Dathea harnesses primal energies to summon Volatile Infusers and Thunder Callers to her aid.][Dathea harnesses primal energies to summon Volatile Infusers to her aid.]", ua = "$?diff15|diff16[Датея черпає первісні енергії, щоб прикликати собі на поміч нестійких вливачів і покликачів грому.][Датея черпає первісні енергії, щоб прикликати собі на поміч нестійких вливачів.]" },
    { en = "Upon death the Volatile Infuser explodes violently, inflicting $s2 Nature damage to all players and knocking them back.", ua = "Гинучи, нестійкий вливач бурхливо вибухає, завдаючи $s2 шкоди від сил природи всім гравцям і відкидаючи їх." },
    { en = "Dathea fires off bolts of wind that upon impact inflicts $388309s1 Nature damage to all players within $388309A1 yds and creates a $@spellname375424 at their location.", ua = "Датея випускає пориви вітру, які при влучанні завдають $388309s1 од. шкоди Природою всім гравцям у межах $388309A1 ярдів і створюють $@spellname375424 на їхньому місці." },
    { en = "Dathea whips up a vortex at her location, pulling players towards her and inflicting $388290s1 Nature damage every $388290t1 sec for $d.\n\n\n\nIf a player is pulled into the vortex they are knocked upwards.", ua = "Датея здіймає вихор на своєму місці, притягуючи гравців до себе й завдаючи $388290s1 шкоди від сил природи щосекунди ($388290t1) протягом $d.\n\n\n\nЯкщо гравця затягує у вихор, його підкидає вгору." },
    { en = "The Thunder Caller unleashes a storm bolt at a target, inflicting $s1 Nature damage.", ua = "Закликач Грому випускає у ціль штормову блискавку, завдаючи $s1 од. шкоди Природою." },
    { en = "The Volatile Infuser periodically expels Unstable Gusts inflicting $s1 Nature damage to players within $A2 yards of the impact locations.", ua = "Нестійкий вливач періодично випускає нестійкі пориви, завдаючи $s1 шкоди від сил природи гравцям у радіусі $A2 м від місць влучання." },
    { en = "A thunderstorm lingers after Dathea's minions spawn, causing lightning to strike players for $s1 Nature damage every $s2 sec.\n\n\n\nEach strike causes players to take $s3% increased damage from $@spellname390449 for $d. This effect stacks.", ua = "Після появи прислужників Датеї лишається гроза, через яку блискавки б'ють гравців, завдаючи $s1 шкоди від сил природи щосекунди ($s2).\n\n\n\nКожен удар змушує гравців отримувати на $s3% більше шкоди від $@spellname390449 протягом $d. Цей ефект накопичується." },
    { en = "The Volatile Infuser slashes its current target, inflicting $s1 Nature damage.", ua = "Нестійкий вливач шматує свою поточну ціль, завдаючи $s1 шкоди від сил природи." },
    { en = "If Dathea's current target is not within reach, she blasts them with a buffet of air that inflicts $s1 Nature damage.", ua = "Якщо поточна ціль Датеї поза досяжністю, вона б'є по ній поривом повітря, що завдає $s1 шкоди від сил природи." },
    { en = "Dathea sends out a series of crosswinds, adjusting the location of every $@spellname375424.\n\n\n\nUpon arriving at their new location each Tempest unleashes a burst of wind, inflicting $388407s1 Nature damage to all players within $388407A1 yards.", ua = "Датея насилає низку бічних вітрів, змінюючи місце кожного $@spellname375424.\n\n\n\nПрибувши на нове місце, кожна буря вивільняє порив вітру, завдаючи $388407s1 шкоди від сил природи всім гравцям у радіусі $388407A1 м." },
    { en = "Dathea slams her empowered fist into her current target with a burst of air, inflicting $s1 Physical damage and knocking them back.\n\n\n\nEach impact increases the damage and knockback taken by $s2% for $d. This effect stacks.", ua = "Датея вкладає в посилений кулак силу повітря й б'є ним по поточній цілі, завдаючи $s1 фізичної шкоди та відкидаючи її.\n\n\n\nКожен удар підвищує отримувану шкоду та відкидання на $s2% на $d. Цей ефект накопичується." },
    { en = "$@spellname375424s periodically emit built up winds, inflicting $s1 Nature damage to all players every $389221t1 sec.", ua = "$@spellname375424 час від часу вивільняє накопичені вітри, завдаючи $s1 шкоди від сил природи всім гравцям кожні $389221t1 сек." },
    { en = "The caster infuses players with fire, causing them to mark their current location every $t1 sec for $d. The marked location explodes after $S2 sec, inflicting $374025s1 Fire damage to players within $374025A1 yards.", ua = "Заклинач наповнює гравців вогнем, через що ті позначають своє поточне місцеперебування кожні $t1 с протягом $d. Позначене місце вибухає через $S2 с, завдаючи $374025s1 шкоди вогнем гравцям у межах $374025A1 м." },
    { en = "Kurog periodically surges with the power of all four altars while standing in the center of the chamber, inflicting $371981s1 Elemental damage to all players every $t1 sec. This effect stacks.", ua = "Перебуваючи в центрі зали, Курог раз у раз сповнюється силою всіх чотирьох вівтарів, завдаючи $371981s1 стихійної шкоди всім гравцям кожні $t1 сек. Цей ефект накопичується." },
    { en = "The Flamewrought Eradicator ignites $@spellname374554s within the chamber, creating $@spellname391555s.\n\n\n\nPlayers who stand within a $@spellname391555 suffer $s1 Fire damage every $t1 sec and reduce its flame. After $s3 sec a Smoldering Hellion emerges from each $@spellname391555.", ua = "Полум'яний Винищувач підпалює $@spellname374554 в залі, створюючи $@spellname391555.\n\n\n\nГравці, що стоять у $@spellname391555, отримують $s1 шкоди вогнем кожні $t1 сек і пригашають його полум'я. За $s3 сек із кожного $@spellname391555 з'являється Тліюча Зловиплодка." },
    { en = "Kurog inflicts $396072s1 Frost damage to all players every $396074t1 sec while attuned to the Altar of Frost. Increases the damage of $@spellname374916 by $s1%. This effect stacks.", ua = "Налаштувавшись на Вівтар Морозу, Курог завдає $396072s1 шкоди від морозу всім гравцям кожні $396074t1 сек. Підвищує шкоду $@spellname374916 на $s1%. Цей ефект накопичується." },
    { en = "Kurog inflicts $396068s1 Nature damage to all players every $396067t1 sec while attuned to the Altar of Earth. Increases the damage of $@spellname374917  by $s1%. This effect stacks.", ua = "Налаштувавшись на Вівтар Землі, Курог завдає $396068s1 шкоди від сил природи всім гравцям кожні $396067t1 сек. Підвищує шкоду $@spellname374917 на $s1%. Цей ефект накопичується." },
    { en = "Kurog inflicts $396077s1 Nature damage to all players every $396076t1 sec while attuned to the Altar of Storm. Increases the damage of $@spellname374918 by $s1%. This effect stacks.", ua = "Налаштувавшись на Вівтар Бурі, Курог завдає $396077s1 шкоди від сил природи всім гравцям кожні $396076t1 сек. Підвищує шкоду $@spellname374918 на $s1%. Цей ефект накопичується." },
    { en = "Kurog charges several players with electricity for $d. Upon expiration, charged players inflict $390921s1 Nature damage to players within $390921a1 yards.", ua = "Курог заряджає кількох гравців електрикою на $d. По завершенні заряджені гравці завдають $390921s1 шкоди від сил природи гравцям у межах $390921a1 м." },
    { en = "Kurog envelops several players in earth, causing their next $391056s1 healing to be absorbed.", ua = "Курог огортає кількох гравців землею, через що їхні наступні $391056s1 зцілення поглинаються." },
    { en = "The elemental surges with power, inflicting $396222s1 Nature damage every $396222t1 sec. This effect stacks.", ua = "Елементаль сповнюється силою, завдаючи $396222s1 шкоди від сил природи кожні $396222t1 сек. Цей ефект накопичується." },
    { en = "The elemental surges with power, inflicting $396212s1 Frost damage every $396212t1 sec. This effect stacks.", ua = "Елементаль сповнюється силою, завдаючи $396212s1 шкоди від морозу кожні $396212t1 сек. Цей ефект накопичується." },
    { en = "Channels a lethal current into the closest player, inflicting $391711s1 Nature damage to all players within $391711a1 yards of the target every $t1 sec for $d.", ua = "Спрямовує смертоносний струм у найближчого гравця, завдаючи $391711s1 шкоди від сил природи всім гравцям у межах $391711a1 ярдів від цілі кожні $t1 с протягом $d." },
    { en = "Kurog unleashes an attack at his current target, inflicting $s1 Elemental damage to players in a frontal cone and knocking them back. Additionally, players suffer $s2 Elemental damage every $t2 sec for $d. This effect stacks.", ua = "Курог завдає удару своїй поточній цілі, завдаючи $s1 стихійної шкоди гравцям у фронтальному конусі та відкидаючи їх. Крім того, гравці зазнають $s2 стихійної шкоди кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "The elemental surges with power, inflicting $396201s1 Fire damage every $396201t1 sec. This effect stacks.", ua = "Елементаль сповнюється силою, завдаючи $396201s1 шкоди вогнем кожні $396201t1 сек. Цей ефект накопичується." },
    { en = "The chill causes the player to become incapacitated and inflicts $s4 Frost damage every $t4 sec for $d. This effect cannot be mitigated or avoided.", ua = "Холод знесилює гравця та завдає $s4 шкоди від морозу кожні $t4 сек упродовж $d. Цей ефект неможливо ні послабити, ні уникнути." },
    { en = "Molten magma inflicts $s1 Fire damage every $t1 sec to players standing within it.", ua = "Розплавлена магма завдає $s1 шкоди вогнем кожні $t1 сек гравцям, що стоять у ній." },
    { en = "The Tectonic Crusher infuses several players with volatile earth for $d. Upon expiration, infused players inflict $374428s1 Nature damage to players within $374428a1 yards.", ua = "Тектонічний Дробильник наповнює кількох гравців нестійкою землею на $d. По завершенні наповнені гравці завдають $374428s1 шкоди від сил природи гравцям у межах $374428a1 м." },
    { en = "Slams the earth, causing rocks to erupt from nearby locations, inflicting $374432s1 Nature damage to players within $374432a1 yards and knocking them away.", ua = "Б'є по землі, через що поблизу вибухають каменюки, завдаючи $374432s1 шкоди від сил природи гравцям у межах $374432a1 м і відкидаючи їх." },
    { en = "The impact of $@spellname375450 chills players to the bone. Upon reaching $s1 applications, the player becomes $@spellname372517.", ua = "Удар $@spellname375450 проймає гравців холодом до кісток. Сягнувши $s1 нашарувань, гравець стає $@spellname372517." },
    { en = "Kurog afflicts all players with a biting chill that inflicts $s1 Frost damage every $t1 sec for $d.", ua = "Курог уражає всіх гравців пронизливим холодом, що завдає $s1 шкоди від морозу кожні $t1 с протягом $d." },
    { en = "The caster pulls Earth Breakers from the ground, inflicting $s1 Nature damage to players with $a1 yards of the eruptions and knocking them back.", ua = "Той, хто творить закляття, витягує Земляних Трощителів із землі, завдаючи $s1 пог. природою гравцям у межах $a1 ярдів від місць виверження й відкидаючи їх назад." },
    { en = "Each consecutive melee attack against the same target increases the elemental's Physical damage by $s1%. This effect stacks.\n\n\n\n$@spellname374321 is removed when the elemental melee attacks a new target.", ua = "Кожна наступна атака ближнього бою по тій самій цілі підвищує фізичну шкоду елементаля на $s1%. Цей ефект накопичується.\n\n\n\n$@spellname374321 знімається, коли елементаль завдає удару ближнього бою новій цілі." },
    { en = "Earth Breaker attacks fracture bones, increasing the player's Physical damage taken by $377780s1% for $377780d. This effect stacks.", ua = "Атаки Земляного Трощія ламають кістки, підвищуючи фізичну шкоду, що отримує гравець, на $377780s1% упродовж $377780d. Цей ефект накопичується." },
    { en = "The caster calls down thunder, inflicting $s1 Nature damage to players within $A1 yards of the impact locations.\n\n\n\nImpacts that fail to hit a player inflict $374218s1 Nature damage to all players.", ua = "Заклинач прикликає грім, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 м від місць удару.\n\n\n\nУдари, що не влучили в гравця, завдають $374218s1 шкоди від сил природи всім гравцям." },
    { en = "Kurog attunes to a primal altar, inflicting $s1 Elemental damage to all players and applying $@spellname374864.", ua = "Курог налаштовується на первісний вівтар, завдаючи $s1 стихійної шкоди всім гравцям і накладаючи $@spellname374864." },
    { en = "Increases damage taken from $@spellname374861 by $s1% for $d. This effect stacks.", ua = "Підвищує шкоду, отриману від $@spellname374861, на $s1% упродовж $d. Цей ефект накопичується." },
    { en = "Kurog unleashes waves of lava, inflicting $373331s1 Fire damage to players caught in their path.", ua = "Курог вивільняє хвилі лави, завдаючи $373331s1 шкоди вогнем гравцям, що опинилися на їхньому шляху." },
    { en = "The caster unleashes frost at its current target, inflicting $s1 Frost damage to players in a frontal cone.\n\n\n\nAdditionally, players' movement speed is reduced by $s2% for $d.", ua = "Заклинач насилає мороз на свою поточну ціль, завдаючи $s1 шкоди від морозу гравцям у фронтальному конусі.\n\n\n\nКрім того, швидкість руху гравців знижується на $s2% протягом $d." },
    { en = "At full power Kurog achieves total attunement with the primal elements gaining all the altar abilities at once. In addition, Grimtotem surges with elemental power, inflicting $396243s1 Elemental damage every $t1 sec. This effect stacks.", ua = "На повній потужності Курог досягає цілковитого єднання з первісними стихіями, отримуючи всі здібності вівтарів водночас. Крім того, Ґрімтотем здіймається стихійною силою, завдаючи $396243s1 стихійної шкоди кожні $t1 с. Цей ефект накопичується." },
    { en = "The caster unleashes thunder at its current target, inflicting $s1 Nature damage to players in a frontal cone. \n\n\n\nVictims are electrified and inflict $393452s1 Nature damage to players within $393452a1 yards after $393431d.", ua = "Заклинач насилає грім на свою поточну ціль, завдаючи $s1 шкоди від сил природи гравцям у фронтальному конусі. \n\n\n\nЖертви наелектризовуються та через $393431d завдають $393452s1 шкоди від сил природи гравцям у межах $393452a1 м." },
    { en = "Magma seeps from the elemental as it is struck, creating lava pools at random locations that inflict $374554s1 Fire damage every $374554t1 sec.", ua = "Коли в елементаля влучають, із нього сочиться магма, утворюючи у випадкових місцях калюжі лави, що завдають $374554s1 шкоди вогнем кожні $374554t1 сек." },
    { en = "Lightning orbs form at nearby locations, inflicting $394726s2 Nature damage to players within $394726A3 yards of the impact locations and knocking them away.\n\n\n\nTouching an orb electrifies the player, destroying the orb but inflicting $395345s1 Nature damage every $t1 sec for $d. This effect stacks.\n\n\n\nAfter $s2 sec the orb explodes, inflicting $391267s1 Nature damage to all players.", ua = "Поблизу утворюються блискавичні сфери, завдаючи $394726s2 шкоди від сил природи гравцям у межах $394726A3 м від місць удару та відкидаючи їх.\n\n\n\nДотик до сфери б'є гравця струмом, знищуючи сферу, але завдаючи $395345s1 шкоди від сил природи кожні $t1 сек упродовж $d. Цей ефект накопичується.\n\n\n\nЗа $s2 сек сфера вибухає, завдаючи $391267s1 шкоди від сил природи всім гравцям." },
    { en = "The caster unleashes flames at its current target, inflicting $s1 Fire damage to players in a frontal cone.\n\n\n\nFlames land nearby, inflicting $393313s1 Fire damage to players within $393313a1 yards of impact locations.", ua = "Заклинач насилає полум'я на свою поточну ціль, завдаючи $s1 шкоди вогнем гравцям у фронтальному конусі.\n\n\n\nПолум'я падає поблизу, завдаючи $393313s1 шкоди вогнем гравцям у межах $393313a1 м від місць влучання." },
    { en = "Vanishes and appears behind a random enemy to unleash $@spellname391696.", ua = "Зникає та з'являється позаду випадкового супротивника, щоб вивільнити $@spellname391696." },
    { en = "The Frozen Destroyer unleashes a nova of frost that inflicts $s1 Frost damage to all players and an additional $s2 Frost damage every $t2 sec for $d. The chilling blast also reduces movement speed by $s3%. This effect stacks.", ua = "Морожений Руйнівник вивільняє нову морозу, що завдає $s1 шкоди від морозу всім гравцям, а також ще $s2 шкоди від морозу кожні $t2 сек упродовж $d. Крижаний вибух до того ж знижує швидкість руху на $s3%. Цей ефект накопичується." },
    { en = "The Frozen Destroyer conjures violent winds centered on itself for $d, inflicting $374625s1 Frost damage every $t1 sec to players farther than $s1 yards away.\n\n\n\nThe winds are slower within $s1 yards, inflicting $374625s2 Frost damage every $t1 sec .", ua = "Морожений Руйнівник прикликає на $d люті вітри, зосереджені на ньому самому, завдаючи $374625s1 шкоди від морозу кожні $t1 сек гравцям, що далі ніж за $s1 м.\n\n\n\nУ межах $s1 м вітри повільніші й завдають $374625s2 шкоди від морозу кожні $t1 сек." },
    { en = "Kurog inflicts $396056s1 Fire damage to all players every $396062t1 sec while attuned to the Altar of Flame. Increases the damage of $@spellname374881 by $s1%. This effect stacks.", ua = "Налаштувавшись на Вівтар Полум'я, Курог завдає $396056s1 шкоди вогнем усім гравцям кожні $396062t1 сек. Підвищує шкоду $@spellname374881 на $s1%. Цей ефект накопичується." },
    { en = "Kurog hurls magma at random players, inflicting $382564s1 Fire damage and causes a $@spellname374554 to form at their destination.", ua = "Курог жбурляє магму у випадкових гравців, завдаючи $382564s1 шкоди вогнем і утворюючи $@spellname374554 в місці їхнього перебування." },
    { en = "The caster unleashes earth at its current target, inflicting $s1 Nature damage to players in a frontal cone and causing their next $376430s1 healing to be absorbed.", ua = "Заклинач насилає землю на свою поточну ціль, завдаючи $s1 шкоди від сил природи гравцям у фронтальному конусі та поглинаючи їхнє наступне зцілення на $376430s1." },
    { en = "The caster hurls a chunk of ice at a player, inflicting $373004s1 Frost damage split evenly among players within $373004a1 yards upon impact.", ua = "Заклинач жбурляє брилу криги в гравця, завдаючи при ударі $373004s1 шкоди від морозу, що рівномірно розподіляється між гравцями в межах $373004a1 м." },
    { en = "The air turns to ice, drastically reducing the temperature and requiring players to remain within $391376A1 yards of at least 2 other players or they gain $@spellname391446.", ua = "Повітря обертається на лід, різко знижуючи температуру й змушуючи гравців триматися в межах $391376A1 ярдів від щонайменше 2 інших гравців, інакше вони отримають $@spellname391446." },
    { en = "The caster creates waves of frozen orbs every $t1 sec for $d, knocking players within $395873A1 yard away as they form. Each orb inflicts $391022s1 Frost damage to any player in its path and stuns them for $391022d.", ua = "Заклинач створює хвилі морожених сфер кожні $t1 сек упродовж $d, відкидаючи гравців у межах $395873A1 м під час їх утворення. Кожна сфера завдає $391022s1 шкоди від морозу будь-якому гравцеві на своєму шляху та приголомшує його на $391022d." },
    { en = "Calls forth lightning, applying auras to random targets. Upon expiration, increases Nature damage taken by $373494s1% and inflicts $373535s1 Nature damage every $373555t1 sec to the closest player for $373555d. This effect stacks.", ua = "Прикликає блискавку, накладаючи аури на випадкові цілі. Після завершення збільшує отриману шкоду Природи на $373494s1% та завдає $373535s1 шкоди Природою кожні $373555t1 сек. найближчому гравцеві протягом $373555d. Цей ефект накопичується." },
    { en = "The elemental surges with power, inflicting $396233s1 Nature damage every $396233t1 sec. This effect stacks.", ua = "Елементаль вибухає енергією, завдаючи $396233s1 шкоди від сил природи кожні $396233t1 с. Цей ефект накопичується." },
    { en = "The caster sends a tectonic ripple through the earth, inflicting $s1 Nature damage to players struck by the ripple.", ua = "Заклинач посилає тектонічну хвилю крізь землю, завдаючи $s1 шкоди від сил природи гравцям, яких накрила хвиля." },
    { en = "Kurog surrounds himself with a barrier of elemental energy, reducing damage taken by $s1%.", ua = "Курог огортає себе бар'єром елементальної енергії, зменшуючи отриману шкоду на $s1%." },
    { en = "The Smoldering Hellion flings a bolt of flame at a player, inflicting $s1 Fire damage.", ua = "Жевріюча Геліонка жбурляє в гравця вогняний снаряд, завдаючи $s1 шкоди вогнем." },
    { en = "The Broodkeeper's diligent care links her life essence to the unhatched eggs, preventing all damage below $375809s2% remaining health. This effect stacks for each intact egg in the room.\n\n\n\nAdditionally, this aura increases the damage done of nearby allies by $396177s1%, decreases damage taken by $396177s2%, and heals $396177s3% of their total health every second for $396177D. This effect stacks.", ua = "Старанна турбота Доглядачки виводку пов'язує її життєву есенцію з невилупленими яйцями, відвертаючи будь-яку шкоду, доки лишається понад $375809s2% здоров'я. Цей ефект накопичується за кожне ціле яйце в кімнаті.\n\n\n\nКрім того, ця аура збільшує завдану шкоду найближчих союзників на $396177s1%, зменшує отриману ними шкоду на $396177s2% і зцілює $396177s3% їхнього загального здоров'я щосекунди протягом $396177D. Цей ефект накопичується." },
    { en = "The Broodkeeper's persistent watch intensely focuses on nearby enemies, increasing the strength of Diurna's Gaze by an additional $s1% every $390569T2 sec for $392193D. This effect stacks.", ua = "Невсипуще пильнування Доглядачки виводку зосереджується на найближчих ворогах, посилюючи дію «Погляду Діурни» додатково на $s1% кожні $390569T2 с протягом $392193D. Цей ефект накопичується." },
    { en = "The Broodkeeper infuses magic into the nearest $376073s1 eggs. After $376074D, these eggs hatch exposing the enemy within.", ua = "Доглядачка виводку насичує магією найближчі $376073s1 яйця. Після $376074D ці яйця вилуплюються, оголюючи ворога всередині." },
    { en = "The Broodkeeper embeds her greatstaff, inflicting $381349s1 Nature damage every $380176T1 sec for $380176D. \n\n\n\nAdditionally, Diurna immediately gains $390711s3 |4application:applications; of $@spellname390711.", ua = "Доглядачка виводку встромляє свій великий посох, завдаючи $381349s1 шкоди від сил природи кожні $380176T1 с протягом $380176D. \n\n\n\nКрім того, Діурна одразу отримує $390711s3 |4застосування:застосувань; ефекту «$@spellname390711»." },
    { en = "The Broodkeeper enters a raging frenzy inflicting $375829s1 Elemental damage to all players and increases damage done from Clutchwatcher's Rage by $375829s2% for $375829D. This effect stacks.", ua = "Доглядачка виводку впадає в шалену лють, завдаючи $375829s1 елементальної шкоди всім гравцям і збільшуючи шкоду від «Люті Доглядачки виводку» на $375829s2% протягом $375829D. Цей ефект накопичується." },
    { en = "The Flamebender conjures Flame Sentries nearby which rotate for $375503D. Players suffer $375578s1 Fire damage every half-second while inside the sentry's effect.", ua = "Полум'яний приборкувач прикликає поблизу Вартових полум'я, що обертаються протягом $375503D. Гравці зазнають $375578s1 шкоди вогнем щопівсекунди, перебуваючи в зоні дії вартового." },
    { en = "Reduces the effectiveness of any healing effects received by $378782s1% for $378782D. This effect stacks, and cannot be mitigated or avoided.", ua = "Зменшує дієвість усіх отриманих ефектів зцілення на $378782s1% протягом $378782D. Цей ефект накопичується, його не можна ні послабити, ні уникнути." },
    { en = "The Broodkeeper keeps a watchful eye on nearby enemies, increasing damage taken by $390569s1% to players within $390561A1 yards, removing the movement speed bonus granted by The Clutchwarren.", ua = "Доглядачка виводку пильно стежить за найближчими ворогами, збільшуючи отриману шкоду на $390569s1% для гравців у межах $390561A1 м і знімаючи бонус до швидкості пересування, наданий Гніздовиськом виводку." },
    { en = "The Broodkeeper embeds her greatstaff nearby, inflicting $375843s1 Nature damage to players within $375843A1 yards every $375842T1 sec for $375842D. \n\n\n\nAdditionally, Diurna immediately gains $390710s3 |4application:applications; of $@spellname390710.", ua = "Доглядачка виводку встромляє поблизу свій великий посох, завдаючи $375843s1 шкоди від сил природи гравцям у межах $375843A1 м кожні $375842T1 с протягом $375842D. \n\n\n\nКрім того, Діурна одразу отримує $390710s3 |4застосування:застосувань; ефекту «$@spellname390710»." },
    { en = "Inflicts $378787s1 Nature damage every $378787T1 sec. for $378787D. This effect stacks.", ua = "Завдає $378787s1 шкоди від сил природи кожні $378787T1 с протягом $378787D. Цей ефект накопичується." },
    { en = "The legionnaire stabs at a foe, inflicting $s1 Physical damage.", ua = "Легіонер штрикає ворога, завдаючи $s1 фізичної шкоди." },
    { en = "The mage hurls frozen ice at a target, inflicting $375716s2 Frost damage and up to an additional $375717s1 Frost damage every $375716T1 sec. for $375716D.", ua = "Маг жбурляє в ціль крижаний снаряд, завдаючи $375716s2 шкоди від морозу і ще до $375717s1 шкоди від морозу кожні $375716T1 с протягом $375716D." },
    { en = "The Proto-Dragon thrashes about for $375457D, inflicting $375458s1 Frost damage every $375457T1 sec. to players within $375458A1 yards, reducing their movement speed by $375458s2% for $375458D.", ua = "Протодракон шалено борсається протягом $375457D, завдаючи $375458s1 шкоди від морозу кожні $375457T1 с гравцям у межах $375458A1 м і зменшуючи їхню швидкість пересування на $375458s2% протягом $375458D." },
    { en = "The primal energies that flow through the Clutchwarren empower those within, increasing movement speed by $390573s1%.", ua = "Первісні енергії, що течуть крізь Гніздовисько виводку, наснажують усіх усередині, збільшуючи швидкість пересування на $390573s1%." },
    { en = "The Juvenile fiercely bites at their target, inflicting $375475s1 Physical damage and bleeds their target for $375475s2 Physical damage every half-second for $375475D. This effect stacks.", ua = "Молодий протодракон люто кусає свою ціль, завдаючи $375475s1 фізичної шкоди, і ціль кровоточить, зазнаючи $375475s2 фізичної шкоди щопівсекунди протягом $375475D. Цей ефект накопичується." },
    { en = "Increases Greatstaff of the Broodkeeper's damage done by $390710s1%.$?diff15|diff16\n\n[ This effect stacks.][]\n\n\n\nPlayers may cast $@spellname375863 while near the embedded weapon, consuming one application of Greatstaff's Wrath and causing a beam to pursue the player.\n\n\n\nThe focused beam inflicts $375883s1 Nature damage to players within $375883A1 yards every half-second during pursuit, shattering any egg in its path$?diff16[][ terminating the beam].$?diff15|diff16[ Shattering an egg incurs Clutchwatcher's Rage.][]", ua = "Збільшує шкоду, завдану Великим посохом Доглядачки виводку, на $390710s1%.$?diff15|diff16\n\n[ Цей ефект накопичується.][]\n\n\n\nГравці можуть творити $@spellname375863 поблизу встромленої зброї, витрачаючи одне застосування Гніву великого посоха і змушуючи промінь переслідувати гравця.\n\n\n\nЗосереджений промінь завдає $375883s1 шкоди від сил природи гравцям у межах $375883A1 м щопівсекунди під час переслідування, розбиваючи будь-яке яйце на своєму шляху$?diff16[][, що уриває промінь].$?diff15|diff16[ Розбиття яйця спричиняє Лють Доглядачки виводку.][]" },
    { en = "Increases Empowered Greatstaff of the Broodkeeper's damage done by $390711s1%.$?diff14|diff15|diff16\n\n[ This effect stacks, beginning at $390711s3 charges.][]\n\n\n\nDiurna empowers the embedded weapon, invoking its wrath, consuming one application of Empowered Greatstaff's Wrath for each targeted player, causing a beam to pursue them.\n\n\n\nThe focused beam inflicts $379419s1 Nature damage to players within $379419A1 yards every half-second during pursuit, shattering any egg in its path$?diff16[][ terminating the beam].$?diff15|diff16[ Shattering an egg incurs Clutchwatcher's Rage.][]", ua = "Збільшує шкоду, завдану Наснаженим великим посохом Доглядачки виводку, на $390711s1%.$?diff14|diff15|diff16\n\n[ Цей ефект накопичується, починаючи з $390711s3 зарядів.][]\n\n\n\nДіурна наснажує встромлену зброю, прикликаючи її гнів, витрачаючи одне застосування Гніву наснаженого великого посоха за кожного гравця в цілі й змушуючи промінь переслідувати їх.\n\n\n\nЗосереджений промінь завдає $379419s1 шкоди від сил природи гравцям у межах $379419A1 м щопівсекунди під час переслідування, розбиваючи будь-яке яйце на своєму шляху$?diff16[][, що уриває промінь].$?diff15|diff16[ Розбиття яйця спричиняє Лють Доглядачки виводку.][]" },
    { en = "Diurna expels a surge of ice$?diff14|diff15|diff16[ inflicting $388920s1 Frost damage][], immobilizing them within an attackable rime causing their next $388920s3 healing to be absorbed.$?diff16[\n\n\n\nWhile the effect remains players suffer an additional $388920s4 Frost damage every second.][]", ua = "Діурна викидає сплеск криги$?diff14|diff15|diff16[, завдаючи $388920s1 шкоди від морозу][], знерухомлюючи гравців у вразливому паморозі, через що їхнє наступне зцілення на $388920s3 поглинається.$?diff16[\n\n\n\nДоки ефект триває, гравці зазнають додатково $388920s4 шкоди від морозу щосекунди.][]" },
    { en = "The Flamebender erupts striking allies and players within $375485A1 yards. This effect inflicts $375485s1% of each target's health as Fire damage, then heals the target for $375487s2% of the damage done over $375487D.", ua = "Полум'яний приборкувач вибухає, вражаючи союзників і гравців у межах $375485A1 м. Цей ефект завдає шкоди вогнем у розмірі $375485s1% здоров'я кожної цілі, а потім зцілює ціль на $375487s2% завданої шкоди протягом $375487D." },
    { en = "Diurna grievously wounds her target, inflicting $378783s1 Physical damage and $378784s1 Nature damage, applying $@spellname378787 and $@spellname378782.", ua = "Діурна тяжко ранить свою ціль, завдаючи $378783s1 фізичної шкоди і $378784s1 шкоди від сил природи та накладаючи «$@spellname378787» і «$@spellname378782»." },
    { en = "Diurna unleashes flame, igniting players within $375871A1 yards, inflicting $375873s1 Fire damage and an additional $375873s2 Fire damage every $375873T2 sec. for $375873D$?diff15|diff16[ to players within $375875A1 yards of the impact location][]. This effect stacks.$?diff14|diff15|diff16[\n\n\n\nMoments later the flames reignite, applying Wildfire to players who remain within $375875A1 yards of the impact location.][]$?diff16[\n\n\n\nPlayers struck by Wildfire jettison additional Wildfire to nearby locations.][]", ua = "Діурна вивільняє полум'я, запалюючи гравців у межах $375871A1 м, завдаючи $375873s1 шкоди вогнем і додатково $375873s2 шкоди вогнем кожні $375873T2 с протягом $375873D$?diff15|diff16[ гравцям у межах $375875A1 м від місця влучання][]. Цей ефект накопичується.$?diff14|diff15|diff16[\n\n\n\nЗа мить полум'я спалахує знову, накладаючи «Пожежу» на гравців, які лишаються в межах $375875A1 м від місця влучання.][]$?diff16[\n\n\n\nГравці, вражені «Пожежею», розкидають додаткову «Пожежу» на найближчі ділянки.][]" },
    { en = "The Earthreaver sends out rumbling tremors that explode upon contact, inflicting $376260s1 Nature damage to players within $376260A1 yards. Afflicted players suffer $376260s2 Nature damage every half-second and are stunned for $376260D. This effect stacks.", ua = "Землероздирач випускає гримотливі поштовхи, що вибухають при дотику, завдаючи $376260s1 шкоди від сил природи гравцям у межах $376260A1 м. Уражені гравці зазнають $376260s2 шкоди від сил природи щопівсекунди й приголомшені протягом $376260D. Цей ефект накопичується." },
    { en = "Diurna's Fury knows no bounds, increasing damage done by $s1%, and empowering abilities with additional power. $?diff16[][Additionally, this doubles the duration of Mortal Wounds. ]This effect stacks and increases in intensity every $375879T2 sec.", ua = "Лють Діурни не знає меж, збільшуючи завдану шкоду на $s1% і наділяючи здібності додатковою силою. $?diff16[][Крім того, це подвоює тривалість «Смертельних ран». ]Цей ефект накопичується і посилюється кожні $375879T2 с." },
    { en = "The Earthreaver charges their current player target, inflicting $376272s1 Physical damage, reducing their armor by $376272s2% for $376272D. This effect stacks.", ua = "Землероздирач кидається на свою поточну ціль-гравця, завдаючи $376272s1 фізичної шкоди і зменшуючи її броню на $376272s2% протягом $376272D. Цей ефект накопичується." },
    { en = "The Stormbringer electrifies afflicted players with lightning energy, jolting players within $375631A1 yards for $375634s1 Nature damage every half-second for $375620D.", ua = "Буревісник електризує уражених гравців енергією блискавки, б'ючи струмом гравців у межах $375631A1 м і завдаючи $375634s1 шкоди від сил природи щопівсекунди протягом $375620D." },
    { en = "The Stormbringer zaps a targeted player, inflicting $s1 Nature damage, stunning them for $375653D.\n\n\n\nThis additionally empowers the drakonid, increasing movement speed by $375715s1% for $375715D. This effect stacks.", ua = "Буревісник вражає вибраного гравця струмом, завдаючи $s1 шкоди від сил природи і приголомшуючи його на $375653D.\n\n\n\nКрім того, це наснажує драконіда, збільшуючи швидкість пересування на $375715s1% протягом $375715D. Цей ефект накопичується." },
    { en = "Inflicts $396264s1 Nature damage every $396264T1 sec. for $396264D.\n\n\n\nUpon expiration, afflicted players explode from $@spellname396265.", ua = "Завдає $396264s1 шкоди від сил природи кожні $396264T1 с протягом $396264D.\n\n\n\nПісля закінчення уражені гравці вибухають від «$@spellname396265»." },
    { en = "Diurna invokes crackling energy left in the path of $@spellname375889 and $@spellname380483 for $396649D, inflicting $396624s1 Nature damage every half-second to those within $A1 yards of each fissure.", ua = "Діурна прикликає тріскотливу енергію, лишену на шляху «$@spellname375889» і «$@spellname380483», протягом $396649D, завдаючи $396624s1 шкоди від сил природи щопівсекунди тим, хто перебуває в межах $A1 м від кожної тріщини." },
    { en = "Reduces the effectiveness of any healing effects received by $396266s1% for $396266D. This effect stacks, and cannot be mitigated or avoided.", ua = "Зменшує дієвість усіх отриманих ефектів зцілення на $396266s1% протягом $396266D. Цей ефект накопичується, його не можна ні послабити, ні уникнути." },
    { en = "Explodes for $396265s1 Nature damage, split evenly amongst all players within $396265A1 yards.", ua = "Вибухає, завдаючи $396265s1 шкоди від сил природи, що порівну розподіляється між усіма гравцями в межах $396265A1 м." },
    { en = "Diurna expels a surge of frost $?diff14|diff15|diff16[inflicting $388717s1 Frost damage ][]to players within $388716A1 yards, reducing their movement speed by $388717s2% and causing their next $388717s3 healing to be absorbed.$?diff16[\n\n\n\nWhile the effect remains players suffer an additional $388717s4 Frost damage every second.][]", ua = "Діурна викидає сплеск морозу $?diff14|diff15|diff16[, завдаючи $388717s1 шкоди від морозу][]гравцям у межах $388716A1 м, зменшуючи їхню швидкість пересування на $388717s2% і змушуючи їхнє наступне зцілення на $388717s3 поглинатися.$?diff16[\n\n\n\nДоки ефект триває, гравці зазнають додатково $388717s4 шкоди від морозу щосекунди.][]" },
    { en = "Diurna furiously smashes her target, inflicting $396267s1 Physical damage and $396268s1 Nature damage, applying $@spellname396264 and $@spellname396266.", ua = "Діурна шалено трощить свою ціль, завдаючи $396267s1 фізичної шкоди і $396268s1 шкоди від сил природи та накладаючи «$@spellname396264» і «$@spellname396266»." },
    { en = "The Surging Ruiner engulfs several players with crackling energy. After $d the energy explodes, inflicting $396038s1 Nature damage to players within $396038a1 yards.", ua = "Навальний Руйнівник огортає кількох гравців тріскотливою енергією. Після $d енергія вибухає, завдаючи $396038s1 шкоди від сил природи гравцям у межах $396038a1 м." },
    { en = "The Stormseeker Acolyte becomes empowered upon reaching $385541s1% remaining health, granting it $s1% increased Haste.", ua = "Послушниця-Шукачка Бурі набуває наснаги, коли її здоров'я падає до $385541s1%, отримуючи $s1% до Поспіху." },
    { en = "Upon reaching 100 energy, Raszageth summons a massive gust of wind. Inflicts $s1 Nature damage to all players. Additionally, players are pushed away and suffer $s2 Nature damage every $t2 sec for $d.$?diff16 [\n\n\n\nEach time Raszageth uses $@spellname377612 the duration of the hurricane is increased by $378977t1 sec.][]", ua = "Сягнувши 100 енергії, Расзаґет прикликає шалений порив вітру. Завдає $s1 шкоди від сил природи всім гравцям. Крім того, гравців відкидає, і вони зазнають $s2 шкоди від сил природи кожні $t2 с протягом $d.$?diff16 [\n\n\n\nЩоразу, коли Расзаґет застосовує $@spellname377612, тривалість урагану зростає на $378977t1 с.][]" },
    { en = "The Stormseeker Acolyte unleashes storm energy at a player, inflicting $s1 Nature damage.", ua = "Послушниця-шукачка бур вивільняє в гравця енергію бурі, завдаючи $s1 шкоди від сил природи." },
    { en = "Raszageth sweeps across the platform, exhaling lightning in a line as she travels. Inflicts $s1 Nature damage $?diff14|diff17 [instantly and an additional $s2 Nature damage every $t2 sec for $d ][]$?diff15|diff16[][]to players standing in the impact area.", ua = "Расзаґет проноситься платформою, видихаючи блискавки лінією на своєму шляху. Завдає $s1 шкоди від сил природи $?diff14|diff17 [миттєво та ще $s2 шкоди від сил природи кожні $t2 с протягом $d ][]$?diff15|diff16[][]гравцям, що стоять у зоні влучання." },
    { en = "Upon defeat, the Colossal Stormfiend grants any remaining Colossal Stormfiends $s1% increased attack speed and causes them to gain additional applications of $@spellname391281 every $391281t1 sec.", ua = "Після загибелі колосальне чудовисько бурі надає всім уцілілим колосальним чудовиськам бурі $s1% підвищення швидкості атаки та змушує їх отримувати додаткові накладення $@spellname391281 кожні $391281t1 с." },
    { en = "The Volatile Spark is destroyed if $@spellname388631 is removed or $@spellname388635 is interrupted.", ua = "Нестійка іскра знищується, якщо знято $@spellname388631 або перервано $@spellname388635." },
    { en = "The Oathsworn Vanguard gains $s1% increased attack speed and movement speed with each successful melee attack.", ua = "Передовик Присяжних отримує $s1% підвищення швидкості атаки та швидкості пересування з кожною успішною атакою ближнього бою." },
    { en = "The Raging Storm clings to players that enter the area, inflicting $395930s1 Nature damage every $t1 sec.", ua = "Лютий шторм чіпляється до гравців, що входять у зону, завдаючи $395930s1 шкоди від сил природи кожні $t1 с." },
    { en = "The Volatile Spark bursts, inflicting $s1 Nature damage to all players and an additional $s1 Nature damage every $t1 sec for $d. This effect stacks.\n\n\n\nThe Volatile Spark is destroyed if the cast succeeds or is interrupted.", ua = "Нестійка іскра вибухає, завдаючи $s1 шкоди від сил природи всім гравцям та ще $s1 шкоди від сил природи кожні $t1 с протягом $d. Цей ефект накопичується.\n\n\n\nНестійка іскра знищується, якщо прочитання завершується або переривається." },
    { en = "The Flamesworn Herald lets loose a blazing roar, inflicting $s1 Fire damage to all players and increases damage done by all allies by $s2% for $d.", ua = "Вісник Полум'яної присяги вивергає полум'яний рик, завдаючи $s1 шкоди вогнем усім гравцям і підвищуючи шкоду всіх союзників на $s2% протягом $d." },
    { en = "Raszageth and her Primalist forces weaken her siblings' prison with their attacks. As the integrity of the vaults falls to $s2% and $s3% Raszageth begins a new stage of her assault.", ua = "Расзаґет та її сили первісників послаблюють в'язницю її родичів своїми атаками. Коли цілість сховищ падає до $s2% та $s3%, Расзаґет починає новий етап свого нападу." },
    { en = "Raszageth sends a current of electricity through each player, inflicting $388645s1 Nature damage to players within $388645a1 yards of each location and leaving behind a Volatile Spark.", ua = "Расзаґет пропускає крізь кожного гравця струм електрики, завдаючи $388645s1 шкоди від сил природи гравцям у межах $388645a1 ярдів від кожного місця та лишаючи по собі нестійку іскру." },
    { en = "Raszageth's wings crash down, inflicting $s1 Nature damage to all players and releasing a storm wave. Players in the wave $?diff14|diff15|diff17 [suffer $388659s1 Nature damage every $388659t1 sec and][]$?diff16 [inflict $388876s1 Nature damage every $388659t1 sec to players within $388876a1 yards and][] are pushed away.", ua = "Крила Расзаґет обрушуються вниз, завдаючи $s1 шкоди від сил природи всім гравцям і вивільняючи хвилю бурі. Гравців у хвилі $?diff14|diff15|diff17 [уражає $388659s1 шкоди від сил природи кожні $388659t1 с і ][]$?diff16 [змушує завдавати $388876s1 шкоди від сил природи кожні $388659t1 с гравцям у межах $388876a1 ярдів і ][]відкидає геть." },
    { en = "The Colossal Stormfiend emits orbs of lightning, inflicting $s1 Nature damage to players caught in their path and stunning them for $d.", ua = "Колосальний Поріддя Бурі випускає кулі блискавки, що завдають $s1 шкоди від сил природи гравцям на їхньому шляху та приголомшують їх на $d." },
    { en = "Raszageth marks players with a $@spellname381615, inflicting $381958s1 Nature damage every $t2 sec for $d. Upon expiration, it inflicts $381613s1 Nature damage to all players. This damage is reduced the further away players are from the blast.\n\n$?diff14|diff15|diff17 [\n\nCreates a $@spellname377662 at the victim's location.][]", ua = "Расзаґет позначає гравців ефектом $@spellname381615, завдаючи $381958s1 шкоди від сил природи кожні $t2 с протягом $d. По завершенні він завдає $381613s1 шкоди від сил природи всім гравцям. Ця шкода зменшується, що далі гравці від вибуху.\n\n$?diff14|diff15|diff17 [\n\nСтворює $@spellname377662 на місці жертви.][]" },
    { en = "Raszageth afflicts players with a Positive or Negative Charge. Players within $s1 yards of allies with the same charge gain $@spellname391992, while players within $s1 yards of allies with the opposite charge gain $@spellname391993.", ua = "Расзаґет накладає на гравців Позитивний або Негативний заряд. Гравці в межах $s1 ярдів від союзників з тим самим зарядом отримують $@spellname391992, а гравці в межах $s1 ярдів від союзників із протилежним зарядом отримують $@spellname391993." },
    { en = "Raszageth snaps at her current target with electrified jaws, inflicting $393898s1 Physical damage and $388815s1 Nature damage. The target is wounded, inflicting $395907s1 Nature damage every $395906t1 sec and increasing Physical damage taken by $395906s2% for $395906d.", ua = "Расзаґет кусає свою поточну ціль наелектризованими щелепами, завдаючи $393898s1 фізичної шкоди та $388815s1 шкоди від сил природи. Ціль зазнає поранення, яке завдає $395907s1 шкоди від сил природи кожні $395906t1 с і підвищує отримувану фізичну шкоду на $395906s2% протягом $395906d." },
    { en = "Upon reaching 100 energy, Raszageth shields herself with a crackling barrier of electricity that absorbs $388691s1 damage. Raszageth pulses while the shield holds, inflicting $387333s1 Nature damage to all players every $387261t1 sec, growing in intensity by $388762s1% with each pulse.\n\n\n\nAfter $d the shield explodes, inflicting $399054s1 Nature damage to all players every $399054t1 sec for $399054d.\n\n$?diff14|diff15|diff16 [\n\nPlayers are $@spellname391989 while the shield holds.][]", ua = "Сягнувши 100 енергії, Расзаґет огортається тріскотливим бар'єром з електрики, що поглинає $388691s1 шкоди. Поки щит тримається, Расзаґет пульсує, завдаючи $387333s1 шкоди від сил природи всім гравцям кожні $387261t1 с, і ця шкода зростає в силі на $388762s1% з кожним пульсом.\n\n\n\nЧерез $d щит вибухає, завдаючи $399054s1 шкоди від сил природи всім гравцям кожні $399054t1 с протягом $399054d.\n\n$?diff14|diff15|diff16 [\n\nПоки щит тримається, гравці отримують $@spellname391989.][]" },
    { en = "Raszageth periodically calls down lightning strikes that inflict $s1 Nature damage to players within $376087a1 yards of the impact locations and stuns them for $d.", ua = "Расзаґет періодично прикликає удари блискавок, що завдають $s1 шкоди від сил природи гравцям у межах $376087a1 м від місць влучання та приголомшують їх на $d." },
    { en = "Electricity clings to the area. Inflicts $s1 Nature damage every $t1 sec$?diff15|diff16 [ increasing while players stand in the area. Additionally][], reduces movement speed by $377662s2%, and reduces forced movement effects on players standing in the area.", ua = "Електрика чіпляється до зони. Завдає $s1 шкоди від сил природи кожні $t1 с$?diff15|diff16 [, наростаючи, поки гравці стоять у зоні. Крім того,][], знижує швидкість пересування на $377662s2% та послаблює ефекти примусового пересування на гравцях, що стоять у зоні." },
    { en = "Raszageth is protected by a shroud of storm energy, reducing damage taken by $s1%.", ua = "Расзаґет захищена пеленою енергії бурі, що знижує отримувану шкоду на $s1%." },
    { en = "Raszageth's scales periodically pulse with crackling energy, inflicting $381250s1 Nature damage to all players every $t sec and striking several players with $@spellname381251.", ua = "Луска Расзаґет періодично пульсує тріскотливою енергією, завдаючи $381250s1 шкоди від сил природи всім гравцям кожні $t с та вражаючи кількох гравців ефектом $@spellname381251." },
    { en = "The Surging Ruiner shields itself and channels into the vault. While the shield holds, $@spellname382530 inflicts $382541s1 Nature damage to all players every $t3 sec.\n\n\n\nUpon removal, the Surging Ruiner gains $@spellname385360 and summons a Primalist Force.", ua = "Навальний руйнівник огортається щитом і спрямовує силу в сховище. Поки щит тримається, $@spellname382530 завдає $382541s1 шкоди від сил природи всім гравцям кожні $t3 с.\n\n\n\nПісля зняття навальний руйнівник отримує $@spellname385360 і прикликає силу первісників." },
    { en = "A tendril of lightning lashes out from Raszageth's scales, inflicting $s1 Nature damage every $t1 sec.", ua = "Пагін блискавки шмагає з луски Расзаґет, завдаючи $s1 шкоди від сил природи кожні $t1 с." },
    { en = "The Frostforged Zealot blasts players with a wave of frost, inflicting $s2 Frost damage and absorbing $s1 healing received. After $d the shroud shatters, inflicting $397384s1 Frost damage to all players.", ua = "Морозокований фанатик б'є гравців хвилею морозу, завдаючи $s2 шкоди від морозу та поглинаючи $s1 отримуваного зцілення. Через $d пелена розколюється, завдаючи $397384s1 шкоди від морозу всім гравцям." },
    { en = "The Flamesworn Herald shields itself for $s3% of its maximum health, granting it immunity to interrupt effects while the shield holds.", ua = "Вісник Полум'яної присяги огортається щитом на $s3% свого максимального здоров'я, що дає йому несприйнятливість до ефектів переривання, поки щит тримається." },
    { en = "Raszageth is protected by a shroud of storm energy, reducing damage taken by $s1% and weakening the integrity of the vault by $s3% every $t3 sec.", ua = "Расзаґет захищена пеленою енергії бурі, що знижує отримувану шкоду на $s1% та послаблює цілість сховища на $s3% кожні $t3 с." },
    { en = "Upon reaching 100 energy, the Seeking Stormling becomes immune to crowd control effects.", ua = "Сягнувши 100 енергії, шукач-буревісник стає несприйнятливим до ефектів знерухомлення." },
    { en = "Contact with the same charge increases damage done by $s2% and increases healing and absorbs done by $s4%.", ua = "Контакт з тим самим зарядом підвищує завдану шкоду на $s2% та підвищує зцілення й поглинання на $s4%." },
    { en = "Contact with the opposite charge $?diff15|diff16 [triggers a detonation, inflicting $395781s1 Nature damage to players within $395781a1 yards and an additional][] $?diff14|diff17 [inflicts ][]$392196s1 Nature damage every $t2 sec.", ua = "Контакт із протилежним зарядом $?diff15|diff16 [спричиняє детонацію, завдаючи $395781s1 шкоди від сил природи гравцям у межах $395781a1 ярдів та додатково][] $?diff14|diff17 [завдає ][]$392196s1 шкоди від сил природи кожні $t2 с." },
    { en = "Raszageth inverts the charge of several players, granting $d of $@spellname394582 but then inverting their polarity to the opposite charge.", ua = "Расзаґет інвертує заряд кількох гравців, надаючи $d дії $@spellname394582, але потім перемикає їхню полярність на протилежний заряд." },
    { en = "The Surging Ruiner overloads, inflicting $396035s1 Nature damage to all players every $t2 sec.\n\n\n\nAdditionally, the Surging Ruiner grants all allies $389214s1% increased damage done until defeated.", ua = "Здіймний Руйнівник перевантажується, завдаючи $396035s1 шкоди від сил природи всім гравцям кожні $t2 с.\n\n\n\nКрім того, Здіймний Руйнівник надає всім союзникам $389214s1% до завданої шкоди, доки його не буде переможено." },
    { en = "Raszageth marks players with a $@spellname399713 for $d. Upon expiration, it inflicts $399711s1 Nature damage to all players and pulls them to the location of the blast. This damage is reduced the further away players are from the blast.", ua = "Расзаґет позначає гравців ефектом $@spellname399713 на $d. По завершенні він завдає $399711s1 шкоди від сил природи всім гравцям і притягує їх до місця вибуху. Ця шкода зменшується, що далі гравці від вибуху." },
    { en = "Raszageth summons a raging storm that engulfs the platform over time. Players standing in the area are afflicted with $@spellname395929.", ua = "Расзаґет прикликає лютий шторм, що поступово огортає платформу. Гравців, що стоять у зоні, уражає $@spellname395929." },
    { en = "Raszageth focuses a thunderous beam on her current target for $d, inflicting $389313s1 Nature damage to players within it every $t2 sec and applying $@spellname390763 to them.", ua = "Расзаґет зосереджує громовий промінь на своїй поточній цілі протягом $d, завдаючи $389313s1 шкоди від сил природи гравцям у його межах кожні $t2 с та накладаючи на них $@spellname390763." },
    { en = "The energy clinging to the target explodes after $d, applying $@spellname391285 to the target and inflicting up to $390817s1 Nature damage to all players. This damage is reduced by reducing the damage taken from $@spellname386410.", ua = "Енергія, що чіпляється до цілі, вибухає через $d, накладаючи на ціль $@spellname391285 і завдаючи до $390817s1 шкоди від сил природи всім гравцям. Ця шкода зменшується, якщо зменшити шкоду, отриману від $@spellname386410." },
    { en = "Raszageth draws motes of Storm-Energy from the Raging Storm to feed. Each mote that reaches Raszageth restores $395818s1% of her maximum health and increases her damage done by $395818s2%. \n\n\n\nPlayers caught in the path of Storm-Energy are afflicted by Storm's Spite.", ua = "Расзаґет витягує частинки енергії бурі з лютого шторму, щоб живитися. Кожна частинка, що сягає Расзаґет, відновлює $395818s1% її максимального здоров'я та підвищує завдану нею шкоду на $395818s2%. \n\n\n\nГравці, що потрапили на шлях енергії бурі, зазнають дії Злоби бурі." },
    { en = "The Colossal Stormfiend teleports, inflicting $s3 Nature to all players and granting it an application of $@spellname391281.\n\n\n\nCreates Seeking Stormlings at the departure location.", ua = "Колосальне чудовисько бурі телепортується, завдаючи $s3 шкоди від сил природи всім гравцям і отримуючи накладення $@spellname391281.\n\n\n\nСтворює шукачів-буревісників на місці зникнення." },
    { en = "The Colossal Stormfiend crackles with energy, inflicting $391282s1 Nature damage to all players every $391281t1 sec.", ua = "Колосальне чудовисько бурі тріскотить енергією, завдаючи $391282s1 шкоди від сил природи всім гравцям кожні $391281t1 с." },
    { en = "The explosion of $@spellname390763 increases Physical damage taken by $s1% and damage taken by $@spellname389313 by $s2% for $d.", ua = "Вибух $@spellname390763 підвищує отримувану фізичну шкоду на $s1% та шкоду, отриману від $@spellname389313, на $s2% протягом $d." },
    { en = "Upon reaching the the Colossal Stormfiend that created it, the Seeking Stormling sacrifices itself to heal the Colossal Stormfiend for $s1% of its maximum health and increases its damage done by $s2%. This effect stacks.", ua = "Сягнувши колосального чудовиська бурі, що його створило, шукач-буревісник жертвує собою, аби зцілити колосальне чудовисько бурі на $s1% його максимального здоров'я та підвищити завдану ним шкоду на $s2%. Цей ефект накопичується." },
    { en = "Raszageth exhales a beam of lightning in front of her, inflicting $377597s1 Nature damage every $t1 sec to players standing in the area.", ua = "Расзаґет видихає перед собою промінь блискавки, завдаючи $377597s1 шкоди від сил природи щосекунди гравцям, що стоять у зоні дії." },
    { en = "Raszageth charges targets with electricity, $?diff14|diff17|diff15 [reducing their movement speed by $s4% for $d.][] $?diff16 [rooting them for $d. ][]Upon expiration, the charge fulminates, inflicting $377881s1 Nature damage to players in the impact area and jumps to the nearest player caught in the blast.\n\n\n\nEach time $@spellname377467 jumps to a new player, its radius is reduced and the previous player is afflicted with $@spellname390911.", ua = "Расзаґет заряджає цілі електрикою, $?diff14|diff17|diff15 [сповільнюючи їх на $s4% на $d.][] $?diff16 [знерухомлюючи їх на $d. ][]Після завершення заряд вибухає, завдаючи $377881s1 шкоди від сил природи гравцям у зоні удару, і перестрибує на найближчого гравця, що потрапив під вибух.\n\n\n\nЩоразу, коли $@spellname377467 перестрибує на нового гравця, радіус зменшується, а попередній гравець опиняється під дією ефекту $@spellname390911." },
    { en = "A lingering charge remains, inflicting $s1 Nature damage every $t1 sec for $d.", ua = "Залишковий заряд продовжує діяти, завдаючи $s1 шкоди від сил природи щосекунди протягом $d." },
    { en = "The searing heat of the $@spellname407046 inflicts $s1 Shadowflame damage every $t1 sec to players standing within the effect.", ua = "Пекучий жар $@spellname407046 завдає $s1 шкоди тіньовим полум'ям кожні $t1 с гравцям, що стоять у зоні дії." },
    { en = "Kazzara summons fragments of blazing energy to blast out from $@spellname407196. Each fragment ignites a blistering beam and hunts a nearby player, leaving a $@spellname402421 in its wake. Touching the beam inflicts $402207s1 Shadowflame damage every $402207t1 sec.", ua = "Каззара прикликає уламки палаючої енергії, що виривається з $@spellname407196. Кожен уламок запалює пекучий промінь і переслідує найближчого гравця, лишаючи за собою $@spellname402421. Дотик до променя завдає $402207s1 од. шкоди тіньовим полум'ям кожні $402207t1 с." },
    { en = "Powerful elementium plates maintain the integrity of Kazzara's volatile core. At $s3%, $s4%, and $s5% health, sections of armor are shattered off into $@spellname404595. The calamitous blast inflicts $s1 Shadowflame damage to all players.", ua = "Могутні елементієві плити підтримують цілісність нестійкого ядра Каззари. На $s3%, $s4% і $s5% здоров'я частини броні розколюються в $@spellname404595. Згубний вибух завдає $s1 шкоди тіньовим полум'ям усім гравцям." },
    { en = "Kazzara lacerates her target, inflicting $406597s1 Physical damage and $406601s1 Shadowflame damage. The charred gashes inflict $401898s1 Shadowflame damage every $404743t1 sec and increase damage taken from further $@spellname404744 by $404743s2% for $404743d.", ua = "Каззара роздирає свою ціль, завдаючи $406597s1 фізичної шкоди та $406601s1 шкоди тіньовим полум'ям. Обвуглені рани завдають $401898s1 шкоди тіньовим полум'ям щосекунди ($404743t1 сек.) і підвищують отриману шкоду від наступних застосувань $@spellname404744 на $404743s2% протягом $404743d." },
    { en = "Upon reaching 100 energy, Kazzara unleashes an annihilating beam from her jaws, inflicting $400432s1 Shadowflame damage every $t2 sec for $d to any players caught inside. The superheated breath inflicts an additional $404813s1 Shadowflame damage every $t2 sec to all players.\n\n\n\nKazzara disgorges increasing amounts of $@spellname404789 as her armor is shattered off.", ua = "Сягнувши 100 енергії, Каззара вивергає з пащі нищівний промінь, завдаючи $400432s1 шкоди тіньовим полум'ям кожні $t2 с протягом $d усім гравцям, що в нього потрапили. Розжарений подих завдає додаткових $404813s1 шкоди тіньовим полум'ям кожні $t2 с усім гравцям.\n\n\n\nУ міру того, як з Каззари збивається броня, вона вивергає дедалі більше $@spellname404789." },
    { en = "Kazzara's exposed core pulses with her molten heartbeat inflicting $408370s1 Shadowflame damage to all players every $t1 sec, hastening as she loses more armor.", ua = "Оголене ядро Каззари пульсує в ритмі її розплавленого серцебиття, завдаючи $408370s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 с і пришвидшуючись у міру втрати броні." },
    { en = "Scorched ground that inflicts $402420s1 Shadowflame damage every $402420t1 sec to players standing within.", ua = "Випалена земля, що завдає $402420s1 шкоди тіньовим полум'ям кожні $402420t1 с гравцям, які стоять усередині." },
    { en = "If a Ray of Anguish is still active by the next cast, it will gain $@spellname410511. The beam speeds up and begins to emanate with seething rage inflicting $410515s1 Shadowflame damage to all players every $t2 sec, growing in intensity by $410517s1% with each pulse.", ua = "Якщо Промінь Муки досі активний під час наступного творення, він отримує $@spellname410511. Промінь пришвидшується і починає випромінювати клекітливу лють, завдаючи $410515s1 шкоди тіньовим полум'ям усім гравцям кожні $t2 с і зростаючи в інтенсивності на $410517s1% з кожним імпульсом." },
    { en = "If a $@spellname402219 crosses onto an existing $@spellname402421, the amalgamation of energy erupts in a hellish combustion inflicting $s1 Shadowflame damage to all players.", ua = "Якщо $@spellname402219 перетинає наявну $@spellname402421, злиття енергії вибухає пекельним займанням, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям." },
    { en = "Kazzara's gruesome wounds spew out masses of her lifeblood, each inflicting $s1 Shadowflame damage within $A1 yards of impact.", ua = "Жахливі рани Каззари вивергають згустки її життєвої крові, кожен з яких завдає $s1 шкоди тіньовим полум'ям у радіусі $A1 м від місця падіння." },
    { en = "Scorched ground that inflicts $402420s1 Shadowflame damage every $402420t1 sec to players standing within the effect.", ua = "Випалена земля, що завдає $402420s1 шкоди тіньовим полум'ям кожні $402420t1 с гравцям, які стоять у зоні дії." },
    { en = "Kazzara releases a furious roar that incites a burning mark within several players. After $406525d, unworldly rifts tear open beneath these players in a torrent of dreadfire inflicting $406526s1 Shadowflame damage within $406526A1 yards.\n\n\n\nKazzara's exposed core causes $@spellname407196 to target an additional player for each piece of armor that has been shattered.", ua = "Каззара вивергає лютий рев, що позначає кількох гравців палаючою міткою. За $406525d під цими гравцями розверзаються потойбічні розломи в потоці страхополум'я, завдаючи $406526s1 шкоди тіньовим полум'ям у радіусі $406526A1 м.\n\n\n\nЧерез оголене ядро Каззари $@spellname407196 цілить на одного додаткового гравця за кожну збиту частину броні." },
    { en = "Kazzara's armor shatters into blazing metal scraps, each inflicting $s1 Shadowflame damage within $A1 yards of impact.", ua = "Броня Каззари розколюється на палаючі металеві уламки, кожен з яких завдає $s1 шкоди тіньовим полум'ям у радіусі $A1 м від місця падіння." },
    { en = "Kazzara thrashes her fiery wings, inflicting $s1 Shadowflame damage to all players and pushing them away. The flames linger, inflicting an additional $403655s1 Shadowflame damage every $403655t1 sec for $403655d.", ua = "Каззара б'є вогняними крилами, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям і відкидаючи їх геть. Полум'я лишається, завдаючи додаткових $403655s1 шкоди тіньовим полум'ям кожні $403655t1 с протягом $403655d." },
    { en = "The Shadowflame Amalgamation calls down black fireballs at nearby locations that inflict $s1 Shadowflame damage to players within $a1 yards of the impact locations. If any fireball fails to hit a player, it inflicts $408216s1 Shadowflame damage to all players.\n\nOrbs of darkness then converge on the impact location, inflicting $408224s1 Shadowflame damage to players in their path.", ua = "Злиток Тіньового Полум'я прикликає чорні вогняні кулі на місця поблизу, що завдають $s1 шкоди тіньовим полум'ям гравцям у межах $a1 м від місць влучання. Якщо якась вогняна куля не влучає в гравця, вона завдає $408216s1 шкоди тіньовим полум'ям усім гравцям.\n\nПотім кулі темряви сходяться до місця влучання, завдаючи $408224s1 шкоди тіньовим полум'ям гравцям на їхньому шляху." },
    { en = "The Essence of Shadow detonates a mass of coalescent dark energy, inflicting $s1 Shadow damage to players within $a1 yards of the detonation point. Players farther from the detonation receive less damage.", ua = "Есенція Тіні підриває згусток згущеної темної енергії, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м від місця підриву. Гравці, дальші від підриву, зазнають менше шкоди." },
    { en = "The Eternal Blaze slashes its current target with fiery claws, inflicting $s1 Fire damage.", ua = "Вічне Полум'я шматує свою поточну ціль вогняними пазурами, завдаючи $s1 шкоди вогнем." },
    { en = "The Shadowflame Amalgamation wreathes several players in shadowflame. Each target erupts after $405642d1, inflicting $s1 Shadowflame damage to players within $a1 yards and creating $@spellname405645.\n\n\n\nEach target also erupts with $@spellname405704.", ua = "Злиток Тіньового Полум'я огортає кількох гравців тіньовим полум'ям. Кожна ціль вибухає через $405642d1, завдаючи $s1 шкоди тіньовим полум'ям гравцям у межах $a1 м та створюючи $@spellname405645.\n\n\n\nКрім того, кожна ціль вивергає $@spellname405704." },
    { en = "Cinders of The Eternal Blaze's essence fly off around her inflicting $s1 Fire Damage to players within $a2 yards of the impact.", ua = "Попіл есенції Вічного Полум'я розлітається довкола неї, завдаючи $s1 шкоди вогнем гравцям у радіусі $a2 м від місця падіння." },
    { en = "Splinters of The Essence of Shadow fly off around him inflicting $s1 Shadow Damage to players within $a2 yards of the impact.", ua = "Скалки Есенції Тіні розлітаються довкола нього, завдаючи $s1 шкоди від тіні гравцям у радіусі $a2 м від місця падіння." },
    { en = "The engulfing flames left behind by $@spellname405643 inflict $s1 Shadowflame damage every $t1 to players within the area.", ua = "Всепоглинне полум'я, лишене після $@spellname405643, завдає $s1 шкоди тіньовим полум'ям кожні $t1 гравцям у межах зони." },
    { en = "The Essence of Shadow pulses every $401854t1 sec, applying $@spellname401809 to players within $406441a1 yards. This dark energy inflicts $s1 Shadow damage every $t1 sec and reduces maximum health by $s2%$?diff14|diff15|diff17[ for $d][]. This effect stacks.", ua = "Есенція Тіні пульсує кожні $401854t1 с, накладаючи $@spellname401809 на гравців у радіусі $406441a1 м. Ця темна енергія завдає $s1 шкоди від тіні кожні $t1 с і зменшує максимальне здоров'я на $s2%$?diff14|diff15|diff17[ на $d][]. Цей ефект накопичується." },
    { en = "The Shadowflame Amalgamation pulses every $406780t1 sec, applying $@spellname405394 to all players. This dark flame inflicts $s1 Shadowflame damage every $t1 sec and reduces maximum health by $s2%. This effect stacks.", ua = "Злиток Тіньового Полум'я пульсує кожні $406780t1 с, накладаючи $@spellname405394 на всіх гравців. Це темне полум'я завдає $s1 шкоди тіньовим полум'ям кожні $t1 с та знижує максимальне здоров'я на $s2%. Цей ефект накопичується." },
    { en = "The Essence of Shadow wreathes several players in darkness. Each player erupts after $d1, inflicting $405082s1 Shadow damage to players within $405082a1 yards and creating $@spellname405084.", ua = "Есенція Тіні огортає кількох гравців темрявою. Кожен гравець вибухає через $d1, завдаючи $405082s1 шкоди від тіні гравцям у межах $405082a1 м та створюючи $@spellname405084." },
    { en = "The Shadowflame Amalgamation slashes its current target with dark claws, inflicting $s1 Physical damage and increasing their Shadowflame damage taken by $413597s1% for $413597d.", ua = "Злиття Тіньового Полум'я шматує свою поточну ціль темними пазурами, завдаючи $s1 фізичної шкоди та підвищуючи отримувану нею шкоду від тіньового полум'я на $413597s1% на $413597d." },
    { en = "The Eternal Blaze calls down fireballs at nearby locations that inflict $s1 Fire damage to players within $a1 yards of the impact locations. If any fireball fails to hit a player, it inflicts $403113s1 Fire damage to all players.", ua = "Вічне Полум'я прикликає вогняні кулі на місця поблизу, що завдають $s1 шкоди вогнем гравцям у межах $a1 м від місць влучання. Якщо якась вогняна куля не влучає в гравця, вона завдає $403113s1 шкоди вогнем усім гравцям." },
    { en = "As the elementals combine, players with $@spellname402617 and $@spellname401809 lose all applications and trigger a $@spellname409328.\n\nApplies $@spellname409320 and $@spellname409299 to players with applications of $@spellname402617 and $@spellname401809.", ua = "Коли елементалі поєднуються, гравці з $@spellname402617 та $@spellname401809 втрачають усі накладення й запускають $@spellname409328.\n\nНакладає $@spellname409320 та $@spellname409299 на гравців з накладеннями $@spellname402617 та $@spellname401809." },
    { en = "The elementals' damage is increased by $s2% while within $407947s1 yards of each other.", ua = "Шкода стихій збільшується на $s2%, доки вони перебувають у межах $407947s1 м одна від одної." },
    { en = "The Eternal Blaze expels swirling flames in the direction of a nearby player that inflicts $404910s1 Fire damage to players caught in their path.", ua = "Вічне Полум'я вивергає вируюче полум'я в напрямку найближчого гравця, завдаючи $404910s1 шкоди вогнем гравцям, що опинилися на його шляху." },
    { en = "The Shadowflame Amalgamation marks several players and then sears them with shadowflame, inflicting $410808s1 Shadowflame damage to players within $410808a1 yards of their location.\n\n\n\nHalf the marked players are afflicted by $@spellname402617 and the others by $@spellname401809. These effects grow in intensity every $401809t1 sec.", ua = "Злиття Тіньового Полум'я позначає кількох гравців, а тоді обпікає їх тіньовим полум'ям, завдаючи $410808s1 шкоди тіньовим полум'ям гравцям у радіусі $410808a1 м від їхнього місця.\n\n\n\nПоловину позначених гравців уражає $@spellname402617, а решту — $@spellname401809. Ці ефекти зростають в інтенсивності кожні $401809t1 с." },
    { en = "The Eternal Blaze pulses every $401862t1 sec, applying $@spellname402617 to players within $406307a1 yards. This searing heat inflicts $s1 Fire damage every $t1 sec$?diff14|diff15|diff17[ for $d][]. This effect stacks.", ua = "Вічне Полум'я пульсує кожні $401862t1 с, накладаючи $@spellname402617 на гравців у радіусі $406307a1 м. Цей пекучий жар завдає $s1 шкоди вогнем кожні $t1 с$?diff14|diff15|diff17[ на $d][]. Цей ефект накопичується." },
    { en = "The Shadowflame Amalgamation calls down a dark meteor nearby, inflicting $s1 Shadowflame damage split evenly among all players within $a1 yards of the impact location. If $@spellname405458 fails to hit at least $s3 players, it detonates and inflicts $406589s1 Shadowflame damage to all players.\n\n\n\nThe impact creates an orb of energy that detonates shortly afterwards, inflicting $405640s1 Shadowflame damage to all players. Players farther from the detonation point receive less damage.", ua = "Злиток Тіньового Полум'я прикликає поблизу темний метеор, завдаючи $s1 шкоди тіньовим полум'ям, що порівну розподіляється між усіма гравцями в межах $a1 м від місця влучання. Якщо $@spellname405458 не влучає щонайменше в $s3 гравців, він підривається й завдає $406589s1 шкоди тіньовим полум'ям усім гравцям.\n\n\n\nВлучання створює кулю енергії, що невдовзі підривається, завдаючи $405640s1 шкоди тіньовим полум'ям усім гравцям. Гравці, дальші від місця підриву, зазнають менше шкоди." },
    { en = "Blistering Twilight causes dark flames to erupt outwards from the target, inflicting $s1 Shadowflame damage and knocking back players caught in their path.", ua = "Пекуче Сутіння змушує темне полум'я вибухнути назовні з цілі, завдаючи $s1 шкоди тіньовим полум'ям і відкидаючи гравців, що опинилися на його шляху." },
    { en = "Shadows lingers on the player, inflicting $s1 Shadow damage every $t1 sec and increasing Shadow damage taken by $s2% for $d. This effect stacks.", ua = "Тіні затримуються на гравцеві, завдаючи $s1 шкоди від тіні кожні $t1 с і підвищуючи отримувану шкоду від тіні на $s2% на $d. Цей ефект накопичується." },
    { en = "Orbs of darkness converge on the Essence of Shadows location, inflicting $s1 Shadow damage to players in their path.", ua = "Кулі темряви сходяться до місцеперебування Есенції Тіні, завдаючи $s1 шкоди від тіні гравцям на їхньому шляху." },
    { en = "The dark residue inflicts $s1 Shadow damage every $t1 sec to players within the area.", ua = "Темний осад завдає $s1 шкоди від тіні кожні $t1 с гравцям у цій зоні." },
    { en = "Flames linger on the player, inflicting $s1 Fire damage every $t1 sec and increasing Fire damage taken by $s2% for $d. This effect stacks.", ua = "Полум'я затримується на гравцеві, завдаючи $s1 шкоди вогнем кожні $t1 с і підвищуючи отримувану шкоду вогнем на $s2% на $d. Цей ефект накопичується." },
    { en = "$@spellname402617 and $@spellname401809 erupt when combined by two players, inflicting $s1 Shadowflame damage to players within $a1 yards.", ua = "$@spellname402617 та $@spellname401809 вибухають, коли їх поєднують двоє гравців, завдаючи $s1 шкоди тіньовим полум'ям гравцям у радіусі $a1 м." },
    { en = "The Essence of Shadow pierces its current target with a dark spike, inflicting $s1 Shadow Damage.", ua = "Есенція Тіні пронизує свою поточну ціль темним шпичаком, завдаючи $s1 шкоди від тіні." },
    { en = "The Eternal Blaze calls down a fiery meteor nearby, inflicting $s1 Fire damage split evenly among all players within $a1 yards of the impact location. If $@spellname403748 fails to hit at least one player, it detonates and inflicts $404833s1 Fire damage to all players.", ua = "Вічне Полум'я прикликає поблизу вогняний метеор, завдаючи $s1 шкоди вогнем, що порівну розподіляється між усіма гравцями в межах $a1 м від місця влучання. Якщо $@spellname403748 не влучає щонайменше в одного гравця, він підривається й завдає $404833s1 шкоди вогнем усім гравцям." },
    { en = "The Shadowflame Amalgamation releases a burst of flames in the direction of its current target, inflicting $s1 Shadowflame damage to players in a frontal cone.", ua = "Злиття Тіньового Полум'я випускає сплеск полум'я в напрямку своєї поточної цілі, завдаючи $s1 шкоди тіньовим полум'ям гравцям у фронтальному конусі." },
    { en = "The experiment's melee attacks inflict $406313s1 Arcane damage every $406313t1 sec. This effect stacks.\n\n\n\nTouching another player afflicted by $@spellname406311 removes all applications and causes an $@spellname407302.", ua = "Ближні атаки піддослідного завдають $406313s1 од. арканної шкоди кожні $406313t1 с. Цей ефект накопичується.\n\n\n\nДотик до іншого гравця, ураженого $@spellname406311, знімає всі накопичення й спричиняє $@spellname407302." },
    { en = "Rionthus creates a vortex of temporal energy that begins to drift toward him. If the anomaly collides with Rionthus, he gains a shield that absorbs damage equal to $s2% of his maximum health.\n\n\n\nIf a player collides with the anomaly, it inflicts $410608s1 Arcane damage$?diff16[, applies $@spellname410635,][] and is knocked away.", ua = "Ріонтус створює вихор темпоральної енергії, що починає дрейфувати до нього. Якщо аномалія зіткнеться з Ріонтусом, він отримає щит, що поглинає шкоду в розмірі $s2% його максимального здоров'я.\n\n\n\nЯкщо з аномалією зіткнеться гравець, вона завдає $410608s1 шкоди від магії таємниць$?diff16[, накладає $@spellname410635][] і відкидає його геть." },
    { en = "The energy from $@spellname406311 explodes, inflicting $s2 Arcane damage to all players and an additional $s1 Arcane damage every $t1 sec for $d. This effect stacks.", ua = "Енергія $@spellname406311 вибухає, завдаючи $s2 шкоди від магії таємниць усім гравцям і додаткових $s1 шкоди від магії таємниць кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Neldris bellows an arcane roar, inflicting up to $409367s1 Arcane damage. Players farther from Neldris take less damage.", ua = "Нелдріс видає арканний рик, завдаючи до $409367s1 арканної шкоди. Гравці, дальші від Нелдріса, отримують менше шкоди." },
    { en = "Increases damage taken from $@spellname410608 by $s1% for $d. This effect stacks.", ua = "Збільшує шкоду від $@spellname410608 на $s1% на $d. Цей ефект накопичується." },
    { en = "Rionthus tears into players with blasts of blue magic, inflicting $s1 Spellfrost damage every $t1 sec over $d.\n\n\n\nThe magic lingers, slowing affected players by $405423s2% and causing them to inflict $405457s1 Spellfrost damage every $405423t1 sec to players within $405457A2 yards for $405423d.", ua = "Ріонтус шматує гравців спалахами синьої магії, завдаючи $s1 шкоди чаромерзлотою щосекунди ($t1 сек.) протягом $d.\n\n\n\nМагія затримується, сповільнюючи уражених гравців на $405423s2% і змушуючи їх завдавати $405457s1 шкоди чаромерзлотою щосекунди ($405423t1 сек.) гравцям у радіусі $405457A2 ярдів протягом $405423d." },
    { en = "Thadrion infuses players with unstable energy, inflicting $407327s1 Arcane damage every $407327t1 sec and growing in intensity over time.\n\n\n\nUpon removal, the energy briefly coalesces and then explodes, inflicting $408462s1 Arcane damage to players within $408462A2 yards$?diff17|diff14[.][ and leaving behind an $@spellname407364.]\n\n\n\nA lingering trace of energy then jumps to a nearby player and applies Unstable Essence.", ua = "Тадріон наповнює гравців нестабільною енергією, завдаючи $407327s1 арканної шкоди кожні $407327t1 с та наростаючи в інтенсивності з часом.\n\n\n\nПісля зняття енергія ненадовго згущується, а потім вибухає, завдаючи $408462s1 арканної шкоди гравцям у межах $408462A2 м$?diff17|diff14[.][ та залишаючи по собі $@spellname407364.]\n\n\n\nЗалишковий слід енергії потім перестрибує на гравця поблизу й накладає Нестабільну Есенцію." },
    { en = "Rionthus takes in a deep breath and flies across the laboratory, spewing molten cinders that inflict $406233s1 Volcanic damage every $406233t1 sec for $406233d to players in his path.", ua = "Ріонтус набирає повні груди повітря й пролітає крізь лабораторію, вивергаючи розплавлені жаринки, що завдають $406233s1 вулканічної шкоди кожні $406233t1 с протягом $406233d гравцям на його шляху." },
    { en = "Thadrion spews forth arcane globules that inflict $405599s1 Arcane damage to players within $405599A2 yards of the impact locations.", ua = "Тадріон вивергає таємничі згустки, що завдають $405599s1 шкоди від магії таємниць гравцям у радіусі $405599A2 м від місць падіння." },
    { en = "Neldris charges between several players, inflicting $s1 Physical damage to anyone in her path, knocking them back, and causing them to bleed for $s2 Physical damage every $t2 sec$?diff16[.][ for $d.] This effect stacks.", ua = "Нелдріс кидається між кількома гравцями, завдаючи $s1 фізичної шкоди всім на своєму шляху, відкидаючи їх та змушуючи стікати кров'ю, зазнаючи $s2 фізичної шкоди кожні $t2 с$?diff16[.][ протягом $d.] Цей ефект накопичується." },
    { en = "Neldris unleashes a shockwave that inflicts $s2 Physical damage to players in a frontal cone.", ua = "Нелдріс вивільняє ударну хвилю, що завдає $s2 од. фізичної шкоди гравцям у конусі попереду." },
    { en = "The $@spellname407364 periodically erupts with energy, inflicting $s1 Arcane damage to all players.", ua = "$@spellname407364 періодично вивергає енергію, завдаючи $s1 од. арканної шкоди всім гравцям." },
    { en = "Thadrion erupts with energy, inflicting $s1 Arcane damage to all players every $405375t1 sec for $405375d. $?diff17|diff14[][\n\n\n\n$@spellname407364s react to the violent energy, inflicting $407507s1 Arcane damage to all players every $407775t1 sec during Violent Eruption.]", ua = "Тадріон вивергається енергією, завдаючи $s1 арканної шкоди всім гравцям кожні $405375t1 с протягом $405375d. $?diff17|diff14[][\n\n\n\n$@spellname407364 реагують на буйну енергію, завдаючи $407507s1 арканної шкоди всім гравцям кожні $407775t1 с під час Буйного Виверження.]" },
    { en = "The impact of Kagni's charge weakens the player increasing their damage taken from $@spellname410535 by $s1%.", ua = "Удар натиску Каґні послаблює гравця, збільшуючи отримувану ним шкоду від $@spellname410535 на $s1%." },
    { en = "Warlord Kagni drains Ignara's life, regaining $s2% of his maximum health and gaining $@spellname406585.", ua = "Воєначальник Каґні висмоктує життя Іґнари, відновлюючи $s2% свого максимального здоров'я та здобуваючи $@spellname406585." },
    { en = "Upon reaching 100 energy, Warlord Kagni sends a devastating shockwave toward the Elder's Door, inflicting $s1 Physical damage split evenly among players in its path$?diff14|diff17[][ and applying $@spellname404616].\n\n\n\nWarlord Kagni expends up to 100 energy, reduced by the number of players hit. If any energy remains, $@spellname410535 triggers a $@spellname404687.", ua = "Сягнувши 100 одиниць енергії, Воєначальник Каґні посилає нищівну ударну хвилю до Дверей Старійшини, завдаючи $s1 фізичної шкоди, рівномірно розподіленої між гравцями на її шляху$?diff14|diff17[][ та накладаючи $@spellname404616].\n\n\n\nВоєначальник Каґні витрачає до 100 одиниць енергії, зменшених на кількість уражених гравців. Якщо енергія лишається, $@spellname410535 запускає $@spellname404687." },
    { en = "The Obsidian Guard unleashes a burning roar that sears players within $408624A1 yards, inflicting $408624s1 Fire damage every $t1 sec for $d.", ua = "Обсидіанова варта вивільняє палаючий рев, що обпікає гравців у межах $408624A1 м, завдаючи $408624s1 шкоди вогнем кожні $t1 с протягом $d." },
    { en = "The caster hurls lava at random players, inflicting $s1 Lava damage on impact and an additonal $s2 Lava damage every $t2 sec for $d.", ua = "Заклинач кидає лаву в довільних гравців, завдаючи $s1 шкоди від лави при влучанні та додатково $s2 шкоди від лави щожно $t2 сек. протягом $d." },
    { en = "Warlord Kagni smolders with Ignara's flame, periodically inflicting $405618s1 Fire damage to all players every $t1 sec.", ua = "У Воєначальникові Каґні тліє полум'я Іґнари, періодично завдаючи $405618s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "Siege Arbalests fire bolts along the ramparts inflicting $406976s1 Physical damage to all players within $406976A1 yards of the impact.", ua = "Облогові арбалести стріляють болтами вздовж валів, завдаючи $406976s1 од. фізичної шкоди всім гравцям у межах $406976A1 ярдів від місця влучання." },
    { en = "Rubble falls from the cavern's ceiling, inflicting $s2 Physical damage to players within $A2 yards of the impact locations.", ua = "Зі стелі печери падає каміння, завдаючи $s2 фізичної шкоди гравцям у межах $A2 м від місць падіння." },
    { en = "The Magma Mystic protects itself within a shield of lava that absorbs $s1 damage. The barrier pulses with flame while the shield holds, inflicting $409242s1 Fire damage to all players every $t2 sec and granting the mystic $@spellname409696.", ua = "Магмовий містик захищає себе щитом із лави, що поглинає $s1 шкоди. Поки щит тримається, бар'єр пульсує полум'ям, завдаючи $409242s1 шкоди вогнем усім гравцям кожні $t2 с та надаючи містику $@spellname409696." },
    { en = "The Magma Mystic fires a searing bolt of lava, inflicting $s1 Volcanic damage to the target.", ua = "Магматична містичка випускає пекучий заряд лави, завдаючи цілі $s1 Вулканічної шкоди." },
    { en = "The Obsidian Guard charges its shield with lava, then fires a beam of magma towards its target, inflicting $s2 Volcanic damage to players in the path of the beam.", ua = "Обсидіанова варта заряджає свій щит лавою, а тоді випускає в ціль промінь магми, завдаючи $s2 вулканічної шкоди гравцям на шляху променя." },
    { en = "The Elder's Door is protected by a runic barrier that backfires when attacked by Zaqali forces, inflicting $s2 Shadowflame damage to all players and an additional $s1 Shadowflame damage every $t1 sec$?diff14|diff17[ for $d][]. This effect stacks.", ua = "Двері Старійшини захищені рунічним бар'єром, що відбиває удар у відповідь на атаки сил Закалі, завдаючи $s2 тіньовим полум'ям усім гравцям та додатково $s1 тіньовим полум'ям кожні $t1 с$?diff14|diff17[ протягом $d][]. Цей ефект накопичується." },
    { en = "Ignara's flame unleashes several $@spellname403786s at player locations. After $s1 sec, a $@spellname410742 rises from its ashes.", ua = "Полум'я Ігнари вивільняє кілька $@spellname403786 на місцях гравців. Через $s1 с із попелу постає $@spellname410742." },
    { en = "At full energy, Warlord Kagni leaps between the battlements. When landing, he slams his hammer into the ground inflicting $s1 Volcanic damage to players within $398676A1 yards and knocking them away.\n\n\n\nMolten fissures radiate from the impact location, inflicting $408117s1 Volcanic damage.", ua = "На повній енергії Воєначальник Каґні стрибає між зубцями стіни. Приземляючись, він б'є молотом об землю, завдаючи $s1 вулканічної шкоди гравцям у межах $398676A1 м та відкидаючи їх.\n\n\n\nВід місця удару розходяться розплавлені тріщини, завдаючи $408117s1 вулканічної шкоди." },
    { en = "Increases the Magma Mystic's fire damage by $s1%. This effect stacks.", ua = "Збільшує шкоду вогнем Магмового містика на $s1%. Цей ефект накопичується." },
    { en = "The Renewed Hatchling fixates on a nearby player and pulses with flame, inflicting $410789s1 Fire damage to players within $410789A1 yards every $410791t1 sec.", ua = "Оновлене драконятко зосереджується на найближчому гравцеві й пульсує полум'ям, завдаючи $410789s1 шкоди вогнем гравцям у межах $410789A1 м кожні $410791t1 с." },
    { en = "Ignara unleashes a gust of wind, inflicting $s1 Nature damage to players on the nearby battlement. The cutting wind pushes players toward the battlement's edge and inflicts $s2 Nature damage every $t2 sec for $d.", ua = "Іґнара здіймає порив вітру, завдаючи $s1 шкоди від сил природи гравцям на найближчому зубчатому мурі. Різкий вітер штовхає гравців до краю муру й завдає $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "Warlord Kagni slams his massive cudgel in the direction of his current target, inflicting $408873s1 Physical damage to players in a frontal cone and increasing their Physical damage taken by $408873s2% for $408873d. This effect stacks.\n\n\n\nThe force of the impact causes $@spellname400450 to fall.", ua = "Воєначальник Каґні гатить своїм велетенським кийком у напрямку поточної цілі, завдаючи $408873s1 фізичної шкоди гравцям у фронтальному конусі та збільшуючи отримувану ними фізичну шкоду на $408873s2% протягом $408873d. Цей ефект накопичується.\n\n\n\nСила удару спричиняє падіння $@spellname400450." },
    { en = "Warlord Kagni slams his massive cudgel in the direction of his current target, inflicting $410353s1 Physical damage to players in a frontal cone and increasing their Physical damage taken by $410353s2% for $410353d. This effect stacks. \n\n\n\nThe force of the impact causes all players to erupt in flame, inflicting $410369s1 Fire damage to targets within $410369A1 yards of their location.", ua = "Воєначальник Каґні гатить своїм велетенським кийком у напрямку поточної цілі, завдаючи $410353s1 фізичної шкоди гравцям у фронтальному конусі та збільшуючи отримувану ними фізичну шкоду на $410353s2% протягом $410353d. Цей ефект накопичується. \n\n\n\nСила удару спричиняє спалах полум'я в усіх гравців, завдаючи $410369s1 шкоди вогнем цілям у межах $410369A1 м від їхнього розташування." },
    { en = "On death, the $@spellname410742 leaves behind another $@spellname403786. After $401108s1 sec, the phoenix revives.", ua = "Помираючи, $@spellname410742 лишає по собі ще одну $@spellname403786. Через $401108s1 с фенікс відроджується." },
    { en = "The huntsman sets his aim on several players, heaving a $@spellname401401 at their location that initially inflicts $401407s1 Physical damage to players within $401407a1 yards of the impact.\n\n\n\nThe $@spellname401401 remains in the ground and after a short duration, explodes inflicting $401119s2 Fire damage to players within $401119a1 yards.", ua = "Мисливець наводиться на кількох гравців, метаючи $@spellname401401 в їхнє розташування, що спершу завдає $401407s1 фізичної шкоди гравцям у межах $401407a1 м від місця падіння.\n\n\n\n$@spellname401401 лишається в землі й за коротку мить вибухає, завдаючи $401119s2 шкоди вогнем гравцям у межах $401119a1 м." },
    { en = "Rashok smashes the ground with the Shadowflame-infused Djaruun, inflicting $s2 Shadowflame damage split evenly among players within $a2 yards of the impact location. $?diff14|diff17[][All players are afflicted with $@spellname405827.]$?diff17[][\n\n\n\nRashok gains up to $s1 energy, reduced by the number of players hit.]", ua = "Рашок гатить об землю наповненим тіньовим полум'ям Джаруном, завдаючи $s2 тіньовим полум'ям, рівномірно розподіленої між гравцями в межах $a2 м від місця удару. $?diff14|diff17[][Усіх гравців уражає $@spellname405827.]$?diff17[][\n\n\n\nРашок отримує до $s1 одиниць енергії, зменшених на кількість уражених гравців.]" },
    { en = "Rashok's energy is being drained by the Elder's Conduit, causing a series of violent reactions in the chamber.", ua = "Енергію Рашока висмоктує Провідник Старійшини, спричиняючи низку бурхливих реакцій у палаті." },
    { en = "Each $@spellname404445 sears players' flesh, increasing damage taken from $@spellname404445 by $s1%. This effect stacks.", ua = "Кожна $@spellname404445 обпікає плоть гравців, збільшуючи отримувану шкоду від $@spellname404445 на $s1%. Цей ефект накопичується." },
    { en = "Scalding vortex of lava that inflicts $406321s1 Fire damage every $406321t1 sec to players within the area. Pours forth $@spellname403556 $?diff17|diff14[during $@spellname403536.][.]", ua = "Пекучий вир лави, що завдає $406321s1 шкоди вогнем кожні $406321t1 с гравцям у його межах. Виливає $@spellname403556 $?diff17|diff14[під час $@spellname403536.][.]" },
    { en = "The $@spellname406160 explodes if hit by $@spellname405821, inflicting $s1 Fire damage to all players every $408855t1 sec for $408855d.", ua = "$@spellname406160 вибухає, якщо його вразити $@spellname405821, завдаючи $s1 од. шкоди вогнем усім гравцям кожні $408855t1 с протягом $408855d." },
    { en = "Rashok roars in pain, inflicting $406165s1 Shadowflame damage to all players as he breaks free from the $@spellname401419.\n\n\n\nRashok's inner flame smolders as he breaks free from his prison, increasing the damage of $@spellname404448 by $s1%.", ua = "Рашок реве від болю, завдаючи $406165s1 тіньовим полум'ям усім гравцям, поки вивільняється з $@spellname401419.\n\n\n\nВнутрішнє полум'я Рашока жевріє, поки він виривається з в'язниці, посилюючи шкоду від $@spellname404448 на $s1%." },
    { en = "Rashok crushes his current target, inflicting $s1 Physical damage and increasing damage taken by  $@spellname407597 by $s2% for $d.", ua = "Рашок трощить свою поточну ціль, завдаючи $s1 фізичної шкоди та збільшуючи отримувану шкоду від $@spellname407597 на $s2% протягом $d." },
    { en = "Rashok unleashes a blast of shadowlava from Djaruun, inflicting $s2 Shadowflame damage to players in a frontal cone.", ua = "Рашок вивільняє з Джаруна спалах тіньової лави, завдаючи $s2 тіньовим полум'ям гравцям у фронтальному конусі." },
    { en = "Rashok leaps toward a target player and slams the ground, creating a $@spellname406160 at that location and inflicting $s1 Fire damage to all players. This damage is increased by $403536s1% for each $@spellname406160 in the chamber.\n\n\n\nThe slam's impact causes each $@spellname406160 to pour forth $@spellname403556.\n\n\n\nA $@spellname408855 erupts if $@spellname405822 hits a $@spellname406160.$?diff14|diff15|diff17[][\n\n\n\n$@spellname410077 hit by $@spellname405822 is destroyed.]", ua = "Рашок стрибає до цільового гравця й б'є об землю, створюючи $@spellname406160 в цьому місці й завдаючи $s1 вогнем усім гравцям. Ця шкода зростає на $403536s1% за кожен $@spellname406160 в залі.\n\n\n\nУдар об землю змушує кожен $@spellname406160 виливати $@spellname403556.\n\n\n\n$@spellname408855 спалахує, якщо $@spellname405822 влучає в $@spellname406160.$?diff14|diff15|diff17[][\n\n\n\n$@spellname410077, у яку влучив $@spellname405822, знищується.]" },
    { en = "After draining Rashok's energy $s1 times, the conduit shatters, inflicting $410883s1 Shadowflame damage to all players within $410883A2 yards and becomes unusable.", ua = "Висмоктавши енергію Рашока $s1 разів, провідник розколюється, завдаючи $410883s1 тіньовим полум'ям усім гравцям у межах $410883A2 м, і стає непридатним." },
    { en = "Rashok launches a barrage of shadowflame missiles across the chamber. Each missile inflicts $s1 Shadowflame damage to players within $a1 yards of its impact location and an additional $408857s1 Shadowflame damage every $408857t1 sec for $408857d. This effect stacks.\n\n\n\nEach missile that fails to hit a player erupts, inflicting $406153s1 Shadowflame damage to all players.", ua = "Рашок випускає залп снарядів тіньового полум'я через зал. Кожен снаряд завдає $s1 тіньовим полум'ям гравцям у межах $a1 ярдів від місця влучання та додатково $408857s1 тіньовим полум'ям щожно $408857t1 сек. протягом $408857d. Цей ефект накопичується.\n\n\n\nКожен снаряд, що не влучає в гравця, вибухає, завдаючи $406153s1 тіньовим полум'ям усім гравцям." },
    { en = "Upon reaching 100 energy, Rashok becomes immune to the Elder's Conduit and overloads with pulsing flame, inflicting $s1 Shadowflame damage to all players every $405316t2 sec.", ua = "Сягнувши 100 енергії, Рашок стає невразливим до Провідника Старійшини й перевантажується пульсівним полум'ям, завдаючи $s1 тіньовим полум'ям усім гравцям щожно $405316t2 сек." },
    { en = "Volatile energy lingers on the player, inflicting $s1 Shadowflame damage every $t1 sec$?diff15[ for $d.][.\n\n\n\nThe Elder's Conduit removes applications of Overcharged from players within the area and triggers a $@spellname405828.]", ua = "На гравцеві затримується нестабільна енергія, завдаючи $s1 тіньовим полум'ям кожні $t1 с$?diff15[ протягом $d.][.\n\n\n\nПровідник Старійшини знімає накладення Перезаряджання з гравців у цій межі й запускає $@spellname405828.]" },
    { en = "The conduit flares with power, inflicting $s1 Shadowflame damage to all players.", ua = "Провідник спалахує силою, завдаючи $s1 тіньовим полум'ям усім гравцям." },
    { en = "Shadowflame energy erupts from Rashok's body as he is drained, inflicting $401510s1 Shadowflame damage to players within $401510a1 yards of the impact location.", ua = "Поки Рашока виснажують, з його тіла виривається енергія тіньового полум'я, завдаючи $401510s1 тіньовим полум'ям гравцям у межах $401510a1 м від місця удару." },
    { en = "Rashok unleashes energy from his body, inflicting $s1 Shadowflame damage to all players and sending orbs of $@spellname410075 across the chamber.", ua = "Рашок вивільняє енергію зі свого тіла, завдаючи $s1 тіньовим полум'ям усім гравцям і розсилаючи кулі $@spellname410075 по всій палаті." },
    { en = "A roiling wave of lava that inflicts $s1 Fire damage every $s2 sec to players within the area.", ua = "Вируюча хвиля лави, що завдає $s1 шкоди вогнем кожні $s2 с гравцям у її межах." },
    { en = "Rashok unleashes a powerful combination of attacks with Djaruun, Pillar of the Elder Flame, at his current target.", ua = "Рашок вивільняє потужну комбінацію атак Джаруном, Стовпом Прадавнього Полум'я, по своїй поточній цілі." },
    { en = "Volatile orb of shadowflame energy that inflicts $s1 Shadowflame damage to players within the area.\n\n\n\nEach orb explodes after $410073d, inflicting $410077s2 Shadowflame damage to all players and increasing the damage taken from $@spellname410075 by $410077s3%. Also causing the next $410077s1 healing they receive to be absorbed.", ua = "Нестабільна куля енергії тіньового полум'я, що завдає $s1 тіньовим полум'ям гравцям у її межах.\n\n\n\nКожна куля вибухає через $410073d, завдаючи $410077s2 тіньовим полум'ям усім гравцям і збільшуючи отримувану шкоду від $@spellname410075 на $410077s3%. Також спричиняє поглинання наступних $410077s1 зцілення, яке вони отримають." },
    { en = "Rashok periodically emits scorching heat as his energy is drained by the $@spellname401419, inflicting $404448s1 Shadowflame damage to all players$?diff17|diff14[.][ and applying $@spellname408204.]", ua = "Рашок періодично випромінює пекуче тепло, поки $@spellname401419 висмоктує його енергію, завдаючи $404448s1 тіньовим полум'ям усім гравцям$?diff17|diff14[.][ та накладаючи $@spellname408204.]" },
    { en = "Rashok slashes at his current target, inflicting $s1 Fire damage and increasing damage taken by $@spellname407547 by $s2% for $d.", ua = "Рашок розтинає свою поточну ціль, завдаючи $s1 од. шкоди вогнем і підвищуючи шкоду, якої вона зазнає від $@spellname407547, на $s2% протягом $d." },
    { en = "Deactivate the targeted active Dragonfire Trap.", ua = "Знешкодьте обрану активну Пастку Драконячого Вогню." },
    { en = "Zskarn covers targets in $@spellname404404, inflicting $s1 Fire damage every $404010t1 sec for $404010d.\n\n\n\nPlayers afflicted by $@spellname404404 inflict $s1 Fire damage to allies within $a1 yards every $404010t1 sec for $404010d.", ua = "Зскарн вкриває цілі $@spellname404404, завдаючи $s1 вогнем щожно $404010t1 сек. протягом $404010d.\n\n\n\nГравці, уражені $@spellname404404, завдають $s1 вогнем союзникам у межах $a1 ярдів щожно $404010t1 сек. протягом $404010d." },
    { en = "Zskarn unleashes a $@spellname403978 that knocks all players back, inflicting $s1 Fire damage on impact and an additional $s2 Fire damage every $t2 sec for $d.", ua = "Зскарн вивільняє $@spellname403978, що відкидає всіх гравців, завдаючи $s1 шкоди вогнем при ударі та додатково $s2 шкоди вогнем щосек. $t2 протягом $d." },
    { en = "Zskarn's claws burn his current target, inflicting $s1 Fire damage every $t1 sec for $d. This effect stacks.", ua = "Кігті Зскарна обпікають його поточну ціль, завдаючи $s1 шкоди вогнем щосек. $t1 протягом $d. Цей ефект накопичується." },
    { en = "Zskarn animates several Dragonfire Golems to assist him by seeking out and activating inactive Dragonfire Traps.", ua = "Зскарн оживляє кількох драконовогняних големів, щоб вони допомагали йому, відшукуючи й активуючи неактивні драконовогняні пастки." },
    { en = "Zskarn activates several nearby $@spellname405462 that inflict $s1 Fire damage every $t1 sec for $d to all players within $a1 yards of the trap. This effect stacks.", ua = "Зскарн активує поблизу кілька $@spellname405462, що завдають $s1 шкоди вогнем щосек. $t1 протягом $d усім гравцям у межах $a1 ярд. від пастки. Цей ефект накопичується." },
    { en = "Upon reaching $409462s1% health or full energy Dragonfire Golems become $@spellname409463, preventing crowd control effects.", ua = "Сягнувши $409462s1% здоров'я або повної енергії, Големи Драконячого Вогню стають $@spellname409463, що унеможливлює ефекти контролю." },
    { en = "Rummage through a defeated Dragonfire Golem's parts, searching for a way to disable Dragonfire Traps.", ua = "Порийтеся в рештках переможеного драконовогняного голема, шукаючи спосіб знешкодити драконовогняні пастки." },
    { en = "Zskarn unleashes a powerful blast at players that were marked with $@spellname404404, inflicting $s1 Fire damage to players in the direction of his targets. \n\n\n\nPlayers hit by Elimination Protocol take $s2% increased damage from $@spellname409942 for $d.", ua = "Зскарн вивільняє потужний вибух у гравців, позначених $@spellname404404, завдаючи $s1 шкоди вогнем гравцям у напрямку його цілей. \n\n\n\nГравці, уражені Протоколом ліквідації, отримують на $s2% більше шкоди від $@spellname409942 протягом $d." },
    { en = "Upon reaching 100 energy, Zskarn unleashes a series of rapid eruptions from nearby dragon statues, inflicting $405439s1 Fire damage to all players caught within the blast.", ua = "Сягнувши 100 енергії, Зскарн вивільняє серію стрімких вивержень із розташованих поблизу драконячих статуй, завдаючи $405439s1 шкоди вогнем усім гравцям, що потрапили у вибух." },
    { en = "After 30 seconds $@spellname404955 detonates inflicting $404959s1 Physical damage and an additional $404959s2 Physical damage every $404959t2 sec for $404959d to all players.\n\n\n\nTriggering a $@spellname404955 early instead causes a localized detonation, inflicting $s1 Physical damage to the player that triggered the detonation and an additional $s2 Physical damage every $t2 sec for $d.", ua = "За 30 секунд $@spellname404955 детонує, завдаючи $404959s1 фізичної шкоди та додатково $404959s2 фізичної шкоди щосек. $404959t2 протягом $404959d усім гравцям.\n\n\n\nЯкщо ж $@spellname404955 здетонувати завчасно, відбувається локальний вибух, що завдає $s1 фізичної шкоди гравцеві, який спричинив детонацію, та додатково $s2 фізичної шкоди щосек. $t2 протягом $d." },
    { en = "Dragonfire Golems attempt to activate inactive Dragonfire Traps. \n\n\n\nIf no inactive Dragonfire Traps are detected, Dragonfire Golems assist Zskarn to eliminate players.", ua = "Драконовогняні големи намагаються активувати неактивні драконовогняні пастки. \n\n\n\nЯкщо неактивних драконовогняних пасток не виявлено, драконовогняні големи допомагають Зскарну знищувати гравців." },
    { en = "Magmorax's heads bite at his current target. Each attack inflicts $s1 Physical damage and an additional $408966s1 Fire damage every $408955t1 sec for $408955d. This effect also increases the damage taken from subsequent $@spellname401348 taken by $408955s2% for $408955d. This effect stacks.", ua = "Голови Магморакса кусають його поточну ціль. Кожен укус завдає $s1 фізичної шкоди та додатково $408966s1 шкоди вогнем щосек. $408955t1 протягом $408955d. Цей ефект також збільшує шкоду від наступних застосувань $@spellname401348 на $408955s2% протягом $408955d. Цей ефект накопичується." },
    { en = "Magmorax spews lava in a frontal cone, inflicting $405626s1 Fire damage to all players caught in his breath.", ua = "Маґморакс вивергає лаву в конусі попереду, завдаючи $405626s1 од. шкоди вогнем усім гравцям, охопленим його подихом." },
    { en = "Upon reaching 100 energy, Magmorax erupts into flame, increasing Physical damage done by $s2%. \n\n\n\nThe explosion inflicts $408359s1 Fire damage to all players every $t1 sec and increases Fire damage taken by $408359s2%. This effect stacks.", ua = "Сягнувши 100 енергії, Магморакс спалахує полум'ям, збільшуючи завдану фізичну шкоду на $s2%. \n\n\n\nВибух завдає $408359s1 шкоди вогнем усім гравцям щосек. $t1 і збільшує отримувану шкоду вогнем на $408359s2%. Цей ефект накопичується." },
    { en = "$@spellname403103s set players within the area ablaze, inflicting $411400s1 Fire damage every $t1 sec$?diff15 [ for $d][]. This effect stacks.\n\n\n\nUpon reaching $s3 applications, the player is $@spellname412078.", ua = "$@spellname403103 підпалюють гравців у межах ділянки, завдаючи $411400s1 шкоди вогнем щосек. $t1$?diff15[ протягом $d][]. Цей ефект накопичується.\n\n\n\nСягнувши $s3 нашарувань, гравець стає $@spellname412078." },
    { en = "While standing within a $@spellname403103, Magmorax gains $407795s1 energy and inflicts $407911s1 Fire damage to all players every $t2 sec.", ua = "Стоячи в $@spellname403103, Магморакс отримує $407795s1 енергії та завдає $407911s1 шкоди вогнем усім гравцям щосек. $t2." },
    { en = "Magmorax expels globs of burning magma onto the ground. Each glob of magma inflicts $413364s2 Fire damage to players within $413360A1 yards of the impact location$?diff14|diff15|diff16[, increasing damage taken from $@spellname413351 by $413367s1% for $413367d][].\n\n\n\nEach glob that fails to hit a player explodes, inflicting $413365s1 Fire damage to all players and leaving a $@spellname403103 behind.", ua = "Магморакс вивергає на землю згустки палаючої магми. Кожен згусток магми завдає $413364s2 шкоди вогнем гравцям у межах $413360A1 ярд. від місця падіння$?diff14|diff15|diff16[, збільшуючи отримувану шкоду від $@spellname413351 на $413367s1% протягом $413367d][].\n\n\n\nКожен згусток, що не влучив у гравця, вибухає, завдаючи $413365s1 шкоди вогнем усім гравцям і лишаючи по собі $@spellname403103." },
    { en = "Magmorax covers random players in fiery spit, inflicting $411417s1 Fire damage every $402994t1 sec for $402994d. \n\n\n\nUpon removal the player explodes, inflicting $404721s1 Fire damage to players within $404721A1 yards and creating a $@spellname403103.", ua = "Магморакс вкриває випадкових гравців вогняним плювком, завдаючи $411417s1 шкоди Вогнем кожні $402994t1 с протягом $402994d. \n\n\n\nПісля зняття гравець вибухає, завдаючи $404721s1 шкоди Вогнем гравцям у радіусі $404721A1 ярдів і створюючи $@spellname403103." },
    { en = "Upon reaching $408839s3 stacks of $@spellname408839, the player is incinerated, suffering $s1 Fire damage.", ua = "Досягнувши $408839s3 накопичень $@spellname408839, гравець спопеляється, отримуючи $s1 вогняної шкоди." },
    { en = "The magma explodes, inflicting $s1 Fire damage split between all players within $A1 yards. \n\n\n\nThe explosion leaves behind a $@spellname403103, reduced in size by the number of players in the impact.", ua = "Магма вибухає, завдаючи $s1 вогняної шкоди, розподіленої між усіма гравцями в межах $A1 ярдів. \n\n\n\nВибух лишає по собі $@spellname403103, розмір якої зменшується залежно від кількості гравців, що потрапили під удар." },
    { en = "$@spellname403103s set players within the area ablaze, inflicting $s1 Fire damage every $t1 sec.", ua = "$@spellname403103s підпалює гравців у зоні, завдаючи $s1 вогняної шкоди кожні $t1 с." },
    { en = "Magmorax stomps the ground, inflicting $s1 Physical damage to all players and knocking them back.", ua = "Магморакс гупає по землі, завдаючи $s1 фізичної шкоди всім гравцям і відкидаючи їх." },
    { en = "Magmorax roars, inflicting $s1 Fire damage on impact and an additional $413546s1 Fire damage every $403747t1 sec to all players. This effect stacks.\n\n\n\nAdditionally, Magmorax expels numerous $@spellname413351s into the chamber.", ua = "Магморакс ричить, завдаючи $s1 шкоди вогнем при ударі та додатково $413546s1 шкоди вогнем щосек. $403747t1 усім гравцям. Цей ефект накопичується.\n\n\n\nКрім того, Магморакс вивергає в палату численні $@spellname413351." },
    { en = "A pool of magma that continues to grow during the course of the fight. Players standing in the pool ignite with $@spellname408839, shrinking the pool over time.\n\n\n\nIn addition, Magmorax entering a pool causes him to erupt into a $@spellname407879.", ua = "Калюжа магми, що дедалі більшає впродовж бою. Гравці, які стоять у калюжі, спалахують від $@spellname408839, з часом зменшуючи калюжу.\n\n\n\nКрім того, коли Магморакс заходить у калюжу, він вибухає ефектом $@spellname407879." },
    { en = "The erupting segment of $@spellname402902 inflicts $s2 Volcanic damage to players in $A1 yards, and knocks them away.", ua = "Сегмент $@spellname402902, що вивергається, завдає $s2 вулканічної шкоди гравцям у межах $A1 ярд. і відкидає їх." },
    { en = "Twisted Aberrations continuously mutate, increasing damage done by $s1% every $408788t1 sec.", ua = "Покручені аберації безперервно мутують, збільшуючи завдану шкоду на $s1% щосек. $408788t1." },
    { en = "Impacting a segment of $@spellname401456 shatters it, inflicting $s2 Physical damage to the impacting player$?DIFF16[ and increasing their damage taken from $@spellname401825 by $411430s1% for $411430d.][.] Fragments burst from the impact, inflicting $407329s2 Physical damage to all players every $407329t2 sec. for $407329d.$?DIFF17[][ This effect stacks.]\n\n\n\nPelts the chamber with $@spellname401883.", ua = "Зіткнення із сегментом $@spellname401456 розколює його, завдаючи $s2 фізичної шкоди гравцеві, що зіткнувся$?DIFF16[, та збільшуючи його отримувану шкоду від $@spellname401825 на $411430s1% протягом $411430d.][.] Від удару розлітаються уламки, завдаючи $407329s2 фізичної шкоди всім гравцям щосек. $407329t2 протягом $407329d.$?DIFF17[][ Цей ефект накопичується.]\n\n\n\nЗасипає палату $@spellname401883." },
    { en = "Neltharion strikes the player's body while they are incorporeal, inflicting $407796s1 Physical damage to the body and hurtling it towards the player. The player rejoins their body and receives its missing health as Shadow damage. Increases damage taken from $@spellname407790 by $408160s1% for $408160d.\n\n\n\nThe player's body colliding with a segment of $@spellname402902 causes it to $@spellname401825.", ua = "Нелтаріон б'є по тілу гравця, поки той безтілесний, завдаючи $407796s1 фізичної шкоди тілу та жбурляючи його в гравця. Гравець возз'єднується зі своїм тілом і отримує його втрачене здоров'я у вигляді шкоди від тіні. Збільшує отримувану шкоду від $@spellname407790 на $408160s1% протягом $408160d.\n\n\n\nКоли тіло гравця стикається із сегментом $@spellname402902, воно спричиняє $@spellname401825." },
    { en = "Neltharion blasts several players for $s1 Shadow damage and knocks them away$?DIFF17[.][, inflicting an additional $407220s1 Shadow damage to any players between Neltharion and his targets and silencing them for $d.]\n\n\n\nColliding with a segment of $@spellname402902 causes it to $@spellname401825.", ua = "Нелтаріон б'є кількох гравців, завдаючи $s1 шкоди від тіні й відкидаючи їх$?DIFF17[.][, завдаючи додатково $407220s1 шкоди від тіні всім гравцям між Нелтаріоном і його цілями та занімовуючи їх на $d.]\n\n\n\nЗіткнення із сегментом $@spellname402902 спричиняє $@spellname401825." },
    { en = "Neltharion shatters the ground beneath him, inflicting $s1 Volcanic damage players within $A1 yards of the impact, and an additional $s2 Volcanic damage to all other players. The effect echoes at each previous location when $@spellname402115 is cast. \n\n\n\nEach cast causes $@spellname402120 and spreads $@spellname409058.", ua = "Нелтаріон розколює землю під собою, завдаючи $s1 вулканічної шкоди гравцям у межах $A1 ярд. від удару та додатково $s2 вулканічної шкоди всім іншим гравцям. Ефект відлунює в кожному попередньому місці при застосуванні $@spellname402115. \n\n\n\nКожне застосування спричиняє $@spellname402120 і розповсюджує $@spellname409058." },
    { en = "The Voice From Beyond ruptures the veil of reality, inflicting $s1 Shadow damage to all players every $410822t1 sec. until slain.", ua = "Голос з Потойбіччя розриває запону реальності, завдаючи $s1 шкоди від тіні всім гравцям щосек. $410822t1, доки його не вб'ють." },
    { en = "Neltharion rips nearby $@spellname402902 into portals to the void realm, inflicting $s2 Shadow damage to players in $a2 yards of the impact. The portal continuously allows Twisted Aberrations into reality.\n\n\n\nPlayers standing in portals gain $@spellname407919.", ua = "Нелтаріон роздирає $@spellname402902 поблизу на портали до царства порожнечі, завдаючи $s2 шкоди від тіні гравцям у межах $a2 ярд. від удару. Портал безперервно впускає покручених аберацій у реальність.\n\n\n\nГравці, що стоять у порталах, отримують $@spellname407919." },
    { en = "Rubble falls from the ceiling, inflicting $s1 Nature damage to players within $A1 yards and stunning them for $d.", ua = "Зі стелі сиплеться каміння, завдаючи $s1 шкоди від сил природи гравцям у межах $A1 ярд. і приголомшуючи їх на $d." },
    { en = "Neltharion infuses players with volcanic energy that explodes after $410966d, inflicting $s1 Volcanic damage to players within $A1 yards, and an additional $s2 Volcanic damage every $t2 sec for $d.\n\n\n\nThis effect stacks.", ua = "Нелтаріон наповнює гравців вулканічною енергією, що вибухає за $410966d, завдаючи $s1 вулканічної шкоди гравцям у межах $A1 ярд. і додатково $s2 вулканічної шкоди щосек. $t2 протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Neltharion raises walls of earth from the chamber's floor, causing $@spellname402831 where they emerge.", ua = "Нелтаріон здіймає стіни землі з підлоги палати, спричиняючи $@spellname402831 там, де вони виринають." },
    { en = "Rock fragments inflict $s1 Nature damage to players standing at the impact location.", ua = "Уламки каменю завдають $s1 шкоди від сил природи гравцям, що стоять у місці падіння." },
    { en = "Neltharion's corruption seeps into players' soul, turning them hostile to allies but allowing them to attack creatures $@spellname407036 for $d.\n\n\n\nBreaking the shield of a Voice From Beyond $@spellname407036 clears $@spellname410972 from all players.", ua = "Скверна Нелтаріона просочується в душу гравців, роблячи їх ворожими до союзників, але дозволяючи нападати на істот $@spellname407036 протягом $d.\n\n\n\nЯкщо зламати щит Голосу з Потойбіччя $@spellname407036, $@spellname410972 знімається з усіх гравців." },
    { en = "Neltharion causes any remaining $@spellname402902 to erupt with a $@spellname402831 and $@spellname402120 to fall.", ua = "Нелтаріон змушує всі залишкові $@spellname402902 вивергнутися $@spellname402831, а $@spellname402120 — впасти." },
    { en = "Lava seeps out from each $@spellname402115, inflicting $s1 Volcanic damage every $t1 sec. to players within the area.", ua = "Лава просочується з кожного $@spellname402115, завдаючи $s1 вулканічної шкоди щосек. $t1 гравцям у межах ділянки." },
    { en = "Neltharion draws in dark power to annihilate players, inflicting $404038s1 Shadow damage to all players. Each cast increases damage done by $@spellname404068 by $404045s1%. This effect stacks.", ua = "Нелтаріон вбирає темну силу, щоб знищити гравців, завдаючи $404038s1 шкоди від тіні всім гравцям. Кожне застосування збільшує шкоду від $@spellname404068 на $404045s1%. Цей ефект накопичується." },
    { en = "Neltharion shields himself in darkness, reducing damage taken by $s1%.", ua = "Нелтаріон огортає себе темрявою, зменшуючи отриману шкоду на $s1%." },
    { en = "Neltharion strikes his current target with his massive blade, inflicting $s1 Physical damage and knocking them away. Increases Physical damage taken by $401998s1% for $401998d.\n\n\n\nColliding with a segment of $@spellname402902 causes it to $@spellname401825.", ua = "Нелтаріон б'є поточну ціль своїм велетенським клинком, завдаючи $s1 фізичної шкоди та відкидаючи її. Збільшує отриману фізичну шкоду на $401998s1% на $401998d.\n\n\n\nЗіткнення із сегментом $@spellname402902 змушує його $@spellname401825." },
    { en = "Neltharion draws upon his might and blasts all players for $s1 Volcanic damage, and an additional $s2 Fire damage every $t2 sec $?DIFF16[.][ for $d.]\n\n\n\nThis power dispels any $@spellname407919 near players.", ua = "Нелтаріон черпає свою міць і вражає всіх гравців, завдаючи $s1 вулканічної шкоди та додатково $s2 вогнем кожні $t2 с$?DIFF16[.][ протягом $d.]\n\n\n\nЦя сила розвіює будь-яку $@spellname407919 поблизу гравців." },
    { en = "Neltharion sunders his current target's shadow from their body, inflicting $s3 Physical damage. Neltharion immediately attacks the target's body with $@spellname407856.\n\n\n\nWhile in control of their shadow, the target is incorporeal and can move through $@spellname402902.", ua = "Нелтаріон відриває тінь поточної цілі від її тіла, завдаючи $s3 фізичної шкоди. Нелтаріон негайно атакує тіло цілі за допомогою $@spellname407856.\n\n\n\nДоки гравець керує своєю тінню, він безтілесний і може проходити крізь $@spellname402902." },
    { en = "Portals distort reality for nearby players, inflicting $s1 Shadow damage every $t1 sec. to players within the area, reducing damage taken from $@spellname407917 by $s3%.", ua = "Портали спотворюють реальність для гравців поблизу, завдаючи $s1 від тіні кожні $t1 с гравцям у зоні та зменшуючи шкоду, отриману від $@spellname407917, на $s3%." },
    { en = "Neltharion surrenders to darkness, inflicting $407048s1 Shadow damage to all players every $409453t1 sec. and a final burst of $s1 Shadow damage as the channel ends.$?Diff17[][\n\n\n\nNeltharion afflicts several players with $@spellname410972.]", ua = "Нелтаріон віддається темряві, завдаючи $407048s1 від тіні всім гравцям кожні $409453t1 с і фінальний сплеск $s1 від тіні наприкінці прочитання.$?Diff17[][\n\n\n\nНелтаріон уражає кількох гравців ефектом $@spellname410972.]" },
    { en = "The Voice From Beyond shrouds itself in shadow, absorbing $s1 damage$?DIFF15|DIFF16[ and concealing itself from players unaffected by $@spellname410972 while the shield holds][]. When the shield breaks, the Voice From Beyond begins casting $@spellname408131.", ua = "Голос з Потойбіччя огортає себе тінню, поглинаючи $s1 шкоди$?DIFF15|DIFF16[ і ховаючись від гравців, не уражених $@spellname410972, доки тримається щит][]. Коли щит руйнується, Голос з Потойбіччя починає творити $@spellname408131." },
    { en = "Rubble periodically falls from the damaged ceiling, inflicting $s1 Volcanic damage to players within $A1 yards.", ua = "Уламки періодично падають з пошкодженої стелі, завдаючи $s1 вулканічної шкоди гравцям у межах $A1 м." },
    { en = "The Voice from Beyond empowers Neltharion with dark power, allowing him to cast $@spellname403049 upon reaching $409970s2% remaining health.", ua = "Голос з Потойбіччя наділяє Нелтаріона темною силою, дозволяючи йому застосувати $@spellname403049, коли його здоров'я опуститься до $409970s2%." },
    { en = "Sarkareth breathes flames in a frontal cone, inflicting $402051s1 Fire damage instantly with an additional $402051s2 Fire damage every $402051t2 sec for $402051d. This attack repeats $s2 times and stacks.\n\n\n\nIf Searing Breath strikes a target with $@spellname401383, it removes that effect and applies $@spellname402052.", ua = "Саркарет видихає полум'я фронтальним конусом, миттєво завдаючи $402051s1 вогнем і додатково $402051s2 вогнем кожні $402051t2 с протягом $402051d. Ця атака повторюється $s2 разів і накопичується.\n\n\n\nЯкщо Пекучий Подих вражає ціль із $@spellname401383, він знімає цей ефект і накладає $@spellname402052." },
    { en = "Sarkareth takes in a deep breath and flies to a location, inflicting $s1 Shadow damage in a line and knocking players back.", ua = "Саркарет робить глибокий вдих і летить до певного місця, завдаючи $s1 від тіні по лінії та відкидаючи гравців." },
    { en = "Searing wounds burn the player, inflicting $402053s1 Fire damage every $t1 sec.", ua = "Пекучі рани обпікають гравця, завдаючи $402053s1 вогнем кожні $t1 с." },
    { en = "When $@spellname401383 is removed from a player, echoing darkness erupts forth and inflicts $s1 Shadow damage to all players with an additional $s2 Shadow damage every $t2 sec for $d. This effect stacks.", ua = "Коли $@spellname401383 знімається з гравця, вивергається лунка темрява, завдаючи $s1 від тіні всім гравцям і додатково $s2 від тіні кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "A void nova erupts from the target, inflicting $s2% of the total Shadow damage taken from $@spellname408422 to all players as Shadow damage.", ua = "З цілі вивергається нова Порожнечі, завдаючи всім гравцям $s2% від загальної шкоди тінню, отриманої від $@spellname408422, як шкоду від тіні." },
    { en = "Whenever a player enters the $@spellname401215, Sarkareth destabilizes reality and inflicts $s1 Physical damage to all players every $t1 sec, reducing their movement speed by $s2% for $d. This effect stacks.", ua = "Щоразу, коли гравець заходить у $@spellname401215, Саркарет дестабілізує реальність, завдаючи $s1 фізичної шкоди всім гравцям кожні $t1 с і зменшуючи їхню швидкість пересування на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Sarkareth releases pure magic, inflicting $401819s1 Arcane damage to all players every $t1 sec for $d. \n\n\n\nIf $@spellname401810 strikes a player with $@spellname401383, it removes that effect and applies $@spellname401905.", ua = "Саркарет вивільняє чисту магію, завдаючи $401819s1 арканної шкоди всім гравцям кожні $t1 с протягом $d. \n\n\n\nЯкщо $@spellname401810 вражає гравця із $@spellname401383, вона знімає цей ефект і накладає $@spellname401905." },
    { en = "The image releases a mighty scream, inflicting $s1 Arcane damage to all players and interrupting spellcasting.", ua = "Образ видає нищівний крик, завдаючи $s1 арканної шкоди всім гравцям і перериваючи творення заклять." },
    { en = "Sarkareth grows bulbs of void energy at player locations which pulse waves to all players and creatures within them every $404384t3 sec, absorbing up to $404425s1 healing for $404425d.", ua = "Саркарет вирощує бруньки енергії Порожнечі в місцях розташування гравців, які пульсують хвилями на всіх гравців і створінь усередині них кожні $404384t3 с, поглинаючи до $404425s1 зцілення протягом $404425d." },
    { en = "While stranded within the $@spellname401215, players can absorb $@spellname407576s to gain $s2% increased Haste and $s1% increased movement speed for $d. This effect stacks.", ua = "Доки гравці загублені в $@spellname401215, вони можуть поглинати $@spellname407576s, щоб отримати $s2% до поспіху та $s1% до швидкості пересування на $d. Цей ефект накопичується." },
    { en = "Oblivion motes rain from above, inflicting $s1 Shadow damage in addition to $s2 applications of $@spellname401951 to players within $A1 yards of the impact.", ua = "Частинки забуття сиплються згори, завдаючи $s1 від тіні, а також $s2 накладень $@spellname401951 гравцям у межах $A1 м від місця падіння." },
    { en = "Sarkareth tears open portals to infinity, conjuring void images of himself that rush out in a line through a player. These images inflict $411997s1 Shadow damage to targets struck.", ua = "Саркарет розриває портали в нескінченність, прикликаючи свої образи Порожнечі, що проносяться лінією крізь гравця. Ці образи завдають $411997s1 від тіні враженим цілям." },
    { en = "Being struck with most Void abilities causes Oblivion, inflicting $401952s1 Shadow damage every $s2 sec for $d. Upon reaching $s1 applications, the affected player is lost in the $@spellname401215.", ua = "Влучання більшості здібностей Порожнечі спричиняє Забуття, завдаючи $401952s1 від тіні кожні $s2 с протягом $d. Після досягнення $s1 накладень уражений гравець губиться в $@spellname401215." },
    { en = "The image lashes out with an unerring strike at its target that always hits and ignores armor, inflicting $s1 Physical damage and increasing damage taken by $s2% for $d. This effect stacks.", ua = "Образ завдає цілі невідворотного удару, який завжди влучає та ігнорує броню, завдаючи $s1 фізичної шкоди й збільшуючи отриману шкоду на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The image releases bolts of Void, inflicting $s1 Shadow damage to all players.", ua = "Образ вивільняє розряди Порожнечі, завдаючи $s1 від тіні всім гравцям." },
    { en = "Sarkareth pulls several asteroids out of space to crash into the ground. These formations inflict $s1 Shadow damage to nearby players every $t1 sec.", ua = "Саркарет витягує з космосу кілька астероїдів, що врізаються в землю. Ці утворення завдають $s1 від тіні гравцям поблизу кожні $t1 с." },
    { en = "Sarkareth causes a massive supernova to grow and erupt, inflicting $s1 Shadow damage and knocking back all players not behind an $@spellname403497.", ua = "Саркарет змушує велетенську наднову зрости й вибухнути, завдаючи $s1 від тіні та відкидаючи всіх гравців, які не сховалися за $@spellname403497." },
    { en = "Sarkareth slashes his current target, inflicting $401327s1 Physical damage with an additional $401339s1 Fire damage every $401330t1 sec for $401330d. This effect stacks.\n\n\n\nUpon expiration, releases a $@spellname401340.", ua = "Саркарет шматує поточну ціль, завдаючи $401327s1 фізичної шкоди й додатково $401339s1 вогнем кожні $401330t1 с протягом $401330d. Цей ефект накопичується.\n\n\n\nПісля завершення вивільняє $@spellname401340." },
    { en = "Upon casting any spell, Sarkareth empowers his allies with the might of the Black dragons. This effect increases their damage done and movement speed by $s1%. Upon reaching $s3 applications, the target becomes immune to crowd controlling and interrupting effects.", ua = "Творячи будь-яке закляття, Саркарет наділяє своїх союзників могутністю чорних драконів. Цей ефект збільшує завдану ними шкоду та швидкість пересування на $s1%. Після досягнення $s3 накладень ціль стає несприйнятливою до ефектів контролю та переривання." },
    { en = "After ascending to the stars, Sarkareth empowers himself with Cosmic energy, increasing his damage done by $s1%. This effect stacks.", ua = "Піднявшись до зірок, Саркарет наділяє себе космічною енергією, збільшуючи завдану ним шкоду на $s1%. Цей ефект накопичується." },
    { en = "Sarkareth grows bulbs of void energy at player locations which pulse waves to all players and creatures within them every $404384t3 sec, absorbing up to $404425s1 healing for $404425d and removing $@spellname404705.", ua = "Саркарет вирощує бруньки енергії Порожнечі в місцях розташування гравців, які пульсують хвилями на всіх гравців і створінь усередині них кожні $404384t3 с, поглинаючи до $404425s1 зцілення протягом $404425d і знімаючи $@spellname404705." },
    { en = "The target's mind and body are heavily fractured, reducing movement speed by $s2% and inflicting $401801s1 Arcane damage every $t1 sec.", ua = "Розум і тіло цілі сильно розколоті, що зменшує швидкість пересування на $s2% і завдає $401801s1 арканної шкоди кожні $t1 с." },
    { en = "Motes of flame fall from above, inflicting $s1 Fire damage and knocking back players within $A1 yards of the impact.", ua = "Частинки полум'я падають згори, завдаючи $s1 вогнем і відкидаючи гравців у межах $A1 м від місця падіння." },
    { en = "Sarkareth places Void Bombs on nearby players. Each inflicts $404062s1 Shadow damage to players within $404060A1 yards every $404059t1 sec. After $404059d, the bombs explode with a $@spellname404152.", ua = "Саркарет встановлює Бомби Порожнечі на гравцях поблизу. Кожна завдає $404062s1 від тіні гравцям у межах $404060A1 м кожні $404059t1 с. За $404059d бомби вибухають, спричиняючи $@spellname404152." },
    { en = "The player erupts with a burning nova, inflicting $s2% of the total Fire damage taken from $@spellname401325 to all players as Fire damage.", ua = "Гравець вибухає палаючою новою, завдаючи всім гравцям $s2% від загальної шкоди вогнем, отриманої від $@spellname401325, як шкоду вогнем." },
    { en = "The bomb erupts with void energy, inflicting $s1 Shadow damage to all players every $t1 sec for $d.", ua = "Бомба вибухає енергією Порожнечі, завдаючи $s1 від тіні всім гравцям кожні $t1 с протягом $d." },
    { en = "Sarkareth flies up through a void portal before crashing through the floor and inflicting $403771s1 Shadow damage to players within $403771A1 yards and knocking back players struck.", ua = "Саркарет злітає крізь портал Порожнечі, а тоді проламується крізь підлогу, завдаючи $403771s1 від тіні гравцям у межах $403771A1 ярдів і відкидаючи вражених гравців." },
    { en = "The target is stranded alone in the vast infinite of space, reducing damage done by $s2%. After $d, if the target has not recovered fragments of their mind, they are lost forever and perish.", ua = "Ціль опиняється сама в неосяжній нескінченності космосу, що зменшує завдану шкоду на $s2%. Якщо за $d ціль не відновить фрагменти свого розуму, вона втрачається назавжди й гине." },
    { en = "Sarkareth causes the infinite emptiness of space to weigh heavy on the target's mind, inflicting $s1 Shadow damage every $t1 sec for $d.\n\n\n\nUpon removal, this triggers Dread.", ua = "Саркарет змушує нескінченну порожнечу космосу важко тиснути на розум цілі, завдаючи $s1 від тіні кожні $t1 с протягом $d.\n\n\n\nПісля зняття спричиняє Жах." },
    { en = "Cosmic energy destabilizes $@spellname403497s, causing them to explode and inflict $s1 Shadow damage to players within $A1 yards and knock back players within $A2 yards.", ua = "Космічна енергія дестабілізує $@spellname403497s, через що вони вибухають і завдають $s1 шкоди від тіні гравцям у межах $A1 м, а гравців у межах $A2 м відкидає." },
    { en = "Sarkareth focuses the crushing weight of space upon a player. After $403520d, a black hole is formed inflicting $405340s1 Shadow damage, split evenly among players struck. \n\n\n\nThe black hole also pulls in and absorbs nearby $@spellname403497s before finally erupting and inflicting $403524s1 Shadow damage to all players within $403524A1 yards.", ua = "Саркарет зосереджує нищівну вагу простору на гравцеві. За $403520d утворюється чорна діра, що завдає $405340s1 шкоди від тіні, рівномірно розподіленої між ураженими гравцями. \n\n\n\nЧорна діра також притягує і поглинає сусідні $@spellname403497s, перш ніж нарешті вибухнути й завдати $403524s1 шкоди від тіні всім гравцям у межах $403524A1 м." },
    { en = "An exploding bomb pierces a hole through the reality of all universes for $d. Players entering this hole fall through the fabric of space and time.", ua = "Бомба вибухає, пробиваючи на $d отвір крізь реальність усіх всесвітів. Гравці, що входять у цей отвір, провалюються крізь тканину простору й часу." },
    { en = "An eruption of dread inflicts $s1 Shadow damage to all players and knocks them away.", ua = "Спалах жаху завдає $s1 шкоди від тіні всім гравцям і відкидає їх." },
    { en = "When a $@spellname401500 erupts, it creates a patch of $@spellname406989. This ground inflicts $s1 Fire damage every $t1 sec to players within.", ua = "Коли $@spellname401500 вибухає, він створює пляму $@spellname406989. Ця поверхня завдає $s1 шкоди вогнем кожні $t1 с гравцям, що стоять на ній." },
    { en = "Players entering the $@spellname401215 pierce a hole through the reality of all universes for $d. Players entering this hole fall through the fabric of space and time.", ua = "Гравці, що входять у $@spellname401215, пробивають на $d отвір крізь реальність усіх всесвітів. Гравці, що входять у цей отвір, провалюються крізь тканину простору й часу." },
    { en = "Sarkareth places several Scorching Bombs on nearby players. Each inflicts $401621s1 Fire damage to players within $401528A1 yards every $401598t1 sec. After $401598d, the bombs explode with a $@spellname401525.", ua = "Саркарет розміщує кілька Пекучих Бомб на сусідніх гравцях. Кожна завдає $401621s1 шкоди вогнем гравцям у межах $401528A1 м кожні $401598t1 с. За $401598d бомби вибухають із $@spellname401525." },
    { en = "Chronal magic rewinds damage taken, restoring $s1% of the image's maximum health every $t1 sec.", ua = "Хрональна магія відмотує отриману шкоду, відновлюючи $s1% максимального здоров'я образу кожні $t1 с." },
    { en = "Sarkareth slashes his current target, inflicting $411242s1 Physical damage with an additional $411240s1 Shadow damage every $411241t1 sec and reducing healing received by $411241s3% for $411241d. This effect stacks.\n\n\n\nUpon expiration, releases a $@spellname411238.", ua = "Саркарет шматує свою поточну ціль, завдаючи $411242s1 фізичної шкоди й додатково $411240s1 шкоди від тіні кожні $411241t1 с та зменшуючи отримуване зцілення на $411241s3% на $411241d. Цей ефект накопичується.\n\n\n\nПісля закінчення вивільняє $@spellname411238." },
    { en = "The player erupts with a void nova, inflicting $s2% of the total Shadow damage taken from $@spellname411236 to players within $A1 yards as Shadow damage.", ua = "Гравець вибухає новою порожнечі, завдаючи гравцям у межах $A1 м $s2% усієї шкоди від тіні, отриманої від $@spellname411236, як шкоду від тіні." },
    { en = "Sarkareth releases a bone-shaking howl at all players, pushing them away and increasing the incoming effects of Mass Disintegrate, Searing Breath, and Glittering Surge. When struck by any of these, $@spellname401383 is removed.", ua = "Саркарет видає кістедробильний рев на всіх гравців, відкидаючи їх і посилюючи майбутні ефекти Масової Дезінтеграції, Пекучого Подиху та Мерехтливої Хвилі. Коли гравця вражає будь-який із цих ефектів, $@spellname401383 знімається." },
    { en = "Sarkareth takes in a deep breath and flies to a location, inflicting $410243s1 Shadow damage in a line and knocking players away. This leaves behind void residue which inflicts $404499s2 Shadow damage every $404499t2 sec to players within.", ua = "Саркарет робить глибокий вдих і відлітає до місця, завдаючи $410243s1 шкоди від тіні по лінії та відкидаючи гравців. Це лишає по собі залишки порожнечі, що завдають $404499s2 шкоди від тіні кожні $404499t2 с гравцям усередині." },
    { en = "Sarkareth slashes his current target and a frontal cone, inflicting $408425s1 Physical damage with an additional $408431s1 Shadow damage every $408429t1 sec and reducing healing received by $408429s3% for $408429d. This effect stacks.\n\n\n\nUpon expiration, releases a $@spellname408434.", ua = "Саркарет шматує свою поточну ціль і фронтальний конус, завдаючи $408425s1 фізичної шкоди й додатково $408431s1 шкоди від тіні кожні $408429t1 с та зменшуючи отримуване зцілення на $408429s3% на $408429d. Цей ефект накопичується.\n\n\n\nПісля закінчення вивільняє $@spellname408434." },
    { en = "Sarkareth forms a shimmering image that marks players. After $401680d, energy erupts from the image in a line towards its targets inflicting $402600s1 Arcane damage.\n\n\n\nIf $@spellname401642 strikes a target with $@spellname401383, it removes that effect and applies $@spellname401718.", ua = "Саркарет формує мерехтливий образ, що позначає гравців. За $401680d з образу вивергається енергія по лінії до його цілей, завдаючи $402600s1 арканної шкоди.\n\n\n\nЯкщо $@spellname401642 вражає ціль з ефектом $@spellname401383, він знімає цей ефект і накладає $@spellname401718." },
    { en = "The player's senses are dazzled, stunning them and inflicting $403202s1 Arcane damage every $t2 sec for $d.", ua = "Чуття гравця засліплюються, оглушуючи його й завдаючи $403202s1 арканної шкоди кожні $t2 с протягом $d." },
    { en = "A fiery blast consumes the bomb, inflicting $s1 Fire damage to all players instantly with an additional $s2 Fire damage every $t2 sec for $d.", ua = "Вогняний вибух поглинає бомбу, миттєво завдаючи $s1 шкоди вогнем усім гравцям і додатково $s2 шкоди вогнем кожні $t2 с протягом $d." },
    { en = "When $@spellname401383 is removed from a player, echoing darkness erupts forth and inflicts $s1 Shadow damage to all players.", ua = "Коли $@spellname401383 знімається з гравця, вивергається відлуння темряви й завдає $s1 шкоди від тіні всім гравцям." },
    { en = "A player stepping into the $@spellname404027 causes the void energy to dissipate into the player. Upon removal, the void energy erupts with a $@spellname404154 unless that player is within the $@spellname401215.", ua = "Коли гравець ступає в $@spellname404027, енергія порожнечі розсіюється в нього. Після зняття енергія порожнечі вибухає з $@spellname404154, якщо тільки цей гравець не перебуває в межах $@spellname401215." },
    { en = "The flaming soil inflicts $s1 Shadowflame damage every $t1 sec to players standing on it.", ua = "Палаючий ґрунт завдає $s1 шкоди тіньовим полум'ям кожні $t1 сек гравцям, що стоять на ньому." },
    { en = "Gnarlroot causes patches of earth to explode with Shadowflame, inflicting $s1 damage to players within the blast.\n\n\n\nSome of these patches absorb the Shadowflame energy, forming dormant $?diff16[Tainted Treants and][] Tainted Lashers.", ua = "Ґнарлрут спричиняє вибухи ділянок землі тіньовим полум'ям, завдаючи $s1 шкоди гравцям у зоні вибуху.\n\n\n\nДеякі з цих ділянок поглинають енергію тіньового полум'я, утворюючи дрімотних $?diff16[Опоганених Древнів і ][]Опоганених Шмагал." },
    { en = "Gnarlroot bellows in agony, inflicting $s1 Shadowflame damage to all players and an additional $s2 Shadowflame damage every $t2 sec for $d.", ua = "Ґнарлрут реве від муки, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям і додатково $s2 шкоди тіньовим полум'ям кожні $t2 сек протягом $d." },
    { en = "Gnarlroot grows $@spellname425648 that siphon power from earth, decreasing his damage taken by $s1% and causing him pulse $421421s1 Shadowflame damage every $421421t1 sec.\n\n\n\n$?diff15|diff16[$@spellname421350 flies from Gnarlroot's body every $422366t1 sec.][]$?diff14|diff17[$@spellname426617 flies from Gnarlroot's body every $426623t1 sec.][]\n\n\n\nThis ability corrupts the soil beneath Gnarlroot, awakening dormant creatures and creating $@spellname422373.\n\n\n\nDestroying all Doom Roots afflicts Gnarlroot with $@spellname421840.", ua = "Ґнарлрут вирощує $@spellname425648, що висмоктують силу із землі, зменшуючи отримувану ним шкоду на $s1% і змушуючи його випромінювати $421421s1 шкоди тіньовим полум'ям кожні $421421t1 сек.\n\n\n\n$?diff15|diff16[$@spellname421350 вилітає з тіла Ґнарлрута кожні $422366t1 сек.][]$?diff14|diff17[$@spellname426617 вилітають з тіла Ґнарлрута кожні $426623t1 сек.][]\n\n\n\nЦя здібність опоганює ґрунт під Ґнарлрутом, пробуджуючи приспаних істот і створюючи $@spellname422373.\n\n\n\nЗнищення всіх Коренів Загибелі накладає на Ґнарлрута $@spellname421840." },
    { en = "Gnarlroot inflicts $s2 Shadowflame damage to players in a frontal cone.", ua = "Ґнарлрут завдає $s2 шкоди тіньовим полум'ям гравцям у конусі перед собою." },
    { en = "Gnarlroot shoots missiles at his current target over $d1, each inflicting $426108s1 Physical damage and $424366s1 Shadowflame damage.\n\n\n\nEach impact also causes the target to take $426106s1% increased Shadowflame damage for $426106d. This effect stacks.", ua = "Ґнарлрут випускає снаряди в поточну ціль протягом $d1, кожен з яких завдає $426108s1 фізичної шкоди та $424366s1 шкоди тіньовим полум'ям.\n\n\n\nКожне влучання також змушує ціль отримувати на $426106s1% більше шкоди тіньовим полум'ям протягом $426106d. Цей ефект накопичується." },
    { en = "The lasher spits thorns at a player, inflicting $422464s1 Shadowflame damage. The thorns shred the target's armor, causing them to take $422466s2% increased damage and bleed for $422466s1 Physical damage every $422466t1 sec for $422466d. This effect stacks.", ua = "Шмагач плює колючками в гравця, завдаючи $422464s1 шкоди тіньовим полум'ям. Колючки шматують броню цілі, змушуючи її отримувати на $422466s2% більше шкоди та кровоточити, завдаючи $422466s1 фізичної шкоди кожні $422466t1 сек протягом $422466d. Цей ефект накопичується." },
    { en = "Shadowflame residue inflicts $425002s1 Shadowflame damage every $425002t1 sec. This effect stacks.\n\n\n\nTouching a $@spellname425648 while afflicted ignites the root and removes one application of this effect.", ua = "Залишки тіньового полум'я завдають $425002s1 шкоди тіньовим полум'ям кожні $425002t1 сек. Цей ефект накопичується.\n\n\n\nДотик до $@spellname425648 під дією ефекту підпалює корінь і знімає одне накладання цього ефекту." },
    { en = "Roots burst forth from the doomed soil, inflicting $s1 Nature damage to players up to $A1 yards and knocking them away.", ua = "Корені виривається з приреченого ґрунту, завдаючи $s1 шкоди від сил природи гравцям на відстані до $A1 м і відкидаючи їх." },
    { en = "Flaming chunks of bramble fly off Gnarlroot's body, causing players to burst into flames after $426548d. The blast inflicts $426616t1 Shadowflame damage to players within $426616A1 yards of their location.\n\n\n\nPlayers become $@spellname421038 by the blast.", ua = "Палаючі шматки тернини відлітають від тіла Ґнарлрута, через що гравці спалахують полум'ям за $426548d. Вибух завдає $426616t1 тіньовим полум'ям гравцям у межах $426616A1 ярдів від їхнього розташування.\n\n\n\nГравців у зоні вибуху уражає $@spellname421038." },
    { en = "Each activated lasher increases the haste and damage done of all other active lashers within $m4 yards by $s1%. This effect stacks.\n\n\n\nUpon reaching $m5 applications, the lasher becomes $@spellname429009.", ua = "Кожен активований шмагач збільшує поспіх і завдану шкоду всіх інших активних шмагачів у радіусі $m4 м на $s1%. Цей ефект накопичується.\n\n\n\nПісля досягнення $m5 накладань шмагач стає $@spellname429009." },
    { en = "Gnarlroot is immobilized by agony, increasing his damage taken by $s1% and causing him to pulse $430324s1 Shadowflame damage to all players every $424734t2 sec for $d.\n\n\n\nUpon expiration, Gnarlroot gains an application of $@spellname425709.", ua = "Ґнарлрут знерухомлений мукою, через що отримує на $s1% більше шкоди й випромінює $430324s1 шкоди тіньовим полум'ям усім гравцям кожні $424734t2 сек протягом $d.\n\n\n\nПісля завершення Ґнарлрут отримує накладання $@spellname425709." },
    { en = "The lasher is germinated by nearby allies, making it immune to interrupts and crowd controlling effects.", ua = "Шмагача пророщують сусідні союзники, роблячи його несприйнятливим до переривань і ефектів контролю." },
    { en = "Gnarlroot marks players with a Shadowflame plague, inflicting $422091s1 Shadowflame damage to players within $422091A1 yards of their location every $t1 sec for $d1.\n\n\n\nUpon expiration, the affliction creates a patch of $@spellname422023.", ua = "Ґнарлрут позначає гравців пошестю тіньового полум'я, що завдає $422091s1 тіньовим полум'ям гравцям у межах $422091A1 ярдів від їхнього розташування щожно $t1 сек. протягом $d1.\n\n\n\nПісля завершення пошесть утворює ділянку $@spellname422023." },
    { en = "The Tainted Treant releases blazing pollen, inflicting $s1 Fire damage to the five closest players and disorienting them for $d.", ua = "Споганений Трент випускає палаючий пилок, завдаючи $s1 шкоди вогнем п'ятьом найближчим гравцям і дезорієнтуючи їх на $d." },
    { en = "The Tainted Treant hurls flaming sap at players, slowing them for $d. While afflicted, players ignite every $t1 sec, inflicting $425821s1 Fire damage to players within $425821A1 yards.", ua = "Опоганений Древінь жбурляє в гравців палаючу живицю, сповільнюючи їх на $d. Поки гравці уражені, вони спалахують щожно $t1 сек., завдаючи $425821s1 вогнем гравцям у межах $425821A1 ярдів." },
    { en = "Upon awakening inflicts $s1 Shadowflame damage to all enemies.", ua = "Завдає $s1 шкоди тіньовим полум'ям усім ворогам під час пробудження." },
    { en = "Toxic soil inflicts $s1 Shadowflame damage every $t1 sec to players within 6 yards of Gnarlroot and reduces movement speed by $s2%. This affliction also reduces the magnitude of forced movement effects.", ua = "Отруйний ґрунт завдає $s1 тіньовим полум'ям щожно $t1 сек. гравцям у межах 6 ярдів від Ґнарлрута та знижує швидкість пересування на $s2%. Це ураження також зменшує силу ефектів примусового пересування." },
    { en = "Chunks of flaming charcoal fly from Gnarlroot, inflicting $421064s1 Shadowflame damage to players within $421064A1 yards of the impact locations, and making them $@spellname421038.\n\n\n\nEach chunk of charcoal that does not hit a player erupts on contact with the ground, inflicting $421427s1 Shadowflame damage to all players.", ua = "Шматки палаючого вугілля розлітаються від Ґнарлрута, завдаючи $421064s1 шкоди тіньовим полум'ям гравцям у радіусі $421064A1 м від місць влучання й накладаючи на них $@spellname421038.\n\n\n\nКожен шматок вугілля, що не влучає в гравця, вибухає при контакті із землею, завдаючи $421427s1 шкоди тіньовим полум'ям усім гравцям." },
    { en = "The pain from $@spellname421840 sends Gnarlroot into a frenzy, causing him to inflict $s1% increased damage. This effect stacks.", ua = "Біль від $@spellname421840 вганяє Ґнарлрута в шаленство, через що він завдає на $s1% більше шкоди. Цей ефект накопичується." },
    { en = "Shadowflame orbs erupt from the afflicted player, inflicting $426056s1 Shadowflame damage to players they contact and an additional $426056s2 Shadowflame damage every $426056t2 sec for $426056d.", ua = "Кулі тіньового полум'я вириваються з ураженого гравця, завдаючи $426056s1 шкоди тіньовим полум'ям гравцям, яких торкаються, і додатково $426056s2 шкоди тіньовим полум'ям кожні $426056t2 сек протягом $426056d." },
    { en = "Igira smashes her current target, inflicting $s1 Shadowflame damage to all players, reduced by the number of players within $429260A1 yards of the impact location.\n\n\n\n$?diff15|diff16 [Players within $429260A1 yards of the impact location also suffer $@spellname429277.][]", ua = "Іґіра вгачує поточну ціль, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям; шкода зменшується залежно від кількості гравців у радіусі $429260A1 м від місця влучання.\n\n\n\n$?diff15|diff16 [Гравці в радіусі $429260A1 м від місця влучання також зазнають $@spellname429277.][]" },
    { en = "Sparks fly from Igira's hammer towards players, inflicting $s1 Shadowflame damage to players within $a1 yards and knocking them back.\n\n\n\n$?diff14|diff15|diff16 [Each swing of her hammer inflicts $426150s1 Shadowflame damage to all players.][]", ua = "Від молота Іґіри до гравців летять іскри, завдаючи $s1 шкоди тіньовим полум'ям гравцям у радіусі $a1 м і відкидаючи їх.\n\n\n\n$?diff14|diff15|diff16 [Кожен змах її молота завдає $426150s1 шкоди тіньовим полум'ям усім гравцям.][]" },
    { en = "Igira lacerates her target, inflicting $414342s1 Shadowflame damage every $414340t1 sec for $414340d. This effect stacks.", ua = "Іґіра шматує свою ціль, завдаючи $414342s1 тіньовим полум'ям щожно $414340t1 сек. протягом $414340d. Цей ефект накопичується." },
    { en = "Igira's melee attacks also strike the next closest player. If no target is found, her primary target is struck again.\n\n\n\nEach melee strike also applies $@spellname414340.", ua = "Атаки ближнього бою Іґіри також вражають наступного найближчого гравця. Якщо цілі не знайдено, її основна ціль уражається повторно.\n\n\n\nКожен удар ближнього бою також накладає $@spellname414340." },
    { en = "Igira expels swirling blades in the direction of a player, inflicting $404910s1 Shadowflame damage to players hit.", ua = "Іґіра викидає в напрямку гравця вихор клинків, завдаючи $404910s1 шкоди тіньовим полум'ям ураженим гравцям." },
    { en = "Igira's torment scars the player's flesh, increasing damage inflicted by $@spellname414367 $s1% after $d.", ua = "Тортури Іґіри спотворюють плоть гравця, збільшуючи шкоду від $@spellname414367 на $s1% за $d." },
    { en = "If none of Igira's areas of torment are extinguished, she smashes the ground inflicting $s1 Shadowflame damage to all players and an additional $429620s1 Shadowflame damage every $429607t1 sec for $429607d.", ua = "Якщо жодну з областей муки Іґіри не погашено, вона вгачує по землі, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям і додатково $429620s1 шкоди тіньовим полум'ям кожні $429607t1 сек протягом $429607d." },
    { en = "Igira leaps to players$?diff17 [inflicting $s1 Shadowflame damage to players within $a1 yards of each impact and knocking them back.][] $?diff14|diff15|diff16 [inflicting $s1 Shadowflame damage to players within $a1 yards of each impact and knocking them back. Igira's leaps inflict $s3 Shadowflame damage to players outside the impact zone.][]", ua = "Іґіра стрибає до гравців,$?diff17 [завдаючи $s1 шкоди тіньовим полум'ям гравцям у межах $a1 ярдів від кожного удару й відкидаючи їх.][] $?diff14|diff15|diff16 [завдаючи $s1 шкоди тіньовим полум'ям гравцям у межах $a1 ярдів від кожного удару й відкидаючи їх. Стрибки Іґіри завдають $s3 шкоди тіньовим полум'ям гравцям поза зоною удару.][]" },
    { en = "Igira hurls blades at several players, causing them to absorb $415623s1 healing for $415623d. Upon expiration, $?diff17 [the target's heart explodes, inflicting $426420s1 Shadowflame damage.][]$?diff14|diff15|diff16 [the target's heart explodes, inflicting $415636s1 Shadowflame damage to all players.] []$?diff15|diff16 [ When removed, the target inflicts $426447s1 Shadowflame damage to players within $426447a1 yards.][]", ua = "Іґіра кидає клинки в кількох гравців, через що ті поглинають $415623s1 зцілення на $415623d. Після завершення $?diff17 [серце цілі вибухає, завдаючи $426420s1 шкоди тіньовим полум'ям.][]$?diff14|diff15|diff16 [серце цілі вибухає, завдаючи $415636s1 шкоди тіньовим полум'ям усім гравцям.] []$?diff15|diff16 [ Коли ефект знято, ціль завдає $426447s1 шкоди тіньовим полум'ям гравцям у межах $426447a1 ярдів.][]" },
    { en = "Heat radiates from the spear, inflicting $414777s1 Shadowflame damage every $t1 sec to players within $414427a1 yards until the spear is destroyed.", ua = "Від списа випромінюється жар, завдаючи $414777s1 шкоди тіньовим полум'ям кожні $t1 с гравцям у межах $414427a1 ярдів, доки спис не буде знищено." },
    { en = "With each leap Igira unleashes waves of devastation that inflict $s1 Shadowflame damage to players they hit.", ua = "З кожним стрибком Іґіра вивільняє хвилі спустошення, що завдають $s1 шкоди тіньовим полум'ям ураженим гравцям." },
    { en = "Igira inflicts $s2 Shadowflame damage, knocking back players within $a1 yards and igniting three areas for torment. Players standing within an ignited area cause it to shrink, but suffer $@spellname414367 while Igira forges her next weapon.\n\n\n\n$?diff14|diff15|diff17 [Igira's finished weapon changes based on which area players fully extinguish. If no area is extinguished, Igira unleashes $@spellname419048.][]$?diff16 [Igira's finished weapons are chosen from the areas not extinguished, then dual wields them to combine their attacks. If no area is extinguished, Igira unleashes $@spellname419048.][]\n\n\n\nWhile forging a weapon, each of Igira's hammer strikes launches $@spellname423715.", ua = "Іґіра завдає $s2 шкоди тіньовим полум'ям, відкидаючи гравців у радіусі $a1 м і підпалюючи три ділянки на муку. Гравці, що стоять у підпаленій ділянці, змушують її стискатися, але потерпають від $@spellname414367, поки Іґіра кує свою наступну зброю.\n\n\n\n$?diff14|diff15|diff17 [Готова зброя Іґіри залежить від того, яку ділянку гравці повністю згасять. Якщо жодну ділянку не згашено, Іґіра вивільняє $@spellname419048.][]$?diff16 [Готову зброю Іґіри обирають із незгашених ділянок, після чого вона б'ється двома клинками, поєднуючи їхні атаки. Якщо жодну ділянку не згашено, Іґіра вивільняє $@spellname419048.][]\n\n\n\nКуючи зброю, кожен удар молота Іґіри запускає $@spellname423715." },
    { en = "Igira hurls spears at players, tethering them to the ground and $?diff14|diff15|diff16|diff17 [inflicting $s1 Shadowflame damage to players within $A1 yards of the impact.\n\n\n\nWhile present, the spear radiates $@spellname414770.][]", ua = "Іґіра кидає в гравців списи, прив'язуючи їх до землі$?diff14|diff15|diff16|diff17 [ і завдаючи $s1 тіньовим полум'ям гравцям у межах $A1 ярдів від влучання.\n\n\n\nПоки спис стоїть, він випромінює $@spellname414770.][.]" },
    { en = "Igira increases her damage done by $s1% when she reaches 100 energy. This effect stacks.", ua = "Іґіра збільшує завдану нею шкоду на $s1%, коли досягає 100 енергії. Цей ефект накопичується." },
    { en = "Igira's attack leaves the player brutalized, unable to diminish the damage of the next $@spellname416056.", ua = "Атака Іґіри лишає гравця понівеченим, нездатним зменшити шкоду від наступного $@spellname416056." },
    { en = "Igira harvests the torment from her victims, inflicting $s1 Shadowflame damage to players within an area Marked for Torment.\n\n\n\n$?diff15|diff16 [When applied, afflicted players suffer $@spellname419462.][]", ua = "Іґіра жне муку зі своїх жертв, завдаючи $s1 шкоди тіньовим полум'ям гравцям в області, Позначеній для Муки.\n\n\n\n$?diff15|diff16 [При накладанні уражені гравці зазнають $@spellname419462.][]" },
    { en = "The spiraling embers radiate fire outward, inflicting $s1 Fire damage to nearby allies. This damage increases as the $@spellname421207 tighten.", ua = "Спіральні жарини випромінюють вогонь назовні, завдаючи $s1 шкоди вогнем сусіднім союзникам. Ця шкода зростає, коли $@spellname421207 стискаються." },
    { en = "The flames fully constrict their target, inflicting $427197s1 Fire damage every $t1 sec for $d.\n\n\n\nUpon expiration, the target explodes, inflicting $427204s1 Fire damage split among players within $427204A1 yards of the blast. The flames then slither to another player.", ua = "Полум'я повністю стискає свою ціль, завдаючи $427197s1 шкоди вогнем кожні $t1 сек протягом $d.\n\n\n\nПісля завершення ціль вибухає, завдаючи $427204s1 шкоди вогнем, розподіленої між гравцями в радіусі $427204A1 м від вибуху. Тоді полум'я ковзає до іншого гравця." },
    { en = "Snakelike flames swirl around the player, inflicting $421228s1 Fire damage to them and radiating $@spellname429153 to nearby players every $421207s2 sec for $421207d. The flames tighten over time, increasing their damage as they reduce in area.$?diff14|diff17|diff15 [\n\n\n\nUpon expiration, the flames slither to another player.][]", ua = "Зміїсте полум'я в'ється довкола гравця, завдаючи йому $421228s1 одиниць вогняної шкоди й випромінюючи $@spellname429153 на ближніх гравців кожні $421207s2 с протягом $421207d. З часом полум'я стискається, посилюючи свою шкоду в міру зменшення площі.$?diff14|diff17|diff15 [\n\n\n\nПісля завершення полум'я перебирається до іншого гравця.][]" },
    { en = "Volcoross's fiery tail emerges from the lava and slams his surrounding ring, inflicting $420410s1 Physical damage to players hit and knocking them back. A molten shockwave inflicts $428137s4 Fire damage to all players.", ua = "Вогняний хвіст Волкоросса виринає з лави й гатить по кільцю довкола нього, завдаючи $420410s1 одиниць фізичної шкоди враженим гравцям і відкидаючи їх. Розплавлена ударна хвиля завдає $428137s4 одиниць вогняної шкоди всім гравцям." },
    { en = "Upon reaching 100 energy, Volcoross launches two massive globs of lava that splatter across his chamber. Each impact inflicts $420929s1 Fire damage split among players within $420929A1 yards, knocking them back, and creating $@spellname421082.\n\n\n\nIf either lava glob fails to hit $?diff14|diff15|diff16 [at least $s4 players][]$?diff17 [a player][], it inflicts $420952s1 Fire damage to all players and $@spellname421082 consumes the entire chamber.", ua = "Досягнувши 100 енергії, Волкоросс запускає дві величезні грудки лави, що розбризкуються по його залу. Кожне влучання завдає $420929s1 шкоди вогнем, розподіленої між гравцями в радіусі $420929A1 м, відкидає їх і створює $@spellname421082.\n\n\n\nЯкщо будь-яка грудка лави не влучить $?diff14|diff15|diff16 [щонайменше в $s4 гравців][]$?diff17 [в гравця][], вона завдає $420952s1 шкоди вогнем усім гравцям, і $@spellname421082 поглинає весь зал." },
    { en = "A flowing rush of lava that inflicts $s1 Fire damage every $t1 sec to players within the effect.", ua = "Бурхливий потік лави, що завдає $s1 шкоди вогнем кожні $t1 сек гравцям у зоні дії." },
    { en = "Volcoross spews surging fire from his jaws, inflicting $421671s1 Fire damage to all players every $t1 sec for $d. Several players combust with $@spellname421207.", ua = "Волкоросс вивергає зі своєї пащі ревучий вогонь, завдаючи $421671s1 шкоди вогнем усім гравцям кожні $t1 сек протягом $d. Кілька гравців спалахують від $@spellname421207." },
    { en = "Volcoross unleashes the full magnifying force of the Firelands, inflicting $421705s1 Fire damage to all players and increasing his damage done by $421702s1% every $t1 sec.", ua = "Волкоросс вивільняє всю всепосилюючу міць Вогняних Земель, завдаючи $421705s1 шкоди вогнем усім гравцям і збільшуючи завдану ним шкоду на $421702s1% кожні $t1 сек." },
    { en = "Taking damage from more than one $@spellname427204 at the same time shreds the player in a whirlwind of flames, inflicting $s1 Fire damage.", ua = "Отримання шкоди одночасно від кількох $@spellname427204 шматує гравця у вихорі полум'я, завдаючи $s1 шкоди від вогню." },
    { en = "Volcoross's igneous skeleton emanates with blistering heat, inflicting $421674s1 Fire damage to all players every $t1 sec.", ua = "Палаючий кістяк Волкоросса випромінює нестерпний жар, завдаючи $421674s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "Volcoross's calamitous jaws ravage his current target, inflicting $423118s1 Physical damage and $423119s1 Fire damage.", ua = "Згубні щелепи Волкоросса терзають його поточну ціль, завдаючи $423118s1 фізичної шкоди та $423119s1 вогнем." },
    { en = "Volcoross's melee attacks inject sizzling venom into his current target, inflicting $419056s1 Fire damage every $t1 sec and increasing damage taken from $@spellname423117 by $s2% for $d. This effect stacks.", ua = "Атаки ближнього бою Волкоросса вприскують шиплячу отруту в його поточну ціль, завдаючи $419056s1 шкоди вогнем кожні $t1 с та збільшуючи отримувану шкоду від $@spellname423117 на $s2% протягом $d. Цей ефект накопичується." },
    { en = "If no players are within reach, Volcoross continually vents waves of flames that inflict $424221s1 Fire damage to all players every $424222t1 sec.", ua = "Якщо поблизу немає гравців, Волкоросс безперервно випускає хвилі полум'я, що завдають $424221s1 шкоди вогнем усім гравцям кожні $424222t1 с." },
    { en = "Volcoross retches chunks of searing bile at players, inflicting $421613s1 Fire damage within $421613A1 yards of each impact and creating $@spellname421082.", ua = "Волкоросс вивергає на гравців згустки пекучої жовчі, завдаючи $421613s1 одиниць вогняної шкоди в межах $421613A1 ярдів від кожного влучання і створюючи $@spellname421082." },
    { en = "Crawling magma incinerates the ground, inflicting $s1 Fire damage every $t1 sec to players within the effect.", ua = "Повзуча магма випалює землю, завдаючи $s1 шкоди вогнем кожні $t1 с гравцям, що перебувають у зоні дії." },
    { en = "You've eaten your fill and cannot consume any more $@spellname420671s.", ua = "Ти наївся досхочу і більше не можеш спожити жодної $@spellname420671s." },
    { en = "Upon reaching 1 health, council members tap into the dream casting $@spellname418187, restoring $s1% health while their allies remain conscious.", ua = "Падаючи до 1 здоров'я, члени ради черпають силу зі Сну, творячи $@spellname418187, що відновлює $s1% здоров'я, доки їхні союзники лишаються при тямі." },
    { en = "The Council of Dreams' unrivaled coordination enables two members to execute their strongest attacks simultaneously.", ua = "Незрівнянна злагодженість Ради Снів дозволяє двом її членам виконати свої найпотужніші атаки одночасно." },
    { en = "$@spellname420671s additionally inflict $s1 Nature damage every $t1 sec to players standing within.", ua = "$@spellname420671s додатково завдають $s1 шкоди від сил природи кожні $t1 с гравцям, що стоять усередині." },
    { en = "If $@spellname420525 is not interrupted, Urctos gains $s1% increased damage done for the duration of the encounter.", ua = "Якщо $@spellname420525 не перервати, Урктос отримує збільшення завданої шкоди на $s1% до кінця бою." },
    { en = "Urctos slashes at his current target, inflicting $421021s1 Physical damage $?DIFF15|DIFF16[to players in a frontal cone, ][and ]increasing damage taken from $@spellname421020 by $421022s1% for $421022d. This effect stacks.", ua = "Урктос шматує свою поточну ціль, завдаючи $421021s1 фізичної шкоди $?DIFF15|DIFF16[гравцям у фронтальному конусі та ][та ]збільшуючи отримувану шкоду від $@spellname421020 на $421022s1% протягом $421022d. Цей ефект накопичується." },
    { en = "Pip's devious magic transforms players into ducks for $d granting them $@spellname424269, afflicting them with $@spellname427602 and enabling them to $@spellname420409 and $@spellname422372.\n\n\n\n$?DIFF15|DIFF16[Upon removal the transformation spreads applying $@spellname418720 to players within $418740A1 yards for $d.][Upon removal the tricky magic spreads incapacitating players within $418740A1 yards for $425410d.]", ua = "Підступна магія Піпа перетворює гравців на качок на $d, надаючи їм $@spellname424269, накладаючи на них $@spellname427602 та дозволяючи їм $@spellname420409 і $@spellname422372.\n\n\n\n$?DIFF15|DIFF16[Після зняття перетворення поширюється, накладаючи $@spellname418720 на гравців у межах $418740A1 м протягом $d.][Після зняття підступна магія поширюється, знерухомлюючи гравців у межах $418740A1 м протягом $425410d.]" },
    { en = "Pip channels massive gusts of wind for $d pushing all players away, inflicting $s1 Nature damage, and inflicting an additional $s2 Nature damage every $t2 sec.", ua = "Піп $d спрямовує потужні пориви вітру, що відштовхують усіх гравців, завдаючи $s1 одиниць шкоди силами природи і ще $s2 одиниць шкоди силами природи кожні $t2 с." },
    { en = "At 100 energy, Pip sings a captivating song causing all players to absorb $421031s1 $@spellname426390 damage.", ua = "При 100 одиницях енергії Піп співає чарівливу пісню, через яку всі гравці поглинають $421031s1 одиниць шкоди від $@spellname426390." },
    { en = "When $@spellname421029 concludes, all players still affected by $@spellname421029 begin to dance, becoming stunned and suffering $423488s1 Nature damage every $t2 sec for $d.", ua = "Коли $@spellname421029 завершується, усі гравці, досі вражені $@spellname421029, починають танцювати, стаючи приголомшеними та зазнаючи $423488s1 одиниць шкоди силами природи кожні $t2 с протягом $d." },
    { en = "At 100 energy, Aerwynn conjures vines for $d, lashing out at all players inflicting $421298s1 Nature damage every $421298t1 sec and decreasing their movement speed by $421298s2%. This effect stacks and increases in stacks every $421292t1 sec.\n\n\n\nThis channel leaves Aerwynn susceptible to $@spellname420946.", ua = "За 100 енергії Аервінн прикликає лози на $d, які шмагають усіх гравців, завдаючи $421298s1 шкоди від сил природи кожні $421298t1 с та знижуючи їхню швидкість пересування на $421298s2%. Цей ефект накопичується і нарощує заряди кожні $421292t1 с.\n\n\n\nЦе каналізування робить Аервінн вразливою до $@spellname420946." },
    { en = "$425362s1% of damage taken by Urctos, Pip or Aerwynn is additionally dealt to the others.", ua = "$425362s1% шкоди, отриманої Урктосом, Піпом чи Аервінн, додатково завдається іншим." },
    { en = "At 100 energy, Urctos becomes entranced in a wild assault for $d, inflicting $420531s1 Physical damage to all players every $t1 sec. Each slam increases his damage done by $420604s1% for the duration of the assault.\n\n\n\nThis trance leaves Urctos susceptible to $@spellname418720.", ua = "При 100 одиницях енергії Урктос на $d впадає в транс несамовитого нападу, завдаючи $420531s1 одиниць фізичної шкоди всім гравцям кожні $t1 с. Кожен удар підвищує завдану ним шкоду на $420604s1% до кінця нападу.\n\n\n\nЦей транс робить Урктоса вразливим до $@spellname418720." },
    { en = "Leap forward as a duck and gain a rush of adrenaline increasing movement speed by $s1% for $d. QUACK!", ua = "Стрибни вперед качкою й отримай приплив адреналіну, що збільшує швидкість пересування на $s1% протягом $d. КРЯ!" },
    { en = "Aerwynn showers the ground with blossoms that emit poisonous fumes, inflicting $420715s1 Nature damage to all players every $420714t1 sec until destroyed.", ua = "Аервінн всіває землю квітами, що випускають отруйні випари, завдаючи $420715s1 шкоди від сил природи всім гравцям кожні $420714t1 с, доки їх не знищено." },
    { en = "If $@spellname421292 is not interrupted, Aerwynn unleashes a furious bombardment for $d, launching javelins at all players every $t1 sec poisoning targets for $421016s1 Nature damage every $421018t1 sec for $421018d. This effect stacks.", ua = "Якщо $@spellname421292 не перервати, Аервінн розв'язує лютий обстріл протягом $d, метаючи дротики в усіх гравців кожні $t1 с, що отруюють цілі, завдаючи $421016s1 шкоди від сил природи кожні $421018t1 с протягом $421018d. Цей ефект накопичується." },
    { en = "As a duck harmful poisons slide right off your feathers reducing Nature damage taken by $s1%.", ua = "У подобі качки шкідливі отрути просто стікають з твого пір'я, знижуючи отримувану шкоду від сил природи на $s1%." },
    { en = "Urctos focuses upon his current target for $s2 sec then charges, inflicting $422052s1 Physical damage to players in his path. $?DIFF15|DIFF16[Targets trampled are weakened, increasing damage taken from $@spellname420947 by $423420s1% for $423420d.][]\n\n\n\nUpon reaching his target, Urctos unleashes a $@spellname420966.", ua = "Урктос зосереджується на своїй поточній цілі на $s2 сек., а тоді кидається вперед, завдаючи $422052s1 фізичної шкоди гравцям на своєму шляху. $?DIFF15|DIFF16[Затоптані цілі слабшають, через що отримують на $423420s1% більше шкоди від $@spellname420947 протягом $423420d.][]\n\n\n\nСягнувши цілі, Урктос вивільняє $@spellname420966." },
    { en = "You've got a ducky appetite and are unable to $@spellname422372. Consuming a $@spellname420671 removes one application.\n\n\n\nUpon removal, applies $@spellname427010.", ua = "У тебе качачий апетит, і ти не можеш $@spellname422372. Спожиття $@spellname420671 знімає один заряд.\n\n\n\nПісля зняття накладає $@spellname427010." },
    { en = "The player bursts with poison, inflicting $s1 Nature damage to other players within $a2 yards.", ua = "Гравець вибухає отрутою, завдаючи $s1 шкоди природою іншим гравцям у радіусі $a2 м." },
    { en = "Requires $@spellname427010.\n\n\n\nCleanse yourself removing the effects of $@spellname418720.", ua = "Потребує $@spellname427010.\n\n\n\nОчисти себе, знявши ефекти $@spellname418720." },
    { en = "Urctos bellows an earth-shaking roar,  inflicting $420966s1 Physical damage to all players reduced by the number of players struck by $@spellname420947.", ua = "Урктос видає землетрусний рев, завдаючи $420966s1 фізичної шкоди всім гравцям, зменшеної на кількість гравців, уражених $@spellname420947." },
    { en = "Aerwynn launches poison-laced javelins at players, inflicting $420858s1 Nature damage on impact, an additional $420859s1 Nature damage every $420858t2 sec and reducing their movement speed by $420858s3% for $420858d. This effect stacks.\n\n$?DIFF16[\n\nUpon removal, the player explodes with $@spellname423522.][]", ua = "Аервінн метає в гравців отруєні дротики, завдаючи $420858s1 шкоди від сил природи при влучанні, додаткові $420859s1 шкоди від сил природи кожні $420858t2 с та знижуючи їхню швидкість пересування на $420858s3% протягом $420858d. Цей ефект накопичується.\n\n$?DIFF16[\n\nПісля зняття гравець вибухає, вивільняючи $@spellname423522.][]" },
    { en = "Pip's emerald winds coalesce throughout the arena inflicting $s1 Nature damage and knocking back any players caught within.", ua = "Смарагдові вітри Піпа збираються по всій арені, завдаючи $s1 шкоди від сил природи та відкидаючи всіх гравців, що потрапили в них." },
    { en = "The Blazing Thorns coalesce into flame orbs which move towards Larodar. Upon contact an orb inflicts $431314s1 Fire damage, increasing critical strike chance by $426249s3% and inflicting $431315s2 Fire damage every $426249t2 sec for $426249D.\n\n\n\nOrbs that reach Larodar increase Fire damage done by $426256s1% for $426256D. This effect stacks.", ua = "Палаючі Терни зливаються у вогняні сфери, що рухаються до Лародара. При контакті сфера завдає $431314s1 шкоди вогнем, збільшуючи шанс критичного удару на $426249s3% та завдаючи $431315s2 шкоди вогнем кожні $426249t2 с протягом $426249D.\n\n\n\nСфери, що досягають Лародара, збільшують завдану ним шкоду вогнем на $426256s1% протягом $426256D. Цей ефект накопичується." },
    { en = "Increases the damage taken from $@spellname421594 by $s1% for $D. This effect stacks.", ua = "Збільшує отримувану шкоду від $@spellname421594 на $s1% протягом $D. Цей ефект накопичується." },
    { en = "Scorching Roots strangle enemies they come in contact with fiery brambles, inflicting $s1 Fire damage every $t1 sec and rooting them in place for $D.", ua = "Пекучі Корені обплутують ворогів, з якими стикаються, вогняними тернами, завдаючи $s1 шкоди вогнем кожні $t1 с та знерухомлюючи їх на місці протягом $D." },
    { en = "Fiery Treants expel flames, inflicting $s1 Fire damage to enemies within $a1 yards.", ua = "Вогняні Древні вивергають полум'я, завдаючи $s1 вогнем ворогам у межах $a1 ярдів." },
    { en = "Reduces damage taken from $@spellname417634 by $M1%.", ua = "Знижує отримувану шкоду від $@spellname417634 на $M1%." },
    { en = "Larodar twists his fiery grip on nature implanting flame inside players for $425888D, causing players to create of $@spellname417610. This effect is reduced when standing next to $@spellname417610.", ua = "Лародар стискає свою вогняну хватку на природі, вкорінюючи полум'я всередині гравців на $425888D, через що гравці створюють $@spellname417610. Цей ефект слабшає, коли стоїш поруч із $@spellname417610." },
    { en = "The Seed of Life blossoms from Renewed Treants' life energy allowing $s1 players to interact, forming a magical bond with the seed.\n\n\n\n$?diff14|diff17|diff15 [Each bonded player][]$?diff16 [The final player in the bond][] expels emerald magic dousing $@spellname417632 and $@spellname418654, draining energy from the Seed of Life.", ua = "Насінина Життя розквітає з життєвої енергії Відроджених Тріантів, дозволяючи $s1 гравцям взаємодіяти з нею, утворюючи магічний зв'язок із насіниною.\n\n\n\n$?diff14|diff17|diff15 [Кожен зв'язаний гравець][]$?diff16 [Останній гравець у зв'язку][] вивільняє смарагдову магію, гасячи $@spellname417632 і $@spellname418654, висотуючи енергію з Насінини Життя." },
    { en = "Renewed Treant's channel their own life force into the Seed of Life, gifting it energy but reducing their own maximum health by $425397s1% every $t1 sec.", ua = "Відроджені Тріанти каналізують власну життєву силу в Насінину Життя, даруючи їй енергію, але знижуючи власне максимальне здоров'я на $425397s1% кожні $t1 с." },
    { en = "Larodar's fury takes a heavy toll on his target, increasing Physical damage taken by $s1% for $D. This effect begins at $U stacks and decreases in stacks over time.", ua = "Лють Лародара тяжко б'є по його цілі, збільшуючи отримувану фізичну шкоду на $s1% протягом $D. Цей ефект починається з $U зарядів і з часом слабшає." },
    { en = "Players encased in ash are stunned for $D.", ua = "Гравці, заковані в попіл, приголомшені протягом $D." },
    { en = "Larodar's very presence combusts the air around him, inflicting $417585s1 Fire damage every $t1 sec to all enemies and causes him to leave behind $@spellname417632.\n\n\n\nLarodar gains a stack after channeling $@spellname417634.", ua = "Сама присутність Лародара спалює повітря довкола нього, завдаючи $417585s1 шкоди вогнем кожні $t1 сек усім ворогам і змушуючи його лишати по собі $@spellname417632.\n\n\n\nЛародар отримує заряд після каналізування $@spellname417634." },
    { en = "Forming a bond with the Seed of Life causes fatigue, preventing the player from forming another bond for $D.", ua = "Зв'язок із Насіниною Життя викликає втому, не даючи гравцеві утворити інший зв'язок протягом $D." },
    { en = "Larodar calls upon the ashes of his fallen Treants.", ua = "Лародар прикликає попіл своїх полеглих трентів." },
    { en = "Larodar releases a fiery outburst when reaching his target, inflicting $s1 Fire damage to all players. This damage decreases based on distance from Larodar.", ua = "Сягнувши цілі, Лародар вивільняє вогняний спалах, завдаючи $s1 шкоди вогнем усім гравцям. Ця шкода зменшується залежно від відстані до Лародара." },
    { en = "After $s1 casts of Raging Inferno Larodar draws upon the surrounding flames for $D radiating $421315s1 Fire damage to all players every $t1 sec, pulling players towards him. Additionally the Keeper inflicts $423610s1 Fire damage to players within $Q1 yards.\n\n\n\nThese flames combust Larodar transforming him into the Avatar of Ash.", ua = "Після $s1 застосувань Лютого пекла Лародар черпає силу з навколишнього полум'я протягом $D, випромінюючи $421315s1 шкоди вогнем усім гравцям кожні $t1 сек і притягуючи їх до себе. Крім того, Хранитель завдає $423610s1 шкоди вогнем гравцям у межах $Q1 м.\n\n\n\nЦе полум'я спалює Лародара, перетворюючи його на Втілення Попелу." },
    { en = "Larodar's ashen husk unleashes a brutal backdraft of flames inflicting $421591s1 Fire damage in a frontal cone, applying $@spellname421594.", ua = "Попеляста оболонка Лародара вивільняє нищівний зворотний спалах полум'я, завдаючи $421591s1 шкоди вогнем у фронтальному конусі й накладаючи $@spellname421594." },
    { en = "The temple blazes with patches of flame, inflicting $s1 Fire damage every $t1 sec.\n\n\n\nLarodar's $@spellname417583, his Fiery Treats and Scorching Roots, and these flame patches spread Burning Ground further.\n\n\n\n$@spellname425249s douse the flames extinguishing these patches.", ua = "Храм палає осередками полум'я, завдаючи $s1 шкоди вогнем кожні $t1 сек.\n\n\n\n$@spellname417583 Лародара, його полум'яні тренти та пекучі корені, а також ці осередки полум'я ще більше поширюють Палаючу землю.\n\n\n\n$@spellname425249s гасять полум'я, тамуючи ці осередки." },
    { en = "Larodar radiates Searing Ash every 12 sec, inflicting $421324s1 Fire damage every $421407t1 sec. This effect stacks.", ua = "Лародар випромінює Пекучий попіл кожні 12 сек, завдаючи $421324s1 шкоди вогнем кожні $421407t1 сек. Цей ефект накопичується." },
    { en = "Larodar focuses his fury and charges at his target, inflicting up to $425031s1 Physical and $425029s1 Fire damage, knocking them away and applying $@spellname423719. This damage decreases based on distance from Larodar.\n\n\n\nLarodar inflicts an additional $418640s1 Physical damage to enemies caught in his path, knocking them back.", ua = "Лародар зосереджує свою лють і кидається на ціль, завдаючи до $425031s1 фізичної та $425029s1 шкоди вогнем, відкидаючи її й накладаючи $@spellname423719. Ця шкода зменшується залежно від відстані до Лародара.\n\n\n\nЛародар завдає додатково $418640s1 фізичної шкоди ворогам на своєму шляху, відкидаючи їх." },
    { en = "Larodar attempts to purge several players in a flash of fire, causing them to absorb $427299s1 healing for $421461D. Each player erupts after $421461D, inflicting $421467s1 Fire damage to players within $421467a1 yards.\n\n\n\nIf the absorb is not healed before expiring, $@spellname421326 also applies $@spellname421463 to players hit.", ua = "Лародар намагається випалити кількох гравців у спалаху вогню, змушуючи їх поглинати $427299s1 зцілення протягом $421461D. Кожен гравець вибухає після $421461D, завдаючи $421467s1 шкоди вогнем гравцям у межах $421467a1 м.\n\n\n\nЯкщо поглинання не зцілити до завершення, $@spellname421326 також накладає $@spellname421463 на вражених гравців." },
    { en = "Larodar focuses his rage into violent tornados that orbit the arena, inflicting $421470s1 Fire damage every $421470t1 sec to players standing within, knocking them back.", ua = "Лародар спрямовує свою лють у несамовиті торнадо, що кружляють ареною, завдаючи $421470s1 шкоди вогнем кожні $421470t1 сек гравцям усередині й відкидаючи їх." },
    { en = "Fiery Treant's melee strikes break splinters off in their target, inflicting $M1 Fire damage every $T1 sec for $D. This effect stacks.", ua = "Удари Вогняного Древня в ближньому бою лишають у його цілі скалки, завдаючи $M1 вогнем щожно $T1 сек. протягом $D. Цей ефект накопичується." },
    { en = "Suffocates a player reducing healing received by $s1% and inflicting $423787s1 Fire damage every $t2 sec for $D. \n\n\n\nAdditionally, this effect leeches $423807s1 health from allies within $423807A yards each $t2 sec.", ua = "Душить гравця, зменшуючи отримуване зцілення на $s1% і завдаючи $423787s1 шкоди вогнем кожні $t2 сек протягом $D.\n\n\n\nКрім того, цей ефект висмоктує $423807s1 здоров'я в союзників у межах $423807A м кожні $t2 сек." },
    { en = "Larodar bursts a spiral of eruptions inflicting $426209s1 Fire to players within $426209a1 yards of each impact, knocking them back.$?diff15|diff16[\n\n\n\nUpon reaching their destination they form a Blazing Coalescence, then return to Larodar.][\n\n\n\nUpon reaching their destination the spiral returns to Larodar.]", ua = "Лародар вивільняє спіраль вивержень, завдаючи $426209s1 вогнем гравцям у межах $426209a1 м від кожного удару й відкидаючи їх.$?diff15|diff16[\n\n\n\nСягнувши призначення, вони утворюють Палаюче Злиття, а потім повертаються до Лародара.][\n\n\n\nСягнувши призначення, спіраль повертається до Лародара.]" },
    { en = "Larodar marks players with explosive ash that draws in surrounding flame, inflicting $428902s1 Fire damage every $t2 sec for $D. Upon expiration, it inflicts $428904s1 Fire damage to all players. This damage is reduced the further away the players are from the blast.", ua = "Лародар позначає гравців вибуховим попелом, що притягує довколишнє полум'я, завдаючи $428902s1 вогнем щожно $t2 сек. протягом $D. Після завершення він завдає $428904s1 вогнем усім гравцям. Ця шкода тим менша, чим далі гравці від вибуху." },
    { en = "Upon reaching 100 energy Larodar releases his unbridled rage as waves of flames, inflicting $419343M1 Fire damage to enemies every $t1 sec for $D. Standing behind a $@spellname418653 reduces this damage by $419485M1%.\n\n\n\nLarodar gains a stack of Combusting Presence after Raging Inferno ends.", ua = "Сягнувши 100 енергії, Лародар вивільняє свою нестримну лють хвилями полум'я, завдаючи $419343M1 шкоди вогнем ворогам кожні $t1 сек протягом $D. Перебування за $@spellname418653 зменшує цю шкоду на $419485M1%.\n\n\n\nЛародар отримує заряд Спопеляючої присутності після завершення Лютого пекла." },
    { en = "Larodar's minions die in an explosion of fiery bark, each inflicting $M1 Fire damage to enemies within $a1 yards.", ua = "Прислужники Лародара гинуть у вибуху вогняної кори, кожен завдаючи $M1 вогнем ворогам у межах $a1 ярдів." },
    { en = "Increases the damage taken by $@spellname426249 by $s1%. This effect stacks.", ua = "Збільшує шкоду, отриману від $@spellname426249, на $s1%. Цей ефект накопичується." },
    { en = "Larodar releases a fistful of embers that fall from the sky, inflicting $421333s1 Fire damage to players within $421333a1 yards of the impact locations.\n\n\n\nEmbers that fail to hit a player inflict $421334s1 Fire damage to all players, applying a stack of $@spellname421323.", ua = "Лародар вивільняє жменю жарин, що падають із неба, завдаючи $421333s1 шкоди вогнем гравцям у межах $421333a1 м від місць удару.\n\n\n\nЖарини, що не влучили в гравця, завдають $421334s1 шкоди вогнем усім гравцям, накладаючи заряд $@spellname421323." },
    { en = "Larodar summons Fiery Treants.", ua = "Лародар прикликає полум'яних трентів." },
    { en = "Larodar summons Scorching Roots.", ua = "Лародар прикликає пекучі корені." },
    { en = "Nymue causes Surging Growths to burst from the ground, inflicting $s1 Nature damage to all players every $429829t1 sec for $420977d.\n\n\n\nPlayers who stand on a Growth stifle it, greatly reducing its duration.", ua = "Німуе змушує Буйні Парості вириватися із землі, завдаючи $s1 шкоди від сил природи всім гравцям кожні $429829t1 сек протягом $420977d.\n\n\n\nГравці, що стають на Парость, придушують її, значно скорочуючи її тривалість." },
    { en = "$430484s1 sec after a Surging Growth or Ephemeral Flora expires Nymue reclaims its energy, triggering an explosion at its location that inflicts $s1 Nature damage to players within $a1 yards.", ua = "За $430484s1 сек після завершення Буйної Парості чи Ефемерної Флори Німуе повертає собі їхню енергію, спричиняючи вибух у тому місці, що завдає $s1 шкоди від сил природи гравцям у межах $a1 м." },
    { en = "Life energy erupts from the Cycle Warden in an intricate pattern, inflicting $s1 Nature damage to players caught in its path.", ua = "Життєва енергія виривається з Вартового Циклу вигадливим візерунком, завдаючи $s1 шкоди від природи гравцям, що опинилися на її шляху." },
    { en = "The ground springs to life beneath your feet as you walk, allowing players within to pass unharmed through $@spellname418423 and increasing their movement speed by $s2%. Lasts $422615d.", ua = "Земля оживає під вашими ногами, коли ви йдете, дозволяючи гравцям усередині неушкодженими проходити крізь $@spellname418423 і збільшуючи їхню швидкість руху на $s2%. Триває $422615d." },
    { en = "When crossing threads of the $@spellname418423, the Cycle Warden disperses life energy inflicting $s1 Nature damage to all players. This effect increases in magnitude by $429798s1% with every crossing.", ua = "Перетинаючи нитки $@spellname418423, Вартовий Циклу розсіює енергію життя, завдаючи $s1 шкоди від сил природи всім гравцям. Сила цього ефекту зростає на $429798s1% з кожним перетином." },
    { en = "Nymue blasts their primary target with a woven beam inflicting $425038s1 Physical damage and $425039s1 Nature damage.", ua = "Німуе вражає свою основну ціль витканим променем, завдаючи $425038s1 фізичної шкоди та $425039s1 шкоди від сил природи." },
    { en = "Nymue conjures verdant shards that fall from above several players, inflicting $s1 Nature damage every $420907t1 sec for $420907d.", ua = "Німуе викликає зелені скалки, що падають згори на кількох гравців, завдаючи $s1 від сил природи щожно $420907t1 сек. протягом $420907d." },
    { en = "The Cycle Warden slams the ground, inflicting $s2 Nature damage to players in a frontal cone.", ua = "Вартовий Циклу б'є об землю, завдаючи $s2 шкоди від сил природи гравцям у фронтальному конусі." },
    { en = "The Manifested Dream gathers energy over $428543s2 sec then snaps all players out of the Dream, inflicting $s1 Nature damage.", ua = "Втілений Сон збирає енергію протягом $428543s2 сек, а потім різко висмикує всіх гравців зі Сну, завдаючи $s1 шкоди від сил природи." },
    { en = "The Manifested Dream blasts energy in several directions inflicting $423994s1 Nature damage to players in a cone.", ua = "Втілений Сон вивергає енергію в кількох напрямках, завдаючи $423994s1 шкоди від сил природи гравцям у конусі." },
    { en = "The victim is vulnerable to the damage of $@spellname428474 for $d.  All $@spellname428474 damage is increased by $s1% per application.", ua = "Жертва вразлива до шкоди від $@spellname428474 протягом $d. Уся шкода від $@spellname428474 збільшується на $s1% за кожне накладання." },
    { en = "The Cycle Wardens' abundant life energy shields Nymue, reducing damage taken by $s1%.", ua = "Рясна енергія життя Вартових Циклу захищає Німуе, зменшуючи отримувану шкоду на $s1%." },
    { en = "Barrier Blossoms forcefully expel players who approach them, inflicting $s1 Nature damage and knocking them away.", ua = "Квіти-Бар'єри силоміць відкидають гравців, що до них наближаються, завдаючи $s1 шкоди від сил природи й відштовхуючи їх." },
    { en = "Nymue incubates an explosive seed in a target.\n\n\n\nAfter a short delay the seed detonates granting the target $@spellname423195 and inflicting $427721s1 Nature damage every $427721t1 sec for $427721d to players within $427721A1 yards.", ua = "Німуе вирощує в цілі вибухову насінину.\n\n\n\nПісля короткої затримки насінина вибухає, даруючи цілі $@spellname423195 і завдаючи $427721s1 шкоди від сил природи кожні $427721t1 сек протягом $427721d гравцям у межах $427721A1 м." },
    { en = "Nymue conjures a magical loom that weaves threads of energy into complex patterns.\n\n\n\nThese threads slowly move outward from Nymue, stunning players on contact and inflicting $s1 Nature damage every $t1 sec for $d.", ua = "Німуе прикликає чарівний ткацький верстат, що тче нитки енергії у складні візерунки.\n\n\n\nЦі нитки повільно віддаляються від Німуе, приголомшуючи гравців при дотику й завдаючи $s1 шкоди від сил природи кожні $t1 сек протягом $d." },
    { en = "Nymue causes Ephemeral Flora to burst from the ground at a location. After $430533d, the Flora's short existence comes to a spectacular end, inflicting $s1 Nature damage to all players every $t1 sec for $d.\n\n\n\nPlayers who stand in the Flora stifle it, reducing its life force by ${$430533s1*0.1}.2% every ${$430533s2*0.1}.2 sec that they do so.", ua = "Німуе змушує Ефемерну Флору вирватися із землі в певному місці. За $430533d коротке існування Флори добігає видовищного кінця, завдаючи $s1 шкоди від сил природи всім гравцям кожні $t1 сек протягом $d.\n\n\n\nГравці, що стають у Флорі, придушують її, зменшуючи її життєву силу на ${$430533s1*0.1}.2% за кожні ${$430533s2*0.1}.2 сек, поки вони це роблять." },
    { en = "Upon reaching 100% energy Nymue releases an overwhelming surge of life energy, inflicting $426775s1 Nature damage to players within $426775A1 yards and granting them $@spellname423195.\n\n\n\nThe surge then flows outwards, coalescing into $s1 powerful Cycle Wardens.", ua = "Сягнувши 100% енергії, Німуе вивільняє нездоланний приплив енергії життя, завдаючи $426775s1 шкоди від сил природи гравцям у межах $426775A1 м і даруючи їм $@spellname423195.\n\n\n\nПотім приплив розливається назовні, зливаючись у $s1 могутніх Вартових Циклу." },
    { en = "Swirling verdant energy surrounds the Manifested Dream, inflicting $428474s1 Nature damage every $428474t1 sec to players within $s1 yards and marks them with $@spellname428479. \n\n\n\nPlayers outside of the miasma have their visibility of the Manifested Dream obscured.", ua = "Вируюча зелена енергія оточує Втілений Сон, завдаючи $428474s1 шкоди від сил природи кожні $428474t1 сек гравцям у межах $s1 м і позначаючи їх ефектом $@spellname428479.\n\n\n\nГравцям поза міазмою бачення Втіленого Сну затьмарюється." },
    { en = "Nymue alters the $@spellname413587 over $421473d inflicting $423670s1 Nature damage every $421473t1 sec.", ua = "Німуе змінює $@spellname413587 протягом $421473d, завдаючи $423670s1 шкоди від сил природи кожні $421473t1 сек." },
    { en = "Increases Nature damage taken by $s1% for $d. This effect stacks.", ua = "Збільшує отримувану шкоду природою на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Nymue's $@spellname418423 draws upon the dream to weave emerald threads across the battlefield. Crossing these threads inflicts $420554s1 Nature damage every $420554t1 sec for $420554d. This effect stacks.", ua = "$@spellname418423 Німуе черпає силу зі Сну, щоб виткати смарагдові нитки по всьому полю бою. Перетин цих ниток завдає $420554s1 шкоди від сил природи кожні $420554t1 сек упродовж $420554d. Цей ефект накопичується." },
    { en = "Nymue channels their immense power to unmake all players, inflicting $s1 Nature damage every $429655t1 sec, and increasing damage taken from $@spellname421368 by $s2%. This effect stacks.", ua = "Німуе спрямовує свою незмірну силу, щоб знищити всіх гравців, завдаючи $s1 шкоди від сил природи кожні $429655t1 сек і збільшуючи шкоду, отримувану від $@spellname421368, на $s2%. Цей ефект накопичується." },
    { en = "Smolderon slams Emberscar into the ground to feast on branded players' essence, knocking back all players.\n\n\n\nAny player branded with $@spellname421643 additionally releases $@spellname421821s.", ua = "Смолдерон вбиває Емберскар у землю, щоб поглинути сутність позначених гравців, відкидаючи всіх гравців.\n\n\n\nКожен гравець, позначений $@spellname421643, додатково вивільняє $@spellname421821s." },
    { en = "Emberscar brands the player, increasing damage taken from $@spellname421343 by $s1%.\n\n\n\nBeing struck by $@spellname422277 removes the effect.", ua = "Емберскар таврує гравця, збільшуючи шкоду, отримувану від $@spellname421343, на $s1%.\n\n\n\nУдар $@spellname422277 знімає цей ефект." },
    { en = "Emberscar's brand cauterizes the player, causing them to absorb $s1 healing.\n\n\n\nRemoving the absorb creates a $@spellname424233 at the player's location $424255s1 sec later.", ua = "Тавро Емберскару припікає гравця, змушуючи його поглинати $s1 зцілення.\n\n\n\nЗняття поглинання створює $@spellname424233 на місці гравця за $424255s1 сек." },
    { en = "Smolderon channels his blazing soul into Emberscar, periodically causing bursts of fire to engulf portions of the arena. This inflicts $s1 Fire damage and applies $@spellname425574 to all players caught within the blast.", ua = "Смолдерон спрямовує свою палахку душу в Емберскар, періодично спричиняючи спалахи вогню, що поглинають частини арени. Це завдає $s1 вогнем і накладає $@spellname425574 на всіх гравців, заскочених у вибух." },
    { en = "Smoldering ground inflicts $s1 Fire damage every $t1 sec to any player standing within.", ua = "Тліюча земля завдає $s1 шкоди вогнем кожні $t1 сек кожному гравцеві, що стоїть у ній." },
    { en = "Smolderon creates several $@spellname426018s that fixate upon random players. Players who touch a $@spellname426018 become afflicted with $@spellname430325.\n\n\n\nWhen one reaches its target or after $s3 sec, it explodes and inflicts $s1 Fire damage to all players. This explosion causes all players to take $s2% increased damage from $@spellname426018 for $d.", ua = "Смолдерон створює кілька $@spellname426018s, що фіксуються на випадкових гравцях. Гравці, які торкаються $@spellname426018, отримують $@spellname430325.\n\n\n\nКоли вона досягає цілі або через $s3 сек, вона вибухає й завдає $s1 шкоди вогнем усім гравцям. Цей вибух змушує всіх гравців отримувати на $s2% більше шкоди від $@spellname426018 упродовж $d." },
    { en = "Smolderon stomps the ground causing plumes of lava to erupt nearby random players. These $@spellname422691 inflict $422823s1 Fire damage and knock back any players struck.\n\n\n\nWhen the lava settles, a pool of $@spellname421527 is left behind.", ua = "Смолдерон гупає по землі, спричиняючи виверження струменів лави біля випадкових гравців. Ці $@spellname422691 завдають $422823s1 шкоди вогнем і відкидають усіх вражених гравців.\n\n\n\nКоли лава осідає, після неї лишається калюжа $@spellname421527." },
    { en = "A fiery explosion inflicts $s1 Fire damage to all players within $A1 yards.", ua = "Вогняний вибух завдає $s1 шкоди вогнем усім гравцям у радіусі $A1 м." },
    { en = "The searing heat causes the primary target of the brand to explode after $422577d, inflicting $s1 Fire damage to all players. Players farther from the target receive less damage.", ua = "Пекучий жар змушує основну ціль тавра вибухнути за $422577d, завдаючи $s1 вогнем усім гравцям. Гравці, дальші від цілі, отримують менше шкоди." },
    { en = "Smolderon sets his soul ablaze, increasing the frequency $@spellname420950 occurs from every $417039t1 sec to $s1 sec$?diff17|diff14[][ and damage by $s3%] for $s2 sec.", ua = "Смолдерон підпалює свою душу, збільшуючи частоту $@spellname420950 з кожних $417039t1 сек до $s1 сек$?diff17|diff14[][ і шкоду на $s3%] упродовж $s2 сек." },
    { en = "$@spellname421969 inflict $s1 Fire damage and knock back any player they come in contact with.", ua = "$@spellname421969 завдає $s1 вогнем і відкидає будь-якого гравця, з яким стикається." },
    { en = "Smolderon ignites multiple players, causing them to inflict $421515s1 Fire damage every $t1 sec to players within $421515A2 yards for $d.\n\n\n\nUpon expiration, the player explodes inflicting $429280s1 Fire damage to players within $429280A2 yards$?diff17|diff14[. ][ and expels $@spellname421969.]", ua = "Смолдерон запалює кількох гравців, змушуючи їх завдавати $421515s1 шкоди вогнем кожні $t1 сек гравцям у радіусі $421515A2 м упродовж $d.\n\n\n\nПісля завершення гравець вибухає, завдаючи $429280s1 шкоди вогнем гравцям у радіусі $429280A2 м$?diff17|diff14[. ][ і викидає $@spellname421969.]" },
    { en = "Smolderon's body incinerates the air, inflicting $420950s1 Fire damage to all players every $s1 sec.", ua = "Тіло Смолдерона спопеляє повітря, завдаючи $420950s1 вогнем усім гравцям щожно $s1 сек." },
    { en = "Upon reaching 100 energy Smolderon ignites into flames, increasing his damage done by $s1%. This effect stacks.\n\n\n\nAfter Heating Up $422172s1 times, Smolderon gains the ability to cast $@spellname426725.", ua = "Досягнувши 100 енергії, Смолдерон спалахує полум'ям, збільшуючи завдавану ним шкоду на $s1%. Цей ефект накопичується.\n\n\n\nПісля $422172s1 розпалювань Смолдерон отримує здатність творити $@spellname426725." },
    { en = "Smolderon decimates his primary target, inflicting $s1 Physical damage$?diff17|diff14[.][ and afflicting them with $@spellname422577.] An additional $421450s1 Fire damage is split evenly among all players within $421450A1 yards of the primary target.\n\n\n\nAll players hit by the effect are branded and afflicted with $@spellname421656.$?diff17[][\n\n\n\nIf $@spellname427969 fails to hit at least $421450s3 players, $428036s1 Fire damage is inflicted to all players and Smolderon gains a stack of $@spellname423896.]", ua = "Смолдерон винищує свою основну ціль, завдаючи $s1 фізичної шкоди$?diff17|diff14[.][ і накладаючи $@spellname422577.] Додаткові $421450s1 шкоди вогнем рівномірно розподіляються між усіма гравцями в радіусі $421450A1 м від основної цілі.\n\n\n\nУсі гравці, вражені цим ефектом, тавруються й отримують $@spellname421656.$?diff17[][\n\n\n\nЯкщо $@spellname427969 не влучає принаймні в $421450s3 гравців, усім гравцям завдається $428036s1 шкоди вогнем, а Смолдерон отримує заряд $@spellname423896.]" },
    { en = "$@spellname423904s drift towards Smolderon when created. Collecting a $@spellname423904 inflicts $s1 Fire damage and applies $@spellname421858 to the player.\n\n\n\nEach $@spellname423904 that reaches Smolderon increases his damage done by $421859s1%.", ua = "$@spellname423904s дрейфують до Смолдерона після створення. Збирання $@spellname423904 завдає $s1 шкоди вогнем і накладає $@spellname421858 на гравця.\n\n\n\nКожна $@spellname423904, що досягає Смолдерона, збільшує завдану ним шкоду на $421859s1%." },
    { en = "Players can collect $@spellname423904s to increase their damage done by $s1% and healing done by $s2% for $d. This effect stacks, but collecting additional flames does not extend the duration.", ua = "Гравці можуть збирати $@spellname423904s, щоб збільшити завдавану ними шкоду на $s1% і зцілення на $s2% упродовж $d. Цей ефект накопичується, але збір додаткових вогнів не подовжує тривалість." },
    { en = "Smolderon combusts, continuously casting $@spellname422243 until all players succumb to their demise.", ua = "Смолдерон спалахує, безперервно творячи $@spellname422243, доки всі гравці не загинуть." },
    { en = "$@spellname422172' bursts sear the player, inflicting $425575s1 Fire damage every $t1 sec over $d. This effect stacks.", ua = "Спалахи $@spellname422172' обпікають гравця, завдаючи $425575s1 шкоди вогнем кожні $t1 сек упродовж $d. Цей ефект накопичується." },
    { en = "The $@spellname426018 ignites the player, inflicting $s1 Fire damage every $t1 sec for $d.", ua = "$@spellname426018 запалює гравця, завдаючи $s1 шкоди вогнем кожні $t1 сек упродовж $d." },
    { en = "Tindral surrounds random players with suppressive ember, absorbing the next $s1 healing. This effect stacks.", ua = "Тіндрал оточує випадкових гравців гнітючим жаром, поглинаючи наступні $s1 зцілення. Цей ефект накопичується." },
    { en = "Tindral violently flaps his wings, pushing back all players. After 2.5 sec, a typhoon erupts, inflicting $s1 Nature damage to all players.", ua = "Тіндрал шалено махає крилами, відкидаючи всіх гравців. Через 2.5 сек здіймається тайфун, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Tindral causes flames to grow inside random players, inflicting $427339s1 Fire damage every $t1 sec for $d.$?diff17[]$?diff14|diff16|diff15[\n\n\n\nThe flames erupt from players when Fiery Growth is removed]$?diff14|diff15[ and leave behind $@spellname424499 at current player's location.][]$?diff16[, afflicting players with $@spellname424582 and leave behind $@spellname424499 at the current player's location.][]", ua = "Тіндрал вирощує полум'я всередині випадкових гравців, завдаючи $427339s1 шкоди вогнем кожні $t1 сек упродовж $d.$?diff17[]$?diff14|diff16|diff15[\n\n\n\nПолум'я вибухає з гравців, коли Полум'яне Зростання знімається]$?diff14|diff15[ і лишає $@spellname424499 на поточному місці гравця.][]$?diff16[, накладаючи $@spellname424582 на гравців і лишаючи $@spellname424499 на поточному місці гравця.][]" },
    { en = "Cinders from $@spellname424581's explosion linger on all players, inflicting $s1 Fire damage every $t1 sec for $d. This effect stacks.\n\n\n\nEach additional stack of $@spellname424582 increases its damage by $s2%.", ua = "Попіл від вибуху $@spellname424581 затримується на всіх гравцях, завдаючи $s1 шкоди вогнем кожні $t1 сек упродовж $d. Цей ефект накопичується.\n\n\n\nКожен додатковий заряд $@spellname424582 збільшує його шкоду на $s2%." },
    { en = "$@spellname425602s fall from the sky, inflicting $s1 Fire damage to all players when they reach the platform.\n\n\n\nA player flying through a $@spellname425602 on a dragonriding mount absorbs the flare, inflicting $425607s1 Fire damage and increasing their damage taken from $@spellname425602 by $425652s1% for $425652d. Also grants player $@spellname425606 for $425606d.", ua = "$@spellname425602s падають з неба, завдаючи $s1 вогнем усім гравцям, коли сягають платформи.\n\n\n\nГравець, що пролітає крізь $@spellname425602 на драконоїздовій їздовій тварині, поглинає спалах, отримуючи $425607s1 вогнем і збільшуючи свою отриману шкоду від $@spellname425602 на $425652s1% протягом $425652d. Також надає гравцеві $@spellname425606 на $425606d." },
    { en = "Fire explodes from player's location when they land, dismounting them. This explosion hits within 10 yards and can strike Tindral Sageswift, Fiery Vines and Scorched Treants, inflicting $s1 Fire damage.", ua = "Коли гравець приземляється, на його місці вибухає вогонь, скидаючи його з їздової тварини. Цей вибух вражає в радіусі 10 м і може зачепити Тіндрала Сейджсвіфта, полум'яні лози та обвуглені тренти, завдаючи $s1 шкоди вогнем." },
    { en = "Tindral brings down a falling star towards the platform, inflicting $423853s1 Astral damage to all players and leaving behind $@spellname422503.", ua = "Тіндрал скидає падучу зорю на платформу, завдаючи $423853s1 астральної шкоди всім гравцям і лишаючи $@spellname422503." },
    { en = "A quick beam of solar light burns players for $s1 Fire damage.", ua = "Швидкий промінь сонячного світла обпалює гравців, завдаючи $s1 шкоди вогнем." },
    { en = "Tindral blasts the platform with fire beams, inflicting $423656s1 Fire damage to players within $423656a1 yards of the impact. This impact creates serveral moving beams which inflict $s1 Fire damage to players within them every $428886t1 sec.", ua = "Тіндрал обстрілює платформу променями вогню, завдаючи $423656s1 вогнем гравцям у межах $423656a1 ярдів від влучання. Це влучання створює кілька рухомих променів, що завдають $s1 вогнем гравцям усередині них щожно $428886t1 сек." },
    { en = "Tindral blasts players on the edge of the platform with $@spellname427297, inflicting $427311s1 Fire damage every $t1 sec.", ua = "Тіндрал обстрілює гравців на краю платформи $@spellname427297, завдаючи $427311s1 вогнем щожно $t1 сек." },
    { en = "Searing heat radiates from the Scorched Treant, inflicting $429742s1 Fire damage every $t1 sec to all players.", ua = "Пекучий жар випромінюється від обвугленого трента, завдаючи $429742s1 шкоди вогнем кожні $t1 сек усім гравцям." },
    { en = "Tindral creates Poisonous Mushrooms and Blazing Mushrooms around himself every $s1 sec for $s2 sec.", ua = "Тіндрал створює навколо себе Отруйні Гриби та Палаючі Гриби кожні $s1 сек упродовж $s2 сек." },
    { en = "Tindral targets all players with fiery vines that erupt after $d, rooting the targeted player and also inflicting $424498s1 Fire damage to players within $424498a1 yards. These roots inflict $424497s1 Fire damage every $424497t1 sec until they are destroyed.", ua = "Тіндрал націлює на всіх гравців полум'яні лози, що вибухають через $d, знерухомлюючи позначеного гравця, а також завдаючи $424498s1 шкоди вогнем гравцям у радіусі $424498a1 м. Ці лози завдають $424497s1 шкоди вогнем кожні $424497t1 сек, доки їх не знищать." },
    { en = "Scorching Ground inflicts $425451s1 Fire damage every $t1 sec to players within.", ua = "Обпалена земля завдає $425451s1 шкоди вогнем кожні $t1 сек гравцям усередині." },
    { en = "Scorching plumes inflict $s1 Fire damage and remove $s3 Skyriding Charges from players that come into contact with it.", ua = "Пекучі струмені завдають $s1 шкоди вогнем і забирають $s3 заряди Небесної Їзди в гравців, що торкаються їх." },
    { en = "$@spellname422324s sprout forth from $@spellname424665 after $422426d, inflicting $422325s1 Fire damage to players every $s1 sec$?diff15|diff16[.][ for $d.]", ua = "$@spellname422324s проростає з $@spellname424665 за $422426d, завдаючи $422325s1 вогнем гравцям щожно $s1 сек.$?diff15|diff16[.][ протягом $d.]" },
    { en = "Tindral's Owl form leaves behind $@spellname425657, allowing players to dragonride within The Blessed Boughs for $d.", ua = "Совина подоба Тіндрала лишає $@spellname425657, дозволяючи гравцям літати на драконі в межах Благословенних Гілок упродовж $d." },
    { en = "Tindral creates Poisonous Mushrooms around himself every $426669s1 sec for $426669s2 sec. Each mushroom erupts after $426670d, inflicting $426690s1 Physical damage and $426687s1 Nature damage to players within the area and increases their damage taken from Poisonous Mushrooms by $426686s1% for $426686d.\n\n\n\nIf $@spellname426690 fails to hit a player, inflicts $426691s1 Nature damage every $426691t1 sec for $426691d to all players.", ua = "Тіндрал створює навколо себе Отруйні Гриби кожні $426669s1 с протягом $426669s2 с. Кожен гриб вибухає за $426670d, завдаючи $426690s1 фізичної шкоди та $426687s1 шкоди від природи гравцям у зоні дії та збільшуючи шкоду, яку вони отримують від Отруйних Грибів, на $426686s1% протягом $426686d.\n\n\n\nЯкщо $@spellname426690 не влучає в гравця, завдає $426691s1 шкоди від природи кожні $426691t1 с протягом $426691d усім гравцям." },
    { en = "Any player flying through the essence of the Emerald Dream empowers all players, increasing their damage done by $s1% and increasing their healing and absorb effects done by $s4%. This effect stacks and lasts until $@spellname424140 finishes casting or is interrupted.\n\n\n\nThe consumed essence leaves behind $@spellname421884.", ua = "Будь-який гравець, що пролітає крізь сутність Смарагдового Сну, наснажує всіх гравців, збільшуючи завдавану ними шкоду на $s1% і ефекти зцілення та поглинання на $s4%. Цей ефект накопичується й триває, доки $@spellname424140 не завершить творитися або не буде перерване.\n\n\n\nСпожита сутність лишає $@spellname421884." },
    { en = "Tindral shields himself for $q1% of his maximum health and summons a dying star, inflicting $429162s1 Fire damage to all players every $t1 sec$?diff16[ and afflicting them with $@spellname429166 for $429166d.]$?diff14|diff17|diff15[.]\n\n\n\nThe star explodes after $d, inflicting $429164s1 Fire damage to all players. This spell is interrupted if Tindral's shield is broken.", ua = "Тіндрал захищає себе щитом на $q1% свого максимального здоров'я й прикликає вмирущу зорю, завдаючи $429162s1 шкоди вогнем усім гравцям кожні $t1 сек$?diff16[ і накладаючи $@spellname429166 упродовж $429166d.]$?diff14|diff17|diff15[.]\n\n\n\nЗоря вибухає через $d, завдаючи $429164s1 шкоди вогнем усім гравцям. Це закляття переривається, якщо щит Тіндрала розбито." },
    { en = "Seeds of Flame, unless crushed by a player, grow into a $@spellname422324 after $?diff14|diff15|diff17[$422426d.][$430582d.]\n\n\n\nWhen a player steps on a $@spellname424665, it is destroyed. The players suffers $s1 Fire damage. $?diff14|diff17|dff16[][This effect increases damage taken from $@spellname424665 by $s2% for $d and stacks.]", ua = "Насінини Полум'я, якщо їх не розчавить гравець, виростають у $@spellname422324 через $?diff14|diff15|diff17[$422426d.][$430582d.]\n\n\n\nКоли гравець наступає на $@spellname424665, вона знищується. Гравець зазнає $s1 шкоди вогнем. $?diff14|diff17|dff16[][Цей ефект збільшує шкоду, отримувану від $@spellname424665, на $s2% упродовж $d і накопичується.]" },
    { en = "Tindral creates Blazing Mushrooms around himself every $s1 sec for $s2 sec. Each mushroom erupts after $424576d, inflicting $424577s1 Physical damage and $423264s1 Fire damage to players within the area and increases their damage taken from Blazing Mushrooms by $424578s1% for $424578d.\n\n\n\nIf $@spellname423260 fails to hit a player, inflicts $424662s1 Fire damage to all players.", ua = "Тіндрал створює навколо себе Палаючі Гриби кожні $s1 сек упродовж $s2 сек. Кожен гриб вибухає через $424576d, завдаючи $424577s1 фізичної шкоди та $423264s1 шкоди вогнем гравцям у зоні й збільшуючи шкоду, отримувану ними від Палаючих Грибів, на $424578s1% упродовж $424578d.\n\n\n\nЯкщо $@spellname423260 не влучає в гравця, він завдає $424662s1 шкоди вогнем усім гравцям." },
    { en = "Tindral unleashes Seeds of Flame around himself and sets the platform ablaze, inflicting $423266s1 Fire damage to players every $t1 sec for $d.", ua = "Тіндрал вивільняє навколо себе Насінини Полум'я й підпалює платформу, завдаючи $423266s1 шкоди вогнем гравцям кожні $t1 сек упродовж $d." },
    { en = "Tindral shapeshifts into a flaming owl.", ua = "Тіндрал перетворюється на полум'яну сову." },
    { en = "Fragments of the falling star explode, inflicting $s1 Astral damage to players within $a1 yards of impact.", ua = "Уламки падаючої зорі вибухають, завдаючи $s1 шкоди від астральних сил гравцям у радіусі $a1 ярдів від місця удару." },
    { en = "$@spellname422509 falls from Tindral's Owl form, allowing players to dragonride within The Blessed Boughs.", ua = "$@spellname422509 падає з Тіндралової совиної подоби, дозволяючи гравцям літати верхи на драконі в межах Благословенних Гілок." },
    { en = "Astral heat surrounds the player, increasing their damage taken from $@spellname424140 by $s1%. This effect stacks.", ua = "Астральний жар огортає гравця, збільшуючи отримувану ним шкоду від $@spellname424140 на $s1%. Цей ефект накопичується." },
    { en = "Tindral's melee attacks sears the target, inflicting $s1 Fire damage every $t1 sec for $d. This effect stacks.", ua = "Атаки ближнього бою Тіндрала обпалюють ціль, завдаючи $s1 шкоди вогнем кожні $t1 с протягом $d. Цей ефект накопичується." },
    { en = "Tindral summons a dying star, inflicting $429170s1 Fire damage to all players every $t1 sec$?diff16[ and afflicting them with $@spellname429166 for $429166d.]$?diff14|diff17|diff15[.]\n\n\n\nThe star explodes after $d, inflicting $429171s1 Fire damage to all players.", ua = "Тіндрал прикликає вмираючу зорю, що завдає $429170s1 шкоди вогнем усім гравцям кожні $t1 с$?diff16[ і накладає на них $@spellname429166 на $429166d.]$?diff14|diff17|diff15[.]\n\n\n\nЗоря вибухає за $d, завдаючи $429171s1 шкоди вогнем усім гравцям." },
    { en = "Remnant energy of the destroyed $@spellname424665 envelops the player, preventing them from destroying other Seeds of Flame.", ua = "Залишкова енергія знищеної $@spellname424665 огортає гравця, не даючи йому знищувати інші Насінини Полум'я." },
    { en = "Seeds of Flame, unless crushed by a player, grow into a $@spellname422324 after $430582d.\n\n\n\nWhen a player steps on a $@spellname424665, it is destroyed. The players suffers $s1 Fire damage and is afflicted with $@spellname430583 for $430583d.", ua = "Насінини Полум'я, якщо їх не розчавить гравець, проростають у $@spellname422324 за $430582d.\n\n\n\nКоли гравець наступає на $@spellname424665, вона знищується. Гравець зазнає $s1 шкоди вогнем і опиняється під дією $@spellname430583 на $430583d." },
    { en = "Emerald winds propel the player forward for $d, granting $s3 Skyriding Charge.", ua = "Смарагдові вітри несуть гравця вперед протягом $d, надаючи $s3 Заряду Небесної Їзди." },
    { en = "The Darkflame Shade leaps towards its target, inflicting $426373s1 Shadowflame damage split evenly among players within $426373a1 yards and increasing damage taken by $@spellname426368 by $426392s1% for $426392d.\n\n\n\nLeaves behind $@spellname419066.", ua = "Тіньовополум'яний Привид стрибає до своєї цілі, завдаючи $426373s1 шкоди тіньовим полум'ям, розподіленої порівну між гравцями в радіусі $426373a1 ярдів, і збільшуючи отримувану від $@spellname426368 шкоду на $426392s1% протягом $426392d.\n\n\n\nЗалишає по собі $@spellname419066." },
    { en = "A fireball erupts from Fyr'alath, inflicting $s1 Shadowflame damage to enemies in its path.", ua = "З Файр'алата вихоплюється вогняна куля, завдаючи $s1 шкоди тіньовим полум'ям ворогам на своєму шляху." },
    { en = "The Roots of Amirdrassil nurture the world tree with the energy of the Emerald Dream. If $@spellname419066 reach the roots, $@spellname421741.", ua = "Корені Амірдрассілу живлять світове дерево енергією Смарагдового Сну. Якщо $@spellname419066 досягають коренів, $@spellname421741." },
    { en = "The burning rift inflicts $s1 Shadowflame damage every $t1 sec to players within it.", ua = "Палаючий розлом завдає $s1 шкоди тіньовим полум'ям кожні $t1 с гравцям усередині нього." },
    { en = "Escaping flames inflict $426375s1 Shadowflame damage to players caught in their wake.", ua = "Вируючі полум'я завдають $426375s1 шкоди тіньовим полум'ям гравцям, що потрапили в їхній слід." },
    { en = "Fyrakk radiates a searing heat, inflicting $418978s1 Shadowflame damage to all players every $t sec.\n\n\n\nPeriodically sets targets $@spellname417807.", ua = "Фіракк випромінює пекучий жар, завдаючи $418978s1 шкоди тіньовим полум'ям усім гравцям кожні $t с.\n\n\n\nПеріодично накладає на цілі $@spellname417807." },
    { en = "Fyrakk sets players $@spellname417807, inflicting $s2 Shadowflame damage every $t2 sec and growing in intensity over time. This effect stacks.", ua = "Фіракк накладає на гравців $@spellname417807, завдаючи $s2 шкоди тіньовим полум'ям кожні $t2 с і посилюючись із часом. Цей ефект накопичується." },
    { en = "Injured $@spellname422032 periodically emerge from the heart of Amirdrassil in the tree's darkest hour.\n\n\n\nUpon reaching the heart of Amirdrassil, each spirit transfers its remaining health to the world tree.", ua = "Поранені $@spellname422032 час від часу з'являються із серця Амірдрассілу в найтемнішу для дерева годину.\n\n\n\nДосягнувши серця Амірдрассілу, кожен дух передає рештки свого здоров'я світовому дереву." },
    { en = "Fyrakk devours his current target, inflicting $s1 Physical damage and an additional $429672s1 Shadowflame damage every $425494t1 sec. This effect stacks.", ua = "Фіракк пожирає свою поточну ціль, завдаючи $s1 фізичної шкоди та додатково $429672s1 шкоди тіньовим полум'ям кожні $425494t1 с. Цей ефект накопичується." },
    { en = "Fyrakk slashes his current target, inflicting $417446s1 Physical damage and $417445s1 Shadowflame damage. The target is branded with the $@spellname417443 for $417443d.\n\n\n\nSends forth $@spellname425345.", ua = "Фіракк шматує свою поточну ціль, завдаючи $417446s1 фізичної шкоди та $417445s1 шкоди тіньовим полум'ям. Ціль таврується $@spellname417443 на $417443d.\n\n\n\nВисилає $@spellname425345." },
    { en = "Fyrakk permanently darkens the sky, periodically calling burning meteors down upon players. Each meteor inflicts $429782s1 Shadowflame damage to players within $429782a1 yards of the impact location and creates a $@spellname425530.\n\n\n\nShards of each meteor also impact Amirdrassil, inflicting $419061s1 Shadowflame damage to players within $419061a1 yards of the impact locations.", ua = "Фіракк назавжди затьмарює небо, періодично прикликаючи на гравців палаючі метеори. Кожен метеор завдає $429782s1 шкоди тіньовим полум'ям гравцям у радіусі $429782a1 ярдів від місця удару й створює $@spellname425530.\n\n\n\nОскалки кожного метеора також влучають в Амірдрассіл, завдаючи $419061s1 шкоди тіньовим полум'ям гравцям у радіусі $419061a1 ярдів від місць удару." },
    { en = "Fyrakk summons burning shades from within the $@spellname419066.", ua = "Фіракк прикликає палаючих привидів із $@spellname419066." },
    { en = "A fireball erupts from the Darkflame Shade, inflicting $429014s1 Shadowflame damage to enemies in its path.", ua = "З Тіньовополум'яного Привида вихоплюється вогняна куля, завдаючи $429014s1 шкоди тіньовим полум'ям ворогам на своєму шляху." },
    { en = "Fyrakk's melee attacks with Fyr'alath inflict $417630s1 Shadowflame damage to those who wear the mark. This effect stacks.", ua = "Фіраккові ближні атаки Файр'алатом завдають $417630s1 шкоди тіньовим полум'ям тим, хто носить тавро. Цей ефект накопичується." },
    { en = "The Burning Colossus smashes its fist into its current target, inflicting $428962s1 Physical damage and $428964s1 Shadowflame damage.", ua = "Палаючий Колос врізає кулаком по своїй поточній цілі, завдаючи $428962s1 фізичної шкоди та $428964s1 шкоди тіньовим полум'ям." },
    { en = "The Dark Colossus smashes its fist into its current target, inflicting $428966s1 Physical damage and $428967s1 Shadowflame damage.", ua = "Темний Колос врізає кулаком по своїй поточній цілі, завдаючи $428966s1 фізичної шкоди та $428967s1 шкоди тіньовим полум'ям." },
    { en = "The seed blooms into a flower, instantly granting players within $423714s1 yards a shield that absorbs the next $s1 incoming damage for $d.", ua = "Насінина розквітає у квітку, миттєво надаючи гравцям у радіусі $423714s1 ярдів щит, що поглинає наступні $s1 одиниць вхідної шкоди протягом $d." },
    { en = "The Dark Colossus shrouds several players in shadows that erupt after $428970d, inflicting $429946s1 Shadow damage to players within $429946a1 yards.\n\n\n\nPlayers within the eruption are stunned and suffer $428969s2 Shadow damage every $428969t2 sec.", ua = "Темний Колос огортає кількох гравців тінями, які вивергаються за $428970d, завдаючи $429946s1 шкоди від тіні гравцям у радіусі $429946a1 ярдів.\n\n\n\nГравці в зоні виверження приголомшуються й зазнають $428969s2 шкоди від тіні кожні $428969t2 с." },
    { en = "Fyrakk devours a shadowflame orb, inflicting $s1 Shadowflame damage to all players and an additional $s2 Shadowflame damage every $t2 sec for $d. This effect stacks.", ua = "Фіракк пожирає кулю тіньового полум'я, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям і додатково $s2 шкоди тіньовим полум'ям кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "The Burning Colossus wreathes several players in flames that erupt after $428988d, inflicting $428991s1 Fire damage to players within $s1 yards.\n\n\n\nShatters $@spellname428968s.", ua = "Палаючий Колос огортає кількох гравців полум'ям, яке вивергається за $428988d, завдаючи $428991s1 шкоди вогнем гравцям у радіусі $s1 ярдів.\n\n\n\nРуйнує $@spellname428968s." },
    { en = "The blazing seed pulses with flame, inflicting $423720s1 Shadowflame damage to all players every $t1 sec for $d.", ua = "Палаюча насінина пульсує полум'ям, завдаючи $423720s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 с протягом $d." },
    { en = "Fyrakk rends the fabric of the Emerald Dream, inflicting $425481s1 Fire damage to all players and opening up a rift into the Firelands.\n\n\n\nSearing heat pours through the rift, inflicting $419217s1 Fire damage to all players every $s1 sec for $420644d and pulling players towards its location. Players farther from the rift receive less damage.\n\n\n\nPlayers drawn beneath the rift are $@spellname425483.", ua = "Фіракк роздирає тканину Смарагдового Сну, завдаючи $425481s1 шкоди вогнем усім гравцям і відкриваючи розлом до Вогняних Земель.\n\n\n\nКрізь розлом ллється пекучий жар, завдаючи $419217s1 шкоди вогнем усім гравцям кожні $s1 с протягом $420644d і притягуючи гравців до свого розташування. Гравці, дальші від розлому, отримують менше шкоди.\n\n\n\nГравці, затягнуті під розлом, опиняються під дією $@spellname425483." },
    { en = "Fyrakk draws shadowflame orbs from the $@spellname419066. The orbs move towards Fyrakk and erupt when touched, inflicting $421942s1 Shadowflame damage.\n\n\n\nFyrakk devours orbs within reach, causing a $@spellname429866.", ua = "Фіракк витягує кулі тіньового полум'я з $@spellname419066. Кулі рухаються до Фіракка й вибухають при дотику, завдаючи $421942s1 шкоди тіньовим полум'ям.\n\n\n\nФіракк пожирає кулі, що в межах досяжності, спричиняючи $@spellname429866." },
    { en = "Fyrakk calls burning meteors down upon players, inflicting $420313s1 Shadowflame damage to players within $420313a1 yards$?diff17 []$?diff14|diff15|diff16 [ and creating $@spellname419066 upon impact].\n\n\n\nShards of each meteor also impact Amirdrassil, inflicting $419061s1 Shadowflame damage to players within $419061a1 yards of the impact locations.", ua = "Фіракк прикликає на гравців палаючі метеори, завдаючи $420313s1 шкоди тіньовим полум'ям гравцям у радіусі $420313a1 ярдів$?diff17 []$?diff14|diff15|diff16 [ і створюючи $@spellname419066 при ударі].\n\n\n\nОскалки кожного метеора також влучають в Амірдрассіл, завдаючи $419061s1 шкоди тіньовим полум'ям гравцям у радіусі $419061a1 ярдів від місць удару." },
    { en = "Fyrakk draws fiery orbs from the $@spellname419066. The orbs move towards Fyrakk and erupt when touched, inflicting $429936s1 Fire damage and applying $@spellname429903.\n\n\n\nFyrakk devours orbs within reach, causing a $@spellname429866.", ua = "Фіракк витягує вогняні кулі з $@spellname419066. Кулі рухаються до Фіракка й вибухають при дотику, завдаючи $429936s1 шкоди вогнем і накладаючи $@spellname429903.\n\n\n\nФіракк пожирає кулі, що в межах досяжності, спричиняючи $@spellname429866." },
    { en = "Fyrakk draws dark orbs from the $@spellname419066. The orbs move towards Fyrakk and erupt when touched, inflicting $429937s1 Shadow damage and applying $@spellname429906.\n\n\n\nFyrakk devours orbs within reach, causing a $@spellname429866.", ua = "Фіракк витягує темні кулі з $@spellname419066. Кулі рухаються до Фіракка й вибухають при дотику, завдаючи $429937s1 шкоди від тіні і накладаючи $@spellname429906.\n\n\n\nФіракк пожирає кулі, що в межах досяжності, спричиняючи $@spellname429866." },
    { en = "Fyrakk's scales radiate a searing heat, inflicting $423705s1 Shadowflame damage to all players every $t sec.", ua = "Фіраккова луска випромінює пекучий жар, завдаючи $423705s1 шкоди тіньовим полум'ям усім гравцям кожні $t с." },
    { en = "Fyrakk plummets from the sky onto Amirdrassil, inflicting $s1 Shadowflame damage to all players upon landing. Players farther from the impact location receive less damage.", ua = "Фіракк рине з неба на Амірдрассіл, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям при приземленні. Гравці, дальші від місця удару, отримують менше шкоди." },
    { en = "$?diff17 [As Amirdrassil begins to bloom, seeds form on its surface. Periodically the seeds surge with power and $@spellname423717.\n\n]$?diff14|diff15|diff16 [As Amirdrassil begins to bloom, seeds form on its surface which can be carried by players.\n\n\n\nPeriodically the seeds surge with power, allowing any player carrying a seed to begin a $@spellname423717.\n\n\n\nSeeds become $@spellname423598s if hit directly by shadowflame.]", ua = "$?diff17 [Коли Амірдрассіл починає квітнути, на його поверхні утворюються насінини. Періодично насінини сповнюються силою і $@spellname423717.\n\n]$?diff14|diff15|diff16 [Коли Амірдрассіл починає квітнути, на його поверхні утворюються насінини, які можуть переносити гравці.\n\n\n\nПеріодично насінини сповнюються силою, дозволяючи будь-якому гравцеві, що несе насінину, розпочати $@spellname423717.\n\n\n\nНасінини стають $@spellname423598s, якщо в них напряму влучає тіньове полум'я.]" },
    { en = "Fyrakk unleashes an incinerating roar, inflicting $422839s1 Shadowflame damage to all players and pushing them away.\n\n\n\nPlayers suffer an additional $422839s2 Shadowflame damage every $422839t2 sec for $422839d.", ua = "Фіракк вивергає спопеляючий рев, завдаючи $422839s1 шкоди тіньовим полум'ям усім гравцям і відкидаючи їх.\n\n\n\nГравці зазнають додатково $422839s2 шкоди тіньовим полум'ям кожні $422839t2 сек упродовж $422839d." },
    { en = "The $@spellname422457 stands at the threshold of corruption. If the world tree loses all its health, $@spellname421741.", ua = "$@spellname422457 стоїть на порозі скверни. Якщо світове дерево втратить усе своє здоров'я, $@spellname421741." },
    { en = "A swirling inferno of flame inflicts $s1 Shadowflame damage and knocks away players caught in its path.", ua = "Вируюче пекло полум'я завдає $s1 шкоди тіньовим полум'ям і відкидає гравців, що опинилися на його шляху." },
    { en = "Fyrakk bites Fyr'alath into the bark of Amirdrassil, inflicting $420422s1 Shadowflame damage to all players.\n\n\n\n$@spellname419066 spread to nearby locations and inflict $429940s1 Shadowflame damage to players within $429940a1 yards of the impact locations.", ua = "Фіракк вгризається Файр'алатом у кору Амірдрассіла, завдаючи $420422s1 шкоди тіньовим полум'ям усім гравцям.\n\n\n\n$@spellname419066 поширюються на сусідні місця й завдають $429940s1 шкоди тіньовим полум'ям гравцям у межах $429940a1 ярдів від місць удару." },
    { en = "Fyrakk begins to corrupt the heart of Amirdrassil with $@spellname410223, converting its lifeforce into a barrier of energy that absorbs damage equal to ${$421922s2/100}.1% of his maximum health.\n\n\n\nFyrakk pulses with shadowflame while the shield holds, inflicting $421923s1 Shadowflame damage to all players every $t1 sec and increasing in intensity over time.\n\n\n\nAfter $d the tree is fully corrupted, and $@spellname421741.", ua = "Фіракк починає опоганювати серце Амірдрассіла за допомогою $@spellname410223, перетворюючи його життєву силу на енергетичний бар'єр, що поглинає шкоду в розмірі ${$421922s2/100}.1% його максимального здоров'я.\n\n\n\nПоки щит тримається, Фіракк пульсує тіньовим полум'ям, завдаючи $421923s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 сек і посилюючись із часом.\n\n\n\nЧерез $d дерево остаточно опоганене, і $@spellname421741." },
    { en = "Upon reaching full life, Spirits of the Kaldorei are protected by a $@spellname422605 that reduces all damage taken by $422605s1%.", ua = "Досягнувши повного здоров'я, духи калдорай захищені $@spellname422605, що зменшує всю отримувану шкоду на $422605s1%." },
    { en = "Fyrakk wreathes the player in flame, increasing their damage taken from $@spellname429875 by $s1% and damage taken from $@spellname429876 by $s2%. This effect stacks.", ua = "Фіракк огортає гравця полум'ям, збільшуючи отримувану ним шкоду від $@spellname429875 на $s1% і шкоду від $@spellname429876 на $s2%. Цей ефект накопичується." },
    { en = "Fyrakk wreathes the player in shadow, increasing their damage taken from $@spellname429876 by $s1% and damage taken from $@spellname429875 by $s2%. This effect stacks.", ua = "Фіракк огортає гравця тінню, збільшуючи отримувану ним шкоду від $@spellname429876 на $s1% і шкоду від $@spellname429875 на $s2%. Цей ефект накопичується." },
    { en = "Fyrakk leaps into the sky above Amirdrassil and descends in dragon form, inflicting $421831s2 Physical damage to all players upon impact and knocking them upward.", ua = "Фіракк стрибає в небо над Амірдрассілом і опускається в драконячій подобі, завдаючи $421831s2 фізичної шкоди всім гравцям при ударі й підкидаючи їх угору." },
    { en = "Holding a $@spellname430048 inflicts $430049s1 Shadowflame damage every $t1 sec for $d. This effect stacks.", ua = "Утримання $@spellname430048 завдає $430049s1 шкоди тіньовим полум'ям кожні $t1 сек упродовж $d. Цей ефект накопичується." },
    { en = "Amirdrassil produces corrupted seeds which apply $@spellname430045 every $t1 sec while held. \n\n\n\nSeeds pulse with flame while unattended, inflicting $430046s1 Shadowflame damage every $430047t1 sec. This effect grows in intensity over time.\n\n\n\nCorrupted seeds become $@spellname423598s if hit directly by shadowflame.", ua = "Амірдрассіл породжує спотворені насінини, які накладають $@spellname430045 кожні $t1 сек, поки їх утримують. \n\n\n\nЗалишені без нагляду насінини пульсують полум'ям, завдаючи $430046s1 шкоди тіньовим полум'ям кожні $430047t1 сек. Цей ефект посилюється з часом.\n\n\n\nСпотворені насінини стають $@spellname423598s, якщо їх безпосередньо вразить тіньове полум'я." },
    { en = "The Screaming Soul unleashes torrid screams, inflicting $430052s1 Shadowflame damage to all players every $t1 sec and increasing its Shadowflame damage done by $430053s2%. This effect stacks.$?diff17 []$?diff14|diff15|diff16 [\n\n\n\nNearby $@spellname422032 despair, becoming Screaming Souls themselves.]", ua = "Волаюча душа вивергає пекучі крики, завдаючи $430052s1 шкоди тіньовим полум'ям усім гравцям кожні $t1 сек і збільшуючи шкоду тіньовим полум'ям, яку вона завдає, на $430053s2%. Цей ефект накопичується.$?diff17 []$?diff14|diff15|diff16 [\n\n\n\nБлизькі $@spellname422032 впадають у відчай, самі стаючи волаючими душами.]" },
    { en = "Fyrakk wreathes players in flames that explode outwards after $s1 sec, inflicting $417789s1 Shadowflame damage to any player caught in the effect.", ua = "Фіракк огортає гравців полум'ям, що вибухає назовні через $s1 сек, завдаючи $417789s1 шкоди тіньовим полум'ям будь-якому гравцю, захопленому ефектом." },
    { en = "Amirdrassil burns, and Fyrakk remakes the world in flame.", ua = "Амірдрассіл палає, і Фіракк перетворює світ на полум'я." },
    { en = "Fyrakk exhales a torrent of flame in front of him, inflicting $410225s1 Shadowflame damage every $t1 sec to players standing within it.", ua = "Фіракк видихає перед собою потік полум'я, завдаючи $410225s1 шкоди тіньовим полум'ям кожні $t1 сек гравцям, що стоять у ньому." },
    { en = "Upon gaining 100 energy the Colossus overheats and explodes, inflicting $s1 Shadowflame damage to all players and an additional $s2 Shadowflame damage every $t2 sec for $d.", ua = "Досягнувши 100 одиниць енергії, колос перегрівається й вибухає, завдаючи $s1 шкоди тіньовим полум'ям усім гравцям і додатково $s2 шкоди тіньовим полум'ям кожні $t2 сек упродовж $d." },
    { en = "The Colossus pulses with dark flames, inflicting $422523s1 Shadowflame damage to enemies within $422523a1 yards every $t1 sec.", ua = "Колос пульсує темним полум'ям, завдаючи $422523s1 шкоди тіньовим полум'ям ворогам у межах $422523a1 ярдів кожні $t1 сек." },
    { en = "Fyrakk calls burning meteors down upon players, inflicting $422522s1 Shadowflame damage to players within $422522a1 yards and creating a $?diff14|diff15|diff17 [Burning ]$?diff16 []Colossus upon impact.\n\n\n\nShards of each meteor also impact Amirdrassil, inflicting $419061s1 Shadowflame damage to players within $419061a1 yards of the impact locations.", ua = "Фіракк скликає палаючі метеори на гравців, завдаючи $422522s1 шкоди тіньовим полум'ям гравцям у межах $422522a1 ярдів і створюючи $?diff14|diff15|diff17 [палаючого ]$?diff16 []колоса при ударі.\n\n\n\nУламки кожного метеора також влучають в Амірдрассіл, завдаючи $419061s1 шкоди тіньовим полум'ям гравцям у межах $419061a1 ярдів від місць удару." },
    { en = "Fyrakk leaps at his current target if not within reach, inflicting a melee attack wtih Fyr'alath.", ua = "Фіракк стрибає до своєї поточної цілі, якщо вона поза досяжністю, завдаючи ближнього удару Файр'алатом." },
    { en = "A raging inferno inflicts $419504s1 Shadowflame damage every $419504t1 sec to players within the area.", ua = "Шалене пекло завдає $419504s1 шкоди тіньовим полум'ям кожні $419504t1 сек гравцям у межах області." },
    { en = "Fyrakk sweeps across Amirdrassil's surface, spewing flames in a line as he travels. Inflicts $422526s1 Shadowflame damage instantly and an additional $429956s1 Shadowflame damage every $429956t1 sec to players in its wake.", ua = "Фіракк проноситься поверхнею Амірдрассіла, вивергаючи полум'я лінією на своєму шляху. Завдає $422526s1 шкоди тіньовим полум'ям миттєво й додатково $429956s1 шкоди тіньовим полум'ям кожні $429956t1 сек гравцям на своєму шляху." },
    { en = "Scorching Roots fixate on random players, pursuing them relentlessly and speed over time.\n\n\n\nWhen killed, they transform into Charred Brambles. $?diff15|diff16 [\n\n\n\nScorched Roots remain untargetable until doused with $@spellname425249.][]", ua = "Палючі Корені зосереджуються на випадкових гравцях, невпинно переслідуючи їх і з часом прискорюючись.\n\n\n\nКоли їх убито, вони перетворюються на Обвуглені Терни. $?diff15|diff16 [\n\n\n\nПалючі Корені лишаються невразливими для прицілювання, доки їх не заллють $@spellname425249.][]" },
    { en = "Renewed Bramble Barriers provide protection against $@spellname417634.\n\n\n\nWhen destroyed, they erupt in $@spellname418535.", ua = "Відновлені Тернові Бар'єри дають захист від $@spellname417634.\n\n\n\nКоли їх знищено, вони вибухають $@spellname418535." },
    { en = "Snakelike flames swirl around the player, inflicting $421228s1 Fire damage to them and radiating $@spellname429153 to nearby players every $s2 sec for $d. The flames tighten over time, increasing their damage as they reduce in area.$?diff14|diff17|diff15 [\n\nUpon expiration, the flames slither to another player.][]$?diff16 [\n\n$@spellname427201 triggers upon expiration.][]", ua = "Зміїсте полум'я в'ється довкола гравця, завдаючи йому $421228s1 одиниць вогняної шкоди й випромінюючи $@spellname429153 на ближніх гравців кожні $s2 с протягом $d. З часом полум'я стискається, посилюючи свою шкоду в міру зменшення площі.$?diff14|diff17|diff15 [\n\nПісля завершення полум'я перебирається до іншого гравця.][]$?diff16 [\n\nПісля завершення спрацьовує $@spellname427201.][]" },
    { en = "Kurog throws chunks of ice at random enemies, inflicting $373004s1 Frost damage divided evenly among players within $373004a1 yards.\n\n\n\nIn addition, this effect applies $@spellname372514.", ua = "Куроґ кидає брили льоду у випадкових ворогів, завдаючи $373004s1 пог. морозом, що порівну розподіляється між гравцями в межах $373004a1 ярдів.\n\n\n\nКрім того, цей ефект накладає $@spellname372514." },
    { en = "Smolderon decimates his primary target, inflicting $s1 Physical damage$?diff17|diff14[.][\n\n and afflicting them with $@spellname422577.] An additional $421450s1 Fire damage is split evenly among all players within $421450A1 yards of the primary target.\n\n\n\nIf \n\n\n\nAll players hit by the effect are branded and afflicted with $@spellname421656.", ua = "Смолдерон нищить свою основну ціль, завдаючи $s1 фізичної шкоди$?diff17|diff14[.][\n\n та накладаючи на неї $@spellname422577.] Додаткові $421450s1 шкоди від вогню рівномірно розподіляються між усіма гравцями в межах $421450A1 ярдів від основної цілі.\n\n\n\nУсі гравці, уражені цим ефектом, затавровані й уражені $@spellname421656." },
    { en = "$?diff15|diff16\n\n[Incur the ire of Diurna's weapon, consuming one charge of Greatstaff's Wrath.][Incur the ire of Diurna's weapon, consuming Greatstaff's Wrath.] The weapon sends a focused beam of storm energy into the ground which pursues the player, inflicting $375883s1 Nature damage to players within $375883A1 yards every half-second during pursuit.", ua = "$?diff15|diff16\n\n[Накликає гнів зброї Діурни, витрачаючи один заряд Гніву Великого Посоха.][Накликає гнів зброї Діурни, витрачаючи Гнів Великого Посоха.] Зброя спрямовує в землю сфокусований промінь штормової енергії, що переслідує гравця, завдаючи $375883s1 пог. природою гравцям у межах $375883A1 ярдів щопівсекунди під час переслідування." },
    { en = "Players encased in ash absorb $s1 healing and are stunned for $D. Releases a $@spellname421469 when removed.", ua = "Гравці, вкриті попелом, поглинають $s1 одиниць зцілення і приголомшені протягом $D. Знятий ефект вивільняє $@spellname421469." },
    { en = "The impact of Embar's $@spellname374043 scorches the ground$?DIFF17|DIFF14[ for $371504d][], inflicting $s1 Fire damage every $t1 sec. to players who stand in the area.\n\n\n\nThe heat dispels $@spellname371836$?DIFF15|DIFF16[ but shrinks $@spellname371514 when $@spellname371836 is dispelled this way][].", ua = "Удар $@spellname374043 від Ембара обпалює землю$?DIFF17|DIFF14[ протягом $371504d][], завдаючи $s1 шкоди Вогнем кожні $t1 сек. гравцям, які стоять у цій зоні.\n\n\n\nЖар розвіює $@spellname371836$?DIFF15|DIFF16[, але зменшує $@spellname371514, коли $@spellname371836 розвіюється в такий спосіб][]." },
    { en = "Embar targets two players and hurls conjured fire axes at them, inflicting $s1 Fire damage split between all targets within $A1 yards$?DIFF15|DIFF16[, increasing damage taken from $@spellname374043 by $375091s1% and inflicting an additional $375091s2 Fire damage every $375091t2 sec. for $375091d][]. Leaves behind $@spellname371514 on impact.\n\n\n\nAny Earthen Pillars in the blast will be destroyed.", ua = "Ембар обирає двох гравців і жбурляє в них викликані вогняні сокири, завдаючи $s1 пог. вогнем, розподілених між усіма цілями в межах $A1 ярдів$?DIFF15|DIFF16[, а також підвищує шкоду, отриману від $@spellname374043, на $375091s1% і завдає додаткові $375091s2 пог. вогнем кожні $375091t2 сек. протягом $375091d][]. У місці влучання лишає $@spellname371514.\n\n\n\nУсі Земляні Стовпи в зоні вибуху буде знищено." },
    { en = "Colliding with the $@spellname410608 inflicts $s1 Arcane damage.", ua = "Зіткнення з $@spellname410608 завдає $s1 арканної шкоди." },
    { en = "The player erupts with a void nova, inflicting $s2% of the total Shadow damage taken from $@spellname408422 to players within $A1 yards as Shadow damage.", ua = "З гравця вивергається нова Порожнечі, завдаючи гравцям у межах $A1 ярдів шкоду тінню в розмірі $s2% від загальної шкоди тінню, якої зазнано від $@spellname408422." },
    { en = "Eranog wreathes his current target in flames. Upon expiration a $@spellname396033 forms at the player's location, inflicting $s1 Fire damage to players within $A1 yards.\n\n\n\nA $@spellname390716 spills forth $@spellname390717, leaving behind a $@spellname370648.", ua = "Ераног огортає свою поточну ціль полум'ям. Після завершення на місці гравця утворюється $@spellname396033, завдаючи $s1 шкоди Вогнем гравцям у радіусі $A1 ярдів.\n\n\n\n$@spellname390716 вивергає $@spellname390717, лишаючи по собі $@spellname370648." },
    { en = "Inflicts $392196s1 Nature damage every $t2 sec.", ua = "Завдає $392196s1 шкоди від сил природи кожні $t2 с." },
    { en = "Increases damage done by $s2% and increases healing and absorbs done by $s4%.", ua = "Збільшує завдавану шкоду на $s2% та збільшує зцілення й поглинання на $s4%." },
    { en = "Afflicted players receive $s1% reduced healing, take $s3% more Physical damage, and bleed for $s2 Physical damage every $t2 sec. \n\n\n\nThis effect stacks, but loses an application every $t2 sec.", ua = "Уражені гравці отримують на $s1% менше зцілення, дістають на $s3% більше фізичної шкоди й кровоточать, втрачаючи $s2 здоров'я від фізичної шкоди кожні $t2 сек.\n\n\n\nЦей ефект накопичується, але втрачає один заряд кожні $t2 сек." },
    { en = "A pool of ichor that inflicts $s1 Shadow damage every $t1 sec to players who stand within it.", ua = "Калюжа сукровиці, що завдає $s1 шкоди від тіні кожні $t1 сек гравцям, які в ній стоять." },
    { en = "The lantern shatters, inflicting $343367s1 Shadow damage to all players and horrifying all players for $s1 sec.\n\n\n\nRavenous Horrors escape the lantern and begin to assault players.", ua = "Ліхтар розбивається, завдаючи $343367s1 шкоди від тіні всім гравцям і сповнюючи їх жахом на $s1 сек.\n\n\n\nЗ ліхтаря вириваються Ненажерливі Жахіття й починають нападати на гравців." },
    { en = "Upon reaching 100 blood Shriekwing fades into the shadows and begins to prowl blindly about The Grand Walk.\n\n\n\nPlayers who come within $339599s1 yards of Shriekwing are murdered.", ua = "Сягнувши 100 крові, Скрикокрил розчиняється в тінях і починає сліпо никати Великим Проходом.\n\n\n\nГравці, що наближаються до Скрикокрила ближче ніж на $339599s1 м, гинуть." },
    { en = "Shriekwing inflicts $s1 Physical damage to all players within $A1 yards.", ua = "Лемкокрил завдає $s1 фізичної шкоди всім гравцям у радіусі $A1 ярдів." },
    { en = "Echoing shrieks inflict $342866s1 Sonic damage upon contact, horrifying the target for $343024d and descending on that location after $342919d.", ua = "Лункий вереск завдає $342866s1 звукової шкоди при контакті, жахаючи ціль на $343024d і обрушуючись на це місце через $342919d." },
    { en = "Shriekwing inflicts $330712s1 Sonic damage to all players within her line of sight and an additional $336005s1 Sonic damage every $330713t1 sec for $330713d. Players also leave behind $@spellname340324 at their location.", ua = "Скрикокрил завдає $330712s1 звукової шкоди всім гравцям у полі свого зору, а також додатково $336005s1 звукової шкоди кожні $330713t1 сек протягом $330713d. Крім того, гравці лишають по собі $@spellname340324 на своєму місці." },
    { en = "The sinister light clings to players, allowing them to see $@spellname329002 and $@spellname342865.\n\n\n\nAffected players suffer $343384s1 Shadow damage every $t1 sec. This effect stacks.", ua = "Зловісне світло чіпляється до гравців, дозволяючи їм бачити $@spellname329002 та $@spellname342865.\n\n\n\nУражені гравці зазнають $343384s1 шкоди від тіні кожні $t1 сек. Цей ефект накопичується." },
    { en = "Shriekwing instantly kills players within $339599s1 yds.", ua = "Скрикокрил миттєво вбиває гравців у радіусі $339599s1 м." },
    { en = "Echoing shrieks inflict $343022s1 Sonic damage upon contact, horrifying for $343024d and causing a $@spellname342923 at that location after $342919d.", ua = "Відлунні зойки завдають $343022s1 звукової шкоди при контакті, жахаючи на $343024d і викликаючи $@spellname342923 у цьому місці через $342919d." },
    { en = "The lantern emanates $@spellname341489 to all players within $s1 yards. Carrying the lantern extends this light to $s2 yards.\n\n\n\nAllowing the lantern to be hit by Descent or Deadly Descent will shatter it, releasing $@spellname343365.", ua = "Ліхтар випромінює $@spellname341489 на всіх гравців у радіусі $s1 м. Якщо нести ліхтар, це світло сягає $s2 м.\n\n\n\nЯкщо дозволити Пікіруванню чи Смертоносному Пікіруванню влучити в ліхтар, він розіб'ється, вивільнивши $@spellname343365." },
    { en = "Shriekwing inflicts $s1 Shadow damage to all enemies and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Скрикокрил завдає $s1 шкоди від тіні всім ворогам, а також додатково $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "Shriekwing inflicts $328887s1 Physical damage and afflicts the target with $s2 applications of $@spellname328897.", ua = "Скрикокрил завдає $328887s1 фізичної шкоди й накладає на ціль $s2 заряд(и/ів) $@spellname328897." },
    { en = "Shriekwing senses a player and descends on their location after $342077d.", ua = "Скрикокрил відчуває гравця й обрушується на його місце за $342077d." },
    { en = "Shriekwing inflicts $s2 Physical damage to players within a $a2 yard frontal cone.", ua = "Скрикокрил завдає $s2 фізичної шкоди гравцям у лобовому конусі радіусом $a2 м." },
    { en = "Hecutis petrifies players, inflicting $334919s1 Nature damage and reducing movement speed by $334919s2% every $t1 sec.\n\n\n\nWhen this effect expires, petrified players shatter inflicting $334889s1 Nature damage to players within $334889a1 yards and create a patch of $@spellname334893 at their location.", ua = "Гекутіс скам'яніває гравців, завдаючи $334919s1 шкоди від сил природи й знижуючи швидкість пересування на $334919s2% кожні $t1 сек.\n\n\n\nКоли цей ефект спливає, скам'янілі гравці розколюються, завдаючи $334889s1 шкоди від сил природи гравцям у радіусі $334889a1 м і створюючи на своєму місці пляму $@spellname334893." },
    { en = "Altimor marks $s1 players and fires at them. Each bolt inflicts $335116s2 Physical damage and an additional $335304s1 Shadow damage every $335304t1 sec for $335304d to the marked player and any players in a line.", ua = "Альтимор позначає $s1 гравця(ів) і стріляє в них. Кожен снаряд завдає $335116s2 фізичної шкоди, а також додатково $335304s1 шкоди від тіні кожні $335304t1 сек протягом $335304d позначеному гравцю та всім гравцям на лінії пострілу." },
    { en = "Hecutis' melee attacks increase his Physical damage done by $s1% and reduce his movement.\n\n\n\nWhile moving, Hecutis sheds stacks of $@spellname334860 and triggers $@spellname334932, inflicting $334932s1 Nature damage to all players.", ua = "Ближні атаки Гекутіса збільшують завдавану ним фізичну шкоду на $s1% і сповільнюють його пересування.\n\n\n\nПід час руху Гекутіс скидає стаки $@spellname334860 і запускає $@spellname334932, завдаючи $334932s1 шкоди Природою всім гравцям." },
    { en = "Hecutis causes players struck by $@spellname335114 to inflict $s1 Nature damage to all players within $a1 yards.", ua = "Гекутіс змушує гравців, уражених $@spellname335114, завдавати $s1 шкоди від сил природи всім гравцям у радіусі $a1 м." },
    { en = "Altimor consumes the player's soul, increasing all damage done by $s1%.", ua = "Альтимор поглинає душу гравця, підвищуючи всю завдавану шкоду на $s1%." },
    { en = "Bargast creates shades of itself that cast $@spellname334708. \n\n\n\nWhile under a loss of control effect Shades of Bargast gain stacks of $@spellname334695, increasing all damage taken by $334695s1%.", ua = "Барґаст створює свої тіні, що творять $@spellname334708.\n\n\n\nПеребуваючи під ефектом втрати контролю, Тіні Барґаста накопичують заряди $@spellname334695, що підвищують усю отримувану шкоду на $334695s1%." },
    { en = "$s1% of damage taken by Altimor and his hunting gargons is additionally taken by the other.", ua = "$s1% шкоди, отриманої Альтимором та його мисливськими гарґонами, додатково отримує інший." },
    { en = "An area of sharp stone erupts from the player, inflicting $s1 Nature damage every $t1 sec and reducing movement speed by $s2% to players standing in the area.", ua = "З-під гравця виривається ділянка гострого каменю, завдаючи $s1 шкоди Природою кожні $t1 с і знижуючи швидкість пересування на $s2% гравцям, що стоять у цій зоні." },
    { en = "Distraught by the loss of his hunting gargons, Altimor takes $s1% increased damage.", ua = "Пригнічений втратою своїх мисливських гарґонів, Альтимор отримує на $s1% більше шкоди." },
    { en = "Bargast causes players struck by $@spellname335114 to summon a Pierced Soul at their location that drifts towards Alitmor. \n\n\n\nThe soul's starting health percentage is proportional to the health percentage of the player after being struck by $@spellname335114.\n\n\n\nIf the soul reaches Altimor, he gains $@spellname334884 for $334884d.", ua = "Барґаст змушує гравців, уражених $@spellname335114, прикликати на своєму місці Пронизану Душу, що дрейфує до Альтимора.\n\n\n\nПочатковий відсоток здоров'я душі пропорційний до відсотка здоров'я гравця після ураження $@spellname335114.\n\n\n\nЯкщо душа сягає Альтимора, він отримує $@spellname334884 на $334884d." },
    { en = "The Ripped Soul inflicts $s1 Shadow damage to all players every $339638t1 sec while it persists.", ua = "Розірвана душа завдає $s1 шкоди Тінню всім гравцям кожні $339638t1 с, доки існує." },
    { en = "Margore empowers $@spellname335114 to inflict $335116s2 Physical damage, divided evenly by all targets struck.", ua = "Марґор підсилює $@spellname335114, що завдає $335116s2 фізичної шкоди, рівномірно розподіленої між усіма враженими цілями." },
    { en = "Altimor fires a cone of bolts at players inflicting $s1 Physical damage.", ua = "Альтимор випускає конус снарядів по гравцях, завдаючи $s1 фізичної шкоди." },
    { en = "Upon reaching 100 energy Shades of Bargast become immune to crowd control and forced movement effects.", ua = "Сягнувши 100 енергії, Тіні Барґаста стають несприйнятливими до ефектів контролю та примусового пересування." },
    { en = "Bargast rips out the soul of a player, inflicting $s1 Shadow damage and causing a soul to appear that drifts toward Altimor until it is healed to full.\n\n\n\nThe soul's starting health is proportional to the health of the player being struck by $@spellname334797.\n\n\n\nIf the soul reaches Altimor, he gains $@spellname334884 for $334884d.", ua = "Барґаст вириває душу гравця, завдаючи $s1 шкоди від тіні й змушуючи з'явитися душу, що дрейфує до Альтимора, доки її повністю не зцілять.\n\n\n\nПочаткове здоров'я душі пропорційне до здоров'я гравця, ураженого $@spellname334797.\n\n\n\nЯкщо душа сягає Альтимора, він отримує $@spellname334884 на $334884d." },
    { en = "Hecutis charges to his target when unburdened by $@spellname334860.", ua = "Гекутіс кидається до своєї цілі, коли його не обтяжує $@spellname334860." },
    { en = "Margore sets his sights on a player, after $334945d he lunges at them inflicting $s1 Physical damage divided evenly by players within $A1 yards.", ua = "Марґор бере гравця на приціл, а за $334945d стрибає на нього, завдаючи $s1 фізичної шкоди, рівномірно розподіленої між гравцями в радіусі $A1 м." },
    { en = "Damage taken increased by $s1% while under loss of control effects. This effect stacks.", ua = "Отримувана шкода збільшена на $s1%, поки діють ефекти втрати контролю. Цей ефект накопичується." },
    { en = "Inflicts $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Завдає $s1 шкоди від тіні всім гравцям, а також додатково $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "Margore shreds his target, inflicting $s1 Physical damage and an additional $s2 Physical damage every $t2 sec for $d.", ua = "Марґор шматує свою ціль, завдаючи $s1 фізичної шкоди, а також додатково $s2 фізичної шкоди кожні $t2 сек протягом $d." },
    { en = "The Rockbound Vanquisher crashes down, inflicting $s1 Physical damage to all players, granting the Rockbound Vanquisher an application of $@spellname335598.", ua = "Скелезакутий Переможець обрушується вниз, завдаючи $s1 фізичної шкоди всім гравцям і даючи Скелезакутому Переможцю заряд $@spellname335598." },
    { en = "A pool of flames lingers, inflicting $s1 Fire damage every $t1 sec.", ua = "Калюжа полум'я лишається й завдає $s1 шкоди вогнем кожні $t1 сек." },
    { en = "Burning plumage emits fire, inflicting $329470s1 Fire damage to all enemies within $329470A1 yards every $328659t1 sec. Each pulse leaves behind $@spellname328579.", ua = "Палаюче оперення випускає вогонь, завдаючи $329470s1 шкоди вогнем усім ворогам у межах $329470A1 ярдів кожні $328659t1 сек. Кожен спалах лишає по собі $@spellname328579." },
    { en = "The Pestering Fiend shatters upon death, inflicting $s1 Physical damage to all players within $A1 yards.", ua = "Гнітючий нечестивець розлітається на друзки при смерті, завдаючи $s1 фізичної шкоди всім гравцям у межах $A1 ярдів." },
    { en = "Upon reaching 0% health, the phoenix collapses into a pile of embers, gaining $s1% of maximum health every $T1 sec.\n\nThe $@spellname328731 reignite upon reaching 100% of maximum health, returning the Reborn Phoenix to the battle.", ua = "Сягнувши 0% здоров'я, фенікс осідає купою жарин і відновлює $s1% максимального здоров'я кожні $T1 сек.\n\n$@spellname328731 спалахують знову, сягнувши 100% максимального здоров'я, і повертають Відродженого Фенікса в бій." },
    { en = "Inflicts $s1 Fire damage every $t1 sec for $d. This effect stacks. Applications are split between all players hit by $@spellname325877.", ua = "Завдає $s1 шкоди вогнем кожні $t1 сек. протягом $d. Цей ефект накопичується. Накладання розподіляються між усіма гравцями, яких уразив $@spellname325877." },
    { en = "Sacrifice health to heal Kael'thas, inflicting increasing maximum health damage every $t1 sec for $d. This weakens the caster, applying $@spellname339251.", ua = "Жертвує здоров'ям, щоб зцілити Кель'таса, завдаючи дедалі більшої шкоди від максимального здоров'я кожні $t1 сек. протягом $d. Це послаблює того, хто творить, накладаючи $@spellname339251." },
    { en = "Oppresses Kael'thas, inflicting $329184s1% of Kael'thas' maximum health as Shadow damage every $t1 sec.\n\nIf the Shade of Kael'thas is present, Soul Infusers instead heal the Shade of Kael'thas for $339281s1% of maximum health every $t1 sec.", ua = "Гнітить Кель'таса, завдаючи $329184s1% максимального здоров'я Кель'таса як шкоду від тіні кожні $t1 сек.\n\nЯкщо присутній Примара Кель'таса, Вливальниці душ натомість зцілюють Примару Кель'таса на $339281s1% максимального здоров'я кожні $t1 сек." },
    { en = "At 100 Energy, the Shade of Kael'thas releases a massive blast of fire, inflicting $s2 Fire damage in a $a2 yard frontal cone.", ua = "При 100 енергії Примара Кель'таса вивільняє потужний спалах вогню, завдаючи $s2 шкоди вогнем у лобовому конусі завдовжки $a2 ярдів." },
    { en = "Fire enshrouds Kael'thas, absorbing $s1 healing received and causing Kael'thas to cast $@spellname337865. Removing the $@spellname337859 interrupts Kael'thas.", ua = "Вогонь огортає Кель'таса, поглинаючи $s1 отриманого зцілення й змушуючи Кель'таса застосувати $@spellname337865. Зняття $@spellname337859 перериває Кель'таса." },
    { en = "Increases damage taken from $@spellname339232 by $s1% and prohibits interaction with Soul Pedestals for $d. This effect stacks.", ua = "Збільшує шкоду, отриману від $@spellname339232, на $s1% і забороняє взаємодію з П'єдесталами душ протягом $d. Цей ефект накопичується." },
    { en = "Channels dark energy into multiple players, inflicting $328890s1 Shadow damage every $328889t1 sec to players within $328890A1 yards of each player.", ua = "Спрямовує темну енергію в кількох гравців, завдаючи $328890s1 шкоди від тіні кожні $328889t1 сек. гравцям у межах $328890A1 ярдів від кожного гравця." },
    { en = "The Shade of Kael'thas lets loose a fiery blast, inflicting $s1 Fire damage and applying $@spellname326456 to all enemies in a $a1 yard frontal cone.", ua = "Примара Кель'таса вивільняє вогняний спалах, завдаючи $s1 шкоди вогнем і накладаючи $@spellname326456 на всіх ворогів у лобовому конусі завдовжки $a1 ярдів." },
    { en = "Inflicts $s1 Fire damage every $t1 sec for $d. This effect stacks.", ua = "Завдає $s1 шкоди вогнем кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Moves through shadows, teleporting to a nearby location to avoid attackers.", ua = "Рухається крізь тіні, телепортуючись у сусіднє місце, щоб уникнути нападників." },
    { en = "The Rockbound Vanquisher crashes down, inflicting $s1 Physical damage to all players.", ua = "Каменепутий Підкорювач обрушується вниз, завдаючи $s1 фізичної шкоди всім гравцям." },
    { en = "Throws a brittle ruby at a random player, inflicting $s1 Physical damage to players within $A1 yards.$@spellname335540 ignores school lockout and has no cooldown.", ua = "Кидає крихкий рубін у випадкового гравця, завдаючи $s1 фізичної шкоди гравцям у межах $A1 ярдів. $@spellname335540 ігнорує блокування школи магії та не має перезарядження." },
    { en = "Increases all healing done by $s1% for $d. This effect stacks.", ua = "Збільшує все завдане зцілення на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Slams the target inflicting $s1 Physical damage and applying $@spellname325442. This effect stacks.", ua = "Гатить ціль, завдаючи $s1 фізичної шкоди й накладаючи $@spellname325442. Цей ефект накопичується." },
    { en = "Inflicts $s1 Physical every $t1 sec for $d. This effect stacks.", ua = "Завдає $s1 фізичної шкоди кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "This leaking Essence Font decays, losing health over time. The rate at which this decays increases over time, disintegrating upon reaching 0 health.", ua = "Цей надтріснутий Витік Есенції розпадається, втрачаючи здоров'я з часом. Швидкість розпаду наростає з часом, аж поки витік не розчиняється, сягнувши 0 здоров'я." },
    { en = "Superheated Fire rains down on all players, inflicting $s1 Fire damage.", ua = "Розпечений Вогонь проливається дощем на всіх гравців, завдаючи $s1 шкоди вогнем." },
    { en = "Kael'thas is bound to his Shade, absorbing all healing while the Shade of Kael'thas exists.", ua = "Кель'тас прив'язаний до своєї Примари й поглинає все зцілення, доки Примара Кель'таса існує." },
    { en = "Brands all enemies with a shadowy mark, inflicting $s1 Shadow damage and increasing damage taken by $s2% for $d.", ua = "Таврує всіх ворогів тіньовою міткою, завдаючи $s1 шкоди від тіні й збільшуючи отриману шкоду на $s2% протягом $d." },
    { en = "Fires a bolt of dark energy at the player, inflicting $s1 Shadow damage.", ua = "Випускає блискавку темної енергії в гравця, завдаючи $s1 шкоди від тіні." },
    { en = "The Bleakwing Assassin turns to stone, healing for $s2% of their maximum health after $d.", ua = "Убивця Похмурокрилих обертається на камінь, зцілюючись на $s2% максимального здоров'я через $d." },
    { en = "Heals Kael'thas for $s1% of his maximum health.", ua = "Зцілює Кель'таса на $s1% його максимального здоров'я." },
    { en = "Vile Occultists carry leaking Essence Fonts, dropping them upon death.\n\nThe Essence Font disintegrates when the Vile Occultists' anima depletes.", ua = "Мерзенні окультисти носять надтріснуті Витоки Есенції, упускаючи їх при смерті.\n\nВитік Есенції розчиняється, коли аніма мерзенного окультиста вичерпується." },
    { en = "The Bleakwing Assassin teleports to behind its marked players, inflicting $326586s1 Physical to players within $326586A1 yards and additionally bleeds targets for $326586s2 Physical damage every $326586t2 sec for $326586d.", ua = "Убивця Похмурокрилих телепортується за спину позначених гравців, завдаючи $326586s1 фізичної шкоди гравцям у межах $326586A1 ярдів і додатково завдаючи цілям кровотечі на $326586s2 фізичної шкоди кожні $326586t2 сек. протягом $326586d." },
    { en = "Increases damage done by $@spellname325506 by $s1%. This effect stacks.", ua = "Збільшує шкоду, завдану $@spellname325506, на $s1%. Цей ефект накопичується." },
    { en = "A cloak of fire enshrouds the Shade of Kael'thas, absorbing $s1 damage and causing him to cast $@spellname337865. Removing the $@spellname343026 interrupts the Shade of Kael'thas.", ua = "Плащ із вогню огортає Тінь Кель'таса, поглинаючи $s1 шкоди і змушуючи його творити $@spellname337865. Зняття $@spellname343026 перериває Тінь Кель'таса." },
    { en = "The Shade of Kael'thas calls down a pillar of fire on a player, inflicting $s1 Fire damage to all enemies within $A1 yards of the impact point, split evenly between all enemies hit.", ua = "Примара Кель'таса обрушує стовп вогню на гравця, завдаючи $s1 шкоди вогнем усім ворогам у межах $A1 ярдів від точки удару; шкода рівномірно розподіляється між усіма ураженими ворогами." },
    { en = "Burning plumage emits fire, inflicting $329470s1 Fire damage to all enemies within $329470A1 yards every $328659t1 sec.", ua = "Палаюче оперення випускає вогонь, завдаючи $329470s1 шкоди вогнем усім ворогам у межах $329470A1 ярдів кожні $328659t1 сек." },
    { en = "The Edge of Annihilation's presence inflicts $s1 Shadow damage to all players every $t1 sec.", ua = "Присутність Грані Знищення завдає $s1 шкоди від тіні всім гравцям кожні $t1 сек." },
    { en = "Necromantic energy arcs from the crystal, inflicting $s1 Shadow to several players.", ua = "Некромантська енергія дугами зривається з кристала, завдаючи $s1 шкоди від тіні кільком гравцям." },
    { en = "Xy'mox activates the root, planting $s1 Seeds of Extinction. After $s2 sec the seeds explode inflicting $329107s1 Nature damage to players within $329107A1 yards.\n\n\n\nPlayers can interact with seeds to move them.", ua = "Ксай'мокс активує корінь, висаджуючи $s1 Насінин Вимирання. Через $s2 сек. насінини вибухають, завдаючи $329107s1 шкоди від сил природи гравцям у межах $329107A1 ярдів.\n\n\n\nГравці можуть взаємодіяти з насінинами, щоб пересувати їх." },
    { en = "Xy'mox activates the crystal, releasing Fleeting Spirits that fixate players and attempt to possess them.\n\n\n\nFleeting Spirits will dissipate if they are unable to reach their target within $327902d.", ua = "Ксай'мокс активує кристал, вивільняючи Скороминущих Духів, які прикипають до гравців і намагаються заволодіти ними.\n\n\n\nСкороминущі Духи розсіюються, якщо не можуть дістатися до своєї цілі протягом $327902d." },
    { en = "Xy'mox activates the Edge of Annihilation, causing it to draw players in with increasing intensity until it erupts, inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Ксай'мокс активує Грань Знищення, через що вона дедалі сильніше затягує гравців, поки не вибухне, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 ярдів." },
    { en = "Xy'mox marks their primary target. The target suffers $325331s1 Arcane damage every $325236t1 sec for $325236d.\n\n\n\nWhen $@spellname325361 expires it inflicts up to $325324s1 Arcane damage to all players and afflicts the primary target with $@spellname340533 for $340533d. \n\n\n\nThis damage is reduced the further away players are from the blast.", ua = "Ксай'мокс позначає свою основну ціль. Ціль зазнає $325331s1 арканної шкоди кожні $325236t1 сек. протягом $325236d.\n\n\n\nКоли $@spellname325361 спливає, він завдає до $325324s1 арканної шкоди всім гравцям і вражає основну ціль ефектом $@spellname340533 протягом $340533d.\n\n\n\nЦя шкода зменшується що далі гравці перебувають від вибуху." },
    { en = "Xy'mox opens rifts that emit a blast of energy after a short delay, inflicting $s1 Arcane damage to players in a line.", ua = "Ксай'мокс відкриває розломи, що за коротку мить виштовхують спалах енергії, завдаючи $s1 арканної шкоди гравцям на лінії." },
    { en = "Increases Arcane damage taken by $s1% for $d.", ua = "Збільшує отриману арканну шкоду на $s1% на $d." },
    { en = "Xy'mox marks $s3 players, after $328448d the mark detonates inflicting $328545s1 Arcane damage to players within $328545a1 yards and creates a wormhole at their location.\n\n\n\nPlayers can travel between wormholes.", ua = "Ксай'мокс позначає $s3 гравців; за $328448d позначка детонує, завдаючи $328545s1 арканної шкоди гравцям у межах $328545a1 ярдів, і створює в їхньому місці кротовину.\n\n\n\nГравці можуть переміщатися між кротовинами." },
    { en = "Xy'mox creates a $@spellname325399 that jumps between all players, inflicting $s1 Arcane damage.", ua = "Ксай'мокс створює $@spellname325399, що перестрибує між усіма гравцями, завдаючи $s1 арканної шкоди." },
    { en = "Upon reaching their fixate target, the spirit possesses the player, forcing them to attack their allies until sufficient damage is taken.", ua = "Досягнувши цілі своєї одержимості, дух вселяється в гравця і змушує його нападати на союзників, доки той не зазнає достатньо шкоди." },
    { en = "The Root lashes out, inflicting $s1 Nature damage every $t1 sec for $d.", ua = "Корінь шмагає, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d." },
    { en = "Xy'mox deploys a set of Stasis Traps at the locations of several players, after $s1 sec the traps arm. \n\n\n\nPlayers that trip a $@spellname326302 are stunned and suffer $326302s1 Arcane damage every $326302t1 sec until the $@spellname326302 is destroyed.", ua = "Ксай'мокс розставляє низку Пасток Стазису в місцях кількох гравців; за $s1 сек. пастки активуються.\n\n\n\nГравці, що зачіпають $@spellname326302, приголомшуються і зазнають $326302s1 арканної шкоди кожні $326302t1 сек., доки $@spellname326302 не буде знищено." },
    { en = "Increases the damage taken from $@spellname329298 by $s1% for $d.\n\n\n\nThis effect stacks.", ua = "Збільшує шкоду, отриману від $@spellname329298, на $s1% на $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Each of the Hungering Destroyer's melee attacks leeches $332296s1 health from the target.", ua = "Кожен удар Голодного Руйнівника в ближньому бою висмоктує $332296s1 здоров'я з цілі." },
    { en = "With each consecutive melee attack against the same target, the damage of $@spellname332296 is increased by $s1%. This effect stacks.\n\n\n\nWhen the Hungering Destroyer switches to a new target, $@spellname332295 is reset.", ua = "З кожним наступним ударом по тій самій цілі в ближньому бою шкода від $@spellname332296 збільшується на $s1%. Цей ефект накопичується.\n\n\n\nКоли Голодний Руйнівник переходить на нову ціль, $@spellname332295 скидається." },
    { en = "The Hungering Destroyer excites the life energy in all players causing them to erupt, inflicting $s1 Shadow damage to nearby players.  The size of the effect increases based on the target's missing health.", ua = "Голодний Руйнівник збуджує життєву енергію всіх гравців, змушуючи їх вибухати і завдаючи $s1 шкоди від тіні гравцям поруч. Розмір ефекту зростає залежно від нестачі здоров'я в цілі." },
    { en = "The Hungering Destroyer unleashes torrents of energy, inflicting $s1 Shadow damage to all players.", ua = "Голодний Руйнівник вивільняє потоки енергії, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "The Hungering Destroyer unleashes energy towards marked targets, inflicting $334228s1 Shadow damage to players in that direction.  In addition, players hit by the effect take $334228s2% increased damage from $@spellname334064 for $334228d.", ua = "Голодний Руйнівник вивільняє енергію в бік позначених цілей, завдаючи $334228s1 шкоди від тіні гравцям у цьому напрямку. Крім того, гравці, уражені цим ефектом, отримують на $334228s2% більше шкоди від $@spellname334064 протягом $334228d." },
    { en = "The Hungering Destroyer smashes its current target, inflicting $s1 Physical damage.", ua = "Голодний Руйнівник трощить свою поточну ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Hungering energies surround the target reducing all healing received by $s1% and inflicting $330590s1 Shadow damage every $t2 sec for $d.  In addition, the target leeches $330537s1 health from all allies within $330537A1 yards every $s2 sec.", ua = "Голодні енергії огортають ціль, зменшуючи все отримане зцілення на $s1% і завдаючи $330590s1 шкоди від тіні кожні $t2 сек. протягом $d. Окрім того, ціль висмоктує $330537s1 здоров'я з усіх союзників у межах $330537A1 ярдів кожні $s2 сек." },
    { en = "The Hungering Destroyer chooses up to $s1 players and unleashes a line of energy in each of their directions, inflicting $334228s1 Shadow damage.", ua = "Голодний Руйнівник обирає до $s1 гравців і вивільняє лінію енергії в напрямку кожного з них, завдаючи $334228s1 шкоди від тіні." },
    { en = "Creates a nexus of chaotic energy.  Touching an $@spellname329835 causes it to erupt, inflicting $s1 Shadow damage to the target.", ua = "Створює осередок хаотичної енергії. Дотик до $@spellname329835 спричиняє його вибух, завдаючи $s1 шкоди від тіні цілі." },
    { en = "The Hungering Destroyer begins to devour all nearby energy, pulling players towards its location and leeching up to $334523s1 health from all players every $t1 sec for $d.  Players farther from the Hungering Destroyer have less health leeched.", ua = "Голодний Руйнівник починає поглинати всю енергію довкола, притягуючи гравців до себе і висмоктуючи до $334523s1 здоров'я в усіх гравців кожні $t1 с протягом $d.  Гравці, дальші від Голодного Руйнівника, втрачають менше здоров'я." },
    { en = "The victim suffers $o1 Shadow damage over $d.", ua = "Жертва зазнає $o1 шкоди від тіні протягом $d." },
    { en = "Your past sins expire, inflicting $o1 Shadow damage to all players over $d.", ua = "Твої минулі гріхи спливають, завдаючи $o1 шкоди від тіні всім гравцям протягом $d." },
    { en = "Inflicts up to $s1 Shadow damage to all enemies. Targets that are further away from the epicenter suffer less damage.", ua = "Завдає до $s1 шкоди від тіні всім ворогам. Цілі, що далі від епіцентру, зазнають меншої шкоди." },
    { en = "The caster hurls out vials of bottled anima that inflict $325769s1 Shadow damage to all players within $325769A1 yards of the impact.\n\n\n\nIf no players are hit by the impact, Unleashed Volatility occurs.", ua = "Той, хто творить закляття, шпурляє флакони з закупореною анімою, що завдають $325769s1 шкоди Тінню всім гравцям у радіусі $325769A1 ярдів від місця влучання.\n\n\n\nЯкщо влучання не зачіпає жодного гравця, спрацьовує Вивільнена Нестабільність." },
    { en = "The caster hurls out vials of bottled anima that inflict $325769s1 Shadow damage to all players within $325769A1 yards of the impact.\n\n\n\nIf no players are hit by the impact, Unleashed Volatility occurs.\n\n\n\nThe impact creates a pool of Lingering Anima.", ua = "Заклинач жбурляє флакони закупореної аніми, що завдають $325769s1 шкоди від тіні всім гравцям у межах $325769A1 ярдів від місця влучання.\n\n\n\nЯкщо влучання не зачіпає жодного гравця, спрацьовує Вивільнена Летючість.\n\n\n\nВлучання створює калюжу Залишкової Аніми." },
    { en = "The caster hurls out vials of bottled anima that inflict $325769s1 Shadow damage to all players within $325769A1 yards of the impact.\n\n\n\nIf no players are hit by the impact, Unleashed Volatility occurs.\n\n\n\nThe impact creates a pool of Lingering Anima and causes a bottle of Replicated Anima to impact one additional time.", ua = "Заклинач жбурляє флакони закупореної аніми, що завдають $325769s1 шкоди від тіні всім гравцям у межах $325769A1 ярдів від місця влучання.\n\n\n\nЯкщо влучання не зачіпає жодного гравця, спрацьовує Вивільнена Летючість.\n\n\n\nВлучання створює калюжу Залишкової Аніми і змушує флакон Реплікованої Аніми влучити ще раз." },
    { en = "When the Sins and Suffering container is at power level two or above, an Anima Web forms between the vertices of Sins of the Past.\n\n\n\nPassing through the Anima Web inflicts $o1 Shadow damage to the target over $d.", ua = "Коли резервуар Гріхів і Страждань на другому рівні потужності чи вище, між вершинами Гріхів Минулого утворюється Павутина Аніми.\n\n\n\nПрохід крізь Павутину Аніми завдає цілі $o1 шкоди від тіні протягом $d." },
    { en = "Extracts the past sins of random enemies at random locations.\n\n\n\nSins of the Past continually inflict $326040s1 Shadow damage to the nearest player until all Sins of the Past are linked with the beams of Shared Suffering.", ua = "Видобуває минулі гріхи випадкових ворогів у випадкових місцях.\n\n\n\nГріхи Минулого безперервно завдають $326040s1 шкоди від тіні найближчому гравцю, доки всі Гріхи Минулого не будуть з'єднані променями Розділеного Страждання." },
    { en = "Extracts the past sins of random enemies at random locations.\n\n\n\nSins of the Past continually inflict $326040s1 Shadow damage to the nearest player until all Sins of the Past are linked with the beams of Shared Suffering.\n\n\n\nAfter the sins manifest, an Anima Web forms between them.", ua = "Видобуває минулі гріхи випадкових ворогів у випадкових місцях.\n\n\n\nГріхи Минулого безперервно завдають $326040s1 шкоди від тіні найближчому гравцю, доки всі Гріхи Минулого не будуть з'єднані променями Розділеного Страждання.\n\n\n\nПісля прояву гріхів між ними утворюється Павутина Аніми." },
    { en = "Failing to catch the bottled anima before it hits the ground causes a massive explosion for $s1 Shadow damage to all players.", ua = "Якщо не впіймати закупорену аніму, перш ніж вона торкнеться землі, стається потужний вибух, що завдає $s1 шкоди від тіні всім гравцям." },
    { en = "Extracts the past sins of random enemies at random locations.\n\n\n\nSins of the Past continually inflict $326040s1 Shadow damage to the nearest player until all Sins of the Past are linked with the beams of Shared Suffering.\n\n\n\nAfter the sins manifest, an Anima Web forms between them. The strands of this Anima Web rotate.", ua = "Видобуває минулі гріхи випадкових ворогів у випадкових місцях.\n\n\n\nГріхи Минулого безперервно завдають $326040s1 шкоди від тіні найближчому гравцю, доки всі Гріхи Минулого не будуть з'єднані променями Розділеного Страждання.\n\n\n\nПісля прояву гріхів між ними утворюється Павутина Аніми. Нитки цієї Павутини Аніми обертаються." },
    { en = "Damage dealt to the victim of $@spellname325379 is copied to targets with Shared Cognition over $d.", ua = "Шкода, завдана жертві $@spellname325379, копіюється на цілі з Розділеним Усвідомленням протягом $d." },
    { en = "Inflicts $s1 Shadow damage to all enemies.", ua = "Завдає $s1 шкоди від тіні всім ворогам." },
    { en = "Lady Inerva Darkvein targets enemies at random and concentrates anima in their hearts, inflicting $332664o1 Shadow damage over $332664d.\n\n\n\nWhen Concentrated Anima expires, an explosion of Unleashed Shadows occurs, inflicting $332668s1 Shadow damage to all enemies within $332668A1 yards.", ua = "Леді Інерва Темножила бере на приціл випадкових ворогів і концентрує аніму в їхніх серцях, завдаючи $332664o1 шкоди від тіні протягом $332664d.\n\n\n\nКоли Сконцентрована Аніма спливає, стається вибух Вивільнених Тіней, що завдає $332668s1 шкоди від тіні всім ворогам у межах $332668A1 ярдів." },
    { en = "Lady Inerva Darkvein targets enemies at random and concentrates anima in their hearts, inflicting $332664o1 Shadow damage over $332664d.\n\n\n\nThe victim is rooted for the duration.\n\n\n\nWhen Concentrated Anima expires, an explosion of Unleashed Shadows occurs, inflicting $332668s1 Shadow damage to all enemies within $332668A1 yards.", ua = "Леді Інерва Темножила бере на приціл випадкових ворогів і концентрує аніму в їхніх серцях, завдаючи $332664o1 шкоди від тіні протягом $332664d.\n\n\n\nЖертва знерухомлена на весь час дії.\n\n\n\nКоли Сконцентрована Аніма спливає, стається вибух Вивільнених Тіней, що завдає $332668s1 шкоди від тіні всім ворогам у межах $332668A1 ярдів." },
    { en = "Lady Inerva Darkvein targets enemies at random and concentrates anima in their hearts, inflicting $332664o1 Shadow damage over $332664d.\n\n\n\nThe victim is rooted for the duration.\n\n\n\nWhen Concentrated Anima expires, an explosion of Unleashed Shadows occurs, inflicting $332668s1 Shadow damage to all enemies within $332668A1 yards and unleashing Fragments of Shadow in all directions.", ua = "Леді Інерва Темножила бере на приціл випадкових ворогів і концентрує аніму в їхніх серцях, завдаючи $332664o1 шкоди від тіні протягом $332664d.\n\n\n\nЖертва знерухомлена на весь час дії.\n\n\n\nКоли Сконцентрована Аніма спливає, стається вибух Вивільнених Тіней, що завдає $332668s1 шкоди від тіні всім ворогам у межах $332668A1 ярдів і вивільняє Уламки Тіні в усіх напрямках." },
    { en = "Burdens the target with unconscionable guilt, inflicting $s1 Shadow damage and increasing damage taken from Unconscionable Guilt and Expose Desires by $s2% for $d.", ua = "Обтяжує ціль нестерпною провиною, завдаючи $s1 шкоди від темряви та збільшуючи шкоду, отримувану від Нестерпної Провини й Оголення Бажань, на $s2% протягом $d." },
    { en = "The loose anima in the room inflicts $s1 Shadow damage to all players every $t1 sec. This damage increases with the number of open containers.", ua = "Вільна аніма в залі завдає $s1 шкоди від тіні всім гравцям кожні $t1 сек. Ця шкода зростає з кількістю відкритих резервуарів." },
    { en = "Lady Inerva Darkvein focuses anima into one of the containers, locking it closed and increasing the rate it gains anima.", ua = "Леді Інерва Темножила фокусує аніму в один із резервуарів, замикаючи його і збільшуючи швидкість, з якою він накопичує аніму." },
    { en = "When the Bottled Anima container is at power level two or greater, the impact creates a pool of Lingering Anima that will continually inflict $325713s1  Shadow damage to all players within its confines.", ua = "Коли резервуар Закупореної Аніми на другому рівні потужності чи вище, влучання створює калюжу Залишкової Аніми, що безперервно завдає $325713s1 шкоди від тіні всім гравцям у її межах." },
    { en = "$s1 Shadow damage to all players within $A1 yards of the target and summons either a Harnessed Specter or a Conjured Manifestation.", ua = "$s1 шкоди від тіні всім гравцям у межах $A1 ярдів від цілі та призиває або Приборканого Привида, або Прикликану Маніфестацію." },
    { en = "The target is attacked by a manifestation of their hidden desires.  If the victim fails to face the attack they take $335324s1 Shadow damage and are afflicted with an additional application of $@spellname325382.", ua = "Ціль атакує втілення її прихованих бажань. Якщо жертва не зустріне напад віч-на-віч, вона дістає $335324s1 шкоди від тіні й отримує додаткову дію $@spellname325382." },
    { en = "Players caught in the path of a Fragment of Shadow suffer $s1 Shadow damage.", ua = "Гравці, які опиняються на шляху Уламка Тіні, дістають $s1 шкоди від тіні." },
    { en = "The Anima Container bursts, inflicting $s1 Shadow damage to all players. The breach continues until the container's anima level is reduced below capacity.", ua = "Вмістилище аніми розривається, завдаючи $s1 шкоди від тіні всім гравцям. Прорив триває, доки рівень аніми у вмістилищі не впаде нижче його місткості." },
    { en = "Roots the target in place for $d.", ua = "Прикорінює ціль на місці на $d." },
    { en = "The caster exposes the deepest desires of the target's heart, inflicting $s1 Physical damage and afflicts the victim with $@spellname325382.", ua = "Заклинач оголює найглибші бажання серця цілі, завдаючи $s1 фізичної шкоди й уражаючи жертву ефектом $@spellname325382." },
    { en = "The caster exposes the deepest desires of the target's heart, inflicting $s1 Physical damage and afflicts the victim with $@spellname325382.\n\n\n\nFurther damage dealt to the victim by Expose Desires is copied to random allies via $@spellname325908.", ua = "Заклинач оголює найглибші бажання серця цілі, завдаючи $s1 фізичної шкоди й уражаючи жертву ефектом $@spellname325382.\n\n\n\nПодальша шкода, завдана жертві ефектом «Оголені Бажання», копіюється на випадкових союзників через $@spellname325908." },
    { en = "The caster exposes the deepest desires of the target's heart, inflicting $s1 Physical damage and afflicts the victim with $@spellname325382.\n\n\n\nFurther damage dealt to the victim by Expose Desires is copied to random allies via $@spellname325908.\n\n\n\nWhen $@spellname325382 expires, the target explodes with a $@spellname325384.", ua = "Заклинач оголює найглибші бажання серця цілі, завдаючи $s1 фізичної шкоди й уражаючи жертву ефектом $@spellname325382.\n\n\n\nПодальша шкода, завдана жертві ефектом «Оголені Бажання», копіюється на випадкових союзників через $@spellname325908.\n\n\n\nКоли $@spellname325382 завершується, ціль вибухає, спричиняючи $@spellname325384." },
    { en = "Open the release valve, causing anima to flow out of the container and into the room. Opening the valve causes you to take $s3 Shadow damage every $t3 sec. for $d.", ua = "Відкрийте випускний клапан, щоб аніма витекла з вмістилища до зали. Відкривши клапан, ви дістаєте $s3 шкоди від тіні кожні $t3 с протягом $d." },
    { en = "Lady Inerva Darkvein links two targets together for $d. Linked targets and any other players caught between them suffer $325004s1 Shadow damage every $t1 sec.", ua = "Леді Інерва Темножила сковує дві цілі разом на $d. Скуті цілі та будь-які інші гравці між ними дістають $325004s1 шкоди від тіні кожні $t1 с." },
    { en = "Lord Stavros is unimpressed by your dance moves. While moving or jumping your movement speed is reduced by $s1% every $346912t1 sec.  \n\n\n\nStanding still allows you to regain your footing.", ua = "Лорд Ставрос не вражений вашими танцювальними рухами. Під час руху чи стрибків ваша швидкість пересування зменшується на $s1% кожні $346912t1 сек.\n\n\n\nНерухоме стояння дозволяє відновити рівновагу." },
    { en = "Baroness Frieda, pulls the life energy from her targets, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Баронеса Фріда висмоктує життєву енергію зі своїх цілей, завдаючи $s1 шкоди від тіні кожні $t1 с протягом $d." },
    { en = "The Baroness violently unleashes the welled-up pride within each player causing them to erupt, inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Баронеса жорстоко вивільняє пиху, що накопичилася в кожному гравцеві, змушуючи їх вибухнути та завдаючи $s1 шкоди від тіні всім гравцям у радіусі $A1 м." },
    { en = "The Veteran Stoneguard slashes at its current target, inflicting $s1 Physical damage and leeching some of the target's essence, permanently increasing their damage done by $346792s1%. This effect stacks.", ua = "Ветеран-кам'яногвардієць шматує свою поточну ціль, завдаючи $s1 фізичної шкоди й висмоктуючи частину її єства, що назавжди підвищує завдавану ним шкоду на $346792s1%. Цей ефект накопичується." },
    { en = "The master of dance calls players to take their places and follow the lead of their dredger dance partners.  Making the proper dance move shows your $@spellname346035, while failing to do so demonstrates your $@spellname330848.", ua = "Розпорядник танцю кличе гравців зайняти свої місця й слідувати за партнерами-копачами в танці. Правильний танцювальний рух являє вашу $@spellname346035, а помилка — вашу $@spellname330848." },
    { en = "Each correctly performed dance step increases Haste by $s1% for $d.\n\n\n\nThis effect stacks.", ua = "Кожен правильно виконаний танцювальний крок підвищує Поспіх на $s1% протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Castellan Niklaus' cold wrath emboldens his forces.  When any of his allies are slain all other Nathrian forces within $A1 yards of the victim become enraged, increasing their damage done by $s1% for $d.", ua = "Холодний гнів кастеляна Ніклауса надихає його сили. Коли вбито будь-якого з його союзників, усі інші сили Натрії в межах $A1 ярдів від жертви оскаженіють, збільшуючи завдану ними шкоду на $s1% протягом $d." },
    { en = "Baroness Frieda summons forth $s2 $@spellname346762 that impale her current target over $d.  Each spike inflicts $346681s1 Physical damage and increases the damge taken from $@spellname346762 for $d.  In addition, each impact radiates a portion of the damage inflicted to all players as Shadow damage.", ua = "Баронеса Фріда викликає $s2 $@spellname346762, які пронизують її поточну ціль протягом $d. Кожен шпичак завдає $346681s1 фізичної шкоди та збільшує шкоду, отримувану від $@spellname346762, протягом $d. Крім того, кожне влучання випромінює частину завданої шкоди всім гравцям як шкоду від тіні." },
    { en = "Baroness Frieda twists the pain of her victims, causing them to manifest pools of $@spellname346945 when they take damage from her abilities.", ua = "Баронеса Фріда викривлює біль своїх жертв, змушуючи їх утворювати калюжі $@spellname346945, коли вони дістають шкоди від її здібностей." },
    { en = "The intense and strict atmosphere of the Council of Blood inflicts $s1 Shadow damage every $t sec to all players.\n\n\n\nThis effect stacks, increasing in stack count every $334952t sec.", ua = "Гнітюча й сувора атмосфера Ради Крові завдає $s1 шкоди від тіні кожні $t с усім гравцям.\n\n\n\nЦей ефект накопичується, зростаючи на одну позначку кожні $334952t с." },
    { en = "Venthyr noble men and women emit violent outbursts of celebratory anima when in the throes of revelry. Each burst inflicts $s1 Shadow damage to players within $A1 yards.", ua = "Вентири-аристократи, чоловіки й жінки, у захваті бенкету вивергають буремні сплески святкової аніми. Кожен сплеск завдає $s1 шкоди від тіні гравцям у радіусі $A1 м." },
    { en = "Baroness Frieda manifests a pool at the player's location that lasts for $346944d.  Standing within the pool inflicts $s1 Shadow damage every $t1 sec.", ua = "Баронеса Фріда створює калюжу на місці гравця, що триває $346944d. Перебування в калюжі завдає $s1 шкоди від тіні кожні $t1 с." },
    { en = "Castellan Niklaus demonstrates a stunning counter-attack, inflcting $s1 Physical damage and increasing the damge of $@spellname346690 by $s2% for $d.  This effect stacks.", ua = "Кастелян Ніклаус демонструє приголомшливу контратаку, завдаючи $s1 фізичної шкоди та підвищуючи шкоду $@spellname346690 на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Lord Stavros calls Waltzing Venthyr to careen across the dance floor. Upon contact players suffer $s2 Shadow damage and are stunned for $d.", ua = "Лорд Ставрос кличе Вальсуючих Вентирів пронестися танцювальним майданчиком. При контакті гравці дістають $s2 шкоди від тіні та приголомшуються на $d." },
    { en = "Calls forth a Dutiful Attendant to shield the caster's allies.", ua = "Прикликає Старанного Прислужника, щоб захистити союзників заклинача." },
    { en = "The Dutiful Attendant maintains a shield on the weakest council member, making them immune to all damage for $d.", ua = "Старанний Прислужник підтримує щит на найслабшому членові ради, роблячи його несприйнятливим до всієї шкоди на $d." },
    { en = "Lord Stavros teleports behind his current target before lunging forward, inflicting $327610s1 Physical damage to players in a line $a1 yards long and increasing their damage taken by $@spellname327503 by $327610s2% for $d. This effect stacks.", ua = "Лорд Ставрос телепортується за спину своєї поточної цілі, а тоді стрибає вперед, завдаючи $327610s1 фізичної шкоди гравцям на лінії завдовжки $a1 м і підвищуючи шкоду, яку вони дістають від $@spellname327503, на $327610s2% протягом $d. Цей ефект накопичується." },
    { en = "Lord Stavros calls all Waltzing Venthyr to the dance floor.", ua = "Лорд Ставрос скликає всіх Вальсуючих Вентирів на танцювальний майданчик." },
    { en = "Castellan Niklaus calls forth Veteran Stoneguard to his aid.", ua = "Кастелян Ніклаус кличе на допомогу Ветерана-кам'яногвардійця." },
    { en = "The magic of the dance enthralls players, applying $s2 stacks of $@spellname347350 for $d. Each time the player jumps, $347434s1 Shadow damage is inflicted to all players and a stack of $@spellname347350 is removed.\n\n\n\nPlayers who fail to remove all stacks before $d are slain.", ua = "Магія танцю заворожує гравців, накладаючи $s2 позначок $@spellname347350 на $d. Щоразу, коли гравець стрибає, усім гравцям завдається $347434s1 шкоди від тіні й знімається одна позначка $@spellname347350.\n\n\n\nГравці, які не зняли всіх позначок до завершення $d, гинуть." },
    { en = "The Baroness launches a blast of anima at every  player, inflicting $s1 Shadow damage. \n\n\n\nEach player hit by the blast suffers an additial $s2 Shadow damage every $t2 sec for $d. This effect stacks.", ua = "Баронеса випускає сплеск аніми по кожному гравцеві, завдаючи $s1 шкоди від тіні.\n\n\n\nКожен гравець, уражений сплеском, дістає додаткові $s2 шкоди від тіні кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "The Dredger Waiter throws fancy hors d'oeuvres at random players, inflcting $s1 Nature damage.", ua = "Копач-офіціант жбурляє вишукані закуски у випадкових гравців, завдаючи $s1 шкоди від сил природи." },
    { en = "Failure to perform the correct dance step inflicts $s1 Shadow damage every $t1 sec and removes any $@spellname346035.  This damage continues to increase until you find your proper location or the $@spellname328497 ends.", ua = "Невиконання правильного танцювального кроку завдає $s1 шкоди від тіні кожні $t1 с і знімає будь-яку $@spellname346035. Ця шкода зростатиме, доки ви не знайдете своє місце або доки не завершиться $@spellname328497." },
    { en = "The Castellan orders several Begrudging Waiters to begin harassing players.", ua = "Кастелян наказує кільком Незадоволеним Офіціантам почати докучати гравцям." },
    { en = "Lord Stavros assigns players to dance in pairs for $d. While farther than $s2 yards from your partner Lord Stavros punishes you, inflicting $331638s1 Shadow damage every $t1 sec.\n\n\n\nIn addition, Lord Stavros encourages your dance moves by marking each partner's location every $t1 sec, causing it to erupt inflicting $334743s1 Shadow damage to all players within $334824A1 yards of the impact.", ua = "Лорд Ставрос призначає гравцям танцювати в парах протягом $d. Поки ви далі ніж за $s2 ярдів від свого партнера, Лорд Ставрос карає вас, завдаючи $331638s1 шкоди від тіні кожні $t1 сек.\n\n\n\nКрім того, Лорд Ставрос заохочує ваші танцювальні рухи, позначаючи місцезнаходження кожного партнера кожні $t1 сек, через що воно вибухає, завдаючи $334743s1 шкоди від тіні всім гравцям у межах $334824A1 ярдів від влучання." },
    { en = "Inflicts $335361s1 Physical damage every $335361t1 sec and reduces players' movement speed by $335361s2%.", ua = "Завдає $335361s1 фізичної шкоди кожні $335361t1 с і знижує швидкість пересування гравців на $335361s2%." },
    { en = "Sludgefist's melee attack damage carries through to the next closest player within $s1 yards. If no player is found the primary target is struck twice.", ua = "Шкода від ближньої атаки Багнокулака переноситься на наступного найближчого гравця в радіусі $s1 м. Якщо гравця не знайдено, основну ціль уражено двічі." },
    { en = "The stones beneath each player erupt after $d, inflicting $341087s1 Physical damage to allies within $341087A1 yds.", ua = "Каміння під кожним гравцем вибухає через $d, завдаючи $341087s1 фізичної шкоди союзникам у межах $341087A1 ярдів." },
    { en = "Sludgefist marks two players and after $342420d shackles them together. The chains inflict $335779s1 Physical damage to both players every $335293t1 sec for $335293d.\n\n\n\nMoving $335294s1 yards apart shatters the chain.", ua = "Багнокулак позначає двох гравців і за $342420d сковує їх ланцюгом разом. Ланцюги завдають $335779s1 фізичної шкоди обом гравцям кожні $335293t1 с протягом $335293d.\n\n\n\nЯкщо відійти на $335294s1 м одне від одного, ланцюг розривається." },
    { en = "Sludgefist impacts a wall and the foundation of Castle Nathria collapses.\n\n\n\nThe destruction inflicts $332241s1 Physical damage every second to all players.", ua = "Багнокулак врізається в стіну, і підмурок Замку Натрія обвалюється.\n\n\n\nРуйнування завдає $332241s1 фізичної шкоди щосекунди всім гравцям." },
    { en = "At $s3% remaining health Sludgefist enrages, gaining $s2% increased damage and increasing attack speed by $s1%.", ua = "При $s3% решти здоров'я Багнокулак шаленіє, отримуючи $s2% додаткової шкоди та підвищуючи швидкість атаки на $s1%." },
    { en = "Upon reaching 100 rage Sludgefist focuses his gaze on a target, then charges in their direction after $331209d.", ua = "Досягнувши 100 одиниць люті, Багнокулак зосереджує погляд на цілі, а потім після $331209d кидається в її напрямку." },
    { en = "Sludgefist slams into an obstacle, inflicting $s1 Physical damage to all players while stunning him and increasing his damage taken by $331314s2% for $331314d", ua = "Багнокулак врізається в перешкоду, завдаючи $s1 фізичної шкоди всім гравцям, а сам приголомшується й дістає на $331314s2% більше шкоди протягом $331314d." },
    { en = "Inflicts $s1 Physical damage to all players.", ua = "Завдає $s1 фізичної шкоди всім гравцям." },
    { en = "Sludgefist tramples everything in his path, inflicting $339067s1 Physical damage and knocking players into the air.", ua = "Багнокулак топче все на своєму шляху, завдаючи $339067s1 фізичної шкоди й підкидаючи гравців у повітря." },
    { en = "Inflicts $s1 Physical damage divided evenly between players within $A1 yards of the impact location.\n\n\n\nThe boulder then splits into two $@spellname341307 which inflict $341307s1 Physical damage to players within $341307A1 yards of each impact location.\n\n\n\nA $@spellname341482 occurs if any piece fails to hit at least one player.", ua = "Завдає $s1 фізичної шкоди, рівномірно розподіленої між гравцями в межах $A1 м від місця удару.\n\n\n\nПотім валун розколюється на два $@spellname341307, що завдають $341307s1 фізичної шкоди гравцям у межах $341307A1 м від кожного місця удару.\n\n\n\nЯкщо хоч один уламок не влучить принаймні в одного гравця, спрацьовує $@spellname341482." },
    { en = "Sludgefist unleashes a powerful roar, inflicting $332698s1 Sonic damage to all players and pushing them away.", ua = "Багнокулак вивергає потужний рев, завдаючи $332698s1 звукової шкоди всім гравцям і відштовхуючи їх." },
    { en = "Bleeds the target for $s1 Physical damage every $t1 sec for $d.", ua = "Викликає кровотечу в цілі, завдаючи $s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Sludgefist immobilizes a player with heavy chains.\n\n\n\nAfter $335470d Sludgefist pulls that player and allies within $335473A1 yards towards him, inflicting $335473s1 Physical damage divided evenly between affected players.", ua = "Багнокулак знерухомлює гравця важкими ланцюгами.\n\n\n\nЧерез $335470d Багнокулак притягує цього гравця і союзників у радіусі $335473A1 ярдів до себе, завдаючи $335473s1 фізичної шкоди, що порівну розподіляється між ураженими гравцями." },
    { en = "Sludgefist impacts a pillar and causes it to collapse.\n\n\n\nThe destruction inflicts $332444s1 Physical damage every second to all players. This effect stacks.", ua = "Багнокулак б'є по колоні й обвалює її.\n\n\n\nРуйнування завдає $332444s1 фізичної шкоди щосекунди всім гравцям. Цей ефект накопичується." },
    { en = "Inflicts $s1 Physical damage to players within $a1 yards of the impact and stuns them for $d.\n\n\n\nCreates a $@spellname335371 at the impact location.", ua = "Завдає $s1 фізичної шкоди гравцям у межах $a1 м від місця удару й оглушує їх на $d.\n\n\n\nСтворює $@spellname335371 у місці удару." },
    { en = "Sludgefist inflicts $s1 Physical damage to enemies within $A1 yards and knocks them back.\n\n\n\nDestroys nearby pillars.", ua = "Багнокулак завдає $s1 фізичної шкоди ворогам у межах $A1 м і відкидає їх.\n\n\n\nРуйнує сусідні колони." },
    { en = "Inflicts $s1 Physical damage to both players and stuns them for $d.", ua = "Завдає $s1 фізичної шкоди обом гравцям і оглушує їх на $d." },
    { en = "Prince Renathal shatters the target's $@spellname329808. The force of this blast triggers $@spellname336137, inflicting $336137s1 Shadow damage and knocking back all players.", ua = "Принц Ренатал розбиває $@spellname329808 цілі. Сила цього вибуху спричиняє $@spellname336137, завдаючи $336137s1 шкоди від тіні й відкидаючи всіх гравців." },
    { en = "Grashaal leaps at an enemy inflicting $s1 Nature damage and knocking back players within $A1 yards. This leaves behind Unstable Ground and causes  $@spellname334130 at all other Unstable Ground locations.", ua = "Грашаал стрибає на ворога, завдаючи $s1 шкоди від сил природи та відкидаючи гравців у межах $A1 м. Це залишає по собі Нестійкий ґрунт і спричиняє $@spellname334130 в усіх інших місцях Нестійкого ґрунту." },
    { en = "Grashaal calls a massive stone from the sky, inflicting $s1 Nature damage divided evenly among players within an $A yard radius of the impact.", ua = "Грашаал прикликає з неба величезний камінь, завдаючи $s1 шкоди від сил природи, рівномірно розподіленої між гравцями в радіусі $A м від місця удару." },
    { en = "Unstable Ground explode, inflicting $s1 Nature damage and applying $@spellname344655 to players within $A1 yards.\n\n\n\nImpacts that are not absorbed trigger $@spellname344740.", ua = "Нестійкий ґрунт вибухає, завдаючи $s1 шкоди від сил природи та накладаючи $@spellname344655 на гравців у межах $A1 м.\n\n\n\nНепоглинуті удари спричиняють $@spellname344740." },
    { en = "While flying, Grashaal launches a stone spike at random players, inflicting $s1 Physical damage and reducing their movement speed by $s2% for $d1.", ua = "Під час польоту Грашаал запускає кам'яний шип у випадкових гравців, завдаючи $s1 фізичної шкоди та знижуючи їхню швидкість пересування на $s2% протягом $d1." },
    { en = "Grashaal smashes his target, knocking them back and inflicting $s1 Physical damage. Enemies hit with this ability take $s2% increased damage from $@spellname342425 for $d. This effect stacks with every $@spellname342425, up to $s4 strikes.", ua = "Грашаал трощить свою ціль, відкидаючи її та завдаючи $s1 фізичної шкоди. Вороги, уражені цим умінням, отримують на $s2% більше шкоди від $@spellname342425 протягом $d. Цей ефект накопичується з кожним $@spellname342425, до $s4 ударів." },
    { en = "Kaal's skin hardens, reducing all  damage taken by $s1% until removed.", ua = "Шкіра Каал твердне, знижуючи всю отриману шкоду на $s1%, доки ефект не буде знято." },
    { en = "Inflicts $s1 Nature damage to all enemies.", ua = "Завдає $s1 шкоди від сил природи всім ворогам." },
    { en = "Kaal throws a ricocheting blade at marked targets, inflicting $s1 Shadow damage. This applies $@spellname333913.", ua = "Каал кидає рикошетне лезо в позначені цілі, завдаючи $s1 шкоди від тіні. Це накладає $@spellname333913." },
    { en = "Upon the death of a Stone Legion Goliath,  a Massive Anima Orb is created, lasting for $339884d. Collecting the Massive Anima Orb bestows $@spellname339885 upon the collector.", ua = "Після загибелі голіафа Кам'яного Легіону створюється Велетенська Сфера Аніми, що існує $339884d. Підбирання Велетенської Сфери Аніми надає тому, хто її підібрав, $@spellname339885." },
    { en = "General Grashaal causes eruptions at marked players every $334498t1 sec for $334498d, inflicting $s1 Nature damage to players within $A1 yards.", ua = "Генерал Ґрашаал викликає виверження на позначених гравцях кожні $334498t1 с протягом $334498d, завдаючи $s1 шкоди від природи гравцям у межах $A1 ярдів." },
    { en = "Volatile anima infects the target, inflicting $s1 Shadow damage every $t1 sec for $d. This anima can be transferred to Prince Renathal to restore $342700s1% of his mana and triggering $@spellname332412.", ua = "Летка аніма вражає ціль, завдаючи $s1 шкоди від тіні кожні $t1 с протягом $d. Цю аніму можна передати принцу Ренаталу, щоб відновити $342700s1% його мани та спричинити $@spellname332412." },
    { en = "Kaal crushes the souls of up to 4 players, inflicting $s1 Shadow damage every $t1 sec for $d.  Upon removal the player is afflicted with $@spellname334771.", ua = "Каал розчавлює душі до 4 гравців, завдаючи $s1 шкоди від тіні кожні $t1 с протягом $d. Після зняття гравець отримує ефект $@spellname334771." },
    { en = "Anima infects the target This anima can be transferred to Prince Renathal to restore $339886s% of his mana.", ua = "Аніма вражає ціль. Цю аніму можна передати принцу Ренаталу, щоб відновити $339886s% його мани." },
    { en = "While flying, Kaal throws a shuriken at random players, inflicting $s1 Physical damage and chaining to up to $s2 nearby players.", ua = "Під час польоту Каал кидає сюрикен у випадкових гравців, завдаючи $s1 фізичної шкоди та перестрибуючи на до $s2 сусідніх гравців." },
    { en = "Inflicts $s1 Nature damage and knocks back anyone within $A1 yards.", ua = "Завдає $s1 шкоди від сил природи й відкидає всіх у межах $A1 м." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec for $d.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с протягом $d." },
    { en = "Grashaal sends a shockwave at an enemy, inflicting $s1 Nature damage and applies $@spellname344655 to players within $A1 yards. This leaves behind Unstable Ground and causes $@spellname344721 at all other Unstable Ground locations.", ua = "Грашаал спрямовує ударну хвилю на ворога, завдаючи $s1 шкоди від сил природи та накладаючи $@spellname344655 на гравців у межах $A1 м. Це залишає по собі Нестійкий ґрунт і спричиняє $@spellname344721 в усіх інших місцях Нестійкого ґрунту." },
    { en = "Grashaal casts $@spellname339690, stunning affected players and removing bleed effects, then $@spellname339728, inflicting Nature Damage, divided among targets hit.", ua = "Грашаал творить $@spellname339690, оглушуючи уражених гравців і знімаючи ефекти кровотечі, потім $@spellname339728, завдаючи шкоди від сил природи, розподіленої між ураженими цілями." },
    { en = "Upon reaching $s3% health Stone Legion Commandos encase themselves in a stone shell, absorbing $s1 damage for $d. $@spellname340038 is triggered if the shield is not broken before the channel ends.", ua = "Досягнувши $s3% здоров'я, Командос Кам'яного Легіону вкривається кам'яною оболонкою, поглинаючи $s1 шкоди протягом $d. Якщо щит не зруйнувати до завершення прочитання, спрацьовує $@spellname340038." },
    { en = "Stone Legion Commando explodes, killing the Commando and inflicting $s1 Shadow damage to all players within a $A1 radius.", ua = "Командос Кам'яного Легіону вибухає, гинучи сам і завдаючи $s1 шкоди від тіні всім гравцям у радіусі $A1." },
    { en = "Kaal's $@spellname334929 afflicts players with a permanent wound, causing them to bleed for $s1 Physical damage every $t1 sec and increases the damage taken from $@spellname334929 by $s2%. This effect stacks.", ua = "$@spellname334929 Каала завдає гравцям незагойної рани, через що вони стікають кров'ю, отримуючи $s1 фізичної шкоди кожні $t1 с, і збільшує отримувану від $@spellname334929 шкоду на $s2%. Цей ефект накопичується." },
    { en = "At $s1% health Stone Legion Skirmisher transforms info a Stormgale Effigy, calling mighty winds to blow players away.", ua = "При $s1% здоров'я Сутичник Кам'яного Легіону перетворюється на Подобу Штормового Шквалу, прикликаючи могутні вітри, щоб здувати гравців." },
    { en = "Kaal throws a ricocheting blade at marked targets which explodes upon contact with any player, inflicting $s1 Shadow damage to players within $A1 yards. This applies $@spellname333913.", ua = "Каал кидає рикошетне лезо в позначені цілі, яке вибухає при контакті з будь-яким гравцем, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів. Це накладає $@spellname333913." },
    { en = "Stone Legion Goliath leaps at a random player, inflicting $s1 Physical damage and Stunning the player for $342735d. This is followed immediately by flurry of attacks, inflicting $342740s2 Physical damage every $t2 sec for $d.", ua = "Голіаф Кам'яного Легіону стрибає на випадкового гравця, завдаючи $s1 фізичної шкоди й оглушуючи гравця на $342735d. Одразу за цим іде шквал атак, що завдає $342740s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Increases damage taken from $@spellname344500 and $@spellname344721 by $s1% for $d.", ua = "Збільшує шкоду, отриману від $@spellname344500 та $@spellname344721, на $s1% протягом $d." },
    { en = "Grashaal's skin hardens, reducing all damage taken by $s1% until removed.", ua = "Шкіра Ґрашаала твердне, знижуючи всю отримувану шкоду на $s1%, доки ефект не буде знято." },
    { en = "Kaal slashes powerfully, inflicting $s1 Physical damage. This applies $@spellname343881.", ua = "Каал завдає потужного удару, завдаючи $s1 фізичної шкоди. Це накладає $@spellname343881." },
    { en = "Upon the death of Kaal or Grashaal, the other general swear an oath to avenge their death, increasing their damage dealt by $s1%.", ua = "Після загибелі Каал чи Грашаала інший генерал клянеться помститися за цю смерть, збільшуючи завдану шкоду на $s1%." },
    { en = "Stone Legion Goliath hungers, increasing all damage done by $s1%.", ua = "Голіат Кам'яного Легіону голодує, що збільшує всю завдану шкоду на $s1%." },
    { en = "Kaal's Wicked Blade afflict players with a permanent wound, causing them to bleed for $s1 Physical damage every $t1 sec.", ua = "Лиха клинок Каала лишає на гравцях незагойну рану, через яку вони стікають кров'ю, отримуючи $s1 фізичної шкоди кожні $t1 сек." },
    { en = "At $s1% health Stone Legion Goliath transforms info a Soultaint Effigy, afflicting all players with $@spellname343895, decreasing healing taken by $343895s1% every $t1 sec. This effect stacks up to $s3 charges.", ua = "При $s1% здоров'я Голіат Кам'яного Легіону перетворюється на Образ скверни душ, накладаючи на всіх гравців $@spellname343895, що зменшує отримане зцілення на $343895s1% кожні $t1 сек. Цей ефект накопичується до $s3 зарядів." },
    { en = "Stone Legion Commandos fly overhead, continually throwing anima bombs at players. \n\nThese bombs explode upon impact for $s1 Shadow damage to players within $A1 yards.", ua = "Командос Кам'яного Легіону пролітають над полем бою, безперервно скидаючи на гравців бомби анімою. \n\nЦі бомби вибухають при влучанні, завдаючи $s1 шкоди Тінню гравцям у радіусі $A1 ярдів." },
    { en = "Grashaal channels at a random player, inflicting $s1 Nature damage every $t1 sec for $d, triggering a $@spellname339693 after.", ua = "Ґрашаал спрямовує закляття на випадкового гравця, завдаючи $s1 шкоди від сил природи кожні $t1 сек протягом $d, після чого спрацьовує $@spellname339693." },
    { en = "Explodes the Crystalize target removing Bleed effects, stunning, and inflicting $s1 Nature damage to players within $A1 yards for $D.", ua = "Підриває ціль Кристалізації, знімаючи ефекти кровотечі, оглушуючи і завдаючи $s1 шкоди Природою гравцям у радіусі $A1 ярдів протягом $D." },
    { en = "Stone Legion Skirmisher teleports behind a random player and strikes, inflicting $s1 Physical damage and applying $@spellname333913.", ua = "Сутичник Кам'яного Легіону телепортується за спину випадкового гравця та б'є, завдаючи $s1 фізичної шкоди й накладаючи $@spellname333913." },
    { en = "Kaal summons $s1 Stone Legion Skirmishers.", ua = "Каал прикликає $s1 Сутичників Кам'яного Легіону." },
    { en = "Infuses anima into the target. This anima can be transferred to Prince Renathal to restore $332498s% of his mana.", ua = "Наповнює ціль анімою. Цю аніму можна передати Принцу Ренаталю, щоб відновити $332498s% його мани." },
    { en = "Upon the death of a Stone Legion Commando, an Anima Orb is created, lasting for $332393d. Collecting the Anima Orb bestows $@spellname332406 upon the collector.", ua = "Після загибелі командос Кам'яного Легіону створюється Сфера Аніми, що існує $332393d. Підбирання Сфери Аніми надає тому, хто її підібрав, $@spellname332406." },
    { en = "Upon the death of a Stone Legion Commando, a Volatile Anima Orb is created, lasting for $332393d. Collecting the Anima Orb bestows $@spellname332406 upon the collector.", ua = "Після загибелі командос Кам'яного Легіону створюється Нестабільна Сфера Аніми, що існує $332393d. Підбирання Сфери Аніми надає тому, хто її підібрав, $@spellname332406." },
    { en = "Volatile anima erupts from Prince Renathal's body, knocking back and inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Нестійка аніма вибухає з тіла Принца Ренаталя, відкидаючи всіх гравців у межах $A1 м і завдаючи їм $s1 шкоди від тіні." },
    { en = "Infuses volatile anima into the target, inflicting $s1 Shadow damage every $t1 sec for $d. This anima can be transferred to Prince Renathal to restore $332498s% of his mana and triggering $@spellname332412.", ua = "Наповнює ціль нестійкою анімою, завдаючи $s1 шкоди від тіні кожні $t1 сек протягом $d. Цю аніму можна передати Принцу Ренаталю, щоб відновити $332498s% його мани та спричинити $@spellname332412." },
    { en = "Perform a dark ritual in honor of Denathrius, inflicting $s1 Shadow damage to players within $a1 yds every $338688t1 sec.\n\n\n\nIncreases damage taken from Countess Gloomveil by $s2% for $d. This effect stacks.", ua = "Проводить темний ритуал на честь Денатріуса, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м кожні $338688t1 сек.\n\n\n\nЗбільшує шкоду, отриману від Графині Ґлумвейл, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "When Remornia hits a player with Impale or Massacre, she scorches the area beneath them with seething hatred for $335872d.\n\n\n\nInflicts $s1 Shadow damage every $t1 sec and increases damage taken by $s2% for players standing within.", ua = "Коли Реморнія влучає в гравця Прохромленням або Різаниною, вона випалює землю під ним кипучою ненавистю протягом $335872d.\n\n\n\nЗавдає $s1 шкоди від тіні кожні $t1 сек і збільшує отриману шкоду на $s2% для гравців, що стоять усередині." },
    { en = "When Denathrius reaches $332734s2% health, all remaining Cabalists move to the inner platform and intensify their ritual. Healing received is reduced by $s1% per Cabalist.", ua = "Коли здоров'я Денатріуса сягає $332734s2%, усі вцілілі Кабалісти переходять на внутрішній поміст і посилюють свій ритуал. Отримане зцілення зменшується на $s1% за кожного Кабаліста." },
    { en = "Denathrius pulls all players to his location and conjures an image of himself.\n\n\n\nAfter $s3 sec, the image releases destructive energy that inflicts $s1 Shadow damage to all players, reduced based on distance.", ua = "Денатріус притягує всіх гравців до себе та прикликає власний образ.\n\n\n\nЧерез $s3 сек образ вивільняє руйнівну енергію, що завдає $s1 шкоди від тіні всім гравцям; шкода зменшується залежно від відстані." },
    { en = "After casting Command: Ravage, Denathrius gains $s1% increased damage. This effect stacks.", ua = "Після застосування «Наказ: Спустошення» Денатріус завдає на $s1% більше шкоди. Цей ефект накопичується." },
    { en = "On Heroic difficulty and above, Fatal Finesse leaves behind a sphere of volatile anima that explodes after $335997d, inflicting up to $s1 Shadow damage to all players.\n\n\n\nEvery ${$335997s2/10}.1 sec, the sphere inflicts $336007s1 Shadow damage to players within $335997s1 yds, reducing its final explosion damage by the same amount.", ua = "На складності «Героїчна» та вище Фатальна вправність лишає по собі сферу нестійкої аніми, яка вибухає через $335997d, завдаючи до $s1 шкоди від тіні всім гравцям.\n\n\n\nКожні ${$335997s2/10}.1 сек сфера завдає $336007s1 шкоди від тіні гравцям у межах $335997s1 м, на стільки ж зменшуючи шкоду свого фінального вибуху." },
    { en = "After $s1 sec, the Sinister Reflection releases anima in a huge arc, inflicting $327123s1 Shadow damage to all players hit and leaving behind Desolation.", ua = "Через $s1 сек Зловісне відображення вивільняє аніму широкою дугою, завдаючи $327123s1 шкоди від тіні всім враженим гравцям і лишаючи по собі Спустошення." },
    { en = "Inflicts $s1 Physical damage to players within $A1 yds of the Night Hunter's target and heals Denathrius for ${$E1*100}% of that amount.\n\n\n\nDamage is reduced for each player in the path of the Night Hunter.", ua = "Завдає $s1 фізичної шкоди гравцям у межах $A1 м від цілі Нічного мисливця та зцілює Денатріуса на ${$E1*100}% цієї величини.\n\n\n\nШкода зменшується за кожного гравця на шляху Нічного мисливця." },
    { en = "Every $t sec, Lady Sinear releases a burst of anima missiles that scatter in all directions. Each missile inflicts $341426s1 Shadow damage to players who come in contact with it and silences them for $341426d.", ua = "Кожні $t сек Леді Грішнобій вивільняє залп снарядів аніми, що розлітаються на всі боки. Кожен снаряд завдає $341426s1 шкоди від тіні гравцям, які його торкаються, і змушує їх замовкнути на $341426d." },
    { en = "Denathrius sets his sights on random players, then slashes each of them $332794d later. Inflicts $s1 Shadow damage to players within $A1 yds of the target, plus an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Денатріус бере на приціл випадкових гравців, а через $332794d б'є кожного з них. Завдає $s1 шкоди від тіні гравцям у межах $A1 м від цілі та додатково $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "On Mythic difficulty, players hit by Cleansing Pain inflict $s1 Shadow damage to allies within $338581A1 yds. Allies with Burden of Sin lose ${$s2} $Lstack:stacks; and summon an Echo of Sin.", ua = "На складності «Міфічна» гравці, вражені Очисним болем, завдають $s1 шкоди від тіні союзникам у межах $338581A1 м. Союзники з Тягарем гріха втрачають ${$s2} $Lстак:стаки; і прикликають Відлуння гріха." },
    { en = "Remornia releases her full power to form massive blades that slash in every direction, inflicting $s1 Shadow damage to any players hit.", ua = "Реморнія вивільняє всю свою міць, утворюючи велетенські клинки, що січуть на всі боки, завдаючи $s1 шкоди від тіні всім враженим гравцям." },
    { en = "Upon reaching 100 energy, Denathrius creates an image of himself that mimics his most powerful abilities.", ua = "Сягнувши 100 одиниць енергії, Денатріус створює власний образ, що копіює його найпотужніші здібності." },
    { en = "Increases damage taken from Night Hunter by $s1%.", ua = "Збільшує шкоду, отриману від Нічного мисливця, на $s1%." },
    { en = "After $328117d, all players are pulled into the Observatorium along with Denathrius. Any player still affected by Burden of Sin falls to their violent, unavoidable death.", ua = "Через $328117d усіх гравців затягує до Обсерваторіуму разом із Денатріусом. Будь-який гравець, досі вражений Тягарем гріха, зривається назустріч жорстокій неминучій смерті." },
    { en = "Upon death, release a spectacular volley of anima toward each player. Inflicts $s1 Shadow damage to players within ${$a1}.1 yds of the impact location and knocks them back.", ua = "Після загибелі вивільняє вражаючий залп аніми в бік кожного гравця. Завдає $s1 шкоди від тіні гравцям у межах ${$a1}.1 м від місця удару та відкидає їх." },
    { en = "Echoes of Sin are immune to all forms of crowd control.", ua = "Відлуння гріха несприйнятливі до всіх форм контролю." },
    { en = "Echoes of Sin inflict $326833s1 Shadow damage to all players every $324831t1 sec.", ua = "Відлуння гріха завдають $326833s1 шкоди від тіні всім гравцям кожні $324831t1 сек." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Завдає $s1 шкоди від тіні кожні $t1 сек протягом $d. Цей ефект накопичується." },
    { en = "All players gain $326693s1 stacks of Burden of Sin at the start of the encounter. Every $t1 sec, Burden of Sin inflicts $326700s1 Shadow damage per stack.", ua = "На початку бою всі гравці отримують $326693s1 стаків Тягаря гріха. Кожні $t1 сек Тягар гріха завдає $326700s1 шкоди від тіні за кожен стак." },
    { en = "Denathrius marks random players, then strikes $327039d later. Inflicts $s1 Physical damage to players within $A1 yds of each target and heals Denathrius for ${$E1*100}% of that amount.", ua = "Денатріус позначає випадкових гравців, а через $327039d б'є. Завдає $s1 фізичної шкоди гравцям у межах $A1 м від кожної цілі та зцілює Денатріуса на ${$E1*100}% цієї величини." },
    { en = "Remornia's attacks and abilities cause affected players to bleed for $s1 Physical damage every $t1 sec for $d. This effect stacks.", ua = "Атаки та здібності Реморнії змушують вражених гравців стікати кров'ю, завдаючи $s1 фізичної шкоди кожні $t1 сек протягом $d. Цей ефект накопичується." },
    { en = "Denathrius strikes with immense cruelty, inflicting $s1 Shadow damage to players in a cone in front of him. Players with Burden of Sin lose ${$s2} $Lstack:stacks; and summon an Echo of Sin.\n\n\n\nPlayers without Burden of Sin receive ${$s3*100}% increased damage from this ability.", ua = "Денатріус б'є з нечуваною жорстокістю, завдаючи $s1 шкоди від тіні гравцям у конусі перед собою. Гравці з Тягарем гріха втрачають ${$s2} $Lстак:стаки; і прикликають Відлуння гріха.\n\n\n\nГравці без Тягаря гріха отримують на ${$s3*100}% більше шкоди від цієї здібності." },
    { en = "As Indignation is cast, the mirrors in the room begin to warp.\n\n\n\nWhat awaits players who pass through a mirror during this time is known only to Denathrius himself.", ua = "Коли застосовано Обурення, дзеркала в залі починають викривлятися.\n\n\n\nЩо чекає на гравців, які пройдуть крізь дзеркало в цей час, відомо лише самому Денатріусу." },
    { en = "Denathrius wields Remornia. He attacks $s2% slower, but his attacks inflict $s1% more damage and apply Scorn.", ua = "Денатріус володіє Реморнією. Він атакує на $s2% повільніше, проте його атаки завдають на $s1% більше шкоди й накладають Зневагу." },
    { en = "Lingering Anima reduces all healing received by $s2% and inflicts $s1 Shadow damage every $t1 sec to players who stand within it.", ua = "Залишкова аніма зменшує все отримане зцілення на $s2% і завдає $s1 шкоди від тіні кожні $t1 сек гравцям, що стоять усередині неї." },
    { en = "Crimson Cabalists channel a dark ritual that inflicts $s1 Shadow damage per Cabalist to all players every $t1 sec.", ua = "Багряні Кабалісти спрямовують темний ритуал, що завдає $s1 шкоди від тіні за кожного Кабаліста всім гравцям кожні $t1 сек." },
    { en = "Upon reaching 100 energy, Denathrius commands Remornia to unleash a series of deadly attacks.", ua = "Сягнувши 100 одиниць енергії, Денатріус наказує Реморнії вивільнити низку смертоносних атак." },
    { en = "Upon reaching 100 energy, Denathrius commands Remornia to unleash stored Anima against players.", ua = "Сягнувши 100 одиниць енергії, Денатріус наказує Реморнії вивільнити накопичену аніму проти гравців." },
    { en = "The Sinister Reflection forms massive blades that slash in every direction, inflicting $330137s1 Shadow damage to any players hit.", ua = "Зловісне відображення утворює велетенські клинки, що січуть на всі боки, завдаючи $330137s1 шкоди від тіні всім враженим гравцям." },
    { en = "Upon reaching $s2% health, Denathrius disables all mirrors and traps players within a twisting maelstrom of anima that inflicts $s1 Shadow damage every $t1 sec to players who attempt to escape.", ua = "Сягнувши $s2% здоров'я, Денатріус вимикає всі дзеркала й замикає гравців у бурхливому вирі аніми, що завдає $s1 шкоди від тіні кожні $t1 сек гравцям, які намагаються вирватися." },
    { en = "Denathrius torments players with Burden of Sin, rendering them unable to move or act for $d.\n\n\n\nWhen this effect expires, each player is knocked away from Denathrius and explodes for $326858s1 Shadow damage to all players who have the same number of Burden of Sin stacks.", ua = "Денатріус мучить гравців Тягарем гріха, позбавляючи їх змоги рухатися чи діяти на $d.\n\n\n\nКоли цей ефект спадає, кожного гравця відкидає від Денатріуса й він вибухає, завдаючи $326858s1 шкоди від тіні всім гравцям з такою самою кількістю стаків Тягаря гріха." },
    { en = "A horrific wail that inflicts $s1 Shadow damage and interrupts spellcasting for $d.", ua = "Жахливий зойк, що завдає $s1 шкоди від тіні та перериває творення заклять на $d." },
    { en = "Denathrius performs a series of deadly attacks, slashing his target for $332620s1% weapon damage $s1 times over $d. He then finishes with a devastating blow that inflicts $332626s1 Shadow damage to all players and knocks them back.", ua = "Денатріус проводить низку смертоносних атак, шматуючи свою ціль на $332620s1% шкоди зброї $s1 разів протягом $d. Тоді він завершує нищівним ударом, що завдає $332626s1 шкоди від тіні всім гравцям і відкидає їх." },
    { en = "Countess Gloomveil envelops herself in a shroud of anima.\n\n\n\nPlayers are unable to target into or out of the shroud.", ua = "Графиня Ґлумвейл огортає себе серпанком аніми.\n\n\n\nГравці не можуть брати на приціл цілі крізь серпанок — ані ззовні всередину, ані зсередини назовні." },
    { en = "If not destroyed within $d, Echoes of Sin return to the players who created them and re-apply Burden of Sin.", ua = "Якщо Відлуння гріха не знищити протягом $d, вони повертаються до гравців, які їх створили, і знову накладають Тягар гріха." },
    { en = "After $s1 sec, Remornia releases anima in a huge arc, inflicting $327123s1 Shadow damage to all players hit and filling the area with Desolation.", ua = "Через $s1 сек Реморнія вивільняє аніму широкою дугою, завдаючи $327123s1 шкоди від тіні всім ураженим гравцям і заповнюючи територію Спустошенням." },
    { en = "Upon reaching $s3% health, Denathrius draws all players to the center of the room, then casts them outward to the edges.\n\n\n\nPlayers affected by Burden of Sin have their movement speed slowed by $s1% per stack and are unable to use abilities.\n\n\n\nMoving within $328117s2 yds of Denathrius absolves players of their Burden of Sin.", ua = "Сягнувши $s3% здоров'я, Денатріус притягує всіх гравців до центру зали, а потім жбурляє їх назовні до країв.\n\n\n\nГравцям, враженим Тягарем гріха, швидкість руху зменшено на $s1% за кожен стак, і вони не можуть застосовувати здібності.\n\n\n\nНаблизившись до Денатріуса на $328117s2 м, гравець звільняється від свого Тягаря гріха." },
    { en = "Remornia draws strength from Denathrius' life force. Any damage she takes is also taken by Denathrius.", ua = "Реморнія черпає силу з життєвої сили Денатріуса. Будь-яку шкоду, якої зазнає вона, зазнає й Денатріус." },
    { en = "Denathrius strikes with immense power, inflicting $s1 Shadow damage to players and cabalists in the direction of his current target and increasing all damage they take by $s2% for $d.", ua = "Денатріус б'є з нечуваною міццю, завдаючи $s1 шкоди від тіні гравцям і кабалістам у напрямку своєї поточної цілі та збільшуючи всю отримувану ними шкоду на $s2% протягом $d." },
    { en = "Whenever Denathrius is unable to reach his target, he shifts through the shadows to their location and strikes them for $s1% weapon damage.", ua = "Щоразу, коли Денатріус не може дістати свою ціль, він проходить крізь тіні до її місця й б'є, завдаючи $s1% шкоди зброї." },
    { en = "Whenever Remornia is unable to reach her target, she shifts through the shadows to their location and strikes them for $s1% weapon damage.", ua = "Щоразу, коли Реморнія не може дістати свою ціль, вона проходить крізь тіні до її місця й б'є, завдаючи $s1% шкоди зброї." },
    { en = "Denathrius creates images of himself that mark random players, then charge to them $d later. Each image inflicts $327810s1 Physical damage and applies Touch of the Night to all players in their path.\n\n\n\nUpon reaching their target, they strike with Insatiable Hunger.", ua = "Денатріус створює власні образи, що позначають випадкових гравців, а через $d кидаються на них. Кожен образ завдає $327810s1 фізичної шкоди й накладає Дотик Ночі на всіх гравців на своєму шляху.\n\n\n\nСягнувши цілі, образи б'ють Невситимою Жагою." },
    { en = "When a player further than $s1 yds away attacks Baron Duskhollow, he reaches through the shadows and pulls them to his location.", ua = "Коли гравець, віддалений більш ніж на $s1 м, атакує Барона Даскголлоу, той сягає крізь тіні й притягує його до свого місця." },
    { en = "Remornia marks random players, then impales each of them a few seconds later. Inflicts $s1 Physical damage to all players in her path.", ua = "Реморнія позначає випадкових гравців, а через кілька секунд прохромлює кожного з них. Завдає $s1 фізичної шкоди всім гравцям на своєму шляху." },
    { en = "Upon reaching $s1% and $s2% health, Lord Evershade summons Baleful Shadows.", ua = "Сягнувши $s1% та $s2% здоров'я, Лорд Вічнотінь прикликає Лиховісні Тіні." },
    { en = "Perform a dark ritual in honor of Denathrius, inflicting $s1 Shadow damage to players within $a1 yds every $338677t1 sec.\n\n\n\nIncreases damage taken from Lady Sinsear by $s2% for $d. This effect stacks.", ua = "Проводить темний ритуал на честь Денатріуса, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м кожні $338677t1 сек.\n\n\n\nЗбільшує шкоду, отриману від Леді Грішнобій, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Denathrius torments all players, rendering them unable to move or act for $326851d.\n\n\n\nWhen this effect expires, each player is knocked away from Denathrius and explodes for $326858s1 Shadow damage to all players.", ua = "Денатріус мучить усіх гравців, позбавляючи їх змоги рухатися чи діяти на $326851d.\n\n\n\nКоли цей ефект спадає, кожного гравця відкидає від Денатріуса й він вибухає, завдаючи $326858s1 шкоди від тіні всім гравцям." },
    { en = "Perform a dark ritual in honor of Denathrius, inflicting $s1 Shadow damage to players within $a1 yds every $338684t1 sec.\n\n\n\nIncreases damage taken from Lord Evershade by $s2% for $d. This effect stacks.", ua = "Проводить темний ритуал на честь Денатріуса, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м кожні $338684t1 сек.\n\n\n\nЗбільшує шкоду, отриману від Лорда Вічнотінь, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Perform a dark ritual in honor of Denathrius, inflicting $s1 Shadow damage to players within $a1 yds every $338686t1 sec.\n\n\n\nIncreases damage taken from Baron Duskhollow by $s2% for $d. This effect stacks.", ua = "Проводить темний ритуал на честь Денатріуса, завдаючи $s1 шкоди від тіні гравцям у межах $a1 м кожні $338686t1 сек.\n\n\n\nЗбільшує шкоду, отриману від Барона Даскголлоу, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Echoing rage fills the caster, increasing damage done by $s2% and haste by $s1% for $d.", ua = "Відлунна лють сповнює мовця, підвищуючи завдану шкоду на $s2% і поспіх на $s1% на $d." },
    { en = "The Tarragrue focuses its gaze upon a player. After $d, the chains fly in their direction and stun the first target struck, inflicting $354173s1 Physical damage and pulling them in for an $@spellname347274.", ua = "Тарраґру спрямовує погляд на гравця. Через $d ланцюги летять у його бік і приголомшують першу вражену ціль, завдаючи $354173s1 фізичної шкоди і притягуючи її для $@spellname347274." },
    { en = "Mort'regar's Echoes increase Magic damage done by the Jailer's forces by $s1%. A player may lessen this effect by absorbing some of the Torment. This causes the player to take $352387s1% increased Magic damage for $352387d.", ua = "Відлуння Морт'реґара підвищують магічну шкоду, що завдають сили Тюремника, на $s1%. Гравець може послабити цей ефект, увібравши частину Мук. Через це гравець отримує на $352387s1% більше магічної шкоди на $352387d." },
    { en = "The Tarragrue roars in triumph after killing a player.", ua = "Тарраґру переможно реве після вбивства гравця." },
    { en = "The Tarragrue slams its target, inflicting $s1 Physical damage and stunning it for $d. This strike applies $@spellname346986.", ua = "Тарраґру вдаряє свою ціль, завдаючи $s1 фізичної шкоди і приголомшуючи її на $d. Цей удар накладає $@spellname346986." },
    { en = "The Tarragrue pulverizes to dust those caught by its chains, inflicting $s1 Physical damage and stunning them for $d.", ua = "Тарраґру стирає на порох тих, кого спіймали його ланцюги, завдаючи $s1 фізичної шкоди і приголомшуючи їх на $d." },
    { en = "Increases Physical damage taken by $s1% for $d.", ua = "Підвищує отриману фізичну шкоду на $s1% на $d." },
    { en = "At $s1% health remaining, The Tarragrue calls out to the Jailer. This removes all Anima Powers from players and grants The Tarragrue an additional $s2% damage done until it dies.", ua = "Коли лишається $s1% здоров'я, Тарраґру кличе Тюремника. Це знімає з гравців усі сили аніми й дарує Тарраґру додаткові $s2% завданої шкоди до самої його смерті." },
    { en = "Soulforge Heat periodically inflicts $352397s1 Fire damage to all players. A player may lessen this effect by absorbing some of the Torment. This causes the player to take $352392s1 Fire damage every $352392t1 sec for $352392d.", ua = "Жар Душокузні періодично завдає $352397s1 шкоди вогнем усім гравцям. Гравець може послабити цей ефект, увібравши частину Мук. Через це гравець отримує $352392s1 шкоди вогнем кожні $352392t1 сек. на $352392d." },
    { en = "The Jailer calls down the memory of a forgotten Torment, which assaults players until it is absorbed.", ua = "Тюремник прикликає пам'ять про забуту Муку, що нападає на гравців, доки її не увібрано." },
    { en = "The Tarragrue howls, causing an aura of dread to form around players for $d. This causes each target to radiate $@spellname347286 to other players within $347286A1 yds every $t1 sec.", ua = "Тарраґру виє, утворюючи навколо гравців ауру жаху на $d. Через це кожна ціль випромінює $@spellname347286 на інших гравців у межах $347286A1 м кожні $t1 сек." },
    { en = "The Jailer's grasp tightens around players, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Хватка Тюремника стискається навколо гравців, завдаючи $s1 шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "Causes the target to flee in fear for $d.", ua = "Змушує ціль тікати в страху на $d." },
    { en = "The Tarragrue dissolves into the mists of Torghast, forming several images. These images erupt and inflict $s1 Shadow damage to all players within $A1 yds.", ua = "Тарраґру розчиняється в туманах Торгаста, утворюючи кілька образів. Ці образи вибухають і завдають $s1 шкоди від тіні всім гравцям у межах $A1 м." },
    { en = "The Might of the Upper Reaches increases Physical damage done by the Jailer's forces by $s1%. A player may lessen this effect by absorbing some of the Torment. This causes the player to take $352384s1% increased Physical damage for $352384d.", ua = "Міць Верхніх Обширів підвищує фізичну шкоду, що завдають сили Тюремника, на $s1%. Гравець може послабити цей ефект, увібравши частину Мук. Через це гравець отримує на $352384s1% більше фізичної шкоди на $352384d." },
    { en = "The Eye of the Jailer corrupts a player with dark energy. All players within 8 yards of the target have their movement speed reduced by $350606s2% and take $350606s1 Shadow damage every $350606t1 sec.", ua = "Око Тюремника опоганює гравця темною енергією. Усім гравцям у межах 8 м від цілі швидкість руху знижується на $350606s2%, і вони отримують $350606s1 шкоди від тіні кожні $350606t1 сек." },
    { en = "The Deathseeker Eyes flanking the Eye of the Jailer inflict $s1 Shadow damage to random targets.", ua = "Очі шукачів смерті, що оточують Око Тюремника, завдають $s1 шкоди від тіні випадковим цілям." },
    { en = "The Stygian Abductor unleashes chains at their target and all players within $A1 yards, inflicting $s3 Shadow damage divided evenly among all players struck.\n\n\n\nIn addition, the Abductor begins to pull each hit target off the platform. The force of this effect is reduced by the number of players being chained. After struggling for $d, the Abductor is pulled from the skies.", ua = "Стигійський викрадач шмагає ланцюгами свою ціль і всіх гравців у межах $A1 м, завдаючи $s3 шкоди від тіні, що порівну розподіляється між усіма враженими гравцями.\n\n\n\nКрім того, викрадач починає стягувати кожну вражену ціль із платформи. Сила цього ефекту слабшає залежно від кількості закутих у ланцюги гравців. Після $d боротьби викрадача стягують із небес." },
    { en = "Ejected Deathseeker Eyes afflict players within 70 yards with applications of $@spellname355240 or $@spellname355245.\n\n\n\nWhen a player with $@spellname355240 collides with a player with $@spellname355245, it causes $@spellname355246.", ua = "Викинуті очі шукачів смерті уражають гравців у межах 70 м застосуваннями $@spellname355240 або $@spellname355245.\n\n\n\nКоли гравець із $@spellname355240 стикається з гравцем із $@spellname355245, це спричиняє $@spellname355246." },
    { en = "Scorn fills the player's soul, inflicting $s1 Shadow damage every $t1 sec. for $d. This effect stacks.\n\n\n\nRunning into a player afflicted with $@spellname355245 will cause a $@spellname355246.", ua = "Зневага сповнює душу гравця, завдаючи $s1 шкоди від тіні кожні $t1 сек. на $d. Цей ефект накопичується.\n\n\n\nЗіткнення з гравцем, ураженим $@spellname355245, спричинить $@spellname355246." },
    { en = "Launches a harpoon to grapple across the gap!", ua = "Запускає гарпун, щоб перебратися через прірву!" },
    { en = "Once grounded, Stygian Abductors throw their lance at their current target, inflicting $s1 Physical damage and causes their target to bleed for $s2 Physical damage every $t2 sec for $d. This effect stacks.", ua = "Приземлившись, стигійські викрадачі кидають списа в свою поточну ціль, завдаючи $s1 фізичної шкоди і змушуючи ціль кровоточити, завдаючи $s2 фізичної шкоди кожні $t2 сек. на $d. Цей ефект накопичується." },
    { en = "The Eye of the Jailer channels a powerful beam of energy and sweeps its gaze across the platform, inflicting $s1 Shadow damage every $t1 sec. and knocking back any targets who stand in it.", ua = "Око Тюремника спрямовує потужний промінь енергії й веде поглядом по платформі, завдаючи $s1 шкоди від тіні кожні $t1 сек. і відкидаючи всіх, хто стоїть на його шляху." },
    { en = "The Eye of the Jailer attempts to wipe out all mortal life around it, permanently increasing its attack rate by $s2%. In addition, the soul draining effects increase every $t1 sec, inflicting a blast of $353591s1 Shadow damage and reducing healing received by players by $348969s1% until the end of the encounter.", ua = "Око Тюремника намагається винищити все смертне життя навколо себе, назавжди збільшуючи свою швидкість атаки на $s2%. Крім того, ефекти висмоктування душі посилюються кожні $t1 сек, завдаючи спалах $353591s1 шкоди від тіні та зменшуючи зцілення, отримуване гравцями, на $348969s1% до кінця бою." },
    { en = "Ire fills the player's soul, inflicting $s1 Shadow damage every $t1 sec. for $d. This effect stacks.\n\n\n\nRunning into a player afflicted with $@spellname355240 will cause a $@spellname355246.", ua = "Гнів сповнює душу гравця, завдаючи $s1 шкоди від тіні кожні $t1 сек. на $d. Цей ефект накопичується.\n\n\n\nЗіткнення з гравцем, ураженим $@spellname355240, спричинить $@spellname355246." },
    { en = "Hateful energies coalesce into a massive explosion, inflicting $s1 Shadow damage to all players within $A1 yards of the explosion and $s2 Shadow damage to all other players.", ua = "Сповнені ненависті енергії зливаються в потужний вибух, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 м від вибуху і $s2 шкоди від тіні всім іншим гравцям." },
    { en = "When Deathseekers are within $s1 yards of each other they cast $@spellname351826 every $t1 sec.", ua = "Коли Шукачі Смерті перебувають у межах $s1 ярдів один від одного, вони творять $@spellname351826 кожні $t1 сек." },
    { en = "The Eye of the Jailer unleashes a beam of shadowy energy at a random player, inflicting $s1 Shadow damage before leaping to nearby allies.", ua = "Око Тюремника випускає промінь тіньової енергії у випадкового гравця, завдаючи $s1 шкоди від тіні, перш ніж перескочити на сусідніх союзників." },
    { en = "The Eye of the Jailer unleashes a surge of soul energy at the feet of random players, inflicting $s1 Shadow damage to all players within $A1 yards of the impact. Players damaged by this effect have their soul split into three Fractured Souls.", ua = "Око Тюремника випускає сплеск енергії душ під ноги випадковим гравцям, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 м від місця удару. У гравців, уражених цим ефектом, душа розколюється на три розколоті душі." },
    { en = "Soul Shards torment the afflicted player until they are touched, inflicting $s1 Shadow damage every $t1 sec, reduce movement speed by $s2%, and reduce damage and healing done by $s3%. This effect stacks.", ua = "Уламки душі мучать ураженого гравця, доки до них не торкнуться, завдаючи $s1 шкоди від тіні кожні $t1 сек., знижуючи швидкість руху на $s2% і знижуючи завдану шкоду й зцілення на $s3%. Цей ефект накопичується." },
    { en = "The Eye of the Jailer propels a sharp pinpoint of force at its current target, inflicting $s1 Physical damage.", ua = "Око Тюремника метає гострий пучок сили в свою поточну ціль, завдаючи $s1 фізичної шкоди." },
    { en = "The Deathseeker Eye unleashes a blast of corrupting energy inflicting $s1 Shadow damage to all players and increasing their Shadow damage taken by $s2% for $d. This effect stacks.", ua = "Око шукача смерті випускає спалах опоганливої енергії, завдаючи $s1 шкоди від тіні всім гравцям і підвищуючи отриману ними шкоду від тіні на $s2% на $d. Цей ефект накопичується." },
    { en = "Creates a pool of condensed evil that lasts for $d, inflicting $350809s1 Shadow damage to all players in the zone every $350809t1 sec.", ua = "Створює калюжу згущеного зла, що триває $d, завдаючи $350809s1 шкоди від тіні всім гравцям у зоні кожні $350809t1 сек." },
    { en = "The Deathseeker Eye spreads misery into the souls of random targets, inflicting $351827s1 Shadow damage every $351827t1 sec. for $351827d. \n\n\n\nUpon removal, the misery spreads to the ground beneath the target, leaving a pool of Jailer's Misery.", ua = "Око шукача смерті сіє лихо в душах випадкових цілей, завдаючи $351827s1 шкоди від тіні кожні $351827t1 сек. на $351827d.\n\n\n\nПісля зняття лихо розливається по землі під ціллю, лишаючи калюжу Лиха Тюремника." },
    { en = "The Eye of the Jailer focuses its energy into a massive blast, inflicting $s1 Shadow damage to all players.", ua = "Око Тюремника зосереджує свою енергію в потужний спалах, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "The Eye of the Jailer unleashes dark energies at its current target inflicting $351143s1 Physical damage, and increasing damage taken from Deathlink by $351143s2% for $351143d.\n\n\n\nIn addition, the impact radiates a portion of the damage inflicted to all other players as Shadow damage.", ua = "Око Тюремника випускає темні енергії у свою поточну ціль, завдаючи $351143s1 фізичної шкоди й підвищуючи шкоду, отриману від Смертозв'язку, на $351143s2% на $351143d.\n\n\n\nКрім того, удар випромінює частину завданої шкоди всім іншим гравцям як шкоду від тіні." },
    { en = "The Eye of the Jailer ejects two Deathseeker Eyes and cloaks itself in a Stygian Shield, inflicting $s1 Shadow damage to players at the landing locations of the eyes.", ua = "Око Тюремника викидає двоє очей шукачів смерті й огортається в стигійський щит, завдаючи $s1 шкоди від тіні гравцям у місцях приземлення очей." },
    { en = "Deathseeker Eyes propels a sharp pinpoint of force at a target, inflicting $s1 Physical damage.", ua = "Очі шукачів смерті метають гострий пучок сили в ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Fatigues random targets with $s1 Shadow damage every $t sec. for $d,  reducing spell casting, ranged attack speed, and movement by $s2%.", ua = "Виснажує випадкові цілі, завдаючи $s1 шкоди від тіні кожні $t сек. на $d і знижуючи швидкість прочитання заклять, швидкість дальніх атак і пересування на $s2%." },
    { en = "Dead Deathseekers cast Suffering every $t1 sec. while another Deathseeker is alive on the platform.", ua = "Мертві шукачі смерті творять Страждання кожні $t1 сек., доки на платформі живий ще один шукач смерті." },
    { en = "The Eye of the Jailer unleashes a beam of shadowy energy at a random player, inflicting $s1 Shadow damage before leaping to nearby allies for increased damage.", ua = "Око Тюремника вивільняє промінь тіньової енергії у випадкового гравця, завдаючи $s1 шкоди від тіні, а тоді перестрибує на сусідніх союзників із посиленою шкодою." },
    { en = "The Formless Mass devours life from all players, inflicting $s1 Shadow damage to them and healing the Formless Mass for the same amount.", ua = "Безформна Маса пожирає життя всіх гравців, завдаючи їм $s1 шкоди від тіні та зцілюючи Безформну Масу на ту саму величину." },
    { en = "Skyja calls for her fallen compatriots, drawing some of them forth to attack players.", ua = "Скія кличе своїх полеглих соратниць, виводячи декого з них наперед, щоб напасти на гравців." },
    { en = "Skyja pierces the soul of her target, inflicting $s1 Physical damage. This effect reduces the target's movement speed by $s2% and healing received by $s3% for $d. This effect stacks.", ua = "Скія пронизує душу своєї цілі, завдаючи $s1 фізичної шкоди. Цей ефект знижує швидкість пересування цілі на $s2% та отримане зцілення на $s3% упродовж $d. Цей ефект накопичується." },
    { en = "Aradne marks several locations for a falling slash. After $350083d, she strikes those locations, inflicting $s1 Shadow damage. For each location, if no players are struck, she instead inflicts $350099s1 Shadow damage to all players.", ua = "Арадна позначає кілька місць для падаючого удару. За $350083d вона б'є по цих місцях, завдаючи $s1 шкоди від тіні. Якщо в якомусь місці не влучено в гравців, вона натомість завдає $350099s1 шкоди від тіні всім гравцям." },
    { en = "Skyja links the souls of players together. If any of the players take damage, they radiate $s1% of that damage split among all other linked players.", ua = "Скія зв'язує душі гравців докупи. Якщо хтось із цих гравців отримує шкоду, він випромінює $s1% цієї шкоди, розподіленої між усіма іншими зв'язаними гравцями." },
    { en = "Brynja marks players with a death song, inflicting $s1 Shadow damage every $t1 sec for $d. Upon expiration, the song inflicts $351142s1 Shadow damage to other players within $351142A1 yds.", ua = "Брин'я позначає гравців піснею смерті, завдаючи $s1 шкоди від тіні кожні $t1 с упродовж $d. Після закінчення пісня завдає $351142s1 шкоди від тіні іншим гравцям у межах $351142A1 м." },
    { en = "Upon reaching 100 energy, Kyra beats her wings for $d, pulling all players to her location. Upon completion, Kyra lashes out and inflicts $350374s1 Physical damage to all players within $350374A1 yds, stunning them for $350374d.", ua = "Сягнувши 100 енергії, Кіра б'є крилами впродовж $d, притягуючи всіх гравців до свого місця. Після завершення Кіра завдає шаленого удару, наносячи $350374s1 фізичної шкоди всім гравцям у межах $350374A1 м та оглушуючи їх на $350374d." },
    { en = "Skyja releases negative emotions, inflicting $351399s1 Shadow damage to all players every $t1 sec for $d.", ua = "Скія вивільняє негативні емоції, завдаючи $351399s1 шкоди від тіні всім гравцям кожні $t1 сек протягом $d." },
    { en = "Upon reaching 100 energy, Signe sings of the end for $d, pushing all players away from her location. Upon completion, Signe crescendoes and inflicts $350374s1 Shadow damage to all players further than $350374A1 yds, causing them to flee in fear for $350462d.", ua = "Досягнувши 100 енергії, Сіґне співає про кінець протягом $d, відштовхуючи всіх гравців від свого місця. По завершенні Сіґне сягає кульмінації й завдає $350374s1 тіньової шкоди всім гравцям далі ніж $350374A1 ярд., змушуючи їх тікати в страху протягом $350462d." },
    { en = "Signe blasts her target with dark energy, inflicting $s1 Shadow damage.", ua = "Сіґне вражає свою ціль темною енергією, завдаючи $s1 шкоди від тіні." },
    { en = "Annhylde creates a shield of protective energy for her allies for $d, reducing damage taken by 90%.", ua = "Аннгільда створює щит захисної енергії для своїх союзників на $d, зменшуючи отриману шкоду на 90%." },
    { en = "Icy fragments form around random players, inflicting $350542s1 Frost damage every $350542t1 sec. When dispelled, these fragments jump to the nearest player. \n\n\n\nIf all fragments are on the same player, they are removed to form a Shard of Destiny.", ua = "Навколо випадкових гравців утворюються крижані уламки, що завдають $350542s1 шкоди від холоду кожні $350542t1 с. Коли їх розвіюють, ці уламки перестрибують на найближчого гравця.\n\n\n\nЯкщо всі уламки опиняються на одному гравцеві, вони зникають, утворюючи Скалку Долі." },
    { en = "Signe sings a shredding song that intensifies every $350286t1 sec for $350286d. This effect inflicts $s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Сіґне співає роздираючу пісню, що посилюється кожні $350286t1 с упродовж $350286d. Цей ефект завдає $s1 шкоди від тіні кожні $t1 с упродовж $d. Цей ефект накопичується." },
    { en = "Agatha forms several images to slash out in straight lines through the area, inflicting $s1 Physical damage and knocking the target back.", ua = "Аґата створює кілька образів, що завдають ударів прямими лініями крізь зону бою, наносячи $s1 фізичної шкоди та відкидаючи ціль назад." },
    { en = "Arthura focuses the chill of Icecrown upon a player. After $d, she slams the ground and inflicts $350040s1 Frost damage divided evenly between all players within $350040A1 yds.", ua = "Артура зосереджує холод Крижаної Корони на гравцеві. За $d вона вдаряє об землю й завдає $350040s1 шкоди від холоду, рівномірно розподіленої між усіма гравцями в межах $350040A1 м." },
    { en = "Standing within $s4 yds of a $@spellname350555 inflicts $s2 Frost damage every $t2 sec and reduces movement speed by $s1%.", ua = "Перебування в межах $s4 м від $@spellname350555 завдає $s2 шкоди від холоду кожні $t2 с та знижує швидкість пересування на $s1%." },
    { en = "Skyja instantly recalls her previous commands for Call of the Val'kyr.", ua = "Скія миттєво відкликає свої попередні накази для Поклику Валькір." },
    { en = "Icy fragments form around random players, inflicting $350542s1 Frost damage every $350542t1 sec. When dispelled, these fragments jump to the nearest player. \n\n\n\nIf all fragments are on the same player, they are removed and form a Shard of Destiny.", ua = "Навколо випадкових гравців утворюються крижані уламки, що завдають $350542s1 шкоди від холоду кожні $350542t1 с. Коли їх розвіюють, ці уламки перестрибують на найближчого гравця.\n\n\n\nЯкщо всі уламки опиняються на одному гравцеві, вони зникають і утворюють Скалку Долі." },
    { en = "Dashcla takes aim at players with a mighty blast above, inflicting $350185s1 Shadow damage to targets within $350185A1 yds of the impact locations.", ua = "Дашкла бере гравців на приціл для могутнього удару згори, завдаючи $350185s1 шкоди від тіні цілям у межах $350185A1 м від місць влучання." },
    { en = "Upon reaching 100 energy, Signe sings of the end for $d and pushes away all players. Upon completion, $@spellname350385 inflicts $350374s1 Shadow damage to all players further than $350374A1 yds, causing them to flee in fear for $350462d.", ua = "Сягнувши 100 енергії, Сіґне співає про кінець протягом $d і відштовхує всіх гравців. По завершенні «$@spellname350385» завдає $350374s1 од. шкоди від магії Тіні всім гравцям далі ніж за $350374A1 ярдів, змушуючи їх тікати у страху протягом $350462d." },
    { en = "Upon reaching 100 energy, Kyra beats her wings for $d and pulls in all players. Upon completion, $@spellname350365 inflicts $350374s1 Physical damage to all players within $350374A1 yds, stunning them for $350374d.", ua = "Сягнувши 100 енергії, Кіра б'є крилами впродовж $d і притягує всіх гравців. Після завершення $@spellname350365 завдає $350374s1 фізичної шкоди всім гравцям у межах $350374A1 м, оглушуючи їх на $350374d." },
    { en = "Kyra slashes out with her blade, causing the target to suffer $s1 Physical damage and take $s2% increased damage for $d. This effect stacks.\n\n\n\nIn addition, $@spellname350206 strikes all players, inflicting $350206s1 Physical damage for each application.", ua = "Кіра завдає удару клинком, наносячи цілі $s1 фізичної шкоди та змушуючи її отримувати на $s2% більше шкоди впродовж $d. Цей ефект накопичується.\n\n\n\nКрім того, $@spellname350206 вражає всіх гравців, завдаючи $350206s1 фізичної шкоди за кожне накладення." },
    { en = "Spectral blades slash out at a player, inflicting $s1 Physical damage.", ua = "Примарні клинки вражають гравця, завдаючи $s1 фізичної шкоди." },
    { en = "At 100 energy, the Remnant of Ner'zhul unleashes a blast of energy at their current target, inflicting $s1 Shadow damage to all players caught in a line and increasing their damage taken from Suffering by $s2% for $d.\n\n\n\nOrbs of Torment caught in the effect lose the effect of Eternal Torment and become vulnerable.", ua = "При 100 енергії Рештки Нер'зула вивільняють вибух енергії по поточній цілі, завдаючи $s1 тіньової шкоди всім гравцям на лінії та збільшуючи отримувану ними шкоду від Страждання на $s2% протягом $d.\n\n\n\nСфери Муки, що потрапили під дію, втрачають ефект Вічної Муки й стають вразливими." },
    { en = "The Remnant of Ner'zhul afflicts random targets with Malevolence for $d. When this effect is removed all players are knocked back from the victim's location and take $350427s2 Shadow damage.", ua = "Рештки Нер'зула вражають випадкові цілі Зловмисністю протягом $d. Коли цей ефект знімають, усіх гравців відкидає від місця жертви, і вони отримують $350427s2 тіньової шкоди." },
    { en = "The burst of Malevolence leaves an area that inflicts $350489s1 Shadow damage every sec to players standing within its confines.", ua = "Спалах Злостивості лишає по собі ділянку, що завдає $350489s1 шкоди від тіні щосекунди гравцям, які стоять у її межах." },
    { en = "While active the Orb of Torment takes $s2% reduced damage from all sources.\n\n\n\nThis effect is removed when the Orb of Torment is struck by $@spellname350337.", ua = "Поки Сфера Мук активна, вона отримує на $s2% менше шкоди з усіх джерел.\n\n\n\nЦей ефект знімається, коли по Сфері Мук влучає $@spellname350337." },
    { en = "The Remnant of Ner'zhul is wrapped in throes of pain that inflict $350672s1 Shadow damage to all players every $t1 sec.\n\n\n\nOnce the first armor piece is shattered away, Aura of Spite periodically unleashes a barrage of missiles at random players.", ua = "Рештки Нер'зула охоплені корчами болю, що завдають $350672s1 шкоди від тіні всім гравцям кожні $t1 с.\n\n\n\nЩойно перший елемент обладунку розбито, Аура Лютості періодично вивільняє град снарядів у випадкових гравців." },
    { en = "The Remnant of Ner'zhul's pain manifests as missiles of shadowy energy that inflict $s1 Shadow damage to all players within $A1 yards of the impact and renders them unable to attack or cast spells for $d.", ua = "Біль Решток Нер'зула проявляється як снаряди тіньової енергії, що завдають $s1 шкоди від тіні всім гравцям у межах $A1 м від влучання та позбавляють їх змоги атакувати чи творити закляття впродовж $d." },
    { en = "Once slain, players can pick up the Orb of Torment and carry it to the edge of the platform to throw it into the abyss.\n\n\n\nWhile holding the Orb of Torment your soul is weakend, inflicting $s1 Shadow damage every $t1 sec and reducing movement speed by $s2%.", ua = "Після вбивства гравці можуть підняти Сферу Муки й віднести її до краю платформи, щоб скинути в безодню.\n\n\n\nПоки ви тримаєте Сферу Муки, ваша душа ослаблена: вам завдається $s1 тіньової шкоди кожні $t1 сек. і знижується швидкість пересування на $s2%." },
    { en = "The Orb of Torment corrupts several players, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Сфера Мук опоганює кількох гравців, завдаючи $s1 шкоди від тіні кожні $t1 с упродовж $d." },
    { en = "At 80%, 60%, and 30% health remaining a piece of the armor restraining the Remnant of Ner'zhul is destroyed, unleashing a wave of energy that inflicts $s2 Shadow damage to all players.", ua = "На 80%, 60% та 30% решти здоров'я знищується частина обладунку, що сковує Рештки Нер'зула, вивільняючи хвилю енергії, яка завдає $s2 шкоди від тіні всім гравцям." },
    { en = "The Remnant of Ner'zhul unfurls ethereal fingers that erupt, inflicting $s1 Shadow damage to all players caught in the effect, knocking them back.", ua = "Рештки Нер'зула простягають ефірні пальці, що вибухають, завдаючи $s1 тіньової шкоди всім гравцям під дією ефекту й відкидаючи їх." },
    { en = "Soulrender Dormazain introduces Garrosh to a new level of torment, causing multiple waves of Anima to surge forth from him at once, inflicting $350217s1 Shadow damage and an additional $350217s2 Shadow damage every $350217t2 sec for $350217d to players caught in their wake. This effect stacks.", ua = "Душороздирач Дормазейн відкриває Ґаррошу новий рівень мук, змушуючи кілька хвиль аніми ринути з нього водночас, завдаючи $350217s1 шкоди від тіні та додатково $350217s2 шкоди від тіні кожні $350217t2 с упродовж $350217d гравцям на їхній траєкторії. Цей ефект накопичується." },
    { en = "Mawsworn Agonizers billow waves of agony, inflicting $s1 Shadow damage and reducing the movement speed of all players by $s2% for $d. This effect stacks.", ua = "Стражденники Пащі здіймають хвилі агонії, завдаючи $s1 шкоди від тіні та зменшуючи швидкість пересування всіх гравців на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The River of Souls drains the lifeforce of all nearby players within it, inflicting $s2 Shadow damage every $t2 sec and reducing damage and healing done by $s3%.", ua = "Ріка Душ висотує життєву силу з усіх гравців, що в ній перебувають, завдаючи $s2 шкоди від тіні кожні $t2 с та знижуючи завдану шкоду й зцілення на $s3%." },
    { en = "If allowed to reach Garrosh, Mawsworn Overlords empower all Mawsworn Agonizers, temporarily granting Defiance while in the effect.", ua = "Якщо Повелителям Пащеприсяжних дозволити дістатися до Ґарроша, вони посилюють усіх Мучителів Пащеприсяжних, тимчасово надаючи Непокору, доки ті в зоні дії." },
    { en = "Soulrender Dormazain torments Garrosh, unleashing waves of Anima that inflict $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d to players caught in their wake. This effect stacks.", ua = "Душороздирач Дормазейн мучить Ґарроша, вивільняючи хвилі аніми, що завдають $s1 шкоди від тіні та додатково $s2 шкоди від тіні кожні $t2 с упродовж $d гравцям на їхній траєкторії. Цей ефект накопичується." },
    { en = "Garrosh unleashes a hellacious roar inflicting $s3 Physical damage to all players every $350411t3 sec until interrupted.\n\n\n\nLok'tar ogar!", ua = "Ґаррош видає пекельний рев, завдаючи $s3 фізичної шкоди всім гравцям кожні $350411t3 с, доки його не перервуть.\n\n\n\nLok'tar ogar!" },
    { en = "Snapping a Warmonger Shackle unleashes a wave of soul energy, inflicting $s1 Shadow damage to all players.", ua = "Розбиття кайданів Розпалювача війни вивільняє хвилю енергії душ, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "Mawsworn Overlords empower nearby Mawsworn Agonizers within $s2 yds, temporarily granting Defiance while they remain in the effect.", ua = "Повелителі Пащеприсяжних посилюють розташованих поблизу Мучителів Пащеприсяжних у межах $s2 ярдів, тимчасово надаючи Непокору, доки ті лишаються в зоні дії." },
    { en = "The Brand inflicts $s1 Shadow damage every $t1 sec to nearby allies and Mawsworn within $350647s3 yds. In addition, any Mawsworn that remain in the effect take $350649s1% increased damage.", ua = "Тавро завдає $s1 шкоди від тіні кожні $t1 с найближчим союзникам і слугам Пащі в межах $350647s3 м. Крім того, усі слуги Пащі, які лишаються в зоні дії, отримують на $350649s1% більше шкоди." },
    { en = "Dormazain plunges Ruinblade into his current target, inflicting $s1 Physical damage and increasing Physical damage taken by $s2% for $d. This effect stacks.", ua = "Дормазейн встромлює Клинок руїни в поточну ціль, завдаючи $s1 фізичної шкоди та підвищуючи отримувану фізичну шкоду на $s2% на $d. Цей ефект накопичується." },
    { en = "Snapping a Warmonger Shackle binds the player's soul to it, preventing them from interacting with Warmonger Shackles. While under this effect the target suffers $358865s1 Shadow damage every $t1 sec.", ua = "Розбиття кайданів Розпалювача війни прив'язує до них душу гравця, не даючи йому взаємодіяти з кайданами Розпалювача війни. Доки діє цей ефект, ціль зазнає $358865s1 шкоди від тіні кожні $t1 с." },
    { en = "Soulrender Dormazain brands players, causing them to inflict Tormented to all nearby players and Mawsworn.", ua = "Душороздирач Дормазейн таврує гравців, змушуючи їх накладати Муки на всіх найближчих гравців і слуг Пащі." },
    { en = "Soulrender Dormazain binds Garrosh with ghastly shackles causing him to Hellscream. Carrying a shackle at least 40 yards away from Garrosh causes it to snap, destroying it and causing Unleashed Tyranny.\n\n\n\nOnce all Shackles have been destroyed, Hellscream is interrupted.", ua = "Душороздирач Дормазейн сковує Ґарроша моторошними кайданами, змушуючи його творити Пекельний крик. Якщо віднести кайдани щонайменше на 40 м від Ґарроша, вони розбиваються, знищуючись і викликаючи Вивільнену тиранію.\n\n\n\nЯк тільки всі кайдани знищено, Пекельний крик переривається." },
    { en = "Garrosh's anima overwhelms the Mawsworn Agonizer, causing them to become immune to all forms of crowd control and increasing all damage done by $s3%.", ua = "Аніма Ґарроша переповнює Мучителя зі слуг Пащі, роблячи його несприйнятливим до всіх видів контролю та підвищуючи всю завдану ним шкоду на $s3%." },
    { en = "The tortured screams of Soulrender Dormazain's countless victims fills the air, inflicting $358612s1 Shadow damage to all players every $t1 sec.", ua = "Повітря наповнюють зойки катованих незліченних жертв Душороздирача Дормазейна, завдаючи $358612s1 шкоди від тіні всім гравцям кожні $t1 с." },
    { en = "Soulrender Dormazain's torments pierce Garrosh's soul, causing fragments to periodically cascade into the arena that inflct $s1 Shadow damage to all players within $a1 yds of the impact.", ua = "Муки Душороздирача Дормазейна пронизують душу Ґарроша, через що уламки періодично летять на арену, завдаючи $s1 од. шкоди від магії Тіні всім гравцям у межах $a1 ярдів від місця падіння." },
    { en = "The Painsmith hurls his scythe at his current target, inflicting $356461s1 Physical damage and applying $@spellname355786. Flames erupt from the target and inflict $355788s1 Fire damage to all other players. Players farther from the target take less damage.\n\n\n\nSpikes erupt in four directions and then ripple outwards from the target's location.", ua = "Болековач жбурляє свою косу в поточну ціль, завдаючи $356461s1 фізичної шкоди та накладаючи $@spellname355786. З цілі вириваються омахи полум'я, що завдають $355788s1 шкоди вогнем усім іншим гравцям. Що далі гравці від цілі, то меншу шкоду отримують.\n\n\n\nШипи вистрелюють у чотирьох напрямках, а тоді розходяться брижами від місця, де стоїть ціль." },
    { en = "The impacts of $@spellname355568, $@spellname348508, and $@spellname355778 cause players affected by $@spellname355504 to erupt with spikes in four directions.", ua = "Влучання $@spellname355568, $@spellname348508 і $@spellname355778 змушують гравців під дією $@spellname355504 вистрелити шипами в чотирьох напрямках." },
    { en = "Floor spikes inflict $s1 Physical damage and stun the target for $d.", ua = "Шипи з підлоги завдають $s1 фізичної шкоди й оглушують ціль на $d." },
    { en = "The $@spellname348456 erupts, inflicting $s1 Fire damage to all players and increasing damage taken from $@spellname348463s by $s2% for $d.", ua = "$@spellname348456 вибухає, завдаючи $s1 шкоди вогнем усім гравцям і підвищуючи отримувану шкоду від $@spellname348463 на $s2% на $d." },
    { en = "The Painsmith chooses up to $s4 victims and after $s3 sec activates a burning trap at their location.\n\n\n\nTraps explode in a $@spellname348463 if stepped on, pierced by spikes, or crushed by spiked balls.", ua = "Болековач обирає до $s4 жертв і за $s3 с активує палаючу пастку на їхньому місці.\n\n\n\nПастки вибухають, спричиняючи $@spellname348463, якщо на них наступити, проштрикнути шипами або розчавити шипастими кулями." },
    { en = "The Shadowsteel Horror extinguishes itself with a grinding screech that inflicts $s1 Fire damage to all players.", ua = "Жах із тіньосталі гасне зі скреготливим вереском, що завдає $s1 шкоди вогнем усім гравцям." },
    { en = "Inflicts $s1 Fire damage every $t1 sec and increases Physical damage taken by $s2% for $d. This effect stacks.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с і підвищує отримувану фізичну шкоду на $s2% на $d. Цей ефект накопичується." },
    { en = "With each strike of the Painsmith's hammer flames erupt, inflicting $s1 Fire damage to all players and applying $@spellname356472.", ua = "З кожним ударом молота Болековача вириваються омахи полум'я, завдаючи $s1 шкоди вогнем усім гравцям і накладаючи $@spellname356472." },
    { en = "The Painsmith's work unleashes blazing embers that inflict $355535s1 Fire damage to players within $355535A1 yds of the impact location.", ua = "Праця Болековача вивільняє жагучі жарини, що завдають $355535s1 шкоди вогнем гравцям у межах $355535A1 м від місця падіння." },
    { en = "The Painsmith hurls his axe at his current target, inflicting $356459s1 Physical damage and applying $@spellname355786. Flames erupt from the impact and inflict $355573s1 Fire damage to all other players. Players farther from the target take less damage.\n\n\n\nSpikes erupt in four directions from the target's location.", ua = "Болековач жбурляє свою сокиру в поточну ціль, завдаючи $356459s1 фізичної шкоди та накладаючи $@spellname355786. Від місця влучання вириваються омахи полум'я, що завдають $355573s1 шкоди вогнем усім іншим гравцям. Що далі гравці від цілі, то меншу шкоду отримують.\n\n\n\nШипи вистрелюють у чотирьох напрямках від місця, де стоїть ціль." },
    { en = "The Painsmith shackles targets with agonizing chains, inflicting $357740s1 Fire damage every $355506t2 sec for $355506d.\n\n\n\nShackled players inflict $?diff17[$357721s1 Fire damage every $357721t1 sec. to allies within $355506s1 yards.][$355524s1 Physical damage to allies within $355506s1 yards and knock them away.]", ua = "Болековач сковує цілі болісними ланцюгами, завдаючи $357740s1 шкоди вогнем кожні $355506t2 с упродовж $355506d.\n\n\n\nСковані гравці завдають $?diff17[$357721s1 шкоди вогнем кожні $357721t1 с союзникам у межах $355506s1 м.][$355524s1 фізичної шкоди союзникам у межах $355506s1 м і відкидають їх.]" },
    { en = "The Painsmith drops spiked balls that roll across the chamber floor, inflicting $348363s1 Physical damage to players caught in their path and stunning them for $348363d.", ua = "Болековач випускає шипасті кулі, що котяться підлогою зали, завдаючи $348363s1 фізичної шкоди гравцям на своєму шляху й оглушуючи їх на $348363d." },
    { en = "The forge's flames smolder, inflicting $356846s1 Fire damage every $t1 sec. This effect stacks.", ua = "Полум'я горнила тліє, завдаючи $356846s1 шкоди вогнем кожні $t1 с. Цей ефект накопичується." },
    { en = "The Painsmith hurls his hammer at his current target, inflicting $356317s1 Physical damage applying $@spellname355786. Flames erupt from the impact and inflict $348520s1 Fire damage to all other players. Players farther from the target take less damage.\n\n\n\nSpikes ripple outwards from the target's location.", ua = "Болековач жбурляє свій молот у поточну ціль, завдаючи $356317s1 фізичної шкоди та накладаючи $@spellname355786. Від місця влучання вириваються омахи полум'я, що завдають $348520s1 шкоди вогнем усім іншим гравцям. Що далі гравці від цілі, то меншу шкоду отримують.\n\n\n\nШипи розходяться брижами від місця, де стоїть ціль." },
    { en = "The Guardian disintegrates players in a line in front of it, inflicting $s1 Arcane damage.  In addition, players struck with this effect are stunned and take an additional $s2 Arcane damage every $t2 sec for $d.", ua = "Вартовий розпорошує гравців на лінії перед собою, завдаючи $s1 арканної шкоди. Крім того, уражені цим ефектом гравці оглушуються й отримують додаткові $s2 арканної шкоди кожні $t2 с упродовж $d." },
    { en = "While near an Energy Core the Guardian will link to it, granting it $s1 energy every $t1 sec.", ua = "Перебуваючи біля Енергетичного ядра, Вартовий приєднується до нього, отримуючи $s1 енергії кожні $t1 с." },
    { en = "While active, the Energy Core emits a field of $@spellname352394. Players standing in the area take $s1% reduced damage from $@spellname350455.", ua = "Доки воно активне, Енергетичне ядро випромінює поле $@spellname352394. Гравці, що стоять у цій зоні, отримують на $s1% менше шкоди від $@spellname350455." },
    { en = "The Guardian slams the ground at its primary target's location, inflicting $s1 Physical damage to players within $a1 yards of the impact and increases damage taken from $@spellname350732 by $s2% for $d.", ua = "Вартовий гатить об землю на місці своєї основної цілі, завдаючи $s1 фізичної шкоди гравцям у межах $a1 м від влучання та підвищуючи отримувану шкоду від $@spellname350732 на $s2% на $d." },
    { en = "The core violently erupts, inflicting $s1 Arcane damage to players within $a1 yards and $s2 Arcane damage to players further than $a1 yards.", ua = "Ядро шалено вибухає, завдаючи $s1 арканної шкоди гравцям у межах $a1 м і $s2 арканної шкоди гравцям далі ніж за $a1 м." },
    { en = "The Guardian executes a combination of attacks on its primary target.", ua = "Вартовий виконує серію атак проти своєї основної цілі." },
    { en = "The Guardian originates a servitor that orbits the caster.", ua = "Вартовий породжує прислужника, що кружляє навколо нього." },
    { en = "While linked to The Guardian, Energy Cores emit pulses of $@spellname350455 inflicting $s1 Arcane damage to all players every $352385t2 sec.", ua = "Доки Енергетичні ядра приєднані до Вартового, вони випускають імпульси $@spellname350455, завдаючи $s1 арканної шкоди всім гравцям кожні $352385t2 с." },
    { en = "The Guardian decimates its primary target, inflicting $358966s1 Physical damage and an additional $355357s1 Arcane damage split evenly among all players within $355357a1 yards of the primary target.\n\n\n\nIn addition, all targets hit by the effect take $358619s1% increased damage from $@spellname355352 for $358619d.", ua = "Вартовий нищить свою основну ціль, завдаючи $358966s1 фізичної шкоди та додаткові $355357s1 арканної шкоди, що порівну розподіляється між усіма гравцями в межах $355357a1 м від основної цілі.\n\n\n\nКрім того, усі цілі, уражені ефектом, отримують на $358619s1% більше шкоди від $@spellname355352 упродовж $358619d." },
    { en = "The Sentry periodically unleashes a barrage of energy at random targets that inflicts $s1 Arcane damage.", ua = "Дозорець періодично обрушує на випадкові цілі шквал енергії, що завдає $s1 арканної шкоди." },
    { en = "Upon reaching 0 energy the Guardian begins to repeatedly unleash pulses of energy that inflict $s1 Arcane damage to all players until it can link with an Energy Core.  Each subsequent cast of Purging Protocol increases its damage by $s2%.\n\n\n\nIn addition, all Sentries hit with Purging Protocol are destroyed.", ua = "Сягнувши 0 енергії, Вартовий починає раз за разом вивільняти імпульси енергії, що завдають $s1 од. шкоди від магії школи Тайнощів усім гравцям, доки він не зможе зв'язатися з Енергетичним Ядром.  Кожне наступне творення Протоколу Очищення збільшує його шкоду на $s2%.\n\n\n\nКрім того, усі Вартові дрони, уражені Протоколом Очищення, знищуються." },
    { en = "Energy Cores begin the encounter drained, striking an Energy Core with $@spellname356090 restores $s1 energy.", ua = "На початку битви Енергетичні ядра спустошені; удар по Енергетичному ядру за допомогою $@spellname356090 відновлює $s1 енергії." },
    { en = "The Guardian locks on to multiple players.  After $d, the Guardian unleashes a barrage at each target's location, inflicting $356103s1 Arcane damage to all players within $350502A1 yards of the impact.", ua = "Страж бере на приціл кількох гравців. За $d він обрушує на місце кожної цілі шквал ударів, завдаючи $356103s1 арканної шкоди всім гравцям у радіусі $350502A1 м від влучання." },
    { en = "The Sentry maintains a $@spellname347359 beneath it that inflicts $s1 Arcane damage every $t1 sec and prevents players from being able to attack or cast spells while in the area.", ua = "Вартова утримує під собою $@spellname347359, що завдає $s1 арканної шкоди кожні $t1 сек і не дає гравцям атакувати чи творити закляття, доки вони в цій зоні." },
    { en = "Fatescribe Roh-Kalo unleashes fragments of possible fates. Touching one of these fragments alters the target's fate, inflicting $s1 Shadow damage and reducing the target's movement speed by $s2% for $d.", ua = "Літописець долі Рох-Кало вивільняє уламки можливих доль. Дотик до такого уламка змінює долю цілі, завдаючи $s1 шкоди від тіні й сповільнюючи рух цілі на $s2% на $d." },
    { en = "Twists the Threads of Fate attached to several players, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Скручує Нитки Долі, прикріплені до кількох гравців, завдаючи $s1 шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "Fatescribe Roh-Kalo triggers a Fated Conjunction, causing several beams of energy to erupt from around the space after a $350169s1 second delay. \n\n\n\nThe beams inflict $s1 Shadow damage to targets caught in the blast, and increasing the damage taken from Fated Conjunction by $s2% for $d.", ua = "Літописець долі Рох-Кало запускає Фатальне Сходження, через що довкола простору, після затримки в $350169s1 сек, вибухають кілька променів енергії. \n\n\n\nПромені завдають $s1 шкоди від тіні цілям, що потрапили під вибух, і збільшують шкоду від Фатального Сходження на $s2% протягом $d." },
    { en = "Fatescribe Roh-Kalo's machinations conjoin several players to the Loom of Fates' current configuration, allowing them to manipulate the rings.", ua = "Підступи Літописця долі Рох-Кало пов'язують кількох гравців із поточним налаштуванням Кросна Доль, дозволяючи їм керувати кільцями." },
    { en = "The power conjured around the Loom of Fates by Fatescribe Roh-Kalo strengthens the Fatespawn Monstrosity, increasing Physical damage inflicted by $s1% every $t2 sec.", ua = "Сила, прикликана Літописцем долі Рох-Кало довкола Кросна Доль, підсилює Породження Долі, збільшуючи завдану фізичну шкоду на $s1% кожні $t2 сек." },
    { en = "A Shade of Destiny fixates upon its target, increasing that target's damage taken by $s2% while the shade lives.\n\n\n\nIf the shade reaches its target or reaches full energy, it erupts, striking the raid with an Overwhelming Burden.", ua = "Тінь Долі зосереджується на своїй цілі, збільшуючи отримувану нею шкоду на $s2%, доки тінь жива.\n\n\n\nЯкщо тінь сягає своєї цілі або набирає повну енергію, вона вибухає, вражаючи рейд Нестерпним Тягарем." },
    { en = "The Fatespawn Monstrosity unleashes a wave Despair upon all players within $A1 yards, inflicting $s1 Shadow damage every $t1 sec and reducing their movement speed by $s2% for $d.", ua = "Породження Долі вивільняє хвилю Відчаю на всіх гравців у межах $A1 м, завдаючи $s1 шкоди від тіні кожні $t1 сек і сповільнюючи їхній рух на $s2% протягом $d." },
    { en = "The Shade of Destiny erupts, inflicting $s1 Shadow damage to all players every $t1 sec for $d.", ua = "Тінь Долі вибухає, завдаючи $s1 шкоди від тіні всім гравцям кожні $t1 сек протягом $d." },
    { en = "The Fatescribe's chosen alignment for the Loom of Fates eats away at his attackers, inflicting $s1 Shadow damage every $353693t1 sec until the Loom is realigned.", ua = "Обране Літописцем долі вирівнювання Кросна Доль роз'їдає його нападників, завдаючи $s1 шкоди від тіні кожні $353693t1 сек, доки Кросно не буде вирівняно знову." },
    { en = "Fatescribe Roh-Kalo hastily adjusts the Loom of Fates in a desperate attempt to alter his own destiny.\n\n\n\nIf any rune remains out of place after $d, the Fatescribe invokes Darkest Destiny.", ua = "Літописець долі Рох-Кало квапливо налаштовує Кросно Доль у відчайдушній спробі змінити власну долю.\n\n\n\nЯкщо після $d хоч одна руна лишиться не на місці, Літописець долі прикликає Найтемнішу Долю." },
    { en = "While manipulating the Loom of Fates, fine filaments form between the active rune and the Loom's center.\n\n\n\nPlayers who touch these filaments have their fate altered, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Під час керування Кросном Доль між активною руною та центром Кросна утворюються тонкі волокна.\n\n\n\nГравці, які торкаються цих волокон, зазнають зміни долі, отримуючи $s1 шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "Fatescribe Roh-Kalo binds several players to runes upon the Loom of Fates.\n\n\n\nAfter $d, if a bound player is touching their assigned rune, the Fatescribe inflicts $354371s1 Shadow damage to all players within the rune.\n\n\n\nIf a rune expires without its bound player inside, the Fatescribe inflicts $354372s1 Shadow damage to all players.", ua = "Літописець долі Рох-Кало прив'язує кількох гравців до рун на Кросні Доль.\n\n\n\nЧерез $d, якщо прив'язаний гравець торкається призначеної йому руни, Літописець долі завдає $354371s1 шкоди від тіні всім гравцям у межах руни.\n\n\n\nЯкщо руна зникає без свого прив'язаного гравця всередині, Літописець долі завдає $354372s1 шкоди від тіні всім гравцям." },
    { en = "Fatescribe Roh-Kalo invokes the current target's inevitable end.\n\n\n\nAfter $d the target erupts, forming a Shade of Destiny and inflicting up to $351685s1 Shadow damage to all players. Players farther from this eruption suffer less damage.", ua = "Літописець долі Рох-Кало прикликає неминучий кінець поточної цілі.\n\n\n\nЧерез $d ціль вибухає, утворюючи Тінь Долі та завдаючи до $351685s1 шкоди від тіні всім гравцям. Гравці, дальші від цього вибуху, зазнають меншої шкоди." },
    { en = "Each time Fatescribe Roh-Kalo attacks a new target, he eagerly probes them for weakness, gaining several stacks of Diviner's Probe.\n\n\n\nThe Fatescribe spends stacks to inflict $353603s1 Shadow damage to the current target.", ua = "Щоразу, коли Літописець Долі Рох-Кало атакує нову ціль, він жадібно вишукує її слабкі місця й отримує кілька стаків Зонду Віщуна.\n\n\n\nЛітописець Долі витрачає стаки, завдаючи $353603s1 шкоди від тіні поточній цілі." },
    { en = "Inflicts $350810s1 Shadow damage every $t1 sec for $d.\n\n\n\nThe target explodes on expiration, striking all players within $357732A1 yards for $350819s1 Shadow damage.", ua = "Завдає $350810s1 од. шкоди від магії Тіні кожні $t1 с протягом $d.\n\n\n\nПо завершенні ціль вибухає, уражаючи всіх гравців у межах $357732A1 ярдів на $350819s1 од. шкоди від магії Тіні." },
    { en = "Fatescribe Roh-Kalo rearranges the Loom of Fates, authoring for himself a glorious new fate. While he is doing so, his damage taken is reduced by $357739s1%.\n\n\n\nSeveral players are revealed as having Runic Affinity for the Loom's current configuration, and are capable of manipulating the position of the Loom's rings.\n\n\n\nAfter $s1 sec, if the rings are not returned to their target positions, Fatescribe Roh-Kalo invokes the Darkest Destiny, killing all players.", ua = "Літописець долі Рох-Кало перебудовує Кросно Доль, складаючи для себе нову славетну долю. Поки він це робить, отримувана ним шкода знижена на $357739s1%.\n\n\n\nВиявляється, що кілька гравців мають Рунічну Спорідненість із поточним налаштуванням Кросна й здатні змінювати положення його кілець.\n\n\n\nЧерез $s1 сек, якщо кільця не повернуть на цільові позиції, Літописець долі Рох-Кало прикликає Найтемнішу Долю, вбиваючи всіх гравців." },
    { en = "Inflicts $350810s1 Shadow damage every $t1 sec for $d.\n\n\n\nThe target explodes on expiration, striking all other players within $357732a1 yards for $350819s1 Shadow damage. The explosion leaves behind an Echo of Eternity.", ua = "Завдає $350810s1 тіньової шкоди кожні $t1 сек. протягом $d.\n\n\n\nПо завершенні ціль вибухає, вражаючи всіх інших гравців у радіусі $357732a1 ярд. на $350819s1 тіньової шкоди. Вибух лишає по собі Відлуння Вічності." },
    { en = "With fate realigned in his favor, Fatescribe Roh-Kalo invokes the darkest possible destiny, ensuring swift and unceremonious deaths for all players.", ua = "Вирівнявши долю на свою користь, Літописець долі Рох-Кало прикликає найтемнішу з можливих доль, прирікаючи всіх гравців на швидку й безславну смерть." },
    { en = "$350568d after players are afflicted by Call of Eternity, all Echoes of Eternity explode and are destroyed in the process, inflicting $s1 Shadow damage to all players within $A1 yards of the Echo.", ua = "Через $350568d після того, як гравців уразив Поклик Вічності, усі Відлуння Вічності вибухають і при цьому знищуються, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 м від Відлуння." },
    { en = "Any number of players within an active rune rotates the attached ring clockwise.", ua = "Будь-яка кількість гравців усередині активної руни обертає прикріплене кільце за годинниковою стрілкою." },
    { en = "Blasts a nearby enemy for $s1 Shadow damage.", ua = "Вражає ворога поблизу на $s1 шкоди від тіні." },
    { en = "An odd number of players within an active rune rotates the attached ring clockwise.", ua = "Непарна кількість гравців усередині активної руни обертає прикріплене кільце за годинниковою стрілкою." },
    { en = "An even number of players within an active rune rotates the attached ring counterclockwise.", ua = "Парна кількість гравців усередині активної руни обертає прикріплене кільце проти годинникової стрілки." },
    { en = "The Remnant constantly opens fissures at random target destinations, inflicting $s1 Shadow damage to enemies within $a1 yards and knocking them back.", ua = "Рештки постійно відкривають розколини у випадкових цільових місцях, завдаючи $s1 шкоди від тіні ворогам у межах $a1 м і відкидаючи їх." },
    { en = "The shard screams, inflicting $s1 Shadow damage to all players.", ua = "Уламок кричить, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "Every $352141t1 sec the spirit launches missiles at random players that inflicts $s1 Shadow damage.\n\n\n\nIn addition, each successful cast increases the damage of the next $@spellname352144 by $355935s1%.", ua = "Кожні $352141t1 сек дух запускає снаряди у випадкових гравців, що завдають $s1 шкоди від тіні.\n\n\n\nКрім того, кожне успішне творіння збільшує шкоду наступного $@spellname352144 на $355935s1%." },
    { en = "Kel'Thuzad revives Frostbound Devoted to stalk his enemies.\n\n\n\nIn addition, all slain players are resurrected and become thralls of Kel'Thuzad until they are slain once more.", ua = "Кел'Тузад оживляє Морозоскутих Відданих, щоб ті переслідували його ворогів.\n\n\n\nКрім того, усі полеглі гравці воскресають і стають невільниками Кел'Тузада, доки їх не вб'ють знову." },
    { en = "Unstoppable Abominations and Soul Reavers defeated while the phylactery is open revive after 10 sec and return to the fight.", ua = "Нестримні Потвори та Душороздирачки, переможені, поки філактерія відкрита, оживають через 10 сек і повертаються в бій." },
    { en = "Hurls an ice shard at the current target that inflicts $s1% attack damage as Physical.", ua = "Жбурляє крижаний уламок у поточну ціль, завдаючи $s1% шкоди атаки як фізичну." },
    { en = "Kel'Thuzad shrouds random players with necrotic energy for $347292d, causing them to silence and pacify all players and Soul Shards within 10 yards.\n\n\n\nUpon expiration, the wearer drops a field of silence at their destination that summons a Frostbound Devoted after $347512d.", ua = "Кел'Тузад огортає випадкових гравців некротичною енергією на $347292d, через що вони занурюють у мовчання та втихомирюють усіх гравців і Уламки Душ у межах 10 м.\n\n\n\nПо закінченні носій лишає на своєму місці поле тиші, що прикликає Морозоскутого Відданого через $347512d." },
    { en = "Once slain, their creator can collect their essence by touching the $@spellname357275 to remove one application of $@spellname348978.", ua = "Щойно його знищено, творець може зібрати його есенцію, торкнувшись $@spellname357275, аби зняти одне накладення $@spellname348978." },
    { en = "When depleted of mana, Kel'Thuzad summons a blizzard that creates ice patches. Standing in an ice patch inflicts $354208s1 Frost damage every $354208t1 sec.\n\n\n\nThese patches grow over $d before exploding, inflicting $354212s1 Frost damage to enemies within $354212a1 yards.", ua = "Коли мана вичерпується, Кел'Тузад прикликає хуртовину, що створює крижані плями. Перебування на крижаній плямі завдає $354208s1 шкоди від криги кожні $354208t1 сек.\n\n\n\nЦі плями розростаються протягом $d, а тоді вибухають, завдаючи $354212s1 шкоди від криги ворогам у межах $354212a1 м." },
    { en = "Kel'Thuzad unleashes a wave of death, inflicting $s1 Shadow damage to all players.\n\n\n\nThis cast is interrupted if the Remnant of Kel'Thuzad is killed or loses 40% of its max health.", ua = "Кел'Тузад вивільняє хвилю смерті, завдаючи $s1 шкоди від тіні всім гравцям.\n\n\n\nЦе творіння переривається, якщо Рештки Кел'Тузада вбито або вони втрачають 40% свого максимального здоров'я." },
    { en = "Kel'Thuzad flays his current target, inflicting $s1 Shadow damage and knocking the player away.\n\n\n\nIn addition, the target's soul is sundered into $s3 Soul Shards, applying stacks of $@spellname348978 for each shard created.", ua = "Кел'Тузад білує свою поточну ціль, завдаючи $s1 тіньової шкоди та відкидаючи гравця.\n\n\n\nКрім того, душу цілі розколює на $s3 Уламки Душі, накладаючи стопку $@spellname348978 за кожен створений уламок." },
    { en = "$@spellname357275s bind the essence of the target, increasing Physical damage taken by $s1% for $d.\n\n\n\nIf this effect is not removed before the duration expires the target is slain outright.", ua = "$@spellname357275 зв'язують сутність цілі, збільшуючи отримувану фізичну шкоду на $s1% протягом $d.\n\n\n\nЯкщо цей ефект не зняти до завершення тривалості, ціль гине миттєво." },
    { en = "Targets effected by Kel'Thuzad's $@spellname348756 are bound by icy restraints, rooting them for $d.", ua = "Цілі, уражені закляттям «$@spellname348756» Кел'Тузада, скуті крижаними путами, що знерухомлюють їх на $d." },
    { en = "Each time Kel'Thuzad is revived by the phylactery, necrotic power surges through him increasing his damage done by $s1%.\n\n\n\nAdditionally, each application also increases the number of players targeted by $@spellname347291 and $@spellname346459.", ua = "Щоразу, коли філактерія оживляє Кел'Тузада, крізь нього прокочується некротична сила, збільшуючи завдану ним шкоду на $s1%.\n\n\n\nКрім того, кожне накладення також збільшує кількість гравців, у яких ціляться $@spellname347291 і $@spellname346459." },
    { en = "Frostbound Devoted erupt upon reaching their target, inflicting $354107s1 Shadow damage to enemies within $A yards.", ua = "Морозоскуті Віддані вибухають, сягнувши своєї цілі, завдаючи $354107s1 шкоди від тіні ворогам у межах $A м." },
    { en = "The Remnant of Kel'Thuzad summons foul winds to push players towards the edge of the phylactery.", ua = "Рештки Кел'Тузада прикликають мерзенні вітри, що відштовхують гравців до краю філактерії." },
    { en = "Kel'Thuzad drags souls from oblivion and onto the battlefield.", ua = "Кел'Тузад витягує душі із небуття на поле бою." },
    { en = "You are barred from re-entering Kel'Thuzad's Phylactery", ua = "Вам заборонено повторно входити до філактерії Кел'Тузада" },
    { en = "The Remnant constantly opens fissures at random target destinations, inflicting $s1 Shadow damage to enemies within $a1 yards, knocking them back, and leaves a $@spellname355137 for $d.", ua = "Рештки безперервно відкривають розколини у випадкових точках, завдаючи $s1 шкоди від тіні ворогам у радіусі $a1 м, відкидаючи їх, і лишають $@spellname355137 на $d." },
    { en = "Shadow Pools inflict $s1 Shadow damage every $t1 sec while standing within it.", ua = "Калюжі Тіні завдають $s1 од. шкоди від магії Тіні кожні $t1 с, доки стоїш у них." },
    { en = "The spike erupts, inflicting $346530s1 Frost damage to all players and an additional $346530s2 Frost damage every $346530t2 sec for $346530d. This effect stacks.", ua = "Шпиль вибухає, завдаючи $346530s1 морозної шкоди всім гравцям і додатково $346530s2 морозної шкоди кожні $346530t2 сек. протягом $346530d. Цей ефект накопичується." },
    { en = "Kel'Thuzad chills the air causing ice patches to continually form on the ground and last for the remainder of the encounter. Standing within these ice patches inflicts $354639s1 Frost damage every $354639t1 sec.", ua = "Кел'Тузад вихолоджує повітря, через що на землі безперервно утворюються крижані плями, які лишаються до кінця бою. Стояння в цих крижаних плямах завдає $354639s1 шкоди від криги кожні $354639t1 с." },
    { en = "Every $352141t1 sec the spirit launches missiles at random players that inflicts $s1 Shadow damage.", ua = "Кожні $352141t1 с дух запускає снаряди у випадкових гравців, завдаючи $s1 шкоди від тіні." },
    { en = "Kel'Thuzad hurls a chunk of ice at an enemy, inflicting $348759s1 Frost damage divided evenly among players within $348759a1 yards and inflicts $357928s1 Frost damage every $357928t1 sec for $357928d. \n\n\n\nIn addition, this effect applies $@spellname357298.", ua = "Кел'Тузад жбурляє брилу криги у ворога, завдаючи $348759s1 шкоди від криги, рівномірно розподіленої між гравцями в радіусі $348759a1 м, і завдає $357928s1 шкоди від криги кожні $357928t1 с протягом $357928d. \n\n\n\nКрім того, цей ефект застосовує $@spellname357298." },
    { en = "Kel'Thuzad summons Glacial Spikes at player destinations, inflicting $346469s2 Frost damage to players within $346469a2 yards and knocking them back.", ua = "Кел'Тузад прикликає льодовикові шпичаки в точки, де стоять гравці, завдаючи $346469s2 шкоди від криги гравцям у радіусі $346469a2 м і відкидаючи їх." },
    { en = "Kel'Thuzad calls the armies of the damned to his aid.\n\n\n\nIn addition, slain players are also added to these ranks, now in the thrall of Kel'Thuzad until they are slain once more.", ua = "Кел'Тузад прикликає на допомогу армії проклятих.\n\n\n\nКрім того, полеглі гравці теж поповнюють ці лави, тепер у поневоленні Кел'Тузада, доки їх не вб'ють знову." },
    { en = "Once summoned, the Glacial Spike loses $348744s1% health every $348744t1 sec. On death the spike shatters, inflicting $356957s1 Frost damage to all players.", ua = "Прикликаний льодовиковий шпичак щомиті втрачає $348744s1% здоров'я кожні $348744t1 с. Гинучи, шпичак розколюється, завдаючи $356957s1 шкоди від криги всім гравцям." },
    { en = "The Remnant of Kel'Thuzad becomes immune to damage and unleashes a barrage of necrotic energy, inflicting $s1 Shadow damage to all players within the phylactery and knocking them back.", ua = "Рештки Кел'Тузада стають невразливими до шкоди й вивільняють шквал некротичної енергії, завдаючи $s1 шкоди від тіні всім гравцям у філактерії та відкидаючи їх." },
    { en = "After being revived by the phylactery, Kel'Thuzad empowers any of his minions still alive, increasing their damage by $s1% and making them immune to all loss of control effects until they are slain.", ua = "Воскреснувши завдяки філактерії, Кел'Тузад наснажує всіх своїх прислужників, які ще живі, збільшуючи їхню шкоду на $s1% і роблячи їх несприйнятливими до всіх ефектів втрати контролю, доки їх не вб'ють." },
    { en = "The Unstoppable Abomination unleashes a wave of necrotic energy in a line towards a random player, inflicting $349806s1 Shadow damage to all players caught in the effect.", ua = "Нездоланна Потвора вивільняє хвилю некротичної енергії лінією в напрямку випадкового гравця, завдаючи $349806s1 шкоди від тіні всім гравцям, що потрапили під ефект." },
    { en = "Continually inflicts $s1 Shadow damage every $t1 sec as long as a player is within the phylactery.\n\n\n\nThis effect stacks.", ua = "Безперервно завдає $s1 шкоди від тіні кожні $t1 с, поки гравець перебуває у філактерії.\n\n\n\nЦей ефект накопичується." },
    { en = "When the Remnant of Kel'Thuzad reaches 20% health remaining it begins unleashing tornadoes that radiate out from the caster, inflicting $s1 Frost Damage and rooting anyone they touch for $d.", ua = "Коли в Рештку Кел'Тузада лишається 20% здоров'я, він починає випускати торнадо, що розходяться від нього, завдаючи $s1 шкоди від криги й знерухомлюючи всіх, кого зачеплять, на $d." },
    { en = "Kel'Thuzad shrouds random players with necrotic energy for $347292d, causing them to silence all creatures within 10 yards.", ua = "Кел'Тузад огортає випадкових гравців некротичною енергією на $347292d, через що вони знемовлюють усіх істот у радіусі 10 м." },
    { en = "The Remnant of Kel'Thuzad unleashes a wave of ice over players in a line, inflicting $352381s1 Frost damage and rooting them for $352381d.", ua = "Рештки Кел'Тузада вивільняють хвилю криги по гравцях у лінію, завдаючи $352381s1 шкоди від криги й знерухомлюючи їх на $352381d." },
    { en = "When depleted of mana, Kel'Thuzad summons a blizzard that inflicts $362495s1 Frost damage every $362495t1 sec. This effect stacks. \n\n\n\nAlso, ice patches form. Standing in an ice patch inflicts $354208s1 Frost damage every $354208t1 sec.\n\n\n\nThese patches grow over $d before exploding, inflicting $354212s1 Frost damage to enemies within $354212a1 yards.", ua = "Вичерпавши ману, Кел'Тузад прикликає хуртовину, що завдає $362495s1 шкоди від криги кожні $362495t1 с. Цей ефект накопичується.\n\n\n\nОкрім того, утворюються крижані плями. Перебування в крижаній плямі завдає $354208s1 шкоди від криги кожні $354208t1 с.\n\n\n\nЦі плями розростаються протягом $d, а тоді вибухають, завдаючи $354212s1 шкоди від криги ворогам у радіусі $354212a1 м." },
    { en = "Ejects abominable detritus along the travel path, inflicting $353413s1 Shadow damage to targets within $353413A1 yards of the impact location.", ua = "Викидає мерзенне сміття вздовж траєкторії польоту, завдаючи $353413s1 шкоди від тіні цілям у радіусі $353413A1 м від місця падіння." },
    { en = "Imbues the Hopebreaker with a burning rage, increasing movement speed by $s4% and causes successful melee swings to inflict $351110s1 Fire damage to their current target and an additional $351110s2 Fire damage to all other players within $351110A2 yards.", ua = "Сповнює Згубителя надії пекучою люттю, збільшуючи швидкість пересування на $s4% і змушуючи влучні удари ближнього бою завдавати $351110s1 шкоди вогнем поточній цілі й додатково $351110s2 шкоди вогнем усім іншим гравцям у радіусі $351110A2 м." },
    { en = "Enshrouds Sylvanas in darkness, reducing damage taken by $s1%.", ua = "Огортає Сильвану темрявою, зменшуючи отримувану шкоду на $s1%." },
    { en = "Sylvanas gains a stack of $@spellname352650 every $352649T1 sec. Upon reaching $352649s1 stacks Sylvanas can replace a $@spellname347548 with a triple burst of $@spellname352650 into her target. Each arrow inflicts $352651s1 Physical damage and $352652s1 Shadow damage, applying $@spellname347607.", ua = "Сильвана отримує заряд $@spellname352650 кожні $352649T1 с. Досягнувши $352649s1 зарядів, Сильвана може замінити $@spellname347548 потрійним залпом $@spellname352650 у ціль. Кожна стріла завдає $352651s1 фізичної шкоди й $352652s1 шкоди від тіні, застосовуючи $@spellname347607." },
    { en = "The Goliath riots allies within $355841A1 yards, causing melee attacks to additionally inflict $355849s1% of their damage done as Shadow.", ua = "Голіаф підбурює союзників у радіусі $355841A1 м, через що їхні атаки ближнього бою додатково завдають $355849s1% завданої шкоди як шкоду від тіні." },
    { en = "Sylvanas burdens targets with a ravenous affliction, inflicting $367607s1 Shadow damage every second. This effect stacks. Upon removal, this coalesces into a pool of shadow on the ground. Any player touching the pool gains $@spellname353929, consuming the pool.", ua = "Сильвана обтяжує цілі ненаситною недугою, завдаючи $367607s1 шкоди від тіні щосекунди. Цей ефект накопичується. Коли його знято, він стікається в калюжу тіні на землі. Будь-який гравець, що торкнеться калюжі, отримує $@spellname353929, поглинаючи калюжу." },
    { en = "The Souljudge sows immense anxiety in afflicted targets, erupting for $351118s1 Shadow damage to players within $351118A1 yards every $351117T1 sec. for $351117D. This effect increases stacks every period, increasing $@spellname351117 damage by $531117s1%.\n\n\n\nUpon removal, this effect transfers to another player until the Souljudge is defeated.", ua = "Суддя душ сіє неймовірну тривогу в уражених цілях, вибухаючи $351118s1 шкодою від тіні гравцям у радіусі $351118A1 м кожні $351117T1 с протягом $351117D. Цей ефект щоразу накопичує заряди, збільшуючи шкоду $@spellname351117 на $531117s1%.\n\n\n\nКоли його знято, цей ефект переходить на іншого гравця, доки Суддю душ не буде переможено." },
    { en = "The Domination Arrow radiates corrupt energy, inflicting $356649s1 Shadow damage $?diff16[to targets within $356649A1 yards ][]when afflicted players come within $356624A1 yards of the arrow chaining them.", ua = "Стріла Панування випромінює зіпсуту енергію, завдаючи $356649s1 шкоди від тіні $?diff16[цілям у радіусі $356649A1 м ][]коли уражені гравці наближаються на $356624A1 м до стріли, що прикувала їх ланцюгами." },
    { en = "Empowers the Vanguard with accursed magic, increasing damage done by $s2%, movement speed by $s4%, and total health by $s3%. This effect stacks.", ua = "Наснажує Авангард проклятою магією, збільшуючи завдану шкоду на $s2%, швидкість пересування на $s4% і загальне здоров'я на $s3%. Цей ефект накопичується." },
    { en = "Sylvanas fires several salvos of Domination Arrows at targeted locations, inflicting $352318s1 Shadow damage to enemies within $352317A1 yards, then chains players to those that remain.\n\n\n\nThese chains pull players inflicting $349458s1 Shadow damage every second and increasing the speed at which players are pulled by $349458s2% until defeated. This effect stacks and removes $@spellname347807 from targets.", ua = "Сильвана випускає кілька залпів Стріл Панування у вибрані місця, завдаючи $352318s1 шкоди від тіні ворогам у радіусі $352317A1 м, а потім прикуває гравців ланцюгами до тих, що лишилися.\n\n\n\nЦі ланцюги тягнуть гравців, завдаючи $349458s1 шкоди від тіні щосекунди й збільшуючи швидкість, з якою гравців тягне, на $349458s2%, доки їх не буде знищено. Цей ефект накопичується й знімає $@spellname347807 з цілей." },
    { en = "Sylvanas erupts with Banshee magic, inflicting $357527s1 Shadow damage to all players every second for $354068D. After $354068D, $@spellname353929 explodes from players inflicting an additional $357526s1 Shadow damage to all players per stack of $@spellname353929.", ua = "Сильвана вибухає магією баньші, завдаючи $357527s1 шкоди від тіні всім гравцям щосекунди протягом $354068D. Після $354068D $@spellname353929 вибухає з гравців, завдаючи всім гравцям додатково $357526s1 шкоди від тіні за кожен заряд $@spellname353929." },
    { en = "Sylvanas heaves corrupted blades, inflicting $347670s1 Shadow damage every $347670T1 sec for $347670D to all struck targets.", ua = "Сильвана метає зіпсуті клинки, завдаючи $347670s1 шкоди від тіні кожні $347670T1 с протягом $347670D усім ураженим цілям." },
    { en = "Sylvanas releases a volley of arrows, inflicting $347928s1 Shadow damage to affected players.", ua = "Сильвана випускає залп стріл, завдаючи $347928s1 шкоди від тіні ураженим гравцям." },
    { en = "$@spellname347928 leaves a $@spellname347807 in targets, bleeding for $347807s1 Physical damage every $347807T1 sec. This effect stacks.", ua = "$@spellname347928 лишає в цілях $@spellname347807, через що вони кровоточать, отримуючи $347807s1 фізичної шкоди кожні $347807T1 с. Цей ефект накопичується." },
    { en = "Sylvanas places a mark on players inflicting $358434s1 Shadow damage every second for $358434D.\n\n\n\nWhen removed, Death-touched blades fling out from the marked players in targeted directions, inflicting $358433s1 Shadow damage every second for $358433D to players within $358433A1 yards of any struck target.", ua = "Сильвана ставить мітку на гравцях, завдаючи $358434s1 шкоди від тіні щосекунди протягом $358434D.\n\n\n\nКоли мітку знято, торкнуті смертю клинки вилітають із позначених гравців у вибраних напрямках, завдаючи $358433s1 шкоди від тіні щосекунди протягом $358433D гравцям у радіусі $358433A1 м від будь-якої враженої цілі." },
    { en = "Sylvanas lets forth a shrill scream, inflicting damage based on each targeted player's health, starting at  ${$353955s1*($353955s2/100)} Shadow damage at full health, increasing to $353955s1 Shadow damage, to players within $353958A2 yards of each targeted player, silencing for $353957D.", ua = "Сильвана видає пронизливий вереск, завдаючи шкоди залежно від здоров'я кожного вибраного гравця, починаючи з ${$353955s1*($353955s2/100)} шкоди від тіні за повного здоров'я й зростаючи до $353955s1 шкоди від тіні, гравцям у радіусі $353958A2 м від кожного вибраного гравця, знемовлюючи на $353957D." },
    { en = "Executes a quadruple series of strikes at a player, each inflicting $358182s1 Physical damage and $358183s1 Shadow damage, applying $@spellname353929.", ua = "Завдає серії з чотирьох ударів по гравцю, кожен з яких завдає $358182s1 фізичної шкоди й $358183s1 шкоди від тіні, застосовуючи $@spellname353929." },
    { en = "Sylvanas gains a stack of $@spellname358185 every $358184T1 sec. Upon reaching $358185s1 stacks Sylvanas can replace a $@spellname347548 with $@spellname353969. Upon reaching $358185s2 stacks Sylvanas can replace a $@spellname348299 with $@spellname358181.", ua = "Сильвана отримує заряд $@spellname358185 кожні $358184T1 сек. Досягнувши $358185s1 зарядів, Сильвана може замінити $@spellname347548 на $@spellname353969. Досягнувши $358185s2 зарядів, Сильвана може замінити $@spellname348299 на $@spellname358181." },
    { en = "$@spellname349458 afflictions taint targets with $@spellname356651, inflicting $356652s1 Shadow damage to all players per stack if re-afflicted with $@spellname349458. This effect stacks and increases in damage by $356651s1% per stack.", ua = "Дія ефекту $@spellname349458 заражає цілі ефектом $@spellname356651, завдаючи $356652s1 шкоди від тіні всім гравцям за кожен заряд, якщо їх знову вражено ефектом $@spellname349458. Цей ефект накопичується, і шкода зростає на $356651s1% за кожен заряд." },
    { en = "Sylvanas gains a stack of $@spellname353965 every $353966T1 sec. Upon reaching $353966s1 stacks Sylvanas can replace a $@spellname347548 with a triple burst of $@spellname353969 into her target. Each arrow inflicts $353968s1 Physical damage and $353967s1 Shadow damage, applying $@spellname353929.", ua = "Сильвана отримує заряд «$@spellname353965» кожні $353966T1 с. Сягнувши $353966s1 зарядів, Сильвана може замінити «$@spellname347548» потрійним залпом «$@spellname353969» у свою ціль. Кожна стріла завдає $353968s1 од. фізичної шкоди та $353967s1 од. шкоди від магії Тіні, накладаючи «$@spellname353929»." },
    { en = "Sylvanas launches a terror-infused arrow at a player, inflicting $358708s1 Shadow damage and additionally inflicting up to $358709s2 Shadow damage to all other players, decreasing in damage based on distance from the point of impact.\n\n\n\nUpon impact, summons $358706s1 Dark Sentinels nearby. Each time $@spellname358704 completes, Sylvanas gains $@spellname358724, increasing the number of Dark Sentinels summoned. This effect stacks.", ua = "Сильвана випускає сповнену жаху стрілу в гравця, завдаючи $358708s1 шкоди від тіні, а також до $358709s2 шкоди від тіні всім іншим гравцям; шкода зменшується залежно від відстані до точки влучання.\n\n\n\nПри влучанні поряд прикликає темних вартових ($358706s1). Щоразу, коли $@spellname358704 завершується, Сильвана отримує $@spellname358724, збільшуючи кількість прикликаних темних вартових. Цей ефект накопичується." },
    { en = "Fires a triple burst of arrows at a player, each inflicting $353968s1 Physical damage and $353967s1 Shadow damage, applying $@spellname353929.", ua = "Випускає потрійний залп стріл у гравця; кожна завдає $353968s1 фізичної шкоди і $353967s1 шкоди від тіні та накладає $@spellname353929." },
    { en = "Sylvanas jettisons a volley of arrows, inflicting $347928s1 Shadow damage to players within $353972A1 yards at the impact location, creating a pool of $@spellname353929.", ua = "Сильвана випускає залп стріл, завдаючи $347928s1 шкоди від тіні гравцям у радіусі $353972A1 м від точки влучання та створюючи калюжу $@spellname353929." },
    { en = "The Summoner enters a deathly trance, summoning $356021s1 |4Decrepit Orb:Decrepit Orbs; and $356021s2 |4Terror Orb:Terror Orbs; nearby.", ua = "Призивач поринає в смертельний транс, прикликаючи поряд орбів розкладу ($356021s1) та орбів жаху ($356021s2)." },
    { en = "The Dark Sentinel enters into a blind fury, fixating on a target and refusing to attack any others. Every $358711T2 sec. the Dark Sentinel gains additional $@spellname358711, increasing damage done by $358722s1% and preventing them from being slowed below $358722s2% of normal speed. This effect stacks.", ua = "Темний вартовий впадає в сліпу лють, зосереджуючись на одній цілі й відмовляючись атакувати інших. Кожні $358711T2 с темний вартовий отримує додатковий ефект $@spellname358711, що збільшує завдану шкоду на $358722s1% і не дає сповільнити його нижче $358722s2% звичайної швидкості. Цей ефект накопичується." },
    { en = "Sylvanas enshrouds an area in fog, inflicting $350777s1 Shadow damage and afflicting enemies within a deathly cloud, absorbing $347704s2 healing and inflicting $357726s1 Shadow damage every half-second.\n\n\n\n${100-$347704s3}% of all healing bypasses this absorb.\n\n$?diff15|diff16\n\n[This effect begins at $347704s5 stacks, and every second attempts to transfer 1 stack to a nearby player within $347704s4 yards.][]", ua = "Сильвана огортає ділянку туманом, завдаючи $350777s1 шкоди від тіні й оповиваючи ворогів усередині смертельною хмарою, що поглинає $347704s2 зцілення і завдає $357726s1 шкоди від тіні щопівсекунди.\n\n\n\n${100-$347704s3}% усього зцілення оминають це поглинання.\n\n$?diff15|diff16\n\n[Цей ефект починається з $347704s5 зарядів і щосекунди намагається передати 1 заряд гравцеві поряд у межах $347704s4 м.][]" },
    { en = "Manifests an orb of dread which repeatedly attempts to fear all players within $356023A1 yards for $356023D.", ua = "Проявляє орб жаху, що раз по раз намагається посіяти страх серед усіх гравців у радіусі $356023A1 м на $356023D." },
    { en = "The Goliath blindly rages at a target, increasing damage done by $351672s2% and melee attack speed by $351672s1% when melee attacking the same enemy. This effect stacks.", ua = "Ґоліаф сліпо лютує на ціль, збільшуючи завдану шкоду на $351672s2% і швидкість атак ближнього бою на $351672s1% під час атак ближнього бою по тому самому ворогу. Цей ефект накопичується." },
    { en = "$@spellname351562 explosions apply $@spellname356024, inflicting $356024s1 Shadow damage every half-second for $356024D. This effect stacks.", ua = "Вибухи $@spellname351562 накладають $@spellname356024, завдаючи $356024s1 шкоди від тіні щопівсекунди протягом $356024D. Цей ефект накопичується." },
    { en = "The Jailer's assault is endless. Periodically, fragments of the battery rain down upon the nearby platforms, inflicting $358589s1 Shadow damage to players within $358588A1 yards of the point of impact. \n\n\n\nIf no players are within $358588A1 yards, the damage increases to $358592s1 Shadow damage to all players within $358592A1 yards from the impact location.", ua = "Наступ Тюремника нескінченний. Періодично уламки батареї дощем падають на ближні платформи, завдаючи $358589s1 шкоди від тіні гравцям у радіусі $358588A1 м від точки влучання.\n\n\n\nЯкщо в радіусі $358588A1 м немає жодного гравця, шкода зростає до $358592s1 шкоди від тіні всім гравцям у радіусі $358592A1 м від точки влучання." },
    { en = "Recites a chant of destruction, inflicting $358216s1 Shadow damage to all players every second while no players are within $358215s1 yards.", ua = "Промовляє наспів руйнування, завдаючи $358216s1 шкоди від тіні всім гравцям щосекунди, доки жоден гравець не перебуває в радіусі $358215s1 м." },
    { en = "The Colossus focuses anima into afflicted players every $351562T1 sec for $351562D. This anima explodes after $351570D, inflicting $351571s1 Shadow damage, divided amongst players within $351571A1 yards.", ua = "Колос зосереджує аніму в уражених гравців кожні $351562T1 с протягом $351562D. Ця аніма вибухає через $351570D, завдаючи $351571s1 шкоди від тіні, що розподіляється між гравцями в радіусі $351571A1 м." },
    { en = "The Souljudge charges towards an enemy, striking them for $351179s1 Physical damage and additionally applies $@spellname351180.", ua = "Суддя душ кидається на ворога, завдаючи йому $351179s1 фізичної шкоди, а також накладає $@spellname351180." },
    { en = "Inflicts $s1 Physical damage to a player every second for $D. This effect stacks, and cannot be dodged, blocked, or parried, and cannot miss.", ua = "Завдає $s1 фізичної шкоди гравцеві щосекунди протягом $D. Цей ефект накопичується, його не можна ухилитися, заблокувати чи парирувати, і він не може схибити." },
    { en = "Sylvanas lets forth a shrill scream, inflicting damage based on each targeted player's health, starting at  ${$348109s1*($348109s2/100)} Shadow damage at full health, increasing to $348109s1 Shadow damage, to players within $348108A2 yards of each targeted player, interrupting for $351252D.", ua = "Сильвана видає пронизливий зойк, завдаючи шкоди залежно від здоров'я кожної ураженої цілі: від ${$348109s1*($348109s2/100)} шкоди від тіні за повного здоров'я до $348109s1 шкоди від тіні, гравцям у радіусі $348108A2 м від кожної ураженої цілі, а також перериваючи їх на $351252D." },
    { en = "Sylvanas looses a cavalcade of infused arrows, erupting for $356377s1 Shadow damage to players within the area of effect.", ua = "Сильвана випускає шквал сповнених сили стріл, що вибухають і завдають $356377s1 шкоди від тіні гравцям у зоні дії." },
    { en = "Sylvanas lays waste to the area, inflicting $355546s1 Shadow damage to all players. This damage cannot be mitigated or avoided.", ua = "Сильвана спустошує ділянку, завдаючи $355546s1 шкоди від тіні всім гравцям. Цю шкоду неможливо ні зменшити, ні уникнути." },
    { en = "Manifests a sphere of domination energy. These orbs increase damage done by $351317s2% every $351317T1 sec. This effect stacks.", ua = "Проявляє сферу енергії панування. Ці сфери збільшують завдану шкоду на $351317s2% кожні $351317T1 с. Цей ефект накопичується." },
    { en = "Inflicts $367607s1 Shadow damage every second for $347607D. This effect stacks.", ua = "Завдає $367607s1 шкоди від тіні щосекунди протягом $347607D. Цей ефект накопичується." },
    { en = "Sylvanas launches a terror-infused arrow at a player, inflicting $357617s1 Shadow damage and additionally inflicting up to $357618s2 Shadow damage to all other players, decreasing in damage based on distance from the point of impact.", ua = "Сильвана випускає сповнену жаху стрілу в гравця, завдаючи $357617s1 шкоди від тіні, а також до $357618s2 шкоди від тіні всім іншим гравцям; шкода зменшується залежно від відстані до точки влучання." },
    { en = "Upon death or after casting $@spellname351323, the orb explodes, inflicting $351324s1 Shadow damage to enemies within $351324A1 yards.", ua = "При загибелі або після застосування $@spellname351323 орб вибухає, завдаючи $351324s1 шкоди від тіні ворогам у радіусі $351324A1 м." },
    { en = "The Summoner curses afflicted targets, inflicting $351451s1 Shadow damage plus an additional $351451s2 Shadow damage every $351451T2 sec and reducing movement speed by $351451s3% for $351451D. Each cast grants $@spellname351452, increasing this curse's duration by $351452s1 seconds.", ua = "Призивач проклинає уражені цілі, завдаючи $351451s1 шкоди від тіні та додатково $351451s2 шкоди від тіні кожні $351451T2 с і знижуючи швидкість пересування на $351451s3% протягом $351451D. Кожне застосування дарує $@spellname351452, збільшуючи тривалість цього прокляття на $351452s1 с." },
    { en = "The Vanguard slams the ground, inflicting $s1 Physical damage to enemies within $A1 yards of the point of impact.", ua = "Передовик б'є об землю, завдаючи $s1 фізичної шкоди ворогам у радіусі $A1 м від точки влучання." },
    { en = "Sylvanas unloads a Death-empowered arrow, annihilating the impact location inflicting $354145s2 Shadow damage to targets within $354145A2 yards and additionally desecrates the area, inflicting $354146s1 Shadow damage every $354146T1 sec.\n\n\n\nThis additionally destroys the $@spellname353642 connections to and from the contaminated area.", ua = "Сильвана випускає стрілу, наснажену силою Смерті, знищуючи точку влучання, завдаючи $354145s2 шкоди від тіні цілям у радіусі $354145A2 м, а також оскверняючи ділянку, що завдає $354146s1 шкоди від тіні кожні $354146T1 с.\n\n\n\nЦе також руйнує з'єднання $@spellname353642 до зараженої ділянки та з неї." },
    { en = "The Colossus releases a shadowy barrage in a targeted direction, inflicting $351591s2 Shadowstrike damage and increasing $@spellname351589 damage taken by $351591s3% for $351591D to players in a frontal cone.  This effect stacks, and cannot be dodged, blocked, or parried, and cannot miss.", ua = "Колос випускає тіньовий шквал у вибраному напрямку, завдаючи $351591s2 шкоди тіньовим ударом і збільшуючи отримувану від $@spellname351589 шкоду на $351591s3% протягом $351591D гравцям у фронтальному конусі. Цей ефект накопичується, його не можна ухилитися, заблокувати чи парирувати, і він не може схибити." },
    { en = "The chamber engages a defensive configuration providing players with access to traverse the arena. Upon traversal, players gain $354175s2% increased movement speed for $354175D.", ua = "Камера переходить у захисну конфігурацію, відкриваючи гравцям шлях для пересування ареною. Перетнувши її, гравці отримують збільшення швидкості пересування на $354175s2% протягом $354175D." },
    { en = "Sylvanas Windrunner is by far one of the most talented fighters from Azeroth, and can execute multiple abilities in quick succession, rapidly changing position to suit her combat needs. While under the effects of $@spellname347504, spells and abilities strike Sylvanas where she cast $@spellname347504.", ua = "Сильвана Віндраннер — безперечно одна з найталановитіших воїтельок Азероту: вона здатна виконувати кілька здібностей у швидкій послідовності, миттєво змінюючи позицію відповідно до потреб бою. Поки діє $@spellname347504, закляття й здібності влучають у Сильвану там, де вона застосувала $@spellname347504." },
    { en = "Sylvanas rips fragments of Torghast, sending them in a targeted direction inflicting $348145s1 Physical damage to all players in the chunk's path.", ua = "Сильвана відриває уламки Торгасту й кидає їх у вибраному напрямку, завдаючи $348145s1 фізичної шкоди всім гравцям на шляху уламка." },
    { en = "Gains the ability to fly.", ua = "Дарує здатність літати." },
    { en = "The Souljudge projects disgrace to players within $355826A1 yards, decreasing damage done by up to $355827s1% based on missing health.", ua = "Суддя Душ випромінює ганьбу на гравців у радіусі $355826A1 м, знижуючи завдану ними шкоду на величину до $355827s1% залежно від бракуючого здоров'я." },
    { en = "The Hopebreaker channels destabilizing magic into afflicted targets, reducing movement speed by $s3%, inflicting $s1 Shadow damage every second and additionally absorbing healing equal to $s4% of the target's health for $351091D. This effect stacks.", ua = "Згубниця надії спрямовує дестабілізуючу магію в уражені цілі, знижуючи швидкість пересування на $s3%, завдаючи $s1 шкоди від тіні щосекунди й додатково поглинаючи зцілення, рівне $s4% здоров'я цілі, протягом $351091D. Цей ефект накопичується." },
    { en = "The Summoner creates $351353s1 Decrepit Orbs.", ua = "Призивач створює орбів розкладу ($351353s1)." },
    { en = "Sylvanas releases rolling energy, pushing away enemies upon contact with the waves and inflicts $351870s1 Shadow damage every half-second for $351869D. This effect stacks.", ua = "Сильвана вивільняє хвилю енергії, що відштовхує ворогів при дотику й завдає $351870s1 шкоди від тіні щопівсекунди протягом $351869D. Цей ефект накопичується." },
    { en = "Carrying the Unstable Core reduces the player's movement speed by $s4% and inflicts $369404s1 Cosmic damage every $t5 sec. \n\n\n\nThe Unstable Core can be Detonated when it is near the Vigilant Guardian.\n\n\n\n$@spelltooltip360528", ua = "Носіння Нестабільного Ядра знижує швидкість пересування гравця на $s4% і завдає $369404s1 космічної шкоди кожні $t5 с. \n\n\n\nНестабільне Ядро можна підірвати, коли воно поряд із Пильним Вартовим.\n\n\n\n$@spelltooltip360528" },
    { en = "The Vigilant Guardian creates a Spike of Creation at the target location.\n\nA player coming into contact with the Spike of Creation will cause it to explode, $?DIFF15|DIFF16[inflicting $s1 Cosmic damage every $t1 sec for $d to all players.][inflicting $s1 Cosmic damage to all players.]$?DIFF16[\n\n\n\nThis effect stacks.][]", ua = "Пильний Вартовий створює Шпичак Творіння в цільовій точці.\n\nКоли гравець торкається Шпичака Творіння, той вибухає, $?DIFF15|DIFF16[завдаючи $s1 космічної шкоди всім гравцям кожні $t1 с протягом $d.][завдаючи $s1 космічної шкоди всім гравцям.]$?DIFF16[\n\n\n\nЦей ефект накопичується.][]" },
    { en = "At 50 energy, the Pre-Fabricated Sentry slams the player for $s1 Cosmic damage.  The victim's defenses vibrate with dissonant frequencies that increase the damage taken by further attacks of Dissonance by $s2% for $d. This effect stacks.", ua = "При 50 енергії Заготовлений Вартовий вдаряє гравця, завдаючи $s1 космічної шкоди.  Захист жертви вібрує дисонансними частотами, що збільшують шкоду, отриману від подальших атак Дисонансу, на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The Vigilant Guardian overloads its core as a final act to defend the Sepulcher of the First Ones.\n\nEvery $t1 sec. the Vigilant Guardian inflicts $364963s1 Cosmic damage to all players. This damage increases by $364963s2% every $t1 sec.", ua = "Пильний Вартовий перевантажує своє ядро як останній крок, щоб захистити Гробницю Перших.\n\nКожні $t1 с Пильний Вартовий завдає $364963s1 космічної шкоди всім гравцям. Ця шкода збільшується на $364963s2% кожні $t1 с." },
    { en = "The Pre-Fabricated Sentry smashes the ground beneath the player.\n\nThe impact creates a Wave of Disintegration zones that explode in rapid succession, inflicting $360999s1 Cosmic damage to all players caught in the blast.", ua = "Збірна Вартова сторожа гатить по землі під гравцем.\n\nУдар створює зони Хвилі Розпаду, що вибухають швидкою чергою, завдаючи $360999s1 космічної шкоди всім гравцям, заскоченим вибухом." },
    { en = "Damage sustained to this point has fractured the Vigilant Guardian's core. All players suffer $364845s1 Cosmic damage every $t1 sec.", ua = "Завдана досі шкода розколола ядро Пильного Вартового. Усі гравці зазнають $364845s1 космічної шкоди кожні $t1 с." },
    { en = "This automa is in low power mode until it is restored to full power.", ua = "Цей автома перебуває в режимі низького живлення, доки йому не відновлять повну потужність." },
    { en = "The Vigilant Guardian fires a beam of immense power that sweeps the battlefield and triggers several explosions, each inflicting $s1 Cosmic damage to all players caught within the blast.", ua = "Пильний Вартовий випускає промінь величезної сили, що змітає поле бою і спричиняє кілька вибухів, кожен з яких завдає $s1 космічної шкоди всім гравцям, заскоченим вибухом." },
    { en = "The Point Defense Drone channels cosmic energy at a random player, inflicting $s1 Cosmic damage every $t1 sec. for $d.", ua = "Дрон ближнього захисту скеровує космічну енергію на випадкового гравця, завдаючи $s1 космічної шкоди кожні $t1 с протягом $d." },
    { en = "The Point Defense Drone teleports away and chooses a random player to attack.", ua = "Дрон ближнього захисту телепортується геть і обирає для атаки випадкового гравця." },
    { en = "After exposing its core, the Vigilant Guardian can Overclock its processes.  Each time it Overclocks, its damage increases by $367561s1%.", ua = "Оголивши своє ядро, Пильний Вартовий може розігнати свої процеси. Щоразу під час розгону його шкода збільшується на $367561s1%." },
    { en = "The Vigilant Guardian increases its damage output by $s1%.", ua = "Пильний Вартовий збільшує завдану шкоду на $s1%." },
    { en = "The Unstable Core detonates, inflicting $s1% of the Vigilant Guardian's maximum health.\n\n$?DIFF16[The detonation cancels Optimal Core Temperature and any affects of Overclocking.][]", ua = "Нестабільне Ядро детонує, завдаючи шкоди в розмірі $s1% максимального здоров'я Пильного Вартового.\n\n$?DIFF16[Детонація скасовує Оптимальну Температуру Ядра та будь-які ефекти Розгону.][]" },
    { en = "The Vigilant Guardian marks the player for Matter Dissolution. After $d., multiple orbs of Anti-Matter form in a large circle around the player. \n\nThe orbs move in toward the player, inflicting $364904s1 Cosmic damage to any player they come in contact with.  Players affected this way take $364904s2% more damage from other orbs of Anti-Matter for $364904d. This effect stacks.$?DIFF15|DIFF16[\n\nWhen Matter Disolution ends the player is slowed by $366805s1% for $366805d.][]", ua = "Пильний Вартовий позначає гравця для Розпаду Матерії. Через $d навколо гравця у великому колі формується кілька куль Антиматерії. \n\nКулі рухаються до гравця, завдаючи $364904s1 космічної шкоди кожному гравцю, якого торкаються. Уражені так гравці зазнають на $364904s2% більше шкоди від інших куль Антиматерії протягом $364904d. Цей ефект накопичується.$?DIFF15|DIFF16[\n\nКоли Розпад Матерії закінчується, гравця сповільнено на $366805s1% протягом $366805d.][]" },
    { en = "The Automated Defense Matrix creates a force field that reduces the damage taken from Exposed Core by $s1%.\n\n\n\nThe Force Field persists until Exposed Core ends.\n\n\n\nWhen Force Field ends the Automated Defense Matrix $?DIFF15|DIFF16[attacks players.][dies.]", ua = "Автоматизована Захисна Матриця створює силове поле, що зменшує шкоду, отриману від Оголеного Ядра, на $s1%.\n\n\n\nСилове поле зберігається, доки не завершиться Оголене Ядро.\n\n\n\nКоли силове поле завершується, Автоматизована Захисна Матриця $?DIFF15|DIFF16[атакує гравців.][гине.]" },
    { en = "The Automated Defense Matrix channels cosmic energy at a random player, inflicting $s1 Cosmic damage every $t1 sec. for $d.", ua = "Автоматизована Захисна Матриця скеровує космічну енергію на випадкового гравця, завдаючи $s1 космічної шкоди кожні $t1 с протягом $d." },
    { en = "The Vigilant Guardian exposes its core to cool down. All players suffer $360409s1 Cosmic damage every $t1 sec. for $d.\n\n$?DIFF16[Once complete, the Vigilant Guardian starts operating at Optimal Core Temperature.][]", ua = "Пильний Страж оголює своє ядро для охолодження. Усі гравці зазнають $360409s1 космічної шкоди кожні $t1 сек. протягом $d.\n\n$?DIFF16[Після завершення Пильний Страж починає працювати за Оптимальної Температури Ядра.][]" },
    { en = "At 50 energy the Vigilant Guardian slams the player for $s1 Cosmic damage. Damage taken from further Pneumatic Impacts is increased by $s2% for $d.", ua = "При 50 енергії Пильний Вартовий гатить по гравцю, завдаючи $s1 космічної шкоди. Шкода від подальших Пневматичних Ударів збільшується на $s2% протягом $d." },
    { en = "The Vigilant Guardian smashes the ground beneath the player, inflicting $s2 Cosmic damage.\n\nThe impact creates a series of Split Resolution zones that explode in rapid succession, inflicting $360257s1 Cosmic damage to all players caught in the blast.", ua = "Пильний Страж б'є по землі під гравцем, завдаючи $s2 космічної шкоди.\n\nУдар створює низку зон Розщепленої Резолюції, що вибухають швидко одна за одною, завдаючи $360257s1 космічної шкоди всім гравцям, які потрапили під вибух." },
    { en = "The Vigilant Guardian fires beams of Cosmic energy at random players, inflicting $s1 Cosmic damage to all players caught in the blast.", ua = "Пильний Вартовий випускає промені космічної енергії у випадкових гравців, завдаючи $s1 космічної шкоди всім гравцям, заскоченим вибухом." },
    { en = "The Vigilant Guardian's core radiates  $366943s1 Cosmic damage to all players every $t1 sec.", ua = "Ядро Пильного Вартового випромінює $366943s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "The Anti-Matter orb inflicts $s1 Cosmic damage to any player it comes in contact with. \n\nAnti-Matter increases the damage taken from other orbs of Anti-Matter by $s2% for $d. This effect stacks.", ua = "Куля Антиматерії завдає $s1 космічної шкоди кожному гравцю, якого торкається. \n\nАнтиматерія збільшує шкоду від інших куль Антиматерії на $s2% протягом $d. Цей ефект накопичується." },
    { en = "Volatile Materium adapt their combat parameters the longer they are in combat. Every $t1s the Adaptive Subroutines increase the movement speed of the Volatile Materium by $367342s1% and their damage done by $367342s2%.", ua = "Що довше Нестабільні Матеріуми перебувають у бою, то більше пристосовують свої бойові параметри. Кожні $t1 с адаптивні підпрограми збільшують швидкість пересування Нестабільного Матеріуму на $367342s1%, а завдану ним шкоду — на $367342s2%." },
    { en = "The Point Defense Drone Fires a volley of missiles at random players, inflicting $360177s1 Cosmic damage to all players within $360177a1 yards of the victim.", ua = "Дрон ближнього захисту випускає залп ракет у випадкових гравців, завдаючи $360177s1 космічної шкоди всім гравцям у межах $360177a1 м від жертви." },
    { en = "The Automated Defense Matrix creates a force field that reduces the damage taken by allies within $s2 yards by $s1%.", ua = "Автоматизована Захисна Матриця створює силове поле, що зменшує шкоду, якої зазнають союзники в межах $s2 м, на $s1%." },
    { en = "Skolex's thrashing movements fling dust at several players furthest from it$?DIFF17|DIFF14[.][, inflicting $s1 Cosmic damage to all players within $A1 yards of the targets.] Applies $@spellname359778.", ua = "Несамовиті рухи Сколекса жбурляють пил у кількох найвіддаленіших від нього гравців$?DIFF17|DIFF14[.][, завдаючи $s1 космічної шкоди всім гравцям у межах $A1 м від цілей.] Накладає $@spellname359778." },
    { en = "Skolex devours $@spellname359778, mutating painfully and increasing its damage done by $s1%. This effect stacks.", ua = "Сколекс пожирає $@spellname359778, болісно мутуючи і збільшуючи завдану ним шкоду на $s1%. Цей ефект накопичується." },
    { en = "Inflicts $s2 Cosmic damage every $t2 sec. for $d. This effect stacks.", ua = "Завдає $s2 космічної шкоди кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "Skolex retches up reality boring acid on all players in a frontal cone, inflicting $s2 Shadow damage on impact and $s1 Shadow damage every $t1 for $d.\n\n\n\nIn addition, $?DIFF15|DIFF16[players will be teleported randomly twice while afflicted][players will be teleported randomly at the end of the duration].", ua = "Сколекс вивергає реальність-роз'їдаючу кислоту на всіх гравців у фронтальному конусі, завдаючи $s2 шкоди від тіні при влучанні та $s1 шкоди від тіні кожні $t1 протягом $d.\n\n\n\nКрім того, $?DIFF15|DIFF16[гравців під час дії ефекту двічі випадково телепортує][гравців випадково телепортує наприкінці дії ефекту]." },
    { en = "The player tears through reality, disorienting them for $d.", ua = "Гравець прориває реальність, що дезорієнтує його на $d." },
    { en = "Skolex breaths reality tearing energies on $?DIFF14|DIFF17[its current target][all players in a $A1 yard frontal cone], inflicting $359976s1 Shadow damage and increasing damage taken by Riftmaw by $s2% for $d.", ua = "Сколекс видихає реальність-роздираючі енергії на $?DIFF14|DIFF17[свою поточну ціль][всіх гравців у фронтальному конусі завширшки $A1 м], завдаючи $359976s1 шкоди від тіні та збільшуючи шкоду, якої цілі зазнають від Розломопащі, на $s2% протягом $d." },
    { en = "Skolex's melee attacks hit the next closest player within $A2 yards for Physical damage. If no players are in range, the primary target is struck twice.", ua = "Атаки Сколекса в ближньому бою влучають у наступного найближчого гравця в межах $A2 м, завдаючи фізичної шкоди. Якщо в радіусі немає гравців, головну ціль вражає двічі." },
    { en = "Skolex flings blood from its wounds, inflicting $s1 Shadow damage to players within $A1 yards of the impact locations. The ichor inflicts $s2 Shadow damage every $t2 sec. and reduces Haste by $s3% for $d.$?DIFF16[ This effect stacks.][]", ua = "Сколекс розбризкує кров зі своїх ран, завдаючи $s1 шкоди від тіні гравцям у межах $A1 м від місць влучання. Сукровиця завдає $s2 шкоди від тіні кожні $t2 с і знижує Поспіх на $s3% протягом $d.$?DIFF16[ Цей ефект накопичується.][]" },
    { en = "If no targets are engaged in melee, Skolex annihilates a player with destructive bile, inflicting $367517s1 Shadow damage.", ua = "Якщо жодна ціль не вступила в ближній бій, Сколекс знищує гравця руйнівною жовчю, завдаючи $367517s1 шкоди від тіні." },
    { en = "Skolex rends the flesh of $?DIFF14|DIFF17[its current target][all players in a $A1 yard frontal cone], inflicting $359980s1 Physical damage on impact and $s1 Physical damage every $t1 sec. for $d.", ua = "Сколекс роздирає плоть $?DIFF14|DIFF17[своєї поточної цілі][всіх гравців у фронтальному конусі завширшки $A1 м], завдаючи $359980s1 фізичної шкоди при влучанні та $s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Skolex thrashes in the sand, inflicting $s2 Physical damage to all players and applying $@spellname359778.", ua = "Сколекс несамовито борсається в піску, завдаючи $s2 фізичної шкоди всім гравцям і накладаючи $@spellname359778." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec. to players who stand within it.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с гравцям, які стоять усередині." },
    { en = "Skolex $?DIFF17[occasionally ][]burrows and attacks $?DIFF17[the largest clump of players][if it detects all players in a single clump], inflciting $s3 Physical damage to all players within $A1 yards, knocking them back, and consuming their applications of $@spellname359778. $?DIFF17[][\n\n\n\nEach time Skolex burrows it leaves behind $@spellname360411 at its previous location and gains a stack of $@spellname360193.]", ua = "Сколекс $?DIFF17[час від часу ][]зариваєтся під землю й атакує $?DIFF17[найбільше скупчення гравців][, якщо виявляє, що всі гравці зібралися в одне скупчення], завдаючи $s3 фізичної шкоди всім гравцям у радіусі $A1 м, відкидаючи їх та поглинаючи їхні застосування $@spellname359778. $?DIFF17[][\n\n\n\nЩоразу, зариваючись, Сколекс лишає по собі $@spellname360411 на попередньому місці й отримує стак $@spellname360193.]" },
    { en = "Skolex leaves behind a collapsing rift that inflicts $s1 Shadow damage to all targets within $A1 yards.", ua = "Сколекс лишає по собі колапсуючий розлом, що завдає $s1 шкоди від тіні всім цілям у межах $A1 м." },
    { en = "If no players are present at the location where Skolex emerges, the shockwave of dust inflicts $s1 Cosmic damage, and applies $s2 stacks of $@spellname359778 to all players.", ua = "Якщо в місці появи Сколекса немає жодного гравця, ударна хвиля пилу завдає $s1 космічної шкоди й накладає $s2 стос. $@spellname359778 на всіх гравців." },
    { en = "Xy'mox calls in Xy Reinforcements as he deciphers the secrets of the Genesis Relic, causing $@spellname363114 every $t2 sec until the Xy Reinforcements are slain.", ua = "Ксай'мокс викликає Підкріплення Ксай, поки розшифровує таємниці Реліквії Генезису, спричиняючи $@spellname363114 кожні $t2 сек, доки Підкріплення Ксай не буде знищено." },
    { en = "Xy'mox deploys a set of Stasis Traps at the locations of several players, after $s1 sec the traps arm. \n\n\n\nPlayers that trip a $@spellname362885 are stunned and suffer $362882s1 Arcane damage every $362882t1 sec until the $@spellname362885 is destroyed.", ua = "Ксай'мокс розставляє стазис-пастки в місцях кількох гравців; за $s1 с пастки активуються.\n\n\n\nГравці, що зачіпають $@spellname362885, приголомшуються й зазнають $362882s1 арканної шкоди кожні $362882t1 с, доки $@spellname362885 не буде знищено." },
    { en = "Upon reaching 100 energy, Xy Acolytes become immune to all forms of crowd control and transform into a Hyperlight Archon, inflicting $367509s1 Arcane damage to all players.", ua = "Досягнувши 100 енергії, послушники Ксай стають несприйнятливими до всіх форм контролю та перетворюються на гіперсвітлового архонта, завдаючи $367509s1 арканної шкоди всім гравцям." },
    { en = "Cartel Plunderers decipher the secrets of Progenitor relics, causing $@spellname365752 to vent every $365751t1 sec until the Cartel Plunderers are slain.\n\n\n\nIf the cast completes, the relic begins to emit $@spellname363413.", ua = "Грабіжники картелю розгадують таємниці реліквій Прародителів, через що $@spellname365752 виривається кожні $365751t1 с, доки грабіжників картелю не буде вбито.\n\n\n\nЯкщо творення завершиться, реліквія починає випромінювати $@spellname363413." },
    { en = "The Genesis Relic activates rings of cosmic energy that inflict $363413s1 Cosmic damage to players who pass through them and an additional $364604s1 Cosmic damage every $364604t1 sec for $364604d.", ua = "Релікт Генезису активує кільця космічної енергії, що завдають $363413s1 космічної шкоди гравцям, які крізь них проходять, та додатково $364604s1 космічної шкоди кожні $364604t1 с протягом $364604d." },
    { en = "Xy'mox deploys a set of Stasis Traps at the locations of several players, after $s1 sec the traps arm. \n\n\n\nPlayers that trip a $@spellname362885 are stunned and suffer $362882s1 Arcane damage every $362882t1 sec until the $@spellname362885 is destroyed.\n\n\n\nUpon being triggered, the trap rearms.", ua = "Ксай'мокс розставляє стазис-пастки в місцях кількох гравців; за $s1 с пастки активуються.\n\n\n\nГравці, що зачіпають $@spellname362885, приголомшуються й зазнають $362882s1 арканної шкоди кожні $362882t1 с, доки $@spellname362885 не буде знищено.\n\n\n\nПісля спрацьовування пастка зводиться знову." },
    { en = "The Cartel Overseer is protected by rotating body absorbing all attacks from the direction the armor faces.", ua = "Наглядач картелю захищений обертовою бронею, що поглинає всі атаки з того боку, куди вона повернена." },
    { en = "Xy'mox marks his primary target, inflicting $362802s1 Arcane damage every $362803t1 sec for $362803d.\n\n\n\nWhen $@spellname362801 expires it inflicts $362835s1 Arcane damage to all players and pulls them to the target, afflicting the primary target with $@spellname362837 for $362837d.\n\n\n\nThis damage is reduced the farther players are from the blast.", ua = "Ксай'мокс позначає свою основну ціль, завдаючи їй $362802s1 арканної шкоди кожні $362803t1 с протягом $362803d.\n\n\n\nКоли $@spellname362801 завершується, він завдає $362835s1 арканної шкоди всім гравцям і притягує їх до цілі, накладаючи на основну ціль $@spellname362837 на $362837d.\n\n\n\nЦя шкода тим менша, чим далі гравці від вибуху." },
    { en = "Progenitor relics radiate energy every $365751t1 sec, inflicting $s1 Cosmic damage to all players and increasing damage taken from $@spellname365751 by $s2%.", ua = "Реліквії Прародителів випромінюють енергію кожні $365751t1 с, завдаючи $s1 космічної шкоди всім гравцям і збільшуючи отримувану від $@spellname365751 шкоду на $s2%." },
    { en = "Cartel gunships bombard the area with ordnance, inflicting $s1 Arcane damage to players within $a1 yds of the impact.", ua = "Канонерки картелю засипають місцевість снарядами, завдаючи $s1 арканної шкоди гравцям у межах $a1 м від місця влучання." },
    { en = "Xy'mox channels the power of the relic into a protective barrier, reducing damage taken by $s1%.\n\n\n\nThis effect is removed when all Xy Reinforcements are slain.", ua = "Ксай'мокс спрямовує силу реліквії в захисний бар'єр, зменшуючи отримувану шкоду на $s1%.\n\n\n\nЦей ефект знімається, коли все підкріплення Ксай буде вбито." },
    { en = "Xy'mox marks players, after $362614d the mark detonates, inflicting $364670s1 Arcane damage to players within $364670a1 yards and creating a wormhole at their location.\n\n\n\nPlayers can travel between wormholes.", ua = "Ксай'мокс позначає гравців; за $362614d позначка детонує, завдаючи $364670s1 арканної шкоди гравцям у радіусі $364670a1 м і створюючи на їхньому місці червоточину.\n\n\n\nГравці можуть переміщатися між червоточинами." },
    { en = "Xy'mox creates a hyperlight spark that jumps between all players, inflicting $s1 Arcane damage instantly and $s1 Arcane damage every $t1 sec for $d to all players within $a1 yds. This effect stacks.", ua = "Ксай'мокс створює іскру гіперсвітла, що перескакує між усіма гравцями, завдаючи $s1 арканної шкоди миттєво та $s1 арканної шкоди кожні $t1 с протягом $d усім гравцям у радіусі $a1 м. Цей ефект накопичується." },
    { en = "The relic collapses, leaving behind residual energy inflicting $s1 Cosmic damage every $t1 sec to all players in the effect.", ua = "Реліквія руйнується, лишаючи по собі залишкову енергію, що завдає $s1 космічної шкоди кожні $t1 с усім гравцям у зоні ефекту." },
    { en = "The Genesis Relic radiates energy every $363112t1 sec, inflicting $s1 Cosmic damage to all players and increasing damage taken from $@spellname363114 by $s2% for $d.", ua = "Реліквія Генези випромінює енергію кожні $363112t1 с, завдаючи $s1 космічної шкоди всім гравцям і збільшуючи отримувану від $@spellname363114 шкоду на $s2% протягом $d." },
    { en = "An Arcane barrage is unleashed, inflicting $365681s2 Arcane damage in a frontal cone and increasing damage taken by $@spellname365681 by $365681s3% for $365681D. This effect stacks.", ua = "Вивільняється чародійський залп, що завдає $365681s2 арканної шкоди в передньому конусі та збільшує отримувану від $@spellname365681 шкоду на $365681s3% протягом $365681D. Цей ефект накопичується." },
    { en = "Xy Spellslingers inflict $s1 Arcane damage every $t1 sec and reduces movement speed by $s2% for $d.", ua = "Чароплети Ксай завдають $s1 арканної шкоди кожні $t1 с і зменшують швидкість пересування на $s2% протягом $d." },
    { en = "The collapse of the $@spellname361651 inflicts $s1% of Dausegne's health as Cosmic damage to her every $t1 sec. for $d.", ua = "Руйнування $@spellname361651 завдає Дозеґне космічної шкоди в розмірі $s1% її здоров'я кожні $t1 с протягом $d." },
    { en = "Dausegne fires an array of missiles out in front of her, inflicting $361418s1 Shadow damage to all players in their path.", ua = "Дозеґне випускає перед собою низку ракет, завдаючи $361418s1 шкоди від тіні всім гравцям на їхньому шляху." },
    { en = "Dausegne energizes herself with power from all of the dominated reservoirs, inflicting $365852s1 Shadow damage to all players, regenerating $s1% mana every $t1 sec, and triggering $@spellname361751 very frequently.", ua = "Дозеґне наснажує себе силою з усіх підкорених резервуарів, завдаючи $365852s1 шкоди від тіні всім гравцям, відновлюючи $s1% мани кожні $t1 с і дуже часто запускаючи $@spellname361751." },
    { en = "Upon reaching 0 mana, Dausegne siphons cosmic energy from a reservoir, refilling her energy and protecting her in a $@spellname363779.", ua = "Досягнувши 0 мани, Дозеґне висмоктує космічну енергію з резервуара, поповнюючи свою енергію та захищаючи себе $@spellname363779." },
    { en = "Dausegne's melee strikes infuse the target with energy, inflicting $s1 Cosmic damage every $t1 sec. for $d for each application.\n\n\n\nWhen this effect expires, the player will erupt with $@spellname361967, amplified by the number of applications of $@spellname361966.", ua = "Удари ближнього бою Дозеґне сповнюють ціль енергією, завдаючи $s1 космічної шкоди кожні $t1 с протягом $d за кожне накладання.\n\n\n\nКоли цей ефект завершується, із гравця вибухає $@spellname361967, посилений кількістю накладань $@spellname361966." },
    { en = "Infused energies release in a massive explosion, inflicting $s1 Cosmic damage to all players, increased by the number of applications of $@spellname361966.", ua = "Сповнена енергія вивільняється в потужному вибуху, завдаючи $s1 космічної шкоди всім гравцям; шкода збільшується з кількістю накладань $@spellname361966." },
    { en = "Dausegne creates a shield that absorbs $s3% of her maximum health in damage.", ua = "Дозеґне створює щит, що поглинає шкоду в розмірі $s3% її максимального здоров'я." },
    { en = "The Domination Core inflicts $s1 Shadow damage to the current target.", ua = "Ядро Панування завдає $s1 шкоди від тіні поточній цілі." },
    { en = "Dausegne channels Domination into a Reservoir of the First Ones, inflicting $s1 Shadow damage to all players every $363490t1 sec.$?DIFF17[][\n\n\n\nWhile channeling, pools of $@spellname361216 created by Domination Cores grow in size.]", ua = "Дозеґне спрямовує Панування в Резервуар Перших, завдаючи $s1 шкоди від тіні всім гравцям кожні $363490t1 с.$?DIFF17[][\n\n\n\nПід час спрямовування калюжі $@spellname361216, створені Ядрами Панування, збільшуються в розмірі.]" },
    { en = "Rings of energy expand from dominated reservoirs, inflicting $s1 Shadow damage when a player crosses the ring.\n\n\n\nIn addition, inflicts $368020s1 Shadow damage every $368020t1 sec. and increases damage taken from $@spellname361751 by $s2% for $d.", ua = "Кільця енергії розходяться від підкорених резервуарів, завдаючи $s1 шкоди від тіні, коли гравець перетинає кільце.\n\n\n\nКрім того, завдає $368020s1 шкоди від тіні кожні $368020t1 с і збільшує отримувану від $@spellname361751 шкоду на $s2% протягом $d." },
    { en = "A ring of energy expands from each dominated reservoir, inflicting $s1 Shadow damage to the player and $366423s1 Shadow damage to all allies in $366423A1 yards when a player crosses the ring.\n\n\n\nIn addition, inflicts $368020s1 Shadow damage every $368020t1 sec., and increases damage taken from $@spellname361751 by $s2% for $d.", ua = "Кільце енергії розходиться від кожного підкореного резервуара, завдаючи $s1 шкоди від тіні гравцеві та $366423s1 шкоди від тіні всім союзникам у межах $366423A1 м, коли гравець перетинає кільце.\n\n\n\nКрім того, завдає $368020s1 шкоди від тіні кожні $368020t1 с і збільшує отримувану від $@spellname361751 шкоду на $s2% протягом $d." },
    { en = "Domination Cores exude bolts of dark energy, inflicting $363399s1 Shadow damage to players within $363399A1 yards of the impacts, and creating pools that last for $361216d that inflict $361225s1 Shadow damage every $361225t1 sec. to those who stand in them.", ua = "Ядра Панування вивергають блискавки темної енергії, завдаючи $363399s1 шкоди від тіні гравцям у межах $363399A1 м від місць влучання та створюючи калюжі, що тривають $361216d і завдають $361225s1 шкоди від тіні кожні $361225t1 с тим, хто в них стоїть." },
    { en = "Dausegne channels out three orbs towards a player, inflicting $360964s3 Shadow damage split between all players in their paths, and pushing players back.$?DIFF15|DIFF16[\n\n\n\nPlayers hit take $364289s1% more damage from Staggering Barrage for $364289d.][]", ua = "Дозеґне спрямовує три сфери в бік гравця, завдаючи $360964s3 шкоди від тіні, розподіленої між усіма гравцями на їхньому шляху, та відкидаючи гравців.$?DIFF15|DIFF16[\n\n\n\nУражені гравці отримують на $364289s1% більше шкоди від Хиткого Залпу протягом $364289d.][]" },
    { en = "All players gain Burden of Sin as the Prototype of Absolution becomes active. Every $t1 sec, Burden of Sin inflicts $361607s1 Shadow damage per application.", ua = "Усі гравці отримують Тягар Гріха, коли Прототип Відпущення стає активним. Кожні $t1 с Тягар Гріха завдає $361607s1 шкоди від тіні за кожне накладання." },
    { en = "Inflicts $s1 Physical damage to players within $A1 yds of the Night Hunter's target.\n\n\n\nDamage is reduced for each player in the path of the Night Hunter.", ua = "Завдає $s1 фізичної шкоди гравцям у межах $A1 м від цілі Нічного Мисливця.\n\n\n\nШкода зменшується за кожного гравця на шляху Нічного Мисливця." },
    { en = "Hurls a bolt of coagulated life force, inflicting $s1 Nature damage instantly and $s3 Nature damage every $t3 sec for $d.", ua = "Жбурляє блискавку згущеної життєвої сили, миттєво завдаючи $s1 шкоди від сил природи, а потім $s3 шкоди від сил природи кожні $t3 с протягом $d." },
    { en = "The Prototype of Renewal summons a torrent of Animastorms, inflicting $366232s1 Nature damage to players caught in the effect every $366232t1 sec and silencing them.", ua = "Прототип Оновлення прикликає потік анімаштормів, що кожні $366232t1 с завдають $366232s1 шкоди від сил природи гравцям, охопленим ефектом, і змушують їх замовкнути." },
    { en = "The Prototype of Absolution creates images of himself that mark random players, then charge to them $d later. Each image inflicts $327810s1 Physical damage and applies Touch of the Night to all players in their path, removing $@spellname366159.\n\n\n\nUpon reaching their target, Night Hunters strike with $@spellname361741.", ua = "Прототип Відпущення створює власні образи, що позначають випадкових гравців, а за $d мчать до них. Кожен образ завдає $327810s1 фізичної шкоди й накладає Доторк Ночі на всіх гравців на своєму шляху, знімаючи $@spellname366159.\n\n\n\nДіставшись цілі, Нічні Мисливці б'ють $@spellname361741." },
    { en = "Increases damage taken from Night Hunter by $s1% for $d.", ua = "Збільшує отримувану від Нічного Мисливця шкоду на $s1% протягом $d." },
    { en = "The Prototype of Absolution pulls all players to his location and conjures an image of himself.\n\n\n\nAfter $s3 sec, the image releases destructive energy that inflicts $s1 Shadow damage to all players, reduced based on distance.", ua = "Прототип Відпущення притягує всіх гравців до свого місця та прикликає власний образ.\n\n\n\nЗа $s3 с образ вивільняє руйнівну енергію, що завдає $s1 шкоди від тіні всім гравцям; шкода зменшується залежно від відстані." },
    { en = "The Prototype of Duty takes to the skies, beating her wings and summoning a barrage of Kyrian armaments towards player locations.", ua = "Прототип Обов'язку здіймається в небо, б'є крилами й прикликає залп кіріанської зброї на місця гравців." },
    { en = "Sinful projections surge forth in multiple directions after $364839d, inflicting $s1 Shadow damage to other players and stunning them for $d.\n\n\n\nSinful Projections apply a stack of $@spellname361608 to players hit by the effect.", ua = "Гріховні проєкції розлітаються в кількох напрямках після $364839d, завдаючи $s1 шкоди від тіні іншим гравцям і приголомшуючи їх на $d.\n\n\n\nГріховні проєкції накладають заряд $@spellname361608 на гравців, яких уразив ефект." },
    { en = "Inflicts $s1 Shadow damage to a random enemy, absorbing $s2 healing received.", ua = "Завдає $s1 шкоди від тіні випадковому ворогові, поглинаючи $s2 отриманого зцілення." },
    { en = "A bulwark protects Necrotic Ritualists and Withering Seeds, reducing damage and healing taken by the target by $s1% until removed.", ua = "Бастіон захищає Некротичних Ритуалістів і В'янучі Зерна, зменшуючи шкоду й зцілення, що отримує ціль, на $s1%, доки його не знято." },
    { en = "The Prototype of Duty strikes her current target inflicting $365269s1 Physical damage, and increasing damage taken from Humbling Strike by $365269s2% for $365269d.\n\n\n\nIn addition, the impact radiates $s4% of the damage inflicted to all other players as Physical damage.", ua = "Прототип Обов'язку б'є свою поточну ціль, завдаючи $365269s1 фізичної шкоди й збільшуючи шкоду від Принизливого Удару на $365269s2% на $365269d.\n\n\n\nКрім того, удар відбиває $s4% завданої шкоди на всіх інших гравців як фізичну шкоду." },
    { en = "The Prototype of Renewal summons a herd of wild beasts to trample players, inflicting $s1 Physical damage to players in the path and knocking them back.", ua = "Прототип Оновлення прикликає стадо диких звірів, щоб затоптати гравців, завдаючи $s1 фізичної шкоди тим, хто на їхньому шляху, і відкидаючи їх назад." },
    { en = "The Prototype of Absolution strikes with immense power, inflicting $s2 Shadow damage to players and Necrotic Ritualists in the direction of his current target and increasing all damage they take by $s3% for $d. This effect stacks.", ua = "Прототип Відпущення б'є з величезною силою, завдаючи $s2 шкоди від тіні гравцям і Некротичним Ритуалістам у напрямку своєї поточної цілі та збільшуючи всю шкоду, що вони отримують, на $s3% на $d. Цей ефект накопичується." },
    { en = "The Prototype of Renewal sows seeds across the battlefield. If their life force is depleted, the seeds burst into a $@spellname361579. If they are instead healed to full health, an $@spellname365306 is released.", ua = "Прототип Оновлення сіє зерна по всьому полю бою. Якщо їхня життєва сила вичерпається, зерна вибухають, спричиняючи $@spellname361579. Якщо ж їх зцілити до повного здоров'я, вивільняється $@spellname365306." },
    { en = "The Primus calls forth several Necrotic Ritualists to usher an expanding ring of $@spellname360618 into this realm, growing until all Necrotic Ritualists are defeated. $@spellname360618 reduces all healing received by $360618s1% and inflicts $360618s2 Shadow damage every $360618t2 sec to all players in the effect.", ua = "Прародитель прикликає кількох Некротичних Ритуалістів, аби ввести в цей світ кільце $@spellname360618, що розширюється, доки не буде здолано всіх Некротичних Ритуалістів. $@spellname360618 зменшує все отримуване зцілення на $360618s1% і завдає $360618s2 шкоди від тіні кожні $360618t2 с усім гравцям у зоні ефекту." },
    { en = "Projections of ascended Kyrians watch over the Prototype of Duty in combat, forming protective wards if called upon to give their life.", ua = "Проєкції піднесених кіріанів охороняють Прототип Обов'язку в бою, утворюючи захисні обереги, якщо їх покличуть віддати своє життя." },
    { en = "Upon giving their life, a protective barrier is formed reducing damage taken by $@spellname360687 by $s5% and and preventing it from jumping to a nearby ally.\n\n\n\nDamage and healing done by players in the effect reduced by $s4%.", ua = "Жертвуючи власним життям, створює захисний бар'єр, що зменшує шкоду від $@spellname360687 на $s5% та не дає їй перескочити на союзника поблизу.\n\n\n\nШкода й зцілення, що завдають гравці в зоні ефекту, зменшені на $s4%." },
    { en = "Upon withering, the seed unleashes a wave of life force inflicting $s1 Nature damage to all players instantly and $s2 Nature damage every $t2 sec for $d. This effect stacks.", ua = "В'янучи, зерно вивільняє хвилю життєвої сили, миттєво завдаючи $s1 шкоди від сил природи всім гравцям і $s2 шкоди від сил природи кожні $t2 с протягом $d. Цей ефект накопичується." },
    { en = "If a member of the Prototype Pantheon is defeated, they initiate a repair for $s1% of their maximum health over $s2 sec.\n\n\n\nThis cast is interrupted when all members of the Pantheon are defeated simultaneously.", ua = "Якщо когось із Прототипного Пантеону здолано, він починає відновлення на $s1% свого максимального здоров'я протягом $s2 с.\n\n\n\nЦе творіння переривається, коли всіх членів Пантеону здолано одночасно." },
    { en = "The Prototype of War carves a sigil into several target's flesh, inflicting $360688s1 Shadow damage every $360687t1 sec for $d. This effect inflicts $360698s1 Shadow damage to all players within $360698a1 yds upon removal and additionally jumps to a nearby ally if the wearer is not protected with $@spellname361067.", ua = "Прототип Війни вирізає знак у плоті кількох цілей, завдаючи $360688s1 шкоди від тіні кожні $360687t1 с протягом $d. При знятті цей ефект завдає $360698s1 шкоди від тіні всім гравцям у радіусі $360698a1 м і додатково перестрибує на ближнього союзника, якщо носія не захищає $@spellname361067." },
    { en = "A Kyrian armament impacts the ground with tremendous force, stunning all players within $a1 yds of the impact and inflicting $s1 Physical damage every $t sec until freed by destroying the armament.", ua = "Кіріанська зброя вдаряє об землю з нищівною силою, приголомшуючи всіх гравців у радіусі $a1 м від удару й завдаючи $s1 фізичної шкоди кожні $t с, доки їх не звільнять, знищивши зброю." },
    { en = "The Prototype of Duty beats her wings with tremendous force for $364941d, repelling all players and inflicting $s1 Nature damage every $t1 sec to all players.", ua = "Прототип Обов'язку б'є крилами з нищівною силою протягом $364941d, відкидаючи всіх гравців і завдаючи $s1 шкоди від сил природи кожні $t1 с усім гравцям." },
    { en = "Upon reaching full health, the Withering Seed blooms, instantly healing all players for $366846s1. Additionally, healing done is increased for all players by $s1% for $365037d. This effect stacks.", ua = "Досягнувши повного здоров'я, В'януче Зерно розквітає, миттєво зцілюючи всіх гравців на $366846s1. Крім того, зцілення, що отримують усі гравці, збільшено на $s1% протягом $365037d. Цей ефект накопичується." },
    { en = "Lihuvim unleashes a blast of protoform energy that creates an Unstable Mote at the location of several players.", ua = "Лігувім вивільняє вибух протоформної енергії, що створює Нестабільну Частку в місці перебування кількох гравців." },
    { en = "A wave of protoform energy motes crash over the area, each inflicting $s1 Cosmic damage to players within 2 yards of the impact point.", ua = "Хвиля часток протоформної енергії накриває місцевість, кожна завдає $s1 космічної шкоди гравцям у радіусі 2 ярдів від точки влучання." },
    { en = "Excess protoform energy bathes the area in radiant light, inficting $s1 Cosmic damage every 2 sec $?DIFF16[and increasing Cosmic damage taken by $s2%.\n\n\n\nStanding in a bay when a Protoform Automa is destroyed removes all stacks of this aura.][.]\n\n\n\nThis effect stacks.", ua = "Надлишок протоформної енергії омиває місцевість сяйним світлом, завдаючи $s1 космічної шкоди кожні 2 с$?DIFF16[ і збільшуючи отримувану космічну шкоду на $s2%.\n\n\n\nЯкщо стояти в ніші, коли знищено Протоформну Автому, знімаються всі заряди цієї аури.][.]\n\n\n\nЦей ефект накопичується." },
    { en = "Lihuvim creates an explosion at target location, unleashing a strike that inflicts $s1 Physical damage to all players within $a1 yards and increasing Cosmic damage taken by $s2% for $d.", ua = "Лігувім створює вибух у вказаному місці, вивільняючи удар, що завдає $s1 фізичної шкоди всім гравцям у радіусі $a1 метрів і збільшує отримувану космічну шкоду на $s2% протягом $d." },
    { en = "Lihuvim unleashes a blast at target location, inflicting $s1 Cosmic damage to all players within $a1 yards and increasing Physical damage taken by $s2% for $d.", ua = "Лігувім вивільняє вибух у вказаному місці, завдаючи $s1 космічної шкоди всім гравцям у межах $a1 ярдів і збільшуючи отриману фізичну шкоду на $s2% протягом $d." },
    { en = "The Defense Matrix Automa generates a shield of energy for $365036d that reduces the damage taken of all of nearby Automa by $s1%.", ua = "Автома Захисної Матриці створює енергетичний щит на $365036d, що зменшує отриману шкоду всіх Автом поблизу на $s1%." },
    { en = "Lihuvim launches alternating blasts of Kinetic Resonance and Sundering Resonance at their current target.", ua = "Лігувім по черзі випускає спалахи Кінетичного Резонансу й Розколювального Резонансу по своїй поточній цілі." },
    { en = "Lihuvim causes protoform energy to collapse around several players, inflicting $s1 Cosmic damage every $t1 sec for $d.", ua = "Лігувім змушує енергію протоформи стискатися навколо кількох гравців, завдаючи $s1 космічної шкоди кожні $t1 с протягом $d." },
    { en = "Lihuvim dematerializes the player, inflicting $s1 Cosmic damage and increasing their Physical damage taken by $S2% for $d.\n\n\n\nDeconstructs nearby Unstable Motes within $a1 yards.", ua = "Лігувім дематеріалізує гравця, завдаючи $s1 космічної шкоди й збільшуючи отримувану ним фізичну шкоду на $S2% протягом $d.\n\n\n\nРозбирає Нестабільні Частки поблизу в радіусі $a1 метрів." },
    { en = "Lihuvim assigns new resonancies to players, applying either Melodic Alignment or Harmonic Alignment.", ua = "Лігувім надає гравцям нові резонанси, накладаючи Мелодійне Узгодження або Гармонійне Узгодження." },
    { en = "The Degeneration Automa inscribes the target with protoform energy, inflicting $364092s1 Cosmic damage every $t1 sec for $d.", ua = "Автома Деґенерації вкарбовує в ціль протоформну енергію, завдаючи $364092s1 космічної шкоди кожні $t1 с протягом $d." },
    { en = "The Acquisitions Automa catastrophically explodes upon death, inflicting $s2 Cosmic damage to all players within $a1 yards and launching them away.", ua = "Автома Заготівлі катастрофічно вибухає після загибелі, завдаючи $s2 космічної шкоди всім гравцям у радіусі $a1 ярдів і відкидаючи їх геть." },
    { en = "30 sec after dying, the Acquisitions Automa reverses its recent detonation, resurrecting and returning to full health.", ua = "Через 30 с після загибелі Автома Здобуття обертає назад свою недавню детонацію, воскресаючи й відновлюючи повне здоров'я." },
    { en = "Upon death, the Degeneration Automa echoes a cast of Unstable Mote, forming a mote at a nearby players location after $d.", ua = "Гинучи, Автома Дегенерації повторює творення Нестабільної Частки, утворюючи частку поряд із гравцем за $d." },
    { en = "Upon death, the Defense Matrix Automa creates one final Ephemeral Barrier that lasts for $d and affects nearby automa and players.", ua = "При смерті Автома Захисної Матриці створює один останній Ефемерний Бар'єр, що триває $d й діє на автом і гравців поблизу." },
    { en = "$?DIFF16[The Guardian Automa creates a Sentry that persists indefinitely.][The Guardian Automa creates a Sentry that persists for $d.]", ua = "$?DIFF16[Автома-Страж створює Вартового, що існує безмежно.][Автома-Страж створює Вартового, що існує протягом $d.]" },
    { en = "The Acquisitions Automa is imperfect and unstable, pulsing $362584s1 Cosmic damage to all players every $t1 sec.\n\n\n\nCosmic damage inflicted increased by $S2%%.\n\n\n\nCasts Detonation upon death.", ua = "Автома Здобуття недосконала й нестабільна, пульсуючи $362584s1 космічної шкоди всім гравцям кожні $t1 с.\n\n\n\nЗавдавана космічна шкода збільшена на $S2%%.\n\n\n\nПри смерті творить Детонацію." },
    { en = "Lihuvim expels players, inflicting $s1 Cosmic damage and pushing them away.", ua = "Лігувім виштовхує гравців, завдаючи $s1 космічної шкоди й відкидаючи їх геть." },
    { en = "Standing inside an active bay reduces Cosmic damage taken by $S1%.", ua = "Якщо стояти в активній ніші, отримувана космічна шкода зменшується на $S1%." },
    { en = "Standing too near to an Unstable Mote destabilizes it causing it to rapidly expand in area of effect.\n\n\n\nThis area inflicts $s1 Cosmic damage every $t1 sec to players who remain in the area.", ua = "Якщо стояти надто близько до Нестабільної Частки, вона дестабілізується, через що її зона дії стрімко розширюється.\n\n\n\nЦя зона завдає $s1 космічної шкоди кожні $t1 с гравцям, які лишаються в ній." },
    { en = "Lihuvim causes the player to resonate harmoniously.", ua = "Лігувім змушує гравця гармонійно резонувати." },
    { en = "Lihuvim causes the player to resonate melodically.", ua = "Лігувім змушує гравця мелодійно резонувати." },
    { en = "Failing to contain both Melodic and Harmonic Alignments causes the cascade to instead inflict $s1 Cosmic damage to players within $368742a1 yards of the target.", ua = "Якщо не вдається стримати і Мелодійне, і Гармонійне Узгодження, каскад натомість завдає $s1 космічної шкоди гравцям у радіусі $368742a1 метрів від цілі." },
    { en = "Lihuvim creates a cosmic resonance at a players location, inflicting $s1 Cosmic damage to all players within $368742a1 yards of the target.\n\n\n\nIf this spell fails to hit both Melodic and Harmonic Alignments, a Dissonance Cascade is created instead.", ua = "Лігувім створює космічний резонанс у місці перебування гравця, завдаючи $s1 космічної шкоди всім гравцям у межах $368742a1 ярдів від цілі.\n\n\n\nЯкщо це закляття не влучає водночас у Мелодійне та Гармонійне Вирівнювання, замість цього утворюється Каскад Дисонансу." },
    { en = "Upon reaching 100 energy, Lihuvim begins forming Protoform Automa in nearby bays, releasing excess Protoform Radiance into the area.\n\n\n\nDefeating a Protoform Automa during this time prevents it from fully forming.\n\n\n\n$?DIFF!16[Standing inside a bay during this time applies Protoform Disalignment.][]", ua = "Досягнувши 100 енергії, Лігувім починає формувати протоформних автома в сусідніх відсіках, вивільняючи надлишок Протоформного Сяйва в зону.\n\n\n\nЯкщо в цей час подолати протоформного автома, він не сформується повністю.\n\n\n\n$?DIFF!16[Перебування в відсіку в цей час накладає Протоформне Розвирівнювання.][]" },
    { en = "The Sentry periodically unleashes a barrage of energy at random targets that inflicts $s1 Cosmic damage.", ua = "Вартовий періодично обрушує шквал енергії на випадкові цілі, завдаючи $s1 космічної шкоди." },
    { en = "Halondrus inflicts $s1 Cosmic damage to its current target and any players caught in the beam.\n\n\n\nInflicts an additional $361312s1 Cosmic damage every $361309t2 sec and increases damage taken from $@spellname359720 by $361309s1% for $361309d. This effect stacks.$?diff15|diff16[\n\n\n\nShatters $@spellname363414.][]", ua = "Галондрус завдає $s1 космічної шкоди своїй поточній цілі та всім гравцям, що потрапили під промінь.\n\n\n\nЗавдає додатково $361312s1 космічної шкоди кожні $361309t2 с і збільшує шкоду, отриману від $@spellname359720, на $361309s1% на $361309d. Цей ефект складається.$?diff15|diff16[\n\n\n\nРозбиває $@spellname363414.][]" },
    { en = "Halondrus' steps cause the earth to tremble, inflicting $362130s1 Physical damage to all players with each step.", ua = "Кроки Галондруса змушують землю здригатися, завдаючи $362130s1 фізичної шкоди всім гравцям з кожним кроком." },
    { en = "Halondrus' engine locks in overdrive, inflicting $368530s1 Cosmic damage to all players every $t1 sec and pulling ephemera towards its location. These effects grow in intensity every $s2 sec.", ua = "Двигун Галондруса замикається на форсажі, завдаючи $368530s1 космічної шкоди всім гравцям кожні $t1 с і притягуючи ефемери до свого розташування. Ці ефекти посилюються кожні $s2 с." },
    { en = "The mote erupts if touched, inflicting $s1 Cosmic damage to the player.", ua = "Частка вибухає, якщо до неї торкнутися, завдаючи $s1 космічної шкоди гравцю." },
    { en = "Halondrus protects motes from players' touch with a shield of light.", ua = "Галондрус захищає частки від дотику гравців щитом світла." },
    { en = "Inflicts $s1 Cosmic damage every $t1 sec to players within the cloud of ephemera.", ua = "Завдає $s1 космічної шкоди кожні $t1 с гравцям усередині хмари ефемер." },
    { en = "Halondrus activates a shield that absorbs $s2% of its maximum health.\n\n\n\nWhile the shield holds, Halondrus inflicts $362052s1 Cosmic damage every $t1 sec and pulls players and ephemera toward its location. This effect grows in intensity over time.", ua = "Галондрус активує щит, що поглинає $s2% його максимального здоров'я.\n\n\n\nПоки щит тримається, Галондрус завдає $362052s1 космічної шкоди кожні $t1 с і притягує гравців та ефемери до свого розташування. Цей ефект з часом посилюється." },
    { en = "Each mote collapses, inflicting $s1 Cosmic damage to players within $a1 yards.", ua = "Кожна частка згортається, завдаючи $s1 космічної шкоди гравцям у межах $a1 ярдів." },
    { en = "Halondrus activates a $@spellname369210 that inflicts $369207s1 Cosmic damage every $369207t1 sec to players in its area of effect.", ua = "Галондрус активує $@spellname369210, що завдає $369207s1 космічної шкоди кожні $369207t1 с гравцям у зоні дії." },
    { en = "Shards of the prism linger, inflicting $368363s1 Cosmic damage every $368363t1 sec and reducing the movement speed of players and Ephemeral Motes.", ua = "Уламки призми лишаються, завдаючи $368363s1 космічної шкоди кожні $368363t1 с і зменшуючи швидкість руху гравців та Ефемерних Часток." },
    { en = "Halondrus creates volatile charges that trigger a $@spellname368958 after $368953s2 sec. Picking up or dropping the charge resets the timer and inflicts $368960s1 Cosmic damage to the player.\n\n\n\nThe charge inflicts $368959s1 Cosmic damage every $368969t1 sec while held and afflicts the player with $@spellname368961 when dropped.", ua = "Галондрус створює нестабільні заряди, що спричиняють $@spellname368958 через $368953s2 с. Підняття чи скидання заряду скидає таймер і завдає $368960s1 космічної шкоди гравцю.\n\n\n\nЗаряд завдає $368959s1 космічної шкоди кожні $368969t1 с, поки його тримають, і вражає гравця ефектом $@spellname368961 при скиданні." },
    { en = "The $@spellname368959 erupts, inflicting $s1 Cosmic damage to all players.", ua = "$@spellname368959 вибухає, завдаючи $s1 космічної шкоди всім гравцям." },
    { en = "Recent exposure to a charge increases damage taken by $@spellname368959 by $s1% for $d.", ua = "Нещодавній контакт із зарядом збільшує шкоду, отриману від $@spellname368959, на $s1% на $d." },
    { en = "Halondrus embeds itself atop an $@spellname361002, inflicting $362610s1 Physical damage to all players each time it stakes a leg into the sand.\n\n\n\nActivates $@spellname368965.", ua = "Галондрус заглиблюється у $@spellname361002, завдаючи $362610s1 фізичної шкоди всім гравцям щоразу, коли вганяє ногу в пісок.\n\n\n\nАктивує $@spellname368965." },
    { en = "Halondrus regains its mobility, inflicting $368950s1 Physical damage to all players each time it pulls a leg from the sand.", ua = "Галондрус відновлює рухливість, завдаючи $368950s1 фізичної шкоди всім гравцям щоразу, коли витягує ногу з піску." },
    { en = "Halondrus' engine pulses with energy, inflicting $368146s1 Cosmic damage to all players every $t1 sec.", ua = "Двигун Галондруса пульсує енергією, завдаючи $368146s1 космічної шкоди всім гравцям кожні $t1 с." },
    { en = "Halondrus shatters a gleaming sphere that knocks all players away from its location.\n\n\n\nInflicts $s1 Cosmic damage to players within $a1 yds of the sphere and $s2 Cosmic damage to all other players.", ua = "Галондрус розбиває мерехтливу сферу, що відкидає всіх гравців геть від її розташування.\n\n\n\nЗавдає $s1 космічної шкоди гравцям у межах $a1 ярдів від сфери та $s2 космічної шкоди всім іншим гравцям." },
    { en = "Halondrus unleashes a barrage of missiles that inflict $361677s1 Cosmic damage to players nearby the impact locations and create $@spellname362025s.", ua = "Галондрус обрушує шквал снарядів, що завдають $361677s1 космічної шкоди гравцям поблизу місць влучання та створюють $@spellname362025s." },
    { en = "The closing of the gate crushes anyone caught in its path.", ua = "Зачинення брами розчавлює всіх, хто опинився на її шляху." },
    { en = "Halondrus creates tremors that inflict $367082s1 Physical damage to players within $367082A1 yards.\n\n\n\nAn $@spellname360113 is opened at each tremor's terminus.", ua = "Галондрус породжує поштовхи, що завдають $367082s1 фізичної шкоди гравцям у межах $367082A1 ярдів.\n\n\n\nНа кінці кожного поштовху відкривається $@spellname360113." },
    { en = "Halondrus' primary attack inflicts Physical damage to its current target.", ua = "Основна атака Галондруса завдає фізичної шкоди його поточній цілі." },
    { en = "Halondrus encases several players in prisms of light that inflict $365297s2 Cosmic damage every $365297t2 sec and reduce movement speed by $365297s3%. These effects grow in intensity for $365297d.$?diff15|diff16[\n\n\n\nUpon removal a $@spellname361916 remains.][]", ua = "Галондрус ув'язнює кількох гравців у призмах світла, що завдають $365297s2 космічної шкоди кожні $365297t2 с і зменшують швидкість руху на $365297s3%. Ці ефекти посилюються протягом $365297d.$?diff15|diff16[\n\n\n\nПісля зняття лишається $@spellname361916.][]" },
    { en = "The Defense Core shatters, flinging debris that inflicts $368247s1 Physical damage to players within $368247a1 yards of the impact location.", ua = "Захисне Ядро розколюється, розкидаючи уламки, що завдають $368247s1 фізичної шкоди гравцям у межах $368247a1 ярдів від місця влучання." },
    { en = "The impact area reverberates shortly afterwards, inflicting $s1 Physical damage to nearby players.", ua = "Зона влучання невдовзі відлунює, завдаючи $s1 фізичної шкоди гравцям поблизу." },
    { en = "Halondrus reclaims an orb of ephemera and erupts with destructive energy, inflicting $s1 Cosmic damage to all players and an additional $s2 Cosmic damage every $t2 sec for $d. This effect stacks.", ua = "Галондрус повертає собі кулю ефемер і вибухає руйнівною енергією, завдаючи $s1 космічної шкоди всім гравцям і додатково $s2 космічної шкоди кожні $t2 с на $d. Цей ефект складається." },
    { en = "Anduin gradually restores his willpower while in combat. Anduin consumes his Willpower to empower players with $@spellname368913 before manifesting the source of his domination.", ua = "Андуїн поступово відновлює свою силу волі в бою. Андуїн витрачає Силу Волі, щоб наділити гравців ефектом $@spellname368913, перш ніж проявити джерело свого панування." },
    { en = "Anduin afflicts players with a word of darkness that inflicts $s1 Shadow damage every $t1 sec for $d.", ua = "Андуїн вражає гравців словом темряви, що завдає $s1 шкоди від тіні кожні $t1 с на $d." },
    { en = "Immune to the effects of Lost Soul.\n\n\n\nDamage taken by $@spellname362405 increased by $s1%.", ua = "Несприйнятливий до ефектів Заблуканої Душі.\n\n\n\nШкода, отримана від $@spellname362405, збільшена на $s1%." },
    { en = "Anduin intensifies the light and darkness within several players marking them with $@spellname361992 or $@spellname361993 for $361992d. Coming into contact with the opposing mark neutralizes the effect on both players.\n\n\n\nAfter $361993d marked players explode, inflicting $?diff15|diff16 [$361999s1 Twilight damage to all players within $361999A1 yds.][]$?diff14|diff17 [$366933s1 Twilight damage.][] Coming into contact with the same mark also causes this explosion.", ua = "Андуїн посилює світло й темряву всередині кількох гравців, позначаючи їх ефектом $@spellname361992 або $@spellname361993 на $361992d. Контакт із протилежною позначкою нейтралізує ефект на обох гравцях.\n\n\n\nЧерез $361993d позначені гравці вибухають, завдаючи $?diff15|diff16 [$361999s1 присмеркової шкоди всім гравцям у межах $361999A1 ярдів.][]$?diff14|diff17 [$366933s1 присмеркової шкоди.][] Контакт з однаковою позначкою також спричиняє цей вибух." },
    { en = "Anduin intensifies the darkness within players afflicting them with $@spellname365966. \n\n\n\nAfflicted players suffer $368660s1 Shadow damage every $365966t2 sec and after $365966d marked players explode, inflicting $?diff15|diff16 [$361999s1 Twilight damage to all players within $361999A1 yds.][]$?diff14|diff17 [$366933s1 Twilight damage.][] Coming into contact with the same mark also causes this explosion.", ua = "Андуїн посилює темряву всередині гравців, вражаючи їх ефектом $@spellname365966.\n\n\n\nУражені гравці зазнають $368660s1 шкоди від тіні кожні $365966t2 с, і через $365966d позначені гравці вибухають, завдаючи $?diff15|diff16 [$361999s1 присмеркової шкоди всім гравцям у межах $361999A1 ярдів.][]$?diff14|diff17 [$366933s1 присмеркової шкоди.][] Контакт з однаковою позначкою також спричиняє цей вибух." },
    { en = "Leaps towards a target, inflicting $s1 Physical damage to all players within $A1 yards and reducing the effectiveness of healing and absorption effects received by $s2%.", ua = "Стрибає до цілі, завдаючи $s1 фізичної шкоди всім гравцям у межах $A1 ярдів і зменшуючи ефективність отриманих ефектів зцілення та поглинання на $s2%." },
    { en = "Anduin sends forth waves of dark energy that travel out and ricochet off of the edges of the arena. Players hit suffer $367634s1 Twilight damage every $367634t1 sec and are unable to attack or cast spells for $367634d.\n\n\n\nAnduin's minions hit by a Wicked Star heal $365112s1% of their maximum health every $365112t1 sec and are immune to crowd control and interrupt effects for $365112d.", ua = "Андуїн надсилає хвилі темної енергії, що розходяться назовні й відбиваються від країв арени. Уражені гравці зазнають $367634s1 присмеркової шкоди кожні $367634t1 с і не можуть атакувати чи творити закляття протягом $367634d.\n\n\n\nПосіпаки Андуїна, уражені Лиховісною Зорею, відновлюють $365112s1% свого максимального здоров'я кожні $365112t1 с і несприйнятливі до ефектів контролю та переривання протягом $365112d." },
    { en = "The soul begins to detonate upon reaching low health, inflicting $s1 Shadow damage every $t1 sec to all players and reducing the effectiveness of healing and absorption effects received by $s2% for $d.", ua = "Душа починає вибухати, досягнувши низького здоров'я, завдаючи $s1 шкоди від тіні кожні $t1 с всім гравцям і зменшуючи ефективність отриманих ефектів зцілення та поглинання на $s2% на $d." },
    { en = "Anduin grants players up to $s5% increased damage done and $s6% reduced damage taken, based on the amount of Willpower consumed.", ua = "Андуїн надає гравцям до $s5% збільшеної завданої шкоди та $s6% зменшеної отриманої шкоди, залежно від кількості витраченої Сили Волі." },
    { en = "The Fallen King strikes at the target's soul. This grants the Fallen King $362775s1% attack speed for $362775d and inflicts $362772s1 Physical and $362773s1 Shadowfrost damage to the target.\n\n\n\nThis effect increases the target's Physical damage taken by $362774s1% for $362774d.", ua = "Полеглий Король б'є по душі цілі. Це дає Полеглому Королю $362775s1% швидкості атаки на $362775d та завдає цілі $362772s1 фізичної і $362773s1 шкоди від тінькриги.\n\n\n\nЦей ефект збільшує фізичну шкоду, яку отримує ціль, на $362774s1% на $362774d." },
    { en = "The soul's rage causes it to unravel, the soul loses $s1% of its maximum health every $363027t1 sec and gains $s2% increased Physical damage done.", ua = "Лють душі змушує її розпадатися: душа втрачає $s1% свого максимального здоров'я кожні $363027t1 сек і завдає на $s2% більше фізичної шкоди." },
    { en = "Darkness rains down around Anduin's Despair, inflicting $362394s1 Shadow damage to players in the impact area and reducing damage and healing done by $362394s2% for $362394d.", ua = "Навколо Відчаю Андуїна спадає темрява, завдаючи $362394s1 шкоди від тіні гравцям у зоні удару та зменшуючи завдану шкоду й зцілення на $362394s2% на $362394d." },
    { en = "Upon death, the soul blasts a target area inflicting $s1 Shadow damage to players standing within $A1 yards of  the impact area.", ua = "Гинучи, душа здіймає вибух у цільовій зоні, завдаючи $s1 шкоди від тіні гравцям у межах $A1 м від місця удару." },
    { en = "When a Severed Soul is defeated, the player that it belongs to is returned to their body.\n\n\n\nIf a player's Severed Soul persists when Lost Soul expires, they are instantly slain.", ua = "Коли Відсічену Душу знищено, гравець, якому вона належить, повертається у своє тіло.\n\n\n\nЯкщо Відсічена Душа гравця лишається після завершення дії Загубленої Душі, гравця миттєво вбито." },
    { en = "The Severed Soul attempts to permanently banish the player it is connected to, instantly slaying them.", ua = "Відсічена Душа намагається назавжди вигнати гравця, з яким вона пов'язана, миттєво вбиваючи його." },
    { en = "The Remnant's domination over Anduin's soul links them, transferring $s2% of damage taken to Anduin.", ua = "Панування Останка над душею Андуїна пов'язує їх, передаючи $s2% отриманої шкоди Андуїну." },
    { en = "Anduin rends the souls of players, inflicting $362407s1 Shadow damage to players in front of him and banishing their souls for $362055d.", ua = "Андуїн шматує душі гравців, завдаючи $362407s1 шкоди від тіні гравцям перед собою та виганяючи їхні душі на $362055d." },
    { en = "The beacon erupts when purging the effects of $@spellname365962, inflicting $s1 Holy damage every $t1 sec to all players for $d. This effect stacks.", ua = "Маяк вивергається, коли очищає ефекти $@spellname365962, завдаючи $s1 свячної шкоди кожні $t1 сек усім гравцям протягом $d. Цей ефект накопичується." },
    { en = "The presence of the Fallen King invokes a raging storm that inflicts $362545s1 Shadowfrost damage every $t1 sec to all players.\n\n\n\nThis effect stacks, increasing in stack count every $362542t1 sec.", ua = "Присутність Полеглого Короля прикликає лютий шторм, що завдає $362545s1 шкоди від тінькриги кожні $t1 сек усім гравцям.\n\n\n\nЦей ефект накопичується, нарощуючи кількість зарядів кожні $362542t1 сек." },
    { en = "When defeated, Grim Reflections empower all remaining Reflections increasing their Haste by $s1%.", ua = "Коли Похмурі Відображення зазнають поразки, вони підсилюють усі вцілілі Відображення, збільшуючи їхній Поспіх на $s1%." },
    { en = "Anduin manifests dark images of himself throughout the arena that cast $@spellname365008.", ua = "Андуїн проявляє по всій арені темні образи самого себе, що творять $@spellname365008." },
    { en = "While players' souls are banished they are able to aid the soul of Anduin. \n\n\n\nDefeating Anduin's doubt and restoring his hope grants him willpower.\n\n\n\nPlayers are afflicted with $@spellname365445 when this effect is removed.", ua = "Поки душі гравців вигнані, вони можуть допомагати душі Андуїна.\n\n\n\nПодолання сумнівів Андуїна та відновлення його надії дає йому силу волі.\n\n\n\nКоли цей ефект знято, на гравців накладається $@spellname365445." },
    { en = "In a moment of clarity, Anduin summons a $@spellname362702. Players that enter the area have applications of $@spellname365966 removed, reducing the size of the barrier and applying $@spellname368428 to all players for $368428d.", ua = "У мить просвітлення Андуїн прикликає $@spellname362702. У гравців, які входять у цю зону, знімаються накладення $@spellname365966, що зменшує розмір бар'єра й накладає $@spellname368428 на всіх гравців на $368428d." },
    { en = "The reflection lets out a psychic scream, $?diff15|diff16 [causing all players to flee for $369011d and][] inflicts $s1 Shadow damage every $t1 sec for $d.", ua = "Відбиття видає психічний зойк, $?diff15|diff16 [що змушує всіх гравців тікати протягом $369011d і][]завдає $s1 шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "With each consecutive melee attack against the same target, Anduin's attack speed increases by $364248s1%. This effect stacks.", ua = "З кожною наступною атакою ближнього бою по тій самій цілі швидкість атаки Андуїна зростає на $364248s1%. Цей ефект накопичується." },
    { en = "Anduin plunges Kingsmourne into the ground unleashing a wave of maw energy, inflicting $361816s1 Shadow damage to all players and an additional $361818s1 Shadow damage every $361817t1 sec until Anduin reaches $s1  willpower. This effect stacks.", ua = "Андуїн занурює Жалоруйнь у землю, вивільняючи хвилю енергії Пащі, що завдає $361816s1 шкоди від тіні всім гравцям і додатково $361818s1 шкоди від тіні кожні $361817t1 сек, доки Андуїн не сягне $s1 сили волі. Цей ефект накопичується." },
    { en = "The Remnant's presence empowers Grim Reflections. Grants $s1% increased maximum health and immunity to interrupt and crowd control effects.", ua = "Присутність Останка підсилює Похмурі Відбиття. Дає на $s1% більше максимального здоров'я та несприйнятливість до переривань і ефектів контролю." },
    { en = "Anduin sends forth waves of dark energy that travel out and return to their origin. Players hit suffer $365024s1 Twilight damage every $365024t1 sec and are unable to attack or cast spells for $365024d.\n\n$?diff15|diff16\n\n[\n\nAnduin's minions hit by a Wicked Star heal $365112s1% of their maximum health every $365112t1 sec and are immune to crowd control and interrupt effects for $365112d.][]", ua = "Андуїн посилає хвилі темної енергії, що розходяться назовні й повертаються до свого джерела. Уражені гравці зазнають $365024s1 присмеркової шкоди кожні $365024t1 сек і не можуть атакувати чи творити закляття протягом $365024d.\n\n$?diff15|diff16\n\n[\n\nПосіпаки Андуїна, уражені Лиховісною Зорею, зцілюють $365112s1% свого максимального здоров'я кожні $365112t1 сек і несприйнятливі до ефектів контролю та переривань протягом $365112d.][]" },
    { en = "Anduin summons a $@spellname365293 that inflicts $365853s1 Twilight damage to all players and creates a barrier that persists for $365173d. $s3% of healing received by players within the area is redirected to the barrier. Up to $s1 healing received reduces the size of the barrier.\n\n\n\nUpon expiration, the barrier explodes and inflicts $365300s1 Twilight damage, tainting all players. This effect absorbs up to $s2 healing received based on the size of the Befouled Barrier.", ua = "Андуїн прикликає $@spellname365293, що завдає $365853s1 присмеркової шкоди всім гравцям і створює бар'єр, який триває $365173d. $s3% зцілення, отриманого гравцями в цій зоні, перенаправляється на бар'єр. Отримане зцілення обсягом до $s1 зменшує розмір бар'єра.\n\n\n\nКоли дія завершується, бар'єр вибухає й завдає $365300s1 присмеркової шкоди, опоганюючи всіх гравців. Цей ефект поглинає до $s2 отриманого зцілення залежно від розміру Опоганеного Бар'єра." },
    { en = "Fiendish souls flood the arena, attacking enemies of the Fallen King.", ua = "Лиховісні душі затоплюють арену, нападаючи на ворогів Полеглого Короля." },
    { en = "Anduin plunges Kingsmourne into the ground unleashing multiple waves of maw energy. Each pulse inflicts $361816s1 Shadow damage to all players and applies $@spellname361817 inflicting an additional $361818s1 Shadow damage every $361817t1 sec. This effect stacks.", ua = "Андуїн занурює Жалоруйнь у землю, вивільняючи численні хвилі енергії Пащі. Кожен імпульс завдає $361816s1 шкоди від тіні всім гравцям і накладає $@spellname361817, що завдає додатково $361818s1 шкоди від тіні кожні $361817t1 сек. Цей ефект накопичується." },
    { en = "Armies of the Damned march across the arena. Players that come into contact with them are stunned and suffer $s1 Shadowfrost damage instantly with an additional $s2 Shadowfrost damage every $t2 sec for $d.", ua = "Армії Проклятих марширують через арену. Гравці, що стикаються з ними, оглушуються та миттєво зазнають $s1 шкоди від тінькриги, а також додатково $s2 шкоди від тінькриги кожні $t2 сек протягом $d." },
    { en = "$@spellname365816 removes an application of $@spellname365966 from a player standing in the impact area. If no players are standing in the impact area the fragment bursts, inflicting $365990s1 Holy damage to all players.", ua = "$@spellname365816 знімає одне накладення $@spellname365966 з гравця, що стоїть у зоні удару. Якщо в зоні удару немає гравців, уламок розривається, завдаючи $365990s1 свячної шкоди всім гравцям." },
    { en = "Aiding Anduin restores his Willpower. Anduin consumes his Willpower to empower players with $@spellname368913 before manifesting the source of his domination.", ua = "Допомога Андуїну відновлює його силу волі. Андуїн витрачає свою силу волі, щоб підсилити гравців за допомогою $@spellname368913, перш ніж проявити джерело свого панування." },
    { en = "Anduin's Hope is afflicted with gloom, reducing movement speed by $s2% and reducing the effects of healing received by $s1%.", ua = "Надію Андуїна вражено мороком, що зменшує швидкість пересування на $s2% і дієвість отриманого зцілення на $s1%." },
    { en = "Mal'Ganis creates an Inchoate Shadow that begins to assault players with $@spellname361923.", ua = "Мал'Ганіс створює Незрілу Тінь, яка починає нападати на гравців за допомогою $@spellname361923." },
    { en = "Mal'Ganis lashes out with his claws, inflicting $362714s1 Physical damage to players in front of him and applying $@spellname359963 to players struck.\n\n\n\nStriking a player already afflicted with $@spellname359963 heals Mal'Ganis for $359964s1% of his maximum health.", ua = "Мал'Ганіс розмахується кігтями, завдаючи $362714s1 фізичної шкоди гравцям перед собою та накладаючи $@spellname359963 на уражених гравців.\n\n\n\nУдар по гравцю, уже враженому $@spellname359963, зцілює Мал'Ганісу $359964s1% його максимального здоров'я." },
    { en = "Claws rip open the target's veins, reducing healing received by $s1% for $d.", ua = "Кігті розривають вени цілі, зменшуючи отримуване зцілення на $s1% протягом $d." },
    { en = "The Inchoate Shadow's incorporeal nature prevents it from being killed. The shadow removes this effect at full health and transforms into a Corporeal Shadow.", ua = "Безтілесна природа Незрілої Тіні не дає її вбити. Тінь знімає цей ефект при повному здоров'ї й перетворюється на Тілесну Тінь." },
    { en = "Kin'tessa creates wandering clouds of mind fog for $360239d. Coming into contact with a cloud afflicts players with $@spellname360241.", ua = "Кін'тесса створює блукаючі хмари мозкового туману на $360239d. Дотик до хмари вражає гравців ефектом $@spellname360241." },
    { en = "Kin'tessa increases her Shadow damage done by $s1% and the size of $@spellname360229 each time she casts $@spellname360417. This effect stcaks.", ua = "Кін'тесса збільшує завдану нею шкоду від тіні на $s1% та розмір $@spellname360229 щоразу, коли творить $@spellname360417. Цей ефект накопичується." },
    { en = "Mal'Ganis increases his Plague damage done by $s1% and the virulence of $@spellname360006 each time he casts $@spellname360319. This effect stacks.", ua = "Мал'Ганіс збільшує завдану ним шкоду від чуми на $s1% та вірулентність $@spellname360006 щоразу, коли творить $@spellname360319. Цей ефект накопичується." },
    { en = "For $d after casting $@spellname360319, Mal'Ganis releases additional insects when casting $@spellname360006. In addition, $@spellname360006 increases in intensity much faster.", ua = "Протягом $d після творення $@spellname360319 Мал'Ганіс випускає додаткових комах, творячи $@spellname360006. Крім того, $@spellname360006 нарощує інтенсивність значно швидше." },
    { en = "Disturbing thoughts cloud the mind, slipping players into a deep sleep for $d.", ua = "Тривожні думки затьмарюють розум, занурюючи гравців у глибокий сон на $d." },
    { en = "Upon death, the dreadlord erupts into a $@spellname360374 and inflicts $360377s1 Shadow damage to all players every $360376t1 sec and increases in intensity every $t1 sec.", ua = "Гинучи, лорд жаху вибухає у $@spellname360374 й завдає $360377s1 шкоди від тіні всім гравцям кожні $360376t1 сек, нарощуючи інтенсивність кожні $t1 сек." },
    { en = "For $d after casting $@spellname360417, Kin'tessa isolates players who are not within $s1 yards of an another player, horrifying them until rescued.", ua = "Протягом $d після творення $@spellname360417 Кін'тесса ізолює гравців, що не перебувають у межах $s1 м від іншого гравця, жахаючи їх, доки їх не врятують." },
    { en = "Mal'Ganis creates an Inchoate Shadow with 1 health that begins to assault players with $@spellname361923.", ua = "Мал'Ганіс створює неповну тінь з 1 одиницею здоров'я, яка починає атакувати гравців за допомогою $@spellname361923." },
    { en = "Stinging bites increase the damage taken from $@spellname360006 by $s1% for $d. This effect stacks.", ua = "Жалкі укуси збільшують шкоду, отриману від $@spellname360006, на $s1% на $d. Цей ефект накопичується." },
    { en = "The Inchoate Shadow consumes the health of the living, inflicting $s1 Shadow damage to all players and healing itself for $361943s1% of its maximum health.", ua = "Неповна тінь поглинає здоров'я живих, завдаючи $s1 шкоди від тіні всім гравцям і зцілюючи себе на $361943s1% свого максимального здоров'я." },
    { en = "Mal'Ganis causes a cloud of insects to surround the target, inflicting $360015s1 Plague damage every $360012s3 sec and growing in intensity over time.\n\n\n\nIf the target comes within $360012s1 yards of another player, the insects will jump to that player and reset the intensity.\n\n\n\nUpon removal, the target is afflicted by $@spellname364985.", ua = "Мал'Ганіс оточує ціль хмарою комах, завдаючи $360015s1 шкоди від чуми кожні $360012s3 сек. і поступово посилюючись із часом.\n\n\n\nЯкщо ціль наблизиться до іншого гравця на $360012s1 м, комахи перестрибнуть на нього й скинуть інтенсивність.\n\n\n\nПісля зняття ціль уражається ефектом $@spellname364985." },
    { en = "The Inchoate Shadow's incorporeal nature prevents it from being killed and reduces damage taken by $s1%. The shadow removes this effect at full health and transforms into a Corporeal Shadow.", ua = "Безтілесна природа неповної тіні не дає її вбити й зменшує отриману шкоду на $s1%. Тінь знімає цей ефект, відновивши повне здоров'я, і перетворюється на втілену тінь." },
    { en = "Kin'tessa warps the shadows around a player for $360146d. Upon expiration, the shadows erupt into $@spellname360148.", ua = "Кін'тесса викривлює тіні навколо гравця на $360146d. Після завершення тіні вибухають ефектом $@spellname360148." },
    { en = "Shadows burst around the target, causing players within $s1 yards to flee in fear for $d.\n\n\n\nStriking an player afflicted with $@spellname360012 instead removes the effect and causes the insects to flee away from that player's location.", ua = "Навколо цілі вибухають тіні, змушуючи гравців у межах $s1 ярдів тікати від страху протягом $d.\n\n\n\nУдар по гравцю, ураженому $@spellname360012, натомість знімає ефект і змушує комах розлітатися геть від місця цього гравця." },
    { en = "Shadows are only vulnerable to crowd controlling effects for $d after being created.", ua = "Тіні вразливі до ефектів контролю лише протягом $d після створення." },
    { en = "The shadow increases its damage done by $s1%.", ua = "Тінь збільшує завдану нею шкоду на $s1%." },
    { en = "Kin'tessa strikes at the mind of targets in front of her, inflicting $362711s1 Physical damage and an additional $360288s1 Shadow damage every $360287t1 sec for $360287d. This effect stacks.", ua = "Кін'тесса вражає розум цілей перед собою, завдаючи $362711s1 фізичної шкоди та додатково $360288s1 шкоди від тіні кожні $360287t1 сек. протягом $360287d. Цей ефект накопичується." },
    { en = "Upon reaching 100 energy, Kin'tessa causes both dreadlords to infiltrate the essences of players with $@spellname360418. If their disguises are not found and defeated within $360418d, they erupt forth with $@spellname360420.", ua = "Досягнувши 100 енергії, Кін'тесса змушує обох лордів жаху проникнути в сутності гравців за допомогою $@spellname360418. Якщо їхні личини не виявити й не подолати протягом $360418d, вони вириваються назовні ефектом $@spellname360420." },
    { en = "Whilst the dreadlords are infiltrating mortal essences, players are unable to trust each other and are hostile to allies. Standing near another player will reveal a hint about their essence.\n\n\n\nInflicts $360419s1 Shadow damage every $t2 sec until the dreadlords' disguises are defeated.", ua = "Поки лорди жаху проникають у сутності смертних, гравці не можуть довіряти одне одному й вороже налаштовані до союзників. Перебування поряд з іншим гравцем розкриває підказку про його сутність.\n\n\n\nЗавдає $360419s1 шкоди від тіні кожні $t2 сек., доки личини лордів жаху не подолано." },
    { en = "Mal'Ganis and Kin'tessa complete their deception, stunning all players for $362202d and inflicting $s1 Shadow damage every $t1 sec until they die.", ua = "Мал'Ганіс і Кін'тесса завершують свій обман, оглушуючи всіх гравців на $362202d і завдаючи $s1 шкоди від тіні кожні $t1 сек., доки вони не загинуть." },
    { en = "Mal'Ganis erupts into a swarm of insects, inflicting $360302s1 Plague damage to all players every $t4 sec for $d.\n\n\n\nDuring this time, Mal'Ganis takes $s3% increased damage.", ua = "Мал'Ганіс вибухає роєм комах, завдаючи $360302s1 шкоди від чуми всім гравцям кожні $t4 сек. протягом $d.\n\n\n\nУ цей час Мал'Ганіс отримує на $s3% більше шкоди." },
    { en = "Players can experience a moment of clarity, revealing to them the essences in which Mal'Ganis and Kin'tessa are hiding. The dreadlords will feed false information to their host in an attempt to obscure themselves.", ua = "Гравці можуть пережити мить прозріння, що розкриває їм сутності, у яких ховаються Мал'Ганіс і Кін'тесса. Лорди жаху згодовують своєму носієві хибну інформацію, намагаючись приховати себе." },
    { en = "Kin'tessa erupts into a swarm of darkness, inflicting $360303s1 Shadow damage to all players every $t4 sec for $d.\n\n\n\nDuring this time, Kin'tessa takes $s3% increased damage.", ua = "Кін'тесса вибухає роєм темряви, завдаючи $360303s1 шкоди від тіні всім гравцям кожні $t4 сек. протягом $d.\n\n\n\nУ цей час Кін'тесса отримує на $s3% більше шкоди." },
    { en = "Upon reaching 100 energy, Mal'Ganis causes the physical forms of both dreadlords to rupture into chaotic swarms for $360300d.", ua = "Досягнувши 100 енергії, Мал'Ганіс змушує фізичні форми обох лордів жаху розпастися на хаотичні рої протягом $360300d." },
    { en = "Rygelon compacts a massive amount of stellar matter into an infinitesimally small point, exploding for $363533s1 Cosmic damage to all players. This damage cannot be mitigated or avoided.", ua = "Райґелон стискає величезну кількість зоряної матерії в нескінченно малу точку, що вибухає, завдаючи $363533s1 космічної шкоди всім гравцям. Цю шкоду неможливо ні пом'якшити, ні уникнути." },
    { en = "Rygelon erupts with cosmic energy, inflicting $366606s2 Cosmic damage if there are no valid enemies.", ua = "Райґелон вивергає космічну енергію, завдаючи $366606s2 космічної шкоди, якщо немає придатних ворогів." },
    { en = "Destroyed Collapsing Quasars dip into The Singularity, becoming Unstable Quasars.\n\n\n\nUnstable Quasars begin to explode if players come within $366978A1 yards, inflicting $366992s1 Shadow damage to players within $366992A1 yards after $366980D.", ua = "Знищені згасаючі квазари занурюються в Сингулярність, стаючи нестабільними квазарами.\n\n\n\nНестабільні квазари починають вибухати, якщо гравці наближаються на $366978A1 м, завдаючи $366992s1 шкоди від тіні гравцям у радіусі $366992A1 м через $366980D." },
    { en = "Players in The Singularity suffer $364701s1 Cosmic damage every $364701T1 sec. This effect stacks.", ua = "Гравці в Сингулярності зазнають $364701s1 космічної шкоди кожні $364701T1 с. Цей ефект накопичується." },
    { en = "The Unstable Antimatter detonates any remaining Unstable Cores, exploding for $364432s1 Cosmic damage to all players.", ua = "Нестабільна антиматерія детонує всі залишкові нестабільні ядра, що вибухають, завдаючи $364432s1 космічної шкоди всім гравцям." },
    { en = "Rygelon summons $362390s1 |4Cosmic Core:Cosmic Cores;.", ua = "Райґелон прикликає $362390s1 |4космічне ядро:космічні ядра:космічних ядер;." },
    { en = "Every $364569T1 sec. the quasar gains additional $@spellname364569, increasing movement speed by $s2% and preventing it from being slowed below $364569s3% of normal speed. This effect stacks.", ua = "Кожні $364569T1 сек. квазар отримує додатковий $@spellname364569, що збільшує швидкість пересування на $s2% і не дає сповільнити його нижче $364569s3% звичайної швидкості. Цей ефект накопичується." },
    { en = "Collapsing Quasars fuse with the constellar upon contact, increasing damage done by $362273s1% and inflicting $362274s1 Cosmic damage to all players every $362273T2 sec for $362273D. This effect stacks.", ua = "Згасаючі квазари при зіткненні зливаються з констеляром, збільшуючи завдану шкоду на $362273s1% і завдаючи $362274s1 космічної шкоди всім гравцям кожні $362273T2 сек. протягом $362273D. Цей ефект накопичується." },
    { en = "Rygelon summons $362275s1 Collapsing Quasars, which seek out the constellar.", ua = "Райґелон прикликає $362275s1 згасаючих квазарів, які шукають констеляра." },
    { en = "Upon health depletion the Unstable Matter gains Burned Out, becoming immune to all damage. After $D the Unstable Matter heals by $369576s1%.", ua = "Коли здоров'я вичерпується, нестабільна матерія отримує ефект «Вигоріла» і стає несприйнятливою до будь-якої шкоди. Через $D нестабільна матерія зцілюється на $369576s1%." },
    { en = "Rygelon erupts with the raw material of unborn stars, inflicting $366379s1 Cosmic damage to all players and causing their next $366379s2 healing to be absorbed.", ua = "Райґелон вивергає сирий матеріал ненароджених зір, завдаючи $366379s1 космічної шкоди всім гравцям і змушуючи поглинути їхнє наступне зцілення на $366379s2." },
    { en = "Upon consumption or expiration, each $@spellname363115 implodes into $@spellname362798. This field inflicts $362798s1 Cosmic damage every half-second to players who stand within them, pulling them in.", ua = "Після поглинання або завершення кожен $@spellname363115 імплодує в $@spellname362798. Це поле завдає $362798s1 космічної шкоди щопівсекунди гравцям, які стоять у ньому, притягуючи їх." },
    { en = "Inflicts the unmitigated damage from $@spellname362184 as Physical and Cosmic damage every $362172T1 sec for $362172D. This effect stacks, adding to the effects of previous Corrupted Wounds.", ua = "Завдає непом'якшену шкоду від $@spellname362184 як фізичну й космічну шкоду кожні $362172T1 сек. протягом $362172D. Цей ефект накопичується, додаючись до ефектів попередніх зіпсованих ран." },
    { en = "Rygelon slashes with astral blades, inflicting $362136s1 Physical damage and $362171s1 Cosmic damage. Unmitigated damage is inflicted as |5 $@spellname362137.", ua = "Райґелон б'є астральними клинками, завдаючи $362136s1 фізичної шкоди та $362171s1 космічної шкоди. Непом'якшена шкода завдається як |5 $@spellname362137." },
    { en = "Rygelon envelops several players with dark magic, inflicting $362276s1 Shadow damage every $361548T1 sec for $361548D.\n\n\n\nExplodes as a $@spellname361553 upon expiration or death.", ua = "Райґелон огортає кількох гравців темною магією, завдаючи $362276s1 шкоди від тіні кожні $361548T1 сек. протягом $361548D.\n\n\n\nВибухає як $@spellname361553 після завершення чи смерті." },
    { en = "Dark spheroids form within pylons along the edge of the chamber.\n\n\n\nWhen destroyed by Rygelon all players lose $@spellname362207 and suffer $363598s1 Shadow damage every $363598T1 sec. This effect stacks.", ua = "Темні сфероїди формуються всередині пілонів уздовж краю зали.\n\n\n\nКоли Райґелон їх знищує, усі гравці втрачають $@spellname362207 і зазнають $363598s1 шкоди від тіні кожні $363598T1 сек. Цей ефект накопичується." },
    { en = "Rygelon absorbs all Unstable Quasars upon entering The Singularity, gaining an application of Dark Quasar for each absorbed. \n\n\n\nEvery $368080T1 sec. Rygelon ejects a Dark Quasar at a targeted player, exploding after $368082D for $368084s1 Shadow damage to players within $368084A1 yards.", ua = "Увійшовши в Сингулярність, Райґелон поглинає всі нестабільні квазари, отримуючи накопичення «Темний квазар» за кожен поглинутий. \n\n\n\nКожні $368080T1 сек. Райґелон викидає темний квазар у вибрану ціль-гравця, що вибухає через $368082D, завдаючи $368084s1 шкоди від тіні гравцям у радіусі $368084A1 м." },
    { en = "Inflicts $361553s1 Shadow damage to $?diff17[the Dark Eclipse afflicted player][all players].", ua = "Завдає $361553s1 шкоди від тіні $?diff17[гравцю під дією «Темного затемнення»][усім гравцям]." },
    { en = "Rygelon shatters an Unstable Antimatter spheroid, removing all players from $@spellname362207.", ua = "Райґелон розбиває сфероїд нестабільної антиматерії, знімаючи з усіх гравців $@spellname362207." },
    { en = "The Unstable Core continuously erupts for $368525s1 Shadow damage every $364267T1 sec to players within $364381A1 yards$?diff16[, and increases their damage taken from the Unstable Core by $368524s1% for $368524D. This effect stacks][]. Any damage inflicted to players in this way is also suffered by the core.", ua = "Нестабільне ядро безперервно вивергається, завдаючи $368525s1 шкоди від тіні кожні $364267T1 сек. гравцям у радіусі $364381A1 м$?diff16[ і збільшує отриману ними від нестабільного ядра шкоду на $368524s1% протягом $368524D. Цей ефект накопичується][]. Будь-яка шкода, завдана гравцям у такий спосіб, завдається й самому ядру." },
    { en = "The player gains a temporary view of Rygelon's dark cosmos for $362206D, allowing them to see Unstable Cores.\n\n\n\nAfflicted players explode upon expiration, inflicting $363735s1 Cosmic damage to allies within $363735A1 yards.", ua = "Гравець отримує тимчасовий вид на темний космос Райґелона на $362206D, що дозволяє йому бачити нестабільні ядра.\n\n\n\nУражені гравці вибухають після завершення, завдаючи $363735s1 космічної шкоди союзникам у радіусі $363735A1 м." },
    { en = "The player gains vision of Rygelon's dark cosmos, allowing them to see Unstable Cores.", ua = "Гравець отримує зір у темний космос Райґелона, що дозволяє йому бачити Нестабільні Ядра." },
    { en = "The Cosmic Core jettisons stellar material at the nearest player, inflicting $362081s1 Cosmic damage and an additional $362081s3 Cosmic damage every half-second to all players within $362081A1 yards, snaring them by $362081s2% for $362081D. This effect stacks.", ua = "Космічне Ядро викидає зоряну матерію в найближчого гравця, завдаючи $362081s1 космічної шкоди та додатково $362081s3 космічної шкоди щопівсекунди всім гравцям у межах $362081A1 ярдів і сповільнюючи їх на $362081s2% на $362081D. Цей ефект накопичується." },
    { en = "Upon destruction, the Unstable Core inflicts $364386s1 Physical damage and an additional $364386s2 Physical damage every half-second for $364386D to any players within $364386A1 yards. This effect stacks. This damage cannot be avoided.\n\n\n\nIf no players are struck by this effect, the Gravitational Collapse hits all players.", ua = "Під час знищення Нестабільне Ядро завдає $364386s1 фізичної шкоди та додатково $364386s2 фізичної шкоди щопівсекунди протягом $364386D усім гравцям у межах $364386A1 ярдів. Цей ефект накопичується. Цієї шкоди не можна уникнути.\n\n\n\nЯкщо жоден гравець не потрапляє під цей ефект, Гравітаційний Колапс уражає всіх гравців." },
    { en = "Rygelon protects the Unstable Matter orbs, shrouding them inside The Singularity.", ua = "Райґелон захищає сфери Нестабільної Матерії, ховаючи їх усередині Сингулярності." },
    { en = "Rygelon coalesces lines of stellar material, blasting players for $363109s1 Cosmic damage.", ua = "Райґелон зливає лінії зоряної матерії воєдино, вибухаючи й завдаючи гравцям $363109s1 космічної шкоди." },
    { en = "Cosmic Ejections taint their targets, inflicting $362088s1 Cosmic damage every $362088T1 sec for $362088D. This effect stacks, and instantly kills targets above $367298s1 applications.", ua = "Космічні Викиди опоганюють свої цілі, завдаючи $362088s1 космічної шкоди кожні $362088T1 сек. протягом $362088D. Цей ефект накопичується й миттєво вбиває цілі, що мають понад $367298s1 нашарувань." },
    { en = "As Rygelon begins to cast Massive Bang, burned out Unstable Matter explode into unstable energy zones for $363115D. Each field $?diff17[grants a single player $371168s1% haste for $371168D. All players enter The Singularity as long as Unstable Matter Fields were created.][protects a single player from the effects of Massive Bang, granting The Singularity instead.]", ua = "Коли Райґелон починає творити Гучний Вибух, вигоріла Нестабільна Матерія вибухає, утворюючи зони нестабільної енергії на $363115D. Кожне поле $?diff17[надає одному гравцеві $371168s1% поспіху на $371168D. Усі гравці входять до Сингулярності, доки створюються Поля Нестабільної Матерії.][захищає одного гравця від наслідків Гучного Вибуху, надаючи натомість Сингулярність.]" },
    { en = "Upon destruction the Collapsing Quasar becomes a field of unstable energy for $361462D. Players who contact the field are afflicted by $@spellname362206$?diff15|diff16[, consume the field][], and trigger a $@spellname361463 if afflicted with $@spellname361548, cleansing the effect.", ua = "Під час знищення Колапсуючий Квазар стає полем нестабільної енергії на $361462D. Гравці, які торкаються поля, уражаються $@spellname362206$?diff15|diff16[, споживають поле][] та спричиняють $@spellname361463, якщо вони уражені $@spellname361548, очищаючи ефект." },
    { en = "Inflicts $361463s1 Shadow damage to all players.", ua = "Завдає $361463s1 шкоди від тіні всім гравцям." },
    { en = "Volatile spheroids form within pylons along the edge of the chamber.", ua = "Нестабільні сфероїди формуються всередині пілонів уздовж краю зали." },
    { en = "The Jailer chains all players to him, pulling them towards his location and inflicting $s1 Shadow damage every $t1 sec for $d.\n\n \n\nThe Jailer casts $@spellname362617 as the chains expire.", ua = "Тюремник прив'язує всіх гравців ланцюгами до себе, притягуючи їх до свого місцеперебування й завдаючи $s1 шкоди від тіні кожні $t1 сек. протягом $d.\n\n \n\nКоли ланцюги спадають, Тюремник творить $@spellname362617." },
    { en = "The Jailer binds his current target in chains, inflicting $369808s1 Physical damage every $t1 sec for $d and growing in intensity over time.\n\n\n\nThe target is chained to the nearest  $s6 allies, who suffer any Physical damage taken by the primary target until their chains are broken. Moving $s5 yards from the primary target breaks a chain and triggers Chain Breaker.", ua = "Тюремник сковує поточну ціль ланцюгами, завдаючи $369808s1 фізичної шкоди кожні $t1 сек протягом $d, причому сила з часом зростає.\n\n\n\nЦіль прикута до найближчих  $s6 союзників, які зазнають усієї фізичної шкоди, отриманої основною ціллю, доки їхні ланцюги не буде розірвано. Відхід на $s5 ярдів від основної цілі розриває ланцюг і запускає Розривача Ланцюгів." },
    { en = "The chain shatters, inflicting $s1 Shadow damage to all players.", ua = "Ланцюг розколюється, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "The Jailer crushes Azeroth, inflicting $s1 Arcane damage and applying $@spellname366381 to all players. \n\n\n\nThe attack expels the $@spellname366401 around the chamber.", ua = "Тюремник трощить Азерот, завдаючи $s1 арканної шкоди та накладаючи $@spellname366381 на всіх гравців. \n\n\n\nАтака викидає $@spellname366401 по всій залі." },
    { en = "Arcane damage taken increased by $s1% for $d.", ua = "Отримувана арканна шкода збільшена на $s1% протягом $d." },
    { en = "The Jailer utters a wicked pronouncement to $s3 players causing them to erupt after $362401d, inflicting $s1 Shadow damage to all players within $A1 yards of targets.", ua = "Тюремник проголошує лиховісний вирок $s3 гравцям, через що вони вибухають через $362401d, завдаючи $s1 шкоди від тіні всім гравцям у межах $A1 ярдів від цілей." },
    { en = "The Jailer slams his current target, inflicting $363952s1 Physical damage and increasing Physical damage taken by $366545s1% for $366545d.", ua = "Тюремник б'є свою поточну ціль, завдаючи $363952s1 фізичної шкоди та збільшуючи отримувану фізичну шкоду на $366545s1% протягом $366545d." },
    { en = "The Jailer raises pylons into alignment, causing them to spread $@spellname360425.\n\n\n\nEach pylon creates up to 3 $@spellname366665 when it is raised, based on its proximity to the Machine of Origination.", ua = "Тюремник піднімає пілони в одну лінію, через що вони поширюють $@spellname360425.\n\n\n\nКожен пілон під час підняття створює до 3 $@spellname366665 залежно від його близькості до Машини Походження." },
    { en = "The Jailer cracks Azeroth, inflicting $s1 Arcane damage to all players. \n\n\n\nThis attack expels $@spellname366401 around the chamber.", ua = "Тюремник розколює Азерот, завдаючи $s1 арканної шкоди всім гравцям. \n\n\n\nЦя атака викидає $@spellname366401 по всій залі." },
    { en = "The Jailer consumes the $@spellname366401, shielding himself for the next $s1 damage. This effect stacks.", ua = "Тюремник споживає $@spellname366401, оточуючи себе щитом, що поглинає наступні $s1 шкоди. Цей ефект накопичується." },
    { en = "The Jailer's words echo after $s2 sec, inflicting $s1 Shadow damage to players within $A1 yards of where $@spellname362415 detonated.", ua = "Слова Тюремника відлунюють через $s2 сек., завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів від місця, де здетонував $@spellname362415." },
    { en = "The Jailer launches destructive magic at his current target, inflicting $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d to players within $A1 yards.\n\n\n\nPylons caught in the blast are destroyed.", ua = "Тюремник вивергає руйнівну магію на свою поточну ціль, завдаючи $s1 шкоди Тінню та додатково $s2 шкоди Тінню кожні $t2 сек. протягом $d гравцям у межах $A1 ярдів.\n\n\n\nПілони, що потрапляють під удар, знищуються." },
    { en = "Each arc of Surging Azerite causes energy to erupt from the target in four directions that explode on contact, inflicting $s1 Arcane damage to all players within $A1 yds.", ua = "Кожна дуга Здіймання Азериту змушує енергію вирватися з цілі в чотирьох напрямках, що вибухає під час дотику, завдаючи $s1 арканної шкоди всім гравцям у межах $A1 ярдів." },
    { en = "A pool of Azerite forms for $d, empowered with $s3 Surges of Azerite. Standing in the pool triggers a Surge of Azerite every $s2 sec until the pool is consumed.", ua = "На $d утворюється калюжа азериту, наповнена $s3 Сплесками Азериту. Перебування в калюжі викликає Сплеск Азериту кожні $s2 сек., доки калюжу не буде вичерпано." },
    { en = "A surge of azerite flows into the target and repeatedly arcs to the nearest player within $s3 yards, inflicting $s1 Arcane damage and applying $@spellname366703 to players hit. The energy heals Azeroth for $s2% of its lifeforce if it is within range, ending the effect.", ua = "Сплеск азериту вливається в ціль і раз за разом перестрибує дугою на найближчого гравця в межах $s3 ярдів, завдаючи $s1 арканної шкоди та накладаючи $@spellname366703 на вражених гравців. Якщо Азерот у межах досяжності, енергія зцілює його на $s2% життєвої сили, завершуючи ефект." },
    { en = "Inflicts $s1 Shadow damage to all players.", ua = "Завдає $s1 шкоди від тіні всім гравцям." },
    { en = "The Jailer imposes his will on the world around him, dominating players and pylons within line of sight.", ua = "Тюремник нав'язує свою волю світові довкола, підкоряючи гравців і пілони в межах прямої видимості." },
    { en = "The Incarnation of Torment unleashes an agonizing scream, inflicting $s1 Shadow damage to all players and decreasing their haste by $s2%. This effect stacks.", ua = "Втілення Муки вивільняє болісний крик, завдаючи $s1 шкоди від тіні всім гравцям і зменшуючи їхній поспіх на $s2%. Цей ефект накопичується." },
    { en = "The Jailer finishes with a crushing attack, inflicting $s1 Physical damage split among all players within $A1 yards of impact$?DIFF14|DIFF15|DIFF17[.]$?|DIFF16[, knocking them back.]\n\n\n\n\n\nIf fewer than 5 players are hit the ground explodes, inflicting $366872s1 Shadow damage to all players.", ua = "Тюремник завершує нищівною атакою, завдаючи $s1 фізичної шкоди, розподіленої між усіма гравцями в межах $A1 ярдів від місця удару$?DIFF14|DIFF15|DIFF17[.]$?|DIFF16[, відкидаючи їх назад.]\n\n\n\n\n\nЯкщо влучено менш ніж по 5 гравцях, земля вибухає, завдаючи $366872s1 шкоди Тінню всім гравцям." },
    { en = "Dominated pylons create orbs of dark energy that mark random players and launch towards them $s1 sec later. Each wave of energy inflicts $s2 Shadow damage and an additional $366132s1 Shadow damage every $366132t1 sec for $366132d to players caught in their path.", ua = "Підкорені пілони створюють кулі темної енергії, що позначають випадкових гравців і кидаються на них за $s1 сек. Кожна хвиля енергії завдає $s2 шкоди Тіні та додатково $366132s1 шкоди Тіні кожні $366132t1 сек. протягом $366132d гравцям на її шляху." },
    { en = "The Jailer marks several players with a wicked rune for $366285d. Upon expiration the rune applies a shield that absorbs the next $s3 damage for $d. While the shield holds the player is hostile to allies and is compelled to jump off the edge of the platform.", ua = "Тюремник позначає кількох гравців лиховісною руною на $366285d. Після завершення руна накладає щит, що поглинає наступні $s3 шкоди протягом $d. Поки щит тримається, гравець ворожий до союзників і змушений стрибнути з краю платформи." },
    { en = "Increases damage taken from $@spellname362189 by $s1% for $d.", ua = "Збільшує шкоду, отриману від $@spellname362189, на $s1% протягом $d." },
    { en = "The Jailer shatters Azeroth, inflicting $s1 Arcane damage and applying $@spellname366381 to all players twice in quick succession.\n\n\n\nThis attack expels $@spellname366401 around the chamber.", ua = "Тюремник розбиває Азерот, завдаючи $s1 арканної шкоди та накладаючи $@spellname366381 на всіх гравців двічі поспіль.\n\n\n\nЦя атака викидає $@spellname366401 по всій залі." },
    { en = "The Jailer delivers a massive attack that inflicts $s1 Physical damage to all players and causes them to bleed for an additional $s2 Physical damage every $t2 sec for $d.", ua = "Тюремник завдає нищівного удару, що уражає всіх гравців на $s1 фізичної шкоди й змушує їх кровоточити, завдаючи додатково $s2 фізичної шкоди кожні $t2 сек протягом $d." },
    { en = "The Jailer marks several players with a dark rune that inflicts $360281s1 Shadow damage every $360281t1 sec for $360281d. Upon expiration the rune erupts, knocking the player upwards and inflicting $s1 Shadow damage to all players.\n\n\n\nIf the player is inside a pylon conduit, the eruption does not affect allies.", ua = "Тюремник позначає кількох гравців темною руною, що завдає $360281s1 шкоди Тінню кожні $360281t1 сек. протягом $360281d. По завершенні руна вибухає, підкидаючи гравця вгору й завдаючи $s1 шкоди Тінню всім гравцям.\n\n\n\nЯкщо гравець перебуває всередині провідника пілона, вибух не зачіпає союзників." },
    { en = "The Jailer dominates a player, increasing their health by $s2%, damage done by $s3% and takes control of their actions.", ua = "Тюремник підкорює гравця, збільшуючи його здоров'я на $s2%, завдану шкоду на $s3% і перебираючи контроль над його діями." },
    { en = "The Jailer marks several players with an evil rune for $365150d. Upon expiration the rune inflicts $s1 Shadow damage to players within $A1 yards and triggers $@spellname365153 at the player's location.", ua = "Тюремник позначає кількох гравців злою руною на $365150d. Після завершення руна завдає $s1 шкоди Тіні гравцям у радіусі $A1 ярдів і запускає $@spellname365153 у місці перебування гравця." },
    { en = "The Jailer applies a shield that absorbs the next $s1 healing, divided evenly amongst targets within $A1 yards of a target location.\n\n\n\nUpon expiration all targets are afflicted with $@spellname362075.", ua = "Тюремник накладає щит, що поглинає наступні $s1 зцілення, рівномірно розподілені між цілями в межах $A1 ярдів від цільового місця.\n\n\n\nПісля завершення всі цілі уражаються $@spellname362075." },
    { en = "The pylon radiates corrupted energy, inflicting $s1 Shadow damage every $t1 sec to nearby players.", ua = "Пілон випромінює зіпсовану енергію, завдаючи $s1 шкоди Тінню кожні $t1 сек. гравцям поблизу." },
    { en = "Azeroth expels the corruption from its recovered blood, inflicting $s1 Shadow damage and silencing players it contacts.", ua = "Азерот виштовхує скверну зі своєї відновленої крові, завдаючи $s1 шкоди від тіні та змушуючи замовкнути гравців, яких вона торкається." },
    { en = "The Jailer launches a deadly attack on Azeroth, reducing Azeroth's lifeforce by up to $s1%. Each player in the area of effect reduces the damage to Azeroth but suffers $365034s1 Shadow damage.", ua = "Тюремник завдає Азероту смертоносного удару, зменшуючи життєву силу Азерота на цілих $s1%. Кожен гравець у зоні дії знижує шкоду Азероту, але дістає $365034s1 шкоди від тіні." },
    { en = "The Jailer's words take form as an Incarnation of Torment where Torment detonated.", ua = "Слова Тюремника набувають форми Втілення Муки в місці, де здетонувала Мука." },
    { en = "The Jailer chains his current target, rooting them for $d.", ua = "Тюремник заковує свою поточну ціль, знерухомлюючи її на $d." },
    { en = "The target is infused with Azerite energy, increasing damage and healing done by $s2% while also increasing damage taken from $@spellname366408 by $s1% for $d. This effect stacks.", ua = "Ціль наповнюється енергією азериту, що збільшує завдану шкоду та зцілення на $s2%, але водночас збільшує шкоду від $@spellname366408 на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Corrupted pylons crash to the floor, inflicting $s1 Shadow damage to players within $A1 yards of the impact location.", ua = "Зіпсовані пілони падають на підлогу, завдаючи $s1 шкоди від тіні гравцям у межах $A1 ярдів від місця удару." },
    { en = "The Jailer fixates on his current target and executes a combination of powerful attacks.", ua = "Тюремник зосереджується на поточній цілі й виконує серію потужних атак." },
    { en = "The Jailer hurls the head of his flail, inflicting $s1 Shadow damage to players within $360858A1 yards of the point of impact location. The force of the impact inflicts $365423s2 Shadow damage every $365423t2 sec for $365423d.", ua = "Тюремник жбурляє голову свого ціпа, завдаючи $s1 шкоди від тіні гравцям у межах $360858A1 ярдів від місця удару. Сила удару завдає $365423s2 шкоди від тіні кожні $365423t2 сек. протягом $365423d." },
    { en = "The Jailer defiles part of the chamber for $365170d, inflicting $s1 Shadow damage every $t1 sec to players within the area. Each time a player suffers damage from Defile the area of effect greatly increases.", ua = "Тюремник опоганює частину зали на $365170d, завдаючи $s1 шкоди Тіні кожні $t1 сек гравцям у цій зоні. Щоразу, коли гравець зазнає шкоди від Опоганення, зона дії значно збільшується." },
    { en = "The Jailer detonates the ground around him, inflicting $s1 Shadow damage to all players. This damage is decreased the farther the player is from the Jailer.", ua = "Тюремник детонує землю довкола себе, завдаючи $s1 шкоди від тіні всім гравцям. Ця шкода зменшується тим більше, чим далі гравець перебуває від Тюремника." },
    { en = "Performs a Necrotic ritual of flesh, preventing enemies from receiving healing and inflicting $s2 Shadow damage every $t2 sec to enemies in the ritual area.", ua = "Проводить некротичний ритуал плоті, не даючи ворогам отримувати зцілення та завдаючи $s2 шкоди Тінню кожні $t2 сек. ворогам у зоні ритуалу." },
    { en = "Strikes at a target, inflicting $s1% of normal weapon damage to an enemy. This removes any $@spellname347548 stacks.", ua = "Б'є по цілі, завдаючи ворогові $s1% від звичайної шкоди зброї. Це знімає всі стопки $@spellname347548." },
    { en = "Shoots at an enemy, inflicting $s1 Physical damage and additionally increasing Ranger Shot damage by $s2%. This effect stacks.", ua = "Стріляє у ворога, завдаючи $s1 фізичної шкоди й додатково збільшуючи шкоду Пострілу Слідопита на $s2%. Цей ефект накопичується." },
    { en = "The caster exposes the deepest desires of the target's heart, inflicting $s1 Physical damage.\n\nThe victim is afflicted with $@spellname325382 for $325382d.", ua = "Чаротворець оголює найглибші бажання серця цілі, завдаючи $s1 фізичної шкоди.\n\nЖертва зазнає дії $@spellname325382 протягом $325382d." },
    { en = "The impact area reverberates shortly afterwards, inflicting $s1 Physical damage to players within $A1 yds.", ua = "Зона удару незабаром відлунює, завдаючи $s1 фізичної шкоди гравцям у межах $A1 ярдів." },
    { en = "Inflicts $341307s1 Physical damage to players within $341307A1 yards of each impact location.\n\n\n\nCauses a $@spellname341482 if $@spellname341102 fails to hit at least one player.", ua = "Завдає $341307s1 фізичної шкоди гравцям у радіусі $341307A1 ярдів від кожного місця влучання.\n\n\n\nВикликає $@spellname341482, якщо $@spellname341102 не влучає принаймні в одного гравця." },
    { en = "The Engine Core protects itself with an energy barrier that absorbs up to $s1 damage.\n\n\n\nUpon removal the core begins emitting $@spellname363415.", ua = "Ядро Двигуна захищає себе енергетичним бар'єром, що поглинає до $s1 шкоди.\n\n\n\nПісля його зняття ядро починає випромінювати $@spellname363415." },
    { en = "The Defense Core inflicts $363416s1 Cosmic damage every $t1 sec to all players while $@spellname363414 is removed.", ua = "Ядро Захисту завдає $363416s1 космічної шкоди кожні $t1 сек усім гравцям, поки $@spellname363414 знято." },
    { en = "A cloak of fire enshrouds Kael'thas, absorbing $w1 healing received. Removing the $@spellname337859 interrupts Kael'thas.", ua = "Плащ із вогню огортає Кель'таса, поглинаючи $w1 отриманого зцілення. Зняття $@spellname337859 перериває Кель'таса." },
    { en = "The $@spellname348456 erupts, inflicting $s1 Fire damage to all players.", ua = "$@spellname348456 вибухає, завдаючи $s1 вогняної шкоди всім гравцям." },
    { en = "Priestess Alun'za summons a spirit of pure gold that will move to absorb any pools of Tainted Blood.  When no pools of Tainted Blood are available, the spirit will attack players.", ua = "Жриця Алун'за прикликає духа з чистого золота, що рушає поглинати будь-які калюжі Опоганеної Крові. Коли калюж Опоганеної Крові не лишається, дух починає нападати на гравців." },
    { en = "The victim's blood is tainted, inflicting $s1 Shadow damage every $t1 sec.", ua = "Кров жертви опоганена, завдаючи $s1 шкоди від тіні кожні $t1 с." },
    { en = "The player is splashed with corrupted gold, burning them for $s1 Fire damage and lowering their damage dealt by $277072s1% for $277072d.", ua = "Гравця оббризкує зіпсованим золотом, обпікаючи його на $s1 шкоди вогнем і знижуючи завдану ним шкоду на $277072s1% на $277072d." },
    { en = "Priestess Alun'za channels a Ritual of Purification for $d, inflicting $255575s1 Shadow damage to all players and healing herself for ${$255835s1/100}.2% of her health every $t1 sec. for $d. Any player with $@spellname255558 will cause Priestess Alun'za to lose ${$255836s1/100}.2% of her maximum health instead of healing.", ua = "Жриця Алун'за читає Ритуал Очищення впродовж $d, завдаючи $255575s1 шкоди від тіні всім гравцям і зцілюючи себе на ${$255835s1/100}.2% свого здоров'я кожні $t1 с. впродовж $d. Кожен гравець із $@spellname255558 змусить Жрицю Алун'за втратити ${$255836s1/100}.2% свого максимального здоров'я замість зцілення." },
    { en = "The caster coats their hands in molten gold, making their melee swings deal $255581s1% Physical damage for $d.", ua = "Творець укриває свої руки розплавленим золотом, через що його удари в ближньому бою завдають $255581s1% фізичної шкоди впродовж $d." },
    { en = "Priestess Alun'za agitates a pool of molten gold, splattering a player at random. The victim burns for $255582s1 Fire damage every $255582t1 sec for $255582d.", ua = "Жриця Алун'за збурює калюжу розплавленого золота, оббризкуючи випадкового гравця. Жертва горить, зазнаючи $255582s1 шкоди вогнем кожні $255582t1 сек протягом $255582d." },
    { en = "Inflicts $250368s1 Nature damage to all players every $t1 sec for $d. In addition, each player hit is afflicted with $@spellname250372.", ua = "Завдає $250368s1 шкоди від сил природи всім гравцям кожні $t1 сек протягом $d. Окрім того, кожен уражений гравець зазнає дії «$@spellname250372»." },
    { en = "Vol'kaal begins to decay, inflicting $s2 Shadow damage to himself every $t2 sec until he is slain. \n\n\n\nIn his death throes, Vol'kaal increases his Physical damage done by $s1% and begins to spew Toxic Pools.", ua = "Вол'каал починає розкладатися, завдаючи собі $s2 шкоди від тіні кожні $t2 с, доки його не буде вбито. \n\n\n\nУ передсмертних корчах Вол'каал збільшує завдану ним фізичну шкоду на $s1% і починає вивергати Токсичні Калюжі." },
    { en = "Inflicts $259574s1 Nature damage every $t1 sec for $d.  This effect stacks.", ua = "Завдає $259574s1 шкоди від сил природи кожні $t1 с впродовж $d. Цей ефект накопичується." },
    { en = "Heals a Reanimation Totem for $s1% of its maximum life.\n\n\n\nThis cast is interrupted when all Reanimation Totems are slain.", ua = "Зцілює Тотем Воскресіння на $s1% його максимального здоров'я.\n\n\n\nЦе творіння переривається, коли всі Тотеми Воскресіння знищено." },
    { en = "Yazma's totems suspend the decay of Vol'kaal's body. While at least 1 $@spellname250190 is active Vol'kaal is granted $@spellname250192.", ua = "Тотеми Язми спиняють розклад тіла Вол'каала. Доки активний бодай 1 $@spellname250190, Вол'каал отримує $@spellname250192." },
    { en = "While any $@spellname250190 totems are active Vol'kaal heals for $s2% of his maximum health every $t2 sec.\n\n\n\nOnce all $s1 totems are destroyed, Yazma's voodoo dissipates, dispelling $@spellname250192 and causing Vol'kaal to $@spellname250241.", ua = "Доки активні будь-які тотеми $@spellname250190, Вол'каал зцілюється на $s2% свого максимального здоров'я кожні $t2 с.\n\n\n\nКоли всі $s1 тотеми знищено, вуду Язми розвіюється, знімаючи $@spellname250192 і змушуючи Вол'каала $@spellname250241." },
    { en = "Vol'kaal leaps towards a random player inflicting $250259s1 Nature to players within $250259A1 yards of the impact, knocking them back.", ua = "Вол'каал стрибає до випадкового гравця, завдаючи $250259s1 шкоди від сил природи гравцям у межах $250259A1 м від місця удару та відкидаючи їх." },
    { en = "Creates a pool of noxious fumes at random locations, that inflict $s1 Nature damage every $t1 sec to players standing within the pool.", ua = "Створює калюжу отруйних випарів у випадкових місцях, що завдає $s1 шкоди від сил природи кожні $t1 с гравцям, які стоять у калюжі." },
    { en = "The remains of this raptor are ready to awaken at the slightest disturbance. Standing in the bones spawns a Reanimated Raptor that will attack players.", ua = "Останки цього раптора готові пробудитися від найменшого поруху. Стоячи серед кісток, ви прикликаєте Воскреслого Раптора, що нападе на гравців." },
    { en = "Rezan's bite causes the victim to bleed profusely for $d. While bleeding in this manner, the victim takes an additional $s2% more Physical damage.", ua = "Укус Резана змушує жертву рясно кровоточити впродовж $d. Кровоточачи в такий спосіб, жертва отримує додатково на $s2% більше фізичної шкоди." },
    { en = "Passing through a pile of bones causes you to move slower for a short period of time.", ua = "Проходження крізь купу кісток ненадовго сповільнює ваш рух." },
    { en = "Causes enemies in line of sight to flee in fear for $d.", ua = "Змушує ворогів у полі зору тікати від страху впродовж $d." },
    { en = "Rezan shakes the ground, waking all remaining bone piles.", ua = "Резан стрясає землю, пробуджуючи всі рештки куп кісток." },
    { en = "Rezan tries to eat the victim whole, inflicting $255445s1 Physical damage every $t1 sec. for $d.", ua = "Резан намагається проковтнути жертву цілком, завдаючи $255445s1 фізичної шкоди кожні $t1 с. впродовж $d." },
    { en = "Rezan starts pursuing a random enemy player.  If he manages to catch up to the victim, he will Devour them.", ua = "Резан починає переслідувати випадкового ворожого гравця. Якщо йому вдасться наздогнати жертву, він її Пожере." },
    { en = "Yazma unleashes a wave of shadowy energy that hits all players, inflicting $259147s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Язма вивільняє хвилю тіньової енергії, що влучає у всіх гравців, завдаючи $259147s1 шкоди від тіні кожні $t1 с впродовж $d. Цей ефект накопичується." },
    { en = "Summons forth several shadowy spider images. Touching an Echo of Shadra causes it to burst inflicting $250022s2 Shadow damage to players within $250022A2 yards, creating a pool of Shadowy Remains at the location.", ua = "Прикликає кілька тіньових подоб павуків. Доторк до Відлуння Шадри змушує його вибухнути, завдаючи $250022s2 шкоди від тіні гравцям у межах $250022A2 м і створюючи калюжу Тіньових Решток на цьому місці." },
    { en = "Upon reaching 100 Energy, Yazma inflicts $259145s1 Shadow damage to a random player, ripping a piece of the target's soul free, creating a Soulspawn at the target's location.", ua = "Сягнувши 100 енергії, Язма завдає $259145s1 шкоди від тіні випадковому гравцю, видираючи шматок душі цілі та створюючи Душепородження на місці цілі." },
    { en = "All $@spellname249926 slowly move towards Yazma. When a Soulspawn reaches her, she unleashes a $@spellname256577.", ua = "Усі $@spellname249926 повільно рухаються до Язми. Коли Душепородження досягає її, вона вивільняє $@spellname256577." },
    { en = "A portion of the damage taken by the Soulspawn is duplicated to the linked player.", ua = "Частина шкоди, отриманої Душепородженням, дублюється на зв'язаного з ним гравця." },
    { en = "Inflicts $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Завдає $s1 шкоди від тіні та додатково $s2 шкоди від тіні кожні $t2 с впродовж $d." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec and reduces the target's movement speed by $s2% while within the effect.", ua = "Завдає $s1 шкоди від тіні кожні $t1 с і знижує швидкість пересування цілі на $s2%, доки вона перебуває в зоні ефекту." },
    { en = "Upon reaching 100 Energy, Yazma inflicts $259191s1 Shadow damage to all players. The impact rips a piece of the target's soul free, creating a Soulspawn at the target's location.", ua = "Сягнувши 100 енергії, Язма завдає $259191s1 шкоди від тіні всім гравцям. Удар видирає шматок душі цілі, створюючи Душепородження на місці цілі." },
    { en = "Inflicts $s1 Physical damage to Yazma's current target.", ua = "Завдає $s1 фізичної шкоди поточній цілі Язми." },
    { en = "Sharkbait bombards his enemies with a vile puddle, inflicting $256016s1 Nature damage every $256016t1 sec and movement speed is decreased by $256016s2% to anyone in the area.", ua = "Шаркбейт закидає своїх ворогів мерзенною калюжею, завдаючи $256016s1 шкоди від сил природи кожні $256016t1 с і знижуючи швидкість пересування на $256016s2% усім у зоні." },
    { en = "Inflicts $s2 Fire damage and an additional $s3 fire damage every $t3 sec for $d to players in front of the caster.", ua = "Завдає $s2 шкоди вогнем і додатково $s3 шкоди вогнем кожні $t3 с впродовж $d гравцям перед творцем." },
    { en = "Sharkbait charges across the battlefield, inflicting $s2 Nature damage and knocking back all players in the way.", ua = "Шаркбейт мчить через поле бою, завдаючи $s2 шкоди від сил природи і відкидаючи всіх гравців на своєму шляху." },
    { en = "Charrrrrges towards a random enemy, inflicting $s1 Nature damage and knocking back all players within $A1 yards.", ua = "Мчиться на випадкового ворога, завдаючи $s1 шкоди від сил природи й відкидаючи всіх гравців у радіусі $A1 м." },
    { en = "Skycap'n Kragg chugs a healing brew, healing an increasing amount every $t1 sec. over $d. Interrupting his chugging will knock the bottle out of his hand to the ground around him.", ua = "Небокеп Краґґ хлище цілющий настій, зцілюючись на дедалі більшу величину кожні $t1 с протягом $d. Якщо перервати його пиятику, пляшка випаде з його руки на землю поряд із ним." },
    { en = "The caster draws a concealed pistol and fires a quick shot at an enemy, dealing $s1 Fire damage.", ua = "Творець вихоплює прихований пістоль і робить швидкий постріл по ворогу, завдаючи $s1 шкоди вогнем." },
    { en = "Increases Critical Strike by $s1% for $d.", ua = "Підвищує Критичний удар на $s1% протягом $d." },
    { en = "Raoul throws an empty barrel at a random enemy, disorienting them until the barrel is destroyed.", ua = "Раул кидає порожню бочку у випадкового ворога, дезорієнтуючи його, доки бочку не буде знищено." },
    { en = "Dashes to a player, inflicting $267523s1 Physical damage to targets within $267523A1 yds. Players struck are left bleeding for $267523s2 Physical damage every $267523t2 sec for $267523d.", ua = "Кидається до гравця, завдаючи $267523s1 фізичної шкоди цілям у межах $267523A1 м. Уражені гравці кровоточать, отримуючи $267523s2 фізичної шкоди кожні $267523t2 с впродовж $267523d." },
    { en = "Increases Haste by $s1% for $d.", ua = "Підвищує Поспіх на $s1% протягом $d." },
    { en = "While allied with players, Eudora loads her rifle with a chain bola and blasts it at her enemy target, stunning them for $272905d.", ua = "Доки Еудора в союзі з гравцями, вона заряджає свою рушницю ланцюговою болою і стріляє нею у свою ворожу ціль, оглушуючи її на $272905d." },
    { en = "Captain Jolly unleashes a whirling saber empowered by the seas that inflicts $272397s1 Nature damage every second to all nearby enemies.", ua = "Капітан Джоллі випускає вируючу шаблю, наснажену силою морів, що завдає $272397s1 шкоди від сил природи щосекунди всім ворогам поблизу." },
    { en = "Raoul lifts his emptied barrel of grog and slams it to the ground repeatedly for $d. All enemies within $256594A2 yards suffer $256594s2 Physical damage and are knocked back every second.", ua = "Раул здіймає свою спорожнілу бочку з грогом і раз за разом гатить нею об землю впродовж $d. Усі вороги в межах $256594A2 м отримують $256594s2 фізичної шкоди і щосекунди відкидаються." },
    { en = "Eudora leaps to a new location and fires wide blasts of grapeshot in a cone in front her across the arena. Each blast inflicts $258352s1 Fire damage and additional $258352s2 Fire damage every $258352t2 sec for $258352d.", ua = "Еудора стрибає на нове місце і дає широкі залпи картеччю в конусі перед собою через усю арену. Кожен залп завдає $258352s1 вогняної шкоди і додатково $258352s2 вогняної шкоди кожні $258352t2 с протягом $258352d." },
    { en = "While allied with players, Jolly bends the trade winds to his will, increasing the movement speed of nearby allies by $s1% for $d.", ua = "Доки Джоллі в союзі з гравцями, він підкоряє пасатні вітри своїй волі, збільшуючи швидкість пересування ближніх союзників на $s1% впродовж $d." },
    { en = "Eudora fires a heavy powder shot at a random enemy, inflicting $s1 Physical damage.", ua = "Еудора робить важкий пороховий постріл по випадковому ворогу, завдаючи $s1 фізичної шкоди." },
    { en = "While allied with players, Raoul will tap a keg of his own personal supply, showering nearby allies with brew. Nearby allies inflict $272900s1% more damage.", ua = "Поки Рауль у союзі з гравцями, він відкорковує барило з власних запасів і обливає брагою найближчих союзників. Союзники поряд завдають на $272900s1% більше шкоди." },
    { en = "Trothak charges a nearby shark, inflicting $s1 Physical damage to anyone in the way. Upon reaching the shark, Trothak reattaches the shark to his arm.", ua = "Тротак кидається до акули поблизу, завдаючи $s1 фізичної шкоди всім на своєму шляху. Діставшись акули, Тротак знову прикріплює її до руки." },
    { en = "Trothak holds his shark by the tail and spins in a circle, inflicting $s1 Physical damage every $256405t1 sec to all enemies within $A1 yards.", ua = "Тротак тримає свою акулу за хвіст і кружляє по колу, завдаючи $s1 фізичної шкоди кожні $256405t1 с усім ворогам у радіусі $A1 ярдів." },
    { en = "A loose shark leaps at the nearest enemy, inflicting $s1 Nature damage to all enemies within $A1 yards of the shark.", ua = "Зірвана акула стрибає на найближчого ворога, завдаючи $s1 шкоди від сил природи всім ворогам у радіусі $A1 ярдів від неї." },
    { en = "Trothak punches a nearby enemy, inflicting $s1 Physical damage and bleeding the target for $s2 every $t2 sec for $d.", ua = "Тротак б'є кулаком найближчого ворога, завдаючи $s1 фізичної шкоди та спричиняючи кровотечу — $s2 кожні $t2 сек. протягом $d." },
    { en = "Rowdy spectators throw piles of meat into the arena creating slippery areas, slowing players movement by $s1%. Any sharks moving through the area consume the chum and stop flailing for $290068d.", ua = "Буйні глядачі кидають на арену купи м'яса, створюючи слизькі ділянки, що сповільнюють пересування гравців на $s1%. Будь-яка акула, що пропливає через таку ділянку, поглинає принаду й перестає борсатися протягом $290068d." },
    { en = "Trothak throws a shark at a player, inflicting $s1 Nature damage to all enemies $A1 yards.", ua = "Тротак жбурляє акулу в гравця, завдаючи $s1 від сил природи всім ворогам у межах $A1 м." },
    { en = "Irontide Grenadiers detonate when they reach their target, inflicting $s1 Fire damage to all enemies within $A1 yards.", ua = "Гренадери Залізного Припливу вибухають, досягнувши цілі, завдаючи $s1 вогнем усім ворогам у межах $A1 м." },
    { en = "Harlan Sweete orders an Irontide Grenadier to charge a random enemy.", ua = "Гарлан Світ наказує гренадеру Залізного Припливу налетіти на випадкового ворога." },
    { en = "Harlan hurls a dagger at a player, inflicting $s1 Physical damage and $s2 Physical damage every $t2 sec for $d.", ua = "Гарлан кидає кинджал у гравця, завдаючи $s1 фізичної шкоди та ще $s2 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "All hands on deck! Harlan Sweete's abilities target additional enemies.", ua = "Усі на палубу! Здібності Гарлана Світа вражають додаткових ворогів." },
    { en = "Harlan's dice give him the power of a Man-O-War. Attack speed increased by $s1% and all damage taken increased by $s2%.\n\nHarlan Sweete's abilities trigger more frequently.", ua = "Кості Гарлана дарують йому міць бойової галери. Швидкість атаки підвищено на $s1%, а вся отримувана шкода зростає на $s2%.\n\nЗдібності Гарлана Світа спрацьовують частіше." },
    { en = "Every $t1 sec the target marks their current location. After 1.5 sec, the marked location explodes inflicting $257310s1 Fire damage to all players within $257310A1 yards.\n\n\n\nIn addition, the target is hit with Flaming Shrapnel causing them to suffer $257308s1 Fire damage every $t1 sec for $d.", ua = "Кожні $t1 сек. ціль позначає своє нинішнє місце. За 1,5 сек. позначене місце вибухає, завдаючи $257310s1 вогнем усім гравцям у межах $257310A1 м.\n\n\n\nКрім того, ціль уражає Палаюча Шрапнель, через що вона зазнає $257308s1 вогнем кожні $t1 сек. протягом $d." },
    { en = "With a flick of his saber, Harlan bends the tradewinds to his will and sends them flying forward. Enemies that collide with the winds are knocked up and suffer $s1 Nature damage.", ua = "Помахом шаблі Гарлан підкоряє своїй волі пасатні вітри й посилає їх уперед. Вороги, що зіткнуться з вітрами, підкидаються в повітря й зазнають $s1 від сил природи." },
    { en = "Turns all pools of Molten Gold in the area into Animated Gold.", ua = "Перетворює всі калюжі Розплавленого Золота в окрузі на Оживлене Золото." },
    { en = "Shields the Golden Serpent for $s2% of its health in damage, and increases its damage done by $s1% until removed.", ua = "Захищає Золотого змія щитом, що поглинає шкоду в розмірі $s2% його здоров'я, і підвищує завдавану ним шкоду на $s1%, доки не зникне." },
    { en = "Spits molten gold at a player, inflicting $s1 Fire damage every $t1 sec. for $d, and creating a pool of Molten Gold at the player's location afterwards.", ua = "Плює розплавленим золотом у гравця, завдаючи $s1 вогнем кожні $t1 сек. протягом $d, а потім створює калюжу Розплавленого Золота на місці гравця." },
    { en = "Unleashes a gust of wind, inflicting $s1 damage to players within $A1 yards and knocking them back.", ua = "Здіймає порив вітру, завдаючи $s1 шкоди гравцям у межах $A1 м і відкидаючи їх назад." },
    { en = "A heavy hitting melee strike that inflicts $s1 Physical damage.", ua = "Потужний удар у ближньому бою, що завдає $s1 фізичної шкоди." },
    { en = "Inflicts $s1 Fire damage every $t1 sec. to players who touch the molten gold.", ua = "Завдає $s1 вогнем кожні $t1 сек. гравцям, які торкаються розплавленого золота." },
    { en = "Inflicts $s1 Fire damage every $t1 sec. to any players inside a patch of Burning Ground.", ua = "Завдає $s1 вогнем кожні $t1 сек. будь-яким гравцям, що стоять на ділянці Палаючої Землі." },
    { en = "Prepares the target for mummification by draining their fluids, inflicting $s1 Nature damage every $t1 sec. for $d. If the effect lasts the full duration, it applies Desiccation to the target.", ua = "Готує ціль до муміфікації, висушуючи її тілесні рідини, завдаючи $s1 від сил природи кожні $t1 сек. протягом $d. Якщо ефект протриває весь час, він накладає на ціль Висихання." },
    { en = "Reduces damage done by $s1% and movement speed by $s2%. Lasts until the target is healed above 90% health.", ua = "Знижує завдавану шкоду на $s1%, а швидкість пересування — на $s2%. Триває, доки ціль не зцілять понад 90% здоров'я." },
    { en = "Afflicts all players with a disease, causing $s1 Nature damage every $t1 sec. for $d.", ua = "Уражає всіх гравців хворобою, що завдає $s1 від сил природи кожні $t1 сек. протягом $d." },
    { en = "Entombs the target within one of the crypts inside the chamber. After casting Entomb, Mchimba will move between the crypts, opening them one at a time, beginning with the crypts that do not contain the entombed player.\n\n\n\nReleasing the Entombed player will interrupt the ritual, preventing Mchimba from releasing additional Half-Finished Mummies.", ua = "Замуровує ціль в одній із крипт усередині палати. Сотворивши Замурування, Мчимба пересувається між криптами, відкриваючи їх по одній, починаючи з тих, де немає замурованого гравця.\n\n\n\nЗвільнення замурованого гравця перерве ритуал і не дасть Мчимбі випустити більше Недороблених Мумій." },
    { en = "Burns the ground, inflicting $s1 Fire damage to players within $A1 yards and creating a patch of Burning Ground.", ua = "Спалює землю, завдаючи $s1 вогнем гравцям у межах $A1 м і створюючи ділянку Палаючої Землі." },
    { en = "Opens one of the crypts, releasing the occupant. Each open coffin reduces the time required to open subsequent coffins.", ua = "Відкриває одну з крипт, випускаючи її мешканця. Кожна відкрита труна скорочує час, потрібний на відкриття наступних." },
    { en = "Gouts of water spew forth from the totem, inflicting $s1 Frost damage to players within $A1 yards and knocking them back.", ua = "Тотем вивергає струмені води, що завдають $s1 від морозу гравцям у межах $A1 м і відкидають їх назад." },
    { en = "Explodes, inflicting $s1 Fire damage to all players.", ua = "Вибухає, завдаючи $s1 вогнем усім гравцям." },
    { en = "Aka'ali charges a targeted player, hitting any players in between her and the targeted player for $266939s1 Physical damage, and hitting the targeted player with Barreling Impact.", ua = "Ака'алі налітає на позначеного гравця, вражаючи всіх гравців між нею та ціллю на $266939s1 фізичної шкоди й уражаючи позначену ціль Тараном." },
    { en = "Creates a burst of poisonous gas, inflicting $s1 Nature damage to all players every $t1 sec. for $d.", ua = "Створює спалах отруйного газу, що завдає $s1 від сил природи всім гравцям кожні $t1 сек. протягом $d." },
    { en = "Inflicts $s1 Nature damage.", ua = "Завдає $s1 від сил природи." },
    { en = "Zanazal the Wise calls forth his four elemental totems.", ua = "Заназал Мудрий прикликає свої чотири стихійні тотеми." },
    { en = "Increases physical damage taken by $s2%.", ua = "Підвищує отримувану фізичну шкоду на $s2%." },
    { en = "Inflicts $s1 Physical damage every $t1 sec. for $d.", ua = "Завдає $s1 фізичної шкоди кожні $t1 сек. протягом $d." },
    { en = "Protects the currently active councilor with a wall of earth, absorbing up to $s1 damage for $d.", ua = "Захищає нинішнього активного радника стіною землі, поглинаючи до $s1 шкоди протягом $d." },
    { en = "A burst of thunder interrupts all players for $d.", ua = "Удар грому перериває дії всіх гравців на $d." },
    { en = "Inflicts $s1 Physical damage to the target and knocks them back. The damage is reduced for every player hit by Barrel Through.", ua = "Завдає $s1 фізичної шкоди цілі й відкидає її назад. Шкода зменшується за кожного гравця, ураженого Проривом." },
    { en = "Wallops her current target with a Debilitating Backhand, inflicting $s1 Physical damage, knocking them back, and applying Shattered Defenses to them.", ua = "Гамселить свою нинішню ціль Знесилюючим Зворотним Ударом, завдаючи $s1 фізичної шкоди, відкидаючи її назад і накладаючи на неї Зламаний Захист." },
    { en = "Unleashes a whirling attack that inflicts $s2 Physical damage to players within $A2 yards, knocking them back. \n\n\n\nAlso, she throws two whirling axes which inflict $266191s1 Physical damage every $266191t1 sec. for $266191d to players who come into contact with them, and knock the player back.", ua = "Здійснює вихровий напад, що завдає $s2 фізичної шкоди гравцям у межах $A2 м і відкидає їх назад.\n\n\n\nТакож кидає дві вихрові сокири, що завдають $266191s1 фізичної шкоди кожні $266191t1 сек. протягом $266191d гравцям, які з ними стикаються, і відкидають гравця назад." },
    { en = "Dazar leaps at the targeted player, inflicting up to $268936s1 Physical damage to all players. This damage is reduced the further players are from the targeted location.", ua = "Дазар стрибає на позначеного гравця, завдаючи до $268936s1 фізичної шкоди всім гравцям. Ця шкода зменшується тим більше, чим далі гравці від позначеного місця." },
    { en = "All damage done to Dazar is redirected to T'zala.", ua = "Уся шкода, завдана Дазару, перенаправляється на Т'залу." },
    { en = "A series of deadly melee strikes that deal increasing damage to their target.", ua = "Низка смертоносних ударів у ближньому бою, що завдають цілі дедалі більшої шкоди." },
    { en = "Jumps towards a targeted player and unleashes a series of gutripping attacks, inflicting $269230s1 Physical to players in a cone with each attack.", ua = "Стрибає до обраного гравця й завдає низки нутровипускних ударів, завдаючи кожним ударом $269230s1 фізичної шкоди гравцям у конусі." },
    { en = "Dazar gathers the power of wind in his blade and slashes, creating a tornado that moves to a player's location and then swirls around the area, inflicting $268419s1 Nature damage every $268419t1 sec. for $d to any players hit, and knocking them back.", ua = "Дазар збирає силу вітру у своєму клинку й б'є, створюючи торнадо, що рухається до місця гравця, а потім кружляє територією, завдаючи $268419s1 шкоди від сил природи кожні $268419t1 сек. протягом $d усім враженим гравцям і відкидаючи їх." },
    { en = "Inflicts $s1 Shadow damage to all players and makes them run in fear for $d.", ua = "Завдає $s1 шкоди від тіні всім гравцям і змушує їх тікати в страху протягом $d." },
    { en = "Launches a spear from a trap, impaling any players hit, inflicting $s1 Physical damage every $t1 sec. and stunning them for $d.", ua = "Випускає з пастки спис, що проштрикує всіх уражених гравців, завдаючи $s1 фізичної шкоди кожні $t1 сек. й оглушуючи їх на $d." },
    { en = "Inflicts $s1 Physical damage and stuns players within $a1 yards of the impact.", ua = "Завдає $s1 фізичної шкоди й оглушує гравців у радіусі $a1 м від місця удару." },
    { en = "Upon reaching 100 energy, Gobbamak smashes his primary target inflicting $s1 Physical damage. Additionally, $@spellname297254 inflicts $297256s1 Nature damage split evenly among all players within $297256a1 yards of the primary target and knocks them back. \n\n \n\nThis applies $@spellname297257 to each target struck.", ua = "Досягнувши 100 одиниць енергії, Ґоббамак гамселить свою основну ціль, завдаючи $s1 фізичної шкоди. Крім того, $@spellname297254 завдає $297256s1 шкоди від сил природи, рівномірно розподіленої між усіма гравцями в радіусі $297256a1 м від основної цілі, і відкидає їх. \n\n \n\nЦе накладає $@spellname297257 на кожну вражену ціль." },
    { en = "Moving near stolen tech with $@spellname297257 removes it and powers the device for $d.", ua = "Наближення до викраденої техніки з $@spellname297257 знімає його й живить пристрій протягом $d." },
    { en = "Thrashes nearby Troggs, instantly killing them.", ua = "Молотить ближніх троґґів, миттєво вбиваючи їх." },
    { en = "Inflicts $s1 Nature damage to the victim and an ally within $297311a1 yards every $t1 sec.\n\n\n\nMoving within $297311a1 yards of Stolen Tech removes $@spellname297257 and temporarily powers the device.", ua = "Завдає $s1 шкоди від сил природи жертві та союзникові в радіусі $297311a1 м кожні $t1 сек.\n\n\n\nНаближення на $297311a1 м до викраденої техніки знімає $@spellname297257 і тимчасово живить пристрій." },
    { en = "Attacks random targets.", ua = "Атакує випадкові цілі." },
    { en = "Zaps nearby Troggs, instantly killing them.", ua = "Б'є струмом ближніх троґґів, миттєво вбиваючи їх." },
    { en = "Gobbamak bounces up and down, inflicting $297262s1 Physical damage to all players every $t1 sec and causing $@spellname297283.", ua = "Ґоббамак підстрибує вгору-вниз, завдаючи $297262s1 фізичної шкоди всім гравцям кожні $t1 сек. і спричиняючи $@spellname297283." },
    { en = "Gobbamak calls Troggs from the surrounding caves to aid him.", ua = "Ґоббамак кличе троґґів із навколишніх печер собі на допомогу." },
    { en = "Gunker splatters $@spellname297821 all around itself and applies $@spellname298124 to a Squirt Bot.", ua = "Замазура розбризкує $@spellname297821 довкола себе й накладає $@spellname298124 на робота-оприскувача." },
    { en = "Inflicts $s1 Plague damage to Gunker's target.\n\n\n\nThis attack is only used by Gunker whenever it is not actively engaged in melee combat.", ua = "Завдає $s1 шкоди від чуми цілі Замазури.\n\n\n\nЗамазура застосовує цю атаку лише тоді, коли не веде активного ближнього бою." },
    { en = "Gunker releases Toxic Goop in all directions.", ua = "Замазура випускає Токсичний слиз на всі боки." },
    { en = "Gunker draws in players and $@spellname297821.", ua = "Замазура притягує гравців і $@spellname297821." },
    { en = "Squirt Bots sanitize the area around them, clearing $@spellname297821 they come into contact with and preventing its effects.", ua = "Роботи-оприскувачі дезінфікують територію навколо себе, прибираючи $@spellname297821, з яким стикаються, і запобігаючи його дії." },
    { en = "The victim is encased in goop, incapacitating them and inflicting $s1 Plague damage every $t1 sec until the goop is destroyed or removed.", ua = "Жертву огортає слиз, знерухомлюючи її й завдаючи $s1 шкоди від чуми кожні $t1 сек., доки слиз не буде знищено або знято." },
    { en = "Gunker emits $@spellname298229 throughout the encounter, inflicting $s1 Plague damage to all players every $298228t1 sec.", ua = "Замазура випромінює $@spellname298229 протягом усього бою, завдаючи $s1 шкоди від чуми всім гравцям кожні $298228t1 сек." },
    { en = "Gunker's abilities create $@spellname297821 throughout the area. Coming into contact with $@spellname297821 applies $@spellname298259 to the victim.", ua = "Здібності Замазури створюють $@spellname297821 по всій території. Контакт із $@spellname297821 накладає $@spellname298259 на жертву." },
    { en = "Trixie hovers to a different position.", ua = "Триксі перелітає на іншу позицію." },
    { en = "Charges to an area, inflicting $s1 Physical damage to all enemies within $A yards.", ua = "Кидається в зону, завдаючи $s1 фізичної шкоди всім ворогам у радіусі $A м." },
    { en = "When Naeno is defeated, Trixie gains $@spellname303525 granting her $s1% Haste for the remainder of the encounter.", ua = "Коли Наено переможено, Триксі отримує $@spellname303525, що дарує їй $s1% поспіху до кінця бою." },
    { en = "When defeated, Trixie uses $@spellname299241 on Naeno causing his successful melee attacks to inflict $s1 Nature damage to all players for the remainder of the encounter.", ua = "Коли її переможено, Триксі застосовує $@spellname299241 на Наено, через що його успішні удари в ближньому бою завдають $s1 шкоди від сил природи всім гравцям до кінця бою." },
    { en = "Naeno does a burnout, creating a $@spellname298573. Inflicts $298588s1 Physical damage and knocks back players caught in his path.", ua = "Наено робить пробуксовку, створюючи $@spellname298573. Завдає $298588s1 фізичної шкоди й відкидає гравців, що опинилися на його шляху." },
    { en = "Inflicts $s1 Nature damage instantly, and $s2 Nature damage every $t2 sec for $d.", ua = "Завдає $s1 шкоди від сил природи миттєво й $s2 шкоди від сил природи кожні $t2 сек. протягом $d." },
    { en = "Creates a cloud of thick smoke in a $s2 yard radius. Inflicts $298602s3 Nature damage every $298602t3 sec to players within it.\n\n\n\nEnemies are unable to target into or out of the smoke cloud.", ua = "Створює хмару густого диму радіусом $s2 м. Завдає $298602s3 шкоди від сил природи кожні $298602t3 сек. гравцям усередині.\n\n\n\nВороги не можуть обирати ціль крізь хмару диму — ні в неї, ні з неї." },
    { en = "Trixie jump starts the Mechacycle allowing Naeno to pilot it.", ua = "Триксі заводить Мехацикл, дозволяючи Наено керувати ним." },
    { en = "When Jump Started, Naeno pilots the Mechacycle.", ua = "Після запуску Наено керує Мехациклом." },
    { en = "Inflicts $s1 Nature damage every $t1 sec and stuns the victim for $d.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 сек і приголомшує жертву на $d." },
    { en = "Naeno speeds at a target, inflicts $298588s1 Physical damage and knocks back all players caught in his path.", ua = "Наено мчить до цілі, завдає $298588s1 фізичної шкоди й відкидає всіх гравців, що опинилися на його шляху." },
    { en = "Naeno slams the ground in front of him, inflicts $s1 Physical damage to players.", ua = "Наено гатить по землі перед собою, завдаючи $s1 фізичної шкоди гравцям." },
    { en = "Inflicts $s1 Nature damage and an additional $s2 Nature damage every $t2 sec for $d.", ua = "Завдає $s1 шкоди від сил природи й додатково $s2 шкоди від сил природи кожні $t2 сек. протягом $d." },
    { en = "The HK-8 Aerial Oppression Unit activates its $@spellname295939, inflicting $296025s1 Nature damage to all players every $t3 sec, and $296043s1 Nature damage to players within its area of effect.\n\n\n\nAfter $d, $@spellname295939 triggers $@spellname303206.", ua = "Повітряний блок гноблення HK-8 активує свій $@spellname295939, завдаючи $296025s1 шкоди від сил природи всім гравцям кожні $t3 сек. і $296043s1 шкоди від сил природи гравцям у зоні дії.\n\n\n\nЧерез $d $@spellname295939 запускає $@spellname303206." },
    { en = "Hack the Overcharge Station. When the Overcharge Station reaches 0 energy, the HK-8 Aerial Oppression Unit will fall to the ground and go $@spellname296080.", ua = "Зламайте Станцію перевантаження. Коли енергія Станції перевантаження сягне 0, Повітряний блок гноблення HK-8 упаде на землю й стане $@spellname296080." },
    { en = "Sentry Bots patrol the platforms, triggering $@spellname296279 on players they come into contact with.", ua = "Роботи-вартові патрулюють платформи, запускаючи $@spellname296279 на гравцях, з якими стикаються." },
    { en = "Inflicts $302384s1 Nature damage every $302384t1 sec to enemies within $s3 yards. \n\n\n\n$@spellname296518 leaves $@spellname296560, reducing movement speed by $296560s2% and inflicting $296560s1 Nature damage every $296560t1 sec to enemies within the affected area.", ua = "Завдає $302384s1 шкоди від сил природи кожні $302384t1 сек. ворогам у радіусі $s3 м. \n\n\n\n$@spellname296518 залишає $@spellname296560, знижуючи швидкість пересування на $296560s2% і завдаючи $296560s1 шкоди від сил природи кожні $296560t1 сек. ворогам у враженій зоні." },
    { en = "A series of devastating melee attacks that deal increasing damage to their target. \n\n\n\nEach attack inflicts massive Physical damage and increases Physical damage taken by $295445s2% for $295445d. This effect stacks.", ua = "Низка нищівних ударів у ближньому бою, що завдають цілі дедалі більшої шкоди. \n\n\n\nКожна атака завдає величезної фізичної шкоди й підвищує отримувану фізичну шкоду на $295445s2% протягом $295445d. Цей ефект накопичується." },
    { en = "Annihilates enemies, inflicting $s1 Nature damage to all players.", ua = "Знищує ворогів, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Self-Destructs upon reaching 0 energy, inflicting $s1 Nature damage to enemies within $A1 yards.", ua = "Запускає самознищення після досягнення 0 енергії, завдаючи $s1 шкоди від сил природи ворогам у межах $A1 м." },
    { en = "The HK-8 Aerial Oppression Unit fires its cannon at a targeted location, inflicting $295552s1 Nature damage to enemies caught in the blast.", ua = "Повітряний пригнічувач HK-8 стріляє з гармати по вказаному місцю, завдаючи $295552s1 шкоди силами природи ворогам, які потрапили під вибух." },
    { en = "The HK-8 Aerial Oppression Unit warps in reinforcement units from Mechagon City.", ua = "Повітряний блок гноблення HK-8 телепортує підкріплення з міста Мехаґон." },
    { en = "Damage taken by the HK-8 Aerial Oppression Unit increased by $s1% for $d.", ua = "Шкода, якої зазнає Повітряний блок гноблення HK-8, підвищена на $s1% на $d." },
    { en = "Inflicts $s1 Nature damage and Stuns enemies for $d.", ua = "Завдає $s1 шкоди від сил природи й оглушує ворогів на $d." },
    { en = "Teleports trespassers to a really inconvenient location.", ua = "Телепортує порушників у вкрай незручне місце." },
    { en = "Spinning buzz saws rip and tear at any target within $A1 yards, inflicting $s2 Physical damage and knocking them back.", ua = "Обертові дискові пилки шматують і рвуть будь-яку ціль у межах $A1 м, завдаючи $s2 фізичної шкоди й відкидаючи її." },
    { en = "The caster charges to a random opponent's location, inflicts $s2 Physical damage and launches all enemies within $A1 yards into the air and reduces their movement speed by $s3% for $d..", ua = "Закляттяр кидається до місця випадкового супротивника, завдає $s2 фізичної шкоди й підкидає в повітря всіх ворогів у межах $A1 м, знижуючи їхню швидкість пересування на $s3% на $d." },
    { en = "Upon reaching 100 energy, Gnomercy 4.U. charges in the direction of a random enemy, inflicting $283422s2 Physical damage and knocking back all enemies in it's path.\n\n\n\nWhen the bot impacts with the arena wall it is stunned for $283640d and causes $@spellname1216431 to be launched into nearby locations.", ua = "Після досягнення 100 енергії Ґномосердя 4.У. кидається в напрямку випадкового ворога, завдаючи $283422s2 фізичної шкоди й відкидаючи всіх ворогів на своєму шляху.\n\n\n\nКоли бот врізається у стіну арени, його оглушує на $283640d, і він розкидає по сусідніх місцинах кілька $@spellname1216431." },
    { en = "Slams into the ground, inflicting $s1 Physical damage to all players every $1215102t1 sec for $1215102d.", ua = "Врізається в землю, завдаючи $s1 фізичної шкоди всім гравцям щосекунди ($1215102t1) протягом $1215102d." },
    { en = "Launches B.4.T.T.L.3. Mine at player's location, inflicting $1215039s1 Fire damage to players within $1215039a1 yards and leaving behind B.4.T.T.L.3. Mine.", ua = "Запускає міну Б.І.Й.К.А. на місце гравця, завдаючи $1215039s1 шкоди вогнем гравцям у межах $1215039a1 м і лишаючи після себе міну Б.І.Й.К.А." },
    { en = "Upon reaching 100 energy, Platinum Pummeler applies thick plates of platinum armor onto itself, reduce all damage taken by $s1%. This effect stacks.\n\n\n\nPlatinum Plating is vulnerable to Piston Smashers.", ua = "Після досягнення 100 енергії Платиновий Гамселювач накладає на себе товсті пластини платинової броні, знижуючи всю отримувану шкоду на $s1%. Цей ефект складається.\n\n\n\nПлатинове Покриття вразливе до Поршневих Трощителів." },
    { en = "Pummels the target, inflicts $s1 Physical damage to all enemies within $a1 yards of impact.", ua = "Гамселить ціль, завдаючи $s1 фізичної шкоди всім ворогам у межах $a1 м від удару." },
    { en = "The defeated combatant unleashes its remaining energy in an electrical storm, inflicting $1216446s1 Nature damage to all players every $t1 sec and increasing their Nature damage taken by 20%. This effect stacks.", ua = "Переможений боєць вивільняє рештки своєї енергії в електричній бурі, завдаючи $1216446s1 шкоди від сил природи всім гравцям щосекунди ($t1) і підвищуючи отримувану ними шкоду від сил природи на 20%. Цей ефект складається." },
    { en = "Massive hydraulic hammers inflict $s1 Physical damage and stunning any players that come within $A1 yards.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nSmashing into the Platinum Pummeler while it has $@spellname282801 shatters the plating, stunning it for $282801d and causing the Piston Smasher to become inactive for $294645d.]", ua = "Масивні гідравлічні молоти завдають $s1 фізичної шкоди й оглушують усіх гравців, що наближаються на $A1 м.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nЗіткнення з Платиновим Гамселювачем, поки на ньому діє $@spellname282801, розколює покриття, оглушуючи його на $282801d і деактивуючи Поршневий Трощитель на $294645d.]" },
    { en = "The caster vents massive jets of flame from their core, inflicting $291949s1 Fire damage to all players outside of cover every $t sec for $d.\n\n\n\nThis also heats Junk Cubes.", ua = "Закляттяр випускає зі свого ядра потужні струмені полум'я, завдаючи $291949s1 шкоди вогнем усім гравцям, що поза укриттям, щосекунди ($t) протягом $d.\n\n\n\nЦе також розжарює Кубики Брухту." },
    { en = "Junk Cubes explode when sufficiently heated, inflicting $s1 Fire damage and knocking back all players within $A1 yards.", ua = "Достатньо розжарившись, Кубики Брухту вибухають, завдаючи $s1 шкоди вогнем і відкидаючи всіх гравців у межах $A1 м." },
    { en = "A fiery bite inflicts $s2 Fire damage every $t2 sec for $d. This effect stacks.\n\n\n\nThe burning wound explodes when dispelled, inflicting $294961s1 Fire damage to all players.", ua = "Вогняний укус завдає $s2 шкоди вогнем щосекунди ($t2) протягом $d. Цей ефект складається.\n\n\n\nПри розвіюванні палаюча рана вибухає, завдаючи $294961s1 шкоди вогнем усім гравцям." },
    { en = "The caster leaps towards random players, heating Junk Cubes and inflicting $292035s1 Fire damage to all enemies within $292035A1 yards of the impact.", ua = "Заклинач стрибає до випадкових гравців, розжарюючи Кубики Брухту й завдаючи $292035s1 шкоди вогнем усім ворогам у радіусі $292035A1 м від місця падіння." },
    { en = "Gnomish Flying Claws drop Junk Cubes from above, inflicting $s1 Physical damage and knocking back all players within $A1 yards.", ua = "Гномські Літальні Кігті скидають згори Кубики Брухту, завдаючи $s1 фізичної шкоди й відкидаючи всіх гравців у межах $A1 м." },
    { en = "Activates a nearby Flame Cannon, causing it to spew flame in multiple directions for $285437d, inflicting $285443s1 Fire damage to all players caught in the flames every $285443t1 sec for $285443d.\n\n\n\nFlammable objects may be caught on fire.", ua = "Активує найближчу Полум'яну гармату, через що вона вивергає полум'я в кількох напрямках протягом $285437d, завдаючи $285443s1 шкоди вогнем усім гравцям у полум'ї кожні $285443t1 сек протягом $285443d.\n\n\n\nЗаймисті об'єкти можуть загорітися." },
    { en = "Launches a blade that bounces around the garden, inflicting $s1 Physical damage.", ua = "Запускає лезо, що відскакує по саду, завдаючи $s1 фізичної шкоди." },
    { en = "Unleashes bolts of lightning at a target, inflicting $294860s1 Nature damage every $294855t1 sec for $d.", ua = "Випускає блискавки по цілі, завдаючи $294860s1 шкоди від сил природи кожні $294855t1 сек протягом $d." },
    { en = "Upon death the Inconspicuous Plant begins to spew flammable fluid into the air. When hit with a $@spellname285443, the gout erupts into a $@spellname294869.", ua = "Після загибелі Непримітна Рослина починає розбризкувати в повітря займисту рідину. Коли в неї влучає $@spellname285443, струмінь спалахує в $@spellname294869." },
    { en = "Lobs a pulse grenade at a target's location, inflicting $s1 Nature damage to anyone within $A1 yards and disorienting them for $d.", ua = "Кидає на місце цілі імпульсну гранату, завдаючи $s1 шкоди від сил природи всім у межах $A1 м і дезорієнтуючи їх на $d." },
    { en = "Periodically spews forth flaming globs of oil that impact nearby, inflicting $s1 Fire  damage to anyone within $a1 yards of the impact.", ua = "Періодично вивергає палаючі згустки нафти, що падають поряд, завдаючи $s1 шкоди вогнем усім у межах $a1 м від місця удару." },
    { en = "Inflicts $s1 Nature damage to all players.\n\n\n\nThis attack is only used by King Mechagon whenever he is not actively engaged in melee combat.", ua = "Завдає $s1 шкоди від сил природи всім гравцям.\n\n\n\nКороль Мехаґон застосовує цю атаку лише тоді, коли не бере активної участі в ближньому бою." },
    { en = "Unleashes a charged burst at his current target, inflicting $s1 Nature damage.", ua = "Вивільняє по поточній цілі заряджений залп, завдаючи $s1 шкоди від сил природи." },
    { en = "Unleashes a beam of lightning, inflicting $s1 Nature damage every $t1 sec to anyone under King Mechagon.  \n\n\n\nIn addition, a pulse of lightning is unleashed every $291626t2 sec for $291626d, inflicting $296331s1 Nature damage to all players.", ua = "Вивільняє промінь блискавки, завдаючи $s1 шкоди від сил природи щосекунди ($t1) усім, хто стоїть під Королем Мехаґоном.\n\n\n\nКрім того, щосекунди ($291626t2) протягом $291626d вивільняється імпульс блискавки, завдаючи $296331s1 шкоди від сил природи всім гравцям." },
    { en = "Touching an orb inflicts $s1 Nature damage, and knocks the player back.", ua = "Дотик до орба завдає $s1 шкоди від сил природи й відкидає гравця." },
    { en = "Unleashes $s5 bolts of energy towards a random players. Each bolt inflicts $s2 Nature damage and an additional $s3 Nature damage every $t3 sec for $d.  In addition, the target takes $s4% increased damage from $@spellname292267 for $d.", ua = "Вивільняє $s5 енергетичних розрядів у бік випадкових гравців. Кожен розряд завдає $s2 шкоди від сил природи й додатково $s3 шкоди від сил природи щосекунди ($t3) протягом $d. Крім того, ціль отримує на $s4% більше шкоди від $@spellname292267 протягом $d." },
    { en = "Launches a powerful electromagnet that pulls all players towards it, inflicting $s1 Nature damage to all players every $283143t2 sec for $283143d.  Players further from the device take less damage.", ua = "Запускає потужний електромагніт, що притягує до себе всіх гравців, завдаючи $s1 шкоди від сил природи всім гравцям щосекунди ($283143t2) протягом $283143d. Гравці, що далі від пристрою, отримують менше шкоди." },
    { en = "Unleashes a bolt of energy towards a player, inflicting $s2 Nature damage and an additional $291939s1 Nature damage every $t3 sec for $d to all players in a line from the caster.  In addition, the target takes $s4% increased damage from $@spellname291928 for $d.", ua = "Вивільняє в бік гравця заряд енергії, завдаючи $s2 шкоди від сил природи й додатково $291939s1 шкоди від сил природи щосекунди ($t3) протягом $d усім гравцям на лінії від закляттяра. Крім того, ціль отримує на $s4% більше шкоди від $@spellname291928 протягом $d." },
    { en = "Adjusts the location of all Plasma Orbs.  Upon arriving at their new location each orb unleashes a blast of energy, inflicting $291856s1 Nature damage to all players within $291856A1 yards.", ua = "Змінює розташування всіх Плазмових Орбів. Прибувши на нове місце, кожен орб вивільняє вибух енергії, завдаючи $291856s1 шкоди від сил природи всім гравцям у межах $291856A1 м." },
    { en = "King Mechagon takes to the air, inflicting $s2 Fire damage to all players within $A2 yards.", ua = "Король Мехаґон здіймається в повітря, завдаючи $s2 шкоди вогнем усім гравцям у межах $A2 м." },
    { en = "A portion of the watery essence splits off. It inflicts $s2% less damage and defeating it wounds Aqu'sirr.", ua = "Частина водяної есенції відколюється. Вона завдає на $s2% менше шкоди, а її знищення ранить Аку'сірра." },
    { en = "Channels dark waters into a player, inflicting $s1 Frost damage every $t1 sec for $d, pushing them back.", ua = "Спрямовує темні води в гравця, завдаючи $s1 шкоди від морозу щосекунди ($t1) протягом $d і відштовхуючи його." },
    { en = "Violently splits into three smaller elementals, reforming when they are defeated.", ua = "Бурхливо розколюється на трьох менших елементалів, відновлюючись після їхнього знищення." },
    { en = "Blasts a player with the rage of the ocean when no enemies are in melee combat, inflicting $s1 Frost damage.", ua = "Б'є гравця люттю океану, коли жоден ворог не бере участі в ближньому бою, завдаючи $s1 шкоди від морозу." },
    { en = "Slams tentacles into the ground, rooting a player in place and inflicting $s2 Shadowfrost damage every $t2 sec for $d.", ua = "Вганяє щупальця в землю, прикорінюючи гравця на місці й завдаючи $s2 шкоди від тіні й морозу щосекунди ($t2) протягом $d." },
    { en = "Inflicts $s1 Frost damage every $t1 sec for $d. Upon being dispelled, Choking Brine travels towards another player. Coming into contact with it afflicts the new target with Choking Brine.", ua = "Завдає $s1 шкоди від морозу щосекунди ($t1) протягом $d. Після розвіювання Удушлива Розсолина прямує до іншого гравця. Дотик до неї накладає Удушливу Розсолину на нову ціль." },
    { en = "Charges forward in a violent wave, inflicting $s1 Frost damage to targets struck and knocking them back.", ua = "Кидається вперед нищівною хвилею, завдаючи $s1 шкоди від морозу враженим цілям і відкидаючи їх." },
    { en = "Creates a Reinforcing Ward at the location which decreases damage taken by $267904s1% while within the Ward and removes all negative effects when entered.", ua = "Створює на місці Підкріплювальний оберіг, що зменшує отримувану шкоду на $267904s1%, поки ви всередині оберега, і знімає всі негативні ефекти з тих, хто в нього входить." },
    { en = "Interrupts while affected by Blessing of the Tempest create a Blowback at a nearby location which inflicts $267838s1 Nature damage and knocks back enemies that come in contact with it.", ua = "Якщо вас перервати під дією Благословення бурі, у сусідній точці виникає Зворотний порив, що завдає $267838s1 шкоди від сил природи та відкидає ворогів, які його торкаються." },
    { en = "Inflicts $s1 Nature damage to all enemies and increases Nature damage taken by $s2% for $d. This effect stacks.", ua = "Завдає $s1 шкоди від сил природи всім ворогам і підвищує отримувану шкоду від сил природи на $s2% на $d. Цей ефект накопичується." },
    { en = "Creates a Swiftness Ward at the location which increases Haste and movement speed by $267888s1% and grants immunity to movement impairing effects.", ua = "Створює на місці Оберіг стрімкості, що підвищує поспіх і швидкість пересування на $267888s1% та дарує несприйнятливість до ефектів, які перешкоджають руху." },
    { en = "Being interrupted causes a Blowback, creating a tornado at a nearby location.", ua = "Якщо вас перервати, виникає Зворотний порив, що породжує торнадо в сусідній точці." },
    { en = "Inflicts $s1 Physical damage to enemies in front of the caster and reduces movement speed by $s2% for $d.", ua = "Завдає $s1 фізичної шкоди ворогам перед мовцем і зменшує швидкість їхнього пересування на $s2% на $d." },
    { en = "Increases Physical damage dealt by $s1% but reduces movement speed by $s2%.", ua = "Підвищує завдану фізичну шкоду на $s1%, але зменшує швидкість пересування на $s2%." },
    { en = "The Mind Rend inflicts $s1 Shadow damage and an additional $s2 Shadow damage every $t2 sec and reduces speed by $s3% for $d.", ua = "Розрив розуму завдає $s1 шкоди від тіні та додатково $s2 шкоди від тіні кожні $t2 с і зменшує швидкість на $s3% на $d." },
    { en = "Lord Stormsong begins to Waken the Void, summoning many Awoken Void which pursue players and attempt to explode on them.", ua = "Лорд Штормосонг починає Пробуджувати Порожнечу, прикликаючи багатьох Пробуджених Порожнечі, які переслідують гравців і намагаються вибухнути біля них." },
    { en = "Lord Stormsong summons an Ancient Mindbender to control the actions of his enemies, causing the player to Surrender to the Void. Receiving sufficient damage will remove the Ancient Mindbender from its host.", ua = "Лорд Штормосонг прикликає Прадавнього Згинача розуму, щоб керувати діями своїх ворогів, через що гравець Скоряється Порожнечі. Достатня шкода вилучить Прадавнього Згинача розуму з його носія." },
    { en = "Coming in contact with the Awoken Void inflicts $s1 Shadow damage and stuns the target for $d.", ua = "Дотик до Пробудженого Порожнечі завдає $s1 шкоди від тіні та оглушує ціль на $d." },
    { en = "Inflicts $s1 Shadow damage to the primary target.", ua = "Завдає $s1 шкоди від тіні основній цілі." },
    { en = "Upon reaching full energy, Vol'zith the Whisperer pulls all players into a sunken realm, sealing them away and drowning them until they defeat the shadowy denizens within and rescue their allies.", ua = "Сповнившись енергії, Вол'зіт Шептун затягує всіх гравців у затонулий світ, замикаючи їх і топлячи, доки вони не здолають тіньових мешканців усередині та не врятують своїх союзників." },
    { en = "Calls the darkness from the abyss, creating a Manifestation of the Deep every $t1 sec for $d.", ua = "Прикликає темряву з безодні, створюючи Прояв Глибин кожні $t1 с протягом $d." },
    { en = "The Forgotten Denizen tears a fragment from the minds of all players, inflicting $s1 Shadow damage to them and restoring health to the caster.", ua = "Забутий мешканець вириває уламок із розуму всіх гравців, завдаючи їм $s1 шкоди від тіні та відновлюючи здоров'я мовцю." },
    { en = "Explodes upon death, inflicting $s1 Shadow damage to all players. This effect grants Vol'zith the Whisperer energy if the manifestation reaches it.", ua = "Вибухає по смерті, завдаючи $s1 шкоди від тіні всім гравцям. Цей ефект дарує енергію Вол'зіт Шептуну, якщо прояв до неї дістанеться." },
    { en = "Rips open a gate to the void, inflicting $269419s1 Shadow damage every $269419t1 sec and silencing all players caught within.", ua = "Розриває браму в Порожнечу, завдаючи $269419s1 шкоди від тіні кожні $269419t1 сек і змушуючи замовкнути всіх гравців, що опинилися всередині." },
    { en = "A shadowy tentacle rises from the deep, slamming the ground and inflicting $s1 Shadow damage to targets struck.", ua = "Тіньове щупальце здіймається з глибин, гепає об землю та завдає $s1 шкоди від тіні враженим цілям." },
    { en = "Whispers a promise of power to a target, increasing their damage and healing done by $s1%. The darkness strains the body, reducing maximum health by $s4%. This effect increases over time.", ua = "Нашіптує цілі обіцянку могутності, підвищуючи завдану нею шкоду й зцілення на $s1%. Темрява виснажує тіло, зменшуючи максимальне здоров'я на $s4%. Цей ефект посилюється з часом." },
    { en = "The Sunken Denizen moves slowly and swings mighty attacks.", ua = "Затонулий мешканець рухається повільно й завдає потужних ударів." },
    { en = "A powerhouse whose movement speed is reduced by $s2%. Additionally, his melee attacks cause knockback.", ua = "Силач, чия швидкість пересування зменшена на $s2%. Крім того, його удари в ближньому бою відкидають." },
    { en = "Hurls a hook at his current target that catches the first enemy in front of the boss, inflicting $257431s2 Physical damage and pulls the target to the boss.", ua = "Жбурляє гак у свою поточну ціль, що чіпляє першого ворога перед босом, завдає $257431s2 фізичної шкоди та притягує ціль до боса." },
    { en = "Shoots at a random enemy, inflicting $s1 Fire damage.", ua = "Стріляє у випадкового ворога, завдаючи $s1 шкоди вогнем." },
    { en = "A cresting wave of destruction surges over enemies in a line in front of the caster, dealing $257292s1 Physical damage and stunning them for $257292d.", ua = "Гребінь хвилі руйнування накочується на ворогів у лінію перед заклинателем, завдаючи $257292s1 фізичної шкоди й приголомшуючи їх на $257292d." },
    { en = "Smashes the ground, inflicting $s1 Physical damage and knocking back enemies within $A1 yards and $s2 Physical damage to everyone.", ua = "Гепає об землю, завдаючи $s1 фізичної шкоди й відкидаючи ворогів у межах $A1 м, а також $s2 фізичної шкоди всім." },
    { en = "Increases his movement speed by $257650s1% every $t1 sec.\n\n\n\nLeading the boss over Heavy Ordinance removes this buff for a short time.", ua = "Підвищує його швидкість пересування на $257650s1% кожні $t1 с.\n\n\n\nЯкщо провести боса понад Важкими боєприпасами, це підсилення на короткий час спадає." },
    { en = "Cannons barrage the area inflicting $s1 Arcane damage to everyone within the area, and knocking them back.", ua = "Гармати обстрілюють ділянку, завдаючи $s1 арканної шкоди всім у її межах і відкидаючи їх." },
    { en = "Turns all his anger towards one enemy and fixates on them.", ua = "Спрямовує весь свій гнів на одного ворога та зосереджується на ньому." },
    { en = "Heavy Ordnance Inflicts $s1 Arcane damage to all nearby enemies on impact and knocks them back.\n\n\n\nWalking over this ordnance detonates it, inflicting $273720s1 Arcane damage to the target and knocking them back.\n\n\n\nLeading the boss into these bombs inflicts $273721s1 Arcane damage, stunning him and increasing his damage taken by $273721s3% for $273721d.\n\n\n\nIf the ordnance is not detonated before its time expires, it explodes and inflicts $273718s1 Arcane damage to the party.", ua = "Важкі боєприпаси при влучанні завдають $s1 арканної шкоди всім ближнім ворогам і відкидають їх.\n\n\n\nЯкщо пройти по цих боєприпасах, вони детонують, завдаючи $273720s1 арканної шкоди цілі та відкидаючи її.\n\n\n\nЯкщо провести боса на ці бомби, вони завдають йому $273721s1 арканної шкоди, оглушують його та підвищують отримувану ним шкоду на $273721s3% на $273721d.\n\n\n\nЯкщо боєприпаси не детонувати до завершення їхнього часу, вони вибухають і завдають $273718s1 арканної шкоди групі." },
    { en = "Inflicts $s1 Physical damage to all enemies and pulls them to the caster.", ua = "Завдає $s1 фізичної шкоди всім ворогам і притягує їх до мовця." },
    { en = "Hurls a rope at the current target, preventing them from using spells or abilities and inflicts $s3 Physical damage every $t3 sec while pulling them towards the boss.", ua = "Жбурляє мотузку в поточну ціль, не даючи їй застосовувати закляття чи здібності, та завдає $s3 фізичної шкоди кожні $t3 с, притягуючи її до боса." },
    { en = "Fires a cannon that inflicts $s2 Arcane damage to all enemies caught in the path.", ua = "Стріляє з гармати, що завдає $s2 арканної шкоди всім ворогам на її шляху." },
    { en = "Shoots at an enemy, inflicting $s1 Physical damage.", ua = "Стріляє у ворога, завдаючи $s1 фізичної шкоди." },
    { en = "Sends the targets in a cone in front of the caster flying, inflicting $s1 Physical damage on impact and knocking them back.", ua = "Відправляє цілі в конусі перед мовцем у політ, завдаючи $s1 фізичної шкоди при падінні та відкидаючи їх." },
    { en = "Inflicts $s1 Physical damage to target enemy and increases their damage taken by 5% for $d. This effect stacks.", ua = "Завдає $s1 фізичної шкоди ворожій цілі та підвищує отримувану нею шкоду на 5% на $d. Цей ефект накопичується." },
    { en = "Marks an enemy destination for  bombardment. Inflicts $272426s1 Arcane damage to enemies nearby the impact.", ua = "Позначає ворожу ціль для бомбардування. Завдає $272426s1 арканної шкоди ворогам поблизу місця влучання." },
    { en = "Shoots a fiery slug at target player, inflicting $s1 Fire damage and additional $s2 Fire damage every $t2 sec for $d, then the missile bounces to $s3 nearby players.", ua = "Стріляє вогняним зарядом у цільового гравця, завдаючи $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 с протягом $d, після чого снаряд відскакує до $s3 ближніх гравців." },
    { en = "Upon reaching 66% and 33% health, Dread Capitan Lockwood withdraws back to her ship.", ua = "Сягнувши 66% і 33% здоров'я, Грізна Капітанка Локвуд відступає назад на свій корабель." },
    { en = "Dread Captain Lockwoods periodically calls on her subordinates to bombard players with $@spellname272426.", ua = "Грізна Капітанка Локвуд періодично закликає своїх підлеглих обстрілювати гравців за допомогою $@spellname272426." },
    { en = "Leaves behind unstable ordnance. Fire this ordnance at the Dread Ship to force the boss back onto land.\n\n\n\nCarrying unstable ordnance reduces your movement speed by $268995s1% for $d.", ua = "Лишає по собі нестабільні боєприпаси. Вистрелюйте ними по Грізному Кораблю, щоб змусити боса повернутися на сушу.\n\n\n\nНесення нестабільних боєприпасів зменшує вашу швидкість пересування на $268995s1% на $d." },
    { en = "Constantly flees from melee combat unless snared or rooted.", ua = "Постійно тікає з ближнього бою, якщо тільки не сповільнений чи знерухомлений." },
    { en = "Inflicts $s1 Arcane damage to all nearby enemies.", ua = "Завдає $s1 арканної шкоди всім ворогам поблизу." },
    { en = "When not being melee attacked, shoots at random enemies inflicting $s1 Physical damage on impact and an additional $s2 Physical damage every $t2 sec for $d.", ua = "Коли не зазнає атак у ближньому бою, стріляє по випадкових ворогах, завдаючи $s1 фізичної шкоди при влучанні та додатково $s2 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "Roiling water erupts under random enemy destinations, inflicting $257883s1 Frost damage to enemies within $257883A1 yards and knocks them into the air as well as inflicting $257883s2 Frost damage to everyone.\n\n\n\nThis ability also leaves brine pools at the destinations that continue to inflict $257886s1 Frost damage every $257886t1 sec  to enemies within them.", ua = "Вируюча вода вибухає під випадковими ворожими цілями, завдаючи $257883s1 шкоди від морозу ворогам у межах $257883A1 ярдів і підкидаючи їх у повітря, а також завдаючи $257883s2 шкоди від морозу всім.\n\n\n\nЦя здібність також лишає на цих місцях соляні калюжі, що й далі завдають $257886s1 шкоди від морозу кожні $257886t1 сек. ворогам усередині них." },
    { en = "A cresting wave of water surges over enemies in a line in front of the caster, dealing $261565s1 Frost damage.\n\n\n\nAlso leaves brine pools at the destinations that continue to inflict $257886s1 Frost damage every $257886t1 sec to enemies within them.", ua = "Гребінь водяної хвилі накочується на ворогів у лінії перед заклиначем, завдаючи $261565s1 шкоди від холоду.\n\n\n\nТакож залишає на цільових позиціях соляні калюжі, які продовжують завдавати $257886s1 шкоди від холоду кожні $257886t1 сек ворогам усередині них." },
    { en = "At full energy, conjures a wall of water that surges across the space, inflicting $276042s1 Frost damage to all enemies caught in the wave.", ua = "При повній енергії викликає водяну стіну, що накочується по всьому простору, завдаючи $276042s1 шкоди від морозу всім ворогам, захопленим хвилею." },
    { en = "A tentacle erupts from the water and crushes its prey for $280485s1 Physical damage every $t2 sec for $d.", ua = "Щупальце виривається з води й роздавлює свою здобич, завдаючи $280485s1 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "Fires cannon balls that explode on impact.", ua = "Стріляє гарматними ядрами, що вибухають при влучанні." },
    { en = "Belches a torrent of water that inflicts $s1 Frost damage on impact to nearby enemies.", ua = "Вивергає потік води, що при влучанні завдає $s1 шкоди від морозу ворогам поблизу." },
    { en = "Fires a blast of water that inflicts $s2 Frost damage to all enemies within $A2 yards.", ua = "Випускає струмінь води, що завдає $s2 шкоди від морозу всім ворогам у межах $A2 ярдів." },
    { en = "Spits putrid water at random enemies that inflicts $275014s1 Frost damage on impact and $275014s2 Frost damage every $275014t2 sec for $275014d.\n\n\n\nIf dispelled, water erupts and inflicts $275051s1 Frost damage to nearby allies and knocks them back.", ua = "Плює гнилою водою по випадкових ворогах, завдаючи $275014s1 шкоди від морозу при влучанні та $275014s2 шкоди від морозу кожні $275014t2 сек. протягом $275014d.\n\n\n\nЯкщо розвіяти, вода вибухає, завдаючи $275051s1 шкоди від морозу союзникам поблизу й відкидаючи їх назад." },
    { en = "The tentacle slams the ground, inflicting $s1 Physical damage to all players.", ua = "Щупальце б'є об землю, завдаючи $s1 фізичної шкоди всім гравцям." },
    { en = "Enemies that remain in the water for too long will be constricted by tentacles and crushed.", ua = "Вороги, що залишаються у воді надто довго, будуть обплетені щупальцями й роздавлені." },
    { en = "Continuously smashes the ground when not engaged in melee combat, inflicting $s1 Physical damage to everyone", ua = "Безперервно гатить по землі, коли не зайнятий ближнім боєм, завдаючи $s1 фізичної шкоди всім" },
    { en = "Adderis slips through the air at blinding speed, teleporting to the target location and striking all enemies along the way.", ua = "Аддеріс мчить крізь повітря зі сліпучою швидкістю, телепортуючись до цільового місця й вражаючи всіх ворогів на своєму шляху." },
    { en = "Adderis inflicts $s1 Nature damage, divided evenly amongst all targets within $A1 yards of him.", ua = "Аддеріс завдає $s1 шкоди від сил природи, рівномірно розподіленої між усіма цілями в межах $A1 ярдів від нього." },
    { en = "Aspix channels a gale force wind at a random target, pushing back all players in line with the victim.", ua = "Аспікс спрямовує штормовий вітер на випадкову ціль, відкидаючи всіх гравців, що стоять на одній лінії з жертвою." },
    { en = "Adderis winds up for a massive strike that inflicts $s1 Nature damage to all enemies within $A1 yards.", ua = "Аддеріс замахується для потужного удару, що завдає $s1 шкоди від сил природи всім ворогам у межах $A1 ярдів." },
    { en = "Aspix charges the air around the victim, causing them to release a sudden burst of $263374s1 Nature damage after $d.\n\nAny allies within $263374A1 yards of the victim will take Nature damage when this effect expires.", ua = "Аспікс заряджає повітря навколо жертви, змушуючи її вивільнити раптовий спалах, що завдає $263374s1 шкоди від сил природи через $d.\n\nБудь-які союзники в межах $263374A1 ярдів від жертви зазнають шкоди від сил природи, коли цей ефект завершиться." },
    { en = "The caster is surrounded by Arc Lightning that reflects $268851s1 Nature damage to all attackers.", ua = "Мовця оточує Дуга блискавок, що відбиває $268851s1 шкоди від сил природи всім нападникам." },
    { en = "Adderis swings their weapon so quickly that a burst of wind inflicts $s1 Nature damage to all players in front of the caster.", ua = "Аддеріс змахує своєю зброєю так швидко, що порив вітру завдає $s1 шкоди від сил природи всім гравцям перед мовцем." },
    { en = "Aspix jolts the target for $s1 Nature damage.", ua = "Аспікс уражає ціль струмом, завдаючи $s1 шкоди від сил природи." },
    { en = "Aspix unleashes a burst of electricity that inflicts $s1 Nature damage.", ua = "Аспікс вивільняє спалах електрики, що завдає $s1 шкоди від сил природи." },
    { en = "Aspix blasts the target for $s1 Nature damage.", ua = "Аспікс уражає ціль, завдаючи $s1 шкоди від сил природи." },
    { en = "Creates a dust cloud that will obscure creatures inside of it.", ua = "Створює хмару пилу, що приховує істот усередині неї." },
    { en = "The embryo within the egg is beginning to hatch. When complete, a snake will emerge and attack the players.", ua = "Зародок усередині яйця починає вилуплюватися. Коли він завершить, з нього з'явиться змія й нападе на гравців." },
    { en = "Merektha exhales Blinding Sand, inflicting $s1 Physical damage to all enemies within $A1 yards. Victims that are looking at Merektha are blinded for $269970d.", ua = "Меректа видихає Сліпучий пісок, завдаючи $s1 фізичної шкоди всім ворогам у межах $A1 ярдів. Жертви, що дивляться на Меректу, осліплені на $269970d." },
    { en = "Merektha burrows through floor, inflicting $s1 Physical damage to any players caught in her path. Victims are knocked back.", ua = "Меректа зариваєтся крізь підлогу, завдаючи $s1 фізичної шкоди всім гравцям на своєму шляху. Жертв відкидає назад." },
    { en = "The caster injects cytotoxins into the target, inflicting $o1 Nature damage over $d.", ua = "Мовець упорскує цитотоксини в ціль, завдаючи $o1 шкоди від сил природи протягом $d." },
    { en = "A potent toxin courses through your veins, inflicting $o1 Nature damage over $d.", ua = "Потужна отрута тече твоїми венами, завдаючи $o1 шкоди від сил природи протягом $d." },
    { en = "A Knot of Snakes envelopes the target, preventing any action and slowly suffocating the victim for $o1 Physical damage over $d.  The victim can be freed by killing the snakes or incapacitating them.", ua = "Клубок змій огортає ціль, не даючи їй діяти й повільно душачи жертву, що завдає $o1 фізичної шкоди протягом $d. Жертву можна звільнити, убивши змій або знешкодивши їх." },
    { en = "Players standing in a Toxic Pool take $s1 Nature damage every $t1 sec.", ua = "Гравці, що стоять у Токсичній калюжі, зазнають $s1 шкоди від сил природи кожні $t1 сек." },
    { en = "Players standing in between Galvazzt and the energy core will prevent Galvazzt from gaining energy; but will take $s1 Nature damage themselves. Further damage from $@spellname266923 is increased by $s2% for $d.", ua = "Гравці, що стоять між Ґалваззтом та енергетичним ядром, завадять Ґалваззту здобувати енергію, але самі зазнають $s1 шкоди від сил природи. Подальша шкода від $@spellname266923 збільшується на $s2% протягом $d." },
    { en = "With each release of energy, Galvazzt's damage increases $s1%.", ua = "З кожним вивільненням енергії шкода Ґалваззта збільшується на $s1%." },
    { en = "Galvazzt consumes all of their energy, inflicting $s1 Nature damage to all players.  Consuming the energy also grants Galvazzt a stack of Capacitance.", ua = "Ґалваззт поглинає всю свою енергію, завдаючи $s1 шкоди від сил природи всім гравцям. Поглинання енергії також дає Ґалваззту накопичення Ємності." },
    { en = "The caster periodically gains energy.", ua = "Мовець періодично здобуває енергію." },
    { en = "If unblocked, the energy core increases the energy level of Galvazzt.  If Galvazzt reaches 100 energy he will cast $@spellname266512.", ua = "Якщо не заблокувати, енергетичне ядро підвищує рівень енергії Ґалваззта. Коли Ґалваззт досягне 100 енергії, він застосує $@spellname266512." },
    { en = "Energizes the Avatar of Sethraliss with some of her missing life force. While energized, the Avatar will receive an additional $s1 points of healing every time they are healed by any ability.", ua = "Наснажує Аватар Сетраліс частиною її втраченої життєвої сили. Поки наснажений, Аватар отримуватиме додаткові $s1 зцілення щоразу, коли його зціляє будь-яка здібність." },
    { en = "The Heart Guardian strikes at the heart of their target, inflicting $s1 Nature damage and increasing the damage they take from all sources by $s2% for $d.", ua = "Серцевий охоронець б'є в серце своєї цілі, завдаючи $s1 шкоди від сил природи й збільшуючи шкоду, що вона зазнає з усіх джерел, на $s2% протягом $d." },
    { en = "Transforms the enemy into a snake for $d. While transformed, the victim is incapacitated, and cannot attack or cast spells.", ua = "Перетворює ворога на змію на $d. Поки перетворена, жертва знешкоджена й не може ні нападати, ні творити закляття." },
    { en = "When a Heart Guardian dies, a fragment of its energy drops to the ground. Using this fragment will give the Avatar $@spellname274149 for $274149d.", ua = "Коли Серцевий охоронець гине, фрагмент його енергії падає на землю. Використання цього фрагмента дасть Аватару $@spellname274149 на $274149d." },
    { en = "Lightning crashes down near the Heart of Sethraliss, inflicting $s1 Nature damage to all players within $A1 yards of the impact.", ua = "Блискавка б'є біля Серця Сетраліс, завдаючи $s1 шкоди від сил природи всім гравцям у радіусі $A1 м від місця влучання." },
    { en = "Taints the Avatar of Sethraliss, reducing all incoming healing taken by $s1%.", ua = "Опоганює Аватар Сетраліс, зменшуючи все вхідне зцілення на $s1%." },
    { en = "The Heart of Sethraliss unleashes a blast of energy, inflicting $o1 Nature damage over $d. to all players.", ua = "Серце Сетраліс вивільняє вибух енергії, завдаючи $o1 шкоди від сил природи всім гравцям протягом $d." },
    { en = "You are afflicted with the plague! Healing you do is reduced by $s1%.\n\nThe victim suffers $o2 Plague damage over the duration.  Multiple applications of Plague cause the damage effect to stack.", ua = "Тебе вражено чумою! Зцілення, яке ти твориш, зменшено на $s1%.\n\nЖертва зазнає $o2 шкоди від чуми протягом дії ефекту. Повторні накладення Чуми складають ефект шкоди." },
    { en = "The caster summons several Plague Toads that will chase down any healers they find and Plague them.", ua = "Заклинач прикликає кількох Чумних жаб, які переслідуватимуть будь-яких цілителів і вражатимуть їх чумою." },
    { en = "Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies. Affects up to $x1 total targets.", ua = "Жбурляє у ворога блискавку, завдаючи $s1 шкоди від сил природи, після чого вона перестрибує на сусідніх ворогів. Вражає до $x1 цілей загалом." },
    { en = "Kicking an Azerite Footbomb into the Coin-Operated Crowd Pummeler causes the footbomb to explode, removing 5 stacks of $@spellname271867.\n\n\n\nThe explosion covers the Crowd Pummeler in blazing Azerite, increasing all damage taken by $256493s1% for $256493D, stacking up to $256493u times.", ua = "Удар Азеритовою футбомбою по Монетному Натовповгамселювачу спричиняє вибух футбомби, знімаючи 5 зарядів $@spellname271867.\n\n\n\nВибух вкриває Натовповгамселювача палаючим азеритом, збільшуючи всю отримувану шкоду на $256493s1% на $256493D, складаючись до $256493u разів." },
    { en = "A timed charge detonates the Azerite Footbomb, inflicting $s1 Fire damage to enemies within $A1 yards.\n\n\n\nThe explosion covers enemies in blazing Azerite, increasing all damage taken by $256493s1% for $256493D, stacking up to $256493u times.", ua = "Часовий заряд підриває Азеритову футбомбу, завдаючи $s1 шкоди вогнем ворогам у межах $A1 метрів.\n\n\n\nВибух вкриває ворогів палаючим азеритом, збільшуючи всю отримувану шкоду на $256493s1% на $256493D, складаючись до $256493u разів." },
    { en = "The crowd throws piles of coins into the arena around the Coin-Operated Crowd Pummeler, inflicting $1217286s1 Physical damage to players within $1217286a1 yards of impact.", ua = "Натовп жбурляє купи монет на арену довкола Монетного Натовповгамселювача, завдаючи $1217286s1 фізичної шкоди гравцям у межах $1217286a1 метрів від місця падіння." },
    { en = "Emits a pulse of electricity, inflicting $s1 Nature damage instantly and $s3 Nature damage every $t3 sec for $d. Also knocks back all enemies.", ua = "Випускає імпульс електрики, миттєво завдаючи $s1 шкоди від сил природи, а також $s3 шкоди від сил природи кожні $t3 с протягом $d. Також відкидає всіх ворогів." },
    { en = "Unleashes a massive wave of electricity in front of the caster, inflicting $s1 Nature damage to enemies hit and stunning them for $d.", ua = "Вивільняє потужну хвилю електрики перед заклинателем, завдаючи $s1 шкоди від сил природи враженим ворогам і приголомшуючи їх на $d." },
    { en = "Launches explosive footbombs into the arena. After $256054D, the footbombs will trigger Timed Detonation.\n\n\n\nFootbombs punted into the Coin-Operated Crowd Pummeler trigger Blazing Azerite instead of exploding.", ua = "Запускає вибухові ножбомби в арену. Через $256054D ножбомби спрацьовують Детонацію з таймером.\n\n\n\nНожбомби, заштовхані в Монетний Натовповгамселювач, замість вибуху спрацьовують Палаючий Азерит." },
    { en = "Upon reaching 100 energy, the Pummeler activates a powerful magnet, drawing in all pile of gold within $1217533a1 yards, gaining a stack of $@spellname271867 for each coin pile consumed.", ua = "Сягнувши 100 енергії, Натовповгамселювач вмикає потужний магніт, притягуючи всі купи золота в радіусі $1217533a1 м, і отримує заряд $@spellname271867 за кожну поглинену купу монет." },
    { en = "Damage inflicted increased by $s1% for every pile of gold consumed by the Coin-Operated Crowd Pummeler.", ua = "Завдана шкода збільшується на $s1% за кожну купу золота, поглинуту Монетним Натовповгамселювачем." },
    { en = "Kick an Azerite Footbomb, sending it flying.", ua = "Удар по Азеритовій футбомбі, що відправляє її в політ." },
    { en = "Earthrager unleashes its stored energy, inflicting $s1 Nature damage to all players.", ua = "Землелют вивільняє накопичену енергію, завдаючи $s1 шкоди від сил природи всім гравцям." },
    { en = "Azerokk slams the ground, inflicting $s2 Physical damage and knocking up players in a cone in front of the caster.", ua = "Азерокк гатить об землю, завдаючи $s2 фізичної шкоди й підкидаючи гравців у конусі перед заклиначем." },
    { en = "Jagged rock slices into the player with every melee attack, inflicting $s1 Physical damage every $T1 sec for $D. This effect stacks.", ua = "Гостре каміння розтинає гравця з кожною атакою ближнього бою, завдаючи $s1 фізичної шкоди кожні $T1 с протягом $D. Цей ефект складається." },
    { en = "Place a Fracking Totem, which incapacitates your current target for $D. Can only be used against Earthragers. This effect breaks when the target is damaged.", ua = "Установлює Тотем фрекінгу, який знешкоджує твою поточну ціль на $D. Можна використовувати лише проти Землелютів. Цей ефект переривається, коли ціль зазнає шкоди." },
    { en = "An Earthrager selects a random player and pursues them relentlessly.", ua = "Землелют обирає випадкового гравця й невпинно його переслідує." },
    { en = "Impact from Resonant Quake triggers the Azerite energy within, causing an eruption of Azerite energy, inflicting $s1 Arcane damage to all players and additional $s2 Arcane damage every $t2 sec for $d.", ua = "Удар від Резонансного землетрусу пробуджує азеритову енергію всередині, спричиняючи виверження азеритової енергії, що завдає $s1 арканної шкоди всім гравцям і додаткові $s2 арканної шкоди кожні $t2 с протягом $d." },
    { en = "Calls forth an Earthrager to assist the caster.", ua = "Прикликає Землелюта на допомогу заклиначу." },
    { en = "Infuses an Earthrager with Azerite, healing it for $271698s1% of its health every $271698t1 sec for $271698d. The Earthrager becomes empowered when the infusion finishes, freeing it from crowd control and increasing its damage done by $s6% and increasing their damage taken by $s7%. \n\n\n\nAlso causes it to pulses Azerite energy every $t1 sec, inflicting $1213142s1 Arcane damage to all players.\n\n\n\nPrefers targets not under the effects of Fracking Totem or other crowd control effects.", ua = "Наповнює Землелюта азеритом, зцілюючи його на $271698s1% здоров'я кожні $271698t1 с протягом $271698d. Коли вливання завершується, Землелют набуває могутності, що звільняє його від ефектів контролю та збільшує завдану ним шкоду на $s6% і отримувану ним шкоду на $s7%.\n\n\n\nТакож змушує його випромінювати азеритову енергію кожні $t1 с, завдаючи $1213142s1 арканної шкоди всім гравцям.\n\n\n\nНадає перевагу цілям, які не перебувають під дією Тотема фрекінгу чи інших ефектів контролю." },
    { en = "Azerokk resonates with power, causing a quake that inflicts $471894s1 Nature damage to all players and reduces their movement speed by $471894s2% for $471894d.\n\n\n\nAlso causes $@spellname258628 on Earthragers.", ua = "Азерокк резонує силою, спричиняючи землетрус, що завдає $471894s1 шкоди від сил природи всім гравцям і зменшує їхню швидкість пересування на $471894s2% на $471894d.\n\n\n\nТакож спричиняє $@spellname258628 на Землелютах." },
    { en = "Fires a burst of sprayer propellant at a player's location for $d, inflicting $260103s1 Nature damage every $1217672t1 sec and pushing them away from the caster.\n\n\n\nPatches of Azerite Catalyst will also be pushed away.", ua = "Випускає струмінь палива розпилювача на місце гравця протягом $d, завдаючи $260103s1 шкоди від сил природи кожні $1217672t1 с і відштовхуючи його від заклинача.\n\n\n\nЛатки Азеритового каталізатора також буде відштовхнуто." },
    { en = "Sprays up to $259852I players with a nasty chemical, inflicting $s1 Nature damage every $t1 sec for $D.", ua = "Обприскує до $259852I гравців гидкою хімікалією, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $D." },
    { en = "Fires a stream of Azerite Catalyst at an enemy for $D, setting the ground ablaze. The flames inflict $259533s1 Fire damage every $259533t1 sec.", ua = "Випускає струмінь Азеритового каталізатора у ворога протягом $D, підпалюючи землю. Полум'я завдає $259533s1 шкоди вогнем кожні $259533t1 с." },
    { en = "Shoots a glob of Searing Reagent at an enemy, inflicting $s1 Fire damage.", ua = "Жбурляє згусток Пекучого реагенту у ворога, завдаючи $s1 шкоди вогнем." },
    { en = "A pipe overflows with Azerite Catalyst, spraying a line of the toxic stuff into the arena.", ua = "Труба переповнюється Азеритовим каталізатором, розбризкуючи смугу токсичної речовини на арену." },
    { en = "Jumps to a location within $262435A1 yards of a player.", ua = "Стрибає на місце в межах $262435A1 метрів від гравця." },
    { en = "Calls several Big Red Rockets down from the sky, inflcting $s1 Fire damage on impact and $s2 Fire damage every $t2 sec for $D.", ua = "Прикликає кілька Великих червоних ракет з неба, завдаючи $s1 шкоди вогнем під час удару й $s2 шкоди вогнем кожні $t2 с протягом $D." },
    { en = "A B.O.O.M.B.A. drone launches a salvo of Micro Missiles, inflicting $s1 Fire damage to players within $a1 yards of each missile's impact.", ua = "Дрон B.O.O.M.B.A. запускає залп Мікроракет, завдаючи $s1 шкоди вогнем гравцям у межах $a1 метрів від місця удару кожної ракети." },
    { en = "Fires a homing missile that chases a player. On impact, or after $260835d, the missile explodes, inflicting $260838s1 Fire damage immediately and $260838s2 Fire damage every $260838t2 sec for $260838d to all players within $260838A1 yards of the missile. The missile's speed increases as it travels.", ua = "Випускає самонавідну ракету, яка переслідує гравця. Під час удару або після $260835d ракета вибухає, миттєво завдаючи $260838s1 шкоди вогнем і $260838s2 шкоди вогнем кожні $260838t2 с протягом $260838d усім гравцям у межах $260838A1 метрів від ракети. Швидкість ракети зростає під час польоту." },
    { en = "Flies through the air and impacts a player's location, inflicting $270926s1 Physical damage to targets within $270926A1 yards, and $s1 Physical damage to all targets beyond $270926A1 yards.\n\n\n\nAny Big Red Rocket struck by Drill Smash will explode, removing a stack of Configuration: Drill.", ua = "Пролітає в повітрі й б'є по місцю гравця, завдаючи $270926s1 фізичної шкоди цілям у межах $270926A1 метрів і $s1 фізичної шкоди всім цілям далі ніж $270926A1 метрів.\n\n\n\nБудь-яка Велика червона ракета, вражена Ударом свердла, вибухне, знімаючи заряд Конфігурації: свердло." },
    { en = "Fires a missile at the current threat target, inflicting $s1 Fire damage.", ua = "Випускає ракету в поточну ціль за загрозою, завдаючи $s1 шкоди вогнем." },
    { en = "Spins in place and fires a hail of bullets, inflicting $s1 Physical damage every $t1 sec to all players in front of Mogul Razdunk.", ua = "Обертається на місці й випускає град куль, завдаючи $s1 фізичної шкоди кожні $t1 с усім гравцям перед Магнатом Раздунком." },
    { en = "Inflicts $s1 Fire damage on impact.", ua = "Завдає $s1 шкоди вогнем при влучанні." },
    { en = "Elder Leaxa's abilities afflict players with the Taint of G'huun. This effect inflicts $s2 Shadow damage every second and absorbs $s1 of all healing received. This effect stacks.", ua = "Здібності Старійшини Ліакси вражають гравців Скверною Ґ'хууна. Цей ефект завдає $s2 шкоди від тіні щосекунди й поглинає $s1 усього отриманого зцілення. Цей ефект складається." },
    { en = "Elder Leaxa blasts a player, inflicting $s1 Shadow damage.", ua = "Старійшина Ліакса вражає гравця, завдаючи $s1 шкоди від тіні." },
    { en = "Elder Leaxa teleports to a random player and begins to cast Sanguine Feast. This effect inflicts $s1 Shadow damage to all players within $A1 yards.", ua = "Старійшина Ліакса телепортується до випадкового гравця й починає творити Кривавий бенкет. Цей ефект завдає $s1 шкоди від тіні всім гравцям у межах $A1 метрів." },
    { en = "Elder Leaxa creates a Blood Effigy in her image.", ua = "Старійшина Ліакса створює Кривавий образ за своєю подобою." },
    { en = "Elder Leaxa summons corruption that moves forward, inflicting $261498s1 Nature damage to all players in its path every $261498t1 sec.", ua = "Старійшина Ліакса прикликає скверну, що рухається вперед, завдаючи $261498s1 шкоди від сил природи всім гравцям на своєму шляху кожні $261498t1 с." },
    { en = "Grows into a Blood Tick after $d.", ua = "Виростає у Кровопивку через $d." },
    { en = "Charges at a target, inflicting $M1 Physical damage and knocking back all targets struck.", ua = "Кидається на ціль, завдаючи $M1 фізичної шкоди й відкидаючи всі вражені цілі." },
    { en = "Tears into the victim, causing them to bleed for $m1 Physical damage over $d1. This effect stacks.", ua = "Роздирає жертву, змушуючи її стікати кров'ю на $m1 фізичної шкоди протягом $d1. Цей ефект складається." },
    { en = "Throws a tantrum upon reaching 100 energy, periodically inflicts $M1 Physical damage to all enemies.", ua = "Сягнувши 100 енергії, впадає в шал, періодично завдаючи $M1 фізичної шкоди всім ворогам." },
    { en = "Explodes on death, inflicting Shadow damage to all enemies.", ua = "Вибухає після смерті, завдаючи шкоди від тіні всім ворогам." },
    { en = "Vomits violently, inflicts $s1 Shadow damage to all targets in a cone in front of the caster and expels Blood Tick larvae.", ua = "Жорстоко блює, завдаючи $s1 шкоди від тіні всім цілям у конусі перед заклиначем і виштовхуючи личинок Кровопивок." },
    { en = "Cragmaw's abilities shed Blood Tick Larvae from it's body.", ua = "Здібності Скелепащі скидають з його тіла личинок кров'яного кліща." },
    { en = "After $259718d1 Zancha ruptures the earth beneath the target, knocking up and inflicting $s1 Physical damage to players and destroying spore pods within $A2 yards.", ua = "Через $259718d1 Занча розриває землю під ціллю, підкидаючи гравців у повітря, завдаючи їм $s1 фізичної шкоди та знищуючи спорові капсули в межах $A2 ярдів." },
    { en = "Zancha slams the ground, inflicting $s1 Physical and destroying any spore pods in front of him.", ua = "Занча гамселить по землі, завдаючи $s1 фізичної шкоди та знищуючи всі спорові капсули перед собою." },
    { en = "$s1 Plague damage inflicted every $t1 sec for $d1.", ua = "$s1 шкоди від чуми кожні $t1 сек. протягом $d1." },
    { en = "Upon reaching 100 energy, Zancha forces all remaining spore pods to burst. Inflicts $s2 Plague damage to all players and applies $@spellname273226 to all players for each active spore pod.", ua = "Досягнувши 100 енергії, Занча змушує всі рештки спорових капсул луснути. Завдає $s2 шкоди від чуми всім гравцям і накладає $@spellname273226 на всіх гравців за кожну активну спорову капсулу." },
    { en = "Zancha summons spore pods throughout the area. Coming into contact with a spore pod will cause it to erupt, inflicting $259714s1 Plague damage and applying $@spellname273226 to players within $259668a1 yards", ua = "Занча призиває спорові капсули по всій місцевості. Дотик до спорової капсули змушує її луснути, завдаючи $259714s1 шкоди від чуми та накладаючи $@spellname273226 на гравців у межах $259668a1 ярдів" },
    { en = "Volatile Pods grow throughout the area and burst, radiating spores outwards. Players that come into contact with a spore suffer $259714s1 Plague damage and have $@spellname273226 applied to them.", ua = "По всій місцевості ростуть Нестабільні капсули, що лускають, розкидаючи спори навсібіч. Гравці, які торкнулися спори, зазнають $259714s1 шкоди від чуми, і на них накладається $@spellname273226." },
    { en = "Titan Keeper Hezrel smites an enemy for Holy Damage.", ua = "Хранитель-титан Гезрел уражає ворога Святою шкодою." },
    { en = "The Unbound Abomination absorbs all damage taken, converting it into Blood Energy. Upon reaching full energy, all of the blood is consumed, creating several Blood Visages.", ua = "Розкута потвора поглинає всю отриману шкоду, перетворюючи її на Кров'яну енергію. Досягнувши повної енергії, вона поглинає всю кров, створюючи кількох Кривавих личин." },
    { en = "Pools of Vile Expulsion periodically coalesce into Rotting Spores that move towards players. Each spore inflicts $s1 Shadow damage to any player it comes into contact with, instantly killing the spore.\n\n\n\nWhenever a Rotting Spore dies, a pool of Vile Expulsion is created at the spore's location.", ua = "Калюжі Мерзенного вивергу періодично зливаються в Гнильні спори, що рухаються до гравців. Кожна спора завдає $s1 шкоди від тіні будь-якому гравцеві, з яким стикається, миттєво гинучи при цьому.\n\n\n\nЩоразу, коли Гнильна спора гине, на її місці утворюється калюжа Мерзенного вивергу." },
    { en = "The Unbound Abomination expels corruption towards a random player, inflicting $s1 Shadow damage in a cone.\n\n\n\nIn addition, pockets of corruption are created, inflicting $269838s1 Shadow damage to all players in the area.", ua = "Розкута потвора вивергає скверну в напрямку випадкового гравця, завдаючи $s1 шкоди від тіні в конусі.\n\n\n\nКрім того, утворюються осередки скверни, що завдають $269838s1 шкоди від тіні всім гравцям у цій місцевості." },
    { en = "The Unbound Abomination corrupts all players, inflicting $s1 Shadow damage every $t1 sec for $d. This effect stacks.", ua = "Розкута потвора опоганює всіх гравців, завдаючи $s1 шкоди від тіні кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Titan Keeper Hezrel purges a Blood Visage, stunning it for $d. This effect inflicts $s2% damage every $t2 sec and $269418s1 Holy damage when it expires.", ua = "Хранитель-титан Гезрел очищає Криваву личину, приголомшуючи її на $d. Цей ефект завдає $s2% шкоди кожні $t2 сек. і $269418s1 Святої шкоди, коли спливає." },
    { en = "When a Blood Visage dies, the link between it and the Unbound Abomination is severed, inflicting $s1% of the abomination's maximum health.", ua = "Коли Кривава личина гине, зв'язок між нею та Розкутою потворою розривається, завдаючи шкоди в розмірі $s1% максимального здоров'я потвори." },
    { en = "Titan Keeper Hezrel attempts to cleanse a player and their allies within $A1 yards, removing Putrid Blood from them. In addition, this effect removes all Vile Expulsion within $A1 yards.", ua = "Хранитель-титан Гезрел намагається очистити гравця та його союзників у межах $A1 ярдів, знімаючи з них Гнилу кров. Крім того, цей ефект знімає весь Мерзенний виверг у межах $A1 ярдів." },
    { en = "Whenever a Buzzing Drone dies nearby The Sand Queen, she enrages and gains $s2% damage done and $s1% Haste for $d. This effect stacks.", ua = "Щоразу, коли Дзизкотливий дрон гине поблизу Піщаної королеви, вона впадає в лють і отримує $s2% до завданої шкоди та $s1% Поспіху на $d. Цей ефект накопичується." },
    { en = "Upon reaching 30% remaining health, The Sand Queen enrages, gaining $s1% haste and $s3% damage done.", ua = "Коли в Піщаної королеви лишається 30% здоров'я, вона впадає в лють, отримуючи $s1% Поспіху та $s3% до завданої шкоди." },
    { en = "Bites cover an enemy, inflicting $s1 Physical damage immediately, with an additional $s2 Physical damage every $t2 sec for $d.", ua = "Укуси вкривають ворога, миттєво завдаючи $s1 фізичної шкоди, а також додатково $s2 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "Disappears beneath the sand, exploding up underneath a player. This eruption inflicts $s1 Nature damage and knocks all targets upwards.", ua = "Зникає під піском і вибухає з-під гравця. Цей вибух завдає $s1 шкоди від сил природи та підкидає всі цілі вгору." },
    { en = "Creates a large sandstorm, inflicting $257580s1 Nature damage to all enemies every $t1 sec for $d.", ua = "Створює велику піщану бурю, що завдає $257580s1 шкоди від сил природи всім ворогам кожні $t1 сек. протягом $d." },
    { en = "Calls forth sand traps beneath all players for $d. Coming into contact with a sand trap inflicts $s1 Nature damage, knocking the target into the air and stunning them for $d.", ua = "Призиває піщані пастки під усіх гравців на $d. Дотик до піщаної пастки завдає $s1 шкоди від сил природи, підкидаючи ціль у повітря та приголомшуючи її на $d." },
    { en = "Hurls a smoke bomb to the ground, stunning players for $d and opening several prison cells to assist the caster.", ua = "Жбурляє на землю димову бомбу, приголомшуючи гравців на $d і відчиняючи кілька тюремних камер, щоб покликати підмогу творцеві." },
    { en = "Absorbs $s1 damage on the caster. While this effect remains, the caster is unable to be interrupted.", ua = "Поглинає $s1 шкоди, завданої творцеві. Поки цей ефект триває, творця неможливо перервати." },
    { en = "Leaps to a target, pinning them to the ground. While the target is pinned, they suffer $s3 Physical damage every $t3 sec for $d.", ua = "Стрибає на ціль, притискаючи її до землі. Поки ціль притиснута, вона зазнає $s3 фізичної шкоди кожні $t3 сек протягом $d." },
    { en = "Channels a rallying cry, applying a stack of $@spellname257956 every $t2 sec for $d. Reduces damage taken by $s3% while channeling.", ua = "Творить заклик-гасло, накладаючи стос $@spellname257956 кожні $t2 сек. протягом $d. Знижує отриману шкоду на $s3% під час творення." },
    { en = "Damage done increased by $s1% for $d. This effect stacks.", ua = "Завдана шкода збільшена на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Hurls a makeshift shiv at a target, inflicting $s1 Nature damage and causing the target to suffer $s2 Nature damage every $t2 sec for $d. This effect reduces movement speed by $s3%.", ua = "Жбурляє в ціль саморобну заточку, завдаючи $s1 шкоди від сил природи та змушуючи ціль зазнавати $s2 шкоди від сил природи кожні $t2 сек. протягом $d. Цей ефект знижує швидкість пересування на $s3%." },
    { en = "Hurls daggers at all players within line of sight, inflicting $s1 Physical damage and knocking them back.", ua = "Жбурляє кинджали в усіх гравців у межах прямої видимості, завдаючи $s1 фізичної шкоди та відкидаючи їх назад." },
    { en = "Releases a mighty howl, causing players within $A1 yds to run in fear for $d.", ua = "Видає могутнє виття, змушуючи гравців у межах $A1 ярдів тікати в страху протягом $d." },
    { en = "Circles of flame erupt underneath targets, inflicting $s1 Fire damage to all players struck.", ua = "Під цілями спалахують кола полум'я, завдаючи $s1 шкоди вогнем усім враженим гравцям." },
    { en = "Marks a player with a burning fuse, causing them to erupt inflicting $s1 Fire damage every $257028t1 sec for $257028d.", ua = "Позначає гравця палаючим ґнотом, через що той вибухає, завдаючи $s1 шкоди вогнем кожні $257028t1 сек. протягом $257028d." },
    { en = "Blasts out a cone of flames in front of the caster, inflicting $s1 Fire damage.", ua = "Випускає конус полум'я перед творцем, завдаючи $s1 шкоди вогнем." },
    { en = "If any barrel of munitions come into contact with fire, it will explode after $s2 sec, inflicting $s1 Fire damage to all targets within $A1 yds.", ua = "Якщо будь-яка бочка з боєприпасами стикається з вогнем, вона вибухає через $s2 сек., завдаючи $s1 шкоди вогнем усім цілям у межах $A1 ярдів." },
    { en = "Marks player for $@spellname256128. After $256105d, shots ring out and inflict $s1 Fire damage to all players within $A1 yds.", ua = "Позначає гравця для $@spellname256128. Через $256105d лунають постріли й завдають $s1 шкоди вогнем усім гравцям у радіусі $A1 м." },
    { en = "Loads his gun with fiery Azerite incendiary rounds, causing targets struck to suffer $256201s1 Fire damage every $256201t1 sec for $256201d.", ua = "Заряджає свою зброю вогняними азеритовими запальними набоями, через що вражені цілі зазнають $256201s1 шкоди вогнем кожні $256201t1 сек. протягом $256201d." },
    { en = "Loads his gun with heavy Azerite blast rounds, pushing back targets struck.", ua = "Заряджає свою зброю важкими азеритовими вибуховими набоями, що відкидають вражені цілі." },
    { en = "Fires a Heartstopper round at each player. Venom courses through the veins each time the target moves. If it reaches their heart, the target is stunned for $256474d.", ua = "Випускає по кожному гравцеві набій-Серцезупин. Отрута біжить по венах щоразу, коли ціль рухається. Якщо вона досягає серця, ціль приголомшується на $256474d." },
    { en = "Being struck by Incendiary Rounds inflicts $s1 Fire damage every $t1 sec for $d. This effect stacks.", ua = "Влучання Запальними набоями завдає $s1 шкоди вогнем кожні $t1 сек. протягом $d. Цей ефект накопичується." },
    { en = "Aims at a player, firing a precise round after $256038d and striking the first player in the line. This shot inflicts $s1 Physical damage and increases damage taken from $@spellname256044 by $s2% for $d.", ua = "Прицілюється в гравця, через $256038d робить точний постріл і вражає першого гравця на лінії. Цей постріл завдає $s1 фізичної шкоди та збільшує шкоду, отриману від $@spellname256044, на $s2% протягом $d." },
    { en = "Blasts players along burning lanes, inflicting $s1 Fire damage.", ua = "Обстрілює гравців уздовж палаючих смуг, завдаючи $s1 шкоди вогнем." },
    { en = "A nearby cannon fires a massive blast, inflicting $s1 Fire damage in a frontal cone and knocking back targets struck.", ua = "Поблизу гармата робить потужний постріл, завдаючи $s1 шкоди вогнем у фронтальному конусі та відкидаючи вражені цілі." },
    { en = "Strikes the enemy with razor-sharp nettles, inflicting $s1 Physical damage and leaves a grievous wound, inflicting  $s2 Physical damage every $t2 sec until the target is healed above $s3% of their maximum health.", ua = "Б'є ворога гострими, як лезо, кропивними жалами, завдаючи $s1 фізичної шкоди та лишаючи тяжку рану, яка завдає $s2 фізичної шкоди кожні $t2 сек., поки ціль не вилікується вище $s3% свого максимального здоров'я." },
    { en = "The caster is empowered by the focusing iris, increasing their energy by $s1 every $t1 sec. At 100 Energy, the caster casts $@spellname260773.", ua = "Творець підсилений фокусувальною ірисою, що збільшує його енергію на $s1 кожні $t1 сек. При 100 одиницях енергії творець застосовує $@spellname260773." },
    { en = "Releases a bust of dark energy, inflicting $s1 Shadow damage to all enemies.", ua = "Вивільняє спалах темної енергії, завдаючи $s1 шкоди від тіні всім ворогам." },
    { en = "The caster manipulates the soul of its target, charming them.", ua = "Заклинатель маніпулює душею своєї цілі, причаровуючи її." },
    { en = "Sister Solena emits a dreadful aura, reducing healing done by $268080s1%.", ua = "Сестра Солена випромінює моторошну ауру, зменшуючи зцілення на $268080s1%." },
    { en = "Sister Malady emits a dreadful aura, inflicting $268086s1 Shadow damage every $268086t1 sec. This effect stacks. Stacks are removed when moving.", ua = "Сестра Маладі випромінює моторошну ауру, завдаючи $268086s1 шкоди від тіні кожні $268086t1 сек. Цей ефект накопичується. Заряди знімаються під час руху." },
    { en = "Sister Briar wraps herself in a thorny aura, inflicting $268126s1 Physical damage every time she is struck.", ua = "Сестра Браяр огортає себе колючою аурою, завдаючи $268126s1 фізичної шкоди щоразу, коли її вражають." },
    { en = "Fires a bolt of crippling energy, inflicting $s1 Shadow damage to the target. Holding the focusing iris increases the damage done by $@spellname260699.", ua = "Випускає блискавку калічної енергії, завдаючи цілі $s1 шкоди від тіні. Тримання фокусувальної іриси збільшує шкоду від $@spellname260699." },
    { en = "Fires a bolt of ruinous energy, inflicting $s1 Shadow damage to the target. Holding the focusing iris increases the damage done by $@spellname260700.", ua = "Випускає блискавку згубної енергії, завдаючи цілі $s1 шкоди від тіні. Тримання фокусувальної іриси збільшує шкоду від $@spellname260700." },
    { en = "Hurls a jagged splinter of bone at the enemy, inflicting $s1 Physical damage. Holding the focusing iris increases the damage done by $@spellname260701.", ua = "Жбурляє у ворога зазублену кісткову скалку, завдаючи $s1 фізичної шкоди. Тримання фокусувальної іриси збільшує шкоду від $@spellname260701." },
    { en = "Marks all nearby enemies with cursed runes, inflicting $s1 Shadow damage every $t1 sec for $d. Upon expiration, or if the mark is dispelled, the rune explodes, inflicting an additional $260702s1 Shadow damage to all allies within $260702a1 yards.", ua = "Позначає всіх ворогів поблизу проклятими рунами, завдаючи $s1 шкоди від тіні кожні $t1 сек протягом $d. Після завершення або розвіювання мітки руна вибухає, завдаючи додатково $260702s1 шкоди від тіні всім союзникам у радіусі $260702a1 метрів." },
    { en = "The caster draws energy from the afterlife, increasing their damage done by $s1% every $261580t1 sec. This effect stacks.", ua = "Творець черпає енергію з потойбіччя, збільшуючи завдану шкоду на $s1% кожні $261580t1 сек. Цей ефект накопичується." },
    { en = "Jagged thorns erupt underneath the player, inflicting $267907s3 Physical damage every $267907t3 sec and stunning them. Destroying the thorns releases the player.", ua = "Під гравцем проростають зазублені терни, завдаючи $267907s3 фізичної шкоди кожні $267907t3 сек та оглушуючи його. Знищення тернів звільняє гравця." },
    { en = "Burning souls peel off of the Soulbound Goliath, attacking nearby players for $268047d.", ua = "Палаючі душі відриваються від Душезв'язаного Голіафа, нападаючи на гравців поблизу протягом $268047d." },
    { en = "Melee attacks inflict Fire damage.", ua = "Ближні атаки завдають шкоди вогнем." },
    { en = "Lightning strikes the target location, inflicting Nature damage to everything within $A2 yards of its impact. Additionally, a wildfire starts to burn, inflicting $260569s1 Fire damage every $260569t1 sec.", ua = "Блискавка б'є по вказаному місцю, завдаючи шкоди від сил природи всьому в радіусі $A2 метрів від місця удару. Крім того, спалахує пожежа, завдаючи $260569s1 шкоди вогнем кожні $260569t1 сек." },
    { en = "Smashes the enemy with a heavy fist, inflicting $s1 Physical damage.", ua = "Б'є ворога важким кулаком, завдаючи $s1 фізичної шкоди." },
    { en = "The caster is set on fire, confusing them and reducing their total Energy. Additionally, the caster emits waves of overbearing heat, inflicting $260547s1 Fire damage to all enemies every $t3 sec for $d.", ua = "Заклинач спалахує, що збиває його з пантелику й зменшує його загальну Енергію. Крім того, заклинач випромінює хвилі нестерпного жару, завдаючи $260547s1 шкоди від вогню всім ворогам кожні $t3 сек протягом $d." },
    { en = "Raal calls in Wasting Servants that walk towards him. A Servant reaching Raal causes him to consume the Servant.", ua = "Раал прикликає Виснажливих Слуг, що йдуть до нього. Коли Слуга досягає Раала, той поглинає його." },
    { en = "If no players are within melee range, Raal the Gluttonous consumes everybody, inflicting $s1 Shadow damage to all players.", ua = "Якщо в зоні ближнього бою немає гравців, Раал Ненажерливий поглинає всіх, завдаючи $s1 шкоди від тіні всім гравцям." },
    { en = "Upon death, the caster explodes, inflicting $s1 Nature damage to players within $a1 yards.", ua = "По смерті творець вибухає, завдаючи $s1 шкоди від сил природи гравцям у радіусі $a1 метрів." },
    { en = "Raal consumes the nearby Wasting Servant, increasing all damage done by $265005s1%. \n\n\n\nThis effect stacks.", ua = "Раал поглинає сусіднього Виснаженого Слугу, збільшуючи всю завдану шкоду на $265005s1%.\n\n\n\nЦей ефект накопичується." },
    { en = "Raal the Gluttonous expels a wave of rancid food, inflicting $264698s1 Nature damage at each impact. Each expulsion remains at the impact point, inflicting $264712s1 Nature damage every $264712t1 sec and reducing movement speed by $264712s2%.", ua = "Раал Ненажерливий вивергає хвилю тухлої їжі, завдаючи $264698s1 шкоди від сил природи при кожному влучанні. Кожна вивержена калюжа лишається в місці влучання, завдаючи $264712s1 шкоди від сил природи кожні $264712t1 сек і зменшуючи швидкість пересування на $264712s2%." },
    { en = "Raal smashes the ground, inflicting $s2 Physical damage to players in a cone in front of him.", ua = "Раал гатить по землі, завдаючи $s2 фізичної шкоди гравцям у конусі перед собою." },
    { en = "Raal releases $@spellname426590 after consuming a Wasting Servant, inflicting $s1 Nature damage every $t1 sec for $d to all players.\n\n\n\nThis effect stacks.", ua = "Раал вивільняє $@spellname426590 після поглинання Виснажливого Слуги, завдаючи $s1 шкоди від сил природи кожні $t1 сек протягом $d усім гравцям.\n\n\n\nЦей ефект накопичується." },
    { en = "Infects the target with a highly infectious plague, inflicting $s1 Nature damage every $t1 sec and reducing movement speed by $s2% for $d. Upon expiration or being dispelled, the target explodes, infecting nearby allies with $@spellname261440.", ua = "Заражає ціль вкрай заразною чумою, завдаючи $s1 шкоди від сил природи кожні $t1 сек і зменшуючи швидкість пересування на $s2% протягом $d. Після завершення або розвіювання ціль вибухає, заражаючи союзників поблизу ефектом $@spellname261440." },
    { en = "$@spellname261440 leaves behind remnants of itself upon expiration. After 4 sec, the remnants explode, inflicting $s1 Nature damage to all enemies with $A1 yards and applying $@spellname261440.", ua = "$@spellname261440 лишає по собі рештки після завершення. За 4 сек рештки вибухають, завдаючи $s1 шкоди від сил природи всім ворогам у радіусі $A1 метрів і накладаючи $@spellname261440." },
    { en = "Transfers a portion of the caster's health to the target, healing them to their maximum health.", ua = "Передає частину здоров'я творця цілі, зцілюючи її до максимального здоров'я." },
    { en = "Transferred vitality empowers the target, increasing damage done by $s1% and haste by $s2%. This effect stacks.", ua = "Передана життєва сила підсилює ціль, збільшуючи завдану шкоду на $s1% і поспіх на $s2%. Цей ефект накопичується." },
    { en = "Strikes the target with a bolt of unbearable pain, inflicting $s1 Shadow damage.", ua = "Вражає ціль блискавкою нестерпного болю, завдаючи $s1 шкоди від тіні." },
    { en = "Lady Waycrest plays an ear-splitting cadenza for $d, inflicting $268308s1 Shadow damage at each of the impact points.", ua = "Леді Вейкрест грає оглушливу каденцію протягом $d, завдаючи $268308s1 шкоди від тіні в кожній точці влучання." },
    { en = "Claws at the enemy with rotten claws, inflicting $s1 Nature damage and additional $s2 Nature damage every $t2 sec for $d.", ua = "Шматує ворога гнилими пазурами, завдаючи $s1 шкоди від сил природи та додатково $s2 шкоди від сил природи кожні $t2 сек протягом $d." },
    { en = "At 100 energy, the caster releases a torrent of dark energy, inflicting $s1 Shadow damage to all enemies. Additionally, all Deathtouched Slavers are resurrected, brought back to their maximum health, and any crowd control effects on them are dispelled.", ua = "При 100 одиницях енергії творець вивільняє потік темної енергії, завдаючи $s1 шкоди від тіні всім ворогам. Крім того, усі Торкнуті смертю Наглядачі-раби воскресають, повертаються до максимального здоров'я, а будь-які ефекти контролю на них розвіюються." },
    { en = "A torrent of death energy is focused on the player, stunning them and inflicting $s Shadow damage every $t1 sec for $d.", ua = "Потік смертельної енергії зосереджується на гравцеві, оглушуючи його та завдаючи $s шкоди від тіні кожні $t1 сек протягом $d." },
    { en = "A shadowy arc of lightning strikes an enemy, inflicting $s1 Shadow damage and then jumping to all nearby enemies.", ua = "Тіньова дуга блискавки б'є по ворогу, завдаючи $s1 шкоди від тіні, а потім перестрибує на всіх ворогів поблизу." },
    { en = "Summons forth a Deathtouched Slaver to assist the caster.", ua = "Прикликає Торкнутого смертю Наглядача-раба на допомогу творцеві." },
    { en = "Throws a vial of alchemical fire at a target location, burning the corpses of nearby Deathtouched Slavers.", ua = "Кидає флакон алхімічного вогню у вказане місце, спалюючи трупи Торкнутих смертю Наглядачів-рабів поблизу." },
    { en = "Leaps to the furthest target and attacks all nearby enemies within $271178A1 yards, inflicting $271178s1 Physical damage and additional Physical damage every $271178t2 sec for $271178d.", ua = "Стрибає до найвіддаленішої цілі й атакує всіх ворогів поблизу в радіусі $271178A1 метрів, завдаючи $271178s1 фізичної шкоди та додаткової фізичної шкоди кожні $271178t2 сек протягом $271178d." },
    { en = "Fires a bolt of darkened energy at the enemy, inflicting $s1 Shadow damage.", ua = "Випускає блискавку затемненої енергії у ворога, завдаючи $s1 шкоди від тіні." },
    { en = "Reduces movement speed by $s2% and inflicts $s1 Nature damage every $t1 sec.", ua = "Зменшує швидкість пересування на $s2% і завдає $s1 шкоди силами природи кожні $t1 с." },
    { en = "The victim is encased in goop, incapacitating them until the goop is destroyed.", ua = "Жертву огортає слиз, знешкоджуючи її, доки слиз не буде знищено." },
    { en = "Causes tremors within an area around the caster, inflicting $s1 Nature damage every $258627t1 sec to players standing in the area.", ua = "Спричиняє поштовхи на ділянці навколо заклинателя, завдаючи $s1 шкоди від сил природи кожні $258627t1 с гравцям, що стоять на цій ділянці." },
    { en = "Hurls blood bolts at random targets that inflict $203364s2 Shadow damage to enemies nearby and creates a pool of blood at her feet that inflicts $202947s1 Shadow damage every $202947t1 sec to enemies within it.", ua = "Жбурляє кривавими снарядами у випадкові цілі, завдаючи $203364s2 шкоди від тіні ворогам поблизу, та створює під своїми ногами калюжу крові, що завдає $202947s1 шкоди від тіні кожні $202947t1 сек ворогам у ній." },
    { en = "The Blood-Princess surges with power from absorbing the Congealed Blood, inflicting $s1 Shadow damage to the party and healing herself for $s2% of her max health.", ua = "Поглинаючи Загуслу кров, Кривава принцеса наливається могутністю, завдаючи $s1 шкоди від тіні групі та зцілюючи себе на $s2% від максимального здоров'я." },
    { en = "The caster must satiate their need for blood by biting a friendly unit, otherwise they lose their will to Princess Thal'ena. Cannot be used on existing vampyrs.", ua = "Заклинач мусить вгамувати свою жагу крові, вкусивши дружню істоту, інакше втратить волю на користь принцеси Тал'ени. Не можна застосувати на наявних вампірах." },
    { en = "You succumb to the hunger and your will is bound to Princess Thal'ena. Increases damage done by $s3%.", ua = "Ти піддаєшся голоду, і твоя воля підкорена принцесі Тал'ені. Збільшує завдану шкоду на $s3%." },
    { en = "Calls to the blood pools in the area, causing one to coalesce into a Congealed Blood that crawls towards the princess.", ua = "Прикликає калюжі крові в околиці, змушуючи одну з них згуститися в Загуслу кров, що повзе до принцеси." },
    { en = "An aura of sorrow and despair emanates from the caster, inflicting $203057s1 Shadow damage every $t1 sec. to enemies that are not vampyrs. Damage increased for every existing vampyr.", ua = "Від заклинача струмує аура скорботи й розпачу, завдаючи $203057s1 шкоди від тіні кожні $t1 сек ворогам, які не є вампірами. Шкода зростає за кожного наявного вампіра." },
    { en = "You are infused with the blood of the Vampyr Princess, increasing all damage done by $202781s4%, increasing Leech by $202781s2% and reducing threat by 100%.", ua = "Тебе сповнила кров принцеси-вампіра, збільшуючи всю завдану шкоду на $202781s4%, висмоктування на $202781s2% та зменшуючи загрозу на 100%." },
    { en = "Deals $202766s1 Physical damage to the target, granting them the Essence of the Blood Princess.", ua = "Завдає $202766s1 фізичної шкоди цілі, наділяючи її Есенцією Кривавої принцеси." },
    { en = "Over time Festerface gains energy. Upon reaching 100 energy Festerface loses control of his tummy, spewing forth a Black Bile.", ua = "З часом Фестерфейс накопичує енергію. Сягнувши 100 енергії, Фестерфейс втрачає контроль над своїм черевом і вивергає Чорну жовч." },
    { en = "Congealed Goo erupt spewing waves of noxious fumes inflicting $201477s1 Nature damage every $t1 sec to all players.", ua = "Загуслий слиз вибухає, випускаючи хвилі отруйних випарів, що завдають $201477s1 шкоди від сил природи кожні $t1 сек усім гравцям." },
    { en = "Bringing Festerface near a Recongealing ooze causes him to devour it, removing it permanently.", ua = "Якщо підвести Фестерфейса до слизу, що знову загусає, він пожирає його, видаляючи назавжди." },
    { en = "Upon reaching 0 health a Congealed Goo bursts into a pool of Icky Goo that inflicts $202266s1 Nature damage to all enemies standing within it.  \n\n\n\nAfter $d the Congealing Goo reforms and is restored to full health.", ua = "Сягнувши 0 здоров'я, Загуслий слиз розривається калюжею Липкого слизу, що завдає $202266s1 шкоди від сил природи всім ворогам, які в ній стоять.\n\n\n\nЧерез $d Загуслий слиз відновлюється й повертає собі повне здоров'я." },
    { en = "While the Black Bile is alive all healing and absorbs are reduced by $s1%.", ua = "Поки Чорна жовч жива, усе зцілення й поглинання зменшені на $s1%." },
    { en = "Festerface unleashes a torrent of toxic bile that inflicts $s1 Nature damage to all players in a cone in front of him.  In addition, pools of bile coagulate into $s2 Congealed Goo.", ua = "Фестерфейс випускає потік токсичної жовчі, що завдає $s1 шкоди від сил природи всім гравцям у конусі перед ним. До того ж калюжі жовчі згущуються в $s2 Загуслого слизу." },
    { en = "Shivermaw breathes on all enemies in front of her, inflicting $201380s1 Frost damage every $t1 sec for $d. Enemies hit by Frost Breath have their movement speed slowed by $201380s2% for $201380d. This effect stacks.", ua = "Шивермо дихає на всіх ворогів перед собою, завдаючи $201380s1 шкоди від морозу кожні $t1 сек протягом $d. Вороги, уражені Морозним подихом, сповільнюються на $201380s2% протягом $201380d. Цей ефект накопичується." },
    { en = "Shivermaw calls down a storm that blankets the upper prison in Frostbite. This effect inflicts $201957s1 Frost damage every second and slows movement speed by $201957s2%. As the storm forms, ice comets rain down, inflicting $201852s1 Frost damage to enemies in the targeted areas.", ua = "Шивермо прикликає бурю, що огортає верхній ярус в'язниці Морозним укусом. Цей ефект завдає $201957s1 шкоди від морозу щосекунди й сповільнює рух на $201957s2%. Поки буря формується, з неба падають крижані комети, завдаючи $201852s1 шкоди від морозу ворогам у позначених ділянках." },
    { en = "Shivermaw flies into the air and releases an Ice Bomb that detonates after 5 sec. This effect inflicts $201961s1 Frost damage to all players. In addition, players in the lower portion of the prison are frozen in ice for $202037d or until their ice block is destroyed.", ua = "Шивермо злітає в повітря й вивільняє Крижану бомбу, що детонує за 5 сек. Цей ефект завдає $201961s1 шкоди від морозу всім гравцям. До того ж гравців у нижній частині в'язниці заморожує в кригу на $202037d або доки їхній крижаний блок не буде зруйновано." },
    { en = "Shivermaw inflicts $s1 Physical damage to players in a cone behind her, knocking them back.", ua = "Шивермо завдає $s1 фізичної шкоди гравцям у конусі позаду себе, відкидаючи їх." },
    { en = "Shivermaw inflicts $s1 Frost damage to players in a cone in front of her, knocking them back.", ua = "Шивермо завдає $s1 шкоди від морозу гравцям у конусі перед собою, відкидаючи їх." },
    { en = "Shivermaw chills all players to the bone, causing them to inflict $202065s1 Frost damage to their allies within $202065A1 yards every second for $d. Each ally hit has their movement speed reduced by $202065s2% for $202065d.", ua = "Шивермо проймає всіх гравців холодом до кісток, через що вони завдають $202065s1 шкоди від морозу своїм союзникам у радіусі $202065A1 м щосекунди протягом $d. Кожен уражений союзник сповільнюється на $202065s2% протягом $202065d." },
    { en = "Causes a barrage of spikes to emerge from the ground in a cone towards a player. Players hit by a spike suffer $s1 Physical damage and are knocked into the air.", ua = "Спричиняє град шипів, що виринають із землі конусом у напрямку гравця. Гравці, у яких влучив шип, дістають $s1 фізичної шкоди й підкидаються в повітря." },
    { en = "Anub'esset calls ancient Spitting Scarabs to his side.", ua = "Ануб'ессет прикликає до себе на поміч прадавніх Скарабеїв-плювачів." },
    { en = "Inflicts $s1 Physical damage and reduces healing received by $s2% for $d.", ua = "Завдає $s1 фізичної шкоди й зменшує отримуване зцілення на $s2% протягом $d." },
    { en = "Players who step into the Blistering Ooze take $s1 Nature damage every $t1 sec. and have their movement speed reduced by $s2% for $d.", ua = "Гравці, що ступають у пухирчастий слиз, дістають $s1 шкоди від сил природи кожні $t1 с і мають швидкість пересування знижену на $s2% протягом $d." },
    { en = "Spits poison at a player, inflicting $s1 Nature damage immediately, and poisoning them for $s2 Nature damage every $t2 sec. for $d.", ua = "Плює отрутою в гравця, завдаючи $s1 шкоди від сил природи негайно та отруюючи його на $s2 шкоди від сил природи кожні $t2 сек протягом $d." },
    { en = "Thick thorium plating renders the rocket chicken indestructible.", ua = "Товста торієва обшивка робить ракетного курча незнищенним." },
    { en = "A finger aimed laser beam strikes a random player, immediately inflicting $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d.", ua = "Націлений пальцем лазерний промінь б'є по випадковому гравцеві, негайно завдаючи $s1 шкоди від вогню та ще $s2 шкоди від вогню кожні $t2 сек протягом $d." },
    { en = "The Elementium Squirrel Bomb charges up and then explodes, inflicting $s1 Fire damage to all players. The bomb can be disarmed beforehand to prevent the explosion.", ua = "Елементієва білка-бомба заряджається, а тоді вибухає, завдаючи $s1 шкоди від вогню всім гравцям. Бомбу можна знешкодити заздалегідь, щоб запобігти вибуху." },
    { en = "Miniature rockets swarm out of the Thorium Rocket Chicken every $t2 sec, striking all players and inflicting $201387s1 Fire damage.", ua = "Мініатюрні ракети роєм вилітають із Торієвого ракетного курча кожні $t2 сек, б'ючи по всіх гравцях і завдаючи $201387s1 шкоди від вогню." },
    { en = "Millificent lobs an Overloaded Elementium Squirrel Bomb onto the ground. This bomb periodically ejects Mechanical Bomb Squirrels as long as it is operational.", ua = "Мілліфісент кидає на землю Перевантажену елементієву білку-бомбу. Ця бомба періодично викидає Механічних білок-бомб, доки лишається справною." },
    { en = "Millificent throws a lunchbox containing a Thorium Rocket Chicken.", ua = "Мілліфісент кидає коробку для сніданку з Торієвим ракетним курчам усередині." },
    { en = "Several Mechanical Bomb Squirrels are released from the bomb, each charging to a player and exploding. The explosion inflicts $s1 Fire damage and destroys the squirrel.", ua = "З бомби вивільняється кілька Механічних білок-бомб, кожна з яких мчить до гравця та вибухає. Вибух завдає $s1 шкоди від вогню й знищує білку." },
    { en = "Millificent lobs an Elementium Squirrel Bomb onto the ground.", ua = "Мілліфісент кидає на землю Елементієву білку-бомбу." },
    { en = "The Thorium Rocket Chicken fires a massive rocket in a straight line, inflicting $s1 Fire damage and knocking back players struck.", ua = "Торієве ракетне курча випускає величезну ракету по прямій лінії, завдаючи $s1 шкоди від вогню та відкидаючи уражених гравців." },
    { en = "Millificent throws a lunchbox containing a Reinforced Thorium Rocket Chicken. This reinforced mechanical construct is indestructible.", ua = "Мілліфісент кидає коробку для сніданку з Підсиленим торієвим ракетним курчам усередині. Ця підсилена механічна конструкція незнищенна." },
    { en = "Calls to the void, ushering Faceless Tendrils through to this world over $D. Each Tendril flays the mind of a target, inflicting $201172s1 Shadow damage every second until defeated.", ua = "Прикликає Порожнечу, тягнучи в цей світ Безликі мацаки протягом $D. Кожен мацак шматує розум цілі, завдаючи $201172s1 шкоди від тіні щосекунди, доки його не знищать." },
    { en = "The shadows begin to collapse around the previously scarred location, attracting nearby players over $D. Any players caught within the event horizon take $201255s1 Shadow damage every second.", ua = "Тіні починають згортатися навколо раніше позначеного місця, притягуючи гравців поблизу протягом $D. Будь-які гравці, захоплені в межах горизонту подій, зазнають $201255s1 шкоди від тіні щосекунди." },
    { en = "Periodically increases Eternal Darkness damage by $s2%. This effect stacks.", ua = "Періодично збільшує шкоду Вічної темряви на $s2%. Цей ефект накопичується." },
    { en = "Fires a shadow missile at a target, dealing $201120s1 Shadow damage to all enemies near the impact point and knocking them away. After impact, leaves an energy field that lingers for $201120D, inflicting $201121s1 Shadow damage every second and reducing healing done by $201121s2%.", ua = "Випускає тіньовий снаряд у ціль, завдаючи $201120s1 шкоди від тіні всім ворогам біля точки влучання та відкидаючи їх геть. Після влучання лишається енергетичне поле, що тримається $201120D, завдаючи $201121s1 шкоди від тіні щосекунди та зменшуючи завдане зцілення на $201121s2%." },
    { en = "Strikes fear in the minds of a target, fearing them for $D.", ua = "Уселяє жах у розум цілі, лякаючи її протягом $D." },
    { en = "Dooms the target, inflicting $201148s1 Shadow damage.", ua = "Прирікає ціль, завдаючи $201148s1 шкоди від тіні." },
    { en = "Chaotic energies arc from the caster to a random target, inflicting $203619s1 Fire damage to all enemies within 5 yards of the target.", ua = "Хаотична енергія перестрибує від мовця на випадкову ціль, завдаючи $203619s1 шкоди вогнем усім ворогам у межах 5 метрів від цілі." },
    { en = "The caster strikes with their axe so violently that a burst of Fel energy erupts in a cone in front of them. Players caught in the area suffer $s2 Fire damage.", ua = "Заклинач рубає сокирою так люто, що в конусі перед ним вивергається спалах енергії Скверни. Гравці, захоплені в цій ділянці, зазнають $s2 шкоди від вогню." },
    { en = "The Wake of Destruction explodes on contact, inflicting $s1 Shadow damage to all players within $A1 yards.", ua = "Слід руйнування вибухає від дотику, завдаючи $s1 шкоди від тіні всім гравцям у радіусі $A1 м." },
    { en = "The caster smashes their axe into the ground so violently that all enemies are thrown about the room.", ua = "Той, хто чаклує, з такою люттю врубує сокиру в землю, що всіх ворогів розкидає по залу." },
    { en = "The caster readies their axe to execute the target.  If the victim is not freed from their bonds within $d they will die instantly.", ua = "Той, хто чаклує, готує сокиру, щоб скарати ціль. Якщо жертву не звільнити від пут протягом $d, вона миттєво загине." },
    { en = "The caster chooses $I targets, causing them to emit 4 Wakes of Destruction after $t1 sec.", ua = "Той, хто чаклує, обирає $I цілей, через що ті за $t1 с випускають 4 Сліди руйнування." },
    { en = "A Phase Spider fixates on a target, moving towards them as long as the target is not facing the caster.", ua = "Фазовий павук зосереджується на цілі й рухається до неї, доки ціль не повернена до того, хто чаклує." },
    { en = "Caustic venom erupts from the targets skin, inflicting $s1 Nature damage every $210504t1 sec. for $210504d.", ua = "Зі шкіри цілі вивергається їдка отрута, завдаючи $s1 шкоди від сил природи кожні $210504t1 с протягом $210504d." },
    { en = "Inflicts $s1 Fire damage to nearby allies.", ua = "Завдає $s1 шкоди вогнем найближчим союзникам." },
    { en = "Inflicts $s2 Nature damage and an additional $s3 Nature damage every $t3 sec for $d.", ua = "Завдає $s2 шкоди від сил природи, а також додатково $s3 шкоди від сил природи кожні $t3 с протягом $d." },
    { en = "Inflicts $s1 Physical damage to all nearby enemies and pulls the targets to the caster.", ua = "Завдає $s1 фізичної шкоди всім найближчим ворогам і притягує цілі до того, хто чаклує." },
    { en = "The Amalgam absorbs a soul, destroying it and increasing the damage inflicted by Soul Burst by $s1%.", ua = "Амальгама поглинає душу, знищуючи її та збільшуючи шкоду від Вибуху душ на $s1%." },
    { en = "Throws a scythe towards a player, inflicting $196517s2 Physical damage and knocking back any players it comes into contact with.", ua = "Кидає косу в напрямку гравця, завдаючи $196517s2 фізичної шкоди й відкидаючи всіх гравців, яких вона зачіпає." },
    { en = "The Amalgam of Souls bursts, inflicting $s1 Shadow damage to all players and releasing the most powerful spirits of Lord Ravencrest's ancestors.", ua = "Амальгама душ вибухає, завдаючи $s1 шкоди від тіні всім гравцям і вивільняючи наймогутніших духів предків лорда Рейвенкреста." },
    { en = "Cuts targets in front of the Amalgamation to their very soul, inflicting $s1 Shadow damage and increasing damage taken by $s2% for $d.", ua = "Розтинає до самісінької душі цілі перед Амальгамою, завдаючи $s1 шкоди від тіні та збільшуючи отримувану ними шкоду на $s2% протягом $d." },
    { en = "Lures the restless souls in the Ravencrest crypts towards the Amalgamation of Souls. If they reach him, they will grant him Soulgorge.", ua = "Приваблює неспокійні душі в криптах Рейвенкрестів до Амальгами душ. Якщо вони її досягнуть, то нададуть їй Душепресит." },
    { en = "Fragments a player's soul, causing them to leave behind soul echoes. These echoes detonate inflicting $s1 Shadow damage to nearby players.", ua = "Розколює душу гравця, через що той лишає по собі відлуння душі. Ці відлуння детонують, завдаючи $s1 шкоди від тіні найближчим гравцям." },
    { en = "Inflicts $s1 Arcane damage and increases the caster's damage done by $s2% for $d.\n\n\n\nThis effect stacks.", ua = "Завдає $s1 арканної шкоди та збільшує шкоду, яку завдає той, хто чаклує, на $s2% протягом $d.\n\n\n\nЦей ефект накопичується." },
    { en = "Illysanna fixes her gaze on players. After a short time she dashes between them, inflicting $197484s3 Physical damage and leaving a Blazing Trail in her wake.", ua = "Іллісанна спрямовує погляд на гравців. За мить вона проноситься поміж ними, завдаючи $197484s3 фізичної шкоди та лишаючи по собі Полум'яний слід." },
    { en = "Inflicts $s1 Physical damage immediately, and $s2 Physical damage every $t2 sec. for $d to a targeted player, bouncing to any other nearby players.", ua = "Миттєво завдає $s1 фізичної шкоди, а також $s2 фізичної шкоди кожні $t2 с протягом $d обраному гравцеві, перестрибуючи на інших найближчих гравців." },
    { en = "A deadly attack shears the target, inflicting $s1 Physical damage.", ua = "Смертоносна атака розтинає ціль, завдаючи $s1 фізичної шкоди." },
    { en = "Fires a beam of fel power that follows a player, leaving behind patches of Felblazed Ground.", ua = "Випускає промінь сили Скверни, що переслідує гравця, лишаючи по собі плями Випаленої Скверною землі." },
    { en = "Inflicts $s1 Fire damage every $t sec.", ua = "Завдає $s1 шкоди вогнем кожні $t с." },
    { en = "Inflicts $s1 Physical damage and stuns all players in a cone in front of the Vanguard for $d.", ua = "Завдає $s1 фізичної шкоди та оглушує всіх гравців у конусі перед Авангардом на $d." },
    { en = "Inflicts $s1 Fire damage every $t1 sec. to any players inside Felblazed Ground.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с усім гравцям на Випаленій Скверною землі." },
    { en = "Impacts the first player he comes into contact with, inflicting $s2 Physical damage, knocking them back, and increasing their damage taken from Hateful Charges by $224188s1% for $224188d.", ua = "Врізається в першого гравця, з яким стикається, завдаючи $s2 фізичної шкоди, відкидаючи його та збільшуючи отримувану ним шкоду від Сповнених ненависті наскоків на $224188s1% протягом $224188d." },
    { en = "Smashspite's damaging melee attacks grant him Brutality in proportion to the damage done. \n\n\n\nWhen he reaches 100 Brutality, he will unleash a Brutal Haymaker at his current target.", ua = "Завдаючи шкоди ближнім боєм, Смешспайт накопичує Жорстокість пропорційно завданій шкоді.\n\n\n\nДосягнувши 100 Жорстокості, він обрушує Жорстокий розмах на свою поточну ціль." },
    { en = "Smashspite punches his current target, inflicting $s1 Physical damage and increasing damage taken by $s2% for $d.", ua = "Смешспайт б'є свою поточну ціль, завдаючи $s1 фізичної шкоди та збільшуючи отримувану нею шкоду на $s2% протягом $d." },
    { en = "Inflicts $s1 Fire damage to any players who come into contact with a pool of Fel Vomitus.", ua = "Завдає $s1 шкоди вогнем будь-яким гравцям, що стикаються з калюжею Блювотиння Скверни." },
    { en = "A nearby felbat marks a target and then, after a brief interval, vomit fel bile in their direction, creating pools of Fel Vomitus.", ua = "Найближчий кажан Скверни позначає ціль, а тоді, за коротку мить, вивергає в її напрямку жовч Скверни, утворюючи калюжі Блювотиння Скверни." },
    { en = "Stomps the ground, inflicting $s1 Physical damage to all players and knocking them back.", ua = "Гупає по землі, завдаючи $s1 фізичної шкоди всім гравцям і відкидаючи їх." },
    { en = "Smashspite the Hateful focuses his gaze on a target. \n\n\n\nSmashspite performs a Hateful Charge in the direction of the affected player when Hateful Gaze expires.", ua = "Смешспайт Ненависний зосереджує погляд на цілі.\n\n\n\nКоли Сповнений ненависті погляд згасає, Смешспайт здійснює Сповнений ненависті наскок у напрямку враженого гравця." },
    { en = "Launches a volley of shadow energy towards all players, inflicting $s2 Shadow damage.", ua = "Запускає залп тіньової енергії в усіх гравців, завдаючи $s2 шкоди від тіні." },
    { en = "Inflicts $s1 Shadow damage to all enemies in a line in front of the caster and knocks them back.", ua = "Завдає $s1 шкоди від тіні всім ворогам на лінії перед тим, хто чаклує, та відкидає їх." },
    { en = "Envelops the target in a swarm of stinging insects, inflicting $s2 Physical damage every $t2 sec.\n\nHas a chance to also stun the target for $199168d when dealing damage. \n\n\n\nPlayers can attack the swarm and must kill it to remove the effect.", ua = "Огортає ціль роєм жалких комах, завдаючи $s2 фізичної шкоди кожні $t2 с.\n\nЗавдаючи шкоди, має шанс також приголомшити ціль на $199168d.\n\n\n\nГравці можуть атакувати рій і мусять знищити його, щоб зняти ефект." },
    { en = "Creates a cloud of hypnotic gas, causing anyone who enters it to be put to sleep. Taking damage or leaving the cloud will remove the effect.", ua = "Створює хмару гіпнотичного газу, через яку кожен, хто в неї входить, засинає. Отримана шкода або вихід із хмари знімають ефект." },
    { en = "Lord Ravencrest calls on the power of his ancestors to grant the party strength, increasing damage done, healing done, and health by $s1%.", ua = "Лорд Рейвенкрест закликає силу своїх предків, щоб наділити загін міццю, збільшуючи завдану шкоду, зцілення та здоров'я на $s1%." },
    { en = "A deadly attack shears the target, inflicting $s1 Physical damage and causing them to bleed for $s2 damage every $t2 sec.", ua = "Смертоносна атака розтинає ціль, завдаючи $s1 фізичної шкоди та змушуючи її кровоточити, отримуючи $s2 шкоди кожні $t2 с." },
    { en = "Throws a glaive at a targeted player, traveling back and forth from the position it was thrown. The glaive inflicts $198781s1 Physical damage and knocks back any targets it touches.", ua = "Жбурляє глефу в обраного гравця; вона рухається туди й назад від місця, звідки була кинута. Глефа завдає $198781s1 фізичної шкоди та відкидає всі цілі, яких торкається." },
    { en = "Splits into several images, who each cast Dark Obliteration in sequence.", ua = "Розділяється на кілька образів, кожен з яких по черзі творить Темне знищення." },
    { en = "With a slam of his mighty bark-covered fists, Agronox deals $s1 Physical damage to his current target and knocks them back.", ua = "Ударом своїх могутніх вкритих корою кулаків Агронокс завдає $s1 фізичної шкоди своїй поточній цілі та відкидає її." },
    { en = "Vines lash to the throat of a player inflicting $238598s1 Nature damage every second until they are more than 20 yards from the deadly bloom. This effect increases by 10% with every tick.", ua = "Лози обвивають горлянку гравця, завдаючи $238598s1 шкоди від сил природи щосекунди, доки він не відійде більш ніж на 20 м від смертоносного суцвіття. Цей ефект збільшується на 10% з кожним спрацюванням." },
    { en = "The flora of the Hanging Gardens erupt in a colorful but deadly cloud, inflicting $s1 Nature damage every $t  sec.  This effect stacks.", ua = "Флора Висячих садів вибухає барвистою, але смертоносною хмарою, завдаючи $s1 шкоди від сил природи кожні $t сек. Цей ефект накопичується." },
    { en = "Fulminating Lashers detonate when they reach their target, inflicting $s1 Nature damage to all enemies within $A1 yards.", ua = "Спопеляючі батожники детонують, коли досягають цілі, завдаючи $s1 шкоди від сил природи всім ворогам у радіусі $A1 ярдів." },
    { en = "Bursts with slime, inflicting $240063s1 Nature damage to all players within $240063A1 yards.\n\n\n\nThis effect creates pools that inflict $240065s1 Nature damage to players within the pools every second.", ua = "Вибухає слизом, завдаючи $240063s1 шкоди від сил природи всім гравцям у радіусі $240063A1 ярдів.\n\n\n\nЦей ефект створює калюжі, що завдають $240065s1 шкоди від сил природи гравцям усередині них щосекунди." },
    { en = "Impacts the first player he comes into contact with, inflicting $238469s1 Physical damage and knocking them back, or destroying any bookshelves with which he collides.", ua = "Врізається в першого гравця, з яким стикається, завдаючи $238469s1 фізичної шкоди й відкидаючи його, або трощить будь-які книжкові полиці, на які наштовхнеться." },
    { en = "Runes spring forth from the magical books, slowing all players.", ua = "З магічних книг здіймаються руни, сповільнюючи всіх гравців." },
    { en = "Thrashbite hurls his mighty cudgel around the outer ring of the library, dealing $240951s1 Physical damage to all players in its path.", ua = "Молотозуб шпурляє свого могутнього кийка вздовж зовнішнього кільця бібліотеки, завдаючи $240951s1 фізичної шкоди всім гравцям на його шляху." },
    { en = "Entrancing narrative charms a random player.  This effect breaks if their health goes below 30%.", ua = "Захоплива оповідь зачаровує випадкового гравця. Цей ефект розвіюється, якщо його здоров'я падає нижче 30%." },
    { en = "As the tomes open, all sound is magically absorbed into the ancient pages, silencing all players for $d.", ua = "Коли томи розкриваються, усі звуки магічно вбираються в стародавні сторінки, занімовуючи всіх гравців на $d." },
    { en = "Inflicts $s1 Arcane damage to the current enemy target.", ua = "Завдає $s1 арканної шкоди поточній ворожій цілі." },
    { en = "Slams the ground with his massive cudgel, inflicting $s2 Physical damage to all enemies and $s1 Physical damage to all enemies within $A1 yards.", ua = "Гатить по землі своїм велетенським кийком, завдаючи $s2 фізичної шкоди всім ворогам і $s1 фізичної шкоди всім ворогам у радіусі $A1 ярдів." },
    { en = "Thrashbite the Scornful focuses his gaze on a target. \n\n\n\nThrashbite performs a Scornful Charge in the direction of the affected player when Scornful Gaze expires.", ua = "Молотозуб Зневажливий зосереджує свій погляд на цілі.\n\n\n\nКоли Зневажливий погляд спливає, Молотозуб виконує Зневажливий ривок у напрямку враженого гравця." },
    { en = "Heat radiates from the fiend, inflicting $241609s1 Fire damage every $t1 sec.", ua = "Від потвори віє жаром, завдаючи $241609s1 вогняної шкоди кожні $t1 с." },
    { en = "The Aegis of Aggramar protects all allies within its radius by reducing damage received by $s1% but also reduces damage inflicted by $s2% and healing done by $s3%.\n\n\n\nGetting hit by Felsoul Cleave or standing within the Aegis' protection drains the shield over time.", ua = "Егіда Аґрамара захищає всіх союзників у своєму радіусі, зменшуючи отримувану шкоду на $s1%, але водночас зменшує завдану шкоду на $s2% і зцілення на $s3%.\n\n\n\nУраження Розрубом скверни-душі або перебування під захистом Егіди поступово виснажує щит." },
    { en = "Inflicts $s1 Shadow damage to enemies within melee distance of the caster and knocks them back.", ua = "Завдає $s1 шкоди від тіні ворогам у межах ближнього бою від того, хто творить закляття, і відкидає їх." },
    { en = "Increases the caster's attack speed by $s2% for $d.", ua = "Збільшує швидкість атаки того, хто творить закляття, на $s2% на $d." },
    { en = "Something large approaches the portal. If the guardian is not destroyed before it arrives, it will emerge from the nether.", ua = "Щось велике наближається до порталу. Якщо не знищити вартового до його прибуття, воно вийде з Нижнього Світу." },
    { en = "Fires a fel blast at a random enemy, inflicting $236566s1 Fire damage to all enemies within $236566A1 yards of the impact.", ua = "Випускає спалах скверни у випадкового ворога, завдаючи $236566s1 шкоди вогнем усім ворогам у радіусі $236566A1 ярдів від місця влучання." },
    { en = "Chaotic energies arc from the caster, inflicting $236551s1 Fire damage to all enemies.", ua = "Хаотичні енергії розходяться дугами від того, хто творить закляття, завдаючи $236551s1 шкоди вогнем усім ворогам." },
    { en = "Inflicts $s2 Fire damage to all enemies in a cone within $A2 yards in front of the caster and leaves fire puddles in the area that inflict $240295s1 Fire damage every $240295t1 sec.", ua = "Завдає $s2 вогняної шкоди всім ворогам у конусі завширшки $A2 ярдів перед заклинателем і лишає на цій ділянці вогняні калюжі, що завдають $240295s1 вогняної шкоди кожні $240295t1 с." },
    { en = "Inflicts $s1 Fire damage to enemies within $A1 yards in a cone in front of the caster, and drains the Aegis of Aggramar by $s2%.", ua = "Завдає $s1 шкоди вогнем ворогам у радіусі $A1 ярдів у конусі перед тим, хто творить закляття, і виснажує Егіду Аґрамара на $s2%." },
    { en = "Hurls fel energy at random enemies  that places an aura on the targets. When the aura expires, a Fel Spike erupts at the destination, inflicting $243152s1 Fire damage to enemies within $243152A2 yards and knocking them back as well as inflicting $243152s3 Fire damage to all enemies.", ua = "Шпурляє енергію скверни у випадкових ворогів, накладаючи ауру на цілі. Коли аура спливає, у точці призначення зринає Шпичак скверни, завдаючи $243152s1 шкоди вогнем ворогам у радіусі $243152A2 ярдів і відкидаючи їх, а також завдаючи $243152s3 шкоди вогнем усім ворогам." },
    { en = "Hurls dark energy at random enemies that inflicts $234824s1 Shadow damage to all nearby enemies and places a debuff on the target that inflicts an additional $234830s1 Shadow damage every $234830t1 sec. for $234830d.", ua = "Шпурляє темну енергію у випадкових ворогів, що завдає $234824s1 шкоди від тіні всім ворогам поблизу й накладає на ціль послаблення, яке завдає додаткові $234830s1 шкоди від тіні кожні $234830t1 сек. протягом $234830d." },
    { en = "Hurls fel bolts at enemies in front of the caster, dealing $239525s1 Fire damage.", ua = "Шпурляє стріли скверни у ворогів перед тим, хто творить закляття, завдаючи $239525s1 шкоди вогнем." },
    { en = "Face the Aegis of Agrammar towards Shadows of Mephistroth to protect Illidan from Shadow Blast.", ua = "Поверни Егіду Аґрамара до Тіней Мефістрота, щоб захистити Іллідана від Спалаху тіні." },
    { en = "A cresting wave of chaotic magic splashes over enemies in front of the caster, dealing $s2 Shadow damage. It also leaves shadow puddles in the area that inflict $233177s1 Shadow damage every $233177t1 sec.", ua = "Гребінь хвилі хаотичної магії накриває ворогів перед тим, хто творить закляття, завдаючи $s2 шкоди від тіні. Він також лишає в цій зоні тіньові калюжі, що завдають $233177s1 шкоди від тіні кожні $233177t1 сек." },
    { en = "Illidan attempts to draw Mephistroth from the shadows. Incoming damage from Shadow Blast interrupts Illidan and lengthens his cast time.", ua = "Іллідан намагається виманити Мефістрота з тіней. Шкода від Спалаху тіні перериває Іллідана і подовжує час прочитання його закляття." },
    { en = "Hurls fel energy at random enemies  that places an aura on the targets. When the aura expires, a Fel Spike erupts at the destination, inflicting $243152s1 Fire damage to enemies within $243152A2 yards and knocking them back as well as inflicting $243152s3 Fire damage to enemies within $243152A3 yards.", ua = "Шпурляє енергію скверни у випадкових ворогів, накладаючи ауру на цілі. Коли аура спливає, у точці призначення зринає Шпичак скверни, завдаючи $243152s1 шкоди вогнем ворогам у радіусі $243152A2 ярдів і відкидаючи їх, а також завдаючи $243152s3 шкоди вогнем ворогам у радіусі $243152A3 ярдів." },
    { en = "As long as Mephistroth remains in the shadows, the party suffers $s1 Shadow damage per stack every $t1 sec.", ua = "Доки Мефістрот лишається в тінях, група зазнає $s1 шкоди від тіні за кожен стак кожні $t1 сек." },
    { en = "Shadows of Mephistroth appear around Illidan and attempt to interrupt his cast of Expel Shadows. Shadow Blasts that impact enemies inflict $s1 Shadow damage to the target.", ua = "Тіні Мефістрота з'являються довкола Іллідана й намагаються перервати його прочитання Вигнання тіней. Спалахи тіні, що влучають у ворогів, завдають $s1 шкоди від тіні цілі." },
    { en = "Mephistroth fades into the shadows becoming invisible until Illidan can complete his Expel Shadows cast. While in this phase, Shadows of Mephistroth continually appear to assault Illidan to prevent Expel Shadows from being cast.", ua = "Мефістрот розчиняється в тінях, стаючи невидимим, доки Іллідан не завершить творити Вигнання тіней. Під час цієї фази безперервно з'являються Тіні Мефістрота, які нападають на Іллідана, щоб не дати йому сотворити Вигнання тіней." },
    { en = "Hinders a target, stunning them for $d.", ua = "Перешкоджає цілі, оглушуючи її на $d." },
    { en = "Drinks a Flask of the Solemn Night, increasing haste by $s1% and damage done by $s2%.", ua = "Випиває Флягу врочистої ночі, збільшуючи поспіх на $s1% і завдану шкоду на $s2%." },
    { en = "Gerdo summons in an arcane streetsweeper, which blasts players in a line after $219496d, inflicting $s1 Arcane damage.", ua = "Ґердо викликає чародійського вуличного підмітальника, який після $219496d випускає залп по гравцях уздовж лінії, завдаючи $s1 арканної шкоди." },
    { en = "Binds the feet of all players, instantly applying 3 stacks of Arcane Lockdown for $d. Each stack inflicts $s1 Arcane damage every $t1 sec and reduces movement speed by $s2%. Jumping removes a stack of Arcane Lockdown.", ua = "Сковує ноги всіх гравців, миттєво накладаючи 3 стаки Чародійського блокування на $d. Кожен стак завдає $s1 арканної шкоди кожні $t1 сек. і зменшує швидкість пересування на $s2%. Стрибок знімає один стак Чародійського блокування." },
    { en = "Slashes out, inflicting $s1 Arcane damage to players struck and stunning them for $d.", ua = "Розтинає, завдаючи $s1 арканної шкоди ураженим гравцям і оглушуючи їх на $d." },
    { en = "Call out for assistance, requesting aid from all active watchposts.", ua = "Кличе на підмогу, вимагаючи допомоги від усіх активних вартових постів." },
    { en = "Slash out around the caster, inflicting $s1 Physical damage immediately and bleeding players struck for $s2 Physical damage every $t2 sec for $d.", ua = "Розтинає довкола того, хто творить закляття, завдаючи $s1 фізичної шкоди негайно й змушуючи уражених гравців стікати кров'ю, завдаючи $s2 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "Radiates flames, inflicting $207907s1 Fire damage to all players every $t1 sec. Each application increases the caster's Fire damage done by $s2%.", ua = "Випромінює полум'я, завдаючи $207907s1 шкоди вогнем усім гравцям кожні $t1 с. Кожне застосування збільшує шкоду вогнем, яку завдає мовець, на $s2%." },
    { en = "Unleashes an ear piercing $@spellname397892 inflicting $s1 Shadow damage and interrupting spellcasting for $d.", ua = "Видає пронизливий $@spellname397892, що завдає $s1 шкоди від тіні й перериває творення заклять на $d." },
    { en = "Causes players to wither, reducing their maximum health by $s1% and movement speed by $s2%. This effect stacks.", ua = "Змушує гравців марніти, зменшуючи їхнє максимальне здоров'я на $s1% і швидкість пересування на $s2%. Цей ефект накопичується." },
    { en = "Sends a wave of force in a frontal cone, inflicting $s2 Physical damage and stunning all players within $a1 yards for $d.", ua = "Випускає хвилю сили в передньому конусі, завдаючи $s2 фізичної шкоди й оглушуючи всіх гравців у радіусі $a1 ярдів на $d." },
    { en = "Inflicts $207981s1 Shadow damage and reduces damage done by $207981s2% every $t1 sec for $d. This effect stacks.\n\n\n\nReduces movement speed by $207981s3%.", ua = "Завдає $207981s1 шкоди від тіні й зменшує завдану шкоду на $207981s2% кожні $t1 сек. протягом $d. Цей ефект накопичується.\n\n\n\nЗнижує швидкість пересування на $207981s3%." },
    { en = "Fire explodes beneath all players, inflicting $207887s1 Fire damage and knocking them into the air. Coming in contact with the flames afterwards inflicts $211457s1 Fire damage.", ua = "Вогонь вибухає під усіма гравцями, завдаючи $207887s1 шкоди вогнем і підкидаючи їх у повітря. Подальший контакт із полум'ям завдає $211457s1 шкоди вогнем." },
    { en = "Leaps at an enemy target inflicting $s1 Physical damage and knocking back all enemies in the area.", ua = "Стрибає на ворожу ціль, завдаючи $s1 фізичної шкоди та відкидаючи всіх ворогів у цій ділянці." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec for $d. Inflicts an additional $397908s1 Shadow damage to all nearby enemies when $@spellname397907 is removed.", ua = "Завдає $s1 шкоди від тіні кожні $t1 сек. протягом $d. Коли $@spellname397907 спадає, завдає додатково $397908s1 шкоди від тіні всім ворогам поблизу." },
    { en = "Shoots a bolt of flame at an enemy, inflicting $s1 Fire damage.", ua = "Метає у ворога вогняну стрілу, завдаючи $s1 шкоди вогнем." },
    { en = "A blazing ritual shoots bolts of fire at random enemies for $224377s1 Fire damage every $t1 sec for $d.", ua = "Палаючий ритуал випускає вогняні стріли у випадкових ворогів, завдаючи $224377s1 шкоди вогнем кожні $t1 с протягом $d." },
    { en = "Dashes to a player, inflicting $209667s1 Physical damage to targets within $209667A1 yds. Players struck are left bleeding for $209667s2 Physical damage every $209667t2 sec for $209667d.\n\n\n\nBlade Surge leaves behind an image of Advisor Melandrus.", ua = "Кидається до гравця, завдаючи $209667s1 фізичної шкоди цілям у радіусі $209667A1 м. Уражені гравці кровоточать, дістаючи $209667s2 фізичної шкоди кожні $209667t2 сек. протягом $209667d.\n\n\n\nКлинковий прорив лишає по собі образ радника Меландруса." },
    { en = "Slashes out with the power of wind, inflicting $s1 Physical damage to players in a straight line.\n\n\n\nImages of Advisor Melandrus also copy this ability when cast.", ua = "Б'є силою вітру, завдаючи $s1 фізичної шкоди гравцям на прямій лінії.\n\n\n\nОбрази радника Меландруса теж повторюють цю здібність, коли вона застосовується." },
    { en = "Enveloping Winds periodically traverse the balcony, stunning players they come in contact with for $d.", ua = "Огортальні вітри періодично проносяться балконом, оглушуючи гравців, яких вони торкаються, на $d." },
    { en = "Channels a fierce storm of blades, inflicting $209678s1 Physical damage to all players every $t1 sec for $d. This inflicts an additional $209678s2 Physical damage to players within $209678A2 yds of the source.\n\n\n\nImages of Advisor Melandrus also copy this ability when cast.", ua = "Спрямовує лютий вихор клинків, завдаючи $209678s1 фізичної шкоди всім гравцям кожні $t1 сек. протягом $d. Гравцям у радіусі $209678A2 м від джерела це завдає додатково $209678s2 фізичної шкоди.\n\n\n\nОбрази радника Меландруса теж повторюють цю здібність, коли вона застосовується." },
    { en = "Archdruid Glaidalis bashes all enemies in a cone in front of him, inflicting $198376s1 Physical damage and knocking them back.\n\nArchdruid Glaidalis then charges forward inflicting $198386s1 Physical damage and knocking back anyone in his way.", ua = "Архідруїд Ґлайдаліс б'є всіх ворогів у конусі перед собою, завдаючи $198376s1 фізичної шкоди та відкидаючи їх.\n\nПотім архідруїд Ґлайдаліс кидається вперед, завдаючи $198386s1 фізичної шкоди та відкидаючи всіх на своєму шляху." },
    { en = "Pulls a fragment of a Nightmare-corrupted star from the sky, creating an area of nightmare corruption that inflicts $198408s1 Shadow damage to anyone in the area.", ua = "Стягує з неба уламок зорі, спотвореної Жахіттям, створюючи ділянку скверни Жахіття, що завдає $198408s1 шкоди від тіні кожному, хто в ній перебуває." },
    { en = "Leaps at an enemy, inflicting $196354s1 Physical damage and causing a $@spellname196376.\n\nArchdruid Glaidalis will then leap back, inflicting $198269s1  Physical damage and causing a $@spellname196376.", ua = "Стрибає на ворога, завдаючи $196354s1 фізичної шкоди й викликаючи $@spellname196376.\n\nАрхідруїд Ґлайдаліс тоді відстрибує назад, завдаючи $198269s1  фізичної шкоди й викликаючи $@spellname196376." },
    { en = "Inflicts $s1 Physical damage every $t1 sec until healed past 90% of maximum health.", ua = "Завдає $s1 фізичної шкоди кожні $t1 сек., доки ціль не зцілять понад 90% максимального здоров'я." },
    { en = "Oakheart picks up and crushes his target, inflicting $s2 Nature damage every $t2 sec for $d. Oakheart then throws his target to the ground, inflicting $204658s1 Nature damage to anyone in the area.", ua = "Дубосерд хапає та чавить свою ціль, завдаючи $s2 шкоди від сил природи кожні $t2 сек. протягом $d. Потім Дубосерд жбурляє ціль об землю, завдаючи $204658s1 шкоди від сил природи всім у цій ділянці." },
    { en = "Oakheart calls for Vilethorn Saplings to erupt from the ground and attack nearby enemies.", ua = "Дубосерд прикликає паростки лиховинної тернини, що виринають із землі та нападають на ворогів поблизу." },
    { en = "Roots emerge under nearby enemies, inflicting $s1 Physical damage every $t1 sec. and rooting them in position for $d or until destroyed.", ua = "Під ворогами поблизу проростає коріння, завдаючи $s1 фізичної шкоди кожні $t1 сек. і знерухомлюючи їх на $d або до знищення." },
    { en = "Shatters the ground around the caster, inflicting $s1 Nature damage and knocking back enemies.", ua = "Розколює землю довкола виконавця, завдаючи $s1 шкоди від сил природи та відкидаючи ворогів." },
    { en = "Inflicts $s1 Fire damage in a cone in front of the caster and then burns the targets, inflicting $s2 Fire damage every $t2 sec. for $d.", ua = "Завдає $s1 шкоди вогнем у конусі перед виконавцем, а потім підпалює цілі, завдаючи $s2 шкоди вогнем кожні $t2 сек. протягом $d." },
    { en = "Dresaron roars, shaking the ground around him, inflicting $218587s1 Nature damage to nearby enemies and causing a cave in, inflicting $199460s1 Nature damage every $199460t1 sec.", ua = "Дресарон ревне, струшуючи землю довкола себе, завдаючи $218587s1 шкоди від сил природи ворогам поблизу та спричиняючи обвал, що завдає $199460s1 шкоди від сил природи кожні $199460t1 сек." },
    { en = "Dresaron aggressively flaps his wings, pushing enemies away and inflicting $220855s1 Nature damage every $220855t1 sec for $199345d.", ua = "Дресарон люто б'є крилами, відкидаючи ворогів і завдаючи $220855s1 шкоди від сил природи кожні $220855t1 сек. протягом $199345d." },
    { en = "Disturbing a Corrupted Dragon Egg causes a  Hatespawn Whelplng to erupt and begin to feed.", ua = "Якщо потурбувати спотворене драконяче яйце, з нього вилуплюється драконя ненависного виводка й починає живитися." },
    { en = "Breathes a cone of acid, inflicting $191326s1 Nature damage every $t2 sec for $d and reducing the armor of anyone hit by $191326s2% for $191326d.", ua = "Видихає конус кислоти, завдаючи $191326s1 шкоди від сил природи кожні $t2 сек. протягом $d та знижуючи броню всіх уражених на $191326s2% протягом $191326d." },
    { en = "Launches a bolt of Nightmare energy, inflicting $s1 Shadow damage.", ua = "Метає блискавку енергії Жахіття, завдаючи $s1 шкоди від тіні." },
    { en = "The burning nightmare fire empowers the Shade of Xavius, increasing all damage dealt by $s1%.", ua = "Палаючий вогонь Жахіття наснажує Тінь Ксавія, збільшуючи всю завдану шкоду на $s1%." },
    { en = "The Shade of Xavius heightens the fears of paranoia in his enemies. Enemies affected take $200329s1  Shadow damage and are Horrified for $200329d if they stand close to allies.", ua = "Тінь Ксавія посилює параноїчні страхи своїх ворогів. Уражені вороги зазнають $200329s1 шкоди від Тіні й охоплюються жахом на $200329d, якщо стоять близько до союзників." },
    { en = "Consumes an enemy's soul, inflicting $s1 Shadow damage every $t1 sec for $d.", ua = "Поглинає душу ворога, завдаючи $s1 шкоди від Тіні кожні $t1 сек. протягом $d." },
    { en = "The Shade of Xavius erupts with nightmare fire, igniting the Shaladrassil and inflicting $204502s1 Fire damage to nearby enemies. The ensuing inferno will then rain fire from above, inflicting $200111s1 Fire damage to anyone it hits.", ua = "Тінь Ксавія вибухає вогнем Жахіття, підпалюючи Шаладрассіл і завдаючи $204502s1 шкоди вогнем ворогам поблизу. Подальша пожежа проллє вогонь із неба, завдаючи $200111s1 шкоди вогнем кожному, кого зачепить." },
    { en = "The Shade of Xavius traps a player in a waking nightmare for $d. While under this effect, the target is silenced and pacified unless they are standing near another player.", ua = "Тінь Ксавія ловить гравця в наяву жахіття на $d. Під дією цього ефекту ціль занімовлена та упокорена, якщо тільки не стоїть поблизу іншого гравця." },
    { en = "Rends the target, leaving an infected wound that inflicts $s1 Nature damage every $t1 sec and decreases healing taken by $s2% for $d.", ua = "Шматує ціль, лишаючи інфіковану рану, що завдає $s1 шкоди від сил природи кожні $t1 сек. і зменшує отримане зцілення на $s2% протягом $d." },
    { en = "Launches a bolt of Nightmare energy, inflicting $s1 Shadow damage and applying  $@spellname200243.", ua = "Метає блискавку енергії Жахіття, завдаючи $s1 шкоди від тіні та накладаючи $@spellname200243." },
    { en = "Hurls a spear at a random enemy, inflicting $s1 Physical damage and an additional $s2 Physical damage every $t2 sec. for $d.", ua = "Метає спис у випадкового ворога, завдаючи $s1 фізичної шкоди та додатково $s2 фізичної шкоди кожні $t2 сек. протягом $d." },
    { en = "Inflicts $s1 Physical damage to all enemies.", ua = "Завдає $s1 фізичної шкоди всім ворогам." },
    { en = "Calls forth a Hatecoil Shellbreaker or Crestrider to assist Warlord Parjesh in combat.", ua = "Прикликає панцеролома або хвилеїзда Гейткойлів, щоб допомогти воєначальнику Парджешу в бою." },
    { en = "Throws a spear at an enemy, rending the first target struck. The strike inflicts $s1 Physical damage every $t1 sec and stuns for $d.", ua = "Кидає спис у ворога, шматуючи першу уражену ціль. Удар завдає $s1 фізичної шкоди кожні $t1 сек. та оглушує на $d." },
    { en = "Inflicts $s1 Nature damage to a random enemy.", ua = "Завдає $s1 шкоди від сил природи випадковому ворогу." },
    { en = "Upon reaching 30% remaining health, Warlord Parjesh enrages, gaining $s1% haste.", ua = "Коли в нього лишається 30% здоров'я, воєначальник Парджеш шаленіє, дістаючи $s1% поспіху." },
    { en = "Charge forward, inflicting $s1 Frost damage to all targets struck.", ua = "Кидається вперед, завдаючи $s1 шкоди від морозу всім ураженим цілям." },
    { en = "Calls forth a Hatecoil Shellbreaker and a Hatecoil Crestrider to assist Warlord Parjesh in combat.", ua = "Прикликає панцеролома та хвилеїзда Гейткойлів, щоб допомогти воєначальнику Парджешу в бою." },
    { en = "$@spellname191919 leaves behind puddles of Quicksand. Inflicts $s1 Nature damage to all targets within the Quicksand every $t1 sec. Also reduces movement speed by $s2%.", ua = "$@spellname191919 лишає по собі калюжі сипучих пісків. Завдає $s1 шкоди від сил природи всім цілям у сипучих пісках кожні $t1 сек. Також знижує швидкість пересування на $s2%." },
    { en = "After using $@spellname192135, the caster becomes motivated, increasing damage done by $s1% for $d. This effect stacks.", ua = "Після застосування $@spellname192135 виконавець наснажується, збільшуючи завдану шкоду на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Channels restorative waters around the caster's allies, healing them for $197504s1% health every $t1 sec for $d.", ua = "Спрямовує цілющі води довкола союзників виконавця, зцілюючи їх на $197504s1% здоров'я кожні $t1 сек. протягом $d." },
    { en = "Lady Hatecoil curses enemies with Arcane magic. When the curse is removed, the bearer releases a blast of Arcane energy in a frontal cone, knocking away players and destroying lesser creatures.", ua = "Леді Гейткойл проклинає ворогів чародійською магією. Коли прокляття знімають, носій вивільняє вибух чародійської енергії в передньому конусі, відкидаючи гравців і знищуючи дрібніших істот." },
    { en = "Monsoons follow their nearest targets, knocking players high into the air and blowing away sand dunes they come in contact with.", ua = "Мусони рухаються за найближчими цілями, підкидаючи гравців високо в повітря й розвіюючи піщані дюни, яких торкаються." },
    { en = "Explodes upon death, inflicting $s1 Frost damage to players within $A1 yds and reducing movement speed by $s2% for $d.", ua = "Вибухає при загибелі, завдаючи $s1 шкоди від морозу гравцям у радіусі $A1 м і знижуючи швидкість пересування на $s2% на $d." },
    { en = "Lady Hatecoil targets all players with a focused lightning strike, inflicting $s1 Nature damage after a brief cast. Any Lightning Strikes will blow away nearby sand dunes.", ua = "Леді Гейткойл б'є по всіх гравцях зосередженою блискавкою, завдаючи $s1 шкоди від сил природи після короткого творіння. Будь-які удари блискавки розвіюють поруч піщані дюни." },
    { en = "Vicious lightning strikes players who leave Lady Hatecoil's arena, inflicting $s1 Nature damage and increasing damage taken from Crackling Thunder by $s2% for $d.", ua = "Люті блискавки б'ють по гравцях, що покидають арену Леді Гейткойл, завдаючи $s1 шкоди від сил природи й підвищуючи шкоду від «Тріскучого грому» на $s2% на $d." },
    { en = "Lady Hatecoil beckons the tides to aid her, summoning several Saltsea Globules near her enemies.", ua = "Леді Гейткойл прикликає на допомогу припливи, призиваючи кілька Солоних Кульбашок поблизу своїх ворогів." },
    { en = "Each player struck by Focused Lightning releases Excess Lightning, inflicting $s1 Nature damage to nearby players. Excess Lightning blows away any sand dunes it strikes.", ua = "Кожен гравець, уражений «Зосередженою блискавкою», вивільняє Надлишкову Блискавку, завдаючи $s1 шкоди від сил природи гравцям поблизу. Надлишкова блискавка розвіює будь-які піщані дюни, в які влучає." },
    { en = "Lady Hatecoil electrifies the water in the surrounding area, inflicting $s1 Nature damage to players touching the water and stunning them for $d.", ua = "Леді Гейткойл електризує воду в навколишній місцевості, завдаючи $s1 шкоди від сил природи гравцям, що торкаються води, і приголомшуючи їх на $d." },
    { en = "King Deepbeard causes a Quake that inflicts $193159s1 Physical damage to enemies and their allies within $193159A1 yards. $?diff23|diff8[On Mythic difficulty, Quake causes Aftershock after $193167d.][]", ua = "Король Діпбірд викликає Трус, що завдає $193159s1 фізичної шкоди ворогам та їхнім союзникам у радіусі $193159A1 м. $?diff23|diff8[На міфічній складності Трус спричиняє Поштовх через $193167d.][]" },
    { en = "Inflicts $193088s1 Physical damage to enemies within $193088A1 yards of the impact location, ignoring armor.", ua = "Завдає $193088s1 фізичної шкоди ворогам у радіусі $193088A1 м від місця удару, ігноруючи броню." },
    { en = "Inflicts $s1 Physical damage to enemies within $A1 yards of the target.", ua = "Завдає $s1 фізичної шкоди ворогам у радіусі $A1 м від цілі." },
    { en = "The erupting Gaseous Bubble inflicts $s1 Frost damage to all nearby enemies.", ua = "Газова бульбашка, що лопає, завдає $s1 шкоди від морозу всім ворогам поблизу." },
    { en = "The Gaseous Bubble absorbs $s1 damage, but causes a Gaseous Explosion if the bubble is not depleted after $d.", ua = "Газова бульбашка поглинає $s1 шкоди, але спричиняє Гасовий Вибух, якщо її не вичерпати за $d." },
    { en = "King Deepbeard calls the seas to his aid! Call the Seas inflicts $193055s1 Frost damage every $193055t1 sec.", ua = "Король Діпбірд прикликає на допомогу моря! «Поклик морів» завдає $193055s1 шкоди від морозу кожні $193055t1 с." },
    { en = "Upon reaching 33% and 66% health Serpentrix Submerges and then Emerges at a distant location, summoning two Hydra Spawns!", ua = "Досягнувши 33% і 66% здоров'я, Серпентрікс занурюється, а потім з'являється в віддаленому місці, призиваючи двох Поріддів Гідри!" },
    { en = "Inflicts $s1 Fire damage to enemies within $A1 yards of the Hydra Spawn.", ua = "Завдає $s1 шкоди вогнем ворогам у радіусі $A1 м від Поріддя Гідри." },
    { en = "Inflicts $s1 Arcane damage to a random target, granting Arcane Charge to the Hydra Spawn.", ua = "Завдає $s1 арканної шкоди випадковій цілі, надаючи Поріддю Гідри Чародійський Заряд." },
    { en = "Increases damage dealt by $s1%. This effect stacks.", ua = "Підвищує завдану шкоду на $s1%. Цей ефект накладається стосами." },
    { en = "If Serpentrix is ever unable to reach an enemy with his melee attack, he enters a Rampage, wildly spitting poison!", ua = "Якщо Серпентрікс будь-коли не може дотягтися до ворога ближнім ударом, він впадає в Шаленство, дико плюючись отрутою!" },
    { en = "Serpentrix causes a Toxic Wound on a random player, causing the player to create a trail of Toxic Puddles.", ua = "Серпентрікс завдає Токсичної Рани випадковому гравцю, через що той лишає за собою слід Токсичних Калюж." },
    { en = "Creates a Toxic Puddle at your location! Toxic Puddles inflict $191858s1 Nature damage every 1 sec.", ua = "Створює Токсичну Калюжу там, де ти стоїш! Токсичні калюжі завдають $191858s1 шкоди від сил природи щосекунди." },
    { en = "Spits Poison at a random enemy target. The Poison Spit travels faster or slower depending on the direction of the winds.", ua = "Плює отрутою у випадкову ворожу ціль. Плювок отрути летить швидше чи повільніше залежно від напрямку вітрів." },
    { en = "The Wrath of Azshara commands massive tidal waves, which inflict $s1 Frost damage to all players within their path.", ua = "Гнів Азшари наказує здійнятися велетенським припливним хвилям, які завдають $s1 шкоди від морозу всім гравцям на своєму шляху." },
    { en = "Summons an arcane tornado nearby each player. Colliding with a tornado inflicts $s1 Arcane damage and knocks players away.", ua = "Призиває чародійський торнадо поряд із кожним гравцем. Зіткнення з торнадо завдає $s1 арканної шкоди й відкидає гравців." },
    { en = "Causes a massive Arcane Bomb to fall onto a target player's location. When dispelled, the bomb no longer tracks the target, but continues to fall. Upon reaching the ground, Arcane Bomb inflicts $s1 Arcane damage to players within $A1 yds and stuns for $d.", ua = "Скидає величезну Чародійську Бомбу на місце, де стоїть гравець-ціль. Після розвіювання бомба більше не стежить за ціллю, але продовжує падати. Досягнувши землі, Чародійська бомба завдає $s1 арканної шкоди гравцям у радіусі $A1 м і приголомшує на $d." },
    { en = "Inflicts $s1 Frost damage to players in an area in front of the caster, knocking them away.", ua = "Завдає $s1 шкоди від морозу гравцям у ділянці перед заклинателем, відкидаючи їх." },
    { en = "Melee attacks cause the ground to tremble, inflicting $197165s1 Physical damage to all players.", ua = "Ближні удари змушують землю двигтіти, завдаючи $197165s1 фізичної шкоди всім гравцям." },
    { en = "The Wrath of Azshara empowers the weather at 10% health remaining, calling forth and vastly intensifying the destructive storm.", ua = "Гнів Азшари підсилює погоду, коли в нього лишається 10% здоров'я, прикликаючи й значно посилюючи руйнівну бурю." },
    { en = "Lightning periodically strikes the ground, inflicting $192794s1 Nature damage to enemies within $192794A1 yards.", ua = "Блискавка раз у раз б'є в землю, завдаючи $192794s1 шкоди від сил природи ворогам у радіусі $192794A1 м." },
    { en = "The Wrath of Azshara targets a player for a crushing detonation, inflicting $s1% of their maximum health in Physical damage. This percentage is split among all players within $A1 yds.", ua = "Гнів Азшари обирає гравця ціллю нищівної детонації, завдаючи фізичної шкоди в розмірі $s1% його максимального здоров'я. Цей відсоток розподіляється між усіма гравцями в радіусі $A1 м." },
    { en = "Violent Winds periodically blow through the cove, making it difficult to remain stationary.", ua = "Шалені вітри раз у раз проносяться бухтою, через що важко лишатися на місці." },
    { en = "The Wrath of Azshara invokes the powers of a raging storm when no enemies are in melee combat, inflicting $s1 Frost damage to all enemies and increasing Frost damage taken by $s2% for $d. This effect stacks.", ua = "Гнів Азшари прикликає міць лютої бурі, коли жоден ворог не б'ється з ним у ближньому бою, завдаючи $s1 шкоди від морозу всім ворогам і підвищуючи отримувану ними шкоду від морозу на $s2% на $d. Цей ефект накладається стосами." },
    { en = "Arcane and Nature damage from the Wrath of Azshara marks its target, increasing Arcane and Nature damage taken by $s1% for $d. This effect stacks.", ua = "Арканна шкода й шкода від сил природи Гніву Азшари позначають ціль, підвищуючи отримувану нею арканну шкоду й шкоду від сил природи на $s1% на $d. Цей ефект накладається стосами." },
    { en = "Frost damage from the Wrath of Azshara marks its target, reducing movement speed by $s1% for $d. This effect stacks.", ua = "Шкода від морозу Гніву Азшари позначає ціль, знижуючи її швидкість пересування на $s1% на $d. Цей ефект накладається стосами." },
    { en = "Static Field creates a series of electrified tornados that radiate out. Touching a tornado inflicts $s1 Nature damage.", ua = "Статичне поле створює низку наелектризованих торнадо, що розходяться навсібіч. Дотик до торнадо завдає $s1 шкоди від сил природи." },
    { en = "The Storm Drake breathes lightning, creating a Static Field that inflicts $s1 Nature damage every $t1 sec while within the zone.", ua = "Штормовий Дрейк дихає блискавкою, створюючи Статичне Поле, що завдає $s1 шкоди від сил природи кожні $t1 с, поки ти перебуваєш у зоні." },
    { en = "Hymdall throws an enchanted blade towards a random player. Upon landing the blade begins to whirl, inflicting $193234s1 Physical damage every $193234t1 sec to all enemies within the zone.", ua = "Гімдалл кидає зачарований клинок у випадкового гравця. Приземлившись, клинок починає кружляти, завдаючи $193234s1 фізичної шкоди кожні $193234t1 с усім ворогам у зоні." },
    { en = "Hymdall blasts his horn, inflicting $s1 Physical damage to all enemies and summoning Storm Drakes to breathe lightning on his enemies.", ua = "Гімдалл сурмить у ріг, завдаючи $s1 фізичної шкоди всім ворогам і призиваючи Штормових Дрейків, щоб ті обдали його ворогів блискавкою." },
    { en = "Hymdall slashes at his current target, inflicting $s1 Physical damage and additional $s2 Physical damage every $t2 sec for $d.", ua = "Гімдалл рубає свою поточну ціль, завдаючи $s1 фізичної шкоди й додатково $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "While in range of Solsten, Hyrja is empowered with thunderous power enabling her to cast Eye of the Storm and Arcing Bolt. Every $192130t sec Solsten further empowers Hyrja increasing the damage of both abilities by $s1%.", ua = "Доки Гір'я перебуває в радіусі дії Сольстена, вона наповнюється громовою силою, що дає їй змогу творити «Око бурі» й «Стрибаючу блискавку». Кожні $192130t с Сольстен ще дужче наснажує Гір'ю, підвищуючи шкоду обох здібностей на $s1%." },
    { en = "While in range of Olmyr the Enlightened, Hyrja is empowered with holy light enabling her to cast Sanctify and Expel Light.  Every $192130t sec Olmyr further empowers Hyrja increasing the damage of both abilities by $s1%.", ua = "Доки Гір'я перебуває в радіусі дії Олмира Просвітленого, вона наповнюється святим світлом, що дає їй змогу творити «Освячення» й «Виверження світла». Кожні $192130t с Олмир ще дужче наснажує Гір'ю, підвищуючи шкоду обох здібностей на $s1%." },
    { en = "The caster creates an arc of lightning that leaps up to $x1 times, inflicting $s1 Nature damage to each target.", ua = "Заклинатель створює дугу блискавки, що перестрибує до $x1 раз(ів), завдаючи $s1 шкоди від сил природи кожній цілі." },
    { en = "Hyrja enchants a player to radiate a burst of light after $192048d, inflicting $s1 Holy damage to all players within $A1 yards.", ua = "Гір'я зачаровує гравця так, що той після $192048d випромінює спалах світла, завдаючи $s1 шкоди від Світла всім гравцям у межах $A1 метрів." },
    { en = "The caster creates a lightning storm that inflicts $200682s1 Nature damage every $200901t1 sec for $200901d. Standing within the eye of the storm reduces Nature damage taken by $203963s1%.", ua = "Створює грозову бурю, що завдає $200682s1 шкоди від сил природи кожні $200901t1 с протягом $200901d. Перебування в оці бурі зменшує отриману шкоду від сил природи на $203963s1%." },
    { en = "Hyrja charges her shield with light, launching a burst of energy towards her current target, inflicting $s2 Holy damage to all enemies in a line and knocking them back.", ua = "Гір'я заряджає свій щит світлом і випускає сплеск енергії в напрямку поточної цілі, завдаючи $s2 шкоди Світлом усім ворогам на лінії та відкидаючи їх." },
    { en = "The caster creates orbs of holy light that radiate out in all directions.  Touching the orb inflicts $s1 Holy damage.", ua = "Мовець створює сфери святого світла, що розходяться навсібіч. Дотик до сфери завдає $s1 шкоди від Світла." },
    { en = "Fenryr lashes out, inflicting $s1 Physical damage split between all enemies within $A1 yards.  \n\n\n\nThis attack will always hit and ignores all armor.", ua = "Фенрір накидається, завдаючи $s1 фізичної шкоди, поділеної між усіма ворогами в межах $A1 м.\n\n\n\nЦя атака завжди влучає та ігнорує всю броню." },
    { en = "Fenryr catches the scent of blood in the air and fixates on a random target for $196801d.", ua = "Фенрір ловить у повітрі запах крові й зосереджується на випадковій цілі протягом $196801d." },
    { en = "Fenryr leaps towards random players, inflicting $196496s1 Physical damage to all enemies within $196496A1 yards of the impact.\n\n\n\nIn addition, all targets bleed for $196497s1 Physical damage every $196497t1 sec.", ua = "Фенрір стрибає до випадкових гравців, завдаючи $196496s1 фізичної шкоди всім ворогам у межах $196496A1 м від місця удару.\n\n\n\nКрім того, всі цілі кровоточать, зазнаючи $196497s1 фізичної шкоди кожні $196497t1 с." },
    { en = "Increases damage done by $s1% for each nearby pack member.", ua = "Збільшує завдану шкоду на $s1% за кожного члена зграї поблизу." },
    { en = "Fenryr lets loose an unearthly howl, interrupting all casting for $d.", ua = "Фенрір видає неземне виття, перериваючи будь-яке чаклування на $d." },
    { en = "Inflicts $s1 Fire damage to all enemies every 1.5 sec for $193826d.  Each cast increases the damage of Ragnarok by $202494s2%.", ua = "Завдає $s1 шкоди вогнем усім ворогам кожні 1.5 с протягом $193826d. Кожне творіння збільшує шкоду Раґнароку на $202494s2%." },
    { en = "Skovald lashes out at his current target inflicting $s1 Physical damage.", ua = "Сковальд накидається на свою поточну ціль, завдаючи $s1 фізичної шкоди." },
    { en = "The bearer of the Aegis of Aggramar creates a shield for allies that absorbs all damage taken from the front for $d.", ua = "Носій Егіди Аґрамара створює для союзників щит, що поглинає всю шкоду, отриману спереду, протягом $d." },
    { en = "Creates an area of blazing flame that inflicts $s1 Fire damage every $t1 sec.\n\n\n\nThis effect stacks.", ua = "Створює зону палаючого полум'я, що завдає $s1 шкоди вогнем кожні $t1 с.\n\n\n\nЦей ефект накопичується." },
    { en = "A Flame of Woe consumes itself slowly, consuming $s1% of its maximum life every $t1 sec until it burns itself out.", ua = "Полум'я Скорботи повільно пожирає само себе, спалюючи $s1% свого максимального здоров'я кожні $t1 с, доки не догорить." },
    { en = "While protected by the Aegis of Aggramar Skovald summons a Flame of Woe that fixates on a random player every $193983t3 sec. As the Flame of Woe moves it spreads Infernal Flames.", ua = "Поки Сковальда захищає Егіда Аґрамара, він прикликає Полум'я Скорботи, що зосереджується на випадковому гравцеві кожні $193983t3 с. Рухаючись, Полум'я Скорботи поширює Пекельне Полум'я." },
    { en = "Skovald rushes at his target, inflicting $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d to enemies within $A1 yds.", ua = "Сковальд кидається на свою ціль, завдаючи $s1 шкоди вогнем, а також додатково $s2 шкоди вогнем кожні $t2 с протягом $d ворогам у межах $A1 м." },
    { en = "The bearer of the Aegis of Aggramar creates a shield that absorbs all damage taken from the front for $d.", ua = "Носій Егіди Аґрамара створює щит, що поглинає всю шкоду, отриману спереду, протягом $d." },
    { en = "Touching a fragment causes it to erupt stunning the target for $d and inflicting $s1 Holy damage.", ua = "Дотик до фрагмента спричиняє його вибух, оглушуючи ціль на $d і завдаючи $s1 шкоди Світлом." },
    { en = "Odyn creates a brand on each player that lasts for $197963d. The brand inflicts $197963s1 Holy damage every $197963t1 sec. Entering the corresponding rune on the ground cleanses the effect and applies Branded.", ua = "Одін позначає тавром кожного гравця, і воно триває $197963d. Тавро завдає $197963s1 шкоди Світлом кожні $197963t1 с. Ставши на відповідну руну на землі, гравець очищає ефект і отримує Таврований." },
    { en = "Upon cleansing a rune Odyn blesses the player increasing damage and healing done by $s1% and increasing movement speed by $s2%.  In addition, the player is restored to full health.", ua = "Очистивши руну, Одін благословляє гравця, збільшуючи завдану шкоду та зцілення на $s1% і підвищуючи швидкість пересування на $s2%. Крім того, гравцеві відновлюється все здоров'я." },
    { en = "Upon being reduced to 1 health Odyn removes the player from battle until he is defeated or all players are proven Unworthy of Odyn's respect.", ua = "Коли здоров'я гравця знижується до 1, Одін усуває його з бою, доки не буде переможений сам Одін або доки всі гравці не виявляться негідними поваги Одіна." },
    { en = "Odyn emits a pulse of energy inflicting $s1 Holy damage and knocks back all players within $a1 yards.", ua = "Одін випромінює імпульс енергії, що завдає $s1 шкоди Світлом і відкидає всіх гравців у межах $a1 м." },
    { en = "Odyn creates a spear of light at a player's location, inflicting $198058s2 Holy damage to all players within $198058a2 yards and $198058s1 Holy damage to all other players.\n\n\n\nIn addition, each spear inflicts $200988s1 Holy damage every $200988t1 sec to all nearby players.", ua = "Одін створює спис світла в місці перебування гравця, завдаючи $198058s2 шкоди Світлом усім гравцям у межах $198058a2 м і $198058s1 шкоди Світлом усім іншим гравцям.\n\n\n\nКрім того, кожен спис завдає $200988s1 шкоди Світлом кожні $200988t1 с усім гравцям поблизу." },
    { en = "Odyn causes all Spears of Light to burst into $s1 Glowing Fragments.", ua = "Одін змушує всі Списи Світла розколотися на $s1 Сяйливих Фрагментів." },
    { en = "The caster erupts in a torrent of electrical energy, inflicting $s1 Nature damage to all enemies.\n\n\n\nIn addition, each successful cast reduces the cast time of the next Surge by $199787s1%.  This effect stacks.", ua = "Чаклун вивергає потік електричної енергії, завдаючи $s1 шкоди від сил природи всім ворогам.\n\n\n\nКрім того, кожне успішне творіння зменшує час прочитання наступної Хвилі на $199787s1%. Цей ефект накопичується." },
    { en = "Odyn summons forth a Stormforged Obliterator to assist him.", ua = "Одін прикликає на допомогу собі Штормокованого Винищувача." },
    { en = "The skeleton increases its vigor periodically, increasing damage done by $s1%. This effect stacks.", ua = "Скелет періодично підвищує свою снагу, збільшуючи завдану шкоду на $s1%. Цей ефект накопичується." },
    { en = "Surrounds the caster with swirling essences of Bane over $193460D. Touching the essences of Bane inflicts $193513s1 Shadow damage to the triggered target and an additional $200194s1 Shadow damage to all enemies.", ua = "Оточує чаклуна вируючими есенціями Згуби протягом $193460D. Дотик до есенцій Згуби завдає $193513s1 шкоди від тіні зачепленій цілі та додатково $200194s1 шкоди від тіні всім ворогам." },
    { en = "Lets out a bone chilling scream, inflicting $s1 Shadow damage and fearing enemies within $A1 yards for $D.", ua = "Видає моторошний крик, що завдає $s1 шкоди від тіні та змушує ворогів у межах $A1 м тікати в жаху протягом $D." },
    { en = "Afflicts several targets within $228838A1 yards with Fetid Rot, inflicting $232408s1 Nature damage per stack every $193367T1 sec and decreasing healing received by $193367s2% per stack, periodically reducing in effectiveness.\n\n\n\nWhen removed, inflicts $228397s1 Nature damage to allies within $228397A1 yards, applying Fetid Rot to any target struck.", ua = "Уражає кілька цілей у межах $228838A1 м Смердючою Гниллю, що завдає $232408s1 шкоди від сил природи за стак кожні $193367T1 с і зменшує отримане зцілення на $193367s2% за стак, поступово втрачаючи дієвість.\n\n\n\nКоли ефект знімається, завдає $228397s1 шкоди від сил природи союзникам у межах $228397A1 м, накладаючи Смердючу Гниль на кожну вражену ціль." },
    { en = "Blast enemies with a frigid wind, knocking back all enemies and inflicting $193977s1 Frost damage.", ua = "Уражає ворогів крижаним вітром, відкидаючи всіх ворогів і завдаючи $193977s1 шкоди від морозу." },
    { en = "Strikes his target from beyond the void, inflicting $s1 Shadow damage.", ua = "Б'є свою ціль із-за меж Порожнечі, завдаючи $s1 шкоди від тіні." },
    { en = "Converts any remaining Essences of Bane into Risen Warriors, inflicting $193594s2 Shadow damage to targets within $193594A2 yards when summoned.", ua = "Перетворює всі залишкові Есенції Згуби на Повсталих Воїнів, що завдають $193594s2 шкоди від тіні цілям у межах $193594A2 м під час прикликання." },
    { en = "Creates a cosmic faultline in a targeted direction, inflicting $194218s1 Arcane damage to any enemies struck.", ua = "Створює космічний розлом у вибраному напрямку, завдаючи $194218s1 арканної шкоди всім враженим ворогам." },
    { en = "Creates a ripple in the void at their present location, inflicting increasing Shadow damage to all players.", ua = "Створює брижі в Порожнечі у своєму поточному місці, завдаючи всім гравцям дедалі більшої шкоди від тіні." },
    { en = "Fragments a target's soul into pieces, stunning them for $198551D. Each Fragment inflicts increasing Shadow damage every second to the target. This effect lasts for $194327D or until all Fragments are defeated.", ua = "Розколює душу цілі на шматки, оглушуючи її на $198551D. Кожен Фрагмент завдає цілі дедалі більшої шкоди від тіні щосекунди. Цей ефект триває $194327D або доки не буде знищено всі Фрагменти." },
    { en = "Conjures a rip the Twisting Nether at a target's location for $D, immediately inflicting $s1 Shadow damage to enemies within $A1 yards of the impact point. This additionally defiles the ground, inflicting $194235s1 Shadow damage every second.", ua = "Розверзає розрив у Викривленому Нижньому Світі в місці цілі на $D, миттєво завдаючи $s1 шкоди від тіні ворогам у межах $A1 м від точки удару. Крім того, це опоганює землю, завдаючи $194235s1 шкоди від тіні щосекунди." },
    { en = "Bellows forward, inflicting $227234s1 Shadow damage repeatedly to enemies in a frontal cone for $227233D.", ua = "Реве вперед, неодноразово завдаючи $227234s1 шкоди від тіні ворогам у фронтальному конусі протягом $227233D." },
    { en = "The turbulent waters of the Maw of Souls sometimes spew orbs of muck, inflicting $197858s1 Frost damage to enemies within $197858A1 yards of each impact location.", ua = "Бурхливі води Пащі Душ часом вивергають кулі багна, що завдають $197858s1 шкоди від морозу ворогам у межах $197858A1 м від кожного місця падіння." },
    { en = "Lashes out at a target, inflicting $197952s1 Physical damage three times and bleeding the target for an additional $185539s1 Physical damage every half-second for $D. This effect stacks.", ua = "Накидається на ціль, завдаючи $197952s1 фізичної шкоди тричі та змушуючи ціль кровоточити, завдаючи додатково $185539s1 фізичної шкоди кожні півсекунди протягом $D. Цей ефект накопичується." },
    { en = "The expelled Taint of the Sea leaves behind a Tainted Essence, which explodes after a short time, inflicting $s1 Frost damage to enemies within $A1 yards.", ua = "Вигнана Скверна Моря лишає по собі Опоганену Есенцію, що за короткий час вибухає, завдаючи $s1 шкоди від морозу ворогам у межах $A1 м." },
    { en = "Conjures a torrent of watery globules which pelt the Naglfar, inflicting $s1 Frost damage to several targets.", ua = "Прикликає потік водяних кульок, що ливнем б'ють по Наґлфару, завдаючи $s1 шкоди від морозу кільком цілям." },
    { en = "Taints a target, inflicting $s1 Frost damage every second for $D. When this aura is removed, the taint explodes, inflicting $197264s1 Frost damage to all players.", ua = "Заражає ціль, завдаючи $s1 шкоди від морозу щосекунди протягом $D. Коли цю ауру знято, зараза вибухає, завдаючи $197264s1 шкоди від морозу всім гравцям." },
    { en = "Fires a massive barrage of frost energy, inflicting $s1 Frost damage to enemies struck by the barrage.", ua = "Випускає потужний залп морозної енергії, завдаючи $s1 шкоди від морозу ворогам, у яких влучив залп." },
    { en = "Smashes the Naglfar when there are no targets within melee range, inflicting increasing $196534s1 Physical damage, increasing in damage by $196534s2% per cast.", ua = "Б'є по Наґлфару, коли в радіусі ближнього бою немає цілей, завдаючи $196534s1 фізичної шкоди, що зростає на $196534s2% з кожним застосуванням." },
    { en = "Buffets the Naglfar when there are no targets within melee range, inflicting $198520s1 Physical damage, increasing in damage by $198520s2% per cast.", ua = "Гатить по Наґлфару, коли в радіусі ближнього бою немає цілей, завдаючи $198520s1 фізичної шкоди, що зростає на $198520s2% з кожним застосуванням." },
    { en = "Helya's tentacle pierces the bottom of the Naglfar, knocking back nearby targets. After $197117s3 seconds, the tentacle inflicts $197117s1 Nature damage to players within $197117A1 yards, knocking them back.", ua = "Щупальце Гельї пробиває дно Наґлфару, відкидаючи цілі поблизу. За $197117s3 с щупальце завдає $197117s1 шкоди від сил природи гравцям у радіусі $197117A1 м, відкидаючи їх." },
    { en = "Conjures a torrent of watery globules which pelt the Naglfar, inflicting $s1 Frost damage to all targets.", ua = "Прикликає потік водяних кульок, що молотять по Наґлфару, завдаючи $s1 шкоди від морозу всім цілям." },
    { en = "The skitter's corpse forms a crystalline gas that fills your lungs, inflicting $s1 Nature damage every $t1 sec.", ua = "Труп скитера утворює кристалічний газ, що наповнює твої легені, завдаючи $s1 шкоди від сил природи кожні $t1 с." },
    { en = "The crystalline body shatters each time it is struck, creating tiny skitters that attack the party.", ua = "Кристалічне тіло розколюється від кожного удару, породжуючи крихітних скитерів, що нападають на групу." },
    { en = "Rokmora charges the ground with crystalline energy, causing enemies to suffer $198028s1 Nature damage every $t1 sec while moving. Lasts $198024d.", ua = "Рокмора заряджає землю кристалічною енергією, через що вороги під час руху дістають $198028s1 шкоди від сил природи кожні $t1 с. Триває $198024d." },
    { en = "The giant swings his arm, hurling crystals that inflict $s2 Nature damage to targets in a cone in front of the boss.", ua = "Велетень змахує рукою, жбурляючи кристали, що завдають $s2 шкоди від сил природи цілям у конусі перед босом." },
    { en = "Stomps the ground, inflicting $s1 Physical damage to enemies around caster and crushing all skitters.", ua = "Тупає по землі, завдаючи $s1 фізичної шкоди ворогам навколо та розчавлюючи всіх скитерів." },
    { en = "When Rokmora smashes the ground, living skitters explode, inflicting $s1 Nature damage to everyone.\n\n\n\nDamage from the skitter is reduced based on the amount of health it had remaining when it was ruptured.", ua = "Коли Рокмора б'є по землі, живі скитери вибухають, завдаючи $s1 шкоди від сил природи всім.\n\n\n\nШкода від скитера зменшується залежно від того, скільки здоров'я в нього лишалося на момент розриву." },
    { en = "Bashes an enemy for $s1 Nature damage.", ua = "Гатить по ворогові, завдаючи $s1 шкоди від сил природи." },
    { en = "Summons a pair of stone hands, which move inwards and explode for $198475s1 Nature damage on contact.", ua = "Прикликає пару кам'яних рук, що сходяться всередину й вибухають при дотику, завдаючи $198475s1 шкоди від сил природи." },
    { en = "Transforms himself into a Bellowing Idol and hides among other identical idols. As long as he remains within this form, the party continuously receives damage from falling debris.", ua = "Перетворюється на Ревучого ідола й ховається серед інших однакових ідолів. Доки він лишається в цій подобі, група безперервно зазнає шкоди від падаючих уламків." },
    { en = "The totems' screams tear at the cave, causing falling debris that inflict $193273s1 Physical damage to enemies near the impact.", ua = "Крики тотемів стрясають печеру, спричиняючи падіння уламків, що завдають $193273s1 фізичної шкоди ворогам біля місця удару." },
    { en = "Summons Bellowing Idols that scream and cause debris to fall onto the party.", ua = "Прикликає Ревучих ідолів, що верещать і обвалюють уламки на групу." },
    { en = "Retches bile, leaving behind toxic pools that inflict $210166s1 Nature damage every $210166t1 sec around the boss and inflicting additional $217851s1 Nature damage every $217851t1 sec to the party for $217851d.", ua = "Вивергає жовч, лишаючи навколо боса отруйні калюжі, що завдають $210166s1 шкоди від сил природи кожні $210166t1 с, і завдаючи групі додатково $217851s1 шкоди від сил природи кожні $217851t1 с протягом $217851d." },
    { en = "Naraxas latches onto her target with a spiked tongue and pulls them into her maw, inflicting $199705s1 Physical damage every $199705t1 sec for $199705d. Run away from Naraxas to avoid being eaten. Every time she eats, she gains an additional stack of Ravenous.", ua = "Нараксас вчіплюється в ціль шипастим язиком і затягує її собі в пащу, завдаючи $199705s1 фізичної шкоди кожні $199705t1 сек. протягом $199705d. Тікайте від Нараксас, щоб вас не зжерли. Щоразу, як вона когось пожирає, вона отримує додатковий заряд Ненаситності." },
    { en = "Fires a ball of venom at a random enemy's destination that does $188493s2 Nature damage on impact and leaves a pool of Toxic Bile.\n\n\n\nAlso, anyone caught within the pool has their movement speed reduced by $188494s2%.", ua = "Випускає кулю отрути в місце, де перебуває випадковий ворог, що завдає $188493s2 шкоди від сил природи при влучанні й лишає калюжу Отруйної жовчі.\n\n\n\nКрім того, у кожного, хто потрапив у калюжу, швидкість пересування знижується на $188494s2%." },
    { en = "Every victim Naraxas devours increases her damage by $s1%. This effect stacks.", ua = "Кожна жертва, яку пожирає Нараксас, збільшує її шкоду на $s1%. Цей ефект накопичується." },
    { en = "Offers their flesh to the Mother of Worms. Each drogbar eaten grants Naraxas a stack of Ravenous.", ua = "Пропонують свою плоть Матері Червів. Кожен з'їдений дроґбар дає Нараксас заряд Ненаситності." },
    { en = "Spews acid on the entire party when not engaged in melee combat, inflicting $s1 Nature damage.", ua = "Бризкає кислотою на всю групу, коли не веде ближнього бою, завдаючи $s1 шкоди від Природи." },
    { en = "As the crowd above Naraxas becomes more violent, they hurl rocks at the party, inflicting $s1 Physical damage to random targets every $199245t1 sec.", ua = "Що несамовитішим стає натовп над Нараксас, то більше вони жбурляють каміння в групу, завдаючи $s1 фізичної шкоди випадковим цілям кожні $199245t1 с." },
    { en = "Naraxas roars, increasing her attack speed by $s1% and the Physical damage she deals by $s2%.", ua = "Нараксас реве, збільшуючи свою швидкість атаки на $s1% і фізичну шкоду, яку завдає, на $s2%." },
    { en = "Leading a Charskin into a Crystal Spike stuns the Charskin for $d and increases all damage taken by $s4%.", ua = "Якщо завести Вугленошкірого на Кристалічний шпичак, той приголомшує Вугленошкірого на $d і збільшує всю отримувану ним шкоду на $s4%." },
    { en = "Every step the Charskin takes shatters the earth, inflicting $209921s1 Fire damage to enemies.", ua = "Кожен крок Вугленошкірого розколює землю, завдаючи $209921s1 шкоди від вогню ворогам." },
    { en = "The Underking smashes the ground, periodically inflicting $217090s1 Fire damage to targets not in cover, culminating in $200404s1 Fire damage to all exposed enemies.", ua = "Підземний король б'є по землі, періодично завдаючи $217090s1 шкоди від вогню цілям, що не сховалися, аж до $200404s1 шкоди від вогню всім незахищеним ворогам." },
    { en = "Causes crystal spikes to erupt at the enemy destination that inflict $200338s2 Nature damage to nearby targets and knocks them back.\n\n\n\nOnce formed, these spikes can be used as cover to protect the party from Magma Wave.", ua = "Спричиняє виверження кристалічних шпичаків у місці перебування ворога, що завдають $200338s2 шкоди від сил природи цілям поблизу й відкидають їх.\n\n\n\nПісля утворення ці шпичаки можна використовувати як укриття, щоб захистити групу від Магмової хвилі." },
    { en = "Every step the chieftain takes shatters the earth, inflicting $209921s1 Fire damage to enemies.", ua = "Кожен крок вождя розколює землю, завдаючи $209921s1 шкоди від вогню ворогам." },
    { en = "The longer the Charskin lives, the more stacks of Rising Inferno it receives increasing its movement speed and damage dealt by $216359s1%.", ua = "Що довше живе Вугленошкірий, то більше зарядів Дедалі більшого пекла він отримує, що збільшує його швидкість пересування й завдану шкоду на $216359s1%." },
    { en = "Slams the ground, causing granite spikes to erupt from the ground in a line, inflicting $s1 Nature damage and knocking back enemies nearby.", ua = "Гатить по землі, спричиняючи виверження гранітних шпичаків у лінію, що завдають $s1 шкоди від сил природи й відкидають ворогів поблизу." },
    { en = "Lava pools erupt through the cracks inflicting $s1 Fire damage every $t1 sec to enemies that enter them.", ua = "Із тріщин виривається лава, утворюючи калюжі, що завдають $s1 шкоди від Вогню кожні $t1 сек. ворогам, які в них заходять." },
    { en = "Fireballs erupt from the lava geyser, inflicting $s1 Fire damage to random targets every $216374t1 sec.", ua = "З лавового гейзера виривають вогняні кулі, завдаючи $s1 шкоди від вогню випадковим цілям кожні $216374t1 с." },
    { en = "Fixates on a random enemy target.", ua = "Зосереджується на випадковій ворожій цілі." },
    { en = "After Landslide, The Underking swings Khaz'goroth and causes the ground to erupt from under his current target, inflicting $s1 Nature damage.", ua = "Після Зсуву ґрунту Підземний король змахує Каз'ґоротом і спричиняє виверження землі під своєю поточною ціллю, завдаючи $s1 шкоди від сил природи." },
    { en = "Summons Molten Charskins that fixate on random targets.", ua = "Прикликає Розплавлених вугленошкірих, що зосереджуються на випадкових цілях." },
    { en = "Throws random stuff at an enemy, inflicting $s1 Nature damage.", ua = "Жбурляє в ворога чим попало, завдаючи $s1 шкоди від сил природи." },
    { en = "Inflicts $s2 Shadow damage, and knocks the target upwards.", ua = "Завдає $s2 шкоди від тіні й підкидає ціль угору." },
    { en = "Launches a bolt of stupendous energy, inflicting $s1 Arcane damage to the enemy.", ua = "Запускає блискавку приголомшливої енергії, завдаючи ворогові $s1 арканної шкоди." },
    { en = "Creates an explosion of wondrous energy, inflicting $s1 Arcane damage to all enemies within $a1 yds.", ua = "Створює вибух дивовижної енергії, завдаючи $s1 арканної шкоди всім ворогам у межах $a1 метрів." },
    { en = "Fills the area with magnificent energy, inflicting $227347s1 Arcane damage every $t1 sec for $d.", ua = "Наповнює ділянку величною енергією, що завдає $227347s1 арканної шкоди кожні $t1 с протягом $d." },
    { en = "Creates a bolt of dark energy. Upon impact, the bolt forms into a vortex, knocking enemies away from the impact.", ua = "Створює стрілу темної енергії. Влучивши, стріла обертається на вихор, що відкидає ворогів від точки удару." },
    { en = "Summons a group of winged assistants to assist the caster.", ua = "Прикликає гурт крилатих помічників на допомогу заклинателю." },
    { en = "Fires a bolt of moody energy, inflicting $s1 Shadow damage to the target.", ua = "Випускає стрілу похмурої енергії, завдаючи цілі $s1 шкоди від тіні." },
    { en = "Marks all players with a $@spellname227780. Upon expiration, inflicts $s1 Nature damage to all players within $A1 yds.", ua = "Позначає всіх гравців ефектом «$@spellname227780». Коли позначка спливає, завдає $s1 шкоди від сил природи всім гравцям у радіусі $A1 м." },
    { en = "Waves of water sweep in from the edges of the room, inflicting $s1 Frost damage to players they collide with.", ua = "Хвилі води накочують від країв зали, завдаючи $s1 шкоди від морозу гравцям, з якими стикаються." },
    { en = "Sends forth a watery bubble. Players coming into contact with the bubble cause it to explode, inflicting $s1 Frost damage and knocking players back.", ua = "Випускає водяну бульбашку. Якщо гравець торкається бульбашки, вона вибухає, завдаючи $s1 шкоди від морозу й відкидаючи гравців назад." },
    { en = "Sweeps out with a burning kick, knocking down players within $A1 yds for $d. This lights targets aflame, inflicting $227568s1 Fire damage immediately with an additional $227568s2 Fire damage every $227568t2 sec for $227568d.", ua = "Завдає удару палаючим копняком, збиваючи з ніг гравців у межах $A1 метрів на $d. Це підпалює цілі, завдаючи $227568s1 шкоди вогнем одразу й додатково $227568s2 шкоди вогнем кожні $227568t2 с протягом $227568d." },
    { en = "Dashes to multiple targets, striking them for $s3 Fire damage and creating a $@spellname227480 at that location.", ua = "Кидається до кількох цілей, б'ючи їх на $s3 шкоди вогнем і створюючи на тому місці «$@spellname227480»." },
    { en = "A blazing tornado forms, inflicting $s1 Fire damage to players inside it every $t1 sec.", ua = "Утворюється палаючий торнадо, що завдає $s1 шкоди вогнем гравцям усередині нього кожні $t1 с." },
    { en = "Step into the shadows and emerge behind a target, inflicting $s1 Nature damage immediately with an additional $s2 Nature damage every $t2 sec for $d.", ua = "Поринає в тінь і виринає за спиною цілі, миттєво завдаючи $s1 шкоди від сил природи та ще $s2 шкоди від сил природи кожні $t2 с протягом $d." },
    { en = "Colliding with a $@spellname228200 heats up Babblet, increasing her movement speed by $s1% for $d.", ua = "Зіткнувшись із «$@spellname228200», Бабблет розжарюється, і її швидкість руху зростає на $s1% протягом $d." },
    { en = "Jabs a target, inflicting $s1 Physical damage immediately and an additional $s2 Physical damage every $t2 sec for $d.", ua = "Штрикає ціль, миттєво завдаючи $s1 фізичної шкоди та ще $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "Hurls a candle-lit flame at a target, creating a burning patch. Coming into contact with the fire inflicts $s1 Fire damage every $t1 sec.", ua = "Жбурляє в ціль свічкове полум'я, утворюючи палаючу пляму. Дотик до вогню завдає $s1 шкоди вогнем кожні $t1 с." },
    { en = "Sprays soup at a target, inflicting $s1 Frost damage and applying $@spellname228013.", ua = "Бризкає на ціль супом, завдаючи $s1 шкоди від морозу й накладаючи «$@spellname228013»." },
    { en = "Reduces the movement speed of targets struck by $@spellname228011 by $s1% for $d. A $@spellname228013 target can move through a $@spellname228200 to extinguish the flames.", ua = "Знижує швидкість руху цілей, уражених «$@spellname228011», на $s1% протягом $d. Ціль під дією «$@spellname228013» може пройти крізь «$@spellname228200», щоб загасити полум'я." },
    { en = "Forks fly at a target, spinning in place and inflicting $232144s1 Physical damage to all players within $232144A1 yds every $t1 sec for $d.", ua = "У ціль летять виделки, обертаючись на місці й завдаючи $232144s1 фізичної шкоди всім гравцям у радіусі $232144A1 м кожні $t1 с протягом $d." },
    { en = "Strikes a target, inflicting $s1 Physical damage and increasing all damage taken for that target by $s2% for $d.", ua = "Б'є ціль, завдаючи $s1 фізичної шкоди й збільшуючи всю отримувану нею шкоду на $s2% протягом $d." },
    { en = "Channels the power of ancient candles, inflicting $228026s1 Fire damage to all players every $t1 sec for $d.", ua = "Спрямовує силу прадавніх свічок, завдаючи $228026s1 шкоди вогнем усім гравцям кожні $t1 с протягом $d." },
    { en = "Expunges old food, inflicting $s3 Nature damage to players within $A3 yds and knocking them back.", ua = "Вивергає зіпсовану їжу, завдаючи $s3 шкоди від сил природи гравцям у радіусі $A3 м і відкидаючи їх назад." },
    { en = "Ring out a dinner bell, increasing the haste of all allies by $s1% for $d.", ua = "Дзвонить в обідній дзвоник, збільшуючи поспіх усіх союзників на $s1% протягом $d." },
    { en = "Calls forth some Silver Forks to assist Coggleston in repelling intruders for $232154d.", ua = "Прикликає кілька срібних виделок на допомогу Коґлстону у відсічі непроханим гостям на $232154d." },
    { en = "Babblet focuses a player and sweeps towards them, inflicting $s1 Nature damage and blinding them for $d if she catches up to them.", ua = "Бабблет зосереджується на гравцеві й мчить до нього, завдаючи $s1 шкоди від сил природи та засліплюючи його на $d, якщо наздожене." },
    { en = "Upon defeating one of the castle servants, the surviving members are fully healed and gain $s2% damage done for the rest of the fight. This effect stacks.", ua = "Коли один зі слуг замку гине, уцілілі повністю зцілюються й отримують +$s2% до завданої шкоди до кінця бою. Цей ефект накопичується." },
    { en = "Coggleston's service allies make him immune to damage until they all have been defeated.", ua = "Слуги-союзники Коґлстона роблять його несприйнятливим до шкоди, доки всіх їх не буде здолано." },
    { en = "Inflicts $s1 Holy damage to a player. Jumps to players within 6 yards, increasing in damage with each jump.", ua = "Завдає гравцеві $s1 шкоди від світла. Перестрибує на гравців у радіусі 6 м, посилюючи шкоду з кожним стрибком." },
    { en = "Absorbs up to $s1 damage and makes the Maiden of Virtue immune to interrupts.", ua = "Поглинає до $s1 шкоди й робить Діву Чесноти несприйнятливою до переривань." },
    { en = "Creates a growing patch of holy ground, inflicting $227848s1 Holy damage every $227848t1 sec. for $227848d to players who enter.\n\n\n\nThis effect stacks.", ua = "Створює дедалі ширшу пляму священної землі, що завдає $227848s1 шкоди від світла кожні $227848t1 с протягом $227848d гравцям, які на неї заходять.\n\n\n\nЦей ефект накопичується." },
    { en = "Inflicts $s1 Holy damage to players and increases all damage taken by $s2% for the remainder of the encounter.\n\n\n\nThis effect stacks.", ua = "Завдає $s1 шкоди від світла гравцям і збільшує всю отримувану ними шкоду на $s2% до кінця бою.\n\n\n\nЦей ефект накопичується." },
    { en = "Incapacitates all players for $d, or until they take damage. After casting Mass Repentance, the Maiden of Virtue will cast Holy Bulwark, and then repeatedly cast Holy Wrath until Holy Bulwark is removed.", ua = "Знешкоджує всіх гравців на $d або доки вони не отримають шкоди. Прочитавши «Масове Каяття», Діва Чесноти створює «Священний Бастіон», а потім раз за разом творить «Священний Гнів», доки «Священний Бастіон» не буде знято." },
    { en = "Inflicts $s1 Holy damage, and increases Holy damage taken by $s2%.\n\n\n\nThis effect stacks.", ua = "Завдає $s1 шкоди від світла й збільшує отримувану шкоду від світла на $s2%.\n\n\n\nЦей ефект накопичується." },
    { en = "Midnight rears up, then stomps down with her front hooves. All players within $A1 yards suffer $s1 Fire damage and have any spells interrupted for $d.", ua = "Міднайт стає дибки, а потім гепає передніми копитами об землю. Усі гравці в радіусі $A1 м зазнають $s1 шкоди вогнем, а їхні закляття перериваються на $d." },
    { en = "The caster summons forth a line of spectral horses to charge across the battlefield. Any players caught in their path suffer $227645s1 Shadow damage.", ua = "Заклинатель прикликає вервечку примарних коней, що мчать через поле бою. Усі гравці на їхньому шляху зазнають $227645s1 шкоди від тіні." },
    { en = "Attumen swings his sword in an overhead chop.  All enemies within $a1 yards in front of Attumen take Physical damage and have their maximum health reduced to 50% of normal.", ua = "Аттумен розмахується мечем для нищівного удару згори. Усі вороги в радіусі $a1 м перед Аттуменом зазнають фізичної шкоди, а їхнє максимальне здоров'я знижується до 50% від звичного." },
    { en = "Midnight raises her front hooves and charges forward, inflicting $s1 Fire damage to all enemies in a cone in front of her.", ua = "Міднайт здіймає передні копита й кидається вперед, завдаючи $s1 шкоди вогнем усім ворогам у конусі перед нею." },
    { en = "The caster summons a specter to haunt their enemies. This specter will inflict $227415s1 Shadow damage to all players every 2 sec. until it is dispelled. Dispelling the wrong player will result in all players taking $227419s1 Shadow damage instead.", ua = "Заклинатель прикликає привида, що переслідує його ворогів. Цей привид завдає $227415s1 шкоди від тіні всім гравцям кожні 2 с, доки його не розвіють. Якщо розвіяти не того гравця, натомість усі гравці зазнають $227419s1 шкоди від тіні." },
    { en = "The caster swings their sword in a great arc, inflicting $s2 Shadow damage evenly divided amongst all targets in the sword's path.", ua = "Заклинатель розмахується мечем широкою дугою, завдаючи $s2 шкоди від тіні, що порівну розподіляється між усіма цілями на шляху клинка." },
    { en = "At 60% health, Moroes purges his dinner guests of all stuns and bonds and makes them immune to these effects for the remainder of the encounter.", ua = "На 60% здоров'я Мороес очищає своїх гостей за обіднім столом від усіх приголомшень і пут і робить їх несприйнятливими до цих ефектів до кінця бою." },
    { en = "Spins violently, inflicting $227651s1 Physical damage every $t1 sec to nearby enemies for $d.", ua = "Шалено обертається, завдаючи $227651s1 фізичної шкоди ворогам поблизу кожні $t1 с протягом $d." },
    { en = "Increases Moroes' attack speed by $s1% and damage done by $s2% for $d.", ua = "Збільшує швидкість атаки Мороеса на $s1% і завдану ним шкоду на $s2% протягом $d." },
    { en = "Lord Crispin Ference swings his weapon, inflicting $s2 Holy damage to targets in a line in front of the caster.", ua = "Лорд Кріспін Ференс розмахується зброєю, завдаючи $s2 шкоди від світла цілям на лінії перед заклинателем." },
    { en = "Drains $s1 mana and inflicts $s2 Arcane damage every $t1 sec to the current target in addition to stunning them for $d.", ua = "Висмоктує $s1 мани й завдає $s2 арканної шкоди кожні $t1 с поточній цілі, а також приголомшує її на $d." },
    { en = "Hurl a trap at the feet of a ghostly dinner guest in order to trap them within it, incapacitating them for $d.", ua = "Жбурляє пастку під ноги примарному гостю, щоб упіймати його в неї та знешкодити на $d." },
    { en = "Increases the damage and attack speed of nearby dinner guests.", ua = "Підвищує шкоду та швидкість атаки гостей вечері поблизу." },
    { en = "Throws an enchanted blade towards a random player. Upon landing the blade begins to whirl inflicting $227473s1 Physical damage every $227473t1 sec to all enemies within the zone.", ua = "Кидає зачарований клинок у випадкового гравця. Приземлившись, клинок починає вихритися, завдаючи $227473s1 фізичної шкоди кожні $227473t1 сек. усім ворогам у межах зони." },
    { en = "Smites an enemy, inflicting $s1  Holy damage.", ua = "Б'є ворога, завдаючи $s1 шкоди Світлом." },
    { en = "Blasts a random enemy, inflicting $s1 Arcane damage.", ua = "Б'є випадкового ворога, завдаючи $s1 арканної шкоди." },
    { en = "Strips the current target of their armor reducing their protection by $s1%. Moroes then provides his target with a complimentary robe, because its not \"that\" sort of dinner party.", ua = "Зриває з поточної цілі обладунок, зменшуючи її захист на $s1%. Тоді Мороес люб'язно надає цілі мантію, адже це не \"така вже\" вечеря." },
    { en = "Vanishes and appears behind a random enemy to garrote them.", ua = "Зникає і з'являється позаду випадкового ворога, щоб задушити його гароттою." },
    { en = "Heals Moroes for $s1% every $t1 sec for $d.", ua = "Зцілює Мороеса на $s1% кожні $t1 сек. протягом $d." },
    { en = "Appears behind the target and garrotes them, inflicting $s1 Physical damage on impact and $s2 Physical damage every $t2 sec.\n\n\n\nThis effect stacks.", ua = "З'являється позаду цілі та душить її гароттою, завдаючи $s1 фізичної шкоди при влучанні та $s2 фізичної шкоди кожні $t2 сек.\n\n\n\nЦей ефект накопичується." },
    { en = "Volatile Energy surges toward an enemy, inflicting $s1 Arcane damage to all enemies within $A1 yds on arrival.", ua = "Нестійка енергія мчить до ворога, завдаючи при досягненні $s1 арканної шкоди всім ворогам у межах $A1 м." },
    { en = "The Curator summons a ball of Volatile Energy that attacks its foes.", ua = "Куратор прикликає кулю нестійкої енергії, що атакує його ворогів." },
    { en = "Volatile Energy shoots lightning at a random enemy, inflicting $m1 Arcane damage. This damage increases every time the Volatile Energy casts Arc Lightning.", ua = "Нестійка енергія шле блискавку у випадкового ворога, завдаючи $m1 арканної шкоди. Ця шкода зростає щоразу, коли нестійка енергія застосовує Дугову блискавку." },
    { en = "The Curator fires a ball of lightning which inflicts $227285s1 Arcane damage on impact and creates an area of Power Discharge that periodically inflicts $m1 Arcane damage to players who remain inside.", ua = "Куратор стріляє кулею блискавки, що при влучанні завдає $227285s1 арканної шкоди і створює зону Розряду сили, яка періодично завдає $m1 арканної шкоди гравцям, що залишаються всередині." },
    { en = "The Curator evocates, taking $m1% increased damage and regaining mana.", ua = "Куратор застосовує заклинання прикликання, дістаючи на $m1% більше шкоди та відновлюючи ману." },
    { en = "The Curator explodes with energy after casting Evocation, inflicting $m1 Arcane damage. This effect is stronger for each Overload the Curator has cast.", ua = "Куратор вибухає енергією після застосування заклинання прикликання, завдаючи $m1 арканної шкоди. Цей ефект сильніший за кожне Перевантаження, яке застосував Куратор." },
    { en = "The Shade of Medivh summons a blizzard that fills the entire room for $d. All players suffer $227806s1 every second for $227806d and have their movement speed reduced by $227806s2%. This effect stacks.\n\n\n\nMoving will cancel one application of Ceaseless Winter.", ua = "Тінь Медіва прикликає хуртовину, що заповнює всю залу протягом $d. Усі гравці дістають $227806s1 щосекунди протягом $227806d, а їхня швидкість пересування зменшується на $227806s2%. Цей ефект накопичується.\n\n\n\nПересування скасовує одне накопичення Невпинної зими." },
    { en = "The Shade of Medivh freezes a player, inflicting $s1 Frost damage and stunning them indefinitely.\n\n\n\nThis effect is canceled when the target is hit by Inferno Bolt", ua = "Тінь Медіва заморожує гравця, завдаючи $s1 шкоди від морозу та приголомшуючи його на невизначений час.\n\n\n\nЦей ефект скасовується, коли ціль уражає Пекельний снаряд." },
    { en = "The Shade of Medivh pierces a player with Arcane magic for $d, inflicting $227641s1 Arcane damage every $t1 sec. This effect increases the Arcane damage taken of the target by $227644s1% for $227644d if Piercing Missiles is channeled for its full duration.", ua = "Тінь Медіва пронизує гравця чародійською магією протягом $d, завдаючи $227641s1 арканної шкоди кожні $t1 сек. Цей ефект підвищує арканну шкоду, якої зазнає ціль, на $227644s1% протягом $227644d, якщо Пронизливі снаряди каналізуються всю тривалість." },
    { en = "The Shade of Medivh wreaths several players in flames, trapping them for $228257d. If the player leaves the ring or if another player enters the ring it explodes, inflicting $228262s1 Fire damage to all players.", ua = "Тінь Медіва огортає кількох гравців полум'ям, ув'язнюючи їх на $228257d. Якщо гравець покине кільце або якщо до кільця ввійде інший гравець, воно вибухає, завдаючи $228262s1 шкоди вогнем усім гравцям." },
    { en = "The Shade of Medivh splits into 3 Guardian's Images.", ua = "Тінь Медіва розділяється на 3 Образи Вартового." },
    { en = "Blasts a random player with magic, inflicting $s1 Arcane damage.", ua = "Б'є випадкового гравця магією, завдаючи $s1 арканної шкоди." },
    { en = "Guardian's Image radiates with Arcane energy, inflicting $s1 Arcane damage every $228521t1 sec. In addition, this effect increase damage taken from Shimmer by $s2% for $d. This effect stacks.", ua = "Образ Вартового випромінює чародійську енергію, завдаючи $s1 арканної шкоди кожні $228521t1 сек. Крім того, цей ефект підвищує шкоду від Мерехтіння на $s2% протягом $d. Цей ефект накопичується." },
    { en = "The Shade of Medivh ignites a player and all players within $A1 yards of them. This effect inflicts $228958s1 Fire damage and an additional $228958s2 Fire damage every second for $228958d.\n\n\n\nInferno Bolt cancels the effect of Frostbite on any player that it hits.", ua = "Тінь Медіва підпалює гравця та всіх гравців у межах $A1 м від нього. Цей ефект завдає $228958s1 шкоди вогнем і додатково $228958s2 шкоди вогнем щосекунди протягом $228958d.\n\n\n\nПекельний снаряд скасовує дію Обмороження на будь-якому гравці, якого він уражає." },
    { en = "Contact with Loose Mana restores $227502s1% of total mana and applies a stack of $@spellname227502 to the target. If the Mana Devourer makes contact with Loose Mana, it will fully consume it, gaining $227466s1% of its total mana.", ua = "Контакт із Вільною маною відновлює $227502s1% загальної мани та накладає на ціль накопичення $@spellname227502. Якщо Пожирач мани контактує з Вільною маною, він повністю поглинає її, отримуючи $227466s1% своєї загальної мани." },
    { en = "Arcane lightning erupts from the Mana Devourer, inflicting $s1 Arcane damage to all enemies.", ua = "З Пожирача мани вивергається чародійська блискавка, завдаючи $s1 арканної шкоди всім ворогам." },
    { en = "The Mana Devourer erupts with energy, expelling all of its mana as $@spellname227296.", ua = "Пожирач мани вибухає енергією, викидаючи всю свою ману як $@spellname227296." },
    { en = "Energy fluctuations around the Mana Devourer create mana deficient zones, inflicting $s1 Shadow damage and consuming a stack of $@spellname227502 every $t1 sec. If the target has no stacks of $@spellname227502, the Energy Void will drain $227528s1% of their total mana every $t1 sec.", ua = "Коливання енергії довкола Пожирача мани створюють зони з дефіцитом мани, що завдають $s1 шкоди від тіні й поглинають один стак $@spellname227502 кожні $t1 с. Якщо ціль не має стаків $@spellname227502, Енергетичне Вакуум висмоктує $227528s1% її загальної мани кожні $t1 с." },
    { en = "A nearby area becomes unstable and explodes with Arcane energy, inflicting $s1 Arcane damage to all enemies within $A1 yds.", ua = "Ділянка поблизу стає нестабільною й вибухає чародійською енергією, завдаючи $s1 арканної шкоди всім ворогам у межах $A1 метрів." },
    { en = "Power surges through the targets body, inflicting $s4 Arcane damage every $t4 sec and increasing all damage done by $s2%", ua = "Тілом цілі прокочується сплеск сили, завдаючи $s4 арканної шкоди кожні $t4 сек. і збільшуючи всю завдану шкоду на $s2%" },
    { en = "Upon reaching full mana, the Mana Devourer discharges a massive explosion, inflicting $s1 Arcane damage.", ua = "Досягнувши повної мани, Пожирач мани вивільняє потужний вибух, завдаючи $s1 арканної шкоди." },
    { en = "Viz'aduum the Watcher orders the Legion Command Ship to fire a Bombardment. This effect shoots several missiles at the area for $229283d, inflicting $229285s1 Fire damage to all players within $229285A1 yards of each impact.", ua = "Віз'адуум Спостерігач наказує командному кораблю Легіону відкрити вогонь Бомбардуванням. Цей ефект випускає кілька снарядів по місцевості протягом $229283d, завдаючи $229285s1 шкоди вогнем усім гравцям у межах $229285A1 м від кожного влучання." },
    { en = "Upon reaching the Command Ship Viz'aduum the Watcher will attempt to stabilize the Rift that is connected to distant Legion worlds. If he successfully stablizes the rift, reinforcements will stream through at a significantly increased rate.", ua = "Сягнувши командного корабля, Віз'адуум Спостерігач спробує стабілізувати Розлом, що з'єднаний із далекими світами Легіону. Якщо він успішно стабілізує розлом, підкріплення поллється крізь нього значно швидше." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec for $d. When Chaotic Shadows is dispelled or expires it causes orbs of Explosive Shadows to form nearby and move away from the target.", ua = "Завдає $s1 шкоди від тіні кожні $t1 сек. протягом $d. Коли Хаотичні тіні розвіюються або спливають, поблизу цілі утворюються кулі Вибухових тіней, що віддаляються від неї." },
    { en = "Inflicts $s1 Shadow damage to enemies within $A1 yards of the triggered Chaotic Shadows orb.", ua = "Завдає $s1 шкоди від тіні ворогам у межах $A1 м від спрацьованої кулі Хаотичних тіней." },
    { en = "The Legion Soul Harvester inflicts $229905s1 Fire damage every 1 sec to enemies within 15 yards of it.", ua = "Збирач душ Легіону завдає $229905s1 шкоди вогнем щосекунди ворогам у межах 15 м від себе." },
    { en = "Inflicts Fire damage to the target and an additional $s2 Fire damage every $t2 sec for $d, reducing the target's movement speed by $s3%. This effect stacks.", ua = "Завдає цілі шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d, зменшуючи швидкість пересування цілі на $s3%. Цей ефект накопичується." },
    { en = "Fires Shadowy Phlegm at the target which inflicts $230067s1 Shadow damage to enemies within $230067A1 yards of the target.", ua = "Випускає в ціль Тіньовий слиз, що завдає $230067s1 шкоди від тіні ворогам у межах $230067A1 м від цілі." },
    { en = "Viz'aduum the Watcher commands the Legion Command Ship to target an enemy with Fel Beam. Fel Beam inflicts $229248s1 Fire damage every $229248t1 sec and creates Fel Flames in its wake.", ua = "Віз'адуум Спостерігач наказує командному кораблю Легіону навести на ворога Промінь Скверни. Промінь Скверни завдає $229248s1 шкоди вогнем кожні $229248t1 сек. і лишає по собі Полум'я Скверни." },
    { en = "Inflicts $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d. This effect stacks.", ua = "Завдає $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 сек. протягом $d. Цей ефект накопичується." },
    { en = "Inflicts $s1 Fire damage to all enemies in front of the caster, knocking the target back.", ua = "Завдає $s1 шкоди вогнем усім ворогам перед заклинателем, відкидаючи ціль назад." },
    { en = "Ivanyr links 3 random players together, repelling them from each other for $196805d. When Nether Link expires, a pool of arcane energy is created in the space between the targeted players for $196806d. The pool of energy inflicts $196824s1 Arcane damage to all players in within the area every second.", ua = "Іванир зв'язує разом 3 випадкових гравців, відштовхуючи їх одне від одного протягом $196805d. Коли Зв'язок Нижнього Світу спливає, у просторі між цілями утворюється калюжа чародійської енергії на $196806d. Калюжа енергії завдає $196824s1 арканної шкоди всім гравцям у межах зони щосекунди." },
    { en = "Ivanyr blasts his target with Arcane energy, inflicting $s1 Arcane damage.", ua = "Іванир б'є ціль чародійською енергією, завдаючи $s1 арканної шкоди." },
    { en = "As Ivanyr drains energy from the Night Crystal it becomes unstable, increasingly emitting Charged Bolts. Each bolt travels out from the crystal and inflicts $220597s1 Arcane damage every $220597t1 sec to any player it touches.", ua = "Поки Іванир витягує енергію з Нічного кристала, той стає нестабільним, дедалі частіше випускаючи Заряджені блискавки. Кожна блискавка вилітає з кристала та завдає $220597s1 арканної шкоди кожні $220597t1 сек. будь-якому гравцеві, якого торкнеться." },
    { en = "Ivanyr channels power from the Night Crystal, periodically gaining stacks of Overcharge.", ua = "Іванир черпає силу з Нічного Кристала, періодично накопичуючи заряди Перевантаження." },
    { en = "Haste and all damage done increased by $s1% per stack.", ua = "Поспіх і вся завдана шкода збільшені на $s1% за кожен заряд." },
    { en = "Ivanyr marks several random players with Volatile Magic. After $d., the magic explodes, inflicting $196570s1 to all players within $196570A1 yards.", ua = "Іванир позначає кількох випадкових гравців Нестабільною Магією. За $d. магія вибухає, завдаючи $196570s1 усім гравцям у радіусі $196570A1 ярдів." },
    { en = "Corstilax summons an orb of unstable energy for $220500d. This effect inflicts $220500s1 Arcane damage to all nearby players every second.", ua = "Корстилакс прикликає сферу нестабільної енергії на $220500d. Цей ефект щосекунди завдає $220500s1 арканної шкоди всім гравцям поблизу." },
    { en = "Nightwell energy increases haste by $s1%. This effect stacks.", ua = "Енергія Нічного Колодязя збільшує поспіх на $s1%. Цей ефект накопичується." },
    { en = "The nearby conduit bursts, applying a stack of Nightwell Energy to all players and creating several pools of residual energy for $d.\n\n\n\nPlayers that enter the pools gain a stack of Nightwell Energy.", ua = "Сусідній провід вибухає, накладаючи заряд Енергії Нічного Колодязя на всіх гравців і створюючи кілька калюж залишкової енергії на $d.\n\n\n\nГравці, які заходять у калюжі, отримують заряд Енергії Нічного Колодязя." },
    { en = "Corstilax channels at a player for $d, firing a missile at their location every second. When the missile impacts it inflicts $196074s1 Arcane damage to all players within $196074A1 yards, increasing their Arcane damage taken by $196074s2% for $196074d. In addition, this effect inflicts $196213s1 Arcane damage to all players.", ua = "Корстилакс зосереджується на гравцеві протягом $d, щосекунди випускаючи снаряд у його місце. Влучаючи, снаряд завдає $196074s1 арканної шкоди всім гравцям у радіусі $196074A1 ярдів і збільшує отримувану ними арканну шкоду на $196074s2% на $196074d. Крім того, цей ефект завдає $196213s1 арканної шкоди всім гравцям." },
    { en = "Corstilax places a random player in Quarantine, stunning them for $195804d. or until the Quarantine is shattered. This effect inflicts $195804s3 Arcane damage every second.\n\n\n\nQuarantine is shattered when a player channels on it for $195826d.", ua = "Корстилакс поміщає випадкового гравця в Карантин, оглушуючи його на $195804d. або доки Карантин не буде зруйновано. Цей ефект щосекунди завдає $195804s3 арканної шкоди.\n\n\n\nКарантин руйнується, коли гравець зосереджується на ньому протягом $195826d." },
    { en = "Corstilax draws in all players, removing one stack of Nightwell Energy every $s1 sec for $d.\n\n\n\nWhen Cleansing Force ends, all players within $196142A1 yards suffer $196142s1 Arcane damage. This effect stuns the target for $203649d if they still have stacks of Nightwell Energy.", ua = "Корстилакс притягує всіх гравців, знімаючи один заряд Енергії Нічного Колодязя кожні $s1 сек. протягом $d.\n\n\n\nКоли Очищувальна Сила завершується, усі гравці в радіусі $196142A1 ярдів зазнають $196142s1 арканної шкоди. Цей ефект оглушує ціль на $203649d, якщо в неї досі є заряди Енергії Нічного Колодязя." },
    { en = "Fissures erupt to form a spire, inflicting $s1 Shadow damage to all players within $A1 yards, knocking them back.", ua = "Тріщини розверзаються, утворюючи шпиль, що завдає $s1 шкоди від тіні всім гравцям у радіусі $A1 ярдів і відкидає їх." },
    { en = "General Xakal tears open a rift at a random player's location that persists for the remainder of the fight. After 3 seconds, the rift will explode into a Fel Spire if any players are within the targeted location.", ua = "Генерал Ксакал розриває розлом у місці випадкового гравця, який лишається до кінця бою. За 3 секунди розлом вибухне Шпилем Скверни, якщо хоч хтось із гравців перебуватиме в цільовій ділянці." },
    { en = "General Xakal slams his axe into the ground, inflicting $s1 Physical damage to all players, knocking them back.", ua = "Генерал Ксакал з усієї сили б'є сокирою об землю, завдаючи $s1 фізичної шкоди всім гравцям і відкидаючи їх." },
    { en = "Dread Felbats claw at their target, inflicting Physical damage. In addition, their movement speed and damage done is increased by $s2% for the remainder of the fight. This effect stacks.", ua = "Жахливі кажани Скверни шматують кігтями свою ціль, завдаючи фізичної шкоди. Крім того, їхня швидкість руху та завдана шкода збільшуються на $s2% до кінця бою. Цей ефект накопичується." },
    { en = "Shadow Slash leaves energy in its wake for $220441ds. This effect inflicts $s1 Shadow damage to all players within the area every second.", ua = "Розтин Тіні лишає по собі енергію на $220441ds. Цей ефект щосекунди завдає $s1 шкоди від тіні всім гравцям у цій ділянці." },
    { en = "Dread Felbats fire a bolt of energy at a random player's location, inflicting $s1 Shadow damage to all players within $A1 yards of the targeted location.", ua = "Жахливі кажани Скверни випускають заряд енергії в місце випадкового гравця, завдаючи $s1 шкоди від тіні всім гравцям у радіусі $A1 ярдів від цільового місця." },
    { en = "General Xakal empowers his axe with dark magic, creating a wave of energy that shoots out towards a random player. This effect inflicts $212071s1 Shadow damage to all players hit by the wave.", ua = "Генерал Ксакал наповнює свою сокиру темною магією, створюючи хвилю енергії, що мчить до випадкового гравця. Цей ефект завдає $212071s1 шкоди від Тіні всім гравцям, яких зачепила хвиля." },
    { en = "Nal'tira spits venom at a random player's location that persists for $200036d. Players inside the venom suffer $200040s1 Arcane damage every second and have their haste reduced by $200040s2%.", ua = "Нал'тіра випльовує отруту в місце випадкового гравця, і та лишається на $200036d. Гравці в отруті щосекунди зазнають $200040s1 арканної шкоди, а їхній поспіх знижено на $200040s2%." },
    { en = "Nal'tira pulls random players to her location, connecting each player together with a web that inflicts $200284s1 Arcane damage every second. This effect persists until players that are webbed together move at least 30 yards away from each other.", ua = "Нал'тіра притягує випадкових гравців до себе, сплітаючи кожного з них павутиною, що щосекунди завдає $200284s1 арканної шкоди. Цей ефект триває, доки сплетені разом гравці не віддаляться один від одного щонайменше на 30 ярдів." },
    { en = "Nal'tira teleports to a distant player and executes a series of attacks for $d. Each attack inflicts $199812s1 Arcane damage to all players in front of her every $t1 sec.", ua = "Нал'тіра телепортується до віддаленого гравця й виконує серію атак протягом $d. Кожна атака завдає $199812s1 арканної шкоди всім гравцям перед нею кожні $t1 сек." },
    { en = "Vicious Manafangs attempt to devour a player, rooting them in place and inflicting Physical damage every second for $d.\n\n\n\nThis effect is canceled if the Vicious Manafang suffers 30% of its maximum health in damage.", ua = "Лючі манозуби намагаються пожерти гравця, знерухомлюючи його та щосекунди завдаючи фізичної шкоди протягом $d.\n\n\n\nЦей ефект скасовується, якщо лютий манозуб зазнає шкоди в розмірі 30% свого максимального здоров'я." },
    { en = "Inflicts $s1 Arcane damage every $t1 sec to all players within the nova's area of effect. In addition, the nova pushes players away as it moves outwards.", ua = "Завдає $s1 арканної шкоди кожні $t1 сек. усім гравцям у ділянці дії нови. Крім того, нова відштовхує гравців, поширюючись назовні." },
    { en = "Advisor Vandros brands a player with unstable energy that marks their current location every $t1 sec for $d. After 1.5 sec, the marked location explodes inflicting $220875s1 Arcane damage to all players within $220875A1 yards.", ua = "Радник Вандрос таврує гравця нестабільною енергією, що позначає його поточне місце кожні $t1 сек. протягом $d. За 1.5 сек. позначене місце вибухає, завдаючи $220875s1 арканної шкоди всім гравцям у радіусі $220875A1 ярдів." },
    { en = "Advisor Vandros blasts a player with dark energy, inflicting $s1 Arcane damage. Each successful cast increases his damage done and haste by $s2% for $d. This effect stacks.", ua = "Радник Вандрос вражає гравця темною енергією, завдаючи $s1 арканної шкоди. Кожне успішне прочитання збільшує його завдану шкоду та поспіх на $s2% на $d. Цей ефект накопичується." },
    { en = "When Advisor Vandros reaches 50% health remaining, he teleports all players away and attempts to banish them in time. If he is not re-engaged within $d, all players are lost in time and die.", ua = "Коли в Радника Вандроса лишається 50% здоров'я, він телепортує всіх гравців геть і намагається вигнати їх у часі. Якщо його не залучити до бою знову протягом $d, усі гравці губляться в часі й гинуть." },
    { en = "Timeless Wraiths breach time, inflicting $203954s1 Arcane damage to all players within $203954A1 yards every second.", ua = "Позачасові примари пробивають час, завдаючи $203954s1 арканної шкоди всім гравцям у радіусі $203954A1 ярдів щосекунди." },
    { en = "Timeless Wraiths lock a player in time, stunning them for $d.", ua = "Позачасові примари сковують гравця в часі, оглушуючи його на $d." },
    { en = "Advisor Vandros periodically summons Chrono Shards that explode after 8 sec. This effect inflicts $203833s1 Arcane damage to all players within $203833A1 yards.", ua = "Радник Вандрос періодично прикликає Хроноскалки, що вибухають за 8 сек. Цей ефект завдає $203833s1 арканної шкоди всім гравцям у радіусі $203833A1 ярдів." },
    { en = "Chrono Shards detonate after 8 sec, inflicting $s1 Arcane damage to all players within $203833A1 yards.", ua = "Хроноскалки детонують за 8 сек., завдаючи $s1 арканної шкоди всім гравцям у радіусі $203833A1 ярдів." },
    { en = "Advisor Vandros summons $s1 Force Bombs that detonate after $202975d. Each Force Bomb inflicts $203087s1 Arcane damage to all players within $203087A1 yards and creates a Force Nova.", ua = "Радник Вандрос прикликає $s1 Бомб Сили, що детонують за $202975d. Кожна Бомба Сили завдає $203087s1 арканної шкоди всім гравцям у радіусі $203087A1 ярдів і створює Нову Сили." },
    { en = "The caster calls down Fel Mortars from the sky, striking at the locations of random enemies. Each impact creates a zone of Furious Flames that will inflict Fire damage to all enemies in the area.", ua = "Заклинач закликає з неба міномети Скверни, що б'ють у місця випадкових ворогів. Кожне влучання створює зону Несамовитого Полум'я, що завдаватиме вогнем шкоди всім ворогам у ній." },
    { en = "The caster empowers their attacks with shadowy energies, inflicting an additional $363073s1 Shadow damage with each successful melee attack for $d.", ua = "Заклинач наповнює свої атаки тіньовою енергією, завдаючи додатково $363073s1 шкоди від тіні з кожною успішною атакою ближнього бою протягом $d." },
    { en = "The Fel Chains binding Tirathon's glaives together burn all in their path with Fel energy.", ua = "Ланцюги Скверни, що сковують глейви Тіратона докупи, спалюють енергією Скверни все на своєму шляху." },
    { en = "The Glaive inflicts $s1 Physical damage to all players in its path.", ua = "Глейв завдає $s1 фізичної шкоди всім гравцям на своєму шляху." },
    { en = "Standing in the flames inflicts $s1 Fire damage to the vicitm.", ua = "Перебування в полум'ї завдає $s1 вогнем шкоди жертві." },
    { en = "The caster unleashes a Furious Blast of energy, inflicting $s1 Fire damage to all players within $A1 yards. The blast leaves behind a zone of Furious Flames that will inflict Fire damage to all players who enter it.", ua = "Заклинач вивільняє Несамовитий Вибух енергії, завдаючи $s1 вогнем шкоди всім гравцям у радіусі $A1 ярдів. Вибух лишає по собі зону Несамовитого Полум'я, що завдаватиме вогнем шкоди всім гравцям, які до неї увійдуть." },
    { en = "The caster channels their Hatred, resulting in a beam of Fel energy that eminates from their eyes.  Standing in the beam inflicts $s1 Fire damage to the victim.", ua = "Заклинач зосереджує свою Ненависть, унаслідок чого з його очей б'є промінь енергії Скверни. Перебування в промені завдає $s1 вогнем шкоди жертві." },
    { en = "The caster leaps to a nearby location, knocking back all enemies in the process. Once the leap is completed, the caster begins to cast Furious Blast.", ua = "Заклинач стрибає до сусіднього місця, відкидаючи при цьому всіх ворогів. Завершивши стрибок, заклинач починає творити Несамовитий Вибух." },
    { en = "The caster's soul radiates Fel Energy, burning nearby targets every $t1 sec with $192503s1 Fire damage.", ua = "Душа заклинача випромінює енергію Скверни, обпалюючи цілі поблизу кожні $t1 сек. на $192503s1 вогнем шкоди." },
    { en = "The caster metamorphoses, bringing their inner demonic energy to the fore. All damage dealt while Metamorphosed is increased by $s2%", ua = "Заклинач перевтілюється, вивільняючи назовні свою внутрішню демонічну енергію. Уся шкода, завдана під час Метаморфози, збільшена на $s2%" },
    { en = "Corrupts an enemy upon death, causing them to explode after $d, inflicting $206020s1 Shadow damage to themselves and all allies within $206020A1 yards.", ua = "Опоганює ворога по його смерті, через що той вибухає за $d, завдаючи $206020s1 шкоди від тіні собі та всім союзникам у радіусі $206020A1 ярдів." },
    { en = "Inflicts $s2 Physical damage and slowly turns enemies to stone, reducing movement speed by $s1% per stack. Causes petrification at $U stacks.", ua = "Завдає $s2 фізичної шкоди й повільно обертає ворогів на камінь, знижуючи швидкість пересування на $s1% за кожен стак. Спричиняє скам'яніння при $U стаках." },
    { en = "Silences an enemy, preventing it from casting spells for $d.", ua = "Сковує ворога мовчанням, не даючи йому творити закляття протягом $d." },
    { en = "Bite an enemy target, inflicting Physical damage equal to $s1% of normal damage.", ua = "Кусає ворожу ціль, завдаючи фізичної шкоди в розмірі $s1% від звичайної." },
    { en = "The caster saps the souls of their enemies. Victims who have their souls sapped will have the cooldown of their next ability used within $200904d increased by $200904s2 sec.", ua = "Той, хто творить закляття, висотує душі своїх ворогів. У жертв, чиї душі висотано, перезарядження наступної здібності, використаної протягом $200904d, зростає на $200904s2 сек." },
    { en = "Fires a missile towards an enemy at range. When this missile lands, it deals $199916s1 Shadow damage to all enemies within $199916A1 yards of that location and $199918s1 Shadow damage to enemies within the area every $199918t1 sec for $199918d.", ua = "Випускає снаряд у напрямку віддаленого ворога. Коли цей снаряд приземляється, він завдає $199916s1 шкоди від тіні всім ворогам у межах $199916A1 метрів від того місця й $199918s1 шкоди від тіні ворогам на цій ділянці кожні $199918t1 с протягом $199918d." },
    { en = "Charge an enemy, causing $206318s2 damage and stunning it for $206318d.", ua = "Налітає на ворога, завдаючи $206318s2 шкоди й оглушуючи його на $206318d." },
    { en = "Shouts at nearby enemies causing them to flee in fear for $d.", ua = "Кричить на ворогів поблизу, змушуючи їх тікати в страху протягом $d." },
    { en = "The caster scans the thoughts of all nearby enemies, disorienting them after $d. Facing the caster will negate the disorientation.", ua = "Той, хто творить закляття, проникає в думки всіх ворогів поблизу й дезорієнтує їх за $d. Якщо повернутися обличчям до нього, дезорієнтації не буде." },
    { en = "Summons a Tormernting Orb that will periodically disorient players unless they are facing the Tormenting Orb.", ua = "Прикликає Стражденну сферу, що періодично дезорієнтує гравців, доки вони не повернуться до неї обличчям." },
    { en = "Channels Fel Power into the target, increasing size by $s1% and Physical damage done by $s1%.", ua = "Спрямовує в ціль силу Скверни, збільшуючи її розмір на $s1% і фізичну шкоду на $s1%." },
    { en = "Inflicts Shadow damage to all enemies within $A1 yards of the target.", ua = "Завдає шкоди від тіні всім ворогам у радіусі $A1 метрів від цілі." },
    { en = "Activating a countermeasure floods the chamber with frost magic, causing Ash'golm and Living Embers to become $@spellname1244248.\n\n\n\nIn addition, removes $@spellname1243566 from Ash'golm and causes $@spellname1243622s to subside.", ua = "Активація протидії заливає камеру магією морозу, через що Аш'ґолм і Живі жарини стають під дією «$@spellname1244248».\n\n\n\nКрім того, з Аш'ґолма знімається «$@spellname1243566», а «$@spellname1243622s» вщухає." },
    { en = "Ash'golm's molten skin sears the air around him, inflicting $1243556s1 Fire damage to all players every $t1 sec. This effect stacks.", ua = "Розпечена шкіра Аш'ґолма обпалює повітря довкола нього, завдаючи $1243556s1 шкоди вогнем усім гравцям кожні $t1 с. Цей ефект накопичується." },
    { en = "Ash'golm stomps the ground causing a volcanic fissure to erupt molten lava, inflicting $s1 Fire damage every $t1 sec to players within. Players hit by the impact are knocked away.", ua = "Аш'ґолм гупає по землі, спричиняючи виверження розплавленої лави з вулканічної тріщини, що завдає $s1 шкоди вогнем щодвох $t1 сек гравцям усередині. Гравців, яких зачепило виверженням, відкидає геть." },
    { en = "Ash'golm releases a flurry of embers at players, inflicting $s1 Fire damage every $t1 sec for $d.\n\n\n\nUpon removal, the embers coalesce into a Living Ember.", ua = "Аш'ґолм випускає шквал жарин у гравців, завдаючи $s1 шкоди вогнем кожні $t1 сек протягом $d.\n\n\n\nПісля зняття жарини зливаються в Живу жарину." },
    { en = "Encases all fire elementals in a deep freeze, preventing all actions and increasing the chance to be critically struck by $s1% for $d.", ua = "Скрижаняє всіх вогняних елементалів, не даючи їм діяти й підвищуючи шанс отримати критичний удар на $s1% протягом $d." },
    { en = "Inflicts $s1 Fire damage to a random player.", ua = "Завдає $s1 шкоди вогнем випадковому гравцеві." },
    { en = "Glazer focuses a destructive beam that chases a random player, inflicting $s1 Shadow damage to players within $a1 yards every $1245311t1 sec. The damage and speed of the beam increases by $1245313s1% every $1245310t1 sec.\n\n\n\nReflecting the beam at Glazer using a Warden's Lens interrupts $@spellname1245308 and removes a portion of his $@spellname1245393.", ua = "Зорій зосереджує руйнівний промінь, що переслідує випадкового гравця, завдаючи $s1 шкоди від тіні гравцям у радіусі $a1 метрів кожні $1245311t1 сек. Шкода і швидкість променя зростають на $1245313s1% кожні $1245310t1 сек.\n\n\n\nВідбиття променя назад у Зорія за допомогою Лінзи вартового перериває «$@spellname1245308» і знімає частину його «$@spellname1245393»." },
    { en = "Glazer fires a ray of dark magic at their current target, inflicting $1243772s1 Shadow damage every $t1 sec for $d, pushing them away. \n\n\n\nUpon expiration, the target releases $s1 volatile orbs of energy that bounce around the arena, inflicting $1243774s1 Shadow damage.", ua = "Зорій випускає промінь темної магії в поточну ціль, завдаючи $1243772s1 шкоди від тіні кожні $t1 сек протягом $d і відштовхуючи її.\n\n\n\nПісля завершення ціль вивільняє $s1 нестійких енергетичних сфер, що відскакують ареною, завдаючи $1243774s1 шкоди від тіні." },
    { en = "Glazer releases lingering eyes that release felfire at random players, inflicting $1245122s1 Chaos damage to players within $1245122a1 every $1245116t1 sec for $1245116d.\n\n\n\nUpon expiration, it leaves a lingering pool of felfire, inflicting $1245166s1 Chaos damage every $1245166t1 to players within.", ua = "Зорій випускає блукаючі очі, що поливають випадкових гравців вогнем Скверни, завдаючи $1245122s1 шкоди хаосом гравцям у радіусі $1245122a1 кожні $1245116t1 сек протягом $1245116d.\n\n\n\nПісля завершення лишається калюжа вогню Скверни, що завдає $1245166s1 шкоди хаосом щомиті $1245166t1 гравцям усередині." },
    { en = "Delivers a turn kick, knocking the victim backwards.", ua = "Завдає удару ногою з розвороту, відкидаючи жертву назад." },
    { en = "Delivers a roundhouse kick, knocking the victim down.", ua = "Завдає кругового удару ногою, збиваючи жертву з ніг." },
    { en = "The caster summons an Avatar of Vengeance at a nearby location. The Avatar will periodically summon a Spirit of Vengenace nearby that can only be seen when exposed by the Light of Elune.", ua = "Той, хто творить закляття, прикликає Аватара помсти неподалік. Аватар періодично прикликає поблизу Духа помсти, якого можна побачити лише тоді, коли його викриває Світло Елуни." },
    { en = "Creates a pool of Deepening Shadows at the victim's feet that grows outward. These shadows will recede if their source is covered in Elune's Light.\n\nStanding in the shadows causes the victim to suffer $213395s1 Shadow damage every second.", ua = "Створює біля ніг жертви калюжу Густішої тіні, що розростається назовні. Ці тіні відступають, якщо їхнє джерело огорнути Світлом Елуни.\n\nПеребуваючи в тіні, жертва щосекунди зазнає $213395s1 шкоди від тіні." },
    { en = "Cordana hurls her Moonglaive at a random location. Any target caught in its path causes it to explode for $197541s1 damage in a $197541A1 yard radius around the target.", ua = "Кордана жбурляє свою Місячну глеву у випадкове місце. Будь-яка ціль на її шляху спричиняє вибух, що завдає $197541s1 шкоди в радіусі $197541A1 метрів навколо цілі." },
    { en = "The caster summons several spirits of Fel energy that slowly move across the platform. If a player comes into contact with one of these spirits an explosion of Fel energy occurs, inflicting $197506s1 Fire damage to all players within $197506A1 yards and knocking them back.", ua = "Той, хто творить закляття, прикликає кількох духів енергії Скверни, що повільно сунуть платформою. Якщо гравець торкнеться одного з цих духів, стається вибух енергії Скверни, що завдає $197506s1 шкоди вогнем усім гравцям у радіусі $197506A1 метрів і відкидає їх назад." },
    { en = "Hits the target for $s1 Shadow damage.", ua = "Б'є ціль, завдаючи $s1 шкоди від тіні." },
    { en = "The Light of Elune shines down on you, making you immune to the effects of Deepening Shadows and revealing any enemies Veiled in Shadow.\n\n\n\nWhile Elune's Light persists you are unable to enter stealth.", ua = "Світло Елуни осяює тебе, роблячи несприйнятливим до дії Густішої тіні й викриваючи всіх ворогів, Огорнутих тінню.\n\n\n\nДоки триває Світло Елуни, ти не можеш увійти в непомітність." },
    { en = "The caster creates a dizzying array of Fel Glaives that spiral out from the center of the platform. Victims caught in the path of these glaives suffer $197334s1 Fire damage.", ua = "Той, хто творить закляття, створює запаморочливий рій Глев Скверни, що по спіралі розлітаються від центру платформи. Жертви на шляху цих глев зазнають $197334s1 шкоди вогнем." },
    { en = "Cordana slips into the shadows, hiding from her enemies until she is revealed by Elune's Light or after $197333d has passed. While Veiled in Shadow, Cordana will create a pattern of Fel Glaives that inflict Physical damage to anyone caught in their path.", ua = "Кордана зникає в тінях, ховаючись від ворогів, доки її не викриє Світло Елуни або доки не мине $197333d. Огорнута тінню, Кордана створює візерунок із Глев Скверни, що завдають фізичної шкоди всім, хто потрапляє на їхній шлях." },
    { en = "Throws a shield of Holy energy, inflicting Holy damage upon impact and additionally blocking sight and movement for $153000D.", ua = "Метає щит зі святої енергії, завдаючи святої шкоди при влучанні та додатково на $153000D перекриваючи огляд і рух." },
    { en = "Channels consecrated power, inflicting increasing Holy damage to all enemies every second for $153006D.", ua = "Підтримує освячену силу, щот секунди завдаючи всім ворогам дедалі більшої святої шкоди впродовж $153006D." },
    { en = "Focuses pious energy, erupting all of the Hallowed Ground immediately.\n\n$@spelltooltip154526", ua = "Зосереджує побожну енергію, миттєво підриваючи всю Освячену землю.\n\n$@spelltooltip154526" },
    { en = "Creates a fissure of Holy energy, inflicting Holy damage to enemies who remain in the Sanctified Ground.", ua = "Створює розлам святої енергії, завдаючи святої шкоди ворогам, що лишаються на Освяченій землі." },
    { en = "Creates a patch of Hallowed Ground, inflicting $154526s1 Holy damage to enemies within $154526A1 yards when triggered.", ua = "Створює ділянку Освяченої землі, яка при спрацюванні завдає $154526s1 святої шкоди ворогам у радіусі $154526A1 ярдів." },
    { en = "Inflicts $s1 damage to an enemy.", ua = "Завдає ворогові $s1 шкоди." },
    { en = "Twists the souls of fallen Draenei, forming multiple tori of Shadow damage at a specific location. The epicenter of this ability is safe from damage.", ua = "Спотворює душі полеглих дренеїв, утворюючи в певному місці кілька кілець тіньової шкоди. Епіцентр цієї здібності безпечний від шкоди." },
    { en = "Rips the spirits out of fallen Auchenai partisans, forcing them to fight.", ua = "Вириває духів полеглих прибічників Аукенай, змушуючи їх битися." },
    { en = "Stuns a target, inflicting frequent Holy damage to additional allies within $149962A2 yards for $D.", ua = "Приголомшує ціль, на $D завдаючи частої святої шкоди ще й союзникам у радіусі $149962A2 ярдів." },
    { en = "A word of darkness that causes $s1 Shadow damage instantly, and an additional $s2 Shadow damage every $T2 sec. over $d.", ua = "Слово темряви, що миттєво завдає $s1 тіньової шкоди, а також додатково $s2 тіньової шкоди кожні $T2 сек. упродовж $d." },
    { en = "Blasts the target for $154415s1 Shadowfrost damage.", ua = "Уражає ціль, завдаючи $154415s1 тіньоморозної шкоди." },
    { en = "Charges a target, creating multiple prisms of Holy energy which radiate away from the caster. These prisms inflict $154301s1 Holy damage upon contact.", ua = "Кидається на ціль, створюючи кілька призм святої енергії, що розходяться променями від заклинача. Ці призми завдають $154301s1 святої шкоди при дотику." },
    { en = "Blasts a target with a burst of Arcane energy, inflicting $154235s1 Arcane damage.", ua = "Уражає ціль спалахом чародійської енергії, завдаючи $154235s1 арканної шкоди." },
    { en = "Focuses nearby Arcane energies into several orbs of immense power. Upon contact or after $154174D, these orbs explode, inflicting $154232s1 Arcane damage to enemies within $154232A2 yards.", ua = "Зосереджує довколишні чародійські енергії в кілька сфер величезної сили. При дотику або через $154174D ці сфери вибухають, завдаючи $154232s1 арканної шкоди ворогам у радіусі $154232A2 ярдів." },
    { en = "Blazing Tricksters are wreathed in intense flames, burning any targets who come too close to them.\n\n\n\nBurned targets are disoriented and suffer $s2 Fire damage every sec. for $d.", ua = "Палаючих пройдисвітів огортає шалене полум'я, що обпікає всіх, хто підходить надто близько.\n\n\n\nОбпалені цілі дезорієнтовані й щосекунди зазнають $s2 шкоди вогнем упродовж $d." },
    { en = "Azzakel becomes immune to damage and opens the Claws of Argus, his portal to the demon homeworld. Demons spew forth from the portal for the duration of the channel.", ua = "Аззакель стає несприйнятливим до шкоди й відчиняє Пазурі Аргуса — свій портал до рідного світу демонів. Поки триває каналізація, з порталу ринуть демони." },
    { en = "The caster conjures a blast of Fel fire, inflicting $s1 Fire damage to the target.", ua = "Заклинач прикликає спалах вогню Скверни, завдаючи цілі $s1 шкоди вогнем." },
    { en = "Azzakel lashes out with a blow backed by Fel energy, inflicting Physical damage, knocking the targeted player back, and increasing the player's Physical damage taken by $s3% for $d.", ua = "Аззакель завдає удару, підкріпленого енергією Скверни, що спричиняє фізичну шкоду, відкидає ціль і на $d збільшує фізичну шкоду, яку вона зазнає, на $s3%." },
    { en = "Azzakel engulfs a player in Fel flame, inflicting $153392s1 Fire damage to the affected player every $153392t1 sec for  $153392d.\n\n\n\nWhen Curtain of Flame deals damage, it will also spread to any other players within $153400A1 yards of the affected player.", ua = "Аззакель огортає гравця полум'ям Скверни, завдаючи ураженому гравцеві $153392s1 шкоди вогнем кожні $153392t1 сек. упродовж $153392d.\n\n\n\nКоли Завіса полум'я завдає шкоди, вона також поширюється на всіх інших гравців у радіусі $153400A1 ярдів від ураженого гравця." },
    { en = "Stomps the ground with fel-infused might, inflicting $s1 Physical damage to all targets within a cone in front of the caster, and knocking them back.", ua = "Гупає по землі з підсиленою Скверною міццю, завдаючи $s1 фізичної шкоди всім цілям у конусі перед заклиначем і відкидаючи їх." },
    { en = "Azzakel slams into the ground, creating a pool of Fel energy.", ua = "Аззакель б'є по землі, створюючи калюжу енергії Скверни." },
    { en = "Players in a Fel Pool suffer $153616s1 Fire damage every $153616t1 sec.", ua = "Гравці в Калюжі Скверни зазнають $153616s1 шкоди вогнем кожні $153616t1 сек." },
    { en = "Tendrils of Fel fire reach out from a Fel Pool, leaving burning patches of flame on the ground.\n\n\n\nThese patches inflict $153726s1 Fire damage every $153726t1 sec. to any players within them.", ua = "Вусики Скверни тягнуться з калюжі Скверни, лишаючи на землі ділянки палаючого вогню.\n\n\n\nЦі ділянки завдають $153726s1 шкоди вогнем кожні $153726t1 сек. усім гравцям, що стоять у них." },
    { en = "Applies wasting magic to the target, inflicting $s1 Shadow damage to the target every $t1 sec for $d.\n\n\n\nIf Unstable Affliction is dispelled, it will detonate, inflicting $156956s1 Shadow damage to the dispeller and silencing them for $156956d.", ua = "Накладає на ціль виснажливу магію, завдаючи $s1 тіньової шкоди кожні $t1 сек. упродовж $d.\n\n\n\nЯкщо Нестабільну неміч розвіяти, вона детонує, завдаючи $156956s1 тіньової шкоди тому, хто розвіяв, і занімовуючи його на $156956d." },
    { en = "Fires a bolt of shadow energy at the targeted player, inflicting $s1 Shadow damage.", ua = "Стріляє розрядом тіньової енергії в ціль-гравця, завдаючи $s1 тіньової шкоди." },
    { en = "The caster calls down a Felborne Abyssal that relentlessly pursues a chosen target.", ua = "Заклинач прикликає народженого Скверною безодняка, що невпинно переслідує обрану ціль." },
    { en = "Burns the target, inflicting $s1 Fire damage and reducing the target's movement speed by $s2% for $d.", ua = "Обпалює ціль, завдаючи $s1 шкоди вогнем і знижуючи її швидкість пересування на $s2% упродовж $d." },
    { en = "Sends a wave of fire to the current target, inflicting $s1 Fire damage.", ua = "Посилає хвилю вогню в поточну ціль, завдаючи $s1 шкоди вогнем." },
    { en = "Ignites the target's flesh, inflicting $s1 Fire damage every $t1 sec. for $d.", ua = "Запалює плоть цілі, завдаючи $s1 шкоди вогнем кожні $t1 сек. упродовж $d." },
    { en = "Inflicts $s1 Shadow damage every $t1 sec.", ua = "Завдає $s1 тіньової шкоди кожні $t1 сек." },
    { en = "Unleashes energy at the enemy, causing $s1 Chaos damage.", ua = "Вивільняє енергію на ворога, завдаючи $s1 шкоди Хаосу." },
    { en = "Corrupts the target's blood with malevolent energy, inflicting $s1 Shadow damage every $t1 sec. for $d.", ua = "Опоганює кров цілі лиховісною енергією, завдаючи $s1 тіньової шкоди кожні $t1 сек. упродовж $d." },
    { en = "Fiery meteors rain down at the targeted location, inflicting $156856s1 Fire damage to all enemies within the area every $156856t1 sec. for $d.", ua = "Вогняні метеори сиплються на вказане місце, завдаючи $156856s1 шкоди вогнем усім ворогам у цій ділянці кожні $156856t1 сек. упродовж $d." },
    { en = "Drains the life from a player, inflicting $s1 Shadow damage to them every $t1 sec. for $d. Each time it deals damage it also restores $s2% of the caster's health.", ua = "Висмоктує життя з гравця, завдаючи йому $s1 тіньової шкоди кожні $t1 сек. упродовж $d. Щоразу, завдаючи шкоди, ефект також відновлює $s2% здоров'я заклинача." },
    { en = "Demonic energy erupts from the afflicted player when Seed of Malevolence expires, creating a Bloom of Malevolence. Any player who enter the Bloom of Malevolence are afflicted with Seed of Malevolence.", ua = "Коли Зерно Злоби спливає, із ураженого гравця виривається демонічна енергія, утворюючи Квіт Злоби. Будь-який гравець, що входить у Квіт Злоби, отримує Зерно Злоби." },
    { en = "Creates a wave of Chaos energy that travels forward from Teron'gor, inflicting $s1 Chaos damage to any players it touches.", ua = "Створює хвилю енергії Хаосу, що рухається вперед від Терон'ґора, завдаючи $s1 шкоди Хаосом усім гравцям, яких торкнеться." },
    { en = "Curses the target, reducing their movement speed by $s1%.", ua = "Проклинає ціль, знижуючи її швидкість пересування на $s1%." },
    { en = "Fires a bolt of whirling energies at the target, inflicting $s1 Chaos damage.", ua = "Стріляє в ціль вихором енергій, завдаючи $s1 шкоди Хаосом." },
    { en = "Leaps towards the target, inflicting $s1 Physical damage to any targets within $A1 yards of the impact position, and knocking them back.", ua = "Стрибає до цілі, завдаючи $s1 фізичної шкоди всім, хто перебуває в межах $A1 ярдів від місця падіння, і відкидає їх." },
    { en = "Plants a demonic seed in the target, inflicting $s1 Shadow damage every $t1 sec. for $d.\n\n\n\nIf the target dies, or after $d, the seed will explode, inflicting $156924s1 Shadow damage to all targets within 10 yards of them, and applying Seed of Malevolence to them.", ua = "Саджає в ціль демонічне сім'я, завдаючи $s1 тіньової шкоди кожні $t1 сек. упродовж $d.\n\n\n\nЯкщо ціль гине, або через $d, сім'я вибухає, завдаючи $156924s1 тіньової шкоди всім цілям у радіусі 10 ярдів від неї та накладаючи на них Сім'я Злоби." },
    { en = "Applies a curse of writhing agony to the target, inflicting $s1 Shadow damage every $t1 sec.\n\n\n\nThe damage dealt by Agony will increase each time it deals damage.", ua = "Накладає на ціль прокляття звивистої агонії, завдаючи $s1 тіньової шкоди кожні $t1 сек.\n\n\n\nШкода від Агонії зростає щоразу, коли ефект завдає шкоди." },
    { en = "Smashes the ground, inflicting $s2 Physical damage to nearby enemies and stunning them for $d.", ua = "Розбиває землю, завдаючи $s2 фізичної шкоди ворогам поблизу та приголомшуючи їх на $d." },
    { en = "Earthen shards strike the ground, inflicting $s2 Nature damage to enemies within $r yards of the impact point. Spikes radiate outwards, inflicting $149963s1 Nature damage to enemies that they come in contact with.", ua = "Земляні скалки б'ють по землі, завдаючи $s2 шкоди від сил природи ворогам у радіусі $r ярдів від точки влучання. Шипи розходяться навсібіч, завдаючи $149963s1 шкоди від сил природи ворогам, яких вони зачіпають." },
    { en = "Hot magma erupts outwards, causing $s1 Fire damage to enemies in a line.", ua = "Гаряча магма вивергається назовні, завдаючи $s1 шкоди вогнем ворогам у лінію." },
    { en = "Ignites the area surrounding the caster, causing $149996s1 Fire damage to all nearby enemies every $t1 sec. for $d.", ua = "Підпалює простір навколо того, хто творить закляття, завдаючи $149996s1 шкоди вогнем усім ворогам поблизу кожні $t1 с. протягом $d." },
    { en = "Inflicts $s1 Fire damage every $t1 sec. Also reduces attack, casting, and movement speed by $s3%. \n\n\n\nIf is not dispelled, it will periodically ignite another ally with Choking Ashes.", ua = "Завдає $s1 шкоди вогнем кожні $t1 с. Також знижує швидкість атаки, творення заклять і пересування на $s3%. \n\n\n\nЯкщо не розвіяти, ефект періодично підпалюватиме ще одного союзника Задушливим попелом." },
    { en = "Scorches an enemy for Fire damage.", ua = "Обпалює ворога, завдаючи шкоди вогнем." },
    { en = "Inflicts $s1 Fire damage every $t1 sec. Also reduces attack, casting, and movement speed by $s3%.", ua = "Завдає $s1 шкоди Вогнем кожні $t1 с. Також знижує швидкість атаки, прочитання заклять і пересування на $s3%." },
    { en = "Smashes the ground, inflicting $s1 Physical damage to enemies within $r yards in a frontal cone and stunning them for $d.", ua = "Б'є об землю, завдаючи $s1 фізичної шкоди ворогам у межах $r ярдів у конусі попереду й приголомшуючи їх на $d." },
    { en = "Instantly burns an enemy, then inflicts additional Fire damage every $t1 sec. for $d. \n\n\n\nIf Dancing Flames is not dispelled, it will jump to another nearby enemy.", ua = "Миттєво обпалює ворога, а потім завдає додаткової шкоди вогнем кожні $t1 с. протягом $d. \n\n\n\nЯкщо не розвіяти Танцюючі язики полум'я, ефект перестрибне на іншого ворога поблизу." },
    { en = "Lava splashes to the floor, inflicting $s1 Fire damage every $t1 sec. to enemies in the lava pool.", ua = "Лава розхлюпується по підлозі, завдаючи $s1 шкоди вогнем кожні $t1 с. ворогам у калюжі лави." },
    { en = "Creates a Molten Impact near an enemy target, summoning a Molten Elemental. The impact inflicts $s1 Fire damage to enemies near the center, decreasing in damage the further away targets are.", ua = "Створює Розплавлений удар біля ворожої цілі, прикликаючи Розплавленого елементаля. Удар завдає $s1 шкоди вогнем ворогам поблизу центру, причому шкода зменшується, що далі від нього перебувають цілі." },
    { en = "Smashes the ground, inflicting $s1 Physical damage to all enemies and knocking them back.", ua = "Б'є об землю, завдаючи $s1 фізичної шкоди всім ворогам і відкидаючи їх назад." },
    { en = "Inflicts $s3 Physical damage to enemies and increases the damage dealt by the caster by $s2% for $d. Weakens the will of nearby miners.", ua = "Завдає $s3 фізичної шкоди ворогам і збільшує шкоду того, хто творить закляття, на $s2% протягом $d. Послаблює волю шахтарів поблизу." },
    { en = "Inflicts $s2% of normal melee damage to all targets in front of the caster. Stuns for $d.", ua = "Завдає $s2% звичайної шкоди ближнього бою всім цілям перед тим, хто творить закляття. Приголомшує на $d." },
    { en = "Calls nearby miners to assist in battle.", ua = "Скликає шахтарів поблизу на допомогу в бою." },
    { en = "Pummels the target, inflicting $s1% weapon damage and causing them to take $s2% additional damage for $d.\n\n\n\nAlso causes the target to bleed, inflicting $s3 Physical damage every $t3 sec.", ua = "Молотить ціль, завдаючи $s1% шкоди зброї та змушуючи її зазнавати на $s2% більше шкоди протягом $d.\n\n\n\nТакож спричиняє кровотечу в цілі, завдаючи $s3 фізичної шкоди кожні $t3 с." },
    { en = "Leaps to enemies, smashing them into the ground. Captured Miners are ordered to attack crushed targets.", ua = "Стрибає до ворогів, вгамселюючи їх у землю. Полонені шахтарі дістають наказ атакувати розчавлені цілі." },
    { en = "Scorching air reduces the cast speed of nearby players by $s1%.", ua = "Розпечене повітря знижує швидкість творення заклять гравців поблизу на $s1%." },
    { en = "Roltall summons a deadly heat wave that inflicts $s1 Fire damage every second and pushes all enemies away for $152867d.", ua = "Ролталл прикликає смертоносну хвилю спеки, що завдає $s1 шкоди вогнем щосекунди та відштовхує всіх ворогів протягом $152867d." },
    { en = "Roltall throws burning slag that ignites all enemies within the targeted area, inflicting $s1 Fire damage every second.", ua = "Ролталл жбурляє палаючий шлак, що підпалює всіх ворогів у цільовій ділянці, завдаючи $s1 шкоди вогнем щосекунди." },
    { en = "Roltall summons a fiery boulder that inflicts $152742s2 Fire damage to all enemies within $152742A2 yards of impact. The fiery boulder rolls forward and inflicts $152843s1 Fire damage to all enemies in its path, stunning them for $152843d.", ua = "Ролталл прикликає вогняний валун, що завдає $152742s2 шкоди вогнем усім ворогам у межах $152742A2 ярдів від місця падіння. Вогняний валун котиться вперед і завдає $152843s1 шкоди вогнем усім ворогам на своєму шляху, приголомшуючи їх на $152843d." },
    { en = "Gug'rokk summons pools of magma at every player's location for $d. Each pool inflicts $s1 Fire damage every second to all players within them.", ua = "Ґуґ'рокк прикликає калюжі магми в місці кожного гравця протягом $d. Кожна калюжа завдає $s1 шкоди вогнем щосекунди всім гравцям, які в ній стоять." },
    { en = "Gug'rokk ignites all players, inflicting $s1 Fire damage and increasing their Fire damage taken by $s2% for $d.", ua = "Ґуґ'рокк підпалює всіх гравців, завдаючи $s1 шкоди вогнем і збільшуючи шкоду вогнем, якої вони зазнають, на $s2% протягом $d." },
    { en = "Gug'rokk summons an Unstable Slag elemental.", ua = "Ґуґ'рокк прикликає елементаля Нестабільного шлаку." },
    { en = "Unstable Slag elementals siphon flames from a kiln, unleashing in a torrent of fire every $150732t1 sec. Each torrent inflicts $s1 Fire damage to 2 random players.", ua = "Елементалі Нестабільного шлаку висмоктують полум'я з печі, вивільняючи потік вогню кожні $150732t1 с. Кожен потік завдає $s1 шкоди вогнем 2 випадковим гравцям." },
    { en = "Gug'rokk blasts an enemy with molten slag, inflicting $s1 Fire damage and granting him one stack of Molten Core.", ua = "Ґуґ'рокк уражає ворога розплавленим шлаком, завдаючи $s1 шкоди вогнем і даруючи собі один заряд Розплавленого осердя." },
    { en = "Gug'rokk's damage is increased by $s2% for $d. Causes a Molten Barrage upon reaching 3 stacks.", ua = "Шкода Ґуґ'рокка збільшена на $s2% протягом $d. Після досягнення 3 зарядів спричиняє Розплавлений шквал." },
    { en = "Gug'rokk explodes with molten energy, inflicting $s1 Fire damage to all enemies. This effect consumes Molten Core.", ua = "Ґуґ'рокк вибухає розплавленою енергією, завдаючи $s1 шкоди вогнем усім ворогам. Цей ефект споживає Розплавлене осердя." },
    { en = "When Unstable Slag elementals reach the kiln they become empowered, inflicting $152092s1 Fire damage to all players every $t1 sec.", ua = "Коли елементалі Нестабільного шлаку досягають печі, вони посилюються, завдаючи $152092s1 шкоди вогнем усім гравцям кожні $t1 с." },
    { en = "Railmaster Rocketspark locks on to the players, increasing his damage done by $s1% every $166559t1 sec. until he can be interrupted.", ua = "Майстер рейок Рокетспарк наводиться на гравців, збільшуючи завдану ним шкоду на $s1% кожні $166559t1 с., доки його не перервуть." },
    { en = "Borka the Brute charges forward trampling over anything in his path inflicting $s1 Physical damage and interrupting spell casts for $d.", ua = "Борка Бугай мчить уперед, затоптуючи все на своєму шляху, завдаючи $s1 фізичної шкоди й перериваючи творення заклять протягом $d." },
    { en = "Railmaster Rocketspark quickly devises a new plan when Borka the Brute is slain and begins launching missiles that inflict $163929s1 Fire damage every $t2 sec.\n\n\n\nIn addition, Rocketspark starts Locking On!.", ua = "Коли Борку Бугая вбито, Майстер рейок Рокетспарк швидко вигадує новий план і починає запускати ракети, що завдають $163929s1 шкоди вогнем кожні $t2 с.\n\n\n\nКрім того, Рокетспарк починає Наведення!." },
    { en = "Launches missiles at up to $s1 enemy targets. Each missile inflicts $162513s1 Fire damage to all targets within $162513A1 yards of the impact.", ua = "Запускає ракети по щонайбільше $s1 ворожих цілях. Кожна ракета завдає $162513s1 шкоди вогнем усім цілям у межах $162513A1 ярдів від місця влучання." },
    { en = "Borka the Brute slips into an uncontrolled blood craze when Pauli Rocketspark is slain, increasing both his damage done by $s1% and his attack speed by $s2%.", ua = "Коли Паулі Рокетспарка вбито, Борка Бугай впадає в некеровану криваву нестяму, збільшуючи і завдану ним шкоду на $s1%, і швидкість своїх атак на $s2%." },
    { en = "Fires volleys of missiles inflicting $162422s1 Fire damage to two targets every 1 second for $d.", ua = "Випускає залпи ракет, що завдають $162422s1 шкоди вогнем двом цілям щосекунди протягом $d." },
    { en = "Inflicts $s1 Physical damage to all players and interrupts casting for $d.", ua = "Завдає $s1 фізичної шкоди всім гравцям і перериває творення заклять протягом $d." },
    { en = "Shoots an homing shell, inflicting $160776s1 Fire damage to the Assault Cannon.", ua = "Вистрілює самонавідним снарядом, завдаючи $160776s1 шкоди вогнем Штурмовій гарматі." },
    { en = "Throws a grenade at a target's location, inflicting Fire damage to enemies within $161153A1 yards.", ua = "Кидає гранату в місце цілі, завдаючи шкоди вогнем ворогам у межах $161153A1 ярдів." },
    { en = "Throws a Blackrock Grenade at a targeted location, inflicting $161073s1 Fire damage to enemies within $161153A1 yards and knocking them back.", ua = "Кидає Гранату Блекрок у вказане місце, завдаючи $161073s1 шкоди вогнем ворогам у межах $161153A1 ярдів і відкидаючи їх назад." },
    { en = "Carrying Shrapnel, allowing the use of a Blackrock Turret's Shrapnel Cannon ability.\n\n$@spelltooltip166545", ua = "Несе Шрапнель, що дозволяє використовувати здібність Шрапнельної гармати Турелі Блекрок.\n\n$@spelltooltip166545" },
    { en = "Readies a salvo of Suppressive Fire, interrupting casts for $161220D and inflicting rapid Physical damage. Suppressive Fire lasts $160681D. Targets may hide behind cover to mitigate the damage from this ability.", ua = "Готує залп Придушувального вогню, перериваючи творення заклять протягом $161220D і завдаючи стрімкої фізичної шкоди. Придушувальний вогонь триває $160681D. Цілі можуть сховатися за укриттям, щоб зменшити шкоду від цієї здібності." },
    { en = "Fires a concentrated salvo of molten slag at a targeted location, engulfing the area in flames. These flames increase Fire damage taken by $166570s2% and inflict $166570s1 Fire damage every second for $166570D. This effect stacks.", ua = "Вистрілює зосередженим залпом розплавленого шлаку у вказане місце, охоплюючи ділянку полум'ям. Це полум'я збільшує шкоду вогнем, якої зазнають, на $166570s2% і завдає $166570s1 шкоди вогнем щосекунди протягом $166570D. Цей ефект накопичується." },
    { en = "Throws a Blackrock Mortar shell, inflicting Fire damage to enemies within $160963A1 yards of the impact.", ua = "Кидає снаряд Мортири Блекрок, завдаючи шкоди вогнем ворогам у межах $160963A1 ярдів від місця влучання." },
    { en = "Blasts enemies in a $156303a1 yard frontal cone, inflicting $156303s1 Fire damage every half-second to enemies.", ua = "Уражає ворогів у лобовому конусі завдовжки $156303a1 ярдів, завдаючи їм $156303s1 шкоди вогнем кожні пів секунди." },
    { en = "Blasts enemies in a frontal cone, inflicting $166545s1 Fire damage every second to nearby enemies.", ua = "Випускає струмінь на ворогів у конусі перед собою, завдаючи щосекунди $166545s1 шкоди вогнем ближнім ворогам." },
    { en = "Throws a Blackrock Grenade at a target, inflicting Fire damage to enemies within $163742A1 yards.", ua = "Жбурляє у ціль гранату Блекрок, завдаючи шкоди вогнем ворогам у радіусі $163742A1 м." },
    { en = "Carrying Mortar Shells, allowing the use of a Blackrock Turret's Homing Shell ability.\n\n$@spelltooltip160705", ua = "Несе мінометні снаряди, що дозволяє використати здібність «Самонавідний снаряд» турелі Блекрок.\n\n$@spelltooltip160705" },
    { en = "Throws a series of Blackrock Mortar shells towards a target's location, inflicting Fire damage to enemies within $163741A1 yards of the impact.", ua = "Жбурляє низку мінометних снарядів Блекрок у бік цілі, завдаючи шкоди вогнем ворогам у радіусі $163741A1 м від місця влучання." },
    { en = "Carrying Grenades, allowing the use of Blackrock Grenade.\n\n$@spelltooltip161060", ua = "Несе гранати, що дозволяє використати гранату Блекрок.\n\n$@spelltooltip161060" },
    { en = "Thunderous Breath encompasses the platform, inflicting Nature damage to all players.", ua = "Громовий подих огортає платформу, завдаючи шкоди від сил природи всім гравцям." },
    { en = "Throws a spinning spear towards a target, penetrating armor and inflicting $162057s1 Physical damage, knocking down the target for $162057D.", ua = "Кидає в ціль обертовий спис, що пробиває броню та завдає $162057s1 фізичної шкоди, збиваючи ціль із ніг на $162057D." },
    { en = "Throws a Frost Trap on the ground, which when tripped, inflicts $162065s2 Frost damage and roots all enemies within $162065A2 yards for $162065D.", ua = "Кидає на землю морозну пастку, яка при спрацюванні завдає $162065s2 шкоди від морозу й знерухомлює всіх ворогів у радіусі $162065A2 м на $162065D." },
    { en = "Forms a pool of viscous electricity on the ground, periodically inflicting Nature damage to targets who remain in the pool.", ua = "Утворює на землі калюжу в'язкої електрики, що періодично завдає шкоди від сил природи цілям, які лишаються в ній." },
    { en = "Marks a target, throwing an Explosive Spear at their location after $163446D, inflicting Fire damage to all targets within $163445A1 yards.", ua = "Позначає ціль і за $163446D метає в її напрямку вибуховий спис, завдаючи шкоди вогнем усім цілям у радіусі $163445A1 м." },
    { en = "Dreadfang howls, causing his allies to inflicts $s1% additional Physical damage for $d.", ua = "Жахопаща виє, через що його союзники завдають на $s1% більше фізичної шкоди протягом $d." },
    { en = "Dreadfang snarls and leaps towards his prey mauling them savagely, reducing their movement speed by $s3% and inflicting $s1 Physical damage every $t1 sec. for $d.", ua = "Жахопаща гарчить і стрибає на свою здобич, люто роздираючи її, що зменшує її швидкість пересування на $s3% і завдає $s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Signals Grom'kar Archers to release a barrage of arrows that rain down from above inflicting $s1 Physical damage.", ua = "Дає сигнал лучникам Ґром'кар випустити шквал стріл, що сиплються згори, завдаючи $s1 фізичної шкоди." },
    { en = "Nok'gar howls an intimidating warsong. Striking him during its effect will cause the attacker to flee in fear.", ua = "Нок'ґар виє грізну бойову пісню. Той, хто вдарить його під час цього, тікатиме у страху." },
    { en = "Signals Grom'kar Flameslingers to launch a continuous volley of flaming arrows, leaving a burning trail on the ground that inflict $s1 Fire damage every $t sec.", ua = "Дає сигнал вогнеметальникам Ґром'кар запустити безперервний залп палаючих стріл, що лишають на землі вогняний слід, який завдає $s1 шкоди вогнем кожні $t с." },
    { en = "Dreadfang lunges forward gnawing everyone caught in his path, inflicting $s1 Physical damage.", ua = "Жахопаща кидається вперед, кусаючи всіх на своєму шляху й завдаючи $s1 фізичної шкоди." },
    { en = "Makogg slashes his burning blade with ferocity and conjures crashing waves of lava, inflicting $s1 Fire damage.", ua = "Макоґґ люто змахує своїм палаючим клинком і прикликає лавові хвилі, що накочуються й завдають $s1 шкоди вогнем." },
    { en = "Ahri'ok Dugru conjures a black miasma and releases a bolt of blood, inflicting $s1 Shadow damage.", ua = "Агрі'ок Дуґру прикликає чорну імлу й випускає згусток крові, завдаючи $s1 шкоди від тіні." },
    { en = "Fires a slug inflicting $s1 Physical damage.", ua = "Стріляє кулею, завдаючи $s1 фізичної шкоди." },
    { en = "Ahri'ok summons an orb of blood to protect her most injured ally, absorbing $s1 damage. The shield will trigger a groupwide heal if broken by damage.", ua = "Агрі'ок прикликає кулю крові, щоб захистити найтяжче пораненого союзника, поглинаючи $s1 шкоди. Якщо щит зруйнується від шкоди, він зцілить усю групу." },
    { en = "Ogre traps snap closed around your ankles, slowing your movement by $s2% and inflicting $s1 Physical damage every $t1 sec for $d.", ua = "Оґрські пастки клацають і змикаються довкола ваших щиколоток, уповільнюючи ваше пересування на $s2% і завдаючи $s1 фізичної шкоди кожні $t1 с протягом $d." },
    { en = "Neesa's jumper cables crackle and release a chain of lightning, inflicting $s1 Nature damage to 3 enemies.", ua = "Пускові кабелі Ніси тріщать і випускають ланцюг блискавок, завдаючи $s1 шкоди від сил природи 3 ворогам." },
    { en = "Bombsquad primes his core and charges towards an enemy, inflicting $s1 Fire damage to enemies within $A1 yards upon detonation.", ua = "Підривник зводить своє ядро й мчить на ворога, завдаючи при детонації $s1 шкоди вогнем ворогам у радіусі $A1 м." },
    { en = "Makogg dashes forward spinning his massive blade, inflicting $s1 Fire damage to all enemies.", ua = "Макоґґ рветься вперед, обертаючи свій велетенський клинок, що завдає $s1 шкоди вогнем усім ворогам." },
    { en = "A surge of power is released, healing $s1% of max health every $t1 sec. for $d.", ua = "Вивільняється сплеск сили, зцілюючи $s1% максимального здоров'я кожні $t1 сек. протягом $d." },
    { en = "Ahri'ok manifests a foul toxin that ravages your body, inflicting $s1 Nature damage every $t1 secs. for $d.", ua = "Агрі'ок насилає мерзенний токсин, що нищить ваше тіло, завдаючи $s1 шкоди від сил природи кожні $t1 с протягом $d." },
    { en = "Neesa anticipates your movements and carefully calibrates her trap launcher, flinging 8 ogre traps around your feet.", ua = "Ніса передбачає ваші рухи й ретельно налаштовує свою пастко-пускалку, жбурляючи 8 оґрських пасток вам під ноги." },
    { en = "Increases damage dealt by $s1% for each nearby Ravenous Wolf.", ua = "Збільшує завдану шкоду на $s1% за кожного ненажерливого вовка поблизу." },
    { en = "Oshir charges towards his prey, brutally mauling enemies in his path for $s1 Physical damage.", ua = "Ошир мчить на свою здобич, брутально роздираючи ворогів на своєму шляху й завдаючи $s1 фізичної шкоди." },
    { en = "The Rylak Skyterror fires an Acid Spit at an enemy, inflicting $178157s1 Nature damage to enemies within $178157A1 yards and creating an Acid Splash for $178157d.", ua = "Рилак-небожах плює кислотою у ворога, завдаючи $178157s1 шкоди від сил природи ворогам у радіусі $178157A1 м і створюючи кислотний бризк на $178157d." },
    { en = "Oshir leaps to a cage, unleashing the caged beast trapped inside!", ua = "Ошир стрибає до клітки, вивільняючи ув'язнену в ній звірину!" },
    { en = "Inflicts $178156s1 Nature damage every $178156t1 sec.", ua = "Завдає $178156s1 шкоди від сил природи кожні $178156t1 с." },
    { en = "Oshir pins his prey to the ground and rends them furiously, inflicting $s3 Physical damage every $t3 sec for $d.", ua = "Ошир притискає свою здобич до землі й шалено роздирає її, завдаючи $s3 фізичної шкоди кожні $t3 с протягом $d." },
    { en = "Oshir enters a feeding frenzy and must be damaged for $162424s1% of his maximum health to release his victim.", ua = "Ошир впадає в несамовите пожирання, і йому слід завдати шкоди в розмірі $162424s1% його максимального здоров'я, щоб він відпустив свою жертву." },
    { en = "Barrages enemies with his cannons, inflicting $168390s1 Fire damage to enemies within $168148A1 yards of the blast.", ua = "Засипає ворогів зі своїх гармат, завдаючи $168390s1 шкоди вогнем ворогам у радіусі $168148A1 м від вибуху." },
    { en = "A plume of heat and smoke backdrafts from the rear of the ship, inflicting $s1 Fire damage to enemies. The more cannon barrages occur, the more severe this explosion is.", ua = "З корми корабля вихоплюється стовп жару й диму, завдаючи $s1 шкоди вогнем ворогам. Що більше відбулося гарматних залпів, то потужніший цей вибух." },
    { en = "Koramar crashes down on enemy targets, inflicting $168399s1 Nature damage to enemies within $A1 yards of his landing.", ua = "Корамар обрушується на ворожі цілі, завдаючи $168399s1 шкоди від сил природи ворогам у радіусі $A1 м від місця приземлення." },
    { en = "Attacks in a whirl of steel, causing $s1% weapon damage to each enemy within melee range.", ua = "Атакує у вихорі сталі, завдаючи $s1% шкоди зброї кожному ворогові в зоні ближнього бою." },
    { en = "Koramar skims his blade across the ground, causing melee sparks that inflict $s1 Fire damage to enemies within the area of effect.", ua = "Корамар черкає клинком по землі, висікаючи іскри, що завдають $s1 шкоди вогнем ворогам у зоні дії." },
    { en = "Zoggosh focuses on a single enemy, rapidly firing at them and all enemies standing in between for $168348s2 Fire damage every half second.", ua = "Зоґґош зосереджується на одному ворогові, швидко стріляючи в нього й усіх ворогів, що стоять між ними, завдаючи $168348s2 шкоди вогнем кожні пів секунди." },
    { en = "Sadana Bloodfury beckons a spirit towards her, in order to consume their essence.\n\n\n\nIf devoured, Sadana Bloodfury heals for $153164s1% of her life, and inflicts $153164s2% additional damage.", ua = "Садана Бладф'юрі прикликає до себе дух, щоб поглинути його сутність.\n\n\n\nЯкщо дух пожерто, Садана Бладф'юрі зцілюється на $153164s1% свого здоров'я та завдає на $153164s2% більше шкоди." },
    { en = "Inflicts $s1 Shadow damage to all enemies every second.", ua = "Щосекунди завдає $s1 шкоди від тіні всім ворогам." },
    { en = "Successful melee attacks have a chance to grant $s2 additional melee attacks which inflict $153089s1 Shadow damage.", ua = "Успішні атаки в ближньому бою мають шанс надати $s2 додаткових атак, що завдають $153089s1 шкоди від тіні." },
    { en = "Causes a Dark Eclipse, inflicting $164686s1 Shadow damage to all players, and corrupting Lunar Runes.", ua = "Викликає Темне Затемнення, завдаючи $164686s1 шкоди від тіні всім гравцям і опоганюючи Місячні руни." },
    { en = "Sadana conjures a sacrificial dagger over a random player, inflicting $153232s1 Shadow damage on impact. The dagger remains in the ground, burning players within $s2 yards for $153224s1 Shadow damage per second.", ua = "Садана прикликає жертовний кинджал над випадковим гравцем, завдаючи $153232s1 шкоди Тінню при влучанні. Кинджал лишається в землі, обпікаючи гравців у межах $s2 ярдів, завдаючи $153224s1 шкоди Тінню за секунду." },
    { en = "Lunar rays of purity bathe you in a divine light, decreasing damage taken by $s1%.", ua = "Місячні промені чистоти оповивають тебе божественним сяйвом, зменшуючи отримувану шкоду на $s1%." },
    { en = "A powerful vortex pulls enemies towards the center, inflicting $152800s1 Shadow damage to players caught in the area.", ua = "Потужний вир затягує ворогів до центру, завдаючи $152800s1 шкоди від тіні гравцям у його зоні." },
    { en = "Successfully recovering your soul empowers you, increasing all damage and healing done by $s1% for $d.", ua = "Успішне повернення своєї душі наснажує тебе, збільшуючи всю завдану шкоду й зцілення на $s1% на $d." },
    { en = "Launches several bolts of Void Devastation every second which inflict $153072s2 Shadow damage and create a pool of Void Devastation inflicting $153070s1 Shadow damage every $153070t1 sec to players caught within.", ua = "Щосекунди випускає кілька стріл Спустошення Порожнечі, що завдають $153072s2 шкоди від тіні та утворюють калюжу Спустошення Порожнечі, яка завдає $153070s1 шкоди від тіні кожні $153070t1 с гравцям, що в ній опинилися." },
    { en = "Tears the soul from an enemies body, inflicting $s1 Shadow damage every $t1 sec. Enemies who recapture their soul within $d are empowered, increasing damage and healing done by $153033s1% for $153033d.", ua = "Вириває душу з тіла ворога, завдаючи $s1 шкоди від тіні кожні $t1 с. Вороги, що повертають свою душу впродовж $d, наснажуються, збільшуючи завдану шкоду й зцілення на $153033s1% на $153033d." },
    { en = "The caster twists the flow of void energy around himself, preparing to teleport towards an enemy within $A1 yards.", ua = "Заклинач спотворює потік енергії Порожнечі довкола себе, готуючись телепортуватися до ворога в межах $A1 м." },
    { en = "A dark energy tears at your flesh, inflicting $153501s1 Shadow damage every second.", ua = "Темна енергія шматує твою плоть, завдаючи $153501s1 шкоди від тіні щосекунди." },
    { en = "Inflicts $165579s1 Shadow damage to all enemies every second.", ua = "Щосекунди завдає $165579s1 шкоди від тіні всім ворогам." },
    { en = "Inhales enemies at an increasingly powerful rate. \n\n\n\nIf a player is caught in Bonemaw's deadly maw, they suffer $153908s5 Nature damage and are spit off of the platform.", ua = "Вдихає ворогів дедалі потужніше. \n\n\n\nЯкщо гравець потрапляє в смертоносну пащу Кістопащі, він зазнає $153908s5 шкоди від сил природи й випльовується з платформи." },
    { en = "Bonemaw slimes his current target with a fetid spit, inflicts $s1 Shadow damage.", ua = "Кістопаща обпльовує свою поточну ціль смердючою слиною, завдаючи $s1 шкоди від тіні." },
    { en = "Inflicts $s1 Nature damage to the enemy target.\n\n\n\nIf left without any valid melee targets, this unit will spit uncontrollably.", ua = "Завдає $s1 шкоди від сил природи ворожій цілі.\n\n\n\nЗалишившись без жодної придатної цілі для ближнього бою, ця істота нестримно плюватиметься." },
    { en = "Bonemaw spews a Necrotic Pitch over a random player's location, inflicting $s1 Shadow damage every second and reducing movement speed by $s2%.", ua = "Кістопаща вивергає Некротичну Смолу на місце випадкового гравця, завдаючи $s1 шкоди від тіні щосекунди й зменшуючи швидкість пересування на $s2%." },
    { en = "Bonemaw thrusts his body forward, inflicting $153395s1 Shadow damage to enemies in front of him and knocking them back.", ua = "Кістепаща кидає своє тіло вперед, завдаючи $153395s1 шкоди Тінню ворогам перед собою та відкидаючи їх назад." },
    { en = "Ner'zhul casts a shadow of void energy, inflicting $s1 Shadow damage to all enemies in a line in front of him. Afflicted players will have their damage reduced by $s2%", ua = "Нер'зул напускає тінь енергії Порожнечі, завдаючи $s1 шкоди від тіні всім ворогам на лінії перед собою. Завдана шкода вражених гравців зменшується на $s2%." },
    { en = "Ner'zhul falls into a trance, showing players a vision of their own death. Void energy rips through the sky, inflicting up to $154353s1 Shadow damage, based on proximity to the effect.", ua = "Нер'зул впадає в транс, показуючи гравцям видіння власної смерті. Енергія Порожнечі роздирає небо, завдаючи до $154353s1 шкоди від тіні залежно від близькості до ефекту." },
    { en = "Ner'zhul summons an army of shadow and death which marches across his platform, eradicating all life in its path. \n\nTendrils of void bind the ritual bones together, inflicting $154469s1 Shadow damage every $t1 sec for $d to those who cross their threshold.", ua = "Нер'зул прикликає армію тіні й смерті, що марширує його платформою, винищуючи все живе на своєму шляху. \n\nПасма Порожнечі сплітають ритуальні кістки докупи, завдаючи $154469s1 шкоди від тіні кожні $t1 с упродовж $d тим, хто переступає їхній поріг." },
    { en = "Unleash a torrent of unbridled natural energy, inflicting $s1 Nature damage to enemies in a cone in front of Witherbark.", ua = "Вивільняє потік нестримної природної енергії, завдаючи $s1 шкоди від сил природи ворогам у конусі перед Зів'якорою." },
    { en = "The enchanted waters of the nearby lake bubble and churn launching a bolt of water at a player's location. Upon impact, the bolt inflicts $s1 Frost damage to all players within $a1 yards.", ua = "Зачаровані води сусіднього озера вирують і нуртують, випускаючи водяну стрілу на місце гравця. При ударі стріла завдає $s1 шкоди від морозу всім гравцям у радіусі $a1 м." },
    { en = "Create a viney growth that pursues a player. Upon reaching that player, the growth erupts and emits poisonous vapors that inflict $s1 Nature damage every $t1 sec to players within.", ua = "Створює виткий пагін, що переслідує гравця. Наздогнавши його, пагін розривається й випускає отруйні випари, що завдають $s1 шкоди від сил природи кожні $t1 с гравцям усередині." },
    { en = "Witherbark's bark dries and becomes brittle, stunning him and increasing his damage taken by $s2%.\n\n\n\nThis effect is removed when Witherbark reaches 100 Aqueous Energy.", ua = "Кора Зів'якори висихає й стає крихкою, оглушуючи її та збільшуючи отримувану нею шкоду на $s2%.\n\n\n\nЦей ефект знімається, коли Зів'якора набирає 100 одиниць Водяної Енергії." },
    { en = "Upon reaching zero health, the Aqueous Globule erupts and inflicts $s1 Frost damage to all players.", ua = "Втративши все здоров'я, Водяна Кулька вибухає, завдаючи $s1 шкоди від морозу всім гравцям." },
    { en = "Earthshaper Telu conjures a toxic bloom that inflicts $s1 Nature damage and stuns all players for $d.", ua = "Землеформувач Телу прикликає отруйний квіт, що завдає $s1 шкоди від сил природи й приголомшує всіх гравців на $d." },
    { en = "Earthshaper Telu blasts a random player, inflicting $s1 Nature damage.", ua = "Землеформувач Телу вражає випадкового гравця, завдаючи $s1 шкоди від сил природи." },
    { en = "Channel the fury of water, inflicting $s1 Frost damage to all players every $427498t1 sec for $427498d.", ua = "Спрямовує лють води, завдаючи $s1 шкоди від морозу всім гравцям кожні $427498t1 сек. протягом $427498d." },
    { en = "Life Warden Gola heals an Ancient Protector for $s1% of their maximum health, plus an additional $s2% every $t2 sec for $d.", ua = "Хранитель життя Гола зцілює одного з Прадавніх Захисників на $s1% його максимального здоров'я, плюс додаткові $s2% кожні $t2 с упродовж $d." },
    { en = "Channel the fury of earth, inflicting $s1 Nature damage to all players every $427509t1 sec for $427509d.", ua = "Спрямовує лють землі, завдаючи $s1 шкоди від сил природи всім гравцям кожні $427509t1 сек. протягом $427509d." },
    { en = "Dulhu marks his target, then charges to them after $427510d, inflicting $s1 Nature damage to players within $A1 yards of their location and leaving behind $@spellname427513.", ua = "Дулху позначає свою ціль, тоді кидається до неї за $427510d, завдаючи $s1 шкоди від сил природи гравцям у радіусі $A1 м від її місця та лишаючи по собі $@spellname427513." },
    { en = "Inflicts $s1 Nature damage every $t1 sec to players standing within.", ua = "Завдає $s1 шкоди від сил природи кожні $t1 с гравцям, що стоять усередині." },
    { en = "Life Warden Gola blasts a random player with water, inflicting $s1 Frost damage.", ua = "Хранитель життя Гола вражає водою випадкового гравця, завдаючи $s1 шкоди від морозу." },
    { en = "Launch a sphere of arcane energy towards the most distant player within range. The orb explodes upon arrival, inflicting $s1 Arcane damage to players within $a1 yds.\n\n\n\nForces resulting from the explosion pull all players towards the impact location.", ua = "Запускає сферу чародійської енергії в найвіддаленішого гравця в межах досяжності. Куля вибухає при прибутті, завдаючи $s1 арканної шкоди гравцям у межах $a1 ярдів.\n\n\n\nСили вибуху притягують усіх гравців до місця падіння." },
    { en = "Inflicts $s1 Arcane damage.", ua = "Завдає $s1 арканної шкоди." },
    { en = "Whenever Archmage Sol's school affinity changes, a Spore Image appears and uses an ability from the previous school.", ua = "Щоразу, коли спорідненість Архімага Сол зі школою магії змінюється, з'являється Споровий Образ і застосовує здібність із попередньої школи." },
    { en = "Inflicts $s1 Fire damage.", ua = "Завдає $s1 шкоди вогнем." },
    { en = "The parasite controlling Archmage Sol can only use one school of magic at a time. Her school affinity changes every $t1 sec, altering her abilities.", ua = "Паразит, що контролює Архімага Сол, може використовувати лише одну школу магії за раз. Її спорідненість зі школою змінюється кожні $t1 с, змінюючи її здібності." },
    { en = "Summon a ring of frozen spheres around all players that collapse inward, inflicting $s1 Frost damage every $t1 sec and stunning for $d on contact.", ua = "Прикликає навколо всіх гравців кільце крижаних сфер, що стискається досередини, завдаючи $s1 шкоди від морозу кожні $t1 сек. і приголомшуючи на $d при дотику." },
    { en = "Inflicts $s1 Frost damage and reduces movement speed by $s2% for $d.", ua = "Завдає $s1 шкоди від морозу та зменшує швидкість пересування на $s2% на $d." },
    { en = "Fire countless burning cinders at nearby players. Cinders strike a random player for $s1 Fire damage every ${$427899s1/1000}.2 sec for $427899d.\n\n\n\nEvery $427899t1 sec, several larger cinders inflict $427922s1 Fire damage to players within $427922a1 yards and leave behind $@spellname426991.", ua = "Випускає незліченні палаючі іскри по гравцях поблизу. Іскри влучають у випадкового гравця на $s1 шкоди вогнем кожні ${$427899s1/1000}.2 сек. протягом $427899d.\n\n\n\nКожні $427899t1 сек. кілька більших іскор завдають $427922s1 шкоди вогнем гравцям у межах $427922a1 ярдів і лишають по собі $@spellname426991." },
    { en = "The caster stings a nearby player at random. Once stung, the victim suffers Nature damage every 3 sec. for $d.", ua = "Заклинач жалить випадкового гравця поблизу. Ужалена жертва зазнає шкоди від сил природи кожні 3 с упродовж $d." },
    { en = "Xeri'tac consumes a pale orc. If successful, Xeri'tac will heal for $169246s1% of her maximum health.", ua = "Ксері'так пожирає блідого орка. У разі успіху Ксері'так зцілюється на $169246s1% свого максимального здоров'я." },
    { en = "The caster's blood burns brightest in the heat of combat. The caster's damage is increased by $169219s1% every $t1 sec.\n\n\n\nIf the caster ever reaches 10 stacks of Toxic Blood they will explode, leaving behind an area of Toxic Gas.", ua = "Кров заклинача палає найяскравіше в запалі бою. Шкода заклинача збільшується на $169219s1% кожні $t1 с.\n\n\n\nЯкщо заклинач набирає 10 стаків Токсичної Крові, він вибухає, лишаючи по собі зону Токсичного Газу." },
    { en = "The caster releases her toxic blood in the form of 2 missiles at ranged targets. When the missiles land, they form areas of Toxic Gas. Players who stand in these areas suffer Nature damage.", ua = "Заклинач випускає свою токсичну кров у вигляді 2 снарядів по дальніх цілях. Приземлившись, снаряди утворюють зони Токсичного Газу. Гравці, що стоять у цих зонах, зазнають шкоди від сил природи." },
    { en = "Whenever a Toxic Spiderling perishes it leaves behind a cloud of Toxic Gas. Players who enter the area suffer Nature damage. Venom-Crazed Pale Ones will rush to these clouds to inhale them.", ua = "Щоразу, коли Токсичне павученя гине, воно лишає по собі хмару токсичного газу. Гравці, що входять у цю зону, зазнають шкоди від сил природи. Очманілі від отрути Блідуни кидаються до цих хмар, аби вдихнути їх." },
    { en = "The orc inhales the toxic fumes left over by the fallen spiderling. If successful, the orc gains Toxic Blood.", ua = "Орк вдихає токсичні випари, що лишилися від загиблого павученяти. У разі успіху орк отримує Токсичну кров." },
    { en = "The caster swipes the air in front of them with both hands, inflicting Physical damage to all players in front of the caster.", ua = "Той, хто творить закляття, розсікає повітря перед собою обома руками, завдаючи фізичної шкоди всім гравцям попереду." },
    { en = "The caster explodes, dealing $s1 Nature damage to all nearby enemies.", ua = "Той, хто творить закляття, вибухає, завдаючи $s1 шкоди від сил природи всім ворогам поблизу." },
    { en = "Xeri'tac descends from her web, looking for unsuspecting prey. Any pale orcs or players in the vicinity will be bitten for significant Physical damage.", ua = "Ксері'так спускається зі своєї павутини в пошуках необачної здобичі. Будь-які бліді орки чи гравці поблизу зазнають укусу й значної фізичної шкоди." },
    { en = "The caster hurls a bolt of their toxic blood at the target, inflicting Nature damage.", ua = "Той, хто творить закляття, жбурляє згусток своєї токсичної крові в ціль, завдаючи шкоди від сил природи." },
    { en = "Walking over an unsprouted Feral Lasher tramples it to death.", ua = "Якщо пройти по Дикому хльосту, що ще не проріс, він гине, розтоптаний." },
    { en = "Gnarled Ancients crush all players in front of them, inflicting $169930s1 Physical damage.", ua = "Вузлуваті прадавні трощать усіх гравців перед собою, завдаючи $169930s1 фізичної шкоди." },
    { en = "Lady Baihu channels a continuous stream of flame into Yalnu, increasing all damage he takes by $s1%.", ua = "Леді Байгу спрямовує безперервний потік полум'я в Ялну, збільшуючи всю шкоду, якої він зазнає, на $s1%." },
    { en = "Yalnu creates a field of sproutlings and begins to channel Genesis for $d. When the channel is complete, all sproutlings that were not Trampled grow into Feral Lashers.", ua = "Ялну створює поле паростків і починає спрямовувати Генезу протягом $d. Коли спрямування завершується, усі паростки, які не було розтоптано, виростають у Диких хльостів." },
    { en = "The Ancient overflows with natural power, inflicting $s1 Nature damage to all players every $428948t1 sec.", ua = "Прадавній переповнюється природною силою, завдаючи $s1 шкоди від сил природи всім гравцям кожні $428948t1 сек." },
    { en = "Yalnu forces a Flourishing Ancient to burst from the ground, inflicting $s1 Nature damage and stunning enemies within $a1 yards for $d.\n\n\n\nThe Ancient focuses its attacks on Lady Baihu, preventing her from channeling $@spellname428746 until it is defeated.", ua = "Ялну змушує Квітучого Прадавнього вирватися із землі, завдаючи $s1 шкоди від сил природи й приголомшуючи ворогів у межах $a1 ярдів на $d.\n\n\n\nПрадавній зосереджує свої атаки на леді Байгу, не даючи їй спрямовувати $@spellname428746, доки його не буде знищено." },
    { en = "Hurls a fiery ball that inflicts $s1 Fire damage.", ua = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню." },
    { en = "Yalnu rears back and sunders the earth, inflicting $s1 Nature damage to all enemies in front of him, stunning them for $d. In addition, this effect inflicts $s3 Nature damage to all enemies.", ua = "Ялну стає дибки й розколює землю, завдаючи $s1 шкоди від сил природи всім ворогам перед собою та оглушуючи їх на $d. Крім того, цей ефект завдає $s3 шкоди від сил природи всім ворогам." },
    { en = "Feral Lashers spit venom at a random player, inflicting $s1 Nature damage.", ua = "Дикі хльости плюють отрутою у випадкового гравця, завдаючи $s1 шкоди від сил природи." },
    { en = "Magnetically charged spike erupts from the earth, inflicting $154428s2 Nature damage.", ua = "Магнітно заряджений шпичак виривається із землі, завдаючи $154428s2 шкоди від сил природи." },
    { en = "Inflicts $m1 to $M1 Physical damage to nearby enemies, ignoring armor.", ua = "Завдає від $m1 до $M1 фізичної шкоди ворогам поблизу, ігноруючи броню." },
    { en = "Deals $s1 Physical damage.", ua = "Завдає $s1 фізичної шкоди." },
    { en = "Empowered with the energy of the Rune Conduits, Gor'ashan unleashes lightning, inflicting $s1 Nature damage to nearby enemies.", ua = "Підсилений енергією Рунних провідників, Ґор'ашан вивільняє блискавки, завдаючи $s1 шкоди від сил природи ворогам поблизу." },
    { en = "Rune Conduits channel power to Gor'ashan, reducing damage taken by $m1%, and empowers Gor'ashan to cast Thunder Cacophony.", ua = "Рунні провідники спрямовують силу до Ґор'ашана, зменшуючи отримувану шкоду на $m1% та наділяючи Ґор'ашана здатністю творити Громову какофонію." },
    { en = "A Lightning Orb travels between the Power Runes inflicting $154345m1 Nature damage every $t1 sec to nearby enemies.", ua = "Куля блискавки рухається між Рунами сили, завдаючи $154345m1 шкоди від сил природи кожні $t1 с ворогам поблизу." },
    { en = "Poison erupts from the target's skin, creating puddles that inflict $m1 Nature damage every $t1 sec.", ua = "Зі шкіри цілі проривається отрута, утворюючи калюжі, що завдають $m1 шкоди природою кожні $t1 сек." },
    { en = "Kyrak fixates on a target and channels a beam of debilitating energy, inflicting $161200m3 Shadow damage every $t1 sec., decreasing movement speed and damage dealt.", ua = "Кайрак зосереджується на цілі та спрямовує промінь виснажливої енергії, завдаючи $161200m3 шкоди темрявою кожні $t1 сек. і знижуючи швидкість пересування та завдану шкоду." },
    { en = "Drinks a potion, healing $s1% of maximum health every $t1 sec. for $d.", ua = "Випиває зілля, відновлюючи $s1% максимального здоров'я кожні $t1 с протягом $d." },
    { en = "Covers the target in toxic poison, inflicting $s1 Nature damage every $162600t1 sec to all nearby allies.", ua = "Вкриває ціль токсичною отрутою, що завдає $s1 шкоди природою кожні $162600t1 сек. усім союзникам поблизу." },
    { en = "Attacks have a chance to cleave enemies for $155033m1 Physical damage.", ua = "Атаки мають шанс розрубати ворогів, завдаючи $155033m1 фізичної шкоди." },
    { en = "Flames erupt in a line in front of the caster, inflicting $s1 Fire damage instantly and disorienting enemies, inflicting an additional $s2 Fire damage every $t2 sec for $d.", ua = "Полум'я здіймається лінією перед тим, хто творить закляття, миттєво завдаючи $s1 шкоди від вогню та дезорієнтуючи ворогів, завдаючи додатково $s2 шкоди від вогню кожні $t2 с протягом $d." },
    { en = "Damage inflicted increased by $m1%.", ua = "Завдана шкода збільшена на $m1%." },
    { en = "Inflicts $s1 Physical damage and causes the target to bleed for $m2 Physical damage every $t2 sec. for $d1.", ua = "Завдає $s1 фізичної шкоди й змушує ціль стікати кров'ю, завдаючи $m2 фізичної шкоди кожні $t2 с протягом $d1." },
    { en = "Creates a puddle of acid, inflicting $s1 Nature damage every $t1 sec.", ua = "Створює калюжу кислоти, що завдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "Breathes a cone of fire, inflicting $s1 Fire damage every $161883t2 sec. and increases Fire damage taken by $m2%. This effect stacks.", ua = "Видихає конус вогню, завдаючи $s1 шкоди від вогню кожні $161883t2 с та збільшуючи отримувану шкоду від вогню на $m2%. Цей ефект накопичується." },
    { en = "Charges a target, inflicting $m1 to $M1 Physical damage to anyone in the way.", ua = "Кидається на ціль, завдаючи від $m1 до $M1 фізичної шкоди всім, хто опиниться на шляху." },
    { en = "Throws a whirling axe, inflicting $m1 to $M1 Fire damage to nearby enemies.", ua = "Метає вихрову сокиру, завдаючи від $m1 до $M1 шкоди від вогню ворогам поблизу." },
    { en = "Increases damage dealt by $s1%. Stacks 4 times.", ua = "Збільшує завдану шкоду на $s1%. Накопичується до 4 разів." },
    { en = "Ragewing spits fire, inflicting $155081s1 Fire damage to nearby enemies.", ua = "Гнівокрил плює вогнем, завдаючи $155081s1 шкоди вогнем ворогам поблизу." },
    { en = "Ragewing spits magma at an enemy, inflicting $s2 damage and leaves a puddle of magma.", ua = "Гнівокрил плює магмою у ворога, завдаючи $s2 шкоди й лишаючи по собі калюжу магми." },
    { en = "Ragewing breathes a cone of fire, inflicting $155031m1 to $155031M1 Fire damage and disorienting enemies for $155056d1.", ua = "Гнівокрил видихає конус вогню, завдаючи від $155031m1 до $155031M1 шкоди вогнем і дезорієнтуючи ворогів на $155056d1." },
    { en = "Ragewing tears at the target's flesh, bleeding the target for $s1 damage every $t1 sec. for $d.", ua = "Гнівокрил роздирає плоть цілі, змушуючи її стікати кров'ю й завдаючи $s1 шкоди кожні $t1 с протягом $d." },
    { en = "Zaela enters a combat frenzy, fixates on a random target, and starts dealing $155728m1 Physical damage to all nearby enemies every $166149t2 sec.", ua = "Заела впадає в бойове шаленство, зосереджується на випадковій цілі й починає завдавати $155728m1 фізичної шкоди всім ворогам поблизу кожні $166149t2 с." },
    { en = "Inflicts $s1 Physical damage.", ua = "Завдає $s1 фізичної шкоди." },
    { en = "Breaths a wide line of fire, inflicting $m1 to $M1 Fire Damage.", ua = "Видихає широку лінію вогню, завдаючи від $m1 до $M1 шкоди від вогню." },
    { en = "Throws an axe, inflicting $s1 Physical damage to the target and bouncing to hit up to 2 more nearby enemies.", ua = "Кидає сокиру, завдаючи $s1 фізичної шкоди цілі й відскакуючи, щоб уразити ще до 2 ворогів поблизу." },
    { en = "Inflicts $s1 Fire damage every $t1 sec to players standing within.", ua = "Завдає $s1 шкоди від вогню кожні $t1 с гравцям, що стоять усередині." },
    { en = "Wise Mari commands the fountain to erupt, inflicting $s1 Frost damage to players standing in the waters and knocking them up.", ua = "Мудрий Марі наказує фонтанові вивергнутися, завдаючи $s1 шкоди від морозу гравцям, що стоять у воді, і підкидаючи їх угору." },
    { en = "Wise Mari marks players for a $@spellname397797. After $d the mark erupts inflicting $397798s1 Frost damage to players within $397798a1 yards and creates a $@spellname397798.", ua = "Мудрий Марі позначає гравців ефектом $@spellname397797. Через $d позначка вибухає, завдаючи $397798s1 шкоди Льодом гравцям у радіусі $397798a1 ярдів і створюючи $@spellname397798." },
    { en = "Wise Mari directs the fountain's corrupted waters to attack players, inflicting $106104s1 Frost damage to enemies caught within the Corrupted Water Burst.", ua = "Мудрий Марі скеровує осквернені води фонтана на гравців, завдаючи $106104s1 шкоди від морозу ворогам, які потрапили під Сплеск оскверненої води." },
    { en = "Players standing in the vortex suffer $s1 Frost damage every $t1 sec and are drawn towards its center.", ua = "Гравці, що стоять у вирі, зазнають $s1 шкоди від морозу кожні $t1 с і притягуються до його центру." },
    { en = "Wise Mari hurls a lance of corrupted water at his target, inflicting $s1 Frost damage.", ua = "Мудрий Марі жбурляє спис із оскверненої води у свою ціль, завдаючи $s1 шкоди від морозу." },
    { en = "Launches bolts of corrupted water inflicting $s1 Frost damage to 3 enemies every $396904t1 sec.", ua = "Випускає стріли з оскверненої води, завдаючи $s1 шкоди від морозу 3 ворогам кожні $396904t1 с." },
    { en = "Wise Mari protects himself in multiple layers of $@spellname106062, reducing damage taken by $s2% for each layer of protection. Whenever a layer of $@spellname106062 is removed it inflicts $396874s1 Frost damage to all enemies and reduces movement speed by $396874s2% for $396874d.\n\n\n\nAny enemy that comes into contact with the protective $@spellname106062 will suffer $106079s2 Frost damage and be knocked away.", ua = "Мудрий Марі захищає себе кількома шарами $@spellname106062, зменшуючи отриману шкоду на $s2% за кожен шар захисту. Щоразу, коли шар $@spellname106062 зникає, він завдає $396874s1 шкоди від морозу всім ворогам і зменшує швидкість пересування на $396874s2% на $396874d.\n\n\n\nБудь-який ворог, що торкнеться захисного бар'єра $@spellname106062, зазнає $106079s2 шкоди від морозу і буде відкинутий." },
    { en = "Corrupt Droplets leave behind a pool of $@spellname395829 that inflicts $s1 Frost damage every $t1 to all targets within 3 yards.", ua = "Осквернені краплі лишають по собі калюжу $@spellname395829, що завдає $s1 шкоди від морозу кожні $t1 усім цілям у радіусі 3 ярдів." },
    { en = "Wise Mari channels a jet of corrupted water, inflicts $s1 Frost damage every $t1 sec to players caught in its path.", ua = "Мудрий Марі направляє струмінь оскверненої води, завдаючи $s1 шкоди від морозу кожні $t1 с гравцям, що опинилися на його шляху." },
    { en = "Inflicts $s1 Frost damage and knocks away anything caught in its path.", ua = "Завдає $s1 шкоди від морозу і відкидає все, що опинилося на шляху." },
    { en = "The corrupted waters of the fountain inflict $s1 Frost damage every $d.", ua = "Осквернені води фонтана завдають $s1 шкоди від морозу кожні $d." },
    { en = "Attacking Peril or Strife will increase their $@spellname113315, inflicting $113394s1 Shadow damage to all enemies every 2 seconds and increasing damage done by 10%. Reaching 10 stacks of $@spellname113315 will cause Peril or Strife to become immune to all damage for $113309d.\n\n\n\nThis effect stacks.", ua = "Атака по Небезпеці чи Чварі підвищує їхню $@spellname113315, завдаючи $113394s1 шкоди від тіні всім ворогам кожні 2 секунди і збільшуючи завдану шкоду на 10%. Досягнення 10 стаків $@spellname113315 робить Небезпеку чи Чвару несприйнятливими до будь-якої шкоди на $113309d.\n\n\n\nЦей ефект складається." },
    { en = "Ignoring this unit will cause it to dissipate to near nothingness, decreasing Damage inflicted by $s2%.\n\n\n\nThis effect stacks.", ua = "Якщо ігнорувати цю істоту, вона розвіється майже до небуття, зменшуючи завдану шкоду на $s2%.\n\n\n\nЦей ефект складається." },
    { en = "Inflicts $106736s1 Shadow damage.", ua = "Завдає $106736s1 шкоди від тіні." },
    { en = "Strife's presence gives you a $@spellname396150 that increases your damage and healing done by $s3% but inflicts $396151s1 Shadow damage every $t2 sec while the feeling persists. The damage inflicted is increased by $s4% for each second you have a $@spellname396150.", ua = "Присутність Чвари дарує тобі $@spellname396150, що збільшує завдану тобою шкоду й зцілення на $s3%, але завдає $396151s1 шкоди від тіні кожні $t2 с, доки триває це відчуття. Завдана шкода збільшується на $s4% за кожну секунду, що ти маєш $@spellname396150." },
    { en = "Experience an uncontrollable $@spellname396152 reducing damage and healing by 5% and preventing you from experiencing a $@spellname396149 until the feeling has faded.", ua = "Ти відчуваєш некеровану $@spellname396152, що зменшує шкоду й зцілення на 5% і не дає тобі відчути $@spellname396149, доки це відчуття не згасне." },
    { en = "Yu'lon breathes a ball of flames at a random enemy, inflicting $107103s1 Fire damage to enemies within $107103a1 yards of the impact area and creating a pool of jade fire at their location that inflicts $s1 Fire damage every second to players within the flames.", ua = "Ю'лон вивергає вогняну кулю в випадкового ворога, завдаючи $107103s1 шкоди вогнем ворогам у радіусі $107103a1 ярдів від місця влучання та створюючи на їхній позиції калюжу нефритового вогню, яка щосекунди завдає $s1 шкоди вогнем гравцям, що стоять у полум'ї." },
    { en = "Liu Flameheart unleashes a flurry of attacks on her target, inflicting $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d.", ua = "Лю Полум'яне Серце обрушує на свою ціль шквал атак, завдаючи $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 с протягом $d." },
    { en = "Immediately following a Serpent Strike, Liu Flameheart performs a vicious Serpent Kick. This powerful kick inflicts $s1 Fire damage to all players within $a1 yards.", ua = "Одразу після Зміїного удару Лю Полум'яне Серце завдає лютого Зміїного копняка. Цей потужний копняк завдає $s1 шкоди вогнем усім гравцям у радіусі $a1 ярдів." },
    { en = "Yu'lon unleashes massive Jade Fire Breath inflicting $s1 Fire damage to enemies up to $a1 yards in front of him.", ua = "Ю'лон вивергає величезний Нефритовий вогняний подих, завдаючи $s1 шкоди вогнем ворогам на відстані до $a1 ярдів перед ним." },
    { en = "The force of Liu Flameheart's Jade Serpent Kick creates four waves of jade fire which radiate away from her. Jade Serpent Waves inflict $s1 Fire damage and knock back players in their path and leave a trail of jade fire in their wake which inflicts $118540s1 Fire damage every $118540t1 sec.", ua = "Сила Нефритового зміїного копняка Лю Полум'яне Серце створює чотири хвилі нефритового вогню, що розходяться від неї. Хвилі нефритового змія завдають $s1 шкоди вогнем і відкидають гравців на своєму шляху, лишаючи по собі слід нефритового вогню, що завдає $118540s1 шкоди вогнем кожні $118540t1 с." },
    { en = "Immediately following a Jade Serpent Strike, Liu Flameheart performs a vicious Jade Serpent Kick. This powerful kick inflicts $s1 Fire damage and knocks back all players within $a1 yards.", ua = "Одразу після Нефритового зміїного удару Лю Полум'яне Серце завдає лютого Нефритового зміїного копняка. Цей потужний копняк завдає $s1 шкоди вогнем і відкидає всіх гравців у радіусі $a1 ярдів." },
    { en = "Liu Flameheart unleashes a flurry of attacks on her target, inflicting $s1 Fire damage and an additional $s2 Fire damage every $t2 sec for $d. In addition, Jade Serpent Strike absorbs up to $s3 healing received by the target.", ua = "Лю Полум'яне Серце обрушує на свою ціль шквал атак, завдаючи $s1 шкоди вогнем і додатково $s2 шкоди вогнем кожні $t2 с протягом $d. Крім того, Нефритовий зміїний удар поглинає до $s3 зцілення, отриманого ціллю." },
    { en = "The force of Liu Flameheart's Serpent Kick creates four waves of fire which radiate away from her. Serpent Waves inflict $s1 Fire damage to all players in their path and knock them back.", ua = "Сила Зміїного копняка Лю Полум'яне Серце створює чотири хвилі вогню, що розходяться від неї. Зміїні хвилі завдають $s1 шкоди вогнем усім гравцям на своєму шляху і відкидають їх." },
    { en = "General Umbriss lets out a terrifying roar, inflicting $s1 Sonic damage to all players. This effect ignores armor.\n\n\n\nTwilight drakes heed the call of General Umbriss and descend on the platform and blast players with $@spellname448566.", ua = "Генерал Умбрісс видає жахливий рев, завдаючи $s1 звукової шкоди всім гравцям. Цей ефект ігнорує броню.\n\n\n\nСутінкові дрейки відгукуються на поклик Генерала Умбрісса, спускаються на платформу й обрушують на гравців $@spellname448566." },
    { en = "Earth erupts underneath players, inflicting $s1 Physical damage and knocking them forward.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nAlso leaves behind $@spellname448953 at impact location for $448948d.]", ua = "Земля вибухає під гравцями, завдаючи $s1 фізичної шкоди й відкидаючи їх уперед.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nТакож у місці удару лишається $@spellname448953 на $448948d.]" },
    { en = "Twilight Drake unleashes breath of shadowflame, inflicting $s2 Shadowflame damage to players within the impact area.", ua = "Сутінковий дрейк вивергає подих тіньового полум'я, завдаючи $s2 шкоди тіньовим полум'ям гравцям у зоні удару." },
    { en = "Ruptured earth makes the terrain difficult to traverse, inflicting $s2 Physical damage every $t2 sec and reducing movement speed by $s1% to players within.", ua = "Розколота земля ускладнює пересування місцевістю, завдаючи $s2 фізичної шкоди щосекунди раз на $t2 с і зменшуючи швидкість пересування гравців на її площі на $s1%." },
    { en = "General Umbriss unleashes on the target player, inflicting $447268s1 Physical damage every $t1 sec for $d.\n\n\n\nThe target becomes severely wounded, bleeding for $447268s2  Physical damage every $447268t2 sec for $447268d. This effect stacks.", ua = "Генерал Умбрісс накидається на цільового гравця, завдаючи $447268s1 фізичної шкоди раз на $t1 с протягом $d.\n\n\n\nЦіль дістає тяжке поранення й кровоточить, втрачаючи $447268s2 здоров'я від фізичної шкоди раз на $447268t2 с протягом $447268d. Цей ефект накопичується." },
    { en = "Throngus' attacks leave pools of molten metal in their wake for $d, inflicting $s1 Fire damage every $t1 sec to players standing in the area.", ua = "Атаки Тронґуса лишають по собі калюжі розплавленого металу на $d, завдаючи $s1 вогняної шкоди раз на $t1 с гравцям, що стоять у цій зоні." },
    { en = "Throngus forges new weapons with molten lava over $d to destroy his enemies. The process generates $@spellname452008 every $t1 sec.", ua = "Тронґус кує нову зброю з розплавленої лави протягом $d, щоб знищити своїх ворогів. Цей процес породжує $@spellname452008 раз на $t1 с." },
    { en = "Molten metals engulf a player inflicting $s1 Fire damage every $t1 sec for $d.", ua = "Розплавлений метал огортає гравця, завдаючи $s1 вогняної шкоди раз на $t1 с протягом $d." },
    { en = "Throngus cleaves his enemies with a molten axe, inflicting $s1 Physical damage to players in front of him.", ua = "Тронґус розтинає ворогів розплавленою сокирою, завдаючи $s1 фізичної шкоди гравцям перед собою." },
    { en = "Throngus unleashes a flurry of attacks on his primary target with molten blades, inflicts $449449s1 Physical damage and $449448s2 Fire damage every sec for $d.\n\n\n\nPeriodically an ember will fly from Throngus' blades afflicting a player with $@spellname449474 and leaving behind $@spellname449483 when expired.", ua = "Тронґус обрушує на свою основну ціль шквал ударів розжареними клинками, завдаючи $449449s1 фізичної шкоди та $449448s2 шкоди вогнем щосекунди протягом $d.\n\n\n\nЧас від часу з клинків Тронґуса злітає жарина, накладаючи на гравця $@spellname449474 і залишаючи по собі $@spellname449483 після закінчення дії." },
    { en = "Inflicts $s1 Fire damage to all players.", ua = "Завдає $s1 вогняної шкоди всім гравцям." },
    { en = "Thorngus forges a massive mace from lava, increasing his melee damage by $s1% for $d.", ua = "Тронґус кує з лави величезну булаву, збільшуючи свою шкоду в ближньому бою на $s1% протягом $d." },
    { en = "Invoked Shadowflame Spirit fixates on a player.", ua = "Прикликаний дух тіньового полум'я зосереджується на гравцеві." },
    { en = "Inflicts $s1 Shadowflame damage every $t1 sec and reduce movement speed by $s2%.", ua = "Завдає $s1 шкоди тіньовим полум'ям раз на $t1 с і зменшує швидкість пересування на $s2%." },
    { en = "The Invoked Shadowflame Spirit goes supernova and inflicts $s1 Shadowflame damage and $s3 Fire damage every $t3 sec to all players.", ua = "Прикликаний дух тіньового полум'я вибухає надновою й завдає $s1 шкоди тіньовим полум'ям і $s3 вогняної шкоди раз на $t3 с усім гравцям." },
    { en = "Drahga Shaowburner creates flame portals in nearby locations. The portal fully opens after $448013d, inflicting $448028s1 Fire damage to all players within $448028a1 yards. \n\n\n\nAn Invoked Shadowflame Spirit emerges from the portal and fixates on a player.", ua = "Драга Тінепал створює полум'яні портали в сусідніх місцях. Портал повністю відкривається через $448013d, завдаючи $448028s1 шкоди вогнем усім гравцям у радіусі $448028a1 ярдів.\n\n\n\nЗ порталу постає Прикликаний Дух Тіньового Полум'я й зосереджується на гравцеві." },
    { en = "Drahga curses target player, inflicting $s4 Shadow damage and absorbing healing equals to $s2% of their health for $d. Also reducing their movement speed by $s3%.", ua = "Драга проклинає цільового гравця, завдаючи $s4 шкоди від тіні й поглинаючи зцілення в розмірі $s2% його здоров'я протягом $d. Також зменшує його швидкість пересування на $s3%." },
    { en = "Valiona flaps her wings, unleashing a gust of wind that inflicts $s1 Shadowflame damage to all players and knocking them back.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nAlso leaves behind $@spellname456769 at impact location for $456769d.]", ua = "Валіона змахує крилами, здіймаючи порив вітру, що завдає $s1 шкоди Тіньовим Полум'ям усім гравцям і відкидає їх.$?diff1|diff2[]$?diff8|diff23[\n\n\n\nТакож залишає по собі $@spellname456769 в місці влучання на $456769d.]" },
    { en = "Dragha blasts a random player with Shadowflame, inflicting $s1 Shadowflame damage.", ua = "Драга обстрілює випадкового гравця тіньовим полум'ям, завдаючи $s1 шкоди тіньовим полум'ям." },
    { en = "Erudax infuses target players with Void energy, inflicting $s1 Shadow damage to all players within $a1 yards every $448057t1 sec for $448057d.", ua = "Ерудакс наповнює цільових гравців енергією Порожнечі, завдаючи $s1 шкоди Тінню всім гравцям у радіусі $a1 ярдів кожні $448057t1 сек. протягом $448057d." },
    { en = "Void Tendrils grab hold of players in their reach, stunning them and inflicting $s2 Shadow damage every $t2 sec for $d.", ua = "Щупальця Порожнечі хапають гравців у межах досяжності, оглушуючи їх і завдаючи $s2 шкоди від тіні раз на $t2 с протягом $d." },
    { en = "Erudax infuses Alexstrasza's eggs with void energy every $t1 sec for $d, causing them to hatch into Mutated Hatchlings.", ua = "Ерудакс наповнює яйця Алекстраси енергією Порожнечі раз на $t1 с протягом $d, через що з них вилуплюються мутовані виводки." },
    { en = "On death, caster unleashes shadow energy that afflicts players with $@spellname456719.", ua = "Гинучи, заклинач вивільняє тіньову енергію, що накладає на гравців $@spellname456719." },
    { en = "Causes an enemy to take $s1% increased Shadow damage for $d. This effect stacks.", ua = "Змушує ворога отримувати на $s1% більше шкоди Тінню протягом $d. Цей ефект накопичується." },
    { en = "Erudax begins to gather shadows at a nearby location, inflicting $461513s1 Shadow damage to players inside. After $s1 sec that location becomes the eye of the Shadow Gale. A shadow storm rages outside of the eye for $449983d, inflicting $449985s1 Shadow damage to all players in it.", ua = "Ерудакс починає збирати тіні в сусідньому місці, завдаючи $461513s1 шкоди від тіні гравцям усередині. За $s1 с це місце стає оком Тіньового Шторму. Навколо ока протягом $449983d вирує тіньова буря, завдаючи $449985s1 шкоди від тіні всім гравцям у ній." },
    { en = "Erudex crushes its target with his void-infused claws, inflicting $450101s1 Physical damage and $450102s1 Shadow damage and knocking back the target.", ua = "Ерудакс розчавлює свою ціль пройнятими Порожнечею пазурами, завдаючи $450101s1 фізичної шкоди й $450102s1 шкоди від тіні та відкидаючи ціль назад." },
    { en = "Erudax unleashes Void energy deep into the earth, inflicting $450079s1 Shadow damage every $t1 sec to all players and causes Void Tendrils to erupt from the earth for $450081d.", ua = "Ерудакс вивільняє енергію Порожнечі глибоко в землю, завдаючи $450079s1 шкоди від тіні раз на $t1 с усім гравцям і змушуючи щупальця Порожнечі вириватися з землі протягом $450081d." },
    { en = "The caster sends a lethal current through all players, inflicting $s1 Nature damage.", ua = "Заклинач пропускає смертоносний струм крізь усіх гравців, завдаючи $s1 шкоди від сил природи." },
    { en = "Grand Vizier Ertan surrounds herself with 8 cyclones at the beginning of the encounter. These cyclones rotate slowly around her in a circle. Periodically Ertan calls the cyclones close to her, then after a few seconds the cyclones return to their regular orbit.\n\n\n\nPlayers that touch a cyclone are dealt $86292s3 Nature damage and have their movement speed and Haste reduced by $86292s1% for $86292d.", ua = "Великий візир Ертан оточує себе 8 циклонами на початку бою. Ці циклони повільно обертаються навколо неї по колу. Час від часу Ертан прикликає циклони ближче до себе, а за кілька секунд вони повертаються на свою звичайну орбіту.\n\n\n\nГравці, що торкаються циклона, дістають $86292s3 шкоди від сил природи, а їхня швидкість пересування й Поспіх зменшуються на $86292s1% протягом $86292d." },
    { en = "Ertan's cyclones emit fragments of energy, players that come into contact with a fragment suffer $86292s3 Nature damage and have their movement speed and Haste reduced by $86292s1% for $86292d.", ua = "Циклони Ертана випромінюють уламки енергії; гравці, що торкаються уламка, отримують $86292s3 шкоди природою, а їхня швидкість пересування й Поспіх знижуються на $86292s1% на $86292d." },
    { en = "Grand Vizier Ertan periodically calls a Lurking Tempest to join the fight.", ua = "Великий візир Ертан час від часу прикликає Причаєну Бурю приєднатися до бою." },
    { en = "A downburst forms near Altairus, inflicts $413271s1 Nature damage to players standing within $413271a1 yards of the impact area and expands outwards. The expanding ring of air silences players it passes over and inflicts $s1 Nature damage every $t1 sec for $d.", ua = "Поблизу Альтаїруса утворюється низхідний шквал, що завдає $413271s1 шкоди від сил природи гравцям у радіусі $413271a1 м від зони удару й розширюється назовні. Кільце повітря, що шириться, занімовлює гравців, яких проходить, і завдає $s1 шкоди від сил природи раз на $t1 с протягом $d." },
    { en = "Altairus' presence chills the air around him, inflicting $s1 Frost damage to all players every $413330t1 sec.", ua = "Присутність Альтаїруса вихолоджує повітря довкола нього, завдаючи $s1 шкоди від морозу всім гравцям раз на $413330t1 с." },
    { en = "Inflicts $s1 Frost damage to enemies in a cone in front of the caster.", ua = "Завдає $s1 шкоди від морозу ворогам у конусі перед заклиначем." },
    { en = "Standing upwind of Altairus makes it easier to attack and cast spells. Haste is increased by $s1%.", ua = "Стоячи з навітряного боку від Альтаїруса, легше атакувати й творити закляття. Поспіх збільшується на $s1%." },
    { en = "Altairus forms a $@spellname413275 around the arena, players standing in the area suffer $s1 Frost damage every $t1 sec and their damage and healing done is reduced by $s2%.", ua = "Альтаїрус здіймає $@spellname413275 над ареною; гравці, що стоять у цій зоні, дістають $s1 шкоди від морозу раз на $t1 с, а завдана ними шкода й зцілення зменшуються на $s2%." },
    { en = "Standing downwind of Altairus inflicts $413319s1 Frost damage every $t2 sec and makes it difficult to attack and cast spells. Haste is reduced by $s1%.", ua = "Стоячи з підвітряного боку від Альтаїруса, ти дістаєш $413319s1 шкоди від морозу раз на $t2 с, а атакувати й творити закляття стає важче. Поспіх зменшується на $s1%." },
    { en = "Asaad creates a static field along the ground, any player touching the ground when his casting completes suffers $s3 Nature damage and has their movement speed reduced by $s2% for $d.", ua = "Асаад створює на землі статичне поле; будь-який гравець, що торкається землі в мить завершення його творіння, дістає $s3 шкоди від сил природи, а його швидкість пересування зменшується на $s2% протягом $d." },
    { en = "Asaad unleashes a lightning bolt at a player, inflicting $s1 Nature damage. The bolt then arcs to additional players within $s2 yards.", ua = "Асаад вивільняє блискавку в гравця, завдаючи $s1 шкоди від сил природи. Тоді блискавка перестрибує на інших гравців у радіусі $s2 м." },
    { en = "Asaad summons a $@spellname413263 that inflicts $413264s1 Arcane damage to all players every $t1 sec until it is destroyed.", ua = "Асаад прикликає $@spellname413263, що завдає $413264s1 чародійської шкоди всім гравцям раз на $t1 с, доки її не буде знищено." },
    { en = "The Honor Guard slithers near a player's location. Increases its Attack speed by $s2% and Movement speed by $s3% for $d.", ua = "Почесний вартовий підповзає до місцеперебування гравця. Збільшує свою швидкість атаки на $s2% і швидкість пересування на $s3% протягом $d." },
    { en = "When Lady Naz'jar reaches $s3% and $s4% remaining health, she summons her Elite Guard and begins to channel $@spellname75683.  \n\n\n\nWhile channeling $@spellname75683 Lady Naz'jar is immune to damage and causes geysers to erupt throughout the arena periodically until her guards are defeated.", ua = "Коли в Леді Наз'джар лишається $s3% та $s4% здоров'я, вона прикликає свою Елітну варту й починає творити $@spellname75683.\n\n\n\nПід час творення $@spellname75683 Леді Наз'джар несприйнятлива до шкоди й періодично спричиняє виверження гейзерів по всій арені, доки її варту не буде знищено." },
    { en = "The Honor Guard strikes rapidly with its spear. Inflicts $428294s1 Physical damage in a cone in front of it every $t2 sec for $d.", ua = "Почесний вартовий стрімко б'є списом. Завдає $428294s1 фізичної шкоди в конусі перед собою кожні $t2 сек протягом $d." },
    { en = "The Frost Witch launches a bolt of frost at the enemy. Inflicts $s1 Frost damage and reduces movement speed by $s2% for $d.", ua = "Морозна відьма пускає у ворога стрілу холоду. Завдає $s1 шкоди від морозу й знижує швидкість пересування на $s2% протягом $d." },
    { en = "Lady Naz'jar hurls a bolt of water. Inflicts $s1 Frost damage to the target.", ua = "Леді Наз'джар жбурляє стрілу води. Завдає цілі $s1 шкоди від морозу." },
    { en = "The Frost Witch accelerates her spellcasting. Grants $s1% Haste and increases Frost damage done by $s2% for $d.", ua = "Морозна відьма пришвидшує своє чаклування. Дарує $s1% Поспіху й збільшує завдану шкоду від морозу на $s2% протягом $d." },
    { en = "Lady Naz'jar blasts her target with a tremendous charge of lightning, inflicts $s1 Nature to players within $428021a1 yards of the target and sends Shock Orbs in all directions.", ua = "Леді Наз'джар вражає ціль потужним зарядом блискавки, завдає $s1 шкоди від сил природи гравцям у радіусі $428021a1 ярдів від цілі та розсилає Сфери Шоку в усіх напрямках." },
    { en = "$@spellname428041 sends fragments of energy in all directions. Players that come into contact with a $@spellname428048 suffer $s1 Nature damage and are stunned for $d.", ua = "$@spellname428041 розсилає уламки енергії в усіх напрямках. Гравці, що торкаються $@spellname428048, зазнають $s1 шкоди від сил природи й приголомшуються на $d." },
    { en = "Lady Naz'jar conjures a focused tempest that lashes out at players. Inflicts $s1 Nature damage to a random target and jumps to additional players for reduced damage.", ua = "Леді Наз'джар прикликає зосереджену бурю, що шмагає гравців. Завдає $s1 шкоди від сил природи випадковій цілі та перестрибує на інших гравців зі зменшеною шкодою." },
    { en = "Lady Naz'jar summons geysers throughout the arena, after a delay the geysers erupt. Players standing in the area are knocked up and suffer $s1 Frost damage.", ua = "Леді Наз'джар прикликає по всій арені гейзери, які після затримки вивергаються. Гравців, що стоять у цій ділянці, підкидає вгору, і вони зазнають $s1 шкоди від морозу." },
    { en = "Ulthok animates all pools of $@spellname427559, transforming them into $@spellname427451 that move and seek out players for $427451d.", ua = "Улток оживляє всі калюжі $@spellname427559, перетворюючи їх на $@spellname427451, що рухаються й вистежують гравців протягом $427451d." },
    { en = "Players standing in $@spellname427559 suffer $s2 Shadow damage every $t2 sec and have their Haste reduced by $s1%.", ua = "Гравці, що стоять у $@spellname427559, зазнають $s2 шкоди від тіні кожні $t2 сек, а їхній Поспіх знижено на $s1%." },
    { en = "Ulthok stomps the ground and releases a wave of ooze, knocking all players back and coating them with ooze. Inflicts $s1 Shadow damage and $s2 Shadow damage every $t2 sec for $d.", ua = "Улток гупає по землі й вивільняє хвилю слизу, відкидаючи всіх гравців назад і вкриваючи їх слизом. Завдає $s1 шкоди від тіні та ще $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "Ulthok snaps at his primary target with a crushing claw. Inflicts $s1 Physical damage and increasing Physical damage taken by $s2% for $d.", ua = "Улток хапає свою основну ціль трощильною клешнею. Завдає $s1 фізичної шкоди й збільшує зазнавану фізичну шкоду на $s2% протягом $d." },
    { en = "Ulthok sends a surge of dark energy through the ground that erupts at a targeted area. Inflicts $427565s1 Shadow damage and knocks back players at the impact area and leaves behind a pool of $@spellname427559.", ua = "Улток посилає крізь землю сплеск темної енергії, що вибухає в позначеній ділянці. Завдає $427565s1 шкоди від тіні й відкидає гравців у місці удару, лишаючи по собі калюжу $@spellname427559." },
    { en = "Congealed Ooze seek out players and are knocked back when attacked.", ua = "Згуслий Слиз вистежує гравців і відкидається назад, коли його атакують." },
    { en = "Erunak summons a $@spellname429037 that increases his Attack speed by $s2% and causes his successful melee attacks to inflict an additional $429038s1 Nature damage until it is destroyed.", ua = "Ерунак прикликає $@spellname429037, що збільшує його швидкість атаки на $s2% і змушує його успішні атаки в ближньому бою завдавати додаткові $429038s1 шкоди від сил природи, доки його не буде знищено." },
    { en = "Ghur'sha assaults the minds of players with a terrifying vision. Inflicts $s1 Shadow damage and Fears players in line of sight for $d.", ua = "Ґур'ша вражає розум гравців жахливим видивом. Завдає $s1 шкоди від тіні й сповнює страхом гравців у полі зору протягом $d." },
    { en = "Ghur'sha rots the minds of players. Inflicts $s1 Shadow damage to all players.", ua = "Ґур'ша руйнує розум гравців. Завдає $s1 шкоди від тіні всім гравцям." },
    { en = "Erunak sears a player with fire, inflicting $s1 Fire damage and $s2 Fire damage every $t2 sec for $d.", ua = "Ерунак обпалює гравця вогнем, завдаючи $s1 шкоди від вогню та $s2 шкоди від вогню кожні $t2 сек протягом $d." },
    { en = "Erunak causes the earth beneath players to erupt every $t1 sec for $d. Inflicts $429057s1 Nature damage to players standing in the area of an eruption.", ua = "Ерунак змушує землю під гравцями вивергатися кожні $t1 сек протягом $d. Завдає $429057s1 шкоди від сил природи гравцям, що стоять у ділянці виверження." },
    { en = "Neptulon channels a rush of cleansed water into players, granting them immunity to Shadow damage and the power to purify $@spellname428404 for $d.", ua = "Нептулон спрямовує в гравців потік очищеної води, даруючи їм несприйнятливість до шкоди від тіні та силу очищувати $@spellname428404 протягом $d." },
    { en = "The Ink of Ozumat unleashes a rotting roar, inflicting $s1 Shadow damage to all players and an additional $s2 Shadow damage every $t2 sec for $d.", ua = "Чорнило Озумата вивільняє гнилісний рев, завдаючи $s1 шкоди від тіні всім гравцям і ще $s2 шкоди від тіні кожні $t2 сек протягом $d." },
    { en = "The Sludge bursts, inflicting $428809s1 Shadow damage within $428809A1 yards and creating $@spellname428404.", ua = "Багниста маса лопається, завдаючи $428809s1 шкоди від тіні в радіусі $428809A1 ярдів і створюючи $@spellname428404." },
    { en = "The Splotch musters a blob of ink to fling at a player, inflicting $s1 Shadow damage.", ua = "Пляма збирає згусток чорнила, щоб жбурнути в гравця, завдаючи $s1 шкоди від тіні." },
    { en = "The Ink of Ozumat launches a volley of smearing globs at players that inflict $428405s1 Shadow damage within $428405A1 yards and create $@spellname428404.", ua = "Чорнило Озумата випускає залп розмазливих згустків по гравцях, що завдають $428405s1 шкоди від тіні в радіусі $428405A1 ярдів і створюють $@spellname428404." },
    { en = "The Ink of Ozumat retches a glut of filth, inflicting $s1 Shadow damage to players in front of it.", ua = "Чорнило Озумата вивергає купу бруду, завдаючи $s1 шкоди від тіні гравцям перед собою." },
    { en = "Ozumat ejects a surge of ink blots into the bubble, each inflicting $428616s1 Shadow damage within $428616A1 yards of impact and forming Servants of Filth.", ua = "Озумат викидає сплеск чорнильних плям у бульбашку, кожна з яких завдає $428616s1 шкоди від тіні в радіусі $428616A1 ярдів від місця удару й утворює Прислужників Бруду." },
    { en = "A spreading pool of ink that inflicts $s1 Shadow damage every $t1 sec to players within the effect and reduces their movement speed by $s3%.", ua = "Калюжа чорнила, що розповзається й завдає $s1 шкоди від тіні кожні $t1 сек гравцям у зоні дії та знижує їхню швидкість пересування на $s3%." },
    { en = "The Sludge's melee attacks have a chance to apply $@spellname428403 to the target, inflicting $428403s1 Shadow damage every $428403t1 sec for $428403d.", ua = "Атаки Багнистої маси в ближньому бою мають шанс накласти на ціль $@spellname428403, завдаючи $428403s1 шкоди від тіні кожні $428403t1 сек протягом $428403d." },
    { en = "Ozumat spits an endless storm of ink into the bubble, inflicting $429049s1 Shadow damage to all players every $t1 sec.", ua = "Озумат випльовує нескінченну бурю чорнила в бульбашку, завдаючи $429049s1 шкоди від тіні всім гравцям кожні $t1 сек." },
    { en = "Neptulon infuses players with the tides energy, granting them immense power. Neptulon additionally channels a beam of pure water into Ozumat, inflicting $s1 Frost damage every $t1 sec.", ua = "Нептулон сповнює гравців енергією припливів, даруючи їм неосяжну міць. Окрім того, Нептулон спрямовує промінь чистої води в Озумата, завдаючи $s1 шкоди від морозу кожні $t1 сек." },
    { en = "The Ink of Ozumat inflicts $s1% of normal weapon damage as Shadow damage to its current target if the player is not in melee range.", ua = "Чорнило Озумата завдає $s1% звичайної шкоди зброї як шкоди від тіні своїй поточній цілі, якщо гравець перебуває поза радіусом ближнього бою." },
    { en = "Ingvar the Plunderer throws his Shadow Axe at a random player. The axe will spin at the target location for $d, inflicting $42751s1 Shadow damage every $59719t1 sec to all nearby enemies.", ua = "Інґвар Грабіжник жбурляє Тіньову Сокиру у випадкового гравця. Сокира обертається у вказаному місці $d, завдаючи $42751s1 шкоди Тінню кожні $59719t1 с усім ворогам поблизу." },
    { en = "Bronjahm consumes a Corrupted Soul Fragment, healing himself for $s1% of his maximum health.", ua = "Бронджам поглинає Уламок Зіпсованої Душі, зцілюючи себе на $s1% свого максимального здоров'я." },
    { en = "The Devourer of Souls blasts a player for $s1 Shadow damage.", ua = "Пожирач Душ б'є гравця, завдаючи $s1 шкоди Тінню." },
    { en = "Ingvar the Plunderer strikes his current target for $s1 Shadow damage and afflicts them with Woe Strike for $d.\n\n\n\nWhen a player with Woe Strike is healed, Woe Strike inflicts $42739s1 Shadow damage to the healer.", ua = "Інґвар Грабіжник вражає свою поточну ціль, завдаючи $s1 шкоди Тінню, і накладає на неї Удар Горя на $d.\n\n\n\nКоли гравця під дією Удару Горя зцілюють, Удар Горя завдає $42739s1 шкоди Тінню зцілювачу." },
    { en = "Bronjahm attempts to corrupt a portion of a player's soul and separate it from their body. If Corrupt Soul is not dispelled before it expires, a Corrupted Soul Fragment is drawn from the player, stunning them for $68848d.", ua = "Бронджам намагається зіпсувати частину душі гравця й відділити її від тіла. Якщо Зіпсування Душі не розвіяти до закінчення, з гравця витягується Уламок Зіпсованої Душі, оглушуючи його на $68848d." },
    { en = "Ingvar the Plunderer smashes the ground with dark energy, inflicting $s3 Shadow damage and stunning all players in front of him for $d.", ua = "Інґвар Грабіжник б'є по землі темною енергією, завдаючи $s3 шкоди Тінню й оглушуючи всіх гравців перед собою на $d." },
    { en = "Loken summons a powerful pulse of electricity that inflicts $s1 Nature damage to all players within $a1 yards.", ua = "Локен закликає потужний імпульс електрики, що завдає $s1 шкоди Природою всім гравцям у радіусі $a1 ярдів." },
    { en = "Anub'arak rears up and smashes down on all players within $53472a1 yards in front of him, inflicting $53509s1 Physical damage and pounding them into the floor for $53472d.", ua = "Ануб'арак здіймається й обрушується на всіх гравців у радіусі $53472a1 ярдів перед собою, завдаючи $53509s1 фізичної шкоди й вбиваючи їх у підлогу на $53472d." },
    { en = "When a Skittering Infector dies, acidic blood erupts from their corpse, inflicting $s1 Nature damage every $t1 sec to friends and enemies within $A1 yards for $d. This effect stacks up to $u times.", ua = "Коли Дріботливий Заражувач гине, з його трупа вивергається кислотна кров, завдаючи $s1 шкоди Природою кожні $t1 с союзникам і ворогам у радіусі $A1 ярдів протягом $d. Цей ефект накладається до $u разів." },
    { en = "Anub'arak calls a swarm of locusts to protect him. These locusts deal $53468s1 Nature damage every $t1 sec to all players within $53468a1 yards.", ua = "Ануб'арак закликає рій сарани, щоб захистити себе. Ця сарана завдає $53468s1 шкоди Природою кожні $t1 с усім гравцям у радіусі $53468a1 ярдів." },
    { en = "Ingvar the Plunderer unleashes a dreadful roar, inflicting $s1 Shadow damage to players within $a1 yards, interrupting any spells being cast for $d, and causing affected players to take $42728s1% increased Shadow damage, stacking up to $42728u times.", ua = "Інґвар Грабіжник видає жахливий рев, завдаючи $s1 шкоди Тінню гравцям у радіусі $a1 ярдів, перериваючи будь-які закляття, що творяться, на $d, і змушуючи уражених гравців отримувати на $42728s1% більше шкоди Тінню. Накладається до $42728u разів." },
    { en = "Bronjahm strikes fear in a random player for $d.", ua = "Бронджам наганяє страх на випадкового гравця на $d." },
    { en = "Ingvar the Plunderer roars, inflicting $s1 Physical damage to all players within $A1 yards and interrupting spellcasting for $d.", ua = "Інґвар Грабіжник реве, завдаючи $s1 фізичної шкоди всім гравцям у радіусі $A1 ярдів і перериваючи творіння заклять на $d." },
    { en = "The Devourer of Souls leaps towards a random player, slamming the ground and creating a Well of Souls. The well persists for the remainder of the fight and inflicts $68863s1 Shadow damage to all players within $68863A1 yards every $68854t1 sec.", ua = "Пожирач Душ стрибає до випадкового гравця, б'є по землі й створює Колодязь Душ. Колодязь зберігається до кінця бою й завдає $68863s1 шкоди Тінню всім гравцям у радіусі $68863A1 ярдів кожні $68854t1 с." },
    { en = "Ingvar the Plunderer enrages, increasing his attack speed by $s1%, stacking up to $u times.", ua = "Інґвар Грабіжник лютішає, підвищуючи свою швидкість атаки на $s1%. Накладається до $u разів." },
    { en = "The Devourer of Souls unleashes a torrent of souls for $68939d. The Unleashed Souls cannot be attacked and pursue random players for $68979d.", ua = "Пожирач Душ вивільняє потік душ на $68939d. Вивільнені Душі неможливо атакувати, і вони переслідують випадкових гравців протягом $68979d." },
    { en = "Skarvald the Constructor strikes a player, inflicting Physical damage and knocking them back.", ua = "Скарвальд Будівничий вражає гравця, завдаючи фізичної шкоди й відкидаючи його назад." },
    { en = "Increases the caster's attack speed by $s2% and the Physical damage it deals by $s1% for $d.", ua = "Підвищує швидкість атаки заклинача на $s2% і фізичну шкоду, яку він завдає, на $s1% протягом $d." },
    { en = "Loken's electric presence shocks all enemies every $59836t1 sec, inflicting increasing Nature damage based on the distance from Loken.", ua = "Електрична присутність Локена б'є струмом усіх ворогів кожні $59836t1 с, завдаючи тим більше шкоди Природою, чим далі вони від Локена." },
    { en = "Loken shocks a player, instantly inflicting $s1 Nature damage. After $d, Arc Lightning leaps to another nearby player, inflicting $s2% of the previous damage.", ua = "Локен б'є струмом гравця, миттєво завдаючи $s1 шкоди Природою. Через $d Дугова Блискавка перестрибує на іншого гравця поблизу, завдаючи $s2% попередньої шкоди." },
    { en = "Bronjahm slashes in a circular arc, inflicting $s1 Physical damage to each target. Deals triple damage against targets with mana.", ua = "Бронджам рубає по колу, завдаючи $s1 фізичної шкоди кожній цілі. Завдає потрійної шкоди цілям, що мають ману." },
    { en = "The Devourer of Souls mirrors a player's soul, causing them to take $69023s2% of the damage he takes.", ua = "Пожирач Душ віддзеркалює душу гравця, через що той отримує $69023s2% шкоди, яку отримує Пожирач." },
    { en = "Prince Keleseth encases a player in a block of ice, stunning them and inflicting $48400s2 Frost damage every $48400t2 sec for $48400d or until the Frost Tomb is destroyed.", ua = "Принц Келесет ув'язнює гравця в брилі льоду, оглушуючи його й завдаючи $48400s2 шкоди Морозом кожні $48400t2 с протягом $48400d або доки Морозну Гробницю не буде знищено." },
    { en = "The Devourer of Souls lets loose a flood of Wailing Souls for $68912d, inflicting $68873s1 Shadow damage to anyone in front of her and knocking them back.", ua = "Пожирач Душ вивільняє потік Голосливих Душ на $68912d, завдаючи $68873s1 шкоди Тінню всім перед собою й відкидаючи їх назад." },
    { en = "Ingvar the Plunderer smashes the ground, inflicting $s1 Physical damage to all enemies in front of him.", ua = "Інґвар Грабіжник б'є по землі, завдаючи $s1 фізичної шкоди всім ворогам перед собою." },
    { en = "Vrykul Skeleton encases Prince Keleseth in bone armor, absorbing $s1 damage for $d.", ua = "Скелет Врайкулів огортає Принца Келесета кістяною бронею, що поглинає $s1 шкоди протягом $d." },
    { en = "Bronjahm hurls a bolt of dark magic at a random enemy, inflicting $s1 Shadow damage.", ua = "Бронджам жбурляє стрілу темної магії у випадкового ворога, завдаючи $s1 шкоди Тінню." },
    { en = "Prince Keleseth hurls a bolt of dark magic at a player, inflicting $s1 Shadow damage.", ua = "Принц Келесет жбурляє стрілу темної магії у гравця, завдаючи $s1 шкоди Тінню." },
    { en = "When Bronjahm reaches 35% health remaining, he teleports to the center of the room and summons a Soulstorm. This swirling vortex of souls inflicts $68921s2 Shadow damage every $68872t1 sec to players more than $68921s1 yards away.", ua = "Коли в Бронджама лишається 35% здоров'я, він телепортується в центр кімнати й закликає Бурю Душ. Цей вихор душ, що кружляє, завдає $68921s2 шкоди Тінню кожні $68872t1 с гравцям, що далі ніж за $68921s1 ярдів." },
    { en = "Decrepifies the target, reducing their $pri by $s1% and slowing movement by $s2% for $d, stacking up to $U times.", ua = "Зрисіває ціль, знижуючи її $pri на $s1% і сповільнюючи рух на $s2% протягом $d. Накладається до $U разів." },
    { en = "Skarvald the Constructor charges a random player, inflicting Physical damage and stunning them for $d.", ua = "Скарвальд Будівничий кидається на випадкового гравця, завдаючи фізичної шкоди й оглушуючи його на $d." },
    { en = "Dalronn the Controller weakens a random player's soul, reducing their attack and casting speed by $s1%, slowing their movement speed by $s2%, and inflicting $s3 Shadow damage every $t3 sec for $d.", ua = "Далронн Повелитель послаблює душу випадкового гравця, знижуючи його швидкість атаки й творіння заклять на $s1%, сповільнюючи його швидкість руху на $s2% і завдаючи $s3 шкоди Тінню кожні $t3 с протягом $d." },
    { en = "Dalronn the Controller hurls a bolt of dark magic at a random player, inflicting $s1 Shadow damage.", ua = "Далронн Повелитель жбурляє стрілу темної магії у випадкового гравця, завдаючи $s1 шкоди Тінню." },
    { en = "Amanitar shoots poison at players, inflicting Nature damage.", ua = "Аманітар бризкає отрутою в гравців, завдаючи шкоди Природою." },
    { en = "Arcanotron launches an arcane bomb at a nearby location. If the bomb strikes the ground, it explodes, inflicting $470012s1 Arcane damage to all players.\n\n\n\nIf the bomb strikes a player it inflicts $470020s1 Arcane damage, increases the player's arcane damage taken by $470020s2% for $470020d, and Arcanotron launches another bomb that will strike the ground more quickly.\n\n\n\nArcane Overcharge will inflict less damage to the raid for each bomb that was caught.", ua = "Арканотрон запускає арканну бомбу в найближчу точку. Якщо бомба влучає в землю, вона вибухає, завдаючи $470012s1 арканної шкоди всім гравцям.\n\n\n\nЯкщо бомба влучає в гравця, вона завдає йому $470020s1 арканної шкоди, збільшує арканну шкоду, яку він зазнає, на $470020s2% протягом $470020d, і Арканотрон запускає ще одну бомбу, що влучить у землю швидше.\n\n\n\nАрканне Перевантаження завдаватиме рейду менше шкоди за кожну впійману бомбу." },
    { en = "Inflicts $s2 Fire damage in a $A2 yard cone in front of the caster.", ua = "Завдає $s2 шкоди вогнем у конусі завдовжки $A2 ярдів перед заклиначем." },
    { en = "Ambassador Flamelash summons a powerful Flamewalker.", ua = "Посол Полум'ябій прикликає потужного полум'яхода." },
    { en = "Flamelash opens portals to the Firelands. Burning Spirits arrive from the Firelands every $465000t1 sec until two nearby portal anchors are destroyed.", ua = "Полум'ябій відкриває портали до Вогняних Земель. Палаючі духи прибувають із Вогняних Земель кожні $465000t1 сек., доки не буде знищено два поблизькі якорі порталу." },
    { en = "While incorporeal the Seven inflict $s1% reduced damage, suffer $s2% reduced damage, and are immune to interrupts.", ua = "У безтілесній формі Семеро завдають на $s1% менше шкоди, зазнають на $s2% менше шкоди та несприйнятливі до переривань." },
    { en = "Inflicts $s1 Fire damage and applies $@spellname464362 to all players.", ua = "Завдає $s1 шкоди вогнем і накладає $@spellname464362 на всіх гравців." },
    { en = "While corporeal, the Seven gain energy over time and are able to use powerful abilities.", ua = "У тілесній формі Семеро з часом накопичують енергію та можуть застосовувати потужні здібності." },
    { en = "Showers globs of lava around the caster that inflict $150003s1 Fire damage to all targets within $150003A2 yard of the impact.", ua = "Осипає закляття довкола згустками лави, що завдають $150003s1 шкоди від вогню всім цілям у радіусі $150003A2 ярда від місця влучання." },
    { en = "Lord Roccor erupts inflicting $462838s1 Volcanic damage to enemies in the area and creating a pool of roiling magma. Roiling magma created by Eruption splashes into $462355s1 Living Magmas that will attempt to return to their pool. Each Living Magma that reaches their pool will increase its size.", ua = "Лорд Роккор вивергається, завдаючи $462838s1 вулканічної шкоди ворогам у цій зоні й створюючи калюжу вируючої магми. Створена Виверженням вируюча магма розбризкується на $462355s1 Живих магм, що намагатимуться повернутися до своєї калюжі. Кожна Жива магма, що досягає калюжі, збільшує її розмір." },
    { en = "Hurls molten lava at the target, inflicting $s1 Fire damage.", ua = "Жбурляє розплавлену лаву в ціль, завдаючи $s1 шкоди від вогню." },
    { en = "Lord Roccor transforms all roiling magma into Obsidian Elementals whose power increases with the size of the pool.", ua = "Лорд Роккор перетворює всю вируючу магму на Обсидіанових елементалів, чия сила зростає разом із розміром калюжі." },
    { en = "Summons a powerful fire elemental. While the fire elemental is alive, Hate'rel's $@spellname464363 targets all players.", ua = "Прикликає могутнього вогняного елементаля. Поки вогняний елементаль живий, $@spellname464363 Гейт'рела б'є по всіх гравцях." },
    { en = "Hate'rel hurls magma at a player. While Hate'rel is corporeal $@spellname464363 applies $@spellname464362", ua = "Гейт'рел жбурляє магму в гравця. Поки Гейт'рел має тілесну форму, $@spellname464363 накладає $@spellname464362" },
    { en = "Golems within $s1 yards have their damage increased by $463853s1% and attack speed increased by $463853s2%. This effect stacks.", ua = "Големи в межах $s1 ярдів завдають на $463853s1% більше шкоди, а їхня швидкість атаки зростає на $463853s2%. Цей ефект накопичується." },
    { en = "Lord Roccor slams the ground inflicting $462469s1 Volcanic damage to all enemies every $t1 sec for $d.", ua = "Лорд Роккор б'є по землі, завдаючи $462469s1 вулканічної шкоди всім ворогам кожні $t1 сек. протягом $d." },
    { en = "Gloom'rel flies into a frenzy, inflicting $s1% increased damage for $d.", ua = "Ґлум'рел впадає в шаленство, завдаючи на $s1% більше шкоди протягом $d." },
    { en = "Unleashes a series of $s1 brutal strikes, each inflicting $464360s1 Physical damage.", ua = "Завдає серії з $s1 жорстоких ударів, кожен з яких завдає $464360s1 фізичної шкоди." },
    { en = "Links pairs of players together. If linked players are farther than $s1 yards apart after $463848d, they suffer $463849s1 Nature damage.", ua = "Зв'язує гравців у пари. Якщо зв'язані гравці після $463848d перебувають далі ніж за $s1 ярдів одне від одного, вони зазнають $463849s1 шкоди силами природи." },
    { en = "Inflicts weapon damage plus additional damage to an enemy and its nearest allies, affecting up to $x1 targets and knocking them back.", ua = "Завдає шкоди від зброї плюс додаткову шкоду ворогові та його найближчим союзникам, вражаючи до $x1 цілей і відкидаючи їх назад." },
    { en = "Sprays knives at all enemies within $A1 yards, inflicting $s1 Physical damage.", ua = "Розкидає ножі по всіх ворогах у межах $A1 ярдів, завдаючи $s1 фізичної шкоди." },
    { en = "Anvilrage Artillerists unleash a barrage of artillery fire every $t1 sec, inflicting $467427s1 Physical damage to enemies in the area.", ua = "Артилеристи Гнівоковадла обрушують шквал артилерійського вогню кожні $t1 сек., завдаючи $467427s1 фізичної шкоди ворогам у зоні дії." },
    { en = "Anvilrage Dragoons fire in coordinated volleys. Each shot inflicts $466663s1 Physical damage and knocks players back.", ua = "Драгуни Гнівоковадла стріляють злагодженими залпами. Кожен постріл завдає $466663s1 фізичної шкоди й відкидає гравців назад." },
    { en = "General Angerforge tosses a grenade into the air that explodes inflicting $464394s1 Fire damage to all players that are not hiding behind cover.", ua = "Генерал Гнівокуй підкидає в повітря гранату, що вибухає й завдає $464394s1 шкоди вогнем усім гравцям, які не сховалися за укриттям." },
    { en = "Toxitron fills the room with poison inflicting $463833s1 Nature damage to all players every $463833t1 sec for $d and inflicting Poison-Soaked.", ua = "Токситрон наповнює приміщення отрутою, завдаючи $463833s1 шкоди силами природи всім гравцям кожні $463833t1 с протягом $d і накладаючи Просочення отрутою." },
    { en = "Inflicts $s1 Physical damage and reduces healing taken by $s2% for $d.", ua = "Завдає $s1 фізичної шкоди і зменшує отримуване зцілення на $s2% протягом $d." },
    { en = "Inflicts $s1 Physical damage and increases Physical damage taken by $s2% for $d.", ua = "Завдає $s1 фізичної шкоди і збільшує отримувану фізичну шкоду на $s2% протягом $d." },
    { en = "When Livewire is removed, a violent Electrical Discharge inflicts $467930s1 Nature damage to players within $467930A1 yards.", ua = "Коли Дріт під напругою знімається, потужний Електричний розряд завдає $467930s1 шкоди силами природи гравцям у межах $467930A1 ярдів." },
    { en = "Grants a shield absorbing $s2 damage. While this shield persists it restores $s3 health every $t3 sec for $d.", ua = "Надає щит, що поглинає $s2 шкоди. Поки цей щит тримається, він відновлює $s3 здоров'я кожні $t3 с протягом $d." },
    { en = "Wreathes all players in rime. After $d, players erupt inflicting $466326s1 Frost damage to players within $466326A1 yards and rooting them for $466326d.", ua = "Огортає всіх гравців памороззю. Через $d гравці вибухають, завдаючи $466326s1 шкоди морозом гравцям у межах $466326A1 ярдів і знерухомлюючи їх на $466326d." },
    { en = "Ice shards pelt the target area, inflicting $464339s1 Frost damage every $464339t1 sec for $464338d and reducing movement speed by $464339s2%.", ua = "Крижані осколки гатять по цільовій зоні, завдаючи $464339s1 шкоди морозом кожні $464339t1 с протягом $464338d і знижуючи швидкість пересування на $464339s2%." },
    { en = "Afflicts $i players with Livewire. Livewires inflict $467928s1 Nature damage to players within $468021A1 yards every $467927t1 sec for $467927d.", ua = "Уражає $i гравців ефектом Дріт під напругою. Дроти під напругою завдають $467928s1 шкоди силами природи гравцям у межах $468021A1 ярдів кожні $467927t1 с протягом $467927d." },
    { en = "Fires Chemical Bombs, inflicting $463831s2 Nature damage on impact and creating a pool of flammable poison.", ua = "Випускає Хімічні бомби, які при влучанні завдають $463831s2 шкоди силами природи й утворюють калюжу займистої отрути." },
    { en = "Summons a totem of crystalline origin that periodically lobs gouts of energy at nearby locations, inflicting Volcanic damage to all enemies within $150263A1 yards and knocking them back.", ua = "Прикликає тотем кристалічного походження, що періодично жбурляє згустки енергії в сусідні місця, завдаючи вулканічної шкоди всім ворогам у радіусі $150263A1 м і відкидаючи їх." },
    { en = "Summons a Felguard; a powerful melee combatant.", ua = "Призиває Вартового Скверни, потужного бійця ближнього бою." },
    { en = "Banishes an enemy, preventing any action for $d. Reduces damage received by $s2% and healing received by $s3%.", ua = "Виганяє ворога, унеможливлюючи будь-які дії протягом $d. Зменшує отримувану шкоду на $s2% і отримуване зцілення на $s3%." },
    { en = "Poison-Soaked inflicts $467918s1 Nature damage every $467918t1 sec. Poison-Soaked is burned away from players who suffer damage from Flamethrower.", ua = "Просочення отрутою завдає $467918s1 шкоди силами природи кожні $467918t1 с. Просочення отрутою випалюється з гравців, які зазнають шкоди від Вогнемета." },
    { en = "Inflicts $s1 Fire damage to all players and combusts all Chemical Pools.", ua = "Завдає $s1 шкоди вогнем усім гравцям і підпалює всі Хімічні калюжі." },
    { en = "Inflicts $463822s1 Fire damage and applies $@spellname470655 to players in a $463822A1 yard cone every $t1 sec for $d.\n\n\n\nBurns away Poison-Soaked and explodes Chemical Pools.", ua = "Завдає $463822s1 шкоди вогнем і накладає $@spellname470655 на гравців у конусі завширшки $463822A1 ярдів кожні $t1 с протягом $d.\n\n\n\nВипалює ефект «Просочений отрутою» та підриває Хімічні Калюжі." },
    { en = "Causes a player to take $s1% increased Physical damage for $d.", ua = "Змушує гравця зазнавати на $s1% більше фізичної шкоди протягом $d." },
    { en = "Summons a totem of crystalline origin that periodically creates a pillar of blinding light at nearby locations, silencing all targets within $153551A2 yards.", ua = "Прикликає тотем кристалічного походження, що періодично створює стовп сліпучого світла в сусідніх місцях, занімовуючи всі цілі в радіусі $153551A2 м." },
    { en = "Strikes an enemy with a lightning bolt that arcs to up to $x1 nearby players inflicting $s1 Nature damage.", ua = "Уражає ворога блискавкою, яка перекидається на до $x1 гравців поблизу, завдаючи $s1 шкоди силами природи." },
    { en = "Releases a spray of knives at all enemies within $150981A1 yards, inflicting Physical damage.", ua = "Випускає віяло ножів по всіх ворогах у радіусі $150981A1 м, завдаючи фізичної шкоди." },
    { en = "Embraces oblivion, inflicting $s1 Shadow damage to all players.", ua = "Зливається з небуттям, завдаючи $s1 шкоди темрявою всім гравцям." },
    { en = "Executioner Gore immobilizes and drains $s1 health every $t1 from an enemy, transferring it to himself over $d.", ua = "Кат Ґор знерухомлює ворога й висмоктує $s1 здоров'я кожні $t1, переносячи його на себе протягом $d." },
    { en = "The Harbingers of Flame wreathe the Lyceum in intensifying flames, inflicting $464414s1 Fire damage every $464414t1 sec. This damage is increased by $464411s1% every $464412t1 sec until players are incinerated.\n\n\n\nHarbingers of Flame are immune to damage until a Shadowforge Torch consumes their fiery essence.", ua = "Провісники Полум'я огортають Ліцей дедалі сильнішим вогнем, завдаючи $464414s1 шкоди вогнем кожні $464414t1 с. Ця шкода зростає на $464411s1% кожні $464412t1 с, доки гравці не згорять дотла.\n\n\n\nПровісники Полум'я невразливі до шкоди, доки Смолоскип Тінькузні не поглине їхню вогняну есенцію." },
    { en = "Inflicts $s1 Fire damage to enemies within $A1 yards. Damage is reduced to enemies further from the caster.", ua = "Завдає $s1 шкоди вогнем ворогам у радіусі $A1 ярдів. Що далі ворог від заклинача, то менша шкода." },
    { en = "Executioner Gore slams his axe into the ground, inflicting $s3 Shadow damage to all enemies and an additional $s2 Shadow damage to targets caught in the frontal cone. The impact creates a lingering vortex that inflicts $152592s1 Shadow damage every second to enemies who remain within it.", ua = "Кат Ґор врубує сокиру в землю, завдаючи $s3 шкоди від темної магії всім ворогам і додатково $s2 шкоди від темної магії цілям, що потрапили в передній конус. Удар створює тривкий вихор, який завдає $152592s1 шкоди від темної магії щосекунди ворогам, що лишаються в ньому." },
    { en = "Bites a target, inflicting periodic Physical damage and leeching life over $151475D.", ua = "Кусає ціль, завдаючи періодичної фізичної шкоди й висмоктуючи життя протягом $151475D." },
    { en = "The Guardian of the Deep devours a Blue Shale Crawler, healing himself for $149921s2%.", ua = "Вартовий глибин пожирає синього сланцевого повзуна, зцілюючи себе на $149921s2%." },
    { en = "When Dagran falls below $s1% health, he beseeches the Firelord for aid, gaining a shield that absorbs $470598s1 damage.\n\n\n\nAn Avatar of Ragnaros joins the battle inflicting $465209s2 Fire damage to all players. The damage is decreased farther from the impact point.", ua = "Коли здоров'я Даґрана падає нижче $s1%, він благає Володаря Вогню про допомогу й отримує щит, що поглинає $470598s1 одиниць шкоди.\n\n\n\nАватар Раґнароса вступає в бій, завдаючи $465209s2 шкоди вогнем усім гравцям. Шкода зменшується з віддаленням від точки удару." },
    { en = "The Guardian of the Deep emits a piercing screech, inflicting $s1 damage to all enemies.", ua = "Вартовий глибин видає пронизливий вереск, завдаючи $s1 шкоди всім ворогам." },
    { en = "Death Speaker Blackthorn rears back and summons unholy strength to pummel enemies in a cone $a1 yards long in front of the caster, inflicting massive Physical damage.", ua = "Речник смерті Блекторн відхиляється назад і прикликає нечестиву силу, щоб гамселити ворогів у конусі завдовжки $a1 ярдів перед собою, завдаючи величезної фізичної шкоди." },
    { en = "Thruk slams his weapon on the ground, inflicting $s2% weapon damage to all enemies within $A2 yards.", ua = "Трук гепає зброєю об землю, завдаючи $s2% шкоди від зброї всім ворогам у радіусі $A2 ярдів." },
    { en = "Inflicts $s1 Volcanic damage to an enemy every $t1 sec for $d.\n\n\n\nCauses an enemy to take $s2% increased damage for $d. This effect stacks.", ua = "Завдає $s1 вулканічної шкоди ворогові кожні $t1 сек. протягом $d.\n\n\n\nЗмушує ворога зазнавати на $s2% більше шкоди протягом $d. Цей ефект накопичується." },
    { en = "Thruk casts his fishing line, hooking a random enemy within $A1 yards and pulling them to his feet.", ua = "Трук закидає вудку, чіпляючи випадкового ворога в радіусі $A1 ярдів і притягуючи його до своїх ніг." },
    { en = "Sends out pulses of sonic energy which create a Sonic Field at several locations. These fields inflict Physical damage to any player standing in them.\n\n\n\nAfter several seconds, charges one of the fields, releasing pulses of sonic energy. These pulses inflict Physical damage and stun any player who collides with them for $153214D.", ua = "Розсилає імпульси звукової енергії, що в кількох місцях створюють Звукове поле. Ці поля завдають фізичної шкоди кожному гравцеві, який у них стоїть.\n\n\n\nЗа кілька секунд заряджає одне з полів, вивільняючи імпульси звукової енергії. Ці імпульси завдають фізичної шкоди й приголомшують кожного гравця, який з ними зіткнувся, на $153214D." },
    { en = "Upon reaching half health, Hunter Bonetusk calls forth a stampede of boars over several seconds, inflicting Physical damage to any player struck by the boars.", ua = "Коли його здоров'я падає до половини, Мисливець Кістоклик за кілька секунд прикликає навалу вепрів, завдаючи фізичної шкоди кожному гравцеві, якого вони зачепили." },
    { en = "Deals $149894s1 Shadow damage to all enemies in a cone in front of the caster, every $t2 sec. for $d.", ua = "Завдає $149894s1 шкоди Тінню всім ворогам у конусі перед заклиначем, кожні $t2 с протягом $d." },
    { en = "Aku'mai tears at the cave's walls, causing falling debris that inflicts $152967s1 Physical damage every $t1 sec. to random enemies.", ua = "Аку'май роздирає стіни печери, спричиняючи падіння уламків, що завдають $152967s1 фізичної шкоди кожні $t1 с випадковим ворогам." },
    { en = "A Burning Spirit sacrifices itself to infuse Ambassador Flamelash with fiery vigor, causing him to inflict $468304s1 Fire damage to all players every $470493t1 sec until all stacks are consumed.", ua = "Палаючий дух приносить себе в жертву, наповнюючи Посла Полум'ябоя вогняною снагою, через що він завдає $468304s1 шкоди вогнем усім гравцям кожні $470493t1 сек., доки не вичерпаються всі заряди." },
    { en = "Summons a tempest that inflicts $149888s1 Shadow damage every $t1 sec. to random enemies.", ua = "Прикликає бурю, що завдає $149888s1 шкоди від темної магії кожні $t1 с випадковим ворогам." },
    { en = "Sets his sights on a player, then fires a volley of flaming arrows nearby. Being struck by an arrow inflicts Fire damage.", ua = "Бере гравця на приціл, а тоді випускає залп палаючих стріл неподалік. Влучна стріла завдає вогняної шкоди." },
    { en = "Fireguard Destroyers erupt in a shower of flames inflicting $465095s1 Fire damage to players in the area and summoning Firelings. If no player is struck then all players suffer $465276s1 Fire damage.", ua = "Руйнівники Вогняної Сторожі вибухають зливою полум'я, завдаючи $465095s1 шкоди вогнем гравцям у зоні та прикликаючи вогнят. Якщо жодного гравця не влучено, усі гравці зазнають $465276s1 шкоди вогнем." },
    { en = "Ghamoo-Ra charges a random target's destination, inflicting $149868s1 Physical damage to enemies in his path, then releases a violent burst of energy, dealing an additional $149869s3 Physical damage to enemies within $149869A3 yards.", ua = "Ґаму-Ра кидається до позиції випадкової цілі, завдаючи ворогам на своєму шляху $149868s1 фізичної шкоди, після чого вивільняє потужний сплеск енергії, завдаючи додатково $149869s3 фізичної шкоди ворогам у радіусі $149869A3 ярдів." },
    { en = "Anvilrage Sappers denote when they reach a player, inflicting $464427s1 Physical damage to players within $464427A1 yards.", ua = "Сапери Гнівоковадла вибухають, діставшись гравця, завдаючи $464427s1 фізичної шкоди гравцям у радіусі $464427A1 ярдів." },
    { en = "Focuses his vision, rapidly firing a barrage of arrows at his target, inflicting Physical damage every half-second for $150881D.", ua = "Зосереджує погляд і швидко випускає шквал стріл у ціль, завдаючи фізичної шкоди щопівсекунди протягом $150881D." },
    { en = "Inflicts $149851s2 Nature damage to all enemies in a cone $a1 yards long.", ua = "Завдає $149851s2 шкоди від сил природи всім ворогам у конусі завдовжки $a1 ярдів." },
    { en = "General Angerforge throws dark iron bombs at up to $i players, inflicting $466262s1 Fire damage to players in the area. Stepping into a Dark Iron Bomb inflicts $466262s1 Fire damage to players within $466262A1 yards.", ua = "Генерал Гнівокуй жбурляє бомби з чорного заліза в щонайбільше $i гравців, завдаючи $466262s1 шкоди вогнем гравцям у зоні дії. Якщо наступити на бомбу з чорного заліза, вона завдає $466262s1 шкоди вогнем гравцям у радіусі $466262A1 ярдів." },
    { en = "Fixates an enemy, ignoring all others.", ua = "Зосереджується на ворогові, нехтуючи всіма іншими." },
    { en = "Mushlump vomits up a cloud of bile.  Enemies within the area are infected with disease inflicting $s1 Nature damage every $t1 sec.", ua = "Грибогруд вивергає хмару жовчі.  Вороги в зоні дії заражаються хворобою, що завдає $s1 шкоди від сил природи кожні $t1 с." },
    { en = "The caster steps through the shadows, appearing behind their target.", ua = "Заклинач ступає крізь тіні й з'являється позаду своєї цілі." },
    { en = "Inflicts Physical damage and slows movement speed by $150859s2%. Costs $150859C Energy.", ua = "Завдає фізичної шкоди й сповільнює швидкість руху на $150859s2%. Коштує $150859C енергії." },
    { en = "Inflicts Physical damage to the current target every $149835t1 sec. for $149835d.", ua = "Завдає фізичної шкоди поточній цілі кожні $149835t1 с протягом $149835d." },
    { en = "Ragnaros hurls a massive boulder of magma inflicting $465097s1 Fire damage split between players in the area and shattering the ground into $@spellname470646. This damage pierces immunities.", ua = "Раґнарос жбурляє величезну брилу магми, що завдає $465097s1 шкоди вогнем, розподіленої між гравцями в зоні, і розтрощує землю на $@spellname470646. Ця шкода пробиває імунітети." },
    { en = "Inflicts $466382s1 Fire damage every $466382t1 sec to players in the area.", ua = "Завдає $466382s1 шкоди вогнем кожні $466382t1 сек. гравцям у зоні." },
    { en = "Shoots poisoned arrows at enemies inflicting Nature damage, then additional Nature damage every $150849t2 sec. for $150849D.", ua = "Стріляє отруйними стрілами по ворогах, завдаючи природної шкоди, а тоді додаткової природної шкоди кожні $150849t2 сек. протягом $150849D." },
    { en = "Readies a massive attack that strikes the ground after a short delay, inflicting Physical damage.", ua = "Готує потужну атаку, що після короткої затримки б'є по землі, завдаючи фізичної шкоди." },
    { en = "Upon dying, casts $@spellname470330, inflicting $s1 Fire damage to all players.", ua = "Гинучи, творить $@spellname470330, завдаючи $s1 шкоди вогнем усім гравцям." },
    { en = "Inflicts $s2% weapon damage as Physical damage and interrupts spell casting for $d.", ua = "Завдає $s2% шкоди зброї як фізичну шкоду й перериває прочитання заклять на $d." },
    { en = "Conceals the caster from sight. This effect is removed when entering combat.", ua = "Приховує заклинача з очей. Цей ефект знімається зі вступом у бій." },
    { en = "Lord Roccor transforms a pool of roiling magma into a Son of Roccor.", ua = "Лорд Роккор перетворює калюжу вируючої магми на Сина Роккора." },
    { en = "A fiery beam connects each Blazing Servitor.  Contact with the beam inflicts $s1 Fire damage every $151867t1 sec.", ua = "Вогняний промінь з'єднує кожного палаючого служника.  Дотик до променя завдає $s1 шкоди від вогню кожні $151867t1 с." },
    { en = "Deploys a soldier to attack the players. Players standing on the Mole Machine's arrival point suffer $467756s1 Physical damage and are knocked back.", ua = "Розгортає солдата для нападу на гравців. Гравці, що стоять на місці прибуття кротомашини, зазнають $467756s1 фізичної шкоди й відкидаються назад." },
    { en = "Bael'Gar inflicts $462969s1 Volcanic damage to players that are not hiding behind a boulder.", ua = "Бейл'Ґар завдає $462969s1 вулканічної шкоди гравцям, що не ховаються за валуном." },
    { en = "Empowering his axe with powers from the Spirit realm, Warlord Ramtusk throws his axe at a location, striking all nearby enemies for high Arcane damage.", ua = "Наповнивши сокиру силами зі світу духів, Воєначальник Тараноклик кидає її в певне місце, б'ючи всіх ворогів неподалік і завдаючи високої арканної шкоди." },
    { en = "Aku'mai widens the portal, allowing more pieces of himself to emerge from the void.", ua = "Аку'май розширює портал, дозволяючи більшій частині себе вийти з порожнечі." },
    { en = "Bathiel inflicts $151815s1 Frost damage every $t1 sec. to random enemies.", ua = "Батіель завдає $151815s1 шкоди від криги кожні $t1 с випадковим ворогам." },
    { en = "Amnennar creates an area of freezing cold that inflicts $s1 Frost damage to all enemies within the area of effect.", ua = "Амненнар створює зону крижаного холоду, що завдає $s1 шкоди Морозом усім ворогам у межах дії." },
    { en = "Fires a well-aimed Arcane Shot at a random enemy's head, inflicting high Arcane damage creating a zone of Arcane damage at their feet for $151286D.", ua = "Випускає влучний Арканний постріл у голову випадкового ворога, завдаючи високої арканної шкоди й створюючи під його ногами зону арканної шкоди на $151286D." },
    { en = "Creates a whirling torrent of Fire, Nature, and Frost magic that strikes a target for high Elemental damage.", ua = "Створює вируючий потік магії вогню, природи й льоду, що б'є по цілі, завдаючи високої стихійної шкоди." },
    { en = "Charges to an enemy and becomes an unstoppable storm of destructive force, inflicting $464350s1 Physical damage every $464349t1 sec for $464349d to players within $464350A1 yards.", ua = "Кидається на ворога й перетворюється на нестримну бурю руйнівної сили, завдаючи $464350s1 фізичної шкоди щосекунди ($464349t1 сек.) протягом $464349d гравцям у радіусі $464350A1 ярдів." },
    { en = "Under 75% health, Roogug will periodically go into a blood frenzy, increasing all allies damage dealt by $150768s1% and haste by $150768s2%. This effect stacks.", ua = "Нижче 75% здоров'я Рооґуґ періодично впадає в кровожерливе шаленство, збільшуючи завдану всіма союзниками шкоду на $150768s1%, а поспіх — на $150768s2%. Цей ефект накопичується." },
    { en = "Aku'mai spits caustic venom at an enemy, inflicting $s1 Nature damage.", ua = "Аку'май плює їдкою отрутою у ворога, завдаючи $s1 шкоди від сил природи." },
    { en = "Flamelash summons Firestarters, inflicting $464381s2 Fire damage to players in the area.", ua = "Полум'ябій прикликає палітелів, завдаючи $464381s2 шкоди вогнем гравцям у зоні дії." },
    { en = "Fires a ball of venom at a random enemy's destination that does $151269s2 Nature damage on impact and leaves a pool of Toxic Bile.", ua = "Вистрілює кулю отрути в позицію випадкового ворога, завдаючи при влучанні $151269s2 шкоди від сил природи й лишаючи калюжу токсичної жовчі." },
    { en = "Vile'rel assaults the mind of a player, inflicting $469724s1 Shadow damage every $469723t1 sec for $469723d. Damage is split between players within $469724A1 yards of the target.", ua = "Вайл'рел атакує розум гравця, завдаючи $469724s1 шкоди темрявою кожні $469723t1 с протягом $469723d. Шкода розподіляється між гравцями в межах $469724A1 ярдів від цілі." },
    { en = "Forms an orb of spiritual energy that travels towards a random foe, blasting them for Spellshadow damage.", ua = "Утворює сферу духовної енергії, що рухається до випадкового ворога, вражаючи його магічно-темною шкодою." },
    { en = "Fears and inflicts $s1 Shadow damage to all players within $A1 yards of the impact every $t1 sec for $d.", ua = "Наганяє жах і завдає $s1 шкоди темрявою всім гравцям у межах $A1 ярдів від місця влучання кожні $t1 с протягом $d." },
    { en = "Ragnaros summons a Fireguard Destroyer. The summoning inflicts $465100s2 Fire damage to all enemies. Damage is reduced farther from the impact point.", ua = "Раґнарос прикликає Руйнівника Вогняної Сторожі. Прикликання завдає $465100s2 шкоди вогнем усім ворогам. Шкода зменшується з віддаленням від точки удару." },
    { en = "A powerful psychic blast inflicts $s1 Shadow damage.", ua = "Потужний психічний вибух завдає $s1 шкоди темрявою." },
    { en = "A fiery boulder Inflicts $s1 Fire damage and $s2 Fire damage every $t2 sec for $d.", ua = "Вогняна брила завдає $s1 шкоди вогнем, а далі $s2 шкоди вогнем кожні $t2 сек. протягом $d." },
    { en = "Inflicts $s1 Physical damage to players in front of the caster every $t1 sec for $d.", ua = "Завдає $s1 фізичної шкоди гравцям перед заклинателем кожні $t1 сек. протягом $d." },
    { en = "Causes a player to suffer $s1% increased Fire damage for $d.", ua = "Змушує гравця зазнавати на $s1% більше шкоди вогнем протягом $d." },
    { en = "Creates several lines of elemental fury, inflicting high Fire damage to all players struck.", ua = "Створює кілька ліній стихійної люті, завдаючи високої вогняної шкоди всім враженим гравцям." },
    { en = "Inflicts Physical damage to a player. The duration of the caster's next $@spellname466111 increases by $s2 sec. This effect stacks up to $u times.", ua = "Завдає гравцеві фізичної шкоди. Тривалість наступного застосування $@spellname466111 заклиначем збільшується на $s2 сек. Цей ефект накопичується до $u разів." },
    { en = "Ambassador Flamelash channels his full fury into his target, inflicting $470356s1 Fire damage to players within $470356A1 yards every $t1 sec, split between enemies struck.\n\n\n\nIf Ambassador Flamelash's target is killed, his energy is refilled.\n\n\n\nAmbassador Flamelash's target is afflicted with $@spellname470207.", ua = "Посол Флеймлеш спрямовує всю свою лють на ціль, завдаючи $470356s1 шкоди вогнем гравцям у радіусі $470356A1 ярдів кожні $t1 с, розподіленої між ураженими ворогами.\n\n\n\nЯкщо ціль Посла Флеймлеша гине, його енергія поновлюється.\n\n\n\nЦіль Посла Флеймлеша уражено ефектом $@spellname470207." },
    { en = "Shatters a player's armor, inflicting $s1 Physical damage and increasing Physical damage taken by $s2% until the end of the encounter.", ua = "Трощить броню гравця, завдаючи $s1 фізичної шкоди та підвищуючи отримувану фізичну шкоду на $s2% до кінця бою." },
    { en = "$s1 Twilight's Hammer Ambassadors arrive to defend Emperor Thaurissan.", ua = "$s1 послів культу Сутінкового Молота прибувають на захист Імператора Тауріссана." },
    { en = "A Dark Iron Imperial Guard arrives in a mole machine to assist the Emperor. The mole machine inflicts $465078s1 Physical damage and knocks players back.", ua = "Імператорський вартовий Темного Заліза прибуває в кротовій машині на допомогу Імператору. Кротова машина завдає $465078s1 фізичної шкоди й відкидає гравців назад." },
    { en = "Magma Clap's explosions erupt in a shower of lava, inflicting $465074s1 Fire damage to players in the area.", ua = "Вибухи Магмового Ляпасу здіймають зливу лави, завдаючи $465074s1 шкоди вогнем гравцям у зоні." },
    { en = "Breaks the linking of Spirits using Shadow magic, increasing healing taken by $151218s1% and periodically inflicting Shadow damage and preventing the target from benefitting from the Spirit Link Totem.", ua = "Розриває зв'язок духів за допомогою темної магії, збільшуючи отримане зцілення на $151218s1%, періодично завдаючи темної шкоди й позбавляючи ціль користі від Тотема духовного зв'язку." },
    { en = "Fires egg sacs at random enemy destinations that inflict $152757s1 Physical damage on impact and births a brood of Guardian Hatchlings.", ua = "Вистрілює яйцеві мішки в позиції випадкових ворогів, завдаючи при влучанні $152757s1 фізичної шкоди й породжуючи виводок дитинчат-вартових." },
    { en = "Restores $s1 health to an ally.", ua = "Відновлює $s1 здоров'я союзникові." },
    { en = "Ironfoe leaves behind Iron Brand inflicting $s1 Fire damage every $t1 sec for $d.", ua = "Залізний Ворог лишає Залізне Тавро, що завдає $s1 шкоди вогнем кожні $t1 сек. протягом $d." },
    { en = "When Moira is defeated or Dagran falls below $466332s1% health, Dagran transforms into a powerful Avatar of Flame, empowering his abilities.", ua = "Коли Мойру переможено або здоров'я Даґрана падає нижче $466332s1%, Даґран перетворюється на могутнього Аватара Полум'я, посилюючи свої здібності." },
    { en = "Hurls flaming hammers at $s1 players inflicting $465064s1 Fire damage and knocking players back.", ua = "Жбурляє палаючі молоти в $s1 гравців, завдаючи $465064s1 шкоди вогнем і відкидаючи гравців назад." },
    { en = "Slams the ground inflicting $465321s1 Fire damage to players within $465321A1 yards and causing violent explosions beneath distant players inflicting $465068s1 Fire damage.", ua = "Б'є по землі, завдаючи $465321s1 шкоди вогнем гравцям у радіусі $465321A1 ярдів і спричиняючи потужні вибухи під віддаленими гравцями, які завдають $465068s1 шкоди вогнем." },
    { en = "When any player comes within $s2 yards, the Firestarter combusts, inflicting $s1 Physical damage to players within $A1 yards and begins casting $@spellname464983.", ua = "Коли будь-який гравець наближається на $s2 ярдів, палітель спалахує, завдаючи $s1 фізичної шкоди гравцям у радіусі $A1 ярдів, і починає творити $@spellname464983." },
    { en = "The Firestarter explodes, inflicting $s1 Fire damage to players within $A1 yards.", ua = "Палітель вибухає, завдаючи $s1 шкоди вогнем гравцям у радіусі $A1 ярдів." },
    { en = "Every $s1 autoattacks, Emperor Thaurissan strikes $s2 additional times.", ua = "Кожні $s1 автоатаки Імператор Тауріссан завдає $s2 додаткових ударів." },
    { en = "Drains $150679s1 health every $150679t1 sec. transferring 75%  of it to the caster and inflicts $150709s1 Shadow damage to all allies.\n\n\n\nEntering Redeemed Soil causes Amnennar to become Overwhelmed stunning him for $150707d.", ua = "Висмоктує $150679s1 здоров'я кожні $150679t1 сек., передаючи 75% із нього творцеві, і завдає $150709s1 темної шкоди всім союзникам.\n\n\n\nКоли Амненнар ступає на Спокутувану землю, він стає Здоланим і приголомшується на $150707d." },
    { en = "Roots in place and begins casting $@spellname464379, up to $s1 times.", ua = "Знерухомлює на місці й починає творити $@spellname464379, до $s1 разів." },
    { en = "Lord Incendius wreathes $i players in consumptive flames inflicting $463504s1 Fire damage every $463504t1 sec for $463504d.", ua = "Лорд Інцендій огортає $i гравців спопеляючим полум'ям, завдаючи $463504s1 шкоди вогнем кожні $463504t1 с протягом $463504d." },
    { en = "Lord Incendius amplifies the force of scorching wind against his current target and inflicts $463500s1 Fire damage every $463500t1 sec. Taunting Lord Incendius forces him to switch targets.", ua = "Лорд Інцендій підсилює міць пекучого вітру проти своєї поточної цілі й завдає $463500s1 шкоди вогнем кожні $463500t1 с. Якщо Лорда Інцендія спровокувати, він змушений змінити ціль." },
    { en = "Lord Incendius creates a powerful scorching wind, inflicting $463644s1 Fire damage every $463644t1 sec and pushing all players towards the edge of the bridge for $d.", ua = "Лорд Інцендій здіймає потужний пекучий вітер, що завдає $463644s1 вогняної шкоди кожні $463644t1 сек. і штовхає всіх гравців до краю мосту протягом $d." },
    { en = "Periodically, the Spirit Link Totem redistributes the health of all targets, such that each target ends up with the same percentage of their maximum health.\n\n\n\nThis affects both players and enemies as separate pools of health.\n\n\n\nThe Spirit Link Totem solidifies the spiritual bond between friend and foe, drawing in all nearby targets who are not inside the Spirit Link Totem.", ua = "Тотем духовного зв'язку періодично перерозподіляє здоров'я всіх цілей так, щоб у кожної лишився однаковий відсоток її максимального здоров'я.\n\n\n\nЦе впливає на гравців і ворогів як на окремі сукупності здоров'я.\n\n\n\nТотем духовного зв'язку зміцнює духовний зв'язок між друзями й ворогами, притягуючи всі сусідні цілі, що перебувають поза Тотемом духовного зв'язку." },
    { en = "Heals an ally for $s1 damage every $t1 sec. and increases healing done by 100%.\n\n\n\nIf a player affected with Soul Leech enters the area, Amnennar becomes stunned for $150707d. and Soul Leech is removed.", ua = "Зцілює союзника на $s1 кожні $t1 с. та збільшує завдане зцілення на 100%.\n\n\n\nЯкщо гравець під дією Висмоктування Душі заходить у цю зону, Амненнар оглушується на $150707d, а Висмоктування Душі знімається." },
    { en = "Magma Clap applies $@spellname470658, inflicting $s1 Fire damage every $t1 sec for $d.", ua = "Магмовий ляск накладає $@spellname470658, завдаючи $s1 шкоди вогнем кожні $t1 сек. протягом $d." },
    { en = "Aku'mai's tentacle slams the ground, inflicting $s2 Physical damage and stunning all enemies in a cone in front of the caster.", ua = "Щупальце Аку'май гепає об землю, завдаючи $s2 фізичної шкоди й оглушуючи всіх ворогів у конусі перед закляттям." },
    { en = "Golem Lord Argelmach's golems share health.", ua = "Големи Лорда-голема Арґельмаха мають спільне здоров'я." },
    { en = "Violent energy erupts from Ghamoo-Ra, inflicting $151684s1 Nature damage to a random enemy every $t1 sec.", ua = "З Ґаму-Ра вивергається потужна енергія, завдаючи випадковому ворогові $151684s1 шкоди від сил природи кожні $t1 с." },
    { en = "Lord Incendius hurls fire inflicting $463470s2 Fire damage to players in the area and summoning a Flame Geyser.", ua = "Лорд Інцендій жбурляє вогонь, завдаючи $463470s2 шкоди вогнем гравцям у зоні та призиваючи Вогняний гейзер." },
    { en = "Lord Incendius sets fire to portions of the bridge every $t1 sec, inflicting $463492s1 Fire damage to players in the area every $463492t1 sec.", ua = "Лорд Інцендій підпалює частини мосту кожні $t1 с, завдаючи $463492s1 шкоди вогнем гравцям у зоні кожні $463492t1 с." },
    { en = "Inflicts heavy Physical damage to enemies in front of Bael'Gar, split between enemies struck.", ua = "Завдає тяжкої фізичної шкоди ворогам перед Бейл'Ґаром, розподіленої між ураженими ворогами." },
    { en = "Fills the room with clouds of thick smoke for $464354d. Player range is reduced by $464356s1% while the smoke persists.", ua = "Наповнює кімнату хмарами густого диму на $464354d. Поки тримається дим, дальність гравців зменшено на $464356s1%." },
    { en = "Bael'Gar delivers a powerful stomp inflicting $462972s2 Physical damage to all enemies and shattering any remaining boulders. Shattered boulders inflict an additional $462973s1 Physical damage to all enemies.", ua = "Бейл'Ґар наносить потужний удар ногою, завдаючи $462972s2 фізичної шкоди всім ворогам і розбиваючи валуни, що лишилися. Розбиті валуни завдають усім ворогам додаткових $462973s1 фізичної шкоди." },
    { en = "Ragnaros rains lava from above, inflicting $470652s1 Fire damage to $470650i players every ${$t2}.2 sec for $d.", ua = "Раґнарос проливає лаву згори, завдаючи $470652s1 шкоди вогнем $470650i гравцям кожні ${$t2}.2 сек. протягом $d." },
    { en = "Upon dying, the molten heart of a Spawn of Bael'Gar inflicts $462968s1 Fire damage to a random player every $462968t1 sec for $462968d.", ua = "Гинучи, розплавлене серце поріддя Бел'Ґара завдає $462968s1 шкоди вогнем випадковому гравцеві кожні $462968t1 сек. протягом $462968d." },
    { en = "Kor'ul summons Aku'mai, terror of the deep, to feed.", ua = "Кор'ул прикликає Аку'май, жах глибин, щоб нагодувати її." },
    { en = "The Seven share health.", ua = "Семеро мають спільне здоров'я." },
    { en = "Before dying, Flame Geysers cast Dying Flare, knocking back and inflicting $463472s1 Fire damage to players within $463472A1 yards. Damage is split between players struck. If no player is struck by Dying Flare, all players suffer $463472s3 Fire damage.", ua = "Перед загибеллю Вогняні гейзери застосовують Передсмертний спалах, відкидаючи гравців у межах $463472A1 ярдів і завдаючи їм $463472s1 шкоди вогнем. Шкода розподіляється між ураженими гравцями. Якщо Передсмертний спалах не зачепив жодного гравця, усі гравці зазнають $463472s3 шкоди вогнем." },
    { en = "Flame Geysers cast Blaze inflicting $463471s1 Fire damage to all players. Successive casts of Blaze gain $463473s2% haste.", ua = "Вогняні гейзери застосовують Багаття, завдаючи $463471s1 шкоди вогнем усім гравцям. Кожне наступне прочитання Багаття отримує $463473s2% поспіху." },
    { en = "Kor'ul begins crushing an enemy, inflicting $s2 Physical damage every $t2 sec. for $d.", ua = "Кор'ул починає душити ворога, завдаючи $s2 фізичної шкоди кожні $t2 с протягом $d." },
    { en = "A pool of flammable chemicals inflicts $464473s1 Nature damage every $464473t1 sec to enemies in the area.", ua = "Калюжа займистих хімікатів завдає $464473s1 шкоди силами природи кожні $464473t1 с ворогам у зоні." },
    { en = "When a portal's nearby anchors are destroyed it becomes unstable, inflicting $464998s1 Fire damage to all players every $464999t1 sec until all portal anchors are destroyed.", ua = "Коли поблизькі якорі порталу знищено, він стає нестабільним і завдає $464998s1 шкоди вогнем усім гравцям кожні $464999t1 сек., доки не буде знищено всі якорі порталу." },
    { en = "Inflicts $s1 Nature damage to nearby enemies.", ua = "Завдає $s1 шкоди від сил природи ворогам поблизу." },
    { en = "Flamethrower and Incineration combust Chemical Pools inflicting $464485s1 Nature damage to all players.", ua = "Вогнемет і Спопеління підпалюють Хімічні калюжі, завдаючи $464485s1 шкоди силами природи всім гравцям." },
    { en = "A player suffering from $@spellname470603 attempting to receive Shadow Word: Necrosis will instead lose $s1% health as Shadow damage.", ua = "Гравець, що страждає від $@spellname470603 і намагається отримати «Слово Темряви: Некроз», натомість втрачає $s1% здоров'я як шкоду темрявою." },
    { en = "After a player passes Shadow Word: Necrosis, they are afflicted with $@spellname470603.", ua = "Після того як гравець передає «Слово Темряви: Некроз», його уражає $@spellname470603." },
    { en = "Shadows engulf the target inflicting $s1 Shadow damage every $t1 seconds for $d.", ua = "Тіні огортають ціль, завдаючи $s1 шкоди від темної магії кожні $t1 с протягом $d." },
    { en = "Fixates a player, ignoring all others.", ua = "Зосереджується на гравцеві, нехтуючи всіма іншими." },
    { en = "Moira unleashes a series of psychic waves every $t1 sec for $d, inflicting $470610s1 Shadow damage to players in the area.", ua = "Мойра вивільняє низку психічних хвиль кожні $t1 сек. протягом $d, завдаючи $470610s1 шкоди темрявою гравцям у зоні." },
    { en = "Inflicts $s1 Radiant damage every $t1 sec for $d.", ua = "Завдає $s1 шкоди сяйвом кожні $t1 сек. протягом $d." },
    { en = "Moira channels a beam of holy fire into Dagran, restoring $470607s1% health to Moira and Dagran every $t1 sec for $d. Players intercepting the beam suffer Radiant Burn every $t1 sec and prevent the healing.", ua = "Мойра спрямовує промінь священного вогню в Даґрана, відновлюючи Мойрі та Даґранові $470607s1% здоров'я кожні $t1 сек. протягом $d. Гравці, що перехоплюють промінь, зазнають Сяйного Опіку кожні $t1 сек. і не дають відбутися зціленню." },
    { en = "Inflicts $466502s1 Shadow damage every $466502t1 sec until Moira is defeated. Every $s1 sec, Shadow Word: Nemesis gains a stack. Dispelling Shadow Word: Nemesis causes it to jump to $s2 other players.", ua = "Завдає $466502s1 шкоди темрявою кожні $466502t1 сек., доки Мойру не буде переможено. Кожні $s1 сек. «Слово Темряви: Немезида» отримує заряд. Розвіювання «Слова Темряви: Немезида» змушує його перестрибнути на $s2 інших гравців." },
    { en = "Summons forth three Splinterbone Warriors to assist Death Speaker Blackthorn.", ua = "Прикликає трьох воїнів-костоламів на допомогу Речникові смерті Блекторну." },
    { en = "Afflicts a player with a shadowy contagion reducing healing taken by $470600s1%. Standing within $s1 yards of another player for $s2 sec causes the contagion to pass to the nearby player and unleashes a $@spellname470602.", ua = "Уражає гравця тіньовою заразою, що зменшує отримуване зцілення на $470600s1%. Якщо лишатися в радіусі $s1 ярдів від іншого гравця протягом $s2 сек., зараза передається ближньому гравцю й вивільняє $@spellname470602." },
    { en = "Injects the target with a plagued-filled toxin that inflicts $s1 Nature damage every $t1 sec. for $d.  The target's movement speed is also reduced by $s2%", ua = "Впорскує в ціль чумний токсин, що завдає $s1 шкоди від сил природи кожні $t1 с протягом $d.  Швидкість пересування цілі також знижується на $s2%" },
    { en = "Hands of Thaurissan emit spheres of magma along their path, inflicting $466492s1 Fire damage.", ua = "Руки Тауріссана випускають на своєму шляху сфери магми, що завдають $466492s1 шкоди вогнем." },
    { en = "Potent arcane energy coalesces around golems and slowly moves towards Arcanotron. Any target that touches the arcane energy will gain $470075s1% increased damage for $470075d, stacking up to $470075u times.", ua = "Потужна арканна енергія збирається навколо големів і повільно рухається до Арканотрона. Будь-яка ціль, що торкнеться арканної енергії, завдаватиме на $470075s1% більше шкоди протягом $470075d; накопичується до $470075u разів." },
    { en = "Aarux attaches a strong filament of webbing to the target and begins dragging the player towards himself.  If Aarux pulls the player close enough they are bitten and infected with Plagued Bite causing $150082s1 Nature damage every $150082t1 sec. for $150082d.", ua = "Аарукс чіпляє до цілі міцну павутинну нитку й починає притягувати гравця до себе.  Якщо Аарукс підтягне гравця достатньо близько, той дістає укус і зараження «Чумним укусом», що завдає $150082s1 шкоди від сил природи кожні $150082t1 с протягом $150082d." },
    { en = "Fires a mortar at a player, inflicting $467503s1 Physical damage to players in the area.", ua = "Стріляє з міномета по гравцеві, завдаючи $467503s1 фізичної шкоди гравцям у зоні дії." },
    { en = "Increases the damage of allies within $s1 yards by $464426s1%, reduces damage taken by $464426s2%, and grants immunity to interrupts.", ua = "Підвищує шкоду союзників у радіусі $s1 ярдів на $464426s1%, зменшує отримувану шкоду на $464426s2% та дає несприйнятливість до переривань." },
    { en = "Golem Lord Argelmach's freed soul possesses a golem, granting it $464939s1 energy every $464939t1 sec.", ua = "Звільнена душа Лорда-голема Арґельмаха вселяється в голема, надаючи йому $464939s1 енергії кожні $464939t1 с." },
    { en = "Binds the target, rooting and tormenting them with Fire, Frost, and Nature damage every second for $151583D.", ua = "Сковує ціль, знерухомлюючи її та катуючи вогняною, крижаною й природною шкодою щосекунди протягом $151583D." },
    { en = "Congeals and lobs viscous venom at a location for $151571D. This blob periodically fires venemous orbs nearby, inflicting Nature damage to any players struck.", ua = "Згущує й жбурляє в певне місце в'язку отруту, що лишається там на $151571D. Цей згусток періодично випускає отруйні сфери неподалік, завдаючи природної шкоди кожному враженому гравцеві." },
    { en = "Calls upon Shadow magic to heal a single undead target.", ua = "Звертається до темної магії, щоб зцілити одну ціль-нежить." },
    { en = "Crumbling Ceiling inflicts $463891s1 Physical damage to players in the area.", ua = "Стеля, що обвалюється, завдає $463891s1 фізичної шкоди гравцям у цій зоні." },
    { en = "Bathiel absorbs the Restorative Water, healing himself for $s1% of his max health.", ua = "Батіель поглинає цілющу воду, зцілюючи себе на $s1% від максимального здоров'я." },
    { en = "Bael'Gar causes the ceiling to crumble, pummeling the area with rocks and inflicting $469303s2 Physical damage every $t1 sec for $d to all players.\n\n\n\nBoulders inflict $462949s2 Physical damage to players, decreasing the farther away the player is from the impact point.", ua = "Бейл'Ґар обвалює стелю, засипаючи зону камінням і завдаючи $469303s2 фізичної шкоди кожні $t1 сек. протягом $d усім гравцям.\n\n\n\nВалуни завдають гравцям $462949s2 фізичної шкоди, що зменшується, чим далі гравець від місця падіння." },
    { en = "Lord Roccor creates a pool of roiling magma inflicting $462352s1 Volcanic damage every $462352t1 sec to enemies in the area.", ua = "Лорд Роккор створює калюжу вируючої магми, що завдає $462352s1 вулканічної шкоди кожні $462352t1 сек. ворогам у цій зоні." },
    { en = "Draws in players over $151562d. and periodically inflicts Frost damage to all players within $151564A2 yards.", ua = "Притягує гравців протягом $151562d і періодично завдає крижаної шкоди всім гравцям у радіусі $151564A2 м." },
    { en = "Summons expanding rings of fire around the caster inflicting $467463s1 Fire damage to players in the area when they erupt.", ua = "Прикликає навколо заклинача кільця вогню, що розширюються й, вибухаючи, завдають $467463s1 шкоди вогнем гравцям у зоні дії." },
    { en = "Stepping into a Living Magma will destroy it but inflicts $462348s1 Volcanic damage every $462348t1 sec for $462348d. This effect stacks.", ua = "Ступивши в Живу магму, ви знищите її, але зазнаєте $462348s1 вулканічної шкоди кожні $462348t1 сек. протягом $462348d. Цей ефект накопичується." },
    { en = "The Restorative Water explodes, dealing $s1 Frost damage to enemies within $A1 yards.", ua = "Цілюща вода вибухає, завдаючи $s1 шкоди від криги ворогам у радіусі $A1 ярдів." },
    { en = "Portions of Bathiel spray across the room, summoning a circle of Restorative Waters.", ua = "Частки Батіеля розбризкуються по залі, прикликаючи коло цілющих вод." },
    { en = "Mordresh Fire Eye creates a rift to the elemental plane of fire summoning a Blazing Servitor to assist the caster.", ua = "Мордреш Вогняне Око створює розлом до елементальної площини вогню, прикликаючи палаючого служника собі на допомогу." },
    { en = "Allows an engineer to make basic contraptions. Requires stone and metal found with the Mining skill.", ua = "Дозволяє інженеру виготовляти базові пристрої. Потребує каменю й металу, які видобуваються навичкою Гірництва." },
    { en = "You grow larger and your Strength is increased by $s1 to match your new size.  Lasts $d.  Battle Elixir.", ua = "Ви стаєте більшими, а ваша Сила зростає на $s1 відповідно до нового розміру. Триває $d. Бойовий еліксир." },
    { en = "Charge to an enemy, immobilizing them for $45334d.", ua = "Кидається до ворога, знерухомлюючи його на $45334d." },
    { en = "Leap behind an enemy, dazing them for $50259d.", ua = "Стрибаєте за спину ворогу, запаморочуючи його на $50259d." },
    { en = "Cannot benefit from Heroism or other similar effects.", ua = "Не може отримати вигоду від Героїзму чи інших подібних ефектів." },
    { en = "Cannot benefit from Bloodlust or other similar effects.", ua = "Не може отримати вигоду від Кровожерливості чи інших подібних ефектів." },
    { en = "You champion the cause of the Wyrmrest Accord.  All reputation gains while in Northrend dungeons will be applied to your standing with them.", ua = "Ви відстоюєте справу Згоди Драконього Спокою. Весь приріст репутації в підземеллях Нортренду зараховуватиметься до вашого статусу серед них." },
    { en = "Activate to slip into the shadows, reducing the chance for enemies to detect your presence. Lasts until cancelled or upon moving. Any threat is restored versus enemies still in combat upon cancellation of this effect.", ua = "Активуйте, щоб прослизнути в тіні, зменшивши шанс ворогів виявити вашу присутність. Триває, доки не скасуєте або не почнете рухатися. Уся загроза проти ворогів, які досі в бою, відновлюється після скасування цього ефекту." },
    { en = "Activates your true form, increasing current movement speed by an additional $s1% for $d.", ua = "Активує вашу справжню форму, збільшуючи поточну швидкість пересування додатково на $s1% протягом $d." },
    { en = "Increases the damage done by your demons by ${$s1}.1%.", ua = "Збільшує шкоду, яку завдають ваші демони, на ${$s1}.1%." },
    { en = "Let loose a wild roar, increasing the movement speed of all friendly players within $A1 yards by $s1% for $d.", ua = "Видаєте дикий рев, збільшуючи швидкість пересування всіх дружніх гравців у радіусі $A1 ярдів на $s1% протягом $d." },
    { en = "Cannot benefit from Time Warp or other similar effects.", ua = "Не може отримати вигоду від Викривлення Часу чи інших подібних ефектів." },
    { en = "Drop to all fours to run as fast as a wild animal.", ua = "Стаєте на чотири лапи, щоб бігти так само швидко, як дикий звір." },
    { en = "You champion the causes of your guild.  All guild reputation gains are increased by $s1%.", ua = "Ви відстоюєте справу своєї гільдії. Весь приріст репутації гільдії збільшується на $s1%." },
    { en = "Leap forward $s2 yards.", ua = "Стрибок уперед на $s2 ярдів." },
    { en = "Swipe all nearby enemies, inflicting $s3 Physical damage. Deals reduced damage beyond $s4 targets.$?a231063[ Deals $231063s1% increased damage against bleeding targets.][]$?a405300[ Applies the Bleed from Thrash.][]\n\n\n\n|cFFFFFFFFAwards $s1 combo $lpoint:points;.|r", ua = "Замашний удар по всіх ворогах поблизу, що завдає $s3 фізичної шкоди. Завдає зменшеної шкоди понад $s4 цілей.$?a231063[ Завдає на $231063s1% більше шкоди цілям, що кровоточать.][]$?a405300[ Накладає кровотечу від Шматування.][]\n\n\n\n|cFFFFFFFFНадає $s1 $lочко:очка;комбо.|r" },
    { en = "Head-shrinking is for amateurs. Shrink your whole body!", ua = "Зменшувати голови — це для аматорів. Зменши все своє тіло!" },
    { en = "Increases your maximum health and healing received by ${$s1}.1%.\n\n\n\nAlso increases your attack power by ${$159195s1}.1%.", ua = "Збільшує ваше максимальне здоров'я та отримане зцілення на ${$s1}.1%.\n\n\n\nТакож збільшує вашу силу атаки на ${$159195s1}.1%." },
    { en = "Summon a rare goods vendor.", ua = "Прикликає торговця рідкісними товарами." },
    { en = "Don a pair of fiery wings, showing off your mastery of the Firebird's Challenge!", ua = "Вдягніть пару вогняних крил, демонструючи свою майстерність у Виклику Вогняного Птаха!" },
    { en = "Clutch the braid tightly and Gamon will be with you.", ua = "Міцно стисніть косу, і Гамон буде з вами." },
    { en = "Darkens the world around you.", ua = "Затьмарює світ навколо вас." },
    { en = "Entangling Roots is now an instant cast spell with a ${$s2/1000} second cooldown but with a $m5 yard range. It can also be cast while in shapeshift forms.", ua = "Заплутувальне коріння тепер твориться миттєво з перезарядженням ${$s2/1000} сек., але з дальністю $m5 ярдів. Його також можна творити у формах перевтілення." },
    { en = "Equip the Black Ice to show off your adventuring.", ua = "Спорядіть Чорну Кригу, щоб похизуватися своїми пригодами." },
    { en = "Creatures become empowered in the dungeon, increasing their health by 10% and their damage by 10%. This effect increases with Keystone level.", ua = "Істоти в підземеллі стають підсиленими: їхнє здоров'я зростає на 10%, а шкода — на 10%. Цей ефект посилюється з рівнем ключа." },
    { en = "Summons an Inquisitor's Eye and binds your vision to it.  The eye is stealthed and moves quickly but is very fragile.", ua = "Прикликає Око Інквізитора й прив'язує до нього ваш зір.  Око невидиме й рухається швидко, але дуже крихке." },
    { en = "Summon a fel lord to guard the location for $d. Any enemy that comes within $213688A1 yards will suffer $<FelCleave> Physical damage, and players struck will be stunned for $213688d.", ua = "Прикликає скверноповелителя, щоб охороняти місцину протягом $d. Будь-який ворог, що наблизиться на $213688A1 ярдів, зазнає $<FelCleave> фізичної шкоди, а вражені гравці будуть приголомшені на $213688d." },
    { en = "Completing World Quests will grant additional reputation gains with the related factions.", ua = "Виконання світових завдань дає додаткову репутацію з відповідними фракціями." },
    { en = "Infused by the void leaking out of the Twisting Nether, increasing damage done by $s1%.", ua = "Просочений Порожнечею, що витікає з Викривленого Нижнього Світу, завдяки чому завдавана шкода зростає на $s1%." },
    { en = "Proclaim your fashion sense to the world.", ua = "Заяви всьому світу про своє чуття стилю." },
    { en = "Tear a rift in space. Reactivate this ability to teleport through the rift.\n\n\n\n$?a1232189[Within Voidstorm, Spatial Rift's cooldown is reduced by 120 seconds.][]", ua = "Розриває розлом у просторі. Активуй цю здібність повторно, щоб телепортуватися крізь розлом.\n\n\n\n$?a1232189[У Войдштормі перезарядження Просторового розлому скорочується на 120 секунд.][]" },
    { en = "Bring forth your own little sea slug friend.", ua = "Викликає вашого власного маленького друга — морського слимака." },
    { en = "You and your pet gain $s1% Leech.", ua = "Ви та ваш улюбленець отримуєте $s1% Висмоктування." },
    { en = "Finishing move that launches explosive Black Powder at all nearby enemies dealing Physical damage. Deals reduced damage beyond $s4 targets.$?s382511[ All nearby targets with your Find Weakness suffer an additional $382511s1% damage as Shadow.][]\n\n\n\n   1 point  : ${$m1*1} damage\n\n   2 points: ${$m1*2} damage\n\n   3 points: ${$m1*3} damage\n\n   4 points: ${$m1*4} damage\n\n   5 points: ${$m1*5} damage$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$m1*6} damage][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$m1*7} damage][]", ua = "Добивальний прийом, що метає вибуховий Чорний Порох у всіх ворогів поблизу, завдаючи фізичної шкоди. Завдає зменшеної шкоди понад $s4 цілей.$?s382511[ Усі цілі поблизу з вашим ефектом «Пошук Слабкості» зазнають додатково $382511s1% шкоди як тіньової.][]\n\n\n\n   1 очко  : ${$m1*1} шкоди\n\n   2 очки: ${$m1*2} шкоди\n\n   3 очки: ${$m1*3} шкоди\n\n   4 очки: ${$m1*4} шкоди\n\n   5 очок: ${$m1*5} шкоди$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$m1*6} шкоди][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$m1*7} шкоди][]" },
    { en = "Disguise yourself as an acolyte of the House of Rituals. Cooldown reduced if applied while in Maldraxxus.\n\n\n\nCan only be used by those pledged to the Necrolords.", ua = "Перевдягніться послушником Дому Ритуалів. Перезарядження зменшено, якщо застосовано в Малдраксусі.\n\n\n\nМожуть використовувати лише ті, хто присягнув Некролордам." },
    { en = "Allows you to detect and mark treasures through physical barriers in the Dragon Isles outdoor world. Lasts $d.", ua = "Дозволяє виявляти й позначати скарби крізь фізичні перешкоди у відкритому світі Драконових Островів. Триває $d." },
    { en = "Opens nearly any locked chest in the Dragon Isles outdoor world.", ua = "Відмикає майже будь-яку замкнену скриню у відкритому світі Драконових Островів." },
    { en = "Teleport to the entrance to Uldaman: Legacy of Tyr.", ua = "Телепортує до входу в Улдаман: Спадок Тіра." },
    { en = "Teleport to the entrance to Ruby Life Pools.", ua = "Телепортує до входу в Рубінові Озера Життя." },
    { en = "Teleport to the entrance to The Nokhud Offensive.", ua = "Телепортує до входу в Наступ Нохудів." },
    { en = "Teleport to the entrance to Brackenhide Hollow.", ua = "Телепортує до входу в Папоротеву Балку." },
    { en = "Teleport to the entrance to The Azure Vault.", ua = "Телепортує до входу в Лазурове Сховище." },
    { en = "Teleport to the entrance to Halls of Infusion.", ua = "Телепортує до входу в Зали Вливання." },
    { en = "Increases Agility, Intellect and Strength by $s1 for $d.  Augment Rune.", ua = "Підвищує Спритність, Інтелект і Силу на $s1 на $d.  Руна підсилення." },
    { en = "While active, you automatically assume your human form when you leave combat.\n\n\n\nActivate to disable this effect.", ua = "Поки ефект активний, ти автоматично набуваєш людської подоби, щойно виходиш із бою.\n\n\n\nАктивуй, щоб вимкнути цей ефект." },
    { en = "Teleport to the entrance to The Vortex Pinnacle.", ua = "Телепортує до входу у Вершину Вихору." },
    { en = "Teleport to the entrance to Throne of the Tides.", ua = "Телепортує до входу в Престол Припливів." },
    { en = "Teleport to the entrance to Dawn of the Infinite.", ua = "Телепортує до входу в Світанок Нескінченного." },
    { en = "Teleport to the entrance to The Dawnbreaker.", ua = "Телепортує до входу в Світанкоруб." },
    { en = "Teleport to the entrance to Darkflame Cleft.", ua = "Телепортує до входу в Розщелину Темнополум'я." },
    { en = "Teleport to the entrance to The Rookery.", ua = "Телепортує до входу в Гніздище." },
    { en = "Ignite a torch.", ua = "Запалити смолоскип." },
    { en = "Gain magical damage reduction equal to $471492s1% of your damage reduction from Armor.", ua = "Дає зменшення магічної шкоди, що дорівнює $471492s1% вашого зменшення шкоди від Броні." },
    { en = "Increases Mastery by $s1 for $d.", ua = "Підвищує Майстерність на $s1 на $d." },
    { en = "Teleport to the entrance of the Liberation of Undermine.", ua = "Телепортує до входу у Визволення Андермайну." },
    { en = "Restores $s1% of your maximum health and mana every second over $d. Must remain seated while eating.", ua = "Відновлює $s1% вашого максимального здоров'я та мани щосекунди протягом $d. Під час їжі потрібно залишатися сидіти." },
    { en = "Increases Critical Strike and Versatility by $s1 for $d.", ua = "Підвищує Критичний удар і Універсальність на $s1 на $d." },
    { en = "$@spellicon457049 $@spellname457049|nIf you spend at least 10 seconds eating, you will become $@spellname457049  gaining $1219179s7 Stamina and$1219179s2 primary stat for$d.", ua = "$@spellicon457049 $@spellname457049|nЯкщо ви їстимете щонайменше 10 секунд, ви станете «$@spellname457049», отримавши $1219179s7 Витривалості та$1219179s2 до основної характеристики на$d." },
    { en = "Increases your Versatility by $s1 for $d.\n\n\n\n$@spelldesc431970", ua = "Підвищує вашу Універсальність на $s1 на $d.\n\n\n\n$@spelldesc431970" },
    { en = "Increases your Mastery by $s1 for $d.\n\n\n\n$@spelldesc431970", ua = "Підвищує вашу Майстерність на $s1 на $d.\n\n\n\n$@spelldesc431970" },
    { en = "Increases your Haste by $s1 for $d.\n\n\n\n$@spelldesc431970", ua = "Підвищує ваш Поспіх на $s1 на $d.\n\n\n\n$@spelldesc431970" },
    { en = "Increases your Critical Strike by $s1 for $d.\n\n\n\n$@spelldesc431970", ua = "Підвищує ваш Критичний удар на $s1 на $d.\n\n\n\n$@spelldesc431970" },
    { en = "Unleash a whirlwind attack dealing heavy damage to enemies within 8 yards.", ua = "Здіймає вихрову атаку, завдаючи важкої шкоди ворогам у межах 8 м." },
    { en = "You eat the fish, increasing your Versatility by $s1.", ua = "Ви з'їдаєте рибу, підвищуючи свою Універсальність на $s1." },
    { en = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Halazzi, Loa of the Hunt\n$@spellicon1253441 Oe, Loa of Growth|r\n\nThrough the loas of the Hunt and Forests, you gain a 5% chance for your attack to deal 500% damage.\n\nOnly active while in Zul'Aman.", ua = "|cnGREEN_FONT_COLOR:$@spellicon1246931 Галаззі, лоа Полювання\n$@spellicon1253441 Ое, лоа Зросту|r\n\nЗавдяки лоа Полювання й Лісів ваша атака має 5% шансу завдати 500% шкоди.\n\nДіє лише в Зул'Амані." },
    { en = "Pouring Death Rite Mixture into the fire.", ua = "Виливає Суміш Поховального Обряду у вогонь." },
    { en = "Teleport to the entrance of Windrunner Spire.", ua = "Телепортує до входу в Шпиль Віндраннерів." },
    { en = "Teleport to the entrance of Pit of Saron.", ua = "Телепортує до входу в Яму Сарона." },
    { en = "Teleport to the entrance of Maisara Caverns.", ua = "Телепортує до входу в Печери Майсари." },
    { en = "Teleport to the entrance of Magisters' Terrace.", ua = "Телепортує до входу на Терасу магістрів." },
    { en = "Sets a player ablaze in $@spellname1255187 inflicting $s1 Holy damage and an additional $s2 Holy damage every $t2 sec for $d.", ua = "Охоплює гравця полум'ям $@spellname1255187, завдаючи $s1 шкоди Світлом та додатково $s2 шкоди Світлом кожні $t2 с протягом $d." },
    { en = "Summon a replica of the Exodar to travel alongside you.", ua = "Прикликає копію Екзодара, що мандрує поруч із вами." },
    { en = "The caster causes a player to absorb $s2 healing and suffer $s1 Shadow damage every $t1 sec for $d.", ua = "Творець змушує гравця поглинути $s2 зцілення та зазнавати $s1 шкоди Тінню кожні $t1 с протягом $d." },
    { en = "The caster screeches, releasing a pulse of Sonic energy that inflicts $1259183s1 Physical damage to any players struck.", ua = "Той, хто творить закляття, верещить, вивільняючи імпульс звукової енергії, що завдає $1259183s1 фізичної шкоди всім ураженим гравцям." },
    { en = "Increases $pri by $s1 for $d.  Augment Rune.", ua = "Підвищує $pri на $s1 на $d.  Руна підсилення." },
    { en = "The Arcway channels huge amounts of arcane energy throughout Suramar. Try not to get zapped!", ua = "Аркова Путь проводить величезні обсяги арканної енергії крізь весь Сурамар. Намагайся, щоб тебе не вдарило струмом!" },
    { en = "Have a serving of Vilebranch stew, increasing your Leech by $s1% and reducing the damage taken from area of effect attacks by $s2% for $d.", ua = "З'їж порцію юшки Лихогіллів, що підвищує твоє Висмоктування на $s1% і знижує шкоду від атак по площі на $s2% упродовж $d." },
    { en = "The Shul'ka lend you further assistance in destroying Chimaerus, increasing your damage and healing done by $s1%. This effect is further increased over time.", ua = "Шул'ка надають тобі додаткову допомогу в знищенні Хімеруса, підвищуючи завдану тобою шкоду та зцілення на $s1%. Згодом цей ефект ще більше посилюється." },
    { en = "Restores $s1% of your maximum mana every second over $d. Must remain seated while drinking.", ua = "Відновлює $s1% вашої максимальної мани щосекунди протягом $d. Під час пиття треба лишатися сидячи." },
    { en = "Disorients anyone exposed to the blinding light of the Luxmaster 5000.", ua = "Дезорієнтує кожного, хто потрапляє під сліпуче світло Люксмайстра 5000." },
    { en = "In Delves, until you complete your next one, all of your stats are increased by $s1%.", ua = "У Глибинах, доки ви не пройдете наступну, усі ваші характеристики підвищено на $s1%." },
    { en = "|CFF88aaffCore Rune|R\n\n\n\nEvery $t1 sec you attract a Void-Touched Orb, up to $1287425u.\n\n\n\nDamaging an enemy sends all of the Orbs at them, dealing $<voidDmg> Cosmic damage per Orb.\n\n\n\nYour healing spells send all of the Orbs to the most injured nearby ally, healing them for $<voidHealing> per Orb.", ua = "|CFF88aaffОсновна руна|R\n\n\n\nКожні $t1 сек ви притягуєте Сферу, торкнуту Порожнечею, до $1287425u.\n\n\n\nЗавдаючи шкоди ворогові, ви спрямовуєте на нього всі Сфери, завдаючи $<voidDmg> космічної шкоди за кожну Сферу.\n\n\n\nВаші зцілювальні закляття спрямовують усі Сфери до найтяжче пораненого союзника поруч, зцілюючи його на $<voidHealing> за кожну Сферу." },
    { en = "|CFF88aaffCore Rune|R\n\n\n\nYour spells and abilities have a very high chance to unleash the power of flame, dealing $<fireDmg> Fire damage to an enemy or restoring $<fireHealing> health to the most injured nearby ally.", ua = "|CFF88aaffОсновна руна|R\n\n\n\nВаші закляття та здібності мають дуже високий шанс розв'язати силу полум'я, завдаючи $<fireDmg> вогняної шкоди ворогові або відновлюючи $<fireHealing> здоров'я найтяжче пораненому союзникові поруч." },
    { en = "A collar of devotion, worn by the Devouring Host's cherished terror.", ua = "Нашийник відданості, що його носить улюблений жах Воїнства Пожирачів." },
    { en = "Stamina and Primary stats increased.", ua = "Витривалість і основні характеристики підвищено." },
    { en = "Pull yourself to a nearby mushroom.\n\n\n\n$@spelldesc1286950", ua = "Притягуєтесь до сусіднього гриба.\n\n\n\n$@spelldesc1286950" },
    { en = "Cloaks the target with an invisible cloaking spell.", ua = "Огортає ціль закляттям невидимості." },
    { en = "Arm yourself with a Spellbreaker's Ward-Lance.", ua = "Озброюєтесь Захисним Списом Руйнівника Чар." },
    { en = "Inflicts periodic Nature damage.", ua = "Завдає періодичної шкоди Природою." },
    { en = "Cancel Spore Buoy. Gain Spore Dive.", ua = "Скасовує Спорову Плавучість. Надає Спорове Пірнання." },
    { en = "Additional elite creatures inhabit the world.", ua = "У світі з'являються додаткові елітні істоти." },
    { en = "The Hal'hadar's elite squad of ethereal mercenaries, the Warp Riders, patrol the wilds of Naigtal looking for hostile invaders to ambush with deadly intent.", ua = "Вершники Викривлення, елітний загін ефірних найманців Гал'гадара, патрулюють нетрі Найґталу, вишукуючи ворожих загарбників, щоб улаштувати смертельну засідку." },
    { en = "Can see Aerospores.", ua = "Дозволяє бачити аероспори." },
    { en = "Remove $s1 beneficial effect from all enemies within $A1 yards and restore $s2% of your Mana.", ua = "Знімає $s1 корисний ефект з усіх ворогів у радіусі $A1 м і відновлює $s2% вашої мани." },
    { en = "The Lightspawn blesses you, granting you a $s1% speed boost for $d.", ua = "Поріддя Світла благословляє тебе, даруючи приріст швидкості на $s1% протягом $d." },
    { en = "Increases all Experience by $w1% up to level $w3.", ua = "Збільшує весь Досвід на $w1% до рівня $w3." },
    { en = "$?PC127588[Dying subtracts from the lives remaining counter which influences rewards at the end of this delve.][You have died too many times, reducing the rewards at the end of this delve.]", ua = "$?PC127588[Смерть зменшує лічильник залишку життів, що впливає на нагороди наприкінці цієї Глибини.][Ви загинули забагато разів, зменшивши нагороди наприкінці цієї Глибини.]" },
    { en = "This delve has an abundance of treasures and will remain bountiful while inside.\n\n\n\nUse a Restored Coffer Key to open a Bountiful Coffer at the end of this delve to receive powerful equipment and greater rewards$?WE43094[, provided you have lives remaining.][.]", ua = "Ця Глибина має достаток скарбів і лишатиметься щедрою, доки ви всередині.\n\n\n\nВикористайте Відновлений Ключ від Скрині, щоб наприкінці цієї Глибини відкрити Щедру Скриню й отримати потужне спорядження та більші нагороди$?WE43094[, за умови, що у вас лишаються життя.][.]" },
    { en = "A Hungering Presence hunts for isolated potential victims. Flying too high up or too far out from Voidstorm will attract its ravenous attention.\n\n\n\nAnything it catches up to dies instantly.", ua = "Зголодніла Присутність полює на самотніх потенційних жертв. Якщо злетіти надто високо чи відлетіти надто далеко від Войдшторму, це приверне її ненажерливу увагу.\n\n\n\nУсе, що вона наздожене, гине миттєво." },
    { en = "Remove the Curse of Transformation from nearby frogs.", ua = "Знімає Прокляття Перетворення з жаб поблизу." },
    { en = "$@spelldesc1260973\n\n\n\nEnemies have a tremendous amount of health and deal a tremendous amount of damage. Additional traps and challenges will appear.", ua = "$@spelldesc1260973\n\n\n\nВороги мають величезний запас здоров'я і завдають величезної шкоди. З'являться додаткові пастки та випробування." },
    { en = "Completing this quest can reward you with a weekly Spark of Radiance. These sparks are usable by professions to create powerful weapons and armor.\n\n\n\nIf you fall behind on these weekly sparks, completing other max-level content such as Delves, Mythic Plus, Raids, Instanced PvP, and some outdoor events may help you catch up.\n\n\n\n$?pc140685[|cnRED_FONT_COLOR:You have already received your Spark of Radiance this week.|r][|cnGREEN_FONT_COLOR:You have not received your Spark of Radiance this week.|r]", ua = "За виконання цього завдання ти можеш щотижня отримати Іскру Сяйва. Ці іскри придатні для професій, щоб створювати потужну зброю та обладунки.\n\n\n\nЯкщо ти відстаєш у цих щотижневих іскрах, надолужити можна, проходячи інший контент максимального рівня: Глибини, міфічні+ підземелля, рейди, інстансований PvP та деякі події у відкритому світі.\n\n\n\n$?pc140685[|cnRED_FONT_COLOR:Цього тижня ти вже отримав свою Іскру Сяйва.|r][|cnGREEN_FONT_COLOR:Цього тижня ти ще не отримав своєї Іскри Сяйва.|r]" },
    { en = "Throw at a Slavering Ultradon to turn other creatures against it.", ua = "Кинь у слинявого ультрадона, щоб налаштувати проти нього інших істот." },
    { en = "Alleria unleashes barrages of void-infused arrows and destroys all $@spellname1265419.", ua = "Аллерія випускає шквали просочених Порожнечею стріл і знищує всі $@spellname1265419." },
    { en = "Zah'ran will appear at the end of this delve with a random assortment of wears for purchase.", ua = "Зах'ран з'явиться наприкінці цієї глибини з випадковим набором товарів на продаж." },
    { en = "In Delves, until you complete your next one, gain $s2% of your maximum health as an absorb shield for $1267063d whenever your health falls below $s1% during combat. Can only occur every $1268672d.", ua = "У Глибинах, доки ти не пройдеш наступну, отримуєш $s2% свого максимального здоров'я як щит-поглинач на $1267063d щоразу, коли твоє здоров'я падає нижче $s1% під час бою. Може траплятися лише раз на $1268672d." },
    { en = "Completing the \"In Search of Darkness\" and \"Rage of the Ren'dorei\" quest lines will unlock the ability to create a Void Elf Demon Hunter.", ua = "Проходження ліній завдань «У пошуках темряви» та «Лють рен'дорей» відкриє можливість створити мисливця на демонів з ельфів Порожнечі." },
    { en = "Troll ritual items provide an useful buff in combat.", ua = "Тролські ритуальні предмети дають корисне підсилення в бою." },
    { en = "Grasping Tendrils have been found rooting and damaging distracted adventurers.\n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$?q95547[][|CFFffd200Unlock: |R|CFFffffffFound in the Ritual Spoils.|R]", ua = "Виявлено чіпкі мацаки, що обплутують і ранять неуважних шукачів пригод.\n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$?q95547[][|CFFffd200Розблокування: |R|CFFffffffЗнаходиться в Ритуальній Здобичі.|R]" },
    { en = "The enemies in the site are using dark obelisks to empower their forces. Disable these or face them with their malevolent boons.\n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$@spelldesc1291098", ua = "Вороги на місці використовують темні обеліски, щоб підсилити свої війська. Вимкни їх або зіткнися з ворогами, посиленими лиховісними дарами.\n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$@spelldesc1291098" },
    { en = "Disruptions at the site trigger forces to be summoned to the location of the incident. The more disruptive the incident, the greater the force summoned. \n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$@spelldesc1291112", ua = "Заворушення на місці викликають підкріплення до точки інциденту. Що серйозніший інцидент, то більше військо прибуває. \n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$@spelldesc1291112" },
    { en = "The overwhelming power of the ritual is felt throughout the site, embers of power can be found empowering nearby enemies and their leader. \n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$@spelldesc1291113", ua = "Нездоланна сила ритуалу відчувається по всьому місцю, і жарини могутності підсилюють довколишніх ворогів та їхнього ватажка. \n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$@spelldesc1291113" },
    { en = "The magic of the site occasionally manifests powerful spirits. Interrupt these manifestations or face their withering magic.\n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$@spelldesc1291110", ua = "Магія цього місця час від часу проявляє могутніх духів. Перерви ці прояви або зіткнися з їхньою згубною магією.\n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$@spelldesc1291110" },
    { en = "Powerful patrols have been seen at the site due to suspected looting. It is best to avoid them if possible. \n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$@spelldesc1291109", ua = "На місці помічено грізні патрулі через підозру в мародерстві. Краще оминати їх, якщо це можливо. \n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$@spelldesc1291109" },
    { en = "Volatile magic in the site has tainted the enemies. When killed, this taint manifests as a pool of deadly magic.\n\n\n\n|CFF20ff20Increases |CFF88aaffSpoils|R by |CFFffffff$s2%|R when selected.|R\n\n\n\n$?q95548[][|CFFffd200Unlock: |R|CFFffffffFound in a tainted bone pile.|R]", ua = "Нестабільна магія на місці осквернила ворогів. Коли їх убивають, ця скверна проявляється калюжею смертоносної магії.\n\n\n\n|CFF20ff20Збільшує |CFF88aaffЗдобич|R на |CFFffffff$s2%|R, коли вибрано.|R\n\n\n\n$?q95548[][|CFFffd200Розблокування: |R|CFFffffffЗнаходиться в осквернілій купі кісток.|R]" },
    { en = "Blasts the target with energy, dealing $30451s1 Arcane damage.\n\n\n\nEach Arcane Charge increases damage by $36032s1% and mana cost by $36032s5%, and reduces cast time by $36032s4%.\n\n\n\n|cFFFFFFFFGenerates $s2 Arcane $lCharge:Charges;.|r", ua = "Уражає ціль енергією, завдаючи $30451s1 арканної шкоди.\n\n\n\nКожен Арканний заряд збільшує шкоду на $36032s1% і вартість мани на $36032s5%, а також скорочує час прочитання на $36032s4%.\n\n\n\n|cFFFFFFFFПороджує $s2 Арканний $lзаряд:заряди;.|r" },
    { en = "Target gains a $h% chance to inflict Fire damage on any melee, ranged, or spell attack.", ua = "Ціль отримує $h% шанс завдати вогняної шкоди будь-якою атакою ближнього бою, дальнього бою чи закляттям." },
    { en = "Lets forth a furious howl, increasing damage taken by ${$158026m2*$158026I}% for ${$158026D*$158026I} sec., dividing the magnitude and duration amongst all targets within $158057A1 yards. The duration and magnitude of this effect carry over.", ua = "Видає лютий рев, збільшуючи отриману шкоду на ${$158026m2*$158026I}% протягом ${$158026D*$158026I} с, розподіляючи силу й тривалість між усіма цілями в радіусі $158057A1 ярдів. Тривалість і сила цього ефекту переносяться при повторному застосуванні." },
    { en = "Unlock Renown levels for the Dragonscale Expedition faction.", ua = "Відкриває рівні слави для фракції «Експедиція Драконячої Луски»." },
    { en = "Becoming an Angler is easy!\n\n\n\nCast your line and reel in the many secrets Midnight has to offer.\n\n\n\nCaught Fish will appear here in your trusty Fishing Journal. The records here will detail these fanciful fish and give indication on where you might find them again!", ua = "Стати рибалкою легко!\n\n\n\nЗакидай вудку й виловлюй численні таємниці, що їх береже Опівніч.\n\n\n\nСпіймана риба з'являтиметься тут, у твоєму вірному Журналі рибалки. Записи розкажуть про цих дивовижних рибин і підкажуть, де їх можна знайти знову!" },
    { en = "Deals $1s Shadow Damage every $1p sec.\n\nSlow $2s% for $d sec.", ua = "Завдає $1s шкоди Тінню щосекунди ($1p с).\n\nСповільнює на $2s% на $d с." },
    { en = "A powerful curse effects this creature.", ua = "Цю істоту вразило могутнє прокляття." },
    { en = "Displacement Portals can be used to duplicate yourself increasing speed and combat strength.", ua = "Портали зміщення можна використати, щоб створити свою копію, підвищивши швидкість і бойову міць." },
    { en = "Allows a Blacksmith to make basic weapons and armor. Requires stone and metal found with the Mining skill.", ua = "Дозволяє ковалю виготовляти базову зброю та броню. Потребує каменю й металу, які видобувають навичкою гірничої справи." },
    { en = "Turn into your currently inactive form.", ua = "Перетворитися на вашу зараз неактивну форму." },
    { en = "Allows an archaeologist to find artifact fragments and complete artifacts up to a maximum potential skill of 75.", ua = "Дозволяє археологу знаходити фрагменти артефактів і відновлювати артефакти до максимального потенційного рівня навички 75." },
    { en = "Increases Experience gained from killing monsters.", ua = "Підвищує досвід, отриманий за вбивство монстрів." },
    { en = "Summons and dismisses a favorite mount that is usable in the current area. If you don't have any favorite mounts, it'll choose from your whole collection.", ua = "Прикликає та відпускає улюблену їздову тварину, придатну для поточної місцевості. Якщо у вас немає обраних їздових тварин, вибере одну з усієї колекції." },
    { en = "Honor gains from Battleground objectives and wins increased by $s1%.", ua = "Честь, отримана за цілі та перемоги на полях бою, підвищена на $s1%." },
    { en = "Summon glacial spikes from the ground that advance forward, each dealing ${$195975s1*$<CAP>/$AP} Frost damage near their eruption point and applying Razorice.", ua = "Прикликає з-під землі крижані шпичаки, що рухаються вперед, і кожен завдає ${$195975s1*$<CAP>/$AP} шкоди від льоду поблизу місця виверження та накладає «Гострий лід»." },
    { en = "Drain the warmth of life from all nearby enemies within $196771A1 yards, dealing ${9*$196771s1*$<CAP>/$AP} Frost damage over $d and reducing their movement speed by $211793s1%.", ua = "Витягує життєве тепло з усіх ворогів поблизу в радіусі $196771A1 яр., завдаючи ${9*$196771s1*$<CAP>/$AP} шкоди від льоду протягом $d і знижуючи їхню швидкість пересування на $211793s1%." },
    { en = "Unlocks access to World Quests in the Broken Isles.", ua = "Відкриває доступ до світових завдань на Зламаних Островах." },
    { en = "Summons and dismisses a favorite battle pet. If you don't have any favorite pets, it'll choose from your whole collection.", ua = "Прикликає та відпускає улюбленого бойового улюбленця. Якщо у вас немає обраних улюбленців, вибере одного з усієї колекції." },
    { en = "The spirit of cooperation binds a fallen delver and their avenger together, granting both $s1% increased movement speed and reducing damage they take by $s2%.", ua = "Дух співпраці поєднує полеглого дослідника глибин та його месника, підвищуючи їм обом швидкість пересування на $s1% і зменшуючи отриману ними шкоду на $s2%." },
    { en = "Waters in Harandar contain unique minerals that, when passing through the gills of a Restored Songfish, emit an ethereal underwater melody. This song, while pleasant to an Angler, wards off predators with its subtle vibration. If a predator, such as the Twisted Tetra, gets too close, the vibrations grow more volatile.\n\n\n\n|cnGREEN_FONT_COLOR:Special: |R\n\n\n\n$@spellicon1237104 Cooking Feasts\n\n\n\nThis especially rare and tasty fish is an important ingredient in many Midnight Cooking recipes.\n\n\n\n|cnGREEN_FONT_COLOR:Areas you can find this fish:|R\n\n- Eversong Woods\n\n- Harandar\n\n\n\n|cnGREEN_FONT_COLOR:Fishing Pools:|r\n\n- Bloom Swarm\n\n- Bubbling Bloom\n\n- Sunwell Swarm\n\n- Blossoming Torrent", ua = "Води Гарандару містять унікальні мінерали, які, проходячи крізь зябра відновленої співочої риби, породжують неземну підводну мелодію. Ця пісня, приємна для рибалки, відлякує хижаків своєю ледь вловимою вібрацією. Якщо хижак, як-от викривлена тетра, підпливе надто близько, вібрації стають дедалі нестабільнішими.\n\n\n\n|cnGREEN_FONT_COLOR:Особливе: |R\n\n\n\n$@spellicon1237104 Приготування бенкетів\n\n\n\nЦя надзвичайно рідкісна й смачна риба — важливий інгредієнт багатьох кулінарних рецептів Опівночі.\n\n\n\n|cnGREEN_FONT_COLOR:Де можна знайти цю рибу:|R\n\n- Ліс Вічної Пісні\n\n- Гарандар\n\n\n\n|cnGREEN_FONT_COLOR:Косяки риби:|r\n\n- Квітковий рій\n\n- Булькотливий цвіт\n\n- Рій Сонячного Колодязя\n\n- Квітучий потік" },
    { en = "Shrunken! You are smaller but movement speed is increased by $s1%.", ua = "Зменшено! Ви стали меншими, але швидкість пересування підвищено на $s1%." },
    { en = "Take a picture with your arcane S.E.L.F.I.E camera, dealing massive damage to anyone nearby in the picture.", ua = "Зробіть знімок арканною камерою S.E.L.F.I.E, завдаючи величезної шкоди всім, хто поблизу потрапив у кадр." },
    { en = "Exit S.E.L.F.I.E. Camera mode.", ua = "Вийти з режиму камери S.E.L.F.I.E." },
    { en = "Knocks back the current enemy target, dealing $s3 Arcane damage. Knockback is more effective against players.", ua = "Відкидає поточну ворожу ціль, завдаючи $s3 арканної шкоди. Відкидання дієвіше проти гравців." },
    { en = "Spits a glob of acid at the target, inflicting Nature damage and additional Nature damage every $t2 sec for $d.", ua = "Плює згустком кислоти в ціль, завдаючи шкоди від сил природи, а також додаткової шкоди від сил природи щосекунди — кожні $t2 сек. протягом $d." },
    { en = "Swipes at the target with its claws, inflicting $s1 Physical damage.", ua = "Б'є ціль пазурами, завдаючи $s1 фізичної шкоди." },
    { en = "Let out a shriek, causing $i enemies within $A1 yds to flee in fear for $d. Damage may cancel the effect.", ua = "Здіймає пронизливий вереск, що змушує $i ворогів у радіусі $A1 яр. тікати в жаху на $d. Шкода може скасувати ефект." },
    { en = "Toss a Void Missile at Elementals to disrupt their energy.", ua = "Кинути Снаряд Порожнечі в елементалів, щоб порушити їхню енергію." },
    { en = "Command Fidoficus to exercise its dominance over others.", ua = "Наказує Фідофікусу утвердити свою зверхність над іншими." },
    { en = "Increases Valeera and all allies' primary stat by $s1% for $d.", ua = "Підвищує основну характеристику Валіри та всіх союзників на $s1% на $d." },
    { en = "Valeera harnesses effective healing upon her to empower her blades, increasing the damage she inflicts by $s1% for $d. This effect stacks.", ua = "Валіра обертає дієве зцілення на силу своїх клинків, підвищуючи завдану нею шкоду на $s1% на $d. Ефект накопичується." },
    { en = "Valeera conceals herself in shadow, making her undetectable by most enemies.", ua = "Валіра ховається в тіні, стаючи невидимою для більшості ворогів." },
    { en = "At any time, decipher the map and guarantee that you'll find a Hidden Trove at the end of the next Tier 4+ Delve you complete.\n\n\n\nHidden Trove's contents depend on the completed Delve Tier.", ua = "Будь-коли розшифруйте карту й гарантовано знайдіть Прихований Скарб наприкінці наступної Глибини Складності 4+, яку пройдете.\n\n\n\nВміст Прихованого Скарбу залежить від Складності пройденої Глибини." },
    { en = "Damage taken reduced by $s1%, while in the Maw and Korthia.", ua = "Отримувана шкода зменшена на $s1%, поки ви в Пащі та Кортії." },
    { en = "Drink the potion to perceive the enemies in a less threatening shape. Damage done increased by $s2%.", ua = "Випий зілля, щоб бачити ворогів у менш загрозливому вигляді. Завдана шкода збільшена на $s2%." },
    { en = "After $1215531s3 sec of combat, party members and Brann deal $1215551s1% more damage and healing for $1215551d. Can only occur once per combat.", ua = "Після $1215531s3 сек бою члени групи та Бранн завдають на $1215551s1% більше шкоди та зцілення протягом $1215551d. Може ставатися лише раз за бій." },
    { en = "Exit Harrower Form.", ua = "Вийти з форми Мучителя." },
    { en = "Swing the hammer around yourself, inflicting massive damage in an area around you, stunning and knocking back enemies.", ua = "Розмахніться молотом навколо себе, завдаючи величезної шкоди по площі довкола вас, приголомшуючи та відкидаючи ворогів." },
    { en = "Use the Eye of Revelation to expose the infiltrators hiding within the university.", ua = "Скористайтеся Оком Одкровення, щоб викрити шпигунів, які ховаються в університеті." },
    { en = "Maximum Health increased by $w1%.\n\n$pri increased by $w2%.\n\nHaste increased by $w3%.\n\nCritical Strike increased by $w4%.\n\nMastery increased by $w5%.\n\nVersatility increased by $w6%.\n\nMovement Speed increased by $w7%.\n\nReduce incoming damage by $w8%.\n\n\n\n$?a1279750[Maximum Health: $1279750w1%.][]\n\n$?a1279752[Movement Speed: $1279752w1%.][]\n\n$?a1279753[$pri: $1279753w1%.][]\n\n$?a1266966[Haste: $1266966w1%.][]\n\n$?a1266965[Critical Strike: $1266965w1%.][]\n\n$?a1266967[Mastery: $1266967w1%.][]\n\n$?a1266969[Versatility: $1266969w1%.][]\n\n$?a1279751[Damage Reduction: $1279751w1%.][]", ua = "Максимальне здоров'я збільшено на $w1%.\n\n$pri збільшено на $w2%.\n\nПоспіх збільшено на $w3%.\n\nКритичний удар збільшено на $w4%.\n\nМайстерність збільшено на $w5%.\n\nУніверсальність збільшено на $w6%.\n\nШвидкість руху збільшено на $w7%.\n\nВхідну шкоду зменшено на $w8%.\n\n\n\n$?a1279750[Максимальне здоров'я: $1279750w1%.][]\n\n$?a1279752[Швидкість руху: $1279752w1%.][]\n\n$?a1279753[$pri: $1279753w1%.][]\n\n$?a1266966[Поспіх: $1266966w1%.][]\n\n$?a1266965[Критичний удар: $1266965w1%.][]\n\n$?a1266967[Майстерність: $1266967w1%.][]\n\n$?a1266969[Універсальність: $1266969w1%.][]\n\n$?a1279751[Зменшення шкоди: $1279751w1%.][]" },
    { en = "Unleash the Alnmoths to deal damage to nearby enemies and consume nearby patches of Lightbloom growths.", ua = "Випускає альнмотів, щоб завдати шкоди ворогам поблизу та поглинути ділянки заростей Світлоцвіту неподалік." },
    { en = "Grants the ability to acquire and use Ascendant Voidcores to increase the item level of worthy weapons and trinkets in Midnight Season 1 at the Voidforge.", ua = "Дає змогу здобувати й використовувати піднесені ядра Порожнечі, щоб підвищувати рівень предметів гідної зброї та дрібничок у 1-му сезоні Опівночі в Кузні Порожнечі." },
    { en = "Decimus transmutes your catalyzed Hungering Oblivium to forge the Nilhammer.\n\n\n\nYou have contributed $@currency3419 of $s1  Hungering Oblivium required.", ua = "Децимус перетворює ваш каталізований Голодний Облівіум, щоб викувати Молот Небуття.\n\n\n\nВи внесли $@currency3419 з $s1  потрібного Голодного Облівіуму." },
    { en = "Valeera performs evasive maneuvers, significantly reducing damage taken from area-of-effect attacks.", ua = "Валіра виконує ухильні маневри, значно зменшуючи шкоду від атак по площі." },
    { en = "Stab the target, causing ${$s2*$<mult>} Physical damage. Damage increased by $s4% when you are behind your target$?s319949[, and critical strikes apply Find Weakness for $319949s1 sec][].\n\n\n\n|cFFFFFFFFAwards $s3 combo $lpoint:points;.|r", ua = "Штрикаєте ціль, завдаючи ${$s2*$<mult>} фізичної шкоди. Шкода збільшена на $s4%, коли ви позаду цілі$?s319949[, а критичні удари накладають «Пошук слабкості» на $319949s1 сек][].\n\n\n\n|cFFFFFFFFНадає $s3 комбо-$lочко:очок;.|r" },
    { en = "Hardened by battle, your Stamina is increased by $s2% and your Armor is increased by $s1% of your Strength.", ua = "Загартований у бою, ваша Витривалість збільшена на $s2%, а Броня збільшена на $s1% від вашої Сили." },
    { en = "Throws a fiery ball that causes $s1 Fire damage.$?a157642[\n\n\n\nEach time your Fireball fails to critically strike a target, it gains a stacking $157644s1% increased critical strike chance. Effect ends when Fireball critically strikes.][]", ua = "Кидає вогняну кулю, що завдає $s1 шкоди Вогнем.$?a157642[\n\n\n\nЩоразу, коли ваш «Вогняний шар» не завдає критичного удару по цілі, він отримує накопичувальне збільшення шансу критичного удару на $157644s1%. Ефект завершується, коли «Вогняний шар» завдає критичного удару.][]" },
    { en = "Burns the enemy, causing $s1 Fire damage immediately and an additional $157736o1 Fire damage over $157736d.\n\n\n\n|cFFFFFFFFPeriodic damage generates 1 Soul Shard Fragment and has a $s2% chance to generate an additional 1 on critical strikes.|r", ua = "Спалює ворога, завдаючи $s1 шкоди Вогнем негайно та додатково $157736o1 шкоди Вогнем протягом $157736d.\n\n\n\n|cFFFFFFFFПеріодична шкода створює 1 Фрагмент Уламка Душі та має $s2% шанс створити ще 1 при критичних ударах.|r" },
    { en = "Reduces all damage you take by $s1% for $d. Usable while stunned.", ua = "Зменшує всю шкоду, яку ви отримуєте, на $s1% протягом $d. Можна застосувати під час оглушення." },
    { en = "Dispels harmful effects on the target, removing all Magic$?s390632[ and Disease][] effects.", ua = "Розвіює шкідливі ефекти на цілі, знімаючи всі ефекти Магії$?s390632[ та Хвороби][]." },
    { en = "Inflicts impending doom upon the target, dealing $s2 Shadow damage immediately and $453567s1 Shadow damage to enemies within $453567a1 yards after $d. Damage is reduced beyond $s1 targets.\n\n\n\nConsuming a Demonic Core reduces the duration of Doom by $s3 sec.", ua = "Насилає невідворотну загибель на ціль, завдаючи $s2 шкоди Тінню негайно та $453567s1 шкоди Тінню ворогам у радіусі $453567a1 ярдів через $d. Шкода зменшується понад $s1 цілей.\n\n\n\nСпоживання Демонічного Ядра зменшує тривалість Загибелі на $s3 сек." },
    { en = "Garrote the enemy, causing $o1 Bleed damage over $d.$?a196861[ Silences the target for $1330d when used from Stealth.][]\n\n\n\n|cFFFFFFFFAwards $s3 combo $lpoint:points;.|r", ua = "Душите ворога, завдаючи $o1 шкоди від кровотечі протягом $d.$?a196861[ Занімлює ціль на $1330d, якщо застосовано зі Скрадання.][]\n\n\n\n|cFFFFFFFFНадає $s3 комбо-$lочко:очок;.|r" },
    { en = "Conjures a Mana Gem that can be used to instantly restore $5405s1% mana and grant $384280s1% spell damage for $384280d. Holds up to $s2 charges.\n\n\n\n$@spellname118812\n\n$@spelldesc118812", ua = "Створює Самоцвіт мани, який можна використати, щоб миттєво відновити $5405s1% мани та надати $384280s1% шкоди заклять на $384280d. Вміщує до $s2 зарядів.\n\n\n\n$@spellname118812\n\n$@spelldesc118812" },
    { en = "Taunts all enemies within $A1 yds to attack you for $d, and increases the threat you generate against them by $s2% for $d.", ua = "Провокує всіх ворогів у радіусі $A1 ярдів атакувати вас протягом $d та збільшує загрозу, яку ви створюєте проти них, на $s2% протягом $d." },
    { en = "Attack with both weapons, dealing a total of $<dmg> Physical damage.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Атакуєте обома зброями, завдаючи загалом $<dmg> фізичної шкоди.\n\n\n\n|cFFFFFFFFНадає $s2 комбо-$lочко:очок;.|r" },
    { en = "Magical energy flows through you while in combat, building up to ${$116267m1*5}% increased damage and then diminishing down to $116267s1% increased damage, cycling every 10 sec.", ua = "Магічна енергія струменіє крізь вас у бою, наростаючи до ${$116267m1*5}% збільшеної шкоди, а потім спадаючи до $116267s1% збільшеної шкоди, повторюючи цикл кожні 10 сек." },
    { en = "Finishing move that tears open the target, dealing Bleed damage over time. Lasts longer per combo point.\n\n\n\n   1 point  : ${$o1*2/6} over 8 sec\n\n   2 points: ${$o1*3/6} over 12 sec\n\n   3 points: ${$o1*4/6} over 16 sec\n\n   4 points: ${$o1*5/6} over 20 sec\n\n   5 points: ${$o1*6/6} over 24 sec$?s193531|((s394320|s394321}s457512)&!s193531)[\n\n   6 points: ${$o1*7/6} over 28 sec][]$?s193531&(s394320|s394321|s457512)[\n\n   7 points: ${$o1*8/6} over 32 sec][]", ua = "Завершальний прийом, що роздирає ціль, завдаючи шкоди від кровотечі з часом. Триває довше за кожне комбо-очко.\n\n\n\n   1 очко  : ${$o1*2/6} протягом 8 сек\n\n   2 очки: ${$o1*3/6} протягом 12 сек\n\n   3 очки: ${$o1*4/6} протягом 16 сек\n\n   4 очки: ${$o1*5/6} протягом 20 сек\n\n   5 очок: ${$o1*6/6} протягом 24 сек$?s193531|((s394320|s394321}s457512)&!s193531)[\n\n   6 очок: ${$o1*7/6} протягом 28 сек][]$?s193531&(s394320|s394321|s457512)[\n\n   7 очок: ${$o1*8/6} протягом 32 сек][]" },
    { en = "Finishing move that dispatches the enemy, dealing damage per combo point:\n\n   1 point  : ${$m1*1} damage\n\n   2 points: ${$m1*2} damage\n\n   3 points: ${$m1*3} damage\n\n   4 points: ${$m1*4} damage\n\n   5 points: ${$m1*5} damage$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$m1*6} damage][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$m1*7} damage][]", ua = "Завершальний прийом, що добиває ворога, завдаючи шкоди за кожне комбо-очко:\n\n   1 очко  : ${$m1*1} шкоди\n\n   2 очки: ${$m1*2} шкоди\n\n   3 очки: ${$m1*3} шкоди\n\n   4 очки: ${$m1*4} шкоди\n\n   5 очок: ${$m1*5} шкоди$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$m1*6} шкоди][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$m1*7} шкоди][]" },
    { en = "Fires several missiles, hitting all nearby enemies within $A2 yds of your current target for $s2 Physical damage$?s115939[ and triggering Beast Cleave][]. Deals reduced damage beyond $s1 targets.$?s19434[\n\n\n\n|cFFFFFFFFGenerates $213363s1 Focus per target hit.|r][]", ua = "Випускає кілька снарядів, влучаючи в усіх ворогів у межах $A2 ярдів від вашої поточної цілі та завдаючи $s2 фізичної шкоди$?s115939[ і запускаючи «Звіриний розтин»][]. Завдає зменшеної шкоди понад $s1 цілей.$?s19434[\n\n\n\n|cFFFFFFFFГенерує $213363s1 Фокусу за кожну уражену ціль.|r][]" },
    { en = "Cleanses a friendly target, removing all $?s393024[Poison, Disease, and ][]Magic effects.", ua = "Очищує дружню ціль, знімаючи всі ефекти $?s393024[Отрути, Хвороби та ][]Магії." },
    { en = "Attempt to finish off a wounded foe, causing ${$280849s1+$163558s1} Physical damage. Only usable on enemies that have less than 20% health.$?s316402[\n\n\n\n|cFFFFFFFFGenerates ${$m3/10} Rage.|r][]", ua = "Спроба добити пораненого ворога, завдаючи ${$280849s1+$163558s1} фізичної шкоди. Можна застосувати лише проти ворогів, у яких менше 20% здоров'я.$?s316402[\n\n\n\n|cFFFFFFFFГенерує ${$m3/10} Люті.|r][]" },
    { en = "Changes your viewpoint to the targeted location for $d. Only usable outdoors.", ua = "Переносить ваш погляд на вказане місце протягом $d. Можна застосувати лише під відкритим небом." },
    { en = "Summons a totem at your feet for $d. Party members within $?s382201[${(1+$382201s3/100)*$s2}][$s2] yds have a $327942h% chance when they auto-attack to swing an extra time.", ua = "Прикликає до ваших ніг тотем на $d. Члени групи в межах $?s382201[${(1+$382201s3/100)*$s2}][$s2] ярд(ів), автоматично атакуючи, мають $327942h% шанс завдати додаткового удару." },
    { en = "Calm your mind, sending you into a focused trance for $d. Grants $m1% haste, increases spell damage by $s2%, and prevents damage from delaying your spellcasts.", ua = "Заспокоює ваш розум, занурюючи вас у зосереджений транс протягом $d. Надає $m1% Поспіху, збільшує шкоду заклять на $s2% та не дозволяє шкоді затримувати ваше творіння заклять." },
    { en = "Your target burns for an additional ${$s1}.1% over $12654d of the total direct damage caused by your Fireball, Fire Blast,  Pyroblast$?s153561[, Meteor][], and Flamestrike. If this effect is reapplied, any remaining damage will be added to the new Ignite.$?a1254756[\n\n\n\nFire Blast causes $s1% of your Ignite to spread to $s5 nearby $Lenemy:enemies;.][]", ua = "Ваша ціль горить, зазнаючи протягом $12654d додаткової шкоди в розмірі ${$s1}.1% від загальної прямої шкоди, завданої вашими Вогняною кулею, Вогняним вибухом, Піровибухом$?s153561[, Метеором][] і Полум'яним ударом. Якщо цей ефект накладено повторно, будь-яка залишкова шкода додається до нового Займання.$?a1254756[\n\n\n\nВогняний вибух змушує $s1% вашого Займання поширитися на $s5 сусідн(іх) $Lенемі:ворогів;.][]" },
    { en = "Increases maximum health by $s1% for $d and instantly heals you for that amount.", ua = "Збільшує максимальне здоров'я на $s1% протягом $d та миттєво зцілює вас на цю величину." },
    { en = "Strikes up to $?a272026[$331850i][${$331850i-3}] nearby targets for $331850s1 Physical damage$?a381878[ that generates 1 combo point per target][], and causes your single target attacks to also strike up to $?a272026[${$s3+$272026s3}][$s3] additional nearby enemies for $s2% of normal damage for $d.", ua = "Уражає до $?a272026[$331850i][${$331850i-3}] сусідніх цілей, завдаючи $331850s1 фізичної шкоди$?a381878[ і породжуючи 1 очко комбо на кожну ціль][], а також дозволяє вашим атакам по одній цілі протягом $d уражати ще до $?a272026[${$s3+$272026s3}][$s3] сусідніх ворогів, завдаючи $s2% звичайної шкоди." },
    { en = "Fills you with the embrace of Shadow energy for $d, causing you to heal a nearby ally for $s1% of any single-target Shadow spell damage you deal.", ua = "Огортає вас обіймами енергії Тіні протягом $d, завдяки чому ви зцілюєте союзника поблизу на $s1% від шкоди Тінню, яку ви завдаєте закляттями по одній цілі." },
    { en = "Silences the target, preventing them from casting spells for $d. Against non-players, also interrupts spellcasting and prevents any spell in that school from being cast for $263715d.", ua = "Змушує ціль замовкнути, не дозволяючи їй творити закляття протягом $d. Проти неігрових персонажів також перериває творіння заклять і не дозволяє творити жодне закляття цієї школи протягом $263715d." },
    { en = "Summons a totem at your feet for $d, granting $320763s1% increased mana regeneration to allies within $<radius> yards.", ua = "Прикликає тотем до ваших ніг протягом $d, надаючи $320763s1% збільшеного відновлення мани союзникам у радіусі $<radius> ярдів." },
    { en = "Reduces the chance enemies have to detect you while Prowl is active.", ua = "Зменшує шанс ворогів виявити вас, поки активне Скрадання." },
    { en = "Your finishing moves have a $s3% chance per combo point to make your next Regrowth or Entangling Roots instant, free, and castable in all forms.", ua = "Ваші завершальні прийоми мають $s3% шанс за кожне комбо-очко зробити ваш наступний Відрощення або Плутане Коріння миттєвим, безкоштовним і придатним для творіння в усіх подобах." },
    { en = "Blasts a target for $s1 Fire damage.", ua = "Вражає ціль, завдаючи $s1 шкоди Вогнем." },
    { en = "A direct strike, dealing $s1 Physical damage.", ua = "Прямий удар, що завдає $s1 фізичної шкоди." },
    { en = "Upon death, you become the Spirit of Redemption for $27827d. You cannot move, attack, be attacked, or be targeted by any spells or effects, and your healing spells cost no mana. When the effect ends, you die.", ua = "Після смерті ви стаєте Духом Спокути на $27827d. Ви не можете рухатися, атакувати, бути атакованими чи стати ціллю будь-яких заклять або ефектів, а ваші зцілювальні закляття не витрачають мани. Коли ефект завершується, ви помираєте." },
    { en = "Increases your threat generation while active, making you a more effective tank.", ua = "Поки активне, збільшує вашу генерацію загрози, роблячи вас ефективнішим танком." },
    { en = "Draws fire toward the enemy, dealing $s2 Fire damage.\n\n\n\n|cFFFFFFFFGenerates $?a387173[${$244670s1*(1+($387173s1/100))} Soul Shard Fragments and an additional ${1*(1+($387173s1/100))} on critical strikes.][$244670s1 Soul Shard Fragments and an additional 1 on critical strikes.]|r", ua = "Скеровує вогонь на ворога, завдаючи $s2 вогняної шкоди.\n\n\n\n|cFFFFFFFFПороджує $?a387173[${$244670s1*(1+($387173s1/100))} уламків фрагментів душі, а за критичних ударів — ще ${1*(1+($387173s1/100))}.][$244670s1 уламків фрагментів душі, а за критичних ударів — ще 1.]|r" },
    { en = "Reduces the target's movement speed by $s1% for $d.$?a391102[\n\n\n\nApplies to enemies within $391104A1 yds of the target.][]", ua = "Зменшує швидкість руху цілі на $s1% на $d.$?a391102[\n\n\n\nЗастосовується до ворогів у межах $391104A1 ярд(ів) від цілі.][]" },
    { en = "$?s388667[Drain Soul][Shadow Bolt] applies Shadow Embrace, increasing your damage dealt to the target by $?s388667[$32390s1%][$453206s2%] for $32390d. Stacks up to $?s388667[$32390u][$453206u] times.", ua = "$?s388667[Викрадення душі][Тіньова блискавка] накладає Тіньові обійми, збільшуючи завдану вами по цілі шкоду на $?s388667[$32390s1%][$453206s2%] на $32390d. Накопичується до $?s388667[$32390u][$453206u] раз(ів)." },
    { en = "Finishing move that drives your poisoned blades in deep, dealing instant Nature damage and increasing your poison application chance by $s2%. Damage and duration increased per combo point.\n\n\n\n   1 point  : ${$m1*1} damage, 1 sec\n\n   2 points: ${$m1*2} damage, 2 sec\n\n   3 points: ${$m1*3} damage, 3 sec\n\n   4 points: ${$m1*4} damage, 4 sec\n\n   5 points: ${$m1*5} damage, 5 sec$?s193531|((s457512)&!s193531)[\n\n   6 points: ${$m1*6} damage, 6 sec ][]$?s193531&s457512[\n\n   7 points: ${$m1*7} damage, 7 sec][]$?a381669[\n\n\n\nUp to 2 Envenom applications can overlap.][]", ua = "Завершальний прийом, що глибоко занурює ваші отруєні клинки, завдаючи миттєвої шкоди природою і збільшуючи шанс накладення вашої отрути на $s2%. Шкода і тривалість зростають за кожне очко комбо.\n\n\n\n   1 очко  : ${$m1*1} шкоди, 1 с\n\n   2 очки: ${$m1*2} шкоди, 2 с\n\n   3 очки: ${$m1*3} шкоди, 3 с\n\n   4 очки: ${$m1*4} шкоди, 4 с\n\n   5 очок: ${$m1*5} шкоди, 5 с$?s193531|((s457512)&!s193531)[\n\n   6 очок: ${$m1*6} шкоди, 6 с ][]$?s193531&s457512[\n\n   7 очок: ${$m1*7} шкоди, 7 с][]$?a381669[\n\n\n\nОдночасно можуть накладатися до 2 застосувань Отруєння.][]" },
    { en = "A touch of darkness that causes $34914o2 Shadow damage over $34914d, and heals you for ${$e2*100}% of damage dealt. If Vampiric Touch is dispelled, the dispeller flees in Horror for $87204d.\n\n\n\n|cFFFFFFFFGenerates ${$m3/100} Insanity.|r", ua = "Дотик темряви, що завдає $34914o2 тіньової шкоди протягом $34914d і зцілює вас на ${$e2*100}% завданої шкоди. Якщо Вампіричний Дотик розвіяно, той, хто розвіяв, тікає в Жасі на $87204d.\n\n\n\n|cFFFFFFFFГенерує ${$m3/100} Безумства.|r" },
    { en = "The target becomes a Living Bomb, taking $217694o1 Fire damage over $217694d, and then exploding to deal an additional $44461s2 Fire damage to the target and reduced damage to all other enemies within $44461A2 yds.\n\n\n\nOther enemies hit by this explosion also become a Living Bomb, but this effect cannot spread further.", ua = "Ціль стає Живою Бомбою, отримуючи $217694o1 вогняної шкоди протягом $217694d, а потім вибухає, завдаючи додатково $44461s2 вогняної шкоди цілі та зменшеної шкоди всім іншим ворогам у радіусі $44461A2 ярдів.\n\n\n\nІнші вороги, уражені цим вибухом, також стають Живою Бомбою, але цей ефект не може поширюватися далі." },
    { en = "Raises $?s207313[an Abomination]?s58640[a Geist][a Ghoul] to fight by your side. You can have a maximum of one $?s207313[Abomination]?s58640[Geist][Ghoul] at a time.", ua = "Піднімає $?s207313[Мерзоту]?s58640[Гейста][Гуля], щоб битися поруч із вами. Ви можете мати щонайбільше одного $?s207313[Мерзоту]?s58640[Гейста][Гуля] водночас." },
    { en = "Allows you to dual-wield a pair of two-handed weapons. Two-handed weapons deal more damage, and provide more Strength and Stamina than one-handed weapons.", ua = "Дозволяє тримати по дворучній зброї в кожній руці. Дворучна зброя завдає більше шкоди та дає більше Сили й Витривалості, ніж одноручна." },
    { en = "Launches a volley of holy light at the target, causing $<penancedamage> Holy damage to an enemy or $<penancehealing> healing to an ally over $47758d. Castable while moving.\n\n\n\nWhen you heal with Penance, everyone with your Atonement is healed for $197419s2.", ua = "Випускає у ціль залп святого світла, завдаючи $<penancedamage> священної шкоди ворогові або даючи $<penancehealing> зцілення союзникові протягом $47758d. Можна творити в русі.\n\n\n\nКоли ви зцілюєте Покаянням, кожен, на кому ваше Спокутування, зцілюється на $197419s2." },
    { en = "Disperse into pure shadow energy, reducing all damage taken by $s1% for $d and healing you for $<heal>% of your maximum health over its duration, but you are unable to attack or cast spells.\n\n\n\nIncreases movement speed by $s4% and makes you immune to all movement impairing effects.\n\n\n\nCastable while stunned, feared, or silenced.", ua = "Розсіюєтеся в чисту тіньову енергію, знижуючи всю отримувану шкоду на $s1% на $d і зцілюючи вас на $<heal>% максимального здоров'я протягом цього часу, але ви не можете атакувати чи творити закляття.\n\n\n\nЗбільшує швидкість пересування на $s4% і робить вас несприйнятливими до всіх ефектів, що уповільнюють рух.\n\n\n\nМожна творити під час оглушення, страху чи німоти." },
    { en = "Heals a friendly target for $s1.  Receives $s2% bonus from $@spellname77495.", ua = "Зцілює дружню ціль на $s1. Отримує бонус $s2% від $@spellname77495." },
    { en = "Each Runic Power you spend has a $<chance>% chance to increase your Rune regeneration rate by $?a137008[$51460s3][$51460s1]% for $51460d.", ua = "Кожна витрачена вами Рунічна сила має $<chance>% шанс збільшити швидкість відновлення ваших рун на $?a137008[$51460s3][$51460s1]% на $51460d." },
    { en = "Calls down a bolt of lightning, dealing $s1 Nature damage to all enemies within $A1 yards, reducing their movement speed by $s3% for $d, and knocking them $?s378779[upward][away from the Shaman]. Usable while stunned.", ua = "Прикликає блискавку, що завдає $s1 шкоди природою всім ворогам у межах $A1 ярдів, зменшує їхню швидкість руху на $s3% на $d і відкидає їх $?s378779[угору][геть від шамана]. Можна застосовувати під час оглушення." },
    { en = "Summons two $?s262624[Elemental ][]Spirit $?s147783[Raptors][Wolves] that aid you in battle for $228562d. They are immune to movement-impairing effects, and each $?s262624[Elemental ][]Feral Spirit summoned grants you $?s262624[$224125s1%][$392375s1%] increased Physical$?s262624[ and $224125s1% increased Fire, Frost, or Nature][] damage dealt by your abilities.\n\n\n\nFeral Spirit generates one stack of Maelstrom Weapon immediately, and one stack every $333957t1 sec for $333957d.", ua = "Прикликає двох $?s262624[Стихійних ][]Духовних $?s147783[Рапторів][Вовків], що допомагають вам у бою протягом $228562d. Вони несприйнятливі до ефектів, що обмежують рух, і кожен прикликаний $?s262624[Стихійний ][]Дикий дух збільшує фізичну$?s262624[, а також вогняну, морозну чи природну на $224125s1%][] шкоду, завдану вашими здібностями, на $?s262624[$224125s1%][$392375s1%].\n\n\n\nДикий дух одразу породжує один заряд Зброї Виру, а також ще один заряд кожні $333957t1 с протягом $333957d." },
    { en = "Sprays knives at all enemies within $A1 yards, dealing $s1 Physical damage and applying your active poisons at their normal rate. Deals reduced damage beyond $s3 targets.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Розкидає ножі по всіх ворогах у межах $A1 ярдів, завдаючи $s1 фізичної шкоди і накладаючи ваші активні отрути зі звичайною частотою. Завдає зменшеної шкоди понад $s3 цілей.\n\n\n\n|cFFFFFFFFНадає $s2 $lочко комбо:очок комбо;.|r" },
    { en = "The caster is surrounded by globes of water, granting $s2 mana per 5 sec. When a melee attack hits the caster, the caster regains $?s382033[${($382033s5/100+1)*$52128s1}][$52128s1]% of their mana. This effect can only occur once every $?a462454[${$proccooldown+($462454s2/1000)}.1][$proccooldown] sec. \n\n\n\n$?s383010[The Shaman can have up to two Elemental Shields active on them.][Only one of your Elemental Shields can be active on you at once.]", ua = "Того, хто творить закляття, оточують кулі води, що дають $s2 мани за 5 с. Коли по ньому влучає атака ближнього бою, він відновлює $?s382033[${($382033s5/100+1)*$52128s1}][$52128s1]% своєї мани. Цей ефект може спрацьовувати не частіше, ніж раз на $?a462454[${$proccooldown+($462454s2/1000)}.1][$proccooldown] с. \n\n\n\n$?s383010[На шамані водночас можуть бути активні до двох Стихійних щитів.][Водночас на вас може бути активний лише один із ваших Стихійних щитів.]" },
    { en = "You master the art of beast training, teaching you the ability to tame Exotic pets.", ua = "Ви опановуєте мистецтво приборкання звірів, що дає вам змогу приборкувати Екзотичних улюбленців." },
    { en = "Increases your maximum Focus and your pet's maximum Focus by $s1.", ua = "Збільшує ваш максимальний Фокус і максимальний Фокус вашого улюбленця на $s1." },
    { en = "When use all your Runes you blow the Horn of Winter, gaining $s1 $LRune:Runes;.\n\n\n\nCan only occur every 45 sec.", ua = "Коли ви витрачаєте всі свої руни, ви сурмите в Ріг зими й отримуєте $s1 $Lруну:рун;.\n\n\n\nСпрацьовує не частіше ніж раз на 45 с." },
    { en = "Frost Strike and Glacial Advance have a $s2% chance to cause your next Howling Blast to consume no runes and deal $59052s2% additional damage.", ua = "Крижаний Удар і Льодовиковий Наступ мають $s2% шанс зробити так, що ваш наступний Виючий Порив не витратить рун і завдасть на $59052s2% більше шкоди." },
    { en = "Siphons the target's life essence, dealing $o1 Shadow damage over $d and healing you for ${$e1*100}% of the damage done.", ua = "Викачує життєву есенцію цілі, завдаючи $o1 тіньової шкоди протягом $d і зцілюючи вас на ${$e1*100}% завданої шкоди." },
    { en = "Flash Heal reduces the cooldown of Holy Word: Serenity by $2050s2 sec.\n\n\n\nPrayer of Healing reduces the cooldown on Holy Word: Sanctify by $34861s3 sec.\n\n\n\nSmite and Holy Nova reduce the cooldown of Holy Word: Chastise by $88625s2 sec.", ua = "Швидке Зцілення знижує перезарядження Святого Слова: Безтурботність на $2050s2 сек.\n\n\n\nМолитва Зцілення знижує перезарядження Святого Слова: Освячення на $34861s3 сек.\n\n\n\nКарання і Свята Нова знижують перезарядження Святого Слова: Покарання на $88625s2 сек." },
    { en = "Terrifies the target in place, stunning them for $d.", ua = "Жахає ціль на місці, оглушуючи її на $d." },
    { en = "Casting Shadow Word: Madness while at least $s1 Vampiric Touches are active summons an apparition twisted with corruption. Upon reaching its target, it explodes and deals $1231479s1 Shadow damage to all enemies within $1231479a1 yds.", ua = "Творення Тіньового Слова: Божевілля, коли активні щонайменше $s1 Вампіричні Дотики, прикликає примару, спотворену розкладом. Досягнувши цілі, вона вибухає і завдає $1231479s1 тіньової шкоди всім ворогам у радіусі $1231479a1 ярдів." },
    { en = "Increases the damage done by your pets by ${$s1}.1% and the damage of your shots and traps by ${$s5}.1%.", ua = "Збільшує шкоду від ваших улюбленців на ${$s1}.1% та шкоду ваших пострілів і пасток на ${$s5}.1%." },
    { en = "Increases your chance to block melee attacks by ${$s1}.1%$?a317907[, and your chance to block spells and harmful periodic effects by ${$317907s1}.1%.][.]\n\n\n\nAlso increases your attack power by ${$s2}.1%.", ua = "Підвищує ваш шанс блокувати атаки ближнього бою на ${$s1}.1%$?a317907[, а ваш шанс блокувати закляття та шкідливі періодичні ефекти — на ${$317907s1}.1%.][.]\n\n\n\nТакож підвищує вашу силу атаки на ${$s2}.1%." },
    { en = "Increases the damage done by your Nature damage $?s319473[and bleeds ][]by ${$s1}.1%.", ua = "Підвищує шкоду, яку завдають ваші здібності шкоди Природою $?s319473[та кровотечі ][]на ${$s1}.1%." },
    { en = "Increases the damage done by your finishing moves by ${$76808m1}.1%.", ua = "Збільшує шкоду ваших добивань на ${$76808m1}.1%." },
    { en = "Increases damage done while Enraged by ${$s1}.1%.", ua = "Збільшує завдану шкоду на ${$s1}.1%, поки ви розлючені." },
    { en = "Increases your chance to block by ${$s2}.1% and your chance to critically block (blocking twice the amount) by ${$s1}.1%.\n\n\n\nAlso increases your attack power by ${$s5}.1%.", ua = "Збільшує ваш шанс блокувати на ${$s2}.1% та ваш шанс критично блокувати (блокуючи подвійний обсяг) на ${$s1}.1%.\n\n\n\nТакож збільшує вашу силу атаки на ${$s5}.1%." },
    { en = "Removes all Magic$?s383016[ and Curse][] effects from a friendly target.", ua = "Знімає всі ефекти Магії$?s383016[ та Прокляття][] з дружньої цілі." },
    { en = "Increases damage done by Agony, $?s445465[Wither][Corruption],$?s63106[ Siphon Life,][]$?s205179[ Phantom Singularity,][]$?s278350[ Vile Taint,][]$?s386997[ Soul Rot,][] Unstable Affliction, and Seed of Corruption by ${$77215s1}.1%.", ua = "Підвищує шкоду від Агонії, $?s445465[В'янення][Псування],$?s63106[ Викачування життя,][]$?s205179[ Примарної сингулярності,][]$?s278350[ Мерзенної скверни,][]$?s386997[ Гниття душі,][] Нестійкого лиха та Сімені Псування на ${$77215s1}.1%." },
    { en = "Your spells deal ${$s1/2}.1% increased damage, plus a random amount of up to ${$s1/2}.1% additional increased damage.", ua = "Ваші закляття завдають на ${$s1/2}.1% більше шкоди, плюс випадкову кількість аж до ${$s1/2}.1% додаткової шкоди." },
    { en = "Increases your chance to trigger Stormsurge and Windfury Weapon by ${$m3}.2%, and increases all Fire, Frost, and Nature damage you deal by ${$77223m1}.1%.$?s201845[\n\n\n\n$@spellicon201845 $@spellname201845\n\n$@spelldesc201845][]", ua = "Підвищує ваш шанс спрацювання Штормового валу та Зброї шаленства вітру на ${$m3}.2%, а також підвищує всю шкоду Вогнем, Морозом і Природою, яку ви завдаєте, на ${$77223m1}.1%.$?s201845[\n\n\n\n$@spellicon201845 $@spellname201845\n\n$@spelldesc201845][]" },
    { en = "Increases healing from your spells by up to ${$77226s1}.1%, based on the current health of your target. Lower health targets are healed for more.", ua = "Збільшує зцілення від ваших заклять аж до ${$77226s1}.1%, залежно від поточного здоров'я вашої цілі. Цілі з нижчим здоров'ям зцілюються більше." },
    { en = "An efficient wave of healing energy that restores $s1 of a friendly target's health.", ua = "Ефективна хвиля цілющої енергії, що відновлює $s1 здоров'я дружньої цілі." },
    { en = "Your direct healing spells heal for an additional ${$77485s1}.1% over $77489d.\n\n\n\nIncreases the healing of Renew by ${$s3}.1%.", ua = "Ваші прямі зцілювальні закляття зцілюють на ${$77485s1}.1% більше протягом $77489d.\n\n\n\nЗбільшує зцілення від «Оновлення» на ${$s3}.1%." },
    { en = "Increases the damage done by your Cat Form bleed and other periodic abilities and finishing moves by ${$s1}.1%.", ua = "Збільшує шкоду від ваших кровотеч у Котячій подобі та інших періодичних здібностей і добивань на ${$s1}.1%." },
    { en = "Your healing is increased by ${$s1}.1% for each of your Restoration heal over time effects on the target, reduced by each additional effect.", ua = "Ваше зцілення збільшується на ${$s1}.1% за кожен ваш ефект зцілення в часі спеціалізації Відновлення на цілі, зменшуючись з кожним додатковим ефектом." },
    { en = "Each time you heal yourself with Death Strike, you gain ${$s1}.1% of the amount healed as a Physical damage absorption shield, up to $s3% of you maximum health.\n\n\n\nAlso increases your attack power by ${$s2}.1%.", ua = "Щоразу, коли ви зцілюєте себе «Ударом смерті», ви отримуєте ${$s1}.1% від зціленого обсягу як щит, що поглинає фізичну шкоду, аж до $s3% вашого максимального здоров'я.\n\n\n\nТакож збільшує вашу силу атаки на ${$s2}.1%." },
    { en = "Increases the damage of your Frost abilities by ${$s1}.1%.", ua = "Збільшує шкоду ваших крижаних здібностей на ${$s1}.1%." },
    { en = "Increases the damage of your Minions and Shadow damage abilities by ${$s1}.1%.\n\n\n\nIncreases the critical strike damage of your Minions and Diseases by ${$s5}.1%.", ua = "Збільшує шкоду ваших прислужників та здібностей тіньової шкоди на ${$s1}.1%.\n\n\n\nЗбільшує критичну шкоду ваших прислужників і хвороб на ${$s5}.1%." },
    { en = "Flame Shock periodic damage has a chance to reset the remaining cooldown on Lava Burst and cause your next Lava Burst to be instant.", ua = "Періодична шкода «Полум'яного шоку» має шанс скинути залишкове перезарядження «Виверження лави» та зробити ваше наступне «Виверження лави» миттєвим." },
    { en = "Finishing moves reduce the remaining cooldown of many Rogue skills by $<cdr> sec per combo point spent.\n\n\n\nAffected skills: Adrenaline Rush, Between the Eyes, Blade Flurry, Blade Rush, Grappling Hook, Keep it Rolling, Killing Spree, Roll the Bones, and Sprint.", ua = "Добивання зменшують залишкове перезарядження багатьох умінь розбійника на $<cdr> сек за кожне витрачене очко комбо.\n\n\n\nЗачеплені уміння: «Приплив адреналіну», «Між очі», «Шквал клинків», «Ривок клинка», «Гак-кішка», «Не зупиняйся», «Різанина», «Кидок костей» і «Спринт»." },
    { en = "Casting Arcane spells has a $s2% chance to grant access to Arcane Missiles or make your next Arcane Explosion free.", ua = "Творення арканних заклять має $s2% шанс надати доступ до «Арканних снарядів» або зробити ваш наступний «Арканний вибух» безкоштовним." },
    { en = "You can transmogrify your two-handed weapons to use one-handed weapon appearances.", ua = "Ви можете трансмогрифікувати свою дворучну зброю, щоб вона мала вигляд одноручної." },
    { en = "Your auto attacks on targets infected with your Blood Plague have a chance to make your next Death and Decay cost no runes and reset its cooldown.", ua = "Ваші автоатаки по цілях, заражених вашою «Кров'яною чумою», мають шанс зробити ваш наступний «Смерть і розпад» безкоштовним щодо рун і скинути його перезарядження." },
    { en = "Each Runic Power you spend has a ${$m1/10}.1% chance to instantly grant you a Rune.", ua = "Кожна витрачена одиниця рунічної сили має ${$m1/10}.1% шанс миттєво надати вам руну." },
    { en = "Wielding a two-handed weapon increases Obliterate damage by $81333s1%, Frostscythe damage by $s3%, and your auto attack critical strikes always grant Killing Machine.", ua = "Володіння дворучною зброєю збільшує шкоду від «Знищення» на $81333s1%, шкоду від «Морозної коси» на $s3%, а критичні удари ваших автоатак завжди надають «Машину вбивства»." },
    { en = "Unleashes a powerful weapon strike that deals $224266s1 $?s403664[Holystrike][Holy] damage to an enemy target.", ua = "Завдає потужного удару зброєю, що наносить ворожій цілі $224266s1 шкоди $?s403664[Священним ударом][Святом]." },
    { en = "Slash the enemy for $s1 Physical damage and corrupt your weapon with blight, causing your next $s3-$s4 Scourge Strikes to summon a Lesser Ghoul.\n\n\n\n$@spellicon275430$@spellname275430\n\n$@spelldesc275430", ua = "Розтинає ворога, завдаючи $s1 фізичної шкоди, та псує вашу зброю гниллю, через що ваші наступні $s3-$s4 Удари Погибелі прикликають нижчого гуля.\n\n\n\n$@spellicon275430$@spellname275430\n\n$@spelldesc275430" },
    { en = "Increases your Intellect by $s2% while wearing only Leather armor.", ua = "Збільшує ваш Інтелект на $s2%, поки ви носите лише шкіряну броню." },
    { en = "Increases your Stamina in Bear Form by $s3% while wearing only Leather armor.", ua = "Збільшує вашу Витривалість у ведмежій подобі на $s3%, поки ви носите лише шкіряну броню." },
    { en = "Increases your Strength by $s1% while wearing only Plate armor.", ua = "Збільшує вашу Силу на $s1%, поки ви носите лише латну броню." },
    { en = "Increases your Stamina by $s1% while wearing only Plate armor.", ua = "Збільшує вашу Витривалість на $s1%, поки ви носите лише латну броню." },
    { en = "Increases your Intellect by $s1% while wearing only Plate armor.", ua = "Збільшує ваш Інтелект на $s1%, поки ви носите лише латну броню." },
    { en = "You may equip one-handed weapons in your off-hand, and you have a chance to parry incoming frontal melee attacks.", ua = "Ви можете споряджати одноручну зброю в другу руку, а також маєте шанс парирувати фронтальні атаки ближнього бою." },
    { en = "Cures harmful effects on the friendly target, removing all Magic$?s392378[, Curse, and Poison][] effects.", ua = "Зцілює шкідливі ефекти на дружній цілі, знімаючи всі ефекти Магії$?s392378[, Прокляття та Отрути][]." },
    { en = "Protects a friendly target for $d. Any damage taken will consume the ward and heal the target for $102352o1 over $102352d.", ua = "Захищає дружню ціль на $d. Будь-яка отримана шкода поглинає оберіг і зцілює ціль на $102352o1 протягом $102352d." },
    { en = "Decreases damage taken by $s1%, increases your chance to dodge by $s3%, and reduces the chance for your attacks to be parried by $s4%.", ua = "Зменшує отриману шкоду на $s1%, збільшує ваш шанс ухилитися на $s3% і знижує ймовірність того, що ваші атаки будуть парировані, на $s4%." },
    { en = "Your Holy Power generation is tripled for $d.", ua = "Генерація вашої Святої сили потроюється на $d." },
    { en = "Instantly heals you for $s1% of maximum health. Usable in all shapeshift forms.", ua = "Миттєво зцілює вас на $s1% від максимального здоров'я. Можна використовувати в усіх подобах перевтілення." },
    { en = "Resets the cooldown of your most recently used totem with a base cooldown shorter than 3 minutes.", ua = "Скидає перезарядження останнього використаного тотема з базовим перезарядженням коротшим за 3 хвилини." },
    { en = "Makes your next Mage spell with a cast time shorter than $s2 sec castable while moving. Unaffected by the global cooldown and castable while casting.", ua = "Дозволяє творити наступне закляття мага з часом прочитання коротшим за $s2 сек під час руху. Не залежить від глобального перезарядження і твориться під час прочитання інших заклять." },
    { en = "Swap health percentages with your ally. Increases the lower health percentage of the two to $s1% if below that amount.", ua = "Обмінюється відсотком здоров'я з союзником. Підвищує менший із двох відсотків до $s1%, якщо він нижчий за це значення." },
    { en = "Summons a Felguard who attacks the target for $d that deals $216187s1% increased damage.\n\n\n\nThis Felguard will stun and interrupt their target when summoned.", ua = "Прикликає стража Скверни, який атакує ціль протягом $d і завдає на $216187s1% більше шкоди.\n\n\n\nЦей страж Скверни приголомшить і перерве ціль, щойно його прикличуть." },
    { en = "Throws a shuriken at an enemy target for ${$s1*$<CAP>/$AP} Physical damage.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Кидає сюрикен у ворожу ціль, завдаючи ${$s1*$<CAP>/$AP} фізичної шкоди.\n\n\n\n|cFFFFFFFFНадає $s2 $lочко:очок; комбо.|r" },
    { en = "Places a Nether Tempest on the target which deals $114923o1 Arcane damage over $114923d to the target and nearby enemies within 10 yds. Limit 1 target. Deals reduced damage to secondary targets.\n\n\n\nDamage increased by $36032s1% per Arcane Charge.", ua = "Накладає на ціль Буревій Нижнього Світу, що завдає $114923o1 арканної шкоди протягом $114923d цілі та ворогам поблизу в межах 10 ярдів. Обмеження: 1 ціль. Завдає зменшеної шкоди другорядним цілям.\n\n\n\nШкода збільшується на $36032s1% за кожен арканний заряд." },
    { en = "Reduces all damage taken by $s2% for $d. Being hit by a melee attack, or taking another action$?s328682[ other than movement][] will cancel this effect.", ua = "Зменшує всю отримувану шкоду на $s2% протягом $d. Отримання удару в ближньому бою або будь-яка інша дія$?s328682[, окрім руху,][] скасовує цей ефект." },
    { en = "Removes all Magic$?a388874[, Poison, and Disease][] effects from the target.", ua = "Знімає з цілі всі ефекти Магії$?a388874[, Отрути та Хвороби][]." },
    { en = "Your abilities deal ${$s1}.1% more damage when they are not a repeat of the previous ability.", ua = "Ваші здібності завдають на ${$s1}.1% більше шкоди, коли вони не повторюють попередню здібність." },
    { en = "Each time you are hit by a melee attack, or hit with Blackout Kick, you gain stacking ${$s1}.1% increased Dodge chance until your next successful Dodge.\n\n\n\nAlso increases your attack power by ${$s2}.1%.", ua = "Щоразу, коли вас вражає атака ближнього бою або ви влучаєте «Затьмарливим ударом», ваш шанс ухилення зростає на ${$s1}.1%. Ефект накопичується до наступного вдалого ухилення.\n\n\n\nТакож збільшує вашу силу атаки на ${$s2}.1%." },
    { en = "Renewing Mist and Enveloping Mist cause a gust of healing mists, instantly healing the primary target for $191894s1.", ua = "«Оновлювальний туман» та «Огортальний туман» здіймають подих цілющих туманів, миттєво зцілюючи основну ціль на $191894s1." },
    { en = "Increases your Intellect by $s1% while wearing only Leather armor.", ua = "Збільшує ваш Інтелект на $s1%, поки ви носите лише шкіряну броню." },
    { en = "Increases your Stamina by $s1% while wearing only Leather armor.", ua = "Збільшує вашу Витривалість на $s1%, поки ви носите лише шкіряну броню." },
    { en = "Rapidly fires a spray of shots for $120360d, dealing an average of $<damageSec> Physical damage to all nearby enemies in front of you. Usable while moving. Deals reduced damage beyond $120361s1 targets.\n\n\n\n$?c1[Grants Beast Cleave.][]", ua = "Швидко випускає град пострілів протягом $120360d, завдаючи в середньому $<damageSec> фізичної шкоди всім ворогам поблизу перед вами. Можна застосовувати в русі. Завдає зменшеної шкоди понад $120361s1 цілей.\n\n\n\n$?c1[Надає Звіриний розтин.][]" },
    { en = "Reduces all damage you take by $m2% to $m3% for $d, with larger attacks being reduced by more.", ua = "Зменшує всю отримувану вами шкоду на $m2%–$m3% протягом $d, причому потужніші атаки зменшуються сильніше." },
    { en = "Drink a healing elixir, healing you for $s1% of your maximum health.", ua = "Ви п'єте цілющий еліксир, який відновлює вам $s1% максимального здоров'я." },
    { en = "Reduces magic damage you take by $m1% for $d, and transfers all currently active harmful magical effects on you back to their original caster if possible.", ua = "Зменшує магічну шкоду, яку ви отримуєте, на $m1% протягом $d і за можливості повертає всі активні шкідливі магічні ефекти на вас назад тому, хто їх наклав." },
    { en = "Summons a Mindbender to attack the target for $d. \n\n\n\n|cFFFFFFFFGenerates ${$123051m1/100}.1% Mana each time the Mindbender attacks.|r", ua = "Прикликає розумокрута, який атакує ціль протягом $d. \n\n\n\n|cFFFFFFFFГенерує ${$123051m1/100}.1% мани щоразу, коли розумокрут атакує.|r" },
    { en = "You may equip one-handed weapons in your off-hand.", ua = "Ви можете споряджати одноручну зброю у другу руку." },
    { en = "Repairing a damaged cannon.", ua = "Ремонт пошкодженої гармати." },
    { en = "Your Blackout Kick now also deals an additional $m1% damage over $128531d if behind the target or heals you for $m1% of the damage done if in front of the target.\n\n\n\nAdditionally, your Rising Sun Kick now also causes Mortal Wounds to the primary target.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFMortal Wounds|r\n\nGrievously wounds the target, reducing the effectiveness of any healing received for $115804d.", ua = "Ваш «Затемнювальний удар» тепер також завдає додатково $m1% шкоди протягом $128531d, якщо ви позаду цілі, або зцілює вас на $m1% завданої шкоди, якщо ви перед ціллю.\n\n\n\nОкрім того, ваш «Удар вранішнього сонця» тепер також накладає «Смертельні рани» на основну ціль.\n\n\n\n|Tinterface\\icons\\ability_criticalstrike.blp:24|t |cFFFFFFFFСмертельні рани|r\n\nТяжко ранить ціль, знижуючи ефективність будь-якого отриманого зцілення протягом $115804d." },
    { en = "Enemies disabled by your Cheap Shot or $?s199804[Between the Eyes][Kidney Shot] take $s1% increased damage from all sources for $255909d.", ua = "Вороги, знерухомлені вашим Підступним ударом чи $?s199804[Між очі][Ударом по нирках], отримують на $s1% більше шкоди з усіх джерел протягом $255909d." },
    { en = "Summons a flock of crows to attack your target, dealing ${$131900s1*$d} Physical damage over $d.", ua = "Прикликає зграю круків, що атакують вашу ціль, завдаючи ${$131900s1*$d} фізичної шкоди протягом $d." },
    { en = "Autoattacks have a $s1% chance to empower your next cast of Maul or Raze, stacking up to $135286u times.\n\n\n\nAn empowered cast of Maul or Raze deals $135286s1% increased damage, costs $135286s3% less rage, and reduces the target's damage to you by $135601s2% for $135601d.", ua = "Автоатаки мають $s1% шансу підсилити ваше наступне творення «Розтрощення» або «Знищення», накопичуючись до $135286u разів.\n\n\n\nПідсилене творення «Розтрощення» або «Знищення» завдає на $135286s1% більше шкоди, коштує на $135286s3% менше люті й знижує шкоду, яку ціль завдає вам, на $135601s2% протягом $135601d." },
    { en = "Restoration Druid core passive", ua = "Друїд Відновлення, основна пасивна" },
    { en = "Mistweaver Monk core passive", ua = "Монах Ткач Туману, основна пасивна" },
    { en = "Holy Paladin core passive", ua = "Паладин Світла, основна пасивна" },
    { en = "Holy Priest core passive", ua = "Жрець Світла, основна пасивна" },
    { en = "Discipline Priest core passive", ua = "Жрець Дисципліни, основна пасивна" },
    { en = "Restoration Shaman core passive", ua = "Шаман Відновлення, основна пасивна" },
    { en = "Elemental Shaman baseline passive", ua = "Шаман Стихій, базова пасивна" },
    { en = "Marks the target, instantly granting full combo points and increasing the damage of your finishing moves by $s1% for $d. Cooldown resets if the target dies during effect.", ua = "Позначає ціль, миттєво надаючи повний набір очок комбо й підвищуючи шкоду ваших завершальних прийомів на $s1% протягом $d. Перезарядження скидається, якщо ціль гине під час дії ефекту." },
    { en = "Split into 3 elemental spirits for $d, each spirit dealing ${100+$m1}% of normal damage and healing.\n\n\n\nYou directly control the Storm spirit, while Earth and Fire spirits mimic your attacks on nearby enemies.\n\n\n\nWhile active, casting Storm, Earth, and Fire again will cause the spirits to fixate on your target.", ua = "Розділяє вас на 3 стихійні духи протягом $d, кожен дух завдає ${100+$m1}% звичайної шкоди та зцілення.\n\n\n\nВи безпосередньо керуєте духом Бурі, тоді як духи Землі та Вогню повторюють ваші атаки по ворогах поблизу.\n\n\n\nПоки ефект активний, повторне творення «Бурі, Землі та Вогню» змусить духів зосередитися на вашій цілі." },
    { en = "Inflicts Frost damage to nearby enemies, reducing their movement speed for $d.", ua = "Завдає шкоди Морозом ворогам поблизу, знижуючи їхню швидкість пересування протягом $d." },
    { en = "Imbue a friendly target with a Barrier of Faith, absorbing $<shield> damage for $395180d. For the next $d, Barrier of Faith accumulates $s2% of effective healing from your Flash of Light, Holy Light, or Holy Shock spells. Every $t2 sec, the accumulated healing becomes an absorb shield.", ua = "Наділяє дружню ціль «Бар'єром віри», що поглинає $<shield> шкоди протягом $395180d. Протягом наступних $d «Бар'єр віри» накопичує $s2% ефективного зцілення від ваших заклять «Спалах світла», «Святе світло» чи «Святий шок». Кожні $t2 с накопичене зцілення перетворюється на щит поглинання." },
    { en = "Ambush and Mutilate refund $256522s1 Energy when used against a poisoned target.", ua = "«Засідка» та «Каліцтво» повертають $256522s1 енергії, коли застосовані проти отруєної цілі." },
    { en = "Continuously deal ${$155166s2*$<CAP>/$AP} Frost damage every $t1 sec to enemies in a cone in front of you, until your Runic Power is exhausted. Deals reduced damage to secondary targets.\n\n\n\n|cFFFFFFFFGenerates $303753s1 $lRune:Runes; at the start and end.|r", ua = "Безперервно завдає ${$155166s2*$<CAP>/$AP} шкоди Морозом кожні $t1 сек ворогам у конусі перед вами, доки не вичерпається ваша Рунічна сила. Завдає зменшеної шкоди другорядним цілям.\n\n\n\n|cFFFFFFFFСтворює $303753s1 $lруну:рун; на початку та в кінці.|r" },
    { en = "Defile the targeted ground, dealing ${($156000s1*($d+1)/$t3)} Shadow damage to all enemies over $d$?a315442|a331119[, and inflict Death's Due for $324164d.\n\n\n\nDeath's Due reduces damage enemies deal to you by $324164s1%, up to a maximum of ${$324164s1*-$324164u}% and their power is transferred to you as an equal amount of Strength.][.]\n\n\n\nEvery sec, if any enemies are standing in the Defile, it grows in size and deals increased damage.", ua = "Оскверняє позначену землю, завдаючи ${($156000s1*($d+1)/$t3)} шкоди Тінню всім ворогам протягом $d$?a315442|a331119[ та накладає Данину Смерті на $324164d.\n\n\n\nДанина Смерті зменшує шкоду, яку вороги завдають вам, на $324164s1%, до максимуму в ${$324164s1*-$324164u}%, а їхня міць передається вам як рівна кількість Сили.][.]\n\n\n\nЩосекунди, якщо будь-які вороги стоять в Осквернінні, воно росте в розмірі та завдає більшої шкоди." },
    { en = "Your Fireball, Pyroblast, Fire Blast, Scorch and Phoenix Flames critical strikes reduce the remaining cooldown on Combustion by $<cdr> sec.\n\n\n\nFlamestrike critical strikes reduce the remaining cooldown of Combustion by ${$s1/1000/$s2}.1 sec for each critical strike, up to ${$s1/1000} sec.", ua = "Критичні удари «Вогняної кулі», «Піровибуху», «Вогняного удару», «Обпалення» та «Полум'я Фенікса» скорочують залишкове перезарядження «Займання» на $<cdr> с.\n\n\n\nКритичні удари «Вогняного удару по площі» скорочують залишкове перезарядження «Займання» на ${$s1/1000/$s2}.1 с за кожен критичний удар, до ${$s1/1000} с." },
    { en = "Icy Veins' duration is increased by ${$s2/1000} sec.\n\n\n\nYour Ice Lances against frozen targets extend your Icy Veins by an additional ${$s1/1000}.1 sec$?s199786[ and Glacial Spike extends it an addtional ${$s3/1000}.1 sec][].", ua = "Тривалість «Крижаних вен» збільшено на ${$s2/1000} сек.\n\n\n\nВаші «Крижані списи» по заморожених цілях подовжують «Крижані вени» ще на ${$s1/1000}.1 сек$?s199786[, а «Льодовиковий шпичак» подовжує їх ще на ${$s3/1000}.1 сек][]." },
    { en = "Increases your damage by $s3% when you do not have an active pet.", ua = "Збільшує вашу шкоду на $s3%, коли у вас немає активного улюбленця." },
    { en = "Every ${$c*$s1} mana you spend brings a High Tide, making your next $288675n Chain Heals heal for an additional $288675s1% and not reduce with each jump.", ua = "За кожні ${$c*$s1} витраченої мани ви отримуєте «Приплив», завдяки чому наступні $288675n «Ланцюгові зцілення» зцілюють додатково на $288675s1% і не слабшають з кожним переходом." },
    { en = "Each time your Fireball fails to critically strike a target, it gains a stacking $157644s1% increased critical strike chance. Effect ends when Fireball critically strikes.", ua = "Щоразу, коли ваша «Вогняна куля» не завдає критичного удару по цілі, її шанс критичного удару збільшується на $157644s1% з накопиченням. Ефект завершується, коли «Вогняна куля» завдає критичного удару." },
    { en = "Causes an explosion around yourself, dealing $s1 Fire damage to all enemies within $A1 yds, knocking them back, and reducing movement speed by $s2% for $d.", ua = "Спричиняє вибух навколо вас, завдаючи $s1 шкоди вогнем усім ворогам у межах $A1 м, відкидаючи їх та зменшуючи швидкість пересування на $s2% на $d." },
    { en = "You gain Parry equal to $s1% of your Critical Strike from gear.", ua = "Ви отримуєте Парирування, що дорівнює $s1% вашого Критичного удару від спорядження." },
    { en = "All Elemental damage increased by ${$s3}.1%.\n\n\n\nYour Lightning Bolt,$?s454009[ Tempest,][] Lava Burst, and Chain Lightning casts have a ${$s1}.1% chance to trigger a second cast on the same target, dealing $s2% of normal damage and generating less Maelstrom.", ua = "Уся шкода від стихій збільшена на ${$s3}.1%.\n\n\n\nВаше прочитання «Спалаху блискавки»,$?s454009[ «Бурі»,][] «Виверження лави» та «Ланцюгової блискавки» має ${$s1}.1% шанс спричинити повторне прочитання по тій самій цілі, завдаючи $s2% звичайної шкоди й генеруючи менше Виру." },
    { en = "Damage done by you or your demon has a chance to grant the other one $s2% increased damage for $171982d.", ua = "Шкода, завдана вами або вашим демоном, має шанс надати іншому збільшення шкоди на $s2% на $171982d." },
    { en = "When you kill an enemy that yields experience or honor, your next Death Strike within $101568d is free and heals for an additional $101568s1% of maximum health.", ua = "Коли ви вбиваєте ворога, що дає досвід або честь, ваш наступний «Смертельний удар» протягом $101568d безкоштовний і зцілює додатково на $101568s1% максимального здоров'я." },
    { en = "Killing an enemy sometimes creates a Soul Fragment that is consumed when you approach it, healing you for $178963s1% of maximum health$?a206478[ and generating $210041s1 Fury][].\n\n\n\nIf the Soul Fragment came from a Demon, you will deal $163073s1% increased damage for $163073d.", ua = "Убивство ворога іноді створює Уламок душі, що поглинається, коли ви наближаєтесь до нього, зцілюючи вас на $178963s1% максимального здоров'я$?a206478[ і генеруючи $210041s1 Люті][].\n\n\n\nЯкщо Уламок душі походив від демона, ви завдаватимете на $163073s1% більше шкоди протягом $163073d." },
    { en = "Increases your Agility by $s1% while wearing only leather armor.", ua = "Збільшує вашу Спритність на $s1%, поки ви носите лише шкіряну броню." },
    { en = "Increases healing done by up to ${$s1}.2%, based on the proximity of your target.", ua = "Збільшує завдане зцілення до ${$s1}.2% залежно від близькості до вашої цілі." },
    { en = "Becoming Enraged increases your damage done by $76856s1%$?s383848[, Haste by $184362s1%, and movement speed by $184362s2% for $184362d.]?s440277[, Mastery by $184362s5% and Leech by $184362s6% for $184362d.][ for $184362d.]\n\n\n\n$@spellicon23881 Bloodthirst has a $23881s3% chance to Enrage you.\n\n\n\n$@spellicon184367 Rampage always Enrages you.", ua = "Входження в Лють збільшує вашу завдану шкоду на $76856s1%$?s383848[, Поспіх на $184362s1% і швидкість пересування на $184362s2% протягом $184362d.]?s440277[, Майстерність на $184362s5% і Висмоктування на $184362s6% протягом $184362d.][ протягом $184362d.]\n\n\n\n$@spellicon23881 «Кровожадність» має $23881s3% шанс увести вас у Лють.\n\n\n\n$@spellicon184367 «Буйство» завжди вводить вас у Лють." },
    { en = "Increases your Chaos damage by ${$s1}.1%$?s320654[ and your movement speed by ${$320654s1}.1%.][.]", ua = "Збільшує вашу шкоду від Хаосу на ${$s1}.1%$?s320654[ і вашу швидкість пересування на ${$320654s1}.1%.][.]" },
    { en = "Allows use of all Stealth abilities and grants all the combat benefits of Stealth for $d. Effect not broken from taking damage or attacking.", ua = "Дозволяє використовувати всі здібності Непомітності та надає всі бойові переваги Непомітності на $d. Ефект не переривається від отриманої шкоди чи атак." },
    { en = "Strike the target, dealing $s1 Physical damage.\n\n\n\nWhile Stealthed, you strike through the shadows and appear behind your target up to ${5+$245623s1} yds away, dealing $245623s2% additional damage.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Уражає ціль, завдаючи $s1 фізичної шкоди.\n\n\n\nПеребуваючи в непомітності, ви б'єте крізь тіні й з'являєтесь позаду цілі на відстані до ${5+$245623s1} м, завдаючи $245623s2% додаткової шкоди.\n\n\n\n|cFFFFFFFFНадає $s2 очко $lкомбо:комбо;.|r" },
    { en = "Throws a poison-coated knife, dealing $s1 damage and applying your active Lethal and Non-Lethal Poisons.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Кидає вкритий отрутою ніж, завдаючи $s1 шкоди й накладаючи ваші активні смертельні та несмертельні отрути.\n\n\n\n|cFFFFFFFFНадає $s2 очко $lкомбо:комбо;.|r" },
    { en = "Draw a concealed pistol and fire a quick shot at an enemy, dealing ${$s1*$<CAP>/$AP} Physical damage and reducing the target's movement speed by $s3% for $d.\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points;.|r", ua = "Вихоплюєте прихований пістоль і робите швидкий постріл у ворога, завдаючи ${$s1*$<CAP>/$AP} фізичної шкоди й знижуючи швидкість пересування цілі на $s3% протягом $d.\n\n\n\n|cFFFFFFFFНадає $s2 очко $lкомбо:комбо;.|r" },
    { en = "Your auto shot critical strikes have a $s1% chance to reset the cooldown of Barbed Shot.", ua = "Критичні удари вашого автопострілу мають $s1% шанс скинути перезарядження «Зазубреного пострілу»." },
    { en = "Increases the range of your $?s259387[Mongoose Bite][Raptor Strike] and Mastery: Spirit Bond to $265189r yds for $d.", ua = "Збільшує дальність вашого $?s259387[«Укусу мангуста»][«Удару раптора»] та «Майстерності: Духовний зв'язок» до $265189r м протягом $d." },
    { en = "Fires an explosion of bolts at all enemies in front of you, knocking them back, snaring them by $s4% for $d, and dealing $s1 Physical damage.$?s378771[\n\n\n\nWhen you fall below $378771s1% heath, Bursting Shot's cooldown is immediately reset. This can only occur once every $385646d.][]", ua = "Випускає вибух стріл по всіх ворогах перед вами, відкидаючи їх, сповільнюючи на $s4% протягом $d та завдаючи $s1 фізичної шкоди.$?s378771[\n\n\n\nКоли ваше здоров'я падає нижче $378771s1%, перезарядження «Розривного пострілу» негайно скидається. Це може статися лише раз на $385646d.][]" },
    { en = "A sweeping attack that strikes all enemies in front of you for $s1 Physical damage. Deals reduced damage beyond $s3 targets.$?s294029[\n\n\n\nReduces the remaining cooldown on Wildfire Bomb by $<cdr> sec for each target hit, up to $s3 sec.][]", ua = "Розмашиста атака, що уражає всіх ворогів перед вами на $s1 фізичної шкоди. Завдає зменшеної шкоди понад $s3 цілей.$?s294029[\n\n\n\nЗменшує залишкове перезарядження «Бомби дикого вогню» на $<cdr> сек за кожну уражену ціль, до $s3 сек.][]" },
    { en = "Transform to demon form for $d, increasing current health by $s2%, healing for that amount, and increasing Armor by $s8%$?s235893[. Versatility increased by $s5%][]$?s321067[. While transformed, Fracture generates one additional Lesser Soul Fragment][]$?s321068[ and $s4 additional Fury][].", ua = "Перетворює вас на демонічну форму протягом $d, збільшуючи поточне здоров'я на $s2%, зцілюючи на цю величину й збільшуючи Броню на $s8%$?s235893[. Універсальність збільшено на $s5%][]$?s321067[. У перетвореному стані «Перелом» генерує один додатковий Малий уламок душі][]$?s321068[ і $s4 додаткової Люті][]." },
    { en = "Strike $?a206416[your primary target for $<firstbloodDmg> Chaos damage and ][]nearby enemies for $<baseDmg> Physical damage$?s320398[, and increase your chance to dodge by $193311s1% for $193311d.][. Deals reduced damage beyond $199552s1 targets.]", ua = "Уражає $?a206416[вашу основну ціль на $<firstbloodDmg> шкоди від Хаосу та ][]довколишніх ворогів на $<baseDmg> фізичної шкоди$?s320398[ і збільшує ваш шанс ухилитися на $193311s1% протягом $193311d.][. Завдає зменшеної шкоди понад $199552s1 цілей.]" },
    { en = "Leap through the air toward a targeted location, dealing $189112s1 Fire damage to all enemies within $189112a1 yards.", ua = "Стрибок у повітрі до вказаного місця, завдаючи $189112s1 шкоди вогнем усім ворогам у межах $189112a1 м." },
    { en = "Increases your Mana regeneration rate and maximum Mana by ${$m1}.1%.\n\n\n\nArcane Charges increase the damage of Arcane Blast by an additional ${$m2}.1% and Arcane Barrage by ${$m3}.1%.\n\n\n\nIncreases all other Arcane damage by ${$s5}.1%", ua = "Збільшує швидкість відновлення мани та максимальну Ману на ${$m1}.1%.\n\n\n\nАрканні заряди збільшують шкоду «Арканного удару» додатково на ${$m2}.1% та «Арканного шквалу» на ${$m3}.1%.\n\n\n\nЗбільшує всю іншу арканну шкоду на ${$s5}.1%" },
    { en = "Hurls a harpoon at an enemy, rooting them in place for $190927d and pulling you to them.", ua = "Метає гарпун у ворога, знерухомлюючи його на $190927d і притягуючи вас до нього." },
    { en = "Hurl a ball of energy at the target, dealing $s1 Nature damage.$?a197911[\n\n\n\n|cFFFFFFFFGenerates ${$m2/10} Astral Power.|r][]", ua = "Метає в ціль кулю енергії, завдаючи $s1 шкоди від Природи.$?a197911[\n\n\n\n|cFFFFFFFFГенерує ${$m2/10} Астральної сили.|r][]" },
    { en = "Calls down waves of falling stars upon enemies within $50286A1 yds, dealing $<damage> Astral damage over $d. Multiple uses of this ability may overlap.$?s327541[\n\n\n\nExtends the duration of active Moonfires and Sunfires by $327541s1 sec.][]", ua = "Прикликає хвилі падучих зірок на ворогів у радіусі $50286A1 м, завдаючи $<damage> Астральної шкоди протягом $d. Численні застосування цієї здібності можуть накладатися.$?s327541[\n\n\n\nПодовжує тривалість активних «Місячних вогнів» і «Сонячних вогнів» на $327541s1 сек.][]" },
    { en = "Summons a totem at the target location that erupts dealing $383061s1 Fire damage and applying Flame Shock to $383061s2 enemies within $383061A1 yards. Continues hurling liquid magma at a random nearby target every $192226t1 sec for $d, dealing ${$192231s1*(1+($137040s3/100))} Fire damage to all enemies within $192223A1 yards.$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s13 Maelstrom.|r][]", ua = "Прикликає тотем у цільовій точці, що вибухає, завдаючи $383061s1 шкоди вогнем і накладаючи Полум'яний удар на $383061s2 ворогів у межах $383061A1 ярдів. Продовжує метати рідку магму у випадкову ціль поблизу кожні $192226t1 с протягом $d, завдаючи ${$192231s1*(1+($137040s3/100))} шкоди вогнем усім ворогам у межах $192223A1 ярдів.$?a343725[\n\n\n\n|cFFFFFFFFГенерує $343725s13 Вихору.|r][]" },
    { en = "Calls forth a Greater Storm Elemental to hurl gusts of wind at your enemies for $157299d.\n\n\n\nWhile the Storm Elemental is active, casting Lightning Bolt$?a454009[, Tempest,][] or Chain Lightning increases your haste by $263806s1%, stacking up to $263806u times.", ua = "Прикликає Великого штормового елементаля, що метає пориви вітру у ваших ворогів протягом $157299d.\n\n\n\nПоки Штормовий елементаль активний, прочитання Блискавки$?a454009[, Бурі,][] чи Ланцюгової блискавки збільшує ваш Поспіх на $263806s1%, накопичуючись до $263806u разів." },
    { en = "Tosses a hatchet at an enemy, dealing $s1 Physical damage.", ua = "Кидає сокирку у ворога, завдаючи $s1 фізичної шкоди." },
    { en = "Viciously strike an enemy, causing ${$s1*$<mult>} Physical damage.$?s279876[\n\n\n\nHas a $279876s1% chance to hit an additional time and make your next Pistol Shot cost $279876s1% less Energy and deal $279876s2% increased damage.][]\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points; each time it strikes.|r", ua = "Люто вражає ворога, завдаючи ${$s1*$<mult>} фізичної шкоди.$?s279876[\n\n\n\nМає $279876s1% шанс вдарити ще раз і зробити ваш наступний Постріл з пістоля на $279876s1% дешевшим за Енергією та завдати на $279876s2% більше шкоди.][]\n\n\n\n|cFFFFFFFFНадає $s2 $lочко:очки:очок; комбо за кожен удар.|r" },
    { en = "Range of all your ranged abilities is increased by ${$s1}.1% and damage of all abilities increased by ${$s2}.1%.", ua = "Дальність усіх ваших здібностей дального бою збільшено на ${$s1}.1%, а шкоду всіх здібностей збільшено на ${$s2}.1%." },
    { en = "Casting Steady Shot increases your haste by $s1% for $193534d.", ua = "Прочитання «Влучного пострілу» збільшує ваш Поспіх на $s1% на $193534d." },
    { en = "Getting two direct-damage critical strikes in a row with Fire spells will make your next Pyroblast or Flamestrike spell instant cast and apply $s1% additional Ignite damage.", ua = "Два поспіль критичні удари прямої шкоди закляттями Вогню роблять ваше наступне закляття «Піровибух» або «Полум'яний удар» миттєвим і додають $s1% додаткової шкоди «Займання»." },
    { en = "Reach out with necrotic tendrils, dealing $s1 Shadow damage and applying Blood Plague to your target and generating $s3 Bone Shield charges.\n\n\n\n$@spellicon55078 |cFFFFFFFF$@spellname55078|r\n\n$@spelldesc55078", ua = "Тягнеться некротичними лозами, завдаючи $s1 шкоди Тінню й накладаючи Кров'яну чуму на ціль та генеруючи $s3 зарядів Кістяного щита.\n\n\n\n$@spellicon55078 |cFFFFFFFF$@spellname55078|r\n\n$@spelldesc55078" },
    { en = "Blackout Kick, Rising Sun Kick, and Spinning Crane Kick increase damage dealt by your next Fists of Fury by $s1%, stacking up to $195321u times.", ua = "«Затьмарливий удар», «Удар вранішнього сонця» та «Вихровий журавлиний удар» збільшують шкоду вашого наступного «Кулаки люті» на $s1%, накопичуючись до $195321u разів." },
    { en = "Launch a grappling hook and pull yourself to the target location.", ua = "Запускає гак-кішку і підтягує вас до цільового місця." },
    { en = "Agony's damage starts at $s3 stacks and may now ramp up to $s2 stacks.", ua = "Шкода «Агонії» починається з $s3 нашарувань і тепер може зростати до $s2 нашарувань." },
    { en = "Chaos Bolt and Shadowburn increases the damage you deal to the target by $s2% for $196414d.", ua = "«Заряд хаосу» та «Тіньовий опік» збільшують шкоду, яку ви завдаєте цілі, на $s2% на $196414d." },
    { en = "Guardian Spirit also grants you 100% of its effects when used on an ally.", ua = "«Дух-охоронець» також надає вам 100% своїх ефектів, коли застосований на союзника." },
    { en = "Holy Word: Sanctify increases the healing done by Prayer of Healing by $196490s1% for $196490d.", ua = "«Святе слово: Освячення» збільшує зцілення від «Молитви зцілення» на $196490s1% на $196490d." },
    { en = "Slip into the nether when you active Blur, increasing movement speed by $196555s2% and becoming immune to damage for $196555d.", ua = "Ви прослизаєте в Нижній Світ, коли активуєте Розмиття, що збільшує швидкість пересування на $196555s2% і дає несприйнятливість до шкоди на $196555d." },
    { en = "Tiger Palm also applies Eye of the Tiger, dealing $196608o2 Nature damage to the enemy and $196608o1 healing to the Monk over $196608d. Limit 1 target.", ua = "«Тигрова долоня» також накладає «Око тигра», завдаючи $196608o2 шкоди Природою ворогу і зціляючи монаха на $196608o1 протягом $196608d. Ліміт — 1 ціль." },
    { en = "Summon a whirling tornado around you, causing ${$162530s1*$s3} healing over $d to up to $s2 allies within $162530A1 yards.", ua = "Викликає навколо вас вихровий торнадо, що зціляє на ${$162530s1*$s3} протягом $d до $s2 союзників у радіусі $162530A1 ярдів." },
    { en = "Lunge at your enemy as a ghostly wolf, biting them to deal $215802s1 Physical damage.", ua = "Кидається на ворога в подобі примарного вовка, кусаючи його і завдаючи $215802s1 фізичної шкоди." },
    { en = "Your auto attacks have a $s2% chance to generate $196911s2 Energy and store $m1 combo $Lpoint:points;, up to $196911u.\n\n\n\nAttacks that generate combo points can expend those stored to generate additional combo points, up to your maximum.", ua = "Ваші автоатаки мають $s2% шанс згенерувати $196911s2 Енергії та зберегти $m1 $Lочко:очки:очок; комбо, до $196911u.\n\n\n\nАтаки, що генерують очки комбо, можуть витратити збережені, аби згенерувати додаткові очки комбо, до вашого максимуму." },
    { en = "When you heal with Penance, everyone with your Atonement is healed for $s2.", ua = "Коли ви зцілюєте «Покаянням», кожен із вашим «Спокутуванням» зціляється на $s2." },
    { en = "You gain:\n\n\n\n$@spellicon131768 $@spellname131768\n\n$@spelldesc131768\n\n\n\nYou also learn:\n\n\n\n$@spellicon1822 $@spellname1822\n\n$@spellicon1079 $@spellname1079\n\n$@spellicon106785 $@spellname106785\n\n$@spellicon22570 $@spellname22570\n\n\n\nYour energy regeneration is increased by $s2%.", ua = "Ви отримуєте:\n\n\n\n$@spellicon131768 $@spellname131768\n\n$@spelldesc131768\n\n\n\nТакож ви вивчаєте:\n\n\n\n$@spellicon1822 $@spellname1822\n\n$@spellicon1079 $@spellname1079\n\n$@spellicon106785 $@spellname106785\n\n$@spellicon22570 $@spellname22570\n\n\n\nВідновлення вашої енергії збільшено на $s2%." },
    { en = "Sprays shurikens at all enemies within $A1 yards, dealing ${$s1*$<CAP>/$AP} Physical damage$?a277953[ and reducing movement speed by $206760s1% for $206760d]?a428387[ and increasing movement speed by $428389s1% for $428389d when striking $428387s1 or more enemies][]. Deals reduced damage beyond $s4 targets.$?s319951[\n\n\n\nCritical strikes with Shuriken Storm apply Find Weakness for $319949s1 sec.][]\n\n\n\n|cFFFFFFFFAwards $s2 combo $lpoint:points; per target hit.|r", ua = "Розпорошує сюрикени по всіх ворогах у межах $A1 ярдів, завдаючи ${$s1*$<CAP>/$AP} фізичної шкоди$?a277953[ і знижуючи швидкість пересування на $206760s1% на $206760d]?a428387[ і збільшуючи вашу швидкість пересування на $428389s1% на $428389d при ураженні $428387s1 чи більше ворогів][]. Завдає зменшеної шкоди понад $s4 цілей.$?s319951[\n\n\n\nКритичні удари Шквалом сюрикенів накладають Пошук слабкості на $319949s1 с.][]\n\n\n\n|cFFFFFFFFНадає $s2 $lочко:очки:очок; комбо за кожну уражену ціль.|r" },
    { en = "Creates a surge of water that flows forward, healing friendly targets in a wide arc in front of you for $197997s1.", ua = "Здіймає потік води, що тече вперед і зцілює дружні цілі в широкій дузі перед вами на $197997s1." },
    { en = "Calls forth a Greater Fire Elemental to rain destruction on your enemies for $188592d. \n\n\n\nWhile the Fire Elemental is active, Flame Shock deals damage ${100*(1/(1+$188592s2/100)-1)}% faster, and newly applied Flame Shocks last $188592s3% longer.", ua = "Прикликає Великого вогняного елементаля, що сіє руйнування на ваших ворогів протягом $188592d.\n\n\n\nПоки вогняний елементаль активний, Полум'яний шок завдає шкоди на ${100*(1/(1+$188592s2/100)-1)}% швидше, а нові накладення Полум'яного шоку тривають на $188592s3% довше." },
    { en = "While Feral Spirits are active, Chain Lightning and Crash Lightning causes your wolves to attack all nearby enemies for $<damage> Physical damage every $198486t1 sec for the next $198486d.", ua = "Поки активні Дикі духи, Ланцюгова блискавка та Нищівна блискавка змушують ваших вовків атакувати всіх ворогів поблизу, завдаючи $<damage> фізичної шкоди кожні $198486t1 с протягом $198486d." },
    { en = "Reduces all damage taken by $212800s3% for $212800d.", ua = "Зменшує всю отриману шкоду на $212800s3% протягом $212800d." },
    { en = "Summons a totem at the target location with ${$m2*$MHP/100} health for $d. ${$m3*$SP/100} damage from each attack against allies within $?s382201[${$198839s1*(1+$382201s3/100)}.1][$198839s1] yards of the totem is redirected to the totem.", ua = "Прикликає тотем у цільовій точці з ${$m2*$MHP/100} здоров'я на $d. ${$m3*$SP/100} шкоди від кожної атаки по союзниках у межах $?s382201[${$198839s1*(1+$382201s3/100)}.1][$198839s1] ярдів від тотема перенаправляється на тотем." },
    { en = "When you kill a target, its soul bursts into flames, dealing ${$199581s1*(1+$s2/100)} Shadowflame damage to nearby enemies. Deals reduced damage beyond $s4 targets.", ua = "Коли ви вбиваєте ціль, її душа спалахує полум'ям, завдаючи ${$199581s1*(1+$s2/100)} шкоди тіньовим полум'ям ворогам поблизу. Завдає зменшеної шкоди понад $s4 цілей." },
    { en = "Wild Call has a $s1% increased chance to reset the cooldown of Barbed Shot.", ua = "Дикий поклик має на $s1% більший шанс скинути перезарядження Зазубреного пострілу." },
    { en = "You can sense nearby treasure, making it appear on the minimap. Lasts $d.", ua = "Ви відчуваєте скарби поблизу, і вони з'являються на мінікарті. Триває $d." },
    { en = "Every third Healing Wave heals for an additional $s1%.", ua = "Кожна третя Хвиля зцілення зцілює на додаткові $s1%." },
    { en = "Holy Light, Flash of Light, and Judgment have a chance to grant you Power of the Silver Hand, increasing the healing of your next Holy Shock by $200656s1% of all damage and effective healing you do within the next $200656d, up to a maximum of ${$MHP*$s1/100}.", ua = "Святе світло, Спалах світла та Присуд мають шанс дарувати вам Могутність Срібної Длані, збільшуючи зцілення вашого наступного Святого шоку на $200656s1% від усієї шкоди та дієвого зцілення, що ви завдаєте протягом $200656d, до максимуму в ${$MHP*$s1/100}." },
    { en = "A quick, efficient plea to heal an ally for $s1.", ua = "Швидке, дієве благання, що зцілює союзника на $s1." },
    { en = "Unleashes the rage of Ursoc for $d, preventing $s3% of all damage you take, increasing your damage done by $s5%, granting you $s3% leech, and reflecting $219432s1 Nature damage back at your attackers.", ua = "Вивільняє лють Урсока на $d, відвертаючи $s3% усієї отриманої вами шкоди, збільшуючи завдану вами шкоду на $s5%, даруючи вам $s3% висмоктування та відбиваючи $219432s1 шкоди від сил природи назад у нападників." },
    { en = "Summon a herd of stampeding animals from the wilds around you that deal ${$201594s1*3} Physical damage to your enemies over $d.", ua = "Прикликає із дикого краю навколо вас табун тварин, що мчить і завдає вашим ворогам ${$201594s1*3} фізичної шкоди протягом $d." },
    { en = "Stormstrike has a $h.1% chance to reset the cooldown of Stormstrike$?a319930[ and cause your next Stormstrike to deal $319930s1% additional damage as Nature damage][].", ua = "Штормовий удар має $h.1% шанс скинути перезарядження Штормового удару$?a319930[ і зробити так, щоб ваш наступний Штормовий удар завдав на $319930s1% додаткової шкоди у вигляді шкоди Природою][]." },
    { en = "Strikes all nearby enemies with a massive slash, inflicting $s2 Physical damage.$?a231063[ Deals $231063s1% increased damage against bleeding targets.][]$?a405300[ Applies the Bleed from Thrash.][] Deals reduced damage beyond $s3 targets.$?a5487[][\n\n\n\n|cFFFFFFFFAwards $s1 combo $lpoint:points;.|r]", ua = "Вражає всіх ворогів поблизу потужним розтином, завдаючи $s2 фізичної шкоди.$?a231063[ Завдає на $231063s1% більше шкоди цілям, що кровоточать.][]$?a405300[ Накладає Кровотечу від Молотіння.][] Завдає зменшеної шкоди понад $s3 цілей.$?a5487[][\n\n\n\n|cFFFFFFFFНадає $s1 $lочко:очки:очок; комбо.|r]" },
    { en = "Your next $n Starfires are instant cast and generate $s2% increased Astral Power.", ua = "Ваші наступні $n Зоряних вогнів миттєві та генерують на $s2% більше Астральної сили." },
    { en = "Enveloping Mist transforms $s1% of its remaining periodic healing into a Dome of Mist when dispelled.\n\n\n\n$@spellicon205655 $@spellname205655\n\nAbsorbs damage. All healing received by the Monk increased by $205655m2%. Lasts $205655d.", ua = "Огортаючий туман перетворює $s1% свого залишкового періодичного зцілення на Купол туману при розвіюванні.\n\n\n\n$@spellicon205655 $@spellname205655\n\nПоглинає шкоду. Усе зцілення, яке отримує монах, збільшено на $205655m2%. Триває $205655d." },
    { en = "Increases Astral Power generated by Solar Wrath and Lunar Strike by $s1%.", ua = "Збільшує Астральну силу, що генерують Сонячний гнів і Місячний удар, на $s1%." },
    { en = "Grants ${$m1/10} Astral Power every $t1 sec.", ua = "Дарує ${$m1/10} Астральної сили кожні $t1 с." },
    { en = "Starsurge has a chance to summon the Spirit of Goldrinn, which immediately deals $203001s1 Arcane damage to the target.", ua = "«Зоряний сплеск» має шанс прикликати Дух Ґолдринна, який негайно завдає цілі $203001s1 арканної шкоди." },
    { en = "If you have not cast Fireball for $203278d, your next Fireball will deal $m1% increased damage with a $m2% reduced cast time.", ua = "Якщо ви не творили «Вогняну кулю» протягом $203278d, ваша наступна «Вогняна куля» завдасть на $m1% більше шкоди зі скороченим на $m2% часом прочитання." },
    { en = "Your tattoos reduce $?$s338682[magic damage taken by $s1% and physical damage taken by $s2%.][all damage taken by $s1%.]", ua = "Ваші татуювання зменшують $?$s338682[отриману магічну шкоду на $s1% та отриману фізичну шкоду на $s2%.][усю отриману шкоду на $s1%.]" },
    { en = "Your auto attacks deal an additional $203796s1 $@spelldesc395041 damage and generate $203796m2-$203796M2 Fury.", ua = "Ваші автоатаки завдають додаткові $203796s1 $@spelldesc395041 шкоди й генерують $203796m2-$203796M2 Люті." },
    { en = "Apply Lifebloom, Rejuvenation, Wild Growth, and Regrowth's heal over time effect to an ally.", ua = "Накладає на союзника поступове зцілення від «Цвіту життя», «Омолодження», «Дикого росту» та «Відростання»." },
    { en = "Surge with fel power, increasing your Armor by ${$203819s2*$AGI/100}$?s321028[, and your Parry chance by $203819s1%, for $203819d][].", ua = "Наповнюється силою Скверни, збільшуючи вашу Броню на ${$203819s2*$AGI/100}$?s321028[ та шанс Парирування на $203819s1% на $203819d][]." },
    { en = "Increases Armor by ${$s1}.1% of your Agility. Armor bonus is doubled while Demon Spikes is active.$?s321299[\n\n\n\nAlso increases your attack power by ${$321299s1}.1%.][]", ua = "Збільшує Броню на ${$s1}.1% вашої Спритності. Бонус до Броні подвоюється, поки активні Демонічні шипи.$?s321299[\n\n\n\nТакож збільшує вашу силу атаки на ${$321299s1}.1%.][]" },
    { en = "Shear shatters the target's soul, leaving a Lesser Soul Fragment behind for $204255d.\n\n\n\nConsuming a Lesser Soul Fragment heals you for $s2% of all damage taken in the last $s4 sec, minimum $s3% of maximum health.", ua = "«Розсічення» розбиває душу цілі, лишаючи по собі Малий уламок душі на $204255d.\n\n\n\nСпоживання Малого уламка душі зцілює вас на $s2% усієї шкоди, отриманої за останні $s4 сек., але не менш ніж на $s3% максимального здоров'я." },
    { en = "Throw a demonic glaive at the target, dealing $346665s1 Physical damage. The glaive can ricochet to $?$s320386[${$346665x1-1} additional enemies][an additional enemy] within 10 yards. Generates high threat.", ua = "Кидає демонічну глефу в ціль, завдаючи $346665s1 фізичної шкоди. Глефа може рикошетити до $?$s320386[${$346665x1-1} додаткових ворогів][ще одного ворога] у межах 10 ярдів. Створює високу загрозу." },
    { en = "Killing a target will sometimes shatter their soul, leaving a Soul Fragment behind for $203795d.\n\n\n\nThe Soul Fragment will be consumed when you approach it, healing you for $210042s1 health.\n\n\n\nConsuming a Lesser Soul Fragment heals you for $203783s2% of all damage taken in the last $203783s4 sec, minimum $203783s3% of maximum health.\n\n\n\nConsuming a Demon's soul will grant you $163073s1% increased damage for $163073d.", ua = "Убивство цілі іноді розбиває її душу, лишаючи по собі Уламок душі на $203795d.\n\n\n\nУламок душі споживається, коли ви наближаєтесь до нього, зцілюючи вас на $210042s1 здоров'я.\n\n\n\nСпоживання Малого уламка душі зцілює вас на $203783s2% усієї шкоди, отриманої за останні $203783s4 сек., але не менш ніж на $203783s3% максимального здоров'я.\n\n\n\nСпоживання душі демона дає вам на $163073s1% більше шкоди протягом $163073d." },
    { en = "Thunderstorm now can be cast on allies within $204406r yards, reduces enemies movement speed by $204408s3%, and knocks enemies $s2% further.", ua = "«Грозу» тепер можна творити на союзників у межах $204406r ярдів, вона знижує швидкість пересування ворогів на $204408s3% і відкидає ворогів на $s2% далі." },
    { en = "Casting Pyroblast or Flamestrike while Hot Streak is active has an $s1% chance to instantly reactivate Hot Streak.", ua = "Творення «Піровибуху» чи «Вогняного удару», поки активна «Гаряча смуга», має $s1% шанс миттєво знову активувати «Гарячу смугу»." },
    { en = "Fireball and Pyroblast apply Conflagration to the target, dealing an additional $226757o1 Fire damage over $226757d.\n\n\n\nEnemies affected by either Conflagration or Ignite have a $s1% chance to flare up and deal $205345s1 Fire damage to nearby enemies.", ua = "«Вогняна куля» та «Піровибух» накладають на ціль «Пожежу», завдаючи додатково $226757o1 шкоди вогнем протягом $226757d.\n\n\n\nВороги під дією «Пожежі» або «Займання» мають $s1% шанс спалахнути й завдати $205345s1 шкоди вогнем ворогам поблизу." },
    { en = "Whenever you attempt to chill a target, you gain Bone Chilling, increasing spell damage you deal by ${$m1/10}.1% for $205766d, stacking up to $205766u times.", ua = "Щоразу, коли ви намагаєтесь охолодити ціль, ви отримуєте «Крижаний холод у кістках», що збільшує вашу шкоду заклять на ${$m1/10}.1% протягом $205766d і накопичується до $205766u разів." },
    { en = "Flamestrike leaves behind a patch of flames that burns enemies within it for ${$205470d*$205472s1} Fire damage over $205470d. Deals reduced damage beyond $205472s2 targets.", ua = "«Вогняний удар» лишає по собі поле полум'я, що обпалює ворогів у ньому на ${$205470d*$205472s1} шкоди вогнем протягом $205470d. Завдає зменшеної шкоди понад $205472s2 цілей." },
    { en = "Shadow Bolt$?s264178[ and Demonbolt have][ has] a $s3% chance to make your next Call Dreadstalkers cost $s1 fewer Soul $LShard:Shards; and have no cast time.", ua = "Тіньова стріла$?s264178[ і Демонічна стріла мають][ має] $s3% шанс зробити так, що ваш наступний Виклик жахострахів коштуватиме на $s1 менше $LСколка душі:Сколків душі; та не матиме часу прочитання." },
    { en = "Places a phantom singularity above the target, which consumes the life of all enemies within $205246A2 yards, dealing ${8*$205246s2} damage over $d, healing you for ${$205246e2*100}% of the damage done.", ua = "Розміщує примарну сингулярність над ціллю, яка поглинає життя всіх ворогів у межах $205246A2 ярдів, завдаючи ${8*$205246s2} шкоди протягом $d і зцілюючи вас на ${$205246e2*100}% завданої шкоди." },
    { en = "Conflagrate increases your $?s6353[Soul Fire, ][]$?s196447[Channel Demonfire, ][]$?a445465[Wither][Immolate], Incinerate, and Conflagrate damage to the target by $265931s1% for $265931d.", ua = "Займання підвищує шкоду, яку завдають цілі ваші $?s6353[Вогонь душі, ][]$?s196447[Спрямування демонічного вогню, ][]$?a445465[В'янення][Спопеляння], Спалювання і Займання, на $265931s1% протягом $265931d." },
    { en = "Reduces the Fury cost of Chaos Nova by $s2% and its cooldown by ${-$m1/600}%.", ua = "Знижує вартість «Нови хаосу» в люті на $s2%, а її перезарядження — на ${-$m1/600}%." },
    { en = "Chaos Strike has a chance to spawn a Lesser Soul Fragment. Consuming any Soul Fragment grants $s1 Fury.", ua = "«Удар хаосу» має шанс породити Малий уламок душі. Споживання будь-якого Уламка душі дає $s1 люті." },
    { en = "Drains $o1 health from the target over $d. The damage they deal to you is reduced by $s2% for the duration and $458687d after channeling it fully.\n\n\n\nYou can move, parry, dodge, and use defensive abilities while channeling this ability.\n\n\n\n|cFFFFFFFFGenerates ${$s3*4/10} additional Runic Power over the duration.|r", ua = "Висмоктує $o1 здоров'я з цілі протягом $d. Шкода, яку вона вам завдає, знижується на $s2% на час дії та на $458687d після повного каналювання.\n\n\n\nПід час каналювання цієї здібності ви можете рухатися, парирувати, ухилятися та застосовувати захисні здібності.\n\n\n\n|cFFFFFFFFСтворює ${$s3*4/10} додаткової рунічної сили за час дії.|r" },
    { en = "Gorefiend's Grasp cooldown is reduced by ${$m1/-1000} sec and it now also Silences enemies for $374776d.", ua = "Перезарядження «Хватки Кровожера» знижується на ${$m1/-1000} сек., і вона тепер також накладає німоту на ворогів на $374776d." },
    { en = "Bursting a Festering Wound deals $s1% more damage, and deals $207267s1 Shadow damage to up to ${$207267i-1} nearby enemies.", ua = "Розрив Гнійної Рани завдає на $s1% більше шкоди й завдає $207267s1 шкоди Тінню до ${$207267i-1} ворогам поблизу." },
    { en = "Strike your target dealing $s2 Shadow damage, applying $s3 Festering Wounds and sending you into an Unholy Frenzy increasing all damage done by $s4% for $d.", ua = "Вражає ціль, завдаючи $s2 шкоди Тінню, накладає $s3 Гнійних Ран і вводить тебе в Нечестиве Шаленство, що збільшує всю завдану шкоду на $s4% протягом $d." },
    { en = "Deals $s2 Shadow damage and causes 1 Festering Wound to burst.", ua = "Завдає $s2 шкоди Тінню й розриває 1 Гнійну Рану." },
    { en = "Causes each of your Virulent Plagues to flare up, dealing $212739s1 Shadow damage to the infected enemy and $212739s2 Shadow damage to foes nearby.\n\n\n\nExtends the duration of Dread Plague and Virulent Plague by ${$137007s11/1000}.1 sec.", ua = "Змушує кожну з твоїх Згубних Пошестей спалахнути, завдаючи $212739s1 шкоди Тінню зараженому ворогу та $212739s2 шкоди Тінню ворогам поблизу.\n\n\n\nПодовжує тривалість Пошесті Жаху та Згубної Пошесті на ${$137007s11/1000}.1 сек." },
    { en = "Each target healed by Efflorescence is healed for an additional $207386o1 over $207386d.", ua = "Кожна ціль, зцілена Розквітом, додатково зцілюється на $207386o1 протягом $207386d." },
    { en = "Summons a totem at the target location for $d. All allies within $?s382201[${$207495s1*(1+$382201s3/100)}][$207495s1] yards of the totem gain $207498s1% increased health. If an ally dies, the totem will be consumed to allow them to Reincarnate with $207553s1% health and mana.\n\n\n\nCannot reincarnate an ally who dies to massive damage.", ua = "Прикликає тотем у вказане місце на $d. Усі союзники в межах $?s382201[${$207495s1*(1+$382201s3/100)}][$207495s1] ярдів від тотема отримують на $207498s1% більше здоров'я. Якщо союзник гине, тотем буде спожито, щоб дозволити йому Переродитися з $207553s1% здоров'я і мани.\n\n\n\nНе можна переродити союзника, який гине від масштабної шкоди." },
    { en = "All Sigils are now placed at your location.", ua = "Усі Сигіли тепер розміщуються на твоєму місці." },
    { en = "Hurls frigid ice at the target, dealing $s1 Frost damage and causing your next Frost Shock to deal $s2% increased damage, damage $s4 additional $Ltarget:targets;, and generate $343725s7 additional Maelstrom.\n\n\n\n|cFFFFFFFFGenerates $343725s8 Maelstrom.|r", ua = "Кидає в ціль крижаний лід, завдаючи $s1 шкоди від холоду і роблячи так, що ваш наступний Крижаний розряд завдасть на $s2% більше шкоди, вразить $s4 додаткову $Lціль:цілей;, і згенерує $343725s7 додаткового Виру.\n\n\n\n|cFFFFFFFFГенерує $343725s8 Виру.|r" },
    { en = "Impales the target for $s1 Chaos damage and stuns them for $d.", ua = "Настромлює ціль, завдаючи $s1 шкоди Хаосом, і приголомшує її на $d." },
    { en = "Brings all dead party members back to life with $s1% health and mana. Cannot be cast when in combat.", ua = "Повертає до життя всіх мертвих членів групи з $s1% здоров'я та мани. Не можна творити в бою." },
    { en = "Returns all dead party members to life with $s1% of maximum health and mana. Not castable in combat.", ua = "Повертає до життя всіх мертвих членів групи з $s1% від максимального здоров'я та мани. Не творити в бою." },
    { en = "Returns all dead party members to life with $s1% of maximum health and mana.  Cannot be cast when in combat.", ua = "Повертає до життя всіх мертвих членів групи з $s1% від максимального здоров'я та мани.  Не можна творити в бою." },
    { en = "Returns all dead party members to life with $s1% of maximum health and mana. Cannot be cast when in combat.", ua = "Повертає до життя всіх мертвих членів групи з $s1% від максимального здоров'я та мани. Не можна творити в бою." },
    { en = "Attack all nearby enemies in a flurry of strikes, inflicting $s1 Physical damage to nearby enemies$?s459868[ and $459870o1 damage over $459870d][]. Deals reduced damage beyond $s3 targets.$?s294029[\n\n\n\nReduces the remaining cooldown on Wildfire Bomb by $<cdr> sec for each target hit, up to ${($s3*$s2)/1000}.1 sec.][]", ua = "Атакує всіх ворогів поблизу шквалом ударів, завдаючи $s1 фізичної шкоди довколишнім ворогам$?s459868[ та $459870o1 шкоди протягом $459870d][]. Завдає зменшеної шкоди понад $s3 цілей.$?s294029[\n\n\n\nЗменшує залишок перезарядження Бомби дикого вогню на $<cdr> с за кожну вражену ціль, до ${($s3*$s2)/1000}.1 с.][]" },
    { en = "A short-range shot that deals $s1 damage, removes all harmful damage over time effects, and incapacitates the target for $d.  Any damage caused will remove the effect. Turns off your attack when used.$?s321468[\n\n\n\nTargets incapacitated by Scatter Shot deal $321469s1% less damage to you for $321469d after the effect ends.][]", ua = "Постріл ближньої дії, що завдає $s1 шкоди, знімає всі шкідливі ефекти шкоди в часі та знешкоджує ціль на $d.  Будь-яка завдана шкода зніме ефект. Вимикає вашу атаку при застосуванні.$?s321468[\n\n\n\nЦілі, знешкоджені Розсіювальним пострілом, завдають вам на $321469s1% менше шкоди протягом $321469d після завершення ефекту.][]" },
    { en = "Focuses Holy energy to deliver a powerful weapon strike that deals $s1 $?s403664[Holystrike][Holy] damage, and restores $408394s1% of your maximum health.\n\n\n\nDamage is increased by $s2% when used against a stunned target.", ua = "Зосереджує святу енергію для потужного удару зброєю, що завдає $s1 шкоди $?s403664[святим ударом][від Світла] та відновлює $408394s1% вашого максимального здоров'я.\n\n\n\nШкода зростає на $s2%, коли застосовується проти приголомшеної цілі." },
    { en = "Every Soul Shard you spend has a $?s137043[$s1%]?s137046[$s3%][$s2%] chance to be refunded.", ua = "Кожен витрачений Сколок душі має $?s137043[$s1%]?s137046[$s3%][$s2%] шанс бути поверненим." },
    { en = "You have a chance equal to your critical strike chance to be healed for an additional $s1% of the amount healed.", ua = "Ти маєш шанс, що дорівнює твоєму шансу критичного удару, отримати додатково $s1% від обсягу зцілення." },
    { en = "Spinning Crane Kick's damage is increased by $220358s1% for each unique target you've struck in the last $220358d with Tiger Palm, Blackout Kick, or Rising Sun Kick. \n\n\n\nStacks up to $228287i times and only applies to the primary target of each effect.", ua = "Шкода Обертового удару журавля зростає на $220358s1% за кожну унікальну ціль, яку ви вразили за останні $220358d Тигрячою долонею, Приголомшливим ударом або Ударом висхідного сонця. \n\n\n\nНакопичується до $228287i разів і застосовується лише до основної цілі кожного ефекту." },
    { en = "Increases your Stamina by $s1% while wearing only leather armor.", ua = "Збільшує твою Витривалість на $s1%, поки ти носиш лише шкіряну броню." },
    { en = "Viciously strike an enemy and all other enemies in front of you for $228478s1 Physical damage and heal yourself for $s4. Deals reduced damage beyond $228478s2 targets.\n\n\n\nConsumes up to $s3 Soul Fragments, increasing damage by $228478s3% per fragment consumed.", ua = "Люто вражає ворога й усіх інших ворогів перед тобою, завдаючи $228478s1 фізичної шкоди, та зцілює тебе на $s4. Завдає зменшеної шкоди понад $228478s2 цілей.\n\n\n\nСпоживає до $s3 Фрагментів Душі, збільшуючи шкоду на $228478s3% за кожен спожитий фрагмент." },
    { en = "While in Moonkin Form, single-target attacks against you have a $s1% chance make your next Starfire instant.", ua = "У Подобі Місячного Змія атаки по одній цілі проти тебе мають $s1% шанс зробити твій наступний Зоряний Вогонь миттєвим." },
    { en = "You gain Dodge equal to $s1% of your Critical Strike from gear.", ua = "Ви отримуєте Ухилення, що дорівнює $s1% вашого Критичного удару зі спорядження." },
    { en = "Vivify healing is increased by $s1%.", ua = "Зцілення від «Оживлення» збільшено на $s1%." },
    { en = "Casting Flash of Light or Holy Light grants $s1 Holy Power.", ua = "Творіння «Спалаху світла» чи «Святого світла» дає $s1 Святої сили." },
    { en = "Soulstone may be used to instantly resurrect a dead target.", ua = "«Камінь душі» можна використати, щоб миттєво воскресити мертву ціль." },
    { en = "Shield Block has ${$s1+1} charges.", ua = "«Блок щитом» має ${$s1+1} заряди." },
    { en = "Call upon the Light and begin a crusade, increasing your damage, healing and critical strike chance by $s1%, and Haste by $s3%.\n\n\n\nEach Holy Power spent during Crusade increases Haste by an additional ${$s3/10}%.\n\n\n\nMaximum $u stacks.", ua = "Прикликайте Світло й розпочніть похід, збільшуючи вашу шкоду, зцілення та шанс критичного удару на $s1%, а Поспіх — на $s3%.\n\n\n\nКожна Свята сила, витрачена під час Походу, збільшує Поспіх ще на ${$s3/10}%.\n\n\n\nМаксимум $u стаків." },
    { en = "Assume a Shadowform, increasing your spell damage dealt by $s1%.", ua = "Ви набуваєте Тіньової форми, збільшуючи завдану вами шкоду закляттями на $s1%." },
    { en = "All of your snare effects reduce the target's movement speed by an additional $s1%.", ua = "Усі ваші ефекти сповільнення додатково зменшують швидкість пересування цілі на $s1%." },
    { en = "Arcane Barrage slows enemies by $236299s1% and increases your movement speed by $236298s1% for $236299d.", ua = "«Арканний обстріл» сповільнює ворогів на $236299s1% і збільшує вашу швидкість пересування на $236298s1% на $236299d." },
    { en = "Dragon's Breath always critically strikes, deals $s2% increased critical strike damage, and contributes to Hot Streak.", ua = "«Драконове дихання» завжди завдає критичного удару, завдає на $s2% більше критичної шкоди й додається до «Гарячої серії»." },
    { en = "Metamorphosis grants $s2% versatility and its cooldown is reduced by ${$m1/-1000} sec.", ua = "«Метаморфоза» дає $s2% універсальності, а її перезарядження зменшено на ${$m1/-1000} сек." },
    { en = "When Scorch damages an enemy below $1254311s2% health, it increases your movement speed by $236060s1% for $236060d.", ua = "Коли «Обпалення» завдає шкоди ворогу зі здоров'ям нижче $1254311s2%, воно збільшує вашу швидкість пересування на $236060s1% на $236060d." },
    { en = "Every $t4 sec, the cast time of your next Chain Heal is reduced by $236502m1%, and jump distance increased by $236502m2%. Maximum of $m2 charges.", ua = "Кожні $t4 сек. час творіння вашого наступного «Ланцюгового зцілення» зменшується на $236502m1%, а дальність перестрибування збільшується на $236502m2%. Максимум $m2 заряди." },
    { en = "Each time Blizzard deals damage, Frozen Orb's cooldown is reduced by 0.5 sec.", ua = "Щоразу, коли «Хуртовина» завдає шкоди, перезарядження «Замерзлої кулі» зменшується на 0.5 сек." },
    { en = "Hurls a fire trap to the target location that explodes when an enemy approaches, causing $236777s2 Fire damage and knocking all enemies away. Limit $s2. Trap will exist for $236775d.$?s321468[\n\n\n\nTargets knocked back by High Explosive Trap deal $321469s1% less damage to you for $321469d after being knocked back.][]", ua = "Кидає вогняну пастку у вказане місце, що вибухає, коли наближається ворог, завдаючи $236777s2 шкоди від вогню і відкидаючи всіх ворогів. Ліміт $s2. Пастка існуватиме $236775d.$?s321468[\n\n\n\nЦілі, відкинуті Високовибуховою пасткою, завдають вам на $321469s1% менше шкоди протягом $321469d після відкидання.][]" },
    { en = "Your Armor is increased by $s1% and Stamina increased by $s3%.", ua = "Вашу Броню збільшено на $s1%, а Витривалість — на $s3%." },
    { en = "$?s262161[Warbreaker][Colossus Smash] increases your Haste by $s1%, or by $s2% if $?s262161[any][the] target is below $s3% health. Lasts for the duration of $?s262161[Warbreaker][Colossus Smash].", ua = "$?s262161[Зброєлам][Удар колоса] підвищує ваш Поспіх на $s1% або на $s2%, якщо $?s262161[будь-яка][ця] ціль має менш ніж $s3% здоров'я. Триває протягом дії $?s262161[Зброєлама][Удару колоса]." },
    { en = "Hurls a Phoenix that deals $257542s2 Fire damage to the target and reduced damage to other nearby enemies.$?a343222[\n\n\n\nAlways deals a critical strike.][]", ua = "Кидає Фенікса, що завдає $257542s2 шкоди від вогню цілі та зменшеної шкоди іншим ворогам поблизу.$?a343222[\n\n\n\nЗавжди завдає критичного удару.][]" },
    { en = "Fires several missiles, hitting your current target and all enemies within $A2 yards for $s2 Physical damage. Deals reduced damage beyond $2643s1 targets.$?s260393[\n\n\n\nMulti-Shot has a $260393h% chance to reduce the cooldown of Rapid Fire by ${$260393m1/10}.1 sec.][]", ua = "Випускає кілька снарядів, вражаючи вашу поточну ціль і всіх ворогів у межах $A2 ярдів на $s2 фізичної шкоди. Завдає зменшеної шкоди понад $2643s1 цілей.$?s260393[\n\n\n\nМножинний постріл має $260393h% шанс зменшити перезарядження Швидкого вогню на ${$260393m1/10}.1 с.][]" },
    { en = "Barbed Shot increases your critical strike chance by $257946s1% for $257946d, stacking up to $s2 $Ltime:times;.", ua = "Колючий постріл підвищує ваш шанс критичного удару на $257946s1% протягом $257946d, накопичуючись до $s2 $Lразу:разів;." },
    { en = "Demon's Bite deals $s2% more damage and generates $s3 to $s4 additional Fury.", ua = "«Укус демона» завдає на $s2% більше шкоди й дає від $s3 до $s4 додаткової Люті." },
    { en = "Unleash a torrent of Fel energy, rapidly consuming Fury to inflict $258926s1 Chaos damage to all enemies within $258926A1 yds, lasting $d or until Fury is depleted. Deals reduced damage beyond $258926s2 targets.", ua = "Вивільняє потік енергії Скверни, швидко витрачаючи Лють, щоб завдати $258926s1 шкоди Хаосом усім ворогам у межах $258926A1 ярд(ів) протягом $d або доки не вичерпається Лють. Завдає зменшеної шкоди понад $258926s2 цілей." },
    { en = "A brutal attack that deals $s1 Physical damage and grants you Mongoose Fury.\n\n\n\n|cFFFFFFFFMongoose Fury|r\n\nIncreases the damage of Mongoose Bite by $259388s1% $?s385737[and the chance for Kill Command to reset by $259388s2% ][]for $259388d, stacking up to $259388u times.", ua = "Жорстока атака, що завдає $s1 фізичної шкоди й дарує вам Лють мангуста.\n\n\n\n|cFFFFFFFFЛють мангуста|r\n\nЗбільшує шкоду Укусу мангуста на $259388s1% $?s385737[та ймовірність скидання Наказу вбити на $259388s2% ][]протягом $259388d, накопичуючись до $259388u разів." },
    { en = "Aimed Shot deals $s3% bonus damage to targets who are above $s1% health.", ua = "«Прицільний постріл» завдає на $s3% більше шкоди цілям, у яких понад $s1% здоров'я." },
    { en = "When Aimed Shot strikes an enemy affected with your Serpent Sting, it spreads Serpent Sting to $s3 enemies nearby.\n\n\n\nSerpent Sting's damage over time is increased by $s2%.", ua = "Коли «Прицільний постріл» влучає у ворога під дією твого «Зміїного жала», воно поширюється на $s3 ворогів поблизу.\n\n\n\nПеріодична шкода від «Зміїного жала» збільшується на $s2%." },
    { en = "Kill Shot strikes up to $s1 additional targets while Coordinated Assault is active.", ua = "«Добивальний постріл» уражає до $s1 додаткових цілей, доки активний «Злагоджений напад»." },
    { en = "Rapid Fire's damage is increased by $s1%.", ua = "Шкода від «Швидкого вогню» збільшується на $s1%." },
    { en = "Bash an enemy's skull, dealing $s1 Physical damage.\n\n\n\nSkullsplitter causes your Rend and Deep Wounds on the target to bleed out $427040s1% faster for $427040d.\n\n\n\n|cFFFFFFFFGenerates ${$s2/10} Rage.|r", ua = "Розтрощує ворогові череп, завдаючи $s1 фізичної шкоди.\n\n\n\n«Черепокол» змушує твої ефекти «Роздирання» та «Глибокі рани» на цілі кровоточити на $427040s1% швидше протягом $427040d.\n\n\n\n|cFFFFFFFFДає ${$s2/10} Люті.|r" },
    { en = "Your next $s4 damaging single-target abilities hit $s1 additional $Ltarget:targets; within 8 yds for $s2% damage. Lasts $d.", ua = "Ваші наступні $s4 здібності шкоди по одній цілі влучають у $s1 додаткову $Ltarget:targets; в межах 8 ярдів, завдаючи $s2% шкоди. Триває $d." },
    { en = "Blackout Kick costs $s1 fewer Chi.", ua = "«Затьмарливий удар» коштує на $s1 менше Ці." },
    { en = "Smash the ground and shatter the armor of all enemies within $A1 yds, dealing $s1 Physical damage and increasing damage you deal to them by $208086s1% for $208086d.", ua = "Б'є об землю й трощить броню всіх ворогів у межах $A1 ярд(ів), завдаючи $s1 фізичної шкоди й збільшуючи шкоду, яку ти їм завдаєш, на $208086s1% протягом $208086d." },
    { en = "Your Feral Spirits are now imbued with Fire, Frost, or Lightning, increasing your damage dealt with that element by $224127s1%, but now only increase your Physical damage dealt by $224127s3%.", ua = "Твої «Дикі духи» тепер наповнені Вогнем, Морозом чи Блискавкою, збільшуючи шкоду, яку ти завдаєш цією стихією, на $224127s1%, але тепер збільшують твою фізичну шкоду лише на $224127s3%." },
    { en = "You and your pet deal $s8% increased damage and take $s6% reduced damage. This bonus is increased by $459722s1% when you're within $s7 yds of each other.", ua = "Ти та твій улюбленець завдаєте на $s8% більше шкоди й отримуєте на $s6% менше шкоди. Цей бонус збільшується на $459722s1%, коли ви перебуваєте на відстані до $s7 ярд(ів) одне від одного." },
    { en = "Kill Command has an additional $s1% chance to immediately reset its cooldown, increased by $s2% when Kill Command critically strikes a target.\n\n\n\nTip of the Spear's damage bonus is increased up to $s3%, based on your critical strike chance.", ua = "«Наказ убити» має додаткову $s1% імовірність миттєво скинути власне перезарядження, збільшену на $s2%, коли «Наказ убити» завдає цілі критичного удару.\n\n\n\nБонус до шкоди від «Вістря списа» збільшується до $s3% залежно від твоєї ймовірності критичного удару." },
    { en = "Unleashes an explosion of dark energy around your target, dealing $s1 Shadow damage and applying Shadow Word: Pain to your target and ${$s2-1} nearby enemies.\n\n\n\n|cFFFFFFFFGenerates ${$391450s1/100} Insanity.|r", ua = "Вивільняє вибух темної енергії навколо твоєї цілі, завдаючи $s1 шкоди Тінню й накладаючи «Слово тіні: Біль» на твою ціль і ${$s2-1} ворогів поблизу.\n\n\n\n|cFFFFFFFFДає ${$391450s1/100} Божевілля.|r" },
    { en = "Rapidly slash your target for ${$225919sw1+$225921sw1} Physical damage, and shatter $s1 Lesser Soul Fragments from them.\n\n\n\n|cFFFFFFFFGenerates $s4 Fury.|r", ua = "Стрімко січе твою ціль, завдаючи ${$225919sw1+$225921sw1} фізичної шкоди й відколюючи від неї $s1 малих Фрагментів душі.\n\n\n\n|cFFFFFFFFДає $s4 Люті.|r" },
    { en = "Reduces the cooldown of Silence by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Тиші» на ${$s1/-1000} сек." },
    { en = "Command your Felguard to strike into the soul of its enemy, dealing $<damage> Shadow damage.$?c2[\n\n\n\n|cFFFFFFFFGenerates 1 Soul Shard.|r][]", ua = "Накажіть своєму сквернократу вдарити в душу ворога, завдавши $<damage> шкоди Тінню.$?c2[\n\n\n\n|cFFFFFFFFСтворює 1 Уламок душі.|r][]" },
    { en = "Summon a Vilefiend to fight for you for the next $d.", ua = "Прикликає лиху потвору, що битиметься за вас наступні $d." },
    { en = "When you gain your third Arcane Charge, the cost of your next Arcane Blast or Arcane Missiles is reduced by $264774s1%.", ua = "Коли ви отримуєте третій арканний заряд, вартість вашого наступного «Арканного вибуху» чи «Арканних снарядів» зменшується на $264774s1%." },
    { en = "Reduces the cooldown of Shadowfury by ${$s1/-1000} sec and increases its radius by $s2 yards.", ua = "Зменшує перезарядження «Тіньової люті» на ${$s1/-1000} сек і збільшує її радіус на $s2 м." },
    { en = "Heals all allies within $A1 yards for $s1, and applies Renew and $s2 stacks of Prayer of Mending to each of them.\n\n\n\n|cFFFFFFFFCooldown reduced by $s3 sec when you cast Holy Word: Serenity or Holy Word: Sanctify.|r", ua = "Зцілює всіх союзників у межах $A1 м на $s1 і накладає на кожного «Оновлення» та $s2 стосів «Молитви зцілення».\n\n\n\n|cFFFFFFFFПерезарядження зменшується на $s3 сек, коли ви творите «Святе слово: Умиротворення» чи «Святе слово: Освячення».|r" },
    { en = "Harpoon has a ${$m2/-1000} sec reduced cooldown, and deals $271625s1 Physical damage and generates ${($265898s1/5)*$265898d} Focus over $265898d. Killing an enemy that yields experience or honor resets the cooldown of Harpoon.", ua = "Перезарядження «Гарпуна» зменшено на ${$m2/-1000} сек, і він завдає $271625s1 фізичної шкоди та генерує ${($265898s1/5)*$265898d} зосередження протягом $265898d. Убивство ворога, що дає досвід чи честь, скидає перезарядження «Гарпуна»." },
    { en = "Dreadbite causes the target to take $270569s1% additional Shadowflame damage from your spell and abilities for the next $270569d.", ua = "«Жахокус» змушує ціль отримувати на $270569s1% більше шкоди тіньополум'ям від ваших заклять і здібностей наступні $270569d." },
    { en = "Infuse your Felguard with demonic strength and command it to charge your target and unleash a Felstorm that will deal $s2% increased damage.", ua = "Наповнює вашого сквернового вартового демонічною силою і наказує йому налетіти на ціль та здійняти скверношторм, що завдасть на $s2% більше шкоди." },
    { en = "Tear open a portal to the nether above the target location, from which several Bilescourge will pour out of and crash into the ground over $d, dealing $267213s1 Shadow damage to all enemies within $267213A1 yards.", ua = "Розриває портал у Нижній Світ над обраним місцем, з якого протягом $d вихлюпуються кілька жовчоплетей, що врізаються в землю, завдаючи $267213s1 шкоди тінню всім ворогам у межах $267213A1 м." },
    { en = "Tear open a portal to the Twisting Nether for $d. Every time you spend Soul Shards, you will also command demons from the Nether to come out and fight for you.", ua = "Розриває портал у Викручений Нижній Світ на $d. Щоразу, коли ви витрачаєте уламки душі, ви також наказуєте демонам із Нижнього Світу з'явитися і битися за вас." },
    { en = "Your auto attacks have a $s1% chance to reset the cooldown of Blade of Justice.", ua = "Ваші автоатаки мають $s1% шансу скинути перезарядження «Клинка правосуддя»." },
    { en = "Raptor Strike and Mongoose Bite damage increased by $s2%.\n\n\n\nRaptor Strike and Mongoose Bite apply Serpent Sting to your target.\n\n\n\n$@spellicon259491$@spellname259491\n\n$@spelldesc259491", ua = "Шкода Удару раптора й Укусу мангуста збільшена на $s2%.\n\n\n\nУдар раптора й Укус мангуста накладають на вашу ціль Зміїне жало.\n\n\n\n$@spellicon259491$@spellname259491\n\n$@spelldesc259491" },
    { en = "Scorch deals $s2% increased damage and is a guaranteed Critical Strike when the target is below $s1% health.", ua = "«Обпалення» завдає на $s2% більше шкоди і гарантовано наносить критичний удар, коли здоров'я цілі нижче за $s1%." },
    { en = "You and your pet leap to the target and strike it as one, dealing a total of $<damage> Physical damage.$?a1252931[\n\n\n\nFlanking Strike generates $1252931s1 stacks of Tip of the Spear.][]\n\n\n\n|cFFFFFFFFGenerates $s3 Focus.|r", ua = "Ви й ваш улюбленець стрибаєте до цілі й вражаєте її разом, завдаючи загалом $<damage> фізичної шкоди.$?a1252931[\n\n\n\nФланговий удар створює $1252931s1 стос Вістря списа.][]\n\n\n\n|cFFFFFFFFСтворює $s3 Зосередження.|r" },
    { en = "Bear Form gives an additional $s1% Stamina.", ua = "«Ведмежа подоба» дає додатково $s1% витривалості." },
    { en = "Rain of Fire damage is increased by $s2% and its Soul Shard cost is reduced by ${$s1/-10}.", ua = "Шкода «Вогняного дощу» збільшена на $s2%, а його вартість в уламках душі зменшена на ${$s1/-10}." },
    { en = "Lace your Wildfire Bomb with extra reagents, randomly giving it one of the following enhancements each time you throw it:\n\n\n\n|cFFFFFFFFShrapnel Bomb: |rShrapnel pierces the targets, causing $?s259387[Mongoose Bite][Raptor Strike] and $?s212436[Butchery][Carve] to apply a bleed for $270343d that stacks up to $270343u times.\n\n\n\n|cFFFFFFFFPheromone Bomb: |rKill Command has a $270323s2% chance to reset against targets coated with Pheromones.\n\n\n\n|cFFFFFFFFVolatile Bomb: |rReacts violently with poison, causing an extra $260231s1 Fire damage against enemies suffering from your Serpent Sting, and applies Serpent Sting to up to $s2 targets.", ua = "Начиняє вашу Бомбу лісової пожежі додатковими реагентами, випадково надаючи їй одне з наведених нижче поліпшень щоразу, коли ви її кидаєте:\n\n\n\n|cFFFFFFFFОсколкова бомба: |rОсколки пронизують цілі, змушуючи $?s259387[Укус мангуста][Удар раптора] і $?s212436[Різанину][Розтин] накладати кровотечу на $270343d, яка накопичується до $270343u разів.\n\n\n\n|cFFFFFFFFФеромонна бомба: |rНаказ вбити має $270323s2% ймовірності скидання проти цілей, вкритих феромонами.\n\n\n\n|cFFFFFFFFНестабільна бомба: |rБурхливо реагує з отрутою, завдаючи додаткові $260231s1 шкоди Вогнем ворогам, що потерпають від вашого Зміїного жала, і накладає Зміїне жало на щонайбільше $s2 цілей." },
    { en = "There is a new talent hiding in the shadows!", ua = "У тінях зачаївся новий талант!" },
    { en = "Your healing and absorption is increased by ${$s1}.1% on targets with Atonement.", ua = "Ваше зцілення і поглинання збільшено на ${$s1}.1% на цілях зі «Спокутою»." },
    { en = "Fire a shot that poisons your target, causing them to take $?s389882[${$m1*(1+($389882m1/100))}][$s1] Nature damage instantly and an additional $?s389882[${$o2*(1+($389882m1/100))}][$o2] Nature damage over $d.$?s378014[\n\n\n\nSerpent Sting's damage applies Latent Poison to the target, stacking up to $378015u times. $@spelldesc393949 consumes all stacks of Latent Poison, dealing $378016s1 Nature damage to the target per stack consumed.][]", ua = "Стріляєте пострілом, що отруює вашу ціль, змушуючи її миттєво зазнати $?s389882[${$m1*(1+($389882m1/100))}][$s1] шкоди Природою та ще $?s389882[${$o2*(1+($389882m1/100))}][$o2] шкоди Природою протягом $d.$?s378014[\n\n\n\nШкода Зміїного жала накладає на ціль Приховану отруту, накопичуючись до $378015u разів. $@spelldesc393949 поглинає всі стоси Прихованої отрути, завдаючи цілі $378016s1 шкоди Природою за кожен поглинутий стос.][]" },
    { en = "Strikes all enemies in front of you with a hungering attack that deals $sw1 Physical damage and heals you for ${$e1*100}% of that damage. Deals reduced damage beyond $s3 targets.\n\n\n\nCauses your Blood Plague damage to occur $s5% more quickly for $d. \n\n\n\n|cFFFFFFFFGenerates $s4 Runes.|r", ua = "Вражає всіх ворогів перед вами голодною атакою, що завдає $sw1 фізичної шкоди й зцілює вас на ${$e1*100}% цієї шкоди. Завдає зменшеної шкоди понад $s3 цілей.\n\n\n\nЗмушує вашу Кровну чуму завдавати шкоди на $s5% швидше протягом $d. \n\n\n\n|cFFFFFFFFСтворює $s4 Рун.|r" },
    { en = "For every $s1 sec Essence Font spends off cooldown, your next Essence Font may be channeled for $s3 additional second.\n\n\n\nThe duration of Essence Font's heal over time is increased by ${$s2/1000} sec.", ua = "За кожні $s1 с, які «Джерело Есенції» проводить поза перезарядженням, ваше наступне «Джерело Есенції» можна каналізувати на $s3 додаткову секунду.\n\n\n\nТривалість поступового зцілення від «Джерела Есенції» збільшено на ${$s2/1000} с." },
    { en = "Intimidating Shout will cause all nearby enemies except your target to flee in fear for $316595d instead of cowering.", ua = "«Залякувальний крик» змушує всіх ворогів поблизу, крім вашої цілі, тікати з переляку на $316595d замість того, щоб зіщулюватися від страху." },
    { en = "Judges the target, dealing $s1 Holy damage$?s231663[, and causing them to take $197277s1% increased damage from your next Holy Power ability][].$?a315867[\n\n\n\n|cFFFFFFFFGenerates $220637s1 Holy Power.][]", ua = "Судить ціль, завдаючи $s1 шкоди Світлом$?s231663[ і змушуючи її зазнати на $197277s1% більше шкоди від вашої наступної здібності Священної сили][].$?a315867[\n\n\n\n|cFFFFFFFFСтворює $220637s1 Священної сили.][]" },
    { en = "Epidemic has a $s1% chance to apply a Festering Wound to all enemies hit with fewer than 3 Festering Wounds, and a $s1% chance to burst a Festering Wound on the rest of the enemies.", ua = "«Епідемія» має $s1% шанс накласти «Гнійну рану» на всіх уражених ворогів, що мають менше ніж 3 «Гнійні рани», і $s1% шанс розірвати «Гнійну рану» на решті ворогів." },
    { en = "Your Ice Lances against frozen targets increase the damage of your Ice Lances by $s1% for $278310d, stacking up to $278310u times.", ua = "Ваші «Крижані списи» проти заморожених цілей збільшують шкоду ваших «Крижаних списів» на $s1% на $278310d, накопичуючись до $278310u разів." },
    { en = "Unleashes a vile explosion at the target location, dealing $386931o1 Shadow damage over $386931d to $s2 enemies within $a1 yds and applies Agony and Curse of Exhaustion to them.", ua = "Спричиняє мерзенний вибух у цільовій місцевості, завдаючи $386931o1 шкоди Тіні впродовж $386931d $s2 ворогам у радіусі $a1 ярдів і накладає на них «Агонію» та «Прокляття виснаження»." },
    { en = "Your tattoos reduce magic damage taken by $s1%.", ua = "Ваші татуювання зменшують отриману магічну шкоду на $s1%." },
    { en = "Your auto attack critical strikes generate $s1% more Rage and damage taken from area of effect attacks is reduced by $s2%.", ua = "Критичні удари ваших автоатак генерують на $s1% більше Люті, а шкода від атак по площі зменшується на $s2%." },
    { en = "Consuming Tidal Waves reduces the cast time of your next heal by $s2%.", ua = "Споживання «Припливних хвиль» зменшує час прочитання вашого наступного зцілення на $s2%." },
    { en = "Finishing move that creates shadow clones of yourself. You and your shadow clones each perform a piercing attack on all enemies near your target, dealing Physical damage to the primary target and reduced damage to other targets.\n\n   1 point  : ${$280720m1*1*$<mult>} total damage\n\n   2 points: ${$280720m1*2*$<mult>} total damage\n\n   3 points: ${$280720m1*3*$<mult>} total damage\n\n   4 points: ${$280720m1*4*$<mult>} total damage\n\n   5 points: ${$280720m1*5*$<mult>} total damage$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$280720m1*6*$<mult>} total damage][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$280720m1*7*$<mult>} total damage][]", ua = "Завершальний прийом, що створює тіньові клони вас самих. Ви й ваші тіньові клони кожен виконуєте пронизливу атаку по всіх ворогах поблизу вашої цілі, завдаючи фізичної шкоди основній цілі та зменшеної шкоди іншим цілям.\n\n   1 очко  : ${$280720m1*1*$<mult>} шкоди загалом\n\n   2 очки: ${$280720m1*2*$<mult>} шкоди загалом\n\n   3 очки: ${$280720m1*3*$<mult>} шкоди загалом\n\n   4 очки: ${$280720m1*4*$<mult>} шкоди загалом\n\n   5 очок: ${$280720m1*5*$<mult>} шкоди загалом$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$280720m1*6*$<mult>} шкоди загалом][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$280720m1*7*$<mult>} шкоди загалом][]" },
    { en = "Your successful Dispel Magic, Mass Dispel, Purify Disease, and Power Word: Shield casts generate $s1 Insanity during combat.", ua = "Ваші успішні прочитання «Розвіювання магії», «Масового розвіювання», «Очищення від хвороб» і «Слова сили: Щит» генерують $s1 Безумства під час бою." },
    { en = "Butchery reduces the remaining cooldown on Wildfire Bomb by ${$212436s2/1000}.1 sec for each target hit, up to $212436s3 targets.", ua = "«Різанина» зменшує залишкове перезарядження «Бомби дикого вогню» на ${$212436s2/1000}.1 с за кожну уражену ціль, до $212436s3 цілей." },
    { en = "Moonfire, Soothe, Remove Corruption, Innervate, and Rebirth are usable in Bear Form. Multiple uses of Ironfur may overlap.$?s2>0[\n\n\n\nAll damage taken in Bear Form reduced by $s2%.][]", ua = "Місячний вогонь, Заспокоєння, Усунення скверни, Наснага та Відродження можна застосовувати у Формі ведмедя. Кілька застосувань Залізного хутра можуть накладатися.$?s2>0[\n\n\n\nУся шкода, отримана у Формі ведмедя, зменшена на $s2%.][]" },
    { en = "Soothe, Remove Corruption, and Innervate are usable in Cat Form.", ua = "«Заспокоєння», «Усунення псування» та «Приплив енергії» можна застосовувати в Котячій подобі." },
    { en = "Grips the target in lightning, stunning and dealing $305485o1 Nature damage over $305485d while the target is lassoed. Can move while channeling.", ua = "Обплітає ціль блискавкою, оглушуючи її та завдаючи $305485o1 шкоди Природи впродовж $305485d, доки ціль спутана ласо. Можна рухатися під час каналізування." },
    { en = "Finishing move that blasts your target with your pistol, dealing Physical damage and increasing your damage dealt by $s2%. Multiple instances of this bonus can overlap.$?a235484[ Critical strikes with this ability deal four times normal damage.][]\n\n   1 point : ${$<damage>*1} damage, 4 sec\n\n   2 points: ${$<damage>*2} damage, 6 sec\n\n   3 points: ${$<damage>*3} damage, 8 sec\n\n   4 points: ${$<damage>*4} damage, 10 sec\n\n   5 points: ${$<damage>*5} damage, 12 sec$?s193531|((s394320|s394321)&!s193531)[\n\n   6 points: ${$<damage>*6} damage, 14 sec][]$?s193531&(s394320|s394321)[\n\n   7 points: ${$<damage>*7} damage, 16 sec][]", ua = "Завершальний прийом, що вражає вашу ціль пострілом з пістолета, завдаючи фізичної шкоди та збільшуючи завдану вами шкоду на $s2%. Кілька застосувань цього бонусу можуть накладатися.$?a235484[ Критичні удари цією здібністю завдають учетверо більшої шкоди, ніж звичайно.][]\n\n   1 очко : ${$<damage>*1} шкоди, 4 с\n\n   2 очки: ${$<damage>*2} шкоди, 6 с\n\n   3 очки: ${$<damage>*3} шкоди, 8 с\n\n   4 очки: ${$<damage>*4} шкоди, 10 с\n\n   5 очок: ${$<damage>*5} шкоди, 12 с$?s193531|((s394320|s394321)&!s193531)[\n\n   6 очок: ${$<damage>*6} шкоди, 14 с][]$?s193531&(s394320|s394321)[\n\n   7 очок: ${$<damage>*7} шкоди, 16 с][]" },
    { en = "Roll the dice of fate, providing a random combat enhancement for $d.", ua = "Кидає кості долі, надаючи випадкове бойове підсилення на $d." },
    { en = "Brutally attack an enemy for $396718s1 Physical damage$?s388933[ and become Enraged for $184362d.][.]\n\n\n\n|cFFFFFFFFGenerates ${$m1/10} Rage.", ua = "Жорстоко атакуєте ворога, завдаючи $396718s1 фізичної шкоди$?s388933[ та впадаєте в Розлюченість на $184362d.][.]\n\n\n\n|cFFFFFFFFСтворює ${$m1/10} Люті." },
    { en = "Judgment generates $220637s1 Holy Power.", ua = "«Присуд» генерує $220637s1 Святої сили." },
    { en = "When you cast Word of Glory on yourself, it is increased by up to $s1% based on your missing health and $s2% of the mana cost is refunded.", ua = "Коли ви застосовуєте «Слово слави» на себе, його ефект збільшується до $s1% залежно від нестачі вашого здоров'я, а $s2% витрат мани повертається." },
    { en = "Afflicts one target with $o2 Shadow damage over $d. \n\n\n\nIf dispelled, deals ${$m2*$s1/100} damage to the dispeller and silences them for $196364d.$?s231791[\n\n\n\n|cFFFFFFFFGenerates $231791m1 Soul $LShard:Shards; if the target dies while afflicted.|r][]", ua = "Уражає одну ціль, завдаючи $o2 шкоди Тінню протягом $d. \n\n\n\nУ разі розвіювання завдає ${$m2*$s1/100} шкоди тому, хто розвіяв, і сковує його мовчанням на $196364d.$?s231791[\n\n\n\n|cFFFFFFFFСтворює $231791m1 $LУламок душі:Уламки душі; якщо ціль гине під час дії ефекту.|r][]" },
    { en = "Increases Howling Blast damage done by an additional $s1%.", ua = "Збільшує шкоду від «Виючого пориву» ще на $s1%." },
    { en = "Increases the damage of Obliterate by $s1% and the damage of Frostscythe by $s2%.", ua = "Збільшує шкоду від «Знищення» на $s1% і шкоду від «Морозної коси» на $s2%." },
    { en = "Killing Machine also causes your next Obliterate to deal Frost damage.", ua = "«Машина вбивства» також змушує ваше наступне «Знищення» завдавати морозної шкоди." },
    { en = "You may now also block spells and harmful periodic effects.", ua = "Тепер ви можете також блокувати закляття та шкідливі періодичні ефекти." },
    { en = "Apocalypse creates an unholy pact that forms shadowy chains between you and your ghoul, dealing ${$319236s1*$s2} Shadow damage over $s2 sec to enemies caught in between.", ua = "«Апокаліпсис» створює нечестивий пакт, що утворює тіньові ланцюги між вами та вашим гулем, завдаючи ${$319236s1*$s2} тіньової шкоди протягом $s2 сек ворогам, які опинилися між вами." },
    { en = "When you use $s2 different combo point-generating abilities within $s1 sec, the damage of your next $145152n Rips or Ferocious Bites is increased by $145152s1% for their full duration.", ua = "Коли ви застосовуєте $s2 різних здібностей, що дають серійні очки, протягом $s1 сек, шкода наступних $145152n застосувань «Роздирання» чи «Лютого укусу» зростає на $145152s1% на весь час їхньої дії." },
    { en = "Mastery: Potent Assassin also increases damage of your bleeds.", ua = "«Майстерність: Могутній асасин» також збільшує шкоду від ваших кровотеч." },
    { en = "Increases the duration of Immolation Aura by ${$s1/1000} sec.", ua = "Збільшує тривалість «Аури спалення» на ${$s1/1000} сек." },
    { en = "Reduces the cooldown of Immolation Aura by ${$abs($s0/1000)} sec.", ua = "Зменшує перезарядження «Аури спалення» на ${$abs($s0/1000)} сек." },
    { en = "Fel energy thickens your skin to demonic proportions, increasing your Stamina by $s1% and your Armor by $s2%.", ua = "Енергія Скверни потовщує вашу шкіру до демонічних розмірів, збільшуючи вашу Витривалість на $s1% і вашу Броню на $s2%." },
    { en = "Reduces the cooldown of Blade Dance by ${$abs($s0/1000)} sec.", ua = "Зменшує перезарядження «Танцю клинків» на ${$abs($s0/1000)} сек." },
    { en = "Each enemy stunned by Chaos Nova has a $179057s3% chance to generate a Lesser Soul Fragment.", ua = "Кожен ворог, приголомшений «Новою хаосу», має $179057s3% шанс породити менший фрагмент душі." },
    { en = "Fel Devastation damage also heals you for up to ${$212106s1*(2/$t1)} health.", ua = "Шкода від «Спустошення Скверни» також зцілює вас на суму до ${$212106s1*(2/$t1)} здоров'я." },
    { en = "Sigil of Flame deals an additional $204598o3 $@spelldesc395020 damage over $204598d, to all enemies affected by the sigil.", ua = "Печать полум'я завдає додаткові $204598o3 шкоди $@spelldesc395020 протягом $204598d усім ворогам, на яких діє печать." },
    { en = "Fiery Brand deals $207771s3 Fire damage every $207771t3 sec.", ua = "«Вогняне тавро» завдає $207771s3 вогняної шкоди кожні $207771t3 сек." },
    { en = "Steady Shot now generates an additional $s1 Focus.", ua = "«Впевнений постріл» тепер дає додатково $s1 Зосередженості." },
    { en = "Demon Spikes also increases your Parry chance by $203819s1% for $203819d.", ua = "«Демонічні шипи» також підвищують ваш шанс парирування на $203819s1% на $203819d." },
    { en = "While transformed, Shear and Fracture generate $s1 additional Lesser Soul Fragment.", ua = "У перетвореному стані «Розсічення» і «Перелом» створюють на $s1 менший уламок душі більше." },
    { en = "While transformed, Shear and Fracture generate $187827s4 additional Fury.", ua = "У перетвореному стані «Розсічення» і «Перелом» дають на $187827s4 більше Люті." },
    { en = "$?s342049[Chimaera Shot][Arcane Shot] and Multi-Shot damage increased by $s1%.", ua = "Шкода $?s342049[Пострілу химери][Арканного пострілу] та Множинного пострілу збільшена на $s1%." },
    { en = "Arcane Shot and Chimaera Shot Focus cost reduced by $s1.", ua = "Витрати Зосередження на «Арканний постріл» і «Постріл химери» зменшено на $s1." },
    { en = "Take direct control of your pet and see through its eyes for $d.", ua = "Ви берете прямий контроль над улюбленцем і бачите його очима протягом $d." },
    { en = "Mastery increases your Attack Power.", ua = "Майстерність підвищує вашу Силу атаки." },
    { en = "Holy Word: Sanctify reduces the cast time and cost of your Prayer of Healing by $321379m1% for $321379d.", ua = "«Святе слово: освячення» зменшує час прочитання і вартість вашої «Молитви зцілення» на $321379m1% на $321379d." },
    { en = "Targets stunned by Binding Shot, knocked back by High Explosive Trap, knocked up by Implosive Trap, incapacitated by Scatter Shot, or stunned by Intimidation deal $s1% less damage to you for $321469d after the effect ends.", ua = "Цілі, приголомшені «Сковувальним пострілом», відкинуті «Вибуховою пасткою», підкинуті «Імплозивною пасткою», знешкоджені «Розсіювальним пострілом» або приголомшені «Залякуванням», завдають вам на $s1% менше шкоди протягом $321469d після завершення ефекту." },
    { en = "Bestial Wrath provokes your pets to tear into your target, causing your target to bleed for $321538s1 damage over $321538d.\n\n\n\nDamage from Bloodshed has a $s3% chance to summon Dire Beasts.", ua = "«Звіриний гнів» спонукає ваших улюбленців вгризатися в ціль, завдаючи їй $321538s1 шкоди від кровотечі протягом $321538d.\n\n\n\nШкода від «Кровопролиття» має $s3% шанс прикликати Лютих звірів." },
    { en = "Arcane Surge lasts an additional ${$s1/1000} sec and grants $s2% increased Spell Damage.", ua = "«Арканний сплеск» триває на ${$s1/1000} сек. довше і дає +$s2% до шкоди заклять." },
    { en = "Increases Arcane Explosion and Arcane Blast damage by $s1%.", ua = "Підвищує шкоду «Арканного вибуху» і «Арканного удару» на $s1%." },
    { en = "Cooldown is reduced by  ${$s2/-1000} sec. and draws in the positive chi of all your Healing Spheres to increase the healing done by Expel Harm.", ua = "Перезарядження зменшено на ${$s2/-1000} сек., і залучається позитивне ці всіх ваших Сфер зцілення, щоб посилити зцілення від «Вигнання шкоди»." },
    { en = "Purifying Brew increases the absorption of your next Celestial Brew by up to $s1%, based on Stagger purified.", ua = "«Очисне вариво» збільшує поглинання вашого наступного «Небесного варива» на величину до $s1%, залежно від очищеної Хитавиці." },
    { en = "When you kill an enemy with $?s152174[Chi Explosion][Blackout Kick], you have a $m1% chance to summon a Chi Sphere, granting 1 Chi when you walk through it.", ua = "Коли ви вбиваєте ворога за допомогою $?s152174[Вибуху ці][Затемнювального удару], з імовірністю $m1% з'являється сфера ці, що дарує 1 ці, коли ви проходите крізь неї." },
    { en = "Spin while kicking in the air, dealing $?s137025[${4*$107270s1*$<CAP>/$AP}][${4*$107270s1}] Physical damage over $d to enemies within $107270A1 yds. $?s322700[\n\n\n\nDealing damage with Spinning Crane Kick grants Shuffle for $322700s1 sec, and your Healing Spheres travel towards you.][] $?c3[\n\n\n\nSpinning Crane Kick's damage is increased by $220358s1% for each unique target you've struck in the last $220358d with Tiger Palm, Blackout Kick, or Rising Sun Kick.][]", ua = "Ви обертаєтесь у повітрі, завдаючи ударів ногами, які протягом $d завдають $?s137025[${4*$107270s1*$<CAP>/$AP}][${4*$107270s1}] фізичної шкоди ворогам у межах $107270A1 ярд. $?s322700[\n\n\n\nЗавдання шкоди Обертальним ударом журавля дарує Переступ на $322700s1 сек, а ваші сфери зцілення рухаються до вас.][] $?c3[\n\n\n\nШкода Обертального удару журавля збільшується на $220358s1% за кожну унікальну ціль, яку ви вразили за останні $220358d Долонею тигра, Затемнювальним ударом чи Ударом висхідного сонця.][]" },
    { en = "Xuen strikes your enemies with Empowered Tiger Lightning every $s1 sec, dealing $s2% of the damage you and your summons have dealt to those targets in the last $s1 sec.", ua = "Сюень б'є ваших ворогів «Підсиленою тигровою блискавкою» кожні $s1 сек., завдаючи $s2% шкоди, яку ви й ваші прикликані істоти завдали цим цілям за останні $s1 сек." },
    { en = "You and the target charge each other, meeting halfway then rooting all targets within $128846A1 yards for $128846d.", ua = "Ви й ціль кидаєтеся назустріч одне одному, зіштовхуючись на півдорозі, і знерухомлюєте всі цілі в радіусі $128846A1 м на $128846d." },
    { en = "Touch of Death reduces delayed Stagger damage by $s1% of damage dealt.", ua = "«Дотик смерті» зменшує відкладену шкоду «Похитування» на $s1% від завданої шкоди." },
    { en = "Touch of Death spawns $s1 Chi Spheres, granting 1 Chi when you walk through them.", ua = "«Дотик смерті» створює $s1 сфер ці, що дають 1 ці, коли ви крізь них проходите." },
    { en = "Dark Transformation grants your ghoul $s1% energy.", ua = "«Темне перетворення» дає вашому гулю $s1% енергії." },
    { en = "If you cast Innervate on somebody else, you gain its effect at $s1% effectiveness.", ua = "Якщо ви творите «Живлення» на когось іншого, ви отримуєте його ефект із $s1% дієвості." },
    { en = "Duration increased by ${$s1/1000} sec.", ua = "Тривалість збільшено на ${$s1/1000} сек." },
    { en = "Sacrifice your ghoul to deal $327611s1 Shadow damage to all nearby enemies and heal for $s1% of your maximum health. Deals reduced damage beyond $327611s2 targets.", ua = "Пожертвуйте своїм гулем, щоб завдати $327611s1 тіньової шкоди всім ворогам поблизу та зцілитися на $s1% максимального здоров'я. Завдає зменшеної шкоди понад $327611s2 цілей." },
    { en = "Cooldown reduced by $s1%.", ua = "Перезарядження зменшено на $s1%." },
    { en = "Moonfire and Sunfire duration increased by ${$s1/1000} sec.", ua = "Тривалість «Місячного вогню» та «Сонячного вогню» збільшено на ${$s1/1000} сек." },
    { en = "Grants an additional charge of Roll and Chi Torpedo.", ua = "Дає додатковий заряд «Перекату» та «Торпеди ці»." },
    { en = "Your next Curse of Exhaustion, Curse of Tongues or Curse of Weakness cast within $d is amplified.\n\n\n\n$@spellname334275\n\nReduces the target's movement speed by an additional $s3%.\n\n\n\n$@spellname1714\n\nIncreases casting time by an additional $<cast>%.\n\n\n\n$@spellname702\n\nEnemy is unable to critically strike.", ua = "Ваше наступне закляття Прокляття виснаження, Прокляття мов чи Прокляття слабкості, прочитане протягом $d, посилюється.\n\n\n\n$@spellname334275\n\nЗнижує швидкість пересування цілі додатково на $s3%.\n\n\n\n$@spellname1714\n\nЗбільшує час прочитання додатково на $<cast>%.\n\n\n\n$@spellname702\n\nВорог не може завдавати критичних ударів." },
    { en = "Each stack of Maelstrom Weapon consumed increases the damage of your next Frost Shock by $334196s1%, and causes it to hit $334196m2 additional target, up to $s1 times.", ua = "Кожен спожитий стак «Зброї Виру» збільшує шкоду вашого наступного «Морозного удару» на $334196s1% і змушує його вразити $334196m2 додаткову ціль, до $s1 разів." },
    { en = "Damaging an enemy with Agony increases the damage dealt by your next Drain Life by $s1%. This effect stacks up to $334320u times.", ua = "Завдання шкоди ворогові «Агонією» збільшує шкоду вашого наступного «Висмоктування життя» на $s1%. Цей ефект накопичується до $334320u разів." },
    { en = "Summoning your Demonic Tyrant instantly generates ${$s1/10} Soul Shards.", ua = "Прикликання вашого Демонічного тирана миттєво створює ${$s1/10} уламків душі." },
    { en = "Teaches your Wild Imps how to spend $s1% less energy when casting Fel Firebolt.", ua = "Навчає ваших диких бісенят витрачати на $s1% менше енергії, коли вони творять «Вогняну стрілу Скверни»." },
    { en = "Your Essence Font's initial heal is increased by $s2% and has a chance to reduce the cooldown of Thunder Focus Tea by $s1 sec.", ua = "Початкове зцілення вашого «Джерела есенції» збільшено на $s2%, і воно має шанс зменшити перезарядження «Чаю громового зосередження» на $s1 сек." },
    { en = "Every $s1 Astral Power spent grants Celestial Alignment for $s2 sec.", ua = "Кожні $s1 витраченої Астральної сили дають «Небесне вирівнювання» на $s2 сек." },
    { en = "Entering Eclipse increases your critical strike chance with Arcane or Nature spells by ${$339943s1*$339943u}%, decreasing by $339943s1% every $339943t2 sec.", ua = "Вхід у Затемнення підвищує ваш шанс критичного удару арканними закляттями чи закляттями Природи на ${$339943s1*$339943u}%, зменшуючись на $339943s1% кожні $339943t2 сек." },
    { en = "Starsurge and Starfall reduce the cost of Starsurge and Starfall by $340049s1% and increase their damage by $340049s2% for $340049d, stacking up to $340049u times.", ua = "Зоряний Сплеск і Зорепад зменшують вартість Зоряного Сплеску і Зорепаду на $340049s1% та підвищують їхню шкоду на $340049s2% на $340049d, накопичуючись до $340049u разів." },
    { en = "The duration of $?a102560[Incarnation: Chosen of Elune][Celestial Alignment] is increased by |cFFFFFFFF${$s1/1000}.1 sec|r.", ua = "Тривалість $?a102560[Втілення: Обранець Елуни][Небесного вирівнювання] збільшується на |cFFFFFFFF${$s1/1000}.1 сек|r." },
    { en = "After casting Vampiric Touch on a target, your next Vampiric Touch within $341282d is instant cast and deals $34914s4 Shadow damage immediately.\n\n\n\nThis effect cannot occur more than once every $341291d.", ua = "Після застосування Вампірського Дотику на ціль ваш наступний Вампірський Дотик протягом $341282d стає миттєвим і завдає $34914s4 шкоди Тіні негайно.\n\n\n\nЦей ефект може спрацьовувати не частіше, ніж раз на $341291d." },
    { en = "A two-headed shot that hits your primary target for $344120sw1 Nature damage and another nearby target for ${$344121sw1*($s1/100)} Frost damage.$?s260393[\n\n\n\nChimaera Shot has a $260393h% chance to reduce the cooldown of Rapid Fire by ${$260393m1/10}.1 sec.][]", ua = "Двоголовий постріл, що завдає вашій основній цілі $344120sw1 шкоди природою, а іншій найближчій цілі — ${$344121sw1*($s1/100)} шкоди морозом.$?s260393[\n\n\n\nПостріл химери з імовірністю $260393h% скорочує перезарядження Швидкого вогню на ${$260393m1/10}.1 сек.][]" },
    { en = "Strike your target with an icy blade, dealing $s1 Frost damage and snaring them by $s2% for $d.\n\n\n\nIce Strike increases the damage of your next Frost Shock by $384357s1% and generates $s4 stack of Maelstrom Weapon.", ua = "Вражаєте ціль крижаним клинком, завдаючи $s1 шкоди Морозу та сповільнюючи її на $s2% на $d.\n\n\n\nКрижаний Удар підвищує шкоду вашого наступного Морозного Розряду на $384357s1% та створює $s4 заряд Зброї Мальстрому." },
    { en = "Crusader Strike mana cost reduced by $s1%.", ua = "Вартість мани Удару Хрестоносця зменшено на $s1%." },
    { en = "Fel Rush damage increased by $s1%.", ua = "Шкоду Ривка Скверни підвищено на $s1%." },
    { en = "Phoenix Flames deals $s1% increased damage and always critically strikes.", ua = "Полум'я Фенікса завдає на $s1% більше шкоди й завжди завдає критичного удару." },
    { en = "Your damage is increased by ${$m1}.1% for each of Vampiric Touch, Shadow Word: Pain, and Shadow Word: Madness on the target. During Voidform, all targets receive the maximum effect.", ua = "Ваша шкода підвищується на ${$m1}.1% за кожен ефект Вампірського Дотику, Слова Тіні: Біль і Слова Тіні: Божевілля на цілі. Під час Форми Порожнечі всі цілі отримують максимальний ефект." },
    { en = "Call down a blast of heavenly energy, dealing $s2 Holy damage to all targets in the area and causing them to take $s3% increased damage from your single target Holy Power abilities, and $s4% increased damage from other Holy Power abilities for $d.\n\n\n\n$?s406158 [|cFFFFFFFFGenerates $406158s1 Holy Power.][]", ua = "Прикликає вибух небесної енергії, що завдає $s2 шкоди Світлом усім цілям у зоні та змушує їх протягом $d отримувати на $s3% більше шкоди від ваших одноцільових здібностей на Святій силі та на $s4% більше шкоди від інших здібностей на Святій силі.\n\n\n\n$?s406158 [|cFFFFFFFFНадає $406158s1 Святої сили.][]" },
    { en = "Spinning Crane Kick's damage is increased by $220358s1% for each unique target you've struck in the last $220358d with Tiger Palm, Blackout Kick, or Rising Sun Kick.", ua = "Шкода Обертового Удару Журавля підвищується на $220358s1% за кожну окрему ціль, яку ви вразили за останні $220358d Долонею Тигра, Приголомшливим Ударом чи Ударом Вранішнього Сонця." },
    { en = "Disable will root targets that are already snared for $116706d.", ua = "Знешкодження знерухомлює цілі, які вже сповільнені, на $116706d." },
    { en = "Purifying Brew now has 2 charges.", ua = "Очисне Вариво тепер має 2 заряди." },
    { en = "Restless Blades now also reduces the remaining cooldown of Evasion and Feint by ${$s1/10}.1 sec per combo point spent.", ua = "Невгамовні Клинки тепер також зменшують залишкове перезарядження Ухилення та Фінту на ${$s1/10}.1 сек. за кожне витрачене комбо-очко." },
    { en = "Additionally reduces damage taken by $s1%.", ua = "Додатково зменшує отриману шкоду на $s1%." },
    { en = "You sound the call of the wild, summoning $s1 of your active pets for $d. During this time, a random pet from your stable will appear every $t2 sec to assault your target for $361582d. \n\n\n\nEach time Call of the Wild summons a pet, the cooldown of Barbed Shot and Kill Command are reduced by $s3%.", ua = "Ви лунаєте поклик дикої природи, прикликаючи $s1 своїх активних улюбленців на $d. Протягом цього часу кожні $t2 сек. з'являється випадковий улюбленець із вашої стайні й атакує вашу ціль протягом $361582d. \n\n\n\nЩоразу, коли Поклик Дикої Природи прикликає улюбленця, перезарядження Колючого Пострілу та Наказу вбити зменшується на $s3%." },
    { en = "Cleanses harmful effects from the target, removing all Magic and Poison effects.", ua = "Очищає ціль від шкідливих ефектів, знімаючи всі магічні та отруйні ефекти." },
    { en = "You and your pet charge your enemy, striking them for a combined $<combinedDmg> Physical damage. You and your pet's bond is then strengthened for $d, causing you and your pet to deal $s2% increased damage.\n\n\n\nWhile Coordinated Assault is active, Kill Command's chance to reset its cooldown is increased by $s1%.", ua = "Ви й ваш улюбленець кидаєтеся на ворога, завдаючи йому разом $<combinedDmg> фізичної шкоди. Після цього зв'язок між вами й улюбленцем зміцнюється на $d, тож ви й улюбленець завдаєте на $s2% більше шкоди.\n\n\n\nПоки активний Скоординований штурм, шанс Наказу вбити скинути своє перезарядження підвищений на $s1%." },
    { en = "You give the signal, and your pet charges your target, bleeding them for $378957o1 damage over $378957d and increasing you and your pet's chance to critically strike your target by $378957s2% for $378957d.", ua = "Ви подаєте сигнал, і ваш улюбленець кидається на ціль, завдаючи їй $378957o1 шкоди від кровотечі протягом $378957d та підвищуючи ваш і улюбленця шанс завдати критичного удару по цілі на $378957s2% протягом $378957d." },
    { en = "Gauge the magical energy of your allies, showing you when they are using an exceptionally powerful ability.", ua = "Оцінює магічну енергію ваших союзників, показуючи, коли вони застосовують надзвичайно потужну здібність." },
    { en = "Increases the damage of your spells by up to ${$s1}.1%, based on the current health of your target. Higher health targets take more damage.", ua = "Підвищує шкоду ваших заклять аж до ${$s1}.1%, залежно від поточного здоров'я цілі. Цілі з більшим здоров'ям отримують більше шкоди." },
    { en = "Healing done to allies is increased by ${$s1}.1% while their health percentage is lower than your own.", ua = "Зцілення, що надається союзникам, підвищене на ${$s1}.1%, поки їхній відсоток здоров'я нижчий за ваш власний." },
    { en = "Emerald Blossom costs $s2 Essence, but no longer has a cooldown.", ua = "Смарагдовий цвіт коштує $s2 есенції, але більше не має перезарядження." },
    { en = "Divert spiritual energy, healing an ally for $367230s1. Jumps to injured allies within $<range> yds when empowered.\n\n\n\n|cFFFFFFFFI:|r   Heals one ally.\n\n\n\n|cFFFFFFFFII:|r  Heals a second ally.\n\n\n\n|cFFFFFFFFIII:|r Heals a third ally.", ua = "Спрямовує духовну енергію, зцілюючи союзника на $367230s1. Перескакує на поранених союзників у межах $<range> м, коли посилене.\n\n\n\n|cFFFFFFFFI:|r   Зцілює одного союзника.\n\n\n\n|cFFFFFFFFII:|r  Зцілює другого союзника.\n\n\n\n|cFFFFFFFFIII:|r Зцілює третього союзника." },
    { en = "Cleanse the rot from Awakened Decay to recover an assortment of Rousing Elements.", ua = "Очистіть гниль із Пробудженого Розпаду, щоб добути набір Бентежних елементів." },
    { en = "Destroy a random element from the core of an Awakened Order, revealing the three remaining elements in the process.", ua = "Знищує випадковий елемент з ядра Пробудженого Порядку, розкриваючи при цьому три елементи, що залишилися." },
    { en = "$?pc105366[Specialize further into Decayology if you wish to discover more potion recipes.]?pc105367[You have learned all there is to discover from potion experimentation.][Experiment with volatile reagents in hopes of discovering new potion recipes.]", ua = "$?pc105366[Спеціалізуйтесь далі в тлінології, якщо хочете відкрити більше рецептів зілль.]?pc105367[Ви дізналися все, що можна відкрити з експериментів над зіллями.][Експериментуйте з нестабільними реагентами в надії відкрити нові рецепти зілль.]" },
    { en = "$?pc105364[Specialize further into Decayology if you wish to discover more phial recipes.]?pc105365[You have learned all there is to discover from phial experimentation.][Experiment with volatile reagents in hopes of discovering new phial recipes.]", ua = "$?pc105364[Спеціалізуйтесь далі в тлінології, якщо хочете відкрити більше рецептів фіалів.]?pc105365[Ви дізналися все, що можна відкрити з експериментів над фіалами.][Експериментуйте з нестабільними реагентами в надії відкрити нові рецепти фіалів.]" },
    { en = "Commune with the Emerald Dream, restoring $s6% health and $s1% mana every $t1 sec for $d. Overhealing is transferred to an injured ally within $370984r yds.\n\n\n\nCastable while stunned, disoriented, incapacitated, or silenced.", ua = "Ви єднаєтеся зі Смарагдовим Сном, відновлюючи $s6% здоров'я та $s1% мани щосекунди $t1 протягом $d. Надлишкове зцілення передається пораненому союзнику в межах $370984r м.\n\n\n\nМожна творити, поки ви приголомшені, дезорієнтовані, знесилені або знімовлені." },
    { en = "Quell's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Приборкання зменшене на ${$s1/-1000} с." },
    { en = "Every $s2 Emerald Blossoms leaves behind a tiny sprout which gathers $s1% of your healing over $371871d. The sprout then heals allies within $371879a1 yds, divided evenly among targets.", ua = "Кожен $s2-й Смарагдовий цвіт лишає по собі крихітний паросток, що збирає $s1% вашого зцілення протягом $371871d. Потім паросток зцілює союзників у межах $371879a1 м, розподіляючи зцілення порівну між цілями." },
    { en = "Mangle increases the damage of your next cast of Maul or Raze, and casting Maul or Raze increases the damage of your next Mangle by $s1%. Stacks up to $372015u.", ua = "Роздирання підвищує шкоду вашого наступного застосування Побиття чи Знищення, а застосування Побиття чи Знищення підвищує шкоду вашого наступного Роздирання на $s1%. Стакається до $372015u разів." },
    { en = "The effectiveness of your next Holy Word: Serenity, Sanctify, or Chastise is increased by $s1% and grants a corresponding Divine Favor for $372761d.\n\n\n\n|cffffffffChastise:|r Increases your damage by $372761s1% and refunds $s2 sec from the cooldown of Holy Word: Chastise.\n\n\n\n|cffffffffSanctify:|r Blesses the target area, healing up to $372787s2 allies for ${$372787s1*($372784d/$372784t3)} over $372784d.\n\n\n\n|cffffffffSerenity:|r Flash Heal, Heal, and Renew heal for $372791s1% more and cost $372791s3% less mana.", ua = "Дієвість вашого наступного застосування Святого слова: Безтурботність, Освячення чи Покарання підвищена на $s1% і надає відповідну Божественну прихильність на $372761d.\n\n\n\n|cffffffffПокарання:|r Підвищує вашу шкоду на $372761s1% і повертає $s2 с перезарядження Святого слова: Покарання.\n\n\n\n|cffffffffОсвячення:|r Благословляє цільову область, зцілюючи до $372787s2 союзників на ${$372787s1*($372784d/$372784t3)} протягом $372784d.\n\n\n\n|cffffffffБезтурботність:|r Швидке зцілення, Зцілення та Оновлення зцілюють на $372791s1% більше й коштують на $372791s3% менше мани." },
    { en = "Rapture enhances $s1 additional shields.", ua = "Захват підсилює додатково $s1 щитів." },
    { en = "Mind Blast gains $s1 additional charge.", ua = "«Вибух розуму» отримує $s1 додатковий заряд." },
    { en = "Renew heals for an additional $s1% and its mana cost is reduced by $s2%.", ua = "«Оновлення» зцілює додатково на $s1%, а його витрата мани зменшена на $s2%." },
    { en = "A word of holy power that heals the target for $s1. \n\n\n\nOnly usable if the target is below $s2% health.", ua = "Слово святої сили, що зцілює ціль на $s1. \n\n\n\nМожна застосувати, лише якщо здоров'я цілі нижче $s2%." },
    { en = "You can detect and utilize gale winds that redirect your flight and propel you onward, boosting your speed in the direction of the gale.", ua = "Ви можете виявляти й використовувати шквальні вітри, що змінюють напрямок вашого польоту й штовхають вас уперед, збільшуючи вашу швидкість у напрямку шквалу." },
    { en = "Icebound Fortitude's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Крижаної стійкості» зменшено на ${$s1/-1000} с." },
    { en = "Convert a mass of unimpressive gemstones into something more remarkable.", ua = "Перетворює купу невиразних самоцвітів на щось значно примітніше." },
    { en = "Your Blood thickens increasing your Stamina by $s1% and your Armor by $s2%.", ua = "Ваша кров густішає, збільшуючи вашу Витривалість на $s1% і вашу Броню на $s2%." },
    { en = "This putrid recipe requires an altar infused with powerful decay magic, rumored to be deep in Brackenhide Hollow.", ua = "Цей смердючий рецепт потребує вівтаря, насиченого могутньою магією гниття, що, за чутками, ховається глибоко в Папоротешкурній Улоговині." },
    { en = "Successfully interrupting an enemy with Quell generates $375508s1 Essence.", ua = "Успішне переривання ворога «Придушенням» породжує $375508s1 есенції." },
    { en = "Renewing Blaze's cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Оновлювального полум'я» зменшено на ${$s1/-1000} с." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a rare hides and scales gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Обробляє $M1 рідкісні шкури та луску якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібрані зі створінь Драконових Островів, до якості 1 |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a rare hides and scales gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Обробляє $M1 рідкісні шкури та луску якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібрані зі створінь Драконових Островів, до якості 1 |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Throw a deadly chakram at your current target that will rapidly deal $375893s1 Physical damage $x times, bouncing to other targets if they are nearby. Enemies struck by Death Chakram take $375893s2% more damage from you and your pet for $375893d.\n\n\n\nEach time the chakram deals damage, its damage is increased by $s3% and you generate $s4 Focus.", ua = "Кидає смертоносний чакрам у вашу поточну ціль, що швидко завдає $375893s1 фізичної шкоди $x разів, відскакуючи до інших цілей поблизу. Вороги, вражені «Чакрамом смерті», отримують на $375893s2% більше шкоди від вас і вашого улюбленця протягом $375893d.\n\n\n\nЩоразу, коли чакрам завдає шкоди, його шкода збільшується на $s3%, а ви породжуєте $s4 зосередження." },
    { en = "Blast all targets affected by your Flame Shock within $r yards with a Primordial Wave, dealing $375984s1 Elemental damage$?a137040[, and granting you Lava Surge][].$?c2[\n\n\n\nPrimordial Wave generates $s5 stacks of Maelstrom Weapon.][]$?a343725[\n\n\n\n|cFFFFFFFFGenerates $343725s12 Maelstrom.|r][]", ua = "Уражає всі цілі, вражені вашим Полум'яним шоком у межах $r ярд, Первісною хвилею, завдаючи $375984s1 шкоди стихіями$?a137040[ і надаючи вам Сплеск лави][].$?c2[\n\n\n\nПервісна хвиля створює $s5 зарядів Зброї виру.][]$?a343725[\n\n\n\n|cFFFFFFFFНадає $343725s12 виру.|r][]" },
    { en = "Conjure a radiant spark that causes $s1 Arcane damage instantly, and an additional $o2 damage over $d.\n\n\n\nThe target takes $376104s1% increased damage from your direct damage spells, stacking each time they are struck. This effect ends after $376104u spells.", ua = "Прикликає осяйну іскру, що миттєво завдає $s1 арканної шкоди та додатково $o2 шкоди протягом $d.\n\n\n\nЦіль отримує на $376104s1% більше шкоди від ваших заклять прямої шкоди, накопичуючись за кожного влучання. Цей ефект закінчується після $376104u заклять." },
    { en = "Temporal Anomaly applies Echo at $s1% effectiveness.", ua = "«Часова аномалія» застосовує «Відлуння» з $s1% ефективності." },
    { en = "This mystical cloth can only be woven at a special loom in the Azure Archives, located in the southern area of The Azure Span.", ua = "Цю містичну тканину можна виткати лише на особливому верстаті в Лазурових Архівах, що на півдні Лазурового Простору." },
    { en = "This cloth can only be woven at a special loom found at the Temporal Conflux, located in the south of Thaldraszus.", ua = "Цю тканину можна виткати лише на особливому верстаті в Темпоральному Конфлюксі, що на півдні Талдразуса." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a leather gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M1 шкіри якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібраної зі створінь Драконових Островів, на 1 шкіру якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a leather gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M1 шкіри якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібраної зі створінь Драконових Островів, на 1 шкіру якості |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a scales gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M1 луски якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібраної зі створінь Драконових Островів, на 1 луску якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a scales gathered from the creatures of the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M1 луски якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібраної зі створінь Драконових Островів, на 1 луску якості |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "While falling from a high location, your mount extends its wings to propel you both forward.\n\n\n\nPointing yourself downward grants more momentum. Evening out can transfer that momentum forward.\n\n\n\nPointing yourself upward slows you down. When at your slowest, you will start to fall slowly toward the ground.\n\n\n\nYou also gain access to the following abilities:\n\n\n\n$@spellicon372608$@spellname372608\n\n$@spelldesc372608\n\n\n\n$@spellicon372610$@spellname372610\n\n$@spelldesc372610", ua = "Падаючи з висоти, ваша їздова тварина розправляє крила, щоб понести вас обох уперед.\n\n\n\nНахил донизу надає більше розгону. Вирівнювання дає змогу перенести цей розгін уперед.\n\n\n\nНахил угору сповільнює вас. На найменшій швидкості ви починаєте повільно опускатися до землі.\n\n\n\nВи також отримуєте доступ до таких здібностей:\n\n\n\n$@spellicon372608$@spellname372608\n\n$@spelldesc372608\n\n\n\n$@spellicon372610$@spellname372610\n\n$@spelldesc372610" },
    { en = "Increases the duration of Divine Steed by ${$s1/1000} sec.", ua = "Збільшує тривалість «Божественного скакуна» на ${$s1/1000} сек." },
    { en = "Judgment's damage is increased by $s1%.", ua = "Шкода «Суду» збільшена на $s1%." },
    { en = "Frostwyrm's Fury has $s1% reduced cooldown and Freezes all enemies hit for $377048d.", ua = "«Лють Морозного вирма» має на $s1% менше перезарядження й Заморожує всіх уражених ворогів на $377048d." },
    { en = "You are able to move while communing with the Dream.", ua = "Ви можете рухатися під час єднання зі Сном." },
    { en = "Emerald Communion increases your maximum health by $377088s1% for $377088d.", ua = "«Смарагдове єднання» збільшує ваше максимальне здоров'я на $377088s1% на $377088d." },
    { en = "Enemies suffer $377359s1% increased damage from Chill Streak each time they are struck by it.", ua = "Вороги зазнають на $377359s1% більше шкоди від «Хвилі холоду» щоразу, коли вона їх уражає." },
    { en = "Chill Streak's bounce range is increased by $s2 yds and each time Chill Streak bounces it has a $s1% chance to increase the maximum number of bounces by $s3.", ua = "Дальність відскоку «Хвилі холоду» збільшена на $s2 ярдів, і щоразу, коли «Хвиля холоду» відскакує, є $s1% шанс збільшити максимальну кількість відскоків на $s3." },
    { en = "Shadow Word: Pain deals an additional $s1% damage. When an enemy dies while afflicted by your Shadow Word: Pain, you gain $?a137033[${$s3/100} Insanity.][${$s5/10}.1% Mana.]", ua = "Слово Тіні: Біль завдає додатково $s1% шкоди. Коли ворог гине під дією вашого Слова Тіні: Біль, ви отримуєте $?a137033[${$s3/100} Безумства.][${$s5/10}.1% Мани.]" },
    { en = "Death Coil and Epidemic debilitate your enemy applying Death Rot causing them to take $377540s1% increased Shadow damage, up to ${$377540s1*$377540u}% from you for $377540d. If Death Coil or Epidemic consume Sudden Doom it applies two stacks of Death Rot.", ua = "«Смертельна змія» та «Епідемія» знесилюють вашого ворога, накладаючи «Смертний тлін», через що він зазнає на $377540s1% більше шкоди Тіні від вас, до ${$377540s1*$377540u}%, протягом $377540d. Якщо «Смертельна змія» чи «Епідемія» поглинають «Раптову приреченість», накладається два стаки «Смертного тліну»." },
    { en = "For ${$s1/1000} sec after leaving Cat Form or Travel Form, you retain up to $s2% movement speed.", ua = "Протягом ${$s1/1000} сек після виходу з Котячої подоби чи Подорожньої подоби ви зберігаєте до $s2% швидкості пересування." },
    { en = "Your Vigor is increased to $s2.", ua = "Ваша Снага збільшується до $s2." },
    { en = "Your Vigor regeneration rate is accelerated to $s1 Vigor every $s2 sec while grounded.", ua = "Швидкість відновлення Снаги пришвидшується до $s1 Снаги кожні $s2 сек, поки ви на землі." },
    { en = "Thrill of the Skies generates $s1 Vigor every $s2 sec.", ua = "«Захват небес» генерує $s1 Снаги кожні $s2 сек." },
    { en = "Pet damage increased by $s1%.", ua = "Шкода улюбленця збільшена на $s1%." },
    { en = "Kill Command damage increased by $s1%.", ua = "Шкода «Наказу вбити» збільшена на $s1%." },
    { en = "Serpent Sting's damage applies Latent Poison to the target, stacking up to $378015u times. $?s137015[Barbed Shot]?s137016[Aimed Shot]?s137017&!s259387[Raptor Strike][Mongoose Bite] consumes all stacks of Latent Poison, dealing $378016s1 Nature damage to the target per stack consumed.", ua = "Шкода Зміїного жала накладає на ціль Приховану отруту, що накопичується до $378015u разів. $?s137015[Колючий постріл]?s137016[Прицільний постріл]?s137017&!s259387[Удар раптора][Укус мангуста] поглинає всі заряди Прихованої отрути, завдаючи цілі $378016s1 шкоди природою за кожен поглинутий заряд." },
    { en = "Your Hex target is slowed by $378080s1% during Hex and for $378080d after it ends.", ua = "Ціль вашого «Врока» сповільнена на $378080s1% під час «Врока» і на $378080d після його завершення." },
    { en = "Increases the healing done by Healing Stream Totem$?a137039[ and Cloudburst Totem by $s1]?a137040[ by ${$s1*(1+$137040s21/100)}][ by ${$s1*(1+$137041s17/100)}]%.", ua = "Збільшує зцілення, що надає Тотем зцілювального потоку$?a137039[ і Тотем зливи на $s1]?a137040[ на ${$s1*(1+$137040s21/100)}][ на ${$s1*(1+$137041s17/100)}]%." },
    { en = "Barbed Shot damage increased by $s1%.", ua = "Шкода «Зазубреного пострілу» збільшена на $s1%." },
    { en = "$?a466932[Black Arrow][Kill Shot] deals $468219s3% increased damage for each of your active pets. Stacks up to $468219u times.", ua = "$?a466932[Чорна стріла][Смертельний постріл] завдає на $468219s3% більше шкоди за кожного вашого активного улюбленця. Накопичується до $468219u разів." },
    { en = "Increases the damage of your Lightning Bolt$?c3[ and Chain Lightning] ?c1[, Chain Lightning, and Storm Elemental] by $s1%.", ua = "Збільшує шкоду вашого Розряду блискавки$?c3[ і Ланцюгової блискавки] ?c1[, Ланцюгової блискавки та Штормового елементаля] на $s1%." },
    { en = "When you cast Earth Shock, Elemental Blast, or Earthquake, gain $?a408572[Volcanic][Lava] Surge and increase the damage of your next Lava Burst by $378269s1%.", ua = "Коли ви творите Земляний шок, Елементальний вибух або Землетрус, отримуєте $?a408572[Вулканічний][Лавовий] прилив і збільшуєте шкоду наступного Виверження лави на $378269s1%." },
    { en = "Dealing direct Fire, Frost, and Nature damage within $378272d will increase all damage dealt by $s4% for $378275d. This can only occur once every $378277d.", ua = "Завдання прямої шкоди вогнем, льодом і природою протягом $378272d збільшує всю завдану шкоду на $s4% на $378275d. Це може статися лише раз на $378277d." },
    { en = "Flame Shock damage over time critical strikes reduce the cooldown of your Fire and Storm Elemental by $?s192249[${$m1/1000}.1][${$m2/1000}.1] sec, and Flame Shock has a $s3% increased critical strike chance.", ua = "Критичні удари періодичної шкоди Полум'яного шоку зменшують перезарядження вашого Вогняного та Штормового елементаля на $?s192249[${$m1/1000}.1][${$m2/1000}.1] сек., а шанс критичного удару Полум'яного шоку збільшено на $s3%." },
    { en = "While skyriding at middle speed and above, you gain stacks of Skyrider's Initiative, up to $388672u.\n\n\n\nWhen landing at mid-to-high speeds, you create a shockwave, damaging enemies for $<points> per stack, split among them, and disorienting them for $388673d. Landing at low speeds cancels Skyrider's Initiative.", ua = "Під час небесної їзди на середній швидкості та вище ви отримуєте заряди «Ініціативи небесного вершника», до $388672u.\n\n\n\nЗастрибуючи при середній і вищій швидкості, ви створюєте ударну хвилю, що завдає ворогам $<points> шкоди за заряд, розподіленої між ними, і дезорієнтує їх на $388673d. Приземлення на низькій швидкості скасовує «Ініціативу небесного вершника»." },
    { en = "Every $s1 Dire Beasts summoned resets the cooldown of Kill Command, and reduces the Focus cost and cooldown of Kill Command by $378747s1% for $378747d.", ua = "Кожні $s1 прикликані Люті звірі скидають перезарядження «Наказу вбити» та зменшують витрату Зосередженості й перезарядження «Наказу вбити» на $378747s1% на $378747d." },
    { en = "Cobra Shot has a $s2% chance to make your next Kill Command consume no Focus.", ua = "«Постріл кобри» має $s2% шансу зробити так, що ваш наступний «Наказ вбити» не витратить Зосередженості." },
    { en = "Gives your Chill effects a $h% chance to freeze the target for $378760d.", ua = "Надає вашим ефектам Холоду $h% шансу заморозити ціль на $378760d." },
    { en = "Whenever you successfully Freezing Trap an enemy, gain $s1 Focus and increase all Focus gained by $s2% for $378761d.", ua = "Щоразу, коли ви успішно ловите ворога «Крижаною пасткою», ви отримуєте $s1 Зосередженості та збільшуєте всю отриману Зосередженість на $s2% на $378761d." },
    { en = "Kill Shot critical strike chance and critical strike damage increased by $s1%.", ua = "Шанс критичного удару та шкода критичного удару «Смертельного пострілу» збільшені на $s1%." },
    { en = "Aimed Shot and Rapid Fire critical strike chance increased by $s1%.", ua = "Шанс критичного удару «Прицільного пострілу» та «Швидкого вогню» збільшений на $s1%." },
    { en = "When you fall below $s1% health, Bursting Shot and Scatter Shot have their cooldown immediately reset. This can only occur once every $385646d.", ua = "Коли ваше здоров'я падає нижче $s1%, перезарядження Bursting Shot і Scatter Shot миттєво скидається. Може статися лише раз на $385646d." },
    { en = "Your successful Purge, Cleanse Spirit, Healing Stream Totem, Hex, and Wind Shear casts generate $378777s1 Maelstrom during combat.", ua = "Успішне прочитання Purge, Cleanse Spirit, Healing Stream Totem, Hex і Wind Shear генерує $378777s1 Мальстрому в бою." },
    { en = "Thunderstorm knocks enemies up instead of away and its cooldown is reduced by ${$s1/-1000} sec.", ua = "Thunderstorm підкидає ворогів угору замість того, щоб відкидати, а його перезарядження зменшено на ${$s1/-1000} сек." },
    { en = "Aimed Shot also fires a Serpent Sting at the primary target.\n\n\n\n$@spellicon271788 $@spellname271788\n\n$@spelldesc271788", ua = "Прицільний постріл також випускає Зміїне жало по основній цілі.\n\n\n\n$@spellicon271788 $@spellname271788\n\n$@spelldesc271788" },
    { en = "Each Wind Arrow fired reduces the cooldown of Rapid Fire by ${$m1/1000}.1 sec, and every $s2 Wind Arrows fired increases the duration of your next Trueshot by ${$424571m1/1000}.1 sec, up to a maximum of ${$424571m1/1000*$424571u}.1 sec.", ua = "Кожна випущена Wind Arrow зменшує перезарядження Rapid Fire на ${$m1/1000}.1 сек, а кожні $s2 випущених Wind Arrows збільшують тривалість вашого наступного Trueshot на ${$424571m1/1000}.1 сек, до максимуму ${$424571m1/1000*$424571u}.1 сек." },
    { en = "Critical strike damage increased by $s1%.", ua = "Шкода від критичного удару збільшена на $s1%." },
    { en = "Trick Shots now ricochets to $s1 fewer targets, but each ricochet deals an additional $s3% damage.", ua = "Trick Shots тепер рикошетить на $s1 менше цілей, але кожен рикошет завдає додатково $s3% шкоди." },
    { en = "All damage done by your pet is increased by $s1%.", ua = "Уся шкода, завдана вашим улюбленцем, збільшена на $s1%." },
    { en = "When you cast Kill Command, you have a $s1% chance to throw a hatchet at your target, dealing ${$193265s1*($s2/100)} Physical damage.", ua = "Коли ви творите Kill Command, є $s1% шанс метнути сокирку в ціль, завдаючи ${$193265s1*($s2/100)} фізичної шкоди." },
    { en = "Critical damage dealt increased by $s1%.", ua = "Завдана критична шкода збільшена на $s1%." },
    { en = "Damage of Flanking Strike and Butchery increased by $s1% and all damage dealt by Wildfire Bomb increased by $s2%.", ua = "Шкода Flanking Strike і Butchery збільшена на $s1%, а вся шкода, завдана Wildfire Bomb, збільшена на $s2%." },
    { en = "Mongoose Bite damage increased by $s1%.", ua = "Шкода Mongoose Bite збільшена на $s1%." },
    { en = "You and your pets maximum Focus is increased by $s1.", ua = "Ваш максимальний Фокус та фокус ваших улюбленців збільшено на $s1." },
    { en = "The cooldown of Spearhead is reduced by ${$s1/-1000} sec and Spearhead's bleed now increases you and your pet's critical strike damage against the target by $s2%.", ua = "Перезарядження Spearhead зменшено на ${$s1/-1000} сек, а кровотеча від Spearhead тепер збільшує шкоду критичного удару вас і вашого улюбленця по цілі на $s2%." },
    { en = "Surge Forward evades Scalechillers, Scalechargers, and other obstacles encountered in time trials and races.", ua = "Surge Forward ухиляється від Scalechillers, Scalechargers та інших перешкод, що трапляються в перегонах на час і гонках." },
    { en = "Whirling Surge evades Wingshredders and dismounts airborne enemy players.", ua = "Whirling Surge ухиляється від Wingshredders і скидає ворожих гравців, що летять." },
    { en = "$?s137012[Store $s1% of your effective healing, up to $<cap>. Your next Moonfire consumes all stored healing to increase its damage dealt.][Store $s1% of your damage, up to $<cap2>. Your next Regrowth consumes all stored damage to increase its healing.]", ua = "$?s137012[Накопичує $s1% вашого дієвого зцілення, до $<cap>. Ваш наступний Місячний вогонь поглинає все накопичене зцілення, щоб збільшити завдану шкоду.][Накопичує $s1% вашої шкоди, до $<cap2>. Ваше наступне Відростання поглинає всю накопичену шкоду, щоб збільшити своє зцілення.]" },
    { en = "While in your Consecration, your $?s2812[Denounce][Shield of the Righteous] and Word of Glory have $s1% increased initial damage and healing.", ua = "Поки ви у своєму Освяченні, ваш $?s2812[Осуд][Щит праведника] і Слово слави мають на $s1% більше початкової шкоди та зцілення." },
    { en = "Frostbolt and Flurry have a $s2% chance to generate $s1 Icicles.", ua = "«Крижана стріла» і «Шквал» мають $s2% шансу створити $s1 бурульок." },
    { en = "Your Frost spells deal $s1% more damage to targets that are rooted and frozen.", ua = "Ваші закляття Морозу завдають на $s1% більше шкоди цілям, що знерухомлені й заморожені." },
    { en = "Casting Ice Lance on Frozen targets has a $s1% chance to generate an Icicle.", ua = "Творіння «Крижаного списа» проти заморожених цілей має $s1% шансу створити бурульку." },
    { en = "Casting Flame Shock reduces the mana cost of your next heal by $s2% and increases its healing effectiveness by $?s137039[${$s5/10}.1][$s3]%.", ua = "Творення Полум'яного шоку зменшує вартість мани вашого наступного зцілення на $s2% і збільшує його дієвість зцілення на $?s137039[${$s5/10}.1][$s3]%." },
    { en = "Increases the damage of your Lightning Bolt by $s1%.", ua = "Збільшує шкоду вашої «Блискавки» на $s1%." },
    { en = "Reduces the cooldown of Spirit Walk by ${$s1/-1000} sec.\n\n\n\nReduces the cooldown of Gust of Wind by ${$s2/-1000} sec.", ua = "Зменшує перезарядження «Ходи духа» на ${$s1/-1000} с.\n\n\n\nЗменшує перезарядження «Пориву вітру» на ${$s2/-1000} с." },
    { en = "Casting Frost Shock or Icefury increases the damage of your next Lava Burst by $381777s1%.", ua = "Творіння «Морозного струсу» чи «Крижаної люті» збільшує шкоду вашого наступного «Виверження лави» на $381777s1%." },
    { en = "Reduces the cooldown of Ascendance by ${$s2/-1000} sec, and you gain $s1% additional Haste while Ascendance is active.", ua = "Зменшує перезарядження «Піднесення» на ${$s2/-1000} с, і ви отримуєте додатково $s1% Поспіху, доки активне «Піднесення»." },
    { en = "Casting Earth Shock or Earthquake while Ascendance is active extends the duration of Ascendance by ${$s1/1000}.1 sec.\n\n\n\nCasting Elemental Blast while Ascendance is active extends the duration of Ascendance by ${$s2/1000}.1 sec.\n\n\n\nAscendance can only be extended up to $s3% of its original duration.", ua = "Творіння «Земного струсу» чи «Землетрусу», доки активне «Піднесення», подовжує тривалість «Піднесення» на ${$s1/1000}.1 с.\n\n\n\nТворіння «Стихійного вибуху», доки активне «Піднесення», подовжує тривалість «Піднесення» на ${$s2/1000}.1 с.\n\n\n\n«Піднесення» можна подовжити лише до $s3% його початкової тривалості." },
    { en = "When Capacitor Totem fades or is destroyed, another Capacitor Totem is automatically dropped in the same place.", ua = "Коли «Тотем-конденсатор» зникає або знищується, на тому ж місці автоматично встановлюється новий «Тотем-конденсатор»." },
    { en = "Gathering herbs or minerals will replenish 1 vigor.", ua = "Збирання трав чи мінералів поповнює 1 бадьорість." },
    { en = "Defeating an enemy will grant you 1 vigor.\n\n\n\nThis effect can only occur once every $s3 sec.", ua = "Перемога над ворогом дарує вам 1 бадьорість.\n\n\n\nЦей ефект може спрацьовувати лише раз на $s3 с." },
    { en = "Flame Shock damage increases the damage of your next Earth Shock, Elemental Blast, or Earthquake by ${$S1/10}.1%, stacking up to $381933u times.", ua = "Шкода від «Вогняного струсу» збільшує шкоду вашого наступного «Земного струсу», «Стихійного вибуху» чи «Землетрусу» на ${$S1/10}.1%. Накопичується до $381933u разів." },
    { en = "Imbuing your weapon with Flametongue increases your Fire spell damage by ${$382028s1}.1% for $382028d.", ua = "Наділення вашої зброї «Вогняним язиком» збільшує шкоду ваших заклять Вогню на ${$382028s1}.1% на $382028d." },
    { en = "Increases the damage dealt by Lightning Shield by $s3%$?s137040[ and causes it to generate an additional $s1 Maelstrom when triggered][]$?s137041[ and it has an additional $s2% chance to trigger Maelstrom Weapon when triggered][].\n\n\n\nIncreases the healing done by Earth Shield by $s4%.\n\n\n\n$?s137039[Increases the amount of mana recovered when Water Shield is triggered by $s5%.][]", ua = "Збільшує шкоду, завдану Щитом блискавки, на $s3%$?s137040[ і змушує його при спрацюванні створювати додатково $s1 Виру][]$?s137041[ і надає йому додатковий шанс $s2% активувати Зброю Виру при спрацюванні][].\n\n\n\nЗбільшує зцілення від Щита землі на $s4%.\n\n\n\n$?s137039[Збільшує кількість мани, відновленої при спрацюванні Щита води, на $s5%.][]" },
    { en = "Primordial Wave has a ${$s1/10}% chance to not incur its cooldown.", ua = "«Первинна хвиля» має ${$s1/10}% шансу не спричинити своє перезарядження." },
    { en = "Reduces the cooldown of Primordial Wave by ${$s1/-1000} sec.", ua = "Зменшує перезарядження «Первинної хвилі» на ${$s1/-1000} с." },
    { en = "Icefury causes your Frost Shocks to damage up to $s1 additional enemies and targets hit take $382089s1% increased Nature damage from your spells for $382089d.", ua = "Крижана лють змушує ваші Морозні розряди завдавати шкоди ще $s1 ворогам, а вражені цілі отримують на $382089s1% більше шкоди від Природи від ваших заклять протягом $382089d." },
    { en = "Casting $382113u Frostbolts or Flurries summons a Frozen Orb that travels toward your target. Hitting an enemy player counts as double.", ua = "Прочитання $382113u Крижаних стріл чи Хуртовин прикликає Заморожену сферу, що рухається до вашої цілі. Влучання у ворожого гравця рахується подвійно." },
    { en = "While Icy Veins is active, each Frostbolt you cast reduces the cast time of Frostbolt by $382148s1% and increases its damage by $382148s2%, stacking up to $382148u times.", ua = "Поки активні Крижані жили, кожна прочитана Крижана стріла зменшує час прочитання Крижаної стріли на $382148s1% і підвищує її шкоду на $382148s2%, накопичуючись до $382148u разів." },
    { en = "Primordial Wave increases the healing done by your next Healing Wave by $s1%.", ua = "Первісна хвиля підвищує зцілення від вашої наступної Хвилі зцілення на $s1%." },
    { en = "Your Barriers heal you for $s1% of the damage absorbed.", ua = "Ваші Бар'єри зцілюють вас на $s1% поглинутої шкоди." },
    { en = "Gain a shield that absorbs $s1% of your maximum health for $382290d after you Blink.", ua = "Після Стрибка ви отримуєте щит, що поглинає шкоду в розмірі $s1% вашого максимального здоров'я протягом $382290d." },
    { en = "Rallying Cry's duration is increased by ${$s1/1000} sec and it grants an additional $s3% maximum health.", ua = "Тривалість Заклику до бою збільшено на ${$s1/1000} сек, і він дає додатково $s3% максимального здоров'я." },
    { en = "Rummage through $M1 pieces of scrap in effort to find $?pc102402[usable parts][sellable junk]$?pc100191[, and sometimes bonus treasure!][.]", ua = "Порпаєтесь у $M1 шматках брухту, намагаючись знайти $?pc102402[придатні деталі][мотлох на продаж]$?pc100191[, а іноді й додатковий скарб!][.]" },
    { en = "Mirror Image's cooldown is reduced by ${$s1/1000} sec whenever a Mirror Image dissipates due to direct damage.", ua = "Перезарядження Дзеркального відображення зменшується на ${$s1/1000} сек щоразу, коли Дзеркальне відображення розсіюється через пряму шкоду." },
    { en = "Your barrier's cooldown recharges $s1% faster while the shield persists.", ua = "Перезарядження вашого бар'єра відновлюється на $s1% швидше, поки тримається щит." },
    { en = "You are healed for $382998s1% of your maximum health whenever a Mirror Image dissipates due to direct damage.", ua = "Ви зцілюєтеся на $382998s1% вашого максимального здоров'я щоразу, коли Дзеркальне відображення розсіюється через пряму шкоду." },
    { en = "Increases your movement speed by $s2% for $384360d after casting Blink.", ua = "Підвищує вашу швидкість пересування на $s2% протягом $384360d після прочитання Стрибка." },
    { en = "Stamina increased by $s1% and the duration of $?c1|c3[Fear, Sap and Incapacitate effects on you is reduced by $s2%][movement impairing effects on you is reduced by $s6%].", ua = "Витривалість збільшено на $s1%, а тривалість $?c1|c3[ефектів Страху, Приголомшення та Знесилення на вас зменшено на $s2%][ефектів, що сповільнюють пересування, на вас зменшено на $s6%]." },
    { en = "Increases Leech by $s2% and reduces damage taken from area-of-effect attacks by $s1%.", ua = "Підвищує Висмоктування на $s2% і зменшує шкоду від атак по площі на $s1%." },
    { en = "Champion's Spear's damage increased by $s1% and its Rage generation is increased by $s2%.", ua = "Шкоду Списа чемпіона підвищено на $s1%, а його вироблення Люті збільшено на $s2%." },
    { en = "$?c3[Ravager's damage is reduced by $s1% but it now has $s4 charges and generates ${$s5/10} additional Rage each time it deals damage.][Bladestorm and Ravager's damage are reduced by $s1% but they now have $s4 charges and generate ${$s5/10} additional Rage each time they deal damage.]", ua = "$?c3[Шкоду Спустошувача зменшено на $s1%, але тепер він має $s4 заряди й генерує ${$s5/10} додаткової Люті щоразу, коли завдає шкоди.][Шкоду Клинкової бурі та Спустошувача зменшено на $s1%, але тепер вони мають $s4 заряди й генерують ${$s5/10} додаткової Люті щоразу, коли завдають шкоди.]" },
    { en = "Intimidating Shout can withstand $s1% more damage before breaking.", ua = "Залякувальний крик витримує на $s1% більше шкоди, перш ніж зруйнуватися." },
    { en = "If Whirlwind $?c1[or Cleave ][]$?s436707[or Thunder Clap ][]$?a137048[or Revenge ][]hits $s1 or more enemies it hits them $s2 additional time for ${100+$s3}% damage.", ua = "Якщо Вихор $?c1[або Розсічення ][]$?s436707[або Громовий удар ][]$?a137048[або Помста ][]влучає у $s1 або більше ворогів, він влучає в них $s2 додаткові рази, завдаючи ${100+$s3}% шкоди." },
    { en = "Charge yourself with lightning, causing your next $n Lightning Bolts or Chain Lightnings to deal $s2% more damage and be instant cast.", ua = "Заряджаєте себе блискавкою, і ваші наступні $n Розряди блискавки чи Ланцюгові блискавки завдають на $s2% більше шкоди та стають миттєвими." },
    { en = "Reduces the cooldown of $@spellname108285 by ${$s1/-1000} sec.", ua = "Зменшує перезарядження $@spellname108285 на ${$s1/-1000} сек." },
    { en = "$@spellname108285 affects an additional totem.", ua = "$@spellname108285 впливає на додатковий тотем." },
    { en = "Summons a totem at your feet for $d that grants $383018s1% physical damage reduction to you and the $s1 allies nearest to the totem within $<radius> yards.", ua = "Прикликає до ваших ніг тотем на $d, що дає $383018s1% зниження фізичної шкоди вам і $s1 найближчим до тотема союзникам у межах $<radius> ярдів." },
    { en = "Summons a totem at your feet for $d that prevents cast pushback and reduces the duration of all incoming interrupt effects by $383020s2% for you and the $s1 allies nearest to the totem within $<radius> yards.", ua = "Прикликає до ваших ніг тотем на $d, що запобігає затримці прочитання й зменшує тривалість усіх вхідних ефектів переривання на $383020s2% для вас і $s1 найближчих до тотема союзників у межах $<radius> ярдів." },
    { en = "Cooldown of Pummel reduced by ${$s1/-1000}.1 sec. \n\n\n\nSuccessfully interrupting an enemy increases the damage you deal to them by $383116s2% for $383116d.", ua = "Перезарядження Pummel зменшено на ${$s1/-1000}.1 с. \n\n\n\nУспішне переривання ворога збільшує шкоду, яку ви йому завдаєте, на $383116s2% на $383116d." },
    { en = "Starsurge has a $s1% chance to apply Stellar Flare to the target.\n\n\n\nStarfall has a $s2% chance to extend Moonfire and Sunfire by $s3 sec, up to $s4 sec.", ua = "Starsurge має $s1% шанс накласти Stellar Flare на ціль.\n\n\n\nStarfall має $s2% шанс продовжити Moonfire і Sunfire на $s3 с, до $s4 с." },
    { en = "Mortal Strike and Cleave have a $h% chance to instantly reset their own cooldowns.", ua = "Mortal Strike і Cleave мають $h% шанс миттєво скинути власне перезарядження." },
    { en = "At any moment, you have a chance to gain $?c1[Arcane Surge for $s1 sec, Clearcasting]?c2[Combustion for $s4 sec, 1 Fire Blast charge]?c3[Icy Veins for $s5 sec, Brain Freeze][], or Time Warp for 6 sec.", ua = "Будь-якої миті ви маєте шанс отримати $?c1[Арканний прилив на $s1 сек., Ясне творення]?c2[Займання на $s4 сек., 1 заряд Вогняного вибуху]?c3[Крижані жили на $s5 сек., Заморозку розуму][] або Викривлення часу на 6 сек." },
    { en = "Crusader Strike now has ${$s1+1} charges.", ua = "Crusader Strike тепер має ${$s1+1} зарядів." },
    { en = "Execute increases Execute's damage dealt by $383290s1% for $383290d, stacking up to $383290u times.", ua = "Execute збільшує завдану Execute шкоду на $383290s1% на $383290d, накопичуючись до $383290u разів." },
    { en = "Cooldown of Cleave reduced by ${$s1/-1000} sec.", ua = "Перезарядження Cleave зменшено на ${$s1/-1000} с." },
    { en = "Hammer of Wrath deals $s1% increased damage and generates ${$403081s1} additional Holy Power.", ua = "Hammer of Wrath завдає на $s1% більше шкоди й генерує ${$403081s1} додаткової Святої Сили." },
    { en = "Whirlwind and Cleave deal $383316s1% increased damage for $<bstorm> sec after Bladestorm ends.", ua = "Whirlwind і Cleave завдають на $383316s1% більше шкоди протягом $<bstorm> с після завершення Bladestorm." },
    { en = "Every ${$s2*$t1/$s1} sec in combat, you gain 1 Holy Power.", ua = "Кожні ${$s2*$t1/$s1} с у бою ви отримуєте 1 Святу Силу." },
    { en = "Increases Versatility by $s1% and reduces the cooldown of Die by the Sword by ${$s2/-1000}.1 sec.", ua = "Збільшує Універсальність на $s1% і зменшує перезарядження Die by the Sword на ${$s2/-1000}.1 с." },
    { en = "Skyriding abilities spend Skyriding Charges. These recharge over time.", ua = "Здібності Небесної їзди витрачають Заряди Небесної їзди. Вони відновлюються з часом." },
    { en = "When mounted on a skyriding mount, double jump to launch upward and start gliding forward.", ua = "Сидячи на їздовій тварині для Небесної їзди, зробіть подвійний стрибок, щоб злетіти вгору й почати планерувати вперед." },
    { en = "While skyriding at high speeds, your Skyriding Charges recharge faster.", ua = "Під час Небесної їзди на високій швидкості ваші Заряди Небесної їзди відновлюються швидше." },
    { en = "Colossus Smash's duration is reduced by $s1% but its damage bonus is increased by $s3%.", ua = "Тривалість Colossus Smash зменшено на $s1%, але його бонус до шкоди збільшено на $s3%." },
    { en = "Haste increased by $s1% and Raging Blow and Bloodthirst generate an additional ${$s2/10} Rage.", ua = "Поспіх збільшено на $s1%, а Raging Blow і Bloodthirst створюють додатково ${$s2/10} Люті." },
    { en = "Your critical strike damage is increased by $s2%. When you activate Combustion, you gain $s3% additional critical strike damage, and up to $383493I nearby allies gain $s4% critical strike for $383493d.", ua = "Шкода вашого критичного удару збільшена на $s2%. Коли ви активуєте «Займання», ви отримуєте $s3% додаткової шкоди критичного удару, а до $383493I поблизьких союзників отримують $s4% критичного удару на $383493d." },
    { en = "Consuming Hot Streak grants you $s3% increased Intellect for $383501d. This effect stacks up to $s2 times.", ua = "Спожиття Hot Streak збільшує ваш Інтелект на $s3% на $383501d. Цей ефект накладається до $s2 разів." },
    { en = "Casting Scorch on targets below $s1% health increase the target's damage taken from you by $383608s1% for $383608d. This effect stacks up to $383608u times.", ua = "Застосування Scorch на цілях зі здоров'ям нижче $s1% збільшує шкоду, якої ціль зазнає від вас, на $383608s1% на $383608d. Цей ефект накладається до $383608u разів." },
    { en = "Increases auto-attack damage with one-handed weapons by $s1% and your auto-attack critical strikes have a $s2% chance to Enrage you.", ua = "Збільшує шкоду автоатак одноручною зброєю на $s1%, а критичні удари ваших автоатак мають $s2% шанс ввести вас у Лють." },
    { en = "Refines $M2 Serevite Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Serevite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 Serevite Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 Serevite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Pyroblast has a $s1% reduced cast time and a $s2% increased critical strike chance. The duration of Combustion is reduced by $s3%.", ua = "Час прочитання Pyroblast зменшено на $s1%, а шанс критичного удару збільшено на $s2%. Тривалість Combustion зменшено на $s3%." },
    { en = "Increases Arcane Missiles damage by $s1%.", ua = "Збільшує шкоду Arcane Missiles на $s1%." },
    { en = "Enemies damaged by Flame Patch have a $h% chance to erupt into a Living Bomb.", ua = "Вороги, яким Flame Patch завдає шкоди, мають $h% шанс вибухнути Living Bomb." },
    { en = "$?pc103935[Crafting this may inspire you with the knowledge of another profession's Draconic Treatise.][]", ua = "$?pc103935[Виготовлення цього може надихнути вас знанням драконічного трактату іншої професії.][]" },
    { en = "Restores $s1% health instantly and removes all diseases, poisons, and curses affecting you.", ua = "Миттєво відновлює $s1% здоров'я та знімає всі хвороби, отрути й прокляття, що діють на вас." },
    { en = "Consuming Clearcasting increases the damage of your next $383783u Arcane Blasts or Arcane Barrages by $s1%.", ua = "Спожиття Clearcasting збільшує шкоду ваших наступних $383783u застосувань Arcane Blast чи Arcane Barrage на $s1%." },
    { en = "Refines $M2 Serevite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Serevite Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 Serevite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 Serevite Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M2 Draconium Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Draconium Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 Draconium Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 Draconium Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M2 Draconium Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Draconium Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 Draconium Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 Draconium Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M2 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M2 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Khaz'gorite Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 руди Хаз'ґориту |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 руди Хаз'ґориту |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "While Combustion is not active, consuming Hot Streak has a low chance to cause all Pyroblasts and Flamestrikes to have no cast time and be guaranteed critical strikes for $383874d. \n\n\n\nEach cast of Pyroblast or Flamestrike during Hyperthermia increases the damage of Pyroblast and Flamestrike by $1242220s1%, up to ${$1242220u*$1242220s1}%.", ua = "Поки Спалах не активний, використання Гарячої смуги має невеликий шанс зробити всі Піровибухи та Полум'яні удари миттєвими й гарантовано критичними на $383874d. \n\n\n\nКожне творіння Піровибуху чи Полум'яного удару під час Гіпертермії збільшує шкоду Піровибуху та Полум'яного удару на $1242220s1%, аж до ${$1242220u*$1242220s1}%." },
    { en = "After consuming $s1 Hot Streaks, your next non-instant Pyroblast or Flamestrike cast within $383883d grants you Combustion for $s2 sec and deals $383883s2% additional damage.", ua = "Після використання $s1 Гарячих смуг ваш наступний немиттєвий Піровибух чи Полум'яний удар, витворений протягом $383883d, дарує вам Спалах на $s2 сек. і завдає $383883s2% додаткової шкоди." },
    { en = "Your auto-attacks deal an additional $383915s1 Physical damage and generate ${$383915s2/10} Rage.", ua = "Ваші автоатаки завдають додатково $383915s1 фізичної шкоди та генерують ${$383915s2/10} Люті." },
    { en = "Recklessness lasts ${$s1/1000}.1 sec longer.", ua = "Безрозсудність триває на ${$s1/1000}.1 сек. довше." },
    { en = "Meteor gains a second charge, with a ${$s1/1000} sec cooldown between uses.", ua = "Метеор отримує другий заряд із ${$s1/1000} сек. перезарядженням між використаннями." },
    { en = "Last Stand increases your Rage generation by $384043s1%.", ua = "Останній рубіж збільшує вашу генерацію Люті на $384043s1%." },
    { en = "Slows enemies in a $A1 yard cone in front of you by $s1% for $d.", ua = "Уповільнює ворогів у конусі $A1 ярдів перед вами на $s1% на $d." },
    { en = "After casting Earth Shock, your next Earthquake deals $s1% additional damage.\n\n\n\nAfter casting Elemental Blast, your next Earthquake deals $s2% additional damage.", ua = "Після творіння Земного струсу ваш наступний Землетрус завдає $s1% додаткової шкоди.\n\n\n\nПісля творіння Стихійного вибуху ваш наступний Землетрус завдає $s2% додаткової шкоди." },
    { en = "Throws your weapon at the enemy, causing $s1 Physical damage to it and $s2 nearby enemies. \n\n\n\nGenerates high threat.", ua = "Кидає вашу зброю у ворога, завдаючи $s1 фізичної шкоди йому та $s2 ворогам поблизу. \n\n\n\nГенерує високу загрозу." },
    { en = "Evocation grants $384265s1 Arcane Charge, channels $s1% faster and while channeling Evocation, your Intellect is increased by $384267s1% every $12051t2 sec. Lasts $384267d.", ua = "Виклик дарує $384265s1 Арканний заряд, каналізується на $s1% швидше, і під час каналізування Виклику ваш Інтелект збільшується на $384267s1% кожні $12051t2 сек. Триває $384267d." },
    { en = "Consuming a Mana Gem grants up to $s1 Clearcasting stacks.", ua = "Використання Самоцвіту мани дарує до $s1 стосів Ясного творіння." },
    { en = "Thunder Clap affects $s3 nearby targets with Rend, causing them to Bleed for $388539o1 damage over $388539d.", ua = "Громовий ляск накладає Роздирання на $s3 цілей поблизу, змушуючи їх кровоточити на $388539o1 шкоди протягом $388539d." },
    { en = "Roar explosively, dealing $s1 Physical damage to enemies within $A1 yds and cause them to bleed for $397364o1 physical damage over $397364d. Deals reduced damage beyond $s3 targets.", ua = "Вибухово ричить, завдаючи $s1 фізичної шкоди ворогам у межах $A1 ярдів і змушуючи їх кровоточити на $397364o1 фізичної шкоди протягом $397364d. Завдає зменшеної шкоди понад $s3 цілей." },
    { en = "Consuming at least $s2 $Lstack:stacks; of Hailstorm, and each explosion from Fire Nova now also grants you $s1 $lstack:stacks; of Maelstrom Weapon.", ua = "Споживання щонайменше $s2 $Lзаряду:зарядів; «Градобою», а також кожен вибух «Вогняної нови» тепер додатково надає вам $s1 $lзаряд:заряди; «Зброї Мальстрому»." },
    { en = "Arcane Blast has a small chance to make your next cast of Arcane Blast free.", ua = "Арканний вибух має невеликий шанс зробити ваше наступне творіння Арканного вибуху безкоштовним." },
    { en = "Call upon the Light and become an avatar of retribution, increasing your damage and healing done by $s1% for $31884d, and allowing Hammer of Wrath to be cast on any target.\n\n\n\nCombines with other Avenging Wrath abilities, granting all known Avenging Wrath effects while active.", ua = "Прикликає Світло, обертаючи вас на втілення відплати, підвищуючи вашу шкоду й зцілення на $s1% на $31884d і дозволяючи творити «Молот гніву» по будь-якій цілі.\n\n\n\nПоєднується з іншими здібностями «Гнівної відплати», надаючи всі відомі ефекти «Гнівної відплати», доки активне." },
    { en = "Call upon the Light and begin a crusade, increasing your haste $?s384376[and damage ][]by $s1% for $231895d.\n\n\n\nEach Holy Power spent during Crusade increases haste by an additional $s1%.\n\n\n\nMaximum $231895u stacks.\n\n\n\nIf $@spellname31884 is known, also grants $s1% damage per stack.", ua = "Закликайте Світло й розпочніть похід, збільшуючи ваш Поспіх $?s384376[і шкоду ][]на $s1% на $231895d.\n\n\n\nКожна Свята сила, витрачена під час «Походу», збільшує Поспіх ще на $s1%.\n\n\n\nЩонайбільше $231895u зарядів.\n\n\n\nЯкщо ви знаєте $@spellname31884, також надає $s1% шкоди за заряд." },
    { en = "Your auto-attacks have a $H% chance to hurl weapons at your target and ${$384391i-1} other enemy in front of you, dealing $384391s1 Physical damage.", ua = "Ваші автоатаки мають $H% шансу метнути зброю у вашу ціль та ${$384391i-1} іншого ворога перед вами, завдаючи $384391s1 фізичної шкоди." },
    { en = "Primordial Wave generates $s1 stacks of Maelstrom Weapon.", ua = "«Первісна хвиля» створює $s1 стосів «Зброї Виру»." },
    { en = "Increases the chance to gain a stack of Maelstrom Weapon by $s1%, and whenever you gain a stack of Maelstrom Weapon, the cooldown of Feral Spirits is reduced by ${$m2/1000}.1 sec.", ua = "Підвищує шанс отримати стос «Зброї Виру» на $s1%, і щоразу, коли ви отримуєте стос «Зброї Виру», перезарядження «Дикого духа» скорочується на ${$m2/1000}.1 сек." },
    { en = "Arcane Barrage deals an additional $s2% damage against targets below $s1% health.", ua = "«Арканний обстріл» завдає додатково $s2% шкоди цілям зі здоров'ям нижче $s1%." },
    { en = "Moonfire increases your Arcane damage to the target, and Sunfire increases your Nature damage to the target, by $s1%.", ua = "«Місячний вогонь» підвищує вашу арканну шкоду по цілі, а «Сонячний вогонь» підвищує вашу шкоду Природою по цілі на $s1%." },
    { en = "Damage dealt to enemies affected by Radiant Spark's vulnerability echo to your current enemy target and ${$384685i-1} nearby enemies for $s1% of the damage dealt.", ua = "Шкода, завдана ворогам під дією вразливості «Осяйної іскри», відлунює по вашій поточній ворожій цілі та ${$384685i-1} ворогам поблизу на $s1% завданої шкоди." },
    { en = "After gaining Deathblow, your next $?a466932[Black Arrow][Kill Shot] will deal $388998s1% increased damage, and shred up to $s1 targets near your $?a466932[Black Arrow][Kill Shot] target for $s2% of the damage dealt by $?a466932[Black Arrow][Kill Shot] over $385638d.", ua = "Отримавши «Смертельний удар», ваш наступний $?a466932[«Чорна стріла»][«Смертельний постріл»] завдасть на $388998s1% більше шкоди й розшматує до $s1 цілей поблизу цілі вашого $?a466932[«Чорної стріли»][«Смертельного пострілу»] на $s2% шкоди, завданої $?a466932[«Чорною стрілою»][«Смертельним пострілом»] упродовж $385638d." },
    { en = "While airborne on a Skyriding mount, you gain stacks of Skyrider's Compassion, up to $s3. \n\n\n\nWhen you dismount, you gain a shield worth $s1% of your health and gain $s2% movement speed per stack, lasting $s4 sec", ua = "Доки ви в повітрі на їздовій тварині для небесної їзди, ви накопичуєте стоси «Співчуття небесного вершника», до $s3. \n\n\n\nКоли ви спішуєтеся, ви отримуєте щит на $s1% вашого здоров'я і $s2% швидкості пересування за кожен стос, що триває $s4 сек" },
    { en = "Standing still for $384863d grants you Foresight, allowing you to cast while moving for ${$384865s1/1000} sec. This duration begins when you start moving.", ua = "Стоячи нерухомо $384863d, ви отримуєте «Передбачення», що дозволяє творити закляття в русі впродовж ${$384865s1/1000} сек. Цей час починається, щойно ви рушаєте." },
    { en = "Golden Path strikes the lowest health ally within it an additional time for $s1% of its effect.", ua = "«Золотий шлях» додатково вражає союзника з найнижчим здоров'ям у своїх межах на $s1% свого ефекту." },
    { en = "Increases the duration of Thunderous Roar's Bleed effect by ${$s1/1000}.1 sec and Thunderous Roar's Bleed effect causes enemies to take $397364s3% increased damage from all your bleeds.", ua = "Збільшує тривалість ефекту кровотечі «Громового рику» на ${$s1/1000}.1 сек, і ефект кровотечі «Громового рику» змушує ворогів отримувати на $397364s3% більше шкоди від усіх ваших кровотеч." },
    { en = "When $?s262161[Warbreaker][Colossus Smash] expires, your Strength is increased by $s1% for every $s3 Rage you spent on attacks during $?s262161[Warbreaker][Colossus Smash]. Lasts $385013d.", ua = "Коли $?s262161[«Зброярозбивач»][«Колосальний удар»] завершується, ваша Сила збільшується на $s1% за кожні $s3 Люті, витраченої на атаки під час $?s262161[«Зброярозбивача»][«Колосального удару»]. Триває $385013d." },
    { en = "When you cast $s1 Holy Power generating abilities, you gain Blessing of Dawn. When you consume Blessing of Dawn, you gain Blessing of Dusk.\n\n\n\n$@spellicon385127$@spellname385127\n\n$@spelldesc385127\n\n\n\n$@spellicon385126$@spellname385126\n\n$@spelldesc385126", ua = "Коли ви застосовуєте $s1 здібностей, що генерують Святу силу, ви отримуєте «Благословення світанку». Коли ви споживаєте «Благословення світанку», ви отримуєте «Благословення сутінків».\n\n\n\n$@spellicon385127$@spellname385127\n\n$@spelldesc385127\n\n\n\n$@spellicon385126$@spellname385126\n\n$@spelldesc385126" },
    { en = "$@spellicon385127$@spellname385127:\n\nBlessing of Dawn increases the damage and healing of your next Holy Power spending ability by an additional $s3%.\n\n\n\n$@spellicon385126$@spellname385126:\n\nBlessing of Dusk increases your armor by $s2% and your Holy Power generating abilities cooldown $s1% faster.", ua = "$@spellicon385127$@spellname385127:\n\n«Благословення світанку» збільшує шкоду й зцілення від вашої наступної здібності, що витрачає Святу силу, ще на $s3%.\n\n\n\n$@spellicon385126$@spellname385126:\n\n«Благословення сутінків» збільшує вашу броню на $s2%, а ваші здібності, що генерують Святу силу, перезаряджаються на $s1% швидше." },
    { en = "Your spells and abilities have a chance to cause your target to erupt in a blinding light dealing $385354s1 Holy damage or healing an ally for $385352s1 health.", ua = "Ваші закляття та здібності мають шанс змусити ціль спалахнути сліпучим світлом, завдаючи $385354s1 шкоди Святом або зцілюючи союзника на $385352s1 здоров'я." },
    { en = "Infect the target's blood, dealing $o1 Nature damage over $d and gaining $s6 use of any Stealth ability. If the target survives its full duration, they suffer an additional $394026s1 damage and you gain $s6 additional use of any Stealth ability for $375939d.\n\n\n\nCooldown reduced by $s3 sec if Sepsis does not last its full duration.\n\n\n\n|cFFFFFFFFAwards $?a121471[${$s7+$121471s4}][$s7] combo $lpoint:points;.|r", ua = "Заражає кров цілі, завдаючи $o1 шкоди Природи впродовж $d та надаючи $s6 застосування будь-якої здібності скрадання. Якщо ціль переживе всю тривалість, вона зазнає додаткових $394026s1 шкоди, а ви отримаєте $s6 додаткового застосування будь-якої здібності скрадання на $375939d.\n\n\n\nПерезарядження скорочується на $s3 сек., якщо «Сепсис» не триває всю свою тривалість.\n\n\n\n|cFFFFFFFFНадає $?a121471[${$s7+$121471s4}][$s7] $lочко:очок; комбо.|r" },
    { en = "Your $?S53595[Hammer of the Righteous]?S204019[Blessed Hammer][Crusader Strike] now also grants you $s1% increased $pri for $385417d. Multiple applications may overlap.", ua = "Ваш $?S53595[«Молот праведних»]?S204019[«Благословенний молот»][«Удар хрестоносця»] тепер додатково надає вам $s1% до $pri на $385417d. Кілька застосувань можуть накладатися." },
    { en = "Embed a bone spike in the target, dealing $s1 Physical damage and $394036s1 Bleed damage every $394036t1 sec until they die or leave combat. \n\n\n\nRefunds a charge when target dies.\n\n\n\n|cFFFFFFFFAwards 1 combo point plus 1 additional per active bone spike.|r", ua = "Встромляє кістяний шпичак у ціль, завдаючи $s1 фізичної шкоди та $394036s1 шкоди кровотечею кожні $394036t1 сек, доки ціль не загине або не вийде з бою. \n\n\n\nПовертає заряд, коли ціль гине.\n\n\n\n|cFFFFFFFFНадає 1 комбо-очко плюс 1 додаткове за кожен активний кістяний шпичак.|r" },
    { en = "Haste increased by $s1% and Judgment cooldown reduced by ${$abs($s2)/1000}.1 sec.", ua = "Поспіх підвищено на $s1%, а перезарядження «Присуду» скорочено на ${$abs($s2)/1000}.1 сек." },
    { en = "Cleave and Whirlwind have a $H% chance to make your next Cleave or Whirlwind cost $439601s1% less Rage.", ua = "«Розсічення» і «Вихор» мають $H% шансу зробити ваше наступне «Розсічення» чи «Вихор» на $439601s1% дешевшим за Люттю." },
    { en = "Damage of Mortal Strike increased by $s1%.", ua = "Шкода «Смертельного удару» підвищена на $s1%." },
    { en = "Kill Shot, Serpent Sting, Arcane Shot, Steady Shot, and Explosive Shot deal $s1% increased damage.", ua = "«Смертельний постріл», «Зміїне жало», «Арканний постріл», «Влучний постріл» та «Вибуховий постріл» завдають на $s1% більше шкоди." },
    { en = "Kill Command generates $s1 additional Focus.", ua = "«Наказ убити» генерує додатково $s1 Зосередженості." },
    { en = "Fury of the Eagle now gains bonus critical strike chance against targets below ${$s2+$s1}% health, and Fury of the Eagle critical strikes reduce the cooldown of Wildfire Bomb and Flanking Strike by ${$m3/1000}.1 sec.", ua = "«Лють орла» тепер отримує додатковий шанс критичного удару по цілях зі здоров'ям нижче ${$s2+$s1}%, а критичні удари «Люті орла» скорочують перезарядження «Бомби пожежі» та «Флангового удару» на ${$m3/1000}.1 с." },
    { en = "Your auto attacks deal ${$385723s1*(1+$s2/100)} additional Holy damage.", ua = "Ваші автоатаки завдають додатково ${$385723s1*(1+$s2/100)} шкоди Світлом." },
    { en = "While Coordinated Assault is active, the cooldown of Wildfire Bomb is reduced by $s1%, Wildfire Bomb generates $s2 Focus when thrown, Kill Shot's cooldown is reduced by $s3%, and Kill Shot can be used against any target, regardless of their current health.", ua = "Поки активний «Скоординований штурм», перезарядження «Бомби пожежі» скорочено на $s1%, «Бомба пожежі» генерує $s2 Зосередженості під час кидка, перезарядження «Смертельного пострілу» скорочено на $s3%, і «Смертельний постріл» можна застосувати до будь-якої цілі незалежно від її поточного здоров'я." },
    { en = "Revenge damage increased by $s2% and Revenge increases the damage of your next Thunder Clap by $s1%.", ua = "Шкода «Помсти» збільшена на $s2%, а «Помста» збільшує шкоду вашого наступного «Громового удару» на $s1%." },
    { en = "Increases the Maelstrom generated by Lightning Bolt and Lava Burst by $s1.", ua = "Збільшує Мальстрем, що генерується «Блискавицею» та «Вибухом лави», на $s1." },
    { en = "Grants access to the following abilities:\n\n\n\n$@spellicon1714$@spellname1714:\n\n$@spelldesc1714\n\n\n\n$@spellicon334275$@spellname334275:\n\n$@spelldesc334275", ua = "Надає доступ до таких здібностей:\n\n\n\n$@spellicon1714$@spellname1714:\n\n$@spelldesc1714\n\n\n\n$@spellicon334275$@spellname334275:\n\n$@spelldesc334275" },
    { en = "Your Felguard deals $386176s1% more damage and takes $386176s2% less damage.", ua = "Ваш Скверноварт завдає на $386176s1% більше шкоди та отримує на $386176s2% менше шкоди." },
    { en = "Your primary Felguard's Legion Strike damage is increased by $s1%. \n\n\n\nYour primary Felguard's Felstorm damage is increased by $s2%.", ua = "Шкода «Удару Легіону» вашого основного Скверноварта збільшена на $s1%. \n\n\n\nШкода «Скверношторму» вашого основного Скверноварта збільшена на $s2%." },
    { en = "Summons a Soulkeeper that consumes all Tormented Souls you've collected, blasting nearby enemies for $386265s1 Chaos damage per soul consumed over ${$386256d-2} sec. Deals reduced damage beyond 8 targets and only one Soulkeeper can be active at a time.\n\n\n\nYou collect Tormented Souls from each target you kill and occasionally escaped souls you previously collected.", ua = "Прикликає Хранителя душ, що поглинає всі зібрані вами Змучені душі, вражаючи ворогів поблизу на $386265s1 шкоди Хаосу за кожну поглинуту душу протягом ${$386256d-2} с. Завдає зменшеної шкоди понад 8 цілей, і водночас може бути активним лише один Хранитель душ.\n\n\n\nВи збираєте Змучені душі з кожної вбитої цілі та подеколи ті, що втекли й були зібрані раніше." },
    { en = "Hurl a brew created from the bones of your enemies at the ground, coating all targets struck for $d. Your abilities have a $h% chance to affect the target a second time at $s1% effectiveness as Shadow damage or healing.\n\n\n\n$?s137024[Gust of Mists heals targets with your Bonedust Brew active for an additional $328748s1.]?s137023[Tiger Palm and Keg Smash reduce the cooldown of your brews by an additional $s3 sec when striking enemies with your Bonedust Brew active.]?s137025[Spinning Crane Kick refunds 1 Chi when striking enemies with your Bonedust Brew active.][]$?s386949[\n\n\n\n$@spelldesc386949][]$?s386941[\n\n\n\nWhen Bonedust Brew deals Shadow damage or healing, its cooldown is reduced by ${$386941s2/-1000}.1 sec.][]", ua = "Метніть у землю вариво, створене з кісток ваших ворогів, покриваючи всі вражені цілі на $d. Ваші здібності мають $h% шансу вплинути на ціль вдруге з $s1% ефективності як шкода або зцілення Тіні.\n\n\n\n$?s137024[«Порив туманів» зцілює цілі з активним «Варивом із кісткового пороху» додатково на $328748s1.]?s137023[«Тигрова долоня» і «Удар діжкою» скорочують перезарядження ваших варив ще на $s3 сек., коли ви вражаєте ворогів з активним «Варивом із кісткового пороху».]?s137025[«Кружний удар журавля» повертає 1 Чі, коли ви вражаєте ворогів з активним «Варивом із кісткового пороху».][]$?s386949[\n\n\n\n$@spelldesc386949][]$?s386941[\n\n\n\nКоли «Вариво із кісткового пороху» завдає шкоди або зцілює Тінню, його перезарядження скорочується на ${$386941s2/-1000}.1 сек.][]" },
    { en = "The duration of Champion's Spear is increased by ${$s1/1000} sec. You deal $376080s5% increased critical strike damage to targets chained to your Spear.", ua = "Тривалість «Списа чемпіона» збільшена на ${$s1/1000} с. Ви завдаєте на $376080s5% більше критичної шкоди цілям, прикутим до вашого Списа." },
    { en = "Shield Charge deals $s2% increased damage, grants you Shield Block, and makes your next Revenge cost no Rage.", ua = "«Наскок щитом» завдає на $s2% більше шкоди, надає вам «Блокування щитом» і робить вашу наступну «Помсту» безкоштовною за Лють." },
    { en = "Your spells and abilities have a chance to summon an Inquisitor's Eye that deals $388070s1 Shadowflame damage every $388067t1 sec for $388067d.", ua = "Ваші закляття та здібності мають шанс прикликати Око Інквізитора, що завдає $388070s1 шкоди Тіньовим полум'ям кожні $388067t1 с протягом $388067d." },
    { en = "Skullsplitter deals $s2% increased damage and also causes your Rend on the target to bleed out $427040s1% faster for $427040d.", ua = "«Череполом» завдає на $s2% більше шкоди, а також змушує ваш ефект «Роздирання» на цілі кровоточити на $427040s1% швидше протягом $427040d." },
    { en = "Lava Burst and Lava Burst Overload damage reduces the cooldown of Primordial Wave by ${$s1/-1000}.1 sec.", ua = "Шкода «Вибуху лави» та «Перевантаження вибухом лави» скорочує перезарядження «Первісної хвилі» на ${$s1/-1000}.1 с." },
    { en = "Casting Primordial Wave triggers $?a408572[Volcanic][Lava] Surge immediately and every $387622T sec for $387622d. $?a408572[Volcanic][Lava] Surges triggered by Primordial Wave increase the damage of your next Lava Burst by $396484s1%.", ua = "Застосування «Первісної хвилі» негайно спричиняє $?a408572[«Вулканічний наплив»][«Лавовий наплив»], а потім щоразу через $387622T сек. упродовж $387622d. $?a408572[«Вулканічні напливи»][«Лавові напливи»], спричинені «Первісною хвилею», збільшують шкоду вашого наступного «Лавового вибуху» на $396484s1%." },
    { en = "While you have Temporal Displacement or other similar effects, you may use Time Warp to grant yourself $386540s1% Haste for $386540d.", ua = "Поки на вас діє «Темпоральне зміщення» чи інші подібні ефекти, ви можете застосувати «Викривлення часу», щоб надати собі $386540s1% Поспіху протягом $386540d." },
    { en = "Drain Life heals for $s1% of the amount drained over $386614d.", ua = "Викрадання життя зцілює на $s1% від висмоктаної кількості за $386614d." },
    { en = "Your $?a1218692[Bloodstone grants an additional $s1% haste.][Healthstone heals you for an additional $s1% of your maximum health.] Any party or raid member using a $?a1218692[Bloodstone also grants you $s3% haste.][Healthstone also heals you for that amount.]", ua = "Ваш $?a1218692[Кровокамінь дає додатково $s1% поспіху.][Камінь здоров'я зцілює вас додатково на $s1% від максимального здоров'я.] Будь-який член групи чи рейду, що використовує $?a1218692[Кровокамінь, також дає вам $s3% поспіху.][Камінь здоров'я, також зцілює вас на цю величину.]" },
    { en = "Increases the duration of Banish by ${$s1/1000} sec. Banish now affects Undead.", ua = "Збільшує тривалість Вигнання на ${$s1/1000} сек. Вигнання тепер діє на нежить." },
    { en = "Hurl bolts of decimating magic at your target, dealing $<damage> Shadow damage and increasing the damage of your next$?s198590[][ $386698u] $?s137046[Incinerates]?a137044&?!s137046[Demonbolts]?!a137044[Shadow Bolts or Drain Souls][] by $386698s1%.$?a196408[ This value is reduced while using Fire and Brimstone.][]\n\n\n\nDecimating Bolt's damage, and the bonus to $?s137046[Incinerate]?a137044[Demonbolt]?!s137046&!a137044[Shadow Bolt and Drain Soul][] both increase as your target's health decreases.", ua = "Кидає стріли нищівної магії в ціль, завдаючи $<damage> шкоди Тінню й підвищуючи шкоду ваших наступних$?s198590[][ $386698u] $?s137046[Спалень]?a137044&?!s137046[Демонічних стріл]?!a137044[Тіньових стріл чи Виснажень душі][] на $386698s1%.$?a196408[ Це значення зменшується під час використання Вогню та Сірки.][]\n\n\n\nШкода Нищівної стріли, а також бонус до $?s137046[Спалення]?a137044[Демонічної стріли]?!s137046&!a137044[Тіньової стріли та Виснаження душі][] зростають зі зменшенням здоров'я цілі." },
    { en = "Refreshing Corruption, Agony, Unstable Affliction, or Siphon Life with less than ${$s1/1000} seconds remaining will deal ${$386760s1*(1+$s3/100)} Shadow damage and has a ${$s2/100}.2% chance to grant you a Soul Shard.", ua = "Поновлення Псування, Агонії, Нестабільної Немочі або Викачування життя, коли до кінця лишається менше ${$s1/1000} секунд, завдає ${$386760s1*(1+$s3/100)} тіньової шкоди й має ${$s2/100}.2% шанс дарувати тобі уламок душі." },
    { en = "Your Felguard hurls his axe towards the target location, erupting when it lands and dealing $386609s1 Shadowflame damage every $386542s2 sec for $386542d to nearby enemies.\n\n\n\nWhile unarmed, your Felguard's basic attacks deal damage to all nearby enemies and attacks $386601s1% faster.", ua = "Твій сквернельник жбурляє свою сокиру до вказаного місця; вона вибухає при падінні й завдає $386609s1 шкоди скверним полум'ям кожні $386542s2 сек протягом $386542d ворогам поблизу.\n\n\n\nПоки сквернельник беззбройний, його звичайні атаки завдають шкоди всім ворогам поблизу й б'ють на $386601s1% швидше." },
    { en = "Increases the attack speed of your primary pet by $s1%. $?a137044[][\n\n\n\nIncreases Grimoire of Sacrifice damage by $s2%.]", ua = "Підвищує швидкість атаки вашого основного улюбленця на $s1%. $?a137044[][\n\n\n\nПідвищує шкоду Гримуара жертвопринесення на $s2%.]" },
    { en = "Increases the damage done by your primary pet by $s1%. $?a137044[][\n\n\n\nIncreases Grimoire of Sacrifice damage by $s2%.]", ua = "Підвищує шкоду, завдану вашим основним улюбленцем, на $s1%. $?a137044[][\n\n\n\nПідвищує шкоду Гримуара жертвопринесення на $s2%.]" },
    { en = "Seed of Corruption's explosion increases the stack count of Agony by $s1 on all targets hit.", ua = "Вибух Сімені Псування збільшує кількість стосів Агонії на $s1 на всіх уражених цілях." },
    { en = "Bonedust Brew's Shadow damage or healing is increased by $s1%, and when Bonedust Brew deals Shadow damage or healing, its cooldown is reduced by ${$s2/-1000}.1 sec.", ua = "Тіньова шкода або зцілення Кістяного відвару збільшено на $s1%, а коли Кістяний відвар завдає тіньової шкоди чи зцілює, його перезарядження скорочується на ${$s2/-1000}.1 сек." },
    { en = "Your abilities have a low chance to cast Bonedust Brew at your target's location.", ua = "Твої здібності мають низький шанс застосувати Кістяний відвар у місці розташування твоєї цілі." },
    { en = "Copies your damage over time effects and Haunt from the target, preserving their duration.\n\n\n\nYour next use of Soul Swap within $399680d will exhale a copy damage of the effects onto a new target.", ua = "Копіює з цілі твої ефекти шкоди з часом і Переслідування, зберігаючи їхню тривалість.\n\n\n\nТвоє наступне застосування Обміну душами протягом $399680d видихне копію шкоди цих ефектів на нову ціль." },
    { en = "Wither away all life force of your current target and up to $s3 additional targets nearby, causing your primary target to suffer ${$o2*(1+$m4/10)} Shadow damage and secondary targets to suffer $o2 Shadow damage over $d.\n\n\n\nDamage dealt by Soul Rot heals you for ${$e2*100}% of damage done.", ua = "Висушує всю життєву силу твоєї поточної цілі та ще до $s3 цілей поблизу, завдаючи основній цілі ${$o2*(1+$m4/10)} тіньової шкоди, а другорядним цілям — $o2 тіньової шкоди протягом $d.\n\n\n\nШкода, завдана Гниттям душі, зцілює тебе на ${$e2*100}% від завданої шкоди." },
    { en = "Each target affected by Soul Rot increases your haste and critical strike chance by ${$s1/10}.1% for $387018d.", ua = "Кожна ціль під дією Гниття душі збільшує твій Поспіх і шанс критичного удару на ${$s1/10}.1% протягом $387018d." },
    { en = "Zen Meditation has $s2% reduced cooldown and is no longer cancelled when you move or when you are hit by melee attacks.", ua = "Дзен-медитація має на $s2% скорочене перезарядження і більше не переривається, коли ти рухаєшся або коли тебе вражають атаки ближнього бою." },
    { en = "Corruption and Agony each grant an application of Wrath of Consumption when a target dies, increasing all periodic damage dealt by $s2% for $387066d, stacking up to $387066u times.", ua = "Псування й Агонія, коли ціль гине, кожне дарує застосування Гніву Поглинання, збільшуючи всю завдану періодичну шкоду на $s2% протягом $387066d. Стосується до $387066u разів." },
    { en = "While Agony, $?a445465[Wither][Corruption], and Unstable Affliction are active, your Shadow Bolt has a $s1% chance and your Drain Soul has a $s2% chance to make your next Malefic Rapture cost no Soul Shards and cast instantly.", ua = "Поки активні Агонія, $?a445465[В'янення][Псування] та Нестабільна пошесть, ваша Тіньова стріла має $s1% шанс, а ваше Виснаження душі — $s2% шанс зробити ваш наступний Лиховісний захват без витрати Уламків душі та миттєвим." },
    { en = "$?a137043[Summon Darkglare]?a137044[Summon Demonic Tyrant][Summon Infernal] cooldown is reduced by $?a137043[${$m1/-1000}]?a137044[${$m2/-1000}][${$m3/-1000}] sec.", ua = "Перезарядження $?a137043[Прикликання Темнозора]?a137044[Прикликання Демонічного тирана][Прикликання Інфернала] зменшується на $?a137043[${$m1/-1000}]?a137044[${$m2/-1000}][${$m3/-1000}] сек." },
    { en = "Increases the duration of Immolate by ${$s1/1000} sec.", ua = "Збільшує тривалість Спалення на ${$s1/1000} сек." },
    { en = "Enemies affected by your Rain of Fire take $s1% increased damage from your Fire spells.", ua = "Вороги під дією твого Вогняного дощу зазнають на $s1% більше шкоди від твоїх вогняних заклять." },
    { en = "Chaos Bolt and Rain of Fire increase the damage of your next $s3 Incinerates by $s1%. Shadowburn increases the damage of your next Incinerate by $s1%.\n\n\n\nStacks up to $387154U times.", ua = "Стріла хаосу та Вогняний дощ підвищують шкоду ваших наступних $s3 Спалень на $s1%. Тіньовий опік підвищує шкоду вашої наступної Спалені на $s1%.\n\n\n\nНакопичується до $387154U разів." },
    { en = "Every $s1 Soul Shards spent grants Ritual of Ruin, making your next Chaos Bolt or Rain of Fire consume no Soul Shards and have its cast time reduced by $387157s3%.", ua = "Кожні $s1 витрачених уламків душі дарують Ритуал Загибелі, завдяки чому твій наступний Хаос-заряд або Вогняний дощ не витрачає уламків душі й має на $387157s3% скорочений час прочитання." },
    { en = "When Chaos Bolt or Rain of Fire consumes a charge of Ritual of Ruin, you summon a Blasphemy for $s1 sec.\n\n\n\n$@spellicon387161 $@spellname387161\n\n$@spelldesc387161", ua = "Коли Стріла хаосу чи Вогняний дощ витрачає заряд Ритуалу руїни, ви прикликаєте Блюзнірство на $s1 сек.\n\n\n\n$@spellicon387161 $@spellname387161\n\n$@spelldesc387161" },
    { en = "Ritual of Ruin requires $s1 less Soul Shards spent.", ua = "«Ритуал Руїни» потребує на $s1 менше витрачених Уламків Душ." },
    { en = "Your Incinerate and Conflagrate casts on targets that have $s2% or less health reduce the cooldown of Soulfire by ${$s1/-1000} sec and reduce its cast time by $454873s1% for $454873d.", ua = "Ваші прочитання «Спалення» та «Займання» по цілях, що мають $s2% здоров'я або менше, зменшують перезарядження «Вогню Душ» на ${$s1/-1000} сек. і скорочують його час прочитання на $454873s1% протягом $454873d." },
    { en = "For the next $d, your Mastery is increased by $?c1[${$117906bc1*$s1}]?c2[${$117907bc1*$s1}][${$115636bc1*$s1}.1]%. Additionally, $?a137025[Rising Sun Kick reduces Chi costs by $311054s1 for $311054d, and Blackout Kick reduces the cooldown of affected abilities by an additional ${$s8/1000} sec.][]$?a137023 [Keg Smash cooldown is reset instantly and enemies hit by Keg Smash or Rising Sun Kick take $312106s1% increased damage from you for $312106d, stacking up to $312106u times.][]$?a137024[Essence Font cooldown is reset instantly and heals up to $311123s2 nearby allies for $311123s1 health on channel start and end.][]", ua = "Протягом наступних $d ваша Майстерність підвищується на $?c1[${$117906bc1*$s1}]?c2[${$117907bc1*$s1}][${$115636bc1*$s1}.1]%. Крім того, $?a137025[Удар висхідного сонця зменшує витрати Ці на $311054s1 упродовж $311054d, а Затьмарливий удар додатково зменшує перезарядження задіяних здібностей на ${$s8/1000} сек.][]$?a137023 [Перезарядження Удару барилом миттєво завершується, а вороги, вражені Ударом барилом чи Ударом висхідного сонця, отримують від вас на $312106s1% більше шкоди упродовж $312106d, накопичуючись до $312106u разів.][]$?a137024[Перезарядження Джерела есенції миттєво завершується, і воно зцілює до $311123s2 союзників поблизу на $311123s1 здоров'я на початку та наприкінці підтримання.][]" },
    { en = "Haunt deals $s1% additional damage. When the Haunt spell ends or is dispelled, the soul returns to you, healing for $s2% of the damage it did to the target.", ua = "«Причаєння» завдає на $s1% більше шкоди. Коли «Причаєння» завершується або його розвіюють, душа повертається до вас і зцілює на $s2% шкоди, завданої цілі." },
    { en = "After you successfully dodge or an enemy misses you, you gain $s1% increased movement speed for $387254d. Max $387254u stacks.", ua = "Після вдалого ухилення або промаху ворога ваша швидкість пересування зростає на $s1% протягом $387254d. Максимум $387254u накопичень." },
    { en = "Increases the damage of your Darkglare by $s1%. When Darkglare extends damage over time effects it also sears affected targets for $453233s1 Shadow damage.", ua = "Збільшує шкоду вашого «Темнозора» на $s1%. Коли «Темнозор» подовжує ефекти шкоди в часі, він також обпалює вражені цілі, завдаючи $453233s1 шкоди Тіні." },
    { en = "Consuming Soul Shards increases your Mastery by ${$s2/10}.1% for $387283d for each shard spent. Gaining a stack does not refresh the duration.", ua = "Поглинання Уламків Душ збільшує вашу Майстерність на ${$s2/10}.1% протягом $387283d за кожен витрачений уламок. Отримання накопичення не оновлює тривалість." },
    { en = "Your Haunt spell also increases the damage of your damage over time effects to all targets by $s1% while active.", ua = "Ваше «Причаєння», доки триває, також збільшує шкоду ваших ефектів шкоди в часі по всіх цілях на $s1%." },
    { en = "When your summoned Dreadstalkers fade away, they increase the damage of your Demonbolt by $s1% for $272945d.", ua = "Коли ваші прикликані Жахоскради зникають, вони збільшують шкоду вашого «Демонічного Спалаху» на $s1% протягом $272945d." },
    { en = "The chance of receiving a Demonic Core from a Wild Imp is increased by $s1% or $s2% when imploded.", ua = "Шанс отримати Демонічне Ядро від Дикого Біса збільшено на $s1% або на $s2% при його імплозії." },
    { en = "Summon Infernal reduces the Soul Shard cost of your next $s1 casts of Chaos Bolt, Shadowburn, or Rain of Fire by 1.", ua = "«Прикликання Інфернала» зменшує вартість в Уламках Душ ваших наступних $s1 прочитань «Стріли Хаосу», «Тіньового Опіку» чи «Вогняного Дощу» на 1." },
    { en = "Each Soul Shard spent on Hand of Gul'dan increases the damage of your next Call Dreadstalkers by $s1%.", ua = "Кожен Уламок Душі, витрачений на «Руку Ґул'дана», збільшує шкоду вашого наступного «Поклику Жахоскрадів» на $s1%." },
    { en = "Each time Felstorm deals damage, it increases the damage the target takes from you and your pets by $s1% for $387402d, up to ${$s1*$387402u}%.", ua = "Щоразу, коли «Буря Скверни» завдає шкоди, вона збільшує шкоду, яку ціль отримує від вас і ваших улюбленців, на $s1% протягом $387402d, до ${$s1*$387402u}%." },
    { en = "Chaos Bolt increases the damage of Chaos Bolt by $s1% and reduces the cast time of Chaos Bolt by $s2% for $387409d.\n\n\n\nRain of Fire increases the damage of Rain of Fire by $s1% for $387413d.\n\n\n\nShadowburn increases the damage of Shadowburn by $s1% for $387414d.", ua = "«Стріла Хаосу» збільшує шкоду «Стріли Хаосу» на $s1% і скорочує час її прочитання на $s2% протягом $387409d.\n\n\n\n«Вогняний Дощ» збільшує шкоду «Вогняного Дощу» на $s1% протягом $387413d.\n\n\n\n«Тіньовий Опік» збільшує шкоду «Тіньового Опіку» на $s1% протягом $387414d." },
    { en = "Shadow Bolt increases the damage of your Demonbolt by $s2%, stacking up to $387437u times. Lasts $387437d.", ua = "«Стріла Тіні» збільшує шкоду вашого «Демонічного Спалаху» на $s2%, накопичуючись до $387437u разів. Триває $387437d." },
    { en = "Summoning a Wild Imp has a $s1% chance to summon a Imp Gang Boss instead. An Imp Gang Boss deals $387458s2% additional damage. \n\n\n\nImplosions from Imp Gang Boss deal $s2% increased damage.", ua = "Прикликання Дикого Біса має $s1% шансу натомість прикликати Ватажка Зграї Бісів. Ватажок Зграї Бісів завдає на $387458s2% більше шкоди. \n\n\n\nІмплозії від Ватажка Зграї Бісів завдають на $s2% більше шкоди." },
    { en = "Your Infernal's melee attacks cause its target to take $s1% increased damage from its Immolation, stacking up to $387476u times.", ua = "Атаки ближнього бою вашого Пекельника змушують ціль отримувати на $s1% більше шкоди від його Самоспалення. Стається до $387476u разів." },
    { en = "Doom deals $s1% increased damage for each demon pet you have active.", ua = "Приреченість завдає на $s1% більше шкоди за кожного активного демона-улюбленця." },
    { en = "Your Felguard deals $s1% additional damage. Soul Strike now deals $s2% of its damage to nearby enemies.", ua = "Ваш Скверностраж завдає на $s1% більше шкоди. Удар душі тепер завдає $s2% своєї шкоди ворогам поблизу." },
    { en = "Increases the base duration of Havoc by ${$s1/1000} sec.\n\n\n\nMayhem has an additional $s2% chance to trigger.", ua = "Збільшує базову тривалість Спустошення на ${$s1/1000} сек.\n\n\n\nБезлад має додаткові $s2% шансу спрацювати." },
    { en = "When Chaos Bolt damages a target afflicted by Havoc, it explodes, dealing $387547s2 damage to enemies within $387547A2 yards.", ua = "Коли Заряд хаосу завдає шкоди цілі під дією Спустошення, він вибухає, завдаючи $387547s2 шкоди ворогам у межах $387547A2 ярдів." },
    { en = "Demons summoned from your Nether Portal deal $s1% increased damage.", ua = "Демони, покликані вашим Порталом Нижнього Світу, завдають на $s1% більше шкоди." },
    { en = "Hand of Gul'dan has a $s1% chance to cast a second time on your target for free.", ua = "Рука Ґул'дана має $s1% шансу спрацювати вдруге на вашій цілі безкоштовно." },
    { en = "While your Felguard is active, your Wild Imps and Dreadstalkers deal $s1% additional damage.", ua = "Поки ваш Скверностраж активний, ваші Дикі бісенята та Жахоблуди завдають на $s1% більше шкоди." },
    { en = "Each time your spells duplicate from Havoc, gain $s1% increased damage for $387570d. Stacks up to $387570U times.", ua = "Щоразу, коли ваші закляття дублюються від Спустошення, ви отримуєте на $s1% більше шкоди упродовж $387570d. Накопичується до $387570U разів." },
    { en = "When Nether Portal ends, you summon a Pit Lord that blasts your target for $<damage> Fire damage every $427688t1 sec for $427688d.", ua = "Коли Портал Нижнього Світу завершується, ви прикликаєте Володаря Ями, що б'є вашу ціль на $<damage> шкоди Вогнем кожні $427688t1 сек. протягом $427688d." },
    { en = "When your Wild Imps expire or die, your other demons are inspired and gain 1% additional damage, stacking up to $387601u times.", ua = "Коли ваші Дикі бісенята зникають або гинуть, ваші інші демони надихаються й отримують додаткові 1% шкоди. Стається до $387601u разів." },
    { en = "When your Wild Imps cast Fel Firebolt, you gain an application of Stolen Power. After you reach $387603u applications, your next Demonbolt deals $387604s2% increased damage or your next Shadow Bolt deals $387604s1% increased damage.", ua = "Коли ваші Дикі бісенята творять Скверновогняний заряд, ви отримуєте застосування Викраденої сили. Досягнувши $387603u застосувань, ваш наступний Демонічний заряд завдає на $387604s2% більше шкоди, або ваш наступний Тіньовий заряд завдає на $387604s1% більше шкоди." },
    { en = "Life Cocoon increases healing over time received by an additional $s1%, and increases all periodic healing you deal by $s1% for an additional $387766d after the cocoon is removed.", ua = "Кокон життя збільшує отримуване поступове зцілення додатково на $s1%, а також збільшує все періодичне зцілення, яке ви завдаєте, на $s1% протягом додаткових $387766d після зникнення кокона." },
    { en = "After casting Holy Prism or Divine Toll you instantly cast $?c2[Avenger's Shield]?c1[Holy Shock][Judgment] every $387895t1 sec. This effect lasts $387895s2 sec.", ua = "Після застосування Святої призми чи Божественного дзвону ви миттєво застосовуєте $?c2[Щит месника]?c1[Святий шок][Присуд] кожні $387895t1 сек. Цей ефект триває $387895s2 сек." },
    { en = "Reduces the cooldown of Amplify Curse by ${$s1/-1000} sec.", ua = "Зменшує перезарядження Підсилення прокляття на ${$s1/-1000} сек." },
    { en = "Rips a hole in time and space, opening a random portal that damages your target:\n\n\n\n$@spellicon394235$@spellname394235\n\n$@spelldesc394235\n\n\n\n$@spellicon387979$@spellname387979\n\n$@spelldesc387979\n\n\n\n$@spellicon394243$@spellname394243\n\n$@spelldesc394243\n\n\n\n|cFFFFFFFFGenerates $s2 Soul Shard Fragments.|r", ua = "Розриває отвір у часі та просторі, відкриваючи випадковий портал, що завдає шкоди вашій цілі:\n\n\n\n$@spellicon394235$@spellname394235\n\n$@spelldesc394235\n\n\n\n$@spellicon387979$@spellname387979\n\n$@spelldesc387979\n\n\n\n$@spellicon394243$@spellname394243\n\n$@spelldesc394243\n\n\n\n|cFFFFFFFFСтворює $s2 Уламки душі.|r" },
    { en = "Raging Blow causes every strike of your next Rampage to deal an additional $393931s1% damage, stacking up to $393931u times.", ua = "Лютий удар змушує кожен удар вашого наступного Буйства завдавати додатково $393931s1% шкоди. Стається до $393931u разів." },
    { en = "Bless an ally for $d, causing $s1% of all healing to be converted into damage onto a nearby enemy and $s4% of all damage to be converted into healing onto an injured ally within $448227A1 yds.\n\n\n\n|cFFFFFFFFBlessing of the Seasons:|r Turns to Autumn after use.", ua = "Благословляє союзника на $d, перетворюючи $s1% усього зцілення на шкоду ворогу поблизу, а $s4% усієї шкоди — на зцілення пораненому союзнику в межах $448227A1 ярд.\n\n\n\n|cFFFFFFFFБлагословення пір року:|r Після використання змінюється на Осінь." },
    { en = "Light of Dawn increases your next Light of the Martyr by $388019s1% for each ally healed, and allows that Light of the Martyr to heal through Beacon of Light.\n\n\n\nLight of the Martyr damages you over $196917d instead of instantly.", ua = "Світло Світанку підвищує наступне Світло Мученика на $388019s1% за кожного зціленого союзника й дозволяє тому Світлу Мученика зцілювати крізь Маяк Світла.\n\n\n\nСвітло Мученика завдає тобі шкоди протягом $196917d замість миттєвої." },
    { en = "Your Tiger Palm, Blackout Kick, Rising Sun Kick, $?a1268807[Jadefire Stomp, ][]and Crackling Jade Lightning heal up to $s2 injured allies within $388024A1 yds for $s1% of the damage done, split evenly among them.", ua = "Ваші Долоня тигра, Затьмарливий удар, Удар висхідного сонця, $?a1268807[Нефритовий тупіт, ][]та Тріскотлива нефритова блискавка зцілюють до $s2 поранених союзників у межах $388024A1 ярдів на $s1% завданої шкоди, розподіленої рівномірно між ними." },
    { en = "Survival of the Fittest reduces damage taken by an additional ${$m1*-1}%.", ua = "Виживання найпристосованіших зменшує отриману шкоду додатково на ${$m1*-1}%." },
    { en = "Raging Blow gains an extra charge.", ua = "Лютий удар отримує додатковий заряд." },
    { en = "Sentinel Owl now also grants unhindered vision to party members while active.", ua = "Вартова сова, поки активна, тепер також дарує безперешкодний зір членам групи." },
    { en = "While the Sentinel Owl is active, your party gains $393777s1% leech.", ua = "Поки Вартова сова активна, твоя група отримує $393777s1% висмоктування." },
    { en = "You deal $391369s1% increased damage to enemies for $391369d after Sigil of Misery's effect on them ends.", ua = "Ти завдаєш ворогам на $391369s1% більше шкоди протягом $391369d після того, як на них закінчується дія Знака Страждання." },
    { en = "Strike the ground fiercely to expose a path of jade for $d$?a137025[ that increases your movement speed by $451943s1% while inside][], dealing $388207s1 Nature damage to $?a451573[$s1 enemy][up to $s1 enemies] within $388207a1 yds caught in the path.$?a137024[]?a137025[ Up to 5 enemies caught in the path][Stagger is $s3% more effective for $347480d against enemies caught in the path.]$?a137023[]?a137024[][ suffer an additional $388201s1 damage.]$?a137024[\n\n\n\nYour abilities have a $s2% chance of resetting the cooldown of Jadefire Stomp while fighting within the path.][]", ua = "Люто б'є по землі, відкриваючи нефритовий шлях на $d$?a137025[, що підвищує вашу швидкість пересування на $451943s1%, поки ви на ньому][], завдаючи $388207s1 шкоди Природою $?a451573[$s1 ворогу][щонайбільше $s1 ворогам] у межах $388207a1 ярдів, захопленим на шляху.$?a137024[]?a137025[ До 5 ворогів, захоплених на шляху][Розсіювання на $s3% ефективніше упродовж $347480d проти ворогів, захоплених на шляху.]$?a137023[]?a137024[][ отримують додатково $388201s1 шкоди.]$?a137024[\n\n\n\nВаші здібності мають $s2% шанс скинути перезарядження Нефритового тупоту, поки ви б'єтеся на шляху.][]" },
    { en = "Overload a nearby elemental ore deposit.\n\n\n\n$?pc106420[The cooldown of this ability is reduced whenever you mine ore native to the Dragon Isles.][Specialize into Master of the Elements to gain significant cooldown reduction on this ability whenever you mine ore native to the Dragon Isles.]", ua = "Перевантажує сусіднє родовище елементальної руди.\n\n\n\n$?pc106420[Перезарядження цієї здібності зменшується щоразу, коли ви видобуваєте руду, властиву Драконовим Островам.][Спеціалізуйтеся на Володарі стихій, щоб отримувати значне зменшення перезарядження цієї здібності щоразу, коли ви видобуваєте руду, властиву Драконовим Островам.]" },
    { en = "Extract the burning components from Darkmoon Cards of Fire.  \n\n\n\nThis will destroy the Darkmoon Card in the process.", ua = "Видобудь палаючі компоненти з Карт Темного Місяця вогню.  \n\n\n\nПри цьому Карта Темного Місяця буде знищена." },
    { en = "Extract the freezing components from Darkmoon Cards of Frost. \n\n\n\nThis will destroy the Darkmoon Card in the process.", ua = "Видобудь крижані компоненти з Карт Темного Місяця морозу. \n\n\n\nПри цьому Карта Темного Місяця буде знищена." },
    { en = "Extract the earthen components from Darkmoon Cards of Earth. \n\n\n\nThis will destroy the Darkmoon Card in the process.", ua = "Видобудь земляні компоненти з Карт Темного Місяця землі. \n\n\n\nПри цьому Карта Темного Місяця буде знищена." },
    { en = "Extract the flowing components from Darkmoon Cards of Air. \n\n\n\nThis will destroy the Darkmoon Card in the process.", ua = "Видобудь плинні компоненти з Карт Темного Місяця повітря. \n\n\n\nПри цьому Карта Темного Місяця буде знищена." },
    { en = "Soothing Mist heals a second injured ally within $388478A2 yds for $s1% of the amount healed.", ua = "Заспокійливий Туман зцілює другого пораненого союзника в межах $388478A2 ярдів на $s1% зціленого обсягу." },
    { en = "Each time Enveloping Mist heals, its healing bonus has a $s2% chance to spread to an injured ally within $388508a1 yds.", ua = "Щоразу, коли Огортаючий Туман зцілює, його бонус до зцілення має $s2% шансу перекинутися на пораненого союзника в межах $388508a1 ярдів." },
    { en = "Thunder Focus Tea also empowers $s1 additional Enveloping Mist or Rising Sun Kick at random.", ua = "Чай Грозового Зосередження також підсилює $s1 додатковий Огортаючий Туман або Удар Висхідного Сонця навмання." },
    { en = "Zen Pulse's damage and healing is increased by $388566s1% each time Soothing Mist heals, up to $388566u times. \n\n\n\nWhen your Soothing Mist channel ends, this effect is canceled.", ua = "Шкода й зцілення Дзен-Імпульсу зростають на $388566s1% щоразу, коли зцілює Заспокійливий Туман, до $388566u разів. \n\n\n\nКоли твоє прочитання Заспокійливого Туману завершується, цей ефект скасовується." },
    { en = "Zen Pulse triggers a second time at $s1% effectiveness if cast on targets with Enveloping Mist.", ua = "Дзен-Імпульс спрацьовує вдруге з ефективністю $s1%, якщо застосований до цілей з Огортаючим Туманом." },
    { en = "You gain $388663m1% haste for $?a388212[${$s2-$s3} sec][$388663d] after summoning your Celestial.", ua = "Ви отримуєте $388663m1% поспіху на $?a388212[${$s2-$s3} с][$388663d] після виклику свого Небожителя." },
    { en = "Your Blackout Kicks strike ${$s2+1} targets and have an additional $s1% chance to reset the cooldown of your Rising Sun Kick while within your Jadefire Stomp.", ua = "Ваш «Приголомшливий удар» вражає ${$s2+1} цілей і має додаткові $s1% шансу скинути перезарядження «Удару висхідного сонця», поки ви в зоні «Нефритового тупотіння»." },
    { en = "Whenever you Parry, you heal for ${$388808s1}.1% of your maximum health. This effect cannot occur more than once every $proccooldown sec.", ua = "Щоразу, коли ви парируєте, ви зцілюєтеся на ${$388808s1}.1% від вашого максимального здоров'я. Цей ефект не може виникати частіше ніж раз на $proccooldown с." },
    { en = "Spinning Crane Kick radius increased by $s1%.", ua = "Радіус «Обертового удару журавля» збільшено на $s1%." },
    { en = "Fists of Fury damage increased by $s1%.", ua = "Шкоду «Кулаків люті» збільшено на $s1%." },
    { en = "Whirlwind has a ${$s1/1000}.1 sec cooldown, but deals $s3% increased damage. \n\n\n\nSlam has a ${$s2/1000}.1 sec cooldown and generates ${$s6/10} Rage, but deals $s4% increased damage.", ua = "«Вихор» має перезарядження ${$s1/1000}.1 с, але завдає на $s3% більше шкоди. \n\n\n\n«Удар» має перезарядження ${$s2/1000}.1 с і породжує ${$s6/10} люті, але завдає на $s4% більше шкоди." },
    { en = "Onslaught Enrages you. If you have Slaughtering Strikes, it also grants you $s1 stacks of Slaughtering Strikes.", ua = "«Навала» розлючує вас. Якщо ви маєте «Різницькі удари», вона також надає вам $s1 накопичень «Різницьких ударів»." },
    { en = "Permanently enchants bracers to increase your Avoidance by $ec1. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує наручі, підвищуючи ваше Уникнення на $ec1. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants bracers to increase your Leech by $ec1. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує наручі, підвищуючи ваше Висмоктування на $ec1. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants bracers to increase your Speed by $ec1. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує наручі, підвищуючи вашу Швидкість на $ec1. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Mastery increased by $s1% and Tactician's chance to trigger is increased by an additional ${$s2/100}.1%.", ua = "Майстерність збільшено на $s1%, а шанс спрацювання «Тактика» збільшено додатково на ${$s2/100}.1%." },
    { en = "Attacks received that deal at least $s2% of your health decrease Unending Resolve's cooldown by $s3 sec. Cannot occur more than once every ${$proccooldown-$s1/-1000} sec.", ua = "Отримані атаки, що завдають щонайменше $s2% вашого здоров'я, зменшують перезарядження «Незламної рішучості» на $s3 с. Не може виникати частіше ніж раз на ${$proccooldown-$s1/-1000} с." },
    { en = "Permanently enchants a chestpiece to increase your primary stats by $ec1. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує нагрудник, підвищуючи ваші основні характеристики на $ec1. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants a chestpiece to increase your Intellect by $ec1 and mana pool by $ec2s1%. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує нагрудник, підвищуючи ваш Інтелект на $ec1 і запас мани на $ec2s1%. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Trueshot lasts an additional ${$m2/1000}.1 sec, reduces the Focus Cost of Aimed Shot by $s1%.", ua = "«Влучний постріл» триває на ${$m2/1000}.1 с довше й зменшує вартість зосередження «Прицільного пострілу» на $s1%." },
    { en = "Permanently enchants a crafting tool to increase your Ingenuity by $ec1. Cannot be applied to items above level $ecix.", ua = "Назавжди зачаровує ремісниче знаряддя, підвищуючи вашу Винахідливість на $ec1. Не можна застосувати до предметів рівня, вищого за $ecix." },
    { en = "Permanently enchants a crafting or cooking tool to increase your Resourcefulness by $ec1. Cannot be applied to items above level $ecix.", ua = "Назавжди зачаровує ремісниче або кулінарне знаряддя, підвищуючи вашу Кмітливість на $ec1. Не можна застосувати до предметів рівня, вищого за $ecix." },
    { en = "Permanently enchants a weapon to sometimes ignite, causing your next heal to additionally cauterize an ally's wounds, healing for $ec1s1. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує зброю, що подеколи спалахує, змушуючи ваше наступне зцілення додатково припекти рани союзника, зцілюючи на $ec1s1. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants a weapon to sometimes ground yourself, increasing your Armor by $ec1s1 for $390345d. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує зброю, що подеколи заземлює вас, підвищуючи вашу Броню на $ec1s1 на $390345d. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants a weapon to sometimes harness Order, increasing your primary stat by $ec1s1 for $390224d. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує зброю, що подеколи використовує силу Порядку, підвищуючи вашу основну характеристику на $ec1s1 на $390224d. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants a weapon to sometimes radiate ice, dealing $ec1s1 Frost damage split between enemies in front of you. Damage is increased for each enemy struck, up to $390350s2 enemies. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує зброю, що подеколи випромінює кригу, завдаючи $ec1s1 шкоди від Морозу, розподіленої між ворогами перед вами. Шкода зростає за кожного враженого ворога, до $390350s2 ворогів. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "Permanently enchants a weapon to sometimes sway the winds, increasing your Haste by $ec1s1 and Speed by $ec1s2 for $390357d. Cannot be applied to items lower than level $ecim.", ua = "Назавжди зачаровує зброю, що подеколи розганяє вітри, підвищуючи ваш Поспіх на $ec1s1 і Швидкість на $ec1s2 на $390357d. Не можна застосувати до предметів рівня, нижчого за $ecim." },
    { en = "You and your allies within $m2 yards have $s1% increased healing taken from all sources.", ua = "Ви та ваші союзники в межах $m2 ярдів отримуєте на $s1% більше зцілення з усіх джерел." },
    { en = "You and your allies within $m2 yards take $s1% reduced damage from area-of-effect attacks.", ua = "Ви та ваші союзники в межах $m2 ярдів отримуєте на $s1% менше шкоди від атак по площі." },
    { en = "When your health drops below $s1%, the percentage of damage shared via your Soul Link is increased by an additional $s2%. $?a137044[][\n\n\n\nWhile Grimoire of Sacrifice is active, your Stamina is increased by $s3%.]", ua = "Коли ваше здоров'я падає нижче $s1%, відсоток шкоди, розподіленої через ваш Зв'язок душ, зростає додатково на $s2%. $?a137044[][\n\n\n\nПоки активний Гримуар Жертви, ваша Витривалість підвищена на $s3%.]" },
    { en = "When a hit deals more than $m2% of your maximum health, reduce all damage you take by $s1% for $390239d.\n\n\n\nThis effect cannot occur more than once every $m3 seconds.", ua = "Коли удар завдає більше ніж $m2% вашого максимального здоров'я, уся шкода, яку ви отримуєте, зменшується на $s1% протягом $390239d.\n\n\n\nЦей ефект не може виникати частіше ніж раз на $m3 секунд." },
    { en = "Your attacks have a chance to resonate, dealing $391400s1 Nature damage to enemies within $391400a1 yds.", ua = "Ваші атаки мають шанс срезонувати, завдаючи $391400s1 шкоди від сил природи ворогам у межах $391400a1 ярдів." },
    { en = "Rampage has a $s1% chance to grant Recklessness for ${$s2/1000} sec.", ua = "«Буйство» має $s1% шансу надати «Безрозсудність» на ${$s2/1000} с." },
    { en = "Greatly increases the effect of Blast Wave's knockback. Blast Wave's cooldown is reduced by ${$s1/-1000} sec", ua = "Значно посилює ефект відкидання «Вибухової хвилі». Перезарядження «Вибухової хвилі» зменшено на ${$s1/-1000} с" },
    { en = "Soul Rot cooldown is reduced by ${$s1/-1000} sec.", ua = "Перезарядження Гниття Душі зменшено на ${$s1/-1000} сек." },
    { en = "While Aspect of the Wild is active, Cobra Shot deals $s1% increased damage.", ua = "Поки активний Аспект Дикої Природи, Постріл Кобри завдає на $s1% більше шкоди." },
    { en = "Increases the duration of Sigil effects by ${$s1/1000}.1 sec.", ua = "Збільшує тривалість ефектів Знаків на ${$s1/1000}.1 сек." },
    { en = "Malefic Rapture causes targets suffering from your Unstable Affliction to take $389868s1% additional damage from your damage over time effects for $389868d.", ua = "Лиховісний Захват змушує цілі, уражені твоїм Нестабільним Стражданням, отримувати на $389868s1% більше шкоди від твоїх ефектів періодичної шкоди протягом $389868d." },
    { en = "All Sigils are now placed at your target's location.", ua = "Тепер усі Знаки розміщуються в місці розташування твоєї цілі." },
    { en = "Increase the damage over time effect of The Hunt by $s1%.", ua = "Збільшує ефект періодичної шкоди Полювання на $s1%." },
    { en = "The cooldown of The Hunt is reduced by $s1 sec whenever an enemy is killed while afflicted by its damage over time effect.", ua = "Перезарядження Полювання зменшується на $s1 сек. щоразу, коли ворог гине під його ефектом періодичної шкоди." },
    { en = "Trueshot grants Wailing Arrow and Aimed Shot generates $s3 additional Wind Arrows while in Trueshot.\n\n\n\nWailing Arrow resets the cooldown of Rapid Fire and generates $s2 $Lcharge:charges; of Aimed Shot.", ua = "Влучний постріл надає Стрілу Плачу, а Прицільний постріл створює $s3 додаткових Стріл Вітру під час дії Влучного пострілу.\n\n\n\nСтріла Плачу скидає перезарядження Скорострільності та створює $s2 $Lзаряд:заряди:зарядів; Прицільного пострілу." },
    { en = "Wailing Arrow fires off $s1 Wind Arrows at your primary target, and $s2 Wind Arrows split among any secondary targets hit.", ua = "Голосяча Стріла випускає $s1 Вітряних Стріл у твою основну ціль, а ще $s2 Вітряних Стріл розподіляються між усіма враженими другорядними цілями." },
    { en = "When you cast Coordinated Assault, you gain $s1 $Lcharge:charges; of Wildfire Bomb. \n\n\n\nWhen Coordinated Assault ends, Explosive Shot's cooldown is reset and your next Explosive Shot fires at ${$459859s2-1} additional targets at $s2% effectiveness.", ua = "Коли ти застосовуєш Скоординований штурм, ти отримуєш $s1 $Lзаряд:заряди:зарядів; Бомби дикого вогню. \n\n\n\nКоли Скоординований штурм завершується, перезарядження Вибухового пострілу скидається, а твій наступний Вибуховий постріл влучає в ${$459859s2-1} додаткових цілей з $s2% ефективністю." },
    { en = "Serpent Sting and Bleed damage increased by $s1%. This value is increased to $s2% against targets below $s3% health.", ua = "Шкода від Зміїного Жала та кровотеч збільшена на $s1%. Це значення зростає до $s2% проти цілей зі здоров'ям нижче $s3%." },
    { en = "When Darkglare deals damage, it deals $s1% of that damage to all enemies affected by your damage over time effects.", ua = "Коли Темнозор завдає шкоди, він завдає $s1% цієї шкоди всім ворогам, що зазнають твоїх ефектів періодичної шкоди." },
    { en = "Activating Avatar or Recklessness grants ${$s1/1000} sec of the other.", ua = "Активація Аватара або Безрозсудності дарує ${$s1/1000} сек. іншого ефекту." },
    { en = "While Avatar is active Rampage's Rage cost is reduced by ${$107574s10/-10} and Bloodthirst's cooldown is reduced by ${$107574s9/-1000}.1 sec.", ua = "Поки активний Аватар, витрата Люті на Буйство зменшена на ${$107574s10/-10}, а перезарядження Жаги Крові зменшене на ${$107574s9/-1000}.1 сек." },
    { en = "Activating Avatar grants ${$s1/1000} sec of Sweeping Strikes and while Avatar is active the cooldown of Cleave is reduced by ${$107574s8/-1000}.1 sec.", ua = "Активація Аватара дарує ${$s1/1000} сек. Розмашистих Ударів, і поки активний Аватар, перезарядження Розсікання зменшене на ${$107574s8/-1000}.1 сек." },
    { en = "Activating Avatar grants ${$s1/1000} sec of Recklessness.\n\n\n\nThe additional Rage generation of this Recklessness is reduced to $s2%.", ua = "Активація Аватара дарує ${$s1/1000} сек. Безрозсудності.\n\n\n\nДодаткове вироблення Люті цією Безрозсудністю знижене до $s2%." },
    { en = "Scourge Strike causes your disease damage to occur ${100*(1/(1+$s1/100)-1)}% more quickly for $390178d.", ua = "Удар Погибелі змушує шкоду від твоїх хвороб відбуватися на ${100*(1/(1+$s1/100)-1)}% швидше протягом $390178d." },
    { en = "$?s137015[Cobra Shot]?s137016[Aimed Shot]?s259387[Mongoose Bite][Raptor Strike] has a chance to fling an Arctic Bola at your target, dealing ${$@traitentryrank100514*$390232s1} Frost damage and snaring the target by $390232s2% for $390232d. The Arctic Bola strikes up to $s1 $Ltarget:targets;.", ua = "$?s137015[Постріл кобри]?s137016[Прицільний постріл]?s259387[Укус мангуста][Удар раптора] має шанс метнути Арктичну болу в твою ціль, завдаючи ${$@traitentryrank100514*$390232s1} шкоди від морозу та сповільнюючи ціль на $390232s2% на $390232d. Арктична бола влучає до $s1 $Lцілі:цілей:цілей;." },
    { en = "When your ghouls expire, they explode in viscera dealing $<damage> Shadow damage to nearby enemies. Each explosion has a $s1% chance to apply Festering Wounds to enemies hit.", ua = "Коли ваші упирі гинуть, вони вибухають нутрощами, завдаючи $<damage> шкоди від Темряви ворогам поблизу. Кожен вибух має $s1% шансу накласти Гнійні рани на уражених ворогів." },
    { en = "Inflict disease upon your enemies spreading Festering Wounds equal to the amount currently active on your target to $s1 nearby enemies.", ua = "Насилає хворобу на ваших ворогів, поширюючи Гнійні рани в кількості, наразі активній на вашій цілі, на $s1 ворогів поблизу." },
    { en = "Overload a nearby elemental herb.\n\n\n\n$?pc106421[The cooldown of this ability is reduced whenever you gather herbs native to the Dragon Isles.][Specialize into Master of the Elements to gain significant cooldown reduction on this ability whenever you gather herbs native to the Dragon Isles.]", ua = "Перевантажує елементальну траву поблизу.\n\n\n\n$?pc106421[Перезарядження цієї здібності скорочується щоразу, коли ти збираєш трави, рідні для Драконових Островів.][Спеціалізуйся на «Володарі стихій», щоб суттєво скоротити перезарядження цієї здібності щоразу, коли ти збираєш трави, рідні для Драконових Островів.]" },
    { en = "While Bladestorming or Ravager is active, you gain $s2% movement speed and $s1% Strength every $?c2[$390719t1][$390577t1] sec, stacking up to $s3 times. Lasts $390581d. \n\n\n\nBladestorm cannot be canceled while using Hurricane.", ua = "Поки активний Вихор клинків або Спустошувач, ти отримуєш $s2% швидкості руху та $s1% Сили кожні $?c2[$390719t1][$390577t1] с, накопичуючись до $s3 разів. Триває $390581d. \n\n\n\nВихор клинків не можна скасувати під час використання Урагану." },
    { en = "Each time Shadow Word: Pain$?a137031[ or Holy Fire][] deals damage, the healing of your next Flash Heal is increased by $s1%, up to a maximum of $?a137033&$?a134735[$390617s2][${$s1*$390617u}]%.", ua = "Щоразу, коли Слово Тіні: Біль$?a137031[ чи Священний вогонь][] завдає шкоди, зцілення твого наступного Швидкого зцілення зростає на $s1%, до максимуму в $?a137033&$?a134735[$390617s2][${$s1*$390617u}]%." },
    { en = "Every $t1 sec, the damage of your next Holy Nova is increased by $390636s1% and its healing is increased by $390636s2%. \n\n\n\nStacks up to $390636u times.", ua = "Кожні $t1 с шкода вашої наступної Святої нови зростає на $390636s1%, а її зцілення зростає на $390636s2%. \n\n\n\nНакопичується до $390636u разів." },
    { en = "Your $?s137031[Holy Fire][Mind Blast] critical strikes reduce your target's movement speed by $390669s1% for $390669d.", ua = "Критичні удари твого $?s137031[Священного вогню][Удару розуму] зменшують швидкість руху твоєї цілі на $390669s1% на $390669d." },
    { en = "$?c1[When an enemy dies while affected by your Bladestorm, all damage you deal is increased by $459572s1% for the remainder of the Bladestorm and for $459572d afterwards.\n\n\n\n][]When an enemy dies while affected by your Ravager, its duration is extended by ${$s1/1000} sec.\n\n\n\n$?c1[These effects][This effect] can trigger a maximum of $s2 times per use of $?c1[Bladestorm or ][]Ravager.", ua = "$?c1[Коли ворог гине під дією твого Вихору клинків, уся завдана тобою шкода зростає на $459572s1% на решту тривалості Вихору клинків і ще на $459572d після.\n\n\n\n][]Коли ворог гине під дією твого Спустошувача, його тривалість подовжується на ${$s1/1000} с.\n\n\n\n$?c1[Ці ефекти можуть][Цей ефект може] спрацювати щонайбільше $s2 разів за одне застосування $?c1[Вихору клинків чи ][]Спустошувача." },
    { en = "Shockwave deals $s1% increased damage and will always critical strike.", ua = "Ударна хвиля завдає на $s1% більше шкоди і завжди завдає критичного удару." },
    { en = "Your Renew healing increases the healing done by your next Prayer of Healing by $390885s1%, stacking up to $390885U times.", ua = "Зцілення твого Оновлення збільшує зцілення твоєї наступної Молитви зцілення на $390885s1%, накопичуючись до $390885U разів." },
    { en = "Circle of Healing heals $s1 additional ally and its cooldown is reduced by ${$s2/-1000} sec.", ua = "Коло зцілення зцілює $s1 додаткового союзника, а його перезарядження зменшується на ${$s2/-1000} с." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20|a herbs gathered from the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20|a.", ua = "Переробляє $M1 трав якості |A:Professions-ChatIcon-Quality-Tier1:20:20|a, зібраних на Драконових Островах, на 1 траву якості |A:Professions-ChatIcon-Quality-Tier2:20:20|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20|a herbs gathered from the Dragon Isles to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20|a.", ua = "Переробляє $M1 трав якості |A:Professions-ChatIcon-Quality-Tier2:20:20|a, зібраних на Драконових Островах, на 1 траву якості |A:Professions-ChatIcon-Quality-Tier3:20:20|a." },
    { en = "Slow applies to all enemies within $391104A1 yds of your target.", ua = "Уповільнення накладається на всіх ворогів у радіусі $391104A1 ярдів від вашої цілі." },
    { en = "Increases your non-periodic Shadow damage by $s1% for $d.\n\n\n\n|cFFFFFFFFGenerates ${$m6/100} Insanity.|r", ua = "Збільшує вашу неперіодичну шкоду від Темряви на $s1% на $d.\n\n\n\n|cFFFFFFFFСтворює ${$m6/100} Безумства.|r" },
    { en = "When Prayer of Mending jumps to a target affected by your Renew, that target is instantly healed for $391156s1.", ua = "Коли Молитва зцілення перестрибує на ціль, уражену вашим Оновленням, ця ціль миттєво зцілюється на $391156s1." },
    { en = "Increases the initial damage of Devouring Plague by $s1%.", ua = "Збільшує початкову шкоду Ненажерливої чуми на $s1%." },
    { en = "Shatter an Enchanting reagent into 3 of lesser rarity.", ua = "Розбиває реагент чароплетства на 3 менш рідкісних." },
    { en = "Shatter an Awakened element to gain its power for $392761d.\n\n\n\nCan only be performed in the Dragon Isles.", ua = "Розбиває Пробуджений елемент, щоб отримати його силу на $392761d.\n\n\n\nМожна виконати лише на Драконових Островах." },
    { en = "Renew reduces the cooldown of Sanctify by an additional ${$s1/1000} sec and heals for $s2% more when cast, but has a ${$s3/1000} sec cooldown.", ua = "Оновлення зменшує перезарядження Освячення додатково на ${$s1/1000} с і зцілює на $s2% більше при застосуванні, але має перезарядження ${$s3/1000} с." },
    { en = "Enemies and allies hit by Jadefire Stomp are affected by Jadefire Brand, increasing your damage and healing against them by $395413s1% for $395413d.", ua = "Вороги та союзники, уражені Нефритовим тупотом, зазнають Нефритового тавра, що збільшує вашу шкоду та зцілення щодо них на $395413s1% на $395413d." },
    { en = "Spectral Sight has ${$s2/1000} sec increased cooldown and now reveals a condemned demon for $391430d. $?a212613[Fel Devastation][Eye Beam] and Throw Glaive deal lethal damage to the demon, granting $347765s1% increased damage for $347765d.\n\n\n\nThe demon explodes on death, dealing $350631s1 $@spelldesc395041 damage to nearby enemies and healing you for $350631s2% of your maximum health. The explosion deals reduced damage beyond $s1 targets.", ua = "Примарний зір має на ${$s2/1000} с більше перезарядження й тепер виявляє приреченого демона на $391430d. $?a212613[Спустошення Скверни][Промінь ока] та Метання глефи завдають демону смертельної шкоди, надаючи $347765s1% більше шкоди на $347765d.\n\n\n\nПри загибелі демон вибухає, завдаючи $350631s1 шкоди від $@spelldesc395041 ворогам поблизу та зцілюючи тебе на $350631s2% твого максимального здоров'я. Вибух завдає меншої шкоди понад $s1 цілей." },
    { en = "Thunderous Roar's cooldown reduced by ${$s1/-1000} sec.", ua = "Перезарядження «Громового рику» скорочено на ${$s1/-1000} с." },
    { en = "Odyn's Fury increases your auto-attack damage and speed by $391688s1% for $391688d.", ua = "«Лють Одина» підвищує шкоду й швидкість ваших автоатак на $391688s1% на $391688d." },
    { en = "Primal Wrath consumes up to $s1 sec of Rip damage on targets it hits and deals $s2% of it instantly.\n\n\n\nDuring $?s102543[Incarnation: Avatar of Ashamane][Berserk], Rip duration consumed is increased to $s4 sec.", ua = "Первісний гнів поглинає до $s1 с шкоди Роздирання на цілях, у які влучає, і завдає $s2% від неї миттєво.\n\n\n\nПід час $?s102543[Втілення: Аватара Ашамані][Берсерка] поглинута тривалість Роздирання зростає до $s4 с." },
    { en = "Temporarily imbues shoulders with an illusion of Order for $ecd.", ua = "Тимчасово наповнює наплічники ілюзією Порядку на $ecd." },
    { en = "Refreshes the duration of your active Lifebloom and Rejuvenation effects on the target and causes them to complete $s1% faster.", ua = "Оновлює тривалість ваших активних ефектів «Цвіту життя» й «Омолодження» на цілі та прискорює їхнє завершення на $s1%." },
    { en = "You may Lifebloom two targets at once, but Lifebloom's healing is reduced by $s1%.", ua = "Ви можете застосовувати «Цвіт життя» на двох цілях одночасно, але зцілення від «Цвіту життя» зменшено на $s1%." },
    { en = "$?a317320[Condemn][Execute] increases the critical strike chance of $?a317320[Condemn][Execute] by $392537s1% for $392537d, stacking up to $392537u times.", ua = "$?a317320[Осуд][Страта] збільшує шанс критичного удару $?a317320[Осуду][Страти] на $392537s1% на $392537d, накопичуючись до $392537u разів." },
    { en = "Holy Shock's healing and damage is increased by $s1%.", ua = "Зцілення та шкода від «Святого шоку» підвищено на $s1%." },
    { en = "You are able to block spells for $392966d.", ua = "Ви можете блокувати закляття протягом $392966d." },
    { en = "Fists of Fury damage increased by $s4%. When Fists of Fury deals damage, it has a $s2% chance to refund $s3 Chi.", ua = "Шкода «Кулаків люті» підвищена на $s4%. Коли «Кулаки люті» завдають шкоди, є $s2% шанс повернути $s3 ці." },
    { en = "Chi spenders increase the damage of your next Crackling Jade Lightning by $393039s1% and reduce its cost by $393039s2%, stacking up to $393039u times.", ua = "Здібності, що витрачають ці, підвищують шкоду вашого наступного «Тріскучого нефритового блискавичного удару» на $393039s1% і зменшують його вартість на $393039s2%. Накопичується до $393039u разів." },
    { en = "Tiger Palm now has a ${$m1+5} yard range and dashes you to the target when used.\n\n\n\nTiger Palm also applies an effect which increases your critical strike chance by $344021m1% for $344021d on the target. This effect cannot be applied more than once every $337341d per target.", ua = "«Тигряча лапа» тепер має радіус дії ${$m1+5} ярдів і при застосуванні кидає вас до цілі.\n\n\n\n«Тигряча лапа» також накладає на ціль ефект, що підвищує ваш шанс критичного удару на $344021m1% на $344021d. Цей ефект неможливо накласти частіше, ніж раз на $337341d для кожної цілі." },
    { en = "Your Nature spells deal ${$s3}.1% increased damage.\n\n\n\nYour Arcane spells deal ${$s1}.1% increased damage.", ua = "Ваші закляття природи завдають на ${$s3}.1% більше шкоди.\n\n\n\nВаші арканні закляття завдають на ${$s1}.1% більше шкоди." },
    { en = "Touch of Death deals $s2% increased damage and can be used a second time within $213114d before its cooldown is triggered.", ua = "«Дотик смерті» завдає на $s2% більше шкоди й може бути застосований удруге протягом $213114d, перш ніж почнеться його перезарядження." },
    { en = "When Tar Trap is activated, all enemies in its area are rooted for $393456d. Damage taken may break this root.", ua = "Коли активується «Смоляна пастка», усі вороги в її зоні знерухомлюються на $393456d. Отримана шкода може зняти це знерухомлення." },
    { en = "Triggering a bonus attack from Press the Advantage or casting Weapons of Order releases a surge of chi at your target's location, dealing Nature damage split evenly between all targets over $393786d.\n\n\n\n$@spellicon418359 $@spellname418359:\n\nDeals $<ptadmg> Nature damage.\n\n\n\n$@spellicon387184 $@spellname387184:\n\nDeals $<dmg> Nature damage and reduces the cooldown of Weapons of Order by $s1 for each affected enemy, to a maximum of ${$s1*5} sec.", ua = "Спрацювання бонусної атаки від Розвинути перевагу або застосування Зброї Порядку вивільняє сплеск ці в місці твоєї цілі, завдаючи шкоди від природи, рівномірно розподіленої між усіма цілями протягом $393786d.\n\n\n\n$@spellicon418359 $@spellname418359:\n\nЗавдає $<ptadmg> шкоди від природи.\n\n\n\n$@spellicon387184 $@spellname387184:\n\nЗавдає $<dmg> шкоди від природи та скорочує перезарядження Зброї Порядку на $s1 за кожного враженого ворога, до максимуму в ${$s1*5} с." },
    { en = "Thunder Focus Tea also empowers $s1 additional Renewing Mist or Enveloping Mist at random.", ua = "«Чай грозової зосередженості» також випадково підсилює $s1 додаткове застосування «Оновлювального туману» чи «Огортального туману»." },
    { en = "Execute increases Execute's damage dealt by $393968s1% for $393968d, stacking up to $393968u times.", ua = "«Страта» підвищує завдану шкоду «Страти» на $393968s1% на $393968d. Накопичується до $393968u разів." },
    { en = "While moving at low speeds, Surge Forward's effectiveness is increased by up to $s1%, decreasing as speed increases.", ua = "Під час руху на низькій швидкості ефективність «Ривка вперед» підвищується до $s1%, зменшуючись зі зростанням швидкості." },
    { en = "Shadow Techniques generates $s1 additional Energy.", ua = "«Тіньові прийоми» генерують $s1 додаткової Енергії." },
    { en = "Your skills at harvesting have granted you some anatomical knowledge, providing you with $s1% increased damage against beasts and dragonkin while outdoors in the Dragon Isles.", ua = "Ваші навички збирання дали вам певні анатомічні знання, збільшуючи вашу шкоду проти звірів і драконоподібних на $s1% на відкритій місцевості Драконових Островів." },
    { en = "Wounds the target, causing $s1 Physical damage instantly and an additional $394063o1 Bleed damage over $394063d.$?s6343[\n\n\n\n|cFFFFFFFFThunder Clap affects $6343s5 nearby targets with Rend.\n\n][]", ua = "Ранить ціль, завдаючи $s1 фізичної шкоди миттєво та додатково $394063o1 шкоди від кровотечі протягом $394063d.$?s6343[\n\n\n\n|cFFFFFFFFГрім грози накладає Роздирання на $6343s5 цілей поблизу.\n\n][]" },
    { en = "Bonedust Brew's radius increased by $s1%.", ua = "Радіус «Кістяного пилового вару» збільшено на $s1%." },
    { en = "Activating Avatar or Shield Wall grants ${$s1/1000} sec of the other.", ua = "Активація «Аватара» чи «Стіни щитів» надає ${$s1/1000} с дії іншого." },
    { en = "Shield Charge critical strike chance and critical strike damage increased by $s2% and Shield Charge increases your auto-attack damage and speed by $394313s1% for $394313d.", ua = "Шанс і шкода критичного удару «Наскоку зі щитом» збільшені на $s2%, а «Наскок зі щитом» збільшує шкоду й швидкість ваших автоатак на $394313s1% на $394313d." },
    { en = "Odyn's Fury's Enrages you, deals $s2% increased damage and grants you $85739u stacks of Whirlwind.", ua = "«Лють Одина» розлючує вас, завдає на $s2% більше шкоди й надає вам $85739u стосів «Вихору»." },
    { en = "Touch of Death strikes up to $s1 additional nearby $Ltarget;targets. This Touch of Death is always an Improved Touch of Death.", ua = "Дотик смерті влучає до $s1 додаткових $Lцілі;цілей; поблизу. Цей Дотик смерті завжди є Покращеним дотиком смерті." },
    { en = "$@spellname395160 $?s414969[or $@spellname355913 ][]increases the duration of your active Ebon Might effects by ${$s1/1000} sec.\n\n\n\nYour empower spells increase the duration of your active Ebon Might effects by ${$s2/1000} sec.\n\n\n\n$?s403631[$@spellname403631][$@spellname357210] increases the duration of your active Ebon Might effects by ${$s3/1000} sec.\n\n\n\nThis effect can critically strike, increasing the duration of Ebon Might by an additional $s4%.", ua = "$@spellname395160 $?s414969[або $@spellname355913 ][]збільшує тривалість ваших активних ефектів Чорної Могуті на ${$s1/1000} с.\n\n\n\nВаші наснажені закляття збільшують тривалість ваших активних ефектів Чорної Могуті на ${$s2/1000} с.\n\n\n\n$?s403631[$@spellname403631][$@spellname357210] збільшує тривалість ваших активних ефектів Чорної Могуті на ${$s3/1000} с.\n\n\n\nЦей ефект може завдати критичного удару, додатково збільшуючи тривалість Чорної Могуті на $s4%." },
    { en = "$@spellname395152 and $@spellname403631 are $s1% more effective when not in a raid.", ua = "$@spellname395152 та $@spellname403631 на $s1% ефективніші поза рейдом." },
    { en = "Your Combo Strikes grant a stacking ${$396167s3/100}% chance for your next Fists of Fury to grant $396168s1% critical strike, haste, and mastery and invoke Xuen, The White Tiger for $396168d.", ua = "Ваші «Комбо-удари» надають кумулятивний шанс ${$396167s3/100}%, що ваш наступний «Кулак люті» надасть $396168s1% Критичного удару, Поспіху й Майстерності та закличе Ксуеня, Білого Тигра, на $396168d." },
    { en = "Weapons of Order calls forth $?c1[Niuzao, the Black Ox]?c2&s325197[Chi-Ji, the Red Crane]?c3[Xuen, the White Tiger][Yu'lon, the Jade Serpent] to assist you for ${$s1/1000} sec.\n\n\n\nTriggering a bonus attack with Press the Advantage has a chance to call forth Niuzao, the Black Ox.", ua = "Зброя Ладу прикликає $?c1[Ніуцао, Чорного Вола]?c2&s325197[Чі-Джі, Червоного Журавля]?c3[Сюеня, Білого Тигра][Ю'лон, Нефритову Змію] вам на допомогу на ${$s1/1000} с.\n\n\n\nБонусна атака від «Тисни на перевагу» має шанс прикликати Ніуцао, Чорного Вола." },
    { en = "Malefic Rapture deals $s1% increased damage to targets suffering from Unstable Affliction.", ua = "«Лиховісна нестяма» завдає на $s1% більше шкоди цілям, що страждають від «Нестабільної недуги»." },
    { en = "Overpower has a $h% chance to trigger an extra attack dealing $400206s1 damage and generating ${$400206s2/10} Rage.", ua = "«Здолання» має шанс $h% викликати додаткову атаку, що завдає $400206s1 шкоди й генерує ${$400206s2/10} Люті." },
    { en = "Each time you cast Sheilun's Gift, you learn one of Shaohao's Lessons for up to $s1 sec, with the duration based on how many clouds of mist are consumed.\n\n\n\n|cffffffffLesson of Doubt|r: Your spells and abilities deal up to $400097s1% more healing and damage to targets, based on their current health.\n\n\n\n|cffffffffLesson of Despair|r: Your Critical Strike is increased by $400100s1% while above $400100s2% health.\n\n\n\n|cffffffffLesson of Fear|r: Decreases your damage taken by $400103s1% and increases your Haste by $400103s2%.\n\n\n\n|cffffffffLesson of Anger|r: $400106s1% of the damage or healing you deal is duplicated every $400106s2 sec.", ua = "Щоразу, коли ви творите «Дар Шейлуна», ви опановуєте один з уроків Шаохао на строк до $s1 с, і тривалість залежить від того, скільки хмар туману спожито.\n\n\n\n|cffffffffУрок сумніву|r: ваші закляття та здібності завдають до $400097s1% більше зцілення й шкоди цілям залежно від їхнього поточного здоров'я.\n\n\n\n|cffffffffУрок відчаю|r: ваш Критичний удар збільшено на $400100s1%, поки ваше здоров'я вище $400100s2%.\n\n\n\n|cffffffffУрок страху|r: зменшує отриману вами шкоду на $400103s1% і збільшує ваш Поспіх на $400103s2%.\n\n\n\n|cffffffffУрок гніву|r: $400106s1% шкоди або зцілення, що ви завдаєте, дублюється кожні $400106s2 с." },
    { en = "When you cast Ironfur, also deal Physical damage equal to $s1% of your armor, split among enemies within $r yards. Damage reduced above $s2 applications.", ua = "Коли ви творите «Залізне хутро», ви також завдаєте фізичної шкоди в розмірі $s1% вашої броні, розподіленої між ворогами в межах $r метрів. Шкода зменшується понад $s2 накладань." },
    { en = "Colossus Smash's duration is increased by $s1% but its damage bonus is reduced by $s2%.", ua = "Тривалість «Удару колоса» збільшено на $s1%, але його бонус до шкоди зменшено на $s2%." },
    { en = "Aimed Shot and Rapid Fire cooldown reduced by $s1%.", ua = "Перезарядження «Прицільного пострілу» та «Швидкого вогню» зменшено на $s1%." },
    { en = "Activating Aerial Halt while affected by Thrill of the Skies generates $s1 Vigor.", ua = "Активація «Повітряної зупинки» під дією «Захвату небес» генерує $s1 Завзяття." },
    { en = "Divine Protection reduces damage you take by an additional $s1%.", ua = "«Божественний захист» додатково зменшує отриману вами шкоду на $s1%." },
    { en = "Blade of Justice and Expurgation now deal Holy damage.", ua = "«Клинок правосуддя» та «Очищення» тепер завдають Святої шкоди." },
    { en = "Flash of Light casts instantly, its healing done is increased by $s3%, but it now has a ${$s1/1000} sec cooldown.", ua = "«Спалах світла» твориться миттєво, його зцілення збільшено на $s3%, але тепер має перезарядження ${$s1/1000} сек." },
    { en = "Every $t1 sec, gain $403976s1% increased damage to your next Divine Storm, stacking up to $403976u times.", ua = "Кожні $t1 сек ви отримуєте $403976s1% додаткової шкоди для наступного «Божественного шторму», накопичуючись до $403976u разів." },
    { en = "The lowest health target of Healing Tide Totem is healed for $s1% more and receives $404072s1% increased healing from you for $404072d.", ua = "Ціль «Тотема цілющого припливу» з найнижчим здоров'ям зцілюється на $s1% більше та отримує на $404072s1% більше зцілення від вас протягом $404072d." },
    { en = "When skyriding near the ground, your Skyriding Charges recharge faster.", ua = "Під час небесного польоту біля землі ваші заряди небесного польоту відновлюються швидше." },
    { en = "Ground Skimming regenerates $s1 Vigor every $s2 sec.", ua = "«Ковзання над землею» відновлює $s1 завзяття кожні $s2 сек." },
    { en = "Highlord's Judgment and Holystrike damage abilities grant you a stack of Divine Arbiter.\n\n\n\nAt $s3 stacks your next damaging single target Holy Power ability causes $406983s1 Holystrike damage to your primary target and $406983s2 Holystrike damage to enemies within 6 yds.", ua = "«Суд верховного лорда» та здібності, що завдають шкоди святим ударом, дають вам заряд «Божественного арбітра».\n\n\n\nПри $s3 зарядах ваша наступна одноцільова здібність, що завдає шкоди й витрачає святу силу, завдає $406983s1 шкоди святим ударом основній цілі та $406983s2 шкоди святим ударом ворогам у межах 6 ярдів." },
    { en = "After using Healing Tide Totem, the cast time of your next $404523u Healing Surges within $404523d is reduced by $404523s1% and their mana cost is reduced by $404523s2%.", ua = "Після використання «Тотема цілющого припливу» час прочитання ваших наступних $404523u «Цілющих хвиль» протягом $404523d зменшується на $404523s1%, а їхня вартість мани зменшується на $404523s2%." },
    { en = "Increases the duration of Mana Tide Totem by ${$s1/1000} sec and increases its radius by $s2 yards.", ua = "Збільшує тривалість «Тотема припливу мани» на ${$s1/1000} сек і збільшує його радіус на $s2 ярдів." },
    { en = "Highlord's Judgment and Radiant damage abilities have a chance to call down an explosion of Holy Fire dealing $407478s2 Radiant damage to all nearby enemies and leaving a Consecration in its wake. \n\n\n\nDeals reduced damage beyond 8 targets.", ua = "«Суд верховного лорда» та здібності, що завдають променистої шкоди, мають шанс закликати вибух Святого вогню, який завдає $407478s2 променистої шкоди всім ворогам поблизу та лишає по собі «Освячення». \n\n\n\nЗавдає зменшеної шкоди понад 8 цілей." },
    { en = "When any party or raid member within $a1 yards dies, you gain Avenging Wrath for $s1 sec.", ua = "Коли будь-який член групи чи рейду в межах $a1 ярдів гине, ви отримуєте «Караючий гнів» на $s1 сек." },
    { en = "Tiger Palm also applies an effect which increases your critical strike chance by $393047m1% for $393047d on the target. This effect cannot be applied more than once every $393050d per target.", ua = "«Долоня тигра» також накладає на ціль ефект, що збільшує ваш шанс критичного удару на $393047m1% протягом $393047d. Цей ефект не можна накласти частіше, ніж раз на $393050d для однієї цілі." },
    { en = "Divine Storm, Divine Hammer and Consecration now deal Radiant damage and your abilities that deal Radiant damage deal $s2% increased damage.", ua = "«Божественний шторм», «Божественний молот» та «Освячення» тепер завдають променистої шкоди, а ваші здібності, що завдають променистої шкоди, завдають на $s2% більше шкоди." },
    { en = "Shred deals $s1% increased damage against bleeding targets and Shred and $?s202028[Brutal Slash][Swipe] apply the Bleed damage over time from Thrash, if known.", ua = "Шматування завдає на $s1% більше шкоди цілям, що кровоточать, а Шматування та $?s202028[Жорстокий удар][Замах] накладають періодичну шкоду від кровотечі Молотіння, якщо ви ним володієте." },
    { en = "Shadow Bolt and Drain Soul deal an additional $s1% damage.", ua = "«Тіньова стріла» та «Викрадення душі» завдають додатково $s1% шкоди." },
    { en = "Malefic Rapture damage increased by $s1%. $?a445465[Wither][Corruption] damage increased by $s2%.", ua = "Шкода від Лиховісного Захвату збільшена на $s1%. Шкода від $?a445465[Зів'янення][Псування] збільшена на $s2%." },
    { en = "Crush the target for $s3 damage and stuns the target for $d Physical damage.", ua = "Розчавлює ціль, завдаючи $s3 шкоди, і приголомшує ціль на $d фізичної шкоди." },
    { en = "Holy Power generating abilities have a chance to cause your next $?s383328[Final Verdict]?s215661[Justicar's Vengeance][Templar's Verdict] to hit an additional $s2 targets at $s3% effectiveness.", ua = "Здібності, що генерують Святу Силу, мають шанс дати вашому наступному застосуванню $?s383328[Останнього Вироку]?s215661[Помсти Правосудця][Вироку Тамплієра] уразити $s2 додаткові цілі з $s3% ефективністю." },
    { en = "Firestorm's radius is increased by $s1%, and Pyre deals $s2% increased damage to enemies within your Firestorm.", ua = "Радіус «Вогняного шторму» збільшено на $s1%, а «Багаття» завдає на $s2% більше шкоди ворогам у межах вашого Вогняного шторму." },
    { en = "When you consume a Demonic Core, your primary Felguard carves your target, dealing $<damage> Physical damage.", ua = "Коли ви споживаєте Демонічне ядро, ваш головний Вартовий Скверни шматує ціль, завдаючи $<damage> фізичної шкоди." },
    { en = "Eye of Tyr deals $s1% increased damage and has $s2% reduced cooldown.", ua = "«Око Тіра» завдає на $s1% більше шкоди й має на $s2% менше перезарядження." },
    { en = "$@spellicon385127$@spellname385127:\n\nBlessing of Dawn increases the damage and healing of your next Holy Power spending ability by an additional $s1%.\n\n\n\n$@spellicon385126$@spellname385126:\n\nBlessing of Dusk causes your Holy Power generating abilities to also grant an absorb shield for $s2% of damage or healing dealt.", ua = "$@spellicon385127$@spellname385127:\n\nБлагословення світанку збільшує шкоду та зцілення вашої наступної здібності, що витрачає Святу Силу, додатково на $s1%.\n\n\n\n$@spellicon385126$@spellname385126:\n\nБлагословення присмерку робить так, що ваші здібності, які генерують Святу Силу, також надають поглинальний щит на $s2% завданої шкоди чи зцілення." },
    { en = "Hand of Gul'dan has a $s1% chance to burn its target for ${$405802s1*(1+$s2/100)} additional Shadowflame damage every $405802t1 sec for $405802d.\n\n\n\nIf this effect is reapplied, any remaining damage will be added to the new Umbral Blaze.", ua = "«Рука Ґул'дана» має $s1% шанс палити ціль, завдаючи ${$405802s1*(1+$s2/100)} додаткової шкоди тіньовим полум'ям щосекунди протягом $405802t1 сек. упродовж $405802d.\n\n\n\nЯкщо цей ефект накладено повторно, будь-яка залишкова шкода додається до нового «Тіньового спалаху»." },
    { en = "Kill Shot now grants the Trick Shots effect.", ua = "«Смертельний постріл» тепер надає ефект «Хитрі постріли»." },
    { en = "While stealthed, Rake will also stun the target for $163505d, and deal $1822s4% increased damage.\n\n\n\nWhile stealthed, Shred deals $5221s3% increased damage, and has double the chance to critically strike.", ua = "У скраданні «Удар кігтями» також приголомшує ціль на $163505d і завдає на $1822s4% більше шкоди.\n\n\n\nУ скраданні «Роздирання» завдає на $5221s3% більше шкоди й має подвоєний шанс критичного удару." },
    { en = "$?c1[Agony damage increased by $s1%.]?c2[Wild Imp damage increased by $s2%.][Immolate damage increased by $s3%.]", ua = "$?c1[Шкода від Агонії збільшена на $s1%.]?c2[Шкода від Дикого біса збільшена на $s2%.][Шкода від Спалення збільшена на $s3%.]" },
    { en = "$?c1[Shadow Bolt and Drain Soul damage increased by $s1%.]?c2[Shadow Bolt damage increased by $s1%.][Incinerate damage increased by $s2%.]", ua = "$?c1[Шкода від Тіньової стріли та Виснаження душі збільшена на $s1%.]?c2[Шкода від Тіньової стріли збільшена на $s1%.][Шкода від Спопеління збільшена на $s2%.]" },
    { en = "When you kill an enemy that yields experience or honor, $?s414969[][the cooldown of Emerald Blossom is refreshed and ]your next Emerald Blossom within $406043d restores an additional $406054s1% of maximum health to you$?s414969 [ and costs no Essence.][.]", ua = "Коли ви вбиваєте ворога, що дає досвід або честь, $?s414969[][перезарядження Смарагдового Цвіту оновлюється, і ]ваш наступний Смарагдовий Цвіт протягом $406043d додатково відновлює вам $406054s1% максимального здоров'я$?s414969 [ і не потребує Есенції.][.]" },
    { en = "Final Reckoning and Execution Sentence grant $408386s1 Holy Power.", ua = "«Остаточна відплата» і «Смертний вирок» надають $408386s1 Святої сили." },
    { en = "Casting an empower spell grants Shifting Sands to $s3 $Lally:allies;, preferring damage dealers, increasing their Versatility by ${$413984s1}.1% for $413984d.\n\n\n\nThe durations of Shifting Sands, Breath of Eons, and your other helpful auras are increased by ${$s2}.1%.", ua = "Застосування наснаженого закляття надає Мінливі Піски $s3 $Lсоюзнику:союзникам;, надаючи перевагу бійцям шкоди, збільшуючи їхню Універсальність на ${$413984s1}.1% на $413984d.\n\n\n\nТривалість Мінливих Пісків, Подиху Еонів та інших ваших корисних аур збільшена на ${$s2}.1%." },
    { en = "Aimed Shot coalesces $s1 Wind $LArrow:Arrows; that shoot your target for $191043s1 Physical damage.\n\n\n\nEach time Rapid Fire deals damage, there is a 5% chance to coalesce a Wind Arrow at your target.", ua = "Прицільний постріл матеріалізує $s1 $Lвітряну стрілу:вітряних стріл;, що вражають вашу ціль на $191043s1 фізичної шкоди.\n\n\n\nЩоразу, коли Швидкий вогонь завдає шкоди, є 5% шанс матеріалізувати вітряну стрілу на вашій цілі." },
    { en = "Hammer of Wrath deals $s1% increased damage to enemies below $s2% health.", ua = "«Молот гніву» завдає на $s1% більше шкоди ворогам зі здоров'ям нижче $s2%." },
    { en = "The duration of Final Reckoning is increased by ${$s1/1000} sec and Divine Hammer by ${$s2/1000} sec.", ua = "Тривалість «Остаточної відплати» збільшено на ${$s1/1000} сек., а «Божественного молота» — на ${$s2/1000} сек." },
    { en = "When Rapid Fire finishes channeling, your critical strike chance is increased by $407405s1% for $407405d.", ua = "Коли завершується підтримання «Швидкого вогню», ваш шанс критичного удару збільшено на $407405s1% протягом $407405d." },
    { en = "For each second you extend Ebon Might, increase the damage and healing and reduce the cast time of your next Living Flame by $s1%.", ua = "За кожну секунду продовження «Чорної могутності» шкода і зцілення вашого наступного «Живого полум'я» зростають, а час його прочитання зменшується на $s1%." },
    { en = "Crusader Strike generates $s1 additional Holy Power and deals $s2% more damage.", ua = "«Удар хрестоносця» створює на $s1 більше Святої сили й завдає на $s2% більше шкоди." },
    { en = "Glimmer of Light can affect $s1 additional targets.", ua = "«Проблиск світла» може вражати на $s1 більше цілей." },
    { en = "Cast $?c1[Prismatic]?c2[Blazing]?c3[Ice][] Barrier on yourself and $414661i allies within $s2 yds.", ua = "Застосуйте $?c1[Призматичний]?c2[Полум'яний]?c3[Крижаний][] Бар'єр на себе та $414661i союзників у межах $s2 м." },
    { en = "Glimmer of Light's healing and damage is increased by $s2%, but it can only affect ${$s1+3} target at a time.", ua = "Зцілення і шкода «Проблиску світла» збільшено на $s2%, але він може вражати лише ${$s1+3} ціль водночас." },
    { en = "Slams enemies in front of you with your shield, causing $s1 Holy damage, and reducing the cooldown of Holy Shock by ${$s4/1000}.1 sec and granting $1270617s1 mana.$?a386568[\n\n\n\n$@spelldesc386568][]$?a280373[\n\n\n\n$@spelldesc280373][]", ua = "Б'є ворогів перед вами вашим щитом, завдаючи $s1 священної шкоди, зменшуючи перезарядження Священного Струсу на ${$s4/1000}.1 с та надаючи $1270617s1 мани.$?a386568[\n\n\n\n$@spelldesc386568][]$?a280373[\n\n\n\n$@spelldesc280373][]" },
    { en = "Your primary Felguard's damaging critical strikes deal $s1% increased damage.", ua = "Шкідливі критичні удари вашого основного Вартового Скверни завдають на $s1% більше шкоди." },
    { en = "Increases the attack speed of your primary demon by $s1%.", ua = "Підвищує швидкість атаки вашого основного демона на $s1%." },
    { en = "Increases Hand of Gul'dan damage by $s1% and the critical strike chance of Hand of Gul'dan by $s2%.", ua = "Підвищує шкоду Руки Ґул'дана на $s1% і шанс критичного удару Руки Ґул'дана на $s2%." },
    { en = "Shadow Bolt deals $s1% increased damage and Demonbolt deals $s2% increased damage.", ua = "Тіньова стріла завдає на $s1% більше шкоди, а Демонічна стріла — на $s2% більше шкоди." },
    { en = "While Combustion is active your Fireball, Pyroblast, Fire Blast, Scorch, and Phoenix Flames deal $s1% increased damage and reduce the cooldown of Combustion by ${$s2/1000}.2 sec.\n\n\n\nWhile Combustion is active, Flamestrike deals $s4% increased damage and reduces the cooldown of Combustion by ${$s2/1000/$s3}.2 sec for each critical strike, up to ${$s2/1000}.2 sec.", ua = "Поки активне Займання, ваші Вогняна куля, Піровибух, Вогняний вибух, Обпалення та Феніксове полум'я завдають на $s1% більше шкоди й зменшують перезарядження Займання на ${$s2/1000}.2 сек.\n\n\n\nПоки активне Займання, Полум'яний удар завдає на $s4% більше шкоди й зменшує перезарядження Займання на ${$s2/1000/$s3}.2 сек за кожен критичний удар, аж до ${$s2/1000}.2 сек." },
    { en = "When Seed of Corruption deals damage to a target suffering from your Unstable Affliction they explode, dealing $416699s1 Shadow damage to all enemies within $416699A1 yards.", ua = "Коли Зерно Скверни завдає шкоди цілі, що потерпає від вашого Нестійкого Немочі, ціль вибухає, завдаючи $416699s1 шкоди Тінню всім ворогам у межах $416699A1 ярдів." },
    { en = "When a Living Bomb expires, if it did not spread to another target, it reapplies itself at $s1% effectiveness.\n\n\n\nA Living Bomb can only benefit from this effect once.", ua = "Коли дія Живої бомби добігає кінця, якщо вона не поширилася на іншу ціль, то накладається знову з ефективністю $s1%.\n\n\n\nЖива бомба може скористатися цим ефектом лише раз." },
    { en = "Your auto attacks heal a nearby ally for ${$416771s1*(1+$s2/100)}.", ua = "Ваші автоатаки зцілюють найближчого союзника на ${$416771s1*(1+$s2/100)}." },
    { en = "Hammer of Wrath has $s1 extra charge and on enemies below $s2% health generates ${$403081s1} additional Holy Power.", ua = "Молот Гніву має $s1 додатковий заряд і на ворогах зі здоров'ям нижче $s2% дає ${$403081s1} додаткової Святої Сили." },
    { en = "Each time you consume Fingers of Frost the damage of your next Ray of Frost is increased by $417492s1%, stacking up to ${$417492s1*$417492u}%. Icy Veins grants $417492u stacks instantly.", ua = "Щоразу, коли ви витрачаєте Крижані Пальці, шкода вашого наступного Промінь Морозу зростає на $417492s1%, накопичуючись до ${$417492s1*$417492u}%. Крижані Вени миттєво дають $417492u зарядів." },
    { en = "Unleash wicked magic upon your target's soul, dealing $o Shadow damage over $d.\n\n\n\nDeals $s2% increased damage, up to ${$s2*$s3}%, per damage over time effect you have active on the target.", ua = "Насилає лиху магію на душу цілі, завдаючи $o шкоди Тінню протягом $d.\n\n\n\nЗавдає на $s2% більше шкоди, аж до ${$s2*$s3}%, за кожен ефект періодичної шкоди, активний на цілі." },
    { en = "Brann will heal for $s1% of his maximum health after taking a significant amount of damage. Can only occur every $s2 sec.", ua = "Бранн зцілюється на $s1% свого максимального здоров'я після того, як зазнає значної шкоди. Може відбуватися лише кожні $s2 сек." },
    { en = "Brann uses his whip to lash the enemy, interrupting enemy spellcasting and preventing any spell in that school from being cast for $420530d.", ua = "Бранн шмагає ворога батогом, перериваючи чари ворога й не даючи творити жодне закляття цієї школи протягом $420530d." },
    { en = "Brann throws healing potions near injured players that restores a moderate amount of health upon walking through them.", ua = "Бранн кидає цілющі зілля біля поранених гравців, що відновлюють помірну кількість здоров'я, коли крізь них проходять." },
    { en = "Brann brandishes a powerful ancient relic that radiates Holy energy, healing allies for a tremendous amount every $461281t sec for $462761d.", ua = "Бранн вимахує могутньою прадавньою реліквією, що випромінює Святу енергію, зцілюючи союзників на величезну кількість кожні $461281t сек протягом $462761d." },
    { en = "Brann throws his rope to free players from stuns, bonds, and snares, and grants immunity to all such effects for $423419d.", ua = "Бранн кидає мотузку, щоб звільнити гравців від оглушень, пут і тенет, і надає імунітет до всіх таких ефектів на $423419d." },
    { en = "Brann fires tranquilizing darts at empowered enemies, removing $420616s1 Enrage and $420616s2 Magic effect.", ua = "Бранн стріляє заспокійливими дротиками по підсилених ворогах, знімаючи $420616s1 ефект люті та $420616s2 ефект магії." },
    { en = "Brann summons a devilsaur egg. Hopefully it hatches.", ua = "Бранн прикликає яйце дияволозавра. Сподіваймося, воно вилупиться." },
    { en = "Your spells and abilities have a chance to call Brann's pet monkey Glibb to your side for $433402d, bananas in hand. \n\n\n\n$@spellicon435533 $@spellname435533\n\n$@spelldesc435533\n\n\n\n$@spellicon463431 $@spellname463431\n\n$@spelldesc463431", ua = "Ваші закляття та здібності мають шанс прикликати мавпочку-улюбленця Бранна на ім'я Ґлібб вам на підмогу на $433402d, із бананами в руках. \n\n\n\n$@spellicon435533 $@spellname435533\n\n$@spelldesc435533\n\n\n\n$@spellicon463431 $@spellname463431\n\n$@spelldesc463431" },
    { en = "After $433058s1 or more enemies attack a player, Brann will hurl an ice trap at them, reducing their movement speed by $433244s1% and occasionally freezing them in place for $433249d. Trap lasts for $433240d.", ua = "Коли на гравця нападає $433058s1 або більше ворогів, Бранн жбурляє в них крижану пастку, знижуючи їхню швидкість пересування на $433244s1% і час від часу заморожуючи на місці на $433249d. Пастка триває $433240d." },
    { en = "When any player falls below $433991s1% health, Brann will instantly heal them for $432515s1% of their maximum health. Can only occur every $433622d.", ua = "Коли здоров'я будь-якого гравця падає нижче $433991s1%, Бранн миттєво зцілює його на $432515s1% від максимального здоров'я. Може статися лише раз на $433622d." },
    { en = "Brann summons his loyal gryphon companion to bombard nearby enemies for significant damage every $433428t2 sec for $433424d.", ua = "Бранн прикликає вірного супутника-грифона, щоб той бомбардував ворогів поблизу, завдаючи значної шкоди кожні $433428t2 сек. упродовж $433424d." },
    { en = "Each Penance bolt you fire reduces the cooldown of Ultimate Penitence by $s1 sec.", ua = "Кожен випущений тобою заряд Покути зменшує перезарядження Найвищої Покути на $s1 сек." },
    { en = "Bilescourge Bombers deal $s1% increased damage, and your spells now have a chance to summon a Bilescourge Bomber.", ua = "Бомбардувальники Жовчобичу завдають на $s1% більше шкоди, а твої закляття тепер мають шанс прикликати Бомбардувальника Жовчобичу." },
    { en = "Blade Flurry does not lose duration during Adrenaline Rush.\n\n\n\nAdrenaline Rush does not lose duration while Stealthed.", ua = "Шквал Клинків не втрачає тривалості під час Приливу Адреналіну.\n\n\n\nПрилив Адреналіну не втрачає тривалості під час непомітності." },
    { en = "After activating Aerial Halt, experience a brief moment of weightlessness as the effects of gravity are reduced for $s1 sec.", ua = "Після активації Повітряної Зупинки ти відчуваєш коротку мить невагомості, поки дія гравітації послаблена на $s1 сек." },
    { en = "Ground Skimming can now occur while affected by Thrill of the Skies.", ua = "Ковзання Землею тепер може спрацьовувати під дією Трепету Небес." },
    { en = "Summon Demonic Tyrant empowers $s1 additional Wild Imps and deals $s2% increased damage for each demon he empowers.", ua = "Прикликання Демонічного Тирана підсилює $s1 додаткових Диких Бісів і завдає на $s2% більше шкоди за кожного підсиленого демона." },
    { en = "Stormstrike, Ice Strike, and Lava Lash have a $h% chance to discharge electricity at your target, dealing $428078s1 Nature damage.", ua = "Штормовий Удар, Крижаний Удар і Лавовий Батіг мають $h% шанс розрядити електрику по твоїй цілі, завдаючи $428078s1 шкоди від Природи." },
    { en = "Blast all friendly targets affected by your Riptide within $r yards with a Primordial Wave, healing them for $375985s1.", ua = "Накриває всі дружні цілі під дією твого Відпливу в межах $r ярдів Первісною Хвилею, зцілюючи їх на $375985s1." },
    { en = "Teaches your primary Felguard the following ability:\n\n\n\n$@spellicon267964 $@spellname267964\n\n$@spelldesc267964", ua = "Навчає вашого основного стража Скверни наступної здібності:\n\n\n\n$@spellicon267964 $@spellname267964\n\n$@spelldesc267964" },
    { en = "Soul Strike deals $s1% increased damage and generates a Soul Shard.", ua = "Удар Душі завдає на $s1% більше шкоди і породжує Уламок Душі." },
    { en = "Sigil of Flame has ${$s3/-1000} sec reduced cooldown and $s1 additional $lcharge:charges;.\n\n\n\nYou have $s2% increased chance to parry attacks from enemies afflicted by your Sigil of Flame.", ua = "Печать полум'я має на ${$s3/-1000} сек. менше перезарядження та $s1 додатковий $lзаряд:заряди;.\n\n\n\nВи маєте на $s2% більший шанс парирувати атаки ворогів, уражених вашою Печаттю полум'я." },
    { en = "Casting Premonition of Solace invokes Clairvoyance, expanding your mind and opening up all possibilities of the future.\n\n\n\n$@spellicon440725 |cFFFFFFFF$@spellname440725|r\n\n$@spelldesc440725", ua = "Творіння Передчуття Розради прикликає Ясновидіння, розширюючи ваш розум і відкриваючи всі можливості майбутнього.\n\n\n\n$@spellicon440725 |cFFFFFFFF$@spellname440725|r\n\n$@spelldesc440725" },
    { en = "Attempt to perform a miracle with $M1 materials of your choosing. This technique may yield new discoveries but is highly destructive.", ua = "Спробуйте здійснити диво, використавши $M1 матеріали на ваш вибір. Ця техніка може принести нові відкриття, але надзвичайно руйнівна." },
    { en = "You heal for $s1% of all Shadow damage you deal.", ua = "Ви зцілюєтеся на $s1% усієї шкоди Тінню, яку завдаєте." },
    { en = "Each time Black Arrow deals damage, you have a small chance to manifest a Dark Hound that charges to your target and attacks nearby enemies for $442419d.", ua = "Щоразу, коли Чорна стріла завдає шкоди, ви маєте невеликий шанс проявити Темного хорта, який кидається до вашої цілі та атакує ворогів поблизу протягом $442419d." },
    { en = "Casting Essence spells extends all your active Threads of Fate by $s1 sec.", ua = "Творення заклять есенції продовжує всі ваші активні Нитки Долі на $s1 с." },
    { en = "After exiting combat, Brann builds a campfire that increases the Versatility of those nearby by $432573s1 and allows cooking.", ua = "Після виходу з бою Бранн розпалює багаття, що підвищує Універсальність тих, хто поблизу, на $432573s1 і дозволяє куховарити." },
    { en = "This talent has yet to be discovered!", ua = "Цей талант ще належить відкрити!" },
    { en = "During combat, Brann designates a player to guide his shot for $445598d before firing towards their location and dealing moderate Physical damage to the first enemy hit.", ua = "Під час бою Бранн призначає гравця, щоб той наводив його постріл протягом $445598d, а тоді стріляє в його напрямку, завдаючи помірної фізичної шкоди першому враженому ворогу." },
    { en = "Brann cures an infected player removing all Poison and Disease effects, or purges an enemy target removing 1 beneficial magic effect.", ua = "Бранн лікує заражену ціль-гравця, знімаючи всі ефекти отрути та хвороби, або очищає ворожу ціль, знімаючи 1 сприятливий магічний ефект." },
    { en = "Brann hurls a shield at all players, reducing their damage taken by $463154s1% and preventing loss of control effects for $463154d.", ua = "Бранн жбурляє щит на всіх гравців, зменшуючи отримувану ними шкоду на $463154s1% і запобігаючи ефектам втрати контролю протягом $463154d." },
    { en = "Brann will finish off wounded targets, executing enemies that have less than $435162s1% health.\n\n\n\nThe health threshold for this effect is reduced to $435162s2% for boss creatures.", ua = "Бранн добиватиме поранені цілі, страчуючи ворогів, у яких менше ніж $435162s1% здоров'я.\n\n\n\nПоріг здоров'я для цього ефекту знижується до $435162s2% для істот-босів." },
    { en = "Brann launches a volley of snacks at injured players, restoring a moderate amount of health over $437591d.", ua = "Бранн запускає залп харчів у поранених гравців, відновлюючи помірну кількість здоров'я протягом $437591d." },
    { en = "While Brann is low health, he will deflect all attacks and take $s5% less damage for $d, but will be unable to attack.", ua = "Поки в Бранна мало здоров'я, він відбиватиме всі атаки й отримуватиме на $s5% менше шкоди протягом $d, але не зможе атакувати." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20|a herbs gathered from Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20|a.", ua = "Обробляє $M1 трав якості |A:Professions-ChatIcon-Quality-Tier1:20:20|a, зібраних у Каз Алґарі, на 1 якості |A:Professions-ChatIcon-Quality-Tier2:20:20|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20|a herbs gathered from Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20|a.", ua = "Обробляє $M1 трав якості |A:Professions-ChatIcon-Quality-Tier2:20:20|a, зібраних у Каз Алґарі, на 1 якості |A:Professions-ChatIcon-Quality-Tier3:20:20|a." },
    { en = "Brann's spells and abilities have a chance to awaken the idol, shielding an injured player for $439237s1% of their missing health.", ua = "Закляття та здібності Бранна мають шанс пробудити ідола, огортаючи пораненого гравця щитом на $439237s1% його втраченого здоров'я." },
    { en = "When any player's health falls below $439837s1% health during combat, the idol awakens dealing moderate Physical damage to nearby enemies and taunting them for $441094d. Can only occur every $452727d.", ua = "Коли здоров'я будь-якого гравця в бою падає нижче $439837s1%, ідол пробуджується, завдаючи помірної фізичної шкоди ворогам поблизу й глузуючи з них протягом $441094d. Може статися лише кожні $452727d." },
    { en = "When any player uses a defensive ability with a cooldown of $439327s1 sec or longer, the idol activates and heals them for ${$439329s1/100}.2% of their maximum health every $439329t1 sec for $439329d.", ua = "Коли будь-який гравець використовує захисну здібність із перезарядженням $439327s1 сек або довше, ідол активується й зцілює його на ${$439329s1/100}.2% максимального здоров'я кожні $439329t1 сек протягом $439329d." },
    { en = "While out of combat, the party's movement speed is increased by $432994s1%. Upon entering combat, the party's haste is increased by $440951s1% for $440951d.", ua = "Поза боєм швидкість пересування групи збільшено на $432994s1%. При вступі в бій Поспіх групи збільшується на $440951s1% протягом $440951d." },
    { en = "When Brann uses $@spellname453812, there is a $439470s1% chance to unearth a powerful artifact that grants your party a powerful Boon.\n\n\n\n$@spellicon453812 $@spellname453812\n\n$@spelldesc453812", ua = "Коли Бранн використовує $@spellname453812, є $439470s1% шанс відкопати могутній артефакт, що дарує вашій групі потужне благословення.\n\n\n\n$@spellicon453812 $@spellname453812\n\n$@spelldesc453812" },
    { en = "Utilize your Algari botanical knowledge in combination with latent magic within the land, doubling the herbs you receive when gathering your next herb in Khaz Algar.", ua = "Поєднай свої алґарські знання з ботаніки з прихованою магією землі, подвоївши кількість трав, які ти отримаєш під час наступного збору трав у Каз Алґарі." },
    { en = "When you apply Reaper's Mark, the cooldown of Soul Reaper is reset, your next Soul Reaper costs no runes, and it explodes on the target regardless of their health.\n\n\n\nSoul Reaper damage is increased by $s1%.", ua = "Коли ти накладаєш Мітку Женця, перезарядження Женця Душ скидається, наступний Женець Душ не коштує рун і вибухає на цілі незалежно від її здоров'я.\n\n\n\nШкода Женця Душ збільшена на $s1%." },
    { en = "Soothing Mist now follows the target of your Enveloping Mist or Vivify and its channel time is increased by ${$s3/1000} sec.", ua = "Заспокійливий Туман тепер слідує за ціллю твого Огортаючого Туману або Оживлення, а час його підтримання збільшено на ${$s3/1000} сек." },
    { en = "Reduces the cooldown of Premonition by ${$s1/-1000} sec.", ua = "Зменшує перезарядження Передчуття на ${$s1/-1000} сек." },
    { en = "Reduces the cooldown of Power Word: Life by ${$s1/-1000} sec and allows it to be usable on targets below $s2% health.", ua = "Зменшує перезарядження Слова сили: Життя на ${$s1/-1000} сек і дозволяє застосовувати його на цілях зі здоров'ям нижче $s2%." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a rare hides and scales gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M1 рідкісних шкур і луски якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібраних із істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a rare hides and scales gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M1 рідкісних шкур і луски якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібраних із істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a leather gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M1 шкіри якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібраної з істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a leather gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M1 шкіри якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібраної з істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a chitin gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M1 хітину якості |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a, зібраного з істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M1 Quality |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a chitin gathered from the creatures of Khaz Algar to 1 Quality |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M1 хітину якості |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a, зібраного з істот Каз Алґару, на 1 якості |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Use your expert knowledge of the outdoors to find a suitable stone to sharpen your knife. This sharpening process will guarantee you receive a hide or carapace from your next Algari skinning attempt. The whole process is physically taxing, and cannot be undertaken often.", ua = "Скористайся своїми глибокими знаннями про природу, щоб знайти придатний камінь для гостріння ножа. Це гостріння гарантує, що ти отримаєш шкуру або панцир при наступній спробі алґарського білування. Увесь процес фізично виснажливий, тож його не можна повторювати надто часто." },
    { en = "If the target is below $434765s1% health, Reaper's Mark immediately explodes as if you had at least $434765s2 stacks and its cooldown is reduced by $s2 sec.", ua = "Якщо в цілі менше ніж $434765s1% здоров'я, «Мітка Женця» негайно вибухає, ніби у вас щонайменше $434765s2 стаків, а її перезарядження скорочується на $s2 сек." },
    { en = "Refines $M2 Bismuth Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Bismuth Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 руди вісмуту |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 руди вісмуту |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M2 Bismuth Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Bismuth Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 руди вісмуту |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 руди вісмуту |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M2 Aqirite Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Aqirite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 руди акіриту |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 руди акіриту |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M2 Aqirite Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Aqirite Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 руди акіриту |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 руди акіриту |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Refines $M2 Ironclaw Ore |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a to $M1 Ironclaw Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a.", ua = "Переробляє $M2 руди залізокігтя |A:Professions-ChatIcon-Quality-Tier1:20:20:0:3|a на $M1 руди залізокігтя |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a." },
    { en = "Refines $M2 Ironclaw Ore |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a to $M1 Ironclaw Ore |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a.", ua = "Переробляє $M2 руди залізокігтя |A:Professions-ChatIcon-Quality-Tier2:20:20:0:3|a на $M1 руди залізокігтя |A:Professions-ChatIcon-Quality-Tier3:20:20:0:3|a." },
    { en = "Prepare to undertake the process of butchery. While active, your next Khaz Algar Skinning attempt will guarantee meat usable in cooking.", ua = "Приготуйтеся до оброблення туш. Поки ефект активний, ваша наступна спроба білування в Каз Алґарі гарантовано дасть м'ясо, придатне для куховарства." },
    { en = "Casting Jadefire Stomp increases the $?c2[damage or healing of your next Rising Sun Kick by $442850s1% or Vivify by $442850s2%]?c3[damage of your next Rising Sun Kick by $442850s1%][].", ua = "Творіння Тупоту Нефритового Вогню підвищує $?c2[шкоду або зцілення вашого наступного Удару Висхідного Сонця на $442850s1% чи Оживлення на $442850s2%]?c3[шкоду вашого наступного Удару Висхідного Сонця на $442850s1%][]." },
    { en = "Transcribe $M1 of the same Khaz Algar Darkmoon Card into a card of Ascension.", ua = "Переписує $M1 однакових Карт Темного Місяця з Каз Алґару на карту Піднесення." },
    { en = "Transcribe $M1 of the same Khaz Algar Darkmoon Card into a card of Vivacity.", ua = "Переписує $M1 однакових Карт Темного Місяця з Каз Алґару на карту Жвавості." },
    { en = "Transcribe $M1 of the same Khaz Algar Darkmoon Card into a card of Symbiosis.", ua = "Переписує $M1 однакових Карт Темного Місяця з Каз Алґару на карту Симбіозу." },
    { en = "Transcribe $M1 of the same Khaz Algar Darkmoon Card into a card of Radiance.", ua = "Переписує $M1 однакових Карт Темного Місяця з Каз Алґару на карту Сяйва." },
    { en = "Each time you conjure $?c1[an Arcane][a Frost] Splinter, increase the damage of your next $?c1[Supernova by $444981s1%][Ice Nova by $444976s1%].\n\n\n\nStacks up to $?c1[$444981u][$444976u] times.", ua = "Щоразу, коли ви прикликаєте $?c1[арканну][крижану] скалку, шкода вашої наступної $?c1[Наднової зростає на $444981s1%][Крижаної нови зростає на $444976s1%].\n\n\n\nНакопичується до $?c1[$444981u][$444976u] разів." },
    { en = "Brann's spells and abilities have a chance to weaken enemies, increasing the chance to critically strike them by $446839s1% for $446839d.", ua = "Закляття й здібності Бранна мають шанс послабити ворогів, збільшуючи шанс завдати їм критичного удару на $446839s1% на $446839d." },
    { en = "|cnNORMAL_FONT_COLOR:Nerubian Novelties - Tertiary Trivialities|R\n\n\n\nPermanently enchants bracers with ancient magic that chants with power, granting $ec1 Speed. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Нерубські дивовижі — третинні дрібнички|R\n\n\n\nНазавжди зачаровує наручі прадавньою магією, що співає силою, даруючи $ec1 Швидкості. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Earthen Enhancements - Bolstered Breastplates|R\n\n\n\nPermanently enchants a chestpiece with Earthen rune magic to increase your $pri by $ec1. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Земляні вдосконалення — зміцнені нагрудники|R\n\n\n\nНазавжди зачаровує нагрудник рунічною магією земляних, підвищуючи вашу $pri на $ec1. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Earthen Enhancements - Wondrous Weapons|R\n\n\n\nPermanently enchants a weapon with the Authority of Storms. Your abilities have a chance to imbue you, causing further abilities to sometimes unleash lightning which deals ${$<rolemult>*$ec1s1} Nature damage split amongst all enemies hit. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Земляні вдосконалення — дивовижна зброя|R\n\n\n\nНазавжди зачаровує зброю Владою Бур. Ваші здібності мають шанс наситити вас, через що подальші здібності іноді вивільняють блискавку, яка завдає ${$<rolemult>*$ec1s1} шкоди Природою, розподіленої між усіма враженими ворогами. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Earthen Enhancements - Terrific Tools|R\n\n\n\nPermanently enchants a crafting tool to increase your Ingenuity by $ec1. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Земляні вдосконалення — чудові інструменти|R\n\n\n\nНазавжди зачаровує ремісничий інструмент, підвищуючи вашу Винахідливість на $ec1. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Nerubian Novelties - Cursed Chants|R\n\n\n\nPermanently infuses a ring with a cursed chant, sapping $ec1s1 of your Versatility while granting $ec1s2 Haste. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Нерубські дивовижі — прокляті співи|R\n\n\n\nНазавжди наповнює перстень проклятим співом, що виснажує $ec1s1 вашої Універсальності, натомість даруючи $ec1s2 Поспіху. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Arathor Alterations - Accentuated Accessories|R\n\n\n\nPermanently enchants a pair of boots with a defender's tenacity, increasing Stamina by $ec1. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Араторські переробки — вишукані аксесуари|R\n\n\n\nНазавжди зачаровує пару чобіт завзятістю захисника, підвищуючи Витривалість на $ec1. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "|cnNORMAL_FONT_COLOR:Arathor Alterations - Fortified Flames|R\n\n\n\nPermanently enchants a weapon with the Authority of Fiery Resolve. Healing allies has a chance to call upon that authority, radiating a wave of soothing fire that heals yourself and your 4 closest allies for $ec1s1. Cannot be applied to items lower than level $ecim.", ua = "|cnNORMAL_FONT_COLOR:Араторські переробки — укріплене полум'я|R\n\n\n\nНазавжди зачаровує зброю Владою Вогняної Рішучості. Зцілення союзників має шанс прикликати цю владу, випромінюючи хвилю заспокійливого вогню, що зцілює вас і 4 найближчих союзників на $ec1s1. Не можна застосувати до предметів нижче рівня $ecim." },
    { en = "Shatter a magical essence of Khaz Algar to utilize the power within for your Enchanting.\n\n\n\nGain the following effect when shattering:\n\n\n\n$@spellicon445798 $@spellname445798:\n\nEmpowered by a shattered magical essence of Khaz Algar, increasing Resourcefulness, Ingenuity, and Multicraft while practicing Khaz Algar Enchanting.", ua = "Розбийте магічну есенцію Каз Алґара, щоб використати силу всередині для вашого Накладання чарів.\n\n\n\nОтримайте наступний ефект під час розбивання:\n\n\n\n$@spellicon445798 $@spellname445798:\n\nПідсилено розбитою магічною есенцією Каз Алґара, що підвищує Кмітливість, Винахідливість та Множинне виготовлення під час Накладання чарів Каз Алґара." },
    { en = "Upon entering combat, players gain either $@spellname456648 or $@spellname456651 until combat ends.\n\n\n\n$@spellicon456648 $@spellname456648\n\n$@spelldesc456648\n\n\n\n$@spellicon456651 $@spellname456651\n\n$@spelldesc456651", ua = "Зі вступом у бій гравці отримують або $@spellname456648, або $@spellname456651 до завершення бою.\n\n\n\n$@spellicon456648 $@spellname456648\n\n$@spelldesc456648\n\n\n\n$@spellicon456651 $@spellname456651\n\n$@spelldesc456651" },
    { en = "This schematic can only be crafted once a day.", ua = "Цю схему можна виготовити лише раз на день." },
    { en = "$?pc125224[Crafting this may inspire you with the knowledge of another profession's Algari Treatise.][]", ua = "$?pc125224[Виготовлення цього може надихнути вас знанням Алґарійського трактату іншої професії.][]" },
    { en = "A member of your group can ride along with you on specific mounts.\n\n\n\nThis option has no cost.", ua = "Учасник вашої групи може подорожувати поряд з вами на певних їздових тваринах.\n\n\n\nЦя опція безкоштовна." },
    { en = "Disallow Ride Along on specific mounts.\n\n\n\nThis option has no cost.", ua = "Заборонити «Спільну їзду» на певних їздових тваринах.\n\n\n\nЦя опція безкоштовна." },
    { en = "Choose Whirling Surge instead of Lightning Rush.\n\n\n\nThis option has no cost.", ua = "Обрати «Вихровий сплеск» замість «Блискавичного ривка».\n\n\n\nЦя опція безкоштовна." },
    { en = "Choose Lightning Rush instead of Whirling Surge.\n\n\n\nThis option has no cost.", ua = "Обрати «Блискавичний ривок» замість «Вихрового сплеску».\n\n\n\nЦя опція безкоштовна." },
    { en = "|cnGREEN_FONT_COLOR:Season 1|r\n\nBrann's combat mastery grants him $s1% increased healing done by his spells and abilities.$?pc125283[][\n\n\n\n|cnWHITE_FONT_COLOR:The rank of this effect is increased further with each companion level.|r]", ua = "|cnGREEN_FONT_COLOR:Season 1|r\n\nБойова майстерність Бранна дає йому $s1% більше зцілення від його заклять і здібностей.$?pc125283[][\n\n\n\n|cnWHITE_FONT_COLOR:Ранг цього ефекту додатково зростає з кожним рівнем супутника.|r]" },
    { en = "|cnGREEN_FONT_COLOR:Season 1|r\n\nBrann's combat mastery grants him $s1% increased damage done by his spells and abilities.$?pc125283[][\n\n\n\n|cnWHITE_FONT_COLOR:The rank of this effect is increased further with each companion level.|r]", ua = "|cnGREEN_FONT_COLOR:Season 1|r\n\nБойова майстерність Бранна дає йому $s1% більше шкоди від його заклять і здібностей.$?pc125283[][\n\n\n\n|cnWHITE_FONT_COLOR:Ранг цього ефекту додатково зростає з кожним рівнем супутника.|r]" },
    { en = "Renewing Mist increases its target's healing received from you by $457013s1% for the first $457013d of its duration, but cannot jump to a new target during this time.", ua = "«Оновлювальний туман» збільшує зцілення, яке ціль отримує від тебе, на $457013s1% протягом перших $457013d його дії, але впродовж цього часу не може перескочити на нову ціль." },
    { en = "Brann hurls steel traps that snaps shut on the first enemy that approaches, wounding them for moderate Physical damage instantly and additional Bleed damage over time.", ua = "Бранн жбурляє сталеві пастки, що захлопуються на першому ворогові, який наближається, миттєво завдаючи помірної фізичної шкоди та додаткової шкоди від кровотечі з часом." },
    { en = "Generating a Spellfire Sphere while your Phoenix is active causes it to cast an exceptional spell.\n\n\n\nMana Cascade can now stack up to $s2 times.", ua = "Створення Сфери чаровогню, поки активний твій Фенікс, змушує його сотворити виняткове закляття.\n\n\n\n«Каскад мани» тепер накопичується до $s2 разів." },
    { en = "Coalesce Mercurial Transmutagen by combining Ominous and Volatile transmutagens with power from your Philosopher's Stone.", ua = "Створити Ртутний трансмутаген, поєднавши Зловісний і Нестабільний трансмутагени з силою твого Філософського каменя." },
    { en = "Coalesce Ominous Transmutagen by combining Mercurial and Volatile transmutagens with power from your Philosopher's Stone.", ua = "Створити Зловісний трансмутаген, поєднавши Ртутний і Нестабільний трансмутагени з силою твого Філософського каменя." },
    { en = "Coalesce Volatile Transmutagen by combining Ominous and Mercurial transmutagens with power from your Philosopher's Stone.", ua = "Створити Нестабільний трансмутаген, поєднавши Зловісний і Ртутний трансмутагени з силою твого Філософського каменя." },
    { en = "Brann temporarily enchants a nearby player's weapon for $451302d, causing their spells and abilities to deal additional damage as fire, provided they remain in combat.\n\n\n\nWhen the enchantment is removed, the effect jumps to a nearby ally.", ua = "Бранн тимчасово зачаровує зброю сусіднього гравця на $451302d, змушуючи його закляття та здібності завдавати додаткової шкоди у вигляді вогню, поки він лишається в бою.\n\n\n\nКоли чари знімаються, ефект перескакує на сусіднього союзника." },
    { en = "Convert Gleaming Transmutagen into an assortment of random materials.", ua = "Перетворити Осяйний трансмутаген на добірку випадкових матеріалів." },
    { en = "When your $?s461264[Nether Flux][Touch of the Magi] detonates, it increases the damage all affected targets take from you by $454004s1% for $454004d.", ua = "Коли ваш $?s461264[Нижній Потік][Дотик Магів] детонує, він збільшує шкоду, яку всі уражені цілі отримують від вас, на $454004s1% протягом $454004d." },
    { en = "Meteor and Flamestrike deal $s1% increased damage.", ua = "«Метеор» і «Вогняний удар» завдають на $s1% більше шкоди." },
    { en = "While Icy Veins is active, damaging an enemy with Frostbolt increases spell damage by $454371s1%. Stacks up to $454371u times.", ua = "Поки активні «Крижані жили», завдавання шкоди ворогові «Крижаною стрілою» збільшує шкоду заклять на $454371s1%. Накопичується до $454371u разів." },
    { en = "When Sentinel starts dealing damage, the target is snared by $450845s1% for $450845d.", ua = "Коли «Вартовий» починає завдавати шкоди, ціль сповільнюється на $450845s1% на $450845d." },
    { en = "During $?c2[Trueshot][Primal Frenzy], all abilities are guaranteed to apply Sentinel.", ua = "Під час $?c2[Влучного пострілу][Первісного шалу] усі здібності гарантовано накладають Вартового." },
    { en = "Consuming Umbral Embrace increases the damage of your Moonfire, Sunfire, Stellar Flare, Shooting Stars, and Starfall by $450419s1% for $450419d.", ua = "Споживання «Тіньових обіймів» збільшує шкоду твоїх «Місячного вогню», «Сонячного вогню», «Зоряного спалаху», «Падучих зірок» і «Зорепаду» на $450419s1% на $450419d." },
    { en = "Consuming Hot Streak has a $s4% chance to grant you Lit Fuse.\n\n\n\n$@spellicon450716 $@spellname450716:\n\nYour next Fire Blast turns up to $s2 nearby $Ltarget:targets; into a Living Bomb that explodes after $217694d, dealing $44461s2 Fire damage to the target and reduced damage to all other enemies within $44461A2 yds.\n\n\n\nUp to $s3 enemies hit by this explosion also become a Living Bomb, but this effect cannot spread further.", ua = "Витрачання Гарячої Смуги має $s4% шанс дати вам Запалений Ґніт.\n\n\n\n$@spellicon450716 $@spellname450716:\n\nВаш наступний Вогняний Вибух перетворює до $s2 найближчих $Ltarget:цілей; на Живу Бомбу, що вибухає через $217694d, завдаючи $44461s2 шкоди вогнем цілі та зменшеної шкоди всім іншим ворогам у радіусі $44461A2 ярдів.\n\n\n\nДо $s3 ворогів, уражених цим вибухом, також стають Живою Бомбою, але цей ефект не може поширюватися далі." },
    { en = "Flamestrike damage increased by $s1% and it now has a ${$s2/1000} sec cooldown.", ua = "Шкода від «Полум'яного удару» збільшена на $s1%, і тепер він має перезарядження ${$s2/1000} сек." },
    { en = "If Phoenix Flames only hits $s1 target, it deals $s2% increased damage and applies Ignite at $s3% effectiveness.", ua = "Якщо «Феніксове полум'я» влучає лише в $s1 ціль, воно завдає на $s2% більше шкоди й накладає «Займання» з $s3% ефективністю." },
    { en = "The stormrook unleashes lightning bolts capable of seeking targets.", ua = "Штормовий грак випускає блискавки, здатні наздоганяти цілі." },
    { en = "Casting Phoenix Flames causes your next Flamestrike to have its critical strike chance increased by $453329s1% and critical strike damage increased by $453329s2%.\n\n\n\nStacks up to $453329u times.", ua = "Творіння «Феніксового полум'я» збільшує шанс критичного удару твого наступного «Полум'яного удару» на $453329s1%, а критичну шкоду — на $453329s2%.\n\n\n\nСтакається до $453329u разів." },
    { en = "Lit Fuse now turns up to $s1 targets into Living Bombs.\n\n\n\nLiving Bombs can now spread to $s2 enemies.", ua = "«Запалений ґніт» тепер перетворює до $s1 цілей на «Живі бомби».\n\n\n\n«Живі бомби» тепер можуть поширюватися на $s2 ворогів." },
    { en = "Casting Combustion grants Lit Fuse and Living Bomb's damage is increased by $s2% while under the effects of Combustion.$?a450716[\n\n\n\nYour chance of gaining Lit Fuse is increased by $s1% while under the effects of Combustion.][]", ua = "Прочитання Спалаху дає Запалений Ґніт, а шкода Живої Бомби збільшується на $s2% під дією Спалаху.$?a450716[\n\n\n\nВаш шанс отримати Запалений Ґніт збільшується на $s1% під дією Спалаху.][]" },
    { en = "Your chance of gaining Lit Fuse when consuming Hot Streak is increased by $s1%.\n\n\n\nLiving Bomb damage increased by $s2%.", ua = "Твій шанс отримати «Запалений ґніт» під час використання «Гарячої серії» збільшено на $s1%.\n\n\n\nШкода від «Живої бомби» збільшена на $s2%." },
    { en = "The cast time of Arcane Blast is reduced by ${$s1*-1}%.", ua = "Час прочитання «Арканного вибуху» скорочено на ${$s1*-1}%." },
    { en = "Nether Precision damage bonus increased by $s1%.", ua = "Бонус шкоди від «Точності Нижнього Світу» збільшено на $s1%." },
    { en = "Consuming Clearcasting has a $s1% chance to make your next Arcane Blast echo, repeating its damage at $s2% effectiveness to the primary target and up to $s3 nearby enemies.\n\n\n\nCasting Touch of the Magi grants Leydrinker.", ua = "Використання «Ясного творіння» має $s1% шансу викликати відлуння твого наступного «Арканного вибуху», повторюючи його шкоду з $s2% ефективністю по основній цілі та до $s3 ворогів поблизу.\n\n\n\nТворіння «Дотику магів» дарує «Пиття лею»." },
    { en = "When you gain a stack of Arcane Salvo, you have a $s1% chance to gain another stack of Arcane Salvo.\n\n\n\nThis effect can trigger off of itself up to $s2 times.", ua = "Коли ти отримуєш стак «Арканного залпу», ти маєш $s1% шансу отримати ще один стак «Арканного залпу».\n\n\n\nЦей ефект може спрацьовувати від самого себе до $s2 разів." },
    { en = "$?s461264[Your Nether Flux now increase the damage of your next spell by $s2%][Your Touch of the Magi now accumulates an additional $s1% of the damage you deal].", ua = "$?s461264[Ваш Нижній Потік тепер збільшує шкоду вашого наступного закляття на $s2%][Ваш Дотик Магів тепер накопичує додаткові $s1% шкоди, яку ви завдаєте]." },
    { en = "Refreshing Agony with $s1 or less seconds remaining deals $453035s1 Shadow damage to its target and enemies within $453035a1 yards.\n\n\n\nDeals reduced damage beyond $s2 targets.", ua = "Оновлення «Агонії», коли лишається $s1 або менше секунд, завдає $453035s1 шкоди Тіні своїй цілі та ворогам у радіусі $453035a1 ярдів.\n\n\n\nЗавдає зменшеної шкоди понад $s2 цілей." },
    { en = "Malefic Rapture damage is increased by $s1% for each enemy it hits, up to $s2 enemies.", ua = "Шкода від «Лиховісного захвату» збільшується на $s1% за кожного враженого ворога, до $s2 ворогів." },
    { en = "Reduces the cast time of Unstable Affliction by $s1% and damage dealt by Unstable Affliction has a chance to generate a Soul Shard.", ua = "Скорочує час прочитання «Нестабільної недуги» на $s1%, а шкода від «Нестабільної недуги» має шанс створити «Уламок душі»." },
    { en = "Agony has 1.$m1 times the normal chance to generate a Soul Shard.", ua = "«Агонія» має в 1,$m1 раза більший за звичайний шанс створити «Уламок душі»." },
    { en = "When your direct damage spells hit an enemy $408673u times, gain $1219307u $lstack:stacks; of Born of Flame. \n\n\n\n$@spellicon1219307 $@spellname1219307\n\n$@spellaura1219307", ua = "Коли ваші закляття прямої шкоди уражають ворога $408673u разів, ви отримуєте $1219307u $lstack:стеків; Народженого з Полум'я. \n\n\n\n$@spellicon1219307 $@spellname1219307\n\n$@spellaura1219307" },
    { en = "Increases Hand of Gul'dan damage by $s1% and Demonbolt damage by $s2%.", ua = "Збільшує шкоду від «Руки Ґул'дана» на $s1% і шкоду від «Демонічної стріли» на $s2%." },
    { en = "When Doom expires, you have a chance to summon a Doomguard that casts $s1 Doom Bolts before departing. Each Doom Bolt deals $453616s1 Shadow damage.", ua = "Коли Прокляття завершується, ви маєте шанс призвати Вартового Прокляття, який випускає $s1 Болтів Прокляття, перш ніж зникнути. Кожен Болт Прокляття завдає $453616s1 шкоди Тінню." },
    { en = "Damaging a target with Arcane Missiles increases the damage they take from Arcane Missiles, Arcane Barrage, and Arcane Blast by ${$s1}.1% for $453599d. Multiple instances may overlap.", ua = "Завдання шкоди цілі за допомогою Арканних Снарядів збільшує шкоду, яку вона отримує від Арканних Снарядів, Арканного Шквалу та Арканного Вибуху, на ${$s1}.1% протягом $453599d. Кілька примірників можуть накладатися." },
    { en = "Every $458388u times you consume Clearcasting, gain Aether Attunement.\n\n\n\n$@spellicon453600$@spellname453600:\n\nYour next Arcane Missiles deals $453601s1% increased damage to your primary target and fires at up to ${$453601s2-1} nearby enemies dealing $453601s4% increased damage.", ua = "Щоразу, коли ви витрачаєте Ясне Чаклування $458388u разів, ви отримуєте Налаштування на Ефір.\n\n\n\n$@spellicon453600$@spellname453600:\n\nВаші наступні Арканні Снаряди завдають на $453601s1% більше шкоди вашій головній цілі та стріляють у до ${$453601s2-1} найближчих ворогів, завдаючи на $453601s4% більше шкоди." },
    { en = "Wicked Maw causes the target to take $s1% additional Shadow damage from your demons.", ua = "Лиха Паща змушує ціль отримувати на $s1% більше шкоди Тінню від ваших демонів." },
    { en = "Siphon the residual energy of the forge for later use. Igniting the forge grants a boon of Algari Blacksmithing stats according to your Everburning Forge specialization.", ua = "Висмоктуйте залишкову енергію кузні для подальшого використання. Розпалювання кузні дарує благо характеристик алґарського ковальства відповідно до вашої спеціалізації Вічнополум'яної Кузні." },
    { en = "Brann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.", ua = "Бранн використовує свої інструменти збирання, щоб допомогти гравцям знаходити додаткове золото, руду, трави, рибу, шкіри та скарби." },
    { en = "Your $?s461264[Nether Flux][Touch of the Magi] now also conjures a spark of potential for $450004d, causing the damage from your next Arcane Barrage, Arcane Blast, and Arcane Missiles to echo for $454016s1% of their damage.\n\n\n\nUpon receiving damage from all three spells, the spark explodes, dealing $453925s1 Arcane damage to all nearby enemies. Damage reduced beyond $s2 targets.", ua = "Ваш $?s461264[Нижній Потік][Дотик Магів] тепер також викликає іскру потенціалу на $450004d, змушуючи шкоду ваших наступних заклять Арканний Залп, Арканний Вибух і Арканні Снаряди відлунювати на $454016s1% їхньої шкоди.\n\n\n\nОтримавши шкоду від усіх трьох заклять, іскра вибухає, завдаючи $453925s1 арканної шкоди всім найближчим ворогам. Шкода зменшена понад $s2 цілей." },
    { en = "Increases Malefic Rapture damage by $s1% and reduces its cast time by $s2%.", ua = "Збільшує шкоду Лиховісного Захвату на $s1% і зменшує час його прочитання на $s2%." },
    { en = "Rising Sun Kick grants a stack of Elusive Brawler.", ua = "Удар Висхідного Сонця дарує заряд Невловимого Бійця." },
    { en = "Virulent Plague has a chance to abruptly flare up, dealing $s1% of the damage it dealt to target in the last $s4 sec.\n\n\n\nWhen this effect triggers, the duration of your active minions are increased by ${$s2/1000}.1 sec, up to ${$s3/1000}.1 sec.", ua = "Згубна Чума має шанс раптово спалахнути, завдаючи $s1% шкоди, яку вона завдала цілі за останні $s4 сек.\n\n\n\nКоли цей ефект спрацьовує, тривалість ваших активних прислужників збільшується на ${$s2/1000}.1 сек, до ${$s3/1000}.1 сек." },
    { en = "The idol draws upon unholy energy to prevent fatal damage on players, instead healing them for an amount equal to $455514s1% of their maximum health and turning them Undead.\n\n\n\nWhile Undead, they cannot be healed, lose $456699s1% of their maximum health every $455516t1 sec, and gain $455516s2% damage and healing done.", ua = "Ідол черпає нечестиву енергію, щоб запобігти смертельній шкоді для гравців, натомість зцілюючи їх на величину, що дорівнює $455514s1% їхнього максимального здоров'я, і перетворюючи їх на Нежить.\n\n\n\nБудучи Нежиттю, вони не можуть бути зцілені, втрачають $456699s1% свого максимального здоров'я кожні $455516t1 сек, а завдана ними шкода та зцілення збільшуються на $455516s2%." },
    { en = "Damage dealt by Grimoire: Felguard is increased by an additional $s1% and you gain a Demonic Core when Grimoire: Felguard ends.", ua = "Шкода, завдана Гримуаром: Сквернова Варта, збільшується додатково на $s1%, і ви отримуєте Демонічне Ядро, коли Гримуар: Сквернова Варта завершується." },
    { en = "Your Dreadstalkers deal $455611s1% increased damage while your Vilefiend is active.", ua = "Ваші Жахоскрадачі завдають на $455611s1% більше шкоди, поки активна ваша Лиха Нечисть." },
    { en = "Power Siphon increases the damage of Demonbolt by an additional $s2%.", ua = "Висмоктування Сили збільшує шкоду Демонічного Болта додатково на $s2%." },
    { en = "When Doom expires, you have a $s1% chance to generate a Demonic Core.", ua = "Коли Прокляття завершується, ви маєте $s1% шанс створити Демонічне Ядро." },
    { en = "Increases the damage of Doom by $s1% and Doom summons $s2 Wild Imp when it expires.", ua = "Збільшує шкоду Прокляття на $s1%, і Прокляття призиває $s2 Дикого Біса, коли завершується." },
    { en = "Brann's spell and abilities have a chance to create bursts of energy, warping the flow of time for all nearby units by $456666s1% for $456662d.\n\n\n\nCasting, movement, periodic effects, cooldowns, and attack speeds are affected while time warped.", ua = "Закляття та здібності Бранна мають шанс створити сплески енергії, викривляючи плин часу для всіх істот поблизу на $456666s1% протягом $456662d.\n\n\n\nПрочитання, пересування, періодичні ефекти, перезарядження та швидкість атаки зазнають впливу під час викривлення часу." },
    { en = "Randomly while in combat a bloodbeast will attach itself to Brann, periodically launching morsels of itself near players, granting $@spellname456688 upon walking through them.\n\n\n\n$@spellicon456688 $@spellname456688\n\n$@spelldesc456688", ua = "Випадково під час бою кровожерний звір прикріплюється до Бранна, періодично викидаючи шматки себе поблизу гравців, що дає $@spellname456688 при проходженні крізь них.\n\n\n\n$@spellicon456688 $@spellname456688\n\n$@spelldesc456688" },
    { en = "$?a421373[When $@spellname421373 is consumed, there is a chance for Brann to throw an additional potion.][When a |cnWHITE_FONT_COLOR:Steel Trap|r is activated, there is a chance for Brann to throw an additional trap.]", ua = "$?a421373[Коли $@spellname421373 витрачається, є шанс, що Бранн кине додаткове зілля.][Коли активується |cnWHITE_FONT_COLOR:Сталева Пастка|r, є шанс, що Бранн поставить додаткову пастку.]" },
    { en = "When Brann calls for it, jumping on him will cause him to hurl players into their enemies, knocking and dealing significant Physical damage split between them.", ua = "Коли Бранн покличе, стрибок на нього змусить його жбурнути гравців у ворогів, збиваючи їх з ніг і завдаючи значної фізичної шкоди, поділеної між ними." },
    { en = "Brann gains access to combat curios, allowing you to earn and use them to configure his combat behavior.", ua = "Бранн отримує доступ до бойових дивовиж, дозволяючи вам здобувати й використовувати їх, щоб налаштовувати його поведінку в бою." },
    { en = "Brann gains access to utility curios, allowing you to earn and use them to configure his combat behavior.", ua = "Бранн отримує доступ до допоміжних дивовиж, дозволяючи вам здобувати й використовувати їх, щоб налаштовувати його поведінку в бою." },
    { en = "Increases the critical strike chance of Shadowburn by $s3%.", ua = "Підвищує шанс критичного удару Тіньового опіку на $s3%." },
    { en = "When your direct damaging abilities deal a critical strike, they have a chance to reset the cooldown of Soul Fire and reduce the cast time of your next Soul Fire by $457555s1%.", ua = "Коли ваші здібності прямої шкоди завдають критичного удару, вони мають шанс скинути перезарядження Вогню душі та зменшити час прочитання вашого наступного Вогню душі на $457555s1%." },
    { en = "Periodic damage dealt by $?a445465[Wither][Immolate] has a $s1% chance to tear open a Dimensional Rift.", ua = "Періодична шкода від $?a445465[Всихання][Спопеління] має $s1% шанс розірвати Вимірний Розлом." },
    { en = "Dimensional Rift can now summon a powerful Flame Rift.", ua = "Вимірний розлом тепер може прикликати потужний Вогняний розлом." },
    { en = "While you have a Dimensional Rift open, all of your damage is increased by $s1%.", ua = "Поки у вас відкритий Вимірний розлом, уся ваша шкода збільшена на $s1%." },
    { en = "Bolts from Dimensional Rift now deal $s1% of damage dealt to nearby enemies as Fire damage.", ua = "Спалахи з Вимірного розлому тепер завдають $s1% завданої шкоди найближчим ворогам як вогняну шкоду." },
    { en = "Backdraft increases the damage of your next Chaos Bolt by $s1% and increases the critical strike chance of your next Incinerate or Soul Fire by $s2%.", ua = "Зворотна тяга збільшує шкоду вашого наступного Спалаху хаосу на $s1% та підвищує шанс критичного удару вашого наступного Спопеляння чи Вогню душі на $s2%." },
    { en = "Living Bomb explosions have a small chance to increase the damage of your next Pyroblast by $457729s1% or Flamestrike by $457729s2%.", ua = "Вибухи Живої бомби мають невеликий шанс збільшити шкоду вашого наступного Піровибуху на $457729s1% чи Вогняного удару на $457729s2%." },
    { en = "Malefic Rapture deals an additional $458131s1 Shadowflame damage to each target it affects.", ua = "Лиховісний захват завдає додатково $458131s1 шкоди тіньового полум'я кожній враженій цілі." },
    { en = "The stack count of Agony is increased by $s1 when applied by Vile Taint.\n\n\n\nEnemies damaged by Phantom Singularity take $458219s1% increased damage from you for its duration.", ua = "Кількість накопичень Агонії збільшується на $s1, коли її накладено Мерзенною скверною.\n\n\n\nВороги, що зазнали шкоди від Примарної сингулярності, отримують на $458219s1% більше шкоди від вас протягом її дії." },
    { en = "Casting Soul Rot grants $s2 applications of Malign Omen.\n\n\n\n$@spellicon458043 $@spellname458043\n\n$@spelldesc458043", ua = "Прочитання Гнилі Душі дає $s2 накладень Лиховісного Знамення.\n\n\n\n$@spellicon458043 $@spellname458043\n\n$@spelldesc458043" },
