    { en = "Combine 20 Raw Crab Meat into a Bundle of Groceries.", ua = "Поєднай 20 Сирого Крабового М'яса у В'язку Харчів." },
    { en = "Combine 20 Wildfowl Breast into a Bundle of Groceries.", ua = "Поєднай 20 Грудок Дикої Птиці у В'язку Харчів." },
