    { en = "Combine 100 Scallions into a Bundle of Groceries.", ua = "Поєднай 100 Зеленої Цибулі у В'язку Харчів." },
    { en = "Combine 100 Red Blossom Leek into a Bundle of Groceries.", ua = "Поєднай 100 Червоноцвітої Цибулі-Порею у В'язку Харчів." },
    { en = "Combine 20 Ginseng into a Bundle of Groceries.", ua = "Поєднай 20 Женьшеню у В'язку Харчів." },
    { en = "Combine 100 Witchberries into a Bundle of Groceries.", ua = "Поєднай 100 Відьмоягід у В'язку Харчів." },
    { en = "Combine 100 Jade Squash into a Bundle of Groceries.", ua = "Поєднай 100 Нефритових Гарбузів у В'язку Харчів." },
    { en = "Combine 100 Striped Melon into a Bundle of Groceries.", ua = "Поєднай 100 Смугастих Динь у В'язку Харчів." },
    { en = "Combine 100 Pink Turnip into a Bundle of Groceries.", ua = "Поєднай 100 Рожевої Ріпи у В'язку Харчів." },
    { en = "Combine 100 White Turnip into a Bundle of Groceries.", ua = "Поєднай 100 Білої Ріпи у В'язку Харчів." },
    { en = "Combine 20 Rice into a Bundle of Groceries.", ua = "Поєднай 20 Рису у В'язку Харчів." },
    { en = "Combine 20 100 Year Soy Sauce into a Bundle of Groceries.", ua = "Поєднай 20 Столітнього Соєвого Соусу у В'язку Харчів." },
    { en = "Combine 20 Instant Noodles into a Bundle of Groceries.", ua = "Поєднай 20 Локшини Швидкого Приготування у В'язку Харчів." },
    { en = "Combine 20 Jade Lungfish into a Bundle of Groceries.", ua = "Поєднай 20 Нефритових Дводишних Риб у В'язку Харчів." },
    { en = "Combine 20 Giant Mantis Shrimp into a Bundle of Groceries.", ua = "Поєднай 20 Велетенських Креветок-Богомолів у В'язку Харчів." },
    { en = "Combine 20 Emperor Salmon into a Bundle of Groceries.", ua = "Поєднай 20 Імператорських Лососів у В'язку Харчів." },
    { en = "Combine 20 Redbelly Mandarin into a Bundle of Groceries.", ua = "Поєднай 20 Червоночеревих Мандаринів у В'язку Харчів." },
    { en = "Combine 20 Tiger Gourami into a Bundle of Groceries.", ua = "Поєднай 20 Тигрових Гурамі у В'язку Харчів." },
    { en = "Combine 20 Jewel Danio into a Bundle of Groceries.", ua = "Поєднай 20 Самоцвітних Даніо у В'язку Харчів." },
    { en = "Combine 20 Reef Octopus into a Bundle of Groceries.", ua = "Поєднай 20 Рифових Восьминогів у В'язку Харчів." },
    { en = "Combine 20 Krasarang Paddlefish into a Bundle of Groceries.", ua = "Поєднай 20 Красарангських Веслоносів у В'язку Харчів." },
    { en = "Combine 60 Golden Carp into a Bundle of Groceries.", ua = "Поєднай 60 Золотих Коропів у В'язку Харчів." },
    { en = "Combine 20 Raw Crocolisk Belly into a Bundle of Groceries.", ua = "Поєднай 20 Сирих Черев Кроколіска у В'язку Харчів." },
    { en = "Combine 20 Sirloin Steak into a Bundle of Groceries.", ua = "Поєднай 20 Стейків з Філейної Частини у В'язку Харчів." },
    { en = "Combine 20 Spinefish into a Bundle of Groceries.", ua = "Поєднай 20 Колючкорибів у В'язку Харчів." },
    { en = "Combine 20 Viseclaw Meat into a Bundle of Groceries.", ua = "Поєднай 20 М'яса Лещокляпа у В'язку Харчів." },
    { en = "Combine 20 Needle Mushrooms into a Bundle of Groceries.", ua = "Поєднай 20 Голчастих Грибів у В'язку Харчів." },
    { en = "Combine 20 Silkworm Pupa into a Bundle of Groceries.", ua = "Поєднай 20 Лялечок Шовкопряда у В'язку Харчів." },
    { en = "Combine 20 Red Beans into a Bundle of Groceries.", ua = "Поєднай 20 Червоної Квасолі у В'язку Харчів." },
    { en = "Combine 20 Farm Egg into a Bundle of Groceries.", ua = "Поєднай 20 Фермерських Яєць у В'язку Харчів." },
    { en = "Create a droplet of water at the target location.", ua = "Створює краплю води в обраному місці." },
    { en = "Create many tiny vibrations, causing nearby earth to move and shake, inflicting Physical damage to all nearby enemies.", ua = "Створює безліч дрібних вібрацій, змушуючи землю поблизу рухатися й тремтіти, завдаючи фізичної шкоди всім ворогам поруч." },
    { en = "Combine ten Motes of Harmony into a Spirit of Harmony.", ua = "Поєднай десять Часток Гармонії у Дух Гармонії." },
    { en = "Permanently attach a living steel belt buckle onto a belt, adding a socket to the belt.\n\n\n\nAttaching the belt buckle causes the item to become soulbound. Cannot be applied to items higher than level $ecix.", ua = "Назавжди прикріплює пряжку з живої сталі до пояса, додаючи йому гніздо.\n\n\n\nПрикріплення пряжки робить предмет прив'язаним до душі. Не можна застосувати до предметів, вищих за рівень $ecix." },
    { en = "Combine the Clamshells of Akkalou, Akkalar, Damlak, Kishak, Clamstok, and Odd'nirok to create a Clamshell Band.", ua = "Поєднай Мушлі Аккалоу, Аккалара, Дамлака, Кішака, Кламстока й Одд'нірока, щоб створити Перстень із Мушлі." },
    { en = "Combine ten Sparkling Shards into a Serpent's Eye.", ua = "Поєднай десять Іскристих Скалок у Зміїне Око." },
    { en = "Combine with a Healthstone to bind the tome to yourself.", ua = "Поєднай з Каменем Здоров'я, щоб прив'язати фоліант до себе." },
    { en = "Apply the Blasting Cap to a Demolisher, detonating and destroying it.", ua = "Застосуй Підривний Капсуль на Руйнівнику, підриваючи та знищуючи його." },
    { en = "Combine the Kor'kron Helmet, Kor'kron Armor, and Kor'kron Boots into a Kor'kron Disguise.", ua = "Поєднай Шолом Кор'кронів, Обладунок Кор'кронів і Чоботи Кор'кронів у Маскування Кор'кронів." },
    { en = "Permanently enchant a cloak to increase PvP Power by $ec1. Cannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи Силу PvP на $ec1. Не можна застосувати до предметів, вищих за рівень $ecix." },
    { en = "Permanently enchants a weapon to increase your $pri by $ec1 and reduces the duration of Disarm effects by $43588s1%. Disarm duration reduction does not stack with other similar effects. Cannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує зброю, збільшуючи вашу $pri на $ec1 та зменшуючи тривалість ефектів Роззброєння на $43588s1%. Це зменшення тривалості не сумується з іншими подібними ефектами. Не можна застосувати до предметів, вищих за рівень $ecix." },
    { en = "Create a pool of dreadful poison.", ua = "Створює калюжу жахливої отрути." },
    { en = "Combine ten nuggets into ore.", ua = "Поєднай десять самородків у руду." },
    { en = "Combine ten fragments into Kyparite.", ua = "Поєднай десять фрагментів у Кіпарит." },
    { en = "Combine ten Torn Green Leaves to create a Green Tea Leaf.", ua = "Поєднай десять Подертих Зелених Листків, щоб отримати Листок Зеленого Чаю." },
    { en = "Combine ten Rain Poppy Petals to create a Rain Poppy.", ua = "Поєднай десять Пелюсток Дощового Маку, щоб отримати Дощовий Мак." },
    { en = "Combine ten Silkweed Stems to create a Silkweed.", ua = "Поєднай десять Стебел Шовкотрави, щоб отримати Шовкотраву." },
    { en = "Combine ten Snow Lily Petals to create a Snow Lily.", ua = "Поєднай десять Пелюсток Сніжної Лілії, щоб отримати Сніжну Лілію." },
    { en = "Combine ten Fool's Cap Spores to create a Fool's Cap.", ua = "Поєднай десять Спор Блазнівського Ковпака, щоб отримати Блазнівський Ковпак." },
    { en = "Combine ten Desecrated Herb Pods to create a Desecrated Herb.", ua = "Поєднай десять Стручків Оскверненої Трави, щоб отримати Осквернену Траву." },
    { en = "Combine with a Radical Mojo to create an item useful for your Loot Specialization ($@lootspec).", ua = "Поєднай з Радикальним Моджо, щоб створити предмет, корисний для твоєї спеціалізації здобичі ($@lootspec)." },
    { en = "Combine with a Radical Mojo to create an item useful for your loot specialization ($@lootspec).", ua = "Поєднай з Радикальним Моджо, щоб створити предмет, корисний для твоєї спеціалізації здобичі ($@lootspec)." },
    { en = "Permanently enchants a melee weapon to sometimes increase your Intellect by $ec1 when healing or dealing damage with spells.  If less than 25% of your mana remains when the effect is triggered, your Versatility will also increase by $s2. Cannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує ближню зброю, що інколи збільшує ваш Інтелект на $ec1, коли ви зцілюєте або завдаєте шкоди закляттями. Якщо в момент спрацювання ефекту у вас залишається менше ніж 25% мани, ваша Універсальність також зросте на $s2. Не можна застосувати до предметів, вищих за рівень $ecix." },
    { en = "Create a pool of Worm Bile that lasts for $d and does Nature damage to all enemies who enter it.", ua = "Створює калюжу Черв'ячої Жовчі, що триває $d і завдає шкоди Природи всім ворогам, які до неї заходять." },
    { en = "Permanently enchant gloves to increase Fishing skill by $ec1. Cannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує рукавиці, збільшуючи навичку Рибальства на $ec1. Не можна застосувати до предметів, вищих за рівень $ecix." },
    { en = "Create a soulbound item appropriate for your loot specialization ($@lootspec).", ua = "Створює прив'язаний до душі предмет, що відповідає твоїй спеціалізації здобичі ($@lootspec)." },
    { en = "Create a soulbound item appropriate for your Loot Specialization ($@lootspec).", ua = "Створює прив'язаний до душі предмет, що відповідає твоїй спеціалізації здобичі ($@lootspec)." },
    { en = "Prepare a bowl of Noodle Soup. This simple soup is a great bargain for the budget conscious student.", ua = "Приготуй миску Локшинного Супу. Цей простий суп — чудова вигода для студента з обмеженим бюджетом." },
    { en = "Prepare a bowl of Dragon's Nest Noodle Soup. The subtleties of the blend of various vegetables is well appreciated by merchants and shopkeepers.", ua = "Приготуй миску Локшинного Супу «Драконове Гніздо». Тонкощі суміші різноманітних овочів дуже до вподоби торговцям і крамарям." },
    { en = "Prepare a bowl of Pandaren Treasures Noodle Soup. This hearty soup has all the nutrients and flavors necessary to restore both the mind and body after a hard day's work.", ua = "Приготуй миску Локшинного Супу «Скарби Пандарії». Цей ситний суп має всі поживні речовини та смаки, потрібні, щоб відновити і розум, і тіло після важкого трудового дня." },
    { en = "Combine the soul shards at the forge in Gul'var to create Gul'dan's Soul Trap.", ua = "Поєднай уламки душ у кузні в Ґул'варі, щоб створити Пастку для Душ Ґул'дана." },
    { en = "Create a fissure in the earth at the target location. After 3 seconds, a pillare of lava erupts from the fissure, dealing fire damage.", ua = "Створює розлам у землі в обраному місці. За 3 секунди з розлому вивергається стовп лави, завдаючи вогняної шкоди." },
    { en = "Create a soulbound item appropriate for a $@class.", ua = "Створює прив'язаний до душі предмет, що відповідає класу $@class." },
    { en = "Create a soulbound item appropriate for a $@classspec.", ua = "Створює прив'язаний до душі предмет, що відповідає спеціалізації $@classspec." },
    { en = "Eat the herb, restoring $s1 health every $t1 sec. for $d.", ua = "З'їж траву, відновлюючи $s1 здоров'я кожні $t1 сек. протягом $d." },
    { en = "Apply a Shadowmoon orc disguise. Shadowmoon orcs at Shaz'gul become friendly.\n\n\n\nOnly usable in Twilight Glade or Shaz'gul in Shadowmoon Valley.", ua = "Одягає маскування орка Тіньового Місяця. Орки Тіньового Місяця в Шаз'гулі стають дружніми.\n\n\n\nМожна використати лише в Сутінковому Гаю або в Шаз'гулі в Долині Тіньового Місяця." },
    { en = "Combine three Sha Crystal Fragments into a Sha Crystal.", ua = "Поєднай три Фрагменти Кристала Ша у Кристал Ша." },
    { en = "Combine with a Volen's Foot to create a soulbound item appropriate for your loot specialization ($@lootspec).", ua = "Поєднай з Ногою Волена, щоб створити прив'язаний до душі предмет, що відповідає твоїй спеціалізації здобичі ($@lootspec)." },
    { en = "Combine ten Lichbloom Stalks to create a Lichbloom.", ua = "Поєднай десять Стебел Лічоцвіту, щоб отримати Лічоцвіт." },
    { en = "Create a Blackrock Crucible.", ua = "Створи Тигель Блекрок." },
    { en = "Combine ten Adder's Tongue Stems to create an Adder's Tongue.", ua = "Поєднай десять Стебел Зміїного Язика, щоб отримати Зміїний Язик." },
    { en = "Combine ten Ancient Lichen Petals to create an Ancient Lichen.", ua = "Поєднай десять Пелюсток Стародавнього Лишайника, щоб отримати Стародавній Лишайник." },
    { en = "Combine ten Arthas' Tears Petals to create an Arthas' Tears.", ua = "Поєднай десять Пелюсток Сліз Артаса, щоб отримати Сльози Артаса." },
    { en = "Combine ten Azshara's Veil Stems to create an Azshara's Veil.", ua = "Поєднай десять Стебел Серпанку Азшари, щоб отримати Серпанок Азшари." },
    { en = "Combine ten Blindweed Stems to create a Blindweed.", ua = "Поєднай десять Стебел Сліпотраву, щоб отримати Сліпотрав." },
    { en = "Combine ten Briarthorn Brambles to create a Briarthorn.", ua = "Поєднай десять Колючок Шипшини, щоб отримати Шипшину." },
    { en = "Combine ten Bruiseweed Stems to create a Bruiseweed.", ua = "Поєднай десять Стебел Синяк-трави, щоб отримати Синяк-траву." },
    { en = "Combine ten Cinderbloom Petals to create a Cinderbloom.", ua = "Поєднай десять Пелюсток Попелоцвіту, щоб отримати Попелоцвіт." },
    { en = "Combine ten Deadnettle Brambles to create a Deadnettle.", ua = "Поєднай десять Стебел Глухої Кропиви, щоб отримати Глуху Кропиву." },
    { en = "Combine ten Dragon's Teeth Stems to create a Dragon's Teeth.", ua = "Поєднай десять Стебел Драконових Зубів, щоб отримати Драконові Зуби." },
    { en = "Combine ten Dreamfoil Blades to create a Dreamfoil.", ua = "Поєднай десять Пагонів Снолисту, щоб отримати Снолист." },
    { en = "Combine ten Dreaming Glory Petals to create a Dreaming Glory.", ua = "Поєднай десять Пелюсток Квіту Снів, щоб отримати Квіт Снів." },
    { en = "Combine ten Earthroot Stems to create an Earthroot.", ua = "Поєднай десять Стебел Земнокореня, щоб отримати Земнокорінь." },
    { en = "Combine ten Fadeleaf Petals to create a Fadeleaf.", ua = "Поєднай десять Пелюсток Блідолисту, щоб отримати Блідолист." },
    { en = "Combine ten Felweed Stalks to create a Felweed.", ua = "Поєднай десять Стебел Скверна-трави, щоб отримати Скверна-траву." },
    { en = "Combine ten Fire Leaf Brambles to create a Fire Leaf.", ua = "Поєднай десять Колючок Вогняного Листа, щоб отримати Вогняний Лист." },
    { en = "Combine ten Firebloom Petals to create a Firebloom.", ua = "Поєднай десять Пелюсток Вогнецвіту, щоб отримати Вогнецвіт." },
    { en = "Combine ten Ghost Mushroom Caps to create a Ghost Mushroom.", ua = "Поєднай десять Шапок Примарного Гриба, щоб отримати Примарний Гриб." },
    { en = "Combine ten Goldclover Leafs to create a Goldclover.", ua = "Поєднай десять Листків Золотої Конюшини, щоб отримати Золоту Конюшину." },
    { en = "Combine ten Golden Sansam Leafs to create a Golden Sansam.", ua = "Поєднай десять Листків Золотого Сансаму, щоб отримати Золотий Сансам." },
    { en = "Combine ten Goldthorn Brambles to create a Goldthorn.", ua = "Поєднай десять Колючок Золотошипу, щоб отримати Золотошип." },
    { en = "Combine ten Grave Moss Leafs to create a Grave Moss.", ua = "Поєднай десять Листків Гробового Моху, щоб отримати Гробовий Мох." },
    { en = "Combine ten Gromsblood Leafs to create a Gromsblood.", ua = "Поєднай десять Листків Крові Ґрома, щоб отримати Кров Ґрома." },
    { en = "Combine ten Heartblossom Petals to create a Heartblossom.", ua = "Поєднай десять Пелюсток Серцецвіту, щоб отримати Серцецвіт." },
    { en = "Combine ten Icecap Petals to create an Icecap.", ua = "Поєднай десять Пелюсток Крижаної Шапки, щоб отримати Крижану Шапку." },
    { en = "Combine ten Icethorn Brambles to create an Icethorn.", ua = "Поєднай десять Колючок Крижаного Терену, щоб отримати Крижаний Терен." },
    { en = "Combine ten Khadgar's Whisker Stems to create a Khadgar's Whisker.", ua = "Поєднай десять Стебел Вуса Хадґара, щоб отримати Вус Хадґара." },
    { en = "Combine ten Kingsblood Petals to create a Kingsblood.", ua = "Поєднай десять Пелюсток Королівської Крові, щоб отримати Королівську Кров." },
    { en = "Combine ten Liferoot Stems to create a Liferoot.", ua = "Поєднай десять Стебел Живокореня, щоб отримати Живокорінь." },
    { en = "Combine ten Mageroyal Petals to create a Mageroyal.", ua = "Поєднай десять Пелюсток Маг-Короля, щоб отримати Маг-Король." },
    { en = "Combine ten Mana Thistle Leafs to create a Mana Thistle.", ua = "Поєднай десять Листків Будяка Мани, щоб отримати Будяк Мани." },
    { en = "Combine ten Mountain Silversage Stalks to create a Mountain Silversage.", ua = "Поєднай десять Стебел Гірського Срібношавлію, щоб отримати Гірський Срібношавлій." },
    { en = "Combine ten Netherbloom Leafs to create a Netherbloom.", ua = "Поєднай десять Листків Незерцвіту, щоб отримати Незерцвіт." },
    { en = "Combine ten Nightmare Vine Stems to create a Nightmare Vine.", ua = "Поєднай десять Стебел Лози Жахіть, щоб отримати Лозу Жахіть." },
    { en = "Combine ten Purple Lotus Petals to create a Purple Lotus.", ua = "Поєднай десять Пелюсток Фіолетового Лотоса, щоб отримати Фіолетовий Лотос." },
    { en = "Combine ten Ragveil Caps to create a Ragveil.", ua = "Поєднай десять Шапок Реґвейлу, щоб отримати Реґвейл." },
    { en = "Combine ten Sorrowmoss Leafs to create a Sorrowmoss.", ua = "Поєднайте десять Листків Журного Моху, щоб отримати Журний Мох." },
    { en = "Combine ten Stormvine Stalks to create a Stormvine.", ua = "Поєднайте десять Стебел Штормолози, щоб отримати Штормолозу." },
    { en = "Combine ten Stranglekelp Blades to create a Stranglekelp.", ua = "Поєднайте десять Пластин Душителя-Ламінарії, щоб отримати Душитель-Ламінарію." },
    { en = "Combine ten Sungrass Stalks to create a Sungrass.", ua = "Поєднайте десять Стебел Сонцетрав'я, щоб отримати Сонцетрав'я." },
    { en = "Combine ten Swiftthistle Leafs to create a Swiftthistle.", ua = "Поєднайте десять Листків Прудкочортополоху, щоб отримати Прудкочортополох." },
    { en = "Combine ten Talandra's Rose Petals to create a Talandra's Rose.", ua = "Поєднайте десять Пелюсток Троянди Таландри, щоб отримати Троянду Таландри." },
    { en = "Combine ten Terocone Leafs to create a Terocone.", ua = "Поєднайте десять Листків Терошишки, щоб отримати Терошишку." },
    { en = "Combine ten Tiger Lily Petals to create a Tiger Lily.", ua = "Поєднайте десять Пелюсток Тигрової Лілії, щоб отримати Тигрову Лілію." },
    { en = "Combine ten Twilight Jasmine Petals to create a Twilight Jasmine.", ua = "Поєднайте десять Пелюсток Сутінкового Жасмину, щоб отримати Сутінковий Жасмин." },
    { en = "Combine ten Whiptail Stems to create a Whiptail.", ua = "Поєднайте десять Стебел Батожника, щоб отримати Батожник." },
    { en = "Combine ten Wild Steelbloom Petals to create a Wild Steelbloom.", ua = "Поєднайте десять Пелюсток Дикого Сталецвіту, щоб отримати Дикий Сталецвіт." },
    { en = "Combine the components to create an Inferno Tonk.", ua = "Поєднайте складники, щоб створити Пекельний Тонк." },
    { en = "Create a demonic gateway between two locations. Stepping into the gateway causes any party member to be instantly transported to the other gateway.\n\n\n\nLimit 5 charges. The portal generates one charge every $113901t1 seconds and lasts $113886d.", ua = "Створює демонічну браму між двома місцями. Ступивши в браму, будь-який член групи миттєво переноситься до іншої брами.\n\n\n\nМаксимум 5 зарядів. Портал генерує один заряд кожні $113901t1 сек. і триває $113886d." },
    { en = "Create a temporary hologram of yourself for $d.", ua = "Створює тимчасову голограму вас самих на $d." },
    { en = "Permanently enchant gloves to increase Fire spell power by $s1.", ua = "Назавжди зачаровує рукавиці, збільшуючи силу заклять Вогню на $s1." },
    { en = "Combine 3 Small Duskwing Dust Samples to create a Duskwing Dust Sample.", ua = "Поєднайте 3 Малі Зразки Пилу Сутінкокрила, щоб отримати Зразок Пилу Сутінкокрила." },
    { en = "Permanently attaches a special device to a ranged weapon, sometimes increases haste by $156055s1 for $156055d when dealing damage with ranged attacks.\n\n\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level $ecix.", ua = "Назавжди прикріплює особливий пристрій до дальнобійної зброї, що інколи збільшує поспіх на $156055s1 упродовж $156055d, коли ви завдаєте шкоди дальнобійними атаками.\n\n\n\nПрикріплення цього пристрою до дальнобійної зброї робить її прив'язаною до душі. Не можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently attaches an electrified device to a ranged weapon, sometimes increasing Critical Strike by $156060s1 for $156060d when dealing damage with ranged attacks.\n\n\n\nAttaching this device to a ranged weapon causes it to become soulbound. Cannot be applied to items above level $ecix.", ua = "Назавжди прикріплює наелектризований пристрій до дальнобійної зброї, що інколи збільшує критичний удар на $156060s1 упродовж $156060d, коли ви завдаєте шкоди дальнобійними атаками.\n\n\n\nПрикріплення цього пристрою до дальнобійної зброї робить її прив'язаною до душі. Не можна застосувати до предметів вище рівня $ecix." },
    { en = "Teaches you Draenor Alchemy and a number of recipes.", ua = "Навчає вас Алхімії Дренору та кількох рецептів." },
    { en = "Provides the plans needed to repair the Garrison Herb Garden.\n\n\n\n$@garrbuilding29", ua = "Надає плани, потрібні для ремонту Трав'яного Саду гарнізону.\n\n\n\n$@garrbuilding29" },
    { en = "Blackrock Spines grow from Oregorger's back, allowing him to launch a $@spellname156877.", ua = "На спині Орегорджера ростуть Блекрокські Шипи, що дозволяють йому застосувати $@spellname156877." },
    { en = "Combine ten for Frostweed.", ua = "Поєднайте десять, щоб отримати Морозозілля." },
    { en = "Combine ten for Fireweed.", ua = "Поєднайте десять, щоб отримати Вогнезілля." },
    { en = "Combine ten for Gorgrond Flytrap.", ua = "Поєднайте десять, щоб отримати Горгрондську Мухоловку." },
    { en = "Combine ten for Starflower.", ua = "Поєднайте десять, щоб отримати Зореквіт." },
    { en = "Combine ten for Nagrand Arrowbloom.", ua = "Поєднайте десять, щоб отримати Награндську Стрілоцвіть." },
    { en = "Combine ten for Talador Orchid.", ua = "Поєднайте десять, щоб отримати Таладорську Орхідею." },
    { en = "Combine ten Blackrock Fragments to create a single Blackrock Ore.", ua = "Поєднайте десять Блекрокських Уламків, щоб отримати одну Блекрокську Руду." },
    { en = "Permanently enchant a cloak to increase critical strike by $ec1.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи критичний удар на $ec1.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a cloak to increase haste by $ec1.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи поспіх на $ec1.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a cloak to increase mastery by $ec1.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи майстерність на $ec1.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a cloak to increase critical strike by $ec1.\n\n\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи критичний удар на $ec1.\n\n\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
