    { en = "Permanently enchant a cloak to increase haste by $ec1 and movement speed by $182495s1%.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи поспіх на $ec1 і швидкість пересування на $182495s1%.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a cloak to increase mastery by $ec1 and movement speed by $182495s1%.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи майстерність на $ec1 і швидкість пересування на $182495s1%.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a cloak to increase versatility by $ec1 and movement speed by $182495s1%.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує плащ, збільшуючи універсальність на $ec1 і швидкість пересування на $182495s1%.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a neck to increase critical strike by $ec1.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує намисто, збільшуючи критичний удар на $ec1.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
    { en = "Permanently enchant a neck to increase haste by $ec1.\n\n\n\nCannot be applied to items higher than level $ecix.", ua = "Назавжди зачаровує намисто, збільшуючи поспіх на $ec1.\n\n\n\nНе можна застосувати до предметів вище рівня $ecix." },
