    { en = "Combine 4 Redrock Slabs to build a dam and block off the waterfall.", ua = "Поєднай 4 Плити Червонокаменю, щоб збудувати дамбу й перекрити водоспад." },
    { en = "Combine with a conductive sheath, an arc circuit, and a power cell to repair the portal generator and gain access to Squadron Commander Vishax's portal.", ua = "Поєднай з провідною оболонкою, дуговим ланцюгом та енергоелементом, щоб полагодити генератор порталу й дістати доступ до порталу командира ескадрону Вішакса." },
    { en = "Combine 100 imp meat to create a disgusting, stinky feast. Why would anyone eat this?", ua = "Поєднай 100 М'яса Імпа, щоб створити огидний смердючий бенкет. Навіщо взагалі це їсти?" },
    { en = "Create a temporary barrier.", ua = "Створи тимчасовий бар'єр." },
    { en = "Apply the bandage, restoring $s1% health every $t1 sec. for $d and dealing Holy damage to attackers. Only usable on the Broken Isles and Argus.", ua = "Наклади бинт, який відновлює $s1% здоров'я кожні $t1 сек. протягом $d і завдає шкоди від Світла нападникам. Придатний лише на Зламаних островах та Аргусі." },
    { en = "Permanently enchants shoulders with the Steadfast enchantment, allowing the wearer to obtain Argunite Clusters from the corpses of their enemies. Cannot be applied to items above level $ecix.", ua = "Назавжди зачаровує плечі чарами «Стійкість», дозволяючи власнику здобувати Скупчення Аргуніту з трупів ворогів. Не можна застосувати до предметів вищого рівня за $ecix." },
    { en = "Permanently enchants shoulders with the Lightbearer enchantment, allowing the wearer to obtain Light's Fortune from the corpses of their enemies. Cannot be applied to items above level $ecix.", ua = "Назавжди зачаровує плечі чарами «Світлоносець», дозволяючи власнику здобувати Скарб Світла з трупів ворогів. Не можна застосувати до предметів вищого рівня за $ecix." },
    { en = "Create a soulbound Arcane relic.", ua = "Створи прив'язану до душі арканну реліквію." },
    { en = "Create a soulbound Blood relic.", ua = "Створи прив'язану до душі криваву реліквію." },
    { en = "Create a soulbound Fel relic.", ua = "Створи прив'язану до душі реліквію Скверни." },
    { en = "Create a soulbound Fire relic.", ua = "Створи прив'язану до душі вогняну реліквію." },
    { en = "Create a soulbound Frost relic.", ua = "Створи прив'язану до душі крижану реліквію." },
    { en = "Create a soulbound Holy relic.", ua = "Створи прив'язану до душі священну реліквію." },
    { en = "Create a soulbound Iron relic.", ua = "Створи прив'язану до душі залізну реліквію." },
    { en = "Create a soulbound Life relic.", ua = "Створи прив'язану до душі реліквію Життя." },
    { en = "Create a soulbound Shadow relic.", ua = "Створи прив'язану до душі тіньову реліквію." },
    { en = "Create a soulbound Storm relic.", ua = "Створи прив'язану до душі штормову реліквію." },
    { en = "Allows faster gathering of herbs on Kul Tiras and Zandalar.", ua = "Дозволяє швидше збирати трави в Кул-Тірасі та Зандаларі." },
    { en = "Permanently enchants bracers to increase the speed of your Hearthstone cast while in Kul Tiras or Zandalar.\n\n\n\nOnly the enchanter's bracers can be enchanted, and doing so will cause them to become soulbound.", ua = "Назавжди зачаровує наручі, пришвидшуючи прочитання вашого Каменя повернення в Кул-Тірасі чи Зандаларі.\n\n\n\nЗачарувати можна лише наручі самого зачарувальника, і після цього вони стануть прив'язаними до душі." },
    { en = "Permanently enchant a weapon to sometimes cause the wielder's helpful spells to put a short heal over time effect on the target for $267537d.\n\n\n\nReduced materials.", ua = "Назавжди зачаровує зброю, завдяки чому корисні закляття власника інколи накладають на ціль короткий ефект періодичного зцілення на $267537d.\n\n\n\nЗменшена витрата матеріалів." },
    { en = "Permanently enchant a weapon to sometimes cause the wielder's helpful spells to put a short heal over time effect on the target for $267537d.\n\n\n\nGreatly reduced materials.", ua = "Назавжди зачаровує зброю, завдяки чому корисні закляття власника інколи накладають на ціль короткий ефект періодичного зцілення на $267537d.\n\n\n\nЗначно зменшена витрата матеріалів." },
    { en = "Permanently enchant a weapon to proc an aura which increases your elemental spell damage by $267685s%.\n\n\n\nReduced materials.", ua = "Назавжди зачаровує зброю, щоб вона активувала ауру, яка збільшує шкоду ваших стихійних заклять на $267685s%.\n\n\n\nЗменшена витрата матеріалів." },
    { en = "Permanently enchant a weapon to proc an aura which increases your elemental spell damage by $267685s%.\n\n\n\nGreatly reduced materials.", ua = "Назавжди зачаровує зброю, щоб вона активувала ауру, яка збільшує шкоду ваших стихійних заклять на $267685s%.\n\n\n\nЗначно зменшена витрата матеріалів." },
    { en = "Permanently enchant a weapon to proc an aura which increases your attack speed by $267612s% for $267612d when using melee or ranged attacks and abilities. \n\n\n\nReduced materials.", ua = "Назавжди зачаровує зброю, щоб вона активувала ауру, яка збільшує вашу швидкість атаки на $267612s% на $267612d, коли ви застосовуєте ближні чи дальні атаки та здібності. \n\n\n\nЗменшена витрата матеріалів." },
    { en = "Permanently enchant a weapon to proc an aura which increases your attack speed by $267612s% for $267612d when using melee or ranged attacks and abilities.\n\n\n\nGreatly reduced materials.", ua = "Назавжди зачаровує зброю, щоб вона активувала ауру, яка збільшує вашу швидкість атаки на $267612s% на $267612d, коли ви застосовуєте ближні чи дальні атаки та здібності.\n\n\n\nЗначно зменшена витрата матеріалів." },
    { en = "Permanently attaches a specialized device to your belt, allowing you to fear an enemy within melee range for $269186d.\n\n\n\nOnly the engineer's belt can be modified, and doing so will cause them to become soulbound.", ua = "Назавжди прикріплює спеціалізований пристрій до вашого пояса, дозволяючи вам налякати ворога в межах ближнього бою на $269186d.\n\n\n\nМодифікувати можна лише пояс самого інженера, і після цього він стане прив'язаним до душі." },
    { en = "Permanently attaches a specialized device to your belt, allowing you to knockback your current target.  Shares a cooldown with potions.\n\n\n\nOnly the engineer's belt can be modified, and doing so will cause them to become soulbound.", ua = "Назавжди прикріплює спеціалізований пристрій до вашого пояса, дозволяючи вам відкинути поточну ціль.  Має спільне перезарядження з зіллями.\n\n\n\nМодифікувати можна лише пояс самого інженера, і після цього він стане прив'язаним до душі." },
    { en = "Craft a Curved Diamond Awl Blade.", ua = "Виготов вигнуте діамантове лезо шила." },
