    { en = "Prepare more Nightborne Delicacy Platter in each batch.", ua = "Приготуй більше Таця з Делікатесами Нічнороджених за один раз." },
    { en = "Prepare more Seed-Battered Fish Plate in each batch.", ua = "Приготуй більше Риба в Зерновій Паніровці за один раз." },
    { en = "Prepare more Fishbrul Special in each batch.", ua = "Приготуй більше Фірмова Страва Фішбрула за один раз." },
    { en = "Prepare more Dried Mackerel Strips in each batch.", ua = "Приготуй більше Сушені Смужки Скумбрії за один раз." },
    { en = "Prepare more Bear Tartare in each batch.", ua = "Приготуй більше Ведмежий Тартар за один раз." },
