    { en = "Prepare more Honey-Glazed Haunches in each batch.", ua = "Приготуй більше Стегенця в Медовій Глазурі за один раз." },
    { en = "Prepare more Ravenberry Tarts in each batch.", ua = "Приготуй більше Тарти з Вороникою за один раз." },
    { en = "Prepare more Swamp Fish 'n Chips in each batch.", ua = "Приготуй більше Болотна Риба з Картоплею Фрі за один раз." },
    { en = "Prepare more Grilled Catfish in each batch.", ua = "Приготуй більше Смажений Сом за один раз." },
    { en = "Prepare more Seasoned Loins in each batch.", ua = "Приготуй більше Присмачена Вирізка за один раз." },
    { en = "Prepare more Loa Loaf in each batch.", ua = "Приготуй більше Коровай Лоа за один раз." },
