    { en = "Prepare more Bil'Tong in each batch.", ua = "Приготуй більше Біл'Тонг за один раз." },
    { en = "Becoming an Angler is easy!\n\n\n\nCast your line and reel in the many secrets Khaz Algar has to offer.\n\n\n\nCaught Fish and Fishing Pools will appear here in your trusty Fishing Journal. The records here will detail these fanciful fish and give indication on where you might find them!", ua = "Стати рибалкою легко!\n\n\n\nЗакидай вудку й виловлюй численні таємниці, що їх береже Каз Алґар.\n\n\n\nСпіймана риба та рибні косяки з'являтимуться тут, у твоєму вірному Журналі рибалки. Записи розкажуть про цих дивовижних рибин і підкажуть, де їх можна знайти!" },
    { en = "|cnGREEN_FONT_COLOR:Recommended Skill:|r 1\n\n\n\nCalm and serene waters make it an ideal location for Anglers to begin exploring what the depths have to offer.\n\n\n\nPools found in this zone:\n\n- Sunwell Swarm\n\n- Bubbling Bloom\n\n- Bloom Swarm\n\n- Viscous Void\n\n- Careless Cargo\n\n- Lost Treasures", ua = "|cnGREEN_FONT_COLOR:Рекомендована навичка:|r 1\n\n\n\nТихі та спокійні води роблять цю місцину ідеальною для рибалок, які лише починають досліджувати, що ховають глибини.\n\n\n\nРибні косяки в цій зоні:\n\n- Зграя Сонячного Колодязя\n\n- Булькотливий квіт\n\n- Квітковий рій\n\n- В'язка Порожнеча\n\n- Недбалий вантаж\n\n- Загублені Скарби" },
    { en = "There are too many threats in the sky for flight to be possible at the moment.", ua = "У небі зараз забагато загроз, щоб можна було літати." },
    { en = "Call in a Flamestrike from an allied blood elf mage.", ua = "Викликає «Удар полум'я» від союзного мага ельфів крові." },
    { en = "Call in a Starfall from an allied night elf priestess.", ua = "Викликає «Зорепад» від союзної жриці нічних ельфів." },
    { en = "Call in a Consecration from an allied blood elf paladin.", ua = "Викликає «Освячення» від союзного паладина ельфів крові." },
    { en = "Move downward.", ua = "Рух униз." },
    { en = "Throw the Improvised Arcane Device.", ua = "Кидає імпровізований арканний пристрій." },
    { en = "Signal Vereesa and her airborne rangers.", ua = "Подає сигнал Вересі та її повітряним рейнджерам." },
    { en = "Pockets of the Void are leaking into Azeroth.", ua = "Кишені Порожнечі просочуються в Азерот." },
    { en = "Feed a violet chloroceros bud to a hydra budling.", ua = "Годує гідреня пуп'янком фіолетового хлороцероса." },
    { en = "Collect the appearances of the Silversun Compact Shoulderpads, Cape, and Tabard.", ua = "Збери вигляди Наплічників, Плаща та Накидки Срібносонячного договору." },
    { en = "Command the nearby lynx to reveal any nearby stealthed enemies.", ua = "Наказує рисі поблизу викрити всіх ворогів у скрадливості довкола." },
    { en = "Use the Cynosure of Twilight to reach out into the Great Dark Beyond and locate a distant world.", ua = "Використай Світоч Сутінків, щоб зазирнути у Велику Темну Безодню й відшукати далекий світ." },
    { en = "Each Mote of Omnial Inquiry can be used to empower the runes within your Omnium Folio.", ua = "Кожну Часточку омніального дослідження можна використати, щоб наснажити руни у твоєму Фоліанті Омніуму." },
    { en = "Receive the Decor Sunstrider Omnium Simulacrum upon completion of the five Seeking Knowledge requests.", ua = "Отримай декор «Симулякр Омніуму Сонстрайдерів», виконавши всі п'ять доручень «Пошуку знань»." },
    { en = "Access to Kifaan's vapors and other consumables to aid in the fight on Val and Naigtal.", ua = "Доступ до випарів Кіфаана та інших припасів, що стануть у пригоді в боях на Валі й Найґталі." },
    { en = "Requesting the lynx loa's aid.", ua = "Просить допомоги в лоа-рисі." },
    { en = "Provoke the crowd.", ua = "Провокує натовп." },
    { en = "Inflicts Nature damage to target and nearby enemies.", ua = "Завдає шкоди від сил природи цілі та ворогам поблизу." },
    { en = "Toss this ethereal battery at the target area, dealing heavy damage to machinery and enemies.", ua = "Кидає цю батарею ефіріалів у цільову область, завдаючи великої шкоди механізмам і ворогам." },
    { en = "Restores ${$m2/5*18} mana over $d.  Must remain seated while drinking.", ua = "Відновлює ${$m2/5*18} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*21} mana over $d.  Must remain seated while drinking.", ua = "Відновлює ${$m2/5*21} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*24} mana over $d.  Must remain seated while drinking.", ua = "Відновлює ${$m2/5*24} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores ${$m1*18/5} health over $d. Must remain seated while eating.", ua = "Відновлює ${$m1*18/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$s1*$d/5} health over $d.  Must remain seated while eating.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$s1*$d/5} health over $d. Must remain seated while eating.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Instantly heals $s1 damage.  Also restores $o2 mana over $d.  Must remain seated while drinking.", ua = "Миттєво зцілює $s1 шкоди. Також відновлює $o2 мани протягом $d. Під час пиття потрібно лишатися сидячи." },
