    { en = "Restores $o1 health over $d.  Must remain seated while eating. Also increases your Strength by $18125s1 for $18125d.", ua = "Відновлює $o1 здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також підвищує вашу силу на $18125s1 протягом $18125d." },
    { en = "Restores $o1 mana over $d.  Must remain seated while drinking.  Also increases your Versatility by $18141s1 for $18141d.", ua = "Відновлює $o1 мани протягом $d. Під час пиття потрібно лишатися сидячи. Також підвищує вашу Універсальність на $18141s1 протягом $18141d." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   Also increases your Stamina by $18191s for $18191d.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також підвищує вашу Витривалість на $18191s на $18191d." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   If you eat for 10 seconds will also increase your Agility by $18192s for $18192d.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете 10 секунд, також підвищить вашу Спритність на $18192s на $18192d." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   Also increases your Versatility by $18193s for $18193d.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також підвищує вашу Універсальність на $18193s на $18193d." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   Also restores $18222s1 health every 5 seconds for 10 min.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також відновлює $18222s1 здоров'я кожні 5 секунд протягом 10 хв." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   Also restores $18194s Mana every 5 seconds for $18194d.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також відновлює $18194s мани кожні 5 секунд протягом $18194d." },
    { en = "Restores ${$s1*$d/5} health over $d.   Must remain seated while eating.   Also increases your Intellect by $18191s for $18191d.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Також підвищує ваш Інтелект на $18191s на $18191d." },
    { en = "Restores $25695o1 health and $25696o2 mana over $25695d.  Must remain seated while eating.  Usable only inside Warsong Gulch.", ua = "Відновлює $25695o1 здоров'я та $25696o2 мани протягом $25695d. Під час їжі потрібно лишатися сидячи. Використовується лише в Ущелині Пісні Війни." },
