    { en = "Restores $25886o1 health and $25887o1 mana over $25887d.  Must remain seated while eating.", ua = "Відновлює $25886o1 здоров'я та $25887o1 мани протягом $25887d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$s1*$d/5} health and ${$s2*$d/5} mana over $d.  Must remain seated while eating.", ua = "Відновлює ${$s1*$d/5} здоров'я та ${$s2*$d/5} мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $o1 mana over $d.  Must remain seated while eating.", ua = "Відновлює $o1 мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$m1/5*$d} health and ${$m3/5*$d} mana over $d. Must remain seated while eating. You should also probably like the taste of fruitcake.", ua = "Відновлює ${$m1/5*$d} здоров'я та ${$m3/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи. А ще вам, напевно, має смакувати фруктовий кекс." },
