    { en = "Restores $o1 health and ${$100367m2/1*5} mana over $d.  Must remain seated while eating.  If you spend at least 5 seconds eating you will become well fed and gain $87547s1 Strength and $100368s2 Stamina for $100368d.", ua = "Відновлює $o1 здоров'я та ${$100367m2/1*5} мани протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 5 секунд, то станете наїденими й отримаєте $87547s1 Сили та $100368s2 Витривалості на $100368d." },
    { en = "Restores ${$m2/5*$d} mana over $d.  Must remain seated while drinking.", ua = "Відновлює ${$m2/5*$d} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $104235o1 health and ${$104262m2/5*$104262d} mana over $104235d.  Must remain seated while drinking.", ua = "Відновлює $104235o1 здоров'я та ${$104262m2/5*$104262d} мани протягом $104235d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores ${$118358m2/5*10} mana over $118358d.  Must remain seated while drinking.  Known to cause massive headaches.", ua = "Відновлює ${$118358m2/5*10} мани протягом $118358d. Під час пиття потрібно лишатися сидячи. Відомий тим, що спричиняє страшний головний біль." },
    { en = "Restores $105231o1 health and ${$105230m2/5*10} mana over $105231d.  Must remain seated while drinking.  May induce delusions of grandeur.", ua = "Відновлює $105231o1 здоров'я та ${$105230m2/5*10} мани протягом $105231d. Під час пиття потрібно лишатися сидячи. Може викликати манію величі." },
    { en = "Restores ${$m2/5*$d} mana over $d. Must remain seated while drinking.", ua = "Відновлює ${$m2/5*$d} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $108030o1 health over $108030d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $108028s1 Intellect for $108028d.", ua = "Відновлює $108030o1 здоров'я протягом $108030d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $108028s1 до інтелекту на $108028d." },
    { en = "Restores $108030o1 health over $108030d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $108031s1 Strength for $108031d.", ua = "Відновлює $108030o1 здоров'я протягом $108030d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $108031s1 до сили на $108031d." },
    { en = "Restores $108030o1 health over $108030d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $108032s1 Agility for $108032d.", ua = "Відновлює $108030o1 здоров'я протягом $108030d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $108032s1 до спритності на $108032d." },
    { en = "Restores $o1 health and ${$111841m2/1*5} mana over $d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $100368s2 Stamina and feel very healthy for $100368d.", ua = "Відновлює $o1 здоров'я та ${$111841m2/1*5} мани протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим, отримаєте $100368s2 Витривалості й почуватиметеся дуже здоровим протягом $100368d." },
    { en = "Restores ${$m1/5*15} mana over $d.  Must remain seated while drinking.", ua = "Відновлює ${$m1/5*15} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores health over time. Must remain seated while drinking.", ua = "Відновлює здоров'я з часом. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $104935o1 health and ${$104270m2/5*$104270d} mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104283s1 Stamina for $104283d.", ua = "Відновлює $104935o1 здоров'я та ${$104270m2/5*$104270d} мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $104283s1 Витривалості на $104283d." },
    { en = "Restores $o1 health over $d.  Must remain seated while eating.", ua = "Відновлює $o1 здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$s1*$d/5} health over $d.  Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain a random buff that works in Kun-Lai Summit.\n\nOnly usable in Kun-Lai Summit.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте випадкове підсилення, що діє на Вершині Кун-Лай.\n\nМожна використати лише на Вершині Кун-Лай." },
    { en = "Restores $104934o1 health and ${$104269m2/5*$104269d} mana over $104269d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104276s1 in a useful stat for $87545d.", ua = "Відновлює $104934o1 здоров'я та ${$104269m2/5*$104269d} мани протягом $104269d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими й отримаєте $104276s1 до корисної характеристики на $87545d." },
    { en = "Restores ${$m2/5*10} mana over $d. Must remain seated while drinking.", ua = "Відновлює ${$m2/5*10} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores 200,000 health and 200,000 mana over $104269d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain 275 in a useful stat for $87545d.", ua = "Відновлює 200 000 здоров'я та 200 000 мани протягом $104269d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете Наїдені й отримаєте 275 до корисної характеристики на $87545d." },
    { en = "Restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104273s1 in a useful stat for $104273d.", ua = "Відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими й отримаєте $104273s1 до корисної характеристики на $104273d." },
    { en = "Restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104274s1 in a useful stat for $104274d.", ua = "Відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими й отримаєте $104274s1 до корисної характеристики на $104274d." },
    { en = "Restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104275s1 in a useful stat for $104275d.", ua = "Відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими й отримаєте $104275s1 до корисної характеристики на $104275d." },
    { en = "Set out a Noodle Cart to sell up to 10 bowls!\n\n\n\nEach Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104273s1 in a useful stat for $104273d.", ua = "Виставте Візок з Локшиною, щоб продати до 10 мисок!\n\n\n\nКожна Юшка з Локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $104273s1 до корисної характеристики на $104273d." },
    { en = "Set out a Deluxe Noodle Cart to sell up to 10 bowls!\n\n\n\nEach Deluxe Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104274s1 in a useful stat for $104274d.", ua = "Виставте Розкішний візок з локшиною, щоб продати до 10 мисок!\n\n\n\nКожен Розкішний суп із локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $104274s1 до корисної характеристики на $104274d." },
    { en = "Set out a Pandaren Treasure Noodle Cart to sell up to 10 bowls!\n\n\n\nEach Pandaren Treasure Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104275s1 in a useful stat for $104275d.", ua = "Виставте Візок з Локшиною «Пандаренський Скарб», щоб продати до 10 мисок!\n\n\n\nКожна Юшка з Локшиною «Пандаренський Скарб» відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $104275s1 до корисної характеристики на $104275d." },
    { en = "Set out a Noodle Cart to sell Noodle Soup!\n\n\n\nEach Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104273s1 in a useful stat for $104273d.", ua = "Виставте Візок з Локшиною, щоб продавати Юшку з Локшиною!\n\n\n\nКожна Юшка з Локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $104273s1 до корисної характеристики на $104273d." },
    { en = "Set out a Deluxe Noodle Cart to sell Deluxe Noodle Soup!\n\n\n\nEach Deluxe Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104274s1 in a useful stat for $104274d.", ua = "Виставте Розкішний візок з локшиною, щоб продавати Розкішний суп із локшиною!\n\n\n\nКожен Розкішний суп із локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $104274s1 до корисної характеристики на $104274d." },
    { en = "Set out a Pandaren Treasure Noodle Cart to sell Pandaren Treasure Noodle Soup!\n\n\n\nEach Pandaren Treasure Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104275s1 in a useful stat for $104275d.", ua = "Виставте Візок з Локшиною «Пандаренський Скарб», щоб продавати Юшку з Локшиною «Пандаренський Скарб»!\n\n\n\nКожна Юшка з Локшиною «Пандаренський Скарб» відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $104275s1 до корисної характеристики на $104275d." },
    { en = "Set out a Grand Noodle Cart to sell up to 25 bowls!\n\n\n\nEach Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104273s1 in a useful stat for $104273d.", ua = "Виставте Великий візок з локшиною, щоб продати до 25 мисок!\n\n\n\nКожен Суп із локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $104273s1 до корисної характеристики на $104273d." },
    { en = "Set out a Grand Deluxe Noodle Cart to sell up to 25 bowls!\n\n\n\nEach Deluxe Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104274s1 in a useful stat for $104274d.", ua = "Виставте Великий розкішний візок з локшиною, щоб продати до 25 мисок!\n\n\n\nКожен Розкішний суп із локшиною відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $104274s1 до корисної характеристики на $104274d." },
    { en = "Set out a Grand Pandaren Treasure Noodle Cart to sell up to 25 bowls!\n\n\n\nEach Pandaren Treasure Noodle Soup restores $104935o1 health and $104270s1 mana over $104935d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $104275s1 in a useful stat for $104275d.", ua = "Виставте Великий візок з локшиною «Пандаренський скарб», щоб продати до 25 мисок!\n\n\n\nКожен Суп із локшиною «Пандаренський скарб» відновлює $104935o1 здоров'я та $104270s1 мани протягом $104935d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $104275s1 до корисної характеристики на $104275d." },
    { en = "Restores $104235o1 health and ${$104262m2/5*$104262d} mana over $104235d.  Must remain seated while eating. If you spend at least 10 seconds eating you will become queasy.", ua = "Відновлює $104235o1 здоров'я та ${$104262m2/5*$104262d} мани протягом $104235d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, вам стане зле." },
    { en = "Reduces inebriation and restores ${$m2/5*$d} mana over $d.  Must remain seated while drinking.", ua = "Зменшує сп'яніння та відновлює ${$m2/5*$d} мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $o1 health over $d.  Must remain seated while drinking.", ua = "Відновлює $o1 здоров'я протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $o3% health and $o1% Mana over $d. Must remain seated while drinking.", ua = "Відновлює $o3% здоров'я та $o1% мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $o1% health and $o2% Mana over $d. Must remain seated while drinking. Can only be used in Draenor.", ua = "Відновлює $o1% здоров'я та $o2% мани протягом $d. Під час пиття потрібно лишатися сидячи. Можна використати лише в Дренорі." },
    { en = "Restores $o1 health over $d. Restores ${$m2/5*$d} mana over $d.  Must remain seated while eating & drinking.", ua = "Відновлює $o1 здоров'я протягом $d. Відновлює ${$m2/5*$d} мани протягом $d. Під час їжі та пиття потрібно лишатися сидячи." },
    { en = "Restores ${$172786m2/5*$172786d} mana over $172786d.  Must remain seated while drinking.  If you spend at least 10 seconds drinking you will become well fed and gain $177931s1 Versatility for $177931d.", ua = "Відновлює ${$172786m2/5*$172786d} мани протягом $172786d. Під час пиття потрібно лишатися сидячи. Якщо ви питимете щонайменше 10 секунд, ви станете наїденим та отримаєте $177931s1 універсальності на $177931d." },
    { en = "Restores $s1% of your health and mana per second for $d and you will become Well Fed, increasing Versatility for $185736d.  Must remain seated while eating. Ineffective over level $maxcast.", ua = "Відновлює $s1% вашого здоров'я та мани щосекунди протягом $d, і ви станете Наїденим, що підвищує універсальність на $185736d. Під час їжі потрібно лишатися сидячи. Неефективно понад рівень $maxcast." },
    { en = "Restores $s1% of your health and mana per second for $d and you will become Fancily Fed, increasing Versatility for $185786d and dressing you up.  Must remain seated while eating.", ua = "Відновлює $s1% вашого здоров'я та мани щосекунди протягом $d, і ви станете Вишукано Наїденим, що підвищує універсальність на $185786d та вбирає вас у пишні шати. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% of your health and mana per second for $d and you will become Well Fed, increasing Versatility for $185736d.  Must remain seated while eating.", ua = "Відновлює $s1% вашого здоров'я та мани щосекунди протягом $d, і ви станете Наїденим, що підвищує універсальність на $185736d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$m1/5*$d} health and ${$m2/5*$d} mana over $d.  Must remain seated while eating.", ua = "Відновлює ${$m1/5*$d} здоров'я та ${$m2/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores 5% health and mana per second for 20 seconds.  Must remain seated while eating.", ua = "Відновлює 5% здоров'я та мани щосекунди протягом 20 секунд. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$s1*$d/5} health over $d. Restores ${$m2/5*$d} mana over $d.  Must remain seated while eating & drinking.", ua = "Відновлює ${$s1*$d/5} здоров'я протягом $d. Відновлює ${$m2/5*$d} мани протягом $d. Під час їжі та пиття потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*21} mana over $d.  Must remain seated while drinking. A highly dignified beverage.", ua = "Відновлює ${$m2/5*21} мани протягом $d. Під час пиття потрібно лишатися сидячи. Вельми шляхетний напій." },
    { en = "Set out a Hearty Feast to feed up to 35 people in your raid or party!\n\n\n\nRestores $192002o1 health and $192002o2 mana over $192002d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $201634s1 in a stat for $201634d.", ua = "Влаштуйте Ситний бенкет, щоб нагодувати до 35 учасників вашого рейду чи групи!\n\n\n\nВідновлює $192002o1 здоров'я та $192002o2 мани протягом $192002d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $201634s1 до характеристики на $201634d." },
    { en = "Set out a Lavish Suramar Feast to feed up to 35 people in your raid or party!\n\n\n\nRestores $192002o1 health and $192002o2 mana over $192002d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $201638s1 in a stat for $201638d.", ua = "Виставте Розкішний Бенкет Сурамару, щоб нагодувати до 35 осіб у вашому рейді чи групі!\n\n\n\nВідновлює $192002o1 здоров'я та $192002o2 мани протягом $192002d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $201638s1 до характеристики на $201638d." },
    { en = "Restores $s1% of your health over $d.  Must remain seated while eating.", ua = "Відновлює $s1% вашого здоров'я протягом $d.  Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% mana per second for $d.  Must remain seated while drinking.", ua = "Відновлює $s1% мани щосекунди протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "As long as it has not gone bad it restores $191876o1 health over $191876d.  Must remain seated while eating.", ua = "Поки страва не зіпсувалася, відновлює $191876o1 здоров'я протягом $191876d. Під час їжі потрібно лишатися сидячи." },
    { en = "As long as it has not gone bad it restores $192001o1 mana over $192001d.  Must remain seated while drinking.", ua = "Поки напій не зіпсувався, відновлює $192001o1 мани протягом $192001d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores $o1% health and $o2% Mana over $d. Must remain seated while drinking.", ua = "Відновлює $o1% здоров'я та $o2% мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores you to full health and mana over $d. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain Mastery for $226805d.", ua = "Повністю відновлює ваше здоров'я та ману протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете Наїдені й отримаєте майстерність на $226805d." },
    { en = "Restores you to full health and mana over $d. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain Versatility for $226807d.", ua = "Відновлює вам усе здоров'я та ману протягом $d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте Універсальність на $226807d." },
    { en = "Restores ${$m1/5*$d} health and ${$m2/5*$d} mana over $d.  Must remain seated while eating.\n\n\n\nIf you spend at least 10 seconds eating you will become well fed and gain all the powers of a fish for [DURATION].", ua = "Відновлює ${$m1/5*$d} здоров'я та ${$m2/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи.\n\n\n\nЯкщо ви їстимете щонайменше 10 секунд, ви станете наїденим і здобудете всі здібності риби на [DURATION]." },
    { en = "Set out a Feast of the Fishes to feed up to 50 people in your raid or party!\n\n\n\nRestores $251232o1 health and $251232o2 mana over $251232d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will obtain all of the powers of a fish.", ua = "Влаштуйте Бенкет риб, щоб нагодувати до 50 учасників вашого рейду чи групи!\n\n\n\nВідновлює $251232o1 здоров'я та $251232o2 мани протягом $251232d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то отримаєте всі здібності риби." },
    { en = "Restores ${$m1/5*$d} health and ${$m3/5*$d} mana over $d.  Must remain seated while eating.", ua = "Відновлює ${$m1/5*$d} здоров'я та ${$m3/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Set out a Galley Banquet to feed up to 35 people in your raid or party!\n\n\n\nRestores $257428o1 health and $257428o2 mana over $257428d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $259452s1 in a stat for $259452d.", ua = "Влаштуйте Камбузний бенкет, щоб нагодувати до 35 учасників вашого рейду чи групи!\n\n\n\nВідновлює $257428o1 здоров'я та $257428o2 мани протягом $257428d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $259452s1 до характеристики на $259452d." },
    { en = "Set out a Bountiful Captain's Feast to feed up to 35 people in your raid or party!\n\n\n\nRestores $257427o1 health and $257427o2 mana over $257427d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $259456s1 in a stat for $259456d.", ua = "Влаштуйте Щедрий капітанський бенкет, щоб нагодувати до 35 учасників вашого рейду чи групи!\n\n\n\nВідновлює $257427o1 здоров'я та $257427o2 мани протягом $257427d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $259456s1 до характеристики на $259456d." },
    { en = "Restores ${$m3/5*$d} health and ${$m2/5*$d} mana over $d.  Must remain seated while eating.", ua = "Відновлює ${$m3/5*$d} здоров'я та ${$m2/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% Health and Mana every $t1 seconds for $d1. Must remain seated while eating.", ua = "Відновлює $s1% здоров'я та мани кожні $t1 секунд протягом $d1. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*$d} mana over $d.  Must remain seated while eating.", ua = "Відновлює ${$m2/5*$d} мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% of your health per second for $d.  Must remain seated while eating. \n\n\n\nWarning: Extremely decadent!", ua = "Відновлює $s1% вашого здоров'я щосекунди протягом $d.  Під час їжі потрібно лишатися сидячи. \n\n\n\nПопередження: надзвичайно розкішно!" },
    { en = "Restores $192002o1 health and $192002o2 mana over $192002d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will transform into a pig-headed beastman.", ua = "Відновлює $192002o1 здоров'я та $192002o2 мани протягом $192002d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то перетворитеся на звіролюда зі свинячою головою." },
    { en = "Set out a Sanguinated Feast to feed up to 35 people in your raid or party!\n\n\n\nRestores $257427o1 health and $257427o2 mana over $257427d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $259456s1 in a stat for $259456d.", ua = "Виставте Кривавий Бенкет, щоб нагодувати до 35 осіб у вашому рейді чи групі!\n\n\n\nВідновлює $257427o1 здоров'я та $257427o2 мани протягом $257427d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $259456s1 до характеристики на $259456d." },
    { en = "Restores $257427o1 health and $257427o2 mana over $257427d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $290467s1 in a stat for $290467d.", ua = "Відновлює $257427o1 здоров'я та $257427o2 мани протягом $257427d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими й отримаєте $290467s1 до однієї характеристики на $290467d." },
    { en = "Set out a F.E.A.S.T. to feed up to 35 people in your raid or party!\n\n\n\nRestores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $297116s1 in a stat for $297116d.", ua = "Влаштуйте Б.Е.Н.К.Е.Т., щоб нагодувати до 35 учасників вашого рейду чи групи!\n\n\n\nВідновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $297116s1 до характеристики на $297116d." },
    { en = "Set out a Surprisingly Palatable Feast to feed up to 35 people in your raid or party!\n\n\n\nRestores $327786o1 health and $327786o2 mana over $257428d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $327701s1 in a stat for $327701d.", ua = "Виставте Напрочуд Смачний Бенкет, щоб нагодувати до 35 осіб у вашому рейді чи групі!\n\n\n\nВідновлює $327786o1 здоров'я та $327786o2 мани протягом $257428d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $327701s1 до характеристики на $327701d." },
    { en = "Set out a Feast of Gluttonous Hedonism to feed up to 35 people in your raid or party!\n\n\n\nRestores $327786o1 health and $327786o2 mana over $327786d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $327706s1 in a stat for $327706d.", ua = "Влаштуйте Бенкет ненажерливого гедонізму, щоб нагодувати до 35 учасників вашого рейду чи групи!\n\n\n\nВідновлює $327786o1 здоров'я та $327786o2 мани протягом $327786d.  Під час їжі потрібно лишатися сидячи.  Якщо ви їстимете щонайменше 10 секунд, то станете наїденим і отримаєте $327706s1 до характеристики на $327706d." },
    { en = "Restores ${$m1/5*$d} health over $d.  Must remain seated while eating.", ua = "Відновлює ${$m1/5*$d} здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed.\n\n\n\nWhile well fed, you assume the form of a K'thir, reducing the range that enemies will attack you while in a Vision of N'Zoth for $316243d.", ua = "Відновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими.\n\n\n\nПоки ви наїдені, ви на $316243d набуваєте подоби к'тіра, що зменшує відстань, з якої вороги нападатимуть на вас у Видінні Н'Зота." },
    { en = "Restores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed.\n\n\n\nWhile well fed, increase movement speed by $316330s% while in a Vision of N'Zoth.", ua = "Відновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими.\n\n\n\nПоки ви наїдені, ваша швидкість пересування збільшується на $316330s%, доки ви у Видінні Н'Зота." },
    { en = "Restores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating. \n\n\n\nIf you spend at least 10 seconds eating, instantly restore $316319s Sanity.", ua = "Відновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d. Під час їжі потрібно лишатися сидячи. \n\n\n\nЯкщо ви їстимете щонайменше 10 секунд, миттєво відновлює $316319s розсудку." },
    { en = "Restores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed. \n\n\n\nWhile well fed, reduce the duration of incoming crowd control effects by $316342s% while in a Vision of N'Zoth.", ua = "Відновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими.\n\n\n\nПоки ви наїдені, тривалість накладених на вас ефектів контролю зменшується на $316342s% у Видінні Н'Зота." },
    { en = "Restores $297098o1 health and $297098o2 mana over $297098d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed.\n\n\n\nWhile well fed, regenerate $316335s% of your max health per sec while in a Vision of N'Zoth.", ua = "Відновлює $297098o1 здоров'я та $297098o2 мани протягом $297098d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, то станете наїденими.\n\n\n\nПоки ви наїдені, ви щосекунди відновлюєте $316335s% свого максимального здоров'я, доки ви у Видінні Н'Зота." },
    { en = "Set out an Empyrean Refreshment to feed up to 35 people in your raid or party!\n\n\n\nRestores $308433o1 health and $308433o2 mana over $308433d.  Must remain seated while eating.", ua = "Виставте Емпірейське Частування, щоб нагодувати до 35 осіб у вашому рейді чи групі!\n\n\n\nВідновлює $308433o1 здоров'я та $308433o2 мани протягом $308433d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $327786o1 health $327786o2 and mana over $257428d. If you spend at least 10 seconds eating you will become Well Fed, increasing Versatility for $347173d.  Must remain seated while eating.", ua = "Відновлює $327786o1 здоров'я та $327786o2 мани протягом $257428d. Якщо ви їстимете щонайменше 10 секунд, ви станете Наїденим, що підвищує Універсальність на $347173d. Під час їжі потрібно лишатися сидячи." },
    { en = "Set out a Kettle of Stone Soup, ready to fill with delicious ingredients. Finish it to provide 70 servings to your raid or party!\n\n\n\nOnce complete, restores $327786o1 health and $327786o2 mana over $327786d.  Must remain seated while eating.  If you spend at least 10 seconds eating you will become well fed and gain $327706s1 in a stat for $327706d.", ua = "Виставте Казан Кам'яної Юшки, готовий до наповнення смачними інгредієнтами. Завершіть страву, щоб почастувати ваш рейд чи групу 70 порціями!\n\n\n\nПісля завершення відновлює $327786o1 здоров'я та $327786o2 мани протягом $327786d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете наїденим і отримаєте $327706s1 до характеристики на $327706d." },
    { en = "Restores ${$m1/5*$d} health over $d.\n\nMust remain seated while eating.", ua = "Відновлює ${$m1/5*$d} здоров'я протягом $d.\n\nПід час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*$d} mana over $d.\n\nMust remain seated while drinking.", ua = "Відновлює ${$m2/5*$d} мани протягом $d.\n\nПід час пиття потрібно лишатися сидячи." },
    { en = "Restores $o1% Mana over $d. Must remain seated while drinking. Each sip has a chance to transform you into a cute and cuddly creature!", ua = "Відновлює $o1% мани протягом $d. Під час пиття потрібно лишатися сидячи. Кожен ковток може перетворити вас на милу пухнасту істоту!" },
    { en = "Restores $s1 health over $382477d1. Must remain seated while eating. If you spend at least 10 seconds eating you will become fed and gain 2 Stamina for [BUFF DURATION]", ua = "Відновлює $s1 здоров'я протягом $382477d1. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете нагодованим і отримаєте 2 Витривалості на [BUFF DURATION]" },
    { en = "Restores $s1 health over $d1. Must remain seated while eating. If you spend at least 10 seconds eating you will become fed and gain 2 Stamina for [BUFF DURATION]", ua = "Відновлює $s1 здоров'я протягом $d1. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви станете нагодованим і отримаєте 2 Витривалості на [BUFF DURATION]" },
    { en = "Set out a Growing Hoard of Draconic Delicacies, ready to fill with delicious prepared meals and excess ingredients. Finish it to provide a great feast for everyone to enjoy!\n\n\n\nOnce complete, restores ${$369166m1/5*$369166d} health and ${$369166m2/5*$369166d} mana over $369166d. Must remain seated while eating. If you spend at least $383202t2 seconds eating, you become well fed and gain $396092s1 primary stat for $396092d.", ua = "Влаштуйте Зростаючу скарбницю драконічних делікатесів, готову до наповнення смачними стравами й надлишковими інгредієнтами. Завершіть її, щоб влаштувати чудовий бенкет для всіх!\n\n\n\nПісля завершення відновлює ${$369166m1/5*$369166d} здоров'я та ${$369166m2/5*$369166d} мани протягом $369166d. Під час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше $383202t2 секунд, то станете наїденим і отримаєте $396092s1 основної характеристики на $396092d." },
    { en = "Restores $s1% of your health per second for $d.  Must remain seated while eating.\n\n\n\nNote: May cause excitability.", ua = "Відновлює $s1% вашого здоров'я щосекунди протягом $d.  Під час їжі потрібно лишатися сидячи.\n\n\n\nПримітка: може спричинити збудженість." },
    { en = "$@spelldesc369166\n\nMust remain seated while eating. If you spend at least 10 seconds eating you will move more quickly while in the Azure Span.", ua = "$@spelldesc369166\n\nПід час їжі потрібно лишатися сидячи. Якщо ви їстимете щонайменше 10 секунд, ви рухатиметеся швидше в Лазуровому Просторі." },
    { en = "losing ${$m1*$d}% of your maximum health over $d.  Must remain seated while eating.", ua = "втрачаючи ${$m1*$d}% вашого максимального здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $o1% health over $d. Must remain seated while eating.", ua = "Відновлює $o1% здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $o1% mana over $d. Must remain seated while drinking.", ua = "Відновлює $o1% мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Restores ${$m2/5*$d} mana over $d. Must remain seated while drinking.\n\n\n\n$@spellicon456575 $@spellname456575\n\nIf you spend at least 10 seconds drinking you will gain $462148s2 Speed and the ability to walk on water for $462148d.", ua = "Відновлює ${$m2/5*$d} мани протягом $d. Під час пиття потрібно лишатися сидячи.\n\n\n\n$@spellicon456575 $@spellname456575\n\nЯкщо ви питимете щонайменше 10 секунд, ви отримаєте $462148s2 швидкості та здатність ходити по воді протягом $462148d." },
    { en = "Restores ${$m1/5*$d} health and mana over $d. Must remain seated while eating.", ua = "Відновлює ${$m1/5*$d} здоров'я та мани протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores ${$m1/5*$d} health and mana over $d. Must remain seated while drinking.", ua = "Відновлює ${$m1/5*$d} здоров'я та мани протягом $d. Під час пиття потрібно лишатися сидячи." },
    { en = "Lose ${$m1*$d}% of your maximum health over $d.  Must remain seated while eating.", ua = "Ви втрачаєте ${$m1*$d}% максимального здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% of your maximum health every second over $d. Must remain seated while eating.", ua = "Відновлює $s1% вашого максимального здоров'я щосекунди протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores $s1% health over $d. Must remain seated while eating.", ua = "Відновлює $s1% здоров'я протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Restores up to $s1% of your maximum health and mana every second over $d. Must remain seated while eating.", ua = "Відновлює до $s1% максимального здоров'я та мани щосекунди протягом $d. Під час їжі потрібно лишатися сидячи." },
    { en = "Follow Myrrit underground, becoming hidden from enemies and able to dig up treasure.", ua = "Прямуй за Мірритом під землю: ти сховаєшся від ворогів і зможеш викопувати скарби." },
    { en = "Have Myrrit sniff for unique smells.", ua = "Нехай Міррит винюхує унікальні запахи." },
    { en = "Attaches an Icespine Stinger Bait to your fishing pole for $d.", ua = "Чіпляє наживку з жала льодошипа до вашої вудки на $d." },
    { en = "Calls down a tremendous lightning strike that deals $s1 Nature damage to your target and ${$m1*$m2/100} Nature damage to enemies within $A1 yds of your target. Damage reduced beyond $s3 targets.$?a383303[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed and damage.|r]?a187880[\n\n\n\n|cFFFFFFFFConsumes Maelstrom Weapon for increased cast speed.|r][]", ua = "Прикликає могутній удар блискавки, що завдає $s1 шкоди від сил природи вашій цілі та ${$m1*$m2/100} шкоди від сил природи ворогам у межах $A1 ярдів від неї. Шкода зменшується, якщо цілей більше за $s3.$?a383303[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання та шкоди.|r]?a187880[\n\n\n\n|cFFFFFFFFСпоживає Зброю виру для збільшення швидкості прочитання.|r][]" },
    { en = "When activated, regenerates $20578s1% of total health and mana every $20578t1 sec for $20578d. Only works on Humanoid or Undead corpses within $a1 yds. Any movement, action, or damage taken while Cannibalizing will cancel the effect.", ua = "Після активації відновлює $20578s1% загального здоров'я та мани кожні $20578t1 сек. протягом $20578d. Діє лише на трупи гуманоїдів чи нежиті в межах $a1 ярдів. Будь-який рух, дія чи отримана шкода під час «Канібалізму» скасовує ефект." },
    { en = "Instantly restart the current race.", ua = "Миттєво перезапускає поточні перегони." },
    { en = "Teaches the blueprints needed to build level one versions of all small, medium and large buildings, excluding the salvage yard.", ua = "Навчає креслень, потрібних для зведення версій першого рівня всіх малих, середніх і великих будівель, за винятком Двору утилю." },
    { en = "Finish learning more about the story and continue experiencing the tale.", ua = "Дізнайся більше про історію та продовжуй переживати цю оповідь." },
    { en = "Killing Alliance players grants you $m1 bonus Honor. Killing Alliance Assassins grants $m2 bonus Honor.\n\n\n\nAfter $m3 Alliance kills without dying, you will graduate to a Horde Assassin, increasing your damage and healing by $264314m1%.", ua = "Вбивство гравців Альянсу дає вам $m1 бонусної честі. Вбивство Вбивць Альянсу дає $m2 бонусної честі.\n\n\n\nПісля $m3 вбивств прибічників Альянсу без власної смерті ви станете Вбивцею Орди, а ваша шкода та зцілення збільшаться на $264314m1%." },
    { en = "Increases your haste by $s1% for $d.", ua = "Збільшує твій поспіх на $s1% протягом $d." },
    { en = "Detonate the bomb currently attached to you.", ua = "Підриває бомбу, що зараз прикріплена до вас." },
    { en = "$?ml[Supplies and Gold rewards from world quests increased by $w4%.][Experience gained from killing monsters and completing quests increased by $w1%.]", ua = "$?ml[Нагороди припасами та золотом за світові завдання збільшено на $w4%.][Досвід, отриманий за вбивство монстрів і виконання завдань, збільшено на $w1%.]" },
    { en = "Use to identify and catalog relics and runes for the Azerothian Archives.", ua = "Використовуйте, щоб ідентифікувати й каталогізувати реліквії та руни для Архівів Азерота." },
    { en = "Increases critical strike damage by $s1%. Increases critical strike healing by $s2%.", ua = "Збільшує шкоду критичних ударів на $s1%. Збільшує зцілення критичних ударів на $s2%." },
    { en = "Perform a ritualistic dance to teleport to the Cradle. Casting this spell while near a world tree's roots within Harandar allows you to travel to that world tree.", ua = "Виконай ритуальний танець, щоб телепортуватися до Колиски. Якщо застосувати це закляття поблизу коренів Світового Дерева в Гарандарі, зможеш перенестися до того Світового Дерева." },
    { en = "Increases experience gained from killing monsters and completing quests by $s1%.\n\n\n\nCompleting Timewalking dungeons  refreshes the duration.", ua = "Збільшує досвід, отримуваний за вбивство монстрів і виконання завдань, на $s1%.\n\n\n\nПроходження підземель Мандрів у часі поновлює тривалість." },
    { en = "Allows a jewelcrafter to make jewelry and cut gems. Requires precious gems and metals gathered with the Mining skill.", ua = "Дозволяє ювеліру виготовляти прикраси та гранувати самоцвіти. Потребує коштовних самоцвітів і металів, які видобувають навичкою Гірництва." },
    { en = "Occasionally emitting spores of sleeping gas.", ua = "Час від часу випускає спори зі снодійним газом." },
    { en = "Allows an enchanter to enchant basic items. Requires Dusts and Essences found by disenchanting magic items.", ua = "Дозволяє зачарувальнику зачаровувати базові предмети. Потребує пилу та есенцій, які здобувають розчаклуванням магічних предметів." },
    { en = "Creatures may spawn with additional abilities.", ua = "Істоти можуть з'являтися з додатковими здібностями." },
    { en = "Take a whiff of the pomander, increasing your movement speed by $s1% and healing for $328490s1% of your maximum health every $t2 seconds for $d.\n\n\n\nOnly usable in the Shadowlands.", ua = "Вдихни аромат запашної кульки — це збільшить твою швидкість пересування на $s1% і зцілюватиме тебе на $328490s1% максимального здоров'я кожні $t2 сек. протягом $d.\n\n\n\nМожна використати лише в Тіньокраї." },
    { en = "Stop taking photos.", ua = "Припиняє фотографування." },
    { en = "Nearby High-Value Beasts will appear on the minimap and be visibly highlighted.", ua = "Цінні звірі поблизу з'являтимуться на мінікарті й будуть помітно підсвічені." },
    { en = "Your Remorseless Winter and Chains of Ice apply Deathchill, rooting the target in place for 4 sec.\n\n\n\n|CFFFFFFFFRemorseless Winter|R \n\nAll targets within $m1 yards are afflicted with Deathchill when Remorseless Winter is cast.\n\n\n\n|CFFFFFFFFChains of Ice|R\n\nWhen you Chains of Ice a target already afflicted by your Chains of Ice they will be afflicted by Deathchill.", ua = "Ваші «Невблаганна зима» та «Крижані ланцюги» накладають «Смертельний холод», що прикорінює ціль на місці на 4 сек.\n\n\n\n|CFFFFFFFFНевблаганна зима|R \n\nКоли ви творите «Невблаганну зиму», усі цілі в радіусі $m1 м уражаються «Смертельним холодом».\n\n\n\n|CFFFFFFFFКрижані ланцюги|R\n\nКоли ви накладаєте «Крижані ланцюги» на ціль, що вже перебуває під дією ваших «Крижаних ланцюгів», вона уражається «Смертельним холодом»." },
    { en = "Investigate the area, and tell Kaiana to absorb the nearby information.", ua = "Досліди місцевість і скажи Каяні увібрати навколишню інформацію." },
    { en = "Summons a totem at your feet that will redirect all harmful spells cast within $8178A1 yards on a nearby party or raid member to itself. Will not redirect area of effect spells. Lasts $d.", ua = "Прикликає до ваших ніг тотем, що перенаправляє на себе всі шкідливі закляття, спрямовані на членів групи чи рейду поблизу в радіусі $8178A1 ярдів. Не перенаправляє закляття з дією по площі. Діє $d." },
    { en = "Step through the shadows to appear behind your target and gain $s2% increased movement speed for $d.$?s137035|s137037[\n\n\n\nIf you already know $@spellname36554, instead gain $394931s1 additional $Lcharge:charges; of $@spellname36554.][]", ua = "Ступаєш крізь тіні, щоб з'явитися позаду своєї цілі, й отримуєш прискорення руху на $s2% на $d.$?s137035|s137037[\n\n\n\nЯкщо ти вже знаєш «$@spellname36554», натомість отримуєш іще $394931s1 $Lcharge:charges; закляття «$@spellname36554».][]" },
    { en = "Command Ooz to consume the corpse.", ua = "Наказує Оозу поглинути труп." },
    { en = "Investigate the area, and tell your familiar to absorb the nearby information.", ua = "Досліди місцевість і скажи своєму фамільярові увібрати навколишню інформацію." },
    { en = "In Delves, until you complete your next one, you are granted an additonal life.", ua = "У Глибинах тобі надається додаткове життя, доки ти не завершиш наступну Глибину." },
    { en = "Deal $s1% of their total health to ALL creatures within $a1 yards.\n\nReduced effectiveness against bosses.", ua = "Завдає ВСІМ істотам у радіусі $a1 м шкоди в розмірі $s1% їхнього загального здоров'я.\n\nЗнижена ефективність проти босів." },
    { en = "$?s137050[Fury ][]Warriors can use the following weapons$?s137050[ and dual wield one-handed or two-handed weapons][]:\n\n\n\nAxes\n\nDaggers\n\nFist Weapons\n\nMaces\n\nPolearms\n\nStaves\n\nSwords", ua = "Воїни $?s137050[спеціалізації «Лють» ][]можуть використовувати таку зброю$?s137050[ й битися парною зброєю — одноручною чи дворучною][]:\n\n\n\nСокири\n\nКинджали\n\nКулачна зброя\n\nБулави\n\nДревкова зброя\n\nПатериці\n\nМечі" },
    { en = "Drop stock fish into the $?a390664[lava][water] to restock fishing hole.", ua = "Кидає рибу із запасу $?a390664[у лаву][у воду], щоб поповнити рибне місце." },
    { en = "Summons a Ring of Fire for $353103d at the target location. Enemies entering the ring are disoriented and burn for ${$353084s2*3}% of their total health over $353084d.", ua = "Прикликає Вогняне Кільце у вказаному місці на $353103d. Вороги, що входять у кільце, дезорієнтуються та горять, втрачаючи ${$353084s2*3}% свого загального здоров'я протягом $353084d." },
    { en = "Removes $@spellname1285392.", ua = "Знімає $@spellname1285392." },
    { en = "Access info about skinning skills, the types of creatures that can be skinned, and specializations. Also manage your skinning equipment.", ua = "Доступ до інформації про навички білування, види істот, яких можна білувати, та спеціалізації. Також дозволяє керувати вашим спорядженням для білування." },
    { en = "Increases the chance for Jawless Skulkers for $d.", ua = "Збільшує шанс упіймати Безщелепних Скрадачів протягом $d." },
    { en = "Reveal maps of regions that have been fully explored by a member of your Warband.", ua = "Відкриває карти регіонів, які повністю дослідив хтось із членів твоєї бойової ватаги." },
    { en = "Increases the remaining stock of fish by $s0.", ua = "Збільшує залишковий запас риби на $s0." },
    { en = "Transmutable into powerful equipment upon defeating powerful foes in Midnight Season 1 raids or completing Mythic+ dungeons, Bountiful Delves and Prey Hunts on Nightmare difficulty.", ua = "Перетворюється на потужне спорядження після перемоги над могутніми ворогами в рейдах 1-го сезону Опівночі або проходження підземель Міфік+, Щедрих Глибин і полювань на здобич на складності «Жахіття»." },
    { en = "Summons a personal portal directly to your Warband Bank, allowing withdrawals and deposits for $68054d.", ua = "Прикликає особистий портал прямо до банку вашого бойового загону, дозволяючи протягом $68054d робити внески та забирати вкладене." },
    { en = "Tranform into an adult and gain improved speed. Spends all remaining Vigor. For every extra Vigor spent, gain an additional $d time in this form.", ua = "Перетворює на дорослу особину та підвищує швидкість. Витрачає всю решту Снаги. За кожну додатково витрачену Снагу тривалість перебування в цій формі збільшується на $d." },
    { en = "Allows you to comprehend the common language of the opposite faction for $d.", ua = "Дозволяє вам розуміти основну мову ворожої фракції протягом $d." },
    { en = "Allows an engineer to make basic contraptions up to a maximum potential skill of 100.", ua = "Дозволяє інженеру виготовляти базові пристрої до максимального потенційного рівня вміння 100." },
    { en = "Experience gains from killing Aberrations, Beasts, and Elementals increased by $s1%. \n\n\n\nDamage dealt to Aberrations, Beasts, and Elementals increased by $s2%.", ua = "Досвід за вбивство аберацій, звірів та елементалів збільшено на $s1%. \n\n\n\nШкоду, завдану абераціям, звірам та елементалям, збільшено на $s2%." },
    { en = "Wait for it...", ua = "Зараз-зараз..." },
    { en = "Release bolts of magical fire at any nearby flammable objects.", ua = "Випускає заряди магічного вогню в усі займисті об'єкти поблизу." },
    { en = "Creates a cloud of thick smoke in an $m2 yard radius around the Rogue for $d. Enemies are unable to target into or out of the smoke cloud.", ua = "Створює хмару густого диму радіусом $m2 м навколо розбійника на $d. Вороги не можуть обирати ціль крізь хмару диму — ні в неї, ні з неї." },
    { en = "Unlocks a new djaradin legend to listen to.", ua = "Відкриває нову джарадинську легенду, яку можна послухати." },
    { en = "Change the contents of your Bag of Tricks. Now where did you put that...?", ua = "Змінює вміст вашої «Торби хитрощів». Ну й куди ж ви це поділи...?" },
    { en = "Become one with a powerful being of Zul'Aman's past.", ua = "Злийтеся воєдино з могутньою істотою з минулого Зул'Аману." },
    { en = "When you take damage, you have a chance to gain one stack of Crystallizing Anima, decreasing the damage you take by $335068s1%, lasting for $335068d. Taking damage at $335068u stacks has a chance to freeze nearby enemies for $335074d, increasing damage they take by $335074s2%.", ua = "Коли ви отримуєте шкоду, є шанс отримати один заряд «Кристалізації аніми», що зменшує отримувану вами шкоду на $335068s1% і триває $335068d. Отримання шкоди за $335068u зарядів має шанс заморозити ворогів поблизу на $335074d, збільшуючи отримувану ними шкоду на $335074s2%." },
    { en = "When your Frost Nova or Water Elemental's Freeze is dispelled or removed, become immune to snares for $407582d. \n\n\n\nThis effect can only occur once every $407648d.", ua = "Коли ваша «Крижана нова» або «Заморозка» водяного елементаля розвіюється чи знімається, ви стаєте несприйнятливими до ефектів сповільнення на $407582d. \n\n\n\nЦей ефект може спрацьовувати лише раз на $407648d." },
    { en = "Command powerful thorns to assault $1238474i enemies and heal $1238467i allies within $a1 yds of the target area.\n\n\n\nEnemies are dealt $<damage> Nature damage and an additional ${$<damageovertime>*($1238474d/$1238474t2)} Nature damage over $1238474d. Allies are healed for $<healing> and an additional ${$<healingovertime>*($1238467d/$1238467t2)} over $1238467d.", ua = "Наказує могутнім тернам атакувати $1238474i ворогів і зцілювати $1238467i союзників у радіусі $a1 м від цільової області.\n\n\n\nВороги дістають $<damage> шкоди від сил природи та додатково ${$<damageovertime>*($1238474d/$1238474t2)} шкоди від сил природи протягом $1238474d. Союзники зцілюються на $<healing> і додатково на ${$<healingovertime>*($1238467d/$1238467t2)} протягом $1238467d." },
    { en = "Unlock powers at the Vindicaar's Matrix Core to use while on Argus.", ua = "Відкрийте сили біля Матричного ядра «Віндікаара», щоб користуватися ними на Аргусі." },
    { en = "Cast a spell from the scribblings of a mad cult member.", ua = "Творить закляття за кривульками божевільної культистки." },
    { en = "Allows for players to gather fish from bodies of water and fishing nodes up to a skill of 175.", ua = "Дозволяє гравцям виловлювати рибу з водойм і рибних косяків до рівня вміння 175." },
    { en = "Take pictures of picturesque landscape.", ua = "Сфотографуй мальовничий краєвид." },
    { en = "Activate at a Temporal Nexus to glimpse moments in the past.", ua = "Активуйте біля часового нексуса, щоб зазирнути в миті минулого." },
    { en = "Unlock the title Intrepid Explorer for your Warband.", ua = "Відкриває титул «Безстрашний Дослідник» для вашого загону." },
    { en = "Automatically shoots the target until cancelled.", ua = "Автоматично стріляє в ціль, доки не буде скасовано." },
    { en = "Your body and spirit swap locations.", ua = "Ваше тіло і дух міняються місцями." },
    { en = "Receive a Worldsoul Satchel that contains several pieces of equipment.", ua = "Отримай Торбу Світодуші, що містить кілька предметів спорядження." },
    { en = "Directs your drogbar helper to dig in the target location.", ua = "Спрямовує вашого помічника-дроґбара копати у вказаному місці." },
    { en = "View options where you could go next.\n\n\n\nYou can rerun the Catch Up Experience at any time from your Adventure Guide.", ua = "Перегляньте варіанти, куди можна вирушити далі.\n\n\n\nВи можете будь-коли повторити Швидке Ознайомлення через свій Путівник пригод." },
    { en = "Unlocks access to the Mine. In addition, you may now mine mineral nodes within the Garrison.\n\n\n\n$@garrbuilding61", ua = "Відкриває доступ до Шахти. Крім того, тепер ви можете видобувати мінеральні жили в гарнізоні.\n\n\n\n$@garrbuilding61" },
    { en = "Spray Icicle Brew on a Charred Hornspike and hit it as hard as you can!", ua = "Розпорошіть Бурулькове Вариво на обвугленого рогошпиля та вдарте його щосили!" },
    { en = "Activate to find relics that match the calibrated temporal frequency.", ua = "Активуйте, щоб знайти реліквії, які відповідають відкаліброваній часовій частоті." },
    { en = "Calls forth Pepe to ride on a sleigh as you adventure together.", ua = "Прикликає Пепе, щоб їхав на санях, поки ви разом мандруєте." },
    { en = "Increases the chance for Abyssal Gulper Eel for $d.", ua = "Збільшує шанс упіймати Безодневого Вугра-Ковтача протягом $d." },
    { en = "Pull your chosen trick from the bag and use it on target enemy or ally. Enemies take $<damage> damage and are snared by $315084s2% for $315084d, while allies are healed for $<healing> and move $317829s2% faster for $317829d.", ua = "Витягни з торби обраний трюк і застосуй його до цільового ворога чи союзника. Вороги зазнають $<damage> шкоди та отримують сповільнення на $315084s2% тривалістю $315084d, а союзники зцілюються на $<healing> і протягом $317829d рухаються на $317829s2% швидше." },
    { en = "Deals $<damage> Arcane damage to nearby enemies and reduces their movement speed by $260369s1%. Lasts $260369d.", ua = "Завдає $<damage> арканної шкоди ворогам поблизу та зменшує їхню швидкість пересування на $260369s1%. Триває $260369d." },
    { en = "Your next Conflagrate or Shadowburn will critically strike and your critical strike chance will increase its critical strike damage.", ua = "Наступний вжиток «Займання» чи «Опіку тіні» завдасть критичного удару, а ваш шанс критичного удару збільшить його критичну шкоду." },
    { en = "Conjure a Shadow Rift at the target location lasting $d. Enemy players within the rift when it expires are teleported to your Demonic Circle.\n\n\n\nMust be within $s2 yds of your Demonic Circle to cast.", ua = "Створює Тіньовий розлом у вказаному місці, що триває $d. Ворожі гравці, які перебувають у розломі, коли той зникає, телепортуються до вашого Демонічного кола.\n\n\n\nДля творення потрібно бути в межах $s2 м від вашого Демонічного кола." },
    { en = "Periodically sprouts patches of springcap mushrooms underneath random targets that last $1297756d. \n\n\n\nUpon contact with a player, inflicts $1297757s1 Nature damage to the triggering player and knocks them away.", ua = "Час від часу під випадковими цілями виростають скупчення грибів-стрибунців, що тримаються $1297756d. \n\n\n\nТоркнувшись гравця, гриби завдають йому $1297757s1 шкоди від природи й відкидають його геть." },
    { en = "A creature cannot be captured until all of their Scales have been removed.", ua = "Істоту не можна впіймати, доки з неї не знято всю луску." },
    { en = "Bound backward away from your enemies.", ua = "Стрибок назад, що віддаляє вас від ворогів." },
    { en = "Only available within Undermine.", ua = "Доступно лише в межах Андермайну." },
    { en = "$?a137039[Summons a totem at the target location that maintains Healing Rain with $455630s3% increased effectiveness for $d.\n\n\n\n|cFFFFFFFFReplaces Healing Rain.|r][Summons a totem at the target location that creates a Tremor immediately and every $455593t1 sec for $455622s1 Flamestrike damage. Damage reduced beyond $455622s2 targets. Lasts $d.]", ua = "$?a137039[Прикликає тотем у вказаному місці, що підтримує «Цілющий дощ» зі збільшеною на $455630s3% ефективністю протягом $d.\n\n\n\n|cFFFFFFFFЗамінює «Цілющий дощ».|r][Прикликає тотем у вказаному місці, що створює Здригання одразу й далі кожні $455593t1 сек., завдаючи $455622s1 шкоди від Удару полум'я. Шкода зменшується після $455622s2 цілей. Триває $d.]" },
    { en = "Removes all stun effects. $?s195710[This effect shares a 90 sec cooldown with other similar effects.][]", ua = "Знімає всі ефекти оглушення. $?s195710[У цього ефекту спільне перезарядження 90 сек з іншими подібними ефектами.][]" },
    { en = "Summons a hawk to circle the target area, attacking all targets within 10 yards over the next $d.", ua = "Прикликає яструба, що кружлятиме над вказаною ділянкою, атакуючи всі цілі в межах 10 ярдів протягом наступних $d." },
    { en = "Command your Eagle to retrieve the loot from a nearby corpse.", ua = "Наказує вашому орлові забрати здобич із трупа поблизу." },
    { en = "Helps put out fire.", ua = "Допомагає гасити вогонь." },
    { en = "Removes any Charm, Fear and Sleep effect. $?s195710[This effect shares a 30 sec cooldown with other similar effects.][]", ua = "Знімає будь-які ефекти зачарування, страху та сну. $?s195710[У цього ефекту спільне перезарядження 30 сек з іншими подібними ефектами.][]" },
    { en = "Teleport to the entrance to Neltharion's Lair.", ua = "Телепортує до входу в Лігво Нелтаріона." },
    { en = "Call upon the forces of your garrison to assist you for $d.", ua = "Прикликає сили вашого гарнізону на допомогу на $d." },
    { en = "Calls forth Pepe to ride on your head as you adventure together.", ua = "Прикликає Пепе, щоб сидів у тебе на голові, поки ви разом мандруєте." },
    { en = "Allows for players to gather fish from bodies of water and fishing nodes up to a skill of 75.", ua = "Дозволяє гравцям виловлювати рибу з водойм і рибних косяків до рівня вміння 75." },
    { en = "Your spells and abilities have a chance to summon a gorm to aid you in combat.\n\n\n\nGorm will only come to your side in Ardenweald.", ua = "Ваші закляття та здібності мають шанс прикликати ґорма, який допомагатиме вам у бою.\n\n\n\nҐорми приходять на поміч лише в Арденвельді." },
    { en = "Critical strikes deal double damage and may knock your target into the air.", ua = "Критичні удари завдають подвійної шкоди й можуть підкинути вашу ціль у повітря." },
    { en = "Remove the wagon that covers a farming plot at Sunsong Ranch.", ua = "Прибирає віз, що накриває грядку на Ранчо Сонячної Пісні." },
    { en = "Feel pretty.", ua = "Відчуй свою красу." },
    { en = "Become trapped under a pile of rubble.", ua = "Ви опинилися в пастці під купою уламків." },
    { en = "On Looted: Chance to apply movement-triggered area-damage to your target as you attack it.\n\n\n\nLasts $d1 and persists through death.\n\n\n\n|cnYELLOW_FONT_COLOR:This item is consumed immediately.|r", ua = "Після підбирання здобичі: шанс під час атак накласти на ціль шкоду по області, що спрацьовує від руху.\n\n\n\nТриває $d1 і зберігає дію після смерті.\n\n\n\n|cnYELLOW_FONT_COLOR:Цей предмет споживається одразу.|r" },
    { en = "Throw a Striped Melon at the ground.", ua = "Кидає Смугасту Диню на землю." },
    { en = "Battle pet experience gained is increased by $s1%.", ua = "Досвід, який отримують бойові улюбленці, збільшується на $s1%." },
    { en = "Otherworldly screeching in The Beastwarrens occasionally drives the player to madness, fearing them and inflicting Shadow damage every $336974t3 sec for $336974d.", ua = "Потойбічний вереск у Звіриних Норах час від часу доводить гравця до безумства, вселяючи в нього жах і завдаючи шкоди від тіні кожні $336974t3 с протягом $336974d." },
    { en = "Increases experience gained from killing monsters and completing quests by $s1%.\n\n\n\nCompleting Timewalking dungeons increases the effect and refreshes the duration.\n\n\n\nUpon reaching $u applications, transforms to $@spellname1229050, increasing that effect to $1229050s1%.", ua = "Збільшує досвід, отримуваний за вбивство монстрів і виконання завдань, на $s1%.\n\n\n\nПроходження підземель Мандрів у часі посилює ефект і поновлює тривалість.\n\n\n\nПісля досягнення $u застосувань перетворюється на $@spellname1229050, збільшуючи цей ефект до $1229050s1%." },
    { en = "$?PC154828[|cnIQ1:- Basic Dive Suit|R][]$?PC154829[|cnIQ2:- Reinforced Joints Suit|R][]$?PC154830[|cnIQ3:- Depth-Greased Suit|R][]$?PC154832[|cnIQ4:- Pahk Trench Fins Suit|R][]\n\nSwim Speed +$w1%\n\n$?PC154836[\n\n|cnIQ1:- Basic Breath Tank|R\n\nMax Oxygen $1224700m6 units\n\n][]$?PC154835[\n\n|cnIQ2:- Depthdiver's Used Tank|R\n\nMax Oxygen $1271613m6 units\n\n][]$?PC154834[\n\n|cnIQ3:- Fathom-Tested Tank|R\n\nMax Oxygen $1271614m6 units\n\n][]$?PC154833[\n\n|cnIQ4:- Nalorakk's Breath Tank|R\n\nMax Oxygen $1271615m6 units\n\n][]$?PC154840[\n\n|cnIQ1:- Basic Bait|R\n\nCommon Fishable Creatures\n\n][]$?PC154839[\n\n|cnIQ2:- Finnow Chum Bait|R\n\nUncommon Fishable Creatures\n\n][]$?PC154838[\n\n|cnIQ3:- Plecofin Bait|R\n\nRare Fishable Creatures\n\n][]$?PC154837[\n\n|cnIQ4:- Murkskimmer Meat Bait|R\n\nEpic Fishable Creatures\n\n][]$?PC159072[\n\n|cnIQ2:- Shallows Net|R\n\nBarbed Crawlers and Thorny Seahorses\n\n][]$?PC152527[\n\n|cnIQ3:- Triple-Thread Net|R\n\nAll Small Creatures\n\n][]$?PC155370[\n\n|cnIQ4:- Pressurized Eyeglass|R\n\nAncient Relics discoverable][]", ua = "$?PC154828[|cnIQ1:- Базовий водолазний костюм|R][]$?PC154829[|cnIQ2:- Костюм із посиленими з'єднаннями|R][]$?PC154830[|cnIQ3:- Костюм із глибинним мастилом|R][]$?PC154832[|cnIQ4:- Костюм із ластами Западини Пака|R][]\n\nШвидкість плавання +$w1%\n\n$?PC154836[\n\n|cnIQ1:- Базовий дихальний балон|R\n\nМаксимум кисню: $1224700m6 од.\n\n][]$?PC154835[\n\n|cnIQ2:- Уживаний балон глибонурця|R\n\nМаксимум кисню: $1271613m6 од.\n\n][]$?PC154834[\n\n|cnIQ3:- Випробуваний глибинами балон|R\n\nМаксимум кисню: $1271614m6 од.\n\n][]$?PC154833[\n\n|cnIQ4:- Дихальний балон Налоракка|R\n\nМаксимум кисню: $1271615m6 од.\n\n][]$?PC154840[\n\n|cnIQ1:- Базова наживка|R\n\nЗвичайні істоти для вилову\n\n][]$?PC154839[\n\n|cnIQ2:- Наживка із січки фінноу|R\n\nНезвичайні істоти для вилову\n\n][]$?PC154838[\n\n|cnIQ3:- Наживка з плекофіна|R\n\nРідкісні істоти для вилову\n\n][]$?PC154837[\n\n|cnIQ4:- Наживка з м'яса мулоплава|R\n\nЕпічні істоти для вилову\n\n][]$?PC159072[\n\n|cnIQ2:- Сітка для мілководдя|R\n\nЗазубрені повзуни та колючі морські коники\n\n][]$?PC152527[\n\n|cnIQ3:- Тринитяна сітка|R\n\nУсі малі істоти\n\n][]$?PC155370[\n\n|cnIQ4:- Герметичний окуляр|R\n\nМожна виявляти прадавні реліквії][]" },
    { en = "Calls in your friend, Gobber, allowing you bank access for $d.", ua = "Прикликає вашого друга Ґоббера, який надає вам доступ до банку на $d." },
    { en = "Aimed Shot may be cast while moving during Aspect of the Cheetah and Aspect of the Cheetah's delayed effect is increased by ${$s1/1000} sec.", ua = "«Прицільний постріл» можна виконувати в русі під час дії «Аспекту гепарда», а відкладений ефект «Аспекту гепарда» триває на ${$s1/1000} сек. довше." },
    { en = "Play the panflute, causing nearby critters to follow you for $d.", ua = "Заграй на флейті Пана, і дрібні звірята поблизу йтимуть за тобою протягом $d." },
    { en = "End the story and exit the Recap, returning to the normal world.", ua = "Завершити історію та вийти з Переказу, повернувшись до звичайного світу." },
    { en = "Devour the life essence of your target, dealing $s1 Cosmic damage. Reduces the cooldown of Reap by ${$1217607s14/1000}.1 sec.\n\n\n\nCastable while moving.\n\n\n\n|CFFffffffGenerates $1288123s1 Fury$?a1215617[ and $1227619s3 soul $Lfragment:fragments;][].|R", ua = "Пожирає життєву есенцію вашої цілі, завдаючи $s1 космічної шкоди. Зменшує перезарядження «Жнив» на ${$1217607s14/1000}.1 сек.\n\n\n\nМожна творити в русі.\n\n\n\n|CFFffffffГенерує $1288123s1 люті$?a1215617[ і $1227619s3 $Lfragment:fragments; душі][].|R" },
    { en = "$?ml&a277253[Gold]?ml[Gold][]$?ml[ rewards from world quests increased by $w4%.][Experience gained from killing monsters and completing quests increased by $w1%.]", ua = "$?ml&a277253[Золоті]?ml[Золоті][]$?ml[ нагороди за світові завдання збільшено на $w4%.][Досвід, отриманий за вбивство монстрів і виконання завдань, збільшено на $w1%.]" },
    { en = "You are infused with the spirit of the wolf, increasing your run speed by $154259s1% outside of combat while in Frostfire Ridge.", ua = "Ви сповнені духом вовка, що збільшує вашу швидкість бігу на $154259s1% поза боєм у Морозовогняному Кряжі." },
    { en = "Causes Holy damage to any creature that strikes a nearby party member. Players may only have one aura on them per paladin at any one time. The aura lasts until cancelled.", ua = "Завдає шкоди Світлом будь-якій істоті, що вдарить члена групи поблизу. На гравцеві одночасно може бути лише одна аура від кожного паладина. Аура діє, доки її не скасовано." },
    { en = "Have Myrrit follow you.", ua = "Нехай Міррит іде за тобою." },
    { en = "A ribbon of affection.", ua = "Стрічка на знак прихильності." },
    { en = "The totem drives players into an insatiable hunger, reducing their maximum health by $s1% for $d. This effect stacks.", ua = "Тотем сповнює гравців ненаситним голодом, зменшуючи їхнє максимальне здоров'я на $s1% протягом $d. Цей ефект накопичується." },
    { en = "Instantly resets the cooldowns of Growth Spurt and Bedtime Rewind. Can only be done in Adult form. Reverts back to Whelp form.", ua = "Миттєво скидає перезарядження «Стрибка росту» та «Повернення до часу сну». Можна зробити лише в дорослій формі. Повертає назад у форму дракончика." },
    { en = "Face a \"Lunker\", then throw!", ua = "Стань обличчям до «здоровила», тоді кидай!" },
    { en = "Increases movement speed by 30%.\n\nStun Immunity.", ua = "Збільшує швидкість пересування на 30%.\n\nІмунітет до оглушення." },
    { en = "Reading the Arcane Tome fills your party with energy increasing haste by $s1% for $d.", ua = "Читання арканного фоліанта наповнює твою групу енергією, що підвищує поспіх на $s1% протягом $d." },
    { en = "Battle for Azeroth reputation gains from combat and quests increased by $s1%.", ua = "Приріст репутації Битви за Азерот від боїв і завдань збільшено на $s1%." },
    { en = "Change your focus to another part of the ship.", ua = "Зосереджує вашу увагу на іншій частині корабля." },
    { en = "Shadowlands reputation gains from combat and quests increased by $s1%.", ua = "Приріст репутації Тіньокраю від боїв і завдань збільшено на $s1%." },
    { en = "Summon Pocopoc to follow you around Zereth Mortis. \n\n\n\nPocopoc can assist you in various tasks at the cost of Pocopoc Energy. \n\n\n\nPocopoc Energy recharges over time.", ua = "Прикликає Покопока, що супроводжуватиме вас у Зерет-Мортісі. \n\n\n\nПокопок може допомагати вам у різних справах коштом Енергії Покопока. \n\n\n\nЕнергія Покопока відновлюється з часом." },
    { en = "Move to the left.", ua = "Рухайся ліворуч." },
    { en = "Track Ancient Mana nodes on the minimap.", ua = "Показує поклади прадавньої мани на мінікарті." },
    { en = "Stabs the target, inflicting $s1 Physical damage and increasing the damage of $@spellname334535 by $s2% for $d.", ua = "Штрикає ціль, завдаючи $s1 фізичної шкоди та збільшуючи шкоду від $@spellname334535 на $s2% протягом $d." },
    { en = "Completing this task frees up space for another net to be placed in this fishing hole today.", ua = "Виконання цього завдання звільняє місце для ще однієї сітки, яку сьогодні можна поставити в цьому рибному місці." },
    { en = "Expose the Disguised Marmot for what he really is.", ua = "Викрий перевдягненого бабака — покажи, хто він насправді." },
    { en = "|CFF20FF20Tier 1|R\n\n\n\nHarvest materials to increase stats.\n\nDeposit materials to upgrade this Blessing.\n\n\n\n+$w1% Movement Speed\n\n+$w2% $pri\n\n+$w3 Pickup Yard Radius\n\n\n\n|CFF9d9d9dContribute more Abundance at an Altar to reach the next tier (Current: $@cdataelem78/1000)|R", ua = "|CFF20FF20Рівень 1|R\n\n\n\nЗбирайте матеріали, щоб підвищити характеристики.\n\nЗдавайте матеріали, щоб покращити це Благословення.\n\n\n\n+$w1% до швидкості пересування\n\n+$w2% $pri\n\n+$w3 м до радіуса підбирання\n\n\n\n|CFF9d9d9dПринесіть більше Рясності до вівтаря, щоб досягти наступного рівня (наразі: $@cdataelem78/1000)|R" },
    { en = "Leave the dive.\n\n\n\nThis will reset any progress if you haven't completed the dive.", ua = "Покинути занурення.\n\n\n\nЯкщо занурення не завершено, весь поступ буде скинуто." },
    { en = "Kick this Wild Prairie Chicken out of here!", ua = "Вижени цю дику лугову курку звідси!" },
    { en = "You dashed from Echo Isles to Silvermoon. Outdoor movement speed increased by $1280079s1% for $d.", ua = "Ви промчали від Островів Відлуння до Сільвермуна. Швидкість пересування на відкритій місцевості збільшено на $1280079s1% протягом $d." },
    { en = "Blink and Shimmer apply Slow at $s2% effectiveness to all enemies you Blink through. For each enemy you Blink through, the cooldown of Blink and Shimmer are reduced by $s3 sec, up to $s4 sec.", ua = "«Блимання» та «Мерехтіння» накладають «Уповільнення» з $s2% ефективності на всіх ворогів, крізь яких ви проходите Блиманням. За кожного ворога, крізь якого ви пройшли Блиманням, перезарядження «Блимання» та «Мерехтіння» зменшується на $s3 сек, аж до $s4 сек." },
    { en = "Time a dodge correctly to avoid being hit by lightning.", ua = "Ухилися в правильний момент, щоб уникнути удару блискавки." },
    { en = "Summon a Voidwalker from the realms beyond.\n\nBinding and controlling summoned creatures will be covered in Summoning 102.", ua = "Прикликає блукача Порожнечі з позамежних світів.\n\nПрив'язування та контроль прикликаних істот розглядатимуться в курсі «Прикликання 102»." },
    { en = "Take a nap and project your dreams into the world around you.", ua = "Подрімай і спроєктуй свої сни у світ довкола себе." },
    { en = "Make like a tree and leaf.", ua = "Прикинься деревом і накивай листям!" },
    { en = "Summons a totem with $s2% of your health at the target location for $d that forms a circuit of electricity that enemies cannot pass through.", ua = "Прикликає у вказаному місці тотем із $s2% вашого здоров'я на $d, що утворює електричне коло, крізь яке вороги не можуть пройти." },
    { en = "Rannan rewards those helping his expedition based on the research objectives completed. You will currently receive $?q75630&we39638 [a |cFFa335ee Indebted Researcher's Scrounged Goods|r]?we39638 [a |cFFa335ee Indebted Researcher's Gift|r]?q75629&we39637 [a |cFF0070dd Thankful Researcher's Scrounged Goods|r]?we39637 [a |cFF0070dd Thankful Researcher's Gift|r]?q75628&we39636 [a |cFF1eff00 Appreciative Researcher's Scrounged Goods|r]?we39636 [a |cFF1eff00 Appreciative Researcher's Gift|r]?q75627&we39635 [a |cFFffffff Researcher's Scrounged Goods|r]?we39635 [a |cFFffffff Researcher's Gift|r][no compensation] for your efforts so far.", ua = "Раннан винагороджує тих, хто допомагає його експедиції, залежно від виконаних дослідницьких цілей. Наразі твоя винагорода за докладені зусилля: $?q75630&we39638 [|cFFa335ee Назбираний Крам Зобов'язаного Дослідника|r]?we39638 [|cFFa335ee Подарунок Зобов'язаного Дослідника|r]?q75629&we39637 [|cFF0070dd Назбираний Крам Вдячного Дослідника|r]?we39637 [|cFF0070dd Подарунок Вдячного Дослідника|r]?q75628&we39636 [|cFF1eff00 Назбираний Крам Шанобливого Дослідника|r]?we39636 [|cFF1eff00 Подарунок Шанобливого Дослідника|r]?q75627&we39635 [|cFFffffff Назбираний Крам Дослідника|r]?we39635 [|cFFffffff Подарунок Дослідника|r][нічого]." },
    { en = "Carrying food supplies.", ua = "Ви несете запаси харчів." },
    { en = "Casting Aimed Shot provides you with Ranger's Finesse. After gaining $408518u stacks of Ranger's Finesse, increase your next Volley's radius and duration by $408518s1%.\n\n\n\nConsuming Ranger's Finesse reduces the remaining cooldown of Aspect of the Turtle by $s1 sec.", ua = "Творення «Прицільного пострілу» дає вам «Витонченість рейнджера». Після накопичення $408518u зарядів «Витонченості рейнджера» радіус і тривалість вашого наступного «Граду стріл» збільшуються на $408518s1%.\n\n\n\nВитрата «Витонченості рейнджера» скорочує залишок перезарядження «Аспекту черепахи» на $s1 сек." },
    { en = "You can now ride flying mounts.", ua = "Тепер ви можете осідлати летючих їздових тварин." },
    { en = "Guarantees that the next Time Rift you complete will grant you a reward.", ua = "Гарантує, що наступний Часовий розлом, який ти завершиш, принесе тобі нагороду." },
    { en = "Release the stretched Spring Vine. The further it has been stretched the farther you'll fly!", ua = "Відпусти натягнуту Пружну Лозу. Що сильніше її розтягнуто, то далі полетиш!" },
    { en = "Release a flurry of Frost magic, extinguishing nearby flames.", ua = "Вивільняє шквал магії морозу, гасячи полум'я поблизу." },
    { en = "Automatically attacks a target in melee with an equipped weapon. This ability can be toggled on or off.", ua = "Автоматично атакує ціль у ближньому бою спорядженою зброєю. Цю здібність можна вмикати й вимикати." },
    { en = "Your presence is masked in the Umbral Bazaar, The Skeins, The Burrows, and High Hollows.\n\n\n\nStill discoverable by Guards with Keen Senses.", ua = "Вашу присутність приховано в Сутінковому Базарі, Мотках, Норах і Високих Улоговинах.\n\n\n\nВартові з гострим чуттям однаково можуть вас виявити." },
    { en = "Move to the right.", ua = "Рухайся праворуч." },
    { en = "Fungal spores float thick in the air! Although unhealthy for flying mounts, the spores will slow your fall.", ua = "У повітрі витає густа хмара грибних спор! Хоч вони й шкідливі для летючих їздових тварин, спори сповільнять твоє падіння." },
    { en = "Activates your rocket belt to jump forward.  Other effects which slow the rate of falling cannot be used within $79636d after using this ability.", ua = "Активує ваш ракетний пояс для стрибка вперед. Інші ефекти, що сповільнюють падіння, не можна використовувати протягом $79636d після застосування цієї здібності." },
    { en = "Strike $?a206416[your primary target for $<firstbloodDmg> Chaos damage and ][]$199552s1 nearby enemies for $<baseDmg> Physical damage$?s320398[, and increase your chance to dodge by $193311s1% for $193311d.][. Deals reduced damage beyond $210153s1 targets.]", ua = "Вражаєте $?a206416[свою основну ціль на $<firstbloodDmg> шкоди Хаосу та ][]$199552s1 ворогів поблизу на $<baseDmg> фізичної шкоди$?s320398[, а також збільшуєте свій шанс ухилитися на $193311s1% протягом $193311d.][. Завдає зменшеної шкоди понад $210153s1 цілей.]" },
    { en = "Dunk the Amorous Rooster in water.", ua = "Занурює закоханого півня у воду." },
    { en = "Unlock the secrets within your Heart of Azeroth to use this power.", ua = "Розкрийте таємниці свого Серця Азерота, щоб скористатися цією силою." },
    { en = "Charge forward for $d, knocking enemies down for $255723d.", ua = "Мчить уперед протягом $d, збиваючи ворогів з ніг на $255723d." },
    { en = "Increases Herbalism skill by $s1 and increases Finesse by $s2. Finesse increases the chance of gathering additional materials.", ua = "Підвищує навичку Травництва на $s1 і Витонченість на $s2. Витонченість збільшує шанс зібрати додаткові матеріали." },
    { en = "Summons a totem at your feet that immediately heals $?a445035[${1+$s2}][$s2] injured allies for $1268684s1 and additional heals $?a445035[${1+$s2}][$s2] injured allies within $52042A1 yards for $1267745s1 every $1267765t1 sec for $d.", ua = "Прикликає до ваших ніг тотем, що негайно зцілює $?a445035[${1+$s2}][$s2] поранених союзників на $1268684s1, а також додатково зцілює $?a445035[${1+$s2}][$s2] поранених союзників у радіусі $52042A1 ярдів на $1267745s1 кожні $1267765t1 сек. протягом $d." },
    { en = "Battle pet experience gained increased by $s1%.", ua = "Досвід, який отримують бойові улюбленці, збільшено на $s1%." },
    { en = "Allows a leatherworker to make leather and mail armor. Requires leather scraps and hides gathered with the Skinning skill.", ua = "Дозволяє чинбарю виготовляти шкіряну та кольчужну броню. Потребує клаптів шкіри та шкур, які збирають навичкою Білування." },
    { en = "An improved Moonkin Form that grants the benefits of Celestial Alignment, $?a429536[$s6% increased Arcane damage, ][]and $s2% critical strike chance.\n\n\n\nLasts $d. You may shapeshift in and out of this improved Moonkin Form for its duration.", ua = "Покращена подоба місяцерода, що надає переваги «Небесного вирівнювання», $?a429536[збільшення арканної шкоди на $s6%, ][]а також $s2% до шансу критичного удару.\n\n\n\nТриває $d. Упродовж дії ви можете вільно перевтілюватися в цю покращену подобу місяцерода й назад." },
    { en = "Bring the Lost Hen to its chicken coop.", ua = "Віднесіть Загублену курку до її курника." },
    { en = "Astalor's artifact insidiously torments you, increasing damage taken by $1245522s1%. This effect stacks every $t1 sec, except while in rested areas.", ua = "Артефакт Асталора підступно мучить вас, збільшуючи отримувану шкоду на $1245522s1%. Цей ефект накопичується кожні $t1 сек, окрім часу перебування в зонах відпочинку." },
    { en = "While in combat, gore occasionally appears beneath you, inflicting Shadow damage after a short delay.", ua = "У бою під вами час від часу проступає кров, що після короткої затримки завдає шкоди Тінню." },
    { en = "Query the Tome as to where to go next or for more information.", ua = "Запитай у Фоліанта, куди вирушати далі, або попроси більше відомостей." },
    { en = "Teleport to the entrance to Halls of Valor.", ua = "Телепортує до входу в Зали Доблесті." },
    { en = "Allows for players to gather fish from bodies of water and fishing nodes up to a skill of 200.", ua = "Дозволяє гравцям виловлювати рибу з водойм і рибних косяків до рівня вміння 200." },
    { en = "Burrow beneath the ground, becoming unattackable, removing movement impairing effects, and increasing your movement speed by ${$s3-100}% for $d.\n\n\n\nWhen the effect ends, enemies within $409304A1 yards are knocked in the air and take $<damage> Physical damage.", ua = "Ви зариваєтеся під землю: вас неможливо атакувати, ефекти, що сповільнюють рух, знімаються, а ваша швидкість пересування збільшується на ${$s3-100}% на $d.\n\n\n\nКоли ефект завершується, ворогів у межах $409304A1 ярдів підкидає в повітря, і вони отримують $<damage> фізичної шкоди." },
    { en = "Have Myrrit wait at a location.", ua = "Нехай Міррит зачекає на вказаному місці." },
    { en = "Slice your target for ${$227518s1+$201428s1} Chaos damage. Annihilation has a $197125h% chance to refund $193840s1 Fury.", ua = "Розтинаєте вашу ціль, завдаючи ${$227518s1+$201428s1} шкоди Хаосу. «Знищення» має $197125h% шанс повернути $193840s1 люті." },
    { en = "Lightning Bolt replaced by Tempest.", ua = "«Блискавка» замінюється на «Буревій»." },
    { en = "Reveal convergence points between Draenor and Outland.", ua = "Виявляє точки дотику між Дренором та Аутлендом." },
    { en = "While outdoors, summon a Mole Machine that tunnels through the earth.", ua = "Просто неба прикликає кротову машину, що прокладає тунелі крізь землю." },
    { en = "$@spellicon457049 $@spellname457049|n|nIf you spend at least 10 seconds eating, you will become $@spellname457049 and gain $1219179s7 Stamina for $d.", ua = "$@spellicon457049 $@spellname457049|n|nЯкщо ви їстимете щонайменше 10 секунд, ви станете «$@spellname457049» й отримаєте $1219179s7 Витривалості на $d." },
    { en = "Allows a scribe to create magical writings. Requires pigments milled from herbs gathered by the Herbalism skill.", ua = "Дозволяє писарю створювати магічні написи. Потребує пігментів, змелених із трав, зібраних навичкою Травництва." },
    { en = "Allows instantaneous teleportation to nodes in the local portal network on Val.", ua = "Дозволяє миттєво телепортуватися до вузлів місцевої мережі порталів на Валі." },
    { en = "Every $t1 sec, restore 1 Vigor until all Vigor has been recovered. Gain a small boost every time Vigor is restored while gliding.", ua = "Кожні $t1 сек відновлює 1 Завзяття, доки все Завзяття не відновиться. Щоразу, як Завзяття відновлюється під час ширяння, ти отримуєш невелике прискорення." },
    { en = "Enter a Lunar Eclipse, empowering Starfire for $48518d.\n\n\n\n$?a429523[][Casting Wrath changes this to Solar Eclipse.\n\n\n\n]$@spellicon48518 $@spellname48518\n\nArcane spells deal $48518s1% additional damage and Starfire's damage is increased by $48518s3%.", ua = "Входите в Місячне затемнення, що підсилює Зоряний вогонь на $48518d.\n\n\n\n$?a429523[][Творення Гніву змінює його на Сонячне затемнення.\n\n\n\n]$@spellicon48518 $@spellname48518\n\nАрканні закляття завдають на $48518s1% більше шкоди, а шкоду Зоряного вогню збільшено на $48518s3%." },
    { en = "Teleport to the entrance of Manaforge Omega.", ua = "Телепортує до входу в Манакузню Омега." },
    { en = "Clever saptors occasionally ambush your foes during combat.", ua = "Кмітливі смолораптори час від часу нападають на ваших ворогів із засідки під час бою." },
    { en = "You champion the cause of the Kirin Tor.  All reputation gains while in Northrend dungeons will be applied to your standing with them.", ua = "Ви відстоюєте справу Кірін Тор. Весь приріст репутації в підземеллях Нортренду зараховуватиметься до вашого статусу серед них." },
    { en = "After $d, the unstable anguish will disintegrate. Timer pauses while in combat.", ua = "Через $d нестабільна мука розпадеться. У бою відлік призупиняється." },
    { en = "Delver's Journey progress gains increased by $s1%.\n\nCompanion experience gains increased by $s3%.\n\nUndercoin gains increased by $s2%.", ua = "Поступ Подорожі Глибинника збільшено на $s1%.\n\nЗдобуття досвіду супутника збільшено на $s3%.\n\nЗдобуття Підземних монет збільшено на $s2%." },
    { en = "Displace yourself from time, making it harder to be seen.", ua = "Зміщує вас у часі, тож вас важче помітити." },
    { en = "The caster expels energy with attacks and spells, inflicting $1297960s1 Arcane damage to players within $1297960a1 yds of impact locations.", ua = "Заклинач вивільняє енергію атаками й закляттями, завдаючи $1297960s1 арканної шкоди гравцям у радіусі $1297960a1 ярдів від місць влучання." },
    { en = "Cancel the current race and return to the Little Scales Daycare.", ua = "Скасовує поточні перегони й повертає до Ясел «Маленькі Лусочки»." },
    { en = "Releases thorny vines that bind and slow players, inflicting $1297710s1 Nature damage every $1297710t1 sec and reducing movement speed by $1297710s2% to players within.", ua = "Вивільняє тернисті лози, що обплутують і сповільнюють гравців, завдаючи гравцям усередині $1297710s1 шкоди від природи кожні $1297710t1 с і зменшуючи їхню швидкість руху на $1297710s2%." },
    { en = "Your blood runs cold, reducing all damage you take by $s8% for $d.$?a382292[\n\n\n\nWhile Ice Cold is active, you heal for ${$382292s1*10}% of your maximum health over the duration.][]\n\n\n\nCauses Hypothermia, preventing you from recasting Ice Cold for $41425d.", ua = "Ваша кров холоне, зменшуючи всю отримувану вами шкоду на $s8% протягом $d.$?a382292[\n\n\n\nПоки діє «Крижаний холод», ви зцілюєтеся на ${$382292s1*10}% свого максимального здоров'я протягом його дії.][]\n\n\n\nСпричиняє «Гіпотермію», яка не дозволяє повторно творити «Крижаний холод» протягом $41425d." },
    { en = "Enter a Solar Eclipse, empowering Wrath for $48517d.\n\n\n\nCasting Starfire changes this to Lunar Eclipse.\n\n\n\n$@spellicon48517 $@spellname48517\n\nNature spells deal $48517s1% additional damage and Wrath damage is increased by $48517s3%.", ua = "Ти входиш у Сонячне затемнення, що посилює Гнів протягом $48517d.\n\n\n\nПрочитання Зоряного вогню змінює це на Місячне затемнення.\n\n\n\n$@spellicon48517 $@spellname48517\n\nЗакляття природи завдають на $48517s1% більше шкоди, а шкоду Гніву збільшено на $48517s3%." },
    { en = "Launch a bolt of lava at a Dragonkiller Ballista, dealing $s1 Volcanic damage to it.", ua = "Запусти лавовий снаряд у балісту-драконобійця, завдавши їй $s1 од. Вулканічної шкоди." },
    { en = "Allows the use of Rift Slippers to quickly exit underground locations on Val.", ua = "Дозволяє використовувати Проковзувачі Розлому, щоб швидко залишати підземні локації на Валі." },
    { en = "Summons a totem at your feet for $d that heals $?s147074[two injured party or raid members][an injured party or raid member] within $52042A1 yards for $52042s1 every $5672t1 sec.\n\n\n\nIf you already know $?s157153[$@spellname157153][$@spellname5394], instead gain $392915s1 additional $Lcharge:charges; of $?s157153[$@spellname157153][$@spellname5394].", ua = "Прикликає до ваших ніг тотем на $d, що кожні $5672t1 сек. зцілює $?s147074[двох поранених членів групи чи рейду][пораненого члена групи чи рейду] в радіусі $52042A1 ярдів на $52042s1.\n\n\n\nЯкщо ви вже знаєте $?s157153[$@spellname157153][$@spellname5394], то натомість отримуєте додатково $392915s1 $Lcharge:charges; $?s157153[$@spellname157153][$@spellname5394]." },
    { en = "Allows a tailor to make basic cloth armors. Requires cloth found on humanoids.", ua = "Дозволяє кравцю виготовляти базову тканинну броню. Потребує тканини, яку знаходять у гуманоїдів." },
    { en = "Extracts the magical element(s) from good quality (Green) or better weapons or armor. The targeted item will be DESTROYED and will not be retrievable.", ua = "Видобуває магічні елементи зі зброї чи обладунків доброї (зеленої) або кращої якості. Обраний предмет буде ЗНИЩЕНО без можливості повернути." },
    { en = "You champion the cause of the Wildhammer Clan.  All reputation gains while in Cataclysm dungeons will be applied to your standing with them.", ua = "Ви відстоюєте справу клану Дикого Молота. Весь приріст репутації в підземеллях Катаклізму зараховуватиметься до вашого статусу серед них." },
    { en = "Spells and abilities have a chance to invoke Terokk.", ua = "Закляття та здібності мають шанс прикликати Терокка." },
    { en = "Toss a hat to an eager elemental to recruit them!", ua = "Кинь капелюха завзятому елементалю, щоб завербувати його!" },
    { en = "Increases your chance to dodge by 1%.", ua = "Підвищує твій шанс ухилитися на 1%." },
    { en = "Paladins can wear cloth, leather, mail and plate armor and use shields.\n\n\n\nStarting at level $s1, you receive a 5% increase to your $?c1[Intellect]?c2[Stamina]?c3[Strength][primary stat] for wearing plate.", ua = "Паладини можуть носити тканинну, шкіряну, кольчужну та латну броню й користуватися щитами.\n\n\n\nПочинаючи з рівня $s1, ти дістаєш +5% до $?c1[Інтелекту]?c2[Витривалості]?c3[Сили][основної характеристики] за носіння лат." },
    { en = "Paladins can use the following weapons:\n\n\n\nAxes\n\nMaces\n\nPolearms\n\nSwords", ua = "Паладини можуть користуватися такою зброєю:\n\n\n\nСокири\n\nБулави\n\nДревкова зброя\n\nМечі" },
    { en = "Increases health gained when resurrected by $s1% and increases movement speed while dead by $s2%. Does not function in combat or while in a Battleground or Arena.", ua = "Підвищує здоров'я, отримане при воскресінні, на $s1% і підвищує швидкість пересування в мертвому стані на $s2%. Не діє в бою, а також на полі бою чи арені." },
    { en = "In-game mail sent between guild members now arrives instantly.", ua = "Внутрішньоігрова пошта між членами гільдії тепер надходить миттєво." },
    { en = "You become the ultimate crusader of light, for $d. Auto-attack damage is increased by $s3%, Judgment and Crusader Strike heal up to $s6 injured allies within $216371A yds for $s5% of the damage done, split evenly among them.\n\n\n\nThis spell is replaced with Crusader Strike while active.\n\n\n\n$@spellicon35395$@spellname35395:\n\n$@spelldesc35395", ua = "Ти стаєш довершеним хрестоносцем світла на $d. Шкода автоатак підвищується на $s3%, а Присуд і Удар хрестоносця зцілюють до $s6 поранених союзників у межах $216371A м на $s5% завданої шкоди, порівну між ними.\n\n\n\nПоки триває, це закляття замінюється Ударом хрестоносця.\n\n\n\n$@spellicon35395$@spellname35395:\n\n$@spelldesc35395" },
    { en = "Increases mounted movement speed in the Broken Isles by $s1%.", ua = "Підвищує швидкість пересування верхи на Зламаних Островах на $s1%." },
    { en = "Summon a Forge of Light, enabling Blacksmithing. \n\n\n\nBlacksmithing skill increased by $255650s1.", ua = "Прикликає Горн Світла, що дає змогу ковалювати. \n\n\n\nНавичка ковальства підвищується на $255650s1." },
    { en = "Dig in your cleats at your current handhold to become immune to all climbing hazards for $d.\n\n$?a362140[\n\n|CFFFF2020Unlock this ability in the Expedition Supply Kit at the Dragonscale Basecamp!|R][]", ua = "Угрузни шипами в поточний уступ, щоб стати невразливим до всіх небезпек сходження на $d.\n\n$?a362140[\n\n|CFFFF2020Відімкни цю здібність у Наборі припасів експедиції в Базовому Таборі Драконячої Луски!|R][]" },
    { en = "Ask a friendly earth elemental to activate a nearby Helping Hand to create a temporary handhold.\n\n$?a362142[\n\n|CFFFF2020Unlock this ability in the Expedition Supply Kit at the Dragonscale Basecamp!|R][]", ua = "Попроси дружнього елементаля землі активувати поблизу Помічну руку, щоб створити тимчасовий уступ.\n\n$?a362142[\n\n|CFFFF2020Відімкни цю здібність у Наборі припасів експедиції в Базовому Таборі Драконячої Луски!|R][]" },
    { en = "Help a nearby climber, restoring their health and Grip.\n\n$?a362143[\n\n|CFFFF2020Unlock this ability in the Expedition Supply Kit at the Dragonscale Basecamp!|R][]", ua = "Допоможи верхолазові поблизу, відновивши йому здоров'я і Хват.\n\n$?a362143[\n\n|CFFFF2020Відімкни цю здібність у Наборі припасів експедиції в Базовому Таборі Драконячої Луски!|R][]" },
    { en = "|CFFFFFFFFPassive|R\n\nAutomatically grapple to the nearest handhold and restore 25 Grip when you run out of Grip, once every 3 minutes.\n\n$?a362146[\n\n|CFFFF2020Unlock this ability in the Expedition Supply Kit at the Dragonscale Basecamp!|R][]", ua = "|CFFFFFFFFПасивно|R\n\nАвтоматично чіпляєшся до найближчого уступу й відновлюєш 25 Хвату, коли Хват вичерпується, раз на 3 хвилини.\n\n$?a362146[\n\n|CFFFF2020Відімкни цю здібність у Наборі припасів експедиції в Базовому Таборі Драконячої Луски!|R][]" },
    { en = "Teleport to the entrance to Karazhan.", ua = "Телепортує до входу в Каражан." },
    { en = "Calibrate the magical telescope to find a nearby source of power.", ua = "Налаштуй магічний телескоп, щоб знайти поблизу джерело сили." },
    { en = "Calibrate the magical telescope to find a nearby ally.", ua = "Налаштуй магічний телескоп, щоб знайти поблизу союзника." },
    { en = "Calibrate the magical telescope to find a nearby danger.", ua = "Налаштуй магічний телескоп, щоб знайти поблизу небезпеку." },
    { en = "Throw a toy duck in the water.", ua = "Кинь у воду іграшкову качку." },
    { en = "At the end of this questline, you will acquire a Bottled Essence, which can be turned into a Spark of Ingenuity.", ua = "Наприкінці цієї гілки завдань ти дістанеш Сутність у пляшці, яку можна обернути на Іскру Винахідливості." },
    { en = "Completing this entire questline will unlock access to cataloging activities within the Dragon Isles.", ua = "Проходження всієї цієї гілки завдань відкриє доступ до каталогізації на Драконових Островах." },
    { en = "Teleport to the entrance to Court of Stars.", ua = "Телепортує до входу в Двір Зірок." },
    { en = "Teleport to the entrance to Black Rook Hold.", ua = "Телепортує до входу у Твердиню Чорного Грака." },
    { en = "Teleport to the entrance to Darkheart Thicket.", ua = "Телепортує до входу в Хащі Темносердя." },
    { en = "Reactive sporbits infest the delve. They will swell up and explode if they detect any nearby adventurers.", ua = "Глибину заполонили реактивні спорбіти. Вони роздуваються й вибухають, щойно вчують поблизу шукачів пригод." },
    { en = "Teleport to the entrance to Siege of Boralus.", ua = "Телепортує до входу в Облогу Боралуса." },
    { en = "Get a job from Nanny Talullah, or cancel the one you're currently on.", ua = "Візьми роботу в няньки Талулли або скасуй ту, яку виконуєш зараз." },
    { en = "Remove your climbing gear.", ua = "Зніми спорядження для сходження." },
    { en = "Summons and dismisses the G-99 Breakneck.", ua = "Прикликає і відкликає Ґ-99 «Шибайголову»." },
    { en = "Leave the G-99 Breakneck.", ua = "Покинути Ґ-99 «Шибайголову»." },
    { en = "Followed by lingering shadows that will occasionally chase you. Look at the shadows to stop them in their tracks!", ua = "За тобою тягнуться примарні тіні, що час від часу кидаються навздогін. Подивися на тіні, щоб спинити їх!" },
    { en = "Destroys supplies and inflicts additional $s1 Fire damage to enemies within $A1 yards of the impact.\n\n\n\nThrow it quickly before it explodes!", ua = "Знищує припаси й завдає додатково $s1 вогнем ворогам у межах $A1 м від місця влучання.\n\n\n\nКидай швидше, поки не вибухнуло!" },
    { en = "Goblins have caused several problems in the area. Who knows what you might find?", ua = "Ґобліни наробили в цих краях чимало клопоту. Хтозна, що ти тут знайдеш?" },
    { en = "Grants the ability:\n\n\n\n$@spelltooltip1236783", ua = "Дарує здібність:\n\n\n\n$@spelltooltip1236783" },
    { en = "Spread the quicksilver according to Talandra's pattern. Take care -- the reagent is toxic.", ua = "Розсип ртуть за візерунком Таландри. Стережися — реагент отруйний." },
    { en = "Cheer for Ani so she has the courage she needs.", ua = "Підбадьор Ані, щоб їй стало відваги." },
    { en = "Really put your back into it this time.", ua = "Цього разу візьмися як слід." },
    { en = "Become invisible for $d by slipping into the space between shadows. While invisible, attacking will catch enemies off guard and inflict additional damage.", ua = "Стань невидимим на $d, прослизнувши в простір між тінями. Поки ти невидимий, атака заскочить ворогів зненацька й завдасть додаткової шкоди." },
    { en = "Call forth a mighty Domanaar from the depths of the Void.\n\nThe last bits of the incantation are covered in something red and sticky, but what could go wrong?", ua = "Виклич могутнього доманара з глибин Порожнечі.\n\nОстанні рядки закляття заліплені чимось червоним і липким, але що може піти не так?" },
    { en = "Use the Singularity Portal for fast travel throughout the Sanctum.", ua = "Скористайся Порталом Сингулярності для швидкої подорожі Святилищем." },
}

